MultiLanguageQuestData['tw'][1660] = {title = "暂无内容", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1665] = {title = "巴特莱比的酒杯", objective = "把巴特莱比的酒杯交给伯加德。", description = "好吧，这是我的酒杯。等等！让我先把酒喝光……给你。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1666] = {title = "治安官哈迦德", objective = "和治安官哈迦德谈一谈。", description = "你学会了一些招数，但你应该有一件像样的武器。我敢打赌，只要你和治安官哈迦德先生谈谈的话，他一定会帮助你的。\n\n哈迦德先生就住在艾尔文森林东谷伐木场的一个庄园里。他已经退休了，不过他在工作期间曾收集了不少装备。\n\n告诉他是我派你去的，如果你够走运的话，他会提供给你一件武器的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1667] = {title = "蛀牙杰克", objective = "从蛀牙杰克的营地里取回治安官哈迦德的徽章，把它交给治安官哈迦德。", description = "是伯加德派你来的吗？是的，我这里的确有一些剩余的武器，不过首先有一项任务交给你……\n\n不久以前，一个被称作蛀牙杰克的迪菲亚混蛋捉弄了我。天很黑，他穿着一件暴风城卫兵的衣服，我还以为他是治安官杜汉呢。他说他要我那个旧的暴风城治安官徽章，我就把徽章给了他……然后他便大笑起来，在我反应过来之前就跑掉了！\n\n帮我取回我的勋章！蛀牙杰克应该是把徽章放在南边的迪菲亚盗贼营地里了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "哈迦德的戰斧哈迦德的匕首哈迦德的戰錘哈迦德的劍"}
MultiLanguageQuestData['tw'][1678] = {title = "维吉雷克", objective = "将维吉雷克的徽记交给铁炉堡的穆伦·雷矛。", description = "如果你想提高自己在战士中的地位，那么你就必须变得更加坚韧一些。我可以教你一些新的技能，不过在此之前，你要向我证明你能够对付真正的敌人。\n\n维吉雷克是这一地区最强大的巨魔，也是你即将挑战的对手。他住在霜鬃要塞南方山脚下的棚屋里。\n\n把维吉雷克的徽记交给我，让我看看你的勇气和力量。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1679] = {title = "穆伦·雷矛", objective = "和穆伦·雷矛谈一谈。你好，战士！你有很大的潜力，不过你还要学习更多的技巧才行，穆伦·雷矛是最合适向你传授这些技巧的矮人。\n\n你可以在铁炉堡军事区的军事大厅里找到穆伦。当你准备要成为一名真正的勇士的时候，就去和他谈谈吧。完成任務後，你將獲得：\n\n", description = "你好，战士！你有很大的潜力，不过你还要学习更多的技巧才行，穆伦·雷矛是最合适向你传授这些技巧的矮人。\n\n你可以在铁炉堡军事区的军事大厅里找到穆伦。当你准备要成为一名真正的勇士的时候，就去和他谈谈吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1681] = {title = "鐵環營地", objective = "把陰影礦石交給鐵爐堡的托姆斯·深爐。", description = "我的導師，斯塔基·鐵環，原本在丹莫洛東部的盔枕湖南邊有一處獨家小院。他在那裡向別人傳授鐵匠的技能，他絕對是最棒的。\n\n不過，有一天，他的一個學生帶給他一塊奇特的礦石。鐵環把它叫做陰影礦石，他很希望能用它做點什麼，可是，之後不久...一夥黑鐵矮人襲擊了他的小院。他們殺死了所有的人!\n\n到鐵環的小院去，<name>，為我的導師復仇，然後把那塊陰影礦石給我帶回來。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1682] = {title = "灰铁武器", objective = nil, description = nil, progress = nil, completion = nil, rewards = "陰影戰斧陰影匕首陰影釘錘陰影長劍"}
MultiLanguageQuestData['tw'][1683] = {title = "沃魯斯·邪蹄", objective = "將沃魯斯的角交給達納蘇斯的艾蘭娜瑞。", description = "在我向你傳授知識之前，你必須顯示出決心。\n\n有一個名叫沃魯斯·邪蹄的薩特找到了我們的一口月井，就在班奈希爾獸穴的東南方。他正在井中戲耍，用他邪惡的身軀污染純潔的井水。\n\n到月井那裡去找到沃魯斯，把他幹掉。把他的角給我帶回來，然後我就會向你傳授更高級的戰士技能。\n\n去月井的路不太好找，但是如果你細心一點的話，應該不會迷路的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1685] = {title = "加科因的召喚", objective = "去暴風城的法師區向『黑暗縛靈師』加金報到。難道不是每次都這樣嗎?!我找了你一整天都不見你的蹤影，等我已經不指望能找到你的時候你卻來了。\n\n你已經浪費我太多時間了，所以現在咱們就少廢話了。加科因大師要召見你進行更多訓練，我覺得你最好還是儘快找到他。\n\n他在已宰的羔羊旅店的地窖裡。順便說一句，他的藏身地點你可得保密，不要讓別人知道了。完成任務後，你將獲得：\n\n", description = "難道不是每次都這樣嗎?!我找了你一整天都不見你的蹤影，等我已經不指望能找到你的時候你卻來了。\n\n你已經浪費我太多時間了，所以現在咱們就少廢話了。加科因大師要召見你進行更多訓練，我覺得你最好還是儘快找到他。\n\n他在已宰的羔羊旅店的地窖裡。順便說一句，他的藏身地點你可得保密，不要讓別人知道了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1686] = {title = "艾鲁拉的阴影", objective = "将艾鲁拉的徽章和8块月神矿石交给达纳苏斯的艾兰娜瑞。", description = "你已经学会很多东西了，<name>。现在我们将为你制作一件精良的武器，一件属于战士的武器。\n\n要完成这一使命，你必须去一趟黑海岸。\n\n很久以前，有一条船在奥伯丁灯塔附近触礁，许多装有月神矿石的箱子沉入了海底。\n\n首先，你必须打败守护那些矿石的亡魂——艾鲁拉的阴影。作为一船之长，她对自己施加了诅咒，变成了一个在海洋深处巡游的亡魂，时时刻刻保护着船上的货物。打败她，摘下她的徽章，然后收集丢失的月神矿石。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1687] = {title = "幽靈燈塔", objective = "帶著你看護的孤兒去西部荒野海岸邊的燈塔。", description = "有時候，我們孤兒院的院長會在晚上給我們講一些鬼故事。真是太恐怖了!其中有一個故事說在西部荒野的燈塔那裡有一個遊蕩的鬼魂。他們說那是一個海賊船長，他的船被別的海賊給搶了。這真是太刺激了!\n\n你能不能把我帶到西部荒野的燈塔那裡去?我想要看看那個鬼魂船長是不是真的在那裡!我保證會一直跟著你，而且絕對不會跑開或者惹些什麼麻煩!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1689] = {title = "誓縛", objective = "召喚並制服一個虛無行者，然後將血石頸飾還給暴風城的『黑暗縛靈師』加金。", description = "你找回了我的頸飾並擊敗了蘇倫娜，這證明你有著至少與她勢均力敵的力量。\n\n雖然這麼說，但我還是認為你需要進一步的訓練。你現在已經能夠控制魔法的流動了，這很好，但如果你要想要成為一位優秀的術士，這還遠遠不夠。\n\n我會教你如何控制虛無行者，不過在我教你之前，你得先在召喚法陣上召喚它出來並制服它，無論你用什麼武器都好─劍或者魔法─隨你自己樂意吧。在下面的召喚法陣上使用這個頸飾裡的魔法，然後擊敗從虛無中出現的惡魔。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n召喚虛無行者"}
MultiLanguageQuestData['tw'][1690] = {title = "制裁廢土遊民", objective = "去加基森的東面殺掉10個廢土竊賊和10個廢土強盜，然後向首席工程師膨嘯覆命。", description = "你!是你出馬幫助加基森水業公司的時候了!\n\n那些廢土遊牧民幾乎佔據了塔納利斯沙漠上所有的水井!如果得不到這些水井的控制權，那我們的水源供應很快就會出現問題。如果你想幫助我們的話，就去解決那些該死的遊牧民吧!\n\n從這裡往東走，去幹掉10個廢土竊賊和10個廢土強盜，然後立即向我報告。你一定要為我們這些人...呃...哥布林們伸張正義啊，不管怎麼樣，快點行動吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][1691] = {title = "制裁更多廢土遊民", objective = "殺死10個廢土暗法師、8個廢土遊蕩者和6個廢土刺客，然後向加基森的首席工程師膨嘯報告。", description = "現在我們需要你去對付那些更強大的廢土遊牧民。到現在為止你都表現得相當出色，但是如果我們想要奪回水井的話，那麼就必須要幹掉更多的遊牧民!\n\n這次，我要你去殺死他們的遊蕩者和刺客，還有暗法師。你可以在這裡的東南面找到這些傢伙。\n\n說實話，他們都很棘手。但是請你一定要幫忙，我們要取回屬於自己的東西!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][1698] = {title = "犹鲁斯·麦酒", objective = "与犹鲁斯·麦酒谈一谈。犹鲁斯·麦酒向联盟所有强大的战士发出了挑战。他在赤脊山的湖畔镇旅店等候着你们，并承诺会给所有通过试炼的战士提供丰厚的报酬。完成任務後，你將獲得：\n\n", description = "犹鲁斯·麦酒向联盟所有强大的战士发出了挑战。他在赤脊山的湖畔镇旅店等候着你们，并承诺会给所有通过试炼的战士提供丰厚的报酬。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1699] = {title = "往返瑞斯班洞穴", objective = "进入瑞斯班洞穴，然后在规定的时间内回到犹鲁斯·麦酒那里。\n\n在整个过程中你都不能死掉或者释放灵魂，否则任务就宣告失败。", description = "我把我的挑战项目称作“往返瑞斯班洞穴”。要想通过这次挑战，你要做的就是进入瑞斯班洞穴，然后回到这里——非常简单的任务！当然，路上也许会有一些小波折……\n\n你必须在一个小时之内返回这里，有成堆的赤脊山豺狼人挡在路上，所以你得花些时间打发它们。\n\n在出发之前，请喝下以我的家族名字命名的美酒：热麦酒！\n\n那么，你觉得如何？瑞斯班洞穴就在湖畔镇北面的山脚下，你准备好了吗？完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1700] = {title = "格瑞曼德·艾尔默", objective = "把弗伦的笔记交给格瑞曼德·艾尔默。", description = "帮你铸造铠甲的时候，我记下了一些心得体会。我要找个人帮我把这份笔记交给格瑞曼德·艾尔默，他在矮人区的武器店里。把笔记交给他的时候要显得低调一点，他对自己的技术有近乎狂妄的自信，根本不愿从我这里学点什么……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][1701] = {title = "淬火鎖甲", objective = "收集必需的材料，將它們交給暴風城的弗倫·長鬚。", description = "我已經給了你一面精緻的盾牌，不過我們的合作決不會就此結束。我知道如何鑄造異常堅固的鎧甲，但是鑄造起來並不容易，我需要一些稀有的材料，只要你願意跑跑腿，我保證會為你打造一件。\n\n你覺得怎麼樣，<name>?如果你願意接受挑戰的話，我會給你一份列表，上面記載著我需要的材料和到可以找到這些材料的地點。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1702] = {title = "铸盾师", objective = "将这桶热酒交给弗伦·长须。", description = "<name>，当你完成挑战时，我就看出你是个厉害的家伙啦。当然，我说话算话，我会按照承诺给你奖励……\n\n不过，这件礼物在暴风城。\n\n去跟我的朋友弗伦·长须谈谈吧，他在暴风城的矮人区里。我敢说他是你见过的最棒的铸盾师，他欠我一份人情。\n\n给，把这桶热麦酒交给弗伦，让他为你制造一副盾牌。那品质绝对让你满意！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n弗倫的禮物"}
MultiLanguageQuestData['tw'][1705] = {title = "燃烧之血", objective = "把20瓶燃烧之血和1块燃烧之石交给暴风城的格瑞曼德·艾尔默。", description = "我很不愿意相信弗伦可能发现了什么新奇的东西。不过，为了确认这一点，我要把他的技术应用到这副新的铠甲上。如果你能帮我找来这些原料，<name>，你就能拥有这样的一件铠甲。\n\n要制造这件铠甲的话，我需要一些燃烧之血和一块燃烧之石。\n\n我知道唯一能找到它们的地方是暮色森林，那些在罗兰德末日矿洞里出没的夜行狼人拥有燃烧之血，而他们的首领加特斯比尔则拥有燃烧之石。\n\n愿好运永远与你同在, <name>.完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1706] = {title = "格瑞曼德的铠甲", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n淬火頭巾"}
MultiLanguageQuestData['tw'][1707] = {title = "收集水袋", objective = "收集5個廢土水袋，把它們交給加基森的魯葛蘭克。", description = "你好啊<name> - 我叫魯葛蘭克，如果你想要找些事情做，我們這裡現在就有一件重要的工作給你!唷呼!\n\n沒有什麼能比幫我帶回一些廢土水袋來更能令我這個老傢伙開心的了。那可都是我們的水─就是那些流浪者把它們偷走了!你每給我帶回五個廢土水袋來，加基森水業公司就會獎勵給你一個正式的醫療包裹。更重要的是，你正在幫助加基森自助!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n加基森水業公司護理袋"}
MultiLanguageQuestData['tw'][1708] = {title = "铁珊瑚", objective = "收集20块灼热珊瑚，把它们交给铁炉堡的科罗莫特·钢尺。", description = "我希望在我自己的铠甲上应用弗伦·长须的新技术。因为你帮了弗伦的忙，而他又帮了我的忙，所以当我做好铠甲以后，你可以第一个试用它！\n\n要打造铠甲的话，我就得弄到一种特别的珊瑚，灼热珊瑚。它只生长在一个地方——湿地的米奈希尔港南边的海岸地带。\n\n只要你给我带来我足够多的灼热珊瑚，我就可以马上开始铸造铠甲啦。快点，<name>，我恨不得现在就开始工作！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1709] = {title = "科罗莫特的成果", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n淬火護手"}
MultiLanguageQuestData['tw'][1710] = {title = "晒焦的蛋壳", objective = "把20个晒焦的蛋壳交给达纳苏斯的玛希尔。", description = "我很想测试一下弗伦·长须的最新发现，希望能将它用于我正在研究的新式铠甲上，我认为弗伦的技术一定能产生最好的结果。\n\n你愿意帮助我吗？如果你愿意帮我收集制造铠甲所需的原料，我就会帮你也做一件。\n\n我需要晒焦的巨翼双足飞龙蛋壳，这种飞龙大都栖息在千针石林的风巢中。在它们的巢下可以找到我要的蛋壳，当你收集了足够数量的蛋壳之后就赶快回来找我。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1712] = {title = "塞克隆尼亚", objective = "把巴斯拉的羊皮纸上列出的东西交给奥特兰克的捕风者巴斯拉。", description = "我几十年来都在关注着这个地方。我关注着，希望有一天能看到强大的塞克隆尼亚被人击败。但迄今为止，我还没有找到一个能打败风领主的勇士。\n\n也许你就是那个勇士。\n\n证明给我看吧，给我找来召唤塞克隆尼亚所需的东西，这样你就能证明自己是一个伟大的勇士。也许你能打败他并夺得他的旋风之心。\n\n这样的话，我将把这颗心的力量注入一把武器里，供你在今后的冒险旅程中使用。\n\n这张羊皮纸上写着我需要的东西。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1713] = {title = "召唤", objective = "将旋风之心带给捕风者巴斯拉。", description = "我已经准备好仪式要召唤塞克隆尼亚了。当他被召唤出来时，你必须打败他，然后得到他的旋风之心。我将用它来把塞克隆尼亚的力量注入到一件武器中。\n\n<name>，你准备好面对风领主了吗？完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1718] = {title = "島民", objective = "和克蘭諾克·馬克雷德談話。作為一名戰士，你的名聲越傳越響，<name>。現在是時候讓你和其他戰士比試一下，看看你真正的實力了。\n\n在貧瘠之地的海岸附近有一座名叫勇士島的小島，就在棘齒城的南部，強大的戰士們時常在那裡聚會。\n\n他們在那裡相聚，然後互相切磋。\n\n去和勇士島的首席戰士克蘭諾克·馬克雷德談談吧。如果他認為你夠格的話，就會指引你在勇士的道路上更進一步的。完成任務後，你將獲得：\n\n", description = "作為一名戰士，你的名聲越傳越響，<name>。現在是時候讓你和其他戰士比試一下，看看你真正的實力了。\n\n在貧瘠之地的海岸附近有一座名叫勇士島的小島，就在棘齒城的南部，強大的戰士們時常在那裡聚會。\n\n他們在那裡相聚，然後互相切磋。\n\n去和勇士島的首席戰士克蘭諾克·馬克雷德談談吧。如果他認為你夠格的話，就會指引你在勇士的道路上更進一步的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1719] = {title = "格斗考验", objective = "杀掉比格维尔，然后向勇士岛的克兰诺克·马克雷德回复。", description = "如果你想从我这儿学到什么，你必须首先通过格斗考验。对于我们勇士岛上的自认为勇猛而又跃跃欲试的战士们来说，这是他们必须通过的挑战，如果你能通过这个考验，那么你就证明了自己的价值。\n\n要开始接受考验的话，就走到那边人群中的斗阵中央。图维基·弗拉海德会知道你已经准备好了，然后他就会派出挑战者来对你进行考验。\n\n在战胜了所有挑战者之后，他会叫出比格维尔。杀了比格维尔，在限定的时间内回到我这里来复命。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1782] = {title = "弗伦的铠甲", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n淬火鍊衫"}
MultiLanguageQuestData['tw'][1791] = {title = "捕风者", objective = "和捕风者巴斯拉谈一谈。现在既然你已经学会了狂暴姿态，就应该去弄一把称手的武器。\n\n去和捕风者巴斯拉谈谈吧，他是住在奥特兰克山脉和西瘟疫之地之间一个巨魔隐士。他是制造武器的行家，也是一个强大的萨满祭司。\n\n去找到巴斯拉，沿着塔伦米尔东侧的河流一直向北——巴斯拉的营地就在这条河东岸的废墟旁。完成任務後，你將獲得：\n\n", description = "现在既然你已经学会了狂暴姿态，就应该去弄一把称手的武器。\n\n去和捕风者巴斯拉谈谈吧，他是住在奥特兰克山脉和西瘟疫之地之间一个巨魔隐士。他是制造武器的行家，也是一个强大的萨满祭司。\n\n去找到巴斯拉，沿着塔伦米尔东侧的河流一直向北——巴斯拉的营地就在这条河东岸的废墟旁。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1792] = {title = "旋风武器", objective = "完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "旋風之斧旋風之錘旋風之劍"}
MultiLanguageQuestData['tw'][1799] = {title = "寶珠碎片", objective = "在棘齒城外的塔里與梅納拉的侍僧們談話，選擇自己修行的方式。\n\n然後給塵泥沼澤的塔貝薩帶去一顆煉獄火寶珠。", description = "很好，那麼我們開始吧。\n\n首先，你必須到裡面去跟我的侍僧們談談，然後決定自己要走哪條路─他們會給你更詳細的解釋。\n\n然後，你必須到淒涼之地的瑪諾洛克集會所去，從那裡的某個術士身上找到一顆煉獄火寶珠。你要淨化這顆寶珠，隱居在塵泥沼澤南部的一個名叫塔貝薩的法師會幫你完成淨化。她肯定會幫助你，因為我們曾有共同的過去。\n\n我再強調一次，這些任務沒完成之前，你就別回來見我。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1818] = {title = "迪林格尔", objective = "和布瑞尔的亡灵卫兵迪林格尔谈一谈。亡灵卫兵迪林格尔告诉我有一份工作可以交给像你这样的<class>。如果你想要为黑暗女王效力的话，那就马上去迪林格尔那边报到吧。\n\n亡灵卫兵迪林格尔在布瑞尔最西边执勤，就在墓地的旁边。完成任務後，你將獲得：\n\n", description = "亡灵卫兵迪林格尔告诉我有一份工作可以交给像你这样的<class>。如果你想要为黑暗女王效力的话，那就马上去迪林格尔那边报到吧。\n\n亡灵卫兵迪林格尔在布瑞尔最西边执勤，就在墓地的旁边。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1819] = {title = "切割者奥拉格", objective = "杀死切割者奥拉格，然后和亡灵卫兵迪林格尔谈一谈。", description = "当亡灵天灾席卷提瑞斯法林地的时候，我们曾经抓住他们中的一员进行研究。他具有自己的意志，并自称为切割者奥拉格。但是，虽然他的意志是自由的，但他仍然只是一个被巫妖王掌控和奴役着的傀儡。\n\n我们希望能够让他脱离巫妖王的控制，但是失败了。现在，我看是时候让他彻底地“解脱”了。\n\n让他解脱，杀了他。\n\n激活北部陵墓那里的颅骨石机关，解除奥拉格身上的魔法封印。\n\n然后……做好准备，<name>。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1823] = {title = "和鲁迦交谈", objective = "和鲁迦·暴怒图腾谈一谈。作为一名战士，你已经具备了相当的素质，而且名望也日渐显赫。也许你已经准备好要接受鲁迦·暴怒图腾的试炼了？如果是这样的话，就去贫瘠之地的陶拉祖营地找鲁迦吧。\n\n他一直以来都在那里等待英勇的战士响应他的召唤。完成任務後，你將獲得：\n\n", description = "作为一名战士，你已经具备了相当的素质，而且名望也日渐显赫。也许你已经准备好要接受鲁迦·暴怒图腾的试炼了？如果是这样的话，就去贫瘠之地的陶拉祖营地找鲁迦吧。\n\n他一直以来都在那里等待英勇的战士响应他的召唤。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1824] = {title = "巨人旷野的试炼", objective = "收集5根颤抖的触角，把它们带给贫瘠之地陶拉祖营地的鲁迦。", description = "要通过试炼，你必须一直向南到巨人旷野去，在那里有一大群叫做异种蝎的昆虫生物。我以前从未在贫瘠之地看到过这种生物，也不知道它们的到来究竟预兆着什么。\n\n把它们的触角交给我，<name>，要刚刚割下来、还再抽搐的那种。不要浪费时间，因为一旦你把触角割下来，它们很快就会彻底失去活力。在规定的时间内把触角带给我，这样你就通过了考验。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n魯迦壁壘"}
MultiLanguageQuestData['tw'][1838] = {title = "野蠻護甲", objective = "為索恩格瑞姆收集15根煙霧鐵錠、10份藍銅粉、10塊鐵錠和1瓶燃素。", description = "我聽說了關於你的英勇事蹟，所以希望能為你製作一套護甲，這能夠幫助你去為部落作出更多更偉大的貢獻。\n\n但是製作這樣一件護甲需要你的幫助，<name>，如果你能幫助我，那你也就幫助了部落裡所有的鐵匠。\n\n拿著這個卷軸，這是我經過無數不眠之夜，強睜著我半瞎的眼睛寫下的，上面記載著製作護甲所需要的材料。把卷軸上所列出的材料幫我找來，我會為你製作一套護甲。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1878] = {title = "收集水袋", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n加基森水業公司護理袋"}
MultiLanguageQuestData['tw'][1883] = {title = "安蘇瓦", objective = "和安蘇瓦談話。森金村的部族法師安蘇瓦發現杜洛塔的魔法流出現了波動，為此他向我尋求幫助。去和安蘇瓦談談，盡你所能去幫助他。\n\n快去吧，到時一定會有更多的秘密展示在你的面前。完成任務後，你將獲得：\n\n", description = "森金村的部族法師安蘇瓦發現杜洛塔的魔法流出現了波動，為此他向我尋求幫助。去和安蘇瓦談談，盡你所能去幫助他。\n\n快去吧，到時一定會有更多的秘密展示在你的面前。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1918] = {title = "被污染的水元素", objective = "將被污染的水球帶去梣谷的碎木崗哨交給馬斯托克‧維爾西斯。", description = "被毀滅的水元素留下了一顆水球，裡面內容令你感到極端的厭惡，仿佛污染密斯特拉湖的所有物質都包含在這顆水球中一樣。\n\n你不清楚誰會對這個感興趣，不過碎木崗哨的馬斯托克‧維爾西斯也許對此有所瞭解。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][1919] = {title = "向詹妮亞報告", objective = "和暴風城的詹妮亞·坎農談談。你的能力正在不斷地增強，年輕的<name>。你準備好要接受真正的挑戰了嗎?你願意加入我們正在進行的這場秘密戰爭之中嗎?\n\n如果你願意的話，就去和詹妮亞·坎農談談吧，她在暴風城法師區的巫師聖所裡。她有一項任務要交給你，這將幫你打開通往那個秘密世界的第一扇窗。完成任務後，你將獲得：\n\n", description = "你的能力正在不斷地增強，年輕的<name>。你準備好要接受真正的挑戰了嗎?你願意加入我們正在進行的這場秘密戰爭之中嗎?\n\n如果你願意的話，就去和詹妮亞·坎農談談吧，她在暴風城法師區的巫師聖所裡。她有一項任務要交給你，這將幫你打開通往那個秘密世界的第一扇窗。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1920] = {title = "調查藍色隱士", objective = "從詹妮亞·坎農身後拿取一根顯形卷軸以及一盒封靈箱。將3個裝滿的封靈箱交給巫師聖所裡的詹妮亞·坎農。", description = "有報告指出，法師區的藍色隱士旅店裡出現了異常的魔法波動。一些隱形的奇怪生物徘徊在旅店裡，我擔心那裡已經有了一道魔法裂隙。\n\n我希望你去調查一下旅店，捕獲那些生物。用旅店中的顯形卷軸讓它們現出原形，然後用封靈箱抓住它們。當你抓到足夠數量的隱形生物之後，就帶著裝滿的封靈箱，空的封靈箱和顯形卷軸回到我這裡來。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1921] = {title = "收集原料", objective = "把10匹亞麻布和6顆充能裂隙寶石交給暴風城的威恩·拉爾森。", description = "你幫了你的法師同行們很多忙，現在是為你製作巫師長袍的時候了。威恩·拉爾森可以幫你這個忙，不過你必須把必需的原料交給她。\n\n制袍用的亞麻布很容易找到，不過你還必須得到充能裂隙寶石，唯一出產這些寶石的地方是在洛克莫丹的銀泉礦坑，它們大多被密封在矮人礦工協會的木箱裡。\n\n收集好亞麻布和寶石之後，把它們交給法師區拉爾森服裝店裡的威恩·拉爾森。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1939] = {title = "高階巫士安多瑪斯", objective = "和高階巫士安多瑪斯談話。高階巫士安多瑪斯希望和你談談，<name>。他就在暴風城巫士區的高塔頂端。\n\n能去和他會面可是非常難得的機會，因為安多瑪斯是少數幾個沒有被困在達拉然的超強的大巫士之一，他找你也一定是有非常重大的事情。完成任務後，你將獲得：\n\n", description = "高階巫士安多瑪斯希望和你談談，<name>。他就在暴風城巫士區的高塔頂端。\n\n能去和他會面可是非常難得的機會，因為安多瑪斯是少數幾個沒有被困在達拉然的超強的大巫士之一，他找你也一定是有非常重大的事情。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1944] = {title = "薩維亞之水", objective = "將克薩維亞水樣交給奧格瑪的迪諾。", description = "傳說中的克薩維亞城位於梣谷的東部，據說在那裡可以找到所有智者都渴望獲得的古代知識，而克薩維亞之水也具有超強的魔法力量。\n\n我需要一些克薩維亞之水─要從水源直接取得的那種。\n\n拿著這只瓶子，去尋找傳說中的克薩維亞城吧。從那裡最高的瀑布底部收集水樣，然後把它交給我。在那裡你要步步小心，薩特佔領了整個遺跡，它們一定不會喜歡讓多事的法師侵入它們的領地。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1945] = {title = "歡笑的姐妹", objective = "給十字路口的基爾哈拉帶去12縷歡笑姐妹的頭髮。", description = "我已經把為你製作新袍子的事情安排妥當了，就等你來提供一些材料...\n\n我需要一些頭髮來製作你的長袍，你應該可以在梣谷的林精身上弄到符合條件的頭髮，那些林精們都聚集在林中樹居那裡。\n\n當你找到足夠的材料之後，就把它們交給貧瘠之地十字路口的基爾哈拉，他是一個食人妖裁縫。他正等著為你製作最新款的長袍。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1947] = {title = "沼澤之旅", objective = "和塔貝薩談話。現在，是讓你得到自己的法師魔杖的時候了。首先，你得去和住在塵泥沼澤的人類隱者塔貝薩談一談。你可以在沼澤深處找到她的小室，那地方就在塞拉摩的西邊，石槌廢墟的北邊。\n\n去和她談談，她的知識非常淵博。完成任務後，你將獲得：\n\n", description = "現在，是讓你得到自己的法師魔杖的時候了。首先，你得去和住在塵泥沼澤的人類隱者塔貝薩談一談。你可以在沼澤深處找到她的小室，那地方就在塞拉摩的西邊，石槌廢墟的北邊。\n\n去和她談談，她的知識非常淵博。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][1953] = {title = "回到沼澤", objective = "和塔貝薩談話。", description = "<name>，是時候讓你去和塔貝薩談談了...這位塵泥沼澤裡的隱士將指導你如何鑄造強大的法師物品。\n\n塔貝薩就隱居在塵泥沼澤的深處，塞拉摩的西邊。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2038] = {title = "宾格斯的补给品", objective = "找回宾格斯的装备：\n\n宾格斯的气压炸弹、宾格斯的扳手、宾格斯的榔头和宾格斯的螺丝起子。", description = "好象在洛克湖坠机还不够倒霉似的，湖心小岛上来的穴居人还袭击了我，抢走了我的工具和气压炸弹。没有旋翼机没有炸药，我什么都干不了！\n\n去帮我找回工具和气压炸弹，<name>。为了诺莫瑞根！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "蒙特的鐮刀機械魔杖地精多用途光線槍您會收到：\n\n"}
MultiLanguageQuestData['tw'][2039] = {title = "尋找賓格斯", objective = "去洛克莫丹尋找賓格斯‧布萊頓海默。", description = "我們和賓格斯失去了聯繫!他被派去偵察諾姆瑞根，不過已經有足足一個星期沒回來報告了。這傢伙應該是失蹤了。\n\n最後有人看到他時，他正在洛克湖上空飛行。你可以去那一帶調查一下，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2040] = {title = "地底突襲", objective = "從死亡礦坑中帶回小型高能發動機，將其帶給暴風城矮人區中的沉默的舒尼。", description = "諾姆瑞根已經被那群卑鄙懦弱的穴居怪們完全佔據了!情況很緊急，或許你能幫上我們的忙，<name>。\n\n在死亡礦坑深處有一台功能強大的哥布林伐木機，找到這台伐木機並帶回它的能源供應機件。有了這台伐木機的能源供應機件，我們就能給高速鑽孔挖掘機供應足夠的能量，用它來鑽透這裡與諾姆瑞根之間的岩石。鑽開一條路，給他們來一次地精式的突襲!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "極地護手紫貂魔杖"}
MultiLanguageQuestData['tw'][2041] = {title = "沉默的舒尼", objective = "去暴风城的矮人区去，和那里的沉默的舒尼谈一谈。也许……也许你能帮我们攻打诺莫瑞根。\n\n你可以到暴风城去找秘密攻击部队的指挥官，沉默的舒尼。舒尼需要有人帮他找一些东西。\n\n你可以在暴风城的矮人区中找到她。\n\n祝你好运，<name>。完成任務後，你將獲得：\n\n", description = "也许……也许你能帮我们攻打诺莫瑞根。\n\n你可以到暴风城去找秘密攻击部队的指挥官，沉默的舒尼。舒尼需要有人帮他找一些东西。\n\n你可以在暴风城的矮人区中找到她。\n\n祝你好运，<name>。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2098] = {title = "基尔卡克的钥匙", objective = "找到基尔卡可钥匙的3段碎片，把它们交给基尔卡克·旋杆。", description = "想要当一个出色的海盗可不简单呀，你这个旱鸭子是不会理解的。我们的生活并不仅仅只是掠夺和痛饮！唉，我的船在海岸附近被那些可恶的鱼龙给弄沉了。\n\n我希望我的大副能够重新回来工作！\n\n当我被冲到海岸的时候，大副的钥匙在岩石上折断了，接着又被黑海岸那一带的怪物给偷走了，我只记得隐约看见一些狂暴暗礁蟹、凶猛的森林陆行鸟和几个鱼人正在搜寻船的残骸……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2118] = {title = "瘟疫蔓延", objective = "活捉一只狂暴蓟熊，把它带到萨纳瑞恩那里。", description = "一种疾病正在黑海岸蔓延，它能够控制一切与它接触的灵魂和肉体。\n\n这种瘟疫对蓟熊的影响最大，使得这种曾经高贵的动物现在几乎变成了毁灭和杀戮的机器——它们变得狂暴，完全失去了理智。我有一种方法应该可以治疗这种病。\n\n把这个陷阱放到森林的空地上。任何狂暴蓟熊经过时，都会在短时间内变得驯服。一旦蓟熊安静下来了，就上前安抚它，减轻它的痛苦（使用/soothe命令），然后它就会跟你走。把它带到这里来，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2158] = {title = "休息和放鬆", objective = "和獅王之傲旅店的旅店老闆法雷談話。", description = "每個冒險家在疲憊的時候都需要休息─而休息和放鬆的最佳去處就是獅王之傲旅店!\n\n我的好朋友法雷是那裡的旅店老闆。告訴他是我介紹你去的，也許他還會給你些特別優惠呢。\n\n如果你要去獅王之傲旅店的，沿著大路往南走就沒錯了!您會收到：\n\n", progress = nil, completion = nil, rewards = "獅王之傲護腕旅店老闆的手套閃金鎮鐵護腕經營者長手套您會收到：\n\n小南瓜清涼的泉水"}
MultiLanguageQuestData['tw'][2159] = {title = "多蘭納爾的貨物", objective = "把藥草送到旅店老闆凱達米爾手中。", description = "你好，年輕的<class>。你能幫我一個忙嗎?我有一包藥草必須送到多蘭納爾去，但是現在我還要忙於處理幽影谷德魯伊的事情，所以走不開。\n\n你能幫我把這包藥帶去嗎?把它送到多蘭納爾旅店的老闆凱達米爾那裡，那座旅店就在南方的路邊上。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n達納蘇斯乳酪清涼的泉水\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][2160] = {title = "塔诺克的补给品", objective = "给卡拉诺斯的塔诺克·霜锤带去一箱旅店补给品。", description = "嘿！我一看就知道你是个精力充沛的冒险家。如果你要继续前进的话，能不能帮我带个包裹到卡拉诺斯的旅馆去？\n\n你应该已经计划在那个旅店里稍作休息了，对吧？我敢说只要你到了旅店，就肯定会想在那里歇一下脚。\n\n无论如何，请把这包裹带给旅馆主人的助手塔诺克·霜锤。我自己是没法活着穿越那危险的通道了，巡山人卫队还得过些天才会经过这儿，所以我只能靠你了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "霜錘護腕卡拉諾斯腰帶踏雪長靴"}
MultiLanguageQuestData['tw'][2161] = {title = "苦工的重擔", objective = "把烏克爾的貨物帶給剃刀嶺的旅館主人格羅斯克。", description = "對不起，你能幫幫我嗎?\n\n我這兒有一車食物，一路上我遭遇了蠍子、蜘蛛，還有其他更可怕的東西!我把這些食物送到了試煉谷，因為我覺得他們可能會需要這個，同時我又很樂意幫助他們。\n\n但是他們居然根本就不需要食物!現在我還得把這些東西帶回剃刀嶺，可是我害怕路上的那些野獸...\n\n你能不能幫我送回去呢?我只是個苦工，可你是個大英雄，你一定什麼都不怕!\n\n請把東西交給剃刀嶺旅館的老闆格羅斯克。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n大塊的硬麵包清涼的泉水"}
MultiLanguageQuestData['tw'][2178] = {title = "炖陆行鸟", objective = "给急弯河的奥兰达利亚·夜歌带回5块陆行鸟肉。", description = "你闻到扑鼻的香气了吗？那可是用我的秘方精心烹制的、新鲜出炉的炖陆行鸟，口感超绝，美味无比！\n\n你对我的食谱很感兴趣吧？\n\n在我告诉你食谱之前，你得证明你能对付那些动物。\n\n我可并不是要求你简单地跑出去驯服一只陆行鸟，然后骑回来见我。你得去捕杀一些陆行鸟，把它们那些多汁的肉脯带回来给我。只有这样我才会把炖陆行鸟的秘方教给你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n食譜：陸行鳥燉肉陸行鳥燉肉"}
MultiLanguageQuestData['tw'][2198] = {title = "破碎的项链", objective = "找到破碎的项链的来源，从而了解其潜在的价值。", description = "你找到了一条破碎的项链，但是破旧不堪的外表并不能掩饰它高超的制作工艺。项链已经破碎，原本应该镶在项链上的三块宝石不见了。在项链的内侧印有铁炉堡的徽记，旁边还刻着三个小字：“TdK”。\n\n如果你想要了解这条项链背后的故事，你就必须找到它的主人。也许那个徽记和小字就是线索……完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2199] = {title = "昂贵的知识", objective = "给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。", description = "我在铁炉堡可是鼎鼎有名的珠宝匠！好吧，我承认那是以前的我……因为一个竞争对手的污蔑让我变成现在这个样子！名声不好在这行里就根本混不下去。结果，你看，我现在就变得穷困潦倒。\n\n现在，我要你给我搞五块银锭来，这样我才能完成我手头上的这份订单——看来这是我唯一的一份订单了。\n\n你给我五块银锭之后，我就会回答你所有关于这条项链的问题。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2200] = {title = "回到奥达曼", objective = "去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。\n\n已提供物品：\n", description = "我的一个邪恶的竞争对手居然污蔑我，说是我制作的项链诅咒了那个圣骑士！显然没有人愿意买被诅咒的东西。\n\n不如我们来做笔交易吧：如果你能帮我找回宝石，我就能重新把它镶到项链上，然后只要你帮我宣传这条项链并没有受到诅咒，帮我恢复名誉的话，我就将把这条项链送给你！\n\n我建议你从奥达曼开始搜集线索，或许那个圣骑士的尸体就在下面，毕竟他是最后一个拥有它的人！当你找到宝石之后就使用这个东西，它可以让你随时和我进行联系。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2201] = {title = "寻找宝石", objective = "在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。", description = "从这个圣骑士的日记上看，只有奥达曼才有可能是项链上的那三块宝石的所在地。如果日记的描述还算准确的话，在奥达曼里有大量的暗炉矮人和穴居人在活动。\n\n知道了这些信息之后，对宝石的搜索行动就可以开始了。当你收集到所有的宝石之后，通过塔瓦斯德的占卜之瓶和他联系来获取下一步的指示。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2204] = {title = "修复项链", objective = "从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。", description = "你现在需要去为项链找到它的“精神”力量，奥达曼无疑最适合的地方。据说那里有很多的石人跑来跑去，对吗？那么，杀死他们当中最强大、最邪恶的那个石人，然后把他身上的能量源夺过来！我敢保证可以把那能量源里的能量重新注入到项链之中。\n\n如果没有那样的能量源，想要修复项链根本是不可能的。取得能量源之后尽快回到铁炉堡来找我，然后我们就能把项链完全恢复到原来的状态啦！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2206] = {title = "連偷帶搶", objective = "找到碼頭主管，為馬迪亞斯‧肖爾拿到船運時間表。", description = "我們派在外面的探子回報，在閃金鎮南部有相當頻繁的盜賊活動。報告中指出，盜賊們控制了傑羅德碼頭，並利用它將大量的違禁品從赤脊山走私到西部荒野去。\n\n我要你想辦法到碼頭旁的屋子裡去一趟，把裡面的船運時間表給我偷出來，<name>。那東西應該就在碼頭主管的衣服口袋裡。\n\n...還有，<name>，如果你的行動被發現了的話，暴風城軍情七處將不會承認你的存在。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n狡詐之刃"}
MultiLanguageQuestData['tw'][2240] = {title = "密室", objective = "阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。", description = "现在我手头有个任务。\n\n我们要找到一间被称作卡兹穆尔大厅的密室。问题是这个房间在一扇巨大的门后面，而那扇门被锁住了！幸运的是，我知道如何打开它。\n\n我把所有东西都写在我的日记里了，就在这个台子上。我的队伍现在被困在这里……所以呢，<name>，你必须为我们找到卡兹穆尔大厅！\n\n阅读我的日记，探索那间密室，然后向铁炉堡探险者协会的勘察员塔伯斯·雷矛汇报。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "矮人衝鋒斧探險者協會礦星燈"}
MultiLanguageQuestData['tw'][2278] = {title = "白金圓盤", objective = "和石之看守者者交談，從他那裡瞭解更多古代的知識。一旦你瞭解到了所有的內容之後就啟動諾甘農圓盤。", description = "財寶室的中間是四塊巨大的白金圓盤，每塊圓盤上都刻滿了各種各樣的未知文字和圖案。你的手觸摸這些圓盤的時候，你感到了一絲震動。就在你接觸圓盤的一瞬間，一個巨大的石之看守者的形象出現在了你的面前。\n\n「你好。我是知識的守衛者。土靈的創造者所留下的一切有關這個種族的知識都已經存儲在了這張諾甘農圓盤上了。」\n\n你發掘到了迄今為止這個世界上最寶貴的知識財富!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2279] = {title = "白金圆盘", objective = "把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。", description = "再次触及诺甘农圆盘让你的手感受到了又一次的震颤。这一次从圆盘传出了一种奇怪的研磨声。\n\n你的背包忽然沉了一下。打开背包之后，你发现了一张迷你版的圆盘！\n\n毫无疑问，在任何对艾泽拉斯大陆历史感兴趣的人手中，这张圆盘都绝对是无价之宝。铁炉堡的探险者协会是一个非常有名的探险团体，也许他们能好好利用这张圆盘。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2280] = {title = "白金圓盤", objective = "把迷你版的諾甘農圓盤帶給某個對它們很有興趣的人。", description = "再次觸及諾甘農圓盤讓你的手感受到又一次的震顫。然而，這次從圓盤內部傳出了一種奇怪的研磨聲。\n\n你的背包忽然沉了一下。打開背包之後，你發現了一張迷你版的圓盤!\n\n毫無疑問，對任何有心研究艾澤拉斯大陸遠古時代歷史的人來說，這張圓盤絕對是無價之寶。一定有人會對這個感興趣!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "杜爾丁之錘白金劍奧達曼指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][2281] = {title = "赤脊山的聯絡員", objective = "到赤脊山的湖畔鎮與盧修斯交談。", description = "現在就把你派出去等於讓你去自殺，雷吉克可不想再讓哪個初出茅廬的盜賊平白掛掉。不過你也別著急，<name>。雷吉克要先培養你的能力。\n\n現在你就動身去赤脊山，和一個名叫盧修斯的軍情七處聯絡員談一談吧。他就在湖畔鎮的碼頭附近，和其他一些遊手好閒的傢伙整天攪在一起。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2283] = {title = "搜寻项链", objective = "在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。", description = "我们有工作要交给你做，不过能否完成要看你有没有胆子！\n\n在荒芜之地的深处有一个名叫奥达曼的挖掘场，我们最近听说有个没脑子的圣骑士在里面挂了。我之所以如此关心这个问题是因为那蠢货身上带着一条非常珍贵的项链，项链上有三块大宝石：一块红宝石，一块蓝宝石和一块黄宝石。\n\n现在的问题是，我们需要它，而且我们会付给完成这个任务的人最丰厚的报酬。也许那条项链已经受到了损坏，但是不管怎么样，只要你把它带给我们，就总是会有办法修好它。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2342] = {title = "尋回寶物", objective = "從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的派翠克·加瑞特。", description = "用這把破掃帚在這裡打掃蝙蝠窩實在不是件適合加勒特做的事!我靠這個該死的工作存了一些錢，而且我願意用這些錢來雇你幫我做些事情。\n\n加勒特家族的祖傳武器自從我們家到那裡去當挖掘工以來就一直被鎖在奧達曼的南會議廳中的箱子裡。沒有它，我就要永遠被困在這裡 - 幫這些該死的蝙蝠打掃。\n\n找到我家族的寶藏，把它給我拿來!幫我找回原本屬於我的東西!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2361] = {title = "修复项链", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n塔瓦斯德的魔法項鍊"}
MultiLanguageQuestData['tw'][2378] = {title = "尋找破碎之手氏族", objective = "前往奧格瑪，和暗影裂口那的申蘇爾談話。<name>，你一向以來都對我們衷心耿耿，現在是讓你出去闖一闖的時候了。雖然你已經展現出了在盜賊之路上過人一等的天賦，但是你還是需要更多的練習才能達到更高的境界。\n\n我們和破碎之手氏族是盟友。去找他們吧，一直以來我們的關係都很好─去奧格瑪找申蘇爾。完成任務後，你將獲得：\n\n", description = "<name>，你一向以來都對我們衷心耿耿，現在是讓你出去闖一闖的時候了。雖然你已經展現出了在盜賊之路上過人一等的天賦，但是你還是需要更多的練習才能達到更高的境界。\n\n我們和破碎之手氏族是盟友。去找他們吧，一直以來我們的關係都很好─去奧格瑪找申蘇爾。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2383] = {title = "简易羊皮纸", objective = "阅读简易羊皮纸，然后和试炼谷的弗朗恩谈一谈。", description = "啊，刚刚你不在的时候，有人送来了这张羊皮纸，<name>。\n\n如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是战士训练师弗朗恩写的，他有事找你。你可以在大兽穴外面的阴凉处找到他。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2398] = {title = "失踪的矮人", objective = "在奥达曼找到巴尔洛戈。", description = "奥达曼挖掘场从前并不是现在这样一团糟的。我们铁炉堡的矮人曾经控制了这个区域，但是……当穴居怪来了之后，一切都变了。它们的数量太多了，连我们矮人也挡不住它们！\n\n事实上，因为它们非常突然地发起了攻击，所以我担心我们有些人被困在了挖掘场里面。\n\n我的朋友巴尔洛戈带了一个矮人小队进入了挖掘场深处，就在穴居怪发起攻击之前。如果他和他的同伴们还活着的话，我希望你能找到他们。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2399] = {title = "發芽的樹葉", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n發芽的樹葉"}
MultiLanguageQuestData['tw'][2418] = {title = "能量石", objective = "給荒蕪之地的里格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。", description = "不久之前，我和暗爐矮人發生過一些插曲。他們把我帶到了苦痛堡壘，讓我對兩種來自於奧達曼的奇怪石頭進行研究。我發現這兩種石頭如果經過正確的處理，就會變成相當理想的能量源。能在那個廢舊的挖掘場裡發現這樣的東西讓我感到十分驚奇!\n\n總之，在我告訴他們這個秘密之後，那幫該死的傢伙就把我踢出了苦痛堡壘，然後自己在奧達曼挖掘更多的石頭。\n\n我自己也要那些石頭!幫我帶那兩種石頭來，我會給你豐厚的報酬的!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "能量石環杜拉辛護腕恆久長靴"}
MultiLanguageQuestData['tw'][2438] = {title = "翡翠攝夢符", objective = "取得翡翠攝夢符。", description = "班奈希爾獸穴的德魯伊守護者蓋洛拉斯‧塔文斯倫曾經給了我一個翡翠攝夢符。這種強大的護符可以吸取翡翠夢境的能量，給拿著它的人帶來好運。\n\n不過，我把它放在星風村的衣櫃裡了，沒辦法把它取回來...星風村原本是個寧靜的小村子，但現在那裡受到了熊怪的侵襲。\n\n你能不能幫我拿回攝夢符，<class>?", progress = "請快點行動吧。我祈求我的翡翠攝夢符沒有遭到熊怪的破壞。\n\n你拿到了它了沒有，<name>?", completion = "翡翠攝夢符對我來說非常重要。這樣的東西只有少數被選中的人才能得到。謝謝你把它還給我，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2439] = {title = "白金圆盘", objective = "把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。", description = "这东西真是个惊人的发现。如果这里储存的知识都是正确的话，那么这些圆盘所涉及的古代泰坦——或者说造物之神——肯定和我们的起源有所联系！我们要用尽可能多的时间来研究它。\n\n至于你，英勇的<class>，把这个凭证交给大厅里的丁尼塔·石衣，你一定会为你的伟大发现得到应有的报酬！\n\n准备好了之后就回到我这里来，探险者协会还有很多事等着你去做！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n超強治療藥水強效法力藥水\n\n您還會收到：\n\n軟皮袋"}
MultiLanguageQuestData['tw'][2459] = {title = "『食夢者』菲羅斯塔", objective = "殺掉7個瘤背秘術使，並找到遺失的珠寶。", description = "翡翠...不見了!我的攝夢符被毀了!\n\n星風村北部有一群瘤背秘術使。我接到報告說他們的領袖『食夢者』菲羅斯塔的脖子上戴著一條在夜間會發出綠光的項鍊。現在既然看到我的攝夢符，我確定就是他偷走了我的翡翠...他絕不會想到那顆翡翠對他毫無用處。\n\n去找到丟失的寶石，<name>。另外，你在那兒活動的時候，別忘了順便清除一些墮落的瘤背秘術使。", progress = "菲羅斯塔和瘤背秘法師必須把我的東西還給我。請取回翡翠，這樣我才能修復我的翡翠攝夢符。", completion = "現在我可以修復攝夢符了。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2478] = {title = "基本不可能的任務", objective = "從工頭希里克斯那裡偷出希里克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司閒工、兩個風險投資公司巡邏員、兩個風險投資公司看守。\n\n殺掉大工頭普茲克·加里維克斯，取了他的首級，然後打開加里維克斯的帶鎖箱，拿走贊吉爾的改良藥劑。將藥劑和加里維克斯的頭顱交給奧格瑪的申蘇爾，等候進一步的指示。", description = "你必須從工頭希里克斯身上偷出塔樓的鑰匙，<name>。拿到鑰匙之後，就把它收好─你也許用得到它。\n\n記住，毒藥已經讓塔樓裡的所有人都變得虛弱不堪。盡你所能給那些傢伙製造混亂和破壞，把他們全都殺了─不要手下留情!\n\n等裡面所有人都躺在血泊中之後，你就可以去打開加里維克斯的帶鎖箱，然後拿走贊吉爾的改良藥劑。把加里維克斯的腦袋和藥劑一起交給奧格瑪的申蘇爾。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n食譜：菊花茶"}
MultiLanguageQuestData['tw'][2499] = {title = "奧肯斯古爾", objective = "從奧肯斯古爾那裡取得巨大的瘤。", description = "我搞明白了!我不得不衝來這裡找你!其實答案很簡單...腐化是經由樹精傳染的，但源頭卻只有一個。\n\n奧肯斯古爾已經被一顆我所見過的最大的腫瘤毒害了...那個腫瘤簡直可以稱之為龐然大物。\n\n奧肯斯古爾過去住在我湖泊附近的一個洞穴裡，但後來跑到了東北方的一個隱蔽處。<name>，殺掉奧肯斯古爾，拿到它身上的腫瘤，讓這個墮落之源永遠從我的家園消失。", progress = "你找到奧肯斯古爾了嗎，<race>?", completion = "我就知道你的能力不只是足以將那個可怕的野獸趕出湖區這麼簡單。\n\n這真是個棘手的局面，奧肯斯古爾曾經是一個偉大的樹精領袖，但是墮落是不分平民和貴族的。\n\n這個腫瘤如此巨大，讓我感到十分費解，不過我一定要對它做進一步的研究才能更多地瞭解這種疾病。\n\n謝謝你，&lt;name&gt;。", rewards = "泥木腰帶苔蘚覆蓋的護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][2500] = {title = "荒芜之地的材料", objective = "从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。", description = "<class>，我需要你的帮助。我是个小有名气的炼金师，我需要你去荒芜之地帮我找一些原材料。\n\n我需要这些东西补充我的库存：五个秃鹫的胃囊、十颗峭壁山狗的牙齿和五块岩石元素碎片。当然你可以从这些动物身上拿到这些东西，不过如果你不擅长打仗的话，可以找些擅长的朋友。\n\n找到这些东西给我，作为交换你可以得到一些钱币。\n\n好吧，你觉得怎么样？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2518] = {title = "月神的淚水", objective = "取得薩絲拉的銀色絲囊。", description = "薩絲拉女士曾經受到伊露恩的寵愛，這只優雅而純潔的蜘蛛在月光下的迷霧中編織著銀線，用以收集銀色的露水，並將這種有強大治療功效的露水存放在附近的神殿裡。\n\n不過最近薩絲拉突然變得瘋狂起來，她的後代也受到了威脅。\n\n找到薩絲拉，<name>，結束她的痛苦。她住在這裡東北邊的河流附近。取得她的銀色絲囊，然後帶回來交給我。", progress = "我很遺憾不得不交給你這個任務，不過薩絲拉已經沒有救了。\n\n我們希望能把這些絲囊作為祭品獻給伊露恩。有了這個祭品，她就會保佑薩絲拉，讓她有可能獲得重生，並獲得安寧。", completion = "整個森林都在為薩絲拉女士哀悼，不過那是我們不得不做的事情。希望她如今能獲得安息。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2519] = {title = "月神殿", objective = "艾奎恩妮让你和月神殿的女祭司艾茉拉谈一谈。森林里有一个曾经强大无比的生物现在急需帮助，<class>。\n\n现在你有一项艰难的任务必须完成。\n\n请你去找女祭司艾茉拉，她会向你解释具体的问题。她就在这里东南方的月神殿里。完成任務後，你將獲得：\n\n", description = "森林里有一个曾经强大无比的生物现在急需帮助，<class>。\n\n现在你有一项艰难的任务必须完成。\n\n请你去找女祭司艾茉拉，她会向你解释具体的问题。她就在这里东南方的月神殿里。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2521] = {title = "为库米沙效力", objective = "在你探索诅咒之地的旅程中，如果碰巧发现了无瑕的德莱尼水晶球，就把它交给收藏家库米沙。\n\n你要知道，这种宝石是整个艾泽拉斯最珍稀的水晶。诅咒之地上的任何一种生物都有可能带着一颗无瑕的德莱尼水晶球。\n\n每找到一颗，你都会得到相应的酬劳。", description = "<race>，你的小脑袋能理解一颗无瑕的德莱尼水晶球有多么珍稀吗？无数德莱尼人终其一生就想要寻找一块这样的水晶，可是却屡遭失败，一直没能达到愿望。\n\n你现在就站在库米沙面前，你知道库米沙想要什么，而且你还愿意帮助我？很好，<race>……在你探索者个区域的过程中，只要找到一颗无瑕的德莱尼水晶球，就把它带回来给我，我会以你永远都无法想象的财富回报你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鑲翡翠的箱子"}
MultiLanguageQuestData['tw'][2522] = {title = "库米沙的努力", objective = "找到一颗无瑕的德莱尼水晶球，把它交给收藏家库米沙。", description = "虽然召唤传送门的魔法失败了，不过我相信下一次一定能成功。\n\n德莱尼人的希望就象你们<race>对财宝的渴望一样强烈，回到这块被诅咒的土地中去，再给我拿回一颗无瑕的德莱尼水晶球来。\n\n当然，要不要接受这个任务完全取决于你*咧嘴笑*。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鑲翡翠的箱子"}
MultiLanguageQuestData['tw'][2523] = {title = "被腐化的輕歌花", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['tw'][2541] = {title = "沉睡的德魯伊", objective = "將一個薩滿巫毒符咒交給班奈希爾獸穴的奧本‧怒爪。", description = "這裡的瘤背薩滿找到了一種可以在德魯伊休眠時將他的靈魂和肉體分離的方法。熊怪就這樣驅使著我的肉身，利用我去襲擊那些對班奈希爾獸穴進行偵察的人。現在我沉睡在翡翠夢境裡，無法阻止他們。\n\n你一定要幫幫我。瘤背薩滿用一種特殊的符咒來完成這種儀式，我希望能研究一下這種符咒。<name>，全靠你了。", progress = "如果我能研究一下那種符咒，也許就能破解瘤背薩滿的魔法。你找到符咒了嗎?", completion = "謝謝你，&lt;name&gt;。\n\n這真是個奇怪的小符咒...我可以感受到它散發出的可怕能量，這裡面包含了一種極為強大的魔法。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2561] = {title = "利爪德魯伊", objective = "奧本‧怒爪要求你去殺掉他那失去靈魂的身體，然後對其屍體使用巫毒符咒。", description = "在研究過這個符咒之後，<name>，我知道該做什麼了。請拿著它，然後照我說的去做。\n\n你必須接近附近房室的門。在門裡，你會發現我那失去靈魂的軀體...雖然我對接下來要說的話感到很遺憾，但是除此之外我找不到其他可以讓我擺脫瘤背熊怪控制的辦法了。\n\n你必須殺了我的肉身，然後對我的屍體使用巫毒符咒。完成這個任務之後就請回到我這裡來。", progress = nil, completion = "我終於擺脫了瘤背熊怪的控制。謝謝你，&lt;name&gt;。\n\n我的靈魂現在可以在翡翠夢境永遠安息了。\n\n也許有一天我們還可以再見面，年輕的&lt;class&gt;。不過現在，請你收下這個，它代表了我對你的感激之情。", rewards = "沉睡長袍灌木之刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][2581] = {title = "弯牙土狼的颚骨", objective = "收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。", description = "众所周知，土狼的颚骨具有强大的力量，不过它能折断三英寸厚的瑟银条吗？不可能，决不可能，可是我却亲眼看到了这种事情。\n\n到诅咒之地去给我弄三个弯牙土狼的颚骨回来，路上顺便打一些野猪和蝎子，因为我还需要两片诅咒之地的野猪肺和一个厚甲蝎螯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n土狼興奮劑"}
MultiLanguageQuestData['tw'][2582] = {title = "远古之怒", objective = "收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。", description = "啊，<name>，欢迎回来。你好像非常喜欢从土狼的颚骨中提炼出来的药剂所带给你的感觉。但是你要小心，虽然它可以使你拥有泰坦一般的力量，不过它对你的精神和智力也具有长期的负面作用。\n\n我跟你说了这么多之后，你还想要更多这种药剂吗？如果你还要的话，就给我弄三个弯牙土狼的颚骨、两片诅咒之地的野猪肺和一个厚甲蝎螯来。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n土狼興奮劑"}
MultiLanguageQuestData['tw'][2583] = {title = "野猪的活力", objective = "收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。", description = "这片不毛之地上生活着两种野猪：灰鬃野猪和地狱野猪。\n\n看来这些野兽的耐力十足，这让它们几乎可以不受任何伤害，因此其它动物都无法与之抗衡。\n\n我们要做进一步的研究，<name>。你给我弄三片诅咒之地的野猪肺、两个厚甲蝎螯和一颗石化蜥蜴的大脑来，我就可以从中提炼出一种超强的药剂。而你就将成为我的第一个实验对象！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n肺汁調酒"}
MultiLanguageQuestData['tw'][2584] = {title = "野猪之魂", objective = "收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。", description = "在第一次试用这种药剂的时候，我就知道仅用一两次是无法满足你对它的渴求的。即使是现在，我也还能看见你眼中的渴望。这种药剂会让人上瘾，再有意志力的人也无法抵挡它的诱惑。\n\n好吧！如果你还想要更多的肺片鸡尾酒，就到诅咒之地里去给我弄三片诅咒之地的野猪肺、两个厚甲蝎螯和一颗石化蜥蜴的大脑来。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n肺汁調酒"}
MultiLanguageQuestData['tw'][2585] = {title = "决定性的打击", objective = "收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。", description = "你见过它们作战吗，<name>？我是说那些蝎子。你有没有见过他们优美、敏捷的动作？有没有看到过它们那迅捷的攻击？\n\n如果我们能将它们的敏捷性分离出来并制成药剂，那我们就发达了……我的意思是……那将是我们对科学的一大贡献！\n\n帮帮我吧，<name>，我可以送给你一份实验样品。<name>我需要三个厚甲蝎螯，两个秃鹫的砂囊和一片诅咒之地的野猪肺。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n厚甲蠍藥粉"}
MultiLanguageQuestData['tw'][2586] = {title = "厚甲蝎盐", objective = "收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。", description = "你还活着！这真是个好消息。我猜你回来是想要更多的厚甲蝎盐吧？\n\n很好，<name>，那么，你再回到诅咒之地去，帮我弄三个厚甲蝎螯、两个秃鹫的砂囊和一片诅咒之地的野猪肺回来吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n厚甲蠍藥粉"}
MultiLanguageQuestData['tw'][2601] = {title = "石化蜥蜴的大脑", objective = "收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。", description = "这块荒地上到处都是红石蜥蜴，<name>。这些蜥蜴的族群比这里的其它任何生物都要兴旺。\n\n我曾经在远处观察过它们的捕猎和其它日常活动——这些野兽表现出了某种思考过程，它们的智商甚至比某些人型生物还要高。\n\n我得研究一下他们的脑子！\n\n给我找十颗蜥蜴的大脑来，<name>。还有，你必须再找两个秃鹫的砂囊，否则我就无法完成药物的配制。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n腦皮層混合飲料"}
MultiLanguageQuestData['tw'][2603] = {title = "秃鹫的活力", objective = "收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。", description = "死亡在这片被诅咒的土地上长出了翅膀，<class>。我曾亲眼目睹那些秃鹫将探险者的尸体狼吞虎咽地吃掉——有时它们甚至会吃下携带着致命疾病的尸体。它们身体内部的系统竟然能够抵御席卷了这片土地的瘟疫，这的确令我感到十分惊奇。\n\n请帮助我进行研究，<name>！我需要秃鹫的砂囊，还需要两块弯牙土狼的颚骨作为原料。\n\n我会和你五五分成的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n砂囊口香糖"}
MultiLanguageQuestData['tw'][2604] = {title = "精神矍铄", objective = "收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。", description = "我看到你体内的火焰已经渐渐熄灭，那就是说，药效只持续了一个小时？\n\n如果你还需要更多砂囊口香糖，就给我弄更多的砂囊来。在诅咒之地中收集十个砂囊和两块腭骨之后再回来。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n砂囊口香糖"}
MultiLanguageQuestData['tw'][2605] = {title = "口渴的哥布林", objective = "找到1個飽滿的露水腺，把它交給加基森的馬林·諾格弗格。", description = "住在大沙漠裡真是活受罪!我都要被烤乾了。\n\n不過我有個主意。聽說有一種被稱作露水收集者的生物就在西南方活動...它們有一種特殊腺體，可以用來儲藏水分。\n\n如果能得到這種腺體，我就可以暢飲一頓，至少滋潤滋潤我的嘴唇!你能幫幫我嗎，<name>?\n\n找到有一大片仙人掌的地方，<name>，露水收集者常在那裡出沒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2606] = {title = "好味道", objective = "马林·诺格弗格让你与加基森的斯普琳科谈一谈。", description = "呸！这个东西真难吃！这个主意也不过如此嘛……\n\n等等，你说什么？哦，我知道，我知道，你认为我不该就这么放弃它。那么，好吧。\n\n对了，我有个主意！一个妙极了的主意！去和我朋友斯普琳科谈谈吧——她是个出色的厨师。告诉她我们想做什么，还有我们想要知道加点什么才能把让人这东西咽下去。\n\n我的意思是，如果它这么难吃的话，总得让它有些让人兴奋的东西才行……可是我现在就是感觉不到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2641] = {title = "斯普琳科的秘密佐料", objective = "加基森的斯普琳科要你去給她找到一顆紫色水生菇。", description = "在我還小的時侯，我姐姐包攬了所有燒飯的活，那簡直是糟透了!她做的有些東西簡直讓我無法忍受─直到我發現了一種被我稱作「秘密佐料」的東西，只要加上一點...嘖嘖!味道好極了!\n\n你問那是什麼東西?嗯，是一種被稱作紫色水生菇的蘑菇。如果你要我把這個嘗起來像拖把一樣的東西變成可以下嚥的食品，那麼我建議你去一趟辛特蘭，到那裡去找一個小湖泊。\n\n哦，記住了，紫色水生菇只有在水下才能找到。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2661] = {title = "给马林的粉末", objective = "斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。", description = "这是紫色粉末，<name>，把它交给马林，告诉他，他欠我一个人情！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2662] = {title = "诺格弗格药剂", objective = "马林·诺格弗格让你在他制成药剂之后再去找他。现在，把这些粉末和露水混合在一起。\n\n等会儿再回来找我……那时我应该已经完成效力惊人的诺格弗格药剂了！您會收到：\n\n", description = "现在，把这些粉末和露水混合在一起。\n\n等会儿再回来找我……那时我应该已经完成效力惊人的诺格弗格药剂了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n諾格弗格藥劑"}
MultiLanguageQuestData['tw'][2681] = {title = "禁錮我們的石頭", objective = "解救九個拉瑟萊克的僕從、三個瑟溫妮的僕從、三個奧利斯塔的僕從和三個戈洛爾的僕從。完成任務後，回到部落英雄的靈魂這裡。", description = "要擊敗拉瑟萊克和他的手下，只靠你一個是不夠的。\n\n召集一隊勇士，讓我的同伴擺脫永恆的折磨吧!你要打碎十八塊石頭。\n\n努力戰鬥吧，<name>。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2701] = {title = "古代英雄", objective = "打开箱子，取走你的酬劳。", description = "请把这些古老的遗物拿走吧，我们不再需要这些东西了。\n\n希望在你和燃烧军团的战斗中，它们能对你有所帮助。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n裂蹄裂片"}
MultiLanguageQuestData['tw'][2702] = {title = "古代英雄", objective = "和桑德·裂蹄谈一谈。", description = "你用你高尚的行动和英勇的表现为我赢得了荣誉，<name>。\n\n你也为他们赢得了荣誉……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2721] = {title = "基利斯", objective = "找到基利斯的下落。你已完成了一次冒险，现在又有新的冒险在等着你，<name>。\n\n我有个手下至今下落不明，他应该在诅咒之地的某个地方，我说的就是基利斯中尉。\n\n我告诉过你，我和他当时被奥利斯塔囚禁起来严刑拷打，可怜的基利斯……他的意志力变得越来越薄弱。在我的牢房里都能听到他受刑的声音，他的惨叫在山洞里回荡。那是我最后一次听见基利斯的声音。完成任務後，你將獲得：\n\n", description = "你已完成了一次冒险，现在又有新的冒险在等着你，<name>。\n\n我有个手下至今下落不明，他应该在诅咒之地的某个地方，我说的就是基利斯中尉。\n\n我告诉过你，我和他当时被奥利斯塔囚禁起来严刑拷打，可怜的基利斯……他的意志力变得越来越薄弱。在我的牢房里都能听到他受刑的声音，他的惨叫在山洞里回荡。那是我最后一次听见基利斯的声音。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2741] = {title = "超级测蛋器", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n蛋箱"}
MultiLanguageQuestData['tw'][2742] = {title = "林吉被困住了！", objective = "护送林吉逃出奎尔丹尼小屋，然后在望海崖找到他藏起来的东西。", description = "嘿，那边的<race>！\n\n请你帮林吉逃出去，我知道像你这样的<race>不喜欢林吉，不过林吉求你了！我要逃出去！\n\n如果<race>帮林吉逃出这里，<race>就可以得到一些好东西……\n\n林吉在望海崖藏了个大秘密。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2743] = {title = "黑暗笼罩", objective = "回去见部落英雄的灵魂，将你的发现告诉他。", description = "我们都别拐弯抹角了，<class>，我的时间有限。\n\n你必须摧毁保护恶魔之王拉瑟莱克的三大魔头的势力。这个任务可不像解救一个被诅咒的灵魂那样简单。\n\n<基利斯咧开嘴大笑着>。\n\n你要知道，拉瑟莱克的三个手下各自戴着一件由拉瑟莱克特制的护符的三分之一。有了这个护符，你才能召唤那个恶魔。\n\n回去见特雷博，告诉他需要什么东西才能召唤拉瑟莱克，他会给你进一步的指示。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2744] = {title = "恶魔猎手", objective = "与艾萨拉的洛拉姆斯·萨里比迪斯谈一谈。", description = "那三个魔王受到拉瑟莱克的保护。\n\n为了让他们忠诚地为他效力，拉瑟莱克使他们在诅咒之地可以使用几乎无限的力量。他们佩戴的护符和他们的命运联系在一起，并使他们变得不老不死。只要他们待在诅咒之地，你就没法杀了他们，他们的生命力可以维持到世界末日。\n\n我认识一个也许可以帮助你的朋友，<name>。到艾萨拉地区的小岛上去找恶魔猎手洛拉姆斯·萨里比迪斯谈谈吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2745] = {title = "潜入城堡", objective = "与暴风城堡的泰里恩谈一谈。", description = "嗯，真是个有趣的故事，而且我们还要认真对待它。好吧，我可以帮你，但如果你想成功的话，就必须采用某种……正义而非法的手段。\n\n我们要赶快解决莱斯科瓦和马尔松，你认为你能胜任吗？\n\n你必须下定决心，到城堡里去找我的一个老朋友，一个名叫泰里恩的侏儒。几星期来他一直在监视着莱斯科瓦，他可以帮你解决这件事。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2746] = {title = "必備物品", objective = "將3塊絲綢和2顆克拉拉的新鮮蘋果交給暴風城的泰里恩。", description = "提亞斯要加快執行計畫了嗎?好吧，我們可以做到，不過我還沒準備好。你知道，我要做的是最困難的部分，而你是負責動手的人，明白嗎?很好。\n\n我要讓你先幫我準備些東西，這樣我就可以對間諜機器人進行偽裝，讓它安全地騙過那些守衛。\n\n給我帶回一些絲綢和幾隻蘋果來。絲綢你自己去找，不過城外那個克拉拉的小農場上有非常合適的蘋果。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2747] = {title = "特别的蛋", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n糖果盒"}
