MultiLanguageQuestData['tw'][2749] = {title = "普通的蛋", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n補給物品盒"}
MultiLanguageQuestData['tw'][2750] = {title = "坏掉的蛋", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2751] = {title = "野人裝甲", objective = "將兩副青銅花紋護腕、兩把青銅巨劍和兩隻鋒利的爪子交給奧格瑪的奧羅克‧沃姆什。", description = "這只鐵錘在沃姆什家族中傳了二十代，<name>。我們熔鑄的鐵有成千上萬噸。不幸的是，這門技藝到了奧羅克手中卻傳不下去了，這是沃姆什家族的恥辱─我既沒有親屬，又無法生育後代。\n\n絕不能讓沃姆什的祖傳技藝和我一起死去！必須有人繼承它，不管他是不是沃姆什家族的後裔！\n\n向奧羅克證明你的能力吧，<name>。給奧羅克找來這些東西:兩副青銅花紋護腕，兩把青銅巨劍和兩隻鋒利的爪子。把這些找來，我們再繼續。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設計圖：野人鐵胸甲"}
MultiLanguageQuestData['tw'][2752] = {title = "鐵肩鎧", objective = "將4把青銅戰鬥斧和4把青銅戰錘交給奧格瑪的奧羅克‧沃姆什。", description = "奧羅克可以看出你眼中的渴望，<name>。你像海綿一樣渴望吸收沃姆什的智慧。\n\n我會教你三樣東西!\n\n到鐵砧那邊去，感受熔爐的熱量，為奧羅克鑄造四把青銅戰鬥斧和四把青銅戰錘，然後你才能學習製造鐵肩鎧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設計圖：野人鐵護肩"}
MultiLanguageQuestData['tw'][2753] = {title = "踩在腳底下", objective = "將4頂綠鐵頭盔、4副綠鐵護腕和4副綠鐵護腿交給奧格瑪的奧羅克‧沃姆什。", description = "奧羅克還剩兩課要教給你，<name>。我知道你的肌肉很疼，不過為了沃姆什家族，你還要繼續!\n\n拿四頂綠鐵頭盔、四個綠鐵護腕和四個綠鐵護腿來給奧羅克 - 你可以學到知識，你的敵人也會更加痛苦!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設計圖：野人鐵靴"}
MultiLanguageQuestData['tw'][2754] = {title = "瘋狂之角", objective = "將2隻堅固的鐵槌、2雙鍍銀青銅長靴和2副鍍銀青銅護手交給奧格瑪的奧羅克‧沃姆什。", description = "這是奧羅克教你的最後一課，<name>。回到神聖的鐵砧和熔爐旁去!將兩隻堅固的鐵槌、兩雙鍍銀青銅長靴和兩副鍍銀青銅護手交給奧羅克。\n\n你會看到敵人眼中的恐懼!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設計圖：野人鐵頭盔"}
MultiLanguageQuestData['tw'][2755] = {title = "沃姆什的喜悅", objective = "觀察並學習沃姆什的喜悅之舞。", description = "奧羅克沒哭，<name>，眼睛進了灰。\n\n<奧羅克偷偷地抹去一滴眼淚。>\n\n奧羅克會教你最後一個沃姆什家族的秘密。多虧了<name>，奧羅克現在死而無憾了。\n\n學習沃姆什家族的喜悅之舞，你就學會了鋼鐵之拳!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設計圖：野人鐵手套"}
MultiLanguageQuestData['tw'][2756] = {title = "古老的技藝", objective = "將4套鋼質胸甲和4頂鋼質頭盔交給奧格瑪的『鐵砧』阿圖爾克。", description = "很久以前，阿圖爾克可以碾碎敵人的頭顱，將他們的骨頭磨成粉做燈絲...很久以前，<race>。現在大酋長號召各氏族和平相處。那些往日的敵人，現在我們只能用厭煩的眼光看著他們!\n\n我知道這很難以接受，不過這就是索爾的意願。\n\n實在是讓我感到悲哀!你是來學習的，那你就學吧!給我拿四套鋼質胸甲和四頂鋼質頭盔來，你可以在鍛造它們的時候嘗到戰爭的滋味!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2766] = {title = "寻找OOX-22/FE！", objective = "把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。", description = "你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。\n\n“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于深痕谷中的一个山洞里！”完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2767] = {title = "拯救OOX-22/FE！", objective = "安全护送OOX-22/FE到达目的地，然后向藏宝海湾的奥格索普·奥布诺提斯报告。", description = "那个侏儒的声音再次从那个机器人中传了出来：\n\n“我需要你帮忙把OOX-22/FE移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到被遗忘的海岸去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”\n\n“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "實驗失敗的飛行裝置鎖鍊長巾"}
MultiLanguageQuestData['tw'][2768] = {title = "探水棒", objective = "把探水棒交给加基森的首席工程师沙克斯·比格维兹。", description = "布莱中士偷了我的东西！他说只是借一下，但那混蛋却偷了我宝贵的探水棒！没有这根棒子，我就不知道该在哪里打井找水！\n\n去找到布莱，把我的探水棒拿回来！我听说他带着一帮恶名远扬的冒险者去了西边的祖尔法拉克古城寻宝，你肯定可以在那里找到他。\n\n但愿那里的巨魔已经把他干掉了，因为如果你必须打败他才能拿回探水棒的话，那必将是一场恶仗。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "石工兄弟會之戒工程學協會首盔"}
MultiLanguageQuestData['tw'][2769] = {title = "铜栓兄弟", objective = "和闪光平原的维兹尔·铜栓谈一谈。", description = "你有没有遇见铜栓兄弟？他们在卡利姆多的闪光平原上与地精赛车，而且他们通常都会获得胜利，这并不奇怪——地精的赛车轮胎总是爆掉，他们几乎从来都没有完成过比赛！\n\n但即使是这样，铜栓兄弟也还是在寻找新的方法使他们的车速更快，维兹尔跟我说过，他的下一个实验需要一种很稀有的原料。\n\n或许他需要别人的帮助来获取这种原料，你去和他谈谈就知道了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2770] = {title = "加兹瑞拉", objective = "把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。", description = "在塔纳利斯沙漠的巨魔古城祖尔法拉克深处，有一个神圣的池塘。巨魔可以从那个池塘里召唤一头巨大的野兽——加兹瑞拉！它凶猛异常，甚至连它的鳞片都会因为巨大的能量而发出声响。我要用它的能量来给我的赛车增加动力！\n\n把加兹瑞拉的鳞片给我弄来！\n\n不过，召唤加兹瑞拉的方法是巨魔的秘密。如果你想要面对加兹瑞拉的话，首先就要从巨魔那里弄到召唤它的方法。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n棍子上的胡蘿蔔賽車護目鏡"}
MultiLanguageQuestData['tw'][2781] = {title = "懸賞:卡利夫·斯科比斯汀", objective = "將卡利夫·斯科比斯汀的頭顱交給加基森的首席工程師膨嘯。", description = "懸賞:卡利夫·斯科比斯汀!\n\n塔納利斯的加基森水力公司願支付高價懸賞廢墟歹徒首領卡利夫·斯科比斯汀的項上人頭。他的罪行包括:\n\n1. 殺害加基森水力公司的雇員!\n2. 偷竊加基森水力公司的資源!\n3. 搶劫加基森水力公司的財產!\n\n將卡利夫·斯科比斯汀的死亡證明交給首席工程師膨嘯，我們將立刻兌現你的獎賞!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2783] = {title = "争论", objective = "与诅咒之地和悲伤沼泽交界处的部落英雄的灵魂谈一谈。我们在和错误的敌人进行战斗，<name>。\n\n这片土地上真正强大的力量正在不断增强，而我们却还在和兽人为了这片焦土进行无谓的争斗。\n\n我们难道要继续这种争斗，直到有一天让燃烧军团把我们都踏扁吗？这实在是一种愚蠢的行为。\n\n<name>，抛开你的偏见，和部落英雄的灵魂谈谈吧，他知道诅咒之地真正的秘密。完成任務後，你將獲得：\n\n", description = "我们在和错误的敌人进行战斗，<name>。\n\n这片土地上真正强大的力量正在不断增强，而我们却还在和兽人为了这片焦土进行无谓的争斗。\n\n我们难道要继续这种争斗，直到有一天让燃烧军团把我们都踏扁吗？这实在是一种愚蠢的行为。\n\n<name>，抛开你的偏见，和部落英雄的灵魂谈谈吧，他知道诅咒之地真正的秘密。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2801] = {title = "悲伤的故事", objective = "聆听部落英雄的灵魂讲述他的故事。", description = "请你一定要先听听我的故事。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2821] = {title = "质量的保证", objective = "给羽月要塞的普拉特·马克格鲁比带去10张厚重的雪人皮。", description = "我对于皮革制作的哲学是要做就做最好——没有商量余地。任何说质量不要紧的人都是想要把丹莫罗的那些水货卖给你！\n\n在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "普拉特的手工長靴普拉特的手工手套"}
MultiLanguageQuestData['tw'][2822] = {title = "质量的保证", objective = "给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。", description = "我为自己制作的皮革作品感到骄傲，它们也值得我骄傲，质量是永不可能妥协的东西。任何说质量不要紧的人都是在信口乱说！\n\n在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "杉多爾的手工手套杉多爾的手工長靴"}
MultiLanguageQuestData['tw'][2841] = {title = "設備之戰", objective = "從諾姆瑞根拿到鑽探設備藍圖和麥克尼爾的保險箱密碼，把它們交給奧格瑪的諾格。", description = "地精的技術─兩年前它最普遍的用途是被當作笑話，但是時代確實變了，現在他們建造的新型鑽探設備比我們所有伐木機加起來都要精密。我需要它的設計圖，<name>!\n\n不幸的是，這些設計圖被鎖在機電師瑟瑪普拉格身邊的一隻保險箱裡了。更糟的是，保險箱的密碼只有機電師瑟瑪普拉格一人知道。\n\n盡你所能得到那個密碼，<name>。把設計圖給我帶回來!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "公民長袍旅行皮褲雙鏈強化護腿"}
MultiLanguageQuestData['tw'][2842] = {title = "首席工程師斯庫提", objective = "和藏寶海灣的斯庫提談話。斯庫提和我剛剛從克努比那裡得到關於新型地精鑽探設備的消息，就馬上開始動手研製捷運器6000型了，它是去諾姆瑞根最快捷可靠的方法!\n\n現在它已經完成了，<name>。如果你想試試的話，就到藏寶海灣去和雙足飛龍棲息處的斯庫提談談吧。你可以從棘齒城乘船去藏寶海灣。\n\n當然，你也可以試試從滿地都是矮人的丹莫洛山脈走到諾姆瑞根去!完成任務後，你將獲得：\n\n", description = "斯庫提和我剛剛從克努比那裡得到關於新型地精鑽探設備的消息，就馬上開始動手研製捷運器6000型了，它是去諾姆瑞根最快捷可靠的方法!\n\n現在它已經完成了，<name>。如果你想試試的話，就到藏寶海灣去和雙足飛龍棲息處的斯庫提談談吧。你可以從棘齒城乘船去藏寶海灣。\n\n當然，你也可以試試從滿地都是矮人的丹莫洛山脈走到諾姆瑞根去!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2844] = {title = "大保姆", objective = "寻找走丢了的精灵小姑娘。都是我不好，<name>。我本应细心照顾我的小朋友，沙恩。但是不知道为什么，她离开了我。我并不十分清楚发生了什么事，真的，但我最后一次看到她的时候，我们正在穿越这里北面的废墟。\n\n一切都很正常，但我转过身一看……她就不见了。\n\n现在我不知道该怎么办了。你有办法吗，<name>？我很担心。\n\n嘿，你帮我去找沙恩怎么样？你看上去应该比我跑得快一些。完成任務後，你將獲得：\n\n", description = "都是我不好，<name>。我本应细心照顾我的小朋友，沙恩。但是不知道为什么，她离开了我。我并不十分清楚发生了什么事，真的，但我最后一次看到她的时候，我们正在穿越这里北面的废墟。\n\n一切都很正常，但我转过身一看……她就不见了。\n\n现在我不知道该怎么办了。你有办法吗，<name>？我很担心。\n\n嘿，你帮我去找沙恩怎么样？你看上去应该比我跑得快一些。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2846] = {title = "深渊皇冠", objective = "将深渊皇冠交给尘泥沼泽的塔贝萨。", description = "很久以前我曾经拥有一件美丽的珍宝，深渊皇冠。它不仅美丽——而且它对于知道怎么使用它的人来说更是一件拥有巨大力量的宝贝。\n\n所以当水占师维蕾萨听说皇冠的事情之后，她就发誓要得到它。维蕾萨派人在我外出的时候到我家来偷走了皇冠，这些卑鄙的小偷！\n\n我要取回我的皇冠！到位于塔纳利斯沙漠中的巨魔城市祖尔法拉克去，把皇冠从她手上抢回来。把它还给我，你会得到报酬的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n幻法之杖晶岩肩鎧"}
MultiLanguageQuestData['tw'][2861] = {title = "塔貝薩的任務", objective = "與塵泥沼澤的塔貝薩談話。", description = "據說有個名叫塔貝薩的法師想要某個祖爾法拉克食人妖的命。如果你去找塔貝薩的話，她會讓你知道詳情的。\n\n別忘了帶幾個夥伴，<name>。如果塔貝薩真的讓你去祖爾法拉克的話，你最好不要獨自前往。\n\n塔貝薩的小屋就在塵泥沼澤裡，準確地說，是在塞拉摩的西邊，石槌廢墟的北邊。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2862] = {title = "与豺狼人开战", objective = "将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。", description = "豺狼人……它们现在不再只是一个小麻烦了，它们已经对我们形成了巨大的威胁！这些豺狼人是不是菲拉斯的原住民已经不重要了；如果我们无法有效地对抗它们，那我们早晚都会被赶出这个地区的。\n\n豺狼人最近对营地的攻势愈演愈烈，因此我们需要你的帮助来削弱它们的数量。带给我十份豺狼人的鬃毛，我会为你付出的努力而给予优厚的报酬。\n\n赶快出发吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2864] = {title = "特蘭雷克", objective = "與加基森的特蘭雷克談話。", description = "我的兄弟特蘭雷克現在顯然處於困境中。幾個星期之前他曾經向我承諾會給我一批聖甲蟲的殼，但是至今為止我還沒有收到。他是我的兄弟，所以我可不想派人去加基森砸他的場子。\n\n你能幫我去問問特蘭雷克到底是怎麼回事嗎?在我真的發飆之前他最好快點把貨給我送來。\n\n加基森就在卡林多大陸上的塔納利斯沙漠北部。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2865] = {title = "聖甲蟲的殼", objective = "帶5個完整的聖甲蟲殼給加基森的特蘭雷克。", description = "塔納利斯這裡的聖甲蟲的殼都很硬!硬得足可以給好多東西當建築材料，好多東西!\n\n事實上，因為那些殼都太有用了...聖甲蟲已經被獵殺得近乎滅絕了!\n\n我知道哪裡有更多的聖甲蟲，如果你保證會給我弄些殼來，我就告訴你它們在哪裡。你保證嗎?\n\n好吧，祖爾法拉克裡面有許多聖甲蟲，我想食人妖們並不因為想要那些殼而獵殺它們。\n\n但你可以!到祖爾法拉克去給我弄些完好無損的殼回來!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2866] = {title = "索兰萨尔废墟", objective = "探索索兰萨尔废墟，并调查纳迦在那个地区的情况。", description = "在我们的南边就是索兰萨尔废墟，那个地区的历史相当悠久。我们探索过那个遗迹，没有发现什么特别值得注意的东西，所以我们就离开了。\n\n最近，憎世纳迦占据了那片遗迹，而且他们的数量已经多到了让我们不得不警惕的程度。一开始我们认为那些纳迦是准备对我们发起攻击，虽然这种可能性现在依然存在，但我们觉得他们可能是有什么别的目的。\n\n现在就到那片废墟去查看一番吧，祝你好运，<name>。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2867] = {title = "返回羽月要塞", objective = "向羽月要塞的珊蒂斯·羽月汇报你的发现。", description = "在索兰萨尔废墟的心脏地带发现了奇怪的瞭望台之后，你觉得应该马上回到羽月要塞去向珊蒂斯·羽月汇报这个发现。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2868] = {title = "暂无内容", objective = nil, description = "把这个坏小子塞到Sunken Temple的巨魔墓里，让他吃吃苦头。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2869] = {title = "憎世纳迦之战", objective = "收集10块憎世纳迦的鳞片，把它们交给羽月要塞的拉托尼库斯·月矛。", description = "我们认为，无论纳迦想要干什么，他们最终的目的无非是完全占据这座岛屿，由此我们制定了相应的行动计划。我们要尽早采取攻击行动来消除这种威胁，否则就可能全盘皆输。\n\n给我带来十块完整的憎世纳迦的鳞片——你应该知道如何获得这东西。这样一来，纳迦在萨尔多岛上的力量就被大大削弱了，这对我们是非常有利的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2870] = {title = "击败沙尔扎鲁", objective = "消灭沙尔扎鲁，然后把神秘遗物交给羽月要塞的拉托尼库斯·月矛。", description = "<name>，新的侦查报告让我们对纳迦部队的组成有了一个更清晰的概念。纳迦的皇室成员在他们的部队中具有最高的权威性。\n\n皇室成员中的沙尔扎鲁是个极端残酷的纳迦，侦查报告表明最近他在南部的遗迹中发现了一块奇怪的古代遗物，那个地方就在恐怖之岛那里。\n\n你的任务就是结果他，然后把那块遗物给我带回来进行研究。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2871] = {title = "递送遗物", objective = "将神秘遗物交给羽月要塞的维斯提亚·月矛。", description = "如果你能帮我将这个东西送给我的妻子维斯提亚，那我会非常感激的。她不仅是我们这里的女祭司，也会是你所见过的最博学的学者之一。我即使抓破头皮也搞不清楚这个东西到底是什么，可我的妻子不同，如果世界上有人能知道这东西是什么，那无疑就是她了……我们也迫切地需要知道真相！\n\n拜托了，<name>。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "黎明騎兵護軀衛戍頭盔"}
MultiLanguageQuestData['tw'][2872] = {title = "斯杜雷的債務", objective = "與熱砂港的斯杜雷談話。", description = "我的老朋友欠我一瓶特殊的朗姆酒。他在塔納利斯沙漠的熱砂港裡經營著一家酒吧，他向我保證說，那裡的朗姆酒絕對比藏寶海灣的任何酒都要香醇，還說如果我喝了他的酒不滿意的話，那他就會雙倍奉還他欠我的錢!\n\n好吧，我想他現在已經不像他上次說這話的時候那麼自信了，他害怕給我嘗他的朗姆酒了。但是我還是想繼續這個賭注，那麼你就替我去和他談談吧...完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2873] = {title = "斯杜雷的货物", objective = "将斯杜雷的货物交给热砂港的斯杜雷。", description = "我欠藏宝海湾的“海狼”马克基雷一些朗姆酒，那是打赌输的，但我现在一瓶朗姆酒都没有了！科尔戈船长偷了我最后一船货，他把它们藏在南边的那个戒备森严的海盗镇里。\n\n如果你能找到我的那批朗姆酒并把它们给我拿回来的话，那我就可以向马克基雷证明，藏宝海湾的那些酒跟我的朗姆酒比起来只能被称作垃圾！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2874] = {title = "給麥克基雷的貨物", objective = "將斯杜雷的瓶子交給藏寶海灣的『海狼』麥克基雷。", description = "再次感謝你的幫助，<name>。這裡有一瓶熱砂港朗姆酒。把它交給麥克基雷，這樣他就可以拋棄藏寶海灣烈酒，改喝熱砂港朗姆酒了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "劍客束帶斷骨長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][2875] = {title = "通缉：安德雷·费尔比德", objective = "将安德雷的徽记交给热砂港的安全主管吉罗姆·比格维兹。", description = "可恶的海盗安德雷·费尔比德因对热砂港和加基森所犯的罪行正被通缉。\n\n根据政府讨论所发布的决议，任何阅读这则通缉令的人有权在逮捕安德雷和他的同党过程中采取可能致其死亡的手段。\n\n进一步的决议表明，如在审讯期间，安德雷死了或病了，他的徽记可以作为代替品，将它交给安全主管吉罗姆·比格维兹仍将使这份通缉令生效。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2876] = {title = "船运时刻表", objective = "把船运时刻表交给热砂港的某个官员。", description = "这卷轴上面记载着热砂港和藏宝湾之间的船运时刻表，包括过去和未来计划中的船运批次和船名，一些船的旅程旁有个大大的红叉记号，剩下的旁边有类似“华丽的战利品”和“坚固的战舰”之类的字样。\n\n热砂港那里的人一定非常想看看这个文件。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2877] = {title = "清理隐匿石", objective = "杀掉10个绿色淤泥怪和10个玉石软泥怪，然后回到鹰巢山向弗拉加尔报告。", description = "比起那些铁炉堡的兄弟们来，我们蛮锤部族对于过去曾发生过的事情有着更加深刻的记忆。如果你想在这里交朋友的话，那么你就要证明给我们看！\n\n部落的蛮子们从隐匿石一带撤了出去，现在那里满地都是淤泥怪。我们想要占领那个地区，不过首先我们要找些人来帮我们清理一下恼人的淤泥怪。\n\n这就是你要做的事情了！到那边去干掉十个绿色淤泥怪和十个玉石软泥怪，然后回到这里来向我报告。快出发吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2878] = {title = "被腐化的輕歌花", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2880] = {title = "巨魔部族项链", objective = "给鹰巢山的弗拉加尔带去5条巨魔部族项链。", description = "直接说吧，<class>——我们不属于联盟！蛮锤部族是独立的，我们依靠自己所做的事情来证明自己的价值，不像那些只会说废话的家伙一样，用闲聊来掩饰自己什么都不想做的态度！\n\n如果你要和我们作朋友，那么首先向我们证明你的价值！那些遍布辛特兰的巨魔有时会带着他们部族的项链。给我带五条项链过来作为友好的证明吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2881] = {title = "巨魔部族项链", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2882] = {title = "科爾戈的黃金", objective = "找到科爾戈的黃金!", description = "這張地圖上畫著一條對著南方的海灘，圖下方用優雅的字體寫著...\n\n\n熱砂港南邊\n家的南邊\n找到骨頭，旗子和旗杆\n如果你夠膽，就去挖挖看\n挖挖看啊，科爾戈的金子閃亮亮!\n開箱需鑰匙，鑰匙你會看見\n你面對的要用血來做交換。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n科爾戈的秘密寶藏"}
MultiLanguageQuestData['tw'][2904] = {title = "一团混乱", objective = "将克努比护送到出口，然后向藏宝海湾的斯库提汇报。", description = "<克努比呻吟着>发……发生什么事了？\n\n我只记得自己被一队黑铁矮人抓住了，他们暴打了我一顿，把我跟这些丑陋的穴居人扔在一块儿。\n\n快救我出去，<name>！\n\n我有个计划：把我带到出口，如果我们能活着走出去的话，你就到藏宝海湾去，告诉斯库提我去了棘齿城，然后警告廷克维斯，黑铁矮人准备制造超强的钻探设备。\n\n让我们开始吧！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "焊接護腕精靈之翼"}
MultiLanguageQuestData['tw'][2922] = {title = "拯救尖端機器人!", objective = "將尖端機器人的記憶體核心交給鐵爐堡的技工大師歐沃斯巴克。", description = "當我們摯愛的諾姆瑞根城淪陷時，我可憐的發明─尖端機器人─受到了某種致命的打擊。它原本包含了很多精巧的設計，並且儲存了大量的資訊，憑藉這些，它無數次地幫助了我和我的同事，但現在它的正電子腦被極化，變成了負電子腦...尖端機器人的行為已經變得完全異常了。它像個瘋子似的在諾姆瑞根裡咆哮!\n\n也許我們仍然可以挽救它，如果你能找回尖端機器人的記憶體核心並把它交給我，那麼我就能找到故障的原因，然後把我可憐的尖端機器人修好。\n\n您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2924] = {title = "基础模组", objective = "收集12个基础模组，把它们交给铁炉堡的科劳莫特·钢尺。", description = "有一种通用型的机械部件——基础模组——对于诺莫瑞根的技师和铁匠来说都非常重要，不过在我们大举逃出诺莫瑞根的时候，谁也没想起要把这些东西带上！我手头上的工作需要大量这种部件。\n\n请去诺莫瑞根给我拿一些基础模组回来，它们就装在城市深处的机械储存柜里。\n\n谢谢你，<name>，请尽快出发吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2926] = {title = "諾恩", objective = "用空著的鉛之瓶對著輻射入侵者或者輻射掠取者，從它們身上收集放射塵。瓶子裝滿之後，把它交給卡拉諾斯的奧齊·電環。", description = "事故後，諾恩想的說的都離不開兩個主題:如何將穴居怪趕出諾姆瑞根，以及如何為席捲諾姆瑞根的瘟疫找到治療的方法。\n\n幸運的是，拉茲和我已經快要研究出一種治療方法了─要不然就是一種很強勁的朗姆酒的配方。我們要試過才知道!當然，為了檢驗我們的理論是否成立，我們需要一些東西，準確地說，是諾姆瑞根城裡那些穴居怪身上的輻射塵。用這個小瓶子裝一些泛著綠光的輻射塵，然後把它帶回來!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2927] = {title = "灾难之后", objective = "与丹莫罗中卡拉诺斯的奥齐·电环谈一谈。你不会认为我生来就是是秃子吧？事实并不是这样的，<先生/女士>！诺莫瑞根的放射性泄露导致了我悲剧性的脱发。在那之前，我有着整个艾泽拉斯世界独一无二的侏儒式飞机头！\n\n<诺恩一边说一边挥舞着拳头>\n\n那些该死的穴居怪——他们都该死！！\n\n或许现在还不晚，<name>。我们也许仍然可以挽回局势——我说的是这座城市！去跟卡拉诺斯的奥齐·电环谈谈吧，他和他伙伴拉兹正在想办法。完成任務後，你將獲得：\n\n", description = "你不会认为我生来就是是秃子吧？事实并不是这样的，<先生/女士>！诺莫瑞根的放射性泄露导致了我悲剧性的脱发。在那之前，我有着整个艾泽拉斯世界独一无二的侏儒式飞机头！\n\n<诺恩一边说一边挥舞着拳头>\n\n那些该死的穴居怪——他们都该死！！\n\n或许现在还不晚，<name>。我们也许仍然可以挽回局势——我说的是这座城市！去跟卡拉诺斯的奥齐·电环谈谈吧，他和他伙伴拉兹正在想办法。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2928] = {title = "陀螺式挖掘机", objective = "收集24副机械内胆，把它们交给暴风城的舒尼。", description = "太糟糕了，<name>。我们没有足够的零件让我们的陀螺式挖掘机部队进入丹莫罗。\n\n我们需要的是零件，<name>，更多的零件。说到寻找零件，难道还有比诺莫瑞根更好的地方吗？我听说那里的机器人像牧区的牛似的到处游荡。\n\n我要你做的就是到诺莫瑞根去，把这些机器人拆开，拿出它们的内部装置。给我弄两打来就够了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "舒尼的扳手欺詐長手套"}
MultiLanguageQuestData['tw'][2929] = {title = "大叛徒", objective = "到诺莫瑞根去杀掉机械师瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。", description = "我以前曾经非常信任麦克尼尔，我从未想过他会背叛我和所有侏儒同胞。他为什么要背叛我们？为了权力？为了金钱？这些东西只要加以时日他都可以拥有。现在我们背井离乡，那个疯子掌握了政权，成了个什么都没有的国王……\n\n我们要夺回诺莫瑞根，<name>。在夺回自己的城市之前，我们决不停止努力。如果你想加入我们，就先去完成一个简单的任务：杀了那个叛徒，机械师瑟玛普拉格。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "公民長袍旅行皮褲雙鏈強化護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][2930] = {title = "抢救数据", objective = "将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。", description = "在逃离诺莫瑞根的时候，我们留下了太多的数据！非常重要的数据！\n\n我需要一张彩色穿孔卡片，你可以从诺莫瑞根城里的矩阵式打孔计算机3005-D型里找到这种卡片。不过糟糕的是，要得到它的话，你就必须先接近低级安全终端，也就是A型，B型和C型计算机，然后用不同的穿孔卡片开启它们，从白色的卡片开始……而且我们把所有的穿孔卡片都留在城里了。\n\n这真是一场灾难！你能帮忙吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n修理工的斗篷技師的蒸汽錘"}
MultiLanguageQuestData['tw'][2932] = {title = "可怕的消息", objective = "在辛特蘭收集枯木食人妖的頭皮，把它們串在尼姆布亞之矛上。將尼姆布亞的長矛插在辛特蘭的某個枯木食人妖村莊中，然後回到荊棘谷的尼姆布亞那裡。", description = "枯木食人妖原來是部落的盟友，但他們現在背叛了索爾...他們要為此受到懲罰!\n\n來，拿起我的長矛，到北面的辛特蘭去，那個地方就在塔倫米爾的東北方向。\n\n追捕那裡的枯木食人妖，收集他們的頭皮，把我的長矛插在他們的某個村莊中，比如西利瓦薩或者祖瓦沙。\n\n讓他們知道，背叛部落，遲早要還的!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2933] = {title = "毒液瓶", objective = "将毒药瓶交给塔伦米尔的某个药剂师。", description = "这些瓶子里装有绿色的毒液。\n\n由村庄中这种瓶子的数量来看，枯木巨魔一定很重视这些东西。或许塔伦米尔的药剂师会对这些毒液的样本感兴趣。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2939] = {title = "寻找知识", objective = "与鲁瑟兰村的达蕾恩·轻风谈一谈。虽然遍布菲拉斯的废墟和遗迹可能很危险，但是它们讲述了许多曾经发生的事情……\n\n几天前我在南边的碎石堆里搜索的时候，发现了一个看起来像是根普通法杖的东西。但是，我总觉得事情并不是那么简单，安吉拉斯和我在这里钻研书籍已经很久了，不过我们没发现什么和它相关的信息。\n\n我在达纳苏斯有一个同事，她能告诉我这是什么东西，<name>。你为什么不去跟她谈谈呢？也许她能帮助我们。完成任務後，你將獲得：\n\n", description = "虽然遍布菲拉斯的废墟和遗迹可能很危险，但是它们讲述了许多曾经发生的事情……\n\n几天前我在南边的碎石堆里搜索的时候，发现了一个看起来像是根普通法杖的东西。但是，我总觉得事情并不是那么简单，安吉拉斯和我在这里钻研书籍已经很久了，不过我们没发现什么和它相关的信息。\n\n我在达纳苏斯有一个同事，她能告诉我这是什么东西，<name>。你为什么不去跟她谈谈呢？也许她能帮助我们。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2940] = {title = "菲拉斯的历史", objective = "如果你想借达蕾恩·轻风的书，要先得到她的允许。看起来这本书很久没有人打开过了。它的封面破旧而且书页发黄，但检查后你会发现这正是特洛亚斯要找的那本书。\n\n你把它捡了起来，但你却突然意识到，也许应该在借阅之前得到物主的允许。完成任務後，你將獲得：\n\n", description = "看起来这本书很久没有人打开过了。它的封面破旧而且书页发黄，但检查后你会发现这正是特洛亚斯要找的那本书。\n\n你把它捡了起来，但你却突然意识到，也许应该在借阅之前得到物主的允许。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2945] = {title = "髒兮兮的戒指", objective = "想方法把髒兮兮的戒指弄乾淨。", description = "你在一個黑鐵矮人的屍體上發現了一枚戒指。但要辨認戒指的細節卻很困難，泥土和堅硬的污垢將它整個包裹了起來，你根本沒法戴上它。你覺得它是用某種珍貴的金屬製成的，似乎還鑲著寶石。\n\n如果你想好好看看這枚戒指的話，就得找些東西把戒指表面的污垢清理掉。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2946] = {title = "拭目以待", objective = "将迷你白金圆盘拿到塔纳利斯的奥丹姆大门去，找出两者之间的联系。", description = "我希望你把这张圆盘拿到奥丹姆的封印之门去。我们……我们不能肯定这样做会带来什么后果。\n\n当然，这听上去确实很危险，但也有可能什么都不会发生。也许你要将圆盘放在什么东西上，也许你只要带着圆盘，大门就会自己打开。总之，不试一试是不会知道真相的。\n\n等你完成这项任务之后就回到铁炉堡来，我们还有很多事需要讨论。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2947] = {title = "歸還戒指", objective = "你可以自己留著這枚戒指，或者按照戒指內側刻著的名字找到它的主人。", description = "打開由超級清潔器5200型製作的盒子之後，你看到了一枚閃閃發光的戒指!你戴上了戒指，立刻感覺身體中湧動著神奇的力量。\n\n戒指的內側有一個很小的鐵爐堡徽印，旁邊刻著三個字:「基瑟爾」。\n\n這可能是它以前的主人或是製作者的姓名縮寫。是將這枚戒指留著自己用，還是把它物歸原主，這要由你自己來決定...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2948] = {title = "地精的手藝", objective = "將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給鐵爐堡的塔瓦斯德‧基瑟爾。", description = "聽著，<name>，這戒指當然是你的...但是我可以給你做一枚更好的!就像我說的一樣，那種設計實在太簡單了。現在我的技術更加嫺熟了，只要你付我三十個銀幣的費用，我就可以幫你製作一枚新戒指!好吧，事實上還要再加一點點...\n\n我現在手頭很緊，我的所有存貨都用完了。如果你給我一塊銀錠和一塊綠瑪瑙，我就可以讓戒指看起來更加閃亮華貴!\n\n相信我!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塔瓦斯德的金戒指"}
MultiLanguageQuestData['tw'][2949] = {title = "歸還戒指", objective = "你要麼自己留著這枚戒指，要麼就按照戒指內側刻著的名字找到它的主人。", description = "打開由超級清潔器5200型製作的盒子之後，你看到了一枚閃閃發光的戒指!你戴上了戒指，立刻感覺身體中湧動著神奇的力量。\n\n戒指的內側有一個很小的奧格瑪徽印。徽印旁刻著一行字母，但即使是經過清理之後也只能看清三個:「NOG...」\n\n這可能是它以前的主人或是製作者的姓名縮寫。是將這枚戒指留著自己用，還是把它物歸原主，這要由你自己來決定...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2950] = {title = "諾格的手藝", objective = "將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給奧格瑪的諾格。", description = "不，不，不─我當然不是突然就說這枚戒指是我的。嗯，我通常不這樣做，但你提供的關於黑鐵矮人的情報很有用，所以我會破例為你改造你的戒指，我的手藝絕對比製作這個小東西的傢伙要高超得多。嗯，八成是個地精做的...\n\n如果你給我拿來一塊銀錠、一塊綠瑪瑙和三十枚銀幣作為加工費的話，我就可以在戒指中加入白銀和瑪瑙的精華來加強其魔力。怎麼樣，感興趣嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n諾格的金戒指"}
MultiLanguageQuestData['tw'][2951] = {title = "超級清潔器5200型!", objective = "將髒兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。", description = "這個裝置屹立於那些竭力保護房間的地精中，裝置上有一塊小金屬牌，上面寫著「超級清潔器5200型」，還有一段文字:\n\n:「污垢和殘渣讓你的東西看起來污穢不堪?超級清潔器5200型會使它重現光芒!將你想要清理的物品放入清潔器中，然後向槽裡投入三枚銀幣。稍候片刻，你的珍寶就會重新變得潔淨而耀眼!」", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2952] = {title = "超级清洁器5200型！", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n被清潔器包裝過的盒子"}
MultiLanguageQuestData['tw'][2953] = {title = "再次使用超級清潔器", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n被清潔器包裝過的盒子"}
MultiLanguageQuestData['tw'][2954] = {title = "石头卫士", objective = "询问诺甘农的石头卫士，搞清楚它要让你干什么，然后再次点击它脚下的奥丹姆石座。", description = "“向你致意——我是把守入口的守护者。除非你拥有完整的奥丹姆圆盘，否则我不会让你进入奥丹姆城。”\n\n这个石头卫士一定就是派你来这里的人希望能在这里找到的东西。看来你必须在继续探索之前找出石头卫士背后隐藏的故事。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2962] = {title = "更多的辐射尘！", objective = "到诺莫瑞根去收集高强度辐射尘。要多加小心，这种辐射尘非常不稳定，很快就会分解。\n\n奥齐要求你把沉重的铅瓶也交给他。", description = "你的样本不仅数量不够，而且纯度也不够。\n\n我们需要更多的辐射尘。很显然，穴居怪身上的辐射剂量根本无法满足我们的需要。你必须重返诺莫瑞根，直接从辐射源头取回一些辐射尘。我指的是那些受到辐射的泥浆怪、潜伏者和水元素。小心一点，收集这种辐射尘并不容易。也许你得试好几次才能找到一个合适的样本。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2963] = {title = "奥丹姆的线索", objective = "与铁炉堡探险者大厅中的史学家卡尼克谈一谈。", description = "你好，很高兴再一次见到你，<name>！你在奥达曼的发现使探险者协会兴奋不已。协会一直都在努力揭开你所发现的那张白金圆盘的秘密。你来的正是时候，我可以和你分享一下我们的最新进展！\n\n史学家卡尼克发现了一些很重要的线索，可能有助于找到塔纳利斯沙漠中的守卫之谷的起源。他想和你谈谈，越快越好！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2964] = {title = "进一步的任务", objective = "与铁炉堡的资深探险家麦格拉斯谈一谈。好吧，<name>…我们现在好象走进了一个死胡同。我们知道我们需要的是什么——奥丹姆圆盘——但我们不知道这些东西在哪里。我们得进行大量的研究才能制定出确实可行的计划。关于到哪里去寻找圆盘……我有一些想法，我坚信我们马上就会要求你尽快出发去找到它。\n\n这件事要通知资深探险家，<name>，毫无疑问，他也会再次感谢你对探险者协会的帮助。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "好吧，<name>…我们现在好象走进了一个死胡同。我们知道我们需要的是什么——奥丹姆圆盘——但我们不知道这些东西在哪里。我们得进行大量的研究才能制定出确实可行的计划。关于到哪里去寻找圆盘……我有一些想法，我坚信我们马上就会要求你尽快出发去找到它。\n\n这件事要通知资深探险家，<name>，毫无疑问，他也会再次感谢你对探险者协会的帮助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "占卜魔杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][2969] = {title = "精灵龙的自由", objective = "从恐怖图腾营地的围栏里释放被俘获的小精龙。至少6个小精龙和辛达尔·月纹必须活着。\n\n如果6分钟之内你还没能达成这个目标，辛达尔就会决定撤退，任务也会随即失败。", description = "可恶的恐怖图腾部族正在捕捉精灵龙，<name>。耶尔卡和我不知道他们打算对这些精灵龙做什么，但那总不会是什么好事。\n\n我们还没有强悍到可以杀进营地去解救那些精灵龙，但也许有了你的帮助……如果你能找到一些得力的帮手的话，就从笼中释放那些精灵龙吧，另外你要保证它们都活着逃出去。我也会帮你的。耶尔卡会留在这里继续戒备。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2971] = {title = "暂无内容", objective = "[PH] Log Description", description = "[PH] Description您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2973] = {title = "新斗篷的光辉", objective = "给莫沙彻营地的克鲁伊格·碎颅带去10个闪光的小精灵翅膀。", description = "你好，<class>。我和我的伙伴们正准备去菲拉斯执行任务。\n\n我的妻子科琳很喜欢新衣服，所以我想为她做一件用小精龙的翅膀装饰的新披风。你能帮帮我吗？长着美丽翅膀的小精龙在莫沙彻营地的西边。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2975] = {title = "菲拉斯的食人魔", objective = "莫沙彻营地的洛卡·奥赫要你杀掉10个戈杜尼食人魔、10个戈杜尼食人魔法师和5个戈杜尼蛮兵。", description = "戈杜尼食人魔在这一地区的影响已经不容忽视了。<name>，你可以清楚地看到这一点，他们的存在污染了这片土地。在他们进一步扩张之前，我们一定要把他们赶回去。\n\n沿着河向北走，你会找到他们的前哨营地。去杀掉他们，<name>。我们必须告诉这些食人魔：他们在这里不受欢迎。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2977] = {title = "返回铁炉堡", objective = "与铁炉堡的史学家卡尼克谈一谈。", description = "你打开了底座，白金圆盘又一次突然出现在你的背包里。\n\n你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回铁炉堡向探险者协会汇报这个大发现了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2978] = {title = "戈杜尼卷轴", objective = "将戈杜尼卷轴交给莫沙彻营地的洛克·奥汉。", description = "你捡起了这个沾满泥土的卷轴，发现上面写着某种集会或仪式的内容。洛卡·奥赫应该会对这个卷轴以及它对戈杜尼食人魔的意义感兴趣。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2981] = {title = "菲拉斯的危機", objective = "貝爾戈洛姆·石槌想讓你去和莫沙徹營地的洛卡·奧赫談話。", description = "菲拉斯是一個有成就的<class>證明自己能力的理想場所。有個名叫戈杜尼的巨魔部族是那裡最主要的軍事力量，而且他們的勢力仍在不斷增長。在這些巨魔威脅到我們在菲拉斯的地位以前，我們必須要阻止他們。\n\n我認識一個名叫洛卡·奧赫的戰士，她住在菲拉斯的莫沙徹營地裡，去找她談談吧，她會讓你知道更多情況的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2982] = {title = "高原荒野", objective = "安吉拉斯·月风要求你杀死8个戈杜尼术士、8个戈杜尼萨满祭司和8个戈杜尼蛮兵。", description = "虽然菲拉斯森林的废墟中隐藏着巨大的危险，但特洛亚斯和我一直以来都在调查这个地区。\n\n最近特洛亚斯老是独自一人去高原荒野，这很让我担心。戈杜尼食人魔已经占领了那里，他们不会对任何进入他们领地的冒险者手下留情的。\n\n我希望你能到菲拉斯南部去一趟，消灭一些食人魔。让我的特洛亚斯安全一点，我会十分感激你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2987] = {title = "戈杜尼钴矿石", objective = "莫沙彻营地的奥尔文·吉兹米克需要12块戈杜尼钴矿石的样本。", description = "我刚刚到达菲拉斯时，曾听说这里的戈杜尼食人魔有一些有趣的矿石。天知道食人魔用矿石来干什么，但他们确实在很小心地保护那种东西！他们有意隐藏这些矿石，以免我们接触到它。\n\n如果你愿意的话，我会把我的铲子给你。到北面的戈杜尼前哨站去，给我挖些戈杜尼钴矿回来。注意找那些泛着蓝光的矿石，然后就挖！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "瑪哈林之靴凝星者披風"}
MultiLanguageQuestData['tw'][2988] = {title = "枯木巨魔的牢笼", objective = "检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。", description = "我们最强大的狮鹫的儿子失踪了！几天前，沙普比克和它的父母外出打猎时失踪了，我们认为是巨魔抓走了它。\n\n你必须帮帮我们！到枯木巨魔的两个村子里去搜一搜那里的笼子，看看沙普比克是不是被关在里面。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2989] = {title = "祖尔祭坛", objective = "检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。", description = "沙普比克没有和枯木巨魔在一起，那么或许是邪枝巨魔带走了他……到邪枝巨魔控制地区的西部边缘去，在那里的祖尔祭坛上找一找吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2990] = {title = "萨迪斯·格希德", objective = "将沙普比克的羽毛交给诅咒之地的萨迪斯·格希德。", description = "把这根羽毛交给占卜师萨迪斯·格希德。几年前，他离开鹰巢山去寻求黑暗的知识，但他内心深处仍是一个不折不扣的蛮锤矮人！\n\n也许他的智慧能帮助我们找到沙普比克。\n\n这根羽毛是从它的巢穴里拿出来的，如果你把它交给萨迪斯，那么他也许就可以用占卜法术找到沙普比克。\n\n祝你好运，<name>。你可以在诅咒之地找到萨迪斯，他就在守望堡的法师塔上。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2991] = {title = "耐克鲁姆的徽章", objective = "将耐克鲁姆的徽章交给诅咒之地的萨迪斯·格希德。", description = "我会帮你找出那头狮鹫的下落，但你得先为我做点事情。巨魔城市祖尔法拉克里面有一个名叫耐克鲁姆的巨魔，他拥有一枚徽章，我很想研究一下那东西。把徽章交给我，我就帮你找到沙普比克。\n\n祖尔法拉克在塔纳利斯的沙漠中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2992] = {title = "占卜", objective = "等待萨迪斯完成占卜仪式。", description = "在我进行占卜仪式的过程中，不要打断我。我会找出你拿来的那根羽毛和它主人之间的关系，然后顺藤摸瓜找到沙普比克。\n\n理论上讲是这样……如果一切都按照计划进行的话。如果不是，那么……你最好闭上眼睛。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2993] = {title = "返回辛特兰", objective = "与辛特兰的狮鹫管理员沙拉克·鹰斧谈一谈。", description = "沙普比克被关在巨魔城市辛萨罗的悬崖上的一只笼子里，笼子的钥匙由邪枝巨魔的邪恶祭司海克斯掌管着。\n\n我已经做了我该做的那部分事情，希望你执行任务的时候一切顺利，<name>。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][2994] = {title = "拯救沙普比克", objective = "到辛萨罗山顶去，杀掉邪恶祭司海克斯，找到沙普比克笼子的钥匙，然后救出沙普比克。", description = "你必须得救出沙普比克！\n\n杀进邪枝巨魔那座城市——辛萨罗的山顶，从邪恶祭司海克斯那里拿到沙普比克笼子的钥匙，找到沙普比克，把它救出来！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "獅鷲騎士戰錘獅鷲騎士護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][2995] = {title = "联络中心", objective = "幽暗城的奥兰·斯内克威瑟让你到辛特兰去烧毁高原精灵记录、高原精灵报告和高原精灵信件。", description = "奎尔丹尼小屋是高等精灵在辛特兰的联络中心。他们的使者正在试图与其他种族建立联系，他们会与这些种族分享与辛特兰南部的枯木巨魔的情报。所有联络其他种族所需的文件都被保存在了小屋中。\n\n我们不希望那些精灵与其他种族建立联盟关系，<name>。\n\n去摧毁他们的文件，或者说，我们要毁掉他们的联络中心……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][2998] = {title = "聖潔之書", objective = "與暴風城的達索瑞恩·拉爾談話。你好，我的<兄弟/姐妹>。我們這裡最有影響力的聖騎士─達索瑞恩·拉爾最近談起過你。我聽他說過你應該去找他接受試煉了...我也從他那裡聽說過你的出色表現。\n\n如果我是你，而且我有時間的話，我就會去暴風城和他聊聊的。我很肯定他會待在聖光大教堂裡─他一般都待在那裡。完成任務後，你將獲得：\n\n", description = "你好，我的<兄弟/姐妹>。我們這裡最有影響力的聖騎士─達索瑞恩·拉爾最近談起過你。我聽他說過你應該去找他接受試煉了...我也從他那裡聽說過你的出色表現。\n\n如果我是你，而且我有時間的話，我就會去暴風城和他聊聊的。我很肯定他會待在聖光大教堂裡─他一般都待在那裡。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3022] = {title = "小心運送", objective = "把仔細包裝過的木箱交給魯瑟蘭村的艾瑞拉斯·琥珀。", description = "<name>，顯然你很想幫我進行崇高的事業。嗯，當然，你可以為我做一些事情!\n\n請把這箱蛋送給艾瑞拉斯·琥珀。他是一個很重視這些蛋的德魯伊，而且一直在幫助孵化這些蛋，以及訓練幼小的角鷹獸。你可以在泰達希爾南邊的一個名叫魯瑟蘭村的村莊裡找到他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3042] = {title = "巨魔调和剂", objective = "收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。", description = "祖尔法拉克的沙怒巨魔用砂石制造巨魔调和剂，我可以用它来加强我铸造的东西！有眼光的行家会出高价购买经过这样处理的装备，所以，如果你能给我提供足够的调和剂，那我一定会重重奖赏你的。\n\n祖尔法拉克在加基森的西北边。祝你好运。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3062] = {title = "黑暗坠饰", objective = "莫沙彻营地的塔罗·刺蹄要你给他拿去艾丹娜·邪爪的黑色坠饰。", description = "艾丹娜·邪爪是居住在西面废墟里的北泉鹰身人的皇后。她是个彻头彻尾的恶魔，我听说她的心是水晶做的。除了对别人的仇恨之外，她没有一丝其它的情感。你必须击败艾丹娜，把她的黑色坠饰交给我。\n\n我听说鹰身人有一种号角——在废墟北部的邪爪石那里吹响号角就可以召来她。\n\n当她发现召唤她的是死亡的命运而不是她的同族时，她会有多么惊讶啊！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "羽冠手套硬角束腰"}
MultiLanguageQuestData['tw'][3063] = {title = "对鹰身人的复仇", objective = "塔罗·刺蹄让你杀掉4个北泉鹰身人、4个北泉游荡者、4个北泉唤风者和4个北泉杀戮者。", description = "年轻时，我曾是个经验丰富的猎手，没有什么野兽会让我感到害怕，直到……\n\n有一次在树林里，我在一场恶战之后正在打磨自己的武器，这时我遭到了伏击。鹰身人包围了我，好不容易我才脱了身。\n\n直到现在，我还能听见它们的嚎叫在耳边回荡……\n\n现在我已经不再年轻了，不过仇恨还在我的心中燃烧——这么多年了，我一定要报仇。\n\n北泉鹰身人就在西边，<name>，去为我复仇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3064] = {title = "暫無內容", objective = "帶20頂完整的海賊帽給尤爾巴‧斯庫比格特。我的商店需要海賊帽。給我帶一些來!", description = "我的商店需要海賊帽。給我帶一些來!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3087] = {title = "风蚀羊皮纸", objective = "阅读风蚀羊皮纸，然后和试炼谷的卡朗尼沙谈一谈。", description = "啊，刚刚你不在的时候，有人送来了这张羊皮纸，<name>。\n\n如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是猎人训练师卡朗尼沙写的，他有事找你。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3088] = {title = "密文羊皮纸", objective = "阅读密文羊皮纸，然后和试炼谷的鲁瓦格谈一谈。", description = "啊，刚刚你不在的时候，有人送来了这张羊皮纸，<name>。\n\n如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是潜行者训练师鲁瓦格写的，他有事找你。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3089] = {title = "符文羊皮纸", objective = "阅读符文羊皮纸，然后和试炼谷的史克里克谈一谈。", description = "啊，刚刚你不在的时候，有人送来了这张羊皮纸，<name>。\n\n如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是萨满祭司训练师史克里克写的，他有事找你。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3090] = {title = "被污染的羊皮纸", objective = "阅读被污染的羊皮纸，然后和试炼谷的纳托克谈一谈。", description = "啊，刚刚你不在的时候，有人送来了这张羊皮纸，<name>。\n\n一般来说我是不会去招惹术士的，但是如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这张羊皮纸是术士训练师纳托克写的，他有事找你。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3091] = {title = "简易便笺", objective = "阅读简易便笺，然后与纳拉其营地的哈鲁特·雷角谈一谈。", description = "刚才有一个信使来找过你，<name>。我相信她是战士训练师哈鲁特派来的。如果这张便笺的确是哈鲁特写的，那么你最好赶快看看上面都说了些什么。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3092] = {title = "风化便笺", objective = "阅读风化便笺，然后与纳拉其营地的兰卡·远箭谈一谈。", description = "刚才有一个信使来找过你，<name>。我相信她是猎人训练师兰卡派来的。如果这张便笺的确是兰卡写的，那么你最好赶快看看上面都说了些什么。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3098] = {title = "雕文卷轴", objective = "阅读雕文卷轴，然后和丧钟镇教堂的伊莎贝拉谈一谈。", description = "啊，刚刚你跟天灾军团的那些行尸走肉作战的时候，有人送来了这根卷轴。我想这应该不是什么小事，因为卷轴上有法师训练师伊莎贝拉的印章。如果我是你的话，就会看看这上面说什么。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3099] = {title = "被污染的卷轴", objective = "阅读被污染的卷轴，然后和丧钟镇的马克希米林谈一谈。", description = "啊，刚刚你跟天灾军团的那些行尸走肉作战的时候，有人送来了这根卷轴。我想这应该不是什么小事，因为卷轴上有术士训练师马克希米林的印章。如果我是你的话，就会看看这上面说什么。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3100] = {title = "简要的信件", objective = "阅读简要的信件，然后与北郡修道院的莱尼·拜舍尔谈一谈。", description = "有人把这封信交给我，说是等你消灭黑石间谍之后立即交给你，<name>。看起来这封信是我们这里的战士训练师莱尼写给你的，如果我是你的话肯定会毫不犹豫的先看看这信里写了些什么，再去做别的事情。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3101] = {title = "圣洁信件", objective = "阅读圣洁信件，然后和北郡修道院的萨缪尔修士谈一谈。", description = "有人把这封信交给我，说是等你消灭黑石间谍之后立即交给你，<name>。看起来这封信是我们这里的圣骑士训练师萨缪尔修士写给你的，如果我是你的话肯定会毫不犹豫的先看看这信里写了些什么，再去做别的事情。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3102] = {title = "密文信件", objective = "阅读密文信件，然后与北郡修道院的乔里克·克里丹谈一谈。", description = "有人把这封信交给我，说是等你消灭黑石间谍之后立即交给你，<name>。看起来这封信是我们这里的潜行者训练师乔里克写给你的，如果我是你的话肯定会毫不犹豫的先看看这信里写了些什么，再去做别的事情。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3103] = {title = "神圣信件", objective = "阅读神圣信件，然后与北郡修道院的牧师安妮塔谈一谈。", description = "有人把这封信交给我，说是等你消灭黑石间谍之后立即交给你，<name>。看起来这封信是我们这里的牧师训练师安妮塔写给你的，如果我是你的话肯定会毫不犹豫的先看看这信里写了些什么，再去做别的事情。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3104] = {title = "雕文信件", objective = "阅读雕文信件，然后与北郡修道院的凯尔东·布雷曼谈一谈。", description = "有人把这封信交给我，说是等你消灭黑石间谍之后立即交给你，<name>。看起来这封信是我们这里的法师训练师凯尔东写给你的，如果我是你的话肯定会毫不犹豫的先看看这信里写了些什么，再去做别的事情。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3105] = {title = "被污染的信件", objective = "阅读被污染的信件，然后与北郡修道院旁边的杜希拉·拉萨雷谈一谈。", description = "有人把这封信交给我，说是等你消灭黑石间谍之后立即交给你，<name>。看起来这封信是我们这里的术士训练师杜希拉写给你的，如果我是你的话肯定会毫不犹豫的先看看这信里写了些什么，再去做别的事情。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3107] = {title = "神圣符文", objective = "阅读神圣符文，然后与安威玛尔的布罗莫斯·格鲁诺尔谈一谈。", description = "<name>，有人让我把这块符文交给你。如果你有时间的话就看一下吧，好像是圣骑士训练师布罗莫斯写给你的。看看符文上说了些什么，然后去安威玛尔里面找他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3108] = {title = "风蚀符文", objective = "阅读风蚀符文，然后与安威玛尔的索加斯·格瑞姆森谈一谈。", description = "<name>，有人让我把这块符文交给你。如果你有时间的话就看一下吧，好像是猎人训练师索加斯写给你的。看看符文上说了些什么，然后去安威玛尔里面找他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3116] = {title = "简易符记", objective = "与幽影谷中奥达希尔里面的奥莉希亚谈一谈。", description = "我们的战士训练师奥莉希亚派来的信使把这块符记交给了我，看起来奥利希亚有话要跟你说，看看符记上写了些什么，然后把符记给她带去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3117] = {title = "风化符记", objective = "与幽影谷中奥达希尔里面的阿亚娜·远途谈一谈。", description = "我们的猎人训练师阿亚娜派来的信使把这块符记交给了我，看起来阿亚娜有话要跟你说，看看符记上写了些什么，然后把符记给她带去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3118] = {title = "密文符记", objective = "与幽影谷中奥达希尔里面的弗拉胡恩·影语者谈一谈。", description = "我们的潜行者训练师弗拉胡恩派来的信使把这块符记交给了我，看起来弗拉胡恩有话要跟你说，看看符记上写了些什么，然后把符记给他带去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3119] = {title = "神圣符记", objective = "与幽影谷中奥达希尔里面的珊达谈一谈。", description = "我们的牧师训练师珊达派来的信使把这块符记交给了我，看起来珊达有话要跟你说，看看符记上写了些什么，然后把符记给她带去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3120] = {title = "綠色符記", objective = "在幽影谷中和瑪丹特·硬木談話。", description = "我們的德魯伊訓練師瑪丹特派來的信差把這塊符記交給了我，看起來瑪丹特有話要跟你說，看看符記上寫了些什麼，然後把符記給他帶去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3121] = {title = "奇怪的要求", objective = "將皺縮頭顱交給菲拉斯拉瑞斯小亭的瑟拉希·火刃。", description = "莫沙徹營地北方拉瑞斯小亭的瑟拉希·火刃有我所需要的東西!他調配出了一種混合物，我需要用它來...好吧，你以後會知道的。\n\n快點出發，去找瑟拉希。拿著這個東西，這是一顆皺縮的頭顱，我答應瑟拉希用它來交換草藥。這是某個可憐矮人的頭顱，我在森林裡撞見了他，然後就...我敢說瑟拉希一定會很高興的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3123] = {title = "测试容器", objective = "去杀掉10头铁鬃熊或是长牙奔跑者，然后使用灵魂精华容器捕获它们的灵魂。\n\n将灵魂精华容器和10个野兽灵魂精华交给菲拉斯的巫医尤克里。", description = "这是一个测试，对我将要进行的仪式和你的能力来说都是一个测试。拿着这个容器，<name>。你可以用它将一个生物的灵魂禁锢起来。\n\n到东边的荒野中去寻找野兽吧。那些铁鬃熊，还有那些长牙奔跑者都是你的目标，<name>。杀死它们，在它们的灵魂逃跑之前用灵魂精华容器把它们收起来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3128] = {title = "天然材料", objective = "为莫沙彻营地的巫医尤克里收集2根断裂的原木、6颗包壳矿石、20片有弹性的肌腱和40块金属碎片。", description = "我需要一些特定的材料来完成我的工作……你可以把这件事情与我要给你的其它几个任务一起完成了。\n\n我需要菲拉斯树人身上的一段断裂的原木，西边的那些山岭巨人和精灵龙身上的包壳矿石，还有从辛特兰的枭兽或者菲拉斯的角鹰兽身上找到的有弹性的肌腱。最后，我还需要大量的金属碎片，这些碎片可以从我刚才提到过的这些生物身上找到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3130] = {title = "憎世纳迦之战", objective = "到羽月要塞的拉托尼库斯·月矛那里去报到。", description = "现在，我要让你到我的助手拉托尼库斯那里去，他一直都在密切注意纳迦的动向。我会对这里的综合形势作出评价，然后才能够采取行动将他们赶出这里，但是一旦我们发起攻击，我们的要塞就必然处于部落的直接威胁下——或者更糟，因此这并不是最佳的方案。\n\n不管怎么样，拉托尼库斯正在等着你。你的表现一直很不错，<name>，希望你能继续保持。\n\n你可以出发了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3141] = {title = "洛拉姆斯", objective = "听洛拉姆斯·萨里比迪斯讲述他的故事。", description = "你想和恶魔战斗？听听我的故事会对你有好处。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3161] = {title = "加茲瑞迪安", objective = "塔納利斯的瑪爾馮·瑞文斯克要你收集30件加茲瑞迪安飾物。", description = "<name>，我是一個科學家，但是我真正的身分其實是一個賞金獵人!\n\n很久以前，當食人妖還在片土地上橫行的時候，他們製作了很多以加茲瑞拉為原型的飾物，並把它作為偶像膜拜。那些裝飾物上的形象被稱為「加茲瑞迪安」，也就是九頭蛇之神的意思。\n\n我自己找到了一些這種飾物，但是我需要更多來進行研究─也許你可以幫我搞到一些?\n\n我甚至發明了一個可以幫助你尋找加茲瑞迪安的裝置!把這件頭盔拿去，開始尋找吧!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "學識法杖勘測員外套"}
MultiLanguageQuestData['tw'][3181] = {title = "玛尔戈的巨角", objective = "将玛尔戈的巨角交给巡山人贝波蒂。", description = "这根巨大的角上有许多擦痕和裂缝，还有一块金属物体嵌在粗糙的表面上。\n\n仔细检查了一番之后，你发现这块金属实际上是一把断掉的斧头。金属上刻着一行字：\n\n巡山人贝波蒂的财产。\n\n当你试着把斧头拔出来的时候，它一下子变成了无数的碎片。\n\n真糟糕！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3182] = {title = "证明信", objective = "把玛尔戈的巨角交给铁炉堡的索里奥斯馆长。", description = "你指望我会相信这样一个故事？真正的角怎么会是这个样子？\n\n听着，把这个明显是赝品的东西拿给铁炉堡的索里奥斯馆长看看。如果他能证明你的话是真的，那么你就能收到一份证明。把那份证明拿回来给我，我就给你一把灼热峡谷的钥匙。\n\n快动身去找索里奥斯馆长！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3201] = {title = "馆长的证明！", objective = "把索里奥斯的证明信交给巡山人贝波蒂。", description = "我真不敢相信贝波蒂居然怀疑这支角的真实性。现在就你和我，我不妨直说，我认为她纯粹是嫉妒！我知道她很想亲手杀了那只野兽，你的“意外的成功”让她的美梦破灭了。\n\n那么，你需要证明是吗？你对博物馆的贡献很大，这不是问题。\n\n<索里奥斯馆长从一大堆文件中翻找东西。>\n\n好了！你可以把它拿去交给贝波蒂。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n[Key to Searing Gorge]"}
MultiLanguageQuestData['tw'][3241] = {title = "暂无内容", objective = "把他们带给图加·符文图腾。从鬼雾峰收集图腾，因为那里现在令人作呕，没有地方有干净闪亮的图腾。", description = "从鬼雾峰收集图腾，因为那里现在令人作呕，没有地方有干净闪亮的图腾。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3341] = {title = "寒冰之王", objective = "安德魯·布隆奈爾要你殺了『寒冰使者』亞門納爾並將其頭骨帶回來。", description = "在貧瘠之地有一處許多藤蔓混雜的地方，那裡被稱為剃刀高地。我們早期的觀察就已經發現那裡的情況有些不對，最近更發現那裡的情況變得更加不妙了...\n\n剃刀高地的野豬人和天譴軍團結成了聯盟。有個名叫『寒冰使者』亞門納爾的巫妖利用他強大的精神力領導著它們每一步的行動。\n\n亞門納爾與耐祖奧有著直接的心靈感應聯繫;我們必須切斷這個聯繫，<name>。我們必須幹掉『寒冰使者』。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鎮壓者之劍琥珀之光咒符"}
MultiLanguageQuestData['tw'][3361] = {title = "逃難者的困境", objective = "取回菲利克斯的盒子、菲利克斯的箱子和菲利克斯的螺釘桶。", description = "我本來正在前往諾姆瑞根的途中，打算和我的地精同胞會合，結果一切錯得一塌糊塗!\n\n我離開安威瑪，包包裝好，跋涉過及腰的雪。然後我們遇上這場莫名其妙的地震，把我震得暈頭轉向。結果我跑到了這裡，更糟的是，食人妖偷光了我的東西!\n\n<name>，過去那一天半顯然證明了我能力不足。你介意幫個忙，進入西南方的食人妖營地，把我的東西帶回來給我嗎?", progress = "一等我拿到工具，我就閃人。", completion = "太好了，你找到我的東西了!準備好，諾姆瑞根的美人們，菲利克斯來了!\n\n那麼，哪條路可以讓我離開這裡...", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3362] = {title = "灌木谷", objective = "加基森的特蘭雷克要你殺掉8隻長瘤的灌木獸和8隻灌木塑根者。", description = "你有沒有去過灌木谷?那是個非常危險的地方，<name>。\n\n那裡到處都是奇怪的野獸，我根本不會冒險去靠近它們!那些野獸應該是被叫作長瘤的灌木獸和灌木塑根者...\n\n不管怎麼樣，我想要到那個山谷裡去看看，可是有那麼多的灌木獸在山谷裡活動，我可不想去送死。但是現在你來了─如果你能清除一些灌木獸的話，也許我就能去一趟了。我想你應該能幫忙吧，<name>?幫幫我，好不好?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3363] = {title = "被腐化的輕歌花", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['tw'][3364] = {title = "热酒快递", objective = "在5分钟内把热酒交给安威玛尔的德南·弗卡特。", description = "嘿！我之前应该把这可口的热酒交给安威玛尔的德南·弗卡特，现在我终于想起来该把东西送过去了！但是我肯定没法在酒变凉之前把酒送给他！\n\n你看起来挺灵敏的，也许你能……这杯热酒只能保温5分钟，而且德南要的可不是冰镇热酒，所以你一定要赶快！安威玛尔就在这里的东北面，那个在山壁上凿出来的大洞里。\n\n不要忘了把我的杯子带回来！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3366] = {title = "发光的碎片", objective = "寻找更多有关这块噩梦碎片的信息。", description = "这块碎片透出异样的绿色光芒，虽然它完全是一块固体，但是却让人感觉好像有一股烟从碎片中冒出来。你情不自禁地注视着这块水晶的深处，这时你突然觉得这其中必定包含着许多曲折的故事。\n\n也许你应该去棘齿城看看那里有没有人知道这块碎片的来历。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3367] = {title = "苏塔拉之石", objective = "帮助杜里奥斯回到铁炉堡。", description = "<杜里奥斯痛苦地呻吟着。>\n\n我受了重伤，<class>。我感觉……头重脚轻……世界在旋转……身体里面在出血。\n\n我必须回到铁炉堡，帮帮我，<name>……完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3368] = {title = "苏塔拉之石", objective = "把烧焦的信件交给铁炉堡的索里奥斯，他在探险者大厅里。", description = "我的好兄弟：\n\n如果你读到了这封信，那我已经不在这个世界上了。至于这封信是怎样到你手中的，我就不得而知了。 \n\n关于那些石头：它们确实存在，而且在黑铁矮人手里。他们的领袖，黑衣拉索里克正在使用石头的力量来禁锢我们勘探队的同伴。他们被带到了大熔炉那里。他们的意志已经被扭曲，被迫不分昼夜地干活以完成一个名叫奥比斯顿的东西。\n\n帮帮他们，我的兄弟。这是一个死者最后的希望了。\n\n——杜里奥斯您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][3371] = {title = "矮人的正义", objective = "回到灼热峡谷，找到杜里奥斯的考古队员。我的心已被悲痛腐蚀，变成了一个空虚的黑洞，<name>。杜里奥斯的逝去让我一时之间无法恢复。我必须让他的心愿得以实现——那个冷血的凶手必须得到正义的惩罚。\n\n回到灼热峡谷去，达成他最后的心愿——解放他的同伴。黑铁矮人强迫他们的奴隶在一处被称为熔渣之池的矿洞中工作，去那里寻找杜里奥斯的同伴吧。完成任務後，你將獲得：\n\n", description = "我的心已被悲痛腐蚀，变成了一个空虚的黑洞，<name>。杜里奥斯的逝去让我一时之间无法恢复。我必须让他的心愿得以实现——那个冷血的凶手必须得到正义的惩罚。\n\n回到灼热峡谷去，达成他最后的心愿——解放他的同伴。黑铁矮人强迫他们的奴隶在一处被称为熔渣之池的矿洞中工作，去那里寻找杜里奥斯的同伴吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3372] = {title = "释放他们", objective = "到北方去找到被暮光之锤守卫着的神秘的古器，然后把它带到熔渣之池的苏塔纳祭坛上。", description = "释放他们，<class>。即使他们的肉体已经不复存在，苏塔拉的力量也会让他们去完成自己的使命。\n\n苏塔拉祭坛是关键。到这里的北边去，在洞穴上面的山顶……暮光之锤守卫着一件古器。拿到它，把它放在苏塔拉祭坛上。\n\n<濒死的考古学家倒下了。>完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3373] = {title = "伊兰尼库斯精华", objective = "把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。", description = "当你接触宝石的时候，一个雄浑的声音回响在你的脑际。\n\n“凡人，请聆听我的请求。我是绿龙军团的伊兰尼库斯，这座被诅咒的神庙的守护者。我的任务是阻止这些巨魔召唤出上古的邪神，但是现在看来，我失败了。我把我的精华力量注入了这块宝石中，我能感到自己对梦境的控制正在陷入混乱。请你帮帮我——把这块宝石放入我的巢穴中，让那里的魔法净化我心智中的污点，那样我才能够安息。”您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n被禁錮的伊蘭尼庫斯精華"}
MultiLanguageQuestData['tw'][3374] = {title = "伊兰尼库斯精华", objective = "把伊瑟拉巨龙军团的誓言石和被禁锢的伊兰尼库斯精华交给悲伤沼泽的伊萨里奥斯。在那里你可以决定是否要帮助伊瑟拉的绿龙军团。", description = "你碰触了一下誓言石，伊萨里奥斯的声音通过这块石头直接和你进行对话。\n\n“一旦你拿起誓言石，就表示你会帮助我，并且准备帮助伊瑟拉的绿龙拯救伊兰尼库斯的灵魂。我们所要做的第一件事情，就是将禁锢着伊兰尼库斯自由心智的宝石交给我。”\n\n“快一点吧，<name>，我们要共同努力来拯救一个值得拯救的灵魂。”完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3376] = {title = "刺鬃酋长", objective = "把刺鬃酋长的徽记交给红云台地的卫兵维萨罗·风羽。", description = "<name>，我听说过你的名字，也许你可以帮助我们一个忙。\n\n我们牛头人在这块土地上建立了自己的家园，但是我们也付出了巨大的代价。刺刃峡谷中有一座刺背野猪人的村庄，在他们的首领——刺鬃酋长的带领下，野猪人一直在与我们交战，这让我们的生活变得非常艰难。我要你去取回刺鬃酋长的徽记！\n\n你可以在东边的峡谷中找到他们那简陋的村庄，刺鬃酋长就在村子里面。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "彩色鎧甲護腿遊牧手套漫行者纏手"}
MultiLanguageQuestData['tw'][3377] = {title = "艾露恩祷言", objective = "听萨麦尔讲述他的故事。", description = "你愿意帮我的忙吗？无论怎样，请先听听我的故事吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3378] = {title = "艾露恩祷言", objective = "找到艾露恩祷言，然后将其交给达纳苏斯的阿斯塔利·逐星。", description = "你愿意帮我的忙吗？你能找到艾露恩祷言吗？\n\n就如我所说的，祷言被刻在一块金色的石板上，那些崇拜它的恶棍把它占为己有。\n\n如果你能够找回我的祷言，就把它交给达纳苏斯的阿斯塔利·逐星。如此我才能在遭受如此多不幸之后重新恢复信心，而且更加重要的是，我的祈祷能够有人听见，至于我是否能被宽恕，我根本不关心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "凱拉雷護肩符文鋼質護臂您會收到：\n\n"}
MultiLanguageQuestData['tw'][3380] = {title = "沉沒的神廟", objective = "到塔納利斯找到瑪爾馮·瑞文斯克。", description = "世界上到處都是不肯安息的靈魂，<name>。有些靈魂因為孤獨而被腐化，繼而和一個上古的邪惡力量聯結了起來...\n\n我聽說有一個地下的神廟，那裡遊蕩著我從未見過而極其強大的力量。\n\n如果你想要對這個被稱作失落神廟的地方有更多瞭解的話，就去找一個名叫瑪爾馮·瑞文斯克的哥布林吧。他曾經研究過許多古代遺跡，我最後一次聽到他的消息時，他正從棘齒城出發去塔納利斯沙漠研究食人妖的遺跡。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3381] = {title = "会见主人", objective = "如果你想要见到萨纳斯的主人，就把2根完好无损的角鹰兽羽毛交给他。", description = "啊，一个年轻的<race>来到了萨纳斯的面前。多么美妙的一天啊！您的大驾光临令我诚惶诚恐。谢谢您！\n\n啊……请不要傲慢地把这些赞美之词真的当作一种恭维。让我们有话直说了吧：我不喜欢你。但是我们之间的关系如何并不重要——重要的是我的主人怎么看待你。\n\n给我带来一些角鹰兽的羽毛，我就向他引荐你。他曾吩咐我带那些有价值的旅行者去见他。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][3382] = {title = "危难中的船长", objective = "帮助瓦妮莎·贝蒂斯船长、她的船员和地平线轻帆号上的乘客抵御纳迦的攻击。瓦妮莎·贝蒂斯船长必须存活。", description = "当时我们正在找一个安全的港口下锚，但是日落还不到一个小时，他们就突然发起了攻击……那些该死的纳迦！\n\n我不知道他们在找什么，但是他们显然是没找到他们要的东西——纳迦们已经回来过一次了。我的侦查兵在山谷的入口守着，以便在他们下次发动攻击的时候及时通报我们。\n\n很抱歉把你卷了进来，<name>，但是现在的情况已经不在我的掌控之中了。\n\n你做好战斗的准备了吗？", progress = nil, completion = nil, rewards = nil}
