MultiLanguageQuestData['tw'][4117] = {title = "被腐化的鞭根草", objective = "You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['tw'][4118] = {title = "被腐化的輕歌花", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4119] = {title = "被腐化的夜龍草", objective = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['tw'][4120] = {title = "堕落的力量", objective = "菲拉斯莫沙彻营地的塔罗·刺蹄要你去费伍德森林杀掉12头怒爪灰熊和12头魔爪掠夺者。", description = "作为猎人，我总是努力来模仿我对手的长处。知己知彼，百战不殆，<name>\n\n在灰谷北部的费伍德森林中生活的野兽们都被恶魔的能量所感染，熊和狼都已经变得疯狂，而且我相信它们的力量也变得更加强大了。\n\n出发吧，<name>。去费伍德森林面对那些野兽。如果你和我想象中的一样强大，就去那里锻炼自己吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4123] = {title = "山脉之心", objective = "把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。", description = "多年以来，我都在追寻一块特殊的宝石。它的名字是山脉之心，个头大概和你的拳头差不多！黑铁矮人把它锁在他们的一个房间里，虽然我想尽了办法，但他们就是不卖给我。\n\n所以我只好诉诸暴力了。\n\n到黑石深渊底部的宝库里去，击败那里的守卫，把山脉之心给我抢出来。你所要做的就是击败卫兵杜格瑞普，不过只有在你打开房间里所有的保险箱之后他才会出现！\n\n祝你好运。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4124] = {title = "失踪的信使", objective = "和羽月要塞的基恩诺·火花谈一谈。我的同事基恩诺·火花正在寻找信使的下落，以及他身上携带的包裹。那个信使已经失踪一个星期了，我们所有的搜寻行动都徒劳而返，因此现在我不得不宣布：信使已经失踪了。\n\n如果你有时间的话，请去跟基恩诺谈谈。他应该在要塞里——也许在他自己的房间里。完成任務後，你將獲得：\n\n", description = "我的同事基恩诺·火花正在寻找信使的下落，以及他身上携带的包裹。那个信使已经失踪一个星期了，我们所有的搜寻行动都徒劳而返，因此现在我不得不宣布：信使已经失踪了。\n\n如果你有时间的话，请去跟基恩诺谈谈。他应该在要塞里——也许在他自己的房间里。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4125] = {title = "失踪的信使", objective = "找到信使的小船，你应该在菲拉斯的南部海岸线上展开搜索。", description = "拉斯卡尔这个信使出发去萨兰纳尔已经快一个星期了。他对菲拉斯了如指掌，自从羽月将军率领远征军踏上这片土地的时候，他就和我们在一起了。我知道他这次是想要划船沿着海岸前进，然后横穿菲拉斯的南部区域以避开部落的营地。\n\n我找不到他的船，但是也许你可以。也许那艘船被藏起来了，也许它已经沉没了。不管怎么样，只要找到船，就有可能找到他的线索。如果你找到什么东西的话，请赶快告诉我。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4126] = {title = "霍尔雷·黑须", objective = "把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。", description = "在万恶的霍尔雷·黑须的带领下，那些黑铁矮人偷了我们的雷霆啤酒的配方，那些混蛋！他们不配得到如此美味的佳酿！\n\n<name>，我有个艰巨的任务要交给你。去燃烧平原的黑石深渊，摧毁找到的所有装有雷霆啤酒的桶，然后把雷霆啤酒的配方带回来！\n\n求求你了，你一定要把配方带回来，即使要把黑石深渊翻个底朝天你也一定要找到它。您會收到：\n\n", progress = nil, completion = nil, rewards = "迅擊鬥棍截肢斬斧您會收到：\n\n矮人黑啤酒"}
MultiLanguageQuestData['tw'][4127] = {title = "船只的残骸", objective = "回到羽月要塞，给基恩诺·火花看看你找到的这把被丢弃的小刀。", description = "你的手沿着泥浆滑过，手指碰到了一把刀柄。它看起来护理得不错，而且肯定是曾经乘坐过这艘船的人把它给弄丢了。这可能和失踪的信使有关。\n\n你抓住这把刀，想起羽月要塞的基恩诺·火花要你把任何能找到的线索都报告给他。然而，你有一种感觉，在水中并不是只有你一个人……完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4128] = {title = "拉格纳·雷酒", objective = "和拉格纳·雷酒谈一谈。你好，<name>。我听说拉格纳·雷酒正因为有人偷了他的酒而大发雷霆呢。他在找合适的冒险者来帮忙，而且报酬丰富。\n\n如果你感兴趣的话就去找拉格纳谈谈吧，他在丹莫罗，卡拉诺斯的雷酒酿制厂里。完成任務後，你將獲得：\n\n", description = "你好，<name>。我听说拉格纳·雷酒正因为有人偷了他的酒而大发雷霆呢。他在找合适的冒险者来帮忙，而且报酬丰富。\n\n如果你感兴趣的话就去找拉格纳谈谈吧，他在丹莫罗，卡拉诺斯的雷酒酿制厂里。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4129] = {title = "奎恩提斯的技艺", objective = "把被丢弃的小刀交给羽月要塞的奎恩提斯。", description = "要塞里有一个名叫奎恩提斯的德鲁伊，他有一些……非同寻常的技艺，比如心灵占卜术——通过触摸某件物品揭示与其关联的历史。不要问我他是怎么做到的，我认为那是一种我不懂也不愿去弄懂的魔法。然而我确实知道两件事：首先，那把戏的效果确实不错；其次，他还欠着我的债。\n\n把小刀交给小树屋里的奎恩提斯，替我告诉他……如果他把他的本事用在那把刀子上的话，他跟我打牌时欠下的债务就一笔勾销。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4130] = {title = "心灵占卜术", objective = "和羽月要塞的基恩诺·火花谈一谈。我仍然有些晕，不好意思。嗯，我看到了一些有用的图像。\n\n拉斯卡尔从小船里拿了两只皮袋子，然后上了岸；然而，他又回到了小船那里。我看到了豺狼人……他遇到了豺狼人——那些被称作木爪豺狼人的家伙。他看起来很着急——看上去有些恐惧——似乎是在躲避什么。他甚至没有注意到身后的水元素……就是这些了。\n\n我得休息一下，对不起，<name>。把我看到的东西告诉基恩诺，他需要知道这些。完成任務後，你將獲得：\n\n", description = "我仍然有些晕，不好意思。嗯，我看到了一些有用的图像。\n\n拉斯卡尔从小船里拿了两只皮袋子，然后上了岸；然而，他又回到了小船那里。我看到了豺狼人……他遇到了豺狼人——那些被称作木爪豺狼人的家伙。他看起来很着急——看上去有些恐惧——似乎是在躲避什么。他甚至没有注意到身后的水元素……就是这些了。\n\n我得休息一下，对不起，<name>。把我看到的东西告诉基恩诺，他需要知道这些。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4131] = {title = "木爪豺狼人", objective = "在菲拉斯南部地區的木爪豺狼人營地裡尋找信差的下落或者信差的物品。拉斯卡爾也許是被我們的那些豺狼人「朋友」抓去了，雖然直覺告訴我事情並不是這樣的。但是你最好還是從它們那裡開始搜索。\n\n我希望我知道該幹什麼，我現在能說的只有「去搜索木爪豺狼人的營地，現在就出發。」我知道豺狼人會把他們搶到的東西藏起來，而且為何這些東西互相爭鬥。也許是它們搶了奎恩提斯所說的包裹。我在搜索過程中沒有去跟豺狼人作戰，不過既然奎恩提斯有這種預感，我們就必須採取行動了。完成任務後，你將獲得：\n\n", description = "拉斯卡爾也許是被我們的那些豺狼人「朋友」抓去了，雖然直覺告訴我事情並不是這樣的。但是你最好還是從它們那裡開始搜索。\n\n我希望我知道該幹什麼，我現在能說的只有「去搜索木爪豺狼人的營地，現在就出發。」我知道豺狼人會把他們搶到的東西藏起來，而且為何這些東西互相爭鬥。也許是它們搶了奎恩提斯所說的包裹。我在搜索過程中沒有去跟豺狼人作戰，不過既然奎恩提斯有這種預感，我們就必須採取行動了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4133] = {title = "薇薇安·拉格雷", objective = "与卡加斯的暗法师薇薇安·拉格雷谈一谈。暗法师薇薇安·拉格雷需要你的帮助。她在荒芜之地，就在兽人的卡加斯前哨基地里，她在那里对有关黑铁矮人的事情进行调查。\n\n去和薇薇安谈谈吧，她正在等着你。完成任務後，你將獲得：\n\n", description = "暗法师薇薇安·拉格雷需要你的帮助。她在荒芜之地，就在兽人的卡加斯前哨基地里，她在那里对有关黑铁矮人的事情进行调查。\n\n去和薇薇安谈谈吧，她正在等着你。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4134] = {title = "遗失的雷酒秘方", objective = "把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。", description = "有传言说黑铁矮人霍尔雷·黑须偷到了一种酒的配方。这种被称作雷霆啤酒的饮料会使饮用者获得无穷的力量和勇气。我们希望能研究一下这种饮料。也许我们可以开发它的其它功能……能够帮助我们被遗忘者达成目标的功能。\n\n我说了被遗忘者的目标？我的意思是……整个部落的目标，我当然是这个意思！\n\n到黑石深渊去找到雷霆啤酒的配方，把它给我带回来。您會收到：\n\n", progress = nil, completion = nil, rewards = "迅擊鬥棍截肢斬斧您會收到：\n\n超強治療藥水強效法力藥水"}
MultiLanguageQuestData['tw'][4135] = {title = "痛苦深渊", objective = "现在你已经知道了拉斯卡尔的去向，那么你最好到痛苦深渊去寻找他，或者至少是他的尸体。根据便笺上的信息，那个地方应该在木爪豺狼人营地的南边。\n\n已提供物品：\n", description = "在背包中有两样东西：第一件是要送到萨兰纳尔去的包裹，第二件是匆忙书写的便笺。\n\n便笺上面写着在豺狼人营地南边有一处被称作痛苦深渊的地方，那里有许多邪恶的虫类生物。作者认为他应该亲自去调查一番，因为他觉得那是对整个菲拉斯的威胁。便笺的末尾署了名，“羽月要塞的拉斯卡尔”。\n\n看来你最终找到了拉斯卡尔的下落。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4136] = {title = "雷布里·斯库比格特", objective = "把雷布里的徽记交给燃烧平原的尤卡·斯库比格特。", description = "我的兄弟雷布里就是我们家族的耻辱，他拿走了我们所有的钱，然后挥霍一空。\n\n藏宝海湾的大财主里维加兹刚刚开始悬赏雷布里的徽记，这对他来说可能有些糟糕，但我简直无法形容斯库比格特家族在得知这个消息之后有多高兴了！我们的小雷布里终于有点价值了！\n\n但是现在他躲在黑石深渊的深处。请你帮忙找到他，然后把他带到我这里来！\n\n如果他不愿意来的话，那么也好……至少把他的徽记给我带来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "怨恨長靴懺悔肩甲鋼條護甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][4141] = {title = "莫爾金和拉里安", objective = "收集15朵血瓣花，然後回覆給莫爾金。", description = "看見那裡的拉里安了嗎?就是他的錯導致我們不得不待在這裡!\n\n我告訴過他我們走錯路了，但是他會聽我的嗎?你能相信他居然不和我說話嗎?好吧，除非他改變主意，否則我們就準備看場好戲吧。\n\n你注意到周圍那些像植物一樣的生物了嗎?它們確實很麻煩，但是我認為只要經過正確的訓練，我就可以讓它們聽命於我。\n\n首先，我需要一些樣品來進行研究。你可不可以幫我收集一些呢?完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4142] = {title = "造访格雷甘", objective = "把血瓣花交给菲拉斯的格雷甘·山酒。", description = "我不能完全确定这是由什么构成的，<name>。这些植物……好像具有一些最简单的智能。\n\n虽然我并不是这方面的专家。但是我知道有人一定知道答案！\n\n到菲拉斯去找我的一个名叫格雷甘·山酒的朋友，他是这方面的专家。\n\n我敢肯定格雷甘能帮我们，你应该可以在菲拉斯的野外找到他，他可不是那种喜欢生活在大城市里的家伙。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4143] = {title = "邪恶之雾", objective = "收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。", description = "我跟你说实话吧，<name>，在我的旅途生涯中，我从来没有看见过这样的植物。也许我应该去一下环形山……\n\n不管怎么样，我想我知道穆尔金正在找什么东西——阿塔莱之雾。那是种恐怖的东西，而且非常难找，但是穆尔金需要这种材料来控制那些小怪兽。\n\n你应该去悲伤沼泽里的那座沉没的神庙，那里的潜伏者、黑暗虫和泥浆怪身上都有阿塔莱之雾。祝你好运，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4144] = {title = "血瓣花苗", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4145] = {title = "拉瑞安和穆尔金", objective = "为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者和5个血瓣花捕兽者。", description = "看到那边的穆尔金了吗？就是他的错使我们迷路了！\n\n我知道正确的路，但是他坚持说他知道一条捷径，然后我们就到了这里！\n\n更糟的是，现在他还不断用他那些疯狂的植物来烦我。我很生气，所以我原本打算不和他说话了，但是这些该死的植物实在是太多，我没有足够的能力来清除它们。\n\n那么，首先让我们来减少这些东西的数量吧，去帮我干掉一些血瓣花鞭笞者和血瓣花捕兽者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4161] = {title = "卡多雷的菜谱", objective = "为多兰纳尔的扎瑞恩收集7条小蜘蛛腿。", description = "很久以前，暗夜精灵被称作卡多雷，卡多雷的意思是“众星之子”。了解这些历史对帮助你成为一名真正的<class>非常重要，<name>，所以好好聆听我告诉你的故事吧。\n\n卡多雷总是以自己和环境之间的和谐关系而感到自豪，这意味着我只向自然索取生活必需的东西，并且要给自然以友善的回报。这种平衡使我们受益良多，<name>。\n\n去帮我收集几条小蜘蛛腿，然后回来找我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n食譜：卡多雷蜘蛛烤肉卡多雷蜘蛛烤肉"}
MultiLanguageQuestData['tw'][4181] = {title = "地精工程学", objective = "如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。", description = "高级的工程学有两个分支：侏儒派和地精派，请注意我提到地精工程学的唯一原因是因为我是个公正的训练师。他们喜欢制造一些会爆炸的东西，而且丝毫不关心有什么东西会被炸到——即使是他们自己。\n\n好吧，<name>，读一下这本手册。如果你想要学习把自己炸上天的方法，就把这个交给加基森的尼克斯·斯普克斯宾。请记住，一旦你加入某一派，就永远也不能再加入另一派了，所以在你完成他交给你的任务之前要三思。", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well &lt;name&gt;, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked &lt;name&gt;, and you might learn something.", rewards = nil}
MultiLanguageQuestData['tw'][4182] = {title = "黑龙的威胁", objective = "杀掉15条黑色小龙、10条黑色龙人、4条黑色龙族和1条黑色幼龙。", description = "燃烧平原上永远充满了争端。\n\n看看这个地方！我们不知道这些建筑到底是怎么回事，但是我们会永远记住，在大爆炸之前，这些地方原本都是属于赤脊山范围的。\n\n现在的情况真是太糟糕了！我们碰到了一个问题，<name>。你也许已经注意到在这道山脊下徘徊的那些龙了。杀了它们，越多越好。去完成这个任务，然后我们再来谈谈别的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4183] = {title = "真正的主人", objective = "把赫林迪斯·河角的信交给赤脊山湖畔镇的所罗门镇长。", description = "我们以前总是认为黑石兽人的残忍是与生俱来的。不过我们在这里找到的东西却告诉我们另一个故事。\n\n没错，嗜血和对战斗的饥渴使他们变成了如今的样子，但是这一切的幕后主使却是那些黑龙。我们认为，正是黑龙把愤怒和敌意灌输给了他们。\n\n把这封信交给所罗门镇长，他会知道该做什么的。\n\n<赫林迪斯把一封信交给了你。>完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4184] = {title = "真正的主人", objective = "到暴风城去把所罗门的求援信交给瓦里安·乌瑞恩国王。\n\n瓦里安·乌瑞恩国王在暴风要塞里。", description = "这真是个可怕的消息，<name>。我们的敌人竟然只是一个更强大的势力的爪牙，这让我感到更加气馁。湖畔镇不可能抵抗黑石兽人和黑龙的联手攻击。如果湖畔镇陷落了，那么下一个就是夜色镇，接下来会是哪里？闪金镇？暴风城？\n\n你必须把这个消息告诉瓦里安·乌瑞恩国王！如果暴风城不施以援手的话，那么一切就都完了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4185] = {title = "真正的主人", objective = "与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。", description = "所罗门描绘了一幅恐怖的画面，但是我们不可能把原本就已经捉襟见肘的兵力再分派一部分去湖畔镇。我需要确凿的证据才能采取行动。\n\n和女伯爵卡特拉娜·普瑞斯托谈谈吧，<name>。她是个学识渊博的女性，并且对龙类生物很有了解。她应该可以在这件事情上帮助我们。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4186] = {title = "真正的主人", objective = "把乌瑞恩的命令交给湖畔镇的所罗门镇长。", description = "我现在任命你为暴风城执行代表，<name>。\n\n回到湖畔镇的所罗门镇长那里，向他传达这份命令。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4201] = {title = "爱情药水", objective = "将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。", description = "啊，爱情的痛苦！我亲爱的罗克诺特下士对我的魅力不来电，他将我无情地拒绝了！这真是令我发狂！\n\n你必须帮帮我！我们魅魔对于爱情了如指掌，所以我可以配制一种药水，用它来融化包围着罗克诺特心脏的铁墙。不过我需要一些材料才能配置这种药水——一种被称作格罗姆之血的药草，一块从艾萨拉的悬崖巨人那里得到的巨大银矿，还有从安戈洛的温泉中取得的水。你可以把水放在这个小瓶里。\n\n<name>，请帮助一个可怜的灵魂追求她的快乐吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "娜瑪拉的腰帶鐐銬腕輪您會收到：\n\n"}
MultiLanguageQuestData['tw'][4221] = {title = "被腐化的迎風花", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4222] = {title = "被腐化的迎風花", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4223] = {title = "真正的主人", objective = "和燃烧平原的麦克斯韦尔元帅谈一谈。<所罗门镇长叹着气。>\n\n你必须回到燃烧平原去，<name>。作为暴风城的代表，你现在应该去向麦克斯韦尔元帅报告。祝你好运。完成任務後，你將獲得：\n\n", description = "<所罗门镇长叹着气。>\n\n你必须回到燃烧平原去，<name>。作为暴风城的代表，你现在应该去向麦克斯韦尔元帅报告。祝你好运。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4224] = {title = "真正的主人", objective = "和狼狈不堪的约翰。", description = "什么？你以为你是第一个被派来这里的？我们到底要损失多少士兵，暴风城才会下决心采取行动？\n\n对于黑石兽人可能造成的威胁，我们已经有了充足的证据，但是在指挥官温德索尔元帅被俘虏之后，我们损失了许多宝贵的情报。\n\n我们需要的是那份文件。去跟约翰谈谈吧，<name>。他当时和温德索尔一起遇到了黑石氏族的袭击，现在他正在北边的一个洞穴里休息。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4241] = {title = "温德索尔元帅", objective = "到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。\n\n狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。这么说来，那个没用的废物说温德索尔还活着，是吗？\n\n做好准备，士兵，你必须去找到他。如果温德索尔还活着的话，你就把他带回来。如果他死了，那我就要你拿出他已经死亡的证据。\n\n<麦克斯韦尔大笑着。>\n\n我打赌你已经厌倦听到这样的命令了，是不是？完成任務後，你將獲得：\n\n", description = "这么说来，那个没用的废物说温德索尔还活着，是吗？\n\n做好准备，士兵，你必须去找到他。如果温德索尔还活着的话，你就把他带回来。如果他死了，那我就要你拿出他已经死亡的证据。\n\n<麦克斯韦尔大笑着。>\n\n我打赌你已经厌倦听到这样的命令了，是不是？完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4242] = {title = "被遗弃的希望", objective = "前往燃烧平原，摩根的岗哨。把这个坏消息传达给麦克斯韦尔元帅。伯瓦尔是个笨蛋。我一直以来都在收集有关他的“证据”，要将他彻底打败。\n\n他是个没脑子的小丑，证据在他面前堆了足有两英尺高而他却视而不见。\n\n如果我能找到铁仇之锤并且走出这个该死的迷宫，那我要做的第一件事就是去暴风城，把那个卑鄙的家伙一劈为二。\n\n离我远点，<name>。完成任務後，你將獲得：\n\n", description = "伯瓦尔是个笨蛋。我一直以来都在收集有关他的“证据”，要将他彻底打败。\n\n他是个没脑子的小丑，证据在他面前堆了足有两英尺高而他却视而不见。\n\n如果我能找到铁仇之锤并且走出这个该死的迷宫，那我要做的第一件事就是去暴风城，把那个卑鄙的家伙一劈为二。\n\n离我远点，<name>。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "監督官頭盔盾鎧脛甲風剪護腿"}
MultiLanguageQuestData['tw'][4243] = {title = "找回艾米 01", objective = "在安戈洛環形山找到艾米 01。", description = "非常不幸，我的一項最偉大的發明出了點問題。你以前見過機械松鼠，對嗎?嗯，為了接近安戈洛環形山的猿猴，我製造了一隻機械猿猴混入它們的群落─我把她稱為艾米 01。\n\n她的水晶眼珠上附有特殊的魔法，因此我能看見她所看見的一切。不過，在她到了北邊的蘑菇石─也就是那群猿猴的巢穴裡面之後，我便與她失去了聯繫。我最後看到她的時候，猿群中有一隻雄猿正衝上前去想和她打招呼!\n\n你能幫我找到她嗎?完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4244] = {title = "找回A-Me 01", objective = "找到一个秘银外壳，然后回到安戈洛环形山的A-Me 01身边。", description = "你仔细看了看,发现有一块面板被打开了。在配线下面清楚地写着一行字，“更换秘银外壳，关闭电源之后再重新打开。”\n\n更换面板之后，你不禁觉得没理由这么容易就能修好A-Me 01，并让她回到马绍尔营地附近的卡尔纳·雷塔维身边。\n\n只有先试试看了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4245] = {title = "找回A-Me 01", objective = "将A-Me 01交给安戈洛环形山的卡尔纳·雷塔维。", description = "在看了看周围的情况是否允许你把A-Me 01带回卡尔纳·雷塔维身边之后，你将开关扳到了“关闭”位置。你有看了看周围，确信没有某只猩猩朝你冲过来，然后将开关扳到“打开”。\n\n这是你最后的机会了……你确定要这样做吗？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4261] = {title = "远古之灵", objective = "护送艾雷脱离危险，然后和灰谷东部的林歌神殿中的凯尼斯·静风谈一谈。", description = "费伍德森林曾经是个和平安详的地方……直到燃烧军团占据了这里。恶魔、毁灭和混乱接踵而来……\n\n古尔丹之颅让这里的所有生物无一幸免地全都堕落了。\n\n直到现在，我还是身陷其中，不得不忍受这片土地所遭受的痛苦。请帮我找到回家的路吧，<name>，告诉我你愿意带领一个古树之灵离开这里，让我得到最终的安息。\n\n在我获得自由之后，就请去找住在林歌神殿的德鲁伊凯尼斯·静风。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "靈霧斗篷雲谷披肩"}
MultiLanguageQuestData['tw'][4262] = {title = "征服者派隆", objective = "杀掉征服者派隆。\n\n加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。", description = "前五个试图进入黑石深渊的法师几乎个个都灰头土脸地回来了，有的情况还要更糟糕。\n\n<加琳达从地上抓了一把灰尘洒向天空。>\n\n造成这种情况的主要原因是有一个可恶的臭虫——征服者派隆给我们带来了很多麻烦。我们必须干掉这个元素生物，然后才能顺利地进入黑石深渊！\n\n他就守在黑石采矿场的黑石深渊入口处。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4263] = {title = "伊森迪奥斯！", objective = "在黑石深渊里找到伊森迪奥斯，然后把他干掉！", description = "你确定派隆临死之前喊出了“伊森迪奥斯”这个词？\n\n<加琳达使劲咽了口唾沫。>\n\n传说伊森迪奥斯是拉格纳罗斯的手下！哦，我的天啊，我的天啊……我们该怎么办啊？\n\n你认为你能再去完成一个任务吗？我现在手头没有足够的人手了，<name>！\n\n如果伊森迪奥斯不断复活派隆的话，那我们的队伍永远也不要想进去了。\n\n你必须找到伊森迪奥斯，把他干掉！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "地穴惡魔護腕陽焰斗篷夜暮手套堅實之攫您會收到：\n\n"}
MultiLanguageQuestData['tw'][4264] = {title = "弄皱的便笺", objective = "温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。", description = "这份便笺上满是污渍，上面的文字已经模糊不清了，但是还是能看出个大概来：\n\n……甜蜜的讽刺……\n\n……联盟的分崩离析……\n\n……如果不是因为安格弗将军的努力工作，也许我们至今还找不到译码的方法……\n\n……阿格曼奇已经差不多可以完成温德索尔便笺的破译了。\n\n我们的主人将从深渊中归来，摧毁所有剩余的东西……\n\n- 达格兰·索瑞森大帝。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4281] = {title = "萨兰纳尔的货物", objective = "将未递送的包裹交给萨兰纳尔驿站的法芬德尔。", description = "你在木爪豺狼人营地里发现的这包货物应该是送往菲拉斯东南部的萨兰纳尔驿站的。不管那个失踪的信使命运如何，递送包裹的任务显然是没有完成。\n\n你仔细地检查包裹，发现在外包装上有手写的“法芬德尔”字样，也许这就是包裹接收人的名字。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4282] = {title = "一丝希望", objective = "找回温德索尔元帅遗失的情报。\n\n温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。", description = "<温德索尔元帅激动地抖着手里的信。>\n\n你知道这意味着什么吗，<name>？\n\n也许他们还没有得到所有的东西！我可以确定的是，现在有两个黑铁矮人——安格弗将军和傀儡统帅阿格曼奇——正在破解我的那些情报。我相信我们是不大可能很顺利地取回我的那封信的。\n\n希望你已经做好了战斗准备。\n\n去找到那两个恶棍！干掉他们，然后带回我遗失的情报。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4283] = {title = "五十个！", objective = "收集50枚黑石徽章。", description = "我要告诉你个小秘密，士兵。走近一些。\n\n我是这里唯一正常的人！\n\n看看我周围的那些家伙！你相信他们都不正常吗？事实上他们都不正常！他们都疯了！疯了！\n\n<奥拉留斯放低了声音。>\n\n这是个秘密，不要告诉别人，只有你，我，还有我的那个军官伙计知道。\n\n<奥拉留斯紧握拳头。>\n\n不管怎么样……我在收集食人魔耳朵的同时也收集徽章，就是那些兽人身上的徽章。给我弄五十枚徽章来，现在就出发！\n\n<奥拉留斯双手拢在嘴边作喇叭状。>\n\n快去拿到那些徽章！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4284] = {title = "能量水晶", objective = "收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。", description = "我确定你一定已经注意过它们了，<name>。它们到处都是！\n\n我在说什么？这都不知道，我当然在说水晶！\n\n那些水晶……它们遍布在整个环形山里。大多数人都会忽视它们，但我感觉到那些水晶里一定蕴含着特殊的力量。我一直以来都在用它们进行实验，但似乎总是没有什么成果。好吧，我承认至今为止我一无所获。\n\n这么说吧，我这里的水晶已经不多了——我想你也许能够帮我收集一些水晶回来？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4285] = {title = "北部水晶塔", objective = "在安戈洛尔环形山找到北部水晶塔。", description = "那些到底是什么东西？我脑子里现在只有这个问题！\n\n它都快要把我逼疯了——我相信那些关于水晶塔的传言都是真的。随便你怎么说，但是我一般总是会相信别人告诉我的任何东西。\n\n不管怎么样，我听说有一座水晶塔就在北部很近的地方……请去找到它，<name>。我敢肯定它们确实存在。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4286] = {title = "好东西", objective = "收集20个黑铁挎包。", description = "温奇船长跟我说黑暗深渊里的黑铁矮人有很多好东西。对吧，温奇？\n\n<奥拉留斯努力扮演一名海盗。>\n\nB对！\n\n明白我所说的了吧？你到那里去，给我带回一些好东西来。\n\n到那儿去摇你的摇钱树吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n骯髒的霹靂包"}
MultiLanguageQuestData['tw'][4287] = {title = "东部水晶塔", objective = "在安戈洛尔环形山找到东部水晶塔。", description = "这段时间我听说了一些关于神秘的水晶塔的奇怪传言，据说它们就在环形山中，<name>。我猜它们的体积非常巨大，而且里面蕴含有珍贵的水晶。\n\n虽然我从来没有见过它们，但我却情不自禁地愿意去相信这些传言是真的——而且那些水晶塔有可能和我们找到的水晶有某种联系。\n\n请帮帮我，满足一下我的好奇心吧。也许在环形山的东部地区有一个水晶塔，你认为你可以找到它吗？完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4288] = {title = "西部水晶塔", objective = "在安戈洛尔环形山找到西部水晶塔。", description = "我的实验迄今为至没有取得任何实质性的进展，<name>。我真希望你能帮我去查看一下传说中的一座水晶塔。\n\n也许我们在那里组合特定颜色的水晶的话……嗯，这我会自己去做的。首先我们得找到那些水晶塔！\n\n<name>，去搜索一下环形山的西部区域；据说那里有个水晶塔。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4289] = {title = "安戈洛的猩猩", objective = "将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。", description = "这个环形山中居住着许多奇怪的生物——它们似乎比我家乡那边的生物更加高贵。我无法解释这一点，但是这块地方在呼唤大地之母。每次我看到大地之母创造的某种美丽的生物时，我都会对她肃然起敬。\n\n如果你也希望感觉到见证这伟大功绩的幸福感，就向北方出发吧。你将在那儿遇到巨大的猩猩，这对<race>的力量来说是一个挑战。把它们的皮毛交给我……证明你的力量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4290] = {title = "拉克维的食物", objective = "找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。", description = "很久以前，我的一个兄弟从拉克维的猎物身上拿了一些肉。他那时并不知道拉克维就潜伏在丛林中看着他。拉克维跟踪了我的兄弟好几天，毁灭了他碰过的一切。我的兄弟吓坏了，最终他决定从安戈洛逃走，彻底甩开拉克维。\n\n拉克维就在这附近杀死了他。\n\n如果你想激怒拉克维，就去寻找它刚刚杀死的猎物，并从尸体上取一些肉。\n\n做完这些之后，就回到我这儿来。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4291] = {title = "拉克维的气味", objective = "将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。", description = "它居然没有来攻击你，这让我感到很惊讶。但是不要紧，我有个计划可以让那头野兽出来。\n\n作为这块区域的领袖，拉克维有权与任何雌性暴掠龙交配——而且它确实这么做了。你可以在这里的西边找到许多暴掠龙蛋，靠近它们，这时就会有雌性暴掠龙跑出来攻击你。这些雌性暴掠龙头上有一种腺体，它所散发出的味道可以告诉雄性暴掠龙：它准备进行交配了。给我带两个这样的腺体回来。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4292] = {title = "拉克维的诱饵", objective = "使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的徽记交给安戈洛环形山入口处的托尔瓦·寻路者。", description = "计划有些复杂，因此这是最困难的部分。沿着山脚向北面走，你可以发现一条很不起眼的小道直通山中。那是我最后一次看到拉克维的地方。那里应该散落着大型野兽的残骸，所以你很容易判断自己的位置是否正确。带上这块肉，把它放在那儿。然后在肉上涂抹我配制的这种液体。如果这还不能使拉克维现身的话，我想也没什么东西能把它引诱出来了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "平原巡者外套先遣騎護腿"}
MultiLanguageQuestData['tw'][4293] = {title = "软泥怪的样本…", objective = "从费伍德的软泥怪身上收集费伍德软泥怪样本，然后使用幽暗城的化学家弗雷身旁的测试设备来检测你所收集的样本中哪一份被腐化的程度最深。给化学家弗雷带去5个被腐化的费伍德样本。", description = "费伍德是在贫瘠之地北边很远的地方的一片森林，比灰谷还要远。在那里的被恶魔污染的池水中到处都可以看到软泥怪，天灾军团的地狱火和其它恶魔法术曾经在这个地区肆虐过——软泥怪应该是在这段时间里从地底下冒出来的。\n\n从费伍德森林的软泥怪身上收集一些样本，然后我们就可以用我的测试仪器拿它们和其他样本作一下比较了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4294] = {title = "一大堆软泥怪", objective = "从安戈洛尔环形山那里任何泥浆怪身上收集安戈洛泥浆怪样本。使用幽暗城的化学家弗雷身旁的测试仪器来检验你所采集到的样本的纯度。把5份纯净的安戈洛样本送到化学家弗雷那里去。", description = "<name>，你听说过安戈洛环形山吗？它就在塔纳利斯沙漠附近，那里是个神奇的地方，到处都是郁郁葱葱的大树，还有大量的野生动物。 \n\n你必须到那里去一趟，我听说那块地方至今未至从未受到过外界的污染，探险者们正在逐渐揭开它的秘密。\n\n我想要对那里的软泥怪或者泥浆怪做一下测试，如果它们真的没有受到污染的话，那我真的想要看看这些生物是怎么进化的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4295] = {title = "羅克諾特的麥芽酒", objective = "哦，麥芽酒!為了黑鐵麥芽酒，我甚至願意去殺人!快點，我的酒勁正在消退!我的視線越來越模糊了...你看起來越來越像上個星期我幹掉的那個德萊尼了!", description = nil, progress = "哦，麥芽酒!為了黑鐵麥芽酒，我甚至願意去殺人!快點，我的酒勁正在消退!我的視線越來越模糊了...你看起來越來越像上個星期我幹掉的那個德萊尼了!", completion = "這是什麼?啊!聞上去就像黑鐵麥芽酒!麥芽酒讓我的視線變得有些模糊，不過我可以肯定地告訴你，女士，你是一個真正的朋友!", rewards = nil}
MultiLanguageQuestData['tw'][4296] = {title = "七贤石板", objective = "取得石板拓文。", description = "我追寻七贤的传说来到了燃烧平原，七贤是一群具有丰富知识和强大力量的矮人，你知道，一旦你有了这两样东西，那么财富必将接踵而来。我要的就是财富！\n\n如果我们能对七贤有更多了解，那我们就能一起发财了。据说索瑞森废墟里有一块七贤石板，上面刻有那些古代矮人所掌握的知识。找到那块石板，把上面的碑文拓下来给我，让我们共同揭开其中的秘密！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4299] = {title = "暂无内容", objective = "把PX83型密码机放在七英雄之墓里，然后向麦克斯沃特·尤博格林复命。", description = "找到七英雄之墓，然后把PX83型密码机放在那里。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4300] = {title = "骨刃武器", objective = "将8只白色暴掠龙爪交给奥格瑞玛的杰斯雷蒙。", description = "嗯，或许你能对碎手氏族有所帮助。没错，杰斯雷蒙肯定需要你的帮助。\n\n在安戈洛环形山生活着许多迅猛龙，它们的利爪是致命的武器。一些迅猛龙的爪子是白色的，还有一些是象征死亡的黑色。我们碎手氏族有些……顾客……他们需要由这些爪子制成的武器。给我带来一些白色的爪子，我会好好回报你的。如果你速度够快的话，也许我可以在其它方面帮助你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "白骨指環白骨切割者白骨長矛您會收到：\n\n"}
MultiLanguageQuestData['tw'][4301] = {title = "强大的尤尔查", objective = "把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。", description = "在你探索安戈洛的时候，我看到了一些像你这样强大的猎手可能会感兴趣的东西。其中之一就是北方的一只巨大的猩猩，它混迹在其它的猩猩中间。你去过那座猩猩洞穴，但这次，我怀疑你是否能在遭遇那只大猩猩之后活下来。\n\n我称他为尤尔查，他是大地母亲最强大的儿子之一，关于这一点你不用怀疑。打败尤尔查，把他的毛皮交给我。如果你能做到这一点，我就会捍卫你称自己为伟大猎手的权利。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "野獸粉碎者野獸斬殺者"}
MultiLanguageQuestData['tw'][4321] = {title = "分析水晶塔", objective = "过一会再和科琳说话。", description = "你带给我的有关这些水晶塔的信息很有趣……\n\n给我点时间，我要计算一下，<name>。过会再和我说话，我应该可以给你一些答复。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n水晶塔使用手冊"}
MultiLanguageQuestData['tw'][4322] = {title = "冲破牢笼！", objective = "帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。", description = "<name>，我们要离开这里。帮助我从补给区拿回我的装备，然后再去救我的朋友。如果我们能够活着逃出去的话，那就在麦克斯韦尔元帅的营地里碰面吧。\n\n我们可以在那里想办法来破译这条情报。如果没有我的译码戒指的话，这个工作可就不简单了。\n\n你准备好了吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "清算之刃作戰之刃您會收到：\n\n元素屏障"}
MultiLanguageQuestData['tw'][4323] = {title = "暂无内容", objective = "把7条Spotted hyena Pelts带给Freewind Post的TESTTAUREN。", description = "我需要一些Hyena Pelts，我只需要那些质量最好的！把spotted hyena pelts带给我，我会给你相应的报酬的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][4324] = {title = "尤卡·斯库比格特", objective = "与燃烧平原的尤卡·斯库比格特谈一谈。尽管我的弟弟雷布里一生都无所作为，但是我认为，最终他的生命还是有些价值的！然而……我们可能需要你的帮助来让雷布里发挥他最后的价值。\n\n我姐姐尤卡这段日子以来都在寻找他，而且跟踪他到了燃烧平原。她曾带话给我，要我雇些人给她帮忙。\n\n那么，你有兴趣吗？如果你想要试试的话，就去跟我姐姐说吧。她就住在巨槌石西北的称作烈焰洞里。", description = "尽管我的弟弟雷布里一生都无所作为，但是我认为，最终他的生命还是有些价值的！然而……我们可能需要你的帮助来让雷布里发挥他最后的价值。\n\n我姐姐尤卡这段日子以来都在寻找他，而且跟踪他到了燃烧平原。她曾带话给我，要我雇些人给她帮忙。\n\n那么，你有兴趣吗？如果你想要试试的话，就去跟我姐姐说吧。她就住在巨槌石西北的称作烈焰洞里。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4341] = {title = "卡兰·巨锤", objective = "去黑石深渊找到卡兰·巨锤。\n\n国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。你去过索瑞森废墟那个破地方没有？碰到过一个名叫卡兰·巨锤的可怜家伙没有？那个应该是正在看守我女儿的矮人！\n\n<国王抽泣着。>\n\n我已经派人把燃烧平原翻了个底朝天，现在唯一关于我女儿的线索就是她应该在黑石深渊里。有消息说她有可能已经死了！\n\n卡兰在黑石深渊中负责看守囚犯……找到他！我要知道我女儿的下落！完成任務後，你將獲得：\n\n", description = "你去过索瑞森废墟那个破地方没有？碰到过一个名叫卡兰·巨锤的可怜家伙没有？那个应该是正在看守我女儿的矮人！\n\n<国王抽泣着。>\n\n我已经派人把燃烧平原翻了个底朝天，现在唯一关于我女儿的线索就是她应该在黑石深渊里。有消息说她有可能已经死了！\n\n卡兰在黑石深渊中负责看守囚犯……找到他！我要知道我女儿的下落！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4342] = {title = "卡兰的故事", objective = "听卡兰·巨锤说他的故事。", description = "求求你，请先听我解释！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
