MultiLanguageQuestData['tw'][4447] = {title = "被腐化的夜龍草", objective = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['tw'][4448] = {title = "被腐化的夜龍草", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4449] = {title = "被锁起来的矮人", objective = "杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。", description = "嘿！嘿，你！过来！\n\n你要帮帮我。我正在逃避黑铁矮人的追击，我藏在这里，满以为他们就找不到我了。但那些可恶的混蛋还有魔法！他们肯定看到我藏了起来，他们很快就把门锁上，说了些什么过一阵子再回来之类的话，然后就离开了。\n\n你要给它们的颜色瞧瞧！给那些黑铁地质学家一个教训！哦……对了，你能不能给我弄几块丝绸来做……做……呃，没什么。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][4450] = {title = "塔纳利斯的账本", objective = "把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。", description = "哦，你猜怎么着？我想起了一件事情。\n\n我现在仍然被困在这里，那么你可以帮我完成一项我在塔纳利斯接受的任务吗？很简单……嗯，对于你来说是这样的。\n\n加基森的克林科·古德斯迪尔需要一些从灼热峡谷和其它地方收集的东西。也许你可以看一下清单，然后把东西交给他……\n\n如果你感兴趣的话，我会把他的账本从门下递给你。把账本和他需要的那些东西交给他就行了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "充能閃電魔棒報復束腰"}
MultiLanguageQuestData['tw'][4451] = {title = "自由的钥匙", objective = "搜寻灼热峡谷并找到一个可以插入这把格里塞特厕所钥匙的锁眼。这把小小的黄铜钥匙看起来可真简单……它唯一与众不同的地方是刻在钥匙头部的一句话：\n\n“黑铁厕所——请勿复制。”\n\n你完全不明白这是什么意思，也不明白这钥匙是干什么用的。完成任務後，你將獲得：\n\n", description = "这把小小的黄铜钥匙看起来可真简单……它唯一与众不同的地方是刻在钥匙头部的一句话：\n\n“黑铁厕所——请勿复制。”\n\n你完全不明白这是什么意思，也不明白这钥匙是干什么用的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
