MultiLanguageQuestData['tw'][7809] = {title = "捐献魔纹布", objective = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Gnomeregan Exiles, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Gnomeregan Exiles, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7810] = {title = "競技場大師", objective = "與荊棘競技場的小個子約翰‧米斯瑞爾談話。\n\n已提供物品：\n", description = "要成為競技場高手肯定需要付出更多的代價!\n\n也許管理古拉巴什競技場的海賊知道到底要多少!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7813] = {title = "捐献毛料", objective = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by the Undercity for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by the Undercity for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7814] = {title = "捐献丝绸", objective = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7815] = {title = "钳嘴龟！", objective = "辛特兰恶齿村的钓鱼者卡图姆要你去杀掉10只海水钳嘴龟。完成任务之后回到他那里去复命。", description = "不要让它们的大眼睛迷惑了你，伙计！那些海水钳嘴龟真是个麻烦。我钓鱼都不能安宁五分钟，那些巨型鱼罐头就会把我的鱼饵给偷吃掉。\n\n帮恶齿巨魔一个忙吧，干掉它们，伙计。\n\n把它们都干掉！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納特‧帕格的極限釣魚竿FC-5000型"}
MultiLanguageQuestData['tw'][7816] = {title = "加莫里塔！", objective = "辛特兰恶齿村的钓鱼者卡图姆要你去杀掉加莫里塔，并从它的尸体上找到卡图姆的超级鱼饵。\n\n卡图姆说加莫里塔和其它海龟都在海岸附近活动。", description = "嘿，我说，这里的海边有一只特殊的乌龟，她叫加莫里塔，是那帮卑鄙的海水钳嘴龟的头儿。\n\n伙计，她偷了我最好的鱼饵，就在我眼皮底下！而且自从那次以后，鱼儿就再也不咬我的钩了。\n\n找到加莫里塔，把我的鱼饵从她的胃里挖出来！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7817] = {title = "捐献魔纹布", objective = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Undercity, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Undercity, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7820] = {title = "捐献毛料", objective = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Thunder Bluff for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Thunder Bluff for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
