MultiLanguageQuestData['tw'][7826] = {title = "捐献毛料", objective = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Orgrimmar for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Orgrimmar for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7827] = {title = "捐献丝绸", objective = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7828] = {title = "银鬃捕猎者", objective = "辛特兰恶齿村的猎户马克霍尔要求你去杀掉5头银鬃捕猎者和5头银鬃嗥狼。完成任务之后就回到他那里复命。\n\n马克霍尔说过那些狼都躲在辛特兰的野外。", description = "许多勇敢的巨魔都在辛特兰的森林中失踪了，<race>。银鬃狼对我们的猎人来说是最大的威胁。它们静静地隐藏在灌木丛中，当时机成熟之后就发起突然袭击。\n\n我们一定要阻止这种残忍的行为！\n\n你必须和银鬃狼一样思考。我们要以牙还牙，猎捕它们！把它们全都干掉！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7829] = {title = "野蛮的枭兽", objective = "辛特兰恶齿村的猎户马克霍尔要求你去杀掉10头野蛮的枭兽。完成任务之后就回到他那里复命。\n\n马克霍尔说过那些野蛮的枭兽都躲在辛特兰的野外。", description = "辛特兰地区最令人讨厌的生物之一就是那些野蛮的枭兽。很多勇敢的恶齿战士都倒在了那些野兽的利爪和尖嘴之下。\n\n干掉你看到的每个野蛮的枭兽，<race>。当你把它们杀得血流成河的时候就回到我这里来，你的贡献一定会得到我们的赞赏。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7830] = {title = "死者的复仇", objective = "辛特兰恶齿村的猎户马克霍尔要求你杀掉一头翱翔的锋喙狮鹫，并将它的狮鹫长羽拿回去交给他。\n\n马克霍尔说过那些翱翔的锋喙狮鹫就躲在辛特兰的野外。", description = "现在蛮锤部族训练的狮鹫正在肆意屠杀巨魔。这真是太可怕了，但是我知道不久之后正义就将得到伸张。\n\n现在我需要派你去清除那些成年的狮鹫首领，也就是那种翱翔的狮鹫。\n\n干掉它们中的一个，然后把它的羽毛交给我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7831] = {title = "捐献魔纹布", objective = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by Orgrimmar, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by Orgrimmar, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7833] = {title = "捐献毛料", objective = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Ironforge for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "We are currently accepting donations for wool cloth. A donation of sixty pieces of wool cloth will net you full recognition by Ironforge for your generous actions. Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7834] = {title = "捐献丝绸", objective = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "As with most other fabrics, our stocks of silk are at an all-time low. Our stores are such that we'd only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.\n\nA benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7835] = {title = "捐献魔纹布", objective = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Darkspear Trolls, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "Mageweave is running low, and we could use your help to replenish our stocks! By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal. Such generosity would not go unnoticed by the Darkspear Trolls, I assure you!\n\nIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful! We thank you for your generous donation, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['tw'][7838] = {title = "競技場宗師", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n競技場宗師飾物"}
MultiLanguageQuestData['tw'][7839] = {title = "邪枝窃贼", objective = "辛特兰恶齿村的铁匠斯拉提要你去找到斯拉提的工具。完成任务之后就回到他那里去。\n\n你记得铁匠斯拉提说过，你可以在辛特兰东北部的某个邪枝巨魔神庙中找到它，要不然就是在隐匿石那边。", description = "邪枝巨魔入侵了我们的村子，偷走了我的工具！我有备用的工具，但是那套被偷走的工具是当年的一个救了我性命的侏儒送给我的。\n\n我要拿回那套工具，<name>——它们对我来说意味着整个世界。\n\n马克霍尔报告说那些工具就在亚戈瓦萨和沙尔瓦萨神庙附近。\n\n那些神庙坐落在辛特兰的东北区域。\n\n找回我的工具！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7840] = {title = "拉尔德的午餐", objective = "辛特兰恶齿村的拉尔德要求你去找到拉尔德的午餐。完成任务之后就回到他那里去。\n\n拉尔德说他把午餐留在了北面的岛上。当心邪枝巨魔。", description = "拉尔德在一个秘密的地方享用野餐，这时丑陋的邪枝巨魔一棍打翻了我。拉尔德跑回了恶齿村，但是把午餐留在了那里。拉尔德饿了。也许你可以去那个秘密的地方找回拉尔德的午餐？拉尔德害怕。出发吧！北边的岛就是那个秘密的地方。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n拉爾德的午餐籃"}
MultiLanguageQuestData['tw'][7841] = {title = "给蛮锤部族的警告", objective = "辛特兰恶齿村的奥索·莫吉克要你去杀掉8个高原前锋、5个高原斥候和2个高原神射手。任务完成之后回到他那里去复命。\n\n你可以在辛特兰西北部的奎尔丹尼小屋找到那些高原精灵。", description = "蛮锤部族的矮人和我们的敌人联合起来，形成了新的联盟。这一次，他们和高等精灵站在了一起，伙计。\n\n<奥索吐了口唾沫。>\n\n我们必须给那些蛮锤矮人传达一条信息，一条用我们敌人的鲜血书写的警告。杀掉你所看到的所有高原高等精灵，把他们的尸体留在那里作为警告。\n\n永远不要与巨魔为敌！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][7844] = {title = "野蛮的亲戚", objective = "辛特兰恶齿村的秘法师雅尔金要你去杀掉6个邪枝割颅者和2个邪枝占卜者。任务完成之后回到他那里去复命。\n\n秘法师雅尔金说过，你可以在辛特兰东北部的沙尔瓦萨和亚戈瓦萨神庙附近找到那些巨魔。", description = "三个不同的巨魔部族居住在辛特兰地区，<name>。我们之间的共同点是：我们都是巨魔，而且我们都住在辛特兰。\n\n邪枝巨魔——正如他们的名字一样，是一群堕落的巨魔；他们以其他的巨魔和人型生物为食。\n\n如果祖尔金在这里的话，他一定会手腕一抖灭掉这个部族——啊，祖尔金还没有回来，所以我们要自己动手了。\n\n现在，你的职责就是把这帮渣滓给干掉！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7845] = {title = "被绑架的断齿长者！", objective = "辛特兰恶齿村的断齿族长要求你到辛萨罗去拯救她的爱人，断齿长者。\n\n你听说他被关在辛萨罗顶部，辛萨罗位于辛特兰的南部地区，那里是邪枝巨魔的主城。我的爱人在邪枝巨魔发动的一次夜间突袭中被掳走。我们的探子回报说他还活着，并且被关在辛萨罗的顶部。据说邪恶祭司海克斯正准备把他当作祭品献给邪神哈卡。\n\n你必须救救他，<name>！我们的村庄不能失去他。完成任務後，你將獲得：\n\n", description = "我的爱人在邪枝巨魔发动的一次夜间突袭中被掳走。我们的探子回报说他还活着，并且被关在辛萨罗的顶部。据说邪恶祭司海克斯正准备把他当作祭品献给邪神哈卡。\n\n你必须救救他，<name>！我们的村庄不能失去他。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][7848] = {title = "熔火之心的傳送門", objective = "進入黑石深淵，在通往熔火之心的傳送門附近找到一塊熔核碎片，然後回到黑石山脈的洛索斯‧天痕那裡。", description = "裂隙在翻滾，它撕裂並吞噬我們周圍所有的東西，<class>。我所站立的地方旁邊的裂隙就是穿過黑石深淵直通炎魔所在地的傳送門。\n\n你感到很驚奇嗎?真是遺憾...凡人總是無法領悟那些他們無法看到、觸摸到或者感覺到的東西。\n\n我向你保證，這個傳送門可以到達熔火之心。\n\n你開始感興趣了嗎?其實這是很簡單的。進入熔火之心，獲得一塊熔核碎片，把它交給我，然後我就會將你的靈魂與傳送門進行同步。", progress = "你一定要在取得同意前協調你在熔火之心的靈魂。", completion = "我現在可以將你傳送至熔火之心了。只要你開口就能辦到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][7849] = {title = "分离的痛苦", objective = "辛特兰恶齿村的猎户马克霍尔要你去找回他的双胞胎兄弟的尸体。找到它，然后把猎户莫克霍尔的徽记和猎户莫克霍尔的骨头交给猎户马克霍尔。\n\n马克霍尔说过，他兄弟的尸体被软泥怪和邪枝巨魔的狼群分食。他还提到在辛萨罗有个大坑，里面全都是软泥怪，那里还有个狼穴。这两个地方都在靠近辛萨罗神庙顶部的区域。", description = "和许多朋友一样，我挚爱的亲人也在野外永远逝去了。啊，我的双胞胎兄弟莫克霍尔——他在邪枝巨魔突袭的那天晚上死了。\n\n他被残忍地处死，他的尸体被软泥怪和邪枝巨魔的狼分食。\n\n现在拯救他的肉体已经太晚了，但我们要拯救他的灵魂。把他的遗体带回来，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "綠葉裹手漆面木板腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][7850] = {title = "黑暗之瓶", objective = "辛特兰恶齿村的断齿族长要你在辛萨罗找到5瓶腐化之血。任务完成之后就回到断齿族长那里。", description = "邪枝巨魔正在疯狂地进攻我们，这是因为他们受到了邪恶祭司海克斯的堕落魔法的影响。\n\n你可以在辛萨罗找到腐化之血。那只装着腐化之血的瓶子散发着邪神哈卡的堕落能量，这让邪枝巨魔们充满了力量，并让他们变得疯狂。\n\n把那些腐化之血交给我，这样我就可以去除其中的堕落能量，以此来削弱邪神的力量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n自然之息"}
MultiLanguageQuestData['tw'][7861] = {title = "通缉：邪恶祭司海克斯和她的爪牙", objective = "你必须杀掉邪恶祭司海克斯和5名邪枝精英守卫。任务完成之后回到辛特兰的恶齿村，向断齿族长报告。\n\n你可以在辛特兰的邪枝巨魔城市辛萨罗的顶部找到他们。", description = "根据断齿族长的命令，邪恶祭司海克斯和她的手下必须受到制裁！\n\n如果你能除掉邪恶祭司海克斯和她的精英卫兵，那么你就可以获得丰富的奖励。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "密林披風常青藤項鍊您會收到：\n\n"}
MultiLanguageQuestData['tw'][7862] = {title = "职位空缺：恶齿村卫兵队长", objective = "你必须消灭5个邪枝狂战士、3个邪枝暗影猎手、3个邪枝饮血者和3个邪枝噬魂者。\n\n完成任务之后向辛特兰恶齿村的断齿族长复命。", description = "在卫兵队长马克霍尔牺牲之后，恶齿村卫兵队长的职位再次空缺。如果你有兴趣成为恶齿村的卫兵队长，就必须完成以下任务，然后向断齿族长提交申请表：\n\n消灭邪枝狂战士。\n\n消灭邪枝暗影猎手。\n\n消灭邪枝饮血者。\n\n消灭邪枝噬魂者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n守衛隊長符文"}
