MultiLanguageQuestData['tw'][7944] = {title = "財富等著你...", objective = "到貧瘠之地的哀嚎洞穴中去尋找你的財寶吧。", description = "「哀嚎洞穴中的財寶正等著你。」\n\n你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出了位於貧瘠之地十字路口西南方的一處洞穴的影像。你專注地觀察著，發現蜿蜒的道路盡頭是一道發光的門...通往洞穴中心的門。你穿過大門，不知從哪兒冒出了一個奇怪的箱子。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘的帶鎖箱"}
MultiLanguageQuestData['tw'][7945] = {title = "財富等著你...", objective = "到莫高雷的白鬃石去尋找你的財寶吧。", description = "「白鬃石外的財寶正等著你。」\n\n你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出莫高雷白鬃石的影像。你專注地觀察著，發現洞穴入口附近有一塊樹樁。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘的帶鎖箱"}
