MultiLanguageQuestData['tw'][8041] = {title = "穆贾巴之力", objective = "Hail, <class>. I am Jin'rokh the Breaker, troll of Mugamba. We of the Zandalar tribe recognize your accomplishments. We salute your tenacity and strength of will.\n\nWear this talisman around your neck, <class>. Let the strength of Mount Mugamba flow through your being. Be empowered as you strike down our enemies!您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n穆賈巴之力"}
MultiLanguageQuestData['tw'][8042] = {title = "穆贾巴之力", objective = "It is good to see you in good health, <name>. The glorious battles you have undertaken affect all life on this planet. Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.\n\nGive me your talisman and I shall amplify its strength. Use the Strength of Mugamba to punish our enemies!", description = nil, progress = "It is good to see you in good health, <name>. The glorious battles you have undertaken affect all life on this planet. Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.\n\nGive me your talisman and I shall amplify its strength. Use the Strength of Mugamba to punish our enemies!", completion = "Our paths will cross again, &lt;class&gt;.", rewards = "您會收到：\n\n穆賈巴之力"}
MultiLanguageQuestData['tw'][8043] = {title = "穆贾巴之力", objective = "Master <name>, you return! Molthor has sent word of your deeds to the King. Your name is known even in the South Seas. Perhaps one day you will be a legendary <class> - a story for the ages.\n\nGive me your talisman so that I may once more amplify its power.", description = nil, progress = "Master <name>, you return! Molthor has sent word of your deeds to the King. Your name is known even in the South Seas. Perhaps one day you will be a legendary <class> - a story for the ages.\n\nGive me your talisman so that I may once more amplify its power.", completion = "Use your newfound strength to destroy the Gurubashi!", rewards = "您會收到：\n\n穆賈巴之力"}
MultiLanguageQuestData['tw'][8044] = {title = "穆贾巴的怒火", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n穆賈巴之怒"}
MultiLanguageQuestData['tw'][8058] = {title = "权力珍宝：辩护者护臂", objective = "从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。\n\n击碎者金罗克在荆棘谷的尤亚姆巴岛上。", description = "复仇便是力量。赞达拉辩护者拥有这样的力量。我们的部族有很多敌人，辩护者要让他们付出代价。对抗我们的愚蠢之人必将受到惩罚，辩护者就是施加惩罚的执行人。敌人害怕复仇，他们永远都会害怕你。\n\n充当起辩护者的角色吧。去祖尔格拉布寻找权力珍宝。杀死哈卡的爪牙，以部族的名义复仇。你会得到奖励的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n贊達拉辯護者臂甲"}
MultiLanguageQuestData['tw'][8061] = {title = "权力珍宝：忏悔者裹布", objective = "从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。\n\n全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。", description = "我们赞达拉部族将权力授予那些能和神灵直接沟通的成员。我们的祭司不仅仅是治疗者，也是忏悔者。邪恶不但来自外部的威胁——比如哈卡，也来自部族内部。我们的忏悔者在此担起了法官的职责，避免我们被那股吞噬了古拉巴什帝国的邪恶力量所毁灭。\n\n我需要的权力珍宝就在祖尔格拉布中，去找到那些珍宝，了解忏悔者的职责和精神，保护我们免受邪恶的侵蚀。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n贊達拉懺悔者裹帶"}
MultiLanguageQuestData['tw'][8070] = {title = "权力珍宝：忏悔者腰带", objective = "从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱腰带。你还必须在赞达拉部族中达到尊敬或更高的声望。\n\n全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。", description = "在古拉巴什帝国陷落之后，我们赞达拉部族几乎被一股来自部族内部的邪恶力量所击败。这个时候有一些忏悔者挺身而出，将那些对自己同胞下手的败类驱逐了出去。他们不仅让我们精神得到升华，而且还让我们保存了性命。\n\n去祖尔格拉布，亲眼见证哈卡的倒下，也顺便拜访一下古拉巴什帝国吧。从他们那里夺得我们所需的权力珍宝，在成功之后，你就将获得奖励！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n贊達拉懺悔者腰帶"}
MultiLanguageQuestData['tw'][8071] = {title = "权力珍宝：忏悔者衬肩", objective = "从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1块原始哈卡莱之盾。你还必须在赞达拉部族中达到崇敬或更高的声望。\n\n全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。", description = "赞达拉的忏悔者都穿着独特的护肩，这可以将他们标示为部族的保护者。这些护肩是用强大的魔精制作的，它会帮助那些为我们部族而战的勇士。作为一个牧师，你也需要这样一副护肩的庇护。\n\n进入祖尔格拉布，和哈卡的爪牙作战，然后把权力珍宝给我带回来，我会给你一副只有最优秀的忏悔者才能获得的护肩。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n贊達拉懺悔者披肩"}
MultiLanguageQuestData['tw'][8073] = {title = "權力珍寶:狂妄者外套", objective = "把原始哈卡萊聖禦盾帶給盲眼法希爾。你還必須在贊達拉部族中達到崇敬或更高的聲望。\n\n盲眼法希爾在荊棘谷的尤亞姆巴島上。", description = "我的眼睛很早以前就瞎了，但是我一點也不懷念它們。在我們這樣的部族中，衣飾代表了著裝者的地位和意圖，而最強大的衣服所蘊涵的力量不是用肉眼就能看出來的。贊達拉狂妄者法衣也不例外，它蘊藏著可任你操控的混亂和瘋狂之力。\n\n我需要的權力珍寶就在祖爾格拉布中，去找那些珍寶，我會獎勵你一件傳說中的法衣...適合狂妄者的法衣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n贊達拉狂妄者外套"}
MultiLanguageQuestData['tw'][8078] = {title = "权力珍宝：辩护者腰带", objective = "从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。\n\n击碎者金罗克在荆棘谷的尤亚姆巴岛上。", description = "祖尔格拉布将再次沐浴在仇恨的洗礼中。哈卡，这个摧毁了古拉巴什帝国的恶魔必须被消灭，无论我们付出多大代价也都在所不惜。现在的巨魔只不过是光芒消退后残存的阴影而已，这都是哈卡造成的！\n\n成为一名辩护者吧，去消灭恶魔的爪牙。祖尔格拉布将要尝到来自赞达拉的复仇。把权力珍宝交给我，我会给你一条辩护者腰带，让你拥有真实的力量。\n\n去吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n贊達拉辯護者腰帶"}
MultiLanguageQuestData['tw'][8079] = {title = "权力珍宝：辩护者胸甲", objective = "从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱套索。你还必须在赞达拉部族中达到崇敬或更高的声望。\n\n击碎者金罗克在荆棘谷的尤亚姆巴岛上。", description = "胸甲是辩护者力量的象征。它是由魔精制成的。只有那些受到部族崇敬的勇士才能拥有它，这是赞达拉复仇的象征。\n\n要成为辩护者，就必须复仇。从祖尔格拉布取回我们需要的权力珍宝，夺回被盗的魔精。哈卡的爪牙将为此付出代价，而你将因此获得辩护者胸甲。\n\n去吧。成为我们的复仇之神，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n贊達拉辯護者胸甲"}
MultiLanguageQuestData['tw'][8105] = {title = "阿拉希盆地之战！", objective = "进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。", description = "<name>，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。\n\n当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！\n\n当你完成了夺回这四个点的任务之后，就回到我这里来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8114] = {title = "控制四座基地", objective = "进入阿拉希盆地，同时占据并控制四座基地，当任务完成之后向避难谷地的奥斯莱特元帅报告。", description = "<name>，你赢得了在阿拉希盆地的战争，并在战场上证明了自己有资格得到荣耀和尊重。你是一个有价值的<class>，你让我们的敌人知道我们绝对不会向他们的暴行屈服！\n\n现在我有一项艰巨的任务要交给你。我需要你进入阿拉希盆地，占领至少四座基地。如果你可以完成这个任务的话，那么我们不仅保证了重要资源的供给，而且还向部落展示了我们的力量！\n\n出发吧，<name>，祝你好运。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8120] = {title = "阿拉希盆地之戰!", objective = "進攻阿拉希盆地的礦坑、伐木場、鐵匠鋪和獸欄，然後向落錘鎮的屠殺者杜維爾覆命。", description = "無疑你已經聽說了，阿拉索聯軍正派大量的軍隊進駐阿拉希盆地。聯盟那幫蠢貨想要食物和補給，因此妄圖佔據這塊富饒的土地。我們必須讓他們知道阿拉希永遠不會再是人類的家園了!\n\n去阿拉希盆地然後進攻那裡礦坑、伐木場、鐵匠鋪和獸欄。奪下敵人在那裡的旌旗，把那裡變成部落的領土。\n\n出發吧，<name>。完成任務之後向我覆命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8121] = {title = "夺取四座基地", objective = "同时占据阿拉希盆地中的四座基地，然后向落锤镇的屠杀者杜维尔复命。", description = "<name>，随着阿拉希盆地的战事进展，你的事迹已经传遍了战场。你的所做所为让我确信你一定可以完成现在我要给你的任务。\n\n现在是给阿拉索联军一个信号的时候了。我们将会向他们展示，他们在阿拉希盆地的防守是多么脆弱。我们要通过同时占领阿拉希盆地的四个战略点来让他们明白这一点。\n\n如果你可以完成这个任务，<name>，你将赢得污染者的尊敬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8149] = {title = "緬懷英雄", objective = "前往西瘟疫之地的光明使者烏瑟的墓碑，在墓碑前放下他的祭品。在收穫節結束之前返回鐵爐堡的瓦格納‧巨錘那兒。", description = "在艾澤拉斯收穫節上，我們對那些無私奉獻英雄們表示感謝，他們其中甚至獻出自己的性命。聯盟曾湧現出很多的英雄，但是沒有誰的光芒能超越光明使者烏瑟。\n\n將這些祭品帶到西瘟疫之地光明使者烏瑟的墓碑那兒，去表達我們的敬意吧。把祭品放在墓碑下，然後回到我們這兒來。收穫節結束之前我會一直在這兒，別浪費時間了，出發吧。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n焦慮靈魂裂片孤寂靈魂裂片祥和靈魂裂片復仇靈魂裂片\n\n您還會收到：\n\n為聖光而戰!龍石"}
MultiLanguageQuestData['tw'][8150] = {title = "緬懷英雄", objective = "前往梣谷屠魔峽谷的葛羅‧地獄吼的紀念碑，在紀念碑前放下他的祭品。在收穫節結束之前返回奧格瑪的亞尼‧納沙克那邊。", description = "在艾澤拉斯收穫節上，我們對那些無私奉獻英雄們表示感謝，他們其中甚至犧牲自己的生命。部落曾湧現出許多英雄，但是沒有誰的光芒能超越葛羅‧地獄吼。\n\n將這些祭品帶到梣谷屠魔峽谷中的葛羅‧地獄吼的紀念碑那兒，去表達我們的敬意吧。把祭品放在墓碑下，然後回到我們這兒來。收穫節結束之前我會一直在這兒，別浪費時間了，出發吧。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n焦慮靈魂裂片孤寂靈魂裂片祥和靈魂裂片復仇靈魂裂片\n\n您還會收到：\n\n部落的地獄吼龍石"}
MultiLanguageQuestData['tw'][8151] = {title = "獵人符咒", objective = "跟艾薩拉的奧汀克談話。", description = "艾薩拉的奧汀克正在召集像你這樣經驗豐富的獵人。他是一名熊怪獵人，他離開自己的部族並前來幫助塞納里奧議會。奧汀克與其他人分享自己的智慧，並引導他們維護平衡。去和他談談會對你很有幫助。\n\n奧汀克住在艾薩拉的懸崖頂部，埃達拉斯廢墟的東北方。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8167] = {title = "阿拉希盆地之戰!", objective = "進攻礦坑、伐木場、鐵匠舖和農場，然後向避難谷地的奧斯萊特元帥覆命。", description = "<name>，在阿拉希盆地的戰鬥是為了資源和領土而進行的戰鬥。這個地區作戰的關鍵是保證我們軍隊稀有物資和補給的順暢運作。我命令你去攻擊距離我們在阿拉希盆地中的基地最遠的戰略設施。\n\n當農場、礦坑、伐木場或鐵匠舖被敵人佔據時，攻擊這些設施，找到敵人的旌旗，然後把它拔掉!\n\n當你完成了奪回這四個點的任務之後，就回到我這裡來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8168] = {title = "阿拉希盆地之战！", objective = "进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。", description = "<name>，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。\n\n当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！\n\n当你完成了夺回这四个点的任务之后，就回到我这里来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8169] = {title = "阿拉希盆地之戰!", objective = "進攻阿拉希盆地的礦坑、伐木場、鐵匠舖和獸欄，然後向落錘鎮的屠殺者杜維爾覆命。", description = "無疑你已經聽說了，阿拉索聯軍正派大量的軍隊進駐阿拉希盆地。聯盟那幫蠢貨想要食物和補給，因此妄圖佔據這塊富饒的土地。我們必須讓他們知道阿拉希永遠不會再是人類的家園了!\n\n去阿拉希盆地然後進攻那裡礦坑、伐木場、鐵匠鋪和獸欄。奪下敵人在那裡的旌旗，把那裡變成部落的領土。\n\n出發吧，<name>。完成任務之後向我覆命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8170] = {title = "阿拉希盆地之戰!", objective = "進攻阿拉希盆地的礦坑、伐木場、鐵匠舖和獸欄，然後向落錘鎮的屠殺者杜維爾覆命。", description = "無疑你已經聽說了，阿拉索聯軍正派大量的軍隊進駐阿拉希盆地。聯盟那幫蠢貨想要食物和補給，因此妄圖佔據這塊富饒的土地。我們必須讓他們知道阿拉希永遠不會再是人類的家園了!\n\n去阿拉希盆地然後進攻那裡礦坑、伐木場、鐵匠鋪和獸欄。奪下敵人在那裡的旌旗，把那裡變成部落的領土。\n\n出發吧，<name>。完成任務之後向我覆命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8171] = {title = "阿拉希盆地之战！", objective = "进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。", description = "无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉希盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！\n\n去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。\n\n出发吧，<name>。当任务完成之后向我复命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8181] = {title = "面对叶基亚", objective = "跟叶基亚谈一谈。通过对摩沙鲁石板的研究，我得出了一个可怕的消息，<name>。你用一枚蛋收复了哈卡，然而血神哈卡的真身可以通过那枚蛋获得新生！叶基亚告诉你说那枚蛋是用来禁锢哈卡的邪恶力量的，但实际上，它的作用是让哈卡重生！那个巨魔将你引入了歧途！\n\n去找到叶基亚，摧毁那枚蛋。希望我们还有足够的时间阻止哈卡死灰复燃！完成任務後，你將獲得：\n\n", description = "通过对摩沙鲁石板的研究，我得出了一个可怕的消息，<name>。你用一枚蛋收复了哈卡，然而血神哈卡的真身可以通过那枚蛋获得新生！叶基亚告诉你说那枚蛋是用来禁锢哈卡的邪恶力量的，但实际上，它的作用是让哈卡重生！那个巨魔将你引入了歧途！\n\n去找到叶基亚，摧毁那枚蛋。希望我们还有足够的时间阻止哈卡死灰复燃！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "褪色的哈卡萊披風破碎的哈卡萊斗篷"}
MultiLanguageQuestData['tw'][8182] = {title = "拉斯塔哈之手", objective = "跟荆棘谷的莫托尔谈一谈。<name>，我们最担心的事情终于发生了。相传拥有无上力量的夺灵者哈卡正在统治着巨魔的古代帝国，那里充斥着邪恶和恐怖。如果我们不做点什么的话，他的统治范围很可能会蔓延到整个艾泽拉斯！\n\n也许赞达拉巨魔能帮助我们阻止悲剧的发生。他们驻扎在荆棘谷的祖昆达废墟以西，也就是那个名叫尤亚姆巴的小岛上。跟他们的首领莫托尔谈谈，但愿他知道如何打败哈卡。完成任務後，你將獲得：\n\n", description = "<name>，我们最担心的事情终于发生了。相传拥有无上力量的夺灵者哈卡正在统治着巨魔的古代帝国，那里充斥着邪恶和恐怖。如果我们不做点什么的话，他的统治范围很可能会蔓延到整个艾泽拉斯！\n\n也许赞达拉巨魔能帮助我们阻止悲剧的发生。他们驻扎在荆棘谷的祖昆达废墟以西，也就是那个名叫尤亚姆巴的小岛上。跟他们的首领莫托尔谈谈，但愿他知道如何打败哈卡。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8183] = {title = "哈卡之心", objective = "把哈卡之心交给尤亚姆巴岛上的莫托尔。", description = "哈卡之心熊熊燃烧着。虽然夺灵者已经被击败，但是他邪恶的力量依然在被诅咒的躯体之中涌动。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n贊達拉英雄徽章贊達拉英雄符咒贊達拉英雄勳章"}
