MultiLanguageQuestData['tw'][8227] = {title = "纳特的卷尺", objective = "将纳特的卷尺交给尘泥沼泽的纳特·帕格。", description = "在散落的鱼饵和滚轴之中是一卷光滑的测量卷尺。卷尺上的标签写着：\n\n“纳特·帕格，尘泥沼泽。”完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8233] = {title = "簡單的要求", objective = "前往拉文霍德莊園，和喬拉齊·拉文霍德領主談一談。", description = "喬拉齊·拉文霍德領主邀請你到他那兒去。這事兒得保密，我不能再透露更多消息了。\n\n拉文霍德莊園位於希爾斯布萊德丘陵，敦霍爾德城堡的西北方有一條道路通往那兒。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
