MultiLanguageQuestData['tw'][8536] = {title = "碎石公爵", objective = "设法召唤并击杀碎石公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。", description = "暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。\n\n根据可靠情报，那个被称作碎石公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧戰術徽章後續戰術指令"}
MultiLanguageQuestData['tw'][8537] = {title = "微风公爵", objective = "设法召唤并击杀微风公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。", description = "暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。\n\n根据可靠情报，那个被称作微风公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧戰術徽章戰術指令"}
MultiLanguageQuestData['tw'][8538] = {title = "圣殿骑士", objective = "设法召唤并击杀四个深渊圣殿骑士，然后向塞纳里奥要塞的唤风者梅恩·长角复命。", description = "暮光之锤和深渊议会之间的联系看来比我们想象中的还要意义重大。\n\n根据可靠情报，那些被称作深渊圣殿骑士的元素领主们可能正在策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他们引诱出来，然后击杀他们。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納留斯印記"}
MultiLanguageQuestData['tw'][8539] = {title = "目標:佐拉雌蠍", objective = "殺死30隻佐拉雌蠍並回希利蘇斯向塞納里奧城堡的指揮官瑪爾利斯回報。你還必須將作戰任務簡報 V帶去才能完成這個任務。", description = "援軍已被徵召加入佐拉蟲巢的攻擊了。你的主要目標是那些佐拉雌蠍。完成你的任務之後再回報給指揮官瑪爾利斯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8540] = {title = "卫兵的护甲片", objective = "把3双精制秘银战靴交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 II才能完成这个任务。", description = "目前塞纳里奥要塞的骑兵团缺乏足够的毛皮护甲片，去收集大量护甲片，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8541] = {title = "卫兵的磨刀石", objective = "把10块致密砂轮、10块坚固的砂轮和10块重砂轮交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 III才能完成这个任务。", description = "塞纳里奥要塞的卫兵急需磨刀石。去收集足够的磨刀石，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8542] = {title = "部落需要錫錠!", objective = "帶20個錫錠給奧格瑪精神谷的蠻兵瑪烏格。", description = "為了部落，<race>，我沒有時間解釋一遍給你聽。我們即將在安其拉開戰，但是首先大酋長要我們做一件叫做「準備」的事。這表示我需要你去收集錫錠。我想我需要的數字很龐大。B\n你還在這裡幹嘛?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8544] = {title = "征服者的肩甲", objective = "將其拉命令束腕、2個夜晚塑像、5隻石甲蟲和5隻泥土甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。", description = "據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。\n\n幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服者的肩甲"}
MultiLanguageQuestData['tw'][8545] = {title = "部落需要秘銀錠!", objective = "帶20個秘銀錠給奧格瑪精神谷的資深士官克拉恩。", description = "<class>，戰爭就要來臨而我們唯一能做的事就是做好準備。這就是我們要互相幫忙的時候了。告訴你，他們叫我負責收集所有製作必備品需要的秘銀錠。而我還需要更多!\n\n所以，我希望你可以離開這裡幫我們挖一些秘銀來，然後將它們熔製成錠。你可以幫我們這個忙嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8548] = {title = "志愿兵的装备", objective = "把5枚作战徽章、3枚后勤徽章和7枚战术徽章交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到友善声望才能完成这个任务。", description = "<name>，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。\n\n希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "土靈力量手套大地憤怒指環地紋披風"}
MultiLanguageQuestData['tw'][8549] = {title = "部落需要寧神花!", objective = "帶20個寧神花給奧格瑪精神谷的草藥師波德‧飛羽。", description = "據說每個世代都必須面臨一個決定性的試驗。我擔心安其拉之戰對我們的毅力而言是個嚴酷的考驗。所以我們要充分準備，並藉此了解我們的實力。\n\n我已經自願幫忙部落收集寧神花，然後它們就能被拿來製作戰爭用的藥劑。我希望你能給我一些支援，我需要你去帶回大量的草藥給我。你能幫我嗎，<class>?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8551] = {title = "船長的箱子", objective = "將斯莫特的箱子交給藏寶海灣的海克拜瑞·斯莫特。", description = "我過去在一條專跑從這裡到卡林多的棘齒城的航線上幹過。我是個很優秀也很有名望的船長。\n\n直到...\n\n那些該死的海巨人毀了我的生活!他們打沉了我的船，殺光了我的水手，把我丟在一條救生艇上，讓我漂回了藏寶海灣。還有，其中一個名叫高拉什的巨人還把我的箱子給偷走了，他說要拿這東西當鼻煙盒，簡直是神經病!\n\n我聽說有人看見高拉什最近在東邊的海岸一帶閒逛。找到他，把我的箱子給搶回來!快去，你會得到一位船長的敬意的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n血環護腕"}
MultiLanguageQuestData['tw'][8552] = {title = "刺着字母的腰带", objective = "将刺着字母的腰带还给他的主人。", description = "这条精致的腰带的边上刺着两个字母“HS”。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8555] = {title = "守护之龙", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8556] = {title = "不屈力量之戒", objective = "帶1枚其拉將領戒指、2個柔光塑像、5隻青銅甲蟲和5隻象牙甲蟲給希利蘇斯的喚風者耶薩德拉。你還需要在塞納里奧議會達到尊敬聲望才能完成這個任務。", description = "謠傳其拉將領所帶的徽戒具有強大可怕的力量，上面裝飾用的墮落寶石，理論上應該要替換成更純淨的材質，才可以讓戒指呈現出一種不腐敗的形象。\n\n這些寶石能完美搭配著其拉塑像，因為他們的品質最頂級了。\n\n帶給我徽戒跟塑像，我就幫你製作一個強大力量的戒指，<class>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n不屈力量之戒"}
MultiLanguageQuestData['tw'][8557] = {title = "不屈力量披氅", objective = "帶1件其拉軍用披氅、2個黑瑪瑙塑像、5隻銀色甲蟲和5隻白骨甲蟲給希利蘇斯的凱伊‧迅爪。你還需要在塞納里奧議會達到崇敬聲望才能完成這個任務。", description = "我很高興聽到你正在協助我們準備攻擊安其拉，<name>。我要給你一個保護物品協助你對抗我們的敵人，<class>。\n\n我需要一塊其拉披氅，我一定會為你量身訂做。我還需要塑像和甲蟲來做一個合適的鉤子。\n\n我保證你不會失望的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n不屈力量披氅"}
MultiLanguageQuestData['tw'][8558] = {title = "不屈力量之鐮", objective = "帶1把其拉尖刺刀柄、2個雪白塑像、5隻水晶甲蟲和5隻石甲蟲給希利蘇斯的守望者哈爾洛。你還必須在塞納里奧議會達到崇拜聲望值才能完成這個任務。", description = "其拉和它們的奴僕使用的物品都是用最稀有和最精緻頂級的材料做成：巨大的古老生物骨頭，地底深處的寶石，純淨堅硬的金屬。\n\n光看一眼其拉神器，就讓我有股衝動想把它們粉碎溶解的碎片，拿來精進我的手藝。證明你對議會的忠誠吧，<name>，然後我就會幫你用最好的其拉材料做一個強大的武器。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n不屈力量之鐮"}
MultiLanguageQuestData['tw'][8559] = {title = "征服者的護脛", objective = "將其拉命令束腕、2個戰爭塑像、5隻象牙甲蟲和5隻金色甲蟲帶給安其拉的坎多斯塔茲。此任務還需要在諾茲多姆的子嗣達到中立的聲望。", description = "其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。\n\n幫我把其拉統御束腕和其他次要材料帶來，我就能為你製作一雙強大的靴子。\n\n你會在對抗敵人時發現它們很有用的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服者的護脛"}
MultiLanguageQuestData['tw'][8560] = {title = "征服者的腿甲", objective = "將奧羅的外皮、2個死亡塑像、5隻青銅甲蟲和5隻象牙甲蟲帶給安其拉裡面的坎多斯塔茲。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成這個任務。", description = "你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。\n\n古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。\n\n他的皮膚很奇怪...很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。\n\n幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服者的腿甲"}
MultiLanguageQuestData['tw'][8561] = {title = "征服者之冠", objective = "將維克尼拉斯的頭環、2個太陽塑像、5隻石甲蟲和5隻水晶甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成此任務。", description = "雙子帝王...他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。\n\n我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的...我會將這些其拉的飾品轉變為適合我們需求的東西。\n\n幫我把我要的材料帶來，<name>。我會給你一頂有著無與倫比能量的首盔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服者之冠"}
MultiLanguageQuestData['tw'][8562] = {title = "征服者的胸甲", objective = "將上古之神的甲殼、2個戰爭塑像、5隻銀色甲蟲和5隻白骨甲蟲帶給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。", description = "最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。\n\n當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。\n\n完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲...一件只有弒神者才有資格獲得的護甲!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服者的胸甲"}
MultiLanguageQuestData['tw'][8563] = {title = "术士训练", objective = "与逐日岛太阳之塔内的术士训练师召唤者泰里拉伦谈一谈。", description = "既然你已经在你所选择的职业上有所进步，那么你一定会希望能够获得更多来自职业训练师的指导。逐日岛上有一位名叫召唤者泰里拉伦的术士训练师。去和他谈谈吧，看看他能教会你些什么。当然，你得付点学费。\n\n召唤者泰里拉伦跟逐日岛其他训练师都在太阳之塔的下层。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
