MultiLanguageQuestData['tw'][8572] = {title = "精兵的装备", objective = "把7枚作战徽章、4枚后勤徽章和4枚战术徽章交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到友善声望才能完成这个任务。", description = "<name>，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。\n\n希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "大地力量指環大地能量外衣您能選擇下列奬勵中的一個：\n\n大地恩典"}
MultiLanguageQuestData['tw'][8573] = {title = "勇士的装备", objective = "把15枚作战徽章、20枚后勤徽章、20枚战术徽章和1枚塞纳留斯印记交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。", description = "<name>，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。\n\n希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "塞納留斯之拳您能選擇下列奬勵中的一個：\n\n塞納留斯之怒大地之擊"}
MultiLanguageQuestData['tw'][8574] = {title = "忠诚者的装备", objective = "把15枚作战徽章、20枚后勤徽章、17枚战术徽章和1枚雷姆洛斯印记交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到崇敬声望才能完成这个任务。", description = "<name>，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。\n\n希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "深岩護腕大地寧靜寶珠岩石烈怒護腕您能選擇下列奬勵中的一個：\n\n塞納留斯之力"}
MultiLanguageQuestData['tw'][8575] = {title = "艾索雷葛斯的魔法账本", objective = "把魔法账本交给塔纳利斯的纳瑞安。", description = "<你无法理解这上面的字。你甚至不知道这些文字是什么语言！>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8576] = {title = "翻译龙语", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8577] = {title = "斯图沃尔，前任死党", objective = "纳瑞安要你找到他的前任死党斯图沃尔，从他那里拿回从纳瑞安那里偷走的占卜眼镜。", description = "如果我要翻译东西的话，就得戴上我的占卜眼镜。不幸的，很久以前，我的眼镜就被我的前任死党给偷走了，他就是斯图沃尔。他把我打翻在地，然后拿走了眼镜，把我留在了这里。\n\n在我忠实的水晶球的帮助下，我现在找到他了！他要么就在银松森林的格雷迈恩之墙，要么就在遍地传送门的外域，那里现在到处都是燃烧军团的家伙。你要追踪到他，然后把我的眼镜拿回来，<name>！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8578] = {title = "占卜眼镜？没问题！", objective = "找到纳瑞安的占卜眼镜。", description = "<你听到箱子里面传来一个声音。>\n\n你只需要他的占卜眼镜？很好！这不是问题……给我一分钟……嘿！该死……在哪里！\n\n好吧，我这里有一些坏消息，还有一些更坏的消息。坏消息是我把眼镜给弄丢了。更坏的消息是，我是上个星期在熔火之心里晃悠的时候把它给弄丢的。是的，熔火之心……我想这不是我能搞定的了！再见！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n極效活力藥水"}
MultiLanguageQuestData['tw'][8579] = {title = "人類勝利者", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8580] = {title = "部落需要火焰花!", objective = "帶20朵火焰花給奧格瑪精神谷的蝙蝠騎士比雷凱基。", description = "嘿，<class>。是你啊!部落認為這次的安其拉之戰需要很多的火焰花。或許他們會將它拿來做些好東西。或許他們會拿來當蒸汽坦克的燃料再送給聯盟?誰知道?比雷凱基也不知道!\n\n不過比雷凱基知道這件事就是了...他知道你會幫他的忙並帶回很多火焰花，對嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8582] = {title = "部落需要紫蓮花!", objective = "帶20朵紫蓮花給奧格瑪精神谷的藥劑師耶澤爾。", description = "<class>，紫蓮花是一種試劑，可以拿來做很多藥水、藥劑和油，有些對我們安其拉戰役很有幫助。我們需要為戰役製作數量龐大的藥水。而且我也要做些實驗找出紫蓮花更多的功用。但是我需要大量的花才能做這些事。\n\n那是你進來的地方。走出去，採集越多紫蓮花越好。這是你能辦到的事嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8584] = {title = "少管闲事", objective = "塔纳利斯的纳瑞安让你和加基森的迪尔格·奎克里弗谈一谈。", description = "如果说我有一些原则是你应该了解的，那就是：永远不要管我的闲事！我所做的事情都是你无法理解的。比如说：你知道精神电能整流器是什么吗？显然你不知道！这就是为什么我来负责我们的项目规划，而你负责满世界跑腿。\n\n我之前说过，如果你想继续下去的话，那么我们需要一只500磅重的鸡。\n\n到加基森去跟迪尔格·奎克里弗谈谈——他知道如何让你找到合适的品种。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8585] = {title = "恐怖之岛！", objective = "加基森的迪尔格·奎克里弗要你去菲拉斯的恐怖之岛击杀拉克麦拉，获得拉克麦拉的肉，并从岛上收集20份奇美洛克的腰肋肉。", description = "传说菲拉斯恐怖之岛的那群名叫奇美洛克的奇美拉族群是最鲜美多汁的食物！现在它们之中出现了一个首领，它的肉在经过巧妙的烹调之后可以变成一盘极品大餐！\n\n去恐怖之岛杀掉拉克麦拉，然后把它的肉带回来。这就可以满足那个侏儒了，而我则需要你带一些奇美洛克的腰肋肉给我。\n\n我会给你那500磅的肉鸡和一些别的什么东西作为交换。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8588] = {title = "部落需要重皮!", objective = "帶10張重皮給奧格瑪精神谷的剝皮師亞曼尼。", description = "既然我們在準備作戰，那麼最好事先收集所有需要的東西，你不覺得嗎?我們現在製作的主要戰爭材料之一是重皮。我們會在任何東西上使用到它，從增強材料到護甲，還有好的老舊防水布。\n\n但是首先我們需要弄到多一點重皮。那是你的工作，<class>。磨銳你的刀，幫我帶回一大堆來。然後我們再談。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8590] = {title = "部落需要厚皮!", objective = "帶10張厚皮給奧格瑪精神谷的烏瑪拉中士。", description = "我很高興你決定來和我談這件事，<class>。看來部落為即將來臨的安其拉之戰準備的差不多了。但是你和我仍要盡自己的責任。\n\n我被要求收集大量的厚皮做為戰爭材料，而我需要你去幫我收集。如果你決定幫忙，那就代表了部落的榮耀和感激。你會幫忙嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8592] = {title = "神諭者的冠冕", objective = "將維克尼拉斯的頭環、2個先知塑像、5隻銀色甲蟲和5隻白骨甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成此任務。", description = "雙子帝王...他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。\n\n我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的...我會將這些其拉的飾品轉變為適合我們需求的東西。\n\n幫我把我要的材料帶來，<name>。我會給你一頂有著無與倫比能量的首盔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神諭者的冠冕"}
MultiLanguageQuestData['tw'][8593] = {title = "神諭者的長褲", objective = "將奧羅的外皮、2個生命塑像、5隻金色甲蟲和5隻泥土甲蟲帶給安其拉的坎多斯塔茲。同時，你一定要在諾茲多姆的子嗣達到友好聲望值才能完成這個任務。", description = "你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。\n\n古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。\n\n他的皮膚很奇怪...很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。\n\n幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神諭者的長褲"}
MultiLanguageQuestData['tw'][8594] = {title = "神諭者的披肩", objective = "帶回其拉命令束腕、2座重生塑像、5隻銀色甲蟲和5隻象牙甲蟲給在安其拉的安多葛斯。同時你必須在諾茲多姆的子嗣達到中立的聲望值才能完成此項任務。", description = "據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。\n\n幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神諭者的披肩"}
MultiLanguageQuestData['tw'][8595] = {title = "人類勝利者", objective = "殺死其拉主使者對人類而言是個顯著的成就，<name>。無論如何，他們擁有強大的能量與數量。繼續對抗他們以證明自己成為我們勇士的價值。", description = nil, progress = "殺死其拉主使者對人類而言是個顯著的成就，<name>。無論如何，他們擁有強大的能量與數量。繼續對抗他們以證明自己成為我們勇士的價值。", completion = "你繼續好好的效忠我們吧，&lt;name&gt;。我們的協定依然存在。", rewards = nil}
MultiLanguageQuestData['tw'][8596] = {title = "神諭者的裹足", objective = "將其拉命令束腕、2個死亡塑像、5個青銅甲蟲和5個金色甲蟲帶給安其拉的坎多斯塔茲。此任務還需要在諾茲多姆的子嗣為中立的陣營。", description = "其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。\n\n幫我把其拉命令束腕和其他次要材料帶來，我就能為你製作一雙強大的靴子。\n\n你會在對抗敵人時發現它們很有用的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神諭者的裹足"}
MultiLanguageQuestData['tw'][8597] = {title = "龙语傻瓜教程", objective = "寻找纳瑞安埋在南海的某座小岛上的书。", description = "我就知道总有一天这本书会有用的！幸运的是，我已经学聪明了！我把它藏了起来。\n\n不要担心，它被放在谁都找不到的地方！嗯，我需要搭乘一架直升飞机才可以到那里去。不幸的是，在我回来的路上，飞机坠毁了。就是因为这次事故，我才获得了超级侏儒精神力量！\n\n到天涯海滩那边去寻找坠毁的直升飞机，然后往南边游！你到了那里就会看到的！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8598] = {title = "敲诈", objective = "把勒索信交给塔纳利斯的纳瑞安。", description = "<便笺上用不同的字体拼凑出一段话。>\n\n我们已经拿到了你宝贵的书，侏儒。如果你想再见到它的话，那么你就必须按照我们说的来做。\n\n<以下是长达3页的具体指示说明。>\n\n把钱带来，只需你一个人来！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8599] = {title = "唱给纳瑞安的情歌", objective = "把米莉蒂丝的情书交给塔纳利斯的纳瑞安。", description = "并不是总是有人来拜访我。上一次有人来拜访，还是那次我把那个可爱的侏儒从坠毁的机器中救出来的时候。\n\n<米莉蒂丝若有所思。>\n\n你认识他吗？他叫纳瑞安……哦，如果有人可以替我给他传个话，那就太好了。我一定要告诉他我的感觉！我知道这就是爱！就是这样的！\n\n你可以帮我传话给纳瑞安吗？我永远都不会忘记你的！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8600] = {title = "部落需要硬甲皮!", objective = "帶10張硬甲皮給奧格瑪精神谷的塞拉圖斯。", description = "我發現刀子握在掌心的適合度遠比刀口的鋒利重要。即使是最鈍的刀劍也能在危急時發揮作用。但是你和我沒有這種問題，畢竟我們總會讓刀鋒維持在最利的狀態。\n\n對吧?嗯，不重要。我有個任務要給你，<class>。為了部落，還有你對安其拉之戰該盡的職責，我要你去收集很多硬甲皮給我。你能做到嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8602] = {title = "風暴召喚者肩鎧", objective = "將其拉統御束腕、2個生命塑像、5隻金色甲蟲和5隻水晶甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。", description = "據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。\n\n幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n風暴召喚者肩鎧"}
MultiLanguageQuestData['tw'][8603] = {title = "神諭者的法衣", objective = "將上古之神的外殼、2個死亡塑像、5隻石甲蟲和5隻水晶甲蟲帶給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。", description = "最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。\n\n當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。\n\n完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲...一件只有弒神者才有資格獲得的護甲!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神諭者的法衣"}
MultiLanguageQuestData['tw'][8604] = {title = "部落需要絨線繃帶!", objective = "帶20個絨線繃帶給奧格瑪精神谷的醫者朗蘭納。", description = "你好，<class>。為了安其拉戰役的準備，我在這裡協調部落收集絨線繃帶的事。戰場上，我們的士兵們無法仰賴醫者得以生存。因此，我們要將這些急救工具收集好給他們。\n\n如果你有時間，我需要很多的絨線繃帶。把它們拿來給我，我就會好好地獎勵你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8606] = {title = "螳螂捕蝉！", objective = "塔纳利斯的纳瑞安要你去冬泉谷，把一袋金子放在绑匪的勒索信上所写的位置。他还要求你教训一下那些家伙！", description = "我终于想到了！我们应该这样做。我要给袋子里装满石头，然后你来负责送货。我知道他们说应该由我亲自送去之类的。\n\n<纳瑞安上下打量着你。>\n\n嗯，你也可以完成这个任务。戴上这条头巾，穿上这件长袍，拿着这袋石头，去冬泉谷的交货地点吧。\n\n我在这个工具包中帮你准备了所有必需的东西。当他们冒出来拿货的时候，就干掉他们！让他们知道惹毛了纳瑞安的下场！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8607] = {title = "部落需要魔紋布繃帶!", objective = "帶20個魔紋布繃帶給奧格瑪精神谷的卡隆女士。", description = "我相信你跟我說話是因為你要幫忙我收集東西吧?很好!不管用什麼方法，我是說真的喔，我希望你去收集很多魔紋布繃帶。越新鮮的越好，但不一定要新鮮。把它們帶來給我，<class>，我就會親自酬謝你的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8609] = {title = "部落需要符文布繃帶!", objective = "帶20個符文布繃帶給奧格瑪精神谷的尼根‧陶蹄。", description = "看來安其拉戰役會造成部落和聯盟間不可避免的衝突。但令人驚訝的是，這不是場雙方間的戰爭，而是對抗異種蠍和控制他們的力量。雙方都在收集打一場勝仗所需的資源。\n\n我在收集要分配給士兵們的符文布繃帶。但是我沒有協助是不會成功的。你能幫我這個忙嗎，<class>?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8611] = {title = "部落需要瘦狼排!", objective = "帶20塊瘦狼排給奧格瑪精神谷的血衛士拉爾塔。", description = "我站在這裡不是為了曬成好看的小麥色，<class>。是為了戰爭作準備。如果我們要消滅安其拉那些蟲子，那麼我們就要準備好，包括食物!\n\n他們要我為即將來臨的戰爭收集並醃製瘦狼排。但是我必須留在這裡處理事情，所以我需要你去殺一些狼，並將它們的肉烹煮成瘦狼排再帶來給我。你聽懂了嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8613] = {title = "部落需要斑點黃尾魚!", objective = "帶20條有斑點的黃尾魚給奧格瑪精神谷的漁夫林度。", description = "今天是個釣魚的好日子，你不覺得嗎?這樣很好，因為我正需要很多的魚。部落要我負責收集一噸有斑點的黃尾魚。他們說是安其拉戰役需要的。我說我會盡力而為。所以我需要一些幫忙。你會幫我吧，<class>?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8615] = {title = "部落需要烤鮭魚!", objective = "帶20條烤鮭魚給奧格瑪精神谷的圖拉‧利爪。", description = "安其拉之戰是一項浩大的工程，<class>。這裡收集的所有材料，不管是武器要用的金屬，還是要吃的食物，所有的東西都一樣重要。如果你好幾天沒吃東西就會沒有力氣在必要時舉起你的斧頭。\n\n因此，我們盡量收集食物。我正在收集烤鮭魚，好保存又營養。你可以幫我這個忙嗎，<class>?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n部落榮譽徽章安其拉軍用補給品"}
MultiLanguageQuestData['tw'][8617] = {title = "部落需要熔火之石！", objective = "把50块熔火之石交给奥格瑞玛精神谷的佐格将军。", description = "是时候让你为安其拉之战做出贡献了，<class>。你不能继续这样游手好闲下去。现在是你为我和部落效劳的时候，而且我可不想酋长那样宽大仁慈。\n\n你必须组织起强大的力量，最好是整个公会的力量，深入熔火之心。在那里，你可以找到很多被称为熔火之石的东西。把它们都交给我。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8619] = {title = "深晨長者", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n先祖硬幣幸運紅包袋"}
MultiLanguageQuestData['tw'][8620] = {title = "唯一的方案", objective = "把8章《龙语傻瓜教程》的章节用魔法书封面合起来，然后把完整的《龙语傻瓜教程：第二卷》交给塔纳利斯的纳瑞安。", description = "我就知道，我最大的敌人，维维尔博士又开始玩他那老一套了！现在，由于你在冬泉谷的失败，维维尔把我的书给毁掉了！你现在还怎么拯救世界，大英雄？\n\n我收集到的仅存的《龙语傻瓜教程：第二卷》被撕成8份，散落在世界各地！如果你可以收集到这些遗失的章节，那么就用这个魔法书封面把它们合在一起，然后给我带回来。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n精神力量之地精頭巾"}
MultiLanguageQuestData['tw'][8621] = {title = "風暴召喚者護足", objective = "將其拉統御束腕、2個先知塑像、5隻青銅甲蟲和5隻泥土甲蟲帶給安其拉的坎多斯塔茲。你一定要在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。", description = "其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。\n\n幫我把其拉統御束腕和其他次要材料帶來，我就為你製作一雙強大的靴子。\n\n你會在對抗敵人時發現它們的威力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n風暴召喚者護足"}
MultiLanguageQuestData['tw'][8622] = {title = "風暴召喚者鍊衫", objective = "帶回上古之神的甲殼、2個先知塑像、5隻銀色甲蟲和5隻白骨甲蟲給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。", description = "最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界在不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。\n\n當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。\n\n完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲...一件只有弒神者才有資格獲得的護甲!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n風暴召喚者鍊衫"}
MultiLanguageQuestData['tw'][8623] = {title = "風暴召喚者冠冕", objective = "將維克洛爾的王冠、2個重生塑像、5隻石甲蟲和5隻水晶甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此項任務。", description = "雙子帝王...他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。\n\n我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的...我會將這些其拉的飾品轉變為適合我們需求的東西。\n\n幫我把我要的材料帶來，<name>。我會給你一頂有著無與倫比能量的首盔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n風暴召喚者冠冕"}
MultiLanguageQuestData['tw'][8624] = {title = "風暴召喚者護腿", objective = "將巨型沙蟲的皮、2個征戰塑像、5隻青銅甲蟲和5隻象牙甲蟲給安其拉的坎多斯塔茲。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此任務。", description = "你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。\n\n古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。\n\n他的皮膚很奇怪...很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。\n\n幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n風暴召喚者護腿"}
MultiLanguageQuestData['tw'][8625] = {title = "神秘肩墊", objective = "帶回其拉統御束腕、2個死亡塑像、5隻石甲蟲和5隻青銅甲蟲給安其拉的安多葛斯。同時你必須在諾茲多姆的子嗣達到中立的聲望值才能完成此項任務。", description = "據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。\n\n幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n謎團肩墊"}
MultiLanguageQuestData['tw'][8626] = {title = "打擊者的護足", objective = "帶其拉命令束腕、2個生命塑像、5隻石甲蟲和5隻白骨甲蟲給安其拉的坎多斯塔茲。同時你必須在諾茲多姆的子嗣達到中立的聲望值才能完成此任務。", description = "其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。\n\n幫我把其拉命令束腕和其他次要材料帶來，我就為你製作一雙強大的靴子。\n\n你會在對抗敵人時發現它們的威力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n打擊者的護足"}
MultiLanguageQuestData['tw'][8627] = {title = "復仇者的胸甲", objective = "帶回上古之神的甲殼、2個先知塑像、5隻銀色甲蟲和5隻白骨甲蟲給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。", description = "最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。\n\n當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。\n\n完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲...一件只有弒神者才有資格獲得的護甲!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n復仇者的胸甲"}
MultiLanguageQuestData['tw'][8628] = {title = "復仇者之冠", objective = "將維克洛爾的王冠、2個重生塑像、5隻石甲蟲和5隻水晶甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此項任務。", description = "雙子帝王...他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。\n\n我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的...我會將這些其拉的飾品轉變為適合我們需求的東西。\n\n幫我把我要的材料帶來，<name>。我會給你一頂有著無與倫比能量的首盔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n復仇者之冠"}
MultiLanguageQuestData['tw'][8629] = {title = "復仇者的腿甲", objective = "將巨型沙蟲的皮、2個征戰塑像、5隻青銅甲蟲和5隻象牙甲蟲給安其拉的坎多斯塔茲。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此任務。", description = "你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。\n\n古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。\n\n他的皮膚很奇怪...很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。\n\n幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n復仇者的腿甲"}
MultiLanguageQuestData['tw'][8630] = {title = "復仇者的肩鎧", objective = "將其拉統御束腕、2個生命塑像、5隻水晶甲蟲和5隻金色甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。", description = "據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。\n\n幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n復仇者的肩鎧"}
MultiLanguageQuestData['tw'][8631] = {title = "神秘護腿", objective = "帶回奧羅的外皮、2個先知塑像、5隻銀色甲蟲和5隻白骨甲蟲給安其拉的坎多斯塔茲。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此任務。", description = "你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。\n\n古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。\n\n他的皮膚很奇怪...很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。\n\n幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n謎團護腿"}
MultiLanguageQuestData['tw'][8632] = {title = "神秘頭環", objective = "將維克尼拉斯的頭環、2個夜晚塑像、5隻青銅甲蟲和5隻象牙甲蟲給在安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此任務。", description = "雙子帝王...他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。\n\n我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的...我會將這些其拉的飾品轉變為適合我們需求的東西。\n\n幫我把我要的材料帶來，<name>。我會給你一頂有著無與倫比能量的首盔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘頭環"}
MultiLanguageQuestData['tw'][8633] = {title = "謎團長袍", objective = "將上古之神的外殼、2個太陽塑像、5隻金色甲蟲和5隻泥土甲蟲帶給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。", description = "最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。\n\n當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。\n\n完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲...一件只有弒神者才有資格獲得的護甲!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n謎團長袍"}
MultiLanguageQuestData['tw'][8634] = {title = "神秘長靴", objective = "將其拉統御束腕、2個太陽塑像、5隻銀色甲蟲和5隻水晶甲蟲帶給安其拉的坎多斯塔茲。你一定要在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。", description = "其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。\n\n幫我把其拉統御束腕和其他次要材料帶來，我就能為你製作一雙強大的靴子。\n\n你會在對抗敵人時發現它們很有用的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n謎團長靴"}
MultiLanguageQuestData['tw'][8635] = {title = "劈石長者", objective = "戰爭的歷史是傳奇茁壯的種子。你正處於英雄的時代，年輕人。願你的英勇傳奇深植人心、源遠流長。\n\n祝你平安， <name>，這是你應有的獎賞...", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n先祖硬幣幸運紅包袋"}
MultiLanguageQuestData['tw'][8636] = {title = "巨石長者", objective = "萬物皆難逃一死，但精神卻永垂不朽。祝你平安， <name>，這是給你的獎賞...", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n先祖硬幣幸運紅包袋"}
