MultiLanguageQuestData['tw'][8730] = {title = "奈法里奥斯的腐蚀", objective = "干掉奈法利安并拿到红色节杖碎片。把红色节杖碎片带给塔纳利斯时光之穴门口的阿纳克洛斯。你必须在5小时之内完成这个任务。", description = "勇士，是你吗？我受命保管这个碎片已经一千年了，在我最黑暗的时候，应该有人站出来替我把它拿回来……但是一切都是任重道远的。\n\n<瓦拉斯塔兹轻轻地咳嗽着。>\n\n耐……耐法里奥斯现在掌握着节杖碎片。\n\n时间是最关键的。耐法里奥斯将要摧毁这个节杖。你必须赶快！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "黑瑪瑙鑲飾護腿您能選擇下列奬勵中的一個：\n\n暗影遮罩護符"}
MultiLanguageQuestData['tw'][8733] = {title = "伊兰尼库斯，梦境之暴君", objective = "到达纳苏斯的城墙外去找到玛法里奥的亲信。", description = "这将是一段救赎之旅，英雄。如果今天我要死去，那么我也要为了一个正义而伟大的事业而牺牲。你必须找到绿色节杖碎片，你必须净化被上古之神控制的伊兰尼库斯。\n\n到达纳苏斯去，在城墙外，你可以找到我的人。这个人将会为我们进行协调，并在不让鹿盔发现的情况下将我们的计划通知给泰兰德。\n\n<玛法里奥叹了口气。>\n\n一千年的守护终究堕落了……完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][8737] = {title = "灰烬公爵", objective = "设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。", description = "暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。\n\n根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧戰術徽章後續戰術指令"}
MultiLanguageQuestData['tw'][8738] = {title = "雷戈虫巢侦查报告", objective = "在雷戈虫巢内找到塞纳里奥斥候兰迪奥，然后把雷戈虫巢侦查报告交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着战术任务简报 VII才能完成这个任务。", description = "我们派出了最好的斥候深入异种虫类的巢穴收集情报。兰迪奥这几天来一直在监视佐拉虫巢，去找到他，拿回他的书面报告。我们需要这些情报来制定战术，要尽快，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧戰術徽章後續戰術指令"}
MultiLanguageQuestData['tw'][8739] = {title = "灰烬公爵", objective = "设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。", description = "暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。\n\n根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧戰術徽章戰術指令"}
MultiLanguageQuestData['tw'][8740] = {title = "暮光掠夺者", objective = "干掉暮光掠夺者莫娜和2个暮光掠夺者。任务完成之后向唤风者梅恩·长角报告。你还必须随身携带战术任务简报 IX以完成这个任务。", description = "许多幕光之锤的骑兵教徒经常在我们塞纳里奥要塞守卫范围之外的区域游荡，并伺机袭击我们巡逻和商旅小队。\n\n找到并击败暮光掠夺者和他们的领袖，一个叫做莫娜的恐怖战士。当任务完成之后向唤风者梅恩·长角报告。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧戰術徽章後續戰術指令"}
MultiLanguageQuestData['tw'][8744] = {title = "仔細包裝的禮物", objective = "這個禮物上的標籤寫著:\n\n給<name>，\n\n祝你的冬幕節充滿快樂及喜悅!", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n仔細包裝的禮物"}
MultiLanguageQuestData['tw'][8746] = {title = "驯鹿梅森", objective = "前往希尔斯布莱德丘陵的无草洞附近解救驯鹿梅森，并击败绑匪。", description = "出大事啦！驯鹿梅森被绑架了！\n\n梅森是冬天爷爷的八头驯鹿之一，也是烟林牧场的财产。我们相信，是那个讨厌的格林奇绑架了梅森，并把它藏在了希尔斯布莱德丘陵里。由于冬幕节正在进行中，我们完全脱不开身！拜托了——请你找到梅森，击败绑匪并把它带回来！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n保存的冬青"}
MultiLanguageQuestData['tw'][8747] = {title = "保衛者之路", objective = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the defender will offer superior protection against the forces of evil.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", description = nil, progress = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the defender will offer superior protection against the forces of evil.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", completion = nil, rewards = "您會收到：\n\n青銅龍軍團的徽記之戒"}
MultiLanguageQuestData['tw'][8748] = {title = "保衛者之路", objective = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", description = nil, progress = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", completion = "Your rise amongst the rank of the Brood is most impressive, &lt;name&gt;. May you never stray from the path of the protector!", rewards = "您會收到：\n\n青銅龍軍團的徽記之戒"}
MultiLanguageQuestData['tw'][8749] = {title = "保衛者之路", objective = "You honor my kind, <name>. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", description = nil, progress = "You honor my kind, <name>. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", completion = "Your rise amongst the rank of the Brood is most impressive, &lt;name&gt;. May you never stray from the path of the protector!", rewards = "您會收到：\n\n青銅龍軍團的徽記之戒"}
MultiLanguageQuestData['tw'][8750] = {title = "保衛者之路", objective = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, <name>. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", description = nil, progress = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, <name>. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", completion = "Your rise amongst the rank of the Brood is most impressive, &lt;name&gt;. May you never stray from the path of the protector!", rewards = "您會收到：\n\n青銅龍軍團的徽記之戒"}
