MultiLanguageQuestData['tw'][8759] = {title = "塑能師之道", objective = "You honor my kind, <name>. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", description = nil, progress = "You honor my kind, <name>. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", completion = "Your rise amongst the rank of the Brood is most impressive, &lt;name&gt;. May you never stray from the path of the invoker!", rewards = "您會收到：\n\n青銅龍軍團的徽記之戒"}
MultiLanguageQuestData['tw'][8761] = {title = "大塑能師", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n青銅龍軍團的徽記之戒"}
MultiLanguageQuestData['tw'][8762] = {title = "驯鹿梅森", objective = "前往希尔斯布莱德丘陵的无草洞附近解救驯鹿梅森，并击败绑匪。", description = "出大事啦！驯鹿梅森被绑架了！\n\n梅森是冬天爷爷的八头驯鹿之一，也是烟林牧场的财产。我们相信，是那个讨厌的格林奇绑架了梅森，并把它藏在了希尔斯布莱德丘陵里。由于冬幕节正在进行中，我们完全脱不开身！拜托了——请你找到梅森，击败绑匪并把它带回来！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n保存的冬青"}
MultiLanguageQuestData['tw'][8764] = {title = "遠離保衛者之路", objective = nil, description = nil, progress = nil, completion = nil, rewards = "青銅龍軍團的徽記之戒青銅龍軍團的徽記之戒"}
MultiLanguageQuestData['tw'][8765] = {title = "遠離塑能師之道", objective = "Champion, should you decide to walk another path, present me with your signet ring and a mountain of scarabs from our enemies in Ahn'Qiraj.", description = nil, progress = "Champion, should you decide to walk another path, present me with your signet ring and a mountain of scarabs from our enemies in Ahn'Qiraj.", completion = "Be well, &lt;name&gt;. If you change your mind, I shall be here to assist you.", rewards = "青銅龍軍團的徽記之戒青銅龍軍團的徽記之戒"}
