MultiLanguageQuestData['tw'][8768] = {title = "精心包裝的禮物", objective = "這件禮物上面寫著你的名字。\n\n等等，它剛才好像動了一下?", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n精心包裝的禮物"}
