MultiLanguageQuestData['tw'][8770] = {title = "目標:亞什防衛者", objective = "殺死30隻亞什防衛者再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報  I帶去才能完成這個任務。", description = "這一地區猖獗的異種蟲群對我們來說是個巨大的威脅。你被指派負責對亞什蟲巢發動攻擊，主要目標是亞什防衛者。\n\n在你的任務完成之後，向指揮官瑪爾利斯回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8771] = {title = "目標:亞什沙巡者", objective = "殺死30隻亞什沙巡者再到希利蘇斯向塞納里奧城堡的指揮官瑪爾利斯回報。你還必須將作戰任務簡報  II帶去才能完成這個任務。", description = "這一地區猖獗的異種蟲群對我們來說是個巨大的威脅。你被指派負責對亞什蟲巢發動攻擊，主要目標是亞什沙巡者。\n\n在你的任務完成之後，向指揮官瑪爾利斯回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8772] = {title = "目標:佐拉守衛", objective = "殺死30隻佐拉守衛再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報  VI帶去才能完成這個任務。", description = "我們需要援軍進攻佐拉蟲巢。你的主要目標是那些佐拉守衛，當你的任務完成之後就去向指揮官瑪爾利斯報告。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8773] = {title = "目標:佐拉劫奪者", objective = "殺死30隻佐拉劫奪者再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報 IV帶去才能完成這個任務。", description = "我們需要援軍進攻佐拉蟲巢。你的主要目標是那些佐拉劫奪者，當你的任務完成之後就去向指揮官瑪爾利斯報告。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8774] = {title = "目標:雷戈伏擊者", objective = "殺死30隻雷戈伏擊者再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報 VIII帶去才能完成這個任務。", description = "這一地區猖獗的異種蟲群對我們來說是個巨大的威脅。你被指派負責對雷戈蟲巢發動攻擊，主要目標是雷戈伏擊者。\n\n在你的任務完成之後，向指揮官瑪爾利斯回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8775] = {title = "目標:雷戈噴火者", objective = "殺死30隻雷戈噴火者再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報  IX帶去才能完成這個任務。", description = "這一地區猖獗的異種蟲群對我們來說是個巨大的威脅。你被指派負責對雷戈蟲巢發動攻擊，主要目標是雷戈噴火者。\n\n在你的任務完成之後，向指揮官瑪爾利斯回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8776] = {title = "目標:雷戈制奴者", objective = "殺死30隻雷戈制奴者再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報  X帶去才能完成這個任務。", description = "這一地區猖獗的異種蟲群對我們來說是個巨大的威脅。你被指派負責對雷戈蟲巢發動攻擊，主要目標是雷戈制奴者。\n\n在你的任務完成之後，向指揮官瑪爾利斯回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8777] = {title = "目標:雷戈掘洞者", objective = "殺死30隻雷戈掘洞者再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報  XI帶去才能完成這個任務。", description = "這一地區猖獗的異種蟲群對我們來說是個巨大的威脅。你被指派負責對雷戈蟲巢發動攻擊，主要目標是雷戈掘洞者。\n\n在你的任務完成之後，向指揮官瑪爾利斯回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧作戰徽章"}
MultiLanguageQuestData['tw'][8778] = {title = "铁炉堡军团需要爆炸品！", objective = "把6瓶献祭之油、5瓶地精火箭燃油和10份致密炸药粉交给希利苏斯地区的佐拉虫巢附近的奥术师诺斯宾。你还必须带着后勤任务简报 IV才能完成这个任务。", description = "铁炉堡军团突然要求我们提供一批高度危险的……材料。收集必需的物资，把他们交给铁炉堡军团的诺斯宾先生。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8779] = {title = "研究材料", objective = "把1份大块魔光碎片、1份大块强光碎片和1块巨型绿宝石交给希利苏斯塞纳里奥要塞的地质学家拉克斯班。你还必须随身带着后勤任务简报 V才能完成这个任务。", description = "地质学家拉克斯班的研究对于我们在希利苏斯的行动很有帮助，她最近需要一些特别的材料，以进行更多的研究。\n\n请收集这些材料，把它们交给拉克斯班。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8780] = {title = "战场上的护甲片", objective = "将8块毛皮护甲片和8块重型护甲片交给佐拉虫巢附近的珍妮拉·硬锤。你还必须随身带着后勤任务简报 VII才能完成这个任务。", description = "我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8781] = {title = "战场上的武器", objective = "将2把月钢宽剑交给佐拉虫巢附近的珍妮拉·硬锤。你还必须随身带着后勤任务简报 VI才能完成这个任务。", description = "我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8782] = {title = "制服供应", objective = "把1块月布、2卷符文布卷和1份铁网蛛丝交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着后勤任务简报 VIII才能完成这个任务。", description = "战场的绷带储存量在最近战争伤亡之后急剧降低。把大量的急救物资带给塞纳里奥要塞的唤风者梅恩·长角。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8783] = {title = "特殊的材料", objective = "把2块魔化瑟银锭和2块魔化皮交给希利苏斯塞纳里奥要塞的瓦古斯。你还必须随身带着后勤任务简报 IX才能完成这个任务。", description = "瓦古斯是塞纳里奥要塞的铁匠，他需要一些附魔材料来为我们的部队制作强力的武器。去找到这些材料，把它们直接交给瓦古斯，这样塞纳里奥议会的军队就有了作战装备的保障。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8784] = {title = "其拉軍的秘密", objective = "將這個上古其拉神器帶給藏在神廟入口附近的巨龍。", description = "你發現了一個上古其拉神器!或許神廟入口附近的巨龍之一需要這個聖物。", progress = "你看起來容光煥發!我知道這代表什麼...", completion = "真是重大的發現，&lt;name&gt;。簡直是太驚人了!這絕對會讓我們對敵人古怪的心理多點了解。", rewards = nil}
MultiLanguageQuestData['tw'][8785] = {title = "奥格瑞玛军团需要魔精！", objective = "把6份强力魔精、6份大瓶魔精和8份献祭之油交给希利苏斯地区的雷戈虫巢附近的暗影祭司沙艾。你还必须随身带着后勤任务简报 IV才能完成这个任务。", description = "奥格瑞玛军团要求我们提供一些不寻常的物资。他们在希利苏斯的表现很不错，因此我们最好尽快满足他们的需求。收集必需的材料，把它们交给那个名叫沙艾的巨魔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8786] = {title = "战场上的武器", objective = "将3把巨型铁斧交给雷戈虫巢附近的梅洛克·远途。你还必须随身带着后勤任务简报 VI才能完成这个任务。", description = "奥格瑞玛军团需要更多的武器，但我们手头也很吃紧。想办法弄到他们要的武器，然后把东西交给雷戈虫巢附近的梅洛克·远途。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8787] = {title = "战场上的护甲片", objective = "将8块毛皮护甲片和8块重型护甲片交给雷戈虫巢附近的梅洛克·远途。你还必须随身带着后勤任务简报 VII才能完成这个任务。", description = "奥格瑞玛军团的志愿者赶来帮助我们作战，但是他们的护甲片在旅途中丢失了。去收集一些护甲片，把东西交给雷戈虫巢附近的梅洛克·远途。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8788] = {title = "輕輕搖晃過的禮物", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n輕輕搖晃過的禮物"}
MultiLanguageQuestData['tw'][8789] = {title = "其拉帝王武器", objective = "把其拉帝王武器和3塊源質錠交給安其拉神廟的亞雷戈斯，他會幫你製作使用源質灌注的武器。", description = "一千年以來，我們並沒有無所事事地留在這裡，<name>。\n\n我們在這裡看著這些野獸耗盡資源時自相殘殺，我們傾聽了它們密謀毀滅我們世界的談話，我們還知道了它們內部的爭權奪利。\n\n它們確實有弱點，而且我們知道如何利用這些弱點。\n\n找到它們在葬禮儀祭上陪葬用的武器，把它和他們自己的神所創造的最強的元素融合在一起，我們就可以創造出終結一切的武器。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "其拉祝福戰斧其拉祝福短匕刃其拉祝福壁壘其拉祝福火槍"}
MultiLanguageQuestData['tw'][8790] = {title = "其拉帝王標誌", objective = "如果你能將其拉帝王徽記和3個源質錠帶給安其拉神廟『夢境之龍』麥琳瑟拉，她就能為你製作源質灌注的武器。", description = "亞雷戈斯認為，在一定情況下，因上古諸神和他們的僕從之間的衝突而產生的元素也會對他們本身造成致命的威脅。凡人，我指的是源質。\n\n將其拉帝王徽記和這種元素交給我，我就能為武器注入巨大的力量。", progress = "你會將他們擊敗並讓我們脫離這些束縛。", completion = "好好使用這個物品，&lt;name&gt;。讓他們嚐嚐自己附加在別人身上的痛苦。", rewards = "其拉祝福戰錘其拉祝福侍僧法杖其拉祝福占兆法杖"}
MultiLanguageQuestData['tw'][8791] = {title = "奧斯里安的隕落", objective = "將『無疤者』奧斯里安的頭顱帶到希利蘇斯給塞納里奧城堡的指揮官瑪爾利斯。", description = "來自其拉蟲群的威脅已經被平息。可怕的奧斯里安已被擊敗。\n\n卡林多的居民知道這樣的勝利都會如釋重負。將奧斯里安的頭顱帶給塞納里奧城堡的指揮官瑪爾利斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "流沙符咒流沙頸飾流沙墜飾流沙護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][8792] = {title = "部落需要你的帮助！", objective = "和奥格瑞玛精神谷的督军格尔库克谈一谈。你好，我很高兴你愿意听我说话。部落需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，<name>！\n\n你应该和负责此事的督军格尔库克谈一谈。你觉得怎么样？你是否愿意帮助部落做好战争的准备？完成任務後，你將獲得：\n\n", description = "你好，我很高兴你愿意听我说话。部落需要一切可以获得的帮助来准备发动安其拉战争，这意味着，我们需要你！现在，官方的资源收集者正在收集必需的资源储备，但是如果没有你的帮助的话，我们是无法达成目标的，<name>！\n\n你应该和负责此事的督军格尔库克谈一谈。你觉得怎么样？你是否愿意帮助部落做好战争的准备？完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
