MultiLanguageQuestData['tw'][8801] = {title = "克蘇恩的遺產", objective = "將克蘇恩之眼帶給安其拉神廟的凱雷斯塔茲。", description = "安其拉的高牆劇烈搖晃，遠比這世界還古老的邪惡力量總算被消滅了。\n\n當你注視著這個巨大怪物的遺體時，心跳彷彿就此凍結。即使克蘇恩已遭擊殺，你還是能感覺到它邪惡的力量依然殘留在四周。\n\n你完成了這個近乎不可能的任務。\n\n你取下怪物的眼梗，小心放進你的包包裡。\n\n把克蘇恩之眼帶到下一個房間裡的巨龍那兒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8802] = {title = "卡林多的救星", objective = "把克蘇恩之眼帶給時光之穴的安納克羅斯。", description = "前往時光之穴，<大人/女士><name>。安納克羅斯等著你回來。把克蘇恩之眼交給他，他絕對會將它放在主人的收集品裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "墮落之神之戒墮落之神披風墮落之神護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][8803] = {title = "節慶禮物", objective = "這個禮物上的便條紙寫著:\n\n給<name>，\n\n希望這個禮物可以幫助你將溫暖及節日的喜悅散播到整個艾澤拉斯大陸。\n\n冬天爺爺敬贈", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n節慶禮物"}
MultiLanguageQuestData['tw'][8804] = {title = "沙漠生存包", objective = "把4份纯水之球、4份特效抗毒药剂和4份烤鲑鱼交给希利苏斯塞纳里奥要塞的卡兰德拉斯。你还必须随身带着后勤任务简报 I才能完成这个任务。", description = "目前塞纳里奥要塞涌入了大量的新兵，我们的首要问题就成了如何保证他们在沙漠中生存下来。缺水的环境和遍布希利苏斯的剧毒生物都威胁着这些缺乏经验的志愿者。去收集一些必需的物资，把他们交给要塞里的卡兰德拉斯吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8805] = {title = "卫兵的护甲片", objective = "把3双精制秘银战靴交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 II才能完成这个任务。", description = "目前塞纳里奥要塞的骑兵团缺乏足够的毛皮护甲片，去收集大量护甲片，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8806] = {title = "卫兵的磨刀石", objective = "把10块致密砂轮、10块坚固的砂轮和10块重砂轮交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 III才能完成这个任务。", description = "塞纳里奥要塞的卫兵急需磨刀石。去收集足够的磨刀石，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8807] = {title = "研究材料", objective = "把1份大块魔光碎片、1份大块强光碎片和1块巨型绿宝石交给希利苏斯塞纳里奥要塞的地质学家拉克斯班。你还必须随身带着后勤任务简报 V才能完成这个任务。", description = "地质学家拉克斯班的研究对于我们在希利苏斯的行动很有帮助，她最近需要一些特别的材料，以进行更多的研究。\n\n请收集这些材料，把它们交给拉克斯班。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8808] = {title = "制服供应", objective = "把1块月布、2卷符文布卷和1份铁网蛛丝交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着后勤任务简报 VIII才能完成这个任务。", description = "最近不断涌来的志愿者导致我们制服紧缺。去搜集一些制服的材料，然后把它们交给唤风者梅恩·长角。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8809] = {title = "特殊的材料", objective = "把2块魔化瑟银锭和2块魔化皮交给希利苏斯塞纳里奥要塞的瓦古斯。你还必须随身带着后勤任务简报 IX才能完成这个任务。", description = "瓦古斯是塞纳里奥要塞的铁匠，他需要一些附魔材料来为我们的部队制作强力的武器。去找到这些材料，把它们直接交给瓦古斯，这样塞纳里奥议会的军队就有了作战装备的保障。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令"}
MultiLanguageQuestData['tw'][8810] = {title = "战场上的绷带", objective = "把30根重符文绷带，30根厚丝质绷带和30根厚绒线绷带带给唤风者梅恩·长角。你还必须随身带着后勤任务简报 X才能完成这个任务。", description = "我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
