MultiLanguageQuestData['tw'][8856] = {title = "沙漠生存包", objective = "把4份纯水之球、4份特效抗毒药剂和4份烤鲑鱼交给希利苏斯塞纳里奥要塞的卡兰德拉斯。", description = "目前塞纳里奥要塞涌入了大量的新兵，我们的首要问题就成了如何保证他们在沙漠中生存下来。缺水的环境和遍布希利苏斯的剧毒生物都威胁着这些缺乏经验的志愿者。去收集一些必需的物资，把他们交给要塞里的卡兰德拉斯吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納里奧後勤徽章後勤指令 2"}
MultiLanguageQuestData['tw'][8857] = {title = "亚什巨像的秘密", objective = "把亚什巨像的獠牙交给藏宝海湾的奥格索普·奥布诺提斯。", description = "我正在寻找那些经过战争洗礼的冒险者，看他们是否愿意从亚什巨像的尸体上取到新鲜的獠牙样本，并把它交给藏宝海湾的奥格索普。不，不，我可不希望你在那家伙的尸体附近游荡。你只需迅速取回样本，这东西腐烂了就不好办了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大袋的戰利品"}
MultiLanguageQuestData['tw'][8858] = {title = "雷戈巨像的秘密", objective = "把雷戈巨像的獠牙交给灼热峡谷的工头奥菲斯特。", description = "我最想做的就是将这块獠牙套到奥菲斯特那肥硕的脑壳上……但是，我得留在这儿从那些畸形的蟑螂身上收集样本。你瞧这工作量，我大概要到凌晨时分才能赶到那儿。\n\n替我将这份样本交给奥菲斯特，要快，<class>。他会付给你丰厚的报酬！\n\n他就在灼热峡谷的瑟银哨塔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大袋的戰利品"}
MultiLanguageQuestData['tw'][8859] = {title = "佐拉巨像的秘密", objective = "把佐拉巨像的獠牙交给东瘟疫之地圣光之愿礼拜堂的玛克斯韦尔·泰罗索斯男爵。", description = "我的仆人几乎搭上性命才取回这个样本。你必须赶快！玛克斯韦尔·泰罗索斯男爵迫切地想要一份新鲜的獠牙样本。他相信巨像背后的秘密能帮助我们对抗亡灵天灾！\n\n你怎么还在这儿？快去圣光之愿礼拜堂！当然，你会因此获得一笔丰厚的奖励……您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大袋的戰利品"}
MultiLanguageQuestData['tw'][8860] = {title = "新年慶典!", objective = "將燻木補給品帶給暴風城的旅店老闆奧里森。", description = "暴風城正在舉辦新年的慶典！那裡整天提供免費的飲料，晚上他們還會舉辦煙火表演！應該會很不錯的…但是藏寶海灣今天晚上也有個宴會，我敢說那一定更棒！\n\n總之，暴風城的旅店老闆奧里森需要燻木牧場的補給品才能應付需求量龐大的慶典。你可以幫我個忙送過去嗎？\n\n謝謝你，<name>！旅店老闆奧里森就在靠近暴風城貿易區的鑲金玫瑰旅店裡面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][8861] = {title = "新年慶典!", objective = "將燻木補給品帶給雷霆崖的旅店老闆帕拉。", description = "雷霆崖正在舉辦新年的慶典！那裡整天提供免費的飲料，晚上他們還會舉辦煙火表演！\n\n應該會很不錯的…但是藏寶海灣今天晚上也有個宴會，我敢說那一定更棒！\n\n總之，雷霆崖的旅店老闆帕拉需要燻木牧場的補給品才能應付需求量龐大的慶典。你能幫我送過去嗎？\n\n謝謝你，<name>！旅店老闆帕拉就在通往獵人高地橋邊的旅店裡面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
