MultiLanguageQuestData['tw'][9207] = {title = "光底礦物樣本", objective = "收集6個光底礦物帶到鬼魂之地的太陽聖所交給博學者奎壘司提斯。", description = "我從太陽聖所被派來這裡收集一些樣本，但是豺狼人卻橫行於這個地方！要是我不快點將那些樣本帶回去給博學者，我就要人頭落地了。<class>，說不定你可以幫幫我？\n\n你可以在這裡的錫礦和銅礦的礦脈中找到樣本，然後豺狼人也會攜帶在身上。等你收集到足夠的數量，請將它們交給太陽聖所的博學者奎壘司提斯。就在此處的正東方，過了死亡之痕，在日牧山峰的南邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9208] = {title = "野蠻護衛-保護秘紋", objective = "祖爾格拉布的『無眠者』贊札 需要1份保護秘紋。", description = "如果贊札擁有所需的成分，他就可以幫你製作不同的古老食人妖附魔!有聽過野蠻護衛嗎?什麼，沒聽過，你當然沒聽過。因為你的心靈已被那些低等的精靈魔法給遮蔽了。\n\n幫我找一份精靈的專注秘紋來，我就可以把那秘紋轉換成野蠻護衛。去吧，只要你完成這個任務，野蠻護衛就是你的了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n野蠻護衛"}
MultiLanguageQuestData['tw'][9209] = {title = "野蠻護衛-疾速秘紋", objective = "祖爾格拉布的『無眠者』贊札 需要1份疾速秘紋。", description = "如果贊札擁有所需的成分，他就可以幫你製作不同的古老食人妖附魔!有聽過野蠻護衛嗎?什麼，沒聽過，你當然沒聽過。因為你的心靈已被那些低等的精靈魔法給遮蔽了。\n\n幫我找一份精靈的專注秘紋來，我就可以把那秘紋轉換成野蠻護衛。去吧，只要你完成這個任務，野蠻護衛就是你的了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n野蠻護衛"}
MultiLanguageQuestData['tw'][9210] = {title = "野性戒卫 - 专注秘药", objective = "祖尔格拉布的无眠者赞扎需要一份专注秘药。", description = "赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。\n\n给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n野蠻護衛"}
MultiLanguageQuestData['tw'][9211] = {title = "寒冰戒卫", objective = "东瘟疫之地圣光之愿礼拜堂的愤怒者玛塔乌斯需要10枚十字军徽记和30金币。", description = "啊，寒冰戒卫。它可以在某些护甲表面生成稀薄的魔法保护光环。寒冰戒卫能在你遭受冰霜系的攻击时起到额外的保护作用。\n\n愤怒者玛塔乌斯的创造物总是相当昂贵的，就算你哭着求我，我也不会降价。你感兴趣吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n冰霜守護者"}
MultiLanguageQuestData['tw'][9212] = {title = "逃出地下墓穴", objective = "護送遊俠莉拉薩回到鬼魂之地的旅行者營地找希里歐斯隊長。", description = "這些食人妖襲擊我還把我關在這籠子裡。我想他們打算犧牲我!救我出去!\n\n籠子上的鎖看起來不是很複雜...只是我從裡面沒辦法打開。如果你讓我離開這裡並護送我回到旅行者營地，我相信希里歐斯隊長一定會獎勵你，而且我也一定會感激你!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "食人妖蹬靴食人妖蹬靴食人妖蹬靴食人妖蹬靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][9213] = {title = "暗影戒卫", objective = "东瘟疫之地圣光之愿礼拜堂的愤怒者玛塔乌斯需要10枚十字军徽记和30金币。", description = "天才的创造物！跟寒冰戒卫类似，暗影戒卫可以在某些护甲表面生成稀薄的魔法保护光环。当然，暗影戒卫跟寒冰戒卫一样价值不菲。\n\n<玛塔乌斯搓着手。>\n\n你感兴趣吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗影守護者"}
MultiLanguageQuestData['tw'][9214] = {title = "影松食人妖的軍備", objective = "收集3個獵頭者之斧、3個暗影施法者之錘、3個馭貓者之爪和3個妖術師之棍，並且回到鬼魂之地的旅行者營地交給希里歐斯隊長。", description = "<class>，我要你盡可能的殺死影松食人妖，越多越好。我們需要大幅削弱他們的實力，如此才能將我們的目標轉移對付死亡之域。既然你要去對付他們，乾脆幫我取回他們的武器。最好不要浪費這些武器，我們還可以拿來對抗天譴軍團。\n\n猛力地攻擊他們的營地吧，就在東邊的札布泰拉和南邊的札布諾瓦。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9215] = {title = "把卡爾喀旭的頭顱帶來!", objective = "將『邪惡者』卡爾喀旭的頭顱帶到鬼魂之地交給旅行者營地的希里歐斯隊長。", description = "懸賞:把影松食人妖的頭目，『邪惡者』卡爾喀旭的頭顱帶給希里歐斯隊長。不准發問。據說卡爾喀旭住在札布諾瓦南邊。\n\n\n\n獎勵:有，但不預付!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "精緻的長弓精緻的劍精緻的法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][9216] = {title = "腐爛之心", objective = "把10顆腐爛之心交給安寧地的博學者艾米諾。", description = "我聽說阿曼尼食人妖以吃掉敵人的心臟來竊取他們的力量。他們一定對某種事物很熟悉，<name>。經過適當的處理，無生命體的心臟能夠製造出強效的菁華。\n\n獵殺在死亡之痕流連的殭屍並將他們的心臟帶來給我。我會讓你見識一下這類能夠運用在身體上的強化以對抗不死生物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n天譴剋星藥丸"}
MultiLanguageQuestData['tw'][9217] = {title = "更多的腐爛之心", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n天譴剋星藥丸"}
MultiLanguageQuestData['tw'][9218] = {title = "脊骨之塵", objective = "把10份脊骨之塵交給安寧地的博學者艾米諾。", description = "再活化的骷髏體內流著的黑暗力量主要會累積在他們的脊椎裡。我發現了一個方法可以將這股能量注入藥水裡，增強我們的魔法能力對抗不死族。\n\n幫我帶來一些脊骨之塵我就會樂意提供你一個樣本。你會在西邊的死亡之痕找到一堆遊走的骷髏。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n天譴剋星秘丸"}
MultiLanguageQuestData['tw'][9219] = {title = "更多脊骨之塵", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n天譴剋星秘丸"}
MultiLanguageQuestData['tw'][9220] = {title = "死亡之域戰爭", objective = "在死亡之域殺掉5名死亡之域通靈師，6名奈幽碧斯百夫長和6名哀嚎者，並回到鬼魂之地向太陽聖所的博學者艾度尼斯回報。", description = "如果你想要幫忙的話，此時此地就是最佳良機。\n\n重建太陽聖所，我們早已在敵方權力中心:死亡之域，高舉反抗的消息。\n\n去與這群居住在這個邪惡天譴軍堡壘的不死生物們對戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9227] = {title = "精良的作战装备 - 银色黎明崇拜", objective = "如果你有6枚银色黎明徽记和6枚十字军徽记，就能从银色黎明库存的宝藏中挑选一件物品。", description = "朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？\n\n如果你在银色黎明的声望达到崇拜的话，我们会给你最低的折扣！我建议你现在就购买吧！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "虔誠指環法雷盟的最後手段聖療皮頭盔瘟疫獵人護腿您能選擇下列奬勵中的一個：\n\n堅決指環補給袋"}
MultiLanguageQuestData['tw'][9228] = {title = "史诗级的作战装备 - 银色黎明崇拜", objective = "如果你有27枚银色黎明徽记和27枚十字军徽记，就能从银色黎明库存的宝藏中挑选一件物品。", description = "朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？\n\n如果你在银色黎明的声望达到崇拜的话，我们会给你最低的折扣！我建议你现在就购买吧！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "淨化者黎明護符黎明勳章希望護腕狡猾護腕您能選擇下列奬勵中的一個：\n\n權勢咒符"}
MultiLanguageQuestData['tw'][9229] = {title = "拉玛兰迪的命运", objective = "进入纳克萨玛斯的宫殿，找到拉玛兰迪的下落。", description = "拉玛兰迪是兄弟会的一名战士，早在银色黎明成立之前他便是莫格莱尼阁下的学生了！当莫格莱尼的死讯传来时，仇恨和愤怒充斥着他的心灵。\n\n试想一下吧，<name>，一个被复仇的怒火占据了心灵的人还能算个人吗，无非是个被情绪操控的傀儡。拉玛兰迪在盛怒之下冲进了纳克萨玛斯的宫殿，想为恩师报仇……可惜是肉包子打狗。\n\n前往纳克萨玛斯的宫殿打探拉玛兰迪的下落吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][9230] = {title = "拉玛兰迪的寒冰之握", objective = "东瘟疫之地圣光之愿礼拜堂的科尔法克斯要1个冰冻符文、1块蓝宝石和1块奥金锭。", description = "要修复这枚戒指可不是件容易的事儿，<name>。瞧，它的原材料是取自天灾建筑物中形成的冰冻符文，例如纳克萨玛斯的宫殿。当然我还需要其它材料，但是你的主要任务就是找到冰冻符文。把我所需的材料拿来，我会让这枚戒指重新恢复光泽的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n羅馬拉丁尼之冰握"}
MultiLanguageQuestData['tw'][9232] = {title = "我只会唱这一首歌……", objective = "将2个冰冻符文、2个水之精华、2块蓝宝石和30金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。", description = "你自诩为银色黎明的英雄，是吗？克尔苏加德手下的小喽啰能轻松砍翻我军最优秀的士兵，这是我亲眼所见！像你这样的蠢货还想去纳克萨玛斯的宫殿？\n\n<威尔海姆叹了一口气。>\n\n呸，我还能有什么选择？你是我惟一的希望；我或许能帮上忙。\n\n“奥玛里恩悄悄地走，除了一份图样，他什么都没留……”，我只会唱这一首歌……嗯，我可以为你制作一条很棒的裤子，但是你得为我提供材料。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "冰禍護腿冰川護腿極地護腿冰鱗護腿"}
MultiLanguageQuestData['tw'][9233] = {title = "奥玛里恩的手册", objective = "将奥玛里恩的手册交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。", description = "威尔海姆：\n\n当你翻阅这本手册时，我已经咽气了——这对我来说是个解脱。我想告诉你，我临死前还想着你和你那糟糕的商业头脑。不幸的是，就工匠技能来说，送手册给你的家伙连你都不如。\n\n这本手册记载了我生前研制的配方，可以让手册的持有者制造出任何他们想要的东西。我想你一定会向别人收取高额费用的，因为你就是这么个混帐。\n\n我鄙视你，\n\n奥玛里恩", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][9234] = {title = "破冰护手", objective = "将5个冰冻符文、12块瑟银锭、2块奥金锭、2个水之精华和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。", description = "感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰护手了。你要做的只是为我提供材料，并支付一笔小小的加工费。", progress = "Have you brought the materials?", completion = "Here is your order, &lt;name&gt;. Delivered as promised!", rewards = "您會收到：\n\n冰禍護手"}
MultiLanguageQuestData['tw'][9235] = {title = "破冰护腕", objective = "将4个冰冻符文、12块瑟银锭、2块奥金锭、2个水之精华和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。", description = "感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰护腕了。你要做的只是为我提供材料，并支付一笔小小的加工费。", progress = "Have you brought the materials?", completion = "Here is your order, &lt;name&gt;. Delivered as promised!", rewards = "您會收到：\n\n冰禍護腕"}
MultiLanguageQuestData['tw'][9236] = {title = "破冰胸甲", objective = "将8个冰冻符文、16块瑟银锭、2块奥金锭、4个水之精华和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。", description = "感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰胸甲了。你要做的只是为我提供材料，并支付一笔小小的加工费。", progress = "Have you brought the materials?", completion = "Here is your order, &lt;name&gt;. Delivered as promised!", rewards = "您會收到：\n\n冰禍胸甲"}
MultiLanguageQuestData['tw'][9237] = {title = "冰川披风", objective = "将5个冰冻符文、4个符文布卷、2个水之精华、4个铁网蛛丝和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。", description = "感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作冰川披风了。你要做的只是为我提供材料，并支付一笔小小的加工费。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n冰川披風"}
MultiLanguageQuestData['tw'][9247] = {title = "保管者的徵召", objective = "將名冊保管者的信交給在東瘟疫之地聖光之願禮拜堂的他。", description = "<name>，\n\n長久以來你為了銀色黎明的利益服務，永遠表現你最有能力的一面。現在，我們又耳聞一項極需支援的號召。\n\n<name>，若你願意協助的話，請向東瘟疫之地的聖光之願禮拜堂，跟名冊保管者報到。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n受祝福的巫師之油聖化磨刀石\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][9248] = {title = "谦卑的馈赠", objective = "将一根深渊节杖交给希利苏斯塞纳里奥要塞的奥蕾尔·金叶。你在塞纳里奥议会的声望必须达到尊敬。", description = "Ishnu-alah，<race>。让我看看能证明你杀死深渊议会领主的证据，我就奖励你一件好东西，它能在你与其拉虫人作战时帮你一臂之力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納留斯指環"}
MultiLanguageQuestData['tw'][9249] = {title = "40張獎券 - 結構圖：蒸汽坦克遙控器", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n結構圖：蒸汽坦克遙控器"}
MultiLanguageQuestData['tw'][9252] = {title = "保衛晴風村", objective = "殺掉4個腐肢掠奪者、4個黑暗怨靈。然後回到遊俠塞瑞覆命，他在永歌森林的晴風村。", description = "我們已感覺到天譴軍團明顯提高攻擊行動，<name>。我們快抵抗不住了，而且銀月城好像也沒有增援的跡象。協助我們削弱死亡之痕不死生物的數目，一起來保護這村莊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9253] = {title = "符文守護者德蘭", objective = "與永歌森林的符文守護者德蘭談話，他在鬼魂之地邊界附近。", description = "天譴軍團有增無減的攻擊行動讓我相信，鬼魂之地邊界那裡的某個防禦符文石一定發生故障。\n\n我們用這些古老的石頭來保護我們不受不死族傷害。它們大部分都在太陽之井的攻擊後被摧毀或不見了。\n\n朝著鬼魂之地的方向沿著路往南走，往西邊看就會發現一條小徑。你會在附近的一個符文石看到符文守護者德蘭;他會知道發生了什麼問題。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9254] = {title = "遊蕩者學徒", objective = "與東部聖所的學徒莫維達談話，位置在永歌森林。", description = "感謝你的幫忙，<name>。當我整頓好這裡的事情時，我想請你幫個忙。我之前的一個學徒捲入了危險的研究調查。她前往了東部聖所，就在死亡之痕中間。\n\n我擔心她的安危。你能不能幫我把她找回來，並說服她找回自己。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9255] = {title = "研究報告", objective = "把研究報告帶到永歌森林交給晴風村的博學者蘭德拉‧晨行者。", description = "雖然我的研究結果令人沮喪，這份資料還是有可取之處。我要在這份報告被正視之前，先讓博學者檢視一下我的成果。拜託你，把這些報告拿給西邊晴風村的博學者蘭德拉‧晨行者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9256] = {title = "晴風村", objective = "到永歌森林與晴風村的遊俠迪哥里恩談話。", description = "我有另一個任務要給你，<name>。遊俠迪哥里恩被派去晴風村找尋更多有關惡癮者攻擊附近船廠的線索。他正尋求增援，可是我們還不能幫忙。去找到他，然後盡你全力去幫助他吧。\n\n沿著獵鷹之翼廣場的道路一直往南走就能找到晴風村了。祝你好運，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9258] = {title = "烈焰邊境", objective = "去烈焰邊境附近找拉瑞安娜‧河風，位置就在永歌森林的西南方。", description = "天譴軍團的污土持續進攻新的區域。為此，我們在鬼魂之地邊界建造了防護符石，以防止污染繼續蔓延。\n\n某次天譴軍團的攻擊行動中，他們摧毀了西邊的符石，迫使我們必須燒掉四周的土地來遏止污穢擴散。我的姐妹，拉瑞安娜‧河風，看管著烈焰邊境。去找她，她可能有工作要給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9259] = {title = "血帆的叛徒", objective = "That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n! That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof.\n\nI don't have it in me heart to do that, nor will I ask ye to. Bring me some silk cloth and red dye and I'll make suitable replicas. I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!", description = nil, progress = "That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n! That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof.\n\nI don't have it in me heart to do that, nor will I ask ye to. Bring me some silk cloth and red dye and I'll make suitable replicas. I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!", completion = "Let us observe a minute of silence for our fallen mates, &lt;name&gt;.\n\n&lt;The Bloodsail Traitor grins at you and winks.&gt;\n\nBeing a traitor is one thing, murdering yer own buckos... that'd be just downright despicable, aye!", rewards = nil}
MultiLanguageQuestData['tw'][9260] = {title = "調查暴風城的天譴軍團", objective = "從暴風城外的天譴軍團身上收集三個暗淡的亡域之石並調查它們營地附近發光的符文法陣。", description = "巫妖王把他的不死生物派到我們的門口;我們不能坐視不管！你一定會站出來保衛暴風城不受可惡的入侵者騷擾吧？\n\n外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9261] = {title = "調查鐵爐堡的天譴軍團", objective = "從鐵爐堡外的天譴軍團身上收集三個暗淡的亡域之石並調查它們營地附近發光的符文法陣。", description = "巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛鐵爐堡不受可惡的入侵者騷擾吧？\n\n外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9262] = {title = "調查達納蘇斯的天譴軍團", objective = "從達納蘇斯外的天譴軍團身上收集三個暗淡的亡域之石並調查它們營地附近發光的符文法陣。", description = "巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛達納蘇斯不受可惡的入侵者騷擾吧？\n\n外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9263] = {title = "調查奧格瑪的天譴軍團", objective = "從奧格瑪外的天譴軍團身上收集三個暗淡的亡域之石並調查它們營地附近發光的符文法陣。", description = "巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛奧格瑪不受可惡的入侵者騷擾吧？\n\n外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9264] = {title = "調查雷霆崖的天譴軍團", objective = "從雷霆崖外的天譴軍團身上收集三個暗淡的亡域之石並調查它們營地附近發光的符文法陣。", description = "巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛雷霆崖不受可惡的入侵者騷擾吧？\n\n外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9265] = {title = "調查幽暗城的天譴軍團", objective = "從幽暗城外的天譴軍團身上收集三個暗淡的亡域之石並調查它們營地附近發光的符文法陣。", description = "巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛幽暗城不受可惡的入侵者騷擾吧？\n\n外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9266] = {title = "重修舊好", objective = "You must've done something really bad to us or our friends, <name>. At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us.", description = nil, progress = "You must've done something really bad to us or our friends, <name>. At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us.", completion = "Thank you, &lt;name&gt;. You're on a quick path to redeeming yourself with our fair town.", rewards = nil}
MultiLanguageQuestData['tw'][9267] = {title = "修復舊創", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][9268] = {title = "海上之戰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][9272] = {title = "適宜的服裝", objective = "呀...如果你真的那麼想加入我們老練水手的行列，你最好穿的像個水手一點!來，在我嚴責你之前快穿上適當的服飾。\n\n它們穿在你身上比穿在紅眼阿班那個老傢伙身上適合多了。他死在海上的一場暴風雨裡。\n\n驕傲的穿著它吧，朋友!", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n血帆襯衣血帆束帶血帆皮靴血帆束褲海盜的制服"}
MultiLanguageQuestData['tw'][9273] = {title = "可口可乐宠物兑换券", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n北極熊項圈"}
MultiLanguageQuestData['tw'][9274] = {title = "溺死者的靈魂", objective = "鬼魂之地，旅行者營地的遊俠克羅南，要你去附近的湖裡殺死8個復仇的亡魂和8個貪婪的亡魂。", description = "就我有印象以來北邊的湖就充斥著我祖先的靈魂，<name>。那些可憐的鬼魂都是在一場悲慘的意外中溺死在湖底的受害者。\n\n事情的來龍去脈我已忘得差不多了，但是他們揮之不去的哭喊聲一直提醒著我他們的詛咒。\n\n如果你能勝任這個任務，我要你去湖那裡結束他們的苦難，<name>。我和他們都會感謝你的...我保證。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9275] = {title = "一點小佐料", objective = "到札布諾瓦營地在食人妖的食物裡下毒，再回到鬼魂之地的旅行者營地，將剩下的藥劑師之毒交給藥劑師范衲斯特。", description = "讓我先自我介紹。我是皇家藥劑師學會的藥劑師范衲斯特。我是來幫助遠行者解決他們的食人妖麻煩。我想我有辦法解決這個問題。\n\n我手上有一堆強而有力的毒藥。食人妖也是活的生物，他們也要吃。如果我們把他們的食物加入我的毒藥…那麼，我相信結果會非常有趣。\n\n你願意幫助我們擺脫南邊札布諾瓦的影松食人妖嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9276] = {title = "攻擊札布泰拉", objective = "殺死8名影松暗影施法者和8名影松獵頭者，再回到鬼魂之地找旅行者營地的遠行者索安娜。", description = "我很高興你來這裡幫忙，<class>。我們的資源已經減少許多，所以你的幫忙對我們而言是相當珍貴的。隊長已派我追查當地影松食人妖營地的騷擾事件。我們的策略就是讓他們失去平衡直到有天能一舉殲滅他們。\n\n到那時候，我們就需要所有能找到的志願者，這樣那些影松食人妖的數量才不會增加。\n\n你覺得你能前往東方的札布泰拉給他們點顏色瞧瞧嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9277] = {title = "攻擊札布諾瓦", objective = "殺死10名影松馭貓者和10名影松妖術師，再回到鬼魂之地找旅行者營地的遠行者索安娜。", description = "是來點比較有挑戰性任務的時候了。南邊的札布諾瓦是較強大的影松食人妖的家。為了持續將食人妖的數量削減至最小，我要派你去那裡攻擊他們，不論你用什麼手段。\n\n你覺得這方法如何，<name>？準備好對付更多的食人妖了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "哨衛護腕軟棉護腕遠行者護腕遠行者的腕輪您會收到：\n\n"}
MultiLanguageQuestData['tw'][9278] = {title = "歡迎!", objective = "將藍色守望禮物兌獎券交給藍色守望的喬萊爾。", description = "歡迎來到魔獸世界!\n\n為了感謝您購買《魔獸世界》典藏版，請將這張禮券交給藍色守望的喬萊爾。您將得到一份特別的禮物:陪伴您踏上冒險旅途的小夥伴!\n\n再次感謝您的支持，請盡情享受魔獸世界的樂趣吧!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n破壞神之石熊貓項圈異化蟲繩索"}
MultiLanguageQuestData['tw'][9279] = {title = "你活下來了!", objective = "和安曼谷失事地點的波尼特斯談談。", description = "別擔心我的傷，<兄弟/姐妹>。我們有人能活下來就是奇蹟!\n\n你看起來還沒恢復健康;你被拘禁了好幾個禮拜。\n\n發生了一些事，艾克索達便失事了。很多人都死了。\n\n但你還活著讓我鬆了一口氣，<name>。有你帶領我們，我相信很快我們就能平安離開這個地方!波尼特斯要我叫你醒來後去找他。他在山丘腳下等你。沿著路往西南方走。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9280] = {title = "補充治療水晶", objective = "從附近的安曼谷飛蛾身上取得6瓶飛蛾血清，再回到安曼谷失事地點的波尼特斯那裡。", description = "現在最緊要的就是我們消耗的治療水晶。我們必須盡快補充水晶!\n\n不幸的是，現在唯一的方法就是從當地的安曼谷飛蛾身上直接抽取血液。牠們的血液是很合適的替代品。\n\n你可以在溪谷附近的區域找到牠們，不過牠們大多集中在西北方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "解救皮腰帶用舊的軟靴微鏽的護腕部份鏽蝕的鎖鏈您會收到：\n\n"}
MultiLanguageQuestData['tw'][9281] = {title = "清除道路", objective = "鬼魂之地安狄里安莊園的學徒瓦瑞爾要你去殺10隻巨型細網蜘蛛和10個鬼爪劫毀者。", description = "博學者坎德立斯派我來這清除任何有敵意的野生生物。等這個區域安全了，博學者打算把這裡變成對抗天譴軍團的前哨。\n\n如果要我說當學生時學到的一件事就是負起責任 - 尤其是悠關性命的事!\n\n如果你有興趣，我要你去殺死西邊和南邊的巨型細網蜘蛛和鬼爪劫毀者，我會給你豐厚的報酬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9282] = {title = "旅行者營地", objective = "太陽聖所的博學者坎德立斯要你去鬼魂之地和旅行者營地的遊俠薇娜談談。", description = "博學者和遠行者永遠都不會有意見一致的時候，<name>。不過，說到達克汗，我們全都同意一定要想出個辦法來擊敗他和他的軍團。\n\n東北邊的旅行者營地有個叫薇娜的遊俠，她對我們的敵人有了一些重要的發現。和她談談看是否你能幫得上忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][9283] = {title = "德萊尼生還者", objective = "對散落在安曼谷各處的其中一名德萊尼生還者使用那魯的祝福技能。之後再回到安曼谷失事地點找薩度恩。", description = "治療水晶的庫存已重新補足，但那不是我們能幫助傷者的唯一方法。所有的德萊尼都能使用那魯的祝福來治療他人。你一定要使用這個能力來治療一個失事後的生還者。\n\n你可以在西邊和西北邊的區域找到大部份的生還者，但那場失事讓我們分佈散落在整個溪谷裡。\n\n生還者暴露在能量水晶的照射下，所以你應該可以順著環繞生還者散發的紅光而找到他們。\n\n你一定要救救他們，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n空的德萊尼補給包"}
