MultiLanguageQuestData['tw'][10467] = {title = "防衛者的誓約", objective = "當你的流沙之鱗聲望值到達尊敬之後帶著你的永恆指環給在時光之穴的索芮朵蜜。", description = "你已經立下你的誓言，<class>。現在就由你來進行。\n\n好好的效忠流沙之鱗，你就會被獎賞。失敗的話據我們所知時間線就會被破壞!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n永恆指環"}
MultiLanguageQuestData['tw'][10468] = {title = "法師的誓願", objective = "當你的流沙之鱗聲望值到達崇敬之後帶著你的永恆指環給在時光之穴的索芮朵蜜。", description = "你已經實現了你對我們的承諾，<name>。因此你也獲得了你應得的認同。\n\n隨著你與海加爾山的萬物達到合諧，我就能持續得在你的戒指內注入能量。要達到戒指的最大潛能不會需要太久的時間。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n永恆指環"}
