MultiLanguageQuestData['tw'][10733] = {title = "遵循紫羅蘭之路", objective = "當你與紫羅蘭之眼的聲望到達尊敬後，將你的紫羅蘭徽記交給逆風小徑的大法師利瑞達。", description = "你已經決定你要走的路了，<class>。現在就由你去走這條不管目的為何處的路。\n\n你會發現有朋友在達拉然法師團裡有它的好處。好好跟我們相處你的功績就不會白費。", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;. Behold as I unleash the power contained in your signet!", rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10734] = {title = "紫罗兰之路", objective = "当你在紫罗兰之眼的声望达到尊敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。", description = "<class>，你已经做出了选择。那么，不管前方的路有多么凶险，你都得走下去。\n\n你要明白，与达拉然的大法师们搞好关系是大有裨益的。为我们服务吧，你的努力不会白费的。", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;. Behold as I unleash the power contained in your signet!", rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10735] = {title = "紫罗兰之路", objective = "当你在紫罗兰之眼的声望达到尊敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。", description = "<class>，你已经做出了选择。那么，不管前方的路有多么凶险，你都得走下去。\n\n你要明白，与达拉然的大法师们搞好关系是大有裨益的。为我们服务吧，你的努力不会白费的。", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;. Behold as I unleash the power contained in your signet!", rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10736] = {title = "紫罗兰之路", objective = "当你在紫罗兰之眼的声望达到尊敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。", description = "<class>，你已经做出了选择。那么，不管前方的路有多么凶险，你都得走下去。\n\n你要明白，与达拉然的大法师们搞好关系是大有裨益的。为我们服务吧，你的努力不会白费的。", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;. Behold as I unleash the power contained in your signet!", rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10737] = {title = "DEPRECATED", objective = "前往时光之穴，劝说麦迪文为你重铸Apprentice's Key。", description = "我已经将这把曾还是个学徒时使用过的钥匙重新拼接好了。虽然它现在看起来应该具备了以前钥匙的功能，但你还是没法用它来打开卡拉赞的大门。事实上，它现在就跟一块废铁一样。\n\n没有麦迪文调和这把钥匙中的魔法力量，它就完全没有任何价值。是的，没错，我知道麦迪文已经死了。但事情并非已经完全没有希望。\n\n艾泽拉斯世界那边有一处地方名叫时光之穴，被青铜龙军团所守护着。你只要找到那里，就可以回到过去找到麦迪文，让他调和这把钥匙中的魔法力量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10738] = {title = "卓越的贡献", objective = "当你在紫罗兰之眼的声望达到崇敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。", description = "<name>，你没有令我们失望。不过，我们也对你寄予了更大的期望。\n\n继续为紫罗兰之眼效力吧，你会得到满意的回报的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10739] = {title = "卓越的贡献", objective = "当你在紫罗兰之眼的声望达到崇敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。", description = "<name>，你没有令我们失望。不过，我们也对你寄予了更大的期望。\n\n继续为紫罗兰之眼效力吧，你会得到满意的回报的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10740] = {title = "卓越的贡献", objective = "当你在紫罗兰之眼的声望达到崇敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。", description = "<name>，你没有令我们失望。不过，我们也对你寄予了更大的期望。\n\n继续为紫罗兰之眼效力吧，你会得到满意的回报的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10741] = {title = "傑出的表現", objective = "當你與紫羅蘭之眼的聲望到達崇敬後，將你的紫羅蘭徽記交給逆風小徑的大法師利瑞達。", description = "你沒有讓我們失望，<name>。不過，我們還是對你寄以高度的厚望。\n\n繼續效忠紫羅蘭之眼，你會得到應得的獎勵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紫羅蘭徽記"}
MultiLanguageQuestData['tw'][10742] = {title = "攤牌", objective = "在苟克祭壇上使用雷克薩的戰爭號角，接著殺掉苟克。", description = "終於到了。我們會把苟克從他的巢穴引出來，然後我們就會殺了他。隨著苟克一死，這些血錘巨魔就再也無法威脅摩克納薩爾了。到位於戈魯爾之巢外苟克的祭壇去，接著吹響我的號角。我會出現，跟你一起面對這個戈魯爾之子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "裂蹄皮護腿油布馬褲紅玉之冠罪人眼罩黑邊胸鎧獅子胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10744] = {title = "勝利的消息", objective = "回到蠻錘要塞與庫德蘭‧蠻錘談談。", description = "你得馬上將我們成功的消息帶給庫德蘭‧蠻錘！他的人民在空軍指揮官奴艾恩領導下不斷的戰鬥保衛蠻錘要塞的安全，你的歸來無疑會提高他們的士氣。隨著軍團的威脅不同以往，庫德蘭終於可將注意力轉移來解決伊利丹的軍隊。我們這裡的位置不好防守，不過我們今日贏得了一場大勝利。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "魔導師手套痛苦指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][10745] = {title = "勝利的消息", objective = "回到影月村與霸主歐巴洛卡赫談談。", description = "你必須馬上將我們成功的消息傳給霸主歐巴洛卡赫知道！如今我們已經擊潰了軍團並使他們在影月谷消聲匿跡，統治者就可以將注意力轉往我們其他的敵人身上。\n\n雖然柯爾克隆守衛不會承認，不過他們會很高興我們不用再到兩個前線上戰鬥了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "魔導師手套痛苦指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][10747] = {title = "巨龍教團的幼龍", objective = "使用黑色幼龍網捕抓10隻巨龍教團黑色幼龍。", description = "我需要檢查生長在黑翼集會所的那些幼龍。\n\n那裡有一大群幼龍在洞穴裡外飛來飛去，同樣的也有為數不少的蛋，可能你一靠近就會孵化。\n\n<name>，麻煩你拿著這個網子去活抓一堆幼龍給我。\n\n朝西前進越過龍骨橋或經過龍骨隧道可以找到它們。順著路一路經過葛瑞許納什及烏鴉林到盡頭去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "巨龍教團兜帽黑色幼龍腰帶幼龍鱗片護手暗示護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][10748] = {title = "麥克斯納爾必須要死!", objective = "殺掉灰喉麥克斯納爾。", description = "他們讓我們別無選擇，<name>。是時候把黑翼集會所帶來的威脅做個了結了，殺掉他們的領導者，灰喉麥克斯納爾。\n\n我不知道你在那裡的時候有沒有瞥見他，但他是龍族的一員，半人半龍。而且他很強壯，所以不要低估了他!\n\n快點把它了結，幸運的話你就能保衛永恆樹林和魯安曠野的安全。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "巫集馬褲巨龍教團胸甲龍族襯衣黑翼頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][10749] = {title = "沙伯曼男爵的毒藥", objective = "將沙伯曼男爵的毒藥送到劍刃山脈的雷霆王村給雷克薩。", description = "來，把這個拿給你的主人。我確定無論理由為何，雷克薩都會好好使用它。\n\n喔，記得提醒他，他欠我一次。\n\n他知道我要什麼，因此我相信不管如何他都會把東西交給我，我們會比你想像的還要更快再次見到面。\n\n現在，當個聽話的小<男孩/女孩>把這個送去給雷克薩吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10750] = {title = "征服之路", objective = "前往影月谷的征服之路。", description = "我的蠍尾獅已經將消息傳送回來了，<name>。伊克利普森血精靈們正在策劃大幹一場。他們已經開始在征服之路組織他們的軍隊，就在東南方遠處 - 緊連著日蝕崗哨。\n\n我要你到征服之路去了解狀況。一旦你完成後，使用這個信號槍向蠍尾獅發出信號。會有一隻蠍尾獅自天空俯衝而下與你會合。把你的發現告訴他們，他們會給你下一個指令。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10751] = {title = "突破道路", objective = "殺掉20個伊克利普森士兵、10個伊克利普森騎士以及10個伊克利普森縛法者。", description = "我們需要多一點的時間，<race>。我會讓其他的蠍尾獅飛到更前面一點的地方去。但願我們能夠收集到更多的資訊。現在我需要你去做得就是清出一條路來還有更重要的是，引開他們對我們的注意力!\n\n一旦你削減了他們的人數後就使用這個柯爾克隆信號槍呼叫一隻蠍尾獅。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10752] = {title = "前往灰谷", objective = "与阿斯特兰纳的莱恩·狼行者谈一谈。", description = "不久之前，莱恩·狼行者离开达纳苏斯，穿过奥伯丁往灰谷方向去了。她跟我提起过熊怪的事，可惜我没机会向她询问详细状况，<class>，或许你能帮她一把。沿着南面的道路离开奥伯丁，越过灰谷边界后继续往南走。莱恩·狼行者就在阿斯特兰纳。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10753] = {title = "搶救自然", objective = "殺死4隻魔誓鱗翼，4隻魔誓匕爪還有2隻惡魔墮落者。", description = "燃燒軍團所犯下的暴行不記其數。即使在我們對話的同時，他們也派出燃燒軍團部隊對付外域的生物們。無力抵抗燃燒軍團的力量，外域的生物們一個接一個的倒下。<name>，幫助我停止他們這些破壞自然的罪行。\n\n越過山丘往東邊去，你會看到燃燒軍團的破壞已經遍及整個刀刃峽谷了。殺死犯下這些罪行的元兇，惡魔墮落者，還有盡可能殺死越多的魔誓越好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10754] = {title = "進入堡壘", objective = "將原始鑰匙模子帶去給地獄火半島上榮譽堡的軍隊指揮官達納斯。", description = "這新開鑄模是用來鑄造某種鑰匙的。從這幅雕在它背面的圖像來看，它看起來與地獄火有關。\n\n也許這能引起榮譽堡部隊指揮官，達納斯的興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10755] = {title = "進入堡壘", objective = "將原始鑰匙模子帶去給地獄火半島上索爾瑪的納茲格雷爾。", description = "這新開鑄模是用來鑄造某種鑰匙的。從這幅雕在它背面的圖像來看，它看起來與地獄火堡壘有關。\n\n也許這能引起部落在索爾瑪的領導人，納茲格雷爾的興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10756] = {title = "罗霍克大师", objective = "将原始钥匙模具交给萨尔玛的罗霍克。", description = "钥匙柄上的符号……雕刻在模具内的符号很难辨别，但是我能认出这是碎手邪兽人的钥匙。\n\n这是个很好的机会，这把钥匙可以让你进入破碎大厅。\n\n与我们的铁匠罗霍克谈一谈。如果说有谁能铸造这把钥匙的话，只能是他了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10757] = {title = "罗霍克的要求", objective = "将4块魔铁锭、2份奥法之尘和4颗火焰微粒交给地狱火半岛萨尔玛的罗霍克。", description = "邪兽人铁匠或许算不上技艺最精湛的铁匠，但他们还是有两把刷子的。想要利用这个模具配制出能用的钥匙，就必须以魔铁锭为熔料——其他材料很可能会破坏模具。\n\n我需要几块魔铁锭、一点奥法之尘还有几颗火焰微粒。我会试着铸造钥匙，但是我不保证能成功。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10758] = {title = "比地獄還熱", objective = "在地獄火半島破壞一部惡魔劫奪者，並且將未淬火的鑰匙模插入它的殘骸裡。將燒焦的鑰匙模型帶到洛赫克給索爾瑪。", description = "沒有用，<name>!不管我放多少煤炭到火裡，它就是不夠熱。\n\n只有一樣東西我能想到有足夠的熱度可以加溫這把鑰匙，而它是在軍團的惡魔劫奪者裡面。\n\n我曾經看見過有一個被擊落，就那麼一次。我記得當它落下時，有看見它裡面在冒煙、射出火焰和蒸汽。帶著這個鑄模，並將它進入倒下的惡魔劫奪者。如果你計畫打倒一個，我建議你一起帶些朋友去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破碎大廳鑰匙"}
MultiLanguageQuestData['tw'][10759] = {title = "找出背棄者", objective = "在熔岩平原上找到帕莎並與他交談。", description = "我覺得全部的碎片都在這裡，但是我就是不能有效的將它們都拼湊在一起。\n\n我認為我們的最好的方向是去努力找出日記中所提到的背棄者。如果他將他的同志遺棄在營地的話，我想你會有機會去說服他幫助我們了解黑暗議會阿拉卡正在計畫些什麼。\n\n在西北方的熔岩平原道路上開始找尋他吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10760] = {title = "史凱瑟隆殘骸", objective = "自史凱瑟隆殘骸的黑暗議會阿拉卡身上取回史凱瑟隆指揮官日誌 - 第一頁，史凱瑟隆指揮官日誌 - 第二頁，和史凱瑟隆指揮官日誌 - 第三頁交給影月村的卡古爾中士。", description = "史凱瑟隆殘骸，就在東方，是一個令人恐懼的地方。那些勞役確信它被詛咒了。\n\n這裡的樹很少，所以勞役們別無他法只有冒險進入阿拉卡廢墟伐木。阿拉卡精靈折磨工作團，吸取他們的生命，並且用它去增強他們的邪惡魔力。\n\n我們必須查明什麼正驅策著黑暗議會，並在他們的影響擴大之前制止他們。為他們計畫的證據搜尋史凱瑟隆殘骸吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10761] = {title = "找出背棄者", objective = "在熔岩平原上找到帕莎並與他交談。", description = "這裡沒有什麼可以解釋為什麼阿拉卡的精靈依然存在於這世界中，或是他們為什麼那麼渴望獸人的血。\n\n我認為我們的最好的方向是去努力找出日記中所提到的背棄者。如果他將他的同志遺棄在營地的話，我想你會有機會去說服他幫助我們了解黑暗議會阿拉卡正在計畫些什麼。\n\n在東南方的熔岩平原道路上開始找尋他吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10762] = {title = "达姆菲大师", objective = "将原始钥匙模具交给荣耀堡的达姆菲。", description = "钥匙柄上有着一个奇特的符号……这种符号应该很难在熔铸的模具上直接印刻出来，不过我认得出这是碎手氏族的标记。\n\n这是个很好的机会，你可以利用这模具配出钥匙，并进入破碎大厅。\n\n与达姆菲谈一谈。他精通各种铁匠工艺，如果他都无法配制出钥匙，那就没人能办得到了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10763] = {title = "达姆菲的要求", objective = "将4块魔铁锭、2份奥法之尘和4颗火焰微粒交给地狱火半岛荣耀堡的达姆菲。", description = "虽然邪兽人都是些没脑子的笨蛋，但是他们的锻造技术却不像你想得那样简单。如果我们想要让铸造出的这把钥匙真正能起作用，那么在铸造时就只能使用魔铁，而其它的材料都有可能造成铸造失败的结果。\n\n给我带一些魔铁锭、奥法之尘和火焰微粒回来。我要亲自试试看，不过不敢保证成功。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10764] = {title = "比地獄還熱", objective = "在地獄火半島破壞一部惡魔劫奪者，並且將未淬火的鑰匙模插入它的殘骸裡。將燒焦的鑰匙模型帶到榮譽堡給戴夫利。", description = "沒有用，<小夥子/姑娘>。我不能給它足夠的熱氣...材料無法被正確地加溫。\n\n你知道的，燃燒軍團使用的惡魔劫奪者們是以滾燙之魔化火焰的核心提供動力的 - 它燃燒所產生的溫度比一般的火焰熱得多。\n\n假如你能找到足夠的人取得一個，你就能在倒下的劫奪者裡面加熱鑄模。注意，<class>，那些惡魔劫奪者們幾乎都是成群結隊的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破碎大廳鑰匙"}
MultiLanguageQuestData['tw'][10765] = {title = "當世界衝突時...", objective = "殺掉大法官血葉和偉大的科羅克，並取回伊利丹的命令。", description = "在征服之路的南端，一支定居商隊附近，我發現了一個看起來像是一個巨人和一位血精靈大法官間的會議。巨人在這裡做什麼?這感覺有點不對勁，蠻兵。\n\n我要你排除任何的困難前往會議地點，並且結束它。取得會議中任何可能發現的東西，然後以信號槍通知我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10766] = {title = "侵略點：災難", objective = "在侵略點：災難向普萊克希報告。", description = "目前我們已經進入軍團在侵略點：災難的基地，我們需要想出一種方式去停止它們在這的運作。蠻錘要塞將不會是安全的，除非軍團被趕出影月谷。\n\n我已經送一隊先遣隊到侵略點幫助你擬定一個計畫去破壞軍團的補給。回去軍團要塞並踏進上方有綠色水晶的傳送器。普萊克希將在你的目的地與你見面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10767] = {title = "侵略點：災難", objective = "在侵略點：災難向那卡西報告。", description = "目前我們已經進入軍團在侵略點：災難的基地，我們需要想出一種方式去停止它們在這的運作。影月村將不會是安全的，除非軍團被趕出山谷。\n\n我已經送一隊先遣隊到侵略點幫助你擬定一個計畫去破壞軍團的補給。回去軍團要塞並踏進上方有綠色水晶的傳送器。那卡西將在你的目的地與你見面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10768] = {title = "伊利達瑞的外袍", objective = "收集10件伊利達瑞外袍。", description = "蠍尾獅騎士必須返回影月村為我們突擊的下一個階段作準備。我現在需要你的是這些血精靈所穿的外袍。\n\n當你收集了足夠的外袍時，使用柯爾克隆信號槍召喚蠍尾獅騎士。準備好做點間諜行動吧，<race>!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10769] = {title = "行列中的歧見...", objective = "在偽裝為伊利丹的代理人時，殺掉5個瘋狂的巨像，並且返回影月谷的影月村向霸主歐巴洛卡赫回報。同時將他的柯爾克隆信號槍交還給他。", description = "研究員提歐魯斯體貼的為了最後的攻擊把這混合物放在一起。我只是在這件你給我的外袍上傾注它，而這件外袍被注滿了伊利達瑞骯贓的精華。\n\n拿著這件施過法的外袍，並且旅行到伊克利普森農場，在日蝕崗哨的西南邊。一旦到了那裡，使用這件外袍轉變成一位伊利丹的代理人。在裝扮期間，殺了在原野徘徊之發狂的戈羅西。他們將認為那是伊克利普森所做的攻擊，而切斷全部關係!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "塑能師的救贖印記救贖之法劍印記救贖之殺戮者印記您能選擇下列奬勵中的一個：\n\n救贖之保衛者印記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][10770] = {title = "一些餘燼", objective = "苔木長老想要你殺死8個灼熱小鬼，然後返回魯安曠野找他。", description = "這裡東北方在我們上方的高原上躺著我老家之被燒盡的灰。在燃燒軍團派他們的灼熱小鬼去燒盡我們之前，有一大片森林在那些繁盛。在過了如此多個死寂的世紀後，我疲倦而老去的心甚至仍然渴望復仇。有太多敵人了以致於不能收復土地，但是你能使他們害怕。\n\n確定你願意幫助我?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10771] = {title = "來自灰燼", objective = "苔木長老想要你旅行至斯卡德，並將鐵根種子種植在三座不同的肥沃的熔岩泥土內，然後返回魯安曠野到他那裡。", description = "如果你沿著東方的道路並上到山的側面，然後轉向北方，那你將會來到我長期失去的家。曾經在那裡有一棵樹。我早已忘記它的名字了。很久以前燃燒軍團召喚灼熱小鬼和其他火焰生物。我的家就被毀滅了，而我的族人逃離了。現在只有我留下來。\n\n我已經保存了一些可以在肥沃的火山土壤種植的鐵樹根種子。他們的魔力是強大的。為我做這件事，而我將與你同享一批被遺忘已久的財寶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "野性之林法杖鐵橡木盾牌焦木之弓您會收到：\n\n"}
MultiLanguageQuestData['tw'][10772] = {title = "征服之路", objective = "前往影月谷的征服之路。", description = "我的獅鷲騎士已經帶了一點消息回來了!伊克利普森血精靈們正在進行大計畫。他們已經開始在征服之路集結他們的軍隊，位於這裡的東邊 - 鄰接日碩崗哨。\n\n我想要你旅行到征服之路並且評估情勢。完成之後使用這隻信號槍發送信號通知獅鷲騎士。獅鷲騎士將從天空俯衝下來與你會面。告訴他們你發現了什麼，他們將給你下一步命令。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10773] = {title = "突破道路", objective = "殺死20名伊克利普森士兵、10名伊克利普森騎士和科難的5個兒子。", description = "我們需要更多的時間，<race>。我將要與一些其他的獅鷲騎士飛越前方。希望，我們能收集更多的情報。我現在需要你清出一條通道，而更重要的，使他們的箭遠離我們!\n\n一旦你削弱他們的人數，使用蠻錘信號槍召喚一名獅鷲騎士。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10774] = {title = "血精靈 + 巨人 = ???", objective = "殺掉大法官血葉和偉大的科羅克，並取回伊利丹的命令。", description = "在征服之路的南端，一支定居商隊附近，我發現了一個看起來像是一個巨人和一位血精靈大法官間的會議。巨人在這裡做什麼?這感覺有點不對勁，蠻兵。\n\n我要你排除任何的困難然後去到該會議，並且結束它。從會議中取得任何你能找到的東西，然後以信號槍召喚我們其中一個。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10775] = {title = "伊利達瑞的外袍", objective = "收集10件伊利達瑞外袍。", description = "獅鷲騎士必須返回蠻錘堡壘為我們突擊的下一個階段作準備。我現在需要你的是這些血精靈所穿的外袍。\n\n當你收集了足夠的外袍時，使用蠻錘信號槍召喚獅鷲騎士。準備好做點間諜行動吧，<race>!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10776] = {title = "行列中的歧見...", objective = "在偽裝為伊利丹的代理人時，殺掉5個瘋狂的巨像，並且返回影月谷之蠻錘要塞的尤瑞卡爾族長那裡。同時將他的蠻錘信號槍交還給他。", description = "葛諾瑪斯體貼的為了最後的攻擊把這混合物放在一起。我只是在這件你給我的外袍上傾注它，而這件外袍被注滿了伊利達瑞骯贓的精華。\n\n拿著這件施過法的外袍，並且旅行到伊克利普森農場，在日蝕崗哨的西南邊。一旦到了那裡，使用這件外袍轉變成一位伊利丹的代理人。在裝扮期間，殺了在原野徘徊之發狂的戈羅西。他們將認為那是伊克利普森所做的攻擊，而切斷全部關係!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "塑能師的救贖印記救贖之法劍印記救贖之殺戮者印記您能選擇下列奬勵中的一個：\n\n救贖之保衛者印記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][10777] = {title = "阿斯格的圖騰", objective = "將史凱瑟隆戰爭圖騰帶給熔岩平原的帕莎。", description = "你在指揮官日誌裡讀到的是真實的。當獸人部落 在古爾丹下方聚集時，我的族人想辦法對抗他以保衛我們免受威脅。古爾丹獲悉他們的意圖，並且施下毀滅我們陣營和扭曲我兄弟靈魂的一種強大咒語。在他們釋放出更大的惡魔之前，\n\n他們必須被制止。在北方的史凱瑟隆殘骸裡，找尋阿斯格並且將他所攜帶的圖騰帶來給我。有了它，我們就能開始阻礙黑暗議會的計畫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10778] = {title = "利安瑟魔棒", objective = "從任何在日蝕崗哨的血精靈身上取得利安瑟的鑰匙，並用它打開利安瑟的保險箱並且取去利安瑟魔棒。返回熔岩平原將魔棒交給帕莎。", description = "單單圖騰不夠強大得足以抵消黑暗議會的邪惡魔力。\n\n我們將它與其他物體的力量結合起來，做成一個權杖以集中能量。我們無法從他們墮落的最深處中拯救出我的諸兄弟，但是我們能制止他們。\n\n為此權杖，我需要的項目之一是利安瑟魔棒，它被東南方日蝕崗哨的血精靈所持有。它被放在廢墟最高層上的一座亭子裡，並且被重重保衛。小心，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10780] = {title = "史凱瑟隆羽毛", objective = "收集8根史凱瑟隆羽毛，並且把他們帶到在熔岩平原給帕莎。", description = "這權杖還欠缺最後一種元素。我們必須把權杖的能力導引向黑暗議會幽靈。\n\n我們能透過收集散佈在史凱瑟隆營地地上的羽毛並且在權杖裡使用他們去完成那件事。營地位於南方，在蠻錘要塞的東方。\n\n古爾丹的魔法完全毀滅了我的諸兄弟，只留下他們的靈魂，但是不只這樣。魔法以阿拉卡所準備的咒語為食，創造出一種吞沒靈魂的邪惡力量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10781] = {title = "赤紅守望的戰鬥", objective = "在赤紅守望的戰鬥與伊利丹的軍隊戰鬥，並且存活下來!\n\n一旦你勝利，回到在撒塔斯城的阿達歐那裡。", description = "當我們在對話時，他們或許正在征服之路尋找你。你必須逃跑，<race>!\n\n留下我，我已經準備好了...他們...我想我聽到他們來了。機不可失，時不再來!走吧!如果你選擇留下，你必須戰鬥!\n\n如果你戰鬥，並且設法存活的話，帶著你在這裡學會的，並且把那知識告知給撒塔斯城的阿達歐。您會收到：\n\n", progress = nil, completion = nil, rewards = "薩塔的特技員印記薩塔的侵略者印記薩塔的法師印記薩塔的降神師印記您會收到：\n\n伊利達瑞綠色戰利外袍伊利達瑞紫色勝利外袍"}
MultiLanguageQuestData['tw'][10782] = {title = "浸注權杖頭", objective = "前往詛咒祭壇，在靠近古爾丹時使用未充能的權杖頭。當權杖頭被灌注能量之後，返回在熔岩平原的帕莎那裡。", description = "權杖差不多要完成了!\n\n剩下的是讓權杖頭充滿流自這個被詛咒地方之古爾丹回聲的力量。向東走，靠近惡魔深淵和在死亡熔爐的南方附近，是詛咒祭壇。\n\n在那裡，古爾丹昔日的碎片被困住。當你攜帶這未完成的權杖頭進入祭壇周遭地區時，假如有一些事物回應它時不要驚嚇到。你正攜帶一個與災變有強大連結關係而又非常危險的物體。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10783] = {title = "沙伯邁恩男爵", objective = "到劍刃山脈的血之環找沙伯邁恩男爵談談。", description = "我的計畫是。我們毒害巨魔們，然後消滅他們的古羅主人。\n\n在我於這些山中旅行期間，我遇見一個名為沙伯邁恩男爵的人。他精通鍊金術，且可確信會幫助我們。\n\n你可以在這裡北邊峽谷下方的血之環那裡找到他。無論他需要什麼代價，都由你來判斷是否接受。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10784] = {title = "粉碎血槌營地", objective = "殺死10個血槌槌兵和5個血槌術士。", description = "<吐查克傾身接近低聲地說。>\n\n<name>，你到目前為止對我們所做的比與巨魔戰鬥還要自豪。而當我對雷克薩所計畫的有信心時，我將依舊要求你在返回之前，粉碎血槌營地的巨魔們。\n\n那樣我們將加倍確信結果。\n\n要到那裡，向北走，走下雷霆王村外面的斜坡道。然後，在斜坡道底部，向西走越過飛龍之末，並向北穿過翻騰峽谷和匕爪峽谷。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "黑暗步態長靴雙月肩衛鍊織繫腰晴天腕甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10785] = {title = "它是一個陷阱!", objective = "將龍火陷阱交付給劍刃山脈之雷霆王村的雷克薩。", description = "在這個世界沒有其他原因能比戈魯爾和他兒子們更能令我憎惡!他們屠殺我的族人-我的孩子-現在我將嚐到報仇的滋味!\n\n我已經利用龍火做成一個陷阱，如果你夠聰明的話，你甚至可以使用它來殺死古羅。\n\n快一點就對了，把陷阱拿給雷克薩。\n\n我渴求報仇的火焰必須要被撲滅!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10786] = {title = "圓面之地大屠殺", objective = "屠殺5個劍刃蠻卒和3個劍刃薩滿，然後返回劍刃山脈的雷霆王村找吐查克‧雙爪。", description = "我知道雷克薩有計畫要你向圓面之地前進。當你到那裡時，我有一些想要你去做的事情。\n\n我們必須把握任何能打倒這些山上的巨魔的機會，否則他們將佔領我們，這樣我們就會流血並且無意義的死去!\n\n圓面之地位於西北方遠處。向北走到魯安曠野，然後從那裡走向西邊，穿過隧道並通過烏鴉林。\n\n<name>，我想要你殺掉圓面之地的劍刃巨魔們。徹底消滅他們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10791] = {title = "歡迎狼魂", objective = "在瑪魯卡茲的小屋裡蠟燭附近使用典禮薰香並且觀察儀式。當儀式完成的時候，再次與瑪魯卡茲交談。", description = "我已經差不多完成我將在儀式期間穿的法衣了。當我加上最後的裝飾時，我要你將薰香設置在我左邊符文石附近的蠟燭旁。\n\n我相信它將幫助我們吸引狼魂的注意，畢竟它是過去獸人氏族所做的。我幾乎能想像我的祖先在一次成功的打獵之後，用它在儀式中向狼魂獻上崇敬。\n\n一旦你已經安置好薰香，我就開始儀式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "貪婪狡猾頭盔狼獵手之衣貪婪恩典頭盔貪婪兇殘頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][10792] = {title = "薩斯葛爾必須被燒毀!", objective = "殺死血之谷苦工奪走他們的火炬，在薩斯葛爾熔爐點燃他們，然後把燃燒的火炬丟到薩斯葛爾建築物裡。", description = "血之谷氏族已經背叛了他們的高貴傳統!我們獸人奮戰並誓死保護自己免於瑪諾洛斯的惡魔感染，望向我們卑鄙的親戚只看見軟弱和卑賤...因此，他們必須被燒死!\n\n進入他們在東方的堡壘，薩斯葛爾並燒毀他們的建築。殺死苦工取有他們的火炬，在他們的熔爐點燃火炬，並且向他們的茅舍、他們的獸欄和他們的兵營投擲燃燒的火炬。燒光他們，然後返回我這裡!\n\n為部落而戰!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "復仇者披風間諜的披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][10793] = {title = "弗札克的日記:戰爭警告", objective = "在赤紅守望找到馬庫斯‧阿瑞利恩，薩塔的大將軍。\n\n他位在一個水晶的監牢裡。", description = "這本日記記錄了伊利丹軍隊最近的活動。它也解釋了為什麼弗札克正在征服之路到處遊行。他親自負責捕捉一位薩塔的大將軍。\n\n這位將軍目前被拘禁在一處名為赤紅守望的兵營，位於征服之路的南端。有一個自稱為赤紅法印的神秘團體負責監禁他。如果你選擇進行調查，帶些盟友是聰明的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10794] = {title = "碎手盗贼", objective = "与奥格瑞玛的申苏尔谈一谈。", description = "<name>，这世界上还有许多我们尚未掌握的秘密。奥格瑞玛的碎手氏族可以帮助你学会这些秘密的其中之一：制造毒药。做他们要求你做的事情，首先获得他们的信任吧。\n\n想去奥格瑞玛的话，你必须使用银月城的传送装置抵达幽暗城。然后走出幽暗城外，找到附近的一处飞艇空港。从那里就可以直接飞到奥格瑞玛了。到了那边后，去暗影裂谷中找到申苏尔吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10795] = {title = "與多爾哥克的約會", objective = "殺死血槌營地的多爾哥克。", description = "非常好，我已經看見你在附近，我一直有一些重要的事情想對你講。\n\n有報告說由於某些原因，血槌巨魔計畫對希爾瓦納和魯安曠野發動攻擊。我們不知道是誰或者什麼東西在催促他們做這事，但是我打算趁早摧毀他們的計畫!\n\n攻擊將從血槌營地開始。沿著魯安曠野外面斜坡道向西北走下去，你就會找到它。我要你殺死他們的領導人，多爾哥克!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10796] = {title = "粉碎血槌營地!", objective = "殺死10個血槌槌兵和5個血槌術士。", description = "我聽說你到目前為止對我們所做的比與巨魔戰鬥還要自豪。現在，我將要求你再次面對他們。我要你摧毀血槌營地的巨魔!\n\n要去那裡，就從魯安曠野外的斜坡往西北方走下去。你將在斜坡道的底部找到他們。\n\n祝你好運，<class>!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "黑暗步態長靴雙月肩衛鍊織繫腰晴天腕甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10797] = {title = "古羅的支持", objective = "將柯爾葛羅姆的徽章帶到劍刃山脈的永恆樹林交給指揮官海法斯‧石牆。", description = "一個小雕像標誌從多爾哥克死亡的爪子上掉下來。它與某個古羅有明顯的相似處。\n\n想必斜坡上往東，魯安曠野的永恆樹林有個指揮官海法斯‧石牆會對這東西感興趣!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10798] = {title = "拜訪男爵", objective = "到劍刃山脈的血之環找沙伯邁恩男爵談談。", description = "這是個壞消息。食龍者柯爾葛羅姆是最近對抗希爾瓦納血槌計畫的幕後主使者!\n\n為什麼他在操縱他們，而不只是利用劍刃，我不知道。但如果我們要對付古羅，我們就需要幫助。\n\n我認識一個精通各種奇特魔法的人。他的名字叫沙伯邁恩男爵，你可以在血之環找到他，回到西北邊的斜坡下，再往西南方通過峽谷。\n\n請他幫我們製作一個給古羅的陷阱。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10799] = {title = "進入翻騰峽谷", objective = "收集7個地殼穿刺者毒腺。", description = "非常好，我會製作這個陷阱，但我要先得到一些東西。\n\n附近有個古羅剛好有我要的物品，但你不能挑戰他，還不能。\n\n所以，我們要用附近的地殼穿刺者毒藥製造出一種睡眠粉末。\n\n你可以在西南邊的翻騰峽谷找到他們。幫我帶一堆他們的腺體來，而且動作要快!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n血沸毒藥"}
MultiLanguageQuestData['tw'][10800] = {title = "晚安，古羅", objective = "取得葛魯洛克的袋子。", description = "我已經再次勝過自己。我已經為你製作了熟睡粉末，去用在葛魯洛克身上，那個我談到正守衛著我想要之東西的古羅。\n\n葛魯洛克一直在詛咒之谷，一個在血之環另一邊，飛龍之末東方邊緣的地區。\n\n如果我是你，一旦得到他的大袋子，我將不會再耽擱。灰塵的效果不會持續多久。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10801] = {title = "它是一個陷阱!", objective = "把龍火陷阱帶到劍刃山脈的永恆樹林交給指揮官海法斯‧石牆。", description = "與戈魯爾的兒子和他們的父親相比較，在這個世界上沒有事物能令我更加憎恨!他們屠殺我的族人和我的孩子，現在我將嚐到報仇的滋味!\n\n我已經由一些龍火作成一個陷阱，如果你足夠聰明的話，你正好可以使用它來殺死古羅。\n\n我確信你有屬意的古羅;而我不在意你殺死哪一個。就是快一點，將陷阱拿給你的石牆指揮官。\n\n我渴求報仇的火焰必須用水熄滅!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10802] = {title = "食龍者柯爾葛羅姆", objective = "從圓面巨魔那裡收集3種可怕圖騰。接著在柯爾葛羅姆的祭壇使用沙伯邁恩的陷阱來召喚並殺死食龍者柯爾葛羅姆。\n\n當柯爾葛羅姆死掉以後，把3種可怕圖騰放置在他的屍體旁邊。", description = "我們必須讓巨魔看看我們不是好欺負的。我們必須送出一個訊息。\n\n到圓面之地殺死那裡的巨魔。把他們的頭帶回來。\n\n然後去柯爾葛羅姆的祭壇，並且為他在那裡佈下陷阱。柯爾葛羅姆將會出現，而你必須誘騙他進入陷阱。當他死掉時，在他的屍體附近裝好你的可怕圖騰，以便巨魔能見他們倒下的主人和兄弟，並且知道想毀滅我們所需付出的代價。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "哨嘯之劍尖牙之斧判決者法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][10803] = {title = "圓面之地大屠殺", objective = "殺掉5個圓面蠻卒和3個圓面薩滿。", description = "我知道我們有讓你向圓面之地前進的計畫。你去那裡的時候，我有些事情想要你去做。\n\n我們必須掌握任何能打倒這些山裡的巨魔的機會，否則他們將征服我們，這樣我們就會流盡鮮血無意義的死去!\n\n圓面之地位於西邊。走到西南方，越過橋並穿過隧道。在烏鴉林的西邊可以找到他們。\n\n<name>，我想要你清除圓面之地的劍刃巨魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10804] = {title = "好心", objective = "影月谷，虛空之翼農場的摩德奈要你餵食8隻成熟的虛空之翼龍。", description = "有東西控制住他們了，<race>。\n\n<摩德奈指著頭頂飛翔的虛空龍。>\n\n他們連飛下來吃飯都不肯。我看過幾隻掉到地上，在他們的身體撞擊到地面前就因為過度疲勞而死亡了。\n\n我們一定要救救他們!在水晶附近可以找到的石釘鐮奪怪是他們天生的獵物。殺死鐮奪怪並帶走他們的屍體。把一個屍體放在農場上，然後站著動也不動。只要你不做出任何攻擊性的動作，他們就不會攻擊你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10805] = {title = "戈魯爾之巢大屠殺", objective = "殺死10個劍刃執行者，5個劍刃戰鬥法師，5個劍刃劫毀者和他們的領導人費葛羅姆。", description = "你已經證明你是足智多謀的，現在我想要請你加入我與戈魯爾和他的兒子間的戰鬥。\n\n劍刃家族擁護古羅，當你在別處消減他們的數量時，你還沒有對付到他們最強大的力量。\n\n戈魯爾只用最強壯的巨魔保護他的巢穴外部，而那些就是你必須殺死的人。往北走穿過匕爪峽谷，然後你就會在盡頭發現戈魯爾之巢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10806] = {title = "攤牌", objective = "在茍克祭壇使用沙伯邁恩的徽章，然後殺死茍克。", description = "我們面對劍刃巨魔的主人，苟克，的時刻已經來到。那也是著手處理事情的時刻，去告別古羅的生命。\n\n拿著我的璽戒。當你到了苟克祭壇時，使用它，而我到來加入你。\n\n我們將一同毀滅苟克。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "裂蹄皮護腿油布馬褲紅玉之冠罪人眼罩黑邊胸鎧獅子胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10807] = {title = "灰舌破碎者", objective = "『感化者』瓦倫恩要你去巴瑞廢墟殺死3個灰舌駕馭者、4個灰舌戰士還有6個灰舌薩滿。為占卜者完成任務會讓你的奧多爾聲望降低。", description = "破碎者們一直都畏懼著灰舌部族。他們其中不乏兇惡又殘忍的成員，全都是由阿卡瑪親手挑選的。他們好鬥殘忍的程度不下於任何一個納迦、惡魔或者伊利丹的血精靈部隊，而他們現在聚集了大批的成員在巴瑞廢墟，就在這裡的北邊。在他們對我們發動攻擊前去那邊削減他們的成員數目吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10808] = {title = "阻礙黑暗議會", objective = "殺掉黑暗議會祭儀師，並且使用帕莎之杖去結束黑暗議會的召喚儀式，然後返回熔岩平原的帕莎那裡。", description = "黑暗議會的幽靈想透過一種在史凱瑟隆營地南邊的熔岩地窖裡進行的儀式，召喚古老而強大的邪惡力量。\n\n古爾丹的魔法與他們自己的混在一起，使他們能夠幫助這種生物顯現在我們的世界!我們不能允許這種事情發生，<name>。它所帶來的死亡和毀滅是無法想像的!\n\n帶著這個權杖到召喚的場地去，並使用其魔力，一勞永逸地阻止黑暗議會!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "史凱瑟隆生存外套灰燼淬鍛腿甲餘燼王冠符文史凱瑟隆腿鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][10809] = {title = "懸賞：座狼大師科洛斯", objective = "殺死座狼大師科洛斯，並且將他的頭帶到斷脊氏族崗哨交給達克豪上尉。", description = "海報寫著:\n\n「座狼大師科洛斯領導血之谷氏族的座狼騎士。懸賞他的人頭，因為他的騎士們向開往斷脊氏族崗哨的補給列車勒索高額的過路費。」\n\n「斥候到薩斯葛爾裡向他報告，能帶來這個壞人頭顱的英雄將贏得部落的感謝，以及一大筆的賞金。」\n\n「-達克豪上尉」您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10810] = {title = "破損的面具", objective = "到劍刃山脈的永恆樹林，把破損的面具交給歐瑪利‧贊普奈。", description = "當你檢視破損的面具的時候，你聽見面具發出奇怪的聲音。假如面具沒有破損的話你可以聽見更清楚的聲音。\n\n魯安曠野的歐瑪利‧贊普奈可能可以修理這個面具。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10811] = {title = "尋找奈爾斯阿拉古", objective = "尋找奈爾斯阿拉古，虛空之翼軍團的庇護者。", description = "他們的庇護者翱翔在高空中，<name>。或許你對他孩子的仁慈已感動了他的心。尋找奈爾斯阿拉古並且得到他的幫助。同時，你或許能解決虛空之翼龍的困境。\n\n<摩德奈指向天空。>\n\n飛的很高，朋友...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10812] = {title = "神秘面罩", objective = "到劍刃山脈的永恆樹林，把神秘面罩交給野蠻領主安德烈利安。", description = "沒問題，修好了。你問我這是什麼?哦，這是一個通訊裝置-它可以讓那些笨蛋跟彼此通訊。你知道的呀，燃燒軍團!我建議你把這個面具交給野蠻領主安德烈利安。他就在那邊走來走去。他總是不停的移動。\n\n那就快點去吧，他一直很想得到這個東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10813] = {title = "葛銳洛克之眼", objective = "使用雷札克的裂片去俘虜一顆葛銳洛克之眼，然後靠近雷札克的大鍋去提煉它。在它被移除之後，把雷札克的裂片還給他。", description = "<name>，你已經勇敢面對了血之谷獸人的巢穴，可怕的薩斯葛爾，並且存活下來!或許你有幫助我的力量，因為我的目的是注視進最黑暗的巫者，葛銳洛克的心智!\n\n拿著這塊裂片。用它蠱惑一顆葛銳洛克之眼，並且將它與自己結合。回到這裡並且靠近我的大鍋...它將從你身上拉出眼睛。\n\n去吧，<name>。小心使用 -- 只要它打開了一條小縫，葛銳洛克之眼就會把你出賣給我們的敵人!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10814] = {title = "奈爾斯阿拉古的傳說", objective = "與奈爾斯阿拉古交談並且聽他的故事。", description = "我有你可能有用的訊息。請聽聽我必須告訴你的，<race>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10815] = {title = "弗札克的日記:戰爭警告", objective = "在赤紅守望找到馬庫斯‧阿瑞利恩，薩塔的大將軍。", description = "這本日記記錄了伊利丹軍隊最近的活動。它也解釋了為什麼弗札克正在征服之路到處遊行。他親自負責捕捉一位薩塔的大將軍。\n\n這位將軍目前被拘禁在一處名為赤紅守望的兵營，位於征服之路的南端。有一個自稱為赤紅法印的神秘團體負責監禁他。如果你選擇進行調查，帶些盟友是聰明的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10816] = {title = "開拓神聖之地", objective = "復仇者阿魯曼要你殺死8個影月殺戮者，8個影月挑選者和4個影月暗織者。\n\n為奧多爾完成任務會讓你的占卜者聲望降低。", description = "你對抗巴瑞的破碎者做得很好，<name>。讓我們看看你對伊利丹最可怕的軍隊可以做的如何。\n\n影月氏族的魔獄獸人佔領了阿塔莫露臺，那兒曾經是非常神聖的地方，在那裡的阿塔莫水晶被用於神聖的典禮上。\n\n我們有理由相信，他們把一顆真的阿塔莫水晶藏在附近，但是我們的水晶球占卜什麼也沒顯示。雖然如此，那些魔獄獸人是在德萊尼的神聖地上，他們的存在必須被解決。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "阿塔莫之冠老舊的皮束腕黑邊鍊甲護脛覆蓋灰燼的頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][10817] = {title = "巨大的懲罰", objective = "『感化者』瓦倫恩要你殺死8個影月殺戮者，8個影月挑選者和4個影月黑暗編織者。\n\n為占卜者完成任務會讓你的奧多爾聲望降低。", description = "你對抗灰舌破碎者做得很好，<name>。如果你可以的話，我還有另一項挑戰給你。\n\n沒多久以前，星光聖所遭受到伊利丹的魔獄獸人一次驚人的攻擊。\n\n我們確定那是佔據阿塔莫露臺的影月獸人所犯下的罪行。\n\n給他們知道占卜者不是好欺負的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "阿塔莫之冠老舊的皮束腕黑邊鍊甲護脛覆蓋灰燼的頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][10818] = {title = "沙伯邁恩男爵請求你的出現", objective = "到劍刃山脈的血之環找沙伯邁恩男爵談談。", description = "<name>，當你出去對付<class>的時候，沙伯邁恩男爵派他的寵物龍帶來一個訊息。\n\n他在找你本人。據我了解，他想要你率領他自己對古羅的戰鬥。\n\n我猜測你是在整個外域裡最有資格幫助他的人，但是如果我是你，我會先與兩位朋友聯繫，並且要他們在血之環加入你的行列。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10819] = {title = "邪誓防毒面具", objective = "到劍刃山脈的煉冶場:怒氣，然後戴著邪誓防毒面具使用軍團通報器。\n\n已提供物品：\n", description = "我有一個非常特殊的任務要交給你，<name>。我要你滲透進入東邊的煉冶場:怒氣。當你到達煉冶場你將需要戴上邪誓防毒面具然後找到軍團通報器。一旦你找到通報裝置就跟裝置另一邊的人談話，不管他是誰。\n\n假如一切順利你就可以誆騙這些惡魔做出一些不光明正大的事情!試著告訴那個惡魔，煉冶場:怒氣已經造反了。\n\n祝你好運<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10820] = {title = "矇騙敵人", objective = "殺死4個末日之爐侍者和4個末日之爐工程師。", description = "有話快說!要是讓我聽到你在浪費我的時間，你就死定了!\n\n什麼?煉冶場造反了?這不可能是真的!我的手下不敢挑戰我的權威。\n\n既然這樣，他們每一個人都將為他們的叛變付出代價，非常大的代價。把他們都殺光事情就結束了!執行完我的命令之後向我回報，不然我就把你一起解決掉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10821] = {title = "你被開除了!", objective = "殺死末日哀嚎者。", description = "末日哀嚎者沒有想辦法阻止那場叛變嗎?她真大膽!她一直以來都在質疑我的權威。不論如何，這會是她的最後一次了。你必須召喚她然後親自解決她。\n\n她的煉冶場守衛擁有可以召喚她到煉冶場:怒氣的鑰匙。取得五把鑰匙然後啟動五座軍團尖塔。那些方尖塔的啟動時間很短，所以確認要全部同時啟動。記住，煉冶場守衛擁有比較多的鑰匙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊墜飾風王指環永恆樹林遊俠披風魯安曠野腕甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10822] = {title = "一個日怒徽章", objective = "Even the smallest contribution to our cause is noted, <name>. Our enemies are many, but we shall prevail!", description = nil, progress = "Even the smallest contribution to our cause is noted, <name>. Our enemies are many, but we shall prevail!", completion = "Victory to the Scryers! Kael's forces will soon crumble.", rewards = nil}
MultiLanguageQuestData['tw'][10823] = {title = "更多的日怒徽章", objective = "How fares the battle against Kael's forces?", description = nil, progress = "How fares the battle against Kael's forces?", completion = "You're making a name for yourself, &lt;name&gt;. Keep it up.", rewards = nil}
MultiLanguageQuestData['tw'][10824] = {title = "日怒徽章", objective = "星光聖所的戰鬥法師維爾阿拉要你為她帶來10個日怒徽章。\n\n為占卜者完成任務會使你的奧多爾聲望降低。", description = "占卜者的生存視超額徵募的凱爾薩斯而定。每一個來自奎爾薩拉斯並加入他的朝聖者都讓他更接近勝利。我們的對手是真實的。\n\n然而，我們很快將沒有新兵，到時候就要看哪一方能較快殺死對方。把和凱爾薩斯及伊利丹結盟的高階血精靈所佩戴的日怒徽章帶來給我，證明你對占卜者的價值。你可以在西邊的日蝕崗哨和東北邊的卡拉伯爾廢墟找到他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10825] = {title = "未知的真相", objective = "將葛瑞納寶珠送到劍刃山脈的永恆樹林給林木守衛蕭恩。", description = "這個奇怪，魔法的寶珠從阿拉卡的廓羽下方落下。\n\n充滿著怪異，紫色的光輝，寶珠跟著一個聽不到的節拍跳動著。拿著它使你略感不舒服，因此你迅速地把它放到你的背包裡。\n\n或許穿過隧道越過龍骨橋，在魯安曠野西邊的林木守衛蕭恩會有興趣看看它?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10826] = {title = "薩格拉斯印記", objective = "取得10個薩格拉斯印記交給影月谷的先驅者沙洛尼恩。\n\n為奧多爾完成任務會讓你的占卜者聲望降低。", description = "現在你應該明白為什麼我們要對抗燃燒軍團還有他們的部下了。\n\n假如你想向奧多爾證明你自己，幫我帶來燃燒軍團還有他們的暗影議會成員的高階徽記。在影月谷這邊你可以找到強大的燃燒軍團成員，位在西邊遠方的軍團要塞還有死亡熔爐。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10827] = {title = "更多的薩格拉斯印記", objective = "Do you bear more of our enemies' insignias, <class>? The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", description = nil, progress = "Do you bear more of our enemies' insignias, <class>? The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", completion = "You continue to prove your worth, &lt;name&gt;. Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded.", rewards = nil}
MultiLanguageQuestData['tw'][10828] = {title = "一個薩格拉斯印記", objective = "I'll take any leftover marks you might have. Do not worry, your actions will be duly noted.", description = nil, progress = "I'll take any leftover marks you might have. Do not worry, your actions will be duly noted.", completion = "You continue to prove your worth, &lt;name&gt;.", rewards = nil}
MultiLanguageQuestData['tw'][10829] = {title = "樹佬長者必須知道", objective = "找住在劍刃山脈烏鴉林裡的知識古樹，樹佬長者交談。", description = "這真麻煩!阿拉卡害長者和保衛者被邪惡靈魂附身!\n\n但是有一位長者無論如何不能被影響。他的名字是樹老長者，如果我們要拯救烏鴉林的樹木，那你必須立刻去找他!\n\n回到烏鴉林。你可在過了葛瑞許納什的道路分岔處找到他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10830] = {title = "淨化樹林", objective = "收集5個葛瑞許納什寶珠和5根凶暴幼羽，然後將它們合併成驅邪羽毛。使用這些羽毛驅除並殺掉5個佔據烏鴉林葉鬚樹人的可伊靈魂。", description = "葛瑞納已經讓葉鬚樹人和石木樹人被邪惡的可伊靈魂佔據。\n\n我們必須拯救這些樹，否則整個烏鴉林很快將永遠消失!\n\n將葛瑞許納什找到的葛瑞許納什寶珠中的魔法，與凶暴烏鴉身上的一根凶暴幼羽結合。\n\n使用結合成的驅邪羽毛引出可伊靈魂並盡快殺了它。這個儀式不足以釋放石木樹人。但如果我們拯救了足夠的葉鬚樹人，他們也將獲得自由。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "樹幹戒指烏鴉之木驅逐者指環葉鬚指環石木樹皮之戒您會收到：\n\n"}
MultiLanguageQuestData['tw'][10834] = {title = "葛銳洛克『暗眼』", objective = "殺死葛銳洛克『黑眼』並且將葛銳洛克的眼罩帶去給斷脊氏族崗哨的雷札克。", description = "葛銳洛克『暗眼』已經將一部份的自己抵押給黑暗力量，並且因而獲得極強的魔法。他失去的眼睛在某個地獄坑洞深處燃燒著，現在一個惡魔的小飾物...和掩蓋他背叛的眼罩掌握著它自己的黑暗秘密。\n\n把葛銳洛克的眼罩帶來給我，<name>，而我將為你的效勞大大地酬謝你...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "神聖羽毛外衣野性靈魂上衣金紋外套鍍金赤紅胸鎧噬骨狂怒者外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][10835] = {title = "藥劑師安拓維奇", objective = "到地獄火半島的索爾瑪，把艾柏瑞克的發現帶給藥劑師安拓維奇。", description = "<name>，我已經準備好關於血之谷獸人發現的初步報告。我在索爾瑪的同事，藥劑師安拓維奇會很高興收到它們。他也研究魔獄獸人的現象...希望能防止這樣的悲劇再次降臨在我們的獸人盟友身上。\n\n把這份報告拿給他，我將繼續研究你帶來給我的血液。如果幸運的話，我們將找出魔獄獸人痛苦的根因。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10836] = {title = "滲入龍喉堡壘", objective = "影月谷，虛空之翼農場上方飛得很高的奈爾斯阿拉古要你殺死15個龍喉獸人。\n\n龍喉堡壘裡所有的龍喉獸人都可以。", description = "我需要時間才能想出一個辦法去救我的孩子和夥伴。你這次要相信我，凡人。\n\n到龍喉堡壘冒險去吧，它位於虛空之翼農場的東方邊緣，並且將你發現的所有龍喉獸人消滅。接著發生的混亂和騷動應該對他們的計畫有相當的影響。\n\n先警告你，我的一些族人太厲害了 - 龍喉腐化了他們的心。對他們來說，唯一的解決就是死。我允許你去結束他們的生命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10837] = {title = "前往虛空之翼岩架!", objective = "影月谷，虛空之翼農場上方飛得很高的奈爾斯阿拉古要你從虛空之翼岩架收集12顆幽藤水晶。", description = "我相信我能以本身的力量給予幽藤水晶附魔的效能。灌輸在這些水晶內的力量足以將那些龍從奴役他們的主人手中解救出來。\n\n前往虛空之翼岩架，一座在影月谷破碎沙洲外的小島，向東南方去。你將在虛空之翼岩架發現幽藤水晶。當你已經收集足以裝滿你背包的水晶時，回到我這裡。\n\n<name>，小心現在居住在島上的龍喉者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10838] = {title = "惡魔占卜器", objective = "在地獄火盆地裡使用惡魔占卜器，等它調和，然後帶走讀數。\n\n將惡魔占卜器和惡魔占卜器讀數帶回索爾瑪給藥劑師安拓維奇。", description = "惡魔占卜器準備好了。把它帶到地獄火堡壘後面，朝向地獄火盆地，在地上召喚它。它就會開始調整自己至與地獄火堡壘調和。在它調和後，對占卜器說話並抄下它告訴你的東西。把那個抄本帶來給我...\n\n去吧，<name>，準備好再去。地獄火堡壘一定會偵測到占卜器並派看守人去破壞它!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "惡魔靈魂囚牢您會收到：\n\n"}
MultiLanguageQuestData['tw'][10839] = {title = "迷霧斯奇司:泰洛克黑石", objective = "在迷霧斯奇司的泰洛克黑石上使用淨化魔棒，並返回白骨荒野的難民商隊找『覺醒者』奇瑞克。", description = "迷霧斯奇司在商隊的西北方，撒塔斯南邊森林的一片獨立的小樹林裡。謠傳司凱堤斯的殖民隊已經建造了一個崇拜的邪惡祭壇。如果斯奇司的阿拉卡要被救贖，這個泰洛克黑石就必須被淨化。\n\n帶著這個淨化魔棒並把它用在黑石上。透過阿達歐祝福，魔棒的純潔應足以帶給黑石清澈。現在去吧，願聖光照耀在你身上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10840] = {title = "聖光之墓", objective = "高階祭司歐格蘭要你進入聖光之墓，殺死10個以太虛空術師和10個以太盜掠者，然後回到難民商隊找他。", description = "向東走，埋在被燒焦的沙子下的即是聖光之墓，一個死者失落的安息之處方。在我們的商隊被伏擊之前，我正要去墓地淨化它邪惡的靈魂。\n\n我卻不知道它已經被另一種邪惡所侵擾。甚至現在，以太族為了死者幾世紀以前獲得的小飾物和紀念品而劫掠死者的身體。\n\n當我們的商隊努力求生存時，我能做的卻很有限。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10842] = {title = "復仇先驅", objective = "高階祭司歐格蘭要你進入聖光之墓並打倒5名復仇的德萊尼。", description = "聖光之墓已經被暗影議會腐化了，德萊尼死者變成了被詛咒的靈魂，對活著的人懷著強烈的憎恨、憤怒且困惑。\n\n進入墓穴，找出這些可憐的受害者。讓他們安息，這是他們應得的。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n遠古德萊尼戰爭咒符遠古德萊尼秘法聖物\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][10843] = {title = "不知道從什麼時候開始...", objective = "殺死劍刃崗哨的巨魔領導人，葛諾斯‧布羅格納。", description = "不知道從什麼時候開始，我們就已經在和劍刃巨魔作戰了。\n\n我們已經設法把他們擊退，因此現在他們只微弱的掌握住劍刃崗哨。按你來的路回去，在剃刀山脊的西南邊緣。\n\n藉由殺死他們的領導人，葛諾斯‧布羅格納，向我證明你的價值。\n\n讓我們看看當你與巨魔作戰時，你是塊什麼料。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10844] = {title = "DEPRECATED", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10845] = {title = "殺死幼龍之母", objective = "殺死魔翼 。", description = "我的獵人剛完成美聲山脊的偵察任務回來。看來寄生於那些水晶的虛空龍已經大幅增加並威脅到我們。\n\n既然你已證明你是一個有能力的殺手，讓我們看看你的<class>技能是否敵的過一隻成年的龍。\n\n向南方穿過鱗翼沙洲並找到美聲山脊。進入那裡並殺死他們的母親，魔翼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "恐懼之翼腰帶虛空毛皮手套雌蜘蛛護腿虛空保衛者胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10846] = {title = "了解摩克納薩爾", objective = "殺掉維克尼爾阿拉卡的領導者，維克。", description = "<李歐羅克斯用一種讓你的靈魂凝結的眼神注視著你的眼睛。>\n\n你來到摩克納薩爾，但是你不了解我們。你不了解我們鬥爭以求生存。\n\n假如你要了解我們，那麼你必須忍受一次那種鬥爭的滋味。\n\n南方是維克尼爾阿拉卡。他們在一個叫做索格瑪領土的洞穴裡奴役一群巨魔，而他們的領導人，維克也在那裡。\n\n殺了他!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10847] = {title = "司凱堤斯之眼", objective = "將瑞斯克之眼還有辛諾之眼交給撒塔斯城內陰鬱城的『贖罪者』里拉克。", description = "厄運從司凱堤斯的懸崖傾聽著。\n\n我的族人，阿拉卡，面臨被無法形容的邪惡掩蔽的命運。我們太常濫用黑暗魔法去做壞事了。透過阿達歐我已經學習了聖光和救贖。\n\n泰洛克透過被黑暗術施法的眼球從司凱堤斯窺看他的殖民地。從泰洛卡北邊的迷霧瑞斯克和迷霧辛諾偷取這些眼珠。讓我看見泰洛克所看見的。讓我透過司凱堤斯的眼睛窺探。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n超強效治療藥水超強效法力藥水\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][10848] = {title = "迷霧瑞漢茲:邪惡靈魂", objective = "殺死4個死亡之爪靈魂、4個尖嘯靈魂還有2個烏鴉之魂然後回報給難民商隊的『覺醒者』奇瑞克。", description = "迷霧瑞漢茲是一塊特別邪惡的司凱堤斯殖民地。\n\n儘管村莊被奧齊頓災難所毀滅，泰洛克的影響力依舊存在那裡的邪惡靈魂中。向西前往迷霧瑞漢茲，殺死那些殘忍卑鄙的人。你將在暗影之墓西邊發現他們，在白骨荒野和泰洛卡森林的邊境上。\n\n這將是我們對抗泰洛克和司凱堤斯的守護者的第一擊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "鷹爪樹枝魔杖覆蓋羽毛的弓您會收到：\n\n"}
MultiLanguageQuestData['tw'][10849] = {title = "尋找奇瑞克", objective = "到白骨荒野的難民商隊，將里拉克的書信交給『覺醒者』奇瑞克。", description = "其他阿拉卡參加了泰洛克的背叛。\n\n奇瑞克認出泰洛克是一個騙徒，並非一位先知。泰洛卡所預測唯一的預言是出自於他自己召喚的毀滅。\n\n是奇瑞克從司凱堤斯英勇地領導我們。在我們朝聖到撒塔斯之後，奇瑞克便到殖民地尋找其他人。\n\n這份公文訴說眼球看過的一切。一定要告訴奇瑞克!沿著撒塔斯外南方的道路到白骨荒野，並且尋找商隊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10850] = {title = "虛空火焰引擎裡的虛空氣體", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10851] = {title = "敵人的圖騰", objective = "收集5個劍刃氏族圖騰。", description = "尊敬一個人的祖先有正確的方式，也有錯誤的方式。\n\n劍刃巨魔帶著圖騰，但是他們並非用它們來表現他們的尊敬。相反的，他們想使用它們去操作並且控制。\n\n我們應該偷取他們的圖騰，因為他們不值得擁有!我們會把它們拿來做更好的利用。\n\n去西方的劍刃崗哨，就在剃刀山脊的西南邊。殺死劍刃秘法師和粉碎者，並從他們那裡拿走圖騰!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10852] = {title = "失蹤的朋友", objective = "伊森要你在迷霧斯奇司找到他的12個失蹤的朋友然後回到難民商隊找他。", description = "我們停留在這邊的原因是因為有一些人在半夜的時候闖入並且發出了很大的噪音。那個感覺是很可怕的。我不知道我們什麼時候可以再度上路。\n\n我的一些朋友已經失蹤了。我不知道他們在哪裡。我想那些可怕的鳥人把他們帶到了西北邊。他們八成是被鎖在籠子之類的東西裡面。假如你找到他們的話那就太好了。我有點擔心他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破損的蒸汽坦克遙控器"}
MultiLanguageQuestData['tw'][10853] = {title = "呼喚靈魂", objective = "使用召靈圖騰來收集8個次級虛空龍靈魂。", description = "美聲山脊的虛空龍靈魂需要解放。\n\n虛空龍不永遠都是虛空龍。他們過去是黑龍。\n\n但是，由於這個世界的毀滅，一股虛空能量改變了一切，並且產生了改變幼龍蛋的副作用。\n\n現在他們全都是以前自身的扭曲版本。我們必須幫助他們找到平靜。\n\n要這樣做就要去殺死一隻靠近召靈圖騰的龍，然後自它身上取走它的靈魂。您會收到：\n\n", progress = nil, completion = nil, rewards = "虛空權勢硬板靴摩克納薩爾勇士肩衛祭儀師頭盔虛空龍腕甲您會收到：\n\n藥用龍之精華"}
MultiLanguageQuestData['tw'][10854] = {title = "奈爾斯阿拉古的力量", objective = "飛翔在影月谷的虛空之翼農場上方的奈爾斯阿拉古要你釋放5隻被奴役的虛空之翼龍。", description = "帶著這顆附魔虛空藤水晶走上你回到龍喉堡壘的路。到了那裡，尋找那些被奴役的龍並召喚附魔幽藤水晶的魔法。我會傾洩自己的能量，讓龍掙脫俘虜著他們的束縛。當你看見龍已經掙脫束縛時，幫助它戰勝它的俘虜者!因為監禁的關係它一定是虛弱的。\n\n解救所有你能找到的龍，並且返回我這裡，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10855] = {title = "惡魔劫奪者，不用了謝謝!", objective = "從熔爐基地:遺忘的甘納格機電師身上取得5份濃縮的虛空氣體，就在風暴之尖的西北方，並把它們裝填進附近閒置的惡魔劫奪者。在你完成這項任務之後，返回虛空巡者那魯利斯那裡。", description = "啊，是的 - 惡魔劫奪者!軍團無疑是最可怕的機械創造物。這些可惡的東西中至少有三座瞄準了風暴之尖。\n\n很幸運的，它們還未啟動。這給予我們透過破壞取代殘暴武力去對付他們的可能性。\n\n由熔爐基地:遺忘的甘納格手中取得凝結的地下瓦斯:用它淹沒並灌滿一只惡魔劫奪者附近的油箱。我有一種感覺，它的引擎會出問題。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10856] = {title = "最佳的防禦", objective = "虛空巡者那魯利斯要你在熔爐基地:苦難殺死12個憤怒使者，在風暴之尖的北方。", description = "工業破壞的勇敢行動只能讓我們走到現在這一步，<name>。熔爐基地:遺忘是惡魔劫奪者的一個集中地，熔爐基地:苦難則是他們軍隊的臨時基地，因為它是大部分軍團的傳送設備所在地。\n\n我要你進入那裡削減他們的數量。他們現在必定有充分的憤怒使者軍團，而我們就是不能允許它發生。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10857] = {title = "傳送這個!", objective = "虛空巡者那魯利斯要你對熔爐基地:苦難的莫阿格使用精神干擾魔棒並且對煉冶場的三個傳送器使用他們的引爆傳送器能力。", description = "儘管殺死惡魔很有趣，但是當軍團持續用它的傳送器輸送任何被我們殺死的替補成員時，對我們完全沒好處。\n\n不幸地，我手邊沒有任何威力強大的爆裂物...不過負責維持傳送器運作的莫阿格那有。\n\n帶著這根魔棒...我已經調整它的功率去干擾莫阿格的大腦頻率。回到熔爐基地:苦難並在你能看到的任何莫阿格身上使用它。你不會有太長的時間，但你將能使用他們的破壞爆裂物摧毀鄰近的傳送器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "韌化德萊尼水晶符文銀法杖破壞之斧虛空巡者之刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][10858] = {title = "凱瑞納古", objective = "到龍喉堡壘尋找凱瑞納古。", description = "我羞愧地再次開口請求你的幫助，<name>，但是你是我們一族的唯一希望。沒有我的伴侶，虛空之翼的龍們可能會全部死去。\n\n想辦法抵達龍喉堡壘的頂端，並找到凱瑞納古。\n\n我們會在上空盤旋。萬一在他們的防禦過程中出現中斷，虛空之翼的力量將向底下展開攻擊來幫助你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10859] = {title = "收集寶珠", objective = "使用寶珠召集圖騰收集15個雷森光球。", description = "雷森以太族有一種奇怪的儀器會發出微小、粉紅色光芒的飄浮光球。它們讓我想起靈魂。\n\n它們不會與以太族死亡時所釋放的大黃球相混淆，這些完全是別種東西。\n\n我要你到北方的雷森平台設置一些圖騰，這些圖騰將會吸引粉紅光球。\n\n把它們帶回來給我這樣我才能確切地判斷它們是什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10860] = {title = "摩克納薩爾的款待", objective = "收集3個迅猛龍肋骨還有3份毒蛇肉。", description = "餓嗎，<race>？偉大的靈魂會幫助那些自助者。如果你想要掙一頓飯，我建議你注意聽著，因為布拉格爾那裡不會給你任何免費的東西，而且也不可口！\n\n剃刀山脊和鱗翼沙洲的迅猛龍及鱗翼具有你從未嚐過之最美味的兩種佳餚中所需要的東西。把他們的迅猛龍肋骨和毒蛇肉帶來給我，我將為你做出這兩道菜。\n\n我甚至可以教你如何自己烹煮它們，如果你動作快的話。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n摩克納薩爾小肋排香脆巨蛇肉食譜：摩克納薩爾小肋排食譜：香脆巨蛇肉"}
MultiLanguageQuestData['tw'][10861] = {title = "迷霧莉斯克：先發制人的攻擊", objective = "打破在迷霧莉斯克受詛咒的蛋。在返回難民商隊找『覺醒者』奇瑞克之前，救回3隻幼鳥並殺掉3隻有害的幼鳥。", description = "西南方不幸的殖民地叫做迷霧莉斯克，泰洛克的爪牙試圖在他們的鳥類同胞孵化之前玷污他們。莉斯克的黑暗男巫士將蛋用暗影詛咒封在容器裡。當幼鳥孵出時，他們不用腦子地為泰洛克效命。\n\n前往迷霧莉斯克，並在咒語有時間滲入前，提前破開這些蛋。即使你太遲了，你也能殺死已被污染的鳥類。\n\n記住，聖光的光芒在黑暗中是最明亮的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "雄鷹紋刻護腕羽毛臂環鷹爪遠行護腕羽毛腕輪您會收到：\n\n"}
MultiLanguageQuestData['tw'][10862] = {title = "向部落投降", objective = "瑞克格要你在撒塔斯城內的陰鬱城尋找『贖罪者』里拉克，並且要求他跟他的人民歸順部落。", description = "那些懦弱的阿拉卡每天都攻擊我們。他們偷襲我們的獵人而且有時候還突襲到城內來。我們盡可能的殺死他們，但是他們的魔法很強大而且他們時常都可以逃出我們的毒手。\n\n我聽說有些阿拉卡要求跟部落維持友好關係。他們住在撒塔斯城的西北邊。他們的首領是『贖罪者』里拉克。去陰鬱城找他，當你找到他的時候要求他投降。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10863] = {title = "阿拉卡的秘密", objective = "戴娜‧甘迺迪女士要你在撒塔斯城內的陰鬱城找到『贖罪者』里拉克，並且向他探聽他願意分享的阿拉卡秘密。", description = "在邊境這裡我們必須每天對付阿拉卡。他們高興就襲擊我們，突襲我們的補給線，並且殺死我們的斥候。\n\n然而，我們對這些謎一般的生物幾乎不瞭解。我已經得到消息，西北方撒塔斯城的阿拉卡和我們不是敵對的。他們或許願意分享他們種族的秘密。\n\n『贖罪者』里拉克是他們的領導人。他住在陰鬱城的北方區域。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10864] = {title = "靈魂的負擔", objective = "殺死20個破碎之手獸人，然後回到索爾瑪找藥劑師安拓維奇。", description = "我有一個儀器，惡魔占卜器，它能分析邪惡魔法。我將讓你使用占卜器，但是首先...你必須安撫它。占卜器，你明白的，在裡面困著一隻有浩瀚智慧的生物，而它的需要，我們可以說，十分古怪。\n\n要安撫占卜者，你必須殺死獸人。具體的說，他們必須是破碎之手獸人 -- 占卜者需要他們的靈魂。\n\n等你獲得靈魂的時候回來找我。你將可在地獄火堡壘北方，以及南方及周圍發現獸人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10865] = {title = "通知李歐羅克斯!", objective = "通知李歐羅克斯關於雷森以太族的企圖。他的位置在劍刃山脈的摩克納薩爾村。", description = "快一點，你必須通知李歐羅克斯在雷森平台發生了什麼事!\n\n那些寶珠是由靈魂所組成，他們之中的一些人是摩克納薩爾!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10866] = {title = "『疲憊者』祖魯希德", objective = "殺死『疲憊者』祖魯希德然後取得祖魯希德的鑰匙。使用祖魯希德的鑰匙打開祖魯希德的鎖鍊釋放凱瑞納古。", description = "他隱藏在我的思想裡，凡人。他等我放棄…讓我順從他的意志。\n\n而這將是他毀滅的原因。我將召喚他。我將告訴他我會按他要求的去做。當他出現時，殺死他並且拿到這把鑰匙！\n\n要知道:祖魯希德是具有未知力量的一個古老獸人。伊利丹肯定已經更進一步授權他。你在為我的要求冒生命危險。你確定你希望做這樣的犧牲嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10867] = {title = "唯一的回應", objective = "取回靈魂收集品。", description = "我們對於這種...這種，對我們祖先靈魂的污辱只能有一種回應!\n\n<name>，假如你可以幫助我們歸還那些受尊崇的往生者靈魂到他們適當的安息地，就回去雷森平台。\n\n回去那邊殺死雷森直到他們的領導者奈薩斯王子洛薩恩露出他膽小的面容。殺死他然後取回那些靈魂，交給招魂師多赫加!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "摩克納薩爾披肩喚靈面罩摩克納薩爾英雄窄褲靈魂救助者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][10868] = {title = "阿拉卡作戰方式", objective = "諫言者菲拉要你殺死14個辛諾鷹爪還有6個辛諾巫士然後回到碎石堡找她。", description = "阿拉卡又攻擊我們了，這一次他們趁半夜的時候襲擊我們，然後在我們可以衝出去跟他們正面交鋒之前，就使用他們的黑暗魔法逃脫。他們使用召喚法陣來復活他們死亡的戰士，但要是我們攻擊他們的家園，他們就不能逃跑了。迷霧瑞斯克還有迷霧辛諾就在這裡的北邊和東北邊。\n\n找到這些阿拉卡的巢穴，然後盡可能地殺光他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10869] = {title = "抑制阿拉卡", objective = "葛拉伏汗中尉要你殺死14個辛諾爪牙還有6個辛諾巫士然後回到艾蘭里堡壘找他。", description = "阿拉卡再度攻擊我們，這一次他們趁半夜的時候襲擊然後在我們整理隊伍攻擊之前就使用他們的黑暗魔法逃脫了。迷霧瑞斯克還有迷霧辛諾就在這裡的北邊和西北邊。\n\n找到這些阿拉卡的巢穴然後盡可能得殺光他們。他們也許不怕我們，但至少我們可以削減他們的戰力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10870] = {title = "虛空之翼的盟友", objective = "讓凱瑞納古送你去虛空之翼農場見摩德奈。", description = "請讓我送你回去見摩德奈。我相信他想要再次見你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "虛空之翼保衛者之盾虛空之翼防衛者之盾虛空之翼軍團之爪虛空之翼女巫符咒虛空之翼巫師符咒您會收到：\n\n"}
MultiLanguageQuestData['tw'][10871] = {title = "虛空之翼的盟友", objective = "讓凱瑞納古送你去虛空之翼農場見摩德奈。", description = "請讓我送你回去見摩德奈。我相信他想要再次見你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "虛空之翼保衛者之盾虛空之翼防衛者之盾虛空之翼軍團之爪虛空之翼女巫符咒虛空之翼巫師符咒您會收到：\n\n"}
MultiLanguageQuestData['tw'][10872] = {title = "『疲憊者』祖魯希德", objective = "殺死『疲憊者』祖魯希德然後取得祖魯希德的鑰匙。使用祖魯希德的鑰匙打開祖魯希德的鎖鍊釋放凱瑞納古。", description = "他隱藏在我的思想裡，凡人。他等我放棄...讓我順從他的意志。\n\n而這將是他毀滅的原因。我將召喚他。我將告訴他我會按他要求的去做。當他出現時，殺死他並且拿到這把鑰匙!\n\n要知道:祖魯希德是具有未知力量的一個古老獸人。伊利丹肯定已經更進一步授權給他。你在為我的要求冒生命危險。你確定你希望做這樣的犧牲嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10873] = {title = "夜裡被劫走的人", objective = "斥候納夫靈要你去幽網山脊釋放6名被網住的薩塔戰士，然後回到薩塔營地找他。", description = "我們的小哨站遭受不斷的攻擊。數天前我們在白骨荒野東南方的邊界遭受幽網山脊的蜘蛛們襲擊。它們的攻擊使得我們許多人中毒並且被蜘蛛網住拖走了。我們的一些士兵在匆忙之中拿起了身邊的武器裝備，在夜色中追補那些蜘蛛。\n\n我們已經好幾天沒看到我們被抓走的俘虜或者外出追捕那些蜘蛛的士兵了。我們希望有些人還活著，也許只是被蜘蛛囚禁起來而已。我們的人數太少了。你可以幫忙搜救我們的人嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10874] = {title = "迷霧撒拉斯:火源信號", objective = "難民商隊的『覺醒者』奇瑞克要你熄滅迷霧撒拉斯的四個火源信號。", description = "泰洛克的棲息地，司凱堤斯，隱現在東邊白骨荒野的上方。迷霧撒拉斯在司凱堤斯的底部，那是泰洛克最受人畏懼的領地。透過在迷霧撒拉斯的要塞，泰洛克的前鋒賢者發動對聖光的戰爭。\n\n撒拉斯的壞蛋們跟他們的主人透過一種複雜的魔法火源信號來溝通。往東邊去，<race>，消滅那些火源。一旦迷霧撒拉斯被消滅，我們就可以策劃攻陷司凱堤斯。\n\n但是我想得太遠了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "可可瑞克的徽章貪婪魔爪披風阿拉卡賢者披巾您會收到：\n\n"}
MultiLanguageQuestData['tw'][10875] = {title = "回報納茲格雷爾", objective = "到地獄火半島的索爾瑪找納茲格雷爾談話。", description = "<name>，在你突襲惡魔占卜器的時候，我向上級回報了你對抗魔獄獸人的英勇事蹟。我們在索爾瑪的傑出領袖，納茲格雷爾想跟你談話。我相信他心裡有一個困難的任務...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10876] = {title = "堡壘之根", objective = "殺死軍隊指揮官葛洛克斯，將部落的挑戰安置在他的屍體上，殺死卡加斯之手，然後將卡加斯之手的頭顱交給索爾瑪的納茲格雷爾。", description = "軍隊指揮官葛洛克斯正在訓練地獄火堡壘的破碎之手隊長，逼他們磨練戰技。你必須殺死他，<name>，因為他的死亡將帶給魔獄獸人沉重的打擊。\n\n然而，這不全然是你要做的事情。\n\n拿著這個旌旗。插在葛洛克斯的屍體上面。如果葛洛克斯的指揮官，卡加斯之手身上流著任何一滴正統的獸人血液的話就會回應你的挑戰!\n\n他的頭顱，卡加斯之手的頭顱，就是我要的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "暗影法師外套黑暗風暴外套雷霆外衣戰鬥大師的胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10877] = {title = "恐怖聖物", objective = "歐肯要你去東邊被遺棄的商隊取回恐怖聖物。任務完成後回去找歐肯。", description = "很久以前有一個商隊帶著任務前往奧齊頓的大墓穴中一個古老墳墓中取得恐怖聖物。他們都逃跑了，原因就是那個遺物。那個遺物是一個邪惡的東西，當有人碰觸它時就會召喚出魔物。那個商隊在東邊的某處被消滅了。\n\n這個邪惡的神器是擊敗受詛咒的泰利巴斯的關鍵，這個飛行在白骨荒野的生物的可怕計畫。假如你願意的話就請幫助我，但是你的生命甚至是你的靈魂都會很危險。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10878] = {title = "暗夜來臨前", objective = "難民商隊的麥克達要你殺死8個卡巴爭鬥者，4個卡巴織法者還有2個卡巴新教徒。", description = "自從我們的商隊被暗影議會卡巴異教徒攻擊以後，斥候就被派到撒塔斯城求救。守衛們認為我們現在暫時安全了，但是他們低估了那些瘋狂的人。\n\n就像我，並不想在半夜被某個卡巴新教徒劃破我的喉嚨。幫我們一個忙，在他們來攻擊我們之前把戰鬥帶到我們的敵人那邊。\n\n你會在南邊找到攻擊我們的人，就在奧齊頓北方的入口。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10879] = {title = "司凱堤斯的攻擊", objective = "阻止那些進攻者，然後跟『贖罪者』里拉克談話。", description = "司凱堤斯已經對我們發動了戰爭!你有足夠的力量幫忙防禦撒塔斯嗎?\n\n阻止那些攻擊者!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "純良羽毛項鍊純種羽毛頸飾您會收到：\n\n"}
MultiLanguageQuestData['tw'][10880] = {title = "卡巴的命令", objective = "到白骨荒野的難民商隊，把卡巴的命令帶給麥克達。", description = "這段訊息上有一個深色的徽印而且上面的語言看起來有點熟悉，看起來像是以密碼編寫的。\n\n也許難民商隊那邊有人會了解。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10881] = {title = "暗影之墓", objective = "去難民商隊西邊的暗影之墓，並且取得阿魯南的披氅、卡倫的裁決錘還有阿塔勒卷軸。任務完成後回去找難民商隊的麥克達。", description = "許多人相信引起大爆炸使得奧齊頓分裂的就是暗影議會。據說他們喚醒了裡面一個巨大的魔物。\n\n假如謠言屬實，那麼那個魔物一定是轉頭對付他們了。根據這些命令，暗影議會部分的成員正在逃離奧齊頓。他們在暗影之墓收藏了奧齊頓的強大神器。\n\n其中的三個神器是神聖而不可侵犯的，因為它們屬於三個法力強大的族王阿魯南、卡倫還有阿塔勒。我必須要求你去取得它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "家傳意志力徽記家傳勇氣徽記您會收到：\n\n"}
MultiLanguageQuestData['tw'][10882] = {title = "末日的预言者", objective = "进入风暴要塞的禁魔监狱，杀死预言者斯克瑞斯。完成任务后返回沙塔斯城的圣光广场，向阿达尔复命。", description = "<阿达尔发出的乐声中突然搀杂了几个“不悦的”重音。>\n\n凯尔萨斯王子的典狱官真是蹩脚，被关押在禁魔监狱的怪物已经挣脱了束缚。\n\n其中有一个名叫预言者斯克瑞斯的，这位上古之神的仆从妄图实现他主人那征服世界的狂想。\n\n你必须阻止他逃出禁魔监狱，<name>。进入风暴要塞的禁魔监狱，杀死预言者斯克瑞斯，阻止事态的进一步恶化！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "權勢薩塔垂飾撒塔斯力量頸飾阿達歐的恢復項鍊您會收到：\n\n"}
MultiLanguageQuestData['tw'][10883] = {title = "風暴之鑰", objective = "與撒塔斯城的阿達歐談談。", description = "你已證明你自己完成重大任務的能力，<name>。你發現毀滅密碼和凱爾薩斯的關連對我們的目標非常重要。萬一凱爾使用那些密碼，這個世界所剩不多的事物都可能會被瓦解。\n\n阿達歐確信凱爾必須被阻止，並且正在尋找願意經歷試煉的冒險者。證明他們的能力者將被授予那魯的眷顧。\n\n<卡德加點頭。>\n\n阿達歐正在等你...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10884] = {title = "那魯的試煉:寬容", objective = "撒塔斯城的阿達歐要你自地獄火堡壘的破碎大廳取回劊子手的廢棄之斧。\n\n此任務必須在英雄難度的地城裡完成。", description = "在你被那魯認可之前，你必須通過四次考驗。\n\n在地獄火堡壘的破碎大廳裡有三個你的族人。他們被殘酷的人，卡加斯‧刃拳抓住。他企圖處決他們以作為他男子氣概和力量的標誌。在這樣的一個暴行發生之前，你必須救出這些囚犯。作為行動的證據，為我帶來劊子手未使用的斧。它的斧刃上不能有一滴血!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10885] = {title = "那魯的試煉:力量", objective = "撒塔斯城的阿達歐要你去取回卡利斯瑞的三叉戟和莫爾墨的精華。\n\n此任務必須在英雄難度的地城裡完成。", description = "在你被那魯認可之前，你必須通過四次考驗。\n\n力量的試驗分成兩部分。你必須消滅盤牙蒸汽洞窟的領導人，督軍卡利斯瑞，並為我帶來他的三叉戟。殺死被稱為莫爾墨的異界生物，他在奧齊頓的暗影迷宮裡，並為我帶來他的精華。\n\n完成這事，你就通過了力量的試驗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10886] = {title = "那魯的試煉:堅毅", objective = "撒塔斯城的阿達歐要你去援救來自風暴要塞，亞克崔茲的米歐浩斯‧曼納斯頓。\n\n此任務必須在英雄難度的地城裡完成。", description = "在你被那魯認可之前，你必須通過四次考驗。\n\n在我們的旅行中，我們遇到了很多危險的生物。我們將其中某些生物監禁並且安置在現在稱為風暴要塞的亞克崔茲。\n\n但是，有一名囚犯，那是一名環境的受害者。一個在錯誤的時間，出現在錯誤的那魯船裡的偷渡者。\n\n去亞克崔茲冒險吧，救出這個地精，米歐浩斯‧曼納斯頓。確保他的生存。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10887] = {title = "逃出墓穴", objective = "幫助阿庫諾回到難民商隊。任務完成後跟麥克達交談。", description = "感謝你的幫忙，<name>。我本來以為我死定了。\n\n我們快點離開吧。不用多久那些教徒就會追上來了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "麥克達的禮物揭露寶珠阿庫諾之刃遠古德萊尼紋章盾您會收到：\n\n"}
MultiLanguageQuestData['tw'][10888] = {title = "那魯的試煉:瑪瑟里頓", objective = "撒塔斯城的阿達歐要你殺死瑪瑟里頓。", description = "在你被那魯認可之前，你必須通過四次考驗。\n\n只剩一個障礙了，凡人。召集一支軍隊並且前往地獄火堡壘深處的瑪瑟里頓巢穴。一路殺進密室的中心，並毀滅那邪惡的腐敗者!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鳳凰之火指環"}
MultiLanguageQuestData['tw'][10889] = {title = "回到撒塔斯城", objective = "到撒塔斯城內的陰鬱城，找『贖罪者』里拉克談話。", description = "你的行為雖然勇敢，但肯定會引起泰洛克的報復行為。\n\n趕快去撒塔斯城。傳話給里拉克!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10893] = {title = "長尾是關鍵", objective = "殺死龍骨隧道裡的巨龍教徒領導者，德拉卡‧長尾。", description = "黑翼巨龍教徒都集結在隧道裡，我們很難應付這樣的局面。坦白說，他們數量比我們多太多了。\n\n雖然我們能夠應付任何太過靠近的教徒，但要是他們認真的攻打過來，我們一定會被擊敗。\n\n目前的狀況下我們需要有人穿過隧道到另一端去，並且殺掉他們的領導人，德拉卡‧長尾。打算找點樂子嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10894] = {title = "龍骨看守者", objective = "將會見紙條交給劍刃山脈的龍骨隧道入口的看守者月影。", description = "嗯，我不確定我們應該怎麼做。我不適合當軍事行動的策劃人。\n\n看守者月影會知道怎麼做。他目前正前往我們在西邊的龍骨隧道的防禦工事，就在龍骨橋的尾端。我們有部隊在那邊以防那些教徒們想搞鬼。\n\n拜託你，請以最快的速度將信件送到他手中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10895] = {title = "薩斯葛爾必須被燒毀！", objective = "在每座薩斯葛爾的哨塔使用煙霧烽火，然後回到遠征隊哨塔找空軍指揮戴畢瑞。", description = "是時候從空中攻擊薩斯葛爾了！我們的獅鷲騎士已準備好突擊，<name>。但是他們需要某個人在地面引導他們開火。你準備好進行一項秘密任務了嗎？\n\n將這些煙霧烽火拿進去薩斯葛爾，血之谷堡壘的西方。他們有四座警衛塔：一座在他們北方的牆附近，一座在他們南方的牆附近，一座在他們的煉冶場，而另一座靠著他們的山麓。把信號標放置在每座塔下面，而我們將飛到那裡轟炸他們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "神聖羽毛外衣野性靈魂上衣金紋外套鍍金赤紅胸鎧噬骨狂怒者外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][10896] = {title = "被寄生的保衛者", objective = "拉庫提要你殺死25隻蝕木蟲，然後回到難民商隊那裡找他。蝕木蟲寄宿在腐爛的森林狂怒者和群聚的根鬚行者的軀體裡。", description = "這塊土地的樹木被奧齊頓釋放出來的能量給毀壞了。釋放出來的腐敗魔法能量將這塊土地摧殘成你目前四處都可以看到的荒野。倖存的樹木現在被討厭的蝕木蟲侵擾，這些蟲在他們的樹皮下爬行並且啃食他們的樹身。\n\n腐爛的森林盛怒者以及群聚的根鬚行者是這些蝕木蟲的宿主。你可以在森林東邊的邊緣地帶找到他們。消滅這些生物，然後殺死自它們樹身逃出的蝕木蟲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10898] = {title = "天翼", objective = "護送天翼然後回報給撒塔斯城的『贖罪者』里拉克。", description = "天翼在你身邊飛來飛去。\n\n你感覺他要你跟著他。您會收到：\n\n", progress = nil, completion = nil, rewards = "靜焰護腿救贖者胸甲飛天女巫帽您會收到：\n\n迷你鸚鵡"}
MultiLanguageQuestData['tw'][10900] = {title = "瓦許的印記", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10901] = {title = "卡德許的鬥棍", objective = "盤牙蓄湖中奴隸監獄的『異端』司卡利斯要你帶給他土靈徽記和熾烈徽記。", description = "把鬥棍所需要的元素徽記帶來給我!\n\n土靈徽記為弒龍者戈魯爾所持有。戈魯爾可在劍刃山脈中的巢穴裡面找到。\n\n第二個徽記是一個叫做夜禍的生物的燃燒之心。這隻神話般的野獸據說住在先知麥迪文的神聖大廳裡。\n\n動作快!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10903] = {title = "返回榮譽堡", objective = "與助手克拉圖談話，他在榮譽堡的旅店裡。", description = "<name>，當你在執行薩斯葛爾的任務時，我接獲我的指揮官，喬渥上校的消息。他在戈卡茲崗哨附近戰鬥時被惡魔的腐敗侵襲，而他的情況已經變得非常糟。\n\n你已經在對抗魔獄獸人上為我們贏得這樣大的斬獲。你在戰鬥中的力量毫無疑問...而你的精神是否一樣堅強?\n\n請返回榮譽堡與克拉圖談話，他在榮譽堡旅店的上層房間內。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10904] = {title = "獲得魔化彈藥", objective = "收集5個惡魔砲彈。", description = "我們必須關閉燃燒軍團進入死亡之門的通道，但是首先你必須破壞他們的兩扇星移門!\n\n問題是，我們現在根本無法對那些東西造成損傷，所以你必須使用他們自己的武器對抗他們。\n\n死亡的力量，死亡看守，死亡熔爐鐵匠和死亡熔爐技師攜帶著惡魔火砲的彈藥。\n\n一般來說，它不會影響他們任何人，但是如果你把彈藥帶來給我，我將為它們注入自然放縱的憤怒!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10908] = {title = "跟『贖罪者』里拉克談談", objective = "『覺醒者』奇瑞克要你去撒塔斯城的陰鬱城，找『贖罪者』里拉克談話。", description = "跟我談話的你看起來很驚訝。我不怪你。我的族人，阿拉卡本來就該被人所畏懼。\n\n假如你想知道更多的事情，你應該去跟撒塔斯城的『贖罪者』里拉克談話。他在陰鬱城的北部，跟司凱堤斯其他的流亡者在一起。\n\n最後，<name>，我們會再交談的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10909] = {title = "惡魔靈魂", objective = "榮譽堡的克拉圖要你在榮譽堡西南方的葛卡茲哨站使用隱士聖物，殺死聖物附近的破碎之手狂戰士，再殺死10個被釋放的惡魔靈魂來為喬渥上校復仇。", description = "喬渥上校在葛卡茲哨站附近的一次戰鬥中被詛咒了，那是一個破碎之手魔獄獸人常出沒的地方。我的主人，巴瑞達心急如焚地工作以治癒不幸的人，但是他需要幫助。上校的痛苦靈魂在尋找平靜，而他通向平靜的道路，我擔心是一條復仇的道路。\n\n把這個隱士聖物拿到葛卡茲哨站。把它放置在靠近破碎之手獸人的地上並且擊敗他們。這將釋放他們的邪惡靈魂 -- 你必須為喬渥靈魂的恢復殺死那些邪惡靈魂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10910] = {title = "死亡之門", objective = "到死亡之門使用德魯伊信號召喚永恆樹林德魯伊，然後找他談話。\n\n已提供物品：\n", description = "現在燃燒軍團有一個更大的威脅。南邊有一個被人稱為死亡之門的傳送門，它開啟另一個可怕的世界，燃燒軍團在那邊養殖他們致命的地獄獵犬。\n\n要去那裡，就離開永恆樹林往東邊斜坡上去。沿著往南的路走，通過刀刃峽谷，雷森平台，剃刀山脊和鱗翼沙洲。然後，走下斜坡進入維克哈爾看臺，再通過摩克納薩爾南邊的隧道進入死亡之門。\n\n當你到達的時候，使用這個德魯伊信號。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10911] = {title = "自由開火!", objective = "使用同化彈藥以取得死亡之門的惡魔火砲控制權。使用它們來摧毀南方星移門還有北方星移門。", description = "既然那些彈藥可以影響燃燒軍團，是時候讓你使用它了。\n\n他們有兩個星移門用來傳送還有加強他們的虛無恐獸。一個在北邊一個在南邊，但是兩個都在惡魔火砲的射程範圍內。\n\n使用同化彈藥以取得各個惡魔火砲的控制權並摧毀星移門。\n\n讓砲隊先展開攻擊，必要的話準備殺死它的防衛者讓火砲保留下來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10912] = {title = "魔犬之主", objective = "殺死『魔犬之主』貝爾蒙。", description = "『魔犬之主』貝爾蒙必須死!就是他主持的儀式使得死亡之門維持運作。\n\n死亡之門位在山谷的北方盡頭。你到了那邊就可以找到埃雷達爾。\n\n你將會需要幫忙，帶著這把魔杖。當你跟貝爾蒙戰鬥的時候使用它，然後我的幾位朋友就會出來協助你。\n\n擊敗了埃雷達爾之後回去找野蠻領主安德烈利安。\n\n另外，<name>，感謝你為了我們所做的努力。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "娜塔夏守護者之索娜塔夏灰燼項鍊娜塔夏秘法絲鏈娜塔夏馱運項圈娜塔夏頸飾您能選擇下列奬勵中的一個：\n\n娜塔夏戰爭項鍊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][10913] = {title = "不適當的葬禮", objective = "泰洛卡森林內白骨荒野中的薩塔營地的指揮官洛沃要你燒毀8個陣亡的奧奇奈戰士還有8個陣亡的薩塔復仇者。", description = "沒有任何事情可以阻止腐敗的蔓延嗎?我的士兵已經與奧奇奈持續戰鬥數天，而且不知道什麼時候才能終止這場戰爭。每起傷亡，無論是奧奇奈還是薩塔的陣亡者魂魄，均從戰場上被抓走 - 他們的靈魂升起並且被帶到未知的地方。\n\n我不允許這種事情發生!在戰場上一個適當的葬禮是不可能的，但是那些惡魔不能奪走他們的靈魂!帶著這支火炬前往戰場，從這裡直接向東走。燒掉你看見的每具屍體!我們不能獻給惡魔儀式更多無辜的靈魂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10914] = {title = "需要一位英雄", objective = "泰洛卡森林內白骨荒野中的薩塔營地的指揮官洛沃要你殺死12個奧奇奈新教徒還有5個奧奇奈末日預言者。", description = "這樣是不夠的。我們需要一位英雄。我們的部隊被奧奇奈日漸增加的數目給擊敗了。\n\n<指揮官洛沃看著你。>\n\n你願意當我們的英雄嗎?回到戰場上殺死他們的士兵。讓他們無暇分神好讓我的斥候潛入他們的後方，然後看他們在製作什麼東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10915] = {title = "墮落的主教", objective = "泰洛卡森林內白骨荒野中的薩塔營地的指揮官洛沃要你摧毀奧奇奈棺材的內容物。", description = "他們將偷來的靈魂奉獻給他們從奧奇奈地穴拖出來的一個棺材。我的斥候相信棺材的裡面包含了地穴的首位主教。他們想要復活這位古老的主教!\n\n你必須一路打進奧齊頓的西邊然後在他們奉獻足夠的靈魂之前阻止棺材裡面的東西。萬一你迷路，就跟隨其他的靈魂走。\n\n摧毀那個棺材裡面的東西!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "薩塔復仇者腿鎧薩塔的神射手手套伊萊克皮革肩甲亡語者的外套您會收到：\n\n"}
MultiLanguageQuestData['tw'][10916] = {title = "挖掘祈禱串珠", objective = "尋回德萊尼祈禱串珠然後交給榮譽堡的助手克拉圖。", description = "隱士巴瑞達計畫驅除喬渥上校體內的腐敗根源，因此他需要一個助手。我需要的助手一定要做好準備...\n\n我很羞愧地承認我的祈禱串珠遺失在榮譽堡的庭院裡了。我覺得是菲菲這隻狗偷了串珠並且埋了起來，但是我不知道在那裡。如果你與菲菲的主人，士官長崔西‧波特威歐談話，或許她會知道菲菲將它偷來的財寶藏在那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10917] = {title = "流亡者的困境", objective = "帶30根阿拉卡羽毛到撒塔斯的陰鬱城給威卡斯。", description = "身為一個流亡者，我身上被效忠於司凱堤斯城的阿拉卡標上了死亡的記號。為了生存我不能離開這些城牆，但那並不表示我不能給他們復仇的一擊。\n\n我有一小堆寶物願意分享，只要你幫我對付那些我想要成為的刺客。把泰洛卡迷霧裡不同居民的羽毛帶來給我做為他們死亡的證據。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n被丟棄的袋子"}
MultiLanguageQuestData['tw'][10918] = {title = "更多的羽毛", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n被丟棄的袋子"}
MultiLanguageQuestData['tw'][10919] = {title = "菲菲的狗餅乾", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10920] = {title = "為了垂死的同伴", objective = "復仇者赫藍要你殺死20隻懼牙寡婦然後回到幽網山脊的西邊找他。", description = "當那些懼牙寡婦攻擊我們的前哨站時，我們聽到那魯的聲音呼喚我們去戰鬥。我們在夜色中追捕那些生物。在黑暗中我們發現有些人死了，我們還可以聽到其他的人因為反抗那些捉住他們的人而發出的掙扎聲。\n\n到了早上我們來到這裡，發生了一場激烈的戰鬥，不過我們被打敗了。懼牙的毒液很快就會奪走我同伴的生命而我也撐不了多久。我希望在我死以前可以知道那些懼牙寡婦已經被打敗了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10921] = {title = "泰洛卡狼蛛", objective = "復仇者赫藍要你殺死泰洛卡狼蛛然後回到幽網山脊的西邊找他。", description = "你已經殺死許多懼牙寡婦但是他們還是會不斷的繁殖並且不久之後就會再度攻擊我們。幽網山脊是泰洛卡狼蛛的巢穴，她是這些可怕生物的母親。假如我們想要安全的話，她就必須死亡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "貴族肩鎧受祝福的璽戒報應之刃滿溢祝福魔典您會收到：\n\n"}
MultiLanguageQuestData['tw'][10922] = {title = "挖掘骨頭", objective = "護送里同還有他的工作人員然後在他們挖掘的時候保護他們。任務完成後回到薩塔營地找德拉弗懷茲。", description = "喂!你看起來像是可以照顧自己的人，<race>。我跟我的工作人員正在尋找一個可以保護我們到北邊挖掘場的保鏢。這份工作的薪水很好而且你只要確保沒有噁心的生物會殺死我或者我的工作人員就可以了。\n\n假如你成功的保護我們的人員無傷亡的回來，在那邊的德拉弗懷茲會付錢給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10923] = {title = "邪惡逼近", objective = "歐肯要你把恐怖聖物帶到苦痛山丘。一旦到了那裡，殺死奧奇奈亡語者和奧奇奈末日預言者，並收集20顆厄運頭顱。然後找到苦痛山丘召喚法陣並且使用恐怖聖物召喚並消滅受詛咒的泰利巴斯。任務完成時，回到歐肯那裡。", description = "如果你希望挑戰受詛咒的泰利巴斯，現在你必須在一個邪惡的死靈儀式裡使用恐怖聖物。到東北方去，在越過奧齊頓的苦痛山丘，一個死靈法師聚集的地方。\n\n那裡的奧奇奈亡語者和末日預言者帶著具有強大死靈魔力的厄運頭顱。如果你收集了足夠的頭顱，你就能使用它們的魔力配合恐怖聖物的力量強迫泰利巴斯面對你的挑戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "龍骨之劍龍骨護肩龍骨咒符您會收到：\n\n"}
MultiLanguageQuestData['tw'][10924] = {title = "血任務!", objective = "帶8罐扭曲追趕者之血給扭曲太空的沙布奧斯。", description = "這區域的扭曲追趕者鮮血是一種強大又稀有的施法材料。它是我店裡銷售最好的物品。\n\n平常我都帶著我的小鬼，塞皮跟我一起去收集。扭曲追趕者的血對你我來說都具有腐蝕性且很難安全的收集，但是卻難不倒塞皮。\n\n店裡的生意越來越忙，所以假如我派塞皮跟你去，你願意幫忙我收集鮮血嗎?塞皮的注意力不集中，所以你必須在殺死扭曲追趕者的時候靠近一點好讓塞皮完成他的工作。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10926] = {title = "回到薩塔營地", objective = "復仇者赫藍要你回到白骨荒野的薩塔營地，找斥候納夫靈談話。", description = "我們沒力氣回去了。那些懼牙的毒液效果太強了。你必須幫我們回報薩塔營地。斥候納夫靈會派一支救援隊來尋找我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10927] = {title = "殺光爬行者", objective = "殺死6隻洞穴爬行者。", description = "指揮官天影要清空這條通道以促進我們跟避難營的貿易。我不能離開我的哨站所以我只好把任務交到你的手裡。清空通道然後馬上回報指揮官天影!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10928] = {title = "殺光爬行者", objective = "殺死6隻洞穴爬行者。", description = "吐查克‧雙爪要清空這條通道以促進我們跟沼澤叛徒的交易。我不能離開我的哨站所以我把任務交到你的手上。清空這個通道然後馬上回報吐查克‧雙爪!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10929] = {title = "太鼓之音", objective = "白骨荒野的薩塔營地的德拉弗懷茲要你帶給他8個成熟骨質分解屍體。", description = "你願意怎樣為探險者協會做更多工作？這些白骨蟲完全激起我們的興趣。\n\n這裡有一面我的鼓，你可以在白骨荒野使用它。只要在這討厭的東西上敲擊，看看你會得到什麼回應。如果它是一條白骨蟲，殺死它並把屍體帶回給我們研究。我們將需要一批完好的屍體以得到一個有效的測試樣品。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10930] = {title = "巨大白骨蟲", objective = "白骨荒野的薩塔營地的德拉弗懷茲要你取得巨大的白骨蟲內臟。\n\n他同時也想要回他的太鼓。", description = "我是對的!你帶給我的這些屍體屬於白骨蟲幼蟲。你知道那表示什麼嗎?那表示在這附近有一隻大的!我認為如果我們能提供正確的食物，就能引誘它出來。這個嘛...需要大型的屍體誘餌!是的!\n\n我記得在這東邊白骨荒野的另一邊看見過裂蹄。到那去並殺掉一隻裂蹄。一旦它死了，就敲響鼓。希望會那隻大蟲會出來吃它。如果有，你就設法殺死它，並把它的內臟帶來給我!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "帝布毛的快速小刀崇敬之母迅捷小刀夏尼的迅捷小刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][10931] = {title = "回到埃索达", objective = "前往埃索达，与凯德莫斯谈一谈。你的老师凯德莫斯要你前往埃索达与他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", description = "你的老师凯德莫斯要你前往埃索达与他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10932] = {title = "回到埃索达", objective = "前往埃索达，与凯德莫斯谈一谈。你的老师凯德莫斯要你前往埃索达与他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", description = "你的老师凯德莫斯要你前往埃索达与他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10933] = {title = "回到银月城", objective = "前往银月城，与奥德兰谈一谈。你的老师奥德兰要你前往银月城跟他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", description = "你的老师奥德兰要你前往银月城跟他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10934] = {title = "回到银月城", objective = "前往银月城，与奥德兰谈一谈。你的老师奥德兰要你前往银月城跟他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", description = "你的老师奥德兰要你前往银月城跟他会面。似乎跟你的训练课程有关吧，具体什么我就不得而知了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10935] = {title = "喬渥上校的驅邪儀式", objective = "跟隱士巴瑞達談話。使用祈禱串珠幫助祭儀進行，然後等上校得救以後跟他談話。最後，回報助手克拉圖。", description = "<name>，現在該拯救喬渥上校了。他的情況惡化了，而且巴瑞達擔心假如我們不淨化他的腐化，那麼我們將會失去他。\n\n帶著你找到的串珠去跟隱士巴瑞達談話並且開始淨化的祭儀。別讓任何事情打擾了祭儀...假如一切順利，喬渥上校就會得救。當喬渥得救了以後跟他談話，然後跟我回報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10936] = {title = "托爾貝恩正在找你", objective = "助手克拉圖告知你軍隊指揮者達納斯‧托爾貝恩正在找你。到地獄火半島，榮譽堡裡的兵營跟他談話。", description = "我們在交談的時候，有一位信差在大廳等著。我想他等的累了或者他趁喬渥沒注意的時候跑走了。\n\n總而言之，軍隊指揮者達納斯正在找你。我建議你馬上去兵營裡頭見他!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10937] = {title = "殺死訓練員", objective = "軍隊指揮者達納斯‧托爾貝恩命令你盡快殺死訓練員蘇洛克。一旦殺了訓練員後就回到地獄火半島的榮譽堡向軍隊指揮者回報。", description = "我收到消息指出地獄火堡壘前外的破碎之手魔獄獸人正在組織一個全面的攻擊行動。毫無疑問的，他們對於你打敗他們一些氏族的這件事感到不太高興。\n\n前往地獄火堡壘，就在光榮之路的盡頭。你會發現那些魔獄獸人正忙著做戰前的準備，而你的出現將使他們大吃一驚。\n\n殺死那邊的指揮者。殺死訓練員蘇洛克!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "暗影法師外套黑暗風暴外套雷霆外衣戰鬥大師的胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][10938] = {title = "暗月祝福套卡", objective = "當暗月馬戲團來到鎮上的時候，把祝福套卡交給他們。", description = "你現在收集齊了整套的祝福套卡，跟前八張卡片有著同樣花色的第九張卡片神奇的出現。這張卡上刻著文字:「將這些卡片帶回暗月馬戲團並接受獎賞。」你聽說這個馬戲團的入口每個月會出現在莫高雷跟閃金鎮附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗月卡:聖戰"}
MultiLanguageQuestData['tw'][10939] = {title = "暗月風暴套卡", objective = "當暗月馬戲團來到鎮上的時候，把風暴套卡交給他們。", description = "你現在收集齊了整套的風暴套卡，跟前八張卡片有著同樣花色的第九張卡片神奇的出現。這張卡上刻著文字:「將這些卡片帶回暗月馬戲團並接受獎賞。」你聽說這個馬戲團的入口每個月會出現在莫高雷跟閃金鎮附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗月卡:狂怒"}
MultiLanguageQuestData['tw'][10940] = {title = "暗月狂怒套卡", objective = "當暗月馬戲團來到鎮上的時候，把狂怒套卡交給他們。", description = "你現在收集齊了整套的狂怒套卡，跟前八張卡片有著同樣花色的第九張卡片神奇的出現。這張卡上刻著文字:「將這些卡片帶回暗月馬戲團並接受獎賞。」你聽說這個馬戲團的入口每個月會出現在莫高雷跟閃金鎮附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗月卡:復仇"}
MultiLanguageQuestData['tw'][10941] = {title = "暗月失心套卡", objective = "當暗月馬戲團來到鎮上的時候，把失心套卡交給他們。", description = "你現在收集齊了整套的失心套卡，跟前八張卡片有著同樣花色的第九張卡片神奇的出現。這張卡上刻著文字:「將這些卡片帶回暗月馬戲團並接受獎賞。」你聽說這個馬戲團的入口每個月會出現在莫高雷跟閃金鎮附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗月卡:瘋狂"}
MultiLanguageQuestData['tw'][10942] = {title = "兒童週", objective = "使用血精靈孤兒哨呼喚你在兒童週領養的小孩。\n\n已提供物品：\n", description = "有一個特別幸運的小女孩將會很高興的當你的朋友，即使你們只有短時間的相處而已。\n\n拿著這個哨子。有了這個哨子你就可以呼喚你領養的小孩子。你只能在特定的時間內擁有這個哨子 - 一直到兒童週結束為止。\n\n拜託你了，<name>，呼喚你的孤兒出來吧。我知道她會非常高興的看見你並且跟著你四處遊玩!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10943] = {title = "兒童週", objective = "使用德萊尼孤兒哨呼喚你在兒童週領養的小孩。\n\n已提供物品：\n", description = "有一個特別幸運的小女孩將會很高興的當你的朋友，即使你們只有短時間的相處而已。\n\n拿著這個哨子。有了這個哨子你就可以呼喚你領養的小孩子。你只能在特定的時間內擁有這個哨子 - 一直到兒童週結束為止。\n\n拜託你了，<name>，呼喚你的孤兒出來吧。我知道她會非常高興的看見你並且跟著你四處遊玩!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10944] = {title = "保守的秘密", objective = "前往影月谷的典獄官監牢並且跟阿卡瑪交談。", description = "再次感謝你，<name>。我認得你。阿卡瑪將他轉而對付伊利丹的計畫託付給你因此我也信任你。\n\n納迦發現我反抗伊利丹的事實而且對我嚴刑拷問。我並沒有告訴他們任何事情 - 阿卡瑪教我如何透過冥想克服痛楚。\n\n伊利丹命令那些納迦把我送到他的手上，因為伊利丹本人可以看穿我的這副身軀並且直接窺視我心中最深處的秘密。\n\n我們必須警告阿卡瑪。我們的計畫處於危險之中!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10945] = {title = "胡秋和蘑菇族民", objective = "帶著你的孤兒瑟蘭德雅前往贊格沼澤的斯博格爾。當你到達而她卻不在的話記得要召喚她。然後跟胡秋談話。", description = "我有一位朋友叫做胡秋。她告訴我她因為要躲避一個邪惡的真菌巨人而逃到了孤兒院。\n\n我們相處的很愉快直到去年她的同胞前來將她帶回去為止。我記得她曾說她要搬到一個叫做斯博格爾的地方。\n\n我想去看看她順便拜訪她們的蘑菇村莊。孤兒監護員告訴我這座村莊位在贊格沼澤的西邊，就在孢子風之湖跟沼澤光之湖中間。\n\n我們可以一起去嗎？我們可以一起去嗎？拜託？！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10946] = {title = "灰舌偽裝", objective = "前往風暴要塞並且戴上灰舌風帽殺死歐爾。完成任務後回到影月谷找阿卡瑪。", description = "歐蘭的犧牲對我們的打擊很大。我真不該叫他犧牲自己的生命。但是該發生的已經發生了。\n\n如果我們想欺騙伊利丹，給他局勢安定的錯覺，我們必須聽從他的命令 - 至少現在必須這麼做。\n\n我有一支龐大的灰舌部族軍隊，但是 - 不屬於死亡誓言者 - 沒有人可以相信。\n\n你必須要完成伊利丹的命令。帶著這頂風帽;它蘊含著魔法的力量。任何看到你殺死凱爾的鳳凰---歐爾的人都會認為你是我的一名手下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10947] = {title = "古老的神器", objective = "前往塔納利斯的時光之穴並且進入海加爾山戰役。進入之後，擊敗瑞齊‧凜冬並且將時間定相骨匣交給影月谷的阿卡瑪。", description = "伊利丹的焦點已經轉向凱爾薩斯，這都要感謝你。是時候該我們行動了。\n\n預兆告訴我一個神器將會在我們的最後一戰中幫忙我們 - 一個被人稱為凜冬的巫妖所佩帶的骨匣。可惜的是自從他在海加爾山戰役被擊敗之後，骨匣的力量就消失了。\n\n然而，應該有方法可以取得這個神器。傳說中艾澤拉斯有一處由青銅龍守衛的地方...一處過去與現在的交會處。你將會在那裡找到我們要尋找的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10948] = {title = "囚禁的靈魂", objective = "前往撒塔斯城告訴阿達歐關於阿卡瑪的請求。", description = "你一定覺得很奇怪為什麼我要繞了一大圈隱瞞我真正的意圖。為什麼我不公開的支持那魯呢?\n\n我的真正本體-也就是我的靈魂-被伊利丹囚禁在黑暗神廟。伊利丹可以隨時殺死我...直到現在!這個骨匣將使我重新獲得靈魂的控制權。\n\n是時候了，<name>。我會率領瑪翼夫和我的死亡誓言者到伊利丹的門階。\n\n和阿達歐談談，告訴他我們的計畫。如果我們能團結一致就能衝破伊利丹的防線。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10949] = {title = "進入黑暗神廟", objective = "前往影月谷的黑暗神廟，在入口處與希瑞談話。", description = "<阿達歐在你面前製造了一個影像，顯示一個那魯站在黑暗神廟外面與德萊尼復仇者以及血精靈博學者戰鬥的景象。你馬上察覺到這就是阿卡瑪在等待的機會。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10950] = {title = "奥金顿的仪式广场", objective = "带上孤儿多尔南，前往位于奥金顿中心仪式广场的集合石。奥金顿就在泰罗卡森林内的白骨荒野的中心地带。如果你抵达时发现她不在身边，记得要先召唤她。", description = "有位路经孤儿院的牧师跟我们讲过奥金顿的故事，据说那地方对德莱尼一族至关重要，就在这附近哦。\n\n他说奥金顿曾经是德莱尼人的埋骨地，但是不久前发生了爆炸事件。\n\n我想去奥金顿的仪式广场看看。孤儿院监护员说那地方就在白骨荒野的中间，泰罗卡森林的南部。\n\n亲爱的<name><先生/小姐>，拜托你，带我去好吗？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10951] = {title = "參觀黑暗之門", objective = "帶著你的孤兒，瑟蘭德雅走上命運階梯，站在地獄火半島的黑暗之門前。當你到達而她卻不在的話記得要召喚她。", description = "我們怎麼可以看了這麼多有趣的地方卻不看黑暗之門呢？！\n\n大人總是告訴我們它的可怕故事和它有多危險，有很多惡魔之類的。\n\n<瑟蘭德雅轉動著她的眼睛。>\n\n但你來了，所以它也沒那麼糟，對吧？\n\n我想親眼看看它。你記得它在地獄火半島東邊的哪個地方吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10952] = {title = "参观黑暗之门", objective = "带上孤儿多尔南，登上命运阶梯，站在地狱火半岛的黑暗之门前。如果你抵达时发现她不在身边，记得要先召唤她。", description = "要是我们没别的地方可去，那就去黑暗之门吧！\n\n孤儿监护员们总是说那儿很危险，居住着很多恶魔什么的，还说只有象你这样的英雄才能跨越黑暗之门。\n\n<多尔南转动着眼珠。>\n\n但是有你保护我，情况应该不会太糟，是吗？\n\n我真得很想去亲眼看看。黑暗之门就在地狱火半岛东部边缘吧，你还记得确切的方位吗？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10953] = {title = "參觀元素王座", objective = "帶著你的孤兒，瑟蘭德雅前往納葛蘭的元素王座。當你到達而她卻不在的話記得要召喚她。然後跟元素師莎爾瓦克談話。", description = "你有聽過元素王座嗎？它位在納葛蘭，週遭有許多強大的元素生物。\n\n將來有一天，我要成為一位偉大的法師，或者是一位術士。我想要學習一些元素力量的知識！\n\n你覺得我們可以去那邊參觀嗎？\n\n<瑟蘭德雅眨著她古靈精怪的小眼睛看著你。>\n\n你要知道實地參觀對小朋友來說多麼的有教育性。它位在卡拉達爾的北方，就在天歌湖的另一邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10954] = {title = "埃瑞斯码头的希尔！", objective = "带上孤儿多尔南，前往位于纳格兰的埃瑞斯码头。如果你抵达时发现她不在身边，记得要先召唤她。然后与希尔谈一谈。", description = "我有点想念我的哥哥希尔了。他比我大几岁，所以监护员们让他去纳格兰给虚灵们当学徒了。\n\n要是能去看看他就好了。他一直很喜欢地质学一类的东西，想必他在那儿过得挺开心的。\n\n孤儿监护员跟我说他在纳格兰一处名叫埃瑞斯码头的地方受训。埃瑞斯码头就位于沃舒古山脉的西北方，沿着塔拉西边的道路一直走就能到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10956] = {title = "纳鲁之座", objective = "带上孤儿多尔南前往秘蓝岛的埃索达，将她带到纳鲁之座底部的沃洛斯面前。如果你到达时她不在你身边，记得召唤她。\n\n进入主城后你可以查看地图确定沃洛斯的位置。", description = "你知道纳鲁的故事吗？这些天使般的神灵一直以来都在无私地帮助德莱尼人。我曾在沙塔斯城附近见过他们。\n\n他们说有一位名叫沃洛斯的纳鲁去了你们的世界，就在埃索达城中。我想亲眼看看他。\n\n你能带我去吗？我敢打赌，要是我们利用达纳苏斯月神殿的传送门，一定很快就能到达那儿！要是你在埃索达中迷了路，我们可以随时查看你的地图。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10957] = {title = "灰舌的救贖", objective = "擊敗黑暗神廟中阿卡瑪的陰影來幫助阿卡瑪奪回他的靈魂。完成後回到先知卡奈那裡。", description = "當伊利丹獲得破碎者的擁戴時，阿卡瑪是我們之中最有智慧的一個人。他知道公開對抗背叛者會讓我們的種族滅絕。\n\n因此他在最高機密的情況下密謀策劃了這重要的一刻。失敗會造成大災難...不只是對阿卡瑪，不只是對破碎者，而是對整個外域。和伊利丹這麼親近的人沒有一個能對他造成這樣可怕的打擊。\n\n幫助阿卡瑪釋放他的靈魂，他就能讓你進入伊利丹的聖所。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10958] = {title = "尋找灰舌", objective = "在黑暗神廟裡找到阿卡瑪的死亡誓言者。", description = "<當你抬頭看著希瑞，你的精神變的集中，意志變的堅定。你在這裡的任務還沒完成;你必須回去黑暗神廟找到阿卡瑪的追隨者。>\n\n<阿卡瑪的成功與否影響很多事情。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10959] = {title = "背叛者之死", objective = "先知卡奈要你擊敗黑暗神廟裡的伊利丹。", description = "等伊利丹的副官被擊敗，阿卡瑪就能衝破伊利丹的聖所之門。只要阿卡瑪這麼做你就準備好帶著軍隊進入。\n\n我們仍然不清楚瑪翼夫發生什麼事，但是就算沒有她我們也要繼續前進。\n\n希望你的軍隊足以應付這個任務。伊利丹不會樂於見到阿卡瑪。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n受祝福的卡拉伯爾勳章"}
MultiLanguageQuestData['tw'][10962] = {title = "前往洞穴的時刻", objective = "帶著你的孤兒朵娜，站在時光之穴中間講臺上叫做薩拉多姆的那條龍面前。當你到達時如果她不在的話記得要召喚她。\n\n接著，從入口通道底附近的時光守望者軍需官，阿勒米那買一隻玩具龍給她。", description = "在孤兒院，曾經有位老牧師告訴過我們有關時光之穴的故事。他說時光之穴位於時間的中間，對於維持事物的正確性非常重要。\n\n我不懂其中的意義，不過他提到那裡有很多龍在幫忙拯救這個世界！我想要看看龍的樣子！\n\n你覺得我們去得了那裡嗎？他提到入口就在一個叫塔納利斯的大沙漠東緣。\n\n也許你能夠在我們抵達時買一個紀念品給我？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10963] = {title = "前往洞穴的時刻", objective = "帶著你的孤兒，瑟蘭德雅，站在時光之穴中間講臺上叫做薩拉多姆的那條龍面前。當你到達時如果她不在的話記得要召喚她。\n\n接著，從入口通道底附近的時光守望者軍需官，阿勒米那買一隻玩具龍給她。", description = "在孤兒院，曾經有位又老又臭的牧師告訴過我們有關時光之穴的故事。他說時光之穴位於時間的中間，對於維持事物的正確性非常重要。\n\n我不懂其中的意義，不過他提到那裡有很多龍在幫忙拯救這個世界！我想要看看龍的樣子！\n\n你覺得我們去得了那裡嗎？他提到入口就在一個叫塔納利斯的大沙漠東緣。\n\n你可以在我們抵達時買一個紀念品給我！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10966] = {title = "返回孤兒院", objective = "把德萊尼孤兒哨交回陰鬱城給孤兒監護員瑪西將你的被保護人帶回撒塔斯城的孤兒院。", description = "糟糕!我猜該是回到撒塔斯城的孤兒院的時候了。\n\n我曾經擁有一段很美好的時光。你是全世界最好的人了，<name>!你現在是我的大<哥哥/姐姐>!\n\n<朵娜的淚水開始盈滿眼睛。>\n\n我會很想念你的!等我長大，我要變得像你一樣!!!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n伊萊克訓練項圈艾格伯特的蛋瞌睡蟲韋利多腳寵物護理包摯愛的刻像\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][10967] = {title = "返回孤兒院", objective = "把血精靈孤兒哨交回陰鬱城給孤兒監護員瑪西將你的被保護人帶回撒塔斯城的孤兒院。", description = "糟糕!我猜該是回到撒塔斯城的孤兒院的時候了。\n\n我曾經擁有一段很美好的時光。你是全世界最好的人了，<name>!你現在是我的大<哥哥/姐姐>!\n\n<瑟蘭德雅的淚水開始盈滿眼睛。>\n\n我會很想念你的!等我長大，我要變得像你一樣!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n艾格伯特的蛋伊萊克訓練項圈瞌睡蟲韋利多腳寵物護理包摯愛的刻像\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][10968] = {title = "拜访预言者", objective = "带上孤儿多尔南，前往秘蓝岛埃索达的水晶大厅拜访预言者努波顿。如果你到那儿时她不在你身边，记得召唤出她来。\n\n记住，你在城里可以查看地图。", description = "我感觉得出，这孩子颇有与众不同之处。\n\n你应该带她去见埃索达的预言者努波顿。我想他一定盼着你们俩呢。\n\n努波顿大人就在水晶大厅的最顶层。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10969] = {title = "尋找阿密爾", objective = "去護國者哨站尋找指揮官阿密爾。", description = "看起來有一股外來的勢力對聯合團的商業活動虎視眈眈。在過去兩天內已經有5名聯合團商人失蹤了。我們有理由相信以太皇族罪嫌重大。假如你想協助我們的話就去護國者哨站尋找指揮官阿密爾吧。\n\n護國者哨站就在正東方的下一座島上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10970] = {title = "慈悲的任務", objective = "為虛空風暴內護國者哨站的指揮官阿密爾取得被搶救的以太皇族監獄鑰匙。", description = "我們在上一次進入以太皇族領地的偵察任務時搶救了這個監禁寶珠。要不是它發出暗淡的悲傷信號，我們原本可能不會發現它。\n\n我們認為我們其中一員可能被關在裡面不過我們沒有辦法打開這個寶珠而不去傷害到裡面的東西。\n\n我們對於以太皇族的所知就是他們其中任何一員 - 在任何時候 - 都持有能夠打開寶珠的鑰匙。取得一把鑰匙並帶回這裡好讓我們能夠揭開這個寶珠的秘密。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10971] = {title = "以太皇族的秘密", objective = "虛空風暴護國者哨站的指揮官阿密爾要你帶給他1個以太皇族囚犯身分標籤。", description = "<阿密爾拿出了一個標籤。>\n\n我在死去的先鋒遺體身上找到這個囚犯的身分標籤。我猜想他們以同樣的方式替所有的囚犯製作標籤。\n\n我想要收集這些標籤然後編列成冊以幫助我了解他們的司法體系。假如你日後找到更多的以太皇族監獄鑰匙，就可以前往南方的以太皇族軍事要塞打開以太皇族監獄，將所有你找到的身分標籤都交給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10972] = {title = "以太皇族囚犯身分編錄", objective = nil, description = "我需要更多的身分標籤，<name>。目前為止我發現這些標籤不只是拿來辨識囚犯的身分而已，它同時也記載著囚禁的場所!\n\n一旦我破解上面的編碼，就可以明確的知道所有盟友被囚禁的位置，並且以最小的衝突救出他們。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][10973] = {title = "千個世界", objective = "虛空風暴護國者哨站的指揮官阿密爾要你帶給他5把以太皇族監獄鑰匙。", description = "我已經破解他們的密碼了!每個標籤的密碼被分成好幾個部份。標籤的正面永遠寫著同一句話:「千個世界...」。我不確定這幾個字的涵義但是感覺上有誘人受騙的意思。\n\n標籤的背後才是重要的資料所在。第一段的記號記錄著地點，而第二段記號記錄著囚犯的種類。此外，看起來那些鑰匙可以組合成一種更特殊的鑰匙，上面記載著另一種囚犯的種類。現在我只需要更多的鑰匙...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10974] = {title = "貝許爾的靜止密室", objective = "使用以太皇族鑰匙片 - A打開在劍刃山脈貝許爾平臺的靜止密室A。\n\n將調查密室得到的證據交給貝許爾平臺的指揮官阿密爾的影像。", description = "以太皇族在劍刃山脈最北邊人稱貝許爾平臺的沙洲上有一塊領地。根據鑰匙碎片上的記載，他們在貝許爾有更大規模的監獄。我應該跟你提一下，以太皇族稱呼那些監獄為靜止密室。\n\n這個鑰匙碎片可以讓你進入其中一個特殊的靜止秘室叫做靜止密室A。帶著這個鑰匙碎片前去調查吧。\n\n調查完成以後我的幻影將會在貝許爾平臺等你，跟我交談。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n護國者藏寶箱"}
MultiLanguageQuestData['tw'][10975] = {title = "淨化貝許爾的密室", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n以太皇族靜止密室鑰匙"}
MultiLanguageQuestData['tw'][10976] = {title = "奈薩斯王印記", objective = "劍刃山脈貝許爾平臺的指揮官阿密爾的影像要你交給他1個奈薩斯王印記。", description = "我必須知道以太皇族在奧齊頓的法力墓地裡關著什麼樣的東西。\n\n在你與貝許爾的靜止密室野獸戰鬥的時候，你可能會看到一樣叫做奈薩斯王印記的東西。如果你找到這樣東西，馬上交給我!這是要製作通往法力墓地裡頭的靜止密室鑰匙所欠缺的最後一樣材料。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10977] = {title = "法力墓地的靜止密室", objective = "劍刃山脈貝許爾平臺的指揮官阿密爾的影像要你使用法力墓地靜止密室鑰匙打開奧齊頓的法力墓地靜止密室。\n\n這個任務只能在英雄難度中完成。", description = "你所找到的奈薩斯王印記使我可以打造一把通往法力墓地靜止密室的鑰匙。\n\n根據雕紋上面的紋路記載其中關著2名囚犯:一名位於前方的區域，另一名位於靠近奈薩斯王子薩法爾的地方。我即將給你的這把鑰匙可以打開位於前方的密室。\n\n我要你前往奧齊頓的法力墓地並且打開法力墓地的靜止密室。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10981] = {title = "奈薩斯王子薩法爾的私人密室", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n薩法爾的靜止密室鑰匙"}
