MultiLanguageQuestData['tw'][10983] = {title = "乾癟的莫格多克", objective = "到劍刃山脈血之環外面的高塔頂端找乾癟的莫格多克。", description = "莫格多克真聰明!他派葛羅克來城市，找幫助。血槌氏族需要幫助。\n\n莫格多克說找幾個強壯的小夥子來劍刃山脈找他。他站在血之環的塔頂。莫格多克真聰明!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10984] = {title = "與巨魔談話", objective = "到撒塔斯城和陰鬱城區的巨魔，葛羅克談話。", description = "<范魯如結晶般清晰的音調傳入你的腦海中。>\n\n陰鬱城有一個巨魔懇求來往旅客的協助。大家對他的困難視而不見。\n\n你覺得你可以幫上他的忙嗎?\n\n他的名字是葛羅克，他就坐在東南方的商人附近。\n\n感謝你，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10985] = {title = "替阿卡瑪製造混亂", objective = "在希瑞的手下製造混亂的時候護送阿卡瑪和瑪翼夫進入影月谷的黑暗神廟。", description = "<希瑞的身上閃爍著光芒，身邊的奧多爾與占卜者部隊等待希瑞下達命令。希瑞的部隊準備逼退伊利丹的部隊，替阿卡瑪製造一場騷動。那魯等待著你提出開戰的請求。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n卡拉伯爾勳章"}
MultiLanguageQuestData['tw'][10989] = {title = "乾癟的莫格多克", objective = "前往劍刃山脈的血之環找乾癟的莫格多克。他就站在丘特看守的塔頂上。", description = "乾癟的莫格多克在塔頂等你。他叫我找一個<race><class>就像你這樣。你去找他說重要的事情。\n\n去吧，但是不要告訴別人。這是秘密!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10995] = {title = "葛魯洛克的兩個龍頭骨", objective = "取得葛魯洛克的龍頭骨。", description = "詛咒之谷位在東邊飛龍之末的邊界處。戈魯爾之子，葛魯洛克就在那邊策劃他的愚蠢計畫。\n\n我聽說他的一樣物品被人用巧妙的手法給偷走了。是你做的嗎?可惜他沒有在過程中喪失性命。\n\n如果我們想重獲自由，我要你搶走他最重要的資產，那就是他父親屠殺黑龍軍團的龍頭骨。你要取得龍頭骨的唯一方法就是殺死他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10996] = {title = "瑪格歐克的寶箱", objective = "取得瑪格歐克的寶箱。", description = "瑪格歐克在剃刀山脊的山坡上以及東南邊巡邏。他的父親指派他為東邊山區的看守者，而他則享受著殘虐當地任何看不順眼的生物。\n\n為了我的部族生存權，身為戈魯爾之子的他必須被消滅。這就要靠你幫忙了。\n\n瑪格歐克總是隨身攜帶一個寶箱。將他的寶箱帶來給我，證明你已經殺死他。你可以拿走寶箱裡頭的任何東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10997] = {title = "就連古羅也有軍旗", objective = "取得史拉格的軍旗。", description = "你聽說過撒塔斯城嗎，<class>?它的西北邊上方有個地方叫做阻礙之丘，一個你只能藉由飛行坐騎才能到達的地方。\n\n其中一位戈魯爾之子 - 史拉格，離鄉背井到那邊並且控制當地的戈杜尼巨魔。即使距離如此遙遠，我們也不能讓他坐大，免得當他的兄弟們都被殺死之後會回來復仇。\n\n<name>，你必須到那邊並且取得他的軍旗，證明他已經被擊潰了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10998] = {title = "搶奪魔典", objective = "取得梵戈的邪惡魔典。", description = "還有一個古羅要殺，那就是史庫洛克‧靈魂研磨者。他的藏身處非常隱密，但是有一個辦法可以引誘他現身。\n\n一個叫做邪惡的梵戈的巨魔術士曾訓練過他，你必須取得梵戈的魔典!\n\n只有站在火焰之環內才能召喚梵戈。到東北邊的山區，靠近破碎荒野的附近尋找梵戈之環。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][10999] = {title = "一下一个", objective = "带给我8颗穴居人的石牙。", description = "带给我8颗穴居人的石牙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11000] = {title = "深入靈魂研磨者獸穴", objective = "取得史庫洛克的靈魂。", description = "這本魔典是殺死史庫洛克的關鍵。\n\n在靈魂研磨者獸穴大聲的閱讀這本魔典以啟動儀式。接著一個叫做靈魂研磨者的東西會伴隨著許多史庫洛克的靈魂受害者出現，這些靈魂會試著破壞靈魂研磨者。你必須阻止這些靈魂這麼做，直到史庫洛克被迫在這個世界上現身為止。\n\n往北穿過匕爪峽谷，到達血之環的另一邊。\n\n獸穴的位置就在你到達戈魯爾之巢之前的右手邊。\n\n將史庫洛克的靈魂帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11002] = {title = "瑪瑟里頓陣亡", objective = "將瑪瑟里頓之首交給地獄火半島榮譽堡的軍隊指揮官達納斯‧托爾貝恩。", description = "伊利丹‧怒風的魔獄獸人軍隊來源已經消失了。生產殘忍戰爭工具的工廠也停止運作了，至少現在是如此。一切只剩下幾個小飾品以及這個割下來的頭顱 - 一個適合聯盟英雄的戰利品。\n\n將瑪瑟里頓之首交給榮譽堡的達納斯‧托爾貝恩。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "那魯光明護衛指環頑強之戒赤紅烈怒指環您能選擇下列奬勵中的一個：\n\n阿達歐的防禦徽記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11003] = {title = "瑪瑟里頓陣亡", objective = "將瑪瑟里頓之首交給地獄火半島索爾瑪的納茲格雷爾。", description = "伊利丹‧怒風的魔獄獸人軍隊來源已經消失了。生產殘忍戰爭工具的工廠也停止運作了，至少現在是如此。一切只剩下幾個小飾品以及這個割下來的頭顱 - 一個適合部落英雄的戰利品。\n\n將瑪瑟里頓之首交給索爾瑪的納茲格雷爾。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "那魯光明護衛指環頑強之戒赤紅烈怒指環您能選擇下列奬勵中的一個：\n\n阿達歐的防禦徽記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11004] = {title = "暗影世界", objective = "瑟弗林要你前往司凱堤斯從當地的阿拉卡身上取回6個暗影之塵。", description = "天空指揮官艾德瑞斯在一次對司凱堤斯的侵略行動中受到重傷。從此之後他的意識一直徘徊在清醒與昏迷之間。\n\n我擔心他已經精神錯亂。他在短暫清醒時要求我準備一種由阿拉卡身上攜帶的暗影之塵所製作的藥劑。他似乎相信這種藥劑能使他看見阿拉卡真正的領導者們所居住的「暗影世界」。\n\n我一點也不相信這種胡言亂語，但是我怕不做出這罐藥劑的話他不會善罷干休。你可以幫我的忙嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗影藥劑"}
MultiLanguageQuestData['tw'][11005] = {title = "魔爪祭司的秘密", objective = "從瑟弗林那裡取得暗影藥劑，用它找到並殺死司凱堤斯的魔爪祭司艾夏歐，魔爪祭司史奇吉克和魔爪祭司札列克。完成這個任務後回去找天空指揮官艾德瑞斯。", description = "感謝你還聽我瘋狂的豪言壯語。一直以來我們都想要摧毀司凱堤斯的指揮系統;我們已經探聽到他們有三個叫魔爪祭司的聖職人員，但是我們從未親眼見過。現在我們知道其中的原因。\n\n去跟瑟弗林交談以取得更多他發現的藥劑。使用藥劑找到並殺死那三個魔爪祭司:艾夏歐、史奇吉克以及札列克。據說他們住在迷霧亞拉芮克，靠近黑風湖的東邊海岸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11006] = {title = "更多暗影之塵", objective = "看來指揮官並不是胡言亂語。交給我更多的暗影之塵，我就給你另一份藥劑。", description = nil, progress = "看來指揮官並不是胡言亂語。交給我更多的暗影之塵，我就給你另一份藥劑。", completion = "繼續把暗影之塵交給我。你要多少藥劑我都可以給你。\n\n這是指揮官的命令。", rewards = "您會收到：\n\n暗影藥劑"}
MultiLanguageQuestData['tw'][11007] = {title = "凱爾薩斯和綠焰光球", objective = "將綠焰光球交給撒塔斯城的阿達歐。", description = "你身邊的空氣發出了嗡嗡聲 - 一種溫和的嗡嗡聲。那魯已經知道你的勝利。也許它們就是你被迫從凱爾薩斯‧逐日者還在抽動的遺體上撿起這個球體的原因。它到底隱藏了什麼秘密？\n\n也許撒塔斯城的阿達歐會知道。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "太陽王的咒符泰隆尼卡斯的暴行墜飾桑古納爾領主的頸鏈您能選擇下列奬勵中的一個：\n\n晦暗者之握\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11008] = {title = "向司凱堤斯開火", objective = "在司凱堤斯住所的屋頂尋找巨大的卡里瑞蛋，並且對其使用禦天者爆破彈藥。完成之後回報天空士官多林。", description = "你認為你夠資格成為禦天者的一員嗎?讓我們看看你在空中的能耐吧。阿拉卡正在培植一批數量龐大的變種攻擊寵物，用來攻擊我們的斥候。我要你拿著這些爆破彈炸毀阿拉卡住所屋頂的孵卵所。盡量避開守衛那些卵的巨大的卡里瑞，要不然在你還沒發現是什麼東西攻擊你之前，你已經從坐騎上被擊落了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11009] = {title = "巨魔的天堂", objective = "乾癟的莫格多克要你去劍刃山脈的歐格利拉與裘阿洛交談。", description = "既然你已經解放了我們的奴役生涯，我們可以開始重新統合整個部族。這可能要花點時間;部族之間的舊仇很難化解。\n\n但是現在有一件更迫切的事情，你必須前往位於西方上空的歐格利拉。你必須保護歐格利拉還有我們不受上方的軍隊威脅，就像之前古羅為了保護我們而對抗以太族、惡魔還有最可怕的黑龍軍團一樣。\n\n當你到達巨魔的天堂時，請教裘阿洛該如何做最好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11010] = {title = "轟炸任務", objective = "使用禦天者炸彈摧毀15個惡魔砲彈堆。", description = "你有飛行坐騎...那又怎樣!你以為你有足夠的能力駕馭它嗎?\n\n北邊的煉冶場:憤怒，還有南邊的煉冶場:驚駭都是我的眼中釘，也對歐格利拉的和平造成威脅。對禦天者發射的滿天惡魔火砲使得我們無法前往他們的煉冶場進行破壞行動。\n\n你想證明你的能力嗎?拿著這些炸彈然後去炸毀他們的砲彈堆吧。小心別被他們把你從坐騎上給射下來了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11012] = {title = "虛空之翼血誓", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11013] = {title = "為伊利達瑞效命", objective = "前往虛空之翼岩架將伊利達瑞勤務報告送給龍喉營地的霸主莫格。", description = "虛空之翼岩架...虛空之翼曾經的庇護所現在成了龍喉的家園。雖然獸人控制了我們的領土，但是我們的魔法仍然很強大。強大到足以掩飾你真實的身分讓你滲入龍喉的軍隊裡。\n\n我為你準備了這封信交給他們的領導者，霸主莫格。直接進入我們敵人的咽喉尋找龍喉營地，開始你身為伊利丹‧怒風的魔獄獸人新生活。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11014] = {title = "和監工談談", objective = "和龍喉營地的監工瓦庫歐‧龍息談談。", description = "<莫格揉碎勤務信然後將它扔到一邊。>\n\n好了蠻兵，先做要事。如果你想加入我親愛的龍喉軍隊，你就要工作。所有人都在岩架這裡忙著。去找個工作來做，不要搞砸了，我會看看晚一點是否有更有趣的事可以給你做。\n\n去和監工瓦庫歐‧龍息談談。他就在小鎮中央。他會評估你的技能並指派他覺得適合的工作給你。\n\n現在離開我的視線!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11015] = {title = "虛空之翼水晶", objective = "影月谷，龍喉營地的監工瓦庫歐‧龍息要你幫他帶來30個虛空之翼水晶。", description = "什麼都不擅長?沒關係。就連像你這樣的呆頭鵝在這裡都有用處。去岩架那裡找到生物並殺了他們。有時候他們身上會有虛空水晶。收集那些水晶帶來給我，我就會當做你已經完成今天的工作令了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11016] = {title = "虛空礦坑鐮奪怪皮革", objective = "影月谷，龍喉營地的監工瓦庫歐‧龍息要你幫他帶來35塊虛空礦坑鐮奪怪皮革。", description = "一個鐮奪怪是嗎?你會在這裡找到一大堆皮革!你要在水晶結構附近尋找鐮奪怪。擊倒他們並剝下他們的皮。有時候他們會有值得收藏的皮革。把它們帶來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11017] = {title = "虛空之塵花粉", objective = "影月谷，龍喉營地的監工瓦庫歐‧龍息要你幫他帶來40份虛空之塵花粉。", description = "一個採花者?!真好笑...不幸地，我們的法師和薩滿需要你的幫忙。生長在這個岩架的虛空之塵灌木擁有一種特別的花粉，對他們的魔法買賣非常有用。把那個東西帶來給我，我就當做你的工作令已經完成了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11018] = {title = "虛空聚晶礦石", objective = "影月谷，龍喉營地的監工瓦庫歐‧龍息要你幫他帶來40個虛空聚晶礦石。", description = "一個採礦者!\n\n<瓦庫歐敬禮。>\n\n一個我們自己的獸人!這就是瓦庫歐如何開始的 - 採礦!沒有什麼比在礦坑裡搞的一身髒更棒的了，對吧?\n\n現在快去那裡找到那些虛空聚晶礦脈。把它們之中值錢的礦石全挖出來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11019] = {title = "你在裡面的朋友", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11020] = {title = "慢速死亡", objective = "影月谷，龍喉營地的商人亞吉歐要你使用亞吉歐的羊肉配上惡魔腺體來毒害12個龍喉苦工營地。", description = "龍喉幾乎在每個水晶結構旁都部署了苦工。公然屠殺他們會為你帶來太多不必要的麻煩，不過我們有一個方法可以削減他們的數量又不會讓莫格起疑。\n\n進入影月谷的荒野殺死被污染的野生動物。拿走他們身上邪惡的惡魔腺體。用那些惡魔腺體配上我在苦工附近給你的羊肉。他們吃一口就會立刻像死了一樣痛苦!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11021] = {title = "艾夏歐的年鑑", objective = "將艾夏歐的年鑑交給司凱堤斯北邊的天空指揮官艾德瑞斯。", description = "這本神秘的書籍是在魔爪祭司艾夏歐的屍體上找到的。書中包含了神秘的文字以及一些神聖生物的圖樣，遠超出你的理解能力。\n\n裡頭的文字是一種你不了解的語言;很像一種古老的阿拉卡書寫體。也許你應該將這本書交給天空指揮官艾德瑞斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11022] = {title = "與莫格多克談話", objective = "跟乾癟的莫格多克談話。他站在劍刃山脈的血之環東面塔頂。", description = "<國王/皇后><name>!在你離開這裡前往歐格利拉之前跟乾癟的莫格多克談談!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11023] = {title = "再度轟炸!", objective = "使用禦天者炸彈摧毀15個惡魔砲彈堆。", description = "那些高射火砲仍然對我們造成威脅，<name>。\n\n你可別誤會我的意思，我認為你上次執行任務的表現非常出色。但事實上，那些該死的惡魔們補充砲彈的速度似乎比我們摧毀他們砲彈的速度還快。這同時表示我們的士兵很難通過該區域，更別提那些惡魔們對歐格利拉所造成的風險。\n\n你意下如何?想再次轟炸他們嗎?", progress = "轟炸任務進行的如何呢?", completion = "了不起的工作，&lt;name&gt;!我本來想叫你飛上空中再次轟炸他們，但是這裡的規定是要確定所有的飛行員可以獲得充分的休息。抱歉，規則不是我定的，但是我確定你一定得這樣做\n\n我們明天再見，好嗎?", rewards = "您會收到：\n\n頂尖裂片"}
MultiLanguageQuestData['tw'][11024] = {title = "陰鬱城的盟友", objective = "將艾夏歐的年鑑帶到撒塔斯城內交給陰鬱城的『贖罪者』里拉克。", description = "陰鬱城有一個阿拉卡叫做里拉克...他是值得信賴的人。把這本書...交給他。\n\n<艾德瑞斯把書交給你的時候失去了意識。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11025] = {title = "頂尖水晶", objective = "裘阿洛要你收集5塊頂尖裂片，然後回到劍刃山脈上方的歐格利拉交給他。", description = "經過適當的事前準備，那些山區中的水晶就能展現出它的奇異能量，就好像我們在歐格利拉發現它有使人思緒清晰的能力。\n\n山上的生物都垂涎著那些水晶裂片，並且將其裂片使用於他們私人的用途之上。那些水晶的價值甚至還引起了一些商機。\n\n想協助我們的話，你必須先學習了解頂尖裂片。幫我找一些裂片回來。除了這裡的生物會攜帶頂尖裂片之外，有時候你也可以在鐮奪怪挖掘水晶的地方發現裂片。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11026] = {title = "驅逐惡魔", objective = "使用驅逐水晶來放逐劍刃山脈上煉冶場:憤怒與煉冶場:驚駭中的惡魔。", description = "朋友，你到達的時間真是太完美了!我們真的需要幫助。你會得到一個非常稀有的物品作為回報，這樣你我兩方都能得到好處。\n\n我們已經不再是凶暴的巨魔了，不過附近的惡魔們威脅要侵擾我們和禦天者。對抗惡魔的問題是，他們一旦被殺死，就會以一個新的軀體重新回來!\n\n不過，如果你使用這個水晶來召喚一個驅逐傳送門，當他們在傳送門附近死亡時，他們的精華就會被抽走，並且放逐回他們的老家!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11028] = {title = "末日的倒數階段", objective = "到泰洛卡森林的黑風平臺，把泰洛克回歸世界的消息告知天空指揮官艾德瑞斯。", description = "這本年鑑預言了泰洛克將會重臨大地，他是阿拉卡歷史中最強大也最殘暴的司凱堤斯之王。\n\n我一直以為這不過是個傳說罷了，<name>。但是魔爪祭司重現的跡象以及你拿來的這本書證明了這不只是傳說而已。\n\n日復一日，泰洛克的力量越來越接近完全恢復的階段。你唯一的機會就是提早將他帶到我們的世界。回到司凱堤斯和艾德瑞斯談談這件事。希望他有智慧做出正確的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11029] = {title = "殘破的偽裝", objective = "使用殘破的阿拉卡偽裝從撒哈克那裡取得敵人之血再回到海茲克那裡。", description = "打開包裹，<name>。這是一個偽裝。看起來沒什麼說服力對吧?\n\n我為以太族走私者製作它們以搜尋稀有的書本。有一個阿拉卡作家住在司凱堤斯的中心島嶼，泰洛克之墓;他的名字叫撒哈克。他既老又幾近全盲。\n\n利用這個偽裝來和他交談並取得那本叫敵人之血的書。小心點，<name>。這個偽裝騙不了其他的阿拉卡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11030] = {title = "我們的兒子想當禦天者巡邏員", objective = "取得野獸的不穩定精煉藥劑。", description = "<class>，我們有個問題 - 我們有很多兒子。自從禦天者搬到附近，所有的兒子都在討論要加入他們的軍隊。\n\n身為一個驕傲的父親，我們要他們在申請的時候擁有所有的優勢。所以，可以請你到北邊或南邊的煉冶場，在惡魔水晶熔爐取得魔法藥水給我們的兒子嗎?你絕對會看到它們的綠色煙霧。\n\n我們認為它們價值十個頂尖裂片。我們會給你裂片，但我們現在手上沒有。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11032] = {title = "远离保卫者之路", objective = nil, description = nil, progress = nil, completion = nil, rewards = "刺客大師之紫羅蘭徽記大法師之紫羅蘭徽記大治癒者之紫羅蘭徽記"}
MultiLanguageQuestData['tw'][11035] = {title = "不太友善的航線...", objective = "影月谷裡龍喉營地的商人亞吉歐要你取得10個虛空之翼聖物。", description = "這個島的東北方邊界處有一個碼頭，用來當作虛空之翼水晶以及聖物的轉運站。龍喉輸送者負責運送貨物往返龍喉堡壘以及碼頭，而龍喉卓越者則負責地面上的警戒工作，監視任何可能的攻擊者。\n\n所以這使你可以攻擊一個地方:龍喉航線。\n\n飛到龍喉航線的破碎小島上伏擊那些輸送者吧。取回我們被偷走的聖物!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11036] = {title = "絕無僅有的產品!", objective = "到虛空風暴的52區，把罐頭水果交給火箭主管夫斯拉吉。", description = "我先承認我不太清楚這個訂單是要用來幹嘛的，但火箭主管夫斯拉吉的指示非常明確 - 只要品質最好的水果，製成足夠長期航行的罐頭食品並密封它們不受自然腐壞的影響。\n\n還有其他的說明，這個要無重力那個要低壓力。我不會假裝我了解，但價錢不錯，所以他會得到他要的超級食品。把這個木箱帶到52區給他。越過了虛空風暴後，順著路走直到你看見城鎮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11037] = {title = "奇怪的景象", objective = "跟52區的火箭主管夫斯拉吉談話。", description = "我預見了一個非比尋常的景象，<name>，而且我不完全知道那是怎麼辦到的。我看見一枝箭，一枝巨大的箭衝向天際，背後拖曳著一道火焰燃燒的痕跡。這種事情對一個技術高超的法師來說算不上什麼，但是我的預感告訴我這個巨大的箭矢並不屬於魔法的產物。\n\n這個東西將不是艾澤拉斯的居民可以達到的成就。你必須找到製造這個東西的人，<name>。協助他們，否則他們的工作可能最後還是會失敗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11038] = {title = "協助主教歐瑞利斯", objective = "跟52區的主教歐瑞利斯談話。", description = "不久以前，高階女祭司伊莎納派出一個由隱士組成的小隊前往虛空風暴，這個小隊由主教歐瑞利斯所帶領。他們的任務目標是調查凱爾薩斯和他的手下所進行的活動，但是我們還沒接獲任何的消息。\n\n我擔心以我們在當地的陣容可能不足以完成這個任務。我相信主教非常需要你在知識以及經驗上的幫助。你願意前往52區並且協助他嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11039] = {title = "向間諜大師薩洛迪恩報到", objective = "向52區的間諜大師薩洛迪恩報到。", description = "許多年前，沃藍索派遣一支小隊到虛空風暴調查凱爾薩斯在當地從事的活動。我們的領導人對間諜大師薩洛迪恩還有他的夥伴很有信心，並且決定允許薩洛迪恩的增援請求。\n\n薩洛迪恩的報告很簡短，但是清楚的指出他目前處理的事情關係重大。前往52區向他報到，並且儘可能的協助他，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11040] = {title = "火箭主管的零件", objective = "到虛空風暴的52區，把波西的備用零件帶給火箭主管夫斯拉吉。", description = "我和哥布林合作的次數用一隻手就數的出來。我們和他們比較像在競爭，但當我接到火箭主管夫斯拉吉的請求，我實在沒辦法拒絕他。\n\n這個木箱裝滿了我在這裡用不到的零件，但那個火箭主管或許可以用在他的工程上。如果你正要去52區的話可以幫忙運送它們嗎？\n\n誰知道，或許一些精細的地精零件可以讓他的創作免於爆炸！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11041] = {title = "未完成的工作...", objective = "殺死10個礦坑鐮奪怪和『獸穴之母』芭拉什。成功後回到龍喉營地找霸主莫格。", description = "以我們偉大主人的名義...為了伊利丹的榮耀!\n\n以霸主莫格的命令，我們一定要保護虛空之翼岩架的高原。由於所有虛空之翼龍都被抓或被迫離開土地，岩石鐮奪怪到處肆虐並威脅水晶收成運作。\n\n把他們都殺光，還有他們的獸穴之后和她的夥伴，亞博爾。\n\n這是莫格的命令!\n\n<看來這個獸人奪取高原失敗。是時候證明你的價值給莫格看了!>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "馴龍者手套卓越者之靴龍喉占兆師繫腰破天者披肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][11042] = {title = "令人困惑的幻象", objective = "跟52區的火箭主管夫斯拉吉談話。", description = "有一股幻象一直困擾著我，<name>。我看見一股股濃煙飄向天際，伴隨濃煙而至的是一股噴射的火焰，以飛快的速度移動著。這並不是自然界的現象或者邪惡的產物，我只知道這麼多。\n\n以我的學識並不足以了解這是什麼東西，只能判斷它是由許多人所製造出來的產物。然而少了其他人的幫忙，這個東西也許永遠沒有完成的一天。\n\n前往虛空風暴吧，<class>。找到製造這個東西的人並且提供協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11043] = {title = "更好的獅鷲獸", objective = "到影月谷的蠻錘要塞找布朗恩‧焰鬚談話。", description = "我聽說那些蠻錘矮人在影月谷的南邊要塞有一座獅鷲獸棲息處。假如你順路到那邊的話，可以幫我傳話給他們嗎？我有一些想法可以改良他們的獅鷲獸！\n\n明明可以在獅鷲獸身上裝飛行儀表板、照後鏡還有火箭，為什麼他們不武裝獅鷲獸呢？想想看裝了之後獅鷲獸可以飛的多快！我稱它為渦輪獅鷲獸8000型！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11044] = {title = "夢境中的災難", objective = "跟蠻錘要塞的空軍指揮官奴艾恩談話。", description = "我在睡夢中時常會夢見一段災難降臨的畫面 - 天上降下綠色的火焰，燒在一座堅固堡壘的英勇防禦士兵身上。這個夢境已經打擾了我好幾個禮拜的睡眠，但是一直到最近我才了解它的意義。\n\n就在遙遠的東邊，影月谷裡的蠻錘矮人們遭受燃燒軍團還有許多其他敵人的持續猛烈攻擊。他們英勇的奮戰著，但是在失去外援的情況下，他們的敵人終將獲得勝利。加入他們吧，<name>。幫助他們擊敗敵人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11045] = {title = "『執法官』索羅斯", objective = "和蠻錘要塞的『執法官』索羅斯談談。", description = "影月谷的歷史既冗長又複雜。很少人願意鑽研它，那裡發生過難以言喻的殘暴，人們害怕在其中呼吸到新的生命。\n\n不過，不是所有人都那麼膽小。『執法官』索羅斯就在影月過去的鬼魂中尋找真相。這是一項龐大的事業，他會很歡迎有人幫忙，我確定。\n\n如果你要去那裡，就到蠻錘要塞找索羅斯，在峽谷南邊地區的中心部分。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11046] = {title = "總藥劑師希爾達嘉", objective = "跟影月村的總藥劑師希爾達嘉談話。", description = "影月谷的歷史既冗長又複雜。很少人願意鑽研它，那裡發生過難以言喻的殘暴，人們害怕在其中呼吸到新的生命。\n\n不過，不是所有人都那麼膽小。總藥劑師希爾達嘉就在影月過去的鬼魂中研究。這是一項龐大的事業，她會很歡迎有人幫忙，我確定。\n\n如果你要去那裡，就到影月村找亥達嘎爾特，在峽谷的西北區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11047] = {title = "學徒的請求", objective = "到影月谷的影月村找達瑪‧蠻鬃談話。", description = "身為蠍尾獅管理員的學徒，我的其中一項工作就是當牠們沒有執行飛行任務時要照顧牠們。問題是我們這邊的雙足飛龍數量太少了，牠們根本沒有休息的時間。\n\n假如我們不能補充雙足飛龍的數量的話，我怕牠們會操勞致死。影月谷西邊的影月村有一個大型的雙足飛龍獸欄。達瑪‧蠻鬃負責照顧和訓練那裡的雙足飛龍。\n\n你可以幫我們去跟她講幾句好話，同時讓她了解我們的情況嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11048] = {title = "卡洛克汗的報告", objective = "跟影月村的血衛士高莫克談話。", description = "本來我接獲的命令是要留在卡拉達爾一段時間，然後繼續前進向影月村的血衛士高莫克回報。在這裡的這段時間我覺得卡拉達爾需要部落更長遠的幫助。\n\n我知道血衛士高莫克需要集結所有人員的每一份力量，但是我想他能諒解我在這的任務使命尚未達成。前往影月村，在影月谷的西北方，告訴血衛士高莫克我將會有所擔擱。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11049] = {title = "虛空之翼獵蛋行動", objective = "影月谷，龍喉營地的商人亞吉歐要你取得一顆虛空之翼蛋。", description = "如果你在探索過程中發現任何虛空之翼的蛋，就把它們帶來給我。\n\n要小心，虛空之翼蛋是稀有的發現。如果找不到也不要沮喪。這些龍喉已經非常徹底的收集過它們並運送到一些未知的地方。\n\n你可以在島上的生物身上找到蛋，靠近水晶結構的地方，礦坑裡，甚至是虛空聚晶結點或虛空之塵灌木裡。\n\n低調一點。我們不希望你的行動引起莫格的注意。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11050] = {title = "接受所有的蛋", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11051] = {title = "放逐更多惡魔", objective = "使用驅逐水晶來放逐劍刃山脈上煉冶場:憤怒或煉冶場:驚駭中15個惡魔。", description = "如果我們了解惡魔，其實基於我們深入地研究，我們是了解他們的，他們能快速修補珍貴的轉換門上所受到的任何傷害。\n\n所以，如果你想要取得另一個暗色符文的機會，帶著我們的驅逐水晶回到那裡並消滅更多惡魔。此外，你想幫我們減輕惡魔造成的威脅，對吧?\n\n我之所以會說「機會」是因為我們使用的程序會產生不同的結果。你可能會得到一個暗色符文，或是可能得到一個完全不同的東西。", progress = "一個像你一樣老練的專家在驅逐惡魔上應該不會有任何困難。你沒有困難吧，<race>?", completion = "我們很希望製造暗色符文的過程是極簡單的，&lt;name&gt;。唉，但它不是。請收下這個包包看看裡面，知道我們今天努力了什麼。我們不敢自己看。\n\n記住，如果你得到一個暗色符文，拿去和賈克交換一個晶鑄暗色符文。然後你就能再一次瓦解夏圖歐的傳送門。\n\n喔，還有&lt;name&gt;，別忘記明天再來這裡拿驅逐水晶。永遠都有更多惡魔需要被驅逐。", rewards = "您會收到：\n\n克朗克的摸彩袋頂尖裂片"}
MultiLanguageQuestData['tw'][11052] = {title = "阿卡瑪的承諾", objective = "將卡拉伯爾勳章交給撒塔斯城的阿達歐。", description = "<阿卡瑪將這顆水晶插入手中的勳章中。>\n\n我的身體已大不如前，<name>。經過這麼多年如此接近邪惡的本體 - 我不知道是否還能夠相信自己可以持有力量如此強大的神器而無動於衷。\n\n把這個當成我對你的承諾，當時機來臨你得面對伊利丹的時候，我會支持你。把它帶給那個我們都認識且能夠相信它的力量的人。將這個勳章交給撒塔斯城的阿達歐。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "阿卡瑪的束帶綠色手套破魔圓盾灰舌之刃血守衛的步槍灰舌死亡誓言者法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][11053] = {title = "起來吧，監督者!", objective = "到影月谷的龍喉營地和霸主莫格談談。", description = "一個苦工可以像你存活這麼久真是稀奇。更稀奇的是當一個苦工從渣滓裡脫穎而出獲得新階級。\n\n<瓦庫歐拍拍手。>\n\n霸主需要你，蠻兵。一個新的身分等著你，沒錯。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n監督者的徽章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11054] = {title = "工頭與你:做出對的選擇", objective = "影月谷，龍喉營地的大監督者馬朗要你幫他帶來10塊境外皮革和1塊泰藍塔斯的硬甲皮。", description = "所以你是新的監督者囉?嗯所有好監督者都需要一個東西，那就是適當的懲罰武器。在你去那裡給這些苦工一點教訓之前，要先準備好你的「利器」。每個監督者要收集材料來製作他們自己的「利器」，而你也不例外。\n\n我需要境外皮革和泰藍塔斯的硬甲皮。你可以在秘境原野找到泰藍塔斯，就在虛空風暴的北邊地區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11055] = {title = "迴力靴:專治沒用的苦工", objective = "影月谷，龍喉營地的大監督者馬朗要你懲罰20個懶惰的龍喉苦工。你還要交回你的迴力靴。", description = "這是你的迴力靴。模樣類似的有很多，不過這個才是屬於你的。\n\n身為一個監督者你要用這個迴力靴在違抗的苦工心中埋下恐懼。恰當地使用這個迴力靴，會對他們灌輸服從的觀念並讓他們卑屈。\n\n前進水晶礦區，懲罰所有被你見到正在偷懶的苦工。讓他們知道迴力靴的厲害!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11056] = {title = "海茲克的交易", objective = "到東司凱堤斯，海茲克的住所取得海茲克的包裹再拿回去給他。", description = "不要讓我們的對話引來注意。艾德瑞斯不會贊同的。\n\n我是阿拉卡社會最低等級的人，<name>。在泰洛克的規則裡，我早已被他的魔爪祭司崇拜的黑暗力量犧牲了。如果你說的是真的，魔爪祭司在尋求泰洛克的歸來，那麼你一定要阻止他們成功 - 不管你的領導者怎麼說!\n\n我有個對你有用的東西要給你。我在迷霧希拉克上層的舊居所有一個包裹。把它拿來給我!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11057] = {title = "下方的窘境", objective = "到劍刃山脈血之環外的其中一座高塔，與乾癟的莫格多克談話。", description = "對於你想來歐格利拉幫忙的熱誠我們非常贊賞，<class>。然而，在我們接受你的幫助之前要請你幫一個小忙。\n\n我們下方的弟兄們，正受到戈魯爾之子的奴役。請與乾癟的莫格多克談話，他正領導著巨魔對抗古羅領主們。\n\n你可以在血之環競技場東側的塔頂找到他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11058] = {title = "頂尖聖物", objective = "從一個頂尖聖物獲得頂尖顫動效果。", description = "很久以前有個已絕種的部族曾經住在這裡，一支叫頂尖的阿拉卡部族。他們文明遺物仍然存在。我們稱它們為頂尖聖物。\n\n我們只知道，適當地使用它們會帶來很多好處。每個聖物會呈現不一樣的顏色，以正確的順序去點按水晶，就會進入下一個等級，一次會比一次還要困難。\n\n要啟動聖物就需要一個頂尖裂片。等你洞悉了頂尖顫動後再來找我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11059] = {title = "紀念碑護衛", objective = "取得頂尖守護者頭顱。", description = "你已經知道怎麼使用這些單人型聖物，但如你所見，還有更大型的聖物，被單人型聖物環繞著。\n\n這些更大型的頂尖紀念碑功能差不多，但它們需要35個頂尖裂片才能啟動。\n\n我們最擔心的就是使用它們時召喚出的護衛。這些水晶結構喚醒了它們很久以前的阿拉卡主人，現在危害著歐格利拉。\n\n我們要你摧毀一個並帶來給我們做為證據。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11061] = {title = "父親的職責", objective = "為他取得巫士的不穩定精煉藥劑。", description = "至於另一個魔法藥水，只有在一個地方才能取得:貝許爾平臺。那是一個以太族基地，他們對外來者不是很友善，所以要取得會有些危險。\n\n你問貝許爾平臺在哪?嗯，如果你坐上你的飛行駿馬前往東北方，過了煉冶場:憤怒，你就會看到它。貝許爾水晶熔爐在平臺的東北方角落。\n\n謝謝你這麼做，<name>。這對我們的兒子來說就是一切!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11062] = {title = "禦天者前哨", objective = "到劍刃山脈頂端的禦天者前哨和天空指揮官凱勒談談。", description = "<name>，不知道你願不願意去北邊的禦天者前哨拜訪我們的朋友?\n\n天空指揮官凱勒和他的禦天者在這裡執行任務和我們守望相助，他要我們派任何可以幫忙的人過去。\n\n那就是你!\n\n盡快前往那裡，還有，請幫我們跟他打聲招呼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11063] = {title = "爭取你的翅膀...", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11064] = {title = "龍喉競賽:老邁克喬的民謠", objective = "跟隨莫格‧老邁克喬並試著待在你的飛行坐騎上。如果你擊敗了莫格‧老邁克喬就將你的勝利回報給影月谷，龍喉營地的傑‧諾斯利。", description = "別讓我的灰髮騙了你，蠻兵。我仍然是比你厲害十倍的騎手!別以為老狗就玩不出新把戲。\n\n現在你要做的就是跟隨我並試著不要被擊下你的坐騎。如果你可以做到，我就會承認失敗。\n\n等你準備好我們就起飛。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11065] = {title = "捆綁一些蒼穹鰭刺!", objective = "使用綑綁套索捕捉5隻蒼穹鰭刺。", description = "想幫忙禦天者和歐格利拉嗎?\n\n走開之前先聽我說吧，<帥哥/美女>。我們需要補充新坐騎!貝許爾平臺的轟炸行動和任務讓我們的坐騎傷亡慘重。\n\n飛翔在漩渦尖塔附近和東北方水晶背脊的蒼穹鰭刺看起來很適合。你不需要把牠們帶回這裡，雖然說那樣也不錯。你只要制伏並捆綁牠們，我們就會去追蹤。\n\n你可以去幫我抓住一些嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11066] = {title = "捆綁更多蒼穹鰭刺!", objective = "使用綑綁套索捕捉5隻蒼穹鰭刺。", description = "那麼，我希望你來幫我們捆綁更多的蒼穹鰭刺!由我所見，你是個使用繩索的天生好手!而且這是為了做好事，不只讓我們得到新坐騎，還幫助我們保衛歐格利拉，巨魔會很感激。\n\n記住，是飛翔在漩渦尖塔附近和東北方水晶背脊的蒼穹鰭刺。\n\n你可以再幫我捆綁一些嗎?", progress = "你對我們貢獻良多，<name>。我要你知道我們真的很感謝你所做的一切，讓我們有足夠存量的最新坐騎!", completion = "你再一次的讓我驚豔!告訴你...你何不明天再回來，我們現在先讓繩子休息一下?\n\n&lt;卡緹笑著。&gt;\n\n非常感謝你，&lt;name&gt;!", rewards = "您會收到：\n\n頂尖裂片"}
MultiLanguageQuestData['tw'][11067] = {title = "龍喉競賽:『污穢者』川普", objective = "跟隨『污穢者』川普並試著待在你的飛行坐騎上。如果你擊敗了『污穢者』川普就將你的勝利回報給影月谷，龍喉營地的傑‧諾斯利。", description = "龍喉對你不錯，<name>。就連像我這樣筋疲力竭的可惡生物都有機會。現在如果你想向破天者證明你的價值，你就要打敗我。\n\n我要把你像臭跳蚤一樣甩在我的尾巴後面...\n\n等你準備好我們就起飛。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11068] = {title = "龍喉競賽:年邁的克洛克", objective = "跟隨年邁的克洛克並試著待在你的飛行坐騎上。如果你擊敗了年邁的克洛克就將你的勝利回報給影月谷，龍喉營地的傑‧諾斯利。", description = "你要挑戰我?別逗我笑了!\n\n你是認真的?那好吧!你要做的就是不要死。你可以不死吧??即使我朝你猛投骷顱頭，再繞著你那可悲的騎乘技巧飛行?\n\n等你準備好讓我知道我們就起飛。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11069] = {title = "龍喉競賽:空軍指揮官艾克曼", objective = "跟隨空軍指揮官艾克曼並試著待在你的飛行坐騎上。如果你擊敗了空軍指揮官艾克曼就將你的勝利回報給影月谷，龍喉營地的傑‧諾斯利。", description = "我在那該死的洞裡待了三年。當了可惡的霜狼氏族戰囚三年。被迫坐在他們的哨塔裡聽著他們不停哀訴通往丹巴達爾的橋。說著有多「不公平」嘰哩呱啦劈哩啪啦...戰爭本來就不是公平的!讓他們都下地獄!\n\n當我被釋放的那一刻我就永遠離開那個地方來到這裡開始新生活。現在我和穆維里克正為頂尖獸人的位置競賽。如果你想得到那個位置，你就要先通過我這關，沒用的人。\n\n等你準備好我們就開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11070] = {title = "龍喉競賽:空軍指揮官穆維里克", objective = "跟隨空軍指揮官穆維里克並試著待在你的飛行坐騎上。如果你擊敗了空軍指揮官穆維里克，就將你的勝利回報給影月谷，龍喉營地的傑‧諾斯利。", description = "三年的血、汗和淚。大部分是淚...當毫無保留的作戰時，一個堅定的士兵流的淚是相當驚人的!\n\n「他們騎著馬跳進我們的哨塔!」「為什麼他們的基地防禦的那麼徹底?」「他們在搶奪我們的急救站，我要閃了!」\n\n軟弱的人...\n\n當黑暗之門打開的那分鐘我就不再哭泣了。現在我是龍喉的第一把交椅。如果你想成為頂尖的獸人，你就要擊敗我。\n\n等你準備好我們就開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11071] = {title = "龍喉競賽:碎天者隊長", objective = "跟隨碎天者隊長並試著待在你的飛行坐騎上。如果你擊敗了碎天者隊長就將你的勝利回報給影月谷，龍喉營地的傑‧諾斯利。", description = "你竟敢挑戰碎天者?你身邊的世界會墜入黑暗，因為天空會被我的隕星炸得四分五裂。\n\n你沒有贏的機會，士兵。不過是你自願找死...\n\n我享受著這種病態的狂熱，只為了要向任何做著這個錯誤的夢想的人說明一點意義。\n\n等你準備好我們就上陣!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n破天者皮鞭\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11072] = {title = "敵人之血", objective = "在司凱堤斯的召喚法陣中央找到顱骨堆。在顱骨堆用10個時光流逝卷軸召喚並擊敗每個子嗣。帶著各個象徵物回到黑風平臺找海茲克。", description = "被司凱堤斯魔爪祭司扣留為囚犯的子嗣都列在這本書裡:女獵人吉札拉，水晶巨人葛洛克，異教徒黑暗尖叫者阿卡萊和『風怒者』瓦奇茲。殺了他們才能讓泰洛克回到這個世界。\n\n你需要時光流逝阿拉卡身上帶的卷軸，才能在司凱堤斯的召喚法陣召喚他們。幫我從他們身上各帶一個象徵物回來。你挑戰的是強大的生物;帶朋友一起去會比較好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光流逝祭品"}
MultiLanguageQuestData['tw'][11073] = {title = "泰洛克的覆滅", objective = "帶著海茲克準備的時光流逝祭品到司凱堤斯中心的顱骨堆，召喚並擊敗泰洛克。完成這個任務後回去找天空指揮官艾德瑞斯。", description = "我...我假裝沒看見你和阿拉卡囚犯的往來，<name>。看來你和他合作的直覺是對的。\n\n你必須了解...如果我贊同你把泰洛克召來這個世界我就會面臨被反叛的命運。\n\n帶著這些海茲克為你準備的物品進行你的計畫。到時候我會率領我的人支援你。我建議你也帶著自己的軍隊去。我擔心這件事你只有一次機會。", progress = nil, completion = "你讓我們感到非常驕傲，&lt;name&gt;。我會讓撒塔斯的人都知道你的行為。禦天者永遠都欠你一份人情。", rewards = "擊風者長槍瑟弗林的柺杖寶石裝飾魔棒您會收到：\n\n"}
MultiLanguageQuestData['tw'][11074] = {title = "子嗣的象徵", objective = "從司凱堤斯的時光流逝阿拉卡身上收集時光流逝卷軸，把它們帶到司凱堤斯，找到召喚法陣裡的顱骨堆。召喚並擊敗泰洛克敵人的子嗣再帶著阿卡萊之爪，凱羅格之刺，瓦奇茲的鱗片和吉札拉之爪回到海茲克那裡。", description = "被司凱堤斯魔爪祭司當做囚犯的子嗣都列在這本書裡。女獵人吉札拉，水晶巨人葛洛克，異教徒黑暗尖叫者阿卡萊和風怒者瓦奇茲。殺了他們才能讓泰洛克回到這個世界。\n\n你需要時光流逝阿拉卡身上帶的卷軸並在司凱堤斯的召喚法陣燃燒它們。你挑戰的是強大的生物;帶朋友一起去會比較好。", progress = "我要每個泰洛克勁敵子嗣的象徵物品。只有這樣我們才能準備好召喚泰洛克。", completion = "太好了!收下這個。我用你取得的物品準備了這個包裹。它們會讓你召喚泰洛克。\n\n小心，&lt;name&gt;。他是世界上最強大的阿拉卡。別小看他!", rewards = "您會收到：\n\n時光流逝祭品"}
MultiLanguageQuestData['tw'][11075] = {title = "虛空之翼礦坑", objective = "找到虛空之翼岩架的礦坑夫人。", description = "虛空之翼礦坑需要你的幫忙，<name>監督者。\n\n兩天前我們有了一個可怕的發現，之後我們的採礦工作就惱人的終止了。一個礦工在礦坑深處工作時鏟到一個不尋常的水晶結構。不幸的是，這個水晶結構是屬於一隻非常憤怒的虛空之龍。這隻野獸從沉睡中醒來消滅了我們所有的勞工。\n\n把這消息報告給礦坑夫人。她們就在西南方的礦坑口等著你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11076] = {title = "拾起貨品...", objective = "影月谷，虛空之翼礦坑的礦坑夫人要你取得15個虛空礦坑貨品箱。", description = "我們許多的苦力都散佈在這些礦坑裡。裝滿貨物的推車散亂在這個礦坑的每一吋!但現在的侵擾讓我們無法靠近。\n\n那是你進來的地方，<name>。你每天在這個礦坑的職責就是收集礦工和深礦勞工留下的貨物。\n\n收集虛空礦坑貨品再回來找我或我的姐妹。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11077] = {title = "龍的問題不算什麼", objective = "影月谷，虛空之翼礦坑的龍喉工頭要你殺死15個虛空礦坑鐮奪怪和5個虛空礦坑劫毀者。", description = "那隻龍醒來激怒了這些礦坑裡其他討厭的生物。有兩種讓龍喉很頭痛。虛空礦坑鐮奪怪和虛空礦坑劫毀者。你一定要幫我們殺掉他們。我只要你每天去一次。\n\n去那裡殺死他們越多越好!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11078] = {title = "統治天空", objective = "取得龍牙。", description = "你四處飛行的時候，一定注意到上方的龍群了。我相信你還沒在牠們的憤怒下成為受害者。幫我們結束牠，<name>!\n\n瑞文達科和歐比希迪亞主宰這個平臺，而印希迪恩和狂怒之翼則管理東北方平臺上方的天空。他們在各自的平臺都有自己的棲所。不知道你和你的朋友是否能去其中一個棲所，<小夥子/小姑娘>，用35塊頂尖裂片打破一顆蛋把龍引下來。\n\n將龍牙交給我做為證據。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11079] = {title = "賈克的惡魔皮鞭", objective = "取得一條惡魔皮鞭。", description = "賈克認為聰明有時候是笨的。賈克不想思考。我要小<race>去擊潰大惡魔!\n\n他們有一些首領，而那些首領都有皮鞭來傷害那些小惡魔。你幫賈克帶一條皮鞭來!\n\n你到燃燒的、綠色的、惡魔水晶稜柱的煉冶場挑戰惡魔首領，用35塊頂尖裂片讓他們現身。他們叫高瓦諾斯，布萊克斯，札克辛和莫阿格焚化者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11080] = {title = "聖物的增益", objective = "從頂尖聖物獲得頂尖放射增益效果。", description = "既然你已感受了頂尖聖物的啟發顫動，是時候讓你更了解它們的作用了。我們很希望得益於你對聖物的觀察!\n\n隨著你調合聖物的能力更進一步，你會獲得更高一層的知識。這個認知來自於聖物的放射增益。\n\n等你獲得這樣的放射增益後再來找我們。", progress = nil, completion = "你處理聖物的睿智再一次令我們驚豔，&lt;name&gt;。我們可以建議你每天與聖物交流至少一次，以維持如此的心智敏銳度嗎?", rewards = "您會收到：\n\n頂尖裂片"}
MultiLanguageQuestData['tw'][11081] = {title = "黑暗之血大反叛", objective = "將黑暗之血逃脫計畫交給礦坑夫人。", description = "這份文件概述黑暗之血破碎者策劃的反叛。看來那隻龍是用來分散別人對他們逃脫的注意力。看看礦坑裡散亂的屍體，可以推測他們的計畫失敗了。\n\n把逃脫計畫交給礦坑夫人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11082] = {title = "真相尋求者", objective = "找到一個黑暗之血監督者並審問他。帶著黑暗之血的訊息和監督者的手回到礦坑夫人那裡。", description = "這些礦工太笨了無法策劃出任何逃亡計畫。我們必須找到並懲罰那個源頭。進入礦坑深處尋找黑暗之血監督者。如果他們還沒被礦坑的居民征服，他們就一定躲在什麼地方。\n\n當你找到一個，就審問他直到他說出策劃逃亡的真正首腦。帶著這個背叛者的身分和監督者的手回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11083] = {title = "瘋狂混亂", objective = "影月谷，虛空之翼礦坑的『鞭奴者』羅納葛要你殺死瘋狂的黑暗之血工頭和5個瘋狂的黑暗之血礦工。", description = "別擔心這條龍，<name>。我們有對策...\n\n在這個礦坑深處有一群瘋狂的黑暗之血。在龍衝破出來後，他們的出口就被切斷。然而，在僅僅兩天的隔離之後，他們全都瘋了。\n\n他們開始吃人並惡意破壞。我們這裡不需要這樣的瘋子。找到並殺光他們全部的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11084] = {title = "抬頭挺胸，隊長!", objective = "到影月谷和龍喉營地的霸主莫格談談。", description = "哇，哇，哇...你還活著。很好，因為莫格要你立刻到他的哨塔見他。動作快!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n隊長的徽章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11085] = {title = "逃離司凱堤斯", objective = "安全護送禦天者囚犯並向天空士官多林報告。", description = "嗨，<name>。謝謝你來幫我。\n\n阿拉卡的怪鳥在我進行偵察任務時把我從虛空鰭刺上擊下。\n\n我們快離開這裡，趁還來的及。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11086] = {title = "瓦解暮光傳送門", objective = "影月谷，龍喉營地的霸主莫格要你殺死20個死亡之影密探。", description = "你身為龍喉隊長的職責之一，就是消滅外域的燃燒軍團活動。壓制那些反抗伊利丹王的傢伙是你的責任!\n\n那些惡魔在納葛蘭西邊的暮光山脊發現傳送門並愚蠢地嘗試穩定它。他們一定要為他們的背叛付出代價，而你就是那個讓他們還債的獸人。\n\n前往暮光山脊殺光它的居民。你要負責每天至少對他們的防禦工事發動一次攻擊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11087] = {title = "HYJAL FLAG", objective = "时空之穴的Soridormi要你从盘牙水库Lady Vashj那儿取回Vashj's Vial Remnant，并从风暴要塞Kael'thas Sunstrider那儿取回Kael's Vial Remnant。", description = "伊利丹从永恒之井中取出了7瓶井水。他将其中3瓶倒入海加尔山颠的湖泊中，由此形成了第二口永恒之井。岁月流逝，剩下4瓶井水已不知去向。\n\n黑暗之门开启后，我们得知伊利丹将2瓶井水交给了他的副官Kael'thas和Vashj。取回残余的井水；我们可以利用它打开通往近代或是远古时期的海加尔山的时光通道。我们必须维持海加尔圣战的成果。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11088] = {title = "<DEPRECATED>Unravelling Your Training", objective = "Bring Jonathan LeCraft 10 pieces of Spellfire cloth.", description = "Bring me a lot of Spellfire cloth, and then you can forget everything.您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n忘卻魔焰裁縫"}
MultiLanguageQuestData['tw'][11089] = {title = "雷斯海卓恩的靈魂火砲", objective = "影月谷，龍喉營地的伊利達瑞領主巴薩斯要你幫他帶來2個魔鋼錠，1個堅鋼骨架，1個克銀能量核心和1個完美的秘法精華。", description = "雷斯海卓恩現在統治著納葛蘭的暮光山脊。一個有這樣力量的埃雷達爾存在這世界上對伊利達瑞而言不是好事。唉，我們沒有需要的資源來殺死雷斯海卓恩。不要那些渾蛋對黑暗神廟帶來的戰爭。不...我有個更好的計畫。\n\n你要去制服雷斯海卓恩，把他逐回暮光傳送門。要這麼做就一定要靈魂火砲。\n\n把這個清單上的東西帶來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11090] = {title = "壓制征服者雷斯海卓恩", objective = "影月谷的龍喉營地，伊利達瑞領主巴薩斯要你對納葛蘭的『鎮壓者』雷斯海卓恩使用靈魂火砲。\n\n你也必須將靈魂火砲交回。", description = "<巴薩斯拿起一個奇特的儀器。>\n\n這是一個靈魂火砲。調整好時它的效果是毀滅性的。這個已經和我的血液調合了。和雷斯海卓恩 - 我兄弟的血管裡流的血是相同的。是的，效忠錯誤的對象會毀了他。\n\n帶著火砲飛往西納葛蘭的暮光山脊。找到雷斯海卓恩並開火!你一定要留在你的坐騎上並在範圍裡才能發揮效用。利用地勢上的優勢對抗他，他就只能跑了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "伊利達瑞領主外套冥想腿甲伊利達瑞角盔戒律之伊利達瑞魔棒您會收到：\n\n"}
MultiLanguageQuestData['tw'][11091] = {title = "特別感謝你", objective = "到劍刃山脈頂端的歐格利拉和喬那斯談談。", description = "你為我們的利益努力讓我們感到光榮。現在我們想讓你見一個人。\n\n喬那斯是我們最信任的軍需官。他管理我們的貨物，只出售給對歐格利拉最有貢獻的朋友。\n\n你就是這樣的一個朋友，<name>。\n\n等你有時間，去和他談談。據我們的了解，他準備了一點東西給你以表達我們的感激。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n歐格利拉醫療包"}
MultiLanguageQuestData['tw'][11092] = {title = "嗨，指揮官!", objective = "到影月谷的龍喉營地和霸主莫格談談。", description = "<name>隊長!\n\n<監工瓦庫歐向你致敬。>\n\n霸主莫格要求立即在他房間見你!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n指揮官徽章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11093] = {title = "飢餓的虛空鰭刺", objective = "在黑風平臺南邊的樹林裡使用虛空鰭刺籠並殺死飢餓的虛空鰭刺附近的黑風扭曲追趕者。完成任務後回去找禦天者管理者迪塞克。", description = "虛空鰭刺一旦經過適當的訓練就會出奇地忠誠和順從。不幸的是司凱堤斯的戰役讓它們傷亡慘重。\n\n我們每天都有許多的突擊 - 可憐的夥伴們都很少休息。隨著最近食物短缺，如果那些可惡的鳥人不殺他們，飢餓也會把他們殺死。\n\n如果你可以幫個忙，帶一隻我們的鰭刺到南邊的樹林去。他們不喜歡扭曲追趕者的肉，除非是新鮮的。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n極效敏捷藥劑內行藥劑\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][11094] = {title = "殺光他們!", objective = "將你任務的消息和龍喉信號槍帶到影月谷給星光聖所的秘法師賽利斯。", description = "指揮官<name>，注意!你要率領一支破天者軍隊劫掠虛空之翼農場底部的占卜者前哨。摧毀星光聖所後，我們和日蝕崗哨跟伊利達瑞崗哨的聯絡管道就會再次開啟。\n\n現在就去!用這個信號槍通知破天者準備攻擊!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11096] = {title = "上方的威脅", objective = "殺死阻礙之丘任何20個戈杜尼巨魔再回撒塔斯城找尤拉。", description = "所以你想加入禦天者?嗯，我知道你會飛行...但你能打鬥嗎?\n\n禦天者誓言保衛撒塔斯不讓危險逼近我們，不管遠或近。住在北方阻礙之丘的戈杜尼巨魔是我們立即的威脅。\n\n接近巨魔對撒塔斯的陸軍來說是有難度的。那是我們進來的地方。看你能做什麼來幫忙遏制他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11097] = {title = "史上最致命的陷阱", objective = "協助指揮官赫布和占卜者人保衛星光聖所。等所有的龍喉軍隊都被擊敗，帶著占卜者勳章回到龍喉營地找霸主莫格。", description = "帶著這些占卜者勳章。一切結束後莫格要看「勝利」的證據。他會知道它們是由占卜者陣亡士兵屍體上取得的。\n\n現在剩下要做的就是使用信號槍來警告龍喉劫掠者。等你準備好我們就會殺了他們。只要給我一句話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11098] = {title = "前往司凱堤斯!", objective = "帶著爆裂物包去司凱堤斯外的黑風平臺找天空士官多林。", description = "阻礙之丘只是我們部署的前線之一。一個較不緊急但危險許多的威脅正從斯其索山脈後方逼近，就在司凱堤斯的阿拉卡城裡。\n\n幾個月前我們的斥候在那裡發現增加頻繁的阿拉卡活動。跟著發生了幾次撒塔斯攻擊。我們就在他們城外部署了軍隊。\n\n帶著這些爆裂物去找黑風平臺的天空士官多林，就在司凱堤斯外。告訴他你是一個新兵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11099] = {title = "殺光他們!", objective = "將你任務的消息和龍喉信號槍帶給薩塔祭壇的隱士希拉。", description = "指揮官<name>，注意!你要率領一支破天者軍隊劫掠我們親愛的黑暗神廟西北方的奧多爾前哨。摧毀薩塔祭壇後，我們和考斯卡崗哨的聯絡管道就會再次開啟。\n\n現在就去!用這個信號槍通知破天者準備攻擊!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11100] = {title = "指揮官阿克斯", objective = "將龍喉信號槍帶到影月谷交給薩塔祭壇的指揮官阿克斯。", description = "龍喉只敢在我們的防守鬆懈時攻擊我們。如果他們在我們準備好的時候攻擊我們只會慘敗。\n\n我要你引他們來，<name>。\n\n<希拉點點頭。>\n\n對...一個陷阱。帶著他們霸主給你的信號槍並將它送給指揮官阿克斯。他就在建築物外面站崗。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11101] = {title = "史上最致命的陷阱", objective = "協助指揮官阿克斯和奧多爾人保衛薩塔祭壇。等所有的龍喉軍隊都被擊敗，帶著奧多爾勳章回到龍喉營地找霸主莫格。", description = "帶著這些奧多爾勳章。一切結束後莫格要看「勝利」的證據。他會知道它們是由奧多爾陣亡士兵屍體上取得的。\n\n現在剩下要做的就是使用信號槍來警告龍喉劫掠者。等你準備好我們就會殺了他們。只要給我一句話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
