MultiLanguageQuestData['tw'][11104] = {title = "不再是治療師", objective = "The power within your ring is malleable, though reversing your choice is not easy. Are you sure you want to replace its current form?", description = nil, progress = "The power within your ring is malleable, though reversing your choice is not easy. Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily. They can be made to flow backward, but with great difficulty.", rewards = "永恆勇士指環永恆聖人指環您能選擇下列奬勵中的一個：\n\n永恆防衛者指環"}
