MultiLanguageQuestData['tw'][11107] = {title = "向大領主鞠躬", objective = "到影月谷的龍喉營地和霸主莫格談談。", description = "我連直接帶個口訊來給您都不配，大人。請原諒我這次的無禮。霸主莫格要求您立刻前去他的房間。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][11108] = {title = "伊利丹‧怒風", objective = "會見伊利丹‧怒風。如果你僥倖存活的話，去撒塔斯的陰鬱城找巴薩姆斯。", description = "來吧，<name>大領主。伊利丹本人正等著我們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
