MultiLanguageQuestData['tw'][11581] = {title = "褻瀆這些火焰！", objective = "Desecrate the Alliance's Westfall bonfire!", description = nil, progress = "Desecrate the Alliance's Westfall bonfire!", completion = nil, rewards = "您會收到：\n\n燃燒之花"}
MultiLanguageQuestData['tw'][11582] = {title = "監控裂口:破碎裂隙", objective = "琥珀岩臺的加倫要你在破碎裂隙異常處使用奧能檢測儀然後把讀數交給他。", description = "你感覺到了嗎?又一個餘震...你真該早幾分鐘來的!\n\n我恐怕又需要你的協助了。我的儀器指出西邊有個巨大的異變，在水面下很深的地方。\n\n就跟之前一樣，我需要你帶著奧能檢測儀下去收集數據。\n\n我會對你施展一道法術，讓你可以在水中呼吸。如果在你找到異變之前法術就耗盡了，回來告訴我，我會替你重新施展。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][11583] = {title = "榮耀火焰", objective = "榮耀西部荒野的火焰。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n燃燒之花"}
