MultiLanguageQuestData['tw'][13176] = {title = "Preparing the Delivery", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][13177] = {title = "以其人之道，還治其人之身", objective = "冬握堡壘的指揮官桑奈希要求你殺掉10個部落成員。", description = "歡迎來到冬握堡壘，<name>。你的任務很簡單。擊敗十個部落菁英。現在，去吧!為聯盟帶回勝利!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13178] = {title = "趕盡殺絕!", objective = "冬握堡壘的指揮官達多許要求你殺掉10個聯盟成員。", description = "歡迎來到冬握堡壘，<name>!督軍卡爾洛斯下了一道命令:趕盡殺絕!\n\n讓十個最強悍的聯盟成員倒下後，回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13179] = {title = "以其人之道，還治其人之身", objective = "冬握湖的指揮官桑奈希要求你殺掉10個部落成員。", description = "歡迎來到冬握湖，<name>。你的任務很簡單，擊敗十個部落的精英。去吧!為聯盟帶來勝利!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13180] = {title = "趕盡殺絕!", objective = "冬握堡壘的指揮官達多許要求你殺掉10個聯盟成員。", description = "歡迎來到冬握湖，<name>!督軍卡爾洛斯下了一道命令:趕盡殺絕!\n\n讓十個最強悍的聯盟成員倒下後，回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13181] = {title = "冬握之捷", objective = "在冬握戰場中獲勝，並向冬握湖的戰術軍官阿布拉米斯回報。你必須參與戰鬥才能擁有勝利的榮耀。", description = "指揮官桑奈希的腳下堆了這麼多的部落屍體，他一定很滿意，但是對驍勇遠征軍而言，控制冬握才是最重要的目標。你得確保我們能徹底控制冬握湖。\n\n不過，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13182] = {title = "别忘了蛛卵！", objective = "纳尔苏深渊的拆解者基里克斯希望你前往艾卓-尼鲁布，摧毁6枚天灾蛛魔之卵。", description = "艾卓-尼鲁布里面布满了天灾蛛魔细心呵护的卵，它们很快就会孵化，进一步扩充天灾蛛魔的规模。\n\n就算我们把洞中的亡灵都干掉，但是倘若留着那些蛛卵的话，等它们孵化出来之后，一切又将会到老样子。\n\n当你去艾卓-尼鲁布探险时，记得清理掉你在我们那座古老的家园中找到的所有天灾蛛魔之卵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "除名護手淨化手甲災禍鎮壓裹帶懲罰驅逐手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][13183] = {title = "冬握之捷", objective = "在冬握戰場中獲勝，並向冬握湖的戰術軍官科伊瑞斯回報。你必須要參與戰鬥才能擁有勝利的榮耀。", description = "雖然達多許必定會為我們痛宰敵人感到滿意，但掌控冬握堡壘才是我們的最終目的。不擇手段也要確保冬握湖是我們的。\n\n然而，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13184] = {title = "Outliving Usefulness", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][13185] = {title = "突破重圍", objective = "冬握堡壘的莫普中尉要你摧毀3台聯盟攻城器械。", description = "我聽到他們了!聯盟就要來了。摧毀三部聯盟攻城器，然後回來找莫普。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13186] = {title = "突破重圍", objective = "冬握堡壘的資深爆破兵勒茍索要你摧毀3台部落攻城器械。", description = "這城堡被部落軍隊包圍，只是時間上的問題了。摧毀3台他們的攻城裝置，然後向我回報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13187] = {title = "無面者", objective = "先知伊須特要你殺死信使沃菈齊及其身邊的三個忘卻者。", description = "在對抗不死生物的戰爭中，隨著家園一寸一寸地淪陷，我的子民也愈發絕望。\n\n那些被稱為無面者的生物，我們只知道他們曾不慎觸怒了古老神衹的意旨。\n\n總而言之，我們無法同時與這些強大的敵人兩面作戰。\n\n也許借助你的幫助，我們終於可以打敗無面者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "邪惡阻撓披肩嫌惡肩墊廢止重肩甲無面者肩冑您會收到：\n\n"}
MultiLanguageQuestData['tw'][13188] = {title = "諸王之道", objective = "把信件送給聯盟的國王，暴風城的暴風要塞中的安杜因‧烏瑞恩。", description = "你從今而後，永遠都是一名黯刃騎士，<name>，但你要知道：你曾是聯盟的英雄。\n\n<達瑞安凝視著你。>\n\n我們的騎士團若要存活下去，必定得要建立盟友。你必須代表黯刃騎士團前往聯盟。\n\n在我東南方的平臺上，有個通往暴風城的傳送門。帶著這封由弗丁為你所寫的信，送到安杜因‧烏瑞恩國王手中。通過傳送門吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13189] = {title = "薩魯法爾的祝福", objective = "把信件送到奧格瑪交給薩魯法爾霸王。", description = "你從今而後，永遠都是一名黯刃騎士，<name>，但你要知道：你曾是部落的英雄。\n\n<達瑞安凝視著你。>\n\n我們的騎士團若要存活下去，必定得要建立盟友。你必須代表黯刃騎士團前往部落。\n\n在我東南方的平臺上，有個通往奧格瑪的傳送門。帶著這封由弗丁為你所寫的信，送到薩魯法爾霸王手中。通過傳送門吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][13190] = {title = "黄金时代", objective = "纳尔苏深渊的拆解者基里克斯希望你弄到一具安卡哈看守者的尸体，将其放在安卡赫特的安卡赫特火盆上焚烧。\n\n这个任务只能在英雄难度下完成。", description = "安卡赫特，我们的起源之地……\n\n我梦想着有一天可以战胜那些笼罩着我们古老家园的死亡和黑暗的力量。为了让我的梦想变为现实，我想到一个计划，可以动摇敌人的军心。\n\n我们要烧死他们那珍贵的看守者！\n\n在城市深处的火盆上焚烧他们的尸体，让那种味道在空气中弥漫，让我们的敌人知道其实他们是如此的不堪一击。\n\n记住，<class>！那些亡灵的尸体非常易碎，而且会很快腐坏。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13191] = {title = "為石毀車補給燃料", objective = "冬握堡壘的攻城鐵匠重蹄要你前往火焰熔爐，從聯盟玩家身上取得10個永恆餘燼。", description = "為了部落，<name>!雖然戰鬥就要結束，我們還是得為聯盟的下一波攻勢做好準備!去冬握東南邊的火焰熔爐取回十個永恆餘燼。\n\n這些餘燼混合煤塊後可以作為石毀車和攻城機具的燃料。\n\n我聽到報告，聯盟豬玀沒日沒夜地採集餘燼。殺光他們，奪走他們的餘燼!如果他們已經遺棄了那區域，做好準備，和那一帶的火元素戰鬥，直到你找到餘燼為止!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13192] = {title = "護衛城牆", objective = "冬握堡壘的咒毒大師符金要求你，從冰川瀑布取回10套灌能的護甲。", description = "嘿，老兄。這地方搞得我皮皮挫的啦，你不暸的嗎?\n\n路上好多孤魂野鬼。我想弄個咒毒防護結界，但是我需要一些靈魂，老兄。別的我不要，只有強悍勇士的靈魂能用。\n\n冬握東邊有個冰川瀑布，那裡的特別性質能夠淬鍊出我要的靈魂。在那裡幹掉聯盟，搞不好他們就有我要的東西。\n\n帶回那些傢伙的護甲。如果沒有聯盟在那，可能就是被元素先下手了，老兄。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13193] = {title = "龍骨與箭頭", objective = "冬握堡壘的維耶隆‧炎羽中尉要你前往暗影森林，從聯盟玩家身上取得10個龍骨箭袋。", description = "為什麼給我裝備弓箭手的工作?我是個詩人，不是遊俠!好吧，抱怨也沒用。<name>，我需要龍骨以製造箭頭。\n\n前往冬握西邊的暗影森林。從最近的一次戰鬥後開始，聯盟也在那個區域採集龍骨。殺掉他們並拿走龍骨。\n\n如果失敗的話，你也可能很幸運地從那一帶的靈魂弄到龍骨。我聽說他們喜歡將活的獵物弄死，然後串在龍骨上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13194] = {title = "以玫瑰治療", objective = "原獵者穆法特要你前往生命冷原，從聯盟玩家身上取得10個聯盟草藥袋。", description = "在戰火稍事歇息之際，或許有人會相信和平的曙光就要降臨於斯。然而令人沮喪，這並非吾輩命運之歸宿。\n\n前往冬握湖西南部的生命冷原。我需要生於當地的玫瑰，用以製造治療創傷的藥膏。\n\n不幸地由於聯盟的濫採，玫瑰已變得駭人地稀少。殺掉生命冷原上的聯盟成員，從他們身上取走草藥袋。\n\n如果此舉不成，或許鞭笞者身上也會有。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13195] = {title = "罕見的草藥", objective = "冬握湖的隱士泰莎要你前往生命冷原，從部落玩家身上取得10個部落草藥袋。", description = "我的媽，這裡有夠冷!讓我想起阿古斯星上風暴圍繞的卡里諾斯山脈。無論如何，這裡的冰霜風雪會讓我們的士兵著涼的。\n\n前往冬握堡壘西南方的生命冷原，把10個部落草藥袋帶回來給我。我會將它們磨成抵禦寒冷用的草藥。\n\n曾有人目擊部落也在那一帶採集草藥。別猶豫，不要留下任何活口，然後取走他們的草藥袋!\n\n你或許也能在那個地區的鞭笞者身上找到草藥袋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13196] = {title = "龍骨與箭頭", objective = "冬握湖的弓箭商藍道夫要你前往暗影森林，從部落玩家身上取得10個龍骨箭袋。", description = "元龍實在是妙不可言!好吧，至少他們的骨頭是!我曾經以龍骨製的箭頭裝備我們的弓箭手。不幸地，在安格拉薩的大屠殺後，在龍骨荒野上幾乎不可能找到龍骨。\n\n然而，冬握湖西緣的暗影森林中，仍有著多得足以淹沒我們的龍骨。\n\n前往暗影森林，帶回任何你所找到的龍骨碎片!\n\n部落也在那一帶收集龍骨碎片。殺光他們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13197] = {title = "為石毀車補給燃料", objective = "冬握湖的攻城大師斯托哈德要你前往火焰熔爐，從部落玩家身上取得10個永恆餘燼。", description = "<name>!是你該現身的時候了。我們很可能會在這場戰鬥中吃鱉，所以最好儘早開始為下回準備!去冬握湖東南部的火焰熔爐取回一些永恆餘燼。\n\n這些餘燼混合煤塊後可以作為石毀車和攻城機具的燃料。\n\n噢，還有，如果你在那裡遇到部落，別猶豫，殺光他們，奪走他們的餘燼。我們一定要阻止他們繼續佔據要塞!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13198] = {title = "保衛勇士", objective = "冬握湖的巫女凱拉娜要你前往冰川瀑布，從部落玩家身上取得10件灌魔部落護甲。", description = "<name>，見到你真好。我們應該加緊腳步以準備下一波對要塞的攻勢。我的研究指出，近來在冰川瀑布被殺害的士兵，他們所穿的護甲被灌注了一股巨大的能量。部落正在那一帶蒐集護甲。\n\n馬上前往冰川瀑布，殺掉任何你遇到的部落成員。將他們灌能的護甲帶回來給我。\n\n如果你找不到任何部落成員，也許可以在那裡找到被元素生物殺害的冒險者所遺留下來的護甲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13200] = {title = "為石毀車補給燃料", objective = "冬握湖的攻城鐵匠重蹄要你前往火焰熔爐，從聯盟玩家身上取得10個永恆餘燼。", description = "為了部落，<name>!雖然戰鬥就要平息，我們還是得為奪回要塞做好準備!去冬握東南邊的火焰熔爐取回十個永恆餘燼。\n\n這些餘燼混合煤塊後可以作為石毀車和攻城機具的燃料。\n\n我聽到報告，聯盟豬玀沒日沒夜地採集餘燼。殺光他們，奪走他們的餘燼!如果他們已經遺棄了那區域，做好準備，和那一帶的火元素戰鬥，直到你找到餘燼為止!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13202] = {title = "大禍臨頭", objective = "冬握湖的咒毒大師符金要你前往冰川瀑布，從聯盟玩家身上取得10件灌能聯盟護甲。", description = "嘿老兄。看到聯盟那些傢伙了嗎?他們躲在自己的堡壘裡，看來倒挺安逸的。\n\n看來他們過得太爽了點，對吧?我想惡搞一下那地方，但是我需要一些靈魂，老兄。不過我可不是巫毒符不挑，我只要可以勝任工作的強悍勇士靈魂。\n\n冬握東邊的冰川瀑布有某種特質，可以淬鍊出我要的靈魂。作掉那裡的聯盟成員，也許他們有我們需要的東西。\n\n帶回那些小傢伙的護甲。如果那裡沒有聯盟成員，或許是被元素先下手為強了，老兄。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13203] = {title = "冬幕節禮物", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n冬幕節禮物"}
MultiLanguageQuestData['tw'][13204] = {title = "奇怪的蘑菇", objective = "从安卡赫特的野蛮洞穴兽那里收集6只奇异的蘑菇，然后把它们交给纳尔苏深渊的拆解者基里克斯。", description = "一只奇形怪状的蘑菇状的真菌从一块散发着强烈异味、被软泥包裹的洞穴兽的肉上掉了下来。在检查这只蘑菇的时候，你被它散发出的恶臭熏得晕头转向。\n\n你不由得猜想，也许这是蛛魔们喜好的某种美食？你决定找出这块有机物的真相，于是把它放在了包裹里。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][13205] = {title = "撤除武裝", objective = "防衛者摩丹要你進入俄特加德要塞，並偷走5件維酷武器。", description = "從我身邊拿走它，<小夥子/小女孩>，這些維酷武器真是齷齪!\n\n我親自觸碰了它們的邊緣，其中有某種古怪。令人迷惑地勻稱、邪惡的鋒利刃口，全然是種致命武器。\n\n潛進他們的堡壘，若沒有意外的話，弄來些他們的武器。\n\n底限是:越少維酷人在附近揮舞斧頭越好。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "寧靜心靈護符鋒刃墜飾聖光殘片項鍊織紋鋼鍊"}
MultiLanguageQuestData['tw'][13206] = {title = "撤除武裝", objective = "黑暗遊俠瑪拉要求你，從俄特加德要塞偷走5件維酷武器，然後送回她手中，她會在俄特加德要塞中等候。", description = "我們應該好好研究這些野蠻人武器中的奧妙!\n\n如果你曾目睹，他們是如何輕易地把我的同袍大卸八塊，你就會了解我的急迫感。\n\n搜索那地方，帶回他們的武器，能拿多少就拿多少。", progress = "武器弄來了沒?", completion = "你能多弄一件出來，士兵在戰場上就會少面對一件。\n\n謝謝你。", rewards = "平靜群空項鍊百牙項鍊磚石墜飾受迫之力護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][13207] = {title = "石之大廳", objective = "布萊恩‧銅鬚要求你和他一道尋找石之大廳裡的秘密。", description = "嗯哼，在這裡看到其他冒險者是蠻令我驚訝的。\n\n如果我的研究正確，這裡一定有值得探尋的巨大發現!\n\n如果你可以讓我無後顧之憂，我倒是很歡迎有你與我作伴。", progress = nil, completion = "未解的疑問永遠都比答案多，嗯，小夥子？", rewards = "無畏探險者披肩冒險者肩墊失落秘密肩甲勘查肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][13210] = {title = "Blizzard Account: - DEM - E - FLAG", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][13211] = {title = "以火淨化", objective = "黑色守望的十字軍歐拉金‧山瑞斯要求你，以歐拉金的火炬焚毀7具膿瘡屍體。", description = "天譴軍團將我們倒下的弟兄轉化成食屍鬼或骷髏，或肢解他們的軀體以製造憎惡體，回過頭來對付我們。這一切必須被阻止!\n\n為了保衛家園和同胞而倒下的弟兄都是英雄，他們不該落得如此可悲的命運。再者，我們實在無法承受在戰場上與他們干戈相向的痛苦。帶著這把火炬前往血肉作坊，燒掉任何你在再活化聖所與憎惡體實驗室裡找到的屍體。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "十字軍公平之觸歐拉金的附魔火炬您會收到：\n\n"}
MultiLanguageQuestData['tw'][13212] = {title = "他被大卸八塊了", objective = "找回歐拉金的軀幹、歐拉金的雙腳、歐拉金的左手、和歐拉金的右手，帶回給黑色守望的黑騎兵阿爾利。", description = "因為十字軍歐拉金被綁架，在對血肉作坊的最終攻擊即將來到之際，銀白十字軍卻是群龍無首。雖然對我而言，他和其他十字軍並無二致，但是十字軍們可不是這麼想。\n\n我實在不喜歡在這件事上浪費時間，但我別無選擇。我們英勇的十字軍勇士大概已經被肢解，要用來製造憎惡體了。下去血肉作坊，宰掉和我方戰鬥的肥胖恐獸，找回歐拉金的軀體。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13213] = {title = "英靈殿之戰", objective = "與英靈殿裡的蓋爾維孚對話。", description = "我看到、聽到了許多事，<name>，自你擊敗共主巴拉加德以來，發生了些很重要的事:英靈殿之戰需要你!\n\n你可以在北方找到戰場。現在和你的夥伴一起出發吧，找到華爾琪蓋爾維孚。她在英靈殿將提供給你的挑戰者必定需要幫助。\n\n祝你好運。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13214] = {title = "英靈殿之戰:已逝的英雄", objective = "英靈殿的蓋爾維孚向你挑戰，在一場戰鬥中擊敗六名死去的英雄:艾德雷斯、『半魂』蓋內斯、賈卓斯、瑪蘇德、里希和塔拉。\n\n若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。", description = "若你認為你準備好了，我剛好有場可以讓你一展身手的比賽。\n\n另一組外來者認為，他們已準備好要接受英靈殿的嚴苛挑戰。他們恃傲而來，但最終和其他人亦無二致。\n\n若你自視不凡--自恃擁有可與傳奇戰士匹敵的技巧與經驗--那麼，請接受挑戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13215] = {title = "英靈殿之戰:『黑暗大師』齊特瑞司", objective = "英靈殿的蓋爾維孚向你挑戰，要你擊敗『黑暗大師』齊特瑞司。\n\n若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。", description = "許多種族不遠千里而來，只為了在英靈殿裡證明他們自己的實力。有些甚至是從地底下的世界來的。\n\n『黑暗大師』齊特瑞司就是其中一人。\n\n來自地底深處，瘋狂支配之處，齊特瑞司要求和奇人異士在環中決鬥。而你就是不二人選。\n\n你敢面對這個奈幽夢魘嗎，<race>?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13216] = {title = "英靈殿之戰:席格芮‧冰誕回來了", objective = "英靈殿的蓋爾維孚向你挑戰，要你擊敗席格芮‧冰誕。\n\n若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。", description = "你的一個老仇家回來了:席格芮‧冰誕。也許你還記得在蠻荒岩臺上擊敗她的往事?\n\n沒關係，她一定記得你。她堅持要給她個再次證明自己的機會。\n\n就我個人而言，這是另一個復仇的機會，但對這裡同樣也有好處。\n\n我就將場子留給你了，<name>。你願意再次面對席格芮‧冰誕嗎?您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n符刻治療藥水符刻法力藥水\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][13217] = {title = "英靈殿之戰:卡納基!", objective = "英靈殿的蓋爾維孚向你挑戰，要你擊敗卡納基。\n\n若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。", description = "你能走到這一步，真的相當了不起，<name>，但是接下來你在英靈殿中得面對的，是遠遠超出你想像的巨大恐懼。\n\n我該警告你馬上回頭。卡納基是巫妖王邪惡心腹打造而成的龐然血肉怪物。\n\n我不覺得你和你的朋友有所勝算。不過，你有權決定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13218] = {title = "英靈殿之戰:死擊族長", objective = "英靈殿的蓋爾維孚向你挑戰，要你擊敗『死擊』巴納霍格族長。\n\n若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。", description = "你的技術已引起卓頓海姆維酷人的注意，<name>。巴納霍格族長對你有很大的興趣，而且堅持要當你的下一個對手。\n\n如果你認為卡納基很可怕，那你大可以回家去了。巴納霍格族長的外號是「死擊」。我想你應該猜得到這名號從何而來的。\n\n你願意接受族長的挑戰嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13219] = {title = "英靈殿之戰:最後的挑戰", objective = "英靈殿的蓋爾維孚向你挑戰，要你擊敗薩杜瓦爾親王。\n\n若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。", description = "我擔心你的勝利終將導致你的毀滅，<name>。\n\n<要是華爾琪的臉色能更白的話，你會覺得她一臉慘白。>\n\n關於你在英靈殿中的勝利，聲名已遠播至冰冠城塞，擾動了一個你絕對不想面對的敵手。\n\n值此非常時刻，薩杜瓦爾親王已在趕往此處的路上。吉雍納警告你該逃離此地，我實在不能不認同。\n\n你怎麼想?他已在途中。你要在最後一場戰鬥中，面對這個血腥親王嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "抑制歡慶長袍不聞之采胸甲不願之勝護胸不當之功外套您會收到：\n\n"}
MultiLanguageQuestData['tw'][13220] = {title = "將歐拉金拼湊回來", objective = "取得一個絲線捲、以及醫生的切割刀，帶往再活化肉塊聖所，試著利用歐拉金的殘骸將其再活化。一旦工作完成，向黑色守望的黑騎兵阿爾利回報。", description = "我們實在沒時間將歐拉金的軀體拼在一起。幸好，天譴軍團提供你一個作縫補活的好地方。\n\n在血肉作坊的血肉巨人實驗室附近，有個再活化聖所。在那一帶找個絲線捲、一把醫生的切割刀。將歐拉金的軀體帶去聖所裡的大實驗室，然後幹活吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13221] = {title = "我還沒死!", objective = "護送卡瑪洛斯神父至安全之處，並向破天者號上的虔誠的亞柏薩倫回報。", description = "聖光對我微笑。我還沒死於這活生生的夢魘中，但若我不能逃脫，天譴軍團將殺了我，並肢解我的軀體以作為他們『工作』的原料。\n\n我無法獨力做到這件事，我的孩子，唯有藉助你的幫忙，我才能活下來再次對抗天譴軍團。\n\n在天譴軍團的劊子手了結我以前，你能幫助我幫逃出去嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13222] = {title = "護衛攻城行動", objective = "冬握湖的資深爆破兵勒茍索要你駕駛或保護一個攻城器，讓其順利摧毀三個建築物。\n\n士兵階級以上的玩家可於哥布林工坊建造攻城器。", description = "向前向中看齊，<name>!我們就要展開對冬握堡壘的攻擊。那些部落畜生以為可以懦弱地躲在城牆之後?嗯哼，我不認為!我們將讓他們見識到地精科技的威力，並且粉碎他們的城牆!\n\n然而，最具威力的攻城器具也需要人手操作。操作或護衛一台攻城載具，直到它摧毀三座部落建築。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13223] = {title = "護衛攻城行動", objective = "冬握湖的莫普中尉要你保衛或駕駛一台攻城載具，讓其順利摧毀三座聯盟建築物。\n\n有階級的部落玩家可於哥布林工坊建造攻城器。", description = "討厭的聯盟不會佔領要塞太久的。莫普將粉碎他們的城牆，但是莫普得待在營地裡。莫普希望他可以粉碎想破壞部落石毀車的聯盟成員。\n\n你，<name>!你來做莫普的工作。保護3台進攻聯盟建築的攻城載具。聯盟不會想到你會保護石毀車。讓聯盟知道莫普有多聰明!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13224] = {title = "奧格林之錘", objective = "找出搭乘著奧格林之錘，在寒冰皇冠上空盤旋的空奪者寇姆‧黑疤。", description = "銀白十字軍將我飽經蹂躪的身軀，從破碎前線上拉了回來。多麼榮耀的一場戰役，<race>。當它砍下聯盟齷齪小賊和天譴軍團的頭顱時，我的斧頭，它高歌著。\n\n我的時代結束了。對我而言，這將是善終。幫我帶封口信，大兵。\n\n我們的基地遠在天譴軍所及之外-默德雷薩和奧多薩之間的上空。它被稱為『奧格林之錘』。\n\n<賀克徒勞無功地試圖敬禮。>\n\n飛高些，小心避開聯盟的毀滅武器，破天者號。告訴寇姆...告訴他我不行了...奮鬥...為了部落。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13225] = {title = "破天者號", objective = "找出搭乘著破天者號，在寒冰皇冠上空盤旋的提督賈斯汀‧巴特勒。", description = "我們和天譴軍團與部落作殊死戰。將死的哀鳴覆蓋了整個戰場。這實在太折磨人了...慘不忍睹!我的身體匱乏了，精疲力盡地倒下了。銀白十字軍喚醒了我，他們將我從破碎前線上拖下來，帶到了這裡。我不行了。答應將死的士兵一個最後的心願好嗎，<race>?我們的基地，破天者號，正在寒冰皇冠上空盤旋。在那裡你可以找到我的指揮官，提督巴特勒。告訴他，我以聯盟士兵的身分，光榮地捐軀。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13226] = {title = "審判日將臨!", objective = "在寒冰皇冠的銀白先鋒駐地，向大領主提里奧‧弗丁報到。", description = "我們無法獨力擊敗巫妖王。分裂的我們唯有敗亡一途!\n\n我懇求你回應我們的呼喚，<兄弟/姐妹>。銀白十字軍接受所有願意為戰爭奉獻心力的志士。大領主提里奧‧弗丁在銀白先鋒駐地親自等著你!坐上你的坐騎，飛往寒冰皇冠的東南邊境。你可以在那裡找到大領主弗丁以及銀白十字軍的士兵。\n\n去吧，<class>，為了審判日將臨!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13227] = {title = "審判日將臨!", objective = "到寒冰皇冠的銀白先鋒駐地向大領主提里奧‧弗丁報到。", description = "我們無法獨力擊敗巫妖王。分裂的我們唯有敗亡一途!\n\n我懇求你回應我們的呼喚，<兄弟/姐妹>。銀白十字軍接受所有願意為戰爭奉獻心力的志士。大領主提里奧‧弗丁在銀白先鋒駐地親自等著你!坐上你的坐騎，飛往寒冰皇冠的東南邊境。你可以在那裡找到大領主弗丁以及銀白十字軍的士兵。\n\n去吧，<class>，為了審判日將臨!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13228] = {title = "破碎前線", objective = "搭乘著奧格林之錘的寇姆‧黑疤要求你，前往破碎前線並詢問垂死的狂戰士，以了解發生的事。", description = "什麼戰鬥?!那支部隊進行的是偵察任務!\n\n還有聯盟的消息是怎麼一回事 - 你確定他說的是聯盟嗎?\n\n聽我說，<name>!我得知道發生了什麼事，現在!\n\n馬上前往該地，找到解答!搜遍戰場並尋找生還者 - 線索 - 什麼都好!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13229] = {title = "我還沒死!", objective = "護送卡瑪洛斯神父至安全之處，並向奧格林之錘上的凱爾坦修士回報。", description = "聖光對我微笑。我還沒死於這活生生的夢魘中，但若我不能逃脫，天譴軍團將殺了我，並肢解我的軀體以作為他們『工作』的原料。\n\n我無法獨力做到這件事，<class>，除非借助你的幫助，我才能活下來再次對抗天譴軍團。\n\n在天譴軍團的劊子手了結我以前，你能幫助我幫逃出去嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13230] = {title = "替我復仇!", objective = "垂死的狂戰士要求你在破碎前線上殺死5個垂死的士兵。完成後，向奧格林之錘上的空奪者寇姆‧黑疤回報。", description = "我聽到他們的聲音，<兄弟/姐妹>...\n\n聯盟傷兵的哀鳴呻吟...那令我實在不舒服...\n\n完成我們未竟的事業，<class>。不要手下留情...不要留下任何一個活口。\n\n為...為了部落...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13231] = {title = "破碎前線", objective = "破天者號上的提督賈斯汀‧巴特勒要求你，去破碎前線訊問一個垂死的士兵，並回報給他。", description = "什麼?!不...!我們承受了多少的痛苦，只為了維持這回攻擊的低調。部落怎麼可能知道的?裝備...人力...全軍覆沒了嗎?不可能的!\n\n我們在寒冰皇冠的戰略，其關鍵在於比部落先奪下那道門。我們必須盡快重新整備，然後發動另一波攻勢。\n\n查看戰場，搜尋所有的生還者。檢討從這場悲劇中得到什麼教訓。\n\n還有，為了將臨的戰鬥，你得打點妥當，<name>，我們必須兩面作戰...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13232] = {title = "給我個痛快!", objective = "破碎前線上一個垂死的士兵要求你，殺死5個垂死的士兵，並向提督賈斯汀‧巴特勒回報。", description = "他們嘲弄我們 - 就算是躺在這裡等死，也還在嘲弄我們...\n\n拜託，<兄弟/女士>...別讓他們的哀鳴成為我最後聽見的聲音...\n\n給我個痛快吧...讓我從痛苦中解脫...進...入聖光。\n\n找到我的夥伴...給他們同樣的了結。\n\n別留給天譴軍團...任何喚醒我們的機會!\n\n我求你...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13233] = {title = "絕不留情!", objective = "破天者號上的提督賈斯汀‧巴特勒要你在寒冰皇冠殺掉15個部落玩家。", description = "如同我告訴過你的。他們不過是在虛張聲勢。\n\n如同往常地，部落再次蔑視我們視為珍愛及神聖的一切事物。他們該以生命償付違逆聖光的罪過。\n\n無一例外。\n\n想想一個不被他們玷污的世界，<name>。想像我們孩子所能享受的歡愉。想想我們後代對你回憶的敬仰，當他們知道是你帶給他們安穩的幸福。\n\n現在去吧，讓夢想成真!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13234] = {title = "叫他們付出代價!", objective = "空奪者寇姆‧黑疤要你在寒冰皇冠殺掉15個聯盟玩家。", description = "時機來臨了!\n\n我們已經忍受了自以為是的聯盟太久!我們袖手旁邊這世界的軟弱與絕望也太久了。\n\n現在，我們將終止這份恥辱!現在，我們讓他們嚐嚐什麼叫恐懼!現在，我們將榮耀帶給部落!\n\n在寒冰皇冠這裡，我們要碾碎聯盟!\n\n去吧，<class>，追捕他們!碾碎他們。讓他們生不如死!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13235] = {title = "血肉巨人鬥士", objective = "在血肉作坊的西端，與瑪葛瑞弗‧達卡交談與莫比達斯接戰的事宜。擊敗莫比達斯以後，向黑色守望的黑騎兵阿爾利回報。", description = "你在破壞血肉作坊與清除巫妖王的爪牙這件事上做得很好。現在，所有殘餘的部隊，必須一起對付血肉作坊最龐大的成品 -- 名為莫比達斯的血肉巨人。\n\n這可不會是場輕鬆的遊戲，不過，暗影穹殿派了瑪葛瑞弗‧達卡和一些援軍。和他在血肉作坊西邊的最高點碰頭。一旦你準備好進行攻擊，告訴他，他會讓他的部隊加入戰鬥。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "血肉巨人披肩血肉作坊肩墊巨人勇士肩甲莫比達斯肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][13236] = {title = "詛咒軍團", objective = "第一軍團前線營地的米希阿斯‧薩爾奈要求你，喚起100名食屍爪牙，以讓它們加入軍隊。", description = "你大概覺得自己很厲害 -- 打敗這些不死生物，用你的戰爭機器壓碎他們的骸骨。\n\n但這跟創造他們的力量比起來微不足道。\n\n我曾經看過王子殿下親自表演。我可以示範給你看...如果你想的話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13237] = {title = "刺探", objective = "奧格林之錘上的寇爾提拉‧亡織者要你前往破碎前線並擊敗5隻笨重的憎惡體，5位毒惡的死靈法師，與5位暗影菁英。", description = "當你的指揮官由於他對聯盟敵人的嫌惡因而分散注意力時，你可以投靠我，並協助我堅定地面對真正的敵人 - 巫妖王及他的爪牙。\n\n為了把握任何能在城塞中擊敗他的希望，你的人馬必須把守住每道大門。\n\n現在，專注在你的第一要務上。回到前線，並刺探他們的防禦狀態。尋找任何可讓我們趁隙而入的弱點。\n\n我會等你的回報，<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "毒惡死靈法師護符笨重憎惡體皮革披風墮落暗影菁英之戒您會收到：\n\n"}
MultiLanguageQuestData['tw'][13238] = {title = "有什麼好料的?", objective = "奧格林之錘上的空奪者寇姆‧黑疤要求你，與首席工程師銅爪交談。", description = "哥布林!超忙碌的小工作狂...\n\n聽著，<name>。我們的工程師銅爪堅持，要我看某樣他弄到的有用玩意。\n\n我實在沒有心情忍受他的碎碎念。上回我對他打招呼，結果他竟然對我嘮叨了一個小時。我差點沒把他踢下辛德拉苟莎之殞!\n\n你代替我去敷衍他一下。讓我知道他是不是真的弄到什麼鬼玩意。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13239] = {title = "烈不烈", objective = "首席工程師銅爪要求你，在破碎前線上使用銅爪的烈性油，以吸引3頭霜育天爪。\n\n為了使用烈性油，你必須在戰場上收集一個白骨堆、一頂被遺棄的頭盔、和一副被遺棄的盔甲。", description = "從哪開始呢...嗯哼，你一定知道我是這艘船的首席工程師，我也經手過所有的情報 - 對，對，這是真的，我最近注意到你在南方目擊冰霜巨龍的報告，而我也相信，我已經發展出一套對付他們很有效的方案...現在你得走幾步路，不過基本上，你要打造一個沒穿護甲的假人，在上面用這溶劑塗上一大塊，然後趕快找個掩蔽!\n\n...你還在聽嗎，<race>?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "走私犯護腕冰川行者雪地靴天空隊長腰帶群空裝甲手鐲您會收到：\n\n"}
MultiLanguageQuestData['tw'][13240] = {title = "泰彌亞在你的未來預見了離心傀儡!", objective = "達拉然的大法師泰彌亞預見你必須摧毀10個離心傀儡。", description = "汝應前往漂浮於凜懼島上的奧核之眼，<name>。\n\n據余所見，汝應當於該地毀去離心傀儡。余斷言，若汝不能當機立斷地摧毀這些怪力亂神之物，則汝輩必致敗亡。\n\n吾既視之，汝遂應行之。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n祈倫托表揚徽章銀白十字軍表揚徽章黯刃表揚徽章龍眠表揚徽章霍迪爾之子表揚徽章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][13241] = {title = "提迈尔的预言：伊米亚狂战士！", objective = "达拉然的大法师提迈尔要你去杀死7个伊米亚狂战士。", description = "你离胜利只剩一步之遥了。伊米隆国王麾下的勇士们是你唯一的阻碍。\n\n你要深入嚎风峡湾的森林，进入那座名为乌特加德之巅的堡垒。你和你的伙伴必须消灭那些伊米亚狂战士，这对你们至关重要。\n\n如果这次行动失败了，那你们就死定了，<name>！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n祈倫托表揚徽章銀白十字軍表揚徽章黯刃表揚徽章龍眠表揚徽章霍迪爾之子表揚徽章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][13243] = {title = "泰彌亞在你的未來預見了恆龍密探!", objective = "達拉然的大法師泰彌亞預見你必須殺死4頭恆龍密探。", description = "由於恆龍軍團之危害，時間線岌岌可危。若無汝的干預，時間將四分五裂!\n\n汝必須穿越時空，前往時光之穴內的斯坦索姆的抉擇。\n\n洞察所有可能往事之意圖，令余頭痛欲裂，但余可預見，殺死這些恆龍密探為汝之第一要務。\n\n唯有除去所有恆龍，真實歷史方能存留，現在與未來亦不為之擾動。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n祈倫托表揚徽章銀白十字軍表揚徽章黯刃表揚徽章龍眠表揚徽章霍迪爾之子表揚徽章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][13246] = {title = "死亡證明:凱瑞史卓莎", objective = "達拉然的大法師朗達拉克要求你，帶回凱瑞史卓莎的碎心。\n\n這個任務只能在英雄難度中完成。", description = "你對凱瑞史卓莎的故事熟悉嗎?\n\n她是如何地在殺死薩拉苟莎，瑪里苟斯的配偶中扮演著關鍵角色?接著，又如何被瑪里苟斯冰封在一塊冰塊之中，以與他相伴?\n\n我們注意到了，瑪里苟斯正利用他的魔法破壞她的心智。這已使凱瑞史卓莎幾近瘋狂。\n\n<name>，你必須進入凜懼島的奧核之心，在她完全喪失心智之前了結她。\n\n雖然這令我十分難過，但我還是堅持你必須帶回她的心臟，以作為證明。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13248] = {title = "死亡證明:依米倫王", objective = "達拉然的大法師朗達拉克要求你，帶回一個逝去王后的墜盒。\n\n這個任務只能在英雄難度中完成。", description = "俄特加德之巔的依米倫王是最受巫妖王器重的維酷人。光是這個理由就值得殺死他。\n\n再者，倘若他響起戰角號召所有的依米亞與默約丁的領袖，維酷人可能會是天譴軍團裡最難纏的角色!\n\n看你的了<name>，千萬別讓它發生。將他頸上上的墜盒帶回來給我，這樣我就會知道依米倫不再對我們構成威脅。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13252] = {title = "死亡证明：塑铁者斯约尼尔", objective = "达拉然的大法师兰达洛克要你将血肉诅咒圆盘交给他。\n\n该任务必须在英雄难度下完成。", description = "我们对于所谓“血肉诅咒”的情况知之甚少，不过岩石大厅里保存着与之相关的信息。\n\n塑铁者斯约尼尔似乎相当了解这种诅咒。我们有充分的证据表明，他身上有着一块泰坦制造的信息圆盘，上面的信息足以解答我们的所有疑问。\n\n帮我把圆盘拿来，<name>，这样我们就能对血肉诅咒进行研究了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13258] = {title = "大好機會", objective = "在冰冠城塞下，和克瑞佳中士交談。", description = "我們最近得到了一份概要，指出了冰冠城塞的弱點。它圖文並茂地描繪了突破其防線的方式。\n\n上面記載的圖示指出，有個深入地底數百呎的孔道。我們還不明白它的功用，但是根據我們的偵察活動，它顯然對天譴軍團相當重要。\n\n去冰冠城塞底下找克瑞佳中士，她負責帶領對城塞的攻擊行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13259] = {title = "先聲奪人", objective = "冰冠城塞裡的克瑞佳中士要求你，殺死10頭笨重的恐獸。", description = "我們有一擊的機會，在此地造成一些破壞 -- 我們得確保不會失手。\n\n我們有天譴軍團製造的高效薩鋼炸彈。但我們得在安置它們前確保此地的安全。\n\n在他們的援軍來到前，我們得儘快撂倒天譴軍團的防務。\n\n協助我的人馬，一旦煙火秀的前置工作都完成了，回來向我回報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "防震擊護頭笨重恐獸外套瘋狂轟炸機手套冰行者尖刺靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][13260] = {title = "引薦", objective = "空奪者寇姆‧黑疤要求你，和奧格林之錘上的寇爾提拉‧亡織者對話。", description = "儘管我們不該放過任何打擊聯盟的機會，我們也不該忘記天譴軍團。\n\n接下來的幾個星期，我們的數量並不足以在這冰河上發動像樣的攻勢，但我們不會停止對其防務的刺探。\n\n我已向派駐在此的死亡騎士建議讓你也加入行動。畢竟，有誰比他們更了解這些敵人呢?\n\n容我介紹，寇爾提拉‧亡織者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13261] = {title = "烈不烈", objective = "首席工程師銅爪，要你在破碎前線使用銅爪的烈性油，以吸引3隻霜育天爪。\n\n為了使用烈性油，你必須先從戰場上取得被遺棄的頭盔、被遺棄的盔甲與骨堆。", description = "哇呼!成功啦!當然我怎麼可能懷疑自己超乎自然的天才，只是我不太確定應該期待多大的爆炸 - 這麼說吧，我很高興你的眉毛沒有燒焦。我現在只要讓老寇看看你砸那些龍。他只得升我當...當...比首席工程師還高的官兒!你再拿一批那玩意兒然後回去前線，我去叫老寇來...\n\n等什麼?出動啊!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13262] = {title = "炸翻它!", objective = "點燃附近薩鋼炸彈堆的引信。", description = "隨著現在這情況發展下去，局勢很可能會失去控制。我們這樣做吧，<name>。\n\n我需要個人，幫我點燃那些炸彈的引信，看來就是你了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13263] = {title = "一觸即發", objective = "注意不要被落下的殘骸擊中。", description = "在你點燃引信的同時，你發現引線燃燒的速度遠比你想像的快。\n\n這些炸彈馬上就要爆炸了，而你唯一能做的就是向坑洞撲倒，並且祈禱不要摔死。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][13264] = {title = "有夠討厭!", objective = "奧格林之錘上的寇爾提拉‧亡織者要你使用憎惡體再活化工具包創造再活化的憎惡體，並用來殺掉15隻冰結食屍鬼、15隻邪惡的魂屍、15個復活的聯盟士兵。", description = "憎惡體...\n\n可以是很難纏的敵人。我曾經不只一次看過他們逆轉整個戰局。很少人能理解，他們也可以是很可靠的戰友。\n\n他們不太思考。如果你知道他們製造的秘密，你就能夠賦予他們一些基本的指令而他們完全不會質疑你。\n\n算你好運，我知道這些秘密。\n\n這個裝置可以重新活化那些被你擊敗的憎惡體殘骸。拿著它，並學著用他們反擊那些死亡之門的天譴軍團。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "破碎前線軟靴再活化披肩魂屍巡者護腿天譴剋星肩鎧您會收到：\n\n"}
