MultiLanguageQuestData['tw'][24777] = {title = "基本原則:攻擊", objective = "摧毀6個訓練假人。", description = "好吧，兄弟。我們從基本的開始。我需要知道你學會怎麼使用你拖來拖去的那個武器。\n\n去攻擊那些訓練假人。慢慢來。天生好手。我要來看看你的攻擊招數，然後我們就從那裡開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24778] = {title = "猎人的技艺", objective = "将等级提升至3级，学习稳固射击。然后对一个蒂基面具假人使用5次稳固射击。", description = "由于你已经开始掌握这些事情的诀窍，你将会明白如何使用新的技巧。\n\n你要学习的第一件事情是在射击间隙保持手臂的稳定，否则如果气力不济，将很难杀死很多敌人。\n\n多锻炼一下吧，明白之后再回来找我，然后向我演示。当你认为自己已经明白时，记得告诉我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
