MultiLanguageQuestData['tw'][24809] = {title = "Healer Ring Flag", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24810] = {title = "Melee Ring Flag", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24811] = {title = "Caster Ring Flag", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24812] = {title = "不再留情", objective = "殺死12個惡鱗納迦。", description = "納迦對我們族人犯下許多暴行。事到如今，我們不會再手下留情。\n\n進入洞穴，見到納迦就殺。今天每死一個納迦，都代表日後少一個納迦偷襲我們。我相信你一定會徹底執行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "殘忍手套冷凝聚焦護腿惡鱗胸甲惡鱗束褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][24813] = {title = "土地神像", objective = "將8個土地神像放置在惡鱗旗幟上。", description = "這次可不是普通的反擊。我們下定決心要剷除這裡每一個納迦，還要竭盡所能，保證他們永遠不敢再回來。\n\n我要你進入他們的洞穴，將這些神像放到裡頭任何一面惡鱗旗幟上。這可以讓他們明白自己有多麼不受歡迎。不僅如此，神像的魔法可以大大削弱每個接近的惡鱗納迦，看他們還想不想留下來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24814] = {title = "古老的敵人", objective = "到惡鱗灣找沃金說話，並協助他殺死海巫札爾基拉。", description = "海巫出現了，就在這座島的最頂端。我們等待許久，就是為了這次復仇的機會。你將有這個榮幸參與這件大事。\n\n到東北方的山坡上與沃金見面。準備好戰鬥時就告訴他。您會收到：\n\n", progress = nil, completion = nil, rewards = "海巫護腕逝友足跡朱尼的傳家寶惡鱗踏靴您會收到：\n\n海巫的背包"}
MultiLanguageQuestData['tw'][24815] = {title = "擇你所向", objective = "To atone for the sins I committed as one of the Lich King's Death Knights, I've dedicated myself to creating rings of great power for our brothers and sisters to use in the struggle.\n\nYou've proven yourself as a valuable ally in the fight against the Scourge, <name>. As your dedication continues I can improve on the ring's original design.\n\nChoose your path carefully. A change of heart will come at a price.", description = nil, progress = nil, completion = nil, rewards = "勇武灰燼指環報復灰燼指環毀滅灰燼指環智慧灰燼指環力量灰燼指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][24816] = {title = "現在誰站在食物鏈頂端啦?", objective = "收集5份鯊魚碎塊。", description = "好吧好吧，也許這個蛋的事情不是很成功。那來點鯊魚肉如何?\n\n只是有個小問題。嗯，其實是個大問題，很大的問題:大錘子!\n\n當然囉，我有個很棒的主意。游到西邊的恐怖海峽去，給我們弄一些鯊魚的身體部位來。將這些鯊魚碎塊交給我的助理格里利。我太重要了，不能光為了這些小事弄髒手。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24817] = {title = "鯊魚腹中的哥布林", objective = "使用機械鯊魚噴射X控制器並利用機械鯊魚噴射X殺死大錘子。", description = "結合了機械小雞和這些鯊魚身體部位，我們組合出了歷史上最偉大的戰鬥潛艦:機械鯊魚噴射X!\n\n荷巴爾特和我希望由你來駕駛它，<name>。進入西邊的水域並使用機械鯊魚噴射X控制器。\n\n你必須殺死大錘子，我們才有辦法盡最大限度去利用恐怖海峽裡面的天然資源!這是為了污水企業聯合著想。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "機械小雞殘骸護腿錘頭您會收到：\n\n"}
