MultiLanguageQuestData['tw'][24897] = {title = "回到鎮上", objective = "到失落群島上的盒中鎮和賽希‧硬心談話。", description = "我們搞錯了。準備要攻擊我們的並不是納迦...而是附近的烏姆拉部族。\n\n<name>，你得返回盒中鎮。那些俾格米已經開始攻擊了!\n\n來，帶著這個。我們從一個俾格米侏儒族手中買來的，據說這曾經屬於他們某個偉大的領袖，那傢伙的名字翻譯過來應該是暗棕盔帽。\n\n那樣應該能騙到他們，讓他們不會攻擊你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24898] = {title = "Going, Going, Guano!", objective = "Bring 1 pile of Kraul Guano to Zan'do at Firestone Point.", description = "There be more in the Razorfen than just pigs, <bruddah/sistah>. There be bats as well...and if you're goin in there and rilin' up the quilboar anyway, I want ya to bring me back some guano.\n\nYah, guano. The droppin's. Don't give me that look. It be foul, but powerful, primal stuff for rituals...rituals to keep the earth 'round here strong enough to keep from rippin' apart under all the damn fools warrin' round here.\n\nJust bring Zan'do one pile of guano, yah?完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24899] = {title = "Going, Going, Guano!", objective = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", description = "As you can see, <name>, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a <class>. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24900] = {title = "Blueleaf Tubers", objective = "In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers to Mebok Mizzyrix in Ratchet.", description = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一小袋寶石"}
MultiLanguageQuestData['tw'][24901] = {title = "盒中鎮:遭受攻擊", objective = "操作B.C.殲滅者擊敗30名烏姆拉戰士。", description = "<name>，請保護我們!\n\n我派了些蛋頭科學家去部署城鎮的防禦砲火，但那些烏姆拉戰士彷彿源源不絕。\n\n移動你的屁股，進入一台B.C.殲滅者，解除城鎮的俾格米威脅吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "迷你B.C.殲滅者盒中鎮盒蓋碎片您會收到：\n\n"}
MultiLanguageQuestData['tw'][24902] = {title = "獵殺希瓦娜斯", objective = "跟隨托比亞斯‧密斯特曼托去追捕希瓦娜斯。\n\n若你跟丟托比亞斯，回去跟羅娜‧克羅雷談話，可以再次呼喚他幫忙。", description = "所以，是真的了?吉爾尼斯失去了它的天之驕子。\n\n我們會為此哀悼，但會是在這一切結束之後。\n\n敵人依舊正在呼吸著吉爾尼斯的空氣，我們沒有時間去哀痛。\n\n只要等我找到女妖之王的蹤跡，我父親的人馬隨時可以發動攻擊。準備好時告訴我。黎姆的仇該做個了結了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24903] = {title = "復仇或求生", objective = "在吉爾尼斯城的葛雷邁恩宮廷和吉恩‧葛雷邁恩國王談話。", description = "告訴葛雷邁恩我們派了追跡者去跟著希瓦娜斯，也把瘟疫的事告訴他了。\n\n要怎麼做由他決定。是要對被遺忘者的領袖發動全面攻擊，或是試著疏散我們的倖存者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24904] = {title = "吉爾尼斯城之戰", objective = "為吉爾尼斯城取得勝利。", description = "是時候了，<name>。我們已將吉爾尼斯中所有可用的人力集結起來並完成武裝。\n\n是時候去和敵人面對面了。該去和希瓦娜斯與她那些被遺忘者走狗算算總帳了，徹底結清。\n\n黎姆會從這個大門率領攻擊部隊出去。葛雷邁恩國王與我父親則從其他地區發動攻擊。\n\n你也在這場行動中扮演一個重要的角色。帶著這把細劍，在戰鬥中用細劍提振我方的士氣。去和卡瑞南‧阿拉納斯交談來加入吉爾尼斯城的戰爭。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "集結之尖號召披風集結衝鋒吉爾尼斯之盾鮮血代價釘錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][24905] = {title = "報答", objective = "到砂槌營地尋找梅格斯‧驚懼伐木機。", description = "你知道嗎，當你不在的時候，梅格斯來過這兒。我已經好幾個月沒見過她，不過她也很少給我好日子過，她只是要我告訴你，有更多生意要忙了。\n\n她說她正要去砂槌營地，開個店鋪，好像跟巨魔有關的。既然這兒的工作都做完了，你說不定可以到那裡去...我可不敢讓她這樣的哥布林等太久。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24906] = {title = "海濱撈寶", objective = "收集7個熱砂補給物資。", description = "要是我們想要有競爭力的話，現在就要趕快往市場去。我對這處境有另一種看法。\n\n加基森被海盜封鎖，但是有大量從船上掉出來的貨物好好地保存了下來...只是被沖走了而已。大部分都沖到這個鎮南邊的淺攤那。\n\n到那裡去開始挖寶;有很多裝滿好東西的貨箱漂浮在那附近。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24907] = {title = "踏浪", objective = "殺死8個逐潮者。", description = "事情是這樣的。如果我們想在加基森建立起污水企業的市場，就必須為這個地方做點什麼。\n\n新的海岸線對生意很有利，但也同時帶進了海巨人。他們又大又噁心，讓地值下滑。\n\n到城鎮南邊的淺灘，能殺幾個巨人，就殺幾個，我會把一些利潤分給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24910] = {title = "火箭救援", objective = "將救生火箭交給5個熱砂倖存者，並使用炸彈殺死40個南海攔路者。", description = "好吧，<name>。雞毛蒜皮的瑣事已經做得夠多了，該是做筆大生意的時候了。\n\n熱砂港廢墟還有一群不幸的熱砂哥布林正等待救援。他們每個都是潛在的顧客。海賊把炮火對準每艘從這裡出港的船…所以我說，飛過去吧！\n\n城鎮外的碼頭停著一艘熱氣球，我們可以好好利用它。跳上熱氣球，我會趕上你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "娜絲米菈的攪湯棍未爆彈回收的熱砂頭盔不成功的救生火箭原型您會收到：\n\n"}
MultiLanguageQuestData['tw'][24911] = {title = "熱帶天堂的呼喚", objective = "到安戈洛環形山的馬紹爾觀測站向威利德‧馬紹爾回報。", description = "嘿，你看起來像是個挑剔的冒險者。想要來點與眾不同的嗎?帶有異國風情的?有些...賺頭的?\n\n先把你靴子裡的沙清一清吧，因為我有個提議。威利德‧馬紹爾正在尋找像你一樣可靠的傭兵。他在馬紹爾觀測站紮了營，位置就在茂密蓊鬱的安戈洛環形山中央那座火山的東南方。\n\n不過話說回來，天堂可不是每個人都待得住的，<race>。就看你自己決定了。熱帶綠洲等著你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24912] = {title = "強化儀式", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24913] = {title = "記住聖光", objective = "幫隱士艾弗恩向瑪格圖爾道別。", description = "瑪格圖爾每分每秒都變得更加虛弱，<name>。我的藥劑已經準備好了…一定要有效。一定要！\n\n你為我們倆做了這麼多。要是你能留下來和我們一起度過瑪格圖爾最關鍵的一刻，我會倍感光榮。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n光之擁\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][24914] = {title = "私人財產", objective = "把密封的箱子帶給在冰冠城塞的大領主達瑞安‧莫格萊尼。\n\n已提供物品：\n", description = "你在這個盒子上找不到機關或縫隙。如果不是裡面有東西在晃動，很容易就把它錯認為一整塊固體金屬。\n\n如果說有人知道開啟它的方法的話，那非大領主莫格萊尼莫屬了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n開封的箱子"}
