MultiLanguageQuestData['tw'][24924] = {title = "烏姆拉村", objective = "在失落群島上的烏姆拉村和伊茲談話。", description = "俾格米侏儒族把大部分的人帶回他們村裡去了。誰知道他們打算做什麼邪惡的事?\n\n<name>，你得在俾格米侏儒族的傢伙對俘虜用些什麼巫毒之前，過去那裡釋放他們!\n\n伊茲已經到了東南方的烏姆拉村附近。至於接下來該幹些什麼，她會為你做個簡報。\n\n你的俾格米盔帽看起來有些破爛，但應該足夠你到達那邊了。\n\n希望啦。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24925] = {title = "解放俘虜", objective = "解放5名哥布林俘虜。", description = "他們從我們這邊擄走一票人。我知道他們在對那些人進行奇怪的儀式。好像是在從他們身上抽取生命的能量!\n\n你得在一切都還來得及之前進去村莊解救那些俘虜!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24926] = {title = "服務艾米01", objective = "把艾米的隨身碟帶去安戈洛環形山的苔蘚堆，交給卡爾納‧雷姆塔維爾。", description = "你好。我是單位艾米01。你...<race>?\n\n艾米研究原生大猩猩的任務成功了。艾米取得卡爾納需要的數據資料。\n\n但是艾米01不回去。艾米現在有新家庭。這裡，跟猩猩一起，艾米要留下。\n\n<艾米01從手中拆下一個小裝置並交給你。>\n\n你帶數據資料回去給卡爾納。你告訴她發生甚麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "卡爾納的斗篷雷姆塔維爾思緒軟帽機械猩猩胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][24927] = {title = "死人的箱子", objective = "殺死任何15位南海掠劫者。", description = "寶貝，你看，你應該能夠很容易的看出現在發生甚麼狀況。這邊是海盜，那邊是哥布林，而哥布林目前與海盜在鬥爭。有些很可悲的小地精也在努力地攻擊海盜。\n\n我簡單的跟你說吧:我們必須要砍殺很多海盜。就這樣去做吧，好嗎?我們終究不希望地精砍殺的比我們多。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "南海兜帽迪羅特的護腿烙紋手套潔淨肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][24928] = {title = "燒成灰!", objective = "將西北方、東南方、和東北方的草屋點燃起火。", description = "我已徹底評估過這裡的房價，很不幸的它的市場價格實在是低到無法對我們有甚麼用處。我們還是得重新裝潢。\n\n幸運的是，我對縱火還有幾分了解。希望你也是!朝著那些骯髒又快倒塌的破草屋丟幾瓶著火的萊姆酒吧。\n\n試著不要站在下風處。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24929] = {title = "殺雞儆猴", objective = "殺死英格威。", description = "烏姆拉族領導者英格威的力量太強大了，我們不能放他活著。他就在跨過繩橋的村莊西側高地，鬼吼鬼叫著對他的手下下令。\n\n過去那裡殺死他，以免他派剩下的村人來對付我們。\n\n小事一樁!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "英格威的外衣俾格米披風烏姆拉法杖英格威外套您會收到：\n\n"}
MultiLanguageQuestData['tw'][24930] = {title = "順路為之", objective = "殺死5隻血牙狼人。", description = "如果葛雷邁恩國王想要你冒生命危險解救一名眾所週知的叛徒，我也不介意。\n\n幫我個忙，在你出去時做點有用的事，殺死這些該詛咒的臭蟲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "阿姆史特護腕商人護胸阿姆史特束腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][24931] = {title = "凝視者標示", objective = "從晶鱗凝視者身上取得5個水晶之眼。", description = "你正要去狩獵土狼，是嗎?要是你不介意，我倒是有個請求。我需要北方那些晶鱗凝視者的眼珠。牠們的眼珠含有很棒的晶體，對...收藏家而言，極具價值。\n\n你可能聽說過某些可悲的傢伙用它們來提升自己的通靈能力，不過我向你保證，我這純粹是學術上的興趣!\n\n幫我帶一些回來，我會好好犒賞你。至少一定比那些小氣的哥布林還大方!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24932] = {title = "降低損失", objective = "到大裂口殺死任15隻哈札里異種蠍。", description = "我上週全都在研究該怎麼利用洞裡這些危險凶暴的節肢動物賺錢。現在我已經江郎才盡，也餓壞了。\n\n這些東西一點用都沒有，我說該是把他們全清掉的時候了。到洞裡去開始殺蟲吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24933] = {title = "沙漠之雞", objective = "收集6塊土狼肉。", description = "我有個點子，不過我們需要一個誘餌。\n\n前幾天我看見一隻瘋狂的皰爪土狼不小心走到裂口邊緣，突然不知從哪飛來一隻異種蠍，幾乎將土狼一口吞下!真是可怕的景象。\n\n顯然我們需要的是土狼肉。去收集一些來，一定要是新鮮的，然後帶回這裡。營地北方應該有很多。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24934] = {title = "擊退登船者!", objective = "和奧布里上將說話以飛上黑池號消滅6個暴吼老水手。", description = "<name>，大海是我們唯一的生命線，現在我大部分的艦隊要不是駛回塞拉摩維修，就是沉沒在這個海灣底生鏽。只有黑池號號還浮在海上保衛我們的港口。\n\n但我剛剛接到通知，敵人已經登上了！\n\n你準備好後告訴我，我會讓我們的海軍獅鷲獸把你放在甲板上。滅了那些膽敢攻擊我寶貝船的暴吼老水手，並向費雪上尉報告以取得進一步的命令。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24937] = {title = "解決烏姆拉", objective = "到失落群島上的盒中鎮和賽希‧硬心談話。", description = "<name>，你得回去盒中鎮，警告他們火山口那些哥布林殭屍的事!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24938] = {title = "北方城堡之砲", objective = "和砲手斯密瑟說話。", description = "費雪上尉從下方給我們發了信號。部落艦隊正在讓部隊登陸?我們不能讓他們從海灘夾擊我們的側面。\n\n我已經派出我們兩個最好的砲台手下去防衛灘頭。下到海灘那裡和砲手斯密瑟說話。\n\n你得經過一番戰鬥穿越庭院才能抵達那裡。看看你能否在下去的路上幫助其他人防守要塞!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24939] = {title = "耗盡槍枝", objective = "使用北方海岸砲台消滅10艘暴吼小艇。", description = "我們有足夠的裝備，但是沒有足夠的人力，<name>。使用海岸這裡的其中一座臼砲，解決掉那些靠近的船隻!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "臼砲手的腰帶北方城堡護腕斯麥瑟的戒指臼砲手的腰環您會收到：\n\n"}
MultiLanguageQuestData['tw'][24940] = {title = "火山之上", objective = "到失落群島上的失落山峰和交叉檢驗教練談話。", description = "我們有一群人上去火山頂端進行救援和反攻行動了。失落山峰上有些恐怖的事情正在醞釀。\n\n他們在等你到達之後才會對俾格米侏儒族展開行動。那些邪惡的小東西把我們很多人變成殭屍了。\n\n救救我們，<name>!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24941] = {title = "蘭格里奇的子彈", objective = "收集15顆蘭格里奇的子彈。", description = "<class>！感謝聖光！他們幾乎要把我們逼回碼頭上了。中庭被敵人淹沒了！\n\n我們的砲彈已經打光了，而且獸人正準備攻上山丘。我們必須就地湊出一些土製彈藥，而且要快。\n\n快點，進去那座破塔，把尖銳的金屬物品全都拿出來，什麼都好！不管是刀子、叉子還是釘子都可以！隨便抓一把塞進火砲裡！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24942] = {title = "超級增壓火箭靴大戰殭屍", objective = "用超級增壓火箭靴殺死50名哥布林殭屍。", description = "剛剛路上遇到的那些殭屍，和前面道路另一邊的那一大票相比根本不算什麼。如果我們不儘快解決他們，俾格米侏儒的巫醫就會派他們來攻擊城鎮，到時就算有下面那些大砲，也無法解決那麼多!\n\n我帶來了一雙伐木機靴。格里利把它們做了些調整，現在它們是超級增壓火箭靴啦!\n\n用火箭靴把東邊那座兀斯坦村莊裡的殭屍全部燒成灰!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "S.B.R.B.原型1號S.B.R.B.原型4號S.B.R.B.原型2號S.B.R.B.原型3號您會收到：\n\n"}
MultiLanguageQuestData['tw'][24943] = {title = "收復庭院", objective = "殺死10個暴吼蠻兵。", description = "就是該那樣來掃平山丘上的敵軍啊。那些屍體上插滿了刀叉!\n\n暴吼氏族破壞了城牆，但我們還是有機會扭轉戰局。走下山丘，並幫我們的人守住庭院後方...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "帕克斯頓的腰帶搶來的暴吼披風庭院戰利品充公的暴吼手環您會收到：\n\n"}
MultiLanguageQuestData['tw'][24944] = {title = "重回戰場", objective = "在6名受傷的防衛者身上使用草藥浸泡過的繃帶。", description = "這場戰鬥還沒結束，<class>。不會就這樣結束的。\n\n庭院裡有一些士兵一息尚存，我們可以救活他們!我用以前在吉爾尼斯經常使用的一種草藥浸泡了這些布料。它的氣味聞起來很可怕，但是這種藥幾乎連死人都可以救活。把這些繃帶用在那些倒在庭院裡的防衛者身上，看看我們是否可以讓他們重新回到戰場。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24945] = {title = "三隻小俾格米", objective = "殺死嘎爾、瑪爾摩、泰洛須。", description = "聽著，我覺得能夠消滅那麼多殭屍是很好的事，即使他們是我們的朋友和親人。但你不覺得我們也該解決製造他們的那些俾格米嗎?\n\n在北、南、東兀斯坦三個村莊裡有三個巫醫:嘎爾、瑪爾摩、泰洛須。\n\n也許你能去解決他們?我不想要被變成殭屍!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "巫醫護腿魏斯坦護腕巫醫裹腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][24946] = {title = "搖滾粉末", objective = "收集5勺搖滾粉末。", description = "我承認這些俾格米矮子有個優點...他們確實知道該怎麼狂歡!不過他們沒那麼聰明。我想我已經發現了他們搖滾能量的來源:搖滾粉末!\n\n看來這些粉末不只能把他們變成世界級的嗨咖，還具有高度的爆炸性。我們一定要得到那玩意!\n\n所以，當你在東邊的兀斯坦那裡的時候，別忘了要撿一些粉末回來。相信我，接下來你會需要用到它的!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24947] = {title = "氣勢", objective = "到落帆海灣與梅格斯‧驚懼伐木機碰面。", description = "我們不能因為一點殊榮就懈怠了，寶貝。要趁勢追擊!人們都在談論我們。\n\n只不過他們也在談論那個腦袋空空的地精，凱爾希，不巧她就在我們身邊，搶我們的生意。我們必須有所行動，才能把她趕出這個原本就屬於哥布林的城鎮。\n\n我們要幫加基森徹底解決海賊麻煩。到南邊的落帆海灣，我會在那裡跟你碰面。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][24948] = {title = "解除封鎖", objective = "使用帕克斯頓的火炬燒毀3台暴吼投石車和1台暴吼刀刃發射器。", description = "只要暴吼和他的手下繼續開火，我們就沒辦法重建堡壘城牆的防線。我需要你殺出一條穿越裂縫的路，然後去解決那些大砲。\n\n獸人喜歡用煤焦油來幫他們的大型機具加料，這讓那些東西更容易著火。拿著我的火炬去把北方沿途所見的每一台投石車都燒掉。\n\n然後再把暴吼營地內的大型刀刃發射器給燒了!我們有太多人死在那些玩意兒手中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24949] = {title = "寶藏任務", objective = "收集10件海賊寶藏。", description = "我們不要當個浪費的人，寶貝。這些海盜身邊擺了數以噸計的貴重東西，等著被人買賣。你能相信他們竟然只是坐在這些東西上面嗎?\n\n我的意思是，如果只是要堆在那邊，那為何要大費周章的去拿呢?偷搶來的東西就應當賣掉，然後拿去買又新又亮的東西。\n\n不管怎麼說，當個可愛的人，當你在外面砍頭時，盡你所能地拿走他們搜刮來的物品。別了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24950] = {title = "恐鬍船長", objective = "殺死恐鬍船長。", description = "好吧，寶貝，這裡有個更大的挑戰給你。\n\n我們發現了南海海賊的船長在南邊的一艘船上;是南邊，而不是我們幾個小時以來死命追趕的那艘。他洋洋得意又平心定氣坐在那裡，看著我們在這裡戰鬥。\n\n我就饒過你，不跟你說「惡意收購」的笑話了。快上他的船將他打得落花流水，然後我們在這就完事了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "調情長袍恐鬍扼殺手套調查員的腰帶坐立難耐長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][24951] = {title = "絕妙點子", objective = "使用私酒商蟲餌捕捉一隻哈札里群居蠍。", description = "現在有了一堆新鮮肉塊，我們只要將它綁在繩子上...你就可以去幫我抓來一隻異種蠍。\n\n怎麼?別給我擺那副表情，這絕對安全。呃，大致上是安全的。好吧，你可能會死得很痛苦。不過這很容易!只要把肉丟出去，等一隻蟲撲向它，就用繩子把他拉回這兒!\n\n找一隻群居蠍下手。我還沒見過其他種蠍子對土狼感興趣，你可以在蟲巢外圍找到許多群居蠍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24952] = {title = "火箭靴之旅", objective = "使用添加了搖滾粉末的火箭靴前往荷巴爾特‧繫錘那裡。", description = "你需要取得那些鞋子然後進入到火山口去找荷巴爾特‧繫錘。\n\n現在這鞋子摻了一些剩下的搖滾粉末，這個推進力道應該發射一次就足夠把你送到目的地。\n\n當你準備好後就啟動這雙鞋子吧。別擔心，這鞋子會自動讓你安全降落的。\n\n我覺得啦。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24953] = {title = "只是清除害蟲", objective = "找納里安‧柔想說話，並引導受到心靈控制的蟲群進入大裂口蟲巢。", description = "現在該是我的計畫發揮作用的時候了。我們得將捉到的蟲子和炸藥綁在一起，看他能揹多少就綁多少，再靠著柔想驚人的精神力量，我們會控制那隻蠢蟲走到地下蟲巢的正中央。\n\n然後...碰!什麼蟲都沒啦!\n\n你是何其榮幸能夠指揮這隻醜八怪。去找納里安說話，裝備好你的蟲蟲夥伴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "大裂口墜飾幾近驚奇手套靴磨長靴私酒商腿鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][24954] = {title = "烏龜神之子", objective = "收集5個火焰腺體。", description = "火岩諾斯是住在那些土人所崇拜洞穴裡的烏龜神。\n\n牠並不是真的神。\n\n<荷巴爾特轉動著眼珠子。>\n\n但牠夠強了，我得利用我們唯一剩下的火箭靴為你設計一個新武器。\n\n我想老諺語說的「以火制火」符合這種狀況。而且，我喜歡玩火!\n\n從火岩諾斯的子孫那裡取得火焰腺體。那應該能給我足夠的時間去把火箭靴調整成更適合的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24955] = {title = "未經許可", objective = "收集10個砂槌巨魔的權狀簽名。", description = "就像我說的，我正試著讓這些砂槌巨魔加入部落，並成為污水企業便宜的本地勞工。\n\n要促成這件事，我們必須費盡唇舌通過整個入盟過程和一些有的沒的，否則我就會落人口實。我已經擬好權狀，還將入盟儀式附在限時勞動契約裡。\n\n我已經幫你準備好一套偽裝，快穿上去，把名字簽一簽。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24956] = {title = "消滅暴吼", objective = "殺死4名暴吼中尉以及卡加‧暴吼，並取回卡加的頭盔。", description = "我之前碰過暴吼部族，<name>。帶領他們的不是一個獸人，而是一個怪物，一個不懂得絲毫禮儀或憐憫的戰爭惡魔。我們一定得將他和他那些中尉除掉，這不只是為了拯救北方城堡，也是為了整個艾澤拉斯著想。\n\n卡加‧暴吼戴著一頂頭盔。宰了他，<class>，然後把他的頭盔帶來給我。這件事...有特別重要的意義。\n\n暴吼的營地就在東邊，穿過裂谷就可以看到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "陣亡同袍的長靴暴吼戰利品您會收到：\n\n"}
MultiLanguageQuestData['tw'][24957] = {title = "森提帕爾派對", objective = "從森提帕爾異種蠍身上取得20個森提帕爾蟲塊。", description = "好了，寶貝。就像我說的，那些巨魔笨蛋還不知道自己簽下了什麼。現在我們得讓他們跟我們一起走，所以必須取得某種所謂的當地美味。\n\n我是說，讓笨蛋流口水的當地美味。\n\n到西邊的腐化之巢去，那裡到處是危險的異種蠍。殺一些森提帕爾異種蠍，把蟲塊帶回來，讓我們可以拿去送給他們，好嗎?再會。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24958] = {title = "火岩諾斯!", objective = "用靴箭筒殺死火岩諾斯。", description = "花了一點血汗和淚，但靴箭筒(專利申請中)已經準備好了!\n\n這些該死的俾格米傢伙在拿我們的同胞餵他們的「神」火岩諾斯，還打算釋放它來攻擊我們的城鎮!\n\n你得趁一切還來得及時，進去洞穴裡殺死那個傢伙!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "救援繩梯救命天梯腰環您會收到：\n\n"}
MultiLanguageQuestData['tw'][24959] = {title = "新出墳土", objective = "到提里斯法林地的喪鐘鎮墓地向管理員摩爾多回報。", description = "<name>!\n\n<name>，起床!\n\n歡迎回到生者的領域。藉由黑暗女王的祝福與力量，我將你從死亡的掌握中解放出來。\n\n你不是奴隸，<name>。你可以自由選擇你今後要走的道路。如果你選擇侍奉希瓦娜斯‧風行者女士，我建議妳去和管理員摩爾多說話。他就在我身後的墓地裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24960] = {title = "甦醒", objective = "和治安官雷德帕斯、莉莉安‧佛斯、瓦德雷‧莫萊談話。", description = "王者，農民，或是<class>...不管過去你是何人，我都不在乎。我只需要有個會講話的傢伙。\n\n從死裡復活是很費勁的。不是每個人都應付得像你一樣好。特別是，有三個新復活的不死族正好在應付這件事情上遇到了麻煩。\n\n我要你找到他們並和他們說話。或許他們只是需要某個能了解他們的人。\n\n你可以在這墓地裡找到他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24961] = {title = "墳墓的真相", objective = "到喪鐘鎮的大旅店裡找到莉莉安‧佛斯。然後和她談話，給她看艾蕾絲的手鏡。", description = "稍早之前，我看見一名年輕的被遺忘者女性跑向那間老旅店。她在高喊救命，懇求誰來帶她回家。\n\n在我們之中並非每個人都像其他人一樣堅決，<name>。儘管如此，如果我們想挺身和企圖殺倒我們的敵人對抗，便得接受自己身為亡靈的命運。\n\n帶上我的鏡子，拿給那名年輕的女性看。她得了解自己的真正身分，然後加入我們的行列。除此之外...我們用得著我們所能取得的每一具「屍體」。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24963] = {title = "好心地槌下去", objective = "在削弱8個砂槌巨魔後，把小份污水企業聯合促銷美食交給他們。", description = "好的，寶貝，聽著。要人幫你辦事有兩種方法。你可以提供商品、服務，或是其他人們想得到的東西...或者你也可以把他們揍到眼冒金星。\n\n我發現雙管齊下是最有效的，想必你對這兩種方法都很熟悉了吧。拿著這些異種蠍點心，去把巨魔揍暈，在你打死他們以前，把點心給他們，好嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24965] = {title = "魔法训练", objective = "将等级提升至3级，学习冰霜新星。然后对一个训练假人施放2次冰霜新星。", description = "咱们先把正事办了吧，怎么样？\n\n随着你的力量不断提升，你与奥术之间的联系也在不断加强，由此你可以习得新法术。\n\n等着瞧吧。去多积累些经验，然后回来向我展示一下，你都学到了些什么。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24968] = {title = "黑暗的魔法", objective = "将等级提升至3级，学习腐蚀术。然后对一个训练假人使用5次腐蚀术。", description = "随着你继续沿着术士之路成长，你会开始听到邪恶力量的低语……他们会揭示他们的秘密，传授新法术给你。\n\n我想看到你学会一门新法术，并拿这里的训练假人来练练手。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24970] = {title = "和殭屍沒兩樣", objective = "到提里斯法林地的喪鐘鎮找達納爾報告。", description = "當你在洞穴裡面的時候，你的好朋友達納爾帶來了一些警訊。\n\n自從華爾琪到來以後，我們看到越來越多的不死族不願意加入我們黑暗女王的旗下。他們聚集在此地山谷中一個小營地裡，現在他們已經變成有組織的軍隊了。\n\n他們打算攻擊喪鐘鎮，<class>。\n\n達納爾就在東方道路的另一頭。小心，<name>。儘管那些不死族並非徹底的喪失心智，但他們還是一群頭腦有問題的傢伙。您會收到：\n\n", progress = nil, completion = nil, rewards = "被遺忘者短劍被遺忘者匕首被遺忘者木槌被遺忘者重劍您會收到：\n\n清涼的泉水"}
MultiLanguageQuestData['tw'][24971] = {title = "突襲腐腦營地", objective = "殺死治安官雷德帕斯和8名腐腦不死族。", description = "當你在幫執行官阿倫處理事情的時候，我去執行了一項個人任務。暗影牧師薩維斯要我去窺探腐腦營地。\n\n那裡會被稱為腐腦營地是有原因的。\n\n他們的領袖叫做治安官雷德帕斯，他是個不折不扣的野獸。\n\n聽著，<name>...攻擊行動開始了。你比我更適合作戰。去那裡幫助我們的戰事!\n\n當你完成後，到教堂去和暗影牧師薩維斯碰面。祝你好運，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "亡靈守衛圓盾執行官法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][24972] = {title = "重要情報", objective = "將血色十字軍文件送去提里斯法林地的考斯頓莊園給亡靈守衛希米爾。", description = "<薩維斯從他的長袍中拿出了一張紙條。>\n\n這些東西必須交給我的戰場密探，亡靈守衛希米爾。這份情報包含了血色十字軍最近的出沒地點和藏身之處，我們將一勞永逸的消滅血色十字軍。我覺得你可以在這方面大展身手。\n\n沿著這條路向北走出喪鐘鎮。一進入提里斯法，你會看到一座大莊園。希米爾就在裡面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24973] = {title = "夜行蜘蛛洞穴", objective = "殺掉8隻小夜行蜘蛛和5隻夜行蜘蛛。", description = "我們最重要的一項任務就是獲取賴以生存的自然資源。即使在當年聯盟最鼎盛的時候，黃金資源也是非常缺乏的。\n\n這裡的西邊有一處金礦，但是那裡蜘蛛橫行。我們需要礦坑裡的資源，但卻根本無法進去採掘。我手上沒有人可以完成這項任務，所以我們只能一步一步慢慢來。\n\n過去那裡，看看你能幫我們做些什麼吧，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "麻布外衣殭屍皮護腿粗厚鎧甲外衣夜行蜘蛛之弩廢棄的礦工束褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][24974] = {title = "無盡的寂寞", objective = "在耳語海岸將魚人鍊繩使用在一隻邪鰭魚人身上，然後將它帶回考斯頓莊園交給塞德瑞克‧考斯頓。", description = "你的一生都在努力地工作，結果呢？被一場瘟疫殺死了。然後你在不死的生命裡更努力的工作，得到了什麼呢？錢，是啊，還有一座帶著麻煩的莊園，但是樂趣呢？沒有多少。\n\n我這老年的日子過得很寂寞，<name>。我需要一個同伴。去西北方的耳語海岸，把這條鍊繩套在其中一隻魚人身上。那樣做之前你必須先削弱牠的力氣。然後把牠帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24975] = {title = "悲傷之地", objective = "從提里斯法林地的索利丹農莊偷回10顆南瓜。", description = "看看誰來了？你看起來還是個菜鳥<class>。如果你想向黑暗女王陛下證明自己，就得先學會被遺忘者的行事方式。\n\n在這裡的西邊你會找到一個農場。人類充斥在那塊土地上，就像感染屍體的黴菌一樣。更糟糕的是，那些血色十字軍會從他們的哨塔出發，巡邏著那一帶。給這些渣滓們好好上一課吧，把他們的寶貝南瓜偷10顆回來。\n\n一旦偷到10顆南瓜時，把它們帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24976] = {title = "變化是死亡的香料", objective = "收集4株髓瓣，4株薩維倫之棘，以及8個鹹水海參。", description = "這些南瓜是有用處的，<class>。它們將被用來散佈我最新發明的瘟疫，一種既痛苦又致命的混合物。然而，這種瘟疫需要一些稀有的材料。\n\n我們會需要用到髓瓣，它們通常生長在這裡東邊的靜水池底。我們也會需要用到薩維倫之棘，通常生長在西北方的石崖邊。最後，我們需要一些鹹水海參，你可以在耳語海岸的海水裡找到它們。您會收到：\n\n", progress = nil, completion = nil, rewards = "薩維倫的手套髓瓣長靴薩維倫護手您會收到：\n\n南瓜袋"}
MultiLanguageQuestData['tw'][24977] = {title = "喬漢的實驗", objective = "將斑紋南瓜帶去給被囚禁在考斯頓莊園涼亭的血色狂熱者。", description = "這些南瓜看起來很正常，對吧？至少外表看來如此。如果我們想要阻止天譴軍團來自北方的進軍，以及人類來自南邊的入侵，那麼我們必須開始意識到自己身為亡靈的優勢。\n\n只要稍微耍點小把戲，一個簡單的南瓜就能為黑暗女王立下大功。這顆南瓜，摻入了我最新的配方，將會成為很有功效的大餐。\n\n最近又有一個血色狂熱者被抓到了，我們把他關在涼亭裡。把這個南瓜拿去給那個笨蛋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24978] = {title = "收割那些農夫", objective = "殺死10名提里斯法農夫或是提里斯法雇農。", description = "人類這種生物素以反覆無常而惡名昭彰。西邊的那些農夫也不例外。是啊，他們現在也許只是平靜地耕作著他們的田地，但是明天，他們可能會舉起他們的鐮刀來對付我們。聯盟正悄悄地逼近吉爾尼斯，而暴風城的力量在南方蠢蠢欲動...這些勢力都有可能對這些農夫進行徵召並把他們當作對付我們的先頭部隊。\n\n我要他們死。去幫我完成這件事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "沸滾的護腕鐮刃灼閃短刀灼閃鬥棍您會收到：\n\n"}
MultiLanguageQuestData['tw'][24979] = {title = "血色書信", objective = "找到血色護欄裡的俘虜。", description = "中尉哥伯勒：\n\n你決定收容一名俘虜…一名不死族俘虜，實在是件奇怪的事情。你在想什麼？難道你認為，只因為這名俘虜以前的身分，她就應該對血色十字軍的命令有豁免權？\n\n這真是令人困擾，哥伯勒。我要提醒你這種行為是有罪的。我命令你立刻處決這名俘虜。她已經不再是我們的一份子了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24980] = {title = "血色護欄", objective = "殺死10名血色戰士。", description = "我們需要一些像你一樣「積極」的傢伙去把那些血色十字軍送進墳墓。\n\n向我證明你能夠為黑暗女王陛下服務吧，往西走，過索利丹農莊抵達哨塔並殺死10名血色十字軍的戰士。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24981] = {title = "我們的眼中釘", objective = "殺死3名血色狂熱者和3名血色傳教士，並且取得血色信函。", description = "我們收到喪鐘鎮的執行官阿倫傳來的情報，內容包括了我們在這片土地所需要清除的所有人類禍害。根據這份情報，血色十字軍任命了派瑞恩隊長帶領一隊軍隊進駐了布瑞爾西南方的廢墟塔。\n\n殺死3名血色狂熱者和3名血色傳教士。當你到達那裡時，看看是否可以找到其他有關他們意圖動向的情報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24982] = {title = "新的被遺忘者", objective = "到提里斯法林地的布瑞爾向執政官塞弗倫回報。", description = "坦白說，去年的被遺忘者還是一群流著鼻涕的可憐傢伙。我們在破舊的人類建築裡縮成一團，躲藏天譴軍團的搜尋，對聯盟感到畏縮，並且在部落的腳下卑躬屈膝。\n\n現在看看你的面前，看看重新誕生的被遺忘者。我們在艾澤拉斯立下了自己的印記，而這個印記將會閃閃發亮。我們的統治很快將會囊括整個世界！\n\n你想聽我的建議？與布瑞爾的執政官塞弗倫交談。沿著這條路往下走。他負責管理那座城鎮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24983] = {title = "被遺忘者的責任", objective = "與提里斯法林地的死亡看守小站的亡靈守衛林奈交談。", description = "我需要東邊亡靈守衛站的最新報告。\n\n我必須知道是否有更多的天譴軍團溜過亡靈壁壘進入提里斯法。我們必須維持對瘟疫之地的警戒，不能讓天譴軍團在這裡得到更強大的立足點!\n\n沿著這條路往南走，然後往東到達守衛站所在的叉路口。與亡靈守衛林奈交談。她會有我所需要的情報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24988] = {title = "死亡之寒", objective = "取得5張夜行蝙蝠的毛皮。", description = "好冷啊...可怕的瘟疫正如冰冷的毒蛇一般在我的血管中逡巡。也許我很快就會徹底失去意志。但這世上沒有任何東西能夠阻止我為我們偉大的黑暗女王效命。命令一下達，我就開始為希瓦娜斯大人軍隊中那些陣亡戰士縫製屍袋。\n\n但現在我的手卻因為寒冷而顫慄不已。如果你能給我帶回五張夜行蝙蝠的毛皮的話，我就可以給自己縫條毯子了。幫幫我，<name>，這樣我就可以繼續為黑暗女王陛下效力了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "格雷森的軟靴夜行蝙蝠束褲死亡看守護腕夜行蝙蝠鎖甲護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][24989] = {title = "向執政官回報", objective = "回去布瑞爾找執政官塞弗倫。", description = "現在帶著我給你的這些情報回到執政官塞弗倫那裡去吧。他急著需要這幾份報告，所以你最好動作快點。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24990] = {title = "黑暗犬的猛襲", objective = "收集5瓶黑暗犬的血液。", description = "希瓦娜斯女士正在召集皇家藥劑師學會。她要我們嘗試製造一場新的瘟疫，一場比艾澤拉斯的任何疾病更為致命的瘟疫。這場新的疾病將會摧毀我們的敵人，不論是死的還是活的敵人。\n\n我的研究顯示那些野獸的血液也許將是關鍵。這裡，將這些瓶子裝滿黑暗犬的血液，這樣我才能拿來測試我的理論。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n弱效食人妖之血藥劑"}
MultiLanguageQuestData['tw'][24991] = {title = "加倫鬼屋", objective = "向位於提里斯法林地內加倫鬼屋的藥劑師傑洛德報告。", description = "你可能已經理解到，皇家藥劑師學會是個分佈廣泛的組織。我們很認真看待瘟疫鍊金這回事，而且我們相信有越多的成員在進行實驗，就能越快實現我們的目標。\n\n我們的其中一位成員就在此地北方的小營地執行他的工作。他的名字叫做傑洛德，他會需要像你這樣...聲譽卓著的學徒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24992] = {title = "逃出吉爾尼斯", objective = "將狼人的出現回報給提里斯法林地的執行官塞加德。", description = "就你所知，一隻狼人盜賊正在提里斯法遊蕩。這是執行官塞加德絕對會感興趣的事情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24993] = {title = "消滅狼人", objective = "找到並殺死5隻滲透到布瑞爾的狼人。", description = "這些狼人必須被解決掉，而且要快。我們首先要做的事就是消滅任何可能滲入到布瑞爾的傢伙。\n\n我要你留意在布瑞爾這裡任何可疑的活動，<name>。我們知道那些狼人會躲藏在陰影裡，所以找出任何你能發現的跡象...腳印、被踢翻的石頭...任何東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "執行官的斗篷狼人殺手之劍狼人教鞭您會收到：\n\n"}
MultiLanguageQuestData['tw'][24994] = {title = "末日草", objective = "收集10份末日草。", description = "我的使者剛為我送來了很多陰暗草。陰暗草!我不需要陰暗草，我要的是末日草!你看到我所處的困境了吧，<name>。\n\n收集我所需要的東西要花上你的時間，我會讓這一切值得。為我帶回足夠的末日草，我會給你適當的報償。\n\n據我所知，他們想要將瘟疫散佈到那大型墓園附近的植物上，就在布瑞爾墓地的北方。動作快，並留意那附近出沒的豺狼人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][24995] = {title = "剝除鱗片", objective = "收集5個邪鰭魚人的鱗片。", description = "在你幫我收集樣本的時候，我的實驗讓我了解到，為了能讓這個新的疾病成功的擴散，我需要更多的試劑。對一些不幸的受害者下毒不過是小孩子的遊戲。讓整個世界感染瘟疫才是難事。\n\n我需要一些魚人身上的鱗片，就在這附近。你會在北邊看到這些生物無腦般地漫步在岸邊。您會收到：\n\n", progress = nil, completion = nil, rewards = "坩堝手套邪鰭腰帶您會收到：\n\n沉睡之砂"}
MultiLanguageQuestData['tw'][24996] = {title = "霍蘭德的實驗", objective = "帶著霍蘭德的特製飲料去找被俘虜的巡山人。", description = "我要了解另外一個剛被俘虜的愚蠢矮人巡山人。亡靈衛兵把他存放在這棟建築物裡，而且還派了人來勸他不要逃跑。\n\n何不去看看這位被俘虜的巡山人是如何享受我為他特製的飲料呢？這裡面含有黑暗女王為艾澤拉斯殘存的人們所準備的神秘配方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "巡山者的腰帶恐懼之末護手巡山人護腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][24997] = {title = "盜墓賊", objective = "殺死腐皮盜墓賊和混血腐皮豺狼人，並且取得6瓶防腐劑。", description = "我們西邊森林裡的亂葬岡，埋葬著一群數量令人...印象深刻...的死者，這些都是第一次瘟疫來臨時在提里斯法死去的人們。\n\n墳墓裡的屍體大多還沒變成不死族，但是最近天譴軍團派了一群腐皮豺狼人到那裡收集屍體，藉以壯大他們的軍隊。我們不能容許這樣的事!\n\n你的任務有兩個:殺光躲在亂葬崗和加倫鬼屋裡的腐皮豺狼人，並且收集他們身上用來復活屍體的防腐劑。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "殭屍皮靴鋼質護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][24998] = {title = "蛆眼", objective = "殺死蛆眼並取得他的爪子。", description = "蛆眼是隻臭名昭彰的野獸，即使以豺狼人的標準來看也是如此。他率領著一群背叛的豺狼人往北邊而去，在林地裡肆虐並且偷走一路上他所能找到的屍體。\n\n那些屍體是我們的!我們對那些屍體可是有計畫的!\n\n蛆眼的存在對我們造成了妨礙。別對他有任何憐憫。只有弱者才會憐憫別人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "邪惡豺狼人腰帶布瑞爾腰帶加倫的護腿布瑞爾護腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][24999] = {title = "種下恐懼的種子", objective = "追趕12隻邪鰭蝌蚪直到牠們嚇昏。", description = "看起來傑洛德要你去獵殺一些北邊的魚人。很好...我們可以用一些魚人的身體來當毒藥。雖然有時我還是有點小擔心...\n\n邪鰭魚人孵化的地方就在提里斯法北方岸邊的不遠處，你應該可以在岸邊的成年魚人之間發現不少小蝌蚪。如果這些敏感的年輕魚人打算對我們展開報復...那我們將會受到重創。去嚇嚇牠們，讓牠們知道我們被遺忘者跟部落不是好惹的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25000] = {title = "提根的同胞", objective = "殺死懼齒奔跑者和懼齒鐮爪龍以收集8個懼齒皮革。", description = "嘿，<class>!\n\n你要去幫提根下士的忙嗎?他現在負責讓補給道路保持暢通。\n\n他手下有兩個負責雜物的矮人，是我所見過脾氣最暴躁彆扭的矮人了。如果你想讓這兩個壞脾氣的獵人對你留下印象，你必須好好表現，讓他們看看你如何料理這一帶的猛獸 。\n\n這個要塞西邊的猛獸特別凶暴，如果你能帶一些新鮮的獸皮給苟丘，就可以讓他們留下深刻的印象。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25001] = {title = "鏟沙者", objective = "殺死鏟沙者。", description = "我的其他助理正在確認我們驕傲的新夥伴都進了舒適的籠子，運往最需要他們的地方。為了部落。在此同時，我們還有最後一件工作要完成。\n\n鏟沙者，砂槌的酋長，可能笨到還沒發現我們在搞什麼鬼。不過我最痛恨沒把事情做完，寶貝。他就在西邊的洞穴裡。快去收拾他，我們就可以高興地結束工作了，好吧?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "擦掌磨拳鏟沙者護腕停業之匕污水胸針砂槌碎顱錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][25002] = {title = "撿寶", objective = "從迅猛龍巢穴取回10個北方補給箱。", description = "<你在屍體上發現一張貨物清單，上面列著一長排前線急需的雜貨物品。>\n\n<泥土中的血跡顯示屍體是從南邊被拖來的，朝著迅猛龍的窩裡去。>\n\n<或許迅猛龍們把補給品拖走了。為提根下士找回這些補給品能幫忙挽救這場災難!>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25003] = {title = "家族墓穴", objective = "殺死5名哀嚎的鬼魂和5名腐爛的古屍。", description = "磨坊最堅固的地方就是阿加曼德的家族墓穴了。藉由死靈術，達高爾隊長復活了阿加曼德家族眾多祖先的古屍，並計畫利用它們來與我們作對。\n\n我們絕對不能允許這種情形，你必須加以阻止。到阿加曼德家族墓穴去，擊敗那些復活的阿加曼德古屍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "阿加曼德家傳護腿阿加曼德家傳手鐲阿加曼德家傳騎乘長靴阿加曼德家傳腕輪您會收到：\n\n"}
MultiLanguageQuestData['tw'][25004] = {title = "磨坊告急", objective = "收集5個凹槽肋骨和3個焦黑的顱骨。", description = "天譴軍團正試圖在阿加曼德磨坊那邊建立起一座前哨基地。如果他們得逞了，他們將可在提里斯法之中發動進一步的攻擊。\n\n命令已經下來了。磨坊的天譴軍團勢力必須被摧毀。\n\n從斷骨士兵和碎顱士兵身上收集凹槽肋骨，再從暗眼骸骨法師身上收集焦黑的顱骨。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25005] = {title = "與塞弗倫交談", objective = "在提里斯法林地的布瑞爾與執政官塞弗倫交談。", description = "我將你交給我的遺骸都摧毀了，<name>。所有的遺骸，除了這些以外...\n\n戴弗林‧阿加曼德過去活著的時候雖然很弱小，但是舌頭卻很毒，同時也是第一批死在瘟疫中的受害者。他被天譴軍團奴役很久了，比大多數人都還要久。因此，他也許擁有一些對我們有價值的知識。\n\n把他的遺骸帶給執政官塞弗倫，並且告訴他我告訴你的事。他會知道該怎麼做的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25006] = {title = "虛弱的控制", objective = "與布瑞爾的暗影牧師馬里雅交談，並且加入抽離戴弗林‧阿加曼德的儀式。", description = "冰封王座進入沉睡之際，巫妖王對天譴軍團的強大控制力也變得軟弱許多。他對像是戴弗林‧阿加曼德這類弱小傢伙的掌握能力應該已經脆弱到可以被我們完全移除。\n\n與城鎮東邊莊園裡的暗影牧師馬里雅交談。她將會協助你完成這個程序。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "戴弗林的襯衣布瑞爾長靴布瑞爾足靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][25007] = {title = "東方...永遠朝向東方", objective = "到提里斯法林地的亡靈壁壘向高階執行官德靈頓回報。", description = "你在這裡為我們做了很多，<name>，不過像你這樣的<男人/女人>在別的地方仍然派得上用場。\n\n在這裡的東邊有一座亡靈壁壘:一個經過加強的防禦工事，用以對抗來自瘟疫之地的劫掠。這座亡靈壁壘保衛著我們免受天譴軍團的入侵，並讓我們有足夠的安全在提里斯法林地這裡建立自己的武力。\n\n去吧，與高階執行官德靈頓交談。他是個盟友，並且毫無疑問的將會非常珍視你所提供的每一分幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25008] = {title = "骯髒的動物", objective = "殺死6隻亂齒食腐狼。", description = "你也許在路上聞過亂齒食腐狼的味道，牠們的臭味比老髒鬼皮特還要可怕。毫無價值的動物!偷走我們的獵物，翻動我們的補給品，最糟的是...牠們甚至難吃得要死。\n\n去殺死一些食腐狼。\n\n如果你想要的話，多殺一些也沒關係。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "亂齒皮腰帶食腐狼戒指亂齒鍊環您會收到：\n\n"}
MultiLanguageQuestData['tw'][25009] = {title = "與血色十字軍的戰爭", objective = "殺死3名血色狂熱者和4名血色苦行修士。", description = "雖然血色十字軍的力量已被削弱了，我們卻仍身處交戰之中。執行官阿倫給我的報告中提到，在瓦松隊長的指揮下，血色十字軍正以提里斯法東南部、巴尼爾農莊附近的那座廢墟塔為據點發動劫掠。\n\n殺死他3名的血色狂熱者和4名血色苦行修士。這應該可以帶給血色十字軍一次沉重的打擊!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25010] = {title = "致命的新盟友", objective = "到提里斯法林地的血色駐營尋找你的新盟友。", description = "就在你抵達亡靈壁壘前不久，一個最不平凡的年輕不死女性過來找我。她宣誓自己對血色十字軍的敵意，所以我派她去對付我們在北邊的敵人。你說你不久前看到一些死掉的血色十字軍？那有可能是她的成果。\n\n去確認一下她的狀況，看看她對那些十字軍的復仇行動是否需要任何支援…雖然，就算她已經把他們殺光了我也不會感到驚訝。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25011] = {title = "更大更好的東西", objective = "與提里斯法林地的提摩西‧卡汀漢交談。", description = "亡靈壁壘這裡沒什麼你可以幫上忙的了，<name>。你已經做得夠多夠好了。然而，也許在銀松森林還有更多的冒險在等著你。\n\n去和我的蝙蝠管理員，提摩西‧卡汀漢交談。他會給你一次免費的飛行，送你到布瑞爾去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25012] = {title = "飛向天空", objective = "在提里斯法林地的布瑞爾與執行官塞加德交談。", description = "如果你要回到布瑞爾，你會想在執行官塞加德那裡稍作停留的。我聽說南邊的銀松森林裡有些刺激的狀況。他會知道得比我清楚。\n\n準備好出發時再和我交談一次。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25013] = {title = "一點精神", objective = "取得4份邪惡的夜行蜘蛛毒液樣本。", description = "<迪瑟斯取樣了他最後的混合物。>\n\n唔…這樣不太對。需要一些別的東西來刺激它的活力。我知道了!北邊那些蜘蛛的毒液有能力做到這件事。去看看你能否幫我萃取一些毒液來，<name>?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "高級夜行蜘蛛之弩夜行蜘蛛手套收割者的小圓盾您會收到：\n\n"}
MultiLanguageQuestData['tw'][25014] = {title = "鏟沙者的寶藏", objective = "找梅格斯‧驚懼伐木機說話。", description = "放在碎石者巢穴最底端，飽經風霜的石箱裡，你找到一個有趣的神器。\n\n它的形狀像一隻甲蟲，表面是一種光滑又亮眼的藍色，以金色滾邊。它看起來像機械裝置，完全不像凡人之手所創造出來的，而且很老舊。\n\n梅格斯應該會對它感興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25015] = {title = "讓他們尖叫", objective = "殺死8個刺背劍衛或是變異織棘者，並且從其中一名變異織棘者身上收集一支刺藤法杖。", description = "卡林多的原住民之一就是「野豬人」。長滿刺的小畜生，足以讓人痛恨這塊大陸。\n\n這場劫掠在我們剛建立好前線營地不久後就發生了。更糟的是，那些多刺的惡魔似乎還讓這些荊棘長成了地獄般的叢林。我需要你幫忙擊退這些野獸，這樣我們才能和前線指揮營地重新建立聯繫。\n\n當你到外面去的時候，順便把他們施法者身上帶著的扭曲的樹枝拿回來，他們似乎就是用這個東西操縱這個叢林的生長。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25016] = {title = "FLAG - Training Complete", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][25017] = {title = "古老門障", objective = "摧毀6個砂岩魔像。", description = "多年來這個峽谷一直都被滴水不漏的密封在門後。現在災難將門破壞掉了，而裡面的秘密等著我們來挖掘。\n\n目前還有一些障礙物在阻礙我們。在門裡面，消失已久的泰坦創造物甦醒了。他們漫無目的地橫跨沙漠，攻擊所有接近他們的事物。\n\n有人必須要摧毀把守峽谷的魔像;你想挑戰嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "看守者腰帶審查人護甲砂岩肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][25018] = {title = "安多連的覺悟", objective = "將神器帶去守衛之谷給安多連‧曦揚。", description = "仔細聽了，<name>。我不清楚巨魔怎麼拿到那個東西的，但那是泰坦的神器。雖然我不是專家，但看來那件神器應該比我們腳下踩的沙還古老。\n\n我還知道這種東西通常只會帶來麻煩。我不想要跟它有任何關係。將它帶去南邊的守衛之谷給那邊一位名叫安多連‧曦揚的血精靈。而且不要問任何問題，寶貝，拜託。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25019] = {title = "佔取", objective = "殺死10名矮人考古學家。", description = "我們不是唯一發現南月廢墟價值的人。探險者協會那些矮人群聚到這裡，為了聯盟蒐集遺寶和銘文。\n\n我不覺得我需要進一步解釋了。我們不會容許這裡的發現落入聯盟的手中。盡你所能地殺死那些矮人，然後將他們趕出廢墟!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25020] = {title = "斷簡殘片", objective = "收集5個古老的象形文字。", description = "我們在東邊的南月廢墟找了點東西。我同僚找到從流沙中浮現出來的石裂片，上面刻著古老的文字。\n\n此文字並不屬於現存在的語言，但與泰坦廢墟那邊看到的印記雷同。解讀此文字可能會顯現出更多秘密。\n\n很不幸的是我的同僚們目前正在防禦石板不被聯盟拿走。我需要你去一趟南月廢墟親自拿到石板。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25021] = {title = "以血興旺", objective = "從沙怒食人妖身上收集6捧血液。", description = "為了在嚴酷的沙漠中生存，沙怒食人妖必須知曉所有血魔法的秘密。把血喝下，你就能得到力量…最黑暗的巫毒，不是嗎？但現在已經沒有什麼保留的餘裕了。\n\n我們需要鮮血才能找到劍。你真走運，瑪左迦是個叛徒，對嗎？那邊的山丘上有許多沙怒食人妖。\n\n到那裡去，幫瑪左迦拿血來…很多的血…然後我們就開始尋找迦薩斯的儀式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25022] = {title = "失去聯絡", objective = "從蔓生之地的野豬人手中救回蓋恩斯大使。", description = "我告訴過他這很愚蠢，但是蓋恩斯大使堅持他可以說服野豬人和我們結盟一同對抗部落。就算他成功了，我也不會想和那些...東西一起作戰。\n\n好吧，蓋恩斯沒有回來，而霍桑將軍會為了失去一個人才，失去一個最懂得要如何和這些愛尖叫的野蠻生物交涉的人才，把責任怪罪到我頭上。\n\n到那座熱氣騰騰的叢林裡尋找大使，如果他還活著，把他給救回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25023] = {title = "老朋友", objective = "到失落群島的大酋長守望和索爾說話。", description = "好啦，爬到梯子上去。我們要離開這啦!\n\n我們會飛過城鎮，然後我就要帶你去見一些老朋友!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][25024] = {title = "擊退傘兵", objective = "殺死10名聯盟傘兵。", description = "朋友，聯盟的傢伙在最壞的時機跑回來找我們了。雖然我們把他們的船處理掉了，不過飛機仍在空投他們引以為傲的127師傘兵成員。\n\n戰誓者和斥候們只能在兩條坡道那裡抵擋住他們的優勢兵力。但我很確定如果你幫助他們，戰爭的情勢很快就能得到逆轉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25025] = {title = "反擊者桑薩斯", objective = "擊敗札克卡魯並取得封印的桑薩斯。", description = "鮮血說話了。我可以感覺到它在沙中流動...死亡浸濡的苦難沙漠...\n\n<瑪左迦兩眼翻白。>\n\n就在那裡！血液流向南邊，都是白骨的峽谷。札克卡魯！札克卡魯，瑪卡利的爪牙，就是那個邪惡的傢伙要求獻祭...他們將他的父親逐出祖爾法拉克，阻礙他的登基...他將再度飲下鮮血...\n\n<瑪左迦搖搖晃晃。>\n\n快去，<class>。桑薩斯在札克卡魯手上。這不是什麼好事，相信我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "骨峽之錘血語者外套懇血者肩鎧沙怒短斧您會收到：\n\n"}
MultiLanguageQuestData['tw'][25026] = {title = "最漆黑的魔精", objective = "從沙怒殭屍身上取得6個最漆黑的魔精。", description = "迦薩斯在閃躲我，老兄...光是血還不夠。我們需要更強大的東西才能找到它。\n\n當你需要傾所有食人妖之力才能度過難關時，死了任何一個都是不得了的事，夥計，這就是為什麼沙怒食人妖需要用巫毒復活死者。你倒了，還能再站起來，繼續幹活...直到永遠!\n\n我們所喚醒的那些殭屍身上有最漆黑的魔精。你到西邊去找他們，給我拿魔精來，懂吧?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25027] = {title = "你輕敲著細籐，留給我葉子", objective = "在蔓生之地將刺藤法杖使用在三齒的身上，然後殺死其他2名變異老巫婆。", description = "根據蓋恩斯的描述，那些野豬人稱他們族母為「三齒」。就是她扭曲了荊棘製造出這個瘋狂的叢林，也是她下令將蓋恩斯「撕成碎片去餵給蔓生之地」。真是位好女士。\n\n讓她嚐嚐自作自受的滋味吧。用你取回來的這柄刺藤法杖把三齒給解決掉，然後殺死她訓練出來的巫婆，確保沒有人會取代她的位子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "野豬老巫婆手套三齒護腕三齒臂甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][25028] = {title = "來自地底的麻煩", objective = "從蔓生之地萌芽的花朵上採集10朵不尋常的花蕾。", description = "提根真是個笨蛋，竟然會認為是那些野豬人造成這場突如其來的植物蔓生。看看你的四周。我每天都在觀察這些植物的花朵和嫩芽，每一代都比之前的變異得更厲害。這可不是某種部落魔法，這是更原始的東西，也更危險。\n\n前一天我們的營地才來了一位偉大的德魯伊。去找納拉雷克斯，他就在這片叢林裡的某處，他會知道該怎麼做的。\n\n順便帶給他一些蔓生之地的植物樣本，好幫助他進行研究。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25029] = {title = "阿加曼德家族", objective = "取得格里高的遺骸，妮薩的遺骸，薩爾曼的遺骸，以及戴弗林的遺骸。", description = "阿加曼德家族曾是提里斯法林地中最富有的家族。我過去曾在他們的磨坊裡工作...在瘟疫降臨之前。\n\n天譴軍團第一次入侵的時候，阿加曼德家族的人在他們的家園上設置了防禦工事，並說服他們的雇員留下來幫助他們進行抵抗。我們是一群傻子，但至少我們是忠誠的傻子。\n\n阿加曼德家族的高傲讓我們遭受毀滅，變成了不死族。現在他們卻成了天譴軍團的走狗!\n\n為了被遺忘者剿滅那些墮落於瘟疫的阿加曼德家族。為了我將他們的屍體帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "碎骨錘暗木法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][25030] = {title = "鬧鬼的磨坊", objective = "將達高爾的顱骨帶給阿加曼德磨坊的庫勒曼‧法席恩。", description = "你感覺某種邪惡的存在從這個野獸的顱骨呼之欲出。庫勒曼‧法席恩也許會有興趣想看看這個。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25031] = {title = "磨坊復仇", objective = "到提里斯法林地的阿加曼德磨坊向庫勒曼‧法席恩回報。", description = "西邊的阿加曼德磨坊淪陷到天譴軍團手中了。阿加曼德家族的人遭到屠殺，整個住宅都受到天譴軍團的控制。\n\n這或許是天譴軍團在提里斯法中最大的前哨基地，<name>。如果你是個夠格的<class>，過去那裡和庫勒曼‧法席恩說話。他一直在盡他的全力去嘗試奪回這片土地，他將會需要幫助。順著路走，你就將見到他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25032] = {title = "綠洲的秘密", objective = "尋找保衛者迦薩斯。", description = "沒錯，我看見另一半了，老兄...在南邊...\n\n我們很接近了，夥計。在一座綠洲裡，埋在水池的泥巴下面。別慢了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "綠洲披肩虛實分辨手套瑪左迦的棄置罩盔輕錘肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][25034] = {title = "到前線去!", objective = "到南貧瘠之地的前線指揮營地找到蓋恩斯大使。", description = "我很希望能讓你待在戰線的後方，但是看來你要被召喚到前線去了。還記得蓋恩斯大使嗎?他重新回到了前線指揮營地，而在這份最新的公文裡，他親自要求你去協助他。\n\n你會在南邊找到我們的前線指揮營地，現在它的名字叫做「鮮血草原」。\n\n小心點，<name>。在這一路上部落已經伏擊我們好幾個軍官了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25035] = {title = "突破防線", objective = "和喬弄說話，騎上坐騎前往惡鱗灣去找摩拉基。", description = "沃金召集了一次全面攻擊，目標是佔據我們北方島嶼的納迦。我們許多人馬已經在橋的附近和他們開戰，但少部分的我軍突破了他們的防線，前去他們的島嶼發動襲擊。\n\n去和喬弄說話，好前往那座島嶼。到達那裡後，去找警備指揮官摩拉基。他會告訴你怎麼協助那邊的戰事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25036] = {title = "提根的麻煩", objective = "到南貧瘠之地的提根遠征隊向提根下士回報。", description = "上將會很高興的，我們幾乎固守住北方城堡，但如果要繼續支撐下去的話，就得維持通往內地的補給線。\n\n就在突擊開始前，我收到了一份奇怪的報告，是負責與前線指揮營地保持聯繫的提根下士送來的。報告上說他在「叢林」碰上一些麻煩?在南貧瘠之地沒有任何叢林!\n\n沿著北方城堡延伸出去的那條上方的路走，看看你是否可以為我們搞不清楚狀況的下士提供什麼協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25037] = {title = "捕螃蟹", objective = "殺死小海浪蟹並收集5份新鮮蟹肉。", description = "或許是我老了，身子的毛病多了，野豬肉我是怎麼也嚥不下去。我想是該來點新東西的時候了。\n\n我們才剛架好一些螃蟹陷阱，不過要是你能體諒一下我這個沒耐心的老食人妖，我倒是馬上就想嚐些新鮮的蟹肉。島的四周到處都是螃蟹，不過最好的捕獵點是在東邊的海岸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25038] = {title = "葛爾多的任務", objective = "收集3株陰暗草，並把它們帶給布瑞爾的初級藥劑師霍蘭德。", description = "主人需要草。我們的手太大，撿得不好。你幫我們，我們不傷害你。我們需要陰暗草。這附近有許多草，路邊也有。\n\n當你拿到陰暗草，把它帶給布瑞爾的主人霍蘭德。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25039] = {title = "你在外面有看到什麼奇怪的事嗎？", objective = "與執行官塞加德談談你遇到狼人的事。", description = "<race>！聽好了，我有些…奇怪的東西要討論。\n\n我在澈水湖釣魚，然後看到了一件最要命的事…某種像狼一樣的人，在提里斯法林地附近奔跑著。你覺得那該不會是個…狼人吧，你覺得呢？\n\n不管怎樣，我不斷告訴自己應該告訴執行官塞加德這件事，但是我實在是太害怕了。也許你可以幫我和他談談？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25040] = {title = "FLAG - Worgen Attacked", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][25041] = {title = "獅子之傲", objective = "殺死5隻的平地徘徊者或是平地傲鬃獅。", description = "尊敬那些獅子，<name>，牠們是兇猛的殺手!你得承認這些野獸真的很優雅...肌肉和利爪...為了食物而疾奔...這麼的原始...\n\n很抱歉，我分心了。就像我說的，我很尊敬這些獅子，但是牠們正在殘殺我們的巡邏隊員。我說得一點也不誇張。我的部下現在甚至不敢在晚上獨自上廁所。你可以幫忙讓我們的營地安全點嗎?\n\n貧瘠之地的獅子喜歡在樹底下徘徊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25042] = {title = "靠我們的胃袋行軍", objective = "殺死在南貧瘠之地的雷角蜥蜴，以收集4份新鮮的雷角蜥蜴肉排。", description = "他們說得一點也沒錯:軍隊是靠胃袋行軍的。而我們已經走了很久了。\n\n我在想如果我們可以把那些巨大的雷角蜥蜴做成烤肉，就有足以餵飽我們好幾個星期的肉了。\n\n雷角蜥蜴又大又笨重，所以應該很好獵殺。除非...嘿，你身上沒有帶著任何金屬吧?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "厚塊白鑞版瓦罐攪拌器雷角皮長靴特洛利的手套雷角蜥蜴踏靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][25043] = {title = "鮮血草原", objective = "在南貧瘠之地的鮮血草原殺死10名淒涼的蠻兵。", description = "部落把這個區域叫做「鮮血草原」。這是一個相當貼切的名字:這些草都被我最優秀部下的鮮血給染紅了。\n\n我派出巡邏部隊去剿滅野豬人並且回報部落軍隊的動態，但是他們並未全數歸來。他們在那邊需要你去援手。\n\n到草原上找出那些淒涼的蠻兵，我們的這些煩惱就是他們造成的。你不用期待他們會投降;他們的大酋長教導過他們要作戰到至死方休。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25044] = {title = "外交的其他途徑", objective = "帶著挑戰號角到南貧瘠之地的刺背挑戰之環。吹響號角挑戰刃鼻並殺了他。", description = "我還沒忘記，在那個險惡的叢林中，我差點就死在野豬人手上。將軍曾經下達一些戰略上的攻擊命令，但他在開始大屠殺之前就停手了。我可沒有這層顧慮。\n\n帶著這個我在談判過程中「借來」的號角，往西方進入刺背挑戰之環。放心，你絕不會錯過;然後我要你在抵達後吹響號角挑戰刺背勇士刃鼻，一對一單挑。殺死他可以讓他的追隨者們陷入徹底混亂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "野豬之啟長靴刺背挑戰之戒刃鼻的披風刺背挑戰足靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][25045] = {title = "泥土中的防線", objective = "在鮮血草原奪下一座中立的山丘，並且防守住部落的反擊。", description = "就戰術上而言，控制一個區域需要經常性的觀察。看看這張地圖，我標出了幾個具有戰略意義的山丘，就像這個一樣。如果想確保我們的敵人在我們的控制之下，聯盟一定得取得這些地方。\n\n我的斥候已經標示出了它們在戰場上的位置。我需要的是有人擔任先發部隊去把它們搶奪過來，而你就是那個合適的人選;。\n\n在陶拉祖營地廢墟的北邊、東邊和南邊找到中立的灰色旗幟。把它們搶過來，並且守住它們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "霍桑之盾血域長袍陶拉祖護腿陶拉祖護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][25046] = {title = "女兒的擁抱", objective = "帶莉莉安‧佛斯到十字軍小徑的塔樓去見她父親。", description = "低語聲繼續說:\n\n<「我的名字是莉莉安‧佛斯。在死前，我是隸屬血色十字軍的成員。我的父親，高階祭司佛斯，將我當成對抗瘟疫的武器來養大。我學習偷竊、巫術、戰鬥技藝，以及任何能讓我變得更強的事物。我為他拋棄了我的童年。」>\n\n<「然後，造化弄人，我在死後重回人間...重回成這副德行。我的父親瞬間遺忘了我，並且，在我重回人間之後，下令將我處決。」>\n\n<「來。我們現在要去和他談談，在他東北方的塔裡。」>您會收到：\n\n", progress = nil, completion = nil, rewards = "達靈頓的短匕莉莉安的法杖執行官的胸甲您會收到：\n\n劊子手的袋子"}
MultiLanguageQuestData['tw'][25047] = {title = "破損的獵豹刻像", objective = "用你的技巧與材料來修復破損的刻像。", description = "這尊嚴重破損的刻像被它的前任主人給丟棄了。然而，藉由正確的材料和珠寶設計手藝，你可以將它完全修復。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n刻像 - 惡魔獵豹"}
MultiLanguageQuestData['tw'][25048] = {title = "海濱撈寶", objective = "收集7個熱砂補給物資。", description = "想說服諾格弗格先生允許我們調來更多地精，就得向他讓他知道我們多有誠意!我知道該怎麼做。\n\n海賊封鎖了加基森，但仍有許多貨物逃過了轟炸，還算完整...只是被海水沖散了。它們大多散落在城鎮南方的淺灘。\n\n如果你去幫他們收集這些物資，就能幫我們交到朋友!而且這樣也能阻止那邊那個壞心的哥布林女孩把它們拿去賣掉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25049] = {title = "踏浪", objective = "殺死8個逐潮者。", description = "這裡有大麻煩啦!海平面上升是件好事，因為這樣讓船可以駛進到加基森。但現在，外頭有一堆噁心的海巨人包圍了城鎮!我相信諾格弗格先生一定會感激我們替他除掉這些海巨人。\n\n別擔心，我不是讓你做慈善事業!解決掉他們，我會給你報償!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25050] = {title = "火箭救援", objective = "將救生火箭交給5個熱砂倖存者，並使用炸彈殺死40個南海攔路者。", description = "當海水灌進來的時候淹沒東邊的熱砂港，很多可憐的哥布林仍困在那裡！可惡的海賊見到從這裡出港的船隻就射。\n\n可他們萬萬沒料到我們還能用飛的吧！碼頭有一艘熱氣球。我們可以靠它飛去拯救那群哥布林，順便收拾那些海賊。諾格弗格先生一定會很高興！\n\n到碼頭去，跳上熱氣球，我會跟在你後面，好嗎？我得去找一些火箭…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "娜絲米菈的攪湯棍未爆彈回收的熱砂頭盔不成功的救生火箭原型您會收到：\n\n"}
MultiLanguageQuestData['tw'][25051] = {title = "滅絕暗霧", objective = "在暗霧洞穴裡摧毀8個暗霧蜘蛛蛋。", description = "佔據西北邊暗霧洞穴的蜘蛛對這裡來說又是一項兇險的威脅。他們不是巨魔無法對付的敵人，但當塞拉摩的部隊潛伏於附近之際，將注意力分散到牠們身上會是致命的錯誤。\n\n我需要某人過去摧毀暗霧洞穴裡面的蛛卵，好斷絕這種肆虐。你會在被蛛網覆蓋的礦坑最深處找到那些蛛卵...以及它們的守護者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25052] = {title = "死人的箱子", objective = "殺死15個南海海賊。", description = "噢，天啊，如你所見，這裡正和海賊打得不可開交。我們正在盡最大的力量，讓他們再也不敢騷擾加基森和地精的新家!\n\n方法就是，殺光他們。\n\n幫幫我們如何?我們真的很希望能殺得比那邊那個綠鼻子和他那幫惡棍還多。我會很感激你!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "南海兜帽驚異護腿藐視不敬手套潔淨肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][25053] = {title = "燒成灰燼!", objective = "使用燃燒的蘭姆酒點燃西北棚屋、東北棚屋和西南棚屋。", description = "你知道，要不是這個地方又舊又髒，還有一堆海賊，這裡會是地精很棒的新家!我們正在解決這些海賊，不過還需要處理這些髒亂。\n\n我是說，沒有一個潔身自愛的地精會想住在這麼破舊的屋子裡!所以啦，拿著這瓶燃燒的蘭姆酒，幫我們燒掉那些破屋子!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25054] = {title = "搶劫", objective = "收集10份海賊寶藏。", description = "那些海賊的黃金就這麼隨處散落，真是浪費。這些東西的用途可多著呢!像是熔成金屬絲，或是當成電器的內部遮罩，或是賣給其他的愚蠢種族，他們蠢到花錢買黃金，就只為了放在身邊。\n\n說到愚蠢的種族，我敢打賭那些貪得無厭的哥布林一定會把它們全拿走。我不能讓他們得逞!去幫諾姆瑞根收集那些寶物!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25055] = {title = "制伏元素", objective = "加文·灰羽要你使用大地之环补给品中的元素灵契和净化图腾，制服20个激动的大地之魂。", description = "<class>，元素的动荡永不会止歇。正在危害这片土地，甚至可能摧毁铁炉堡的地震并不寻常。大地之环相信，我们必须在元素彻底撕裂艾泽拉斯之前让它们恢复平静。我们需要你的帮助，<name>。\n\n我会给你一口袋大地之环的补给品。你能在其中找到两件物品——元素灵契和净化图腾。你可以用灵契看到元素世界。然后你就要使用净化图腾制服躁动的大地之魂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25056] = {title = "恐怖的灰熊", objective = "取得5張染疫褐熊毛皮。", description = "你見過在西方四處遊蕩的染疫褐熊嗎？那些熊的毛皮…這麼醜惡、充滿病菌、這麼的…完美！\n\n帶5張皮回來給我。我有個製作「反天譴」毒素的好主意，而且肯定會成功！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25057] = {title = "軍令如鐵", objective = "在陶拉祖營地廢墟與陶拉祖營地強奪者交談並且逮捕他們。使用北方城堡的鐐銬制服5名受傷的強奪者。", description = "我們從暴風城監獄徵召非暴力罪犯當士兵的這個政策，現在變成了我們的夢魘，<name>。一些不是那麼守規矩的士兵在陶拉祖營地犯下不合身分的行為，搶奪了遺留在城市裡的東西。\n\n這嚴重違反了軍紀。更糟糕的是，儘管我們的最終目標是取得和平，褻瀆敵人的家園卻只是刺激他們更奮力的和我們作戰。\n\n帶上這些鐐銬，把那些陶拉祖營地強奪者帶來伏法。先和他們交談，不過你也許會需要出手制伏他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25058] = {title = "哥布林除雷法", objective = "引爆10枚地雷。", description = "那些傘兵在海灘上設了地雷!\n\n大酋長問我有沒有辦法處理一下。我告訴他，「我們當然可以!」我是在想，也許你能拿這袋手榴彈過去，從安全的距離引爆那些地雷?\n\n這才是我們辦事的方法，對吧?!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25059] = {title = "陶拉祖營地的簡報", objective = "在陶拉祖營地廢墟尋找3張陶拉祖營地的情報。", description = "將軍把全部的心思都放在陶拉祖營地的強奪者上。太軟弱了!我們應該把心思專注在下一步如何對付部落才對。\n\n如果我們容許陶拉祖營地廢墟遭到燒毀，可能就會危及到一些珍貴的情報。在你進行將軍的任務時，到處看看能否找到什麼地圖或是紙條。我會說一些獸人語，所以我能搞得懂你所找到的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25060] = {title = "定義「瘋狂」", objective = "殺死10個瘋狂的倖存者。", description = "我們接獲報告，一艘哥布林船隻前些日子在這處海灘發生船難，留下生還者自生自滅。我們原本以為只會看見小貓兩三隻，或許還有審問他們的機會。\n\n沒想到我們卻發現一群發狂的污水哥布林，瘋瘋癲癲的，還有嚴重的暴力傾向...我的意思是，比一般我們所知的情形還要嚴重。\n\n簡而言之，他們百害而無一利。為了諾姆瑞根，我們得盡力除掉他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25061] = {title = "天涯", objective = "到鋼火崗哨找凱爾希‧鋼火說話。", description = "噓!喂!靠近點，呆子，你要讓我猜你在想什麼還是─哎。靠近點就是了!\n\n你為諾姆瑞根做了很多，朋友!而且裝做一副你只是為了銀子的樣子，真是太厲害了。不過現在凱爾希‧鋼火還需要你再幫一點忙。\n\n她又跑出去了...她要我告訴你到南邊的天涯海灘和她碰面。我可不想讓她等太久!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25062] = {title = "為何而來", objective = "在污水置物箱中尋找線索。", description = "諾姆瑞根先前收到情報，部落的污水哥布林在抵達杜洛塔之前，曾落難在卡林多附近的一座無人島。我們來這裡就是為了調查是什麼樣的技術和科技，讓這群蠢貨在艱困的環境中存活下來。\n\n儘管哥布林正處於無所適從的狀態，我們還是要搞清楚到底發生了什麼事。在海灘上的殘骸和失物中尋找任何可能是關鍵的證據，帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25063] = {title = "海龜世界", objective = "從海浪龜身上取得烏龜消化過的鑰匙", description = "我們必須得到日誌裡提到的這個東西。我們很可能得從一個箱子內把它取出來，但這東西聽起來極不穩定。強行打開箱子可能會釀成嚴重的災難。\n\n幸虧我們知道鑰匙在哪裡...就統計學而言是如此啦。在海灘的最東邊有許多海龜。鑰匙就在其中一隻身上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25064] = {title = "摩拉雅", objective = "和摩拉雅談話。", description = "摩拉雅一直在找人幫忙處理迅猛龍。有機會的話，你應該到暗矛要塞另一邊和她談話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25065] = {title = "你也是嗎，蠻卒?", objective = "取得肉臉的箱子。", description = "是了結這檔事的時候了。根據我們的結論，日誌中提到一個「聰明」的蠻卒，這個神秘的東西就在他手中。我們不清楚這傢伙身上到底發生了什麼事，所以你務必當心。\n\n這個...「肉臉」就躲在山上的哥布林墓地附近。找到墓地，應該就能發現他的蹤跡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "肉臉懲戒錘光鮮護腕暗刺兇殺匕首諾姆瑞根功勳勳章肉臉的拍肉錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][25066] = {title = "凱贊之傲", objective = "射下10架諾姆瑞根隱形戰機。", description = "這太荒謬了!那些地精就是不知道何時該停止!\n\n哥布林的驕傲正岌岌可危!<name>，跳上凱贊之傲，讓他們搞清楚狀況!\n\n準備好時跟我講!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "槍手手套地精降落傘廢棄品槍手之握您會收到：\n\n"}
MultiLanguageQuestData['tw'][25067] = {title = "雷霆競技場:大巨人!", objective = "擊敗大巨人。", description = "規矩很簡單:兩個男人進去，一個...等等。有時候也會有女人。\n\n兩個人進去，一個...等等，不對，有時候比兩個還多...那就代表出來的人會超過兩個...\n\n好吧，唯一的規則就是待在場地裡面!沒有其他規則!\n\n你要先來挑戰廢土強盜中最大、最壞的成員。這要就是場暖身運動，要就是場血浴...看你來決定!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25068] = {title = "粉碎的過去", objective = "收集5個大地珠寶。", description = "漫遊在這些廢墟裡的生物是土靈，矮人古老的祖先，由泰坦製造出來，用以塑造這個世界。\n\n千年前，最原始的土靈崩潰後瘋了，而現在這些最新出土的看起來也沒甚麼不同。我們乾脆利用這些迷惑又精神不穩定的傀儡吧。\n\n進入廢墟摧毀土靈，然後收集他們身體內的珠寶;裡面的魔法能量既有價值又值得研究。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25069] = {title = "奧丹姆的秘密", objective = "在奧丹姆的前廳內尋找完整的神器。", description = "我們可以進入前廳了，<name>。這是值得紀錄的一刻。\n\n從你帶來的文字看來，我相信這些廢墟曾經是奧丹姆氣派的入口。將門撕裂的地震大概也震碎了裡面的通道，但我們也許還可以從裡面找到精采的東西。\n\n在廢墟裡搜索任何完好且可以研究的東西。發掘物事的快感等著你!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][25070] = {title = "裡頭的東西", objective = "擊敗前廳守護者。", description = "你把手放在箱子上，聽見微弱的聲響。箱子自動關上，後頭還傳來摩擦地面的回音。\n\n有東西朝你接近!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
