MultiLanguageQuestData['tw'][28017] = {title = "徵集冒險者:血色大廳", objective = "進入血色大廳。", description = "大酋長有令，所有身強體壯的冒險者都必須前往幽暗城東北方的血色大廳，不得拖延！\n\n血色十字軍已經在整個瘟疫之地與其他地方重新開始活動。大酋長相信他們即將死灰復燃，而我們絕不能容許這件事發生。\n\n進入血色大廳，在他們動員部隊之前徹底毀掉他們的軍火庫與圖書館。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28019] = {title = "徵集冒險者:血色修道院", objective = "進入血色修道院。", description = "大酋長有令，所有身強體壯的冒險者都必須前往幽暗城東北方的血色修道院，不得拖延！\n\n血色十字軍持續對被遺忘者要塞與整個瘟疫之地造成威脅。必須摧毀他們。\n\n到血色修道院去報到，執行大酋長的命令，一舉消滅血色十字軍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28021] = {title = "徵集冒險者:血色大廳", objective = "進入血色大廳。", description = "安杜因‧烏瑞恩國王有令，所有身強體壯的冒險者都必須前往幽暗城東北方的血色大廳，不得拖延！\n\n血色十字軍已經在整個瘟疫之地與其他地方重新開始活動。陛下擔心他們正在醞釀重振旗鼓。國王的領地附近絕不容許血色狂熱分子的出現！\n\n進入血色大廳，在他們動員部隊之前徹底毀掉他們的軍火庫與圖書館。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28023] = {title = "徵集冒險者:血色修道院", objective = "進入血色修道院。", description = "安杜因‧烏瑞恩國王有令，所有身強體壯的冒險者都必須前往幽暗城東北方的血色修道院，不得拖延！\n\n我們再三嘗試與血色十字軍進行交涉，但都失敗了。他們的狂熱分子蹂躪了整個瘟疫之地與其他地方。\n\n到血色修道院報到，實踐國王的正義。我們鼓勵使用致命武力！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
