MultiLanguageQuestData['tw'][28080] = {title = "徵集冒險者:斯坦索姆僕從入口", objective = "和十字軍指揮官艾利格‧黎明使者談話。安杜因‧烏瑞恩國王有令：\n\n所有身強體壯的冒險者都必須前往北地哨塔西北邊的斯坦索姆側門，不得拖延！\n\n奧里爾斯‧瑞文戴爾領主是前任白銀之手的聖騎士，也是瑞文戴爾男爵的親生子，但死而復生的他如今正領導著斯坦索姆裡的殘存部隊！如果你選擇執行這項任務，前往斯坦索姆側門和十字軍指揮官艾利格‧黎明使者談話，他是銀白十字軍奪回斯坦索姆行動的指揮官。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "安杜因‧烏瑞恩國王有令：\n\n所有身強體壯的冒險者都必須前往北地哨塔西北邊的斯坦索姆側門，不得拖延！\n\n奧里爾斯‧瑞文戴爾領主是前任白銀之手的聖騎士，也是瑞文戴爾男爵的親生子，但死而復生的他如今正領導著斯坦索姆裡的殘存部隊！如果你選擇執行這項任務，前往斯坦索姆側門和十字軍指揮官艾利格‧黎明使者談話，他是銀白十字軍奪回斯坦索姆行動的指揮官。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28081] = {title = "徵集冒險者:斯坦索姆僕從入口", objective = "和十字軍指揮官艾利格‧黎明使者談話。大酋長有令：\n\n所有身手矯健、四肢健全的冒險者都要前往北地哨塔西北邊的斯坦索姆側門，不得拖延！\n\n奧里爾斯‧瑞文戴爾領主是前任白銀之手的聖騎士，也是瑞文戴爾男爵的親生子，但死而復生的他如今正領導著斯坦索姆裡的殘存部隊！如果你選擇執行這項任務，前往斯坦索姆側門和十字軍指揮官艾利格‧黎明使者談話，他是銀白十字軍奪回斯坦索姆行動的指揮官。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "大酋長有令：\n\n所有身手矯健、四肢健全的冒險者都要前往北地哨塔西北邊的斯坦索姆側門，不得拖延！\n\n奧里爾斯‧瑞文戴爾領主是前任白銀之手的聖騎士，也是瑞文戴爾男爵的親生子，但死而復生的他如今正領導著斯坦索姆裡的殘存部隊！如果你選擇執行這項任務，前往斯坦索姆側門和十字軍指揮官艾利格‧黎明使者談話，他是銀白十字軍奪回斯坦索姆行動的指揮官。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28082] = {title = "徵集冒險者:通靈學院", objective = "進入通靈學院。", description = "安杜因‧烏瑞恩國王有令，所有身強體壯的冒險者都必須前往安多哈爾東方的通靈學院，不得拖延！\n\n近來這個地區的死靈活動都指向黑暗院長加丁，他企圖再次為天譴軍團訓練出強大的死靈法師。如果你願意幫忙，即刻前往瘟疫之地的通靈學院，把裡面的邪惡勢力都清除乾淨。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28083] = {title = "徵集冒險者:通靈學院", objective = "進入通靈學院。", description = "大酋長有令，所有身強體壯的冒險者都必須前往安多哈爾東方的通靈學院，不得拖延！\n\n近來這個地區的死靈活動都指向黑暗院長加丁，他企圖再次為天譴軍團訓練出強大的死靈法師。如果你願意幫忙，即刻前往瘟疫之地的通靈學院，把裡面的邪惡勢力都清除乾淨。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28084] = {title = "克羅姆加的力量", objective = "你現在可以使用克羅姆加的儲備物資了，<name>!只要花一點點費用，我就會賣給你一些軍備用品，這對於打倒你的敵人是非常有用的!我能賣給你什麼樣的東西端視你在軍隊中的階級而定。當你贏得新階級時，來我的店裡看看吧。\n\n不勝即亡!", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28085] = {title = "風巢之災", objective = "到千針石林的風巢找波卡‧捷山說話。", description = "謝謝你的幫忙，<name>。你應該到西南方的風巢向波卡‧捷山說話。\n\n也許他知道年邁的長者去了哪裡？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28086] = {title = "解救小傢伙", objective = "解放12隻風巢的幼小雙足飛龍。", description = "那些陷捕者正在捕捉所有的幼小蠍尾獅，<name>，你可以去解救那些幼龍嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28087] = {title = "所有陷捕者的死期!", objective = "收集8張陷捕者網子。", description = "對付那些卑劣的暮光之錘陷捕者只有一個辦法!那就是死!\n\n把他們的網子帶來給我，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "迅捷登山長靴陷捕者頭盔波卡的腰帶陷捕者打孔手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][28088] = {title = "釋放撕心者", objective = "將撕心者從束縛中釋放出來。", description = "暮光之錘捉住了風巢的首領。你必須趕緊爬上東邊的斜坡釋放撕心者，不要讓雙足翼龍失去了一族之長。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28089] = {title = "大酋長的命令：希爾斯布萊德丘陵！", objective = "到希爾斯布萊德丘陵的南點大門向高階執行官達薩利亞報到。", description = "所有身強體壯的部落成員必須聽命前往希爾斯布萊德丘陵的南點大門，向高階執行官達薩利亞報到。被遺忘者的部隊正不斷推進，為部落拿下整個羅德隆地區！\n\n要前往南點大門，順著向南的道路穿過銀松森林，再走向東延伸至希爾斯布萊德丘陵的岔路。\n\n兄弟姊妹，前進吧！命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28090] = {title = "珍貴的貨物", objective = "尋找一塊暮光之錘門石。矛衛兵身上應該有能讓你打開箱子的鑰匙。", description = "在峽谷更深處的門都緊閉著。我們偵察後，發現他們放在車隊上的箱子裡的某種門石可以用來打開這些門。\n\n過去找找看守衛的屍體上有沒有箱子的鑰匙。找到後，打開車上的箱子並將門石帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "長遠仇恨頭盔壓箱護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][28091] = {title = "不是對手", objective = "殺死8個暮光矛衛兵。", description = "突襲進行的很順利。大部分守衛已死了，但有些還被貨運馬車壓住。\n\n你可以在我們西邊下面的峽谷裡看到他們。過去將他們都處理掉好讓我們的攻擊能繼續向前推進。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28092] = {title = "若鑰匙吻合", objective = "帶領哥布林戰隊到關閉的龍喉大門。\n\n若你與哥布林戰隊走散了，回去與督軍克羅格交談，請他派遣一支新的戰隊給你。", description = "龍群們已經在格瑞姆巴托的空中開始戰鬥了。剩下就等我們的人進去佔領大門。\n\n我想你該知道在這緊要關頭最重要的是什麼，<class>。格瑞姆巴托是暮光之錘給整個高地派遣援軍的源頭。若沒有在這裡將源頭中斷，我們就無法贏得後面的戰爭。\n\n我會遣派哥布林戰隊跟你一起過去。前往東南邊的門並將它打開。派奇會給你更多需要的資訊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28093] = {title = "往前邁進", objective = "帶領哥布林戰隊經過西南方的龍喉大門到格瑞姆巴托的入口。\n\n若你與哥布林戰隊走散了，回到龍之彎道請督軍克羅格重新指派。", description = "到目前為止幹得還不錯。通過下一道門，應該就會看見格瑞姆巴托的入口。\n\n我的任務是要在其他兵力沿著我們清空的峽谷進軍時，守住入口並阻擋敵方援軍。我在想如果我們能夠提早到，也許可以讓提克爾先玩樂一下。\n\n到峽谷西南方去吧!我們應該可以很快找到下一道門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "破門者足靴中隊隊長手套悍勇指引披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][28094] = {title = "鋪路", objective = "在前往格瑞姆巴托入口的途中，沿著巨龍之彎殺死30個暮光之錘教徒。", description = "我奉令伴隨你往南，穿過龍喉小徑抵達格瑞姆巴托。我們已清出一條路讓剩下的人可以跟著上去佔領入口。\n\n以上翻譯為:將所有會動的東西殺掉，若你為了可以這樣做感到開心，不必害羞。\n\n我們的人也在蠢蠢欲動了。走吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28096] = {title = "核心機構歡迎你", objective = "分配3項任務。", description = "來這裡，親愛的<小男孩/小女孩>，抽個雪茄。作為被遺忘者的高級軍官，你將會平步青雲的。沒錯，的確，這就是你將要過上的美好生活!\n\n我要你接下這些命令，把它們丟給來找工作的那群下等人去做。你高興要誰幹嘛就幹嘛。\n\n當你準備好，騎上我可靠的骷髏戰馬，這樣他們才不會輕視你，然後開始享受人生!所謂享受人生就是待在那裡等就好。", progress = nil, completion = "那麼，情形如何?就像你夢想中的一樣嗎?興奮嗎，沒有?\n\n不興奮?\n\n&lt;達薩利亞嘆口氣。&gt;\n\n我看得出你是個真正的英雄。你想進行任務。我猜「出一張嘴」的任務不適合你。", rewards = "提示手套任務給予者的肩鎧可攜式折疊桌連勝鎖甲手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][28097] = {title = "格瑞姆巴托之門", objective = "到巨龍之彎與督軍克羅格說話。", description = "克羅格開始往峽谷逼近進攻。他剛經過我們東南方的閘門。\n\n我先召集小隊準備開始攻擊。我們等等在下面會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28098] = {title = "暮光飛行師", objective = "讓撕心者載你到暮光高巢，除掉暮光飛行師瑞奇歐分。", description = "暮光飛行師瑞奇歐分就在東南方的暮光高巢上。不論我們在下頭做什麼，只要沒解決掉他，風巢就沒有未來。\n\n撕心者傷得太重，無法協助你戰鬥，但牠可以載你飛上那裡。剩下的就靠你自己了，<name>。\n\n祝你好運。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "小飛龍絨毛護腿撕心者的贈禮飛行師的束褲自尊持護者胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28099] = {title = "拉沙克拉克", objective = "取得拉沙克拉克的地縛護腕。", description = "根據你的消息，我相信已經有一個「大公」的爪牙，準備對瑟銀哨塔下手。\n\n他的名字叫拉沙克拉克，就在我們南邊熔岩池附近巡邏。他看起來和附近狂怒的火元素沒兩樣，唯一的不同，在於他手上的護腕。\n\n找到他，把他的護腕帶回來給我，<name>。在我們涉入元素戰爭之前，我需要證明我們已經身處危險之中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28100] = {title = "會說話的圖騰", objective = "在死木村附近與魯姆波圖騰交談。", description = "在這裡南邊的熊怪村莊是木喉的死敵死木部落的家園。他們和各種其他生物一樣被腐化了，受到這座森林的污染影響而變得瘋狂。\n\n然而在村莊的附近發生了一些不尋常的事。根據來到這裡的旅人們的描述，在路邊的圖騰曾經和他們說話。\n\n然而每次我靠近它都沒有聽到任何東西。也許它會和你說話，<name>？也許你可以幫我找出到底發生了什麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28101] = {title = "馬迪亞斯的指示", objective = "到龍喉小徑找馬迪亞斯‧肖爾說話。", description = "最近幾件事讓我更加明白，一直躲在這兒，對格瑞姆巴托發動幾波零星的攻擊，並不是保全我族的長遠之計，更別說是奪回格瑞姆巴托了。我們必須更積極些，朝他們的心臟進攻。\n\n我已經答應派幾隻龍協助你的指揮官。他們正在策動一波針對格瑞姆巴托的攻擊，這應該是你的當務之急。\n\n你可以在龍喉小徑找到馬迪亞斯‧肖爾，就在我們下方的峽谷南邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28102] = {title = "打擊力量", objective = "在克斯特拉斯廢墟殺死8名碧火盜賊或是碧火巡影者。", description = "該是給那些碧火薩特最後一擊的時候了!\n\n如果你已準備好突破他們邪惡的魔法障壁，並且與他們的領導者進行決戰，我打算同時要求你幫忙對付那些較次級的薩特。我們的德魯伊勇猛的戰鬥著，但你的力量可以有效的幫我們扭轉戰局。\n\n讓那些碧火薩特知道他們的力量再也不能控制這些土地!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28103] = {title = "軟柿子", objective = "殺死8個暮光持矛衛兵。", description = "埋伏進行得很順利。大部份的守衛都死光了，只剩下一些還死守貨車作困獸之鬥。\n\n到那裡去清光他們，我們才能繼續朝峽谷邁進。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28104] = {title = "珍貴的貨物", objective = "取得暮光商隊門石。那些持矛衛兵身上應該有一把鑰匙，能開啟裝著石頭的箱子。", description = "敵人關閉了峽谷前方的大門。根據斥候回報，他們的商隊在箱子中攜帶了一顆石頭，是他們用來開啟大門的工具。\n\n到那裡去搜尋守衛的屍體，找到打開箱子的鑰匙。找到後，就用它打開商隊貨車上的某個箱子，再把門石帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "守門者頭盔長矛穿刺護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][28105] = {title = "無情的卡維姆", objective = "從無情的卡維姆身上取得奈斐賽特鑰匙。", description = "在奈斐賽特受雇於死亡之翼之前，卡維姆就已經夠殘忍的了。他從別人的痛苦中得到快樂的行為已經近乎瘋狂。\n\n他握有我們身上鐐銬的鑰匙。\n\n他住在我們旁邊的建築物裡，就是我右手邊那座。\n\n找到他並從他身上取得鑰匙。不要猶豫或是憐憫他。他會甚麼都不想的切開你的喉嚨。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "卡維姆的綴飾護胸鑰匙竊賊裹手珍珠長柄槍您會收到：\n\n"}
MultiLanguageQuestData['tw'][28106] = {title = "The Gates of Grim Batol (DO NOT DELETE, DO NOT DEPRECATE!)", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28107] = {title = "鋪路", objective = "在前往格瑞姆巴托入口的途中，沿著巨龍之彎殺死30個暮光之錘教徒。", description = "我的任務是要陪同你往南通過龍喉大門，前往格瑞姆巴托的入口。我們必須清出一條路，讓其他人可以跟上我們並守住入口。\n\n我來翻譯一下:就是殺死每個會動的東西，要是你覺得樂在其中，也別感到羞愧。\n\n那些小夥子已經蠢蠢欲動了。我們走。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28108] = {title = "若鑰匙吻合", objective = "帶領高岸堡小隊前往緊閉的龍喉大門。\n\n要是你和小隊走散了，就去找馬迪亞斯‧肖爾重新指派一個小隊。", description = "巨龍已經飛到格瑞姆巴托上空，加入戰場。這會兒就看我們的地面部隊能不能進到那裡守住大門了。\n\n我希望你知道這其中有什麼危險，<class>。暮光之錘在高地的援軍全都來自格瑞姆巴托。要是我們不能從這裡斬斷他們，就無法拿下往後的戰役。\n\n我從高岸堡為你調來了一支小隊。去開啟東南方的大門。你的中尉會在那裡下達進一步指示。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28109] = {title = "往前邁進", objective = "帶領你的小隊通過北方的龍喉大門，抵達格瑞姆巴托的入口。\n\n如果你和小隊走散了，就到龍之彎道找馬迪亞斯‧肖爾重新指派一個小隊。", description = "到目前為止幹得還不錯。\n\n通過下一道門，應該就會看見格瑞姆巴托的入口。我的任務是要在其他兵力沿著我們清空的峽谷進軍時，守住入口並阻擋敵方援軍。\n\n我們得繼續沿著峽谷往西南方前進。下一道門應該馬上就在眼前。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "指揮官踏靴擊門護手偉大領導披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][28111] = {title = "碧玉礦坑的麻煩", objective = "到希爾斯布萊德丘陵的碧玉礦坑向吉頓隊長回報。", description = "我們在碧玉礦坑的蜘蛛農場生產量停滯不前。吉頓隊長要求我們立即增援。吉頓說礦坑蜘蛛拒絕聽命，還到處發狂。更糟的是，海岸邊的魚人還在搶奪我們的補給品。我要你到那裡去看看狀況。去幫幫吉頓和蜘蛛管理員，<name>。\n\n你會在東南方的海岸附近找到碧玉礦坑。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28112] = {title = "逃出失落之城", objective = "釋放納登親王，並到奧丹姆的蘭姆卡韓去和法歐瑞斯王交談。", description = "萬事齊備!解開我的鎖鍊並放你朋友自由。\n\n我們必須在那些奈斐賽特雜碎發現我們在做甚麼之前趕快離開!\n\n如果我們能成功，你就去跟我的兄弟法歐瑞斯王領賞。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n皇家的獎賞蘭姆卡韓勇氣徽章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][28113] = {title = "突破不可突破的屏障", objective = "殺死薩瓦瑟拉斯。", description = "有了提克迪奧斯之爪的幫助，我們準備好突破碧火的防線了。\n\n前往西北方的廢墟。在那些薩特的前線後方你將會找到一條狹窄的小徑，通往他們被污染的月井。在那裡一座巨大的惡魔火焰牆阻擋著道路，但是提克迪奧斯之爪的力量應該能夠將它解除。\n\n在這道屏障後方，你將找到他們的領袖，薩瓦瑟拉斯，守衛著被污染的月井。到那裡去殺死他!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "戴拉瑞斯的手套開展手套破法者頭盔惡魔碎擊者您會收到：\n\n"}
MultiLanguageQuestData['tw'][28114] = {title = "大豐收", objective = "找到60個食苔蛛的卵。", description = "在南點大門的正東南方，你會找到我們的蜘蛛馴養場。這些年來我們將希爾斯布萊德的蜘蛛培養出了幾代，也試著馴服並養育這些可愛的小生物。現在蜘蛛對我們來說就像是一般的家庭寵物，也是戰場上的野獸!牠們真是變化多端的生物!\n\n我要你到東南方的農場上去，小心的把我們在熊身上培養的卵採回來。把收成送到礦坑給薩魯斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "蜘蛛管理員披肩熊皮外衣爬行長靴網刻套衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][28115] = {title = "年老體衰", objective = "消滅8隻受感染的熊。", description = "熊是沒有靈魂的生物，生在這世上只會來煩我們。只有以被遺忘者的聰明才智。才讓這些熊反過來有點用處!我們把熊拿來用在我們的蜘蛛農場上，當作活蜘蛛卵的養分。我們的蜘蛛在熊身上產卵，卵就在那些野獸的血肉裡成長茁壯。\n\n熊的養分用完以後就要被殺死。到東南方去殺了那些已經衰老的受感染的熊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28116] = {title = "泣鳴紫羅蘭", objective = "收集8株泣鳴紫羅蘭。", description = "在我們對加德納爾發動突襲前，必須謹慎的進行我們的準備工作。加德納爾裡的那些術士和惡魔擁有非常強大的魔法，在我們進去以前得為自己做好防護。\n\n我們現在還需要再多一樣要素:泣鳴紫羅蘭，就長在敵人堡壘的西北邊的山丘上。\n\n幫我收集這些泣鳴紫羅蘭，然後到戰場上和我的助手碰面。他會知道下一步要怎麼做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28117] = {title = "清理深淵", objective = "你被要求要到巴拉丁堡東邊的詛咒深淵去殺死任意9個鬼魂。", description = "看見你真好啊，<name>。雖然我們拿下了托巴拉德，但是戰鬥才正要開始而已。\n\n我們在東邊發現了一區牢房，需要你去清理一下。有一大群鬼魂塞在裡頭，天曉得他們已經被鎖在那裡多久了。\n\n盡你所能把那裡清乾淨，完成之後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28118] = {title = "被監禁的大法師", objective = "你必須到巴拉丁堡東邊的詛咒深淵去，殺死大法師加魯斯並把他的法杖帶回來。", description = "我們到達托巴拉德之後，就一直嘗試要清理詛咒深淵的牢房。每次我們快完成目標的時候，就會出現一個大法師把我們逼退回來。\n\n現在我們已經取得這個島嶼，是再嘗試一次的時候了。到那裡去，把他的法杖帶回來給我，證明你已經完成工作。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28119] = {title = "淨化腐敗", objective = "在加德納爾的中心用被腐化的月井水裝滿空壺。", description = "你帶給我的花是不可或缺的一部分要素。\n\n在暗影堡的四周籠罩著由惡魔火盆製造出來的保護屏障。如果我們想要將暗影議會趕出費伍德森林，就得先撲滅那些火盆。\n\n在這個瓶子裡，注入了泣鳴紫羅蘭與野性的魔法。到加德納爾中心被腐化的月井去裝滿它。當你完成以後回到我這。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28120] = {title = "從經驗中學習", objective = "你被要求要到巴拉丁堡東邊的詛咒深淵去取回4本布滿灰塵的監獄日誌。", description = "現在我們終於在這個荒涼的島嶼上有座堡壘了。我們可以開始調查為什麼它會落到現在這個地步。我們有些部隊在東邊的詛咒深淵牢房入口處附近發現一些日誌。\n\n這些日誌非常吸引我們營區裡的資深抄寫員。我需要你儘快去帶四本回來給我。\n\n<name>，在那裡要小心，那邊到處爬滿了不死怪物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28121] = {title = "加德納爾的軍隊", objective = "殺死12名加德納爾精兵。", description = "暗影議會造成了這塊土地的腐敗。他們在西北邊的加德納爾膜拜燃燒軍團的惡魔，並且為了替他們主人打開回到這個世界的道路而工作。\n\n暗影議會的加德納爾惡犬、守護者、精兵斥候和教徒在地面上巡邏，其他的惡棍則負責看守著通往地底的邪惡力量的道路。為了不讓這些森林承受更多的苦難，我們首先就得把他們給除掉!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28122] = {title = "天大的問題", objective = "你受命殺死普拉卜林姆，漫遊在托巴拉德道路上的雙頭巨人。", description = "我們終於奪得這個被神遺棄的石頭，卻發現有個雙頭巨人在四處漫遊，放倒我們的巡邏哨兵!\n\n<name>，我需要你召集幾位朋友，解決掉雙頭巨人。我們不能讓這種野獸到處撒野，製造破壞。保持警覺，根據前線情報，雙頭巨人拿著一顆天大的樹當武器，而且不怕使用它。", progress = nil, completion = "你真的殺了他？！真不敢相信！", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28123] = {title = "惡魔鎖鍊", objective = "取得惡魔鎖鍊。", description = "納克拉爾曾向我展示他駕馭此地龍族的秘密。我本以為惡魔鎖鍊只是一個傳說，不過那東西一直都在他手上。\n\n現在這個笨蛋就要把它弄丟了!\n\n他的性命對我來說毫無意義，不過龍喉部族不能承受失去這個神器的結果。跟著他前往北方，進到桑德瑪。這座城市現在陷入一團混亂，所以你可以在不被發現的狀況下降落在那裡。就算得從納克拉爾的屍體上拿出來，你也要把惡魔鎖鍊帶回來給我。\n\n找到那件神器，<name>!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28124] = {title = "前進暮光壁壘", objective = "到千針石林的暮光壁壘找拉克塔‧風歌說話。", description = "<name>，當你正在和雙足翼龍設法除掉飛行師時，拉克塔‧風歌來過一趟，她要我告訴你到東邊的暮光壁壘去找她。\n\n那裡一定就是他們關住瑪加薩‧恐怖圖騰的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28125] = {title = "人要衣裝", objective = "收集10件暮光之錘護甲。", description = "我有個主意，可以讓你接近他們的領導人還能保住小命。不過首先，你得找點衣服穿。\n\n我建議你到那去，把他們的護甲拿來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "拉克塔的釘錘千錘百鍊盾牌染血暮光腰帶拉克塔的裁決錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][28126] = {title = "澆熄防護火焰", objective = "使用淨化過的月井水澆熄暗影堡內的4座防護火盆。", description = "那些火盆散佈在暗影堡的四處。\n\n從地道進入暗影堡，然後沿著它穿過地底的通道。澆熄每一個火盆的火焰，這至少能暫時破壞暗影議會所建立的防護結界。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "失落古墓腰帶碧玉肩甲聖堂肩鎧翡翠寶珠您會收到：\n\n"}
MultiLanguageQuestData['tw'][28127] = {title = "劫囚", objective = "從暮光獄卒手中救出5個亡靈壁壘囚犯。", description = "暮光之錘不只俘虜了瑪加薩。\n\n當你到南邊時，記得救出其他俘虜，救幾個是幾個。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28128] = {title = "內部議會", objective = "殺死暗影堡內12名防衛者。", description = "他們外部的哨兵已被清除乾淨，接下來輪到暗影議會更高階的成員了。\n\n在這腐敗的地穴深處裡，你將會遭遇到強大的加德納爾術士、獵人、執行者、暗織者以及軍團士兵。\n\n為了拯救這些土地，我們一定得擊敗他們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "影持釘錘月弓純淨加德納爾護符暗影堡匕首您會收到：\n\n"}
MultiLanguageQuestData['tw'][28129] = {title = "惡魔王子", objective = "殺死薩瓦利斯王子。", description = "這些遍佈費伍德森林的碧火薩特與暗影議會根本上是一夥的。\n\n這些薩特直接聽命於古老而強大的薩瓦利斯王子。有些人說他是薩格拉斯親自給予祝福的第一個薩特，薩維斯的兒子。\n\n不管他是怎麼來的，如果我們想削弱碧火薩特的力量並奪回我們的獸穴，薩瓦利斯就一定得死。深入暗影堡去把他殺了。不要對他手下留情;他對你可不會這麼做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28130] = {title = "不是最友善的城鎮", objective = "馬庫斯‧強森要你去鏽堡村殺死14個村民。鏽堡村在營地南邊，就在右手邊的位置。", description = "<name>，你有去過鏽堡村嗎？如果你要往那個方向走，我建議你在身上帶把磨利的尖刀。\n\n那個城鎮的人們表面上看起來很好，但有些可疑的事情正在那裡進行。根據回報指出，他們正在消滅我們附近的士兵。我們已經受夠了，所以我需要你去那裡幫我們清掃一下。\n\n盡你所能殺光他們，完成之後向我回報。", progress = nil, completion = "就跟你說那個村莊裡都是瘋子。把那裡清乾淨真是做得好，&lt;name&gt;。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28131] = {title = "雙生女魔", objective = "殺死米萊恩和薩莉亞。", description = "米萊恩和薩莉亞是暗影領主費爾丹的私人女僕。別被她們的外表給欺騙了!\n\n這些邪惡的魅魔使用她們的花招和邪惡魔法將凡人拉進暗影堡的深處。那些落入她們手中的人都會受到洗腦，或是由費爾丹將他們奉獻給他的惡魔主子。\n\n這兩個魅魔戰鬥起來就彷彿是一個人，而且總是形影不離，這使她們變得更加危險。到暗影堡去殺死她們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28132] = {title = "有效率的挖掘法", objective = "將「有效率的挖掘法」帶去舒諾茲營地給貝洛克‧亮刃。\n\n已提供物品：\n", description = "這本手冊上的外國理論，詳述了如何在大隊工作人員從事大規模挖掘行動時，對他們進行最有效的管理。\n\n快速地掃描了一番，你立刻理解到就是這本書的作者領導著那群過度富有侵略性的劫掠者。\n\n書後有份地圖，指出這作者在奧丹姆西南邊的區域有個碉堡。\n\n也許你該去自我介紹一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28133] = {title = "解放狂怒", objective = "前往水道和札伊拉談談。並殺死托斯。", description = "在對桑德瑪那場失敗的攻擊行動中，納克拉爾的龍活了下來，牠叫做托斯，這隻龍現在獲得自由，不受牠前一個主人的控制了。\n\n托斯想對龍喉部族展開報復，而牠已經對鮮血峽谷發動過一次攻擊。在把牠永遠串在竿子之前，牠還會不斷回來。是時候讓惡魔鎖鍊發揮效果了。\n\n托斯的舊巢穴是位於此地西方山丘的一個小洞穴，我們已將那裡變成了一個叫做「水道」的小營地。\n\n去水道和我碰頭，我們來終結托斯的性命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "水道釘錘洞察力護腰龍怒護手堡壘淨化護腿托斯殺手法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][28134] = {title = "隨之而來的報復", objective = "到塔雷特營地找諾瑪屈‧泰尼斯談話、到太陽之王封印找太陽牧師阿薩里斯談話、到瑪拉特找阿薩克談話。", description = "既然你已經獲得了適當的獎賞，我希望現在我能坦誠地告訴你。\n\n雖然你幫了我們王國一個大忙，但你也擾亂了脆弱的和平商議過程。\n\n我本來只想藉由外交手段來釋放我兄弟，以避免流血傷亡。\n\n但現在敵人肯定會進行報復。\n\n到東邊的塔雷特營地去找諾瑪屈‧泰尼斯，到北邊的太陽之王封印去找太陽牧師阿薩里斯，還有到西邊的瑪拉特去找阿薩克，並和他們交談。找出敵人會從哪裡攻過來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28135] = {title = "奧拉基爾的復仇", objective = "和奧丹姆的阿爾沙德交易站的納登親王談話。", description = "聽著，<name>。襲擊奧爾希斯的不是自然的沙塵暴。是奧拉基爾的爪牙。\n\n風元素領主是死亡之翼的有力盟友，他遲早都會對我的同胞出手。\n\n奧爾希斯的攻擊事件是對我們的警告。我們必須快點行動，為我們的同胞提供援助。\n\n到瑪拉特外的阿爾沙德交易站和納登碰面。我要開始準備照顧流離失所者和受傷的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28136] = {title = "在你後面!", objective = "暗殺密碼大師迪梭克、指揮官快線、元素師斯塔利恩。", description = "暮光壁壘的三個領導者，各個都是狠角色，不容小覷，<name>。不過幸好，你的偽裝會讓你看起來像是不折不扣的暮光教徒。\n\n你必須穿上偽裝，分別與密碼大師迪梭克、指揮官快線、元素師斯塔利恩交談。找機會讓他們背對你，趁這個時候迅速擊斃他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "斯塔利恩的軟靴密碼大師的腕輪快線手套領袖壁壘您會收到：\n\n"}
MultiLanguageQuestData['tw'][28137] = {title = "教他釣魚...或用偷的", objective = "你必須到鏽堡村去取得22份鏽堡村海鱸。你可以在村莊後方的碼頭的帶狀區域找到魚。鏽堡村在營地北邊，就在右手邊的位置。", description = "鏽堡村。那個地方是我們的詛咒也是祝福，<name>。我不知道那些暴徒是怎麼學會像那樣抓魚的，但我現在沒時間擔心那個。\n\n我需要你到那裡去，儘可能把他們的魚貨偷來。自從我們收復這座島嶼就一直以吃殘羹維生，這是我們能取得真正食物的最佳機會。\n\n在那裡要特別留意潛行者，報告指出他們遍佈在村落的牆壁裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28138] = {title = "人類橫行", objective = "抓到8個希爾斯布萊德人類。", description = "這個礦坑一度是聯盟在希爾斯布萊德的採礦活動中心。它現在是我們忠誠蜘蛛的繁殖地，不過人類在某種方面還是佔據著它。\n\n<吉頓咧嘴笑了。>\n\n但是回到正事!管理員斯蒂沃特要求更多工人到淤泥農場去。我要你帶著這些鐐銬進入礦坑，抓捕希爾斯布萊德的人類到農場做工。\n\n將他們從讓他們癱瘓的網中救出來，然後將他們打到服從再銬上鐐銬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "軍官的臂環奴隸商人護腿禁錮之鏈網織護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][28139] = {title = "密碼大師的密碼", objective = "取得密碼大師的密碼。", description = "<name>，他們在瑪加薩的鐐銬特別上了密碼。要釋放她就得取得密碼。\n\n東南方暮光壁壘的密碼大師迪梭克身旁有個特殊的裝置。密碼就在裡面。\n\n請你務必得到它。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28140] = {title = "長者", objective = "關閉瑪加薩的鐐銬控制器。", description = "你得到了密碼。現在你要做的，就是到壁壘東側，釋放長者。\n\n祝你好運，<name>。謝謝你所做的一切。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28141] = {title = "太陽之王的神器", objective = "取得4個太陽之王的神器。", description = "太陽之王封印為蘭姆卡韓提供了保護機制。\n\n奧丹姆四周的關卡陷落後，我們就看到從塔納利斯來的廢土先遣軍進入我們的邊界。\n\n他們在往西的途中攻擊這個神聖的場所，搶走曾給予我們力量的神器。\n\n幫我們找出神器。少了它們，我們就無法在沙漠中對攻擊做出防禦。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28142] = {title = "暮光枯萎之地", objective = "在千針石林的暮光枯萎之地和瑪加薩‧恐怖圖騰談話。", description = "根據瑪加薩所言，她會在東邊的暮光枯萎之地外面和你碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28144] = {title = "偷偷摸摸的小怪物!", objective = "找回6個被遺忘者營地的「補給品」。", description = "我們正南方那條由西向東延伸的漫長海岸線，名叫西部海岸。沿著西部海岸你會找到兩樣東西:魚人和我們失竊的「補給品」。\n\n<吉頓把手舉在空中用手指做出引號。>\n\n那些該死的鬼祟魚人趁我們不注意的時候跑來偷走我們的「補給品」。\n\n薩魯斯和我不能離開崗哨。我們需要你到西部海岸找回那些「補給品」!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28145] = {title = "毒血解毒劑", objective = "從8隻毒血蠍的屍體上收集毒液，把解藥瓶裝滿。", description = "伊賽特試圖在廢土強盜進行掠奪時，保衛這片神聖的土地。\n\n他們似乎使用了存在於毒血蠍中的強力毒素。\n\n帶著這個瓶子，從牠們的屍體上蒐集毒液，如此我或許可以調製出一種解毒劑。我害怕伊賽特沒剩多少時間可活了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "黑暗金字塔護腕瑪拉特腰帶閃亮蠍眼您會收到：\n\n"}
MultiLanguageQuestData['tw'][28146] = {title = "沿岸好味道!", objective = "將西部海岸的12個魚人餵給飢餓的礦坑蜘蛛吃。", description = "我的蜘蛛又餓又生氣!牠們好幾天沒吃東西，現在開始吃我們的人類俘虜了。不能這樣。那些人類在淤泥農場有用處。\n\n我要你帶一隻饑餓的礦坑蜘蛛出去，餵牠吃南邊那條西部海岸上的魚人。不管你殺掉什麼，牠都吃!越多越好!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28147] = {title = "你適合紫色", objective = "收集8個暮光服飾碎布。", description = "就我所知，洞穴外的噁腸巨魔還沒加入暮光之錘。如果我們機伶點，就可以讓他們和彼此對抗。\n\n來玩個我在希利蘇斯學到的把戲吧。首先，我們要幫你收集一套教徒長袍。\n\n到南邊的暮光裂層殺幾個暮光扭風者。這不僅可以破壞他們在進行的行動，還讓你有機會湊衣服。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28148] = {title = "找出被污染者", objective = "從怒爪熊或是魔爪狼的身上收集10張腐化毛皮。", description = "這個令人作噁的惡魔污染滲進了整座森林。土壤、樹木、動物...所有的東西都蒙上了厚重的邪惡魔法。\n\n我們翡翠議會誓言淨化這座森林，而這件事將需要長期的抗戰。在這裡的一些生命仍然有被治癒的機會，不過在附近漫遊的熊與狼已經被扭曲得太嚴重了。\n\n我們得終結牠們的痛苦，並保證牠們的屍體不會將污染散佈得更嚴重。獵殺這些熊群和狼群，然後帶著牠們的毛皮回到我這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "怒爪護腿魔爪長靴聖堂腰帶紅羽指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28149] = {title = "風中的呢喃", objective = "收集1個語風者符咒與5個漩渦之息。", description = "你聽到了嗎，<class>？從洞穴傳來的聲音。他們想要說話，但是他們已經沒有了呼吸。\n\n讓我們找個方法。暮光之錘，他們可以和風交談。到南邊的暮光止境去，從營地裡把語風者符咒帶來。那東西會在其中一根石柱的頂端。\n\n我們還需要元素的呼吸！殺死風暴漩渦以取得你需要的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28150] = {title = "秘法同盟", objective = "在克斯特拉斯廢墟與秘法師戴拉瑞斯交談。", description = "翡翠議會誓言接受任何願意在費伍德森林與惡魔作戰者的幫助。雖然我的人民已經躲避秘法很長一段時間了，但我們沒辦法拒絕它在這裡所能帶來的利益。\n\n秘法師戴拉瑞斯，一個精靈貴族的倖存者，在與碧火薩特的戰鬥中幫了我們不少忙。沿著這條路往北，你會在我們俯瞰克斯特拉斯廢墟的營地裡找到她。\n\n如果你願意幫忙淨化費伍德森林的話，就像你先前為我做的一樣聽從她的指示。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28151] = {title = "整裝為殺戮", objective = "消滅10個噁腸巨魔。進入噁腸谷之後你的暮光之錘偽裝會自動啟動。", description = "你已經偽裝好了，<name>。不論何時前往北邊的噁腸谷，你的暮光之錘裝扮都可以騙過巨魔。\n\n接下來的計畫就很單純了:殺他一票的噁腸巨魔，他們就會怪在暮光教徒身上。你準備好到巨魔營地搞破壞了嗎？我想沒錯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "巨魔殺戮者胸鎧偽夜護腕教派潛伏肩甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28152] = {title = "拜訪加德納爾", objective = "將秘法師的草藥帶去野性之心營地給格雷塔‧苔蹄。", description = "你所看到那些看守提克迪奧斯之爪的教徒是暗影議會的成員，他們是一群想將惡魔帶到艾澤拉斯來的邪惡術士。\n\n加德納爾就位於這裡的北方，它的名字是從他們所膜拜的基爾加丹而來。在它底下就是暗影堡的所在，那是個古老的獸穴，也是暗影議會設立於艾澤拉斯的堡壘。\n\n帶著這些草藥到北邊道路東側的野性之心營地。格雷塔‧苔蹄將可以利用它們進行淨化暗影堡的計畫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28153] = {title = "暗影領主費爾丹", objective = "消滅暗影領主費爾丹。", description = "暗影領主費爾丹在深淵中等待著，<name>。\n\n你殺了他心愛的寵物，他的憤怒將無可抑止。即使身邊沒有米萊恩和薩莉亞，他的力量也是難以對付。\n\n當心他的黑暗力量;他現在已經更接近惡魔，而不是獸人了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28154] = {title = "泥鰓的蹼之類的...", objective = "將泥鰓的鰭送去希爾斯布萊德丘陵的碧玉礦坑給吉頓隊長。", description = "這看來像是泥鰓的蹼之類的。也許有人很介意你在碧玉礦坑營地殺了這隻魚人。可能並沒有，但是可以這麼猜。\n\n帶著這個泥鰓的鰭之類的玩意到西南希爾斯布萊德的碧玉礦坑去找吉頓隊長。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "吉頓的束帶軟綿綿肩衛吉頓的鎖甲肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][28155] = {title = "貝恩霍勒領主", objective = "消滅貝恩霍勒領主。", description = "潛伏在暗影堡深淵的最後勢力就是貝恩霍勒領主。\n\n暗影議會為他做事，就連費爾丹對他而言也只是個用來讓燃燒軍團再次侵略這片土地的工具。\n\n小心行事，<name>。驚懼領主是個可怕的敵人。昂首取得勝利吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "淨化過的暗影議會腰帶法爾魯斯的法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][28156] = {title = "礦坑深處救援", objective = "護送杜瑪斯到安全處!", description = "<你可以透過蜘蛛網聽到杜瑪斯說話。>\n\n「嗨！到處都是蜘蛛！隊長派我來拯救世界還有抓人類！但這裡到底是哪？好熱啊！我…」\n\n<杜瑪斯一直說著自己的處境。>\n\n也許你應該把他安全的救出來。或者你也能把他留在這裡，雖然最初是你害他陷在礦坑裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28157] = {title = "四種暮光元素", objective = "收集四種暮光元素:空氣、土、火和水。", description = "暮光之錘召喚出一種怪物。它不僅是四種元素的集合體，還注入了源質礦的能量。\n\n如果你想拯救心愛的千針石林免於徹底毀滅的命運，就必須摧毀那個怪物。不過首先，你需要幾樣東西，才能突破它的護盾。\n\n到東邊的枯萎之地去，帶回四種暮光元素。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28158] = {title = "束縛解放", objective = "解放被束縛的火元素和被束縛的漩渦。", description = "暮光之錘禁錮了兩個非常強大的元素。他們利用被束縛的火元素和漩渦，賦予元素憎惡體無比的力量。\n\n當元素憎惡體吸飽了它們的能量，他就會爆炸。整個千針石林和附近的區域都會化為烏有。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28159] = {title = "末日石", objective = "取得末日石。", description = "元素憎惡體的核心是一個叫做末日石的神器。它其中一個特性是能吸收大量能量。\n\n那些教徒於是想藉此引發大爆炸...讓石頭超載，透過元素增強能量。\n\n把末日石拿來給我。當然我只是想保管它而已。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "安全保存護腕枯萎面具髒活護脛受騙傀儡護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][28160] = {title = "散播傳言", objective = "在千針石林的菲茲爾與普茲克的高速駁船和菲茲爾‧銅栓談話。", description = "因為你忠誠地服務了我，我饒過你的性命。乖乖收下這個禮物，滾出我的視線。讓你的人民知道發生的一切吧。\n\n還有<name>，如果我們再次碰面，你就會死。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "千針石林長袍千針石林護腿千針石林外衣千針石林護胸千針石林肩鎧千針石林頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28161] = {title = "散播傳言", objective = "在千針石林的菲茲爾與普茲克的高速駁船和普茲克談話。", description = "因為你忠誠地服務了我，我饒過你的性命。乖乖收下這個禮物，滾出我的視線。讓你的人民知道發生的一切吧。\n\n還有<name>，如果我們再次碰面，你就會死。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "千針石林長袍千針石林護腿千針石林外衣千針石林護胸千針石林肩鎧千針石林頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28162] = {title = "沼澤的誘餌", objective = "你受命從托巴拉德的巴拉丁鱷魚身上收集到8張鱷魚皮。你可以在巴拉丁堡西方的沼澤找到鱷魚。", description = "在這種地方找到補給向來不是件容易的事。<class>。我們從佔領這個島嶼開始就一直搜索，但情況一直都很不妙。\n\n幸運的是，我們剛接到偵察情報指出，在我們的營地的西方有一個充滿鱷魚的沼澤。鱷魚皮會對我們的皮革製造者很有用的。能帶回多少就帶回多少吧。", progress = "你把沼澤清乾淨了嗎？", completion = "看起來你的確拿到了我們要的鱷魚皮。謝啦&lt;name&gt;，你的貢獻我們會銘記在心。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28163] = {title = "善後工作", objective = "你受命殺死在托巴拉德的12位部落步兵。你可以在托巴拉德的熔渣處理場、看守者崗哨和鐵甲要塞找到他們的藏匿處。", description = "我們經歷了一番奮鬥才拿下這個島嶼，<race>。我們清除了大部分部落的雜碎，但我還是聞得到他們在空氣中留下的一絲穢氣。\n\n我需要你調查熔渣處理場、看守者崗哨和鐵甲要塞。殺死你所找到的任何部落士兵。\n\n你知道他們常說的，唯有死去的部落才是好部落!", progress = nil, completion = "那些骯髒的部落士兵根本不是對手。幹得好，&lt;name&gt;。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28164] = {title = "前往奧格瑪", objective = "到奧格瑪的兵營與馬丁‧古柴爾德交談。", description = "有個信差請我把這個邀請函交給你。寄件人是馬丁‧古柴爾德，他是牧師訓練師，常駐在奧格瑪的兵營。\n\n他請你一有空就馬上去見他。兵營就在榮譽谷中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28165] = {title = "D區", objective = "你接到指示要到巴拉丁堡西北邊的D區去殺死任10個惡魔。", description = "<name>，你有聽過D區嗎？那是這個島上的一座古老牢房。問題在於，那裡頭有惡魔成群出沒。我們打算把在這座島上找到的部落殘黨關在那裡，但以目前的狀況來說不可能辦到。\n\n我需要你到那裡去把那些惡魔清光。完成之後來向我回報。", progress = nil, completion = "D區淨空了？幹得好，&lt;name&gt;。我們馬上派工作人員下去清理。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28166] = {title = "索格的夜光", objective = "到惡腸巨魔谷地拿靈魂之光。", description = "想要看見靈魂，我們需要一種特別的光線。一種能照亮內心的光線。靈魂之光。\n\n在海加爾事件後，暮光之錘用這來掃蕩背叛者。他們才剛給了噁腸巨魔一個當做禮物。\n\n在北邊的噁腸谷裡，你會找到殘暴又巨大的索格。他有一個靈魂之光。至少在你搶走之前都算有。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28167] = {title = "向卡沃‧爆栓報告", objective = "到諾姆瑞根找卡沃‧爆栓報告。", description = "我要準備讓我的人馬離開這裡了。我們沒辦法再抵擋下去。我要你去到中間的大房間前。\n\n你會在那裡找到卡沃‧爆栓。他會給你進一步的指示。祝你好運，<name>，我們會在地面上再次碰面的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28168] = {title = "淤泥農場的麻煩", objective = "到希爾斯布萊德丘陵的淤泥農場向管理員斯蒂沃特報到。", description = "在北方淤泥農場上的管理員斯蒂沃特，送出了求救信號。信件不很清楚，但是從我能辨認的地方看來，在淤泥農場有暴動，守衛幾乎都死了。他提醒各位想要成為英雄的人從淤泥農場西邊的後方入口進去。\n\n他也要求大家慎重其事。他不希望這件小「呃哼」的消息浮上檯面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28169] = {title = "撤退到裝載室!", objective = "跟著S.A.F.E.技工到裝載室找潔佛‧螺旋彈簧。", description = "救援其他生還者的任務作得漂亮!他們跟你是S.A.F.E團隊繼續留在此地的理由。在找到並救出每一個可能的生還者之前，納文是不會休息的。\n\n我會派人到裝載室進行放射消毒的準備。請跟著他們走，然後在到達裝載室後和潔佛‧螺旋彈簧碰頭。她會為你進行放射消毒並將你送往地面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28170] = {title = "夜之驚懼", objective = "在水道和烏徹克談話。在靈魂國度裡拜訪洞穴裡的三座神殿時，用你的靈魂之光保護自己安全。", description = "我朋友烏徹克已經在洞裡了。我們在裡面建了三座神殿。你只要負責把壞的魂能從裡面一個個趕出來就好，老兄。\n\n去裡面和烏徹克聊聊。他會讓你出竅，進入靈魂國度。謹慎行事!如果你看到幽靈般的野獸，不要驚慌。對著野獸點亮靈魂之光，一會兒之後，光芒就會讓他們永遠消失。光芒會保護你的安全。現在，去淨化那三個神殿!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "神殿清潔淨化機有害光線標誌您能選擇下列奬勵中的一個：\n\n靈機魂能\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][28171] = {title = "染紅天空", objective = "參與攻擊黑龍軍團的行動。", description = "在死亡之翼分身乏術的情況下，我們面對著一個嚴酷且讓人望而生畏的任務，根據龍后的命令。黑龍必須被徹底滅絕。\n\n如果你願意提供協助的話，我十分歡迎。只要告訴我一聲，我就會送你加入下一次的飛行參與攻擊行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28172] = {title = "什麼都沒做錯", objective = "取得一隻獲釋的紅龍寶寶、一隻獲釋的綠龍寶寶、一隻獲釋的藍龍寶寶以及一隻獲釋的青銅龍寶寶。", description = "這片平原上的黑石獸人侍奉著一位黑暗之主，他對活著的生物進行一些扭曲的實驗，以創造出屬於他的可憎生物。他的試驗對象大多變得如同他一般墮落，但還有許多生物是無辜的。\n\n他們將幼龍鎖在南方幼龍丘陵的地上，準備用來進行實驗。我不容許這種事情。去讓那些幼獸得到自由，然後把牠們安全地帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "幼龍守護者法杖幼龍保衛者燎星護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][28173] = {title = "昏厥", objective = "使用獵龍者之鉤捕獲並殺死8隻暮光炎翼飛龍。", description = "暮光飛龍獵人用惡劣的工具把我們的飛龍從天空拉下來。他們為了維護暮光的安全，用勾子刺入我們親人的鱗片，並把他們拉下地來。\n\n如今我們對和平不再抱持希望。對他們的改過自新不再抱持希望。我們唯一留給黑龍軍團的慈悲，就是他們所急切追尋的幻滅。\n\n用這些勾子殺死南方的暮光炎翼飛龍。正確使用的話，這應該可以讓你在空中更具機動性。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "獵龍者肩甲夜鱗束腰龍翼披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][28174] = {title = "燃燒的復仇", objective = "殺死5位黑石畜養者和5隻火鱗小龍。", description = "黑石獸人不停地湧入這座山，就像傷口的血流不停一般。他們群聚在東邊的戰爭平原上蓄勢待發，準備在任何時刻發動攻擊。\n\n他們已經對我的家鄉發動過攻擊了。我是來這裡阻止他們再次攻擊的。\n\n如果你對人類有一絲一毫的愛，你也會做一樣的事。證明你自己吧。前往南方的幼龍丘陵，殺死他們的幼獸和小黑龍。證明你已經準備好參與這場戰爭了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28175] = {title = "在黑暗中閃耀", objective = "在黑曜之樹下方的洞使用雅立史卓莎之淚。", description = "南方那棵矗立在我們之前的巨大石化樹木，曾是一個偉大生命的信標。我們的信標。我們的森林被黑龍軍團奪走了，而它從此遭到了腐敗和石化。幾乎無藥可救。\n\n但並不是完全沒有希望。我帶了強力的工具來進行醫療程序。透過長久的時間跟好運，可能再加上一點你的努力，這棵樹或許還能救回來。\n\n帶著這個，雅立史卓莎之淚，並把它用在那棵樹中空的核心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28176] = {title = "跟著幼雛回家", objective = "在黑曜龍蛋上使用育母之焰來放出幼龍。跟著幼龍找到他們母親的藏身處。", description = "在黑曜森林的西南區域，你會找到一窩黑色的蛋。大部分的蛋經過適當熱源刺激後都可以孵化，幼龍孵化之後，他們會哭著一起去找媽媽。\n\n別擔心，如果是要淨化這些幼龍，那我不會勉強你接受這項任務。我只是希望你讓他們走出窩裡，然後在他們去找媽媽時跟著他們回家。母龍才是我們要面對的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28177] = {title = "進貨", objective = "取得5個鋒銳蠍刺。", description = "我們必須做好計畫，才有辦法和黑石部族的傢伙開戰。我已經把計畫設計好了，現在只剩下執行的問題。\n\n我需要蠍尾針...要你所能找到最尖銳的那種。蠍子在燃燒平原上到處都是，但你在西邊的河谷裡能夠找到最多。\n\n不要去管用途。你負責儘快找到就好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "銳利蠍刺附魔蠍尾淬毒蠍尾您會收到：\n\n"}
MultiLanguageQuestData['tw'][28178] = {title = "未來的計畫", objective = "取得11張灰燼座狼皮革。", description = "我們需要座狼的毛皮，需要很多。就算破了、燒焦或沾滿血污都沒關係，我們就是要大量的毛皮。\n\n其實，也許有點破損反而更好。\n\n你可以在這裡的西邊和東邊找到座狼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "灰燼座狼之眼您會收到：\n\n"}
MultiLanguageQuestData['tw'][28179] = {title = "泥濘獵人", objective = "取得9堆黑曜石粒泥。", description = "希望你不怕把身上弄髒。從你的外觀來研判，這似乎不是什麼問題。\n\n前往北方的熔岩邊緣，你會發現一堆深色的泥濘。我需要那些東西。\n\n你最好不要多問，專心完成你收到的命令就好，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "黑曜石斑點風帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][28180] = {title = "沙子、蘋果酒和珠子", objective = "到風暴祭壇附近和戈瑟奇‧邪眼談談。", description = "卓特曼上校正在東邊等我們。不過在出發之前，我們還需要收集更多東西。這次，你要從一個名叫戈瑟奇‧邪眼的術士身上取得那些東西。\n\n你可以在西北方的風暴祭壇附近找到他。告訴他我們需要他的幫助。我們需要沙子、蘋果酒跟珠子。\n\n他明白這是什麼意思。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28181] = {title = "術士的貨物齊全", objective = "取得一把沉睡之砂、一壺魔化調味冰砂以及一顆清澈玻璃寶珠。", description = "基沙恩說他需要補給?我有很多的補給!但問題是，那些術士把我踢出了我的老巢，他們可不讓我回去。\n\n<戈瑟奇打量著你。>\n\n也許你可以進得去。前往北方，取得一些沉睡之砂、魔化調味冰砂以及清澈玻璃寶珠。我確定這些是他要的。\n\n噢對，如果你不小心在那裡殺了幾個獸人，我一點都不會覺得不高興的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28182] = {title = "毆打陰影", objective = "殺死『陰影』奈葛胥。", description = "『陰影』奈葛胥是北方那些術士的領導者，黑石獸人出現的時候，就是那個混蛋把我給趕出老巢的。\n\n嗯，他們都是混蛋，但他是最混的蛋。\n\n如果我想要有回到祭壇的一天，奈葛胥就必須離開。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28183] = {title = "回去找基沙恩", objective = "到燃燒平原的燎星崗哨將術士的補給品交給約翰‧J‧基沙恩。", description = "好吧，看來你可以幫我的都已經完成了。建立起足夠的勇氣之後，我要去把其他的術士給趕走。\n\n來，別忘了拿著這些補給品。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28184] = {title = "鑿柄，平原之心", objective = "在前往鑿柄的路上殺死15名黑石獸人。", description = "我們要前往位於平原中心點的鑿柄。我們會在那裡和瑟銀兄弟會與卓特曼碰頭。\n\n你跟瑟銀兄弟會熟嗎？那些黑鐵矮人幫助我不只一次了。我們或許會再次需要他們的幫助。\n\n我們途中會穿越黑齒小屋。你覺得在路上殺幾個獸人如何？我在這個營地裡有點悶得發慌。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "款待外衣黑齒頭盔分憂肩鎧礦指火槍您會收到：\n\n"}
MultiLanguageQuestData['tw'][28185] = {title = "斯瓦爾諾斯", objective = "你必須到D區去殺死斯瓦爾諾斯並把牠的詛咒項圈帶回來。你可以在巴拉丁堡西北邊的D區裡面找到斯瓦爾諾斯。", description = "在攻占島嶼的工作上你做得很好，<class>。取得了島嶼之後，我們必須讓牢房可以用來關囚犯。D區一直都特別難清理。不幸的是它裡面還充滿了各式各樣的惡魔。\n\n我們已經削減了惡魔的數量，但有一隻巨大的熔核犬衝出了籠子，在底下造成巨大破壞。我需要你去殺了牠並把牠的項圈帶回來。", progress = "熔核犬死了嗎？", completion = "斯瓦爾諾斯終於死了？看來我們終於可以接著整頓牢房了。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28186] = {title = "被詛咒的鐐銬", objective = "你被要求要到巴拉丁堡西北邊的D區去，找出8副被詛咒的鐐銬。", description = "<name>，你有下去D區過嗎？每次我們將這個害蟲橫行的牢房清理乾淨，惡魔似乎總是很快就回來。我們發現這些傢伙是從零星分佈在這個地區裡被詛咒的鐐銬再生出來的。這就是你的工作了，<name>。\n\n我需要你盡量把這些鐐銬找出來並帶回來給我。我們會立刻摧毀它們。", progress = "你有找到很多鐐銬嗎？根據報告，底下到處都是。", completion = "是那些鐐銬!我們會立刻進行摧毀這些鐐銬的工作，&lt;name&gt;。感謝你的幫忙。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28187] = {title = "就差這麼一點!", objective = "當你準備陪同指揮官舒諾茲離開著火的房子時，就和他說話。", description = "好吧，<race>！這可是來真的！\n\n有人以為可以那麼輕易解決掉我，嗯？\n\n我們走著瞧！沒有任何事能阻撓我們的工作！沒有！\n\n<舒諾茲看著四周火焰漸漸逼近。>\n\n我們最好先離開這裡。\n\n快點！別浪費時間！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28188] = {title = "監獄造反", objective = "你受命在巴拉丁堡西南方的大坑裡殺死任何10位囚犯。", description = "我們攻下整個島嶼了，現在只剩下開始運用這裡的資源。我們在西南方找到了一個被遺棄的監獄分區，需要你過去看一下，<name>。\n\n根據情報，那邊充滿了多年來被關在底下動彈不得的囚犯。盡一切力量把那個地方處理乾淨吧。完成後向我回報。", progress = nil, completion = "你清除那個地區了嗎？看起來你比我們想像中更有用，&lt;race&gt;。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28189] = {title = "做正確的事", objective = "解救15個人類幼苗。", description = "你見到了可怕的一幕。某人或某種東西像種植物一樣把那些人類從脖子以下埋在地裡。食屍鬼們彷彿在農場上管理人類幼苗，有時候會把最靠近的人類的頭吃掉!\n\n你有能力立刻結束這件事。帶著這個鏟子去「解救」那群人類。\n\n做正確的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "憐憫之鏟您會收到：\n\n"}
MultiLanguageQuestData['tw'][28190] = {title = "受污染的軟泥怪", objective = "殺死8隻受污染的軟泥怪。", description = "這一切都是因溫娜‧哈薩德而起。她是血毒崗哨的一名藥劑師，在這裡研究用魔化軟泥怪對付聯盟的方法。\n\n我們警告過她，她的研究偏離太遠了，但她聽不進去，而我們也太慢作出反應。現在她和整個血毒崗哨的人都變成了喪失心智的軟泥生物...\n\n她用來研究的噁心軟泥怪依然在東方和南方的水池附近徘徊。我求你，<class>，去摧毀它們，這樣就不會再有其他人身陷如此的邪惡之中了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28191] = {title = "最適合的結局", objective = "殺死10個黑曜龍人。", description = "黑曜龍人把我們南方的景色搞得一團亂。他們完全沒有立場與我們對抗，但你永遠不知道沒有徹底完結的戰爭會帶來甚麼樣的威脅。\n\n我要你去和龍人戰鬥。掃蕩他們，好讓我們可以開始清理黑龍軍團在土地上留下的污染物質。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28192] = {title = "沒人能活著出去", objective = "評估淤泥農場的情況。", description = "農場被封鎖了！進不去也出不來！我們還在評估狀況，試著瞭解發生了什麼事，但我的理論是：有些苦力吃了蘑菇，就此變成可怕的不死怪物。我是說，還能有什麼原因呢？這只是個農場！我們在這裡種蘑菇！還有淤泥！沒錯，淤泥！\n\n四處調查看看吧，<class>，因為你人在這裡，事情沒有解決之前無法離開。\n\n自己看看！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28193] = {title = "禁閉!", objective = "指揮官舒諾茲要你觀察舒諾茲營地的賓客。", description = "那棟屋子絕對不會自己爆炸!\n\n有人想幹掉我，在我沒找出真兇前，你也別想休息!\n\n先從那些賓客著手。拜訪他們，觀察他們的舉止，然後向我回報。\n\n要是他們知道半點消息，就讓他們接受審問!\n\n解散!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28194] = {title = "大逃亡", objective = "舒諾茲營地的多產作家要你從舒諾茲水手身上收集6套乾淨的制服。", description = "拜託，<class>!我們需要你的幫助!\n\n他們強行將我們關在這間屋子裡。指揮官大發雷霆，誰也不知道他會對我們做什麼!\n\n如果你弄來幾件制服，我們或許有機會溜走。\n\n我們不該到這裡來的。我現在明白了。\n\n如果你幫我們逃走，我會寫下關於這裡的「真相」。\n\n那些船上的人身上穿的正是我們所需的衣服。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "假臉面具方尖碑護手鏡面拋光長靴軍官的指揮短棒您會收到：\n\n"}
MultiLanguageQuestData['tw'][28195] = {title = "殺雞儆猴", objective = "指揮官舒諾茲要你殺死瑪根船長、考克船長和克隆克船長。", description = "這個地方到處是我的眼線，<race>。\n\n我有聽到軍隊中散佈的一些流言。我對這可悲的行徑一直很忍耐。直到現在！\n\n我要殺雞儆猴，讓部隊裡的每個人都了解到這點：我絕不容忍有人刻意挑撥離間！\n\n你得去碼頭那裡，除掉我船上那幾個船長。就是他們在帶頭作亂。\n\n完成後，我會監控通訊決定下一步該怎麼做。\n\n解散！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28196] = {title = "希爾斯布萊德之戰", objective = "將《希爾斯布萊德之戰》送去希爾斯布萊德丘陵的淤泥農場給管理員斯蒂沃特。", description = "書記員赫拉斯‧懷特斯蒂德生命最後62天的日誌文件。其中滿是對管理員斯蒂沃特和他在淤泥農場所做活動的咒罵指控。\n\n你應該把這個拿給管理員看。無疑的，他對日誌的內容應該會有所解釋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28197] = {title = "謹慎是關鍵", objective = "消滅居民維爾克斯和書記員赫拉斯‧懷特斯蒂德。", description = "我們必須摧毀所有證據，<name>!我說了證據嗎?我是指發狂的不死族!不管怎樣，謹慎是關鍵。我們不能讓橫衝直撞的不死族逃出淤泥農場，也不能讓外面的機構知道裡面發生了什麼事!\n\n你可以在正東南方的舊蘑菇農場找到一個復活的惡魔，居民維爾克斯，和他的同伴，書記員赫拉斯‧懷特斯蒂德。他們給我的守衛們惹了很大的麻煩。找出並殺了他們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "雙擊殺弩懷特斯蒂德書記員的披風居民維爾克斯的戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][28198] = {title = "最弱的一環", objective = "到奧丹姆的蘭姆卡韓軍團哨站找薩赫特說話。", description = "他們說，一條鎖鍊再堅韌也強不過它最弱的一環。\n\n我對這個理論深信不疑。\n\n與其移除最弱的一環，還不如...強化它。\n\n就拿我的部隊來說，我們最弱的一環有個名字。薩赫特。\n\n你可以在階梯下方發現他正在受訓。\n\n你可以先叫他做點簡單的事。例如，西邊山上的那些土狼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28199] = {title = "為了科學!", objective = "找到6個肉塊樣本。", description = "樣本...沒錯...一定要有樣本!這些，呃，實驗...我是指，一定要研究這些不幸的勞工。\n\n到東南方的第一個農場殺了復活的食屍鬼。你一定要從殘破的屍體上找到新鮮樣本。把它們帶來給我!\n\n<阿爾諾德把雙手擰在一起，沒來由的狂笑起來。>\n\n一定要化驗!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28200] = {title = "補給的元素", objective = "收集12份硬化鱷魚皮。", description = "你會發現他們還沒完全準備好上戰場。\n\n幾千年來，托維爾部族沒見過什麼大的戰爭場面。\n\n但是泰坦為我們祖先制定的戰鬥協定還沒有消失。有些出自我們的本能，有些是藉著傳統傳承下來。\n\n不過這些都不能彌補物資的匱乏。我們需要武器。我們需要盔甲。\n\n附近河床的鱷魚皮，可以縫製出最好的盔甲。去幫我們收集一些來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "赫利奧波利斯腿鎧渦卷銘刻肩甲石棺護腕毒蛇小刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][28201] = {title = "犁頭對刀劍", objective = "募集8名蘭姆卡韓苦力。", description = "我們兵力還算充足，但我害怕日後與奈斐賽特部族的決戰，會需要徵召蘭姆卡韓和奧爾希斯裡面所有體格健全的族人。\n\n我希望你到前線去，加入我們募兵的行列。\n\n越過這條河，到雅奇涅特原野，募集在那裡工作的苦力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28202] = {title = "完美的裝束", objective = "從賽拉隆‧恐針的裁縫桌上取得適當數量的補給品。", description = "根據你的體重、身形和大小，我們會把你裝扮成一個獸人。他們的軍隊大多由獸人組成，所以你可以輕易地混進去。\n\n你懂得裁縫嗎?不懂的話，把這當做你的第一堂課吧。我的工作檯就在那裡，上面有所有必要的工具。\n\n把你認為必要的東西全拿到這裡。賽拉隆會馬上幫你搞定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28203] = {title = "完美的裝束", objective = "從賽拉隆‧恐針的裁縫桌上取得適當數量的補給品。", description = "根據你的體重、身形和大小，我們會把你裝扮成一個巨魔。火腹巨魔總是為黑石的傢伙工作，所以你可以輕易地混進去。\n\n你懂得裁縫嗎？不懂的話，把這當做你的第一堂課吧。我的工作檯就在那裡，上面有所有必要的工具。\n\n把你認為必要的東西全拿到這裡。賽拉隆會馬上幫你搞定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28204] = {title = "完美的裝束", objective = "從賽拉隆‧恐針的裁縫桌上取得適當數量的補給品。", description = "根據你的體重、身形和大小，我們會把你裝扮成一個哥布林。大家都知道黑石的傢伙經常雇用哥布林傭兵加入他們的隊伍中，所以你可以輕易地混進去。\n\n你懂得裁縫嗎?不懂的話，把這當做你的第一堂課吧。我的工作檯就在那裡，上面有所有必要的工具。\n\n把你認為必要的東西全拿到這裡。賽拉隆會馬上幫你搞定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28205] = {title = "完美的裝束", objective = "從賽拉隆‧恐針的裁縫桌上取得適當數量的補給品。", description = "根據你的體重、身形和大小，我們會把你裝扮成一個獸人。燃棘食人妖經常和黑石獸人合作，所以你可以輕易地混進去。\n\n你懂得裁縫嗎?不懂的話，把這當做你的第一堂課吧。我的工作檯就在那裡，上面有所有必要的工具。\n\n把你認為必要的東西全拿到這裡。賽拉隆會馬上幫你搞定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28206] = {title = "小男孩不見了", objective = "到希爾斯布萊德丘陵的淤泥農場找『棒透了』強尼。", description = "昨天我才派他去勘查東邊的農場，但是感覺像過了一輩子！\n\n他的金色髮絲圍繞在他完美的血精靈臉蛋旁的模樣…如此堅定的意志，簡直完美無瑕。我並不想派他去，但他非常堅持！我怎麼能拒絕他呢？\n\n唉，可憐的『棒透了』強尼沒有回來！我擔心會有最壞的結果，<name>。去找他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28207] = {title = "黏糊的處境", objective = "收集7個翡翠幻光菇。", description = "這個可憐的人差一點就無法活著逃出血毒崗哨!如果想要確保他不會像其他人一樣變成黏糊的生物，我們必須治療他身上的感染。\n\n蘑菇喜歡生長在這附近明亮的綠色水域周遭，像是東邊瀑布底下的池塘。它們大部分都沒有用...我需要你幫我收集一些發出綠色光芒的蘑菇!\n\n如果你拿到了，我就能立刻做出有助於這可憐牛頭人的解藥。別花太多時間!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28208] = {title = "溫娜的貓", objective = "從溫娜的貓身上取得小貓的耳牌。", description = "牛頭人先生告訴我很多關於血毒崗哨的事情。他說溫娜‧哈薩德依然在那裡!\n\n她已經沒救很久了，但是她殘餘的部份還在製造更多的軟泥生物。我們要阻止這一切!\n\n很幸運的，我有一個計畫。牛頭人先生說溫娜養過一隻貓。她餵牠喝了腐敗的軟泥水，然後牠往森林裡跑了。我在東南方看過某種東西在血毒塔過去一點的暗處活動，不過它顯然比小貓還要大隻!去看看那貓是不是有名牌...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28209] = {title = "讓林度恩自由", objective = "找到林度恩的籠子鑰匙。", description = "這裡不是農場！斯蒂沃特一直在拿希爾斯布萊德的人類做實驗。這裡的怪物都是他製造出來的。\n\n這還不是最糟糕的，<class>。持有我籠子鑰匙的畸形曾經是被遺忘者。斯蒂沃特的實驗對被遺忘者有副作用，會把他們變成無腦的殭屍。你覺得他幹嘛這麼害怕走漏風聲？他知道這種罪行只有死路一條。\n\n把我弄出去！外面那些被感染的淤泥守衛有鑰匙！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "異常的外衣巨盾淤泥守衛鎖甲外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][28210] = {title = "鍛鍊體魄", objective = "幫助薩赫特殺死8隻血咆土狼。", description = "卡姆塞斯將軍有個特別任務要交給我？\n\n等等…別告訴我。又是土狼，對吧？\n\n非常好，我會盡全力去做。\n\n到日衛者山脊去跟我碰頭。\n\n我不會讓你失望的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28211] = {title = "元素之焰的淬鍊", objective = "收集8支淬鍛長矛。", description = "該處理的要先處理:我們需要彈藥。威力足以射穿黑龍盔甲般外皮的彈藥。\n\n在桑德瑪西邊有個蠻錘城鎮，到處漫遊著不受拘束的火元素。任何在那片大火中存留下來的武器都經受了元素之焰的淬鍊。比我用這個熔爐所能打造出的任何東西都還要堅強!\n\n到杭伯特焚焰地裡面幫我找一些矛來，<name>。越尖銳的越好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28212] = {title = "火熱玩意", objective = "收集5顆熔火之怒。", description = "我有個計畫，能四倍擴大這種體型的矛槍的力矩，但根據我的計算，那樣在射擊時它的框架會整個碎裂。而且可能會把整個星球劈成兩半。\n\n如果能擁有純粹的元素火焰作為熔煉之用，我可以造出一個堅韌一百倍的底座。\n\n在西邊有些無縛的灰燼魔火在杭伯特焚焰地裡遊盪。殺死它們應該能讓它們化為一顆顆的熔火之怒。給我帶一些來!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28213] = {title = "哈薩德的處境", objective = "使用小貓的耳牌吸引溫娜‧哈薩德的注意，然後把她給殺死。", description = "溫娜現在與這些軟泥怪的根源緊緊聯繫在一起，就在西邊那座血毒崗哨的後面。是她讓這些軟泥怪源源不絕的出現，並且讓她獲得安全!不過，要是你能吸引她的注意...\n\n將這個耳牌帶去給溫娜看。那怕只是一小部分的她還存在，這東西或許可以吸引她的注意。也許她對她可憐小貓的哀悼將讓她再次想起遺憾的感覺，然後離開那些軟泥怪!\n\n那樣一來，你或許就能殺死她以停止這些軟泥怪的滋生。就是這樣!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "花飾披肩葉歌外衣牛頭人先生的長靴懊悔腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][28214] = {title = "清理血毒崗哨", objective = "殺死6名血毒軟泥僕從。", description = "嗝...\n\n你能不能...呃...能不能請你...嘔!\n\n原諒我，我還是有一點...呃，胃不太舒服。如果你打算前往西邊的血毒崗哨，能不能請你...哇啦...\n\n幫我結束我朋友的痛苦。馬上出發吧。為了你自己好。哇啦啦...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28215] = {title = "潛在的能量", objective = "收集10個扭曲的源質線圈。", description = "你應該知道，儲藏在尋常彈簧裡的能量有該發條所能製造的一半之多。除非你用的是源質彈簧。那數據就很瘋狂了!簡直是數學上的變異!\n\n我的秘密武器需要一些源質迴路，剛好暮光之錘教徒就使用那樣的線圈來束縛土元素。\n\n在東邊的黑曜石奴身上可以找到它們。就是那個被叫做黑色裂層的可怕區域。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28216] = {title = "熔岩領主法薩札爾", objective = "取得熔岩領主法薩札爾的腦袋。", description = "我聽說在西邊發生了很糟糕的事件。我們失去了杭伯特農場。那裡在一道火牆中從地表上徹底消失了!\n\n暮光之錘該為這件事負責，而生還者說那是熔岩領主法薩札爾的傑作。他是個卓越者，亦即化身為元素的最高階暮光之錘教徒。他是個純粹由火焰構成的生物。\n\n他很快就要變成純粹由死亡構成的生物了!到杭伯特焚焰地殺了法薩札爾，把他的腦袋帶來給我!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "冷卻熔岩腿鎧防火足靴抗腐化手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][28217] = {title = "懸賞：惡魔獵人", objective = "殺死費洛納斯‧辛德爾勒。", description = "從薩特手中奪回了碧火小徑後，翡翠議會派出了許多德魯伊著手淨化廢墟的漫長工作。昨天夜裡，他們之中的許多人都被謀殺了...被一個夜精靈。\n\n根據目擊者的描述，那是一個惡魔獵人，伊利丹瘋狂的追隨者。這個情況很少見。毫無疑問，他和他的主人一樣被對力量的渴望給搞瘋了。\n\n我將提供最高的賞金，只要你擁有這個兇手死亡的證據。根據目擊，他最近出現在北邊道路的前方，碧火小徑底下的一處山谷附近。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28218] = {title = "燃燒與悲傷的命運", objective = "再次經歷伊利丹與阿薩斯的戰鬥。", description = "我們這種人總是為了我們所做的事情而被仇視...被唾棄和鄙視，被指摘為墮落而無藥可救。\n\n然而要不是因為一位惡魔獵人，這座森林早就成了燃燒軍團在艾澤拉斯最強大的堡壘。我說的正是我的主人...伊利丹‧怒風，我的主人，被稱為「叛徒」的那個人。\n\n你自己看看吧。看看伊利丹最初被釋放時，在這裡發生了什麼事，以及驚懼領主提克迪奧斯的惡魔軍隊是如何在這座森林裡橫行無阻...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28219] = {title = "餵食幼苗", objective = "殺死10隻鐵木蜂鳴者來餵食幼苗保衛者。", description = "<這株幼苗將它的葉片寬闊的展了開來，像是隻等待著被餵食的幼鳥。它用一種非常微弱的聲音說起話來:>\n\n好餓...想要...蟲...<你可以聽到南方傳來黃蜂振翅的嗡嗡聲。那有可能是這個小東西想被餵食的東西嗎?>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28220] = {title = "尋找土壤", objective = "帶領幼苗保衛者找到7塊肥沃土壤。", description = "<這株小芽苗四處移動著，示意你向南方前進。你可以聽到一陣微弱的聲音。>\n\n土...\n\n<看來它似乎想要新鮮的土壤。也許你應該試著導引它前往看起來更肥沃的土地去。>您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n古老的種子盒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][28221] = {title = "這些根是用來踏的", objective = "消滅10個鐵木踐踏者。", description = "有這麼多的靈魂還困在腐爛的屍體裡...\n\n你看到沒?北方的鐵木踐踏者。它們因為惡魔的玩意兒和黴菌而生病痛苦。在它們體裡的悲慘靈魂沒辦法出來。\n\n你能夠幫助它們!把它們砍倒，靈魂便能得到釋放。我會把靈魂存放在我體內，我們可以在我成長時和諧地共生。你會幫忙嗎?拜託?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28222] = {title = "在陽光下歌唱", objective = "引導樹苗保衛者到鐵木森林的5道陽光去。", description = "我們成長了很多...該是吸收光線的時候!把我們的葉片伸展在陽光下的時間到了!\n\n帶我們去曬太陽!太陽很遙遠，但它的光芒照耀著我們。它的光芒使我們再度變得高大茁壯。光芒一視同仁地照耀著強壯樹枝還有我們這樣的小樹枝。\n\n到那裡去!到從北方照著我們的太陽那去!帶我們跟你走，帶著我們跳躍!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28223] = {title = "典獄長", objective = "你必須到大坑殺死典獄長希爾瓦並帶著他的鑰匙回來。大坑就在巴拉丁堡的西南方。", description = "我們就快將大坑裡那些反叛的囚犯處理完畢了，但最後還有一個麻煩:典獄長。\n\n典獄長希爾瓦是囚犯的頭目，囚犯為了他什麼都敢做。若我們擊敗他，就等於我們擊敗所有囚犯了。將希爾瓦殺死並帶回他身上的鑰匙。我們可以用那些鑰匙更深入監獄地區，而且也許可以找到這個島嶼的水源補給。", progress = "典獄長死了嗎？", completion = "啊，典獄長的鑰匙。又成功完成一件任務了，&lt;name&gt;。這些對我們將會非常有用。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28224] = {title = "最後的守護者", objective = "打倒枯萎的保衛者。", description = "啊...謝謝你，小<race>。我和其它人好幾次試著在這森林裡成長，但都失敗了。\n\n在森林崩壞之後，潛伏在北方的枯萎的保衛者是唯一完全長成的古木，但它的軀體有病，也失去了理智。就像我們收集樹人的靈魂一樣，我要救出它體內的靈魂，而非拋棄它們。\n\n打倒它，在我扎根前讓它的靈魂與我融為一體。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28225] = {title = "證明你的忠誠", objective = "在索瑞森廢墟殺死10名黑鐵矮人。", description = "我們歡迎你停留在鑿柄，但我必須確認你是我們的朋友。所以我有一件工作要給你。\n\n我們瑟銀兄弟會並非是平原上唯一的黑鐵部族。完全不是。黑石山的黑鐵矮人數量遠遠壓倒我們。我們在鑿柄找到了一個安穩的落腳處，但即便如此，近如北邊那座索瑞森廢墟的地方還是受到了他們的侵擾。\n\n證明你自己，<race>。為我殺了他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28226] = {title = "廢料魔像", objective = "在索瑞森廢墟殺死戰爭劫奪者，然後從掉落的戰爭劫奪者零件中收集3個黑曜石活塞、3個熔焊排氣過濾器、3個瑟銀齒輪軸以及1個石製能量核心。", description = "我們在這裡用魔像當守衛。北方的矮人也有魔像，不過我不確定他們用來幹麼。\n\n主要是用在戰鬥吧，我想。\n\n我們需要一些多餘的零件給魔像用，所以你要做的就是:殺死他們的魔像，然後收集任何掉到地上的零件。盡你所能地回收零件。你恐怕沒辦法回收每一件東西，所以仔細挑選吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28227] = {title = "訓練魔像", objective = "幫助4座鑿刻魔像完成戰鬥訓練。", description = "你證明了自己是個有用的人，<race>。我想你還可以再幫我們一個忙。\n\n我們的守衛很強壯，不過它們不像你一樣的強悍。我在想，如果不介意的話，你可以幫我們訓練一下它們嗎？只要和其中幾個談談，與它們戰鬥個幾次就好。希望它們可以從你的動作中學到改進的技巧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "導師斗篷善意寵愛護腕戰鬥訓練外衣鑿柄盾牌您會收到：\n\n"}
MultiLanguageQuestData['tw'][28228] = {title = "重回森林", objective = "把繁茂保衛者帶回鐵木森林中心的山丘上。", description = "該是告別的時候了。你將我從幼苗養育長大，雖然很短暫，但我現在該重返森林。\n\n帶我回到你發現我的山丘。我會在那裡扎根，在先人的庇蔭下成長。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "天賦樹枝活木護符樹圈指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28229] = {title = "天生自然", objective = "在語風林地的月井將瓶子裝滿，然後將它灑在鐵木森林裡死去的古樹保衛者之間的地面。", description = "這裡北邊的鐵木森林裡的古樹保衛者們已經死去多年了，他們的遺骸是這些土地所受傷害的無情證據。\n\n每一個季節，我們都會從這座月井裡取水，然後灑在他們面前的土地，希望能藉此滋長新生的生命。願意的話，你可以親自帶些水過去。\n\n這是個讓人反省的好機會。帶著這個瓶子並且在月井裡將它裝滿，然後將它灑在小山丘頂端的三個古樹保衛者中間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28230] = {title = "緊急協定", objective = "消滅雷恩-蓋茲-卡拉巴巨怪。", description = "在管理員得到報應之前，我們必須先處理暴動。我們不能冒險讓傳染源進入這個世界。\n\n在北邊的苦力區裡，有一個斯蒂沃特用三名農夫拼出來的怪物。我們必須殺了這頭野獸才能拯救淤泥農場!這是緊急協定的需求!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28231] = {title = "為了閃閃", objective = "消滅鐵匠維林坦。", description = "管理員斯蒂沃特派我到農場上調查暴動。我一到那裡，就和閃閃遇上了名叫維林坦的笨巨怪。我從閃閃身上被擊落下來，只好馬上逃命。但是閃閃留在後面抵抗那隻野獸。唉，她被打敗了，而且立刻就像某種燦爛的小幼苗一樣被種植在土裡。\n\n她付出了生命來保護我。我一定要報仇!要是想不出理由，那就為了閃閃!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "繁星小馬護腿驚人長靴『潔妮』的手套絕妙鎖甲長靴"}
MultiLanguageQuestData['tw'][28232] = {title = "下方來的補給", objective = "你受命從大坑取回12份監獄口糧，就在巴拉丁堡的西南方。", description = "營地的補給品已經快沒有了，<name>。我們最近得知西南方的監獄地區有足供我們用好幾年的口糧存貨。我們需要你去收集口糧，盡你所能搬越多回來營地越好。\n\n還有一件事，整個監獄地區充斥著囚犯，所以請小心。", progress = "你取回口糧了嗎？情報指出，你在那下面到處都能找到口糧。", completion = "這些口糧對整個軍隊真會很有幫助，&lt;name&gt;。謝謝你的協助。", rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28233] = {title = "失蹤的兄弟", objective = "找到巴盧姆‧爐錘。", description = "我的兄弟巴盧姆失蹤了！\n\n他本來是這區域裡最初的斥候之一。其他人全都平安回來了，只有他至今仍沒有蹤影。他們說他只是在什麼地方打混罷了，但他是我唯一的兄弟，我曾答應老媽會好好保護他的。拜託你，去找他好嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28234] = {title = "他們幹走了我的褲子!", objective = "找到巴盧姆的腿甲。", description = "我為什麼站在榖物箱裡面？長話短說吧，就是有大黃蜂和一些龍喉的傢伙在很糟糕的時機跑了出來。我平安逃走了，但那些混帳幹走了我的腿甲！那是我的姊妹幫我拼湊出來的，甚至在上面刻了我的名字…如果被她發現我弄丟了，我肯定會羞愧而死。請幫我找到它們。我看見那個偷褲賊跑進那邊的堡壘中。我會留在這裡保持…咳…掩護。不准問一個蠻錘在褲子下穿的是什麼！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋穀物"}
MultiLanguageQuestData['tw'][28235] = {title = "伯恩賽德必須死", objective = "消滅伯恩塞德鎮長。", description = "伯恩塞德曾經是這區的鎮長。活著的時候，他在希爾斯布萊德的戰役中是一個強大的對手。成為亡靈後他絕對會是我們的重大考驗。\n\n伯恩塞德在淤泥農場西北區域導引著強大的秘法。帶領我們到那裡去，協力結束他的支配，一絕後患。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28237] = {title = "大地上的荒疫", objective = "拿下管理員斯蒂沃特的頭顱。", description = "阻止了亡靈的暴動，是時候要斯蒂沃特和他的跟隨者為罪行付出代價了。雖然我們終結了一場自從天譴入侵後就無可比擬的慘劇，我們還是得進一步確保這種事永遠不再發生。他們必須受死!\n\n來吧，<name>!我要斯蒂沃特的人頭!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "斯蒂沃特的匕首斯蒂沃特的披風斯蒂沃特的徽記您會收到：\n\n"}
MultiLanguageQuestData['tw'][28238] = {title = "暮光海岸", objective = "到暴風港和法戈‧燧鎖談話。", description = "時候到了，<class>。暴風城安全後，我們就會向敵人宣戰。為了高地!\n\n我們已經派出了大批海軍，感謝你先前做的努力。不過法戈‧燧鎖打算從海路加緊腳步出發。\n\n在港口和燧鎖談談，告訴他你會陪同他前往暮光高地。你可以在水邊找到他。祝你旅途平安，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28239] = {title = "進入黑齒小屋", objective = "到燃燒平原的黑齒小屋和軍需官卡歐辛談談。\n\n已提供物品：\n", description = "這不是我所看過最...有說服力的偽裝，不過會有用的。反正臥底工作本來就要裝腔作勢。你就裝一副本來就是那裡人的樣子，一切都會順利的。\n\n你在黑齒小屋的接應人是個叫做軍需官卡歐辛的獸人。他並不知道你是個臥底，所以保持冷靜。\n\n不管卡歐辛要你做什麼，聽他吩咐。卓特曼上校會透過地精自動紀錄器和你保持聯絡，他會給你特殊指示。\n\n祝你好運，士兵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28241] = {title = "暮光的幻象", objective = "在黑色裂層內找到一個暮光之眼。", description = "丘加利一直用一個有趣的魔法球「暮光之眼」來追蹤他的手下。\n\n如果我拿到這種魔法球，我敢說我們能用它來觀看丘加利與其手下嘍囉在做什麼。\n\n在這裡的東邊、河流的北方找到黑色裂層，給我找出暮光之眼。用上任何手段將它帶回來這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28242] = {title = "我們都要獻祭", objective = "殺死10名黑色薩滿。", description = "<眼球對著你說話，他的「話語」的回響就好像同時聲音來自四面八方。>\n\n你尋求我的視界嗎，<race>？想要我的力量是需要代價的。這些暮光的追隨者用附近遺跡裡的蠻錘矮人鮮血來榮耀我，但我仍然感到飢渴。也許你可以做得更好。\n\n殺死我的舊主，我的視界就會歸屬於你。屠殺黑色薩滿來榮耀我。說到底，鮮血就是鮮血，都是一樣的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28243] = {title = "眼睛", objective = "到暮光高地的桑德瑪將暮光之眼交給低階薩滿布朗第。", description = "非常好，<race>。你用鮮血換取了我的能力。帶我回去找那個桑德瑪的「低階薩滿」吧。\n\n噢，是的，我已經知道你要帶我到何處去了。布朗第非常貧弱，他被麥酒浸蝕的能力不值一提。但是你－你讓我感到驚奇，<race>。藉由我的視界和你的能力，想像一下我們能聯手為這可悲的世界帶來多大的災難...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28244] = {title = "眼之間諜", objective = "為低階薩滿布朗第仔細看著暮光之眼。", description = "我老實說吧，<name>。那個東西讓我渾身發毛。但看見你花了費了那麼大的力氣把它帶到這裡，我想我們還是得好好利用它。\n\n你先。\n\n窺視那顆眼睛，要它將丘加利的暮光堡壘內的模樣展示給你。我們會弄清楚那個雙頭肥蟲打算做什麼，並藉此反制他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "暗眼戒指絕望之眼您會收到：\n\n"}
MultiLanguageQuestData['tw'][28245] = {title = "大兵的任務", objective = "用力地擦亮10雙黑石長靴。", description = "呸!你很走運，我現在正缺人手。否則你一整個禮拜都會嚐到我的鞭子，<小子/小女孩>。\n\n有人得去把軍官和高階士兵的鞋子擦亮。他們都把鞋子放在帳篷外面。\n\n我要在那些鞋子上看到我的倒影，大兵!快去工作!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28246] = {title = "戰術削減", objective = "在灰燼之柱的頂端找到巫毒師提曼，在座狼棚找到座狼女仕歐桑娜，在熔岩池附近找到戈洛普，對他們使用鋒銳蠍刺。", description = "<雜訊聲><name>…<name>，聽得見我嗎？我是卓特曼。\n\n聽著，我們剛收到了關於你下一個任務的最後一份情報。現在有三個目標需要你去拿下。第一個是巫毒師提曼，你可以在灰燼之柱的頂端找到他。座狼女仕歐桑娜則在座狼棚裡面。最後，你可以在南方的熔岩池附近找到戈洛普。\n\n你可以在你的隨身行囊中找到鋒銳蠍刺。在正確的時機對這些目標使用蠍刺。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28247] = {title = "碩果僅存", objective = "殺死奧希蒂亞", description = "奧希蒂亞是最後幾頭有能力延續黑龍血脈的成熟巨龍之一。必須將她殺死。\n\n如果你成功殺掉她，你應該立刻將勝利的消息告知麗菈史卓莎。她為了完成這件事奮戰了很長的時間。\n\n謝謝你在這場戰役中為了我們作戰。你證明了自己是個很強大的盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "暮光終局護腰失落孤寂兜帽最後回憶護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][28248] = {title = "致勝點", objective = "到勝利者崗哨和庫德蘭‧蠻錘談話。", description = "你的意圖和能力都已無庸置疑。除去格瑞姆巴托並擊退黑龍之後，暮光之錘就只能坐困於他們的城塞。\n\n去找你的領導者。你應該能在西北邊的勝利者崗哨找到他們。讓他們知道當進攻暮光城塞的行動開始時，紅龍群將遮蔽該處之上的天空。你或許無法彌補你盟友所犯下的罪行，但在這場戰役中，我們當與你們並肩作戰。\n\n暮光之錘將會敗亡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28249] = {title = "碎擊之地", objective = "到碎擊之地和札伊拉酋長談話。", description = "你的意圖和能力都已無庸置疑。格瑞姆巴托被除，黑龍也遭到擊退之後，暮光之錘就只能坐困於他們的城塞。\n\n去找你的領導者。你應該能在西邊的碎擊之地找到他們。讓他們知道當進攻暮光城塞的行動開始時，紅龍群將遮蔽該處頂上的天空。你或許無法彌補你盟友所犯下的罪行，但在這場戰役中，我們當與你等並肩作戰。\n\n暮光之錘將會敗落。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28250] = {title = "拔棗子的小竊賊", objective = "使用特雷特王朝大錘打爛30個沙漠俾格米侏儒。", description = "我沒有世界上最迷人的工作。\n\n戰爭的事情或是奧丹姆大廳最深處的秘密或是你，都跟我沒有關係。\n\n我負責這片土地...而這些土地會長出棗子來。\n\n現在，這些拔棗子的小雜種居然有膽站在彼此的肩膀上，試著偷走我珍貴的果子。\n\n我不會容忍這種事情。\n\n帶著這個由泰坦巨人製作並受到太陽之王和天知道還有誰祝福的木槌，打扁那些矮冬瓜!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28251] = {title = "南海鎮的麻煩", objective = "在希爾斯布萊德丘陵的南海鎮廢墟與瑟爾格‧希諾特交談。", description = "在我被抓住並且遭到囚禁前，我人在南海鎮。我在那個廢墟的主要工作是收集軟泥怪的樣本並確認我們所釋放的荒疫已經安全的消散了。一件簡單容易的工作，如果沒有那些狼人持續不斷的騷擾我們的話。\n\n我需要你前往南海鎮去找我的學徒，瑟爾格‧希諾特。確認他狀況還好，然後告訴他，等我在這裡的工作告一段落以後就會回去。\n\n你可以在東南方靠近海岸的地方找到南海鎮廢墟。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28252] = {title = "科多獸呼喚者的號角", objective = "使用呼喚者號角召喚7隻黑石作戰科多獸回到營地。如果有科多獸不願聽命，攻擊牠直到牠屈服。", description = "好吧，我有一些確切、合理且重要的工作要交給你。我們要從放牧地將科多獸召來南方。索伊佐格將軍說我們很快就要遷徙至赤脊山，我可不會留下我的科多獸不管。\n\n在科多獸旁使用這個號角。聽到這聲音，牠就會回到營地。\n\n你要小心。有時候科多獸會有點執拗，所以你可能需要粗暴一點，牠們才會聽你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28253] = {title = "將號角佔為己有", objective = "將呼喚者的號角帶到燃燒平原的鑿柄交給卓特曼上校。", description = "<name>，我是卓特曼。我要你留著那個號角。我確信我們可以即時想出在這項計畫中運用號角的方式。\n\n我很想知道關於卡歐辛所說攻擊赤脊山的事。我們知道另一波攻擊行動正迫在眉睫，但我們的時程表已經落後好幾天了。\n\n帶著號角回來找我。我們會在鑿柄這裡討論。不要毀掉你的偽裝。你還沒完成臥底的工作。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "大草原護腿臨時胸甲機緣頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28254] = {title = "地獄裡的針", objective = "到燃燒平原的鑿柄和賽拉隆‧恐針談談。", description = "你和我沒辦法應付一批軍隊，<name>。他們光憑數量就能淹沒我們了。所以我們才必須堅持卓特曼的計畫。\n\n這個計畫的下一步需要一點機巧...這是我最不拿手的。這就是你派上用場的地方。\n\n和賽拉隆‧恐針談談，他是此地的裁縫師。我已經把我們收集到的皮毛和泥濘交給他了。他要丈量你的身體尺寸。\n\n沒錯，我們要把你裝扮成敵人的模樣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28256] = {title = "古爾丹之顱", objective = "再次經歷伊利丹尋找古爾丹之顱的戰鬥。", description = "伊利丹動身去尋找古爾丹之顱。他一路與惡魔的軍隊戰鬥，憑藉著的是讓他受到憎恨與放逐的那份力量。\n\n看看他在戰鬥中的樣子，<class>。看看兇猛對抗著費伍德森林的腐化者的那個人，看著他直擊腐化者的根源。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28257] = {title = "提克迪奧斯的滅亡", objective = "再次經歷伊利丹與提克迪奧斯的戰鬥。", description = "是的，伊利丹取走了古爾丹之顱的力量為自己所用。\n\n但是他有帶著它逃進黑夜之中嗎？他有使用它為自己追求榮耀嗎？沒有…他所做的第一件事，就是用他的新力量對驚懼領主提克迪奧斯發動攻擊！\n\n看看他的勝利，<class>。看看伊利丹是如何從惡魔的手中奪回了費伍德森林…以及他得到的是什麼樣的感謝。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "假冒者面具辛德爾勒臂甲忘恩負義肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][28258] = {title = "與賽妮達‧堅鑄會面", objective = "到暴風城的訓練大廳與賽妮達‧堅鑄交談。", description = "賽妮達‧堅鑄捎來訊息給你。她希望你能盡快到暴風城舊城區的訓練大廳跟她見面。聽起來很要緊，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28259] = {title = "與伊芙琳‧棘刺會面", objective = "到暴風城的訓練大廳與伊芙琳‧棘刺交談。", description = "我剛剛收到暴風城的伊芙琳‧棘刺寄來的卷軸。她要你到暴風城的訓練大廳一趟。她沒有提及詳情，但我感覺這是為了極重要的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28260] = {title = "與戴葛恩‧鋼松會面", objective = "到暴風城的訓練大廳與戴葛恩‧鋼松交談。", description = "伍爾夫‧韓斯里姆從暴風城捎來訊息 - 他想馬上與你見面。他會在暴風城舊城區的訓練大廳等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28261] = {title = "我們之中的騙徒", objective = "在碧火小徑殺死12名碧火變形者。", description = "現在你學會了敞開你的心胸，也許你可以理解「為什麼」我要殺死那些德魯伊。\n\n答案很簡單:他們根本就不是什麼德魯伊。\n\n惡魔仍然漫步在這座廢墟裡，偽裝成保護者的模樣。你自己看看吧...這個眼罩浸滿了惡魔的血液。帶著它到碧火小徑北邊的山丘去，將它放在你的眼睛上。即使是最健忘的笨蛋也能看出那些惡魔的原形。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28262] = {title = "與維魯卡‧暗流會面", objective = "到暴風城的訓練大廳與維魯卡‧暗流交談", description = "維魯卡‧暗流是暴風城軍情七處的資深盜賊訓練師，她捎來訊息，表示想跟你談話。以最快速度前往暴風城，到舊城區南邊的訓練大廳找她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28263] = {title = "與法拉索‧霜指會面", objective = "到暴風城的訓練大廳與法拉索‧霜指交談。", description = "我剛接到法拉索‧霜指，暴風城的高級魔法師訓練師，捎來的信息。他請你在最快時間內動身到暴風城的訓練大廳與他見面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28264] = {title = "納瓦拉克斯的行動", objective = "殺死惡魔偽裝的大德魯伊納瓦拉克斯。", description = "我已經獵殺這些惡魔冒充者好一陣子了，終於找到了他們的領導者的所在。那正是翡翠議會的領導者，大德魯伊納瓦拉克斯本人。\n\n這個惡魔用無辜的外表保護著他自己。如果我想進入語風林地去獵殺他，我將會先被那些無知的保護者給攔下…但是你！你可以毫無預警的逮住他。\n\n回到語風林地去。爬到德魯伊塔上，你將會看到納瓦拉克斯待在最上面，就在他樹枝之間的房間裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "瑟魯娜的披風惡魔之心墜飾納瓦拉克斯的徽記您會收到：\n\n"}
MultiLanguageQuestData['tw'][28265] = {title = "索伊佐格將軍", objective = "和索伊佐格將軍談談。", description = "看來卡歐辛比我預期的還要更能幹，不過我們已經用不著他了。是讓你去和將軍談談的時候了。我想你準備好了。\n\n索伊佐格將軍是運籌燃燒平原地面軍隊的「三巨頭」之一。他就在西北邊的黑石要塞中執行這項工作。穿上你的偽裝，去和他談談。看看你能否贏得他的信任。卓特曼會和你保持聯繫，以確保我們需要任何協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28266] = {title = "岩漿試煉", objective = "和沃泰‧史皮宋克談談，並要他釋放熔岩領主寇羅布。並在戰鬥中擊敗熔岩領主寇羅布。", description = "我想我會善加利用目前的情勢。這些哥布林傭兵帶了這個巨大的火元素到我的要塞作為雇用他們的「謝禮」。我在燃燒平原要這些火元素幹嘛？這就像是把沙子拿到海灘上一樣。\n\n如果你想找工作，就證明你的實力。去和哥布林談談，然後挑戰他的火元素。勝利者才能贏得我的敬重，以及我的時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "熔岩領主披風可悲手套角鬥護腕索伊佐格的指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28267] = {title = "行刑隊", objective = "和指揮官舒諾茲說話。", description = "跟我一起回到外頭去，<race>。\n\n我想讓你看樣東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "哈里遜的神器徽記邪惡命令咒符舒諾茲的統率勳章您會收到：\n\n"}
MultiLanguageQuestData['tw'][28268] = {title = "與艾祖蘭會面", objective = "到暴風城的訓練大廳與艾祖蘭交談。", description = "艾祖蘭從暴風城的訓練大廳捎來訊息給你。在你下一次到暴風城時，他希望跟你談話。訓練大廳位在暴風城的舊城區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28269] = {title = "到韋爾薩爾綠洲見我", objective = "到韋爾薩爾綠洲和哈里遜‧瓊斯談話。", description = "來，聽好，<name>。\n\n我知道這些尖塔與應許法櫃有關聯，不過事實不只如此。\n\n這個應許法櫃似乎極為重要，它與一個被造物主稱為起源大廳的地方密切相關。\n\n既然舒諾茲這傢伙和死亡之翼是一伙的，我們勢必得先他們一步到那個地方去。\n\n我會在北邊的韋爾薩爾綠洲等你，快點!他們已經領先了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28271] = {title = "生產力降低", objective = "殺死15個舒諾茲挖掘者或舒諾茲監督者。", description = "好的，<name>，我解讀到的是這樣。\n\n有一種泰坦裝置藏在一個叫起源大廳的地方深處。那是艾澤拉斯一切生命的緊急重置開關。要是啟動了，它就會摧毀世界上所有的生物!\n\n現在，這只能在某種非常情態下使用，但要是死亡之翼腐化了泰坦看守者，他就能用箱子裡的東西啟動裝置。\n\n到月亮方尖碑去，<name>。拖延他們的速度!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28272] = {title = "缺失的線索", objective = "收集7個古老鍍銅卷軸。", description = "我還缺少幾個特定的線索。\n\n一旦填補了這些空缺，我們就能啟動最後的方尖碑。接著，我們要比舒諾茲那群人更快發現應許法櫃。\n\n那些傻子正加緊趕工挖掘這處遺址。他們保存文物的速度還不及他們破壞的效率!\n\n到方尖碑去搜索他們的戰利品，<name>。\n\n看能不能找到我們需要的線索。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28273] = {title = "朋友的朋友", objective = "哈里遜要你和韋爾薩爾綠洲的蘇拉談話。", description = "我要解裝看一下這個區域。同時，我有個老朋友希望你見見。\n\n蘇拉和我認識超久。他是個值得信任的傢伙，這種人最近越來越少了。\n\n上前去自我介紹一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28274] = {title = "兩頂帳篷", objective = "陪伴蘇拉前往蘇拉的雜耍帳篷。", description = "看看你，我的朋友。你這場大冒險讓你全身打結了!\n\n你需要休息放鬆。你太緊繃了，這樣會害你累翻。\n\n相信我，我知道該怎麼放鬆!\n\n說到帳篷，看來瓊仔把我跟他要的帳篷送到了。\n\n來吧，朋友，和我一起去!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28275] = {title = "盡情轟炸!", objective = "摧毀10艘恐怖的補給艇。", description = "維爾森船廠不斷從近海接收補給品，我們必須阻止。他們沿著甲板裝設了加農砲作為防禦，但要是你能接近大砲，我們就可以用大砲來毀掉他們的補給船。\n\n去看看你能做些什麼。回來向我報告你的進度。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28276] = {title = "薩赫特的秘密", objective = "到奧丹姆的日衛者山脊南端找薩赫特。", description = "聽著，<name>。在你放棄對我的希望之前，我有東西想給你看看。\n\n你知道，我是個不怎麼樣的戰士。我協調性不是很好。\n\n我比較像是一個謀略家。\n\n到南邊的山脊旁邊來跟我碰頭，我會展示給你看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28277] = {title = "『謀士』薩赫特", objective = "與薩赫特交談，並殺死30隻血咆食腐者。", description = "從我還是個小毛頭的時候，我就一直夢想成為一個將軍。\n\n我非常渴望能加入軍隊。但如你所見，我的格鬥技術並不是很到家。\n\n這不是我第一次被派來殺土狼。事實上，我經常被派到這裡來，這讓我跟這些獅子變得很親近，而且訓練牠們去執行我的命令。\n\n牠們是我的士兵，在我的指揮下，牠們會殺死一大票的土狼。仔細看著!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "偉大將軍之冠貓科指揮護腿薩赫特的華麗匕首您會收到：\n\n"}
MultiLanguageQuestData['tw'][28278] = {title = "軍紀如鐵", objective = "在榮譽原野的20名士兵身上使用黑石戒律鬥棍。如果其中一名士兵發現了你的偽裝，在他有機會揭發你之前將他毆打至死。", description = "我一直在找像你這樣優秀、堅強的士兵。我需要有人幫我維持部隊的秩序。\n\n在堡壘外面，獸人、巨魔和食人妖們準備著對赤脊山的襲擊。我的士官正在負責管理，但我希望你能去協助他們。\n\n帶著這根棍子，整頓一下我的士兵。我不在乎他們是破壞規矩了還是乖乖站在隊伍裡，我要他們挨揍。我要他們精神專注、經得起磨練，而且服從。\n\n去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28279] = {title = "權力濫用", objective = "用黑石戒律鬥棍殺死5名黑石士官。在他們有機會揭發你之前迅速擊敗他們。", description = "<name>？我是卓特曼。\n\n聽起來你贏得索伊佐格將軍的信任，讓他將維持軍紀的工作交給了你。這可真是幸運。\n\n我們需要你把他們的士官處理掉。你會在榮譽原野的黑石要塞外面找到他們。將棍棒用在他們身上，用個幾次，直到他們死掉。你得動作快點，因為若他們理解到你不是他們的一員，他們就能揭發你。快速而兇狠地出擊，<name>。\n\n通話完畢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28280] = {title = "將他們擊落!", objective = "使用肩射式飛龍擊落裝置殺死8條龍喉黑龍。", description = "呃啊!他們在這裡，<name>。他們來了!\n\n我本來希望能為整支軍隊裝備我的肩射式飛龍擊落裝置，但我所擁有的只是一個貴到不行而且從未測試過的原型機。來，拿去!\n\n射擊盤旋在桑德瑪上空的龍喉黑龍，讓他們從空中墜落!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28281] = {title = "桑德瑪的最後防線", objective = "殺死8名步行的龍喉天爪。", description = "我得讚揚你和你聯盟朋友們的功勞。你們真的把龍喉部族打得潰不成軍!\n\n儘管他們許多騎士墜落到了地上，但他們還是不斷朝我們進攻。若沒有人幫忙，我的防禦者們將會被擊敗。\n\n殺死步行的龍喉天爪，桑德瑪氏族將永遠欠你大恩情!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28282] = {title = "『馴龍師』納克拉爾", objective = "殺死納克拉爾‧耙爪。準備好時和柯林‧桑德瑪談話。", description = "在這群人之中有一個龍喉獸人，他們稱之為「馴龍師納克拉爾」。我不知道他從哪裡取得駕馭那些野獸的力量，但他所騎乘的黑色恐怖，是有史以來出現在高原上空的生物中最難纏的。\n\n<name>，納克拉爾就是奪走我父親性命、讓我肩負起桑德瑪這項責任的惡魔。\n\n我無法獨力撂倒他，但我已經了解你的能力，<class>。也許我們能協力了結這件事。\n\n準備好時讓我知道，我們會一起和納克拉爾作戰!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "龍蔑釘錘怒縛腰鎧酒浸之握納克拉爾的護腿龍人和解法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][28283] = {title = "那格格響的玩意是啥", objective = "在千針石林的暗雲峰調查骨之波浪鼓。你看到在外面地上的那個格格響的玩意了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", description = "你看到在外面地上的那個格格響的玩意了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28285] = {title = "與派翠絲‧域法會面", objective = "到暴風城的訓練大廳與派翠絲‧域法交談。", description = "我剛剛收到訓練大廳送來的卷軸，<name>。派翠絲‧域法捎來訊息，表示希望跟你談話。你應該盡快去找她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28286] = {title = "今天破壞夠了", objective = "到鑿柄找卓特曼上校。", description = "我們對索伊佐格或黑石獸人的地面部隊沒有進一步的戰略計畫了。我們得開始下一階段的計畫。\n\n完成在要塞的工作後，回到鑿柄來找我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "計謀指環庫比特的匕首備戰腰帶完結護手機動軍團胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28287] = {title = "與穆瑞克‧勇石會面", objective = "到暴風城的訓練大廳與穆瑞克‧勇石交談。", description = "穆瑞克‧勇石的信差剛剛找到我，<name>。他有一件極要緊的事希望與你詳談，並傳話表示，希望你能盡快前往暴風城，到舊城區的訓練大廳見他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28288] = {title = "打開他們的眼睛", objective = "用戴拉瑞斯的棱柱嚇20個碧火小鬼。", description = "在你走之前…\n\n我已經和伊普斯「單獨」相處過，知道了一些關於小鬼的有趣事情。尤其是，他最後跟我說了一個所有小鬼都怕的東西。某個他們絕對害怕的東西。\n\n我覺得這有趣又實用，所以我施了些基礎咒術。這個稜柱會投射出…唉呀，總之是伊普斯說的東西的影像。\n\n潛影山脊仍然爬滿了小鬼。你去幫我探探他們的反應如何？您會收到：\n\n", progress = nil, completion = nil, rewards = "大筆錢財手套歡喜護肩彩虹指環您會收到：\n\n彩虹產生裝置"}
MultiLanguageQuestData['tw'][28289] = {title = "來自月光林地的請求", objective = "到月光林地的永夜港去和洛甘納爾交談。", description = "我收到我在月光林地的兄弟的訊息，他請求你的協助，<name>。你應該到那裡去和永夜港的洛甘納爾談談。他會把你該知道的事全告訴你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28290] = {title = "與戈莫克‧巨拳會面", objective = "到奧格瑪的兵營與戈莫克‧巨拳交談。", description = "戈莫克‧巨拳送了緊急訊息要給你，<name>。他要你立刻到奧格瑪榮譽谷的兵營去找他。他絕對是有重要的任務要給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28291] = {title = "回到營地", objective = "到蘭姆卡韓軍團哨站去找卡姆塞斯將軍。", description = "<name>，你的看法如何？或許將軍會派幾個手下來受我指揮。\n\n或許我們可以一起領導一個軍團。你覺得呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28292] = {title = "這不是金字塔!", objective = "到暴風城和暴風要塞的哈里遜‧瓊斯談話。", description = "位於奧丹姆的造物者遺跡有個和它格格不入的金字塔。那是個巨大的機械，經過調整，可以使用於各種不同的用途。\n\n死亡之翼打算讓暮光之錘將它變成巨大的武器!\n\n<name>，你得穿過傳送門來將這項資訊交給暴風城的哈里遜‧瓊斯。他會知道該怎麼做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28293] = {title = "這不是金字塔!", objective = "到奧格瑪和葛羅瑪許堡的貝洛克‧亮刃談話。", description = "位於奧丹姆造物者遺跡的金字塔根本不是什麼金字塔。那是個巨大的機械，經過調整設定就可以用在各種不同的用途。\n\n死亡之翼打算讓暮光之錘將它變成巨大的武器!\n\n<name>，你得穿過傳送門，將這個情報交給奧格瑪葛羅瑪許堡的貝洛克‧亮刃。他會知道該怎麼做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28294] = {title = "柯特海文高峰會", objective = "到暮光高地的柯特海文和拉克蘭‧麥葛拉夫談話。", description = "在狠狠教訓了他們一頓之後，龍喉對桑德瑪的襲擊應該會停止了。也許蠻錘確實該在你的聯盟中佔一席之地。桑德瑪氏族真的欠你一次。\n\n在柯特海文之上，我們的高階薩滿拉克蘭‧麥葛拉夫一直試著安排一場高峰會議，讓各個存活下來的蠻錘家族聚在一起。\n\n飛上北邊的柯特海文吧，去找拉克蘭‧麥葛拉夫談話。我會在那裡和你碰面!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28295] = {title = "和車隊碰面", objective = "到塔納利斯的灌木谷和艾達拉談話。", description = "奧丹姆造物者遺跡裡的金字塔，可以被設定為某種消滅艾澤拉斯上所有生物的超級兵器。\n\n<哈里遜沉思了一會兒。>\n\n你得繼續你所開始的研究。前往卡林多南端的塔納利斯沙漠。在那裡有個車隊正打算啟程前往奧丹姆。\n\n阿達拉是我的一個老助手。她會收容你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28296] = {title = "和車隊碰面", objective = "到塔納利斯的灌木谷和艾達拉談話。", description = "奧丹姆造物者遺跡裡的金字塔，可以被設定為某種消滅艾澤拉斯上所有生物的超級兵器。\n\n<貝洛克沉思了一會兒。>\n\n你必須繼續你所開始的美好研究。前往卡林多南端的塔納利斯沙漠。在那裡有個車隊正打算啟程前往奧丹姆。\n\n阿達拉是我的一個老助手。她會收容你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28297] = {title = "與塔瑪基會面", objective = "到奧格瑪的兵營與塔瑪基交談。", description = "我收到奧格瑪的塔瑪基寄來給你的卷軸。她希望你盡快啟程前往榮譽谷的兵營找她談話。聽起來很急迫，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28298] = {title = "與瑟加‧墓刃會面", objective = "到奧格瑪的兵營與瑟加‧墓刃交談。", description = "奧格瑪的破碎之手資深盜賊訓練師瑟加‧墓刃，希望和你會面。快點啟程前往奧格瑪，<name>，到榮譽谷的兵營去找她。她一定有很重要的任務要給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28299] = {title = "與卡茲克‧暗嘯會面", objective = "到奧格瑪的兵營與卡茲克‧暗嘯交談。", description = "我剛剛收到來自卡茲克‧暗嘯的訊息，他是奧格瑪第一流的術士訓練師。他希望你前往奧格瑪，到榮譽谷的兵營找他談話。聽起來他有重要的任務要給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28300] = {title = "與費尼斯‧法爍會面", objective = "到奧格瑪的兵營與費尼斯‧法爍交談。", description = "我剛剛收到從奧格瑪捎來給你的卷軸，<name>。寄件人是費尼斯‧法爍，他是那裡的法師訓練師。他要你去榮譽谷的兵營見他一面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28301] = {title = "與瑞塔爾‧河語者會面", objective = "到奧格瑪的兵營與瑞塔爾‧河語者交談。", description = "有個指名要給你的緊急訊息剛剛送到，<name>。寄件人是瑞塔爾‧河語者，他是奧格瑪的薩滿訓練師。他要求你盡快去見他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28302] = {title = "與阿法羅斯‧曦刃會面", objective = "到奧格瑪的兵營與阿法羅斯‧曦刃交談。", description = "你應該盡快啟程前往奧格瑪，<name>。阿法羅斯‧曦刃捎信表示，希望跟你談談關於部落的重要問題。到榮譽谷的兵營找他吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28303] = {title = "與阿法羅斯‧曦刃會面", objective = "到奧格瑪的兵營與阿法羅斯‧曦刃交談。", description = "阿法羅斯‧曦刃送了緊急訊息給你，<name>。他希望你下次到奧格瑪時，可以去榮譽谷的兵營見他一面。聽起來他似乎有很重要的事要委託給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28304] = {title = "前往奧格瑪", objective = "到奧格瑪的兵營與馬丁‧古柴爾德交談。", description = "有個信差請我把這個邀請函交給你。寄件人是馬丁‧古柴爾德，他是牧師訓練師，常駐在奧格瑪的兵營。\n\n他請你一有空就馬上去見他。兵營就在榮譽谷中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28305] = {title = "血毒崗哨的命運", objective = "到血毒崗哨和凱爾妮爾‧葉歌談談。", description = "在我們料理加德納爾的時候，我派了一個朋友前往北邊的血毒崗哨。我們偶爾會跟那裡的牛頭人往來，不過他們最近好一段時間沒出現了。\n\n我的朋友凱爾妮爾‧葉歌到現在還沒回來。你可以到北方去，看看她在血毒崗哨的情況如何？\n\n如果你找到她，請留意一件事…像她這樣的林精很容易對長得有點奇怪的種族發動攻擊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28306] = {title = "語風林地", objective = "在語風林地與看管者淨林交談。", description = "你在這裡幫了大忙！\n\n我打算繼續留在這裡一陣子，照顧牛頭人先生直到他不再嘔吐得這麼厲害為止。你何不到北方的語風林地去呢？那個地方真的很漂亮，所有的德魯伊都很友善！\n\n幫我告訴淨林小姐我很好，如果我消失太久，她會擔心的。她也許也會要你幫忙她的花！多有趣呀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28307] = {title = "前往奧格瑪", objective = "到奧格瑪的兵營與馬丁‧古柴爾德交談。", description = "有個信差請我把這個邀請函交給你。寄件人是馬丁‧古柴爾德，他是牧師訓練師，常駐在奧格瑪的兵營。\n\n他請你一有空就馬上去見他。兵營就在榮譽谷中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28308] = {title = "前往奧格瑪", objective = "到奧格瑪的兵營與馬丁‧古柴爾德交談。", description = "有個信差請我把這個邀請函交給你。寄件人是馬丁‧古柴爾德，他是牧師訓練師，常駐在奧格瑪的兵營。\n\n他請你一有空就馬上去見他。兵營就在榮譽谷中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28309] = {title = "前往奧格瑪", objective = "到奧格瑪的兵營與馬丁‧古柴爾德交談。", description = "有個信差請我把這個邀請函交給你。寄件人是馬丁‧古柴爾德，他是牧師訓練師，常駐在奧格瑪的兵營。\n\n他請你一有空就馬上去見他。兵營就在榮譽谷中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28310] = {title = "摩根的崗哨", objective = "到燃燒平原的摩根的崗哨向奧拉留斯回報。", description = "我們在鑿柄的工作完成了，這大都要感謝你。我們現在要朝東方走，前往摩根的崗哨。\n\n我們的情報指出，摩根的崗哨裡的人員已被撤離，現在大部分居民都遷入了黑石山，投入對抗黑石部族的戰鬥之中。聽起來那地方非常適合作為我們計畫最終階段的指揮基地。\n\n當然，基沙恩會在路上加入你的，我也是。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28311] = {title = "黑灰", objective = "取得9堆黑曜石灰燼。", description = "在我們打倒黑石部隊的殘兵之前，我需要你去做點採集工作。既然要做，就要做得正確，所以我們得好好準備。\n\n我需要灰，<name>。不是隨便的灰...是漫遊在西北方平原上的巨型黑曜石元素的灰。那東西是極深、極深的黑色，我們可以用在下一次的偽裝中。\n\n別擔心，你已經有偽裝了。這東西是給另一個人...嗯或者說另一個...東西的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28312] = {title = "惡魔潛伏", objective = "取得18個倒下的小鬼。", description = "西邊附近的熔岩場是火焰小鬼的溫床，長久以來，這些火焰惡魔漫遊在平原之上。照黑石軍團目前的狀況來看，如果我們小心點，或許能讓這種火焰小鬼潛進敵人後方，製造一些災害。\n\n給我帶幾個火焰小鬼的屍體來。作為惡魔，他們很容易就可以被復活，然後我們就能按照自己的目的利用他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28313] = {title = "一堆美味座狼", objective = "利用座狼鋸從被殺死的巨型灰燼座狼身上取得40份座狼厚肉排。", description = "我們需要新鮮的肉，所以你該以平原這一帶的座狼為獵殺目標。\n\n<卓特曼取出一柄大刀，然後交給你。>\n\n去獵殺巨型灰燼座狼吧。一旦殺死他們，用這柄刀鋸取走牠們身上最好部位的肉。你會發現平原四處都是這些座狼，而最近的一群則位於這裡的東北邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28314] = {title = "血腥之旅", objective = "殺死25個黑色龍裔或黑色龍人。", description = "我的腿又有點發癢了。你有興趣稍微旅行一下嗎，<name>？\n\n我們正準備前往巨槌石一帶。我想要在成行之前先調查一下黑石軍隊的狀況，或許還能順手殺掉幾個傢伙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28315] = {title = "龍之先鋒", objective = "殺死米尼歐斯、幼龍馴獸師阿庫米、『燒灼者』泰洛瑪斯和塔格納‧破喉。", description = "黑石獸人不是獨自來的。你已經看過火腹巨魔和燃棘食人妖陪在他們身邊。不幸的是，他們還找來黑龍群和他們沆瀣一氣。\n\n獸人和龍群已經派出一些勇士來駐守在集結點。那些地點豎立有插著巨龍頭骨的尖柱做記號。你和我得找到這些集結點，在戰爭開始前殲滅這群先鋒部隊。\n\n準備好了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28316] = {title = "與龍有約", objective = "將獲救的龍寶寶送去燃燒平原的滑石給阿克萊德。", description = "當我們在巨槌石附近環繞時，還有一站是我們必須過去的。\n\n記得你從幼龍丘陵解放出來的那些幼龍嗎？卓特曼一直留著他們，而我們得將他們送去某個比我們更懂得怎麼照顧的人。這個人就待在巨槌石東北邊的滑石。\n\n他的名字叫阿克萊德，他或許是贏得接下來戰役的關鍵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28317] = {title = "給索伊佐格的快遞", objective = "使用你的黑石偽裝，然後將醃肉排口味調味冰沙帶去燃燒平原的火腹熔爐給索伊佐格將軍。如果你需要一套新的黑石偽裝，去和卓特曼上校談話。", description = "索伊佐格將軍就在火腹熔爐的那群巨魔中間，那裡是巨槌石西端之上的一個洞穴。我要你將這個送去給他和巨魔們。\n\n在這包裹之中，你會找到你之前取得的座狼肉片，經過我們從風暴祭壇取來的魔化調味冰砂醃漬。\n\n如果我是你，我會盡量避免吃它。\n\n將它帶去給索伊佐格將軍。他會確保自己的士兵都填飽肚子，而幸運的話，他自己也會吃掉一些。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28318] = {title = "給尼洛拉克的快遞", objective = "使用你的黑石偽裝，然後潛入顱骨區，說服龍領主尼洛拉克收下你那一箱睡著的小鬼。如果你需要一套新的黑石偽裝，去和卓特曼上校談話。", description = "黑石部族的術士經常在顱骨區練習他們的魔法，那地方就在巨槌石的東面。他們的領導者希倫正在其他地方忙碌，所以那洞穴目前正受到另一名三巨頭「龍領主尼洛拉克」的掌管。尼洛拉克專精於龍，而非死靈法術。\n\n我已經將沉睡之砂使用在你抓補來的火焰小鬼身上。試著說服尼洛拉克他們是術士的小鬼而非火焰小鬼。當這些傢伙醒來時，他們不會開心的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28319] = {title = "給希倫的快遞", objective = "使用你的黑石偽裝，然後將清澈玻璃寶珠帶去燃燒平原的巨槌石頂上交給高階術士希倫。", description = "情報指出，高階術士希倫，也就是三巨頭中最後的成員，就在巨槌石頂上的洞穴中準備他的重要時刻。\n\n他正在等待一件貨物，名叫統御寶珠，好施行一項強力的召喚儀式。我要你將這交給他:\n\n<卓特曼給了你一顆玻璃球。>\n\n這是你從風暴祭壇取出來的清澈玻璃寶珠。它沒有一絲力量。將它交給希倫，然後偷偷祈禱他不會發現。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28320] = {title = "襲擊巨槌石", objective = "殺死200名黑石入侵者。如果你失去了交通工具，使用呼喚者號角來再次召喚。", description = "就是這樣，<name>。這就是關鍵的時刻。所有佈局合而為一的位置。\n\n整頓好自己，跟著我出發。我們要去跟阿克萊德說話，他欠我們一次幫忙，現在該償還了。我們將在這場對赤脊山的入侵開始之前阻止它!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28321] = {title = "混沌中的榮耀", objective = "殺了索伊佐格將軍、龍領主尼洛拉克和高階術士希倫。", description = "你和基沙恩要回去那座山。有三名獸人從攻擊中存活了下來，在他們死去之前，我們不會停下來休息。\n\n沒錯，我是在講那三巨頭。\n\n索伊佐格將軍爬回了火腹熔爐，龍領主尼洛拉克蜷縮在山峰上的洞穴。希倫就在顱骨區的後邊，和他的術士同伴陰謀計畫著。\n\n去創下你的功勳，<name>。獵殺那些抽抽搭搭的黑石雜碎，讓他們了解赤脊山的力量!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28322] = {title = "戰利品", objective = "到燃燒平原的摩根的崗哨檢視一箱剩下的補給品。", description = "我們今天可說推倒了一個巨人，<name>。儘管黑石獸人仍然群聚在他們的尖塔裡，我想他們短期之內無法再對赤脊山有任何計畫了。這是你和基沙恩的功勞。\n\n我得說我們還真是徹底利用了燃燒平原的各種資源，我們所收集的那些術士補給品確實好用，用來掩蔽我們那隻龍的黑曜石灰燼也是。\n\n然而，還有一些收集到的物品剩了下來。請在你離開平原之前盡情地挑選。您會收到：\n\n", progress = nil, completion = nil, rewards = "黑曜石斑點斗篷希倫的徽記灰燼座狼長靴鋒銳蠍刺腰帶魔像粉碎者之握您會收到：\n\n破裂的支配寶珠"}
MultiLanguageQuestData['tw'][28323] = {title = "前往奧格瑪", objective = "到奧格瑪的兵營與馬丁‧古柴爾德交談。", description = "有個信差請我把這個邀請函交給你。寄件人是馬丁‧古柴爾德，他是牧師訓練師，常駐在奧格瑪的兵營。\n\n他請你一有空就馬上去見他。兵營就在榮譽谷中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28324] = {title = "致命研究", objective = "找到250個荒疫樣本。", description = "我們用了相當強力的荒疫來對付南海鎮的人類。如你所見，非常有效。不過，用荒疫的麻煩是，使用完畢後痕跡會一直留著。\n\n我要你帶著這個實驗工具包去到野外，從我們放出的荒疫軟泥怪身上檢測致命讀數。對著漫遊在泥漿池的荒疫軟泥怪用致命程度解析器。拿到可靠的數據後回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28325] = {title = "綠色生活", objective = "找到8個使用過的荒疫桶。", description = "資源回收！最近都在瘋這個。女妖之王下令，作為一個種族，我們必須節省才能繁榮昌盛。大家都要盡自己的本分，對吧？那是說，你要幫我們去做我們的工作。\n\n在南海鎮散落了零零碎碎有數千個的荒疫桶。我們可以把這些桶子重複使用，製造更多的荒疫炸彈。到廢墟去把你看到的東西都撿回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28326] = {title = "調兵遣將", objective = "到燃燒平原的摩根的崗哨找卓特曼上校。", description = "<name>。聽起來你和基沙恩完成了你們的任務。我也完成了我的。\n\n回去摩根的崗哨吧。我已經準備了幾個包裹要交給那三巨頭:索伊佐格、尼洛拉克和希倫。你已經遇過索伊佐格將軍了。這就是你和其他兩員見面的機會。\n\n那是指，在我們殺掉他們之前。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "兵卒護腕警戒護腕覆滅足音瑟銀兄弟會臥底胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28327] = {title = "子彈上膛", objective = "到燃燒平原的摩根的崗哨找卓特曼上校回報。", description = "<name>，請回答。你聽得到我嗎？\n\n戰爭一觸即發。我希望你把所有包裹都送到了。\n\n我需要你回來摩根的崗哨。立刻。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "光透指環偽術士軟靴靈活滑動手套惡意言行肩甲行為失當護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][28328] = {title = "暮光的陰謀", objective = "到黑石深淵的住宅區利用白熾火炬燒毀8件暮光綱領。", description = "暮光之錘教團的影響力又廣又遠。為了與我們持續對抗，他們不斷地尋找盟友，甚至網羅了黑石深淵的黑鐵矮人到他們旗下。\n\n茉艾拉對黑鐵的掌控能力很薄弱，而隨著一天天過去，她的人民漸漸脫離她的掌控。我們一定要破壞他們的新兵徵募。\n\n我希望你去黑石深淵的住宅區，用此火炬將暮光之錘教團在那邊四處發送的書本燒掉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神聖之冠"}
MultiLanguageQuestData['tw'][28329] = {title = "憤怒的低級泡泡", objective = "殺死5隻憤怒的荒疫軟泥怪。", description = "這些荒疫軟泥怪似乎很火大。他們甚至在外表上製造出一些人類生氣的臉孔形狀。希諾特看到在軟泥池裡有這些不聽話的軟泥怪可不會太開心。\n\n去殺死你所看到的每一隻憤怒的荒疫軟泥怪，並試著把飼育池給鎖上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28330] = {title = "穢物的蹤跡", objective = "消滅軟泥怪飼養師查特。", description = "穢物的蹤跡和怒氣往市政廳廢墟而去。建築物裡想必有一攤軟泥怪養殖池。殺進去並且和你所遇到的任何軟泥怪飼養師戰鬥!\n\n南海鎮廢墟的瑟爾格‧希諾特一定想收到你勝利的消息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "希諾特的外罩長袍查特的軟泥護腕致命護腿防軟泥護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][28331] = {title = "赫爾庫拉的施予魔棒", objective = "使用赫爾庫拉的魔棒增強8名黑暗遊俠。", description = "想想看吧，我，由科爾蘇加德親自訓練的死靈大師，有段時間竟只是墓地裡的一具死屍。幸好，我精明的徒弟塞萬德，成功找了一群英雄把這樣東西給找回來:\n\n<赫爾庫拉揮舞著他的魔棒。>\n\n藉由魔棒的力量我重生了。施予與強奪之魔棒!\n\n我要你使用它去強化我們正在北邊戰場上與狼人作戰的黑暗遊俠們。用我的魔棒去恢復他們的精力吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "赫爾庫拉的另一根魔棒您會收到：\n\n"}
MultiLanguageQuestData['tw'][28332] = {title = "赫爾庫拉的命令", objective = "殺死15名血牙被遺忘者獵人。", description = "我們的黑暗遊俠在野外搜索著那些狼人破壞份子。這些狼人的黑暗主人派他們出來獵殺我們。黑暗遊俠的戰鬥能力雖然強大，但狼人經常都是成群的進行攻擊，甚至可以因此而壓倒一個黑暗遊俠。\n\n我要你到南海鎮廢墟的附近去搜索那些血牙被遺忘者獵人。殺死你遇見的每一個!為了被遺忘者，為了羅德隆!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28333] = {title = "上油的時機", objective = "使用達爾拉的爪鉤收集鐵木油壺並且使用它們幫7台鐵木切割者上油。", description = "在鐵木空地這裡出產三種東西:木材，油，還有累壞的工人。前面兩樣東西就是造成第三樣東西的主因，但我希望盡可能讓一切變得更有效率一些。\n\n我已經讓我們的切割者無薪加班三倍的工時了，因此實在是沒辦法安排讓它們進行保養的時間。\n\n用這個爪鉤把漂浮在營地四周的油壺弄來，然後拿它們去替切割者上油，可以嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "過勞護肩伐木機操作員頭盔高效法術釘錘抽油人盾牌您會收到：\n\n"}
MultiLanguageQuestData['tw'][28334] = {title = "照明彈戰爭", objective = "使用達爾拉的超強照明彈找出8名刺枝林地徘徊者並殺死他們。", description = "這裡的運作到目前為止還算順利，不過刺枝林地的那些狼人對我們造成了不少麻煩。他們用盡各種手段想讓我們關門大吉。\n\n一些工人告訴我，他們似乎瞥見狼人在林地附近潛行。我要你帶上這些超強照明彈。它們的亮度足以讓任何靠近的東西無所遁形。\n\n用這些照明彈找出在附近徘徊的狼人，並確保他們沒辦法活著離開!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28335] = {title = "關掉!關掉!", objective = "關掉鐵木山洞底部的主控幫浦。", description = "是那些天殺的狼人！他們一陣風似的從我面前衝進了那些洞穴。\n\n一定他們是把主控幫浦給毀了！如果那東西繼續這樣運作下去，我們腳下的每根管子都會炸開來。你覺得現在的漏水很嚴重嗎？等著瞧吧！\n\n聽好，如果你可以到達這個洞穴後方的主控幫浦，你就可以把它關掉並且拯救我們所有人！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28336] = {title = "掌摑工人", objective = "掌摑7名恐慌的工人好讓他們去蓋上油井。", description = "喔...別又來了!如果你聽到副隊長在外面大喊，那就表示我們手上又有漏油的大麻煩了!又是那些骯髒的狼人幹的!\n\n聽著，這裡的情況將會陷入完全的混亂。睡眠不足的哥布林四處奔跑尖叫，不知道該做什麼。我需要你去教訓那些工人，讓他們回到原本的崗位上。\n\n在他們臉上賞一巴掌應該就可以了!等他們清醒過來，他們就會回去把那些油井給蓋上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "腳底抹油軟靴石油噴發護腿勞動力護胸剝奪睡眠披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][28337] = {title = "鐵木伐木機", objective = "殺死9名鐵木切割者。", description = "真噁心，不是嗎？看看他們。可憐的小東西，連運用自己的身體進行勞動都辦不到。\n\n他們用那大型的金屬伐木機在四處移動著，把森林切砍成一片片的木條。我猜他們覺得自己在那機器裡面很安全，既溫暖又舒適。\n\n讓他們知道自己錯了。穿越營地前往北方，盡你所能的摧毀鐵木切割者。等到你讓他們灑夠了血，我們就可以徹底摧毀這個地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28338] = {title = "北方的死木熊怪", objective = "在魔爪村殺死15隻任一種的死木熊怪。", description = "在我們西南方有一處死木熊怪的營地。腐化的力量滲透了那裡，我希望能在問題變得嚴重以前解決它。\n\n死木部族非常邪惡，不過這是由於惡魔污染了他們的心智。他們天性並不壞，只是我們再也幫不了他們了。這對我來說是件悲哀的事，但我們還是得與自己的同胞作戰。\n\n拜託了，<name> - 我要你去做該做的事。只是別告訴我細節;這令人難過的景象會讓我太過傷心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "巨熊護腿尋路者頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28339] = {title = "你的油跑掉了嗎？", objective = "從油膩的軟泥怪身上收集10份原生焦油球。", description = "我們上次發生這麼嚴重的漏油時，那些油竟然自己試著跑掉!\n\n我不知道這是怎麼發生的，也許是在這裡四處漂浮的惡魔黏液在搞鬼，總之當我們試著阻止漏油時，大概有一半的油聚在一起想要跑掉。\n\n那在逃跑的可都是錢啊!去追趕那些軟泥油怪，把它們可愛、珍貴的油給帶回來!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28340] = {title = "炸彈交易", objective = "從鐵木山洞收集8份鐵木爆裂物。", description = "我的所有工人都被那些看起來像是大型黃蜂一樣的東西給趕出洞穴了！達爾拉要我來這裡收拾，但是你有看到那些東西嗎？我才不要進去！\n\n我們在裡面還留有好幾噸的炸藥，我們可不能讓它們白費了。\n\n我來跟你談個交易：你到裡面去收集那些炸藥，我待在這裡免得被那些黃蜂給宰了，如果你成功了的話，我會付你一大筆的錢！聽起來如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28341] = {title = "收集腐敗", objective = "從碎痕谷的混亂恐獸身上收集8個混亂精華。", description = "雖然我們德魯伊躲開了侵擾這座島的惡魔力量，但還是要面對它。\n\n碎痕谷南邊到處都腐敗了。那裡的能量是如此混亂，竟然具現出狂暴的實體，它們從純粹的惡魔法術凝聚成形，侵害著所有的生命。\n\n我一直很留心這些混沌的野獸，研究它們的力量。我必須確定它們仍在隨著時間減弱。把它們遺留的精華帶來給我，這樣我才能確認它們在衰退。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28342] = {title = "惡魔碎片", objective = "在碎痕谷收集9塊煉獄火殘骸。", description = "那些潛伏在碎痕谷的煉獄火是種令人畏懼的對手，不過並非無懈可擊。我們已將他們的數量削減掉不少。\n\n然而，摧毀他們只能解決一部份的問題。我發現被用來創造煉獄火的石頭，即使在煉獄火死後仍然附有大量的惡魔魔法。\n\n現在，煉獄火死後所留下的碎石在碎痕谷到處都是，腐化的力量污染了大地。如果你可以去收集這些石頭並帶回來給我，我會很感激你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28343] = {title = "塞納留斯之息", objective = "到黑石深淵去從火占師羅格雷恩身上找出塞納留斯之息，並使用這個神器關閉3個元素之門。", description = "<name>，我們已經知道有個遺失的塞納里奧神器目前落在暮光之錘火占師的手上。火占師羅格雷恩拿走了塞納留斯之息這樣神器，並把它帶進黑石深淵中，利用它的力量開啟元素之門。\n\n我們必須阻止羅格雷恩召喚元素來支援它的黑鐵軍團盟友。從他那裡取回神器，並使用它的力量關閉他羅格雷恩所使用的傳送門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "青翠之環頭飾綠意之環頭飾您會收到：\n\n"}
MultiLanguageQuestData['tw'][28344] = {title = "你可以聞出他在煮什麼嗎?", objective = "到希爾斯布萊德丘陵的南海鎮廢墟去，找到弒王者歐庫斯。", description = "就在你抵達這裡不久前，一個獸人乘著冰霜巨龍飛到這裡，要我告訴他「菜鳥聚集的地方」。由於聽不懂他在說什麼，我要求他盡他身為部落成員的責任去對付這個區域的狼人威脅。他抱怨了一陣有關「獸人煮的東西」的事情然後就往南邊的碼頭飛去了。\n\n一般來說我並不會關心一、兩個走丟的獸人，不過我真的很好奇那個獸人究竟在煮什麼。去瞭解一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28345] = {title = "*嗝*救命!*咕嚕咕嚕*", objective = "幫助弒王者歐庫斯從水中離開。", description = "*咕嚕咕嚕*\n\n救命!*嗝*\n\n「歐庫斯要淹死了!救救我!好心人!<name>!」\n\n*咯*\n\n矮人把歐庫斯丟進了水裡!不能死!\n\n*咕嚕咕嚕*\n\n這太丟臉了。", progress = nil, completion = "&lt;歐庫斯的臉變得像他的盔甲一樣紅。&gt;\n\n我...呃...那些人類一定是施展了某種心靈法術在歐庫斯身上。歐庫斯可以解釋的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28346] = {title = "單身漢", objective = "和暮光高地的柯特海文的基岡‧火鬍討論婚姻的展望。", description = "我們要讓這件事成功，<name>。答案就在血液裡!家族羈絆是讓蠻錘氏族彼此離異的原因。想要復合就得靠家族羈絆。這得花時間，不過我們要當和事佬!\n\n我會找出柯林‧桑德瑪並和他談談。你比較圓融，所以你要去和基岡‧火鬍交心。他很敏銳，能夠理解政治聯姻。去問問他喜歡誰!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28347] = {title = "Coffer of Promise TRACKING QUEST", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28348] = {title = "雷矛集結地", objective = "從歐庫斯那裡瞭解有關雷矛集結地的事情。", description = "我追蹤到那名衰老的死靈法師，赫爾庫拉，希望能夠藉此找到在希爾斯布萊德的聯盟。\n\n赫爾庫拉交代我一項任務，找出並殺死那些狼人。一般來說這對歐庫斯並不是什麼問題，但是我剛吃完了幾份戴格的美味奇美洛克肉排，害得我的腸子有點疼痛。這就是麻煩的開始和我掉進水裡的原因。\n\n聽聽歐庫斯的話吧，<name>。", progress = nil, completion = "我會為我自己報仇的，不過首先我們得治好卡沙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28349] = {title = "行銷部門的梅格斯", objective = "到凱贊的卡亞羅貿易公司總部找梅格斯‧驚懼伐木機。", description = "老闆，你在礦坑裡的時候，行銷部門的梅格斯‧驚懼伐木機問起你。是有關你新坐騎的事?\n\n她就在這建築外的左邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28350] = {title = "誘餌大師", objective = "蘇拉要你收集5塊奧丹姆野生動物的碎肉塊。", description = "有件關於我的事你該知道，<name>...\n\n我們一家都是陷阱大師。我父親教導我精通設置陷阱的藝術，就像他父親教給他一樣。\n\n就像任何一個陷阱大師會告訴你的一樣，一個好陷阱的最重要元素就是誘餌。\n\n所以就從那裡開始吧。\n\n將這個籃子裝滿任何奧丹姆野生動物的碎肉塊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28351] = {title = "潛力無窮", objective = "使用強化過的籠子捕捉5個活蹦亂跳的俾格米。", description = "有些人將小俾格米視為害蟲，甚至是下流的小惡魔。\n\n但我認為，這是天大的誤會!\n\n只要悉心照料、教導，這些小傢伙也能成為大自然寶貴的禮物。\n\n我要你帶著這些籠子，抓幾隻俾格米給我。\n\n你得先好好揍他們一頓，才能把他們裝進籠子，不過到頭來，這都是為了他們好。\n\n你等著瞧吧!\n\n去南邊找俾格米!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28352] = {title = "托駝妥拓", objective = "使用蘇拉的韁繩馴服3隻駱駝。", description = "你好，朋友！\n\n我簡陋的篷舍永遠歡迎你。\n\n想找點事情做嗎？找蘇拉就對了！\n\n擁有幾隻駱駝總是好的，不過若想準備一場表演，牠們就是不可或缺的角色！\n\n帶著這個韁繩，馴服一隻遊蕩的駱駝。\n\n或許你得先，呃，想辦法讓牠們乖點…知道我的意思吧。\n\n你會在南邊發現一個充滿駱駝的沙漠。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28353] = {title = "瓊仔在找你", objective = "到韋爾薩爾綠洲與哈里遜‧瓊斯交談。", description = "聽著，<name>，若有時間，你或許會想要回去找一下瓊仔。\n\n不管他想跟你討論什麼，可能都比我要你做的事情更緊急。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28354] = {title = "卡沙會再飛起來的", objective = "收集8株泥嘴花。", description = "卡沙會再飛起來的，<name>。她一定得再飛起來，我們才有報仇的機會!可惜歐庫斯得留在這裡陪卡沙。你得幫助我們。我求求你!\n\n仔細聽好了。當我第一次來到這裡時，我在這四周飛了好幾天才弄清楚這塊土地的形勢。在這裡的東邊有一個被廢棄已久、現在被豺狼人佔據的農場。在那個農場上長著一種被稱為泥嘴的特殊蘑菇。我需要你去那裡幫卡沙收集一些泥嘴回來。把你的背包裝滿後回到這裡來。", progress = "你取回那些泥嘴了嗎？", completion = "這個蘑菇對活著的東西來說是有毒性的，但卻可以快速的恢復不死生物的生命力。讓我們看看卡沙的反應吧。", rewards = "紅色騎乘手套泥嘴肩甲弒王者胸甲歐庫斯騎乘肩甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28355] = {title = "可怕的小東西", objective = "在奈杉德崗哨殺死10隻豺狼人。", description = "豺狼人!這些可怕的小東西在任何地方都像是一場瘟疫，現在希爾斯布萊德是被遺忘者的領土，所以你可以想像這樣說代表他們有多麻煩。為了這個世界好，到奈杉德崗哨去盡你所能的殺死那些豺狼人!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28356] = {title = "先發制人", objective = "在東部海灘殺死15隻納迦。", description = "這些計畫文件似乎描述一場即將對南海鎮進行的攻擊。聯盟被趕出之後，東部海灘的那些納迦正計畫著要奪走這座城鎮。\n\n在你的幫忙下這是不可能的事!\n\n到東部海灘去殺死所有的納迦，然後前往南海鎮廢墟，向赫爾庫拉報告有關刺脊納迦攻擊計畫的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "先制攻擊法杖刺脊匕首刺脊之球東部海灘指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28357] = {title = "衝入樹林", objective = "殺死8名刺枝林地防衛者。", description = "那些骯髒的野狗以為他們可以偷偷摸摸的溜到我基地附近，然後再從容的離開?我會讓他們知道厲害的...\n\n我的意思是，「你」會讓他們知道厲害的。你和那些被我派去刺枝林地的斧刃哥布林部隊。\n\n這個地方滿滿的都是狼人，而這正符合我們的期待。我要你到東南方和我們其他的部隊會合，然後製造一些飛舞的毛皮吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28358] = {title = "獵殺被詛咒者", objective = "殺死6名煉獄火哨衛。", description = "煉獄火是最早涉足這座森林的惡魔。很久以前，這些石頭和火焰所形成的強大惡魔從天而降，想要為燃燒軍團奪下這塊土地。\n\n在碎痕谷南邊的那些隕石坑，就是當初煉獄火降落的地點，至今仍有許多煉獄火在那附近徘徊。他們是兇猛的對手，殺死他們不僅是個值得的挑戰，也是一件光榮的工作。\n\n我提供懸賞給那些加入獵殺煉獄火的人。完成之後回到我這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28359] = {title = "克羅蘇斯的核心", objective = "取得克羅蘇斯的煉獄火之核。", description = "在碎痕谷最令人畏懼的惡魔名叫克羅蘇斯。這些年來有許多人試著獵殺他，結果只是讓他變得更強大。\n\n一次又一次的，術士來到這座森林裡復活了克羅蘇斯。現在他就潛伏在東南方，被惡魔火焰圍繞，等待著任何想試著奪取他力量的傢伙到來。\n\n我不想讓這樣的循環再繼續下去了!殺死克羅蘇斯，把他的煉獄火之核帶來我這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "暗影詛咒兜帽語風臂環煉獄火胸甲術士剋星盾牌您會收到：\n\n"}
MultiLanguageQuestData['tw'][28360] = {title = "追獵行動", objective = "殺死8隻魔腐鹿。", description = "我很希望能拯救這森林裡的每一隻生物，但是你也許已經發現，其中有些實在是無可挽救了。\n\n在我們最早發現語風林地時，南方的樹林裡有著許多漂亮的巨角鹿，一種神秘而友善的生物。這裡的腐化還沒使牠們變得凶暴，但是也已經奪走了牠們的一切。\n\n就算我們能夠將牠們淨化，最後也只會讓牠們對現狀感到痛苦。拜託了，<class>，幫我結束牠們的痛苦吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28361] = {title = "清洗松鼠", objective = "擦洗6隻被感染的松鼠。", description = "較大型的動物通常都腐化得太深而難以挽救，但是你會對那些小東西的韌性感到驚訝。\n\n例如那些松鼠。在浸泡過被腐化的水之後，牠們能將疾病散播到距離源頭極遠的地方，但牠們自己受到的影響卻要緩慢許多。事實上，只要簡單地清洗牠們，就可以重新得到一隻乾淨的松鼠，並且讓森林變得更加安全些!\n\n帶著這個裝有清潔溶液的瓶子。到南邊的樹林去，把你看到的每一隻松鼠抓來用力擦洗一番...牠們會為此感激你的!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28362] = {title = "愚蠢的德里佐!", objective = "到魔爪村去找到德里佐。", description = "愚蠢，愚蠢的德里佐！我叫他別去的！\n\n德里佐想要從魔爪村偷盜一些蜂蜜…你知道的，就在西邊那裡？你可以從懸崖上看到它…\n\n無論如何…我告訴他那是個笨主意，但是他還是去了，然後被那些死木部族的傢伙逮個正著，然後…然後…\n\n吸鼻涕…\n\n我不知道他們要怎麼做！請你幫忙找到他，<race><先生/小姐>！就算德里佐很笨！我也不希望他被吃了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28363] = {title = "驚動黃蜂巢", objective = "到蘇拉的雜耍帳篷找蘇拉說話。", description = "哇!\n\n看來你真的引起他們的注意了，<name>。在他們這麼警戒的情況下，我們永遠也不可能通過。\n\n一定有什麼法子...\n\n舒諾茲那群人啟動尖塔只是時間問題，我還需要研究你找來的那些卷軸。我要你自己想辦法。\n\n蘇拉在這附近有點人脈。或許他有辦法讓我們進到裡頭去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28364] = {title = "酋長的鑰匙", objective = "從血喉酋長那兒取回德里佐的鑰匙。", description = "(吸鼻涕)...我很抱歉!我沒有想到會被抓到!他們抓到了我，然後用這條鎖鍊綁著我丟在這裡!我沒辦法移動，連腳都麻痺了，而且又餓又渴!\n\n鑰匙在他們的酋長那裡...血喉酋長，其他人是這麼叫他的。他就在營地北邊的盡頭。\n\n不過你的動作要快一點!拜託!別把我一個人丟在這裡!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "惡災護腿啜泣外衣血喉腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][28365] = {title = "<PH>Drizle Safe", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28366] = {title = "解除熊怪的武裝", objective = "在魔爪村收集7件死木熊人武器。", description = "可以選擇的話，我寧願選擇不殺死每個死木部族的傢伙就能保護我們族人的方法。我們之前這樣嘗試過，如果你想要向木喉部族證明自己，我會希望你也這樣做。\n\n到魔爪村的西南方找到他們堆放武器的地方。然後盡可能的把它們帶走。如果我們能夠解除死木部族的武裝，我們應該可以稍微減少之後的流血事件。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "木喉護腕木喉護腿木喉長靴木喉胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28367] = {title = "造物主罩氅", objective = "破壞7個舒諾茲火藥桶。", description = "有朋友真好，<class>!除了友誼之外，還能得到一些實質的利益!\n\n我朋友最近攔截了一批舒諾茲劫掠的貨物，發現有個東西你正好用得上。\n\n它是一種泰坦科技，可以讓使用者幾乎完全隱形。如果你在敵方營地使用它，就可以重設他們的炸藥，把他們的行動搞得一團糟。\n\n每次充電只能維持一段時間，別離安全的地方太遠!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "重新發現的三角洲行走靴火藥桶護腕維爾納爾護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][28368] = {title = "要爆炸了!", objective = "殺死『永燃者』葛羅維塔。", description = "土地就是財富，伙計!你把那些閥門關上真是大功一件。\n\n不幸的是我們的中央調節器已經炸掉了!達爾拉小姐盡可能的派出她的人去把它關掉，但是那些火焰自己會思考!\n\n真的!它們會冒出來抓住任何靠近的人!所以達爾拉說，如果你有勇氣進到那個洞裡，解決那個元素怪物的話，她將會把庫藏裡最有價值的東西獎賞給你!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "原始力量護手永燃披風訓寐者指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28369] = {title = "我妹妹，芬妮", objective = "到暮光高地的桑德瑪和芬妮‧桑德瑪談話。", description = "在你離開之前，務必到我身後的旅店去看看。我的妹妹芬妮在裡面。\n\n難民從我們四周被燒毀的蠻錘居住地湧進桑德瑪來，我讓芬妮去管理。她那傢伙就像猛禽一樣強悍。但她也許會需要你幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28370] = {title = "捕捉幽光", objective = "使用達爾拉的幽光磁鐵收集5隻刺枝林地幽光。", description = "你能相信這裡的狼人竟然有幽光嗎?那些夜精靈把所有的德魯伊垃圾都教給他們，現在他們也有了那些寶貝幽光，可以不用傷害任何寶貴的樹木就獲得建築所需的原料。\n\n如果我們也擁有那些玩意的話，就可以在我們的基地搞出更多額外的木材了。免費的資源，免費的利益!所以我做出了這個收容裝置。\n\n我要你過去刺枝林地，用它把一些幽光給偷過來。只要對準那些東西然後按下按鈕就可以了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28372] = {title = "回到正事", objective = "飛到鐵木林場並和達爾拉‧訓寐者交談。", description = "這些快樂的友情遊戲真是棒，不是嗎？人們一起工作，治療著這座森林。不過這座森林被治癒時會發生什麼事？就讓它這樣坐落在這裡嗎？\n\n我們需要這些木材。部落需要它。我收到命令，要所有忠心的部落士兵：我很確定你是其中一名！ 到北方的鐵木林場去。\n\n我已經讓角鷹獸管理員為你安排一隻免費的坐騎。當你著陸時，去和達爾拉‧訓寐者交談吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28373] = {title = "木喉要塞", objective = "在木喉要塞與納菲恩交談。木喉要塞就在東邊，穿過魔爪村的位置。", description = "好吧，我知道這有點過份，不過我猜問一問也不打緊。\n\n在我待在這裡處理這些荒謬事件時，我需要你去和一些熊怪談談。木喉熊怪控制著這裡東北方的森林，他們並不太喜歡我們。\n\n我需要有人過去，讓他們瞭解部落並不壞。沿著路走到東北方的木喉要塞去，別走進魔爪村了! 然後問問外面的那個熊怪是否有任何事情需要幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28374] = {title = "清理草地", objective = "拔起7株語風鞭笞者，檢查他們是否受到腐化的作用。", description = "在像這樣的地方，即使是一花一草也可能需要英雄的照護。\n\n在這座樹林裡的蘭草鞭笞者算得上是治療效果的一項指標。但是它們並不完美;其中一些蘭草鞭笞者偶爾還是會受到惡魔腐化的影響。\n\n我發現，檢查它們是否受到腐化影響的最好方法就是把它們拔起來檢查。如果它們的狀況正常，它們將會遊蕩一陣子然後重新扎根。否則的話...你最好準備好作戰吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "繁花窄褲淨林肩甲拔草人護腕荊棘結界護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][28375] = {title = "通往贖罪之路", objective = "陪弒王者歐庫斯到贖罪島去。", description = "該是復仇的時候了，<name>。卡沙又能飛了，這都要多謝你。她會載著我們到贖罪島去，我們將可以直接面對雷矛矮人的將軍，范達爾‧雷矛，還有他的上尉，巴琳達‧石爐。「兩個」都得為他們所做的事情付出代價。\n\n你準備好了嗎？歐庫斯沒辦法一個人完成這件事。", progress = nil, completion = "這個地方有種黑暗...不祥的預感。這裡聞起來有種尿騷和毛皮的味道。這裡一定有狼人，很可能也有矮人在。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28376] = {title = "米澤里安的頭顱", objective = "將米澤里安的頭顱帶去蘇拉的雜耍帳篷給蘇拉。", description = "死亡之翼手下最令人生畏的一隻黑龍，其頭顱就正在你的手上。\n\n艾澤拉斯有許多人願意為了這樣的神器付出大筆財富，但你認為它應該被放在一座博物館內，供人瞻仰，記取歷史教訓。\n\n哈里遜‧瓊斯應該有什麼合適的管道。\n\n蘇拉會很樂意將東西交給他的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n煉獄紅寶石琥珀石海洋藍寶石"}
MultiLanguageQuestData['tw'][28377] = {title = "噁腸巨魔谷地救援行動", objective = "到暮光高地的噁腸巨魔谷地找柯林‧桑德瑪。", description = "才剛說到穿藍色洋裝的惡魔，芬妮竟然就讓自己被巨魔給綁架了!\n\n我不相信桑德瑪矮人能自己展開救援。我會集合我的獅鷲騎士提供空中支援。\n\n我確定他們會用得著一個額外的<class>作幫手，<name>。拿著你的裝備去噁腸巨魔營地找柯林‧桑德瑪。就在這裡的西南邊的峭壁下面。現在快去!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28378] = {title = "尋找芬妮", objective = "找到並救出芬妮‧桑德瑪。", description = "我們已經在摧毀他們的營地，<name>，但是沒有芬妮的蹤跡。也許你找得到她。\n\n我們還沒搜過我後面西北方的那個洞穴。看你能不能在洞裡找到芬妮!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28379] = {title = "痛擊巨魔", objective = "消滅10個噁腸巨魔(噁腸搥擊者、噁腸投擲者或噁腸猛擊者皆可)。", description = "噁腸巨魔!我打賭他們就跟一袋錘子一樣笨，但是我還比較尊重我的錘子。\n\n我們多年來都在抵抗他們的侵略，但要是他們大膽到偷我們的東西，我們就得好好給他們上一課。\n\n幫我們幹掉幾個噁腸巨魔!殺掉他們的搥擊者、投擲者或是猛擊者，在這裡也可以，在洞穴裡更好。給他們點顏色看看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28380] = {title = "山洞裡的皮克威克", objective = "到鐵木山洞去和工頭皮克威克交談。", description = "這裡發生什麼事了？工頭皮克威克應該要已經把那些閥門給關上了。\n\n我們可以花上整天把這些漏油給蓋上，如果能把中央閥門給關上的話，我們就可以拖延這場大爆炸一陣子。\n\n聽著，如果你重視錢、重視生命、或是兩者你都重視，你最好到南邊的鐵木山洞去，看看你能不能找到工頭皮克威克。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28381] = {title = "女導師", objective = "飛到刺枝林地並和女導師烏莉卡談談。", description = "在距離北邊不遠的位置，哥布林破壞著這片森林，地毯式地砍伐樹木，提供給部落做戰爭器具的燃料，並從中大賺一筆。這傢伙用漂亮的詞彙與精美的謊言矇騙了這裡的德魯伊，讓他們睜一隻眼閉一隻眼，以免打擾到此地脆弱的中立狀態。\n\n刺枝林地的狼人受夠了。加入我們吧!角鷹獸管理員可以將你直接送到我們的家鄉。女導師烏莉卡將會歡迎任何願意加入戰鬥的<race>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28382] = {title = "根源之敵", objective = "殺死8名鐵木砍伐者。", description = "哥布林已經惹上我們了!\n\n我們試過用任何方法來警告那些哥布林，要他們在我們訴諸暴力之前離開鐵木空地。在對我們的警告置若罔聞後，我們發動了攻擊，但他們仍寧願為了貪婪冒生命危險，也不願意就此放過這座森林。\n\n他們很快就會知道我們有多麼的憤怒!戰爭就在北方大門之處展開。帶著榮耀加入我們的族人，殺掉那些膽敢出現在我們面前的哥布林!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "運送人肩甲置之不理頭盔刺枝血水盾牌您會收到：\n\n"}
MultiLanguageQuestData['tw'][28383] = {title = "樹木之魂", objective = "使用疾風枝條收集5個刺枝林地幽光。", description = "我和導師在這裡辛苦了好長一段時間，傳佈有關塞納留斯的教誨以及野性之道的知識。她讓我非常地信任，作為回報，我允許她向學生們介紹有關森林之魂的奧秘。擁有幽光的陪伴是一項莫大的榮耀，同時也是很好的祝福。\n\n但如今哥布林正向我們襲來，打算竊取幽光進行邪惡的計畫。拜託，阻止如此的褻瀆行為!\n\n用受祝福的枝條將西方森林內的幽光召喚回此地，然後保護它們的安全。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28384] = {title = "進入空地", objective = "在鐵木山洞附近和艾爾頓‧雷汀談談。", description = "我們一定要夷平鐵木空地。如果我們要阻止哥布林為整片森林帶來毀滅，我們就必須冷酷無情。\n\n艾爾頓‧雷汀是我最信任的守護者，他率領了大部分的族人埋伏在敵人的陣線週遭，好趁他們分神應付此地時，伺機展開突擊。去西邊那個能眺望鐵木山洞的地方找他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28385] = {title = "石油與反諷", objective = "到鐵木山洞的底部秘密破壞主控幫浦。", description = "我打算將哥布林的貪婪和污染反加諸到他們身上。他們對這片飽受他們傷害的土地的每一次掠奪，都將成為阻止他們進一步擴張的有利代價。\n\n在我們下方的鐵木山洞深處，遍佈著許多抽取地下石油的幫浦管線。這些管線都連結到洞穴深處的主控幫浦之上。\n\n進入山洞並破壞幫浦，緊接而來的大混亂就會提供我們發動最後攻擊的絕佳機會。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28386] = {title = "借來的炸彈", objective = "從鐵木洞穴中收集8個鐵木爆裂物。", description = "我們下方那個鐵木山洞裡的工人已經被驅趕出去了。有其他的東西攻佔了那個洞穴。\n\n這情況對我們有利。我看到他們在逃跑時丟下不少炸彈...我們可以在下一階段的計畫中用到這些炸彈。\n\n進入山洞，回收你所能找到的每一個炸彈。搞定這些炸彈和幫浦之後，我們就可以展開最後的突襲了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "腳底抹油軟靴艾爾頓的護腿抗議胸甲鐵木披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][28387] = {title = "燒光光", objective = "用遭竊的鐵木爆裂物點燃7個鐵木林場的油井。", description = "你對幫浦的破壞使得他們的整個營地到處都是漏油。那群哥布林為了油井緊張得不得了，不過我們還能火上加油。\n\n把你收集到的炸藥帶著，讓油井陷入火海。我們要盡力破壞營地，讓他們沒有油可以發動伐木機...或者是更糟糕的部落戰艦。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28388] = {title = "血汗工資", objective = "殺死7名恐慌的工人。", description = "悲哀的膽小鬼...看看他們驚慌逃跑的樣子!\n\n別被他們騙了，<name>。只要他們一恢復理智，那些哥布林又會用盡所有的力氣來把森林砍成木片，然後送去給部落作為軍事用途。\n\n別給他們機會。徹底殺光鐵木空地裡的工人，沒有任何憐憫...讓他們為自己的貪婪付出代價!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28389] = {title = "向女導師報告", objective = "到刺枝林地和女導師烏莉卡談話。", description = "哥布林四散奔逃，裝備也受到毀損，他們應該都了解我們所傳遞的消息並且離開了，就算有人選擇留下，我們也可以輕鬆地對付。我們贏了。\n\n你戰鬥起來就像我們的族人一樣勇猛，<name>。回去找女導師並讓她知道我們的勝利。我會繼續在這裡監視著。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "獸群之拳女導師披風結合信物您會收到：\n\n"}
MultiLanguageQuestData['tw'][28390] = {title = "葛羅普，葛羅普之子", objective = "和大地治癒者諾爾莎拉談談，然後殺死真菌師葛羅普。", description = "葛羅普有個兒子。傲慢的他把他也命名為葛羅普，如此才能延續真菌師的血脈。\n\n我要你去殺死這個新的真菌師。你的薩滿盟友已經回來了，就在他位於維洛克村西南方的洞穴等著你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28391] = {title = "騷亂的族群", objective = "擊敗艾瑟拉。", description = "艾瑟拉躁動又倔強。她對我們的統治叱之以鼻，需要有人提醒她自己的立場。\n\n我還留著你為我取得的槌子。回到蒼白棲息地的西端，敲擊共鳴水晶。\n\n我會在那裡和你碰面，並盡可能提供你幫助。讓她搞懂自己的立場，<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28392] = {title = "木喉部落", objective = "到木喉要塞的入口處和納菲恩談談。", description = "據我們所知，木喉熊怪是最後一批尚未受到腐化影響的熊怪部落。他們聚集在這塊土地的邊緣，兇猛地守護著他們的家園木喉要塞。\n\n儘管他們是高傲的生物，此刻仍需要幫忙。如果你想幫他們，沿著道路前往北方，找到木喉要塞的入口。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28393] = {title = "危險的聯盟", objective = "到黑石深淵的西部兵營殺死6個火焰衛士摧毀者，並從安格弗將軍身上找出將軍的攻擊計畫。", description = "軍情七處針對暮光之錘與黑鐵軍團的活動所做的最新報告讓我很擔心，<name>。有證據顯示，他們正在黑石山裡面計畫一個聯合攻擊行動。面對這股二合為一的武力，我們會很難抵擋，但假如我們在他們準備好進攻之前搶先行動，或許就能阻止這波攻擊。\n\n你必須到黑石深淵的西部兵營去，從安格弗將軍身上奪得暮光之錘的攻擊計畫。面對支援他的部隊的那些元素時，不要猶豫，殺了它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "皇冠面甲皇冠護盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28394] = {title = "魔像領主的創作", objective = "到黑石深淵的製造廠從魔像身上收集5樣元素模組並取得元素魔像藍圖。", description = "軍情七處有關黑石深淵的最新情報令人擔憂，<name>。看起來暮光之錘與黑鐵工程師阿格曼奇合作，製造出以元素為動力的戰爭魔像。以這些魔像對付我們簡直是一種致命的武器。\n\n你一定要阻止這樣的事發生，<name>。到黑石深淵的製造廠，奪取工程師要用來製造魔像的藍圖，並拿走他要用來發動魔像的元素模組。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n皇冠頭盔"}
MultiLanguageQuestData['tw'][28395] = {title = "給納菲恩的羽毛", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28396] = {title = "給格拉茲的羽毛", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28397] = {title = "他們料想不到的...", objective = "在贖罪島殺死8名雷矛矮人和8名血牙哨衛。", description = "他們沒在有機會的時候把我殺死是個錯誤。他們大概以為歐庫斯會溺死吧。哈!現在他們得為他們的草率付出代價。\n\n你跟我將撕碎這塊土地，<name>。他們料想不到的!等他們的士兵全都死光後，我們將面對他們的領導者。記得留意他們的攻擊計畫。如果可以取得他們的攻擊計畫，我們將能徹底阻止他們的入侵!\n\n讓我們出發吧，<name>!", progress = nil, completion = "看看這場屠殺，&lt;name&gt;。你跟我真是合作無間!\n\n現在讓我們找出那些計畫並且對付他們的領導者吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28398] = {title = "火占師的魔典", objective = "殺死6位暮光使者並在黑石深淵的索瑞森神殿從火占師羅格雷恩身上取得羅格雷恩的魔典。", description = "黑鐵部隊和他的暮光之錘戰友在黑石山日漸強大。火占師羅格雷恩，一位有名的法師，扮演著領導暮光之錘部隊的重要角色。若我們能取得他的魔典，我或許能夠研究出反制的法術和其他減弱他們元素魔法的方式。\n\n你必須要潛入黑石深淵，找到索瑞森神殿，然後奪取魔典。不要放過羅格雷恩和他的暮光嘍囉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n皇家巫師兜帽"}
MultiLanguageQuestData['tw'][28399] = {title = "禁錮之石", objective = "從黑石深淵收回6件元素束縛之石。你可以在影爐城，住宅區，索瑞森神殿，西部兵營和東部兵營找到這些石頭。", description = "我確信軍情七處很關切暮光之錘和黑石深淵的黑鐵矮人之間的合作。我們可以利用這個情報，證明我們對聯盟的價值，並同時為我們自己獲得利益。\n\n情報指出暮光之錘的跟隨者在影爐城，住宅區，索瑞森神殿，西部兵營和東部兵營放置了具有元素能量的石塊。找到並捕獲這些石塊!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n正當罪行角帽"}
MultiLanguageQuestData['tw'][28400] = {title = "部落的英雄!", objective = "偷走聯盟戰鬥計畫並成為部落的英雄。", description = "現在我們要找出他們的戰鬥計畫，然後解決掉他們的領導者!成功之後，去找一個曾參與銀松森林戰爭的獸人高階督軍，他正駐紮在位於希爾斯布萊德心臟位置的塔倫米爾。他會為了我們的功勞好好表揚我們一番!我們將成為部落的英雄，<name>!\n\n前進吧!讓我們一起擊敗骯髒的聯盟!", progress = "<高階督軍克洛姆什看來有些悶悶不樂。>", completion = "&lt;高階督軍克洛姆什向你行了一個軍禮。&gt;\n\n他將被尊崇為部落的英雄，正如他一向希望的。你和歐庫斯所完成的事將拯救數百條性命，並確保我們不致失去在希爾斯布萊德的立足點。", rewards = "英雄腰帶英雄手套英雄肩甲英雄長靴英雄肩鎧英雄護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][28401] = {title = "炎魔的奴隸", objective = "使用自由圖騰解放黑石深淵的6位火焰衛士，火焰衛士摧毀者，或熾熱火焰衛士。", description = "在黑石深淵的大廳裡，邪教暮光之錘和黑鐵矮人正在召集軍隊。而他們軍團的主力，是大量受到束約、必須服侍炎魔拉格納羅斯的火元素。\n\n如果我們有辦法將這些元素從束約中解放，就能同時削弱敵人的力量，並且讓元素們獲得自由。拿著這個圖騰，對被制伏住的火焰衛士使用它。這能讓它們的靈體從束縛中解脫，恢復它們正常的狀態。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "先知頭罩先知面具您會收到：\n\n"}
MultiLanguageQuestData['tw'][28402] = {title = "舒諾茲太飛快", objective = "殺死10個舒諾茲精英裝甲兵。", description = "我快準備好了，<name>。\n\n你的卷軸裡有充足的訊息能破解他們的加密法。現在我只需要進行譯碼的工作。\n\n我要你偵察月亮方尖碑下方的房間。應該有些舒諾茲的部隊在那裡躲過了你的攻擊。\n\n去處理掉他們，我完成後在那和你會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28403] = {title = "壞掉的數據", objective = "在月之大廳陪伴哈里遜‧瓊斯。", description = "大廳內應該有兩組泰坦通訊設備。\n\n如果我翻譯得沒錯，其中一個是死亡陷阱，另一個才能接收密碼啟動尖塔。\n\n希望我沒搞錯。\n\n你準備好就跟我說一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28404] = {title = "我要親手做", objective = "打倒泰坦守護者。", description = "沒錯，這看起來真眼熟。\n\n感謝你為我收集的所有資訊，我確定我能啟動機制。只要有人幫我爭取一些時間。\n\n在我開始之後，不用懷疑，那具泰坦的傀儡絕對會跑來試著阻止我。\n\n那就是你的用處了。\n\n我不用提醒你這關係到多少事。拿下那名守護者!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "守護者殺手腰鎧泰坦足靴阿姆圖爾護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][28405] = {title = "黑暗的武器", objective = "從黑石深淵的鐵怒矮人那裡取得5件元素灌注武器，然後在影爐城的黑鐵砧上方將武器銷燬。", description = "黑石深淵長期以來一直是我們敵人的巢穴，但現在軍情七處傳來的消息指出，黑鐵部族和暮光之錘的交流漸漸增加了。黑鐵矮人運用暮光邪教傳授的知識，在武器裡灌注了元素能量。他們已經讓鐵怒軍團裝備上這些嚇人的新武器了。\n\n我需要你去黑石深淵收集鐵怒矮人的武器，並在影爐城中心的黑鐵砧上面將這些武器銷毀。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "秩序頭盔秩序面甲秩序護盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28406] = {title = "黑鐵軍團", objective = "使用急性毒藥在黑石深淵的西部或東部兵營的6袋穀物口糧裡面下毒。", description = "黑石山的事情越變越精采了，<name>。情報指出黑鐵矮人與暮光之錘已結成聯盟，並聯手準備著一波大攻擊。\n\n我已將情報內容告知暴風城的重要首領，同時我要你協助處理這股新起的黑鐵威脅。\n\n黑鐵軍團將大部分糧食存放在黑石深淵的東部和西部兵營。拿著這瓶毒藥，將它摻入他們的儲備糧食。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n軍情七處特殊用途面罩"}
MultiLanguageQuestData['tw'][28407] = {title = "俏女郎", objective = "到暮光高地的柯特海文和芬妮‧桑德瑪談話。", description = "火鬍？娶我妹妹！？這個世界瘋了，<name>！\n\n不過，也許庫德蘭是對的。一個出色的正統婚禮可以慰藉大家的心…也許還能讓火鬍冷靜點。能夠真的一起對抗巨魔感覺確實很棒。\n\n那好吧！就看芬妮的意思。但我有感覺她還不想定下來。\n\n回柯特海文看她願不願意。我要在這裡和巨魔了結這件骯髒事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28408] = {title = "勇敢的東西", objective = "收集12根原始貓頭鷹羽毛。", description = "依照傳統，蠻錘的新娘都穿白色以表示她們的純潔。另外，還戴黑羽毛頭冠，表示她們「無所畏懼」。\n\n貓頭鷹羽毛最亮眼，最配得上芬妮。黃褐色貓頭鷹生長在高地。去找貓頭鷹，牠們在峭壁邊緣的樹附近盤旋，去拿牠們的羽毛。\n\n不過首先你要殺了牠們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28409] = {title = "釀製的東西", objective = "和柯特海文東邊路上的哈墨爾海德談話，並護送補給商隊回到城鎮。", description = "蠻錘婚禮沒有酒是非常沒面子的。庫德蘭自己從高岸堡叫了幾桶少見的雷霆啤酒送上岸，但是商隊過不了小徑。\n\n沿著雷霆之擊山南邊往東的路，趕上商隊。找一個叫哈墨爾海德的人，幫他把酒弄過小徑來!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28410] = {title = "偷來的東西", objective = "收集一捲優質暗布。", description = "每個人都想為了這件事打扮得最體面，但是高地的華服正短缺。\n\n我知道岸邊那些卑鄙的哥布林用上好的絲線來修理他們的飛艇氣囊。真浪費!\n\n去找一艘在龍喉港和克拉茲工坊間來回的飛艇，從下層甲板的貨物裡拿些絲線。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28411] = {title = "燉煮的東西", objective = "收集8塊新鮮鹿肉和5塊座狼肋排。", description = "最後，我們會需要一頓大餐。不要什麼「小點心」的!這些人要吃肉，很多很多肉。\n\n去從高岸堡麋鹿和高岸堡雌鹿身上收集鹿肉。高地座狼也很好吃，帶點狼肋排回來。我們要弄一頓你從來沒在東部王國見過的大餐給你看，朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28413] = {title = "作詞作曲者是...", objective = "和羅賽爾‧布羅爾談話，幫他寫首歌。", description = "我一生中寫過許多經典名曲，<name>，但是這場即將到來的婚禮絕對要有一首非常特別的歌曲。而且要快！\n\n我該寫首情歌嗎？還是輕快小曲？胡鬧的飲酒歌？\n\n我需要有人幫我想歌詞，如果你願意試試的話。\n\n和我聊聊，讓我們一起來寫歌！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28415] = {title = "七隻!沒錯!", objective = "抓到7隻火蠅。", description = "我們必須採取行動。溫奇和戈泰什起了爭執，所以我準備了這個友情儀式來幫助他們兩人重修舊好。一切進展得很順利，直到...\n\n嗯，你知道接下來的事。\n\n我甚至還準備了飲料!\n\n溫奇喜歡火蠅。他幾乎每個晚上都跑出去抓那些蟲子。我想他也許就正在那裡。\n\n前往西邊和北邊，只要有熔岩的地方就能找到火蠅。幫我弄來七隻，動作快!\n\n戈泰什說不定會接著離開!您會收到：\n\n", progress = nil, completion = nil, rewards = "肚皮按摩手套火蠅肩甲戈泰什的長靴您會收到：\n\n小火蠅"}
MultiLanguageQuestData['tw'][28416] = {title = "燃燒的復仇", objective = "殺死5名黑石畜養者和5隻火鱗小龍。", description = "<name>…是你嗎？我以為你和其他人一樣，都死了！\n\n不，你總是很堅強，就連在過去，在赤脊山的時候也一樣。\n\n我們的戰鬥還沒完，<name>。他們已經攻擊過我們的家園。我要確保這種事不會再次發生在這裡。\n\n如果你還能像往日一樣戰鬥，那加入我。你首先可以前往南邊的幼龍丘陵，去殺死他們的畜養者和孵化的黑龍。\n\n就像以前那樣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28417] = {title = "什麼都沒做錯", objective = "取得一隻獲釋的紅龍寶寶、一隻獲釋的綠龍寶寶、一隻獲釋的藍龍寶寶以及一隻獲釋的青銅龍寶寶。", description = "這片平原上的黑石獸人侍奉著一位黑暗之主，他對活著的生物進行一些扭曲的實驗，以創造出屬於他的可憎生物。他的試驗對象大多變得如同他一般墮落，但還有許多生物是無辜的。\n\n他們將幼龍鎖在南方幼龍丘陵的地上，準備用來進行實驗。我不容許這種事情。去讓那些幼獸得到自由，然後把牠們安全地帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "幼龍守護者法杖幼龍保衛者燎星護符蟲巢重整工具您會收到：\n\n"}
MultiLanguageQuestData['tw'][28418] = {title = "燃燒的復仇", objective = "殺死5隻黑石畜養者和5隻火鱗小龍。", description = "我一出生就是黑石獸人。我大半的年輕歲月都在那座山中度過。\n\n<阿利歐克朝北邊的黑石山比了一比。>\n\n但儘管體內流著和他們相同的血液，我卻不認同他們的見解。我正在尋找一個能幫我阻止他們發動攻擊的盟友。\n\n證明自己吧。前往南邊的幼龍丘陵，殺死他們的幼獸和小黑龍。證明你已經準備好參與這場戰爭了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28419] = {title = "進貨", objective = "取得5個鋒銳蠍刺。", description = "我們必須做好計畫，才有辦法和黑石部族的傢伙開戰。我父親已經把計畫設計好了，現在只剩下執行的問題。\n\n我需要蠍尾針...要你所能找到最尖銳的那種。蠍子在燃燒平原上到處都是，但你在西邊的河谷裡能夠找到最多。\n\n不要去管用途。你負責儘快找到就好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "銳利蠍刺附魔蠍尾您會收到：\n\n"}
MultiLanguageQuestData['tw'][28420] = {title = "未來的計畫", objective = "取得11張灰燼座狼皮革。", description = "根據我父親的說法，我們需要座狼的毛皮，需要很多。就算破了、燒焦或沾滿血污都沒關係，我們就是要大量的毛皮。\n\n其實，也許有點破損反而更好。\n\n你可以在這裡的西邊和東邊找到座狼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "灰燼座狼之眼您會收到：\n\n"}
MultiLanguageQuestData['tw'][28421] = {title = "泥濘獵人", objective = "取得9堆黑曜石粒泥。", description = "希望你不怕把身上弄髒。從你的外觀來研判，這似乎不是什麼問題。\n\n前往北方的熔岩邊緣，你會發現一堆深色的泥濘。我需要那些東西。\n\n你最好不要多問，專心完成你收到的命令就好，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "黑曜石斑點風帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][28422] = {title = "沙子、蘋果酒和珠子", objective = "到風暴祭壇附近和戈瑟奇‧邪眼談談。", description = "我的父親正在東邊等我們。不過在我們出發之前，我們還需要收集更多補給。這次，你要從一個名叫戈瑟奇‧邪眼的術士身上取得那些東西。\n\n你可以在西北方的風暴祭壇附近找到他。告訴他我們需要他的幫助。我們需要沙子、蘋果酒跟珠子。\n\n他明白這是什麼意思。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28423] = {title = "術士的貨物齊全", objective = "取得一把沉睡之砂、一壺魔化調味冰砂以及一顆清澈玻璃寶珠。", description = "阿利歐克說他需要補給?我有很多的補給!但問題是，那些術士把我踢出了我的老巢，他們可不讓我回去。\n\n<戈瑟奇打量著你。>\n\n也許你可以進得去。前往北方，取得一些沉睡之砂、魔化調味冰砂以及清澈玻璃寶珠。我確定這些是他要的。\n\n噢對，如果你不小心在那裡殺了幾個獸人，我一點都不會覺得不高興的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28424] = {title = "毆打陰影", objective = "殺死『陰影』奈葛胥。", description = "『陰影』奈葛胥是北方那些術士的領導者，黑石獸人出現的時候，就是那個混蛋把我給趕出老巢的。\n\n嗯，他們都是混蛋，但他是最混的蛋。\n\n如果我想要有回到祭壇的一天，奈葛胥就必須離開。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28425] = {title = "回去找阿利歐克", objective = "到燃燒平原的燎星崗哨將術士的補給品交給阿利歐克。", description = "好吧，看來你可以幫我的都已經完成了。建立起足夠的勇氣之後，我要去把其他的術士給趕走。\n\n來，別忘了拿著這些補給品。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28426] = {title = "鑿柄，平原之心", objective = "在前往鑿柄的路上殺死15名黑石獸人。", description = "我們要前往位於平原中心點的鑿柄。我們會在那裡和瑟銀兄弟會與我父親碰頭。\n\n你跟瑟銀兄弟會熟嗎？那些黑鐵矮人幫助我不只一次了。我們或許會再次需要他們的幫助。\n\n我們途中會穿越黑齒小屋。你覺得在路上殺幾個黑石的傢伙如何？我在這個營地裡有點悶得發慌。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "款待外衣黑齒頭盔分憂肩鎧礦指火槍您會收到：\n\n"}
MultiLanguageQuestData['tw'][28427] = {title = "地獄裡的針", objective = "到燃燒平原的鑿柄和賽拉隆‧恐針談談。", description = "勝利，<class>。我的名字是伊崔格，隸屬於銀白十字軍…曾是大酋長榮譽守衛的一員。在那之前，則是黑石獸人的一員。\n\n我相信我兒子已經跟你談過我們的計畫了。還沒有？那樣也好。\n\n這個計畫的下一步需要一點機巧。\n\n和賽拉隆‧恐針談談，他是此地的裁縫師。我已經把我們收集到的皮毛和泥濘交給他了。他要丈量你的身體尺寸。\n\n沒錯，<race>，我們要把你裝扮成敵人的模樣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28428] = {title = "完美的偽裝", objective = "從賽拉隆‧恐針在鑿柄的裁縫桌上取得適當數量的補給品。", description = "根據你的體重、身形和大小，我們會把你裝扮成一個獸人。他們的軍隊大多由獸人組成，所以你可以輕易地混進去。\n\n你懂得裁縫嗎?不懂的話，把這當做你的第一堂課吧。我的工作檯就在那裡，上面有所有必要的工具。\n\n把你認為必要的東西全拿到這裡。賽拉隆會馬上幫你搞定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28431] = {title = "完美的偽裝", objective = "從賽拉隆‧恐針在鑿柄的裁縫桌上取得適當數量的補給品。", description = "根據你的體重、身形和大小，我們會把你裝扮成一個食人妖。燃棘食人妖經常和黑石獸人合作，所以你可以輕易地混進去。\n\n你懂得裁縫嗎?不懂的話，把這當做你的第一堂課吧。我的工作檯就在那裡，上面有所有必要的工具。\n\n把你認為必要的東西全拿到這裡。賽拉隆會馬上幫你搞定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28432] = {title = "進入黑齒小屋", objective = "到燃燒平原的黑齒小屋和軍需官卡歐辛談話。\n\n已提供物品：\n", description = "臥底工作本來就要裝腔作勢。你就裝一副本來就是那裡人的樣子，一切都會順利的。\n\n你在黑齒小屋的接應人是個叫做軍需官卡歐辛的獸人。他並不知道你是個臥底，所以保持冷靜。\n\n不管卡歐辛要你做什麼，聽他吩咐。\n\n<伊崔格在你掌中放了個小型機械裝置。>\n\n把這裝置放在耳朵裡。我會和你保持聯絡，給予你特殊指示。\n\n祝你好運，士兵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28433] = {title = "大兵任務", objective = "用力擦亮7雙黑石長靴。", description = "呸!你很走運，我現在正缺人手。否則你一整個禮拜都會嚐到我的鞭子，<小子/小女孩>。\n\n有人得去把軍官和高階士兵的鞋子擦亮。他們都把鞋子放在帳篷外面。\n\n我要在那些鞋子上看到我的倒影，大兵!快去工作!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28434] = {title = "戰術削減", objective = "在灰燼之柱的頂端找到巫毒師提曼，在座狼棚找到座狼女仕歐桑娜，在熔岩池附近找到戈洛普，對他們使用鋒銳蠍刺。", description = "<你的耳裡響起嗡嗡的聲音。>\n\n<name>？我是伊崔格。\n\n我們剛收到了關於你下一個任務的最後一份情報。現在有三個目標需要你去拿下。第一個是巫毒師提曼，你可以在灰燼之柱的頂端找到他。座狼女仕歐桑娜則在座狼棚裡面。最後，你可以在南方的熔岩池附近找到戈洛普。\n\n你可以在你的隨身行囊中找到鋒銳蠍刺。在正確的時機對這些目標使用蠍刺。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28435] = {title = "科多獸呼喚者的號角", objective = "使用呼喚者號角召喚7隻黑石作戰科多獸回到營地。如果有科多獸不願聽命，攻擊牠直到牠屈服。", description = "好吧，我有一些確切、合理且重要的工作要交給你。我們要從放牧地將科多獸召來南方。索伊佐格將軍說我們很快就要遷徙至赤脊山，我可不會留下我的科多獸不管。\n\n在科多獸旁使用這個號角。聽到這聲音，牠就會回到營地。\n\n你要小心。有時候科多獸會有點執拗，所以你可能需要粗暴一點，牠們才會聽你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28436] = {title = "將號角佔為己有", objective = "將呼喚者號角帶到燃燒平原的鑿柄交給伊崔格。", description = "<name>，我是伊崔格。我要你留著那個號角。我確信我們可以即時想出在這項計畫中運用號角的方式。\n\n我很想知道關於卡歐辛所說攻擊赤脊山的事。我們知道另一波攻擊行動正迫在眉睫，但我們的時程表已經落後好幾天了。\n\n帶著號角回來找我。我們會在鑿柄這裡討論。不要毀掉你的偽裝。你還沒完成臥底的工作。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "大草原護腿臨時胸甲機緣頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28437] = {title = "索伊佐格將軍", objective = "和索伊佐格將軍談談。", description = "看來卡歐辛比我預期的還要更能幹，不過我們已經用不著他了。是讓你去和將軍談談的時候了。我想你準備好了。\n\n索伊佐格將軍是運籌燃燒平原地面軍隊的「三巨頭」之一。他就在西北邊的黑石要塞中執行這項工作。穿上你的偽裝，去和他談談。看看你能否贏得他的信任。我會和你保持聯繫，以確保我們需要任何協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28438] = {title = "岩漿試煉", objective = "和沃泰‧史皮宋克談談，並要他釋放熔岩領主寇羅布。在戰鬥中擊敗熔岩領主寇羅布。", description = "我想我會善加利用目前的情勢。這些哥布林傭兵帶了這個巨大的火元素到我的要塞作為雇用他們的「謝禮」。我在燃燒平原要這些火元素幹嘛？這就像是把沙子拿到海灘上一樣。\n\n如果你想找工作，就證明你的實力。去和哥布林談談，然後挑戰他的火元素。勝利者才能贏得我的敬重，以及我的時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "熔岩領主披風可悲手套角鬥護腕索伊佐格的指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28439] = {title = "軍紀如鐵", objective = "在榮譽原野的20名士兵身上使用黑石戒律鬥棍。如果其中一名士兵發現了你的偽裝，在他有機會揭發你之前將他毆打至死。", description = "我一直在找像你這樣優秀、堅強的士兵。我需要有人幫我維持部隊的秩序。\n\n在堡壘外面，獸人、巨魔和食人妖們準備著對赤脊山的襲擊。我的士官正在負責管理，但我希望你能去協助他們。\n\n帶著這根棍子，整頓一下我的士兵。我不在乎他們是破壞規矩了還是乖乖站在隊伍裡，我要他們挨揍。我要他們精神專注、經得起磨練，而且服從。\n\n去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28440] = {title = "權力濫用", objective = "用黑石戒律鬥棍殺死5名黑石士官。在他們有機會揭發你之前迅速擊敗他們。", description = "<name>？我是伊崔格。\n\n聽起來你贏得索伊佐格將軍的信任，讓他將維持軍紀的工作交給了你。這可真是幸運。\n\n我們需要你把他們的士官處理掉。你會在榮譽原野的黑石要塞外面找到他們。將棍棒招呼在他們身上，用個幾次直到他們死掉。你得動作快點，因為若他們理解到你不是他們的一員，他們就能揭發你。快速而兇狠地出擊吧，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28441] = {title = "今天破壞夠了", objective = "到鑿柄找伊崔格。", description = "我們對索伊佐格或黑石的陸軍沒有進一步的戰略計畫了。我們得開始下一階段的計畫。\n\n完成在要塞的工作後，回到鑿柄來找我和我兒子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "計謀指環庫比特的匕首備戰腰帶黑石薩滿的手套破舊的銀白十字軍胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28442] = {title = "烈焰峰", objective = "到燃燒平原的烈焰峰找基布雷爾報告。", description = "我們在鑿柄的工作完成了，這大都要感謝你。我們現在要前往東北方到烈焰峰。\n\n烈焰峰就位於越過索瑞森廢墟的峭壁之中。聽起來那地方非常適合作為我們計畫最終階段的指揮基地。\n\n當然，阿利歐克會在路上與你會合的，我也是。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28443] = {title = "黑灰", objective = "取得9堆黑曜石灰燼。", description = "在我們打倒黑石部隊的殘兵之前，我需要你去做點採集工作。既然要做，就要做得正確，所以我們得好好準備。\n\n我需要灰，<name>。不是隨便的灰...是漫遊在西北方平原上的巨型黑曜石元素的灰。那東西是極深、極深的黑色，我們可以用在下一次的偽裝中。\n\n別擔心，你已經有偽裝了。這東西是給另一個人...嗯或者說另一個...東西的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28444] = {title = "惡魔潛伏", objective = "取得18個倒下的小鬼。", description = "南邊附近的熔岩場是火焰小鬼的溫床，長久以來，這些火焰惡魔漫遊在平原之上。照黑石部隊目前的狀況來看，如果我們小心點，或許能讓這種火焰小鬼潛進敵人後方，製造一些災害。\n\n給我帶幾個火焰小鬼的屍體來。作為惡魔，他們很容易就可以被復活，然後我們就能按照自己的目的利用他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28445] = {title = "一堆美味座狼", objective = "利用座狼鋸從被殺死的巨型灰燼座狼身上取得40份座狼厚肉排。", description = "我們需要新鮮的肉，所以你得去獵殺座狼。你該以平原這一帶的座狼為目標。\n\n<伊崔格取出一柄大刀，然後交給你。>\n\n去獵殺巨型灰燼座狼吧。一旦殺死牠們，用這柄刀鋸取走牠們身上最好部位的肉。你會發現平原四處都是這些座狼，最近的一群則位於這裡的東南邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28446] = {title = "血腥之旅", objective = "殺死25個黑色龍裔或黑色龍人。", description = "我的腿又有點發癢了。你有興趣稍微旅行一下嗎，<name>？\n\n我們正準備前往巨槌石一帶。我想要在成行之前先調查一下黑石軍隊的狀況，或許還能順路殺掉他們一些。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28447] = {title = "龍之先鋒", objective = "殺死米尼歐斯、幼龍馴獸師阿庫米、『燒灼者』泰洛瑪斯和塔格納‧破喉。", description = "黑石獸人不是獨自來的。你已經看過火腹巨魔和燃棘食人妖陪在他們身邊。不幸的是，他們還找來黑龍群和他們沆瀣一氣。\n\n獸人和龍群已經派出一些勇士來駐守在集結點。那些地點豎立有插著巨龍頭骨的尖柱做記號。你和我得找到這些集結點，在戰爭開始前殲滅這群先鋒部隊。\n\n準備好了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28448] = {title = "與龍有約", objective = "將獲救的龍寶寶送去燃燒平原的滑石給阿克萊德。", description = "當我們在巨槌石附近環繞時，還有一站是我們必須過去的。\n\n記得你從幼龍丘陵解放出來的那些幼龍嗎？我一直照顧著他們，而我們得將他們送去某個比我們更懂得怎麼照顧的人。這個人就待在巨槌石東北邊的滑石。\n\n他的名字叫阿克萊德，他或許是贏得接下來戰役的關鍵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28449] = {title = "調兵遣將", objective = "到燃燒平原的烈焰峰找伊崔格。", description = "<你耳朵裡傳來嗡嗡的聲響。>\n\n<name>。聽起來你和阿利歐克完成了你們的任務。我也完成了我的。\n\n回去摩根的崗哨吧。我已經準備了幾個包裹要交給那三巨頭:索伊佐格、尼洛拉克和希倫。你已經遇過索伊佐格將軍了。這就是你和其他兩員見面的機會。\n\n那是指，在你殺掉他們之前。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "兵卒護腕烈焰峰護腕覆滅足音瑟銀兄弟會臥底胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][28450] = {title = "給索伊佐格的快遞", objective = "使用你的黑石偽裝，然後將醃肉排口味調味冰沙帶去燃燒平原的火腹熔爐給索伊佐格將軍。如果你需要一套新的黑石偽裝，去和伊崔格談話。", description = "索伊佐格將軍就在火腹熔爐的那群巨魔中間，那裡是巨槌石西端之上的一個洞穴。我要你將這個送去給他和巨魔們。\n\n在這包裹之中，你會找到你之前取得的座狼肉片，經過我們從風暴祭壇取來的魔化調味冰砂醃漬。\n\n如果我是你，我會盡量避免吃它。\n\n將它帶去給索伊佐格將軍。他會確保自己的士兵都填飽肚子，而幸運的話，他自己也會吃掉一些。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28451] = {title = "給尼洛拉克的快遞", objective = "使用你的黑石偽裝，然後潛入顱骨區，說服龍領主尼洛拉克收下你那一箱睡著的小鬼。如果你需要一套新的黑石偽裝，去和伊崔格談話。", description = "黑石部族的術士經常在顱骨區練習他們的魔法，那地方就在巨槌石的東面。他們的領導者希倫正在其他地方忙碌，所以那洞穴目前正受到另一名三巨頭「龍領主尼洛拉克」的掌管。尼洛拉克專精於龍，而非死靈法術。\n\n我已經將沉睡之砂使用在你抓補來的火焰小鬼身上。試著說服尼洛拉克他們是術士的小鬼而非火焰小鬼。當這些傢伙醒來時，他們不會開心的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28452] = {title = "給希倫的快遞", objective = "使用你的黑石偽裝，然後將清澈玻璃寶珠帶去燃燒平原的巨槌石頂上交給高階術士希倫。如果你需要一套新的黑石偽裝，去和伊崔格談話。", description = "情報指出，高階術士希倫，也就是三巨頭中最後的成員，就在巨槌石頂上的洞穴中準備他的重要時刻。\n\n他正在等待一件貨物，名叫統御寶珠，好施行一項強力的召喚儀式。我要你將這交給他:\n\n<伊崔格給了你一顆玻璃球。>\n\n這是你從風暴祭壇取出來的清澈玻璃寶珠。它沒有一絲力量。將它交給希倫，然後偷偷祈禱他不會發現。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28453] = {title = "子彈上膛", objective = "到燃燒平原的烈焰峰找伊崔格回報。", description = "<name>，請回答。你聽得到我嗎？\n\n戰爭一觸即發。我希望你把所有包裹都送到了。\n\n我需要你回來烈焰峰。立刻。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "光透指環偽術士軟靴靈活滑動手套惡意言行肩甲行為失當護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][28454] = {title = "襲擊巨槌石", objective = "殺死200名黑石入侵者。如果你失去了交通工具，使用呼喚者號角來再次召喚。", description = "結束了，<name>。這是個悲傷的日子...但在這個日子，黑石獸人將學到沉重的一課。在這個日子，我們的計畫開花結果。\n\n跟著我出發。我們要去跟阿克萊德說話，他欠我們一次幫忙，現在該償還了。我們將在這場對赤脊山的入侵開始之前阻止它!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28455] = {title = "混沌中的榮耀", objective = "殺了索伊佐格將軍、龍領主尼洛拉克和高階術士希倫。", description = "你和我兒子要回去那座山。有三名獸人從攻擊中存活了下來，在他們死去之前，我們不會停下來休息。\n\n沒錯，我是在講那三巨頭。\n\n索伊佐格將軍爬回了火腹熔爐，龍領主尼洛拉克蜷縮在山峰上的洞穴。希倫就在顱骨區的後邊，和他的術士同伴陰謀計畫著。\n\n去創下你的功勳，<name>。一勞永逸地推翻那些被腐化的黑石雜碎。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28456] = {title = "戰利品", objective = "到燃燒平原的烈焰峰檢視一箱剩下的補給品。", description = "儘管黑石獸人仍然群聚在他們的尖塔裡，我想他們短期之內無法再對赤脊山的無辜人們有任何計畫了。這是你和基沙恩的功勞。\n\n我得說我們還真是徹底利用了燃燒平原的各種資源，我們所收集的那些術士補給品確實好用，用來掩蔽我們那隻龍的黑曜石灰燼也是。\n\n然而，我們還剩了一些東西。請在你離開平原之前盡情地挑選。您會收到：\n\n", progress = nil, completion = nil, rewards = "黑曜石斑點斗篷希倫的徽記灰燼座狼長靴鋒銳蠍刺腰帶魔像粉碎者之握您會收到：\n\n破裂的支配寶珠"}
MultiLanguageQuestData['tw'][28457] = {title = "危險的聯盟", objective = "到黑石深淵的西部兵營殺死6個火焰衛士摧毀者，並從安格弗將軍身上找出將軍的攻擊計畫。", description = "破碎之手部族相信黑鐵矮人和暮光之錘正在合作。有證據顯示，他們正在黑石山裡面計畫一個聯合攻擊行動。我們不能放任這樣強大的軍隊離開黑石山。\n\n你必須進入黑石深淵，從西部軍營的安格弗將軍手中取得暮光之錘攻擊計畫。消滅暮光之錘用來增強部隊的那些元素。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "群集面甲群集護盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28458] = {title = "火占師的魔典", objective = "到黑石深淵的索瑞森神殿去，殺死6個暮光使者，並從火占師羅格雷恩身上找出羅格雷恩的魔典。", description = "黑鐵軍團與他們的暮光之錘同盟，在黑石山中不停地壯大自身的武力。火占師羅格雷恩是暮光之錘代表團中一個力量強大、有權有勢的法師。如果我們能得到他的魔典，我就可以對抗暮光之錘的咒語和詛咒。\n\n你必須深入黑石深淵，找出索瑞森神殿的所在位置，並取得魔典。別憐憫羅格雷恩與他的暮光走狗。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n秘法之路兜帽"}
MultiLanguageQuestData['tw'][28459] = {title = "禁錮之石", objective = "到黑石深淵取得6個元素束縛之石。你可以在影爐城、住宅區、索瑞森神殿、西部兵營和東部兵營找到這些石頭。", description = "破碎之手部族發現到在黑石深淵的暮光之錘和黑鐵矮人之間的合作關係不斷加深。我們有個襲擊敵人並強化自己的機會，<name>。\n\n暮光之錘的追隨者在影爐城、住宅區、索瑞森神殿、西部兵營和東部兵營四處放了許多的元素束縛之石。找到並奪取這些石頭!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n左手之道角帽"}
MultiLanguageQuestData['tw'][28460] = {title = "冬泉熊怪的威脅", objective = "在冰火溫泉附近殺死15隻任何種類的冬泉熊怪。", description = "我是來冬泉谷調查冰火溫泉的。我注意到這裡的泉水似乎有些...古怪。我暫時還沒有找出問題的根源，而且老實說，最近那些冬泉熊怪讓我遇到一些麻煩。\n\n他們跟我一樣被吸引到了泉水附近。這些熊怪對水源的保護意識極強，不讓我接近北邊那兩處較大的溫泉。\n\n我想繼續進行研究，你能幫幫我嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "多諾瓦的毛茸茸長袍溫泉便鞋雪山裹腿寒水腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][28461] = {title = "魔像領主的創作", objective = "到黑石深淵的製造廠去，從魔像身上取得5個元素模組，並找出元素魔像藍圖。", description = "破碎之手部族在黑石深淵中發現了一些不大妙的資訊。消息顯示暮光之錘正和黑鐵軍團的工程師阿格曼奇一起合作，打造以元素為動力的戰爭魔像。這些魔像會成為我們敵軍的極大助力。\n\n阻止這件事發生是你的責任。到黑石深淵裡去找出製造廠，取得他製造那些魔像的藍圖，並找出他用來作為魔像動力的元素模組。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n偉大獵人頭盔"}
MultiLanguageQuestData['tw'][28462] = {title = "冬泉火酒", objective = "将空的火酒瓶交给冬泉谷的多诺瓦·雪山。", description = "你从冬泉熊怪那儿拣来的这只小瓶子是空的，但是里面有一些奇怪的绿色液体，它甚至发出了微微的光芒。\n\n这会是什么重要的东西吗？\n\n多诺瓦·雪山可能会告诉你更多的信息，她在冬泉谷的温泉附近有个营地。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28463] = {title = "黑鐵軍團", objective = "使用急性毒藥在黑石深淵的西部或東部兵營的6袋穀物口糧裡面下毒。", description = "作為破碎之手的一員，你知道我們的工作是監視部落的敵人。我們發現黑鐵矮人和他們的新盟友「暮光之錘」正在準備發動攻擊。\n\n我要派你過去，在黑鐵的軍隊進發前幫忙處理這項威脅。拿著這瓶毒藥，將它摻入黑石深淵的儲備糧食。\n\n黑鐵矮人大多數的糧食都存放在黑石深淵的東部和西部兵營。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破碎之手面甲"}
MultiLanguageQuestData['tw'][28464] = {title = "墮落熊怪", objective = "在北邊的冬泉熊怪營地尋找寒水大鍋。", description = "冬泉熊怪的威脅性一定有個源頭。只要在能力範圍內，我想更深入了解這件事!\n\n我看過北邊營地的熊怪在大鍋裡熬著某些東西。他們看起來對那鍋東西很保護...如果他們在熬煮的東西跟這件事有關，我必須親自加以調查。\n\n找看看那只大鍋子還在不在原地，並將裡面的東西帶回來給我!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28465] = {title = "炎魔的奴隸", objective = "使用自由圖騰解放黑石深淵的6位火焰衛士，火焰衛士摧毀者，或熾熱火焰衛士。", description = "在黑石深淵的大廳裡，邪教暮光之錘和黑鐵矮人正在召集軍隊。而他們軍團的主力，是大量受到束約、必須服侍炎魔拉格納羅斯的火元素。\n\n如果我們有辦法將這些元素從束約中解放，就能同時削弱敵人的力量，並且讓元素們獲得自由。拿著這個圖騰，對被制伏住的火焰衛士使用它。這能讓它們的靈體從束縛中解脫，恢復它們正常的狀態。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "演講者頭罩演講者面具您會收到：\n\n"}
MultiLanguageQuestData['tw'][28466] = {title = "黑暗的武器", objective = "從黑石深淵的鐵怒矮人那裡取得5件元素灌注武器，然後在影爐城的黑鐵砧上方將武器銷燬。", description = "黑石深淵一直是我們敵人的家園，但現在破碎之手部族發現黑鐵矮人和暮光之錘加強了合作關係。黑鐵矮人利用教團的知識，以元素力量強化了他們的武器。他們用這些恐怖的新武器強化了鐵怒軍團。\n\n我要你進入黑石深淵，從鐵怒矮人身上收集這些武器，然後在影爐城中心的黑鐵砧上擊碎它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "日行者頭盔日行者面甲日行者護盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28467] = {title = "神秘的粘液", objective = "向多諾瓦‧雪山回報你的發現。", description = "大鍋子裡的綠色事物泛冒惡臭而且十分黏稠。不管它是什麼，看起來都不像好玩意。\n\n若冬泉熊怪有使用它，這是否代表他們很快也會像死木部落一樣遭到腐化?\n\n最好向多諾瓦回報你所找到的資訊，並附上一些大鍋子裡的液體樣本。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28468] = {title = "oxic Horrors", objective = "Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.", description = "I've studied the sample you returned with, and while I can't say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison.\n\nI believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors.\n\nCollect a few samples for me to compare, but be careful -- it's very dangerous there!完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28469] = {title = "冬泉信差", objective = "找到並擊敗冬泉信差後從他身上取得冬泉木箱。", description = "非常有趣，<name>...\n\n將這有毒性的物品與溫泉的水結合時，毒性會消失，飲用它時只會有暫時性的效果。這應該是為什麼冬泉部落這麼積極地守護溫泉泉水─它們需要淨化火水。\n\n我們需要停止這件事，中斷冬泉部落和死木部落的聯繫。有一群信差往來於他們的村落和費伍德森林之間。找到並擊敗他們，然後竊取他們的運送物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28470] = {title = "冬泉酋長", objective = "殺死冬泉酋長。", description = "冬泉熊怪原本並不是很具有威脅性的部落，他們舉止的轉變讓我想到，他們一定是受到酋長的指示。我們應該無法改變已造成的破壞了，但如果將酋長殺死，他們也許不會繼續惡化下去。\n\n再次向東前進，越過你找到大鍋的地方。冬泉酋長就在那裡，在木喉崗哨的最東邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "熊怪皮毛護腕柔伊公主的舊狩獵手套伏擊臂甲突來變化魔杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][28471] = {title = "最後的線索", objective = "將潦草的日誌帶到冬泉谷給多諾瓦‧雪山。", description = "你在冬泉酋長身上找到的日誌看起來很厚，但讀了幾頁後，你發現自己看不懂上面的文字。上面的字跡既潦草又結構不良，你也不確定到底有沒有人可以看懂。\n\n但或許多諾瓦可以告訴你上面記載甚麼...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28472] = {title = "熊怪酋長的話", objective = "將潦草的日誌帶到凱斯利爾給科雷克‧天衛。", description = "冬泉部落對我來說已經沒有威脅了，若你還想追查是甚麼牽引著熊怪製造並飲用這奇異的火水，我想你最好去找科雷克‧天衛。\n\n這位德魯伊曾經用翡翠議會淨化過費伍德森林，並從那時起就來到附近的遺跡做研究。\n\n你可以在東邊的凱斯利爾湖找到他，他最近花很多時間在那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "大酋長之力牛頭人酋長之能您會收到：\n\n"}
MultiLanguageQuestData['tw'][28473] = {title = "黑暗的武器", objective = "從黑石深淵的鐵怒矮人那裡取得5件元素灌注武器，然後在影爐城的黑鐵砧上將武器銷燬。", description = "黑石深淵一直是我們敵人的家園，但現在破碎之手部族發現黑鐵矮人和暮光之錘加強了合作關係。黑鐵矮人利用教團傳授的知識，以元素力量強化了他們的武器。他們用這些恐怖的新武器強化了鐵怒軍團。\n\n我要你進入黑石深淵，從鐵怒矮人身上收集這些武器，然後在影爐城中心的黑鐵砧上擊碎它們。您會收到：\n\n", progress = nil, completion = nil, rewards = "秩序頭盔秩序面甲秩序護盔您會收到：\n\n血騎士外袍"}
MultiLanguageQuestData['tw'][28474] = {title = "暮光的陰謀", objective = "到黑石深淵的住宅區利用白熾火炬燒毀8份暮光綱領。", description = "暮光之錘教團的影響力在黑石深淵中日益增長。他們和黑鐵矮人結成聯盟，並試圖說服他們向山脈之外的地區出擊。\n\n我們必須摧毀暮光之錘鼓吹動亂的手段。他們對黑鐵矮人的影響必須縮減到最小。\n\n我要你進入黑石深淵的住宅區，用這個火把燒毀暮光之錘教團分發到那裡的書本。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n被遺忘者信念之冠"}
MultiLanguageQuestData['tw'][28475] = {title = "暮光的陰謀", objective = "到黑石深淵的住宅區利用白熾火炬燒毀8份暮光綱領。", description = "暮光之錘教團的影響力在黑石深淵中日益增長。他們和黑鐵矮人結成聯盟，並試圖說服他們向山脈之外的地區出擊。\n\n我們必須摧毀暮光之錘鼓吹動亂的手段。他們對黑鐵矮人的影響必須縮減到最小。\n\n我要你進入黑石深淵的住宅區，用這個火把燒毀暮光之錘教團分發到那裡的書本。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n追日者之冠"}
MultiLanguageQuestData['tw'][28476] = {title = "暮光的陰謀", objective = "到黑石深淵的住宅區利用白熾火炬燒毀8份暮光綱領。", description = "暮光之錘教團的影響力在黑石深淵中日益增長。他們和黑鐵矮人結成聯盟，並試圖說服他們向山脈之外的地區出擊。\n\n我們必須摧毀暮光之錘鼓吹動亂的手段。他們對黑鐵矮人的影響必須縮減到最小。\n\n我要你進入黑石深淵的住宅區，用這個火把燒毀暮光之錘教團分發到那裡的書本。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大地之母之冠"}
MultiLanguageQuestData['tw'][28477] = {title = "暮光的陰謀", objective = "到黑石深淵的住宅區利用白熾火炬燒毀8份暮光綱領。", description = "暮光之錘教團的影響力在黑石深淵中日益增長。他們和黑鐵矮人結成聯盟，並試圖說服他們向山脈之外的地區出擊。\n\n我們必須摧毀暮光之錘鼓吹動亂的手段。他們對黑鐵矮人的影響必須縮減到最小。\n\n我要你進入黑石深淵的住宅區，用這個火把燒毀暮光之錘教團分發到那裡的書本。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗影行者之冠"}
MultiLanguageQuestData['tw'][28478] = {title = "暮光的陰謀", objective = "到黑石深淵的住宅區利用白熾火炬燒毀8份暮光綱領。", description = "暮光之錘教團的影響力在黑石深淵中日益增長。他們和黑鐵矮人結成聯盟，並試圖說服他們向山脈之外的地區出擊。\n\n我們必須摧毀暮光之錘鼓吹動亂的手段。他們對黑鐵矮人的影響必須縮減到最小。\n\n我要你進入黑石深淵的住宅區，用這個火把燒毀暮光之錘教團分發到那裡的書本。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n金錢崇拜之冠"}
MultiLanguageQuestData['tw'][28479] = {title = "凱斯利爾廢墟", objective = "到冬泉谷的凱斯利爾湖去和卡多雷之靈交談。", description = "這個湖裡，有個精靈貴族偷來的辛瑪洛水晶。這水晶是一個力量強大的神器，可以用狂暴且無法預知的方式扭轉秘法...但它只能運用在有價值的地方，否則將會帶來厄運。\n\n這些靈魂世世代代都在這裡遊蕩，每個靈魂都受到辛瑪洛的束縛。有些能說話的會敘述他們的命運。\n\n如果你想知道辛瑪洛的命運，就去找湖心的那個靈魂...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28480] = {title = "暗影中尉", objective = "消滅蠍子王納克海爾和高等貴族瑟克梅特。", description = "蘭姆卡韓的軍隊要被奈斐賽特的不朽守護者給殲滅了。\n\n擊敗它們的唯一方法，是殺了奈斐賽特的黑暗法老特卡恩。\n\n然而，在我們行動之前，我們得先處理他的副官。\n\n深入戰線後側，殺了蠍子王納克海爾和高等貴族瑟克梅特。只有那樣我們才能迎戰黑暗法老。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "甲蟲鑲飾之弩瑟克梅特的徽印您會收到：\n\n"}
MultiLanguageQuestData['tw'][28481] = {title = "Troubled Spirits of Kel'Theril", objective = "Use Gormir's Pick to find the four Highborne Relic Fragments.", description = "The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.\n\nIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28482] = {title = "蘇拉的禮物", objective = "到朝聖者絕壁和哈里遜‧瓊斯談話。", description = "瓊仔告訴我你們兩個要上山去。\n\n嗯，敵人的那些部隊就像爬滿在肉塊上的螞蟻一樣，在山上到處都是，你們是走不遠的。\n\n還好，我有些朋友弄到了一些敵人的裝備，應該能讓你們的旅途輕鬆點。\n\n前往北邊的山脊上，裝備就擺在路上等著你們。\n\n祝你們兩個好運!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28483] = {title = "血染敵軍", objective = "取得10個奈斐賽特徽記。", description = "我不會騙你，<name>。我們將面對一個極大的挑戰。\n\n進入奈斐賽特城的敵軍陣線後，我要你從你所擊敗的奈斐賽特人渣身上取回徽記。\n\n知道你給了敵方致命的一擊，我們的軍隊會受到很大的鼓舞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28484] = {title = "問題核心", objective = "收集12顆跳動的雪人心臟。", description = "那些魔導師無所事事太久了，而無所事事的魔導師經常造成我們計畫的漏洞。我這次受命收集不同種類的野獸內臟，據說是要用來強化某種控制魔杖。我已經累得沒有力氣出去獵殺野獸了，尤其是那些雪人！\n\n如果我給你一些報酬，也許你可以幫我去完成這件工作？我只需要你到西邊的雪人洞穴殺死一些雪人。從他們的胸腔把還在跳動的心臟摘下來，然後帶回來這裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "貝瓦里爾的臂環柔軟雪人護腿故事講述護腕貝瓦里爾鎖甲護腿您會收到：\n\n窒息雪人心臟"}
MultiLanguageQuestData['tw'][28485] = {title = "『雪人之王』耶堤穆斯", objective = "取得耶堤穆斯扭曲的角。", description = "多年以來，從來沒有人去管束這個區域的山嶺雪人。我們放任那些雪人威脅的這種態度是不對的!那些雪人的頭領，耶堤穆斯，不論在體型或力量上都不是我們守衛所能應付的。我們擔心他的食慾會牽引他來到靠近塔倫米爾的地方，然後把我們全都吃了。\n\n我要你召集一群適當的冒險者，合力殺死這隻野獸。他就在西邊的鄉間遊蕩。\n\n把他的一隻角帶回來給我，我將好好的獎賞你一頓。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "耶堤穆斯巨錘塔倫米爾寶珠放任食慾盾牌您會收到：\n\n"}
MultiLanguageQuestData['tw'][28486] = {title = "薩赫特的先鋒", objective = "護送蘭姆卡韓遊俠隊長上高地。", description = "奈斐賽特城防守得太穩固了。但是入城的山間通道就並非如此。\n\n我和遊俠隊長談過，他願意帶幾個人去攻佔具有戰略性的山頂。\n\n只有一次機會，<name>。他同意了，但你要當他們的攻擊先鋒。\n\n那必須是個小型隊伍，否則會被敵人太早注意到，不過相信我...蘭姆卡韓遊俠也很強悍。有你並肩作戰我們一定會勝利。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28487] = {title = "亨伯特的個人問題", objective = "取回亨伯特的長劍、亨伯特的頭盔、還有亨伯特的束褲。", description = "這真是難為情。該從哪裡開始呢？\n\n好吧，你瞧，梅里薩拉派我去探查西邊不遠處山洞裡的雪人威脅。由於時間匆促，我的護甲對我造成了不少負擔。我脫下了我的裝備決定去溜達溜達。是的，我，呃，去散了個步。不論如何，當我回來時我發現我的裝備被偷走了！是那些雪人。我很確定。他們帶走了我的束褲，長劍還有頭盔，然後跑回了他們的山洞。幫我把它們找回來，我會好好酬謝你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28488] = {title = "表面之下", objective = "取得巨大的紅寶石晶簇。", description = "在我們到達不了的破碎深淵底部，藏著許多珍貴的寶石，而在這些寶石之間有著巨大的紅寶石晶簇，裡面含有驚人的能量。\n\n這種東西可不容易取得，它們都被嚴密守護著。不過你可以，你是如此堅強且勇敢。我想這是你能做的事。\n\n到破碎深淵裡面，找到被岩石硬生生截斷的隧道盡頭。你可以在那些通道裡找到這些晶簇。如果你取得其中一個，帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28489] = {title = "鹿肉堡", objective = "取得8份鹿肉。", description = "有聽過鹿肉堡嗎？我也沒聽過。不過顯然它們很美味。我並不是個饕客，不過我是個商人。如果我的顧客想要鹿肉堡的話，我有什麼立場好爭論的呢？你也許會問，「這關我什麼事？」讓我告訴你吧，<class>，我需要鹿肉！幫我從希爾斯布萊德的丘陵雄鹿的身上弄來鹿肉，我就會付你一筆錢。聽起來不錯吧，不是嗎？\n\n出發吧！西邊是最多雄鹿聚集的地方。您會收到：\n\n", progress = nil, completion = nil, rewards = "鹿肉堡分割刃您會收到：\n\n鹿肉堡"}
MultiLanguageQuestData['tw'][28490] = {title = "英雄的召喚：黑海岸！", objective = "到黑海岸的洛丹諾向女牧師丹泰莉雅回報。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往黑海岸的洛丹諾向女牧師丹泰莉雅報到。\n\n洛丹諾的人民需要你的協助，以照料在奧伯丁毀滅後逃出的生還者，同時守護城鎮不受暮光之錘的侵襲。到達納蘇斯外的魯瑟蘭村和角鷹獸管理員維斯派塔斯交談，他會幫你安排前往黑海岸的飛行坐騎。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28491] = {title = "不是螢火蟲，是火蠅", objective = "抓到7隻火蠅。", description = "跟我一起住到烈焰峰的居民似乎都因為某種原因離開了。我猜是燃燒平原太無趣了。\n\n不過，我可不一樣。我一直都能找到新的理由留下來，而最近讓的原因就是火蠅的出現。\n\n牠們白天出現在熔岩附近。到了晚上，你幾乎可以在任何地方發現牠們。\n\n如果你幫我抓一些這種蟲子，我會付給你相對的報償的。您會收到：\n\n", progress = nil, completion = nil, rewards = "撫愛手套火蠅肩甲熔岩長靴您會收到：\n\n小火蠅"}
MultiLanguageQuestData['tw'][28492] = {title = "英雄的召喚：梣谷！", objective = "到梣谷西北隅的奧蘭迪爾居所向哨兵席雅拉報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往梣谷西北隅的奧蘭迪爾居所向哨兵席雅拉報到。\n\n絕不能放任部落對梣谷進行侵略！梣谷需要你的幫助來擊退入侵者及修復神聖的森林。往南穿越黑海岸的暮光谷來抵達梣谷的森林。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28493] = {title = "大酋長的命令：梣谷！", objective = "到北貧瘠之地與梣谷邊境之間的莫爾杉壁壘向卡德拉克報到。", description = "所有身強體壯的部落成員，都在此受命前往北貧瘠之地與梣谷邊境之間的莫爾杉壁壘向卡德拉克報到。協助我們將夜精靈趕出森林的行動，為我們的人民取得資源！\n\n要抵達莫爾杉壁壘，在北貧瘠之地順著十字路口北方的黃金之路前進。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28494] = {title = "大酋長的命令：北貧瘠之地！", objective = "到北貧瘠之地的前沿哨所向卡加爾‧戰痕報到。", description = "所有身強體壯的部落成員，都必須聽命前往北貧瘠之地的前沿哨所，向卡加爾‧戰痕報到。\n\n那裡需要你的幫助，以確保北貧瘠之地不受野豬人和半人馬的侵害。\n\n要抵達前沿哨所，往西穿過杜洛塔的怒水河氾濫平原，然後過橋進入北貧瘠之地。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28495] = {title = "一戰的機會", objective = "拯救10隻丘陵幼鹿。", description = "讚美聖光!我需要你的幫忙!\n\n在我進入希爾斯布萊德的路上我注意倒有幾個可愛的小鹿家庭。正當我拍打著其中一隻可愛的幼鹿時，一隻兇惡的山貓跳出來殺了牠。我逃到了塔倫米爾，並發誓一定要幫助那些丘陵幼鹿。現在，經過多天的修補，我製作了這個丘陵幼鹿拯救器!\n\n帶著我的魔杖到西邊的野外去，用它來增大那些小丘陵幼鹿。等牠們變大之後，就會有能力保護自己了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28496] = {title = "大酋長的命令：艾薩拉！", objective = "到艾薩拉的奧格瑪後門向工人隊長葛拉比特報到。", description = "所有身強體壯的部落成員，都必須聽命前往艾薩拉的奧格瑪後門向阿格圖‧血拳報到。\n\n協助我們驅逐進逼的聯盟部隊，為了部落的榮光，堅守艾薩拉！\n\n穿過奧格瑪的北門即可抵達位於艾薩拉的奧格瑪後門。\n\n你的使命正在召喚！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28497] = {title = "天火", objective = "搭上沒收的火砲，消滅100個舒諾茲裝甲兵。", description = "蘇拉沒開玩笑。那山丘上到處都是軍隊!\n\n上去幫我把目標指出來。\n\n每一擊都要命中，<name>!我們一定要上到那裡去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "臟器胸鎧火藥燃燒肩甲沒收的辨識牌您會收到：\n\n"}
MultiLanguageQuestData['tw'][28498] = {title = "納候姆的秘密", objective = "取得8塊阿圖爾西特的記錄碎片。", description = "有個有關納候姆的老故事。故事說到一個叫阿圖爾西特的強大預言者用這座神殿注入太陽的力量，使敵人無法接近珍寶。\n\n大多人都覺得這只是傳說，但是那個力量...現在對我們很有用。\n\n卑鄙的奈斐賽特搜刮了阿圖爾西特的墓地。他們拿走所有具力量的神器，還打碎記載他事蹟的石板。\n\n到東邊的先驅者之墓去找回你發現的所有碎片。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28499] = {title = "懲罰侵入者", objective = "在先驅者之墓消滅10個奈斐賽特入侵者。", description = "我們納候姆的祭司，是先驅者之墓的守護者。\n\n自從奈斐賽特變成他們的新主人之後，他們就轉成了異端邪教。\n\n他們掠奪我們祖先的神聖墓地，搜尋法力強大的神器，並同時摧毀寶貴的聖物。\n\n到這裡東邊的墓地去，懲罰那些盜墓者的罪行，以免他們在奈斐賽特對納候姆發動攻擊時加入他們的同夥。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "蘭姆卡韓典禮之錘墓穴保衛者重肩甲難恕墓穴護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][28500] = {title = "奇瑟密碼", objective = "取得奇瑟密碼。", description = "<薩赫特和他周圍的祭司花了點時間查看石板。>\n\n這裡沒問題的，<name>。阿圖爾西特在神殿裡建造了強大的武器，想使用它的唯一方法是輸入正確密碼。\n\n據說密碼被藏在奇瑟小徑。我們該祈禱奈斐賽特掠奪者還沒把它弄到手。掠奪者領主哈瓦特控制著那個地方，他是敵人之中最心狠手辣的一個。\n\n假如沒有援軍，這武器可能是我們保衛納候姆的唯一希望。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28501] = {title = "納候姆的防禦", objective = "和蘭姆卡韓士官談話並成功防禦納候姆。", description = "敵人來了…並且為數眾多。\n\n我們不需要更多援軍。祈禱我們能阻止奈斐賽特進一步侵襲吧。\n\n要是納候姆淪陷，蘭姆卡韓也會失守。\n\n你準備好後進去和我的士官談談。我會幫你盡全力指揮我們的部隊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28502] = {title = "強盜督軍", objective = "消滅督軍依赫森。", description = "我們的法律要給這些攻擊的始作俑者應得的懲罰。\n\n那夥強盜的頭目是個叫督軍依赫森的傢伙。\n\n你會在沙漠的西邊遠處找到他。絕對要嚴懲他所犯下的罪。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "昆布涅特護脛黑普圖護盔天譴歹徒護腕依赫森恐懼法杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][28503] = {title = "英雄的召喚：千針石林！", objective = "到菲拉斯和千針石林邊境的新薩蘭納爾向凱雷希亞‧獵月報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往菲拉斯和千針石林邊境的新薩蘭納爾向凱雷希亞‧獵月報到。\n\n哨兵們需要你的幫助來抵擋肆虐該地的恐怖圖騰劫掠者。你可以在菲拉斯東部、靠近千針石林邊境的位置找到新薩蘭納爾。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28504] = {title = "大酋長的命令：千針石林！", objective = "到塵泥沼澤南部的泥鏈營地向奈瑟報到。你可以選擇在奧格瑪搭乘朵拉斯的蠍尾獅。", description = "所有身強體壯的部落成員，都在此受命前往泥鏈營地向奈瑟報到。加入部落的軍隊，和掌控該區域的恐怖圖騰的叛徒對抗吧。\n\n奈瑟會提供你直達前線的運輸方式。她將在泥鏈營地的旅店中等你，營地就在塵泥沼澤的南部。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28505] = {title = "安多哈爾之戰", objective = "與戈斯魯姆交談，以飛往西瘟疫之地的安多哈爾。然後在安多哈爾向薩沙理安回報。", description = "我剛剛收到消息， <小夥子/小姑娘>。這消息聽起來有些不妙。\n\n安多哈爾城正陷入被遺忘者、聯盟、還有天譴軍團的三方交戰之中。烏瑞恩王已經決定派出一名死亡騎士帶領突擊行動，不過我確定他用得上他所能獲得的所有幫助。\n\n我不想讓你離開，不過他們指名了要你，<name>。到外面去和戈斯魯姆談談。他會讓你坐上第一隻前往安多哈爾的獅鷲獸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28506] = {title = "雷矛的行進", objective = "觀察雷矛之行進。", description = "你找回來的這些計畫組織成一個有趣的消息，<name>。雷矛開始將部隊從奧特蘭克山谷移進希爾斯布萊德的「四指區域」，已經超過一個月了。他們不知怎麼逃過了我們軍隊的注意，秘密地設置了他們的基地。如果我們沒有取得這些計畫書，他們很可能在幾週之內就行進到我們這裡，殲滅一路上所有的東西。\n\n不過，若是擁有這些計畫書，我們可以將情勢完全反轉。\n\n這就是我們得做的事...", progress = nil, completion = "現在就是行動的時候了。雷矛將被擊潰!", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28507] = {title = "英雄的召喚：塔納利斯！", objective = "到塔納利斯的加基森向凱爾希‧鋼火報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往加基森向凱爾希‧鋼火報到。\n\n聯盟需要你的幫助，來贏得當地貿易巨商的授權，取得位於該地的無價資源。你可以從千針石林的閃耀深淵往南方走，以抵達加基森。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28508] = {title = "安多哈爾之戰", objective = "與凱雷恩‧庫恩交談，以飛往西瘟疫之地的安多哈爾。然後在安多哈爾向寇爾提拉‧亡織者回報。", description = "我剛收到了一份奇怪的公文。真的很奇怪...\n\n安多哈爾城正陷入被遺忘者、聯盟、還有天譴軍團的三方交戰之中。聽起來希瓦娜斯已經決定了如何行動，最有趣的是，她讓死亡騎士寇爾提拉‧亡織者負責指揮。\n\n他們提到了你的名字，<name>。去和蝙蝠管理員凱雷恩‧庫恩交談。他會讓你坐上第一隻前往安多哈爾的蝙蝠。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28509] = {title = "大酋長的命令：塔納利斯！", objective = "到塔納利斯的加基森向梅格斯‧驚懼伐木機報到。你可以選擇在奧格瑪搭乘朵拉斯的蠍尾獅。", description = "所有身強體壯的部落成員，都在此受命前往加基森向梅格斯‧驚懼伐木機報到。幫助部落和污水企業搶先在聯盟之前進駐塔納利斯！\n\n要前往塔納利斯的加基森，你可以從位在千針石林東南方的『菲茲爾與普茲克的高速駁船』往南走直到上岸。或者，你也可以從奧格瑪的朵拉斯飛到那裡。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28510] = {title = "大酋長的命令：菲拉斯！", objective = "到菲拉斯的阿塔亞營地向寇奴‧符文圖騰報到。", description = "所有身強體壯的部落成員，都在此受命前往菲拉斯的阿塔亞營地向寇奴‧符文圖騰報到。幫助部落從聯盟和恐怖圖騰手中奪得那片廣大的森林吧。\n\n你可以從淒涼之地往南走來進入菲拉斯，並抵達阿塔亞營地。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28511] = {title = "英雄的召喚：菲拉斯！", objective = "到菲拉斯的夢旅者之眠向泰拉隆‧風程報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往菲拉斯的夢旅者之眠向泰拉隆‧風程報到。\n\n聯盟需要你的幫助來征服我們的敵人：部落和恐怖圖騰。你可以從淒涼之地往南走來進入菲拉斯。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28512] = {title = "幫助瑟銀兄弟會", objective = "到灼熱峽谷的瑟銀先遣營地和傑克‧岩腿談談。", description = "黑鐵矮人也許喜愛惹事生非且狡猾成性…不過他們並非都是敵人。我跟瑟銀兄弟會的矮人談過很多次話，他們十分的有幫助。\n\n我有個叫做傑克‧岩腿的朋友不久前來到城鎮，他問我可不可以和他一起加入某個探險隊。這聽起來很重要。\n\n我正好有點忙，不過你也許能幫我走一趟？往西邊灼熱峽谷的方向前進。你在離開荒蕪之地不久的路上就能看到他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28513] = {title = "精靈貴族的傲慢", objective = "殺死8個痛苦或受難的精靈貴族。", description = "一萬年前...\n\n精靈貴族幸福地居住在這裡。我們認為自己比一般階級的夜精靈更高等。由於我們所有的需求都可以藉由魔法與財富來滿足，我們讓生活被慾望及享樂牽著鼻子走。還有貪婪...\n\n你在這裡看到的靈魂已經被罪惡感與悔恨吞噬。苦痛將他們束縛在這裡。如果你想知道更多關於凱斯利爾與辛瑪洛的事，就讓他們從苦痛中解脫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "苦痛匕首卡多雷之靈護符辛瑪洛戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][28514] = {title = "莫頓‧燎星", objective = "到燃燒平原的燎星崗哨向莫頓‧燎星回報。", description = "這些天來，我只有一點點珍貴的時間可以離開灼熱峽谷。過去數個月間，我打算去燃燒平原拜訪一位朋友，但是至今仍找不到機會。\n\n他的名字是莫頓‧燎星。雖然他不是兄弟會的成員，不過他是個受到信賴的朋友，而且絕對值得信賴。\n\n你能幫我送上我的問候給他嗎？你得前往南方，穿過黑石山。只要一路往南…你就會找到他的。\n\n多謝你了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28515] = {title = "莫頓‧燎星", objective = "到燃燒平原的燎星崗哨向莫頓‧燎星回報。", description = "這些天來，我只有一點點珍貴的時間可以離開灼熱峽谷。過去數個月間，我打算去燃燒平原拜訪一位朋友，但是至今仍找不到機會。\n\n他的名字是莫頓‧燎星。雖然他不是兄弟會的成員，不過他是個受到信賴的朋友，而且絕對值得信賴。\n\n你能幫我送上我的問候給他嗎？你得前往南方，穿過黑石山。只要一路往南…你就會找到他的。\n\n多謝你了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28516] = {title = "幾世紀的苦痛", objective = "到凱斯利爾湖的湖心去和卡多雷之靈交談。我同意考慮跟夜精靈與聯盟合作，完全只因為謠傳說辛瑪洛水晶在這裡找到了。\n\n這水晶是一個力量強大的古代神器，它詛咒並毀滅了這片土地，但組合起來，也可以轉而慰藉修補它。\n\n但我無法面對居住在這裡的冤魂。你可以嘲弄我，但你也可以自己親手去試試看。或許坐在湖心那個溫和的靈魂會跟你說話...您會收到：\n\n完成任務後，你將獲得：\n\n", description = "我同意考慮跟夜精靈與聯盟合作，完全只因為謠傳說辛瑪洛水晶在這裡找到了。\n\n這水晶是一個力量強大的古代神器，它詛咒並毀滅了這片土地，但組合起來，也可以轉而慰藉修補它。\n\n但我無法面對居住在這裡的冤魂。你可以嘲弄我，但你也可以自己親手去試試看。或許坐在湖心那個溫和的靈魂會跟你說話...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28517] = {title = "咆哮橡樹", objective = "到達納蘇斯的咆哮橡樹找吉恩‧葛雷邁恩談談。", description = "這裡就是...我們的新家。我不確定我是否真能再次體會到回家的感覺。\n\n不過我們不得不感激夜精靈所供給我們的一切。他們可不是個隨意歡迎任何人的種族。對他們來說，接納我們的到來真正是一項關於信念與慷慨的考驗。\n\n葛玟和葛雷邁恩正在城市裡的咆哮橡木。你應該去拜訪他們。進入我們北方樹下的傳送門，然後在城市的北部找到咆哮橡樹。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28518] = {title = "高等精靈的遺產", objective = "從大法師梅尼爾斯身上取得辛瑪洛的記憶。", description = "一百年前...\n\n我跟一小群高等精靈從家園奎爾薩拉斯旅行到這裡。我們在尋找凱斯利爾的古老秘密...找出它覆滅的原因。\n\n我們在冰裡面找到碎片，水晶的裂片。陪著我們的大法師沒有多久就淪陷在水晶的支配下。因為我們的愚蠢，所以等我們注意到時已經太晚了。\n\n他的靈魂和一群被他逼成瘋狂的靈魂一起，在東南方遊蕩，仍緊抓著珍貴裂片的記憶不放...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28519] = {title = "血精靈的痛苦", objective = "到凱斯利爾湖去殺死7個扭曲之靈或扭曲幽魂。", description = "一年前…\n\n辛瑪洛水晶的傳說流傳到銀月來，我率領所能找到的最強戰士與最優秀學者，組成一支團隊來到這片土地上。我們帶來大量的法力水晶，所以我們當中不會有人想去嘗試辛瑪洛水晶的滋味。\n\n水晶不需要用我們的渴望來毀滅我們。等我們擁有了水晶，它將除了我以外的其他人全扭曲成為卑劣的野獸。\n\n這些扭曲的靈魂仍在四處遊蕩，想把更多生命束縛在這個湖裡。你能不能憐憫他們…或是遠遠地逃開，好在某天死在一個安全的地方？您會收到：\n\n", progress = nil, completion = nil, rewards = "扭曲幽魂匕首扭曲之靈劍刃辛多雷之靈釘錘縈繞記憶法杖您會收到：\n\n凱斯利爾寶珠"}
MultiLanguageQuestData['tw'][28520] = {title = "奈斐賽特城的滅亡", objective = "在奧丹姆的奈斐賽特城消滅黑暗法老特卡恩。", description = "我們準備好攻擊了，<name>。\n\n要是我們打倒黑暗法老特卡恩，不朽巨像將會陷落，我們的軍隊也就能進入奈斐賽特城。\n\n去找出他來，勇敢迎戰。當打倒他的時機到來，我保證你絕不會孤單。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "死者之城項鍊陣亡弟兄護手破敗城市長袍奈斐賽特毀滅披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][28521] = {title = "與薩爾法交談", objective = "穿過木喉要塞到位於冬泉谷的出口去。與薩爾法交談，他就站在木喉要塞的入口外面進行著守衛工作。", description = "腐化的威脅不僅來自南邊的死木熊怪，也來自東邊冬泉谷的冬泉熊怪。如果你想要進一步的援助我們，到要塞的另一邊去與薩爾法交談，就在冬泉谷的入口處。沿著這條路向左就可以到達那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28522] = {title = "冬泉熊怪的活動", objective = "從冬泉熊怪身上收集10條靈魂串珠。", description = "木喉部族習慣只與自己人交涉，<name>。雖然我們會與可信賴的人聯絡，我們還是極力避免遇到其他熊怪部落。\n\n冬泉部落近來漸漸對我們充滿敵意。它們似乎很憤怒，全然沉浸在害怕之中，怨恨任何它們不了解的事。\n\n冬泉熊怪隨身攜帶著靈魂串珠，但很顯然的並沒保護它們不受腐化的影響。帶10串珠子給我，好讓我知道你已將它們的數量減少了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "大地護衛手套尋路者手套巢穴守衛外衣巨熊的擁抱您會收到：\n\n"}
MultiLanguageQuestData['tw'][28523] = {title = "給薩爾法的串珠", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28524] = {title = "給多諾瓦的快遞", objective = "將薩爾法的籃子送到冬泉谷給多諾瓦‧雪山。", description = "多諾瓦‧雪山是一位常去附近溫泉的親切矮人。她聲稱在學習溫泉的魔法屬性。\n\n她是一位很親切的人，而且與我們的部落關係友善。冬泉部落變得越來越有威脅性後，她開始調查讓冬泉部落腐化的因素。\n\n我必須繼續駐守在此，但我準備了一籃點心給她。請幫我拿去給她並轉告她，我們在等待她下一次的拜訪。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28525] = {title = "英雄的召喚：安戈洛環形山！", objective = "到安戈洛環形山的馬紹爾觀測站向威利德‧馬紹爾報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往馬紹爾觀測站向威利德‧馬紹爾報到。\n\n聯盟需要你幫助馬紹爾觀測站的人員發掘安戈洛環形山之中，古老野獸、特有植物和強力水晶的秘密。你可以順著塔納利斯西方的道路前進來抵達安戈洛環形山。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28526] = {title = "大酋長的命令：安戈洛環形山！", objective = "到安戈洛環形山的馬紹爾觀測站向威利德‧馬紹爾報到。你可以選擇在奧格瑪搭乘朵拉斯的蠍尾獅。", description = "所有身強體壯的部落成員，都在此受命前往馬紹爾觀測站向威利德‧馬紹爾報到。\n\n你要幫助馬紹爾觀測站的人員發掘安戈洛環形山的秘密。部落或許能利用生長在環形山中的獨特野獸和水晶。\n\n你可以順著塔納利斯西方的道路前進來抵達安戈洛環形山。或者，你也可以從奧格瑪的朵拉斯飛到那裡。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28527] = {title = "大酋長的命令：希利蘇斯！", objective = "到希利蘇斯的塞納里奧城堡向喚風者傲角報到。你可以選擇在奧格瑪搭乘朵拉斯的蠍尾獅。", description = "所有身強體壯的部落成員都必須聽命前往塞納里奧城堡，向喚風者傲角報到。幫助我們塞納里奧的朋友戰鬥，抵抗暮光之錘。絕不容許丘加利的爪牙控制希利蘇斯！\n\n你可以利用西北邊離開安戈洛環形山的道路前往希利蘇斯。或者，你也可以從奧格瑪的朵拉斯飛到那裡。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28528] = {title = "英雄的召喚：希利蘇斯！", objective = "到希利蘇斯的塞納里奧城堡向喚風者傲角報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往塞納里奧城堡向喚風者傲角報到。你要幫助我們塞納里奧的朋友進行戰鬥，抵抗暮光之錘。絕不容許丘加利的爪牙控制希利蘇斯！\n\n你可以利用西北邊離開安戈洛環形山的道路前往希利蘇斯。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28529] = {title = "虛無的文字", objective = "前往洛丹諾，將黑暗使者的手稿送給遊俠戈琳達‧納希亞。", description = "這些卷軸的內容模糊，而且似乎只是某個巨大謎題的一部分，不過如果你沒弄錯的話，這些卷軸似乎記載著成為惡魔獵人的方法。\n\n大部分的夜精靈都禁止談論成為惡魔獵人所需的黑暗誓約與儀式，所以他們絕對會想對這東西守口如瓶。\n\n遊俠戈琳達‧納希亞會知道如何處理這些卷軸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28530] = {title = "灼燙的徵象", objective = "從滾燙的泉水元素或沸騰的泡沫怪身上收集七件可疑的綠色淤泥。", description = "這大鍋看起來彷彿裝過濃縮的材料。要是冬泉部落直接將這東西丟進泉水裡稀釋，污染層級將會漸漸升高…而稀釋的作用會越來越無效。\n\n東北方的泉水裡有元素沸騰著。我原本以為是大災難造成元素的出現，如今看來有可能是因為這個。\n\n你可以去查查看它們有沒有受到腐化嗎？獵殺幾個元素，並帶給我它們遺留下來的任何綠色異物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28531] = {title = "英雄的召喚：淒涼之地！", objective = "到淒涼之地的塔迪薩蘭向軍官薔琪報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須在通往淒涼之地的道路上的塔迪薩蘭向軍官薔琪報到。\n\n尼耶爾前哨站的英勇士兵們正受到惡魔與部落軍隊的包圍，他們急需你的幫助。要抵達淒涼之地，從石爪山脈的焦炭谷出發，沿著道路往南走。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28532] = {title = "大酋長的命令：石爪山脈！", objective = "到梣谷的銀風避難所向血衛士艾爾多‧石雨報到。", description = "所有身強體壯的部落成員，都在此受命前往梣谷的銀風避難所向血衛士艾爾多‧石雨報到。\n\n部落在石爪山脈的部隊需要你的幫助來驅趕聯盟的入侵者，保衛我們的同胞。血衛士會指引你前往石爪山脈的邊境。\n\n前往銀風避難所，深入梣谷的中心並找尋我們湖邊的部隊。命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28533] = {title = "高階議會的決定", objective = "和奧丹姆的蘭姆卡韓的法歐瑞斯王談話。", description = "高階議會已經準備好決定是否和奈斐賽特族宣戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28534] = {title = "精靈貴族的後裔", objective = "與奎爾多雷之靈交談。", description = "在我死後不久，我族人的貪婪導致他們的流亡。在大陸的盡頭，他們變成了奎爾多雷，也就是高等精靈。在奎爾薩拉斯，他們沐浴在太陽之井的力量下，並遺忘了他們遺傳到的慾望與貪婪。\n\n這些遙遠的後裔在命運之手的牽引下回到這裡，注定要重蹈歷史的覆轍。聽聽他們的故事，就像我的故事一樣...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28535] = {title = "高等精靈的後裔", objective = "與辛多雷之靈交談。", description = "在我死了好長一段時間之後，我的族人因更巨大的錯誤而遭受折磨。高等精靈依賴太陽之井與它的榮光。我們從沒想過有一天會失去它，更不曾對這樣的命運有所準備。\n\n過沒多久，太陽之井在不死生物的攻擊下陷落了，留給我的子孫的只有失落與無助... 而他們選擇的道路永遠地改變了他們。\n\n辛多雷，時至今日仍努力的贖罪，他們也會回到這裡來...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28536] = {title = "辛瑪洛的詛咒", objective = "到冬泉谷的凱斯利爾湖去找科雷克‧天衛", description = "你看的夠多了。你已經知道辛瑪洛水晶帶來的只有毀滅。\n\n如果你不想成為我們的一員的話，就離開這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28537] = {title = "尋找陰影", objective = "追蹤並殺死靈語者之影，然後取得任何與它的主人有關的證據。", description = "你說它談到一個主人？辛瑪洛的擁有者？\n\n這是一個非常重要的消息。<class>，你必須行動！我看見陰影飛向南方。沿著小徑走到上面的廢墟，你或許能跟在它後面爬上結冰的瀑布！\n\n千萬別放鬆警戒…它可能就在那裡等著你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28538] = {title = "女妖的哭嚎", objective = "使用女妖之鏡捕捉10名軍情七處密探。", description = "所以你是來拯救我們的？很好，我會讓自己和你緊緊連結在一起。藉由這樣的連結，我將透過你的眼睛觀察一切，並且趁你在野外時和你進行聯繫。\n\n根據你帶來的計畫書，雷矛條列了軍情七處在北邊索菲亞高地的支援工作。軍情七處是個純由人類組成的單位，我們可以利用的人類。\n\n帶著我的鏡子前往北方。和軍情七處的傢伙作戰並且讓他們陷入瀕死狀態。當他們傷得夠重時，使用這個鏡子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28539] = {title = "英雄的召喚：石爪山脈！", objective = "到位於梣谷和石爪山脈邊界之間的星塵尖塔向女獵手加琳報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往梣谷的星塵尖塔向女獵手加琳報到。\n\n部落的軍隊正持續地往石爪山脈中推進，一定要阻止他們！你可以前往梣谷森林的南部來抵達星塵尖塔。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28540] = {title = "執行魂精魔法", objective = "取得瑞姆沛爾特的心臟。", description = "瑪艾里利用野外的靈魂來製作符咒已經有好幾年了。瑪艾里只是從外面的動物身上把魂精「拖」出來，然後幫小孩子跟冒險者做符咒。\n\n在東邊，有一座很高的山丘上都是裂齒熊。在山頂上的是森林中最老的熊，瑞姆沛爾特。\n\n瑪艾里需要那隻熊來施法術。你把那隻熊的老心臟帶來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "魂精收集者腰帶箝心爪巫醫肩甲獵熊人的腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][28541] = {title = "Cache of Mau'ari", objective = "Watch Witch Doctor Mau'ari pull the E'ko from Rimepelt's body.It be hard to describe de E'ko, but all creatures in dese lands have it... beasts, furbolg, even de frost giants. You got to open your mind and know where to look...\n\nWatch me now, an' I show you how to pull out de E'ko.您會收到：\n\n", description = "It be hard to describe de E'ko, but all creatures in dese lands have it... beasts, furbolg, even de frost giants. You got to open your mind and know where to look...\n\nWatch me now, an' I show you how to pull out de E'ko.您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n瑪艾里的容器"}
MultiLanguageQuestData['tw'][28542] = {title = "大酋長的命令：費伍德森林！", objective = "到費伍德森林的翡翠聖地向泰尼爾‧飄葉報到。", description = "所有身強體壯的部落成員，都在此受命前往翡翠聖地向泰尼爾‧飄葉報到。\n\n塞納里奧議會需要你的幫助來將費伍德森林從惡魔與其他腐化生物的控制中解放出來！\n\n要前往翡翠聖地，從梣谷往北走，順著道路直到你抵達該處。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28543] = {title = "英雄的召喚：費伍德森林！", objective = "到費伍德森林的翡翠聖地向泰尼爾‧飄葉報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往翡翠聖地向泰尼爾‧飄葉報到。\n\n他的團隊需要你的幫助來將費伍德森林從惡魔的奴役中解救出來。從梣谷往北走，順著道路進入費伍德森林，直到你抵達翡翠聖地。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28544] = {title = "英雄的召喚：冬泉谷！", objective = "到冬泉谷的冰火溫泉向多諾瓦‧雪山報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往冰火溫泉向多諾瓦‧雪山報到。\n\n她需要你的幫助，來解決冬泉熊怪的威脅。要抵達冬泉谷，你必須從費伍德森林北部出發往東走並穿越木喉要塞。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28545] = {title = "大酋長的命令：冬泉谷！", objective = "到冬泉谷的冰火溫泉向多諾瓦‧雪山報到。", description = "所有身強體壯的部落成員，都必須聽命前往冰火溫泉向多諾瓦‧雪山報到。她對於冬泉熊怪的發現或許會是徹底解決這項威脅的關鍵。\n\n要抵達冬泉谷的冰火溫泉，你必須從費伍德森林北部出發，向東穿越木喉要塞。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28548] = {title = "大酋長的命令：淒涼之地！", objective = "到淒涼之地的塔迪薩蘭向弗里安報到。", description = "所有身強體壯的部落成員，都在此受命前往淒涼之地的塔迪薩蘭向弗里安報到。淒涼之地裡英勇的部落戰士需要你的幫助，來擊退聯盟的軍隊和古老的惡魔們。\n\n協助我們驅逐進逼的聯盟部隊，為了部落的榮光，堅守艾薩拉！\n\n要抵達淒涼之地，從石爪山脈的焦炭谷出發，沿著道路往南走。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28549] = {title = "大酋長的命令：南貧瘠之地！", objective = "到南貧瘠之地的高地小道向努拉‧探路者報到。你可以選擇在奧格瑪搭乘朵拉斯的蠍尾獅。", description = "所有身強體壯的部落成員，都在此受命前往南貧瘠之地的高地小道向努拉‧探路者報到。\n\n由於聯盟近期在貧瘠之地得到的勝利，我們的敵人極有可能威脅到我們的補給線。我們必須行動！\n\n你可以從石爪山脈往東走來抵達高地小道。或者，你也可以從奧格瑪的朵拉斯飛到那裡。命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28550] = {title = "英雄的召喚：南貧瘠之地！", objective = "到南貧瘠之地西北部的石爪小徑向指揮官瓦爾波報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往南貧瘠之地的石爪小徑向指揮官瓦爾波報到。我們英勇的戰士在貧瘠之地取得了驚人進展，但是也付出了巨大的代價！他們需要你的幫忙來鞏固這些成果。你可以從石爪山脈出發，穿過東南邊的巨木谷來抵達南貧瘠之地。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28551] = {title = "英雄的召喚：南貧瘠之地！", objective = "到南貧瘠之地的北方城堡之外的碼頭向碼頭管理員路易斯報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往北方城堡附近向碼頭管理員路易斯報到。\n\n我們英勇的戰士們在貧瘠之地取得了驚人進展，但他們也付出了巨大的代價！他們需要你的幫忙來鞏固這些成果。你可以乘船前往棘齒城，然後沿著海岸往南走來抵達北方城堡。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28552] = {title = "英雄的召喚：塵泥沼澤！", objective = "到塵泥沼澤的塞拉摩島向卡莉雅‧哈斯丁報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往塞拉摩島向卡莉雅‧哈斯丁報到。\n\n你必須援助軍情七處的卡莉雅‧哈斯丁找到潛伏在塞拉摩城內與城外的威脅。你可以從米奈希爾乘船或是由南貧瘠之地穿過沼澤來抵達塞拉摩島。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28553] = {title = "歐克里拉和詛咒之地", objective = "到詛咒之地的巨槌要塞去向歐克里拉回報。", description = "我有最後一件快遞要交給你，<name>。它來自南邊詛咒之地的巨槌要塞。\n\n戰爭監護者歐克里拉正在進行一場戰爭，對抗來自守望堡的聯盟軍隊，而他需要一個勇敢的<class>的協助。你得下定決心。\n\n前往南邊的詛咒之地，然後往西邊走。祝你好運了，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28554] = {title = "大酋長的命令：塵泥沼澤！", objective = "到塵泥沼澤的蕨牆村向克羅格報到。你可以選擇在奧格瑪搭乘朵拉斯的蠍尾獅。", description = "所有身強體壯的部落成員，都在此受命前往蕨牆村向克羅格報到。沼澤裡充滿了各式各樣的敵人，位於該處的聯盟軍隊則強大得危險。\n\n你可以順著南貧瘠之地東部的道路前往塵泥沼澤。或者，你也可以從奧格瑪的朵拉斯飛到那裡。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28556] = {title = "壯士斷腕", objective = "在索菲亞高地、考蘭之匕、山頭營地和加文高地各設置一份哥布林小型核彈。", description = "若想阻止雷矛的入侵，我們就得切斷他們伸出的手指。\n\n<克洛姆什遞給你一個小包裹。>\n\n在這個包裹裡有四個高性能的哥布林炸藥。我要你潛入奧山四指的每一區: 索菲亞高地、考蘭之匕、山頭營地和加文高地，然後在每一處放置一份哥布林小型核彈。\n\n完成這件事，還有梅里薩拉要你完成的每件事之後，回到我這裡來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "索菲亞腰帶加文的肩鎧考蘭的披風山頭營地腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][28557] = {title = "大酋長的命令：奧丹姆！", objective = "到塔納利斯西邊的灌木谷向艾達拉報到。", description = "所有身強體壯的部落成員，都必須聽命前往塔納利斯的灌木谷向艾達拉報到。\n\n根據古老文字記載，奧丹姆裡面充滿了無法言喻的財富及寶藏。前往該處，以部落之名取回這些財寶！\n\n你可以前往塔納利斯西南方，在灌木谷中和艾達拉的車隊會合。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28558] = {title = "英雄的召喚：奧丹姆！", objective = "到塔納利斯的灌木谷和艾達拉談話。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往塔納利斯的灌木谷向艾達拉報到。\n\n為了聯盟，成為最早進入奧丹姆、取得其中寶藏的人吧！\n\n前往塔納利斯西部邊境和艾達拉的車隊會合。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28559] = {title = "英雄的召喚：血謎島！", objective = "到血謎島的凱索十字路向『伊萊克牧者』渥卡恩報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往凱索十字路向『伊萊克牧者』渥卡恩報到。\n\n血謎島的人民需要你的幫助，解決血精靈叛徒和島上肆虐的危險生物。你可以利用藍謎島北邊的橋樑抵達血謎島上的凱索十字路。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28560] = {title = "大酋長的命令：鬼魂之地！", objective = "到鬼魂之地的安寧地向秘法師范德隆報到。", description = "所有身強體壯的部落成員，都在此受命前往鬼魂之地的安寧地向秘法師范德隆報到。\n\n那裡需要你的幫助來擊退大量的天譴軍團入侵者，並取得被遺忘者的幫助來對抗我們的共通敵人。\n\n從晴風廣場出發，順著道路往南走來進入鬼魂之地，並抵達安寧地。B\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28561] = {title = "必須守住納候姆", objective = "到奧丹姆的納候姆向軍團回報。", description = "一旦我們西進攻打奈斐賽特城，敵人就會由我們較弱的東邊攻擊我們。\n\n納候姆會首先淪陷，這樣一來，蘭姆卡韓也會失守。\n\n我們已經有一小支分遣隊先行進駐該處了。\n\n向他們聽取簡報。我要你在我能派出更多部隊之前，確實固守住納候姆。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28562] = {title = "英雄的召喚：西部荒野！", objective = "到西部荒野的傑生農場向何瑞修‧萊恩中尉報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往傑生農場向何瑞修‧萊恩中尉報到。\n\n西部荒野已經被乞丐和遊民給淹沒，導致犯罪率大幅攀升。從艾爾文森林沿路往西走即可抵達西部荒野的傑生農場。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28563] = {title = "英雄的召喚：赤脊山！", objective = "到赤脊山的警戒塔向警衛隊長派克報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往赤脊山的警戒塔向警衛隊長派克報到。\n\n派克隊長的部隊受到豺狼人和獸人的包夾，湖畔鎮的居民身陷致命危機，需要你幫忙解救。從艾爾文森林的邊境往東走，進入赤脊山的三角路口區域，就可以抵達警戒塔。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "派克的碼尺懸題腰帶髒髒的長靴不幸足靴髒髒的輕鞋您會收到：\n\n"}
MultiLanguageQuestData['tw'][28564] = {title = "英雄的召喚：暮色森林！", objective = "到暮色森林的夜色鎮向指揮官奧爾希雅‧埃伯洛克報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往夜色鎮向指揮官奧爾希雅‧埃伯洛克報到。\n\n指揮官的守夜人正勉力對抗肆虐的狼群和野生狼人。少了你的幫助他們無法堅持太久。你可以順著艾爾文森林和赤脊山之間的道路南行，來抵達位於暮色森林的夜色鎮。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28565] = {title = "英雄的召喚：溼地！", objective = "到丹奧加茲向巡山人拉倫報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往丹奧加茲向巡山人拉倫報到。\n\n在大災難的破壞之下，如今的溼地正遭到野生野獸、獸人盜匪和野蠻豺狼人的肆虐！要前往溼地，你必須從洛克莫丹往北走，穿過矮人要塞丹奧加茲。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28566] = {title = "大屠殺", objective = "殺死冰心上尉和12名雷矛士兵。", description = "<梅里薩拉的影像出現在你的面前。>\n\n雷矛的前線營地就坐落在索菲亞高地西邊的考蘭之匕上。你得進到營地裡，殺死你所遇見的每一個矮人。我們得教教他們恐懼的意義，而絕對的屠殺最適合當做這樣的課程了。\n\n不留活口，<name>。尤其是他們的上尉，一定得死！\n\n我會和你保持聯繫的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28567] = {title = "英雄的召喚：洛克莫丹！", objective = "到洛克莫丹的南門崗哨向駕駛員塞克‧錘足報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往南門崗哨向駕駛員塞克‧錘足報到。\n\n巨石水壩的毀滅、狗頭人和穴居怪的復甦，已經讓巡山員們不堪負荷。他們急需援軍！從丹莫洛東部出發，往東穿過南門小徑以抵達南門崗哨。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28568] = {title = "大酋長的命令：銀松森林！", objective = "到銀松森林的被遺忘者高階指揮所向總執行官莫吐斯報到。", description = "所有身強體壯的部落成員都必須聽命前往銀松森林，到被遺忘者高階指揮所向總執行官莫吐斯報到。\n\n現在，我們比以往更迫切需要你的幫助，清除這個地區的所有敵人，並且拿下吉爾尼斯的港口！\n\n要前往被遺忘者高階指揮所，你必須往南穿過提里斯法林地，進入銀松森林。從那裡順著道路不斷往南走，就會抵達被遺忘者高階指揮所。\n\n弟兄姊妹，前進吧！命運在呼喚著我們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28569] = {title = "沼槳特快車", objective = "到燃燒平原的東南隅和雪倫‧爆塵談談，好乘坐沼槳特快車前往悲傷沼澤。然後到沼漿和貿易巨商銀鉗談談。", description = "我聽說了許多故事，敘述一條通往悲傷沼澤的小路。神秘的傳說指出，有一條山間小徑可以完全避開赤脊山，讓你直接進入泥漿！\n\n如果在這沒事可做，我想你只好離開了。我們都會因此感到難過的。你要離開的時候，去和平原東南方角落的雪倫‧爆塵談談。她會送你一程的。\n\n<奧拉留斯的頭傾向一側，好像在聆聽什麼聲音。>\n\n溫奇？溫奇！不！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28570] = {title = "沼槳特快車", objective = "到燃燒平原的東南隅和雪倫‧爆塵談談，好乘坐沼槳特快車前往悲傷沼澤。然後到沼漿和貿易巨商銀鉗談談。", description = "你是個貨真價實的<race>，對吧？看看你…你完全的成長了。而我們不過剛認識！\n\n我知道接下來會如何…不久後，你在烈焰峰的工作就會全部完成。你將承諾再次回來。但你永遠無法實踐。\n\n基布雷爾之前就看得夠多了。\n\n你要離開的時候去和平原東南方角落的雪倫‧爆塵談談。她會用子彈送你一程的。\n\n什麼？噢，不過是個火箭而已。非常安全。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28571] = {title = "大酋長的命令：希爾斯布萊德丘陵！", objective = "到希爾斯布萊德丘陵的南點大門向高階執行官達薩利亞報到。", description = "所有身強體壯的部落成員，都在此受命前往希爾斯布萊德丘陵的南點大門，向高階執行官達薩利亞報到。被遺忘者戰爭機器正不斷前進，為了部落佔領羅德隆！\n\n想到達南點大門，你要順著道路往南通過銀松森林，再走上向東的岔路進入希爾斯布萊德丘陵。\n\n邁進吧，<兄弟/姊妹>！命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28572] = {title = "大酋長的命令：阿拉希高地！", objective = "到阿拉希高地的加林之殞向黑暗遊俠奧麗娜報到。", description = "所有身強體壯的部落成員，都在此受命前往加林之殞向黑暗遊俠奧麗娜報到。黑暗女王的軍隊需異你伸出援手，好擴張部落的領地並驅逐聯盟的干擾者。\n\n要抵達阿拉希高地，從希爾斯布萊德丘陵往東出發，並順著道路穿越索拉丁之牆。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28573] = {title = "英雄的召喚：阿拉希高地！", objective = "到阿拉希高地的避難谷地向尼艾絲隊長報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往避難谷地向尼艾絲隊長報到。\n\n古老的激流堡的榮耀需要恢復！巨魔和罪犯已竊佔那座城市的街道太久了。從濕地北邊出發，穿越薩多爾大橋抵達阿拉希。順著道路前往避難谷地並向隊長報到。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28574] = {title = "大酋長的命令：辛特蘭！", objective = "到辛特蘭的惡齒村向斷齒長者報到。", description = "所有身強體壯的部落成員，都在此受命前往惡齒村向斷齒長者報到。\n\n蠻錘的矮人正式和聯盟結為聯軍，也讓自己成了我們的敵人。必須擊敗他們！\n\n要前往惡齒村，穿過希爾斯布萊德丘陵東邊的山脈，穿越辛特蘭，並前往東邊的河岸。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28575] = {title = "大酋長的命令：西瘟疫之地！", objective = "到西瘟疫之地的安多哈爾向寇爾提拉‧亡織者報到。", description = "所有身強體壯的部落成員，都在此受命前往安多哈爾向寇爾提拉‧亡織者報到。\n\n聯盟部隊正在進犯安多哈爾的都市廢墟，試著將那裡佔為己有。我們必須在對方站穩腳跟之前反制他們！\n\n穿過提里斯法林地東端的亡靈壁壘，再順著道路往東南邊前進，好抵達安多哈爾和我們在那裡的部隊會合。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28576] = {title = "英雄的召喚：西瘟疫之地！", objective = "到西瘟疫之地的安多哈爾向薩沙理安報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往安多哈爾向薩沙理安報到。\n\n儘管先前我們在安多哈爾贏得了勝利，但被遺忘者隨即決定發動反擊。那裡需要你的幫助，來擊退天譴軍團和部落，並收復失落的安多哈爾。\n\n往北穿越希爾斯布萊德丘陵，並順著冰風營地上方的道路走，即可抵達安多哈爾。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28577] = {title = "大酋長的命令：東瘟疫之地！", objective = "到東瘟疫之地的索多里爾河東岸向菲歐娜報到。", description = "所有身強體壯的部落成員，都在此受命前往索多里爾河東岸向菲歐娜報到。\n\n銀白十字軍加強了在瘟疫之地的軍力，並且需要你的幫助來鞏固他們的勝利。\n\n在西瘟疫之地的東緣穿過索多里爾河，然後在對岸尋找菲歐娜。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28578] = {title = "英雄的召喚：東瘟疫之地！", objective = "到東瘟疫之地的索多里爾河東岸向菲歐娜報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往索多里爾河東岸向菲歐娜報到。\n\n銀白十字軍需要你的幫助來從天譴軍團手中搶回東瘟疫之地。\n\n要前往東瘟疫之地，從西瘟疫之地出發，渡過索多里爾河並在東岸搜尋菲歐娜。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28579] = {title = "英雄的召喚：荒蕪之地！", objective = "到東瘟疫之地的聖光之願禮拜堂向吉克‧火箭嘴報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往東瘟疫之地的聖光之願禮拜堂向吉克‧火箭嘴報到。\n\n那裡需要你的幫助，好測量死亡之翼所造成的災害和部落軍隊在荒蕪之地的部署。\n\n吉克同意提供前往荒蕪之地的運輸火箭，用以換取你的協助。到東瘟疫之地的聖光之願禮拜堂去找他。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28580] = {title = "大酋長的命令：荒蕪之地！", objective = "到東瘟疫之地的聖光之願禮拜堂向吉克‧火箭嘴報到。", description = "所有身強體壯的部落成員，都在此受命前往東瘟疫之地的聖光之願禮拜堂向吉克‧火箭嘴報到。\n\n聯盟亟欲在荒蕪之地取下橋頭堡。你的任務就是阻止他們，並蒐集死亡之翼所帶來毀滅的情報。\n\n加克同意提供前往荒蕪之地的運輸火箭。到聖光之願禮拜堂去找他。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28581] = {title = "大酋長的命令：灼熱峽谷！", objective = "到灼熱峽谷的瑟銀先遣營地向傑克‧岩腿報到。", description = "所有身強體壯的部落成員，都在此受命前往瑟銀先遣營地向傑克‧岩腿報到。\n\n根據破碎之手的報告，灼熱峽谷的黑鐵矮人似乎在準備著什麼。你的任務是盡力發掘出他們的計畫並加以阻止。\n\n你可以從荒蕪之地沿路向西進入灼熱峽谷。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28582] = {title = "英雄的召喚：灼熱峽谷！", objective = "到灼熱峽谷的瑟銀先遣營地向傑克‧岩腿報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往瑟銀先遣營地向傑克‧岩腿報到。\n\n根據軍情七處的報告，灼熱峽谷的黑鐵矮人似乎正在準備攻擊。你的任務是盡力發掘出他們的計畫並加以阻止。\n\n你可以順著荒蕪之地西邊的道路走，來抵達灼熱峽谷。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28583] = {title = "克拉茲工坊", objective = "將專利申請書帶去暮光高地的克拉茲工坊給克拉茲上尉。", description = "這台新型的伐木機應用了最頂尖的設計，<name>。最頂尖的!下一步就是要保護好我的智慧財產。註冊專利、商標、申請停止令。喔，還有賄賂!\n\n喏，把這份專利申請書帶去克拉茲工坊給克拉茲上尉。他在飛艇失事後活了下來，或許正迫不及待尋找新的商機。\n\n克拉茲工坊就在這兒的正北方，一個絕對安全的山尖上。快去，小子。工作、工作!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28584] = {title = "施工品質", objective = "使用防爆膠帶封閉10個故障的閥門。", description = "看著，老大，要不是這個蠢貨，克拉茲工坊原本一點事也沒有。\n\n倒楣的是，這個「公子哥」羅斯曼決定要在山頭上指揮這個地方！拜託，到底誰會這麼做？\n\n這下好了，故障的閥門害油漏得到處都是。能請你帶著這捆防爆膠帶，幫我把漏洞封起來嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "發瘋駕駛員手套高科技專家安全帽製圖師的護胸您會收到：\n\n"}
MultiLanguageQuestData['tw'][28586] = {title = "小馬泳圈救援行動", objective = "使用小馬泳圈拯救10個落水的克拉茲工坊苦力。", description = "前面這個渾蛋把我的人全殺光了！\n\n「無賴」布雷特把東西放錯了位置，害得克拉茲工坊極不穩定。這些爆炸把平台上的工人轟進了水裡。\n\n你不介意用小馬泳圈到下頭去把他們救上來吧，<name>？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28587] = {title = "霜狼的援助", objective = "到希爾斯布萊德丘陵找沃加‧死爪談話。", description = "我會研讀一下雷矛的戰鬥計畫並準備突襲行動。我需要你前往奧特蘭克山谷尋求霜狼部族的援助，霜狼部族是我們前任大酋長索爾的家族。他們將會協助我們一同攻擊雷矛矮人!只要齊心協力，我們一定能徹底消滅入侵者並將他們永遠趕出羅德隆!\n\n出發吧，<name>。奧特蘭克山谷就在塔倫米爾的西北方，去找沃加‧死爪，告訴他部落請求霜狼部族的支援!\n\n勝利!", progress = nil, completion = "你從塔倫米爾來？你散發著死亡的氣息…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28588] = {title = "蠻錘的騷擾", objective = "殺死10個蠻錘掠奪者。", description = "就在這兩個蠢貨搶著當搞破壞的大功臣時，敵人對克拉茲工坊展開了全面的入侵!\n\n到處都是那些不安好心的蠻錘矮人。到外面去，幫克拉茲工坊除掉這些酒氣沖天的臭蟲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28589] = {title = "所有家當，除了廚房水槽", objective = "殺死15個蠻錘風暴利爪。", description = "你得想個辦法對付那些蠻錘風暴利爪。他們把我們害慘了！\n\n問題是，我們快沒彈藥了，只好臨時湊點什麼。我們將所有能想到的東西都裝進了我的克拉茲火砲:小馬泳圈、卡迦可樂罐、食物包裝、燃料電池、輪胎…你明白的。\n\n基本上除了廚房水槽，所有家當都用上了。\n\n你這會兒有心情來點瞄準演練嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "工具支架臂甲河水防治護胸槍砲射擊手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][28590] = {title = "報復", objective = "到高岸堡附近的裂天者號上找派奇說話。", description = "我正巧知道一些聯盟混帳得到了某些東西。而他們的某些東西是屬於我們的。我已經授權發動一波對高岸堡的全力進攻。\n\n搭上裂天者號，加入攻擊行動。等你抵達目的地後，派奇會告訴你更多細節。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28591] = {title = "拆牆", objective = "使用裂天者砲台殺死80個高岸堡神射手、12個高岸堡砲手，並摧毀4座高岸堡火砲。", description = "你看起來就是個閒不下來的<男人/女孩>。爬上一座砲台，摧毀他們牆上的防禦。\n\n動作快點，好嗎?趁大火球還沒把我們轟上天之前。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28592] = {title = "分包裹", objective = "到船上、堡壘入口，還有北方的一座塔裡放置提克爾的爆裂物。", description = "我想派奇心中一定有什麼了不起的計畫，不過如果我們不留下一點爆炸性的禮物，這可算不上是一場攻擊。\n\n到船上、堡壘入口，還有北方的一座塔裡放置一些炸藥。這應該就夠他們忙的了。\n\n我們正準備降落。當你辦完事後，就到東邊的塔和我們會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "克拉茲工坊攀爬腰帶機組檢修足靴鯊盾兜帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][28593] = {title = "最重要的事", objective = "取回感應式負載平衡器。", description = "你在艾薩拉幫我們收集到的感應式負載平衡器，和卡爾洛斯的飛艇一起墜落到了地面。聯盟把它藏在堡壘的某處，克拉茲想要奪回它。\n\n我猜他們一定是把它藏在堡壘的地下室，你就從那裡開始找吧。拿到它後，就回到東部哨塔找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28594] = {title = "高岸堡，哭泣吧", objective = "殺死10個高岸堡防衛者。", description = "過去那裡好好攪和那些聯盟雜碎一番。你愛找誰就找誰。只要能分散他們的注意力，讓我們可以對付真正的目標。\n\n完成後到東部哨塔附近找我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28595] = {title = "克拉茲動起來!", objective = "和紐特說話，回到克拉茲工坊，並將感應式負載平衡器交給克拉茲上尉。", description = "好了。我們已經準備妥當。啟航吧。\n\n紐特有幾架旋翼機停在塔頂上。去找她，盡快回到克拉茲工坊。我們留在這解決剩下的敵人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "裂天者戰甲空襲部隊護腿突擊兵兜帽風劫信標您會收到：\n\n"}
MultiLanguageQuestData['tw'][28596] = {title = "歡迎來到高岸堡!", objective = "到高岸堡殺死10個部落攻擊者。", description = "歡迎來到高岸堡，士兵。你來得正是時候。\n\n部落的軍隊剛從空中發動了一波攻擊。你得挺身而出。除掉他們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28597] = {title = "兩頭燒", objective = "收集10袋滿滿的大砲火藥。", description = "哈!我們馬上就得行動啦，<name>。看來高岸堡遇上了你們所謂的飛艇難題:那艘飛船把牆撞了個稀巴爛。\n\n聽著，我想到了一個笨到無敵的點子。我只需要一些大砲火藥。\n\n去高岸堡附近收集火藥，越多越好，然後到貿易區來見我!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28598] = {title = "眼光放高", objective = "等待法戈‧燧鎖把你送上飛艇，然後將他的炸藥放置在下層的船艙。", description = "看好，<name>。我找到了高岸堡最大的一把槍!我想用來試試一個老爸傳給我的伎倆，這招是我爺爺傳給我老爸的，我爺爺又是在我曾祖父轟掉自己之前學會的。\n\n這招就叫做「<class>轟炸」。\n\n你只要找來一個<race><class>，把<他/她>裝進一個大砲，然後... 別緊張。通常都會成功。\n\n拿著這些炸藥，在我旁邊等著。等到飛船一過來，我就把你轟上甲板。把這些炸藥裝進她的船腹，然後，呃，然後我也不知道，你就在路上想個辦法吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "燧鎖的寶貝槍您會收到：\n\n"}
MultiLanguageQuestData['tw'][28599] = {title = "庫德蘭等著你", objective = "到暮光高地的高岸堡內找庫德蘭‧蠻錘說話。", description = "看來攻擊結束了，<name>。真可惜，我們的<class>火箭還沒派上用場呢。\n\n先不管了，庫德蘭‧蠻錘正在堡壘最上頭，我想他一定會給你一個英雄式的歡迎。這是你應得的!去見他吧!\n\n我得到海灘繼續巡視。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28600] = {title = "忠誠問題", objective = "和德雷克塔爾談話。", description = "我沒有權限做此決策，你必須跟我們的首領德雷克塔爾談談。我已經向霜狼要塞通報你到來的訊息了，德雷克塔爾將會與你私下會談。", progress = nil, completion = "&lt;高階督軍克洛姆什的臉色發白。&gt;\n\n他們拋棄了我們？他們把整個部落都當成了被遺忘者？不能有這種事！\n\n我…\n\n&lt;克洛姆什單腳跪地。&gt;\n\n我…我會沒事的。我們不用他們幫忙。讓霜狼的傢伙見鬼去吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28601] = {title = "老事情", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28602] = {title = "準備好", objective = "收集六段繩索。", description = "每一位有份量的探險家都知道絕對不能在沒有充足繩索的情況下踏入洞穴，地牢，土窖或墓穴...對嗎?\n\n我的繩索就在你所引爆那輛裝滿炸藥的貨車上。\n\n你何不幫我在附近找一下，看看能否發現一些。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "斷骨頭盔腿骨斷裂踏靴握繩手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][28603] = {title = "滲透", objective = "消滅講師路法斯，訓練中士瑪格努斯和渣鬍子上尉。", description = "你的下一個任務是前往西邊的高地並滲透進雷矛的訓練營地。雖然那邊有上百位雷矛受訓員，但我手下的一名女妖會將你偽裝成我們稍早前抓到的人類俘虜，讓你可以在敵營中自由出入。\n\n進入高地，找出雷矛的講師，然後強迫他們攻擊你!當他們對你拳打腳踢時，殺了他們。只要導師死了，他們就無法訓練更多的士兵!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28604] = {title = "欺騙和詭計", objective = "使用水桶毒害30個雷矛受訓員。", description = "只要我持續跟在你身邊，敵人就會認為你跟他們是同陣營的。然而切記，你新獲得的人性並不允許你因此變得無所顧忌，假如你太掉以輕心，矮人將會對你產生疑心，甚至會攻擊你!\n\n說到這裡，我有個計畫，拿著這個裝有毒藥水的桶子去讓那些又累又渴的雷矛受訓員暢飲一番。只要喝下這個，他們會變得像垂死的病人一般，最終死於毒害。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "劇毒護腕魅影外衣莉莉絲的魔杖預謀殺人指環鬼魅鎖甲外套欺瞞護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][28605] = {title = "支配", objective = "殺掉10名雷矛工程師。", description = "<梅里薩拉的思緒與你的心智進行了交流>\n\n最後一個任務是突襲在加文高地的攻城器械技師，他們就在高地的西邊。前往最後的那根手指，幹掉那些為雷矛製作戰爭器械的矮人與地精工程師，別忘了設置好克洛姆什終極版的小型核彈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28607] = {title = "酷炫改裝車的鑰匙", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n酷炫改裝車的鑰匙"}
MultiLanguageQuestData['tw'][28608] = {title = "灰影墓穴", objective = "到喪鐘鎮的灰影墓穴取得濃稠的防腐液和屍體縫合麻繩。", description = "很高興看到你還可以醒過來四處走動，<name>。你狀況還不壞，很好，尤其是在死了這麼久之後!\n\n其他人就不像你這麼幸運了。如果你不介意的話，我需要你幫忙拿回我的防腐液和一些麻繩來把這些屍體縫合起來。你可以在灰影墓穴找到這些東西，就是我身後的這棟建築物。\n\n這位是達納爾，他會跟你一起去，他知道路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28609] = {title = "打擊時間", objective = "與迪滋‧岩偷交談。", description = "我們三個為了誰的武器比較精良，已經爭論了好幾個星期。\n\n我絕不允許任何人說我的釘錘是第二名。基爾拉姆的斧頭和瑟里爾的劍永遠都比不上我這樣工藝品的純粹力量。\n\n我懶得繼續爭論下去。是時候拿證據給那兩個傢伙看看，證明我是對的了。親愛的，如果你願意，到外面去找迪滋‧岩偷，告訴他:我需要他所能找到最大的巨礫!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28610] = {title = "麻煩的礫石", objective = "從霜片奔行者身上取得6份優質礫石。", description = "如果你想弄一顆巨石過去那裡，你可以用我的專利:礫石封裝盒!通常我會直接賣你一個，但我的材料剛用完。\n\n有些土元素突然出現在城鎮南方的山頂上。它們是很優良的礫石來源。如果你帶足夠的數量回來給我，我會照進貨量付錢給你，還免費奉送你一個礫石封裝盒!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28611] = {title = "污染者儀式", objective = "到莫克迪普山洞阻止奈斐賽特儀式。", description = "啊，現在我了解得更透徹了，<name>。\n\n我們對奈斐賽特的疑慮果然是對的。我可以感覺到他們正是污染河川的元兇。\n\n再到水裡一趟，找到莫克迪普山洞。你會發現奈斐賽特正在舉行一場腐化的儀式。阻止他們，讓河川恢復原本的清澈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28612] = {title = "哈里遜‧瓊斯與奧丹姆神廟", objective = "取得應許法櫃。", description = "我們經歷了這麼多，看來一切都快要水到渠成了!\n\n我們離法櫃只差幾步了...我研究了一下開啟它的密碼...舒諾茲還以為我們死了...\n\n你知道嗎，我們可能真的快達成目標了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "法老的陪葬品肩甲古老生物束腰應允護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][28613] = {title = "另一頭再見!", objective = "到奧丹姆的造物者高地找哈里遜‧瓊斯說話。", description = "好吧，<name>。我們為自己爭取了一點喘息的空間，但是沒有時間可以浪費了。\n\n跟著我!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28614] = {title = "狂暴熊", objective = "殺死狂暴者葛羅納爾。", description = "失去冬泉酋長並無法停止冬泉谷的憤怒。失去酋長之後，他們最強壯的一個戰士已經漸漸晉升到足以掌握恐怖勢力的地位。\n\n狂暴者葛羅納爾棲息在寒水村上方的洞穴裡，服用了大量的腐化火水，強得足以殺死十隻次等的熊怪。\n\n他變成了自大又可怕的野獸！我們的戰士都無法面對他…你有足夠的力量擊敗他嗎，<class>？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "脹起的腰帶熊暴者肩甲伯恩多的捆綁式長靴火水護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][28615] = {title = "翻覆大地", objective = "用塔恩瑞爾的超載圖騰讓四支冬泉谷大地圖騰的元素超載。", description = "且不論他們的腐敗和瘋狂，冬泉熊怪幾乎不用他們的薩滿能力。我對他們使用元素的力量傷害我的部落和其他無辜者感到很不舒服。\n\n我們會使用他們自己的圖騰對付他們!帶著我的圖騰進去寒水村。從遠處將它的力量使用在冬泉熊怪的圖騰上，這樣一來大地的暴怒就會向周邊釋放出去!\n\n我應該不用提醒你...保持安全距離!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28616] = {title = "雷矛的末日", objective = "目睹雷矛的末日。", description = "在我們繼續任務之前，讓我們先為那位陣亡的兄弟歐庫斯做片刻的默哀，假如沒有他，我們必定會在雷矛的猛攻下遭到摧毀。這是為了你，兄弟！\n\n<克洛姆什單膝跪地。>\n\n現在，<name>，別以為我會忘記你在整個事件中扮演的角色！這就是為什麼你能夠有榮幸負責引爆哥布林小型核彈。\n\n你準備好了嗎？為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "壞掉的希爾斯布萊德指套小型核彈腰帶叛國披風防核彈護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][28617] = {title = "花朵的力量", objective = "撐過1波殭屍的猛烈攻擊。", description = "你知道怎麼使用噴濺者，但你知道該怎麼使用向日葵來讓它們生長得更快嗎？我們會種植一些向日葵，然後再種植噴濺者來抵擋管理員斯蒂沃特的瘋狂怪物。\n\n上吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28618] = {title = "運送巨礫", objective = "將礫石封裝盒帶去永望鎮遞交給輕盈的莉莉絲。", description = "拿去，我答應要給你的！一個礫石封裝盒。\n\n這是莉莉絲要的，對吧？她是我唯一的顧客！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28619] = {title = "大酋長的命令：阿拉希高地！", objective = "到阿拉希高地的加林之殞向黑暗遊俠奧麗娜報到。", description = "所有身強體壯的部落成員，都在此受命前往加林之殞向黑暗遊俠奧麗娜報到。黑暗女王的軍隊需要你伸出援手，好擴張部落的領地並驅逐聯盟的干擾者。\n\n要抵達阿拉希高地，從希爾斯布萊德丘陵往東出發，並順著道路穿越索拉丁之牆。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28620] = {title = "東點哨塔", objective = "和希爾斯布萊德丘陵的東點哨塔的尼爾斯‧畢羅特談話。", description = "我們在東南方的崗哨遇到點麻煩。我沒有再更進一步的消息，除了...嗯，讓我來讀上一封信吧:\n\n「獸人越來越鬧脾氣。派人來幫忙不然我拿蘆葦打他們。」\n\n就這樣。這是我們的首席哲學家，尼爾斯‧畢羅特寄來的。沒錯，我也搞不懂是什麼意思。你可以到東點哨塔去看看他要幹嘛嗎?我受不了這些含糊不清的信了!\n\n你只需要往南去，再順著向東的路走。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28621] = {title = "把娃娃放回搖籃裡!", objective = "到奧丹姆神廟找哈里遜‧瓊斯說話。", description = "哦！\n\n你和那小子來到這兒的路上挺愜意的，是吧！？\n\n<喝喝酒/拉拉小手>，看看風景，八成是這樣吧。\n\n可別高興得太早，真正的工作才要開始呢！\n\n這個古老文物還有許多你不知道的秘密，不過想要解開這些秘密，就得把它拿到先祖育床！\n\n你想我們該怎麼做？\n\n或許那邊那個小子有什麼好點子，嗯？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28622] = {title = "閃三下", objective = "在奧丹姆神廟使用信號槍。", description = "我打算將法櫃帶回我的實驗室進行研究，不過看起來布萊恩那個老頭有別的計畫。\n\n他以為自己有辦法從奧丹姆阻止死亡之翼。\n\n我的搭擋札克已經準備好把它運回去了，就等我們發出信號。\n\n在四周放置這些信號彈，讓他知道我們已經準備就緒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28623] = {title = "往西前進", objective = "到奧丹姆的奈斐賽特城郊區向法歐瑞斯王回報。", description = "我們在這兒的工作結束了，<name>。我們排除萬難，阻止了奈斐賽特對納候姆的野心。\n\n我們不妨加入西進的隊伍，免得他們將功勞全攬在自己身上。\n\n他們現在應該已經抵達了奈斐賽特城郊區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28624] = {title = "基爾拉姆的自傲", objective = "與迪滋‧岩偷交談。", description = "呿!我看到的只有粗糙與笨重!\n\n你需要的不只是力量。我的斧頭力量跟莉莉絲的釘錘一樣大，但是卻這麼鋒利，我可以一斧就砍斷一棵樹!\n\n你沒聽錯，只要一斧!我也會證明給你們看，就在大家面前。去問問迪茲能不能把一棵樹弄進來這裡!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28625] = {title = "砍啊砍", objective = "從霜葉樹人身上收集10片新伐的霜木。", description = "我有豐富的木材可供買賣，但一整棵樹？那可真是種新鮮的商品。就像那些巨礫一樣稀奇。\n\n或許你可以幫我另一個忙。城鎮西邊有一片可以俯視凱斯利爾湖的樹林。我不知道是因為那裡太嚇人，還是那個地方整個灑滿了精靈的魔法垃圾，總之最近那裡到處都有樹人跟鞭尾蠍在遊蕩。\n\n他們對於那片樹林的伐木產業造成很大的損傷，所以，你何不去那邊砍掉一些呢？從樹人身上帶些木頭回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "剁剁砍砍長靴樹人樹皮輕鞋岩偷頭盔霜葉指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28626] = {title = "運送樹木", objective = "將超級速成樹帶去永望鎮的旅店遞交給基爾拉姆。", description = "來，拿去吧，有80%是用天然成份製造而成的超級速成樹!\n\n沒有根，不髒亂，不吵鬧。把這個拿給基爾拉姆，在他使用的時候務必讓他站遠一點。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28627] = {title = "瑟里爾的自傲", objective = "與迪滋‧岩偷交談。", description = "真是粗暴又不專業。\n\n如果你的武器揮舞起來像個笨重的巨魔，那它多鋒利或力量多強都不是重點。我可以一次又一次的強調技巧跟速度跟平衡跟操控性...但最容易的方式還是讓這些笨蛋開一次眼界。\n\n告訴迪茲我們還要再跟他下個訂單，我需要一大塊冰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28628] = {title = "運送冰塊", objective = "將速成冰磚帶去永望鎮遞交給瑟里爾‧天譴剋星。", description = "好了，一塊高品質、等級精純的速成冰磚！\n\n有段時間我試著把這些東西當做護甲賣給人們。你知道，就像你所看過法師玩的那些把戲？不過會導致使用者無法呼吸的問題到現在還無法克服。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "輕盈的莉莉絲的小錘基爾拉姆的殺手斧天譴剋星之劍天譴剋星分割刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][28629] = {title = "我們到了沒，雪人?", objective = "從冰薊雪人身上收集10張厚雪人毛皮。", description = "我的朋友們總是能想出很棒的點子。我從來不覺得自己能和他們並駕齊驅...直到今天!我剛擬訂了一些很棒的計畫!如果你保證不告訴別人，我就讓你參與這個秘密...\n\n我要打造一個機器雪人!我的朋友看到時肯定會嚇一跳。不只如此，等他們反應過來後，還會非常佩服我!\n\n我需要冰薊雪人身上的厚雪人毛皮。在冰薊嶺東南方有一票冰薊雪人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28630] = {title = "回音三號", objective = "尋找回音三號。", description = "最近很多哥布林在冰薊嶺裡消失了。我差一點也是其中一位！\n\n我原本是想架設一支感應器，用來在雪人接近永望鎮的時候通報我們。當然，這也沒有效果。山丘上滿是雪人，但我從沒聽到感應器響過一聲。\n\n你能幫我去查看一下嗎？或許還能修得好。回音三號就設置在冰薊嶺東南方邊緣的地方。不要問我回音一號和二號發生了什麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28631] = {title = "完美的一對角", objective = "取得撞冰完美的雙角。", description = "我無法做出沒有角的雪人!\n\n我感覺像是花了無盡的時間來尋找一對完美的角...但我找到的都不夠好!然而幾天前我看到冬泉谷裡最大的雪人。\n\n我將牠命名為撞冰。牠頭上的角就是我一直在尋找的!牠棲息在冰薊嶺東邊邊緣的洞穴最深處。\n\n將它的一對角帶給我...但記得在路上去看一下回音三號!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28632] = {title = "山丘鮮採", objective = "到冰薊嶺的山洞中收集7片純淨的冰川冰塊。", description = "這次是冰？唉唷喂呀，當然了，我有好消息也有壞消息要告訴你。\n\n好消息是，就在永望鎮東方的冰薊嶺的山洞裡，有一大團精純而堅硬的冰。壞消息是那裡也有一大群兇惡的雪人。\n\n不過如果你能料理那些雪人，嘿，事情就簡單得很！只要走到最大的那團冰上面，用你的武器敲開它們。把冰帶回來，我會做我該做的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28633] = {title = "應許法櫃", objective = "將應許法櫃內的東西交給布萊恩‧銅鬚。", description = "我不知道接下來會發生什麼，你最好做好準備，嗯？\n\n這些密碼將揭露法櫃的真正用途，並給我們工具阻止死亡之翼對奧丹姆的野心！\n\n退後點！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28634] = {title = "滅絕", objective = "消滅12隻狂暴的梟獸。", description = "梟獸...沒有靈魂的長羽毛怪物，從扭曲的虛空深淵裡出來，補食弱小。\n\n<尼爾斯指指圍繞東點哨塔的林子。>\n\n他們從四面八方包圍著我們，計畫發動攻擊!我感覺得到。你必須在他們組織完成之前阻止他們。\n\n我要你進森林裡去殺了被你看見的所有梟獸。一隻都不留!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28635] = {title = "希爾斯布萊德鬧鬼事件", objective = "尋找丹加洛克鬧鬼的證據。", description = "丹加洛克之戰是全希爾斯布萊德戰役裡最慘烈的。矮人們以一擋十、奮戰到底。他們每一個人都是為了保衛家園而喪命。\n\n現在我聽說那個地方鬧鬼了。沒人想靠近那裡！不幸的是，我受命要把丹加洛克整頓成能給人居住的地方。\n\n你能幫我去丹加洛克找出鬧鬼的證據嗎？它就位於東南邊的遠處。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28636] = {title = "矮人的沉默", objective = "消滅10個丹加洛克鬼魂。", description = "我們士兵的魂魄在這個堡壘裡作祟，<小夥子/小姑娘>。他們的靈魂被束縛在此。即使在死後，他們也繼續為它而戰。令人難過。\n\n幫他們脫離這悲慘的命運，也許你能拿到你們的獎賞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "陰魂作祟披肩海德先生的護腕不屈之握陰森預感護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][28637] = {title = "熊肉的滋味", objective = "殺死15隻裂齒熊。", description = "你有沒有嚐試過熊肉的奢侈滋味？我在吉爾尼斯的時候從來沒機會試試，但這裡的熊真是絕妙非常。\n\n在南方閒晃的裂齒熊脂肪分布就像大理石的紋路一樣。我曾親自獵捕牠們，非常有趣，不過我更愛吃掉牠們！\n\n我建議你去試試身手，狩獵牠們。鎖定白毛的裂齒熊，隊長會到野地裡去把你獵殺的任何獵物都帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28638] = {title = "在貓頭鷹手上", objective = "殺死15隻冬泉巨梟。", description = "我一輩子都在吃貓頭鷹。貓頭鷹很好吃，我的朋友傑茲也同意這一點。我是第一個叫他賣貓頭鷹的人!\n\n花褲子的狼人先生說熊肉的滋味比較好，不過不用理會他。你應該去幫自己抓一些貓頭鷹。在南方有一些貓頭鷹四處逡巡。特別注意灰色的貓頭鷹，等你收集到一些貓頭鷹之後，利用愛講話的傑茲給你的那個蜂鳴器通知我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28639] = {title = "尤西烏斯", objective = "殺死尤西烏斯。", description = "我曾經聽人家說，你吃什麼就像什麼。我不知道我信不信這一套，但如果是真的...我會比較想吃掉我所能找到最強壯的生物。\n\n尤西烏斯是冬泉谷最巨大的熊。牠所領導的裂齒熊群帶回奇美拉或梟羽時，牠總是第一個進食。牠住在裂齒保留地區中最舒服的洞穴裡。而且牠...對於裂齒母熊具有強大的影響力。\n\n牠就是熊族中的我。\n\n我想要吃了牠。\n\n牠的山洞位置就在裂齒暴熊附近。祝你好運!您會收到：\n\n", progress = nil, completion = nil, rewards = "裂齒手套尤西烏斯的軟帽上熊油的鎖甲護胸可觀影響護腕莫爾考特的弓您會收到：\n\n尤西烏斯腰肉"}
MultiLanguageQuestData['tw'][28640] = {title = "新鮮的霜刃豹", objective = "殺死15隻霜刃豹或霜刃捕食者。", description = "聞起來是不是很棒？我的煙燻肉是價錢最高的，而且這整個山丘，除了我以外沒人能提供這種異國風味。讓我們採取有效率的做法吧。你負責狩獵並賺取一點賞金，而我其他的好朋友把野獸拖回來剝皮燻製！\n\n我現在已經壟斷了霜刃豹肉的交易市場。百分之百好吃的原料，可以做成極佳的香腸。到西邊去獵捕那些貓咪，這是第一步！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28641] = {title = "晚餐桌上的驕傲", objective = "殺死15隻霜刃雌豹或霜刃守衛者。", description = "好了孩子，該是深入荒原的時候了!\n\n這批收穫的品質很好，不過再往西走，你會找到體型大上許多的貓咪。這些驕傲的守衛者與雌豹身上有更多的肌肉，可以做出「不可思議」的漢堡肉。它們可以用瘋狂的價格賣出!\n\n等你把這件事辦完我們再看你能不能搞定最主要的問題。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28642] = {title = "Shy-Rotam", objective = "Storm Shadowhoof at Everlook in Winterspring wants you to defeat Shy-Rotam.", description = "In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam. Defeating the matriarch of the frostsabers would grant you much respect in the eyes of your fellow <race>.\n\nGo again to the harsh wilds, and once there, gather sacred meat from the frostsabers. Find the stone of Shy-Rotam, and place it there. Placing the meat of her kin before her will summon Shy-Rotam, in anger.\n\nBe ready for her fury, and defeat her.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "獸巡者之刃獵獸匕首您會收到：\n\n"}
MultiLanguageQuestData['tw'][28643] = {title = "敦霍爾德的挑戰:賽佛路斯", objective = "殺死賽佛路斯。", description = "敦霍爾德城堡一直是個征戰不休的地方。多年來，人類將它當成放置獸人的集中營和監獄。在那之後，辛迪加佔據了它。現在？黑暗女王佔領並在其中放置了強力的元素。她賦予我管理「敦霍爾德擂台」的責任。任何能夠擊敗所有元素的人都將獲得極大的獎賞！收下這份導引，面對你最初的挑戰：賽佛路斯吧！\n\n敦霍爾德就在我們的東北方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28644] = {title = "敦霍爾德的挑戰:泰拉古拉", objective = "殺死泰拉古拉。", description = "根據這份導引，泰拉古拉就是你下一次挑戰的對象。它就漫遊在賽佛路斯巢穴外面的道路上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28645] = {title = "敦霍爾德的挑戰:血毒", objective = "殺死血毒。", description = "根據這份導引，血毒就是你下一次挑戰的對象。這可懼的元素就位於敦霍爾德城堡的低層。靠近西邊的監獄區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28646] = {title = "敦霍爾德的挑戰:因弗努斯", objective = "殺死因弗努斯。", description = "根據這份導引，因弗努斯就是你下一次挑戰的對象。這元素是熔岩和狂暴火焰構成的存在，它位於敦霍爾德城堡的低層。靠近東邊的監獄區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28647] = {title = "敦霍爾德的挑戰:D-1000", objective = "殺死D-1000。", description = "在古老敦霍爾德城堡競技場之中，囚禁著純粹水銀組成的生物。被遺忘者稱它為D-1000。殺死D-1000並取得你的獎勵!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "審判日之斧不連續之錘D-1000戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][28648] = {title = "Frak's Wild Ride", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28649] = {title = "特殊的驚喜", objective = "赤紅之焰禮拜堂的騎士指揮官瘟疫之拳命令你處決哈佛領主，附近監獄裡的一名銀色黎明囚犯。", description = "我們拆了這整個地方，然後朝監獄建築前進。我們完全沒想到會遇見這種情況，<name>。看來十字軍很忙啊。那裡整個塞滿了銀色黎明的囚犯。我們抵達時大多數囚犯都死了，但少數幾個還有呼吸。\n\n我本來打算過去那裡，處決剩下的傢伙，但我想該把這份榮譽讓給你。特別是，那裡有個特別精力充沛的狼人，我想你會很樂於處決掉的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28650] = {title = "特殊的驚喜", objective = "赤紅之焰禮拜堂的騎士指揮官瘟疫之拳命令你處決蓋里‧朗普史丹，附近監獄裡的一名銀色黎明囚犯。", description = "我們拆了這整個地方，然後朝監獄建築前進。我們完全沒想到會遇見這種情況，<name>。看來十字軍很忙啊。那裡整個塞滿了銀色黎明的囚犯。我們抵達時大多數囚犯都死了，但少數幾個還有呼吸。\n\n我本來打算過去那裡，處決剩下的傢伙，但我想該把這份榮譽讓給你。特別是，那裡有個特別精力充沛的哥布林，我想你會很樂於處決掉的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28651] = {title = "新兵艾蕾絲", objective = "到提里斯法林地的喪鐘鎮和新兵艾蕾絲談談。", description = "你何不去找我的學徒艾蕾絲談談？她聽命於我，應該能提供你一些工作，好讓你運用新習得的技能。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28652] = {title = "管理員凱斯", objective = "到提里斯法林地的喪鐘鎮墓地和管理員凱斯談談。", description = "我已經沒事要麻煩你了。不過還有其他人用得上你。\n\n站在我後面那個樹樁前的管理員凱斯或許可以給你另一項任務。你應該立刻過去跟他談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28653] = {title = "暗影牧師薩維斯", objective = "到提里斯法林地的喪鐘鎮和暗影牧師薩維斯談談。", description = "你在聽嗎，<name>?你知道的，我只是個亡靈守衛。我手上沒有太多的工作可以交付給像你這樣的路人。\n\n我建議你去找暗影牧師薩維斯。我記得，在我從那墳墓醒來後，是他幫助我重新出發的。我相信他也一樣會幫你。\n\n你可以在城鎮西側的教堂內找到他。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28654] = {title = "問題核心", objective = "布萊恩‧銅鬚要你到起源大廳和他碰面。", description = "好吧，<小夥子/小姑娘>，有一半的我想繼續待在這兒，看你大展身手。\n\n我從前也見過一些了不起的事，不過跟你一比全都是小兒科。\n\n可惜的是，我得在進入起源大廳之前好好研究一下這些圓盤。\n\n你挺有本事的，何不跟著我，看看一個真正的考古學家是怎麼工作的，嗯?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28655] = {title = "野蠻、狂野的蠻錘婚禮", objective = "和格蘭地‧麥葛拉夫交談以開始進行婚禮儀式。殺死任何試圖阻止婚禮的暮光之錘!", description = "我們準備好開始了，<name>！\n\n不過根據可靠消息指出，暮光之錘可能會試著干擾婚禮儀式，藉以打擊並摧毀蠻錘部族。狀況可能會變得非常危險！\n\n因此，我將會親自主持婚禮儀式，好讓新娘和新郎可以待在靠近我的地方。聽起來像是個好計畫吧？很好！\n\n由於她的父親已經過世，而她的兄弟又是伴郎，芬妮要你負責陪在她身邊一起走下來。多麼光榮啊！當你準備好開始時，和我交談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28656] = {title = "古怪的生命力", objective = "到冬泉谷的雪山農舍去和巫醫瑪艾里交談。", description = "當這個生物死亡的瞬間，某種能量從牠的身體釋放出來。這股能量朝向你而來，不知為何你感到自己變得強壯了點。\n\n根據冬泉谷當地居民的說法，雪山農舍的巫醫瑪艾里是這個地區野生動物的專家。她或許知道有關這股神秘力量的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28657] = {title = "天大的問題", objective = "你受命殺死普拉卜林姆，漫遊在托巴拉德道路上的雙頭巨人。", description = "我們終於奪得這個被神遺棄的石頭，卻發現有個雙頭巨人在四處漫遊，放倒我們的巡邏哨兵!\n\n<name>，我需要你召集幾位朋友，解決掉雙頭巨人。我們不能讓這種野獸到處撒野，製造破壞。保持警覺，根據前線情報，雙頭巨人拿著一顆天大的樹當武器，而且毫不在意的使用它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28658] = {title = "沼澤的誘餌", objective = "你受命從托巴拉德的巴拉丁鱷魚身上收集到8張鱷魚皮。你可以在巴拉丁堡西方的沼澤找到鱷魚。", description = "在這種地方找到補給向來不是件容易的事。<class>。我們從佔領這個島嶼開始就一直搜索，但情況一直都很不妙。\n\n幸運的是，我們剛接到偵察情報指出，在我們的營地的西方有一個充滿鱷魚的沼澤。鱷魚皮會對我們的皮革製造者很有用的。能帶回多少就帶回多少吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28659] = {title = "善後工作", objective = "你受命殺死在托巴拉德的12位聯盟步兵。你可以在托巴拉德的熔渣處理場、看守者崗哨和鐵甲要塞找到他們的藏匿處。", description = "我們經歷了一番奮鬥才拿下這個島嶼，<race>。我們清除了大部分的聯盟雜碎，但我還是聞得到他們在空氣中留下的一絲穢氣。\n\n我需要你調查熔渣處理場、看守者崗哨和鐵甲要塞。將所找到的任何聯盟兵殺死。\n\n你知道他們常說的，唯有死去的聯盟才是好聯盟!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28660] = {title = "清理深淵", objective = "你被要求要到巴拉丁堡東邊的詛咒深淵去殺死9個鬼魂。", description = "看見你真好啊，<name>。雖然我們拿下了托巴拉德，但是戰鬥才正要開始而已。\n\n我們在東邊發現了一區牢房，需要你去清理一下。有一大群鬼魂塞在裡頭，天曉得他們已經被鎖在那裡多久了。\n\n盡你所能把那裡清乾淨，完成之後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28661] = {title = "被監禁的大法師", objective = "你必須到巴拉丁堡東邊的詛咒深淵去，殺死大法師加魯斯並把他的法杖帶回來。", description = "我們到達托巴拉德之後，就一直嘗試要清理詛咒深淵的牢房。每次我們快完成目標的時候，就會出現一個大法師把我們逼退回來。\n\n現在我們已經取得這個島嶼，是再嘗試一次的時候了。到那裡去，把他的法杖帶回來給我，證明你已經完成工作。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28662] = {title = "從經驗中學習", objective = "你被要求要到巴拉丁堡東邊的詛咒深淵去取回4本布滿灰塵的監獄日誌。", description = "現在我們終於在這個荒涼的島嶼上有座堡壘了。我們可以開始調查為什麼它會落到現在這個地步。我們有些部隊在東邊的詛咒深淵牢房入口處附近發現一些日誌。\n\n這些日誌非常吸引我們營區裡的資深抄寫員。我需要你儘快去帶四本回來給我。\n\n<name>，在那裡要小心，那邊到處爬滿了不死怪物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28663] = {title = "D區", objective = "你接到指示要到巴拉丁堡西北邊的D區去殺死任10個惡魔。", description = "<name>，你有聽過D區嗎？那是這個島上的一座古老牢房。問題在於，那裡頭有惡魔成群出沒。我們打算把在這座島上找到的殘餘聯盟士兵關在那裡，但以目前的狀況來說不可能辦到。\n\n我需要你到那裡去把那些惡魔清光。完成之後來向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28664] = {title = "斯瓦爾諾斯", objective = "你必須到D區去殺死斯瓦爾諾斯並把牠的詛咒項圈帶回來。你可以在巴拉丁堡西北邊的D區裡面找到斯瓦爾諾斯。", description = "你把攻占島嶼的工作做得很好，<class>。取得了島嶼之後，我們必須讓牢房可以用來關囚犯。D區一直都特別難清理。不幸的是它裡面還充滿了各式各樣的惡魔。\n\n我們已經削減了惡魔的數量，但有一隻巨大的熔核犬衝出了籠子，在底下造成巨大破壞。我需要你去殺了牠並把牠的項圈帶回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28665] = {title = "被詛咒的鐐銬", objective = "你被要求要到巴拉丁堡西北邊的D區去，找出8副被詛咒的鐐銬。", description = "<name>，你有下去D區過嗎？每次我們將這個害蟲橫行的牢房清理乾淨，惡魔似乎總是很快就回來。我們發現這些傢伙是從散佈在這個地區裡被詛咒的鐐銬再生出來的。這就是你的工作了，<name>。\n\n我需要你盡量把這些鐐銬找出來並帶回來給我。我們會立刻摧毀它們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28666] = {title = "英雄的召喚：燃燒平原！", objective = "到燃燒平原的燎星崗哨向約翰‧J‧基沙恩報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往燎星崗哨向約翰‧J‧基沙恩報到。\n\n那裡急需你的幫助來終結黑石獸人的威脅！\n\n你可以從灼熱峽谷出發，往南穿越黑石山來抵達燃燒平原。在山脈的另一端尋找燎星崗哨。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28667] = {title = "大酋長的命令：燃燒平原！", objective = "到燃燒平原的燎星崗哨向阿利歐克報到。", description = "所有身強體壯的部落成員，都在此受命前往燎星崗哨向阿利歐克報到。\n\n可敬的伊崔格之子阿利歐克需要你的幫助來阻止黑石獸人對周遭區域發動盲目的入侵。\n\n你可以從灼熱峽谷出發，往南穿越黑石山來抵達燃燒平原。燎星崗哨會在山脈的南方。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28668] = {title = "監獄造反", objective = "你受命在巴拉丁堡西南方的大坑裡殺死任何10位囚犯。", description = "我們攻下整個島嶼了，現在只剩下開始運用這裡的資源。我們在西南方找到了一個被遺棄的監獄分區，需要你過去看一下，<name>。\n\n根據情報，那邊充滿了多年來被關在底下動彈不得的囚犯。盡一切力量把那個地方處理乾淨吧。完成後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28669] = {title = "典獄長", objective = "你必須在大坑殺死典獄長希瓦爾並帶著他的鑰匙回來。大坑就在巴拉丁堡的西南方。", description = "你就快將大坑裡那些反叛的囚犯處理完畢了，但最後還有一個麻煩:典獄長。\n\n典獄長希爾瓦是囚犯的頭目，囚犯為了他什麼都敢做。若我們擊敗他，就等於我們擊敗所有囚犯了。將希爾瓦殺死並帶回他身上的鑰匙。我們可以用那些鑰匙更深入監獄地區，而且也許可以找到這個島嶼的水源補給。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28670] = {title = "下方來的補給", objective = "你受命從大坑取回12份監獄口糧，就在巴拉丁堡的西南方。", description = "營地的補給品已經快沒有了，<name>。我們最近得知西南方的監獄地區有足供我們用好幾年的口糧存貨。我們需要你去收集口糧，盡你所能搬越多回來營地越好。\n\n還有一件事，整個監獄地區充斥著囚犯，所以請小心。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28671] = {title = "大酋長的命令：詛咒之地！", objective = "到詛咒之地的巨槌要塞向歐克里拉報到。", description = "所有身強體壯的部落成員，都在此受命前往巨槌要塞向歐克里拉報到。\n\n歐克里拉是部落位於巨槌要塞的指揮官，需要你的幫助才能在叛亂巨魔和聯盟軍隊之間固守哨站。\n\n順著悲傷沼澤南邊的道路往南走來抵達巨槌要塞。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28672] = {title = "戰地執行官", objective = "找執行官阿倫報告。", description = "我可以讓你在鎮上忙一整個星期...不過你看起來似乎比較適合戰鬥。\n\n<艾蕾絲看了看你，點點頭。>\n\n是的，你會很合用的。我希望你去和執行官阿倫談談。順著北方的小路走出喪鐘鎮。你可以在越過路障不遠處找到他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28673] = {title = "英雄的召喚：詛咒之地！", objective = "到守望堡向軍需官朗格爾斯報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往守望堡向軍需官朗格爾斯報到。\n\n守望堡的駐軍急需你的幫助來抵擋部落對詛咒之地的進逼！從悲傷沼澤出發往南邊走，順著道路往東抵達守望堡。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28674] = {title = "墜星村", objective = "到墜星村與威恩德‧夜風說話。", description = "你在這裡忙好一會兒啦。若你還積極的想繼續做好事，或想賺點錢，我有你可能會有興趣的差事。\n\n墜星村就在永望鎮的西北方。那裡的夜精靈最近遭受一種頗棘手的昆蟲感染，目前他們正四處要求協助。\n\n有幾位哥布林已經過去除蟲了，但我相信那裡還有更多除蟲的需要。去找威恩德‧夜風說話，他會提供你該知道的訊息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28675] = {title = "英雄的召喚：悲傷沼澤！", objective = "到悲傷沼澤的沼槳向貿易巨商銀鉗報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往沼槳向貿易巨商銀鉗報到。\n\n聯盟部隊急需他所提供的軍火！你必須利用一切手段來說服貿易巨商繼續用合理價格將軍火賣給我們。\n\n要前往沼澤，順著燃燒平原東南邊的道路穿過赤脊山。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28676] = {title = "驅蟲專家出動", objective = "到班薩羅獸穴裡與里諾‧彈幕說話。", description = "發生在我們獸穴的這一波昆蟲感染幾乎是在一夕之間發生的。以往從未出現在這片土地上的凶暴生物充斥著整個隧道，從沒見過的蛋裡破殼而出。\n\n我們只有這麼幾個人，能做的就只是將感染維持在獸穴裡面不往外擴。因情勢所逼我們雇請了永望鎮自稱是驅蟲專家的哥布林，但目前為止，他們還沒成功地驅除昆蟲。\n\n如果你願意協助他們，從這小屋的西邊進入獸穴並與里諾‧彈幕說話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28677] = {title = "大酋長的命令：悲傷沼澤！", objective = "到悲傷沼澤的沼槳向貿易巨商銀鉗報到。", description = "所有身強體壯的部落成員，都在此受命前往沼槳向貿易巨商銀鉗報到。\n\n說服貿易巨商繼續替我們的戰士提供兵器和彈藥的必須補給，不論需要什麼代價或手段！\n\n順著燃燒平原東南部那條穿越赤脊山的道路走，以前往悲傷沼澤並在貿易巨商的海濱樂園碰面。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28678] = {title = "哈利斯船長", objective = "你接到在逝望角殺死哈利斯船長的任務。你可以沿著海岸往南邊的方向走來找到逝望角。只要搜尋船骸就可以看到了。", description = "這幾個禮拜以來，逝望角真像是我們托巴拉德背後的一根芒刺。一半以上的貨船都沉在了下面的大石塊那裡。\n\n更糟的是，現在那裡被一些不死族水手佔領了。我們試著處理過，但他們一直重複出現。我們最後的招數就是想辦法解決他們曾提過的船長。你應該可以在岸邊的一艘船上找到他。\n\n喔，希望你不會對鯊魚感到恐懼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28679] = {title = "激怒他們", objective = "三副克隆卡要你到逝望角殺死8個海難水手。逝望角就在西北方的海灘。", description = "逝望角的不死族困擾了我們好一陣子。每次一發生船難，就有更多不死族加入他們。\n\n可以請你幫我們個忙，到那裡去削弱他們的數量嗎？我知道你沒辦法殺光他們，但不論你做了多少，都聊勝於無。\n\n要小心聯盟，我們接到許多報告，發現他們最近常在海灘埋伏。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28680] = {title = "激勵士氣", objective = "你被要求要到逝望角去找6桶南海蘭姆酒。這個海角在北方的海岸邊。", description = "<name>，我們的士氣現在很低落。我們已盡了一切努力想讓部隊的鬥志高昂，但用來支持士氣的重要補給品已經日漸短缺…那補給品就是萊姆酒。\n\n我收到一份南方步兵傳回來的報告，在逝望角岸邊有艘發生船難的船，它的船體殘骸上仍有品質很好的南海蘭姆酒存貨。你可以去調查一下嗎？\n\n把你能找到的蘭姆酒全帶回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28681] = {title = "鯊魚坦克", objective = "你被賦予殺死坦克的任務。坦克是一隻在逝望角海域逡巡的巨大鯊魚。這個海角位於北方，沿北邊的海岸線走就可以找到。", description = "我恨鯊魚。我所有的部隊成員也一樣。這就是你來派上用場的地方，<name>。\n\n我需要你到逝望角去宰了一隻名叫坦克的大鯊魚。不要太輕視坦克，如果我是你，我會帶幾個朋友一起去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28682] = {title = "取得城堡", objective = "你被賦予到法森堡去殺死堡主法森的任務。你可以在島嶼北方找到法森堡。", description = "<name>，你有看到島嶼北方的那棟城堡嗎？那裡就是堡主法森坐鎮指揮的地方。\n\n法森擁有一群為他獻身的追隨者，而那些人從我們一到這裡之後就不停的找我們麻煩。我們派了一個小隊進去偵察，他們也回報了城堡中法森所在的精確位置。\n\n你可以去幫我們解決掉他嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28683] = {title = "削減蛛群", objective = "到暗木森林中去殺死12隻暗木蜘蛛。暗木森林就在北邊，越過橋往島嶼中心走。", description = "我們幾個星期以來一直試著要攻下暗木森林裡的一個堡壘，但那個森林裡有大批蜘蛛出沒。幫我個忙，看看你能不能減少牠們的數量，好讓我們能進行攻擊。\n\n在那裡要小心，我聽到報告說本週稍早時，聯盟的部隊也在那附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28684] = {title = "黏答答任務", objective = "到暗木森林去從暗木森林育母身上收集4個粘絲腺體。暗木森林就在西邊，越過橋往島嶼中心走。", description = "在這個島嶼找補給品可以說是非常困難。\n\n幸好，我們在北邊的暗木森林裡找到一種很好的絲。壞消息是這種絲是從育母蜘蛛的腺體中分泌出來的。我需要你去幫我拿4個腺體。\n\n這應該就足以完成最後一批襯衫了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28685] = {title = "別留下武器", objective = "到托巴拉德半島北方的法森堡取回12隻生鏽的步槍。", description = "身處在這座岩島上很難取得戰爭補給品。每當我們又再一次阻擋了聯盟的攻擊，都會覺得自己是用樹枝與石頭在作戰。\n\n有報告指出，島嶼北方的堡主法森有很豐富的步槍庫存，我們可以拿來使用。你能到那裡去確認一下嗎？\n\n小心，<name>，法森的追隨者為了保護它會無所不用其極。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28686] = {title = "不是最友善的城鎮", objective = "指揮官拉瑪胥要你去鏽堡村殺死14個村民。鏽堡村在營地南邊，就在右手邊的位置。", description = "<name>，你有去過鏽堡村嗎？如果你要往那個方向走，我建議你在身上帶把磨利的尖刀。\n\n那個城鎮的人們表面上看起來很好，但有些可疑的事情正在那裡進行。根據回報指出，他們正在消滅我們附近的士兵。我們已經受夠了，所以我需要你去那裡幫我們清掃一下。\n\n盡你所能殺光他們，完成之後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28687] = {title = "教他釣魚...或用偷的", objective = "你必須到鏽堡村去取得22份鏽堡村海鱸。你可以在村莊後方的碼頭的帶狀區域找到魚。鏽堡村在營地北邊，就在右手邊的位置。", description = "鏽堡村。那個地方是我們的詛咒也是祝福，<name>。我不知道那些暴徒是怎麼學會像那樣抓魚的，但我現在沒時間擔心那個。\n\n我需要你到那裡去，儘可能把他們的魚貨偷來。自從我們收復這座島嶼就一直以吃殘渣維生，這是我們能取得真正食物的最佳機會。\n\n在那裡要特別留意潛行者，報告指出他們遍佈在村落的牆壁裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28688] = {title = "大酋長的命令：北荊棘谷！", objective = "到北荊棘谷的格羅姆高營地向指揮官阿格羅戈西報到。", description = "所有身強體壯的部落成員，都在此受命前往格羅姆高營地向指揮官阿格羅戈西報到。指揮官需要你幫忙確保補給線不受當地居民與麻煩的聯盟妨礙。\n\n要前往格羅姆高營地，你可以在奧格瑪東邊或幽暗城附近的高塔乘坐飛行船。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28689] = {title = "遺民", objective = "到遺忘之丘去解放6個受折磨的靈魂。你可以藉由直接觸碰墓碑來引導靈魂。遺忘之丘就在越過無寧前線西方的位置。", description = "許多士兵死在這個島嶼上，<name>。我們應當用任何可能的方式來向他們表達敬意。\n\n我需要你到西邊的遺忘之丘去，將我們好弟兄受折磨的靈魂從這片土地解放。在那裡務必要小心，據報那個區域仍有不死生物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28690] = {title = "收集肢體", objective = "你得從居住在遺忘之丘的食屍鬼那裡取回9根受詛咒的腿骨。遺忘之丘在島嶼西方，就在越過無寧前線之後。", description = "在我們收復遺忘之丘以來，這個悲慘的島嶼一直都有殭屍與食屍鬼四處橫行。我們試過很多次要把他們清除掉，但他們似乎總是會跑回來。\n\n我們的一個中尉建議我們在殺掉這些食屍鬼時把骨頭拿走，希望這樣他們就無法在晚上復活。我想你能到外面去幫我們這個忙？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28691] = {title = "科諾爾中尉", objective = "到遺忘之丘找出科諾爾中尉並殺了他。你會在遙遠的島嶼西邊找到遺忘之丘。", description = "我第一次聽到科諾爾中尉這個名字時還只是怒焰裂谷的一個新兵。沒人相信他最後會到托巴拉德來。很不幸，他仍舊在這幾座悲慘的島嶼上漫遊，對我們的部隊士氣造成嚴重打擊。\n\n我需要你去結束他的苦難...以及我們的苦難。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28692] = {title = "磁鐵，要怎麼用？", objective = "你被賦予找出7片攻城機具碎塊的任務。到無寧前線去利用磁化廢金屬收集器找出碎塊。無寧前線在西方，越過第二座橋的地方。", description = "要在這個島上取得有用的機械零件非常困難，<name>。我們試著要修復營地裡的攻城機具，但我們一直缺少可用的零件。\n\n我們的第二軍團報告說西邊的古戰場裡有一些壞掉的攻城機具。或許我們能在那裡找到一些零件？\n\n要在那個古戰場裡找東西對你來說會有點麻煩，所以帶著這個磁化廢金屬收集器，好好的運用它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28693] = {title = "完成工作", objective = "到無寧前線去殺死5個焦躁的步兵。你可以在島嶼西邊找到這個前線，就在遺忘之丘前方。", description = "我們整星期都在嘗試從前線收集一些有用的碎塊。每次我們收集到一批碎塊要帶回營地，就會被這個地區的焦躁的步兵攻擊。你能不能到那裡去把他們除掉？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28694] = {title = "小心木刺!", objective = "士兵薩洛斯克要求你到維爾森船廠去取回15片船廠木材。你可以從船廠鬼魂的身上取得木材，或是在船廠場地裡的各處撿到。船廠位於西北方的海岸邊。", description = "<name>，你有去過維爾森船廠嗎？除非你有很好的理由，不然最好離那裡遠點。很不幸的，這正好是我要你進去的地方。\n\n你知道的，我們收復這座島嶼之後補給品一直處在短缺狀態。這個被鬼魂支配的船廠裡頭滿滿的都是木材，但每次我們派護衛隊去取那些木材，他們都沒有活著回來。\n\n你能幫幫我們嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28695] = {title = "通緝:工頭維爾森", objective = "到維爾森船廠去殺死工頭維爾森。船廠位於北方，海岸的西邊。", description = "自從我們來到這裡，工頭維爾森就一直是我們的肉中刺。他的船廠中有大量的補給品，這些東西對我們來說非常有用...如果我們拿得到的話。\n\n他嚴密的監視他的走狗，讓我們難以在船廠中建立據點。我需要你立刻殺死維爾森。小心點，<name>，我們接獲報告，這個區域裡到處都有骯髒的聯盟。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28696] = {title = "盡情轟炸!", objective = "摧毀10艘恐怖的補給艇。", description = "維爾森船廠不斷從近海接收補給品，這種事情不能再發生了。他們沿著甲板裝設了加農砲作為防禦，但要是你能接近大砲，我們就可以用大砲來毀掉他們的補給船。\n\n去看看你能做些什麼。回來向我報告你的進度。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28697] = {title = "魔鬼剋星", objective = "到部落營地東北邊的拉爾戈瞰臺去殺死14個鬼魂。", description = "看到我們營區東北邊，那座豎著哨塔的山丘了嗎？那是拉爾戈瞰臺，在那地方旁邊設置營地可不是件好玩的事。打從建造營地那時候起，我們就一直在處理那些靈魂與幽靈的事情。\n\n你能不能過去那裡，讓它們知道我們還要待上好一段時間？衝進去大開殺戒一番應該能讓它們搞清楚狀況。\n\n謝謝你肯幫這個忙，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28698] = {title = "砲彈!", objective = "你必須幫士兵薩洛斯克從拉爾戈瞰臺取回4堆砲彈。你可以在營區東北邊找到拉爾戈瞰臺。", description = "自從我們在這裡設立營地之後，拉爾戈和他的走狗常常跑來偷走我們的補給品。可以說是讓人非常懊惱。\n\n我們接過報告指出他正在監督水邊哨塔的儲存砲彈工作。你可以到那裡去試著幫我們帶一些砲彈回來嗎？ \n\n<name>，別忘了小心注意聯盟的蹤跡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28699] = {title = "英雄的召喚：北荊棘谷！", objective = "到北荊棘谷的反抗軍營地向多倫中尉報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往反抗軍營地向多倫中尉報到。\n\n在庫爾森上校背叛暴風城的多年之後，事情的真相依然隱晦不明。幫助那些生還者查明上校現在的狀況。從暮色森林往南走，進入叢林地帶之後順著道路往西，就可以到達反抗軍營地。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28700] = {title = "收復瞰臺", objective = "士兵薩洛斯克要你到拉爾戈瞰臺去殺死指揮官拉爾戈。瞰臺就在營地的東北邊。", description = "只有一個辦法可以收復拉爾戈瞰臺\n\n我想你知道我們該怎麼做，<name>。拉爾戈最近有嚴重的妄想症，所以你可以在塔頂找到他，他在那裡幻想他的部隊最後會到達。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28701] = {title = "遠離危險", objective = "從班薩羅獸穴收穫5件墜星聖物。", description = "幸運的是，當昆蟲感染發生時，並無任何德魯伊在西邊的獸穴沉眠。那地方對我們來說還是神聖的，其深處存放著幾世紀以來從未受過打擾的受祝福的聖物。\n\n儘管我還算信任那幾位哥布林驅蟲專家，但我也...很了解這個種族的習性。請你幫我收回在獸穴裡能找到的任何聖物，並將聖物帶回來給我以防被破壞。聖物就放在甕裡，分散在獸穴壁上的小壁龕裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28702] = {title = "英雄的召喚：荊棘谷海角！", objective = "到荊棘谷海角的探險者協會挖掘場向布朗尼恩‧砍擊報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往探險者協會挖掘場向布朗尼恩‧砍擊報到。\n\n探險者協會遠征隊需要你的幫助來保衛挖掘場不受巨魔的掠奪。從北荊棘谷出發，順著道路往南走到探險者協會挖掘場。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28703] = {title = "踏入我的獸穴", objective = "殺死10隻冷潛狼蛛和5隻冷潛掘地蟲。", description = "我完全想不出那些昆蟲從哪邊來的。最大的可能，應該是災難捲出了一些前所未知的地下巢穴。\n\n但在眼前有這些蟲子需要消滅的時候，沒必要分心去猜測這件事!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28704] = {title = "大酋長的命令：荊棘谷海角！", objective = "到荊棘谷海角的硬心藏匿處向賽希‧硬心報到。", description = "所有身強體壯的部落成員，都在此受命前往硬心藏匿處向賽希‧硬心報到。她需要你的幫忙，來處理肆虐叢林的海盜與納迦。\n\n從北荊棘谷往南走，在古拉巴什競技場的西南邊尋找那座城鎮。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28705] = {title = "大酋長的命令：外域！", objective = "到地獄火半島的命運階梯向歐萊恩中將報到。\n\n在奧格瑪傳送室的索爾瑪法師可以協助你抵達該地。", description = "所有身體強壯的部落成員，都在此受命前往命運階梯向歐萊恩中將報到。\n\n外域需要你的本事，才能對抗燃燒軍團的殘存兵力。\n\n前往奧格瑪正門的傳送室並與索爾瑪法師交談以前往詛咒之地，然後穿過黑暗之門以抵達命運階梯。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28706] = {title = "向前噴灑", objective = "將盒裝燻蟲器帶去班薩羅獸穴裡面給芮瑪‧彈幕。\n\n已提供物品：\n", description = "我的手足們深入獸穴去處理昆蟲，目前已經快抵擋不住了。我說是時候來燻蒸這個地方啦。這些煙燻器給你。不要自行開啟煙燻器，那需要受過訓練的專家並準確拿捏最恰當的噴灑時間才能這麼做。去找我的姊妹們並將煙燻器分發給她們。\n\n芮瑪應該在最靠近入口的位置。走下通道，並在經過向下的斜坡時靠右。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28707] = {title = "再次噴灑", objective = "將盒裝燻蟲器帶去班薩羅獸穴裡面給瑪西‧彈幕。", description = "我要開始設置這個東西了。\n\n下一個給瑪西，在更進入獸穴的地方。從這個通道走下去，到下一個主房間找她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28708] = {title = "英雄的召喚：外域！", objective = "到地獄火半島的命運階梯向指揮官杜朗報到。\n\n在法師區的榮譽堡法師可以協助你抵達該地。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往地獄火半島向指揮官杜朗報到。\n\n遠征軍需要你的幫助來戰勝燃燒軍團的惡魔部隊！到法師區找榮譽堡塔樓上的法師交談以前往詛咒之地，再穿過黑暗之門以抵達命運階梯。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28709] = {title = "英雄的召喚：北風凍原！", objective = "到北裂境北風凍原的驍勇要塞向招募軍官布里斯報到。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往北裂境北風凍原的驍勇要塞向招募軍官布里斯報到。\n\n驍勇遠征軍需要你的幫助來抵擋天譴軍團的部隊，捍衛文明的國度！前往暴風城碼頭，乘船北航以抵達驍勇要塞。\n\n為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28710] = {title = "再噴灑一次", objective = "將盒裝燻蟲器帶去班薩羅獸穴裡面給莎娜‧彈幕。", description = "我還以為里諾會捨得派遣不止一位<race>下來幫忙我們咧!那個不勞而獲的傢伙...\n\n我要將這東西設置起來。從這房間出發，向北走穿過通道去找薩納。她大概在最後一個房間迷路了，所以到那邊的時候去旁邊的小路找找看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "彈幕披肩燻蒸護腿除害戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][28711] = {title = "大酋長的命令：北風凍原！", objective = "到北風凍原的戰歌堡向戰歌招募軍官報到。", description = "所有身強體壯的部落成員，都在此受命前往戰歌堡向戰歌招募軍官報到。\n\n戰歌進攻部隊需要你的幫助來克服不死天譴軍團的持續威脅。\n\n到奧格瑪西邊的高塔搭乘飛艇前往戰歌堡，並向招募軍官報到。\n\n命運正在召喚著你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28712] = {title = "加入龍后", objective = "在暮光高地的生命之環找到麗菈史卓莎。", description = "哈囉，<race>。我希望我們可以在更好的情況下碰面。這個世界命懸一線，泰坦所精心製造的一切事物都可能滅亡。\n\n雖然我非常悲傷，但是心意已決。死亡之翼，那個曾是大地守護者，也曾是我好友的可怕生物，一定得被摧毀。\n\n我在高地頂上、朱紅壁壘的西邊準備了一個地點，在那裡我將可以終結他的命運。去找到生命之環並且在裡面和麗菈史卓莎交談。我會在那裡加入你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28713] = {title = "自然的平衡", objective = "消滅6隻小夜刃豹。", description = "您好，<name>。我是伊爾薩萊恩。我在幽影谷的任務是訓練像你這樣的年輕<class>們，以確保自然界的平衡得到維持。\n\n今年春季的雨勢特別大，使得森林裡有些野獸在其他動物受難時反而茁壯了起來。不幸的是，夜刃豹數量成長太快，要是不捕殺的話，牠們會毀滅別的族群。\n\n去吧，年輕的<class>，減少夜刃豹的數量，好維護自然界的和諧。", progress = nil, completion = "你完美的達成了任務，&lt;name&gt;。", rewards = "箭術訓練手套樹葉護腕峽谷挑選者之握您會收到：\n\n"}
MultiLanguageQuestData['tw'][28714] = {title = "墮落魔苔", objective = "從伊爾薩萊恩西邊的劣魔那裡收集6個魔苔。", description = "你似乎知道自己在做什麼。也許我可以讓你做一些較為重要的工作。\n\n你或許很清楚，泰達希爾上的腐化理當已被除去才對。但某種事物仍殘留著。生物們並沒有平靜下來，各種問題依然纏繞著我們。\n\n我需要你去處理聚集在西邊的劣魔，當你在這裡時，我希望你能在他們身上搜尋到魔苔。這能幫助我確定持續不斷的腐化是從哪開始的。", progress = "滿足我的疑心吧，<name>。幫我從劣魔那裡帶魔苔回來。", completion = "你為幽影谷的生物所作的事值得獎勵，&lt;name&gt;。然而，你證實了我的恐懼。劣魔們依舊受到魔苔的感染，不受泰達希爾的祝福影響。某種惡毒的東西依然留存在樹木裡。我只希望瘤背部族的熊怪未曾受到這腐化的影響，否則我們就陷入了致命的危機。\n\n我會進一步研究，並聯絡或許有能力提供幫助的人。謝謝你，&lt;class&gt;。", rewards = "布織護腿追蹤之靴藤蔓手套苔蘚包覆鎖甲束褲您會收到：\n\n止血草"}
MultiLanguageQuestData['tw'][28715] = {title = "惡魔小偷", objective = "從西邊的劣魔那裡取回麥利薩爾被偷走的袋子。", description = "惡毒的小劣魔!他們又從我們的食物店裡偷東西。\n\n如果你不介意幫個忙，他們肯定把我遭竊的袋子帶回他們在西邊的營地裡去了。如果你能把它們帶回來給我，我將會非常樂意地給你報酬。", progress = "在取回失竊的貨物之前，我沒有任何多餘的補給品給我的顧客。你還順利嗎?", completion = "讚美伊露恩!也讚美你，年輕的&lt;class&gt;。\n\n有很多年輕的夜精靈需要這些物資，但我也非常樂意給你一個袋子作為報酬。我確定它會很有用的。\n\n祝你旅途平安。", rewards = "您會收到：\n\n麥利薩爾的補給袋"}
MultiLanguageQuestData['tw'][28716] = {title = "英雄的召喚：暮光高地！", objective = "到暴風城的暴風要塞和傑塔瑞斯上將談話。", description = "奉安杜因‧烏瑞恩國王陛下之命，所有身強體壯的聯盟公民，都必須前往暴風要塞的王座廳報到。\n\n國王陛下需要一名可靠、名符其實的英雄去執行一項至關緊要的任務。\n\n暴風要塞就在暴風城的東部區域。\n\n自願者可向傑塔瑞斯上將報到。為了聯盟的光輝與榮耀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28717] = {title = "大酋長的命令：暮光高地！", objective = "到奧格瑪的葛羅瑪許堡向薩魯法爾霸王回報。", description = "所有身強體壯的部落成員，都必須聽命前往葛羅瑪許堡向薩魯法爾霸王報到。\n\n薩魯法爾霸王需要你一同協助，準備對暮光高地發動襲擊，戰勝聯盟和暮光之錘這兩大敵人！\n\n到奧格瑪力量谷中央的葛羅瑪許堡去見他。\n\n命運正在召喚你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28718] = {title = "哪兒在冒煙，哪兒就有好吃的肉", objective = "到冬泉谷的古德古瑞伯煙坑去找傑茲‧古德古瑞伯。", description = "我說啊，<class>…你喜歡吃肉嗎？更好一點，你喜歡錢嗎？\n\n我有個二表哥為了冷凍肉生意在進行獵殺活動。他很想在北邊建立一個燻肉場，同時他正在找人幫忙獵殺那些危險但肉質鮮美的野獸。\n\n肉食動物的價碼很好，朋友。我在這個獸穴已經投資太多了，真不知道我當初在想啥？… 所以我不如指點一下像你這種有幫助的<race>。\n\n他的名字叫傑茲。到東北方去，尋找冒煙的地方！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28719] = {title = "一點野味", objective = "殺死15隻裂齒暴熊。", description = "很多人覺得裂齒熊的味道太腥羶了。我不同意，但我不會去批評其他人的口味。\n\n不過牠們棕色毛皮的表兄弟，也就是南方的裂齒暴熊，肉味就溫和多了，尤其是熊掌的部分。我聽說牠們的軟鼻子也是道好菜。\n\n繼續你的狩獵行動，<name>。看看你能不能幫老法蘭西斯把那些暴熊打包帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28721] = {title = "穿他們的鞋子走一哩路", objective = "護送一名法森堡囚犯到安全的處所。這座堡壘就位於島上的西北端。", description = "在過去幾個禮拜裡，我們派出了至少三支的偵察部隊去調查法森堡的情報。叫人難過的是，沒有任何一支帶著任何資訊回來。\n\n在這種狀況下，我們只能希望他們是被活捉並囚禁了。我需要你滲透進那座堡壘並幫忙救回我們的士兵。那不是簡單的事，<name>，但如果有任何人能幫助我們，那就是你了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n托巴拉德表揚徽章"}
MultiLanguageQuestData['tw'][28722] = {title = "雪人恐懼症", objective = "用烏米的機械雪人嚇萊加奇。", description = "都準備好了，<name>!\n\n我和我朋友萊加奇說我要給她一個驚喜。接著就是你要幫忙的地方啦!\n\n我會把我的機械雪人給你，而你很榮幸的能用它給她一個驚喜。她在永望鎮的另一頭，靠近旅店。\n\n走近她並開啟機械雪人的開關...我會在這邊觀看!您會收到：\n\n", progress = nil, completion = nil, rewards = "永望鎮雪鞋雪人恐懼症頭盔搗蛋鬼手套有趣肩鎧烏米的高超射擊器您會收到：\n\n機械雪人"}
MultiLanguageQuestData['tw'][28723] = {title = "月之女祭司", objective = "在幽影谷中央的兩座池子之間與丹泰莉雅‧銀林交談。", description = "或許你會願意幫我們進一步追捕那些肆虐幽影谷的腐敗力量。\n\n月之女祭司，丹泰莉雅‧銀林，已經答應了要幫忙我們。你應該到我們巨偉之樹北方的兩座池子之間去找她。繞著樹走，你就可以找到她，然後盡你所能的為她提供幫助，年輕的<class>。", progress = nil, completion = "你來了真好。看起來你的訓練進展得很快。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28724] = {title = "埃沃隆的解藥", objective = "收集7株月牙百合花。", description = "我們的朋友埃沃隆中了附近樹林蜘蛛的毒。我可以讓他的狀況不繼續惡化，不過我需要有人去幫忙蒐集一項材料好準備給他的解藥。\n\n在這些池塘附近，你可以找到月牙百合花。這些花具有強大的療效，我可以用它們幫助埃沃隆恢復到較佳的狀態。\n\n你可以幫我收集它們嗎?靠近水池邊的地方應該就可以找到不少。", progress = "即使我為他進行了一些治療，我們親愛的朋友依舊狀況不太好。你有幫我帶來我需要的補給品了嗎?", completion = "這些會很合用的。謝謝你，&lt;name&gt;。感謝你動作這麼迅速。", rewards = "莎草馬褲樹鎧外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][28725] = {title = "森林保衛者", objective = "到幽影谷北端的影絲洞去找名為塔琳德拉的林精。", description = "我必須請你去做一件危險的事。森林中的靈魂透過低語告訴我一些奇怪的消息。神秘的森林保衛者塔琳德拉又回到了幽影谷。\n\n這位林精的身影從泰達希爾得到祝福後就不曾出現過了。既然她回到了這裡，意味著一定有什麼事情不對勁。\n\n到北邊的影絲洞去找塔琳德拉。這很危險，但我們必須預防萬一。", progress = nil, completion = "你找到我了，年輕的&lt;race&gt;。丹泰莉雅派你來證明了他的睿智。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28726] = {title = "樹林的腐敗", objective = "殺死12隻樹林蜘蛛。", description = "我本來希望永遠不要為了這種邪惡的事務回到泰達希爾。我本來希望那裡的腐化已經完全遭到清除。但某種事物仍殘留著。\n\n這些蜘蛛比附近其他生物承受了更多的腐化。牠們變成了你們的人民和這片森林的威脅。我們必須削減牠們的數量，但更重要的是，必須找到污染牠們的腐化源頭。\n\n我會跟你一起去，幫助你完成這個任務。", progress = nil, completion = "這些蜘蛛所受的腐化不只侵蝕到表面而已。這不可能光是因為魔法或陰謀疾病的作用。這是在牠們體內培育出來的。\n\n看來我們的下一項任務很明確了。", rewards = "棘木匕首棘木法杖棘木之刃棘木之槌您會收到：\n\n"}
MultiLanguageQuestData['tw'][28727] = {title = "邪惡之觸", objective = "在影絲洞北方的盡頭殺死邪惡的基塞伊斯。", description = "如果這些蜘蛛的血脈裡天生就帶著腐敗的力量，那麼牠們的育母一定就是這個邪惡的根源了。\n\n讓我們前往洞穴北方的盡頭，找到邪惡的基塞伊斯。我們所尋找的答案就在她身上。", progress = nil, completion = "基塞伊斯和她的血脈都被這個圖騰給腐化了。這是一個熊怪圖騰。\n\n這真令人困惑。這就是說瘤背熊怪對這些森林仍然是個威脅。我們太快放鬆警戒了。", rewards = "布織披氅被燻黑的皮腰帶蛛網覆蓋鎖甲腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][28728] = {title = "暴風將至", objective = "在幽影谷北方的池子之間與丹泰莉雅‧銀林地交談。", description = "我會追蹤瘤背的痕跡，並試著找出這些腐化的源頭。如果你曾在多蘭納爾遇見過阿斯瑞達斯‧熊皮的話，他很清楚肆虐著這座森林的麻煩，應該可以告訴你該如何進一步的提供幫助。\n\n我相信我們還會再見面的。也許當我找到這種腐化的源頭時，你可以幫助我對付它。現在，我需要你回到丹泰莉雅那兒去完成你的訓練。謝謝你所做的一切，<name>。", progress = nil, completion = "你回來了!看到你真好。看來你已經解決了幽影谷腐化的根源。\n\n泰達希爾仍然處於苦難之中，需要受到好好的照顧，不過我們可以稍微抽出點時間，讓你完成在幽影谷這兒的訓練。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28729] = {title = "泰達希爾:艾澤拉斯之冠", objective = "在幽影谷東北邊的月井將水晶之瓶裝滿。", description = "作為結束在幽影谷訓練的儀式之一，你必須學習我們近代的歷史。\n\n有一個你必須去完成的任務。到我們東北邊的月井裡裝一瓶水。在那裡，你將會短暫地見識我們的魔法，並了解我們的過去。\n\n當你完成後，帶著水回來找我。我會進一步地指引你。", progress = "我們近代的歷史充斥著鬥爭和暴力。我們還有許多事物得去面對。", completion = "做得好，&lt;name&gt;。在你離開幽影谷，前往泰達希爾的開闊原野之前，只剩下一件事得做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28730] = {title = "珍貴的水", objective = "將裝滿的水晶之瓶帶去幽影谷的奧達希爾頂端給特納隆‧雷拳。", description = "特納隆‧雷拳統領著奧達希爾，負責監督在這片林地中發生的所有事情。\n\n如果你前往南方，你會看見一條通往他所在位置的斜坡。爬上這個斜坡完成你的訓練吧。\n\n很高興能認識你，<name>。知道在年輕的夜精靈之中還有像你這樣無私、對生命充滿熱愛的存在，讓我感到非常驕傲。你將會為我們的人民做出偉大貢獻。你將會為這個世界完成偉大的成就。\n\n別了，直到再會之日。", progress = "月井裡的水源自永恆之井，這個蘊涵著強大魔法能量的古代源泉曾給我們的世界帶來巨大的恐慌。\n\n德魯伊們充分利用月井的特性來修行，而哨兵們則將它視為月神伊露恩的祭壇，現在，就連歸來的精靈貴族們也渴望地注視著這口井。", completion = "那麼，你已經知道了海加爾山戰役結束後的第一部分。你需要知道的還有很多，你會在穿越泰達希爾前往達納蘇斯的旅程之中逐漸瞭解到這項任務的其他部分。", rewards = "林地外套林地之盾林木長袍林地鎖甲護胸您會收到：\n\n"}
MultiLanguageQuestData['tw'][28731] = {title = "泰達希爾:過去的認識", objective = "將裝著半瓶水的瓶子交給多蘭納爾的科瑞薩斯‧月怒。", description = "關於月井和泰達希爾的點點滴滴實在是太多了，我無法一一告知給你，這需要你自己去探索。科瑞薩斯‧月怒正在等著你。我已經把你所帶回來的水倒入了這個容器中，把它送到科瑞薩斯那裡去吧。\n\n出發吧，科瑞薩斯就在多蘭納爾的月井旁。你只需要沿著奧達希爾南邊的小路走出幽影谷，沿著鵝卵石鋪成的小路一直走，然後向西轉就行了。\n\n注意，你要一直沿著路走，<name>。最近路旁的森林裡出現了許多危險的野獸。", progress = "你好，<class>。是什麼讓我有榮幸和你會面呢?", completion = "啊，我明白了。你是被特納隆派來的。好吧，那麼，看起來我們有很多事要談，也有很多事要做。\n\n在我們著手進行任務之前，你應該先知悉一些跟月井相關的事情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28732] = {title = "這只代表一件事...", objective = "搭乘皮普的鑽地機前往黑石山。", description = "拉茲和我被海加爾守護者徵召來，調查拉格納羅斯再次入侵我們世界的情況。我調查並確認過，它回來了，而且充滿怒氣!我們還有證據指出這些暮光之錘教徒正將此地的元素移往東部王國的黑石洞穴。\n\n拉茲和我打算前往該處進行調查。如果你有興趣的話，我們的鑽地機還有一個空位。到裡面和我們碰頭，我們將要出發了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28733] = {title = "基礎植物學", objective = "撐過1波殭屍的猛烈攻擊。", description = "救命!救命!瘋狂的不死族在攻擊我的農場!淤泥農場的那個瘋子管理員或許是這場災難的始作俑者。幫我抵擋那些殭屍!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28734] = {title = "幫忙麥利薩爾", objective = "在幽影谷與麥利薩爾‧鹿盔交談。", description = "你應該去和麥利薩爾談談。我相信他已經遇到些小劣魔的麻煩了。\n\n如果你幫他的忙，我猜他可以提供一個不錯的地方讓你存放貨物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28735] = {title = "前往焚化之廳!", objective = "殺死羅姆歐格‧裂骨者。", description = "這是個埋伏，<name>!我們一下就遭到那叫做羅姆歐格‧裂骨者的超肥巨魔的襲擊!拉茲趁我跑去躲起來的時候英勇的禦敵。我看到他們把他打暈，然後想拖到一個地方，那胖子說叫做「焚化之廳」。我想那就在沿著大廳過橋的地方。\n\n我太害怕了，不能再前進了。帶著我的萬能潛水頭盔去找拉茲。我會用頭盔和你聯絡。\n\n如果你找到那隻巨魔，殺了他!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28736] = {title = "天火", objective = "登上沒收的火砲，並用它殺死100個舒諾茲步兵。", description = "造物者高地那裡還有一些舒諾茲的餘黨，危害著附近的生物。\n\n這兒有足夠的火藥，但卻沒有一個好的空中偵察員，我就像是矇著眼亂射一樣。\n\n跳上來，幫我一把。那些士兵將會連自己是怎麼死的都不會知道!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28737] = {title = "這是什麼地方?", objective = "殺死暮光信使柯爾菈。", description = "<皮普的頭盔發出輕微的振動。>\n\n這是什麼地方?看起來他們要對虛空龍做些恐怖的事。這個生物的能量要被吸到那女人的身上了!我們要阻止這個儀式!\n\n殺死柯爾菈以通過這個大廳!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28738] = {title = "暮光熔爐", objective = "殺死卡爾許‧控鋼者。", description = "<皮普的頭盔發出充滿能量的嗡嗡聲。>該死的!拉茲停不下來!他就好像被暮光那種燃燒的仇恨給支配了一樣!看來若想通過這個房間並追上拉茲，我們非得殺死暮光護甲商卡爾許‧控鋼者不可了。快點殺死他，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28739] = {title = "Night Elf Class Skill Tracker Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28740] = {title = "我眼花了嗎", objective = "殺死美麗。", description = "<皮普的頭盔爆響出女孩一般的尖叫。>\n\n不可能!我曾經被困在那些野獸之一的體內長達一個月。是的，就是被困在它們的胃裡。要不是我的裝備跟萬能頭盔，我早就慘死啦!看看那個，它生了一窩小崽子!\n\n你…你要阻止這一切，<name>!我們不能讓這些小崽子活著離開這裡!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "美麗二世的項圈美麗的虱子幼兒巾自動解碼指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][28741] = {title = "卓越者統領奧希迪厄斯", objective = "殺死卓越者統領奧希迪厄斯。", description = "<皮普的頭盔嗡嗡作響。>\n\n我的老天啊！看看這個地方！天…天花板上那個是死亡之翼用爪子做的記號嗎？房間中央的那隻生物到底是什麼？\n\n我到處都看不到拉茲。趕快解決這隻怪獸然後去找到拉茲！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "拉茲的胸甲鑽石鑲飾頭盔酸腐外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][28742] = {title = "希洛塔姆", objective = "殺死希洛塔姆。", description = "夥伴，殺死大傢伙的時候到了!希洛塔姆潛伏在北方，牠是霜刃豹當中體型最大的。\n\n你應該感到驕傲。沒有其他獵人擁有足以應付這場殘忍遊戲的技能...假如你看到那些美食家願意付給我多少錢買這傢伙的一片肉，你的眼珠子一定會掉出來!\n\n一旦你抓到牠就回營地來。我們可不想一口氣消耗掉太多的霜刃豹...您會收到：\n\n", progress = nil, completion = nil, rewards = "羞怯胸甲害羞肩套霜刃頭盔第五獵人胸甲拖屍者盾牌您會收到：\n\n希洛塔姆肉排"}
MultiLanguageQuestData['tw'][28743] = {title = "機尾槍手!", objective = "射下15個舒諾茲王牌飛行員。想要打獵嗎，<name>？\n\n跳上來！我負責飛行，你開槍！您會收到：\n\n完成任務後，你將獲得：\n\n", description = "想要打獵嗎，<name>？\n\n跳上來！我負責飛行，你開槍！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28744] = {title = "殭屍討厭我的植物", objective = "撐過2波猛烈攻勢的殭屍攻擊。", description = "你是個專家，<name>!正規的初級植物學家!聽著，我有些叫做岩果的新種子。用它來阻擋殭屍的進襲吧。只要把它丟到地上，它們就會阻擋不死族的前進路線。不死族笨的咧!\n\n試試看吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28745] = {title = "尖銳的哭嚎", objective = "殺死15隻冬泉鳴梟。", description = "小隻的貓頭鷹是很好吃，但古德古瑞伯說遙遠的南方有更大隻的貓頭鷹。鳴梟，這一帶的人如此稱呼牠們…當你和牠們纏鬥的時候，牠們會發出恐怖的噪音！\n\n但他說鳴梟是他吃過也賣過最棒的貓頭鷹了，而我相信他。當我在這裡繼續跟法蘭西斯爭辯的時候，你何不去幫我們湊幾隻鳴梟來？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28746] = {title = "滲透防禦", objective = "進入泰坦控制室。", description = "出發吧，<name>!\n\n那扇門後頭就是控制室。\n\n我會直接跑進去，關閉再生機制，然後我們就可以回家了。就這麼簡單。\n\n明白了嗎，<小夥子/小姑娘>，這層準備工作就是一個真正的考古學家與一般寶藏獵人不同的地方。\n\n如果沒必要，就別去招惹裡面的怪物。那樣搞，到頭來只會一團糟...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "離線護脛寶庫護手艱辛之路長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][28747] = {title = "誰來放個南瓜炸彈", objective = "撐過2波猛烈攻勢的殭屍攻擊。", description = "你看過這些東西嗎？\n\n<布瑞奇拉過一顆南瓜。>\n\n這可不是普通的南瓜，朋友。要知道，一旦你把這玩意種下，它們就會等待殭屍出現，然後碰嘎！炸得殭屍碎片滿天飛。上吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28748] = {title = "亡者草地", objective = "擊敗管理員斯蒂沃特。", description = "是斯蒂沃特!他快到了!我們得利用手上的一切來擊敗他!上吧!您會收到：\n\n", progress = nil, completion = nil, rewards = "植物學家馬褲布瑞奇的植物光源植物學家的鎖甲束褲您會收到：\n\n布瑞奇的向日葵種子"}
MultiLanguageQuestData['tw'][28749] = {title = "安多哈爾之戰", objective = "和戰爭法師埃拉葉談話來傳送到西瘟疫之地的安多哈爾。然後在安多哈爾中向薩沙理安回報。", description = "一隻獅鷲獸剛從瘟疫之地帶來消息。而且不是好消息。\n\n安多哈爾正陷入被遺忘者、聯盟、還有天譴軍團的三方交戰之中。烏瑞恩王已決定派出一名死亡騎士帶領突擊，但我確定他還是會用得著一切幫助。\n\n他們指名要一名聯盟<class>去進行某些特殊任務。如果你接受這份工作，再次和我談話，我就會準備一道傳送門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28750] = {title = "安多哈爾之戰", objective = "和秘法師阿爾曼談話來傳送到西瘟疫之地的安多哈爾。然後在安多哈爾中向寇爾提拉‧亡織者回報。", description = "一隻蠍尾獅剛從瘟疫之地帶來消息。而且不是好消息。\n\n安多哈爾正陷入被遺忘者、聯盟、還有天譴軍團的三方交戰之中。希瓦娜斯似乎已做出決定，而為了讓事態更有趣，她讓死亡騎士寇爾提拉‧亡織者坐鎮指揮。\n\n他們指名要一名部落<class>去進行某些特殊任務。如果你接受這份工作，再次和我談話，我就會準備一道傳送門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28751] = {title = "照顧花園", objective = "撐過2波猛烈攻勢的殭屍攻擊。", description = "就算我們擊敗了管理員斯蒂沃特，他的殭屍們還是在鄉間漫遊。看，另一波接近了!幫我抵擋他們，老朋友!上吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][28753] = {title = "硬著頭皮來", objective = "布萊恩‧銅鬚要你殺死伊希賽特、安姆內、賽特胥和拉頡。", description = "該死!\n\n有人癱瘓了整個系統!這下我沒辦法從操作台取得寶庫的控制了。\n\n我們得硬著頭皮來，<小夥子/小姑娘>。希望你和你的同伴已經有作戰的準備。\n\n上層總共有四個守衛。除非他們...呃... 斷線，我才有辦法使用這些圓盤。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "寶藏獵人手套真考古學家護腕重組頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][28755] = {title = "白銀之手年鑑", objective = "從斯坦索姆取回一本失落的白銀之手年鑑。", description = "你知道白銀之手騎士團嗎？他們是最早的聖光騎士，而他們之中的一些騎士，日後則分別加入了銀色黎明或是血色十字軍。儘管有些人誤入歧途，但他們仍然保有不少白銀之手騎士團的聖物。\n\n就在斯坦索姆的深處，在檔案管理員加爾福特的看守下，許多白銀之手年鑑仍然被留存了下來。你帶回來的任何一本年鑑都是對聖光之願禮拜堂的貢獻，你不這麼覺得嗎？完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28756] = {title = "畸形枯骨", objective = "消滅通靈學院的儲藏所的血骨傀儡。", description = "在生之時，我的兄弟和我與天譴軍團的每一種部隊戰鬥過，但其中死靈法師最令人不齒。他們不僅把我們死去的同伴復活來對抗我們，還製造出扭曲、手拿鐮刀的枯骨魔像。\n\n這些畸形骷髏殺了我很多兄弟，但我們無法把它們全毀掉。我請求你，<name>，為逝者接下這項任務。到通靈學院的儲藏所去，把這些可恨生物裡最巨大危險的那一個給消滅掉。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][28757] = {title = "打退他們!", objective = "殺死6隻黑石座狼。", description = "所以你就是暴風城來的新兵?我是治安官瑪克布萊德，此地駐軍的指揮官。歡迎你加入...\n\n<瑪克布萊德掃視著文件。>\n\n<name>。是叫<name>，對吧?\n\n你來的時間剛好。黑石獸人經由山區的空隙潛進了北郡。我的手下士兵正盡全力擊退對方，但我擔心他們很快就會被擊潰。\n\n前往西北方的森林，殺死進攻的黑石座狼吧!幫助我的士兵!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士繫腰座狼管理者手套行者腰帶追跡者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][28758] = {title = "生命與死亡之戰", objective = "騎上一隻朱紅先鋒。殺死8隻暮光暗影飛龍。", description = "死亡之翼和雅立史卓莎飛往格瑞姆巴托上方的空中了! 她的計畫被破壞了! 龍后比預期來得早離開了她準備的生命之環。我們得盡一切的力量幫助她。\n\n快點!爬上我身後任何一隻朱紅先鋒。\n\n如果遇到任何想要幫助死亡之翼的暮光飛龍，我們必須把牠們給殺死。騎上去吧，動作快!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "紅龍軍團披風紅色龍心戒指勝利之怒墜飾您會收到：\n\n"}
MultiLanguageQuestData['tw'][28759] = {title = "誘獅入羊群", objective = "殺死8名黑石間諜。", description = "入侵的獸人不是傻子。他們在估量我們，確保每一次攻擊都能為自己帶來優勢。\n\n在西北邊的森林裡有些黑石間諜。他們利用望遠鏡窺視我們，觀察我們每一個動作，並且等待時機。我要你去找他們開戰!\n\n殺光那群黑石間諜!必須讓他們了解:我們知道他們正在觀察，而我們有所準備!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士長袍間諜大師護腿暴風城步兵腰帶間諜派遣人護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][28760] = {title = "奧爾希斯的復仇", objective = "殺死亞沙德。", description = "奧爾希斯這座偉大的城市受到了風元素軍隊的攻擊。\n\n我們被囚禁起來，但我們算是幸運的了。\n\n大部分的人都死了，被困在令人窒息的沙漠黃沙之下。\n\n奧拉基爾的統治者亞沙德，是他下令進行攻擊的...他得為此付出生命作為代價。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "奧爾希斯護脛謝意信物卡利夫的指環您會收到：\n\n"}
