MultiLanguageQuestData['tw'][29074] = {title = "慶祝的季節", objective = "到暴風城門外與『豐收女巫』瑟萊斯丁說話。", description = "很高興看到你，<class>。萬鬼節是慶祝和反思的時刻，儘管有些人不知道其中道理。許多節日的習俗，比如說稻草人，已經隨著時間消逝了…到現在，因吉爾尼斯回歸聯盟才又有人重視。\n\n到暴風城門外與『豐收女巫』瑟萊斯丁說話。她會告訴你更多關於稻草人儀式的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29075] = {title = "增長的時刻", objective = "在稻草人的前面使用篝火。", description = "你好，<class>。你面前所見的稻草人象徵了自我。焚燒著它的則是淨化之火。\n\n這種傳統代表著我們卸下自身的負擔，投交給淨化之火。在冬季將臨時，我們卸下所有的負擔，以增長淨化與寧靜。加入我們的傳統儀式吧，<class>。\n\n從附近的篝火裡拿一根樹枝並把它投擲到稻草人上。", progress = "你釋放了你的負擔了嗎，<class>?", completion = "不要再讓你的負擔煩擾著你了。每次你感受到沉重的負擔時，記得想想稻草人。", rewards = "您會收到：\n\n搗蛋糖果龍石"}
MultiLanguageQuestData['tw'][29076] = {title = "凯文的测试任务", objective = "Just complete it.A testing quest", description = "A testing quest", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29078] = {title = "打退他們!", objective = "殺死6隻黑石座狼。", description = "又一個聯盟的號召，是嗎?我是治安官瑪克布萊德，此地駐軍的指揮官。我們不常見到像你這樣的<race>在這附近。>\n\n你來的時間剛好。黑石獸人經由山區的空隙潛進了北郡。我的手下士兵正盡全力擊退對方，但我擔心他們很快就會被擊潰。\n\n前往西北方的森林，殺死進攻的黑石座狼吧!幫助我的士兵!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士繫腰座狼管理者手套行者腰帶追跡者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][29079] = {title = "誘獅入羊群", objective = "殺死8名黑石間諜。", description = "入侵的獸人不是傻子。他們在估量我們，確保每一次攻擊都能為自己帶來優勢。\n\n在西北邊的森林裡有些黑石間諜。他們利用望遠鏡窺視我們，觀察我們每一個動作，並且等待時機。我要你去找他們開戰!\n\n殺光那群黑石間諜!必須讓他們了解:我們知道他們正在觀察，而我們有所準備!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士長袍間諜大師護腿暴風城步兵腰帶間諜派遣人護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][29080] = {title = "加入戰局!", objective = "到艾爾文森林後面的北郡修道院找維里中士。", description = "我有一道來自維里中士的緊急訊息。看來黑石獸人雇用了哥布林暗殺者。他們在修道院後面伏擊了我們的部隊。維里請我派給他一名英雄。你得去幫助他們，<name>!\n\n到修道院北邊的指揮營帳去找維里中士。快去!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29081] = {title = "他們派來的刺客", objective = "殺死8名哥布林暗殺者。", description = "你見過哥布林嗎，<name>？他們是卑鄙的小怪物，最喜歡的兩樣東西是黃金和他們自己。\n\n黑石獸人取得了哥布林暗殺者的援助，派他們來殺死我們的士兵。如果你到北邊的原野上尋找，就能在草叢間看到他們潛行的輪廓。\n\n我要你過去那裡殺死你所見到的每一個哥布林。必須讓他們知道：沒有人可以招惹聯盟！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "服飾商手套旅行之靴休閒手套先遣騎腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][29082] = {title = "無懼邪惡", objective = "治療四名受傷的暴風城士兵。", description = "你是否擁抱了聖光，<兄弟/姊妹>?是聖光解救我們!是聖光讓我有能力治療這些負荷過重的士兵!透過聖光，你才有辦法深入北邊的原野，救援我們倒下的兄弟們!\n\n帶著這本祈禱書，到原野上對傷者施展聖光的治療之觸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士輕鞋邊境護腕狼獵手之外衣輕量微光護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][29083] = {title = "後顧無憂", objective = "到艾爾文森林的北郡修道院前面找治安官瑪克布萊德回報。", description = "做得好啊，<name>!如今後方真的是清理乾淨了。我們會負責料理脫隊的傢伙。我要你回去南邊的北郡修道院前面找治安官瑪克布萊德，讓他知道哥布林的問題已經得到控制。\n\n再見。<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29084] = {title = "经典旧世随机 35-39级 （第一次）", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n實用貨物背袋"}
