MultiLanguageQuestData['tw'][29086] = {title = "惡性競爭", objective = "從風險投資公司的苦工、傭兵或雇工身上找回6張斯布特瓦夫的藍圖。", description = "我只是個小人物，想要搞個自己的生意做做。向著我的艾澤拉斯之夢努力，你明白嗎\n\n但是我一開店，隔壁的風險投資公司就決定要把我攆走。他們用威脅信來騷擾我，並在信上寫著「終止」和「結束」等字眼。\n\n更糟糕的是，我最新機器的結構圖不見了，我知道是那些公司的小偷把它偷走了!到淤泥沼澤打倒一些他們的員工。我知道他們把我的藍圖藏起來了!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29087] = {title = "淤泥的調查", objective = "在淤泥沼澤調查5個泥濘的痕跡。", description = "嘿<name>，你看到這個腳印了嗎？我們昨天發現營地外面到處都是這些腳印！沒有東西不見，但是我們所有的物品都被…檢查過了。泥濘的痕跡一直通往淤泥沼澤。\n\n有人在附近鬼鬼祟祟的，而且我一點也不喜歡這樣的感覺。你能去淤泥沼澤調查一下嗎？看看你能不能找出其他像是這個痕跡的線索！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29088] = {title = "滅絕土狼", objective = "殺死6頭亂齒土狼。", description = "嘿<name>，我們現在有個嚴重的問題。就在西方淤泥沼澤的土狼有繁殖過剩的跡象，而且已經漸漸形成了一種威脅。\n\n如果要再多聽牠們發情的鬼叫一晚上，我就要發瘋了！沃農說土狼可能還順手偷走了他獸欄裡的一頭豬。我們不能容許這樣的事情。\n\n你能去幫我們削減土狼的數量嗎？你可以發現牠們在西邊光天化日下大搖大擺的遊盪。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29089] = {title = "淤泥獸!", objective = "調查淤泥獸的棲息地並殺死任何冒出來的鬼東西。", description = "無論是什麼潛伏在淤泥沼澤附近，它都不像是人類。根據它留下來的痕跡來看，它也非常危險。\n\n你決定要追蹤痕跡到湖底並尋找這個生物的棲息地。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "淤泥沼澤披風管壺的外衣淤泥硬殼外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][29090] = {title = "燃燒的威脅", objective = "殺死農場西南方8個燃刃部族。", description = "當我們專注在這場大災變的時候，誰來提防我們背後的冷箭？當我們的領袖拿起武器對抗死亡之翼的時候，燃燒軍團正在籌劃讓我們垮台的陰謀。\n\n就在我們談話的同時，他們已經在西南方的農場集結部隊和供給品。要是死在燃燒軍團手上我也不在乎。是時候讓我們掌握自己的命運了。\n\n<name>，你願意幫助我維持警備嗎？去消滅他們的人，否則一切都太遲了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29091] = {title = "自由的行動", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29092] = {title = "通知長者", objective = "到主城與陶土議會長者說話。", description = "這消息必須得要散佈給整個陶土議會。我不確定要怎麼做，但是那個當初派你執行這個任務的長者可能知道該怎麼做。拜託，回到長老那裡並找出下一個行動的方向 - 我們必須得做些什麼!", progress = nil, completion = "這的確是一個重大的消息。我們一定得要傾盡全力阻止這場戰爭發生。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29093] = {title = "裂谷的豪華旅遊", objective = "到西部荒野的哨兵嶺並騎上一輛出租摩托車，跟你的孤兒一起參觀狂怒裂谷。", description = "我有一個朋友說有個在西部荒野的蒸氣坦克技師讓訪客使用他的摩托車。我朋友還坐過一次咧！\n\n我也曾在孤兒院看到有人騎那樣的車經過。聲音真的很大，也是我看過最快的東西了！我也想要試試看！\n\n我們能去西部荒野的哨兵嶺也坐坐看摩托車嗎？拜託？我保證會乖乖的，然後我們還可以去看在世界變化時所留下來的那個超級大洞！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29094] = {title = "回家的捷徑", objective = "乘坐X-831銀彈火箭兜風。", description = "看來你在這裡的工作已經結束了，<class>。你最好回到十字路口。\n\n算你運氣好，我的X-831銀彈火箭原型已經完成而且準備好供試駕了。要不你幫我最後一個忙，帶她出去兜一圈?\n\n我的助手會陪著你一起。你的美妙旅行工具正在我身後的平台上等著你。準備好就跳上去吧。", progress = nil, completion = nil, rewards = "測試駕駛員馬褲緊急短斧過客窄褲"}
MultiLanguageQuestData['tw'][29095] = {title = "回報給索克", objective = "到北貧瘠之地的十字路口向索克回報。", description = "現在威脅已經被化解了，你該回到十字路口。索克想要和你說話。\n\n再見了，朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29100] = {title = "布恩巴的靈魂", objective = "警告荊棘谷的人並找到另一個暗矛特使。", description = "這對我們暗矛來說是非常艱難的時候。贊達拉正在招集所有食人妖氏族並計畫要收復他們的失土。\n\n我們正在盡我們最大的努力警告所有人，但是可能已經太遲了。\n\n另外有一個暗矛已經去荊棘谷警告那邊的人。但是這段荊棘谷的旅途並不安全。\n\n幫我找到他並確保荊棘谷的人收到食人妖部族進攻的通知。\n\n我的靈魂與你同在。當你抵達荊棘谷的時候，我將提供幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29101] = {title = "踢龜季節", objective = "將5隻托爾托拉的子嗣踢進水裡。", description = "儘管小龜寶寶有點愛咬人，牠們還是很可愛。\n\n<蜜露恩舉起包著繃帶的手指頭。>\n\n但牠們腿短跑不快，沒有辦法逃過攻擊海加爾的那些火焰生物!\n\n<蜜露恩合起雙手。>\n\n請救救牠們，<name>!撿起那些烏龜，將牠們踢進梣湖的水裡。不用擔心踢傷牠們。牠們有堅硬的小殼。\n\n牠們也有很硬的牙齒，所以別碰牠們的嘴巴。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29102] = {title = "前往李文斯頓堡壘", objective = "前往北荊棘谷的李文斯頓堡壘尋找暗矛特使。", description = "我們先去查看李文斯頓堡壘，因為食人妖可能會先攻擊那裡。\n\n李文斯頓堡壘周圍全是食人妖廢墟...因此很容易被當成目標。\n\n也許我們能在那裡找到特使，希望還來得及。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29103] = {title = "毒蛇與蛇毒", objective = "殺死叢林毒蛇並檢視中毒的冒險者以便讓布恩巴治療。", description = "因為特使的警告讓我們集結了更多的冒險者來幫忙防禦。但是我們以為我們要打的是食人妖。\n\n沒想到我們竟然是被成群的毒蛇淹沒!\n\n牠們就像是從各個角落冒出來一樣，我們差一點就撐不住了，而且我猜情況可能會變得更糟。\n\n幫我們消滅這些毒蛇，說不定你這裡的食人妖朋友可以用魔法幫忙治療那些中毒的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29104] = {title = "靈魂與我們同在", objective = "在李文斯頓堡壘準備篝火以進行布恩巴的儀式。", description = "這裡的毒蛇總有點不對勁，<name>。牠們的毒液中含有腐敗魔精的痕跡，這種事件並不自然。\n\n營地中央的篝火，可以供我們來進行一個儀式。\n\n無論是誰召來這些毒蛇來攻擊我們，他們可能還在一旁監視著。\n\n唯一的問題，<name>，就是我現在只是以靈魂的形式存在這裡。我需要你來代為幫手。我要你去篝火那替我準備好。然後我會處理接下來的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29105] = {title = "奈辛瓦里會知道", objective = "警告在北荊棘谷內奈辛瓦里遠征隊營地的獵人們。", description = "太好了，這就是我們需要的:古拉巴什的暴動將會用毒蛇來打頭陣。我們至少知道這麼多。\n\n假設奈辛瓦里遠征隊會有些相關內部消息的可能性應該滿高。就算是沒有有用的線索至少他們也知道怎麼對付那些毒蛇。\n\n出發並讓他們知道你目睹到的事情。讓他們知道食人妖將會用毒蛇作為他們的武器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29106] = {title = "世界上最大顆的鑽石", objective = "帶你的人類孤兒到舊鐵爐堡的王座廳下。當你到達時如果他不在，一定要召喚他。", description = "我聽說過那個麥格尼‧銅鬚，他曾經是鐵爐堡的國王，然後被變成一顆巨大的鑽石！這是真的嗎？怎麼會有人無端地就變成一顆鑽石？也許是你要先成為一個國王才辦的到，所以沒有人試過。\n\n我們能去看看他嗎？他應該就在鐵爐堡王座廳的底下，一個被稱為舊鐵爐堡的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29107] = {title = "瑪法里恩回來了!", objective = "帶你的人類孤兒到達納蘇斯的月神殿與瑪法里恩·怒風見面。如果到達的時候孤兒不在，就呼喚他。", description = "我聽說瑪法里恩·怒風從翡翠夢境回來了。我雖然不知道那在哪裡，但是聽起來像是在很遠的地方。\n\n總而言之，他本來應該在達納蘇斯的月神殿那裡跟高階祭司一起。你認為我們可以跟他見面嗎?他是艾澤拉斯歷史上最厲害的德魯伊了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
