MultiLanguageQuestData['tw'][29217] = {title = "被監禁的斥候", objective = "釋放被監禁的斥候:哈茲雷克、巴卡祖、諾卡尼和卡沙。他們正被阿曼尼的高階祭司監禁著。", description = "我們到了以後，我派出了我的斥候去探尋更多關於贊達拉出現在祖阿曼這裡的消息。很多人帶著有用的資訊回來了，但是有些卻失蹤了。如果我們不儘快做出行動，他們將會被新督軍的中尉當成祭品貢獻給贊達拉大使。\n\n找出我的斥候，<name>，然後在那些祭司犧牲他們之前把他們帶回來!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29218] = {title = "世界之樹印記", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29219] = {title = "布恩巴的靈魂", objective = "警告荊棘谷的人並找到另一個暗矛特使。", description = "這對我們暗矛來說是非常艱難的時候。贊達拉正在招集所有食人妖氏族並計畫要收復他們的失土。\n\n我們正在盡我們最大的努力警告所有人，但是可能已經太遲了。\n\n另外有一個暗矛已經去荊棘谷警告那邊的人。但是這段荊棘谷的旅途並不安全。\n\n幫我找到他並確保荊棘谷的人收到食人妖部族進攻的通知。\n\n我的靈魂與你同在。當你抵達荊棘谷的時候，我將提供幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29220] = {title = "前往班姆巴拉", objective = "前往北荊棘谷的班姆巴拉尋找暗矛特使。", description = "我們先去查看班姆巴拉，因為食人妖可能會先攻擊那裡。\n\n班姆巴拉十分靠近食人妖的城市祖爾格拉布...因此很容易被當成目標。\n\n也許我們能在那裡找到特使，希望還來得及。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29221] = {title = "毒蛇與蛇毒", objective = "殺死叢林毒蛇並檢視中毒的獵頭者以便讓布恩巴治療。", description = "警告發揮作用了，<name>。\n\n我們集結了更多的獵頭者來幫忙防禦。但是獵頭者...不習慣獵毒蛇的頭。所以我們很快就會被毒蛇淹沒。牠們就像是從各個角落冒出來一樣，而且情況可能會變得更糟。\n\n幫我們消滅這些毒蛇，並讓布恩巴用他的魔精來治療那些中毒的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29222] = {title = "靈魂與我們同在", objective = "在班姆巴拉附近的毒蛇神廟前準備篝火以進行布恩巴的儀式。", description = "這裡的毒蛇攻擊我們的方式有些不對勁，<name>。有些不自然的地方…即使是牠們的毒液中也含有腐敗魔精的痕跡。\n\n這裡附近的神殿有篝火，可以供我們來進行一個儀式。\n\n無論是誰召來這些毒蛇來攻擊我們，他們可能還在一旁監視著。\n\n唯一的問題，<name>，就是我現在只是以靈魂的形式存在這裡。我需要你來代為幫手。我要你去篝火那替我準備好。然後我會處理接下來的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29223] = {title = "奈辛瓦里會知道", objective = "警告在北荊棘谷內奈辛瓦里遠征隊營地的獵人們。", description = "古拉巴什的暴動將會用毒蛇來打頭陣。\n\n你知道誰最懂得怎麼控制這些動物的數量？那些奈辛瓦里遠征隊的獵人。\n\n到那裡去看看他們的狀況如何，有沒有什麼好辦法可以解決這些毒蛇。\n\n如果他們不知道的話，至少你可以警告他們這些毒蛇的事情，這一點都不自然。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29225] = {title = "採取可行的應對行動", objective = "到海加爾山的諾達希爾和卡雷苟斯談話。", description = "<塔瑞克苟莎心無旁騖地聆聽你描述自己所看見的幻象。>\n\n不可能!\n\n就連亞雷戈斯都不敢做到這種程度。\n\n我不是質疑你的誠信，<class>，但你必須理解，你凡人的心智很容易遭到蒙蔽。\n\n無論如何，必須讓卡雷苟斯知道這些事。你要立刻前往諾達希爾找他。\n\n我當留在這裡隱藏我們行動的證據。務必別和其他任何人談論這件事!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29226] = {title = "反追蹤", objective = "在北荊棘谷找到袞特‧厄錘。", description = "這幾天我們都在抵禦毒蛇，<name>。不過跟叢林裡的那傢伙相比，毒蛇算是小事了。\n\n我們獵人反被獵。\n\n有一隻大型獵豹，我們叫牠莫堤，牠不斷地把我的人拖進灌木叢中。\n\n我們派出最厲害的獵人袞特‧厄錘去追捕這頭野獸。\n\n厄錘往東邊去了，說不定你能在那找到他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29227] = {title = "獵人的復仇", objective = "殺死莫堤，為袞特‧厄錘的狩獵劃下句點。", description = "那隻在追殺我們的野獸…我一直以來都想要獵殺牠。\n\n我們都管牠叫莫堤。牠可是很聰明的。但是牠在殺死我兄弟的時候犯下了一個大錯。而現在牠所犯下的錯會讓她吃到苦頭。厄錘已經嗅出牠的味道了。\n\n我注意到牠就在庫爾森的營地上方徘徊。如果我們動作快一點，我們就可以幹掉牠。\n\n準備好了嗎，<name>？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29228] = {title = "追蹤那隻豹", objective = "找出莫堤把袞特‧厄錘帶去哪裡了。", description = "噢，這樣就可以解釋為什麼莫堤看起來變小了...真的莫堤叼著袞特‧厄錘跑了，憑著袞特的機敏，他設法發射了信號彈，好讓你還是能夠追蹤到他。在一切都太遲之前先找到厄錘!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29230] = {title = "莫堤", objective = "帶布恩巴到莫提的屍體處。", description = "我覺得那隻獵豹有點不太對勁，<name>。牠不太自然。我需要在牠的屍體上舉行一個儀式。把莫堤放下，然後讓我們來看看能發現什麼線索，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29231] = {title = "那個獵人的狀況如何？", objective = "去看看袞特‧厄錘。", description = "情況看起來很不妙。那隻黑豹受了某種強大法術的影響。我們最好去看看那個獵人現在怎麼樣了？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29232] = {title = "與靴共葬...", objective = "收集袞特‧厄錘的靴子。", description = "啊…是你。<name>。莫堤…死了？那麼我兄弟的仇算是報了。我現在只求你一件事…這傢伙，老是在抓我的光腳板。矮人不應該光腳入土的。拜託，讓我跟我的靴子一起合葬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29233] = {title = "警告格羅姆高營地", objective = "前往格羅姆高營地。", description = "他不是白白犧牲的，<name>。我們推測出基爾娜拉是這件事情的幕後主使。情況看來不太妙。\n\n我們最好去西邊查看一下格羅姆高營地。說不定我們的聯絡人會在那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29234] = {title = "指派", objective = "從火源之界取回諾達希爾木枝。", description = "我有義務立刻調查你所敘述的事情，<race>，這表示我在這邊的任務必須落到你的肩上了。\n\n我因為一股古老的魔法來到這裡，這魔法的力量過於強大，不可能是自然產生的。在那之後，我發現了一種令人極度不安的演變。\n\n一節來自諾達希爾的樹幹被人從樹上扯了下來，並帶到火源之界的深處。在那裡有個具有危險性的強力儀式，很可能會使諾達希爾遭受污染並被火焰吞噬。\n\n你必須找到中斷儀式的方法，並取回那份世界樹的枝幹。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29235] = {title = "防禦格羅姆高營地", objective = "幫忙防禦格羅姆高營地3分鐘。", description = "我希望你喜歡戰鬥，<name>。你的食人妖朋友已經來過了，然後警告我們有關古拉巴什準備展開的暴動。但是我從來沒想過這場戰爭會如此光榮。\n\n來吧，加入我們的戰鬥並讓那些古拉巴什食人妖看看部落的威力!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29236] = {title = "前往硬心藏匿處", objective = "前往荊棘谷海角的硬心藏匿處。", description = "布恩巴…是你嗎？\n\n你的聯絡人來過了。他急忙趕往下一個地點好警告他們。說真的，能怪他嗎？我提供了一隻蠍尾獅讓他前往哥布林的硬心藏匿處，就在荊棘谷海角那邊。\n\n我會讓你乘坐我的蠍尾獅過去。\n\n你準備好要出發的時候跟我說一聲，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29237] = {title = "巫毒殭屍", objective = "拯救10名藏匿處殭屍攻擊倖存者。", description = "那些人...那些全是殭屍!巫毒殭屍!這可不太妙，<name>。\n\n你得殺了他們才行。\n\n只要殺了他們，我就有時間救他們，把他們變回原本的模樣。\n\n我們動作要快點，殭屍可不用休息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29238] = {title = "糟糕的供給品", objective = "檢查硬心藏匿處準備區域的食物供給。", description = "有些倖存者提到了食物，<name>。我們最好檢查一下食物供給。我有一種不妙的預感。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29239] = {title = "諾達希爾木枝", objective = "在北風凍原的琥珀岩臺取得諾達希爾木枝。", description = "自從我們上次交談以來，發生了很多事。\n\n我獨自拜訪了奧核之心，將安納克羅斯的神器使用在自己身上，隨即將之取回。我同樣看見了你曾經看見的事物。\n\n在進一步討論之前，讓我對你在這裡和在火焰界域所提供的協助表示感謝。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n諾達希爾木枝"}
MultiLanguageQuestData['tw'][29240] = {title = "緊急撤離", objective = "伴隨卡雷苟斯前往凜懼島。\n\n準備好時就去和他交談。", description = "那麼，回到眼前的事務上...\n\n我相信奧核之心裡的幻象是死亡之翼趁這敏感時機用來在我們族群中製造衝突的幻覺。\n\n我們陷入彼此爭鬥只會讓碎界者從中獲利。\n\n不過，一種纏繞不去的不安感覺讓我不得不戒慎小心。\n\n在選擇的時機來臨前，帶著塔瑞克苟莎先行撤離會是明智的抉擇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29241] = {title = "擊敗破神者", objective = "在英雄難度中殺死祖爾格拉布內的金度。", description = "<血腥殺戮者札拉指向遠方的神廟。>\n\n當金度最後從這個世界上被撕碎時，他藏身於陰影之中，雖然還活在靈魂的世界裡，但是已經支離破碎而且非常虛弱。\n\n但是金度對靈魂一直都是有很強大的控制力量。一個接著一個，他讓這些靈魂屈服在他的意志之下，每吞噬一個靈魂，距離金度打破時空之洞並入侵這個世界就會更近一點。\n\n他現在已經到這裡了...\n\n靈魂已與我們同在，我們必須了結金度。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29242] = {title = "幫無價的定個價", objective = "調查狂性儲納所並找出神秘的古拉巴什寶石。", description = "聽好了，朋友。我不認識你，你也不認識我。但是既然我們現在都在這裡，那麼就代表里維加茲有話要跟你提一提。\n\n也許你只是在這個充斥食人妖的災變叢林中散步而已。也許你只是剛好找到了一兩個無價的食人妖文物。也許你把它帶回來給我，我會一不小心留下一些小禮物給你。\n\n如果你一定得知道的話，這是一個專案研究。還有不行，你不能問我這個專案的內容是什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29243] = {title = "直擊核心", objective = "殺死火焰副官。", description = "拉格納羅斯的一名副官在拉格納羅斯之境現身了。出擊的時刻到了。賽那‧風暴行者隊長要求你過去協助戰鬥。\n\n當你抵達時，萎枝和其他人應該也會加入戰局。你應該儘快過去西北方找他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29245] = {title = "神秘的種子", objective = "將橡實帶去火源之界裡的瑪法里恩突破口給愛芙里拉。\n\n已提供物品：\n", description = "一粒小而乾癟的橡實從火焰德魯伊的袍中掉落出來。\n\n為什麼一名火焰德魯伊會隨身帶著這種東西?\n\n也許瑪法里恩突破口裡的某個人會想要看看這東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29246] = {title = "紓緩疼痛", objective = "從沸騰的炎之王那裡取得4顆烈焰包覆的心臟。", description = "大德魯伊對疼痛的忍耐度極高。我曾治療過一天中有二十二小時都在痛苦慘叫的患者，而他們傷勢的嚴重程度甚至不到哈繆爾所承受的一半。\n\n然而，我可以感受到他今天的不適比平常都要嚴重。幫我把東南邊那些大型火元素的心帶來吧。我能用它們來為我們的患者準備紓緩用的藥膏。", progress = "這些心臟正好有能力讓我們幫助哈繆爾安心休息。", completion = "我必須立刻開始準備藥膏，因為不快點的話這些藥材很快就會失去效力。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29247] = {title = "療傷", objective = "從賽瑟莉亞裡的熾炎焦皮巨人那裡取得4條摻有硫磺的裹帶。", description = "我們在聖地這裡擁有充足的醫療補給，但我們不能遺忘現在正處於戰時。哈繆爾不是唯一需要繃帶的人。\n\n熾炎焦皮巨人漫遊在賽瑟莉亞的棲息處，身上穿戴著擁有抗火特性的裹帶，能在哈繆爾身上發揮和任何繃帶相同的效果。把這些裹帶拿來，我會處理一下然後用在大德魯伊身上。", progress = "有人說這些裹帶裡的硫磺包含有治療成分。我自己其實不怎麼肯定，但我願意為了這種可能性忍受它刺鼻的氣味。", completion = "非常感謝，&lt;class&gt;。\n\n你為戰況提供了助益。燒傷病患需要大量的繃帶，就算是哈繆爾也不例外。", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29248] = {title = "釋放壓力", objective = "取得100個喚焰者鱗片。", description = "由於嚴重的燒傷，大德魯伊哈繆爾正承受浮腫之苦，他的身體組織腫脹不堪。他的隨從盡了很大的努力才幫他消腫到能夠呼吸的程度。\n\n一般說來，我們會用切開血肉的方式來消除腫脹，但他太虛弱了，<name>。我不能就這樣在他身上動刀。\n\n喚焰者的鱗片可以治療這種腫脹，但你需要收集很多很多才行。", progress = "你拿到鱗片了嗎？我仍在猶豫是否要在大<class>身上動刀，我們必須找到方法來消除這種腫脹。", completion = "你擁有慈善的心腸，牛頭人。這麼多的鱗片，我們至少不用在今天對他動刀。兩天也說不一定。", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29249] = {title = "栽種季節", objective = "在瑪法里恩突破口，把橡實種在安戈洛的泥土裡。", description = "橡實似乎沒有什麼損傷。\n\n<愛芙里拉聳聳肩。>\n\n在這邊推敲了半天也沒有什麼意義。就直接把它種下去，看看會長出什麼吧。\n\n你運氣好，我們有帶來一些剩下的泥土好幫助我們重建基地。\n\n你會在正東邊的墓地找到這些泥土。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29250] = {title = "嘗試聯絡", objective = "前往藏寶海灣去找布恩巴的聯絡人。", description = "你不是殭屍…\n\n食人妖？我是有看到過一個，在事件爆發前…他警告過我們，叫我們要提高警覺…但一切都太遲了。\n\n你的食人妖朋友前往藏寶海灣去警告他們了…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29251] = {title = "藏寶海灣的利益", objective = "收回或許能夠讓祖爾格拉布的食人妖遠離藏寶海灣的神器。", description = "聽好了，<name>。到目前為止你幫上了很多忙，但這還是不夠的。我需要阻止那些食人妖。或者至少阻止他們進入藏寶海灣。\n\n我會派一個人去監督整個行動的過程，但我要你到祖爾格拉布並確保行動順利。\n\n最起碼，我要你找到可以阻止食人妖進入藏寶海灣的東西。\n\n你若能辦到的話我們絕對不會虧待你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29252] = {title = "藏寶海灣的利益", objective = "收回或許能夠讓祖爾格拉布的食人妖遠離藏寶海灣的神器。", description = "藏寶海灣的大財主里維加茲派我過來確保這裡的食人妖威脅已經解除了。或者至少在藏寶海灣大門的威脅是已經解除了。\n\n我想要的是行動然後看到結果。\n\n我要你去那裡然後開始屠殺。\n\n我要你去那裡找些東西讓這些食人妖不會再出現在藏寶海灣。\n\n你能做到的話我將會確保你會收到你應得的獎勵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29253] = {title = "閃亮的獎勵", objective = "從加尼祿哨站雕像的箱子中取回你的獎勵。", description = "有一堆戰利品位於荊棘谷在藏寶海灣西北方的加尼祿哨站雕像那裡。\n\n到雕像那裡拿取你的獎勵，<class>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n黑冰黃金項鍊黯淡的皇冠寶石手鐲"}
MultiLanguageQuestData['tw'][29254] = {title = "小鞭笞者", objective = "帶著赤紅鞭笞者去找愛芙里拉。", description = "小紅花開心地擺動它的觸鬚。它似乎喜歡你!\n\n也許愛芙里拉會想要看看橡實所長出的這個東西。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29255] = {title = "餘燼膠質", objective = "從焦炭士兵和焦炭鎮壓者那裡取得5份餘燼膠質。", description = "赤紅鞭笞者的藤上長了一些破裂的水泡。如果不加以整治，可能會構成生命威脅。\n\n幸運的是，區域裡焦炭士兵和焦炭鎮壓者會產生一種名為餘燼膠質的蠟狀物質，應該能紓緩鞭笞者的痛苦。\n\n帶一些這種膠質給我，順便殺死那些討厭的火元素。", progress = "鞭笞者長得還蠻快的。", completion = "聞起來味道不太好，但應該能很快治好鞭笞者。", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29257] = {title = "偷走熔岩花", objective = "在北邊的熔岩泉收集8份熔岩花。", description = "我們在北邊的熔岩泉發現了一個新花種。這種花令人驚異，竟能在純粹的熔岩之中生長!\n\n請過去那裡，取回一些樣本給我。我確定研究這種植物能幫助我們更加了解你這位小朋友。\n\n說到這裡，這位小朋友似乎非常想跟你一起去。希望小傢伙會乖乖的。", progress = "太迷人了!我在火源之界待得越久，就越覺得這裡有個獨特運作的生態系統。", completion = "謝謝你，&lt;name&gt;。我會立刻開始分析這些樣本。", rewards = "您會收到：\n\n世界之樹印記"}
