MultiLanguageQuestData['tw'][29267] = {title = "好事遲早會來的", objective = nil, description = "這麼多戾氣、這麼多死亡。有的兄弟已經陣亡了、有的母親失去生命，現在要是沒有去處理的話有隻獵豹寶寶馬上也會死去。\n\n你能在這些兇殘行為中暫停一下，去照顧獵豹寶寶嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n獵豹寶寶"}
MultiLanguageQuestData['tw'][29268] = {title = "好事遲早會來的", objective = "照顧獵豹寶寶，畢竟，是你殺死了牠的母親。", description = "這麼多戾氣、這麼多死亡。有的兄弟已經陣亡了、有的母親失去生命，現在要是沒有去處理的話有隻獵豹寶寶馬上也會死去。\n\n你能在這些兇殘行為中暫停一下，去照顧獵豹寶寶嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n獵豹寶寶"}
MultiLanguageQuestData['tw'][29269] = {title = "合而為一", objective = "和卡雷苟斯談話來同意他的提議。", description = "保護她是我的責任，然而她卻犧牲了自己來拯救我。\n\n我不能失去她，<name>。我必須鄭重地向你提出一個請求。\n\n從來沒有任何凡人接受過真正龍族的精華，但若你允許，我願意開個先例。\n\n拜託，趁她還有氣息的時候，你是否能容許我將塔瑞克苟莎的精華連結到你的身上?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29270] = {title = "分秒必爭", objective = "到火源之界收集1000份沸騰燼渣。", description = "塔瑞克苟莎已和你連結在一起，<name>，但只是暫時的。還需要守護巨龍的力量來永遠封住她的精華。\n\n瑪里苟斯繼任者的選拔要直到艾澤拉斯下一次月蝕才會決定，你們的連結無法延續到那個時候。\n\n幸好，有個方法能為我們爭取更多的時間。強大的元素存在能夠延長儀式的效力。你已經相當熟悉的火焰界域就有些這樣的元素。\n\n取來那些東西，<class>，讓塔瑞克苟莎得以存續到月蝕。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29271] = {title = "Bound for Warmer Weather", objective = "Speak to General Taldris Moonfall at Malfurion's Breach on the Molten Front.We should be okay here for now, and they have need of you in the Firelands. You should go through the portal and help them out.您會收到：\n\n完成任務後，你將獲得：\n\n", description = "We should be okay here for now, and they have need of you in the Firelands. You should go through the portal and help them out.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29272] = {title = "需要...水...", objective = "將安倫‧尋影者帶往通向熔岩前線的入口處。", description = "需要...水...。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29273] = {title = "真燙啊", objective = "使用索羅的溫度計來測量火羽峰上三處大熔岩池的溫度。", description = "火羽峰的火鷹可以承受不可思議的高溫。儘管你經常看見牠們盤旋空中，其實牠們也能在熔岩之中游泳。\n\n對不對，安倫？\n\n我們想要知道那種熔岩到底有多燙。火羽峰上有三處大型熔岩池。用這個來測量每個池子的溫度吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29274] = {title = "夏諾克斯之犬", objective = "取得6小堆的獵犬骨灰。", description = "在火源之界最大的島上，我們的部隊在與喚焰者獵人夏諾克斯對抗時遭遇了困難。他不僅有著無懈可擊的準頭，更養了多條訓練有素的獵犬，為我們的部隊造成數不清的麻煩。\n\n憑著他傲人的明智，索羅認為研究這些獵犬的生物學資訊會是個好主意。而我，當然同意索羅的主意。\n\n你會在熔爐底下的熔岩之流找到幾條這種獵犬。我們需要牠們的灰燼來進行學習。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29275] = {title = "范達爾的手段", objective = "取得火焰德魯伊法杖、火焰德魯伊法術書、火焰德魯伊試劑袋和火焰德魯伊塑像。", description = "火焰德魯伊...直到幾週前，索羅和我都還沒聽說過這群德魯伊。現在，在范達爾‧鹿盔的帶領下，他們操控火焰的技藝威脅到我們完成任務的可能性。\n\n看來他們在東北方的火成深淵儲存了一些補給品。如果我們能取得那些補給，就可以在與范達爾的戰鬥中取得更多的優勢。", progress = "相信我 - 我們在這裡取得的任何資訊都對了解范達爾的力量來源大有幫助。", completion = "安倫，看看&lt;name&gt;找到了什麼!這正是我們所需要的!\n\n我們會花上一點時間來檢驗這些補給。感謝你，我們先去忙了。", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29276] = {title = "火焰蛛后", objective = "取得8份烈焰毒液的樣本和8份灼熱蛛網絲液的樣本。", description = "東北方的寡婦之攫，就是根據巨大的蛛后貝絲堤拉克來命名的。她的網子與毒液對我們的主攻軍來說是莫大的威脅。\n\n我們相信，針對熔岩前線裡火焰蜘蛛所做的研究，可以用來找出成功解決貝絲堤拉克的方法。盡你所能地收集牠們的毒液和製網的腺體液，然後回來找我可靠的朋友安倫。", progress = "小心那些液體，<name>。我們不會喜歡它們潑到外面的結果。", completion = "你為我們的任務幫了很大的忙，&lt;name&gt;。索羅和我都很感謝。", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29277] = {title = "Druid Tree, Stage 3 Tracking", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29278] = {title = "活體黑曜石", objective = "取回10份黑曜隕石。", description = "你看見從天空落下的那些火球了嗎？我看見其中一顆墜落在北方的原野上，而落地岩塊的材質竟然是純粹的活體黑曜石！\n\n我可以用這種材料為我們的部隊鍛造出極度堅固的防火盔甲和武器。你能幫我帶一批來嗎？\n\n過去熔岩泉，並碰觸其中一個磁石。只要記得火雨來臨時站到安全的位置就好，然後在那些岩石因衝擊而崩碎之前收集它們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29279] = {title = "注滿月井", objective = "取得125個世界之樹印記。", description = "我們在哨兵樹外面建造了一座月井，但在注滿永恆之井的神聖純水之前，這座井還派不上什麼用場。\n\n擁有能夠發揮力量的月井，我們就能對我們庫存的食物施予祝福。我們也可以利用月井的祝福來為你施加防護火焰的能力。\n\n當你取得足夠的印記，到瑪洛尼聖地去找瑪托克勞，她有辦法把井水運過來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29280] = {title = "滋養之水", objective = "在瑪法里恩突破口和埃拉‧暗影風暴談話。", description = "我已經按照你的要求將神聖的月井之水送到瑪法里恩突破口。埃拉接受過良好的訓練，知道該如何運用。你應該回去找她，看看她能為你施予什麼樣的祝福。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29281] = {title = "額外的裝備", objective = "取得125個世界之樹印記。", description = "這些德魯伊缺乏適合此地任務的工具。不過，我在傳送門另一邊的老雄鹿祭壇那裡有個兄弟。既然我們要團結起來，就一定要弄點真正的玩具來對付拉格納羅斯那個老傢伙和手下的小伙計們。\n\n去搞點那種印記玩意，然後去找瑪托克勞，跟她說你要找瑞基特。我們需要瑞基特待在這兒，這樣才方便製造一些大麻煩。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29282] = {title = "裝備精良", objective = "在瑪法里恩突破口和瑞基特談話。", description = "瑞基特應該和你要求的一樣，正和達密克一起待在瑪法里恩突破口。不過，我不確定你是否真的知道和這兩個人打交道代表了什麼意義。\n\n說到這個，你可能得去看看他們...確保他們沒把哨兵樹都給炸了。只要你讓他們忙著應付那些元素，突破口那邊發生「意外」的機率應該就會不那麼戲劇化一些。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29283] = {title = "召喚先祖", objective = "取得125個世界之樹印記。", description = "先祖們在海加爾等待著。因為自身的...「構成物質」緣故，火源之界對祂們來說是個危險的地方。但想和拉格納羅斯的屬下對抗，祂們的力量會是我們絕大的幫助。\n\n帶著你的印記到瑪洛尼聖地去找老枝。如果先祖們願意和我們同行，將會是由它來帶領祂們穿過傳送門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29284] = {title = "先祖的援助", objective = "在瑪法里恩突破口和老枝談話。", description = "先祖們已經了解你的智慧多有價值，並往瑪法里恩突破口出發了。你應該去找老枝，我確定它會想和你碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29285] = {title = "連成一線", objective = "和卡雷苟斯一起前往藍龍議會。\n\n準備好時，在凜懼島和卡雷苟斯談話。", description = "遴選的時刻到了，<name>。\n\n儘管只有藍龍軍團的成員可以出席遴選，和塔瑞克苟莎的連結卻讓你的現身具有必要性。\n\n我得請求你轉化為她的形體，並代表她進行投票。\n\n不要拖延。月蝕的時刻就快到了...您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n諾達希爾符文法杖"}
MultiLanguageQuestData['tw'][29286] = {title = "Druid Tree, Stage 2 Tracking", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29287] = {title = "高度興趣", objective = "到火羽峰頂取回一顆火鷹蛋。", description = "這些火鷹是屬於火焰的生物，但牠們也表現出許多和我們家鄉鳥類相同的特質。我不禁開始思考牠們的發源地為何。\n\n回到重點，我在想我們應該能訓練牠們。如果你有那個意思，就馴服牠們並用來對付我們的敵人吧。\n\n我要你到火羽峰頂上，取回一顆火鷹的蛋。若你把蛋安全地帶回來，我會負責之後的事。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29288] = {title = "羽翼初成", objective = "帶回5隻小火鷹。", description = "我們的斥候回報，整個山頂上都是剛出生的火鷹幼雛…牠們的蛋一定是在這幾天孵化了。更好的是，牠們看起來溫馴可愛。\n\n我知道這要求聽起來或許很奇怪，或是讓人不舒服，但若你帶回一些幼雛，我或許能訓練牠們成為我們戰爭的助力。\n\n你願意嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29290] = {title = "天火", objective = "利用訓練有素的火鷹在火源之界殺死100名喚焰者，40隻燼網蜘蛛，和3名熔岩領主。", description = "看啊!真是太棒了!才出生不過兩天就已經完全長成。可惜，我猜牠們的生命週期將如曇花一現，所以我們得好好利用僅有的時間。\n\n訓練進展得十分順利，我要你負責帶牠上陣去襲擊拉格納羅斯堡壘附近的那些敵軍。\n\n不要手下留情，<race>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29293] = {title = "焦翼", objective = "在火羽峰解救5名受傷的猛禽德魯伊。", description = "我們派出許多風暴烏鴉去偵察山頂，並試著取回火鷹的蛋，可惜成功的實在不多。上升氣流讓飛行變得極度危險，火鷹們也不是友善之輩。\n\n我需要你過去那裡，盡力解救那邊的德魯伊。我有夾板、繃帶、燒傷藥膏、嗅鹽...等，只要他們還活著的話，這些都是能幫助他們恢復意識的東西。請你加快動作，盡可能幫助越多的人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29294] = {title = "Animate Embers", objective = "Retrieve 6 Animate Embers.Several of our scouts have reported seeing what seemed to be living flames skittering around the surfaces of Fireplume Peak.\n\nIf the reports are accurate, we need these for study immediately. We've yet to fully understand where all of the attacking elementals come from, and these could well lend us significant insight.您會收到：\n\n", description = "Several of our scouts have reported seeing what seemed to be living flames skittering around the surfaces of Fireplume Peak.\n\nIf the reports are accurate, we need these for study immediately. We've yet to fully understand where all of the attacking elementals come from, and these could well lend us significant insight.您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29295] = {title = "越大越...", objective = "從火羽峰上的黑曜懲戒者那裡收集10份活體黑曜石。", description = "你不會想穿著那玩意跑去挑戰熾炎焦皮巨人吧？如果你不穿上我用黑曜石鍛造的裝備，你將在一瞬間被燒得乾乾淨淨！就算你穿上了，也永遠還有其他的好貨色。\n\n瞧，<兄弟/姐妹>，我可以為你鍛造用金錢所能買到的最頂級盔甲，但我需要純淨、尚未熔化的活體黑曜石。\n\n火羽峰上的那些黑曜懲戒者正好就是這種玩意構成的。過去大開殺戒，然後收集它們的碎片。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29296] = {title = "地域觀念", objective = "殺死5隻火鷹。", description = "火鷹被我們長時間的出現給激怒了。牠們變得極度敵對，而且和平常保衛地盤的態度不同。我擔心如果不加以處理，牠們很快也會對我們的樹發動侵襲。我不確定我們有能力應對那種狀況。\n\n前往火羽峰，盡你所能地處理掉牠們。對我來說，我們的安全遠比牠們的要來得重要，果斷地行動吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29297] = {title = "掰掰鳥仔", objective = "用刺鳥矛殺死3名處於火鴉形態的火焰德魯伊。", description = "鹿盔的德魯伊在東北方的野火哨點激戰。\n\n德魯伊變成火鴉的形體盤旋在我們頭頂上，趁我們不注意的時候發動突襲。更可惡的是，他們太了解如何待在我們反擊不到的地方。若不是達密克借我厲害的刺矛，我們簡直束手無策。他說這些武器即使在濃霧密布時也會準確無誤地直射向天空的目標。\n\n用這矮人的武器射一些鳥下來!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29298] = {title = "覆滿煙塵的墜盒", objective = "將覆滿煙塵的墜盒帶去月光林地的永夜港給拉比恩‧薩圖納。", description = "這只墜盒的表面上有一些小小的葉形雕飾，但其他部分的細節就因為時間而磨損，或被火焰給燒去了。整個物件看起來似乎和德魯伊有關。\n\n大多數德魯伊都會在訓練時經過月光林地。如果有任何人能夠幫你解答出這只墜盒的來源，那將是永夜港的拉比恩‧薩圖納。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29299] = {title = "燙的好", objective = "觀察赤紅鞭笞者從6灘燼池中吸收液體。戰鬥中的燼唾蠍才會製造出燼池。", description = "我的研究有了不錯的進展，<name>。根據我們在本地植物身上看到的，高熱液體也很可能是鞭笞者的主要營養來源。\n\n我想請你幫我做個小小實驗。居住在北邊熔岩泉的燼唾蠍會在戰鬥中噴出燃燒的熔岩池。\n\n把鞭笞者帶去，看看他對燼唾蠍所吐出的燼池反應如何。", progress = nil, completion = "有效嗎？我的理論正確嗎？", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29302] = {title = "解開其中秘密", objective = "見證存放在覆滿煙塵的墜盒裡的回憶。", description = "墜盒上的名字看起來已模糊不清，但根據我從裡面感覺到的力量，其擁有者只可能是一個人:\n\n火焰德魯伊雷亞拉。\n\n退後，讓我們看看墜盒裡有著什麼樣的驚人事物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29303] = {title = "悲劇與家庭", objective = "將覆滿煙塵的墜盒帶去梣谷阿斯特蘭納附近的一處夜精靈墳墓。", description = "將這墜盒帶來給我相當明智，<name>。我是少數知道瓦爾斯坦葬身於何處的人之一。\n\n你可以在梣谷的阿斯特蘭納東南方的一個小小墓園那裡找到他的安息之地。將墜盒帶去那裡，那樣就能解開更多回憶。\n\n再見，<name>，祝你旅途順利。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29304] = {title = "戰爭工具", objective = "殺死5隻焦炭獵犬或上古焦炭獵犬。", description = "我們的部隊受到成群焦炭獵犬的襲擊。\n\n這群獵犬無所畏懼，而且永不休止，要直到牠們嚐遍我們所有人的鮮血才會滿足。我們幾乎擋不住牠們的攻擊。\n\n前往熔岩之流，加入我們位於灰燼之地那群守護者。也許你可以削減一下牠們的數量。", progress = nil, completion = "很好，&lt;class&gt;。敵人或許強大，但今天你證明了自己比他們更強大。", rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29305] = {title = "直擊核心", objective = "殺死火焰副官。", description = "拉格納羅斯的一名副官在拉格納羅斯之境現身了，就在我們東北方被牆圍繞的區域裡。\n\n我本來希望一等你回來就立刻派你過去，但我想萎枝和我們的部隊此刻已經在戰鬥了。你得快點行動。\n\n你應該能從這裡直接飛下峭壁，好快速與他們會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n世界之樹印記"}
MultiLanguageQuestData['tw'][29307] = {title = "烈焰之心", objective = "用250個悶燃精華為諾達希爾符文法杖充能，並取得烈焰之心。", description = "你是第一個親眼見識到龍族議會的凡人，<name>，而且是艾澤拉斯上少數能參與守護巨龍遴選的存在。\n\n晉升已賦予我超凡的力量，我自作主張加強了塔瑞克苟莎和你之間的連結，但她會需要一個更加...恆久的居所。\n\n我要你再次進入火焰界域，將拉格納羅斯的心臟帶來給我，這會是最後一次了。\n\n我們下次會面的時候，我將有能力適當地報答你至今所做的一切。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29308] = {title = "烈焰之心", objective = "用250個魂焰精華為諾達希爾符文法杖充能，並取得烈焰之心。", description = "你是第一個親眼見識到龍族議會的凡人，<name>，而且是艾澤拉斯上少數能參與守護巨龍遴選的存在。\n\n晉升已賦予我超凡的力量，我自作主張加強了塔瑞克苟莎和你之間的連結，但她會需要一個更加...恆久的居所。\n\n我要你再次進入火焰界域，將拉格納羅斯的心臟帶來給我，這會是最後一次了。\n\n我們下次會面的時候，我將有能力適當地報答你至今所做的一切。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29309] = {title = "傳說之物", objective = "和哈勒苟莎談話。", description = "很榮幸認識你，<race>。\n\n你的行誼在艾澤拉斯的凡人乃至不朽者之間如雷貫耳。\n\n我會在卡雷苟斯抵達時將拉格納羅斯的心臟呈獻給他。心臟的力量將被用來進一步附加到你的武器上。\n\n儀式很快就要開始。我被指派來這裡，在你做好準備時護送你前往那兒。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍怒，塔瑞克苟莎之眠"}
MultiLanguageQuestData['tw'][29310] = {title = "臨界點", objective = "將覆滿煙塵的墜盒帶去海加爾裡，位於雷亞拉的憂傷的一個小型墓碑。", description = "雷亞拉攻擊哈繆爾的那天，她在癒合之地西北方某個海加爾廢墟附近等待著。當時她的舉止有些奇怪:冷靜、沉默，怔怔望著遠方。也許那個地方對她有什麼重要性。\n\n將墜盒帶去那裡也許能觸發什麼反應。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29311] = {title = "往事已成歷史", objective = "將覆滿煙塵的墜盒帶去熔岩前線給瑪法里恩。\n\n已提供物品：\n", description = "在雷亞拉的記憶之中提到了瑪法里恩。她過去所承受的那些悲劇遭遇有絕大部分是他導致的，至少，在她眼中的確是這樣。\n\n瑪法里恩一定在雷亞拉成為火焰德魯伊之前就認識她了。你決定將帶著墜盒去火源之界找他，或許他能夠回答你剩下的疑問。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n雷亞拉的墜盒"}
MultiLanguageQuestData['tw'][29312] = {title = "傳說之物", objective = "和哈勒苟莎談話。", description = "很榮幸認識你，<race>。\n\n你的行誼在艾澤拉斯的凡人乃至不朽者之間如雷貫耳。\n\n我會在卡雷苟斯抵達時將拉格納羅斯的心臟呈獻給他。心臟的力量將被用來進一步附加到你的武器上。\n\n儀式很快就要開始。我被指派來這裡，在你做好準備時護送你前往那兒。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍怒，塔瑞克苟莎之眠"}
MultiLanguageQuestData['tw'][29313] = {title = "完美泡菜的秘訣", objective = "在達納蘇斯找到8個埋起來的泡菜罈。", description = "自從達納蘇斯創建以來，我們家族製作的泡菜就是最棒的，<name>。秘訣其實十分簡單，但也就是這樣才使它與眾不同。\n\n我們把泡菜罈埋起來，直到可以食用，而我最新的一批泡菜正好完成。你可以在城裡各地的土堆中找到罈子。你願意趁現在時機最好的時候，幫我收集起來嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29314] = {title = "緬懷祖先", objective = "從月神殿收集受過祝福的年糕。", description = "不只有生者需要進食。我的責任之一就是要替祖先準備年糕。通常，我的資深學徒會負責把年糕帶到月神殿去接受祝福，然後進呈給祖先。由於她今天出城去了，你可以替她完成這項工作嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29315] = {title = "蘑菇入侵", objective = "收集12個下水道蕈。然後帶回給幽暗城的尤奈斯‧伯奇。", description = "有些廚師在抱怨我們深愛的幽暗城沒有值得自誇的材料來做出一道真正美味的菜餚。\n\n那些只會在哭哭啼啼的笨蛋！\n\n到幽暗城西北方的下水管道那裡，收集些惡臭無比、滑溜的下水道蕈，然後帶回來給我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29316] = {title = "回歸基礎", objective = "幫助工匠區和貿易區的居民倒入黏米簍內的米以製作黏米粉。", description = "有些東西是每個人都需要的，從最基本家中的廚傭到烹飪大師都是如此。一座城市中最重要的主食就是黏米粉。大部分的家庭會在家裡起碼保存一袋黏米，住在工匠區和貿易區的居民也不例外。\n\n我常叫我的學生幫忙把黏米碾成粉，因為這不但是一種很好的練習，而且也是一個永無止境的任務。要不你也試試看？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29317] = {title = "釣顆頭來", objective = "阿曼德‧克倫威爾要你為藥劑大師法拉尼爾從幽暗城釣起一個被切斷憎惡體的頭。", description = "發生了一個…獸人守衛跟藥劑大師法拉尼爾的憎惡體…的事件。\n\n看來，柯爾克隆監督者把它的頭切下來然後踢到泥漿裡。\n\n法拉尼爾的學徒找了好幾個小時但是還是徒勞無功。想要試試看用釣的嗎？我確信老傢伙會很感激的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29318] = {title = "給哨兵的肋排", objective = "在營火或爐子使用未烹煮的肋排來煮熟它們，並用來餵食5名達納蘇斯的哨兵。", description = "我的職責之一就是讓在達納蘇斯執勤的哨兵能吃飽。這十分花時間，但是我十分樂意執行這項工作。這同時也是練習技能的好方法。你願意幫我準備今天的餐點嗎？只要拿這些肋排並在火堆或爐子中烤熟，然後分給城裡的哨兵就可以了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29319] = {title = "蝌蚪大災難", objective = "幽暗城的阿曼德‧克倫威爾要你帶給他8隻巨大食肉蝌蚪。", description = "我們有些藥劑師把廢棄的化學藥劑倒進了靜水池而…我只能說沒人想知道變異的吃人蟾蜍可以變大到什麼程度。\n\n你願意幫忙在這樣的事情發生之前釣起一些巨大食肉蝌蚪嗎？記得不要用手去抓就好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29320] = {title = "喜歡狗魚嗎？", objective = "去羅德隆廢墟的庭院挖出一條屍蟲然後當成魚餌來釣上一條食屍狗魚。可在位於幽暗城東北方的澈水湖釣上食屍狗魚。", description = "你在澈水湖釣過魚，是吧？\n\n釣上的大獎之一就是湖裡巨大的食屍狗魚。但是，牠們只吃特定的魚餌…屍蟲。\n\n去上方庭院的墓地那裡找找應該就可以找到一些。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29321] = {title = "挖蚌樂無窮", objective = "到魯瑟蘭村的海邊附近收集10個泰達希爾蛤蜊肉。", description = "看來每個我認識的人都愛蛤蜊肉，但我可無法忍受！它們又滑又臭，另外要挖蛤蜊就代表要挖土。任何時候只要給我一根魚桿跟些魚餌我就能夠釣起魚來。\n\n但是，我還是想要送上一籃新鮮的蛤蜊肉給我的兄弟一個驚喜。如果你願意幫我收集蛤蜊肉的話我會好好獎勵你的。\n\n穿過魯瑟蘭村的傳送門然後在海邊附近的陰暗處尋找那些蛤蜊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29322] = {title = "粘菌時間", objective = "收集10份蠕動的粘菌給幽暗城的阿曼德‧克倫威爾。", description = "只有特別的漁夫才會願意在幽暗城噁心的黏液中捕捉獵物。你願意去下面收集一些蠕動、具有智力的粘菌嗎?\n\n你可以試圖用釣的，但是牠們相當狡猾，你直接跳進去泥漿裡面用抓的可能比較快。\n\n記得，只有完整活著的才有用...誰願意吃死掉的粘菌?!噁心死了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29323] = {title = "進貨", objective = "在達納蘇斯釣到5條鯡形白鮭。", description = "我們為了照顧難民和家園生計被摧毀的人們，已經用掉大部分的存糧了。如果我們不補充存糧，下次有風暴來襲或部落入侵我們就危險了。\n\n也許你會願意幫我累積一些鯡形白鮭的存貨吧。你可以在達納蘇斯任何地方釣到牠們，只要曬乾就能長久保存。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29324] = {title = "姊妹的墜飾", objective = "從巨大鯰魚的腹中找到艾奎恩妮的月亮墜飾。你在達納蘇斯任何可以釣魚的地方都能釣到牠們。", description = "你見過我的姊妹艾奎恩妮嗎？她跟我在多蘭納爾一起受訓，而她最近才來到這個城裡的月神殿進修。我們決定要一起去划船，但是笨拙的船夫把船給弄翻了！\n\n等我們回到岸邊，艾奎恩妮的月亮墜飾不見了。達納蘇斯湖裡到處都是巨大的鯰魚，會把任何閃亮的東西吞下去！\n\n我一直不停的釣著牠們，希望能找到吞下墜飾的那一隻魚。你可以幫忙嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29325] = {title = "滑溜的點心", objective = "在魯瑟蘭村附近沙灘的淺水區收集6隻章魚寶寶。", description = "你有吃過章魚肉嗎?這可能需要試個幾次才會習慣，但這是我最愛的食材!我甚至還有認識人喜歡吃整顆的活章魚!\n\n我在短期之內是沒打算要嘗試啦，但是我已經沒有新鮮的章魚了。你能幫我收集一些嗎?牠們棲息在魯瑟蘭村附近沙灘的淺水區。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋亮晶晶的東西"}
MultiLanguageQuestData['tw'][29326] = {title = "諾達希爾之巔", objective = "在海加爾山的世界之樹底下和索爾談話，並見證陶土議會的儀式。", description = "哈囉，<class>!我在陶土議會的各位兄弟姊妹都對你在大災變中的表現讚譽有加。但為了治療這個受損破碎的世界，我們還有很多事得做。\n\n陪我走走吧，朋友。我們正在準備一個儀式，我期望這儀式能成為我們對抗暮光之錘的轉捩點。\n\n一切結束之後，你就能向眾人訴說我們在這裡的勝利。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29327] = {title = "元素桎梏:懷疑", objective = "和塞寇那斯談話以取得前往尋找索爾的通行許可。然後和折磨著索爾的風元素交戰，直到索爾自由為止。", description = "的確，我知道你在找的那個人…但我不知道追上他對你來說是不是好事。他將自己投入了龍捲風之中。狂風撕裂他的身體和心智，只留下破碎的血肉和無盡懷疑。\n\n追上他有可能為你帶來相同的後果。那銳利的風可以撕裂任何東西。\n\n你已經收到警告了。那麼，你的決定如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29328] = {title = "元素桎梏:渴望", objective = "殺死深淵止境附近的欲望浪潮和渴望漩渦，直到索爾脫離他們的掌握。", description = "再一次，<class>，我需要有你的協助才能成功。我會試著安撫這股暴風雨，但你得擊退圍繞在它周遭的不穩定元素。只有這樣我們才能解放高爾!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29329] = {title = "元素桎梏:耐心", objective = "當你準備好要幫助索爾的時候去和阿格拉談話。然後擊敗禁錮索爾的耐心元素和耐心核石。", description = "有了石母的祝福，我可以將我們送去到高爾被禁錮的位置。\n\n我們得多加小心。那裡到處都是暮光之錘的人。當我試著前往高爾身邊時，你得幫我抵擋他們!\n\n準備好就和我談話，我會將你帶到他的身邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29330] = {title = "元素桎梏:狂怒", objective = "在高地的西緣殺死阿格拉的風之圖騰旁的火元素，直到圖騰啟動。然後繼續前往阿格拉的水之圖騰、阿格拉的大地圖騰和阿格拉的火焰圖騰。", description = "圖騰，<name>!我們得啟動圖騰!否則高爾的性命堪憂!\n\n在高地周邊有我的圖騰，在圖騰旁殺死那些元素。一旦四個圖騰都被啟動，我們應該就能解放高爾的最後一片靈魂!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29331] = {title = "元素桎梏:誓約", objective = "在海加爾山的諾達希爾和索爾說話。", description = "在穿越通往海加爾山的傳送門之前，索爾要求你跟隨他。有件事他希望能與你一同見證。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "欲望披肩懷疑披肩狂怒披肩耐心披肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][29332] = {title = "百合，噢百合", objective = "收集10個靜水池百合。把收集的百合交給幽暗城的尤奈斯‧伯奇。", description = "生長在靜水池附近的百合可以熬成非常美味的肉湯。\n\n呃…所謂「美味」，我指的是不會馬上讓喝過湯的獸人覺得噁心。\n\n你何不去幫我收集一點，嗯？只要小心那些巨大的食肉蝌蚪就行。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29333] = {title = "美味蝸牛大餐", objective = "收集8隻澈水湖蝸牛。然後帶回去給幽暗城的尤奈斯‧伯奇。", description = "那些獸人守衛老是在抱怨幽暗城的食物太過於平淡無味且又腐壞難吃，好像他們光吃蘑菇跟老朽屍體無法果腹是「我們」的錯一樣，所以我想是時候讓他們知道，如果我們想要的話，他們也能夠嚐到多麼與眾不同的異國美食。\n\n到澈水湖收集生活在水底的淡水蝸牛，然後我就可以讓他們見識到真正的烹飪大師的能耐。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29334] = {title = "蟑螂車", objective = "收集20隻肥美的蟑螂。把牠們交給幽暗城的廚師奧德雷。", description = "那些柯爾克隆監督者不管怎麼抱怨幽暗城的食物，他們還是會吃光我姊妹奧德雷煮的超辣香脆燉蟑螂。\n\n這道菜如此受歡迎，害她的食材永遠不夠用。你可以幫她收集一些到她在販賣的小吃車那裡嗎？\n\n你可以在城裡找到很多陷阱，只要把陷阱裡面的東西帶給奧德雷，她就會解決剩下的問題了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n美食主義者的獎勵"}
MultiLanguageQuestData['tw'][29335] = {title = "勇闖切骨之風", objective = "在奧丹姆的南風崖和塞寇那斯談話。", description = "<class>，我拒絕相信我的高爾就這樣不在了。他的靈魂散佈在元素界域之間。只要他還存在，我們就能找到他，不過我需要你的援助。\n\n我們從風之界域開始。\n\n跟我說一聲，我們就能一起前往漩渦尖塔。我們必須和一個名叫塞寇那斯的元素交談。他的個性反覆無常，但風之界域裡的一切事物都逃不出他的眼睛。如果我的愛人在那，塞寇那斯會知道他的命運。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29336] = {title = "勇闖無盡之潮", objective = "前往瓦許伊爾的地獄深淵，在深淵止境和海德留斯談話。", description = "高爾一定是在水之界域…難道是深淵之喉？我不敢想像他在那裡要面臨什麼樣的命運。\n\n到深淵止境附近找元素海德留斯。他知道高爾的事，並且認同我們和拉格納羅斯的戰爭。如果有任何能幫助你的存在，那就是他了。\n\n我將和你在瓦許伊爾的波濤之下再見，<race>…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29337] = {title = "勇闖恆定之土", objective = "在地深之源的瑟拉贊恩王座和瑟拉贊恩談話。\n\n阿格拉能將你從深淵止境傳送到瑟拉贊恩王座。", description = "沒有時間了!我的愛人就在地深之源。只等你準備好，我就將我們一起送去那裡和石母瑟拉贊恩談話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29338] = {title = "勇闖無情之焰", objective = "到地深之源的穩固山脊和阿格拉說話以前往火源之界。", description = "我們必須立刻前往火源之界。在那個界域裡，高爾燃燒的靈魂甚至可能變得和拉格納羅斯一樣可怖!做好準備，我們要孤軍深入一個充滿的敵意的世界。\n\n準備好就和我談話...但願祖靈保佑我們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
