MultiLanguageQuestData['tw'][29382] = {title = "謝了，但就免了", objective = "如果你真的不喜歡你的禮物，你可以和一名燻木牧場的商人交談，來將它兌換成金幣。\n\n一經兌換概不退還。", description = "不一定每個人都喜歡節日毛衣。\n\n收據上說你可以在任何燻木牧場的商人那裡兌換現金。\n\n一經兌換概不退還。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n小氣財神的報酬"}
MultiLanguageQuestData['tw'][29383] = {title = "謝了，但就免了", objective = "如果你真的不喜歡你的禮物，你可以和一名燻木牧場的商人交談，來將它兌換成金幣。\n\n一經兌換概不退還。", description = "不一定每個人都喜歡節日毛衣。\n\n收據上說你可以在任何燻木牧場的商人那裡兌換現金。\n\n一經兌換概不退還。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n小氣財神的報酬"}
