MultiLanguageQuestData['tw'][29605] = {title = "兄弟鬩牆", objective = "釋放被囚禁的拉卡。成功解救拉卡之後，回塞司克大廳找伊斯法。", description = "塞司克在奧齊頓爆炸時離開了司凱堤斯。\n\n我的兄弟希斯是領導者的其中一員，他告訴我們有義務進入神廟廢墟去晉見我們的神。\n\n但後來，希斯因為我對他們起疑而把我逐出大廳，但他拒絕讓我帶走我的姐妹拉卡。你願意幫我救她出來嗎?您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "塞司克預言者項圈塞司克神諭者焦點鷹主項圈您能選擇下列奬勵中的一個：\n\n烏鴉護衛印記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][29606] = {title = "泰洛克的遺物", objective = "將泰洛克面罩和泰洛克羽毛交給塞司克大廳內的伊斯法。", description = "阿拉卡的英雄泰洛克有一天神秘地消失了，只留下他的面罩和矛。\n\n暗織者希斯還收藏著他的面罩，而鷹王伊奇斯則守護著他的矛。\n\n如果這兩樣東西能夠歸還給我們的話，這對我們的人民會是很有意義的象徵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "泰洛克之刺泰洛克的傳說泰洛克面罩您會收到：\n\n"}
MultiLanguageQuestData['tw'][29607] = {title = "慾望之眼", objective = "塞司克大廳內的商人維傑想要你帶3個巨蛇之眼給他。", description = "我有個買家對居住在這裡的鈷藍巨蛇的眼睛非常感興趣。\n\n如果你能幫我帶回一些這種稀世珍寶，我願意分點好處給你。\n\n成交嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29608] = {title = "在達拉然的盟友", objective = "搭乘獅鷲獸至達拉然，與「英雄光臨」旅店的伊斯拉米‧順風說話。", description = "歡迎來到北裂境，<name>。我收到指示要替你安排一趟達拉然觀光之旅，你便可與我們所有的盟友見面。\n\n搭乘獅鷲獸至達拉然，到達以後前往我們那裡的旅店 - 「英雄光臨」，找到伊斯拉米‧順風後立即和她說話。\n\n她可以幫你綁定爐石，這樣你就可以使用白銀領區的傳送門，迅速回到暴風城。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29609] = {title = "在達拉然的朋友", objective = "乘坐飛行管理員的載具至達拉然，然後和下流畜生酒店的『野獸』烏達說話。", description = "歡迎來到北裂境。我收到指示要替你安排一趟達拉然觀光之旅，好與我們城市中的朋友見面。\n\n準備好以後與我說話，然後搭乘載具至達拉然，到達以後前往下流畜生酒店。\n\n立即和『野獸』烏達說話。\n\n她可以幫你綁定爐石，這樣你就可以使用奪日者聖堂的傳送門，迅速回到奧格瑪。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29610] = {title = "追踪事件：玩家首次到达", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29611] = {title = "戰爭的藝術", objective = "到葛羅瑪許堡找納茲格寧姆將軍。", description = "不勝即亡，<race>。我是納茲格寧姆。\n\n你在此受命立刻前往葛羅瑪許堡。\n\n所有侍奉部落的成員都必須對他們的新大酋長宣誓效忠。\n\n別讓他等太久，<race>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29612] = {title = "戰爭的藝術", objective = "到奧格瑪的葛羅瑪許堡找納茲格寧姆將軍。", description = "不勝即亡，老朋友。距離我們上次談話已過了太久的時間。\n\n看到你平安脫離瓦許伊爾的深淵真讓我開心。\n\n我現在駐守在葛羅瑪許堡。\n\n所有侍奉部落的成員都必須對他們的新大酋長宣誓效忠。\n\n最好別讓他等太久，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29613] = {title = "正當的命運", objective = "殺死督軍卡利斯瑞，然後回蒸汽洞窟找看守者詹汗格。", description = "督軍卡利斯瑞負責整個蒸汽洞窟的行動。\n\n我要你去殺了他，<name>。納迦逼得我們只能選擇動用武力。\n\n絕不留情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29614] = {title = "牽制才是關鍵", objective = "殺死3個泥沼主宰、6個盤牙痲瘋者，然後從機電師蒸汽操控者那裡取得一個輻射裝置，然後回蒸汽洞窟找自然學家拜特。", description = "那些納迦正在與麻瘋地精聯手對贊格沼澤到處散播可怕的疾病。現在疾病已經蔓延至整個蒸汽洞窟了。\n\n把所有被感染的東西都清除，然後從機電師蒸汽操控者那裡把核心裝備帶來給我，動作快!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29615] = {title = "喚風者裂爪與偷水賊", objective = "殺死水占師希斯比亞，然後回蒸汽洞窟找喚風者裂爪。", description = "蒸汽洞窟是納迦主要抽乾贊格沼澤水源的重點區域，由水占師希斯比亞本人親自監督整個作業。\n\n幹掉她可以大大地阻礙整個行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29616] = {title = "搶攻蒸汽洞窟", objective = "和蒸汽洞窟的看守者詹汗格說話。", description = "我們無法阻止蒸汽洞窟內的納迦，我們大部分的抽水設施都在那裡。\n\n好在，我派出的遠征隊正在努力改變現狀。你願意去蒸汽洞窟助看守者詹汗格和她的隊員一臂之力嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29617] = {title = "天僧寺", objective = "到翠玉林的天僧寺找林‧嫩爪。", description = "來自潘達利亞各地的人們不遠千里，只為了到位於此處北方的天僧寺修行。或許是因為他們從不拒絕任何人吧。他們接受錦魚人、猴人...甚至像你這樣來自異域的<race>!\n\n我的童年玩伴小林幾週前才加入天僧寺。如果你有興趣學習武僧的修行之道，或許你該去跟她談談話!", progress = nil, completion = "你來的時機太剛好了。高階長者雲落同意在寺中收幾門弟子。這可能是我學得如何與人搏鬥的大好機會!", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29618] = {title = "高階長者", objective = "到翠玉林的天僧寺找高階長者雲落。", description = "真奇怪，竟然有這樣一個異國面孔的<class>來拜訪我們的寺院。你是來修行的嗎？\n\n你…你看起來非常強壯。你應該很輕鬆就能得到寺院的同意。你該去和高階長者談話，他就在上方的陽台。", progress = nil, completion = "歡迎來到天僧寺。我看到小林已經幫你了解過我們在這山村裡扮演的角色。\n\n我們這裡不常有外地人。有你在年輕弟子們的身邊受訓是我們的榮幸。除了知識，我們沒有其他事物能提供給你。當然，或許還有作為熊貓人的一點熱情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29619] = {title = "謙恭來客", objective = "在天僧寺南邊的林子裡收集8顆成熟的柳橙。", description = "我聽說了，我聽說了！高階長者希望你和我們一起接受訓練！\n\n還會有個為我們受訓弟子舉辦的宴會…出於禮貌，你應該要帶個禮物過去。\n\n寺院南邊林子裡的橙子正是特別甜的時候。帶些回來參加宴會吧。", progress = "你準備好參加筵席了嗎？我等不及了。", completion = "太完美了。真是設想周到的禮物，&lt;name&gt;！\n\n我？我當然是要帶啤酒囉。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29620] = {title = "大開筵席", objective = "到天僧寺的筵席場地找高階長者雲落。", description = "筵席隨時都會開始。去謁見高階長者，表示你的敬意。我會立刻跟上的。", progress = "訓練很快就會開始了，年輕的<class>。但在那之前，我們要談天說地、大吃大喝。\n\n不過我得說，我欣賞你的紀律。", completion = "自我介紹就到此為止了。你應該做好開始訓練的準備。\n\n實際上…你應該做好開始訓練的準備…在我們乾掉另一杯酒之後。兩杯也不錯。來吧，&lt;name&gt;！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29622] = {title = "訓練正式展開", objective = "到翠玉林的天僧寺找講師老詹。", description = "<曉自顧自埋頭苦吃。>\n\n嘿，新來的<傢伙/小姐>！很高興看到你從筵席裡全身而退！最初的試煉，過關！\n\n<曉大聲地吃著。>\n\n你最好去找講師老詹。他會期望你參加每日訓練。\n\n<他繼續大吃特吃。看來他的話已經講完了。>", progress = nil, completion = "先是喝了太多啤酒…然後你還上課遲到？看來你已經在身體力行熊貓人的文化了。\n\n來開始吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29623] = {title = "完美境界", objective = "在寺院的訓練競技場裡按照指導者的示範練習12次打擊。", description = "熟能生巧。訓練競技場中的每一個學生都總有一天能達到屬於自己的完美境界…只要他們沒有放棄的話。這是事實。\n\n我鼓勵你加入他們，<name>。作為寺院的貴客，你不需要每天練習10000次攻擊。只需要跟隨指導者的示範照做幾分鐘就好。", progress = nil, completion = "這不是你第一次戰鬥對吧？你的技巧並不完美，但確實有幾分架式。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29624] = {title = "專注", objective = "摧毀兩個訓練沙包。按照講師老詹的指示來決定打擊哪個沙包。", description = "你的下一個試煉與專注力有關。我希望你到下面的競技場去，在訓練沙包上練習你的技巧。\n\n沙包是兩個一組。當我說「左」，攻擊左邊的沙包。當我說「右」，攻擊右邊的沙包。\n\n如果你沒能跟上我簡單的指示，這項任務將變得更加困難。\n\n走吧，把那些沙包打爆再停止！", progress = nil, completion = "你或許不是全日在此受訓，但別因此阻礙你的學習。\n\n我敢保證，快速切換目標的技巧會在你未來的戰鬥中展現價值。", rewards = "琥珀霧之索黑木林腰帶玉巫婆護腰玻璃湖扣環絲林之索深林腰帶狐林腰帶雷木束腰翠玉虎束腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][29626] = {title = "園丁老吳", objective = "到翠玉林的天僧寺找園丁老吳。", description = "我們這裡沒有什麼規矩，但其中一條卻值得謹記。如果你想要吃…\n\n<曉的肚子大聲地咕嚕叫了起來。>\n\n…你就得工作。園丁老吳能給你一整天的工作。他就在西邊的市場裡。", progress = nil, completion = "&lt;老吳的話聲相當嚴厲。&gt;\n\n你是&lt;name&gt;吧？高階長者最看好的男弟子？是的，我記得在宴會上看過你。\n\n別期待我會給你任何特殊待遇，年輕人。你要和最菜的熊貓人一樣努力工作。\n\n或許要更努力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29627] = {title = "適當的武器", objective = "在天僧寺的市場附近取得6條藤莖細枝。\n\n向六月‧白花綻購買一瓶黑胡桃萃取物。\n\n向釀酒大師雷‧康來購買3瓶三倍加苦的酒。", description = "事有先後順序。\n\n一個好的受訓弟子需要適當的武器。而一個謹慎的受訓弟子會打造自己的武器…或至少收齊材料。\n\n附近的藤莖細枝應該能用來打造成各式各樣的武器。你也會需要購買黑胡桃萃取物來處理它。出去採購的時候順便買一些酒，好用來…\n\n<老吳停頓了一下。>\n\n…好吧，你知道酒用來幹什麼。", progress = "<老吳期待地看著你。>", completion = "&lt;園丁老吳感激地接過收集好的材料。&gt;\n\n等訓練接近尾聲，我會將你的武器準備好。現在，該談正事了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29628] = {title = "堅強的背", objective = "從蠟林裡的吳媽媽那裡取得沸騰的大鍋，然後回去天僧寺找園丁老吳。", description = "我們某些受訓弟子的胃口…比其他人更大。有時候我們沒辦法提供足夠的食物把所有人餵飽。像這種時候，我們得尋求協助。\n\n西北方有一位仁慈的老婦人願意幫我們的受訓弟子做一些燉湯。你只要過去把它們帶回來就好。", progress = nil, completion = "我會確認這些燉湯被平均分給受訓弟子們。\n\n當然，在我分出一些給自己之後。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29629] = {title = "穩健的手", objective = "從蠟林裡的紅葉花簇取得80瓶紅葉萃取物。", description = "你向白花綻小姐買的黑胡桃萃取物只是我們保存的各種藥劑之一。\n\n你可以從西邊蠟林裡的花取得紅葉萃取物。一朵花就能萃取出幾個單位，但只有自信冷靜、手指穩健的人有辦法抽出一朵花裡所有的菁華。", progress = "據說古老的草藥大師能從一朵花裡取出20瓶的萃取物。", completion = "不要忘了洗手。紅葉的顏色永遠褪不掉。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29630] = {title = "還有沉重的拳", objective = "到蠟林裡殺死10隻綠木欺詐者。", description = "確實，西邊蠟林裡的綠木妖精對我們沒有直接的威脅。然而，最近他們的數量大增，他們的狡詐也是。\n\n保衛這座森林和其中的平衡也是我們的任務之一。你的責任就是讓這些妖精回歸大地來完成這項任務。", progress = nil, completion = "謝謝你，&lt;name&gt;。妖精的數量用不了幾天就會回復，但至少在目前，自然的平衡得到維護。", rewards = "琥珀霧手套黑木林手套玉巫婆護手玻璃湖手套絲林手甲深林手套狐林護手雷木護手翠玉虎護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][29631] = {title = "熾烈燃燒", objective = "殺死6隻蠟林獵人虎。", description = "我能請你幫個忙嗎，學徒<name>?\n\n在進入寺院之前，我全然不熟悉作戰之道。在我接受訓練的期間，我孜孜不倦地練習，但我從未經歷過真正的危險。現在，身為結業弟子、同時也是個領薪水的守衛，大家期望我不惜一切代價保護這個地區。\n\n我有辦法料理綠木妖精，但西邊蠟林中的老虎是截然不同的挑戰。你願意幫我解決掉牠們嗎?", progress = nil, completion = "謝謝你，&lt;name&gt;。千萬分感謝，謝謝。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29632] = {title = "做好戰鬥準備", objective = "在天僧寺的比武中打敗8名天僧寺弟子。", description = "好了，<race>。我想看看你的實力。\n\n你會在僧院裡遇見很多我的弟子。挑戰他們。激發他們的極限。他們也受到指示要這樣對待你。\n\n不論輸贏，你們雙方都會透過戰鬥變得更強。", progress = nil, completion = "&lt;石拳大師小心地注視著你。&gt;\n\n好了，我看夠了。可以停止毆打我們的年輕弟子了。我們將進行下一個階段。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29633] = {title = "迅敏的熙熙", objective = "在天僧寺擊敗熙熙。", description = "在我右手邊的山丘上，你會找到名叫熙熙的猴人。他同樣在決鬥中多次勝出並提升階級。我想他應該會是更好的挑戰。\n\n面對他，試著擊敗他。", progress = nil, completion = "看來我得再次提升你的階級了，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29634] = {title = "乾癟的賀司涵", objective = "在天僧寺挑戰並擊敗賀司涵。", description = "錦魚人長久以來都是熊貓人的盟友，我們永遠歡迎他們踏入我們的寺院。他們的一名叫賀司涵的薩滿長者，最近加入了我們一起受訓。\n\n作為武僧，他的技巧頂多算不好不壞，但他仍然是個兇猛的鬥士。他應該是一個能與你匹敵的對手。", progress = nil, completion = "我得警告你，&lt;class&gt;。\n\n如果你再像這樣擊敗我最好的弟子，我恐怕都沒辦法訓練你了。那樣你就沒有藉口能享受我令人愉悅的陪伴。\n\n下次秒殺我弟子前，可要三思。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29635] = {title = "貪吃的曉", objective = "在天僧寺挑戰並擊敗曉。", description = "你可能已經在筵席上見過我最好的學生，曉。我個人認為他好幾屆之前就可以結業了，但講師老詹堅稱他需要更多的紀律。\n\n如果你問我的意見，我會說既然能打贏所參加的每一場戰鬥，紀律的意義倒也不大。我很好奇曉是否能對你保持他的連勝記錄。", progress = nil, completion = "我得承認，我一點也不驚訝，&lt;race&gt;。你是天生的鬥士，和一個傑出的&lt;class&gt;。", rewards = "竹風葉形臂鎧竹板鎧甲臂鎧狐林護腕竹板鎧甲裹臂竹風剝奪腕輪竹風剝奪護腕玉巫婆臂甲竹風葉形束腕竹風纖維腕輪您會收到：\n\n"}
MultiLanguageQuestData['tw'][29636] = {title = "耐力試煉", objective = "到天僧寺的西面找講師崔眠。", description = "我已經將我會的傾囊相授了，<name>。是你去找講師崔眠的時候了。\n\n和我所熟悉的拳法較量相比，她主持的格鬥較量比較不那麼傳統。不過，你這種雲遊冒險者的路途總是曲折的，擁有廣博的格鬥知識會對你很有幫助。\n\n再會，<name>，願你接下來的訓練能好運不斷。", progress = nil, completion = "你好啊，&lt;name&gt;。你在這裡的受訓者之間變得還挺有名的。我已經好幾次聽到有人在悄聲說著你的名字，通常是從你的一位陪練搭檔浮腫變色的嘴唇之間傳出來的。\n\n我很期待能和你共事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29637] = {title = "格鬥場", objective = "在心靈專注競技場點燃寺院煙火，然後在其中存活兩分鐘。", description = "石拳大師已訓練你一對一較量的技藝。現在你要學習一對多戰鬥的技巧。\n\n一對五十聽起來怎麼樣？\n\n到底下的心靈專注競技場去，準備好時點燃這個煙火。我的助手會數個一組朝你進攻。\n\n你要做的只有一件事，那就是撐過這些攻擊。", progress = "祝好運，<name>。", completion = "你身為&lt;class&gt;的戰鬥方式非常強大，&lt;name&gt;。我們的受訓弟子可以從你身上學到很多。", rewards = "心靈專注法杖講師之杖天僧法杖孤寂勝利者之劍孤寂勇士之斧翠玉步槍最後生存者戰利品內在平靜之錘皇家短刃寧靜之錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][29639] = {title = "火樹銀花", objective = "到翠玉林的天僧寺找高階長者雲落。", description = "你通過了我們為你準備的每一項測試，<name>。是時候讓你進入更大、更好的下一階段了。\n\n…但我們得先開個宴會！高階長者會在筵席場地等著為你慶祝從天僧寺結業。", progress = nil, completion = "恭喜，&lt;name&gt;。你的訓練十分嚴格，而你的成績無疑地令人印象深刻。年輕的弟子都向你看齊。\n\n園丁老吳準備了這個給你。請在你覺得適當的時候使用它。", rewards = "榮譽巨斧榮譽之劍天之防衛者天之保衛者榮譽之刃榮譽之錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][29640] = {title = "找尋間諜吐剛", objective = "找出奧齊頓的暗影迷宮內間諜吐剛的所在處。", description = "暗影議會已經殺死我們大部分的間諜，吐剛卻笨到逃出來了以後又潛返回去了!\n\n你得找到他。雖然他的行動十分魯莽，但我們還是需要他獲得的資訊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29641] = {title = "靈魂儀器", objective = "偷取5個靈魂儀器，並運送給奧齊頓暗影迷宮內的間諜葛瑞克薩。", description = "他們折磨我，試圖從我口中得知我腦袋裡面的資訊。\n\n他們把其他人拿去餵海爾瑪，而我就是下一個了。但我沒有告訴他任何事情!\n\n他們使用特別的裝置讓他們的召喚更具威力。你必須去偷盜這些裝置!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "薩塔式臂甲奧奇奈護腕間諜首領腕甲撒塔斯裹帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][29642] = {title = "奧齊頓的麻煩", objective = "到泰洛卡森林裡奧齊頓的暗影迷宮內，向戰場元帥瑪赫范報到。", description = "我在奧齊頓安排了幾名間諜，從他們的報告看來那兒情況不妙。那個地方從幾年前炸毀後就是個麻煩。\n\n據說那邊又再搞飛機了，這次暗影議會正在籌備戰事。雖然報告裡沒有說得很詳細，不過他們的準備活動看起來似乎是指向內部。\n\n，你必須想辦法到暗影迷宮。戰場元帥瑪赫范會告訴你應該完成什麼任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29643] = {title = "血之聖典", objective = "閱讀奧齊頓暗影迷宮裡的血之聖典。", description = "兩年前暗影議會喚來一隻生物粉碎了奧齊頓。\n\n去讀讀血之聖典，看到底發生了什麼事情。記住了，宗師瓦皮歐可是拼了老命守護這本書。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29644] = {title = "進入迷宮的中心", objective = "殺掉莫爾墨後，回到奧齊頓的暗影迷宮，通知戰場元帥瑪赫范裡頭發生的事件。", description = "暗影議會對兩年前召喚的強大生物失去控制了!\n\n我們只知道那隻怪物叫做莫爾墨，牠威脅打倒暗影議會並獲得自由來到外面的世界!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "薩塔式護脛奧奇奈長靴間諜首領長靴撒塔斯步靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][29645] = {title = "海爾瑪大使", objective = "殺死12個卡巴祭儀師和海爾瑪大使，然後回奧齊頓的暗影迷宮找戰場元帥瑪赫范。", description = "卡巴找到我們的間諜以後，他們被一個一個餵給海爾瑪大使。\n\n我們的夥伴需要有人替他們伸張正義。先殺死束縛海爾瑪的祭儀師，然後料理掉海爾瑪。\n\n這是他應得的報應。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29646] = {title = "火樹銀花", objective = "到翠玉林的筵席場地找高階長者雲落。", description = "我已經沒有什麼可以教你的了。其他人似乎也是一樣。\n\n高階長者雲落會在筵席場地等著慶祝你鵬程萬里。倒不是說我們很高興看到你離開…他只是喜歡慶祝。", progress = nil, completion = "恭喜，&lt;name&gt;。你的訓練十分嚴格，而你的成績無疑地令人印象深刻。年輕的弟子都向你看齊。\n\n園丁老吳準備了這個給你。請在你覺得適當的時候使用它。", rewards = "榮譽巨斧榮譽之劍天之防衛者天之保衛者榮譽之刃榮譽之錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][29647] = {title = "火樹銀花", objective = "到翠玉林的筵席場地找高階長者雲落。", description = "格鬥場已是你的最終試煉。你已經熟習天僧寺教給你的一切。\n\n你的修行從宴會開始，也將於宴會結束。高階長者雲落應該會在筵席場地上等你。我隨後跟上。", progress = nil, completion = "恭喜，&lt;name&gt;。你的訓練十分嚴格，而你的成績無疑地令人印象深刻。年輕的弟子都向你看齊。\n\n園丁老吳準備了這個給你。請在你覺得適當的時候使用它。", rewards = "榮譽巨斧榮譽之劍天之防衛者天之保衛者榮譽之刃榮譽之錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][29649] = {title = "如何拯救生命", objective = "地獄火堡壘內破碎大廳的先遣斥候查德威克要你去帶一個魔化餘燼回來。", description = "甘尼受到強大詛咒的關係瀕臨死亡的邊緣，<name>。\n\n而大術士奈德克斯用一對神秘的火盆來增強其力量。要是你能從火盆裡拿回一點餘燼，說不定可以用來中和黑魔法的效果?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "無懼手甲深刻符文腰帶遠征隊斥候肩冑維持手套助理牧師的靴子您會收到：\n\n"}
MultiLanguageQuestData['tw'][29650] = {title = "魔化餘燼", objective = "地獄火堡壘內破碎大廳的石衛士史托克頓要你去帶一個魔化餘燼回來。", description = "卡沙瑞斯被迫要懦弱地死去。\n\n大術士奈德克斯在他身上施放了一種可怕的詛咒。要是你能從火盆裡帶回一點餘燼給我，說不定可以用在悲劇發生之前中和黑魔法的效果?", progress = "你帶餘燼回來了嗎?卡沙瑞斯至少得死的像個英勇的戰士!", completion = "我將歌頌他的英勇事蹟。", rewards = "無懼手甲深刻符文腰帶遠征隊斥候肩冑維持手套助理牧師的靴子您會收到：\n\n"}
MultiLanguageQuestData['tw'][29651] = {title = "死者的榮耀", objective = "地獄火堡壘內破碎大廳的卡沙瑞斯要你殺死4個破碎之手的軍團士兵、2個百夫長和2個勇士。", description = "他們的精英戰士冷血無情，而且力量強大。\n\n<卡沙瑞斯吐出一口鮮血。>\n\n你必須殺死他們...否則我們絕對打不贏卡加斯...", progress = nil, completion = "卡沙瑞斯...已經不在人世了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29652] = {title = "最後一個忙", objective = "地獄火堡壘內破碎大廳的甘尼要你殺死4個破碎之手的軍團士兵、2個百夫長和2個勇士。", description = "可憐的老甘尼所剩時日無多...\n\n幫我最後一個忙，殺死你找到體積最大、最兇殘的魔獄獸人。\n\n念在舊情上，好嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29653] = {title = "大酋長的意志", objective = "將大酋長卡加斯之手帶回給地獄火堡壘內破碎大廳的石衛士史托克頓。", description = "卡加斯曾經是部落裡面最偉大的英雄。\n\n但是他現在走上歧途。將那把以他為名的武器帶回來給我，以後我們會永遠以當初英雄的身分紀念他，而不是他現在變成的怪物模樣。", progress = "你帶回卡加斯‧刃拳戰敗的證據了嗎?", completion = "我們不會忘記之前的獸人卡加斯，也不會忘記從他的隕落中所吸取的教訓。", rewards = "極致暗影魔棒殘拳頸飾牧師披風征服者的指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][29654] = {title = "扭轉劣勢", objective = "將大酋長卡加斯之手帶回給地獄火堡壘內破碎大廳的先遣斥候查德威克。", description = "只有一種實際的方式可以終結魔獄獸人對榮譽堡和聯盟的威脅。\n\n殺死他們的大酋長。\n\n將那把以他為名的武器帶回來給我，以後我們會永遠悼念他的忌日的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "剛勇守衛勳章納莉可的復仇生命賦予披肩痛苦之奈德克斯魔棒您會收到：\n\n"}
MultiLanguageQuestData['tw'][29655] = {title = "特殊的戰袍", objective = "殺死歐姆拉格並把它的戰袍帶回去給地獄火堡壘內破碎大廳的石衛士史托克頓。", description = "戰爭使者歐姆拉格是我見過殺死最多勇敢戰士的敵人。他不但冷酷無情、奸詐狡猾，而且力量非常強大。\n\n幹掉歐姆拉格然後把他的戰袍帶回來給我，我們可以用來裝飾旌旗並讓他們看看什麼是部落的憤怒之火!", progress = "戰袍到手了嗎?", completion = "幹得好。這可以讓那些嗜血如狂的傢伙們看清楚他們的對手是誰。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29656] = {title = "歐姆拉格的戰袍", objective = "殺死戰爭使者歐姆拉格並將他的戰袍帶回去給地獄火堡壘內破碎大廳的先遣斥候查德威克。", description = "暴風城想要看到我們在戰場上勝利的證據。\n\n與其給他們看裝屍袋，我想還不如拿卡加斯最兇狠的戰士，歐姆拉格身上的戰袍更有效果。可以幫我幹掉他嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29657] = {title = "能力越強，責任越重", objective = "阿達歐要求你前往風暴要塞的麥克納爾，殺掉機械領主卡帕希特斯。", description = "<一陣有如聖光般的聲音在你腦中響起。>\n\n麥克納爾運用我族科技製造法力容器，這些東西能提供絕大的能量。\n\n我需要你把機械領主卡帕希特斯解決掉，這樣一來，凱爾薩斯的大軍就無法取得能量了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29658] = {title = "操縱者", objective = "阿達歐要求你前往風暴要塞的麥克納爾，殺掉操縱者帕薩里歐。", description = "<一股微風輕柔地撫過臉頰。>\n\n只剩下最後一個任務要完成。\n\n操縱者帕薩里歐在他主人的許多行動中，身負監督重任。他要為這個世界最近發生的災禍負起個人責任。\n\n我要求你結束他的性命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29659] = {title = "消失的寶藏", objective = "到風暴要塞的麥克納爾，為阿達歐從軍團貯藏箱取回炫目狂怒。", description = "我感覺到，有人取走我輩文物，失竊的物品被存放在軍團貯藏箱裡面。\n\n不能給他們時間挖掘出藏於物品之中的力量。如果你願意替我除掉看守者，我會相當感激你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29660] = {title = "拯救波塔尼卡", objective = "阿達歐要求你前往風暴要塞的波塔尼卡，殺掉指揮官薩瑞尼斯、大植物學家費瑞衛恩及『看管者』索古林。", description = "凱爾薩斯在波塔尼卡的大軍無法管理那裡面的大量生物。我們要採取行動，修正他們犯下的錯誤。\n\n首先，就是要把這些大軍消滅掉，這樣他們就無法再製造什麼麻煩了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29661] = {title = "乾爽修行", objective = "跨越平衡樁並搖響訓練鐘。", description = "透過冥想，我試圖找出尋找水靈的方法。與此同時，你可以進行一些鍛鍊來提升自己。\n\n你的第一項任務是所有進入頌唱之池的受訓弟子都必須完成的:以不可掉入池水為前提，跨越西方的平衡樁並搖響訓練鐘。\n\n如果你掉入池中，池水的詛咒會讓你難以再次爬上平衡樁。你得回到池邊重新開始。\n\n對了，要小心那些鶴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "沒有損傷的索沒有損傷的腰環沒有損傷的腰帶完好的腰鍊帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][29662] = {title = "比蘆葦更強", objective = "收集8份特硬淚木蘆稈。", description = "替我從附近的池水收集蘆葦。\n\n別問原因。行動。然後觀察結果。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29663] = {title = "平衡樁修行", objective = "在平衡樁上擊敗6名土水武僧。", description = "我需要獨處時間來進行冥想。在我冥思尋找水靈所在地點時，你可以練一下你的身手。\n\n其他僧侶都在附近池水裡的平衡樁上做平衡與戰鬥的練習。過去擊敗他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29664] = {title = "挑戰者之焰", objective = "在閃曳烈焰火盆處點燃你身上的未點燃的挑戰者的火炬，然後用火炬點燃李飛大師身邊的三個火盆。", description = "你擁有強大的心智和意念，但仍缺乏與我互搏的技術。儘管你必須運用身體來戰鬥，實質受考驗的卻是你的品性。\n\n讓我平衡一下遊戲規則吧。\n\n帶上這束火炬，用我身旁的火盆點燃它，然後用它點燃池水周圍那三個熄滅的火盆。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29665] = {title = "每下愈況", objective = "擊敗8隻深海折磨者。", description = "船隻失事後，成群的邪惡生物從海中竄出，將船骸大肆搜刮了一番。和他們今天所遭受的不幸相比，我們的援助簡直就是滄海一粟。\n\n擊敗這些深海折磨者。這群人急需我們的幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29666] = {title = "修行的苦處", objective = "殺死6隻水黽。", description = "池水中潛伏著危機。近來最凶惡的就是水黽。削減牠們數量的時刻已經到來，而我不再有能力擔起這項任務。\n\n如果你能幫忙除掉一些水黽，我會非常感激。小心牠們的數量…一般來說從池邊誘出牠們會是比直闖進去更好的策略。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29667] = {title = "汰弱扶強", objective = "阿達歐要求你前往風暴要塞的波塔尼卡，殺掉6隻突變的鞭屍者、6隻突變的恐懼尖嘯者、6隻突變的恐獸，然後取得拉杰身上的飛躍進化藻葉。", description = "波塔尼卡的物種在凱爾薩斯的大軍手中扭曲，這已無可挽回。我不希望看到它們被放出去，外域已經有太多太多了。\n\n這些物種中，有個我很想研究的對象，那就是拉杰。這個生物不太一樣，也許可以從它身上得到什麼資訊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29669] = {title = "最嚴峻的工作", objective = "阿達歐要求你前往風暴要塞的波塔尼卡，殺掉扭曲分裂者。", description = "此刻，我必須要求你完成一項極為嚴峻的工作。\n\n扭曲分裂者原本的職責應該是守護整個波塔尼卡，但現在卻墮落了，必須將其除掉才行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29670] = {title = "突擊戈爾莫營地", objective = "在戈爾莫營地裡殺死征服者戈爾莫。", description = "多虧了你，有一小支由農夫組成的民兵埋伏在附近。漢妮提過會給他們「藉酒壯膽」什麼的，所以我肯定，那代表他們現在都已經醉醺醺而且發起酒瘋。\n\n魔古以為能隨意宰割我們，讓他們瞧瞧我們的厲害吧。\n\n順著小路穿過遺跡，到海灘那裡去，找到他們的領導者。在你和他交戰時，我們會出來協助你。", progress = nil, completion = "這真是令人極度不安。如果魔古像這樣在大陸各地集結起來，將成為潘達利亞的重大威脅。", rewards = "您能選擇下列奬勵中的一個：\n\n絲珠塑像鏡像水黽紋章綠爪塑像生命之箭迷霧翠玉塑像\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][29671] = {title = "The Black Morass", objective = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.完成任務後，你將獲得：\n\n", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29672] = {title = "开启黑暗之门", objective = "时光之穴黑色沼泽的萨艾特要求你保护麦迪文，直到他成功开启黑暗之门。\n\n任务完成后向萨艾特复命。", description = "守护者麦迪文正在这里兴奋地忙碌着，想要打开黑暗之门。\n\n但沼泽四周将会出现许多裂隙。永恒之龙会涌出裂隙，试图破坏麦迪文的法力护盾，最终杀死麦迪文。\n\n消灭裂隙领主和他们的首领！保护麦迪文，直到黑暗之门成功开启。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "守衛指環時光扭曲寶石虔誠之堅護者指環您能選擇下列奬勵中的一個：\n\n安杜姆的眼淚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][29673] = {title = "The Black Morass", objective = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.完成任務後，你將獲得：\n\n", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29674] = {title = "無縛黑暗", objective = "阿達歐要求你前往風暴要塞的亞克崔茲，殺掉無約束的希瑞奇斯。", description = "<令人擔憂的警鈴聲傳入耳中。>\n\n我們將旅途中碰到最兇惡的生物關在這裡。\n\n希瑞奇斯是一名強大的虛無領主，如果它逃進虛空風暴，外頭充沛的虛無能量將會把它餵得飽飽的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29675] = {title = "嘿，達利亞", objective = "阿達歐要求你前往風暴要塞的亞克崔茲，殺掉怒鐮者索寇斯瑞特與末日預言者達利亞。", description = "怒鐮者索寇斯瑞特與末日預言者達利亞，這兩名強大的燃燒軍團代理人，已經開始集結惡魔，同時形成一支小規模的部隊了。\n\n不能讓對方的聲勢再壯大下去，否則恐怕要不了多久，亞克崔茲就會變成另一個燃燒軍團的要塞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29676] = {title = "尋訪老友", objective = "到頌唱之池裡的梁的居所找梁老頭。", description = "在頌唱之池的這些年，水之靈‧舒似乎有個玩伴。一位名為梁老頭的老熊貓人。\n\n不久之前，梁老頭搬離主城鎮，不再到泉水這裡練習。我聽說他住在東北方山丘上的一間小屋子裡。\n\n梁老頭或許知道舒離開的原因，以及祂可能的所在地。\n\n去找梁老頭，向他打聽舒的資訊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29677] = {title = "太陽珍珠", objective = "取得太陽珍珠。", description = "水之靈‧舒長生不老，如同所有神真子上的其祂靈一般。我已經和舒做了一輩子的朋友，但我不再有能力和祂一起嬉戲。我老了，沒有力氣。\n\n不論其祂的複雜之處，取悅舒相當容易:祂渴望友情。每個季節，當我回去找舒玩時，我總是會帶上太陽珍珠作為禮物，然後我們才玩在一起。前往東南方的深水池，你能在那裡找到太陽珍珠。或許你可以成為祂的新朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "太陽珍珠手套太陽珍珠外衣太陽珍珠護腕太陽珍珠鎖甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][29678] = {title = "水之靈‧舒", objective = "哄水之靈‧舒一起遊戲。", description = "水之靈‧舒在北邊的深水池裡悶悶不樂。穿越石塊然後把太陽珍珠丟進池水中央。祂會知道這是什麼意思。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29679] = {title = "新朋友", objective = "游進水靈的5道水柱裡。", description = "祂想要你陪祂玩。去吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "俏皮的腕環水花手套閃耀胸甲水花護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][29680] = {title = "生命之源", objective = "到戴洛農莊找紀。有輛車子在道路附近等著將你載去那兒。", description = "我們完成尚羲大師交代給我們的任務了。我將回到寺廟，向大師稟告我們的進展。你該沿路南行，到一處農莊裡找尋大地之靈‧烏果。\n\n紀在戴洛農莊等著，他肯定需要你的協助。我得警告你，紀的率直也代表著魯莽。要謹記我在這裡教導你的:紀律與耐性。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29681] = {title = "突破安管極限", objective = "阿達歐要求你前往風暴要塞的亞克崔茲，殺掉先驅者史蓋力司。", description = "先驅者史蓋力司是亞克崔茲的問題核心。\n\n它腐化了看守者米利恰爾，使他釋放了許多囚犯。先驅者重獲自由只是時間問題而已。\n\n<name>，不能讓上古之神的奴僕存活在這世上!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "權勢薩塔垂飾撒塔斯力量頸飾阿達歐的恢復項鍊您會收到：\n\n"}
MultiLanguageQuestData['tw'][29682] = {title = "博學者殿堂", objective = "塞里斯‧曦爐上尉要你進入博學者殿堂找主教雷索爾。", description = "我們最近派遣了一支遠征隊進入博學者殿堂阻止燃燒軍團的大軍。\n\n不過，至今為止仍未收到任何回報，我擔心最糟的情況發生了。\n\n你願意進去，看看能不能找到主教雷索爾嗎？這支隊伍是由他率領的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29683] = {title = "占星球", objective = "塔雷斯要求你使用魔导师平台内的阳台上的宝珠。", description = "<塔雷斯一边说话，一边痛苦地抽搐。>\n\n去……去平台上，使用那颗宝珠。\n\n……它们正在……为太阳之井输送能量……\n\n<塔雷斯艰难地喘着气。>\n\n快点……必须马上阻止他们……不要等到他们……\n\n<塔雷斯咽下了最后一口气。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29684] = {title = "中斷的通訊", objective = "博學者殿堂的主教雷索爾要你找出血精靈間諜提里斯。", description = "我們派人潛入博學者殿堂收集情報，到現在已經有一段時間了，不過我們無法和他取得聯繫。\n\n他手中的情報攸關重大，任務成敗全繫於此。", progress = nil, completion = "...&lt;race&gt;...靠過來點...聽清楚...我接下來要說的...", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29685] = {title = "打不死的小強", objective = "卡雷苟斯要求你擊敗博學者殿堂的凱爾薩斯。你要帶著凱爾薩斯的頭在博學者殿堂裡面向雷索爾回報。", description = "如你所見，燃燒軍團的部隊正在不眠不休地工作，想利用太陽之井的力量來完成他們邪惡的目標。\n\n凱爾薩斯已從失敗的灰燼中復甦，再度領導他們。一定要阻止他。", progress = "很好，<class>，我必須承認，我原本不太確定是否會再見到你。", completion = "&lt;雷索爾專心地聽著你述說在博學者殿堂的事情。&gt;\n\n我們會懷念提里斯的，他是個好人。感謝你，沒讓他的死白費。", rewards = "您能選擇下列奬勵中的一個：\n\n精緻的赤紅尖晶石明亮的赤紅尖晶石\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][29686] = {title = "根本信念", objective = "博學者殿堂的主教雷索爾要你殺死維克索魯斯，取得它的精華。", description = "我們在這場戰爭中經不起傷亡損失。我打算為哨衛進行強化，這樣一來，英勇的男男女女就不需要葬送自己的生命。\n\n燃燒軍團拘禁了一隻強大的元素生物，我們需要的正是它的精華。", progress = "你能拿到它的精華嗎?", completion = "棒極了!我等不及要把這項計畫呈報上去了!", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29687] = {title = "邪惡的結合", objective = "博學者殿堂的主教雷索爾要你殺死賽林‧炎心與女牧師戴利莎。", description = "燃燒軍團和凱爾薩斯大軍之間的關係越來越緊密，我為此深深擔憂。\n\n從我們獲得的消息指出，賽林‧炎心與女牧師戴利莎共同合作，想讓兩支軍隊更加緊密結合。你必須阻止他們。", progress = nil, completion = "很好，大兵。一步一腳印，確實完成目標。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29688] = {title = "戰況逼近", objective = "暗影獵手泰巾要你去和地獄火堡壘內破碎大廳的石衛士史托克頓說話。", description = "我大部分的時候都在聆聽，<class>。我幫大酋長接收訊息，這樣他就無需親自處理這些繁瑣的事情。\n\n我聽說了有關於對抗地獄火堡壘戰役的狀況。是時候進攻破碎大廳了，魔獄獸人的權力之座。\n\n去和石衛士史托克頓談話，他負責那邊的事務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29689] = {title = "戰況逼近", objective = "軍隊指揮官達納斯‧托爾貝恩要你去地獄火堡壘的破碎大廳找先遣斥候查德威克交談。", description = "是時候給魔獄獸人最後一擊了。\n\n先遣斥候查德威克在地獄火堡壘的破碎大廳等你。動作快，他們隨時都準備攻擊榮譽堡!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29690] = {title = "進入霧中", objective = "到地獄吼之拳上找納茲格寧姆將軍。", description = "<納茲格寧姆將肺部吸滿了海上的空氣。>\n\n你聞到了嗎，<name>？是我們家鄉的味道，我們流血捐軀所保護的土地。\n\n你聽…你聽到了嗎？是和平與安全的味道。我們所雕塑出的天堂，一個我們敵人不敢踏上的地方。\n\n記住這一切。短時間內，你是無法再次擁有像這樣的感受了。我們有一場仗要打。\n\n現在，就好定位。我們要出發了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29691] = {title = "給我木槿花!", objective = "收集5朵血紅木槿，交給深幽泥沼的塔蘇。", description = "對我們來說，在很多地方都會用到血紅木槿。\n\n不過這種花只生長在深幽泥沼，而且那邊有一堆傢伙喜歡這東西。\n\n你要是能幫我帶些過來，我會很感激你的。", progress = nil, completion = "這些花很合適，但是不太夠。或許你很快就會再來深幽泥沼?", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29692] = {title = "再給我木槿花!", objective = "這些花很合適，但是不太夠。或許你很快就會再來深幽泥沼?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29694] = {title = "重新整隊！", objective = "在甘露林地解救影王卡玲、理弗特‧窩爆、修基雅和士官哥羅克。", description = "他們有個空軍基地！我低估了這個聯盟艦長的能力了。我們失去了這麼多的好戰士…\n\n一定還有少數倖存者撐過了墜毀。我們需要每一名有能力戰鬥的戰士。\n\n到底下的森林去，盡可能找尋生還者。我會親自調查殘骸。將所有人集合到附近的村莊，準備反擊。", progress = nil, completion = "你只能找到這一點倖存者嗎，&lt;name&gt;？\n\n好吧。我們沒有其他選擇，只能面對命運帶給我們的挑戰。\n\n\n\n去他的人數。英雄就是這樣誕生的。", rewards = "冒煙砲艇支柱金浚的矮人斬斧回收的翼片刃被砲彈砸凹的盾牌猴人打擊錘海員的登船木板您會收到：\n\n"}
