MultiLanguageQuestData['tw'][29703] = {title = "Barrel of Monkies", objective = "Sally Fizzlefury wants you to kill 5 drunken monkies.", description = "These monkeymen are driving me insane!  I was just trying to get some insight into panderan brewing tactics and these hozu things keep drinking the brews before I can properly chemical test them.  Can you please go take a few of them out as a lesson to the others?  I'll make it worth your while.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
