MultiLanguageQuestData['tw'][29715] = {title = "林中巫女", objective = "到玉巫婆小屋北邊的道路找安‧風毛。喔，拜託！你能幫我嗎，<race>？\n\n村裡有些孩子跑到樹林裡玩就沒有回來。如果你正要前往那附近，能請你幫忙注意一下嗎？\n\n我已經和那些搗蛋鬼說過別去打擾林子裡的老寡婦，但我猜他們還是跑去騷擾她了。他們覺得她是個巫婆。", description = "喔，拜託！你能幫我嗎，<race>？\n\n村裡有些孩子跑到樹林裡玩就沒有回來。如果你正要前往那附近，能請你幫忙注意一下嗎？\n\n我已經和那些搗蛋鬼說過別去打擾林子裡的老寡婦，但我猜他們還是跑去騷擾她了。他們覺得她是個巫婆。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29716] = {title = "猴人大挑戰", objective = "解救6個受驚嚇的小熊貓人。", description = "樹林裡有個巫婆，但沒有人相信我。她把我的朋友小新變成玉了！\n\n我們都好害怕，試著跑回去，但她派她的大玉怪獸來抓我們。我有很多朋友逃到樹上去了。\n\n你能幫忙去救我的朋友嗎？", progress = nil, completion = "喔謝謝你幫助我的朋友。但我還是沒看到小新…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29717] = {title = "壞貓咪!", objective = "摧毀8隻翠玉守護者。", description = "我試過和樹林裡的玉虎戰鬥，但牠們太可怕了。牠們會瞪著你，然後你就變成一座玉像！\n\n真的！小陳的姊姊的朋友小妮從小凱的媽媽那裡聽來的！\n\n但我想像你一樣勇敢。你能讓我看看你會怎麼對付牠們嗎？", progress = nil, completion = "哇!你好棒!你就像這樣「砰」然後他們就像「啊啊啊」然後他們就被打爛了!", rewards = "喵喵指環碎玉者指環風毛指環風毛戒指安的戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][29723] = {title = "玉巫婆", objective = "擊敗玉巫婆。", description = "玉巫婆一定還抓著小新。\n\n我…我做不到！我不想看見那個巫婆。拜託，你能不能去問她小新是不是在她那裡？你是個大人。我想她不會想把你變成玉。", progress = nil, completion = "喔耶!太感謝你了!小新得救了，你也痛扁了老巫婆!最棒的是我們的父母永遠也不會知道我們幹了什麼。喔耶!\n\n看來每個平安回來的人都很想擺脫身邊所有的玉。托亞不知道為了什麼在收集這些玉，還說你應該過去找他。", rewards = "您能選擇下列奬勵中的一個：\n\n翠玉浣熊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][29725] = {title = "軍情七處報告:天火降臨", objective = "聽取蘇利的報告。", description = "是的，我們找到了琥珀，她還活著，一切都好。但這大概就是唯一的好消息了。\n\n我試試看能否接著老瑞爾的話往下說…", progress = nil, completion = "現在你知道老瑞爾的遭遇了。\n\n&lt;你發現蘇利臉上的表情有了一些轉變，並快速轉過頭去。他…在哭嗎？&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29726] = {title = "軍情七處報告:敵對原住民", objective = "聽取小小盧的報告。", description = "我…我可以告訴你接著發生了什麼！我們繼續往北，進入森林…", progress = nil, completion = "幸運的是，所有人都活著出來了。\n\n嗯…所有人，除了襪子之外。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29727] = {title = "軍情七處報告:不留活口", objective = "聽取琥珀‧吉爾妮的報告。", description = "我們最後一段旅程將我們帶向西方一座大型猴人村落。我們避開他們的視線，在山間設立了一座小型營地…", progress = nil, completion = "這就是全部了。我們沒能找到白棋，但我們帶回了對聯盟更加至關緊要的情報。\n\n部落和猴人締結了同盟，不斷將他們武裝起來。如今，部落和他們的猴子大軍，數量已經是我們的三十倍之多。", rewards = "月水戒指龍脊指環伏虎指環恢復戒指花綻戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][29730] = {title = "偵察報告：敵對原住民", objective = "聽取瑞可的報告。", description = "我敢說你的第一個問題是：「士官哥羅克發生什麼事？」不要擔心，不要擔心。他活得好好的。沒有死掉之類的。\n\n<瑞可很侷促地欲言又止。>\n\n好吧，我們「覺得」他還活著，但他也很有「可能」死得很透、很透。\n\n<瑞可看著你的眼睛，探索著你的想法。>\n\n好啦！讓我告訴你到底發生了什麼事。", progress = nil, completion = "所以你懂了，這不是瑞可的錯。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29731] = {title = "偵察報告：正確線索", objective = "聽取卡玲的報告。", description = "瑞可說的大多是真的。\n\n我們不敢去追哥羅克，部落在這裡的人數太少了。我們的部隊只能承擔少部分的損失，而老實說，我們真不知道那個女巫究竟有多強大。\n\n讓我接著猴人的那段說下去…", progress = nil, completion = "那就是我們找到這個聯盟俘虜的過程。\n\n但那不是一切的經過。還差得遠了…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29733] = {title = "軍情七處報告:葬身林中", objective = "聽取瑞爾的報告。", description = "<瑞爾開口前先重重咳了一陣。>\n\n拜託，<name>。你得聽聽我們經歷了什麼。\n\n整個該死的聯盟都需要聽聽我們經歷了什麼。時間剩下不多了。", progress = nil, completion = "…那就是&lt;咳&gt;我們怎麼找到…\n\n&lt;瑞爾的話轉變成強烈的咳嗽。他的嘴角滲出一縷血絲。&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
