MultiLanguageQuestData['tw'][29743] = {title = "異變之境", objective = "收集每一塊古老雕像碎片的素描。", description = "這雕像和周遭的廢墟看似相當古老。顯然，這片土地歷史悠久，肯定不是在最近的大災變中形成。\n\n然而，這一帶的水域歷經數個世紀的探索，除了一片汪洋之外沒有任何紀錄。\n\n也許，若你用這古老雕像的碎片拼出個輪廓，就能稍微了解這塊大陸的由來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29744] = {title = "「自然之瞳」什麼的", objective = "調查綠石採石場東北方的迷失者之林。", description = "林中妖精並不喜歡閒晃，所以我很訝異他們竟然會跑到像石匠區這麼遠的地方來。一定有什麼東西迫使他們違背了天生的慣性。\n\n這些妖精是北邊那座迷失者之林裡的原生種。我很想自己去，但我聽說樹林裡鬧鬼。\n\n所以沒錯，就這樣吧。\n\n看來我們永遠也不會知道真相囉。\n\n<老黃發出乾咳。>\n\n除非…有個像「你」這樣大隻又勇敢的冒險者可以過去看看狀況！你怎麼說？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29745] = {title = "妖精之難", objective = "在迷失者之林摧毀10個石縛毀滅者，並找出他們的來源。", description = "<活生生的雕像在樹林中肆虐。>\n\n<目前，他們似乎滿足於把森林妖精打爆的運動，但若這樣繼續下去，熊貓人們可能會有比玉石消失更大的事得去擔心。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29747] = {title = "斬草除根", objective = "在十方雷殿殺死8名衫織縛靈者。", description = "<魔古咒術師從遠方召喚來不幸的魂靈，強迫他們進入雕像。\n\n看來光是摧毀雕像還不足以斬草除根。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29748] = {title = "魔傀碎片", objective = "在十方雷殿踢爆6具未被附身的毀滅者。", description = "<古老魔古雕像的破碎殘骸。它在破裂前還不曾活動起來過。\n\n不管魔古在這裡用了什麼樣的黑暗法術，似乎都讓這雕像變得更加堅硬了。可以的話，最好趁它們被附身前，把它們摧毀掉。\n\n一記老式的前段踢應該可以搞定。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29749] = {title = "迫切的請求", objective = "取得培志之杖，並到十方雷殿的中心打斷咒法儀式。", description = "<你的腦中傳來一陣嚎聲。嚎聲之後，藏著一道渺不可聞、彷彿來自遠方的聲音。>\n\n請...幫幫忙...廢墟中心...儀式...咒法...\n\n...不該在這裡...\n\n我的杖...在祭壇上...取走它。快點。", progress = "靈縛之術!怎麼能有人容許魔古恢復這種噁心的技藝?!看看我，半失敗的咒法產品...\n\n<魂靈氣得七竅生煙，然後轉向你。>\n\n現在是哪個世紀了?", completion = "請容我自陳來歷:我是培志，侍奉最後一位熊貓人皇帝，紹昊陛下的首席靈魂先知。\n\n應該說...曾經是。", rewards = "犧牲之斧靈魂粉碎者靈魂賢者保衛者靈魂賢者之盾縛靈月牙刀縛靈之斧您會收到：\n\n"}
MultiLanguageQuestData['tw'][29750] = {title = "魂靈容器", objective = "從十方雷殿的衫織靈爪那裡取得8個靈魂之瓶。", description = "靈爪是一脈魔古族的僧侶刺客。在魔古帝國的全盛期，他們是皇帝旗下最令人畏懼的菁英部隊。\n\n他們全都精通能捕捉敵人魂靈的死亡重擊，將對方封鎖在玉瓶裡，交給縛靈者。\n\n如果你在廢墟裡遇到任何靈爪，要記住：他們的腰帶上懸掛著魂靈的重擔。\n\n解放這些魂靈，將玉瓶帶回來給我。", progress = "想到這麼多年來，魔古竟然還在繼續訓練靈爪…\n\n你拿到瓶子了嗎？", completion = "謝謝你，&lt;class&gt;。\n\n我已經能感覺到這些瓶子裡的魂靈，他們在哭喊，哭喊裡充斥著恐懼、迷惑…以及憤怒。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29751] = {title = "儀式文物", objective = "在十方雷殿裡取得一只有缺口的儀式碗、一根刺鼻的儀式蠟燭和一個玉琮，並交給培志。", description = "有這麼多的魂靈被禁錮在這裡…我能感應到他們存在於每個地方。就連這些牆壁都是他們的牢籠。\n\n<name>，光是打破此地的咒法還不夠，這樣只會將無數的痛苦靈魂釋放到大地上。他們需要一個信標來指引他們。\n\n透過你的幫助，我可以創造出「天橋」：一座連結現世和天界的橋樑。為了準備這個儀式，我會需要一只碗、一根蠟燭和一個玉琮。你應該能在廢墟中找齊這些東西。", progress = "你找來儀式用的物品了嗎？少了它們，我們無法引導魂靈們回到該去的地方。", completion = "做得好。有了這些，我就能完成將此處包括我在內的所有魂靈，送回應屬之處的儀式。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29752] = {title = "固執的亡靈", objective = "在十方雷殿使用培志之杖以吸收10名固執的先祖。", description = "像魔古在此處施展的這種大型咒法，少不了會產生副作用。有些被召來的魂靈太過狂暴或難以駕馭，因而遭到禁錮並棄之不顧，他們只能不斷地虛度光陰，直到他們因絕望而變得更好操控。\n\n我懷疑魔古在附近建立了這樣的禁錮場所，這些場所很有可能受到靈爪的保護。\n\n請再次帶上我的杖去聚集這些固執的魂靈。你不用和他們戰鬥，只要亮出法杖，他們應該就會被吸引過來。", progress = nil, completion = "謝謝你，&lt;name&gt;。我會帶他們一起前往亡者的世界。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29753] = {title = "回到自然", objective = "將靈魂之瓶丟到潮霧林地的地上來解放8隻野獸之靈。", description = "恐怕我還得請你幫另外一個忙，<name>。\n\n你找回的瓶子裡裝載了既非魔古先祖，也不是最近被殺害敵人的魂靈。那是一些野獸的魂靈。看來靈爪們得透過盜獵來建立他們的魔傀大隊。\n\n這讓我們的任務變得更複雜了，因為野獸沒有辦法度過「天橋」。\n\n將這些瓶子帶去西邊的潮霧林地，擊碎它們，讓這些魂靈返回自然。有些野獸之靈或許會被憤怒蒙蔽雙眼而需要馴服。", progress = nil, completion = "牠們的身體回歸大地已久，這樣牠們的魂靈也能跟上了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29754] = {title = "橋接天地", objective = "在十方雷殿保護培志進行儀式。", description = "我們準備好打開天橋，並引領魂靈們前往安息之地了。\n\n如果可以，我想再請你幫忙一次。儀式開始後，魔古肯定會有所感應，並盡一切力量來阻止。我只需要片刻不受打擾的時間。一旦天路開啟，那洶湧的力量將使它無法再被關閉。\n\n如果你願意再幫忙一次，請陪我前往儀式地點。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29755] = {title = "報復", objective = "到十方雷殿的喚魂者之座面對汕吉通並救出培志。", description = "<先祖們的魂靈湧上培志的天橋，擁抱自由。\n\n天橋北邊的廢墟中還有最後一個房間。邪惡的能量在其上空吱啪作響。汕吉通在行動了。>", progress = nil, completion = "想必是這個激盪的時代孕育出像你這種的英雄。我只能想像未來的旅程會是多麼壯闊的冒險。\n\n能遇見你是我的榮幸，&lt;name&gt;。\n\n我會留在這裡引導所有的魂靈，然後才自己跨過天橋。\n\n但我仍困擾於喚魂者死前的詛咒…\n\n「你阻止不了雷王的。」\n\n他這樣說是什麼意思？", rewards = "琥珀霧披肩黑木林肩甲玉巫婆肩甲玻璃湖肩甲絲林襯肩深林肩甲狐林肩甲雷木護肩翠玉虎護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][29756] = {title = "微薄的供品", objective = "到潮霧林地採集10朵潮霧菇。", description = "我幾乎準備好進行儀式了，現在只需要另外一樣東西。供品。\n\n放輕鬆，我不是在說血腥的獻祭。只是要一些食物。\n\n西北邊的潮霧林地肯定長有一些適合當供品的香菇。請你帶一些回來。", progress = "即使是死去的人也是會飢餓的。", completion = "謝謝你，&lt;name&gt;。這些香菇看起來或許不算什麼好供品，但虔誠的情感本身就足以感召這些魂靈。\n\n而且，它們炒起來吃實在很讚。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29757] = {title = "蟾蜍醬", objective = "到最上層的純淨之池裡舀起8個咯咯蟾蜍卵。", description = "你聽說純淨之池那裡的麻煩了嗎？\n\n蟾蜍大舉遷徙進去，像發了瘋一樣地繁殖起來！這為種蓮工帶來很大的麻煩。\n\n剛好，我懂得用凝膠狀的蟾蜍卵製作一種果醬。我稱之為「蟾蜍醬」，這可是大受附近孩子們歡迎。幾乎不會有庫存。\n\n如果你打算過去水池那裡並且呃…取來一些蟾蜍的蛋，你就幫了我們所有人一個大忙。\n\n幫我把它們裝到瓶子裡。\n\n只要看準有泡泡的地方，然後一把舀到瓶子裡！", progress = nil, completion = "現在如果有小孩問我：「你有蟾蜍醬嗎？」我可以大聲說有了！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29758] = {title = "猜猜誰回來了", objective = "將克羅西的背殼帶回新席非拉給嚴。\n\n已提供物品：\n", description = "<這龍龜的巨殼跟岩石一樣堅硬，長滿銳利的脊刺。一定有個當地人能讓它派上用場。>", progress = nil, completion = "老天啊，看看這個！多麼漂亮的殼！\n\n把這帶來給我是聰明的決定，朋友。這會是很棒的餐盤。\n\n請收下這個作為報酬。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29759] = {title = "鋼釘", objective = "殺死鋼釘以取得彈尾之鑰。", description = "希望你有能力進行下一個任務，因為這攸關著我們的性命。\n\n只有一把鑰匙能解開我們的鎖鍊。不幸的是，這鑰匙掛在猴人所馴養，一隻名叫鋼釘的老虎的脖子上。\n\n他們把老虎關在北邊的深坑裡。只有殺死這頭野獸才有可能取得鑰匙。", progress = "你找到他了嗎？", completion = "很好，有了這柄鑰匙，我就能解開我們身上的枷鎖了。\n\n是你幫我們脫離了這汙穢之地。", rewards = "登陸皮甲長靴登陸鍊甲長靴登陸絲質足靴登陸緞質足靴登陸底鞋登陸脛甲登陸光潔護脛登陸戰靴登陸鎧甲長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][29760] = {title = "格鬥戰士", objective = "去和暗月馬戲團的庫爾苟‧碎顱說話。\n\n已提供物品：\n", description = "想要成為格鬥戰士的大師光是這樣肯定還不夠...\n\n可能主持死鬥場的格鬥大師庫爾苟‧碎顱會知道。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29761] = {title = "格鬥戰士大師", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n格鬥戰士大師"}
MultiLanguageQuestData['tw'][29762] = {title = "傳家寶", objective = "到月水居，從死去珠鰭村民的遺骸上取得8個珠鰭傳家寶。", description = "月水居在最近一場和猴人的激戰中淪陷了。\n\n我們盡力疏散百姓，但還是有許多人遇難。\n\n我們也沒有死者的遺物好來拜祭他們。\n\n如果有人能去從他們的遺骸上取得遺物，我們就能超渡死者安息，並繼續自己的人生。\n\n若你能這樣做，<name>，對我們將會意義深遠。", progress = "我們仍為逝去的手足感到悲傷。", completion = "謝謝你，&lt;name&gt;。你不知道這對逝者的家庭來說意義有多大。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29763] = {title = "擒王計畫", objective = "防衛者摩丹要你提著『盜掠者』因格瓦的頭來見他。", description = "那些維酷人在戰鬥中毫不畏懼。他們甚至渴望能犧牲戰死。他們的數量龐大並且行為兇殘，我們死定了 - 無庸置疑。\n\n不過他們有一個景仰的人，那個人叫因格瓦。扳倒他肯定會對他們的士氣造成嚴重的打擊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "劊子手指環劇毀戒指迅捷審判徽記您會收到：\n\n"}
MultiLanguageQuestData['tw'][29764] = {title = "撤除武裝", objective = "防衛者摩丹要你偷回5把維酷武器。", description = "拿去吧，<小夥子/小女孩>，這些維酷武器真是厲害!出乎意料地順手好用、也極為鋒利，絕對的殺人武器。\n\n在被用來對付我們之前，我需要你先去弄點些他們的武器回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "寧靜心靈護符鋒刃墜飾聖光殘片項鍊織紋鋼鍊您會收到：\n\n"}
MultiLanguageQuestData['tw'][29765] = {title = "眼睛都哭出來", objective = "從猴人捶地者身上收集金浚的東西。\n\n如果你找不到金浚，到旋風坡去找他。", description = "我應該可以把他們宰光的，老兄。\n\n把他們一個接一個地射爆，然後在他們靠近的時候裝死。這招對他們每次都靈驗。好吧，幾乎是每次…\n\n其中一個終於變聰明了。發現我在裝死。我還沒能反應過來，他們就已經在拿我的眼睛當彈珠玩了。\n\n那些野蠻的傢伙，他們搶了我的東西，把我留在這裡等死…\n\n幫助我，老兄。讓我帶著完整的尊嚴死去。", progress = "你拿到我的東西了嗎，老兄？", completion = "&lt;金浚啜泣著…至少你這樣覺得。&gt;\n\n他們殺了鼻煙…\n\n老鼻煙能對他們做什麼？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29768] = {title = "失蹤的鑼槌", objective = "從祁漢酒坊取得戴洛休息木槌。", description = "<name>，我想到了！其實很簡單。我們來製造一個讓祂完全無法繼續睡下去的騷動。\n\n你看嘛，這麼剛好就有個鑼擺在那裡！所以我想這或許就是過去的人喚醒祂的方法。我們只需要找到匹配的鑼槌，然後想辦法讓它響得越大聲越好。\n\n村長告訴我鑼槌在這裡西南邊河上的那間祁漢酒坊裡。遠倒不遠。願意去幫我拿來嗎？我會負責警告村子裡的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "絲質輕鞋夏日輕鞋舞動長靴響鈴長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][29769] = {title = "無賴", objective = "殺死10隻兔妖。", description = "我會繼續尋找讓這個小頑固起床的辦法，但是這座島上似乎到處都是麻煩。我們的作物飽受兔妖所害，那是一種長得像兔子的小賊、強盜。\n\n簡直就是無賴！！\n\n牠們繁衍的速度比我們殺的還快！對於這種狀況我有個絕妙良方—再殺更快一點！既然有你在這兒，<name>，想必這不會是什麼問題。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29770] = {title = "還是不錯！", objective = "取回3個連根拔起的菜頭、3個遭竊的胡蘿蔔、3個失竊的南瓜。", description = "南邊那些兔妖帶著我們的作物屁滾尿流地跑了，但牠們帶走的量超乎牠們能吃的份。牠們肯定是把作物囤積在什麼地方－反正一定是囤積牠們喜歡吃的。\n\n你能去找回這些被偷走的作物嗎？整座島上老百姓的肚子都等著我去填飽，就算多找回一根蔬菜都很有幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "手織護腿柔軟的馬褲舒適護脛墊甲護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][29771] = {title = "比木頭更強", objective = "收集12塊被丟棄的木板。", description = "替我從祁漢酒坊附近的建築收集些木板。\n\n你還不知道我的力量，我會展示給你看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29772] = {title = "噪聲大作", objective = "敲響鑼。", description = "你準備好了嗎，<name>？我在想我們或許該先找點東西塞住耳朵，但現在已經來不及了。你只要記好接下來幾個小時在你耳中迴盪的回音是我們勝利的讚聲！\n\n這光榮的任務交給你了，<name>。準備好時就敲響鑼！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29774] = {title = "別打臉！", objective = "向舒請求協助來喚醒大地之靈‧烏果。", description = "好吧，<name>，我思考過如果這敲鑼的辦法沒效的話，接著該怎麼辦。然後我就這麼靈光一閃！臉上潑水對我來說一直很有用。對一個又乾又土的傢伙來說肯定雙倍有效！\n\n介意去找水之靈‧舒，看看祂是否願意幫助我們嗎？祂應該在那棵樹另一端的瀑布旁的水池玩耍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29775] = {title = "神真子的靈與體", objective = "將水之靈‧舒和大地之靈‧烏果帶回五晨寺。一輛車子在路旁等著帶你過去那兒。", description = "好吧，這件事就大功告成了，不是嗎<name>?我們喚醒了兩個元素之靈，而且祂們都對你很有好感，現在我們只需要護送祂們回五晨寺就好。\n\n你先去吧，我要先跟這裡的人告別，然後我很快就會追上你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "水靈長袍大地之靈束腕大地與水之護手大地之靈護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][29776] = {title = "晨風村", objective = "到晨風村找紀‧火爪。", description = "第四，也是最後一位元素之靈是風之靈‧大風。當不在天上時，祂會出現在西邊的笑風嶺。我將艾莎和紀都派過去，協助你找尋祂。\n\n當你準備好時，我會召喚強風將你送到寺廟的頂端。你可以從那裡跨過西邊的橋，到晨風村和紀會面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29777] = {title = "敵人的工具", objective = "取回8柄浸泡油漆的刷子。", description = "猴人偷走了我們的刷子，在我們的智慧卷軸上塗抹牠們的智慧，假設那些能稱作智慧的話。若你是來幫忙的，阻止牠們，並在傷害擴大前將我們的刷子帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29778] = {title = "重寫智慧", objective = "燒毀5份損毀的智慧卷軸。", description = "<name>，我們得幫幫長者蕭湃。比他更值得幫忙的人可說不多了。\n\n在前往這裡的路上，你想必已經注意到懸掛在南邊岩洞的智慧卷軸。猴人已經褻瀆不少卷軸，而令人難過的是，這些傷害無法修復。我們只能直接處理問題－燒掉被褻瀆的卷軸，徹底清除猴人的塗鴉。\n\n別替長者蕭湃擔心。大家會一起協助他及時地將智慧重新寫下來。我會確保這件事完成。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "智慧手套真理手套樸實護臂真理纏手您會收到：\n\n"}
MultiLanguageQuestData['tw'][29779] = {title = "直接解決", objective = "在非凡村殺死20隻猴人。", description = "好吧<name>，這是我們第二次必須處理這些破壞狂猴人。我想也是時候用火金的方式來處理這個問題了。不需要耐心也不需要冥想。我們直切問題的根源。\n\n我們要進入北邊的猴人村莊，把這些臭味四溢的麻煩製造者徹底清除掉。我早就期待有機會再次和你並肩作戰了，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29780] = {title = "勿入邪道", objective = "殺死非凡酋長魯克‧魯克。", description = "<name>，我需要你理解，火金之道並非暴力的道理。當需要戰鬥的時刻來臨，我們不會遲疑，但當不需要戰鬥時，我們也不挑起。然而，俗話說得好，打蛇打七寸，擒賊先擒王。\n\n有個首腦在背後教唆猴人們發動攻擊。若能除掉魯克‧魯克，我們就不用解決所有的猴人來阻止這場攻擊。\n\n我知道你不是火金的一員，但你願意跟我一起完成這件該做的事嗎，<name>？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "猴人之劍猴人之匕猴人之杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][29781] = {title = "預防猴患成災", objective = "取回8份遭竊的煙火卷。", description = "這些猴子攻擊村莊並偷走裡面的東西。少了其中一些食物庫存，我們應該還撐得過去，但想到猴子們手上拿著煙火…我就有點擔心。更別說，誰知道那些煙火哪時候派得上用場？\n\n幫我從牠們的村莊取回失竊的煙火好嗎，<name>？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29782] = {title = "比骨頭更強", objective = "將翠玉虎之柱帶去晨風村給喬喬‧鐵頭。\n\n已提供物品：\n", description = "這個巨大的翠玉虎之柱似乎和其他猴人建築不太搭。\n\n不過它看起來的確很硬。非常結實。\n\n你知道該把這個帶給誰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "翠玉盾翠玉弩玉柄劍玉柄匕首粗糙的鬥棍您會收到：\n\n"}
MultiLanguageQuestData['tw'][29783] = {title = "比石頭更強", objective = "收集12塊棄置的石塊堆。", description = "幫我從南邊的笑風嶺那裡收集一些石塊來。\n\n你曾兩次見證我的力量，但我在你眼中看見懷疑。你的懷疑就快要消失了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29784] = {title = "平衡的觀點", objective = "跨越繩索並到晨風湖上找艾莎‧雲詠。", description = "從我們來到湖邊後開始，艾莎就一直在冥想，她所有心神都集中在大風身上。我不知道她打算發現什麼，但她不是傻子，尚羲大師也信任她，將這項任務交付給她。\n\n你得跨越從碼頭盡頭延伸出來的繩索到她身邊。這考驗著你的平衡感，但我想對你來說不是難事，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29785] = {title = "風之靈‧大風", objective = "到輕語廳找風之靈‧大風。", description = "如果你聆聽得夠久，風會將答案帶到你耳邊。\n\n風之靈大風因為害怕瑪瑙蛟兆仁而離開了天空。祂躲在高地南邊的輕語廳裡。\n\n過去找祂，我和紀會與你在該處碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29786] = {title = "空戰", objective = "利用紀的煙火來擊敗瑪瑙蛟‧兆仁。", description = "風之靈‧大風受了瑪瑙蛟‧兆仁的驚嚇。我們得幫助祂面對這項恐懼，或由我們親自代替祂面對。\n\n當我將瑪瑙蛟的事告訴紀，他說有了個主意，他會在大廳外面進行準備。儘管他有著急躁的天性，但我必須承認，我羨慕他的熱情和信念。\n\n讓我們到外面去面對瑪瑙蛟吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "熾炎晴空披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][29787] = {title = "通行的資格", objective = "擊敗長者守護者。", description = "四位元素之靈會協助你與這塊土地交談，了解它的苦痛。但首先，我還有一項小任務要交付給你。\n\n跟我來，我的弟子。陪我這個老熊貓人一起到西邊的小樹林去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29788] = {title = "不受歡迎的本性", objective = "殺死8隻刺枝惡棍。", description = "你曾在晨曦谷遇過森林妖精，但這片林地裡的森林妖精屬於不同的族群。更殘酷，也更危險。\n\n如果你把這些妖精除掉一些，魂靈們會感謝你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29789] = {title = "小而美", objective = "取得8份昆派儀式符咒。", description = "我很累了，<name>。我需要休息。\n\n我們要進行一項儀式，但我們需要這樹林裡的一些符咒。若你漫步林中，你應該能看到它們到處懸掛在樹上。\n\n如果你這位年輕人不介意，你願意讓我坐在這裡回復力氣，由你去收集這些符咒嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29790] = {title = "消逝的智慧", objective = "聆聽尚羲大師的教導。", description = "很快我就不能陪伴你繼續這屬於你的旅程了。請稍停片刻來聽我這老人的一席話。讓我的知識成為你的基石，使你能夠青出於藍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "悲悼之索悲悼腰帶悲悼繫腰悲悼鎖鏈您會收到：\n\n"}
MultiLanguageQuestData['tw'][29791] = {title = "神真子的苦痛", objective = "登上熱氣球並和神真子交談。", description = "現在不是哀傷的時候。氣球已準備好，神真子正等待著。\n\n我們將是數百年來第一個和神真子談話的熊貓人。這是莫大的榮譽。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29792] = {title = "天降大任", objective = "打開通往培武林的門。", description = "拔除神真子背上刺的工作就交給你們了。別讓你們之間的差異妨害你們。要相信彼此。\n\n在培武林內住著一名獨居隱士。前往他的小屋。他非常清楚是什麼樣的黑暗事物潛伏在我們的林間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29793] = {title = "來自海上的邪惡", objective = "殺死8隻黑暗恐懼獸或黑暗驚駭獸。", description = "我不知道殘害這片森林的邪惡是什麼，<class>，但我知道該怎麼料理它。我想你應該也知道。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "保衛者長袍勇氣長靴勇者腿甲勇氣長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][29794] = {title = "不放棄任何人", objective = "拯救3名受傷的水手。", description = "你的朋友盡了一切努力來解救我的船員。我深深感激。\n\n但我們還是面對著無法解決的難題：撲滅失事現場的火焰，救出我的人，擊退這些邪惡的海上生物，試著防止囚犯們逃走。我們忙得一個頭兩個大。\n\n我還有船員留在船骸裡，我們得在船骸崩解之前疏散他們。我知道這樣要求是太多了，但你能幫忙嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "倖存者護腿憐憫外衣憐憫護手同理鎖甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][29795] = {title = "囤積竹枝", objective = "收集10根斷裂的竹枝。", description = "我的人營養不良、負傷、疲憊不堪，但他們是部落的一員。每個人都會作戰到最後一口氣。作為我們的新盟友，我們會在時刻到來時與你們並肩，但我們需要擁有更多武器。\n\n我的人在外面收集竹枝，好將它們製作成竹矛。如果你願意幫忙，我們用得上你的一份人力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29796] = {title = "緊要消息", objective = "到尋天號的殘骸找戴羅拉‧獅心。", description = "我肯定艾莎不會喜歡這個計畫，但這是我們唯一的計畫。你願意幫我傳達這個壞消息嗎，<name>？她得知道我們在做什麼，才能將所有人帶到安全的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29797] = {title = "醫療補給", objective = "取得8個醫療補給箱。", description = "我們需要補給品來照料傷患，但裝載補給的貨箱在船難中散失了。如果你能帶回你所找到的任何貨箱，我都會非常感激。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29798] = {title = "古老的邪惡", objective = "擊敗『深海夢魘』佛煞佧。", description = "<name>我正好在找你！\n\n一名逃脫的水手看到艾莎在船骸間面對某種巨大的野獸。她或許需要你的援助。你要快點過去找她！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29799] = {title = "治療神真子", objective = "援救並保衛治療師們，直到神真子的傷口痊癒。", description = "這遠比我所能想像的更加恐怖，但我們能處理好的。我們得號召治療師們集合起來治療這道傷口。我們得拯救神真子。\n\n把你所能找到的治療師全都帶來！解救他們，用一切必要方法把他們弄來這裡治療傷口。\n\n然後不惜代價保護治療師的安全！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "醫者裹腕典禮護腿儀式胸甲效忠護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][29800] = {title = "新盟友", objective = "返回五晨寺。一輛車子在尋天號的殘骸附近等著將你接去那裡。", description = "<name>，我做了我該做的事。計畫生效了。如果我們沒採取行動，事情可能會變得更糟。我只希望她能理解。\n\n我們會有很多時間去反省的，但眼前，我們得返回五晨寺。我們得讓他們知道神真子得救了，同時也得釐清這些新盟友們的命運為何。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29801] = {title = "證明你的實力", objective = "在巨龍之魂團隊副本的永恆之眼，從『暴風守縛者』哈甲拉身上偷取密譯師的解碼戒指。", description = "哈囉，<name>!你的...呃...就直說吧，你的「巧手」在巨龍軍團當中頗負盛名。\n\n我們需要像你這樣的人來幫忙辦點事情，這需要相當微妙的手法才能完成。在我透漏更多之前，我們得先知道你這個<人/人>到底是不是適當人選。\n\n戰鬥過程中你會經過永恆之眼，我要你從『暴風守縛者』哈甲拉那邊把密譯師的解碼戒指給偷過來。你辦得到嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29802] = {title = "加密訊息", objective = "為密譯師的解碼戒指補充能量，然後用戒指來解譯寇菈史卓莎手中的燒焦密文。", description = "寇菈史卓莎目前駐守在暮光高地的朱紅壁壘，她攔截到一組加密資訊，內容事關重大。之後會讓她來解釋整個狀況，不過首先需要你來幫忙破譯這些密文!\n\n帶著這個解碼戒指，回到主城尋找以太奇術師，對方應該知道如何為裝置補充能量。然後找寇菈史卓莎取得密文，為她破解開來。快點!時間緊迫...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29803] = {title = "巫妖王的耳目", objective = "俄特加德要塞內的防衛者摩丹要你殺死凱雷希斯親王。", description = "凱雷希斯親王就如同阿薩斯在峽灣的耳目。\n\n我一點都不喜歡這種情況!\n\n去讓他嚐點苦頭。你只不過順便幫全世界一個小忙而已。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "煞婪裹帶仇殺束腕符文使護腕報復使者護臂您會收到：\n\n"}
MultiLanguageQuestData['tw'][29804] = {title = "怒紅了眼", objective = "殺死剛克。", description = "我本來都準備好蜷起身子去死了，老兄。\n\n現在又發生了這個！\n\n鼻煙和我的感情很深厚。喔，那麼多的回憶…\n\n老兄，沒能幫老鼻煙報仇，我下地獄也沒臉見他！\n\n這些流氓都受到一個叫剛克的傢伙領導。我們得把他打得一個鼻孔噴煙、一個鼻孔進不了煙。為了鼻煙！", progress = nil, completion = "金浚死了？\n\n這真是艱難的時刻，弟兄。這些害蟲會付出代價的！", rewards = "支配權皮甲外套支配權鍊甲護甲支配權絲質長袍支配權緞質長袍支配權皮外套支配權環甲護甲支配權光潔護胸支配權裝甲護軀支配權重型護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][29805] = {title = "追踪事件：在飞机上寻找米希卡", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29806] = {title = "游荡者", objective = "在战斗中打败云游的斗士。[ph]找到云游的斗士并发出挑战。", description = "[ph]找到云游的斗士并发出挑战。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][29807] = {title = "狙殺逆王", objective = "阿茲歐-奈幽的回收者阿札克給你打敗阿努巴拉克的任務。帶阿努巴拉克的裂殼回去找阿札克。", description = "逆王阿努巴拉克，以阿茲歐-奈幽，這個一度光榮輝煌的地底王國作為根據地。\n\n自他叛變以來，他已使我們的家鄉墮落成卑鄙污穢之地。他統率著一支不死奈幽蟲族的軍隊，如同其領導者，也都出賣了靈魂來服侍巫妖王。\n\n為逆王的統治畫下一個句點吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "齊力克斯的絲質軟靴索托大爺的長靴碎殼脛甲叛徒護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][29808] = {title = "別忘了那些蛋!", objective = "阿茲歐-奈幽的回收者阿札克要你摧毀6顆奈幽天譴蛋。", description = "天譴奈幽蟲族在阿茲歐-奈幽各地小心翼翼地孵育即將孵化的蛋，以提供它們年幼的奈幽蟲族來宰殺然後復生為不死族。\n\n那些蛋都染上了邪惡的魔法。我們唯一的辦法就是毀了那些蛋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "除名護手淨化手甲災禍鎮壓裹帶懲罰驅逐手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][29810] = {title = "无面者", objective = "纳尔苏深渊的拆解者基里克斯要你去杀死传令官沃拉兹和他身边的3个被遗忘的无面者。", description = "我的同胞们在对抗亡灵天灾的战斗中，一旦遭到失败，就会采取往深处挖洞的办法躲避敌人。可在绝望的驱使下，他们挖得太深了。\n\n我们不小心放出了一群古神的爪牙，一种名为无面者的生物。\n\n最终，我们无法面对两个如此强大的敌人。这场灾难导致我们输掉了对亡灵的战争，并最终失去了我们的家园。\n\n进入安卡赫特吧，<class>，把这些无面者暴徒清除出我们的故园。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "邪惡阻撓披肩嫌惡肩墊廢止重肩甲無面者肩冑您會收到：\n\n"}
MultiLanguageQuestData['tw'][29811] = {title = "守門者咒符", objective = "阿茲歐-奈幽的回收者阿札克要你從『守門者』齊力克西爾那裡取得守門者咒符。", description = "阿茲歐-奈幽的『守門者』齊力克西爾並不是個叛徒。\n\n他在蜘蛛之戰時，奮力守護我們的家園免受天譴軍的侵略。\n\n他也負責保管通往隱藏的阿茲歐-奈幽帝國的鑰匙。我希望你能替我的子民找回這把鑰匙。", progress = "齊力克西爾的靈魂是否已從亡靈的詛咒中解放出來?取回咒符了嗎?", completion = "正如我所料。\n\n自從齊力克西爾的最後之役後，帝國的大部分區域就被封閉了。說不定我的子民早已淨空深淵並且等待著解放之日?抑或無面者已經腐化了它們?\n\n只有時間能夠解答這一切謎底。必須得先淨化被阿薩斯腐化的未被封閉的阿茲歐-奈幽上層區域。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29812] = {title = "救救那些小可爱", objective = "套住5只狐狸森林里喝醉的红色熊猫，然后把他们带到徒弟季·酒怒身边。", description = "狐狸森林已经成为了本地红色熊猫的危险之地。\n\n都怪我帮了那个疯狂的酒仙影斟，森林里的狐狸才学会了酩酊之咬。于是这些年幼的红色熊猫一直处于酒醉的状态，毫无反击之力。\n\n请帮帮我！你能帮帮我吗？\n\n如果你能把他们中的一些聚拢过来，我就可以用这堆火的芳香让他们清醒过来。这样应该可以暂时保证他们的安全。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29813] = {title = "致命的宿醉", objective = "杀死狐狸森林里8只醉酒狂暴的狐狸。", description = "我劝过他别这样做！但是他却说“没人能阻止酒仙影斟”。\n\n我师父污染了本地水源，居然是为了往水里“添加酒香”。酒毒从这里流进了狐狸森林，对那里的狐狸产生了难以逆转的影响。\n\n酒毒扭曲了它们的思想，并让他们变得狂暴。现在，它们威胁到了旅行者和本地的野生生物。\n\n你能帮我削减它们的数量吗？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29815] = {title = "鑑識科學", objective = "採集8份黏性葉綠素。", description = "這些生物到處都是，而且充滿敵意！我們得在更多聯盟出現之前解決掉他們。這傢伙被打得很慘，但我還是設法研究出關於他身體結構的一些絕妙資訊。\n\n只要能正確地組合原料，我肯定能研製出一種專門對付這個種族的特效藥。實際上，我只需要對我身邊的一些藥劑稍作調整就可以。\n\n看看你是否能在水邊採集到一些黏性葉綠素。隨便一種稍具靈智的植物應該都能滿足我的需求。", progress = "希望你成功。我們能否活下來都靠這個了。", completion = "喔太好了，&lt;name&gt;。這會很合用的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29820] = {title = "前往魔枢", objective = "大法师伯林纳德希望你能与魔枢内的战斗法师凯特琳交谈。我派了战斗法师凯特琳前往魔枢调查玛里苟斯领地里的骚乱事件，可好几天过去了，她仍然音讯全无。\n\n你是否愿意去那里助她一臂之力？如果她还没有被龙吃掉的话，你应该能帮上她的忙。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "我派了战斗法师凯特琳前往魔枢调查玛里苟斯领地里的骚乱事件，可好几天过去了，她仍然音讯全无。\n\n你是否愿意去那里助她一臂之力？如果她还没有被龙吃掉的话，你应该能帮上她的忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29821] = {title = "還差得…遠咧！", objective = "在寂靜瀑布找到遺失的補給。\n\n已提供物品：\n", description = "聽著，<老兄/小妞>。\n我從砲艇上派了幾架補給無人機，但它們全部都失蹤或墜毀了。應該說，幾乎是全部。\n\n其中一架飛過這裡的營地，然後墜毀在那些瀑布旁。\n\n你何不過去一趟，看看能不能把木箱裡的內容物帶回來這裡，嗯？\n\n我們已經沒有無人機了，但我的火箭靴或許能助你一臂之力…但在這情況下，應該說一足之力。\n\n哈！我真是幽默…", progress = nil, completion = "這貨箱應該要裝滿補給品才對…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29822] = {title = "情勢", objective = "拜訪太陽神殿、月亮神殿並殺死大廢渣烏坎。", description = "這些該死的毛毛蟲！殺死一個，就又有兩個跑出來…\n\n但這不影響，<name>。命令就是命令，不管我們數量有多少，機率又多渺茫。\n\n我得制定計畫，解決這些問題。\n\n到外面去調查這地區的形勢。找到有用的情報再回來見我。\n\n在外面時順便把那隻吱吱叫的傻瓜解決掉！\n\n解散！", progress = nil, completion = "歡迎，旅人。\n\n請隨意。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29823] = {title = "偵察報告：敵人的朋友", objective = "聽取瑞可的報告。", description = "你知道，我們在找的不只是聯盟。我們也在找那些軟趴趴、活跳跳的錦魚人！\n\n好吧，我們找是找到了…", progress = nil, completion = "對啦，我翹頭了。那又怎樣？如果不是我，卡玲恐怕已經死了。喔等等…她已經死了…已經…\n\n走開！瑞可的頭很痛。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29824] = {title = "偵察報告：有如桶中錦魚人", objective = "聽取修基雅的報告。", description = "我們的領導者被玉化、猴人嚮導不見蹤影，手上還押著戰俘，卡玲和我能做的事只剩下一件：\n\n衝進敵人的領地向他們討回公道。\n\n想知道結果如何嗎？", progress = nil, completion = "我們所得到最重要的資訊是…聯盟不只和錦魚人成了朋友，還提供他們武器，教導他們用法。\n\n如今聯盟部隊的數量是我們的三十倍。而我們部落在這邊和猴子當朋友。", rewards = "月水戒指龍脊指環伏虎指環恢復戒指花綻戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][29825] = {title = "叛出師門", objective = "安卡罕特的先知伊須特給你暗殺先知那杜斯的任務。", description = "先知那杜斯曾經是我的啟蒙導師。\n\n但自從我親眼目睹他變成天譴軍的爪牙，無情地屠殺我的親人與朋友的那一刻起，我就跟他恩斷義絕了。\n\n<race>，到深淵中找出那杜斯，然後讓為他自己所犯下的罪行付出代價。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29826] = {title = "收回安卡罕特", objective = "先知伊須特要你殺死3個泰爾達朗之眼、1個磨骨者和泰爾達朗親王。", description = "泰爾達朗親王與他的天譴軍團所用的結界，和我們帝國當初為了避免受到冰冷深淵原居生物侵擾所設下的防護結界是相同的。\n\n關閉結界然後殺死那些守護結界的天譴軍。我的軍隊將會協助那些原居生物殺死剩下的天譴軍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29827] = {title = "酸雨", objective = "使用尋回的旋翼機殺死25隻猴人撕腸者和25隻猴人利刃暗殺者。", description = "自從你離開之後，有越來越多的這種生物逼近我們的營地。他們似乎想集結起來發動一場大型襲擊！\n\n如果不採取激烈手段，我們有可能全都見不到明天的太陽了。\n\n來，把我浸過毒的星形飛鏢拿去，設法削減他們的數量。", progress = nil, completion = "太好了！真是有創意的解決方法！\n\n那應該能阻止他們一陣子。", rewards = "榮譽戰鬥工程師皮甲長褲榮譽戰鬥工程師鍊甲護腿榮譽戰鬥工程師絲質長褲榮譽戰鬥工程師緞質護腿榮譽戰鬥工程師皮護腿榮譽戰鬥工程師環甲護腿榮譽戰鬥工程師光潔腿鎧榮譽戰鬥工程師腿甲榮譽戰鬥工程師重型腿鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][29828] = {title = "天譴軍剋星", objective = "德拉克薩隆要塞的庫賽爾要你去殺死崔德王並帶回牠的牙齒。", description = "有個逃走的德拉克瑞食人妖跟我說，有一隻名叫崔德的迅猛龍之王竟然對瘟疫免疫\n\n找到崔德王，並帶回牠的牙齒，我也許可以用來鑄成一把武器。", progress = "那頭巨獸還活著嗎?", completion = "&lt;庫賽爾的眼睛睜大。&gt;\n\n哇噢!真是顆巨齒!", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29829] = {title = "謹慎才是關鍵", objective = "羅甯要你前往達拉然的紫羅蘭堡，並與辛克拉麗中尉交談。", description = "聽我說，<race>。\n\n不久前，紫羅蘭堡的一件意外引起了我的注意。看來藍龍即將對達拉然發動全面的入侵!\n\n我要你馬上前往監獄，並與辛克拉麗中尉交談。她會告訴你詳情。\n\n不只這樣，我需要做到滴水不漏的地步。若是可以避免這場災難的話，那我們應該儘可能不要驚動達拉然市民。我的指示夠清楚嗎?\n\n很好，現在去吧!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29830] = {title = "牽制", objective = "紫羅蘭堡的辛克拉麗中尉想要你結束藍龍的大軍進攻。殺死霞妮苟莎之後再去找她說話。", description = "我方已潰不成軍，瑪里苟斯的襲擊者又如潮水般湧進。\n\n我擔心最壞的情況還沒開始。\n\n你得要全力對付他們，直到他們的領袖霞妮苟莎出現。只有殺死她才能拯救達拉然，阻止這場侵襲。\n\n準備好了以後再來跟我說。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "刺青鹿皮護腿協商窄褲錯綜迷宮腿甲達拉然守望者腿鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][29831] = {title = "废弃：公海惊魂", objective = "去暴风要塞的王座大厅和杰塔瑞斯将军谈一谈。暴风城近日收到消息，称运送联盟平民的船只在公海上遭遇了骇人听闻的恐怖袭击。部落被指控劫持联盟船只、强行登船、虐待乘客，以及盗抢财物。\n\n联盟的英雄们，联盟需要你的帮助来调查事件真相！如果你愿意响应征召，就去暴风要塞找到杰塔瑞斯将军吧。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "暴风城近日收到消息，称运送联盟平民的船只在公海上遭遇了骇人听闻的恐怖袭击。部落被指控劫持联盟船只、强行登船、虐待乘客，以及盗抢财物。\n\n联盟的英雄们，联盟需要你的帮助来调查事件真相！如果你愿意响应征召，就去暴风要塞找到杰塔瑞斯将军吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29832] = {title = "废弃：收集证据", objective = "走访暴风城港口，和哨兵伊罗莉亚、鲁米安·星语、纳耶斯·霜月和菲拉尔·迷雾行者谈一谈。", description = "有一艘名为“勇者号”的船只会定期从暴风城港口将乘客和货物运送到达纳苏斯城外的鲁瑟兰村。\n\n不过，船只上刚刚传回来不幸的消息。乘客和船员都说，部落的舰队在泰达希尔附近的海域劫下了他们并且强行登船，对船上的人员实施了虐待，盗抢了一些货物，最后还逼使船只调头行驶。\n\n我们必须了解发生了什么事情，<name>。你愿意前往暴风城港口，去听听乘客们的叙述吗？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29833] = {title = "未完成的任務", objective = "哈寇亞要你與剛德拉克的托爾瑪交談。", description = "雖然阿卡利的預言者再也不會侵擾這個世界了，但是我們還有事情得做。\n\n大部分的阿卡利之血都被另外一個傢伙吸收強化了，他才是真正的危險人物。\n\n快，<name>，前往剛德拉克，去找托爾瑪談談。他會提供你更進一步的資訊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29834] = {title = "蓋爾達拉必須付出代價", objective = "托爾瑪要你到剛德拉克殺死史拉德銳、慕拉比、以及蓋爾達拉。", description = "那一定是我一生中看過最糟糕的事情了。偉大的阿卡利，竟然在我眼前被殺害。太可怕了...\n\n我的工作只是觀察而已。但是這實在讓人忍無可忍!蓋爾達拉和他的人一定要為此付出代價!\n\n替阿卡利復仇，老兄，這是你該做的事。", progress = nil, completion = "你成功了?!全死透了?\n\n拿去吧，老兄。把這個當作你為這片冰凍荒原制裁廢物的獎賞。", rewards = "詭詐魔精束帶奇怪巫毒腰帶殞落帝國遊俠腰帶逝亡半神扣環您會收到：\n\n"}
MultiLanguageQuestData['tw'][29835] = {title = "蓋爾達拉必須付出代價", objective = "撰史者巴琪妮要你到剛德拉克殺死史拉德銳、慕拉比、以及蓋爾達拉。", description = "偉大的阿卡利被殺害了，<race>。\n\n我這一生該做的是記錄，不是打鬥。但是這實在讓人忍無可忍!蓋爾達拉和他的人一定要為此付出代價!\n\n替阿卡利復仇，老兄，這是你該做的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "詭詐魔精束帶奇怪巫毒腰帶殞落帝國遊俠腰帶逝亡半神扣環您會收到：\n\n"}
MultiLanguageQuestData['tw'][29836] = {title = "探班", objective = "托基尼要你與剛德拉克的撰史者巴琪妮談談。", description = "有些可怕的聲音從剛德拉克裡頭傳出來，老兄。而且還越來越大聲，越來越頻繁。\n\n我的老學生待在剛德拉克記錄事情。也許你能夠幫我去探個班?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29838] = {title = "獨一無二", objective = "撰史者巴琪妮要你進入剛德拉克取得一塊德拉克瑞巨像碎片。", description = "就第一眼而言，這看來不過就是另一個古老的故事:食人妖藉由毀滅他們原應敬仰的神靈，獲得了禁忌的力量。\n\n如果我聽說的傳說是真的，剛德拉克內應該有尊特別的魔像:一尊獨一無二的魔像!\n\n幫我從剛德拉克帶回那魔像的一部分，好讓我研究研究。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "毛皮內襯底鞋犀牛獸皮及膝靴殞落希望綴鱗長靴食人妖之蹬靴多啾魔精鎧靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][29839] = {title = "獨一無二", objective = "托爾瑪要你進入剛德拉克取得一塊德拉克瑞巨像碎片。", description = "如果當初德拉克瑞並非試圖毀掉神靈，而是去景仰膜拜祂們，現在眼前不會是滿地瘡痍的景象。\n\n據說，德拉克瑞人手中有具特殊的魔像，這具魔像身上灌注了禁忌的力量。\n\n從那具魔像弄塊碎片給我，這樣我們就能從同胞身上學點東西。", progress = "找到沒?我確定魔像一定就在那裡面。", completion = "太驚人了!我從沒看過這樣的東西。\n\n做得好，老兄。", rewards = "毛皮內襯底鞋犀牛獸皮及膝靴殞落希望綴鱗長靴食人妖之蹬靴多啾魔精鎧靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][29840] = {title = "為了後代子孫", objective = "剛德拉克的撰史者巴琪妮要你收集6個德拉克瑞歷史石板。", description = "你知道的，放眼望去在剛德拉克滿是瘡痍。\n\n如果你夠勇敢，去找找歷史石板，看看有什麼線索可以告訴我們，德拉克瑞帝國怎麼會走到今天這一步。\n\n說不定有一天我們能重拾往日的榮耀。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "巫毒徽記腐惡魔精之戒堅固白金指環獅首戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][29844] = {title = "為了後代子孫", objective = "剛德拉克的托爾瑪要你進入剛德拉克收集6個德拉克瑞歷史石板。", description = "寒冰食人妖的這片土地是昔日輝煌餘下的陰影。\n\n如果你夠勇敢，去找找歷史石板，看看有什麼線索可以告訴我們，德拉克瑞帝國怎麼會走到今天這一步。\n\n說不定某天我們會把這片土地交還到新一代的寒冰食人妖手上。", progress = "你找到德拉克瑞歷史石板了嗎，老兄?", completion = "我們食人妖帝國分裂的時候，某些種族根本就還沒出現呢。\n\n我們要從這些斷垣殘壁之中重新站起來。", rewards = "巫毒徽記腐惡魔精之戒堅固白金指環獅首戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][29847] = {title = "抓小偷", objective = "潛入拉文霍德莊園並找出那顆遺失的黑龍蛋。", description = "過了這個洞穴之後不遠處就是拉文霍德莊園。你必須在不被發現的情況下偷偷潛進去!\n\n<莫爾斯塔茲在你身上放了一道魔法。>\n\n好了 - 這樣一來我在你闖入營地後就依然可以關注你的狀況並跟你保持聯絡。去潛入莊園吧，找到那顆蛋，小心不要被抓到了...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29848] = {title = "淒涼的看守者", objective = "石之大廳的卡迪爾‧鐵禍要你讓悲嘆少女安息，並帶回一滴悲傷晶淚。", description = "我很願意獻出自己的生命給造物者。\n\n但是自從洛肯變節之後，好像奧杜亞所有的人都背叛了這個世界。特別是悲嘆少女，彷彿還在為了她的新指令而痛苦不已。\n\n請讓她安息並帶回一滴她的眼淚。", progress = "我衷心希望還有其他的辦法，但是看起來死亡是她唯一的救贖。", completion = "&lt;卡迪爾默默地看著晶淚。&gt;\n\n再也沒有其他人能夠像悲嘆少女體會到這麼深摯的哀傷。\n\n讓我們在對抗洛肯時，永遠記得她的精神。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29850] = {title = "墮落的石器", objective = "石之大廳的卡迪爾‧鐵禍要你殺死克利斯托魯斯和3個黑暗符文巨人。", description = "鐵矮人正在忙著雕刻一個巨型的石器物體，我擔心很快就會被拿來當做一件強大的武器。\n\n你必須打敗他們的監督者克利斯托魯斯，和已經在大廳內肆虐的黑暗符文巨人，否則一切將為時已晚!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29851] = {title = "聯賽勇士", objective = "大領主提里奧‧弗丁要求你參與勇士試煉。", description = "這場聯賽能讓我們之間的發展更加緊密，在最終決戰裡聯手對抗巫妖王。\n\n心懷勇氣與榮耀而戰吧，<name>。聚集在這的所有人都是為了同樣的目標而戰。\n\n團結起來，我們就能阻止阿薩斯!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29860] = {title = "一山不容二虎", objective = "雷光大廳的風暴信使埃利林要你擊敗渥克瀚。", description = "我該坦率地告訴你，小<race>。我的子民變了，自從跟索林姆分裂之後就不一樣了。\n\n渥克瀚和我們是勢不兩立的，不是他死，就是我亡，沒有第三種結果。我們只想要和平度日，可是看來除了開戰之外別無選擇。", progress = nil, completion = "渥克瀚再也不會如同鬼魅般，縈繞於子民的夢境之中了。\n\n繼續努力下去，小&lt;race&gt;。我的子民早晚會原諒索林姆的。", rewards = "閃電灌注披肩焦熱皮甲肩衛風鑄護肩泯仇肩鎧渥克瀚披肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][29861] = {title = "不擇手段!", objective = "雷光大廳的風暴信使埃利林要你擊敗洛肯。帶著洛肯之舌回去找風暴信使埃利林。", description = "不論怎樣，洛肯都得死。\n\n擊敗他所隨之而來的榮耀將歸於你。\n\n拔下他那說謊的舌頭帶來見我，我會感激你的。", progress = "洛肯受到正義的制裁了嗎?", completion = "那畜生死了?\n\n你為我的子民帶來無比恩惠，小&lt;race&gt;。\n\n請收下這份禮物，作為你忠誠友誼的回報。", rewards = "雷光長袍硬化舌頭外套雷光使者鍊衫鋸齒岩石胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][29862] = {title = "清除道路", objective = "雷光大廳的風暴信使埃利林要你除掉3名風鑄修補者、3名風鑄謀士及畢亞格林將軍。", description = "洛肯的大軍正在備戰。不過對方還沒有會被攻擊的心理準備。\n\n是時候該發動攻擊了。解決畢亞格林將軍和他的手下，以免他們對全艾澤拉斯發動攻擊!", progress = nil, completion = "雖然在外面的人大多不知道，不過你今天救了整個世界。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29863] = {title = "風暴信使埃利林", objective = "裘庫姆王要你進入雷光大廳和風暴信使埃利林交談。", description = "我派了一名信使進入雷光大廳去對付洛肯。\n\n不用說也知道，他需要援手才能對抗洛肯的手下。盡量協助他，這樣我們才能阻止那個叛徒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29864] = {title = "從源頭下手", objective = "銀白告解者帕爾璀絲要你殺掉絲瓦拉‧悲傷亡墓。", description = "我們很努力的要把天譴戰爭機器造成的損傷降到最低。\n\n然而這裡的維庫族自願加入巫妖王的行列，這讓這件任務變得更加困難。\n\n拜託你了，勇士，你一定得擊敗他們的精神領袖絲瓦拉，不然她會帶領她的子民墮入無垠深淵之中!", progress = nil, completion = "每從天譴軍團手中奪回一個士兵，所救回的可不單是一條性命。\n\n謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29865] = {title = "絲林之路", objective = "擊敗8隻絲林蜘蛛。", description = "絲林之路就在西邊。自從邪惡又貪食的蜘蛛佔據了那條道路後，它就沒落了。\n\n我是很想親自面對這些壞蛋，但總是得有人保護這間麵店免於...呃...危險之類的。\n\n去吧英雄，戰勝這些野獸!如果你成功了，或許我會讓你聽一些我的經典英勇事蹟。\n\n我也會付你錢的。", progress = nil, completion = "真是高尚的英雄。你讓我想到一個比較年輕，也比較沒那麼帥的版本的我。", rewards = "琥珀霧長袍黑木林長袍玉巫婆護甲玻璃湖護胸絲林長袍深林外套狐林護甲雷木護軀翠玉虎護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][29866] = {title = "黏黏的線", objective = "收集7份原始絲線。", description = "啊，歡迎你，旅人。我需要你的幫助!\n\n錫拉‧金流需要一些絲。其實我超討厭絲的，因為它老是卡在我的毛裡。\n\n但我真的想讓她印象深刻。\n\n如果你能到西邊的絲林去幫我弄一些絲來，我會很高興付你報酬。", progress = "你有找到絲林嗎？", completion = "喔，真是太感謝你了!這太完美了!\n\n我希望它不會也在你身上黏來黏去。\n\n我要立刻把這個送去給錫拉!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29871] = {title = "聰明的艾須歐", objective = "找到聰明的艾須歐。", description = "我不太確定聰明的艾須歐的『聰明』稱號是打哪來的。所有的錦魚人都是聰明的，我也不認為他有比其中大多數來得聰明。\n\n老實說，我認為恰好相反。\n\n至少他是個合格的戰士。他在天僧寺表現不錯，因此獲選來參與我們的訓練修行。\n\n如果你想協助他尋找隱居的宗師，只要沿著四風峽的北邊界就可以找到他。", progress = nil, completion = "我以前是不是在哪裡見過你？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29872] = {title = "林‧嫩爪", objective = "找到林‧嫩爪。", description = "林比她自己想像的還有天份。她擁有強力的拳頭，卻也有著脆弱的心靈。只要多點自信，她可以比我們任何一個人都優秀。\n\n或許她可以在她前往西方的旅途中找到她需要的自信。我們講話的當下，她或許已在前往石犁村的途中。如果你經過那附近，停下來與她談談。", progress = nil, completion = "喔，是你！\n\n不，我還沒有找到隱居的宗師。我到這來或許只是浪費時間。\n\n&lt;嘆氣…&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29873] = {title = "肯‧肯", objective = "尋找肯‧肯。", description = "嗯...肯‧肯。那個猴人。\n\n就個人而言，我很佩服他可以進行訓練到這種程度。他的腦殼裡有點大腦，和他同族的大多數人相比，算是很突出的。\n\n他說他要往東走，但由於我們已經在山谷東側，我實在無法想像他還能從這兒走多遠。沿著小徑往南走，到喀撒朗蠻荒的祝家守望站找他。去看看他找到了什麼。", progress = nil, completion = "這個地方...這裡...好悲傷!\n\n肯‧肯從沒見過這麼悲傷的地方。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29874] = {title = "康恩‧藤杖", objective = "尋找康恩‧藤杖。", description = "康恩的自信經常會變成讓他走上危險之路的自大。他現在走的路就很危險。他想深入喀撒朗蠻荒。\n\n我通常不會要求一個陌生人幫忙，但...你能不能去確認他人沒事?知道有個勇敢的<race>在找他會讓我比較安心。", progress = nil, completion = "我很確定這些移民幾星期前還不在這兒，他們是從哪兒來的?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29875] = {title = "康恩‧藤杖", objective = "尋找康恩‧藤杖。", description = "康恩的自信經常會變成讓他走上危險之路的自大。他現在走的路就很危險 - 深入喀撒朗蠻荒。\n\n我通常不會要求一個陌生人幫忙，但...你能不能去確認他人沒事?知道有個勇敢的<race>在找他會讓我比較安心。", progress = nil, completion = "我很確定這些移民幾星期前還不在這兒，他們是從哪兒來的?", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29877] = {title = "輸在起跑點", objective = "挖出7份農耕工具。", description = "兔妖不只是偷吃我們的食物而已。他們還想自己種田。問題在於…嗯，他們幾乎是一群笨蛋。\n\n你不相信牧諾？昨天晚上他們闖進工具棚…偷走了用具。我們醒來的時候，發現耙子和手推車都被種在土裡。\n\n他們還在上面澆水。他們居然想種植手推車！\n\n拜託，如果你有去到那裡，幫忙把工具挖出來吧。", progress = nil, completion = "謝謝你，朋友。這樣我這個猴人就能來幹點活兒了。", rewards = "您能選擇下列奬勵中的一個：\n\n西瓜炸彈\n\n您還會收到：\n\n西瓜炸彈恆龍寶箱"}
MultiLanguageQuestData['tw'][29879] = {title = "囫圇吞「猴」", objective = "到奇提塔塔湖，從吃撐的鱷魚中釋放5隻猴人，並取得5條斑點鱒魚。", description = "現在，回到你的困境上。\n\n我相信你可以幫助你的人民跟我們的猴人建立關係，就像我們跟猴人間的關係一樣。\n\n我身後的小路會引導你前往猴人捕魚的水域。\n\n每年的這個時候，可怖的野獸會進駐這個水域，讓飢餓的猴人傷亡慘重。\n\n如果你能救出一些受害者並取得一些魚，或許他們會對你更有善意。", progress = "怪怪人有滑魚…要給我！？", completion = "怪怪人救了猴人？而且帶了滑魚來？\n\n嗯，或許怪怪人沒那麼壞。\n\n反正兔積‧兔積從來沒喜歡過大廢渣烏坎…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29881] = {title = "完美的顏色", objective = "收集8片剛落下的花瓣。", description = "如你所見，這林地裡長滿了美麗的粉紅花朵。隨著花齡增長，花朵的色調會加深而後凋謝。\n\n如果你願意幫忙，我需要幾朵新近落下的花。只有剛落下的花瓣才具備我需要的那種顏色。\n\n我能利用它製造出一種令人屏息的墨水。你願意幫助我嗎？", progress = "花瓣落地後，只有一段很短的時間能被用來製作完美的顏色。", completion = "啊!你鑑賞顏色的眼力很好，朋友。這些能造出超棒的顏料。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29882] = {title = "蜂針毛筆", objective = "從果園蜂那裡取得6份黃蜂毒刺。", description = "你需要正確的工具來達成完美的筆觸。我自己的已經毀了，筆毛變得像猴人的毛一樣無法掌控。\n\n你看過落英園裡的果園蜂嗎？他們的蜂刺可以製造出一筆一劃都擁有正確銳利度的毛筆。\n\n能請你幫我收集一些來嗎？", progress = "你有拿到一些蜂刺嗎？我通常會請武僧幫忙，但他們似乎剛好都不在。", completion = "感謝你，旅人。這些能造出很好的毛筆。這是給你的一點謝禮。", rewards = "琥珀霧護腿黑木林腿甲玉巫婆腿甲玻璃湖腿鎧絲林長褲深林腿甲狐林腿甲雷木腿甲翠玉虎腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][29883] = {title = "珠鰭困境", objective = "到珠鰭村和長者廬山、珍珠守衛者富錦、講師銳鰭和傲天墮談話。", description = "我想了挺久。\n\n我們在這裡無依無靠，還離家千里之遠。\n\n雖然這些珠鰭錦魚人不信任我們，但是看起來也沒有敵意。\n\n如果能讓他們相信我們是朋友，兩族之間便可以締結有利的聯盟。\n\n<name>，你得去和村子裡的錦魚人談話。\n\n讓他們的領導者了解到無須懼怕我們，我們只想要和平。", progress = nil, completion = "看來你建立了良好的第一印象。\n\n做得好，&lt;name&gt;!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29884] = {title = "追踪事件：特工出发", objective = "目送斥候离开，然后与卢山大哥谈一谈。", description = "我和苏利该出发了。我们会注意寻找白卒留下的一切痕迹并尽快回报。\n\n在海军上将泰勒康复期间，我恐怕只能让你留下来主持大局了。在我们离开的期间，你要尽可能多地多了解这些锦鱼人。我希望当我们回来的时候能得到一份详细的报告。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29885] = {title = "趕路乾糧", objective = "收集6份龜腰肉。", description = "我們沒有在這裡坐等將軍恢復的時間了。\n\n我和蘇利準備去北邊搜索安杜因，但我們需要補給品來完成這趟旅程。\n\n這片湖泊裡滿滿都是野生動物，我們也取得了狩獵的許可。\n\n去那裡收集補給，我和蘇利會在這兒做最終準備。", progress = "時間短暫。我們每拖延一個小時，白棋就離我們越遠一點。\n\n我要的補給品在哪裡？", completion = "這樣應該很充裕了，&lt;name&gt;。感謝。", rewards = "您能選擇下列奬勵中的一個：\n\n海龜肉乾\n\n您還會收到：\n\n海龜肉乾"}
MultiLanguageQuestData['tw'][29887] = {title = "長者的指示", objective = "從彈尾黏爪那裡取得水語者之杖、典禮長袍、翠玉皇冠和紫檀串珠。", description = "喔，老天。喔老天…這絕不能被長者發現！\n\n我一定是在從另一個村子撤離時，把長者的祭器遺落在那了。\n\n但是…月水居現在到處都是猴人！\n\n竟然這麼粗心地把祭器丟下，我這算是什麼珍珠守護者啊！\n\n<老錦魚人把臉埋進雙手之間。>\n\n陌生人，你能發發好心幫我這個忙嗎？", progress = "長老是一名水語者。他能和水交談。", completion = "你找到它們了？喔水靈保佑！\n\n你救了我一身老鱗啊，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29888] = {title = "找尋博學行者", objective = "到翠玉林的夢旅者亭閣找博學行者阿洲。", description = "我知道你和你的人都急著要找到你們的安杜因王子。\n\n我知道有個人或許能幫助你。他是個比任何人都熟知這片土地的熊貓人博學行者。所以我無法保證你會受到怎樣的接待，但他絕對會像你對他感到好奇一樣，對你十分感興趣!\n\n那位博學行者就住在西南邊的森林裡，告訴他是珠鰭送你去的。", progress = nil, completion = "你環顧空蕩蕩的房子。\n\n你應該來到了正確的地方，卻沒看到屋子的主人。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29889] = {title = "借來的酒", objective = "嚐嚐令人垂涎的酒。", description = "撲鼻的香味從桌上的瓶子中傳來。\n\n嚐一點點應該沒有關係吧，對吧?", progress = nil, completion = "我聽說你們的人漂流到我們的海岸邊。但我沒想到會有個漂流到我的家門前!是什麼風把你吹來的，陌生人?\n\n&lt;你解釋你搜索安杜因王子的目的，並將他的外表描述給這名熊貓人聽。&gt;\n\n很有趣!所以，是珠鰭的人將你送來找我的，是嗎?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29890] = {title = "保持專注", objective = "前往翠玉林，在夢旅者亭閣的涼亭和博學行者阿洲一起冥想。", description = "夢幻之釀完成了!這一次，當你喝下夢幻之釀時，你必須全新接受你在內心專注下看見的影像。\n\n跟我一起到我的涼亭去，我會教導你如何達到我們熊貓人最重視的內心平靜。\n\n你充滿困擾的心靈會為你帶來許多干擾，但記得保持專注!", progress = nil, completion = "你怎麼找到我的?\n\n&lt;安杜因聽你描述夢幻之釀帶給你的幻象。&gt;\n\n太棒了!這正是幾天前發生的事情。我們從那時起就一直在躲藏著。", rewards = "友情之戒贊同指環友好之禮指環天資指環發現指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][29891] = {title = "勁道", objective = "殺死迷霧蠕行怪，直到迷霧恐懼怪出現，然後取得迷霧恐懼怪之心。", description = "我們需要一些原料來製造夢幻之釀。\n\n首先，為了加強它的勁道，我需要的原料來自於一種恐怖的生物，傳說中的迷霧恐懼怪。\n\n據說這種生物只出現在霧氣最濃的時候。\n\n在這裡的北方和東方，你會發現小型的迷霧蠕行怪在沼澤間漫遊。殺死這些生物，直到迷霧恐懼怪出現，然後挖出牠的心帶來給我。", progress = "迷霧彷彿擁有自己的心智一般，不是嗎？", completion = "這真是超棒的樣本!老實說，我很訝異你竟然能成功。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29892] = {title = "主體", objective = "從沼澤鱷魚身上取得5個原始的鱷魚眼。", description = "酒的本體是個重要、也經常被忽略的要素。\n\n要創造完美的順暢口感，我需要東邊那種沼澤鱷魚身上的古老之眼。\n\n小心。這種生物相當的凶惡。", progress = "在沼澤中要注意你的腳步，我的新朋友。", completion = "你來的地方有鱷魚嗎？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29893] = {title = "色澤", objective = "收集8份琥珀飛蠅的翅膀。", description = "夢幻之釀最與眾不同的特色就是它的色澤，夢幻一般的色澤。\n\n在此地的東邊，你會找到閃耀的琥珀飛蠅。我需要牠們的翅膀來為這種酒添加最後的光澤。\n\n帶上這把刀，收集8份翅膀。", progress = "你收集到所有原料了嗎？是時候製造夢幻之釀了。", completion = "美麗的顏色，稀有的透明度，光芒閃爍卻不致於太過刺眼…這會是上好的夢幻之釀。\n\n我開始看見你身上異於常人的潛力了，陌生的訪客。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29894] = {title = "水之靈", objective = "和長者廬山談話，並見證水語儀式。", description = "我們與猴人的戰爭無休無止，我族的未來也風雨飄搖。這就是水語者決定向水尋求智慧的原因。\n\n長者廬山正在等你。請將你收集到的祭器送去，好讓他們開始。", progress = nil, completion = "我看到預言的幻象了，&lt;name&gt;。你覺得那是什麼意思？\n\n我想很顯然的，你在其中佔有一席之地。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29895] = {title = "白棋的蹤跡", objective = "帶披風到翠玉林的珠鰭村找泰勒上將。\n\n已提供物品：\n", description = "儘管披風變得破破爛爛，屬於皇家徽飾的織工仍是隱藏不了的事實。\n\n你該把它送去給你的聯盟指揮官看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29898] = {title = "聖水", objective = "從悲愁洞府裡的四只神聖之碗裡取得治療之水。", description = "我很感激你大老遠跑來救我，但阿仁傷得非常嚴重。\n\n這個老熊貓人沒有任何幫助我的理由，但他依舊賭上自己的生命來拯救我這條命。\n\n在他發燒昏迷之前，他提到山丘下的洞穴裡有一種治療之水。\n\n那很危險，但我會不計一切代價去幫助我的朋友。你能幫我取回這種水嗎？", progress = nil, completion = "這種治療之水應該能讓阿仁退燒一陣子，但我恐怕這不是一勞永逸的解藥。\n\n謝謝你，&lt;class&gt;。至少我們為他爭取了一些時間。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29899] = {title = "安息", objective = "殺死8名受折磨的靈魂。", description = "那些魂靈...洞穴的居民...發出痛苦的哀號...\n\n困在...這個世界...無法前往...下一站。\n\n我...聽著...他們哭喊...快瘋了...\n\n請...幫助他們...安息。", progress = nil, completion = "謝謝你...朋友。我很...高興...知道...魂靈們...安息了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29900] = {title = "古老的傳說", objective = "到悲愁洞府取回恆春谷之歌。", description = "我父親畢生致力於研究恆春谷。\n\n這山谷是神話之地，在一萬兩千年前的熊貓人革命後便遭到封鎖。我們幾乎對它一無所知！\n\n我父親順著線索來到山丘底下的洞穴。裡面有一首名為恆春谷之歌的非常古老的詩，但他沒有能力將它取回來。\n\n如果你要過去那裡，可以把詩帶回來給他嗎？", progress = "你…找到那卷軸了嗎？", completion = "喔…是那首詩！你…念過了嗎？那山谷在哪裡？", rewards = "琥珀霧腕輪黑木林束腕玉巫婆腕甲玻璃湖護腕絲林腕輪深林裹臂狐林腕甲雷木臂鎧翠玉虎臂鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][29901] = {title = "安杜因的決定", objective = "告訴安杜因回家的時候到了。", description = "你為王子的朋友盡了一切努力。\n\n你完成你的任務，找到了白棋，也就是安杜因王子。泰勒上將和軍情七處的其他探員會期望你將王子送去接受他們保護。\n\n回家的時候到了。", progress = nil, completion = "他做了什麼？！？！？！\n\n沒被我找到算他好運，因為到時候，我搞不好會親手殺了他！\n\n不管他覺得自己在做什麼…追尋這個山谷…可不是符合王子身分的舉動！\n\n若不是眼前有更加緊急的事務得處理，我肯定把整支艦隊都派出去追他！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29902] = {title = "灭火", objective = "扑灭迷航港的6处火焰。", description = "这些猴子的智慧还不及他们野蛮的万分之一，但也足以让他们明白——火是一件威力强大的武器。\n\n不用我说你也明白，如果我们放任不管，那些火会吞噬这里的一切。\n\n我的手下都已经忙得四脚朝天了，所以必须由你来摆平这件事。带上这桶水，把那些火扑灭！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29903] = {title = "絕配", objective = "和珠鰭水解師們談話，並幫助他們穿上適當的裝備。", description = "長者廬山和我都同意，同心協力將是未來最好的道路。\n\n我們會和珠鰭分享我們具有優勢的軍事知識和武器。\n\n作為回報，如果我們再次與部落遭遇，錦魚人們將成為強大的盟友。\n\n帶上這個裝載武器和裝備的貨箱。我要你到村莊裡協助錦魚人們裝備上適合他們能力的武器。", progress = "錦魚人擅長的與我們不同。我們得負責找到他們的強處。", completion = "很好。看這些部落人渣還敢不敢露臉!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29904] = {title = "更重要的任務", objective = "在竹林原殺死24隻野生動物來訓練珠鰭受訓員。", description = "我召集了一隊聰明年輕的珠鰭受訓員去累積實戰經驗。\n\n帶領他們前往東北邊的竹林原，殺死你們遇見的各種野生動物。\n\n不到徹底熟悉戰鬥，別帶他們回來。", progress = nil, completion = "你的受訓員剛剛回來。我真不敢相信自己的眼睛!他們跟之前相比，簡直是天壤之別。\n\n做得好，&lt;class&gt;。就算是我也做不了更好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29905] = {title = "燒光他們", objective = "殺死15名葛魯援兵或彈尾新兵。", description = "先遣斥候回報，猴人有大批援軍群聚在北邊的彈尾坑。\n\n我們的部隊聚集在西北方的山脊準備作戰，現在就只差你一人。\n\n該讓猴人見識我們的真本事，將他們徹底殲滅的時候到了。", progress = nil, completion = "水之靈對你的評價沒錯，&lt;name&gt;。你的努力為這個村子帶來希望。我們不會忘記你給予我們的教導，&lt;class&gt;。", rewards = "您能選擇下列奬勵中的一個：\n\n小魚\n\n您還會收到：\n\n小魚恆龍寶箱"}
MultiLanguageQuestData['tw'][29906] = {title = "及時魚樂", objective = "殺死尬腸酋長。", description = "猴人表面上雜亂無章，其實亂中依然有章法可循。他們的領袖「尬腸酋長」是個精明的策劃者，是他組織了猴人的攻擊。\n\n他在西北邊猴人營地裡的深坑中組織行動。\n\n立刻出擊，不要手下留情，<name>，不然就換我們遭殃了。", progress = nil, completion = "猴人失去了領袖，應該會再次陷入混亂。\n\n讓我們慶祝這場勝利！&lt;name&gt;，你以陌生人的身分前來，但以朋友的身分離開。\n\n從今以後，你擁有至高無上的地位，是珠鰭部族珍貴的朋友和守護者。", rewards = "錦魚人冥想法杖錦魚人預言魔棒錦魚人鬥杖錦魚人巨劍錦魚人手斧錦魚人之弩錦魚人戰斧錦魚人儀式權杖錦魚人匕首錦魚人鬥錘您會收到：\n\n錦魚人冥想法杖錦魚人預言魔棒錦魚人鬥杖錦魚人巨劍恆龍寶箱"}
MultiLanguageQuestData['tw'][29907] = {title = "老陳與莉莉", objective = "跟著老陳‧風暴烈酒前往潘家莊。", description = "我和姪女初到潘達利亞。你好像也跟我們一樣。我們是打漂流島來到這裡的。老實說，我們根本不知道要往哪裡去。\n\n前方的農地看起來是個不錯的地方，我們可以好好休息並喝上一杯。你說呢，莉莉？\n\n<race>？你想和我們一道去嗎？", progress = nil, completion = "歡迎，歡迎，客人！你們是來品嚐我兒子種的菜頭的吧？還是想買幾頭豬？\n\n請請請，把這當自己家吧。我們的房間還很多。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29908] = {title = "看似無盡的滋擾", objective = "殺死8隻暴牙偵察兵、暴牙工具掠奪者或暴牙搗蛋鬼。然後殺死18隻暴牙工具糾纏者。", description = "很抱歉這一帶的現況不是很好。兔妖，住在山丘下的那些長得像兔子的生物，越來越猖獗地闖進我們家族的農地，我們那些特大又特美味的作物也因此不斷遭到危害。\n\n我不是個戰士…不過你可能是！你願意幫個忙，把那些兔妖趕出我的土地嗎？", progress = nil, completion = "&lt;潘環視了他的農地。&gt;\n\n嗯，他們還沒走光，但也少了許多。而且他們不再把自己的耳朵豎得高高的。\n\n我想他們是怕了你了，&lt;name&gt;。", rewards = "絲綢大師緞質護腿沐日腿甲皇澤鱗甲護腿泡泉光潔腿鎧金扇澤絲質長褲平原隼腿甲野生原腿甲雷足重型腿甲日歌裝甲腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][29909] = {title = "沒有菜頭了", objective = "找到安‧雷足。", description = "感謝你幫這麼多忙，<name>。如果你有興趣的話，我想給你另一件工作。\n\n我的兒子安在山丘下經營一片小農地。他應該要在今天早上給我送來一些水果和蔬菜，不過我一整天都沒看到他的人影。\n\n你可以去那兒看看發生什麼事了嗎？", progress = nil, completion = "什麼…？你是…？我父親派你來的？\n\n啐…他有時候還真愛多管閒事。這裡一切都在我的掌控之下。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29910] = {title = "橫衝直撞的齧齒動物", objective = "趕走雷足田地的6隻肥嘟嘟的土撥鼠，並封住6個土撥鼠洞。", description = "我今天早上跑出去看爸爸和兔妖的對抗。當我回來的時候，田裡全都是土撥鼠！\n\n我不想殺死牠們，不過我得把牠們趕走。嘿，我知道了！我們可以把鼠洞封起來！\n\n用土把牠們的洞封起來，這樣牠們就不能爬到我們的農田了。", progress = "土撥鼠看到你要封牠們的巢穴會很不高興的。", completion = "謝謝你，先生！現在我可以回去幹我的農活兒了。", rewards = "您能選擇下列奬勵中的一個：\n\n欠踹的土撥鼠\n\n您還會收到：\n\n欠踹的土撥鼠恆龍寶箱"}
MultiLanguageQuestData['tw'][29911] = {title = "幾近完美的出產", objective = "將新鮮的農產品箱子交給潘‧雷足。", description = "拿去，<name>。我父親在等這些蔬果。\n\n再次感謝你幫忙處理那些兔妖。", progress = "那是菜頭的味道嗎？", completion = "喲呵！這就是我在等的！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29912] = {title = "傳說中的范妮小姐", objective = "將安的巨大粉紅菜頭、安的夏日西瓜和潘的特辣豆腐交給范妮小姐並請她運送。務必將這批食物送到雷足農莊。", description = "我們會賣掉大部分的蔬菜，不過我想留下一些給我的家人。尤其是我的姪兒小梁，他需要一些蔬菜來餵豬。\n\n不幸的是，成群兔妖佔領了通往梁的農地的道路。我們只好拜託范妮小姐來幫忙了。\n\n把我們採收的食物送去房子的旁邊給范妮小姐。然後「和善地！」請她把食物送去梁的農地。", progress = nil, completion = "我知道是你將食物從我叔叔的農地那裡送過來的。謝謝你。\n\n我的豬很挑食，不過那些菜頭跟西瓜是牠們最愛的食物。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29913] = {title = "牠們會吃的肉", objective = "取得4份牡山獸肩頸肉排和80份龜肉碎塊。", description = "我先前告訴過你，我的豬很挑食。牠們要吃肉才能長得強壯，但牠們不喜歡羊兒，也不喜歡犛牛，顯然我也不可能餵牠們任何豬肉。\n\n不過呢，牠們會吃牡山獸的肉，也對烏龜有點偏愛。在西邊能夠找到很多這兩種動物。\n\n全世界都知道我的狩獵技巧很弱。你可以幫幫我這個年輕的農場主人和他的豬仔們嗎？", progress = "牠們肚子餓的嘶叫聲快把我給吵死了。\n\n只要你當過一陣子豬農，就能分辨牠們肚子餓的叫聲和平常的叫聲有什麼不一樣。", completion = "&lt;梁把肉一一分類。&gt;\n\n你不只是個&lt;class&gt;，還是個屠夫吧？你有能找出上等豬飼料的眼力，鄰居。", rewards = "平原隼軟帽野生原護盔金扇澤絲質軟帽絲綢大師緞質軟帽沐日軟帽皇澤鱗甲護盔泡泉光潔軟帽日歌裝甲軟帽雷足重型軟帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][29914] = {title = "回到豬圈", objective = "找到小堅、阿凌和臭臭。", description = "我試著盯緊我的家畜，不過牠們偶爾還是會溜走。因為兔妖肆虐造成的混亂，有時我對豬隻的注意力比較鬆懈，然後牠們就會趁機逃跑。\n\n你可以幫我找找牠們嗎？你可以從西邊的山腳下開始找起。", progress = "你找到牠們了嗎？我想應該只有三隻豬走失吧。", completion = "是牠們！你們三個，立刻回到豬圈裡！\n\n&lt;梁看著你。&gt;\n\n謝謝你，鄰居。我真心感謝你的幫助。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29915] = {title = "鄰居的職責", objective = "將亂跑的羔羊帶去給牧童法蘭西斯。", description = "看起來我不是唯一弄丟家畜的人。法蘭西斯又有一隻羊跑來我的農地裡閒晃，這已經是這禮拜第三次了。我開始覺得他需要有人幫他管好自己的家畜。\n\n你應該去看看他，鄰居。順便把這隻可憐的小東西帶回去。", progress = "噢…你找到了…我的羊？", completion = "你真不該把這隻羊帶回來給我的。牠…牠在豬圈比待在這裡還要安全。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29916] = {title = "尖刺之爪和垂涎之顎", objective = "殺死5隻行竊的平原隼和6隻行竊的狼。", description = "一開始是老鷹，你也許已經看到一些在天空上盤旋了。\n\n不久後狼也來了。我想牠們應該察覺到了我的軟弱。\n\n我根本不像尚大師所認為的那般勇敢。如果我再不對這些野獸做點什麼，大師一定會對我非常生氣的。\n\n可以…可以幫我嗎，<先生/小姐>？", progress = nil, completion = "牠們…牠們是不會停止的，不過至少我們反擊了。對吧？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29917] = {title = "魯沛羅", objective = "殺死魯沛羅。", description = "我在想…如果我們能殺死這群狼族的頭子，說不定牠們就會停止攻擊了。\n\n我們叫牠魯沛羅，牠就在河岸的對面徘徊。\n\n<法蘭西斯的注意力被另一波攻擊打斷。看來你要自己去處理魯沛羅了。>", progress = nil, completion = "我知道和牠們對抗是我的責任。也許我終究還是沒能力當個牧羊人。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29918] = {title = "勇氣修行", objective = "使用牧羊人套索來制伏一隻大白平原隼。", description = "<尚大師對著他的牧童說。>\n\n法蘭西斯，你需要展現你的勇氣！ 你擁有一個偉大牧羊人所需要的一切，你欠缺的只是面對恐懼的勇氣！\n\n<他端詳著你。>\n\n你， 陌生人。你曾幫助我其他的家人。法蘭西斯就像我的第二個兒子一樣。\n\n讓我的學徒知道甚麼叫做無畏。利用這個套索來制伏一隻天上的大白隼。\n\n<尚大師指向天空，並看了法蘭西斯一眼後就離開了。>", progress = "我可以感受到，在你的心中你無所畏懼。", completion = "法蘭西斯花了比我想像還久的時間來成為一個優秀的牧者。我們都經歷過這些階段…我的兒子梁也曾經脆弱過。而我也是。\n\n但他終究能學會。那就是雷足之道。", rewards = "鷹羽指環套索戒環牧羊人戒環勇敢指環勇氣戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][29919] = {title = "英雄所飲略同", objective = "護衛老陳‧風暴烈酒與莉莉到西南方的酒坊。", description = "真是山水有相逢啊，<name>。多麼有緣，我們已經巧遇彼此四次了？\n\n聽著…我的酒桶幾乎快要乾了。我曾聽說在西南方有一個酒坊，而那正是我們的目的地。要加入我們嗎？", progress = nil, completion = "如果你在找啤酒，你來對地方了，好鄰居。\n\n只是，啊…原諒這裡亂七八糟。過去幾天兔妖確實給我帶來了一些麻煩。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29920] = {title = "取得認可", objective = "挑戰並擊敗潘達族王金流、潘達族王風毛和潘達族王藤杖。", description = "樓試著向潘達族王祈求迎娶我的認可。儘管逝世已久，他們的祝福還是具有很大的份量。\n\n只是，他們都是魂靈，我們帶來的禮品或貢物全都沒能打動他們。他們宣稱，唯有樓或一名勇士能在比武中打敗他們，我倆才能贏得他們的祝福。\n\n小樓是個好人，但並不是一個戰士。\n\n你能擔任我們的勇士嗎？", progress = nil, completion = "他們…同意了？！太棒了！真是感激不盡！有了他們的祝福，我們會成為這片土地上最快樂的熊貓人！\n\n請收下這個。我們原本想供奉給族王們，但他們似乎不感興趣。", rewards = "禪心蓮花墜飾晨綻項鍊谷歌墜飾綠石墜飾翠玉之眼墜飾您會收到：\n\n"}
MultiLanguageQuestData['tw'][29922] = {title = "尋找智慧", objective = "和風箏大師歐南談話並前往晨綻。", description = "你不在的時候，博學行者阿洲過來問起你。\n\n他在北邊的晨綻鎮裡，急需你的協助。至於原因，他沒有提及。\n\n去找風箏大師歐南。他會樂於將你送去晨綻鎮。", progress = nil, completion = "你的行動讓我回想起一個遺忘已久的記憶，和一個古老的預言有關。這值得調查。\n\n我需要玉來進行調查工作。我已經指示托亞儘可能地收集玉，並在完成後把玉交給你。把那些玉帶來給我，讓我們看看能不能解譯出古老的「帝王之兆」。\n\n當他收集玉的時候，你可以隨意四處探索。你或許會發現鎮上的人們都需要像你這種有能的人。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29924] = {title = "殺死剋山", objective = "在老虎林殺死剋山。", description = "剋山是個很大的廢渣。\n\n他幹掉了我所有的兒子！咿咿、哪哪、噎噎、嗶嗶，還有很多我不記得了。\n\n怪怪人要幫忙猴人？幹掉剋山！\n\n那個廢渣就在那裡。\n\n<尼比‧尼比指向東邊。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29925] = {title = "最後餘力", objective = "將搜來的翠玉送去帝王之兆給博學行者阿洲。和晨綻的托亞談話來乘坐交通工具。", description = "好吧，我已經用一切方法去請求援助。這就是我們現在擁有的。\n\n希望阿洲肚子裡有點盤算!\n\n準備好去見他時告訴我一聲。我已經為你備好交通工具。", progress = "啊，又見面啦，<name>!所以你收到我的信息囉?", completion = "我就知道托亞會幫我解圍的!\n\n你懂的，他什麼好東西都弄得到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29926] = {title = "玉石災害", objective = "在綠石採石場殺死12隻綠石啃咬者和6隻綠石暴食者。", description = "你曾看過岩蛛嗎，<class>?通常無害，只是爬來爬去啃食石頭，但牠們愛吃玉的程度就像小崽子們愛吃糖一樣。小子們管牠們叫「啃咬者」。\n\n幾天之前，我們把這種傢伙的一處大巢穴給挖穿了。牠們像潮水一般湧入礦坑，跟瘋子一樣狂啃視線裡的所有東西。甚至啃了我的一些小子。\n\n你到裡面去料理掉牠們，我們有不少的玉可以分享給你。採石場就在這裡的正西方。", progress = nil, completion = "喔見鬼啦...你還真成功了!\n\n你想要更長期的工作嗎，兄弟?我用得上像你這樣的全職打手!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29927] = {title = "蔓恩的男人", objective = "在綠石採石場找到郝‧蔓恩。", description = "<難得地，工頭放低了聲音。>\n\n聽著，這對我不是容易的事…我得請你幫另外一個忙。我的蠢老公，郝，是採石場那邊的一個領班。我跟他說過別回去，太危險了，但他不僅跟個猴人一樣頑固，還加倍的笨。他說小子們要有他才會「士氣大振」。\n\n<蔓恩冷笑一聲。>\n\n那誰來讓我士氣大振？！那個呆瓜死掉的話我該怎麼辦？！\n\n拜託…去照顧他一下。叫他趕快回家。\n\n<她的眼神軟了下來，並趕緊轉過頭去。>", progress = nil, completion = "&lt;郝抬頭看著你，掙扎著想從石礫間脫身。&gt;\n\n不用不用。我自個兒行。哼咿咿咿咿！！\n\n好吧。也許我不行。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29928] = {title = "無玉狂嘯", objective = "從綠石石匠區附近的惡作劇的妖精那裡取得15份大塊的玉。", description = "我們整條玉礦補給線都崩潰了。礦坑淪為死亡陷阱，士氣創歷史新低;而就在你以為不能更糟的時候，石匠區竟然被木之妖精給入侵了！\n\n現在是連植物都要來弄我就對了！\n\n你這麼需要玉的話，可以順著西南邊的路前往石匠區，自己去從那些筷子妖怪的手上搶。", progress = "<曼恩眼巴巴地看著你，鼻翼掀動著。>", completion = "拋繡球？他們在拿我的貨物玩拋繡球？！\n\n希望你有給這些活動牙籤一點顏色瞧瞧。\n\n知道嗎，你或許終究不只是個小崽子。我早就在物色一些打手幫我解決礦坑那邊的麻煩。\n\n根據博學行者在這裡回復工作的規模，我想你還需要更多更多的玉。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29929] = {title = "受困！", objective = "在綠石採石場解救8名綠石礦工。", description = "<郝用吃奶的力氣推擠著石礫。>\n\n哼呃呃呃呃!!\n\n讓我猜猜:我老婆派你來的?你看看，我可愛的小雪花擔心了。哈哈!她老是像個麥芽糖黏著我不放。聽著，哼呃呃呃呃!!一點小坍方還阻止不了郝爺。\n\n但我手下的一些小子可就有麻煩了。遇上的話就幫幫他們吧，行嗎?我沒事的。\n\n真沒事的。", progress = nil, completion = "&lt;郝放聲大笑。&gt;\n\n我看到他們像被老剋山追在屁股後面似的拼命跑了出去。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29930] = {title = "挖到就是你的", objective = "乘上裝載玉的貨車，和郝一起返回帝王之兆。", description = "好咧，所以你需要玉，是吧？我得說那是我們欠你的。我們採石場裡有很多玉，而且多虧你的幫助，我們應該很快就能趕上時程。\n\n我想我該回去找老婆了，就讓我們把這車好東西直接送到她那邊吧。\n\n好咧，這世界上沒有我推不動的<race>。爬到車子上吧，讓郝爺我負責體力活。", progress = "如何？老郝在哪裡？\n\n別跟我說你找不到他…", completion = "你成功了！你把我的蜜糖熊熊帶回來了！\n\n喔感謝你，&lt;name&gt;！感謝你！", rewards = "翠綠披風蜜風披風蔓恩的披風蜜糖熊斗篷雲落披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][29931] = {title = "蟠龍之心", objective = "到翠玉林裡的蟠龍之心找工頭雷克。", description = "你做得非常好，孩子。多虧了你，我們現在還有不少多餘的玉。而我剛好知道某人可能用得上這些玉。\n\n我的朋友工頭雷克正在蟠龍之心那裡進行大型雕像工程。\n\n送一批額外的玉過去給他，跟他說這是來自老朋友曼恩的問候。我敢說他正焦急地等著這批貨物。", progress = nil, completion = "我眼睛沒花吧？一整車無瑕疵、高品質、未加工的玉礦？\n\n感謝老天啊。我就知道曼恩會幫我們度過難關的。\n\n喔當然還有你。感謝你幫忙送來。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29932] = {title = "玉蛟寺", objective = "到玉蛟寺的入口外和大賢者風怡談話。與『風箏大師』修苦交談以乘坐風箏到寺廟。", description = "你給我們幫了個大忙，旅人。\n\n現在我們有了足夠的玉礦來建造雕像，我們該知會玉龍，也就是玉蛟一聲。\n\n抵達玉蛟寺時，在入口外和大賢者風怡談話。\n\n如果你想要縮短旅程時間，去找『風箏大師』修苦，我肯定他願意借一只風箏給你。", progress = nil, completion = "你帶了來自蟠龍之心的消息?\n\n&lt;大賢者耐心聽你講述發生在玉礦和巨大玉像那裡的事。&gt;\n\n謝謝你千里跋涉而來，陌生人。然而，我目前還不能讓你和玉蛟談話。\n\n玉龍非常忙碌，而且如你所見，祂此刻不在這裡。", rewards = nil}
MultiLanguageQuestData['tw'][29933] = {title = "蟲蟲腿影", objective = "在老虎林從虎蜂身上取得30條蟲腿。", description = "你真的是猴人的朋友嗎，怪怪人？我們等著瞧，嗯？\n\n葛魯山丘的猴人都沒有滑魚的餌了。虎蜂的腿在水裡晃來晃去，就是最好的餌！\n\n波波被叮到了，不舒服。怪怪人去拿餌然後帶去葛魯山丘。", progress = "滑滑的食物！", completion = "喔耶！喔耶！怪怪人是好廢渣！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29934] = {title = "潛至拉文霍德", objective = "和朱紅壁壘的莫爾斯塔茲交談，然後一起飛行至拉文霍德莊園。", description = "要是蛋還在拉文霍德莊園的話，我們就不能冒險發動全面進攻。我需要有人潛入調查事實的真相。\n\n這個人就是你了，<name>。\n\n莫爾斯塔茲會幫你進入到內部。去外面與它交談然後一起飛到拉文霍德。祝你好運!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29935] = {title = "命令就是命令", objective = "把聯盟命令帶去葛魯山丘給卡卡酋長。\n\n已提供物品：\n", description = "嗯，也許怪怪人畢竟不是那麼壞！\n\n其他沒毛的傢伙對猴人不好。\n\n猴人從壞蛋怪怪人那裡拿到這個！\n\n所有怪怪人戰利品都在卡卡酋長的管轄下！\n\n哪，怪怪人。你拿著。卡卡會想見猴人的新朋友。\n\n他的營地在葛魯山丘的南邊。", progress = nil, completion = "嗯。\n\n壞怪怪人打好怪怪人？\n\n猴人也跟壞怪怪人戰鬥！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29936] = {title = "即時通", objective = "在葛魯山丘的卡卡酋長附近，使用地獄吼之拳的信號煙火。", description = "歡迎，怪怪人!我卡卡，葛魯山丘猴人的酋長。\n\n大廢渣烏坎想當酋長，但好怪怪人痛扁他，送卡卡好大禮物。\n\n猴人也有禮物送給好怪怪人。來自撞壞大飛機的禮物，猴人為怪怪人保護它安全。", progress = nil, completion = "你讓我印象深刻，&lt;name&gt;。\n\n我從沒想過有和這些生物當朋友的可能。\n\n被他們接受之後，我們可以將注意力轉移到更重要的事物上。", rewards = "友情之戒贊同指環友好之禮指環天資指環發現指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][29937] = {title = "憤怒鳥", objective = "從猴屍地的血爪那裡取得6把鳥腸。", description = "這些傢伙喜歡魚，是吧？不如，我們讓你的成果更進一步，讓他們愛死我們？\n\n我還有一些從船難中搶救出來的炸藥，現在只欠某種能吸引魚的東西。\n\n腸子應該能完成這項工作。屢試不爽。我看到鎮子南邊有些鳥在飛。\n\n你還在等什麼？", progress = "你的手沒沾到那些東西吧？", completion = "耶！\n\n就是這寶貝。你等著瞧吧…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29939] = {title = "手到擒魚", objective = "在莫奇河岸使用鳥腸炸彈以取得5條爆炸的滑魚。", description = "來。我把你的鳥腸黏到我的炸藥上了。\n\n我稱之為鳥腸炸彈。專利申請中。\n\n既然你和這些傢伙成了朋友，何不由你來執行？\n\n只要點燃引線然後丟到海岸外就行了！", progress = "我還沒遇過炸藥解決不了的危機。", completion = "我們剛為這些憨族…我是說猴人的捕食方法帶來劃時代的改進。\n\n他們再也不一樣了！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29940] = {title = "找作物", objective = "取得5份遭竊的菜頭和5份遭竊的西瓜。", description = "好吧、好吧。並非所有事情都在掌握之中。我花了一整個早上和兔妖搏鬥，雖然設法把他們趕出了田裡，但他們還是帶著我的作物跑掉了。\n\n他們把我的作物帶到南邊的河。我不知道他們拿走作物打算幹嘛，可能不是吃就對了。\n\n我需要有人去幫我把作物拿回來，才能讓我父親收到他想要的蔬果。你願意幫忙嗎？", progress = "我需要你的幫助，才能讓父親收到想要的蔬菜。", completion = "太棒了。\n\n&lt;安看了看表面受傷的菜頭還有泡了水的西瓜。&gt;\n\n他們到底在那裡幹了什麼！？", rewards = "絲綢大師緞質手套沐日手套皇澤鱗甲護手泡泉光潔手套金扇澤絲質手甲平原隼手套野生原護手雷足重型護手日歌裝甲護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][29941] = {title = "地平線的另一端", objective = "與修基雅、士官哥羅克、影王卡玲和卡卡酋長交談。", description = "我記得你在這所做的一切，<class>。我會在呈交大酋長的報告中附上你的功績。\n\n但我們沒有休息的時間！\n\n我們必須探索和記錄這塊土地，做好讓部落進駐的準備。我已經決定好進行這項工作的派遣隊人選。\n\n在他們變得安逸之前找到他們，把任務內容告訴他們，並試著說服你的新朋友派人擔任嚮導。\n\n而你將和我一起留下來，我們有些準備工作得做。", progress = nil, completion = "做得好，&lt;name&gt;。\n\n你所組織的派遣隊出發了。\n\n我希望哥羅克有點常識，能記得把他那套紅衣服給換掉。我佩服他的熱情，但他從我們離開奧格瑪開始就一直穿著它。\n\n穿著那玩意，我想他們也不用想偷襲任何人了…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29942] = {title = "笨蛋怪怪人，肉肉給猴人", objective = "從莫奇河岸那裡取得4份鉗嘴龜排。", description = "你以為猴人很瘋嗎，怪怪人？等你看到沒有滑魚的猴人就知道！\n\n沒有足夠的滑魚給猴人和怪怪人了！\n\n鉗嘴龜！猴人討厭臭鉗嘴龜。怪怪人吃掉所有的臭鉗嘴龜！\n\n<伊果伊果指向南邊。>", progress = "怪怪人幹掉臭烏龜了沒？", completion = "現在每個人都有食物了！伊果伊果有偉大的猴人智慧。\n\n或許伊果伊果有天可以當酋長…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29943] = {title = "搜索游擊隊", objective = "在觀景台附近殺死8名聯盟滲透者。", description = "安杜因‧烏瑞恩王子。我們敵人國王的兒子！命運再次眷顧了部落，<name>。\n\n但這也是一柄雙面刃。如果以為那孩子會這樣被拋棄，我們可就太天真了。\n\n這片土地上的聯盟傢伙肯定全都拼了命在搜尋他們的寶貝王子。\n\n我們要一起掃蕩這個區域，挖出他潛在的援兵。", progress = nil, completion = "太好了！\n\n索爾的血拳啊，我真懷念狩獵聯盟的傢伙！", rewards = "琥珀霧腕輪黑木林束腕玉巫婆腕甲玻璃湖護腕絲林腕輪深林裹臂狐林腕甲雷木臂鎧翠玉虎臂鎧您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29944] = {title = "繁殖的源頭", objective = "殺死『煎鍋』艾玉，『爪刃』吉安雅，和嗨翻天。", description = "在開酒之前，有件工作我們必須要做。這些兔妖和漂流島上一樣…都是群繁殖速度相當快的麻煩兔子。\n\n當然，我們可以把他們每一隻都宰了，但又何必製造這些無意義的屠殺？不如我們直接解決他們的繁殖源頭，這樣應該就可以減緩他們的…繁殖。", progress = nil, completion = "&lt;老陳點點頭。&gt;\n\n幹得好，&lt;name&gt;。你戰鬥還挺有兩下子。\n\n我們搭檔挑戰下個階段如何？", rewards = "您能選擇下列奬勵中的一個：\n\n菜頭沙包\n\n您還會收到：\n\n菜頭沙包恆龍寶箱"}
MultiLanguageQuestData['tw'][29945] = {title = "黃加紅等於橘", objective = "取得10個草原金盞花與40瓶動物之血。", description = "老陳叔叔說我們要幫助這傢伙處理兔妖的問題。這我沒問題！我超愛惡搞這些兔妖。\n\n計畫是這樣:我們來把一些菜頭漆成橘色，然後試著讓兔妖相信它們是胡蘿蔔。\n\n這將是一齣很精彩的搞笑劇。\n\n我會負責收集菜頭。你去找些原料來製作食用橘色塗料。", progress = "我收集到了一些菜頭。你準備好製作塗料的東西了嗎？", completion = "哇哇哇！你帶回了「血」？看來我在請你帶回紅色東西前應該先花點時間到處看看的。\n\n好咧！\n\n&lt;莉莉花了點時間將花瓣搗碎，並混入了一些動物的血&gt;\n\n&lt;她開始竊笑。&gt;", rewards = "您能選擇下列奬勵中的一個：\n\n菜頭噴漆「槍」\n\n您還會收到：\n\n菜頭噴漆「槍」恆龍寶箱"}
MultiLanguageQuestData['tw'][29946] = {title = "兔妖穴母", objective = "擊敗兔妖穴母秋法。", description = "我們已經招呼過他們族中的雄性「種兔」，現在該輪到那些雌性的了。\n\n兔妖交配的時候不是非常挑，但大多數群體中還是找得到一隻「種母」般的存在。與其他兔妖相比，她體型通常比較大，心眼比較壞，也比較兇狠。\n\n你知道的，我不介意在這種兔妖穴母身上練習我的新招式。我可以跟你一起戰鬥嗎？", progress = nil, completion = "那應該可以讓兔妖們安分幾個禮拜了。足夠讓泥杯不受干擾地釀造出一些美味的啤酒。\n\n這很重要不是嗎？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29947] = {title = "臥蘿蔔藏菜頭", objective = "把橘色菜頭丟到12隻抽腳囤積者面前。", description = "老陳叔叔仍在監視著我，也就是說我沒辦法繼續瞎晃了。看來只有靠你把這些菜頭…嗯我是說『蘿蔔』…送到蜿蜒地穴裡。\n\n我想這應該相當簡單。只要把這些蔬菜扔到兔妖面前，然後看他們啃下這些菜頭後是什麼反應！", progress = nil, completion = "哇哈哈哈哈哈！我愛惡搞這些兔妖。", rewards = "您能選擇下列奬勵中的一個：\n\n塗成橘色的菜頭\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][29948] = {title = "直搗賊心", objective = "在蜿蜒地穴中找回6袋遭竊的啤酒花。", description = "你跟那個叫老陳的傢伙都是好人，幫助我處理兔妖的問題。我不喜歡開口拜託，但也不會拒絕別人的好意就是了。\n\n在解決那些兔崽子的同時，你應該不介意順便看看附近有沒有一袋袋的穀子吧？ 我確信他們昨晚偷走了這些袋子。\n\n按照他們的習性來說，恐怕是拿來當枕頭。", progress = "我警告過那些兔妖離我的土地遠一點了。", completion = "噢，真的很感謝你，先生。你是個貨真價實的紳士。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29949] = {title = "精神食糧", objective = "跟老陳、莉莉，與泥杯喝一杯。", description = "我得說，我們的努力終於開花結果了。我等不及來嚐嚐泥杯都釀造了些甚麼。", progress = nil, completion = "我知道陳叔叔還會回來。我並不擔心。\n\n事實上，這可能是我探索潘達利亞最好的機會！再也沒有胖叔叔整天管東管西！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29950] = {title = "莉莉放風去", objective = "帶莉莉到絲綢場、新席非拉，與皇澤瀑布。", description = "陳叔叔要我別在他不在的時候惹麻煩…但可沒說我不能去探險。終於，我可以自由地探索潘達利亞，不用每走47步就休息一次！\n\n你要一起來嗎？ 我打賭附近不遠就有各式各樣的酷地方可以探索。", progress = nil, completion = "太棒了！ 有機會我們該再去探險一次。\n\n而且看來我們在陳叔叔回來之前完成了這次探險，完美啊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29951] = {title = "泥水", objective = "使用泥杯的水瓶來收集泥水。", description = "雖然你只是在閒晃，但我還是會讓你參與我釀造啤酒的『程序』。其實沒有太多的程序啦，真的…我只是把所有的材料混在一起然後等待。\n\n你可能聽說過，我喜歡使用南方河岸的泥水。你介意幫我把這瓶子拿去裝滿那種水，並帶回來給我嗎？我會負責把啤酒花和大麥準備好。", progress = "第一眼看到你，我就知道我們可以做朋友。", completion = "幹得好，&lt;name&gt;。你做得很好。", rewards = "絲綢大師緞質足靴沐日護足皇澤鱗甲脛甲泡泉光潔護脛金扇澤絲質足靴平原隼長靴野生原脛甲雷足重型戰靴日歌裝甲戰靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][29952] = {title = "破碎的夢", objective = "與老陳‧風暴烈酒談話並聆聽他的故事。", description = "是的，我發現了風暴烈酒酒坊…儘管沒有受到我所期望的溫暖接待。\n\n<老陳幫自己倒了杯麥酒。>\n\n你想聽故事嗎？", progress = nil, completion = "或許我註定漂泊一生。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29966] = {title = "燒為平地", objective = "用納茲格寧姆的烈酒摧毀觀景台頂上的聯盟營地。", description = "看啊，<name>！\n\n這些聯盟狗在山脊上造了一座營地。\n\n把我的酒拿去。給他們來一場連在暴風城都能看見的大火！\n\n為了部落！", progress = nil, completion = "我們一定要把聯盟的傢伙從這片土地上剷除，&lt;name&gt;！\n\n半調子的行動是不行的！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29967] = {title = "引爆的時機到了", objective = "到葛魯山丘東邊找理弗特。使用他的甲烷手榴彈對抗錦魚人的攻擊。", description = "緊急事件!\n\n看來你殺死這些魚一樣傢伙的行動是捅到馬蜂窩了。\n\n現在他們打算對葛魯山丘發動全面反攻!\n\n我本來希望有多一點的開發研究時間，但我的甲烷手榴彈理論得趕鴨子上架啦!\n\n到堡壘的東邊和我碰面，記得把你丟炸彈的那隻手帶著!", progress = nil, completion = "這已經不能光以打退敵人來形容啦!", rewards = "錦魚人冥想法杖錦魚人預言魔棒錦魚人鬥杖錦魚人巨劍錦魚人手斧錦魚人之弩錦魚人戰斧錦魚人儀式權杖錦魚人匕首錦魚人鬥錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][29968] = {title = "綠綠的能量", objective = "在猴屍地收集7個翠綠枝。", description = "兩個字:甲烷！\n\n我們要響應環保。完全燃燒、容易取得、完全天然，而且能讓我們回去的時候不會被德魯伊們碎碎唸。\n\n除此之外，我的火藥也用光了…\n\n所以，我需要你的幫忙，<name>。\n\n不，不，我不是要你去做那種髒活兒，尤其不會在將軍面前。我會自己去收集那些「沉積物」。\n\n你去收集一些蓋廁所用的木頭，我可是有個長遠的計畫！", progress = "要小心濕濕的那種…咿咿！", completion = "啊，聞起來大有進展，還帶點甲烷味。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29969] = {title = "破损的土灵雕像", objective = "运用你的技能和材料，修复破损的雕像。", description = "这只破损的雕像被它的主人扔掉了。不过，只要有合适的材料，再加上你的珠宝加工技能，就可以完全修复它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n刻像 - 土靈守護者"}
MultiLanguageQuestData['tw'][29970] = {title = "破损的土灵雕像", objective = "运用你的技能和材料，修复破损的雕像。", description = "这只破损的雕像被它的主人扔掉了。不过，只要有合适的材料，再加上你的珠宝加工技能，就可以完全修复它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n刻像 - 土靈守護者"}
MultiLanguageQuestData['tw'][29971] = {title = "探子回報", objective = "到葛魯山丘找修基雅。", description = "嘿，你跑出去的時候，我們的斥候回來了。聽著，他們找到了什麼聯盟的小子。\n\n你或許該去聽他們簡報。", progress = nil, completion = "我們恐怕遇上麻煩了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][29981] = {title = "阻擋蟲群", objective = "在石犁村殺死14隻伊克席克螳螂人。", description = "我不是本地人，今天算是第一次到這裡，即使如此，我也看得出來事情不太對勁。\n\n那座長城是為了阻擋螳螂人入侵熊貓人領土而建造的。現在，螳螂人派出他們長了翅膀的斥候從上方穿過，彷彿城牆根本不存在一般！\n\n那些瘦弱的螳螂人苟活到現在，是因為他們專挑農夫攻擊，而不找戰士。對上你，他們一點機會也沒有。", progress = nil, completion = "林請你來幫助我們？她想得太多了。\n\n不過，我們確實缺人手。我們不會拒絕你…或是那女孩的協助。感謝你，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29982] = {title = "撤離命令", objective = "疏散黑土家族、鏟爪家族、青磧家族和泥毛家族。", description = "有部分農夫仍不肯離開農地…其中某些甚至離崩毀的城牆特別近。我不希望有農夫在那邊逞英雄。等我們處理掉螳螂人大軍後，他們才能安然返家。\n\n我的影潘已為了保護這個村子而疲於奔命，無力組織疏散行動。你想證明自己幫得上忙？把這些農夫引導到安全的地方。", progress = nil, completion = "有些固執的農人想讓我的工作變得更難做？\n\n&lt;警備指揮官嘆了口氣。&gt;\n\n好吧。我不會奪走任何一名熊貓人保衛自己土地的權力。", rewards = "日歌裝甲肩鎧雷足重型肩鎧野生原肩鎧平原隼肩鎧金扇澤絲質肩鎧泡泉光潔肩鎧皇澤鱗甲肩鎧沐日肩鎧絲綢大師緞質肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][29983] = {title = "隱居的宗師", objective = "到四風峽找淤爪大師。", description = "現在開始，我們應該有能力防守石犁村了。\n\n<警備指揮官伸手指向林‧嫩爪。>\n\n這位林‧嫩爪正在搜尋某個她稱之為「隱居的宗師」的人。我想我知道她說的是誰，我還有些線索可以給你。\n\n向北走吧。", progress = nil, completion = "你想要接受修練？\n\n&lt;熊貓人沉默了幾秒，專心地研究著你的體格。&gt;\n\n好吧。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29984] = {title = "不屈之拳:竹之試煉", objective = "與淤爪大師談話，並成功的擊中竹子堆3次。", description = "我們將從竹之試煉開始。\n\n你的朋友林在這項測試中失敗了。\n\n跟著我，並仔細聽我的解說。", progress = nil, completion = "你很有潛力，&lt;name&gt;。我們將繼續。\n\n是讓你接受第一回合的修練的時候了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29985] = {title = "化身成霧", objective = "殺死12隻迷霧化身。", description = "這森林裡的霧一直是個麻煩。一個我很樂意交給你這種學徒來處理的麻煩。怪異的生物潛伏在這些霧裡，你必須三不五時地與牠們戰鬥來趕走牠們。\n\n把這也當成你修練的一部份。", progress = nil, completion = "你將我的指示執行得很好，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29986] = {title = "霧之結界", objective = "點亮北邊的霧之結界，西邊的霧之結界，以及南邊的霧之結界。", description = "受訓弟子。\n\n我房子附近的樹林裡，藏了幾個霧之結界環繞我們四周。它們能很有效率地驅散這些霧，但是需要持續的維護。\n\n你可以在北邊，西邊，南邊各找到一個。找到這些霧之結界並點亮它們。", progress = nil, completion = "你讓你的同族感到驕傲，&lt;name&gt;。", rewards = "三罪項鍊胡倫的項圈相對和平項鍊歌頌沼澤護符奧圖西亞護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][29987] = {title = "不屈之拳:木之試煉", objective = "與淤爪大師談話，並成功地擊中木材堆4次。", description = "我想，你的修練已經有些進展了。跟著我來，讓我們來試試木之試煉。", progress = nil, completion = "你擁有專注的天份，&lt;name&gt;。我的學生很少成功走到這一步。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29988] = {title = "鳥蛋的風味", objective = "取得10顆帝王燕鷗蛋，4顆白漁鶴蛋，以及1顆陸行犀鳥蛋。", description = "我可以感受到你的焦慮，但你還沒有準備好。在面對最終的試煉之前，你的修練必須持續下去。至於你的任務…我要你去幫我拿些蛋來。\n\n是的，蛋。東邊丘陵上的沼澤是一大群鳥的巢穴，一般說來牠們本性都相當溫馴。你應該可以輕鬆拿到足夠我過好幾個禮拜的鳥蛋。", progress = "你的鳥蛋狩獵進行得如何？", completion = "現在你知道為什麼我不自己去收集那些蛋了。\n\n我們可以繼續你的修練了嗎？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29989] = {title = "不屈之拳:石之試煉", objective = "與淤爪大師談話，並成功地擊中石板堆五次。", description = "你在這短短的時間內，已經完成了許多成就，<name>。我通常不會那麼快就讓人進行這項試煉…但我感覺到你已經準備好了。\n\n是時候讓你接受石之試煉了。", progress = nil, completion = "&lt;淤爪大師向你鞠躬致意。&gt;\n\n石頭在你的拳頭之下顫抖並碎裂。只要你真的想，你的力量已足以撼動山陵。\n\n我已經沒什麼東西可以教你了。", rewards = "絲綢大師緞質長袍沐日胸甲皇澤鱗甲護甲泡泉光潔護胸金扇澤絲質長袍平原隼外套野生原護胸雷足重型護軀日歌裝甲護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][29990] = {title = "訓練與紀律", objective = "到四風峽的石犁村找輪眉。", description = "我曾告訴自己，如果有一天能找到隱居的宗師，我要努力學習他的一切。這是我的大好機會，<name>。我不會讓它溜走。\n\n不過，我恐怕石犁村需要我們。我在螳螂人的斥候部隊被擊退前就離開了。如果你能代替我去幫警備指揮官，我心裡會安心許多。\n\n喔，如果你遇到其他人，或許你該告訴他們隱居的宗師在哪…", progress = nil, completion = "很高興聽到林平安無事。\n\n我們的防線暫時沒事。螳螂人仍在派出斥候跨越到牆的這一邊，但除此之外他們沒有太多進展。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29992] = {title = "以嫩爪為名，柔掌成名", objective = "收集18片碧月葉。", description = "我想告訴曉、康恩還有其他人我找到宗師了，但現在他不讓我離開！他說我必須先通過竹之試煉才行。\n\n<林低聲說:>順便問問，你如何通過試煉的？\n\n目前看起來，我是只能被困在這裡，對著這顆石頭練習我的出拳哩。而我的關節都快要塌陷了。\n\n你能不能幫我收集一些碧月葉？那樣我就能準備一種藥膏，至少舒緩一下這些痛楚。", progress = "噢！噢！噢！", completion = "&lt;林暫停了一下並用這些樹葉摩擦她腫脹的手掌。&gt;\n\n謝謝你！我晚點會準備一些藥膏，但目前這樣就可以了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29993] = {title = "尋找小樓", objective = "和水墨大師老魏談話。", description = "你有看見我的兒子小樓嗎？他剛剛還在這裡，我才跟他講過我們今天就要離開。\n\n我敢說他一定又跑去向那個年輕的錫拉‧金流求愛了。那正是我們要離開的原因！\n\n我的兒子絕不能跟一個金流家的女孩跑走！\n\n我打算在這裡附近找他們。\n\n不過，我也常抓到他們兩個跑到落英園那邊。你願意過去找他們嗎？", progress = nil, completion = "你在找尋一對無視家族間紛擾的愛侶。他們是來過這裡，來這裡尋找力量，幫助他們堅持所走的道路。\n\n可惜，他們並沒有在山水或文藝間找到答案。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29995] = {title = "曙光廟", objective = "到曙光廟找錫拉‧金流。", description = "雖然他們的長輩這樣講，但你在找的那些「孩子」其實並非小孩，而是成年的熊貓人。他們的愛不會因為家族間的不和而被打斷。\n\n你會發現錫拉和小樓都在曙光廟，不斷向過往的諸位潘達族王們祈求解決他們困境的答案。", progress = nil, completion = "喔陌生人!請跟我說你能夠幫忙。他們真的把小樓傷得很重。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29997] = {title = "占卜者的困境", objective = "殺死水之惡魔並取回智者瑪利的法杖。", description = "既然你在礦坑裡幫了這麼多忙，你願意幫助敝寺解決一個小問題嗎？\n\n最近智者瑪利一直抱怨他的寺廟裡有了麻煩。\n\n水元素近來十分頑皮，甚至還偷走了他的儀式法杖。\n\n如果你願意幫這個忙，我會非常感激。我甚至可以在玉蛟那裡為你說幾句好話。\n\n沿著道路往北走吧。", progress = "水池罩上了一層雲霧。我需要我的法杖才能安撫魂靈和與水交談。", completion = "我只是條老錦魚人，完全無力去抓那些討厭的水靈。謝謝你，&lt;name&gt;。謝謝你把法杖帶回來給我。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29998] = {title = "圖書管理員的困惑", objective = "到寺廟的圖書館找博學行者石步。", description = "博學行者石步負責整座寺廟的圖書。最近有某件事讓他在工作上感到十分困擾。\n\n由於他身負著抄寫數千卷古老文書的工作，我不能容許任何事物讓他分心。\n\n你願意順著南邊的道路前往圖書館，看看是什麼在困擾他嗎？", progress = nil, completion = "大賢者雨竹派你來的？\n\n很好。你可以幫我個忙。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][29999] = {title = "騎兵的約束", objective = "找到4條好動的戰蛟。", description = "你看到訓練場上的那些年輕戰蛟了嗎？\n\n年紀小的戰蛟通常特別淘氣，現在其中一些在訓練課程開始前溜出去玩了。\n\n女主人若發現牠們失蹤，可是會大發雷霆的。\n\n你願意幫忙尋找並把牠們給帶回來嗎？我不希望牠們遇上麻煩。\n\n牠們喜歡在開闊的地方玩，你可以去庭園或尖柱的周圍找找。", progress = nil, completion = "你把牠們全都找到並帶回來了！\n\n牠們好像真的很喜歡你。\n\n真的很感謝你！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30000] = {title = "玉蛟", objective = "聆聽玉蛟的話。", description = "你是來傳訊給玉蛟的對嗎？\n\n<小女孩歪過頭，好奇地看著你。>\n\n我想是讓你見她的時候了。", progress = nil, completion = "你的訊息傳遞到了嗎？", rewards = "琥珀霧兜帽黑木林頭盔玉巫婆頭盔玻璃湖頭罩絲林風帽深林頭盔狐林頭盔雷木頭盔翠玉虎頭盔"}
MultiLanguageQuestData['tw'][30001] = {title = "蛾滿為患", objective = "殺死8隻斑紋飛蛾。", description = "圖書館被蛾侵佔了。蛾!\n\n隨便一個夠格的圖書館員都知道蛾是紙張的最大威脅，僅次於書蟲。\n\n到頭來，我的助手都是一群怕蟲的膽小沒用傢伙。\n\n拜託，你得馬上幫我處理掉這些蛾!上千名熊貓人敘事者的心血結晶仰賴著你!", progress = nil, completion = "太好了，太好了，謝謝你!你大大削減了牠們的數量。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30002] = {title = "歷史書頁", objective = "檢驗圖書館裡的書籍，壓扁12條書蟲。", description = "最糟的情況發生了，<race>。\n\n我們、有、書蟲!\n\n這是致命的危機。必須殲滅圖書館裡的每一條書蟲才能防止牠們擴散。\n\n我們得碾碎這些大麻煩!請你檢驗圖書館裡的書籍，壓扁你所看見的每一條書蟲。", progress = nil, completion = "喔，太好了!解決了這場禍患讓我大大鬆了一口氣。\n\n別!別!拜託不要靠我太近。你的鞋子上還是有被壓扁的蟲子。", rewards = "琥珀霧足靴黑木林護足玉巫婆脛甲玻璃湖護脛絲林足靴深林長靴狐林脛甲雷木戰靴翠玉虎戰靴您會收到：\n\n琥珀霧足靴黑木林護足玉巫婆脛甲玻璃湖護脛恆龍寶箱"}
MultiLanguageQuestData['tw'][30003] = {title = "以貌取書", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30004] = {title = "諸事皆好", objective = "到翠玉林的玉蛟寺找大賢者雨竹。", description = "你想像不到你幫了我們一個多大的忙，<name>。\n\n如果我們就這樣失去珍貴的書卷，我真的不知道該怎麼辦。\n\n請回去找大司祭雨竹，告訴他圖書館已經沒事了。", progress = nil, completion = "博學行者石步又開始工作了？\n\n非常好。你完成了前四名司祭所不能完成的事。\n\n我…我的頭痛好像消失了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30005] = {title = "劃亮天空", objective = "發射8個煙火。", description = "你喜歡煙火嗎，<先生/小姐>？\n\n我超愛的！在過去，我們會發射煙火來嚇走惡魔，但我喜歡它們主要是因為看起來很美麗！\n\n我想寺廟裡還有一些以前的發射器。\n\n你願意幫我放幾個煙火嗎？我會很開心的！", progress = nil, completion = "耶!我打從這兒就能看到那些煙火!\n\n真是感謝你，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30006] = {title = "黑暗的包圍", objective = "殺死15個煞入侵者。", description = "儘管我們用盡全力，煞仍然打破了主寺周圍的封印。\n\n如果無法在這裡阻止他們，他們的黑暗會散播到整座翠玉林。\n\n我們需要你立刻伸出援手。殺死你所看見的每一個煞。他們應該不會太難找。", progress = nil, completion = "謝謝你，&lt;name&gt;。每殺死一個煞都能讓情勢好轉一些。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30007] = {title = "追踪事件：完成到达阶段", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30011] = {title = "新的幻象", objective = "到翠玉林的玉蛟寺院子附近找大賢者雨竹。", description = "請告訴大司祭雨竹我會立刻開始工作。", progress = nil, completion = "太好了!聽到占卜者繼續進行冥想真是讓我鬆了一口氣。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30015] = {title = "晨綻", objective = "到晨綻找博學行者阿洲。\n\n到葛魯山丘找飛行管理員以取得通行。\n\n已提供物品：\n", description = "鮮血與雷鳴！我的斧頭渴望戰鬥！\n\n在清除這片土地上的聯盟之前，我們絕不返回奧格瑪。\n\n有必要的話，我會親自訓練這些本地人。不管用什麼方法，這裡都會成為部落的殖民地。\n\n與此同時，他們的酋長要我把這個轉交給你。是一份地圖和一則用奇妙文字寫的訊息。\n\n做你必須做的事，但切記要快。\n\n戰爭的暗潮正醞釀著…", progress = nil, completion = "歡迎，&lt;name&gt;！\n\n歡迎來到晨綻，我同胞的家園。\n\n只可惜我必須離開了。唉，博學行者的工作永遠都做不完。\n\n請自便。你的天賦一定幫得上我同胞的忙。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30019] = {title = "长城缺口", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30027] = {title = "鐵桿修行", objective = "取得並裝備受訓員之杖。", description = "首先，你需要適合你天賦的兵器。到下面去，從兵器架上取一個法杖來給我，讓我看看你拿武器的姿勢正不正確。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30028] = {title = "取回穀物", objective = "將8袋穀物交給『榖物之王』凱。", description = "既然你要往南方去，你能試著拿回一些被偷走的穀物嗎？\n\n我們看見鳥和妖精帶著整袋的頂級貨，跑進東邊和南邊的原野。", progress = "這些鳥和妖精一日不除，我們就永遠無法達到風暴烈酒酒坊預定的配額。", completion = "謝謝你啊，陌生人。日子不好過，不過你讓生活有了一點起色。\n\n請收下它，這是你應得的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30029] = {title = "小把戲", objective = "殺死8隻狡猾的樹妖。", description = "就是...我們買進了大批的便宜穀物。結果發現這批穀物裡藏著一群妖精。\n\n我恨妖精，特別是他們小小的眼珠子，還有令人發毛的微笑。\n\n我想低調解決這檔事。我可以雇用你去幫我暗中除掉這些偷穀物的賊嗎?", progress = nil, completion = "謝謝你幫我這個忙，陌生人!順利的話，接下來的事我們能夠自己處理。", rewards = "榖物之王墜盒榖物之王頸飾榖物之王項鍊榖物之王墜飾榖物之王護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][30030] = {title = "消滅妖精", objective = "擊敗野蠻人麥王柯南。", description = "先把話說清楚，之前發生的全都是意外。我所做的一切，都是為了產業發展！\n\n我哪曉得什麼時候會蹦出個妖精入侵，也沒想到會有一隻妖精想把我的「潘家神奇成長藥劑」給吞下肚。\n\n這下可好，現在帶領他們的不但是一隻大妖精，還是一隻憤怒的怪獸。\n\n如果我付你錢，你願意幫我解決掉他嗎？", progress = nil, completion = "既然事情都解決了，我又想到一些製作新混合物的點子。結果如何，到時候就知道了。\n\n謝謝你幫忙。這是你的報酬。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30031] = {title = "口味評鑑", objective = "試吃陳年穀物、輕量榖物、新鮮穀物和麥芽穀物。", description = "當你在這的時候，應該可以幫我一點忙。我覺得自己沒辦法應付這項任務，因為我這輩子從來就沒喝過半滴啤酒。\n\n你該去試嚐一下那些穀物的味道，看有沒有哪個榖物的甜度夠資格交給老陳叔。", progress = nil, completion = "呃，看來這些穀物沒一個過關。老陳叔可是很挑的。\n\n或許榖物之王知道哪裡可以找到更加「特別」的貨。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30032] = {title = "追尋更好的大麥", objective = "到風之緣底部尋找麥芽洞穴大麥。", description = "甜美的穀物？我的父親曾經提到一種麥芽洞穴大麥，感覺正是你所要找的。\n\n如果你不怕危險，在南方的風之緣底部有一處古老洞穴。\n\n那裡還留有一座老舊的升降梯，是當初我父親為了進入叢林探險所搭建。\n\n洞穴裡頭的灌木林，擁有和我家族一樣悠久的歷史。在那片灌木林裡，你能找到一種甜美得讓你的感官都自慚形穢的穀物。\n\n不過你得提防那裡的守衛。", progress = "那座叢林聽起來讓人毛骨悚然。", completion = "這聞起來可就對了！", rewards = "絲綢大師緞質之索沐日腰帶皇澤鱗甲護腰泡泉光潔扣環金扇澤絲質之索平原隼腰帶野生原腰帶雷足重型束腰日歌裝甲束腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][30033] = {title = "鐵桿修行", objective = "取得並裝備受訓員的法刃和學徒的手搖扇。", description = "首先，你需要適合你天賦的兵器。到下面去，從兵器架上取一柄法刃和手搖扇來給我，讓我看看你拿武器的姿勢正不正確。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30034] = {title = "鐵桿修行", objective = "取得並裝備受訓員的弩。", description = "首先，你需要適合你天賦的兵器。到下面去，從兵器架上取一個弩來給我，讓我看看你拿武器的姿勢正不正確。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30035] = {title = "鐵桿修行", objective = "取得並裝備受訓員之錘和受訓員的祈禱書。", description = "首先，你需要適合你天賦的兵器。到下面去，從兵器架上取一柄釘錘和一本祈禱書來給我，讓我看看你拿武器的姿勢正不正確。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30036] = {title = "鐵桿修行", objective = "取得並裝備受訓員的匕首。", description = "首先，你需要適合你天賦的兵器。到下面去，從兵器架上取一對匕首來給我，讓我看看你拿武器的姿勢正不正確。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30037] = {title = "鐵桿修行", objective = "取得並裝備受訓員之斧和受訓員之盾。", description = "首先，你需要適合你天賦的兵器。到下面去，從兵器架上取一柄斧頭和一面盾來給我，讓我看看你拿武器的姿勢正不正確。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30038] = {title = "鐵桿修行", objective = "取得並裝備受訓員之斧和受訓員之盾。", description = "首先，你需要適合你天賦的兵器。到下面去，從兵器架上取一柄斧頭和一面盾來給我，讓我看看你拿武器的姿勢正不正確。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30045] = {title = "学海无涯", objective = "与尚喜师父交谈。", description = "初来乍到，你的第一个任务很简单：与尚喜师父交谈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30046] = {title = "老陳的決心", objective = "到四風峽的半丘找老陳‧風暴烈酒。", description = "你知道嗎？我沒必要承受這些。\n\n我會讓高叔叔看看什麼叫真正的釀酒人。我會用我以前未曾用過的原料，釀造出他從未品嘗過的完美啤酒。\n\n我是老陳‧風暴烈酒，也是當今世上最棒的釀酒人。", progress = nil, completion = "咱們來釀些啤酒吧。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30047] = {title = "老陳口味評鑑", objective = "向老陳‧風暴烈酒回報。", description = "老陳叔一定會愛死它的，或者…他會叫我們滾去找更甜的。他就是這麼個蠢傢伙。\n\n我們趕緊把穀物拿到半丘給他吧。", progress = nil, completion = "啊！這些麥芽穀物真是極品。你們兩個的眼睛和鼻子真不錯。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30048] = {title = "莉莉與穀粒", objective = "到四風峽的皇家糧倉找莉莉。", description = "我將會讓你參與我的釀酒計畫，<name>：我正計畫釀造一種濃烈的皇帝黑啤酒。只要釀造的好，它將會顏色深厚、味道濃烈，並且有著極高的酒精濃度。\n\n<老陳的眉頭皺了起來。>\n\n我突然想到…我完全不曾把我的計畫告訴莉莉過。這樣她不會知道該帶回哪一種穀物！\n\n你可以去跟她說嗎？我需要她把她所能找到最甜的麥穀帶回來。", progress = nil, completion = "&lt;name&gt;？你在這裡做什麼？\n\n陳叔叔需要甜麥穀？沒問題！讓我們開始試味吧。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30049] = {title = "扛不住水", objective = "到四風峽的金扇澤找泥杯。", description = "你介意去看看泥杯嗎？他可能需要一些幫忙才能把水運回來。\n\n有你這樣巨大強壯的<class>過去幫忙減輕肩頭重擔，他肯定會很感激的。", progress = nil, completion = "&lt;name&gt;！你是來幫忙的嗎？ 你這傢伙真是棒呆了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30050] = {title = "園丁弗蘭與灑水壺", objective = "聽從園丁弗蘭的指示並替她的60株蔬菜澆水。\n\n你可以在坐騎上執行這個動作。", description = "你要我就這麼「送」你一些啤酒花？呿！你已經是今天第三個沒頭沒腦地衝來跟我要食物的小<race>了！\n\n你要食物是嗎？那你就必須工作！\n\n<她把一個灑水壺交到你手上。>\n\n現在去幫我的植物澆水！", progress = nil, completion = "嗯嗯！\n\n澆得好。", rewards = "園丁鐮刀園丁魔杖弗蘭的長矛園丁之斧弗蘭的手斧弗蘭的弩園丁之錘弗蘭的黃金錘弗蘭的匕首弗蘭的青銅錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][30051] = {title = "探尋極致之水", objective = "帶領泥杯到金扇澤裡的池塘漩渦，並幫助他收集30份林地之水。\n\n如果你和泥杯走散了，你可以在金扇澤裡的巨大香蕉旁找到他。", description = "看哪，<name>：金扇澤。我聽過太多關於這裡優質好水的美談。當然也有不少壞的事情就是。\n\n老陳沒說他需要哪一種水，我們準備幾種樣本給他如何？\n\n來吧，快點出發。讓我們一起舀些水來。", progress = "風暴烈酒那傢伙說他是有史以來最棒的釀酒師。可能是真的，目前我也沒有其他的解答。", completion = "看看你，我的好鄰居！我們可真是收集了不少種類的水。有了這神奇的水，我確信老陳可以做出令人非常驚艷的啤酒。\n\n當然也可能是讓某人衝去茅坑蹲上一個月的啤酒。我猜我們只能走著瞧。", rewards = "眾樹之擁塵背披風黃褐毛皮斗篷泥杯的披風草生群披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][30052] = {title = "雜草戰爭", objective = "在凱藍的田地拔100株雜草。\n\n你可以在坐騎上執行這個動作。", description = "你想要些啤酒花是嗎？我後頭的小屋裡有很多。我很樂意分一些給你…如果你能幫我的庭院除草的話。\n\n別「花」呆了，快去吧！嘿嘿，「花」呆，你聽懂了嗎？", progress = nil, completion = "你除起草來就像個英雄。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30053] = {title = "探尋啤酒花", objective = "問問園丁弗蘭、凱藍，與登‧泥爪有沒有啤酒花。", description = "有莉莉處理穀物，泥杯搞定了水，我們現在只缺啤酒花，與一些製作精良的木桶。我會負責木桶…但我需要你去找來一些啤酒花。\n\n我不太了解這塊土地上的啤酒花，但我確信附近的農夫有一些值得釀造的東西。去看看你能湊到些甚麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30054] = {title = "受夠了", objective = "拿到100付兔妖的牙齒。", description = "兔妖，他們太會亂啃。\n\n他們啃了芒芒的胡蘿蔔。他們啃了芒芒的南瓜。芒芒試著趕走他們，而他們竟然啃掉芒芒的尾巴跟腳。\n\n我真的受夠了。\n\n你的戰鬥技巧比芒芒好太多。把他們該死的牙齒帶回來。然後我們來看看是誰啃誰。", progress = "把那些牙齒帶回來，說不定芒芒會給你一些啤酒花。", completion = "好多牙齒喔！芒芒可能會把它們黏在一起來做一個小耙子。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30055] = {title = "風暴烈酒的啤酒花", objective = "到半丘找老陳‧風暴烈酒。", description = "三名農夫都將啤酒花送到半丘來了。或許你該跟老陳確認一下他是不是收到了。", progress = nil, completion = "看看這些啤酒花！品質都非常好。\n\n我們開始有些進展了，&lt;name&gt;。很快的我們就能準備好所有材料並開始釀造。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30056] = {title = "農夫的女兒", objective = "找到米娜‧泥爪。", description = "勇敢的<class>，你來得正好。我女兒失蹤了！\n\n我懷疑兔妖把她擄到他們臭氣沖天的狹窄兔窩裡了。我的年紀老得無法與兔妖戰鬥，我的雇農們也因為整個早上與他們對抗而精疲力竭。\n\n你可以幫我去尋找她嗎？", progress = nil, completion = "不… 不… 滾開… 我不想…\n\n等等，你不是胡蘿蔔。你也不是兔妖。你是來這裡救我的？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30057] = {title = "看到橘色", objective = "帶米娜‧泥爪回到她父親身邊。", description = "那些兔妖…他們讓我做了非常非常恐怖又瘋狂的事情。全跟胡蘿蔔有關。我無法敘述他們到底朝我丟了多少胡蘿蔔。\n\n我們別浪費時間。把我帶離這裡！", progress = nil, completion = "這胡蘿蔔恐懼症是怎麼回事？我不能理解。", rewards = "絲綢大師緞質披肩沐日肩甲皇澤鱗甲肩甲泡泉光潔肩甲金扇澤絲質襯肩平原隼肩甲野生原肩甲雷足重型護肩日歌裝甲護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][30058] = {title = "摩沙拉！", objective = "引誘並擊敗摩沙拉。", description = "備受推崇的絲綢熟練工老楚似乎製造出了一個怪物。牠是長了翅膀的蠶絲死神。\n\n摩沙拉。\n\n你曾經和牠的同類打過照面。現在我們要請你幫忙對抗這個傢伙。\n\n<class>，請你冒險進入坑裡，設置誘餌，那隻野獸就會朝你靠近。\n\n我們的殺蛾鬥士將會在必要時援助你，不過他們很容易被絲線纏住，要是他們動彈不得，你也許得幫他們一把。", progress = nil, completion = "我們追求技藝和自身的完美。但在達到完美的路上會犯下許多錯誤。\n\n我確信明天會有更多錯誤產生。再次感謝你的幫助。", rewards = "日歌外衣雷足外衣野生原胸甲平原隼外衣泡泉外衣皇澤鱗甲外衣沐日外衣您能選擇下列奬勵中的一個：\n\n英雄的獎金\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30059] = {title = "蛾的逆襲", objective = "殺死6隻突變的絲生蛾和8隻小突變絲生蛾。", description = "哦…哦，太好了！一個<class>！能幫幫我嗎？\n\n我在進行提升絲綢產量的實驗時，無意間創造出一種邪惡的怪物。\n\n結果便是一場大規模的飛蛾暴亂。能請你發揮你的<class>之力，摧毀一些這種怪胎嗎？", progress = nil, completion = "看來實際上並不是真的有那麼多蛾。但至少，你幫我在真正的大大大麻煩來之前爭取了一些時間。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30063] = {title = "面具之後", objective = "收集8張疑惑面具。", description = "儘管煞看似無法阻止，實際上卻並非如此。\n\n他們的面具似乎是他們力量的來源。當煞和面具分離開來，他們的精華就消褪到他們自己的領域去。\n\n幫我帶回完整的面具，我想進一步研究它們。但千萬小心，我敢說煞不會輕易把面具拱手讓人。", progress = "請小心處理那些面具。如果你不小心，他們會嘗試吞噬你。", completion = "我想這些面具讓煞有辦法和我們的世界建立物質上的連結。\n\n我得進一步研究它們，這樣我們才能永遠驅逐這種生物。\n\n謝謝你，&lt;name&gt;。十分感謝你的協助。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30064] = {title = "挽救經典", objective = "收集6份遠古箴言。", description = "煞開始入侵時，我的專家被迫拋下他們的研究。\n\n不幸的是，他們將書本遺落在寺廟各處的地上。我們必須挽救這些無價的知識結晶!\n\n你可以在東北方的訓練場和老手之圈附近找到這些遠古箴言。", progress = "箴言的狀況如何?有損傷嗎?", completion = "謝謝你!看到這些文稿平安無事真讓人鬆一口氣。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30066] = {title = "隱藏的力量", objective = "將古老禱文送給6名玉龍守護者或玉龍大師。", description = "我們的寺廟守護者血戰了數個小時。他們肯定越來越疲憊了。\n\n我會給你一些禱文，請轉交給我們的戰士。\n\n別看它們只是幾張紙。這些古老的文稿上有著蘊含力量的真言。", progress = nil, completion = "煞的數量無窮無盡，我們的數量卻很稀少。但我們不會因為困境而氣餒。\n\n謝謝你盡了一份力來保衛我們的家園，&lt;race&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30067] = {title = "懷疑之影", objective = "擊敗懷疑之影。", description = "南方發生了一場激烈的煞之暴亂。\n\n它正在嘗試摧毀一樣古老的聖物，千語之鐘。\n\n在寺廟的歷史上，這鐘從未被人敲響過，因為傳說中，它是一件強大的古器。\n\n請你立刻擊敗這隻惡魔!我們必須拯救這樣神器!", progress = nil, completion = "你拯救我們免於令人不敢想像的可怖命運。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30069] = {title = "攻擊是最好的計畫", objective = "殺死6名卡爾洛夏蠻兵和6名卡爾洛夏零件潤滑工。", description = "軍情七處喜歡採取快速而安靜的行動。至少，在計畫中是這樣的。\n\n瑞爾‧夜風已經進入卡爾洛夏海岬尋找安杜因和泰勒的蹤影，但那裡的情勢越來越嚴峻，他需要有人支援。\n\n在那群狗種中殺出一條血路，找到瑞爾！", progress = nil, completion = "幹得好！如果你哪天決定放棄冒險生涯，軍情七處需要你的天賦…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30070] = {title = "加楚爾的末日", objective = "殺死加楚爾。", description = "好了，<小子/妹子>。我們已經受夠這個術士的大軍了…該是進行斬首行動的時候了。\n\n加楚爾就在那個又大又舊的寺廟廢墟裡。送他上路，讓部落沒辦法繼續在潘達利亞扎根。", progress = nil, completion = "煞…\n\n在異域海岸上和部落作戰已經夠麻煩了。", rewards = "和平破壞者皮甲頭盔和平破壞者鍊甲頭盔和平破壞者絲質風帽和平破壞者緞質兜帽和平破壞者皮頭盔和平破壞者環甲頭盔和平破壞者光潔頭罩和平破壞者裝甲頭盔和平破壞者重型頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][30072] = {title = "絲從何處來", objective = "取得桑葉、餵給5隻飢餓的幼蠶，並獲得生絲。", description = "你想成為一日絲綢大師嗎?\n\n首先你得有新鮮的桑葉。你可以去我們西北邊的桑葉林尋找。\n\n然後你必須把桑葉拿到西邊的養蠶洞餵給飢餓的幼蠶。\n\n最後你就可以在農場南邊的處理室裡獲得天然的蠶絲。\n\n玩得開心!", progress = "你找齊每樣東西了嗎?你有聽清楚每個步驟嗎?", completion = "這些樣本太棒了。我會確保它們被送去正確的地方。這份樣品就送給你吧。", rewards = "絲綢大師披巾絲綢大師披氅絲綢大師斗篷絲綢大師法術斗篷絲綢大師披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][30073] = {title = "「帝王」酒", objective = "站在老陳‧風暴烈酒旁邊協助他釀造。", description = "萬事俱備。該是開始釀造的時候了。\n\n專注精神，<name>…說不定你可以學到些什麼。", progress = "啤酒可不會過個三秒就自己釀好，<name>。就算你的名字叫老陳‧風暴烈酒。", completion = "謝謝你願意等那麼久。你的耐心就像你的勇氣一樣可敬。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30074] = {title = "登門拜訪", objective = "到風暴烈酒酒坊的入口找老陳‧風暴烈酒。", description = "現在，前往風暴烈酒酒坊的時候到了！能和其他的風暴烈酒族人重聚讓我很興奮…而又有甚麼比來幾杯啤酒更適合這個興奮的時刻呢？\n\n你知道酒坊在哪，對吧？順著這條路往西走就好。你不可能錯過的。當然，你想要的話也可以與我們同行。我們馬上就要出發了。", progress = nil, completion = "這門…被封起來了？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30075] = {title = "清道夫", objective = "宰了10隻爛醉猴人或搗蛋兔妖。", description = "你有看到嗎？兔妖，猴人以及水靈…全都從酒坊的門與窗戶傾巢而出！裡面到底發生了什麼事！？\n\n釀酒廠的東邊還有另一個入口。我去看看能不能搞清楚現況。在這同時，你試試能不能料理掉這些怪物。沒甚麼比喝醉的猴人更糟的了。", progress = nil, completion = "我對這酒坊的忍耐已經到了極限。我開始覺得我們應該直接轟掉外牆並開始清理這間房子。", rewards = "您能選擇下列奬勵中的一個：\n\n絲生蛾的翅膀平原隼的羽毛幸運兔腳虎鉗的甲殼黃褐色毛皮的鹿角\n\n您還會收到：\n\n絲生蛾的翅膀平原隼的羽毛幸運兔腳恆龍寶箱"}
MultiLanguageQuestData['tw'][30076] = {title = "最珍貴的水", objective = "取得3個水精精華。", description = "我聽過很多關於這釀酒廠的荒謬謠傳。我以為他們都在胡扯…直到我看到那巨大的猴人。\n\n所以，我不禁懷疑，萬一其他謠傳也是真的怎麼辦？我曾聽過水靈會在釀酒廠裡四處遊蕩，造成一些騷動什麼的。他們的身體貨真價實是「純水打造」的。\n\n這麼珍貴的水，應該能用來製造一些絕佳純釀。如果你有找到，可以帶一些給我嗎？", progress = "這會很令人興奮的。基本上還是釀造啤酒，只是我用的原料不是水，而是水靈的身體。", completion = "看起來就像一般的純水。很難相信這曾經是貨真價實、老天為證、活蹦亂跳的生物屍體。\n\n我等不及要把它變成啤酒喝掉它了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30077] = {title = "木桶耶，天啊!", objective = "釋放7個受困木桶的熊貓人。", description = "那隻大金剛一般的猴人真令人不可置信!他就這樣把木桶丟來丟去!\n\n木桶耶，天啊!\n\n看來他幾乎把在釀酒廠外工作的熊貓人全都抓了起來。如果我是你，我會試著幫他們解圍。你身上這些滑稽的肌肉也該派上用處了。\n\n我們的目標是釀酒廠東邊的後門。那兒見!", progress = nil, completion = "猴子們到底是有多愛木桶啊？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30078] = {title = "大掃除", objective = "擊敗艾迪、裘加，以及發泡黃色酒元素。", description = "夠了，<name>。我受夠這一切了。\n\n如果沒有人挺身而出來整頓這間釀酒廠，我們將永遠失去它。這裡有太多的家族歷史，還有啤酒，我們承擔不起它被摧毀的風險。\n\n所以…我們要從後門衝進去。你、莉莉、泥杯與我。\n\n這裡面將會發生一場激戰。\n\n當你準備好了告訴我。", progress = nil, completion = "看看四周。外面似乎寧靜多了。 這間釀酒廠需要的就是某個強壯的傢伙來整頓。\n\n我們得花上一些時間才能把這裡清乾淨，但我沒那麼介意。\n\n畢竟…這是我的家。", rewards = "絲綢大師緞質兜帽沐日頭盔皇澤鱗甲頭盔泡泉光潔頭罩金扇澤絲質風帽平原隼頭盔野生原頭盔雷足重型頭盔日歌裝甲頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][30079] = {title = "什麼侵蝕了祝家守望站？", objective = "在祝家守望站與當地居民談話，找出一個願意與你交談的人。", description = "熊貓人總是對旅行者大開雙臂…並大開酒桶！但這個城鎮卻充滿了混球！\n\n每個人都忙著擺臭臉，完全不跟肯‧肯說話！\n\n你能在這個鎮上找到一個人跟我們說話嗎？也許正常的熊貓人都躲在屋子裡？", progress = nil, completion = "只有一個熊貓小姐沒瘋嗎？這比肯‧肯想的還糟…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30080] = {title = "找出易謀", objective = "到祝家守望站的東北方某處找易謀‧長眉。", description = "我的姪子易謀一向有點消極。當絕望的波濤侵襲城鎮時，他受到的影響比任何人都強烈。他在那裡坐了好幾天，拒絕進食，兩眼發直地盯著地平線那端。\n\n現在他朝東北方的峭壁走去了，那裡是雷鳥築巢與狩獵的地區。\n\n拜託你，<class>，你可以去找他嗎？", progress = "易謀長嘆一聲。", completion = "讓我猜猜：我嬸嬸派你來的？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30081] = {title = "中藥秘方", objective = "從祝家界裡取得4大塊蜂巢、4條滑溜的泥鰍與4顆鹽之核。", description = "好吧，肯‧肯確定知道熊貓人出了什麼問題!有個非常古老的猴人療法可以搞定。\n\n需要混合蜂蜜、魚油和鹽。肯‧肯看到城鎮周圍的樹上有很多蜂窩，而乾掉的池塘裡一定有魚留在那兒。\n\n至於鹽嘛...小美可能知道要到哪裡去找一點鹽。", progress = "肯‧肯居然沒有早點想到，這可能會毀了他一整天的好心情...", completion = "熊貓人悶了一肚子便便!\n\n有時候便便會受驚嚇，不想出來。可憐的毛毛屁屁一定都快爆掉了!\n\n這東西最能讓便便出來。這樣一定能讓熊貓人開心!\n\n就像老奶奶常說的:痾不出的便便沒法丟!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30082] = {title = "易謀，開心點嘛!", objective = "把易謀‧長眉帶回祝家守望站。", description = "自從風暴開始後，我就覺得...很疲倦。\n\n不是身體上的...不是。比較像是內在的靈魂已經枯竭。人生變得毫無價值，毫無希望。我想妻子跟了一個頂著啤酒肚的傢伙跑了，就是這種感覺吧。但我沒結過婚，哪知道那是什麼感覺?\n\n我怎麼能聲稱自己無所不知?我對任何人而言都毫無價值，除了這些雷鳥。至少牠們可以從我身上飽餐一頓。\n\n<易謀深深一嘆，然後繼續凝視著天空。看來他哪裡也不想去。>", progress = nil, completion = "我不敢相信他真的打算這樣做...這次的絕望比我想像的還要嚴重。將他帶回來的恩情，我怎麼謝你都不夠。", rewards = "納耶里兜帽號角之息頭盔深野蠻荒頭盔納松頭罩安格寇風帽川刃頭盔薩鍾頭盔廓亞頭盔朵迦頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][30083] = {title = "保衛領地", objective = "在祝家守望站殺死10名野鱗薩烏洛克或野鱗草藥師。", description = "我們對領地的掌控變得薄弱，來自荒野的薩烏洛克也趁機推進到城鎮北邊的洞穴裡。\n\n我們的獵人大都在各自低首垂淚，讓薩烏洛克得以把這裡當成自家後院一樣地走進來，隨意搶走他們想要的任何東西！\n\n我要給他們送一條消息，讓他們明白祝家守望站不是好惹的。\n\n你願意擔任我的信差嗎？", progress = nil, completion = "謝謝你，&lt;name&gt;。這應該可以讓那些野蠻人學會安份守己。", rewards = "鬼煞墜盒絕望頸飾野鱗護符紅鶴墜飾失落王朝墜飾您會收到：\n\n"}
MultiLanguageQuestData['tw'][30084] = {title = "邊境", objective = "到祝家界的西南邊界，點亮祝的紀念聖火、琳的紀念聖火與波的紀念聖火。", description = "篝火可以阻止荒野外頭的野獸靠近，而且效果出奇的好。我們沿著西南邊的邊界擺放了三堆篝火，我們通常會讓它們一直保持燃燒狀態。\n\n然而，已經有好幾天沒人過去，那些火現在一定都熄了。過不了多久，這片蠻荒就會再次鯨吞蠶食我們保護了好幾世紀的土地。\n\n拜託你，把那些篝火重新點燃。它們是保護領地安全的關鍵，也是用以紀念我們創始人的方式。", progress = nil, completion = "謝謝你，&lt;name&gt;。\n\n祝家界是上通山谷下接海洋的通道。\n\n維護領地的安全需要日復一日的努力，才能維持住邊界，抵擋野蠻的喀撒朗蠻荒。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30085] = {title = "進入釀酒廠", objective = "到風暴烈酒酒坊找老陳‧風暴烈酒。", description = "我們必須弄清楚酒坊裡發生了什麼事，<name>!\n\n我們或許清掉了幾隻較大的害蟲，但我非常確定在他們出現的地方還有更多。集合你的朋友們，然後到裡面跟我碰頭!", progress = nil, completion = "你來了!非常好!\n\n我很期待再次與你並肩作戰，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30086] = {title = "搜尋隱居的宗師", objective = "聽聽曉跟他的夥伴在說些甚麼。", description = "喔，你好。你在找這地方的主人嗎？那就去找臺階最上面的那個熊貓人。我只是個訪客…就像你一樣。\n\n先失陪了，我正在和幾個朋友商量一些事情。我們等等再聊。", progress = nil, completion = "你剛剛是在偷聽嗎？別擔心，我不介意。歡迎你一起搜索隱居的宗師。\n\n不過，若是你找到了他，希望你能回來告訴我他在哪裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30087] = {title = "FLAG—功夫介绍", objective = "倾听晓和他同伴们的谈话。", description = "嘿，你好。你在寻找这片地方的主人吗？那就去见见楼梯上面的那位熊猫人吧。跟你一样，我也是访客。\n\n不好意思，我跟我朋友现在要商量点事情。我们稍后再聊。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30088] = {title = "何必這麼嚴肅呢？", objective = "在祝家界收集18個巨型豹齒和一罐顏料。", description = "好吧，這沒用。嗯...至少讓肯‧肯很開心!但熊貓人還是很傷心...\n\n我們試試另一種猴人療法。這一次，我們要回到比老奶奶的時候更早，到很古早很古早以前。猴人偶爾仍會做這種事...通常是在開派對的時候。\n\n肯‧肯有木工活兒要做，你把牙齒帶來給他!不是你的牙齒;要大牙齒，像是豹的牙齒!\n\n喔，還要一些顏料!小美可能知道要去哪裡找。", progress = "<肯‧肯忙著在樹皮上雕著什麼東西。>\n\n你等著看，這一定會很棒。", completion = "正好趕上!我完成了...你看!\n\n&lt;肯‧肯舉起一個木雕面具，面具有張滑稽的臉。&gt;\n\n現在只要完成最後一道手續，我們就有一台保證有趣的機器了!", rewards = "朵迦裹手廓亞裹手薩鍾裹手川刃裹手安格寇裹手納松裹手深野蠻荒手甲號角之息裹手納耶里裹手您會收到：\n\n"}
MultiLanguageQuestData['tw'][30089] = {title = "直接放在額頭上", objective = "在祝家守望站裡用肯‧肯的面具治癒8個沮喪的祝家守望站看守者。", description = "嗯…那可真是意料之外啊！\n\n仔細想想，現在肯‧肯記起猴人最開始為什麼要用面具了…\n\n傳說名叫紹昊的老熊貓皇帝，因為太悲傷而無法領導他的人民，有一個美猴王用面具治癒了他。然後他們把面具與老皇帝的悲傷全都埋到地底下。\n\n我們應該把這個面具用在更多熊貓人身上，但不要把悲傷埋到地下，我們該把它當沙包痛打一頓。\n\n<name>，我們開始吧！", progress = nil, completion = "我們救了熊貓人，但這塊土地還是很悲傷…你看，雨一直不停地下！\n\n&lt;肯‧肯對天空揮舞著他的小拳頭。\n\n我們還得揍多少屁股才能把城鎮恢復原狀？！\n\n&lt;天空以更加陰鬱的天色作為答覆。&gt;", rewards = "納耶里護腿號角之息腿甲深野蠻荒腿甲納松腿鎧安格寇長褲川刃腿甲薩鍾護腿廓亞腿甲朵迦尼腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][30090] = {title = "祝的絕望", objective = "在祝家守望站去除易謀‧長眉身上煞的絕望能量。", description = "嗯嗯...在那兒的是易謀那小鬼嗎？\n\n<肯‧肯斜睨越來越劇烈的滂沱大雨。>\n\n真的是他！他就在井邊，而且他看起來不怎麼好。\n\n肯‧肯有不好的感覺...", progress = nil, completion = "我們今天做得很好，&lt;name&gt;。\n\n僧院總是告訴我們要讓我們經過的地方變得更好。", rewards = "您能選擇下列奬勵中的一個：\n\n肯‧肯的面具\n\n您還會收到：\n\n肯‧肯的面具恆龍寶箱"}
MultiLanguageQuestData['tw'][30091] = {title = "潘達利亞之淚", objective = "在祝家界殺死12隻哭泣的恐獸。", description = "所有的一切都從我們的池塘而起。一天之內，所有的水流進地底下。當池中的水完全乾涸時，水就開始從天空落下來。\n\n儘管傾盆大雨永無止境地從天空落下，池塘卻沒有注滿。大地如同火燒般乾渴，無法冷卻下來。\n\n現在，從池塘中誕生出一種可怕的絕望形體:由天上之水和大地之鹽混合而成的元素。這是潘達利亞之淚。", progress = nil, completion = "謝謝你，&lt;class&gt;。\n\n是讓我們的土地從詛咒中解放的時候了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30092] = {title = "吉爾尼斯的暗樁", objective = "前往吉爾尼斯首都的廢墟外找出薩索‧閃指。", description = "若你想加入我的理想，殺掉躲藏的黑龍，那便解決悉拉姆‧教條領主來證明你自己吧。他正在吉爾尼斯召集軍隊。\n\n我們還無法躲過防衛者的耳目順利潛入，但是我們布了一個暗樁監視著他。薩索‧閃指這位足智多謀的秘法師正在吉爾尼斯首都的廢墟外等著我們與他接洽。\n\n去找他，他會告訴你悉拉姆在哪裡。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30093] = {title = "刺殺悉拉姆", objective = "潛入吉爾尼斯城廢墟，殺掉軍事區裡的悉拉姆‧教條。", description = "城裡好幾天都是一團亂。悉拉姆‧教條假扮成吉爾尼斯人，用他的嚴酷之血感染大部分的吉爾尼斯人，就連被遺忘者也拿他沒輒。\n\n看來只能派專人去除掉他了!\n\n我後頭的那座橋戒備比較鬆散，你從商業廣場溜進去，往南走 - 教條就在軍事區的中央。\n\n我會看著你，當你有危險時救你出來。\n\n...肯定會有危險的!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30094] = {title = "終焉之刻", objective = "在終焉之刻與諾茲多姆說話。", description = "青銅龍諾茲多姆尋求部落勇士的幫助，你在他的候選人名單之中。我還能再跟你分享一些細節。\n\n我的主人向來不會要求凡人的協助，但我想事情總是會隨著時間而變…就算是時間之王也不例外。\n\n他正在遙遠的未來，終焉之刻等著你。你願意的話，我可以送你到那裡去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30095] = {title = "終焉之刻", objective = "在終焉之刻與諾茲多姆說話。", description = "青銅龍諾茲多姆尋求聯盟勇士的幫助，你在他的候選人名單之中。我還能再跟你分享一些細節。\n\n我的主人向來不會要求凡人的協助，但我想事情總是會隨著時間而變…就算是時間之王也不例外。\n\n他正在遙遠的未來，終焉之刻等著你。你願意的話，我可以送你到那裡去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30096] = {title = "姆多茲諾", objective = "殺掉姆多茲諾。", description = "我們得借助巨龍之魂的力量才能殺掉死亡之翼。為了取得巨龍之魂，我得帶你回到一萬年前的大崩裂發生前...但是那條時光隧道被封住了。\n\n封住時光隧道的怪物名叫姆多茲諾，在這個扭曲的未來他必須得死，如此我們才能順利除掉死亡之翼。\n\n<name>，這就是你被帶到這裡的原因。", progress = nil, completion = "姆多茲諾死了，時間之道又再度開啟。", rewards = "青銅衝擊槍岔路長靴時光扭曲者護手命運風帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][30097] = {title = "保留檔案的用途", objective = "殺掉終焉之刻裡的兩個回音，然後讓阿勒米的容器記錄他們的資訊。", description = "就我所知，你意圖避免這段未來。若真是如此，那麼我們一定得在失去這段時間線之前記下關於它的資料。\n\n我們相信在龍殿中迴盪的強烈「回音」是這段未來最有趣與珍貴的部分。\n\n當你去中止這些回音時帶著這個容器，他們的一部份能量會被儲存在青銅龍軍團的保管箱。", progress = "諾茲多姆倉卒行動，他平常是不會這樣的。\n\n正常情況下，我會保留所有的檔案，然而鑒於當下的情勢，我們得挑選記錄的對象... 以及雇用像你這樣的傭兵來幫助我們。", completion = "&lt;阿勒米取走你身上的容器。&gt;\n\n這些東西接下來就由我保管。當然，我得妥善標誌、記錄並儲存它們。", rewards = "古卷管理者手套月牙魔杖時光繩帶護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][30098] = {title = "永恆之井", objective = "與永恆之井的諾茲多姆談話。", description = "在恆龍密探的餘黨阻擾我們之前，我們得趕快行動。時間寶貴。\n\n我現在得將你從遙遠的未來送回遙遠的過去...也就是先祖之戰發生的年代。我們的目的是要拿到巨龍之魂，一個擁有巨大力量的文物... 足以殲滅死亡之翼，終結他的統治。", progress = nil, completion = "進行下一步。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30099] = {title = "無盡之數", objective = "關閉三個惡魔的傳送門，然後殺掉佩洛薩恩。", description = "巨龍之魂由一支惡魔軍團守衛著，要接近巨龍之魂就得先除掉他們。\n\n如果我時間抓得夠準 - 通常是如此 - 一個名叫伊利丹‧怒風的年輕夜精靈馬上會經過這裡，他一定能幫上一點忙。\n\n幫助伊利丹關閉惡魔的傳送門，然後殺掉那個惡魔首領，佩洛薩恩。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30100] = {title = "自負者", objective = "解決艾薩拉女王。", description = "艾薩拉女王與她的皇家守衛擋在我們眼前，我們不能讓任何人干擾我們的計畫。因此在她找到機會攪局之前，我們得向她開戰。\n\n你今天殺死艾薩拉的機率微乎其微，因為那條分支上連結的時間軸非常少。你只要能吸引她的注意就算是成功了，不過，只要吸引一下下的注意就好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30101] = {title = "通往巨龍之魂的道路", objective = "殺掉瑪諾洛斯。", description = "我不可能就這樣飛上去拿走巨龍之魂，有上古之神在保護它。\n\n況且，他們的防護因為漩渦、永恆之井散發的秘法能量，以及大魔王瑪諾洛斯所聚集的能量而變得更強。\n\n只要擾亂瑪諾洛斯，便能中斷巨龍之魂與永恆之井之間的連結。少了永恆之井的力量， 上古之神的結界就會減弱，到時便可以接近巨龍之魂。\n\n然後，它就是我們的了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "鐵羽長弓狩魔獵人腰帶惡魔之顱險路長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][30102] = {title = "暮光之時", objective = "與暮光之時的索爾說話。", description = "我們不需要一直在這兒一籌莫展。你忘了嗎？我們能控制時間！特別是你已經在未來擺脫了姆多茲諾。\n\n你剛釋放的巨龍之魂嗎？現在的索爾已經拿到它了，他需要你的幫助。\n\n準備好出發了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30103] = {title = "前往龍眠神殿!", objective = "護送索爾安全抵達龍眠神殿。", description = "巨龍之魂...力量足以除掉死亡之翼的武器。因為你的幫忙，現在它安然地在我們手裡。\n\n來吧!守護巨龍正等著我們。我們得將巨龍之魂帶到龍骨荒野中央的龍眠神殿。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "安全守護手套世界薩滿腰帶忠誠夥伴指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][30104] = {title = "記錄時間之道", objective = "殺掉一個軍團惡魔、一個皇家女僕與瓦羅森隊長，然後讓阿勒米的容器記錄他們的資訊。", description = "你是…<name>嗎？你之前幫我們保留過去的檔案，雖然嚴格來說，那是未來的檔案，嗯，總之我想你知道我在說什麼，時間總是相對的。\n\n我需要更多的檔案，雖然你和諾茲多姆不想再像終焉之刻那樣修改時間軸，但檔案這種東西愈多愈好。\n\n我要瓦羅森隊長的檔案，還有艾薩拉某位美麗的小女僕的檔案，還有…嗯…喔，樓下那個高大的惡魔守衛的檔案，好嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "阿勒米之戒往昔足靴撰史者的護胸歷史學家護腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][30105] = {title = "暮光預言者", objective = "找到並讓暮光預言者現出真面目。", description = "書信裡頭寫著:\n\n「暮光之時降臨。大薩滿索爾手裡拿著巨龍之魂來到龍眠神殿，低聲嗚咽著說要殺了我們偉大的主人。」\n\n「阻止索爾，我們便贏得這場戰役。我會在一旁看著你。」\n\n   ～ 暮光預言者您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "痛苦糾結魔杖索爾的感激之情暮光預言者徽記您會收到：\n\n"}
MultiLanguageQuestData['tw'][30106] = {title = "大功告成", objective = "前往希爾斯布萊德丘陵的拉文霍德莊園，向怒西昂王子報告你已順利完成任務。", description = "怒西昂王子知道你順利完成任務會很高興的，你應該到拉文霍德莊園向他回報。\n\n大家都知道，王子對恩人向來是非常大方的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恐懼復仇"}
MultiLanguageQuestData['tw'][30107] = {title = "收集源質寶石簇", objective = "在巨龍之魂團隊副本中，從怪物身上拾取源質寶石簇，收集333個暗影寶石。", description = "我給你的兩柄匕首目前只是沒有生命的空殼，一旦把我已預想好的能量灌注進去，它們將會成為神兵利器。\n\n我需要你幫我拿到暗影寶石。這種稀有寶石的切面就像眺望永恆之處的窗口。暮光之錘的爪牙常用這些寶石來控制最強大的元素。\n\n龍眠神殿外正有一場激烈的戰爭，從死亡之翼的爪牙身上收集源質寶石簇，然後帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30108] = {title = "卡拉贊的眼線", objective = "前往卡拉贊東南方的廢墟，向薩索‧閃指回報。", description = "你的下一個目標是納麗絲，她在卡拉贊荒廢的高塔之下作威作福。\n\n你的首要任務是殺掉她。如果你能帶一瓶她的鮮血回來給我，我就能用來強化我之前給你的匕首。\n\n你的夥伴薩索已經被派到那裡，正等你過去。他會告訴你更多詳情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30109] = {title = "叛徒的鮮血", objective = "潛入卡拉贊外廢墟底下的塔主地窖，擊敗納麗絲，取回一瓶黑龍血。", description = "我已經查到納麗絲就在塔主地窖裡，也就是前方廢墟的廣大地下室。\n\n這裡到處都是龍的教徒，納麗絲在這一區設下奇怪的秘法儲存裝置。也許你可以利用那些東西來做點什麼？\n\n偷偷溜過教徒的身邊，殺掉納麗絲，裝一瓶她的鮮血帶給怒西昂。\n\n我會在一旁看著你，在你有麻煩時救你出來。但是我不會跟你進到裡面去！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30110] = {title = "LFGDungeons - Cataclysm - Raid Finder - 1st", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30111] = {title = "LFGDungeons - Cataclysm - Raid Finder - Nth", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30112] = {title = "有待解決的宿怨", objective = "黑暗遊俠瑪拉要你進入俄特加德要塞並殺掉凱雷希斯親王。", description = "俄特加德的部落軍團在天譴軍的煞婪大使凱雷希斯親王的指揮下增員。\n\n我們不能再讓維酷的讒言奏效了，讓他永遠閉上嘴巴。", progress = nil, completion = "復仇的感覺真好。儘管把這當作是真正復仇的開胃菜吧。\n\n阿薩斯將很快得到報應。", rewards = "煞婪裹帶仇殺束腕符文使護腕報復使者護臂您會收到：\n\n"}
MultiLanguageQuestData['tw'][30113] = {title = "深淵的勝利", objective = "帶著保存良好的龍血以及懼怕與復仇雙匕首，回去希爾斯布萊德丘陵的拉文霍德莊園找怒西昂。", description = "<薩索對血瓶施展魔法，然後迅速遞還給你，好像瓶子有毒一般。>\n\n完成了!盡快將這個瓶子還有雙匕首交給怒西昂。\n\n我不知道他打算拿這個血瓶做什麼。這件事我只跟你說啊，有時候那個龍小子還真讓我毛骨悚然。祝你好運!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n沉睡者夢旅者"}
MultiLanguageQuestData['tw'][30116] = {title = "做好萬全準備", objective = "在巨龍之魂團隊副本中，從怪物身上收集60個源質寶石簇。", description = "你知道為什麼我要你刺殺龍群，卻饒那些人一命嗎?因為那不是他們的錯，他們得追尋自己的命運，擺脫龍族的干預。\n\n任務已經接近尾聲，你也該去追尋自己的命運了。我可以繼續強化你的武器，但是光靠收集暗影寶石是不夠的，我需要整簇寶石。到我父親的爪牙那裡收集這些東西...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30117] = {title = "石犁村", objective = "將一桶「帝王」送去四風峽的石犁村給輪眉。", description = "不好意思…<name>？我沒聽錯你的名字吧？\n\n我來自西邊的石犁村。他們派我來領些緊急啤酒配給，但風暴烈酒酒坊整個封起來了！\n\n你那個帥朋友…不，不是泥杯，是另外一個。他似乎帶有幾個酒桶。你們能否分出一桶解決鎮子的急需呢？", progress = "歡迎，<class>。", completion = "終於!艾米成功了。\n\n希望風暴烈酒酒坊一切都好。我的人沒有啤酒可就廢了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30118] = {title = "弒父", objective = "消滅死亡之翼，並拿一塊他的下巴回來。", description = "我之前派去的刺客都死在你的下一個目標手中，我要你殺掉我的父親。\n\n你得殺掉死亡之翼。\n\n我們沒有時間了。他的瘋狂腐化了我的族人，若不阻止他，他將用黑暗吞噬這個世界。\n\n若你奇蹟般得勝，並帶一片他的東西回來 - 也許是一塊他用來掩飾混亂本質的盔甲 - 我將給你豐厚的回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戈拉德，巨龍之暮提洛許，世紀夢魘"}
MultiLanguageQuestData['tw'][30119] = {title = "Well of Eternity RP Tracker", objective = "去火焰之地夺回诺达希尔的分枝。我有责任对你的发现进行调查，<race>，这也就意味着我的任务现在只能交给你了。\n\n一股远非天然生成的强大魔力将我引来此地，我这才发现事态大为不妙。\n\n有人将诺达希尔的一根树枝折了下来，带到了火焰之地的深处。在那里，敌人正利用它进行邪恶的仪式，以腐蚀诺达希尔，试图用大火烧毁它。\n\n你必须想办法干扰仪式，将世界之树的树枝夺回来。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "我有责任对你的发现进行调查，<race>，这也就意味着我的任务现在只能交给你了。\n\n一股远非天然生成的强大魔力将我引来此地，我这才发现事态大为不妙。\n\n有人将诺达希尔的一根树枝折了下来，带到了火焰之地的深处。在那里，敌人正利用它进行邪恶的仪式，以腐蚀诺达希尔，试图用大火烧毁它。\n\n你必须想办法干扰仪式，将世界之树的树枝夺回来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30120] = {title = "淨化德拉克薩隆", objective = "德拉庫魯需要你在德拉克薩隆的火盆上使用德拉庫魯的藥劑。你需要五個耐久魔精才能使用德拉庫魯的藥劑。\n\n已提供物品：\n", description = "嘿，老兄，你來了!幹得好，老兄!\n\n德拉克薩隆很快就會從邪惡的不死生物中淨化，回復到原本高貴的樣子。為了報答你的幫助，要塞裡面最珍貴的寶藏就是你的了，老兄!\n\n爬到塔頂之後，你必須最後一次召喚我過去，我將完成儀式。\n\n哎呀，召喚我照例需要一些材料。從要塞的倖存者身上收集一些魔精吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "誘人脛甲引誘者護肩黑暗低語鐐銬誘惑綸巾您會收到：\n\n"}
MultiLanguageQuestData['tw'][30121] = {title = "尋找小隊", objective = "到喀撒利廢墟去搜尋恰星‧曦逐者。", description = "我派了一個外交官到東邊的廢墟尋找盟友。\n\n我的外交官還沒回來，而康恩剛告訴我那裡到處都是一種窮凶極惡的魔古。\n\n恰星是我的朋友，更是麗紗的兄弟。失去兄弟的打擊會讓她陷入絕望。她的熱病已經夠她擔心的了。\n\n你能不能去東邊的廢墟調查看看發生了什麼事？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30122] = {title = "銀絲藥劑", objective = "將瓶子裝滿強力的鍊金溶液。", description = "你發現一個用華美金線裝飾的漂亮銀水壺。藉由正確的材料和鍊金技術，它可以變得很有魔力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鍊金師精煉藥劑"}
MultiLanguageQuestData['tw'][30123] = {title = "誘捕者燉肉", objective = "取得5個完整的誘捕者腺體。", description = "麗紗得了熱疫。一個懷孕的媽媽不該染上熱疫。\n\n藤杖媽媽曾告訴我，幾乎所有疾病都可以用誘捕者燉肉來治療。讓我們來驗證一下這項知識是否正確。\n\n當我去採集所需的草藥時，你幫我取一些完整的誘捕者腺體回來，我會把它們料理一番。", progress = "就連叢林的空氣都瀰漫著危險的氣息。", completion = "太完美了！誘捕者燉肉的療效真是無與倫比。\n\n來，收下吧。這是藤杖媽媽的紀念品。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30124] = {title = "斷其眼目!", objective = "殺死達納蘇斯先遣騎。", description = "這些日行者是群煩人的傢伙。我需要的是胸中有點血氣和榮譽的部落士兵。不是什麼日靈和平主義爛貨。\n\n聯盟的傢伙也在這兒，$p。想當然是跟著我們，或跟隨麗紗那種幻象來的。這不重要。我不想讓他們知道我們現在有多麼分散。到南邊去，在他們斥候回報之前殺了他們。\n\n願地獄吼的雙眼看顧你。", progress = nil, completion = "做得好，&lt;name&gt;。你完美地執行了任務，並為我們爭取到更多時間來加強防禦。現在我只需要讓戴斯可繼續進攻就行了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30127] = {title = "來自朵迦的威脅", objective = "殺死6名朵迦回收者與8名朵迦勘測員，和4名朵迦執行者。", description = "魔古？他們似乎跟精靈差不多，古老又喜歡講派頭。不論早晚，艾澤拉斯的居民會了解到，部落不是來這地方「拜訪」的。我們來到這裡，我們要留在這裡。\n\n給他們一點教訓。到南邊和西邊的廢墟去削減他們的數量。在他們決定進攻前擊潰他們的大軍。\n\n試著了解這種生物是怎麼戰鬥的，還有怎麼死的。", progress = nil, completion = "這不是單純的盜匪威脅，這是一群為了同樣的目標而聚集在一起的古老種族。記住我的話，這塊土地上很快便會燃起戰火。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30128] = {title = "青春之池", objective = "從青春之池中取回水。", description = "魔古找到青春之池了!\n\n藤杖媽媽總是告訴我關於這東西的故事。在魔古帝國時期，他們用這種池水來延長壽命。\n\n不知怎麼，這些故事從來都沒好結局。就好像那水被詛咒了似的。\n\n無論如何，我們應該調查一下。這種水很有可能幫得上麗紗。\n\n青春之池似乎就在廢墟的西北邊。", progress = "麗紗承受著巨大的痛苦，需要比我更強大的力量才能拯救她與寶寶。", completion = "到這地步我願意嘗試任何東西。這土地即將奪走我的妻子和未出生的孩子。任何幫助我都需要。", rewards = "瀉湖披氅瀑布披氅天棚披氅綠背斗篷宜人披氅您會收到：\n\n瀉湖披氅瀑布披氅天棚披氅恆龍寶箱"}
MultiLanguageQuestData['tw'][30129] = {title = "魔古會議記錄", objective = "取回朵迦之序。", description = "魔古不常這樣大批聚集。我們必須弄清楚他們想幹什麼。\n\n我好像聽到某個傢伙在廢墟中央發號施令。我們該去看看他手上有什麼情報。", progress = "顯然魔古曾建立帝國，征服了他們遇到的每一個種族。\n\n這些魔古似乎熱切地想要恢復往日榮光。", completion = "等等，這文件提到青春之池！\n\n這池子真的存在？！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30130] = {title = "草本療法", objective = "找到20片帝國蓮花葉。", description = "康恩的藥方沒效。\n\n某些東西在暗中運作著。一股來自土壤底下的力量。它在吸取我們的希望，用絕望和失落來打擊我們。\n\n康恩告訴我這土地上有種蓮花。我或許能用來泡出一種讓麗紗恢復氣力的茶。\n\n拜託，到南邊和西邊的廢墟尋找蓮花葉。我會報答你的。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n蓮花水\n\n您還會收到：\n\n蓮花水恆龍寶箱"}
MultiLanguageQuestData['tw'][30131] = {title = "新生命", objective = "與聖光行者戴斯可談話，等待新生兒誕生。", description = "我的孩子要誕生了。我必須儘可能幫忙。\n\n請留在附近，英雄。如果我的妻子與孩子能活下來，我希望他們能見見救命恩人。", progress = nil, completion = "她...她死了。即便用上聖光賜予我的所有力量，我還是救不了她。\n\n不過還是謝謝你的協助...我們救了我的孩子。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30132] = {title = "往西前進", objective = "到紅鶴寺附近找日行者斥候。", description = "如今麗紗去到這塊異鄉土地上的祖先身邊了，我必須把眼光放在活著的人身上。\n\n柯爾帶領我們的一隊斥候，往西深入叢林。\n\n我派了一名斥候去調查紅鶴寺。拜託你，$p，去尋找我的斥候，取得他們的報告，然後與柯爾會合並儘可能地給予他所需的協助。\n\n我們會儘快加入你們。", progress = "戰爭。到最後總是戰爭。", completion = "&lt;name&gt;！來得正好！\n\n我們埋伏在廢墟西邊準備伏擊聯盟時，卻遭到魔古的埋伏攻擊。他們利用魔法傳送門呼叫援軍。", rewards = "刺藤墜盒刺藤頸飾刺藤項鍊刺藤墜飾刺藤護符您會收到：\n\n刺藤墜盒刺藤頸飾刺藤項鍊恆龍寶箱"}
MultiLanguageQuestData['tw'][30133] = {title = "深入蠻荒", objective = "在朵迦河北部找到失蹤的祝家守望站信差，然後繼續前往紅鶴寺與可羅‧霧行者交談。", description = "在蠻荒深處，喀撒朗河位於南方海岸的出海口一帶，坐落著紅鶴寺。寺裡住有赤吉與他最虔誠的信徒。\n\n他們應該已知悉這裡所發生的事了。\n\n如果你往那裡去，我想請你幫個忙。我們常常會送補給品到那座寺廟去，但我們最後派去的那名信差並沒有回來。請你在旅途中尋找他的蹤跡。他應該是在朵迦河前的分叉路上往北走。抵達紅鶴寺之後，去找可羅‧霧行者。", progress = nil, completion = "我明白了…煞已經滲透到領地那邊了，是不是？\n\n嗯，我真的很不想讓你失望，但這座寺廟裡也有煞在肆虐。我們當中還沒殺死或被…占據之類的人，都已經逃命去了。\n\n如果你在祝家守望站打敗過煞，我必須乞求你在這裡幫我們解決他們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30134] = {title = "野東西", objective = "到翠玉林的嘯風島找講師老佟。", description = "歡迎來到雲蛟衛，<race>。我可以從你眼中閃爍的火花看出，你想要加入雲蛟衛。\n\n讓我好好看看你。\n\n<安麗長老托著你的頭，凝望著你的臉。>\n\n唔。我看見你擁有一顆誠實和正直的心。你走了很遠的路來到這裡，但我恐怕你還得繼續跋涉。\n\n你加入雲蛟衛的道路從這裡開始。\n\n到東北方的嘯風島找講師老佟，踏出你的第一步。", progress = nil, completion = "感謝老天，他們終於派人來了！\n\n情況已經失控了！", rewards = "這個任務線能解鎖：\n\n每日任務：雲蛟衛\n\n您還會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30135] = {title = "絕處逢生", objective = "殺死8名滑鱗撕裂者或滑鱗飲蛋者。", description = "剛開始，滑鱗還很害怕接近野生蛟龍。\n\n接著，我抓到他們在夜色掩護下偷走蛟龍的蛋。\n\n現在，他們對成年蛟龍與幼蛟一視同仁地屠殺!\n\n如果我們不採取行動，這種溫和的生物將整個滅絕。這樣也就沒有雲蛟衛可以參加了!\n\n去殺掉那些惡劣的滑鱗，然後我們再談。", progress = nil, completion = "喔，謝謝你，&lt;race&gt;。\n\n我試過盡力阻止滑鱗，但終究敵不過他們的數量。\n\n你今天所做的事對於保存這個世代的雲蛟大有幫助。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30136] = {title = "空巢", objective = "繫住並送6隻嘯風蛟寶寶回巢。", description = "攻擊開始時，年輕的蛟寶寶因恐懼四散奔逃。\n\n現在牠們在島上四處漫遊，迷惘而恐懼。\n\n如果你想要幫忙，用這繩索繫住住這些迷路的小寶寶。送牠們回巢裡。送牠們回家。", progress = nil, completion = "別擔心，蛟寶寶在他們的巢裡很安全。\n\n有你在這裡，我的感謝真是無以復加。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30137] = {title = "收集蛋蛋", objective = "收集6顆蛟龍蛋。", description = "啊啊，我早該知道的！你看起來就是個飢渴的新人。\n\n我很樂意幫你挑選蛟蛋。然而，滑鱗已將蛟的巢掠奪一空。\n\n我感到非常抱歉。我不知道該說什麼。\n\n除非你瘋狂到潛入西邊的薩烏洛克營地，並帶回一些被偷走的蛟龍蛋，否則我恐怕沒辦法幫你。", progress = "薩烏洛克把偷來的蛟龍蛋保存在他們的營地裡。", completion = "喔，太棒了！\n\n這些蛋看起來…呃…它們看起來偏小了一點。你確定找不到更好的了嗎？\n\n喔算了，我想在當前這種情況下，我們不能太挑。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30138] = {title = "選蛋", objective = "到翠玉林的嘯風島找講師老佟。", description = "我檢驗了每一顆蛋，<name>。從你給我的那批裡，我選出三顆最有潛力的。\n\n你只能選擇一顆帶走。準備好下最終決定了嗎？", progress = nil, completion = "你只能選擇一顆蛋帶走。\n\n千萬小心。選了就不能改變。", rewards = "您能選擇下列奬勵中的一個：\n\n青蛟蛋綠蛟蛋黃蛟蛋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30139] = {title = "新騎兵日記", objective = "到翠玉林的落英園找講師天刺。", description = "太棒了，真是太棒了！我會把其他的蛋平安送回巢裡。\n\n與此同時，將你的蛋送去落英園給講師天刺。", progress = "野生雲蛟和自然之間有著微妙的平衡。他們數量稀少的蛋面對敵人時非常脆弱。", completion = "啊是的，安麗長老提過有個新弟子加入了我們。看來你已經選擇了你的雲蛟蛋。\n\n我會好好指引你。先讓我看看它。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30140] = {title = "新騎兵日記", objective = "到翠玉林的落英園找講師天刺。", description = "太棒了，真是太棒了！我會把其他的蛋平安送回巢裡。\n\n與此同時，將你的蛋送去落英園給講師天刺。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30141] = {title = "新騎兵日記", objective = "到翠玉林的落英園找講師天刺。", description = "太棒了，真是太棒了！我會把其他的蛋平安送回巢裡。\n\n與此同時，將你的蛋送去落英園給講師天刺。", progress = "野生雲蛟和自然之間有著微妙的平衡。他們數量稀少的蛋面對敵人時非常脆弱。", completion = "啊是的，安麗長老提過有個新弟子加入了我們。看來你已經選擇了你的雲蛟蛋。\n\n我會好好指引你。先讓我看看它。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30142] = {title = "那是…！", objective = "看著你的蛋孵化。", description = "喔我的天！這顆蛋隨時都會孵出來！\n\n好吧，看來這個小傢伙急著想見見你。\n\n你準備好了嗎？", progress = nil, completion = "恭喜！是屬於你的漂亮蛟寶寶。\n\n請好好照顧它，&lt;name&gt;。", rewards = "這個任務線能解鎖：\n\n每日任務：雲蛟衛\n\n您還會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30143] = {title = "雜草般的生命力。", objective = "到落英園找講師風刃。", description = "啊啊，又是你，<name>。\n\n講師風刃正在找你。你可以在東邊的山脊找到她。\n\n她有關於你的雲蛟的消息。", progress = nil, completion = "恭喜，&lt;name&gt;。\n\n看到你的努力開花結果讓人十分喜悅。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30144] = {title = "飛行訓練:穿越雲環", objective = "乘著你的雲蛟穿越6朵雲環。", description = "你的蛟龍已完全長成，這也代表你準備好開始飛行訓練。\n\n和其他初學者一樣，你必須從頭開始。\n\n你的第一項任務很簡單。到東邊的尖柱地帶，穿越6朵雲環。", progress = "你的初次飛行體驗如何？", completion = "你在這堂課裡學到什麼？\n\n速度。速度就是一切。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30145] = {title = "飛行訓練:全速前進", objective = "跟隨講師風刃。", description = "下一項任務將稍微困難一些。\n\n你準備好了嗎？", progress = nil, completion = "你做得比我想像中好。以受訓員來講還不錯。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30146] = {title = "點心時間", objective = "在潘達利亞的鹹水池或淡水池中釣得10條蜜糖小鯉。", description = "雲蛟很愛吃。牠們最喜歡的一種大餐就是蜜糖小鯉。\n\n在潘達利亞上，不論是鹹水還是淡水，都可以找到這些魚的蹤影。我相信你有些抓魚的技巧，而且有自己的釣竿吧? \n\n帶些新鮮的蜜糖小鯉回來給我，附近那些飢腸轆轆的雲蛟肯定會很感激你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30147] = {title = "過去的片段", objective = "拜訪潘達利亞各處的考古挖掘場，並使用勘察技能取得6個蛟龍騎士聖物。", description = "雲蛟衛的歷史可追溯到數千年前，儘管我們試著保存傳統，但還是有許多古老技藝隨著時間流失。\n\n你可以藉由搜索潘達利亞的考古挖掘場來收集歷史的線索，從而幫我們取回一些古老的知識。\n\n使用你的考古學技能來調查潘達利亞各處，並將你找到的東西全帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30148] = {title = "只是小傷", objective = "在嘯風島使用風絨繃帶或厚風絨繃帶來治療8隻受傷的蛟寶寶。繃帶可由裁縫製作或自拍賣場購得。", description = "嘯風島上的許多蛟寶寶因為之前的幾次戰鬥受傷了。\n\n我聽說你可能知道該怎麼幫助牠們。\n\n請到東北方去，用品質最好的繃帶解救受傷的蛟寶寶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30149] = {title = "感官饗宴", objective = "收集5份魚肉餅。", description = "我聽說你懂得一點烹飪技巧。\n\n主要是，蛟龍非常喜歡吃魚肉餅。\n\n如果你運用你的烹飪技巧，為我帶來5份這種餐點，附近的雲蛟將會非常的高興。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30150] = {title = "甜如蜜", objective = "從落英園的生氣的蜂蜜看守者那裡取得30個蜂巢。", description = "<小雲蛟到處蹦跳，然後嗚嗚地發出哀鳴。>\n\n根據這樣的行為來判斷，你感覺牠是想吃甜點了。\n\n落英園裡的香樹上有很多的蜂巢。\n\n從附近的蜜蜂那裡取得蜂蜜不會是很困難的任務。", progress = "<蛟寶寶到處打轉，為你的歸來歡欣鼓舞。>", completion = "&lt;蛟寶寶跳著迎向你的手。牠用長蛇般的尾巴圍繞著你，開始舔你手指上的蜂蜜。&gt;\n\n&lt;好癢喔。&gt;", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30151] = {title = "傳接球!", objective = "使用彈力球。然後接球再拋回給你的蛟寶寶，重複8次。", description = "<蛟寶寶用無聊至極的表情看著你。>\n\n你感覺牠在籠子裡關了一天實在是太悶了。\n\n何不玩一點傳接球遊戲?", progress = nil, completion = "喔，看來你和你的蛟玩得很開心!做得好，&lt;name&gt;。從精神到生理上，遊戲時間都對你的蛟非常有益。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30152] = {title = "天際競賽", objective = "在落英園飛過10支賽旗來完成天際競賽，然後從下方跨越終點線。", description = "大賽的時間到了!\n\n完成穿梭在尖柱之間的路線，通過10個氣球檢查站的賽旗。\n\n完成後，務必從下方跨過終點線。\n\n競爭將異常激烈，祝你好運。準備好開始時過來跟我說。", progress = nil, completion = "太棒了!完成天際競賽的感覺如何?\n\n你一定急著要拿到你的獎品!", rewards = "您會收到：\n\n\n\n等級 20–80獲勝者的獎賞\n\n等級 20–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30154] = {title = "抓住蛟龍的心，先抓住牠的胃", objective = "收集5份老虎腰肉。", description = "<蛟寶寶滿面愁容地對著你。>\n\n呃喔，看來有人心情不好!\n\n幸運的是，你正好知道怎麼讓這個小野獸開心。\n\n雲蛟最喜歡虎肉的滋味，但想取得柔軟的老虎腰肉是不小的...挑戰。\n\n幸好，你正好記得在嘯風島的西北邊有些肥美多汁的老虎。\n\n當然，你身上可能會被抓幾道傷口，或被搥打幾下，但為了你的蛟一切都值得的，對吧?", progress = "看來任務完成了。", completion = "看來為了給你飢餓的蛟寶寶找食物，你工作得十分努力。做得好。眼前或許感覺不值得，但你的蛟能感受到你的努力，並因此而愛你。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30155] = {title = "回復平衡", objective = "殺死8名滑鱗撕裂者或滑鱗飲蛋者。", description = "島上的情勢依然危急，<name>。\n\n滑鱗沒有回應我們談和的請求，所以只剩最後一個選項。\n\n為了保護野生的雲蛟，我們得把這些侵入者消滅殆盡。只有這樣，雲蛟才能平安地生活。", progress = nil, completion = "這些侵入者對外交途徑不做回應，但肯定會對我們的刀劍有所反應。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30156] = {title = "餵養時間", objective = "取得3份鹽背烏龜肉餵養你的蛟寶寶。", description = "<蛟龍衝上前來啃著你的手指。>\n\n噢!顯然，這小野獸肚子餓了。你回想到東北方那座住著野生雲蛟的島上有些看起來肉很多的烏龜。\n\n也許龜肉可以滿足蛟寶寶貪婪的食慾。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30157] = {title = "更空的巢", objective = "繫住並送6隻嘯風蛟寶寶回巢。", description = "喔，感謝女神，另一名雲蛟訓練師！\n\n我剛聽說東北方嘯風島上的野生蛟龍寶寶遇上了大麻煩！\n\n在成年蛟龍和那些可怕的薩烏洛克作戰時，有誰看顧可愛的蛟龍寶寶？沒有人！\n\n我們得拯救牠們！\n\n我把我遇見的每一個訓練師都派去幫忙。如果你不忙，能否去確保蛟龍寶寶都平安回到牠們母親的巢？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30158] = {title = "解除敵方武裝", objective = "收集5個滑鱗魚叉。", description = "我們需要更具侵略性的行動才有辦法阻止這些侵入者。\n\n如果我們能移除敵人用來殺死和捕捉蛟龍的主要工具，或許就能一勞永逸地阻止他們的行動。\n\n我需要你進入他們位於嘯風島東方的領地，偷走他們的武器。\n\n沒爪子的貓無法抓傷人。", progress = "完成了嗎?", completion = "我們削弱了他們的力量，但我們還不能安心慶祝。無牙的老虎依然是危險的。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30159] = {title = "保育", objective = "取得8顆偷來的蛋。", description = "喔不!我們必須阻止他們!<name>，對嗎?雲蛟衛需要你的幫忙!\n\n你知道那些恐怖的滑鱗薩烏洛克在做什麼嗎?\n\n牠們竟敢從族母的巢裡直接偷走雲蛟的蛋!\n\n雲蛟都已經越來越稀有了，那些野蠻的傢伙真是...真是...\n\n<舒琦深呼吸。>\n\n...他們把雲蛟的蛋拿來當晚餐!太糟糕了!\n\n到東北方的嘯風島去，盡力取回所有還沒破損的蛋。身為雲蛟衛的學生，這是我們的責任!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30160] = {title = "給艾拉的紅寶石裂片", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30163] = {title = "為了部族", objective = "援救8個曦逐者俘虜。", description = "我們在魔古攻擊時撤退到避難所，但路程中還是失去了一些人。\n\n到西邊與北邊去，尋找任何對我們的戰爭有幫助的俘虜，援救他們。\n\n如果你找到聯盟的傢伙，把那些人留在那兒就好。", progress = nil, completion = "我們已失去太多人了，我拒絕失去更多。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30164] = {title = "石犁村車隊", objective = "在7名石犁特使身上使用帝國蓮花藥膏。", description = "我盡力試過援救石犁特使，但那些「螳螂人」把許多特使拖進叢林。\n\n這些民眾需要我們的幫助。\n\n請帶著你稍早收集的藥草，我會將聖光賜予我的力量灌注在這些藥草裡。盡你所能把這些藥草用在石犁特使身上。", progress = nil, completion = "百姓們都想來感謝你。這些螳螂人是個嚴重的威脅。我們得趕快集合力量來幫忙。\n\n其中一位大使希望我把這交給你作為謝禮。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30165] = {title = "追踪事件：挑选蓝色翔龙", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30166] = {title = "追踪事件：挑选绿色翔龙", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30167] = {title = "追踪事件：挑选金色翔龙", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30168] = {title = "竊盜劫掠者", objective = "找回5件掠奪來的錦魚人贓物。", description = "薩烏洛克！\n\n這些邪惡的生物酷愛殘殺與偷竊。他們毫無先兆和預警地攻擊我們營地。\n\n拜託，<class>，你能幫我們從河岸邊的川刃掠奪者那裡取回一些失去的物品嗎？我們會很樂於報答你的。", progress = "我想他們甚至偷走了我的神聖痰盂。", completion = "很少有人願意這樣幫助一個需要協助的村落...尤其這個村落位於蠻荒深處。\n\n&lt;name&gt;，你是我們人民的英雄。", rewards = "您能選擇下列奬勵中的一個：\n\n絲生蛾刻像獵鯉野鶴羽飾林地螫蟹羽毛叢林女獵手塑像\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30169] = {title = "劫掠者首領斯洛凡", objective = "殺死劫掠者首領斯洛凡。", description = "劫掠者的首領是一個非常暴力的薩烏洛克，人稱劫掠者首領斯洛凡。紅鶴寺通常會在他來襲的時候前來援助，但我們似乎開始敵不過他們，也跟不上他們的行動。\n\n拜託你，<class>，幫我們消滅這個劫掠首領。\n\n他的巢穴就在喀撒利瀑布後面，你可以在那裡找到他。", progress = nil, completion = "你幫了我們一個很大的忙。我代表人民感謝你。\n\n請收下這個做為我們的謝意。", rewards = "您會收到：\n\n舒申的痰盂恆龍寶箱"}
MultiLanguageQuestData['tw'][30172] = {title = "力能扛桶", objective = "帶領泥杯回到半丘。\n\n如果你和泥杯走散了，你可以在金扇澤裡的巨大香蕉旁找到他。", description = "不，不，不，你別擔心扛桶子的事。我可以扛起這些木桶。\n\n我或許不是最結實、最聰明，或者相處起來最有趣的熊貓人，但我還是比牡山獸之類的野獸強壯的多。\n\n我只需要你帶路就好。", progress = "泥杯在哪？", completion = "太好了！水來了！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30173] = {title = "战地豪猪！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30174] = {title = "為了家人", objective = "搜尋柯爾‧血牙。", description = "柯爾現在應該要跟上了。他說他要去確保東邊廓亞廢墟的安全，再跟我們會合，協助我們抵抗螳螂人的威脅。\n\n他或許需要人幫忙對付創始者布歐齋。你能去協助他嗎?我跟康恩很快就會跟上。", progress = nil, completion = "&lt;name&gt;，我要謝謝你為我的朋友報仇。我們並不總是處得很好，但我會為他哀悼。\n\n我相信他會希望你挑走一樣他的物品，用來紀念他並表示他的謝意。", rewards = "納耶里披肩號角之息肩甲深野蠻荒肩鎧納松肩甲安格寇襯肩川刃肩甲薩鍾肩甲廓亞護肩朵迦護肩您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30175] = {title = "螳螂人", objective = "殺死10個伊克席克先驅者。", description = "螳螂人!他們從四面八方冒出來，瞬間將我們的車隊摧毀殆盡，讓我們的人四散奔逃。\n\n現在他們準備要攻擊石犁村。\n\n拜託你，<class>，在這些野獸的數量足以夾擊我們的家園之前，先殺掉其中一些。\n\n如果我的表親連大使還活著待在我們的車隊裡，他一定會給你酬勞以感謝你的協助。", progress = nil, completion = "&lt;class&gt;，謝謝你的協助!我從沒見過有人能和螳螂人對抗到這種程度。\n\n嗯，當然，除了影潘之外...", rewards = "納耶里長袍號角之息長袍深野蠻荒護甲納松護胸安格寇長袍川刃外套薩鍾護胸廓亞護軀朵迦護軀您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30177] = {title = "随机英雄日常 （第一次）（大地的裂变）", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30178] = {title = "深入蠻荒", objective = "在朵迦河南部找到失蹤的祝家守望站信差，然後繼續前往紅鶴寺與可羅‧霧行者交談。", description = "在蠻荒深處，喀撒朗河位於南方海岸的出海口一帶，坐落著紅鶴寺。寺裡住有赤吉與他最虔誠的信徒。\n\n他們應該已知悉這裡所發生的事了。\n\n如果你往那裡去，我想請你幫個忙。我們常常會送補給品到那座寺廟去，但我們最後派去的那名信差並沒有回來。請你在旅途中尋找他的蹤跡。他應該要在朵迦河前的分叉路上往北走。抵達紅鶴寺之後，去找可羅‧霧行者。", progress = nil, completion = "我明白了…煞已經滲透到領地那邊了，是不是？\n\n嗯，我真的很不想讓你失望，但這座寺廟裡也有煞在肆虐。我們當中還沒殺死或被…占據之類的人，都已經逃命去了。\n\n如果你在祝家守望站打敗過煞，我必須乞求你在這裡幫我們解決他們。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30179] = {title = "中毒！", objective = "取得5隻魔古毒刃。", description = "不要相信，魔…古。有毒…取樣本…樣本刀刃，帶去西邊…雷霆斷崖…給戴斯可。", progress = "你有恰星的消息嗎？", completion = "恰星死了？這真是壞消息。柯爾、恰星和我在每個海岸上一起鬥過龍、亡靈和聯盟。\n\n這樣子失去他…\n\n我很感激你把這些武器帶回來給我。這應該能讓我們更了解這種新敵人。", rewards = "青春之池戒指淚之戒排齒指環失落世紀徽印禁忌叢林徽印您會收到：\n\n青春之池戒指淚之戒排齒指環恆龍寶箱"}
MultiLanguageQuestData['tw'][30181] = {title = "牡山獸狩獵專精", objective = "殺死15隻塵背牡山獸。", description = "牡山獸！瞧牠們生得多大隻。牠們的年紀可能就跟腳下的泥土一樣老。也是不錯的戰利品。\n\n如果你想証明自己捕獲大型獵物的能力，就從牠們下手吧。", progress = nil, completion = "幹得好&lt;name&gt;。\n\n我的父親橫渡海洋到了新大陸，結果他好像只想狩獵那些無聊的狼。\n\n我呢，我喜歡那些有肉的獵物。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30182] = {title = "狐狸狩獵專精", objective = "殺死15隻狡猾狐狸。", description = "所以，我在東邊偵察時，看見一群狐狸。我在漂流島上的時候，那是我最先學會補獵的東西。\n\n如果你想要看看一個年輕熊貓人獵手在成長中面臨過的挑戰，就到東邊去抓些狐狸吧。牠們大都聰明又狡猾，所以提高戒備。", progress = nil, completion = "做得好！你鬥智贏了這些狐狸。我會和痞利浦先生聊聊，再給你弄一份戰利品。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30183] = {title = "潛獵者狩獵專精", objective = "殺死15隻峽谷潛獵者。", description = "老虎！不管哪塊土地，我都會聽見這種尖牙猛獸的名字。但我還沒機會獵殺牠們。\n\n來獵點老虎吧。我往東走，你往西走。我好像看到有些老虎在塵背峽谷附近出沒。我敢說那些牡山獸附近會有很多。", progress = nil, completion = "哇！你真是獵了很多。我會和痞利浦先生聊聊，把裡面最好的一隻弄成你的戰利品。", rewards = "赫米特的緞質護腿赫米特的皮腿甲赫米特的環甲護腿赫米特的光潔腿鎧赫米特的絲質長褲赫米特的皮甲腿甲野生原護腿赫米特的重型腿甲赫米特的裝甲腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][30184] = {title = "牡山獸狩獵專精：黑革", objective = "取得黑革的頭。", description = "我的孩子是個有天賦的獵人…受訓中的獵人。我們來讓他見識一下老派的奈辛瓦里風格吧？\n\n我在東邊看見一隻皮革和夜晚一樣黑的牡山獸。看起來牠在全盛期時還幹掉過幾個獵人。\n\n如果你有興致獵點大的，試著去挑戰牠吧。", progress = "「特大級獵人」就該有「大」獵物。", completion = "這才是個像樣的戰利品。", rewards = "牡山獸砍斧黑革之刃狩旅團防衛者黑革屏障牡山獸尖刀奈辛的巨鉗戰利品狩旅團日誌狩旅團燈籠您能選擇下列奬勵中的一個：\n\n英雄的獎金\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30185] = {title = "烏龜狩獵專精", objective = "收集5個完整的龜殼。", description = "確實，烏龜算不上什麼大獵物，但牠們可是凶惡的獵物。而且牠們也是誘捕大獵物絕佳的餌！\n\n高特爾找到一些古老石板，上面記載托加利坑曾是用來獻祭的場所。古帝國就從這裡把犯人當作食物丟進水裡。\n\n我倒想知道水底下到底有什麼。去收集一些新鮮的烏龜殼，和我在坑裡碰面。\n\n讓我們看看古老的傳說是不是真的。", progress = "我一直活在父親的陰影下。但是從今以後，人們將會記得小奈辛瓦里的名字！", completion = "謝謝你。這一次我一定可以超越老爸。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30186] = {title = "家傳狩獵專精", objective = "消滅托加的禍害。", description = "如果那些石板說得沒錯，我只要來個小小的舞蹈儀式，就能召喚出深處的那隻大傢伙。\n\n等他一出來，我們就捉住他，到時老爸就知道我們兩個都跟他一樣，是真正的特大級獵人。", progress = nil, completion = "你救了我兒子一命！我不知道該怎樣表達我的感激。拜託！收下這個吧。", rewards = "深淵巨物指環舞蹈儀式指環奈辛瓦里徽記父母專精指環托加的禍害之戒您會收到：\n\n"}
MultiLanguageQuestData['tw'][30187] = {title = "飛行訓練:維持航線", objective = "飛過漂浮於霧紗海上各個檢查站的10支賽旗。", description = "你已經學會比賽的基礎技巧，你應該去熟悉一下比賽航線。\n\n探索尖柱區，從各個檢查點取得賽旗。\n\n飛過檢查點就能取得賽旗。", progress = nil, completion = "做得好。如果你沒辦法找到檢查點，你恐怕永遠也不能在天際競賽中有所表現。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30188] = {title = "展翅高飞", objective = "加入云端翔龙骑士团。", description = "我已经不能再以你的老师自居了，<name>。\n\n你已经证明了自己，现在你配得上你的翔龙了。\n\n今天，你将加入我们的行列。准备好了吗?您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n翠玉雲蛟韁繩\n\n您還會收到：\n\n翠玉雲蛟韁繩恆龍寶箱"}
MultiLanguageQuestData['tw'][30189] = {title = "給艾拉的可愛的蘋果", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n半顆可愛的蘋果"}
MultiLanguageQuestData['tw'][30190] = {title = "林精之患", objective = "击败8个岩肤捣乱者。", description = "又是林精！我恨死这种东西了。我们要阻止他们伤害其他人或烧掉半个村庄！\n\n如果你看到了这种害虫，杀掉他们！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30191] = {title = "谁动了我的啤酒", objective = "找回10个失窃的雾临酒桶。", description = "有人把一些啤酒忘在南面的高地上了，现在林精喜欢上了我们的啤酒。他们上午偷偷溜进我们的小镇，偷走了所有酒桶。\n\n把你找到的酒桶带回来。熊猫人工人如果没有了啤酒……是没办法打起精神干活的。我们需要精神抖擞的工人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30192] = {title = "我们村着火了", objective = "扑灭30处火盆火焰。", description = "不知你注意到没有，我们村着火了……\n\n林精正在踢火盆玩儿！他们在村里到处放火。\n\n求你帮帮我们吧！把你能看到的火头都踩灭。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30193] = {title = "想吃肉", objective = "取回10片草原羚羊肉。", description = "辛勤工作的人有資格吃大餐，但我沒有上好的肉了!\n\n你可以到森林裡去弄一些新鮮的羚羊肉嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30194] = {title = "山雨欲来风满楼", objective = "击败8只雷喉狼。", description = "今天早晨，村民们又丢了一头牦牛，肯定是河对岸某只雷喉狼干的好事。这些家伙真是越来越大胆了。\n\n这说明它们的种群太过庞大，这座山谷已无法再供养它们了。是该再削减一下它们的数量了。\n\n如果你愿意帮我做这件事，我会衷心感谢你的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30195] = {title = "怒放的鲜花", objective = "收集10束锦绣花。", description = "能否帮我这个友善的商人一个忙呢？我需要增加锦绣花的库存。它们生长在附近的树林中。\n\n你能帮我这个忙吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30196] = {title = "采菇热", objective = "采摘12朵蘑菇。", description = "建造新村庄的工人们似乎已经饥饿难耐了。\n\n我已经准备了一份丰盛的炖汤食谱，但还需要从东面的徒圣陵园中采摘一些蘑菇。显然，那里有一些愤怒的灵魂，让人难以靠近。我不太适合去做打打杀杀的事情。\n\n如果你今天打算去墓地，能否帮我摘一些蘑菇呢？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30197] = {title = "Cart Ride", objective = "Ride a delivery cart to XXX Village.The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.您會收到：\n\n完成任務後，你將獲得：\n\n", description = "The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
