MultiLanguageQuestData['tw'][30226] = {title = "高地之血", objective = "在遗迹高地击败8个韶天魔古族人。", description = "一小队魔古族正在北边的遗迹高地安营扎寨。\n\n快去把它们杀光！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30227] = {title = "『花崗哨兵』巫龍", objective = "殺死『花崗哨兵』巫龍。", description = "郭萊院裡的一尊麒麟獸雕像活過來了，而且差點殺掉我寶貝的昆。我絕不允許!沒人可以威脅我的昆。\n\n我要你到裡面去把那東西砸成碎片。我很想自己去做這件事，但我得先照料我愛人的傷勢。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n谷之寶藏次級好運符咒"}
MultiLanguageQuestData['tw'][30228] = {title = "給麻煩精找麻煩", objective = "殺死8個石木妖精。", description = "木之妖精回來了。我需要你在他們造成麻煩之前先殺了他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30229] = {title = "更大的危機", objective = "殺死8個廓亞回收者。", description = "抱歉我之前講話太粗魯。戴斯可等待力量集中再前往西邊的想法或許是對的。\n\n當我們搜索西邊廢墟時，裡面的魔古對我們造成重大打擊。他們用召喚傳送門和黑暗魔法伏擊我們。自從去過外域之後，我還沒看過這麼邪惡的巫術。\n\n我們需要喘息的空間。到西邊去，殺死他們的召喚師，斷絕他們補給線。", progress = nil, completion = "斷絕了他們的援軍之後，我們就可以對回收者領主展開攻擊行動了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30230] = {title = "再回收", objective = "找回10個魔古神器。", description = "魔古是群暴徒，始終如一。只有在他們帝國統治時代的古老傳說中，他們才懂得一點魔法。\n\n但這些魔古卻會使用秘法傳送門和法術。我們必須阻止他們!\n\n$p，找出任何魔古用來施放法術的神器。我在西方和北方看到許多他們的收集者與回收者在收集這些物品。", progress = "我們手中多一件神器，魔古手中就少一件武器。", completion = "幹得好，&lt;name&gt;。你取走了孩童手中的利劍。", rewards = "納耶里腕輪號角之息束腕深野蠻荒臂甲納松護腕安格寇腕輪川刃裹臂薩鍾腕甲廓亞臂鎧朵迦護腕您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30231] = {title = "撿起雙龍果", objective = "取得12個雙龍果。", description = "我需要更多雙龍果!去樹林裡幫我搖一些果子下來，好不好?\n\n拿著這個，我採收時都會用到它。當水果掉下來的時候，它可以讓採收的效率更高!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30233] = {title = "裂齿", objective = "击败裂齿。", description = "嗨！呃……我碰到件左右为难的事。关于狼的名字，我只有一个拿得出手……你听听……裂齿！我知道，很酷的名字，不是吗？！但现在森林里有两只让人讨厌的大狼，我根本分不清谁是谁。\n\n我想请你去杀掉一只，这样我就用不着再想一个名字了。够简单了吧，对吗？特别是对于像你这样的传奇人物。\n\n那么，准备好出发了吗？我希望得到肯定的回答！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n谷之寶藏勇氣點數次級好運符咒"}
MultiLanguageQuestData['tw'][30234] = {title = "钳颚", objective = "击败钳颚并取回任的长棍。", description = "钳颚！听起来很凶猛，对不对？这是我自己想出来的名字，我觉得非常贴切。我曾同它搏斗了好几个小时，想把我的法杖从它嘴里弄出来，但它就是不松口！\n\n好吧，其实我只跟它搏斗了几秒的时间而已。我还是喜欢跟朋友坦诚相对，虽然这会让我的故事乏味很多。\n\n说正题吧，你能不能把你满腔的愤怒发泄到这只下颚像钳子一样有力的鳄鱼身上，然后再把我的法杖带回来给我？最好是完整的啊！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n谷之寶藏次級好運符咒"}
MultiLanguageQuestData['tw'][30237] = {title = "重现：熊猫人起义", objective = "击败8只远古魔古之魂。", description = "在东边的徒圣陵园，古代魔古族的灵魂和反抗他们的熊猫人先祖的灵魂陷入了一场混战。自从魔古族回到这个山谷之后，灵魂们就一直不得安宁。\n\n如果你愿意到陵园去让那些魔古族灵魂重新体验一次战败的滋味，那我们就可以让我们先祖的灵魂获得长久的安宁了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30238] = {title = "重归安宁", objective = "祭拜6个熊猫人墓碑。", description = "我们先祖的灵魂正在东边的徒圣陵园重现一场历史上的伟大战斗。\n\n请按我说的去做，<race>，并祭拜他们的墓碑。让他们知道，多年之后他们的在天之灵仍然受到后人景仰，他们应该得到安息。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30239] = {title = "缚奴者牢非", objective = "击败缚奴者牢非的灵魂。", description = "你听到缚奴者牢非的灵魂在徒圣陵园顶上的山洞里吼叫嘲骂的声音了吧？\n\n击败他一定确保熊猫人武僧灵魂们取得胜利。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n谷之寶藏次級好運符咒"}
MultiLanguageQuestData['tw'][30240] = {title = "生存競技場:灼熱火焰", objective = "進入生存競技場，並在裡面存活60秒，不能離開。", description = "我讓我的戰士們接受這樣的挑戰，好讓他們保持強壯與迅捷。我們來看看你的表現如何。\n\n在競技場裡待上60秒，不能被推出場外或被殺死。保持警覺。", progress = nil, completion = "不錯，&lt;class&gt;。非常不錯。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30241] = {title = "警告石犁村", objective = "前往四風峽的石犁村。", description = "這麼多的死亡。而如果韓大使關於螳螂人的故事屬實，那麼還會有更多的死亡。\n\n我們必須幫忙。我們必須盡我們所能來挽救生命。\n\n到石犁村去。警告他們螳螂人即將來襲。\n\n在我安葬柯爾的屍體之後，我會帶著我所能集結的最大兵力和你會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30242] = {title = "生存競技場:致命刀鋒", objective = "進入生存競技場，並在裡面存活60秒，不能離開。", description = "我讓我的戰士們接受這種挑戰，好讓他們保持強壯與迅捷。我們來看看你的表現如何。\n\n在環裡待上60秒，不能被推擠出環外或被殺死。保持警覺。", progress = nil, completion = "不錯，&lt;class&gt;。非常不錯。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30243] = {title = "螳螂人著火", objective = "到落陽關附近，使用熱油鍋殺死80個螳螂人。", description = "螳螂人再次來襲，我們在城牆上的人手有點不足。由於期待你來幫忙，我特別為你保留了一個有趣的崗位:熱油!\n\n這工作比聽起來更暴力但沒那麼可恥。\n\n真的很簡單。到城牆上去，找一個儲油站，然後把油倒到任何攻擊長城的螳螂人身上。這非常有效。", progress = nil, completion = "你重創了螳螂人的部隊。城牆防衛者接下來應該能控制局面了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30244] = {title = "沿著蟠龍脊", objective = "到落陽關殺死10個柯克席克螳螂人。", description = "城牆上有螳螂人。庭院的防衛者正在求援!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30247] = {title = "翻滚俱乐部：锦绣谷", objective = "完成锦绣谷的翻滚路线。", description = "跟随旗帜，拜访记录点，完成巡视路线。在时间用完之前回到我这里。\n\n准备翻滚时请告诉我一声。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30249] = {title = "落陽之下", objective = "殺死『劫屍者』科里崇。", description = "有隻大怪獸挖地道從門底下穿到院子裡來肆虐。防衛者需要你的幫忙!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n谷之寶藏次級好運符咒"}
MultiLanguageQuestData['tw'][30252] = {title = "伸出援手", objective = "摧毀8個不動如山之石。", description = "我花了一整個早上推它、鏟它還有敲它，不過一點用都沒有。\n\n這些岩石真是不動如山！\n\n「就像一陣清風。」我爺爺曾經說。「耕田就像呼吸一樣簡單！」對他或許是這樣啦，但對我可不是！\n\n如果我連清出一塊可以種植的農地都辦不到，我這個農夫事業還有什麼前途呢？\n\n喂，等等。你看起來是個強壯的傢伙。\n\n你想幫忙嗎？先等我喘口氣吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30254] = {title = "第一次種植就上手第二課:種植作物", objective = "翻動兩畦未開墾的荒土使其變成開墾過的沃土。然後將輕鬆培植綠色捲心菜的種子播在這兩畦開墾過的沃土中。", description = "好，有了種子，是時候來播種了。\n\n首先，我們要準備合適的土壤！你得翻動土壤，把它攪鬆，讓它變成適合發芽的溫床。\n\n翻動那邊的兩畦土壤，然後把種子播下去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30255] = {title = "第一次種植就上手第三課:照料作物", objective = "在日歌農莊使用生鏽的灑水壺，對兩個乾巴巴的輕鬆培植綠色捲心菜澆水。", description = "我的祖父以前常告訴我「小尹啊，蔬菜就像女人一樣，你放著不管她，她很快就會腐敗的。如果你細心呵護她，那她就會長得又大又豐滿，然後你就可以幫她綁上緞帶拿去市場和你的朋友們炫耀了。」別追究觀念，他是另一個世代的人了，好嗎？\n\n現在的重點是，我們的蔬菜發芽了，它們需要被照顧！今天它們看來有點乾燥，所以你該給它們灑點水。\n\n這是我祖父留下的舊灑水壺。我把它放在田地附近，好讓你隨時可以取用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30256] = {title = "第一次種植就上手第四課:收成", objective = "從你的田地裡採收兩株輕鬆培植綠色捲心菜，然後帶去日歌農莊交給農夫尹。", description = "是我們的辛勤工作開花結果的時候了！我們通常得等上一天作物才會收成。\n\n幸運的是，青田給的這些特製種子可以快速地生長。它們產量也許不豐，不過可以讓新手農夫循序漸進學會耕種的過程。\n\n我們的蔬菜應該可以收成了。不用說，我當然會讓你負責執行這項光榮的任務！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30257] = {title = "第一次種植就上手第五課:半丘市集", objective = "調查農夫尹房子底下的深色土壤，然後將禮物帶去給半丘市集的吉娜‧泥爪。", description = "好了，朋友，剛才耕的那些田不過是練習而已！\n\n你準備好來點真正的工作了嗎？\n\n我聽說有個名叫吉娜‧泥爪的女士負責營運南邊街上的半丘市集。\n\n我聽說她想買一些蔬菜。由於這是你第一次和她見面，你不該兩手空空地去拜訪。\n\n你何不在農場四處搜尋一下，看看有沒有什麼好東西藏在附近？\n\n或許我們會找到能送給我們新鄰居的好禮物！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30258] = {title = "芒芒的一票I:猴子難纏", objective = "到四風峽的好漢‧泥爪的房子處找芒芒。", description = "我一直在思考該如何獲得耕者工會的垂青，<name>。\n\n聽好，耕者工會每年都會接受新成員加入，而他們有一個五人小組的選拔委員會。\n\n我們已經拿到吉娜的一票，但還得繼續向其他四名成員證明我們自己。\n\n你何不過去和芒芒打個招呼？他在泥爪先生那裡工作，就在西北方泥爪的農地那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30259] = {title = "芒芒的一票II：腐敗核心", objective = "收集10株被咬過的胡蘿蔔。", description = "那些兔妖又回來了！\n\n他們一直啃咬泥爪先生的胡蘿蔔。破壞他的作物。然後誰要負責？芒芒，就是我要負責！\n\n在泥爪先生看到之前，你去把被咬過的胡蘿蔔收起來。它們在西南邊的田裡到處都是，還有地下的兔妖隧道裡。\n\n不幫我，芒芒就有大麻煩了。\n\n你願意幫我吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30260] = {title = "拓展農地I:除草", objective = "到四風峽的中央平原找凱藍談話。", description = "嘿，<name>，我最近打算擴展我們的農地。\n\n看到那塊被雜草覆蓋的土地了嗎？如果能清理掉那些雜草，我們就可以把那塊地拿來耕種了。\n\n我聽說有個叫凱藍的農夫知道不少除去雜草的方法。\n\n他的田地就在西邊。去和他談談，看他是否願意幫助我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30261] = {title = "滾動俱樂部:蟠龍脊", objective = "完成蟠龍脊的滾動行程。", description = "在最短的時間內到牆底下去。\n\n準備好要滾動時就告訴我。", progress = nil, completion = "打造那面牆的時候，我想他們不知道我們會把牆用在這種用途上面。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30262] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30264] = {title = "兵臨城下", objective = "使用影潘天蛟殺死60隻柯克席克攻擊者、3台柯克席克戰車、和3台柯克席克投石車。", description = "螳螂人部隊朝長城大舉進攻。我已經安排了一些飛蛟要從空中削弱他們的武力。\n\n你願意騎到其中一隻蛟身上嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30265] = {title = "眼中光华", objective = "找回8颗闪光红宝石。", description = "我一直凝视着湖面，思索着生命、爱情和所有美好的事物。然后突然我意识到，水中泛起的辉光绝不是我光辉人格的倒影，水底下真的有东西在发光！而且肯定价值不菲。\n\n你可以潜到水下，揭开湖底深处那神秘的辉光之迷吗？拜托啦！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30266] = {title = "血染蒼穹", objective = "使用落陽砲台殺死30隻柯克席克雄兵。", description = "我們在主門兩側的塔頂架設了火砲。當螳螂人像現在這樣想飛越長城時，這些火砲是讓天上保持淨空的最佳手段。\n\n看來輪到你上場了，<name>。", progress = nil, completion = "你瞄得很準，&lt;class&gt;。下次有空襲時我會記住這一點。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30267] = {title = "淡淡的悲傷", objective = "取得18隻林地微光蟲與5支細長血羽。", description = "我愛釣魚。如果我的釣餌還在的話，我現在一定會更開心。它們在一場…與我太太的誤會中被丟掉了。\n\n<林地拋竿手嵐嘆了口氣。>\n\n我該讓小小的家庭糾紛，毀掉我一整天的釣魚日嗎？不！我需要的只是一些小蟲跟羽毛，這林地裡到處都是這兩樣東西。\n\n介意幫我這漁夫一個忙嗎？", progress = "我絕不能不釣魚。釣魚就是我的一切。", completion = "終於，有人了解我了。釣魚就是一切，對吧？\n\n或許我該離開新席非拉…打包我的家當並加入南方的釣手隊。當然，我不能這麼拋下我的家庭…\n\n但無論如何…熊貓人有作夢的權利，對吧？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30268] = {title = "黑汗", objective = "到喀撒朗河中，從暗鱗打擊者身上取得暗鱗蛇頭。", description = "仔細看看。附近的河裡滿滿都是這種蛇。他們的毒液會造成當地人稱為「黑汗」的症狀。\n\n幾個難民從寺廟逃出來時被咬傷，現在已經開始出現噁心、嘔吐、排乾體液似地瘋狂流汗，造成脫水症狀並可能致死。\n\n我們正在儘快施打血清，但我們需要更多毒腺。別浪費時間自己取出腺體，只要把整顆頭帶回來就好。", progress = "<安杜因全神貫注在自己的手上，他飛快地把毒腺從蛇頭裡切割出來。>\n\n就在上下顎裡...第二顆牙後方兩英吋處...", completion = "謝謝你，&lt;class&gt;。我就知道你的努力可以解決問題。\n\n聽到避難所裡發出的慘叫聲後，即使是不共戴天的仇敵，我也不希望他們身上發生黑汗。", rewards = "黑汗結界鸚鵡羽毛指環蛇顎指環蛇群之戒暗鱗指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][30269] = {title = "不安全的通道", objective = "幫可羅‧霧行者將一群來自紅鶴寺的難民護送到鶴翼避難所去。開始前先和可羅交談。", description = "就像我們在寺裡常說的:「後門有猴，前門忌虎。」\n\n我們一定會解決煞的問題，但我們無法兩面兼顧，必須先處理好...眼前的麻煩。\n\n<可羅將扭動掙扎的薩烏洛克狠狠摔在石頭上。>\n\n有群從寺廟逃出的難民想前往北邊的營地，但他們遭到薩烏洛克的伏擊。幫我把下一群難民送到營地去，然後我們再想想下一步該怎麼做。", progress = nil, completion = "謝謝你，&lt;name&gt;。沒有你的幫助我們無法完成這件事。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30270] = {title = "奪川刃眼目", objective = "到鶴翼避難所周遭殺死8個川刃巡路者。", description = "「罩頭鷹隼，獵物無著。」\n\n這是我們寺裡最早教給年輕僧侶的頌歌之一。意思是即使如鷹隼般迅捷致命的敵人，也可以藉由剝奪其感官使他失去攻擊力。\n\n薩烏洛克在整個地區都有斥候，相當於他們騎兵隊的眼目。\n\n該是奪走他們眼目的時候了，你不認為嗎？", progress = nil, completion = "做得好。真希望我能跟你一起去...\n\n你知道的，我綁手上的血漬不是我自己的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30271] = {title = "煞可畏", objective = "在10名失去希望的武僧或侍僧附近殺死煞，以鼓舞他們。", description = "煞有神秘的能力，可以在受害者身上引發強而有力、鋪天蓋地的情緒反應。\n\n我們逃出寺廟的時候，鶴翼教團中較年長的成員墊後掩護我們逃走。他們肯定已受制於巨大而激烈的情感創傷，而我擔心，恐怕他們不是每個人都有足夠的力量抗拒落入絕望的深淵。\n\n$p，我們必須讓他們看見希望!讓他們目睹絕望可以被打敗!", progress = nil, completion = "老實說，我有點驚訝那真的有效。\n\n在潘達利亞這塊土地上，隱喻與真實之間界線模糊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30272] = {title = "朝雨揮拳", objective = "在紅鶴寺殺死18個絕望幽魂。", description = "至於「朝雨揮拳」這個部分...嗯，有時你不得不這樣。\n\n「冀若雲外日，天陰雨嵐侵，朦朧難目視，長存自吾心。」\n\n從寺廟裡湧出的煞似乎沒有止盡。但為了看見被絕望的面紗所遮蔽的事物，你必須切開它。\n\n如果幸運的話，你會在烏雲背後找到太陽...", progress = nil, completion = "&lt;name&gt;，你知道嗎？我們是絕佳團隊！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30273] = {title = "紅鶴的屋簷下", objective = "進入紅鶴寺的地下室並擊敗絕望之煞。", description = "「絕望之禍源于心，心中無望則身瘁。」\n\n這是紅鶴在煞蜂擁而出的幾個時辰前，留給我最後的智慧箴言，現在我懂了… \n\n$p，煞發動攻擊時，是從寺廟的地下室裡衝出來的…\n\n他所有的教導，所有鶴之道的真義…全都是為了面對絕望之煞所做的準備。\n\n紅鶴在幾世紀前就已經預料到這場衝突了！", progress = nil, completion = "你消滅了絕望之煞。接下來交給我的信徒們就行了。\n\n看起來，面對紹昊所造成後果的時候終於來了。\n\n這場衝突已經醞釀許久，你們族類的到來只不過是個引子。如今，潘達利亞需要你們的援助才能存續。", rewards = "納耶里之索號角之息腰帶深野蠻荒護腰納松扣環安格寇之索川刃腰帶薩鍾護腰廓亞束腰朵迦束腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][30274] = {title = "秘法之牢", objective = "找到並解開3個囚牢之鎖。", description = "一個聯盟成員？在這裡？讚美伊露恩啊。\n\n我的團隊遭遇了一個困難。我們找到一些時代比艾薩拉統治時期更早的秘法卷軸，並用以開啟通往這塊土地的傳送門。\n\n很不幸地，石板提供的座標鎖上了，而原本應該該送我們前往目的地的傳送門，卻把我們帶來這個秘法之牢。\n\n我們困在這裡好幾天了，而這個地牢正緩慢地吸收著我們的能量以加強它自己的力量。\n\n你能在附近找到封住秘法之牢的枷鎖，並解除它們嗎？", progress = nil, completion = "太好了!你剛剛好趕到。若在這裡多待一天，我想我們或許就虛脫成乾屍了。\n\n現在我們可以繼續尋找青春之池了!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30275] = {title = "鱷魚傳說", objective = "帶著巨鱷尾巴到四風峽的新席非拉找嚴。", description = "這鱷魚怎麼可以長到這麼大隻？\n\n當然，有傳聞說很老的鱷魚可以長到非常大隻…但這隻母鱷魚不可能超過60歲。\n\n或許在新席非拉有人能針對這個議題指點明燈。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30277] = {title = "崩潰的大廳", objective = "取回遠古郭萊神器。", description = "郭萊密庫裡發現了一個遠古魔古留下的神器，就在雕像廳外面。我們不斷地試著想取回它，但沒有人成功。\n\n我們不能讓這個神器落入嘯天的手中。我需要一個能幹的人去取回它。\n\n你要幹嗎?", progress = "你找回神器了嗎?", completion = "當其他人都讓我失望的時候，你卻把事情完成了。這就是我喜歡你的原因。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
