MultiLanguageQuestData['tw'][30279] = {title = "REUSE FOR PROGRESSION", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30280] = {title = "地底雷鳴", objective = "殺死密流。", description = "咆哮聲在郭萊院裡迴盪。魔古喚醒了某種古代野獸，不久他們就會把這隻野獸放出來攻擊我的手下。\n\n在他們有機會放野獸出來攻擊我們之前，想辦法到蛟龍廳去殺死牠。我無法信任其他人去執行這麼危險又重要的任務。", progress = "你殺死那隻野獸了嗎?", completion = "你完成了連我都懷疑自己能否辦到的事。你的英勇令我折服。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30281] = {title = "悄然出击", objective = "在琼花湖击败6个韶天魔古人。", description = "<他弯下身子画了一个人型生物，一看就知道是魔古，然后他指了指湖的西面，又将匕首的刀背放在喉咙的位置作切割状，满心期盼地看着你。他的意思应该是让你干掉琼花湖的魔古族。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30282] = {title = "烧光秽物", objective = "焚烧10面韶天旗帜。", description = "魔古族在琼花胡的西岸插上了他们肮脏的旗帜，以宣示他们对这里的占领。带上这把火炬，让他们知道我们对这些旗子的态度。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30283] = {title = "破碎印象", objective = "摧毁韶天仪式雕像。", description = "有时候我真为这些魔古族感到悲哀……也许抽取其他种族的灵魂只是他们处理家庭琐事的方式？也许我们应该更加体谅一下他们这些侵略活动的起因？\n\n又或许我们应该去摧毁湖边上那些用于举行灵魂盗取仪式的工具。我个人觉得这个想法听起来更有趣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30284] = {title = "千顆尖牙", objective = "殺死9個刃齒魚群。", description = "今天的水底到處危機四伏!某種討厭的食肉魚成群地住進我們的湖中了!太悲慘了。而且就發生在我想全身脫光來個午泳的時候!\n\n你很擅長殺死那些討厭的東西，不是嗎?以所有渴望游泳的熊貓人之名，你能不能在今天使用你的技能?\n\n這是一個非常高貴的動機，尤其還有我在他們的行列中!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30285] = {title = "武豪偵查報告", objective = "取回3份武豪偵查報告。", description = "攻擊之後，還有幾份偵查報告沒有回來。若我們夠幸運的話，這些報告還在村莊裡。但那樣一來，他們也有可能落入魔古的髒手中。\n\n若你能帶回你所看見的每一份偵查報告，我肯定會放心很多。絕不能讓魔古知道我們所在位置，或我們所找到神器的消息。以免讓大家陷入更深的危險。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30286] = {title = "绝境逢生", objective = "营救6个被困的雾临村民。", description = "许多村民走投无路、惊恐万分，无法保护自己。你得去保护他们、去营救他们。\n\n快点去吧，朋友，尽可能多救几个人！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30287] = {title = "来者不善", objective = "在雾临村击败6名韶天攻击者。", description = "莱文派鲁克来这里阻挡魔古军队，但是鲁克一个人杀不完。\n\n你能帮忙吗？鲁克会告诉莱文你帮忙了的。我保证。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30288] = {title = "我的村子又失火啦", objective = "使用霧臨村水桶來撲滅60處火焰。", description = "我不知道你有沒注意到，但我的村子...又著火了。\n\n村中到處都有水桶，但沒有人能出去撲滅火勢。拜託，拜託幫幫我們!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30289] = {title = "身心大解放", objective = "殺死6個守衛的控制者來解放他們。", description = "魔古正在偷取人們的心智!使他們做出邪惡的事。\n\n不要傷害他們，只要把魔古殺掉，他們就會忘記魔古偷取心智的事，並且不再變得邪惡。你應該像茹克一樣把人們修理好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30290] = {title = "石缚杀手", objective = "击败8只石缚魁麟。", description = "魔古族的石头狗怪物正在追逐并伤害村民。鲁克想干掉一些，但是它们太快了。\n\n你也帮忙干掉一些吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30291] = {title = "惊艳之举", objective = "收集12条昏迷的琼花鲤鱼。", description = "我又跟谭坛讨论了一次……他坚持认为钓鱼是一门深奥的学问。我虽然抱着怀疑的态度，但还是再试了一次。可我对那种举着鱼竿，一动不动等鱼上钩的垂钓方式不太感冒，所以我试着用了一种更直接的方法。\n\n你能帮我个忙，去收集漂浮在湖面上的那些身体完整但已经肚皮朝上的鱼吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30292] = {title = "猛然觉醒", objective = "击败8个被控制的白刃食肉者。", description = "在西边的湖畔，魔古族控制了蜥蜴人的心智并让他们与我们为敌！事实上，那些蜥蜴人原本就跟我们作对，真不知道那些魔古族在做事之前动过脑子没有。\n\n不管怎样，在这个组合里，安济是个战士，而我只是个业余的，所以我想找个能够挥动武器、施放法术和发出战吼的全能帮手。\n\n你能替我杀死些蜥蜴人吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30295] = {title = "交还任务测试例子", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30300] = {title = "成功之匙", objective = "找到韶天囚笼钥匙，释放6名金莲囚犯。", description = "魔古族抓走了许多俘虏。他们一定会受到折磨，甚至更糟。\n\n快去想办法将他们救出牢笼吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
