MultiLanguageQuestData['tw'][30304] = {title = "坚硬如石", objective = "摧毁10座魔古石雕。", description = "嘿！你知道今早我碰到什么怪事吗？\n\n我当时正和安济在遗迹里散步，我眼睛一直盯着地上，防止再踩到那些恶心的蜘蛛卵囊，结果有座石雕突然复活了，还想拍死我！\n\n虽然安济最后把它给拍死了，但这个隐患必须根除。我觉得你应该出手击碎所有石雕，无论它们有没有复活。这才是万无一失的办法。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30306] = {title = "競技場", objective = "到競技場擊敗20個影潘受訓弟子。", description = "我們有些新來的受訓弟子，對你遠遠無法構成威脅，但人數一多，他們或許就有挑戰的資格。如果不行，至少他們也上了一堂名為謙遜的課。\n\n當你準備好後，就走入競技場。別小看他們。", progress = "上場吧。讓他們看看真正的<class>如何戰鬥。", completion = "非常了不起。看來他們要學的還很多。我會確保他們把該學的都學會。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30307] = {title = "永久警戒", objective = "在金輝臺殺死8個嘯天魔古。", description = "<class>，有你跟我們在一起真好。如果你要參與戰鬥，我需要更多人到黃金階梯上的戰場，把駐守在那裡的魔古清理乾淨。\n\n我能倚重你嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30308] = {title = "硬石麒麟獸", objective = "殺死6隻花崗麒麟獸。", description = "利文總是說只有死麒麟獸才是好麒麟獸，而我非常同意。你來這裡幫忙的嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30309] = {title = "往石裡打", objective = "摧毀6個魔古肖像。", description = "魔古今天把他們那些自戀的石頭肖像送到我們的戰場上來。他們在黃金階梯上讓它們甦醒。\n\n雕像越大，我們就打得越用力。你加入嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30310] = {title = "漫天雷火", objective = "击败3只被制服的翔龙。", description = "魔古族降服了青空翔龙，使其与我们为敌。\n\n守护者难以抵挡这些翔龙，但是你可以。快沿着西北方向前往金色阶梯，并将其击落。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30311] = {title = "高标准", objective = "竖起6面金莲军旗。", description = "如果让我来选，那么军旗最重要的一个特质就是屹立不倒……并且未被烧毁，当然最重要的还是第一点。因此，毋庸置疑的，我对于我方军旗目前的状况有点担忧。\n\n如果有哪位无名<class>能前往我们西北面的战场，帮忙重新竖起我们的军旗，我本人以及我那超级性感又有点彪悍的妻子将对他感激不尽。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30312] = {title = "第二次機會", objective = "治療6個受傷的防衛者。", description = "一支愚蠢的分隊試著從東邊的小徑攻上黃金階梯，結果受到砲火的轟炸。有命回來的傷勢都十分嚴重，還有更多傷患仍在戰場上。\n\n這裡有些繃帶。用這些繃帶或你所具有的治癒技能，幫助我們受傷的防衛者回到安全之處。\n\n請你儘快，時間不多了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30313] = {title = "移动之雾", objective = "击败8个雾行鬼。", description = "<他看了看脚下迷雾怪兽的尸体，又抬头看看你，然后指了指环绕于湖边的雾霭。看来他是想让你去搜寻并击败更多的迷雾怪兽。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30314] = {title = "料理蒼刃", objective = "殺死8個蒼刃薩烏洛克。", description = "<他往下看著他腳邊死去的薩烏洛克，再抬頭看看你，然後手指著湖岸。他似乎要你殺死更多的薩烏洛克。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
