MultiLanguageQuestData['tw'][30317] = {title = "水，到處都是水", objective = "找榮雅借風箏，然後替中央平原上35個布滿塵土的地方澆水。", description = "你想讓自己派上用場嗎?\n\n最近天氣很乾燥。我需要有人到中央平原幫作物澆水。這樣吧，我需要你幫「所有的」作物澆水。\n\n我在榮雅那裡放了幾個風箏，乘坐其中一個，對任何看起來乾燥又多塵土的地方澆水。", progress = nil, completion = "哼哼!我第一眼看到你就知道你是個好的澆水員。你的手臂很適合澆水。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30318] = {title = "追逐雞隻", objective = "從西荒雞群裡面找到獲獎的雞。", description = "嘿，那邊那個!你叫<name>，對吧?我有麻煩了，我需要一個兩腿比我強壯的人來幫我解決麻煩。\n\n我的金獎母雞從雞欄裡飛出去啦!現在她跑到野外跟其他的母雞還有野鳥混在一起了，還跟...<吞口水>可能帶病的公雞混在一起。\n\n我的農田就在此地的西邊，在擎天嶺的南方。你可以幫我去找到她，然後把她帶回來嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30319] = {title = "害蟲問題", objective = "和威卡威卡交談，並踩踏25隻黑鼻土撥鼠。", description = "我的一位雇農威卡威卡一直在我最西邊的田地裡翻土。我聽說他遇到了害蟲的問題。\n\n他有很多的殺蟲劑可以撲滅啃咬我作物的昆蟲，不過我擔心他不知道怎麼處理鼠類的侵害。\n\n你願意幫他一下嗎?猖獗的猴人跟兔妖就已經夠麻煩，我不能承受再因為什麼蟲害而損失作物了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30320] = {title = "釋放靈魂", objective = "進入靈魂漩渦並釋放15個熊貓人靈魂。", description = "我在偶然的情況下發現嘯天靈魂撕裂者的匕首。它散發出強大的魔法。我聽說它可以讓你進入魔古的靈魂漩渦。\n\n魔古利用這些東西獲取靈魂，並讓靈魂屈服於他們的意志之下，但我希望你能用這把匕首來釋放靈魂。\n\n進入你在黃金階梯上找到的任何靈魂漩渦，並在魔法消失前儘可能地釋放靈魂。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30321] = {title = "雜草戰爭II", objective = "和凱藍交談，然後在他田裡拔除100株雜草。你可以在騎乘狀態下拔草。", description = "呼啊...你知道那塊田裡那個人嗎，有...有*嗝*...雜草問題那個?凱藍，我想他叫做凱藍。我真喜歡那傢伙，老兄。\n\n反正呢，他說如果我*嗝*派一個冒險者去幫他除草，他就會送我一些酒。\n\n只是一點點雜草而已，不多，也許吧。\n\n*嗝*您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30322] = {title = "錢的問題", objective = "取得香料大師金兆的欠款、商人傑必基的欠款、旅店老闆雷藍的欠款和劉儸儸的欠款。", description = "我喜歡在市集的工作，只是裡頭有個讓我很厭惡的部分:收取欠款。\n\n雖然大部份熊貓人都只是因為懶惰才會欠錢，不過鎮上還是有一些名聲不好的人會故意不還錢，也有一些是因為真的很窮困。\n\n鎮上有幾個人欠我一點錢。你可以去和他們談談，並提醒他們還我錢嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30323] = {title = "他們又不戴珠寶", objective = "取得遭竊的頭環、洗劫來的戒指和偷來的手鐲。", description = "幾個禮拜之前，一群神經質的簧尾兔妖闖進我家打破了我的箱子，偷走許多珠寶。雖然有找回一些，不過我大部分的收藏還是被他們拿走了。\n\n如果你打算前往北邊峭壁的簧尾洞穴，一定要留意那幫兔妖。我好希望能找回那些珠寶。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30324] = {title = "別在奇奇地盤撒野", objective = "到崑真村殺死8名崑真部落的族人。", description = "猴人也是有很多種的。奇奇的部落是森林猴人...來自翠玉林。我們非常好相處。\n\n崑真的入侵者...他們來自遙遠北方的山上。他們一點也不像奇奇那麼好。\n\n他們闖進我們的綠地，拿走我們的東西，然後留下一堆麻煩。\n\n奇奇想要殺死他們。你願意幫忙嗎?", progress = nil, completion = "太好了!奇奇就知道你能辦到!", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30325] = {title = "萬全之計", objective = "扔擲8個崑真儀式蠟燭、踢倒4堆熾熱餘燼，並殺死1名崑真祭儀師。", description = "我一直在觀察崑真猴人，而且我發現到他們有一個習慣。當他們準備要發動攻擊之前，他們會在自己的圖騰柱附近舉行一種奇怪且原始的儀式。\n\n如果我們能打斷他們的儀式，不只可以阻止他們即將發動的攻擊，還能嚴重打擊他們的士氣!出發吧，搗亂他們，盡你所能地把他們搞到天翻地覆!", progress = nil, completion = "哈!他們要花好一陣子來善後了。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30326] = {title = "崑真傳奇酋長", objective = "從崑真傳奇酋長身上取得崑真傳說。", description = "我聽到有些人在討論崑真猴人，說他們只是一群沒有制度的笨猴子部落...才不是這樣!他們也有大腦，只是他們都不喜歡用而已。\n\n我聽說崑真部落有兩位酋長，一位掌管戰鬥，另一位則掌管故事、知識與歷史。\n\n要是能親眼看到他們的故事，要我怎樣都甘願...您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30327] = {title = "你必須燒掉繩索", objective = "燒毀6條崑真繩索。", description = "我，嗯...好吧...\n\n喔，別在意。我只是想到一個笨點子。\n\n是這樣的，我在想，也許我們可以阻止崑真猴人再來攻擊我們，而不必...你知道的...不必殺死他們。我發現山邊有一些繩索。我覺得他們就是利用這些繩索爬下來襲擊我們的農地，還有...\n\n不，算了。反正只是個天真的想法。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30328] = {title = "千年蒸餃", objective = "取得7罐醃菜。", description = "我最受歡迎的一道料理就是千年蒸餃，裡面塞滿了醃菜。\n\n我通常會把這些蔬菜放在我家下面的洞裡發酵，不過我今天早上過去看的時候，發現它們都不見了!\n\n一定是那些可惡的兔妖小偷。\n\n把醃菜找回來，我就讓你幫我下廚。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章次級好運符咒"}
MultiLanguageQuestData['tw'][30329] = {title = "焚腸辣椒", objective = "取得4份焚腸辣椒。", description = "附近的某些熊貓人喜歡把他們的食物弄得非常辣。不幸的是，我弄不到太多這種辣椒。\n\n住在西邊山上的崑真猴人常在身上帶著焚腸辣椒。只要能弄到一點，我就能撐上好幾天。\n\n如何，你可以幫我收集一些嗎?如果你打算直接用手去碰的話，最好戴個手套。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章次級好運符咒"}
MultiLanguageQuestData['tw'][30330] = {title = "蘑菇蘑菇", objective = "取得8株影光蘑菇，並種下8顆影光孢子。", description = "我喜歡烤蘑菇...當我能找到它們的時候。蘑菇只生長在擎天嶺上，而且數量非常非常的稀少。\n\n那是非常美妙的食材，可是我們也要小心不能過度採收，這就是我們採收後還要反過來撒種的緣故。幫我摘一把已經成熟的蘑菇，然後把這些孢子種在那裡。", progress = "我們不需要太多的蘑菇。那只是用來調味而已，真的。", completion = "這些蘑菇很棒。\n\n現在，&lt;name&gt;...站近一點。讓我露兩手烤功給你瞧瞧...", rewards = "您會收到：\n\n鐵爪徽章次級好運符咒"}
MultiLanguageQuestData['tw'][30331] = {title = "一哩高的苦行", objective = "在崑真村的篝火上準備20份牡山獸肉尾燉湯。", description = "你有嚐過牡山獸肉尾燉湯嗎？就算你嚐過，恐怕也是既黏稠又無味。你瞧，有一個小秘訣可以做出完美的牡山獸肉尾燉湯:你得在高海拔的地方來烹調這道料理。\n\n我已經收集好原料了。拿著這個鍋子到西邊山上的崑真村，然後用他們的篝火來烹煮這道料理。", progress = "以前我每天都會爬到那山上，只為了練習煮這道料理。\n\n那時候我還年輕。", completion = "真是太驚人了!你真是個有天份的廚師，&lt;race&gt;。", rewards = "您會收到：\n\n鐵爪徽章次級好運符咒"}
MultiLanguageQuestData['tw'][30332] = {title = "肥羊排", objective = "收集4份肥羊排。", description = "你知道嗎?今天我打算來烤一些羊排。\n\n不，不是他們養在附近的那種小羔羊。牠們身上根本沒有足夠的油脂。\n\n<廚師拍了拍他鬆垮垮的肚子。>\n\n你覺得我光吃那些瘦巴巴的羊兒會有這樣的肚子嗎?\n\n聽好，長角羊就在西邊的擎天嶺上...牠們美味極了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章次級好運符咒"}
MultiLanguageQuestData['tw'][30333] = {title = "兩害取其輕", objective = "殺死簧尾巢母。", description = "就像其他的農耕聚落一樣，我們偶而也會遇到兔妖帶來的麻煩。\n\n最強大的簧尾兔妖就住在北方高聳的峭壁上，他們只有在蔬菜啃光了的時候才會下山來。\n\n他們只是群必須加以抑制的害蟲，而抑制他們的最好方法就是殺了他們的巢母。就這麼簡單。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30334] = {title = "其人之道還治其人", objective = "偷回16份遭竊的蔬菜。", description = "西邊山上的猴人老愛偷走我農夫朋友們的蔬菜。因為我離半丘很近，所以很少遭受到猴人攻擊的危害，不過我的朋友們就沒有那麼幸運了。\n\n依我看來，他們偷走的蔬菜根本吃不完。如果你在山上有找到任何完整無損的蔬菜...就把它們偷回來吧!", progress = "你得手了嗎?", completion = "謝謝!我會確實將這些蔬菜交還給我朋友的。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30335] = {title = "拖延暴亂", objective = "殺死12隻崑真猴人。", description = "住在西邊山上的崑真猴人非常調皮，他們四處點火並大聲吼唱。根據我在此地觀察的結果，這可能表示有一場大規模的暴亂要來了。\n\n我們沒甚麼方法阻止這場暴亂，但我們至少能在他們攻擊前削弱他們的數量。", progress = nil, completion = "或許一場攻擊仍免不了，但我和我朋友的田地應該不會有危險。\n\n反正現在只能聽天由命了。對吧，&lt;name&gt;?", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30336] = {title = "崑真獵人酋長", objective = "殺死崑真獵人酋長。", description = "據我所知，崑真猴人有兩位頭目。其中一個是無害的，他掌管著藥劑、醫學還有古老寓言的知識。另一位管理所有的崑真族獵人，而他們目前狩獵的目標就是我們的作物。\n\n這位崑真獵人酋長是我們必須處理的問題。我相信本地的農夫們都會很感激你爬上山去，然後，你知道的，「料理」他一下。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30337] = {title = "猴子大破壞", objective = "在一堆遭竊的武器、遭竊的工具、遭竊的啤酒還有遭竊的穀物附近使用一桶煙火。", description = "猴人偷走我們的東西，我們又去偷回自己的東西。這種循環總有一天要停止的。\n\n<農夫尹遞給你一桶煙火。>\n\n在他們位於西邊山上的營地找到我們的補給品，然後把煙火放在旁邊。但願經過爆炸的洗禮，他們會覺得我們的補給品不是那麼好，進而從此放棄偷竊的念頭。\n\n值得一試，對吧?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30338] = {title = "沉重的任務", objective = "取回8個魔古神器。", description = "我這輩子始終搞不懂為什麼魔古要把他們的雕像全建在這麼深的湖底。我很肯定那裡並不是一直都有水存在，不過一旦開始下雨，那個地方應該還是不怎麼方便。\n\n啊不管了，誰搞得懂魔古的奇怪意圖呢...\n\n你能否行行好，游到湖底去，把任何看起來方便攜帶的神器帶回來給我?我當然是感激不盡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30339] = {title = "弄髒你的手", objective = "取得12隻新鮮的白瓣蟲。", description = "這個湖邊可以釣到一些全潘達利亞最棒的魚。我帶了足夠的啤酒，可以讓我撐一整天，但我忘了帶魚餌。\n\n誰會記得這東西啊?\n\n如果你願意到岸邊幫我弄一些魚餌，等你要跟我買東西的時候，我會考慮為此給你一個好價錢。喔，當然，我還會付你酬勞。\n\n聽起來如何?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30340] = {title = "泥中鱼竿", objective = "收集12棵琼花芦苇。", description = "我本来是选在这个好日子出来钓鱼的，结果忘记带鱼竿了。钓个鱼要记得的事情可真多呀，脑袋里都装不下了。\n\n河边上的那些芦苇看起来正适合做根钓竿。如果你去帮我折些芦苇过来，我可以在你来买东西的时候给你打个折。哦，当然，你的劳动是有报酬的。\n\n你觉得怎么样？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30341] = {title = "在警惕的注视下", objective = "击败8个韶天勘察者。", description = "<他看了看脚下魔古斥候的尸体，又抬头看看你，然后指了指湖岸边。看来他是想让你去搜寻并杀死更多的魔古斥候。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30342] = {title = "火焰之舌，脆弱之足", objective = "杀死6条静水鳄鱼。", description = "我当时正在玩水嬉戏，突然有一只凶残的鳄鱼向我袭来，想一口咬掉我的脚！太野蛮了！后来我学着在离水远一点的地方歇脚，但我真的很怀念那一段在水里嬉戏打闹的日子。\n\n你能帮我去杀掉一条或八条鳄鱼吗？我向你保证这是它们吓唬我而应得的报应。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30344] = {title = "失落皇朝", objective = "取得6片王朝石板。", description = "不知道我能不能請你執行另一個任務。我女兒，優秀的哨兵指揮官賴奧莉亞，拒絕讓我進入荒野。\n\n我每天都在地牢中凝視著北方的廢墟，想去調查想得心癢難搔。\n\n如果我們的所在地如我所想，那麼那些廢墟裡可能有找到傳說中的青春之池所需的關鍵!\n\n<class>，拜託你!到那些廢墟裡去搶救上頭有文字的任何石板。", progress = "研究失落皇朝是一回事，親身前往遠古廢墟完全是另一回事。\n\n我腦袋發昏，好像回到了幾千年前一樣!", completion = "喔!太棒了!太棒了!\n\n你的一趟旅程讓我研究進展的程度，比苦讀十年塵封書冊與腐爛卷軸還要多...\n\n還有你看到的那些「魔古」。我要針對這個主題做些研究，也要跟康恩討論。\n\n根據我的研究推論，我懷疑他們是失落皇朝的種族。\n\n當然，這也意謂青春之池曾在他們的掌控之下。", rewards = "青春之池戒指淚之戒排齒指環失落世紀徽印禁忌叢林徽印您會收到：\n\n"}
MultiLanguageQuestData['tw'][30346] = {title = "池子在哪裡", objective = "取得朵迦之序。", description = "或許這些魔古知道池子在哪裡。\n\n我們的斥候回報，在朵迦廢墟南側看到一個指揮官。\n\n殺了他並把他身上帶著的資料拿回來。這些資料應該可以引導你到水池去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30347] = {title = "青春之池", objective = "取得一些青春之泉。", description = "北方!到北邊的青春之池去取一些泉水，但要小心謹慎。\n\n魔古在清單中把它列為「高價值」的目標。如果康恩‧藤杖還沒抵達這裡，那他會在那裡跟你碰頭。", progress = "沒有什麼比身為必朽的凡人更讓人感到急迫。", completion = "你...你找到水池了!那種泉水確實存在!\n\n但有些事不對勁。我感覺到瓶中旋動著分量相等的光明與陰暗。", rewards = "瀉湖披氅瀑布披氅天棚披氅綠背斗篷宜人披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][30348] = {title = "永生不死？", objective = "觀察費爾迪林試喝青春之泉。", description = "有些東西...不見了。這泉水感覺怪怪的。\n\n我們到達這裡的時候，我感覺到聖光的存在，強烈而生氣勃勃，從遙遠的北方傳來。\n\n我以為那是青春之池。但這個...這泉水不知為何被污染了。被魔古的魔法玷污了。\n\n我想我最好先喝一小口，然後我們看看會發生什麼事。", progress = nil, completion = "發…發生什麼事？這泉水…它…它只會轉變生命形態。它不會創造新的生命。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30349] = {title = "來自朵迦的威脅", objective = "殺死6名朵迦回收者與8名朵迦勘測員，和4名朵迦執行者。", description = "當你在廢墟幫我父親為石板撣灰塵時，我有五個斥候死於四處出現的魔古傳送門。\n\n這些生物顯然對和平不感興趣，而且跟部落一樣不可靠。\n\n無論如何，他們人數眾多，而我們太弱。\n\n到西方的廢墟去削減魔古的數量。他們不會料到有個<class>跑出來的。", progress = nil, completion = "做得好，&lt;name&gt;。再多執行幾次這樣的任務，我們或許就得讓你成為榮譽哨兵了。", rewards = "刺藤墜盒刺藤頸飾刺藤項鍊刺藤墜飾刺藤護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][30350] = {title = "美味蠕蟲", objective = "收集5個完整的誘捕者腺體。", description = "隱居的宗師可能得等等了。看看這些人，$p。\n\n他們瘦成皮包骨！他們一定餓壞了。\n\n你知道我們需要什麼嗎？一大碗熱騰騰的美味蠕蟲。\n\n如果你剛好走到河的附近，試著弄一些完整的誘捕者腺體回來，我會煮一鍋菜。", progress = "藤杖媽媽總是說，美味蠕蟲有辦法餵飽每個飢餓的人。", completion = "哈!有了這個，我可以做出一鍋讓那些流浪精靈絕倒的燉菜。", rewards = "您會收到：\n\n美味蠕蟲恆龍寶箱"}
MultiLanguageQuestData['tw'][30351] = {title = "蓮花茶", objective = "收集20片帝國蓮花葉。", description = "魔古真的很愛他們的毒藥跟詛咒。藤杖媽媽總是說蓮花茶可以治療所有魔古的詛咒。\n\n我在附近的朵迦廢墟看到一些帝國蓮花。我們應該去收集一些蓮花的葉子，並留在身邊以免魔古失控。\n\n這也給我一個機會，讓你看看我怎麼用拳頭揍那些魔古的臉。", progress = "我從沒見過這麼多的魔古。他們一直都是麻煩精，但沒有這麼壞。", completion = "沒錯!你摘葉，我揍人!", rewards = "您會收到：\n\n蓮花水恆龍寶箱"}
MultiLanguageQuestData['tw'][30352] = {title = "獵鶴高手", objective = "殺12隻獵鯉野鶴。", description = "獵鳥，你需要的是子彈，而我一點也沒有。要跟奈辛瓦里一同狩獵，你就得不斷的證明自己有足夠的戰利品能不停地吹噓。\n\n無法狩獵，就無法吹噓。而我最愛的就是吹噓，所以這一點都不好。\n\n我可以僱你幫忙殺一點獵鯉野鶴嗎？你會發現牠們在西方的河流那裡來回飛舞。牠們到處都是，所以別遲疑，順手了結牠們吧。", progress = nil, completion = "了不起。再來張椅子，這趟狩獵之旅就能變得更愉悅了。這是我答應要給你的賞金。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30353] = {title = "大發利市", objective = "獲得12瓶老虎的血。", description = "四個字：老虎的血！\n\n這玩意在黑市可以賣到比薩鋼更高的價錢。尤其是在我散佈老虎血可以讓人強精補血的流言之後。\n\n而這個森林裡到處都是老虎。你能幫我弄來幾瓶老虎的血嗎？我可以讓你分一杯羹。", progress = "我是很喜歡跟奈辛瓦里一起狩獵啦，但他純粹只為了狩獵。我則是為了獲利而加入的，而他並沒有付我們錢。", completion = "太棒了!這玩意兒可以幫我在卡林多賺進大把鈔票。這是你的份。", rewards = "納耶里手套號角之息手套深野蠻荒護手納松手套安格寇手甲川刃手套薩鍾護手廓亞護手朵迦護手您會收到：\n\n納耶里手套號角之息手套深野蠻荒護手安格寇手甲恆龍寶箱"}
MultiLanguageQuestData['tw'][30354] = {title = "拯救同胞", objective = "救出8個魔古的俘虜。", description = "我們搜索南方的廢墟時，魔古不知打哪兒冒出來突襲我們。\n\n我們當中有些成功撤回營地，但還有許多人被抓住了。魔古還抓了一些剛好也在這個地區的部落成員與熊貓人。\n\n拜託你，$p，盡你所能地救出哨兵。\n\n至於那些日行者，就留他們自求多福吧。", progress = nil, completion = "我們人數非常少，能得到這樣的幫助真的輕鬆許多。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30355] = {title = "再回收", objective = "找回10個魔古神器。", description = "魔古「不會」使用秘法。\n\n他們是群暴徒，始終如一。只有在他們帝國統治時代的古老傳說中，他們才懂得一點魔法。\n\n但這些魔古卻會使用秘法傳送門和古老神器。我們必須阻止他們!\n\n$p，找出任何魔古用來施放法術的神器。我在南方的廓亞廢墟看到成堆的這類物品。", progress = "我們手中多一件神器，魔古手中就少一件武器。", completion = "幹得好，&lt;name&gt;。你取走了孩童手中的利劍。", rewards = "納耶里腕輪號角之息束腕深野蠻荒臂甲納松護腕安格寇腕輪川刃裹臂薩鍾腕甲廓亞臂鎧朵迦護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][30356] = {title = "切斷補給線", objective = "殺死8個廓亞回收者。", description = "魔古回收者利用傳送門連結到崑萊峰，帶來援軍與補給品。\n\n更糟的是他們透過傳送門來傳送俘虜。\n\n到廓亞廢墟摧毀你所找到的每一個廓亞回收者。", progress = nil, completion = "你給了我們一些喘息的空間來療傷並準備反攻。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30357] = {title = "石犁村車隊", objective = "在7個石犁特使身上使用帝國蓮花藥膏。", description = "幫幫我，$p。這些可憐的熊貓人需要接受治療，而我的力量太弱。我從藏書中找到一本古書，教我把你稍早收集的草藥做成治療的膏藥。\n\n把膏藥拿去用在受傷的熊貓人身上，這應該能讓他們再次站起來。", progress = nil, completion = "我很久沒捲起袖子幫助需要的人了。我對長生的渴望，讓我忘記了牧師的本分。\n\n謝謝你提醒我這世界上還有值得為之而戰的東西，&lt;name&gt;。", rewards = "帝國蓮花披巾帝國蓮花披氅帝國蓮花斗篷帝國蓮花法術斗篷帝國蓮花披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][30359] = {title = "回收者領主", objective = "尋找賴奧莉亞並殺死創始者布歐齋。", description = "我女兒在他們手上!布歐齋...那個回收者領主!我能清楚地透過賴奧莉亞的雙眼看見他。\n\n那個傻女孩一定是想去拿下布歐齋的首級。\n\n$p，拜託你!到廓亞廢墟救她出來。\n\n我會找到康恩，並且把布歐齋從廢墟裡引出來。", progress = nil, completion = "謝謝你為我女兒報仇。我不會讓我女兒死的。\n\n我還有青春之泉。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30360] = {title = "警告石犁村", objective = "到四風峽的石犁村去。", description = "父親將性命托付給我，泰蘭妲毫無懷疑地信任我，哨兵們對我忠心不二。\n\n現在該是回報他們的時候了。\n\n既然布歐齋已死，我們便能趁勢掃蕩殘餘的魔古。下一個威脅是螳螂人。\n\n前往北邊的石犁村支援戰事，告訴那裡的人們，我會盡一切所能集結哨兵，幫忙對抗螳螂人，防守村莊。", progress = nil, completion = "螳螂人從南方來了？狀況可真不妙了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30361] = {title = "螳螂人", objective = "殺死10個伊克席克螳螂人。", description = "是螳螂人!他們突然竄了出來，瞬間我們的車隊便摧毀殆盡，大夥兒四處奔逃。\n\n現在他們準備要攻擊石犁村。\n\n拜託你，<class>，在這些怪蟲的數量足以包夾我們的家園之前，先剷除其中一些。\n\n如果我的表親連大使還活著待在車隊裡，他一定會給你酬勞以感謝你的協助。", progress = nil, completion = "&lt;class&gt;，謝謝你的協助!我從沒見過有人能和螳螂人對抗到這種程度。\n\n嗯，當然，除了影潘之外...", rewards = "納耶里長袍號角之息長袍深野蠻荒護甲納松護胸安格寇長袍川刃外套薩鍾護胸廓亞護軀朵迦護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][30363] = {title = "繼續攻擊", objective = "取得侵略哨兵的報告。", description = "哈!所以父親為了一個徒勞無功的任務浪費了我們二十年光陰!\n\n現在由我來負責了。\n\n當泰蘭妲派我們出來時說得很明確，沒找到她在預言中看見的聖光源頭，就不要回去。很明顯，青春之泉並不是聖光的源頭。\n\n我希望你去尋找我的斥候。我派她去調查紅鶴寺，但她還沒有回來。\n\n取得她的報告，並到西邊遠處的哨兵營地和我們碰頭。", progress = "你有找到那個斥候嗎？", completion = "&lt;name&gt;，你就和往常一樣適時趕到。目前看來，魔古也和我們一樣懂得如何使用傳送門。", rewards = "您會收到：\n\n恆龍寶箱"}
