MultiLanguageQuestData['tw'][30457] = {title = "逼首領出來", objective = "在崑萊小徑殺死10個巴塔利部族成員，直到巴塔利火焰戰士現身。然後殺死他。", description = "顯然，你是來援助我們的英雄。\n\n殺死西北邊崑萊小徑的巴塔利部族，直到巴塔利火焰戰士生氣被你逼出來為止。然後解決他。", progress = nil, completion = "我們得救了！我果然沒看錯你，&lt;class&gt;。", rewards = "濱南巨劍濱南之刃巴塔利戰盾招炎者盾牌刺藤之刃巴塔利短斧官僚手冊村長的手搖扇您能選擇下列奬勵中的一個：\n\n英雄的獎金\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30458] = {title = "探子回報", objective = "到翠玉林的珠鰭村找瑞爾‧夜風。<name>，你的朋友從偵察任務回來了。他們要立刻見你。\n\n我恐怕…\n\n嗯，我最好別再多說。你自己看就知道。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<name>，你的朋友從偵察任務回來了。他們要立刻見你。\n\n我恐怕…\n\n嗯，我最好別再多說。你自己看就知道。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30459] = {title = "所有的箭", objective = "為謝指揮官收集12枝箭。", description = "一旦他們的援兵抵達，揚古就會佔領這塊據點。那樣一來村莊就淪陷了。\n\n你願意到戰場上盡可能取回夠多的箭嗎？我有個計畫，你的幫助或許能救我們一命。", progress = "你拿到多少枝箭了？", completion = "謝謝你，&lt;name&gt;。你拯救了我們的防線。\n\n是你促成了接下來的這波攻勢。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30460] = {title = "跌打藥", objective = "使用跌打酒或你自身的治療能力幫8名受傷的濱南戰士治療。", description = "我們的戰士們正在西北方的崑萊小徑與揚古奮戰，阻擋他們入侵。\n\n帶上這個外用藥，這個藥方在我的家族中流傳了數代。\n\n如果你沒有治療的能力，就用這個跌打酒醫治戰士們吧。", progress = nil, completion = "感謝你，&lt;name&gt;。你的所作所為展現了高尚的榮譽。\n\n希望我們家的跌打酒有幫上忙。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30461] = {title = "深入蠻荒", objective = "到喀撒朗河南端的紅鶴寺附近找可羅‧霧行者。", description = "在蠻荒深處有一座紅鶴寺，寺裡住著赤吉與他最虔誠的信徒。我猜他們應該知道這裡發生了什麼事。\n\n那座寺廟就在喀撒朗河位於南方海岸的出海口一帶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30462] = {title = "深入蠻荒", objective = "到喀撒朗河南端的紅鶴寺附近找可羅‧霧行者。", description = "在蠻荒深處有一座紅鶴寺，寺裡住著赤吉與他最虔誠的信徒。我猜他們應該知道這裡發生了什麼事。\n\n那座寺廟就在喀撒朗河位於南方海岸的出海口一帶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30464] = {title = "往西前進", objective = "前往曦逐者居所。", description = "現在麗紗去到這塊異鄉土地上的先祖身邊了，我必須把眼光放在活著的人身上。\n\n我的兄弟柯爾帶領我們的一群斥候，往西深入叢林。\n\n跟上他，並儘可能地協助他。我們會儘快加入你們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "刺藤墜盒刺藤頸飾刺藤項鍊刺藤墜飾刺藤護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][30465] = {title = "繼續攻擊", objective = "到喀撒朗蠻荒的哨兵營地找賴奧莉亞，與她交談。", description = "哈!所以父親為了一個徒勞無功的任務浪費了我們二十年光陰!\n\n現在由我來負責了。\n\n當泰蘭妲派我們出來時說得很明確，沒找到她在預言中看見的聖光源頭，就不要回去。很明顯，青春之泉並不是聖光的源頭。\n\n我希望你去尋找我的斥候。我派她去調查紅鶴寺，但她還沒有回來。\n\n取得她的報告，並到西邊遠處的哨兵營地和我們碰頭。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30466] = {title = "動機充分", objective = "鞭策10名懶猴人。", description = "訓練這些蠻人不是件容易的工作，<name>。\n\n幫他們找到動機倒不困難，困難的是讓他們為了這項動機不斷努力…並且保持專注…還有清醒。\n\n既然你回來了，可以幫我去鞭策那些沒有紀律的猴人嗎。方法就隨你便。", progress = "猴人準備好參與部署了嗎？", completion = "唔。能讓這些生物保持專注配合戰略，我就已經很驚訝了，&lt;name&gt;。\n\n等開始戰鬥時，他們最好別擋路！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30467] = {title = "我的兒子...", objective = "在墨鰓湖找到吳平。", description = "你能去找我兒子嗎？\n\n當錦魚人攻擊時，他在混亂中逃走了。我不知道錦魚人有沒有對他作什麼，甚至不知道他是不是還活著。\n\n若找不到他，什麼都沒意義了。\n\n我拜託過梅…但她看起來不太對勁。在攻擊事件之後，她似乎變得…太過衝動，我無法信任她能平安把我兒子帶回來。", progress = nil, completion = "太可怕了…當我看到殺戮的情況，我只能逃跑。我父親…梅…他們還活著嗎？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30468] = {title = "轉怒為恨", objective = "殺死15隻暴怒的錦魚人。", description = "<女劍聖看起來不太舒服。在她眼中有種不符合熊貓人個性的黑暗。>\n\n我覺得自己不曾這麼…憤怒過。多麼卑劣的背叛！\n\n我在他們進攻時打退了他們，在這殺了幾個，但商人阿席那個懦夫沒有膽子讓我過去將他們斬草除根！\n\n你，替我完成這工作。殺了他們。殺光他們。", progress = nil, completion = "聽到我們敵人死亡的消息令人欣慰。也許你可以使用我一名鑣師的武器。", rewards = "墨鰓之刃保鏢長戟女劍聖巨劍女劍聖之刃保鏢步槍小美之刃華麗釘錘保鏢匕首隱關鉤刺您會收到：\n\n"}
MultiLanguageQuestData['tw'][30469] = {title = "奪回所有權", objective = "蒐集8件遭竊的補給品。", description = "當然，眼前最重要的事情是找到我兒子。但是，若我們平安無事的結果是得餓肚子，這樣又有什麼意義呢？\n\n拜託你了，去取回錦魚人從我們車隊那裡奪走的一些物資。", progress = "如果能有塊美味的炭烤虎排，要我捨棄什麼都可以。有時候我覺得我們能吃的好像只有魚，魚，魚，還有更多的魚。", completion = "你不知道你幫了多大的忙。現在我有時間做其他的雜事了。\n\n前提是『女劍聖』梅沒有再派給我更多的其他雜事。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30470] = {title = "給蒂娜的禮物", objective = "取得1顆未切割的金綠玉。", description = "蒂娜‧泥爪今天在半丘市集拜訪她的姊妹。她人真的很好，但送禮物給她真的好難!\n\n在北方的峭壁處可以找到一種小珠寶。我們叫它做金綠玉，當你拿在手上的時候它會改變色澤。我打賭她一定沒有這樣的東西!\n\n去兔妖洞穴裡面看看。你一定馬上就能找到。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30471] = {title = "給奇奇的禮物", objective = "取得1份正宗峽谷快炒。", description = "那個瘋瘋癲癲的奇奇其實還不壞。老媽常說，猴人只會給人添麻煩，不過...我想他算是猴人裡面比較好的吧。\n\n我們應該要對他表示一下善意!西邊山上的猴人會做相當不賴的快炒，並且常會在他們的小猴人房子裡留下一碗炒好的。\n\n如果你去為奇奇弄來一份，他一定會很感激的。", progress = "嗯?", completion = "給我?給奇奇?\n\n這讓奇奇感覺回到了還是小嬰兒的時候。以前奇奇的媽媽總是會做像這樣的料理給我。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30472] = {title = "給阿秀的禮物", objective = "取得1碗魚蘋湯。", description = "住在山上的那個名叫阿秀的女孩，今天來到了鎮上。我看到她往半丘市集走了。\n\n她走了好長的路...現在一定很餓!我知道有樣東西她一定會喜歡。\n\n住在擎天嶺上的猴人都會用鮮魚和蘋果來煮湯。我知道這聽起來很噁心...不過很美味。你可以在他們的又大又恐怖的圖騰附近找到那種湯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30473] = {title = "給小魚的禮物", objective = "到崑真猴人的營帳內取得1個犛牛雕像。", description = "那個小魚‧跌蘆是個奇怪的女孩。首先，她的名字叫做小魚。這就是第一個奇怪的點。\n\n其實若跟她講過話，她可是個很好相處的女孩。比如說，你知道她非常喜歡小動物嗎?\n\n我有個點子了!住在西邊山上的崑真猴人，他們會雕刻一些動物雕像來嚇唬敵人。我敢說，小魚肯定會很喜歡這種東西的!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30474] = {title = "給艾拉的禮物", objective = "取得香辣鮮蝦蒸餃。", description = "那個可憐的艾拉，她太害羞了!我看到她站在半丘市集，餓著肚子，卻不敢跟任何一個廚子說話。\n\n我們應該給她送點食物!而且不是普通的餐點，要特別的。\n\n崑真猴人用在我們農地偷得的食材，做了一些香辣鮮蝦蒸餃。我不喜歡吃辣，但艾拉應該會!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30475] = {title = "給老豐的禮物", objective = "從巨型平原隼身上取下血淋淋的平原隼腿，帶去半丘市集交給柯‧鐵爪。", description = "農夫老豐脾氣有點壞，也有點可怕。但老媽總是說他是峽谷裡最好的農夫之一。\n\n我想我知道什麼樣的禮物最適合這種脾氣壞又可怕的人。\n\n有一些巨大的平原隼在此地西邊的山丘上空盤旋。你去獵個一隻，取出一大塊肉，然後請柯‧鐵爪幫忙烤一烤!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30476] = {title = "給老丘爪的禮物", objective = "找到1顆藍色淡水珍珠。", description = "老丘爪的田裡有上百隻雞...不過他真正的愛好卻不是這個。\n\n我發現他喜歡收集藍色的羽毛。\n\n我不太知道附近哪裡有這種藍色羽毛，但我知道某個地方有一種藍色的珍珠!\n\n去西北方香蒲湖裡的牡蠣身上找找，我相信這種藍色珍珠會很搭他的羽毛收藏!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30477] = {title = "給好漢的禮物", objective = "取得1顆巨大的香蒲石斑魚牙齒。", description = "好漢‧泥爪是耕者工會的領袖，也是這個峽谷裡最富有的人!他好心讓我能留在這裡，我也想對他做點好事。\n\n他喜歡昂貴的東西，比如紅寶石裂片，但我沒有那麼多錢，所以我得給他準備其他東西。\n\n我知道了!我在香蒲湖看過一種很巨大的魚!我們應該送他一顆這種魚的牙齒來當禮物!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30478] = {title = "給酒骨的禮物", objective = "取得8顆尹的蘋果以及50顆尹的鶴紅苺，然後帶去給波波‧鐵爪請他釀造蘋莓酒。", description = "有時候我會為酒骨感到難過。他是這附近唯一的錦魚人，顯然他身邊沒多少朋友。當然，除了他臭烘烘的酒瓶以外。\n\n你知道嗎?我有個點子。農夫尹的房子裡有一籃鶴紅苺，還有一些蘋果。我希望你能把這些水果帶去給半丘市集的一位蒸餾大師，請他為酒骨釀造一些特別的飲料。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30479] = {title = "給吉娜的禮物", objective = "取得金火蘭。", description = "你見過吉娜‧泥爪吧?市集裡的那個女孩?她擁有一切的好特質，漂亮、有頭腦，又有個完美的大肚子。你介意幫我送個禮物給她嗎?\n\n我想過爬上西邊的高大山丘頂上去摘下長在那兒的漂亮蘭花，不過我根本不可能爬那麼高。你可以摘一些去送給吉娜嗎?\n\n喔，然後當你遇到她的時候...幫我跟她說聲「妳好」。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30480] = {title = "儀式", objective = "與水語者郭萊交談並完成儀式。", description = "自我第一次從河中站起的那一刻，我就知道自己注定成為一個水語者。\n\n我學習許多儀式，每一種都使用過…除了其中一個。\n\n那是一種非常古老的儀式。我們受到囑咐，只有在人民反過來對付我們時才能執行。\n\n想必這曾發生在我們古老的歷史中。因為以往在這座村莊，並沒有使用這種儀式的必要。\n\n我想是執行儀式的時候了。", progress = nil, completion = "我懂了。無論是什麼控制了這些生物的心靈，這個儀式會一概將其撕裂。現在我知道該怎麼做了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30481] = {title = "刻入石中", objective = "收集12颗郭莱符文石。", description = "看到墙上那些闪光的石头了吗？鲁克想要一些。魔古族也在收集这些石头，所以他们身上可能也带着一些。\n\n如果你找到这样的石头，请你带来给鲁克，好吗？鲁克会跟你交朋友的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30483] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30484] = {title = "衡量進度", objective = "找影王卡玲、理弗特‧窩爆、修基雅和瑞可確認情況。", description = "開戰的時刻迫在眉睫，<name>!\n\n你離開之後，我們就日以繼夜地訓練這些原住民，我相信他們已經達到他們的巔峰了。\n\n去親眼看看吧。跟其他人確認一下，將你的發現帶回來給我。\n\n我們只能期望我們的對手在比較之下...準備得更不充分。", progress = "我們的戰鬥訓練情況如何？", completion = "至少他們很有自信。\n\n那應該有點用。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30485] = {title = "最終線索", objective = "在蟠龍之望上的洲家祖廟使用阿洲的傳家寶。\n\n和米什談話來進行移動。", description = "猴人的舉動很不尋常，<name>。組成戰陣前進？身穿盔甲？\n\n這讓我感到困擾。但我們得改天討論了。我是來這裡請求你幫助的。\n\n我們上次談話處的壁畫就快現出全貌了。我敢說，在那畫裡蘊含著古老的智慧。皇帝希望我們記住的知識。\n\n我的冥想可能無法找出其中的意涵。請將這個帶去我祖先的祠堂，我要向他們尋求援助。", progress = nil, completion = "&lt;博學行者阿洲不由自主地顫抖著。&gt;\n\n傳說…是真的！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30486] = {title = "青龙定相地形追踪", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30487] = {title = "到山上去", objective = "護送推車和嚮導平安抵達奈佛勒斯山脈。", description = "山上的小徑非常危險。你要運氣很好才能活下來。彎釘侄兒會告訴你該怎麼走。\n\n或許今天是個旅行的好日子。風從東邊來，這是好兆頭。咕嚕摩總是在東風吹起時啟程。\n\n你準備好要離開時就上車吧。", progress = nil, completion = "你來得正好，&lt;class&gt;!我還以為我要死在這裡了!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30488] = {title = "失蹤的麝爪", objective = "到頑童洞穴找麝爪二世。", description = "你到底是個什麼鬼？|5<class>？從沒聽過這種玩意。你是來這裡幫忙還是來偷我的犛牛？\n\n聽著，如果你堅持要幫忙，就去找我兒子。他被一群妖精抓走了，可能連我們失去牧場了都不知道。\n\n那些妖精把他拖到東南方的頑童洞穴去了。去把他救出來，我再看看要如何獎賞你。", progress = nil, completion = "謝謝你的援救，陌生人!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30489] = {title = "新鮮的靈針香氣", objective = "收集100支刺鼻的靈針。", description = "如果你真的是來幫忙的，我需要一些頑童洞穴裡妖精身上的針。\n\n咕嚕摩嗅不到味道就不相信有好運，他們會願意為擁有新鮮靈針香氣的犛牛付更好的價錢。", progress = "嗯，沒有什麼東西比得上新鮮靈針的香氣了。", completion = "你讓我大賺了一筆。抓取那些靈針會讓手掌很痛，但當我們帶著犛牛到市場上時，這點痛都是很值得的。拿去吧，為了你所遇到的麻煩。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30491] = {title = "清洗場", objective = "帶6隻逃脫的犛牛到勞記犛牛清洗場的清洗口。", description = "聽著，我的父親瘋了。我愛他，但是他瘋了。\n\n這些揚古徹底摧毀了我們的牧場，害得我們的犛牛四處逃竄。\n\n依我對父親的瞭解，他會直接衝去找那些揚古要回我們的犛牛。\n\n你可以幫我們找回一些犛牛，以免我父親跑去做出蠢事嗎？\n\n你只要騎上牠們回到清洗場，我們就會把牠們清理乾淨然後賣給那些咕嚕摩。", progress = nil, completion = "做得好，陌生人!希望我們可以賣了這些傢伙以彌補一些揚古造成的破壞。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30492] = {title = "回到犛牛生意", objective = "帶打理乾淨的犛牛到崑萊峰的咕嚕摩市集給好運八錢。如果你搞丟了你的犛牛，回去找麝爪二世。", description = "關於獎賞的事我可沒有騙你。來吧，帶著這些犛牛去找咕嚕摩商隊隊長八錢。你可以在西邊的咕嚕摩市集找到他，他會記在我們的帳上並付給你一筆運費的。\n\n他個子也許長得很矮，但卻是我們最大的客戶。\n\n如果你搞丟了犛牛，就回到我這裡。每當牠們被打理乾淨了，牠們常常會自己跑回來這個地方。", progress = nil, completion = "啊!我大老遠就可以聞到幸運的味道。麝爪總是有最好的犛牛可買賣。", rewards = "您能選擇下列奬勵中的一個：\n\n祝福硬幣機緣硬幣運氣硬幣好運硬幣幸運星硬幣\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30495] = {title = "愛情奴隸", objective = "將玉送去給歷史學家甸、勘測員沙瓦、『風箏大師』修苦和監工艾米。", description = "我能請你幫另外一個忙嗎？\n\n我們的進度已經大幅落後，這些是我們完成大雕像所需的最後一批玉礦。\n\n我實在是太忙了，你可以把這些礦送去給其他工頭嗎？\n\n歷史學家甸、勘測員沙瓦和『風箏大師』修苦都在雕像底部一帶。監工艾米則在雕像頂端監督生產。\n\n我們正在追趕期限，所以千萬要快！不要浪費時間！", progress = nil, completion = "什麼，已經送到了？你可真是個飛毛腿，&lt;class&gt;。你想過拿這當生計沒有？", rewards = "您能選擇下列奬勵中的一個：\n\n歌唱蟋蟀勳章樹林響尾蛇勳章珊瑚奎蛇勳章焰酒勳章琥珀飛蠅塑像\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30496] = {title = "水語者的法杖", objective = "從墨鰓湖的歐拉奇身上，取回水語者郭萊遭竊的墨鰓儀式法杖。", description = "在墨鰓湖的村民之間有著嚴重的爭議，<race>。長者夏虎喝下了被煞污染的水，並強迫其他人做同樣的事。當我拒絕時，城鎮守衛歐拉奇便奪走我的儀式法杖，並將我放逐。\n\n現在，我不僅遭到流放，甚至沒辦法和水交談！\n\n我不是個戰士，但如果你是，或許你能從歐拉奇那裡取回我的東西？他就在北邊的城鎮裡。", progress = "你找到法杖了嗎？", completion = "很好。現在我們有希望挽救這個情況。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30498] = {title = "快回來!", objective = "到珠鰭村找泰勒上將。\n\n已提供物品：\n", description = "喔，為免忘記，有人要我把這東西交給你。我想是你同伴的來信。\n\n據我所知，他們亟需你過去幫忙，所以我會負責安排你過去。\n\n準備好時，到南邊去找金莎‧箭眼。她會準備好風箏等妳。", progress = nil, completion = "歡迎回來，&lt;name&gt;。相信你在這趟旅程中得到很多收穫，尤其是在地形分布的層面。我們在開戰前還有很多事要做。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30499] = {title = "快回來!", objective = "到葛魯山丘找納茲格寧姆將軍。\n\n已提供物品：\n", description = "喔，為免忘記，有人要我把這東西交給你。我想是你同伴的來信。\n\n據我所知，他們亟需你過去幫忙，所以我會負責安排你過去。\n\n準備好時，到南邊去找金莎‧箭眼。她會準備好風箏等妳。", progress = nil, completion = "歡迎，&lt;name&gt;!\n\n希望你在穿越森林時，順便收集到能派上用場的情報。\n\n我們的準備差不多完成了，不過還是需要你的幫助。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30500] = {title = "異塵餘生", objective = "殺死10隻煞的回音。", description = "潘達利亞是片神秘的土地，旅人。\n\n就算對博學行者來說，也始終埋藏著許多秘密。\n\n封閉裂縫並無法修補已經損毀的東西。\n\n若傳說屬實，要將土地從煞的侵襲中解放出來，還需要更多努力。\n\n那場戰爭的侵略性喚醒了一個活生生負面情緒的宿主。你在這裡見到的，恐怕只是多場動亂的其中之一。\n\n眼前，我們只能試著在這裡消滅他們。", progress = nil, completion = "這真是糟糕…\n\n我們必須找到方法回復這一切。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30501] = {title = "接受小道消息测试例子", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30502] = {title = "玉之心", objective = "使用天國翠玉來擊敗6個煞的殘渣。", description = "更強大的煞或許就不是你能獨自對付的了，<name>。\n\n我在實際戰鬥中恐怕發揮不了什麼幫助，但我能提供一個解決方案。\n\n那座巨大的玉像很快就要化為真正的蛟龍。它的結構賦予它特殊的力量，或許能大幅弱化你這些敵人。", progress = nil, completion = "&lt;阿洲喪氣地看著你。&gt;\n\n這些玉本來有那麼大的用處...", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30504] = {title = "緊急回應", objective = "在納茲格寧姆將軍、影王卡玲、修基雅和理弗特‧窩爆附近使用阿洲的煙火。", description = "你的同伴們就在我們土地上待下來了，還帶來危險的衝突。\n\n我們想像不出他們會在這裡帶來多大的毀滅。此刻的傷害，就已經…無法言喻。\n\n無論如何，因蔑視而拋棄你的朋友不符合我們的處世之道。還活著的人肯定受傷、絕望，急切需要照護。\n\n這些煙火本來是用來慶祝雕像完工的。在你夥伴周圍使用它來通知米什，她會將他們搬運到安全的地方。", progress = nil, completion = "我會照料你的同伴們，&lt;name&gt;。\n\n希望他們的傷很快就能回復。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30506] = {title = "泰勒上將甦醒", objective = "到崑萊峰的濱南村找泰勒上將。", description = "看來泰勒上將已從傷勢中甦醒。他和他的人馬在濱南村藥劑師家樓上。\n\n他要你過去。", progress = nil, completion = "&lt;name&gt;，是你嗎？我不敢相信我們在玉蛟的攻擊下死裡逃生了。\n\n儘管只有一部份人。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30507] = {title = "泰勒上將甦醒", objective = "到崑萊峰的濱南村找泰勒上將。", description = "看來泰勒上將已從傷勢中甦醒。他和他的人馬在對面的藥劑師家樓上。\n\n他要你過去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30508] = {title = "泰勒上將甦醒", objective = "到崑萊峰的濱南村找泰勒上將。", description = "看來泰勒上將已從傷勢中甦醒。他和他的人馬在樓上。\n\n他要你過去。", progress = nil, completion = "&lt;name&gt;，是你嗎？我不敢相信我們在玉蛟的攻擊下死裡逃生了。\n\n儘管只有一部份人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30509] = {title = "納茲格寧姆將軍甦醒", objective = "到崑萊峰的濱南村找納茲格寧姆將軍。", description = "看來納茲格寧姆將軍已從傷勢中甦醒。他和他的人馬在濱南村藥劑師家樓上。\n\n他要你過去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30510] = {title = "納茲格寧姆將軍甦醒", objective = "到崑萊峰的濱南村找納茲格寧姆將軍。", description = "看來納茲格寧姆將軍已從傷勢中甦醒。他和他的人馬在對面藥劑師家樓上。\n\n他要你過去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30511] = {title = "納茲格寧姆將軍甦醒", objective = "到崑萊峰的濱南村找納茲格寧姆將軍。", description = "看來納茲格寧姆將軍已從傷勢中甦醒。他和他的人馬在樓上。\n\n他要你過去。", progress = nil, completion = "你跑去哪了，&lt;name&gt;？算了。如你所見，我們從玉蛟一戰中存活下來了。\n\n不幸的是…他們也是。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30512] = {title = "西風之眠", objective = "到揚古先遣營地找雇農阿波和長者楚嵐。", description = "<泰勒上將痛得縮成一團。>\n\n翠玉林是一場災難。安杜因不見了，許多好人在這裡喪生。我們甚至無法阻止部落深入大陸。\n\n好消息是，我可能找到了讓當地人站在我們這邊的方法。\n\n你剛幫他們擊退了一些「揚古」，對嗎?\n\n我聽說揚古掠奪了當地一個名叫西風之眠的村莊。據說有兩隊倖存者在鎮外西邊的路上紮了營。\n\n如果我們幫助他們，或許他們會考慮加入聯盟。", progress = nil, completion = "嗯...我們還活著，若沒有你的協助，我們連活著的可能性都沒有。\n\n但，如果這裡真的要成為你行動的根據地，而且我們真的要加入你的聯盟的話，你還必須做一件事來保障我們的安全。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30513] = {title = "東風之眠", objective = "到崑萊峰找雇農阿郭和蕭長老。", description = "我受傷了，但我們不能停在這兒。\n\n猴人是…不可靠的。熊貓人會是更好的盟友。\n\n我很確定你已看到這個村莊的難民，也聽說了揚古的侵略？\n\n總之，我們聽說附近一個村莊，東風之眠，遭到揚古摧毀了。\n\n顯然有部分倖存者聚集在城鎮的路旁。沿著路往西走，集結這些倖存者。\n\n我們將幫助他們重建。到時候，他們會看見加入部落的好處！", progress = nil, completion = "嗯…我們還活著，若沒有你的協助，我們連活著的可能性都沒有。\n\n但，如果這裡真的要成為你行動的根據地，而且我們真的要加入你的部落的話，你還必須做一件事來保障我們的安全。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30514] = {title = "接受挑戰", objective = "燒掉揚古旌旗以召喚烏巴塔，並在戰鬥中擊敗他。", description = "揚古一直都是頑固、驕傲的民族，但從來不會這麼暴力或具侵略性。\n\n我不知道是什麼改變了他們的行為模式，但現在，我們沒時間把事情搞清楚了。只要巴塔利揚古的首領烏巴塔還活著，我們就得擔憂自己的性命與生計。\n\n去吧，到他的營地，燒掉旗幟向他挑戰，然後在戰鬥中擊敗他。唯有如此我們才能安心。", progress = nil, completion = "你辦到了!最後的最後，儘管在過程中失去了許多東西，我們終於得到正義與安全。\n\n無論如何，事情已經決定了。我們將加入聯盟，並在你的協助下重建村莊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30515] = {title = "接受挑戰", objective = "燒掉巴塔火焰營地中的揚古旌旗以召喚烏巴塔，然後在戰鬥中擊敗他。", description = "揚古一直都是頑固、驕傲的民族，但從來不會這麼暴力或具侵略性。\n\n我不知道是什麼改變了他們的行為模式，但現在，我們沒時間把事情搞清楚了。只要巴塔利揚古的首領烏巴塔還活著，我們就會擔憂自己的性命與生計。\n\n去吧，到他的營地，燒掉旗幟向他挑戰，然後在戰鬥中擊敗他。唯有如此我們才能安心。", progress = nil, completion = "你辦到了!最後的最後，儘管在過程中失去了許多東西，我們終於得到正義與安全。\n\n無論如何，事情已經決定了。我們將加入部落，並在你的協助下重建村莊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30516] = {title = "拓展農地I:小麻煩", objective = "幫凱藍收集6份蛛根。", description = "你想要除掉一些狡猾的雜草是吧？\n\n沒問題，好鄰居！只是，我的除草劑用完了。\n\n我的自製藥劑效力特強，完全有機，對土地無害。植物都愛死它！好吧…除了那些討厭的雜草！它們一定恨死這玩意兒了！\n\n如果你幫我到西邊的梯田那裡弄來一些蛛根，我就可以製作一批新藥劑，然後親自到尹的農場裡除草。\n\n我是可以自己去收集…不過…我討厭蜘蛛。你會懂的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30517] = {title = "農夫老豐的一票I:犛牛攻擊", objective = "到四風峽的中央平原或半丘市集找農夫老豐。", description = "耕者工會裡下個有投票權力的人就是農夫老豐，原因顯而易見。\n\n他可以種出全峽谷最大的蔬菜！我只希望有一天我的南瓜可以跟他種出來的一樣大。\n\n如果我們想加入工會，他就是我們下一個要說服的對象。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30518] = {title = "農夫老豐的一票II:脫韁野牛", objective = "將5頭逃脫的粗皮帶到蒼翠牧場的北端，送回農夫老豐的犛牛獸欄裡。", description = "你要我投票給農夫尹？哈！你一定是在開玩笑對吧？\n\n聽著，我才不會投票給一個完全不懂耕作的紈褲子弟。\n\n在你或那個叫尹的垃圾附近種田可是會把我的臉給丟光的。\n\n現在，請你離開。不知道哪來的惡魔把我珍貴的犛牛放出欄圈，現在牠們就在半丘的西北邊放肆地跑來跑去。\n\n若能找回我的牛兒，今晚也許就能好好入睡了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30519] = {title = "娜娜的一票I:娜娜‧泥爪的秘密配方", objective = "到四風峽的半丘找娜娜‧泥爪。", description = "我們需要拉攏的下一個對象是娜娜‧泥爪。她是好漢的祖母，成為耕者的時間比你和我活過的時間還要長！\n\n她還在半丘的耕者建築裡工作。過去拜訪她一趟，如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30521] = {title = "好漢的一票I:小屋入侵案", objective = "到四風峽的中央平原或半丘市集找好漢‧泥爪。", description = "接下來會很困難，<name>。\n\n我們需要的最後一票屬於好漢‧泥爪，耕者工會的領袖。\n\n我知道他對我們一向沒什麼好感，不過我們已經學到這麼多農耕技術了，相信我們可以改變他的心意！\n\n去和他談談。你可是很有說服力的，對吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30522] = {title = "好漢的一票II:真正的犯人", objective = "調查8個可疑的足跡。", description = "你在這裡做什麼，都市佬？\n\n聽著，我已經為了我西邊那座棚子被闖空門的事忙得不可開交。有一群匪徒趁半夜跑來洗劫了這個地方。\n\n我的種子沒了、工具壞了，還得處理被吃掉的存糧。\n\n我可以把這加到我的問題列表裡：一整車被偷的甜瓜，壞掉的抽水幫浦，糟蹋我收成的動物…\n\n我真希望我能搞清楚這一切是怎麼回事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30523] = {title = "拓展農地II:壞掉的貨車", objective = "到四風峽的半丘市集或香蒲湖找小魚‧跌蘆談話。", description = "嘿，<name>。打從搬進來時開始，我就每天盯著那輛貨車看，每天每天的看。不覺得它真是很礙眼嗎？\n\n我聽說鎮上有一個叫做小魚‧跌蘆的人對工具很在行。她應該可以幫我們修好它，然後我們就能把那一小塊土地拿來耕作了。\n\n何不去和她談談，看看她是否願意幫助我們呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30524] = {title = "拓展農地II:敲木頭", objective = "收集100份蠟板。", description = "當然！我知道你說的那輛馬車！\n\n我可以把它修好，不過我需要木頭。\n\n在這片湖底有很多的木頭可用。如果你能跟魚一樣潛下去的話，哈哈，明白嗎？魚？喔，我只是偶而會自嘲一下罷了。\n\n反正，只要你幫我弄來一些木頭，我就可以開始工作！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30525] = {title = "好漢的一票III:天下至毒", objective = "收集1份血綻花、1份洞穴百合、1份鬼靈菇以及1份紫地衣。", description = "好了，<name>。這是我們的大機會!\n\n泥爪先生的農場有大麻煩。山上那些猴人會趁晚上跑下山來，破壞他的作物，吃掉他辛苦耕種的收成。\n\n我們得一勞永逸地擺脫掉他們。\n\n以前，我祖母曾教我如何混合出致命毒藥來料理農場上的害蟲。\n\n北方的兔妖聚落有我所需要的關鍵原料。\n\n別愁眉苦臉的，<name>!我敢確定這個計畫一定可行的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30526] = {title = "走丟的孤犬", objective = "從四風峽擎天嶺上的擎天嶺牡山獸身上收集20份美味丁骨。", description = "這隻餓壞又骯髒的狗發出可憐的哼鳴，並試著搖了一下尾巴。\n\n看來牠急需一頓豐盛的美食。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30527] = {title = "好漢的一票IV:偷瓜重罪", objective = "種植並採收4批條紋甜瓜，然後將20顆條紋甜瓜送去給農夫尹。\n\n條紋甜瓜種子可以在半丘市集的商人青田那裡買到。耕種並照料過你的植物後，你必須等到隔天才能採收長成的條紋甜瓜。", description = "好，我正好知道山上的猴人喜歡吃一種美味的甜瓜。\n\n泥爪先生最新一批的甜瓜收成被偷走了，所以我們得自己種一些出來。\n\n採收之後，我們就能利用它們來將那個可惡的猴人領袖給引誘出來!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30528] = {title = "好漢的一票V:葉葉酋長", objective = "到西北方的崑真洞殺死酋長葉葉。", description = "你準備好執行計畫的最後一步了嗎？\n\n住在崑真村的猴人們聽命於一個兇猛的酋長，他叫做葉葉。據說他非常能承受傷痛。\n\n這就是我稍早要你去收集另一種原料的原因。我要在這些甜瓜裡注入我的神秘配方。\n\n基於對猴人的了解，我打賭葉葉一樣無法抵抗甜美的粉紅甜瓜，等到他一口咬下，你就有機會對他發動攻擊了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30529] = {title = "拓展農地III:生苔滾石", objective = "到四風峽的中央平原或半丘市集找好漢‧泥爪。", description = "由於我們已經是耕者工會的正式成員，泥爪先生說他很樂意幫助我們清除田地中間的大石塊。\n\n等那些石頭都被清掉以後，我打算種一些特別的東西。\n\n過去喊他一聲，讓他知道我們準備好了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
