MultiLanguageQuestData['tw'][30565] = {title = "意外的優勢", objective = "從東邊的猴人伏擊者那裡取得被搶走的被水損壞的裝置和生鏽的固定螺栓。", description = "情勢似乎開始變得對我們有利了，<name>。我在外面探索的時候，邂逅了這個「寶貝」。\n\n<蘇利指了指他右手邊的弩砲。>\n\n但她只是弩砲的其中一部份，另一半目前還未組裝起來。要不是那些討厭的嚴睨猴人襲擊我，搶走了一些零件，我早就把她整個裝設好了。\n\n嘿，你看起來很懂得怎麼料理這些土著。想必你願意去幫老蘇利這個忙吧？", progress = "你找到我缺少的裝置和螺栓了嗎？", completion = "好吧，她能配得上更好的零件，但眼前也只能將就了。\n\n&lt;蘇利拍了拍分解的弩砲。&gt;\n\n我很快就會讓她起來活蹦亂跳，你瞧著吧!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30566] = {title = "FLAG—害虫问题训练", objective = "倾听晓和他同伴们的谈话。", description = "嘿，你好。你在寻找这片地方的主人吗？那就去见见楼梯上面的那位熊猫人吧。跟你一样，我也是访客。\n\n不好意思，我跟我朋友现在要商量点事情。我们稍后再聊。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30567] = {title = "白蘭琪的轟隆酒", objective = "完成「雷電佳釀」事件。", description = "你聞得到嗎？空氣中有風暴正在醞釀的味道！而我也要來醞釀啦！\n\n風暴來襲時，到山丘頂上和我碰頭，我們要攜手釀一桶我最出名的酒。我能仰賴你嗎？\n\n", progress = nil, completion = "還不壞，我的&lt;class&gt;朋友！我們拯救了僧院，而且還有半桶酒留下來。\n\n多謝你的幫助！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30568] = {title = "一臂之力", objective = "和英勇的卡爾勒什、琥珀‧吉爾妮及密西卡打個招呼。", description = "歡迎回來，<name>!錦魚人們受訓的表現似乎比我想像中更好。我們已經進入最終準備階段。\n\n我需要有人去和琥珀、英勇的卡爾勒什及密西卡打個招呼，看看他們是否需要什麼幫助來進行結訓。\n\n你會在珠鰭村找到卡爾勒什和密西卡。琥珀則在西北邊的彈尾坑訓練那些新兵。", progress = nil, completion = "令人讚嘆的成果，&lt;name&gt;。我們很快就能準備好出發了。有這群盟友在身邊，我們絕不可能被打敗。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30569] = {title = "農莊有麻煩", objective = "到崑萊峰的周家莊找農夫老周。", description = "我…我從東南邊的農夫老周那裡逃了出來。那裡被揚古佔領了，但那老傢伙和他老婆就是不肯放棄！\n\n拜託，過去那裡幫他的忙。那樣的話，或許他會願意派些人過來這裡幫你們耕種給新城鎮的食物？", progress = nil, completion = "你真是沙漠中的綠洲，&lt;class&gt;。\n\n我很樂意幫助聯盟的朋友們。不過你得先幫我把農場討回來。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30570] = {title = "農莊有麻煩", objective = "到崑萊峰的周家莊找農夫老周。", description = "我…我從東南邊的農夫老周那裡逃了出來。那裡被揚古佔領了，但那老傢伙和他老婆就是不肯放棄！\n\n拜託，過去那裡幫他的忙…那樣的話，或許他會願意派些人過來這裡幫你們耕種給新城鎮的食物？", progress = nil, completion = "你真是沙漠中的綠洲，&lt;class&gt;。\n\n我很樂意幫助部落的朋友們。不過你得先幫我把農場討回來。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30571] = {title = "雇農的自由", objective = "殺死歐朵監督者，釋放12名被奴役的僱農。", description = "歐朵揚古會把我的雇農奴役到死!這樣不對。\n\n求求你，<class>，在事態變得不能挽回前拯救他們吧。", progress = nil, completion = "你果然是我們需要的人!\n\n不過，我想強迫這些工人留下來並不公平，因為我們沒有那麼多工作給他們...", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30573] = {title = "追踪事件：开始第三步扩张", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30574] = {title = "追踪事件：完成第三步扩张", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30575] = {title = "圈趕回來", objective = "圈趕3隻野生原犛牛回到西風之眠。", description = "機動性是我們在這新土地上站穩腳跟的關鍵。問題是，少了坐騎，我們沒有辦法維持機動性，而且…我們本來就沒有多少機動性了，對吧？\n\n當地的犛牛似乎是不錯的坐騎。至少當地的熊貓人這樣說。你何不幫我們圈趕一些回來？", progress = nil, completion = "這些犛牛很夠用了。做得好，&lt;name&gt;。我感覺狀況已經變樂觀了。", rewards = "卡法緞質披肩卡法皮肩甲夢境之靈護肩卡法光潔肩甲卡法絲質襯肩卡法皮甲肩甲犛牛牧人護肩卡法重型護肩卡法裝甲護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][30581] = {title = "...還有鍋子啊!", objective = "收集12株根莖類蔬菜及1只鑄鐵鍋。", description = "當然，我很願意幫忙你們。但我們也得吃東西!我連煮東西的鍋子都沒有!更別提要放進鍋子裡的食材了!\n\n這張清單上列了我需要的所有東西。去幫我帶回來!", progress = "清單上的東西都到手了嗎？！", completion = "幹得好。這樣我們應該沒問題了。", rewards = "您會收到：\n\n菜根湯恆龍寶箱"}
MultiLanguageQuestData['tw'][30582] = {title = "已故的麝爪太太", objective = "把麝爪的紀念品帶去給勞‧麝爪。", description = "這件被人長期穿戴過的小飾品上有幾個記號，表現出已故的麝爪太太的愛與崇拜。\n\n或許勞會很高興拿回太太的飾品。", progress = "喔，什麼風把你吹來了。", completion = "你永遠不知道能夠失去多少，直到有一天真的失去了。我太太過世好幾個季節了，但我可以告訴你，這是我最需要她溫暖微笑的一天。\n\n至少她不用看到這些揚古對她熱愛的牧場所做的事。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30583] = {title = "燉肉需要肉!", objective = "收集160份崑萊肉塊。", description = "喂!\n\n我們需要你幫忙弄些食物，否則我們在這活不了多久!\n\n你或許不知道，但我可是個廚師。你何不出去弄些肉回來。我會料理他們，讓我們好幾個禮拜不愁餓肚子!或者，至少好幾天啦。", progress = "嗯…有肉嗎？", completion = "做得好!告訴你，這些崑萊肉會讓神都讚不絕口!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30584] = {title = "令人吃驚!", objective = "到喀撒朗蠻荒的朵迦河去釣7隻朵迦鰻。", description = "<name>，你吃過新鮮的朵迦鰻嗎?沒有?\n\n那你算是白活了!到北邊的朵迦河去幫我們釣幾隻來吧。小心點，否則那些鰻魚可是能要了你的小命!", progress = "你有抓到那種鰻魚嗎?", completion = "&lt;name&gt;，這些鰻魚看起來很美味!我肯定你一定會愛死牠們!", rewards = "您會收到：\n\n\n\n等級 35–80香脆朵迦鰻\n\n等級 20–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30585] = {title = "潛伏者", objective = "到西北方的喀撒朗瀑布找上古釣魚池，並在池中釣魚，把隱藏其中的野獸引誘出來。", description = "傳說在北邊森林裡有隻巨大的野獸。我兒子失蹤了，我怕他可能是在閒晃時太接近牠的巢穴...\n\n往西北邊走，到喀撒朗瀑布尋找一個神秘的漩渦。這漩渦就是揭露那裡所藏匿生物的關鍵。殺死那隻卑劣的野獸，尋找任何與我兒子有關的線索。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30586] = {title = "鋸齒鮑魚", objective = "到東北邊的納松海溝，從鋸齒鮑魚身上取得9塊鋸齒鮑魚肉。", description = "熊貓人在這個區域採收鋸齒鮑魚有好幾個世代了。現在該是你學習這個儀式的時候。\n\n你可以在西邊的納松海溝找到這種鮑魚。小心，我們注意到最近那個區域的鯊魚數量有增加的現象。", progress = "有遇到任何鯊魚嗎?", completion = "喔!看來你可是找到不少鮑魚。幹得好啊，&lt;name&gt;!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30587] = {title = "牛話連篇", objective = "到麝爪牧場去殺死9隻波力吉掠奪者。", description = "到目前為止，這些揚古入侵者似乎只偷些犛牛就滿足了。但若仔細觀察區域，你會發現他們隨時都可以輕易侵入清洗場。\n\n削弱他們的數量，或許足以讓他們知道這個區域是有人保護著的。", progress = nil, completion = "好吧，我非常感謝你讓那些揚古吃了一點教訓。\n\n希望你的略施小戒足以讓他們學會再也不要跑來這裡。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30588] = {title = "拯救捕魚隊", objective = "到釣手泊船處西邊的釣手遠征隊殺死8個川刃河岸劫掠者。", description = "川刃薩烏洛克族正在攻擊我們當地的一個捕魚隊!他們現在就需要幫助!\n\n削減那些薩烏洛克的數量並幫助捕魚隊平安回來!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30589] = {title = "毀壞殘骸", objective = "到培武林找麥靠‧貝。", description = "要弄走那艘聯盟船艦，必須先找到我們的工程師。我們從船難中逃生的時候走散了。\n\n你應該能在森林西側的某處找到他。告訴他是闊卡派你來的，他就會幫助你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30590] = {title = "小心處置", objective = "取得6份裝滿的炸藥。", description = "我們正在嘗試從聯盟那邊拿回炸藥。只要能拿到更多炸藥，我們就能幫忙弄走你的船。\n\n在逃跑前，我命令手下盡力帶走最多的火藥。如果你翻找一下我們南方的那些殘骸與屍首，應該能在其中找到更多的炸藥，總之就是還沒爆炸的那些啦。\n\n給我找來足夠的炸藥，我想我能給你做個好東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30591] = {title = "補獵掠食者", objective = "殺死9隻培武虎。", description = "神真子的晃動開始之後，森林變得遠比以往危險。老虎變得暴躁，開始攻擊難民們;偶爾，甚至會來攻擊我。\n\n我們得幫忙清除森林中的危險，這些負傷又虛弱的生還者才有安全抵達小屋的機會。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30592] = {title = "粗麻小徑:前往粗麻小站", objective = "護送一群咕嚕摩前往粗麻小站。至少得讓一名咕嚕摩存活下來。\n\n如果你失去了你的咕嚕摩，你可以搜尋粗麻小徑，或是回到獨罈集等待下一群離開。", description = "今天對咕嚕摩來說真是倒楣的一天。猴人開始搶劫了！他們攻擊了我們在蟠龍脊的補給線。\n\n你願意幫忙嗎？我們不是戰士。我們是咕嚕摩。幫助咕嚕摩的人都會獲得好運。\n\n帶群咕嚕摩前往粗麻小站。保護他們的安全。至少得讓一名咕嚕摩存活下來。\n\n咕嚕摩會報答你的。咕嚕摩總是會報答你的。", progress = nil, completion = "太感謝你了，並祝你好運，咕嚕摩的朋友。不過前往蟠龍脊的旅途仍然充滿著危險。", rewards = "您能選擇下列奬勵中的一個：\n\n粗麻儀式袋子\n\n您還會收到：\n\n粗麻儀式袋子"}
MultiLanguageQuestData['tw'][30593] = {title = "消除活物", objective = "摧毀14具兵馬俑戰士或兵馬俑守護者。", description = "上將交代我解決這個大麻煩，可是我的專長是治療，不是戰鬥!\n\n營地裡的熊貓人告訴我，在東北方的魔古岬出了些狀況。有什麼東西在讓雕像活動起來。\n\n你會幫我忙嗎，<name>?我們現在沒有餘裕和一支雕像軍隊開戰。", progress = nil, completion = "好啦!看來我們不再需要擔心雕像的問題了。幹得好，&lt;name&gt;!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30594] = {title = "消除活物", objective = "摧毀14具兵馬俑戰士或兵馬俑守護者。", description = "我這裡有太多事情要做了，<name>。\n\n西北邊有個地方，熊貓人稱之為魔古岬。那裡好像有什麼東西讓雕像活了起來，把我們的熊貓人朋友嚇得心驚肉跳。\n\n我們得盡快解決它們，否則可能會陷入大麻煩。我們才剛進駐此地，現在可沒有餘裕和一支雕像軍隊開戰。", progress = nil, completion = "喔，你把雕像料理掉了？做得好。請收下這個吧。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30595] = {title = "古董生財", objective = "收集12個魔古聖物。", description = "讓我猜猜，你是來處理活起來的那些魔古雕像的問題，對吧？真巧真巧，我是來呃…研究魔古的。\n\n我跟你說，如果你盡可能幫我帶回夠多的魔古聖物，我就分你一份…研究資金。", progress = "這麼多聖物我是要放哪好？", completion = "哦嗚!太感謝你了，&lt;name&gt;!\n\n\n\n我在想，既然你都削減他們的數量了，或許我能自己過去，在外圍多找幾個古董寶物。不危險的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30597] = {title = "奇怪的球形岩石", objective = "用少許黃金蓮來為石頭灌注魔力。", description = "這漂亮的石頭蘊藏著魔力...至少對熟練的鍊金師來說。你肯定，經過正確的潘達利亞草藥處理，這石頭能變得很有用處。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n禪之鍊金石"}
MultiLanguageQuestData['tw'][30598] = {title = "誰知道魚喜歡吃蛋?", objective = "到納松尖塔取得新鮮的蛋，並利用它捕捉一隻銀刺鰭魚。", description = "幾個世代以來，巨鶴在這個區域築巢。納松尖塔提供他們養育幼鳥的安全環境。\n\n牠們新鮮的蛋可以用來做為捕捉銀刺鰭魚的誘餌。取回一個鶴蛋，看看你能不能抓到一隻刺鰭魚!", progress = "你有抓到銀刺鰭魚嗎?", completion = "是滑不溜手的銀刺鰭魚!&lt;name&gt;，你可真的成為一個釣手了!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30599] = {title = "猴人神像", objective = "在猴人的祭壇上使用塔克塔克，達克達克，和可可屍體。", description = "之前，我們用食物賄賂猴人讓他們不來搶劫。\n\n但現在南邊的斷齒猴人有一些大大的魔法神像。廢猴酋長烏克訓練他們對神像獻祭來獲得力量。\n\n他們在用神像殺死咕嚕摩！\n\n你得毀了這些神像！\n\n每一個神像都有一個酋長看守著。殺死猴人酋長並把他們的屍體丟到祭壇上。", progress = nil, completion = "一隻有自信的猴人會是危險的猴人。\n\n謝謝你的幫忙，咕嚕摩的朋友。", rewards = "您能選擇下列奬勵中的一個：\n\n猴人偶像\n\n您還會收到：\n\n猴人偶像恆龍寶箱"}
MultiLanguageQuestData['tw'][30600] = {title = "不留下任何一包", objective = "在斷齒營地或是斷齒深淵取回8件咕嚕摩包。", description = "南邊的斷齒猴人殺光了我的咕嚕摩。更糟的是，他們的包包都送不到了。\n\n有個使命不達的咕嚕摩包是件很不幸運的事。\n\n請幫忙讓沿路的咕嚕摩安息，並把他們的咕嚕摩包帶來給我。\n\n我會想辦法把它們送到目的地的。", progress = "咕嚕摩是很單純的種族。我們生來就是為了探險和傳遞好運的。", completion = "你真是咕嚕摩的好運。\n\n等我們回到適當的營地，我一定要幫你買個我能找到味道最重，最好運的薰香。", rewards = "您能選擇下列奬勵中的一個：\n\n咕嚕摩背包\n\n您還會收到：\n\n咕嚕摩背包"}
MultiLanguageQuestData['tw'][30601] = {title = "速食勇氣", objective = "在嚎風洞穴激勵3名躲起來的嚮導幫助你。", description = "不帶個好嚮導就在山裡的小徑上旅行，這不是幸運的事。我們咕嚕摩是很好的嚮導，但很多咕嚕摩都逃跑了。他們害怕現在的山路。有許多好咕嚕摩在山路上消失。\n\n咕嚕摩擅長做很多事，但膽子很小。或許你可以用火焰蓮花薰香讓他們變得勇敢一點。這樣他們就會願意幫你領路。", progress = nil, completion = "薰香的作用是暫時的迷惑!效力不會持續太久，所以你的動作要快!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30602] = {title = "幸運兔腳", objective = "從斷齒哨站解救兔腳兄。", description = "斷齒猴人偷走了我們的兔腳兄！他是帶著最大幸運星的咕嚕摩。\n\n這真是很不幸運。拜託了，<race>，我們需要我們的兔腳兄回來。我們需要他的好運回來。\n\n你可以到斷齒哨站去找找他嗎？", progress = nil, completion = "看看斷齒和骨捶對咕嚕摩小站做了什麼。半個幸運星都找不到了。\n\n咕嚕摩和猴人有過協議。我們給他們食物，他們不搶劫我們。每當他們想要搶劫，影潘會提醒他們不要。\n\n但所有影潘都去保護長城了。而猴人想要的食物比咕嚕摩有的還多。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30603] = {title = "斷齒蹂躪", objective = "從莫莫那裡取回兔腳兄的幸運星。", description = "他們偷了我的幸運星！他們在本地的首領，莫莫，偷走了我的幸運兔腳。\n\n這對咕嚕摩來說真是最大的不幸。我的幸運兔腳對每一處的咕嚕摩來說都是很大的幸運星。如果猴人知道怎麼從我的幸運兔腳得到幸運的話，一切就都完了。\n\n拜託，你能幫我把它弄回來嗎？", progress = "以幸運星為名的咕嚕摩能為特定的咕嚕摩帶來最大的好運。最重要的是不能讓猴人偷走了好運。", completion = "我的幸運星!喔真是開心又好運滿滿的一天!太感謝了!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30604] = {title = "斷絕斷齒", objective = "殺死8隻斷齒衝鋒者和6隻斷齒投擲者。", description = "猴人只有在他們覺得補給少於吃飯嘴巴的數量時，才會開始搶劫。\n\n問題是，猴人的嘴巴永遠多於食物。\n\n這些日子以來，咕嚕摩的數量變得很少。\n\n做這樣的要求很困難，但是你能夠當一下咕嚕摩的朋友，幫忙殺死一些斷齒猴人嗎？這是唯一可以防止他們摧毀這塊土地的方法了。", progress = nil, completion = "謝謝你，&lt;name&gt;!希望這樣可以緩和斷齒的劫掠行為。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30605] = {title = "幸運的牛蹄", objective = "解救牛蹄兄。", description = "你不在的時候，我看見一群咕嚕摩在牛蹄兄的帶領下延著粗麻小徑走了下來。\n\n但接著骨捶攻擊了他們。他們把我的兄弟和他手下的咕嚕摩帶去了北邊。\n\n拜託，$p!救救我的兄弟。雖然他總是運氣很背，但他是我的兄弟。到銀背堡壘前面的聖壇去找他。", progress = nil, completion = "能被像你這樣的幸運星救出來真是我的運氣。\n\n兔腳兄總是說我運氣很背。呸!", rewards = "您能選擇下列奬勵中的一個：\n\n咕嚕摩蛋糕\n\n您還會收到：\n\n咕嚕摩蛋糕"}
MultiLanguageQuestData['tw'][30606] = {title = "重擊骨捶", objective = "到骨捶洞穴殺死8隻骨捶重擊者或是刺臂者。", description = "骨捶猴人有了個叫廢猴酋長烏克的新酋長。\n\n他看見西邊有恐懼、南邊有憤怒、東邊有揚古。\n\n所以他派猴人出來搶劫，收集食物和補給來預防未來的饑荒。\n\n骨捶數量多又危險。\n\n拜託，幸運星，你能幫忙打敗他們的戰士嗎？", progress = nil, completion = "你真是個真正的幸運星。", rewards = "城牆看守者外衣峰頂守護者外衣犛牛牧人外衣默葉外衣平靜外衣夢境之靈外衣牡山獸皮外衣您能選擇下列奬勵中的一個：\n\n英雄的獎金\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30607] = {title = "猴人熱愛他們的鑰匙", objective = "從裘裘那裡取得雪人鐐銬鑰匙並釋放老噗噗。", description = "猴人們抓了一隻雪人！他們給他取名叫老噗噗並且把牠關在山洞的後方。\n\n猴人通常很怕雪人，但他們現在拿咕嚕摩去餵牠。\n\n他們有個叫『邪惡的』裘裘的獵人酋長在那裡監視著那野獸。你能去看看他身上有沒有鑰匙能解開雪人身上的鐐銬嗎？\n\n如果有隻雪人在堡壘裡跑來跑去，那些猴人就要倒大楣了。", progress = "聰明的幸運星從不騎髒犛牛經過有雪人的地方。", completion = "喔喔!看起來好像很刺激!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30608] = {title = "美味點心", objective = "解救5名被囚禁的咕嚕摩，你可以放他們下來或是從籠子裡釋放他們。", description = "他們帶走了我的咕嚕摩！猴人不會吃咕嚕摩，但是雪人會。而那些骨捶養了一隻雪人。\n\n拜託，救救我的咕嚕摩。放他們下來或是把他們從籠子裡放出來。用你想得到的任何方法救救他們。\n\n幫我這個忙，我會給你加持很多好運的。", progress = nil, completion = "今天是同時充滿好運和壞運的一天。壞運是那些猴人偷走了我的咕嚕摩。好運是我的&lt;race&gt;解救了我的咕嚕摩。壞運是這麼多的猴人得死去才能學到教訓。好運是&lt;race&gt;是群知道怎麼戰鬥的幸運星。\n\n咕嚕摩不作戰。我們扛貨，我們探險，我們心滿意足。", rewards = "瀑布之索牡山獸皮腰帶夢境之靈護腰平靜扣環屈心者之索默葉腰帶犛牛牧人腰帶峰頂守護者束腰城牆看守者束腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][30610] = {title = "咕嚕摩!咕嚕摩!咕嚕摩!", objective = "護送5名沒背包包的咕嚕摩到廢渣園地附近的補給箱。", description = "咕嚕摩們已經得救，該去救我們的補給了。\n\n廢猴酋長烏克就是因為有補給才能稱王。\n\n到西北方的廢渣園地去。帶一些咕嚕摩和你一起。確保他們的安全並讓他們靠近補給箱。\n\n咕嚕摩知道接下來該怎麼做。我們在那裡和你碰頭。", progress = nil, completion = "現在猴人之王該懂得為什麼欺騙咕嚕摩是壞運氣了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30611] = {title = "釋放雪人!", objective = "殺死4隻牢籠看守者。", description = "你的雪人狂飆給了我一個主意。廢猴酋長烏克有一隻寵物雪人叫做強普‧強普。\n\n他用雪人恐嚇其他猴人，以確保他的領導地位。我們得釋放那隻雪人。我有個計畫。\n\n到廢渣園地去打倒一些牢籠看守者，這樣強普‧強普就不會被綁得這麼緊了。\n\n牛蹄和我會帶著大批的薰香和一隻髒犛牛在那裡和你碰面。", progress = nil, completion = "準備好釋放雪人了嗎？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30612] = {title = "猴人之王", objective = "激怒強普‧強普然後擊敗廢猴酋長烏克。", description = "面對廢猴酋長烏克的時候到了。將他擊敗，就沒有人領導猴人進行掠奪。\n\n計畫是這樣的:牛蹄會帶領塔索到競技場去嚇跑強普‧強普。\n\n然後，你趁其他猴人的注意力全集中在肆虐他們老家的雪人身上時，偷跑進去打敗廢猴酋長烏克。\n\n我們會準備好大大的謝禮在柯沓營地與你會合。祝你好運，咕嚕摩的朋友。", progress = nil, completion = "廢猴酋長烏克死了!萬歲!", rewards = "瀑布手套牡山獸皮手套夢境之靈護手平靜手套屈心者手甲默葉手套犛牛牧人護手峰頂守護者護手城牆看守者護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][30613] = {title = "鋼牙鯉魚", objective = "到釣手泊船處南邊的水域用魚矛抓5隻鋼牙鯉魚。", description = "鋼牙鯉魚是這一帶的美食。\n\n不幸的是，我們無法釣上這種魚，因為他們會用強而有力的下巴咬斷我們的鉤子。帶上這把魚矛，看你能不能幫我們抓幾隻回來。", progress = "有用魚矛抓到魚嗎?", completion = "小心那些鯉魚，&lt;name&gt;。他們會咬掉手指!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30614] = {title = "加油站", objective = "到一座揚古鑽油井裝滿空油瓶。", description = "揚古來到這裡之後就開始挖油。不曉得這個「油」究竟是什麼東西？也許是帶有特殊好運的東西。\n\n來吧，帶上這個瓶子，從一架風車那裡裝些揚古的油回來。我會給你加持很多好運的。", progress = "揚古超可怕的。有這種「油」當幸運星的揚古更是超超超可怕。", completion = "開心的一天!給你報酬。希望這些錢幣給你好運。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30616] = {title = "交通事故", objective = "擊敗8名魯秦火焰營地的揚古。", description = "揚古在攻擊我們的粗麻小徑。這對咕嚕摩來說真是太不幸運了。\n\n我們用那條路把補給帶去熊貓人的長城。沒有這些補給，保衛長城的大家就有危險。\n\n咕嚕摩們是旅行家，不是戰士。你可以當個我們的幸運星，阻止揚古的封鎖嗎？", progress = nil, completion = "有&lt;race&gt;幫咕嚕摩的忙是很大的幸運。祝咕嚕摩的朋友好運。", rewards = "幸運星戒指咕嚕摩市集紀念品粗麻戒環火焰營地戒指煙屁股指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][30617] = {title = "道路救援", objective = "沿著通往獨罈集的路上點燃8枝好運粗麻薰香。", description = "一個幸運星總是記得帶薰香到山裡去。薰香越臭就越幸運。\n\n你能不能沿著路往獨罈集去，順便點燃你一路上看見的薰香？\n\n這會為必須走那條路的咕嚕摩帶來祝福。\n\n絨棉口袋兄會給你很多獎賞的。到獨罈集那裡後跟他講話。", progress = nil, completion = "歡迎來到獨罈集!連接粗麻小徑和奈佛勒斯山的門扉!", rewards = "您能選擇下列奬勵中的一個：\n\n鼠尾草薰香\n\n您還會收到：\n\n鼠尾草薰香恆龍寶箱"}
MultiLanguageQuestData['tw'][30618] = {title = "補給獨罈集", objective = "到嚎風洞穴取回8份被偷走的補給。", description = "如果你正在尋找全崑萊最棒的補給品，那你就來對地方了！喔當然，現在看起來有點空。別讓表像蒙蔽你…\n\n哦，我在騙誰啊？！經過一連串的猴人攻擊和妖精搶劫後，我們還能剩下什麼補給物資，我的存貨數量已經危在旦夕。\n\n如果你能替我取回一些被偷走的物資，或許我能為你的旅程做點貢獻。", progress = "你拿回我的補給了嗎？", completion = "喔，謝謝你，&lt;name&gt;!只要我切掉被咬的地方，修理一下損害較小的部份，它們可能還賣得掉。\n\n一旦你的車準備好上路，我會把我答應過的補給裝上去!", rewards = "城牆看守者裹腕峰頂守護者裹腕犛牛牧人裹腕默葉裹腕屈心者裹腕平靜裹腕夢境之靈裹腕牡山獸皮裹腕瀑布裹腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][30619] = {title = "魔古？！喔不！", objective = "殺死魔古岬靈魂呼喚者。", description = "我知道你朋友很擔心魔古岬那些復活的雕像，但我要告訴你真正該擔心的事。\n\n有復活雕像的地方，就有魔古。我不知道你以前有沒有看過魔古，假如你沒見過…\n\n嗯，這樣說吧，魔古出現是個非常，非常糟糕的消息。\n\n不管你正在處理什麼事，都必須把魔古這個麻煩解決掉！", progress = nil, completion = "喔感謝老天！相信我，你讓我們逃過一劫。\n\n你不知道那些傢伙可以惹出多少麻煩。\n\n呃，或者，我想你現在知道了。稍微知道。大部分啦。\n\n想像一下你所知道的，然後還要更糟，而且再持續個幾千年。", rewards = "瀑布兜帽牡山獸皮頭盔夢境之靈頭盔平靜頭罩屈心者風帽默葉頭盔犛牛牧人頭盔峰頂守護者頭盔城牆看守者頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][30620] = {title = "魔古？！喔不！", objective = "殺死魔古岬靈魂呼喚者。", description = "我知道你朋友很擔心魔古岬那些復活的雕像，但我要告訴你真正該擔心的事。\n\n有復活雕像的地方，就有魔古。我不知道你以前有沒有看過魔古，假如你沒見過…\n\n嗯，這樣說吧，魔古出現是個非常，非常糟糕的消息。\n\n不管你正在處理什麼事，都必須把魔古這個麻煩解決掉！", progress = nil, completion = "喔感謝老天！相信我，你讓我們逃過一劫。\n\n你不知道那些傢伙可以惹出多少麻煩。\n\n呃，或者，我想你現在知道了。稍微知道。大部分啦。\n\n想像一下你所知道的，然後還要更糟，而且再持續個幾千年。", rewards = "瀑布兜帽牡山獸皮頭盔夢境之靈頭盔平靜頭罩屈心者風帽默葉頭盔犛牛牧人頭盔峰頂守護者頭盔城牆看守者頭盔您會收到：\n\n牡山獸皮頭盔默葉頭盔恆龍寶箱"}
MultiLanguageQuestData['tw'][30621] = {title = "他們把我的好運偷走了!", objective = "將好運兔妖腳、犛牛蹄、四風三葉草和金幣交還給『幸運者』姬盧。", description = "我在崑萊的旅程教給我兩件事。第一，永遠不要偷偷騎上正在睡覺的犛牛。第二，受幸運眷顧是必要卻可遇不可求的事。\n\n咕嚕摩們相信隨時在身上攜帶幸運物。我覺得，如果一個小飾品有辦法偶爾帶來好運，那很多小飾品就能保證好運!\n\n抵達獨罈集後，我的幸運飾品被那些壞蛋妖精給偷了。如果你能幫我弄回來，我真的會很感激的。", progress = "你找回我的幸運飾品了嗎？好運永遠都不嫌多。", completion = "謝謝你!看來我的飾品也為你帶來了好運，&lt;class&gt;。因為當你不在的時候，我竟然忍著沒把這輛貨車給賭丟了。\n\n我很樂於將這貨車借給你趕路。除此之外，我還有些貨物得從這個鬼祟的咕嚕摩那裡贏回來!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30622] = {title = "群蟲壓境", objective = "殺死15個伊克席克戰士或伊克席克感染者。", description = "少了牆的保護，我們幾乎沒有勝算。要不是你召集了那麼多人來幫助我們，我們恐怕已經毀了。\n\n去向橡木盾隊長報到，他應該在牆的裂口附近。沿路上盡可能多殺些螳螂人。\n\n如果我們贏了，那就贏了。如果我們輸了，至少也要奮戰到最後一刻。為了潘達利亞！", progress = nil, completion = "我的城牆…我在上頭守了一輩子的牆…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30623] = {title = "螳螂人解藥", objective = "對5個伊克席克空軍指揮官使用肯‧肯的面具，並打倒隨之竄出的實體化的恐懼之煞。", description = "<小美比了個手勢指向戰場。>\n\n你看到戰場裡那些巨大的螳螂人指揮官了嗎？他們身上有種奇怪的靈氣，讓我忍不住想起在祝家守望站裡目睹到的悲劇。\n\n或許…他們也是受到了煞的影響？\n\n我還保留著肯‧肯用來移除易謀身上煞靈的面具。我相信，如果我們把它用在那些螳螂人身上，我們可以說服他們撤退。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30624] = {title = "酒喝多了不好", objective = "將啤酒交給祝家看守者、鶴翼司祭、影潘和夜精靈移民者。", description = "我一直在想。\n\n我們有這麼多老陳釀的啤酒，還有這麼多你召集來的人手。我們應該讓兩者結合。\n\n外頭那群傢伙正為了潘達利亞拼命。你和我至少該去給他們帶個幾桶酒。\n\n他們要不就是在勝利時可以舉杯慶祝，要不就是在蟲子扒掉他們的皮之前，可以痛快地喝一次。不管怎樣，我可不希望他們奮戰的時候，肚子空空如也。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30625] = {title = "脫胎換骨", objective = "找到武術學徒們，並協助他們擊敗一隻伊克席克血怒者、蛋之主母、切腱者與恐懼散佈者。", description = "那五名曾去尋找隱居宗師的學徒獨自衝上前線了。我很想派出影潘去幫助他們，但我已經沒有多餘的兵力。\n\n在牆的附近有好幾種危險的生物。如果你找到那些學徒，務必別讓他們栽在任何一隻危險生物的手裡。", progress = nil, completion = "他們無法一直這樣戰鬥下去。儘管那些孩子都是勇敢奮戰的英雄，但我並不希望他們變成犧牲陣亡的英雄。\n\n是時候認輸撤退了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30626] = {title = "撤退!", objective = "到四風峽的石犁村找輪眉。", description = "我打算撤回我僅存的兵力。我們可能要撤離到風暴烈酒酒坊，或者甚至到半丘。這是警備指揮官輪眉該做的決定。\n\n你先走吧。把這些話傳給指揮官。我的影潘隨後就到。", progress = nil, completion = "我了解了。\n\n好吧，我們已經盡了全力。現在該趁這些螳螂人還沒占領四風峽之前撤離，搶救一些生命，並重新組織一下我們的策略，", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30627] = {title = "石犁村救星", objective = "與石犁村的范妮小姐談話。然後，藉由她的幫助，擊敗大蟲。", description = "指揮官講話時很匆忙，他手上握有致勝的武器，而那個武器就是你。\n\n你可能會說「這太難了吧。」。\n\n那你可就錯了，這一點都不難，沒有什麼是太難的。\n\n快去，<name>。去，拯救石犁村!", progress = "一切都完了，<name>。收拾你的行李。我們將起程前往半丘。", completion = "真不敢相信!像你這樣一個外地來的&lt;race&gt;，辦到了連影潘都辦不到的。完成了連長城也完成不了的。\n\n這下我們總算可以保住村莊了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30628] = {title = "石犁村的謝禮", objective = "找到指揮官的貯藏箱以領取你的獎賞。", description = "最後一件事，<name>。別擔心，不是要再麻煩你幫忙。你今天已經殺死夠多蟲子了。\n\n我們最近收到了一批從崑萊峰運來的高品質護甲。我本來是要留給自己人的...但是我想不到還有誰比你更有資格擁有它們。你可以在村裡旅店的二樓找到它們。", progress = nil, completion = "你往箱子裡瞧，發現了...", rewards = "納耶里足靴號角之息護足深野蠻荒脛甲納松護脛安格寇足靴川刃長靴薩鍾脛甲廓亞戰靴朵迦戰靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][30629] = {title = "FLAG—最后一轮", objective = "倾听晓和他同伴们的谈话。", description = "嘿，你好。你在寻找这片地方的主人吗？那就去见见楼梯上面的那位熊猫人吧。跟你一样，我也是访客。\n\n不好意思，我跟我朋友现在要商量点事情。我们稍后再聊。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30630] = {title = "進入谷中", objective = "到恆春谷的七星廟找女總管菲芬。啊，我正在等你呢，旅行者。\n\n我希望我們見面的時機別這麼糟，但是恆春谷的情勢恐怕相當危急。\n\n先別說這個了，到七星廟去找女總管菲芬。\n\n她應該能說明目前的狀況。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "啊，我正在等你呢，旅行者。\n\n我希望我們見面的時機別這麼糟，但是恆春谷的情勢恐怕相當危急。\n\n先別說這個了，到七星廟去找女總管菲芬。\n\n她應該能說明目前的狀況。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30631] = {title = "七星廟", objective = "到恆春谷找『慷慨使』賈廬、『無憂者』庫魯、幸運阿琳與女總管菲芬。", description = "看看這生物，旅人。我們到達沒多久，魔古刺客就毫無預警地攻擊了我們。\n\n他攻擊的目標是金蓮會的首領。真是萬幸，我們剛好在這裡阻止了他的攻擊。\n\n由於他們企圖取走值的性命，我擔心其他來到山谷的人可能也有危險。\n\n那些護法們都在城市東南邊安頓你的人民。去和那些領導者們說話，並確保他們平安。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30632] = {title = "郭萊廢墟", objective = "到恆春谷的郭萊廢墟找安吉‧秋光。", description = "根據『和諧雅士』值所說，魔古正從西方的郭萊廢墟往恆春谷移動。\n\n我派安吉和昆去調查情況，但他們還沒回來。\n\n我需要個像你這樣能幹的<class>去查看他們的狀況。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30633] = {title = "清光斥候", objective = "殺死8個嘯天先驅者。", description = "我們已經知道魔古出現在谷中，但情況比我們預期得更糟糕。\n\n他們的斥候在西北方的廢墟四處逡巡，蒐集情報並竊取寶物。\n\n你的目標很清楚，就是殺光你見到的每個斥候。失去耳目的軍隊將無法動彈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30634] = {title = "禁止進入", objective = "到廢墟高地找勞‧軟足，並跟著他走上小徑。接下來，把爆破酒桶放在廢墟高地洞穴入口。", description = "我跟勞‧軟足偵察過北方的廢墟。\n\n看來魔古已經穿過山丘上的山洞進入谷中，而且他們正派遣數量龐大的援軍過來。\n\n敵人太多，無法一一把他們的頭砍掉，所以你必須到廢墟入口處去見勞‧軟足。\n\n他會幫助你用潛行的狀態潛入。然後，把這些裝滿炸藥的桶子放在山洞的洞口。\n\n接下來就順其自然了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30635] = {title = "殺死麒麟獸", objective = "殺死9個石頭守護者。", description = "我們暫時解決了斥候的問題，但山丘下的郭萊院裡，魔古的武力還在繼續增加。\n\n不幸地，廢墟深處有兇惡的守衛犬在保護他們進行的工作。\n\n宰了那些野獸吧。務必要保持警戒，這些野獸與周遭環境融合的能力非常好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30636] = {title = "力量之石", objective = "收集7個利維萊特水晶。", description = "好幾千年前，恆春谷的統治者尋找過一種具有強大力量的水晶，這種水晶被稱為利維萊特。\n\n有了這種物質，它們就能驅動城市、工廠、以及用於戰場上的機器。\n\n『和諧雅士』值要求我們去收集一些水晶，並帶回城市裡。\n\n當你在廢墟行走時注意找找看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30637] = {title = "郭萊院", objective = "到郭萊院調查魔古的存在。", description = "在你經過巨大的門扉同時，你聽見大門深處傳來了聲音。\n\n安吉提過，魔古早一步發現了這個地區。或許他們也用自己的方式進到了深淵底下。\n\n你的感官在震顫，你決定去調查一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30638] = {title = "留下一個缺口", objective = "到恆春谷的黃金寶塔找利文‧曦刃。", description = "這很嚴重。\n\n我跟昆會照料這裡的事，但你應該到黃金寶塔去。\n\n去吧，動作快點!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30639] = {title = "郭萊的秘密", objective = "到郭萊院找何‧軟足，並在西邊房間中發現魔古的目的。", description = "我剛收到郭萊廢墟附近的守衛站傳來的消息，嘯天的首領進入大廳，殺死了我的兩個手下。他們的目的是裡頭的某樣東西。我們必須阻止他們。\n\n何‧軟足已經跟著他們進去了。他應該正在西側房間的入口處等你。\n\n動作快點，<name>。我不喜歡魔古可能領先我們一步的感覺。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "金蓮之精緻印記金蓮之燃燒印記金蓮之癒合印記金蓮之兇猛印記金蓮之耐久印記您會收到：\n\n"}
MultiLanguageQuestData['tw'][30640] = {title = "雷电之王的战矛", objective = "取回雷电之王的战矛。", description = "我听到了一些不好的消息，<name>。\n\n魔古正密谋从锦绣谷窃取三件神器。\n\n我们必须立即取回神器，并把它们藏起来妥善保管。\n\n第一件神器是雷电之王的战矛。\n\n皇帝雷神死后，他的战矛被放在了西北面的古代神龛中。\n\n去把战矛给我带回来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30641] = {title = "雷电之王的战盔", objective = "取回雷电之王的战盔。", description = "第二件强大的神器是雷电之王的战盔。\n\n雷神皇帝每场战斗都戴着那顶头盔。此事人尽皆知，他的敌人一看到那顶头盔，就会四下逃散。\n\n皇帝死后，他们把那顶头盔放置在了西边郭莱古厅的深处，由几千个陶土士兵守卫着。\n\n如此一来，他们就可以在死后继续追随他们的首领。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30642] = {title = "雷电之王的战斧", objective = "取回雷电之王的战斧。", description = "最后一件神器是雷电之王的战斧。\n\n雷神每次上战场时，总是一手执矛，一手持斧。\n\n据说他投掷战斧例不虚发，而且在击中目标后，它会发出惊雷一般的巨响。\n\n雷神死后，战斧被放在了西南面的祠堂中。\n\n毫无疑问，我们不能让它落入魔古族的手中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "金蓮之精緻護胸金蓮之脆裂鍊甲金蓮之溫暖護胸金蓮之兇猛鎧甲金蓮聯結鎧甲金蓮之亡眼鍊甲金蓮之耐久鎧甲金蓮之燃燒長袍金蓮之癒合長袍您會收到：\n\n"}
MultiLanguageQuestData['tw'][30643] = {title = "魔古的訊息", objective = "到恆春谷的靜默聖地找『和諧雅士』值。", description = "與魔古之間的戰鬥激烈地進行，沒有一邊讓步。\n\n我們無法永遠維持這種情況。必須做點什麼事來重創魔古，狠狠一擊，讓他們再也無法恢復。\n\n到靜默聖地去找『和諧雅士』值報到。我想聽聽他對這種情況的想法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30644] = {title = "逝者已矣", objective = "和锦绣谷鎏金亭的孙·柔心谈一谈。", description = "你最好立即返回鎏金亭进行汇报。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30645] = {title = "三人之力", objective = "在锦绣谷的仲夏原击败100个魔古入侵者。", description = "就这样了，<name>。结束了。\n\n如果我们无法将魔古族赶出锦绣谷，他们将夺取剩余的上古力量，并用它来肆意破坏潘达利亚。\n\n我们的军队不够强大，士兵也很疲乏。我们的军队会受伤，敌人的军队却都是石头战士。\n\n<name>，尽管面临着重重困难，我还是要请求你去帮助我们的军队杀死魔古入侵者。\n\n我已经向众神祈祷过，祈求他们的帮助。我只能寄希望于他们回应我们的召唤了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30646] = {title = "最后的力量", objective = "击败韶天军阀——放血者兆金。", description = "我从没想过事情会变成这样！\n\n莱文去宫殿阶梯的顶端挑战韶天军阀——放血者兆金去了，但我们的援军无法通过！\n\n只有我们能阻止他与锦绣谷最强大……也是最凶残的敌人交手。\n\n拜托了，<name>，请你一定要阻止他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "金蓮之兇猛項鍊金蓮之精緻項鍊金蓮之耐久項鍊金蓮之癒合項鍊金蓮之燃燒項鍊您會收到：\n\n"}
MultiLanguageQuestData['tw'][30647] = {title = "追踪任务：开启金色谷入口", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30648] = {title = "旅程繼續", objective = "與緋談話以前往四風峽。", description = "你在這片土地上的旅程堪稱多采多姿，旅人。而我的旅程，似乎還要持續一段時間。\n\n你們一行人的到來之後發生了不少事件，儘管有些事件造成的後果慘不忍睹，我仍感覺你們的出現帶有更深的意義。\n\n眼前，你最好離開這裡，探索潘達利亞的其他區域。\n\n準備好離開時便告知我一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30649] = {title = "雙月廟", objective = "到恆春谷找『慷慨使』賈廬、『強者』莫奇摩、廖長者與菲羅女士。", description = "看看這生物，旅人。我們到達沒多久，魔古刺客就毫無預警地攻擊了我們。\n\n他攻擊的目標是金蓮會的首領。真是萬幸，我們剛好在這裡阻止了他的攻擊。\n\n由於他們企圖取走值的性命，我擔心其他來到山谷的人可能也有危險。\n\n那些護法們都在城市東南邊安頓你的人民。去和那些領導者們說話，並確保他們平安。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30650] = {title = "熊貓人囚犯", objective = "釋放8個熊貓人囚犯。", description = "聽著，我知道聯盟需要新兵，而且現在我們這個鎮上戰鬥的兵力不足。\n\n但我知道，我們有許多人被關在西北方的歐朵火焰營地那裡。而且我也知道，如果你去把他們救出來，他們可能會更願意加入聯盟。\n\n你怎麼說，<name>？", progress = nil, completion = "唉呀，這可不是我們的英雄，&lt;name&gt;嗎。\n\n我真的不確定我們有沒有獲勝的機會，你知道嗎？\n\n這些傢伙或許還有點拙，但我們能夠把他們雕琢成形。到時候，我們就有機會守住崑萊了。\n\n做得好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30651] = {title = "歡樂桶", objective = "使用在歐朵火焰營地找到的炸藥桶，摧毀西邊、南邊與東邊的油井。", description = "喔，那麼，讓我們來給自己找點樂子吧，<男孩/女孩>！\n\n西北方那些歐朵揚古替我們省了自製炸彈的麻煩。他們已經把炸彈放在那兒了。\n\n讓我們利用他們的炸藥桶子，去摧毀他們的抽油幫浦，怎麼樣？", progress = nil, completion = "呵呵，真是精采。&lt;name&gt;，我就知道應該跟你一起去!", rewards = "您能選擇下列奬勵中的一個：\n\n火藥桶\n\n您還會收到：\n\n火藥桶恆龍寶箱"}
MultiLanguageQuestData['tw'][30652] = {title = "導引帷幄之中", objective = "殺死歐朵喚燼者、歐朵火占師、歐朵火語者與歐朵施焰者。", description = "歐朵火焰營地的揚古是可怕的威脅。我需要你到西北邊去殺了他們的首領。\n\n不幸的是，他的四個屬下築了一道火焰柵欄，防止我們接近鄰接山洞中的首領。\n\n把巫師全殺了，如此防護盾就會消失。你會發現他們正在帳篷裡導引法力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30653] = {title = "酒喝多了不好", objective = "將啤酒交給祝家看守者、鶴翼司祭、影潘和牛頭人移民者。", description = "我一直在想。\n\n我們有這麼多老陳釀的啤酒，還有你聚集起來的這麼多人手。我們應該讓他們「結合」一下。\n\n有群傢伙正在外頭為了潘達利亞拼命。你和我至少該去給他們送個幾桶酒。\n\n他們要就是能在勝利時舉杯慶祝，要不就是在蟲子扒掉他們的皮之前，痛快地喝一頓。不管怎樣，我都不希望他們艱苦奮戰的時候，沒有幾兩黃湯在肚。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30654] = {title = "郭萊院", objective = "調查郭萊院的魔古。", description = "魔古在計畫些什麼。我感覺得到。\n\n他們把斥候送進郭萊院。\n\n根據管理員所言，郭萊院裡面保存大量過去帝國時代的遠古珍寶。不僅是財富，還是具有偉大力量的神器。\n\n我們必須防止魔古接近那些寶藏!從西北方的斜坡往下走，去阻止他們!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30655] = {title = "熊貓人囚犯", objective = "釋放8個熊貓人囚犯。", description = "聽著，我知道部落需要新兵，而且現在我們這個鎮上戰鬥的兵力不足。\n\n但我知道，我們有許多人被關在西方的歐朵火焰營地那裡。而且我也知道，如果你去把他們救出來，他們可能會更願意加入部落。\n\n你怎麼說，<name>？", progress = nil, completion = "嗯，看來我們在這裡有一個小小的軍隊了，多虧了你。\n\n他們或許看起來不怎麼樣，但只要經過一點部落的訓練，我們很快就能讓他們進入戰鬥模式。\n\n對了，&lt;name&gt;...你做得很好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30656] = {title = "歡樂桶", objective = "使用在歐朵火焰營地找到的炸藥桶子，摧毀東邊、南邊與西邊的油井。", description = "我最愛把東西炸得滿地開花。我從骨子裡熱愛爆炸!\n\n西方歐朵火焰營地的揚古在營地周圍放了上噸的炸藥桶子。\n\n照我說呢，我們該來點樂子，利用他們的炸藥桶子，去摧毀他們的抽油幫浦!", progress = nil, completion = "&lt;name&gt;，這真的很好玩吧!我就知道應該跟你一起去!", rewards = "您能選擇下列奬勵中的一個：\n\n火藥桶\n\n您還會收到：\n\n火藥桶恆龍寶箱"}
MultiLanguageQuestData['tw'][30657] = {title = "導引帷幄之中", objective = "殺死歐朵喚燼者、歐朵火占師、歐朵火語者與歐朵施焰者。", description = "歐朵火焰營地的揚古是可怕的威脅。我需要你到西邊去殺了他們的首領。\n\n那個懦夫躲在山洞裡，四周由他的四個屬下築了一道火焰柵欄。\n\n把巫師全殺了，如此防護盾就會消失。你會發現他們正在帳篷裡導引法力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30658] = {title = "河豚的刺", objective = "到薩鍾深淵用魚矛殺死5隻多刺河豚，並把刺帶回來。", description = "<name>，你聽過多刺河豚這種魚嗎?你當然沒聽過，你才剛到這一帶來!\n\n你可以在西邊的薩鍾深淵找到這種魚。帶著這把魚矛，看看你能不能幫我帶一些河豚身上有毒的倒刺回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30660] = {title = "歐朵戰爭使者", objective = "殺死歐朵戰爭使者。", description = "<防護盾已消除。進入洞穴殺死歐朵揚古戰爭使者的時候到了！>", progress = nil, completion = "&lt;name&gt;，你辦到了！我欠你一次情！\n\n應該說是第二次！", rewards = "歐朵釘錘燃焰者魔杖風眠長矛戰爭使者之斧風之刃炎熾步槍風之鋒歐朵手斧戰爭使者匕首炎熾痛擊錘您會收到：\n\n歐朵釘錘風眠長矛恆龍寶箱"}
MultiLanguageQuestData['tw'][30661] = {title = "歐朵戰爭使者", objective = "殺死歐朵戰爭使者。", description = "<防護盾已消除。進入洞穴殺死歐朵揚古戰爭使者的時候到了!>", progress = nil, completion = "你又再一次完成了不可能的任務。\n\n有人懷疑過嗎？", rewards = "歐朵釘錘燃焰者魔杖風眠長矛戰爭使者之斧風之刃炎熾步槍風之鋒歐朵手斧戰爭使者匕首炎熾痛擊錘您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30662] = {title = "歐朵戰爭使者", objective = "殺死歐朵戰爭使者。", description = "你消除了歐朵火焰營地的防護盾，在防護盾再次升起前回到那裡。\n\n進入洞穴殺死酋長的時候到了!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30663] = {title = "歐朵戰爭使者", objective = "殺死歐朵戰爭使者。", description = "你消除了歐朵火焰營地的防護盾，在防護盾再次升起前回到那裡。\n\n殺死歐朵戰爭使者!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30665] = {title = "保衛影潘後援地", objective = "殺死15個被煞侵蝕的揚古。", description = "我派人去影潘僧院求援，但完全沒有收到任何回音。這個鎮已經淪陷了。\n\n有幾個幸運的村民殘存下來，但我們都被困在這裡。\n\n我們沒時間招待陌生人了。如果你能戰鬥，請協助我的人防禦塔樓。如果你不懂戰鬥，離開這裡，否則你活不了太久。", progress = nil, completion = "你為我們爭取到一些時間來喘口氣。我們不能絕望，相反的，我們必須行動。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30666] = {title = "意外的鱷魚入侵", objective = "到齊克拉克殺死8隻號角之息鱷魚。", description = "正常來說，我的日子就是抓魚、吃魚、然後睡覺。注意，清單裡沒有包含「跟鱷魚戰鬥」這個項目。\n\n你看起來像是一個有用的<class>。你能不能去解決一些鱷魚，好讓我的生活恢復正軌？鱷魚通常在西北方的齊克拉克出沒。", progress = nil, completion = "昨天，我們還在快樂地釣魚。今天，那些鱷魚就開始想…吃掉我們。\n\n真奇怪。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30667] = {title = "特別的羽毛", objective = "取得6根翡翠尾羽、6根赤紅尾羽與6根暗色尾羽。", description = "鱷魚群開始攻擊的時候，把一群金剛鸚鵡給嚇得飛出牠們位於我們西北方的巢穴了。\n\n我可以用那些金剛鸚鵡的羽毛做特殊的魚餌，哪天我不用再防止那些爬蟲接近我的隊友時，那種魚餌會變得相當有用。\n\n你有興趣獵些羽毛回來嗎？", progress = "<東尼的眉毛上有一顆閃著光芒的小汗珠子。>", completion = "謝謝你，&lt;name&gt;。今天這樣過也算值得了。我實在很討厭眼睜睜失去這種採集羽毛的好機會。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30668] = {title = "建造你自己的木筏", objective = "取得4塊備用木板與一些硬藻。", description = "<傑遙望著齊克拉克的方向。>\n\n嗯。他們似乎並沒有...冷靜下來。我們必須試試別的方法。\n\n你需要一艘木筏。去找一些木板跟海草，然後帶來給我。我會幫你組合起來。", progress = "東西拿全了嗎？我會幫你造一艘木筏，但我需要材料。", completion = "&lt;傑熟練地將木板綁在一起，變成一艘好像真有能力在海上航行的交通工具，然後推到水面上。&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30669] = {title = "湖上的博學行者", objective = "登上你的木筏，然後到納耶里潟湖的中心找智者安娜‧吳。", description = "你的木筏已經在水裡了。搭著它划到湖心去，你會在那裡找到一個女人。她的名字是安娜‧吳。\n\n每當我遇到自己弄不懂的問題，我都會去問她。她應該能告訴我們這些鱷魚一直不停攻擊的原因。", progress = nil, completion = "孩子，你臉上掛著憂慮。\n\n我這個博學行者能為你做什麼呢？你在尋求什麼？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30670] = {title = "轉變", objective = "到火枝望角，從盲目之怒身上收集5個盲怒精華。", description = "我們真正的敵人是煞，不是揚古。\n\n煞是種情感表現。的確具有毀滅性，但沒經過訓練。沒經過訓練的武力無法持久。洪流一旦分散，便失去力量。野火也有燒盡的一天。\n\n而修練與智慧可以將它們的毀滅力量轉而對付它們自己。\n\n到村莊裡去把煞的精華帶來給我，我會解釋得更清楚。", progress = "你取得它們的精華了嗎?", completion = "很好。現在你將看到該如何擊敗肆無忌憚的憤怒。\n\n我會為揚古的首領柯巴設一個陷阱。雖然我們會抓住並擊敗他，但他不是我們的最終目標...", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30671] = {title = "智慧有價", objective = "取得5片鯊魚肉片。", description = "<安娜聆聽你的故事，然後點點頭。>\n\n鱷魚攻擊？我知道這件事。我會跟你分享這個故事，但首先…我有點餓了。\n\n來點鯊魚肉應該不錯。你應該會在湖裡找到足夠的鯊魚。", progress = "<race>，我肚子非常餓。我已經在這個湖上待了好幾天都沒東西吃。", completion = "你帶來的肉比我所希望還要多得多\n\n好了，我應該還欠你一個故事...", rewards = "朵迦輕鞋廓亞輕鞋薩鍾長靴川刃輕鞋安格寇輕鞋納松輕鞋深野蠻荒護脛號角之息輕鞋納耶里輕鞋您會收到：\n\n"}
MultiLanguageQuestData['tw'][30672] = {title = "生態平衡", objective = "殺死10隻仰加捕魚者。", description = "這個故事沒有快樂的結局。對納松鱷魚而言不是。\n\n然而這一次，你或許有機會改變結局。\n\n南方的猴人在這些水域裡濫捕魚。魚群絕跡之後，鱷魚既飢餓又絕望，因此攻擊瑪里斯塔。\n\n現在去吧，<race>!阻止猴人的濫捕!", progress = nil, completion = "&lt;傑聽著你敘述一整天的經歷。&gt;\n\n我懂了。我們會盯緊那些仰加，我們也會盡量別在這水域過度捕撈。毫無疑問，我們也是這問題的一部分。\n\n再會了，&lt;name&gt;。", rewards = "魚販之刃護水者魔杖瑪里斯塔長戟瑪里斯塔之刃雲落之劍瑪里斯塔之弓瑪里斯塔之錘瑪里斯塔之斧雲落之刃雲落釘錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][30673] = {title = "藏匿", objective = "救出金‧溫桶、雅‧火枝、豐婆與賽雅‧鍾。", description = "喔老天啊，感謝你，<class>！我真不知道還能撐多久。\n\n我很肯定還有一些火枝望角的倖存者。你能不能幫忙救出他們，並把我們送去影潘後援地避難？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30674] = {title = "以和平的方式達到平衡", objective = "把6隻活跳鯉魚丟進納耶里潟湖。", description = "有些被仰加猴人抓去的魚看起來還活著，或許還有時間把牠們丟回水裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30675] = {title = "埋藏的猴人寶藏", objective = "找出埋藏的猴人寶藏。", description = "你手上那張地圖又髒又皺，而且畫得很糟，但你可以看到一個海岸的位置上畫了大大的X。\n\n島上的某處是否埋藏著寶物呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30678] = {title = "有如甕中炸魚", objective = "使用哥布林炸魚炸彈殺死3隻刺魟魚，並把刺帶回來給費茲尼克斯。釣手泊船處西邊的淺灘可以找到這種魚。", description = "原來這些魟魚比我想像得還要難抓！你看起來是個聰明的<小夥子/小姑娘>，也許你可以幫我？\n\n我製作了這些炸彈，但我的腳受傷了沒辦法使用木筏。魟魚通常會在西邊的淺灘出沒。帶著炸彈去搭我的木筏，把那種魟魚的刺帶回來給我！\n\n喔對了，小心錘頭鯊！", progress = "有在淺灘發現刺魟魚嗎?", completion = "那些炸彈你用得很上手嘛!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30680] = {title = "藏匿", objective = "救出金‧溫桶、雅‧火枝、豐婆與賽雅‧鍾。", description = "喔謝謝你，謝謝你，真是謝謝你。如果你沒出現...\n\n等等!一定還有其他像我一樣的望角倖存者!\n\n拜託，<class>，求求你，救出其他的村民們，並把我們安全送到影潘後援地。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30681] = {title = "藏匿", objective = "救出金‧溫桶、雅‧火枝、豐婆與賽雅‧鍾。", description = "喔，謝謝你！靠我自己一定無法辦到。\n\n仔細一想，火枝望角四周一定有更多需要救援的人。我們能不能去救他們，然後一起回到安全的影潘後援地去？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30682] = {title = "藏匿", objective = "救出金‧溫桶、雅‧火枝、豐婆與賽雅‧鍾。", description = "我不敢相信你真的辦到了!\n\n我不知道還能在這裡面躲多久。\n\n<class>，我很肯定外面還有其他人，我們必須救他們出來!然後便可以前往影潘後援地。那邊的宗師會知道該怎麼做!", progress = nil, completion = "我們無法確定外頭有沒有倖存者。\n\n謝謝你把他們平安帶回來，&lt;name&gt;。", rewards = "您會收到：\n\n金‧溫桶的酒恆龍寶箱"}
MultiLanguageQuestData['tw'][30683] = {title = "一個旅人的不幸", objective = "在被遺棄的殘骸找尋補給品。", description = "你一定要用補給品丟他們嗎？！為什麼不用武器？或者帥氣的法術或飛踢？為什麼要是補給品？！\n\n現在我們沒有足夠的補給品來維持生計了，特別是對彎釘侄兒來說，他的食量跟雪人一樣大！\n\n東西你丟的，你去找更多東西來。小徑那邊有些殘骸。那裡或許能找到一些補給品。", progress = nil, completion = "你被魔古攻擊了？聽起來真糟！\n\n我不想這樣問，但你拼命戰鬥的時候有沒有順便帶點補給品回來？\n\n沒有？！這真是太不好運了。", rewards = "瀑布長袍牡山獸皮外套夢境之靈護甲平靜護胸屈心者長袍默葉外套犛牛牧人護甲峰頂守護者護軀城牆看守者護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][30684] = {title = "追尋者之愚行", objective = "登上追尋者之愚行的山路，尋找博學行者阿洲，在路上三處神壇停下來致敬。", description = "我敢說你的熊貓人朋友知道那些魔古在尋找什麼。\n\n幾天前，他沒帶嚮導就到山裡去了。他說只准派你去找他。他說得非常具體：\n\n「<class>必須獨自完成旅程，用<他自己的/她自己的>想法。<他/她>必須在登頂前對每一座神壇表示敬意。」\n\n那山路就在營地西北邊，有旗子做標記。請小心！就算在幸運的日子，追尋者之愚行的路途也很危險。", progress = nil, completion = "啊，你成功了，而且你對各個神壇表示了敬意。\n\n我就知道你能完成。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30690] = {title = "撕下揚古的面具", objective = "將柯巴引誘到盲怒陷阱中，從他身上偷走惡意之怒的面具，然後擊敗惡意之怒。", description = "光殺死柯巴對情況沒什麼幫助，因為他身上附著一個特別強大而具有毀滅性的煞，惡意之怒。\n\n我用你帶來的盲怒精華製造出一個陷阱，你可以使用它。把柯巴引誘到陷阱裡，然後偷走他的面具。一旦你戴上面具，惡意之怒就會出現在你面前，並企圖控制你。\n\n打敗他，我們便能在這悲慘的處境中取得勝利。", progress = nil, completion = "我該為村莊的損失感到羞恥，為你的成功感到自豪。\n\n我應該要有很多感觸，但我不允許自己這樣做。在我們與煞的爭鬥結束之前，我們必須完全掌控自己的情感。", rewards = "城牆看守者軟帽峰頂守護者軟帽犛牛牧人軟帽默葉軟帽屈心者軟帽平靜軟帽夢境之靈軟帽牡山獸皮軟帽瀑布軟帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][30691] = {title = "悲劇", objective = "將納哈薩從悲劇中解救出來。", description = "當你到水下的時候，你應該要殺死號角之息的族長納哈薩。牠正在受苦。我可以感覺到牠臨死前的哭嚎浮到潟湖表面。\n\n找到牠的洞穴，將牠從悲劇中解救出來。做這件事不是為了解決瑪里斯塔的鱷魚問題，純粹是出自於慈悲。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30692] = {title = "粗麻小徑:前往柯沓營地", objective = "護送一群咕嚕摩由粗麻小站前往柯沓營地。至少得讓一名咕嚕摩存活下來。\n\n如果你失去了你的咕嚕摩，你可以在粗麻小徑附近找找或是回到粗麻小站等待下一群離開。", description = "這裡是猴人的領土。很危險。不過咕嚕摩得通過這裡。補給必須運送到熊貓人長城。\n\n走吧，保護下一批咕嚕摩前往柯沓營地。\n\n如果能有至少一名咕嚕摩存活下來，你將會獲得好運。", progress = nil, completion = "哈哈！咕嚕摩們的英雄！歡迎來到柯沓營地，請享受最歡樂的咕嚕摩快遞所帶來的好運。", rewards = "落雪披巾雪迅披氅雪盲斗篷巨雪球法術斗篷雪罩披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][30694] = {title = "小心行走", objective = "在安全距離外使用「監控」來啟動10個川刃尖刺陷阱。", description = "我的學生告訴我，這個區域四處都布滿致命的陷阱，這些陷阱毫無疑問是薩烏洛克所設，只要踩到一個就會被釘子釘得滿臉包。\n\n就像俗話說的『道路險阻，小心行走』。帶著『監控』上路吧。\n\n<可羅交給你一隻長樹枝。>\n\n拿去，這就是「監控」。\n\n這應該夠長了，足以在安全範圍內先啟動陷阱。", progress = "嗯，我沒在你臉上看到釘子。這是個好現象。", completion = "你所彈開的每一個陷阱都救了一條生命，可能是熊貓人、野獸，或是其他東西。沒有人應該像這樣輕如鴻毛地死去。", rewards = "霧行者緞質護腿霧行者皮腿甲深野蠻荒腿甲霧行者光潔腿鎧霧行者絲質長褲霧行者皮甲腿甲薩鍾腿甲霧行者重型腿甲霧行者裝甲腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][30695] = {title = "通往「道」之路", objective = "在紅鶴寺東西邊的涼亭殺死兩個絕望之喉。", description = "在寺廟兩側涼亭的巨大絕望之喉不停地噴湧大量的煞。同時，你對「道」的臨時訓練也持續進行。\n\n「朝雨揮拳者，其身必濕於補傘者。」\n\n儘管我對這一課始終有點異議，因為有時候直接「朝雨揮拳」可是十分有效，但面對眼前的情況，這句話終究有它的道理。\n\n把這些絕望之喉解決掉，讓我們的人有機會收復寺廟。", progress = nil, completion = "可羅的隱喻有些煩人，但那背後總是存有真正的智慧。", rewards = "紅鶴之劍鶴神廟之刃絕望結界希望之盾煞曲之刃絕望之喉紅鶴權杖希望之燈您能選擇下列奬勵中的一個：\n\n英雄的獎金\n\n您還會收到：\n\n紅鶴之劍鶴神廟之刃絕望結界希望之盾恆龍寶箱"}
MultiLanguageQuestData['tw'][30698] = {title = "尋寶", objective = "用哥布林漁筏在沉船殘骸附近漂浮的碎片間釣起15個生鏽的沉船殘骸。", description = "你!你就是我一直在尋找的人!\n\n我需要更多材料來製作我的哥布林炸魚炸彈，但我弄傷了腿，無法自己去收集材料。\n\n你看到附近那些船骸了嗎?如果你能靠近那些殘骸並設法運出來，我敢打賭，裡頭一定有我需要的東西。使用我的漁筏，看看你能找到什麼!我的好朋友也一直試著想幫我，所以你可能會在殘骸附近發現一些多餘的木筏，你也可以隨意使用它們。", progress = "你有找到船骸嗎?", completion = "看來你找到不少材料，另一批炸魚炸彈馬上完工!謝了，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30699] = {title = "前往冬綻", objective = "到崑萊峰的冬綻找林‧默襲。", description = "對抗煞的戰爭是沒有止盡的。我們不能離開這個地方。\n\n情況如此緊急，加上我前幾天發過消息給僧院，僧院卻仍沒有派來援軍。這讓我很擔心。\n\n你至今的表現令人欽佩，或許你可以過去冬綻看看，那是我們往影潘僧院路上的一座基地。抵達後去和林‧默襲談談。他是個經驗豐富的斥候，應該會知道那裡發生了什麼事。往村子北方走，沿著路穿過影潘盆地，即可前往冬綻。", progress = nil, completion = "影潘宗師沖派你過來？\n\n是的，我們有收到他求援的消息。\n\n但以目前的情況，我們無法辦到。我們自己才剛結束一場戰役，僧院更已重重深鎖。\n\n我們也不過在山腳下，但就連我們也無法得到援軍！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30700] = {title = "猛鉗", objective = "到納松海溝底部的一個洞穴殺死猛鉗，並帶回牠的螯做為證明。", description = "一隻巨大的、惡毒的螃蟹在大肆蹂躪我們本地的鮑魚盛產地。我需要你到納松海溝裡去解決牠!", progress = "你殺死那隻噁心的東西了嗎?", completion = "這的確是牠的螯，猛鉗一定比我想得還要大!這不重要，&lt;name&gt;，做得好!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30701] = {title = "虎鉗湯", objective = "到海邊殺死虎鉗獵魚蟹，並帶回16顆眼珠來煮一些好喝的湯。", description = "虎鉗湯的味道堪稱天下一絕。這是喀撒朗的特產!\n\n我正想煮這麼一鍋湯，卻發現我少了一樣最關鍵的材料，眼睛!\n\n我需要你去殺了海邊的虎鉗獵魚蟹，並把牠們的眼睛帶回來煮湯!", progress = "你拿到多少小眼珠子啦?", completion = "謝了，&lt;class&gt;，這可能是我最讚的一批湯!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30710] = {title = "激怒巨魔", objective = "击败10个赞达拉追踪者和5个赞达拉妖术师。我们已经暂时击退了他们，但是如果不能把他们彻底消灭，这些家伙很快就会卷土重来。\n\n我丈夫不知道是胆小还是愚蠢，竟然主张不要激怒他们。我可不是胆小鬼！\n\n我们不能这样就算了。杀死他们的前锋斥候。或许我们就能激怒——并消灭——他们的首领。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "我们已经暂时击退了他们，但是如果不能把他们彻底消灭，这些家伙很快就会卷土重来。\n\n我丈夫不知道是胆小还是愚蠢，竟然主张不要激怒他们。我可不是胆小鬼！\n\n我们不能这样就算了。杀死他们的前锋斥候。或许我们就能激怒——并消灭——他们的首领。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30714] = {title = "消灭首领", objective = "击败赞达拉剑圣和赞达拉法师现在，他们都怕了你了。\n\n他们的首领：一个剑圣一个法师，就躲在废墟深处。去杀了他们。\n把他们打痛，就算是为了我们。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "现在，他们都怕了你了。\n\n他们的首领：一个剑圣一个法师，就躲在废墟深处。去杀了他们。\n把他们打痛，就算是为了我们。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30715] = {title = "無法突破的防線", objective = "讓影潘宗師志姚、千擊劉與世亞‧勇刃得到安息。", description = "承受了他們的第一擊後，我們重新編組，發現少了三個人。你有戰鬥能力，而我們必須計畫如何抵禦那些該死揚古的下一次進攻。\n\n如果你願意幫助我們，請為我們死去的戰友舉行告別儀式，並取回他們的戰甲。你會在西邊的關口附近找到他們的遺體。\n\n試著讓那些鳥遠離他們。", progress = nil, completion = "很好。我會確保這些戰甲被交到他們弟子的手中。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30716] = {title = "追逐希望", objective = "碰觸3個鶴之靈。", description = "赤吉始終與我們同在。即使他不在搖籃這裡，他的魂魄也散落在島上的森林與海岸，照看我們，給予我們試煉。\n\n<name>，在赤吉的關注下證明你是個身手敏捷的人。找出鶴的靈魂並抓住它。", progress = nil, completion = "赤吉對你微笑。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30717] = {title = "巨鶴的禮物", objective = "取得10根巨鶴的禮物。", description = "喀撒朗的鶴是赤吉的禮物，即使只是鶴的鳥羽也非常珍貴。\n\n我們運用這些羽毛來裝飾我們的長袍並製作羽箭。但首先...得先收集羽毛。", progress = "即使是最小、最薄的羽毛，也是赤吉愛著我們的證明。", completion = "&lt;name&gt;，謝謝你。\n\n早點回來找我們。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30718] = {title = "赤吉的學生", objective = "與10個赤吉的學生進行決鬥。", description = "我們對於持續精進戰鬥技能這件事十分自豪。我們在赤吉搖籃這裡決鬥，藉此磨練戰技。\n\n在紅鶴之眼下證明你自己。前往南方吧，深入島的中央，與你的同窗進行決鬥。", progress = nil, completion = "不論輸贏，每場戰鬥都能使你進步。你會變得更敏捷、更堅強、更聰敏...更厲害。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30719] = {title = "FLAG - Cradle of Chi-Ji Progress Bit 01", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30720] = {title = "FLAG - Cradle of Chi-Ji Progress Bit 02", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30721] = {title = "FLAG - Cradle of Chi-Ji Progress Bit 03", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30722] = {title = "FLAG - Cradle of Chi-Ji Progress Bit 04", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30723] = {title = "雖死猶榮", objective = "殺死12隻崑萊食腐鷹。", description = "嗯…如果影潘宗師沖信任你，也許你能幫助我們。\n\n揚古是我們的敵人。\n\n但我們仍然必須證明自己比他們更好。我們會讓他們死得有尊嚴。\n\n和往常一樣，禿鷹在戰鬥後開始聚集起來。殺掉幾隻禿鷹，讓我們敵人的遺體不至於遭到褻瀆。那些禿鷹聚集在西邊的戰場上。", progress = nil, completion = "很好。在他們做過這些事之後，我這輩子再也不會對揚古展現一點仁慈。但我也不會允許他們的遺體被鳥吃掉。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30724] = {title = "到長城去!", objective = "到崑萊峰的冬綻找『風箏大師』連，以乘坐風箏飛到玄牛關去找蘇納‧默襲。", description = "他們再次發動攻擊了!\n\n<林看著玄牛關。>\n\n弓箭手...到城牆上!\n\n我需要你到那裡去。我妻子蘇納跟那個笨蛋老秦一起到長城去進行偵察。如果他能多花點時間準備防禦工事，少花點時間去打造那愚蠢的啤酒運送工具...\n\n這不重要了。往西邊走，到連那裡去拿一個風箏，然後利用風箏到城牆上去找我妻子。她會知道接下來該怎麼做。", progress = nil, completion = "哇喔，剛剛的風箏飛行可真夠嗆。能活著從那上面回來，真是幹得好。\n\n有你在這兒也真的很好。老秦正在鑽研他自己的一個點子，但眼前我們還得料理揚古。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30725] = {title = "艾莉亞‧鴉鬃", objective = "在安格寇亭閣擊敗艾莉亞‧鴉鬃。", description = "我們定期安排程度差不多的受訓弟子，進行一對一決鬥。<name>，我們為你找到一個適合你的受訓弟子，<name>。\n\n她的名字是艾莉亞‧鴉鬃，這也是她第一次進行決鬥。她會在南邊的亭閣裡等你。", progress = nil, completion = "非常好!\n\n下次你回來的時候，你會面對一個新的挑戰者。繼續獲勝，赤吉眼中對你的關愛將持續加深。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30726] = {title = "谭命夺", objective = "击败谭命夺。", description = "你的下一个挑战者也是一位新晋的弟子。他的名字叫谭命夺，在前两场决斗中他都获得了胜利。\n\n他会在南面的仙鹤雕像那里等你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30729] = {title = "茱莉亞‧貝茨", objective = "擊敗茱莉亞‧貝茨。", description = "我們歡迎各式各樣的人來搖籃，只要他們了解並贊同紅鶴的思想。我們當中有個新來的，她來自東北方的人類王國，是個帶點異國風情的受訓弟子。她要別人用這個洋味十足的名字稱呼她，茱莉亞‧貝茨。\n\n她是你的下個挑戰者，你會在島嶼的西岸找到她。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30731] = {title = "郭納‧羽爪", objective = "擊敗郭納‧羽爪。", description = "搖籃內舉辦的大部分決鬥都是由兩位受訓弟子來進行。在少見的情況下，當一個受訓弟子展現出罕見的優秀技巧，他會有機會與訓練師決鬥。\n\n今天，你決鬥的對象是郭納，她在希望石臺等你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30732] = {title = "艾莉亞‧鴉鬃:復仇", objective = "到巴爾里莎圓頂擊敗艾莉亞‧鴉鬃。", description = "你的「對手」又出現了。這段時間艾莉亞‧鴉鬃拋下她在島上的責任，全神貫注於個人訓練上，一心想在戰鬥中擊敗你。\n\n「我要讓<name>粉身碎骨。」她說。\n\n我尊重她再次比試的要求，但我會緊盯著她。她的動機可能往危險的方向發展。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30737] = {title = "肥龍肥:再比試", objective = "在巴爾里莎圓頂擊敗肥龍肥。", description = "肥龍肥要求再與你比試一次。我覺得這件事很奇怪，也令人掛心。\n\n他會在巴爾里莎圓頂的頂端等你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30738] = {title = "瑟隆諾斯", objective = "擊敗瑟隆諾斯。", description = "在我們上次的談話中，我答應過要告訴你肥龍肥的秘密。我仍然打算告訴你那個秘密...但我要先確定你的價值。\n\n我會在西岸與你碰頭，到時我們將進行決鬥。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][30742] = {title = "停下來", objective = "到柯沓峰殺死12隻吃了卡法後發瘋的公山羊。", description = "我搞砸了。\n\n要挑出卡法莓的籽實在太難了！不過我發現山羊會吃掉整顆莓果再把籽排出來…大概花個一天時間左右吧。\n\n於是我把我所有的卡法莓拿去餵柯沓峰上的山羊，哪知道牠們全瘋了！看到會動的東西就一股腦地衝過去。\n\n咕嚕摩本來可以安心地在柯沓峰採卡法，現在被那些山羊害得完全不行。你能幫幫忙嗎？", progress = nil, completion = "謝謝你，朋友。希望你學到點教訓。永遠別餵山羊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30743] = {title = "卡法美食", objective = "到柯沓峰標記15個消化後的卡法「礦點」。", description = "真是天才：山羊吃掉卡法莓，種子再自己排出來。\n\n卡法柯沓原本就很稀有又值錢，但是我發明的消化後的卡法，才是美味中的美味。\n\n只是現在都完了。叔叔火冒三丈，山頂一團混亂。我們只有收集剩下的消化後的卡法，還有記得別讓同樣的事再度發生。\n\n我不會要求你去採集它。對一位英雄來說這太委屈了。你只要把它標記起來，這樣山上安全的時候，我就可以輕鬆找到它。", progress = nil, completion = "太好了，我會上去並儘快...「收割」他們。\n\n&lt;羊毛表兄開始把長長的亞麻布條纏在他的手上。&gt;\n\n真不敢相信，我居然會認為這是個好主意。", rewards = "您會收到：\n\n鋒豆卡法恆龍寶箱"}
MultiLanguageQuestData['tw'][30744] = {title = "柯沓特調", objective = "到柯沓峰收集100顆卡法柯沓莓。你可以在山邊的灌木叢，或是雪人洞穴裡找到它們。", description = "柯沓峰以其山上的卡法灌木聞名。沒有其他植物能在這種高度下存活。\n\n咕嚕摩藉著出售卡法柯沓特調致富，但是多虧了我的表弟，現在這變成一門危險的生意。他的小技倆讓山上的野生動物瘋狂迷上卡法。\n\n現在有那群山羊在那裡嚼個不停，加上雪人也愛把它們囤積在洞穴，卡法柯沓變得比從前更稀少了。\n\n要是你能從柯沓峰上帶幾顆莓子下來，我會好好犒賞你。\n\n哪，拿個樣本。吃了它。自己感受一下卡法的威力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30745] = {title = "麻煩醞釀中", objective = "到柯沓峰的山洞裡殺死5個吃了卡法後發瘋的雪人。", description = "柯沓峰上有許多雪人。真多。通常都不大危險。通常他們只吃山羊。\n\n最近他們吃了一肚子卡法莓的山羊…\n\n<鋒豆叔叔向羊毛投去意味深長的一眼。>\n\n現在他們暴躁，古怪，睡很多但看起來總是沒睡飽。典型的卡法成癮症。\n\n我很確定，他們沒多久就會為了找更多卡法莓而從山洞裡跑出來。\n\n到時候我們就全都有麻煩了。", progress = nil, completion = "你辦到了！\n\n雪人本身就是很強悍的生物，我實在無法想像一個患有卡法成癮症的發瘋雪人會變成啥樣子。你很勇敢。或者也可以說很幸運。或者也可以說很笨。\n\n也許三者皆是。", rewards = "您會收到：\n\n一杯卡法恆龍寶箱"}
MultiLanguageQuestData['tw'][30746] = {title = "公平交易", objective = "把一捆卡法柯沓莓，帶去柯沓峰頂附近，柯沓峰的恐懼之王巢穴。", description = "<吼聲再次響起，比你目前為止遇過的雪人都要更大聲也更兇猛。再一次，一個咕嚕摩的慘叫隨後響起...>\n\n咿!拜託，偉大的柯沓峰的恐懼之王，原諒咕嚕摩。讓我走，我馬上會帶更多卡法來!我保證!\n\n<那個被稱為柯沓峰的恐懼之王的野獸以厚實的咆哮做為回應。>", progress = "柯沓峰的恐懼之王想要更多卡法莓，但我已經把我所有卡法莓都餵給她吃了!然後我試著給她一個漂亮的蝴蝶結，但她不滿意!\n\n<這嚇壞的咕嚕摩吞了口口水，然後把身子靠過來低語。>\n\n我想她聞得到我早餐喝的卡法...", completion = "你帶了卡法莓來？！\n\n你真是…\n\n美妙的…\n\n幸運星…\n\n快，我們把卡法莓拿給她！也許她就不會把我們兩個都當點心吃了…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30747] = {title = "碾壓粗麻", objective = "在柯沓營地用卡法之瓶餵食柯沓峰的恐懼之王，然後到粗麻小徑殺死100個猴人。", description = "好吧...嗯，她沒有吃掉任何人。這是個好的開始。\n\n她一定是想要更多卡法莓，但我們得給她一點事做，好消耗多餘的精力...\n\n我想到了！粗麻小徑！她可以在那邊打爛那些猴人，打上一整天！\n\n<刺莓轉身面對那隻魁梧的野獸。>\n\n漂亮姑娘，妳覺得呢？想打爛猴人嗎？！\n\n我想也是。來，拿我的應急用卡法之瓶餵她。她喜歡你。", progress = nil, completion = "哇喔！這真是太太太暴力了。\n\n我不確定這是我希望看到的情況…\n\n謝謝你了，我們似乎不小心和柯沓峰的恐懼之王形成了互利的友誼。", rewards = "瀑布足靴牡山獸皮護足夢境之靈脛甲平靜護脛屈心者足靴默葉長靴犛牛牧人脛甲峰頂守護者戰靴城牆看守者戰靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][30750] = {title = "滾下牆來！", objective = "殺死12個歐索弓箭老手或歐索火焰戰士。", description = "在城牆上的這些揚古正以火焰掩護下方的揚古。我不知道老秦在想什麼，但我希望你去解決這些弓箭手。\n\n好消息是，上頭這裡有玄牛的靈魂幫助我們。當他們變弱時，玄牛靈魂會把他們擊暈，你可以利用這點把他們都踢下牆去。\n\n你可以在門外找到那些弓箭手。", progress = nil, completion = "哈！我就愛看他們飛起來。做得好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30751] = {title = "可怕的犧牲", objective = "取得6桶揚古燃油。", description = "我有個主意…並準備好要做一個可怕的犧牲。\n\n儘管我很清楚，我們需要烈酒來讓我們的保衛者有氣力長時間保衛玄牛關…\n\n現在討論這件事實在太令人痛苦了，但是拜託你，當你上去保護長城時，收集幾桶他們用來點燃火焰箭的油。我們會用得上。", progress = "你拿到油了嗎？", completion = "好了。我要去準備下一步的行動。祝你好運，朋友。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30752] = {title = "不可思議！", objective = "和影潘哨兵談話來進入影潘僧院。", description = "等我們讓他們體會到眼前狀況有多嚴重後，我就不信這些警衛會不肯讓我們進入僧院。\n\n朋友，往東走去找僧院前的影潘哨兵，提出謁見的請求。我會跟你一道去。", progress = "真不敢相信！", completion = "不…這比我所能想像的更糟。連僧院本身都遭到入侵…", rewards = "生長看管人墜盒飲酒人護符熊心項鍊釀酒鬼墜飾熊心護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][30753] = {title = "跳上鯊魚", objective = "空手殺死一隻狂暴的暗礁鯊魚。", description = "在我的故鄉，只有一個方法可以殺死鯊魚，就是赤手空拳把牠打死!\n\n我在這個碼頭外丟下為數不少的魚餌，這地方馬上就會擠滿當地的暗礁鯊魚。跳到你看到的第一隻鯊魚身上，把牠宰了!", progress = nil, completion = "這可真是條大鯊魚，&lt;name&gt;!讓我印象深刻!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30754] = {title = "閃亮的誘餌", objective = "到釣手泊船處北邊的森林收集7隻太陽蟹。", description = "某些魚只會被亮光吸引。北邊的森林住著被當地熊貓人稱為太陽蟹的螢火蟲。\n\n你可以在這一帶的樹幹根部找到他們。帶一把太陽蟹回來給我，我可以拿來作餌!", progress = "有找到太陽蟹嗎?", completion = "這真是太好了，&lt;name&gt;。謝謝你的幫忙!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30757] = {title = "影潘宗主", objective = "幫塔蘭‧祝脫離仇恨之煞的控制。", description = "我們的宗主，塔蘭‧祝，已經被純粹仇恨所形成的煞給擊敗。整座僧院都陷落了!\n\n<class>，你一定得把他從這著魔的狀態解救出來。我最後一次見到他時，他在落花林中冥想。", progress = nil, completion = "謝謝你，&lt;class&gt;。我的憎恨都被清除了。\n\n你是影潘的英雄。", rewards = "憤怒思緒風帽擾亂安寧頭罩煩惱頭巾無盡焦慮兜帽反對者裹頭坐立難耐頭罩內部爭鬥風帽敵意頭盔不安躁怒頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][30759] = {title = "Sotelo's Quest", objective = "Use Sotelo's Plunger.", description = "Push the plunger.\n\nPUSH IT!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30763] = {title = "食人魚!", objective = "到喀撒朗蠻荒的喀撒朗河去釣5隻餓狼食人魚。", description = "有些魚非常難抓。餓狼食人魚就絕對屬於這一類的魚。\n\n但我運氣好，有你出現在這裡!測試一下你的釣魚技術，到西北邊的喀撒朗河去抓一些魚回來給我吧。", progress = "運氣如何?", completion = "看來你的手指都還在，做得好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30767] = {title = "孤注一擲", objective = "幫神真子拔刺。", description = "等等，你說什麼？他怎麼能這麼魯莽？把那艘船炸開太瘋狂了！他們可能會害死神真子，還拉我們一起陪葬。\n\n我知道時間不多了，但我們得想出另一個方法…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30768] = {title = "我丈夫...", objective = "在螳螂荒原的長陰哨站和蘇納‧默襲碰頭。", description = "林...\n\n我不在乎班、老秦甚至塔蘭‧祝說什麼。我要前往螳螂荒原。我或許沒辦法獨自救出林，但我不要坐在這裡枯等其他人趕上。\n\n等塔蘭‧祝打開通往他寶貝僧院的大門，我們會救出林。在那之前，我會在前頭偵察，確保他平安。", progress = nil, completion = "很好，看來其他影潘覺得是該跟上的時候了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30769] = {title = "第一波攻勢", objective = "殺死6名歐索銳角。", description = "既然我們花了時間評估敵人的弱點，是時候給揚古一記當頭痛擊了。\n\n登上西邊的臺地，面對歐索銳角。\n\n讓他們知道我們就在這裡，而且我們不怕他們的威脅。", progress = nil, completion = "做得好，&lt;name&gt;。我希望你沒對他們手下留情。", rewards = "蒼風肩鎧神廟守護者肩鎧歐索峰肩鎧高原獸肩鎧沼澤漫步者肩鎧金爪肩鎧移陸者肩鎧迷霧潛伏者肩鎧霧降肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][30770] = {title = "狂奔節", objective = "嚇唬8隻長毛犛牛或高原獸。", description = "任何軍隊都缺少不了補給線。\n\n敵人在西邊的營地裡牧養了一大群動物，是揚古大軍的主要食物來源。\n\n幸運的是，這區域的犛牛和牡山獸很容易受驚。\n\n進去摑打牠們一陣，然後等著看結果。", progress = nil, completion = "喔呵呵！我從這裡就能看見那些動物揚起的塵土。\n\n那些揚古說不定還搞不清楚怎麼回事。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30771] = {title = "收集瀝青", objective = "收集8份黑暗瀝青。", description = "歐索部族上戰場時，會為他們的矛和箭抹上易燃、難以熄滅的瀝青。\n\n這種可怕的武器不只能傷人，更能將敵人的家園夷為平地。\n\n當你到他們營地時，我需要你收集一些瀝青。\n\n我們會讓那些揚古看看什麼叫玩火自焚。", progress = "揚古可不不滿足於擊敗敵人。不，他們喜歡摧毀敵人並虐殺他們。", completion = "聞起來還很新鮮。\n\n做得好，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30772] = {title = "殺紅眼", objective = "殺死8名歐索掠奪者或歐索吐火者。", description = "揚古軍隊的主力就在我們前方。\n\n他們在這裡整頓大軍，以攻擊崑萊的村莊。\n\n如果我們立刻對歐索發動攻擊，就能削弱他們的主力。\n\n記住，我們在這裡多殺一個，就形同在家鄉多救一個人。", progress = nil, completion = "那應該能大幅削減他們的數量。\n\n我懷疑他們能否從這麼大的打擊中復原。", rewards = "霧降護腿迷霧潛伏者腿甲移陸者護腿金爪腿鎧沼澤漫步者長褲高原獸腿甲歐索峰褶裙神廟守護者腿甲蒼風腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][30773] = {title = "瀝青攻擊", objective = "用班的炸藥摧毀6臺歐索弩砲。", description = "揚古正用他們那些攻城弩砲摧毀我們長陰哨站和崑萊峰兩地的防禦。\n\n必須摧毀那些可怖的武器才行。\n\n帶著這些炸藥。我已在上面塗滿你收集來的瀝青。\n\n把他們丟到弩砲上，讓揚古嚐嚐自食其果的滋味。", progress = nil, completion = "很好，&lt;class&gt;。\n\n既然沒辦法躲在攻城武器後，他們就只能出來面對我們了。", rewards = "您能選擇下列奬勵中的一個：\n\n班的炸彈袋子\n\n您還會收到：\n\n班的炸彈袋子恆龍寶箱"}
MultiLanguageQuestData['tw'][30774] = {title = "解救遊俠", objective = "打開乾木牢籠來解救4名長陰遊俠和林‧默襲。", description = "我得交給你一項十分重要的任務，<name>。\n\n我的丈夫，林，就在歐索營地的某個籠子裡。他是我這世上唯一的希望。\n\n請替我找到他，將他帶回我的身邊，並盡力解救我們的影潘同袍。\n\n你應該能在歐索蠻卒身上找到那些籠子的鑰匙。", progress = nil, completion = "聽到林沒能撐過去真的令我很遺憾。\n\n蘇納受到的打擊很大。她終究會原諒我的。\n\n至於你救回來的其他影潘，我很高興看見他們平安回來。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30775] = {title = "流放者", objective = "殺死烏蘭戈、庫佟和霸泰德。", description = "有什麼好說的，陌生人？\n\n我和姜‧杜克交戰並落敗了。相信他會公平對戰的我是個傻子。\n\n如今，我的兄弟反過來對付我，而我淪落到這裡，和我的敵人交談。\n\n我知道你是來攻擊歐索的。\n\n我只請你去獵殺那三個背叛我的人。\n\n在我水裡下毒的烏蘭戈。破壞我長矛的庫佟。在我取得勝利時用匕首攻擊我的霸泰德。\n\n完成之後，我就能平靜地死去。", progress = nil, completion = "我很高興能看到那些懦夫死在你的手裡。\n\n這樣一來，或許我心中那燃燒的怒濤可以平息了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30776] = {title = "姜‧杜克", objective = "將影潘旌旗放在儀式祭品堆上，然後殺死姜‧杜克。", description = "這、是、戰爭。\n\n我會殺死每一個將林從我身邊奪走的人。每一個！\n\n我們會從歐索的領導者姜‧杜克開始。\n\n將這面影潘戰旗帶去插在他們營地中央。\n\n姜‧杜克將別無選擇，只能出來面對你。\n\n別對他手下留情，<name>。", progress = "姜‧杜克留給我們的記憶是用無辜者的鮮血寫成的。", completion = "姜‧杜克終於死了。\n\n成百，甚至上千條性命因為他殘暴的侵略而死去。\n\n儘管沒能在這裡見證他的死亡，他們還是會深深感謝你今日的英勇行為。", rewards = "霧降之索迷霧潛伏者腰帶移陸者護腰金爪扣環沼澤漫步者之索高原獸腰帶歐索峰腰帶神廟守護者束腰蒼風束腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][30777] = {title = "搜尋蘇納", objective = "抵達仇恨之惡後去找班‧熊心。", description = "我有壞消息。當我回來時，蘇納已經不在了。\n\n其他人說她帶著自己的東西，順路往東走，嘴裡叨唸著要獵殺揚古侵略的源頭。\n\n我不能放她獨自進入危險的地域。\n\n我已經整備好一隊士兵來向東推進。\n\n我們很快就要離開。準備好和影潘一起出發時就上車吧。你可以在那邊和我們碰頭。", progress = nil, completion = "嗯，我們抵達了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30778] = {title = "塵歸塵", objective = "在20名蒼風村民身上使用影潘火炬。", description = "若要在這裡紮營，我們就不能讓這些揚古屍體留在這裡腐爛。\n\n把這火炬帶著，點燃那些村民的屍體。\n\n火炬上的香氣應該也能淨化他們四周的土地和空氣。\n\n雖然是敵人，他們仍應該得到安息。", progress = nil, completion = "做得好，&lt;name&gt;。\n\n希望他們的魂靈前往更好的地方。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30779] = {title = "殺死食腐者", objective = "殺死8隻灰牙土狼。", description = "腐爛的屍體吸引了食腐肉的土狼。\n\n這些兇狠的生物不僅會透過食死屍散佈疾病，還會不分青紅皂白地攻擊。\n\n消滅這些野獸。雖然很不幸，但最終會是好事。", progress = nil, completion = "謝謝你，&lt;name&gt;。這是個令人不愉快的任務，但是必要的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30780] = {title = "圖騰研究", objective = "收集9個蒼風圖騰。", description = "當我們進入那村莊，我不由得注意到營地裡到處都是揚古圖騰。\n\n我懷疑這裡潛伏著黑暗之力，而這些圖騰就是引出他們的關鍵。\n\n你能幫我帶些圖騰來做進一步的調查嗎？我想要研究他們。", progress = "我相信那些圖騰會對我們有用。", completion = "我是對的！這些圖騰曾經用來儲存和傳導強大的魔法能量。\n\n我相信我能用它們達到同樣的效果。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30781] = {title = "揚古的最後喪鐘", objective = "帶蕭屠前往仇恨之惡的冒煙處。", description = "班要我去探查村莊，確認這裡發生了什麼事。\n\n我注意到東邊、西邊、西北邊和南邊都有煙升起。\n\n但我需要有個能信任的人來保護我。\n\n你覺得如何？想要幫我完成第一次的偵察任務嗎？", progress = "這裡一定發生了恐怖的事。", completion = "謝謝你的幫助，&lt;name&gt;。\n\n我們無法得知這裡到底發生了什麼事，但顯然有什麼東西讓揚古開始自相殘殺。\n\n什麼樣的力量能做到這種事？", rewards = "正午火炬黎明火炬黃昏火炬仇恨之鉗煞滅之刃影潘遊俠之弓仇恨之咬分割之鋒影潘遊俠之刃熊心木棒您會收到：\n\n正午火炬黎明火炬黃昏火炬仇恨之鉗恆龍寶箱"}
MultiLanguageQuestData['tw'][30782] = {title = "惡意之靈", objective = "殺死10個懷恨的靈魂。", description = "死去村民的靈魂現身了！我能感覺到從靈魂身上傳來的憎恨。\n\n<name>，我們必須自衛才有辦法存活。這是讓他們安息的唯一辦法。", progress = nil, completion = "做得好。我們不能為他們復仇，但至少我們終結了他們的憤怒。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30783] = {title = "被憎恨同化", objective = "使用和諧圖騰，從8名瘋狂的影潘遊俠身上逐出煞靈。擊敗沸騰憎恨獸來淨化你的盟友。", description = "我早該想到有煞的存在！\n\n只要繼續躲在和諧圖騰的保護範圍內，我們就能夠安全，但其他同胞就沒有那麼幸運了。\n\n煞的力量顯露時，他們被困在營地外面，現在他們開始自相殘殺！\n\n把我的圖騰帶在身上，放在一名發瘋的盟友身邊，淨化他們。但千萬小心。\n\n你或許必須和糾纏他們的黑暗作戰。", progress = nil, completion = "謝謝你。\n\n煞捕食軟弱和虛弱的人。\n\n如果我們不保持警戒，就連最強壯的成員都會屈服於煞的黑暗影響。", rewards = "您會收到：\n\n和諧圖騰恆龍寶箱"}
MultiLanguageQuestData['tw'][30784] = {title = "難以回頭", objective = "找到蘇納‧默襲。", description = "我們的一名遊俠回報，看見蘇納在西北邊的山丘上。\n\n知道她平安讓我很慶幸。我本來擔心她會在悲傷中做出什麼傻事。\n\n你能代替我去和她談談嗎？\n\n帶著這個圖騰。若你在路上遇見危險，它會派上用場。", progress = nil, completion = "什麼？她被仇恨之煞附身了？\n\n不！不！\n\n儘管我們意見不同，但她是我們的一份子。今天，影潘失去了一個最親愛的姊妹。\n\n她不會白白犧牲的。在擊敗仇恨之煞我絕不休止！\n\n蘇納，我向妳發誓！", rewards = "霧降長袍迷霧潛伏者外套移陸者護甲金爪胸甲沼澤漫步者長袍高原獸外套歐索峰護甲神廟守護者護軀蒼風護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][30785] = {title = "高仁前線", objective = "到螳螂荒原的高仁前線找影潘宗主塔蘭‧祝。", description = "藉由你的幫助，我們抑止了本地的魂靈。\n\n他們終於能安息了。\n\n但我們在這詛咒之地上的旅程，恐怕才剛剛開始。\n\n我得在這裡替一些重要的工作收尾，但我們很快就會出發。\n\n我需要有人先行向塔蘭‧祝大人報告我們會與他會合的消息。\n\n到高仁前線那裡找他。跟他說這裡所發生的事。", progress = nil, completion = "北方的營地那裡還好嗎？你帶來什麼消息？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30786] = {title = "矛穿我身，鎖困我靈", objective = "殺死囚禁歐爾比斯的薩滿，帝孟納魯克。", description = "我的命運註定了。揚古把這根矛刺進我的身側。我會因重傷而死。\n\n揚古用他們扭曲、汙穢的魔法將我囚禁起來。這種侮辱比傷我的矛傷更教人痛苦。\n\n我無法阻止我的死亡。但你...或許能幫我解除我所受的禁錮。", progress = nil, completion = "我自由了。\n\n必須阻止那些揚古。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30787] = {title = "火炬", objective = "取得6支迷霧薩滿的火炬。", description = "不久之前，揚古薩滿還會過來這裡和我們一起合作。如今，他們奴役了我的人民。\n\n如果我們拒絕接受，他們就殺了我們。\n\n揚古迷霧薩滿的魔法就在他的火把裡。拿走他的火炬，他就會變得一無所有。", progress = "這些火炬能幫助我復仇。\n\n我還沒屈服於這個傷口。我還來得及在死前完成復仇。\n\n還有時間。", completion = "這火炬...揚古曾用來和我，和我的族類交流。\n\n如今，他們用這些來毀滅我們。", rewards = "迷霧薩滿項鍊歐爾比斯墜飾泥沼墜盒復仇墜飾渴望護符您會收到：\n\n迷霧薩滿項鍊歐爾比斯墜飾泥沼墜盒復仇墜飾恆龍寶箱"}
MultiLanguageQuestData['tw'][30788] = {title = "苟格斯", objective = "將迷霧薩滿的火炬插入泥沼高地的泥炭堆來召喚苟格斯。", description = "揚古迷霧薩滿的領袖叫做賈黑許。他的力量名聞遐邇。\n\n我們族裡也有個人以力量出名。他的名字是苟格斯。\n\n苟格斯沉睡在泥沼高地的迷霧裡。幫助我召喚他，他會和我一起為我們的人民復仇。", progress = nil, completion = "苟格斯不會說你的語言，頂多會幾個字。我想我在這方面是獨特的。\n\n他謝謝你召喚了他。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30789] = {title = "阿空尼斯", objective = "將迷霧薩滿的火炬插入泥沼高地的泥炭墩來召喚阿空尼斯。", description = "要和賈黑許，揚古迷霧薩滿的領導者作戰，我必須有阿空尼斯在身邊幫忙。阿空尼斯的悍勇舉世無雙。\n\n他就在泥沼高地的迷霧之下休息。找到他休息的地方，用這些火把喚醒他。", progress = nil, completion = "有阿空尼斯在身邊，想輸都很難。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30790] = {title = "苟格斯的飢餓", objective = "取得10份吠藤。", description = "苟格斯的力量很強，但他需要吃飽喝足才能發揮。\n\n泥沼高地的吠藤灌木有著沉重、飽含纖維的枝幹，應該滿足他的食慾。", progress = "苟格斯的飢餓十分強烈。", completion = "我們距離目標更進一步了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30791] = {title = "阿空尼斯的乾渴", objective = "取得4份凝結的水貍之血。", description = "阿空尼斯用無人能敵的狂怒來戰鬥，但長期待在迷霧之下讓他變得虛弱。\n\n沼澤裡有很多水貍，牠們的體內有滋補的血液。帶回足夠讓阿空尼斯重振精神的血液來。", progress = "我們的準備接近完成。", completion = "距離完成任務又更進一步。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30792] = {title = "歐爾比斯的消逝", objective = "走過泥沼高地的迷霧間歇泉來取得8份濺血迷霧。", description = "我知道死亡會來臨。但我不知道它來得這麼快。\n\n我必須爭取時間。泥沼高地的迷霧溫暖而芬芳。這種霧對我們來說很有營養。\n\n盡你所能地將這種霧裝進...壺裡、瓶子裡或是包包裡，並帶回來給我。我能用它來多維持一會兒形體。", progress = nil, completion = "我曾跟你說，這傷口會為我帶來死亡。儘管你幫我爭取了時間，死亡仍在不遠之處。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30793] = {title = "霧的機會", objective = "殺死歐索的賈黑許。", description = "是出擊的時候了。\n\n苟格斯、阿空尼斯和我會過去東邊，進入賈黑許的領域。到那裡和我們碰面，做好戰鬥準備。\n\n今天，我們要回復我族的榮耀。", progress = nil, completion = "我的名字將被遺忘，但我的行為不會。\n\n你的也不會，&lt;name&gt;。", rewards = "霧降披肩迷霧潛伏者肩甲移陸者肩甲金爪肩甲沼澤漫步者襯肩高原獸肩甲歐索峰肩甲神廟守護者護肩蒼風護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][30794] = {title = "緊急護理", objective = "治療廖賢者，使他回復狀態。", description = "我…還活著…但也只剩半條命了。他們把其他人都殺了。我的朋友…和家人…\n\n我必須回村莊去…但我活不久了，也無法靠自己的力量行動…你是醫者嗎？我…我的小屋裡有一個治療藥劑…搜索我屋裡的東西。或者如果你懂治癒法術的話也可以使用。", progress = nil, completion = "謝謝你。但我想…在我能夠回村莊前，我需要拜託你多做幾件事。我無法離開我朋友與家人的屍體。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30795] = {title = "保持聯繫", objective = "在帝王谷使用霸凶的舌頭。", description = "<name>，霸凶的舌頭應該可以讓我們進行遠距離通信。\n\n如果這個聖物運作的方式跟我想的一樣，那麼在你到帝王谷進行偵察的時候，我應該可以留在這裡繼續冥想。\n\n米什會帶你到山谷的邊界，如此便能測試我的理論是否正確。我絕不希望你在墓地時無法跟我聯繫。那實在太可怕了！", progress = nil, completion = "好極了！這聖物有效！\n\n看來帝王谷裡進行的活動比我預期的還要多。我們得搞清楚魔古為什麼要打開陵墓，這件事非常重要。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30796] = {title = "打破輪迴", objective = "摧毀5個受折磨的靈魂。", description = "這些靈魂一定是在墓地開啟時被釋放出來的…\n\n死亡並不是這些魔古的終站，相反的，死亡只是通往新軀體道路上的一個休息站。縛靈者使用卑劣的法術，將靈魂從一個軀殼轉移到下一個。\n\n被困在墓中多年讓他們變得迷惑。我們得趕緊摧毀他們，不然迷惑將轉為憤怒。甚至，他們可能會找到新的軀殼。", progress = nil, completion = "你幫了他們一個大忙，&lt;name&gt;。\n\n被困在生與死的交界處是殘酷的命運。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30797] = {title = "歷歷在目", objective = "從攤開的書上撕一頁下來，帶去給博學行者阿洲。", description = "曾有個儀式在這裡舉行，而從現場的情況看來並不是很成功。\n\n被遺棄的物品當中有一本攤開的書，你並不認識書中的文字。\n\n把整本書帶在身上也許會有點困難，撕一頁下來應該就夠了。如果你能把這一頁帶去給博學行者阿洲，或許他能告訴你書中寫些什麼。", progress = "<name>，你找到什麼？", completion = "&lt;name&gt;，這段文字的確很古怪…\n\n似乎是在孟朝時代寫下，其中有些符號又不正確。雖然看起來非常像魔古文，但我不認為這是魔古所寫。\n\n我得花上一點時間翻譯。繼續前進，看你能不能找到其他東西。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30798] = {title = "破壞帝王之盾", objective = "阻止秘密之墓中的縛靈儀式。", description = "魔古多年來一直處於一盤散沙的狀態。現在他們出現在山谷的目的已昭然若揭。\n\n有了這麼多無法安息的靈魂，他們可以利用埋在各個墓中的守護者打造自己的軍隊。若讓他們和贊達拉的部隊合流，這將變成一場災難!\n\n秘密之墓裡頭住著被稱為帝王之盾的精銳戰士。絕不能讓他們復活!你可以在西南邊最高的山丘上找到這座墓。", progress = nil, completion = "魔古與贊達拉試圖讓雷王復活？！\n\n&lt;name&gt;，我們絕不能讓此事發生！雷王一旦復活，這片土地便會滅亡。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30799] = {title = "暗影之墓", objective = "到暗影之墓收集神朝石板、魏朝石板和羌朝石板的拓文。", description = "鑒於你在祭壇上發現的神物，我猜他們試圖進行縛靈儀式。\n\n絕大多數涉及縛靈的文本都被鎖在暗影之墓。或許我們能在那兒找到答案。\n\n搜尋任何可以幫上忙的東西，你會在接近祭壇的第一個斜坡上找到暗影之墓。", progress = "你有在暗影之墓裡找到什麼嗎？", completion = "這些石板詳細記載魔古與贊達拉結盟的歷史，最遠可以追溯到魔古開朝皇帝的時代。\n\n看來他們似乎重新結盟了，但為什麼是現在？", rewards = "縛靈者指環炎怒戒指鑲玉徽記藍山徽記破封之墓指環您會收到：\n\n"}
MultiLanguageQuestData['tw'][30800] = {title = "偷走他們的雷王", objective = "找到雷神石板的底部碎片，並把碎片拼回雷霆石板上。", description = "我們唯一的希望，就是搶在他們之前找到雷王的遺體。他一定是被埋在征服者之墓裡。\n\n接近他的遺體絕非易事，<name>。為了嚇阻盜賊，毫無疑問會有守護者與其他不大友善的驚喜在保護墓地。\n\n進去之後，我們必須弄清楚他的遺體到底放在哪裡。", progress = "你弄清楚雷王遺體藏在哪裡了嗎？", completion = "我們很幸運，他們「目前」還沒拿到雷神的遺體。\n\n贊達拉在得到他們想要的東西之前絕不會放棄。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30801] = {title = "歷史教訓", objective = "在征服者之墓閱讀雷霆石板。", description = "雷王是個兇惡的皇帝，而有了贊達拉在他身邊，更是沒人能阻止他。他的復活一定會讓這片土地回到動盪與苦難之中。\n\n你一定要找出他的遺體，並把遺體帶到安全的地方去。雷霆石板應該能幫你了解怎麼進入他的墓穴。", progress = nil, completion = "他們需要把遺體移到一個安全的地方。我們必須跟著他們！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30802] = {title = "追雷", objective = "在一個贊達拉戰士身上找到沾血顯露的秘圖。", description = "我們必須弄清楚他們打算把雷王的遺體帶去哪裡。他們不可能在帝王谷讓雷王復活。他們需要到某個偏遠且安全的地方。\n\n看來，離開這裡也會是一個挑戰...\n\n殺出一條路，並搜尋與遺體有關的資訊。", progress = "有找到任何跟他們所在地相關的資訊嗎?", completion = "這是黑暗的贊達拉血魔法。一旦我們用完這張地圖，就要燒了它。\n\n地圖顯示，他們往海岸外一個名叫驟晴的小漁村去了。那裡的村民或許可以幫我們找到贊達拉。只希望那些村民還活著...", rewards = "您能選擇下列奬勵中的一個：\n\n博學行者印記博學行者紋章博學行者符印博學行者勳章博學行者徽記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30804] = {title = "恐懼之王", objective = "殺死恐懼之王。", description = "我再也忍受不下去了。我的妻子，老天保佑她，她將她所有的心力與靈魂都注入這個牧場，才使牧場有現在的規模。\n\n那些揚古來了個自命不凡的領導者。只要你能把他猥褻、臭氣沖天又一無是處的臉上那種得意的微笑打掉，我會付你豐厚的賞金。", progress = nil, completion = "咿哈！我就知道你這個&lt;race&gt;很行。當他倒在地上時一定發出了令人滿意的「噗通」聲。", rewards = "卡法緞質足靴卡法皮護足夢境之靈長靴卡法光潔護脛卡法絲質足靴卡法皮甲長靴犛牛牧人長靴卡法重型戰靴卡法裝甲戰靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][30805] = {title = "正義", objective = "殺死裂肉首領與6個南海傭兵。", description = "大部分傭兵在搶劫我們之後就離開了。\n\n但其中一個…在其它人搶光我們的東西之後，他用武器刺穿我們剩下的人。只為了運動一下！\n\n從這些墮落傢伙身上討回正義。或許他們的死訊可以提振我的精神，讓我繼續活下去。\n\n你可以在西邊找到他們。", progress = nil, completion = "啊…他們死了。我已經開始感覺精神提振起來了。很快我就會有力量回村莊去了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30806] = {title = "生命的香氣", objective = "取得1個乳白藍蟹殼與8個遭竊的熊貓人香料。", description = "許多生命在這裡消逝。我們得適當地向他們致敬，這意味著我們得收集一些生命薰香。\n\n它不只是聞起來很香而已。它有讓人恢復元氣的效果，甚至能幫助植物生長。或許我只要聞一聞這種香氣，就能夠恢復過來。\n\n這些成分都可以在附近的生物身上找到。除了香料，香料都被那些掠奪村莊的傭兵偷走了。", progress = "我在你身上聞到的氣味是生命薰香的原料嗎？還是說…你最近沒洗澡。", completion = "太美了，太美了。若不需要埋葬我們的朋友當然是最好，但如果我們必須埋葬他們，能夠為他們舉行適當的儀式是件好事。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30807] = {title = "為殞落之人來到瀑布", objective = "取得3塊瀑布沖磨過的石頭。", description = "我不希望羞辱我的朋友們，把他們遺棄在無名墓。\n\n然而，我們從不曾一次埋葬這麼多人，而我的狀況也無法出去收集材料。\n\n拜託你，沿著路往南走，到那個環抱山陵的湖去。你會在那裡的瀑布下找到被水沖刷得光亮盈潤的石頭。它們很適合拿來當墓石。", progress = "你把石頭帶來了嗎？", completion = "很好。謝謝你。這麼一來，我便可以給我的同伴舉行一個適當的葬禮", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30808] = {title = "咕嚕摩的好運", objective = "找到8個遭竊的幸運星。", description = "揚古們搶走了我們的幸運星!帶著長矛的壞壞騎兵沿著粗麻小徑衝下來把我們兄弟的整個車隊擄走。\n\n這真是很不好的厄運。如果揚古發現幸運星的秘密，所有的咕嚕摩都要遇到麻煩。\n\n到魯秦火焰營地找回我們的幸運星，我們會報答你很多好運。", progress = "幸運星是帶著極大好運的東西。揚古還不懂得如何使用幸運星...目前為止。", completion = "喔耶!我們的幸運星。向咕嚕摩的朋友送上許多感謝與好運!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30814] = {title = "上門一腳", objective = "殺死8名歐索衝鋒者。", description = "<影潘宗主塔蘭‧祝鋼鐵般的視線立刻緊盯著你。>\n\n<class>，你身上有許多過去戰役的印記。\n\n很好!我們需要更多像你這樣的戰士來鞏固住前線。\n\n我們好不容易在這建起一個根據地，但揚古十分渴望將我們給消滅。\n\n如果你有心證明自己的價值，到山丘下去告訴揚古，我們絕不退卻。", progress = nil, completion = "很好。我看得出你很能幹。\n\n我希望接下來也能仰賴你的天賦。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30815] = {title = "我的死期", objective = "拔出歐爾比斯身上的矛。", description = "我決定拔出我身上這柄矛。\n\n為此，我需要你的協助。你的手比我的有力氣。", progress = nil, completion = "拔出這支長矛後，我的死期就確定了。\n\n這並不讓我感到害怕。\n\n我寧願儘早死去，也不願敵人的武器插在我身上苟活。", rewards = "泥沼釘錘翠鳥之死歐爾比斯之盾潛伏迷霧之盾扭曲之刃迷霧薩滿鉤刺您會收到：\n\n"}
MultiLanguageQuestData['tw'][30816] = {title = "查看", objective = "到崑萊峰的驟晴海岸找廖賢者。", description = "食人妖來的時候，還帶著他們的傭兵…「朋友」。我看到他們從我們身旁經過，往西北方的釣魚營地去了。我的表兄是個醫者，他就住在那裡。你能不能去查看他和他的村莊是否安好？", progress = nil, completion = "啊...我表弟的擔心是很明智的...我一點也不好...", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30819] = {title = "照料遺體", objective = "去找李海並告訴他葬禮的事。", description = "非常感謝你，朋友。在這場悲劇之後，幸運之神仍對我們微笑而派了你過來，這真是件好事。\n\n你為我死去的朋友們討了公道，並取回向他們致敬所需的材料。我會集中他們的遺體，把葬禮所需的材料準備好，然後跟你到墓地碰頭。\n\n在這段時間裡，請你回去找我的表弟，並拜託召集村民舉行葬禮。", progress = nil, completion = "我明白了...那裡發生的事真是悲慘。我們會在墓地與你碰頭，向亡者致敬。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30820] = {title = "葬禮", objective = "出席葬禮並點亮生命薰香。", description = "如我所言，我會集合所有村民，我們全都會出席葬禮。\n\n你做了這麼多事來向我們的朋友致敬，我們覺得點亮生命薰香，並引導他們的靈魂前往彼岸的最佳人選，就是你。", progress = "你必須點燃薰香來對死者表示敬意。", completion = "很好。我們開始舉行葬禮吧。", rewards = "瀑布披肩牡山獸皮肩甲夢境之靈肩甲平靜肩甲屈心者襯肩默葉肩甲犛牛牧人肩甲峰頂守護者護肩城牆看守者護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][30821] = {title = "碾壓粗麻", objective = "到柯沓營地找柯沓峰的恐懼之王談話並騎在她身上，然後到粗麻小徑殺死100個猴人。", description = "好啦，是帶柯沓峰的恐懼之王出去「散散步」的時候了。\n\n我們幫她釀了兩壺卡法莓，現在她動力全開！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30823] = {title = "停下來", objective = "到柯沓峰殺死12隻吃了卡法後發瘋的公山羊。", description = "我在柯沓營地的表哥可搞砸了。真的是搞砸了。\n\n他懶得用手把卡法莓的籽挑出來，但他注意到山羊吃了卡法莓之後會把籽大出來…大約需要一天的時間。\n\n他把他所有的卡法莓拿去餵柯沓峰上的山羊，哪知道牠們全瘋了！看到會動的東西就一股腦地衝過去。\n\n咕嚕摩本來可以安心地在柯沓峰採卡法，現在被那些山羊害得完全不行。你能幫幫忙嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30824] = {title = "卡法美食", objective = "到柯沓峰標記15個消化後的卡法「礦點」。", description = "這真是個瘋狂的主意：山羊吃掉卡法莓，種子再自己排出來。\n\n卡法柯沓原本就很稀有又值錢，但是我表兄發明的消化後的卡法，才是美味中的美味。\n\n只是現在都完了。鋒豆叔叔火冒三丈，山頂一團混亂。我們只有收集剩下的消化後的卡法，還有記得別讓同樣的事再度發生。\n\n我不會要求你去採集它。這種瑣碎的任務不適合一位英雄。你只要把它標記起來，這樣山上安全的時候，我們就可以輕鬆找到它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鋒豆卡法"}
MultiLanguageQuestData['tw'][30825] = {title = "柯沓特調", objective = "到柯沓峰收集100顆卡法柯沓莓。你可以在山邊的灌木叢，或是雪人洞穴裡找到它們。", description = "柯沓峰以其山上的卡法灌木聞名。沒有其他植物能在這種高度下存活。\n\n咕嚕摩藉著出售卡法柯沓特調致富，但是多虧了我的表弟，現在這變成一門危險的生意。他的小技倆讓山上的野生動物瘋狂迷上卡法。\n\n現在有那群山羊在那裡嚼個不停，加上雪人也愛把它們囤積在洞穴，卡法柯沓變得比從前更稀少了。\n\n要是你能從柯沓峰上帶幾顆莓子下來，鋒豆叔叔一定會好好犒賞你。\n\n哪，拿個樣本。吃了它。自己感受一下卡法的威力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30826] = {title = "麻煩醞釀中", objective = "到柯沓峰的山洞裡殺死5個吃了卡法後發瘋的雪人。", description = "柯沓峰上有許多雪人。真多。通常都不大危險。通常他們只吃山羊。\n\n最近柯沓營地的蠢蛋羊毛表兄餵山羊吃卡法莓，雪人又吃山羊。\n\n現在他們暴躁，古怪，睡很多但看起來總是沒睡飽。典型的卡法成癮症。\n\n我很確定，他們沒多久就會為了找更多卡法莓而從山洞裡跑出來。\n\n到時候我們就全都有麻煩了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一杯卡法"}
MultiLanguageQuestData['tw'][30827] = {title = "潛藏的事物", objective = "和雅里亞‧賢語者談話來開始儀式。\n\n然後，啟動仁慈圖騰、靜心圖騰和寧靜圖騰。", description = "若我的懷疑沒錯，這地方仍殘留著某種黑暗勢力。\n\n不管當時出了什麼事…都不會是自然產生的。\n\n即使是揚古，也沒有野蠻到將自己的同族屠殺到…這種程度。\n\n我會用你帶回的圖騰來施行一個淨化儀式。\n\n我需要有人在儀式中幫助我。當你準備好時知會一聲。", progress = nil, completion = "我們看到了憎恨的真正面貌！\n\n一切都說得通了。這是煞的傑作。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30828] = {title = "淨化湖泊", objective = "到墨鰓湖為水語者郭萊指出腐敗的池子，讓他知道你準備好在他完成淨化儀式時保護他。", description = "最近，曾從梅體內竄出的那種陰鬱物質在湖裡湧冒出來，匯聚成池。\n\n我會跟你一起到湖那邊去。若你準備好讓我清理哪個腐敗的池子，把它指出來。\n\n你得負責解決從池子裡跑出的任何東西，並在我完成儀式前保護我。", progress = "湖水得到淨化了嗎？", completion = "我可以感覺到…湖水的腐敗已清除，至少目前這種腐敗不會繼續擴散。\n\n但我們還有一件事得做。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30829] = {title = "霸凶的舌頭", objective = "協助博學行者阿洲對霸凶的舌頭使用縛靈儀式。", description = "$p，謝謝你過來。我很抱歉搞得這麼神秘，但我不能冒險讓魔古注意到我在這裡的工作。\n\n他們在谷中搜尋著什麼東西，掠奪他們先王的墳墓來取得強力的聖物。\n\n在逃出之前，我沒能找到機會長時間觀察他們，但我設法取得了一個聖物。\n\n霸凶的舌頭可以讓我們在遠距離下安全的通信，但只有在我和它建立連結之後才行得通。\n\n我已經準備好要開始了，就等你了。", progress = nil, completion = "祖安這麼急於取回這項遺物，想必它具有很強大的力量。\n\n一想到他們還能在這些墓穴裡找到什麼就讓我感到害怕…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30834] = {title = "父與子的重逢", objective = "到崑萊峰墨鰓湖的東南岸找商人阿席與吳平。", description = "他們還活著？我父親還活著！\n\n我以為我們全都會葬身在這座恐怖的湖裡，死在那些精神錯亂的錦魚人手裡。\n\n我會想辦法回去，回營地跟我碰頭吧。", progress = "我的兒子!他還活著!", completion = "你找到他了!我所能給你的就這麼多了，這些還不足以感謝你幫我找到兒子。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30854] = {title = "拉博追踪任务", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30855] = {title = "夏虎的墮落", objective = "擊敗夏虎。他會出現在水語者的聖所，亦即崑萊峰的墨鰓湖中央的島上。", description = "我可以聽見湖的聲音，它已被淨化了。\n\n然而，在我們擊敗夏虎之前，我的人民歷史中的這一章，永遠不會完結。\n\n他撤退到湖中央的島嶼，褻瀆我們最神聖的場所。\n\n千萬小心，他是很強大的。但我們已經完成了這麼多，我相信我們會比他更強。", progress = nil, completion = "謝謝你，&lt;name&gt;。你已確保腐敗不會再蔓延，並讓我那些沒有受到污染的人民能夠找一個新的村莊繼續生活。\n\n我們的歷史會延續下去。你所做的超出我們的期望。\n\n謝謝你，朋友。", rewards = "瀑布腕輪牡山獸皮束腕夢境之靈臂環平靜護腕屈心者腕輪默葉裹臂犛牛牧人腕甲峰頂守護者臂鎧城牆看守者護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][30879] = {title = "第1回合：酒仙倩妮", objective = "打败酒仙倩妮。", description = "欢迎参加勇者比武大会，挑战者！今天我们要看看潘达利亚的英雄们到底有多厉害。\n\n你的第一个对手正在东边的凉亭下等着你呢。打败她，你就能晋级下一轮。\n\n为了力量而战！为了荣誉而战！", progress = nil, completion = "做得好，挑戰者。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30880] = {title = "第1回合:街頭霸王", objective = "擊敗街頭霸王。", description = "挑戰者，歡迎來到我的勇士聯賽。潘達利亞上最勤苦修業的各路英雄，將在今天面臨力量的考驗。\n\n你第一個對手在東方瞭望台下等你。擊敗她，你就能進入下一回合。\n\n帶著力量和榮耀戰鬥吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30881] = {title = "第2回合：聪明的阿西约和肯肯", objective = "击败聪明的阿西约和肯肯。", description = "你可能已经知道你接下来的对手是谁了。他们刚来的时候争执不休，所以我让他们俩搭档。\n\n一来让他们了解友谊的力量，二来也是给我找点乐子。\n\n到北边的东竞技场去，打败锦鱼人和猢狲。\n\n别对他们手下留情，得教他们学会并肩作战。", progress = nil, completion = "可惜，這兩個傢伙還沒學到教訓。無所謂。我很肯定他們會隨著時間增長智慧。\n\n同時我要恭喜你獲勝。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30882] = {title = "第2回合:康恩‧藤杖", objective = "擊敗康恩‧藤杖。", description = "你的下個挑戰者是藤杖家族的人。他們的血液裡天生流動著力量。我記得曾有一整個世紀的冠軍都是藤杖家族的人。\n\n不要有壓力，小<race>。\n\n到北邊的東方競技場面對這個年輕的挑戰者。親身體驗力量是繼承而來，還是努力得來的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30883] = {title = "第3回合：摔跤手", objective = "打败摔跤手。", description = "你的下一位对手是我最钟爱的。他的力量来自与生俱来的蛮力和他果断的性格。\n\n而且，他还戴着一个面具。\n\n你准备好了就去西部竞技场会会他吧，祝你好运。", progress = nil, completion = "打得好，挑戰者。那個對手很強。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30884] = {title = "前線的後方", objective = "到濕土陷坑找陶氏。", description = "自從我不在崑萊，這個防禦據點就一直處於人手不足和物資缺乏的狀態。我們得在找到仇恨之煞的蹤跡前，讓這裡回歸正軌。\n\n陶氏是我最好的手下。我將她派去北邊調查螳螂人穿越防禦據點的謠言。我需要值得信任的人過去和她一起找出我們防禦上的漏洞。\n\n如果關於你的報告沒錯，我應該能放心把這項任務交給你。對吧，<class>？", progress = nil, completion = "你看起來很能幹。塔蘭把最好的派來給我。我喜歡。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30885] = {title = "第3回合:砰砰大師", objective = "擊敗砰砰大師。", description = "你的下個挑戰者是在海邊發現自己的力量。特別是一個上頭標著「炸藥」的盒子。\n\n他也證明，若將他找到的力量做為個人使用，會具有致命的威力。\n\n你準備好的時候，到西方競技場去找砰砰大師。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30886] = {title = "Example Pandaren Race Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30887] = {title = "不受歡迎的入侵者", objective = "在陶氏的幫助下殺死12名柯克席克深入斥候。", description = "那些是螳螂人的斥候。高仁的防禦據點應該要將他們阻擋在螳螂荒原的東側之外。如果坐視他們越過防禦工事，我們或許會失去此地的根據地。\n\n把他們清理掉吧。我會助你一臂之力。", progress = nil, completion = "這就是他們通過的地方，東邊的隘口。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30888] = {title = "防禦缺口", objective = "使用影潘照明彈，並殺死10名柯克席克遺香者。", description = "通常，只要少數斥候就能守住這道隘口。從牆上可以監視到大部分的區域，所以弓箭手可以摧毀任何打算突破這裡的螳螂人部隊。問題是，眼前大多數弓箭手都還在關口那裡戰鬥著。\n\n把這照明彈帶去，它能幫你找到趁我們監視薄弱時潛入的那些螳螂人。殺光他們。不能讓他們留下引領螳螂人大軍深入荒原的蹤跡。", progress = nil, completion = "穿過的敵人比我想的更多。我或許得留在這裡清理一陣子。\n\n你做得很足夠了，&lt;class&gt;。謝謝你。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30889] = {title = "設置陷阱", objective = "重設8個影潘尖刺陷阱。", description = "幸會，<class>。我們沿整個隘口設下陷阱，幫助我們捕捉潛過路障的螳螂人，但他們的數量太大，大多數陷阱都被觸動了。\n\n陶氏說你在外面時，或許能幫忙重設一些陷阱。你願意嗎？", progress = nil, completion = "我們營地這邊用得上像你這樣能幹的男子漢。謝謝你的幫忙，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30890] = {title = "看守不懈", objective = "傳遞返回命令給斥候魏秦、斥候隆、斥候瑛和斥候潔甘。", description = "我聽說我們的斥候不眠不休地在淺階小徑執勤兩天多了。怪不得螳螂人會潛過來。就算是最專注的斥候也會在這樣的勤務中分神。\n\n我想請你過去那裡，傳遞讓他們立刻回來休息和進食的命令。我會安排新的執勤者。", progress = nil, completion = "謝謝你，我很快就派新的斥候到他們的崗位。", rewards = "淺階小徑戒指警惕之眼戒指忠心斥候指環陶氏徽記看守不懈徽印您會收到：\n\n淺階小徑戒指警惕之眼戒指忠心斥候指環陶氏徽記恆龍寶箱"}
MultiLanguageQuestData['tw'][30891] = {title = "部隊治療", objective = "收集10朵紫香櫞。", description = "新面孔！很高興遇見你。我是賽普堤。我負責幫助影潘戰鬥。\n\n螳螂人身上有種能穿透皮膚，感染血液的毒。若不治療，會讓人緩慢、痛苦地死去。\n\n我需要紫香櫞的花粉。能採集這種東西的最近地點，在戰線北邊的濕土陷坑。如果你剛好往那邊去，能幫我帶一些回來嗎？", progress = "正確混合之後，這種花的花粉可以毫無副作用地消除體內的毒素。", completion = "太棒了。而且保存得很好！\n\n謝謝你，仁慈的&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30892] = {title = "幫他們恢復", objective = "治療8名受傷的影潘黑衣衛。", description = "<name>，我需要你的幫忙。漫長的勤務之後，我們封鎖線南端的戰士都戰鬥到筋疲力竭，還有很多中了螳螂人的毒。\n\n我們需要更多人來照料傷者。我用你帶給我的草藥做了一些繃帶，但若你懂得治療技巧，用它們來治療或許更有效率。\n\n拜託，<name>，幫我們的人幫他們恢復，如此他們才能平安回來。", progress = nil, completion = "許多戰士都欠你一命。我向你表達最深的感謝，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30893] = {title = "無盡蟲群", objective = "在高仁前線殺死12名柯克席克攻擊者。", description = "高仁在南方前線的人需要幫助。如果你想幫助影潘，那裡是你該去的地方。", progress = nil, completion = "前線這邊的人對你越來越尊敬了。顯然你知道該怎麼戰鬥。", rewards = "霧降手套迷霧潛伏者手套移陸者護手金爪手套沼澤漫步者手甲高原獸手套歐索峰護手神廟守護者護手蒼風護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][30894] = {title = "翻找遺體", objective = "取回20個柯克席克肢體。", description = "我還有另一項任務要交給你，<name>，儘管這任務十分殘酷。我真的需要好好研究螳螂人的毒，但那代表我需要更多第一手資訊。\n\n當你前往南方戰場時，能不能幫我帶回一些螳螂人的肢體，讓我檢驗他們完整的毒腺。", progress = "我希望能找到永遠解決螳螂人毒的方法，讓我們的人從一開始就不被影響。這需要一點時間才能完成。", completion = "這些的狀態非常完整！謝謝你，&lt;name&gt;！\n\n你知道，我曾試著取出他們的毒素，做成我們可以使用的形態。或許你不信，我甚至想出幾種用在法術裡的方法。你想要試試嗎？", rewards = "您能選擇下列奬勵中的一個：\n\n驅逐毒刺\n\n您還會收到：\n\n驅逐毒刺恆龍寶箱"}
MultiLanguageQuestData['tw'][30895] = {title = "克難彈藥", objective = "從琥珀沼澤取得16個烈性恐怖之球。", description = "我有另外一項工作要給你。\n\n我們用來收拾一大群螳螂人的龍砲快要沒彈藥了。營地的砲手用西邊山脊上的環狀種子做出克難式的爆裂物。\n\n數小時前，他們派出幾個小師弟去收集，但他們從此就失去聯絡。我想要派更有能力的人去確實解決這件事。\n\n你是我所需要的<男子漢/女勇士>嗎？", progress = "比我想像的更快回來。你有帶回種子嗎？", completion = "有個我能倚靠的&lt;class&gt;真好。", rewards = "蒼風窄褲神廟守護者窄褲歐索峰腿甲高原獸窄褲沼澤漫步者窄褲金爪窄褲移陸者褶裙迷霧潛伏者窄褲霧降窄褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][30896] = {title = "小賊和麻煩精", objective = "殺死10個激動的蕁膚精。", description = "我死都抓不到那些小兔崽子。\n\n盡量把他們都宰掉。記得看緊你身上有價值的東西，他們最喜歡偷走所有沒被綁緊的玩意。", progress = nil, completion = "看來你動作比我快些。好吧，謝啦。\n\n我會試著趕在大家還沒翹辮子之前撿完珠子，帶回營地去。", rewards = "您會收到：\n\n易爆球恆龍寶箱"}
MultiLanguageQuestData['tw'][30897] = {title = "落入惡徒之手", objective = "取回趙師弟的劍。", description = "聽著…嗯…這真的很尷尬。我放下我的劍去收集珠子大概才一秒吧。一秒！一個巨大的妖精就不知道從哪裡蹦出來把它摸走，往西邊的裂口那跑去。\n\n沒了劍我不能回去營地。失去武器可是讓人被踢出影潘的捷徑。\n\n拜託，你能否試著找出這巨大的妖精，把我的劍拿回來？這對我意義重大。", progress = "我母親警告過我會發生這種事…", completion = "你…你真是個救星！真的。\n\n太謝謝你了！", rewards = "您會收到：\n\n趙家餅恆龍寶箱"}
MultiLanguageQuestData['tw'][30898] = {title = "截斷蟲群", objective = "用高仁之龍發射器殺死50隻螳螂人。", description = "自從你離開前往裂口那裡，螳螂人的數量就不斷上升。讓我們好好利用你收集來的這些珠子吧。\n\n到防禦據點那裡，負責操作其中一尊大砲。別放過任何一隻。", progress = "在我有生之年，我不曾記得他們這麼大批地聚集在一起。", completion = "我們的工作還沒結束…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30899] = {title = "在武藝精湛的手中", objective = "把影潘弩箭捆帶去給鷹大師砮龍。", description = "<name>，帶著這些弩箭，到西南邊的遠方峭壁交給鷹大師砮龍。\n\n砮龍是武豪公認的神射手。這幾個月的防線能守住，都要歸功於他的努力。我希望你能跟他一起工作，自己評斷看看。他或許是我們狩獵團隊所需的最後一個影潘。", progress = "另一波飛行者要來了。準備好。", completion = "裂口的另一邊有許多動靜…某個大傢伙要來了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30900] = {title = "悚然荒野的恐怖之王", objective = "擊敗悚然荒野的恐怖之王諾瓦卡斯。", description = "這玩意兒真大！\n\n防守前線的影潘從沒受過關於這玩意兒的訓練…我們過去自個兒把它料理掉吧。", progress = nil, completion = "就是你。你跟我一起走。\n\n我從沒見過有人能在戰場上做出那種表現。面對仇恨之煞的時候，我會需要像你這樣強大的&lt;class&gt;。", rewards = "高仁戒指恐懼指環塔蘭‧祝徽印諾瓦卡斯之戒前線指環您會收到：\n\n高仁戒指恐懼指環塔蘭‧祝徽印諾瓦卡斯之戒恆龍寶箱"}
MultiLanguageQuestData['tw'][30901] = {title = "沿著南方前線", objective = "跟塔蘭‧祝與陶氏一起前往夕光谷地。", description = "我正和陶氏一起前往西邊，尋找我所能找到最強壯的人來對抗仇恨之煞。\n\n我希望你跟我一起走。", progress = nil, completion = "快點把這解決掉，這樣我們才能過橋。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30902] = {title = "第4回合:風毛大師", objective = "擊敗風毛大師。", description = "做得好，挑戰者。你已來到最後的回合。\n\n你最後的對手是一個強大的御風大師。多年來他一直保護他的人民，而且不只一次坐上冠軍寶座。\n\n你準備好的時候，到大競技場去面對風毛大師。\n\n挑戰者...祝你好運。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30907] = {title = "第4回合:蜥蜴鐵三角", objective = "擊敗傷奇思、補里思和坦奇思。", description = "現在這是最後回合。我為你選擇了三個挑戰者。這看起來或許不大公平...不過那是對弱者而言。你不是弱者，沒錯吧?\n\n到主寺的大競技場去面對那三個挑戰者。證明你比他們三個加起來還要強!\n\n挑戰者，祝你好運!", progress = nil, completion = "太精采了!真是場激烈的戰鬥!\n\n你已證明自己是今天這場大賽的冠軍。做得好!\n\n未來你一定要回來這裡，再次展現你的力量。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30910] = {title = "绿石村", objective = "营救所有村民。", description = "请救救我们。\n\n我们出钱聘请了一些冒险者帮我们赶走了元素之灵，现在他们竟回来报仇了！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30918] = {title = "仇灰的复仇", objective = "打败仇灰。", description = "虽然有点难以启齿，但为了绿石村……可以麻烦你为我们去对付仇灰吗……？", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30921] = {title = "螳螂人的動機", objective = "殺死克里斐斯的螳螂人，好讓泰豪從屍體中尋找線索。", description = "<class>。或許你可以幫忙。\n\n影潘想知道為什麼螳螂人會這麼狂暴地進行攻擊。我們有些猜測，但不能確定。而且，我們不想讓螳螂人知道我們正在調查他們。\n\n這就是你派上用場的地方了。\n\n我需要你到北方的克里斐斯去殺死螳螂人。我會潛伏在你背後的陰影裡，並從他們的屍體中尋找線索。", progress = nil, completion = "螳螂人身上出現大量的犛牛毛髮，這只表示一件事…它是從怒兆寺來的。&lt;class&gt;，我們繼續往西走。", rewards = "霧降腕輪迷霧潛伏者束腕移陸者臂環金爪護腕沼澤漫步者腕輪高原獸裹臂歐索峰裹腕神廟守護者護腕蒼風護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][30922] = {title = "天然消毒劑", objective = "取得5份完整的牡山獸膀胱。", description = "影潘的數量非常稀少，而且全都是菁英，要訓練出新影潘來取代舊的，代價很高。我們承受不起任何人因淬毒武器或傷口感染而死傷。所以我需要你幫我去拿…某樣東西。\n\n我就老實跟你說吧，牡山獸的尿液是最好的天然消毒劑。幸好，牠們的產量多到不行…因為我們需要的用量非常大。", progress = "的確，這是個髒活兒。\n\n但跟挖墳比起來算不了什麼。", completion = "&lt;race&gt;，今天你做的髒活兒可能會救活好幾條性命。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30923] = {title = "逼退螳螂人", objective = "到克里斐斯使用火藥桶，炸毀克里席克武器與克里席克補給品。", description = "螳螂人每天都在打造許多武器用來對付他們敵人。光靠我們兩個無法阻止他們…但我們可以讓他們做白工。\n\n<泰豪交給你一些炸藥。>\n\n我必須保持低調。你願意接受這份榮幸嗎？", progress = nil, completion = "&lt;race&gt;，我們欠你一次。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30924] = {title = "怒兆的智慧", objective = "到螳螂荒原的怒兆寺找奧苟老弟。", description = "玄牛怒兆就住在西邊的寺廟裡。祂或許知道螳螂人為何會進行攻擊。\n\n事實上，祂知道的或許還要更多。\n\n<class>，我會跟你在怒兆寺會合。", progress = nil, completion = "你的影潘夥伴已經告訴我了。是的，怒兆知道為什麼螳螂會攻擊。但祂還沒準備好要告訴你。\n\n目前還沒準備好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30925] = {title = "怒兆的開價", objective = "殺死斯拉席克侵略哨站的螳螂人，好讓泰豪在他們的屍體殘骸中尋找怒兆的雕像。", description = "怒兆有一個祂非常珍視的小雕像，雕的是祂的模樣。雕刻者是一個很久以前就死去的哨兵。這個雕像最近被斯拉席克螳螂人偷走，帶回他們的營地裡去了。\n\n把這個雕像帶回來。我們會告訴你和你影潘同伴所尋求的答案。", progress = nil, completion = "怒兆會很高興。\n\n和祂的體型不同，我們的守護神是一隻充滿憐憫心與慈悲的猛獸。祂珍視這個雕像…一如祂珍視祂的每個追隨者。", rewards = "您能選擇下列奬勵中的一個：\n\n憐憫符印忠貞符印恩賜符印耐心符印虔誠符印\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30926] = {title = "可怕的事實", objective = "調查怒兆墓穴，並殺死蟄伏在裡面的恐懼之影。", description = "我以沉重的心情證實了你的懷疑。螳螂人的確受到恐懼之煞的控制。\n\n我們曾發過誓，要負責把這個怪物監禁在我們寺廟底下。不幸的是，我們的警戒潰散，我們的守衛屈服，而煞逃走了。它現在跟螳螂人在一起。\n\n你自己去看看吧。螳螂人挖洞進入我們島嶼的西側了。", progress = nil, completion = "讓我跟你講清楚...那個怪物根本不是恐懼之煞。只是煞真正力量的影子...一片破片罷了。\n\n不，恐懼之煞現在跟螳螂人在一起。我族的長者必須立刻知道這件事。\n\n剩下的我會處理。謝謝你的協助，&lt;race&gt;。再一次，你的族類證明自己是潘達利亞的寶貴資產。", rewards = "您能選擇下列奬勵中的一個：\n\n墓穴印記墓穴符印墓穴紋章墓穴勳章墓穴符記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30927] = {title = "讓他們安息", objective = "幫10個被恐懼侵襲的哨兵闔上雙眼並把雙手放在腹部，使他們獲得平靜。", description = "我在旁邊聽到了。所以我們的秘密已經洩漏了。\n\n當我聽說螳螂人掘進我們寺廟下方時，我儘快做了處置。我派了好幾打守衛儘可能地進行防禦，但他們並沒有準備好。他們屈服於恐懼之下，再也沒有回來。\n\n一個熊貓人應該像睡著時一樣擁抱大地而死...而不是倒在地板上，眼中充滿恐懼。拜託，<name>。把他們應有的平靜還給他們。", progress = nil, completion = "謝謝你，&lt;class&gt;。\n\n\n\n我應該與他們同行的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30928] = {title = "恐懼的足跡", objective = "到怒兆墓穴裡殺死12個恐懼靈。", description = "現在你知道怒兆的秘密了。我們並不只是這間寺廟的看守者…我們還是埋在底下的恐懼之煞的看守者。\n\n煞可能已經逃脫了…但它留下了足跡。如果你真的要進入地下墓穴，你應該把那些足跡清除掉，免得他們跑出來給我們製造更大的問題。", progress = "即使在我族之人，也只有少數資深的長者，知道我們遏制恐懼之煞的神聖責任。\n\n為什麼他們會選擇告訴一個犛牛看守者，或許我永遠都不會知道。", completion = "我們操心的問題已經包含螳螂人、魔古跟揚古了。我們得在超出負荷之前，把這剛冒出頭的煞麻煩給摘除掉。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30929] = {title = "壞犛牛", objective = "幫藍鞍換掉他那隻有缺陷的犛牛。", description = "這裡就是他們更換有瑕疵的犛牛的地方嗎？\n\n有沒有人能幫幫我啊？", progress = nil, completion = "我想我們的論點非常具有說服力。他們非幫我換一隻犛牛不可。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30930] = {title = "撿一隻犛牛", objective = "在野生螳螂荒原犛牛身上使用犛牛套索，然後跟牠們戰鬥，看看牠們適不適合藍鞍。", description = "我在這裡連一隻好犛牛都找不到。所有的犛牛都很糟糕！\n\n有的太臭，有的太好鬥，剩下的全都嚇得皮皮挫。\n\n你看起來是個幸運的<race>。來，拿著套索。看你能不能幫我找隻好犛牛來。", progress = nil, completion = "看看這是什麼呀！一隻好犛牛！\n\n&lt;name&gt;，告訴你吧。我把這隻超棒的犛牛帶走，這隻壞透了的犛牛呢，隨便你要怎麼處置牠。", rewards = "您會收到：\n\n魯瑟斯的鞍具"}
MultiLanguageQuestData['tw'][30931] = {title = "我父親的弩", objective = "取得庫堯的弩。", description = "我到寺廟來找我爸爸。當我到這裡時，我看到我這輩子見過最可怕的東西。\n\n那是一隻螳螂人，從我旁邊經過，手裡還拿著我父親的弩。\n\n我父親一定發生了什麼事!我們得查清楚...但首先，我們必須把他的弩拿回來。我看到那隻螳螂人往西走，就在寺廟後面。", progress = "你…你有找到它嗎？", completion = "對，這是我爸爸的。\n\n我們到寺廟去吧。他們會知道...\n\n&lt;庫摩的聲音哽住了。&gt;\n\n...我父親發生了什麼事。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30932] = {title = "父親的腳步", objective = "找出父親的鋪蓋卷、父親的盾牌、哈查、以及哨兵亞婁。", description = "是的，那個男孩的父親，哨兵庫堯失蹤了。我們最近可不缺敵人…所以他可能在任何地方。\n\n如果願意，你可以隨意到處看看。你或許可以從尋找他的犛牛開始，或者問問哨兵亞婁知道些什麼。", progress = nil, completion = "沒有盾，沒有十字弓，沒有犛牛…父親身上發生了一些糟糕的事。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30933] = {title = "尋找父親", objective = "尋找哨兵庫堯。", description = "我到處都找過了…但還是沒找到我爸爸。我知道他還活著。他只是需要他的十字弓…然後他就會沒事了。\n\n我聽說你們影潘有時會跟斯拉斐斯的螳螂人交戰。我沒辦法到那裡去。如果你有要到那裡去，可以幫我找我爸爸嗎？", progress = nil, completion = "&lt;庫摩似乎沒注意到你。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30934] = {title = "标准效果测试任务", objective = "和任务目标进行互动，确保它们的图标有用。", description = "你好，朋友！我们来做一些测试，好吗？\n\n点击装置！\n和泡泡聊天！\n治疗绿色烟火！\n杀死该杀目标！\n点击装置尸体！\n\n扬声器会播报你的进度。\n\n每达成一个目标，你都会爆炸。\n\n（最后一点我很抱歉。）您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啄眼者異味長靴麥克威醬的拍肉錘"}
MultiLanguageQuestData['tw'][30935] = {title = "漁夫的故事", objective = "和米什談話以前往征服者之路。從那裡到雲語高地找阿伸‧雲語。", description = "驟晴的村民比崑萊的任何人都熟悉這片海岸。如果贊達拉躲在其中某座島嶼之上，他們會知道。\n\n米什會帶你順著帝王之道走。我要去試著跟長者們談談。\n\n順著路前往雲語高地。阿伸‧雲語會在那幫助你前往村子。", progress = nil, completion = "長者們同意協助我們找出贊達拉藏匿雷王遺體的地點。\n\n不過他們有一些條件...", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30936] = {title = "UNUSED", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30942] = {title = "成為一名戰士", objective = "在驟晴縣殺死4名阿曼尼爭鬥者、4名古拉巴什妖術師與3名德拉克瑞織霜者。", description = "噓!不要這麼大聲!我父親可能會聽到你的聲音。\n\n<琇蜜指著控鋼者道舒。>\n\n我父親腦筋糊塗了!他認為我應該在村莊受攻擊時，繼續坐在這裡研究我的茶道。真是太荒謬了!我的勇氣不比任何男人少。我只是還不知道...如何戰鬥而已。\n\n這是你派上用場的地方啦。讓我跟你一起旅行!我學得很快，而且保證不會妨礙你!\n\n拜託啦!!!!!!!!\n\n如果我們走散了，我會回來村莊跟你碰頭。", progress = nil, completion = "我跟你說過我學得很快吧!我要回村莊去訓練其他人。謝謝你，&lt;name&gt;。", rewards = "琇蜜的巨劍琇蜜的釘錘琇蜜的盾琇蜜的護盾琇蜜的斧琇蜜的鶴琇蜜的扇子您能選擇下列奬勵中的一個：\n\n英雄的獎金\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][30943] = {title = "小心輕放", objective = "把50朵揮發之花帶給舒長老。", description = "我已見到這些侵略者的數量，要贏這場仗絕非易事。我還知道一件事可以給我們帶來好處。\n\n村莊周圍有種植物，可以用來製作非常有效的液體炸藥。如果你能帶來足夠的量，我就可以開始製作混合物。\n\n你要找的植物有個很貼切的名稱，叫做揮發之花。摘花時要小心輕放，<class>。", progress = "你有找到足量的揮發之花嗎？", completion = "這些很完美！現在，&lt;class&gt;，我建議你多洗幾次手。\n\n接下來幾天我也建議你不要靠近開放的火源…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30944] = {title = "同村協力", objective = "讓精疲力竭的防衛者從崗位下哨。", description = "從第一次攻擊後開始，我們的村民就一直保衛著驟晴村。他們都筋疲力盡又傷痕累累。\n\n當贊達拉再次攻擊時，我們最不希望發生的就是衛士們在執勤時不支睡倒。\n\n過去通知他們下哨，讓他們有時間治療和看看家人。\n\n崗哨就在村子四周。", progress = nil, completion = "非常好，&lt;class&gt;!村民充分休息後，我們或許有機會抵抗贊達拉。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30945] = {title = "你的就是我的", objective = "從贊達拉入侵者手中取回6個遭竊的武器。", description = "長者們要我們準備防禦？<class>，我們不是武僧。我們手上得有武器才能戰鬥！\n\n幫我帶來那些野蠻人手中的武器。我應該能把它們鎔鑄成更適合我們村民使用的東西。\n\n數量越多越好，我會負責其他的事。", progress = "我們需要更多好運來度過難關。希望你有找到什麼東西來給我利用。", completion = "嗯，這些比我預期的還好。我可以用這邊的一把劍做成四支長矛。\n\n不要擔心，我會及時讓村民們武裝起來的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30946] = {title = "革命", objective = "與贊達拉囚犯交談。", description = "囚犯就被監禁在樓上，<name>。要從他身上取得資訊十分困難，但只要與他們的所在地有關，即使最細微的線索都有幫助。\n\n長者們已經開始訊問他。有了他們的協助，我們應該就能知道下一步該怎麼做。\n\n去跟他談談，看他是否知道任何有用的資訊。", progress = "囚犯說了些什麼？", completion = "我們不能執著在這個挫折上，&lt;name&gt;。一定得把預言者跨茲庫解決掉。\n\n每摧毀一個雷王部隊的成員，都能讓我們離勝利更進一步。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30952] = {title = "無止境的圍攻", objective = "到怒兆寺擊敗12個斯拉席克攻擊者。", description = "螳螂人持續攻擊我們。他們的數量時多時少，但完全沒有停下來。\n\n這無所謂。犛牛的特質就是持久力。我們不會向他們屈服。我們要永遠保衛祂的家。\n\n你會幫我們嗎?", progress = nil, completion = "你戰鬥起來就像我們的一員。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30953] = {title = "倒下的哨兵", objective = "治療8名受傷的怒兆哨兵，使他們的體力值恢復超過50%。你可以使用犛牛奶瓶或你自己的法術與技能。", description = "我們的哨兵可以持續不斷地戰鬥好幾天，但即使如此他們還是有極限。自從螳螂人大軍開始出現後，有太多人逼迫自己超出了能力的界限。\n\n拜託你，不管用什麼方式都好，幫助他們。如果你自己無法治療他們，那你可以給他們一些這個。一口營養的犛牛奶，可以供應他們所需要的體力。", progress = nil, completion = "像這種時候，我們必須相信怒兆的保護與力量。事情若變得更糟，祂會保護我們。\n\n祂一向如此。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30954] = {title = "刀就是刀", objective = "取得10件斯拉席克武器。", description = "不是去維持傳統的時候了。我們石匠起繭的雙手流血而顫抖。我們的鐵匠鍛造武器的速度趕不上哨兵弄壞的速度。\n\n該是用腦子戰鬥的時候了。\n\n許多螳螂人都有帶武器來，而當他們死去，武器就這樣留在戰場上。眼睜睜看那些武器浪費掉真是太可惜了。", progress = "我們的人習慣用錘與棍棒來戰鬥。很不幸地，我們沒什麼時間去習慣這些新武器了。", completion = "我會好好把這些武器確實分配給大家。更重要的是，我會確保我們的鐵匠能獲得休息。怒兆知道，這是他們應得的。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30955] = {title = "獻上供品", objective = "取得6份怒兆食物。怒兆強臂會幫你扛食物。", description = "我們的守護神怒兆是一座底下有車輪的山...要移動祂很難，要讓祂停下來更困難。這就是我的重點:一旦我們讓祂動起來，螳螂人就得忙於嘗試讓祂慢下來。\n\n讓祂動起來的最簡單方法就是在祂面前擺食物。我們運氣好，寺裡的食物非常豐富...即使在這戰時。\n\n我會派我一個有力的手下跟你一起去扛東西。", progress = nil, completion = "祂會站起來的。很快。或許不是今天，但很快。\n\n當祂站起來的時候...\n\n&lt;一抹微笑出現在寶廈的臉上。&gt;", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30956] = {title = "攻城浪潮", objective = "到怒兆寺擊敗25個斯拉席克攻擊者。", description = "今日的螳螂人大軍是我所見過最嚴重的。我們很幸運，有怒兆加入戰役。\n\n幫助祂，<class>。回到庭院去，然後加入我們寺廟的防禦部隊。", progress = nil, completion = "看看祂，&lt;class&gt;。\n\n沒有東西可以阻止怒兆。只有怒兆可以阻止祂自己。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30957] = {title = "鋪天蓋地的蟲群", objective = "擊敗4個斯里席克崑蟲。", description = "怒兆的哨兵由我指揮。外頭每個守衛都能與螳螂人大軍對抗並自保。\n\n然而，崑蟲有些不同。\n\n牠們巨大、暴力，而且毫無疑問，是我手下哨兵生命的最大威脅。只有怒兆有機會與之抗衡。怒兆...或許還有你。", progress = nil, completion = "穿上我們的鎧甲，你就變得像我們外頭的哨兵一模一樣。\n\n精彩的戰鬥，&lt;race&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30958] = {title = "在戰爭的陰影下", objective = "把10塊鬆動的岩石丟上去給怒兆石匠。", description = "就許多方面來說...怒兆出現在戰場上是一種祝福。\n\n由於祂造成的混亂，我們的石匠才能抓住機會把粉碎的牆重新建起來。他們會需要你幫忙。\n\n把你找到的每一塊鬆動的磚丟去給他們。而且要快!怒兆不會永遠處在狂怒狀態。", progress = nil, completion = "看來牆壁似乎重新建起來了。寺廟終於再次完整。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30959] = {title = "大型火砲", objective = "摧毀3台斯拉席克戰車。", description = "現在螳螂人用他們可恨的攻城坦克圍住寺廟。我們最好快點把這些東西清除乾淨。你可以用你自己的武器與法術摧毀它們，但這個方法會快得多。\n\n<奧苟遞給你幾小桶匆忙綑在一起的炸藥。>\n\n當炸藥爆炸時，小心坦克裡殘存的螳螂人對你進行報復。事實上，我建議儘可能離那些東西越遠越好。", progress = nil, completion = "很好，你回來了，沒有少掉一隻手或一隻腳。\n\n&lt;race&gt;，我們希望未來能夠常常見到你。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][30960] = {title = "從隘口回來", objective = "到高仁前線找塔蘭‧祝。", description = "我在隘口這裡還有些清理工作要做。有些螳螂人還是成功穿越到這裡了。你是個很有價值的幫手，而且我知道，繼續留你在這裡做這些基礎工作，塔蘭可不會樂意。\n\n塔蘭應該還跟高仁一起留在主營區。去跟他們報到。我稍後就會跟上你。", progress = nil, completion = "歡迎回來。我聽說東邊隘口的裂口所發生的事了。看來我把正確的人放到了正確的位置上。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30963] = {title = "荒原護甲匠", objective = "取得120片咬序龜殼碎片。", description = "影潘總是在戰鬥。正因如此，他們的甲冑常會被割破、出現裂痕、爆開或燒焦。我的工作就是修復它。\n\n我不是護甲匠，但只要洞別破太大，我可以修復一件破裂的鎧甲。\n\n在東北方有一種烏龜，我喜歡利用牠們的甲殼碎片。幫我弄一些來，這樣我才能讓更多影潘穿上裝甲保住性命。", progress = "我絕不讓我們的族人因為穿著破裂的鎧甲而陣亡。", completion = "太完美了。今晚，等大家差不多都回來後，我就要來修鎧甲。", rewards = "霧降足靴迷霧潛伏者護足移陸者脛甲金爪護脛沼澤漫步者足靴高原獸長靴歐索峰脛甲神廟守護者戰靴蒼風戰靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][30964] = {title = "適當的藥膏", objective = "取得11株毛柳草。", description = "乾燥的繃帶起不了什麼作用，只能讓蟲子不要靠近傷口而已。但在某些營地裡，這已經是你所能期待最好的治療方式。\n\n不過在我的營地可不是這樣。\n\n我喜歡把我找到任何能緩解疼痛的藥草搗成泥，然後塗在傷口上，再用繃帶包起來。我在荒原中所能找到最具鎮定效果的藥草，就是荒原東北邊的毛柳草。如果你有碰上任何毛柳草，把它們帶回來給我。", progress = "<name>，在外頭有沒有碰上什麼好運？", completion = "這些就夠了。\n\n影潘非常感謝你的協助，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30967] = {title = "釋放異議份子", objective = "到墨鰓湖拯救6名異議份子。", description = "並不是我所有的村民都遭到了腐化。許多人聽進了我的警告，沒有喝下被煞污染的水。\n\n如今他們在村莊裡四處躲藏，恐懼不已，或遭到守衛的恐嚇。\n\n拜託，告訴他們一切還有希望！前往北邊的村莊，叫他們來這裡找我。", progress = nil, completion = "雖然我們人數不多，但我知道我們能以這次不幸的事件為起點另起爐灶。謝謝你，朋友。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30968] = {title = "仇恨之煞", objective = "擊敗仇恨之煞。", description = "我們狩獵的終點即將來臨。我們已聚集了最強的影潘，而且有你的力量加入我們，我們將會擊敗仇恨之煞並阻止它對世界造成危害。\n\n當我們進入通道後，要跟緊一點，並保持心靈澄淨，不要被仇恨入侵。眼前的戰役即將考驗我們所有人。\n\n無論發生什麼事，能和你一起旅行是我的榮幸，<name>。", progress = nil, completion = "擊敗一個煞…不是件容易的事。我們能全身而退簡直是個奇蹟。\n\n塔蘭仍在責怪自己讓仇恨擊敗了他，並將那個怪獸釋放到大地上。對他來說，要從這件事走出來或許得花點時間，但這是必要的，以免他再次失敗在同樣的弱點上。\n\n我們完成了偉大的壯舉，這件事會被世人記上好一陣子。\n\n你的參與也不會被人遺忘。謝謝你。", rewards = "霧降兜帽迷霧潛伏者頭盔移陸者頭盔金爪頭罩沼澤漫步者風帽高原獸頭盔歐索峰頭盔神廟守護者頭盔蒼風頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][30969] = {title = "新的敵人", objective = "到怒焰裂谷從任何教徒身上收集5個腐化徽記。", description = "<name>，這些黑暗薩滿的力量吸引了不少盟友。有一些部落的前成員，現在為了黑暗的目的效力。\n\n我們得拿他們立個榜樣，以免又有另一個暮光之錘誕生。\n\n殺死你看見的任何教徒，並把他們的徽記帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30970] = {title = "因仇恨而憤怒", objective = "殺死9隻沸騰碎屍蠍。", description = "這些蠍子被煞影響了。看來牠們似乎已從洞中跑出來並進入我們的營地，滿懷著恨意攻擊地盤上的外來者。\n\n我們必須清光蠍子並保護營地。殺死你找到的每一隻蠍子。", progress = nil, completion = "很好。這樣留在營地裡的人會安全點。", rewards = "谷地披風沸騰憎恨披風蠍子披氅血肉撕裂者斗篷夕光披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][30971] = {title = "撿殘枝", objective = "收集120支影潘烈焰之箭。", description = "我被派回營地，為我們在橋上的弓箭手收集箭頭鋒利的箭，這就是我的下場。我與這裡絕大多數的熊貓人一起接受訓練…我沒做好這種準備。\n\n不過，橋上的弓箭手還是需要我們的幫忙。如果你能幫忙從殘骸中收集弓箭，那麼我們或許可以從這可怕的情況中救出一點東西。", progress = "橋上的熊貓人只能靠我們了…", completion = "我…你…呃，謝謝你。其實你不需要幫忙，但你還是幫了。謝謝你。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30972] = {title = "加入戰鬥", objective = "把影潘烈焰箭袋帶去夕光橋給『鐵肚皮』老秦。", description = "老秦在橋上的弓箭手會需要那些箭。你可以把箭帶去嗎？", progress = "歡迎來到這團混亂。", completion = "塔蘭‧祝跟我說了我的營地變成了什麼樣子。如果我能，我會阻止這一切，但來自橋上的攻擊仍未減弱。\n\n謝謝你帶這些箭來，我的弓箭手會好好利用它們。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30973] = {title = "陷入火坑", objective = "藉由老秦桶子的協助，殺死10個闊席克木殼兵。", description = "越過橋來的螳螂人身上有厚厚的甲殼，讓他們可以無視我們大部分的攻擊。即使如此，他們依然有弱點:火。\n\n老秦的部下把酒桶帶到戰場上來，就是為了這個原因。把酒桶踢進螳螂人聚集的地方，老秦的弓箭手會點燃它們。\n\n那應該可以很輕鬆地解決他們。", progress = nil, completion = "有個額外的好處是，螳螂人在看到他們的弟兄們被活活燒死後，會士氣潰散然後離去。雖然很殘酷，但如果他們停止進逼我們的封鎖線，很多條性命是可以被饒恕的。", rewards = "蒼風腰環神廟守護者腰環歐索峰護腰高原獸腰環沼澤漫步者腰環金爪腰環移陸者腰帶迷霧潛伏者腰環霧降腰環您會收到：\n\n"}
MultiLanguageQuestData['tw'][30974] = {title = "提神醒腦", objective = "把8份鐵肚皮的烈酒丟給附近的夕光爭鬥者與夕光遊俠。", description = "這些酒桶裡裝滿我品質最差的存貨。拿來放火很好，喝起來的話像嚐尿。\n\n不過我已經拿出幾杯我最好的酒，混到那些桶子裡面，為了嘉勉我戰功卓越的手下！經過無止境且激烈的戰鬥後，酒精可以提振他們的精神。\n\n你可以幫忙分發這個好東西嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵肚皮靈酒"}
MultiLanguageQuestData['tw'][30975] = {title = "奪回夕光橋", objective = "幫『鐵肚皮』老秦守住夕光橋的另一端。", description = "讓我們把這些昆蟲打退到橋的另一邊，擊潰牠們的士氣！\n\n聽我的指揮。", progress = nil, completion = "經過這樣的打擊後，螳螂人可能不會太快回來…現在老秦可以加入我們的狩獵行列了。", rewards = "放血者指環夕光指環老秦之戒闊席克徽印血肉撕裂者之戒您會收到：\n\n放血者指環夕光指環老秦之戒闊席克徽印恆龍寶箱"}
MultiLanguageQuestData['tw'][30976] = {title = "加入狩獵", objective = "與塔蘭‧祝、陶氏跟老秦一起到任賽看守站。", description = "我們團結起來會變得更強。你的貢獻是無法衡量的。\n\n我們到西邊的任賽看守站找到團隊的最後一個成員吧。", progress = nil, completion = "我們接近了。我可以感受到不自然的仇恨在胸口翻湧。\n\n這裡的部隊沒被它的影響給吞噬，就是影潘訓練成果的證明。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30977] = {title = "歡迎降落", objective = "殺死12隻落地的闊席克翼螳。", description = "我所有的人都在西南方的遠眺者瞰臺，阻擋那些試圖飛越裂口的螳螂人。只要我的神射手有箭可用，他們會把所有通過裂口的螳螂人都射落在地。\n\n如果你是來這裡幫忙的，那我需要多點人手把掉到地上的螳螂人清乾淨。<class>，你願意嗎？", progress = nil, completion = "感謝你的努力，&lt;class&gt;。即便只是在攻擊間多喘幾口氣，在最近的日子裡也是種慰藉。", rewards = "遠眺緞質長袍遠眺皮長袍移陸者胸甲遠眺光潔護胸遠眺絲質長袍遠眺皮甲外套歐索峰護胸遠眺重型護軀遠眺裝甲護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][30978] = {title = "敵方空襲", objective = "射下50隻闊席克蟲群與弗雷斯法利克。", description = "我們將要重創他們…\n\n如果你願意，拿起那隻火砲並幫我們的忙。射擊目標可多得是。", progress = "我真的可以讓你來使那隻火砲…", completion = "射得漂亮！\n\n不過我很確定掉下來的大蟲還活著…", rewards = "您能選擇下列奬勵中的一個：\n\n砮龍的槍\n\n您還會收到：\n\n砮龍的槍恆龍寶箱"}
MultiLanguageQuestData['tw'][30979] = {title = "毀滅之下", objective = "接受鷹大師砮龍的協助，擊敗弗雷斯法利克。", description = "我們下去把那隻大蟲解決掉，就你我兩個。", progress = nil, completion = "我這輩子怎麼現在才遇到你？！剛才真是太棒了！\n\n任何時候，我都願意驕傲地跟你一起戰鬥。", rewards = "遠眺緞質兜帽遠眺皮頭盔移陸者軟帽遠眺光潔頭罩遠眺絲質風帽遠眺皮甲頭盔歐索峰軟帽遠眺重型頭盔遠眺裝甲頭盔您會收到：\n\n遠眺緞質兜帽移陸者軟帽遠眺光潔頭罩遠眺絲質風帽恆龍寶箱"}
MultiLanguageQuestData['tw'][30980] = {title = "影潘的英雄", objective = "跟鷹大師砮龍一起到任賽看守站找塔蘭‧祝。", description = "你說塔蘭‧祝來到螳螂荒原，還要找我？一定有什麼重要的事…", progress = nil, completion = "總是能夠倚靠你真好。你擁有真正的影潘精神。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30981] = {title = "陶氏與克爾菲西斯", objective = "在陶氏的協助下殺死克爾菲西斯。", description = "陶氏正在席克斐斯南側設置一支伏兵，準備伏擊一個螳螂人首領。她的任務是取回螳螂人首領的水晶，好讓我們用來打開通道的門。\n\n兩個人總比一個人強。我要你到那裡去確保事情可以順利進行。", progress = nil, completion = "第一塊水晶是我們的了…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30982] = {title = "动物控制", objective = "杀死阿达罗格和焰喉。", description = "这条裂谷里到处都是烈焰猎犬和熔岩虫，他们依靠庞大的穴居人种群的肉为食维持着他们无限的繁衍生息。\n\n这种情况必须在它们破坏城市之前得到处理。你看起来可以独自解决这个问题，<name>。\n\n我要你在那群野兽中杀出一条路来，而且务必要解决掉最大的麻烦——阿德杰里斯和焰喉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30983] = {title = "黑暗薩滿", objective = "擊敗黑暗薩滿坷蘭索與熔岩守衛哥爾多斯。", description = "這些黑暗薩滿來到這裡飼養野獸並舉行黑暗儀式，有好幾個月了。\n\n我不知道他們做這些事的企圖是什麼，但他們很顯然並不是部落的朋友。這就是你派上用場的時候了，<name>。\n\n殺進裂谷並宰了黑暗薩滿坷蘭索與熔岩守衛哥爾多斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30984] = {title = "不放棄任何一個獸人", objective = "到怒焰裂谷救出5個柯爾克隆斥候。", description = "這應該是一次例行清理，<name>。清除幾個穴居怪，確保沒有任何東西威脅到城市，然後中午時到小酒館去喝一杯。\n\n但相反的，我有一隊斥候不見了，火焰犬傾巢而出，而索倫斯嘴裡不停嘮叨著「下個暮光之錘」。\n\n<指揮官巴格仁吐了口口水>\n\n到那裡去找回我的斥候，這樣我們才能搞清楚下面發生了什麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30986] = {title = "古代魔古地穴", objective = "殺死被附身的影潘首領，並淨化生命之池。", description = "我們的斥候隊被完全摧毀了。幫幫忙!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][30987] = {title = "加入聯盟", objective = "到暴風要塞找安杜因‧烏瑞恩國王。", description = "我們有責任，<name>。\n\n在漂流島外傳播土水的思想是我們的責任…而沒有地方比這裡更適合展開行動：暴風城，聯盟的核心。\n\n我們去找出誰是這裡的領導人吧。我們需要盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30988] = {title = "联盟之道", objective = "跟着瓦里安·乌瑞恩国王。", description = "我对你们一族知之甚少，除了有人告诉过我，说是你们中有一些人会来到我们这边。如果你们愿意加入我们的阵线，那么我也会很高兴地接纳你们作为盟友。\n\n<name>，你跟我过来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30989] = {title = "比武高手", objective = "与瓦里安·乌瑞恩国王过招。", description = "我需要知道你是否是个合格的战士。今后也许你会受我召唤奔赴沙场，我想知道你是否有能力保护我的王国。\n\n我早已耳闻过熊猫人的“武术”技巧，却未得亲眼一见。\n\n你准备好了吗？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30991] = {title = "滾動桶子！", objective = "撿起老秦附近的一個小桶，把它往山下的揚古滾去，然後在揚古附近點燃桶子，摧毀4個歐索射樹車與50個歐索入侵者。", description = "當初我接受釀酒大師訓練時，並沒料到會把知識運用在這種地方…\n\n你知道啤酒點著時會燃燒起來嗎？嗯，混入揚古油之後，它就會大爆炸。\n\n我已經把你給我的油混入這些小桶子裡。把桶子往揚古的方向滾過去，等他們靠近就點燃。\n\n桶子要隔幾秒鐘才會爆炸，但當它爆炸時…\n\n嗯，這麼說吧，我可不希望自己在那附近。\n\n這就是為什麼我要待在這裡，為失去的啤酒哀悼。", progress = nil, completion = "呼，可真是一波大爆炸啊！事實上，應該是好幾波爆炸。\n\n可惜，我的啤酒也沒了，但至少我們「目前」安全了。", rewards = "您會收到：\n\n老秦的最後一杯恆龍寶箱"}
MultiLanguageQuestData['tw'][30992] = {title = "結束一切！", objective = "結束玄牛關的戰役。", description = "我們已收到蘇納從牆上傳來的回音。有事發生了…\n\n看來他們似乎正在準備最後的進攻。該是結束這一切的時候了，朋友。", progress = nil, completion = "的確，他們的隊長死了。我們終於成功地把他們趕出崑萊。\n\n但付出了什麼代價？這麼多人死去，林遭到俘虜…我絕不容許塔蘭‧祝繼續無視他的責任。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30993] = {title = "我的援軍在哪？", objective = "到崑萊峰的影潘僧院外找班‧熊心。", description = "這真是太過分了。我再也不能坐視他們這樣遺棄我們。\n\n經過這裡的事，加上你在火枝望角經歷的一切，我們必須前往僧院才行。\n\n不論他們那裡有什麼要事，都可以先緩一緩！我們可以乘坐我的氣球上山到僧院去。氣球停在東北方的營地裡。", progress = nil, completion = "我們到了，現在你知道為什麼不能讓我們的弟兄們呆坐著了吧。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30994] = {title = "老秦的策略", objective = "到崑萊峰的冬綻找『鐵肚皮』老秦。", description = "好了。謝謝你，我們已控制住長城的情勢了。做得好。\n\n我要在這上面待一會兒，確定沒有其他揚古跑到城牆上來。\n\n不過，你應該下去看看老秦在煮什麼東西。我很不想這樣說，但或許他終究會有個好主意…", progress = nil, completion = "很高興看到你活著回來。謝謝你幫忙搬油桶，我已經為前面那些揚古朋友釀了一個很棒的驚喜。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][30995] = {title = "不留下任何人", objective = "到怒焰裂谷救出5名軍情七處探員。", description = "我在一小時前派人出去偵察，沒有人回來向我報告。現在這些該死的狗在裂谷中到處肆虐。\n\n我不知道下面發生了什麼事，但在我找回我的人之前，我絕不會離開。\n\n我要你進去那裡找他們，<name>，希望他們還活著。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30996] = {title = "黑暗薩滿", objective = "擊敗黑暗薩滿坷蘭索與熔岩守衛哥爾多斯。", description = "這些黑暗薩滿來到這裡飼養野獸並舉行黑暗儀式，有好幾個月了\n\n我不知道他們做這些事的企圖是什麼，但他們很顯然並不是聯盟的朋友。我需要你幫忙阻止他們，<name>。\n\n到裂谷裡殺出一條路，宰了黑暗薩滿坷蘭索與熔岩守衛哥爾多斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "毀滅儀式長袍怒焰護腿薩滿毛皮外衣石衛護脛灼熱腰帶石衛士護脛薩滿鱗甲外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][30997] = {title = "削减战力", objective = "杀死阿达罗格和焰喉。", description = "我很高兴你能来，<name>。部落正在集结军队，而我也不打算等查明原委后再行动。\n\n我们要先发制人，去下面干掉几个他们的大型野兽。\n\n我希望你能在部落将阿达罗格和焰喉用作对抗我们的武器之前，把这两个家伙先处理掉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30998] = {title = "新的敵人", objective = "從黑暗薩滿的教徒身上收集5個腐化徽記。", description = "<name>，部落正在這下頭利用黑魔法控制野獸，並玷污他們的同胞。\n\n我打算阻止這件事，但首先，我必須知道我們對抗的是什麼玩意兒。這就是你派上用場的地方了。\n\n殺進山洞中，並收集教徒身上的徽記。有了那些徽記，我就能研究在這裡產生作用的是什麼魔法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][30999] = {title = "少有旅者拜訪的小徑", objective = "到獨罈集找三葉草叔叔。", description = "最艱辛的道路，往往能讓我們學到最多的事物，<class>。無疑地，追隨紹昊走過的路會讓我學到非常多。\n\n許多年前，紹昊為了尋求玉蛟的建言，登上崑萊的最高峰。我也將前往追尋者聖壇追尋智慧。\n\n也許你對這樣的旅程有興趣?如果有，去和三葉草叔叔談談，他會幫你準備東西。", progress = nil, completion = "&lt;class&gt;，要前往追尋者聖壇，你需要很多好運。希望你有很多幸運物!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31000] = {title = "顫慄空間", objective = "到蟠龍脊找女弓手李。", description = "影潘弓手持續在蟠龍脊頂端監視悚然荒野。他們當然會歡迎一個像你這樣技巧精熟的<class>去幫忙。\n\n利用風箏到女弓手李那裡去看看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31001] = {title = "降下去", objective = "使用影潘索垂降到葛薩恩臺地裡，並搜尋失蹤的影潘神射手。", description = "試著抵擋螳螂已經夠糟的了，但現在廢墟底下還有大批蜘蛛。\n\n我最好的神射手之一，被蛛網捲住腳拉到地下去了!\n\n我們認為他還活著，但我沒有足夠的人力可以派去找他。我們捉襟見肘了，<class>。\n\n如果你想幫忙，就用我身後的繩索垂降到廢墟裡去。你不會怕高吧?\n\n那你會怕蜘蛛嗎?", progress = nil, completion = "其實下墜沒有那麼糟糕。我有一個輕鬆著陸的訣竅。\n\n降落在一堆蜘蛛屍體上可能也會有幫助。", rewards = "這個任務線能解鎖：\n\n每日任務：卡拉西\n\n您還會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31002] = {title = "沒事", objective = "到葛薩恩臺地殺死6隻驚懼紡織者並使用影潘龍槍摧毀20個驚懼紡織者的卵。", description = "我們還撐得住，但很勉強。不管你怎麼做，只要可以抵擋一波波攻上城牆的驚懼紡織者，都能幫上大忙。\n\n你打算徒手一次撕開一個蜘蛛卵嗎？\n\n我不覺得那是個好主意。去拿一支龍槍，然後在下面點燃蜘蛛卵。我想聽那些小蜘蛛崽子變成爆米花的聲音。", progress = "嘿，到外面來幫我!", completion = "你把龍槍用得真好。我在這裡盡了全力，不過弓箭對付這些東西的效果真不怎麼樣。", rewards = "慈母之種手套樹蠅手套枯木護手清澈手套驚懼紡織者手甲鬼狐手套奪風者護手刃誓護手冰蝕護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][31003] = {title = "神經病螳螂", objective = "到葛薩恩臺地調查螳螂人的內鬨。", description = "你不會相信我看到了什麼！兩隻螳螂人在打架，魔法飛來飛去的。\n\n其中一隻螳螂人的外觀是我從沒見過的。顏色與穿著的樣式都和其他螳螂人完全不同，看起來像是…先知之類的。另一隻螳螂人完全是個神經病，身上像在噴一整桶特藏風暴烈酒一樣地噴出煞能量。\n\n聽著，我得回到我的崗位，但我感覺在我背後那洞穴裡打架的兩個傢伙會是件要緊的事。介不介意去偵察看看？", progress = "女皇…被…誤導了。", completion = "&lt;這隻螳螂受到重傷。他勉強地在喘息間嗆咳出幾個字。&gt;\n\n等等，&lt;race&gt;…\n\n我們…不是你的敵人。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31004] = {title = "保存於琥珀之物", objective = "到葛薩恩臺地對古老的琥珀塊使用卡拉西調音叉。", description = "拿著…這個…\n\n<這個瀕死的螳螂人掙扎地伸出他的手臂。他血肉模糊的手中抓著一把雙頭叉，叉頭又細又長，叉柄有著華麗的珠寶裝飾。>\n\n喚醒…奪風者…\n\n這是唯一…阻止蟲群的方法。", progress = nil, completion = "卡拉西…在呼喚我。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31005] = {title = "冬眠症候群", objective = "到葛薩恩臺地帶100個樹蠅碎塊給『奪風者』基爾魯克。", description = "你得原諒我現在的狀態。我睡了很多年。\n\n應該要有個卡拉西瓦在這裡用奇帕利樹液來照料我的甦醒，但我想現在只能靠你了。\n\n我感覺到附近有些樹蠅在嗡嗡飛舞。他們總是貪婪地吸食能給我必要營養的樹液。帶他們來給我。", progress = "沒有養分，我將會死在這裡。", completion = "這應該夠了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31006] = {title = "卡拉西議會", objective = "到悚然荒野中央的卡拉西斐斯。你可以到葛薩恩臺地找『奪風者』基爾魯克搭乘交通工具，或自己前往。", description = "我必須去向卡拉西回報。如果不是情況危急，他們不會喚醒我。\n\n你不是完全沒有用處。因此，我會饒你一命。\n\n議會或許能用得上你，", progress = nil, completion = "這是個神聖的卡拉西會議場所。\n\n如果你聰明的話就別開口，讓我來說話。", rewards = "葛薩恩墜盒議會頸飾群生幼螳項鍊基爾魯克墜飾聖石護符您會收到：\n\n葛薩恩墜盒議會頸飾群生幼螳項鍊基爾魯克墜飾恆龍寶箱"}
MultiLanguageQuestData['tw'][31007] = {title = "恐怖窩巢", objective = "到杉齊爾窩巢附近殺死6個杉齊爾窩巢守衛。", description = "宮殿前帝王之巢的存在已經變成令人難以忍受！窩巢守衛加速新的群生幼螳的成長，將汙穢的煞之能量滲透到他們體內，再將他們送往長城。\n\n卡拉西希望抵擋住從恐怖窩巢中不停產出的群生幼螳。殺死那些守衛！", progress = nil, completion = "又少了幾個可以拿去餵崑蟲的叛徒。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31008] = {title = "琥珀之臂", objective = "從恐懼之心和杉齊爾窩巢附近的杉齊爾刃誓取得6把琥珀刀。\n\n到卡拉西斐斯與『奪風者』基爾魯克交談，騎著他到恐懼之心去。", description = "就是你！低下的東西！\n\n你現在為我工作！\n\n杉齊爾刃誓的琥珀刀是全帝國最好的武器。\n\n如果你離開這裡後沒有馬上被這種刀刺穿身體，就儘可能多帶一些回來給我！我想確保我們有充分的武器庫存，以備不時之需。", progress = "刃誓以他們身上帶的刀刃為傲。我要這些刀刃出現在我的武器架上！", completion = "如果一切按照計畫進行，卡拉西不需要你的幫忙也能阻止女皇。不過，我的職責就是做好準備。", rewards = "冰蝕輕鞋刃誓長靴奪風者輕鞋鬼狐輕鞋驚懼紡織者輕鞋清澈輕鞋枯木輕鞋樹蠅輕鞋慈母之種輕鞋您會收到：\n\n卡拉西"}
MultiLanguageQuestData['tw'][31009] = {title = "死寂的區域", objective = "在恐懼之心閒置的聲波傳輸器上使用卡拉西共鳴水晶。\n\n到卡拉西斐斯與『奪風者』基爾魯克交談，騎著他到恐懼之心去。", description = "某位卡拉西瓦向信號塔發出低語。信號塔將低語傳向遠方;傳給其他的信號塔，傳給螳螂人，傳給聖螳們。低語再反彈回來，傳回卡拉西的耳裡。\n\n透過這種方式可以掌控一切。\n\n附近有一個塔十分安靜。不該如此。它必須為卡拉西而歌唱。\n\n修復信號塔是我的工作，但如果你為卡拉西服務，那你也應該為我服務。你去修信號塔，我會在這裡等!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n卡拉西"}
MultiLanguageQuestData['tw'][31010] = {title = "在她巢中", objective = "到杉齊爾窩巢找到螳螂人聖螳的所在位置，並喚醒他。", description = "水晶向卡拉西歌唱。他們感應到有個聖螳在塔東邊的巢穴中。窩巢守衛正試著污染這個聖螳。\n\n找到這個聖螳，將你的雙手放在他的琥珀塊上，卡拉西會透過你來傳送低語，讓他得以自由。盡力保護他。", progress = nil, completion = "我的睡眠被突然的夢境打斷。那是無法言述的可怕夢魘。\n\n接著我醒過來了。\n\n卡拉西已跟我談過。我收到了命令。有很多事情要做。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31011] = {title = "侵入家門", objective = "擊敗10個阿曼尼狂怒者、5個阿曼尼巨獸與3個古拉巴什血騎兵。", description = "贊達拉發動攻擊了!你必須協助保衛村莊!\n\n如果我們無法逼退他們，我們就永遠都找不到雷王的遺體!", progress = nil, completion = "贊達拉已經撤退了，&lt;name&gt;。這場勝利對村莊來說意義非凡。\n\n我在混亂中抓了一名戰士。或許我們能從他身上獲得一些資訊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31012] = {title = "加入部落", objective = "到奧格瑪找卡爾洛斯‧地獄吼。", description = "我們到了，<name>...奧格瑪，部落的核心。\n\n在漂流島外我們也能派上用場，外面的世界有數不清的問題等著我們去解決，而這也是尚羲大師所希望的。\n\n沒有地方比這裡更適合展開行動，尤其再加上部落的協助。我們去找出誰是這裡的領導人吧。我們需要盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31013] = {title = "部落之道", objective = "與卡爾洛斯‧地獄吼一起散步。", description = "我最近收到消息，說你們族人當中有些人會成為我們的一員。這很好。我最近一直試著要加強部落的力量。幾個熊貓人對我們來說或許不錯。\n\n跟我一起走走，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31014] = {title = "地獄吼的禮物", objective = "擊敗奧卡克斯、加頓與凍血，以完成卡爾洛斯的測驗。", description = "我必須知道你能不能戰鬥...你能殺人，而且能活下來。最後，你們每一個人都會被徵召到戰場上，而我必須知道能不能依靠你。\n\n稍早之前我提過一個禮物，它就擺在這兒，在勇武競技場裡。穿過我身後的門，走進競技場。我要測試你的技能。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31015] = {title = "你的私人收藏", objective = "清理空書架。", description = "潘達利亞充滿了歷史、神話、故事以及各式各樣的傳說。當你在世界各地旅行時，我請求你密切注意，那些你覺得可能跟我們這裡的工作有關的神器與資訊。\n\n當你累積了足夠的知識，我們就會在這裡幫你把知識編纂成冊，做為你的個人收藏。\n\n當然，任何時候你都可以回來檢閱我們為你製作的書冊。", progress = nil, completion = "啊!現在事情做完了，我們可以把你收集的研究放在這裡。我很想看看你找到些什麼。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31016] = {title = "博學行者", objective = "到恆春谷的知識之座找博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n我們在恆春谷發現了驚人的東西。一個巨大的寶庫，裡面滿是書籍、卷軸與傳說，似乎從魔古帝國時代到現在都沒有被翻動過。\n\n拜託，一有空就來加入我們吧。你可以先到著名的魔古山墓穴，從那裡飛到知識之座的入口前面。\n\n我期待你的到來!\n\n誠摯的\n\n博學行者阿洲您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31017] = {title = "《谦卑的土地精》", objective = "将《谦卑的土地精》带给闻道之座的游学者周卓。\n\n已提供物品：\n", description = "亲爱的$p，\n\n我们收到了你关于土地精的调查报告，并确信我们已对他们的起源和历史有了明确的认识。\n\n如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。\n\n感谢你的努力！\n\n此致，\n\n游学者周卓您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31018] = {title = "在恐懼之心的下方", objective = "殺死隨從艾克凡、隨從伊克斯、隨從瑟拉斯和隨從西克席，然後釋放『毒化心智』薩瑞爾。", description = "卡拉西已發現了另一個聖螳，喚醒者。\n\n這一個被人藏的很好，而且理由充分。\n\n這個聖螳在女皇手上，現在女皇的副手正試圖摧毀它。\n\n他們正在宮殿地下深處的房間裡施行巫術，必須阻止他們。\n\n我們要維繫卡拉西斐斯。你必須代替我們去。西邊的岩壁上有個入口可以進入他們的房間。", progress = nil, completion = "你忠實地盡了自己的責任，喚醒者。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31019] = {title = "琥珀就是生命", objective = "殺死7個霧刃撕裂者與霧刃鱗王。", description = "為了讓我們對抗螳螂人帝國的努力持續下去，我們需要更多琥珀。\n\n南方的湖底有藏量豐富的琥珀，但那個區域住著野蠻的薩烏洛克部族。\n\n我沒有其他人力可以去做這件事了。你必須到湖那裡去，測試一下那個部族的力量。削減他們的數量，並消滅他們的首領。\n\n這對你來說想必不是太難的任務吧？", progress = nil, completion = "低語聲似乎是從這塊琥珀中發出來的。\n\n這裡面是否沉眠著另一個聖螳？", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31020] = {title = "餵食野獸", objective = "殺死8隻冰蝕鱷魚。", description = "我必須立刻加入卡拉西議會與其他聖螳的行列，但我幾乎連站都站不起來。\n\n我必須吃東西，喚醒者。\n\n我感覺到湖的北岸有生物的心臟在跳動。\n\n為我殺了牠們，剩下的我會處理。", progress = nil, completion = "我感到力量回到了我的身體中。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31021] = {title = "活化琥珀", objective = "收集8個活化琥珀，並把琥珀餵給『至高者』柯爾文。", description = "要恢復一個剛甦醒的聖螳的體力，液體琥珀是最有效的，這通常在甦醒儀式中提供。\n\n不幸的是，你似乎沒收到這個指示，所以我們得湊合一下。\n\n我可以感覺到，在我們下方的湖中有數量龐大的琥珀化石。這可以用，但我太虛弱，沒辦法自己去挖。\n\n幫我做這件事，我會確保你能得到獎賞。", progress = "你明白嗎，喚醒者？琥珀賜與生命。", completion = "謝謝你，喚醒者。這些暫時夠了。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31022] = {title = "奇帕利札爾", objective = "啟動聲波塔，然後在『至高者』柯爾文檢查那棵樹的時候保護他。", description = "在西方山丘上的是什麼樹？那會是…奇帕利札爾嗎？？\n\n<『至高者』柯爾文陷入沉默。>\n\n當我從最後一次的大戰中歸來，但還沒被拔擢為聖螳之前，我被賦予種下這棵樹的榮耀。\n\n原來它已長成一棵偉大的奇帕利樹，但…似乎有些不對勁。\n\n樹下有座古老的聲波塔。帶我到那裡去，喚醒者。我可以利用那座塔做進一步觀察。", progress = nil, completion = "這棵樹的脈絡中曾有大量的琥珀流動。如今它只不過是一個枯乾的殼子而已。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31023] = {title = "蟲群的聖物", objective = "收集8個螳螂人聖物。", description = "這個外表古怪的雕刻物上頭布滿複雜的語言，可能是出於螳螂人之手。\n\n你注意到聖物被輕率地四處丟在營地中與湖裡。\n\n或許卡拉西會有興趣研究這些神器。\n\n誰知道呢？或許這可以幫你贏得一些好處。", progress = "你那裡有什麼東西？", completion = "這些聖物描述了奇帕利沃爾與附近其他琥珀樹的歷史。\n\n我很想研究這些東西。\n\n謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31024] = {title = "崑蟲請客", objective = "收集4份龜腰肉。", description = "當科沃克成長時，他需要同等的訓練與獎賞。\n\n訓練方面我這裡不會少，但我們補給品中的肉幾乎都沒了。\n\n到南方去，你會在星辰湖與奇帕利札爾的北邊找到四處晃蕩的烏龜。\n\n獵捕牠們。科沃克喜歡吃牠們的新鮮的肉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31026] = {title = "問題的根源", objective = "殺死冰蝕族母。", description = "奇帕利札爾快死了。\n\n一個可怖的黑暗生物從根部深處污染了它。 \n\n這棵樹已經沒救了，但我們至少能減輕它的痛苦。\n\n你看。這邪惡的生物留下走過的痕跡，痕跡通往牠的巢穴。我們只需要跟著塔後方的痕跡走下山丘就好。", progress = "蟲群不知道他們愚蠢到多麼可怖的程度！我們必須不惜代價保護這些珍貴的樹木！", completion = "謝謝你，喚醒者。奇帕利札爾現在可以平靜地做個好夢了。\n\n然而，那隻野獸不過是盛裝腐敗的容器而已。\n\n不…真正的腐敗源頭在更深的地方。", rewards = "您能選擇下列奬勵中的一個：\n\n奇帕利札爾聖物奇帕利札爾符印奇帕利札爾紋章奇帕利札爾徽記奇帕利札爾徽章\n\n您還會收到：\n\n奇帕利札爾聖物奇帕利札爾符印奇帕利札爾紋章奇帕利札爾徽記恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31030] = {title = "進入僧院", objective = "到影潘僧院裡找班‧熊心。", description = "這…真是無法形容。如果僧院真的被煞佔據，我們會需要極大的功夫才有可能淨化裡面的武僧。\n\n集合你的盟友，到僧院裡和我碰面。", progress = nil, completion = "你來了。很好。眼前的情況可說是多災多難。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31031] = {title = "進入僧院", objective = "到影潘僧院裡找班‧熊心。", description = "這…真是無法形容。如果僧院真的被煞佔據，我們會需要極大的功夫才有可能淨化裡面的武僧。\n\n集合你的盟友，到僧院裡和我碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31032] = {title = "窒息的天空", objective = "燒掉10具闊席克翼螳的屍體。", description = "砮龍要我帶火炬來燒屍體。\n\n那些會飛的螳螂人很脆弱，無法在悶熱的煙霧裡撐太久。", progress = nil, completion = "感謝你的幫忙，陌生人。", rewards = "您會收到：\n\n火葬火炬恆龍寶箱"}
MultiLanguageQuestData['tw'][31034] = {title = "敵人在下方", objective = "找指揮官巴格仁談話。", description = "這個城市的暗處有部落的敵人，<class>。\n\n灼刃的混蛋計畫要將奧格瑪據為己有，他們已經攻下怒焰裂谷了！我們必須攻破他們的部隊，奪回屬於我們的一切！\n\n到怒焰裂谷去跟指揮官巴格仁談談。他會給你進一步的指示。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31035] = {title = "下面的敌人", objective = "跟石头守卫库尔加克谈一谈。奥格瑞玛的怒焰裂谷已经被燃刃氏族占领了，<name>，我们不能听之任之，让他们接着觊觎雷霆崖。\n\n去跟裂谷里的石头守卫库尔加克谈一谈。尽你所能帮助他，毕竟雷霆崖与奥格瑞玛唇齿相依。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "奥格瑞玛的怒焰裂谷已经被燃刃氏族占领了，<name>，我们不能听之任之，让他们接着觊觎雷霆崖。\n\n去跟裂谷里的石头守卫库尔加克谈一谈。尽你所能帮助他，毕竟雷霆崖与奥格瑞玛唇齿相依。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31036] = {title = "敵人在下方", objective = "找指揮官巴格仁談話。", description = "奧格瑪的怒焰裂谷已被黑暗薩滿佔領了，<name>，我們絕不能就這樣算了，免得他們把下個目標放在雷霆崖。\n\n到裂谷中去和指揮官巴格仁談談。盡你的力量去幫助他，因為我們和他們的命運息息相關。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31037] = {title = "敵人在下方", objective = "找指揮官巴格仁談話。", description = "奧格瑪的怒焰裂谷已被黑暗薩滿佔領了，<name>。我們絕不能就這樣算了，免得他們把下個目標放在幽暗城。\n\n到裂谷中去和指揮官巴格仁談談。盡你的力量去幫助他，因為我們雙方的命運息息相關。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31038] = {title = "挑戰者競技場:雪綻", objective = "到挑戰者競技場挑戰雪綻並擊敗她。", description = "<name>，你的功績已傳遍了整個營區。\n\n老實說，雪綻想在戰鬥中測試你的技能。\n\n<class>，你最好做好準備。要打敗她可不容易。\n\n如果你能向她證明你的價值，那麼你將會贏得一個有價值的朋友。", progress = nil, completion = "啊呀，所以你在戰鬥中擊敗了雪綻，是不是?\n\n我敢打賭，她會因為這個挫折而難受一陣子。\n\n不過，你做得很好，你贏得她這個跟你站在同一邊的夥伴。\n\n她性格剛開始比較冷淡，但時間一長，她會證明自己是個忠誠且可靠的夥伴。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31039] = {title = "魔古的威脅", objective = "殺死12個衫織縛蛟者或衫織馴獸者。", description = "我們的斥候在西北方的衫織島發現一隊重裝魔古軍隊。\n\n那裡應該是個無人島，因此他們的出現是個令人不安的消息。\n\n更令人不安的是，他們正在那個島上進行邪惡的實驗。\n\n我需要一個能幹的<class>去確認一下情況。\n\n衫織那些傢伙可能會找你麻煩，如果真的發生，就殺了他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31040] = {title = "惡毒的妖精", objective = "殺死30個暗木小妖精或暗木魅精。", description = "衫織島的暗木妖精落入魔古的掌控中了。\n\n這些狡猾的小騙子現在完全變成衫織的僕人。他們一天比一天更大膽，四處偷竊殺戮來滿足他們的主人。\n\n一定得除掉他們，但要小心。他們看起來或許無害，但他們其實很惡毒。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31041] = {title = "把蛋救出來!", objective = "收集8個乘雲者蛟龍蛋。", description = "蛋。是的，你沒聽錯。我說的是蛋，而且這不是拿來吃的。\n\n你有看過雲蛟的蛋嗎?\n\n這些稀有的蛋看起來就像寶石，而且價值跟等重的黃金相同。\n\n北邊的衫織島通常有很多野生雲蛟，但魔古與妖精已鎖定牠們的蛋。\n\n我們必須儘可能地保住這些蛋。\n\n我只能靠你了，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31042] = {title = "瑪瑙之心", objective = "收集4個瑪瑙之心。", description = "衫織縛蛟者控制了野生雲蛟的心智，但他們也利用岩石、金屬、血液及古代巫術，創造出屬於他們的黑暗生物 。\n\n他們創作的其中之一，瑪瑙風爪，就是西北邊島嶼上的守衛。\n\n我想研究組成這些生物的魔法。把他們的心臟帶來給我，這樣我才能更瞭解我們對抗的是什麼樣的巫術。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31043] = {title = "暗黑藝術", objective = "收集8塊衫織石板。", description = "據說衫織島裡曾座落著一間偉大的魔古寺廟。\n\n衫織曾在那裡研究並實踐征服死者或無生命之物的技藝。\n\n他們的知識大部分都還留在西北邊的島上，埋藏在廢墟之中。\n\n我們必須取得那些知識，一方面防止那些知識落入衫織手中，另一方面也可以了解他們實驗的性質。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31044] = {title = "銅爪", objective = "收集20個銅爪。", description = "衫織的造物中最凶暴也最忠實的就是他們的麒麟獸。\n\n這些野獸會不斷追殺獵物，直到獵物或牠們自己死亡。\n\n我不只需要你去削減牠們的數量，還要你把牠們身上的銅爪取回來。\n\n牠們的爪子很堅硬，而且像剃刀一樣鋒利，我們可以利用來做成我們想要的武器跟鉤子。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31045] = {title = "過往的幻影", objective = "殺死3個衫織幻術師。", description = "<class>，我需要你到西北邊的衫織島除去衫織幻術師。\n\n請求你進行這個艱難的任務讓我心情十分低落。\n\n幻術師是衫織巫師菁英中最強大的一支。\n\n要擊敗他們並不容易，但我知道沒有別的<class>比你更適合這個任務。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31046] = {title = "小寶寶", objective = "釋放20隻乘雲者蛟寶寶。", description = "我看過衫織在他們西北方的島上進行的殘酷實驗。\n\n衫織把蛟寶寶從蛋裡拉出來。他們把這些孩子關在狹小的籠子裡，周圍都是穢物與糞便。\n\n最殘忍的看守者會讓他們餓肚子並折磨他們。\n\n我們必須把這些蛟寶寶儘可能的救出來。我完全授權你用任何方式懲罰這些魔古!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31047] = {title = "天生自由", objective = "從鐵鍊下救出6隻野生雲蛟。", description = "<name>，你知道潘達利亞那條偉大的雲蛟的故事嗎?\n\n哪天你一定要聽聽。不幸的是現在沒時間說這個故事。\n\n現在你只需要知道螳螂荒原的野生雲蛟有麻煩了。\n\n魔古正在捕捉野生雲蛟並污染牠們的心靈，使雲蛟屈從於他們邪惡的意志。\n\n到西北方的衫織島去。把成年蛟從鐵鍊下拯救出來。救出牠們!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31048] = {title = "嚴重的後果", objective = "殺死24個衫織先祖。你可以在魔古葬禮瓦罐中找到衫織先祖。", description = "我們在衫織島的廢墟中找到古代魔古的葬禮瓦罐。\n\n通常這不會有什麼大問題，除非這些瓦罐裡裝了憤怒的魔古靈魂。\n\n這些瓦罐不僅會讓找到它們的倒楣傢伙陷入危險，如果落入惡徒的手中，可能還會被用在毀滅之途上。\n\n我們必須讓這些瓦罐在衫織島裡完全消失。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31049] = {title = "到處都有妖精", objective = "殺死暗木邪妖。", description = "衫織島的妖精一直都是反覆無常的騙子，但他們現在受到了魔古的影響。\n\n此刻，他們正在一個新領導者之下聚集起來。\n\n我們不能允許這種事發生。\n\n他們的頑皮惡作劇是一回事，但一旦團結起來，他們的黑魔法就強大且危險得超乎想像。\n\n在事情不可收拾之前把他們的領導者殺了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
