MultiLanguageQuestData['tw'][31061] = {title = "騎上風暴", objective = "使用銅爪騎上8隻衫織乘雲者。攻擊牠們，把牠們從腐敗中解救出來。", description = "衫布，衫織的首領，正在西北邊的島嶼上準備進行某種黑暗的儀式。\n\n我們相信被征服的衫織乘雲者正在讓法術變得更強。但我們還不確定。\n\n我們相信還有辦法解救衫織乘雲者脫離污染他們的腐敗。\n\n帶著這些銅爪。利用銅爪騎上衫織乘雲者的背。\n\n攻擊牠們。把牠們的腦袋給打清醒點!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31062] = {title = "當死者開口說話", objective = "殺死衫織亡頌者。", description = "衫織的實驗受到一個法力強大的死靈法師監督，這個法師人稱衫織亡頌者。\n\n我們得除去他們的領導人，才有辦法終結他們的行動。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31063] = {title = "老秦與瑟里菲克斯", objective = "在『鐵肚皮』老秦的協助下擊殺瑟里菲克斯。", description = "老秦就在席克斐斯的北側，入口處上方的大樹對抗首領。他會帶回我們進入螳螂人隧道所需的第二塊水晶。\n\n到那裡去協助他。", progress = nil, completion = "如此我們就有第二塊水晶了。很好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31064] = {title = "砮龍與羅西克", objective = "在鷹大師砮龍的協助下殺羅西克。", description = "鷹大師砮龍已前往席克斐斯的西北方，確保最後一個螳螂人首領無法逃脫。\n\n跟上他並幫他殺死那個螳螂人首領。幫他這個忙，砮龍就會帶回最後一塊水晶。", progress = nil, completion = "最後一塊水晶是我們的了。距離最後戰役只差幾步了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31065] = {title = "蟄伏深處", objective = "到任賽看守站用望遠鏡看看。", description = "陶氏在山稜線上設置了一個望遠鏡，好讓我看她偵察到了什麼。\n\n到那裡去看看吧。", progress = nil, completion = "我們的任務就擺在我們眼前。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31066] = {title = "來自黑暗的呼喊", objective = "到奇帕利沃爾殺死被污染的聖螳。", description = "所以，你從帝國的魔爪中存活下來。你…很有韌性。\n\n卡拉西聽到北方有另一個聖螳，就在奇帕利沃爾被煞灼焦的根部附近。\n\n這個聖螳發出恐懼與苦悶的哭喊。已經沒救了。\n\n卡拉西希望殺了他。去擊敗他，完成任務之前不要回來。", progress = nil, completion = "什麼？！你怎麼有辦法…\n\n喚死者是傳說中的英雄。他一定是還沒完全醒過來。\n\n你運氣很好。", rewards = "引導低語指環難言夢魘戒指突發夢境指環甦醒至高者徽印窩巢守護者徽印您會學到：\n\n每日任務：卡拉西\n\n您還會收到：\n\n卡拉西"}
MultiLanguageQuestData['tw'][31067] = {title = "戰火的嗡鳴劃破天際", objective = "殺死阿西斯‧克泰。", description = "螳螂人總是讓我的工作變得很不容易，但現在他們太過分了。\n\n我們可以應付從柯爾斐斯來的零星攻擊，但現在…現在他們想包圍我們。更糟的是，他們把我們樹裡的琥珀都用光了。\n\n這真是難以忍受！我們需要那些琥珀！那是用來做啤酒的！\n\n他們在樹的南側挖了一個洞穴。我這裡的人手不夠，你可以幫我解決他們嗎？", progress = nil, completion = "我們不是來這裡傷害任何人的。我們只是想用這棵樹的樹液釀一點啤酒。這要求難道很過分嗎？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31068] = {title = "神聖的卷軸", objective = "把預兆卷軸帶去日落釀酒園給十歌的莉亞。", description = "「當恐懼降臨\n且戰火的嗡鳴劃破天際\n盛滿救贖之偉大容器\n須經由核心得以釋出。」\n\n這樣的文字在卷軸上持續書寫了好幾個章節。或許日落釀酒園中的某人可以破譯這神秘的訊息。", progress = "那是某種卷軸嗎？\n\n你介不介意讓我看一下？", completion = "&lt;莉亞讀完所有的訊息。&gt;\n\n這個卷軸，這…這個預言…\n\n太可怕了！", rewards = "您能選擇下列奬勵中的一個：\n\n十歌符咒十歌繩帶十歌繩結\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][31069] = {title = "束縛於暗影", objective = "在日落釀酒園附近殺死煞怪物與野生動物以收集100滴暗影。", description = "關於你找到的卷軸...\n\n我繼續讀了第二個章節，「應束縛於樹木與暗影之中」。那章所提到的「暗影」特別讓我感到好奇。\n\n我必須承認，我經常想著把這個地區殘留的一些煞的精華結合進啤酒裡。我懷疑這就是我們卷軸中所稱的暗影。\n\n你會在我們這棵樹的東南方找到大量煞的混合體...或許你也可以從當地的野生動物身上取到一些。", progress = nil, completion = "太美了。這會讓我們的啤酒更添美味。\n\n最危險的成份通常也是最美味的。", rewards = "縛影斗篷老余的披氅樹汁大師披風釀酒園斗篷日落披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][31070] = {title = "巨獸的撕裂匕首", objective = "取得3顆巨大的牡山獸牙齒。", description = "卷軸裡寫著:「巨獸的撕裂匕首」...\n\n<歐龍思考著這行文字。>\n\n牡山獸!就是這個!\n\n外頭那些晃來晃去的牡山獸有著大大的牙齒...長度就像匕首一樣。這一定就是卷軸裡說的東西。", progress = "我很好奇，我們該怎麼把這些東西混在啤酒裡？不能磨碎加進去，這樣喝起來會沙沙的。\n\n或許我該把牙齒泡在酒裡一會兒。", completion = "我以前從沒想過要把牡山獸牙齒加在啤酒裡。\n\n那個卷軸裡的想法還真夠古怪。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31071] = {title = "我讓大家蒙羞", objective = "找回遺失的桶子、遺失的酒杯和遺失的野餐補給品。", description = "我讓我的釀酒師同伴失望了。\n\n我把一些補給品帶到樹的東方的空地去...然後把它們忘在那裡了。現在煞正在污染這片土地，螳螂人四處晃來晃去，對我來說，去取回那些東西實在太危險了。\n\n若你願意幫我去把東西找回來，或許我能恢復一些名譽。", progress = "你找回東西了嗎？可能嗎？", completion = "你為我帶來了快樂，旅行者。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31072] = {title = "搶奪匕首", objective = "取得凱茲克之刃與伊利凱斯之刃。", description = "忘掉他們，忘掉他們的啤酒。我們有真正的工作要做。\n\n卷軸提到「巨獸的撕裂匕首」。我有種感覺，我知道要去哪裡找這些東西。\n\n有兩個螳螂人中尉在南方的恐怖之界巡邏。他們身上各帶有一把儀式用的匕首。\n\n把那些匕首帶回來，<name>。我們可能已經摸到某個大事件的邊了。", progress = "我想我開始理解預言中接下來的那幾行文字了，<name>。\n\n你拿到匕首了嗎?", completion = "這些匕首，你看!\n\n&lt;莉亞把兩把匕首的刀柄相對。&gt;\n\n這兩把匕首當初打造時，就是為了要結合在一起!但是該怎麼結合呢...?", rewards = "冰蝕裹手刃誓裹手奪風者裹手鬼狐裹手驚懼紡織者裹手清澈裹手枯木手甲樹蠅裹手慈母之種裹手您會收到：\n\n"}
MultiLanguageQuestData['tw'][31073] = {title = "應束縛於樹木", objective = "取得8片芳香核木。", description = "<老余看著卷軸。>\n\n嗯...「應束縛於樹木」。我們不用樹木來釀造啤酒，而是...樹液，但不是樹木。\n\n偶爾，我們會把西方那些樹人的樹心灌注到酒裡。他們大部分都被螳螂人殺了...但他們的遺體應該可以用在我們的配方裡。", progress = "我們這裡不用木頭來釀啤酒。這會讓啤酒變的生硬、乏味，跟葡萄酒完全不同。 \n\n<老余吐了口口水。>", completion = "我會把這幾片木頭準備好。\n\n我們已經收集到不少材料了!我得趕快去把鍋裡的東西煮滾。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31074] = {title = "樹木與暗影", objective = "找到女皇的印記與奇帕利柯爾的心根。", description = "「巨獸的撕裂匕首，應束縛於樹木與暗影之中。」。嗯。\n\n我待在這裡時，學過許多跟闊席克螳螂人有關的事。我知道他們在柯爾斐斯聚落中設有兩個聖壇。\n\n一個是他們所居住那株巨大樹木的心根。另一個則是一根黑色的柱子，將他們與他們的女皇連結在一起。\n\n這些聖壇肯定就是樹木與暗影。如果我預測的沒錯...匕首在那裡應該會起反應。", progress = nil, completion = "&lt;name&gt;，你看!這兩柄匕首，結合起來變成一把叉刃了。\n\n我們用對了方法。我就知道這不是啤酒的配方。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31075] = {title = "末代君主", objective = "到雷基頓村找樹汁大師老余。", description = "歐龍有個聰明的主意。他認為我們應該到西方去找妖精，看他們那裡有沒有這些材料可以要一點來。這個配方要的一些材料看起來…很奇怪。\n\n雷基頓的妖精在柯爾斐斯西方有個村落。我想在那裡跟你碰頭，<name>。", progress = nil, completion = "我有好一段時間沒在道路上釀酒了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31076] = {title = "風暴烈酒的命運", objective = "詢問日落釀酒園的居民，是否見過任何風暴烈酒的族人。", description = "你好啊，<race>。我是老陳‧風暴烈酒。\n\n我正在尋找我的家人。有人告訴我，有幾個風暴烈酒族人越過長城，去協助對抗螳螂人的威脅。我很想找到並加入他們。\n\n你有見過任何名叫風暴烈酒的人經過這裡嗎？你介不介意幫我四處問問？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31077] = {title = "愛薇‧風暴烈酒", objective = "到日落釀酒園跟老陳‧風暴烈酒碰頭，然後聆聽他的悼詞。", description = "我遲了一步。她是這麼的小…而我來晚了。\n\n應該給她一場合適的葬禮。像她這樣的小戰士值得受到更好的對待。", progress = "<老陳口中念念有詞。>", completion = "&lt;一時之間，老陳沉默了。&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31078] = {title = "漢恩‧風暴烈酒", objective = "到柯爾斐斯底下的珀光密殿找漢恩‧風暴烈酒。", description = "等會兒就要天亮了。現在，還得去找其他風暴烈酒族人。\n\n他們說最後一次見到漢恩‧風暴烈酒時，他正在探索柯爾斐斯。我懷疑他穿過這條路進入螳螂人的洞穴了。\n\n你應該到下面去跟我碰頭，<name>。我毫不懷疑自己有足夠能力對付幾隻螳螂人...但有你在身邊我覺得比較好。", progress = "我想我看到那裡有人，但我似乎無法越過這些琥珀柱。", completion = "先是愛薇，現在是漢恩。\n\n我又遲了一步。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31079] = {title = "恐懼降臨", objective = "殺死7個徘徊迷霧潛伏者與2隻奇帕利環蟲。", description = "我們被保護不受螳螂人侵擾。這項協議在數千年前就已達成。\n\n然而，現在有股力量讓我們不再安全。西方地底下的奇帕利環蟲會獵捕我們，追殺我們…甚至吃了我們。迷霧潛伏者也會用手抓起我們的族人來吃。\n\n幫助我們的人民，外來者。擊敗我們的敵人。", progress = nil, completion = "我們村莊裡有你這樣身材巨大的人是件好事。\n\n你在很多地方都能派上用場。", rewards = "奇帕利法杖奇帕利爪錘雷基頓之斧雷基頓之弓雷基頓方尖碑寶吉歐的儀式之斧雷基頓尖刺刃雷基頓之荊棘寶吉歐的棘刺神諭者之刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][31080] = {title = "熾燃雙翼", objective = "拍打雷基利亞精龍，然後抓取88份飛揚之塵。", description = "我想那古老的紙張上有提過「熾燃雙翼」的事。附近那些小龍長有翅膀，而且某種程度上也蠻熾熱的。\n\n你的速度比我快。試著去抓幾隻那種龍來...或至少把牠們身上的粉拍下來。\n\n如果你想要的只是牠們翅膀上那些亮晶晶的東西，沒必要殺害無害的幼龍。", progress = "我還沒能抓住那些東西過!", completion = "喔耶!!!是飛揚之塵!!!\n\n&lt;歐龍把粉丟進鍋裡。&gt;\n\n這啤酒變得有點，奇怪，而且聞起來很臭。我開始覺得莉亞可能是對的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31081] = {title = "精靈與根源之咒", objective = "殺死阿弓納斯與米弓納斯。", description = "我猜我們需要那些妖精的幫忙。\n\n我們有兩把附魔匕首，被樹木與暗影束縛在一起。現在我們需要某個人在我們的神器上施行古老的「咒語」。\n\n在我們請求協助之前，先向這些妖精釋出善意。我聽他們的首領提過，迷霧潛伏者綁架了他們好幾個村民。 如果我們殺掉這些野獸...或許我們就能得到「咒語」做為回報。", progress = nil, completion = "做得好。我聽到那些妖精在談論我們。\n\n我們得到他們的注意了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31082] = {title = "盛滿救贖之偉大容器", objective = "在雷基頓吟唱者的協助下，把3顆慈母之種帶回雷基頓村的收集坑裡。\n\n如果你們走散了，你可以使用雷基頓之鐘來召喚你的吟唱者。", description = "我知道你跟那個熊貓女孩在尋求什麼。我們會幫你們舉行儀式...當時間到的時候。\n\n首先，我請求你們的協助。有種子從我們偉大的母樹掉下來。收集這些種子是我們的責任，即便在這種危險的時刻也不能放棄。\n\n護送我的吟唱者到慈母之種那裡，好讓他們把種子帶回來放到收集坑裡。", progress = nil, completion = "是的，很好。慈母之種得到照顧了。\n\n現在，我們可以來討論你的附魔了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31083] = {title = "金色的承諾", objective = "到悚然荒野的雷基頓村找雷基頓老爺。", description = "那生物一死，有一群奇怪的妖精就冒出來取走了牠的珍珠。\n\n那些妖精在附近有個村莊，叫做雷基頓村。或許你該去調查一下。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n苟克拉克的殼恆龍寶箱"}
MultiLanguageQuestData['tw'][31084] = {title = "締結魔力", objective = "讓雷基頓老爺為叉刃附魔。", description = "上次有人要求我們部族進行這個儀式，已經是很久很久以前的事了。我會盡我的全力。", progress = nil, completion = "這把刀已經準備好了。\n\n現在只剩下一個任務:你得使用它。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31085] = {title = "古老的火焰與恐懼", objective = "在『思緒清晰』尹幽卡身上使用壞滅之叉，並保護他，直到他成功逃脫。", description = "我們找到這些利刃，把它們與木頭和陰影結合在一起，並用古老的咒語加以祝福。如果我沒弄錯的話，現在該是使用它的時候了。\n\n妖精提過在女皇宮殿附近一個名叫琥珀之冬的山洞裡，存有一塊古老樹液。那一定就是預言裡所說的「上古之血」。\n\n不管樹液裡有什麼東西，一定都很重要。祝你好運，<name>。", progress = nil, completion = "琥珀裡有…有一隻螳螂人？我絕不會想到，我們與螳螂人之間的戰爭的解決方式居然會是…另一隻螳螂人。\n\n我還有很多事要學，但有一件事我很肯定:那絕對不可能是啤酒的配方。", rewards = "慈母之種足靴樹蠅護足枯木脛甲清澈護脛驚懼紡織者足靴鬼狐長靴奪風者脛甲刃誓戰靴冰蝕戰靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][31086] = {title = "上古之血", objective = "取得一個大塊的凝固琥珀。", description = "我跟莉亞都同意一件事，「上古之血」幾乎可以肯定是這個區域中大樹的樹液。我早該知道的，我一天到晚都在用那玩意兒釀啤酒。\n\n其中最古老的樹就是杉齊爾女皇居住的地方，人們稱那裡為恐懼之心。從那棵樹上找來一些琥珀，我們的啤酒應該就能完成了。", progress = "運氣如何？", completion = "這應該管用!配方...完成了。\n\n現在我們來看看啤酒的滋味如何。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31087] = {title = "擴大涵蓋範圍", objective = "到珀光洞穴開啟共鳴信標。", description = "卡拉西瓦聽到了另一名聖螳的訊息。他的呼喊很微弱，散失在黑暗中。得把他的訊號強化才行。\n\n在琥珀之光洞穴裡有座沉寂已久的塔。必須讓它再次歌唱，這是卡拉西的旨意！\n\n這一次，我會和你一起。你要幫助我修復它。\n\n帶著這塊共鳴水晶，到琥珀之光與我碰面。", progress = nil, completion = "很高興你及時趕到。\n\n也許你不像我想的那樣沒用…\n\n卡拉西瓦正在對那個聖螳歌唱。很快他們就會知道該派你到哪裡去。眼前，還有其他的任務要做。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31088] = {title = "罪與罰", objective = "在尖刺小徑殺死8名伊克席克收割者。", description = "尖刺小徑裡長有許多年輕的奇帕利樹。外來者，女皇過早抽取了裡面的樹液。必須等它們長成才能取走裡面的琥珀。\n\n卡拉西瓦要看到這種罪行得到懲罰！如果你能殺死那些伊克席克收割者，他們會很高興的。", progress = nil, completion = "卡拉西對我們的成果很滿意，外來者。事實證明，你比我們所想的更有用。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31089] = {title = "海，永不復返", objective = "在被海水侵蝕的石頭上使用卡克西音叉，以喚醒聖螳。", description = "卡拉西瓦和我說過了，外來者。聖螳就躲在潮間帶裡，但他的行蹤已經暴露了。\n\n他被蜥蜴人給包圍。絕不能讓他落入他們長滿鱗片的手中。\n\n你要去找到他。喚醒他。帶著他一起回來!\n\n成功之後，卡拉西瓦會對我們感到很高興的。", progress = nil, completion = "你...你是哪種生物?\n\n你怎麼會喚醒我?", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31090] = {title = "熟成", objective = "從尖刺小徑的琥珀收集裝置那裡取得7份裝滿琥珀的罐子。", description = "砍伐年輕的樹是種罪，但浪費琥珀的罪孽更重。\n\n青澀的琥珀沒那麼強力，但卡拉西需要它才能繼續戰鬥。我們要找來更多琥珀，讓他們對我感激不盡!\n\n去收集青澀的琥珀。我們會把它們儲藏起來，直到它們成熟並可食用為止。", progress = "我很想跟你一起去收集琥珀，但我的才能在這裡更能派上用場。", completion = "即使是生琥珀也有用處。這種時候我們不能太吹毛求疵。\n\n卡拉西瓦會賞識我這種想法。我會跟他們提你幫上的忙!", rewards = "珀光墜盒珀光頸飾珀光項鍊珀光墜飾珀光護符您會收到：\n\n卡拉西"}
MultiLanguageQuestData['tw'][31091] = {title = "團圓的感覺真好", objective = "在『操縱者』卡茲提克挖出他最大的武器時支援他。", description = "你看著我，覺得我不會是個好戰士。為什麼我會被選為聖螳？有的武器不能被肉眼看見，喚醒者。單憑外表無法判斷一個人。\n\n在我做進一步解釋之前，我必須知道你值得信任。\n\n在我被保存起來的時候，有某個對我而言很珍貴的東西被藏起來了。沒有它，我什麼都不是。\n\n在我挖出我最強的武器之前保護我，如此你便能得到我的信任。", progress = nil, completion = "科沃克就跟我上次看到牠的時候一樣棒。牠一定能為卡拉西取得偉大的勝利。", rewards = "慈母之種兜帽樹蠅頭盔枯木頭盔清澈頭罩驚懼紡織者風帽鬼狐頭盔奪風者頭盔刃誓頭盔冰蝕頭盔您會收到：\n\n慈母之種兜帽樹蠅頭盔枯木頭盔清澈頭罩恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31092] = {title = "餵我，不然就讓我吃了你", objective = "在潮間帶的鹹水殼鉗嘴龜身上取得6塊多汁烏龜肉片來餵食科沃克，以開始牠的訓練。", description = "多年來和崑蟲一起工作的經驗，讓我發展出一個理論。從幼兒開始養大一個崑蟲，會強化情感和聲波的連結。\n\n我獲選為要被保存下來的聖螳時才剛開始訓練科沃克。他仍然十分年輕，需要勤勉的訓練來發揮所有的潛力。\n\n我將科沃克交給你，但要小心，如果他受到任何傷害，你的小命也沒了。\n\n首先你得餵食他，好贏得他的信任。附近的烏龜應該就可以了。", progress = nil, completion = "非常好!我本來預測科沃克有可能會把你吃掉。看到你們兩個都完整無缺，真是個愉快的驚喜。\n\n或許養育崑蟲是你的天職。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31093] = {title = "霧中的猴人", objective = "把霧中的猴人帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n你對猴人的研究相當具啟發性。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "猴人天生就是蠻橫霸道的一群傢伙。\n\n我們會將這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31094] = {title = "錦魚人的故事", objective = "把魚尾巴帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n閱讀你關於錦魚人的研究是種徹底的享受。真是個迷人且相當聰明的種族。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "這是真正的享受。我一直很喜歡錦魚人。他們是如此和平的種族，而且感恩上天賜給他們智慧。\n\n我們會把這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31095] = {title = "魔古的黑心", objective = "把魔古的黑心帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n我們一向都知道魔古既黑暗又邪惡。然而你的研究指出他們遠比我們所知道的更壞。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "魔古。即使只是吐出這兩個字，都讓我毛髮直豎。我們會把這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31096] = {title = "什麼才值得一戰", objective = "把《什麼才值得一戰》帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n你發掘出的故事，是關於我們的人民在魔古帝國統治下，爭取自由的故事。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "誰想得到，熊貓人民的自由就始於一個揮拳。\n\n太奇妙了。我們會把這個事件加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31097] = {title = "螳族之心", objective = "把螳族之心帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n雖然我們十分感激你努力調查潘達利亞上的傳說，但你送來關於螳螂人的文件還是讓我失眠了好幾個晚上。恐怖的東西。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "當你開始做這個研究的時候，我沒想過可以學到這麼多關於這個可怖種族的資訊。我們會把這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31098] = {title = "《云端翔龙骑士团的建立》", objective = "将《云端翔龙骑士团的建立》带给闻道之座的游学者周卓。\n\n已提供物品：\n", description = "亲爱的$p，\n\n我们已经将你所发现的有关云端翔龙骑士团的传说整理成了一个精彩的故事。\n\n如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。\n\n感谢你的努力！\n\n此致，\n\n游学者周卓您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31099] = {title = "《卡拉克西之战》", objective = "将《卡拉克西之战》带给闻道之座的游学者周卓。\n\n已提供物品：\n", description = "亲爱的$p，\n\n你关于卡拉克西的发现令我们非常震惊。\n\n如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。\n\n感谢你的努力！\n\n此致，\n\n游学者周卓您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31100] = {title = "揚古之歌", objective = "把揚古之歌帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n你的揚古研究表現出深刻的見地。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力!\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "揚古是好戰的族群，在長城的另一邊流亡，並因此愈發強壯。我們會把這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31101] = {title = "《酒中仙传奇》", objective = "将《酒中仙传奇》带给闻道之座的游学者周卓。\n\n已提供物品：\n", description = "亲爱的$p，\n\n你那份关于酒中仙的调查报告非常……令人垂涎。\n\n如果你能来闻道之座一趟，我们就可以将这一成果加入你的私人收藏。\n\n感谢你的努力！\n\n此致，\n\n游学者周卓您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31102] = {title = "紹昊背負的七件重擔", objective = "把紹昊背負的七件重擔帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n看來你已經收集到與潘達利亞最後一個皇帝「紹昊」有關的所有傳說了。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力!\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "我一直想把這個故事挖掘出來。自從煞被釋放出來後，我心中有種感覺，這個故事是所有事件的核心。\n\n我們會把這份知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31103] = {title = "劉浪的民謠", objective = "把劉浪的民謠帶去知識之座交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n多虧你的研究，我們終於擁有完整的劉浪的民謠。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "這個失傳已久的故事是關於劉浪和他的漂流島。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31104] = {title = "挑戰者競技場:雅里亞‧賢語者", objective = "在挑戰者競技場挑戰雅里亞‧賢語者，並擊敗她。", description = "影潘弟兄與姊妹們不停討論著你的事蹟，<name>。\n\n事實上，雅里亞對你的修業成果感到很大的興趣。\n\n她想在訓練場挑戰你。\n\n你最好能盡力表現。如果你有辦法讓她佩服你，未來她或許會願意協助你。", progress = nil, completion = "你做到了!你擊敗了雅里亞!\n\n你肯定贏得了她的支持，&lt;race&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31105] = {title = "魔古的威脅", objective = "殺死12個衫織縛蛟者或衫織馴獸者。", description = "我們的斥候在西北方的衫織島上，發現一隊重裝魔古軍隊。\n\n那裡應該是個無人島，因此他們的出現是個令人不安的消息。\n\n更令人不安的是，他們正在那個島上進行邪惡的實驗。\n\n我需要一個能幹的<class>去確認一下情況。\n\n衫織那些傢伙可能會找你麻煩，那樣的話就殺了他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31106] = {title = "魔古的威脅", objective = "殺死12個衫織縛蛟者或衫織馴獸者。", description = "我們的斥候在西北方的衫織島上，發現一隊重裝魔古軍隊。\n\n那裡應該是個無人島，因此他們的出現是個令人不安的消息。\n\n更令人不安的是，他們正在那個島上進行邪惡的實驗。\n\n我需要一個能幹的<class>去確認一下情況。\n\n衫織那些傢伙可能會找你麻煩，那樣的話就殺了他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31107] = {title = "新帝國子民", objective = "到奇帕利沃爾收集10個弗爾席克蛋。", description = "在杉齊爾的命令下，偉大的奇帕利之樹奇帕利沃爾被扭曲成了一個恐怖的圖騰。\n\n就像皇宮外的窩巢一樣，附近的窩巢被用來腐化我們的蟲群。\n\n取回弗爾席克的蛋吧，喚醒者，我們會在這裡撫養他們。他們將成為新帝國的子民，不受煞的腐化。", progress = "奇帕利沃爾曾經很美麗。富含琥珀，周遭全是豐饒的獵場。", completion = "他們體型很大。很快就會孵出來了。\n\n很好。我們可能會需要他們。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31108] = {title = "凝集恐懼", objective = "從奇帕利沃爾的弗爾席克塑懼者身上收集4個恐懼琥珀。", description = "琥珀就是力量。它帶來力量。\n\n你給我帶來的這個…恐怖的琥珀已經被扭曲了。它是恐怖的結晶。\n\n弗爾席克清楚這件事。他們的奇帕利完全被煞吞沒，他們用這種恐怖琥珀來催生他們的蟲群。\n\n把弗爾席克塑懼者用在儀式裡的那些水晶帶來給我。卡拉西會研究他們，決定摧毀的方式。", progress = "你弄到結晶了嗎？", completion = "我在想，若是你吃一個下去會發生什麼事？它會對你柔軟粉紅的內部造成什麼影響？", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31109] = {title = "摘除蟲群", objective = "在杉齊爾窩巢殺死40個杉齊爾螳螂人。和『奪風者』基爾魯克談話來進行空投。", description = "女皇持續擴張著部隊。若不加以干涉，他們肯定會侵入長城，就算那代表成千上萬的群生幼螳將死於非命。\n\n我們來幫這些屍體找個更好的場所吧。\n\n準備好前往窩巢時就告訴我。我會很樂意地將你空投到裡面。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31110] = {title = "穿過傳送門", objective = "收集1000份遠古魔粉。", description = "啊，我正想找你這樣的<class>!\n\n我們終於弄清楚傳送門失效的原因了。我們需要更多的魔粉!\n\n要取得足夠的魔粉可能得花掉我們好幾個月時間，不過幸運的是，這座島上的魔古為了施放法術，帶了為數可觀的魔粉。\n\n他們用的東西多半很老舊，所以我們得收集很多的量。", progress = "你有找到魔粉嗎?", completion = "太完美了!太完美了!\n\n就是這玩意兒，&lt;name&gt;。\n\n我們會立刻開始工作。我敢說一定很快就能完成。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31111] = {title = "撲滅贊席克", objective = "到贊斐斯殺死6個贊席克穿刺者與6個贊席克操控者。", description = "贊斐斯的戰士是帝國中最受到敬畏與尊重的戰士，而且理由充分。\n\n只要有長柄武器在手，這些刺殺者就是無敵的。毫無疑問，瑪力克在他的時代中曾與贊席克一起受訓。他們的操控者能支配恐怖的聲波，就像呼吸一樣容易。\n\n必須把他們都解決掉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31112] = {title = "他們刺真多!", objective = "從水之妖精身上收集5份緊急補給。", description = "這箱子裡曾經裝滿必需品，但現在已完全被掠奪一空。\n\n迅速掃視這個區域後，竊賊留下的證據映入眼中。冰冷的刺，就跟東邊海岸的水之妖精身上的刺一樣。\n\n對於你們這些倖存者來說，這是攸關生死的狀況。必須從那群小賊胚手上把補給品搶回營地。", progress = "夥伴，你拿到那些補給品了嗎?", completion = "瞧瞧!\n\n這些補給品足夠讓我們多撐個幾天。\n\n還有我的靴子!你竟然沒把它們炸掉。幹得好，&lt;name&gt;!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31113] = {title = "突襲蓋州火焰營地", objective = "殺死16個蓋州揚古、蓋州地語者或蓋州投擲者。", description = "揚古一直都是個麻煩。不過北邊火焰營地蓋州的那些傢伙，最近與歐索揚古合謀入侵崑萊。\n\n我們絕不容許這些入侵者逍遙法外。\n\n去攻擊火焰營地蓋州。我們得確實佔據那裡，讓他們沒法再次威脅玄牛關。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31114] = {title = "突襲死語者高地", objective = "殺死8個死語者褻屍手與1個死語者碎骨手。", description = "我們一向不會去理會死語者。長久以來，他們只負責維護揚古部族的神聖墓地而已。\n\n然而現在，他們正在練習黑魔法，並玷污他們過世同族的屍體...\n\n我不知道他們去哪裡學的黑魔法，也不知道他們為什麼不再尊重亡者，但我們沒時間研究這些事了。\n\n必須阻止他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31115] = {title = "FLAG - Freed Han", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31116] = {title = "靈魂之塵", objective = "在螳螂荒原的死語者高地將8個靈魂送回遺體。", description = "揚古從他們祖先遺體中捕獲的靈魂，還殘留有些許的生命精華。\n\n如果你在戰鬥中擊敗靈魂，你可以以靈魂之塵的型式收集那些精華，然後歸還到區域裡的屍體裡，如此，他們才終於能轉世輪迴。\n\n這是唯一能糾正死語者所作所為的方式。對於保護我們安全也有幫助。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31117] = {title = "烏魯克!", objective = "到螳螂荒原的死語者高地殺死烏魯克。", description = "烏魯克是螳螂荒原的揚古死語者。必須擊敗他，你的任務才算完成。去吧!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31118] = {title = "死語者密碼", objective = "到死語者高地從揚古身上收集一個縛靈儀式卷軸。", description = "我們得弄清楚死語者到底出了什麼問題。\n\n這麼多年來，死語者一直只負責維護墓地、並為死去的戰士舉行葬禮。\n\n但在最近的進攻裡，我們在地上發現一塊肯定是用密碼寫成的石板。但這種密碼我們從來也沒見過。如果能從某個死語者那裡取得一份加過密的卷軸，我們就能開始解析密碼，理解眼前的狀況。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31119] = {title = "我敵人的敵人...還是我的敵人!", objective = "在蓋州戰場上使用高爆型揚古油桶，殺死100個螳螂人或揚古。", description = "螳螂人是我們的敵人，就像蓋州火焰營地的揚古一樣。\n\n不過，幸好他們也與彼此為敵。來自克里斐斯的螳螂人不斷攻擊蓋州揚古，揚古則將他們抵擋在門外。\n\n我要你去製造騷動。從蓋州營地裡「借」一些高爆型油桶，然後從空中把油桶丟在他們的戰場上。\n\n我不在乎你殺死的是哪一方的人，多殺點就對了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31120] = {title = "程波!", objective = "到螳螂荒原的蓋州火焰營地殺死程波。", description = "程波是蓋州火焰營地的戰爭使者。你已對他們的行動造成打擊，現在你有機會給他們重重一擊。\n\n殺死這個戰爭使者!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31121] = {title = "請留步，聽我說個故事", objective = "從阿洲的茶壺裡喝茶。", description = "趕趕趕，你們這些人總是這麼匆匆忙忙的嗎？\n\n坐下來跟我喝一會兒茶，我們來討論一下你的處境。\n\n<博學行者阿洲臉上掛著一抹有耐性的微笑。>", progress = "我希望我不會讓你覺得很無聊，旅行者。", completion = "我會幫你，旅行者，但首先我想了解一下你的部落…", rewards = "您會收到：\n\n恆龍寶箱"}
