MultiLanguageQuestData['tw'][31127] = {title = "挑戰者競技場:『大聲公』小趙", objective = "到螳螂荒原的影潘要塞挑戰『大聲公』小趙，並在戰鬥中擊敗她。", description = "看來你是個了不得的戰士，$p。\n\n小趙聽說了你的事，而且她說她要狠狠踢你的...\n\n嗯，這樣說吧，我覺得你應該去挑戰她，試著讓她尊敬你。", progress = nil, completion = "我確定你們之間不會有芥蒂。她只是熱愛一場好戰鬥。下次我有任務給你時你應該去跟她談談，她是個很有才能的戰士，我相信你已經見識過了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31128] = {title = "挑戰者競技場:『鐵肚皮』老秦", objective = "到螳螂荒原的影潘要塞挑戰『鐵肚皮』老秦，並在戰鬥中擊敗他。", description = "老秦頭上似乎有一片烏雲...或者，更確切的說，他的啤酒裡有一片烏雲。\n\n經過最近幾場戰役後，他似乎整個人沉溺於研發完美的戰鬥用啤酒。\n\n那沒什麼不好，但我們需要他到外面去進行真正的戰鬥!\n\n你應該去挑戰他，看能不能把他從這瘋癲狀態打醒。\n\n如果你擊敗他，或許他會為了想領先你，而到外頭去協助戰鬥!", progress = nil, completion = "哇喔，你一定讓老秦很欽佩。他不停說著他到外頭跟你戰鬥有多刺激。做得好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31129] = {title = "風暴烈酒的命運", objective = "詢問日落釀酒園的居民，是否見過任何風暴烈酒的族人。", description = "$p！看到你健健康康的，還來到這麼遠的地方。真好。看來我們倆的道路相當緊密地交織在一起。\n\n我來這裡是為了尋找我的家人。有人告訴我，有幾個風暴烈酒族人越過長城，去協助對抗螳螂人的威脅。我很想找到並加入他們。\n\n你有見過任何名叫風暴烈酒的人經過這裡嗎？你介不介意幫我四處問問？", progress = nil, completion = "&lt;老陳專心地聽著。&gt;\n\n大丹、漢恩、愛薇跟大娘。我了解了。\n\n大丹在這裡似乎很安全。我會去找漢恩、愛薇跟風暴烈酒大娘。\n\n一路順風，&lt;name&gt;，追隨浪人之道。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31130] = {title = "與博學行者阿洲的會面", objective = "在房屋四周協助博學行者阿洲，以和他成為朋友:修剪樹木，粉刷牆壁，以及餵他的鳥。", description = "陌生人，我或許有辦法幫助你找到你的王子。但首先，我想多知道關於你和你人民的事情。\n\n來，幫幫我，我們邊做邊聊天。\n\n你看起來像是久經戰陣的老兵，但顯然你有時間能幫助一個書獃子熊貓人整理房子，對吧？", progress = "沒有什麼比小小的勞動更能讓兩個陌生人親近了，你不認為嗎？", completion = "儘管征戰多年，你仍然有雙美麗的眼睛，&lt;name&gt;。我喜歡你這個特質！\n\n現在，我們來尋找你失蹤的王子吧。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31131] = {title = "白瓣湖", objective = "到白瓣湖找何·軟足。", description = "根據報告，白瓣湖今天很平靜，但我派出倫·火舌與何·軟足去確保安全。\n\n如果你想幫忙，往西走到湖邊，和何·軟足碰面，幫他應付任何威脅。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31132] = {title = "穿我的鞋走一哩路", objective = "到白骨之環找博學行者阿洲。", description = "喔，我真沒禮貌。理論上，我算是這裡的主人。\n\n在向你提出問題之前，我該介紹一下關於我和我同胞的事。", progress = nil, completion = "我想，要向你解釋何謂博學行者，最好的辦法就是讓你自己看看…", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31133] = {title = "闊席克攻擊", objective = "到柯爾斐斯殺死17個闊席克螳螂人。", description = "我不是釀酒師，光看這些原料就讓我頭昏眼花。只要完成之後把啤酒放在我面前就好，謝謝你。\n\n不，我來這裡是為了確保釀酒師們在試著釀造完美啤酒時，不會突然被砍成兩半。這不是個容易的工作。\n\n橫跨這個流域的闊席克螳螂人每晚都來攻擊我們。如果你打算到那裡去，何不攻擊幾個螳螂人做為回報？", progress = nil, completion = "你有成為釀酒園警衛的優良素質，&lt;race&gt;。如果你哪天對當個「&lt;class&gt;」感到厭倦的話，告訴我一聲。", rewards = "日落緞質兜帽日落皮頭盔枯木軟帽日落光潔頭罩日落絲質風帽日落皮甲頭盔奪風者護盔日落重型頭盔日落裝甲頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][31134] = {title = "如果這些石頭會說話", objective = "在白骨之環使用原石石碑。", description = "這是很古老的地方，旅人。\n\n我最近才發現翻譯這些石頭上古老語言的方法。\n\n喔，重大的發現總是讓人興奮得顫抖！真是永遠都不會膩，真的。\n\n來，你是客人，交給你來。別客氣。\n\n用這鑰匙解開石頭中的秘密。", progress = nil, completion = "我想今天已經翻得夠多了。\n\n我希望這是一次具啟發性的經驗。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31135] = {title = "諾姆瑞根的未來", objective = "到新地精區找『短者之友』西。", description = "每當我們幫助一個生還者逃出被污染的諾姆瑞根大廳，對我們來說就是一次勝利。像你這樣的<class>，將在諾姆瑞根的未來扮演舉足輕重的角色。為此，我們的領袖，大工匠梅卡托克召集了一群訓練師，幫助你學習技藝。\n\n『短者之友』西，她從遙遠的地方來到這裡，她將監督你的訓練，幫助你適應地面的生活。她在路對面的小練習場等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31137] = {title = "會見大工匠", objective = "向新地精區的大工匠梅卡托克介紹你自己。", description = "不知道你還記不記得梅卡托克。納文跟其它地精告訴我，喪失記憶在你們這些生還者身上是很常見的事。\n\n總之，大工匠梅卡托克是全地精的領導人。他習慣親自會見每個獲救的生還者。你應該向他介紹一下自己。他與他的戰爭顧問就在城鎮中心帳篷下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31138] = {title = "武僧之道", objective = "将等级提升至3级后学习猛虎掌。学成之后，在新工匠镇的训练假人身上使用两次。", description = "通过战斗，你的技能将有所提高。随着技能的提高，你将开始领悟出新的招式。去吧，去探险，去学习，然后向我展示你学到了什么。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31139] = {title = "打退他們!", objective = "殺死6隻黑石座狼。", description = "所以你就是暴風城來的新兵?我是治安官瑪克布萊德，此地駐軍的指揮官。歡迎你加入...\n\n<瑪克布萊德掃視著文件。>\n\n<name>。是叫<name>，對吧?\n\n你來的時間剛好。黑石獸人經由山區的空隙潛進了北郡。我的手下士兵正盡全力擊退對方，但我擔心他們很快就會被擊潰。\n\n前往西北方的森林，殺死進攻的黑石座狼吧!幫助我的士兵!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士繫腰座狼管理者手套行者腰帶追跡者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][31140] = {title = "誘獅入羊群", objective = "殺死8名黑石間諜。", description = "入侵的獸人不是傻子。他們在估量我們，確保每一次攻擊都能為自己帶來優勢。\n\n在西北邊的森林裡有些黑石間諜。他們利用望遠鏡窺視我們，觀察我們每一個動作，並且等待時機。我要你去找他們開戰!\n\n殺光那群黑石間諜!必須讓他們了解:我們知道他們正在觀察，而我們有所準備!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士長袍間諜大師護腿暴風城步兵腰帶間諜派遣人護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][31141] = {title = "手写书信", objective = "阅读手写书信，然后和北郡修道院的阿宝谈一谈。", description = "有人托我在你处理完黑石间谍的事情之后把这个东西交给你，<name>。看起来像是一封用阿宝的印章密封的书信，阿宝是从远方来到这里的一个熊猫人。我想在你处理修道院的其他事情之前尽快读一下这封信。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31142] = {title = "猛虎之掌", objective = "将等级提升至3级后学习“猛虎掌”，然后在北郡修道院入口南面的训练假人身上进行练习。", description = "既然你已有机会在战斗中测试自己的能力，那么是时候向你解释我们如此重视训练的另一个原因了。\n\n随着经验的增长，你将能够学习超出自己想象的新技能。\n\n去吧，再积累一些经验，学习一项新技能，然后找一个训练假人进行练习。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31143] = {title = "加入戰局!", objective = "到艾爾文森林後面的北郡修道院找維里中士。", description = "我收到一道來自維里中士的緊急訊息。看來黑石獸人雇用了哥布林暗殺者。他們在修道院後面伏擊了我們的部隊。維里請我派給他一名英雄。你得去幫助他們，<name>！\n\n到修道院北邊的指揮營帳去找維里中士。快去！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31144] = {title = "他們派來的刺客", objective = "殺死8名哥布林暗殺者。", description = "你見過哥布林嗎，<name>？他們是卑鄙的小怪物，最喜歡的兩樣東西是黃金和他們自己。\n\n黑石獸人取得了哥布林暗殺者的援助，派他們來殺死我們的士兵。如果你到北邊的原野上尋找，就能在草叢間看到他們潛行的輪廓。\n\n我要你過去那裡殺死你所見到的每一個哥布林。必須讓他們知道：沒有人可以招惹聯盟！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "服飾商手套旅行之靴休閒手套先遣騎腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][31145] = {title = "後顧無憂", objective = "到艾爾文森林的北郡修道院前面找治安官瑪克布萊德回報。", description = "做得好啊，<name>!如今後方真的是清理乾淨了。我們會負責料理脫隊的傢伙。我要你回去南邊的北郡修道院前面找治安官瑪克布萊德，讓他知道哥布林的問題已經得到控制。\n\n再見，<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31146] = {title = "潦草的卷轴", objective = "阅读精致的卷轴，然后和丧钟镇的铁胆海胃丁绿衫谈一谈。", description = "呃，当你在外面对付那些愚蠢的天灾军团时，我们收到一个寄给你的卷轴，是个叫丁绿衫的熊猫人寄的。或许你们武僧能看懂这种乱七八糟的东西，反正我看不懂。你应该和她谈一谈，她在街对面的旅馆里。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31147] = {title = "猛虎掌", objective = "等级提升至3级后学习猛虎掌，然后在训练假人身上练习运用掌法。", description = "在你克服并突破身心内外的桎梏时，你会释放潜藏在体内的新能力。去吧，深入并掌控自我，打开通往猛虎掌绝技的大门。然后去找一个训练假人来练练手。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31152] = {title = "凝視過去", objective = "到石之環找博學行者阿洲。", description = "耽誤一下時間。讓我整理一下東西。\n\n我們可不想弄丟這些筆記，對吧？特別是你冒著斷手喪命的危險去拿到它們！\n\n好啦，搞定了。讓我們出發吧？\n\n我得說，看見你料理那隻薩烏洛克後，我感覺特別安全！", progress = nil, completion = "我最感激的就是祖先傳給我的這些知識。\n\n我站在他們所築下的根基上。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31153] = {title = "Tracking Event - Saved Diaani", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31154] = {title = "Tracking Event - Saved Zuulo", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31155] = {title = "Tracking Event - Saved Arekk", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31156] = {title = "智者的来信", objective = "阅读手写羊皮纸，然后和试炼谷的贾徒谈一谈。", description = "呃，你不在的时候，我们收到了一封羊皮纸书信，<name>。\n\n有时间的话看一下吧。如果我没有猜错，这封信是我们的熊猫人朋友贾徒寄来的。他云游四方，和我们分享他的智慧，向我们传授武僧的修行之道。要聆听他的教诲，不要让你们的族人蒙羞！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31157] = {title = "猛虎掌", objective = "将等级提升至3级后学习猛虎掌。选定一个训练假人，然后对其使用2次猛虎掌。", description = "在你不断训练的过程中，你会逐渐发现自己体内蕴藏的能量，它们足以帮你领悟新技能。你甚至不需要我或其他经验更丰富的武僧来教导你——它们自然而然就会浮现在你心中。\n\n但现在，你还得继续练习基本要领。积累更多经验，开发新的技能——学会后，你可以在附近的假人身上练习并熟练掌握。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "虎掌裹布"}
MultiLanguageQuestData['tw'][31158] = {title = "基本原則:攻擊", objective = "摧毀6個訓練假人。", description = "好吧，夥伴。我們從基本的開始。我需要知道你懂得怎麼使用你拖來拖去的那些武器。\n\n去攻擊那些訓練假人。慢慢來。天生好手。我要來看看你的攻擊招數，然後我們就從那裡開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31159] = {title = "暗矛中興", objective = "到暗矛訓練場找薩柏瑞克斯。", description = "暗矛部族長久以來一直都是受害者，是流亡者。我們發現自己一次又一次的逃離自己的家園...但這一次，並不是逃亡讓我們來到這裡。\n\n沃金用他的智慧帶領著我們，這幫助我們一直生存到現在。現在，這個智慧給予了我們一個預兆，揭示出部落在卡爾洛斯‧地獄吼帶領之下的混沌未來。\n\n不，這次我們不逃亡。這一次，我們要為家園戰到最後一刻。\n\n是你開始訓練的時候了，<name>。往東走去找薩柏瑞克斯談話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31160] = {title = "艱難的開始", objective = "取得6份蠻鬃山貓皮。", description = "來實際運用那些技能吧。我會讓你從簡單的開始，老兄。\n\n有些大貓在屠殺我們的野豬。我們可不分享食物。如果你晚上想吃東西，那些野豬就得活得好好的。\n\n那些大貓整座島上都是。給我帶一些大貓的毛皮來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31161] = {title = "試煉場", objective = "和一名暗矛獄卒談話，然後進入試煉場殺死一名被俘虜的惡鱗斥候。", description = "你做得很不錯，<class>。我確定自己還能多教你一些有的沒的技巧，但我不想再用訓練假人浪費你的時間了。\n\n因此我為你準備了一場試煉，老兄。前往這塊區域中央的試煉場，和一個真正的壞傢伙作戰。一個真正想要殺死你的壞傢伙。準備好時就讓試煉場的獄卒知道吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗矛武僧法杖"}
MultiLanguageQuestData['tw'][31162] = {title = "武僧之道", objective = "将等级提升至3级后学习猛虎掌。在那些蒂基面具假人身上练习一下猛虎掌。", description = "随着在战斗中的表现越来越好，你将开始发现一些你从没想过自己能做到的事情。\n\n想见识一下吗？去吧，多加练习，学习一些新事物。\n\n然后回到这里向我展示。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31163] = {title = "超乎預期", objective = "到暗矛要塞向沃金回報。", description = "你真的是超乎預期，老兄。我確信還有其他更重要的事務需要你的天賦。你不必繼續和這些新手混在一起了。\n\n前往東南方的村莊，讓大家認識你。到處幫幫別人，我確定你很快就能接觸到更有份量的要事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31167] = {title = "族譜", objective = "在石之環點燃薰香。", description = "就是這樣了，旅行者，作為介紹應該算足夠了，是嗎？\n\n那麼，你是什麼人？你的人民跟我的有很大的不同嗎？\n\n當然，我們之間一定有共通點。讓我們看看…", progress = "真是愉快的一天，不是嗎？", completion = "你和我，我們之間並沒有太大不同。\n\n我相信我們可以成為好朋友。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31168] = {title = "手写魔符", objective = "与幽影谷中奥达希尔里面的劳希谈一谈。", description = "熊猫人访客劳希派了一位信使过来，给了我这个魔符。看来他想占用你几分钟时间谈一谈。你先看一下，接着再去他那边。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31169] = {title = "武僧之道", objective = "将等级提升至3级后学习猛虎掌。找一个训练假人，在它身上练习使用猛虎掌。", description = "禅道的奥义在于释放隐藏在你身体里的知识与能量。\n\n出发吧，积累经验，去学习新的技能。然后找个训练假人演练一番。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31171] = {title = "虎掌", objective = "到達等級3以學習虎掌。在日尖塔外找一個訓練假人，用它來練習虎掌。", description = "很好。你有一個光明的開始。這條路會很漫長，當你學會的東西越多，你會發現你能做到自己以前想像不到的事。\n\n去吧，累積更多經驗，學會新技能。學會之後就在訓練假人身上演練一番。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31173] = {title = "猛虎掌", objective = "将等级提升至3级后学习猛虎掌。在坠毁点西北侧找一个训练假人，利用它进行练习。", description = "希望你的人安然无恙……坠毁的声音震耳欲聋！\n\n<墨乔仔细打量着你，揣测你的潜力。>\n\n对，你肯定行的。他们说需要更多人手加入战斗，他们不想我伤及自己。我并不怯战，但我也不想冒犯他们。所以，我要教你功夫。\n\n可能你已经发现了，你的战斗经验可以进一步激发你内在的潜力。去吧，看你能否掌握新的技能，证明给我看。你会摸着窍门的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31175] = {title = "『覓血者』斯其爾", objective = "到水下洞穴喚醒『覓血者』斯其爾。", description = "我們保護淺灘不被贊斐斯入侵的努力已經奏效了。\n\n我們發現了另一個埋在琥珀中的聖螳，就藏在西南方的水域裡。\n\n找到另一個聖螳加入我們的行列是必要的。多一名歷史上的英雄，就可以將戰局轉成對我們有利的情勢。\n\n我很想立刻動身前往，不幸的是，這裡需要我。\n\n既然你已經是個喚醒者，你可以代替我去執行這個任務。", progress = nil, completion = "這種飢餓感…他們說過會餓得很厲害，但我沒料到會到這種程度。\n\n這種感覺真怪，這種…虛弱的感覺。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31176] = {title = "奇怪的口味", objective = "收集12份海星肉。", description = "食物。我需要食物。\n\n在我的時代，海星的肉不只能帶來力量，還能讓提神醒腦。我必須吃海星肉。\n\n從附近的淺灘帶一些來給我。\n\n等太久的話，我就會把你給吃了。", progress = "多汁的海星肉可以讓我神智清醒。", completion = "沒錯，把它拿過來！做得好，喚醒者。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31177] = {title = "豐盛的晚餐", objective = "收集8條龍蝦人尾巴。", description = "在我生活的時代，我是蟲群中最偉大的戰士。\n\n幫助我取回我的力量，我會證明給你看。\n\n我聞到附近有海水的鹹味，而有海的地方，你就能找到鹹水龍蝦人。\n\n把他們的尾巴帶來給我，好讓我飽餐牠們新鮮的肉。", progress = "我有許多工作要做。我越快能開始戰鬥，就能越快回議會去。", completion = "太完美了。這會給我力量去戰勝敵人。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31178] = {title = "血腥的喜悅", objective = "從恐印魚身上收集100份烈性之血。", description = "一個戰士得先嚐到敵人的鮮血，才能準備好上戰場。\n\n我虛弱得無法狩獵，所以你必須代替我去。\n\n只有兇猛掠食者的血才有用。我聞到牠們在洞穴外的水裡！\n\n把血帶來給我，那麼或許你就能見識到他們稱我為「覓血者」的原因。", progress = "喝下你敵人的血，你就能獲得他們的力量。", completion = "很好，這能管用。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31179] = {title = "血的氣味", objective = "殺死12個泥鱗食肉者與泥鱗蛇人。", description = "你不在的這段時間，恐怕我已經讓薩烏洛克的鮮血液沾滿我的雙手了。\n\n我很抱歉，但我控制不了自己。你看，他們要來攻擊我了。\n\n真可悲！\n\n他們想為死掉的族人報仇嗎？他們要挑戰我？\n\n身經百戰贏過上百場戰役的我？以一擋千，大吼著「有膽就上！」的我？\n\n不，這些…薩烏洛克…會在被火焚身之前先像紙一樣被我揉成一團！\n\n我要向你展現我的力量，喚醒者。跟我並肩而戰，並張大眼看清楚。\n\n他們來了！", progress = nil, completion = "你再次成功了。做得好，喚醒者。", rewards = "覓血者之斧覓血者釘錘喚醒者之盾喚醒者之眼鹽鱗匕首喚醒者之顎喚醒者之光百戰編年史您能選擇下列奬勵中的一個：\n\n英雄的獎金\n\n您還會收到：\n\n覓血者之斧覓血者釘錘喚醒者之盾喚醒者之眼恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31181] = {title = "新鮮的壺", objective = "到寂寞灣為10個空的螃蟹壺放餌。每個陷阱需要2份海霸王的肉塊。", description = "在外頭有一大票需要新鮮誘餌的空蟹壺。\n\n當然，我們大可以把牠們一個個引誘過來，舒舒服服地釣起牠們。坐在一張舒服的椅子上，也許來杯熱茶讓身體暖呼呼的。聽起來不賴，是吧?\n\n不可能發生這種事的。\n\n滾到寂寞灣去，並把那些壺裝滿兩份的海霸王當做誘餌。我說「新鮮」的意思是你要直接在水裡抓住宰了。\n\n喔，「壺」的意思是指陷阱。如果你想成為船員的一份子，最好學一下術語。", progress = nil, completion = "還不賴，菜鳥，還不賴。", rewards = "慈母之種長袍樹蠅外套枯木護甲清澈胸甲驚懼紡織者長袍鬼狐外套奪風者護甲刃誓護軀冰蝕護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][31182] = {title = "水獺知道", objective = "到寂寞灣使用一包蛤蜊肉餵8隻冰疾水獺。", description = "你知道那些壺裡的餌出了什麼問題嗎？\n\n水獺。這就是問題所在。\n\n牠們比較喜歡新鮮蛤蜊肉，但如果太餓的話，牠們會把我們螃蟹陷阱的餌吃個精光。\n\n寂寞灣的水獺受到法律保護，而我們的行動必須合法。所以，儘管我很想直接打爆這些小老鼠然後收工，但我們要做的只是確保牠們不會餓到來搶劫螃蟹陷阱。\n\n到外頭的時候丟一些蛤蜊肉給牠們，讓牠們去忙。", progress = nil, completion = "這應該可以讓那些小鬍子暫時遠離我們的陷阱。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31183] = {title = "會見船長", objective = "到濕佬的賭注找『濕佬』船長蘇道。", description = "好了，$p我有另一個工作要給你。\n\n你看到那隻圈在欄裡的海獅嗎？牠的名子是小狗。濕佬已經養牠養了好多年了。\n\n小狗最近的狀況不好，我想牠在那個圈欄裡感到很不安。去向濕佬報告這件事。\n\n反正你也該去見見船長了。", progress = nil, completion = "新水手，是吧？我們走著瞧。\n\n我帶船很嚴格的，即使她在海底也一樣。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31184] = {title = "舊時代與背叛。", objective = "從躍霧者的殘骸中找到契約筒。", description = "聽著，我沒有理由要相信你，但我有個不能交給我船員的任務。\n\n我要你去搜尋我們一艘老船的殘骸，那艘船叫做躍霧者，然後把契約筒帶回來。契約筒就在一個銀色的管子，保存在甲板下面的置物箱裡。\n\n那是某種…嗯…罪證。假如有船員決定要去找這艘老船，我不想冒著被他們發現這玩意兒的風險。那船停靠在西邊的瑪祖海棚。\n\n不怕吐的話，我建議你乘上海岸邊的回流。海棚那裡到處都是。", progress = "老實說，我希望有條石斑魚吃掉這個老舊的契約筒。\n\n等等，這樣它還是可能會出現在這裡。該死！", completion = "這就是裝證書的筒子。好吧。我猜你很想知道如此大費周章是為了什麼，對吧？\n\n&lt;濕佬打開筒子時長長地嘆了一口氣。&gt;\n\n也該結束這一切了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31185] = {title = "帶狗散步", objective = "帶小狗到瑪祖海棚找熱噴泉、鯨魚屍體與躍霧者的殘骸。", description = "小狗不是我的「寵物」。他是船員的一份子，也是我最好的朋友。你知道，他不只一次救了我的命。\n\n但我年紀太大，沒辦法帶他去散步了，而他還是需要運動。幫我帶小狗去海邊走走，好嗎？\n\n他喜歡到東南方的淺灘那裡，在溫熱的噴泉裡游泳。\n\n他絕對會到西方邊界的海岸那裡，在死鯨魚身上…呃…「做記號」。\n\n喔還有，他也會想去看看我們那艘舊船。他很念舊的。", progress = nil, completion = "情況如何？我希望他沒給你帶來太多麻煩！", rewards = "慈母之種護腿樹蠅腿甲枯木褶裙清澈腿鎧驚懼紡織者長褲鬼狐腿甲奪風者護腿刃誓腿甲冰蝕腿甲您會收到：\n\n慈母之種護腿樹蠅腿甲枯木褶裙清澈腿鎧恆龍寶箱"}
MultiLanguageQuestData['tw'][31186] = {title = "狗食", objective = "帶小狗吃掉10隻岩殼硬爪龍蝦人的屍體。", description = "<小狗發出了一隻海獅所能發出最大的嚎泣聲，有氣無力的用腳掌指指自己巨大的嘴。\n\n他餓了。\n\n瑪祖海棚上頭覆滿了岩殼龍蝦人，那應該可以給他作為大餐。>", progress = "<這絕對是你所見過最可悲的海獅。>", completion = "&lt;小狗開心地舔著他的腳掌，看起來很滿足。&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31187] = {title = "撈螃蟹", objective = "到瑪祖海棚，把躍霧者浮標掛在8個裝滿的螃蟹壺上。", description = "我剛收到消息，今早我們丟下去的一串壺收穫不小。我們抓到蟹了！\n\n問題是，海流變得越來越強，有些壺我們找不到了。它們就這樣漂在外頭，裡面滿滿裝著長尖刺的藍色黃金！\n\n我要你回到外面去。把你找到裝滿漁獲的陷阱打撈起來到水面上，交給我們。", progress = nil, completion = "幹得好！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31188] = {title = "鯊魚週", objective = "在瑪祖海棚從長尾鯊嘴裡拔下並收集200顆長尾鯊牙齒。", description = "螃蟹是我們最主要生財來源，但我們把各種貨物送到長城那邊。油、植物，甚至礦物。海洋的礦藏可是很豐富的!\n\n目前，市場上最瘋狂的就是長尾鯊牙齒。顯然它們是很好的項鍊素材?\n\n西邊的瑪祖海棚到處都是長尾鯊。給我多帶點牙齒回來!", progress = "親眼目睹某人被長尾鯊吞掉後，我不確定你還會不會想把牠們的牙齒掛在脖子上，但隨便啦。", completion = "那些很完美，放在那邊就好。我不想自己碰到它們。讓我渾身不舒服。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31189] = {title = "收線策略", objective = "在濕佬的賭注協助釣手大師祝廉。", description = "我打從…好吧我從來沒有想到會有這一天，釣手大師祝廉竟然會需要人幫忙。\n\n顯然這片海域變得太瘋狂了，連他都料想不到。他就在這裡的南邊釣魚，看看你能否去幫他一把。", progress = nil, completion = "發生了什麼事？！我聽見一聲尖叫，然後這些東西就跟著海浪跑了出來！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31190] = {title = "水手的復仇", objective = "在濕佬的賭注，駕駛碼頭旁的躍霧者二世，並用它來擊殺鱆。", description = "我可不想在我們船員被海怪吞食時呆坐在一個該死的石頭椅子上!\n\n拜託，讓我們到碼頭那裡弄一艘小船吧。我正好為這種情況準備了一艘。我的躍霧者二世。我們會給那傢伙一頓魚叉大餐。", progress = nil, completion = "射擊得漂亮!\n\n我就知道我們能成功。只要魚叉的數量夠，我還沒看見殺不死的東西。", rewards = "慈母之種披肩樹蠅肩甲枯木肩甲清澈肩甲驚懼紡織者襯肩鬼狐肩甲奪風者肩甲刃誓護肩冰蝕護肩您會收到：\n\n慈母之種披肩樹蠅肩甲枯木肩甲清澈肩甲恆龍寶箱"}
MultiLanguageQuestData['tw'][31194] = {title = "鎮壓滑鱗", objective = "殺死滑鱗蜥蜴王。", description = "滑鱗聽命於他們的新首領，滑鱗蜥蜴王。他就在嘯風島的東南方慶祝他的勝利。\n\n如果我們能殺死這個首領，就能對他們的部族造成很大的打擊。\n\n少了領導者，滑鱗在攻擊東邊那些溫和的雲蛟前就得多考慮一下了。", progress = nil, completion = "太棒了!我就知道你能打贏那個滑鱗之王。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31195] = {title = "教训坏蛋", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31196] = {title = "斯拉斐斯刺殺任務", objective = "在斯拉斐斯附近殺死任意15名非菁英螳螂人。", description = "螳螂人的數量遠勝我們。幾乎是好幾百比一之數。\n\n而且，他們從兩個方向包夾我們。在南邊的高仁，我們還能擋住他們。但西邊，在他們稱為斯拉斐斯的島上，他們的數量卻絲毫不減。\n\n我們可沒笨到直接跑去打他們。我們沒有能力開啟更多戰線。\n\n我們要派你和我們手下一名武豪去幹點骯髒的工作。聽起來很好玩吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31197] = {title = "當他們變得越大...", objective = "在斯拉斐斯殺死任意4名菁英螳螂人。", description = "殺死較小的螳螂人是很好的拖延之計。能在他們組織起大規模入侵前，強迫他們補充兵員。\n\n至於那些大的...如果能宰掉一些，我們就能真正打亂島上的編組，爭取到大量的時間了。這些螳螂人在組織裡的重要性和簡直就跟體形成正比。\n\n所以，去給我宰幾隻大傢伙吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31198] = {title = "打擊士氣", objective = "在斯拉斐斯摧毀南方、中央、東方和西方雕像。", description = "螳螂人在斯拉斐斯造了一些雕像。我們不知道它們到底有什麼用途。或許是某種宗教象徵，或是幫助他們用音波互相聯絡。\n\n在你與敵人對決時，你們不只是在物理層面，更是在精神層面上交戰。不管這些螳螂人在做什麼，他們顯然十分重視這些雕像。\n\n所以，我希望你去炸掉那些雕像。失去這麼重要的東西必定會打擊他們的士氣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31199] = {title = "摧毀攻城武器!", objective = "在螳螂荒原的斯拉斐斯摧毀四架螳螂人攻城武器。", description = "螳螂人不只會成群結隊地進攻。\n\n他們很聰明。他們會使用鍊金術、炸彈...更糟的是攻城武器。若是拿來攻擊，肯定會造成極端嚴重的傷害。\n\n我們收到報告，宣稱他們在西邊的斯拉斐斯建造他們自己的攻城武器部隊。過去摧毀他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31200] = {title = "灰飛湮滅", objective = "將影潘毒氣炸彈放在斯拉斐斯裡的5處目標建築。", description = "我們的鍊金師搞出了一組毒氣炸彈，足夠將那些螳螂人嚇得屁滾尿流。\n\n如果我們將這些安裝在斯拉斐斯的核心結構上，他們就不得不撤離。這些螳螂人也將陷入混亂，讓行動延遲好幾天。\n\n去吧，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31201] = {title = "是夥伴，不是食物!", objective = "在飼養之淵的北部、中部、南部解救影潘受訓弟子。", description = "我們的斥候傳來令人擔憂的消息。\n\n有三名受訓弟子失蹤了，而我們的斥候發現...\n\n他們被螳螂人俘虜，並送到他們的崑蟲坑裡去了。\n\n他們的崑蟲「餵食」坑。幸運的是，崑蟲並不那麼常進食。\n\n我需要你過去那裡，將這些逃生風箏交給他們，把他們救出來!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31203] = {title = "難得的目標:斯拉席克蟲王", objective = "到螳螂荒原的斯拉斐斯殺死斯拉席克蟲王", description = "趁在這裡的時候，我們應該再做一件事。\n\n斯拉席克蟲王在空中領導著螳螂人部隊。讓牠活著會給要塞帶來麻煩。\n\n所以我們要取牠的小命。咱們殺了牠吧，$p。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31204] = {title = "難得的目標:斯拉席克巢王", objective = "擊敗斯拉席克巢王。", description = "斯拉斐斯東部靠海的區域，有個山洞可以通往一整個洞穴網絡。\n\n斯拉席克巢王在那裡面號令整個斯拉斐斯，制定對付我們的計畫。如果我們設法殺了他，就能中斷他們的活動好幾天。\n\n我們就這樣辦吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31205] = {title = "游学者周卓追踪任务", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31206] = {title = "兇殘之爐:血眼衛士!", objective = "進入兇殘之爐的競技場並擊敗赫普德普!", description = "告訴你吧，伙計，這地方遠遠比不上納葛蘭波濤起伏的平原，或是祖爾德拉克的盆地。但…嘿，哪裡有黃金我就往哪去！所以歡迎來到「暮高」，兄弟。\n\n你新來到這裡，就讓我跟你明說吧。我是戰鬥發起人，而我旁邊這個精力旺盛的食人妖是烏丁，我的保鏢。你則是大夥的娛樂。當你想要戰鬥的時候，告訴我，我就會為你安排比試。\n\n如果你準備好了，身邊又有一隊朋友跟著，我們就可以開始！你意下如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31207] = {title = "殲滅競技場", objective = "進入殲滅競技場並完成事件。之後，找『食人妖僕從』烏丁領取你的獎金。", description = "啊，我還記得在納葛蘭泥坑經營的那個競技場。我們已經走了很長的路，對吧，烏丁？\n\n我告訴你，沒什麼東西能比一場激鬥更吸引白虎寺的武僧了。因此他們付了我好價錢在這裡開一家店，幫忙吸引世界各地最強壯的戰士！\n\n你也去找兩個朋友到殲滅競技場來上幾回合吧…？錢越多，獎金越高！", progress = "你還在等什麼？武僧們等不及要看一場好戲啦。", completion = "葛爾薩克說他會讓你的努力得到報酬，孩子。隨你挑！", rewards = "劉楊的光燃長劍悠格魯姆的冰凍之錘劉楊的可愛長杖查剛的愉快砍斧沙喋的戳刺劍疤殼的閃爍法杖真樹的碎擊錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][31208] = {title = "惡毒的意圖", objective = "收集8根劇毒毒刺。", description = "我們需要武器來與女皇對抗。我的首選是具有特別淬毒設計的武器。\n\n在暗礁中爬行的蠍子會製造出致命的毒液，牠們把毒液儲存在尾巴裡。\n\n把牠們的刺帶來給我，我會讓你看看我贏得這個聖螳稱號的原因。", progress = "你有感覺到那些毒尾的螫刺嗎？多麼甜美的痛楚。", completion = "做得好，喚醒者。我希望你有小心處理這些刺。\n\n蠍子身上的天然毒物十分致命，但發作很慢。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31209] = {title = "黑暗之翼，黑暗之物", objective = "收集150個甲蟲翅膀。", description = "我需要另一種材料來創造我的第一個毒藥，喚醒者。\n\n你很容易就能在附近的甲蟲身上找到這種材料。\n\n殺了牠們並把牠們的翅膀帶來給我。", progress = "把甲蟲翅膀搗碎後，可以製成致命的美麗白色粉末。", completion = "很好，太完美了，喚醒者!\n\n你有沒有考慮過學習使毒者的手藝?", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31210] = {title = "恐懼的陰影", objective = "收集8朵懼影花。", description = "最後的成分或許也是最致命的。\n\n這些山丘上到處長滿了懼影花。\n\n吃下這些花的野生動物會變得具有毒性。\n\n只要一滴悚然暗影就能讓崑蟲的心跳停止。\n\n去帶一些這種花來給我。別試圖去嚐它的味道。", progress = "有時候，最美麗的東西也是最危險的。", completion = "很少有人知道你手上那些東西的價值。\n\n你做得很好，喚醒者。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31211] = {title = "被毒害的心", objective = "和『毒化心智』薩瑞爾談話。跟他一起飛行時，殺死200個螳螂與3個崑蟲。", description = "在我們回卡拉西斐斯之前，我想看一看帝國。\n\n卡拉西議會跟我說女皇的宮殿外頭聚集了很多人。\n\n我的毒藥已經準備好了。死亡和毀滅不正是我宣告回歸的最好方式嗎？\n\n小心別混合了兩種血清…至少別在你還握著容器的時候。\n\n等你準備好要飛上天時，告訴我一聲。", progress = nil, completion = "謝謝你帶我回家，喚醒者，但戰爭恐怕才剛開始。", rewards = "柯克席克指環毒化心智戒環薩瑞爾之戒戰鬥坦克徽印側翼守衛戒環您會收到：\n\n卡拉西"}
MultiLanguageQuestData['tw'][31212] = {title = "旗帜——选择腾武", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31213] = {title = "旗帜——选择陶矢", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31214] = {title = "旗帜——选择砮荣", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31216] = {title = "無際的黑暗天空", objective = "和『毒化心智』薩瑞爾一起飛行並殺死200個螳螂和3個崑蟲或悚然巨獸。", description = "喚醒者，蟲群行動了!螳螂人在恐懼之心群聚了起來。\n\n他們的翅膀遮蓋了天空，爪子撕裂了大地。他們絕不會停止這場黑暗進軍，直到他們的身體被人撕開，血液灑上大地為止。\n\n而我們樂於這樣做。我們會從上方攻擊他們。當我在飛行時，用我的毒阻止他們前進。\n\n在準備好進攻之前別混合那兩種血清。血清混合的反應可說是相當...劇烈。\n\n準備好了就跟我說。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31218] = {title = "旗帜——解锁腾武", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31219] = {title = "旗帜——解锁砮荣", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31220] = {title = "挑戰者競技場:鷹大師砮龍", objective = "到螳螂荒原的影潘要塞挑戰鷹大師砮龍，並在戰鬥中擊敗他。", description = "你真是在影潘中建立了聲譽，<name>。\n\n砮龍打算透過挑戰你來磨練他的技巧。\n\n好消息是，如果你贏了，我會允許他和你一起進行任務。\n\n壞消息是，我真的不覺得你會贏。", progress = nil, completion = "唉呀啊。看來我錯了。\n\n幹得好。砮龍打算跟你一起去執行任務。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31221] = {title = "挑戰者競技場:『人間赤煙』添武", objective = "到螳螂荒原的影潘要塞挑戰『人間赤煙』添武，並在戰鬥中擊敗他。", description = "所以...你受到了惡名昭彰的『人間赤煙』添武挑戰。\n\n至少他是這樣叫自己的。他是個很好的戰士，也是個很好的盜賊，只是他吹捧自己的聲音太大，很難潛到任何人的背後。\n\n總之，我覺得你應該回應他的挑戰。或許能讓他學會一點謙遜。或許不能。不管怎樣，如果你贏了，他或許會願意和你一起進行任務。\n\n同時我也能有點娛樂。", progress = nil, completion = "哇!幹得好。很高興看見你打得這麼漂亮。\n\n如果他能試著在戰鬥中趕上你，他的話就不會那麼多了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31228] = {title = "預言者跨茲庫", objective = "擊敗預言者跨茲庫。", description = "預言者跨茲庫是個力量強大的占卜師，但他也低估了你的能力。\n\n我們必須摧毀跨茲庫來保護村莊。他的死將帶給雷王一個強烈的訊息，那就是我們不會被擊敗！\n\n你會在清算之島找到他。", progress = nil, completion = "我們應該要從這些事件當中學到教訓，&lt;name&gt;。\n\n從我們的歷史當中學習是件非常重要的事。如果我們更重視歷史一點，或許就能在事情演變成這樣之前阻止它發生。\n\n此刻發生的這些事其實都是可預測的，只是我們不知道如何去判斷。", rewards = "瀑布護腿牡山獸皮腿甲夢境之靈褶裙平靜腿鎧屈心者長褲默葉腿甲犛牛牧人護腿峰頂守護者腿甲城牆看守者腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][31230] = {title = "歡迎來到晨綻", objective = "到晨綻找凱‧蕩酒、風毛大師和佩吉‧金流。", description = "阿洲出去進行他的另一場冒險了，而且這次的冒險需要大量的玉。我要去請求一些協助。\n\n在這段時間裡，你去跟當地人自我介紹一下如何。\n\n凱‧蕩酒是個值得認識的好人，風毛大師也是。喔，還要到上方的旅館去跟佩吉‧金流打聲招呼。\n\n從他們三個人身上，你可以感受到晨綻的生活方式。", progress = nil, completion = "很好，很好，很好。你會融入他們的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31231] = {title = "消滅驚懼紡織者", objective = "到葛薩尼臺地殺死8個年幼的驚懼紡織者。和『奪風者』基爾魯克談話以從空中降落。", description = "回到你找到我的葛薩尼臺地那裡去，驚懼紡織者持續佔據了影潘神射手的注意力，若非如此，他們應該能削減這些卑劣蟲群的數量。\n\n撲滅那些蜘蛛，讓城牆上的弓箭手可以稍事休息。", progress = nil, completion = "我從來就不喜歡蜘蛛。都是骯髒、盲目的蟲子。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31232] = {title = "古代帝國", objective = "取得8塊葛薩尼石板。", description = "我的兄弟提到一個坐落在東方廢墟的古代魔古帝國。\n\n曾經，這個部族通曉無數巫術及征服的秘密。\n\n我很好奇，喚醒者，這個統治我之後的時代的部族，我希望能學習跟他們有關的事。\n\n關於過去的知識將會決定我們的未來。\n\n去那些廢墟裡搜尋他們的古代石板。我要研究他們的秘密，並引為我們所用。", progress = "你帶來了什麼知識?", completion = "很好，喚醒者。破譯這些石板要花我一點時間，但所有知識都值得花時間。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31233] = {title = "抽取樹液", objective = "收集6份琥珀樹汁。", description = "我在東邊發現了一叢年輕的琥珀樹，喚醒者。\n\n我在那些樹上放了抽取器具，但我太忙，沒時間去取回樹液。\n\n我需要有人去找那些抽取器。啟動它們，然後帶一些琥珀樣本回來給我。", progress = "這些樹還很年輕。它們都還不是奇帕利。\n\n它們的樹液像水一樣，真正的奇帕利樹，樹液應該是像葡萄酒一樣才對。\n\n它們必須繼續成長。", completion = "啊沒錯，這的確是我需要的東西。\n\n我會測試這些樣品。我們必須持續監控這些年輕奇帕利的健康。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31234] = {title = "把眼睛挖出來", objective = "收集1個原始沼澤獸之眼。", description = "啊!喚醒者!你一定得幫我!(你要幫我，否則我就拿你當自助餐!)\n\n我需要更多材料來進行實驗，沒錯沒錯!(鮮血跟腸子，心臟和腦漿，舌頭，還有眼睛，眼睛，眼睛!)\n\n到西邊去，我看過那裡有一些迷霧生物。他們擁有又大、又圓、又美的眼球!大大的看著，圓滾滾的一眨也不眨!\n\n現在就去，小喚醒者。帶著這把匕首，給我帶一顆晶亮的眼珠來!", progress = "喔喔喔，你帶了什麼漂亮的、美味的器官來給我啊?", completion = "沒錯，沒錯!太棒了!喔，真是美味!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31235] = {title = "一掃而空", objective = "到葛薩尼臺地使用影潘龍槍摧毀20個驚懼紡織者的卵。", description = "最近，我從在城牆附近進行的偵察行動中，找回了這個武器。它似乎非常有助於解決你們影潘在葛薩尼臺地的害蟲問題。\n\n他們的精神越集中在抵禦蜘蛛爬上城牆，就花越少時間在殺死群生幼螳。", progress = nil, completion = "一個粗糙的武器，但還是有它的用處。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31237] = {title = "為臺地除蟲", objective = "到葛薩恩臺地周圍揪出6個女皇之眼。殺戮會啟動你的費洛蒙追蹤，幫助你發現他們。", description = "如果這個女皇真的已被恐懼與妄想佔據，她絕對會派斥候到土地的每個角落以鞏固她的統治。\n\n這些斥候苦工似乎到處都是，但用肉眼很難看到。最好是用他們留下的費洛蒙痕跡來追蹤他們。\n\n我已經...賦予你...一種反應毒素，讓你在經歷勝利快感後的短時間內，有能力追蹤這些痕跡。\n\n現在就去葛薩恩臺地把他們的間諜揪出來。", progress = nil, completion = "資訊就是力量，&lt;name&gt;。我們不能任由女皇監控我們的行動。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31238] = {title = "大腦的食物", objective = "帶4個牡山獸舌頭到卡拉西斐斯給『操縱者』卡茲提克。", description = "科沃克正在加速成長，但他的大腦可能跟不上。他需要特殊的飲食，以確保他不會長到無法控制自己的身體。\n\n牡山獸的舌頭含有豐富的營養，可以促進崑蟲的腦部生長，但他們通常會吃掉一整隻野獸，那樣很快就飽了。如果我們每隔兩天左右餵科沃克吃牡山獸的舌頭一次，應該可以讓他的成長平衡一下。\n\n東邊葛薩尼臺地附近的山丘有許多牡山獸在那裡吃草。", progress = "你有找到適合科沃克的餐點嗎?", completion = "你離開的時候科沃克一直哭個不停。樣子真的很可憐。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31239] = {title = "名名是什麼?", objective = "殺死7個河行錦魚人。", description = "所以，你想當個猴人，是不是啊，怪怪人?\n\n猴人保衛他們的土地不被敵人拿走，比如錦魚人。\n\n卡卡跟很多錦魚人作戰過，而且都贏了。\n\n猴人只給厲害的殺手名名。去殺錦魚人，這樣或許他們會叫你<name><name>。\n\n錦魚人在河裡游。把他們打進便便裡!", progress = nil, completion = "哈哈!怪怪人殺錦魚人!", rewards = "您能選擇下列奬勵中的一個：\n\n小魚\n\n您還會收到：\n\n小魚恆龍寶箱"}
MultiLanguageQuestData['tw'][31241] = {title = "邪惡的怪怪人", objective = "從善戰的傘兵那裡收集6個聯盟服務勳章。", description = "他們說，<name>是好怪怪人…\n\n他們說，<name>幫助猴人…\n\n他們說，不殺<name>。\n\n那很好。看外面。邪惡怪怪人像雨一樣天上掉下來，剛好殺掉！\n\n一起去開心吧。但記住，所有亮晶晶都要給卡卡酋長！這是猴人的第二條規則。\n\n<吉克吉克抓抓頭。>\n\n嗯，所有的猴人規則都是第二條…", progress = "你拿的是什麼，怪怪人？", completion = "怪怪人殺東西，讓猴人擁有一堆亮晶晶！\n\n&lt;name&gt;創造了很好的第二印象。對猴人來說，第二是最重要的！", rewards = "怪怪人外套怪怪人披氅怪怪人斗篷怪怪人披風怪怪人裹衣您會收到：\n\n怪怪人外套怪怪人披氅怪怪人斗篷怪怪人披風恆龍寶箱"}
MultiLanguageQuestData['tw'][31243] = {title = "霧臨村受襲", objective = "到霧臨村找孫·嫩心。", description = "西南方的霧臨村出現魔古的蹤跡。我立刻派了茹克跟孫過去，但我還需要另一個能幹的幫手儘快過去。\n\n別耽擱了，村莊需要你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31244] = {title = "郭莱营地", objective = "和郭莱遗迹的莱文·晨刃谈一谈。莱文怒气冲冲地从这儿经过！还说着遗迹那儿的魔古什么的。\n\n我觉得最好出发去找他。莱文生起气来可不是闹着玩的。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "莱文怒气冲冲地从这儿经过！还说着遗迹那儿的魔古什么的。\n\n我觉得最好出发去找他。莱文生起气来可不是闹着玩的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31245] = {title = "雾临村", objective = "和雾临村的车·荒野行者谈一谈。车去村子时顺道来找了我，问我有没有见过你。我告诉他没见过。\n\n如果你愿意，可以去见他。但现在可没人强迫你去见他！我的善解人意是不是非常令人惊讶呢？您會收到：\n\n", description = "车去村子时顺道来找了我，问我有没有见过你。我告诉他没见过。\n\n如果你愿意，可以去见他。但现在可没人强迫你去见他！我的善解人意是不是非常令人惊讶呢？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31247] = {title = "落陽要塞", objective = "到落陽要塞找安吉·秋光。", description = "安吉跟昆要到要塞去。真是可愛的一對，你不覺得嗎?如此截然不同，卻又深愛對方...啊，光用想的我就覺得神魂顛倒。\n\n他們指名要你。或許他們想給你安排什麼訓練? 我真心希望他們腦袋裡沒想著一些頑皮的事情...您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31251] = {title = "到處都是大餐!", objective = "收集160份崑萊肉塊。", description = "是啊，是啊。\n\n大家都知道我們哥布林很會修補東西。還會做炸藥。還有...嗯，你知道的，一些不那麼有名的東西。\n\n但有件事沒人知道，那就是我真的是個很棒的廚師!那是我的嗜好。\n\n幫我們從附近的生物身上，取一些肉香四溢的材料來，我會做出任何地方都沒得比的飯菜!\n\n而且我保證，我只會用掉百分之三或四的火箭燃料。", progress = "香香的肉呢，<name>？我們需要肉！", completion = "你知道他們是怎麼形容烹飪這回事。裝味洗。裝飾，味道…還有洗…洗碗？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31252] = {title = "回到西風之眠", objective = "到崑萊峰的西風之眠找雇農阿波。", description = "嗯，據我推測，我們有許多重建工作要做。\n\n我不是一個會加入偉大事業的人，但老實說，我的農場工人在這裡沒什麼事可做。還有，自從你幫助過他們之後，他們就很想加入你的「聯盟」。所以，我有什麼資格能阻止他們呢？\n\n把他們帶走吧，回去雇農阿波那裡。我會想念他們，但他們跟你在一起會更好。", progress = nil, completion = "你帶回了一些人，做得很好。我們馬上讓他們幫你種一些食物！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31253] = {title = "回到東風之眠", objective = "到崑萊峰的東風之眠找雇農阿郭。", description = "嗯，據我推測，我們有許多重建工作要做。\n\n我不是一個會加入偉大事業的人，但老實說，我的農場工人在這裡沒什麼事可做。還有，自從你幫助過他們之後，他們就很想加入你的「部落」。所以，我有什麼資格能阻止他們呢？\n\n把他們帶走吧，回去雇農阿郭那裡。我會想念他們，但他們跟你在一起會更好。", progress = nil, completion = "你帶回了一些人，做得很好。我們馬上讓他們幫你種一些食物！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31254] = {title = "通往崑萊的道路", objective = "穿越朦朧天梯到濱南村。", description = "啊！你好啊，博學行者阿洲的朋友。我有個訊息要給你。\n\n<這奇怪的小生物交給你一個破爛的卷軸盒子。>\n\n博學行者在崑萊等你。過去的路非常危險，是的，非常危險。\n\n尋找路上的嚮導來幫你找到方向。", progress = "更多陌生人？今天是在測試我的極限就對了。", completion = "喔，你是阿洲的朋友？歡迎！歡迎！\n\n我很願意為你準備酒席，但如你所見，我們正處在可怕的情境裡。\n\n這麼說吧，你願意伸出援手嗎？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31255] = {title = "通往崑萊的道路", objective = "穿越朦朧天梯到濱南村。", description = "啊！你好啊，博學行者阿洲的朋友。我有個訊息要給你。\n\n<這奇怪的小生物交給你一個破爛的卷軸盒子。>\n\n博學行者在崑萊等你。過去的路非常危險，是的，非常危險。\n\n尋找路上的嚮導來幫你找到方向。", progress = "更多陌生人？今天是在測試我的極限就對了。", completion = "喔，你是阿洲的朋友？歡迎！歡迎！\n\n我很願意為你準備酒席，但如你所見，我們正處在可怕的情境裡。\n\n這麼說吧，你願意伸出援手嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31256] = {title = "圈趕回來", objective = "圈趕3隻野生原犛牛，並把牠們帶回東風之眠。", description = "你好啊，<class>。\n\n我們有些進展，但我們需要機動性才能在崑萊這裡站穩腳跟。\n\n我在這附近沒看到座狼、科多獸，或其他類似的東西。我看到的只有犛牛。我們的熊貓人盟友說過牠們是很好的坐騎，那就來騎牠們吧。\n\n去圈趕幾隻犛牛回來，讓我們的人有東西可騎!", progress = nil, completion = "幹得好!嗯，我得說，牠們可是很頑固的。但牠們應該會做得很好。", rewards = "卡法緞質披肩卡法皮肩甲夢境之靈護肩卡法光潔肩甲卡法絲質襯肩卡法皮甲肩甲犛牛牧人護肩卡法重型護肩卡法裝甲護肩您會收到：\n\n卡法皮肩甲卡法皮甲肩甲恆龍寶箱"}
MultiLanguageQuestData['tw'][31260] = {title = "大發利市:卡辛", objective = "收集遠古老虎的血。", description = "我要投身到一個偉大騙局裡啦！\n\n當我從空中飛過，我看見一隻古老的母老虎在四處竄走。\n\n你知道她的血在黑市裡值多少錢嗎？更別提，假如我能說服一些術士，這血可以增加他們召喚咒語的威力什麼的。\n\n如果你帶些她的血回來給我，我就讓你分一杯羹。她就出沒在朵迦河遙遠的那頭。", progress = "我想過自己去打那隻老虎，但老實說，我還想活...", completion = "真了不起！你聞到錢的味道了嗎？這兒是你的那一份。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31261] = {title = "傑克船長之死", objective = "帶傑克船長的頭顱到葛魯山丘給卡卡酋長。\n\n已提供物品：\n", description = "在你研究那得來不易的戰利品時，從傑克船長頭顱滴下來的血塊神秘地滲進了地板。\n\n詭異，但現在沒時間調查原因了。有太多工作要做。\n\n有這個當證據，你那群新朋友的酋長對你的殺人技巧肯定會大感佩服。", progress = nil, completion = "殺的漂亮，怪怪人！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31262] = {title = "獵鶴高手:針喙", objective = "捕獲針喙。", description = "現在，既然你大概了解鶴是如何戰鬥的了，我有個特別的任務要交給你。\n\n針喙！\n\n至少我是這麼稱呼牠啦。那是我見過最大的鶴。而且牠的喙就像劍一樣鋒利。\n\n你會在西北方找到朵迦河形成的一個大瀑布。針喙喜歡到瀑布閒逛。\n\n你把牠的喙當作戰利品帶來給我，我就在奈辛瓦里面前多講你幾句好話。", progress = "我看過那隻鳥用喙刺穿老虎的臉。鳥成了老虎的天敵，這是什麼樣的地方啊？", completion = "這才叫做戰利品。看起來真可怕。等等…上頭是你的血嗎？", rewards = "朵迦腰環廓亞腰環薩鍾腰帶川刃腰環安格寇腰環納松腰環深野蠻荒腰帶號角之息腰環納耶里腰環您會收到：\n\n"}
MultiLanguageQuestData['tw'][31265] = {title = "瑪祖的吐息", objective = "喝下瑪祖的吐息藥水。", description = "來幫忙的是嗎？先做該做的事吧。\n\n<艾利在口袋裡翻了一會兒，然後拿出一個裝著閃亮藍色液體的小瓶子。>\n\n這就是了！「瑪祖的吐息」。船長的私人配方。\n\n什麼？你以為我會沒有讓你呼吸的方法，就送你出海？我需要的是漁工，不是屍體！\n\n帶著它下艙口去，菜鳥。這會讓你在礁石上有戰勝的機會。", progress = "不，我沒有「解酒液」！喝下去就對了！", completion = "之後你會感謝我的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31266] = {title = "魔古奇襲", objective = "找出衫織間諜大師並殺了他。", description = "我們接獲報告，有一組魔古正滲透進螳螂荒原的海岸。我不知道他們想做什麼。坦白說，我也不在乎。\n\n你已證明自己的能力，所以我們決定把這個任務交給你。\n\n任務流程是這樣的。你離開，找到他們，而後宰了他們。\n\n我們的斥候報告說第一批部隊在北邊海岸登陸了，就在這裡跟死語者高地之間。去把他們消滅掉。", progress = nil, completion = "那只是誘餌！他們跑去攻擊怒兆寺了！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31267] = {title = "霧刃的末日", objective = "殺死6個霧刃撕裂者。", description = "柯爾文跟我說了他的發現。在星辰湖的湖底，有著一塊巨大無比的琥珀。\n\n不幸的是，一支具有敵意的薩烏洛克部族住在湖畔，將琥珀據為己有。\n\n他們絕不會那麼輕易地讓我們進入他們的領地。\n\n到南邊的湖泊去，殺死霧刃薩烏洛克，讓我們能更輕鬆地取得附近的琥珀。", progress = nil, completion = "做得好。有了這些琥珀，我們就能做出自己的武器。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31268] = {title = "小小的腦部工作", objective = "從西克席克琥珀毒蠍身上收集3個琥珀硬殼腦。", description = "在遙遠的南方，蟲群繁殖出毀滅性的武器。巨大的、幾乎無法摧毀的琥珀蠍。\n\n和其他生物一樣，牠們可以受到操縱。但跟其他生物不同的是，牠們還沒有屈服於我的心靈控制。\n\n顯然，我們需要深入研究，才能操縱牠們為我們服務。\n\n我必須研究牠們的腦部，所以你必須幫我取回一些標本。\n\n帶著這個聲波發射器。我發現用它來對付野獸非常有效。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31269] = {title = "鱗王", objective = "殺死霧刃鱗王。", description = "鱗王統治著星辰湖的薩烏洛克。他是一個凶惡無情的頭目，兇狠地保衛著他們領地。\n\n若能剷除這名頭目，就能得到湖底那巨大的琥珀礦脈。\n\n去吧。他們的頭目就在他位於湖泊南岸的地下棲息地裡發號施令。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31270] = {title = "對抗恐懼之戰", objective = "殺死15個恐鱗鉗蠍", description = "當我們發現奇帕利札爾受到煞的影響時，我曾希望可以把污染清除掉。\n\n不幸的是，卡拉西議會查證到恐懼之煞的污染已然深植，而且持續擴散。\n\n我在南方發現，一些當地的野生動物被不知名的恐懼給吞噬了。\n\n煞可以讓它的受害者深陷無以名狀的恐怖中。\n\n我們必須在事情變得更糟之前阻止腐敗擴散。找出被煞污染的恐鱗鉗蠍。消滅牠們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31271] = {title = "不好的基因", objective = "殺死3個伊克席克基因占卜師與6個伊克席克蟲卵護衛。", description = "喚醒者，在遙遠的南方，女皇的操生者著手進行他們黑暗的實驗。(是很黑暗沒錯，但不像我的那麼黑!)\n\n他們解剖附近的野生動物，使其突變，進而繁殖出他們自己設計的生物。(他們的設計，將會成為我的設計!)\n\n我們絕不讓他們成功!(不，不!只有我才能擁有這種力量!)\n\n他們創造的突變生物已經被派出來打仗了。去吧!不惜一切代價摧毀他們!", progress = nil, completion = "太好了，太好了!他們死了!\n\n謝謝你，喚醒者。做得好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31272] = {title = "感染", objective = "殺死6隻遭到感染的野生動物。被感染的野生動物可能包含骨灰蛾、藍革牡山獸和豪豬。", description = "女皇的操生者正在把玩危險的玩具。\n\n在南方，他們把帶著荷爾蒙的寄生蟲注入野生動物體內，企圖製造可供戰爭使用的突變種。\n\n出於意外，他們讓寄生蟲逃進當地的生態系統裡了。\n\n如果任其發展，感染會在動物之間不斷傳播，直到疫情大幅爆發。\n\n我會幫你注入一種溫和的毒素。有了它，你就能辨識出遭到感染的生物。\n\n把那些生物全殺光。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
