MultiLanguageQuestData['tw'][31308] = {title = "基礎訓練", objective = "在一場寵物對戰中獲勝。", description = "現在你已經是個寵物訓練師，是時候測試一下你的技能了！\n\n到森林去挑選一隻戰寵，並與其交戰。獲勝之後就回來找我，我會繼續訓練你。祝你好運！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31309] = {title = "康復", objective = "去拜訪獸欄管理員艾瑪，以治療你的寵物並恢復其生命力上限。", description = "現在你在戰鬥中獲勝了，我們必須治癒你的寵物，好讓牠們還有能力再上戰場！去找我們當地的獸欄管理員艾瑪治療你的寵物，讓牠們恢復健康。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
