MultiLanguageQuestData['tw'][31311] = {title = "燒烤之道", objective = "帶5塊生虎排給燒烤大師。", description = "熊貓人燒烤之道製作的食物能讓你變得強壯。帶一些生虎排給燒烤大師，他會教你該怎麼處理這個食材。在翠玉林與喀撒朗蠻荒有許多老虎，不過其他地方你也可以找得到老虎。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n燒烤之道\n\n您還會收到：\n\n生虎排鐵爪徽章"}
MultiLanguageQuestData['tw'][31312] = {title = "古老的地圖", objective = "到四風峽的香蒲湖或半丘市集，把地圖拿給小魚‧跌蘆看。\n\n已提供物品：\n", description = "這塊古老、褪色的皮革裂成了好幾塊，但上頭的字跡仍可辨識。\n\n\n深峽里，四風吹，\n金扇掩面淑女嫣;\n亭亭玉立祖階下，\n絕密輕語翩，回聲幽暗間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31313] = {title = "只是個民間故事", objective = "跟穀物整理員小佩、鑿石者麥克、茗大娘以及白鬚佬聊聊。", description = "什麼？！這沒道理啊！<小魚的臉垮了下來。>\n\n這段什麼少女啊祖先啊還有一堆階梯的胡言亂語是什麼東西？\n\n我想不出這是什麼意思，你能嗎？\n\n嗯，這裡有很多居民比我們兩個老得多，<name>。\n\n你能去跟半丘的居民聊聊嗎？我想他們可能知道些什麼！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31314] = {title = "寂老頭的寶藏", objective = "找出洞穴入口，並發現寂老頭藏起來的寶藏。", description = "我的天老爺啊！這變成真正的尋寶行動了！\n\n北邊香蒲湖跟山巒的交接處那裡，一定有某種入口或洞口。\n\n我會在入口處跟你碰頭！咱們去取寶藏吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n寂老頭的寶藏"}
MultiLanguageQuestData['tw'][31315] = {title = "中央平原的遺寶", objective = "把寂老頭的年鑑帶去四風峽的半丘給種子看守者辛興。", description = "在藏寶箱的最底部，你找到一堆卷軸，還有一個裝滿種子的軟皮袋。\n\n打開卷軸，你看到裡頭寫著詳細的農作筆記，畫著植物、數量與計算法，附近泉水的地點，還有其它數不清的小片段。\n\n耕者工會裡或許有人會想看看這個。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31316] = {title = "馴獸師茱莉亞", objective = "在寵物對戰中擊敗茱莉亞‧史蒂文斯。", description = "我看得出來你已經在磨練你寵物對戰的技能，<name>。我想現在是讓你接受真正挑戰的時候了。\n\n你可以在暴風城南方的馬科倫農場找到茱莉亞‧史蒂文斯。她是個活潑又充滿野性的馴獸師，我想該是你和她戰鬥的時候了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
