MultiLanguageQuestData['tw'][31319] = {title = "緊急回應", objective = "在泰勒上將、密西卡和蘇利附近使用阿洲的煙火。", description = "你的同伴們就在我們土地上待下來了，還帶來危險的衝突。\n\n我們想像不出他們會在這裡帶來多大的毀滅。此刻的傷害，就已經…無法言喻。\n\n無論如何，因蔑視而拋棄你的朋友不符合我們的處世之道。還活著的人肯定受傷、絕望，急切需要照護。\n\n這些煙火本來是用來慶祝雕像完工的。在你夥伴周圍使用它來通知米什，她會將他們搬運到安全的地方。", progress = nil, completion = "我會照料你的同伴們，&lt;name&gt;。\n\n希望他們的傷很快就能回復。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31320] = {title = "請魚喝杯酒吧？", objective = "帶一杯四風燒酒給『酒鬼』酒骨。潘達利亞大部分的酒保那裡都可以買到四風燒酒。", description = "嘿咿，老兄，過的如何啊？你想請錦魚人喝杯酒嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31321] = {title = "請魚喝一輪吧?", objective = "帶5杯熊貓人梅酒給『酒鬼』酒骨。潘達利亞大部分的酒保那裡都可以買到梅酒。", description = "嘿咿咿，是我的朋友<race>!\n\n我猜你已經看過我在附近晃來晃去了，不過我要解釋清楚，我沒有喝醉。\n\n我是說，看看我現在的樣子!像清水裡的魚一樣清醒!\n\n當然，偶而我喜歡將我的悲傷淹沒在好喝的啤酒裡，但錦魚人是喝不醉的!還不如去試試淹死一條魚!\n\n不，啤酒讓我想睡覺，而當我睡著時，我就會看見未來。\n\n\n\n啤酒越烈，夢的力量就越強!如果你帶杯酒給我，我就算欠你一次。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31322] = {title = "請魚喝一桶酒吧？", objective = "帶10杯玉巫婆酒給『酒鬼』酒骨。你可以使用烹飪專業製造出玉巫婆酒。", description = "我的夢境最近都很模糊，<race>。\n\n我需要某種強力的東西來把我踢回正軌！\n\n我聽說現在居民有製造出一種很好喝的酒。\n\n它叫做玉巫婆酒。\n\n我很想喝一點看看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31323] = {title = "給魚買一座酒坊吧？", objective = "帶20份瘋狂釀酒人的早餐給『酒鬼』酒骨。你可以使用烹飪專業製造出瘋狂釀酒人的早餐。", description = "好了，<name>，為了繼續我的預言，我必須擁有自己的酒坊。\n\n…\n\n開玩笑的啦！你真該看看自己臉上的表情！滑稽透了…嗝！\n\n總之，我聽說有種新的酒，跟其他酒都不一樣，我很想喝喝看。\n\n你有聽過瘋狂釀酒人的早餐嗎？如果你能帶些那種東西給我，那麼你將成為我一輩子的朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31324] = {title = "家族秘密", objective = "收集5份風暴烈酒秘訣。", description = "我們的秘密配方!當時我正在把配方收集起來，然後...猴人?\n\n<嬸嬸看起來很慌亂。>\n\n這樣老高要怎麼釀啤酒?他需要那些配方，不然麻煩就大了!", progress = "喔，哈囉!", completion = "呵呵，這是什麼?\n\n&lt;高叔叔看到家族配方時輕輕晃著他的肥啤酒肚。&gt;\n\n喔，我就知道我加了太多玉米了!", rewards = "風暴烈酒飲酒餐巾用過的酒吧抹布姨媽的烹飪圍裙品酒室桌布黑褐披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][31325] = {title = "一條非常美麗的項鍊", objective = "把項鍊帶去四風峽的好漢的小屋或半丘市集，交給蒂娜‧泥爪。\n\n已提供物品：\n", description = "這條美麗的項鍊有一部份被猴人的手弄髒了。\n\n山谷中只有一個人會擁有如此美麗的珠寶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31326] = {title = "蒂娜的高雅的冠冕", objective = "把高雅的冠冕帶去四風峽的好漢的小屋或半丘市集，交給蒂娜‧泥爪。\n\n已提供物品：\n", description = "這是個燦爛的鑽石冠冕。山谷中誰有資格擁有如此珍貴的珠寶？\n\n不管是誰，他們應該很願意付出優厚的賞金。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31327] = {title = "釀酒麻煩", objective = "殺死『破罈者』嚴祝。", description = "我很肯定釀酒的人們有麻煩了，因為酒坊裡到處都有猴人出沒，還有...天曉得是什麼鬼的東西。\n\n我的朋友，你介不介意去幫我看看裡頭發生什麼事?", progress = nil, completion = "一個由啤酒形成的巨大生物?!這種事誰能想像得到?\n\n感謝你將老高從他誤入歧途的釀酒試驗中拯救出來。", rewards = "釀酒大師手套疊桶工長手套品酒手套拔木塞手套桶藏手套兔妖終結者手套切菜手甲派對破壞者護手壯健體格手甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][31328] = {title = "精緻的耳環", objective = "把精緻的耳環帶去四風峽的好漢的小屋或半丘市集，交給蒂娜‧泥爪。\n\n已提供物品：\n", description = "你將耳環從那個多毛生物的耳朵上取下。他似乎覺得帶著這個亮晶晶的圈圈很有趣。太過有趣了。\n\n或許這個漂亮小玩意的主人會想拿回這東西。你不需要告訴她你是在哪裡找到的…或是誰曾經戴過它。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31329] = {title = "美麗的胸針", objective = "把美麗的胸針帶去四風峽的好漢的小屋或半丘市集，交給蒂娜‧泥爪。\n\n已提供物品：\n", description = "這是個年代久遠的古董胸針，做工精細，邊緣有金絲跟銀絲鑲飾。看起來非常昂貴。\n\n只有一個人的珠寶老是被這些毛茸茸小流氓給偷走，而且她應該會想拿回這個傳家寶才對。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31331] = {title = "弄清楚如何制作任务", objective = "制作一个索引任务。好耶！你要学会如何制作一个索引任务！现在想想下面该做什么。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "好耶！你要学会如何制作一个索引任务！现在想想下面该做什么。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31332] = {title = "第1課：蜜桃切片", objective = "為糯米的烹飪課程取得5顆熊貓人蜜桃。", description = "真高興能開始訓練。先從蜜桃切片開始，對嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n蜜桃切片"}
