MultiLanguageQuestData['tw'][31334] = {title = "第三課:烤魚乾", objective = "為糯米的課程取得5隻金鯉魚。", description = "烹飪比我想像中來得難。把東西燒掉比較簡單。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n烤魚乾"}
MultiLanguageQuestData['tw'][31335] = {title = "第四課:乾燥金針菇", objective = "為糯米的課程取得5份金針菇。", description = "我不是很愛香菇…但我會努力學著喜歡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n乾燥金針菇"}
MultiLanguageQuestData['tw'][31336] = {title = "第五課:搗過的年糕", objective = "為糯米的課程取得5份米。", description = "我喜歡年糕。我會努力做出好吃的年糕！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n搗過的年糕"}
MultiLanguageQuestData['tw'][31337] = {title = "表示謝意", objective = "收下糯米的謝禮。謝謝你來確認我的進展！我已經有能力幫助鐵爪家的人了，他們說我可以把這個給你。", description = "謝謝你來確認我的進展！我已經有能力幫助鐵爪家的人了，他們說我可以把這個給你。", progress = nil, completion = "你是我最喜歡的老師了。", rewards = "您會收到：\n\n糯米送的好東西鐵爪徽章"}
MultiLanguageQuestData['tw'][31338] = {title = "失蹤的羊羊", objective = "找回羊羊，並把牠帶回去給奇奇。", description = "奇奇的得獎綿羊，羊羊不見了！\n\n那隻壞綿羊每次都晃到農場外面去。\n\n笨羊！我到處都找不到牠。\n\n你可以幫我嗎，<race>？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31339] = {title = "失蹤的羊羊…又一次", objective = "找回羊羊，並把牠帶回去給奇奇。", description = "那隻笨羊！牠又跑出去亂晃了\n\n你可以再幫我找牠一次嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31340] = {title = "喔羊羊…", objective = "找回羊羊。", description = "唉…你猜對了…羊羊牠…又不見了。\n\n笨羊！給我帶來這麼多麻煩！\n\n我真不想再拜託你，我保證這是最後一次了。\n\n你可以幫我找牠嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31341] = {title = "披著羊皮的狼", objective = "到擎天嶺或崑真村的任何一個地方使用老綿羊皮，然後殺死昆可。", description = "啊啊啊咿咿咿咿嗚嗚嘎吼吼吼！這是激怒奇奇的最後一根稻草！\n\n山上的那些蠢蛋猴人殺了我的寶貝羊羊！\n\n我知道是誰幹的好事，現在復仇的時候到了。\n\n如果你願意幫我，就穿上這個老綿羊皮。\n\n到北邊山區的任何地方，用這東西偽裝自己，等那個小廢渣昆可從藏身處出來，然後打斷他的骨頭！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31342] = {title = "暴力是通往尊重的道路", objective = "殺死暴力之煞。", description = "你已在戰鬥中證明了自己的能力。\n\n不過，如果你想進一步幫助我們，我還有一件事得請你去做。\n\n暴力之煞在封印的房間中等著你。如果你想贏得我的尊敬，就去摧毀它。", progress = nil, completion = "你擊敗暴力之煞並拯救了僧院。你贏得我的尊敬。\n\n或許我們對於你這個種族所抱持的想法是錯誤的，&lt;name&gt;。", rewards = "兇神惡煞之索崑萊登山腰帶補煞者護腰擊雲者之索影潘學徒腰帶元素射手鎖鍊僧院守護者束腰破碎封印束腰擾人惡夢之索您會收到：\n\n"}
