MultiLanguageQuestData['tw'][31372] = {title = "耕者們", objective = "到四風峽的日歌農莊找農夫尹。", description = "耕者們在四風峽的半丘經營他們的事業。\n\n如果你有興趣開始農作，我聽說城裡有個新農夫，他叫做農夫尹，\n\n我打賭他會需要幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31373] = {title = "雲蛟衛", objective = "到翠玉林的落英園找講師天刺。", description = "雲蛟衛總是在尋找有才能的騎手。\n\n如果你想跟隨我們的道路，那麼你該去翠玉林的落英園跟講師天刺談談。\n\n祝你好運，<race>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31374] = {title = "耕者們", objective = "到四風峽的日歌農莊找農夫尹。", description = "耕者們在四風峽的半丘經營他們的事業。\n\n如果你有興趣開始農作，我聽說城裡有個新農夫，他叫做農夫尹，\n\n我打賭他會需要幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
