MultiLanguageQuestData['tw'][31376] = {title = "玉蛟寺的襲擊", objective = "到翠玉林的玉廟庭找大賢者泰豐。", description = "黑暗潛伏在玉蛟寺中，玉龍的司祭懇求我們幫忙。\n\n他們目前還能控制住煞，但非常勉強。\n\n你或許能扭轉局勢，<class>。", progress = nil, completion = "你來的正是時候，&lt;class&gt;。", rewards = nil}
MultiLanguageQuestData['tw'][31377] = {title = "玉蛟寺的襲擊", objective = "到翠玉林的玉廟庭找大賢者泰豐。", description = "黑暗潛伏在玉蛟寺中，玉龍的司祭懇求我們幫忙。\n\n他們目前還能控制住煞，但非常勉強。\n\n你或許能扭轉局勢，<class>。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31378] = {title = "紅鶴寺的挑戰", objective = "到喀撒朗蠻荒的赤吉搖籃找瑟隆諾斯。", description = "紅鶴寺仍因煞的出現而餘悸猶存，到最近才整頓好人手去重建和重新訓練他們的戰士。\n\n如果你想去寺裡幫忙，就到赤吉搖籃去跟瑟隆諾斯談談。", progress = nil, completion = "歡迎你，&lt;class&gt;。", rewards = nil}
MultiLanguageQuestData['tw'][31379] = {title = "紅鶴寺的挑戰", objective = "到喀撒朗蠻荒的赤吉搖籃找瑟隆諾斯。", description = "紅鶴寺仍因煞的出現而餘悸猶存，到最近才整頓好開始重建和重新開始訓練他們的戰士。\n\n如果你想去寺裡幫忙，就到赤吉搖籃去跟瑟隆諾斯談談。", progress = nil, completion = "歡迎你，&lt;class&gt;。", rewards = nil}
MultiLanguageQuestData['tw'][31380] = {title = "白虎寺的競賽", objective = "到崑萊峰的白虎寺找雪怒。", description = "雪怒，北方最偉大的天尊，祂在尋找這片土地上最偉大的英雄。\n\n今天，祂在祂位於崑萊峰上的寺廟中，舉辦戰鬥競賽。\n\n如果你想測試自己的能力，對抗全潘達利亞技能最精熟的戰士們，那就去找祂，並進入挑戰者競技場!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31381] = {title = "白虎寺的競賽", objective = "到崑萊峰的白虎寺找雪怒。", description = "雪怒，北方最偉大的天尊，祂在尋找這片土地上最偉大的英雄。\n\n今天，祂在祂位於崑萊峰上的寺廟中，舉辦戰鬥競賽。\n\n如果你想測試自己的能力，對抗全潘達利亞技能最精熟的戰士們，那就去找祂，並進入挑戰者競技場!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31382] = {title = "怒兆寺的防衛", objective = "到螳螂荒原的怒兆寺找奧苟兄長。", description = "位於遙遠西方的怒兆寺正受到螳螂人攻擊。\n\n偉大的天尊目前還能抵擋他們，但他無法永遠憑一人之力支撐下去。\n\n去幫助那些防衛者，<class>。寺廟絕不能失陷！", progress = nil, completion = "來得好，&lt;class&gt;！我們需要你的協助。", rewards = nil}
MultiLanguageQuestData['tw'][31383] = {title = "怒兆寺的防衛", objective = "到螳螂荒原的怒兆寺找奧苟兄長。", description = "位於遙遠西方的怒兆寺正受到螳螂人攻擊。\n\n偉大的天尊目前還能抵擋他們，但他無法永遠憑一人之力支撐下去。\n\n去幫助那些防衛者，<class>。寺廟絕不能失陷！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31384] = {title = "金蓮會", objective = "到恆春谷的落陽要塞找安吉‧秋光。", description = "金蓮會數百年來一直守護著山谷，保護它不被傷害。\n\n最近的事件對我們神聖的山谷造成了嚴重的慘況，但是金蓮會的盟友依然挺身對抗，試圖維護和平。\n\n如果你想幫忙，你最好到落陽要塞加入他們。", progress = nil, completion = "形勢嚴峻啊，&lt;class&gt;。無論你能幫上什麼忙，我們都歡迎。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31385] = {title = "金蓮會", objective = "到恆春谷的落陽要塞找安吉‧秋光。", description = "金蓮會數百年來一直守護著山谷，保護它不被傷害。\n\n最近的事件對我們神聖的山谷造成了嚴重的慘況，但是金蓮會的盟友依然挺身對抗，試圖維護和平。\n\n如果你想幫忙，你最好到落陽要塞加入他們。", progress = nil, completion = "形勢嚴峻啊，&lt;class&gt;。無論你能幫上什麼忙，我們都歡迎。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31386] = {title = "影潘的進攻", objective = "到螳螂荒原的長陰哨站找塔蘭‧祝。", description = "許多世紀以來，我們影潘第一次將所有的武力集結起來。\n\n仇恨之煞逃出玉蛟寺了，將它再次囚禁起來，是我們神聖的責任。\n\n然而，我們的戰士雖優秀，但我們的人數很少。若有一個能幹的<class>願意協助我們，想來不會受到拒絕。\n\n如果你想加入攻擊部隊，就到螳螂荒原去跟塔蘭‧祝談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31387] = {title = "了解影潘", objective = "取得金蓮會的聲望崇敬。", description = "影潘是潘達利亞最古老的守護者。\n\n我們在高聳崑萊峰之上的僧院中接受多年的訓練，精鍊我們祖先所傳下來的武術秘訣。\n\n我們的數量或許很少，但一名影潘足比一百個訓練有素的士兵還要致命。\n\n加入影潘是一條艱辛漫長的道路。如果這是你所尋求的道路，那你必須證明你的價值。\n\n這裡有一項十分緊急的任務。幫助金蓮會保衛恆春谷。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31388] = {title = "影潘的進攻", objective = "到螳螂荒原的長陰哨站找塔蘭‧祝。", description = "許多世紀以來，我們影潘第一次將所有的武力集結起來。\n\n仇恨之煞逃出玉蛟寺了，將它再次囚禁起來，是我們神聖的責任。\n\n然而，我們的戰士雖優秀，但我們的人數很少。若有一個能幹的<class>願意協助我們，想來不會受到拒絕。\n\n如果你想加入攻擊部隊，就到螳螂荒原去跟塔蘭‧祝談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31389] = {title = "了解影潘", objective = "取得金蓮會的聲望崇敬。", description = "影潘是潘達利亞最古老的守護者。\n\n我們在高聳崑萊峰之上的僧院中接受多年的訓練，精鍊我們祖先所傳下來的武術秘訣。\n\n我們的數量或許很少，但一名影潘足比一百個訓練有素的士兵還要致命。\n\n加入影潘是一條艱辛漫長的道路。如果這是你所尋求的道路，那你必須證明你的價值。\n\n這裡有一項十分緊急的任務。幫助金蓮會保衛恆春谷。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31390] = {title = "卡拉西", objective = "到悚然荒野與恆春谷之間的落陽關找女弓手李。", description = "卡拉西只是謠傳中的存在，傳說他們住在牆外的悚然荒野中。\n\n很少有人願意冒險進入那個區域，而且從來沒有人回來述說那裡的故事。\n\n如果你要去找這些…卡拉西…那麼在遙遠的西南方，有一小群在長城工作的影潘，他們或許會知道更多關於卡拉西的事。", progress = nil, completion = "悚然荒野是非常危險的地方。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31391] = {title = "卡拉西", objective = "到悚然荒野與恆春谷之間的落陽關找女弓手李。", description = "卡拉西只是謠傳中的存在，傳說他們住在牆外的悚然荒野中。\n\n很少有人願意冒險進入那個區域，而且從來沒有人回來述說那裡的故事。\n\n如果你要去找這些…卡拉西…那麼在遙遠的西南方，有一小群在長城工作的影潘，他們或許會知道更多關於卡拉西的事。", progress = nil, completion = "悚然荒野是非常危險的地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31392] = {title = "白虎寺", objective = "到崑萊峰的白虎寺找安杜因‧烏瑞恩。", description = "你聽到消息了嗎，旅行者？我我們的至聖之地恆春谷遭到攻擊了！\n\n就在此刻，有個人類王子正在白虎寺裡跟其他人爭論，到底該不該允許像你或其他來自迷霧另一端的種族進入那裡。\n\n白虎寺就在崑萊峰的東北方。或許你能說服白虎允許你入谷？\n\n我只希望恆春谷別全毀了…", progress = nil, completion = "&lt;class&gt;，真高興你在這兒!熊貓人談論著一個傳說中的地方，「恆春谷」。如果當地人的描述可信，那麼這個地方具有偉大的治癒力量。\n\n可是部落的大酋長對恆春谷做了某種事情，某種可怕的事情。\n\n我們必須進去那兒!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31393] = {title = "白虎寺", objective = "到崑萊峰的白虎寺找戴斯可。", description = "你聽到消息了嗎，旅行者？我我們的至聖之地恆春谷遭到攻擊了！\n\n就在此刻，有個人類王子正在白虎寺裡跟其他人爭論，到底該不該允許像你或其他來自迷霧另一端的種族進入那裡。\n\n白虎寺就在崑萊峰的東北方。或許你能說服白虎允許你入谷？\n\n我只希望恆春谷別全毀了…", progress = nil, completion = "哈囉，&lt;class&gt;!我們獲准覲見白虎了。恆春谷最近遭到我們大酋長的摧殘，我們在爭論聯盟和部落雙方都該獲准回到谷裡，來修復這裡所受的傷害。\n\n山谷是個神聖的地方。我相信我的妻子麗紗曾經預見過它，這也是我的人民來到潘達利亞的原因。我們一定要拯救這裡!\n\n你覺得我們能得到入谷的許可嗎?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31394] = {title = "神聖的體驗", objective = "與雪怒交談，並完成祂的任務。", description = "沒有經過聖獸天尊的允許，任何人都不能進入山谷。白虎雪怒似乎已準備好要聽我說話。\n\n但自從最近的事件後，影潘的塔蘭‧祝就很不願意讓聯盟或部落的人接近山谷半步。\n\n<安杜因搖搖頭。>\n\n也許你能幫我。代表我們去跟白虎談談吧。小心點!他或許會為你設下許多挑戰...", progress = "你完成白虎的任務了嗎?", completion = "你辦到了，&lt;name&gt;!\n\n白虎同意讓我們跟熊貓人一起進入恆春谷。谷裡已經有一座聯盟哨站了。現在可以展開修復損害的艱辛工作了!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31395] = {title = "神聖的體驗", objective = "與雪怒交談，並通過祂的測試。", description = "那個人類小子為我們發言。他講話很得體；我能了解為什麼貝恩‧血蹄會給這王子這麼高的評價。\n\n不過，這場爭辯還是沒有好的結果。我是個無名小卒，但你是部落的英雄。或許你可以幫我們講幾句好話?\n\n跟白虎談談，解釋我們的情況，<race>。\n\n小心點!祂或許會為你設下許多挑戰...", progress = nil, completion = "你辦到了，&lt;name&gt;!\n\n白虎同意讓我們跟熊貓人一起進入恆春谷。\n\n聯盟王子辦不到的事，部落的英雄成功了。\n\n恆春谷裡已經有一座部落哨站了。現在可以展開修復損害的艱辛工作了。", rewards = "您會收到：\n\n恆龍寶箱"}
