MultiLanguageQuestData['tw'][31439] = {title = "中斷的訊號", objective = "到暮根沼地喚醒聖螳。", description = "珀光洞穴中的信標似乎遭到了改動。在信號斷掉之前，卡拉西瓦接收到附近一個聖螳的訊號。\n\n他們相信那個聖螳就藏匿在那汙穢的小沼澤，暮根沼地裡面。\n\n我會跟你一起到沼澤去設置一個暫時的信標，直到我能讓琥珀之光重新開始運作為止。\n\n你要去喚醒那名聖螳，並且幫助我。", progress = nil, completion = "看來我的工作立刻就要開始了。你的處境相當危險，喚醒者。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31440] = {title = "四部巨著", objective = "摧毀四部巨著:「在聖光的陰影之中」、「科爾蘇加德的深層知識」、「禁忌儀式與其他死靈儀式」、以及「闇黑魔典」。", description = "通靈學院中有四本關於偉大死靈邪惡研究的巨著:「在聖光的陰影之中」、「科爾蘇加德的深層知識」、「禁忌儀式與其他死靈儀式」、以及「闇黑魔典」。\n\n當我們設法通過這個受詛咒之地時，把這四本書找出來並摧毀掉，免得在我們之後有傻瓜跟著進來，並學會他們邪惡的秘密。", progress = nil, completion = "謝謝你，&lt;name&gt;。\n\n摧毀這些書冊，知道它們再也不能傷害任何活著的靈魂之後，我終於能得到永恆的安眠了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31441] = {title = "腐敗加深", objective = "到暮根沼地擊敗叛徒。", description = "喚醒者，今天你學到了，在戰爭時沒有任何人可以相信。即使與卡拉西最親近的人也那麼容易受到污染。\n\n誰知道這個叛徒被污染多久了。一定得殺了他！\n\n你似乎很困惑。你沒看出我們當中的那個叛徒嗎？讓我來幫你把眼睛擦亮點吧。", progress = nil, completion = "你將會看到更多這種事情。戰爭永遠都是醜惡的。\n\n女皇的污染範圍很廣，而且很難查出來。\n\n有許多工作得完成。我們必須開始修復柯利克造成的損害。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31442] = {title = "四部巨著", objective = "摧毀四部巨著:「在聖光的陰影之中」、「科爾蘇加德的深層知識」、「禁忌儀式與其他死靈儀式」、以及「闇黑魔典」。", description = "通靈學院中有四本關於偉大死靈邪惡研究的書冊:「在聖光的陰影之中」、「科爾蘇加德的深層知識」、「禁忌儀式與其他死靈儀式」、以及「闇黑魔典」。\n\n當我們設法通過這個受詛咒之地時，把這四本書找出來並摧毀掉，免得在我們之後有傻瓜跟著進來，並學會他們邪惡的秘密。", progress = "這四本書冊裡包含的秘密，就是詛咒這個地方並賦予它永恆苦難的根源。\n\n必須摧毀它們!", completion = "謝謝你，&lt;name&gt;。\n\n摧毀這些書冊，知道它們再也不能傷害任何活著的靈魂之後，我終於能得到永恆的安眠了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31443] = {title = "飛天虎斑絲足魚", objective = "把飛天虎斑絲足魚帶去釣手泊船處給納特‧帕格。", description = "你釣到了一條獨特的魚...有翅膀的。或許有必要去釣手泊船處找納特‧帕格詢問一下專家意見。", progress = "會飛的魚?", completion = "這是飛天虎斑絲足魚嗎?\n\n這隻小魚是虎斑絲足魚中少見的飛行突變種，在潘達利亞各處的淡水水域中都可以抓到這種魚。\n\n當地傳說吃了這種魚會帶來好運。而按照當地傳統，只有皇室的人可以吃這種魚。破壞這種「傳統」的人會被判處死刑。\n\n考慮到這一點，我會務必將這條魚交到正確的人手中。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31444] = {title = "棘魚首領", objective = "把棘魚首領帶去釣手泊船處給納特‧帕格。", description = "你釣起了某種特別的東西。牠看起來十分具侵略性。\n\n或許釣手泊船處的納特‧帕格對這東西有更多了解?", progress = "怪魚?", completion = "這該不會是我想的那個東西吧，是嗎?哇喔，一隻棘魚首領，潘達利亞最致命的掠食者。\n\n棘魚是煞所造就出來的一種畸形異怪，這種體型大的更是可怕。棘魚首領常會吃掉其他的棘魚，即使這種魚身上沒有任何一個地方可以食用。\n\n我們兩個運氣很好，對於鍊金師來說，他們是很有趣的東西。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31446] = {title = "擬色章魚", objective = "把擬色章魚帶去釣手泊船處給納特‧帕格。", description = "你不確定自己是怎麼辦到的，不過你抓到了一隻特別的頭足類生物。釣手泊船處的納特‧帕格一定會想看看牠。", progress = "偽裝章魚?", completion = "那是一隻擬色章魚嗎?我有個好友幾年前曾在贊達拉海外抓到過一隻。事實上，他差點沒辦法活著回來。那傢伙是個討厭的食人妖，但很懂釣魚!\n\n總之，這種章魚沒有你想像得那麼稀少，因為牠們會利用偽裝來躲藏在岩石與植物之間;只有非常老練的漁夫才有希望抓到這種難以捉摸的美味佳餚。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31447] = {title = "苦難的終點", objective = "殺死黑暗院長加丁。", description = "黑暗院長加丁的真正死亡是解除這地方詛咒的關鍵。\n\n上吧，$p，讓他痛苦!", progress = nil, completion = "看哪，這就是我真正的模樣。\n\n我欠你一份情，雖然這份情也許我永遠還不了，但我還是要感謝你解除我家族的詛咒。\n\n科爾蘇加德、巫妖王，還有黑暗院長加丁，總算全都死了。\n\n或許，如今我也能找到些許的平靜。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31448] = {title = "苦難的終點", objective = "殺死黑暗院長加丁。", description = "黑暗院長加丁的真正死亡是解除這地方詛咒的關鍵。\n\n上吧，$p，讓他痛苦!", progress = nil, completion = "看哪，這就是我真正的模樣。\n\n我欠你一份情，雖然這份情也許我永遠還不了，但我還是要感謝你解除我家族的詛咒。\n\n科爾蘇加德、巫妖王，還有黑暗院長加丁，總算全都死了。\n\n或許，如今我也能找到些許的平靜。", rewards = "符文亡骨胸鎧雕者濺血護軀冷爐甲殼拼湊血肉護甲食屍鬼膚法衣黑暗院長的備用長袍強能骨堆長袍銘刻血鏈鍊衫邪惡蒼白護甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][31450] = {title = "新的命運", objective = "與尚羲大師的靈魂交談，並選擇你想與聯盟還是部落一起離開。", description = "這些新盟友點出了一個重大的事實:受苦的並不只是神真子，而是白雲彼端的所有土地。世界需要療癒，而我想你將是為世界施予治療的那個人。\n\n我要你、紀跟艾莎離開，將你們的力量與智慧帶到整個世界上去。聯盟與部落有著不同的理想，但核心目的都是高貴的。\n\n我讓你們自己選擇想要加入哪一方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31451] = {title = "失蹤的商人", objective = "到崑萊峰的墨鰓湖找商人阿席。", description = "通常，商人阿席會到崑萊峰與錦魚人和咕嚕摩做交易。我們聽說他沒在濱南出現，而我們也還沒在這裡見到他…\n\n我擔心他發生什麼事了。你能去墨鰓湖看看他在不在那兒嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31452] = {title = "失蹤的商人", objective = "到崑萊峰的墨鰓湖找商人阿席。", description = "通常，商人阿席會到崑萊峰與錦魚人和咕嚕摩做交易。我們聽說他沒在濱南出現，而我們也還沒在這裡見到他…\n\n我擔心他發生什麼事了。你能去墨鰓湖看看他在不在那兒嗎？", progress = nil, completion = "我的兒子！他們抓走我的兒子…你能幫我嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31453] = {title = "影潘", objective = "到火枝望角的影潘後援地找影潘宗師沖。", description = "我們的新成員都在私下談論一個名為「影潘」的熊貓人集團。他們顯然非常強大，而且行蹤隱密。\n\n很顯然的，無論崑萊這裡發生了什麼事，與這些影潘結盟，對我們在潘達利亞建立據點具有決定性的影響。\n\n這就是你派上用場的地方了。謠傳他們在東南方的火枝望角附近有個行動基地。\n\n你要到那裡去討好他們。為了部落!", progress = nil, completion = "你是誰?你能戰鬥嗎?如果可以，那我們用得上你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31454] = {title = "创造传奇", objective = "和拉希奥喝一杯。他请客。", description = "我们的世界走到了十字路口。接下来的几个月中将会发生各种各样的事情——假如我们还有未来的话。\n\n啊！我好像有点跑题了，还是说回眼前的事吧。来，和我喝一杯。我们来讨论一下艾泽拉斯的未来。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31455] = {title = "影潘", objective = "到火枝望角的影潘後援地找影潘宗師沖。", description = "我們的新成員，對於一個他們稱為「影潘」的熊貓人團體始終秘而不宣。他們顯然非常強大，而且行蹤隱密。\n\n這就是你派上用場的地方了。謠傳他們在東南方的火枝望角附近有個行動基地。你該以聯盟使節的身分到那裡去。給予他們要求的任何幫助。", progress = nil, completion = "你是誰？你能戰鬥嗎？如果可以，那我們用得上你。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31456] = {title = "麝爪牧場", objective = "到崑萊峰的麝爪牧場找勞‧麝爪。", description = "外頭有另一個叫做麝爪牧場的熊貓人殖民地。因為揚古入侵惹出的這些事，我擔心他們是否安好。\n\n你幫了我們很多忙，你應該去那裡看看他們的狀況，朋友!", progress = nil, completion = "啥？你是什麼鬼東西？你在這裡幹什麼？\n\n喔，你想幫忙？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31457] = {title = "麝爪牧場", objective = "到崑萊峰的麝爪牧場找勞‧麝爪。", description = "外頭有另一個叫做麝爪牧場的熊貓人殖民地。因為揚古入侵惹出的這些事，我擔心他們是否安好。\n\n你幫了我們很多忙，你應該去那裡看看他們的狀況，朋友!", progress = nil, completion = "啥？你是什麼鬼東西？你在這裡幹什麼？\n\n喔，你想幫忙？", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31458] = {title = "損害控制", objective = "摧毀10個伊克席克耳語者，並關閉奇帕利依科信號水晶。", description = "柯利克持續發送訊號給女皇好幾個星期了。卡拉西做的每一件事，女皇都一清二楚。\n\n這件事將到此為止!!\n\n奇帕利依科是接收柯利克訊息的第一站。確保訊息無法傳遞給女皇，將能為我方取得優勢。\n\n摧毀那裡的耳語者與信號裝置，那樣能幫我們爭取足夠的時間，在女皇有機會行動之前想出一個計畫。", progress = "資訊就是力量，喚醒者。擁有最多資訊的人就擁有最大的力量。", completion = "幹得漂亮!這應該可以讓我們有時間修復柯利克造成的損害。\n\n你或許將戰局改變成對我方有利的情勢了。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31459] = {title = "阿洲的口信", objective = "到崑萊峰的獨罈集找博學行者阿洲。", description = "那群咕嚕摩當中走來了一個人，他說博學行者阿洲有口信給你。你應該前去與他會面，他或許有什麼重要的事情要說。\n\n那個咕嚕摩說阿洲人在北方的獨罈集。", progress = nil, completion = "喔，哈囉，很高興又見到你了。", rewards = nil}
MultiLanguageQuestData['tw'][31460] = {title = "阿洲的口信", objective = "到崑萊峰的獨罈集找博學行者阿洲。", description = "那群可愛的小咕嚕摩當中，有一個走過來，告訴你博學行者阿洲送了訊息給你。你應該去跟他見面!\n\n那個咕嚕摩說，阿洲在北邊的獨罈集那裡。", progress = nil, completion = "喔，哈囉，很高興又見到你了。", rewards = "您會收到：\n\n"}
