MultiLanguageQuestData['tw'][31467] = {title = "健壯如虎", objective = "跟著燒烤大師練習製作火烤老虎肉排，然後交給他5塊火烤老虎肉排。", description = "經過燒烤，你可以將生虎排變成使你更強壯的食物。跟我學習製作火烤老虎肉排的方法。讓我看看你的成果。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31468] = {title = "黑龍王子的考驗", objective = "在黑龍王子那裡贏得尊敬聲望值。恆春谷、螳螂荒原與悚然荒野中，等級90的魔古與螳螂人可以讓你贏得聲望值。", description = "根據我可靠的情報顯示，你是英雄中的英雄，但請原諒我的無禮，我想親自測試你的實力。\n\n攻擊恆春谷的魔古，棲息在衫織島的魔古走狗，以及悚然荒野那被煞污染的螳螂人蟲群... 對於你這樣有才能的人來說，這些應該是很合適的考驗。\n\n向我證明你的能力。別著急，我預期這會花你一些時間的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31469] = {title = "UNUSED", objective = "Make a Charbroiled Tiger Steak for the Master of the Grill. You will need to learn the Way of the Grill and the recipe from him first.", description = "The Pandaren Way of the Grill produces foods that increase your physical strength. Learn the recipe for Charbroiled Tiger Steak from the Master of the Grill and show him the results of your learning.您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31470] = {title = "快炒之道", objective = "帶5根脆嫩多汁胡蘿蔔給快炒大師。", description = "如果你想製作能讓你變得更加敏捷的餐點，你該帶些紅蘿蔔跟米去給快炒大師。這附近的兔妖通常攜帶有大量的紅蘿蔔。如果你有農場的話，也可以自己種。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n快炒之道\n\n您還會收到：\n\n脆嫩多汁胡蘿蔔鐵爪徽章"}
MultiLanguageQuestData['tw'][31471] = {title = "迅捷如虎", objective = "接受快炒大師的炒胡蘿蔔訓練，然後把5份炒胡蘿蔔交給她。", description = "要用炒鍋作料理，你需要敏捷的速度。你的第一堂課是炒胡蘿蔔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31472] = {title = "燉煮之道", objective = "帶5隻翠玉龍魚去給燉煮大師。", description = "燉煮之道所烹調出的食物能增長你的智力。帶一些翠玉龍魚去給燉煮大師，她會教你。你可以到翠玉林裡去釣翠玉龍魚。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n燉煮之道\n\n您還會收到：\n\n翠玉龍魚鐵爪徽章"}
MultiLanguageQuestData['tw'][31473] = {title = "敵人的力量", objective = "到魔古山寶庫、恐懼之心或豐泉台，從團隊首領身上取得10個力量符印與10個智慧符印。", description = "要成為偉大的領導者，需要擁有塑造人民命運的力量，和做出正確決策的智慧。在潘達利亞上有著偉大的力量和古老的智慧，但這兩者很少共存在同一處。\n\n來看看你跟我是否能改變這個現狀!\n\n到魔古山寶庫、恐懼之心或豐泉台去，從死去的敵人身上取得力量與智慧的符印。考慮到他們主人的現況，我們能更妥善地運用這些符印。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31474] = {title = "沉思的湯", objective = "接受燉煮大師的繚繞薄霧湯訓練，然後把5份繚繞薄霧湯交給她。", description = "看著燉鍋，你會有很多思考的時間。讓我教你如何製作繚繞薄霧湯，你就會明白我的意思了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31475] = {title = "蒸煮之道", objective = "帶5隻巨型螳螂蝦給蒸煮大師。", description = "好的一餐能提振你的精神，蒸煮之道的食物最能達到這種效果。帶一些巨型螳螂蝦去給大師，他會讓你見識一下。你可以在海裡釣到巨型螳螂蝦。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n蒸煮之道\n\n您還會收到：\n\n巨型螳螂蝦鐵爪徽章"}
MultiLanguageQuestData['tw'][31476] = {title = "烹飪精神", objective = "接受蒸煮大師的鮮蝦蒸餃訓練，然後把5份鮮蝦蒸餃交給他。", description = "在我蒸東西的時候，我將愛灌注到食物裡。讓我把鮮蝦蒸餃的食譜教給你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31477] = {title = "耐性", objective = "接受烘烤大師的炭烤野雉訓練，然後把5份炭烤野雉交給他。", description = "據說鶴群中被指派為負責警戒的那隻鶴，會在喙裡啣一枚石子，那樣一來，如果牠不小心睡著，石子就會從嘴裡掉下來驚醒牠。要熟練烤爐的技巧，你得擁有耐力和耐心。學習製作炭烤野雉，然後讓我知道你了解箇中真意。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31478] = {title = "烘烤之道", objective = "帶5份野雉胸肉給烘烤大師。", description = "如果你想要充滿飽足感、增強體耐力的豐富一餐，你該追隨烘烤之道。帶一些野雉胸肉去給烘烤大師，她會教你。在四風峽與翠玉林中有許多鶴，不過你也可以從其他鳥身上取得野雉胸肉。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n烘烤之道\n\n您還會收到：\n\n野雉胸肉鐵爪徽章"}
MultiLanguageQuestData['tw'][31479] = {title = "釀酒之道", objective = "帶1份人參給釀酒大師。你可以向宋辛‧鐵爪買人參。", description = "熊貓人的釀酒之道會生產出…嗯，我還是讓釀酒大師來解釋吧。帶一些人參給他，他會讓你看看釀酒之道。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n釀酒之道\n\n您還會收到：\n\n人參鐵爪徽章"}
MultiLanguageQuestData['tw'][31480] = {title = "喝一杯", objective = "接受釀酒大師的人參茶訓練，然後把1份人參茶交給他。", description = "我的同伴真是嚴肅。我覺得生命苦短，不該一直這麼嚴肅。我們一起喝杯茶。讓我教你如何製作人參茶吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31481] = {title = "恐惧", objective = "在永春台击败惧之煞并获得恐惧奇美拉。", description = "我在这里的这段时间，学习了一些熊猫人的智慧。我尤其喜欢这句话：\n\n“自卑者忧难；怯懦者畏难；勇者克难而后怕。”\n\n这句话有没有道理呢？我们来试试吧。\n\n惧之煞已经潜入了永春台。去那里找到它、击败他并抽出他的灵魂——假如它有灵魂的话。\n\n你的勇敢将会得到丰厚的奖赏的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31482] = {title = "黑龍王子之息", objective = "到巧匠之愚的石階頂端去與怒西昂見面，並領取你的獎賞。", description = "<怒西昂銳利的紅色眼睛凝視著你。>\n\n像你這類的人十分的罕見，<name>。\n\n你正是我要找的，憑一己之力就能影響全世界的那種人。\n\n現在來吧，我答應你會有你應得的獎賞!這個客棧的東邊有一段石階，通往一個當地人稱為「巧匠之愚」的地方。到那裡跟我碰頭。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n晶化畏懼晶化恐懼晶化恐怖\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][31483] = {title = "即将到来……", objective = "当你的海军舰队在潘达利亚南部海岸登陆之后，联系拉希奥。", description = "熊猫人的战争才刚刚开始！我们现在得把注意力集中到联盟和部落之间的冲突上了。\n\n我在拉文霍德的联络人告诉我，联盟第七军团和大规模的部落侵略部队正在向潘达利亚南部海岸进发。无论你是否愿意，潘达利亚很快就会变成一个战场。\n\n我们可以暂时蛰伏，但我希望你能在你们的舰队达到之后联系我。然后……我们将采取行动！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31484] = {title = "Hisek Tracking Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31485] = {title = "UNUSED", objective = "Learn the recipe for Soft-Boiled Eggs from the Guide to the Ways and make 5 of them for her.", description = "I am not a master chef like my siblings. What I am is a great teacher. If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are.\n\nIf you wish to learn, show me you can at least follow basic instructions. Learn the recipe for soft-boiled eggs, make five of them and bring them to me.  I have fresh eggs which I will sell to you at a token price.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31486] = {title = "我這身廚藝", objective = "將信送去給宋辛‧鐵爪。她在半丘市集裡教學。", description = "我真高興你喜歡我的食物。你對食譜有興趣嗎？有的話，你應該跟我在半丘市集的諸位老師好好學一下。我身上一切和廚房有關的技藝，都是他們教我的。\n\n如果你剛好經過那裡，能不能替我把這紙條交給宋辛‧鐵爪？她是我最喜歡的老師，我想讓她知道我想念她。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31487] = {title = "聲波干擾", objective = "在杉齊爾窩巢殺死4隻恐懼崑蟲和6隻杉齊爾操縱者。音波崩解叉會削弱崑蟲並使牠們陷入混亂。", description = "用聲波的低語操縱崑蟲在我的研究中還只是最原始的階段，但帝國似乎完全採納了這種方式。杉齊爾的操縱者太缺乏耐性，沒和他們的崑蟲達成適當的鏈結。\n\n這種懶惰會讓他們付出代價。\n\n把這個調音叉放到窩巢裡的崑蟲附近，然後欣賞牠們在困惑中反撲牠們主人的模樣。利用這個優勢，將他們消滅。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31488] = {title = "异乡的陌生人", objective = "在雾纱栈道的迷雾酒肆找到“黑王子”。", description = "对不起，<class>。你是<name>吗？\n\n一个披着黑色斗篷的人让我把这个交给你。和你一样，她也是来自迷雾之外的旅行者，但是——我不相信她。\n\n这个消息来自雾纱栈道的酒馆。我会把信交给你的……但是你在去那里的时候一定要小心提防！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31489] = {title = "陌生異地的陌生人", objective = "到朦朧天梯的霧隱客棧找出怒西昂。", description = "請問一下，<class>。你的名字是<name>嗎?\n\n一個穿著黑色斗篷的人叫我把這個交給你。她跟你一樣是來自迷霧另一頭的旅行者。嗯，我不信任她。\n\n她提到「怒西昂」這個名字。這有讓你想到什麼嗎?\n\n我會把這個紙條交給你，但...如果你要和這些人打交道，你得多加小心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31490] = {title = "徹底抹消", objective = "到血色大廳中殺死50名血色十字軍成員。", description = "該做的先做。讓我們去殺一些十字軍吧。\n\n當我說去殺一些血色十字軍時，我指的是抹消他們，連根拔除，一個不剩。", progress = nil, completion = "非常好的開始，&lt;name&gt;!\n\n不用多久，血色十字軍將化為歷史紀錄中一個醜惡的註腳，除此之外什麼也不是。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31492] = {title = "力量火炬", objective = "帶著力量火炬到白虎寺的大門去，並不讓火炬熄滅。", description = "雪怒說這個挑戰可以幫助「鍛鍊力量」。我開始覺得，他所謂「力量」的定義跟我們其他人不一樣。\n\n哪，帶著這個火炬到寺廟門口的最頂端。如果你能到達那裡而火炬還沒熄滅，你就算通過這項挑戰。\n\n不管你怎麼做，千萬別嘗試帶著火炬騎馬。你的火炬會被風吹熄。相信我。", progress = nil, completion = "哇喔!你辦到了。通常我遇上那陣狂風之後就失敗了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31493] = {title = "只是保管而已，當然了", objective = "收集十字軍聖典。", description = "大廳裡有一本書，對我來說極具價值。\n\n不幸的是，這本書在織焰者喀格勒手裡。我之前試過想接近他，但從來沒成功過。\n\n你的運氣或許會好一點。要小心，我聽說他是個真正的瘋子。織焰者計畫要燒掉圖書館裡的所有書籍。\n\n在過程中他可能會連血色大廳一起燒了。", progress = "取得那本典籍，對我來說是絕對必要的。", completion = "啊太好了!\n\n&lt;戴頭罩的十字軍看到典籍時，開心地搓著雙手。&gt;\n\n那麼，現在我有血色十字軍的名單了!\n\n你知道的...以防有漏網之魚。我做事不喜歡有遺漏。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31494] = {title = "脫離窩巢", objective = "在杉齊爾窩巢打開崑蟲籠子來解放8名小崑蟲。", description = "杉齊爾操縱者將年幼崑蟲關進窩巢裡，讓他們暴露在純粹的恐懼能量中，扭曲牠們，加速牠們的生長。\n\n令人厭惡!我絕不允許!\n\n打開牢籠，放那些幼蟲自由。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31495] = {title = "徹底抹消", objective = "到血色大廳中殺死50名血色十字軍成員。", description = "該做的先做。讓我們去殺一些十字軍吧。\n\n當我說去殺一些血色十字軍時，我指的是抹消他們，連根拔除，一個不剩。", progress = nil, completion = "非常好的開始，&lt;name&gt;!\n\n不用多久，血色十字軍將化為歷史紀錄中一個醜惡的註腳，除此之外什麼也不是。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31496] = {title = "採集帝國極品純釀", objective = "在恐懼之心外的帝國餵食管使用樹汁罐來將它裝滿。", description = "奇帕利樹液總是讓我感到很神奇。在它數不清的特性和用途中，有一種是將它精製成富含營養且極度美味的靈液。\n\n皇宮是整個帝國裡最懂得如何製作這種飲料的地方。想當然爾，那些忠誠者的家裡有餵食管在為他們灌注這種甜美的甘露。\n\n在他們的餵食管那裡將這個罐子裝滿，然後帶回來給我。我很想再次嘗試帝國的這種極致美味。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31497] = {title = "只是保管而已，當然了", objective = "收集十字軍聖典。", description = "大廳裡有一本書，對我來說極具價值。\n\n不幸的是，這本書在織焰者喀格勒手裡。我之前試過想接近他，但從來沒成功過。\n\n你的運氣或許會好一點。要小心，我聽說他是個真正的瘋子。織焰者計畫要燒掉圖書館裡的所有書籍。\n\n在過程中他可能會連血色大廳一起燒了。", progress = "取得那本典籍，對我來說是絕對必要的。", completion = "啊太好了!\n\n&lt;戴頭罩的十字軍看到典籍時，開心地搓著雙手。&gt;\n\n那麼，現在我有血色十字軍的名單了!\n\n你知道的...以防有漏網之魚。我做事不喜歡有遺漏。", rewards = "法拉克斯護腰血色勇士腰帶維爾當啃過的腰鎧煎熬羞愧腰帶扔桶者束腰血腥福音之索學者之索血色弓箭手鎖鍊洛克希的失落腰帶您會收到：\n\n法拉克斯護腰血色勇士腰帶維爾當啃過的腰鎧煎熬羞愧腰帶恆龍寶箱"}
