MultiLanguageQuestData['tw'][31502] = {title = "折翼", objective = "在杉齊爾窩巢從杉齊爾刺針螳螂身上收集到24個釘刺者翅膀。", description = "這個世代的飛行者真是令人讚嘆。在我那時候，他們出色的敏捷和耐力是在群體中最佼佼者或成熟飛行者身上才能看到的。\n\n這似乎顯示出在翅膀結構上的演化...或者是先進訓練法達到的成果?有意的基因突變?或是育種?\n\n啊!沒有生體組織的樣本，實在沒辦法確定。\n\n把他們的翅膀帶來給我!盡量不要弄壞了，好嗎?我需要完整的樣本!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31503] = {title = "通往毀滅的捷徑", objective = "在恐懼之心外面殺死斐斯守衛納卡爾。", description = "那群忠誠追隨者中，有一名勇士名叫斐斯守衛納卡爾。他的力量並非來自經驗和訓練，而是來自基因調整。他要被當成未來螳螂人的模範，這種想要一出生就得到力量而非努力獲取的作法令我作嘔。\n\n他是對我一切努力的污辱!基因強化只該用在成熟、出生後的老兵身上!\n\n把他給解決掉。或許那樣杉齊爾女皇就能學到走捷徑只會帶來毀滅的道理。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31504] = {title = "軍事配置", objective = "在杉齊爾窩巢和恐懼之心附近解除8個費洛蒙地雷。", description = "如果杉齊爾女皇的探員依然按照我那時代的安全程序行事，他們應該在窩巢四周埋藏了強力的費洛蒙地雷。\n\n只要輕輕低語，她就能同時引爆所有地雷，吞沒整個宮殿，讓攻入的軍隊徹底無力化。\n\n我們必須拆除那些地雷才能成功地進行大規模入侵。我在與你碰面時交給你的...「禮物」能讓你看見那些地雷。觸發它們然後躲到安全的距離去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31505] = {title = "斐斯守衛的責任", objective = "到贊斐斯殺死斐斯守衛維卡茲。", description = "斐斯守衛維卡茲在贊斐斯調度防禦部隊。在戰場上，他的戰力可抵10隻螳螂人，而且他的存在可以激勵與他並肩作戰的贊席克。\n\n不用說，他必須死。\n\n他就徘徊在島嶼中心的居住區。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31506] = {title = "操控鐐銬", objective = "到贊斐斯，從意念控制的礦工與意念控制的蠻卒身上收集6個贊席克鐐銬。", description = "贊席克僱用了大量的...約聘勞工。\n\n揚古受到一種特殊鐐銬的制約，這種鐐銬能用來增強並擴大聲波操控的效果。就是這種技術讓贊席克能夠指揮大量的奴隸，在採石場進行永無休止的勞動工作。\n\n我要研究一下這些鐐銬。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31507] = {title = "溶化", objective = "到贊斐斯殺死6隻贊席克琥珀殼。使用柯爾文的實驗品來削弱牠們強化的甲殼。", description = "贊斐斯那些有毒刺的蠍子從小就被餵食樹液，從而產生一種奇妙的突變，牠們的天生的甲殼裡注滿了琥珀。事實上，這是有機的奇帕利，這種物質被用來打造帝國的絕大多數武器與裝甲。\n\n我想我找到了一種可以讓奇帕利溶解的化學方法，但這需要測試。把這些手榴彈用在贊席克毒針身上，並將結果記錄下來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31508] = {title = "要求樣本", objective = "到潮間帶去，從奇帕利爬行蟲身上收集6份奇帕利裂片。", description = "為了擬態成周遭環境，奇帕利環蟲具有極高的適應性。牠們還可以長成大部分生物無法企及的巨大尺寸。\n\n牠們的生理構造可以為後續階段的突變提供寶貴的資訊。\n\n到贊斐斯附近的淺灘去，從奇帕利環蟲身上取回一些碎片樣本給我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31509] = {title = "恐懼扎根", objective = "到贊斐斯與潮間帶摧毀15個懼孢球莖。", description = "終結了她的統治之後，杉齊爾的瘋狂所帶來的餘波，將繼續盪漾一段很長的時間。在未來的許多年裡，我們將拼命地治療我們的新土地;就算這樣，我們所做的一切也很可能徒勞無功。\n\n一個被煞扭曲的新物種植物已開始在贊斐斯附近扎根。摧毀你所找到的每一株這種植物，但要小心，我們不知道它會有什麼樣陰險的防禦方式。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31510] = {title = "寂然無聲", objective = "在贊斐斯的低語石與贊席克共鳴水晶進行交流，藉此刺激隨從賽考特，然後殺了他。", description = "在贊斐斯的西南角有低語石。那些東西有點像我們這裡的信號塔，是遠距離聲波傳輸的關鍵。\n\n有一個女皇的隨從在操縱這些石頭，讓她跟贊席克部隊保持聯繫。截斷訊號，滅了他的口。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31511] = {title = "歷史的見證", objective = "到聖獸天尊之門找日行者戴斯可。", description = "我會集合其他牛頭人朝聖者，一起前往恆春谷。\n\n到崑萊峰南方邊界的聖獸天尊之門找我，並在那裡跟我談談。", progress = nil, completion = "歡迎來到雙月廟，旅行者。\n\n我知道聖獸天尊派你來幫助我們，可是先花點時間休息，並且探索這座城市吧。\n\n歡迎來到恆春谷。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31512] = {title = "歷史的見證", objective = "到聖獸天尊之門找安杜因‧烏瑞恩。", description = "天尊允許我們回到恆春谷了!那一定是個壯觀的景象。\n\n我們別再浪費時間了。到崑萊峰南方邊界的聖獸天尊之門去，在那裡跟我談談。", progress = nil, completion = "歡迎來到七星廟。\n\n我希望能告訴你好消息，&lt;class&gt;，但是恆春谷裡的情勢相當嚴峻。\n\n要做的事情很多，可是先花點時間休息，並且探索這座城市吧。\n\n歡迎來到恆春谷。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31513] = {title = "聖佑之劍", objective = "收集兩把聖佑之劍。", description = "血色十字軍的問題在於他們會一直不停地回來，即使死了也一樣。\n\n他們能夠復活，背後的原因就是高階審判官懷特邁恩。只要殺了她，十字軍也死定了。\n\n為了讓她死得徹底，我們需要兩把傳說中的刀劍，這兩把刀劍背後都有著失傳的知名歷史。\n\n我很幸運...呃，我們很幸運，這兩把聖佑之劍就安置在修道院裡。\n\n找到它們，一旦你殺死懷特邁恩，就將刀劍刺入她的屍體，讓死亡成為永恆。", progress = "<你手上拿了一把劍，並伸手去取另一把。>\n\n<劍後方的雕像上刻著銘文，「天佑之手」。>", completion = "&lt;第二把聖佑之劍漂浮在一個潮濕的雕像前面。劍上冒著蒸氣。&gt;\n\n&lt;你有種不可思議的感覺，天佑之手在等待著你。&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31514] = {title = "汝當歸於塵土", objective = "在高階審判官懷特邁恩的屍體上使用聖佑之劍，將她送進永恆的死亡。", description = "<你將第二把聖佑之劍拿在手中，感受兩把劍刃的力量同時流竄過你的身體。>\n\n<眼前要做的事只剩一件。如同那名頭戴帽兜的神秘女人解釋過的，你必須將這兩把劍刃刺入高階審判官懷特邁恩的屍體中，才能終結血色十字軍。>", progress = nil, completion = "懷特邁恩永遠死去之後，血色十字軍也就完蛋了。現在只剩下清除垃圾的問題。\n\n謝謝你，&lt;name&gt;。謝你的不只是我，還有所有反對盲目仇恨與偏執的人。\n\n還有，謝謝你那兩把新的刀。她的鮮血成了新的油膏，這樣當我與通靈學院交戰並料理黑暗院長加丁時，它們應該可以為我提供很好的服務。\n\n我要暫時與你道別了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31515] = {title = "聖佑之劍", objective = "收集兩把聖佑之劍。", description = "血色十字軍的問題在於他們會一直不停地回來，即使死了也一樣。\n\n他們能夠復活，背後的原因就是高階審判官懷特邁恩。只要殺了她，十字軍也死定了。\n\n為了讓她死得徹底，我們需要兩把傳說中的劍，這兩把劍背後都有著失傳的知名歷史。\n\n我很幸運...呃，我們很幸運，這兩把聖佑之劍就安置在修道院裡。\n\n找到它們，一旦你殺死懷特邁恩，就將劍刺入她的屍體，讓死亡成為永恆。", progress = "<你手上拿了一把劍，並伸手去取另一把。>\n\n<劍後方的雕像上刻著銘文，「天佑之手」。>", completion = "&lt;第二把聖佑之劍漂浮在一個潮濕的雕像前面。劍上冒著蒸氣。&gt;\n\n&lt;你有種不可思議的感覺，天佑之手在等待著你。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31516] = {title = "汝當歸於塵土", objective = "在高階審判官懷特邁恩的屍體上使用聖佑之劍，將她送進永恆的死亡。", description = "<你將第二把聖佑之劍拿在手中，感受兩把劍刃的力量同時流竄過你的身體。>\n\n<眼前要做的事只剩一件。如同那名頭戴帽兜的神秘女人解釋過的，你必須將這兩把劍刃刺入高階審判官懷特邁恩的屍體中，才能終結血色十字軍。>", progress = nil, completion = "懷特邁恩永遠死去之後，血色十字軍也就完蛋了。現在只剩下清除垃圾的問題。\n\n謝謝你，&lt;name&gt;。謝你的不只是我，還有所有反對盲目仇恨與偏執的人。\n\n還有，謝謝你這兩把新劍。她的鮮血成了新的油膏，這樣當我與通靈學院交戰並料理黑暗院長加丁時，它們應該可以為我提供很大的助益。\n\n我要暫時與你道別了。", rewards = "精湛武藝護手正義信念護手狂熱激情手甲聖諭手套善益手套血色幻象手套灼熱淨化手套血腥審判護手深紅武僧裹手您會收到：\n\n精湛武藝護手正義信念護手狂熱激情手甲聖諭手套恆龍寶箱"}
MultiLanguageQuestData['tw'][31517] = {title = "與暴徒戰鬥", objective = "擊敗修努夫。", description = "我們崇尚力量，而不是獸性。但很不幸的，有些來到我門前的人忘記了這個區別。\n\n我驅逐了這樣一名挑戰者。為了報復，他劫掠了陰影村。\n\n到寺院東南方的陰影村去，面對這個「修努夫」。讓他弄清楚什麼才是真正的力量。", progress = nil, completion = "我宣布你獲得勝利，並感謝你料理了那些惡棍。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31518] = {title = "恆春谷", objective = "到聖獸天尊之門找安杜因。", description = "距離上次山谷大門打開，已經是許多許多世代之前的事了，<name>。\n\n我絕對不會錯過這件事，而你也不該錯過它!\n\n到崑萊峰的南方邊界跟我碰頭。我會在那裡等你。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31520] = {title = "夠格的挑戰:疑惑之煞", objective = "完成玉蛟寺挑戰模式。", description = "<name>，我要你募集一支隊伍，並領往玉蛟寺。在寺內，你必須啟動挑戰者之球，並消滅疑惑之煞。\n\n完成這項挑戰後回來找我，我會好好獎勵你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n英雄藏寶箱"}
MultiLanguageQuestData['tw'][31521] = {title = "成為大師", objective = "製作出黑胡椒鮮蝦肋排、海霧米粉、魔古燉魚、清蒸螃蟹、崇天春捲和瘋狂釀酒人的早餐，然後回去找廚藝鬼才。", description = "總有一天，你會精通我們教給你的所有技巧。到時候，就輪到你教導其他人了。當你發現自己精通了一切時，回來找我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31522] = {title = "夠格的挑戰:仇恨之煞", objective = "完成影潘僧院挑戰模式。", description = "<name>，我要你募集一支隊伍，並帶領他們前往影潘僧院。在僧院之內，你必須啟動挑戰者之球，並將塔蘭·祝救出仇恨之煞的掌控。\n\n完成這項挑戰後回來找我，我會好好獎勵你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n英雄藏寶箱"}
MultiLanguageQuestData['tw'][31527] = {title = "夠格的挑戰:織焰者喀格勒", objective = "完成血色大廳挑戰模式。", description = "<name>，我要你募集一支隊伍，並深入血色大廳。在大廳內，你必須啟動挑戰者之球，並阻止織焰者喀格勒的燒書行為。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n英雄藏寶箱"}
MultiLanguageQuestData['tw'][31528] = {title = "夠格的挑戰:黑暗院長加丁", objective = "完成通靈學院挑戰模式。", description = "<name>，我要你募集一支隊伍，並深入通靈學院。在學院內，你必須啟動挑戰者之球，並消滅黑暗院長加丁的邪惡存在。\n\n完成這項挑戰後回來找我，我會好好獎勵你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n英雄藏寶箱"}
MultiLanguageQuestData['tw'][31529] = {title = "任務:捕殺兔妖", objective = "殺死12隻簧尾兔妖。", description = "我被派來這個山谷，保護中央平原遠離任何潛在的威脅。\n\n我已確認一個高度優先的目標。簧尾兔妖鑽進了農地上方高處的山壁中。\n\n如果放任不管，牠們的數量會大幅增加，而且他們會設法跑到下方的田地裡去。\n\n必須消滅牠們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31530] = {title = "任務:猴人一籮筐", objective = "殺死12隻簧尾兔妖。", description = "自從我到達這裡之後，我就一直在監視猴人，而且我不喜歡我在他們營地中看到的活動。\n\n許多猴人借夜色的掩護從山上下來，到農場裡搶走補給品。\n\n我們必須阻止他們猖狂的竊盜行為。我之前削減過他們的數目，但只有一個戰士是不夠的。\n\n我需要你幫忙。盡你所能去殺光猴人吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31531] = {title = "任務:空中的威脅", objective = "殺死12隻峭壁鳶。", description = "我已確認另一個高風險的目標，大多數人都不會對那東西有所懷疑。\n\n峭壁鳶在東邊山丘上空盤旋，而且牠們非常危險。\n\n我曾看過牠們在沒人注意的時候，從空中突然飛撲下來，搶走農場上的穀物跟種子。\n\n為了保護農場，我們必須削減牠們的數量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31532] = {title = "任務:峭壁上的掠食者", objective = "殺死巨型峭壁鳶。", description = "今早我在山上進行例行巡邏的時候，我注意到一隻巨大的白鳥向下飛往農地。\n\n牠用爪子抓起了整隻犛牛，並消失在群山峭壁之中。\n\n今天是犛牛，明天可能就是農夫!\n\n我們必須殺了這隻鳥，免得牠再去尋找下一個受害者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31534] = {title = "初學者的啤酒", objective = "跟好漢‧泥爪取1顆湖生甜瓜，跟吉娜‧泥爪取1顆絨毛蜜桃，跟小魚‧跌蘆取1顆黑櫻桃，以及跟農夫老豐取1根紅色小蘿蔔。", description = "你能保守秘密嗎，<name>？\n\n我已經開始嘗試自己釀啤酒了。我只有這個老舊的手製蒸餾器，但它的功能還是很好。\n\n我有個新啤酒的點子，但我需要一些材料。\n\n想到要跟周遭居民打交道，我實在是害羞到不行，但我看過你跟附近的人做朋友。\n\n你願意跟那些農夫要一些我需要的材料嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31535] = {title = "補給食材室", objective = "將一包食材包帶去給年‧鐵爪。你可以使用商人老程販售的容器來創造一包食材包。", description = "人們從潘達利亞各地來向鐵爪家族學習烹飪。我們不僅以自己最頂尖的廚藝為傲，更因能將這身廚藝傳授給其他人而自豪。那就是我們的烹飪課收費這麼低的原因。\n\n但是，這代表著我們經常要面臨上課用食材短缺的困難。你願意捐獻一些食材給學校，幫助無力支付的學生嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31536] = {title = "保住新鮮", objective = "將空的虎肉籃子帶去給年‧鐵爪。", description = "要讓食材保住新鮮，就必須採用適當的保存方式。幸運的是，商人老程有在賣很好的保存容器。派你去做這麼微小的任務讓我很不好意思，但你能否幫我買幾個空的虎肉籃子？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][31537] = {title = "艾拉的味道測試", objective = "詢問『酒鬼』酒骨、波波‧鐵爪、農夫尹以及娜娜‧泥爪，他們對艾拉的酒有何看法。", description = "嗯，我終於釀出啤酒了，但除非有人喝過，否則我不知道這啤酒的味道如何。\n\n你能不能拿我的啤酒去給半丘的居民，聽聽他們的想法？\n\n我…我無法自己面對他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31538] = {title = "有價值的啤酒", objective = "要求老陳‧風暴烈酒嚐嚐艾拉的酒。", description = "還有一個最後的人選必須嚐嚐我的啤酒。\n\n我聽說他曾旅行到很遠很遠的地方，而且喝過全世界的酒。\n\n他現在正好在城裡，我想知道他認為我的技術如何。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31539] = {title = "美麗事物", objective = "製造一個受人委託的畫作並帶去翠玉林的落英園給水墨大師老魏。你可以在銘文學技能面板中的任務類別找到配方。", description = "我們居住在一個魔法世界裡。很少人有能力將這種魔法灌注到我們所製作的東西裡，賦予它們力量。這樣的東西十分珍貴。\n\n而更少的人，有能力創造出值得世代珍藏的東西，卻不是因為賦予了它力量，而是因為該樣事物的極度美麗。\n\n玉蛟寺給了我們這樣的任務，我相信你是我們之中最有資格的。你願意接受這項任務嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
MultiLanguageQuestData['tw'][31540] = {title = "天僧寺之杖", objective = "製作3支鬼鐵法杖和2支雨罌粟法杖。帶去翠玉林的落英園給水墨大師老魏。", description = "看來今年有很多武僧在天僧寺受訓。我們受託製作大批的長杖。而我說的大批，是真的很「大」一批。\n\n你能幫忙負責一部分嗎?我會很感激你的。當然，你也會獲得你那一份的報酬。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
MultiLanguageQuestData['tw'][31541] = {title = "玉石工藝", objective = "製作紋刻的翠玉盤並帶去翠玉林的落英園給水墨大師喬寶。你可以在銘文學技能面板中的任務類別找到配方。", description = "我們的時代裡有一位偉大詩人，名叫匡大師。他寫了一首極優美的詩，有名半丘的商人想把詩句雕刻在石頭上，展示在他的房子裡。她要求一名擁有優秀雕刻技能的人過去辦這件事。你願意接受嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
MultiLanguageQuestData['tw'][31542] = {title = "渲紅墨水", objective = "取得水墨大師葛林蘇所找尋色彩，需要一種不尋常的顏料。他的描述讓你聯想到了血的顏色，尤其是老虎血...\n\n製作5份渲紅墨水。你可以在銘文學技能面板中的任務類別找到配方。", description = "練習書法是潘達利亞的古老傳統。我正在寫一篇關於古代戰爭的文章，需要合適的墨水來完成這項工作。為了找到合適的色調，我翻遍了所有的地方，卻始終一無所獲。你能幫我想個方法，找到我所需要的顏色嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
MultiLanguageQuestData['tw'][31543] = {title = "畫像", objective = "為苟雅女士畫一幅畫並帶去翠玉林的落英園給水墨大師葛林蘇。你可以在銘文學技能面板中的任務類別找到配方。", description = "許多偉大的藝術品亦是偉大愛情的結晶。半丘的一位商人希望替他所深愛的妻子留一張肖像，作為祝壽的禮物。你願意接受這項工作嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
MultiLanguageQuestData['tw'][31544] = {title = "向死者致意", objective = "製作一顆銘刻的紀念石並帶去翠玉林的落英園給水墨大師喬寶。你可以在銘文學技能面板中的任務類別找到配方。", description = "萬物都有終結。就連好人的生命也不例外。崑萊那裡的一家人想為他們最近過世的大家長立一座紀念碑。你願意接受這項工作嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
MultiLanguageQuestData['tw'][31545] = {title = "精品", objective = "将指定的物品带给锦绣谷的潘达利亚财富社团的成员。", description = "潘达利亚财富社团想从像你这样技艺高超的珠宝匠手中购买一些精美的工艺品。我们将对这些物品进行分类，然后将切割最为独特的部分放入秘密宝库中；剩余部分出售给别人，以回笼资金。\n\n我们的最终目标是挑选一些稀世藏品，以备特殊活动之用。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n禪師級珠寶匠徽章"}
MultiLanguageQuestData['tw'][31548] = {title = "基礎訓練", objective = "在一場寵物對戰中獲勝。", description = "現在你已經是個寵物訓練師，是時候測試一下你的技能了！\n\n到山谷去挑選一隻戰寵，並與其交戰。獲勝之後就回來找我，我會繼續訓練你。祝你好運！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31549] = {title = "康復", objective = "去拜訪獸欄管理員謝爾比‧石火，以治療你的寵物並恢復其生命力上限。", description = "現在你在戰鬥中獲勝了，我們必須治癒你的寵物，好讓牠們還有能力再上戰場！去找我們當地的獸欄管理員謝爾比‧石火來治療和復活你的寵物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31550] = {title = "去抓一隻來！", objective = "抓一隻戰寵。", description = "目前為止你都做得很好，<name>。你自己都還沒發覺，你已經要變成一個寵物專家了。現在你該去為自己抓一隻專屬的寵物！\n\n回去找一隻戰寵，與牠交戰，並在牠生命力上限偏低時把你的陷阱丟出去。完成之後，把你抓到的東西帶回來給我看看。\n\n記住，你至少要有一隻戰寵達到等級3才能使用陷阱！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31551] = {title = "去抓一隻來！", objective = "抓一隻戰寵。", description = "目前為止你都做得很好，<name>！你自己都還沒發覺，你已經要變成一個寵物專家了。現在你該去為自己抓一隻專屬的寵物！\n\n回去找一隻戰寵，與牠交戰，並在牠生命力上限偏低時把你的陷阱丟出去。完成之後，把你抓到的東西帶回來給我看看。\n\n記住，你至少要有一隻戰寵達到等級3才能使用陷阱！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
