MultiLanguageQuestData['tw'][31609] = {title = "杉齊爾之怒", objective = "殺死阿寇隆、休斯席克、實體化的恐懼之煞，和25名螳螂人征服者來擊退螳螂人大軍。", description = "其餘重獲自由的聖螳散佈在恐懼之心各地，和螳螂大軍作戰。他們或許需要你的協助!", progress = nil, completion = "圍城部隊暫時被擊潰了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31611] = {title = "崑萊好勁道", objective = "保護酒月節。", description = "你看過酒月節嗎？\n\n濱南村的好傢伙們真是辦了一場了不得的宴會。而且今晚宴會要提供的啤酒非本人在下我的啤酒莫屬。\n\n我正在製作我著名的崑萊好勁道！\n\n你或許願意加入我們的宴會？這是一個完全放鬆的活動，而且絕對沒有任何危險。", progress = nil, completion = "我確實有可能低估了如今釀啤酒的安全性。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31612] = {title = "帝國的陰影", objective = "到卡拉西斐斯的殿堂中找『奪風者』基爾魯克。", description = "你對我們只有片面的了解。你是個外來人，也一直接受外來人的待遇。\n\n繼續對你保持秘密並不恰當。有些東西應當讓你看看。", progress = nil, completion = "&lt;基爾魯克奇怪地看了你一眼。&gt;\n\n或許卡拉西瓦永遠也不會真正接受你。他們的仇外思想讓他們無法接受一名有用的&lt;race&gt;。\n\n至於我，對於能和你並肩作戰感到很榮幸，&lt;class&gt;。你的存在，為我們帶來很大的榮耀。", rewards = "至高者徽印思緒清晰徽印毫髮無傷徽印奪風者徽印覓血者徽印您會收到：\n\n"}
MultiLanguageQuestData['tw'][31613] = {title = "烈性綠石酒", objective = "協助綠石村進行防禦。", description = "我正在製作一批我著名的烈性綠石酒。\n\n把這東西用來對付我們最近在礦坑看到的，那些又壞又淘氣的元素，一定會很暢快。\n\n這樣吧，你去集合一些你的朋友，然後把他們帶回來這裡試一回合。\n\n先到屋子的人贏！", progress = nil, completion = "我看到你好好利用了我的烈性綠石酒。幹得好，&lt;class&gt;！", rewards = "您會收到：\n\n"}
