MultiLanguageQuestData['tw'][31669] = {title = "捲心菜測試", objective = "在日歌農莊種植綠色捲心菜。你可以在半丘市集向商人青田購買種子。", description = "爺爺老是說，真正頂尖的農夫就看他捲心菜的品質來決定。每次有新農夫來到鎮上，他都會買幾顆捲心菜來檢驗他們有沒有知識。\n\n現在，輪到我成了新農夫，這是證明我自己的大好機會。你能幫我種一些捲心菜嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31670] = {title = "閒置的胡蘿蔔", objective = "在日歌農莊種植脆嫩多汁胡蘿蔔。你可以在半丘市集向商人青田購買種子。", description = "爺爺老愛說「胡蘿蔔只是引來兔妖的招牌。」我好像真沒看他種過半根胡蘿蔔。\n\n難得我這次不同意我爺爺的意見。我喜歡刺激的生活。而且，我很愛吃胡蘿蔔。\n\n你能弄些種子來，幫我種一些嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31671] = {title = "來點青蔥如何？", objective = "在日歌農莊種植青蔥。你可以在半丘市集向商人青田購買種子。", description = "我聽好漢提到他今天要種青蔥。我不確定今天是種青蔥的好日子，但我認為他應該知道自己在做什麼。畢竟，他是農夫工會的頭頭嘛。\n\n你能幫我種點青蔥嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31672] = {title = "南瓜香", objective = "在日歌農莊種植魔古南瓜。你可以在半丘市集向商人青田購買種子。", description = "我在市集上聽說吉娜‧泥爪最愛南瓜花的香味。或許，如果我在農場上種點南瓜，她就會更常過來拜訪一些。\n\n你能幫我種南瓜嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31673] = {title = "紅花蔥，你顛覆了鱷魚的世界", objective = "在日歌農莊種植紅花蔥。你可以在半丘市集向商人青田購買種子。", description = "爺爺跟我說過，花蔥的味道會讓鱷魚不敢侵入你的領土。他這話肯定有什麼道理…他老愛種花蔥，而我從來沒看過「任何一隻」鱷魚靠近他的農地。\n\n我們距離水邊頗遠…但我想小心駛得萬年船吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31674] = {title = "粉紅菜頭挑戰", objective = "在日歌農莊種植粉紅菜頭。你可以在半丘市集向商人青田購買種子。", description = "老丘爪跟我打賭，說我的土地種不出粉紅菜頭。\n\n我會讓他親眼瞧瞧。我的土地能種出那老傢伙這輩子所見過最大、最粉紅的菜頭！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31675] = {title = "白菜頭種植法", objective = "在日歌農莊種植白菜頭。你可以在半丘市集向商人青田購買種子。", description = "爺爺常跟我說「抽屜要收乾淨，泥土要更乾淨。」聽起來像個笑話，但其實很有道理。\n\n蔬菜通常會在土裡留下一點根，對土壤造成污染…但一根又大又肥美的白菜頭正好能解決這個問題。你能去幫我種一根菜頭嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31676] = {title = "遠古復仇", objective = "在葛薩恩臺地殺死6個復仇的葛薩尼之靈。", description = "我可以聽見他們的怒嚎…那些在久遠之前被我殺死的葛薩尼魔古。他們在這廢墟中遊蕩，尋求著復仇。\n\n以眼前的狀態，若被他們發現，我沒有力量能將他們擊退。去吸引他們的注意，放倒他們。\n\n完成我所起頭的工作，然後我會向你表明我的身分。", progress = nil, completion = "魔古是我們的共同的敵人。或許還有其他的。\n\n我們等著看。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31677] = {title = "督軍骨灰", objective = "把督軍葛薩恩的灰燼帶去卡拉西斐斯給『奪風者』基爾魯克。\n\n已提供物品：\n", description = "<『奪風者』基爾魯克曾在好幾世紀前擊敗督軍葛薩恩，但這名魔古獸王的靈魂還是在他過去堡壘的廢墟裡作祟。\n\n帶回你戰勝那個靈魂的證據，應該能讓你更進一步獲得卡拉西的青睞。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31679] = {title = "擴大涵蓋範圍", objective = "到珀光洞穴開啟共鳴信標。", description = "卡拉西瓦聽到了另一名聖螳的訊息。他的呼喊很微弱，散失在黑暗中。得把他的訊號強化才行。\n\n在琥珀之光洞穴裡有座沉寂已久的塔。必須讓它再次歌唱，這是卡拉西的旨意!\n\n這一次，我會和你一起。你要幫助我修復它。\n\n帶著這塊共鳴水晶，到琥珀之光與我碰面。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n卡拉西卡拉西"}
MultiLanguageQuestData['tw'][31680] = {title = "罪與罰", objective = "在尖刺小徑殺死8個琥珀收割者。", description = "尖刺小徑裡長有許多年輕的奇帕利樹。外來者，女皇過早抽取了裡面的樹液。必須等它們長成才能取走裡面的琥珀。\n\n卡拉西瓦要看到這種罪行得到懲罰!如果你能殺死那些伊克席克收割者，他們會很高興的。", progress = nil, completion = "卡拉西對我們的成果很滿意，外來者。事實證明，你比我們所想的更有用。", rewards = "您會收到：\n\n卡拉西"}
MultiLanguageQuestData['tw'][31681] = {title = "熟成", objective = "從尖刺小徑的琥珀收集裝置那裡取得7份沾滿膠凍的梳子。", description = "砍伐年輕的樹是種罪，但浪費琥珀的罪孽更重。\n\n青澀的琥珀沒那麼強力，但卡拉西需要它才能繼續戰鬥。我們要找來更多琥珀，讓他們對我感激不盡!\n\n去收集青澀的琥珀。我們會把它們儲藏起來，直到它們成熟並可食用為止。", progress = "我是想跟你去收集琥珀，但我的能力在這裡更有用。", completion = "就算是青澀的琥珀也有好處。這種時刻我們沒有挑嘴的餘地。\n\n卡拉西瓦會賞識我這種想法。我會跟他們提你幫上的忙!", rewards = "珀光墜盒珀光頸飾珀光項鍊珀光墜飾珀光護符您能選擇下列奬勵中的一個：\n\n恆龍寶箱\n\n您還會收到：\n\n珀光墜盒珀光頸飾珀光項鍊珀光墜飾卡拉西"}
MultiLanguageQuestData['tw'][31682] = {title = "海，永不復返", objective = "在被海水侵蝕的石頭上使用卡克西音叉，以喚醒聖螳。", description = "卡拉西瓦和我說過了，外來者。聖螳就躲在潮間帶裡，但他的行蹤已經暴露了。\n\n他被蜥蜴人給包圍。絕不能讓他落入他們長滿鱗片的手中。\n\n你要去找到他。喚醒他。帶著他一起回來!\n\n成功之後，卡拉西瓦會對我們感到很高興的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n卡拉西卡拉西"}
MultiLanguageQuestData['tw'][31685] = {title = "四風峽", objective = "傳送到四風峽並和士兵提姆‧P‧奧拉瑞談話。", description = "呀啊啊，翠玉林正在積極重建中，但四風峽那裡仍充滿了探險機會。準備好過去時就和我說，我有辦法送你一程。在另一邊和我的同僚講話，他會給你一些對旅途有幫助的裝備。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31687] = {title = "削弱西克席克", objective = "殺死12名西克席克螳螂人。", description = "我們花了那麼大力氣將螳螂人困在悚然荒野，但還是有一些穿過了防線，可能是要去怒兆寺。我的人一直試著在西邊的席克斐斯消滅他們，但都無法成功。如果你這位<class>有像塔蘭所描述的一半厲害，或許你能獲得更大的成果。\n\n到西邊去，殺死你所找到的每一個西克席克螳螂人。要記著，這不是心軟的時候。怒兆寺裡人們的性命仰賴著我們。", progress = nil, completion = "螳螂人是殘酷的。幸運的是，你的專注奉獻超越他們的殘酷。\n\n有你在這裡真好，&lt;class&gt;。", rewards = "西克席克墜盒橡樹皮頸飾任賽項鍊十字路口墜飾看守站護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][31688] = {title = "搜尋靜不下來的連格", objective = "在西克席克牢籠中搜尋靜不下來的連格。", description = "我最好的一名斥候，靜不下來的連格，在席克斐斯另一側執行任務時失蹤了。我希望他只是被抓到而非被殺死了，但螳螂人被煞污染得這麼嚴重，這種可能性很低。\n\n但是，你能去調查席克斐斯周圍的牢籠嗎？我欠他比這更仔細的搜查，但我分不出人手，否則我們的南部邊界肯定會崩潰。\n\n拜託，<class>，就算他已經死了，至少找到他，讓我知道他的命運。", progress = nil, completion = "連格跟我講述過你的英勇。他欠你的情，我也是。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31689] = {title = "懼誓螳戰士", objective = "在奇帕利沃爾殺死6名弗爾席克懼誓螳戰士。", description = "卡拉西的耳目無遠弗屆。他們和我分享了他們的知覺。\n\n弗爾席克投靠了煞，這個荒謬的蟲群利用這種力量來支持他們的進軍。他們的戰士吞食被污染的琥珀，自稱為懼誓螳戰士。\n\n他們沒有未來。他們是該被處理的垃圾。\n\n而你，要在抵達奇帕利沃爾時替我們開始這項工作。", progress = nil, completion = "在訓練有素的手中，這矛是完美的武器。只有弱者會去用巫術強化它。\n\n而我們不需要弱者。", rewards = "您會收到：\n\n恆龍寶箱卡拉西"}
MultiLanguageQuestData['tw'][31690] = {title = "銘刻白虎法杖", objective = "將你的銘刻白虎法杖帶去落英園給水墨大師葛林蘇。", description = "儘管它很強大，但你知道有一天你會超越這柄法杖。到那時候，落英園裡的一名水墨大師會十分樂於從你手上接過它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
MultiLanguageQuestData['tw'][31691] = {title = "銘刻紅鶴法杖", objective = "將你的銘刻紅鶴法杖帶去落英園給水墨大師喬寶。", description = "儘管它很強大，但你知道有一天你會超越這柄法杖。到那時候，落英園裡的一名水墨大師會十分樂於從你手上接過它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n智慧卷軸"}
