MultiLanguageQuestData['tw'][31694] = {title = "Hisingen Blues", objective = "test log desc ! 5 [Marcio's Test Ninja] [Marcio's Test Ninja] 5 test cona [Marcio's Test Ninja] fodasse $o1x caracois $o1 crl\n\n*DO NOT LOCALIZE*ass", description = "test desc! $1oa $1oo $1oo $1oa test cona $oo fodasse $oa caracois $1ox $9o crlaasd\n\n*DO NOT LOCALIZE*asd", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31695] = {title = "長城之外", objective = "到螳螂荒原的長陰哨站找塔蘭‧祝。", description = "我們收到消息，影潘開始朝螳螂荒原推進反擊了。聽起來他們在追查這次揚古入侵的根源。\n\n熊貓人已有好幾千年不曾組隊進入螳螂荒原。影潘強大且勇敢，但他們也很高傲，人數很少。他們會需要像你這樣的英雄協助。你能穿過冬綻西北邊的關口嗎？能找到影潘領導者，向他提供你的協助和經驗嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31698] = {title = "削減數量", objective = "殺死8隻嘯風虎或嘯風原生猛虎。", description = "過去的幾個季節都是豐收，也因此，嘯風島上野生老虎的數量大爆炸。\n\n這些野蠻的生物將附近的獵物殺得精光，還開始侵犯雲蛟的巢。\n\n老虎興盛的結果，就是雲蛟的消減。\n\n如果我們不小心處理，這些貓科掠食者可能會將雲蛟消滅殆盡。\n\n我們必須削減老虎的數量，<race>。", progress = nil, completion = "你完美達成了任務，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31699] = {title = "妖精的恐怖", objective = "殺死7隻暗影妖精欺詐者。", description = "喔老兄，這下我要怎麼完成任務?\n\n講師天刺要我去嘯風島上殺一些老虎，但我聽說那塊區域裡到處都是妖精在肆虐!\n\n呃!我恨透了妖精!他們讓我不寒而慄!\n\n他們是那麼小，而且...而且...他們會跳到你身上然後...然後...他們有又冷又像小牙簽的死亡之手!\n\n啊啊啊!你一定得幫我，<name>。把那些東西解決掉，拜託!", progress = nil, completion = "你給了那些妖精應有的教訓，&lt;name&gt;。他們應該暫時無法製造問題了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31700] = {title = "鞋子在另一隻腳上", objective = "偷回14雙被偷走的長靴。", description = "你知道我有多討厭妖精嗎?有一次，那些該死的小妖怪整天跟著我，在我的茶裡加土，頭髮裡放蟲子。\n\n什麼東西會喜歡做這種事啊!?\n\n好吧，我想是報復的時間到了。你知道嘯風島上的妖精最喜歡的是什麼嗎?\n\n鞋子!\n\n所以我們要去偷鞋。讓他們抓狂!哈!\n\n好吧，我不敢接近妖精，所以這項工作就交給你了，<name>。", progress = "你有看到他們的表情嗎?他們有沒有很抓狂?", completion = "看來你和寧葛娜在做調皮搗蛋的勾當。不幸的是，雲蛟衛對這種行為絕不寬恕...\n\n等等，你在哪找到那些鞋子的?我找我這雙驢皮馬靴找了幾百年了!\n\n好吧...我想我會放過你們一次...就這一次。咳嗯。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31701] = {title = "黑暗雌獵虎", objective = "殺死嘯風雌獵虎。", description = "我得知有關一隻凶惡野獸的事，一隻嘯風雌獵虎，正在島的西北方肆虐。\n\n她已經殺了幾隻雲蛟，還傷了幾名過去制服她的蛟騎士。\n\n必須除掉她，以免她對其他人造成危害。你能完成這項任務嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31702] = {title = "潛行", objective = "殺死嘯風劍齒虎。", description = "我已經聽說有隻白色的大野獸潛伏在野生雲蛟島上西北方的樹林。\n\n這隻野蠻的生物是嘯風雌獵虎的配偶，牠已經殺害好幾個成年的雲蛟族母。\n\n我們不能讓這麼恐怖的掠食者肆無忌憚地在島上遊盪。\n\n去把這個傢伙解決掉。讓我們看看你的訓練是否有所成果。", progress = nil, completion = "看來你消滅了那隻野獸。你是個很有前途的弟子。真的!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31703] = {title = "狂妄者的傷害", objective = "殺死暗影妖精狂菇。", description = "我還有另一項任務要交給你。\n\n森林妖精的領導者就是暗影妖精狂菇。\n\n如果釀酒出了麻煩，他就是幕後搞鬼的主腦。\n\n我們沒有時間去應付妖精無止境的惡作劇和無禮。把暗影妖精狂菇解決掉。儘快。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31704] = {title = "便便", objective = "收集5小袋便便。", description = "<你的蛟注意到你的眼神，害羞地把頭藏了起來。>\n\n你敢說，肯定是有人跑出來做了什麼「好事」。\n\n好吧，最大的可能性就是蛟寶寶吃了什麼東西，然後那個東西從身體另一邊出來了...留在某個地方。\n\n你最好在蛟大師發現之前找到蛟寶寶的便便。", progress = "<蛟寶寶無辜地看著你。>", completion = "蛟龍寶寶滿足地玩耍，完全遺忘你的努力。唉...有時候，蛟龍訓練師的生活缺了一點感恩。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31705] = {title = "別刺我", objective = "在落英園的北邊林地使用蜂蜜，然後殺死果園刺蜂。", description = "落英園是我們的家，我們養育年輕蛟龍和訓練弟子的避風港。\n\n不幸的，還有其他更危險的生物想要來這裡定居。\n\n在北邊，河的另一邊，我們看到有個巨大的黃蜂在花間採蜜。\n\n這傢伙已經螫昏我們好幾個弟子了。\n\n用這個蜂蜜將黃蜂釣出來。然後在牠傷害任何其他人之前摧毀牠。", progress = nil, completion = "那隻毒蜂死了嗎?很好。這麼多弟子都失敗的任務，你卻成功了，&lt;name&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31706] = {title = "哭泣寡婦", objective = "殺死7隻哭泣寡婦。", description = "斯里拉村附近的蜘蛛變得非常有侵略性。他們對在海岸邊釣魚的釣手隊造成很大的困擾。\n\n為了他們的安全，我需要你過去消滅寡婦之嚎裡的哭泣寡婦。\n\n你可以在北邊的海岸旁找到那個洞穴。", progress = nil, completion = "講師天刺跟我講過寡婦之嚎的現況了。你做得很好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31707] = {title = "糾纏的網", objective = "摧毀寡婦蛛網來拯救5名斯里拉村民。", description = "斯里拉村那裡的釣手傳來令人困擾的消息，<name>。\n\n村裡有許多人失蹤了，被住在寡婦之嚎的蜘蛛給抓走了。那是海岸北邊的一個洞穴。\n\n被害者被拖進黑暗的深淵，被絲包裹成繭，等著成為蜘蛛的下一餐。\n\n我們相信其中有些人或許還活著。還有時間拯救他們!我需要你過去盡量救援你所能找到的村民。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31708] = {title = "蛟龍之鱗", objective = "收集25份蛟龍之鱗。", description = "我看到你有了自己的蛟寶寶，<race>。\n\n你有沒有好好餵牠吃東西、幫牠清理，陪牠玩?只有這樣做，才能讓牠長得強壯又健康。\n\n讓我告訴你一個訓練師的秘密。在北邊的寡婦之嚎裡，你可以找到名叫蛟龍之鱗的一種香菇。\n\n它很難取得，但這種香菇有很強的效力和重要的營養。你的蛟龍不會喜歡吃，但話說回還，有誰喜歡吃菜呢?", progress = "<你的蛟龍開心地歡迎你。>", completion = "&lt;你的蛟聞了聞香菇，露出嫌惡的表情。牠試著逃跑，但你溫柔地按著牠，哄牠一點一點把它們吃下去。&gt;", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31710] = {title = "风味美食", objective = "收集100只小蜘蛛眼。", description = "当你走近时，你的翔龙张着嘴巴开始流口水了。自从你上次离开后，小家伙变得非常饥饿。\n\n从它不停啜泣和拍打小尾巴的动作来看，小家伙不想随随便便填饱肚子，而是想来点比较特别的美食。\n\n你的翔龙喜欢嚼小蜘蛛眼，但这东西只有小寡妇蛛身上有，沿着海岸线向北可以找到洞穴。\n\n那么，你还在等什么呐？赶紧出发吧。", progress = "你的蛟為你的歸來而開心。", completion = "你的蛟親暱地蹭著你的手，然後開始吞吃點心!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31711] = {title = "疑惑之種", objective = "殺死疑惑之種。", description = "聽好了<race>，疑惑之煞的麻煩處，就在於它散佈欺詐的能力。\n\n一旦種下了疑惑的種子，它就會像雜草一樣滋生。\n\n這樣的種子已被種在北邊的寡婦之嚎。就像對付雜草一樣，我們必須立刻消滅它的存在。\n\n我需要你去摧毀殘餘的疑惑碎片，以免它找到更多受害者。", progress = nil, completion = "做得好，&lt;name&gt;。我「懷疑」這個敵人是否真的離去了。直到得以確定之前，我們必須保持警醒。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31712] = {title = "頑皮猴", objective = "殺死13名烏納猴人。", description = "斯里拉村那裡傳來奇怪的故事。\n\n看起來猴人部族似乎在那漁村南邊海岸的烏納卡古洞窟裡過得很舒服。\n\n實際上，恐怕太舒服了。那部族的猴人在整條海岸線上偷搶拐騙。\n\n我們得給他們一個教訓...只能用武力達成的教訓。他們受招待的時光已經結束了。", progress = nil, completion = "猴人的存在相當令人困擾。你將講師天刺的任務辦得很好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31713] = {title = "酒好笑", objective = "收集100份斯里拉烈酒。", description = "真是災難啊，<name>!\n\n昨天，當我去舞龍客棧光顧的時候，他們的酒竟然賣完了。說是來自斯里拉村的船貨被偷了!\n\n看來烏納猴人在碼頭那裡製造了各式各樣的麻煩。甚至把酒搶去他們海岸邊的烏納卡古洞窟裡。\n\n沒酒喝我可受不了。沒有酒的日子根本不算活著!\n\n誰可以過去把酒救回來!", progress = "酒找到了嗎?我...我快不行了...", completion = "喔，感謝風暴烈酒!你是我的英雄!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31714] = {title = "拯救蛟龍", objective = "收集10隻被拯救的蛟龍。", description = "那些烏納猴人幹得太過分了。\n\n你知道他們對雲蛟做了什麼嗎?抓走小雲蛟，強迫牠們互相爭鬥，就只為了他們的娛樂。\n\n這些野蠻人!\n\n如果年輕的蛟龍在小時候學習到這種侵略性行為，長大後或許會變得暴戾又腐化。凶惡的雲蛟絕不是我們想料理的東西。\n\n我們必須拯救那些蛟寶寶。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31715] = {title = "大烏納", objective = "殺死烏納領主。", description = "烏納猴人的領導者是個名叫烏納領主的強盜。\n\n我曾聽說這個肆虐海上的恐怖船長和他的船員。他與他部族所到之處，帶來的都是毀滅。\n\n烏納將船隻停靠在富饒的土地，掠奪當地的村莊，在離開前吸乾土地的所有價值。\n\n我們絕不能容許同樣的事情發生在我們的海岸上，更不能發生在我負責守衛的時候。\n\n我需要有人過去消滅他。", progress = nil, completion = "他們的領導者死了?很好。或許這樣一來，那些猴人就不會去招惹村民了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31716] = {title = "便便", objective = "收集5大袋便便。", description = "<當你走近獸欄，那蛟龍縮進角落躲了起來。>\n\n他用羞澀的眼神看著你，你敢說，肯定是有人跑出來做了什麼...好事。\n\n好吧，最大的可能性就是蛟龍寶寶吃了什麼東西，然後那個東西從身體另一邊出來了...留在某個地方。\n\n你最好在蛟龍訓練師發現之前找出蛟龍寶寶的便便並且清理掉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31717] = {title = "训练师的试炼：王牌飞行员长爪", objective = "和王牌飞行员长爪谈一谈，然后击败他。", description = "你把我们弟子的水准又提上了一个新台阶，<name>。\n\n就像一把宝剑需要千锤百炼，我们的弟子也得互相挑战，获取实战经验。\n\n今天，你将和我们中最出色的一名弟子——王牌飞行员长爪进行对决。要想击败他，你得好好利用你的防守能力。\n\n去训练之环和他谈一谈，开始挑战。祝你好运。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31719] = {title = "训练师的试炼：宁纳·黑轮", objective = "和宁纳·黑轮谈一谈，然后击败她。", description = "你天赋异禀，<name>。但天赋这东西一旦失去了戒律和谦卑的支撑，就会变得不堪一击。\n\n今天，你将面对的是宁纳·黑轮。她的天然优势使她成为了我们这里最具天赋的弟子之一。\n\n要想击败她，你就得严格把控自己。\n\n去训练之环和她谈一谈，开始挑战。祝你好运。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31720] = {title = "訓練師挑戰:甜心舒琦", objective = "和甜心舒琦說話，然後擊敗她。", description = "今天，你要在訓練場上面對甜心舒琦。儘管她很甜美，她仍是個難纏的對手。\n\n她的攻擊迅速而精確，但這麼強大的攻擊，會隨著時間流逝而漸漸減弱。\n\n你需要趁她虛弱時一口氣造成傷害，才有辦法擊敗她。\n\n和舒琦說話來開始挑戰。祝好運。", progress = nil, completion = "你的專注力十分出色，&lt;name&gt;。做得好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31721] = {title = "訓練師挑戰:魁羅‧白眉", objective = "和魁羅‧白眉說話，然後擊敗他。", description = "魁羅‧白眉通常被視為雲蛟衛最好的學生。\n\n他似乎沒有什麼弱點。他聰明機智，力量強大，堅忍務實，且極具天賦。\n\n當你在訓練場上面對他時，你將面對我們最強弟子的考驗。\n\n和他說話來開始對決。不論結果如何，你都能從挑戰他的過程中學到許多。", progress = nil, completion = "你的技巧十分傑出，&lt;name&gt;。當看到像你這麼有前途的弟子，我由衷地覺得雲蛟衛後繼有人了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][31723] = {title = "四風峽", objective = "在四風峽和士兵提姆‧P‧奧拉瑞談話。", description = "呀啊啊，翠玉林正在積極重建中，但四風峽那裡仍充滿了探險機會。想過去探索的話，我有辦法送你一程。務必看看我們這裡一些或許對你旅途有幫助的裝備。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31724] = {title = "王老先生", objective = "在寵物對戰中擊敗王老先生。", description = "以新手來講，你還真強啊！\n\n我所有關於戰鬥的知識都來自於王老先生。和他戰鬥對你來說應該是很好的經驗！\n\n他就在通往西部荒野的橋另一端。別被他的年紀給騙了，他已經打敗過好幾個像你這樣的新訓練師了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31725] = {title = "林塞", objective = "在寵物對戰中擊敗林塞。", description = "你準備好展示你的能力了嗎？在赤脊山有個真的深具實力的小女孩。\n\n到止水營地的碼頭尋找林塞。她或許很年輕，但她出色的紀錄不容小看！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31726] = {title = "艾里克‧戴維森", objective = "在寵物對戰中擊敗艾里克‧戴維森。", description = "我的朋友都在談論暮色森林那裡的一個名叫艾里克‧戴維森的恐怖狼人。據說從來沒有人能打敗他的寵物。\n\n我敢說，如果你能打敗他，或許人們會改開始談論你！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31727] = {title = "賭注的問題", objective = "到悚然荒野的濕佬的賭注找甲板長艾利。", description = "想贏得這場戰爭，我們就不能忽略任何細節，外來人。\n\n在海岸邊有個必須深入調查的麻煩。那裡有不屬於我們族類的存在，而且對我們毫無益處。然而，他們的補給將是相當珍貴。\n\n如果裡面有任何資源是我們可利用的，我們就必須趕在女皇之前取得。", progress = nil, completion = "所以，那些蟲子對我們感興趣？好吧，如果他們想要我們的東西，他們就得親自過來這裡賺！\n\n這裡沒有白吃的午餐。你也是一樣！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31728] = {title = "比爾‧圓盾", objective = "在寵物對戰中擊敗『海盜』比爾。", description = "我在荊棘谷海角的老朋友、同僚訓練師，也是臭名遠播的酒鬼『海盜』比爾，對所有具備實力的訓練師提出公開挑戰！\n\n你應該回應他的挑戰，好好測試一下你的能力。他總是走在海角南部的道路上。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31729] = {title = "史蒂芬‧李斯本", objective = "在寵物對戰中擊敗史蒂芬‧李斯本。", description = "如果你覺得我已經很強了，做好心理準備吧。前方的路只會越來越艱難。\n\n你會發現史蒂芬‧李斯本在北荊棘谷的南部道路上行走。找到他，看看誰才是更優秀的寵物訓練師！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31730] = {title = "不是很友善的要求", objective = "到悚然荒野的釀酒園找樹汁大師老余。", description = "斥候報告，在柯爾斐斯附近有不是螳螂人的存在。通常，他們侵入和劫取琥珀的行為會很快被制止，但我們的部隊必須前往其他地方。\n\n你似乎很適合這項任務，喚醒者。你要去說服他們離開這片土地，否則你就會以卡拉西瓦之名摧毀他們。", progress = nil, completion = "所以他們希望我們離開？多麼自私的要求！我們不過是取了一棵樹上的琥珀。\n\n嗯，我哪裡也不去！我還得釀酒。\n\n如果你幫助我們，或許我們能達成一項互惠協議。我會給他們一些酒，而他們停止試著殺了我們。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31732] = {title = "獄火降臨", objective = "駕駛天火旋翼機來殺死60名卡爾洛夏士兵，並摧毀8台卡爾洛夏伐木機，然後擊沉刃拳收割者和冥痕。", description = "我絕對不允許部落在我們之前搶占這片海岸！如果你打算參戰，我可以分一台跑道盡頭的旋翼機給你。攻擊航程已經設定完畢，你只需要專注在射擊上就好。\n\n讓那些部落嚐嚐地獄火的滋味！", progress = nil, completion = "用來歡迎部落來到這片新土地正剛好！", rewards = "蘇利的接線小刀飛船海員狙擊步槍路障突破者鬥棍斬霧者之杖天空法師之杖神秘永恆運動之錘天火號醫護兵法杖突擊隊戰斧羅傑斯船長文雅敲擊手杖天火號士兵釘錘您會收到：\n\n蘇利的接線小刀飛船海員狙擊步槍路障突破者鬥棍斬霧者之杖恆龍寶箱"}
MultiLanguageQuestData['tw'][31733] = {title = "著地", objective = "使用天火號降落傘來降落在卡爾洛夏海岬，然後去找『醃漬王』蘇利‧麥拉利。", description = "他們的城鎮陷入火海，他們的人四散奔逃。我需要每個有戰鬥能力的人立刻到地上把他們解決掉。\n\n快點到船尾巴抓一包降落傘跳下去!", progress = nil, completion = "也該是你出現的時候了，小子!來搞點破壞吧!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31734] = {title = "歡迎車隊", objective = "使用蘇利的信號槍摧毀5台部落戰車。", description = "你有看見那些戰車的尺寸嗎？他們裝上了這麼多的爆裂物，我都不知道部落是打算佔領這塊大陸還是要把它整個炸沉到海裡！\n\n我們得在他們離開卡爾洛夏海岬之前摧毀那些戰車。\n\n來，帶我的信號彈去。把它發射到一台戰車裡，準備欣賞煙火表演！", progress = nil, completion = "解決掉那些戰車後，我們就能把注意力集中到指揮官身上。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31735] = {title = "合適的工具", objective = "使用蘇利的信號槍來清除路障，並在碼頭後方面對加楚爾。", description = "我偵察了整個區域，並沒有發現王子或是泰勒上將的線索。我們得儘快佔領這座基地，並在別處開始搜尋。\n\n一個名叫加楚爾的獸人術士負責指揮這裡的任務。他在碼頭周圍設下路障，打算透過一個惡魔法陣來逃走。\n\n再次利用那把信號槍，把那些路障給轟爛！我會在後面掩護你，並在你逮到加楚爾時參戰。", progress = nil, completion = "我們會抓到他的。我肯定。", rewards = "支配權皮甲外套支配權鍊甲護甲支配權絲質長袍支配權緞質長袍支配權皮長袍支配權環甲護甲支配權光潔護胸支配權裝甲護軀支配權重型護軀您會收到：\n\n"}
MultiLanguageQuestData['tw'][31736] = {title = "聯盟特使", objective = "找到坡東村的領導者並與之會面。", description = "在這基地北方有個櫻花果園，果園後還有一座村莊。我們得在那裡留宿並治療我們的傷患，同時計畫我們的下一步。\n\n到那座村莊去，和當地的領袖聯繫。密西卡探員和我會在那裡和你會合。\n\n記得要有禮貌一點，<name>！我授權你代表整個聯盟。\n\n我想，能和像你這樣強大的聯盟英雄會面，應該能達成一些好的印象。", progress = nil, completion = "迷霧消散時，我們知道有訪客前來只是時間早晚的事。\n\n但我們沒預料到會是這樣的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31737] = {title = "戰爭的代價", objective = "在卡爾洛夏海岬殺死10隻鬼煞和5隻先驅煞。", description = "這整個地方都著火了，根據天火號的報告，有更多那種...暗影...爬出地面。得把我們的人帶離那裡才行。\n\n往北方的基地方向清出一條路來。我會和你在那裡會合。", progress = nil, completion = "很高興你為自己負起責任。若不處理，負面情緒很快就會淹沒這裡的每一個人。就像它們開始淹沒你稱為「瑞爾」的那個人一樣。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31738] = {title = "劫掠農奴", objective = "殺死12名雙石監工或雙石苦工。", description = "我的村莊為什麼成了戰場？\n\n在西邊，你的部落敵人砍倒了我們珍貴的果園。少了我們的蘋果樹，我們就沒有收成，沒有食物，沒有生計。\n\n如果你真的和部落有所不同，表現給我們看！幫助我們保衛我們的林地，殺死那些褻瀆土地的人。", progress = nil, completion = "我們的果園是村莊最大的資產。你保住了我們的收成，我們真的很感激。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31739] = {title = "優先事項！", objective = "收集6份蘋卉酒。", description = "那些叫「獸人」的東西洗劫了酒坊，帶走了好幾桶我們家最上等的蘋卉酒。\n\n我知道現在正在打仗，但我可不是那種能坐視心血結晶被人用下流的嘴巴啜飲的那種釀酒師。\n\n這個「部落」想必會有所抵抗。你何不好好利用你那把武器，幫我找回我的蘋卉酒？", progress = nil, completion = "看來你們兩個忙了很久。謝謝你找回了我們的酒。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31740] = {title = "寇寇之怒", objective = "殺死寇寇。", description = "我們得擔心的可不只是地窖而已。\n\n我深愛的牡山獸寇寇發瘋了！看看牠！\n\n我試過哄牠，求牠，吼牠還有安撫牠，但全部都沒效。\n\n我害怕牠已經喪失心智了。眼前只剩下一個解救牠和我們酒坊的方法。\n\n迅速確實地給牠一個了斷，別讓牠再繼續受苦。", progress = nil, completion = "謝謝你幫助了釀酒人，還有告訴我這個消息。\n\n根據你所說的，聽起來寇寇是被某種黑暗能量感染了。難道是…？\n\n不。這不可能。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31741] = {title = "雙石要塞", objective = "在雙石要塞殺死15名部落的士兵。", description = "我不信任這個部落。他們使用汙穢的魔法，顯然也沒安好心眼。我們不能再容許他們待在雙石要塞，那裡距離坡東村太近了。\n\n拜託你，在他們對這村子做出可怕的事之前，削減他們的數量。", progress = nil, completion = "你讓這裡變得血流成河了，孩子。\n\n幹得好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31742] = {title = "破敗的部隊", objective = "殺死道爾甘和貝爾安德拉‧魔風。", description = "部落為我們省下了不少功夫。他們的內鬥和分裂讓他們分散成兩個營地:西邊的獸人和東邊的不死族。\n\n獸人們遵循他們指揮官道爾甘的命令，不死族則追隨貝爾安德拉‧魔風，一名強大的術士。幸運的話，他們的內部爭鬥能分散他們的注意力，讓你有機會潛進那裡，殺死這兩個人。蘇利已經滲透到廢墟裡，完成後找他回報。", progress = nil, completion = "漂亮的擊殺，&lt;class&gt;。\n\n好了，解決掉這兩傢伙後，就只剩下我背後大廳裡那個大傢伙了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31743] = {title = "開火的信號", objective = "使用聯盟信號彈召喚對彈藥堆、雙石要塞石毀車、狂野小鬼和戍達迦的空襲。", description = "蘇利在北邊偵察到部落的基地，他還說他們帶了一大堆的爆裂物，和一小隊的石毀車。更別提他們術士所召喚的惡魔了。\n\n幸運的是，我們有所準備。我們有天火號的空中火力支援。我們只需要將攻擊信號傳給我們的飛行員。\n\n<瑞爾交給你一支煙霧信號槍，對你點頭示意。>", progress = nil, completion = "我的空軍小子們很有勁吧？哈哈哈！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31744] = {title = "不公平的交易", objective = "殺死在雙石要塞負責看守的惡魔眼球來解放8名被俘虜的幼小熊貓人。", description = "儘管我們遇到彼此不久，但我們擁有共同的敵人。這個所謂的「部落」。\n\n幾天前，他們的領導者提出和我們交易的要求。我們拒絕之後，他的手下綁走了我們的孩子，作為談判籌碼。\n\n我們已經向影潘請求協助，但他們在崑萊峰，過來這邊要花上好幾天。你能幫助我們嗎？", progress = nil, completion = "啊，我也看到過那些小傢伙。上來的路上解救了幾個。\n\n你做得很好，小子。這些孩子或許會做惡夢，但他們會平安長大的。多謝你了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31745] = {title = "向前也向內", objective = "到翠玉林的坡東村找上將羅傑斯。", description = "「煞」能量是嗎?千萬小心，<name>。在這大陸上有著潛藏的黑暗。\n\n我們會留在後方收拾殘餘的部落士兵，但我們需要你進行主要任務:解救泰勒隊長，找回安杜因王子。\n\n我們的空軍斥候在坡東村發現了旗艦的殘骸。過去那裡向上將羅傑斯報到，接受進一步指示。\n\n你可以隨意使用我的旋翼機。", progress = nil, completion = "做得很好，&lt;class&gt;。我能了解為什麼你能得到這麼高的評價。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31752] = {title = "布靈登4000型", objective = "我樂於給你這份禮物，<race><class>。根據我的測定，這會引起快樂和感動的情緒。\n\n祝你順心。您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n布靈登4000型禮物包"}
MultiLanguageQuestData['tw'][31754] = {title = "砲火", objective = "摧毀7座嘯天火砲。", description = "黃金階梯上的那些魔古大砲在對我們做長距離轟炸。如果那些大砲不知怎麼壞掉了，那該有多好啊，你不覺得嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31755] = {title = "残暴行径", objective = "营救5名金莲卫士或雾临村民。", description = "我能听到那些被俘的战士和村民们发出来的哀号，就在金色阶梯那里。魔古族正在折磨他们！\n\n求求你，快去救救他们！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31756] = {title = "阻止风暴", objective = "摧毁引风杖。", description = "金色阶梯上的魔古族正试图通过法术引来一场风暴。可想而知，魔古族和风暴结合在一起，可不是什么好事。要我说我们得阻止他们。\n\n通过那些引风杖所散发出来的巨大电弧，你应该很容易就能找到它们。能不能帮我去毁掉它们？回头我肯定能睡个好觉了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31757] = {title = "靈魂暴走", objective = "殺死12個被釋放的靈魂。", description = "嘯天魔古派出他們所捕捉的受苦靈魂來對付我們。他們從黃金階梯一湧而下，一望無際。\n\n盡力殺死這些靈魂。他們很脆弱，但若你不注意，他們會輕易將你淹沒。\n\n祝好運。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31758] = {title = "爛偵查", objective = "拯救勞·軟足。", description = "勞·軟足在黃金階梯那邊被抓住了。我不想幫他找藉口，他真是個爛盜賊。\n\n但我們應該不能就這樣把他留在那裡吧。你能去找他嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31760] = {title = "先发制人", objective = "阻止魔古族启动韶天巨兽。", description = "魔古族正在金色阶梯上启动某种石像巨兽。毫无疑问，他们想拿它来对付我们。\n\n不如你去跟他们“表达”一下我们的态度？要确保我们的观点直击要害。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31762] = {title = "岩石巨獸", objective = "殺死嘯天巨獸。", description = "魔古成功地驅動了一座巨大的岩石雕像，並派它來對付我們。\n\n作為反制，我打算派你去對付它。\n\n它正從黃金階梯那裡逼近。把它解決掉...您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31765] = {title = "血流成河！", objective = "使用砲艇砲台殺死80名雷鳴要塞士兵，和摧毀9座雷鳴要塞砲台。", description = "他們射中了我們的引擎，於是我們只能漂浮在這裡。這裡！就在敵人火線的中心！\n\n你知道該怎麼做，<name>。到甲板底下，登上砲座！\n\n讓這些雜碎知道，是他們跑到了我們的火線中心！", progress = nil, completion = "部落的優勢火力發揮作用了！\n\n…你做得還不錯啦。", rewards = "降落傘繩索分割刃備用的砲艇大砲索地者鬥棍迷霧領航者之杖轟天雷之杖風暴召喚者戰棍壕溝醫護兵法杖卡爾洛斯先鋒戰斧砲艇軍械庫巨斧您會收到：\n\n"}
MultiLanguageQuestData['tw'][31766] = {title = "落地", objective = "使用垂降繩索來垂降到地面。", description = "納茲格寧姆擔任地面襲擊行動的指揮，並要求你立刻過去和他會面。\n\n在砲座附近設有幾條垂降用的繩索。這會是你所能找到最快，也最不會出差錯的方式了。", progress = nil, completion = "你來了！\n\n我都開始擔心我們得衝進去自己享受所有的樂趣了呢。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31767] = {title = "解決他們！", objective = "殺死15名雷鳴要塞士兵。", description = "我們已經削弱他們，現在該解決他們了！\n\n務必將那座堡壘中的聯盟清理乾淨，我們沒有收容俘虜的空間。\n\n<納茲格寧姆露出示意的微笑。>\n\n你知道該怎麼做的，<name>。那些懦夫一有機會就會逃跑。\n\n別給他們機會！", progress = nil, completion = "做得好，&lt;class&gt;！我們打敗他們了！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31768] = {title = "火是唯一的解答", objective = "摧毀10份雷鳴要塞軍需品。", description = "光是摧毀他們的部隊還不夠。別留下任何東西給他們！\n\n用這把信號槍燒毀他們的彈藥堆。一點東西都不留！", progress = nil, completion = "哈哈！做得好，&lt;name&gt;。\n\n別留給他們任何東西！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31769] = {title = "最後一擊!", objective = "在雷鳴要塞殺死多倫隊長。", description = "根據情報，他們的隊長躲在重重障礙之中。\n\n那個懦夫躲避我們的怒火，坐看他的部隊為他而死!典型的聯盟!\n\n無所謂。他再也無法延後他的命運了。\n\n我會派我的陸戰隊去掃蕩城牆，你則去對坡道發動正面攻擊。對路障附近的彈藥使用信號槍來炸出通路。\n\n我們會和你在上頭會合，並合力摧毀這個可悲的隊長!", progress = nil, completion = "空軍基地，這麼長時間，他們在這裡有個秘密空軍基地!早知道的話，我就會派更多人到砲塔那裡，我就會 - 呃啊啊 - \n\n&lt;納茲格寧姆臉上的血色消失了，他的身體開始湧冒一股神秘的黑暗能量。&gt;", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31770] = {title = "不是朋友就是…", objective = "試著在甘露村取得甘露村長的協助。", description = "$p，我們需要附近村莊的協助。\n\n我們得利用村莊重整隊伍和照料傷患。\n\n或許在見到聯盟造成的暴力破壞之後，村民們會願意加入我們。\n\n我要你擔任部落的大使。取得村民的協助。別讓我失望！", progress = nil, completion = "你的爭鬥為我們這個小村子帶來太多的毀滅了！\n\n我們對你們的戰爭沒有興趣，但我們不會趕走你們的傷患。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31771] = {title = "面對後果", objective = "殺死20個鬼煞和7個先驅煞。", description = "我不知道你們戰爭的背後歷史，也對它沒有興趣。這片土地對負面能量有強烈反應。你所帶來的憎恨、疑惑和暴力，如今像傷口滲出的鮮血一樣在潘達利亞各處出現。\n\n你們的行動為這片廢墟帶來了浩劫！收拾你所留下的殘局，再到下方的村莊和我碰面。我會盡量解釋這裡所發生的事。", progress = nil, completion = "很高興你為你的行為負起了一些責任。如果放任不管，負面情緒很快就會淹沒這裡的個體，就像它們已經開始侵蝕你稱為「納茲格寧姆」的那個人一樣。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31772] = {title = "優先事項！", objective = "在甘露林地找到6桶甘露酒。", description = "看看這團混亂！這麼多酒都被糟蹋了！\n\n塔蘭‧祝警告過我們別和你們這些外來人說話，但我用得上所有的協助。\n\n你們開打的時候，我們正在前往晨綻送酒的路上。現在所有的酒都沒了！\n\n你想要補償我們？也許你能找到幾桶還沒破損的甘露酒。那樣就能彌補一點我們的損失。", progress = nil, completion = "嗯，和我所希望的不太一樣，但也不能講究了。我想為了打翻的酒哭泣是沒有意義的。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31773] = {title = "徘徊者問題", objective = "在甘露林地殺掉10隻被煞侵蝕的徘徊者。", description = "動物們全都瘋了！\n\n那些徘徊者通常不會靠近村莊，但現在，我們連阻止牠們靠近都沒辦法。我從沒見過像這樣的行為！\n\n村長已經向影潘求助，但他們還沒全部到齊。你能否在這些徘徊者攻擊我們的農夫前，將牠們解決掉？", progress = nil, completion = "啊，所以你們在廢墟的衝突開始污染當地的野生動物了？這真是令人困擾，我從沒見過這麼強烈的影響。\n\n謝謝你保衛了村子，但必須殺死那些可憐的動物是場悲劇。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31774] = {title = "找尋金浚", objective = "在旋風坡某處找到金浚。", description = "理弗特宣稱他看到金浚和其他生還者一起棄船了。那就表示他還在外邊的某處。\n\n我們絕不能把他留下。他可能受傷了，更糟的是被俘虜了！\n\n去找到金浚，帶他回來。", progress = nil, completion = "&lt;金浚受了重傷，但感覺到你是友善的。&gt;\n\n猴子傢伙！到處都是猴子傢伙！", rewards = "登陸皮甲長靴登陸鍊甲長靴登陸絲質足靴登陸緞質足靴登陸底鞋登陸脛甲登陸光潔護脛登陸戰靴登陸鎧甲長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][31775] = {title = "襲擊機場跑道", objective = "在強臂簡易機場殺死15個強臂部隊。", description = "我找到他們隱藏的空軍基地了，<name>。強臂簡易機場。找到那裡不難，畢竟那裡擠滿了聯盟。\n\n<納茲格寧姆啐了一口。>\n\n他們以為自己把我們徹底殲滅了，但我們是部落！我們戰鬥到我們變成屍體為止…有時候甚至戰到變成屍體之後。讓他們嚐嚐我們武器的滋味！", progress = nil, completion = "在潘達利亞殺死聯盟的最好之處？那就是他們得過好幾個月才能得到增援。\n\n這片土地會落入部落手中，&lt;class&gt;。我們就快達成了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31776] = {title = "強臂戰略", objective = "殺死傑克森‧純銀下士、摩格斯‧峻斧、工程大師考格斯溫和迴轉工程師薰衣。", description = "強臂簡易機場那裡來了偵察報告，我圈出了幾個優先的目標給你。\n\n聯盟的旋翼機仰賴兩個地精裝置來飛在空中，破壞這兩個裝置就能使旋翼機的數量減少。\n\n一名矮人死亡騎士在巡邏他們的邊界。他是個像你一樣的冒險者，沒什麼盟友，但極度危險。\n\n終於，有個我認識的名字:傑克森‧純銀下士。他是聯盟的英雄，十字弓的技巧出神入化。\n\n祝好運，<name>。", progress = nil, completion = "鮮血與雷霆，&lt;name&gt;。鮮血與雷霆。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31777] = {title = "有機可乘", objective = "在強臂簡易機場撿起徵用的煙火發射器，再用在12架強臂旋翼機上。", description = "我在前往這裡的路上看見幾管肩式火箭發射器。\n\n也有可能是煙火而已。我不知道。我只是假設它們是肩式火箭發射器，直到我被證明是錯的為止。\n\n重點是，在像你這樣經驗老到的<class>手中，它們或許能把旋翼機給打下來。如果你在附近找到這種發射器，試著拿它們對準對方那些粗製濫造的旋翼機。", progress = nil, completion = "希望那些痞子喜歡你為他們舉辦的派對！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31778] = {title = "不可靠的盟友", objective = "鼓吹12名熊貓人志願者離開強臂簡易機場。", description = "我們原本以朋友的方式歡迎聯盟。有些村民自願去幫他們建築飛機跑道。但直到最近，我們才理解到他們是在建造一個軍事基地，就在離我們村莊不遠的位置。\n\n更糟的是，我恐怕有些村民遭到了拘禁。如果你找到他們，<class>，讓他們知道回家的時候到了。", progress = nil, completion = "儘管我不能理解你為什麼選擇將你們的戰爭帶來我們的土地，但我可以清楚看出哪一方是更有德性的。\n\n謝謝你的幫助，&lt;race&gt;。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31779] = {title = "內心的黑暗", objective = "殺死多倫隊長。", description = "你在外面的時候，有沒有看到多倫隊長？\n\n那個愛哭哭啼啼的聯盟指揮官肯定就躲在某個地方。如果他不在那座空軍基地，那他肯定離這裡不遠。搜尋主要機場的西南邊。我要把聯盟趕出這裡！", progress = nil, completion = "聯盟被擊潰了。你、納茲格寧姆、卡玲、哥羅克、修基雅和理弗特需要一個行動基地。\n\n這裡得要改弦易張了。\n\n為了部落！", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][31780] = {title = "王老先生", objective = "在寵物對戰中擊敗王老先生。", description = "這次我可不會這麼好對付！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31781] = {title = "林塞", objective = "在寵物對戰中擊敗林塞。", description = "你以為自己能再次打敗我？我永遠樂於接受挑戰！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31782] = {title = "挑戰王座", objective = "到卡拉西斐斯找卡拉西瓦。", description = "議會正處於和諧的狀態，喚醒者。\n\n我們的儀式會為女皇帶來毀滅，讓我們的帝國有個偉大的未來吧。\n\n見證卡拉西的力量吧！", progress = nil, completion = "我們…尚未成功，喚醒者。\n\n你的成就曾經對我們的目標是重要的助力。\n\n代表殘餘的議會成員，我請求你繼續協助我們。", rewards = "慈母之種之索樹蠅腰帶枯木護腰清澈扣環驚懼紡織者之索鬼狐腰帶奪風者護腰刃誓束腰冰蝕束腰您會收到：\n\n卡拉西"}
MultiLanguageQuestData['tw'][31784] = {title = "女神瑪瑙", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31785] = {title = "升級！", objective = "讓寵物升到等級3。", description = "很好、很好。讓你的寵物保持健康並準備好面對戰鬥是很種要的。\n\n我給你的下一項任務就是進行幾場戰鬥，將一隻寵物提升到等級3。完成這項任務之後，回來找我討論關於捕捉你自己寵物的事情！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31786] = {title = "完好如初的叛亂鐐銬", objective = "展示考古文物。", description = "這件古物已經被回復到十分良好的狀態。也許你可以將它展示在知識之座，讓博學行者和考古學家們可以研究。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n復原的古文物魔古雕像碎塊"}
