MultiLanguageQuestData['tw'][31919] = {title = "戰寵馴獸師：外域", objective = "在寵物對戰中擊敗尼奇‧小型技術、雷森、納羅克以及長者莫魯魯。", description = "你已經擊敗了卡林多和東部王國的大師級馴獸師，但你接下來的挑戰將會更加困難。\n\n在外域有四名你必須擊敗的馴獸師：地獄火半島的尼奇‧小型技術、贊格沼澤的雷森、納葛蘭的納羅克、以及撒塔斯的長者莫魯魯。\n\n你必須擊敗他們來獲得更大的成就。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31920] = {title = "宗師安塔利", objective = "在寵物對戰中擊敗血騎士安塔利。", description = "我看過像你這樣的傢伙。年輕、天真的訓練師，覺得自己天下無敵，勝利唾手可得。\n\n得了吧你！我就是你的天敵，<class>。我，影月谷的血騎士安塔利，會讓你嚐嚐在戰鬥中失敗的滋味您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31921] = {title = "戰寵馴獸師：外域", objective = "在寵物對戰中擊敗尼奇‧小型技術、雷森、納羅克以及長者莫魯魯。", description = "你已經擊敗了卡林多和東部王國的大師級馴獸師，但你接下來的挑戰將會更加困難。\n\n在外域有四名你必須擊敗的馴獸師：地獄火半島的尼奇‧小型技術、贊格沼澤的雷森、納葛蘭的納羅克、以及撒塔斯的長者莫魯魯。\n\n你必須擊敗他們來獲得更大的成就。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31922] = {title = "尼奇‧小型技術", objective = "在寵物對戰中擊敗尼奇‧小型技術。", description = "根據我的計算，我的獲勝機率為32.333%。行，來吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31923] = {title = "雷森", objective = "在寵物對戰中擊敗雷森。", description = "你想再打一次？我可是強大多了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31924] = {title = "納羅克", objective = "在寵物對戰中擊敗納羅克。", description = "我想再戰鬥一次。這些年輕的傢伙需要有機會變強。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31925] = {title = "長者莫魯魯", objective = "在寵物對戰中擊敗長者莫魯魯。", description = "上次見面後，我已經學了不少。你想再次測試你的技能嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31926] = {title = "宗師安塔利", objective = "在寵物對戰中擊敗血騎士安塔利。", description = "上一次，你利用了我犯的錯誤並得到勝利。這一次，你不會再這麼幸運了，<race>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31927] = {title = "戰寵馴獸師：北裂境", objective = "在寵物對戰中擊敗畢格‧疾熔，『差點頭不保』的雅格布，奧庫特‧龍荒以及腸嘔。", description = "你已經擊敗了外域的最強者，但還有北裂境在等著你！\n\n你必須擊敗四名馴獸師：凜風峽灣的畢格‧疾熔，水晶之歌森林的『差點頭不保』的雅格布，龍骨荒野的奧庫特‧龍荒，以及祖爾德拉克的腸嘔。\n\n如果你有辦法擊敗所有人，北裂境的宗師肯定會向你提出挑戰！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31928] = {title = "宗師佩恩", objective = "在寵物對戰中擊敗佩恩少校。", description = "依我的想法，我的訓練師同伴給你的訓練太過寬鬆了。\n\n真正的寵物訓練需要的是軍事般的紀律。我會讓你有榮幸親身體驗軍事紀律能達到什麼成果。\n\n過來寒冰皇冠的銀白聯賽場地，親眼看看你可以獲得多大的成就吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31929] = {title = "戰寵馴獸師：北裂境", objective = "在寵物對戰中擊敗畢格‧疾熔，『差點頭不保』的雅格布，奧庫特‧龍荒以及腸嘔。", description = "你已經擊敗了外域的最強者，但還有北裂境在等著你！\n\n你必須擊敗四名訓馴獸師：凜風峽灣的畢格‧疾熔，水晶之歌森林的『差點頭不保』的雅格布，龍骨荒野的奧庫特‧龍荒，以及祖爾德拉克的腸嘔。\n\n如果你有辦法擊敗所有人，北裂境的宗師肯定會向你提出挑戰！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31930] = {title = "戰寵馴獸師：潘達利亞", objective = "在寵物對戰中擊敗寺裡的懷雅、農夫妮希、摩洛卡、勇敢的雍、追尋者薩世席以及『荒行者』塾。", description = "現在，你得面對全艾澤拉斯最強大的馴獸師，<name>。他們以潘達利亞為家，那裡是宗師的訓練場。\n\n你得擊敗六名宗師：翠玉林的寺裡的懷雅，四風峽的農夫妮希，喀撒朗蠻荒的摩洛卡，崑萊峰的勇敢的雍，螳螂荒原的追尋者薩世席以及悚然荒野的『荒行者』塾。\n\n如果你感覺準備好了，去找這些英雄，證明你自己！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31931] = {title = "畢格‧疾熔", objective = "在寵物對戰中擊敗畢格‧疾熔。", description = "昨天，我的一隻雞飛了好一段時間，我發誓。我們終於要發達啦！\n\n喔，你要再戰鬥一次嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31932] = {title = "『差點頭不保』的雅格布", objective = "在寵物對戰中擊敗『差點頭不保』的雅格布。", description = "你一次又一次地挑戰我的智慧。你為什麼要回到這片林地？\n\n啊，你想要再戰鬥一次。很好，來吧。", progress = nil, completion = "你的冒險有了代價。滾吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31933] = {title = "奧庫特‧龍荒", objective = "在寵物對戰中擊敗奧庫特‧龍荒。", description = "你膽敢阻礙我們工作？那你必須再和我戰鬥一次！叫出你的寵物，我會讓你嚐嚐地獄吼怒火的滋味！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31934] = {title = "腸嘔", objective = "在寵物對戰中擊敗腸嘔。", description = "我喜歡和你打。你不像其他人那麼弱。我們再打一次吧？", progress = nil, completion = "我喜歡和你打，就算我輸了也是。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31935] = {title = "宗師佩恩", objective = "在寵物對戰中擊敗佩恩少校。", description = "<class>小賊再次前來向宗師挑戰，好測試<他/她>自己的力量。這一次，你的勇氣會造成你的末日！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31936] = {title = "「錦魚人公主」灌溉系統", objective = "將「錦魚人公主」灌溉系統帶去日歌農莊或半丘市集給農夫尹。\n\n已提供物品：\n", description = "<盒子的背後畫著一個被商標包圍的漫畫式錦魚人侍女。>\n\n「哈囉，綠手指。你為了乾枯的南瓜哀傷嗎？對著硬梆梆的卷心菜哭泣嗎？你的韭菜枯萎，甜瓜可悲透了嗎？\n\n將錦魚人公主抱回家的時候到了！她會像春天的小雨一樣滋潤你的菜園，深深浸透乾旱的...」\n\n<這些文字繼續了六段之長。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31937] = {title = "「雷王」除蟲王", objective = "將「雷王」除蟲王帶去日歌農莊或半丘市集給農夫尹。\n\n已提供物品：\n", description = "<一張威風凜凜的魔古的臉孔佔據了這個盒子，睥睨著一排粗體的文字。>\n\n「別讓軟弱、噁心的蟲子侵蝕你高貴的作物。用雷王的力量征服他們，保護你的財產。」\n\n<其餘的空間描繪著各種昆蟲在恐懼中哭喊著逃跑的卡通圖案。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31938] = {title = "「裂地者」犁田主宰", objective = "將「裂地者」犁田主宰帶去日歌農莊或半丘市集給農夫尹。\n\n已提供物品：\n", description = "<盒子上畫著一個體格粗勇無比的熊貓人農夫，驕傲地跨在地面的一道裂縫上，手中握著一柄強大的鋤頭。小熊貓人開心地在他的肩膀上扭打，吊掛在他肌肉糾結的手臂上。\n\n在他身邊，一名端莊的女性－同樣擁有無與倫比的體格－頭上優雅地頂著一個豐收的籃子，腳下踢著一隻害蟲的臉。>\n\n「犁田主宰。主宰大地。主宰你的人生。」您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31939] = {title = "Test", objective = "种植并收获4份爽脆胡萝卜。爽脆胡萝卜种子可以在半山市集的商人绿野处买到。在开垦土地并照料植株之后，你必须等到第二天才能收获成熟的爽脆胡萝卜。好了，朋友，之前的农活不过是热身而已！\n\n现在，要动真格的了！你准备好了吗？\n\n市集的美美·铁掌需要一些胡萝卜来做炖菜。你知道这些胡萝卜要由谁来种吗？我们！\n\n现在，你就来种植、催生并收获四畦爽脆胡萝卜，让我看看你学到了点什么吧！您會學到：\n\n", description = "好了，朋友，之前的农活不过是热身而已！\n\n现在，要动真格的了！你准备好了吗？\n\n市集的美美·铁掌需要一些胡萝卜来做炖菜。你知道这些胡萝卜要由谁来种吗？我们！\n\n现在，你就来种植、催生并收获四畦爽脆胡萝卜，让我看看你学到了点什么吧！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n真言術：恐龍\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][31941] = {title = "除臭碧玉瓜", objective = "在日歌农场种植一棵碧玉瓜。你可以从半山市集的商人绿野那里购买种子。", description = "爷爷常说：“每周一只碧玉瓜，可以让臭气远离你的尾巴。”\n\n<老愚敏锐地闻了闻空气。>\n\n没错。我想一周快到了。你能帮我种一个碧玉瓜吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31942] = {title = "甜瓜時間", objective = "在日歌農莊種植條紋甜瓜。你可以在半丘市集向商人青田購買種子。", description = "<農夫尹抬頭望天，聞了聞氣味。>\n\n哼嗯…\n\n<他舔了舔爪子，舉起來放在空中，又將一根指爪插進土壤裡，測試他影子的長度。>\n\n沒錯。甜瓜時間到了。\n\n你能不能抓些種子，幫我種一個條紋甜瓜？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31943] = {title = "什麼莓？巫莓。", objective = "在日歌農莊種植巫莓。你可以在半丘市集向商人青田購買種子。", description = "那邊那個小夥子，安狄，有一天會成長為了不起的農夫。我光看他的樣子就知道了。\n\n我想我會給他種一些巫莓。小孩子最喜歡巫莓了，這會是個驚喜。", progress = nil, completion = "好啊，巫莓！等不及！\n\n但等不及也得等。", rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][31944] = {title = "完成你的訓練:最終測試", objective = "到寂靜峰的訓練場完成你的最終試煉。", description = "歡迎回來，<name>。完成最後一步訓練的時候到了。前往訓練場，接受你的最終試煉吧。", progress = nil, completion = "做得好呀，&lt;name&gt;。你已經完成了你的訓練。歡迎你之後回來與這裡的大師們過個兩招來複習你學過的東西。", rewards = "鶴舞者法杖白虎王之杖牛蹄雷霆之杖您會學到：\n\n啟蒙\n\n您還會收到：\n\n鶴舞者法杖白虎王之杖牛蹄雷霆之杖恆龍寶箱"}
MultiLanguageQuestData['tw'][31945] = {title = "第一次種植就上手第六課:吉娜的一票", objective = "種植並收成1批青蔥，然後將5份青蔥交給吉娜‧泥爪。青蔥種子可以在半丘市集的商人青田那裡買到。耕種並照料過你的植物後，你必須等到隔天才能採收長成的青蔥。", description = "我的生意完了!你看到伙房那邊的那些鐵爪家的人嗎?\n\n他們的美食吸引很多顧客前來市集，但他們的青蔥用完了!\n\n這像是一樁小事，但青蔥是十分關鍵的食材。少了它，食物會失去風味，不夠可口，更不夠芳香。\n\n這真是太糟了!另一批青蔥還要一個星期才會送到!\n\n等等!你是個農夫，對嗎?你能夠幫我嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31946] = {title = "芒芒的一票III:跳躍的胡蘿蔔", objective = "種植並收成2批脆嫩多汁胡蘿蔔，然後將10份脆嫩多汁胡蘿蔔交給芒芒。脆嫩多汁胡蘿蔔種子可以在半丘市集的商人青田那裡買到。耕種並照料過你的植物後，你必須等到隔天才能採收長成的脆嫩多汁胡蘿蔔。", description = "芒芒不在乎是誰偷了胡蘿蔔。只在乎泥爪先生發現他的作物完蛋了的時候，會對可憐的芒芒做什麼!\n\n<芒芒思索著，撫著下巴。>\n\n等等!芒芒有個聰明的主意。你去種一些脆嫩多汁胡蘿蔔。然後，我們拿你的胡蘿蔔過去，假裝它們是泥爪先生的。\n\n太好啦!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31947] = {title = "農夫老豐的一票III:瘋狂捲心菜", objective = "種植並收成3批綠色捲心菜，然後將15份綠色捲心菜交給農夫老豐。綠色捲心菜種子可以在半丘市集的商人青田那裡買到。耕種並照料過你的植物後，你必須等到隔天才能採收長成的綠色捲心菜。", description = "<農夫老豐燦爛地一笑。>\n\n多虧了你，我的寶貝犛牛回來了!不幸的是，我注意到牠們在野外的時光讓他們變得憔悴得多。\n\n牠們肯定餓壞了，但我可不會拿普通的老乾草給我的珍貴犛牛吃。\n\n絕不會，牠們只吃你在山谷裡所能找到最肥美的綠色捲心菜。\n\n我的庫存有點低落。如果你能幫我的犛牛帶來一些捲心菜，我會好好回饋你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31948] = {title = "娜娜的一票II:神聖之泉", objective = "在黃金瀑布使用空壺來收集千年好水。", description = "你來找我的時間剛剛好，<name>。我正好很想做一批新鮮的冰鎮巫莓汁。\n\n你聽說過這種美妙的酒嗎？\n\n每一口都能讓你回春十年！你以為我為什麼看起來這麼棒？\n\n總之，我需要一種特殊的原料：千年好水。你可以在北邊的瀑布口收集到這種水。\n\n過去那裡的旅程對像我這樣的老婦來說恐怕太危險了，但如果你能幫我裝一大罐來，我會分你一些酒喝。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31949] = {title = "娜娜的一票III:冰鎮巫莓汁", objective = "種植並收成3批巫莓，然後將15份巫莓交給娜娜‧泥爪。巫莓種子可以在半丘市集的商人青田那裡買到。耕種並照料過你的植物後，你必須等到隔天才能採收長成的巫苺。", description = "拿到水之後，我幾乎能嚐到冰涼冰鎮巫莓汁的味道了!\n\n現在，我們只需要給自己找一些甜美的巫莓。\n\n我孫子這一季的收成爛透了，我得到其他地方找一批好的。\n\n你今年有沒有種些巫莓呢?你何不從你的農場上帶一些給我?\n\n如果你的收成符合標準，我們就能給自己做一大堆美味的果汁啦!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31950] = {title = "Tracking Quest: Move NPCs to Dais", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][31951] = {title = "宗師雅姬", objective = "在寵物對戰中擊敗『天選』雅姬。", description = "你和艾澤拉斯的訓練師們戰鬥得十分辛苦而精采。就連宗師都臣服在你機智的戰略之下。\n\n我會在恆春谷裡等待著你，因為你已經贏得與我對決的殊榮。來吧，<name>，讓我們看看你有沒有擊敗我的實力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31952] = {title = "戰寵馴獸師：潘達利亞", objective = "在寵物對戰中擊敗寺裡的懷雅、農夫妮希、摩洛卡、勇敢的雍、追尋者薩世席以及『荒行者』塾。", description = "現在，你得面對全艾澤拉斯最強大的馴獸師，<name>。他們以潘達利亞為家，那裡是宗師的訓練場。\n\n你得擊敗六名宗師：翠玉林的寺裡的懷雅，四風峽的農夫妮希，喀撒朗蠻荒的摩洛卡，崑萊峰的勇敢的雍，螳螂荒原的追尋者薩世席以及悚然荒野的『荒行者』塾。\n\n如果你感覺準備好了，去找這些英雄，證明你自己！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31953] = {title = "宗師懷雅", objective = "在寵物對戰中擊敗寺裡的懷雅。", description = "你想要再打一次?很好，這會強化我保衛我人民神聖處所的力量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31954] = {title = "宗師摩洛卡", objective = "在寵物對戰中擊敗摩洛卡。", description = "這一次換我痛宰你了!等著瞧吧!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31955] = {title = "宗師妮希", objective = "在寵物對戰中擊敗農夫妮希。", description = "多虧了我們當做訓練場的豐饒大地，我的寵物變得越來越強。你沒有機會了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31956] = {title = "宗師雍", objective = "在寵物對戰中擊敗勇敢的雍。", description = "如果你以為我會讓你就這樣再贏一次，那你就徹底搞錯了。這一次，我會成為勝利者!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31957] = {title = "宗師塾", objective = "在寵物對戰中擊敗『荒行者』塾。", description = "你闖到這片荒野的中心來和我二度對決，但你只會在真正的宗師手下嚐到失敗的滋味。你很勇敢，但也很愚蠢。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31958] = {title = "宗師雅姬", objective = "在寵物對戰中擊敗『天選』雅姬。", description = "你想要再度嘗試和我對決?很好，來戰鬥吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31959] = {title = "女王先發制人", objective = "到恐懼之心外面找『毫髮無傷』的瑪力克。", description = "杉齊爾女皇終於對我們失去耐心了。我們剛剛才得知，有數量驚人的軍隊集結在恐懼之心的陰影中，他們接到的命令是摧毀卡拉西斐斯。\n\n我們能撐這麼久已經很幸運，但在如此大規模的圍攻下，我們不可能生存下來。\n\n喚醒者，至今你已立下許多戰果。去吧，加入戰場上的聖螳們。\n\n我和你在戰場上見！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
