MultiLanguageQuestData['tw'][31966] = {title = "戰寵馴獸師：浩劫與重生", objective = "在寵物對戰中擊敗布拉克、博丁‧穩拳以及苟斯‧禍怒。", description = "你擊敗了北裂境最好的馴獸師，但你還需要更多準備，才有辦法面對潘達利亞的宗師。準備好磨練你的技能，擊敗這些菁英級馴獸師：海加爾山的布拉克，地深之源的博丁‧穩拳，以及暮光高地的苟斯‧禍怒。\n\n若你能戰勝他們，你就準備好前往潘達利亞面對終極的挑戰。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31967] = {title = "戰寵馴獸師：浩劫與重生", objective = "在寵物對戰中擊敗布拉克、博丁‧穩拳以及苟斯‧禍怒。", description = "你已征服了北裂境，但你還沒準備好面對潘達利亞的宗師。擊敗這些馴獸師來強化你的意志，好面對將來的挑戰：海加爾山的布拉克，地深之源的博丁‧穩拳，以及暮光高地的苟斯‧禍怒。\n\n戰勝他們，你才能準備好前往潘達利亞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
