MultiLanguageQuestData['tw'][31970] = {title = "宗師歐巴里斯", objective = "在寵物對戰中擊敗歐巴里斯。", description = "你覺得自己準備好挑戰潘達利亞了？你真的相信你能擊敗艾澤拉斯上最強大訓練師？\n\n我會為你評判這個念頭是不是真的，<race>。到奧丹姆頂端的維爾納爾水壩面對我，讓我們看看你是否真的準備好了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31971] = {title = "宗師歐巴里斯", objective = "在寵物對戰中擊敗歐巴里斯。", description = "凱旋而去的訓練師再度回來挑戰我，測試<他/她>的技能。很好。我接受你的挑戰。", progress = nil, completion = "擊敗我之後，我也會變得更強。下次相遇你最好小心。", rewards = "您會收到：\n\n一袋寵物用品"}
MultiLanguageQuestData['tw'][31972] = {title = "布拉克", objective = "在寵物對戰中擊敗布拉克。", description = "我還沒完全了解這些生物的境況以有效率地幫助牠們。也許再戰鬥一次能加深我們之間的連結？", progress = nil, completion = "就算戰敗了，我也感覺和我的寵物變得更親近。謝謝你和我打了一場好仗。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31973] = {title = "博丁‧穩拳", objective = "在寵物對戰中擊敗博丁‧穩拳。", description = "本地的原住民教導我大地的力量。我認識到了那無盡的堅忍。讓我們再次戰鬥吧，你會發現我比以往任何時候都要強！", progress = nil, completion = "不、不，我搞砸了。再打一場如何？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31974] = {title = "苟斯‧禍怒", objective = "在寵物對戰中擊敗苟斯‧禍怒。", description = "暮光的力量在我身上流竄。我是個神！你沒有擊敗我的希望！", progress = nil, completion = "你戰鬥時的怒氣可以和我的主人匹敵。也許我們並沒有那麼不同。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31975] = {title = "勇士回歸", objective = "到暴風城找奧德蕾‧燃憂。", description = "問我的話，我覺得你應該留在外域和其他好傢伙在一起。你為什麼不回暴風城去找奧德蕾‧燃憂，看看你身為訓練師的下一步該怎麼走？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31976] = {title = "勇士回歸", objective = "到暴風城找奧德蕾雷‧燃憂。", description = "關於你強大技巧的傳言已經散播開來。我建議你回去找你的訓練師，奧德蕾‧燃憂，尋求進一步的指引。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31977] = {title = "勇士回歸", objective = "到奧格瑪找伐索克。", description = "問我的話，我覺得你應該留在外域和其他好傢伙在一起。你為什麼不回奧格瑪去找伐索克，看看你身為訓練師的下一步該怎麼走？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][31978] = {title = "優先事項！", objective = "到甘露林地找6桶甘露酒。", description = "看看這團混亂！這麼多酒都被糟蹋了！\n\n塔蘭‧祝警告過我們別和你們這些外來人說話，但我用得上所有的協助。\n\n你們開打的時候，我們正在前往晨綻送酒的路上。現在所有的酒都沒了！\n\n你想要補償我們？也許你能找到幾桶還沒破損的甘露酒。那樣就能彌補一點我們的損失。", progress = nil, completion = "嗯，和我期望的不太一樣，但也足夠了。我想為了打翻的酒哭泣沒什麼意義。", rewards = "您會收到：\n\n恆龍寶箱"}
