MultiLanguageQuestData['tw'][32003] = {title = "夠格的挑戰:雷剛", objective = "完成落陽關挑戰模式。", description = "<name>，我要你募集一支隊伍，並領往落陽關。在關內，你必須啟動挑戰者之球，並毀滅雷剛。\n\n完成這項挑戰後回來找我，我會好好獎勵你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n英雄藏寶箱"}
MultiLanguageQuestData['tw'][32004] = {title = "艰难的挑战：翼虫首领尼诺洛克", objective = "完成围攻砮皂寺挑战。", description = "<name>，我要你去召集一支目力过人的队伍，参与围攻砮皂寺的战役。你要激活那里的挑战者的宝珠，并击落翼虫首领尼诺洛克。\n\n完成这个挑战后，你再回来找我。我会好好奖赏你的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n英雄藏寶箱"}
