MultiLanguageQuestData['tw'][32115] = {title = "旧日的枷锁", objective = "解救14个不安的灵奴。", description = "魔古族就是一群混蛋！\n\n在洞中干活儿的熊猫人即便在死后都要受到他们的奴役。你要去解救他们的灵魂！因为那是不对的。\n\n但你要小心点……那些饱经创伤的灵魂已经分不清敌友了。所以他们可能会反抗。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32116] = {title = "事有輕重緩急！", objective = "到喀撒朗蠻荒的歐古戴遺跡找希爾達‧角旋。", description = "當我下令挖掘西北邊的隧道時，我以為我們會找到什麼有用的東西。黃金，鐵礦…什麼都好！\n\n結果我們挖到了魔古神器，這下子我得充當那群探險者協會矮人的保姆了。\n\n我聽士兵說礦坑裡出了麻煩，烏瑞恩命令我支援探險者協會，可是我沒有多餘的部隊可以派過去，你可以幫忙看看出了什麼事嗎？", progress = nil, completion = "喂！我們這裡有個棘手的問題。我們踢到馬蜂窩了，而且還是兇殘得不得了的魔古鬼魂馬蜂窩！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32118] = {title = "善加利用", objective = "使用閃亮火箭哨站的傳送門，前往喀撒朗蠻荒的歐古戴遺跡找凱利斯‧日翔。", description = "探險者協會的笨蛋在東北方挖出了一座古代的魔古遺跡。而且，想當然爾，他們亂搞一通，擾動了裡面的魔古之靈。\n\n我們要趁機利用他們的愚蠢。穿過這道傳送門去找凱利斯‧日翔，那是我在遺跡的聯絡人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32119] = {title = "費解之謎", objective = "用希爾達的異象體追蹤器找出並消滅異象體。", description = "下頭有東西把工人給嚇壞了。某種異象體...看起來像是鬼魂或魔法...我從沒見過類似的東西。\n\n不過我試著讀取它的資料，做出了這個裝置來追蹤它。裝置上的螢幕會告訴你大概的距離。\n\n等你夠接近了，就能用它引出異象體，徹底解決它!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32120] = {title = "歐古戴的遺產", objective = "收集5個遠古魔古精華。", description = "我們目前佔據的這個遺跡是一名古代的魔古統治者，歐古戴所建造的。我們對他的身分所知甚少，但是從這塊區域復甦的靈魂看來，事情似乎與束縛靈魂有關。\n\n當你消滅這些靈魂的時候，它們會有一小部分的精華留在這個世界。把精華交給我們，我們會嘗試分析它，希望可以瞭解更多歐古戴的歷史，以及他的力量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32121] = {title = "灵魂陷阱", objective = "摧毁3个灵魂陷阱。", description = "废墟里有一大堆十分危险的蓝色水晶。检查它们时稍有不慎，就会有愤怒的鬼魂冲出来攻击你。\n\n我需要你进去，除掉一些这些害人的东西，这样我们的人才能重返工作。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32122] = {title = "歐古戴的副官", objective = "消滅『山力』孟督和『巧言』簡立。", description = "我們挖到魔古遺跡其中一塊古老的區域時，所有的麻煩事就在這個時候開始了 - 其中最可怕的兩個幽靈也是從這裡冒出來的。\n\n朋友，我們需要除掉它們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32123] = {title = "大殺四方", objective = "在制霸岬消滅10個聯盟士兵。", description = "聯盟已經登陸了。如果我們不在這裡擊敗他們，部落就無望在這塊大陸上立足。\n\n前往南邊的戰場，見到聯盟成員就殺。\n\n讓他們瞧瞧，只要是還能作戰的部落士兵，就抵得過十個聯盟的傢伙!", progress = nil, completion = "做得好，&lt;name&gt;。看來你待在這片土地上讓你的決心更堅定、技藝更高強了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32126] = {title = "撕成碎片", objective = "摧毀8個聯盟空投補給。", description = "聯盟也許都是些懦夫，但是他們可不笨。他們的攻擊對那些比較弱小的對象來說，是很可怕的。\n\n為了持續攻勢並且對我們的部隊施壓，他們正空投補給以支援地面部隊。\n\n搜索南邊的海岸與港口，找出任何空投補給並打爛它們。\n\n讓聯盟親眼看著自己的糧食與彈藥被人毀掉，奪去他們的希望。", progress = nil, completion = "要記得，你該使用的武器不是那些射程最長或是威力最強的。到頭來，最好的武器是那些總是管用的武器。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32127] = {title = "全死光了", objective = "消滅『黑面』布蘭特船長和莫琪船長。", description = "我們的大酋長派我到這片海岸來處理這場可悲的聯盟威脅。\n\n這些人類和他們的盟友非常倚賴自己的領袖。他們自己不會主導行動。\n\n你今天上戰場的時候，留意我們南邊海岸的聯盟船艦。找出他們的船長。\n\n殺掉他們。\n\n為了部落!", progress = nil, completion = "奪去聯盟的領袖還不夠。我們一定要警告那些有意領導的人，成為領袖的代價。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32128] = {title = "又一個上西天", objective = "引爆「不屈號」與「勇氣之鋒」的火藥庫。", description = "聯盟在我們南側岸邊站穩陣腳，不斷用大砲轟擊我們的地面部隊。我們就看看他們沒了補給以後攻勢能有多猛烈。\n\n登上敵人的船艦，摧毀他們的備用彈藥。把獠牙拔了，看他們還多能咬。", progress = nil, completion = "啊!你看它們著火的模樣。不過，光靠這樣是沒辦法徹底毀掉這些聯盟的新船艦的。我確定他們一兩天之內就會撲滅火勢。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32130] = {title = "祝好運，玩得開心點!", objective = "在喀撒朗蠻荒的雄獅灘收集10個超多耳屎的聯盟耳朵。", description = "我有客人等著想收集傳統的耳朵。可是不是那種隨便的陳年耳朵。他們想要的是那種用錢能買到的，耳屎最多的耳朵!\n\n他們可能覺得自己運氣很好之類的。\n\n總之，我需要你幫我找耳朵回來。我不想傷害動物，所以你得從雄獅灘的聯盟身上想辦法。\n\n玩得開心點 - 別忘了，我只要耳屎最多的那種!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32131] = {title = "我們需要更多的石礦!", objective = "在喀撒朗蠻荒的雄獅灘採石場收集20個可活化的石頭。雄獅灘的工程師會帶著它們，或者可以利用連帶損傷將石板炸成你可以攜帶的碎塊。", description = "地精在開採東北方的一座採石場。\n\n他們在用石頭蓋東西!\n\n<札希克斯翻了翻白眼。>\n\n它們太笨了，不知道那是特殊的魔古石頭，用來製造會動的雕像。\n\n我們可以混一點哥布林的神奇液體進去，弄出超級大爆炸!\n\n可是這東西很重。他們用一些傻呼呼的炸彈機器人在開採石頭。在石板附近炸掉它們，就會有可以帶著走的小石頭。\n\n或者直接殺了他們搶走石頭也可以。隨你方便。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32132] = {title = "騷擾工人", objective = "殺死30個雄獅灘農民。", description = "我們的哥布林朋友恐怕沒辦法理解長期作戰所需的策略。\n\n消滅任何常駐基地的關鍵就是破壞他們運補部隊與重建的能力。\n\n在這個案例裡，就是除掉他們的農民。殺掉他們，你就能削弱根基。堡壘其餘的部分註定會垮台。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32133] = {title = "哨衛結界", objective = "在雄獅灘的港口，城鎮大廳和兵營二樓放置哨衛結界。", description = "我們在對方的基地發現了重型空中支援，多得不得了的矮人騎著多得不得了的獅鷲獸。這表示我們沒辦法從空中獲得任何視野。\n\n有個食人妖...朋友給了我一組哨衛結界，我們可以用來監視他們的基地，並且從制高點觀察裡面的動靜。\n\n壞消息是，朋友，要潛入基地的人是你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32134] = {title = "一物剋一物", objective = "殺死8個雄獅灘迫擊砲團隊工程師，並且摧毀2個雄獅灘迫擊砲筒。", description = "我們讓一部分的石毀車上岸了，可是那些蠢矮人也在岸上，用他們的蠢迫擊砲筒阻止石毀車往前推進還有攻擊城堡!\n\n過去那邊殺幾個矮人，順便炸掉幾個迫擊砲筒。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32135] = {title = "英雄殺手", objective = "在喀撒朗蠻荒的雄獅灘殺死一名聯盟英雄。", description = "有的時候，除掉一個士兵比殺死一百個還重要。\n\n他們派出了幾個英雄到戰場上提振守軍的士氣。殺掉這些英雄不只可以削弱他們的防衛，還可以打擊士氣。\n\n所以去吧，為我拿下一個英雄。你辦得到的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32136] = {title = "工作令：燃料", objective = "到污水灘找格里斯‧輪滑。", description = "我們的燃料補給快用完了。沒有燃料，建造這裡的機器就不能運作。他們搞不好還會要我幫忙施工呢!\n\n我不是做工的料!看到這雙指甲了嗎?我才剛修過的!\n\n過去精煉廠完成這份燃料工作令!快點!他們今天早上配了個工具腰帶給我。那跟我的衣服根本不搭!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32137] = {title = "油盡燈枯", objective = "從黑沙疏洪道取回9個精煉燃料桶。", description = "我沒見過這種品質的油!問題是，這些油需要再精煉一下。\n\n我聽說有種方法是用海水來加速精煉的過程。我沒時間浪費了，所以我直接把燃料桶丟進海灣裡了。\n\n這點子不錯吧。問題是，我不確定要怎麼把桶子撈回來...\n\n像你這種有本事的人也許可以幫我個忙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32139] = {title = "疊木頭!", objective = "到木材場採集9塊制霸岬木材。", description = "我們今天早上才完成一份工作令。他們怎麼可能這麼快就需要更多的東西?!\n\n我的團隊一直在趕工砍樹跟處理木材。\n\n問題是雄獅灘的部隊在這裡騷擾我們。我今天已經冒過一次生命危險了，我可不要再回去那裡!\n\n戈伯會跟你一起過去，幫你完成這份命令。他不怎麼聰明，不過可以幫忙搬重的東西。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32142] = {title = "我們會震撼你", objective = "在制霸岬殺死10個獸人。", description = "不能讓獸人在這塊土地上立足。他們會玷污這裡，就像卡林多一樣。\n\n$p，我們要在這裡站穩腳步，把部落送進墳墓裡。到海岸線那裡去，給他們嚐嚐從天而降的聯盟憤怒!\n\n殺掉你見到的每一個獸人。讓他們的船帆不再飄蕩。\n\n為了國王而戰!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32143] = {title = "神奇魔法", objective = "在制霸岬找出3隻偵察機。", description = "$p，你好!我聽說了很多你在戰場上的勝績。我想請你測試我最新的「攻城旋翼」，那是個擁有各種高強能力的機械。\n\n我保證它大多數的時候都不會傷到使用者。\n\n你在制霸岬附近的時候留意我的偵察機。它們已經安置在外面，收集適合攻擊的目標資訊。當你找到其中一個的時候，啟動它，我會開著攻城旋翼前往你的位置。\n\n這麼說吧...我們戰場上見。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32144] = {title = "遭受壓力", objective = "摧毀8個部落補給箱。", description = "部落戰士的自尊心強大，每個人都會戰到至死方休。\n\n我們得想個不會造成我們部隊重大損失的辦法，來打擊他們的戰意。\n\n沿著岸邊還有他們的船艦附近找出部落的補給。\n\n沒什麼比看著自己的糧食燒個精光更能打擊守軍的意志了。\n\n完成之後，到敵軍戰線後方找蘇利。他會交代你下一個任務。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32145] = {title = "別丟了腦袋", objective = "擊敗石衛士魯克菈、轟炸官斯尼克斐茲以及奧岱克。", description = "我的偵測器在制霸堡的庭院發現三個很危險的目標。\n\n他們有一個巨魔特使，一個柯爾克隆軍官，還有一個哥布林瘋狂炸彈客。\n\n我的攻城旋翼還沒準備好進行一對一的戰鬥，所以要靠你來消滅這些目標。\n\n祝你好運!完成以後回到天火號向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32146] = {title = "制裁降臨", objective = "殺死5個笨重蠢蛋。", description = "看來部落以為自己可以躲在笨重蠢蛋後面。\n\n這些蠢蛋很耐打，力氣大，腦袋比宿醉的巨魔還笨。\n\n過去讓那些傢伙嚐嚐聯盟憤怒的制裁!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32147] = {title = "每日攻擊06", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32148] = {title = "攻擊!前進!", objective = "殺死12個制霸薩滿或制霸劫掠者。", description = "沒錯，外頭是有很多他們的蠻兵，捶著我們的門，等著砍掉我們的腦袋。\n\n我不擔心蠻兵，他們還有薩滿和劫掠者。薩滿利用魔法來強化蠻兵，而劫掠者速度快，擅長破壞我們的建築。\n\n我需要你去殺一些薩滿和劫掠者。\n\n去吧!攻擊!前進!", progress = nil, completion = "士兵，做得好。少了那些怪物幫忙，他們想突破防禦恐怕就沒那麼容易了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32149] = {title = "採集資源", objective = "從匆忙遺落的木材堆當中收集12塊雄獅灘木材。", description = "喔，可憐的農民...\n\n是，沒錯，他們都是膽小鬼。可是他們不懂得戰鬥，而且他們是為了我們的戰爭才出去採集木材...部落把他們當成目標...情況真的太糟了!\n\n可是，我們想撐下去的話還是需要木材。出去把他們丟掉的木材收集回來。", progress = "你採集到木材了嗎?", completion = "做得好!有了木材，我們就能完成堡壘的強化工作，保障人們的安全。你今天救了許多人的性命!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32150] = {title = "補給中斷", objective = "摧毀8輛制霸岬補給車。", description = "部落決定讓哥布林來掌管他們的後勤。只要有哥布林，就會有到處亂放的炸藥。\n\n斥候回報說，他們推車裡的補給也包括石毀車的彈藥。那些箱子只要一個沒處理好，就會炸上天去。\n\n只要能摧毀夠多的部落資源，我們就能拖延他們的攻勢並拯救更多生命。所以趕快去處理那些車子!", progress = nil, completion = "少了那些補給，他們就負擔不起讓更多的戰士加入戰局。如果他們沒辦法讓更多的戰士加入，我們能撐下去的機會就更大了。\n\n至少可以撐過今天。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32151] = {title = "塔防", objective = "在雄獅灘收集20塊可活化的石頭，可以從污水哥布林的手中搶回來，或者利用連帶損傷把石板炸成碎塊。", description = "地精負責西北邊採石場的營運，那邊的石頭格外堅硬 - 而且地精他們還說魔古就是用這些石頭來製作傀儡。\n\n這我不太清楚，我只知道我們得靠這些石頭來興建塔樓，而部落派出了污水哥布林來偷走這些石頭。\n\n去把石頭搶回來。\n\n對了，在周圍造成的連帶損傷可能會把石板炸碎。如果發生這樣的狀況，把碎石頭一起帶回來。", progress = "你帶石頭回來給我們了嗎?", completion = "很好!我們馬上就用石頭修補牆上的缺口，速度比矮人喝酒還快。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32152] = {title = "攻城傷害", objective = "在污水工兵身上找出污水爆破雷管，然後裝在制霸岬石毀車上。", description = "部落想出了一個很聰明的點子，派污水哥布林來攻擊我們的採石場。\n\n他們帶了強力炸藥 - 可以跟石毀車上的彈藥起反應。\n\n殺死污水哥布林，直到你找到炸藥為止，然後把炸藥裝在其中一輛石毀車上...砰!攻城結束了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32153] = {title = "英雄殺手", objective = "殺死一名部落英雄。", description = "聽著，你很強悍。比我手下其他的男女士兵都強悍。所以我需要你進行一個特殊任務。\n\n部落派出他們的精銳來對付我們。他們部隊裡的英雄 - 大劍師、牛頭人酋長，你想得到的都有。\n\n我們需要你除掉其中一個。這會重創他們的攻勢，以及士氣。", progress = nil, completion = "我知道這不容易，可是你辦到了。做得好。士兵，你贏得了我的尊敬。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32154] = {title = "燃燒殆盡!", objective = "利用不穩定爆裂物摧毀東北方的燃料桶、北方的燃料桶和西北方的燃料桶。", description = "那些哥布林太過分了!他們先是剷平了森林，弄了個亂七八糟的鑽油平台。然後他們開始把油桶丟進海灣裡!\n\n我們得結束這場混亂!至少，我們得阻礙他們。\n\n我們得除掉他們的燃料補給!也許你還可以順便殺幾個哥布林!", progress = nil, completion = "真希望我在現場看著他們的燃料燃燒!看起來可能很壯觀。\n\n&lt;name&gt;，你做得很好!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32156] = {title = "該做的事", objective = "在污水灘和周圍區域陣亡的鐵壁士兵身上取得7個鐵壁士兵辨識牌。", description = "<class>，這是場野蠻的戰爭!我們為了阻止污水哥布林繼續擴張，失去了許多的同胞。\n\n這些士兵英勇犧牲，該得到應有的尊重。至少我們得通知他們的親人。\n\n也許你可以收集他們的辨識牌，讓我們可以聊表致敬之意。", progress = "即使是戰爭，也該有所禮儀分寸。", completion = "&lt;name&gt;，你為這些士兵做了很大的貢獻。我們現在該做的，就是別讓他們白白犧牲。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32157] = {title = "好的哥布林...", objective = "在污水灘和附近的區域殺死10個污水哥布林。", description = "<class>，我們不能原諒喀撒朗所受的摧殘。 唯一的解決辦法 ，就是消滅污水哥布林在這裡的行動。\n\n這都是為了潘達利亞與聯盟的大義。到污水灘去殺掉他們!部落一定會過來幫忙那些哥布林。\n\n消滅他們!", progress = nil, completion = "&lt;class&gt;，做得好! 我們遲早會把部落趕出這片大陸的。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32158] = {title = "兩階段計畫", objective = "在快斧木材場殺死碎木大師派克。", description = "<class>，這裡的慘狀大多是碎木大師派克造成的。\n\n謠傳他為了加快工作速度而改造了伐木機，無視它們對周遭造成的損害。\n\n可想而知，那些樹木被砍伐的時候一定痛苦萬分。\n\n所有治療的第一階段都是認清問題。第二階段就是消除問題。", progress = nil, completion = "&lt;name&gt;，做得太好了!森林現在可以開始重生的過程了。死亡會帶來新生，我們也再度得到保護自然的機會。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32164] = {title = "野獸大師的狩獵:鶴", objective = "取得5根純淨的金色冠羽和一根純淨的黑色冠羽。", description = "除了圈套，你還得到了一些獵鶴的建議:\n\n喀撒朗蠻荒裡最優良的鶴不在乎食物這種小東西。如果你想把牠們從森林裡的藏身處給誘出來，就得利用牠們的情緒。\n\n西邊的赤吉搖籃和納松尖塔兩地都有許多的鶴。拔一些鶴的羽毛，然後放在紅鶴寺附近明顯的地方。你的獵物就會主動來找你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32165] = {title = "野獸大師的狩獵:虎", objective = "取得25塊完好的犛牛臀肉。", description = "除了陷阱，你還得到了一些獵虎的建議:\n\n老虎的食慾很旺盛，可是這座叢林裡不容易找到大型的獵物。如果你想把年長的老虎誘出牠們的藏身處，你得準備一份誘人的大餐。\n\n在蟠龍脊的另一頭，你可以找到一群犛牛。殺掉牠們，把牠們的肉拿到叢林外圍，設好陷阱，然後等待。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32166] = {title = "野獸大師的狩獵:蟹", objective = "從仰加印古的仰加村民身上取得30條惡臭腐爛的魚", description = "除了螃蟹箱，你還得到了一些捕蟹的建議:\n\n螃蟹是奇特而古老的生物，動機與我們大異其趣。\n\n小螃蟹很好找、也容易抓，可是大螃蟹會躲在沙下遠離危險，不讓我們抓到。我們得利用味道來引誘牠們出來。\n\n西南方的仰加村民在吃魚之前會先讓牠們發酵。只要準備足夠的臭魚，你就能抓到巨大的螃蟹。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32170] = {title = "古鶴的殞落", objective = "到喀撒朗蠻荒的喀撒朗海灣找獵人布雷克。", description = "鶴已經倒下了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鶴靈\n\n您還會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32171] = {title = "古虎的尾聲", objective = "到喀撒朗蠻荒的喀撒朗海灣找獵人布雷克。", description = "老虎已經倒下了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n虎靈\n\n您還會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32172] = {title = "巨大的勝利", objective = "到喀撒朗蠻荒的雄獅灘跟獵人布雷克交談。", description = "螃蟹已經倒下了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n蟹靈\n\n您還會收到：\n\n次級好運符咒"}
