MultiLanguageQuestData['tw'][32175] = {title = "暗月寵物對戰!", objective = "在寵物對戰中擊敗傑瑞米‧菲索。", description = "你準備好試試自己寵物的本領了嗎...?", progress = nil, completion = "我得說，你表現得真好!", rewards = "您會收到：\n\n暗月寵物用品"}
MultiLanguageQuestData['tw'][32185] = {title = "野獸大師的獵物:虎", objective = "把喀撒利年長猛虎帶給獵人布雷克。", description = "年長的老虎還活著，可是昏迷了。\n\n你應該在牠醒來之前把牠帶給獵人布雷克。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32186] = {title = "野獸大師的獵物:蟹", objective = "把巨型虎鉗蟹帶給獵人布雷克。", description = "巨型虎鉗蟹還活著，可是昏迷了。\n\n你應該在牠醒來之前把牠帶給獵人布雷克。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32189] = {title = "寒碜的陌生人", objective = "与半山市集的巴纳比·弗莱彻谈一谈。", description = "今早，一个戴着尖帽子的怪家伙跑来推销一些特别的种子，还声称那是魔法种子。\n\n其实我并不介意有点竞争——毕竟生意就是生意——可这位先生长得……十分寒碜。噢，他还散发着很浓的恶臭。\n\n你能去查查这个人，看看他是否可靠吗？他就在坚·铁掌那边试吃呢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32190] = {title = "前往魔古岬", objective = "到魔古岬找攝政王洛索瑪‧塞隆。找制霸岬的塔克塔克送你過去。", description = "你好，<class>。在我們忙著保衛這個據點的時候，攝政王洛索瑪‧塞隆率領研究隊往北進入了崑萊峰。\n\n不幸的是，他們似乎遇到了麻煩。\n\n大酋長卡爾洛斯‧地獄吼已經親自前去援助，但是他需要額外的支援。\n\n往北進入崑萊山脈，找塔克塔克送你過去。", progress = nil, completion = "&lt;class&gt;，你好。我們是考古探索隊，奉命來挖掘這些遺跡的。我們沒想到這裡到處都是危險的魔古。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32191] = {title = "遠古守護者", objective = "殺死5個考倫守護獸。", description = "在魔古襲擊我們的偵察隊之前，我們在北邊的遺跡找到了零星散落的聖物。\n\n我想收集一些樣本，可是我們應付不了魔古的看門狗兵馬俑。\n\n如果你可以把它們清出這個區域，我們就能繼續進行研究。", progress = nil, completion = "啊，做得好！解決守護獸之後，我們就能安全地挖掘這片遺跡。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32192] = {title = "血脈", objective = "殺死考倫看守者，救出6名制霸法師。", description = "我們成功趕走了魔古衛兵跟他們的走狗，可是偵察隊裡的許多血精靈就沒那麼好運了。\n\n我們還有許多人被困在北邊的遺跡裡。我們正在想辦法救出他們，不過我認為可能有更直接了當的方式。\n\n到遺跡去，殺死看管每個犯人的看守者。如果我的直覺是對的，這樣就能救出我們的同伴。", progress = nil, completion = "我們血精靈一直對部落忠心耿耿。近來我開始思考，我們在卡爾洛斯的領導下能得到些什麼。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32193] = {title = "前往魔古岬", objective = "到魔古岬找布萊恩‧銅鬚。找雄獅灘的芬妮‧角旋送你過去。", description = "數天前，探險者協會派了一支探勘隊前往北方。\n\n從那之後我們一直沒接到他們的消息，要是我知道大夥沒出麻煩的話，我晚上會睡得安穩點。\n\n我最後聽說的消息是，布萊恩‧銅鬚朝崑萊峰的魔古岬去了。\n\n過去找他，然後回來報告他們的狀況。有需要的話，芬妮可以送你一程。", progress = nil, completion = "這些文物一定有數千年之久了。你有見過這麼古老的嗎?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32194] = {title = "宿怨", objective = "從銀月符文尋者、制霸法師或制霸騎士身上取得5個考倫文物。", description = "探險者協會來這裡挖掘遺跡，我的職責就是保護他們。\n\n我們抵達的時候，發現這裡到處都是血精靈。顯然部落和我們一樣對魔古有興趣。\n\n這是個削減敵方人數的好機會，還能奪走他們研究的成果。\n\n殺死任何你在遺跡裡遇到的血精靈，把他們挖到的東西都帶回來。", progress = "這些血精靈在找什麼?", completion = "&lt;class&gt;，做得好。我就知道你可以完成這個任務。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32197] = {title = "神秘肉塊", objective = "從本地的野生動物身上取得7個大塊的神秘之肉。", description = "我們接到了一大堆的抱怨，說女頭目都把好康的留給自己，剩菜才分給別人。\n\n我私下跟你說，他們可能說得對。我都還沒有她吃得好呢!\n\n我們需要一種瑟席克可以大量製作的玩意，來掩飾這邊的食物有多難吃...\n\n我想到了!神秘肉塊!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32198] = {title = "一塊魔法飛行王國的...垃圾", objective = "和巴納比‧伏萊齊交談，獲得更多關於傳送門裂片的消息。", description = "在我們開始做生意之前，依照規定我必須告訴你，我是個酗藥水成癮者，正在接受戒除藥水的治療。\n\n好啦，講完了，我們來談談傳送門吧!\n\n你知道，城市裡的那些大傳送門－不分日夜運轉的那些－會漏出大量的魔法能量。這些能量會在傳送門的外緣結晶，一般都被當成沒用的垃圾。\n\n可是我在達拉然的下水道...呃，休息的時候，發現這些結晶裂片仍然具有能量。\n\n有興趣嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n不穩定的傳送門裂片"}
MultiLanguageQuestData['tw'][32200] = {title = "札突爾的危機", objective = "殺死札突爾裡的12名食人妖。", description = "<name>，我拜託你的事情可說是滅族屠殺，但是這個任務非完成不可。\n\n為了大家好，找出村子裡還有海灘上的食人妖，殺光他們。", progress = nil, completion = "今天流了太多血了。&lt;name&gt;，這是我的責任，不是你的。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32201] = {title = "墓況嚴峻", objective = "殺死10個衫織守墓者、衫織撕魂者或衫織喚雷者。", description = "魔古部隊集結在白骨之廷，日夜不休地進行雷霆儀式。\n\n若我們想成功奪下這座島嶼，便不能讓他們佔據這個戰略要點。\n\n必須消滅他們。", progress = nil, completion = "了不起。魔古絕對難忘這次慘痛的教訓。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32202] = {title = "消灭巨魔", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32203] = {title = "消灭魔古之魂", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32204] = {title = "污刃威脅", objective = "殺死10名污刃薩烏洛克", description = "伊加路克峭壁上到處都是薩烏洛克。這些野獸攻擊我的手下，並將疾病散播到鄰近的水域與野生動物身上，干擾我們的行動。\n\n削減他們的數量，<name>。一旦部落完全掌控這座島，我們便能找出永久的解決辦法。", progress = nil, completion = "總有一天，這座島會落入部落手中，我只希望到時薩烏洛克已經被消滅殆盡。\n\n&lt;埃薩冷笑了一下。&gt;\n\n至少他們也攻擊聯盟。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32206] = {title = "這樣是不行的", objective = "在征戍台殺死8名贊達拉食人妖。", description = "這裡的贊達拉非常厲害，<class>。別小看他們。若因為對方不使用刀劍就掉以輕心，我們將受到極大的損失。\n\n每天都有更多的贊達拉來到這裡，帶來傳承數百年的魔法知識。我們必須盡快處理這項威脅。\n\n幫助我們肅清這塊區域，<class>。也許我們可以從他們身上學到一點東西。", progress = nil, completion = "你居然能輕易地除掉他們，真是了不起。也許，你正是他們不可低估的對手。謝謝你的幫忙，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32207] = {title = "除掉馴獸師", objective = "擊敗獸園裡的10名贊達拉食人妖。", description = "在獸園裡，你會遇到幾個贊達拉軍隊裡頭最有才能的馴獸師。他們擅長以斧頭、野獸與利爪殺戮敵人。這裡也是他們訓練騎兵的地方。\n\n我們需要你在食人妖騎乘魔龍加入戰場前，殺掉每一個你在獸園裡所能找到的食人妖。", progress = nil, completion = "訓練有素的贊達拉喚獸者乘著坐騎馳騁在戰場上時，足以一抵二十。你先發制人的攻擊拯救了許多生命。謝謝!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32208] = {title = "電容上限", objective = "與鬼鐵礦坑裡的3台閃電鑽孔機互動然後摧毀它們，並殺死冶煉統領魔諾汗。", description = "這裡的北方礦坑被用來開採鬼鐵礦石，並在礦石中灌注閃電能量。\n\n我們得摧毀開採礦石的鑽孔機。普通的攻擊對這種機器無效，但是適當的方式能使其超過負荷。\n\n對了。到了那裡，順便除掉礦坑作業的負責人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32209] = {title = "拯救斥候!", objective = "從鬼鐵礦坑裡救出三名被俘虜的奪日者密探，並殺死冶煉統領魔諾汗。", description = "礦坑裡出現重裝魔古，可見那是一個很重要的地方。不過，我們需要收集更多關於他們活動的資訊，因此我們派遣密探到礦坑裡監視他們。\n\n可惜，許多密探都被俘虜了，而且我們發現有些人在礦坑裡受到嚴刑拷打。你得去救出他們 - 那些人不該遭遇這種命運...\n\n還有，救出他們之後，殺掉那些囚禁他們的魔古。別心軟，$p!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32210] = {title = "Kill mogu boss for key, use object behind jumping puzzle", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n奪日者獎賞"}
MultiLanguageQuestData['tw'][32211] = {title = "暴风领主纳拉克", objective = "[PH] Kill Nalak [Log Description]", description = "[PH] Kill Nalak [Description]您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32212] = {title = "襲擊札布圖拉", objective = "完成襲擊札布圖拉。和洛索瑪‧塞隆交談以展開攻擊。", description = "<class>，我們在海岸線的偵察帶回了關於這座島嶼的寶貴情報。\n\n然而，如果我們不朝大陸邁進，是不會有收穫的。\n\n我已經組成了一支最精英的飛行作戰隊伍來進行攻擊。\n\n我希望你加入這場攻勢。像你這樣的勇士可以在關鍵時刻扭轉局勢。\n\n當你準備好進攻時，和我說一聲。", progress = nil, completion = "很好!勇士，你辦到了!\n\n我們會如同浪濤般橫掃這座島嶼，同時為我們的同胞迎來嶄新的命運。而你，英雄，就在浪濤的浪尖上。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32213] = {title = "宿敵", objective = "殺死雷王島上的10名祈倫托成員或玩家。", description = "珍娜和祈倫托以為這次又可以把我們趕出這裡?我才不會乖乖的什麼都不做，讓達拉然的舊事重演!\n\n這次我們要主動反擊!換我們將他們趕出去...\n\n前往紫羅蘭高崗殺死任何一個你找到的祈倫托密探。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32214] = {title = "污水滲透者", objective = "在制霸岬與污水灘附近殺死10個軍情七處破壞者。", description = "一個人在路上走著走著、結果聽到後面有人跟蹤你，是世界上最可怕的事了。我發誓我在這邊到處都聽見背後有聲音!有人在監視我們!\n\n我覺得整個海岸都有間諜埋伏著!\n\n我改良了我們的紅外線護目鏡技術，要讓他們的賊兮兮活動畫下句點。沒錯，賊兮兮活動!現在我只需要你來測試一下!你如果發現了間諜，儘管解決掉沒關係。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32215] = {title = "兇憎祭儀", objective = "摧毀贊達拉獻祭壇。", description = "贊達拉對我的族人進行惡毒的儀式!一定要阻止他們!\n\n探究札突爾的中心，摧毀他們的祭壇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32216] = {title = "痛苦的翼手龍", objective = "釋放受折磨的嘯天龍。", description = "贊達拉把他們的嘯天龍寵物當成惱人的小禍害，用暴力與折磨讓牠們服從命令。\n\n我能聽見其中一頭龍受到折磨所發出的痛苦聲音。\n\n到札突爾找到那隻受折磨的嘯天龍，從囚禁牠的人手中救出牠。", progress = nil, completion = "什麼?!牠殺了自己的主人?太好了。這些嘯天龍比我想得還有鬥志。&lt;race&gt;，謝謝你幫忙救出這頭龍，部落少了一個威脅，贊達拉又多了個敵人。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32217] = {title = "邪恶供品", objective = "摧毁6份赞达拉供品。", description = "赞达拉缚灵者通过献祭仪式来取悦神灵和他们的邪神。我们的人民也成了这些黑暗仪式的牺牲品。\n\n把你在赞图尔帐篷间找到的任何供品全都摧毁，这样一来，我们也许就能让献祭无法如期进行。", progress = nil, completion = "腥風血雨緩了下來，至少目前如此。&lt;class&gt;，謝謝你幫忙拖延獻祭的進行。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32218] = {title = "焚屍揚灰", objective = "焚燒8個魔古木乃伊。", description = "這裡在白骨之廷的魔古正藉由復活他們的死者以壯大兵力。\n\n我們不能讓他們復活那些死去的戰士。\n\n用這把火炬燒掉你能找到的魔古木乃伊。我們要在敵人有機會爬起來之前消滅他們。", progress = nil, completion = "他們的死者永遠安息了，謝謝你，&lt;name&gt;。做得好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32219] = {title = "冷血石獸", objective = "摧毀8個墓穴守護者。", description = "我們持續進攻白骨之廷。我們的進度依然緩慢，但確實有進展。\n\n不幸的是，我們接到數起報告說，有麒麟獸石像突然活過來了。我不能讓這些麒麟獸威脅到我的研究隊。\n\n到白骨之廷毀掉所有能找到的麒麟獸雕像。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32220] = {title = "靈魂也屈服", objective = "拯救6名奪日者斥候或白銀誓盟斥候。", description = "我們朝白骨之廷發動攻擊，但我害怕我們只是讓部隊白白犧牲，成為他們可怕儀式的祭品。\n\n魔古不只殺掉囚犯，還會奪取他們的靈魂灌注到石像機關裡，或是將死者變成幽靈般的戰爭工具。\n\n囚犯是部落或聯盟並不重要，重要的是我們不能讓魔古繼續壯大下去。\n\n進入墓穴，救出還活著的囚犯。", progress = nil, completion = "謝謝你，&lt;name&gt;。你的英勇行徑讓我卸下心頭的重擔。\n\n我會永遠記得你今天的努力。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32221] = {title = "灣岸突擊", objective = "在污水灘和附近的區域殺死10個鐵壁部隊，包括軍情七處破壞者。", description = "我們的木材補給持續受到雄獅灘的攻擊威脅。\n\n我們擋得住攻擊，然而是時候讓他們瞧瞧我們的能耐了!\n\n過去海岸那裡，打破他們的腦袋!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32222] = {title = "懸賞：首席工程師榫扳", objective = "在污水灘的邊緣殺死首席工程師榫扳。", description = "目標因為對污水哥布林犯下的罪行而遭到通緝!\n\n首席工程師榫扳最近一次現身，是在污水灘的外圍建造類似巨大蜘蛛坦克的東西。\n\n接近時要格外謹慎。\n\n消滅榫扳可獲得重賞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32223] = {title = "懸賞:中尉伊森·傑科布森", objective = "在快斧木材場南邊的一座島嶼殺死中尉伊森·傑科布森。", description = "目標因為對制霸岬部隊犯下的罪行而遭到通緝!\n\n中尉伊森·傑科布森率領地面部隊，對污水的採木活動發動數起攻擊。\n\n最近一次出現時，正在佔領快斧木材場南邊的一座島嶼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32224] = {title = "打倒那些亡靈!", objective = "殺死15名甦醒的古代亡靈。", description = "你見到墓地裡那些遊蕩的鬼魂嗎?\n\n它們是甦醒的古代亡靈，被喚回世上的魔古亡魂。\n\n它們憤怒時攻擊快狠無聲，而且它們的數量日漸增加。\n\n這些亡靈不屬於這裡。消滅他們，把他們送回墳裡。", progress = nil, completion = "做得漂亮，&lt;class&gt;。這對我們的進攻大有裨益。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32225] = {title = "喚雷", objective = "阻止衫織喚雷者的儀式。", description = "在墓地裡頭，西邊墓穴最深處的廢墟裡，雷王最強大的巫士正以猛爆的電力為閃電之柱充能。\n\n我們懷疑這個武器是要用來摧毀曦尋者之岬要塞的。\n\n事不宜遲，你得立即阻止他們的儀式。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32226] = {title = "進入墓地", objective = "在崇者大廳使用古拉的咒卷，然後擊敗『回煞魔』古拉。", description = "聖匣守護者今天外出採集!\n\n研究員每天都會找到新的古物進行研究與分類。\n\n最近，我們的一位探險家在白骨之廷發現這個卷軸。\n\n我相信這個咒卷能用來召喚墓地的死者。假如我的魔古語沒有生疏的話，我建議你到崇者大廳的最後一間房間使用這個咒卷。\n\n你願意去測試我的理論嗎?", progress = nil, completion = "太好了，你證實了我的理論!謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32227] = {title = "防範未然", objective = "跑到12隻嘯天龍寶寶身邊驚嚇牠們。", description = "贊達拉的坐騎小時候體型沒那麼大，也不像長大後如此兇殘忠心。\n\n如果你能將一些嘯天龍寶寶從海灘嚇跑，也許牠們就有機會可以度過真正的生活。", progress = nil, completion = "&lt;race&gt;，你回來了。我希望這些小嘯天龍可以不受那些食人妖的虐待，以牠們應得的方式生活。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32228] = {title = "戰慄沼澤", objective = "殺死強力魔暴龍。", description = "沼澤裡有一隻龐然巨獸。雖然它還沒有前來攻擊我們，但這樣的好運不可能持續太久。\n\n在牠為了填飽肚子而敢於進犯我們之前，率先擊敗牠。", progress = nil, completion = "你不是等閒之輩。日後我必定還有需要你幫助的地方。\n\n改天記得來找我，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32229] = {title = "消灭游荡的巨魔战斗小队", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32230] = {title = "贊達拉巨像", objective = "摧毀贊達拉巨像。", description = "食人妖在南方道路上部署了一隻巨大的傀儡，擋住了我們的道路。去將它料理乾淨，<class>。", progress = nil, completion = "你如期達成我交付給你的使命。\n\n做得好，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32231] = {title = "在黑暗中寻找光明", objective = "重新点亮阴惨泥沼中的8支火炬。", description = "在阴惨泥沼中存在着某种黑暗法术，就连我们的魔法之光都能扑灭，我们的斥候只得艰难的辨识方向。\n\n当你在泥沼中穿行时，重新将你所找到的所有火炬点燃，从而为我们的兄弟们照亮道路。或许它们还能帮你找到回来的路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32232] = {title = "裡頭的才重要", objective = "摧毀征戍台的守護者大庫。", description = "我在最後一次偵察任務中注意到一件怪事。一群贊達拉對一個非常大的哨衛進行儀式。他們可能試圖重新喚醒它。\n\n我們得阻止這個儀式並摧毀哨衛。東西凡是那麼大都不是好現象。\n\n我已派遣一名斥候去探查他們的行動，與她碰面並想辦法阻止贊達拉。", progress = nil, completion = "我的擔憂是正確的。幸好你在守衛注滿魔法之前阻止他們。\n\n做得好，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32233] = {title = "繳械行動", objective = "從征戍台偷走7把羅亞附靈之刃。", description = "看看四周，<class>。你看到了什麼?我看到了一個機會。\n\n施法者在這裡將強大的魔法灌注到贊達拉的武器中，彷彿利刃還不足以將最強壯的仇敵碎屍萬段。\n\n我從偵察中發現武器周圍沒有部署太多守衛，你可以從這裡下手...\n\n假如能偷來幾把武器，我們便能加以利用。至少，這讓敵人少了幾把利器。", progress = "怎樣?你找到了什麼?", completion = "漂亮，&lt;class&gt;!\n\n這些武器本身就很嚇人，更別提灌注在它們身上的魔法。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32234] = {title = "知識就是力量", objective = "從征戍台周圍取得6個儀式文物。", description = "這裡的贊達拉練習各種魔法。想擊敗魔法之前我們得先了解它，<class>。\n\n他們擅長操縱秘法與暗影。我希望學習他們是如何辦到這些其他人辦不到的事。\n\n我相信在他們的儀式文物中可以找到我追尋的答案。帶一些你發現的文物給我，保證你會得到豐厚的報酬。", progress = "找到文物了嗎?", completion = "事情辦得很好，&lt;class&gt;。了不起。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32235] = {title = "有閃光!啊啊啊!", objective = "用污水燃燒瓶摧毀6架天火旋翼機X2。", description = "地精帶來了他們的飛行裝置。給我把天空掃蕩乾淨!\n\n不管你用什麼坐騎，飛上天去把那些脆弱的玩意打下來。\n\n你可以用我從哥布林盟友那邊「獲得」的這個烈酒。拿它來擊落旋翼機比被那些綠色的麻煩鬼灌進肚子裡有用多了。", progress = nil, completion = "哈!簡單的機器玩具比不過一瓶正中目標的烈酒。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32236] = {title = "蟲滾開!", objective = "用「蟲滾開」噴霧器噴灑5隻激動的岩蛛，並且消滅12隻岩片蛛。", description = "洞穴裡爬滿了討厭的岩蛛!牠們把礦工跟礦石都吃光光了，這樣是怎麼會有工作成效呢?!\n\n看來這是個測試我的新發明「蟲滾開」的好機會。你只要把這玩意噴在岩蛛身上就可以了。牠們討厭「蟲滾開」，而且這個似乎不會對礦工造成太多的長期副作用!\n\n哪會有什麼問題呢?\n\n把這個噴霧器拿去，開始工作吧!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32237] = {title = "珍貴的資源", objective = "在輪滑油井和附近的區域旋緊8個故障的閥門。", description = "<name>，我們這裡的問題，就是好東西太多了!\n\n我們的鑽油平台來不及處理從地底抽出來的油料!油都從零件的縫隙噴出來了!更準確的說，從閥門噴出來了。\n\n我一直忙著修理閥門，可是我一修好，它們又壞光了。\n\n感覺好像有人在跟蹤我...不過這想法太離譜了...\n\n也許你會好運點。把閥門旋緊，數量越多越好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32238] = {title = "萬能遙控爆炸", objective = "在快斧木材場和附近的區域破壞9個鐵壁機械搗碎機。", description = "機械搗碎機是個大麻煩，不過我想我可能有解答了!\n\n我給自己做了這個萬用遙控器，不過我似乎找到了一個特定的頻率，可以產生有用的效果!\n\n顯然這個頻率可以削弱它們的護甲!\n\n用這個遙控器讓它們變弱，然後狠狠揍一頓!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32242] = {title = "埋藏的秘密", objective = "到恆春谷的先祖高地找芬萊爾‧銀棘。", description = "我聽說魔古曾經擁有幾百個秘密兵器庫，裡面都是能劈天裂地的武器。\n\n魔古軍隊準備作戰時，敵人的心中會充滿恐懼與害怕。\n\n這就是我來潘達利亞所尋求的知識!\n\n我派了一支探索隊調查西邊的遺跡，可是他們的動作慢得像笨蛋一樣!\n\n去找他們的領袖，芬萊爾‧銀棘。告訴他，我要馬上見到成果。", progress = nil, completion = "大酋長派你過來的?他怎麼說?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32243] = {title = "考倫力量的來源", objective = "從考倫織法者身上取得1個煞化之爪。", description = "喲，你好啊！你有沒有看過像這樣的雕像呀？真是迷人！\n\n我剛才正沿著遺跡往上偵察，在最上頭的地方發現有意思的玩意。\n\n我沒辦法靠得太近，不過我想那可能是個魔古雕像，只不過它會動！\n\n我沒辦法越過那些麻煩的血精靈，可是你看起來有辦法。\n\n妳可以上去那裡，幫我帶些有意思的東西回來嗎？", progress = "你在上頭有找到什麼嗎?", completion = "喔，老天，瞧瞧這個玩意!", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32244] = {title = "考倫", objective = "從考倫織法者身上收集考倫聖典。", description = "這些兵馬俑看守者令人生畏，可是比起我們在遺跡頂端發現的生物還差得遠了。\n\n我們有幾個倖存的斥候回報說，他們在北端的最高處發現某種魔古法師。\n\n他使用的魔法是我們前所未見的。\n\n我們得從這個生物身上盡可能地獲得情報。殺死他，把找到的任何東西帶回來給我。", progress = "你有什麼發現嗎?", completion = "很好，這太了不起了!我們來這裡就是想找到這樣的文物!", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32246] = {title = "和斥候會面", objective = "到喀撒朗蠻荒的喀撒朗海灣找斥候琳娜。", description = "自從迷霧散去以來，已經過了兩個月。為了幫艦隊尋找合適的登陸點，聯盟的斥候已經在喀撒朗蠻荒的海岸與部落的部隊交戰。\n\n和斥候琳娜會面，幫忙鞏固登陸點。", progress = nil, completion = "&lt;class&gt;，你的時間抓得真準。烏瑞恩王正要登陸，我們的全體艦隊很快就會跟上。", rewards = "這個任務線能解鎖：\n\n每日任務：雄獅灘\n\n您還會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32247] = {title = "人中之王", objective = "陪同瓦里安‧烏瑞恩國王找出卓特曼元帥和希爾達‧角旋，並且殺死25個部落成員。", description = "沒時間浪費了，我們得找到卓特曼，守住海灘。\n\n我們也該去看看矮人，探險者協會雖然很強，但畢竟不是軍隊。他們應該就在北方的懸崖邊上。\n\n為了朋友，也為了聯盟，<class>，我們出發吧。", progress = "聯盟會成為潘達利亞抵禦部落的盾牌。", completion = "我對這個地點很滿意，是時候讓整批艦隊登陸了。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32248] = {title = "耐心試煉", objective = "進入「耐心試煉」事件，向瓦里安‧烏瑞恩國王報告。", description = "瓦里安國王需要能左右戰局的冒險者，協助他了結泰蘭妲‧語風與據守紅鶴寺的部落特遣隊之間的對決。\n\n立即向他報告!", progress = nil, completion = "&lt;name&gt;，很高興又見面了。\n\n我們手邊的局面很微妙，下一步必須謹慎處理。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32249] = {title = "和斥候會面", objective = "到喀撒朗蠻荒的部落登陸點找斥候羅可菈。", description = "自從迷霧散去以來，已經過了兩個月。為了幫艦隊尋找合適的登陸點，部落的斥候已經在喀撒朗蠻荒岸外的一座小島與聯盟的部隊交戰。\n\n和斥候羅可菈會面，幫忙鞏固登陸點。", progress = nil, completion = "你正好趕上。大酋長要登陸了。等這個據點通過他的檢閱，部隊就會跟著過來。", rewards = "這個任務線能解鎖：\n\n每日任務：制霸岬\n\n您還會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32250] = {title = "大酋長之力", objective = "陪同卡爾洛斯‧地獄吼找出血衛士葛羅塔許和格里斯‧輪滑，並且殺死25個聯盟成員。", description = "<class>，跟我來!我要檢閱這座島嶼，確保我的登陸部隊有好好完成他們的工作。\n\n血衛士葛羅塔許應該在島嶼北邊的某處，尋找適合建立要塞的地方。哥布林探勘隊也已經往東邊的海岸尋找油料了。\n\n讓我們粉碎弱不經風的聯盟，為部落拿下這座島嶼!", progress = "血吼之斧渴望聯盟的鮮血。", completion = "做得好。我們在這裡站穩了腳步!", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32251] = {title = "暗箭難防", objective = "進入「暗箭難防」事件，向沃金報告。", description = "暗影獵手沃金加入了一隊柯爾克隆斥候，進行大酋長交付的重要任務。\n\n像你這麼尊榮的部落成員當然是歡迎加入，不過你要小心，情況可能很危險。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32252] = {title = "羅亞之靈的使者", objective = "殺死2名羅亞之靈的使者。", description = "你聽說過羅亞嗎?我們不清楚它的全貌，但它似乎是種具有相當程度意識的黑暗魔法。我們不知道羅亞有什麼力量，但我得請你阻止他們的儀式，<class>。", progress = nil, completion = "&lt;name&gt;，我不敢想像你目睹了何種慘況。今天你的勇氣受到了考驗，而你的表現也沒讓部落失望。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32253] = {title = "REMOVE (No Longer Used)", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32254] = {title = "操弄薩烏洛克", objective = "找博學者亞蘭、博學者薩瑞安與博學者凡薩菈報到。", description = "我讓三位博學者躲在伊加路克峭壁監視薩烏洛克，有機會的時候誘導他們對抗魔古。我需要你去找他們，看他們是否需要補給品或協助。\n\n他們躲起來不讓人發現，注意薩烏洛克村莊中閃閃發亮的光柱。", progress = nil, completion = "&lt;大法師仔細聆聽你的報告。&gt;\n\n我懂了。謝謝你的幫助，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32255] = {title = "回收傀儡", objective = "取回四個被偷走的奪日者傀儡。", description = "薩烏洛克不停騷擾邊界，通常我們的傀儡能阻擋他們。不過，有些傀儡卻被擊敗，拖回伊加路克峭壁。\n\n我希望取回那些傀儡。有我在，那些滑溜的蜥蜴休想偷走奪日者的財產。", progress = nil, completion = "這才像話。\n\n謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32256] = {title = "帝國的興起", objective = "到雙月廟找大酋長地獄吼。找制霸岬的塔克塔克送你過去。", description = "大酋長卡爾洛斯‧地獄吼帶著手下的精銳部隊往北前進了。\n\n向他報告我們對抗聯盟接連勝利的消息。\n\n找塔克塔克送你過去。", progress = nil, completion = "你有事要報告嗎?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32257] = {title = "眾神之音", objective = "調查幻變守衛，並取得遠古考倫石板。", description = "動作太慢！？我們為了大酋長已經盡快工作了！\n\n我們必須小心挖掘，把找到的每個物件進行分類，而且當然還要遵守安全規範。他一定得明白！\n\n不過，也許我們很快就有東西可以向他展示了。你看到西邊的那個石像了嗎？我們懷疑那是個石製的古代儲藏設備。現在我們只要想辦法打開它就行了。\n\n如果你願意協助我們進行挖掘工作，請小心行事。", progress = "我們可以處理好這場挖掘任務的。我明白是大酋長派你來的，不過他如果能讓我們好好工作，他就能更快看到成果。", completion = "嗯…很有意思。這個石板一定能透露許多秘密。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
