MultiLanguageQuestData['tw'][32262] = {title = "釋放俘虜", objective = "釋放5名紫羅蘭高崗周圍的奪日者俘虜。", description = "祈倫托做得太過分了! 現在他們抓住了我們的奪日者同伴!\n\n他們不可能同意交換人質的，我們得用自己的方法解決這件事情。\n\n前往紫羅蘭高崗，盡你所能釋放囚犯。千萬別被抓到了，我們不能少了你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32264] = {title = "魔法束缚", objective = "从紫罗兰高地取回吉安娜的褪色法术书。", description = "吉安娜手里有不少强大的魔法神器。她一直把这些东西带在身边，从来不曾让它们远离自己的视线。我对其中一样东西很感兴趣。\n\n那是一本充满知识的书册，在大法师间流传已久。而我却只瞥过几眼而已。\n\n既然我们现在各自为战，从她手里把书卷夺过来也没什么不应该的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32265] = {title = "充能魔格石", objective = "取回一個充能魔格石並將它帶給高階秘法師塞佛。", description = "我們每天派遣間諜進入祈倫托的指揮中心。其中有些人奉命從敵人那裡取得充能魔格石帶回這裡。\n\n他們沒有回來，可是我卻肯定他們已經離開祈倫托的指揮中心了。\n\n搜尋這附近的叢林，尋找可能從運輸過程中遺落的充能魔格石，並帶回來給我，我們會善加利用。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32266] = {title = "實體化的法力", objective = "殺死9名祈倫托法力惡魔。", description = "法力惡魔是一種討厭的生物。體型小容易被低估，卻是我們的施法者的剋星。祈倫托讓紫羅蘭高崗到處都是這些討厭鬼。\n\n我們得謹慎處理，料理一隻很容易，一旦它們聚集起來就棘手了。\n\n前往紫羅蘭高崗削減它們的數量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32268] = {title = "戰術法力炸彈", objective = "在聯盟船艦、聯盟補給船與傀儡儀式上各放置一個戰術法力炸彈。", description = "啊，$p，這正是我在尋找的<race>。我收到另一批戰術法力炸彈，需要將它們放置在東南方紫羅蘭高崗上的關鍵位置。\n\n拿去。我不敢將這種火藥交給一般的士兵。喔... 還有不管怎樣，都別搖晃它們。\n\n將一個炸彈放置在祈倫托的船艦上，另一個放置在他們的補給品上，最後一個放在他們建造的傀儡身上。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32269] = {title = "摧毀防禦", objective = "摧毀6個祈倫托陣地結界。", description = "我們得密切關注祈倫托與他們的日常活動。在正常情況下，我們只要派遣間諜，要他們時時回報消息就可以了。\n\n然而我們遇到了一點困難，我相信你能幫得上忙。\n\n祈倫托陣地結界的法力增強了，沒有人能通過這道結界。如果結界被打破了，我們便能在它們修復好之前，派人潛進去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32274] = {title = "伊加路克的居民", objective = "殺死一名污刃蠻卒、污刃魔龍祭司與一名污刃海龍。", description = "污刃薩烏洛克威脅我們人民的安危，但是全面屠殺他們卻又反應過度了。\n\n比較合理的應對方式是除掉他們幾個部落首領。這樣就不用流那麼多血，他們也會因此而尊重我們的領地邊界。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32275] = {title = "招招致命", objective = "殺死3名贊達拉縛靈者、3名贊達拉喚獸者與3名贊達拉狂豹戰士。", description = "贊達拉將嘯天龍訓練成翱翔空中的兇猛野獸。縛靈者不斷拿我們的族人獻祭。還有，狂豹戰士越來越深入我們營地的中央。\n\n到札突爾找出他們，除掉這個威脅。", progress = nil, completion = "在威脅徹底弭平前我無法得到平靜，可是你的幫忙讓我們離這個目標更近了。&lt;name&gt;，謝謝你。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32276] = {title = "突破城牆!", objective = "與洛索瑪‧塞隆交談，然後攻下城市的下層區，為部落奪回這座城池。", description = "時候到了。我們的軍隊屯營在這裡養精蓄銳，該朝雷王的巢穴推進了。可惜，雷王看來是不會自動打開那扇大門的。\n\n我想我們得自己打一個通道進去。你準備好的時候告訴我一聲，<name>。", progress = nil, completion = "在你的幫助下，我們朝目標邁進一大步。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32277] = {title = "飛上天吧!", objective = "進入電光礦脈。", description = "我們能使用你找到的翼手龍對魔古發動決定性的攻擊。\n\n他們的採礦活動禁不起空中突襲，你的翼手龍是我們唯一能用來飛到那裡的工具。\n\n準備好的時候跟我說一聲!", progress = nil, completion = "幹得好哇。這讓我們有一個大好機會。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32278] = {title = "關鍵行動", objective = "潛入狂濤港，從裡頭打開庭院大門。與陶氏交談以展開任務。", description = "贊達拉的戰艦劫掠島嶼海岸，他們從贊達拉運來士兵與戰爭猛獸來助長雷神的氣焰。\n\n如果我們能攻下宮殿的船塢，便能切斷雷王的補給線，而你們在這島的根基也會更穩固。\n\n我有個計畫，不需要派出全部兵力就能達到目的。", progress = nil, completion = "做得好!毀掉那艘戰艦之後，我們沿海的部隊就不會再受到砲火轟擊。\n\n塔蘭‧祝通知我，影潘將持續監視狂濤港，如此奪日者的人力就能再度分配到各地以展開圍攻。陶氏也會在狂濤港那，她肯定會很開心能再次與你合作。\n\n我們都很感謝你的貢獻，&lt;name&gt;。謝謝你。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32279] = {title = "衫布敗亡", objective = "擊敗衫布。", description = "很久以前，雷神找到了一窩稀有的風暴龍蛋。孵出來的小龍當中有隻叫納拉卡的，生性特別殘暴，因此雷神親自飼養牠。\n\n雷王的僕人衫布正在復活雷神的飛龍納拉卡。\n\n我們必須擊敗衫布，可以的話，阻止他復活這條龍。", progress = nil, completion = "做得好，&lt;name&gt;。衫布的敗亡削弱了魔古的實力，人們將永遠記得你的英雄事蹟。", rewards = "這個任務線能解鎖：\n\n每日任務：雷王島\n\n您還會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32280] = {title = "金铁末世录", objective = "去雷神岛的闪电矿脉击败金铁领主莫诺汗。", description = "你有了一个很好的开端，但现在该是真正进一步干扰他们行动的时候了。\n\n快去矿脉那里干掉金铁领主莫诺汗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32281] = {title = "塑肌者的末日", objective = "去雷神岛的闪电矿脉外击败塑肌者霍古。", description = "那个拷打密探的魔古族，塑肌者霍古就站在矿脉外面。\n\n只有消灭他，才能为我们的密探伸张正义。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32282] = {title = "除掉那些龍", objective = "殺死獸園裡的5隻迅猛龍和10隻訓練有素的細顎龍。", description = "贊達拉的迅猛龍和細顎龍對我們的部隊造成嚴重威脅。牠們是優秀的狩獵者，能長途追逐獵物。出其不意的襲擊往往致獵物於死命。\n\n我要你進入獸園削減牠們的數量，務必在牠們成為訓練有素的猛獸前下手為強。", progress = nil, completion = "我們剛到這座島上便有三名優秀的戰士喪生，被溜進營帳裡的細顎龍給殺了。某些夜晚我還是會聽見慘叫聲。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32283] = {title = "羅亞恐龍", objective = "擊敗一名羅亞語者。", description = "贊達拉找到方法將羅亞灌注到野獸體內，賦予其驚人且致命的力量。\n\n我們得阻止這一切發生。\n\n到獸園尋找一名羅亞語者，殺了他。留意發光的野獸便能找到他們。\n\n我們務必得阻止這種惡行繼續下去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32284] = {title = "有個人你該見見", objective = "到崑萊峰的濱南村找老陳‧風暴烈酒。找制霸岬的塔克塔克送你過去。", description = "$p?我運氣真好，能找到你。\n\n老陳‧風暴烈酒要我把這個東西交給你，而且叫你到崑萊峰的濱南村找他。\n\n他找到了一個你們共同的朋友，而且這個人受了很重的傷。\n\n老陳說找塔克塔克送你過去。", progress = nil, completion = "啊!你收到了我的口信。很好。沃金快死了，我需要你幫他療傷。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32285] = {title = "不眠的軍團", objective = "殺死6個活化戰士。", description = "衫織活化了島嶼中央的雕像，組成了一支大軍日夜打擊我們的防衛。把你看到的每個會走路的雕像都給毀掉。我們的防衛部隊會很感激的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
