MultiLanguageQuestData['tw'][32291] = {title = "山怖之死", objective = "[PH] Kill Shan Bu [Log Description][PH] Kill Shan Bu [Description]您會收到：\n\n完成任務後，你將獲得：\n\n", description = "[PH] Kill Shan Bu [Description]您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32292] = {title = "朝熔爐前進!", objective = "在雷王島上殺死熔爐統領，並從血肉工匠郝古身上取得聖典殘片。", description = "你眼前有一座熔爐，它是魔古鍛造武器的核心。\n\n更遠處的魔古守門人手中握有打開大門的鑰匙，從這扇門可以進入城市的另一區。\n\n該是時候出發了!", progress = "嗯?", completion = "做得好。你今天的作為讓我們朝終極目標又邁進一步。", rewards = "您會收到：\n\n\n\n等級 51–80奪日者獎賞\n\n等級 65–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32293] = {title = "白骨之間", objective = "殺死『白骨工匠』祖恰卡。", description = "我的斥候在伊加路克峭壁西方的一堆白骨之間，看到一個危險的贊達拉。我需要有能力的人去除掉他，你願意接下這個任務嗎?", progress = "完成了嗎?", completion = "身邊有一位值得信賴的男人真好。", rewards = "您會收到：\n\n\n\n等級 51–80奪日者獎賞\n\n等級 70–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32295] = {title = "不尋常的書冊", objective = "和你的惡魔僕從交談，調查這本書的來源。", description = "這本書似乎是用某種既華麗又雜亂的文字寫成的，而且很有懸浮於紙上的異樣立體感。看起來有點像是惡魔語，但所用字符之精細複雜卻又是你前所未見的。\n\n或許，你的惡魔夥伴能告訴你更多詳情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32296] = {title = "雷王的寶藏", objective = "與陶氏交談以進入雷王城塞。在裡頭將雷神皇宮鑰匙交給她以展開限時的奪寶任務。", description = "我的斥候回報，許多雷神的古墓寶藏被帶到城塞裡頭。我們想從一處隱密的下水道進入攔截，卻被一道門給擋住了。如果我們想成功奪寶，就得從雷神最信任的軍官身上取得鑰匙。\n\n如果你拿到鑰匙，請帶回來給我。\n\n奪寶過程中你搶到的寶藏都歸你所有，我只是不想讓這批寶物落入雷神手中。", progress = nil, completion = "這次的任務雖然不算失敗，但是我們下次要做得更好。\n\n謝謝提供鑰匙給我們。少了你，我們不可能完成此次任務。", rewards = "您會收到：\n\n陪葬品寶箱之鑰"}
MultiLanguageQuestData['tw'][32297] = {title = "恐角龍對戰魔暴龍", objective = "殺死不肯馴服的恐角龍或魔暴龍身邊進行禁錮儀式的NPC，來中斷儀式。", description = "我們有機會阻止贊達拉的戰爭機器，並且從這個過程中獲得一點樂趣。\n\n獸園裡有一頭身穿護甲的魔暴龍和恐角龍，牠們的心智受贊達拉的符咒所操縱。\n\n進入營帳阻止其中一個禁錮儀式，哪一個都可以，只要殺掉那些企圖禁錮生物的施法者。如此一來，便能讓那隻裝甲生物在贊達拉營帳中瘋狂亂跑。接下來你只要等著看好戲就行了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32298] = {title = "恐龍的力量", objective = "在獸園找到恐龍神像並對5隻迅猛龍、細顎龍、嘯天龍或恐角龍使用它。", description = "贊達拉使用一系列的神像與符咒來操縱野獸。\n\n那一套你會我也會。\n\n我要你去找一些神像過來，對獸園裡的各種野獸進行測試。\n\n仔細記錄野獸們對每個雕像的反應，然後向我回報。\n\n也許我們能找到對付贊達拉的利器。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32299] = {title = "小小的清潔工作", objective = "殺死伊加路克峭壁的顫動穢怪來驅散75塊髒東西。", description = "我坦白告訴你，這不是件光榮的任務。\n\n污刃薩烏洛克將所有的髒東西都排到村莊中央的池子裡。這些髒東西濃稠腐臭，凍凝成會移動的生命體。\n\n薩烏洛克怎麼處理污水池是他們家的事，可是一旦它擴散到村莊以外，我們便不能袖手不管。", progress = nil, completion = "這樣的工作讓我慶幸自己大部分的鼻子都留在墓地裡。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32300] = {title = "拆除炸彈", objective = "拆除部落船艦、占卜水晶與曦尋者之岬的橋樑上的戰術法力炸彈。", description = "嗯，看來普勞德摩爾女士決定以牙還牙。陣地看守者那裡發現好幾個間諜帶著戰術法力炸彈穿越我們的防禦工事。\n\n我倒想看看如果那些炸彈不管用，她臉上會是什麼表情。\n\n找出這些炸彈並拆除它們。我們的看守者回報，一個炸彈在北方部落船艦的附近，一個在主島上的一座橋上，還有一個在曦尋者之岬東邊的占卜水晶附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32301] = {title = "宿敵", objective = "殺死雷王島上的10名奪日者密探或玩家。", description = "想想，我們也曾在同樣的處境! 奪日者趁我們不備的時候，倒戈相向。這樣的事情絕不會重演!\n\n我們已經看清楚他們的真面目。支持卡爾洛斯與他的瘋狂行為，這一切都讓他們非死不可。\n\n殺死每一個你找到的奪日者密探，大開殺戒吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32302] = {title = "摧毀傀儡", objective = "摧毀3名紫羅蘭高崗周圍的祈倫托傀儡。", description = "祈倫托傀儡雖然簡單，卻仍然是一項威脅。\n\n前往紫羅蘭高崗去拆除珍娜那些可憐的戰爭機器。讓祈倫托知道他們是多麼不堪一擊!\n\n祈倫托絕對不會輕忽這項訊息。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32303] = {title = "戰爭利器", objective = "殺死秘法毀滅者。", description = "珍娜還以為輕輕鬆鬆就能打贏這場仗，我要讓她知道，她大錯特錯!\n\n祈倫托帶來了一樣必須摧毀的武器。秘法毀滅者是足以扭轉戰局的大型傀儡。\n\n摧毀這個巨怪能讓普勞德摩爾知道我們的厲害。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
