MultiLanguageQuestData['tw'][32307] = {title = "解讀死亡之語", objective = "帶聖典回主城找術士訓練師。", description = "回主城找術士訓練師，詢問關於這本聖典的更多詳情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32309] = {title = "六位大師的傳奇", objective = "閱讀《大師傳奇》的第一章。", description = "這本書說不定正是我們需要的東西... \n\n你知道黑穫議會的事情嗎，<name>?\n\n打敗死亡之翼後，有六位法力最高強的術士決定共同合作，教導從敵人那兒學來的高深魔法給所有的術士。\n\n看看我身邊的這本書...您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n《大師傳奇》第一章"}
MultiLanguageQuestData['tw'][32310] = {title = "六位大師的傳奇", objective = "閱讀《大師傳奇》的第一章。", description = "這本書說不定正是我們需要的東西… \n\n你知道黑穫議會的事情嗎，<name>？\n\n打敗死亡之翼後，有六位法力最高強的術士決定共同合作，教導從敵人那兒學來的高深魔法給所有的術士。\n\n看看我身邊的這本書…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n《大師傳奇》第一章"}
MultiLanguageQuestData['tw'][32315] = {title = "安杜因的請求", objective = "到七星廟找安杜因‧烏瑞恩。找雄獅灘的芬妮‧角旋送你過去。", description = "啊，你正是我要找的<class>。我收到了一封小王子安杜因送來的緊急信件。\n\n他計畫在恆春谷的七星廟招待他父親烏瑞恩國王和幾位重要的聯盟人士。\n\n根據他最近一次聯絡的內容，那邊發生了什麼很糟糕的事情。\n\n請立刻動身去找他。我在雄獅灘這兒還有些事情要處理，但是我很快就會過去跟你們會合。\n\n你可以找芬妮送你去恆春谷。", progress = nil, completion = "你好，&lt;class&gt;，我們在此還有許多的事情得做。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32316] = {title = "聯盟之心", objective = "打倒6個煞化士兵。如果你跟丟了安杜因王子，到帝國交易所找他交談。", description = "我簡直無法相信會發生這樣的事情，<name>。在潘達利亞發生了這麼多的事情，難道大家還是無法從過去的錯誤學到教訓嗎?\n\n布萊恩的探險隊剛從魔古岬那兒回來，並且帶了一個煞的樣本回來研究。\n\n打從一開始我就不太贊成這個計畫，現在我最擔心的事情果然發生了。\n\n那個煞已經逃離了監禁，我不必跟你解釋太多，你也該知道讓煞進入恆春谷會發生多麼可怕的事情。\n\n我們務必得除掉所有的煞，而且動作要快!", progress = "我們必須保護我們的人、保護這塊土地不受煞的影響。", completion = "我知道你和我兒子一直在努力解決問題，謝謝你主動協助我們在恆春谷的行動。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32317] = {title = "尋找靈魂石", objective = "閱讀裘貝卡的日誌，根據書中的線索找出四個靈魂石碎片。", description = "<name>，拿去，這是裘貝卡‧破影者的日誌。\n\n閱讀她的日誌，分析裡頭的線索，查出她到哪裡去了。\n\n找到她的靈魂石，然後使用它們來找出她的下落。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32318] = {title = "再生需要時間", objective = "收集10根結實的細針。", description = "如果沃金不是食人妖，他一定早就死了。他的再生能力雖然驚人，卻受到劇毒的妨礙。\n\n我們得先把毒給解了，他的身體才有辦法再生療傷。\n\n往東南方的天空飛去，越過秘密鷹巢的山巔，你會在那邊找到刺針妖精，然後把你從他們身上找到的最硬的針帶回來給我。\n\n我要利用那些針來進行針灸療法，排除他身體的毒素，加速他的再生。", progress = "沃金完全是靠我的草藥才得以活命，我不敢離開他的身邊。", completion = "太好了，這些針一定能派上用場。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32319] = {title = "去找索爾!", objective = "使用沃金的爐石找到索爾。", description = "<沃金半睜開眼睛，顫動嘴唇想開口講話，但是卻發不出任何聲音。不過，你還是從他的嘴形認出了這句話。>\n\n去找索爾。\n\n<沃金吃力地將一顆爐石塞進你的手裡，然後就此昏迷。>", progress = "你跋涉千里來找我，<race>。說吧。", completion = "&lt;索爾盯著你交給他的爐石。&gt;\n\n沃金的爐石?朋友，事態真的到了這等地步?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32320] = {title = "部落大家庭", objective = "護送索爾前往回音群島。", description = "很久以前，沃金和我曾經談到這顆爐石。\n\n他認為他的族人有危險。雖然我不清楚在我離開的這段期間到底發生了什麼事情，但至少，我該為朋友盡這份力。\n\n來吧，$p，陪我去回音群島。我們得確保暗矛食人妖沒有受到任何的危險。", progress = nil, completion = "沃金救過我的性命許多次。如今見到我一手創立的柯爾克隆被派來對付他的族人，我心裡的傷痛實在難以言喻啊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32321] = {title = "美猴王", objective = "協助安杜因‧烏瑞恩在帝王谷裡尋找美猴王。", description = "自從部落奪得聖鐘之後，我一直在研究反擊其力量的方法。\n\n我的研究指引我來到這座古墓，而且我要親自進去調查。如果你願意跟我來，我會沿途把我知道的其他事情和你分享。\n\n萬一我們分開了，就到古墓的入口跟我會合。等你準備好出發了，跟我說一聲。", progress = nil, completion = "你來要找美猴王？\n\n我來瞧瞧，你們唱的都是什麼歌。\n\n你是誰？這麼小隻、這麼不好玩？\n\n你要做的事情太笨了！害我想睡覺打呼了。\n\n三個謎語，我來問你，\n\n三個謎語，叫你辦事，\n\n不要遲疑，快快辦好，\n\n我才考慮，是否幫你。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32324] = {title = "尋找信號", objective = "跟隨靈魂石前往黑暗神廟的大門。", description = "靈魂石碎片輕而易舉地在你的手裡合而為一。\n\n但奇怪的是，裡頭並沒有存放任何靈魂。而且，這顆靈魂石好像是在從影月谷的某個地方汲取力量。往東邊望去，你感覺這股力量與山脈連結，通往黑暗神廟的大門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32325] = {title = "入侵黑暗神廟", objective = "在黑暗神廟的主要入口尋找裘貝卡的印記。進入神廟之後，去神廟頂層找裘貝卡交談。", description = "顯然裘貝卡的靈魂石帶你來到了黑暗神廟。\n\n但問題還是存在...為什麼?\n\n剩下唯一能做的就是進入神廟，查清楚他們為何會來到這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32326] = {title = "敵後行動", objective = "利用制霸岬裡的奪日者傳送門來安全的傳送到達納蘇斯。", description = "<name>!你是最適合的人選。\n\n我們知道聯盟把聖鐘藏在哪裡。我們已經派了一名密探進入敵方領地，我們只需要你協助他執行任務。\n\n整裝出發，<name>。你要前往達納蘇斯。", progress = nil, completion = "&lt;name&gt;!納茲格寧姆選上你真是太好了。\n\n部落費了很大的工夫才讓你通過珍娜的陷阱，來到這裡。在距離達納蘇斯這麼近的地方維持幻象的代價相當高昂。\n\n除此之外，達拉然的奪日者冒著失去中立位置的風險來協助部落的這起行動。\n\n換句話說，我們希望你能盡全力表現。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32327] = {title = "達納蘇斯任務", objective = "找出聖鐘。\n\n遇上麻煩的時候，可以使用銀月符咒回到芬萊爾的所在。", description = "聖鐘就在城裡，我們不想鬧出事情，只想拿到神器。我需要你在不被發現的狀況下想辦法進城。這表示不能搭乘坐騎、不能飛行、不能戰鬥。\n\n我可以提供協助。我會用魔法讓你隱身，這麼一來你就能匿蹤行動。我也會給你一個小符咒，讓你在碰到麻煩的時候可以回到安全的地方。\n\n<name>，出發吧。找出聖鐘並做上標記，讓它跟你一起傳送回來。", progress = nil, completion = "&lt;race&gt;，做得好!我就知道你值得信賴。\n\n是時候離開這棵討厭的樹了。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32329] = {title = "我的成果!", objective = "到銀月城找洛索瑪‧塞隆。", description = "啊，$p。大酋長要我派你到銀月城去。\n\n他對洛索瑪的研究進展感到不耐煩，並且認為你在魔古方面的...獨特...經驗會對他們有所幫助。\n\n到銀月城去，叫洛索瑪加快研究的速度。", progress = nil, completion = "大酋長「要求」進度?他的急性子隨著接連的命令越來越具破壞性。\n\n就目前的情況而言，我們用得上你的專長。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32331] = {title = "祈倫托", objective = "使用雄獅灘的傳送門前往紫羅蘭頂閣，與安杜因‧烏瑞恩會面。", description = "$p，瓦里安國王要我派你去達拉然找他的兒子，他認為你可以幫忙協調驅逐血精靈的事宜。\n\n這些「奪日者」效忠於部落，對我們的戰事是一大威脅。\n\n既然現在我們的珍娜‧普勞德摩爾掌管了祈倫托，說服她把部落威脅掃出自己的城市應該不難。\n\n使用雄獅灘這裡的傳送門前往紫羅蘭頂閣，並且盡全力協助安杜因王子。", progress = nil, completion = "朋友，很高興見到你。我在外交方面雖然學到了很多，但我認為珍娜對我的策略瞭若指掌。\n\n有朋友能助我解決這場衝突就太好了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32332] = {title = "第一道謎題:慈悲", objective = "找出美猴王謎題所描述的物品。", description = "你為了一把槌子而喚醒了美猴王，是嗎?先答出三道謎題，你就能一睹此槌。\n\n第一道謎題\n\n  「柔聲唱誦苦痛之謳，\n\n    乃是受難瘸跛之獸。\n\n    越牆彼方行遙之南，\n\n    此獸逃避惡主之喚。\n\n    探索搜尋悲獸下落，\n\n    救其解脫野生琥珀。」\n\n把野生琥珀帶來給我。", progress = "啊，聰明的傢伙回來了。琥珀帶來了嗎?", completion = "啊!琥珀!野生的新鮮琥珀。你殺了牠才拿到的嗎?那是當然的。\n\n即使不受束縛，野生琥珀仍然是個危險的東西，許多性命可能因其而死。\n\n慈悲有眾多的形式，像是尖刺、螳螂人、還有很嚇人的暴風雨。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32333] = {title = "第二道謎題：友誼", objective = "取得金屬佳釀。", description = "你想阻止聖鐘？我們得先有槌子才行。\n\n你想拿到槌子？我們得先當朋友才行。\n\n你想當我的朋友？我們得先拿到金屬佳釀才行。\n\n你想要金屬佳釀？你得先去結義聖壇才行。\n\n你想去結義聖壇？太好了！它就在翠玉林裡，天僧寺的東南方。\n\n到那邊敲響結義銅鐘，順便幫美猴王我帶點酒回來。喔…要酒的話，你可能得打上一架。", progress = "你拿到金屬佳釀了嗎？", completion = "金屬佳釀有勁道、又醇久，大戰之後和朋友共享再適合不過。\n\n當年大帝紹昊和他的美猴王暢飲了許多回。許多的戰役，還有許多的好友。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32334] = {title = "第三道謎題:力量", objective = "在白虎寺打敗挑戰者。", description = "你要的槌子不是鬧著玩，\n\n它像女妖之歌招惹災難。\n\n美猴王面前身手一試，\n\n才能讓你帶回槌子。\n\n白虎寺裡挑戰者到，\n\n大展身手瞧一瞧。\n\n正門右轉下山坡，\n\n挑戰歐克是英雄!", progress = nil, completion = "為什麼要打架?為什麼要當笨蛋?\n\n你找美猴王要強力神器，我得確定到時候你不會膽小哭泣。你以為自己強而有力，可是很多人遇上魔古就逃得不見蹤影。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32335] = {title = "最棒的惡作劇", objective = "聽美猴王的故事。", description = "你已經回答了三個謎題，很好很好。美猴王可不是老糊塗，把自己的把戲告訴每個人。\n\n那可是史上最棒的惡作劇！\n\n你想不想聽槌子和猴子的故事啊？唉啊，我才不管你想不想聽呢！", progress = nil, completion = "看來我們得花個幾天才能追蹤到所有的這些「嘍囉」。\n\n&lt;name&gt;，謝謝你的幫忙。過幾天到雄獅灘找我，我們到時出發去找這些物品。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32336] = {title = "和諧槌柄", objective = "取回和諧槌柄。", description = "從前有個首領叫印古印古，\n\n他喝酒贏了我咕嚕咕嚕。\n\n他把槌子的柄當成獎品，\n\n卻不知道跟猴王喝酒絕對喝不贏。\n\n美猴王得讓槌子遠離聖鐘，\n\n印古子孫拿了槌柄卻不好好運用。\n\n他們一直拿槌柄做惡使壞，\n\n我們得找現任首領拿回來。\n\n往南走到仰加印古，美猴王在那裡等。\n\n只有壞壞才會不帶禮物上門。", progress = "印古是個好猴人。好領袖，好派對，好酒。", completion = "神器不會讓人變得偉大，只會讓人展露自己。好人變得更好、壞人變得更壞，印古十七世就是變得更糟。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32337] = {title = "和諧槌頭", objective = "取回和諧槌頭。", description = "美猴王有槌頭該去哪找的消息了，\n\n拿走它的猴人已經死翹翹。\n\n崑真首領把槌頭代代相傳，\n\n可是兔妖思基吉將它搶了來。\n\n現在兔妖壞壞把槌頭供奉，\n\n因為槌頭太大吞不下口。\n\n我派出王下探尋者往北去尋找，\n\n你往中央平原西邊的山上去找他就好。", progress = "你拿到槌子頭了嗎?", completion = "兔妖碰到不明白的東西，不是供奉起來、就是跟它打一架，或者是逃跑。\n\n我應該送他們幾座我的雕像。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32338] = {title = "和諧油膏", objective = "取得和諧油膏。", description = "傳奇不是與生俱來的，而是塑造的。\n\n你的下個目標就是這樣，一個名叫『刀鋒之王』的魔古。\n\n你會在他的袋子找到，\n\n在你心中歌唱的油膏。\n\n把油膏交給美猴王!\n\n他會讓槌子歌唱!\n\n往北沿著牆走，走到底的時候往左轉。", progress = "魔古能發現這種油膏真是奇蹟。\n\n不過自從世界崩裂以來，發生了太多的事情了。", completion = "嗚喔嗚喔!", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32339] = {title = "重铸钟杵", objective = "获得神圣之杵。", description = "修理时间到了，接着则是搅和时间！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32340] = {title = "掠奪黑暗神廟", objective = "拿走你能拿的所有東西，並抵達凡慾邪窟的盡頭。", description = "趁著阿卡瑪和他的手下在忙著對付惡魔的時候，沒有人能阻止你偷走一、二件法器…您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鑑定"}
MultiLanguageQuestData['tw'][32342] = {title = "靈魂陷阱", objective = "收集3個靈魂陷阱。", description = "我們在遺跡裡辨識出幾件強大的魔古神器。它們把靈魂囚禁在裡面，可能是用來進行某種儀式或召喚之用。\n\n我們還沒有辨明這一類的裝置，急需好好研究它們...這些裝置也許能透露更多魔古束縛靈魂技術的秘密。\n\n去吧，幫我們找些樣本回來，我們才能繼續好好研究。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32343] = {title = "歐古戴的副官", objective = "在歐古戴遺跡裡收集孟督精華與簡立精華。", description = "無能的聯盟已經挖出了兩個極為強大的魔古之靈。\n\n<class>，這些會是我們首選的目標。如果你殺了它們、取回精華，對於我們解開這座奇特遺跡的歷史能有極大的進展。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32344] = {title = "費解之謎", objective = "在歐古戴遺跡裡用秘法寶珠找出異象。", description = "我們在礦坑裡偵測到幾個...異象，是秘法或靈魂之類的，它們正妨礙我們查明束縛靈魂的儀式中所使用魔法的性質。\n\n它們難以捉摸，不過我們成功獨立出其中一個異象的秘法訊號，而且我們有個法師將此訊號附魔在這顆珠子上。\n\n帶著這顆珠子，當你接近異象的時候，它會變得越來越明亮。當你找到異象的所在，你可以用珠子把它引出來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32345] = {title = "我們不是怪物!", objective = "解放14個困擾的奴役之靈。", description = "聖匣守護者以前的名聲可能不太好，但我們不是壞人。我們只是對考古學的觀點和探險者協會不同。\n\n我們偶而會進行一些英雄行徑的作為。所以去吧，解救遺跡裡熊貓人奴隸的靈魂。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32346] = {title = "灾祸猛于鬼！", objective = "击败12个缚魂魔古。", description = "你瞧，我们遇到了一件恶心事儿，要是不能把事态控制住的话，雄狮港的老托德曼非把我们踢出去不可。\n\n帮个忙吧，拜托了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32347] = {title = "驱逐令", objective = "在敖骨打废墟击败10名神圣遗物学会成员。", description = "该死的神圣遗物学会也混进废墟里来了。他们占据了地势较低的地区，并在那里搞起了他们那套装神弄鬼的把戏。\n\n我要你去狠狠踢爆他们的屁股，把他们都赶走！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32348] = {title = "落井下石", objective = "殺死12個雄獅灘的軍事單位。", description = "聯盟以為自己的基地在附近，就能穩穩控制住遺跡。\n\n我們要讓他們認清自己的錯誤。除掉他們的守衛。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32351] = {title = "雷霆迴盪", objective = "到雙月廟找牛頭人酋長貝恩‧血蹄。到制霸岬找塔克塔克送你過去。", description = "啊，<name>，我們又見面了。我聽到了些很棒的消息。\n\n牛頭人的大酋長貝恩‧血蹄來到潘達利亞了。\n\n他正在恆春谷的雙月廟和大酋長卡爾洛斯‧地獄吼還有攝政王洛索瑪‧塞隆會面。\n\n他交代了一個奇特的任務，叫我派個忠心耿耿的部落英雄過去找他，要有本事的...而且口風要緊。\n\n我能想到的人裡，就你最適合了。有需要的話，找塔克塔克送你過去。", progress = nil, completion = "&lt;class&gt;，幸會。制霸岬那邊派你來的嗎?很好，我們有很多事情要討論。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32352] = {title = "風暴前夕", objective = "質問6個煞化蠻兵。", description = "既然是納茲格寧姆將軍派你來的，那我相信你是個辦事很小心的人。\n\n我來到這邊的時候，我發現卡爾洛斯在…實驗…他從北邊山裡找到的某種古老魔力。\n\n他認為這個「煞」可以強化我們的士兵。\n\n不幸的是，目前的結果卻恰恰相反。\n\n我們的士兵陷入失控暴怒之中。過去質問他們，要是他們威脅你的話，做好自衛的準備。", progress = nil, completion = "你擊敗了我的守軍？終於有人能控制他的恨意和怒意！\n\n我需要更多像你一樣有本事的人。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32355] = {title = "和諧之槌", objective = "到征服者之墓找安杜因。到雄獅灘找芬妮‧角旋送你過去。", description = "$p!安杜因王子不知怎麼又擺脫了手下的衛士，他對聖光的掌握越來越熟練了。\n\n他最後被發現的時候，正朝崑萊峰前進。他在帝王谷甩開了我們的法師。\n\n你能找到他嗎?他堅持要找到他所說的那個能與聖鐘抗衡的東西。也許你可以在他舌燦蓮花地說服你回來之前，跟他講點道理。\n\n跟芬妮交談，好搭乘坐騎上山。", progress = nil, completion = "朋友，我很高興你來了，接下來我會需要你的協助。我的父親希望我待在部隊的安全管束之下。\n\n可是如果我在潘達利亞學到了什麼，那就是在正確的時間與正確的地點，只要少數的人就能比發揮比千軍萬馬更大的效果。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32356] = {title = "追踪事件：召唤大使", objective = "目送斥候离开，然后与卢山大哥谈一谈。", description = "我和苏利该出发了。我们会注意寻找白卒留下的一切痕迹并尽快回报。\n\n在海军上将泰勒康复期间，我恐怕只能让你留下来主持大局了。在我们离开的期间，你要尽可能多地多了解这些锦鱼人。我希望当我们回来的时候能得到一份详细的报告。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32357] = {title = "追踪事件：事件完成", objective = "目送斥候离开，然后与卢山大哥谈一谈。", description = "我和苏利该出发了。我们会注意寻找白卒留下的一切痕迹并尽快回报。\n\n在海军上将泰勒康复期间，我恐怕只能让你留下来主持大局了。在我们离开的期间，你要尽可能多地多了解这些锦鱼人。我希望当我们回来的时候能得到一份详细的报告。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32358] = {title = "靈魂之核", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32361] = {title = "追踪事件：事件完成", objective = "目送斥候离开，然后与卢山大哥谈一谈。", description = "我和苏利该出发了。我们会注意寻找白卒留下的一切痕迹并尽快回报。\n\n在海军上将泰勒康复期间，我恐怕只能让你留下来主持大局了。在我们离开的期间，你要尽可能多地多了解这些锦鱼人。我希望当我们回来的时候能得到一份详细的报告。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32362] = {title = "達拉然的命運", objective = "跟珍娜‧普勞德摩爾交談，聽聽她的說法。", description = "珍娜拒絕聽我解釋，父親大人希望我能說動她，但我覺得她還是把我當成小孩看待。\n\n然而你是聯盟的英雄，而且我知道她敬重你的作為。\n\n你能不能想辦法說服她，我們真的需要她的協助?", progress = nil, completion = "英雄，謝謝你的幫忙，我明白了珍娜話裡蘊含的智慧。\n\n希望奪日者別背叛她的信任。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32363] = {title = "遠征崑萊峰", objective = "到卡爾洛夏先遣營地找大酋長貝恩‧血蹄。到制霸岬找塔克塔克送你過去。", description = "牛頭人酋長貝恩‧血蹄又有個訊息要我給你。\n\n看來你讓他留下了深刻的印象。\n\n他和大酋長的先鋒部隊一同往北前往崑萊峰。他們在獨罈集東邊紮了營，也就是卡爾洛夏先遣營地。\n\n最好別讓他等你。找塔克塔克送你過去。", progress = nil, completion = "&lt;name&gt;，感謝你前來。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32365] = {title = "Tracking Event: Epilogue Complete", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32368] = {title = "回憶之酒", objective = "喝下回憶之酒，見證衫‧基恩的過去。", description = "藥酒準備好了，喝吧。", progress = nil, completion = "&lt;class&gt;，你看到什麼了?", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32370] = {title = "崑萊峰遠征", objective = "到咕嚕摩市集找康奈利。到雄獅灘找芬妮‧角旋送你過去。", description = "<class>，榮耀歸於聯盟。雖然步調緩慢，我們在喀撒朗蠻荒與部落的對抗仍有斬獲。\n\n在我們守住前線的同時，我們需要你幫忙進行一場不同的戰鬥，直搗敵人的心臟。\n\n我們在軍情七處的線報來源，情報員康奈利，捎來消息說有一支部落的先鋒部隊正深入崑萊峰的北端。\n\n馬上出發，和現場的情報員康奈利聯繫，查明目前的狀況。\n\n找芬妮讓你直接飛過去。", progress = nil, completion = "&lt;眼前的熊貓人突然用康奈利的聲音說話，讓你猶豫了一下。&gt;小夥子，你終於來了!我一直在等你哪。\n\n這些熊貓人都是些好傢伙，不過他們實在不會調馬丁尼。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32371] = {title = "回憶之酒", objective = "利用柯爾克隆偽裝進入營地，然後喝下回憶之酒，見證衫‧基恩的過去。", description = "<無線電傳來雜音，情報員康奈利接著說起話來。>\n\n<小夥子/小姑娘>，真正的挑戰要開始了。\n\n朝營地中央移動，看看你能偷聽到什麼。", progress = nil, completion = "菜鳥，這麼快就回來了?你查到什麼了嗎?", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32372] = {title = "不再屈從", objective = "殺死10個柯爾克隆監督者、5個柯爾克隆征服者，以及『征服者』古爾塔。", description = "柯爾克隆被訓練為大酋長最忠心最精良的士兵。他們出現在這裡，表示卡爾洛斯害怕有叛亂發生。\n\n沃金和他的族人也和所有的獸人一樣，是部落的一份子。\n\n我們得結束這場佔領行動、解放食人妖。這麼說讓我很難過，但你必須消滅足夠的柯爾克隆，食人妖才能取回他們的城市。成功之後到暗矛要塞找我，我們才能向他們的軍官直接挑戰。", progress = nil, completion = "獸人已經變了。我的部落也變了。我得殺死獸人同胞，直到部落再度成為「我的」部落嗎?我有什麼權利，強迫部落成為以前的樣子?\n\n這是動盪不安的時期，但是現在我必須照顧沃金的族人。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32373] = {title = "领袖的标准", objective = "去迷雾酒肆与拉希奥谈一谈。", description = "我们的熊猫人战役已经发展到了新的阶段。联盟的主力舰队已经登陆了海滩。你们的国王想要牵制部落对这片新大陆的侵略。\n\n加尔鲁什·地狱咆哮带着部落一头扎入了战斗，可瓦里安·乌瑞恩国王的行动对我来说却有点神秘。你有时间吗？我想跟你谈谈你们的领袖。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32374] = {title = "王子的追求", objective = "击败卡桑琅丛林南部海滩上的部落军队，直到你在黑王子阵营的声望达到崇敬。", description = "我的目标就是暂时终止这场代价高昂的战争。在我看来，联盟完全应该获胜。让我看看你在战场上的实力吧。\n\n我不是要你去面对那些抽象的敌人，例如煞魔，而是要你正面对抗你的敌人。\n\n你是否能凯旋归来呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32376] = {title = "前往帝王谷", objective = "到帝王谷找你「銀月城的朋友」。到制霸岬找塔克塔克送你過去。", description = "這份密封的函件是交給你的，同時緊急命令你前往崑萊峰的帝王谷。\n\n這似乎是件大事，如果我是你就會盡快行事。找塔克塔克送你過去。", progress = nil, completion = "啊，很好，你到了。\n\n容我再次為信函的故作神秘而道歉 - 可是卡爾洛斯越來越不相信我們了。我不想讓這起行動因為他的倉卒而失敗。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32377] = {title = "柯爾克隆就在你身邊", objective = "收集1個柯爾克隆頭盔、1個柯爾克隆護甲和1個柯爾克隆靴子，然後將它們合成1個柯爾克隆偽裝。", description = "卡爾洛斯一心一意地要找到聖鐘。他要是為了聖物把崑萊峰給拆了，我也不意外。\n\n大酋長在卡爾洛夏先遣營地召開一場會議，就在我們的北邊。\n\n我得留在這裡監督部隊的動向，所以你得滲透進入他們的營地，偷聽會議的內容。\n\n到卡爾洛夏先遣營地，然後從劫奪者、榮譽守衛和斥候身上偷走柯爾克隆護甲。\n\n這個無線電耳機給你，別聯絡我...我會跟你聯絡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32378] = {title = "開出道路", objective = "殺死10個考倫魔古。", description = "事有輕重緩急。如果我們要俘虜對方的領袖，我們就得削弱他手下的數量。\n\n小心，這些魔古格外危險 - 他們似乎以我們從未見過的方式操控著煞。", progress = nil, completion = "很好，我們應該準備好展開行動了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32379] = {title = "考倫遺卷", objective = "在帝王谷找出考倫遺卷的文件，並且從考倫魔古身上取得考倫密令和密封的考倫神器。", description = "我還沒準備好讓更多的士兵去對抗我們仍不明瞭的敵人。\n\n看你能不能在這個區域找到線索，查出這些「考倫」魔古究竟是什麼，以防萬一這個行動出了什麼差錯。", progress = "你查到任何關於魔古的訊息嗎?", completion = "很好。這裡有相當多的資料可以研究...\n\n我會交代聖匣守護者展開調查。我們一定可以利用這些資訊揭露出更多關於考倫魔古的秘密。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32380] = {title = "最佳人選", objective = "到暴風城那一側的礦道地鐵的畢茲摩鬥陣俱樂部，找臥底情報員湯斯利報到。", description = "如果我們想弄清楚卡爾洛斯在潘達利亞的計畫，我們得找人幫忙。\n\n我心裡有個人選，不過要說服他可不容易。\n\n情報員康奈利以為自己退休了，可是誰都沒辦法離開軍情七處的。我們有個臥底情報員亦步亦趨地跟著他好幾個月了。\n\n目前他偽裝成畢茲摩鬥陣俱樂部的豪賭客，好像是要清一筆舊帳的樣子。\n\n到鬥陣俱樂部和我們的臥底情報員會合。", progress = nil, completion = "跟蹤康奈利的過程有意思極了。那個傢伙是個偽裝大師！\n\n&lt;class&gt;，要說服他加入你還不是最麻煩的，從這些活蹦亂跳的傢伙裡找出他才是不可能的任務。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32381] = {title = "諜對諜", objective = "把粉紅土撥鼠、魔古甜瓜汁和生鏽匕首交給正確的客人。", description = "我可以告訴你那一個是康奈利，可是這樣一來就太輕鬆了!想逮間諜，你就得用間諜的方式思考。\n\n你得先通過測試!\n\n從小處可以觀察到一個人許多的線索，秘密就在細節裡。\n\n我要拿杯飲料讓你送過去。我會告訴你關於點飲料者服裝的一個小細節，接下來就靠你自己了。\n\n選擇要把飲料給誰的時候請小心。如果你給錯飲料，客人會很不高興的!", progress = "當酒保的時候，你能學會觀察每個細節。", completion = "&lt;class&gt;，你的眼力真好!我想你已經準備好和康奈利會面了。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32382] = {title = "深陷其中", objective = "到崑萊峰找康奈利。到雄獅灘找芬妮‧角旋送你過去。", description = "情報員康奈利成功滲透進卡爾洛斯在崑萊峰的營地了!他持續追蹤他們的一舉一動。\n\n康奈利特別要求你協助他收集一些重要的情報。\n\n他還帶了偽裝給你，接近營地前一定要穿上!那裡一定戒備森嚴。\n\n他堅持說，你看到他的時候一定會認得他，說你觀察入微...\n\n過去那裡找芬妮進行空降。", progress = nil, completion = "你來得正是時候。根據我收集到的情報顯示，我認為卡爾洛斯正在尋找某種強大的古代魔古神器。\n\n如果我們弄清楚他在找什麼東西，就能阻止他得到那個玩意!\n\n我們得快點行動，盡量收集資訊。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32383] = {title = "竊聽風雲", objective = "在大營帳裡面、補給區裡面還有小營帳周圍安置巧妙偽裝的竊聽器。", description = "我在營地周圍成功安裝了幾個竊聽器，不過這玩意總是多多益善。\n\n我把竊聽器偽裝成雕像的樣子，完全融入附近的其他神器。\n\n你的偽裝應該可以讓你在營地裡自由行動，只要別靠近那條狗、別在卡爾洛斯旁邊待太久就行！尼諾跟卡爾洛斯可以看穿你的偽裝。\n\n要是你被抓了，我是幫不上忙的，我不能危害到任務！", progress = nil, completion = "做得好！大家總是低估了小傢伙的能耐，他們可是大錯特錯了！", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32384] = {title = "逮住首腦", objective = "在崑萊峰的暗影之墓弱化衫‧基恩，然後活捉他。", description = "我們該行動了。前往暗影之墓，弱化他，然後活捉他。\n\n我得留在這裡，以免卡爾洛斯抵達。一定要拖延他，我們才能帶著東西離開，免得卡爾洛斯一氣之下毀了它。\n\n動作快!", progress = nil, completion = "我們總算逮到了我們的獵物。 \n\n但是坦白講，我實在不曉得我們的下一步該怎麼走。我會試著跟我們盟友的領袖們聯絡，看看他們是否有什麼主意 - 我實在不曉得我們的魔法師到底有沒有辦法從這位魔古俘虜身上套問出什麼。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32388] = {title = "朝令夕改", objective = "去卡桑琅丛林的统御岗哨击败血柄督军。建议你组队前往。", description = "我一直在密切监视一个兽人将军。由于在南贫瘠之地击退了联盟的先头部队，血柄督军获得了加尔鲁什·地狱咆哮的赏识。他现在就呆在统御岗哨的堡垒里。\n\n我很怀疑联盟能否干掉他。可是……你以前就曾证明过我的判断有误。\n\n如果你想干掉他，一定要找几个朋友一起去。记得多带点人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32389] = {title = "雄狮怒吼", objective = "赢得寇魔古寺和碎银矿脉的胜利。", description = "这是一场全球战争，<name>。它不仅波及了潘达利亚，连卡利姆多和东部王国也同样战火频燃。你在有组织的战场上会表现如何呢？我很想亲眼看一看。\n\n我期待听到你从前线带回的报告。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32390] = {title = "狼王的呼嗥", objective = "與怒西昂談話。", description = "透過你的雙眼，<class>，我見證了此地沿岸的慘烈戰事，以及世界各地的大規模對戰。你非常有耐心... 而且消息靈通。\n\n告訴你，我一直在密切觀察你們的國王。你有沒有興趣聽聽我發現了什麼呢?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n黑龍王子之眼"}
MultiLanguageQuestData['tw'][32391] = {title = "考倫廢墟", objective = "到考倫廢墟找伊什。到制霸岬找塔克-塔克送你過去。", description = "卡爾洛斯派出了數百名騎士到崑萊峰北方的岸邊，去尋找符合你在衫·基恩的記憶中見到的那座魔古墓穴。\n\n結果，真的有人找到了藏放聖鐘的地方。\n\n大劍師伊什正率領先鋒部隊去取得聖鐘。\n\n立刻去協助他，守住聖鐘，殺掉所有阻礙你們完成任務的人!\n\n立刻去找塔克-塔克，他可以送你過去。", progress = nil, completion = "聯盟比我們先到一步，這怎麼可能?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32392] = {title = "聖鐘", objective = "殺掉莎蕾娜‧天刃。", description = "要是聯盟以為他們能從我們這兒偷走聖鐘的話，他們可就大錯特錯了!\n\n就在此刻，我們已經把他們困在了底下的墓穴裡。\n\n膽敢與我們為敵的代價，就是死亡!\n\n走，<class>，去讓他們知道他們錯得有多離譜。", progress = nil, completion = "達納蘇斯?\n\n聯盟以為他們已經贏了，此刻正是他們最狂妄自大的時候，同時也是我們把戰利品從他們手裡硬生生搶走的最佳時機。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32393] = {title = "考倫廢墟", objective = "到考倫廢墟找莎蕾娜‧天刃。到雄獅灘找芬妮‧角旋送你過去。", description = "是時候進行我們最大膽的行動了，<name>。\n\n自從你取得了聖鐘下落的情報之後，我們便組織了一個精英隊伍，刻不容緩要把那件神器挖出來。\n\n莎蕾娜‧天刃指揮官將親自率領這支隊伍深入崑萊峰的最北端。\n\n立刻動身加入他們，發揮你所有的本事，務必讓任務成功。\n\n祝你好運，<class>，我不必再贅述這個任務對聯盟有多重要了。\n\n去找芬妮，她可以馬上讓你過去。", progress = nil, completion = "我們剛剛才把入口給炸開，&lt;class&gt;，你來得正是時候。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32394] = {title = "聖鐘", objective = "殺掉織懼者阿法圖，取得聖鐘。", description = "沒有人能預料底下究竟有什麼，所以我會親自帶領先鋒隊去探查。\n\n但如果你的情報沒錯的話，考倫魔古應該就把聖鐘藏在我們腳底下的某個密室裡。\n\n我有一種預感，他們絕對不會把聖鐘棄置在這裡，而沒有設下任何的保護機制。\n\n我需要像你這樣值得信賴的<class>來協助我。等你準備好了，就跟我說一聲。", progress = nil, completion = "做得太好了，&lt;name&gt;。我不敢想像，要是聖鐘落入卡爾洛斯的手裡，他會做出多麼可怕的事情。\n\n今天，我們一起捍衛了聯盟安全的未來，我會確保聖鐘平安送至達納蘇斯。\n\n我會向國王大力稱讚你的表現。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32395] = {title = "追踪事件：见到阿瓦图", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32396] = {title = "Uncompletable Binding Quest [DND]", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32397] = {title = "乾淨俐落", objective = "在營地裡引起一場騷動，偷走陳舊的日記。", description = "我注意到卡爾洛斯和那個聖匣守護者的血精靈帶著某本日記。\n\n那本日記從來沒離開過他們的身旁，一定很重要!\n\n要是你能引起夠大的騷動，說不定可以趁機把日記從桌上摸走。\n\n這幾隻犛牛正好可以派上用場，你只要在牠們屁股上拍一下，剩下的交給牠們就行了。\n\n不過要做好逃跑的準備!", progress = "你發現什麼?", completion = "哇，真是驚險!不過我從來沒懷疑過你的能耐。\n\n現在我就來瞧瞧這本日記...", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32398] = {title = "聖鐘之聲", objective = "到帝王之境找馬可羅克。到制霸岬找塔克塔克送你過去。", description = "<class>，你的努力如今有了成果。\n\n大酋長卡爾洛斯在崑萊峰集結了部落的精英群雄，一睹聖鐘響起的時刻。\n\n你絕對有權利參與這場盛會。\n\n出發吧，新部落的黎明今天就要升起。\n\n去找塔克塔克，他應該可以幫你安排交通工具。", progress = nil, completion = "&lt;name&gt;，我還在想你什麼時候才會到呢。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32399] = {title = "最深沉的暗影之息", objective = "見證聖鐘響起的一刻。", description = "<name>，時候到了。我們費盡辛苦，就為了這一刻。\n\n今天，我們的大酋長，卡爾洛斯‧地獄吼，會永遠改變我們族人的歷史。\n\n今天，我們要見證卡爾洛斯部落的誕生!\n\n別讓任何事情干擾這場儀式!", progress = "我們不能仰賴命運或天意。我們要刻出自己的未來...我們應得的未來!", completion = "他們也許毀了聖鐘，但是我奪走了聯盟王子的性命!\n\n我沒有辜負父親的期望。\n\n這場勝利付出的代價雖高，但是無所謂。\n\n我會另外想辦法消滅我的敵人，榮耀我們的部落!", rewards = "您會收到：\n\n大蠍尾獅恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32400] = {title = "聖鐘之聲", objective = "到帝王之境找安杜因。到雄獅灘找芬妮‧角旋送你過去。", description = "部落在崑萊山巔的帝王之境集結了重兵。\n\n那個區域是古代的魔古宮殿，顯然有著不知名的力量。\n\n這件事只有一種可能:卡爾洛斯要使用聖鐘了，可是...安杜因還有和諧之槌...雙雙失蹤了。\n\n我敢肯定那個傻孩子一定獨自往北去了。\n\n我沒時間組成精銳部隊過去抓他，你一定要過去阻止安杜因。\n\n芬妮可以帶你過去。", progress = nil, completion = "&lt;name&gt;!你就是我要找的&lt;class&gt;。你來的時間真是太巧了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32401] = {title = "最深沉的暗影之息", objective = "擊敗伊什並摧毀聖鐘。", description = "卡爾洛斯就在那裡，他隨時都有可能敲響聖鐘。\n\n我們沒時間等父親的軍隊過來了，這是我們唯一能阻止他的機會!\n\n我會先試著和他講道理，萬不得已才會使用和諧之槌。\n\n<name>，準備好的時候就衝吧，我就在後面跟著你。", progress = nil, completion = "&lt;安杜因看起來像個癱倒在地的玩偶。他毫無動靜地倒在地上，只有那淡金色的頭髮因冰冷的寒風吹拂而揚起。&gt;\n\n&lt;你靜靜地坐了一會，直到寒意滲進你的骨裡。聖鐘已毀，但這靜默令人難以承受。&gt;\n\n&lt;這時，你從眼角瞥見男孩的手微微抽動了一下，你靠近他的身旁，他微弱地吸了口氣...他還一息尚存!安杜因還活著!&gt;", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32402] = {title = "達拉然的局勢", objective = "與克隆莎交談，飛向達拉然。", description = "夜精靈已經知道聖鐘被偷走了，但這倒也在預料之中。\n\n但是他們也發現了達拉然「中立」的奪日者有涉嫌其中。所以，我們現在有新的狀況要處理。\n\n我要你立刻前往達拉然。去叫克隆莎送你一程，到了之後立刻去見大博學者洛摩斯。", progress = nil, completion = "你能夠過來真是太好了...部落在達拉然的日子可不好過了。\n\n珍娜已經下令要把所有奪日者都趕出去，我們得合作救出所有的人，包括大法師埃薩‧奪日者他本人，然後盡快離開這裡。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32405] = {title = "白銀誓盟之手", objective = "殺死索琳‧法師之手。", description = "珍娜從城裡趕出去的每一位奪日者，都將變成為了我們、為了部落而戰的新生力軍。\n\n我要去找更多還有能力作戰的精靈，你已經證明了你獨自作戰的本事 - 去解決黑市裡那個東西。\n\n等你辦好了，我們就到坡道那邊會合，然後到地面上去。", progress = nil, completion = "任務第一階段總算完成了，但這還是最簡單的。\n\n&lt;洛摩斯深呼吸一口氣，然後繼續說道...&gt;", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32408] = {title = "白銀誓盟要塞", objective = "殺掉秘法師蕾瑟拉。", description = "我握有可靠的線報，大法師埃薩‧奪日者被關在白銀誓盟的總部，白銀領區，而且是由秘法師蕾瑟拉在看管他。\n\n目前大多數的白銀誓盟成員都在外頭獵殺奪日者，正是我們潛入救人的最佳時間。殺掉蕾瑟拉，把埃薩救出來。", progress = nil, completion = "我們繼續努力，再多救一些奪日者。埃薩的下落說不定到時候就會有著落了。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32409] = {title = "祈倫托的真實本色", objective = "殺掉考文中尉和他的10個手下。", description = "任何祈倫托是個「中立」團體的假貌，都可以正式拋棄了。我聽說珍娜已經讓聯盟的部隊進駐到安東尼達斯紀念碑那邊。\n\n雖然那裡已經沒有奪日者了，但是看到祈倫托的立場如此偏頗依然讓我滿腔怒火。\n\n到紀念碑那裡去看一下，<name>...並且順道教訓一下那些聯盟混球。", progress = nil, completion = "謝謝你，&lt;name&gt;。\n\n雖然跟白銀誓盟的高等精靈直接開戰還是讓我有點不開心...但是殺聯盟的走狗我永遠都不會厭倦。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32410] = {title = "卡薩斯平臺", objective = "釋放6隻奪日者龍鷹。", description = "就算我們救了再多的奪日者，要是逃不開這裡的話，一切也是枉然。\n\n白銀誓盟的人必定會去降服和殺掉奪日者的龍鷹，我們得阻止這件事。", progress = nil, completion = "做得好，&lt;name&gt;。做得很好。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32412] = {title = "最後的努力", objective = "殺掉法師指揮官祖洛斯，然後逃離達拉然。", description = "我們已經找過了他可能會在的每個地方，如今就只剩下一個地方:紫羅蘭城塞。\n\n找出大法師埃薩是否被關在紫羅蘭城塞裡，<name>。說不定我們終於會改走好運...萬一還是沒找到，至少我們已經努力多救了不少人的性命。", progress = nil, completion = "這不是...&lt;name&gt;?這裡到底是怎麼回事?", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32414] = {title = "達納蘇斯遇襲？", objective = "與雄獅灘的西蒙斯‧金躂交談，以傳送到達納蘇斯，抵達後與珍娜交談。", description = "如你所知，我們的夜精靈盟友把聖鐘移到達納蘇斯進行保管與研究。不久前，他們把幾個精靈貴族法師傳送來這裡請求支援。細節並不明朗，似乎是城市遭到偷襲之類的？\n\n我不知道這是怎麼一回事，可是珍娜‧普勞德摩爾已經到現場去了，我覺得他們可能需要越多人手越好。\n\n跟西蒙斯‧金躂交談可以馬上傳送到達納蘇斯去。找到珍娜！", progress = nil, completion = "聖鐘被偷走了…\n\n我們在現場發現了秘法留下的痕跡…我應該可以發揮技能追蹤那些小偷。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32416] = {title = "珍娜的決心", objective = "使用傳送門從達納蘇斯前往達拉然，然後找凡蕾莎‧風行者交談。", description = "我努力了好久好久，不斷辛苦在修補聯盟與部落的關係。我一次又一次相信部落的善意，他們卻一次又一次在背後捅我。\n\n從今天開始，我拒絕再受到背叛!既然部落企圖利用祈倫托來當作對抗聯盟的武器，那麼他們就沒有資格繼續待在達拉然。\n\n跟我來，<name>。", progress = nil, completion = "從現在開始，由我來對你下達指示。\n\n珍娜要親自待在城裡實施我們的新規矩。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32417] = {title = "清理下水道", objective = "在达拉然下水道中击败12名夺日者。", description = "吉安娜清理附近夺日者的行动很成功，但还有很多人躲在下水道里。\n\n去找出那些满口谎言的鼠辈并消灭他们！", progress = nil, completion = "很開心那些鼠輩終於被徹底解決了，做得好，英雄。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32420] = {title = "兑现", objective = "击败魔导师布拉塞尔。", description = "我刚刚看见一名夺日者——我想他叫布拉塞尔——朝北边的银行方向逃去了。毫无疑问，他是想在逃走前卷走一切财产。\n\n去找到他，绝不能让他偷走我们金库中的一分一毫。当他和他那些夺日者同党背叛我们的时候，他已经放弃了自己存在银行里的一切资产。", progress = nil, completion = "這傢伙光是當懦夫和背叛者還不夠過癮...非得也當個貪婪的小偷才開心。\n\n哼，部落和奪日者都是一個樣，難怪會同流合污。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32423] = {title = "必要的手段", objective = "與凡蕾莎‧風行者交談以前往雄獅灘，抵達後與瓦里安‧烏瑞恩國王交談。", description = "感謝你今日的鼎力相助，<name>，後續的掃蕩工作由我來接手就可以了。\n\n珍娜已經前往雄獅灘去見瓦里安，而且她說希望你也能過去。", progress = nil, completion = "我無法責怪你服從命令，事實上，這回我甚至也無法責怪珍娜擅自採取行動。\n\n只不過… 這並不是遊戲、不是比賽，而是戰爭。牽涉無數人命的戰爭，牽涉聯盟未來命運的戰爭。\n\n但至少，祈倫托是我們的了，所有人都將記得今天聯盟所獲得的勝利。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32426] = {title = "攪動，不要搖動", objective = "到畢茲摩鬥陣俱樂部的貴賓室找基爾特教授。", description = "好吧，我告訴你要怎樣找到康奈利。\n\n情報員康奈利目前正偽裝成一個大賭徒，基爾特教授。他幾乎都待在貴賓室裡，而且據說他是在找一個很久以前背叛過他的鬥士。\n\n可惜，貴賓室一定要有邀請函才能進去。幸運的是，我剛好有一張邀請函。\n\n經過保鏢的時候可要鎮定點，萬一露出馬腳被逮了，可別說這張邀請函是我給你的。\n\n事實上，我們根本從來沒見過!", progress = nil, completion = "軍情七處的人是不曉得「退休」這兩個字怎麼寫嗎?\n\n好吧，要不是狀況真的很慘的話，他們應該也不會來找我才對。\n\n我願意幫忙，但是我需要幾天的時間來收集一點情報。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32428] = {title = "熊貓人古靈馴獸師", objective = "在寵物對戰中擊敗所有的熊貓人古靈。", description = "傳說有熊貓人古靈在潘達利亞四處漫遊。把他們找出來，並且在寵物對戰中擊敗他們。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n熊貓人風靈熊貓人土靈熊貓人火靈熊貓人水靈\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][32429] = {title = "王子的目的", objective = "殺掉喀撒朗蠻荒南方岸邊的聯盟士兵，直到你和黑龍王子達到崇敬聲望。", description = "我的目標就是快速了結這場代價高昂的戰爭。向我證明，部落才是應該獲勝的一方。向我證明，你在戰場上的實力。\n\n你要對抗的不是煞這種沒有實體的力量，而是活生生、面對面的敵手。\n\n你會獲勝嗎?您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32430] = {title = "撤換指揮官", objective = "到喀撒朗蠻荒的雄獅灘殺掉大元帥塔文布萊德。你需要組成隊伍。", description = "我一直在密切觀察一個聯盟的矮人。在失去巴爾莫丹之後，大元帥塔文布萊德在南貧瘠之地的反擊已經對部落造成了不小的干擾。如今他鎮守在雄獅灘的聯盟要塞裡，協助聯盟規劃在喀撒朗蠻荒的反擊行動。\n\n唯有召集一隊傳奇的部落英雄才有機會擊敗他。\n\n你如果想解決他，記得帶朋友...帶很多朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32431] = {title = "部落的榮耀", objective = "在科特魔古神廟和碎銀礦坑贏得戰場勝利。", description = "這是一場全面性的戰爭，<name>。戰火不僅燒到了潘達利亞，卡林多和東部王國的許多易燃點也都跟著起火了。在有組織的戰場前線裡，你的表現又會如何呢?我真想親自見識見識。\n\n我期盼能聽到你在戰場前線的傑出表現。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32434] = {title = "燃燒的熊貓人古靈", objective = "在寵物對戰中擊敗燃燒的熊貓人古靈。", description = "你回來了!要跟我再打一場嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n熊貓人古靈寵物用品"}
