MultiLanguageQuestData['tw'][32440] = {title = "低語的熊貓人古靈", objective = "在寵物對戰中擊敗低語的熊貓人古靈。", description = "你回來了!要跟我再打一場嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n熊貓人古靈寵物用品"}
MultiLanguageQuestData['tw'][32441] = {title = "雷霆的熊貓人古靈", objective = "在寵物對戰中擊敗雷霆的熊貓人古靈。", description = "你回來了!要跟我再打一場嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n熊貓人古靈寵物用品"}
MultiLanguageQuestData['tw'][32442] = {title = "危險逼近", objective = "完成「危險逼近」任務。", description = "宗師，我們的斥候發現惡魔指揮艦出現在地平面上。它似乎要往漂流島直直過來了。\n\n我們應該馬上佈置兵力，準備應付最糟的情況 - 全面開戰。\n\n在此同時，我們可以先派出勇士，試著轉移燃燒軍團戰艦的注意力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32444] = {title = "FLAG - Earned Brawler Title (Weekly)", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32446] = {title = "借拆來用", objective = "使用重新配置過的遙控器摧毀叢林伐木機，收集6個金屬碎塊。", description = "那些伐木機已經變成了嚴重的問題，<class>。\n\n雖然我們已經派了搗碎機過來，但還是不夠，它們壞的速度遠快過我們修的速度!\n\n我在偵察的時候剛好弄到了這個奇怪的遙控器，只要調整修改一下，應該就可以拿來給我們用。\n\n去試看看對著叢林伐木機使用它，希望真的可以摧毀它們，然後你就可以把廢五金材料帶回來給我。", progress = "那個遙控器真的有用嗎?", completion = "哥布林的東西總是讓人覺得不太好用，不過現在也只能湊合著啦。做得好，&lt;name&gt;!", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32448] = {title = "過往之繫", objective = "取得韋拉圖斯靈魂精華。", description = "我之前在谷裡的時候，發現了一個古老的熊貓人配方，回憶之酒。我認為這種酒可以從衫‧基恩身上引出有用的情報。\n\n這裡需要我，所以我別無選擇，只能請你幫忙尋找釀酒的重要素材。我們需要魔古的靈魂精華，這個魔古必須曾經活在我們想要重現回憶的那個年代。\n\n你可以在東北方的征服者之路找到所需的這個魔古之靈。", progress = "你永遠不知道能在書裡找到什麼，尤其是熊貓人的古籍。\n\n我迫不及待想知道回憶之酒的作用原理。", completion = "啊，很好。這是最後一個材料了。", rewards = "您會收到：\n\n恆龍寶箱制霸先鋒軍"}
MultiLanguageQuestData['tw'][32449] = {title = "歐古戴遺跡", objective = "到閃亮火箭哨站找貝洛克‧亮刃。", description = "我們在閃亮火箭哨站的斥候回報，在一個名為歐古戴遺跡的區域附近有新的動靜。\n\n我們要收集情報、弄清楚聯盟在做些什麼，更重要的是他們找到了什麼。我們不能容許任何未知的狀況。\n\n到閃亮火箭哨站跟貝洛克‧亮刃會合，弄清楚他知道些什麼。", progress = nil, completion = "&lt;class&gt;，我們有得忙了。誰知道他們在歐古戴遺跡挖出了什麼東西!", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32450] = {title = "是時候了!", objective = "到閃亮火箭哨站找影王卡玲。", description = "<class>，進攻的時候到了!\n\n到閃亮火箭哨站找影王卡玲報到，她有命令給你。\n\n現在我們就來瞧瞧他們要怎麼對付部落全力進攻他們寶貴的堡壘!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32451] = {title = "捎個訊息", objective = "到喀撒朗蠻荒的天火號找空軍上將羅傑斯。", description = "該讓部落的狗雜種見識一下聯盟的力量了!今天我們要直搗他們的家門。\n\n向天火號的上將羅傑斯報告，她會給你進一步的指示。\n\n<class>，祝你好運。讓聯盟以你為傲!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32452] = {title = "哥布林來也", objective = "到喀撒朗蠻荒的天火號找空軍上將羅傑斯。", description = "<class>，我們腹背受敵。就連潘達利亞大陸都需要我們的保護。\n\n污水哥布林正在摧毀不屬於他們的大地，一定要阻止他們!\n\n向天火號的空軍上將羅傑斯報告。以她那裡的視角，她應該清楚對方的弱點在哪裡。", progress = nil, completion = "是時候解決這個麻煩了，該給那些污水矮冬瓜一點教訓!", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32455] = {title = "沉默", objective = "使用聯盟信號槍。", description = "我...我們...辦到了嗎?\n\n<安杜因喃喃說著，費力開口讓他更虛弱了。>\n\n從我的...背包裡...找...\n\n發出...信號...", progress = nil, completion = "&lt;name&gt;，要不是你在小王子身邊，我真不敢想像會發生什麼事情。\n\n今天，你將卡爾洛斯的計畫劃下句點。\n\n顯然你拯救了成千上萬的性命，更重要的是，你把安杜因帶回來了。\n\n我們會盡一切努力照顧這個孩子，可是現在只能靜觀其變。\n\n我相信他可以奮鬥下去的，我一定得相信...", rewards = "您會收到：\n\n大獅鷲獸恆龍寶箱"}
MultiLanguageQuestData['tw'][32458] = {title = "有了風的庇佑...", objective = "收集好運符咒。", description = "<耳邊傳來急切的求助聲。>\n\n<name>!我父親的艦隊正朝潘達利亞前進。如果順著風勢，他們隨時都可以抵達這裡。\n\n熊貓人有種祝福，可以讓天候順利、讓我們的船艦加快抵達這片海岸。我們只要收集好運符咒就能達到這個效果。\n\n我們的船艦離島嶼越近，需要的符咒就越少。不過你如果有夠多的符咒，我們馬上就能加快船隻的速度...", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32460] = {title = "追蹤盜賊", objective = "跟隨珍娜，協助她查出是誰偷走了聖鐘、又把聖鐘送到哪裡去了。你可以和雄獅灘的西蒙斯‧金躂交談，傳送到達納蘇斯。", description = "我們一定會查個水落石出。\n\n<name>，跟我來。就算要翻遍這座城的每個角落也無所謂，我們一定要弄清楚他們是怎麼偷走聖鐘的…而且偷到哪裡去了。\n\n我在這裡發現了些微的秘法痕跡…我們得追蹤下去！", progress = nil, completion = "我的心意已決。\n\n祈倫托裡的某些成員對部落的忠誠高於達拉然之上，我絕不容許這種事。這顯然是背叛。\n\n&lt;珍娜的眼裡閃著怒火。&gt;\n\n&lt;name&gt;，跟我來。我們要肅清達拉然。", rewards = "您會收到：\n\n恆龍寶箱鐵壁特遣行動"}
MultiLanguageQuestData['tw'][32461] = {title = "雲蛟衛", objective = "到翠玉林的落英園找講師天刺。", description = "啊，看來你成了雄偉雲蛟的尊榮主人。\n\n在你乘著這頭強大的生物飛上雲霄之前，你得先學會騎乘雲蛟的技術。\n\n雲蛟衛可以教導你所需的知識。\n\n如果你想跟隨我們的道路，那麼你該去翠玉林的落英園跟講師天刺談談。\n\n祝你好運，<race>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32467] = {title = "阻止献祭", objective = "击败5个赞达拉牧师。北边镇上的赞达拉牧师准备用我们阵亡盟友的遗体进行献祭。\n\n知道阻止他们的最佳办法是什么吗？干掉他们。把他们全都干掉。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "北边镇上的赞达拉牧师准备用我们阵亡盟友的遗体进行献祭。\n\n知道阻止他们的最佳办法是什么吗？干掉他们。把他们全都干掉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32468] = {title = "晶瑩剔透", objective = "從荊棘谷內尤亞姆巴島的晶背族母身上取得1個完好的水晶裂片。", description = "對了，如果你有興趣的話，我知道有個辦法可以讓你的自拍相機升級。只要有適合的聚焦鏡片，我就可以加上各式各樣的功能。\n\n我聽說荊棘谷有座古老的尤亞姆巴島，有人在那裡看過晶背石化蜥蜴的族母。她的鱗皮上綴滿寶石，是做聚焦鏡片的絕佳材料，要是我拿得到就好了。\n\n她可不是好對付的，你最好多找幾個朋友一起去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n自拍濾鏡更新套件"}
MultiLanguageQuestData['tw'][32469] = {title = "晶瑩剔透", objective = "從荊棘谷內尤亞姆巴島的晶背族母身上取得1個完好的水晶裂片。", description = "嗨，又見面了！噢，我忘了告訴你，我有個絕佳的方法，可以幫你升級自拍相機！\n\n其實呢，只需要合適的寶石，我就可以做出無比清晰，適用於各種功能的鏡片！\n\n我的冒險者同伴跟我說荊棘谷裡的尤亞姆巴島有隻巨大的石化蜥蜴，她身上的鱗皮綴滿品質一流的水晶！一切就是這麼剛好！\n\n不過，那隻石化蜥蜴族母可不是好對付的，你最好多帶幾個朋友去！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n自拍濾鏡更新套件"}
MultiLanguageQuestData['tw'][32470] = {title = "攝影活動", objective = "在主城收集一個鐵箱和一個赤色腰帶，並向工程師取得一個普通瞄準鏡。", description = "喔，嗨！你看這張照片是不是拍得很棒？我愛死我的自拍相機了！\n\n你希望我也幫你做一台嗎？我只需要幾個零件而已！\n\n背帶的部分，我需要一個赤色腰帶，在暴風城的護甲商人那邊就買得到。\n\n我已經訂購了好幾個機殼，你可以自己拿走一個。不過，你得先找到我訂的那箱貨物到底跑到哪裡去了！\n\n喔，還需要一個普通瞄準鏡。大多數的工程師都能幫你做一個。\n\n好！你準備好要多拍點照片了嗎？！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n自拍相機"}
MultiLanguageQuestData['tw'][32471] = {title = "攝影活動", objective = "在奧格瑪收集一個鐵箱和一個赤色腰帶，並向工程師取得一個普通瞄準鏡。", description = "你對視覺藝術呈現好像也很有興趣的樣子。要不要來玩玩攝影啊？\n\n我可以幫你做一台自拍相機，我只需要幾個零件而已。\n\n背帶的部分，去跟附近的護甲商人買一個赤色腰帶來給我就行了。\n\n我已經訂購了一箱機殼，應該在後門那邊。經過的時候記得順手拿一個過來給我。\n\n喔，還需要一個普通瞄準鏡。大多數的工程師都能幫你做一個。\n\n好了，快點去收集零件！準備成為攝影大師吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n自拍相機"}
MultiLanguageQuestData['tw'][32472] = {title = "Frighten Pterodactyls [PH]", objective = "吓跑12头翼手雏龙。", description = "北边那些正在接受赞达拉巨魔训练的翼手雏龙还没有变成那种残暴野蛮的野兽。\n\n我认为我们应该在这些生物被巨魔腐蚀前将它们就救出来。如果你能把它们吓跑，或许其中的一些小家伙能够躲过这悲惨的命运。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32474] = {title = "勇气的试炼", objective = "获取总共3000点勇气点数，达成“勇气的试炼”成就。", description = "<毫无征兆地，拉希奥朝他的拇指上划了一道口子，并将这根手指贴上了你的额头。他的血液带有烧灼的触感，不过很快就渗入你的皮肤并消失了。>\n\n好了！我的眼睛会跟随你，<class>。我在注视着你。\n\n那些熊猫人，和联盟一样崇尚“勇气”。在这片大陆上，你有很多种办法证明你的勇气。你可以去完成日常任务，也可以深入强大敌人的巢穴将他们击败。我会让你自己去选择你的事业。\n\n向我证明你的勇气吧，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32476] = {title = "勇气的试炼", objective = "获取总共3000点勇气点数，达成“勇气的试炼”成就。", description = "<毫无征兆地，拉希奥朝他的拇指上划了一道口子，并将这根手指贴上了你的额头。他的血液带有烧灼的触感，不过很快就渗入你的皮肤并消失了。>\n\n好了！我的眼睛会跟随你，<class>。我在注视着你。\n\n那些熊猫人，和部落一样崇尚“勇气”。在这片大陆上，你有很多种办法证明你的勇气。你可以去完成日常任务，也可以深入强大敌人的巢穴将他们击败。我会让你自己去选择你的事业。\n\n向我证明你的勇气吧，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
