MultiLanguageQuestData['tw'][32485] = {title = "加强防御", objective = "在紫罗兰高地附近强化6个肯瑞托监视结界。", description = "这座岛屿十分危险，<name>。我们要提防来自赞达拉巨魔、魔古族、蜥蜴人的攻击，最要命的是，还有夺日者。\n\n我在我们营地外围布满了监视结界，以提供额外保护。在当前状态下，它们只会对一名攻击者造成伤害，可我已经厌倦警告了！\n\n在你的帮助下，我们可以强化这些结界，把它们变成更具致命杀伤力的防御系统。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32489] = {title = "遍地蔓延的峭壁蟑螂", objective = "踩扁75隻伊加路克蟑螂。", description = "喔，蟑螂!我曾經在幽暗城買過一隻蟑螂寶寶。\n\n蟑螂會像海綿一樣吸收疾病，然後散佈到各處，無邊無際。\n\n伊加路克峭壁上頭爬滿這種東西，牠們將污刃的穢物散佈到整座島上。在你還在峭壁那邊時，盡可能的踩扁那些蟑螂。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32491] = {title = "腐肉傳疫", objective = "摧毀3個惡臭肉塊。", description = "污刃薩烏洛克不會吃掉所有獵捕來的肉，他們把大部分的肉堆在家的附近放著腐爛，吸引害蟲並散佈疾病。\n\n我們不能讓薩烏洛克將疾病散佈到伊加路克峭壁以外。摧毀所有找到的腐肉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32492] = {title = "摧毁大锅", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32493] = {title = "他們全倒下了", objective = "殺死5個縛靈哨衛，然後使用共鳴水晶捕捉困在體內的贊達拉魂靈。", description = "<class>，贊達拉不容許他們之中有弱者存在。\n\n弱小的食人妖往往會成為野蠻祭典中的祭品。受害者的魂靈被禁錮在你見到的那些哨衛體內，保護這片土地。\n\n我想研究他們的精華，為此我需要你的協助。\n\n帶著這塊共鳴水晶從哨衛屍體內吸取魂靈。\n\n別讓它們逃走了!", progress = nil, completion = "做得好，&lt;class&gt;! 這大大幫助我的研究，也讓我們朝理想邁進一步。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32494] = {title = "魔力面具", objective = "前往征戍台從縛靈者圖柴克與秘宗拉庫爾身上取回黑暗秘儀面具與喚靈者面具。", description = "贊達拉會將羅亞的精華灌注在物品裡，賦予物品強大的力量。這些物品往往代代相傳，由每一位接收者添加新的魔力。\n\n這裡便有兩件這樣的物品。精確來說，是兩件面具，由一對兄弟戴在臉上。\n\n我們得阻止縛靈者圖柴克與秘宗拉庫爾，並且摧毀他們的面具。\n\n殺掉他們，並將面具帶回來給我。我保證會徹底銷毀面具。", progress = "拿到面具了嗎?", completion = "取得面具很不容易，&lt;class&gt;。非常感謝你的辛勞。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32495] = {title = "『放血者』凱達", objective = "殺死『放血者』凱達。", description = "我聽到一件令人煩惱的報告，<class>。\n\n在我們據地的更遠處，位於白骨之廷裡，魔古將俘虜獻給名為『放血者』凱達的將軍。\n\n詳情我就不多說了，但是這位將軍使用殘忍的手段凌虐囚犯。\n\n我們得阻止這個怪物。若你不幸倒在他的刀下，願你能死個痛快。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32496] = {title = "褻瀆這些火焰！", objective = "褻瀆部落的恆春谷篝火！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n燃燒之花"}
MultiLanguageQuestData['tw'][32497] = {title = "榮耀火焰", objective = "榮耀悚然荒野的仲夏篝火。", description = "仲夏火焰節慶是一個紀念元素的時節。火焰的元素會激起我們內心的激情。很多時候，這種激情將會化為積極的行動。但是在這裡，在這座島上，我們只把我們的熱情專注在崇敬而已。\n\n我們榮耀火焰是為一種傳統的儀式，你願意加入我們一起榮耀火焰嗎，<name>？", progress = nil, completion = "榮耀悚然荒野的火焰。", rewards = "您會收到：\n\n燃燒之花"}
