MultiLanguageQuestData['tw'][32504] = {title = "任务：暴风城的秘密", objective = "派遣一支秘密部队潜入敌方腹地，设法打探对方的计划。", description = "派遣一支秘密部队潜入敌方腹地，设法打探对方的计划。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32505] = {title = "崩壞的司庫", objective = "取回司庫的肩膀、頭部、法杖、頭髮和軀幹。", description = "那邊的!幫我個忙。\n\n我生前為雷王陛下的御前司庫。我的努力奉獻，換來死後被咒語化為石像，被迫永遠看管他的一部份珍寶。\n\n有人褻瀆我光榮的身軀，將碎片送到島上的其他地方。想到自己永生永世只剩下這一顆頭，我就覺得難過。\n\n搜尋這座島嶼，找回那些碎片。我會送你一件陛下的珍寶。", progress = "我需要所有的部位。假如很多部位都找不到，我應該考慮撤銷協議。", completion = "喔!我又完好無缺了!謝謝你，凡人。拿走這顆石頭並謹慎使用。若是你在旅程中遇見雷王本人，別告訴他這顆石頭的來歷，否則你也會化為石像陪我一輩子了。", rewards = "您會收到：\n\n\n\n等級 51–80衫織儀式石\n\n等級 57–70恆龍寶箱"}
MultiLanguageQuestData['tw'][32506] = {title = "可供騎乘的翼手龍", objective = "帶回一隻野生翼手龍寶寶。", description = "我剛收到回報說，厄運沼澤又見到另一隻年輕的翼手龍。\n\n我們得盡可能蒐羅這些生物，牠們也許是能讓我們飛翔在這座島上的關鍵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32507] = {title = "幻化成薩烏洛克", objective = "前往伊加路克峭壁並殺死一名污刃薩烏洛克。", description = "伊加路克峭壁這個地方太險惡了。幸運的是，你有奪日者的魔法保護你。\n\n我可以將你變形成一隻薩烏洛克。\n\n我先施行前半段的幻術。之後，你直接到伊加路克峭壁並殺死一名污刃薩烏洛克。事成之後，我會跟你聯絡，並完成後半段的幻術。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32508] = {title = "欢迎到岛上来", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32509] = {title = "榮耀火焰", objective = "榮耀恆春谷的火焰。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n燃燒之花"}
MultiLanguageQuestData['tw'][32510] = {title = "榮耀火焰", objective = "榮耀恆春谷的火焰。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n燃燒之花"}
MultiLanguageQuestData['tw'][32517] = {title = "石征者", objective = "阻止白骨之廷主廟裡的上古石征者儀式。", description = "雷王的巫士在白骨之廷裡進行黑暗儀式。\n\n衫織撕魂者將奪來的生者靈魂灌注到上古石像中，以壯大他們的陣容。\n\n這些石征者要是活了過來，將會成為戰場上的強敵。\n\n我們必須在石像甦醒之前阻止他們的儀式。", progress = nil, completion = "小心防守就是最好的進攻。這下除掉了一種強敵。\n\n做得好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32518] = {title = "短缺奖励", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32519] = {title = "短缺奖励", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32520] = {title = "魔法對決", objective = "殺死織秘者鳩谷瓦。", description = "我的斥候在札突爾的這一側看見一位危險的贊達拉，我需要有能力的人去除掉他。你願意接下這個任務嗎?您會收到：\n\n\n\n等級 60–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 60–80奪日者獎賞\n\n等級 70–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32521] = {title = "外力入侵", objective = "殺死贊達拉戰爭領袖奴凱拉。", description = "我的斥候在北方海灘看見贊達拉的戰士。我需要一位有能力的人去除掉他。你願意接下這個任務嗎?", progress = nil, completion = "&lt;name&gt;，我們感謝你。", rewards = "您會收到：\n\n\n\n等級 60–80奪日者獎賞\n\n等級 70–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32522] = {title = "重大威脅", objective = "殺死『奴役者』霍賈克。", description = "我的斥候在中央高塔下發現了一個魔古首領。在他對我們的陣地發動攻擊之前，我們得殺掉他。\n\n你願意幫我辦這件事嗎?", progress = nil, completion = "我們身旁又少了一分威脅。&lt;name&gt;謝謝你。", rewards = "您會收到：\n\n\n\n等級 51–80奪日者獎賞\n\n等級 70–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32523] = {title = "獸園", objective = "尋找獸園裡的斥候隊長艾爾西雅。", description = "我們得對抗贊達拉用來襲擊陣營的野獸。我已經派遣斥候隊長艾爾西雅與幾名戰爭法師到獸園作為掩護。\n\n到東邊的牆縫附近找她，幫助她除掉騎兵並圍捕攻擊我們的野獸。\n\n他們身上都有偽裝，尋找魔法披風法術的亮光就能找到他們。", progress = nil, completion = "很高興洛索瑪派你來，光靠我們幾個無法處理這些野獸。該是大開殺戒的時候了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32524] = {title = "贊達拉戰鼓響起", objective = "找到征戍台的斥候隊長艾爾西雅。", description = "你聽到了嗎，<class>？ 遠方響起隆隆的戰鼓聲，贊達拉準備朝我們進攻了。\n\n別讓他們有時間部署防禦，我們現在就得發動攻擊！\n\n向征戍台的斥候隊長艾爾西雅回報。她會給你下一步命令。", progress = nil, completion = "這些贊達拉比我們預期的還要危險。\n\n別犯下低估他們的錯誤，那可能會要了你的命。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32525] = {title = "敌人的骨灰", objective = "超度8具干尸残骸。", description = "白骨庭院中的魔古族正在施法复活亡者之魂来扩充兵力。\n\n我们决不能任由他们让亡者士兵起死回生。\n\n带上这个火把，去超度你所找到的干尸遗骸。\n\n我们要在这些敌人复活之前先干掉他们。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32526] = {title = "靈魂也屈服", objective = "拯救6名白銀誓盟斥候或奪日者斥候。", description = "我們朝白骨之廷的魔古發動攻擊，但我害怕我們只是讓部隊白白犧牲，成為他們可怕儀式的祭品。\n\n魔古不只殺掉囚犯，還會奪取他們的靈魂灌注到石像機關裡，或是將死者變成幽靈般的戰爭工具。\n\n囚犯是部落或聯盟並不重要，重要的是我們不能讓魔古繼續壯大下去。\n\n進入墓穴，救出還活著的囚犯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32527] = {title = "墓況嚴峻", objective = "殺死10個衫織守墓者、衫織撕魂者或衫織喚雷者。", description = "魔古部隊集結在白骨之廷，日夜不休地進行雷霆儀式。\n\n若我們想成功奪下這座島嶼，便不能讓他們佔據這個戰略要點。\n\n必須消滅他們。", progress = nil, completion = "了不起。魔古絕對難忘這次慘痛的教訓。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32528] = {title = "進入墓地", objective = "在崇者大廳使用古拉的咒卷，然後擊敗『回煞魔』古拉。", description = "我們每天都會從白骨之廷挖掘出新的文物。\n\n最近我們在某個極深的墓穴中，在碑林裡發現了這個卷軸。\n\n我相信這個咒卷能用來召喚墓地的死者。假如我的魔古語沒有生疏的話，我想你應該在崇者大廳的最後一間房間使用這個卷軸。\n\n你願意去測試我的理論嗎?", progress = nil, completion = "太好了，你證實了我的理論!謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32529] = {title = "喚雷", objective = "阻止衫織喚雷者的儀式。", description = "在墓地裡頭，西邊墓穴最深處的廢墟裡，雷王最強大的巫士正以猛爆的電力為閃電之柱充能。\n\n我們懷疑這個武器是要用來摧毀紫羅蘭高崗的要塞。\n\n事不宜遲，你得立即阻止他們的儀式。", progress = nil, completion = "你再次讓我刮目相看，&lt;class&gt;。做得好。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32530] = {title = "放血者", objective = "击败放血者喀岱。", description = "我收到了一份令人不安的报告，<class>。\n\n在距离我们不远的白骨庭院中，魔古族会将俘虏都交给一个名叫放血者喀岱的将军。\n\n他惯于拷打受害者。\n\n我们必须阻止这个怪物。如果你倒在他的剑下，那我只能祈祷你能速死。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32531] = {title = "石征者", objective = "中斷白骨之廷主廟裡的上古石征者儀式。", description = "雷王的巫士在白骨之廷裡進行黑暗儀式。\n\n衫織撕魂者將奪來的生者靈魂灌注到上古石像中，以壯大他們的陣容。\n\n這些石征者要是活了過來，將會成為戰場上的強敵。\n\n我們必須在石像甦醒之前阻止他們的儀式。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32532] = {title = "打倒那些亡靈!", objective = "殺死15名甦醒的古代亡靈。", description = "你是否見到墓地裡那些遊蕩的鬼魂?\n\n它們是甦醒的古代亡靈，被喚回世上的魔古亡魂。\n\n它們憤怒時攻擊快狠無聲，而且它們的數量日漸增加。\n\n這些亡靈不屬於這裡。消滅他們，把他們送回墳裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32533] = {title = "冷血石獸", objective = "摧毀8個墓穴守護者。", description = "我們對白骨之廷的攻擊持續進行中，進展雖然緩慢，但是成效顯著。\n\n在這個節骨眼上，我們卻收到好幾名斥候回報說，麒麟獸石像無預警地復活了。這些麒麟獸是不容小看的強敵。\n\n潛入白骨之廷，毀掉所有你能找到的麒麟獸石像!", progress = nil, completion = "很高興聽到你把麒麟獸雕像打成粉碎。這些傢伙妨礙了我在島上的工作。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32535] = {title = "污刃威脅", objective = "殺死10名污刃薩烏洛克。", description = "伊加路克峭壁上到處都是薩烏洛克。這些野獸攻擊我的手下，並將疾病傳染到鄰近的水域與野生動物身上，干擾我們的行動。\n\n削減他們的數量，<name>。一旦聯盟完全掌控這座島，我們便能找出永久的解決辦法。", progress = nil, completion = "總有一天，這座島會落入聯盟手中，我只希望到時薩烏洛克已經被消滅殆盡。\n\n&lt;莫德菈冷笑了一下。&gt;\n\n至少他們也攻擊部落。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32536] = {title = "操弄薩烏洛克", objective = "找到博學者雅里斯、博學者萊安納斯與博學者薩納爾。", description = "我讓三位博學者躲在伊加路克峭壁監視薩烏洛克，有機會的時候誘導他們對抗魔古。我需要你去找他們，看他們是否需要補給品或協助。\n\n他們躲起來不讓人發現，注意薩烏洛克村莊中閃閃發亮的光柱。", progress = nil, completion = "&lt;大法師仔細聆聽你的報告。&gt;\n\n我懂了。謝謝你的幫助，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32537] = {title = "回收傀儡", objective = "取回四個被偷走的白銀誓盟傀儡。", description = "薩烏洛克不停騷擾邊界，通常我們的傀儡能阻擋他們。不過，有些傀儡卻被擊敗，拖回伊加路克峭壁。\n\n我希望取回那些傀儡。有我在，那些滑溜的蜥蜴休想偷走白銀誓盟的財產。", progress = nil, completion = "這才像話。\n\n謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32538] = {title = "兇憎祭儀", objective = "摧毀贊達拉獻祭壇。", description = "有批縛魂者當中的精銳用可憎的儀式祭拜他們的邪神。\n\n我們想出了摧毀祭壇的方法，如今的難題是怎麼活著抵達各個祭壇。\n\n深入札突爾，摧毀他們的祭壇。", progress = nil, completion = "&lt;class&gt;，破壞這些祭壇可以迫使贊達拉停止他們邪惡至極的獻祭行為。這裡每個人都很感謝你。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32539] = {title = "黑暗獻祭", objective = "摧毀6個贊達拉祭品。", description = "贊達拉縛靈者在黑暗獻祭中宰掉我們的人民，獻給神明。\n\n毀掉你能在札突爾找到的所有贊達拉祭品，來拖緩黑暗獻祭的進行速度。", progress = nil, completion = "沒有了祭品，他們就得重新準備才能進行獻祭。謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32540] = {title = "羅亞之靈的使者", objective = "殺死2名羅亞之靈的使者。", description = "你如果在札突爾待一陣子，很可能會看到某個大帳篷發散出邪惡的純粹形體。\n\n拜託你，深入食人妖營地阻止這些惡毒至極的儀式。", progress = nil, completion = "見過這些儀式的人幾乎都沒能回來，回來的人也都大受打擊。而你，&lt;name&gt;，似乎不為自己的壯舉所動。真是了不起。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32541] = {title = "防範未然", objective = "跑到12隻嘯天龍寶寶身邊驚嚇牠們。", description = "想到食人妖在訓練那些可憐的嘯天龍成為戰爭道具時牠們所遭遇的痛苦，就讓我心痛。\n\n那些龍寶寶膽子很小，你一靠近牠們就會飛走。拜託你，在贊達拉腐化牠們之前嚇跑一些龍寶寶。", progress = nil, completion = "&lt;race&gt;，歡迎回來。你嚇跑的那些龍寶寶離開捕捉牠們的人之後，會過著更好的生活。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32542] = {title = "精準襲擊", objective = "殺死3名贊達拉縛靈者、3名贊達拉喚獸者與3名贊達拉狂豹戰士。", description = "贊達拉縛靈者拿活人獻祭給神明，喚獸者操縱無辜的嘯天龍作為幫手，狂豹戰士越來越深入我們營地的中央。\n\n剷除札突爾裡的這些禍害，<race>，削弱食人妖的勢力。", progress = nil, completion = "除掉他們幾個種子士兵之後，下次贊達拉也許就不敢隨便輕視我們了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32543] = {title = "札突爾的危機", objective = "殺死札突爾裡的12名食人妖。", description = "贊達拉是可怕的強敵，比我們過去遭遇過的對手都還要危險。不過你也是個狠角色，<name>。\n\n進入札突爾，讓他們瞧瞧惹毛像你這樣的人需要付出什麼代價。", progress = nil, completion = "&lt;name&gt;，感謝你協助對抗贊達拉。我明白看似大勢已去，但你的努力確實幫了我們一把。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32544] = {title = "痛苦的翼手龍", objective = "釋放痛苦的嘯天龍。", description = "有隻食人妖的嘯天龍正在札突爾遭受折磨儀式，讓牠的意志永遠屈服於牠的主人。\n\n殺死那些折磨這隻生物的人，希望牠能重回天空的懷抱。", progress = nil, completion = "我希望那頭龍夠聰明，知道是誰救了牠。在我看來，牠被激怒的話會是個可怕的敵人。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32545] = {title = "伊加路克的居民", objective = "殺死一名污刃蠻卒、污刃魔龍祭司與一名污刃海龍。", description = "污刃薩烏洛克威脅我們人民的安危，但是全面屠殺他們卻又反應過度了。\n\n比較合理的應對方式是除掉他們幾個部落首領。這樣就不用流那麼多血，他們也會因此而尊重我們的領地邊界。", progress = nil, completion = "我知道殺人得付出什麼，我也了解戰爭的代價。\n\n盲目地屠殺敵人，直到他們投降。這種做法雖然簡單，可是對嗎?", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32546] = {title = "小小的清潔工作", objective = "殺死伊加路克峭壁的顫動穢怪來驅散75塊髒東西。", description = "我坦白告訴你，這不是件光榮的任務。\n\n污刃薩烏洛克將所有的髒東西都排到村莊中央的池子裡。這些髒東西濃稠腐臭，凍凝成會移動的生命體。\n\n薩烏洛克怎麼處理污水池是他們家的事，可是一旦它擴散到村莊以外，我們便不能袖手不管。", progress = nil, completion = "做得好，&lt;name&gt;。看到你，我突然對達拉然先進的下水道系統感到自豪。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32547] = {title = "伊瓜鲁克的恐怖地毯", objective = "踩死75只伊瓜鲁克蟑螂。", description = "啊，蟑螂！我曾在藏宝海湾买过一只宠物蟑螂。\n\n蟑螂会像海绵一样吸收病菌，然后将它们散播到自己所经之处。而它们的活动范围偏偏又很广。\n\n伊瓜鲁克峭壁上爬满了这种东西，将邪刃部族的秽物传播到岛上的每一个角落。当你去那里时，记得尽可能多踩死几只蟑螂。", progress = nil, completion = "每殺一隻蟑螂，就幫我一個大忙。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32548] = {title = "腐肉傳疫", objective = "摧毀3個惡臭肉塊。", description = "污刃薩烏洛克不會吃掉所有獵捕來的肉，他們把大部分的肉堆在家的附近放著腐爛，吸引害蟲並散佈疾病。\n\n我們不能讓薩烏洛克將疾病散佈到伊加路克峭壁以外。摧毀所有找到的腐肉。", progress = nil, completion = "那些被扔在那裡的腐肉堆正是繁殖病菌的溫床。\n\n如果我從事散佈疾病的工作，我也會採用這個方法。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32549] = {title = "幻化成薩烏洛克", objective = "前往伊加路克峭壁並殺死一名污刃薩烏洛克。", description = "伊加路克峭壁這個地方太險惡了。幸運的是，你有祈倫托的魔法保護你。\n\n我可以將你變形成一隻薩烏洛克。\n\n我先施行前半段的幻術。之後，你直接到伊加路克峭壁並殺死一隻污刃薩烏洛克。事成之後，我會跟你聯絡，並完成後半段的幻術。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32550] = {title = "除掉馴獸師", objective = "擊敗獸園裡的10名贊達拉食人妖。", description = "在獸園裡，你會遇到幾個贊達拉軍隊裡頭最有才能的馴獸師。他們擅長以斧頭、野獸與利爪殺戮敵人。這裡也是他們訓練騎兵的地方。\n\n我們需要你在食人妖騎乘魔龍加入戰場前，殺掉每個你在獸園裡找到的食人妖。", progress = nil, completion = "這些食人妖為了達成目標不惜使用黑魔法。毫無耐心與榮譽可言。今日你削減他們的數量，幫了這個世界一個大忙。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32551] = {title = "除掉那些龍", objective = "殺死獸園裡的5隻迅猛龍和10隻訓練有素的羽冠龍。", description = "贊達拉的迅猛龍和羽冠龍對我們的部隊造成嚴重威脅。牠們是優秀的狩獵者，能長途追逐獵物。出其不意的襲擊往往致獵物於死命。\n\n我要你進入獸園削減牠們的數量，務必在牠們成為訓練有素的猛獸前下手為強。", progress = nil, completion = "我們剛到這座島上便有三名優秀的戰士喪生，被溜進營帳裡的羽冠龍給殺了。某些夜晚我還是會聽見慘叫聲。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32552] = {title = "羅亞恐龍", objective = "擊敗一名羅亞語者。", description = "贊達拉找到方法將羅亞灌注到野獸體內，賦予其驚人且致命的力量。\n\n我們得阻止這一切發生。\n\n到獸園尋找一名羅亞語者，殺了他。留意發光的野獸便能找到他們。\n\n這種惡行不能再繼續下去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32553] = {title = "恐角龍對戰魔暴龍", objective = "殺死不肯馴服的恐角龍或魔暴龍身邊進行禁錮儀式的NPC，來中斷儀式。", description = "我們有機會阻止贊達拉的戰爭機器，並且從這個過程中獲得一點樂趣。\n\n獸園裡有一頭身穿護甲的魔暴龍和恐角龍，牠們的心智受贊達拉的符咒所操縱。\n\n進入營帳阻止其中一個禁錮儀式，哪一個都可以，只要殺掉那些企圖禁錮生物的施法者。如此一來，便能讓那隻裝甲生物在贊達拉營帳中瘋狂亂跑。接下來你只要等著看好戲就行了。", progress = nil, completion = "這世上沒幾件事情比觀看暴怒的遠古野獸將敵人陣營搞得人仰馬翻還來得有趣。\n\n假如時間不是那麼緊迫，我還考慮售票招攬觀眾呢。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32554] = {title = "恐龍的力量", objective = "在獸園找到恐龍神像並對5隻迅猛龍、細顎龍、嘯天龍或恐角龍使用它。", description = "贊達拉使用一系列的神像與符咒來操縱野獸。\n\n那一套你會我也會。\n\n我要你去找一些神像過來，對獸園裡的各種野獸進行測試。\n\n仔細記錄野獸們對每個雕像的反應，然後向我回報。\n\n也許我們能找到對付贊達拉的利器。", progress = nil, completion = "非常有趣的結果，肯定會有法師對這個細節感興趣。而我只是很享受食人妖被自己的野獸騷擾時的尖叫聲而已。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32555] = {title = "哨衛體內的百年魂靈", objective = "殺死5個縛靈哨衛，然後使用共鳴水晶捕捉困在體內的贊達拉魂靈。", description = "在贊達拉的社會中，獻祭是一件很普通的事情。在這種野蠻儀式中有一點比較奇怪的是，有人會自願當活祭品。他們認為這是無上的榮耀!\n\n即使那代表得犧牲性命，魂靈禁錮在你所見的這些移動哨衛體內，病弱的贊達拉仍然樂於奉獻。\n\n帶著這塊共鳴水晶。打倒哨衛之後便用水晶吸取裡頭的贊達拉魂靈。完成任務之後將水晶帶回來給我。", progress = nil, completion = "這個現象真有趣，&lt;class&gt;。魂靈的怨氣讓水晶發出嗡嗡聲。他們的奉獻不因為時間而有任何削減。\n\n我要好好來研究研究。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32556] = {title = "知己知彼", objective = "從征戍台附近取回6個儀式文物。", description = "這裡到處都是贊達拉文物。我非常想研究這些東西，它們對贊達拉祭儀的重要性讓我著迷。\n\n再說，知己知彼，百戰不殆嘛!\n\n我若想認真研究，就得近距離地觀察它們。帶越多的文物回來給我越好。", progress = "你帶了什麼回來給我，<class>?", completion = "這些文物都很棒!研究它們雖然耗費時間，但肯定能更加了解贊達拉的文化。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32557] = {title = "奪敵之刃", objective = "從征戍台偷走7把羅亞附靈之刃。", description = "魔法由高手來施展，是可怕的強敵。可是利刃交由莽夫來揮舞，才真正嚇人。\n\n贊達拉擁有一些強大的武器，附魔之後更加致命。我們得斬除他們的這項優勢。\n\n盡可能多偷一些武器回來。", progress = "你在那裡找到什麼?有任何可以使用的東西嗎?", completion = "做得好，&lt;class&gt;! 這些武器非常強大，現在我們在戰場上可以少擔心一些事情了。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32558] = {title = "家傳古物", objective = "前往征戍台從縛靈者圖柴克與秘宗拉庫爾身上取回黑暗秘儀面具與喚靈者面具。", description = "征戍台由一對兄弟看守;縛靈者圖柴克與秘宗拉庫爾。他們是強大的施法者，千萬別對他們掉以輕心。\n\n他們的魔力似乎源自於臉上所穿戴的華麗面具。這些面具是代代相傳的古物，而且每一位擁有者在傳給下一代之前，還會再將自身的魔法灌注在上頭。\n\n我們得解決掉這對兄弟，並且在面具落入他人手中前摧毀面具。", progress = "面具呢?", completion = "摧毀這些面具是萬不得已的事。我很想研究裡頭的古魔法，但為了避免面具為部落所用，最好先摧毀它們。\n\n做得好，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32559] = {title = "打倒魔像", objective = "摧毀征戍台的守護者大庫。", description = "羅亞是贊達拉崇拜的動物之靈，祂們被贊達拉召喚並祈求給予協助。現在贊達拉正試圖將這些魂靈綁縛到巨大的魔像身上，成功的話將釀成極大的災難。\n\n我已派遣一名密探去收集更多資訊，但是若要完成這項任務，得借重你的才幹才行。\n\n不惜任何代價都要阻止那場祭儀!", progress = nil, completion = "幸好你中斷了這場儀式，&lt;class&gt;。若沒阻止的話，誰曉得那個魔像會釀成什麼樣的破壞。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32560] = {title = "務必保密", objective = "殺死征戍台的8名贊達拉食人妖。", description = "贊達拉是這場戰役的威脅，<class>。\n\n他們將暗影能量融入秘法系的魔法之中，絲毫不顧會造成什麼結果，這種使用魔法的手段真是討厭。\n\n我們絕不能讓他們在這場戰爭中施展全力，或讓部落學習到他們扭曲的魔法。\n\n我們得削減他們的數量，這個任務就交給你了。", progress = nil, completion = "做得好，&lt;class&gt;。我們殺死越多個贊達拉，他們的魔法就越不容易落入部落手裡。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32566] = {title = "DEBUG: Eligible for All Quests", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32567] = {title = "獸園", objective = "尋找獸園裡的斥候隊長狄林。", description = "我不想再見到贊達拉獸騎士衝破我們的防線了！\n\n我已經派遣斥候隊長狄林和幾名戰爭法師前往西北方的獸園。他們的任務是滲透贊達拉的防線，並騷擾他們的騎兵單位。我要你加入他們，借助你的專長來幫助他們。\n\n留意他們魔法披風法術所發出的微光，便能發現他們的行蹤。", progress = nil, completion = "今天，獵人是我們的獵物！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32568] = {title = "還不是休息的時候", objective = "找出征戍台的斥候隊長狄林。", description = "雖然來到這裡之後我們完成許多工作，但是現在還不是休息的時候。由於你的辛勞，我們攻入了雷王要塞的上層。\n\n現在，我請求你繼續協助我們的戰役。向征戍台裡的斥候隊長狄林回報，他會給你下一步指示。", progress = nil, completion = "這裡的贊達拉不容小覷，&lt;class&gt;。他們用強大的魔法征服這塊區域。\n\n我們得加把勁才行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32569] = {title = "在黑暗中寻找光明", objective = "在阴惨泥沼中重新点燃8个火炬。", description = "在阴惨泥沼中存在着某种黑暗法术，就连我们的魔法之光都能扑灭，我们的斥候只得艰难的辨识方向。\n\n当你在泥沼中穿行时，重新将你所找到的所有火炬点燃，从而为我们的兄弟们照亮道路。或许它们还能帮你找到回来的路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32571] = {title = "可供騎乘的翼手龍", objective = "帶回一隻野生翼手龍寶寶。", description = "我剛收到回報說，厄運沼澤又見到另一隻年輕的翼手龍。\n\n我們得盡可能蒐羅這些生物，牠們也許是能讓我們飛翔在這座島上的關鍵。", progress = "這座島籠罩在一片漆黑之中...", completion = "太好了!我會將牠交給我們的管理員。謝謝你。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32572] = {title = "不眠的軍團", objective = "殺死6個活化戰士。", description = "衫織活化了島嶼中央的雕像，組成了一支大軍日夜打擊我們的防衛。把你看到的每個會走路的雕像都給毀掉。我們的防衛部隊會很感激的。", progress = nil, completion = "謝謝你的努力。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32573] = {title = "高塔下的强敌", objective = "在阴惨泥沼消灭7个山泽魔古。", description = "魔古族正在阴惨泥沼的高塔附近集结雕像大军。温蕾萨下令将他们全部消灭。我想你正好是执行这项任务的合适人选。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32574] = {title = "戰慄沼澤", objective = "殺死強力魔暴龍。", description = "沼澤裡有一隻龐然巨獸。雖然它還沒有前來攻擊我們，但這樣的好運不可能持續太久。\n\n在牠為了填飽肚子而敢於進犯我們之前，率先擊敗牠。", progress = nil, completion = "你不是等閒之輩。日後我必定還有需要你幫助的地方。\n\n改天記得來找我，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32575] = {title = "贊達拉巨像", objective = "摧毀贊達拉巨像。", description = "食人妖在南方道路上部署了一隻巨大的傀儡，擋住了我們的道路。去將它料理乾淨，<class>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32576] = {title = "魔法竞赛", objective = "消灭织魔者琼古瓦。", description = "有位占卜师在中央高塔附近发现了一位赞达拉首领。必须将他铲除。\n\n你愿意替我完成这项任务吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32577] = {title = "危机四伏", objective = "消灭奴役者霍嘎克。", description = "温蕾萨手下的一位斥候回报说在中央高塔下方有位魔古首领。我们得将他除掉。\n\n你愿意替我完成这项任务吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32578] = {title = "白骨之間", objective = "殺死『白骨工匠』祖恰卡。", description = "我的斥候在伊加路克峭壁西方的一堆白骨之間，看到一個危險的贊達拉。我需要有能力的人去除掉他，你願意接下這個任務嗎?", progress = nil, completion = "身邊有一位值得信賴的男人真好。", rewards = "您會收到：\n\n\n\n等級 60–80秘法珍寶\n\n等級 59–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32579] = {title = "魔法對決", objective = "殺死織秘者鳩谷瓦。", description = "我的斥候在札突爾的這一側看見一位危險的贊達拉，我需要有能力的人去除掉他。你願意接下這個任務嗎?", progress = nil, completion = "你的武藝令人佩服。謝謝你為我做的事，&lt;name&gt;。", rewards = "您會收到：\n\n\n\n等級 51–80秘法珍寶\n\n等級 70–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32580] = {title = "外力入侵", objective = "殺死贊達拉戰爭領袖奴凱拉。", description = "我接到消息說海灘上有贊達拉的戰士出沒，就在我們據地的北方。我們得追捕並殺掉這些傢伙。\n\n你願意為我們辦這件事嗎，<class>?", progress = nil, completion = "我們十分感激你所做的一切，&lt;name&gt;。", rewards = "您會收到：\n\n\n\n等級 51–80秘法珍寶\n\n等級 70–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32581] = {title = "重大威脅", objective = "殺死『奴役者』霍賈克。", description = "我的占卜者在中央高塔見到一個魔古首領。在他對我們的陣地發動攻擊之前，我們得殺掉他。\n\n你願意幫我辦這件事嗎?", progress = nil, completion = "門階上少了一項威脅。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n\n\n等級 51–80秘法珍寶\n\n等級 70–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32583] = {title = "赞达拉的崛起", objective = "消灭织魔者琼古瓦。", description = "我们在中央阶梯上发现了一位赞达拉首领。必须在返回营地前将他消灭。\n\n你能完成这项任务吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n秘法珍寶次級好運符咒"}
MultiLanguageQuestData['tw'][32585] = {title = "渗透力量", objective = "消灭赞达拉战争首领奴卡拉。", description = "我们在海滩上发现了一支赞达拉作战小队。必须赶在返回营地前将他们消灭。\n\n你愿意去执行这项任务吗？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32586] = {title = "電容上限", objective = "摧毀鬼鐵礦坑裡的3台閃電鑽孔機，並殺死冶煉統領魔諾汗。", description = "北方的礦坑是魔古重要的補給線。他們使用巨大的閃電附魔鑽孔機來採礦。\n\n假如你能破壞鑽孔機，中斷採礦行動，便能拖延魔古製造武器的速度。\n\n喔，對了。順便殺掉採礦的負責人，可以嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32587] = {title = "朝熔爐前進!", objective = "在雷王島上殺死熔爐統領，並從血肉工匠郝古身上取得聖典殘片。", description = "你眼前有一座熔爐，它是魔古鍛造武器的核心。\n\n更遠處的魔古守門人手中握有打開大門的鑰匙，從這扇門可以進入城市的另一區。\n\n該是時候出發了!", progress = "嗯?", completion = "做得好。你今天的作為讓我們朝終極目標又邁進一步。", rewards = "您會收到：\n\n\n\n等級 51–80秘法珍寶\n\n等級 65–70恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32588] = {title = "為魔法女士閣下的秘密效命", objective = "拯救被囚禁在鬼鐵礦坑裡的3名祈倫托密探，並殺死冶煉統領魔諾汗。", description = "珍娜下令派遣幾名密探試圖溜過魔古的防線，去探查礦坑裡的活動。\n\n他們卻被捉住了，受到鬼曉得是什麼樣的嚴刑拷打。\n\n請你務必救出他們，並殺死捉住他們的魔古。我們絕不拋下夥伴!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32589] = {title = "生命之血", objective = "使用調諧水晶從雷霆王座裡的黑暗憎惡魔像吸取憎惡魔像的殘魂。", description = "斥候從電光礦脈中挖掘出這個奇怪的傀儡，這肯定是雷王的秘密武器。\n\n也許，我們可以好好利用這個機會。如果能重新賦予傀儡生命，我們便能研究它。更重要的是，還能發現它的弱點。\n\n前往雷霆王座，使用這塊水晶捕捉任何驅動這些傀儡的精魄。\n\n完成任務後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n奪日者先鋒軍的榮耀軍旗恆龍寶箱"}
MultiLanguageQuestData['tw'][32591] = {title = "第一帝国的秘密", objective = "收集20份帝国秘史和40块延极锭。", description = "两千年来，这片土地始终都在魔古族的统治之下。他们施行的暴政如此残酷，以至于无人敢大声说出它的名字——熊猫人将它称作“古代王朝”或“第一王朝”。\n\n雷电之王是这一王朝的创建者，也是它的第一任君主。他在如今被称作雷神岛的地方积聚着巨大的力量。\n\n他的时代已经过去了，<name>。我们应该将他的部分力量化为己用。替我从雷电王座收集圣物，再找些延极锭来——我有个好办法！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32592] = {title = "我需要勇士", objective = "在雷神岛上击败魔古、赞达拉巨魔和蜥蜴人，在黑王子阵营中达到崇拜声望。", description = "你是你族人当中的盖世精锐，<race>。可我需要的是一个特别的帮手。我有一揽子的大计划。若要将这些计划变为现实，就得有一位勇士，将我的光辉散播到世界各处。\n\n你是合适的人选吗？\n\n去雷神岛向我证明你的实力吧！消灭你所遇到的所有魔古、赞达拉巨魔或蜥蜴人。让我对你刮目相看！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32593] = {title = "雷霆熔炉", objective = "在雷神岛上继续探索，直到你找到雷霆熔炉。与拉希奥在雷霆熔炉外面碰头，并完成他的任务。", description = "一切都准备好了，<name>，我也已经将你选为我的勇士。\n\n接下来，我们必须接近传说中雷神本尊的雷霆熔炉！你和你的阵营需要继续前进，直到雷霆熔炉暴露出来——如果它还没暴露的话。\n\n等你接近熔炉后，与我在那里会面。做好战斗的准备吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32594] = {title = "暴风领主之魂", objective = "在雷神岛上继续探索，直到你找到最后一个庭院。将长枪插进暴风领主纳拉克的身体里，坚持到将他的力量虹吸出来，以获得淬火闪电长枪。", description = "我们的下一个目标，就是要用充满雷电之王力量的半神之血来调节这把武器。\n\n据密探回报，有位名叫山怖的魔古族正在创造这样一种怪物，想让其戍守雷电堡。\n\n当你的阵营攻到前门时，攻击暴风领主纳拉克，并将这根长枪插进它的身侧。这只怪物会使出浑身解数来阻止你——在成功将暴风领主的力量吸出来以前，千万要挺住！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32595] = {title = "天堂之冠", objective = "到朦朧天梯的巧匠之愚頂端與怒西昂碰面，並領取獎賞。", description = "還記得你我之前碰面的巧匠之愚嗎?就是東方的那個山丘頂上。\n\n我要使用閃電長槍來製造一個特別的東西，肯定沒辦法在這裡完成。\n\n來巧匠之愚的頂端和我碰面，我們也許能一同慶祝勝利!您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n不撓原始鑽石英勇的原始鑽石電容原始鑽石厄邪的原始鑽石\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][32596] = {title = "泰坦回音", objective = "从修身殿和风暴之巅的团队首领身上取得12块泰坦符文石。", description = "我开始放眼大局了，并开始了解魔古族与泰坦的关联。但每个答案却衍生出更多的问题！\n\n要想把谜团解开，唯一的办法就是把从雷电之王宫殿里找到的所有关于泰坦的信息碎片都搜集起来。消灭雷电之王和他的爪牙，把能找到的泰坦符文石都拿回来！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32597] = {title = "雷神之核", objective = "在雷电王座内殿里消灭雷电之王，并取得雷神之核。", description = "已死去一万两千年之久的雷电之王，却被赞达拉的声音唤了回来。无疑是泰坦之力使他邪恶的尸身恒久不腐。\n\n泰坦之力应该归我所有。\n\n<name>！把雷神之核给我带回来。一旦我得到了它，谁也别想再让他起死回生。\n\n把它带来交给我，<class>。把他冰冷的核心交给我！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32599] = {title = "拯救未來", objective = "在風暴之巔擊敗雷王，並使用安東尼達斯之杖從高臺上吸取他剩餘的能量。", description = "謠傳說雷王的力量源自於宮殿底下的一處秘密來源。\n\n就算擊敗了他，下一位暴君，說不定就是卡爾洛斯，也可能會利用這股魔力來進行暴虐統治。\n\n因此我們得搶先一步！\n\n帶著我的法杖進入風暴之巔。一旦擊敗雷神，便將我的法杖插入高臺中心。\n\n我們要吸取他剩餘的能量，以確保為我們所用。", progress = "一旦雷神的力量灌注到我的法杖之中，我們便所向披靡了。", completion = "你幫了我們一個大忙，&lt;name&gt;。人們會永遠記得你的事蹟。\n\n卡爾洛斯會為他的行為付出代價！", rewards = "您會收到：\n\n祈倫托先遣軍的榮耀軍旗恆龍寶箱"}
MultiLanguageQuestData['tw'][32600] = {title = "贊達拉預言", objective = "把贊達拉預言交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n我已讀過你對贊達拉做的相關研究，我相信對於他們最近的大規模攻擊已經找出幾條線索。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "難怪贊達拉會來到這裡，他們需要一個新的家園。魔古肯定也承諾他們許多條件。\n\n我們會把這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32601] = {title = "雷聲迴盪", objective = "把雷聲迴盪交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n不祥的雷霆之聲讓我們世代的子民惶惶不安。就如你在研究中所發現，雷神是這股恐懼的源頭。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "我們對雷神的認知來自於流傳已久的黑暗傳說。我常常懷疑這些傳說是否誇大了雷神的力量，然而你的研究卻指出，雷王的能力可能遠遠被低估了。那的確是一段慘不忍睹的時光。\n\n我們會把這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32602] = {title = "神與魔", objective = "把《神與魔》交給博學行者阿洲。\n\n已提供物品：\n", description = "親愛的$p，\n\n魔古真的與泰坦有關嗎？我感到難以相信。可是看過你的研究之後，一些關於魔古的真相開始出現輪廓。\n\n如果你到恆春谷的知識之座來找我們，我們會把這項成果加到你的個人收藏中。\n\n感謝你的努力！\n\n誠摯的，\n\n博學行者阿洲", progress = nil, completion = "你的研究結果讓人煩惱，但是卻解答了我們長久以來的問題：魔古來自哪裡？為什麼他們會如此殘暴？\n\n我們會把這個知識加進你的收藏中。如果你希望我為你講這個故事，就到你的私人收藏裡點選正確的書籍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32603] = {title = "寓言裡的野獸", objective = "擊敗熊貓人寓言中的精英戰寵。", description = "你讀過熊貓人的寓言故事嗎?熊貓人唸裡頭的故事，像是蟋蟀與老鷹、慢慢爬的烏龜給小孩子聽，來教導孩子們人生的道理。孩子們不曉得的是，潘達利亞的確有這些生物存在!雖然關於旅行的故事是虛構的，然而它們確實是這個世界上強大的居住者。若你在旅途中碰巧遇見，可以拿身邊的寵物與它們一較高下。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n小熊貓"}
MultiLanguageQuestData['tw'][32604] = {title = "寓言裡的野獸:第一冊", objective = "擊敗『暴食者』卡威、泥吞、卡菲和朵斯雷加。", description = "『暴食者』卡威、泥吞、卡菲、朵斯雷加的故事會在這片土地永遠流傳，你希望再次與牠們較量嗎?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n熊貓人寓言寵物用品"}
MultiLanguageQuestData['tw'][32605] = {title = "給點顏色瞧瞧", objective = "將魔古武器埋入9名污刃薩烏洛克的屍體內。", description = "薩烏洛克雖然討厭，但我們有共同的敵人，那就是魔古。 與其派自己人去對付魔古，倒不如派薩烏洛克過去。\n\n我們收集了魔古的武器，將這些長柄武器埋入薩烏洛克的頭顱裡，以敵克敵也許能拯救部落的性命。", progress = nil, completion = "做得漂亮，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32606] = {title = "給點顏色瞧瞧", objective = "將魔古武器埋入9名污刃薩烏洛克的屍體內。", description = "薩烏洛克雖然討厭，但我們有共同的敵人，那就是魔古。 與其派自己人去對付魔古，倒不如派薩烏洛克過去。\n\n我們收集了魔古的武器，將這些長柄武器埋入薩烏洛克的頭顱裡，以敵克敵也許能拯救聯盟的性命。", progress = nil, completion = "做得漂亮，&lt;class&gt;。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32608] = {title = "襲擊寶庫", objective = "從天驕寶庫取得風暴頸飾。", description = "天驕寶庫裡頭存放著幾件雷神最險惡的武器，同時也是雷神最珍貴的寶物 - 這兩種東西往往是一樣的，真是不意外。\n\n其中一件名叫風暴頸飾的護符是能夠駕馭雷電的神器。\n\n闖入寶庫殺死裡頭的管庫，拿走他的鑰匙並從寶庫後面的貯藏箱裡取出護符。", progress = "雷王的力量超凡入聖，我們需要取得一切幫助來擊敗他。", completion = "這是什麼? 一條項鍊?你是想...啊，我知道了。這是雷王寶庫裡的寶物!真是漂亮...而且威力強大。\n\n祈倫托會妥善保管它。請你收下這份禮物作為回報。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
