MultiLanguageQuestData['tw'][32618] = {title = "騎術訓練", objective = "找到蘭達爾‧亨特。", description = "你學習騎術的時候到了！到艾爾文森林的東谷伐木場找蘭達爾‧亨特。到了那裡別忘了買個坐騎！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32621] = {title = "雷鋼", objective = "調查雷霆熔爐，找出雷鋼的秘密。\n\n已提供物品：\n", description = "以你的專業眼光，可以看出這塊金屬具有非常奇異的特徵。也許在這附近有什麼線索可以透露出它的性質。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n雷鋼錠雷鋼筆記"}
