MultiLanguageQuestData['tw'][32630] = {title = "首席工程師賈德的日誌", objective = "調查雷霆熔爐，解開穩定的閃電之謎。多麼不尋常的能量來源。不曉得它如何運作?又能創造出什麼?您會收到：\n\n", description = "多麼不尋常的能量來源。不曉得它如何運作?又能創造出什麼?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n賈德奇特的能量來源首席工程師賈德的日誌"}
MultiLanguageQuestData['tw'][32632] = {title = "戰爭利器", objective = "殺死柴星毀滅者。", description = "有些東西存在的理由很複雜，有些東西只是為了破壞而生。\n\n一種名叫柴星毀滅者的巨大傀儡鎮守著曦尋者之岬，它的唯一功用就是造成破壞，務必除掉它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32633] = {title = "夢寐以求的寶物", objective = "從曦尋者之岬取回洛摩斯的咒術之書。", description = "大博學者洛摩斯身上有一件我非常想要的東西。\n\n他隨身帶著一本強大的魔典，如果他失去了這本書，那對我們的戰況會非常有利。\n\n找出洛摩斯的咒術之書並帶回來給我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32634] = {title = "粉碎防御", objective = "在寻晨者海角附近摧毁6个夺日者监视结界。", description = "哪怕是最无懈可击的防御也会有薄弱点，<class>。我们只需要找到夺日者防线的薄弱点，然后尽可能地加以利用。\n\n据斥候回报，在寻晨者海角四处布满了监视结界。这些结界十分强大，可并不具有致命的杀伤力。\n\n如果能让它们失效，我们就能近距离监视夺日者的行动了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32635] = {title = "终止爆炸！", objective = "在紫罗兰高地卸除联盟舰船、构造体仪式和补给品附近的战术魔法炸弹。", description = "夺日者在我们的营地四周布满了战术魔法炸弹。必须在这些炸弹爆破前将其卸除。\n\n在重要区域搜寻这些炸弹，比如我们的补给品附近。一定要找到并把它们全都卸除。我们决不能再失去任何阵地了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32636] = {title = "釋放俘虜", objective = "釋放5名曦尋者之岬附近的祈倫托俘虜。", description = "奪日者願意不擇手段，以獲得想要的東西，<name>。\n\n之前我收到回報，得知幾名祈倫托的成員不見了。我懷疑是奪日者動的手腳。\n\n希望他們安然無恙，否則我會採取立即且殘暴的報復手段。我相信你能將他們安全帶回來，不過請快一點。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32637] = {title = "壓制", objective = "摧毀7個曦尋者之岬周圍的奪日者法力收集器。", description = "最近奪日者的軍力變得更加強大了。我懷疑是因為使用魔法的緣故，但是又不敢肯定。\n\n調查他們的營地，尋找這個額外能量的來源，應該是比較聰明的做法。\n\n一旦你找到了，便使用這塊水晶超載能量並摧毀它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32638] = {title = "魔法清道夫", objective = "消灭9只夺日者法力浮龙。", description = "有时候，最微不足道的生物却能造成最大的威胁。\n\n夺日者携带法力浮龙作战。虽然体型小巧，但却能让我们的施法者在战斗中阵脚大乱。许多人都为轻敌付出了惨痛代价。\n\n必须尽快消灭它们。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32639] = {title = "摧毀傀儡", objective = "摧毀3個曦尋者之岬外圍的奪日者傀儡。", description = "斥候回報，有大批的傀儡巡邏於曦尋者之岬的外圍。\n\n若放任不管，將來奪日者發動攻擊時，它們將是可怕的威脅。\n\n唯一的辦法就是先發制人。在傀儡攻擊我們之前先摧毀它們!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32640] = {title = "雷王的勇士", objective = "在雷王島上的各地使用衫織儀式石以進行閃電儀式、靈魂儀式與原始儀式，然後擊敗召喚出來的強大對手。", description = "這座島上四伏的危機來自於三大群敵人:控雷者、強大的古靈與原始贊達拉巨獸，他們總是伺機從旁攻擊我們。\n\n如果你能取回一些散落在島上的衫織儀式石，你便能喚出這些強大的對手與他們正面交鋒。\n\n找出並擊敗每一群敵人的成員來動搖他們的根本，你會得到豐厚的獎勵。", progress = nil, completion = "你身為&lt;class&gt;的能力是不容質疑的。你幫了我們一個大忙，非常謝謝你。\n\n這是我答應給你的獎勵...", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32641] = {title = "雷王的勇士", objective = "在雷王島上的各地使用衫織儀式石以進行閃電儀式、靈魂儀式與原始儀式，然後擊敗召喚出來的強大對手。", description = "這座島上四伏的危機來自於三大群敵人:控雷者、強大的古靈與原始贊達拉巨獸，他們總是伺機從旁攻擊我們。\n\n如果你能取回一些散落在島上的衫織儀式石，你便能喚出這些強大的對手與他們正面交鋒。\n\n找出並擊敗每一群敵人的成員來動搖他們的根本，你會得到豐厚的獎勵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32642] = {title = "工作令：制霸先鋒軍I", objective = "在日歌農莊播下8顆紅花蔥的種子。", description = "<從字跡似乎可以看出尹矛盾的情緒。>\n\n我向來不喜歡淌渾水，但是工作令就是工作令。既然你是部落的一員，我決定將工作令交給你。\n\n制霸先鋒軍需要紅花蔥。\n\n那裡的部隊似乎總是吃不膩紅花蔥!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32643] = {title = "工作令：制霸先鋒軍II", objective = "採收8株成熟的紅花蔥，並提供40顆紅花蔥給制霸先鋒軍。", description = "一旦你的紅花蔥長大成熟了，你只需要將它們裝入木箱等人來取。\n\n只要這樣想，這些紅花蔥也會是你的陣營對潘達利亞所做的貢獻!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32644] = {title = "襲擊韶嘛喇", objective = "完成襲擊韶嘛喇。與珍娜‧普勞德摩爾交談以展開攻擊。", description = "我們的密探在海岸進行的偵察行動，提供我們島上的可貴資訊，<class>。\n\n然而，我們若不朝大陸發動攻擊，便無法取得任何成果。\n\n我集結了一支最優秀的空中部隊準備展開進攻。\n\n我要你加入攻擊的行列。像你這樣的勇士能在關鍵時刻扭轉戰局。\n\n當你準備好開戰時告訴我一聲。", progress = nil, completion = "很好!你辦到了，勇士!\n\n現在，雷霆之王將會嘗到祈倫托的厲害!", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32645] = {title = "工作令：鐵壁特遣行動I", objective = "在日歌農莊播下8顆巫莓的種子。", description = "<從字跡似乎可以看出尹矛盾的情緒。>\n\n我向來不喜歡淌渾水，但是工作令就是工作令。既然你是聯盟的一員，我決定將工作令交給你。\n\n鐵壁特遣行動需要一堆巫莓。\n\n雖然不肯定，但是我認為他們想出了某種把巫莓當成武器的辦法。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32646] = {title = "工作令：鐵壁特遣行動II", objective = "採收8株成熟的巫莓，並提供40顆巫莓給鐵壁特遣行動。", description = "一旦你的巫莓長大成熟了，你只需要將它們裝入木箱等人來取。\n\n你想想，這些巫莓會成為你的陣營對潘達利亞所做的貢獻!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32647] = {title = "工作令：金蓮會I", objective = "在日歌農莊播下8顆白菜頭的種子。", description = "<尹的這張工作令相當簡短。>\n\n金蓮會需要大量的白菜頭。\n\n他們提到有愛搗蛋的妖精在霧臨村大鬧。顯然這些妖精討厭菜頭!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32648] = {title = "工作令：金蓮會II", objective = "採收8株成熟的白菜頭，並提供40顆白菜頭給金蓮會。", description = "希望這些作物符合他們的需要!\n\n一旦你的白菜頭準備好收成，你只要把它們打包好等人來拿就可以了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32649] = {title = "工作令：影潘I", objective = "在日歌農莊播下8顆綠色捲心菜的種子。", description = "<尹的字跡潦草，他當時的心情肯定很興奮。>\n\n影潘需要你的作物!這是多麼榮幸的事情啊!\n\n今早他們提出需要綠色捲心菜的要求。顯然他們之前做的捲心菜湯相當美味。\n\n只有最棒的食材才配得上影潘!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32650] = {title = "工作令：影潘II", objective = "採收8株成熟的綠色捲心菜，並提供40顆綠色捲心菜給影潘。", description = "你今日的工作已經完成了!現在只要等著明天收割就好。\n\n一旦你的綠色捲心菜長大成熟，你只要把它們打包好等人來拿就可以了。\n\n只有最棒的捲心菜才配得上影潘!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32651] = {title = "飞行介绍", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32652] = {title = "飛上天吧!", objective = "進入電光礦脈。", description = "我們計畫終止魔古製造武器的能力，計畫中會用到你從贊達拉那裡取得的生物。\n\n準備好的時候跟我說一聲。", progress = nil, completion = "幹得好哇。這讓我們有一個大好機會。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32653] = {title = "工作令：聖獸天尊I", objective = "在日歌農莊播下8顆條紋甜瓜的種子。", description = "<破爛的紙張上有尹熟悉的字跡。>\n\n赤吉搖籃的受訓弟子需要條紋甜瓜，顯然是拿來練習用的。\n\n明天將有個代表會來收集你所能提供的所有條紋甜瓜。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32654] = {title = "突破城牆!", objective = "與珍娜‧普勞德摩爾女士交談，然後攻下城市的下層區，為聯盟奪回這座城池。", description = "時候到了。我們的軍隊屯營在這裡養精蓄銳，該朝雷王的巢穴推進了。可惜，雷王看來是不會自動打開那扇大門的。\n\n我想我們得自己打一個通道進去。你準備好的時候告訴我一聲，<name>。", progress = nil, completion = "在你的幫助之下，我們朝目標邁進一大步。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32655] = {title = "出奇制勝", objective = "潛入狂濤港，從裡頭打開庭院大門。與陶氏交談以展開任務。", description = "贊達拉的戰艦劫掠島嶼海岸，他們從贊達拉運來士兵與戰爭猛獸來助長雷神的氣焰。\n\n如果我們能攻下宮殿的船塢，便能切斷雷王的補給線，而你們在這島的根基也會更穩固。\n\n我有個計畫，不需要派出全部兵力就能達到目的。", progress = nil, completion = "做得好。那艘戰艦一時之間無法再轟擊我們的部隊了。\n\n塔蘭‧祝通知我，影潘將持續監視狂濤港，如此祈倫托的資源就能重新分配到各地以展開圍攻。陶氏也會在狂濤港那，她肯定會很開心能再次與你合作。\n\n我們都很感謝你的貢獻，&lt;name&gt;。謝謝你。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32656] = {title = "衫布敗亡", objective = "擊敗衫布。", description = "雷神在早年的一場戰役中找到了一窩稀有的風暴龍蛋。孵出來的幼龍中有一隻叫納拉卡的性格特別殘暴，殺死了每個照顧他的人，因此雷神便親自飼養這隻惡龍。\n\n現在，雷神忠實的僕人衫布正在復活這隻飛龍。\n\n此刻正是討伐衫布的時機!\n\n等你準備好發動攻擊時跟我說一聲!", progress = nil, completion = "你辦到了，&lt;class&gt;!衫布永遠死了，我們也知道洛索瑪也沒那麼像他的外表一樣。", rewards = "這個任務線能解鎖：\n\n每日任務：雷王島\n\n您還會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32657] = {title = "工作令：聖獸天尊II", objective = "採收8株成熟的條紋甜瓜，並提供40顆條紋甜瓜給聖獸天尊。", description = "一旦你的條紋甜瓜可以收成了，你只要把它們打包好等人來拿就可以了。\n\n一名赤吉搖籃的受訓弟子很快就會來拿甜瓜。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32658] = {title = "工作令：卡拉西I", objective = "在日歌農莊播下8顆魔古南瓜的種子。", description = "<雖然農夫尹的字跡潦草得難以入目，但農場裡能有這一點來自他的東西還是令人開心的。>\n\n今早卡拉西那兒來了一張工作令，他們居然想要一些魔古南瓜來做點研究。\n\n我發現最好還是別問他們太多問題...\n\n你最好開始栽種。如果你不乖乖聽話的話，我不敢想像那樣巨大的蟲子會對你的作物做出什麼事情!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32659] = {title = "工作令：卡拉西II", objective = "採收8株成熟的魔古南瓜，並提供40顆魔古南瓜給卡拉西。", description = "一旦你的魔古南瓜長大成熟，只要把它們打包好等人來拿就可以了。\n\n如果我是你的話，我就會趕緊行動。卡拉西向來沒什麼耐心!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次級好運符咒"}
MultiLanguageQuestData['tw'][32661] = {title = "騎術訓練", objective = "找到阿露恩。", description = "你學習騎術的時候到了！到藍謎島的艾克索達入口處找阿露恩。到了那裡別忘了買個坐騎！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32662] = {title = "騎術訓練", objective = "找到奧薩姆‧鐵角。", description = "你學習騎術的時候到了！到丹莫洛的凍石農場找奧薩姆，沿著鐵爐堡外的東邊道路一直走就可以到達。到了那裡別忘了買個坐騎！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
