MultiLanguageQuestData['tw'][32672] = {title = "騎術訓練", objective = "找到維爾瑪‧瓦納姆。", description = "你學習騎術的時候到了！到提里斯法林地的布瑞爾找維爾瑪‧瓦納姆。到了那裡別忘了買個坐騎！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32673] = {title = "騎術訓練", objective = "找到莉薇‧彈桿。", description = "你學習騎術的時候到了！到奧格瑪的精神谷找莉薇‧彈桿。到了那裡別忘了買個坐騎！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32674] = {title = "你肯定能飛", objective = "找到瑪茲薩。", description = "天空召喚著你！學習飛行的時候到了！\n\n到奧格瑪的航線找飛行訓練師瑪茲薩。\n\n別忘了買一隻飛行坐騎！", progress = nil, completion = "啊，很高興見到你。看來你已經準備好學習飛行！\n\n記住，你可以從我身後的德拉克瑪那裡買一隻飛行坐騎。", rewards = nil}
MultiLanguageQuestData['tw'][32675] = {title = "你肯定能飛", objective = "找到布拉拉‧雲翼。", description = "天空召喚著你！學習飛行的時候到了！\n\n到暴風城的獅鷲獸棲息處找飛行訓練師布拉拉‧雲翼。\n\n別忘了買一隻飛行坐騎！", progress = nil, completion = "啊，很高興見到你。看來你已經準備好學習飛行！\n\n記住，你可以從坦涅克‧石喙那裡買一隻飛行坐騎。", rewards = nil}
MultiLanguageQuestData['tw'][32677] = {title = "襲擊寶庫", objective = "從天驕寶庫取得風暴頸飾。", description = "天驕寶庫裡頭存放幾件雷神最險惡的武器，同時也是最珍貴的寶物。\n\n其中一件名叫風暴頸飾的護符，能幫助我們了解雷神駕馭雷電的能力。\n\n闖入寶庫殺死裡頭的管庫，拿走他的鑰匙從寶庫後面的貯藏箱裡取出護符。", progress = "希望你帶來好消息。", completion = "喔，我一眼就能認出寶物的價值。你把它帶來這裡是對的。我會立刻讓埃薩檢查一番，也許我們能好好利用它。\n\n同時，請收下這份禮物作為交換。", rewards = "您會收到：\n\n恆龍寶箱次級好運符咒"}
MultiLanguageQuestData['tw'][32678] = {title = "緊急召喚", objective = "回到螳螂荒原的影潘要塞向斥候隊長艾爾西雅回報。", description = "攻擊雷王的時候到了!\n\n一群奪日者在螳螂荒原的影潘要塞附近等著你。\n\n向斥候隊長艾爾西雅回報取得進一步指示。", progress = nil, completion = "我們得趕緊行動，&lt;name&gt;!其他人已經先出發了，我會在飛行中跟你簡單做個介紹。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32679] = {title = "緊急召喚", objective = "回到螳螂荒原的影潘要塞向凡蕾莎‧風行者回報。", description = "攻擊雷王的時候到了!\n\n一群祈倫托的成員在螳螂荒原的影潘要塞附近等著你。\n\n向凡蕾莎‧風行者回報取得進一步指示。", progress = nil, completion = "我們得趕緊行動，&lt;name&gt;!其他人已經先出發了，我會在飛行中跟你簡單做個介紹。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32680] = {title = "沙場點兵", objective = "與斥候隊長艾爾西雅一起旅行到雷王島。", description = "沒時間浪費了，<name>。我們在這裡多待一刻，就讓珍娜與祈倫托多一分佔領島嶼的機會。\n\n洛索瑪等著我們。準備好了就跟我說，我會親自護送你到那裡。", progress = nil, completion = "你及時趕到了，獸人。趕在祈倫托之前控制這片海岸，對這場戰役來說非常重要。\n\n這事說來話長。", rewards = "您會學到：\n\n每日任務：雷王島\n\n您還會收到：\n\n奪日者信標恆龍寶箱"}
MultiLanguageQuestData['tw'][32681] = {title = "沙場點兵", objective = "與凡蕾莎‧風行者一起旅行到雷王島。", description = "沒時間浪費了，<name>。我們在這裡多待一刻，就讓奪日者多一分佔領島嶼的機會。\n\n珍娜‧普勞德摩爾女士等著我們，別讓她等太久。\n\n準備好了就跟我說，我會親自護送你到那裡。", progress = nil, completion = "你來的正是時候，&lt;name&gt;。為了大家的安全，祈倫托必須擁有這片海岸的控制權。這不是個容易的任務。", rewards = "這個任務線能解鎖：\n\n每日任務：雷王島\n\n您還會收到：\n\n祈倫托信標恆龍寶箱"}
MultiLanguageQuestData['tw'][32682] = {title = "耕者繼承人", objective = "與農夫尹交談。", description = "你也知道，<name>，我的年紀漸漸大了。人不可能常保年輕的狀態。\n\n我正在找尋耕者工會的接班人，我覺得農夫尹是最適合的人選。\n\n他還有很多事情需要學習，但是他頭腦聰明，而且最重要的是，他有寬厚的胸懷。\n\n你覺得他會對這個位置感興趣嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32683] = {title = "所以你想當個鐵匠…", objective = "當鍛造技能達到至少500點時做出一把鬼靈骷髏鑰匙。如果你希望使用潘達利亞的材料來進行訓練，你可以從庫侖‧錘眉那裡學習適合你技能等級的訓練課程。", description = "從簡單一點的金屬特性開始學起，並且由淺入深，是最穩紮穩打的方式。但是你也能藉由擅長使用鬼鐵製作各種家用物件而成為一位優秀的鐵匠。如果你有心成為一位禪師級鐵匠，我可以示範給你看。不管你選擇哪一條道路，只要你能做出一把鬼靈骷髏鑰匙給我，你便能獲得我的尊敬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32684] = {title = "你想釣魚嗎？", objective = "與『大聲公』班交談。", description = "你在尋找金鯉魚嗎？或其他的潘達利亞魚類？我不是漁夫，但是河畔有個人專門教導經過這一區的旅行者。如果你跟他說話，他可能會給你一些魚，並教你如何釣魚。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n金鯉魚"}
MultiLanguageQuestData['tw'][32685] = {title = "不需要釣竿！", objective = "釣5隻金鯉魚。不需要釣竿就可以釣魚！\n\n只要點擊專業技能欄位裡的釣魚圖示。注意水中的浮標，當浮標濺起水花的時候，立刻點擊浮標就能捕捉上鉤的魚！", description = "在潘達利亞釣魚，你甚至不需要釣竿！\n\n這裡的水域到處都是魚。只要保持專注，你幾乎每次都能釣到魚。去試試看吧！", progress = "釣5隻金鯉魚。不需要釣竿就可以釣魚！", completion = "讓我瞧瞧… 沒錯，這些是上等的鯉魚。做得好！來，給你更多魚。", rewards = "您會收到：\n\n金鯉魚恆龍寶箱"}
MultiLanguageQuestData['tw'][32686] = {title = "完好如初的螳螂人帝國旌旗", objective = "展示考古文物。", description = "這件古物已經被回復到十分良好的狀態。也許你可以將它展示在知識之座，讓博學行者和考古學家們可以研究。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n復原的古文物螳螂人琥珀稜片"}
