MultiLanguageQuestData['tw'][32728] = {title = "白骨之廷", objective = "尋找白骨之廷外的大博學者洛摩斯。", description = "白骨之廷附近的魔古持續對我們在這座島上的據地造成威脅。大博學者洛摩斯已受委託來中止他們的行動。有了厲害的<class>，他肯定能更加順利地完成任務。\n\n去找他，並盡你所能幫助他。", progress = nil, completion = "很好，來吧…該是做個了結的時候了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32729] = {title = "札突爾", objective = "尋找札突爾外的赫杜倫‧亮翼。", description = "自從我們來到這座島，贊達拉就一直是我們的心頭之患。我已派遣赫杜倫‧亮翼去消滅南方札突爾的食人妖。\n\n準備好了就向赫杜倫回報，他有工作給你。", progress = nil, completion = "又多一個幫手來追捕贊達拉嗎？很好，非常好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32730] = {title = "伊加路克峭壁", objective = "尋找伊加路克峭壁外的大法師埃薩‧奪日者。", description = "埃薩已經統治東南方的伊加路克峭壁，並持續利用薩烏洛克來對付贊達拉和魔古。\n\n去找他，並盡你所能幫助他。", progress = nil, completion = "你來的正是時候。我非常需要你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32731] = {title = "白骨之廷", objective = "尋找白骨之廷外的娜拉希‧雪曦。", description = "白骨之廷附近的魔古是我們在這座島上的重大威脅。娜拉希‧雪曦已受委託來中止他們的行動，不過我相信如果有個能幹的<class>來幫忙，對她的任務肯定有幫助。\n\n去找她，並盡你所能協助她。", progress = nil, completion = "很好，來吧…我們有工作要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32732] = {title = "伊加路克峭壁", objective = "尋找伊加路克峭壁外的大法師莫德菈。", description = "大法師莫德菈已經統治東南方的伊加路克峭壁，並持續利用薩烏洛克來對付贊達拉和魔古。\n\n去找她，並盡你所能幫助她。", progress = nil, completion = "你來的正是時候。我非常需要你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32733] = {title = "札突爾", objective = "尋找札突爾外的大法師朗達拉克。", description = "自從我們來到這座島，贊達拉就一直是我們的心頭之患。我已派遣大法師朗達拉克去消滅南方札突爾的食人妖。\n\n準備好了就向他回報，他有工作給你。", progress = nil, completion = "又多一個幫手來追捕贊達拉嗎？很好，非常好。", rewards = "您會收到：\n\n"}
