MultiLanguageQuestData['tw'][32804] = {title = "死者的遺物", objective = "找回10個死去霜狼族人的遺物。", description = "就算在復仇行動中，我們也必須秉持霜狼一族的榮耀。\n\n無數驍勇的霜狼族獸人就葬身在下方的洞穴裡。他們不能被遺忘。\n\n在你執行格納爾的任務時，順便尋找死去弟兄的遺物。把遺物帶來給我，我會交給薩滿，再按照傳統舉行一場葬禮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32805] = {title = "天神的祝福", objective = "前往昆莱山的白虎寺、卡桑琅丛林的朱鹤寺、翡翠林的青龙寺、螳螂高原的砮皂寺，获得四位天神的祝福。完成他们四项挑战中的其中一项。", description = "我愿意将自己全部的巨龙之力都赋予你，但遗憾的是，那会使你的凡人之躯彻底瓦解。不过，希望仍在——我相信我能创造出一个强大的容器来供你使用。\n\n要想制作这个容器，我需要潘达利亚四位至尊天神的祝福。与我一同前往那四座神殿吧，让我们与诸位天神谈一谈。若要让自己配得上他们的馈赠，你必须赢得他们其中一项挑战。\n\n这些挑战可不简单——选择与你的装备和技能最相匹配的挑战吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32806] = {title = "王者與議會", objective = "完成「血染滄雪」事件。你可以使用地城搜尋器加入佇列，或是使用博學行者阿洲的夢幻之釀。", description = "<name>，很高興你來了。我一直用夢幻之釀來體驗世界裡的各種事件，可是我知道得越多，我就變得越困惑。\n\n舉例來說，烏瑞恩王向鐵爐堡的矮人要求更多的部隊，可是並非所有人都支持他。\n\n我可以再說下去，可是我也想聽聽你親身的經歷...", progress = nil, completion = "喔，烏瑞恩王和黑鐵矮人拯救了城市，分崩離析的三錘會在聯盟的大旗下重新團結。真有意思!\n\n可是部落那邊怎麼了呢?", rewards = "您能選擇下列奬勵中的一個：\n\n大型藏寶箱\n\n您還會收到：\n\n大型藏寶箱恆龍寶箱"}
MultiLanguageQuestData['tw'][32807] = {title = "大酋長與黑暗", objective = "完成「潘達利亞的黑暗之心」事件。你可以使用地城搜尋器加入佇列，或是使用博學行者阿洲的夢幻之釀。", description = "我現在知道聯盟的王者是怎麼領導人民了。可是部落的大酋長在做什麼?我們腳下有一大群的哥布林，受他命令在神聖的恒春谷中進行挖掘。他想在那裡找出什麼?我們一定要查出來!", progress = nil, completion = "什麼?有一位上古之神的遺骸就埋葬在潘達利亞?難怪這片大地如此紛擾!\n\n大酋長對那些蟄伏力量的追尋正在撕裂他所領導的部落。他的眼光不但狹隘，而且極度危險。我得馬上通知影潘。", rewards = "您能選擇下列奬勵中的一個：\n\n大型藏寶箱\n\n您還會收到：\n\n大型藏寶箱恆龍寶箱"}
MultiLanguageQuestData['tw'][32808] = {title = "來點前線偵查", objective = "到七星廟找格里坡·恰恰開關，前往卡林多。接著與琥珀·吉爾妮交談，她正在偵查杜洛塔骷髏石附近的刃拳海灣。", description = "我的夢幻之釀能透露的就只有這些了。它顯露的景象分散在時空之中。可是奧格瑪的部落首都顯然醞釀著一場風暴。\n\n你應該前往那裡，親眼見證那些事件!\n\n我在夢幻之釀中見到兩位勇敢的聯盟間諜獨自深入杜洛塔。一個叫「琥珀」，一個叫「蘇利」...\n\n也許你還記得他們?我想他們需要你的協助!\n\n你可以在卡林多找到琥珀和蘇利，就在奧格瑪門外一個叫做薩魯法爾防線的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32809] = {title = "收集情报", objective = "取得“库卡隆补给线”、“行动：毁灭暗矛部族”和“库卡隆指挥官位置图”，并释放囚犯。", description = "加尔鲁什继续在奥格瑞玛壮大自己的军队——这地方简直像堡垒一样！\n\n乌瑞恩国王不愿意冒险出击，除非我们搜集到了尽可能多的情报。\n\n利用C4T计划对封锁线展开调查。尽你所能地搜集情报。寻找任何高优先级的文件，以及任何我们能加以利用的薄弱点。一定要眼观六路耳听八方，小心行事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32810] = {title = "暗矛起义军", objective = "在杜隆塔尔的剃刀岭与岑塔布拉交谈。", description = "巨魔们公然反叛了。我们正好可以利用这一点！要是他们能开辟出第二条战线，加尔鲁什就会分身乏术，无法同时抵挡我们两支攻城大军。\n\n我这里有一项风险极高的任务要你去完成。我要你充当联盟代表，去与暗矛部族的沃金展开谈判。\n\n试着找到我们从库卡隆手中救出的巨魔囚犯。好像是叫岑塔布拉对吧？\n\n这也许是我们击垮加尔鲁什的唯一机会……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32811] = {title = "戰場:貧瘠之地", objective = "收集15份柯爾克隆木材、15份柯爾克隆之油、15份柯爾克隆肉塊與15份柯爾克隆石材。", description = "你想要我們與你合作，就得先贏得我的信任。\n\n柯爾克隆正在北貧瘠之地集結備戰。地獄吼的走狗正在囤積木材、油料、食材與肉類。我們暗矛打算利用那些補給來對付他們。\n\n前往貧瘠之地。把補給帶來給我!見到他們就殺，保衛補給車隊，組隊合作打倒強敵，盡你所能就對了。\n\n向我證明聯盟的意願!我會盯著你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32812] = {title = "暗矛反抗軍", objective = "到杜洛塔的森金村找奇塔·箭牙。", description = "我的夢幻之釀能透露的就只有這些了。它透露的景象分散在時空之中。可是部落內部顯然醞釀著一場風暴。\n\n我在夢幻之釀裡看到了暗矛氏族的食人妖沃金已經前往杜洛塔保衛他的族人。漂流島的釀酒大師老陳·風暴烈酒與他同行。\n\n依我對老陳的了解，那就是他很快就會惹出麻煩來...你得加緊腳步!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32813] = {title = "森金村之戰", objective = "從柯爾克隆的攻勢下守住森金村。", description = "<遠方響起戰鼓的聲音。>\n\n<class>你總是在正確的時間現身。地獄吼要對自己的同伴出手了。\n\n他會見識到激怒暗矛的代價。來吧!和我們一同作戰!讓他們瞧瞧真正的部落之魂!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32814] = {title = "剃刀嶺之戰", objective = "為暗矛革命軍解放6個俘虜並打敗柯爾克隆領袖，佔領剃刀嶺。", description = "現在，我們反擊!我們不要讓地獄吼有時間重整部隊。上馬吧!向北進軍。只要碰到柯爾克隆，就割斷他們的脖子。\n\n如果我們拿下了剃刀嶺，我們就控制了杜洛塔所有的道路。\n\n來吧!跟我走!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32815] = {title = "年老的先知", objective = "到崑萊峰奈佛勒斯山的坡道上找出先知昊范州。", description = "我可以幫你收集故事的片段，但要靠你自己才能將它們拼湊起來。而我可能恰好知道你該從哪裡著手。\n\n我聽過先知昊范州這個老學者的故事。他算是...潘達利亞歷史的專家，而且也許可以對潘達利亞當下的動盪之勢提供線索。\n\n<name>。去找他吧，<name>。我最近聽說他打算追隨紹昊的腳步，登上崑萊峰的奈佛勒斯山。", progress = nil, completion = "&lt;呼&gt;喔，你好，&lt;呼&gt;年輕人，你好啊。\n\n今天的風刮得可真大啊，不是嗎?", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][32816] = {title = "末帝之道", objective = "護送先知昊范州前往追尋者聖壇。沿路將他的登山繩裝在每個繩索錨點，幫助他攀爬山脈。", description = "每當心有疑慮的時候，末代皇帝會上山獨行，直到找出心中的解答。\n\n我來這裡走上相同的道路，看來你也有疑問需要解答。也許你可以加入我，一同找到答案?\n\n喔，可是我已經老了，我這身老骨頭受不了這場風雪。你可以往前爬然後固定好這條繩索嗎?我可以從那裡攀著繩索過去。\n\n我們可以一起踏上末代皇帝走過的道路。", progress = nil, completion = "我們成功了，&lt;class&gt;!真是謝謝你。請收下我的小飾品。\n\n不過...我有些事情沒有跟你說過...", rewards = "緘默足靴謙遜長靴尊敬足靴無盡耐心長靴謙卑脛甲謙虛便鞋奉承巨靴保守軟靴謙讓長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][32819] = {title = "戰場:貧瘠之地", objective = "收集15份柯爾克隆木材、15份柯爾克隆之油、15份柯爾克隆肉塊與15份柯爾克隆石材。", description = "要擊垮大酋長，我需要軍隊與補給。\n\n我已經有軍隊了，在地獄吼對部落的作為之後，我們的恨意也不匱乏。可是我們要補給!木材、肉品、油料和石材。我們需要這些東西\n\n地獄吼的柯爾克隆在我們西邊的北貧瘠之地囤積補給品。殺掉柯爾克隆!見一個殺一個。幫我們的牛頭人弟兄護衛他們的車隊，並且組隊合作打倒柯爾克隆的領袖。怎麼做都可以。\n\n把補給帶回來給我!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32832] = {title = "祝踏岚与德兹科场景", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][32836] = {title = "冒牌土笛子", objective = "前往你所在阵营的搏击俱乐部，把冒牌土笛子交给那里的某个人。", description = "这支“土笛子”是草草用树根雕凿而成，笛身遍布凹凸不平的孔洞。\n\n但在仔细检查背面之后，你发现了这样一行刻字：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32837] = {title = "寶笛爺爺", objective = "購買寶笛爺爺的挑戰卡然後在鬥陣俱樂部向他挑戰並且擊敗他。", description = "我今天為你準備的挑戰卡屬於一個有著可愛名字的咕嚕摩，他叫寶笛爺爺。咕嚕摩並不以戰鬥技巧聞名，不過他們可是出奇好運的小傢伙。\n\n也許是因為他們的...叫什麼來著...幸運星的關係?您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n吹笛者外套巨大的一袋錢幣"}
MultiLanguageQuestData['tw'][32838] = {title = "俠義浪漫譚", objective = "把「熊與夫人」交給所屬陣營之鬥陣俱樂部裡的某個人。", description = "一本寫給孩子看的小書。書本的裝訂很不錯，書況也很好。\n\n在封底接近書脊的地方，你發現一小段字體流暢的文字:\n\n交還鬥陣俱樂部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32839] = {title = "熊與夫人", objective = "購買熊與夫人的挑戰卡然後在鬥陣俱樂部向他們挑戰並且擊敗他們。", description = "你贏得的這個挑戰卡屬於一對特殊的人物。我不確定還有其他的文字能更貼切地描述他們了。\n\n也許你應該買下挑戰卡自己瞧瞧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n華麗短衫滿溢的一袋錢幣"}
MultiLanguageQuestData['tw'][32840] = {title = "布姆布姆的引线", objective = "前往你所在阵营的搏击俱乐部，把布姆布姆的引线交给那里的某个人。", description = "在寇塔空毁灭之球周围满天飞扬的猢狲肉块和皮毛之间，你似乎抓到了一根短小的引线。\n\n引线由猢狲尾毛交织缠绕而成，味道很是难闻。\n\n但在引线的一端却贴有一个小小的纸质标签，上面写着这样一行字：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32841] = {title = "布姆布姆大师", objective = "购买布姆布姆大师的挑战卡牌，并在搏击俱乐部里向他发起挑战。", description = "你赢得的这张挑战卡牌，属于一只喜欢扔炸弹的猢狲，他叫布姆布姆大师。\n\n尽管猢狲生来就是炸药破坏力的狂热爱好者，可他们却很少能够学会如何正确地使用炸药，总是在使用过程中把自己炸伤。布姆布姆大师是个例外。\n\n祝你好运！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n轟炸襯衣巨大的一袋錢幣"}
MultiLanguageQuestData['tw'][32842] = {title = "利齿如剑", objective = "前往你所在阵营的搏击俱乐部，把无暇的利齿交给那里的某个人。", description = "这颗牙齿一端很尖，仿佛经过了石头的切削。显然是属于某只凶残野兽的。\n\n小心翼翼地端详过后，你发现有人在牙釉质里巧妙地刻下了这样一行小字：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32843] = {title = "锋齿", objective = "购买锋齿的挑战卡牌，并在搏击俱乐部里向他发起挑战。", description = "你今天赢得的挑战卡牌属于南海最危险的生物之一：锋齿。只要被他的利齿咬到一口，你就会变得血肉模糊、内脏横流。\n\n祝你玩得开心！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鯊皮外套超巨大的一袋錢幣"}
MultiLanguageQuestData['tw'][32844] = {title = "软泥的秘密", objective = "前往你所在阵营的搏击俱乐部，把一瓶红色软泥交给那里的某个人。", description = "瓶中液体剧烈地旋转起泡，引得瓶子在你手中颤动起来。当你望向容器深处时，你觉得自己在一瞬间看见了一张活灵活现的愤怒面孔。\n\n瓶塞紧紧嵌在瓶口，在瓶塞边缘，有某位行家刻下的一行小字：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32845] = {title = "血泥怪", objective = "購買血泥怪的挑戰卡然後在鬥陣俱樂部向她挑戰並且擊敗她。", description = "你可能知道吞齧怪，我們鬥陣俱樂部第2階的挑戰者。你所贏得的是血泥怪的挑戰卡，它是吞齧怪的大姊，比吞齧怪更兇殘。\n\n<name>，你可別死啊，要是死了，也要給大家一點樂子瞧瞧!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n泥漿襯衣超巨大的一袋錢幣"}
MultiLanguageQuestData['tw'][32846] = {title = "改良的咀嚼装置", objective = "前往你所在阵营的搏击俱乐部，把改良的咀嚼装置交给那里的某个人。", description = "如果不是因为在这玩意上面胡乱地写有“改良的咀嚼装置”这几个字，你也许不会想到这竟是一个改良的咀嚼装置。\n\n在那破烂的标签底下，你看到一行更小的文字，用醒目的红色墨水书写得较为整洁：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32847] = {title = "机甲布鲁斯", objective = "购买机甲布鲁斯的挑战卡牌，并在搏击俱乐部里向他发起挑战。", description = "人人都知道布鲁斯。人人都爱布鲁斯！可结果呢，人人都杀死了布鲁斯。\n\n一位精通工程学的兽人猎人把这视作奇耻大辱，于是他找到了他的鳄鱼，给他草草武装了一下。\n\n你赢得的这张挑战卡牌，赋予了你与机甲布鲁斯决斗的权力。这注定是场血战。问题在于……你将成为猎手，还是猎物？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n布魯斯皮革套衫巨額的一袋錢幣"}
MultiLanguageQuestData['tw'][32848] = {title = "冰冻蛋壳", objective = "前往你所在阵营的搏击俱乐部，把冰冻蛋壳交给那里的某个人。", description = "一片蛋壳，有可能是企鹅蛋。蛋壳边缘覆有白霜，而且根据弯曲度来看，这枚蛋在完整时是相当巨大的。\n\n奇怪的是，在蛋壳内侧用翠绿色的墨水写有这样一行字：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32849] = {title = "帝皮和杜皮", objective = "购买帝皮和杜皮的挑战卡牌，并在搏击俱乐部里向他们发起挑战。", description = "搏击俱乐部的老手们都会记得那只名叫帝皮的企鹅。帝皮在搏击俱乐部里并不是战技最为卓绝的挑战者，但也决不是不堪一击的草包！\n\n其实仔细想想的话，它也确实有点草包……\n\n不论如何！你赢得的这张挑战卡牌将使你得以挑战帝皮和他的大块头哥哥杜皮。它们或许都是草包，但没准你就会死在它们其中一个或两个的手上。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n仿禮服襯衣超巨大的一袋錢幣"}
MultiLanguageQuestData['tw'][32850] = {title = "去年的型號", objective = "把布滿灰塵的機器人交給所屬陣營之鬥陣俱樂部裡的某個人。", description = "這個機器人的狀況很糟。它和布靈登4000型一樣設有數個鑲孔，上面可能曾經裝過寶石，但如今空空如也。\n\n機器人布滿灰塵的外殼上有個閃亮的小飾板，上面鑲著幾個字:\n\n交還鬥陣俱樂部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32851] = {title = "布林顿3000", objective = "购买布林顿3000的挑战卡牌，并在搏击俱乐部里向他发起挑战。", description = "布林顿系列一直销路不畅，直到4000型系列上市才得以改观。很少有人记得布林顿3000，可它确实凭借自身实力创造了真正的工程学奇迹！\n\n你解锁的这张挑战卡牌使你能够在搏击俱乐部中与布林顿3000对决。\n\n祝你好运！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n過季襯衣巨額的一袋錢幣"}
MultiLanguageQuestData['tw'][32852] = {title = "挖掘大師的破土刀", objective = "把挖掘大師的破土刀交給所屬陣營之鬥陣俱樂部裡的某個人。", description = "一個外表平凡無奇的鏟子。把手上刻了裝飾文字:「挖掘大師的破土刀」。\n\n不過，把手的另一面有個更小的標籤，寫著簡單的文字:\n\n交還鬥陣俱樂部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32853] = {title = "明格斯·迪格司", objective = "購買明格斯·迪格司的挑戰卡然後在鬥陣俱樂部向他挑戰並且擊敗他。", description = "你贏得了挑戰考古學家明格斯·迪格司的權利!\n\n我聽說明格斯不是很厲害...可是上頭的人讓他帶著自己挖到的寶物上競技場。那些東西才是你要小心的。\n\n準備好的時候就過來買他的卡片吧!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n挖掘專家的短袖衫巨型的一袋錢幣"}
MultiLanguageQuestData['tw'][32854] = {title = "陈旧的眼罩", objective = "前往你所在阵营的搏击俱乐部，把陈旧的眼罩交给那里的某个人。", description = "一块依据人类头型剪裁的布。这块布显得朴素简洁，只在最下边有个小标签，上面写着：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32855] = {title = "盲大俠", objective = "購買盲大俠的挑戰卡然後在鬥陣俱樂部向他挑戰並且擊敗他。", description = "你贏得的挑戰卡讓你可以和盲大俠對戰，他是個來自逝去年代的神秘戰士。他的刀法無人能敵，誰也贏不了他。\n\n好在他什麼都看不見。好好享受!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n盲目披肩巨型的一袋錢幣"}
MultiLanguageQuestData['tw'][32856] = {title = "用布包著的石頭", objective = "把用布包著的石頭交給所屬陣營之鬥陣俱樂部裡的某個人。", description = "這是個奇怪的物品組合。布把石頭整個包了起來，窒息般地緊緊包覆著它。那顆石頭跟布比起來顯得渺小無比。\n\n對著光看，布上頭有個清楚的浮水印以及一段文字:\n\n交還鬥陣俱樂部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32857] = {title = "剪刀石頭布", objective = "購買剪刀石頭布的挑戰卡然後在鬥陣俱樂部向她挑戰並且擊敗她。", description = "你解鎖的挑戰卡讓你可以挑戰剪刀石頭布，它是個來自不知名地方的奇特生物。\n\n小心點，聽說它會不少把戲。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紙製襯衣滿溢的一袋錢幣"}
MultiLanguageQuestData['tw'][32858] = {title = "迅猛龙皮拳击手套", objective = "前往你所在阵营的搏击俱乐部，把迅猛龙皮拳击手套交给那里的某个人。", description = "这副手套针脚粗糙，而且从气味判断，应该沾有爬行者的粘液。尽管如此，看上去仍然坚固耐用。\n\n令人不大出乎意料的是，在内侧边缝处有这样一行字：\n\n归还搏击俱乐部您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32859] = {title = "泰塔尔", objective = "购买泰塔尔的挑战卡牌，并在搏击俱乐部里向他发起挑战。", description = "你赢得了购买一张挑战卡牌的权力，这张卡牌属于一位名叫泰塔尔的巨魔。\n\n泰塔尔的战斗风格极为独特，且作为他与搏击俱乐部协议的一部分，你必须遵循他的规则：\n\n面对面徒手拳击。不得四处乱跑。\n\n三次击倒对手者获胜。\n\n祝你好运！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n如假包換的冠軍襯衣巨大的一袋錢幣"}
