MultiLanguageQuestData['tw'][32974] = {title = "羅洛的謎語", objective = "解開這道謎題。", description = "<這張羊皮紙非常古老。紙上染著歲月的痕跡，寫著以下的文字:>\n\n時光島上四高人\n身材渾圓而強壯\n兄弟當中最矮小\n即是吾道之方向。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32975] = {title = "羅洛的謎語", objective = "解開這道謎題。", description = "<泥土裡埋著另一份髒污的羊皮紙片。>\n\n某處希望高昂揚\n從其腳下轉朝南\n穿越古門至彼方\n雙石之後吾等待。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32976] = {title = "羅洛的謎語", objective = "解開這道謎題。", description = "最終一步藏寶喚\n落水之上其所向\n瞭望之高陰影下\n天空之外無路往。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n永恆鎧甲儲藏箱永恆鎖甲儲藏箱永恆皮甲儲藏箱永恆布甲儲藏箱\n\n您還會收到：\n\n永恆鎧甲儲藏箱永恆鎖甲儲藏箱永恆皮甲儲藏箱永恆布甲儲藏箱恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][32979] = {title = "要塞戰役：先知之石", objective = "前往霜火峰的先知之石找到德拉卡和德雷克塔爾。", description = "德拉卡和德雷克塔爾已經動身前往先知之石。那裡既是聖地，也是險地。不過德拉卡堅持德雷克塔爾必須重建他與元素的聯繫。\n\n我可以感覺到，這片土地的靈魂騷動不安。情況不太對勁，我認為必須傾全力援助他們。\n\n拜託了，$p，找到他們，助他們一臂之力。我十分擔心他們的安危。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32980] = {title = "元素吞噬者", objective = "在儀式進行期間保護德雷克塔爾。", description = "德雷克塔爾的儀式已經開始了，儀式的威力太強大，肯定會引起這裡的戈倫注意。元素魔法對那些野獸而言，就像屍體之於蒼蠅一樣誘人。\n\n我很快就會疲於應付。你願意的話就幫忙我們，不過一定要讓德雷克塔爾完成儀式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32981] = {title = "僅遵勝者", objective = "收集天詠者史崔格的圖騰。", description = "我是古羅巡者洛卡什，我只會站在勝利的一方。\n\n我聽說過一些你的事蹟，指揮官，也看過一些你和你的部隊留下的屍體。\n\n我現在這個氏族讓我有點煩了，他們膽怯又軟弱，而且不會是贏家。\n\n我給你一個挑戰，進入北邊的巨獸之殞，殺死天詠者史崔格。取得她的圖騰作為戰利品，我就會奉你為我的新酋長。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "凜冽寒風之鍊滾燙火焰頸飾流動大地頸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][32983] = {title = "在巨人的陰影下", objective = "解救炎火和燃火。", description = "戈倫和麥奈隆巨人正在毀滅元素之靈，就像熔煉鋼鐵一樣在熔煉它們的元素之魂。\n\n指揮官，帶上我的圖騰前往東邊的麥奈洛克。找到它們，解救它們。\n\n德拉卡和我將會前往霜火坡。完事後，在那裡跟我們會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32984] = {title = "上坡", objective = "將德雷克塔爾帶到霜火之靈艾索洛圖斯面前。", description = "我聽到怒靈的聲音從坡頂傳來。上吧，一起爬上這座階梯。\n\n保持警覺。薩滿的氣味很可能會把這個區域的戈倫吸引過來。\n\n如果我們走散了，就回到階梯最底部重新集結。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32985] = {title = "霜火之怒", objective = "擊敗克隆。", description = "在我開始執行儀式解救艾索洛圖斯的時候，一定會把克隆引來。\n\n通常需要一大群驍勇的戰士才能擊敗一個麥奈隆巨人，但現在我們只有三個人。\n\n注意我在戰場上放出的火焰圖騰。我會努力運用艾索洛圖斯的力量來協助我們。靠近圖騰，與怒靈合而為一。\n\n利用怒靈的力量殺死克隆！不勝即亡！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n火怒之靈圖騰"}
MultiLanguageQuestData['tw'][32989] = {title = "固守南方", objective = "和石牙哨站的羅克拉交談。", description = "雷霆王氏族的大軍越過沃格爾的時候，將我們位於東南方的哨站團團包圍。\n\n我已經派出支援部隊固守哨站，並且朝東邊的格羅姆加進攻。我們會把雷霆王全面趕出我們的土地、一路追殺，把他們趕回那堆他們稱之為家園的惡臭屍骸中。\n\n羅克拉，德拉卡的妹妹，已經和其他的志願者前往掃蕩石牙哨站的敵人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32990] = {title = "堅持不懈", objective = "和石牙哨站的卡格‧血怒交談。", description = "敵人的攻勢已經潰不成軍。他們低估了石牙哨站的韌性，而且來自劍刃堡壘的我方援軍逮到機會，將他們打個措手不及。\n\n一旦我們收拾好此地的殘局，就可以集結剩餘戰力，準備朝格羅姆加進軍。\n\n石牙哨站的隊長，卡格‧血怒，現在應該出來跟我們碰面了。你能不能叫他出來？\n\n告訴他羅克拉正在等。他很清楚我有多討厭等人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32991] = {title = "深入焚骨坑地", objective = "搜尋焚骨坑地，找出失蹤的霜狼獸人。", description = "雷霆王的人把俘虜帶進了焚骨坑地？\n\n那我們還在等什麼？我們得追上去！\n\n你負責找出失蹤的村民，艾薩和我負責追查卡格的下落。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32992] = {title = "移動的目標", objective = "前往冰風雪原，和羅克拉會合。", description = "擄走卡格的人往東邊去了，大概是打算夾著尾巴撤回格羅姆加！\n\n他們以為跑得比我快，但是沒有人能跑得過艾薩。我們可以在冰風雪原追上他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32993] = {title = "我們的牽絆之力", objective = "到格羅姆加找卡格‧血怒。", description = "艾薩已逝，但我們之間的連繫不會因為死亡而中斷。就連現在，她的靈魂仍然在催促我前往格羅姆加。\n\n鐵狼聲稱我們的情感讓我們脆弱…愛成為我們的弱點。\n\n他錯了。\n\n卡格是我的力量，我也是他的力量。我會將他從枷鎖中解放，只要我們合力，就可以向雷霆王氏族展示我們的牽絆是多麼強大。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "羅克拉之怒艾薩之牙您能選擇下列奬勵中的一個：\n\n卡格的狩獵號角\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][32994] = {title = "攻其不備", objective = "用黑石火藥粉摧毀5座格羅姆加的鋼鐵部落大砲。", description = "如果我們現在就走，我的氏族對格羅姆加的最後一擊就會一敗塗地。\n\n雖然我們的戰士在近身肉搏時無人能敵，但雷霆王取得了新的遠程武器。我們的部隊可能在跨越冰風雪原的時候就被盡數殲滅。\n\n但我們現在就站在這裡。我們可以趕在這些武器開火之前先攻佔下來。\n\n黑石獸人在南方的工坊協助我們的敵人鑄造這些「大砲」。如果能使用他們的工具來破壞這些武器，就可以讓格羅姆加的門戶洞開，任由霜狼進攻。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][32995] = {title = "染血的卷轴", objective = "将武器大师的卷轴带到奥格瑞玛的搏击竞技场交给高洛斯·碎地者。", description = "这个卷轴看起来十分古老。在厚厚的灰尘和斑斑血迹下面，你大致能读出几段关于“精通武器”的描述。\n\n这可能会对你的训练大有帮助。\n\n也许在某个地方会有一位老练的战士，他能告诉你与这个卷轴有关的更多细节。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
