MultiLanguageQuestData['tw'][33070] = {title = "想想孩子們！", objective = "拯救拉斯塔克、雅莉安娜和哈肯姆。", description = "當影月氏族的人攻擊艾博谷地時，一切都陷入了混亂。\n\n我們有許多人逃了出來，還有三個孩子失去蹤影。\n\n我相信他們還在村子裡。\n\n請救救他們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33072] = {title = "暮光之中", objective = "到暮光林地與預言者費倫交談。", description = "我族人的安危才是第一優先。\n\n耐祖奧應該已經帶著囚犯前往夏茲高，他那個位於西南方的要塞。\n\n我並不想對他發動攻擊，但這是他自找的。\n\n到暮光林地找我，<name>。然後，我們要盡可能地救出囚犯。", progress = nil, completion = "謝謝你過來，&lt;name&gt;。還有很多事情要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33074] = {title = "烈焰的记忆", objective = "在火焰之环上使用闪烁的余烬。", description = "<这块黑曜石碎片摸上去很烫，但奇怪的是，拿在手里却完全没有被灼伤的危险。>\n\n它的表面上刻着一幅画——一块长方形的石头，正中间被穿了个洞，周围有一圈火焰。\n\n在北边的旷野里恰好有块这样的石头。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33075] = {title = "英雄式的歡迎", objective = "到安伯瑞村與薩瑪菈交談。", description = "預言者費倫要我帶你在影月谷四處走走。\n\n我們會先到安伯瑞村，我的姐姐薩瑪菈正在那裡等著我們。自從鋼鐵部落把我抓到塔南以後，我就沒看過她了。\n\n安伯瑞村是卡拉伯爾神廟與撒塔斯之間的一個貿易村莊。\n\n沿著路向東走就是安伯瑞村了。我會跟你一起過去，朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33076] = {title = "明晰藥劑", objective = "收集6份沼澤螢光蟲鱗粉、3顆腫脹的心臟，以及1朵原始星辰百合。", description = "我看到未來數不清的瞬間，在一片混沌的模糊中湧動。\n\n集中我的精力，或許可以看到真正的結果，也就是最可能成為歷史的未來。\n\n我需要一枚先知石來集中我的力量，還有一瓶特殊藥劑來穩定我的心志。\n\n想要製造出藥劑，我需要這些材料：河畔的沼澤螢光蟲鱗粉、巨大多頭怪仍在跳動的心臟，還有一朵罕見的星辰百合。\n\n在準備好這些材料之後，到月柳峰和我碰面。", progress = "嗯？", completion = "我果然沒看錯人，年輕的&lt;class&gt;。\n\n對我的大部分學生而言，這工作太過棘手，但你卻能輕易完成。", rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][33077] = {title = "祖傳藥方", objective = "收集6瓶蝦蟆油。", description = "噢，真是活力充沛的年輕<小夥子/小姑娘>！步伐如此輕快，雙眼洋溢神采。\n\n等你到了我這把年紀，就會全身疼痛不已。\n\n幸好，我知道一個藥方，可以讓關節不再酸痛。只需要從沼澤裡的大肚蟾蜍皮膚表面取得一些黏液就可以了。\n\n你能不能行行好，幫老太婆一個忙？", progress = "親愛的，身體狀況走下坡就回不來了。", completion = "噢，謝謝你，孩子，謝謝，謝謝。\n\n沼澤的夜晚很冷。讓老太婆痠痛的老骨頭舒服一點，這可是意義重大。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33078] = {title = "致盲之暗", objective = "到細語原野拓下東、西、南、北部族之石上碑文。", description = "即使研究了好幾年，我對影月氏族還是有很多不了解的地方。\n\n在西南邊有數塊石碑，上面記載了獸人的歷史。\n\n我無法接近那個石碑，仔細看看上面的文字，但或許你有辦法。\n\n如果你能用石灰粉拓下碑文，我會給你豐厚的獎賞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33079] = {title = "伪装大师", objective = "与吉尼·姜唇交谈来制作一套影月兽人伪装服。", description = "有布料皮革在手，我们终于可以制作一套适合执行潜入任务的伪装服了。\n\n去找吉尼·姜唇谈一谈。她在……呃……服装设计方面很是在行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33080] = {title = "潛入敵陣", objective = "到暮光林地和席瑞妮交談以取得獸人幻影偽裝，然後到夏茲高的關鍵地點安置炸藥。\n\n如果喪失偽裝效果，就使用席瑞妮的幻影護符，重新披上獸人外觀。", description = "伊芮爾帶著幾個我手下的遊俠去影月村找那些俘虜。\n\n他們做的事非常危險，所以我需要你來進行這個後備任務。\n\n席瑞妮精通幻象法術，能讓你安全地混進夏茲高。與她交談，她會幫你進行偽裝。\n\n接下來，在軍需官補給站、主屋以及儀式祭壇中放置炸藥。\n\n如果出了問題，就直接引爆它們，分散注意力。", progress = nil, completion = "你辦到了，&lt;name&gt;！真高興能見到你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33081] = {title = "逃離夏茲高", objective = "協助伊芮爾逃出夏茲高。", description = "我失敗了，<name>…\n\n我們小隊被巡邏兵逮到了。我們雖然奮勇戰鬥，但警報已經響起。遊俠要我先躲起來，然後才讓敵人把他們抓走。\n\n他們在我的指揮之下，還獻出了生命…這一切是為了什麼？我…我不知道該怎麼做，<name>。\n\n我們要離開這裡，可是要怎麼逃？", progress = nil, completion = "要是沒有你，我絕對辦不到的，&lt;name&gt;。你的鼓勵打開了心中的門扉，解放了我過去從未體驗的東西。\n\n無論你怎麼稱呼這種感受，是決心、信念，或是信心，我相信一定會常在我心，&lt;class&gt;。", rewards = "遊俠初學者脛甲卡拉伯爾爭鬥者長靴卡拉伯爾初學者戰靴卡拉伯爾賢者足靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][33082] = {title = "先祖的記憶", objective = "在流放者高地底下的洞穴裡找到先祖圖騰。", description = "我相信你應該知道你所殺死的生命需要付出的代價。\n\n在我幫你尋找耐祖奧之前，你必須先了解為什麼他會加入鋼鐵部落。\n\n在這個村落下面有個山洞，裡面有個我們稱之為先祖圖騰的神器。上面雕刻了每一個影月氏族成立以來的成員名字。\n\n洞穴的入口就在正南方。我會在那裡跟你碰面。", progress = nil, completion = "我們會建立新的傳統。我的族人將會…脫胎換骨。", rewards = "卡拉伯爾榮譽守衛腿甲遊俠初學者護腿卡拉伯爾爭鬥者腿甲卡拉伯爾賢者護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][33083] = {title = "主動出擊", objective = "殺死15個影月黑暗法師或影月虛無之爪。", description = "我們無法進入這道門，但是你可以，<class>。\n\n你的任務非常重要，影月氏族一見到你就會痛下殺手。不要遲疑，馬上還手。", progress = nil, completion = "影月氏族並不是容易對付的敵人。你的戰技真的是無與倫比。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33084] = {title = "大搬運", objective = "收集1000份伊萊克生肉排。", description = "嗨，指揮官，能夠在外面碰到你還真不尋常！\n\n要塞裡面已經有不少人飢腸轆轆，而且每天都有更多人湧入。\n\n我們需要大量的肉才能讓每個人都笑顏逐開。\n\n你能不能幫個忙？如果多些幫手，工作起來會更快。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33085] = {title = "从星辰坠落", objective = "采集一朵新鲜的烁星花。", description = "最后一种原料需要用到只在暗夜沼泽深处生长的罕见花朵。\n\n这种花只依赖星光的照耀，一旦坠入暗影就会死亡。\n\n如果你能找到这种花的话，请把它带给我。只有它的精华才能帮我获得我需要的澄澈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33086] = {title = "Tracking Quest: The Root of Darkness - Stone 1", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33087] = {title = "回旅店与我会面", objective = "到雾纱栈道迷雾酒肆的楼上与拉希奥会面。", description = "我敢肯定，你此刻已经迫不及待地想要试试自己的新披风了。那就让它发挥作用吧。\n\n回旅馆里与我碰面！一项新发现引起了我的注意，我们可以对其善加利用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33088] = {title = "永恒的发现", objective = "前往位于翡翠林东南部的永恒岛，并与拉希奥交谈。", description = "潘达利亚。正当我以为自己已经洞悉了这片大陆上的一切神秘时，我却有了新的发现。\n\n那地方叫做“永恒岛”。它曾经深藏在迷雾之中，仿佛听凭自己的意志忽而出现，忽而消失。我听说时间在那里毫无意义，既无日出，也无日落。\n\n我们正好可以利用这一怪象，<name>！如果我能用时间锁住你的斗篷，它所蕴含的力量将会是……无边无际的。\n\n我们的前路非常清晰。飞去翡翠林的东南部，到永恒岛上与我会面！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
