MultiLanguageQuestData['tw'][33098] = {title = "永恒岛的秘密", objective = "从永恒岛的怪物身上和事件中收集5000枚永恒铸币。", description = "在这座岛屿上铸有一种独特的货币，叫做“永恒铸币”。它们可以免疫岛上的时间扭曲之力……我想要查明原因。\n\n替我找些铸币来！深入这片被遗忘天堂的丛林间吧。不惜一切代价消灭那些潜伏在这片永恒之地的神秘敌人，探索隐藏的宝藏，找寻被遗忘的财宝。我等着你回来！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33100] = {title = "帝王之道", objective = "击败玉珑、赤精、雪怒和砮皂这四位潘达利亚的至尊天神。", description = "不久前，潘达利亚的至尊天神给予了你一项挑战——而你取得了胜利。\n\n但你能在战斗中打败他们吗？他们在考验潘达利亚所有英雄的胆魄。\n\n这项挑战并非不可能完成，可你需要听取熊猫人末代皇帝的建议，并凭借坚定的内在力量应对这项挑战。你还需要集结一小支军队，去找些你信任的朋友来吧。\n\n在天神庭院击败四位天神，我们的旅途就差不多要结束了……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33104] = {title = "熊貓人的傳奇", objective = "到恆春谷的知識之座找怒西昂。", description = "朋友，我在這個永恆之地學到了許多。在聖獸天尊的睿智以及這些永恆神器的奇特力量之間，我現在知道要如何利用自己強大的力量來安全地強化你的披風。\n\n我需要一個神聖的地方來完成我最後的咒語。動作快!到恆春谷裡魔古山宮的知識之座內和我碰頭。\n\n你的傳奇就要在今天展開了!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n黑龍軍團的永恆精華"}
MultiLanguageQuestData['tw'][33105] = {title = "黑龍王子的判決", objective = "完成圍攻奧格瑪並擊敗卡爾洛斯‧地獄吼。", description = "現在，開始我計畫的最終階段吧。是時候完成你偉大的使命了。\n\n運用你得到的新力量，該讓這場戰爭劃下句點了。消滅卡爾洛斯‧地獄吼。你的同胞要求你這麼做，今後的世代也會歌頌你為光榮新世界的先鋒，這個世界將由我們攜手建立。\n\n我沒有什麼可獎勵你的。我已經盡我所能確保你能成功。接下來靠你自己了。\n\n結束地獄吼的統治。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33107] = {title = "預感壞，結局更壞", objective = "打倒林大顧之魂。", description = "<當你打開卷軸的時候，你發現自己最害怕的事情成真了:煞能腐化了林家食譜。>\n\n<你如今唯一的選擇就是把釋出的煞能打敗，希望還救得回這份卷軸。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33108] = {title = "任务：中毒的兔子", objective = "焚烧5只中毒的兔子", description = "这里有许多小兔子感染了剧毒。\n\n这也许听上去很残忍，但是焚烧那些小兔子的尸体是阻止感染进一步扩散的唯一办法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33109] = {title = "短缺奖励", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33111] = {title = "懸賞：扭曲的古樹", objective = "從扭曲的古樹上取得腐化樹枝。", description = "詛咒森林裡那些扭曲的古樹已經被惡魔魔法腐化。既然它們需要被解決，我們也許可以善用它們提供的資源。不要浪費，就不會匱乏。\n\n小心：這些林地裡的巨獸可不好對付。召集你的好友們一起來對付這些扭曲古樹吧。\n\n─巴洛斯‧艾力克斯頓您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][33112] = {title = "不祥之兆", objective = "逼迫全知之眼。", description = "現在月牙的女祭司已經造出祝福之水，該是處理那個惡魔的時候了。\n\n拿著水和伊露恩的聖典。\n\n透過這兩者的力量，你就能逼迫惡魔向我們展現古爾瓦的獸人打算做什麼。", progress = "如果我們想知道古爾瓦發生了什麼事，就要讓這個惡魔接受試煉。", completion = "古爾丹在那裡！快，我們得活捉他！", rewards = "盲目魔眼之戒魔化玷污之戒沐聖魔縛之戒您會收到：\n\n"}
MultiLanguageQuestData['tw'][33113] = {title = "影月之井", objective = "取得一個月岩石塊。", description = "大法師請我準備好這座月井。一旦完工之後，我就可以將裡面的水聖化，用來對抗惡魔。\n\n現在只剩一件事要做。\n\n這附近有塊德拉諾的月之碎塊，掉落在森林那頭的湖泊中。想要奉獻給伊露恩的月井，這再適合不過了。\n\n你能幫我把它帶回來嗎，<name>？", progress = "有了月岩石塊，我就可以完成月井的奉獻儀式。", completion = "多謝你，&lt;name&gt;。月神會十分高興。\n\n我現在應該去準備月井之水，讓大法師完成他的計畫。\n\n不過在這之前，不知道你能不能再幫我一個忙。看守者帶回了一個令人擔心，與森林生物有關的消息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33114] = {title = "鑄造靈魂陷阱", objective = "鑄造古爾丹的靈魂陷阱。", description = "克羅斯尼司的熾炎之心就在這個熔爐裡。我們取得了靈魂裂片。\n\n現在只要生起爐火，把這些邪惡事物熔鑄起來，就可以造出一個捕捉古爾丹的陷阱。", progress = "鑄好靈魂裂片之後，我們就可以困住古爾丹，並且終止暗影議會在德拉諾圖謀的一切。", completion = "你已經鑄好靈魂陷阱，不能再浪費時間了，&lt;name&gt;。\n\n我們一定要抓住古爾丹。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33115] = {title = "蔽形石", objective = "摧毀中央、北方和南方的蔽形石。", description = "很久以前，影月氏族的薩滿在森林中豎立了三枚石塊。他們在這些地點進行神聖儀式，祝福野獸和樹木。\n\n現在，不知何人在這些石塊上面施放了邪惡魔法。就是這種腐化正籠罩著古爾瓦。\n\n在我們有辦法利用抓來的惡魔來安全地窺視暗影議會在村中的舉動之前，我們必須先處理這些石塊。", progress = nil, completion = "我們現在已經移除了森林的屏蔽，可以好好利用惡魔了。\n\n我們會說服他把目光轉向古爾瓦，向我們展示暗影議會的計畫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33116] = {title = "捕捉暗影", objective = "對古爾丹使用靈魂陷阱。", description = "古爾丹就在暗影高地，位於西邊的山丘上。不過，你的動作要快，<name>。我們得知他正打算前往塔拉多爾和霜火峰。\n\n靈魂陷阱的使用方法十分直接，只要瞄準、發射，就可以抓住古爾丹。水晶會負責接下來的工作。\n\n抓住他之後，我會在墜星哨站等你。\n\n祝你好運。", progress = nil, completion = "雖然這場不幸並不令人意外，但至少我們擊敗了一個暗影議會的重要成員。\n\n我們還有一絲希望，&lt;name&gt;。目前已經掌握了暗影議會的目的和動向。\n\n我們準備前往塔拉多爾，同心協力除掉泰朗戈爾，終結他染指奧齊頓的計畫。\n\n你聽到什麼了嗎？", rewards = "腐生披氅剝皮披風魔血漿製披風您會收到：\n\n"}
