MultiLanguageQuestData['tw'][33146] = {title = "湯麵時刻", objective = "在半丘拉麵攤加入並完成拉麵攤的佇列。", description = "你好啊，<name>還想擺拉麵攤嗎?\n\n如果你想再擺一輪攤子的話跟我說，我會把東西全部準備好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][33147] = {title = "亞煞拉懼的臨終之息", objective = "在圍攻奧格瑪中與博學行者阿洲交談。", description = "漆黑的揮發物質髒污了地面。這就是上古之神亞煞拉懼僅存的殘骸。", progress = nil, completion = "你明白嗎?即使是現在，它仍在消逝。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33149] = {title = "救援行动", objective = "在迦尔玛克沙石场外面找到塞林·暗砧。嗨，<name>，你就是我想见到的<race>。我刚刚收到来自塞林的求救信号。\n\n他和罗姆尔不久前出发去侦察另一块德莱尼水晶了，可听起来他们像是卷进了什么大麻烦。\n\n根据我对塞林的了解，他肯定需要人帮忙。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "嗨，<name>，你就是我想见到的<race>。我刚刚收到来自塞林的求救信号。\n\n他和罗姆尔不久前出发去侦察另一块德莱尼水晶了，可听起来他们像是卷进了什么大麻烦。\n\n根据我对塞林的了解，他肯定需要人帮忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33150] = {title = "以暴制暴", objective = "击败莫克里克·黑指、机械师卢卡和加尔·碎钢。", description = "钢铁部落毫无荣誉感可言。\n\n他们的首领在我们替他们干活时还往我们身上吐口水。\n\n我有许多兄弟姐妹都死在了他们手上。\n\n是时候送这群野蛮人进坟墓了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遊俠初學者頭盔卡拉伯爾榮譽守衛頭盔卡拉伯爾賢者軟帽卡拉伯爾爭鬥者兜帽您會收到：\n\n"}
