MultiLanguageQuestData['tw'][33234] = {title = "肥美的鶴腿", objective = "你帶什麼來了?", description = nil, progress = "你帶什麼來了?", completion = "哇，這真的好肥美!想想我可以用它煮出來的湯!來，我要給你一些永恆硬幣來交換它。", rewards = "您會收到：\n\n永恆硬幣"}
MultiLanguageQuestData['tw'][33235] = {title = "巨型龜肉", objective = "嗯，那個聞起來...很有意思...", description = nil, progress = "嗯，那個聞起來...很有意思...", completion = "這個肉...好有彈性!嗯，很好，也許可以加點醬油跟調味油...來，這些硬幣給你當報酬!", rewards = "您會收到：\n\n永恆硬幣"}
