MultiLanguageQuestData['tw'][33253] = {title = "保卫卡拉波", objective = "与[FLIGHT MASTER]谈一谈，然后到卡拉波的后门处向阿卡玛回报。前往卡拉波吧，你这<race><class>y小不点儿。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "前往卡拉波吧，你这<race><class>y小不点儿。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33255] = {title = "正義之師", objective = "護送要塞部隊前往卡拉伯爾神廟，殺死所有光明之路上的獸人。", description = "鋼鐵部落已經攻下卡拉伯爾。如果我們再不行動，我們就會失去這座城市。\n\n阿卡瑪主教和我們的最後一支部隊都被困在城裡，但你要塞裡的兵力都還在神殿外等候你的指令。\n\n跟我一起走吧。我們會在戰場上和你的部隊會合。有了那魯的幫助，我們將進行最後一次城市奪回戰！", progress = nil, completion = "就是現在！讓這些獸人全下地獄吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33256] = {title = "卡拉伯爾防衛戰", objective = "摧毀鋼鐵部落在卡拉伯爾的勢力。", description = "從鋼鐵部落手中保衛卡拉伯爾。\n\n『燃燒者』阿諾克在北方盡頭的庭院，負責看守卡拉伯爾後面的港口，那就是鋼鐵部落主力軍隊的待命地點。\n\n解決他之後，我們就得面對鋼鐵部落的領導者，指揮官沃爾卡。", progress = nil, completion = "我們成功了，&lt;name&gt;。要是沒有你的英勇表現，卡拉伯爾神廟一定會落入鋼鐵部落手裡。\n\n預言者費倫一定會以我們為傲。", rewards = "遊俠初學者頭盔卡拉伯爾榮譽守衛頭盔卡拉伯爾賢者軟帽卡拉伯爾爭鬥者兜帽您會收到：\n\n"}
