MultiLanguageQuestData['tw'][33322] = {title = "Tracking Quest - Daily - Watcher Osu", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33323] = {title = "Finale - Tracking Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33327] = {title = "要的就是它", objective = "取回莫克里克的破烂的日志、卢卡的尘封的日记和加尔的保存完好的日记。", description = "我注意到指挥官们随身带着日记本。我有种预感，要是能拿到那些日记本的话，肯定能从里面找到重要信息。\n\n日记本的主人总是把它们带在身上，所以事情恐怕不太好办……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33330] = {title = "任务：被困的小动物", objective = nil, description = "释放被肃霜食人魔囚禁的霜狼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33331] = {title = "被捕獲的小動物", objective = "在幽蔭林地救出被捕獲的小動物。", description = "這隻可憐的小動物即將成為魔花人的食物。但是要釋放牠並非難事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33332] = {title = "來自過去的提示", objective = "向織霧者小艾購買一本老舊的日記。", description = "這個地方有很多尚待研究之處，但它的秘密可不會輕易揭曉。\n\n你上次向我提到的一件事讓我很好奇。我沒記錯的話，這個織霧者小艾帶著一本老舊的日記，對嗎?這或許能解答我們許多的問題，也可能發掘出更多的問題。我想這都得看紀錄這個反常之地的探索家有多勤奮了。\n\n將老舊的日記帶回來給我。我們要一起探索其中的奧秘。", progress = "啊，你回來了。拿到日記了嗎?", completion = "啊，你拿到了!太好了!\n\n我大致看了一眼，這和我的假設似乎相去不遠。雖然書頁破損又泡過水，大部分的文字還能辨識。看來我們的朋友，探險者哈林頓，鉅細靡遺地記錄了他在島上旅行所見的各種生物與寶藏。\n\n好啦，你只想呆站在這裡嗎?這本書簡直是集神秘之大全，而我們才剛開始接觸它的表面而已!冒險等待著我們!", rewards = "您會收到：\n\n老舊的日記恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33333] = {title = "永恆寶藏", objective = "在永恆之島上找出一個隱藏的寶藏。", description = "日記顯示島上各地有豐富的寶藏，有的藏在伸手難及的地方，有的藏在陰暗的洞穴和深坑中。在這裡埋藏了許多世代的，會是什麼東西呢?\n\n或許更重要的是，是誰藏的呢?\n\n找出島上的這些寶藏，然後帶著你的發現回來找我。不過你要小心，發亮的東西並非都是寶物，反之亦然。有時候，最平凡的樹洞反而是最適合隱藏寶物的地方。", progress = nil, completion = "我很高興你的努力有所收穫，不過我們揭露謎團的進度仍然停滯不前。放寬心情，還有許多寶藏四散在這座島嶼上，殷切期待著你的探索技藝以及戰鬥本領。\n\n喔，還有最後一件事，年輕的冒險家啊，別忘了偶而抬頭看看天空。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33334] = {title = "因強而生", objective = "在永恆之島上擊敗5隻稀有或稀有精英生物。", description = "一座消失在時光中的島嶼，如今又生氣勃勃地回來了！\n\n這座島嶼去了哪裡？它是跳躍到了未來的時間，還是在扭曲虛空的黑暗深處凋萎？\n\n有件事是肯定的：居住在這裡的生物絕不像外表看來那麼簡單。我感覺到牠們體內藏著一股由亙古所鑄煉出的力量。找出這些族類之中強健雄壯的精英，然後擊敗5隻這樣的生物。\n\n我們也許能從牠們的屍體找出想要的線索。", progress = nil, completion = "這個故事很有趣，結合了戰鬥與英勇之舉，不過除了證明了你是個厲害的冒險者，我們從你的行動中恐怕沒有學到太多東西。看來我們在這個故事的每個轉折都是碰壁難行。時光真是捉摸不定。\n\n在日落之前，你也許會想花點時間在這裡磨練你的技巧。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33335] = {title = "末代皇帝", objective = "和紹昊大帝交談。", description = "據我所知，這裡曾經是某種競賽的場地，來自潘達利亞各地的戰士會追隨他們末代皇帝紹昊的腳步，展現自己的武藝。\n\n我聽說當紹昊完成他的試煉時，他和大地合而為一，並且將潘達利亞深藏於濃霧之中，就連我們穿越時光之流的能力都無法貫透。\n\n這聽起來很有意思，也許你該和他談談?", progress = nil, completion = "出於傲慢，我曾試圖將潘達利亞隱藏起來，如今我又發現自己從這片大地學到了寶貴的一課。我很高興能和我的同胞分享我的故事，而且希望他們能和我一樣再度從我的錯誤中汲取教訓。也許你也可以從潘達利亞的故事中學到一些東西。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33336] = {title = "時光精華", objective = "從永恆之島的生物身上取得一個紀元之石。", description = "我該向你透露我來這座島嶼的目的了。\n\n青銅龍軍團的力量已大不如前，我們現在只能勉強穿透時間、匆忙一瞥。這令人...倍感挫折。\n\n可是我們並非全然束手無策。我手中握有時光之視，這是我自創的神器。這座島嶼上的生物已經穿越時光，而且身上可能帶有時光的精華。有了這些精華，我們就能填補沙漏，讓我們再度於時光之道打開一扇窗。", progress = "你有找到什麼嗎?", completion = "紀元之石相當稀有。這些結晶化的時光精華需要迅速穿越漫長的年代才能成形。它們出現在這裡，表示這座島嶼可能不是只存在於一個時間，而是在不同的時光之道間快速轉移。\n\n然而，現在這已經不重要了。時光中還有更重要的時刻需要我們的注意。給我一點時間研磨紀元之石，把它們加進時光之視沙漏裡。", rewards = "這個任務線能解鎖：\n\n每日任務：永恆之島\n\n您還會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33337] = {title = "時光之視的秘密", objective = "在圍攻奧格瑪使用時光之視。", description = "看看時光之視的反應!真令人難以置信!直到現在，它還顯示著環繞著我們的時間之道的暗影。雖然不是時光沙漏真正的沙子，但這些磨得很仔細的紀元之石碎屑，顯然自有神奇的力量。我們的首要任務就是用它們在時光之視上劃下刻度。\n\n帶著時光之視到圍攻奧格瑪的地點去，那是創造歷史的地點。到了那裡以後，翻轉沙漏，看看會發生什麼事。", progress = nil, completion = "真有意思。我得做一些額外的修改，或許放一種更合適的催化劑。謝謝你做了這次實驗，相信你沒有受到什麼不良影響吧?你若想做些任務，我可能很快又會需要你的幫忙了。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33338] = {title = "沙漏充能", objective = "從永恆之島的生物身上收集紀元之石。", description = "這個沙漏能讓我們一窺時光之流，我們曾在其中穿梭自如，彷彿行走於熟悉的舊徑。\n\n收集更多的紀元之石，我們才能繼續使用沙漏的力量，深入時光之道的奧秘。\n\n未來就仰仗它了。", progress = "紀元之石是稀有而結晶化的時光精華。", completion = "給我一點時間研磨紀元之石，把它們加進沙漏裡，我們就能看看新的事件會如何發展。\n\n這真的很方便，我能清楚掌握特定的時刻，而非漫長的連續事件。\n\n時光之道向我透露，我們在不久的將來會經常需要它的力量。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33340] = {title = "永恆營養品", objective = "在永恆之島食用成熟的爽脆果、被沙覆蓋的蛋、充能水晶、大片烤犛牛、燒烤種子或火罌粟。", description = "正如你所預料，這座島上的動植物很不尋常。然而，並非所有的解釋都是神秘難辨。有時我們得傾聽大地，傾聽我們身旁世界的故事。你曾經想過，島上的生物只憑著你腳下大地的滋養，就能長成如此的體型？\n\n你可以在島上找到大量富含營養的來源：成熟的果實、蛋、肉、花朵、核果，就連岩石都能提供養份。食用它們，發現大地的力量。", progress = nil, completion = "這座島嶼提供了豐富的滋養與解答。你只要環顧身邊，就能找到想要的東西。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33341] = {title = "天尊聖壇", objective = "找到一座有效用的時佚聖壇，然後向聖獸天尊祈求祝福。", description = "許多年前，我的同胞會前來這裡朝聖。在這裡，他們會傾聽聖獸天尊的話語，然後冥想數日。他們會在冥想中發現困擾自己心靈的恐懼、憤怒、絕望、疑懼與暴戾。\n\n在他們面前的，是一條啟蒙之道。每個人的道路都不相同，起點卻都從睿智開始。\n\n像他們一樣在島上旅行，找出其中一座失落的天尊聖壇。", progress = nil, completion = "你體驗了聖獸天尊的力量與睿智。現在，讓它流過你的身體，永遠停留在你的心中。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33342] = {title = "撲滅火焰", objective = "打敗永恆之島的歐朵揚古，直到紹昊的聲望值達至尊敬。", description = "熊貓人曾經和歐朵揚古和平共處。當島嶼突然消失時，歐朵揚古面臨滅亡的命運。在絕望之下，大薩滿向火焰之王求助，並獲得了回應。這名大薩滿的名字就是歐朵斯。如今，他成了憤怒而暴戾的生物。雖然他的同胞獲救了，但他卻受到永世熔燒之苦。\n\n和平已蕩然無存。歐朵揚古想要佔領天尊之廷，然後把我們全部獻祭給歐朵斯。趕走他們，恢復原本的平衡。", progress = nil, completion = "你的成就眾多，你的勇氣無庸置疑。目前歐朵揚古被趕了回去，但是別低估他們。要恢復島上的平衡，我們得時時不懈。", rewards = "您會收到：\n\n恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33343] = {title = "火焰大祭司", objective = "召喚並擊敗火焰大祭司。", description = "你的努力成功逐走了歐朵揚古，並且讓天尊之廷重獲和平，但這不是永遠的。是時候除去歐朵斯的特使，火焰大祭司了。\n\n和織霧者阿古交談並購買一份挑戰之卷軸，然後前往北邊的三風台地。向挑戰之石宣告挑戰，召喚出強大的生物。持續挑戰，直到你吸引到歐朵斯的注意，將火焰大祭司從歐朵聖堂引出來。這是你唯一的機會。", progress = nil, completion = "歐朵斯的特使暫時被消滅了。\n\n要知道，憤怒、暴力和仇恨是永遠不會消失的。只要一個人的靈魂裡存有黑暗，你就會發現這些煞等待著你。他們可能以各種方式現形：一名渴望權力的督軍，黑夜中從背後襲來的匕首，一名步上黑暗道路的王子，甚至是你與敵對勢力對抗的戰鬥。\n\n從這些情感中學習，別讓自己迷失在黑暗之中。", rewards = "您會收到：\n\n永恆之負恆龍寶箱永恆硬幣"}
MultiLanguageQuestData['tw'][33344] = {title = "武裝凶器", objective = "將武器交給10名霜狼奴隸。", description = "萊格拉來的時候帶了一些武器，這樣霜狼奴隸就可以成為武裝戰力。\n\n武裝他們，擊敗奴隸販子，殺出血路！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
