MultiLanguageQuestData['tw'][33349] = {title = "STARTER QUEST - RED->PURPLE 15", objective = "跑過這道拱門，碰到紅色標記，再來是紫色標記，再回到鋼鐵精靈比賽營地。", description = "比賽規則是這樣的，跑過這道拱門，碰到紅色標記，再來是紫色標記，最後在15響內回到這裡。祝你好運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33350] = {title = "赤脊组试炼", objective = "Log description text.", description = "赤脊组试炼。抵达蓝色标记，然后是绿色标记，再然后是红色标记，最后返回湖畔镇钢铁精灵营地。", progress = nil, completion = nil, rewards = nil}
