MultiLanguageQuestData['tw'][33352] = {title = "Tracking Event: Chief killed", objective = "击败蕨人首领。好吧，好朋友。让我们跟那个又老又臭的脏首领谈一谈。我们闻上去像月光石和美食那么香。我们把月亮石送给朋友们。我们告诉朋友们我才是首领。所有的美食都归我们。\n\n那个又蠢又臭的首领。他以为我是美食？他才是美食。\n\n该享用美食了好朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "好吧，好朋友。让我们跟那个又老又臭的脏首领谈一谈。我们闻上去像月光石和美食那么香。我们把月亮石送给朋友们。我们告诉朋友们我才是首领。所有的美食都归我们。\n\n那个又蠢又臭的首领。他以为我是美食？他才是美食。\n\n该享用美食了好朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33354] = {title = "獸穴之后殞落", objective = "將月牙狼皮帶去暗月島，交給暗月馬戲團的亞布‧尼比蓋爾。", description = "這是暗月島上巨大母狼的毛皮。\n\n暗月馬戲團的馴獸者亞布‧尼比蓋爾會很高興，這隻鬼魅一般的狼和牠的子嗣再也不會對他的馬戲團造成威脅了…至少暫時是這樣。把東西拿去給他吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗月獎品券"}
MultiLanguageQuestData['tw'][33358] = {title = "湯麵時刻:獎勵", objective = "在半丘拉麵攤加入擺攤的佇列，再完成獎勵目標。", description = "你好啊，<name>。覺得你是個貨真價實的優秀湯麵廚師嗎?\n\n我們來看看你的本事吧!您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵爪徽章"}
MultiLanguageQuestData['tw'][33359] = {title = "相約在墜星哨站", objective = "在墜星哨站與大法師卡德加交談。", description = "大法師在這個峽谷裡面發現了暗影議會的行蹤，特地請我來通報。\n\n只要你有空，就到墜星哨站來加入我們。我們需要你的力量才能將其斬草除根，指揮官。", progress = nil, completion = "又見面了，&lt;name&gt;。你來的正是時候。\n\n我們追蹤暗影議會來到了附近的一座村莊，而且我懷疑古爾丹就跟他們在一起。", rewards = "您會收到：\n\n"}
