MultiLanguageQuestData['tw'][33400] = {title = "普遍问题", objective = "与指挥官多尔戈什交谈。我的军队处境艰难。钢铁部落无止无休地冲击着我们的防御。\n\n如果你真想要帮忙的话，就去前线找我的指挥官，帮他们稳住阵线吧。", description = "我的军队处境艰难。钢铁部落无止无休地冲击着我们的防御。\n\n如果你真想要帮忙的话，就去前线找我的指挥官，帮他们稳住阵线吧。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33401] = {title = "托尔格的麻烦", objective = "与指挥官托尔格交谈。我的军队处境艰难。钢铁部落无止无休地冲击着我们的防御。\n\n如果你真想要帮忙的话，就去前线找我的指挥官，帮他们稳住阵线吧。", description = "我的军队处境艰难。钢铁部落无止无休地冲击着我们的防御。\n\n如果你真想要帮忙的话，就去前线找我的指挥官，帮他们稳住阵线吧。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33402] = {title = "维里克的守备官", objective = "与指挥官维里克交谈。我的军队处境艰难。钢铁部落无止无休地冲击着我们的防御。\n\n如果你真想要帮忙的话，就去前线找我的指挥官，帮他们稳住阵线吧。", description = "我的军队处境艰难。钢铁部落无止无休地冲击着我们的防御。\n\n如果你真想要帮忙的话，就去前线找我的指挥官，帮他们稳住阵线吧。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33408] = {title = "大火球！", objective = "和劍刃堡壘的索爾交談。", description = "格納爾帶著萊格拉一行人闖進了堡壘二樓。你的朋友索爾也投入了戰鬥。\n\n從壁壘南端的坡道上去，和他們會合。\n\n一起迎向霜狼氏族的勝利!您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33409] = {title = "艾尔文跑步大赛", objective = "击中蓝色标记，然后是绿色标记，最后返回钢铁精灵游戏营地。", description = "欢迎来到钢铁精灵游戏营地！在这项挑战中：你需要抵达蓝色标记，然后是绿色标记，最后返回这里。\n\n你的得分取决于你用掉的时间，以最快的速度跑回来吧！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33410] = {title = "劍刃堡壘的屠夫", objective = "殺死無情的多羅格。", description = "在格納爾闖進堡壘之後，那些劍刃氏族的混帳對我們放出一頭巨大的生物！\n\n施展魔法之後，我一直都很虛弱，不過至少我能幫這名獸人治療傷勢。\n\n幫我們把多羅格收拾掉吧，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "霜狼斥候手套霜狼堅實護手霜狼風語者手套霜狼環甲護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][33412] = {title = "清理善後", objective = "到血之環和『堅毅者』伊格瑞瑪交談。", description = "今天的勝利屬於我們，但我們的工作才剛剛開始。\n\n我的部隊會清理城塞，並除掉任何倖存者。至於你，我把清理北邊鬥士之坑的榮耀交給你。\n\n早在我們發動攻擊之前，就派了一位得力手下去偵察那個區域。若你仍渴望鮮血，就去幫忙她吧。那裡一定還有些麻煩需要解決。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
