MultiLanguageQuestData['tw'][33419] = {title = "生死一線間", objective = "尋找血棘洞穴中的阿雷克、迪雅妮和祝羅。", description = "陌生人，請幫幫我們！\n\n我和夥伴冒險到達此地，獵捕懸賞的怪物毒蜂蟲后。\n\n我們在山丘下搭好營地後便昏昏睡去。沒想到半夜時分，我們居然被這些恐怖又蒼白的…不明生物攻擊！\n\n我不知道我朋友到哪去了，但是我聽到洞穴深處傳來了尖叫聲。\n\n求求你，找到我的夥伴！我絕對不能丟下他們！", progress = nil, completion = "我的祈禱終於有回應了，英雄。我會讓村莊裡的每個人都知道你的英勇事蹟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33422] = {title = "艾爾文長程練習", objective = "跑過這道拱門，碰到藍色標記，再碰到綠色標記，再回到鋼鐵地精比賽營地。", description = "比賽規則是這樣的：跑過這道拱門，碰到藍色標記，再來是綠色標記，最後回到這裡來。\n\n你的時間很充裕。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n[Power Transformer: Dash]"}
MultiLanguageQuestData['tw'][33425] = {title = "Blue/Yellow Sprint 15 INTERNAL REPEATABLE", objective = "跑過這道拱門，碰到藍色標記，再來是綠色標記，再回到鋼鐵精靈比賽營地。", description = "[Ready for a tougher challenge? This one has an extra leg:\n\nRun through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here before the bell tolls 15 times.\n\nGood luck!]您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33427] = {title = "怒火燎原", objective = "到霜火峰找你要塞裡的將領佐格交談。", description = "德雷克塔爾只要適應一下，就會沒事的。元素所顯現的預知幻景是如此強大，他會脫胎換骨，並成為世上最偉大的薩滿。\n\n到要塞找將領佐格，告訴他這裡發生的事。\n\n他也許可以部署一些兵力到這個地區來保衛此處的安危。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
