MultiLanguageQuestData['tw'][33461] = {title = "幽蔭獵人", objective = "在幽蔭林地收集食材。", description = "<你在一張羊皮紙上找到一份詳細的清單。\n\n亞森尼歐為要塞準備的新食譜需要一些食材。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33462] = {title = "雷霆王教學", objective = "製作一副雷霆王爪鉤。", description = "地上散布著雷霆王鎖鍊的零件。鎖鍊的設計看起來很簡單，不過效果出奇的好。\n\n只要拿到足夠的零件，即使是第一次看到的人也會知道怎麼組裝，而且組裝後的成品就和雷霆王爪鉤手所用的一樣有效。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n雷霆王爪鉤\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][33463] = {title = "钢铁狂潮", objective = "在卡拉波消灭炽燃者阿诺克和10位钢铁部落成员。", description = "卡拉波的大部分防御部队都在西边的前线上迎战敌人的主力大军。但除了应对那个方向的攻势之外，我们也决不能忽视了对侧翼的防守。\n\n有位名叫阿诺克的敌军首领正率军攻打神殿的这一侧。去干掉他，连同他那些兽人追随者，最好一个不留。\n\n等你完成任务后，到神殿前方来见我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33464] = {title = "高墙之外", objective = "从卡拉波的外墙附近拆除6个黑石氏族抓钩。", description = "卡拉波正在陷落。钢铁部落不会停止攻击，直到把我们全都赶尽杀绝为止。\n\n我不知道你是怎么打算的，可我决不会让那种事发生。\n\n现在，我们一定得做点什么，以阻止他们攀爬我们的城墙……您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33467] = {title = "督軍的隕落", objective = "殺死督軍布沃特。", description = "你已經走到這一步了，陌生人。剩下的工作就是打垮競技場的督軍。\n\n這將是你的第一項真正考驗。即使是飽經戰場磨練的霜狼，面對布沃特都是項艱鉅的挑戰。\n\n將你收集到的首級放在霜火競技場的長矛上。此舉一定會觸怒督軍，引誘他加入戰局。\n\n以勝利者的姿態走出競技場，證明杜洛坦對你的信任沒有錯付。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "競技戰士徽印競技之王璽戒競技潛藏者戒指您會收到：\n\n"}
MultiLanguageQuestData['tw'][33468] = {title = "保衛狼居", objective = "保衛沃格爾，擊退雷霆王氏族。", description = "雷霆王那些懦夫…\n\n在堡壘的戰鬥中，傳令兵告訴我，鐵狼正在攻擊我們的家園。他不會有好下場的，他每殺一個族人，德拉卡都會讓他付出十倍的代價，但是我們仍然必須趕快回去把那些傢伙趕走。\n\n你跟你的盟軍證明了你們是霜狼的忠實戰友。我們歡迎你們來協助我們守護沃格爾。\n\n若你願意前去，我們就在戰場上見吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33469] = {title = "先知", objective = "前往幻景之池，殺死領軍伽葛拉克。", description = "雷霆王領軍啊…<name>，你得想辦法阻止他。\n\n他的部隊往西北方去了，準備對幻景之池的德雷克塔爾發動攻擊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33470] = {title = "幻景之池", objective = "到幻景之池與先知德雷克塔爾交談，開始進行預知儀式。", description = "強風起天末，<class>。\n\n我已經準備好儀式，請你向幻景之池請益，看看我們未來的命運如何。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "霜狼斥候肩甲霜狼堅實護肩霜狼風語者披肩霜狼環甲肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][33473] = {title = "返回劍刃堡壘", objective = "回劍刃堡壘找杜洛坦。", description = "請你把預知幻景轉達給杜洛坦，浦爾‧雕風者會送你一程。\n\n霜狼一族…以及德拉諾的命運，就全看你了，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33483] = {title = "穆維里克的困境", objective = "從奴隸管理者特加爾身上取得鑰匙並找回穆維里克的斧頭。", description = "你要讓我重獲自由？看來我們可以合作。\n\n煤污礦場的奴隸管理者特加爾手中一定有這個牢籠的鑰匙。\n\n當你進入礦場之後，能不能留意一下，哪個沒種的監工拿了我的斧頭？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "狼皮披氅狼皮巨披風狼皮披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][33484] = {title = "奴隸管理者之死", objective = "和劍刃堡壘的古絲交談。", description = "和你今天救出的其他霜狼族人聊聊。他們會很高興得知還有其他人活著逃離礦場。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][33485] = {title = "多人競賽", objective = "跑過這道拱門，碰到藍色標記，再來是綠色標記，紅色標記和紫色標記，最後回到鋼鐵精靈比賽營地。", description = "跑過這道拱門…\n碰到藍色標記…\n再來是綠色標記…\n還有紅色標記，\n紫色標記，\n再回到這裡…\n然後再重複一次。沒錯，2輪！\n\n祝你好運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33493] = {title = "重返狼群", objective = "在你的要塞和杜洛坦交談。", description = "卡格也不盡然是錯的：我們現在「能」挑戰鐵狼了。只要一提到他的名字，我的拳頭就會握緊。我的肌肉就會嘶吼著要復仇。\n\n但是在我內心深處，我可以感受到艾薩試圖讓我冷靜下來，試圖引導我。我沒有資格領受她的智慧，但我不會平白浪費這贈禮。\n\n<羅克拉瞇起雙眼看著天空。>\n\n杜洛坦和其他人現在差不多在你的要塞集結了。我們應該去見見他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
