MultiLanguageQuestData['tw'][33513] = {title = "黑棘的副官", objective = "殺死阿魯斯、莫德雷斯和肉疙瘩。", description = "亞門納爾的轉生迫在眉梢。為了保護儀式，亡語者黑棘已在我們與他之間部署了他最信賴的副官。\n\n阿魯斯，一隻在其幼蛛附近築巢的染疫蜘蛛，受到亡首毒法師的照料。莫德雷斯正在骸骨堆集結亞門納爾的軍力。最後，肉疙瘩則守衛著荊棘螺旋的入口。\n\n一旦你擊敗這些守衛，我們就可以合力迎戰黑棘。", progress = nil, completion = "你做得很好，但戰鬥還沒有結束。輔助他的軍隊已陷入混亂，現在是對亡語者黑棘展開攻擊的好機會。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33514] = {title = "復活儀式", objective = "殺死『寒冰使者』亞門納爾。", description = "你這麼快趕來真的太好了。為了拯救卡林多，我必須請你再度冒險。\n\n亞門納爾的得意弟子，亡語者黑棘，希望讓他的導師重返人世！我們必須盡快登上荊棘螺旋，在儀式完成前打敗他。我們必須一同攻擊，只有集結所有力量，才有機會阻止他的野心！", progress = nil, completion = "做得很好，&lt;name&gt;。亞門納爾的骨匣現在有紅龍軍團在監管，我們可以安心了。", rewards = "寒冰使者的護腿剃刀肩甲救贖護胸暴虐奴役腰帶柯莉史卓莎護符您會收到：\n\n"}
MultiLanguageQuestData['tw'][33516] = {title = "剑走偏锋", objective = "关闭4个安全阀。", description = "这些设计图就连最没有经验的冶炼新手都能看懂。他们在特定的管道上用显眼的符号标示出了哪些阀门不得转动，除非愿意付出死伤惨重的巨大代价。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33521] = {title = "拯救奥金尼看护者", objective = "到塔拉多的光辉庭院，将6位奥金尼看护者送到安全地点。", description = "我非常幸运，恶魔攻击时，我正去给大主教送情报，可我其他的同胞都去了光辉庭院！\n\n我们这些看护者都没什么战斗经验。快去西北边的庭院，帮他们脱离险境吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
