MultiLanguageQuestData['tw'][33656] = {title = "集拢塔布羊", objective = "在库洛斯农场救出4只塔布羊。", description = "我的父亲卡尔曼是这农场的主人，我们饲养的主要家畜是塔布羊。肯定有魔荚打开了畜栏的大门，结果它们全都跑光了！\n\n那些小怪物其实完全可以在畜栏里杀死这些塔布羊，可它们享受猎杀的快感。我担心如果我继续留在这里的话，就要变成它们的下一顿美餐了！\n\n你愿意帮我找回那些塔布羊，把它们带来这里吗？我自己搞不定，而且我也不能让我爸爸发现这个意外！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33657] = {title = "進駐堡壘", objective = "和劍刃堡壘的杜洛坦見面。", description = "戈爾索格終於死了，我們總算可以在劍刃堡壘站穩陣腳了。到下面和我見面，我們得加強守備。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][33658] = {title = "钢铁信函", objective = "烧毁钢铁部落补给品和钢铁部落营地。", description = "<信件勾勒出了一个邪恶计划，他们要污染雷象原野进而破坏德莱尼的食物供给，与此同时，首领索克会派兵从山上的营地前往西北方去屠杀剩余的难民。>\n\n<如果你用他们留下的火炬烧毁他们在这里的补给品和前沿营地的话，就能给防御军争取到宝贵的时间，以应对即将到来的进攻！>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
