MultiLanguageQuestData['tw'][33781] = {title = "生存专家之道", objective = "在影月谷的审判祭坛收集6个萤光虫蚕丝和12个刃齿之牙。", description = "我当时正在追踪钢铁部落穿过钢铁先遣站，结果被他们的一个奇美拉骑兵发现了。\n\n我拼死击退了他们的围剿小队，但也受了重伤，已经不能再继续前进了。陌生人，我必须取得尽可能多的情报来巩固卡拉波的防御。\n\n如果你能给我带来蚕丝，并从附近湖里的鳐鱼身上找来几颗牙齿，我就能给自己动个手术，用自制的绷带包扎好伤口，这样我就可以撑下去继续完成任务了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33782] = {title = "維持平衡", objective = "在阿比提姆殺死鉗顎。", description = "看看這些齒痕，朋友。這些強力的咬痕表示這條鱷魚是屈服於同一物種的生物。當雌鱷長得夠大之後，她會對同物種實施支配權。\n\n身為獵人的職責，就是確保這些生物之間維持平衡，如同我會感謝他們的犧牲來成就我的生命一樣。\n\n追蹤這頭野獸的下落，並在我包紮傷口的時候殺死她。她很可能在阿比提姆的遠方出沒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33783] = {title = "库洛斯农场", objective = "在库洛斯农场找到贝尔多斯。许多来自图雷姆的难民已经去了东边的库洛斯农场。\n\n如果你能办到的话，就请去那里寻找贝尔多斯。他带领难民从图雷姆去了那里，是最合适的联络人。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "许多来自图雷姆的难民已经去了东边的库洛斯农场。\n\n如果你能办到的话，就请去那里寻找贝尔多斯。他带领难民从图雷姆去了那里，是最合适的联络人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33784] = {title = "格莫爾塔", objective = "從劍刃巨魔手中奪回格莫爾塔。", description = "現在換我們主動出擊，對抗企圖奴役我們的傢伙！\n\n我們要前往格莫爾塔，從劍刃巨魔手中把這個地方搶回來。我很歡迎你能與我們同行。\n\n上來吧，我們一起衝殺吧！", progress = nil, completion = "我終於知道你為什麼能夠從奴役之手拯救我們氏族了。多麼強大！", rewards = "霜狼斥候長靴霜狼堅實戰靴霜狼風語者足靴霜狼環甲長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][33785] = {title = "解放的卡格", objective = "殺死25個格羅姆加的雷霆王獸人。", description = "他們奪走了我的兄弟姐妹。\n\n他們奪走了我的狼。\n\n<卡格舉起斧頭，注視著刃鋒。>\n\n現在，我們會砍下他們的頭。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33786] = {title = "動彈不得的車隊", objective = "在影月谷尋找菲歐娜的馬車。", description = "我收到報告說波塔尼已經離開它們的棲息地，開始攻擊旅人。這件事很不尋常。\n\n我們已經派出一批遊俠來解決這個問題。\n\n最近有個從艾澤拉斯來的車隊經過這裡，或許你該去看看他們，確保他們的安全。", progress = nil, completion = "指揮官！很高興見到你。\n\n這裡出了點狀況。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33787] = {title = "菲歐娜的解藥", objective = "在影月谷收集1顆河獸之心、2份沼澤螢光蟲毒液、4株暴動藤蔓以及3株月光草。", description = "基德溫被那些植物攻擊了。\n\n看樣子他似乎被麻痺了。\n\n我可以製作解藥，但我需要一些當地的材料。", progress = "你有材料嗎?", completion = "太棒啦，&lt;name&gt;！基底劑就快好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33788] = {title = "活性藥草的調製工作", objective = "協助影月谷的菲歐娜製作治療藥劑。", description = "基底劑已經煮滾，可以加入材料了。\n\n一次加入一種，我會負責混合和攪拌。準備好就跟我說吧。", progress = nil, completion = "基德溫看起來好多了。謝謝你，&lt;name&gt;。\n\n我們正好有足夠的藥劑幫助其他人。", rewards = "您會收到：\n\n配方：菲歐娜的藥劑"}
MultiLanguageQuestData['tw'][33793] = {title = "虛無使者", objective = "消滅暗影之靈、黑暗之靈及苦痛之靈。", description = "我們的斥候發現一件駭人聽聞的事，<name>。\n\n俘虜的靈魂被用來召喚虛無中的生物。\n\n在裡面已經有三隻黑暗生物，分別是暗影之靈、黑暗之靈和苦痛之靈。\n\n我們必須在它們的力量釋放前立刻把它們解決掉。", progress = nil, completion = "我就知道可以放心讓你處理這件事情，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33794] = {title = "偉大的救贖", objective = "從牢籠中解救8個德萊尼俘虜。", description = "我們知道俘虜在哪裡了。他們都被關在這座影月堡壘裡面。\n\n拜託你，盡可能把那些俘虜都救出來。動作要快，我在這裡都聽得到他們的慘叫。", progress = nil, completion = "我們會照顧所有的生還者。多虧你救了他們的命，謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33795] = {title = "浩瀚星空", objective = "收集5份星象解讀記錄。", description = "影月氏族力量的重要來源，是他們對星象以及神諭的了解。\n\n數個世紀以來，他們記錄了星辰的運行以及他們對此的解讀。\n\n當你進入堡壘後，替我收集這些文件。\n\n我會用他們自己的知識來對付他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33800] = {title = "Darren's Bombing Run of Awesomeness", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33807] = {title = "解放行動", objective = "釋放6頭霜狼或沃格爾村民。", description = "雷霆王的膽小鬼只會用網子和鎖鍊這種懦夫的武器。\n\n但是不少村民和霜狼同胞都被困住了。\n\n只要釋放他們，他們就會和你一起奮戰。\n\n我們得趕快平息這次攻擊，這樣我才能回到劍刃堡壘繼續進行準備工作。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33808] = {title = "沼澤螢光蟲后", objective = "幫影月谷的菲歐娜取得沼澤螢光蟲后之尾。", description = "看來那些植物使用了某種毒物攻擊基德溫。\n\n這種混合物的毒性相當強烈。\n\n如果想要治好基德溫，我們還需要一種特別的材料。這種材料比其他的更難取得。\n\n你願意接受這個挑戰嗎，<name>？", progress = "我只想採一些藥草，和我的孩子們好好放鬆一下…我應該待在艾澤拉斯的。", completion = "喔喔，動作真快啊！好，讓我們開始救治吧！", rewards = "卡拉伯爾爭鬥者外衣卡拉伯爾榮譽守衛胸鎧遊俠初學者外衣卡拉伯爾賢者長袍您會收到：\n\n"}
MultiLanguageQuestData['tw'][33813] = {title = "急需英雄", objective = "提水撲滅火焰，救出史奎吉。", description = "我…<啜泣>…我不能走…<哽咽>…不能沒有…史奎吉…！\n\n他…他被…困住了！\n\n你一定要…撲滅…那團火！\n\n<雅莉安娜指著房間對面，放聲大哭。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33814] = {title = "快速擴張", objective = "到影月谷找你要塞裡的巴洛斯‧艾力克斯頓回報。", description = "你好，指揮官！\n\n我代表巴洛斯‧艾力克斯頓來到這裡。\n\n我們已經集結充分的資源，可以進行下一階段的擴張。\n\n他希望能盡快與你談話。", progress = nil, completion = "啊，歡迎，指揮官！正想到你呢。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33815] = {title = "霜與火之歌", objective = "和杜洛坦見面。", description = "你從塔南的奴隸窩中救出了我的族人。你讓族人們重獲自由，還破壞了黑暗之門，讓我完全相信你是值得我們信賴的夥伴。\n\n不過，我們的首領杜洛坦可能對你還沒有印象，我想介紹你們彼此認識一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33816] = {title = "榮耀有其獎勵", objective = "前往沃格爾的薩滿石處，並獲得祝福。", description = "你讓我的族人備感榮耀。現在，我們希望能和你一同共享榮耀。\n\n我們的氏族有一項成年儀式。在成年時，族人會用首次狩獵的鮮血塗抹身體，並將手放在薩滿石上禮敬從前的先祖。\n\n在我們並肩作戰的短時間內，你已經殺死許多比我們的獵人一生中所面對的敵人更為強大的敵手。去吧，觸碰在沃格爾的薩滿石，以平等的身分成為我們的一份子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33817] = {title = "争斗的痕迹", objective = "在染血的日记附近的背包里翻找。", description = "从标记来看，那像是一本某位影月兽人随身携带的日记。\n\n<哈格拉昨晚消失了。她是第五个在夜晚消失的人。为什么他们只会在夜晚消失呢？>\n\n<我一定会查出真相。今晚我要等着看看到底是什么怪兽在我们的村子里出没。>\n\n<我要把那怪兽的脑袋带给鲁尔坎，然后把我的亲戚们送回家。>\n\n也许那野兽的脑袋就在前方废墟的某个背包里？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][33820] = {title = "Tracking Quest: Seen Escape Cinematic", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][33822] = {title = "拉布鲁的反叛", objective = "在影月谷的迦尔玛克沙石场找到拉布鲁。拉布鲁不肯听。他杀死了一个守卫，他们把他拖到其中一个帐篷里去了。\n\n他们肯定要杀了他！您會收到：\n\n完成任務後，你將獲得：\n\n", description = "拉布鲁不肯听。他杀死了一个守卫，他们把他拖到其中一个帐篷里去了。\n\n他们肯定要杀了他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
