MultiLanguageQuestData['tw'][34078] = {title = "完成服務，支付酬勞", objective = "帶著加茲魯維到位於鋼鐵軍火廠內的黑錘霸主要塞的屋頂上。", description = "我準備好要離開這裡了，我可不想再跟這些獸人攪和。\n\n幸好，我留了一些火箭雞在身上，讓我們能帥氣地返回你的要塞！快到屋頂上去，找個好地方起飛吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34080] = {title = "物归原主", objective = "归还皮下追踪器。", description = "这个小巧的跟踪装置是用来收集生物数据的。它似乎是被绑在了一枚飞镖上，然后从远距离之外射出。\n\n在仔细检查过这个装置后，你根据信号找到了附近的接收器。里面的数据信息可能非常重要，你或许应该去找它的主人，尽快物归原主。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34084] = {title = "Keeping Calm", objective = "在白月镇与杜尔加谈一谈。<这些珠子的主人一定是你救下的那个名叫卡杜兹的萨满祭司。珠子上刻着“杜尔加”的名字。>\n\n<他说过让你到附近的白月镇去找他。你肯定能在那见到卡杜兹和杜尔加两人。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<这些珠子的主人一定是你救下的那个名叫卡杜兹的萨满祭司。珠子上刻着“杜尔加”的名字。>\n\n<他说过让你到附近的白月镇去找他。你肯定能在那见到卡杜兹和杜尔加两人。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34087] = {title = "對鏡望遠", objective = "用塞林的觀測機來觀察。", description = "塞林，你的一位盟友在幫我們對鋼鐵部落展開反擊。\n\n他宣稱這個裝置可以用來監視敵人的一舉一動，就算距離很遠也可以聽到他們在說什麼。\n\n我不相信這樣的裝置。你來用用看，告訴我你看到了什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34088] = {title = "火中炙鐵", objective = "到莫格蘭伐木場打倒15位鋼鐵部落的成員。", description = "一定要殺光侵擾我們土地的鋼鐵部落大軍。 \n\n找出玷污偉大森林的元兇，讓他們知道什麼是正義。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34089] = {title = "供給短缺", objective = "收集6個鋼鐵部落炸藥。", description = "鋼鐵部落在伐木營地中心存放了爆裂裝置。 \n\n我們得取回這些東西，以免他們用來對付我們。\n \n我會盯著瑪銳德…他生氣的時候讓人很擔心。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34090] = {title = "塞林的應急裝置", objective = "摧毀雷霆王儲物所、黑石熔爐和原木存放場。", description = "這些獸人總是喜歡把東西堆在一個地方。這倒是給了我一個想法…\n\n我幫你做了這個絕妙的裝置！只要你離目標夠近，它就會通知你，在部署之後就可以引發保證讓你滿意的大爆炸！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n外燃機「可靠的」威脅評估器防呆瞄準裝置\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34091] = {title = "除役任務", objective = "殺死工程師特拉克，並找回閒置的鋼鐵伐木機。", description = "可緹雅‧碎鐵，\n\n你打造的全新鋼鐵伐木機，對我們自己的士兵造成了嚴重威脅。\n \n馬上讓原型機除役，把它移走，直到你把問題解決為止。\n\n同時，我會派遣工程師特拉克前去處理問題。\n \n- 奧格林‧末日錘您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34092] = {title = "孤注一擲", objective = "收集安格拉斯法術書及魔典：綁定術，然後在安格拉斯廢墟中的安格拉斯祭壇進行儀式。", description = "我們已經找出泰朗戈爾營地的位置，但他的兵力之強，是我們前所未見的。我們一定要想辦法取得優勢，而且要快。\n\n安格拉斯巨魔受詛咒的靈魂，我們的宿敵，就在附近的遺跡盤桓。到那裡取回安格拉斯法術書和魔典：綁定術。\n\n在他們的祭壇進行魔典中記載的儀式，解除詛咒，並尋求他們的幫助。\n\n這件事不容易做到，但我們已經別無選擇了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34093] = {title = "收集尖矛", objective = "在阿古拉克之骨內收集5支雷霆王尖刃長矛。", description = "那些在我們頭上盤旋的雷霆王騎兵是一大麻煩，<name>。\n\n他們輕鬆騎著那些可悲的萊拉克飛過山谷，自以為安全無虞，從我們頭上降下矛雨。我們必須讓他們了解，面對決心復仇的霜狼時，他們無處可逃！\n\n我有個計畫，不過我們必須先收集一些材料。去山谷裡面尋找完整無缺的長矛，五支就夠了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34094] = {title = "第十卷的書頁呢？", objective = "從阿克農陣地的獸人身上收集20張說明書頁。", description = "那台伐木機的駕駛艙內塞了一本說明書，只是缺了很多張書頁。只要能找齊缺漏的書頁，我敢用我的第三根腳趾來打賭，這台原型伐木機一定可以動起來。 \n\n我發誓之前在阿克農陣地那邊有看到一些書頁在那兒飄來飛去的，說不定那些獸人身上會有帶著。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34095] = {title = "夷平一切", objective = "摧毀6台鋼鐵部落的攻城機具。", description = "除了那些獸人之外，我們還有其他威脅。他們的攻城武器仍然具備可觀的威力。\n\n他們已經被用來攻擊杜瑞，我們不能讓他們持續這樣的舉動。\n\n用你從伐木營地拿回來的炸藥破壞攻城武器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34096] = {title = "保密防諜", objective = "用塞林的觀測機來觀察。", description = "我現在就讓這台原型伐木機動起來！\n\n看看我的觀測機。你會看到等會要前往的地方…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34097] = {title = "為切碎而生", objective = "在杜瑞用鋼鐵伐木機殺死100個鋼鐵部落的人。", description = "我把這台原型伐木機大部分的汽缸都啟動了。\n \n當他們看到你開著他們的機器四處踐踏時一定會大吃一驚！\n\n簡直等不及在觀測機上看你表演了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34098] = {title = "死亡工程", objective = "擊敗可緹雅‧碎鐵。", description = "-- 老媽來了。警告！警告！--您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "可緹雅的火槍鋼鐵伐木機輪軸凸輪軸柄斬斧鋼鐵伐木機裝置斷裂的伐木機刀刃鋸刃之斧多功能伐木機油壓控制桿停機備用戰斧您會收到：\n\n"}
MultiLanguageQuestData['tw'][34099] = {title = "為撒塔斯而戰", objective = "將鋼鐵部落趕出撒塔斯。", description = "如果我們的目標是阻止鋼鐵部落，那我們必須克服偏見，攜手合作。 \n\n部落，聯盟。過去，現在…在這個敵人面前，都毫無意義。\n\n我們要一起奪回撒塔斯，…至少拚死一試。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "塔拉多爾哨兵手套薩塔守護者手甲奧奇奈守護者手套薩塔神射手護手您會收到：\n\n"}
