MultiLanguageQuestData['tw'][34362] = {title = "暗影之門", objective = "擊敗戈魯諾爾‧戰臟並跟上波格爾。", description = "好了，我們動作真的要快了。\n\n我曾經看過波格爾開啟魔法傳送門，他很有可能會利用其中一道門逃跑。如果他真的這麼做，我們也只能跟上去了。此外，他會讓副官戈魯諾爾隨侍在側，所以免不了一場惡鬥。\n\n<歐維恩窺視著山洞>\n\n躲好一點，裡面有些動靜。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34364] = {title = "為了部落！", objective = "插上部落旌旗，成為此地的擁有人。", description = "要不是有你的協助，我們恐怕沒有人能夠活著抵達我故鄉的海岸。現在將由你來領導我們在德拉諾的兵力，並且建造歸你指揮的要塞。\n\n我就讓你來插上旌旗，擁有這塊土地。等你準備好，我會請卡德加打開傳送門，把必要的人手和物資送過來。", progress = nil, completion = "指揮官，我遵從你的命令。", rewards = "霜狼手斧霜狼斬斧霜狼巨斧霜狼獵弩霜狼靴中刀霜狼占兆杖霜狼登山杖霜狼風語者鬥棍您會收到：\n\n"}
MultiLanguageQuestData['tw'][34365] = {title = "釋放萊拉克", objective = "在暗潮棲息地放出籠中的萊拉克。", description = "這些哥布林一直在萊拉克身上進行各種可怕的實驗。這個笨蛋給了我三個寶貴的實驗地點。\n\n讓這些突變的萊拉克重獲自由。或許自由可以讓這些備受折磨的靈魂，找到生命中的少許平靜。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34375] = {title = "重返工作", objective = "標記6棵樹木。", description = "好的，老闆。要讓這座要塞開始動起來，首先我們需要一些木材。\n\n只要你把要砍的樹標記好，剩下的工作你的苦工就會幫你包辦到好。", progress = nil, completion = "現在木頭應該夠了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34376] = {title = "不是矿石", objective = "消灭蒙奇。", description = "好吧，指挥官，事情是这样的。你想要给你的要塞加装尖刺和各种酷酷的东西对吧？要想开工，我们就得从附近的洞穴里找些矿石来。\n\n检查东南边的洞穴。别看我才刚到这里，我敢打赌里面肯定有个难缠的大家伙。\n\n干掉它，然后劳工们就会为你采集矿石了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34377] = {title = "通往家乡的传送门", objective = nil, description = "[Ph] Khadgar is willing to open a portal to Azeroth, if only briefly, to get some of those we need to secure our foothold here.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34378] = {title = "建立你的要塞", objective = "使用主監控裝置視察你要塞的施工進度", description = "好戲上場！我們有物資、有人力，該有的錢也不缺。\n\n動手把這個蓋起來吧！\n\n我在西邊的山上有一大群助手。\n\n他們應該把你的私人監控所蓋好了。\n\n到那裡去，你可以從那裡視察我們的工程進度。", progress = nil, completion = "沒錯！我想一切都在我們的掌控之下。連爆炸聲都聽不到！", rewards = "您會收到：\n\n要塞爐石"}
MultiLanguageQuestData['tw'][34379] = {title = "狼窩", objective = "乘坐霜狼萊拉克飛往沃格爾。", description = "如今你已經建立了據點，杜洛坦希望我們能去見他。我希望他會願意接受你的協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34380] = {title = "集結霜狼勢力", objective = "請德拉卡吹響戰鬥號角。", description = "我那心急的哥哥已經等不下去了。我們還沒完全準備好，他就已經帶走了一些族人要去突襲劍刃堡壘。\n\n德拉卡在我們的戰鬥號角旁邊等你。請告訴她，現在是集結全族的時候了！\n\n靠著你和你部隊的幫助，我們很有可能戰勝巨魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34381] = {title = "暗影之門", objective = "擊敗戈魯諾爾‧戰臟並跟上波格爾。", description = "洞裡一定有巨魔，我聞到他們的臭味了。\n\n把武器拿好，我們動作要快，趕在巨魔開始丟魔精之前解決他們。\n\n<普雅窺視著山洞>\n\n小心點，裡面有點狀況。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34382] = {title = "Vignette: Grand Warlock Duress", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][34392] = {title = "終結惡戰", objective = "關閉黑暗之門的兩座惡魔尖塔。", description = "「用你們的生命保護古爾丹和暗影議會的成員！沒有那幾個囚犯的魔法，傳送門就無法使用。要是你們辜負我的期望，就等著看你們珍愛的一切都化成灰燼吧。\n\n-葛羅瑪許‧地獄吼。」\n\n鋼鐵部落似乎囚禁了幾個維持傳送門開啟的關鍵人物，到附近的尖塔裡去找找看！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34393] = {title = "傳送門的能量", objective = "進入黑暗之門底下的靈魂核心，然後關閉黑暗之門。", description = "啟動這個傳送門的既不是機械構造，也不是秘法能量。\n\n看看我們兩側，<name>。那些被殺死的俘虜，靈魂都被送到傳送門的中心。\n\n負責傳導這些靈魂的就是古爾丹。\n\n想辦法進到底下的房間，阻止古爾丹，別再讓他傳導靈魂。我們最後的希望就寄託在你身上了，<name>。", progress = nil, completion = "古爾丹…自由了。這並不是我預想的勝利。\n\n雖然古爾丹因為我們的行動而得以脫逃，但是能以他的自由換取傳送門另一端眾多的無辜生命，我認為還是值得欣慰的。你的決定相當明智，&lt;name&gt;。", rewards = "鋼鐵部落弩箭發射器鋼鐵部落輕斧鋼鐵部落戰爭鬥棍鋼鐵部落短斧鋼鐵部落儀式法杖鋼鐵部落戰斧鋼鐵部落藤杖鋼鐵部落雕刻刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][34397] = {title = "削減暗潮", objective = "解決暗潮領導者。", description = "為了求生的可悲藉口讓他背叛了同伴。而這一切只需要在脖子上輕輕一捏。\n\n找出這個行動的領導者，並把他們的腦袋拿回來。赫拉薩會和你一塊進行任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34398] = {title = "德拉諾之霸：黑暗之門", objective = "到詛咒之地的黑暗之門下，與大法師卡德加交談。", description = "\n\n\n大法師卡德加，第二次戰爭的英雄，正在集結艾澤拉斯的強者通過黑暗之門，阻止鋼鐵部落入侵艾澤拉斯。\n\n尋求榮耀的勇士可前往詛咒之地黑暗之門底部與卡德加會面。\n\n此行不保證安全。", progress = nil, completion = "看來我們到了對的地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34399] = {title = "礦場的麻煩", objective = "與復仇者杜魯談話。", description = "佐魯礦坑出事了！\n\n我們最近挖出一顆極為強大的巨型秘法水晶，但不知道出了什麼差錯，水晶的能量充斥了整個礦場。\n\n奧奇奈已經派了復仇者到礦場來幫忙。\n\n去礦場裡和復仇者杜魯交談，他會告訴你如何協助我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34400] = {title = "狂暴的食法者", objective = "對8個狂暴的食法者使用秘法消除器。", description = "塔拉多爾有一種稀有的飛蛾，叫做食法者，這些飛蛾以秘法水晶粉塵維生。\n\n一般而言，這些飛蛾除了偶爾造成困擾外，並不是甚麼大問題，但現在牠們吸收了由礦場散逸的強大秘法能量後，變得很有地盤意識，極具侵略性。\n\n我已經調節了這顆水晶，可以去除秘法能量，請用它來讓狂暴的食法者安定下來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34401] = {title = "秘法精華", objective = "取得6個秘法精華。", description = "凱莉娜拉在把所有秘法能量吸取殆盡前是不會罷休的…她也會同時毀掉這整個礦場。她用來保護自己的秘法護盾無法用一般的方式破除，但是我有個計畫。\n\n只要我有一顆足以暫時穿透那個護盾的強力聚能水晶，我們就能對付凱莉娜拉了。\n\n幸運的是，這裡就是製作聚能水晶的絕佳地點。你可以從那些在礦場裡橫衝直撞的生物身上，找一些秘法精華給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34402] = {title = "狼群與戰士", objective = "與杜洛坦同行。", description = "許多族人重返家園對我們而言實在是一大助力，而我在此感謝你協助拯救了他們的性命。\n\n來，跟我走吧。我們還有很多事要討論。", progress = nil, completion = "這片土地正符合我們的需要。指揮官，我們就讓你決定如何來運用它了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34403] = {title = "秘法精華", objective = "取得6個秘法精華。", description = "凱莉娜拉對秘法力量的欲念已經吞噬了她的理智，並對這個礦場造成了無比的威脅，我們一定要阻止她。\n\n不幸的是，只要她有那個護盾，我們就對她無可奈何，必須想辦法破除她的護盾法術。\n\n要是我能製作聚能水晶的話，就可以破解她的護盾…我需要你在水晶礦場中尋找必要的材料。\n\n首先，我需要這個礦場裡水晶狂怒者和秘法怨靈身上的秘法精華。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34404] = {title = "異能水晶", objective = "取得10個未精煉的能量水晶。", description = "這個大小和強度的秘法水晶，甚至在德拉諾都難得一見，看來德萊尼在這個礦場附近建立了撒塔斯和奧齊頓並非偶然。\n\n我對這些秘法水晶，以及它們具備的秘法能量特別有興趣。\n\n把你找到的未精煉的能量水晶帶回來給我，我會好好回報你的努力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34405] = {title = "DEPRECATED - REUSE", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34406] = {title = "陷入混亂", objective = "救出8個受傷的礦工。", description = "<name>，當混亂爆發時，不是每個德拉諾礦工都能安全離開，很多受傷的人還被困在裡面。\n\n凱莉娜拉所造成的破壞讓一切陷入混亂，釋出的能量衍生出秘法怨靈四處攻擊，而原本在地底沉睡的元素從岩石中甦醒，變得狂暴且危險。\n\n請盡可能找到所有受傷的礦工，並協助他們脫離險境。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34407] = {title = "堅守陣線", objective = "消滅15隻燃燒前線的惡魔。", description = "很高興再見到你，勇士。\n\n惡魔正在攻擊奧齊頓，我們只能勉力抵擋他們。\n\n我們必須推進前線，否則傷亡將難以估量。\n\n如果你是站在我們這邊的，那就讓你的利刃劃破這些惡魔生物的咽喉吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34409] = {title = "要塞戰役：戰場上的烏鴉", objective = "在格古隆德的天海山脊和黎沙莉‧烏鴉交談。", description = "德魯伊構建了廣大偵察網，用來追查你在納葛蘭獲得的情報。\n\n有一支可疑的鋼鐵部落隊伍，在格古隆德西岸的一些小鹽池旁邊進行探勘。\n\n我們有理由相信這些獸人正在沙漠深處尋找貴重的神器。\n\n我打算組織安排一次重點式的小型攻擊任務，我希望你能夠加入這個隊伍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34410] = {title = "跳動的心臟", objective = "把格古瑞克之心帶給你要塞裡的莫西斯‧語翼。", description = "有件事是肯定的。我們得到了一個對鋼鐵部落很有價值的物品。\n\n我們最好要立刻保護這個…「格古瑞克之心」。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
