MultiLanguageQuestData['tw'][34413] = {title = "Lumberstruck", objective = "Protect your peasants as they gather 100 lumber.", description = "[Test Quest - Do Not Translate]\n\nThis box is empty, begging to be filled with wood.\n\nProtect your peasants as they gather materials from the region.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34414] = {title = "巨人安杜雷", objective = "取回水晶巨人之心。", description = "要破除凱莉娜拉的秘法護盾，就需要能量極為強大的優質聚能水晶。\n\n在這個礦場裡，有個被德拉諾人稱為安杜雷的水晶巨人，長久以來他一直在地底沉睡，但凱莉娜拉的魯莽舉動喚醒了他。\n\n水晶巨人之心是非常強大的神器，請打敗安杜雷並將水晶巨人之心帶回來給我。\n\n只要有水晶巨人之心，就可以製作聚能水晶了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34415] = {title = "巨人安杜雷", objective = "取回水晶巨人之心。", description = "要破除凱莉娜拉的秘法護盾，就需要能量極為強大的優質聚能水晶。\n\n在這個礦場裡，有個被德拉諾人稱為安杜雷的水晶巨人，長久以來他一直在地底沉睡，但凱莉娜拉的魯莽舉動喚醒了他。\n\n水晶巨人之心是非常強大的神器，請打敗安杜雷並將水晶巨人之心帶回來給我。\n\n等你回來以後，我會做好聚能水晶，再一起去阻止凱莉娜拉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34418] = {title = "堅守陣線", objective = "消滅15隻燃燒前線的惡魔。", description = "奧齊頓正在遭受攻擊！\n\n雖然奧奇奈是抱持信念的英勇戰士，但他們無法獨力抵抗源源不絕的惡魔大軍。我們來到此地，就是為了阻止燃燒軍團吞沒德拉諾…合作是我們的最佳方案。\n\n我需要你去削減惡魔的數量，我們才能夠安全集結兵力，並向前推進到燃燒前線。\n\n今天，我們就在此阻止他們的腳步！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34420] = {title = "戰爭的代價", objective = "跟隨大法師卡德加。", description = "他們說這是自殺任務，不過我可不打算讓任何人白白送命。\n\n大家跟我來！", progress = nil, completion = "黑暗之門無法作用了，我們有了新任務，那就是設法存活。\n\n我們必須繼續奮鬥下去，即便只是為了榮耀那些殿後確保我們能夠撤退的戰友。", rewards = "您會學到：\n\n存活戰鬥\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34421] = {title = "鮮血乾涸", objective = "從心之血的2個血之谷牢籠中釋放奴隸。", description = "<獸人吐出了最後幾個字。>\n\n他們把我們關在籠子裡。他們…吸我們的血，用在…儀式上…\n\n<這位霜狼獸人劇烈地咳嗽。>\n\n…還有很多人…\n\n我的…族人…\n\n<獸人斷了氣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34422] = {title = "榮耀之火", objective = "使用光銀火石摧毀8間血之谷小屋。", description = "我們不能永遠待在這裡。我們必須繼續移動。但首先，我們需要引開敵人的注意力。\n\n<卡德加變出了一顆小型寶石。>\n\n這個火石能點燃任何在你附近的可燃物。用你的本事，再加上一點運氣，你應該能將血之谷獸人的注意力從我們身上移開。", progress = nil, completion = "方出虎穴，又入險林。\n\n喘口氣，做好準備，&lt;name&gt;。我們沒有太多時間休息。", rewards = "空心腿甲空心鍊甲護腿空心長褲空心窄褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][34423] = {title = "祭壇的爭鬥", objective = "與阿利歐克交談，並協助他轉移基爾羅格之眼的注意力。", description = "你看到那裡的祭壇了嗎？它上面有顆魔法之眼。如果它發現我們，恐怕我們將全軍覆沒。\n\n轉移它的注意力，<name>。製造混亂，殺掉祭儀師，不論要採取什麼必要手段，反正就是盡量吸引那隻眼睛的注意，讓我有足夠時間引導其它人通過它的視線範圍。\n\n<卡德加回頭看。>\n\n把那個魁梧的獸人也帶去。不是索爾，是他旁邊那個。", progress = nil, completion = "&lt;卡德加看來相當憂慮。&gt;\n\n不，我們不能等阿利歐克。他早知道這項任務會有危險。\n\n他不會白白犧牲的，我們必須繼續前進。", rewards = "您會學到：\n\n進階戰鬥機制\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34425] = {title = "卡加薩試煉場", objective = "跟隨卡德加。", description = "在高地的那些獸人看來很像破碎之手那夥的。看他們的手就知道。\n\n我們快與其他人會合吧。我們必須找路離開這裡。", progress = nil, completion = "我們將暫時按兵不動。我們必須讓這些重獲自由的囚犯們喘口氣。\n\n不過這裡地形並不理想，我們待會就要立即移動。", rewards = "您會收到：\n\n"}
