MultiLanguageQuestData['tw'][34427] = {title = "潛在的盟友", objective = "在卡加薩試煉場的火焰之環使用霜舞聚焦石，以釋放先知德雷克塔爾。", description = "其中一個被抓的獸人正在接受…高規格待遇，如果你能這麼說的話。其他的獸人被綁起來拷問，這個獸人則被綁在木樁上受火烤，作為俘虜者們的娛樂。\n\n使用這個符文石。它應可解決環繞在獸人身邊的火圈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "降奴者長袍降奴者外套降奴者鎖鍊護胸降奴者護胸您會收到：\n\n"}
MultiLanguageQuestData['tw'][34429] = {title = "百人斬", objective = "在卡加斯競技場中存活。", description = "要離開這個險境只有一條路，<name>，那就是直接通過那座競技場。\n\n但是，這很可能是我們的末路。", progress = nil, completion = "你還活著？很好。\n\n崩塌只能拖延他們一段時間，我們必須繼續移動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34431] = {title = "暗影之主", objective = "殺死雯歌菈、監工格朗和『墮落者』安可娃。", description = "壞獸人想抓我，但我溜了出來。我很會躲哦。\n\n臭獸人每個都壞壞，但是我記住了幾個最壞的獸人名字，免得有人剛好跑來救我。\n\n<盧卡深呼吸>\n\n雯歌菈、格朗，還有…嗯…噢！安可娃。\n\n你能不能從他們手中保護我？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34432] = {title = "影月氏族", objective = "在晦影石窟裡殺死10個影月獸人或虛無之狼。", description = "我們會保護受傷的人，而且保證不會讓卡加斯通過這些碎石堆。你先去把洞穴裡的敵人解決掉吧，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "虛無凝視者護盔虛無凝視者軟帽虛無凝視者鍊甲兜帽虛無凝視者頭罩您會收到：\n\n"}
MultiLanguageQuestData['tw'][34434] = {title = "伊芮爾", objective = "護送伊芮爾到安全的地方。", description = "請原諒我的慌張，我從來沒殺過人。\n\n我的名字叫伊芮爾，是卡拉伯爾的學生。\n\n你說你帶了一支軍隊來？聖光真是眷顧我。\n\n既然如此，我將跟隨你。請帶路，<name>。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n操作機制\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34436] = {title = "『破壞者』凱利丹", objective = "殺死『破壞者』凱利丹。", description = "耐祖奧的一位副官還活著，就在前面。出口在他後面不遠的地方。\n\n我會回頭告訴卡德加洞穴安全了。等你把凱利丹解決以後我們再會合吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34437] = {title = "恣意妄為的霜狼", objective = "到塔南森林的黑石礦場向先知德雷克塔爾回報。", description = "讓我先宰掉幾個黑石獸人...然後我就自己回到德雷克塔爾那裡。", progress = nil, completion = "請接受我的謝意，&lt;name&gt;。我們的酋長，杜洛坦，將會樂意聽到格納爾活著的消息。", rewards = "您會收到：\n\n"}
