MultiLanguageQuestData['tw'][34439] = {title = "熔爐之戰", objective = "殺死15個黑石獸人以及3個歐格隆碎戰者。", description = "我們的部隊已經全副武裝，現在是攻擊的好機會！\n\n要快、狠、準。攻擊，<name>！", progress = nil, completion = "你能到高地來真是太好了。\n\n看看那個水壩！", rewards = "您會學到：\n\n第一階天賦解鎖\n\n您還會收到：\n\n"}
