MultiLanguageQuestData['tw'][34582] = {title = "尋找據點", objective = "跟隨預言者費倫。", description = "你就是帶我孩子回家的人嗎？我一直在等你。\n\n鋼鐵部落一天比一天強大。\n\n我已經預見到慘烈的大戰，但我的預知幻象卻被遮蔽了。就好似時間重疊一般。\n\n有一件事是可以確定的，你在這裡可說至關重要。", progress = nil, completion = "這裡就可以了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34583] = {title = "為了聯盟！", objective = "插上聯盟旌旗", description = "<name>，如果不是你，我們是不可能從塔南活著回來的。很多德萊尼和聯盟的成員，都欠你一份情。\n\n在我們去黑暗之門之前，烏瑞恩國王親自下令，要我讓你主導我們在德拉諾的行動。在看過你的表現之後，我同意這是絕佳的安排。\n\n這裡就是你未來的要塞。指揮官，放置旌旗後我們就會立刻開始動工。", progress = nil, completion = "這就是德拉諾？比我想的還暗一點。不過，在蓋了暴風城之後，這個任務實在是易如反掌。\n\n好吧，那你準備開始了嗎，指揮官？", rewards = "遊俠初學者之弩卡拉伯爾步卒長矛遊俠初學者匕首卡拉伯爾巨劍遊俠初學者臂刃卡拉伯爾步卒之刃卡拉伯爾秘法師節杖卡拉伯爾占兆師釘錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][34584] = {title = "尋找木材", objective = "標記8棵樹。", description = "這附近有些樹看起來很小，工人一下子就可以把它們砍倒。\n\n我們可以把粗重的工作留給雪莉的手下去做，但如果你能先把樹木標記出來，讓他們知道從哪裡開始著手，我們的進展就會快很多。", progress = nil, completion = "太好了。\n\n這種木材不但實用，還很美觀！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34585] = {title = "震地之拳", objective = "殺死震地之拳。", description = "我收到報告，說森林裡有個大傢伙。\n\n有幾個卡拉伯爾保安官跟著到洞穴裡去了。老實說，我手下的人都不想跟那個怪物打交道。\n\n你能幫忙調查一下嗎？我敢說保安官們一定會很感激你的。", progress = nil, completion = "那個大傢伙一死，這個基地絕對更安全了。\n\n那些保安官真的對你刮目相看了。", rewards = "您會學到：\n\n技能徹底解鎖\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34586] = {title = "建造你的要塞。", objective = "建造你的要塞。", description = "這麼快就能讓這個團體緊密結合，真是讓我佩服不已，指揮官。\n\n我想現在是開始建造城牆，並在我們的基地周圍設立防線的時候了。", progress = nil, completion = "要塞開始成形了。", rewards = "您會收到：\n\n要塞爐石"}
MultiLanguageQuestData['tw'][34587] = {title = "建造兵營", objective = "找到藍圖，學會藍圖，然後使用建築繪圖桌來建造你的兵營。", description = "指揮官，我得說我們的要塞真的是一天比一天完善。\n\n現在我們手上有足夠的材料，只需找出我畫的藍圖草稿就可以開始為你建造兵營了。\n\n嗯…我把藍圖放在哪裡了？", progress = nil, completion = "建造兵營的工作進行得怎麼樣了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34589] = {title = "TEST - Quest Objective Completion Effect Not Firing", objective = nil, description = "Testing Instructions\n\ncgo 230284\n\nLoot items until objective is complete\n\nYou should see an explosion visual", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][34592] = {title = "小古羅問題", objective = "殺死8個霜火小古羅。", description = "如果到處都是小古羅在四處搞破壞，想要幫你建好這座堡壘可是難上加難。\n\n我不覺得這邊有什麼人可以料理這些巨獸，所以你可能得自個想辦法。", progress = nil, completion = "德拉諾的野獸還真兇狠。", rewards = "您會學到：\n\n第六階天賦解鎖\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34593] = {title = "取得巨魔攻擊軍令", objective = "在瑪爾戈克堡壘取得庫爾格羅許的命令和索爾戈克的命令。", description = "我的姊妹米菈娜正在崖上偵察，我則偵察下方的區域。有兩個巨魔法師正在下方作威作福。\n\n他們身上似乎有某種指令或卷軸之類的東西，能幫我們進一步了解目前的情況。\n\n收集那個情報，然後在上面的長梯跟我的姊妹碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34596] = {title = "雷格拉克的研究", objective = "阻止大博學者雷格拉克。", description = "這些巨魔過去一直使用古老的泰坦文物，來強化其中一群特殊成員，並稱之為破源者。博學者雷格拉克在此研究改良這個過程的方式。不管山崖上在進行什麼儀式，我們都要加以阻止。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "強力戈利安斬斧強力戈利安巨劍強力戈利安長弓強力戈利安匕首強力戈利安短劍強力戈利安長戟戈利安秘法師施術杖戈利安秘法師撼魂者強力戈利安碎顱錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][34597] = {title = "清除書面紀錄", objective = "在瑪爾戈克堡壘摧毀8箱巨魔研究成果。", description = "這個箱子裝滿了文件跟圖樣，看起來很怪，像是使魔法無效化的研究。\n\n最好能夠摧毀這些成果來阻礙這些研究。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34598] = {title = "失蹤的車隊", objective = "尋找遺失的貨物。", description = "我遇到了一個問題，而你看起來就像是最適合這個工作的<race>！\n\n有批貨物昨天就該送到了，但現在卻下落不明。我的存貨不多了，想請人幫我去調查到底發生了什麼事情！\n\n如果要我猜的話，應該是那些劍齒人搞的鬼。自從我們來到這裡，那些兇狠的傢伙就一直困擾著我們！\n\n動作快，到劍喉谷旁邊的道路去搜索一下！時間就是金錢啊！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
