MultiLanguageQuestData['tw'][34681] = {title = "戰略考量", objective = "和布隆‧天角交談，飛往塔拉多爾。", description = "這些鋼鐵部落的人還真有一手。\n\n他們把艦隊調頭，從格古隆德轉往塔拉多爾，我的間諜居然一無所知。對整個地區來說，塔拉多爾是交通要衝，我們不能讓他們佔領。\n\n別擔心，老闆，我們有個計畫。我們派了工頭葛羅巴什，找了很棒的地點建造崗哨，等你到達的時候應該準備得差不多了，指揮官。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34682] = {title = "行動：奇襲隊伍", objective = "搭乘塞林的直升機前往遊俠瞰臺。", description = "在戰歌氏族的攻擊之下，沒有多少人倖存下來。僅存的幾位遊俠爬上了一片可以俯看泰拉的懸崖。\n\n那些遊俠正在等你，並打算發動一場令敵人猝不及防的反擊。\n\n我的直升機已經發出巨響，上面的自動導航設定好了，可以帶你過去。我想這應該是它最後一趟飛行了。\n\n也許啦。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34683] = {title = "搶先一步", objective = "到塔拉多爾和杜洛坦交談。", description = "老闆，杜洛坦、德拉卡和加茲魯維一起出發，去探查鋼鐵部落在海岸的動靜了。\n\n他們會在西北方的峭壁上等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34684] = {title = "抢先一步", objective = "在塔拉多与守备官玛尔拉德谈一谈。指挥官，守备官玛尔拉德带着伊瑞尔和塞林·暗砧去前方追踪钢铁部落在森林里的军队了。\n\n他们已经在制定战略，阻止钢铁部落的行动。眼下就在西北边的悬崖上等着你呢。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "指挥官，守备官玛尔拉德带着伊瑞尔和塞林·暗砧去前方追踪钢铁部落在森林里的军队了。\n\n他们已经在制定战略，阻止钢铁部落的行动。眼下就在西北边的悬崖上等着你呢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34685] = {title = "火勢蔓延", objective = "在塔拉多爾的阿盧納附近尋找塑晶者貝倫。", description = "阿盧納陷入一片火海。\n\n阿拉卡從山上俯衝而下，將一切化為灰燼。德萊尼、塔巴克，甚至獸人都無一倖免，他們不在乎盟約，要的就只是把這個世界燒成灰燼。\n\n我好不容易逃了出來，但我最好的朋友，貝倫，卻留在那裡找他女兒。大家都說你是了不起的勇士。拜託，我求求你，去阿盧納找到他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34690] = {title = "刚刚开始而已", objective = "在塔拉多与伊瑞尔交谈。已经……结束了。\n\n我们应该返回你的哨站，讨论下一步行动计划。在塔拉多的各个角落都有无辜的民众身陷险境，他们需要我们的帮助。\n\n我会让卡德加为我们打开一道传送门。有话以后再慢慢聊吧。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "已经……结束了。\n\n我们应该返回你的哨站，讨论下一步行动计划。在塔拉多的各个角落都有无辜的民众身陷险境，他们需要我们的帮助。\n\n我会让卡德加为我们打开一道传送门。有话以后再慢慢聊吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34692] = {title = "德拉諾任務委派", objective = "使用指揮桌，派琪安娜‧月影去執行任務。", description = "在德拉諾要做的事情比我們能負擔的多得多，所以我們要開始委派任務了。\n\n墜星哨站有群夜精靈需要一名勇士。\n\n派琪安娜過去再好不過了。", progress = nil, completion = "這是好的開始，我們未來還會需要更多勇士來負責這些任務。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34693] = {title = "Profession Quest", objective = "建造一座专业技能建筑。", description = "我们已经清理出了面积相当大的土地，指挥官。\n\n我们应该继续强化要塞。\n\n再去找巴隆斯谈谈，他会帮你建造你选好的专业技能建筑。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34696] = {title = "聖光女士", objective = "在塔拉多爾的燃燒前線和莉雅德倫女士交談。", description = "你是<name>，對嗎？你就是這裡的負責人？我是騎士領主卓那魯斯，在此為你效力。\n\n莉雅德倫女士說西南方的奧齊頓出現了可疑的惡魔。為了不讓奧齊頓落入古爾丹之手，她特別表示需要你的協助。\n\n如果能夠盡早出發的話，我敢說她會不勝感激的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34697] = {title = "重現的傳奇", objective = "到格古隆德的石槌競技場附近找卡許德拉寇。", description = "要想訓練你的部隊作戰，最好讓他們習慣戰鬥！而且他們最好有兩下子。\n\n你聽過卡許德拉寇吧？\n\n他是個赫赫有名的霜狼戰士，想把我們獰笑骷髏的人趕盡殺絕。要不是巨魔把他抓走，他搞不好還真的這麼做了。\n\n他們把他和許多窮凶極惡的驍勇鬥士帶到了北邊的石槌競技場。\n\n要是你能去把他們放出來，他們會是理想的訓練師。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34698] = {title = "奴隸獵人", objective = "取得布羅、克雷哥和莫爾的墬飾。", description = "每當有鬥士從石槌競技場逃走，他們就會派出冷酷無情的奴隸獵人來追殺我們。\n\n我自認是不錯的戰士，數年來在競技場中掙扎求生磨練了我一身的本領。\n\n但是這些奴隸獵人用魔法的墜飾控制著奴隸。只要有這些墜飾，他們就可以追蹤到我們的位置，在我們入睡、或是放鬆警戒的時候殺掉我們。\n\n我知道我沒有資格這樣要求你，但是能夠請你幫幫忙，進入石槌拿回這些墜飾嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34699] = {title = "鬥士歸來", objective = "救出鬥士布魯多、鴉奇虛和鬥士范達姆。", description = "當我們逃離石槌競技場的時候，我們不得不留下其他的人。\n\n如果我們妄想一起救出他們而被發現，那些巨魔必定會察覺我們的目的，而他們會做的第一件事就是殺光我們的朋友。\n\n那些巨魔不認識你，這可能會給你一個機會。\n\n進入石槌競技場，找到其他的鬥士，並且將他們釋放出來。只要做到這一點，我們就會向你效忠。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "氣爆裹腕火鑄鎧甲裹腕野木牧者裹腕蔓生切除裹腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][34700] = {title = "納茲格雷爾", objective = "解救納茲格雷爾。", description = "從石槌競技場逃出來還算容易，但是我的兒子還在管理競技場的混蛋巨魔手裡。\n\n以前他們就經常拿我兒子來威脅我，強迫我在競技場上戰鬥。現在我逃出來了，他們肯定會訓練他來代替我。\n\n拜託你，救出我兒子。他們只要一看到我，就會馬上殺死他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34701] = {title = "亡靈代言人", objective = "在塔拉多爾的燃燒前線和瑪拉達爾主教交談。", description = "噢，感謝聖光，你在這裡！瑪拉達爾主教派我來找你。\n\n我們需要你的協助。奧齊頓受到了惡魔的攻擊！\n\n盡快到西南方的燃燒前線去！你是少數他信得過，又能領導防禦的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34702] = {title = "卡夫歐加", objective = "在石槌競技場內使用挑戰銅鑼並殺死奴隸管理者歐克莫克。", description = "石槌氏族不但有酋長，還有奴隸管理者。今天，我們要把他們兩個都殺了。\n\n首先是奴隸管理者歐克莫克。我在個子只有你這麼高的時候，就開始在競技場討生活，我知道什麼叫殘酷。奴隸管理者歐克莫克就是殘酷的化身。\n\n想當個真正的鬥士嗎？到石槌競技場去，在競技場中央敲響挑戰銅鑼，和奴隸管理者手下的野獸決一死戰。\n\n搞不好你會把歐克莫克惹毛，讓他親自跳下場來對付你。他要是真的下場，就把他殺了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34703] = {title = "寇加爾的斧頭", objective = "殺掉寇加爾並拿回他的斧頭，塞拉希爾。", description = "現在是我復仇的時候了！我們要殺死寇加爾，然後讓你拿走他的斧頭。\n\n打破這個簡陋的路障，沿著後面的橋樑往前走，你就會抵達酋長的寶座。\n\n你救了我們，所以讓敵人流出第一滴血的榮耀就交給你了。只要你出手，我們就會隨後加入你。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "寇加爾的力量您能選擇下列奬勵中的一個：\n\n寇加爾的殘暴寇加爾之怒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34704] = {title = "重現的傳奇", objective = "到格古隆德的石槌競技場附近找鬥士艾卡妮。", description = "這個搏擊競技場是個不錯的開始，不過我們需要訓練師，幫忙把你的部隊訓練成夠格的鬥士。\n\n倒是有人說在西邊看到過有個像是艾卡妮的德萊尼。\n\n這下有趣了，我們都以為她已經死了。她名列有史以來最強的德萊尼戰士之一，不管是什麼樣的武器，她幾乎樣樣都精通。\n\n指揮官，我們不可能找到比她更好的訓練師，我建議去把她找出來，如果那真的是她的話…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34705] = {title = "Tracking Quest - Shadowmoon Intro", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][34706] = {title = "匯集", objective = "在沃金之傲和騎士領主卓那魯斯交談。", description = "你在這裡的工作都完成了，<name>。我會留在這裡，負責清理殘餘的惡魔。\n\n你應該回你的營地，讓卓那魯斯知道我們成功了。他會把這個消息傳到艾澤拉斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34707] = {title = "匯集", objective = "在烏瑞恩堡和復仇者艾希亞交談。", description = "古爾丹和他的親信會牢牢記住這一天的。千萬不要小看我們奧奇奈。\n\n你應該讓哨站裡的復仇者艾希亞知道我們成功了。她可以把消息傳給分散各地的難民和他們的家人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34708] = {title = "Vignette: Jehil the Climber", objective = "消灭$1oa个鬣蜥人卵簇、$2oa个冰铸噬铁者和巢母里戈艾克。鬣蜥人是危险的敌人，尤其是在他们人多势众的时候，更别说我们身边还跟着一个没用的瞎眼老萨满。\n\n幸运的是，他们都很短命。而不幸的是，他们繁衍很快，生长更快。\n\n如果我们想要完成这个任务，就得找到巢母。消灭她和她的卵，就能令鬣蜥人的攻势放缓。去检查一下熔炉之门附近的洞穴吧，我会尽量不让他们发现德雷克塔尔的气味。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "鬣蜥人是危险的敌人，尤其是在他们人多势众的时候，更别说我们身边还跟着一个没用的瞎眼老萨满。\n\n幸运的是，他们都很短命。而不幸的是，他们繁衍很快，生长更快。\n\n如果我们想要完成这个任务，就得找到巢母。消灭她和她的卵，就能令鬣蜥人的攻势放缓。去检查一下熔炉之门附近的洞穴吧，我会尽量不让他们发现德雷克塔尔的气味。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34709] = {title = "每分力都有用", objective = "在塔拉多爾的佐魯礦坑和艾吉菈交談。", description = "西邊的佐魯礦坑需要你的援助！\n\n我的好朋友艾吉菈要我來尋求協助。瑪拉達爾主教已經派出手邊所有的復仇者，但這還不夠！\n\n你願意前往礦坑並協助我們嗎？我們需要礦坑裡的水晶，才能建立防禦，就像你在燃燒前線看到的那種水晶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34710] = {title = "每分力都有用", objective = "在塔拉多爾的佐魯礦坑和艾吉菈交談。", description = "曼杜爾‧天喚者被派到佐魯礦坑進行一項很敏感的任務，已經隔了好幾個小時，他卻還沒回來。\n\n我想他應該需要協助。當你找到他的時候，我會要他向你簡報目前狀況，不過他有可能困在礦坑深處。\n\n你應該向艾吉菈報到，那是一位當地的德萊尼礦工，同意協助我們以換取我方的力量，讓她重掌礦坑的控制權。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34711] = {title = "值得慶祝的動機", objective = "到烏瑞恩堡和博學者塞瑞娜交談。", description = "我們回到你的哨站吧。在那邊慶祝比較好，也比較安全。\n\n我用傳送術送你一起過去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n完整的哨站建造指南"}
MultiLanguageQuestData['tw'][34712] = {title = "值得慶祝的動機", objective = "在沃金之傲和博學者克雷拉斯交談。", description = "我真的覺得這裡不是個說話的好地方。\n\n我們回你的哨站去吧？在那裡慶祝比較好。\n\n我用傳送術送你一起過去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n完整的哨站建造指南"}
