MultiLanguageQuestData['tw'][34729] = {title = "奈許菈的血誓", objective = "接受大劍師奈許菈的血誓", description = "你幫了我很大的忙，這把劍說是我鑄的，其實也等於你鑄的。\n\n我謹此立下血誓，貢獻我對鑄劍和採礦的知識，為你效命。\n\n你接受嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：武器鍛造師奈許菈\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][34730] = {title = "洛卡拉的血誓", objective = "接受剑圣纳什拉的血誓。", description = "你帮了我一个大忙。这柄利刃既是你的也是我的。\n\n我要为你送上这个血誓：我愿助你一臂之力，把我掌握的利刃和采矿方面的知识都贡献给你的军队。\n\n你愿意接受吗？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
