MultiLanguageQuestData['tw'][34814] = {title = "相交而相識", objective = "跟隨大法師卡德加並在贊格拉和博學者克雷拉斯交談。", description = "真高興能見到對秘法法術這麼有興趣的人，你知道的。恕我直言，這樣的人近來真是越來越少了！\n\n不巧的是，我得去找寇達娜處理一件重要的事情，但我們的運氣不錯！我有個來自祈倫托的好朋友願意幫你的忙，把秘法聖所連上地脈網路。\n\n他就在我的塔裡等著。我們現在就過去吧，我介紹你們認識一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34815] = {title = "相交而相識", objective = "跟隨大法師卡德加並在贊格拉和博學者塞瑞娜交談。", description = "真高興能見到對秘法法術這麼有興趣的人，你知道的。恕我直言，這樣的人近來真是越來越少了！\n\n不巧的是，我得去找寇達娜處理一件重要的事情，但我們的運氣不錯！我有個來自祈倫托的好朋友願意幫你的忙，把秘法聖所連上地脈網路。\n\n她就在我的塔裡等著。我們現在就過去吧，我介紹你們認識一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
