MultiLanguageQuestData['tw'][34818] = {title = "他們叫他『劍刃』蘭崔索", objective = "在哈瓦洛尋找『劍刃』蘭崔索。", description = "戰歌氏族洗劫你的車隊後，要塞藍圖就被送到燃刃村了。沒有藍圖的話，我就無法建造你要的建築了。\n\n據說有一位被氏族放逐多年的年輕大劍師，人稱『劍刃』蘭崔索。\n\n我們的斥候最近見到他回到哈瓦洛，向大劍師的首領之位做出挑戰。可惜他失敗被囚。\n\n或許他仍然活著，說不定還可以協助你找回藍圖？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34819] = {title = "香甜果肉", objective = "收集15顆納葛蘭櫻桃。", description = "喔，不！牠們是吃素的。\n\n伊萊克需要吃水果，大量的水果。這裡的樹下全部都是櫻桃。\n\n你應該不會介意幫我拿一點吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34820] = {title = "失蹤的伐木工", objective = "查明雪莉和失蹤的伐木工出了什麼事。", description = "雪莉和她的組員還沒從幽蔭林地回來。\n\n已經好幾天了…我希望一切平安。", progress = nil, completion = "這是雪莉和伐木工帶到幽蔭林地的其中一頭運貨馱騾。", rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34821] = {title = "召唤卡德加", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][34822] = {title = "我們要什麼", objective = "收集10箱苦工船打撈物。", description = "我聽說你們劫持一艘船逃出塔南，還失事了。\n\n就像我老爸經常掛在嘴上的：一個人失事的地方，就是另一個哥布林的工坊。\n\n你應該前往要塞西邊的海岸，尋找可以回收的材料。噢，還有，呃…你應該要小心點。我聽說那個區域有巨魔劫掠者出沒。", progress = "回收行動進行得怎麼樣了？", completion = "嘿…這些回收品很棒啊。你要怎麼罵鋼鐵部落是一回事，但他們手中的原料還真不是蓋的。", rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34823] = {title = "歐格隆還活著？", objective = "殺死戈魯格。", description = "指揮官，我們的霜狼盟友回報，在一隻歐格隆的帶領之下，劍刃巨魔已經在我們的西邊建立了一座前哨站。\n\n我有聽過歐格隆的傳說，但是從來沒有見過。他們是兇狠的東西，最好永遠被忘掉。聽說在部落一開始組成時，大部份都被殺掉了。雖然沒有什麼腦袋，但是他們用了暴力、兇狠和貪婪來彌補。\n\n我建議趕快解決掉這頭怪物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34824] = {title = "我們有什麼", objective = "叫史卡吉特讓苦工開工，並找到資深二級苦力。", description = "每一座要塞都少不了三個要素。\n\n第一：苦工！去找史卡吉特，叫他把我們的苦工帶回來工作。\n\n第二：建材。我讓苦工把你不在時所生產的資源都存放在一個地方，你應該去查看一下。\n\n還有第三：健壯又有經驗的工人！在要塞裡蓋建築物需要一點時間，但如果能雇用史卡吉特剛晉升的資深二級苦力，你第一棟建築物的進度就能加快很多。去找他，跟他說是我派你去的。", progress = nil, completion = "對，就是這些玩意。木材、石頭、苦工，更多苦工。就像我們要幫你建造要塞之類的東西似的。", rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34825] = {title = "Vignette: Gruuk", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34826] = {title = "敵人的朋友", objective = "殺死15名哈瓦洛的燃刃成員。", description = "哈瓦洛是燃刃氏族祖靈的家鄉。基於他們是堅實的盟友，因此戰歌允諾讓大劍師們留在納葛蘭。\n\n如果讓燃刃氏族先行攻擊，勇猛如我們也毫無勝算。率先發難才是明智的選擇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34827] = {title = "魔爪祭司末裔", objective = "到暗影林地的艾夏歐小屋，飲用暗影藥劑。", description = "魔爪祭司無聲無息的躲在我們之間，把守著鷹王回歸的儀式。\n\n你從司凱堤斯取回的擁護宣言裡，揭露其中兩位就住在暗影林地的北邊。但是獸人已經推進到這個區域，而擁護者的光束武器讓維爾阿卡拉茲成為一道冒煙的裂隙。\n\n如你所見，我的人民被四面八方的敵人團團包圍。\n\n魔爪祭司艾夏歐還活著，躲了起來。去他的小屋附近喝下這瓶藥劑，窺視暗影並和他聯繫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34828] = {title = "艾夏歐的寶珠", objective = "從刺疤營地取回艾夏歐的寶珠。", description = "擁護者來找我，不過我先躲起來了。我在暗影之中看著他們洗劫我的小屋。\n\n接著破碎之手獸人出現，那些擁護者像晚餐的雞鴨一樣被大卸八塊。看來這段時間所有人都在找我們。\n\n其中一名獸人帶著我的占卜之球逃走，我必須拿回來，因為沒有占卜之球，我對伊斯卡就一點用處也沒有。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34829] = {title = "新鄰居", objective = "在刺疤營地殺掉15名破碎之手獸人。", description = "破碎之手氏族是由四處流浪的獸人所組成，這些好戰份子會自殘軀體，也許是作為團結的象徵，或者只是單純享受痛苦。\n\n這不重要。重要的是他們在擴張勢力範圍，殘殺進入他們視線範圍的任何人。\n\n一定要解決他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "崖甲束腰影幕之索鴉鍊腰帶天歌者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][34830] = {title = "帷幕背後", objective = "在維爾阿卡拉茲札列克的小屋飲用極效暗影藥劑。", description = "就在獸人攻進來沒多久，從擎天峰射出一道光線，將維爾阿卡拉茲毀壞殆盡。\n\n<艾夏歐觀察著占卜之球，眼神逐漸迷離。>\n\n他們似乎錯失了真正的目標。札列克仍然活著，躲在暗影領域中。\n\n另外…還有一個人，那個使用我占卜之球的獸人刺客。\n\n拿著這瓶藥劑，到維爾阿卡拉茲喝下它，然後找出札列克。\n\n喔，你要小心，它的效力比上次還強一點。你等等就知道了…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
