MultiLanguageQuestData['tw'][34950] = {title = "毀滅巨砲", objective = "消滅毀滅巨砲。", description = "一群鋼鐵部落獸人以驚人的速度奪取了這附近的一個重要的戰略據點。\n\n一具被稱為毀滅巨砲的戰車是他們得勝的大功臣，在指揮部隊前往杜瑞與鋼鐵部落交戰之前，我們必須先消滅那輛裝甲車。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34951] = {title = "他們叫他『劍刃』蘭崔索", objective = "在哈瓦洛尋找『劍刃』蘭崔索。", description = "哈瓦洛的燃刃氏族正在提供戰歌氏族源源不絕的支援兵力及武器。我們絕不能讓他們稱心如意。\n\n我聽說有一位名叫『劍刃』蘭崔索，被燃刃放逐多年的大劍師。\n\n我的遊俠日前目擊他已返回哈瓦洛，想挑戰大劍師首領們。可惜他寡不敵眾，最後被囚禁起來。\n\n或許他仍然活著，說不定還可以協助你對付燃刃？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34952] = {title = "敵人的朋友", objective = "殺死15名哈瓦洛的燃刃成員。", description = "哈瓦洛是燃刃氏族祖靈的家鄉。基於他們是堅實的盟友，因此在其他氏族被迫離開時，戰歌仍允諾讓燃刃的大劍師以及薩滿們留在納葛蘭。\n\n廢話連篇。\n\n我說啊，如果他們是我敵人的朋友，那也就是我的敵人了，我只需知道這件事就好！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34953] = {title = "燃刃之血", objective = "殺死15名哈瓦洛的燃刃成員。", description = "哈瓦洛是我燃刃氏族祖靈的家鄉。在新酋長與其家族掌握政權後，身為混血的我就被流放異鄉。\n\n我要伸張正義。\n\n我想你大概不會介意一路殺進去，雖然你可能別無選擇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34954] = {title = "劍刃本身", objective = "從講師路科身上取回蘭崔索之刃。", description = "當他們用鐵鍊銬住我時，燃刃講師『銳敏之眼』路科拿走了我的劍。他是個重榮耀的獸人，可惜完全不會教學生。\n\n我要拿回我的劍，<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34955] = {title = "奪回榮耀", objective = "在一個燃刃藏寶箱中找出大劍師的旌旗。", description = "劍並不是大劍師唯一的重要物品。\n\n一旦他通過宗師會所的考驗，大劍師便具備佩戴燃刃旌旗的資格。\n\n我重返氏族的請求被當成耳邊風，這項榮耀自然也被剝奪了。\n\n我的旌旗一定還放在哈瓦洛某處。如果他們沒燒掉的話，就一定是給了其他年輕的大劍師了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "乘獸者手套平原雷鳴護手塑風者手套草原風暴護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][34956] = {title = "洞中一聚", objective = "到宗師會所與『劍刃』蘭崔索碰面。", description = "是時候了，<class>。跟首領們決一死戰吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34957] = {title = "首領的挑戰", objective = "在燃刃試煉中比武取勝。", description = "該是挑戰燃刃首領的時候了。\n\n到洞穴深處的試煉場，首領們會在試煉場上方觀看。\n\n走到場中央拔劍，向他們挑戰。我的氏族重視榮耀勝過一切，一定會尊重你比武審判的要求。\n\n勝利的話，你將可以活著帶你的藍圖離開，或是光榮戰死。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "平原雷鳴束腰塑風者之索草原風暴腰帶乘獸者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][34958] = {title = "碎界者之影", objective = "從黑石礦場的黑石獸人身上取得碎界者結構圖。", description = "看來我們馬上就要遇到另一個難題：他們稱之為鋼鐵碎界者的超巨型坦克，現在正朝黑暗之門前進。\n\n這龐然大物應該是黑石機械工的傑作。如果我能弄到關於它運作方式的文件，我就可以弄懂如何讓它失靈。那些機械工和工人身上應該有說明文件，對吧？", progress = "運氣如何？", completion = "嗯…是的…夠簡單了。\n\n&lt;矮人對圖紙翻了又翻，似乎忘了你的存在。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34959] = {title = "毀滅巨砲", objective = "消滅毀滅巨砲。", description = "鋼鐵部落毫不留情地攻下了一個和平的德萊尼前哨站。\n\n他們使用了一台被稱作毀滅巨砲的機器，只花了幾分鐘就剷平整座城鎮。\n\n毀掉它。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34960] = {title = "大地之禮", objective = "收集30份冰凍的植物物質。", description = "冰顫山溝的冰藤蔓非常耐寒，將它們做為建造要塞的材料應該非常有用。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][34962] = {title = "卡德加的計畫", objective = "在撒塔斯之門附近與卡德加交談。", description = "多虧你，我們終於把鋼鐵部落逼入了死角。\n\n差不多是時候進入撒塔斯城，把他們一舉殲滅了。\n\n但首先，我們要和卡德加還有一些新盟友碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34963] = {title = "卡德加的計畫", objective = "在撒塔斯之門附近與卡德加交談。", description = "撒塔斯絕對不能落入鋼鐵部落手裡，浴血奮戰的時候到了。\n\n我們會告訴卡德加我們已經準備好進城，並奪回屬於我們的一切。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34964] = {title = "晉見先知", objective = "到元素王座找先知德雷克塔爾。", description = "你需要去元素王座一趟，<name>。\n\n先知德雷克塔爾在風中聽到怒靈的召喚，已經啟程去與元素對談。\n\n先知已經傳話，請你到元素王座去找他。\n\n去吧，去看看元素找你們有什麼要事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34965] = {title = "王座的召喚", objective = "與元素王座的怒靈們談話。", description = "我抵達納葛蘭不久後，便在風中聽到卡蘭崔歐斯召喚我的聲音。\n\n能獲得元素王座的召見，深感榮幸，但想到這件事一定極為重要，心情也跟著沉重了起來。\n\n一股令人惶惶不安的氣息圍繞著我們，圍繞著所有的生物…包覆一切…令人窒息…\n\n來吧，該是與怒靈溝通，助他們一臂之力的時候了。一道無形的陰影正籠罩著這座山谷，或許只有我們才有辦法使之消散。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
