MultiLanguageQuestData['tw'][34994] = {title = "青春永駐", objective = "幫比吉爾尋找嫩草根。", description = "在這裡浪費時間根本於事無補。\n\n我必須想辦法彌補我的損失。\n\n那些女德萊尼很在意頭上的角好不好看。\n\n我聽過有人講到某種刃月茂林裡的植物草根，據說可以減緩犄角老化還是什麼的。\n\n我敢說她們一定願意高價收購這種草根。\n\n要是你能幫我弄點貨來，錢我會分你一份的。", progress = "你有找到嫩草根嗎？", completion = "嗯…我要怎麼打包？\n\n有了！\n\n&lt;比吉爾在一張標籤上寫下「嫩草根」，然後把標籤貼在一瓶奎蛇油上。&gt;\n\n&lt; 他把嫩草根丟進身後的草叢裡。&gt;\n\n就是這樣！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34995] = {title = "痛擊波塔尼", objective = "殺死5名波塔尼。", description = "基德溫好多了。謝謝你，<name>。\n\n我不敢相信德萊尼竟然跟這些可怕的魔物比鄰而居這麼久。\n\n或許我們應該教訓這些「獸類」招惹艾澤拉斯人會有什麼下場。", progress = nil, completion = "就是這樣！做得好，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34996] = {title = "腐化的河獸", objective = "殺死5個茂林魔陀羅。", description = "波塔尼使用某種怪異的食肉植物感染當地的河獸。\n\n我擔心這場感染最後會擴散到族人身上。\n\n如果你見到任何被感染的河獸，在牠們殺掉你之前，趕緊消滅掉在牠們體內繁衍生長的奇怪植物。", progress = nil, completion = "這件事真是讓人不安。真沒想到，感染散播得如此快速。", rewards = "刃月護腿刃月長褲刃月鍊甲護腿刃月鎧甲腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][34997] = {title = "安眠花", objective = "把收集到的小石頭砸向安眠花。", description = "嗯？…老天，我好像又睡著了。\n\n這些安眠花真是麻煩。前一秒我還在跟波塔尼搏鬥，下一秒卻夢到我是隻跟河獸跳舞的伊萊克。\n\n*呵欠*我們真的應該處理一下這些安眠花*呵欠*…呼嚕嚕嚕嚕…\n\n<你從睡著的德萊尼身邊抓了一把小石頭。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34998] = {title = "鴉爪崗哨", objective = "把安祖之眼帶給鴉爪崗哨的爪衛庫瑞克。與天爪莫沙爾交談，請他載你一程。", description = "現在你一定在想這詛咒到底是怎麼回事。是什麼讓偉大的阿拉卡畸形至此？\n\n<瑞薩德抬起一隻扭曲的手劃過臉上雜亂的羽毛。>\n\n有隻烏鴉已經備妥，正等著載你飛往鴉爪崗哨。在那你應該就能了解這個詛咒的起源。\n\n把安祖之眼給爪衛庫瑞克看，他會指引你接下來該做什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][34999] = {title = "不滅的憎恨", objective = "在塞司克谷地收集15滴塞司的凝結之血。", description = "塞司神死去時所流的血液，遺留在這兒的池子裡。血中還殘留祂對安祖與魯克馬爾的憎恨。\n\n祂的憎恨是如此強烈，以致於從二神殺死塞司迄今這麼多年，血液竟然仍有生命力。\n\n我需要這些邪惡生物賴以維生的凝血。\n\n擁護者最懼怕的就是詛咒的力量，說不定我們能用它來對付他們？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "崖甲戰靴影幕足靴鴉鍊脛甲天歌者長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][35000] = {title = "從天空放逐", objective = "在8個受詛咒的阿拉卡身上使用安祖之眼。", description = "數個世紀以來，擁護者一直將敵人放逐至谷地去。\n\n塞司臨死前的詛咒恨意充滿了整個池區，讓無盡的黑暗與痛苦籠罩著阿拉卡族人，讓他們心智遲緩、軀體發臭、羽翼萎縮。\n\n大多數阿拉卡人受到詛咒後不久不是死去便是陷入瘋狂，只有身心最強健的族人活了下來，將他們找出來，然後用這顆安祖之眼讓他們恢復心智。\n\n小心，塞司的信奉者也想將這些生還者納入自己旗下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35001] = {title = "烏鴉神的凝視", objective = "在4個塞司克風蛇巢穴上使用安祖之眼。", description = "塞司克正在用塞司的血與骨來培養邪惡風蛇。靠著這些生物，他們會撕裂天空。\n\n這些巢穴受到強大魔法的保護，但是安祖的目光應該可以輕易穿透。\n\n讓我們作個友善的拜訪，然後把它們統統摧毀！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35002] = {title = "塞司之子", objective = "收集6個風蛇之翼。", description = "多年來，沒人能與安祖交流。祂跟泰洛克一樣，就這樣躲藏在暗影之中消失了。\n\n如果我們想引誘祂現身，就必須獻上祭品。\n\n塞司奪走我們在天空翱翔的能力，那就摘下牠子民的翅膀當作祭品吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35003] = {title = "中斷儀式", objective = "踐踏三個塞司克儀式法陣來破壞它們。", description = "我無法破解這道詛咒，因此長久以來一直在黑暗中休養生息。\n\n塞司克人想利用黑暗儀式讓我回來，使我臣服於塞司的意志。如果他們成功了，塞司會命令我以黑暗帷幕遮蔽天際，以其之血清洗整個世界。\n\n去中斷他們的儀式，這樣我才能重獲自由。如此我們就能聯手，讓塞司復活的計畫徹底失敗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35004] = {title = "祀奉一個已死的神", objective = "在塞司克谷地殺掉6個塞司克預言者和6個塞司克受選者。", description = "就算在死後，塞司的影響力也不會消失。塞司克神教便是因此而生，由偽王所創立，供奉一個早已死去的神。\n\n讓他們的先知沉默，因為這些先知口中的未來，只是個死水成海、黑疫蔽空的世界。\n\n打敗他們所選中的勇士，因為他們所謂的信念，不過是個謊言。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "谷地鮮血披氅谷地鮮血巨披風谷地鮮血披風谷地鮮血鱗片披風谷地鮮血披巾您會收到：\n\n"}
MultiLanguageQuestData['tw'][35005] = {title = "準備戰鬥", objective = "取得30件黑石武器。", description = "這裡已經沒有地方躲了。我們必須不斷移動，要這樣的話，就得直取鋼鐵部落的核心。\n\n該是讓這群烏合之眾成長為一支軍隊的時候了。您會學到：\n\n", progress = nil, completion = nil, rewards = "採石者肩甲採石者重肩甲採石者披肩採石者肩鎧您會學到：\n\n冷卻時間\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35006] = {title = "麻痺劇毒", objective = "解救失蹤的旅人。", description = "商隊裡還有一些人也失蹤了。\n\n我猜他們可能被波塔尼抓進刃月茂林了。\n\n你必須解救他們，<name>。你是我們唯一的希望。\n\n來，拿點我剛做好的萬靈藥，會派上用場的。", progress = nil, completion = "我永遠都無法回報你今天的義舉，&lt;name&gt;。\n\n我真的欠你太多了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35007] = {title = "與祭儀師會合", objective = "在鴉痕與鴉語者瑟卡拉交談。", description = "我們敬愛的弟兄瑟卡拉前往鴉痕，帶領一些鴉群成員進行偉大的淨化儀式。\n\n過去一天，還沒有人回來裝運補給品，我想應該是在祈禱中吧。\n\n我想去檢查他的狀況，但我必須確定抄寫員沒把我最新的證道詞寫錯。你能幫我這個忙嗎？我馬上就會過去，大概再…唉，誰知道呢…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35008] = {title = "UNUSED", objective = "[PH] asdf[PH] Now that we're somewhat safer and the texts are returned go report back to the High Ravencaller. We will continue our prayers here.您會收到：\n\n完成任務後，你將獲得：\n\n", description = "[PH] Now that we're somewhat safer and the texts are returned go report back to the High Ravencaller. We will continue our prayers here.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35009] = {title = "召喚鴉母", objective = "協助高階鴉語者科里卡進行召喚儀式。", description = "現在召喚鴉母回巢儀式所需的物品都已具備。\n\n你已經通過我們給予你的所有考驗，有資格與我們一同參與儀式。\n\n很快地鴉母本人就將在我們眼前現身！喔，我的羽毛都興奮得顫動！\n\n當你準備好時，再次與我談話。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35010] = {title = "高階鴉語者", objective = "前往高階鴉語者科里卡處", description = "是的，我就知道你夠資格！\n\n信仰之書記載著，當危機來臨時，我們的信心將會受到極大的考驗，但只要保持對鴉母的信仰，一切都會迎刃而解！\n\n來吧，來吧，我們得到高階鴉語者那裡去！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35011] = {title = "偽鷹王", objective = "從鷹王伊奇斯身上取得磨損的手鐲。", description = "伊奇斯原本是一位在擁護者中備受尊敬的賢者，但是他為了追尋泰洛克隕落的真相而落得遭受放逐的下場。\n\n伊奇斯對泰洛克的事蹟徹底著魔，甚至宣稱自己是這位古老英雄轉世。\n\n他指揮塞司克，允諾在新的黑暗時代會賦予無法言喻的力量。\n\n你必須明白：伊奇斯絕非鷹王。殺掉那個有妄想症的蠢蛋吧，然後在他的身上找找看，有沒有什麼有用的東西。大家都知道，他非常喜歡收集強大的飾品。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35012] = {title = "塞司，死去的神", objective = "在橫斷峰協助安祖擊敗塞司。", description = "時間到了，該為塞司的生命畫下句點了。他之前是死在我手中，有你的幫助，我可以再次殺死他。\n\n做好準備，那些教徒可不會乖乖站在那邊任我們踐踏他們的神祇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "崖甲胸鎧鴉鍊外衣天歌者外衣影幕長袍您會收到：\n\n"}
MultiLanguageQuestData['tw'][35013] = {title = "莉斯克的禮物", objective = "把磨損的手鐲帶往莉斯克之眠。", description = "<庫瑞克瞇眼看著爪子上的手鐲，並且緩緩地轉著。>\n\n這裡面有一段銘文寫著：\n\n「致我的父親，願魯克馬爾能照亮你的道路。敬愛您的莉斯克。」\n\n這不可能…這居然是泰洛克的手鐲！這是他女兒獻給他的禮物，而他長年戴著，直到…\n\n好吧，我們最好把它還回去。\n\n泰洛克在鴉爪崗哨附近替莉斯克作了一座紀念碑，這手鐲應當屬於那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35014] = {title = "刃月茂林", objective = "在刃月茂林裡與遊俠阿爾菲奧碰面。", description = "我們沒有選擇了。\n\n我要深入林中，看看究竟發生什麼事情。我們在林中碰面吧。\n\n祝你好運，<class>。", progress = nil, completion = "很好，你來了。我需要你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35015] = {title = "孕育中的傑那索", objective = "殺掉傑那索。", description = "情況不妙。有隻傑那索竟然在刃月茂林生長。\n\n這是三百多年來，首宗傑那索誕生在德拉諾的案例。\n\n難怪波塔尼最近行為如此瘋狂。它們是為了餵養那頭怪物，所以才將屍體帶回來。\n\n我們必須在它長大前殺掉它。一旦發育完全，就沒有辦法阻止它作亂。", progress = nil, completion = "真驚險。\n\n如果那頭傑那索再大一點，就必須帶支軍隊來了。\n\n感謝你的大力協助。", rewards = "遊俠初學者護手卡拉伯爾爭鬥者手套卡拉伯爾初學者護手卡拉伯爾賢者手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][35016] = {title = "基礎奪顱", objective = "從5名死亡的奪顱者身上取得頭顱。", description = "我的獵人們都死了，你現在就是我的狩獵隊。\n\n找到他們的屍體，將他們的顱骨拿回來。我將選擇哪些將獲得榮耀，哪些將隨手拋棄。這是我們的傳統。\n\n我會繼續往前走，查看這裡是否有其他的頭顱。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35017] = {title = "奪顱者的復仇", objective = "殺死7個真菌潛伏者。", description = "其他人…不是死了就是迷失方向了。我也遭到攻擊，但我太強了。我決定殺一個是一個，直到牠們擊碎我的身體為止。我殺牠們還殺得不夠，$p！還不夠！去吧，殺掉更多的潛伏者，然後告訴我的狩獵首領我死的時候並不是一個人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
