MultiLanguageQuestData['tw'][35077] = {title = "消滅真菌", objective = "使用QR58烈焰衝擊槍摧毀20個孢子膿包。", description = "你看過水裡的真菌了嗎？它長的比小安戈洛暴掠龍還快。如果我們不趕快控制它的生長，零件廠會跟上一個村落一樣化為廢墟。\n\n奎克索叔叔以前跟我說過，紅色的真菌會促進生長，所以一定要燒掉才行。\n\n你應該去拿把烈焰衝擊槍，幫我們處理掉暗處的那些孢子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "風險投資公司「防火」爆烈鎧甲風險投資公司「防火」鎖甲風險投資公司「防火」外套風險投資公司「防火」長袍您會收到：\n\n"}
MultiLanguageQuestData['tw'][35079] = {title = "孢子再見", objective = "啟動6具孢子滅擊砲。", description = "緊急狀況！\n\n一群孢子飄浮者不斷騷擾沿岸，搗毀了我們的孢子滅擊砲，\n\n我們已經毫無防備之力了！如果我們不把這些砲塔修好，討厭的孢子就會直接飄進零件廠裡，然後在我們面前化為另一個急嘯角！\n\n我們必須快點過去，以人工方式啟動才行。\n\n你怎麼說？能幫忙嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35080] = {title = "母礦號", objective = "到母礦號的殘骸與金茲‧急嘯會合。", description = "喂，我們碰上大麻煩了！我們的飛艇「母礦號」墜毀在南方的山區裡！\n\n它應該只是在執行偵察任務而已，怎麼會發生這種事？\n\n我們必須快點趕過去，我需要你來幫我。\n\n你願意來嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35081] = {title = "開工前先清場", objective = "殺掉8隻緋翼黃蜂。", description = "情況是這樣的。\n\n我們必須盡快開始搶救物資，但飛艇剛好墜落在黃蜂巢中間。\n\n那裡到處都是可怕的蟲子，除非把蟲子清掉，否則我沒辦法叫我的人來開工。\n\n盡量殺掉那邊的黃蜂，我會分你一點所得的物資。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35082] = {title = "船員團聚", objective = "救活6個受傷的船員。", description = "喔，山坡上到處都是殘骸！如果我們不盡快行動，生還者就活不久了。他們現在就需要治療！\n\n來，拿著我的繃帶，快點去幫他們包紮吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35083] = {title = "打斷儀式", objective = "摧毀儀式圖騰。", description = "戰歌不再與元素同在。他們濫用元素的力量來引導虛無的黑暗。\n\n我不會忍受這樣的儀式繼續下去。找到戰歌氏族用來引導虛無的儀式圖騰，並且將之摧毀。\n\n元素的贈禮不是給予獸人來讓他們污損及玩弄用的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35084] = {title = "停止召喚", objective = "殺死庫爾拉斯和10個戰歌薩滿。", description = "戰歌氏族為了主宰一切而向黑暗的虛無索求力量。黑暗薩滿信仰既可鄙又危險，濫用了我賦予它們的元素贈禮。\n\n有一個戰歌氏族的人呼喚虛無的聲音最大，一個叫庫爾拉斯的薩滿長老。殺死他和其他的黑暗薩滿。\n\n我不會允許戰歌濫用元素褻瀆傳統。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "扭曲元素焦點庫爾拉斯的詛咒圖騰虛無之觸圖騰您會收到：\n\n"}
MultiLanguageQuestData['tw'][35085] = {title = "穿越虛空", objective = "使用虛空信標前往扭曲虛空。", description = "虛空儀式被打斷了，但虛空信標仍然充滿能量地發光。\n\n這一定代表信標的能量是由扭曲虛空本身內部所提供！\n\n我們必須摧毀虛空的連結！只有一個辦法可以做到：你必須殺死維持連結我們世界的虛無生物。\n\n把你的手放在信標上前往扭曲虛空，在你抵達另一邊時，使用薩滿石跟我聯繫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35086] = {title = "虛無之界", objective = "消滅10個虛無恐獸及15根虛無觸鬚。", description = "虛無之界的生物正躲在扭曲虛空的帷幕之下進軍歐夏剛。巨大的虛無正在聖山中擴大，吸引它們如飛蛾撲火般前來。\n\n它們一波接著一波地向聖山前行，自己向英瓦里德斯獻祭。虛無領主英瓦里德斯不能再繼續享用這些虛無生物了，否則他將勢不可當。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35087] = {title = "虛空逼近", objective = "摧毀6個虛無傳送門。", description = "藉由連接扭曲虛空，戰歌氏族造成了他們自己也沒預料的漣漪效應。\n\n看看你的四周，無數的傳送門即將開啟，顯示出扭曲虛空想要連結到德拉諾。\n\n如果這些傳送門成功開啟，所有惡魔及虛空生物將可不受阻礙地進入山谷作惡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35088] = {title = "虛無暗影", objective = "召喚並擊敗英瓦里德斯。", description = "是時候面對那個虛無領主了。英瓦里德斯正在持續變強，所以如果你想要擊敗那個怪物，就必須快點行動。\n\n戰歌氏族每一個舉行儀式的地點都有一個虛無水晶，這些水晶用來引導扭曲虛空的能量。\n\n若干擾了水晶，英瓦里德斯就會在下方感應到你的存在。\n\n做好準備，水晶被干擾後，英瓦里德斯將會立刻追殺你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "乘獸者護手平原雷鳴手甲塑風者護手草原風暴之握您會收到：\n\n"}
MultiLanguageQuestData['tw'][35089] = {title = "撈點油水", objective = "收集4份烈性油。", description = "我們只能靠飛行器離開這裡，但是油箱裡頭一滴油也不剩！\n\n我們就在油井隔壁，不過油井到處都是殭屍，看來是沒辦法進行燃料精煉了。\n\n油坑那倒是有一群瀝油生物，這些生物由高性能油料所組成，可以直接倒進油箱使用。帶一些油料回來給我，我們便向離開這裡又邁進了一步。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35090] = {title = "正確的零件", objective = "使用G-14破壞者火箭從損壞的伐木機取回可用的齒輪。", description = "奎克索叔叔是個硬漢，但是他腿斷了，沒辦法靠雙腿行動。\n\n他從艾澤拉斯帶了一架飛行器，我們能搭上飛行器離開這裡。問題是，飛行器的引擎壞了。\n\n我需要一些零件來修理飛行器。鎮外的碎木機應該有我們需要的零件，但已經生鏽到無法發動。我們沒時間將它們拆開，你就拿著這個火箭發射器去直接炸開吧，把沒炸爛的零件帶給我就好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "抗真菌鎧甲長靴抗真菌軟靴抗真菌鎖鏈長靴抗真菌工作靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][35091] = {title = "孢子浩劫", objective = "在急嘯角殺死6個孢子跛行者。", description = "那些東西簡直噁心透頂、讓人火冒三丈！\n\n我說得是遊蕩在急嘯角的孢子生物。\n\n趁我修理機器的時候，你要不要到外頭去處理掉一些孢子生物？那玩意兒少一點，我心裡就舒坦一點。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35092] = {title = "黑暗之门的能量源", objective = "在黑暗之门下方与古尔丹交谈。光有法力炸弹还是不够。这始终都是有风险的。\n\n真是太不走运了。\n\n这座门下面关着的那个兽人古尔丹，他声称能够关闭这道传送门。想办法下去找他，不惜一切代价关闭传送门。\n\n<大法师盯着你。>\n\n不惜一切代价。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "光有法力炸弹还是不够。这始终都是有风险的。\n\n真是太不走运了。\n\n这座门下面关着的那个兽人古尔丹，他声称能够关闭这道传送门。想办法下去找他，不惜一切代价关闭传送门。\n\n<大法师盯着你。>\n\n不惜一切代价。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35093] = {title = "月亮的陰暗面", objective = "找到耐祖奧。", description = "伊芮爾與我已經找到了耐祖奧的下落。他正要前往那座俯瞰苦怨堡壘，位於最高點的祭壇，與葛羅瑪許‧地獄吼會面。\n\n和我們在那碰面，我們一定要阻止他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遊俠初學者肩甲卡拉伯爾爭鬥者肩甲卡拉伯爾初學者護肩卡拉伯爾賢者披肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][35094] = {title = "恶魔的交易", objective = "回黑暗之门的地上部分向大法师卡德加报告。<古尔丹逃走后，黑暗之门失去了效用，艾泽拉斯所面临的威胁暂时被遏制了。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<古尔丹逃走后，黑暗之门失去了效用，艾泽拉斯所面临的威胁暂时被遏制了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35095] = {title = "沿著河畔", objective = "在河畔哨站與杜洛坦交談。", description = "杜洛坦已將多數兵力帶往西邊，在天歌河畔建立前進基地。\n\n他會很高興知道我們即將對葛羅瑪夏進軍。\n\n我確信他在洛克拉斯與戰歌獸人的對峙會很需要你的協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35096] = {title = "投降條件", objective = "在洛克拉斯與斬敵者烏魯克交談。", description = "我有好消息，指揮官：我們已拿下了洛克拉斯。\n\n<大酋長得意地微笑。>\n\n部落已俘虜了大多數的戰歌士兵，包括他們的首領，斬敵者烏魯克。\n\n我把受降的榮耀留給你。他們正在裡頭等著，指揮官。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35097] = {title = "洛克拉斯的驕傲", objective = "殺死斬敵者烏魯克。", description = "你以為戰歌軍人會這麼輕易戰敗嗎？\n\n<你聽見一陣急促的聲音，像是繩索在金屬上磨擦。>\n\n我對你們部落早不耐煩了，竟然還敢侵入我們的家園。\n\n<斬敵者烏魯克直視你的眼睛，那股聲音也越來越清楚。>\n\n我們不會投降，戰歌氏族不向任何人低頭！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "平原雷鳴護腰塑風者裹腰草原風暴鍊甲腰帶乘獸者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][35098] = {title = "平定洛克拉斯", objective = "在沃瓦爾與索爾交談。", description = "他們首領已死，剩下的戰歌軍隊就更容易殲滅了。\n\n只要戰爭一結束，我便會拔營離開洛克拉斯，向葛羅瑪夏進軍。\n\n如果你將前往沃瓦爾，請通知索爾我們即將準備就緒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35099] = {title = "摧毀戰爭機器", objective = "毀掉3部鋼鐵部落戰爭機器。", description = "鋼鐵部落從鐵拳港將戰爭機器送往洛克拉斯。不久他們便會將河畔哨站夷為平地。\n\n我們必須毀掉那些戰爭機器！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35100] = {title = "如果他們不投降…", objective = "殺掉10個洛克拉斯的敵方士兵。", description = "這是我們準備要送往與卡爾洛斯‧地獄吼及葛羅瑪夏對抗的部隊主力。\n\n如果他們不投降，我們別無選擇，只能完全消滅戰歌氏族。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "塑風者護腕平原雷鳴護腕草原風暴護腕乘獸者護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][35101] = {title = "納葛蘭之懼", objective = "從薩戈身上取得薩戈的項圈。", description = "<一個死去士兵的遺體躺在這裡。斑斑血跡從屍體延伸至北邊的洞穴入口。>\n\n<從獸穴周圍的屍骸與吼叫聲判斷，裡面一定住著十分可怕的怪物。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35102] = {title = "鐵刃出鞘", objective = "到塔拉多爾的沃金之傲內與摩克斯‧刃嚎交談。", description = "謝謝你…老大。\n\n我不會讓你失望的！我連想都沒想過要把苦工放在牢籠旁邊的劣質刀具偷走。這樣很不好，應該要趕快把刀具拿走，免得有哪個下流傢伙有機可乘。\n\n廢話少說，我們先逛逛這個地方吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35103] = {title = "鍊金師", objective = "在焚骨坑地找到卡妲爾。", description = "我從表姊卡妲爾學到一些關於鍊金術的知識。她是石牙哨站的鍊金術師。如果你想學習更多鍊金術，可以向她請教。\n\n我只希望她從那場攻擊中倖存。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35104] = {title = "學徒", objective = "搬開礫石，與安可菈談話。", description = "卡妲爾的遺言…還有人在小屋裡面嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35106] = {title = "報仇雪恨，失而復得", objective = "擊殺害死卡妲爾的兇手，取回那本書。", description = "我要替師傅報仇，奪回她的畢生心血。這都是為了榮譽。我迫切渴望要報仇，就算要賠上生命，我也在所不惜。殺人兇手終將償命。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n德拉諾鍊金概論鍊金實驗室，第1級"}
MultiLanguageQuestData['tw'][35128] = {title = "誠心的警告", objective = "殺掉8個碎脊歐格隆和博洛甘。", description = "在這邊的歐格隆算不上才華洋溢，但是他們要比古羅聰明。他們身材巨大，甚至比外表看來更強壯。\n\n他們的領導者，博洛甘，更是特別地可怕。儘管和他對戰了幾次，我還是沒能殺掉他。\n\n謹記我的話，朋友。在你探索他們的巢穴時要格外小心。\n\n妮莎已經準備動身了。請她帶你前往洞口，而且我敢說她一定很樂意。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "歐格隆殺戮者的斧頭歐格隆殺戮者的巨斧歐格隆殺戮者的射目弓歐格隆殺戮者的割踝匕歐格隆殺戮者的瘀眼錘歐格隆殺戮者的鑿目矛歐格隆殺戮者的巨杖歐格隆殺戮者的木錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][35129] = {title = "丟下每個士兵", objective = "找到下士蘇克瑪並取回他得到的情報。", description = "嗯。\n\n歐格隆對鋼鐵部落而言具備了某種價值。我很確定他們還沒注意到這點，只視他們為百般無聊之餘用來拷打的東西。\n\n我是很樂意放任不管，這是他們應得的命運。但我們可不能就這麼放過這個契機。如果運氣夠好的話，這可以協助我們阻止鋼鐵部落，把格古隆德最可怕的生物轉變成武器。\n\n試著找出這位下士蘇克瑪和他的筆記。我們在那邊見面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35136] = {title = "鋼鐵鎖鏈", objective = "擊敗布萊珂上尉，並找到麥奈隆之心。", description = "我們尋找的神器已近在咫尺。\n\n做好戰鬥準備。如果他們真的學會如何控制古羅，事情可能會比想像中棘手。\n\n你一到該處我便會加入戰鬥。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "火鑄胸鎧野木牧者外衣蔓生切除外衣氣爆長袍您會收到：\n\n"}
MultiLanguageQuestData['tw'][35137] = {title = "搏擊競技場", objective = "在格古隆德的高地之路與遊俠喬納交談。", description = "我們的自由是你給的，要感謝你的事情太多了。我已經和其他人談過了，我們願意跟你回要塞，教導你所謂的「士兵」如何正確作戰。\n\n我們也會盡量傳授知識給你，指揮官。如果你在格古隆德的荒野中有需要我們的地方，儘管呼喚我們。\n\n你或許該告知遊俠喬納我們將會到來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35139] = {title = "空中之眼", objective = "與妮莎交談。", description = "你找回來的筆記中描述了一個裝置，甚至可以讓麥奈隆聽命。\n\n在遠古傳說提到了這樣的神器，那是由創世者打造、用來抑制這一類生物時所使用的。我在過去一直把這些傳說視為無稽之談，但如果這些都是真的…\n\n<name>，德拉諾就完蛋了。\n\n如果他們駕馭了這股力量，就沒有軍隊能夠阻止他們了。我們一定要阻止他們，絕不放棄。\n\n來，我會將我們的視野與妮莎連結在一塊，希望牠能夠找到這件神器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35140] = {title = "塞林！", objective = "捕獲15個戈倫寶寶。", description = "那小畜…！\n\n<伊芮爾試圖壓抑怒氣。>\n\n塞林‧暗砧送來了一批貨，裡面本該是些工程零件。\n\n但當我們打開其中一個貨箱時，卻跳出來一個戈倫寶寶。你知道那東西有多可怕嗎？\n\n而且他馬上將其他的同伴都放了出來。\n\n想幫我復仇嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35141] = {title = "寵物籠已經抵達", objective = "到泰拉蕊哨站將戈倫寶寶提籠交給塞林‧暗砧。\n\n已提供物品：\n", description = "我們要對那小混帳還以顏色。\n\n將戈倫寶寶放進其中一個運送器，送給塞林一個驚喜吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35142] = {title = "戈倫入侵！", objective = "擊退侵略要塞的戈倫。\n\n(再次與士官邪顎談話即可開始)", description = "大地在我們腳下顫動，指揮官。我們的斥候還沒回來。我有預感我們即將遭到攻擊，但究竟會來自何方呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35143] = {title = "燃刃之血", objective = "殺死15名哈瓦洛的燃刃成員。", description = "哈瓦洛是我燃刃氏族祖靈的家鄉。當新酋長與其家族掌握政權後，身為混血的我就被流放異鄉。\n\n我要伸張正義。\n\n我想你大概不會介意一路殺進去，雖然你可能別無選擇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35144] = {title = "黑暗束縛", objective = "解救10個元素之靈。", description = "即使在我們交談的現在，蒼白獸人正在墜影峽谷奴役元素。已經有許多元素受到奴役，還有更多會加入它們。\n\n必須阻止蒼白獸人並解救尚未完全被他們奴役的元素之靈。至於那些已經被蒼白獸人奴役的元素，我們唯一的仁慈就是透過死亡解除他們的連結。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35145] = {title = "蒼白的威脅", objective = "殺死灰色先知及6個蒼白獸人。", description = "蒼白獸人是可悲的生物，躲在地面之下，不停想著如何害死居住在地面上的人。他們在蒼白地穴活動，那裡是歐夏剛地底扭曲而黑暗的洞穴。\n\n若我們想要成功阻止丘加利，我們必須一路打進地底。\n\n前往下面的山洞，殺死裡面的邪惡生物，並解決蒼白獸人的領袖，他的名字是灰色先知。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35146] = {title = "好醫生", objective = "解救哈德利‧瑞卡德醫生。", description = "我們遠征隊的生物學家被魔花人綁架了！\n\n我們來納葛蘭進行探索，殺死最可怕的怪獸，跟隨著偉大的赫米特‧奈辛瓦里，測試我們的膽量。\n\n我們一抵達這裡，具有超凡狩獵技巧的赫米特卻要立刻去協助對抗戰歌氏族。與其坐在這裡浪費時間，我們決定繼續探索！\n\n當我們在探索惡葉灌木林時，受到了魔花人的襲擊！哈德利‧瑞卡德醫生在混亂中被抓走了。\n\n拜託你了，我們不能把他留在那裡！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35147] = {title = "過往的碎片", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][35148] = {title = "堡壘裡的麻煩", objective = "在瑪爾戈克堡壘找到遊俠艾莉娜。", description = "你知道，我們派了幾個斥候查看瑪爾戈克堡壘那些臭不可當、所謂「文明」的巨魔。\n\n我有一段時間沒他們的消息了。事實上，從我在泰拉救你一條小命後他們就音訊全無。\n\n有空去那幫我查看他們狀況如何嗎，<小男孩/小女孩>？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
