MultiLanguageQuestData['tw'][35166] = {title = "打撈沉船", objective = "收集15箱苦工船打撈物。", description = "指揮官，我們的補給存量快見底了。\n\n或許我們能從那艘載你過來的船上回收點物資？\n\n按照傳送門把大夥傳送過來的速度，太陽下山前我們就要一無所有了，或者該說月亮下山前…？\n\n我還在習慣這地方的作息。", progress = "補給已經快見底了，指揮官。", completion = "哇…有了這些物資，我們應該就沒問題了。\n\n有你在這裡保護我們真是老天保佑，指揮官。", rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35167] = {title = "迷失在納葛蘭", objective = "找到曼寇里克的女朋友奧格菈。", description = "<先生/女士>，可以幫我嗎？\n\n我認識一位叫奧格菈的女孩。她和她的雙親昨天回去沃瓦爾了。不過他們一直沒有回來，而且再也沒有人見過他們。\n\n若你要回去，可以順便找找她嗎？\n\n她可以算是我的女朋友啦。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35168] = {title = "你的第一張鍛造訂單", objective = "在冶煉廠開始和點收你的第一張鍛造訂單。", description = "現在冶煉廠已經完工了，我們可以開始為你製作真鋼錠。等你取得足夠的材料之後，請和我的助手交談，就可以開始進行第一張訂單。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n真鋼錠"}
MultiLanguageQuestData['tw'][35169] = {title = "索爾的正義", objective = "在葛羅瑪夏之門與復仇者伊芮爾交談，並率領部隊向戰歌氏族進攻。", description = "時候已經到了，指揮官。你已經把戰歌氏族的盟友和據點都收拾掉了。\n\n我們的部隊正聚集在葛羅瑪夏外頭。\n\n根據遊俠的可靠情報顯示，卡爾洛斯就躲在戰歌要塞裡面。\n\n我們之前所有的努力，都是為了這一刻。讓我們除掉卡爾洛斯吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "地基護盔喚雷者風帽掌握大地罩盔雷霆箭鞣製盔帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][35170] = {title = "復仇心切", objective = "殺死『野蠻人』沃格斯金。", description = "他們…突然出現。從那個方向。\n\n<年輕的女孩含著淚水，大略地指向西方。>\n\n他們騎著兇惡的狼。\n\n求求你，指揮官，我家族的榮耀正岌岌可危。你能為我復仇嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35171] = {title = "索爾的正義", objective = "在葛羅瑪夏之門與杜洛坦交談，並率領部隊向戰歌氏族進攻。", description = "時候到了，指揮官。你已經解決了在這附近所有的戰歌氏族盟軍及佔領區。\n\n我們的部隊正在葛羅瑪夏之門外集結。暗影獵手有可靠的消息，說卡爾洛斯正在戰歌堡壘內堅守。\n\n之前所有努力，都是為了讓這一刻能夠到來。成敗在此一戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "地基護盔喚雷者風帽掌握大地罩盔雷霆箭鞣製盔帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][35174] = {title = "蒼白的月光", objective = "殺死『覓血者』嚙咬和8個蒼白吞噬者。", description = "我們收到很奇怪的消息，說附近的德萊尼營地靜潮臺受到獸人攻擊。\n\n據說這些獸人和我們之前遇到的完全不同。\n\n他們…一臉病容，膚色也非常蒼白。\n\n靜潮臺的德萊尼需要我們的協助，指揮官。這正是個可以測試要塞實力的絕佳機會。", progress = nil, completion = "老實說這很令人不安。\n\n這些生物一定是從地底來的。\n\n希望我們看到的就是僅剩的一批了。", rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35176] = {title = "保持鎮定", objective = "與雪莉交談、找尋助手布萊斯東，並且查看要塞儲物箱。", description = "有這麼多工作要做…我都不知道要從哪裡著手了。\n\n確保這座要塞順利運作可不是件容易的事。\n\n雪莉還沒向我回報，我的助手布萊斯東跟她的組員不知道在哪…啊啊啊，我實在是忙翻了，到現在都還沒時間去查看資源存量。\n\n如果我是個法師，是不是就可以用分身術，同時把這些工作完成？", progress = "我們可以晚一點再聊嗎？女士？\n我現在真的沒有時間。", completion = "你說什麼？指揮官，你真是個救星。\n\n解決掉這些事情，我的工作就輕鬆多了。", rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35185] = {title = "要塞戰役：薩格萊", objective = "在影月谷的索奎薩爾高地和大法師莫德菈交談。", description = "你好，<name>。\n\n大法師卡德加想要向你傳達一些重要訊息。\n\n在德萊尼的領導者，奧薩爾主教自行揭露他早就在為燃燒軍團效力後，所有德萊尼都受到了遭人背叛的切膚之痛。\n\n現在，奧薩爾來到影月谷的山上，以索奎薩爾的名號徵募新兵，來完成他的目標。\n\n這一次的秘密任務是由大法師莫德菈負責，而我們需要你的協助才能完成。\n\n到現場去和她會面，她會進一步告訴你詳情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35186] = {title = "要塞戰役：薩格萊", objective = "和布隆‧天角交談以前往影月谷。", description = "你好，<name>。\n\n大法師卡德加想要向你傳達一些重要訊息。\n\n當德萊尼的領導者，奧薩爾主教自行揭露他早就在為燃燒軍團效力之後，所有德萊尼受到了背叛般的切膚之痛。\n\n現在，奧薩爾來到影月谷的山上，以索奎薩爾的名號徵募新兵，來完成他的目標。\n\n這一次的秘密任務是由大法師莫德菈負責，而我們需要你的協助才能完成。\n\n到現場去和她會面，她會進一步告訴你詳情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35187] = {title = "滲透薩格萊", objective = "收集一套薩格萊長袍、薩格萊風帽、以及薩格萊便鞋以合成薩格萊偽裝。穿上偽裝，然後與縛魂者薩瑪雅以及隱士朗達交談。", description = "我有個手下已經滲透進了薩格萊陣營，但是我需要你過去協助他。\n\n為了保護他的身分，你必須喬裝成敵人的一份子。\n\n殺掉那些薩格萊成員，收集偽裝所需的一整套風帽、長袍、以及便鞋。\n\n換上偽裝之後，向縛魂者薩瑪雅謊稱你是新學生，然後告訴隱士朗達「影月谷下雨了」。\n\n他聽到這句暗號就會知道你是同伴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35188] = {title = "可惡的魔花人", objective = "收集8個木製長矛。\n\n如果你的偽裝失效，殺死敵對的薩格萊教徒就可以取得薩格萊風帽、薩格萊長袍和薩格萊便鞋，重新製造一套薩格萊偽裝。", description = "啊，新來的，準備好進行第一個任務了嗎？\n\n南邊的林地滿是可惡的魔花人。那些壞傢伙定期會破壞我們的農田、偷竊補給品、攻擊不懂事的學員。\n\n這種噁心又糟糕的生物還是清除掉吧。\n\n <薩瑪雅不信任地看著你。>\n\n你必須帶回他們的長矛，證明你真的完成了這個任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35189] = {title = "索奎薩爾之言", objective = "閱讀「埃雷達爾的命運」、「和諧之願」和「永恆之誓」。", description = "薩格萊狂熱的跟著索奎薩爾。從我收集到的情報來看，他是一位極具說服力又能令人屈從的領導者。\n\n許多初學者都會帶著他所撰寫的書籍。\n\n我要你去閱讀那些著作，再向我回報。如果我們能夠瞭解薩格萊的動機，或許有機會暗中破壞。\n\n我上次看到這些書籍分別放在湖邊，噴泉附近的桌子，還有花園附近的屋子裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35190] = {title = "遠古威脅", objective = "殺死苔木古樹。\n\n如果你的偽裝消失，殺死薩格萊的成員來收集薩格萊風帽、薩格萊長袍和薩格萊便鞋，來製作薩格萊偽裝。", description = "在東北方有一棵古樹坐落在森林中的空地上。\n\n我需要人手去解決這個麻煩。\n\n這應該是件簡單的工作，就算你這樣的新手也可以勝任。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35191] = {title = "粉碎敵人", objective = "毀掉6枚魔風水晶。", description = "趁你虛情假意服從薩瑪雅的命令時，我們正打算在他們眼皮下面破壞薩格萊的進度。\n\n你可以在這座村落四周找到魔風水晶。敵人利用這些物品來放大他們的力量。\n\n摧毀這水晶，我們就可以拖慢他們的行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35192] = {title = "See Reinforcements Teleport", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][35193] = {title = "敌人的武器", objective = "获得4份萨格雷武器。\n\n假如你失去了你的伪装，杀死萨格雷成员以收集一顶萨格雷兜帽、一件萨格雷长袍和一双萨格雷软鞋，并用它们合成萨格雷伪装。", description = "一切进展顺利，新兵。我们就快要获得进入议会间的资格了。\n\n与此同时，我们的破坏行动也还要继续。在东北边的山上，你会找到萨格雷的训练场。\n\n他们花了几个月的时间在那里锻造最精良的武器，以供战时之需。\n\n而我们只需片刻就可以破坏他们的成果，<name>。\n\n把他们的武器都偷来，看他们还能拿什么打仗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35194] = {title = "面對惡魔", objective = "打到因沃卡茲，並摧毀惡魔之門。", description = "時機快到了，<name>。薩格萊在西邊山丘上開啟了一道召喚用的傳送門。\n\n我相信他們正打算運用這一道傳送門把惡魔大軍送來此地，進入影月谷。\n\n我們一定要阻止這件事發生，不計一切代價。運用這枚秘法炸彈來毀滅傳送門。\n\n我們的偽裝可能被識破，但現在阻止傳送門更加重要。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35195] = {title = "索奎薩爾之怒", objective = "對抗索奎薩爾，並從縛魂者薩瑪雅手中收集薩格萊作戰計畫。", description = "<在展開卷軸的時候，隱士朗達的訊息出現在眼前。>\n\n我匆匆寫下這些訊息。我被發現了。我正被帶往索奎薩爾前線。\n\n你必須完成我們的任務。我已經得知縛魂者薩瑪雅手中握著索奎薩爾下一波攻擊的詳細內容。\n\n她還是很信任你，所以你應該可以進入主要建築物。拜託你，找到這些計畫，<name>！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n薩格萊偽裝"}
MultiLanguageQuestData['tw'][35196] = {title = "打鐵趁熱", objective = "回到你的要塞找卡德加的僕從。", description = "<隱士朗達的聲音幾乎微不可聞。>\n\n你必須告訴卡德加。\n\n索奎薩爾打算奪下撒塔斯。他會…不斷招募追隨者…為他效命…\n\n感謝你…協助我…在我臨終之時…\n\n讓我一個人靜一靜…我想休息…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35197] = {title = "打鐵趁熱", objective = "在霜火峰回到你的要塞找卡德加的僕從。", description = "<隱士朗達的聲音幾乎微不可聞。>\n\n你必須告訴卡德加。\n\n索奎薩爾打算奪下撒塔斯。他會…不斷招募追隨者…為他效命…\n\n感謝你…協助我…在我臨終之時…\n\n讓我一個人靜一靜…我想休息…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
