MultiLanguageQuestData['tw'][35202] = {title = "幫蘇克一把，好嗎？", objective = "從骨墳吞食者身上收集9個戈倫外殼。", description = "蘇克編織的魔法可以幫你做大事，只是要先準備一下，才能獲得靈魂力量的祝福。\n\n蘇克需要從那些麻煩戈倫身上取得許多外殼。蘇克偷偷和你說個秘密。\n\n只要靠近他們的火山口通道，這些戈倫就會通通跑出來。這樣你就可以一次殺掉一堆。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35203] = {title = "更多的材料", objective = "收集50份要塞资源。", description = "要建造要塞可不容易，要是没有合用的资源，我们什么都做不了。\n\n我们需要更多更多的资源。\n\n要是你在野外发现了什么一定要告诉我。我们需要一切形式的帮助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35204] = {title = "花粉之力", objective = "收集20份高效花粉。", description = "波塔尼利用巨大的類昆蟲的生物幫助花朵授粉。\n\n它們攜帶的花粉有幾個對你的要塞軍隊有益的強大屬性。\n\n如果你能帶一些花粉給我，我就能做出有價值的東西。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35205] = {title = "燒毀屍體", objective = "燒掉6具被當成堆肥的屍體。", description = "你沒搞懂。沒有被這些植物人感染的東西，都被拿來當食物了。\n\n我說啊，我們得解決它們的食物來源。\n\n我看過這些波塔尼留下一些屍體，就躺在附近。把那些屍體燒掉可能是個好點子。\n\n讓我們看看，它們是不是連灰燼都加以感染。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35206] = {title = "奇襲者", objective = "殺死7個茂林編織者。", description = "我們正在繼續搜尋塞林的手下，但這些波塔尼帶來的威脅遠超預期。\n\n殺死目標後加以感染…駭人聽聞。\n\n求求你，指揮官，如果你去了我們西邊的永晨泉，盡你所能殺掉那些怪物。\n\n阻止它們繼續進行這種可怕的行動，制裁它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "波塔尼栽植者之戒波塔尼看管者徽印波塔尼治癒者璽戒波塔尼散葉者璽戒波塔尼修剪者璽戒您會收到：\n\n"}
MultiLanguageQuestData['tw'][35207] = {title = "煤件的復仇", objective = "殺掉3個靈樹法師。", description = "我飽到連斧頭都沒辦法揮了。\n\n我跟你說，我們有共同的利益。你幫我向這片林地後面的大波塔尼復仇，我就告訴你要怎麼拿到波塔尼收藏的秘密武器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35208] = {title = "打倒黑鐵", objective = "到永晨泉找布瑞恩‧煤件。", description = "當你外出時，我們這裡的遊俠發現更多關於我其他朋友的線索。\n\n布瑞恩‧煤件和灼眉。\n\n問題是，他們的足跡通往西邊的永晨泉。\n\n指揮官，你是否可以過去那邊，拯救他們別被當成堆肥呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35209] = {title = "生命泉水", objective = "取得奧崔菲斯之水。", description = "我們來此處的原因是想拿到波塔尼曾使用的一種武器。\n\n漢瑟爾拿走了神器，而灼眉跟我應該要拿使用神器所需的特殊起源之水。\n\n但我們不曉得這水如此有生命力，竟然形成了水元素。\n\n如果你去永晨泉裡古神器底層的大鍋，你便會看到那怪物。只要你殺掉它，拿到起源之水，當我們拿到剩下的神器後，便能使用了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "波塔尼纏繞之鍊水蝕的巨魔雕刻奧崔菲斯中的靈魂石光滑的靈魂石波塔尼荊棘項鍊您會收到：\n\n"}
MultiLanguageQuestData['tw'][35210] = {title = "大逃亡", objective = "清理戈倫隧道，穿過之後來到怒之裂口外，與雷克薩見面。", description = "一條戈倫隧道！\n\n只要把入口清乾淨，一定可以帶我們離開這個不被聖光眷顧的場所，直通外面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35211] = {title = "預防萬一", objective = "在急嘯角放置5顆火焰彈。", description = "你看到急嘯角建築上的那些真菌了嗎？早晚整座海岸都會被孢子感染！\n\n急嘯角上的殭屍已經無法挽救，最好的方式就是幫它們解脫，預防範圍更廣的感染發生。\n\n我做了一些火焰彈來破壞孢子，但我需要你在我安裝引信時將它們放好。\n\n你準備好了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "「超無毒」爆烈守衛腿鎧「超無毒」爆烈守衛裹腿「超無毒」爆烈守衛護腿「超無毒」爆烈守衛馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][35212] = {title = "深根林", objective = "到深根林找塞林‧暗砧。", description = "既然你已經準備和這些花草樹木打交道，我得請你幫個忙。\n\n我來自格古隆德並試圖找出一群前往此地的同胞，黑鐵探險隊的下落。可惜我找不到他們了。\n\n我準備往南繼續尋找。問題是，南邊除了波塔尼、魔花人、巨樹，和其他殘忍、生氣的植物以外，什麼都看不到。\n\n你的木材營地資源可以從中取之不竭。如果你能幫我尋找朋友，我發誓我們會儘一切可能協助你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35213] = {title = "剃刀茂林", objective = "找到蕾拉‧灰趾、諾里‧煤斑、和亂鬚下落的線索。", description = "凱爾雅認為她找到線索了，照足跡來看，一群矮人似乎走去北邊的剃刀茂林了。\n\n問題是，那個地方到處都是植物人。我對會走的植物實在沒輒。\n\n你願意去調查一下嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "火鑄鎧甲束腰氣爆之索野木牧者腰帶蔓生切除腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][35214] = {title = "慘遭感染", objective = "殺死6隻遭感染的受害者。", description = "德坎雖然沒說，但是除了你找到的人之外，還有其他許多遊俠被波塔尼帶走了。\n\n他認為他們都被殺了，但我擔心他們的下場可能更糟。\n\n你可能要大著膽子冒險進入剃刀茂林。如果你進去了，就有可能發現波塔尼對它們的…「囚犯」做了什麼。\n\n讓這些可憐的靈魂安息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35215] = {title = "艾猶之聲", objective = "消滅艾猶之聲。", description = "日誌第25章-\n\n波塔尼出現了一個首領，她…呃…他…不對…它自稱…艾猶之聲。\n\n波塔尼似乎將傑那索視為神，而只有地位最高的波塔尼才能代表傑那索發言。\n\n當我們試著問它關於我們在底層發現的神器，它十分生氣，蕾拉跟諾里就被逐出來了，從那時我就沒見過她們倆。\n\n我有不好的預感。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35216] = {title = "超級種子", objective = "收集營養的種子。", description = "這些種子被波塔尼小心的保護著。\n\n從這些小小的生命之器中，可以感受到強大的力量。\n\n這可能會派上用場。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35217] = {title = "冰糖雪梨", objective = "摧毁10枚蜜糖梨。\n\n假如你失去了你的伪装。杀死萨格雷成员以收集一顶萨格雷兜帽、一件萨格雷长袍和一双萨格雷软鞋。并用它们合成萨格雷伪装。", description = "在你听命于扎玛亚以赢得她好感的同时，我们会暗中破坏萨格雷的行动。\n\n魔荚人把他们从农场里偷来的梨子都藏到了西北边的森林里。这群小麻烦精就爱这种水果。\n\n而且那些梨子似乎正是萨格雷最主要的食物来源。既然如此，我们自然就要把他们的收成都毁掉。\n\n这样德莱尼和魔荚人的问题就都解决了，真是一举两得。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35218] = {title = "鋼鐵部落指令", objective = "在碎牙之歿的鋼鐵部落營地中尋找武裝指令。", description = "靈魂在附近崖地的鋼鐵部落營地發現了一些命令。你上次去的時候一定錯過了。你可以再去找找嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
