MultiLanguageQuestData['tw'][35240] = {title = "鮮血乾涸", objective = "從心之血的2個血之谷牢籠中釋放奴隸。", description = "<德萊尼人說出最後遺言。>\n\n他們將我們囚禁在牢籠裡。他們…抽取我們的血液，以供…儀式之用…\n\n<他劇烈咳嗽。>\n\n…許多人還在那裡…我的…同胞…\n\n<德萊尼人死了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35241] = {title = "為死者復仇", objective = "殺死6個血之谷獸人。", description = "太多同胞死在血之谷獸人的手裡，絕對不能饒恕這些殘酷無情的傢伙。\n\n<悲傷的獸人抬頭看著你。>\n\n讓他們付出代價。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35242] = {title = "為死者復仇", objective = "殺死6個血之谷獸人。", description = "太多同胞死在血之谷獸人的手裡，絕對不能饒恕這些殘酷無情的傢伙。\n\n<悲傷的德萊尼人抬頭看著你。>\n\n讓他們付出代價。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
