MultiLanguageQuestData['tw'][35335] = {title = "Vignette: Bashiok", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][35337] = {title = "重擊之聲", objective = "從厚皮裂蹄身上收集12對厚皮耳朵。", description = "指揮官。遊俠和我正好在討論各種「狩獵」方式的價值。\n\n我向她保證，軍情七處不管處理什麼狀況都會全副武裝，即便是身在野地也不例外。\n\n但她似乎覺得我們在「她的地盤」上搞不太清楚狀況，而且絕對會輸掉這場比賽。\n\n我們可不希望讓她就這樣贏了，然後到處說嘴，對吧？讓我們去獵點裂蹄吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "平原獵手之爪平原獵手匕首平原獵手棍棒平原獵手尋水節杖平原獵手遮蔭盾平原獵手防曬盾您會收到：\n\n"}
MultiLanguageQuestData['tw'][35338] = {title = "逐風追擊", objective = "從逐風塔巴克身上收集24個逐風塔巴克角。", description = "我和琪雅正為了誰的獵殺技巧比較有效率而爭論不休，是軍情七處？還是遊俠？\n\n要不要賭一把啊，指揮官？\n\n我喜歡塔巴克的勇猛與威武，所以一直關注牠們。每個土生土長的德拉諾居民都知道，塔巴克象徵了納葛蘭的威嚴。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35339] = {title = "最後請求", objective = "從要塞內的怨靈身上收集6個鬼靈精華，然後說服艾莉絲‧芬恩接受死亡的事實。", description = "我不知道發生了什麼事。我的工作組員和我是最先死去的。\n\n我的太太、也就是旅店老闆跟我先前一樣對外界毫無反應。我可以感受得到…我太太身邊還有許多人。\n\n拜託，讓那些村民的怨靈安息，並把他們的精華拿給我的太太。這應該能讓她恢復意識。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35340] = {title = "这儿发生了什么？", objective = "找来一份布莱恩·费恩的图纸。", description = "这名建筑师的灵魂没有主动攻击我们。或许我们能破除笼罩他神智的迷雾，让他告诉我们这里发生了什么。\n\n我猜这里这些亡灵农夫的身上可能带着他的设计图纸之类的东西，可以拿去给他看，以便他恢复神智。\n\n我认为这值得一试。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35341] = {title = "古羅巡者洛卡什的背叛", objective = "接受大劍師奈許菈的血誓", description = "你幫了我很大的忙，這把劍說是我鑄的，其實也等於你鑄的。\n\n我謹此立下血誓，貢獻我對鑄劍和採礦的知識，為你效命。\n\n你接受嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：古羅巡者洛卡什\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35342] = {title = "神秘燒瓶", objective = "和你要塞裡的艾尼爾交談。\n\n已提供物品：\n", description = "燒瓶中的液體不斷旋轉，顯然具有很強的化學特性，但你的訓練並不足以駕馭那液體的本質。\n\n在你要塞的靜潮村民之中，聽說有個人通曉德拉諾的鍊金術。也許他能告訴你更多事情？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n德拉諾耐力精煉藥劑"}
MultiLanguageQuestData['tw'][35343] = {title = "年輕鍊金術師", objective = "在綠水潭找到艾芭莎。", description = "我跟我的阿姨學過一點鍊金術。如果你想學習更多鍊金術，你應該要請教我的表姊艾芭莎。在我阿姨過世之前，艾芭莎曾是她的學徒。\n\n艾芭莎跟她父親和妹妹就住在綠水潭附近。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35344] = {title = "失蹤的父親", objective = "到綠水潭找特洛斯。", description = "我很樂意幫助你多了解一點鍊金術，但我現在很擔心我的父親。\n\n他到河邊打獵已經好一段時間了，卻一直沒有回家。我得看著璐米爾。能拜託你去找他嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35345] = {title = "震撼協助", objective = "從震鱗鰻魚身上取得100片震鱗。", description = "自從我太太過世，要撫養整個家確實非常不容易。而且，那張蒐集震鱗的訂單我實在是過於自信了。\n\n唉，我一定無法在契約要求的期限之內獵捕到足夠的鰻魚。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n德拉諾鍊金概論鍊金實驗室，第1級"}
