MultiLanguageQuestData['tw'][35386] = {title = "戰歌的威脅", objective = "偷取戰歌攻擊計畫。", description = "<這份攻擊計畫用濃厚、黑色的墨水，潦草的寫在羊皮紙上，再用粗皮繩綁起來>\n\n致所有先遣騎部隊：\n\n酋長已經號令所有先遣騎，準備全面突襲在我們土地上的聯盟入侵者。攻擊計畫已經送往數個偏遠的先遣騎哨站。\n\n當我們把聯盟入侵者踩在腳下時，鮮血與榮耀將與我們同在！\n\n酋長有令，戰歌誓死遵從！不勝即亡！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35387] = {title = "穿越扭曲虚空", objective = "进入扭曲虚空。", description = "虚空仪式被阻止了，可黑暗能量仍在不断地流入各个仪式场的虚空道标之中。这只能有一个原因：这些道标的能量是由扭曲虚空直接供给的。\n\n切断这些虚空能量流的唯一方法就只有进入扭曲虚空，然后消除潜伏在那里的能量！\n\n使用那边的道标进入扭曲虚空。一旦你到了那里，就使用元素之怒赐给我们的萨满之石来联系我。\n\n愿圣光与你同在。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35388] = {title = "虚空的大军", objective = "摧毁12只虚空生物。", description = "虚空恐魔的大军正向着沃舒古汇聚，并一一将它们的身躯奉献给虚空领主伊瓦里杜斯。每当那些虚空恐魔死亡，伊瓦里杜斯就会变得更加强大。那些下级的生物似乎纯粹是为了被虚空领主吞噬而存在的。\n\n伊瓦里杜斯的力量正在不断增强，我们必须趁在还能阻止它的时候将它消灭。\n\n尽可能地杀死那些虚空怪物以减缓伊瓦里杜斯的成长速度。我会尽快想出一个能与伊瓦里杜斯作战的方法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35389] = {title = "停止召唤", objective = "杀死所有的战歌仪式领袖。", description = "战歌萨满正使用元素之力来引导虚空能量。\n\n我虽然不是萨满，但也知道这种行为在大多数兽人氏族里是被禁止的。虚空之力是圣光的反面，是无序和毁灭的根源。\n\n这些仪式会削弱扭曲虚空与这个世界之间的壁障。要是不阻止这些仪式的话，这片土地很快就会被扭曲虚空的住民所填满。\n\n杀死那些主持这些黑暗仪式的萨满，迟了的话，毁灭就会降临到我们的头上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35390] = {title = "笼罩沃舒古的阴影", objective = "召唤并击败伊瓦里杜斯。", description = "虚空领主伊瓦里杜斯在沃舒古的山顶上吸食着亡者的灵魂。\n\n甚至那些死去的虚空恐魔也成为了它的食粮。\n\n我们必须立刻行动，否则这个怪物会变得越来越强大，让我们无法应付了。\n\n在扭曲虚空中的每一处仪式场地上，都有一颗充满了虚空能量的水晶。只要触碰这种水晶，伊瓦里杜斯就会注意到你的存在。\n\n准备好，伊瓦里杜斯会第一时间试图吸食你的灵魂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35391] = {title = "破坏仪式", objective = "摧毁仪式图腾。", description = "战歌兽人在沃舒古的山脚下进行着黑暗的仪式。\n\n战歌萨满意图从圣山的中心吸取虚空能量来强化他们的氏族。\n\n我并不了解这虚空能量的源头……但这恐怕与飞船中濒死的纳鲁克乌雷有关。\n\n我们必须阻止这些战歌仪祭师，否则这个世界与扭曲虚空之间屏障将被撕裂。\n\n找到他们用来维持仪式的仪式图腾，并摧毁它们。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35392] = {title = "虚空迫近", objective = "摧毁10道虚空传送门。", description = "战歌氏族吸取虚空能量的愚行削弱了我们的世界和扭曲虚空之间的壁障。\n\n扭曲虚空中正不断有传送门在打开，意图将虚空的怪物们引往德拉诺。\n\n一旦这些传送门彻底开始运作，各种各样的恶魔和虚空怪物将席卷纳格兰。\n\n快趁这些传送门还没开始运作前摧毁它们！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35393] = {title = "靈性事端", objective = "和先祖之地的靈魂交談。", description = "長久以來，死者的靈魂會被吸引到歐夏剛的山中。\n\n就我記憶所及，這些森林到處都是先祖之魂，以鬼魂的形態朝著山腹進行朝聖之旅。我擔心被吸引到歐夏剛的靈魂會被山中擴大的虛無吞噬。\n\n前往先祖之地並和該地的靈魂交談，獲得他們的指引。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35394] = {title = "白鬼的威胁", objective = "回去找守备官努波顿。当你在和虚空大军激战之时，我去调查了一下坠影峡谷中的那些异象。\n\n阴暗的迷雾遍布于山谷之中，<name>；我还看到扭曲、苍白的生物潜伏于雾中。\n\n快从扭曲虚空中回来吧，我需要和你详细谈谈这件事。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "当你在和虚空大军激战之时，我去调查了一下坠影峡谷中的那些异象。\n\n阴暗的迷雾遍布于山谷之中，<name>；我还看到扭曲、苍白的生物潜伏于雾中。\n\n快从扭曲虚空中回来吧，我需要和你详细谈谈这件事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35395] = {title = "葛爾道格的命運", objective = "取回怒靈之心。", description = "擋住我們進入內室的路，像高塔般的可怕怪物，就是我們試圖要送回元素王座的怒靈。\n\n我們面前的葛爾道格已經被迷惑了；成為丘加利的奴隸。看到如此偉大的生物喪失自我，受到邪惡的奴役，讓我心中充滿了沉痛的悲傷。\n\n現在已經無路可退，為了向前推進，你必須通過葛爾道格這一關。\n\n雖然痛苦不堪，但必須要殺死葛爾道格才行。\n\n殺掉葛爾道格並將這位怒靈的心臟送回元素王座，它應該安息之地。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35396] = {title = "歐夏剛的黑暗之心", objective = "進入那魯聖所。", description = "受到漫長時間洗禮的真諾達號殘骸中，有一道通往船隻內室的大門。看來虛無能量就在那個地方凝聚。\n\n你必須進入內室，並面對潛伏在裡面的任何東西。我怕的是庫爾，偉大那魯的命運時刻已經來到，但不管那邊有什麼邪惡，都要加以淨化。\n\n願聖光與你同在，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "虛空扭曲的歐夏剛短劍虛空扭曲的歐夏剛巨槌虛空扭曲的歐夏剛之弩虛空扭曲的歐夏剛匕首虛空扭曲的歐夏剛釘錘虛空扭曲的歐夏剛法杖虛空扭曲的歐夏剛施術杖虛空扭曲的歐夏剛之槌您會收到：\n\n"}
MultiLanguageQuestData['tw'][35397] = {title = "來自蒼白的威脅", objective = "殺死灰色先知及6個蒼白獸人。", description = "若我們成功阻止丘加利摧毀那魯，我們會需要一路打進蒼白地穴。那是個黑暗、曲折的山洞，裡面全是蒼白獸人。\n\n蒼白獸人是痛恨善良及神聖事物的墮落獸人。如果放任他們和地下的那些東西不管，他們的黑暗計畫就會持續進展下去。\n\n前往蒼白地穴，殺死那些邪惡的生物並解決他們的領袖，灰色先知。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35398] = {title = "黑暗束縛", objective = "救出8個元素之靈。", description = "即使在我們交談的現在，蒼白獸人正在墜影峽谷奴役一整支元素大軍。已經有許多元素受到奴役，如果我們再不幫忙，還有更多會加入它們。\n\n前往墜影峽谷並解救尚未完全被蒼白獸人奴役的元素之靈。至於那些已經被奴役的元素，我們唯一的仁慈就是給他們痛快的死亡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35399] = {title = "生苔的命運", objective = "在剃刀茂林中尋找『剁耳者』托格、『嚼面者』梅卡、和『無鼻者』恰格。", description = "你的狼后不會讓我離開她的視線。\n\n雖然毀掉村子的是麥奈隆的孩子，但傑那索的孩子才是抓走人民的禍首。\n\n波塔尼和它們的僕從把我們的人拖進了剃刀茂林，就算我們能夠再見到他們，也不再是活著時候的模樣了。\n\n你幫助過獰笑骷髏氏族，現在我再次向你求救。\n\n進入剃刀茂林，尋找我們最近被抓走的族人。\n\n或許他們還活著。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "火鑄鎧甲束腰氣爆之索野木牧者腰帶蔓生切除腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][35400] = {title = "感染寄生", objective = "殺掉6個被感染的獸人。", description = "我了解卡茲極想解救她人民，但她的計畫太過魯莽，又沒跟我們據實以告。\n\n我來到這裡，是為了查明她是否在暗中對付我們，結果我看到的是…是…眼前這副恐怖景象。\n\n波塔尼到底對這些獸人做了什麼？\n\n必須讓這些被寄生的靈魂安息，拜託你了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
