MultiLanguageQuestData['tw'][35406] = {title = "超級種子", objective = "收集營養的種子。", description = "這些種子被波塔尼小心的保護著。\n\n從這些小小的生命之器中，可以感受到強大的力量。\n\n這可能會派上用場。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35407] = {title = "處以極刑", objective = "殺掉8個要塞叛徒。", description = "叛徒，都是叛徒！\n\n在你面前的是最後一群對泰勒上將和聯盟忠心不貳的軍人。\n\n我絕對不會讓那些叛徒逍遙法外。\n\n看樣子你已經整裝待發，讓他們看看我們在戰時是怎麼處置他們這種敗類的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35408] = {title = "裝填火砲", objective = "取回10顆鐵皮砲彈和1座軍械庫火砲。", description = "軍械庫被叛徒佔據了。我們僅剩這幾座火砲，而且沒有彈藥可以發射。\n\n士兵，我要你去取得砲彈，讓火砲繼續運作。\n\n事實上，再多弄一座火砲來也不錯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
