MultiLanguageQuestData['tw'][35462] = {title = "受到包圍", objective = "破壞3台鋼鐵石毀車。", description = "那些鋼鐵部落的大砲正在摧毀我們的部隊。我不確定在這樣的攻勢下我們還能撐多久。我們的戰線已經延伸地太過薄弱了。\n\n一定得找出個辦法來阻止那些戰爭機器。", progress = nil, completion = "鋼鐵部落要讓那些石毀車再次啟動可得花上好一段時間。做得非常好，&lt;name&gt;。", rewards = "您會學到：\n\n存活戰鬥\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35463] = {title = "危險的斥候", objective = "殺死5個鋼鐵部落斥候。", description = "我們大多數的作戰計畫都沒辦法執行，一定有人在監視我們。\n\n鋼鐵部落在詛咒之地各處一定設有斥候。勝利正不斷離我們遠去。", progress = nil, completion = "你說你殺掉幾個斥候？難怪我們的作戰計畫都沒辦法順利執行…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35464] = {title = "阻止處刑", objective = "殺死3個鋼鐵戰線劊子手。", description = "我們盡快地趕過來…但依然太遲了。守望堡已經陷落，一部分的士兵被鋼鐵部落所俘虜。\n\n他們現在一定在對我們的人逼問重要情報。\n\n我怕他們只要問到了想要的資料，便會毫不遲疑地處決囚犯。時間正在流失。", progress = nil, completion = "囚犯有點驚慌，但他們自由了。士兵的家屬將感激你的協助，&lt;name&gt;。", rewards = "您會學到：\n\n進階戰鬥機制\n\n您還會收到：\n\n"}
