MultiLanguageQuestData['tw'][35647] = {title = "殘酷收成", objective = "從真菌踐踏者身上取得3個孢子毒莢交給坎諾。", description = "越深入沼澤，這些孢子就生長的越濃密，但那些大型的真菌怪獸才是關鍵。\n\n是的，殺掉它們，然後拿走孢子毒莢。孢子毒莢將對我的…研究有莫大助益。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
