MultiLanguageQuestData['tw'][35663] = {title = "學習團隊合作", objective = "取回10個神秘的文物。", description = "考古學隊伍最需要的重要技能之一，就是團隊合作。團隊合作的關鍵在於知道何時該給、何時該拿。\n\n天槌巨魔最近在峽谷中挖掘神秘的文物。為了考古學，我要你跟天槌巨魔合作！\n\n還記得我跟你說的給和拿嗎？巨魔努力地「給」我們挖掘文物，我要你把那些文物「拿」回來！\n\n這就是團隊合作！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n出土的天槌飾品出土的天槌小玩意出土的天槌裝置\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35664] = {title = "壞消息的懷種者", objective = "燒毀5個懷種古樹的屍體。", description = "當這些懷種者被殺死之後，他們的種子仍然活著。並從中生出新的懷種者，這不用等數年，只要幾個小時。\n\n把他們的屍體留在此地，這座前哨站馬上就會被淹沒。\n\n我們已經學會燒掉他們的屍體，以避免此事發生。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35665] = {title = "我們有伴了", objective = "調查硫磺盆地的鋼鐵部落營地。", description = "指揮官，我發現了藏身在附近的鋼鐵部落士兵。\n\n就算是對他們來說，膽敢冒險進入這麼危險的區域，只能說他們十分勇敢。\n\n如果我們不出面處理他們，肯定會對你的營地造成威脅。\n\n我們進一步深入峽谷偵察時，可以請你去調察營地嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35666] = {title = "身陷紅沼", objective = "到格古隆德的緋紅沼澤附近尋找坎諾。", description = "格古隆德是個相當危險的地方，我已經派遣數個斥候小隊調查各個區域。\n\n其中一個地區是緋紅沼澤，這支斥候小隊現在還沒有回來。我希望你能找到失蹤的小隊，可以的話請他們回報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35667] = {title = "緋紅沼澤的奪顱者", objective = "到格古隆德的緋紅沼澤附近尋找格魯克爾。", description = "格魯克爾和他的隊伍經常一次就消失好幾個星期，直到他們帶著再也拿不動的戰利品和補給品才會回來。但這一次他消失的太久了。\n\n他提過要去緋紅沼澤進行首次的狩獵，去看看他是不是還活著。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35668] = {title = "希斯的秘密", objective = "取回安祖之眼。", description = "我們去世的朋友收藏了不僅是對古老卷軸和巫術傳說的熱愛，其中也有極具價值的寶物。\n\n如果我對他筆記中的意思理解無誤的話，他宣稱已經找到了泰洛克的占卜寶珠，泰洛克死後被稱為安祖之眼。\n\n我們需要那顆占卜寶珠！他的筆記上記載著將它藏在路上的劫毀者巢穴中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35669] = {title = "懸賞：割下的奇喉獸爪", objective = "從野蠻的奇喉身上取得割下的奇喉獸爪。", description = "張貼人：監工高內克\n\n一個名為奇喉的劍齒人對落斧堡造成威脅。\n\n他喜歡在夜晚殘殺苦工，並將屍體拖進他領地的巢穴裡。\n\n只要有人殺掉他，割掉他的獸爪帶給我以資證明，我重重有賞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35670] = {title = "懸賞：割脊者的軀殼", objective = "從割脊者身上取得割脊者的軀殼。", description = "張貼人：琪爾佳\n\n誰能將割脊者的軀殼帶給我，有筆豐厚的賞金等著他。\n\n我想要製作精良的劫毀者盔甲，但沒能力殺掉這種怪物。\n\n軀殼盡量不要毀損。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35671] = {title = "暗影集結", objective = "與瑞薩德進入維爾泰洛克。", description = "維爾泰洛克就在前面。\n\n希望其他人旅途平安無事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35672] = {title = "懸賞：毒鉤", objective = "擊殺毒鉤。", description = "張貼人：胡朵‧羽風\n\n毒鉤是在阿拉卡上空製造恐懼的禍害，阿拉卡貴族也懼之三分。\n\n牠讓空中交通困難重重，阻擾我們運送必要物資到落斧堡。\n\n我不需要任何證明，你只要確保阿拉卡上空不再聽到牠的梟叫就行。\n\n牠的窩巢在東北方的嚎風峭壁上。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35673] = {title = "Nagrand - Treasure 014 - Appropriated Warsong Supplies", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][35674] = {title = "懸賞：割下的奇喉獸爪", objective = "從野蠻的奇喉身上取得割下的奇喉獸爪。", description = "張貼人：威廉中尉\n\n巨型劍齒人奇喉經常在晚上出沒，在南埠大肆劫掠，讓我們損失不少人手。\n\n如果有人能抓到奇喉，把他的爪子割下來給我，我重重有賞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35675] = {title = "懸賞：割脊者的軀殼", objective = "從割脊者身上取得割脊者的軀殼。", description = "張貼人：軍需官裘莉\n\n我們已經幾乎沒有修復盔甲所需的物資。\n\n把強大的劫毀者，割脊者的軀殼帶來給我，我會支付豐厚的酬勞。牠的軀殼足以應付數週的修補物資之需。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][35676] = {title = "懸賞：毒鉤", objective = "擊殺毒鉤。", description = "張貼人：法若\n\n毒鉤每天都嘲諷我，尖叫著掃我的興。\n\n誰都好，快把牠殺掉。我不需要證明，我要安靜祥和的生活。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
