MultiLanguageQuestData['tw'][35736] = {title = "難解的字跡", objective = "將破損的日誌書頁交給你要塞中的洛克漢。", description = "這是暗影獵手普雅日誌中磨損的一頁，似乎是血槌奴役礦坑入口的草圖。你要塞中的洛克漢應該會對這個有興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35737] = {title = "難解的字跡", objective = "將破損的日誌書頁交給你要塞中的伯德里克‧格雷。", description = "這是歐維恩‧葛瑞達克日誌中磨損的一頁，似乎是血槌奴役礦坑入口的草圖。你要塞中的伯德里克‧格雷應該會對這個有興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35738] = {title = "自然而燃", objective = "从古树身上收集30份新鲜的木炭。", description = "哦，你有一处走私者巢穴？\n\n我是很想和你做交易，但伙伴你看，我的镭射加农炮有点问题。\n\n我跟你说啊，看见周围这些古树了没有？他们都被烤焦了，成了名副其实的木炭。带点这种焦炭来，好让我给这玩意儿充能，然后我们就可以开始交易了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35739] = {title = "天然資源", objective = "從古樹身上收集30塊新鮮的木炭。", description = "喔，你有交易站啊？\n\n太好了！\n\n我們來做個交易吧。你幫我雷射砲加滿能源，我就拿這些…熱能…終極…黑曜玻璃跟你交易武器。\n\n被阿拉卡武器擊中後，這周圍的古樹變得跟木炭沒兩樣，去拿一些來吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35744] = {title = "阻止處決", objective = "殺死3個鋼鐵戰線劊子手。", description = "我們盡快趕過來了…但還是太遲了。我方士兵淪為鋼鐵部落的俘虜。\n\n他們現在一定在逼問我們的人，想取得重要情報。\n\n我怕他們只要問到了想要的情報之後，便會毫不遲疑地處決囚犯。時間正一分一秒流逝。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n進階戰鬥機制\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35745] = {title = "鋼鐵部落的攻擊", objective = "殺死8個鋼鐵戰線蠻兵。", description = "我們接到報告，黑暗之門在攻擊展開前變成了紅色。他們自稱鋼鐵部落，但似乎與我們所知的部落並無任何關係。\n\n他們部隊裝備十分精良，而且數量源源不絕。\n\n他們已經拿下守望堡和歐克里隆堡。我們在前線的部隊會需要你的協助，<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "侵略者的血色徽印傳送門破壞者指環黑石璽戒紅寶石之眼徽印藍寶石徽印您會收到：\n\n"}
MultiLanguageQuestData['tw'][35746] = {title = "受到包圍", objective = "破壞3台鋼鐵石毀車。", description = "那些鋼鐵部落的大砲正在摧毀我們的部隊。我不確定在這樣的攻勢下我們還能撐多久。我們的戰線已經延伸地太過薄弱了。\n\n一定得找出個辦法來阻止那些戰爭機器。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n存活戰鬥\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35747] = {title = "坦克上一遊", objective = "與塞林‧暗砧談話，然後護送他到鋼鐵碎界者上。", description = "我們不能讓黑暗之門再度開啟。該是給予他們致命一擊的時候了。\n\n塞林應該已經搞清楚要怎麼使用那台坦克了。帶他一起去，並利用坦克毀掉黑暗之門。我們會跟隨著你。", progress = nil, completion = "這個…我可以試試看。", rewards = "您會學到：\n\n第四階天賦解鎖\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35748] = {title = "危險的斥候", objective = "殺死5個鋼鐵部落斥候。", description = "我們大多數的作戰計畫都沒辦法執行，一定有人在監視我們。\n\n鋼鐵部落在詛咒之地各處一定設有斥候。勝利正不斷離我們遠去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35750] = {title = "瘋狂的副官", objective = "取得鋼鐵部落作戰計畫。", description = "該是時候深入了解我們的敵人了。\n\n我們的斥候已經辨識出一部分的鋼鐵部落副官。他們的攻擊太過有組織，已經不是單純的部族戰鬥可比擬了。他們的副官一定有秘密的戰鬥計畫。\n\n你是我唯一信任能完成此項任務的士兵，<name>。您會學到：\n\n", progress = nil, completion = nil, rewards = "顱齒項圈迅敏項鍊囓咬之齒餘燼之怒頸飾閃避之鍊您會學到：\n\n操作機制\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35751] = {title = "攻擊守望堡", objective = "在守望堡內放置部落旗幟。", description = "鋼鐵部落控制著守望堡，但如果他們認為我們不會回來收復失土，那就大錯特錯了。\n\n我旗下最優秀的部隊已經迫不及待想殺幾個野蠻人，但我們需要像你這樣的勇士領導衝鋒。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n冷卻時間\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35759] = {title = "Nagrand - Treasure 065 - Abandoned Cargo", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][35760] = {title = "殲滅者牙碎", objective = "殺掉殲滅者牙碎", description = "如果你帶回來的戰鬥計畫是真的，那巨槌巨魔就跟鋼鐵部落一樣該為這場災難負責。是時候送這些巨魔一個訊息了。\n\n鋼鐵部落在巨槌的主要聯絡人似乎是一個體型龐大，叫牙碎的巨槌巨魔。殺掉他將會重創他們的戰鬥計畫。您會學到：\n\n", progress = nil, completion = nil, rewards = "野火之風披風塑霜者斗篷屠夫裹布振奮巨披風暗夜徘徊者披風您會學到：\n\n天賦解鎖\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35761] = {title = "洗劫守望堡", objective = "收集艾托克大師的斧頭、內卡的毒藥瓶、和監督者斯楚克的盾牌。", description = "我們在鋼鐵部落拿下守望堡後展開攻擊。我們雖然殺掉在守望堡的鋼鐵部落，他們又經由傳送門派遣更多部隊，拿下了歐克里隆堡。太多弟兄被這些野蠻人所殺。\n\n我們絕不能忘記為守望堡犧牲性命的弟兄們。拜託你，如果你找到任何死去弟兄的遺物，請把它們帶回給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35762] = {title = "巨槌之死", objective = "殺死8個巨槌巨魔。", description = "巨槌巨魔的愚蠢總是讓我驚訝不已。鋼鐵部落顯然在利用他們達到自己邪惡的目的。\n\n無論如何，我們必須讓巨魔知道與真正的部落作對有何下場。我想是送給巨槌巨魔們一個訊息的時候了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35763] = {title = "加邁克‧刃旋", objective = "殺死加邁克‧刃旋。", description = "多虧你收集的情報，我們知道這次攻擊是由一個力量強大的鋼鐵部落獸人所引導，他的名字叫加邁克‧刃旋。他正駐紮在歐克里隆堡裡。\n\n殺掉他並不會幫我們贏得戰爭，但一定會破壞鋼鐵部落的通訊，讓我們能有更多時間調集更多軍力，擬出應對這個新威脅的戰鬥計畫。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n技能徹底解鎖\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35764] = {title = "歐克里拉的復仇", objective = "對巨槌巨魔的食物補給下毒。", description = "巨槌巨魔認為他們已經打敗我們了？他們所有人都會付出代價。來，拿著這個毒藥，滴幾滴在他們的燉鼠肉裡。毒藥將慢慢侵蝕他們的內臟，造成緩慢而痛苦的死亡，這是他們罪有應得。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35765] = {title = "Nagrand - Treasure 049 - Adventurer's Pack", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][35766] = {title = "我看到了死鸦人", objective = "使用驱鬼者12000型，并消灭鸦爪祭司泽克的鬼魂。", description = "我现在遇到了一个非常诡异的问题，你或许能帮上忙。我都不知道该找谁了。\n\n我的工人们一直说他们撞见了以前这里的一个鸦人的鬼魂。\n\n我知道，我知道，这听起来太疯狂了。但你能不能用我的驱鬼者12000型去检查一下她的尸体？假如附近真的有鬼，它就能找到的。要是找不到，那肯定就是我的工人在浑水摸鱼了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
