MultiLanguageQuestData['tw'][35828] = {title = "我是天生嘲諷臉", objective = "到荒林小徑找塞林‧暗砧。", description = "$p？真是高興看到你啊。\n\n當我誤闖這座遊俠營地時，我正努力想甩掉那隻傑那索。\n\n回過神來我才發現天地似乎顛倒了，而整窩的憤怒植物傾巢而出。\n\n就在那頭傑那索將我的坦克如同空酒杯般摔出去前，我才好不容易從坦克爬出來。\n\n我會回去路上找我的坦克。\n\n你事情辦完就來找我吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35834] = {title = "傑那索之醒", objective = "殺掉9棵狂亂植物。", description = "前一刻我們才看到一具金屬巨怪開進我們營地，下一秒一頭傑那索就尾隨而來，還派一群狂亂生物攻擊我們。\n\n我們必須收拾傑那索留下來的爛攤子，才能在離開前回收可用的物資。\n\n如果你是來協助我們的，那就開始盡可能殺掉這些攻擊我們的植物吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "蔓生切除肩甲火鑄鎧甲護肩氣爆披肩野木牧者護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][35835] = {title = "黯黑獵人", objective = "從黯黑獵人身上收集一個有機雷射器官。", description = "我們準備要架設雷射裝置了，但我們還要更強的火力才有辦法切割這東西。\n\n有個「黯黑獵人」潛伏在這東南方的三角洲，它的臉上有個能發射強力雷射的器官，威力比我們所裝設過的裝置都還強。\n\n我們需要那東西。\n\n你應該趁我們做好架設時將那東西拿回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n哨站建築組裝筆記"}
MultiLanguageQuestData['tw'][35836] = {title = "Nagrand - Vignette Boss 008 - The Lunker", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][35837] = {title = "要塞戰役：深入調查", objective = "到納葛蘭的秘密營地找珍寧‧安瑞爾。", description = "珍寧‧安瑞爾是我手下其中一名頂尖外勤探員，她前一陣子深入納葛蘭北方的鋼鐵部落境內。\n\n她發現獸人氏族的酋長正計畫在莫克戈爾哨站秘密集結。\n\n這對我們可能是個收集關於他們未來計畫情報的大好機會。\n\n我需要你立刻與安瑞爾探員會面。我們必須好好把握這次機會，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35838] = {title = "酋長會議", objective = "找出這張字條是誰寫的。", description = "靠近檢查後，你發現她脖子上綁了一張羊皮紙。\n\n上面寫了一段十分憤怒的話：\n\n「違逆鋼鐵部落便是如此下場！」您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35839] = {title = "戰爭計畫", objective = "找到格古瑞克等比模型、迷你戰爭機器和塔南森林的地圖。", description = "我想辦法看到了珍寧的筆記本。她在附近的建築物找到幾項值得調查的關鍵物品，但在死去之前來不及追查。\n\n我們至少可以追查這條線索，看看她為我們留下了什麼。\n\n搜索營地中的任何情資。我負責讓獸人分心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35840] = {title = "攔截命令", objective = "收集霜火任務指令、影月任務指令、和阿拉卡山任務指令。", description = "最重要的是情報戰，朋友。我們對地獄吼的計畫了解越多，就越有機會跟他們對抗。\n\n莫克戈爾獸人時常被指派為地獄吼的信使，從此處攜帶任務指令至地獄吼位於德拉諾各處的哨站。\n\n殺掉這些騎兵，將你能找到的指令帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35841] = {title = "撲滅首惡", objective = "擊殺首領弗葛許。", description = "莫克戈爾哨站的各項行動都交由首領弗葛許來負責，他是一位強大的戰士。\n\n如果我們能除掉這個勇猛的首領，便能暫時癱瘓他們的通訊。\n\n弗葛許在東北邊的基地巡邏。\n\n殺掉他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35842] = {title = "撲滅首惡", objective = "擊殺首領弗葛許。", description = "負責莫克戈爾哨站的人是首領弗葛許。\n\n只要除掉他，就能封鎖他們的攻勢。\n\n弗葛許在東北邊的基地巡邏。\n\n把他殺了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35843] = {title = "要塞戰役：深入調查", objective = "到納葛蘭的秘密營地找暗影獵手札斯塔。", description = "你的時機正好，指揮官。\n\n前一陣子，我派出手下其中一名頂尖的暗影獵手深入敵境探查。\n\n他說那些酋長正打算秘密集結於莫克戈爾哨站。\n\n這是我們了解地獄吼有何意圖的好機會。\n\n去吧，與札斯塔會面。他會告訴你接下來怎麼做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35844] = {title = "酋長會議", objective = "找出這張字條是誰寫的。", description = "靠近檢查後，你發現他脖子上綁了一張羊皮紙。\n\n上面寫了一段十分憤怒的話：\n\n「違逆鋼鐵部落便是如此下場！」您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35845] = {title = "戰爭計畫", objective = "找到格古瑞克等比模型、迷你戰爭機器和塔南森林的地圖。", description = "我找回了札斯塔的筆記。他看到戰歌領導者經常在附近的建築物裡開會。札斯塔認為附近一定可以找到和鋼鐵部落計畫有關的線索。\n\n至少，我們可以追查他留下的這條線索。\n\n搜索營地中的任何情資。我負責讓獸人分心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35846] = {title = "攔截命令", objective = "收集霜火任務指令、影月任務指令、阿拉卡山任務指令。", description = "最重要的是情報戰，指揮官。我們對地獄吼的計畫知道得越多，就越容易破壞它。\n\n那莫克戈爾獸人是地獄吼的信使，從此處將任務指令送往地獄吼位於德拉諾各處的哨站。\n\n殺掉這些騎兵，取回任何你能找到的指令。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
