MultiLanguageQuestData['tw'][35882] = {title = "布魯多的興趣", objective = "接受大劍師奈許菈的血誓", description = "你幫了我很大的忙，這把劍說是我鑄的，其實也等於你鑄的。\n\n我謹此立下血誓，貢獻我對鑄劍和採礦的知識，為你效命。\n\n你接受嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者： 布魯多\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35883] = {title = "范達姆之拳", objective = "接受大劍師奈許菈的血誓", description = "你幫了我很大的忙，這把劍說是我鑄的，其實也等於你鑄的。\n\n我謹此立下血誓，貢獻我對鑄劍和採礦的知識，為你效命。\n\n你接受嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：鬥士范達姆\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][35884] = {title = "最後衝刺", objective = "逃到碼頭去。", description = "就算之前沒讓他們發火，現在也一定惹毛他們了。待在這台坦克上面的話根本撐不了一分鐘。\n\n我們快點和其他人會合，然後離開這裡吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
