MultiLanguageQuestData['tw'][35914] = {title = "Internal: Default Invasion Reward", objective = "擊退侵略要塞的破源者。\n\n(再次與士官邪顎談話即可開始)", description = "這一小時以來要塞不斷發生地震，我們一些斥候也還沒有回報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35915] = {title = "謀殺未遂", objective = "與弗恩‧迅風談話，取得前往暗影警戒的飛行路線。", description = "柯爾雷格快死了，指揮官。他中了毒，得在一切都太遲之前取得解毒劑。\n\n你的一位斥候曾經回報沒多久之前看到破碎之手的獸人在附近出沒 - 我敢打賭那個可能性最大。\n\n在東邊人盡皆知的破碎之手營地附近，有一個阿拉卡小營地。我們該要從那邊著手搜尋，<長官/女士>。\n\n我已經和飛行管理員談過如何把我們送出去；每一秒鐘都很寶貴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
