MultiLanguageQuestData['tw'][35921] = {title = "麵包與競技", objective = "到試煉競技場，與德賽爾‧亡刃談話。", description = "嗨，<先生/女士>，這笨蛋不讓我進去。對白花花的鈔票有興趣嗎？\n\n我的老闆正在宣傳試煉競技場的打鬥。你看來有兩下子。\n\n你應該去試試看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][35922] = {title = "麵包與競技", objective = "到試煉競技場，與德賽爾‧亡刃談話。", description = "嗨，<先生/女士>，這笨蛋不讓我進去。對白花花的鈔票有興趣嗎？\n\n我的老闆正在宣傳試煉競技場的打鬥。你看來有兩下子。\n\n你應該去試試看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
