MultiLanguageQuestData['tw'][35970] = {title = "保護重要資本", objective = "收集紅牙項鍊、紫牙項鍊和巨魔半身塑像。", description = "我在尋找珍貴的文物，可以解答一些德拉諾最大謎團的那種文物，然後讓熱砂保護協會賺進一大筆錢。女人就是愛錢，你瞭吧？\n\n所以呢，將文物帶給我吧，女人歸我，而你可以得到…等等，你說你在尋找什麼？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
