MultiLanguageQuestData['tw'][36119] = {title = "歡迎來到艾斯蘭", objective = "到暴風之盾和指揮官安妮‧敦沃希交談。", description = "你好，歡迎來到艾斯蘭。\n\n請到暴風之盾向指揮官安妮‧敦沃希報到以聽取簡報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36123] = {title = "進入荒野", objective = "在暴風之盾堡壘的克里斯‧克拉奇，要你去殺死主要道路外圍的任何一名部落成員，並從對方身上取回一片護甲做為證明。", description = "<name>，在這塊大地上，榮耀之路並不限於征戰平原。我們必須進入此地的荒野才能找回神器。\n\n勇敢向前，殺死你在外圍區域遇到的部落成員，從他們倒下的屍體收集護甲碎塊帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36124] = {title = "Jared's Test Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][36125] = {title = "榮耀之路", objective = "暴風之盾的克里斯‧克拉奇要你去殺死榮耀之路上的5位部落成員。", description = "部落想要把我們逼出艾斯蘭，<name>。我們不能讓他們成功。前往榮耀之路，削弱他們的數量，至少五人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36127] = {title = "調查艾斯蘭", objective = "暴風之盾的先知凱蘭達要你去探索艾斯蘭的這些地方：榮耀之路、熔岩礦場、蠻卒高崗、殲滅露天競技場，以及燼槌墓地。", description = "身為先知，我在暴風之盾就能看到艾斯蘭的每個角落。但是你必須親自到每個地方去看看，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\nS.O.S.救援信號槍"}
