MultiLanguageQuestData['tw'][36176] = {title = "獵人的呼喚", objective = "將髒字條交給安伯瑞村的費娜菈以參加比賽。\n\n已提供物品：\n", description = "<字條上的字很模糊，但似乎是安伯瑞村當地狩獵比賽的廣告。>\n\n「歡迎所有參賽者在這狩獵友誼賽中試試身手。」您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36177] = {title = "友誼賽", objective = "收集4張影月皮革和3個銀翼之爪，趕在其他人之前將物資交給費娜菈。", description = "你想參加比賽，<name>？祝你好運。\n\n趕在其他人之前，從本地野生動物身上拿到獸皮和利爪，然後交給我！\n\n贏家有機會成為大師賈拉爾的學徒。\n\n祝你好運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
