MultiLanguageQuestData['tw'][36185] = {title = "公平交易", objective = "賈拉爾正等著你的貨物。\n\n已提供物品：\n", description = "好了，來。\n\n快點把貨物交給賈拉爾。他一向對細緻的手工藝有很大的興趣，一定會喜歡你的東西。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n製皮廠，第1級德拉諾製皮"}
