MultiLanguageQuestData['tw'][36376] = {title = "戈倫入侵！", objective = "擊退侵略要塞的戈倫。\n\n(再次與克羅勒士官談話即可開始)", description = "要塞不斷發生地震，我們的斥候也好幾個小時沒有回報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
