MultiLanguageQuestData['tw'][36481] = {title = "火鳥的挑戰", objective = "在飛行時收集15個火圈。", description = "你準備好航向高空，試試看火鳥的挑戰了嗎？太好了！\n\n只要收集15個火圈就能獲勝！準備好起飛了就跟我說！", progress = nil, completion = "哇，你在上頭飛得很棒，王牌！這是你的獎賞！", rewards = "您會收到：\n\n暗月遊戲獎"}
MultiLanguageQuestData['tw'][36482] = {title = "綠色的歐格隆？", objective = "殺掉被感染的歐格隆。", description = "卡茲總是告訴我綠色歐格隆很邪惡。\n\n這裡的波塔尼有隻綠色的歐格隆，也相當殘暴。\n\n他厲害到解決了我父親整支狩獵隊伍。\n\n你有辦法殺掉他嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "火鑄鎧甲戰靴氣爆足靴野木牧者脛甲蔓生切除長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][36483] = {title = "戰鬥寵物總召集", objective = "擊敗戰鬥區域裡的寵物。", description = "看來今天有些訪客想到我們的戰鬥場來小試身手，你何不讓他們看看寵物戰鬥大師是如何鍛練<他自己/她自己>的？您會收到：\n\n\n\n等級 43–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 43–80磨亮的寵物吊飾\n\n等級 51–70亮晶晶的寵物吊飾"}
MultiLanguageQuestData['tw'][36488] = {title = "偷竊的矮人", objective = "在堡壘高地尋找卡特。", description = "卡特正在追查被矮人偷走的神器。說到叢林狩獵他可是敏銳至極。\n\n沿著峽谷往南走，直到你找到他為止。\n\n看來狼后與我在離開這裡前還要再製造一些傷害。\n\n我們會盡快趕上你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
