MultiLanguageQuestData['tw'][36601] = {title = "納葛蘭的消息", objective = "到影月谷與你要塞裡的伯德里克‧格雷交談。", description = "在你外出時，你的一名士兵前來詢問你的消息，一隊前往納葛蘭的商隊似乎出了事情。\n\n不管是什麼，情況一定對他們不利。那是戰歌的領土。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36602] = {title = "納葛蘭的消息", objective = "到你位於霜火峰的要塞與洛克漢談話。", description = "在你外出時，你的一名士兵前來詢問你的消息，一隊前往納葛蘭的商隊似乎出了事情。\n\n不管是什麼，情況一定對他們不利。那是戰歌的領土。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
