MultiLanguageQuestData['tw'][36623] = {title = "巨魔入侵！", objective = "擊退侵略要塞的巨魔。\n\n(再次與士官邪顎談話即可開始)", description = "指揮官，我們的斥候說有巨魔隊伍正在穿越雪原。如果他們在被我們痛宰一頓之後還是想要討打，我倒是很樂意成全他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36624] = {title = "艾斯蘭的外觀", objective = "在艾斯蘭的暴風之盾和士兵崔斯坦交談。", description = "我們在艾斯蘭的基地幾乎完工了，指揮官。\n\n如果你能夠前往當地，肯定他們在整備區的成果，就可以給予大幅的支持。\n\n如果你願意的話，我可以安排飛行工具。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
