MultiLanguageQuestData['tw'][36669] = {title = "進攻石怒崖", objective = "在霜火峰突擊石怒崖的血槌巨魔。", description = "來自霜火峰的血槌巨魔不斷突襲這片土地的貿易路線，並且把被俘的士兵丟到他們的熔渣礦坑中工作。\n\n暗影獵手洛克漢要求你救出石怒崖的血槌主要營地中，被俘的友軍部隊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36674] = {title = "進攻鋼鐵軍火廠", objective = "前往霜火峰的鋼鐵軍火廠，對鋼鐵部隊發動攻擊。", description = "鋼鐵部落的戰爭機器正大量運往戰場，而我們的部隊也在苦苦支撐。大多數的戰爭機器似乎是在霜火峰東部的鋼鐵軍火廠製造的。\n\n如果想逆轉戰局，一次擾亂並瓦解軍火廠鋼鐵部落的戰略性攻擊，可能正是我們需要的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36675] = {title = "進攻麥奈洛克", objective = "前往霜火峰的麥奈洛克，向岩石巨怪發動攻擊。", description = "巨大的麥奈隆、古羅，還有其他岩石巨怪一直是我們西方哨站的威脅，而看起來他們大多數來自於霜火峰的麥奈洛克。\n\n如果我們攻擊他們的大本營，就應該能強迫他們撤退。雖然相當危險，但這應該是我們最好的戰術了。既然你要去麥奈洛克，那也試著帶點我們的補給品回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36676] = {title = "進攻永茂林野地", objective = "前往格古隆德的永茂林野地，對波塔尼軍隊進行攻擊。", description = "波塔尼和它們製造出來的植物怪獸不斷在蠶食鯨吞我們北方的哨站。不管我們殺了多少，似乎都會有同樣多的敵人在原地長出來。\n\n伯德里克‧格雷已經擬定了一套計畫，攻擊它們在永茂林野地裡的關鍵要地。他認為如此一來它們就會退回格古隆德的荒野，讓我們有更多喘息的空間。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36677] = {title = "進攻破碎絕壁", objective = "前往納葛蘭的破碎絕壁，對歐格隆部隊發動進攻。", description = "大量的歐格隆正在猛攻我們的前線，而且不管我們打倒多少敵人，都會有更多的人補上。\n\n大部分的歐格隆似乎來自破碎絕壁，位於納葛蘭西部深處。如果我們想在接下來的戰事中掌握一線生機的話，我們就要想辦法讓這些歐格隆離開戰場。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36678] = {title = "襲擊莫克戈爾哨站", objective = "前往納葛蘭的莫克戈爾哨站對戰歌部隊發動攻擊。", description = "莫克戈爾哨站派出的戰歌劫掠者不斷威脅著不受高牆保護的地區。我們已經警告旅人不要獨自在外行動，但還是有許多人充耳不聞。\n\n如果我們可以對莫克戈爾哨站發動一場攻擊，就很有可能讓戰歌獸人必須回防，並且讓劫掠者的活動區域限制在納葛蘭境內。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36679] = {title = "進攻暗潮棲息地", objective = "前往影月谷的暗潮棲息地，對鋼鐵部落部隊發動攻擊。", description = "在對抗鋼鐵部落的遭遇戰當中，我們發現戰場上萊拉克的數量源源不絕。如果我們不斬斷萊拉克的來源的話，很快就會失去道路的控制權，然後被迫撤退到哨站裡面。\n\n這些額外的萊拉克很有可能來自於影月谷東南方的暗潮棲息地。如果我們動作夠快的話，就還有可能在問題擴大之前解決一切。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36680] = {title = "進攻索奎薩爾高地", objective = "前往影月谷的索奎薩爾高地，對薩格萊部隊發動攻擊。", description = "目前情報顯示，影月谷南方索奎薩爾高地的薩格萊部隊開始頻繁活動。\n\n索奎薩爾信徒不只是對德萊尼，也會對我們的要塞造成威脅。我們必須盡快擊潰他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36681] = {title = "進攻失落的維爾安祖", objective = "在阿拉卡山的失落的維爾安祖向敵對生物發動攻擊。", description = "我們有些頂尖的斥候一到失落的維爾安祖廢墟附近，就會失去蹤影。\n\n伯德里克‧格雷要求派出任何可用的資源，以明辨威脅的源頭並探查廢墟中是否還有倖存者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36682] = {title = "進攻命運之柱", objective = "突襲影月谷中，位於命運之柱的影月獸人。", description = "殘存的影月氏族還持續地在阿拉卡山東側邊界的山上行動。\n\n伯德里克‧格雷顧忌他們太過靠近要塞，因而要求我們盡快削弱他們的兵力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36683] = {title = "進攻司凱堤斯", objective = "突擊阿拉卡山、司凱堤斯境內的魯克馬爾擁護者。", description = "我們經常接獲回報，指出來自南方的鳥人會突襲並燒毀大路上的商隊。\n\n位於我方前哨站的守衛要求對位於阿拉卡山，司凱堤斯境內的魯克馬爾擁護者展開反擊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36684] = {title = "艾斯蘭之戰", objective = "參加艾斯蘭的戰鬥。", description = "當我們在德拉諾四處交戰時，懦弱的部落趁機侵佔我們在艾斯蘭的領土。\n\n如果你能進入戰場，將恐懼深植在部落士兵的心中，絕對能夠讓我們的弟兄士氣大振。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36685] = {title = "進攻撒塔斯的中心", objective = "前往塔拉多爾的撒塔斯城深處，對薩格萊部隊發動進攻。", description = "撒塔斯深處的薩格萊部隊一天比一天壯大。我們已無法再坐視他們造成的威脅了。\n\n如果你決定與城市深處的薩格萊部隊交戰，請帶著戰友。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][36686] = {title = "進攻廢坑", objective = "對格古隆德廢坑的黑石獸人發動進攻。", description = "根據地在格古隆德廢坑的黑石獸人部隊為鋼鐵部落提供了大量軍力。如果我們可以踏平他們的領土，那麼鋼鐵部落的殘黨也會失去與我們對抗的信心。\n\n如果你決定要戰鬥的話，帶上你的朋友。黑石獸人可不太容易對付。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
