MultiLanguageQuestData['tw'][36923] = {title = "死敵：死亡化身", objective = "在德拉諾裡的玩家對玩家戰鬥中，殺死一位矮人玩家，並取回矮人心臟。", description = "你已經選定獵物，他們肯定很快就會體驗到你的無情怒火。但首先，你得深入德拉諾的荒野，在生死決鬥中挖出矮人還在跳動的心臟，然後帶著你的戰利品回到此處。\n\n透過敵人的心臟，魂靈會強化你的感官，賦予你洞穿敵人的視力和敏銳的聽覺。讓你更容易追蹤獵物，斬殺死敵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36924] = {title = "死敵：矮人獵殺者", objective = "在德拉諾的玩家對玩家戰鬥中，殺死500位矮人玩家。", description = "<拉札庫爾把血淋淋的心臟遞給了你。>\n\n儀式完成了，死亡已經標示在你的死敵身上。\n\n現在你的工作才算正式開始，把敵人從這個世界上清光吧。殺光膽敢對抗部落的矮人，用他們的死亡去警告其他的聯盟成員：離開德拉諾，不然只有死路一條。\n\n在你用矮人的鮮血平息怒火之後再回來。\n\n征服我們的敵人，化身為矮人獵殺者。別失敗了，否則你什麼都不是。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36925] = {title = "死敵：死亡化身", objective = "在德拉諾裡的玩家對玩家戰鬥中，殺死一位地精玩家，並取回地精心臟。", description = "你已經選定獵物，他們肯定很快就會體驗到你的無情怒火。但首先，你得深入德拉諾的荒野，在生死決鬥中挖出地精還在跳動的心臟，然後帶著你的戰利品回到此處。\n\n透過敵人的心臟，魂靈會強化你的感官，賦予你洞穿敵人的視力和敏銳的聽覺。讓你更容易追蹤獵物，斬殺死敵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36926] = {title = "死敵：地精煞星", objective = "在德拉諾的玩家對玩家戰鬥中，殺死500位地精玩家。", description = "<拉札庫爾把血淋淋的心臟遞給了你。>\n\n儀式完成了，死亡已經標示在你的死敵身上。\n\n現在你的工作才算正式開始，把敵人從這個世界上清光吧。殺光膽敢對抗部落的地精，用他們的死亡去警告其他的聯盟成員：離開德拉諾，不然只有死路一條。\n\n在你用地精的鮮血平息怒火之後再回來。\n\n征服我們的敵人，化身為地精煞星。別失敗了，否則你什麼都不是。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36927] = {title = "宿敌：化为死神", objective = "在德拉诺的PvP战斗中击败一名狼人玩家，并夺取他们身上的狼人之心。", description = "你已经选好了目标，他们很快就能感受到你无情的怒火，但首先，你必须深入德拉诺的荒野，在一场生死大战中将一位狼人跳动的心挖出来。带着你的战利品回来找我吧。\n\n通过敌人的心，灵魂将与你的感知力相协调，使你获得超人的视野与敏锐的听觉——更加便于你追踪猎物，占尽优势。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
