MultiLanguageQuestData['tw'][36944] = {title = "制服一頭野豬", objective = "對著年輕的石牙野豬使用野豬套索並跟著牠，直到馴服牠為止。", description = "在格古隆德的野豬不但可以當做坐騎，也是絕佳的食物來源。在要塞中留幾頭的確不失為明智之舉。\n\n如果真的打算騎馬捕捉一頭，我幫你做了另一條套索。小心附近有鋼鐵部落出沒。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36945] = {title = "徵用河獸", objective = "對著年輕的污泥河獸使用河獸套索並跟著牠，直到馴服牠為止。", description = "我曾經在塔拉多爾的河流中，看過一種巨獸在水中緩慢的漂浮著。我認為這種生物會被稱為「河獸」。\n\n牠們的皮革很結實，硬的像石頭，而且可以輕鬆漂在水面上。要是你打算前往那個方向的話，我很想仔細看看這些生物。如果你有興趣的話，托邁克已經幫你做了另一條繩子。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36946] = {title = "驯服雷象", objective = "对一只幼年草地践踏者使用雷象套索，跟着它直到将它驯服。", description = "纳格兰平原是我见过的最肥沃，最葱翠的土地。你可以在那里看到这片大陆上最强大的一些野兽。\n\n雷象就是其中之一。这种巨兽的一根长牙都可能长得比你我都要巨大。\n\n假如你对驯服这种野兽有兴趣的话，这是我准备的套索。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36947] = {title = "新的力量", objective = "您會學到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n托爾瑪克技能：化身"}
MultiLanguageQuestData['tw'][36948] = {title = "買賣零件", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][36950] = {title = "馴養一頭狼", objective = "對著年輕的咆哮者使用野狼套索並跟著牠，直到馴服牠為止。", description = "這塊土地上的狼群有著鋼鐵般的下顎。難怪獸人會想要將牠們納入麾下。\n\n不過在納葛蘭深處，還是有一些適合馴服的年輕狼群。對你而言，牠們會是項很大的挑戰，畢竟那是這塊土地上最快速、最敏捷的生物。\n\n這是你最後一根繩索了，願好運與你同在。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36951] = {title = "出阿拉卡記", objective = "在阿拉卡山和阿茲卡交談。", description = "我想你應該很了解阿拉卡吧，指揮官？體型龐大、會飛的鳥人族，地域觀念很重。\n\n他們當中有些人的翅膀萎縮了，可能是某種疾病的緣故吧。這些人好像被阿拉卡給放逐了。你有時會看到他們棲身在被遺忘的廢墟裡，或在路邊販賣飾品維生。\n\n看樣子鋼鐵部落已經進駐了他們的領地，煽動了阿拉卡，這些流亡者則紛紛逃離。\n\n我們應該和這些流亡者取得聯繫，他們或許有重要的情報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36952] = {title = "烽火納葛蘭", objective = "到納葛蘭的車隊處與石衛士布洛克斯談話。", description = "**機密 -- 指揮官<name>**\n\n杜洛坦建議我們在納葛蘭建立新據點，所以我派出了一些手下。\n\n索爾回報外面已經快完工了，要我告訴你他們已經在等你了。\n\n我已經幫你備妥蠍尾獅，可以隨時送你過去趕上車隊，<先生/女士>。\n\n-- 洛克漢您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36953] = {title = "戰略考量", objective = "和布隆‧天角交談，飛往塔拉多爾。", description = "**機密 -- 指揮官 <name>**\n\n鋼鐵部落證明了自己是個值得挑戰的對手。\n\n他們設法將艦隊從格古隆德移到塔拉多爾，並且逃過我方間諜的監視。塔拉多爾是整塊大地的中樞點。我們不能把這塊地區拱手讓出。\n\n別擔心，老大，我們已經準備好應對計畫了。在我們交談的同時，工頭葛羅巴什已經開始為我們的部隊架設崗哨。在你抵達時一切應該都準備好了，指揮官。\n\n-- 洛克漢您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36955] = {title = "死敵：獵人 - 獵物", objective = "在鬥士會堂燒掉一個死敵肖像，並和庫洛斯交談。", description = "敵人已經將我們重重包圍了，而且每過一天，他們的數量有增無減。該是下定決心，直擊他們軍隊的時候了，勇士。\n\n在我身邊放的是我們最痛恨的對手肖像。你會讓他們就此敗亡，<name>。你將成為他們的死敵，讓他們看到你就驚惶逃竄。\n\n現在選定你的怒火要燒向何方，並燒掉該種族的肖像。做好選擇之後，和我交談。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][36956] = {title = "Nemesis Flag, Human", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][36957] = {title = "死敵：死亡化身", objective = "在德拉諾裡的玩家對玩家戰鬥中，殺死一位血精靈玩家，並取回血精靈心臟。", description = "你已經選定獵物，他們肯定很快就會體驗到你的無情怒火。但首先，你得深入德拉諾的荒野，在生死決鬥中挖出血精靈還在跳動的心臟，然後帶著你的戰利品回到此處。\n\n透過敵人的心臟，他們的靈魂會強化你的感官，賦予你洞穿敵人的視力和敏銳的聽覺。讓你更容易追蹤獵物，斬殺死敵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36958] = {title = "死敵：辛多雷屠殺者", objective = "在德拉諾的玩家對玩家戰鬥中，殺死500位血精靈玩家。", description = "<庫洛斯爾把血淋淋的心臟遞給了你。>\n\n儀式完成了，死亡已經標示在你的死敵身上。\n\n現在你的工作才算正式開始，把敵人從這個世界上清光吧。殺光膽敢對抗聯盟的血精靈，用他們的死亡去警告其他的部落成員：離開德拉諾，不然只有死路一條。\n\n在你用血精靈的鮮血平息怒火之後再回來。\n\n征服我們的敵人，化身為辛多雷屠殺者。別失敗了，否則你什麼都不是。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][36959] = {title = "死敵：死亡化身", objective = "在德拉諾裡的玩家對玩家戰鬥中，殺死一位被遺忘者玩家，並取回被遺忘者心臟。", description = "你已經選定獵物，他們肯定很快就會體驗到你的無情怒火。但首先，你得深入德拉諾的荒野，在生死決鬥中挖出被遺忘者幾近死寂的心臟，然後帶著你的戰利品回到此處。\n\n透過敵人的心臟，他們的靈魂會強化你的感官，賦予你洞穿敵人的視力和敏銳的聽覺。讓你更容易追蹤獵物，斬殺死敵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
