MultiLanguageQuestData['tw'][37027] = {title = "狼之訓練：獸人獵手", objective = "在騎乘訓練中的咆哮者時打敗偉大獵人卡拉克。", description = "我曾經不幸碰上那些納葛蘭的戰歌氏族，他們的確算是最出色的獵手之一。如果有人想替未來的坐騎找個真正的考驗，那非得找那些王牌野獸殺手不可。\n\n在納葛蘭你會找到一個名為卡拉克的獸人，他有個「偉大的獵人」的稱號，因為他比氏族裡的任何人殺掉了更多兇猛的野獸。以那些可憐野獸之名，踏上你的狼擊敗他！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37028] = {title = "狼之訓練：岡恩", objective = "在騎乘訓練中的咆哮者時打敗殘爪。", description = "我還有最後一項挑戰要給你，指揮官，但這回可一點都不簡單。\n\n岡恩狼像夜晚一樣漆黑，體型比一般的狼足足大上兩倍，幾秒鐘就能把人撕碎。任何腦袋正常的野獸一看到這樣的獵食者，馬上會嚇到六神無主。\n\n有一頭落單的岡恩從霜火峰的老家一路跑到了納葛蘭。帶著你的狼，騎上去，然後打敗牠。如果你們兩位都倖存，那你的狼就準備好了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n訓練過的咆哮者要塞資源"}
MultiLanguageQuestData['tw'][37029] = {title = "黑手符印", objective = "在普通困難度之下，從黑石鑄造場每一區的最後首領身上，收集4塊山之餘燼、4枚石之心，以及4片鋼鐵裂片。", description = "<古拉魯克嘆了口氣，帶著…解脫？…或是悔恨之意？>\n\n我曾經帶著自傲走過這些通道，像個黑石氏族的獸人一樣抬頭挺胸。但這條路是錯的。我們的錘子原本是用來打造斧頭、刀劍…而不是陌生人在低語聲中描述的機器。\n\n督軍不會動搖，但卻受到脅迫。如果你能夠取得鑄造場中最強大守護者的精華，我就可以幫你打造出一枚符印，讓你直接進入黑手的大爐缸。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n黑手符印\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37030] = {title = "黑手符印(英雄)", objective = "在英雄難度之下，從黑石鑄造場每一區的最後首領身上，收集4塊山之餘燼、4枚石之心，以及4片鋼鐵裂片。", description = "<古拉魯克嘆了口氣，帶著…解脫？…或是悔恨之意？？>\n\n我曾經帶著自傲走過這些通道，像個黑石氏族的獸人一樣抬頭挺胸。但這條路是錯的。我們的錘子原本是用來打造斧頭、刀劍…而不是陌生人在低語聲中描述的機器。\n\n酋長不聽任何勸告，只能採取強硬手段。如果你能夠取得鑄造場中最強大守護者的精華，我就可以幫你打造出一枚符印，讓你直接進入黑手的大爐缸。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n黑手符印\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37031] = {title = "黑手符印(傳奇)", objective = "在傳奇難度之下，從黑石鑄造場每一區的最後首領身上，收集4塊山之餘燼、4枚石之心，以及4片鋼鐵裂片。", description = "<古拉魯克嘆了口氣，帶著…解脫？…或是悔恨之意？？>\n\n我曾經帶著自傲走過這些通道，像個黑石氏族的獸人一樣抬頭挺胸。但這條路是錯的。我們的錘子原本是用來打造斧頭、刀劍…而不是陌生人在低語聲中描述的機器。\n\n酋長不聽任何勸告，只能採取強硬手段。如果你能夠取得鑄造場中最強大守護者的精華，我就可以幫你打造出一枚符印，讓你直接進入黑手的大爐缸。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n黑手符印\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37032] = {title = "野豬訓練：笞劈", objective = "在騎乘訓練中的野豬時打敗笞劈。", description = "這頭野豬以格古隆德的崎嶇平原為家，所以在訓練上容易一點。和其他野獸一樣，我們先從牠們的家園展開訓練。\n\n做為考驗，我們先讓你的野豬對抗強大的掠食者笞劈，這頭迅猛龍經常獵殺野豬。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37033] = {title = "野豬訓練：格茲朗", objective = "在騎乘訓練中的野豬時打敗格茲朗。", description = "在德拉諾上，有許多生物在最危險的環境裡生長的欣欣向榮。而其中最狡詐的生物之一就是潛獵者。\n\n潛獵者可以融入環境，讓他們溜過附近的獵物，偷走牠們的蛋。看看你和你的野獸能不能克服這種大自然的防禦機制。你可以在塔拉多爾找到適合你的掠食者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37034] = {title = "野豬訓練：布巴波爾", objective = "在騎乘訓練中的野豬時打敗布巴波爾。", description = "在南邊遠方的阿拉卡山裡，土地被生長在水下的蘑菇吞噬，奇怪的真菌生物無止盡的生長。\n\n和其中一隻怪異生物對抗，例如真菌巨人布巴波爾，會是個讓你的坐騎面對牠完全不熟悉掠食者的大好機會。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37035] = {title = "野猪训练：凶残的食人魔", objective = "骑着你的训练中的石牙野猪去击败高里亚驱兽者。", description = "在纳格兰居住着德拉诺最强大的野兽，而且那里的食人魔使用一种非常残忍的手段驯养他们。\n\n其中，又数那个叫高里亚驱兽者的尤为凶残。他浑身充满了血腥和恐惧的气息。让我们瞧瞧你的坐骑面对他是否还能面不改色。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37036] = {title = "野猪训练：暗翼大鹏", objective = "骑着你的训练中的石牙野猪去击败暗翼大鹏。", description = "纳格兰的风鹏是一种非常聪明的捕食者，它们经常成群结队地突袭猎物。要是你的坐骑不时刻注意着天空的话，就可得跟它这双眼睛说再见了。\n\n去纳格兰干掉那里最凶猛的风鹏——暗翼大鹏。这对你的坐骑来说是个不错的试炼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37037] = {title = "野猪训练：暴怒飞蛾", objective = "骑着你的训练中的石牙野猪去击败暴怒飞蛾。", description = "在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。\n\n如果它能让附近的野狼都不得不退避三舍，这对你的野猪来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37040] = {title = "野豬訓練：獸人獵手", objective = "在騎乘訓練中的野豬時打敗偉大獵人卡拉克。", description = "在納葛蘭的戰歌氏族裡，可以找到整個德拉諾中無人能出其右的獵人。他們是專門對付野獸的殺手，可以讓我們進一步考驗這頭野獸。\n\n在納葛蘭中，你會找到一位名叫卡拉克，稱號是「偉大的獵人」的獸人。因為他打倒的殘暴野獸比氏族的其他人都還要多。騎在你的坐騎身上面對他，並為被屠殺的野獸復仇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37041] = {title = "野豬訓練：岡恩", objective = "在騎乘訓練中的野豬時打敗殘爪。", description = "你的坐騎要面對的最後考驗，就是對抗這塊土地上最可怕的野獸。\n\n岡恩。毛色像夜晚一樣黑，體型比一般的狼還大上兩倍，短短一瞬間就可以撕碎一個獸人。所以這裡的野獸會怕牠們也是合理的。\n\n有隻落單的岡恩跑到納葛蘭去了，騎上你的野豬打敗牠吧。如果你們兩個都倖存下來的話，那你的野豬就訓練完成了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n訓練過的石牙野豬要塞資源"}
MultiLanguageQuestData['tw'][37043] = {title = "鋼鐵碎塊", objective = "從德拉諾的鋼鐵部落身上，收集5塊鋼鐵部落碎塊。", description = "在軍械庫中，我們可以收集你帶來的鋼鐵部落護甲碎塊，並轉變成新的器具。那並不是世界上最強大的東西，但是看起來真的不錯。\n\n取得一些鋼鐵部落的碎塊，再回來找我。在你努力之餘，我會幫你做一件很棒的外袍。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n奧格瑪外袍"}
MultiLanguageQuestData['tw'][37044] = {title = "不按常規的發明", objective = "在你的哥布林工坊中，從工作桌上取得一項發明。", description = "在是一個非常忙碌的工坊，我們隨時都有新發明。你可以在我背後的工作桌找到發明成果。\n\n去看看今天最棒的發明。歡迎使用，但風險自負。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37045] = {title = "回收狀況", objective = "在回收場中的焚化爐旁邊，使用小袋的回收貨物。", description = "在回收場裡面，我們會檢查追隨者從戰場上帶回家的額外材料，把可以派上用場的東西留下來。\n\n我手上又多了一包其他人帶回來的材料要檢查，你要不要帶去焚化爐那邊，看看裡面有沒有什麼好東西？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋回收貨物"}
MultiLanguageQuestData['tw'][37046] = {title = "獵頭者的收割", objective = "在霜牆酒館中從亞坎佳招募一位追隨者。", description = "嘿，親愛的伙計，我是你的新獵頭者。\n在漫長的旅程之後，旅店成為一個絕佳的休息場所，也是一個和他們聊聊之後，請他們加入行列的地方。\n\n我帶了幾位人選，如果你找到值得雇用的人，為了補償你的時間，我會給你一點東西當傭金。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37047] = {title = "圣光的礼物", objective = "您會學到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n伊蘿娜技能：遠古諸王守護者"}
MultiLanguageQuestData['tw'][37048] = {title = "裂蹄訓練：巨牙", objective = "在騎乘訓練中的裂蹄時打敗巨牙。", description = "戰爭坐騎的下一個訓練，就是讓牠熟悉戰場上的光景和聲音。如果沒能經過完整的訓練，牠有可能在不恰當的時候驚懼異常。\n\n雖然牠還很小，帶著你的裂蹄前往影月谷的平原，尋找你眼前最強大的野獸。牠很快就會成長到足以面對這樣的敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37049] = {title = "裂蹄訓練：拉奇里", objective = "在騎乘訓練中的裂蹄時打敗拉奇里。", description = "你的裂蹄以霜火峰為家，這也是我們開始訓練的好場所。\n\n就在外面的冰原上，你會找到象徵著鮮血和死亡的獵手。拉奇里是頭有翅膀的恐怖象徵，也是這個地區所有野獸的走避對象，更是你未來坐騎的最佳考驗。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37050] = {title = "裂蹄訓練：笞劈", objective = "在騎乘訓練中的裂蹄時打敗笞劈。", description = "許多野獸在看到強大掠食者的時候會因恐懼而畏縮。而就在格古隆德的荒涼懸崖上有一頭最兇殘的生物。牠會是你的下個挑戰。\n\n帶著你的野獸來到強大笞劈的巢穴，看看你有沒有辦法取勝。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37051] = {title = "裂蹄訓練：格茲朗", objective = "在騎乘訓練中的裂蹄時打敗格茲朗。", description = "在德拉諾上，有許多生物在最危險的環境裡生長的欣欣向榮。而其中最狡詐的生物之一就是潛獵者。\n\n潛獵者可以融入環境，讓他們溜過附近的獵物，偷走牠們的蛋。看看你和你的野獸能不能克服這種大自然的防禦機制。你可以在塔拉多爾找到適合你的掠食者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
