MultiLanguageQuestData['tw'][37058] = {title = "裂蹄訓練：獸人獵手", objective = "在騎乘訓練中的裂蹄時打敗偉大獵人卡拉克。", description = "在納葛蘭的戰歌氏族裡，可以找到整個德拉諾中無人能出其右的獵人。他們是專門對付野獸的殺手，可以讓我們進一步考驗這頭野獸。\n\n在納葛蘭中，你會找到一位名叫卡拉克，稱號是「偉大的獵人」的獸人。因為他打倒的殘暴野獸比氏族的其他人都還要多。騎在你的坐騎身上面對他，並為被屠殺的野獸復仇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37059] = {title = "裂蹄訓練：岡恩", objective = "在騎乘訓練中的裂蹄時打敗殘爪。", description = "你的坐騎要面對的最後考驗，就是對抗這塊土地上最可怕的野獸。\n\n岡恩。毛色像夜晚一樣黑，體型比一般的狼還大上兩倍，短短一瞬間就可以撕碎一個獸人。所以這裡的野獸會怕牠們也是合理的。\n\n有隻落單的岡恩跑到納葛蘭去了，騎上你的裂蹄打敗牠吧。如果你們兩個都倖存下來的話，那你的裂蹄就訓練完成了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n訓練過的冰足裂蹄要塞資源"}
MultiLanguageQuestData['tw'][37060] = {title = "忙中有失", objective = "找回5箱剩餘的物資。", description = "<先生/女士>，倉庫已經全面展開運作，我也看到你的補給品安全存放在裡面。\n\n壞消息是，經過我的後續審查，發現我們少了幾箱剩餘材料，有可能是搬運工放錯地方了。\n\n如果你在四處走走停停時，碰巧找到這幾箱剩餘的物資，請帶回來給我，好讓我更新帳本。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37062] = {title = "商業技巧", objective = "找出失蹤的商人並喚醒他。", description = "一直以來，商人最出名的就是飲用各種東西來激發他們的本能，你應該懂我在說什麼。\n\n有時候，他們就是喝過頭。你的商人可能在大門之外倒了下來，並在一棵樹下昏倒。這種情況經常出現，已經不是新聞了。\n\n幸運的是，我手中有些飲料可以用來喚醒無力的商人。只要噴一下，我發現他們的工作意願會馬上提高。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37063] = {title = "伊萊克訓練：殘酷的巨魔", objective = "在騎乘訓練中的踏草伊萊克時打敗戈利安笞獸者。", description = "這種野獸在納葛蘭肯定有回到家的感覺，而且在德萊尼的長年馴化之後，一定很容易訓練。\n\n讓我們放牠去對付你也很熟悉的那個巨魔。那個渾身發出血腥與令人恐懼氣息的戈利安笞獸者，讓我們看看你的伊萊克會有什麼樣的反應。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37064] = {title = "雷象训练：暗翼大鹏", objective = "骑着你的训练中的草地践踏者去击败暗翼大鹏。", description = "纳格兰的风鹏是一种非常聪明的捕食者，它们经常成群结队地突袭猎物。要是你的坐骑不时刻注意着天空的话，就可得跟它这双眼睛说再见了。\n\n去纳格兰干掉那里最凶猛的风鹏——暗翼大鹏。这对你的坐骑来说是个不错的试炼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37065] = {title = "雷象训练：暴怒飞蛾", objective = "骑着你的训练中的草地践踏者去击败暴怒飞蛾。", description = "在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。\n\n如果它能让附近的野狼都不得不退避三舍，这对你的雷象来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37066] = {title = "雷象训练：雷鸣", objective = "骑着你的训练中的草地践踏者去击败雷鸣。", description = "元素生物有时候也会对野兽构成威胁。即使是最强大座狼也常会被远处的雷声所惊吓。\n\n在纳格兰的海岸，有一处迎风而立的峭壁。在那峭壁上有一只由纯粹的雷雨构成的生物，它的名字叫雷鸣。骑上你的坐骑去那儿对付它，让我们瞧瞧结果如何。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37069] = {title = "伊萊克訓練：岡恩", objective = "在騎乘訓練中的踏草伊萊克時打敗殘爪。", description = "你的坐騎要面對的最後考驗，就是對抗這塊土地上最可怕的野獸。\n\n岡恩。毛色像夜晚一樣黑，體型比一般的狼還大上兩倍，短短一瞬間就可以撕碎一個獸人。所以這裡的野獸會怕牠們也是合理的。\n\n有隻落單的岡恩跑到納葛蘭去了，騎上你的伊萊克打敗牠吧。如果你們兩個都倖存下來的話，那你的伊萊克就訓練完成了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n訓練過的踏草伊萊克要塞資源"}
MultiLanguageQuestData['tw'][37070] = {title = "虛無之力", objective = "您會學到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n愛伊達技能：召喚煉獄火"}
MultiLanguageQuestData['tw'][37071] = {title = "河獸訓練：格茲朗", objective = "在騎乘訓練中的河獸時打敗格茲朗。", description = "這種圓圓胖胖的野獸，在塔拉多爾的荒野中生活了好幾年。所以我們會從那邊開始訓練。而且牠也相當容易駕馭，所以我覺得和其他野獸比較起來，用不著那麼長的訓練時間。\n\n你可能早就聽說過，潛獵者可以融入環境之中，溜過附近的獵物，偷走牠們的蛋。看看你和你的河獸能不能克服這種大自然的防禦機制。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37072] = {title = "河獸訓練：布巴波爾", objective = "在騎乘訓練中的河獸時打敗布巴波爾。", description = "在南邊遠方的阿拉卡山裡，土地被生長在水下的蘑菇吞噬，奇怪的真菌生物無止盡的生長。\n\n和其中一隻怪異生物對抗，例如真菌巨人布巴波爾，會是個讓你的坐騎面對牠完全不熟悉掠食者的大好機會。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37073] = {title = "淡水兽训练：凶残的食人魔", objective = "骑着你的训练中的淡水兽去击败高里亚驱兽者。", description = "在纳格兰居住着德拉诺最强大的野兽，而且那里的食人魔使用一种非常残忍的手段驯养他们。\n\n其中，又数那个叫高里亚驱兽者的尤为凶残。他浑身充满了血腥和恐惧的气息。让我们瞧瞧你的坐骑面对他是否还能面不改色。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37074] = {title = "淡水兽训练：暗翼大鹏", objective = "骑着你的训练中的淡水兽去击败暗翼大鹏。", description = "纳格兰的风鹏是一种非常聪明的捕食者，它们经常成群结队地突袭猎物。要是你的坐骑不时刻注意着天空的话，就可得跟它这双眼睛说再见了。\n\n去纳格兰干掉那里最凶猛的风鹏——暗翼大鹏。这对你的坐骑来说是个不错的试炼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37075] = {title = "淡水兽训练：暴怒飞蛾", objective = "骑着你的训练中的淡水兽去击败暴怒飞蛾。", description = "在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。\n\n如果它能让附近的野狼都不得不退避三舍，这对你的淡水兽来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37077] = {title = "淡水兽训练：铁钻", objective = "骑着你的训练中的淡水兽去击败铁钻。", description = "你解决掉了陆地和天空的敌人，甚至还有雷雨。接下来你将面对你脚底下的动物。\n\n岩虫是一种狡猾的捕食者，它们喜欢从沙土底下钻出来袭击敌人。在纳格兰，很多野兽都学会了注意脚底下的动静。带你的座狼去那边的沙滩，尝试干掉那里的老岩虫：铁钻。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37078] = {title = "河獸訓練：獸人獵手", objective = "在騎乘訓練中的河獸時打敗偉大獵人卡拉克。", description = "在納葛蘭的戰歌氏族裡，可以找到整個德拉諾中無人能出其右的獵人。他們是專門對付野獸的殺手，可以讓我們進一步考驗這頭野獸。\n\n在納葛蘭中，你會找到一位名叫卡拉克，稱號是「偉大的獵人」的獸人。因為他打倒的殘暴野獸比氏族的其他人都還要多。騎在你的坐騎身上面對他，並為被屠殺的野獸復仇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
