MultiLanguageQuestData['tw'][37086] = {title = "回收狀況", objective = "在回收場中的焚化爐旁邊，使用小袋的回收貨物。", description = "在回收場裡面，我們會檢查追隨者從戰場上帶回家的額外材料，把可以派上用場的東西留下來。\n\n我手上又多了一包其他人帶回來的材料要檢查，你要不要帶去焚化爐那邊，看看裡面有沒有什麼好東西？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋回收貨物"}
MultiLanguageQuestData['tw'][37087] = {title = "忙中有失", objective = "找回5箱剩餘的物資。", description = "<先生/女士>，倉庫已經全面展開運作，我也看到你的補給品安全存放在裡面。\n\n壞消息是，經過我的後續審查，發現我們少了幾箱剩餘材料，有可能是搬運工放錯地方了。\n\n如果你在要塞奔走時，碰巧找到剩餘的物資，請帶回來給我，好讓我更新帳本。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37088] = {title = "交易的訣竅", objective = "找出失蹤的貿易者並喚醒他。", description = "在過去一陣子，貿易者最出名的就是飲用各種東西來激發他們的本能，你應該懂我在說什麼。\n\n有時候，他們就是喝過頭。你的貿易者可能在大門之外倒了下來，並在一棵樹下昏倒。這種情況經常出現，已經不是新聞了。\n\n幸運的是，我手中有些酒可以用來喚醒無力的貿易者。只要噴一下，我發現他們的工作意願會馬上提高。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37091] = {title = "不按常規的發明", objective = "在你的地精零件廠中，從工作桌上取得一項發明。", description = "在工坊裡有各種呼呼作響的思緒和馬達在奔忙。我們隨時都有新發明。\n\n去看看我背後工作桌上的光榮發明吧。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][37092] = {title = "鋼鐵碎塊", objective = "從德拉諾的鋼鐵部落身上，收集5塊鋼鐵部落碎塊。", description = "在矮人碉堡中，我們可以利用你四處收集而來的鋼鐵部落護甲碎塊，並轉變成新的器具。那雖然不是世界上最強大的東西，但是看起來真的不錯。\n\n取得一些鋼鐵部落的碎塊，再回來找我。在你的努力之餘，我會幫你做一件很棒的外袍。", progress = "拿到那些碎片了嗎？", completion = "這些碎塊可以用。", rewards = "您會收到：\n\n暴風城外袍"}
MultiLanguageQuestData['tw'][37093] = {title = "塔巴克訓練：巨牙", objective = "在騎乘訓練中的塔巴克時打敗巨牙。", description = "塔巴克已經準備好接受訓練了，而我們會先回到牠的老家影月谷開始訓練。\n\n巨牙是這塊土地上最強大的生物之一，牠佔據了一座峽谷。讓你的野獸上場對抗牠，如果你們存活下來，牠就會對自已的能力更有自信。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37094] = {title = "塔巴克訓練：拉奇里", objective = "在騎乘訓練中的塔巴克時打敗拉奇里。", description = "我們應該從霜火峰的冰凍平原開始訓練塔巴克。我們要嚴酷訓練牠，以免牠看到戰場時有所畏懼，進而逃跑。\n\n在冰凍平原上找到強大的吸血獸拉奇里，然後騎上你的塔巴克打倒牠。那會讓牠品嚐到戰鬥的滋味。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37095] = {title = "塔巴克訓練：笞劈", objective = "在騎乘訓練中的塔巴克時打敗笞劈。", description = "許多野獸在看到強大掠食者的時候會因恐懼而畏縮。而就在格古隆德的荒涼懸崖上有一頭最兇殘的生物。牠會是你的下個挑戰。\n\n帶著你的野獸來到強大笞劈的巢穴，看看你有沒有辦法取勝。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37096] = {title = "塔巴克訓練：格茲朗", objective = "在騎乘訓練中的塔巴克時打敗格茲朗。", description = "在德拉諾，有許多生物在最危險的環境裡順利繁衍。其中最狡詐的生物之一，就是潛獵者。\n\n潛獵者可以融入環境，讓牠們躲過附近的獵物，把蛋偷走。看看你和你的野獸能不能克服這種大自然的防禦機制。你可以在塔拉多爾找到適合你的掠食者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37097] = {title = "塔布羊训练：布巴波尔", objective = "骑着你的训练中的塔布羊去击败布巴波尔。", description = "在遥远南方的阿兰卡峰林，生长在水下的蘑菇正在不断地侵蚀着陆地，古怪的真菌生物四处横行。\n\n其中有一个真菌巨人叫布巴波尔，正好让你的坐骑见识一下它不曾见过的捕食者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37098] = {title = "塔布羊训练：凶残的食人魔", objective = "骑着你的训练中的塔布羊去击败高里亚驱兽者。", description = "在纳格兰居住着德拉诺最强大的野兽，而且那里的食人魔使用一种非常残忍的手段驯养他们。\n\n其中，又数那个叫高里亚驱兽者的尤为凶残。他浑身充满了血腥和恐惧的气息。让我们瞧瞧你的坐骑面对他是否还能面不改色。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37102] = {title = "塔巴克訓練：艾恩波爾", objective = "在騎乘訓練中的塔巴克時打敗艾恩波爾。", description = "你已經打倒了天空、地上，甚至是雨中的敵人了。接下來，你要面對的生物來自腳下。\n\n岩蟲是十分狡詐的獵食者，直接從沙土之中攻擊獵物。所以很多納葛蘭的野獸在大地震動時就會提高警覺。帶著你的坐騎到沙灘上，考驗牠對抗年長岩蟲艾恩波爾的本事。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37103] = {title = "塔巴克訓練：獸人獵手", objective = "在騎乘訓練中的塔巴克時打敗偉大獵人卡拉克。", description = "在納葛蘭的戰歌氏族裡，可以找到整個德拉諾中無人能出其右的獵人。他們是專門對付野獸的殺手，可以讓我們進一步考驗這頭野獸。\n\n在納葛蘭中，你會找到一位名叫卡拉克，稱號是「偉大的獵人」的獸人。因為他打倒的殘暴野獸比氏族的其他人都還要多。騎在你的坐騎身上面對他，並為被屠殺的野獸復仇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37104] = {title = "塔布羊训练：铁颚狼", objective = "骑着你的训练中的塔布羊去击败残爪。", description = "你的坐骑的最后一项挑战将是面对这片大地上最可怕的一种动物。\n\n有一种狼，他们的皮肤像夜晚一样漆黑，他们体型比一般的狼要大上一倍，它们就是铁颚狼。它们转眼间就能把一个兽人撕成两半，野兽们害怕它们不是没有理由的。\n\n现在有一头孤独的铁颚狼跑到了纳格兰定居。骑上你的塔布羊去干掉它，如果你们两个能够生还，你的塔布羊才真正算是准备好了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n訓練過的銀光塔巴克要塞資源"}
MultiLanguageQuestData['tw'][37105] = {title = "座狼训练：凶残的食人魔", objective = "骑着你的训练中的啸狼去击败高里亚驱兽者。", description = "这片大地上的野狼是我见过的最凶残的野兽，而且它们也不怕兽人和食人魔。\n\n让我们带它去会一会你在那边的食人魔老熟人吧，那个浑身充满了血腥和恐惧气息的高里亚驱兽者。让我们瞧瞧你的座狼面对他是否还能面不改色。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37106] = {title = "座狼训练：暗翼大鹏", objective = "骑着你的训练中的啸狼去击败暗翼大鹏。", description = "纳格兰的风鹏是一种非常聪明的捕食者，它们经常成群结队地突袭猎物。要是你的坐骑不时刻注意着天空的话，就可得跟它这双眼睛说再见了。\n\n去纳格兰干掉那里最凶猛的风鹏——暗翼大鹏。这对你的坐骑来说是个不错的试炼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37107] = {title = "座狼训练：暴怒飞蛾", objective = "骑着你的训练中的啸狼去击败暴怒飞蛾。", description = "在纳格兰的森林中有许多善于躲避捕食者的动物。但其中又要属那只名叫暴怒飞蛾的蛾子做的最好，它浑身覆满了充满恶臭的飞蛾之尘。\n\n如果它能让附近的野狼都不得不退避三舍，这对你的座狼来说一定是一次非常美妙的试炼。看看你能不能让它保持专注，干掉那只飞蛾吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37110] = {title = "狼之訓練：獸人獵手", objective = "在騎乘訓練中的咆哮者時打敗偉大獵人卡拉克。", description = "在納葛蘭的戰歌氏族裡，可以找到整個德拉諾中無人能出其右的獵人。他們是專門對付野獸的殺手，可以讓我們進一步考驗這頭野獸。\n\n在納葛蘭中，你會找到一位名叫卡拉克，稱號是「偉大的獵人」的獸人。因為他打倒的殘暴野獸比氏族的其他人都還要多。騎在你的坐騎身上面對他，並為被屠殺的野獸復仇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37111] = {title = "狼之訓練：岡恩", objective = "在騎乘訓練中的咆哮者時打敗殘爪。", description = "你的坐騎要面對的最後考驗，就是對抗這塊土地上最可怕的野獸。\n\n岡恩。毛色像夜晚一樣黑，體型比一般的狼還大上兩倍，短短一瞬間就可以撕碎一個獸人。所以這裡的野獸會怕牠們也是合理的。\n\n有隻落單的岡恩跑到納葛蘭去了，騎上你的狼打敗牠吧。如果你們兩個都倖存下來的話，那你的狼就訓練完成了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n訓練過的咆哮者要塞資源"}
MultiLanguageQuestData['tw'][37112] = {title = "休息和放鬆", objective = "和獅王之傲旅店的旅店老闆法雷談話。", description = "每個冒險家在疲憊的時候都需要休息─而休息和放鬆的最佳去處就是獅王之傲旅店！\n\n我的好朋友法雷是那裡的旅店老闆。告訴他是我介紹你去的，也許他還會給你些特別優惠呢。\n\n如果你要去獅王之傲旅店的話，沿著大路往南走就沒錯了！", progress = nil, completion = "又累又冷的旅行者啊，獅王之傲就是您溫暖的家─這是我們的格言！請坐在火邊，讓您疲憊的身體好好放鬆一下。\n\n您要不要嘗一嘗我們這兒最好的酒菜？", rewards = "獅王之傲護腕旅店老闆的手套閃金鎮鐵護腕鐵匠的鎖甲手套您會收到：\n\n小南瓜清涼的泉水"}
MultiLanguageQuestData['tw'][37119] = {title = "獵頭者的收割", objective = "在落月旅店中從萊莎‧瑟里昂那裡招募一位追隨者。", description = "旅店為冒險者在旅程途中提供一個完美的休息場所。如果想要和他們喝上幾杯，閒聊之後請他們加入我們的行列，這也是個不錯的地方。\n\n列出你的招募條件，看看我們能否雇傭到一名人手。我會給你一些東西當做傭金。", progress = nil, completion = "啊啊，我真高興你能找到好人選！\n\n我會繼續幫你找更多的候選者。記得每星期回來看看我的最新名單。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37120] = {title = "Sunspring POI Tracking Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][37121] = {title = "黑爪", objective = "詢問芬妮‧火鬍與塞司黑爪有關的事。", description = "在我的背後，你可能已經看到了，是個巨大的黑爪。在我們外出尋找可馴服的動物時發現的。這些動物似乎很怕它，或許是因為這頭野獸在過去曾經獵捕過牠們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37122] = {title = "獵食者之牙", objective = "詢問芬妮‧火鬍與岡恩牙齒項鍊有關的事。", description = "在我們出外尋找可以馴服的野獸時，這個項鍊從獸人獵人身上掉了出來。我從來沒看過動物們對它產生的強烈反應！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37123] = {title = "黑爪", objective = "詢問賢者帕努納與塞司黑爪有關的事。", description = "你可能在我們的補給堆上，看過這個巨大、漆黑的爪子。是我們在外出尋找可馴服的動物時發現的。這些動物似乎很怕它，或許是因為這頭野獸在過去曾經獵捕過牠們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37124] = {title = "掠食者之牙", objective = "向先知帕鲁纳询问铁颚狼齿项链的情况。", description = "我们出去驯服野兽时，一个兽人猎手身上掉下了这根项链。我从没见过动物们对什么东西会有这么强的反应。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37125] = {title = "少見的發現", objective = "有時候，考古學家的經驗很難累積…比如說，一件經過長時間保存的文物，就像從時光機裡面掉出來的東西一樣。\n\n光是想像新發現的興奮之情，就會讓我很情緒化…像那樣的聖物，可以賣個大好價錢！", description = nil, progress = "有時候，考古學家的經驗很難累積…比如說，一件經過長時間保存的文物，就像從時光機裡面掉出來的東西一樣。\n\n光是想像新發現的興奮之情，就會讓我很情緒化…像那樣的聖物，可以賣個大好價錢！", completion = "找到好東西了！這件聖物一定會大受歡迎，成為某人的私人收藏。", rewards = nil}
MultiLanguageQuestData['tw'][37126] = {title = "少把劍的巨魔…", objective = "在納葛蘭的破碎絕壁，從輔臣達古德手中取回托爾瑪克的愛劍。", description = "在我搭船離開格古隆德的時候，我奉派到納葛蘭的破碎絕壁，讓難以駕馭的掘泥工作持續進行。輔臣達古德拒絕讓我帶著最鍾愛的劍同行；他告訴我的是「在我要去的地方用不到它。」\n\n我要把它拿回來，指揮官，而且我相信我們合力之下，就有足夠的力量打倒達古德，並從他的血腥屍體上取回我的劍。\n\n這對我而言十分重要。少了一把劍的巨魔根本就不算巨魔。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n托爾瑪克特殊能力：武具大師\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37127] = {title = "離鄉聖光", objective = "前往塔拉多爾的撒塔斯城，從薩塔燈塔的海爾瑪大使手中取得離鄉聖光。", description = "我的祖父經常告訴我許多故事，提到一枚由聖光打造而成的強力水晶，用它行善之人可以獲得強大的力量。他把水晶稱之為離鄉聖光。\n\n我從來就不相信他…直到現在為止。\n\n你的斥候已經找到了這枚符合描述的水晶。問題在於它被一個可怕的惡魔帶走了，目前這個惡魔正在撒塔斯城的薩塔燈塔中腐化水晶。\n\n我們的動作要快點！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n伊蘿娜特殊能力：引路聖光\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37128] = {title = "平息不滿", objective = "前往塔拉多爾的撒塔斯城，從薩塔燈塔的海爾瑪大使手中取得離鄉聖光。", description = "我們的斥候已經找到一枚威力強大的德萊尼水晶，不過位於撒塔斯城薩塔燈塔裡面的海爾瑪大使正在腐化這枚水晶。德萊尼將這枚水晶稱為離鄉聖光。\n\n指揮官，這一次的任務我想和你同行。海爾瑪在外域殺死了我兄弟…這是個人仇恨。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n愛伊達特殊能力：召喚儀式\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37129] = {title = "不愉快的回憶", objective = "在格古隆德的永茂林野地，從阿坎薩斯手中取回被感染的獸人遺骸。", description = "永茂林野地的波塔尼正在進行某種邪惡的魔法，來創造這種植物…呃…基本上應該算殭屍。\n\n我看過這種沒有意識的奴隸大軍。巫妖王…\n\n<德爾瓦閉上雙眼。>\n\n沒關係。我們不能讓這種事情繼續發展下去。我聽說它們剛剛完成了一個特別噁心的東西…讓我們宰了它，然後看看是什麼東西讓它動了起來。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n德爾瓦特殊能力：死亡之門\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37130] = {title = "Sunspring POI Tracking Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][37131] = {title = "黑暗女王的顧慮", objective = "在格古隆德的永茂林野地，從阿坎薩斯手中取回被感染的獸人遺骸。", description = "在永茂林野地中的波塔尼，會殺死膽敢靠近花朵的任何笨蛋，然後讓他們的屍體復活，成為沒有心智的士兵。\n\n這一切都讓我們想到天譴軍…而在這之間最引人注目的就是黑暗女王。她為我們指派了一個特殊任務，指揮官。\n\n最近復活了一個特別巨大、受到感染的生物。我們得毀掉它，並取得它的遺骸。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n薇薇安妮特殊能力：傳送門：要塞\n\n您還會收到：\n\n"}
