MultiLanguageQuestData['tw'][37203] = {title = "艾絲蕾", objective = "在寵物對戰中打倒艾絲蕾。", description = "我不是很喜歡讓我的寵物作戰，但是我很喜歡在他們作戰後替他們治療。您會收到：\n\n\n\n等級 12–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 12–80磨亮的寵物吊飾\n\n等級 7–69亮晶晶的寵物吊飾"}
MultiLanguageQuestData['tw'][37204] = {title = "重燃古焰", objective = "把火焰精華帶給麥奈洛克中的菲加拉。", description = "我快死了，<race>。我的火焰，已經化為餘燼了…很快的，我的火光會開始閃爍搖曳，然後黯淡熄滅。\n\n你絕不能讓這件事發生。為我取回火焰精華，讓我再次復甦，我發誓一定會把每一個破源者都殺掉。\n\n我會為我的兄弟姐妹復仇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37205] = {title = "珈歌菈", objective = "在寵物對戰中打倒珈歌菈。", description = "你想要尋求挑戰嗎？我的狼群得受訓才能變得更強大。您會收到：\n\n\n\n等級 13–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 13–80磨亮的寵物吊飾\n\n等級 13–70亮晶晶的寵物吊飾"}
MultiLanguageQuestData['tw'][37206] = {title = "『可怕的』塔爾", objective = "在寵物對戰中打倒塔爾。", description = "塔爾是真正的督軍！帶你的軍隊來作戰，我就讓你開眼界。您會收到：\n\n\n\n等級 11–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 11–80磨亮的寵物吊飾\n\n等級 18–69亮晶晶的寵物吊飾"}
MultiLanguageQuestData['tw'][37207] = {title = "維夏爾", objective = "在寵物對戰中打倒維夏爾。", description = "我看過一個幻象，會有一位精通寵物作戰的人前來挑戰。這道幻象成真了嗎？您會收到：\n\n\n\n等級 11–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 11–80磨亮的寵物吊飾\n\n等級 11–66亮晶晶的寵物吊飾"}
MultiLanguageQuestData['tw'][37208] = {title = "泰菈露妮", objective = "在寵物對戰中擊敗泰菈露妮。", description = "我教的是非致命性的寵物對戰。你想要學習嗎？您會收到：\n\n\n\n等級 13–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 13–80磨亮的寵物吊飾\n\n等級 12–69亮晶晶的寵物吊飾"}
MultiLanguageQuestData['tw'][37209] = {title = "冰冷金屬第二部", objective = "在恐軌車站找一具鋼鐵自動火砲。", description = "嘿，你。\n\n我想要感謝你為我所做的一切。體驗火砲在我手中振動的感覺，就是最需要的治療方式。但現在…\n\n<基沙恩看著遠方並皺起眉頭。>…彈藥都沒了。\n\n我猜我只能坐在這邊等死。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一箱傳說的寶物"}
