MultiLanguageQuestData['tw'][37284] = {title = "做一票大的", objective = "為格利夫塔取得髒鐵幣。", description = "我知道，我知道。我把這些送給你珍藏了，但現在我得把它們要回來。這很複雜，夥計。你要不要黃金？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
