MultiLanguageQuestData['tw'][37474] = {title = "夯实基本功", objective = "与暴风城的奥黛丽·伯恩赫普交谈。不错的气势，<name>，但你在宠物对战这块可得从头学起。去暴风城找奥黛丽·伯恩赫普吧，她会将基本功传授给你的。", description = "不错的气势，<name>，但你在宠物对战这块可得从头学起。去暴风城找奥黛丽·伯恩赫普吧，她会将基本功传授给你的。", progress = nil, completion = nil, rewards = nil}
