MultiLanguageQuestData['tw'][37510] = {title = "斯騰法索的鬥士", objective = "以新任鬥士的身份向斯騰法索回報。", description = "因為你擊敗了烏克嘟克，斯騰法索那隊現在空出了一個名額。你必須加入隊伍，成為他的鬥士。這樣一來，巨人就不會懷疑這個突然出現又突然消失的陌生人。\n\n在此同時，我會開始製造混亂，方便我們襲擊歐宣諾王子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37511] = {title = "迪茲‧迅火", objective = "找出迪茲‧迅火。", description = "就開挖東西來講，我這個地點還不錯。\n\n我們還有幾位協會成員在挖掘現場工作。我是想去找找他們的下落，但是對健康好像不太好。\n\n你看來蠻吃苦耐勞的，能不能找出迪茲？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37512] = {title = "Primals Invasion! BETA", objective = "击退原兽对你要塞的入侵。\n\n（再次与克劳勒中士交谈来开始行动）", description = "植物今天看起来很不一样。草叶都被风吹弯了，掠扫着我的靴子。早上还有两根树枝掉到了我的头盔上。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][37515] = {title = "The Iron Horde Approaches... BETA", objective = "与克劳勒中士谈一谈。", description = "远方有几股黑烟……钢铁部落来了。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][37516] = {title = "給妮可希的消息", objective = "和妮可希交談。", description = "妮可希很可能正在為這次調查行動的損失而茶飯不思。\n\n如果你看到她的話，能不能告訴她我們會儘快回去？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37517] = {title = "給妮可希的消息", objective = "和妮可希交談。", description = "妮可希很可能正在為這次調查行動的損失而茶飯不思。\n\n如果你看到她的話，能不能告訴她我們馬上就會回去？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37518] = {title = "鬧鬼的大廳", objective = "進入學院的西側。", description = "所以，你本來想做什麼？你來這裡看葛剛尼斯潮石？哈！呵呵哈哈哈！\n\n呼，我的天。\n\n你看不到的，只有學院的院長才有房間的鑰匙，但她已經有…喔，大概一萬年沒打開過房門了。\n\n你現在該去上課了。快去啊！趕快到西側的學院去！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
