MultiLanguageQuestData['tw'][37687] = {title = "要塞戰役：陰影之中", objective = "在雄獅堡殺死3位議會夜刃。", description = "我需要你的協助。伊斯卡失蹤了。我有足夠的理由，相信他加入了在塔南此地集結的塞司克殘黨。我一直在調查並…那是什麼？\n\n<瑞薩德壓低聲音，幾不可聞>\n\n在暗影之中有動靜，我們被監視了！\n\n把這些瓶子拿去，裡面的液體只要接觸到空氣，就會揮發成臭到不行的氣體。他們肯定受不了這種可怕臭味。用這些東西把監視者逼出藏身之處。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料"}
MultiLanguageQuestData['tw'][37688] = {title = "要塞戰役：陰影之中", objective = "在沃爾瑪殺死3位議會夜刃。", description = "我需要你的協助。伊斯卡失蹤了。我有足夠的理由，相信他加入了在塔南此地集結的塞司克殘黨。我一直在調查並…那是什麼？\n\n<瑞薩德壓低聲音，幾不可聞>\n\n在暗影之中有動靜，我們被監視了！\n\n把這些瓶子拿去，裡面的液體只要接觸到空氣，就會揮發成臭到不行的氣體。他們肯定受不了這種可怕臭味。用這些東西把監視者逼出藏身之處。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料"}
MultiLanguageQuestData['tw'][37689] = {title = "假冒者", objective = "用爪鉤爬上雄獅陵園的懸崖，悄悄潛入暴風城，前往軍情七處的根據地，然後殺死戴瑟洛克。", description = "戴瑟洛克在所有屋頂上部署了軍情七處最厲害的狙擊手。我們不能乘上坐騎，也不能飛進去。但是崖壁上有可以用爪鉤爬上去的地方。\n\n一路上也放置了乾草捆，方便我們一邊躲藏，一邊前往軍情七處。我們只要潛行進去，殺死戴瑟洛克就行了。\n\n爬上去之後，我們分頭行動。這樣能提高至少有一個人順利穿過城市的機會。\n\n祝你好運，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "盟之聖光盟之秘紋盟之血肉盟之魔禦盟之烈焰盟之冰心盟之銳志盟之富饒盟之夕暮盟之風暴您會收到：\n\n無冕者護胸強效職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][37690] = {title = "未曾遺忘的人", objective = "在沉沒庭園找到守夜者艾德莉。", description = "南邊的那些鬼魅精靈，曾經持有名為「葛剛尼斯潮石」的創世之柱。\n\n他們的大城市納薩拉斯許久以前就毀滅了。治理城市的法隆迪斯親王也隨著城市一同覆滅。你們這些小傢伙真是容易死。\n\n要說有誰知道碎片在哪裡，那一定是親王的鬼魂。去找他的族人吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37727] = {title = "調酒行家", objective = "收集6個灌注秘法的蛋。", description = "你應該知道，我是酒類飲品的行家…尤其是灌注秘法的烈酒。調酒就是鍊金術，而大家都知道，鍊金術就是魔法。\n\n我準備推出的新款調酒，一定要比以前的調酒更有特色。我已經集齊了大部分的材料，只剩下幾種還沒弄到。\n\n看到潟湖邊的蒼鷺了嗎？就像艾蘇納的許多生物一樣，在這座島嶼上流動的魔力會滲入牠們體內。\n\n牠們的蛋會是很好的材料。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n食譜：法隆納氣泡飲"}
MultiLanguageQuestData['tw'][37728] = {title = "裝飾才是重點", objective = "收集岡加梅許的六顆眼睛。", description = "這些蛋會讓我的調酒更有勁道。不過還有一個要素，最好不要低估它的影響力！\n\n那就是裝飾。\n\n你也可以用牙籤串橄欖這種普通的裝飾，或者在杯緣隨便插一根胡蘿蔔。\n\n不過，這不是我的風格。\n\n朋友，我可不想那麼隨便，我的調酒裝飾只有獨一無二的生物身上有。這杯酒我不會調第二次，所以我需要獨一無二的材料。\n\n我要的是岡加梅許的眼睛。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37729] = {title = "隨堂抽考：進階符文繪製", objective = "摹刻一個秘法符文、一個火焰符文和一個冰霜符文。", description = "還想進去院長的書房嗎？我想應該能讓你進去…只要你證明你有在唸書。\n\n施放咒語時，畫出正確的符文是相當重要的。如果你能畫出符文，就能施放咒語。\n\n我會給你大綱，你可以直接用腳描繪出符文。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37730] = {title = "院長的鑰匙", objective = "從學院院長艾爾雅‧蒼月手裡取得潮石寶庫鑰匙。", description = "我懷疑你只是想逃避唸書 - 不過我看得出來，你很想快點見到院長。\n\n非常好！蒼月院長就在前面，不過我不認為她願意受到打擾。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "納薩拉斯護腕海沫護腕遺跡巡者束腕脈行者護腕您能選擇下列奬勵中的一個：\n\n發瘋學者之鍊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][37733] = {title = "法隆迪斯親王", objective = "到崩裂之殿和守夜者艾德莉碰面。", description = "很高興發現我對你的質疑毫無根據。\n\n你要找法隆迪斯親王？請跟我來，我會帶你去找親王。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37736] = {title = "人要衣裝", objective = "取得納薩拉斯學院帽、長袍、魔杖和法術書。", description = "馬上給我站住，你看看你！看起來就像是從街上來的。你的長袍和帽子在哪裡？\n\n還有，別告訴我你沒帶魔杖和法術書就來了。\n\n新生。\n\n把你自己打理好，我或許會考慮讓你進學院。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘的新生帽"}
MultiLanguageQuestData['tw'][37749] = {title = "卡德加的試煉：鐵娘子軍", objective = "遵守下列條件，打倒鐵娘子軍。", description = "以高超的技巧打倒敵人，贏得卡德加的好感，並且取得更棒的獎勵！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][37753] = {title = "進行古物獵人任務", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][37756] = {title = "壁壘之城：綠蕨孢子巨人", objective = "擊敗天槌的綠蕨孢子巨人。", description = "鋼鐵部落只是我們在德拉諾必須解決的威脅之一。我們也必須解決他們所經之處造成的混亂。\n\n綠蕨孢子巨人是古老的深淵行者，因鋼鐵部落的出現而從天槌附近的水域現身。他會散播真菌與苔蘚，若對他置之不理，他會把我們全都消滅。\n\n前往天槌並擊敗綠蕨孢子巨人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37757] = {title = "秘法聖所：寇拉夫", objective = "擊敗天槌的寇拉夫。", description = "忘掉你在艾澤拉斯所知的巨魔吧，<name>。在德拉諾，巨魔曾經建立強大的文明帝國。即使是現在，他們餘威仍在，想重獲往日的榮耀。\n\n在納葛蘭的天槌挖掘場發現了神秘的聖物。唯一沒有因為接觸聖物而死亡的巨魔，就是寇拉夫。他幾乎對所有的魔法免疫。\n\n我們必須在其他巨魔研究出如何複製他的能力前殺死他。前往天槌，擊敗寇拉夫！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37758] = {title = "統治者之臺：統治者瑪爾戈克", objective = "擊敗天槌的統治者瑪爾戈克。", description = "對天槌發動關鍵一擊的時機已經成熟了，指揮官。你要出擊嗎？\n\n身為天槌的最高統治者，瑪爾戈克出身歷史悠久的巫士世家，集狡詐與兇蠻於一身，並在了解對抗鋼鐵部落的下場後，決定與他們結盟。\n\n前往天槌擊敗統治者瑪爾戈克。沒有領袖的巨魔帝國將會陷入長年動亂。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37762] = {title = "熔渣處理場：山脈之心", objective = "擊敗黑石鑄造場高爐旁的山脈之心。", description = "黑石氏族的戰鬥能力是其他氏族難以比擬的。他們使用的武器跟護甲是在異於尋常的熔爐中鑄造出來的。\n\n在黑石鑄造廠的深處，提供這個熔爐能量的，是名叫山脈之心的強大生物。把它摧毀，剝奪他們倚重的軍備。\n\n前往黑石鑄造場並擊敗山脈之心。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37763] = {title = "黑熔爐：克羅莫格", objective = "擊敗黑石鑄造場中的克羅莫格。", description = "指揮官。霜狼的斥候回報，黑石礦工挖到了一隻麥奈隆，還強迫那隻怪物幫助他們製造邪惡的裝置。他們叫他「克羅莫格」。\n\n我們必須殺了他，<name>。前往黑石鑄造場，擊敗克羅莫格。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37764] = {title = "鋼鐵集貨區：珈蘭上將", objective = "擊敗黑石鑄造場中的珈蘭上將。", description = "我們在陸地上的進展不錯，但在海上仍然無法獲勝。我們必須在港口解決鋼鐵部落的領袖。\n\n珈蘭上將是鋼鐵部落的海軍上將，鐵娘子軍的元老之一，擅長各種戰術。她和她的副官瑪拉克及索爾卡目前未嘗敗績，把敵人全都殲滅了。\n\n前往黑石鑄造場並擊敗珈蘭上將。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37765] = {title = "黑手的爐缸：黑手", objective = "擊敗黑石鑄造場中的黑手。", description = "葛羅瑪許‧地獄吼倚賴酋長的力量來統馭鋼鐵部落。一舉擊潰他們的時候到了。\n\n黑手，黑石氏族的酋長，是個無所畏懼的戰士，也是無情的暴君。在鋼鐵部落中，他的地位僅次於葛羅瑪許。他在鑄造場頂端的爐缸監督整個鑄造場。\n\n前往黑石鑄造場並擊敗黑手。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37766] = {title = "壁壘之城：綠蕨孢子巨人", objective = "擊敗天槌的綠蕨孢子巨人。", description = "一波未平，一波又起 - 我敢說這個被聖光遺棄的世界就算沒有部落也會把我們整個吞噬。綠蕨孢子巨人是古老的深淵行者，因鋼鐵部落的出現而在天槌附近的水域中現身。那個東西已經像疾病一樣擴散了，<name>。你一定要阻止它！\n\n前往天槌並在綠蕨孢子巨人變得太過強大之前擊敗它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37767] = {title = "秘法聖所：寇拉夫", objective = "擊敗天槌的寇拉夫。", description = "你聽過「寇拉夫」這個名字嗎？他也是天槌的巨魔。他們之前挖到一個聖物，除了寇拉夫以外，所有碰到的人都死了，這也讓他幾乎對所有的魔法免疫。\n\n巨魔不該擁有那樣的力量！前往天槌擊敗寇拉夫，不能讓他們知道該怎麼利用他對付我們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37768] = {title = "統治者之臺：統治者瑪爾戈克", objective = "擊敗天槌的統治者瑪爾戈克。", description = "我一直沒把巨魔當一回事，但在我看到天槌的軍隊時就改觀了。他們看起來像一座穿了護甲的牆，還有巫王麾下最厲害的巫士奧援。千萬別低估那些巨魔。\n\n統治者瑪爾戈克是天槌之王。他十分狡猾，還跟鋼鐵部落結盟。如果我們想擊潰這支軍隊，最好擒賊先擒王。\n\n前往天槌並擊敗統治者瑪爾戈克！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37769] = {title = "熔渣處理場：山脈之心", objective = "在黑石鑄造場中擊敗高爐的山脈之心。", description = "黑石戰士使用的武器，是藉由純焰生物「山脈之心」所噴出的詛咒火焰打造的。讓我們剝奪他們的武裝，<小夥子/小姑娘>！摧毀那個煉獄生物，黑石氏族就沒有足夠的能量燒熱高爐。\n\n前往黑石鑄造場並擊敗山脈之心。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37770] = {title = "黑熔爐：克羅莫格", objective = "擊敗黑石鑄造場中的克羅莫格。", description = "你的要塞斥候回報有黑石的礦工挖出了一隻麥奈隆，而那隻該死的野獸居然開始幫他們製造邪惡裝置。他們叫他「克羅莫格」。\n\n前往黑石鑄造場並殺死那隻野獸！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37771] = {title = "鋼鐵集貨區：珈蘭上將", objective = "擊敗黑石鑄造場中的珈蘭上將。", description = "「要推倒一座牆，就要從地基著手。」這是古老的矮人格言。只要我們解決鋼鐵部落的首領，整個組織就會分崩離析。\n\n珈蘭是鋼鐵部落的海軍上將，也是所謂「鐵娘子軍」的首領。她和她的心腹手下，瑪拉克和索爾卡，幾乎稱霸全德拉諾的大海。\n\n這種狀況不能再繼續下去了，<name>。前往黑石鑄造場，擊敗珈蘭上將。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37772] = {title = "黑手的爐缸：黑手", objective = "擊敗黑石鑄造場中的黑手。", description = "老葛羅瑪許若沒有酋長幫忙把那些氏族管好，就沒辦法統領整個鋼鐵部落。讓我們全力出擊，讓他們一蹶不振！黑手，黑石氏族的酋長，是個無所畏懼的戰士，也是無情的暴君。在鋼鐵部落中，他的地位僅次於葛羅瑪許。他在鑄造場頂端的爐缸監督整個鑄造場的運作。\n\n前往黑石鑄造場並擊敗黑手。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高級懸賞戰利品"}
MultiLanguageQuestData['tw'][37773] = {title = "殺死阿默松！", objective = "在塔拉多爾的庫羅斯的領地上面，從阿默松身上取得一個嗡鳴的德萊石尖刺。", description = "塔拉多爾哨站裡的工頭艾克索斯覺得他找到最近地殼活動頻繁的原因了。\n\n因為巨人，呃，應該要說是大地怒靈，它在庫羅斯的領地上面山的洞裡，身上覆蓋著強大的水晶。這些水晶會發出很大聲的共鳴，我們覺得就是因為那樣才讓怒靈發瘋！\n\n問題是，沒有人有足夠的火力把那個玩意兒弄下來取得一些樣本。能幫忙嗎，指揮官？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37774] = {title = "殺死戈蘇爾！", objective = "殺死位於阿拉卡山血鬃領地的戈蘇爾。", description = "劍齒人靈魂大軍。我沒在開你玩笑，指揮官，如果我們不趕快行動，這就是我們將要面臨的大麻煩。就在我們的商隊開始被劍齒人靈魂襲擊的同時，有人在阿拉卡山的血鬃領地看到破碎之手的薩滿戈蘇爾。\n\n我不想要冒風險，指揮官。我想你最好親自去那裡終結那個麻煩。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37775] = {title = "殺死淨化者達庫爾！", objective = "到納葛蘭的血之競技場與葛爾薩克交談，並贏得特別表演賽。", description = "你聽說過血之競技場嗎，指揮官？\n\n很簡單。一隻叫莫古的大巨魔喜歡看人們為自己的生命跟野蠻的野獸戰鬥。充滿野心的哥布林葛爾薩克會負責安排戰鬥和從中獲利。\n\n總之，葛爾薩克跟我是老朋友了，他特別為你安排了一場特別的表演賽！很棒吧？只要跟他輕聲說：「我在尋找追尋者」就可以了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37776] = {title = "殺死暗流！", objective = "殺死位於影月谷昂布拉凡北方塔南海峽中的暗流。", description = "你好，指揮官！\n\n我有個壞消息。\n\n我們最近委託當地的漁夫去當間諜。我們付他們金幣，他們駕船去昂布拉凡湖北邊看看鋼鐵部落的動靜。雙贏，對吧？\n\n不過，事情卻沒有這麼順利。開往那裡的船沒有一艘回來。有一隻巨大的水元素，名字好像是叫暗流，只要看到船就毀掉。\n\n你能幫我們解決它嗎，指揮官？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37777] = {title = "殺死震顫！", objective = "在格古隆德殺死格古瑞克之殞西邊的震顫，並將一堆被消化一半的蝦怪肉帶回來。", description = "你在格古隆德的哨站有很嚴重的劍齒人問題，指揮官，而我們已經無法再繼續派兵去增援了。所以我有個主意。\n\n格古隆德的西岸有隻巨蟲叫震顫，最愛吃蝦怪。如果你把那玩意兒殺了，把那堆被消化一半的蝦怪肉帶回來，我們可以在這裡把肉煮熟並送到哨站那裡去，這一定能讓那些劍齒人安靜一段時間！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37778] = {title = "殺死巢王伊克里斯！", objective = "前往霜火峰的南風崖，從巢王伊克里斯那裡取得冰碎之殼。", description = "我們有一個全新的點子，就是在淬鍊過程使用寒冰劫毀者甲殼來冷卻我們的盔甲和武器。這是我們一直渴望的開創性作法，指揮官！\n\n問題是，劫毀者顯然不喜歡我們的人把牠們的甲殼剝下來。在霜火峰的南風崖有一隻特殊的劫毀者，叫做巢王伊克里斯 - 如果你能解決它，我們就可以有好幾個星期不用煩惱了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37779] = {title = "攪亂均勢", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][37780] = {title = "奧齊頓", objective = "擊敗奧齊頓的泰朗戈爾。", description = "指揮官，古爾丹的心腹手下泰朗戈爾已經潛入塔拉多爾的奧齊頓，準備吞噬裡面無以計數的靈魂。我們絕對不能讓這個作惡多端的術士繼續壯大。\n\n進入奧齊頓的神聖陵寢，擊潰泰朗戈爾和暗影議會的餘黨，以免造成更多傷害。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37781] = {title = "血槌熔渣礦場", objective = "擊敗血槌熔渣礦場的古格洛克。", description = "血槌巨魔都是殘暴的奴隸販子，指揮官。他們把德拉諾各地的無辜受害者拖進霜火峰的熔渣礦場，日復一日地挖掘寶石和礦石，裝滿一輛又一輛的推車，至死方休。\n\n我們認為他們已經轉移目標，專心挖掘某個力量無窮的古代聖物，好獻給巫王。\n\n那個叫古格洛克的巨魔在熔渣礦場以高壓手段發號施令。打垮他，礦場就會變成一盤散沙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37782] = {title = "恐軌車站", objective = "擊敗恐軌車站的傲天者托芙菈。", description = "我們要趕快採取行動了，指揮官。恐軌列車這時已經準備駛離恐軌車站，運送為數眾多的兵力到撒塔斯了。有傳言說他們在車上裝了強力武器，威力足以把保護內城的護盾轟個粉碎。\n\n傲天者托芙菈已經去護送列車前往塔拉多爾了。你必須阻止托芙菈，千萬不能讓恐軌列車抵達撒塔斯！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37783] = {title = "鋼鐵碼頭", objective = "擊敗鋼鐵碼頭的史庫洛克。", description = "鋼鐵碼頭對鋼鐵部落來說，是這場戰事的一大籌碼。我們的斥候回報，碼頭那裡動作頻頻，可能是要採取攻擊。\n\n有人目擊戈魯爾之子史庫洛克已經離開了黑石鑄造場，帶著威力強大的火砲，全副武裝，然後登上了他們一艘最為精良的戰艦。不管他們打算襲擊哪個地方，指揮官，你一定要想辦法摧毀鋼鐵碼頭，擊敗史庫洛克，千萬不能讓他們離開港口！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37784] = {title = "影月墓地", objective = "擊敗影月墓地的耐祖奧。", description = "耐祖奧也曾是高貴的獸人，他是影月氏族睿智的酋長，也是受人景仰的薩滿長老。他孤注一擲地加入鋼鐵部落，蔑視他曾珍視的一切，出賣先祖的靈魂，求取黑暗的禁忌之力…只為了取悅地獄吼。\n\n影月氏族就此沒落了，指揮官。進入他們的先祖墓地，阻止耐祖奧的瘋狂行徑，別讓他把德拉諾拱手送進虛無的虎口之中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37785] = {title = "擎天峰", objective = "擊敗擎天峰的大賢者維瑞思。", description = "大賢者維瑞思已經在阿拉卡山擎天峰的最高處完成了極具破壞力的水晶超級武器。她想以太陽神魯克馬爾之名，把「次等種族」趕盡殺絕。\n\n阿拉卡流亡者已經快被這可怕的武器殺光了。你必須立刻阻止維瑞思，別讓她把目標轉向你的要塞，指揮官！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37786] = {title = "永茂林", objective = "擊敗永茂林的亞爾努。", description = "祈倫托在格古隆德建了一個哨站，有道通往暴風城的傳送門，可以迅速傳送援軍，攻擊黑石鑄造場。沒想到，足智多謀的他們卻偏偏把哨站建在永茂林深處，那裡正是波塔尼和最強的傑那索 - 亞爾努的家園。\n\n哨站早已遭到佔領，而情勢蔓延到暴風城也只是遲早的事…甚至會遍及整個艾澤拉斯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37787] = {title = "黑石塔上層", objective = "擊敗黑石塔上層的札伊拉酋長。", description = "地獄吼的鋼鐵戰線先鋒已設法潛入黑石山，與龍喉氏族的札伊拉酋長結為同盟。在鋼鐵部落做好準備入侵艾澤拉斯之時，札伊拉正在黑石山的深山之中準備足可毀滅一切的終極武器，用以剷除他們面前的一切阻礙。\n\n你必須立刻阻止札伊拉，永絕後患，指揮官。她一直是我們的眼中釘，早就該拔掉了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
MultiLanguageQuestData['tw'][37788] = {title = "寶藏契約：古崔克砍刀", objective = "在破碎絕壁的巨魔身上尋找與金鏟的發現相關的線索。", description = "在納葛蘭，巨魔提到他們有一把叫做古崔克砍刀的古老武器。我很想要進一步研究它。\n\n一個名為瓦爾‧金鏟的哥布林寶藏獵人找到了這把武器的下落。很不幸地，這個哥布林在破碎絕壁失蹤了。或許他跟當地的居民起了衝突。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][37789] = {title = "黑石塔上層", objective = "擊敗黑石塔上層的札伊拉酋長。", description = "地獄吼的鋼鐵戰線先鋒已設法潛入黑石山，與龍喉氏族的札伊拉酋長結為同盟。在鋼鐵部落做好準備入侵艾澤拉斯之時，札伊拉正在黑石山的深山之中準備足可毀滅一切的終極武器，用以剷除他們面前的一切阻礙。\n\n你必須立刻阻止札伊拉，永絕後患，指揮官。她一直是我們的眼中釘，早就該拔掉了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n要塞資源"}
