MultiLanguageQuestData['tw'][38022] = {title = "ssault on the Temple of Sha'naar", objective = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle.", description = "The Sargerei council continues to work in secret with the warlock, Gul'dan. Up in the hills of Tanaan Jungle, they have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger their forces become.您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
