MultiLanguageQuestData['tw'][38044] = {title = "血濺血之谷", objective = "在塔南森林的薩斯格爾襲擊血之谷。", description = "血之谷獸人替塔南森林的鋼鐵部落提供了強大的增援。他們從薩斯格爾的根據地開始，無情地追殺我們的斥候，破壞我們的行動，並且讓古爾丹的魔法更加強大。\n\n我們應該考慮直接攻擊薩斯格爾，逼他們把兵力調回峽谷的另一側。這樣應該可以為我們爭取到一點喘息的空間…即便只能維持一陣子。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
MultiLanguageQuestData['tw'][38045] = {title = "血濺血之谷", objective = "在塔南森林的薩斯格爾襲擊血之谷。", description = "血之谷獸人替塔南森林的鋼鐵部落提供了強大的增援。他們從薩斯格爾的根據地開始，無情地追殺我們的斥候，破壞我們的行動，並且讓古爾丹的魔法更加強大。\n\n我們應該考慮直接攻擊薩斯格爾，逼他們把兵力調回峽谷的另一側。這樣應該可以為我們爭取到一點喘息的空間…即便只能維持一陣子。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
MultiLanguageQuestData['tw'][38046] = {title = "鋼鐵前線之戰", objective = "幫助聯盟及部落襲擊塔南森林的鋼鐵前線。", description = "將軍，我們的部隊在鋼鐵前線遭到聯合攻擊，戰情一路升溫，傷亡慘重。\n\n到鋼鐵前線報到，助我軍一臂之力吧。我相信當弟兄們親眼看見你上戰場的時候，一定會很振奮，讓我們迎向勝利！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
MultiLanguageQuestData['tw'][38047] = {title = "鋼鐵前線之戰", objective = "幫助聯盟及部落襲擊塔南森林的鋼鐵前線。", description = "對抗鋼鐵部落的戰爭如火如荼展開。\n\n我們的戰士正在離此不遠的鋼鐵前線，與敵人進行一場不共戴天的戰爭。他們帶著強大的怒火頑強抵抗，但是損傷慘重。\n\n前往鋼鐵前線，明明白白的告訴敵人，這場戰爭我們絕不退讓。\n\n讓他們看看我們像狼群一樣奮戰！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
