MultiLanguageQuestData['tw'][38175] = {title = "熔解碎塊", objective = "克麗絲汀‧石鑄要你收集25個鋼鐵部落碎塊。", description = "我們在熔解你收集來的金屬碎塊時，有了突破性的進展！如果你能替我帶來一小堆碎塊，我們能夠替你的部隊做出一些有用的東西。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n護甲改良工具武器改良工具"}
MultiLanguageQuestData['tw'][38176] = {title = "文件：進攻石怒崖", objective = "在霜火峰突擊石怒崖的血槌巨魔。", description = "來自霜火峰的血槌巨魔不斷突襲這片土地的貿易路線，並且把被俘的士兵丟到他們的熔渣礦坑中工作。\n\n暗影獵手洛克漢要求你到石怒崖的血槌主要營地中，救出被俘的友軍部隊。", progress = nil, completion = "戰鬥捷報已先傳回，一些戰利品也運回來了，老大。\n\n你真是一股不可小看的力量。", rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38177] = {title = "文件：進攻麥奈洛克", objective = "前往霜火峰的麥奈洛克，向岩石巨怪發動攻擊。", description = "巨大的麥奈隆、古羅，還有其他岩石巨怪一直是我們要塞的威脅，而看起來他們大多數來自於北方的麥奈洛克。\n\n如果我們攻擊他們的大本營，就應該能強迫他們撤退。雖然相當危險，但這應該是我們最好的戰術了。既然你要去麥奈洛克，那也試著帶點我們的補給品回來。", progress = nil, completion = "戰鬥捷報已先傳回，一些戰利品也運回來了，老大。\n\n你真是一股不可小看的力量。", rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38178] = {title = "文件：進攻鋼鐵軍火廠", objective = "前往霜火峰的鋼鐵軍火廠，對鋼鐵部隊發動攻擊。", description = "鋼鐵部落的戰爭機器正大量運往戰場，而我們的部隊也在苦苦支撐。大多數的戰爭機器似乎是在霜火峰東部的鋼鐵軍火廠製造的。\n\n如果想逆轉戰局，一次擾亂並瓦解軍火廠鋼鐵部落的戰略性攻擊，可能正是我們需要的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38179] = {title = "文件：進攻永茂林野地", objective = "前往格古隆德的永茂林野地，對波塔尼軍隊進行攻擊。", description = "波塔尼和那些它們製造出來的植物怪獸不斷在蠶食鯨吞著我們的北方哨站。不管我們殺了多少，似乎都會有同樣數量的敵人在原地長出來。\n\n洛克漢已經擬定了一套計畫，目標是攻擊它們領土的核心：永茂林野地。洛克漢認為如此一來它們就會退回格古隆德的叢林中，讓我們有更多喘息的空間。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38180] = {title = "文件：進攻破碎絕壁", objective = "前往納葛蘭的破碎絕壁，對歐格隆部隊進攻。", description = "大量的歐格隆正在猛攻我們的前線，而且不管我們打倒多少敵人，都會有更多的人補上。\n\n大部分的歐格隆似乎來自破碎絕壁，位於納葛蘭西部深處。如果我們想在接下來的戰事中掌握一線生機的話，我們就要想辦法根除這些戰場上的歐格隆。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38181] = {title = "文件：進攻莫克戈爾哨站", objective = "前往納葛蘭的莫克戈爾哨站對戰歌部隊發動攻擊。", description = "莫克戈爾哨站派出的戰歌劫掠者不斷威脅著不受高牆保護的地區。我們已經警告旅人不要獨自在外行動，但還是有許多人充耳不聞。\n\n如果我們可以對莫克戈爾哨站發動一場攻擊，就很有可能讓戰歌獸人必須回防，並且讓劫掠者的活動區域限制在納葛蘭境內。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38182] = {title = "文件：進攻暗潮棲息地", objective = "前往影月谷的暗潮棲息地，對鋼鐵部落部隊發動攻擊。", description = "在對抗鋼鐵部落的遭遇戰當中，我們發現戰場上萊拉克的數量源源不絕。如果我們不斬斷萊拉克的來源的話，很快就會失去道路的控制權，然後被迫撤退到哨站裡面。\n\n這些額外的萊拉克很有可能來自於影月谷東南方的暗潮棲息地。如果我們動作夠快的話，就還有可能在它們全面行動之前解決一切。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38183] = {title = "文件：進攻索奎薩爾高地", objective = "前往影月谷的索奎薩爾高地，對薩格萊部隊發動攻擊。", description = "目前情報顯示，影月谷南方索奎薩爾高地的薩格萊部隊開始頻繁活動。\n\n索奎薩爾的信徒對德拉諾各地造成威脅。我們絕不能讓他們在我們控制區域外有立足之地。", progress = nil, completion = "戰鬥捷報已先傳回，一些戰利品也運回來了，老大。\n\n你真是一股不可小看的力量。", rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38184] = {title = "文件：進攻失落的維爾安祖", objective = "前往阿拉卡山的失落的維爾安祖，對敵對生物發動攻擊。", description = "我們一些最好的斥候在維爾安祖的廢墟附近消失蹤影。\n\n洛克漢已請求調動可用資源，前往找出威脅來源，並調查廢墟內是否還有友軍存活。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38185] = {title = "文件：進攻命運之柱", objective = "突襲影月谷中，位於命運之柱的影月獸人。", description = "殘存的影月氏族還持續地在阿拉卡山東側邊界的山上行動。\n\n洛克漢顧忌他們太過靠近通往影月谷的要道，因而要求我們盡快削弱他們的兵力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38186] = {title = "文件：進攻司凱堤斯", objective = "前往阿拉卡山的司凱堤斯，對阿拉卡部隊發動攻擊。", description = "我們經常接獲回報，指出來自南方的鳥人會突襲並燒毀大路上的商隊。\n\n位於我方前哨站的守衛要求對位於阿拉卡山，司凱堤斯境內的魯克馬爾擁護者展開反擊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][38187] = {title = "文件：進攻撒塔斯港", objective = "在塔拉多爾的撒塔斯城，突擊薩格萊的部隊。", description = "撒塔斯城目前受到薩格萊兵力的控制，其由先前為主教的索奎薩爾所領導。\n\n在東側城市的暗影議會兵力透過虛空惡魔的協助而取得力量，必須要在他們威脅到我方所有行動之前，就加以剷除。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
