MultiLanguageQuestData['tw'][38267] = {title = "天上的朋友", objective = "到阿克塔崗哨和瑞薩德見面。", description = "伊斯卡失蹤，現在暗影議會又緊緊地掐住我們的喉嚨。這兩件事肯定脫不了關係。我們得去可拉納克廢墟看看，那是他最後現身的地方。\n\n我請一位朋友在附近架設了營地。我建議我們應該前往那裡，繼續搜尋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38269] = {title = "天上的朋友", objective = "到阿克塔崗哨和瑞薩德見面。", description = "伊斯卡失蹤，現在暗影議會又緊緊地掐住我們的喉嚨。這兩件事肯定脫不了關係。我們得去可拉納克廢墟看看，那是他最後現身的地方。\n\n我請一位朋友在附近架設了營地。我建議我們應該前往那裡，繼續搜尋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38270] = {title = "尋找殺手", objective = "在薩斯格爾附近找到殺了血之谷獸人的兇手。\n\n已提供物品：\n", description = "你在這張地圖上看出了這些攻擊的發起點。該是時候查清楚這些攻擊背後的真相、究竟是誰下的手，以及有沒有可能成為我們的盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38271] = {title = "沿著血腥道路", objective = "跟著阿利歐克到洞窟", description = "我殺死的那些獸人…他們提到一個洞穴。對血之谷氏族而言十分神聖。基爾羅格可能在那邊，我要動身了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38272] = {title = "血之谷", objective = "抵達血之谷底端。", description = "這個洞穴吸引我過來，它讓憤怒的靈魂在這附近徘徊。基爾羅格在這裡用過魔法，你要幫我瞭解…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38273] = {title = "血之谷靈魂", objective = "殺死6個暴怒的血魂。", description = "很明顯的是，洞穴受到威力強大的鬼魂所保護，那些都是血之谷的祖先。\n\n不管下面有什麼東西，能夠率先解決這些靈魂的威脅，會讓事情變得簡單一些。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38274] = {title = "基爾羅格之眼", objective = "找到基爾羅格之眼，進行占卜儀式。", description = "如果你想知道基爾羅格和他的新主人在打什麼主意，你需要他的眼睛。在儀式完成之後，所有的酋長都會把他們的眼睛放在隔壁房間，接受血之谷鬼魂的保護。\n\n去那裡取得基爾羅格之眼。但是其他酋長的鬼魂不會站在我們這一邊，一定會奮力抵抗。\n\n接下來，把它放在附近的儀式符陣上，就可以找到答案。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n邪怨護手"}
