MultiLanguageQuestData['tw'][38499] = {title = "新奇礦石", objective = "取得10個脈石礦石。", description = "鐵匠，你聞到了嗎？喔喔喔…是機會的味道。\n\n達拉然把我們帶到新鮮有趣的地方，充滿了神秘的金屬。我必須在這裡顧店，不過…你可以自由探索和採礦。\n\n帶給我一些有趣的東西，看看它到底有什麼用途。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n軍團鍛造\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38500] = {title = "精通脈石鍛造", objective = "按照你的鍛造設計圖列表中的艾拉得‧席彌德設計圖，製造手工脈石護手。", description = "很好，現在我們有助熔劑了，可以正式開始，看看是否順利。你這次要不要親自動手，幫我做一些護手？我會在旁邊看著…大概會稍微站遠一點吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][38501] = {title = "盤恨鍛造工藝", objective = "取得一副精工盤恨胸甲和精工盤恨肩鎧。", description = "我們或許有辦法立刻開始研究脈石。\n\n我聽說艾蘇納這裡有納迦營地。如果他們在艾蘇納待得夠久，他們的鐵匠一定早就開始對脈石進行實驗。\n\n麻煩你留意納迦身上的脈石護甲…最好是比護腕更精巧的東西。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][38502] = {title = "夜落精靈的手法", objective = "取得1個上古哨衛傀儡記憶核心。", description = "我有個想法，<name>。\n\n你之前遇過艾蘇納的夜落精靈嗎？他們是精靈貴族的後代，而精靈貴族鐵匠的工藝技術絕對是舉世無雙。\n\n這些夜落精靈掌握了某些秘法工藝，製作了哨衛在營地巡邏。\n\n幫我從其中一個哨衛身上取回記憶核心。說不定可以從中學到一些鐵匠知識！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38505] = {title = "工程師：還有一點點用處", objective = "把上古哨衛傀儡記憶核心帶到達拉然給提摩菲‧歐杉科。", description = "很抱歉，我完全不曉得如何擷取這個核心中的資訊，不過我知道有人會。\n\n請去隔壁隔壁再隔壁的工程學商店「精準如錶發條舖」。提摩菲‧歐杉科欠我一個人情，他應該能擷取這個核心的記憶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38506] = {title = "鬼畫符", objective = "將遠古精靈貴族資料交給達拉然的帕林教授。", description = "我剛好有工具可以幫你擷取這個核心中的資訊。\n\n<提摩菲把核心放入明顯是哥布林出品的機器儲存槽中，然後蓋住耳朵。>\n\n你最好把眼睛移開，鐵匠。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38507] = {title = "脈石鍛造的奧秘", objective = "把脈石鍛造指南帶給達拉然的艾拉得‧席彌德。", description = "「我會花好幾個小時來鑽研這些精采手稿的內容！」\n\n…但是這東西太簡單了，像我這樣的專家根本沒機會說這句話！這些手稿和所謂的「脈石鍛造」有關。\n\n<地精在卷軸背後寫下翻譯內容。>\n\n翻好了，一字不漏，下次帶有趣一點的東西過來吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38513] = {title = "高嶺鐵匠", objective = "在高嶺與巴姆‧碎石者交談。", description = "我想接下來的部份已經超乎我的知識範圍了，<name>。\n\n高嶺牛頭人一族一定有一些鐵匠。看看你能不能從他們身上學到進一步提升脈石鍛造技藝的方式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38514] = {title = "有待進步", objective = "運用你的鍛造技術製作一副脈石護手給巴姆。", description = "想要我教你如何提升你的技藝？我們不可能聽你說個幾句，就把商業機密分享給你。\n\n不過我們確實十分重視工藝和紀律。\n\n來瞧瞧你的鍛造技術。我們的綠角受訓者在那裡使用小小的鐵砧。做出你最好的一對護手，讓我看看你的實力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38515] = {title = "天然原料", objective = "取得10朵狐花。\n\n如果你不是草藥師，可以去拍賣場購買狐花，或與其他玩家交易。", description = "非常有趣，這表示脈石只要碰到任何外來異物，就會形成劇烈反應。我們從外面帶進來的助熔劑已經足以引發小型爆炸。\n\n不過，當地原料卻能與脈石共存。高嶺上生長著稱為狐花的草藥，可以製作成合適的助熔劑。\n\n請去採集一些狐花，然後我們就能製作合用的助熔劑。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n狐花助熔劑"}
MultiLanguageQuestData['tw'][38518] = {title = "師從多人", objective = "在達拉然回去找艾拉得，跟他分享你從牛頭人身上學到的東西。", description = "年輕人，現在回去找你在達拉然的師傅\n，繼續練習你的技術。如果想多學一點東西，隨時都能回來找我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38519] = {title = "沉灰", objective = "進入深徑洞穴，找庫卜魯取得高嶺牛頭人的古老戰錘「沉灰」。", description = "我們部族會定期用脈石製作腿鎧。我願意跟你分享圖樣…只要你幫我個忙。\n\n我爸爸在好幾年前被卓格巴殺死，他們把他的錘子當成戰利品。那把錘子是我們家族的傳家寶，現在卻落入邪惡的卓格巴庫卜魯手裡。\n\n我非常希望它能重回我們家族的懷抱。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：脈石護脛\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38522] = {title = "不是只有武器和護甲", objective = "製作4個特硬脈石鑄塊和24個特硬脈石釘。", description = "你懂的，我們不只是會做武器護甲。我也經常製作銘刻用的鑿子、鍊金師的爐缸，甚至是裁縫的頂針。\n\n如果不想讓自己的姆指被針刺到，就應該戴著包住整隻手的護手縫紉。\n\n總之，我有像你這樣的冒險者會感興趣的配方，來試試看吧。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：脈石蹄甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38523] = {title = "脈石蹄甲", objective = "騎著坐騎去找梅‧法蘭西斯，幫你的坐騎裝上脈石蹄甲。", description = "拿去，帶著這些蹄鐵去找坐騎和寵物商店的梅‧法蘭西斯，讓坐騎的足部獲得保護。\n\n等你回來後，我就會分享圖樣。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：脈石蹄甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38524] = {title = "魔匠娜麗莎", objective = "到蘇拉瑪爾找魔匠娜麗莎回報。", description = "鐵匠圈現在流傳著一個說法，據說一對伊利達瑞鐵匠在惡魔橫行的蘇拉瑪爾前線，有了非常創新的成就。我很想自己去一探究竟，但是，「惡魔橫行」這種形容詞實在與我的品味不符。\n\n我負責打造護甲，但我可不想自己穿上！\n\n你，呃…你可以去幫我看看。在那裡看看找不找得到娜麗莎。據說她是個非常優秀的鐵匠。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38525] = {title = "團隊的一份子", objective = "在魔魂堡中殺死40隻惡魔。", description = "你是個鐵匠？\n\n<精靈看了你的錘子一眼。>\n\n還在學習脈石的用法，是嗎？我或許可以幫你。\n\n聯盟現在贏得很艱難。你的臉長得很好看，不過這不代表你有能力解決惡魔。我現在還沒辦法信任你。\n\n等你全身沾滿惡魔的血液後再回來，到時我們再來討論鍛造的事。", progress = nil, completion = "這樣就夠了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38526] = {title = "火鍛法", objective = "遵從魔匠娜麗莎的指示，製作脈石長靴。", description = "你缺少長靴的配方？\n\n怎麼回事，你是接受牛頭人的訓練嗎？\n\n那要快一點，距離惡魔下次攻擊，可能只有幾分鐘的時間。這兒有個圖樣，讓我看看你的作品。", progress = "上了前線，就要步步為營。你現在已經不是在和平的浮空之城鐵匠舖了。", completion = "還不錯，&lt;class&gt;。你知道如何揮動錘子。", rewards = "您會學到：\n\n設計圖：脈石長靴\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38527] = {title = "娜麗莎的技藝", objective = "取得60個脈石礦石和60個魔岩。", description = "聽好，<class>。要是我們不幸死在對抗燃燒軍團的戰爭中，我們需要像你這樣的鐵匠去延續伊利達瑞的傳統。你已經做好學習的準備。\n\n帶給我很多很多材料。等到你回來，我們還有很多事要討論。", progress = "準備好開始學習了嗎？", completion = "很好，讓我們開工吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38528] = {title = "脈石潛能", objective = "運用魔匠娜麗莎的技術製造一副精工脈石臂甲。", description = "我相信你自己也明白了，你目前所知的脈石配方都還有改進的空間。\n\n只要學會掌握脈石潛藏的力量，你就能減少需要用到的材料，並獲得等量的成果。來吧，我示範給你看。\n\n按照慣例，我們先從最簡單的護腕開始。這一個部位的護甲可以受益於硫磺符文。自己親眼見證吧。", progress = "保持下去，<class>。", completion = "做得好。\n\n脈石是一種易變金屬。加入硫磺可以強化脈石臂甲，但是如果要提高肩墊的品質，就需要附魔之塵。頭盔則可受益於未雕刻的寶石，諸如此類。", rewards = "您會學到：\n\n設計圖：脈石臂甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38530] = {title = "蒼天之石", objective = "在高嶺與巴姆‧碎石者交談。", description = "處理魔岩和惡魔鋼的時候，需要用到特殊的設備。尤其是要有一個堅固的鐵砧，足以承受敲擊魔岩時散發的能量。\n\n烏瑞爾和我沒有這種鐵砧，不過你的朋友高嶺牛頭人有。\n\n想辦法獲得蒼天之石，那是他們的神聖鐵砧，然後我們才能繼續處理惡魔鋼。", progress = nil, completion = "你回來了，&lt;name&gt;。你想來接受更多訓練嗎？\n\n什麼？蒼天之石？\n\n\n\n這可不得了啊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38531] = {title = "脈石精通", objective = "向薩菈‧鋼圖騰購買一個脈石護甲架，然後把八件脈石護具都掛上去。", description = "在處理蒼天之石之前，鐵匠必須先證明自己已經能將脈石運用自如。\n\n製作一整套脈石護甲，然後交給我檢查。薩菈可以為你提供護甲架。", progress = "記住，<name>：我絕不容忍敷衍了事。", completion = "&lt;牛頭人仔細檢查你的作品，眉頭深鎖。&gt;\n\n看得出來你真的有學到東西。\n\n非常好，你成功了。", rewards = "您會學到：\n\n設計圖清單：宗師級脈石鍛造\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38532] = {title = "靈魂之喉：飽受風吹雨打", objective = "前往靈魂之喉，取回上古維酷人之錘。", description = "你的錘子看來脆弱不堪，大概在擊打蒼天之石的時候就會壞裂。\n\n古老維酷鍛造大師以其戰錘的強度聞名。我們要拿到這種戰錘的唯一方法，就是前往維酷人死後會去的世界。前往靈魂之喉。\n\n主管維酷冥界的女神名叫黑爾雅。她出於私慾，收藏亡者攜帶的飾品。\n\n打敗她，你或許就能獲得這樣的戰錘。", progress = "你有拿到那個東西嗎？", completion = "&lt;巴姆將戰錘放於掌中，緩慢翻轉檢視。&gt;\n\n這可真是把好鎚！", rewards = "您會收到：\n\n布蘭迪斯拉，弗洛斯克之錘"}
MultiLanguageQuestData['tw'][38533] = {title = "部族知識", objective = "在蘇拉瑪爾找魔匠娜麗莎回報。", description = "首先，你必須要有惡魔鋼護甲的正確圖樣。雖然透過努力和堅持就能使用蒼天之石，但我們的設計圖只會教給值得信賴的部族成員。\n\n如果你要討論惡魔鋼護甲的圖樣，也許你該去找別的鐵匠。", progress = nil, completion = "我就知道牛頭人不可能會輕易分享他們的設計圖。雖然我們不像他們…那麼有牛脾氣，但我們的設計圖也不是隨隨便便就能得到的。\n\n然而，你獲得了蒼天之石的使用權，為我和烏瑞爾找到另一個偉大鐵砧。\n\n我們願意把這張設計圖送給你，作為我們的謝禮。", rewards = nil}
