MultiLanguageQuestData['tw'][38585] = {title = "進攻基爾加丹王座", objective = "在塔南森林的基爾加丹王座擊敗暗影議會。", description = "暗影議會正在一座他們稱之為基爾加丹王座的山上，召喚他們的惡魔主人。千萬別出差錯，那是全塔南最危險的地區。\n\n集結一支作戰隊伍突擊基爾加丹王座，別讓燃燒軍團在那裡設下立足點！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
MultiLanguageQuestData['tw'][38586] = {title = "進攻基爾加丹王座", objective = "在塔南森林的基爾加丹王座擊敗暗影議會。", description = "暗影議會正在一座他們稱之為基爾加丹王座的山上，召喚他們的惡魔主人。千萬別出差錯，那是全塔南最危險的地區。\n\n集結一支作戰隊伍突擊基爾加丹王座，別讓燃燒軍團在那裡設下立足點！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
MultiLanguageQuestData['tw'][38587] = {title = "進攻基爾加丹王座", objective = "前往塔南森林的基爾加丹王座，突擊暗影議會的部隊。", description = "暗影議會正在一座他們稱之為基爾加丹王座的山上，召喚他們的惡魔主人。別忘了第一次戰爭的教訓，我們都知道如果不阻止燃燒軍團會造成多可怕的後果。\n\n前往基爾加丹王座，截斷敵人的入侵計畫，別讓他們有機會開始。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][38588] = {title = "進攻基爾加丹王座", objective = "前往塔南森林的基爾加丹王座，突擊暗影議會的部隊。", description = "暗影議會正在一座他們稱之為基爾加丹王座的山上，召喚他們的惡魔主人。別忘了第一次戰爭的教訓，我們都知道如果不阻止燃燒軍團會造成多可怕的後果。\n\n前往基爾加丹王座，截斷敵人的入侵計畫，別讓他們有機會開始。", progress = nil, completion = nil, rewards = nil}
