MultiLanguageQuestData['tw'][38595] = {title = "瑪法里恩之怒", objective = "與伊瑟拉交談以尋找瑪法里恩。", description = "塞納留斯遭到夢魘所害，對我們所有人都是嚴重的打擊。\n\n也怪不得瑪法里恩怒不可遏，但他對薩維斯的憎恨已延續數個世紀，我害怕他的盲目怒火將反遭人用來對他不利。\n\n希望伊露恩能指引我們盡快找到他，否則今天我們可能將失去另一位好友。", progress = nil, completion = "噢，&lt;name&gt;…\n\n這塊土地怎麼會變得這樣？", rewards = "您會收到：\n\n"}
