MultiLanguageQuestData['tw'][38710] = {title = "緊急集合", objective = "集合崔瓦和歐利克‧真心，然後到卡薩斯平臺與麥斯威爾‧泰羅索斯領主會合。", description = "現在必須當機立斷，<name>。\n\n燃燒軍團讓我們在破碎海岸的大軍幾乎全軍覆沒。有史以來最強大的軍隊瞬間毀於一旦。\n\n我們必須召集有志之士，拯救我們的家園。提爾的衛士崔瓦和歐利克‧真心分別制定了計畫，而我們也不能袖手旁觀。\n\n請你找到他們，帶他們到卡薩斯平臺，然後一起做出最後決策。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38711] = {title = "看守者璽戒", objective = "將看守者璽戒交給亞羅德‧影歌。\n\n已提供物品：\n", description = "夜精靈身上帶著一枚璽戒，上面刻著看守者的徽章。\n\n這枚指環由堅不可摧的銀光金屬打造，由主人不經意地轉動和磨擦手指所造成的痕跡，可以看出戴了很長一段時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38714] = {title = "瑪翼夫的蹤跡", objective = "搜尋熔爐，劍刃豹圍欄和哨塔。", description = "前方就是堡壘的領地。要搜索的範圍很大，但如果我們分頭行事，應該可以加快進度。\n\n在囚犯牢籠、熔爐和哨塔中，搜尋瑪翼夫的蹤跡。我去搜尋上層壁壘，並在堡壘的另一端和你會合。", progress = nil, completion = "做得好，&lt;name&gt;。他們想必已經把瑪翼夫移到塔底的牢房了。", rewards = "夜谷裹腕鴉衛護臂擁棘腕甲黑革臂環遠尋者披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][38715] = {title = "玄鴉堡守衛隊", objective = "殺死凱斯特‧遠尋者、崔蘭‧破盾者和斯塔麗絲‧強弓。", description = "這已不是我記憶中的玄鴉堡。這裡的牆壁崩塌，幾乎無法想像往日榮光。\n\n如果黑羽堡主真的復活了，他之前的副官一定也在他身邊。\n\n凱斯特‧遠尋者，守衛隊隊長。\n\n崔蘭‧破盾者，蓋世無雙的釘錘大師。\n\n還有蒙住雙眼也能百步穿楊的斯塔麗絲‧強弓。\n\n我們一定得先把他們解決掉，才有可能進入塔中。", progress = nil, completion = "多謝你，&lt;name&gt;。願他們的靈魂安息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38716] = {title = "玄鴉堡", objective = "將看守者璽戒交給亞羅德‧影歌。", description = "箱子裡藏了一枚刻著獨特徽章的璽戒，混在各式各樣的裝飾品之間。\n\n這枚指環由堅不可摧的銀光金屬打造，由主人不經意地轉動和磨擦手指所造成的痕跡，可以看出戴了很長一段時間。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][38717] = {title = "玄鴉監牢", objective = "殺死艾拉克薩斯並取得監牢鑰匙。", description = "經歷了這麼多，我絕不會在這最後一刻放棄她。\n\n瑪翼夫一定被關在玄鴉堡下方的牢房裡。\n\n我從上面偵察過了，前住牢房的入口由壯碩的惡魔獄卒守著。\n\n我會溜過去先解決掉裡面的守衛。打倒艾拉克薩斯，取得鑰匙，再到裡頭和我會合。", progress = "你拿到鑰匙了嗎？", completion = "很好，這些鑰匙應該可以打開監牢內的任何牢房。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38718] = {title = "克塔羅斯‧黑羽", objective = "檢視黑羽家徽。", description = "黑羽大人是無畏的領導者，是經驗豐富的指揮官，既正直又有榮譽心，以族人為重，是我們所有人的表率。\n\n瑪法里恩、伊利丹、泰蘭妲，還有我…在他引領我們追尋自己的使命時，當時我們都還很年輕。\n\n他的家族徽記名揚天下，赫赫有名。請檢視他之前安息地點上方的家徽，我會告訴你更多關於他的傳說。", progress = nil, completion = "攻擊我們的靈魂一直喊著「堡主」和「大人」。我想燃燒軍團已經讓黑羽堡主復生，並加以控制、操縱。至於如此邪惡的復生，又有什麼代價，我就不知道了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38719] = {title = "解救伊利達瑞", objective = "救出席里斯‧黯翼、凱西爾‧夜棘和雅夏‧鴉曲。", description = "<這位伊利達瑞惡魔獵人身上有幾道恐怖傷口正在流血。看來他被丟在這裡等死。>\n\n在牢房中還有三位…<咳>…同伴。\n\n我們在偵察那個區域的時候遭到突襲。\n\n我時間不多了，但請你救救他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38720] = {title = "非走不可", objective = "疏散弦月旅店和海妖守望的倖存者。", description = "艾莉珊德對弦月旅店發動的攻擊，讓許多人猝不及防。我的許多同胞不是死了就是被帶走了。\n\n有些同胞可能還在默默忍受，我們需要確保他們沒有留在那裡。\n\n我需要你去那附近，在房舍中搜尋倖存者，在他們被發現之前讓他們逃走。說服他們，他們不該留下來。\n\n至少，在艾莉珊德的暴政之下，先離開這裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾攸爾的枴杖"}
MultiLanguageQuestData['tw'][38721] = {title = "塔裡的中尉", objective = "殺掉德斯戴‧星眼", description = "你的猜測全都正確。古爾丹讓黑羽堡主從墓地裡復活，讓他的軍隊成了一支鬼魅大軍。現在他們為燃燒軍團效力，保護塔中的秘密。\n\n雖然黑羽在頂端指揮，但負責牢房運作的是德斯戴‧星眼中尉。\n\n這幾個月我持續被他拷問，但我沒有屈服。\n\n<瑪翼夫用一根手指滑過她的刀刃。>\n\n該結束他的生命了。", progress = nil, completion = "星眼來自貴族之家，但是在戰爭中，他的實力遠遠不及黑羽或我弟弟。\n\n打倒他之後，我們終於可以將注意力轉到他的指揮官身上。\n\n不過，接下來的工作將會相當困難。在面對黑羽堡主之前，必須集結我們的力量。", rewards = "受庇佑的明月之盃塔樓魔導師之眼獄卒的貓尾艾拉克薩斯的徽章永焰箭頭死神的寒鏡裂片鴉火礦石沃露苔蟄眠影蟲藥劑堡壘天懼的指環伊露恩露澤法印小巧的精靈貴族玩偶審問者的藥瓶古爾丹的委任徽章審判官的烙鐵尖端不屈冰凍之拳鍛造大師的錘頭重拾活力薰香一塊升起的夜刃豹皮隨風飄揚的堡壘旌旗鴉廷田野鐮刀您會收到：\n\n星眼寶石"}
MultiLanguageQuestData['tw'][38723] = {title = "阻止古爾丹！", objective = "進入背叛者牢獄，殺死粉碎者和大鎚，並奪取他們的魔化能量。", description = "自從在黑暗神廟擊敗伊利丹後，我們把他的屍身搬來這裡，永遠埋藏在看守者鐵獄之中。\n\n不過，古爾丹突破了我們的防線，企圖偷走背叛者的屍身。\n\n就算死了，燃燒軍團還是可以利用伊利丹的屍身。絕對不能讓古爾丹得逞。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n蠻恨撤離\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38724] = {title = "姊弟情深", objective = "在玄鴉監牢找到瑪翼夫‧影歌。\n\n已提供物品：\n", description = "瑪翼夫就在監獄某處。我在來這裡的路上發現她的護甲。\n\n我們分頭搜索牢房吧，這樣比較快。\n\n我們必須找到她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38725] = {title = "深入魔育所", objective = "在魔育所和珂娃絲‧血棘會合。", description = "我審問的其中一隻惡魔透露了非常有用的消息。顯然，火山裡有隻鬼母知道燃燒軍團的秘密。\n\n珂娃絲‧血棘已經出發去找那隻惡魔，等她回來，我們或許就能知道秘密到底是什麼。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
