MultiLanguageQuestData['tw'][38727] = {title = "阻止轟炸", objective = "摧毀軍團毀滅者。", description = "捷斯的防護結界撐不了多久。我們需要有人深入前線，確保那些軍團毀滅者大砲都被解決掉。\n\n<凱恩用靈視之眼意有所指地看著你。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38728] = {title = "鑰石", objective = "殺掉育母蛛后泰蘭娜，取走薩格萊特鑰石。然後到下方的傳送門大廳和其他人會合。", description = "<name>，育母蛛后泰蘭娜就在前面的指揮室。其他人已經先衝進去了。她身上有薩格萊特鑰石。\n\n我們犧牲這麼大，總算快拿到手了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "育母蛛后的面紗育母蛛后的面紗您會收到：\n\n"}
