MultiLanguageQuestData['tw'][38753] = {title = "惡魔的蹤跡", objective = "找到瑪法里恩‧怒風。", description = "瑪法里恩一定就在附近，我感覺得到他的氣息…\n\n你去安杜塔拉山巔那邊找找，我會繼續在森林中搜尋。\n\n動作快，<name>，刻不容緩！", progress = nil, completion = "我丈夫，瑪法里恩，他怎麼了？！\n\n快告訴我！", rewards = "您會收到：\n\n墮落者圖騰"}
