MultiLanguageQuestData['tw'][38777] = {title = "脈石礦床樣本", objective = "把脈石礦床樣本帶到達拉然給蒂格媽媽。", description = "這顆礦石與你之前看過的完全不同。\n\n金屬內部彩光流轉，形成複雜多變的紋路。達拉然的訓練師一定很想見識一下。", progress = "你帶了什麼東西過來，小伙子？", completion = "如此明亮，如此漂亮！讓我聯想到源質礦。\n\n如果找到更多像這樣的礦石，試著沿著紋路敲打，比較不會浪費礦石。", rewards = "您會學到：\n\n採礦技術：脈石礦床\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38778] = {title = "轉動符石", objective = "在符文之林內啟動符石。", description = "我的樹根枯朽…我的枝幹死去…\n\n骸語氏族，他們想讓符文之林永遠沉默。關鍵就在符石上…\n\n轉動符石…解開我的束縛…", progress = nil, completion = "當符石解開束縛，我在森林內聽到的，就是你的腳步聲？\n\n十分感謝你，外來者。", rewards = "您會收到：\n\n"}
