MultiLanguageQuestData['tw'][38872] = {title = "黑暗女王的要求", objective = "在喚懼平台和納薩諾斯‧凋零者碰面。", description = "啊，這些傢伙是我方的人嗎？他們還沒把公爵夫人吃了，這應該是好現象…。\n\n總之呢，我有命令在身。納薩諾斯趕上了黑暗遊俠。他們奉希瓦娜斯女士本人的命令登上忘卻號，執行秘密任務！很不幸聯盟得知我們的計畫，現在葛雷邁恩正在攻擊崗哨！\n\n那裡真的很需要你的協助，<name>。公爵夫人能帶你去那兒，跟我說一聲就行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38873] = {title = "清除甲板！", objective = "在葛雷邁恩進攻據點發射4具被遺忘者投石車。", description = "我們在斯寇亞胥的任務目標暫時必須往後延了，<class>。現在，我們有更要緊的事情迫在眉睫。\n\n我和突擊增援部隊才剛抵達，葛雷邁恩的船隻就航進海灣，開始轟炸我們的城牆。我們部署了攻城武器，但是他們的地面部隊很快就讓我們潰不成軍。\n\n如果你能夠到投石車那邊去，並解決掉操作火砲的聯盟狗，就可以為我們爭取到足夠的空間，讓我們把戰線推回去！", progress = nil, completion = "哈！當荒疫吞噬他的船員時，葛雷邁恩就會發現他的火砲派不上用場了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38876] = {title = "進攻魔化熔爐", objective = "前往塔南森林的鐵握港，襲擊鋼鐵部落援軍。", description = "鋼鐵部落持續從德拉諾各地調動援軍，來鞏固他們在地獄火堡壘的勢力。如果我們不打斷補給線，就有可能無力按照原定計畫、固守塔南。\n\n想要讓鋼鐵部落轉為守勢，並維持我方氣勢，最合適的做法就是對鐵握港的補給線進行一波策略性攻擊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
MultiLanguageQuestData['tw'][38877] = {title = "進攻魔化熔爐", objective = "前往塔南森林的鐵握港，襲擊鋼鐵部落援軍。", description = "鋼鐵部落持續從德拉諾各地調動援軍，來鞏固他們在地獄火堡壘的勢力。如果我們不打斷補給線，就有可能無力按照原定計畫、固守塔南。\n\n想要讓鋼鐵部落轉為守勢，並維持我方氣勢，最合適的做法就是對鐵握港的補給線進行一波策略性攻擊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶"}
MultiLanguageQuestData['tw'][38878] = {title = "盾中秘密", objective = "在斯寇亞胥檢查6面紋刻維酷盾牌。", description = "我們的目標就在那座神殿裡，<class>。我沒時間仔細說明 - 你只需要知道在這裡成功對被遺忘者至關重要。\n\n女盾侍的防禦十分頑強，但可能還有其他方式可以進入神殿。她們之中，有少數受選的戰士得以進入神殿。你要去查明是怎麼辦到的。\n\n我在城鎮裡看到雕工複雜的盾牌，我認為是這些勇士傳下來的。她們所描繪的場景可能是進入神殿的關鍵。", progress = nil, completion = "我希望你帶來的是好消息，&lt;class&gt;。\n\n這樣對你我都好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38882] = {title = "不死者的新生", objective = "跟隨希瓦娜斯進入埃伊爾之殿。", description = "你似乎不時帶來驚奇，<name>。在華爾琪拉女王的祝福之下，你開啟了一條將會重塑艾澤拉斯命運的道路。\n\n我邀請你來此見證，今天是被遺忘者的新黎明！", progress = nil, completion = "看來我們低估了葛雷邁恩的韌性 - 被遺忘者為這個錯誤付出慘痛代價。\n\n不過，埃伊爾躲不了多久的。如果必要，我會追著她進入英靈殿！\n\n先退下，&lt;class&gt;。在需要你的時候，我會召你回來。", rewards = "女妖之王的祝福希瓦娜斯的倒刺箭咒心風帽瘟疫使者的面具黑暗遊俠罩盔凋零者的腦籠您能選擇下列奬勵中的一個：\n\n被遺忘者之力\n\n您還會收到：\n\n靈魂牢籠碎片"}
MultiLanguageQuestData['tw'][38888] = {title = "高嶺牛頭人", objective = "在高嶺向羅諾斯‧鐵角回報。", description = "你為我帶來了一些值得一看的岩石，<name>。如果你有興趣的話，我有個特別的任務要給你。\n\n我聽說高嶺上有群牛頭人，他們以高超的採礦技術而聞名。我不知道他們是不是像你我一樣有才華，不過他們開採脈石的時間比我們還久。\n\n去拜訪他們，學習他們的長處。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38889] = {title = "收養小熊", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n灰喉幼熊"}
MultiLanguageQuestData['tw'][38901] = {title = "魔匠們", objective = "到蘇拉瑪爾向魔匠娜麗莎回報。", description = "你知道一些處理魔岩的訣竅，<小伙子/小姑娘>，但是最好去比我更了解這種東西的人那邊進修。\n\n伊利達瑞一向是惡魔事物的專家，我聽說有幾個礦工在蘇拉瑪爾的惡魔附近開店。\n\n去拜訪他們，學習他們的長處。", progress = nil, completion = "你要開採魔岩？\n\n你真的做好萬全準備了嗎？\n\n你願意付出所需的代價嗎？\n\n很好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38904] = {title = "返回破碎海岸", objective = "乘著薩魯法爾的另一隻坐騎前往破碎海岸，與他並肩作戰，重返榮耀。", description = "別擔心，<name>。我雖然憤怒，但也不會自尋死路。\n\n我們會從空中偵察，尋找最理想的進攻點。惡魔仍然陶醉在自己的勝利之中，不過我們很快就會讓它們清醒過來！\n\n你搭另一隻坐騎，一起飛往破碎海岸。在那裡，我們將為死者爭取應有的榮耀。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38907] = {title = "神錘守護者", objective = "在高嶺的雷霆圖騰和梅拉‧高嶺見面。", description = "高嶺部族打算向你的勢力宣誓效忠。我們知道與燃燒軍團開戰的時刻已經來臨。\n\n然而，我們內部出現叛徒，現在必須先向你求助。\n\n邪惡的卓格巴從我們手中偷走至高的聖物卡茲格羅斯之錘。\n\n我們需要你幫忙取回聖物。", progress = nil, completion = "我很清楚你在尋找創世之柱，但很遺憾地，我必須告訴你，那是我們今天失去的諸多事物之一。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38909] = {title = "前往高地", objective = "帶潔爾‧河鬃到雷霆圖騰。", description = "達古爾會對河鬃發動攻擊並不意外。那是他們用以提供糧食的農場和牧場所在地。\n\n麻煩你，幫助潔爾前往雷霆圖騰。如果運氣夠好，梅拉會派兵對這個地區增援。\n\n我們會在這裡集結倖存者，並盡快趕上。", progress = nil, completion = "河彎被…毀了？達古爾那個噁心的怪物！除非親眼看到他死去，否則我絕對不會停手。\n\n但光靠我們現有的軍隊，恐怕無法辦到。\n\n我們需要其他部族的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38910] = {title = "大鵬對老鷹", objective = "拯救7隻被俘虜的巨鷹。", description = "勾爪女王教導她的女巫如何詛咒我們摰愛的巨鷹，讓牠們變成不斷突擊山谷的邪惡大鵬。\n\n一旦詛咒生效，就再也無法破除。\n\n我們會飛向天空並對抗這些大鵬，但地面就需要你來處理。\n\n往北穿過暗羽谷地，並釋放你找到的任何巨鷹。\n\n你每救出一隻巨鷹，我們就能少殺一隻大鵬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38911] = {title = "河鬃部族", objective = "到地母之賜找潔爾‧河鬃。", description = "想要清楚說明這裡發生的事，我得花更多時間。但簡單來說，在攻擊發生時我們的氏族就分散了，只能任由卡茲格羅斯之錘落入野蠻的卓格巴手中。\n\n而直到現在，卓格巴也還在侵略河鬃部族，但我身邊的勇戰者太少，派去協助也是只是徒然。\n\n我們需要的是一位英雄。拜託你，前往地母之賜，並盡可能提供協助。", progress = nil, completion = "梅拉還能夠提供協助？真是個好孩子。\n\n歡迎你，外來者。我是潔爾‧河鬃，河鬃部族的酋長。我們真的非常需要你的幫忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38912] = {title = "血圖騰部族", objective = "在絕崖與奧肯‧鐵牛碰面。", description = "血圖騰部族由托洛卡所領導，他是一位暴躁卻十分可靠的牛頭人酋長。他對外來者一向保持高度警戒，但我相信你已經見過他們氏族中的密使，奧肯‧鐵牛，你在河彎救過他。\n\n運用這一絲關係，你就有可能把血圖騰的人帶回窪地。如果我們想要擊敗卓格巴並取得卡茲格羅斯之錘，高嶺就少不了他們。小心行事，<name>。", progress = nil, completion = "外來者，沒幾個人能夠越過高嶺，安然進入這些森林，但你就是其中之一。在我為你擔保之後，托洛卡已經對血圖騰部族下了禁殺令。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38913] = {title = "天角部族", objective = "在天角村與拉桑‧天角會面。", description = "天角部族的人民是世界知名的探路者和獵人。\n\n他們相當驕傲，但應該聽得進道理。\n\n如果路上不太安全的話，你可以去找高嶺的任何一個飛行管理員帶你飛過去。\n\n$p，請去找他們的領導者拉桑，提醒他：團結一心，高嶺永存！", progress = nil, completion = "哈哈！這又是什麼小東西？你是來和我們打架的？還是要加入我們？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38915] = {title = "雪盲台地之戰", objective = "前往雪盲台地。", description = "你來得正好。我們在雪盲台地的部隊回報地底之王在地面活動。\n\n更重要的是，他身邊沒幾個護衛，而且還帶著神錘。感謝你的努力，我們可以和他們交戰了。\n\n到雪盲台地與我們一同對抗達古爾吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38916] = {title = "高嶺的秘密", objective = "到雷霆圖騰的南方山崖與靈行者黯角會合。", description = "梅拉的父親，烏蘭，是我們前一任牛頭人酋長。他試圖阻止地底之王取得卡茲格羅斯之錘，結果被殺了。\n\n我看著梅拉從小長大，可以告訴你，她確實具備足夠的勇氣和力量，有資格繼任牛頭人酋長。\n\n梅拉只需要我們幫助她更瞭解自己。\n\n你能不能在南方峭壁的城市入口處和我們會面？有一個儀式可能幫得上忙，但我們需要你的協助，才能活下來。", progress = nil, completion = "啊，感謝你前來。梅拉要是固執起來，一點也不輸她父親。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38922] = {title = "小毛", objective = "在燃皮灌木林與小毛交談。", description = "陌生人，我懇求你！我原本愛好和平的族人，現在充斥著永不止息的憤怒。\n\n我和姪兒試圖離開，卻引來酋長的不滿。族人把他從我手中奪走。要不是我逃出來，他們會把我殺死。\n\n他被困在村落中，我怕他的下場更慘。\n\n偉大的<class>，請救救他。我年老體衰，無法親自去救他。", progress = nil, completion = "叔叔？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38923] = {title = "艾斯蘭制霸", objective = "在艾斯蘭的事件地點擊敗敵對陣營，在敵方基地內殺死其領袖。", description = "聯盟拒絕放棄艾斯蘭。在聯盟掠奪古代巨魔帝國的力量為己用的時候，讓他們瞭解部落絕對不會袖手旁觀。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一箱魔化戰場物資榮譽獎章"}
MultiLanguageQuestData['tw'][38924] = {title = "维护霸权", objective = "在阿什兰的事件地点击败联盟，并击杀大元帅泰布雷德。", description = "联盟拒绝从阿什兰撤退。告诉他们，部落绝不会袖手旁观，眼看他们掠夺古代食人魔帝国的力量为他们所用的。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][38925] = {title = "艾斯蘭制霸", objective = "在艾斯蘭的事件地點擊敗敵對陣營，在敵方基地內殺死其領袖。", description = "如同我們擔心的，部落正在想辦法擄掠這這座島來鞏固他們的防線。去讓他們瞧瞧，聯盟不會容忍這樣的侵略行為。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一箱魔化戰場物資榮譽獎章"}
MultiLanguageQuestData['tw'][38926] = {title = "繼續制霸", objective = "在艾斯蘭的所有事件地點擊敗部落勢力，並殺死高階督軍沃拉斯。", description = "如同我們擔心的，部落正在想辦法擄掠這這座島來鞏固他們的防線。去讓他們瞧瞧，聯盟不會容忍這樣的侵略行為。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][38927] = {title = "身經百戰", objective = "贏得3場積分戰場。", description = "在戰場上打敗你的敵人，你就會得到獎賞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇士的保險箱"}
MultiLanguageQuestData['tw'][38929] = {title = "身經百戰", objective = "贏得3場積分戰場。", description = "在戰場上打敗你的敵人，你就會得到獎賞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇士的保險箱"}
MultiLanguageQuestData['tw'][38932] = {title = "裝備藍圖：艙底水泵", objective = "把藍圖帶回要塞船塢，拿給船艦設備專家。", description = "看來是某種海上裝備的藍圖。我們應該把它帶回船塢，看看有誰能瞭解其中玄機。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38933] = {title = "後勤工作", objective = "與格雷森‧破影者領主交談。", description = "我想該是時候…讓破碎群島的燃燒軍團…重新見識我們的厲害了。\n\n格雷森‧破影者領主自願帶領我軍的地面作戰行動，建議你立刻與他談談，大領主。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38934] = {title = "希拉斯的秘密寶物", objective = "找到希拉斯的秘密寶物。", description = "暗月財寶現蹤跡，\n敬告慎者莫追尋。\n欲知謎題何處解，\n玄機就在紙背後。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n希拉斯的秘密寶物"}
MultiLanguageQuestData['tw'][38935] = {title = "他的名字是…風暴烈酒", objective = "到四風峽的雷足牧地找老陳‧風暴烈酒。", description = "流言在這塊土地上四處流竄，描述一位不尋常的熊貓人武僧，他的力量和酒量一樣強大。\n\n他和姪女一塊旅行，後者的大嘴巴老是讓他們陷入一連串的麻煩。\n\n根據本地人的說法，他們兩人朝四風峽去了。你應該和他見個面！只不過…要小心那記右鉤拳。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38936] = {title = "通往崑萊的道路", objective = "穿越朦朧天梯到濱南村。", description = "博學行者阿洲已經傳來消息，你的幾位勇士在翠玉林的衝突戰活了下來，但轉到崑萊峰去療傷了。\n\n他們急需你的協助，才有辦法活下來！\n\n想要抵達崑萊峰，必須前往四風峽並在東北方邊界，也就是朦朧天梯底端，找到大道咕嚕摩。\n\n他們可以引導你走完後續的路程。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38939] = {title = "襲擊斯寇亞胥", objective = "<insert>", description = "<insert>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][38944] = {title = "適「縫」其會", objective = "取得10份夏多雷絲綢。你能夠在破碎群島的人形生物身上找到夏多雷絲綢，或與其他冒險者交易，或前往拍賣場購買。", description = "每當達拉然飛到一片新的大陸，我就會迫不及待想知道，我們可以從下面找到什麼樣的織品和布料。\n\n是注入魔法的絲線？還是出自惡魔之手的事物？\n\n呃，但願不會又是毛皮。\n\n你是冒險者…也是裁縫師。前往下面的大陸，看看你能找到什麼！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n軍團裁縫\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38945] = {title = "輕而易舉…吧？", objective = "在塔妮穗亞的工作桌上製作手工絲織長袍。你可以在裁縫圖樣清單中找到圖樣，並且在她店裡找到必要的材料。", description = "我有很多絲綢圖樣，可以讓這塊布料派上用場。\n\n幫我準備一些材料，<name>。我們要好好利用這塊布料，幫你製作新的長袍。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n絲織技巧簡介\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38946] = {title = "詢問當地人", objective = "在艾蘇納找到裁縫。", description = "不管這塊布料是誰織的，絕對不會只用來製作皮帶和肩墊。一定有什麼辦法把線縫進這種材料裡。\n\n去艾蘇納找裁縫師吧。如果真的想做裁縫，那就少不了針線活。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38947] = {title = "符文腸線", objective = "取得3條符文腸線。", description = "讓我猜猜…穿線遇到麻煩了？嗯嗯。\n跟我懷疑的一樣。我的族人編織奢華的絲綢，不過每種絲綢適合的縫線類型各有不同。\n\n夏多雷絲綢在編織時，會混入一點地脈能量。你需要一些確定可以與這片土地的地脈能量共存的東西。\n\n我指的就是梟羽獸，我的好朋友！牠們有你需要的東西。你可以在洛席恩廢墟中找到牠們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38948] = {title = "難關", objective = "取得污損的絲質長袍和一對盤恨裹腕。", description = "當我還在蘇拉瑪爾的裁縫公會的時候，通常會保留一些圖樣，從中獲得啟發。\n\n可惜的是，我後來遭遇一連串的不幸，丟失了我的圖樣，我覺得很丟臉。\n\n不過西方潟湖中的納迦巫女擁有巧奪天工的裹腕。還有，只要你有辦法搶來的話，北方的夜落精靈穿的是我們能用的長袍…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38949] = {title = "你會裁縫嗎", objective = "在林德拉斯的工作檯上製作一件符線絲織長袍和一對符線絲織護腕。你可以在你的裁縫圖樣清單中找到這些圖樣。", description = "非常好，我想我們已經可以開始了。\n\n<林德拉斯偷看一眼你那強大的武器，臉上浮現渴望的表情，隨即又收斂情緒，繼續動作。>\n\n讓我們把材料準備好，製作你應得的長袍和護腕！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n新手絲織技巧\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38950] = {title = "遊蕩的裁縫師", objective = "在達拉然與拉菈‧亮織交談，並要求她召喚林德拉斯。", description = "<name>，我能請你幫個忙嗎？\n\n我最近無處可去，也沒有親朋好友，我在想你能不能帶我參觀一下浮空城？我必須承認，我對那個地方非常好奇。我也聽到有關裁縫店的消息。\n\n我沒辦法自己去到那裡，不過像這樣的魔法之都，一定有人可以召喚我。\n\n<林德拉斯既期待又擔心地看著你。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38951] = {title = "獨缺縫衣針", objective = "取得150根妖精尖刺。", description = "這間店幾乎什麼東西都不缺。只可惜縫衣針的品質不夠好。\n\n我知道到哪裡取得更好的縫衣針。維爾薩拉的妖精身上覆滿尖刺，恰好就是我們所需的最好縫衣針。\n\n我不想那麼挑剔，不過那種縫衣針真的非常好用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38952] = {title = "精準無比", objective = "將妖精尖刺交給達拉然的蒂芬妮‧卡地亞。", description = "這些針十分尖銳，不過仔細一看，有些針不夠筆直，有些針的側邊還有小刺。看看這一支…上面還有90度的折角！我不打算使用這些品質太差的針。\n\n珠寶設計商店的蒂芬妮‧卡地亞的眼睛很好，擅長處理這種事情。請將這些針交給她，她會把它們弄直。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38953] = {title = "更上層樓", objective = "在塔妮穗亞的工作桌上製作鑲邊絲織長袍。你需要在她店裡找到材料。", description = "你已經學會護腕、腰帶、肩胄還有長袍的圖樣。可惜你的手法浪費太多材料…你得學習更好的方法。\n\n這時候我們的針就派上用場了。\n\n來吧，我會教你如何改進製作這些圖樣的過程。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n中級絲織技巧\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38954] = {title = "林德拉斯在哪裡？", objective = "找到林德拉斯。", description = "看起來好怪。林德拉斯匆匆忙忙跑來，然後又匆匆忙忙跑走。臉上的表情非常奇怪。\n\n也許我們應該跟過去看看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38955] = {title = "縫好縫滿", objective = "製作一個絲織包。你得在達拉然的裁縫店裡找到需要的材料。", description = "你的裁縫技術真的讓人印象深刻，雖然我沒把圖樣帶在身邊，不過我的確記得一些圖樣。其中一張圖樣是一種簡易包包。\n\n聽我的指示，<name>。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n絲織背袋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38956] = {title = "林德拉斯又跑到哪裡去了？", objective = "在達拉然找到林德拉斯。", description = "喔，親愛的。\n\n他不久前才向你保證他不會亂跑，現在又故態復萌！\n\n我不得不開始認為，這個林德拉斯實在不知好歹，完全不符合我的品味。\n\n請快點找到他，別讓他製造出更多麻煩。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38957] = {title = "靈光一閃", objective = "取得6條符文長褲。", description = "我希望有更多圖樣可以分享，不過我的店沒了，筆記本也跟著沒了。我們必須自己想出一些圖樣。\n\n我一直在想斯鐸海姆維酷人身上穿的皮革馬褲。比起我們現有的商品，它們看起來厚重許多，不過它們的裝飾性符文相當引人注目。\n\n如果我能拿到幾件，說不定可以將符文重印在更…華麗的服飾上。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n絲織窄褲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38958] = {title = "顏色正確", objective = "取得10瓶黑爾烏賊墨液。", description = "<name>，有時間的話就幫我個忙。\n\n我想重製前一段時間看到的鞋子圖樣，不過一直搞不定染料的色彩。我們的黑色染料顏色太深，藍色染料顏色太亮，混合之後感覺不太對勁。\n\n我想要的色彩比較接近墨藍。如果在你旅行途中，發現這種顏色的染料，可以幫我個忙，帶一些給我嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n絲織軟靴\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38959] = {title = "來不及拿", objective = "前往你在艾蘇納第一次遇到林德拉斯的地方，取得他的裁縫剪刀、度量工具箱和穿線針。", description = "我真的很想幫你提升裁縫技術，不過既沒有圖樣，也沒有材料，除了把我還記得的教給你，實在沒有其他能做的了。\n\n要是我記的沒錯，你只需要再找張製作手套跟兜帽的好圖樣。\n\n首先，我需要你去我們第一次見面的地方拿一些東西。我要這些東西…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38960] = {title = "熊皮襯裡", objective = "收集15張熊皮。", description = "既然你要去艾蘇納，何不替我們的工作項目取些襯裡回來？\n\n艾蘇納熊隻的毛皮柔軟又耐用，名聞遐邇。\n\n在洛席恩的樹林各處獵捕牠們，帶回牠們的毛皮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38961] = {title = "艾薩拉之眼：邪惡夜落", objective = "前往艾薩拉之眼，擊倒艾薩拉之怒並取回風暴之心。", description = "要製作手套的話，我們需要一樣特殊物品。要拿到那樣東西可不簡單，<name>。\n\n聽說艾蘇納的納迦試圖將某個可怕的生物召喚到這個世界。\n\n那個生物的心臟具有豐沛能量，只要我們把這股能量傳輸到手套裡，手套就會充滿力量。\n\n我需要…我是說，我們需要那顆心臟，才能製作出配得上你這種英雄的手套。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n絲織手套\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38962] = {title = "蘇拉瑪爾之路", objective = "持續協助蘇拉瑪爾的夜落精靈，找出方法安全地進入蘇拉瑪爾，不引起精靈懷疑。", description = "我記得林德拉斯提過，在蘇拉瑪爾城中有個裁縫師公會，或許他們知道該如何運用這種新布料。\n\n但很不幸地，我聽說他們已向惡魔效忠。任何反抗惡魔的人，都格殺勿論。\n\n你得找個能安全進出城市的方法，我們才能繼續研究。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n上古法力"}
MultiLanguageQuestData['tw'][38963] = {title = "最後一課？", objective = "在塔妮穗亞的工作桌上製作手工絲織兜帽。你需要在她店裡找到材料。", description = "我們現在拿到所需的一切了，開始製作兜帽吧。\n\n完成之後，我們就開始製作手套。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n絲織兜帽\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38964] = {title = "林德拉斯現在人在哪裡？", objective = "前往對街的鍊金商店。", description = "林德拉斯應該還沒有走遠。畢竟，我們是漂浮在海上幾千英尺的高空。\n\n我今天早上聽到對面的鍊金店外吵吵鬧鬧的。希望不是林德拉斯又在惹事生非。\n\n可以請你去確認一下嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38965] = {title = "紫羅蘭堡之襲：進入堡壘", objective = "進入紫羅蘭堡，瞭解林德拉斯的狀況。", description = "林德拉斯被關入紫羅蘭堡後，你覺得自己應該對他負責，並追查出他所作所為的背後真相。\n\n如果能夠跟他談談，說不定可以想辦法把他弄出紫羅蘭堡，交予你監管。\n\n進入紫羅蘭堡，瞭解林德拉斯的狀況。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38966] = {title = "神秘的絲織技巧", objective = "製作一些精工絲織護腕。\n\n你得在達拉然的裁縫店和鐵匠舖裡找到需要的材料。", description = "好了，哀悼完了！讓我們看看他的東西。\n\n<塔妮穗亞花一點時間匆匆翻閱林德拉斯的日記。結果一臉震驚。>\n\n我們的朋友一直沒對我們說實話。看看這個！他教給我們的每一個圖樣都有改進的空間。\n\n先從簡單的開始，像是護腕。大部分的材料我都有，不過你必須跑一趟鍛造舖，找艾拉得‧席彌德拿一些硫磺粉末。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n進階絲織技巧\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38967] = {title = "夜裔人脈", objective = "在蘇拉瑪爾與織能師泰塔洛交談。", description = "現在你找到偽裝自己的方法了，你應該去蘇拉瑪爾城，試著找出這個裁縫師公會。\n\n祝你好運，<name>，別讓他們發現了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38968] = {title = "忠誠之證", objective = "在蘇拉瑪爾殺死25個凋萎者。", description = "<泰塔洛傾聽你述說林德拉斯的故事。>\n\n原來如此。你聽起來…似乎很同情那個可憐人。\n\n夜落精靈都是騙子和小偷，毫無例外，林德拉斯也是其中之一。\n\n竟然對那種…東西存有敬意或同情心，我不會容忍這種學生。此外，你注意過他們在墜入墮落深淵的時候成了什麼模樣嗎？\n\n如果你想贏得我的好感，就讓你的手沾滿凋萎者的血，否則不要回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38969] = {title = "絲織大師", objective = "向織能師米斯洛岡購買夏多雷人體模型，然後製作一整套絲織護甲，並穿戴在人體模型上。", description = "泰塔洛忙著將凋萎者滅族的時候，就由我來負責訓練比較乏味的部分。\n\n我們必須先瞭解你本身的才華。\n\n為我製作一整套絲織護甲。織能師米斯洛岡能夠提供適當的人體模型，方便你展示護甲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38970] = {title = "皇后之賜織布機", objective = "使用織能師大廳的傳送水晶，然後與織能師雅賽娜交談。", description = "想要獲得強大的力量，就必須付出代價。就算是最出色的裁縫師，其絲織技藝也一定有所侷限。為了進一步改良圖樣，就必須有所取捨。\n\n<name>，你已經準備好學習如何處理灌魔絲織。\n\n使用位在我身後的傳送水晶，與我們公會的領導者雅賽娜交談。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n灌魔絲織簡介\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38971] = {title = "異域紡織品", objective = "取得魔能銘刻罩氅。", description = "我以我的生命和事業為賭注來到這裡，裁縫師。\n\n我一直對惡魔布料很好奇，但我卻無法透過正常管道取得任何惡魔布料。\n\n我只是一定要親眼看看這種布料。\n\n我不想破壞雅賽娜與惡魔的協議，但是你可以 - 你可以在不引起公會注意的情況下攻擊惡魔。\n\n我對於惡魔的特殊長袍特別感興趣。帶一片碎布給我，我就教你我會的東西。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n灌魔絲織手套\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38974] = {title = "英靈殿：正確的問題", objective = "擊敗英靈殿的海姆達爾，取回他的纏腰。", description = "有人可能會問織能師為什麼要站在維酷人的屍體上。這種問題只會造成麻煩。\n\n應該換個說法，詢問我們能從死者身上學到什麼。像這樣的問題才能讓對話延續下去。\n\n我想你來這裡的用意，是想要我教你灌魔絲織束褲的圖樣，對吧？\n\n如果這是你的目的，那麼我需要死者身上的一些東西。就位在偉大守衛海姆達爾所居住的英靈殿。\n\n把他的纏腰帶來給我，我就教你圖樣。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n灌魔絲織窄褲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38975] = {title = "給我靈感！", objective = "站在織能師米斯洛岡身旁，製作棕色亞麻長袍、白色毛絨裙、簡單的黑裙子、霜織長袍和靈魂癒療長袍。\n\n如果有不會的圖樣，你可以向各大城市的裁縫訓練師學習。", description = "我的志業就是研究怎麼製作長袍和裙子。你可以留著你的手套、皮帶和披風。什麼都比不上一件好長袍。\n\n我會與你分享我的灌魔絲織長袍圖樣，只要你教我一些你在鑽研裁縫技術的過程中學到的長袍和裙子圖樣。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n灌魔絲織長袍\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][38989] = {title = "有何指示，将军？", objective = "前往塔纳安丛林的塔纳安计划图。", description = "将军，你的部队已集结在塔纳安丛林，正等候你的指示。到塔纳安计划图跟前去，下达你的指令。\n\n为了部落！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][38990] = {title = "冰冠城塞的呼喚", objective = "使用死亡之門前往冰冠城塞，取得墮落王子之刃。", description = "<某種強大的存在再次碰觸了你的思緒。>\n\n我已經命令你的弟兄前往冰冠城塞，為接下來的戰鬥做準備，但我有更重要的使命要交給你。你，<name>，將成為我們的復仇之手！\n\n使用死亡之門返回冰冠城塞，我將揭露你所要扮演的角色。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][38996] = {title = "將軍，你的命令？", objective = "回到塔南森林的雄獅哨站和伊芮爾交談。", description = "伊芮爾主教從塔南森林的雄獅堡送來消息，你的部隊已經在等候新的命令。\n\n為了聯盟！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39000] = {title = "沒借書證也無所謂", objective = "從地獄火堡壘中的首領身上收集33本混沌秘典。", description = "如果從歷史可以看出任何徵兆，古爾丹一定在訓練一整批新世代的術士，準備對我們大舉進攻。但只要我們的動作夠快，就可以遏止這股浪潮，讓我們有機會從容應付。\n\n當你和其他英雄冒險踏入地獄火堡壘深處時，從古爾丹的手下奪取混沌秘典。\n\n這些書籍十分危險，任何一本都不得翻閱，就算是圖片也不可以看。\n\n<卡德加聳聳肩。>\n\n「尤其」不要看圖片。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39001] = {title = "前往法兰伦！", objective = "使用你的船坞完成“前往法兰伦！”的海军行动，取得法兰伦珍珠。", description = "<name>，你听说过法兰伦吗？大法师瓦格斯一直在提到那里——美丽的田野和森林，装点着天然形成的水晶阵列，让那里成为了德拉诺的魔法枢纽。想到达那里几乎是不可能的。那附近的大海上经常会出现无法预测的魔法风暴。\n\n为了完成你的戒指，我们需要一件法兰伦的魔法神器。你需要组成一支高水平的船队，才能安全地到达那里，并活着回来。仔细挑选你的队员，去为我取回那件神器吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39002] = {title = "深海食人魔", objective = "使用你的船坞完成“深海食人魔”海军行动，并取回浸水的食人魔解码器。", description = "高里亚食人魔帝国在鼎盛时期曾有一支海军舰队，规模虽小但威力非常强大，知道这一点你也许会惊讶吧。不过如果告诉你，这支舰队中有不少大战舰已经沉没了，你可能不会吃惊。毕竟那些船是石头做的。\n\n我找到了一张古老的海图，上面标注着“皇帝之足”最后一次出现的位置，我所需要的一件价值连城的神器也和它一起消失在了大海里。一台食人魔解码器。\n\n没错！为了取回它，你需要一艘潜水艇和一批船员。这是非常危险的任务，正因如此，我才要找你来完成。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39003] = {title = "焚書毀卷", objective = "將古爾丹的混沌藏書帶給贊格拉的寇達娜，確保書籍全面銷毀。", description = "<name>，我們得毀掉這些書籍。裡面還有好幾本書直接把受難的靈魂束縛在書頁之中，光是燒掉還不夠。寇達娜知道怎麼做。\n\n把這些書帶到我在贊格拉的法師塔，交給寇達娜。事情辦完了就回來告訴我一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39004] = {title = "黑暗的化身", objective = "在地獄火堡壘中追擊與擊敗古爾丹。", description = "現在我們還有一個最後的工作，<name>。我們必須打倒古爾丹，破壞他對這個世界的邪惡計劃。\n\n我已經沒有什麼可以送你，能幫的我都幫了。\n\n來吧。等你和你的盟友都準備好，我們就朝地獄火堡壘進軍…結束這一切。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39011] = {title = "玄鴉入侵", objective = "在布瑞登溪殺死7個玄鴉殺手。", description = "這個地區原本既和平又繁榮。但有一天壞事開始發生：奇怪的疾病、作物離奇壞死…諸如此類的怪事。現在鬼魂從河對岸的城堡攻擊我們、不死刺客殺害我們的漁夫、切斷村落的糧食補給。\n\n我們是最後一個在城堡附近定居的家庭，但我們不敢撤退：對漁夫來說，想要把貨物送入城鎮，這條河是最好的路線。拜託你，你能不能對抗那些不死生物？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39015] = {title = "躁躁", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n躁躁之鍊"}
MultiLanguageQuestData['tw'][39018] = {title = "大法師的召喚", objective = "在贊格拉的卡德加之塔與大法師卡德加交談。", description = "大法師卡德加有件急事要請你協助。他非常擔心這個世界可能會對艾澤拉斯造成更多威脅，因此他需要你的協助以進一步追查。請前往塔拉多爾東邊的贊格拉沼澤，到卡德加之塔和他會面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39019] = {title = "大法師的召喚", objective = "在贊格拉的卡德加之塔與大法師卡德加交談。", description = "大法師卡德加想出對抗暗影議會的下一步行動。請前往卡德加之塔中和他會面，就在塔拉多爾東邊的贊格拉沼澤。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39020] = {title = "燃烧的时光之路", objective = "完成5个时空漫游地下城。", description = "燃烧的星星照耀着大地，使土地布满焦痕，四处都是干枯的景象。那是一颗残忍而恶毒的星星。在它的影响持续期间，新的道路将被打开，通往遥远的空间与时间。没有哪位贤者真正了解这一预兆的涵义，但英勇的行为总会得到幸运的眷顾。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鋼鐵艦隊藏寶箱宿命徽印"}
MultiLanguageQuestData['tw'][39021] = {title = "冰冻的时光之路", objective = "完成5个时空漫游地下城。", description = "冰冷的星星用它冰冷的光芒照耀着大地，仿佛连灵魂都退缩到了暗影之中。这颗星星与天空中其他的星星完全不同，它会吸取热量与生命。在它的影响持续期间，新的道路将被打开，通往遥远的空间与时间。没有哪位贤者真正了解这一预兆的涵义，但英勇的行为总会得到幸运的眷顾。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鋼鐵艦隊藏寶箱宿命徽印"}
MultiLanguageQuestData['tw'][39022] = {title = "大法師的召喚", objective = "在贊格拉的卡德加之塔與大法師卡德加交談。", description = "大法師卡德加想出對抗暗影議會的下一步行動。請前往卡德加之塔中和他會面，就在塔拉多爾東邊的贊格拉沼澤。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39023] = {title = "大法師的召喚", objective = "在贊格拉的卡德加之塔與大法師卡德加交談。大法師卡德加想出了對抗暗影議會的下一步行動。請前往塔拉多爾東邊的贊格拉沼澤，到卡德加之塔中和他會面。\n\n這不會花太久時間。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "大法師卡德加想出了對抗暗影議會的下一步行動。請前往塔拉多爾東邊的贊格拉沼澤，到卡德加之塔中和他會面。\n\n這不會花太久時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39024] = {title = "大法師的召喚", objective = "在贊格拉的卡德加之塔與大法師卡德加交談。大法師卡德加想出了對抗暗影議會的下一步行動。請前往塔拉多爾東邊的贊格拉沼澤，到卡德加之塔中和他會面。\n\n這不會花太久時間。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "大法師卡德加想出了對抗暗影議會的下一步行動。請前往塔拉多爾東邊的贊格拉沼澤，到卡德加之塔中和他會面。\n\n這不會花太久時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39025] = {title = "地底之王的魔掌", objective = "拯救潔爾‧河鬃、勇戰者歐洛和奧肯‧鐵牛。", description = "要說我們哪一點運氣好，就是達古爾那傢伙不知道要如何使用神錘的力量。\n\n他一直認為那是武器，而非用來創造的工具。\n\n即便如此，他還是把我們的族人困在從地面召喚出來的石掌中。我們試過了，武器對這種魔法無效。\n\n你或許有足夠的力量破壞這些石掌，你願意幫忙嗎？", progress = nil, completion = "上次看到數量龐大的卓格巴在地面活動，已經不知道是多久以前的事了。\n\n他們之前只是我們拿來編故事嚇小孩子用的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39026] = {title = "卓格巴", objective = "在河彎殺死8個卓格巴。", description = "對達古爾來說，光是摧毀這座村莊還不夠。他派遣了啃石者來掠奪剩下的東西。\n\n勇士，請向人民證明你就是我預言中的英雄吧。\n\n殺死這些啃石者，直到動搖他們的信心為止。", progress = nil, completion = "你的戰鬥技巧讓我印象深刻。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39027] = {title = "達古爾與神錘", objective = "對抗『地底之王』達古爾。", description = "雖然我們總是警告小孩，別跟著卓格巴走進洞穴，現在卻必須這麼做。\n\n有幾個勇戰者已經先進去找達古爾了。\n\n來吧，和我們一同奮戰，奪回卡茲格羅斯之錘。", progress = nil, completion = "歐洛和其他人呢？他們也逃出來了嗎？\n\n真是慘不忍睹。今天有太多善良的勇戰者倒下了。\n\n現在情勢很明顯，如果我們想要取回神錘，就需要高嶺部族的每一分力量。", rewards = "雪盲護腕卓格縫製裹腕白浪腕甲雷霆之巔護腕您能選擇下列奬勵中的一個：\n\n堅定勇戰者戒環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39029] = {title = "保衛神殿", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][39033] = {title = "突袭时刻", objective = "在盛产埃匹希斯的地区完成5项目标。", description = "星辰的方位使散布在德拉诺各处的远古文物——埃匹希斯水晶——产生了非同寻常的振动。有人发誓说，这些水晶会在无人观察的时候在夜空下自行增殖，但没有人亲眼目睹过这样的现象。不管原因到底是什么，如果你现在去寻找水晶的话，收获一定会比之前更多。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料頂尖水晶要塞資源"}
MultiLanguageQuestData['tw'][39034] = {title = "战争的使者", objective = "完成4次史诗难度的地下城。", description = "当战争使者的标记在夜空中闪烁时，星辰将会强化已有的羁绊，并会创建新的联系。想要获取友谊并不容易，你需要通过自己的行为来证明忠诚，但在这样的日子中，信任会变得更容易创建。冲进地穴与要塞的深处，证明你的价值。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n鋼鐵艦隊藏寶箱"}
