MultiLanguageQuestData['tw'][39047] = {title = "伊利達瑞的呼喚", objective = "在卡薩斯平臺與『受難者』奧翠司交談。", description = "<name>，奧翠司請求你立刻在卡薩斯平臺與他碰面。\n\n<珂娃絲靠近對你低語，語氣急切。>\n\n你一定要快。到處都有燃燒軍團的耳目。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39049] = {title = "獎勵就在眼前", objective = "殺死審判官邪怨，取得他的力量。", description = "這個惡魔毫無用處。我一直用奪魂鐮拷問它，但它還是守口如瓶。那我們就來看看它能撐多久。\n\n不過我有另一個主意…\n\n前面有個惡魔審判官。他是可怕的魔化施法者，能透過飄浮之眼窺探世界，特別擅長黑暗契約。如果你能竊取他的力量，捷斯‧暗織者就能把力量運用在儀式中，用來監視燃燒軍團。\n\n而且更好的是，你還可以撕裂它冒煙的屍體，獲得它的力量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n扭曲之心"}
MultiLanguageQuestData['tw'][39050] = {title = "偵察蛛后", objective = "完成儀式以監視軍團的領袖。", description = "我們可以使用一些精華來完成儀式。然後就能監視燃燒軍團的領袖，看看它們到底在計畫什麼。\n\n使用虛空法陣並完成儀式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39051] = {title = "不擇手段", objective = "進入紫羅蘭堡並審問『毀滅者』塔爾達茲，以得知叛徒瓦瑞迪斯的下落。", description = "我們要想辦法查明瓦瑞迪斯躲在哪裡 - 唯一的辦法就是進到監獄裡。\n\n該做什麼就去做吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39054] = {title = "造船", objective = "學習藍圖並銷毀證據。", description = "我們要動手造船，需要的第一樣東西就是藍圖。在你的協助下，我在逃出鋼鐵碼頭之前，從裡面拿了一些最棒的設計。\n\n<class>，為了確保它們不會重回鋼鐵部落之手，請你記住這些藍圖，然後將其銷毀。完成之後告訴我一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39055] = {title = "船艦的建造", objective = "和亞納斯交談，開始進行運輸艦的建造工作。完成之後，將它加進船艦收藏中。", description = "現在我們有藍圖了，是時候開始建造我們的第一艘船了。就從運輸艦開始吧！當你準備開始的時候，和我說一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39056] = {title = "海軍指揮官", objective = "到船塢找莫瑞克‧方達，並完成一個海軍任務。", description = "我們的船塢在短短的時間內便獲得了很大的進展，<name>。現在是我們執行第一個海軍任務，掌控德拉諾海域的時候了！\n\n我需要找個視野遼闊的制高點，才好規劃海上任務。到船塢入口那邊找我，準備開始進行任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39057] = {title = "稱霸海上", objective = "將船塢升到第2級。", description = "古爾丹一點時間都沒浪費，他的暗影議會手下已經滲透到鋼鐵部落的各個層級，連一度只效忠葛羅瑪許的海軍艦隊現在也聽他號令。我們要是想反擊，光靠幾艘運輸艦是不夠的，必須要有戰力完整的海軍艦隊才行。\n\n我們需要借重你的專長，指揮官。升級你的造船廠，建立一支海軍艦隊，稱霸海上！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39058] = {title = "德拉諾的小動物", objective = "在寵物對戰中擊敗『收藏家』厄莉絲。", description = "我喜歡收集寵物，而且還在德拉諾這裡收集到了幾隻罕見的寵物。想不想跟我打一場啊？要是你能打敗我的隊伍，相信我們應該都能學到一些新把戲。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n旅行者的寵物用品無瑕的戰鬥訓練石"}
MultiLanguageQuestData['tw'][39059] = {title = "捉女妖記", objective = "在黯狼守望與吉恩‧葛雷邁恩會面。", description = "那名談吐怪異的維酷人說我或許能在這找到你。我有來自葛雷邁恩的指令。他似乎有希瓦娜斯下落的線索。\n\n他在山腳附近紮了營。不過我們遇到一些麻煩。看來部落可能已向我們的位置迫近。\n\n我們會需要你的協助。你可以使用我的獅鷲獸，準備好動身就跟我說一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39060] = {title = "易燃傳染源", objective = "燒毀黯狼守望附近的被遺忘者荒疫儲物堆。", description = "我們確實有關於希瓦娜斯的線索。雖然我很想親手宰了女妖之王，但黯狼守望的狀況更為緊急。\n\n昨天有衛兵回報說，在林裡發現被遺忘者。現在這些衛兵已經開始出現類似荒疫的病徵，就像我們之前在吉爾尼斯遇到的類似。看來被遺忘者想在黯狼守望散播荒疫。\n\n在我們被荒疫攻擊前，找出並毀掉他們的荒疫儲物堆！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39061] = {title = "黑暗中的低語", objective = "從黯狼守望附近的懼翼騎士密探和懼翼騎士瘟疫使者身上，取得被遺忘者偵察指令。", description = "我們仍舊無法掌握部落在這個地區的行動。我希望你能夠協助收集情報。\n\n最近，整座森林到處都是希瓦娜斯的密探。我們捉到的幾個人身上都帶有黑暗遊俠的指令。希瓦娜斯在此區的部隊想必就是由他們指揮。\n\n狩獵敵人時，留意任何偵察指令。相關文件可能有助於我們找出希瓦娜斯在這個區域的目標。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39062] = {title = "前往斯寇亞胥", objective = "在克羅雷瞰臺與指揮官羅娜‧克羅雷碰面。", description = "終於逮到她了！根據這些報告，希瓦娜斯的部隊在斯寇亞胥肯定在尋找什麼東西，那是個離此不遠的維酷城鎮。我們得出發前往該地，並追查她的下落。\n\n我先前已經派出指揮官羅娜‧克羅雷帶領吉爾尼斯兵團分遣隊到該地點進行偵察。到那邊和她會合，並查明希瓦娜斯在尋求什麼。\n\n同時，我會召集艦隊突擊他們的前哨站。就算要把他們的營地化為廢墟，我們也一定會伸張正義。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39063] = {title = "盾中秘密", objective = "在斯寇亞胥檢查6面紋刻維酷盾牌。", description = "很明顯，部落想要斯寇亞胥的某樣東西。不幸的是，我們還是不知道他們要什麼。\n\n我們認為秘密就在此地的女盾侍身上，所以我們得進一步瞭解她們。一些早期的偵察結果顯示，她們用某種方式雕刻盾牌，用來傳述故事。\n\n進入城市，盡你所能尋找這些盾牌。如果運氣夠好，我們就可以查出希瓦娜斯想要的是什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39067] = {title = "艦隊升級", objective = "收集1000要塞資源、1000枚金幣，並且完成15個海軍任務。", description = "你的表現非常出色，指揮官。不過，我們還需要更多經驗、更多資源才能夠讓船塢升級。一旦達到目標，我們就可以提高船塢的容量！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n要塞：船塢，等級2\n\n您還會收到：\n\n船艦藍圖：潛水艇"}
MultiLanguageQuestData['tw'][39068] = {title = "制霸海權", objective = "收集2500要塞資源，2500枚金幣，並且完成25個海軍尋寶任務。", description = "我們的海上霸權將會延續下去！\n\n不過，我們需要更多的經驗和資源，把這座船塢提升到更高的境界。等目標達成，就能提高船艦的數量！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n要塞：船塢，等級3\n\n您還會收到：\n\n船艦藍圖：航空母艦"}
