MultiLanguageQuestData['tw'][39082] = {title = "我們開工吧", objective = "到乾船塢和所羅格會面。", description = "我們現在有了這座船塢，得開始忙著造船了！所羅格跑去乾船塢了，你直接去下面找他如何？他說他有個計畫。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料"}
MultiLanguageQuestData['tw'][39090] = {title = "殺光他們！", objective = "殺死200個敵對玩家。", description = "找到他們，追殺他們，宰掉他們。給敵人一個永生難忘的教訓。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一箱魔化戰場物資"}
MultiLanguageQuestData['tw'][39092] = {title = "成為晉升者", objective = "在斯寇亞胥的神廟中獲得4座祭壇的祝福，然後和雕像溝通。", description = "現在的目標很明確了。我們必須進入神殿，阻止希瓦娜斯獲得創造更多華爾琪的力量。\n\n入口被封住了，可能是因為這樣她才沒能進去，不過你或許已經找到破除這道屏障的關鍵了。\n\n你必須成為下一位晉升者。\n\n完成盾牌上描述的儀式，並打破神殿入口的屏障。我會把目前所知的一切告訴葛雷邁恩，他會想親自面對希瓦娜斯的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39096] = {title = "杀光他们！", objective = "击杀200名敌方玩家。", description = "绝不能容忍部落的入侵。把他们都干掉！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39107] = {title = "做一票更大的", objective = "為格利夫塔取得髒鐵幣。", description = "原來這些塔南的呆子帶了各式各樣的財寶。這還是很複雜，但我現在可以給你更多！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39117] = {title = "終止尖嘯", objective = "沿著布瑞登溪找到爛喙，並取回這頭野獸的腦袋。", description = "爸爸很喜歡這個村子。就算在這種最悲慘的時候，他也聽不進任何要他離開這裡的建議。\n\n他在死前告訴我攻擊他的是一隻恐怖的獵鷹，叫做爛喙。\n\n你正在對抗這些不死生物，對吧？你能幫我父親復仇嗎？如果願意的話，那頭野獸就在此地的西北方，在通往海邊的路上徘徊。", progress = "爸爸老是說，如果要他離開此地，一定是躺橫的被扛走。\n\n真希望他說的沒有成真。", completion = "謝謝你。看起來很恐怖吧，欸？我想我會把它掛在門上。\n\n這個也給你。爸爸生前最愛吃新鮮打撈的蘚鰓鱸魚。", rewards = "您能選擇下列奬勵中的一個：\n\n黑革指環骨羽咒符\n\n您還會收到：\n\n食譜：酥炸蘚鰓鱸魚"}
MultiLanguageQuestData['tw'][39119] = {title = "襲擊斯寇亞胥", objective = "<insert>", description = "<insert>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][39122] = {title = "終結新希望", objective = "在埃伊爾之殿迎戰希瓦娜斯。", description = "女妖之王就在這裡！不論在什麼地方，我都認得出她那汙穢的箭矢。\n\n我們就是為了這一刻而奮戰不休。希瓦娜斯必須為背叛瓦里安‧烏瑞恩和聯盟付出代價！\n\n所有人備戰！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "希瓦娜斯的斷箭黑暗女士之禍時髦的吉爾尼斯項圈盛怒狼人兜帽守牆者罩盔精製狂怒顱殼您能選擇下列奬勵中的一個：\n\n咒血之毅\n\n您還會收到：\n\n黑瑪瑙箭頭"}
MultiLanguageQuestData['tw'][39123] = {title = "守株待獅", objective = "在松岩盆地獵殺松岩潛獵者和松岩徘徊者。", description = "這片山丘上潛伏著許多山獅，在遠處觀察獵物。這些大貓一旦鎖定任何目標，就會朝獵物飛撲而去，包括<race>。\n\n雖然多數人都會敗給這種強大的掠食者，但在我狩獵團裡的每一個人都有能力擊敗這種野獸。\n\n拿出真本事來，幹掉幾隻潛獵者，證明你的實力吧。", progress = nil, completion = "我看你毫髮無傷，看來這些山獅根本不知道你來了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39124] = {title = "鹿死誰手", objective = "在松岩盆地獵殺松岩領角鹿。", description = "高嶺是許多野生動物的家園，這些動物在外地絕對獵不到。告訴我，<name>，你之前有注意過這些鹿嗎？\n\n這些悠閒的領角鹿看起來是性情溫和的巨獸，但只有傻子才會低估牠們的力量。\n\n即使是像你這麼有經驗的人，牠們應該還是蠻有挑戰性的。", progress = nil, completion = "你殺了高嶺領角鹿，還能活著回來告訴我們這個消息。這可不是一般人能做到的事，你太讓我驚艷了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39125] = {title = "屠魔者", objective = "殺死厄運召喚者、蔑喉和獰鍊。", description = "一定要解決掉散播這片腐化的惡魔。殺掉它們的將軍，它們的計畫自然會泡湯。\n\n我要送你一件寶物。這個號角是歐丁親自給我的，用它掃蕩所有阻礙吧。\n\n你若能擋下燃燒軍團的攻勢，諸神一定會向你微笑的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39127] = {title = "長城之外", objective = "到螳螂荒原的長陰哨站找塔蘭‧祝。", description = "我們收到消息，影潘開始朝螳螂荒原推進反擊了。聽起來他們在追查這次揚古入侵的根源。\n\n熊貓人已有好幾千年不曾組隊進入螳螂荒原。影潘強大且勇敢，但他們也很高傲，人數很少。他們會需要像你這樣的英雄協助。你能穿過冬綻西北邊的關口嗎？能找到影潘領導者，向他提供你的協助和經驗嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39128] = {title = "Tanaan Vignette", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39131] = {title = "佔有力量", objective = "去找對裂片的來源有所了解的人。", description = "萬千世界的迴響如漩渦般在你掌中繚繞。我們需要眼魔之眼，才能體現它真正的價值。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39133] = {title = "沒空聊天", objective = "消滅8個暴怒的琥珀裂石怪。", description = "達古爾派了他的寵物來應付我們。\n\n我們得在這些元素生物的怒火夷平雷霆圖騰之前，把它們統統打碎。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39134] = {title = "怒碎", objective = "殺死怒碎。", description = "地底之王用卡茲格羅斯之錘把山坡化成武器來對抗我們。神錘是創造用的工具，而不是讓他拿來消遣的武器！\n\n他的水晶僕人怒碎還一直驅使元素生物離開山脈，找我人民的麻煩。\n\n讓我們看看你是否和預言中一樣厲害。\n\n把怒碎打成碎片，再把碎片送回它主人手中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "雷霆之巔束腰雪盲之索白浪繫腰卓格縫製腰帶雪盲護腿卓格縫製馬褲白浪裹腿雷霆之巔腿鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][39142] = {title = "測試理論", objective = "對被囚禁的小鬼使用血石。", description = "血石已經餵飽了，我希望能利用它的力量來控制惡魔，它們沒那麼容易用其他方式控制。\n\n當然了，這一切都只是理論。我從未親眼見過在血石直接影響之下的惡魔，這也就是為什麼我需要你協助。\n\n我抓了一些小鬼，它們應該很適合作為測試對象。對它們用這顆血石，然後告訴我效果如何。", progress = nil, completion = "測試對象在過程中死亡？這真是出乎意料。\n\n不過，你已經完成你承諾的事。現在該換我實踐承諾了。", rewards = "您會收到：\n\n"}
