MultiLanguageQuestData['tw'][39188] = {title = "英雄的召喚：泰洛卡森林！", objective = "到泰洛卡森林去和塞納里奧灌木林的一個德魯伊談談。", description = "我們和塞納里奧灌木林的德魯伊失聯了。\n\n瓦里安國王下令聯盟所有行有餘力的人，都要進入泰洛卡森林並查明發什了什麼事。\n\n想要找到灌木林，必須穿過贊格沼澤並前往泰洛卡森林的西北方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39191] = {title = "碎冰者的遺贈", objective = "面對麥格納爾‧碎冰者。", description = "最傑出的戰士應該用最強大的武器。很久以前有一位偉大的國王，叫做麥格納爾‧碎冰者，他的武器是以當時最強大的巨龍鱗片製成。他應該來到英靈殿，但卻沒有，而是在墳墓裡逐漸凋零。\n\n他的兒子赫魯茲納就在這裡。他會帶你前往墳墓。可以的話，請拯救麥格納爾。而無論如何，都要帶著他的武器回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39195] = {title = "頂尖寶石", objective = "到塔南森林尋找日之賢者恰基斯。", description = "指揮官！雖然戰事持續進行，你對珠寶設計技術的鑽研仍持續勤奮不懈，我覺得這才是最值得讚揚的。\n\n我聽到阿拉卡人在談論一台寶石切割裝置，他們相信那個東西位於塔南森林。他們是從一位叫「恰基斯」的人那邊聽到的。\n\n我想，你可能會有興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39196] = {title = "大酋長的命令：納葛蘭！", objective = "到納葛蘭和卡拉達爾的卡洛克汗隊長談談。", description = "大酋長要求任何能動身的部落勇士，前去卡拉達爾提供協助。\n\n那是瑪格哈獸人的家園，位置就在南方的納葛蘭。沿著南方的道路穿出沼澤，然後在第一條叉路轉向東方，並留心尋找湖邊的大型聚落。\n\n向該地的卡洛克汗隊長報到，並盡你所能的提供協助。卡拉達爾絕不能淪陷！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39197] = {title = "英雄的召喚：納葛蘭！", objective = "到外域的納葛蘭和泰拉的守望者莫布夫‧吉爾談談。", description = "國王要求你，代表他到納葛蘭與泰拉的卡爾奈會面。\n\n抵達之後，先去找守望者莫布夫‧吉爾。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39198] = {title = "大酋長的命令：劍刃山脈！", objective = "前往劍刃山脈的雷霆王村和葛德雷克談談。", description = "大酋長正在招募勇士前往劍刃山脈，一舉解除巨魔的威脅。一路向北進入山區，抵達獸人堡壘雷霆王村。讓葛德雷克瞭解我們的狀況，並且請他提供任何的協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39199] = {title = "英雄的召喚：劍刃山脈！", objective = "到劍刃山脈的希爾瓦納與琳娜‧月泉交談。", description = "在劍刃山脈希爾瓦納的聯盟部隊要求增援。\n\n國王請求任何能夠動身的聯盟人員，沿著贊格沼澤的北側邊界進入山區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39201] = {title = "大酋長的命令：虛空風暴！", objective = "向52區的火箭主管夫斯拉吉回報。", description = "在虛空風暴52區的哥布林要求協助，請任何有能力前往的勇士，自願去協助他們的工作。\n\n大酋長認為他們在當地的位置與協助能提供我們優渥的戰術優勢，對抗附近的凱爾薩斯部隊。\n\n要前往52區，只要沿著劍刃山脈最北邊的路，直到你看到整個世界在扭曲虛空中崩碎。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39202] = {title = "英雄的召喚：虛空風暴！", objective = "向52區的火箭主管夫斯拉吉回報。", description = "在虛空風暴52區的哥布林要求協助，請任何有能力前往的勇士，自願去協助他們的工作。\n\n大酋長認為他們在當地的位置與協助能提供我們優渥的戰術優勢，對抗附近的凱爾薩斯部隊。\n\n要前往52區，只要沿著劍刃山脈最北邊的路，直到你看到整個世界在扭曲虛空中崩碎。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39203] = {title = "大酋長的命令：龍骨荒野！", objective = "和位於阿格瑪之錘的大法師埃薩‧奪日者的影像談談。", description = "大酋長期望能夠在龍骨荒野的阿格瑪之錘強化部落的勢力。\n\n這座堡壘是我們對寒冰皇冠展開襲擊的關鍵，也是管控混亂的魔法能量四處流竄的重要據點。\n\n去向大法師埃薩‧奪日者報到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39204] = {title = "英雄的召喚：龍骨荒野！", objective = "到繁星之眠和大法師莫德菈的影像談談。", description = "我們需要志願者到龍骨荒野協助白銀誓盟部隊反制混沌的秘法能量，以免這塊大地被撕成碎片。\n\n特別歡迎擅長對抗飛龍和不死生物的人士。\n\n願意回應召喚的人，請到龍骨荒野的繁星之眠向大法師莫德菈報到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39206] = {title = "大酋長的命令：灰白之丘！", objective = "向征服者克蓮娜自我介紹，她就在灰白之丘的征服堡。", description = "灰白之丘的基地向我們求援。\n\n去找征服者克蓮娜，她想要取得該地所有的天然資源。在她身邊要小心一點，據說連一般獸人都覺得她過於激進。\n\n從龍骨荒野往東邊走就可以找到她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39207] = {title = "英雄的召喚：灰白之丘！", objective = "到灰白之丘西部的琥珀松小屋向都蒙特中尉回報。", description = "當我們專注於防守溫特加德的領土和解決憤怒之門的事件時，來自遙遠的西部荒野的部隊也正在灰白之丘與艱苦的環境和充滿敵意的居民奮戰，希望能夠找出一條進入寒冰皇冠的替代道路。\n\n駐紮在琥珀松小屋的都蒙特中尉正在徵召身強體壯，願意冒生命危險，協助開拓這片陌生荒野的民眾。你願意挺身面對這個挑戰嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39208] = {title = "祖爾德拉克", objective = "到祖爾德拉克的黯黑守望找史戴芬‧瓦度。", description = "我們在祖爾德拉克的死亡騎士盟軍，需要英雄幫助他們對抗天譴軍團，拿下食人妖的土地。\n\n願意伸出援手的英雄，請前往黯黑守望西南方的營地，與那裡的史戴芬‧瓦度交談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39209] = {title = "休拉薩盆地", objective = "在休拉薩盆地的叢生沼林與蒙特‧膛擊交談。", description = "赫米特‧奈辛瓦里深入休拉薩盆地的叢林深處探險後就音訊全無。從那之後，他的遠征隊憑空消失了。\n\n蒙特‧膛擊這位駕駛員出發去援助探險補給以後也一去不返。\n\n我們需要志願者前去尋找失蹤的探險隊。蒙特的飛行器最後出現的地點是休拉薩盆地，日觸之柱南邊的叢生沼林。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39210] = {title = "魔法王國達拉然", objective = "到達拉然的紫羅蘭之門向大法師瑟琳卓回報。", description = "祈倫托將整座城市遷移到北裂境這裡來。\n\n達拉然再也不會待在洛丹米爾湖畔的保護罩裡面，現在這個城市靠著魔法漂浮在水晶之歌森林的上方。\n\n他們認為你已經準備好，該到達拉然去一趟。去找水晶之歌森林中的傳送水晶。\n\n當你抵達的時候，去找大法師瑟琳卓。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39212] = {title = "休拉薩盆地", objective = "當你準備要前往休拉薩盆地時，去跟大法師潘塔魯斯談談。等你抵達之後，可以和蒙特‧鼻擊談一談，他就在休拉薩盆地的叢生沼林。", description = "赫米特‧奈辛瓦里深入休拉薩盆地的叢林深處探險後就音訊全無。從那之後，他的遠征隊憑空消失了。\n\n蒙特‧膛擊這位駕駛員出發去援助探險補給以後也一去不返。\n\n達拉然的大法師潘塔魯斯正在一架飛行器旁邊等著你，要送你去蒙特‧膛擊最後的已知地點。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39214] = {title = "歐丁之眼", objective = "前往歐丁之眼。", description = "是時候在艾澤拉斯開戰了。我們已準備了一項工具，協助你從這兒指揮旗下的戰士及任務行動。它就名為歐丁之眼。\n\n跟我來，我帶你過去，然後會有人協助你使用歐丁之眼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39217] = {title = "放下仇恨，去探勘！", objective = "人在艾斯蘭的哈里遜‧瓊斯要你去調查艾斯蘭挖掘場的最深處，那是一個叫突破口的地方。", description = "嗯，<name>，好消息是我們的挖掘小隊在外頭的洞窟下方挖出了一間密室。壞消息是部落也在那裡。下去那裡探個究竟。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39221] = {title = "瑪諾洛斯之池", objective = "在地獄火堡壘擊敗寇姆洛克。", description = "他們在地獄火堡壘中使用瑪諾洛斯之池內的魔化能量來腐化麥奈隆。\n\n如果你要去探索那個地方的魔化池，務必要保持警覺。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39225] = {title = "靈魂之喉", objective = "在地獄火堡壘擊敗血魔。", description = "墜入奧齊頓的陵墓深處，泰朗戈爾吞嚥數以百計的德萊尼亡靈，在這個過程中演變成體態浮腫的噁心怪物。\n\n泰朗戈爾已經不再具有獸人的外型，而且還放棄了他原有的名字，改稱自己為「血魔」。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39228] = {title = "暴君神殿", objective = "在地獄火堡壘擊敗女暴君維哈里。", description = "女暴君維哈里曾是一位大有可為的復仇者，但是後來卻為了只有她自己知道的不明原因而投向黑暗。\n\n淨化這個黑暗的埃雷達爾。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39231] = {title = "毀滅者高臺", objective = "在地獄火堡壘擊敗瑪諾洛斯。", description = "我們以為之前已經搞定瑪諾洛斯了，至少目前是這樣。可是古爾丹比我們預料的還要強大。\n\n瑪諾洛斯可能又會回到這個世界。他的骨骸就在堡壘中，我們必須在他重獲力量之前摧毀他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39232] = {title = "黑門", objective = "在地獄火堡壘擊敗阿克蒙德。", description = "據說一位強大的埃雷達爾很快就會通過黑門進入這個世界。\n\n如果傳言是真的，很可能是『污染者』阿克蒙德來了。要是沒有人能擊敗『污染者』阿克蒙德，德拉諾就完了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39233] = {title = "放下仇恨，去探勘！", objective = "人在艾斯蘭的貝洛克·亮刃要你去調查艾斯蘭挖掘場的最深處，那是一個叫突破口的地方。", description = "<name>，你終於來了，而且你來的時間剛剛好。快，到礦坑底下去，看看我們發現了什麼。你可能會在下頭遇到聯盟。只是點小麻煩罷了，很容易就可以解決。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39234] = {title = "緊急狀況", objective = "在達拉然下水道跟馬迪亞斯‧肖爾談話。\n\nB軍情七處的馬迪亞斯‧肖爾大師有事相召。他正在達拉然地底等你。小心，下水道最近常有人失蹤。", description = "\n\nB軍情七處的馬迪亞斯‧肖爾大師有事相召。他正在達拉然地底等你。小心，下水道最近常有人失蹤。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39236] = {title = "我們開工吧", objective = "到乾船塢和所羅格會面。", description = "我們現在有了這座船塢，得開始忙著造船了！所羅格跑去乾船塢了，你直接去下面找他如何？他說他有個計畫。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料"}
MultiLanguageQuestData['tw'][39241] = {title = "造船", objective = "學習藍圖並銷毀證據。", description = "我們要動手造船，需要的第一樣東西就是藍圖。在你的協助下，我在逃出鋼鐵碼頭之前，從裡面拿了一些最棒的設計。\n\n<class>，為了確保它們不會重回鋼鐵部落之手，請你記住這些藍圖，然後將其銷毀。完成之後告訴我一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39242] = {title = "船艦的建造", objective = "與所羅格交談，開始建造運輸艦。完成之後，把它加到你的船艦收藏裡。", description = "你想要對抗古爾丹？你需要運輸艦！當你準備開始建造的時候，和我說一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39243] = {title = "海軍指揮官", objective = "到你的船塢找羅沃許‧逐浪者，並完成一個海軍任務。", description = "你天生就是這塊料，<name>。你的身上流著大海的血液。是時候展開第一項海軍任務，進一步掌控德拉諾的海域！\n\n你需要一個優越的位置來規劃航海任務。我知道在我們背後的這條路上就有個好地點。到船塢入口那邊和我碰面，然後就著手進行第一個任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39245] = {title = "艦隊升級", objective = "收集1000要塞資源、1000枚金幣，並且完成15個海軍任務。", description = "你的表現非常出色，指揮官。不過，我們還需要更多經驗、更多資源才能夠讓船塢升級。一旦達到目標，我們就可以提高船塢的容量！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n要塞：船塢，等級2\n\n您還會收到：\n\n船艦藍圖：潛水艇"}
MultiLanguageQuestData['tw'][39246] = {title = "制霸海權", objective = "收集2500要塞資源，2500枚金幣，並且完成25個海軍尋寶任務。", description = "我們的海上霸權將會延續下去！\n\n不過，我們需要更多的經驗和資源，把這座船塢提升到更高的境界。等目標達成，就能提高船艦的數量！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n要塞：船塢，等級3\n\n您還會收到：\n\n船艦藍圖：航空母艦"}
MultiLanguageQuestData['tw'][39247] = {title = "獵殺", objective = "在蘇拉瑪爾從瓦瑞迪斯‧魔魂的手中取得欺詐者雙刃。", description = "這場獵殺行動由你帶領，<name>。有支伊利達瑞精英部隊將歸你指揮，務必擊殺瓦瑞迪斯。\n\n我們其他人必須留守後方。只有小型隊伍才有機會進入他的要塞而不受察覺。\n\n等你準備好的時候，我們會在卡薩斯平臺替你送行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
