MultiLanguageQuestData['tw'][39417] = {title = "拉傑的能耐", objective = "到赫米特‧奈辛瓦里的高嶺居所找他。", description = "赫米特正在等我的軍火研發進度報告。\n\n我想你一定很樂意跟我老大說我的最新成品運作順暢。\n\n你可以在獵人小屋附近找到他的營地。", progress = nil, completion = "很高興聽到拉傑的工具研發有所進展。\n\n如果他能設計一種可以自動瞄準的槍枝，那些在盆地亂跑的業餘獵人就不怕打不中目標了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39419] = {title = "消咒破織", objective = "殺死咒織者雅卡菈。", description = "這些鷹身人總是不斷想要控制盆地。我們清理那些邪惡魔法生物的速度，總是趕不上他們製造的速度。\n\n只要咒織者還活著，天角部族就無法佔上風。一定要阻止她。", progress = nil, completion = "你幫了天角部族很大的忙，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39422] = {title = "船塢報告", objective = "回到落月船塢。", description = "指揮官，我們收到了來自船塢的報告，情勢開始變得嚴重。能不能請你返回落月船塢，去找莫瑞克？我們建造的每一艘船都能提高我們對抗古爾丹麾下新部落的戰力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39423] = {title = "船塢報告", objective = "回到霜牆船塢。", description = "指揮官，我們收到了來自船塢的報告，情勢開始變得嚴重。能不能請你返回霜牆船塢，去找羅沃許？我們建造的每一艘船都能提高我們對抗古爾丹麾下新部落的戰力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39424] = {title = "一切！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39425] = {title = "石暗水晶", objective = "找到納瓦羅格的石暗聚焦水晶。", description = "少了聚焦水晶，我的力量會變得虛弱。抓到我的人把它拿走了，而且我不清楚它現在位於何方。\n\n我只能確定它在魔化圖騰部族的某人手中。如果你找到它的話，請帶回來給我。", progress = "就算沒有水晶，我還是有能力操控大地。但有了水晶，我的力量就不可同日而語了。", completion = "這可以協助我修復破碎的身體。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39426] = {title = "血債", objective = "在托洛卡之崖擊敗托洛卡‧血圖騰。", description = "你證明了自己是比血圖騰部族更好的盟友。多虧我的聚焦水晶，我的傷勢已經痊癒了。然而碎石怪恐怕是回天乏術了。\n\n托洛卡跟他的血圖騰部族會為他們所做的事付出慘痛代價。在他們對洞穴中的族人發動攻勢之前，我們來拜訪他們一下。", progress = nil, completion = "你已經贏得我的信任。但只要地底之王達古爾領導著我的同胞，石暗卓格巴就依然危在旦夕。我們願意加入梅拉‧高嶺的牛頭人行列，一起對抗他們。", rewards = "石暗之勇石暗聚焦水晶血詠師精華托洛卡之心惡魔部族尖牙血圖騰之懼碎石怪的核心領角鹿的本能血圖騰的背叛鐵牛的遺言貪婪血寶石您會收到：\n\n"}
MultiLanguageQuestData['tw'][39427] = {title = "神鷹之魂的祝福", objective = "到高嶺的觀魂者哨站，接受神鷹之魂的祝福。", description = "那支矛與雍亞拉的靈魂互相連結。先與她交談，接受祝福之後再去追尋那支矛是我們的傳統。她也可能會傳授一些知識。\n\n如果你陪我前往觀魂者哨站，我會召喚神鷹之魂，祈求她祝你武運昌隆。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39429] = {title = "攻擊女巫之地", objective = "在女巫之地殺掉8個勾爪鷹身人和6個忠誠的天鬚狗頭人。", description = "步行進入女巫之地，並殺死你看見的任何鷹身人。\n\n削減她們的人數！\n\n我們會提供空中支援，讓你的獵物在地面上任你處置。\n\n讓這些女巫嘗嘗你…嗯…你「那個」的厲害。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39430] = {title = "有「瓶」相求", objective = "在高嶺的鐵角營地尋找巴姆‧碎石者。", description = "你知道，這瓶混合藥劑沒受到多少損傷。我想這玩意還能修復。\n\n我不是修補玻璃的高手，但我聽說過這方面的專家，一位名叫巴姆‧碎石者的牛頭人。他的職業是鐵匠，但熟識他的人都說他生來就是玻璃工匠的料。\n\n那些牛頭人可不會做白工，所以你可能會有些工作要做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39431] = {title = "修補濾紙", objective = "在維爾薩拉找到能幫助你縫補絲綢的裁縫師。", description = "帶這樣的布料回來對德克斯一點助益也沒有。\n\n或許維爾薩拉這裡會有裁縫師願意幫你縫補。\n\n稍早幫助你的女祭司或許知道這樣的人物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39432] = {title = "不可知的力量", objective = "從塔南森林的寶藏、稀有或稀有精英生物身上收集魔化頂尖碎片。", description = "那個叫做古爾丹的人腐化了他自己的族人，他現在還想對我們所剩的族人下手。在可拉納克那邊的墮落流亡者已經效忠古爾丹，只為了那個能再次翱翔天際的虛假承諾。古爾丹會將頂尖之力賜給最強大的手下，但這是一股我無法解釋的扭曲力量。替我取回其中一片碎片吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39433] = {title = "不可見的影響", objective = "從塔南森林的寶藏、稀有或稀有精英生物身上收集10個魔化頂尖碎片。", description = "有許多族人受到了腐化的頂尖水晶影響。我們太習慣水晶所賦予的力量了，所以也更容易在日復一日的低語下屈服。你一定要幫我帶來更多樣本，才能讓我的族人擺脫另一道詛咒。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39434] = {title = "短缺奖励", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39437] = {title = "洞穴深處", objective = "在石暗洞穴殺死8個魚人。", description = "我們再也受不了那些魚人了。他們在洞穴裡到處竄來竄去，簡直把這裡當成他們家一樣。他們偷走了幾樣寶貴的聖物，還到處留下了充滿魚腥味的鱗片。\n\n殺掉幾隻魚人，讓它們知道不能在這裡搗亂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39438] = {title = "咕嚕嚕嚕", objective = "擊敗咕嚕嚕嚕。", description = "魚人平時很怕我們，但有些體型較大的魚人會帶著同伴闖進我們的洞穴，真是莽撞。\n\n殺死他們的領導者。我想它的名字像是「咕嚕嚕嚕」。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "深蹲者束帶深蹲者護腰深蹲者腰帶深蹲者護腰汗水淋漓腕輪汗水淋漓臂環汗水淋漓護腕汗水淋漓腕鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][39439] = {title = "石暗聖物", objective = "取回反抗之鍊、堅毅之輪和負荷之杖。", description = "魚人想辦法偷走了我們的聖物，並且把它們帶到了低處的洞穴裡。\n\n在我們暖身的時候，你能先去找它們嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39440] = {title = "好傢伙，不舉嗎？", objective = "扛著這些重物走到大力卜魯雕像那邊，再回頭找『強者』丹魯爾。", description = "你能舉重嗎？如果你扛著這些重物走到大力卜魯雕像那邊再回來，或許我們可以聊聊。", progress = nil, completion = "你比外表強壯多了，小傢伙。", rewards = "您會收到：\n\n"}
