MultiLanguageQuestData['tw'][39445] = {title = "進攻魔化熔爐", objective = "在塔南森林的鐵握港襲擊鋼鐵部落援軍。", description = "鋼鐵部落持續從德拉諾各地調動援軍，來鞏固他們在地獄火堡壘的勢力。如果我們不打斷補給線，就有可能無力按照原定計畫、固守塔南。\n\n想要讓鋼鐵部落轉為守勢，並維持我方氣勢，最合適的做法就是對鐵握港的補給線進行一波策略性攻擊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][39446] = {title = "進攻魔化熔爐", objective = "在塔南森林的鐵握港襲擊鋼鐵部落援軍。", description = "鋼鐵部落持續從德拉諾各地調動援軍，來鞏固他們在地獄火堡壘的勢力。如果我們不打斷補給線，就有可能無力按照原定計畫、固守塔南。\n\n想要讓鋼鐵部落轉為守勢，並維持我方氣勢，最合適的做法就是對鐵握港的補給線進行一波策略性攻擊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
