MultiLanguageQuestData['tw'][39661] = {title = "活泉洞穴", objective = "在活泉洞穴和潔爾‧河鬃碰面。", description = "卓格巴佔據了我的洞窟。我們河鬃氏族在洞窟裡施展水之魔法，產生了高嶺最純淨的癒療之水。\n\n在那裡跟我會面，我們會將這些黑暗魔物逐出聖所。", progress = nil, completion = "你準備好了嗎？我們即將進入洞穴…而黑暗的洞穴對卓格巴來說就像家一樣親切。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39663] = {title = "乘上魔化蝙蝠", objective = "從依薩爾‧皎月那裡取得魔化蝙蝠，飛上魔錘號。", description = "時候到了。我們已經對燃燒軍團帶來難以彌補的沉重打擊。\n\n快點，騎上坐騎，飛往泰蘭娜的指揮室。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39665] = {title = "真正的海軍指揮官", objective = "在你的船艦上裝備高壓熔爐，並完成海軍封鎖任務。", description = "沒錯！那就是我上禮拜在釣魚的時候弄丟的藍圖。這上面的說明和我的原形裝備絲毫不差。把高壓熔爐裝在我們的船艦上吧，這樣我們就能突破海軍封鎖線，進一步控制德拉諾的海域了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n趕工令：船塢油料"}
MultiLanguageQuestData['tw'][39666] = {title = "整備艦隊", objective = "到碼頭上和索提‧裘倫碰面。", description = "指揮官，要想在這場戰爭中求勝，我們的艦隊就需要一些專門的船艦設備。到碼頭那裡找索提‧裘倫，他會有辦法幫助我們的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料"}
MultiLanguageQuestData['tw'][39667] = {title = "林德拉斯的下落：侵佔地脈火焰", objective = "向紫羅蘭堡的衛兵詢問林德拉斯的下落。", description = "這裡的守衛一定有看到林德拉斯經過。也不太可能沒人注意到地脈之塵的痕跡。\n\n或許其中一位守衛知道林德拉斯發生什麼事了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39668] = {title = "多麼糟糕的禮物啊！", objective = "毀掉5個不尋常的禮物。", description = "那表示壞心鬼有很多很多詭異的禮物。他故意要送小朋友最爛最爛的禮物來打擊他們的心情。\n\n這個開心炸彈給你。把它丟在壞心鬼那些不尋常的禮物上，把它們炸掉！\n\n我們一起加油吧，<name>。快點去拯救歡樂開心的節慶精神！", progress = nil, completion = "哇…這些禮物還真是糟糕啊。等等你最好去…洗個手。天曉得它們裡頭裝了什麼東西。", rewards = "您會收到：\n\n歡樂補給品"}
MultiLanguageQuestData['tw'][39670] = {title = "發射小動物進行驅散", objective = "在日霜林地捕捉兔子。", description = "這些山丘的嚎狼群聚而行。我可不想要以一打三。\n\n幸運的是，這些狼群可不是我工程技術的對手！我正好完成了一部原型機，它可以協助讓狼群分散。我現在需要的是一些彈藥…\n\n幫我去南方的林地抓些兔子回來，我就讓你第一個試試這款手砲。", progress = "你抓到兔子了嗎？", completion = "嗯，這些兔子比我想的大了一些，不過應該還是有幾隻能塞進手砲裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39671] = {title = "Guards and Criswold", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39674] = {title = "一次不成功，再試一下！", objective = "到乾船塢去找所羅格‧羅亞克，建造另一艘驅逐艦。驅逐艦完成以後，就派出去執行新任務。", description = "看樣子那艘潛水艇的火力比我們想像的還要強！我們根本就還沒看到他們，他們就用先手攻擊對付我們了。\n\n損失船艦對海軍來說是兵家常事，指揮官。幸運的是，我們對這種情況早有準備。到乾船塢找所羅格談談，他會幫我們盡快建造另一艘驅逐艦。船艦好了以後就回來這裡，我們還有新的海軍任務等著你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料"}
MultiLanguageQuestData['tw'][39675] = {title = "整備艦隊", objective = "在碼頭與柯朗克‧鏽光碰面。", description = "指揮官，要想在這場戰爭中求勝，我們的艦隊就需要一些專門的船艦設備。到碼頭那裡找柯朗克‧鏽光，他會有辦法幫助我們的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n油料"}
MultiLanguageQuestData['tw'][39676] = {title = "真正的海軍指揮官", objective = "在你的船艦上裝備高壓熔爐，並完成海軍封鎖任務。", description = "沒錯！那就是我上禮拜在釣魚的時候弄丟的藍圖。這上面的說明和我的原型裝備絲毫不差。把高壓熔爐裝在我們的船艦上吧，這樣我們就能突破海軍封鎖線，進一步控制德拉諾的海域了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n趕工令：船塢油料"}
MultiLanguageQuestData['tw'][39680] = {title = "進退兩難…", objective = "將薩里斯的錘子帶回他的店裡。", description = "<name>，如果我的心裡有遺憾，我擔心我會對這個地方念念不忘。\n\n很久以前，我在玄鴉堡後面的海岸發現一個洞穴。在探索過程中，我被一隻可惡的生物攻擊，逃跑時，不小心遺落了我的錘子。\n\n我必須拿回錘子，才能感到安心。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：脈石護腰\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39681] = {title = "脈石特性", objective = "觀察艾拉得處理脈石礦石的過程。", description = "我從未見過像「脈石」礦石這樣的東西。像秘銀一樣輕，卻又蘊藏更為強大的魔法能量…甚至比蕯鋼或源質礦還強大。\n\n讓我們試著用它來製作物品，例如一對護手？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n脈石鍛造簡介"}
MultiLanguageQuestData['tw'][39682] = {title = "俠盜獵蝠手", objective = "乘坐魔化蝙蝠飛到鐵獄上層。", description = "你聽見瑪翼夫說了，我們必須離開這裡。\n\n在這座洞窟遠處的另一端，有個升降梯井。我們要想辦法前往那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39683] = {title = "火鑄而生", objective = "殺死伊姆婪斯並奪取他的力量。", description = "伊姆婪斯是讓人聞風喪膽的惡魔，他率領燃燒軍團的部隊征服遙遠的異界，最終成為當地的統治者。\n\n不過他卻被看守者抓了起來，就關在我們左邊的囚室裡。但像他這樣的惡魔是關不了多久的。\n\n這個惡魔的力量對於能夠擊敗他的惡魔獵人而言，無疑是極具價值的獎勵。擊敗惡魔的人就能獲得超乎想像的力量。\n\n我相信那個人就是你，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n扭曲之心"}
MultiLanguageQuestData['tw'][39684] = {title = "照過去", objective = "破壞格雷瑟的護盾。", description = "東邊有一間複雜的特殊牢房，專門用來關押眼魔格雷瑟。\n\n但是這裡遭到入侵之後不久，控制系統就開始失效。\n\n你必須轉動牢房中的鏡子，讓能量光束聚焦在那個怪物身上，否則的話我們將無法擊破格雷瑟刀槍不入的護盾。\n\n動作快！奧翠司已經先過去幫其他人了，但我們的情況不妙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39685] = {title = "凍結於時光之中", objective = "啟動寒冰牢獄的反制系統。", description = "看守者在鐵獄內關押了各式各樣的危險怪物。現在，古爾丹的部隊已經攻了進來，這些囚犯造成了意外的…困擾。\n\n許多人正忙著壓制南邊牢房中的可怕熔岩怪物。我們才剛從靜止狀態甦醒過來，根本無法解決它。不過，我們或許可以重新啟動牢房的控制力場。\n\n請去與凱恩會合。盡一切所能封鎖那間牢房！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "煉獄火索束帶煉獄火索束帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][39686] = {title = "一路向上", objective = "乘坐升降梯前往審判廳。", description = "珂娃絲先過去找凱恩和奧翠司了。\n\n搭上降下來的升降梯，到上面的審判廳去找他們。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39688] = {title = "邁向自由的唯一障礙", objective = "殺死巴斯提萊斯並奪取他的力量。", description = "我們剩下的同伴已經殺出一條血路，到前方的最後一個房間去了。\n\n通往鐵獄出口的唯一障礙，只剩下巴斯提萊斯。而他正是這場惡魔入侵行動的領導者。\n\n殺死他，取得他的力量，奪回我們的自由。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n殘影\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39689] = {title = "伊利達瑞，我們要啟程了", objective = "與大法師卡德加交談。燃燒軍團已經開始入侵我們的世界。來自卡林多和東部王國各地的無數勇士，紛紛接受號召挺身參戰。\n\n然而，沒有你們的幫忙，這場戰爭終將會一敗塗地。伊利達瑞本來就是為了對抗燃燒軍團而訓練出來的武器。\n\n我只要求你和我一起走。到另一邊之後，你會得到進一步的指示。完成任務後，你將獲得：\n\n", description = "燃燒軍團已經開始入侵我們的世界。來自卡林多和東部王國各地的無數勇士，紛紛接受號召挺身參戰。\n\n然而，沒有你們的幫忙，這場戰爭終將會一敗塗地。伊利達瑞本來就是為了對抗燃燒軍團而訓練出來的武器。\n\n我只要求你和我一起走。到另一邊之後，你會得到進一步的指示。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39690] = {title = "伊利達瑞，我們要啟程了", objective = "與大法師卡德加交談。燃燒軍團已經開始入侵我們的世界。來自卡林多和東部王國各地的無數勇士，紛紛接受號召挺身參戰。\n\n然而，沒有你們的幫忙，這場戰爭終將會一敗塗地。伊利達瑞本來就是為了對抗燃燒軍團而訓練出來的武器。\n\n我只要求你和我一起走。到另一邊之後，你會得到進一步的指示。完成任務後，你將獲得：\n\n", description = "燃燒軍團已經開始入侵我們的世界。來自卡林多和東部王國各地的無數勇士，紛紛接受號召挺身參戰。\n\n然而，沒有你們的幫忙，這場戰爭終將會一敗塗地。伊利達瑞本來就是為了對抗燃燒軍團而訓練出來的武器。\n\n我只要求你和我一起走。到另一邊之後，你會得到進一步的指示。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39691] = {title = "戰爭召集令", objective = "在暴風要塞與捷斯‧暗織者交談。", description = "暴風城這座希望的壁壘今日籠罩在悲傷之中。\n\n瓦里安‧烏瑞恩國王戰死沙場，將王位留給他的兒子，安杜因。\n\n聯盟各大首領都聚集在此向他致敬。他們想必能用上你獨特的能力。\n\n國王正在暴風要塞的王座，有另一位伊利達瑞在他身邊。我必須先回到達拉然。\n\n祝你好運，$p。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39694] = {title = "邁向自由的唯一障礙", objective = "殺死巴斯提萊斯並奪取他的力量。", description = "我們剩下的同伴已經殺出一條血路，到前方的最後一個房間去了。\n\n通往鐵獄出口的唯一障礙，只剩下巴斯提萊斯。而他正是這場惡魔入侵行動的領導者。\n\n殺死他，取得他的力量，奪回我們的自由。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n扭曲之心"}
MultiLanguageQuestData['tw'][39696] = {title = "奮起吧，勇士們！", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：麥斯威爾‧泰羅索斯"}
MultiLanguageQuestData['tw'][39697] = {title = "主人對上指揮官", objective = "等你擊沉主喚號，取得德拉諾海域輿圖，即可完成傳奇船塢任務。", description = "我還在忙著挖掘，我不知道你們用航海術語是怎麼講的啦。浮潛還是什麼的？\n\n古爾丹派出他的精銳旗艦在德拉諾四處進行偵察任務。他正在繪製地圖，記載海域各處潛藏的魔法地脈。我可以利用這些情報來強化你的戒指…但要是落入古爾丹手裡，那後果可是不堪設想。\n\n擊沉他的艦隊，<name>！追擊他那艘聲名狼藉的旗艦，名字叫「主喚號」，在他們完成任務之前把地圖搶過來，快！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39698] = {title = "完成整備", objective = "跟隨希瓦娜斯‧風行者女士，並為她的船隻準備啟航。", description = "如你所見，為了支持你的偉大使命，我們可以說是不遺餘力。\n\n我們正在做最後準備。來，跟我一起走走。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39699] = {title = "鐵角脈石鍛造", objective = "收集鐵角營地附近的金屬碎塊。然後使用綠蹄的鐵砧和熔爐製作廢五金手甲、廢五金護掌、廢五金袖甲和1個廢五金護指。", description = "我感覺到你擁有很強的力量，但你卻拒絕發揮你的力量。我們鐵角部族在製作物品時，都會比一般鐵匠多用一倍的金屬。\n\n此外，在錘打數量加倍的脈石時，有特殊的技巧，這些我都會一一教你。\n\n使用我們剩下的金屬，錘打出護手的部件。完成後，我會把部件焊接在一起。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鐵角脈石鍛造\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39702] = {title = "玄鴉堡的傳說", objective = "到玄鴉堡尋找薩里斯‧迅錘。", description = "<name>，你聽說過薩里斯‧迅錘嗎？\n\n他是玄鴉堡精靈一族的傳奇鐵匠。不知道他的研究成果是不是還流傳於世。\n\n我要你去找找看有沒有跟薩里斯有關的東西，或者他有沒有留下一些東西，能帶回店裡研究。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
