MultiLanguageQuestData['tw'][39714] = {title = "Where Are the Children?", objective = "Help save the children.", description = "The children have gone missing!\n\nThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!\n\nOur scouts have spotted him over in Frostfire Ridge.您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n歡樂補給品"}
MultiLanguageQuestData['tw'][39715] = {title = "Menacing Grumplings", objective = "Remove the grumpling threat.", description = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus.\n\nIf you're able to remove the threat I'm sure rescuing the children won't be much of a problem.您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n野蠻雪球歡樂補給品"}
MultiLanguageQuestData['tw'][39716] = {title = "爆打南瓜怪", objective = "殺掉6個成長中的南瓜怪。", description = "骸骨艦隊一度曾襲擊行走德拉諾海域的商船。其中一艘船艦載了要送往埃羅多爾的農作物資。\n\n現在，他們利用這些物資在我們的土壤上散播他們的瘟疫。腐爛的土堆中長出了可怕的植物。這些魔物一定要被摧毀，才能阻止瘟疫擴散到這片土地上。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n萬鬼補給品"}
MultiLanguageQuestData['tw'][39718] = {title = "失樂園", objective = "在達拉然的卡薩斯平臺與大法師卡德加交談。", description = "大法師卡德加正在計畫遠征艾蘇納的行動。你應該立刻前往達拉然的卡薩斯平臺找他。", progress = nil, completion = "太好了。想去艾蘇納一趟嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39719] = {title = "骸骨戰船攻堅記", objective = "殺死裂骨船長。", description = "每年的這個時候，都會有一股鬼魅般的能量在德拉諾流竄，一支由不死海盜組成的可怕艦隊將會從迷霧中出現。我們把這隻艦隊稱作骸骨艦隊。\n\n骸骨艦隊由兇殘的裂骨船長帶領，他的目標就是要讓德拉諾生靈塗炭。\n\n在裂骨船長返回迷霧之前，抓緊時機擊敗他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n萬鬼補給品"}
MultiLanguageQuestData['tw'][39720] = {title = "惡臭的肥料", objective = "銷毀8桶恐怖的肥料。", description = "骸骨艦隊唯一的念頭就是在陸地上散播他們的不死詛咒。要是不嚴加防範，這個詛咒就會像病毒一樣在這片土地上逐漸擴散。\n\n不死的腐臭味，瀰漫在它們用來播下恐怖作物的一桶桶肥料當中，這些就是瘟疫散播的來源，一定得摧毀才行。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n萬鬼補給品"}
MultiLanguageQuestData['tw'][39721] = {title = "剔除船員", objective = "消滅12個骸骨戰船船員。", description = "要保護德拉諾不受骸骨艦隊的威脅，我們就要讓那些船員的數量降低。\n\n只要確保能快速減少他們的數量，或許就能把他們趕回海上，我們今年就安全了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n萬鬼補給品"}
