MultiLanguageQuestData['tw'][39729] = {title = "玄鴉知識", objective = "把薩里斯的研究帶回達拉然交給艾拉得。", description = "你的協助讓我得以維護尊嚴，現在我想要報答你。我的研究成果都放在那座石臺上。全部都交給你，好好鑽研學習，把我的傳說傳承下去。\n\n再次謝謝你，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39731] = {title = "寧靜之森", objective = "到達拉然的卡薩斯平臺找大法師卡德加交談。", description = "大法師卡德加不久前送來關於維爾薩拉的訊息，看來是好消息。\n\n你最好盡快到達拉然的卡薩斯平臺找他。", progress = nil, completion = "&lt;大法師卡德加向你微笑。&gt;\n\n我很少有機會這麼說，但我有好消息，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39733] = {title = "孤嶺", objective = "在達拉然的卡薩斯平臺與勇戰者歐洛交談。", description = "情報指出高嶺牛頭人信使抵達了達拉然。我們還不知道他的意圖，但他的人民有可能成為我們在當地的重要盟友。\n\n卡德加正在卡薩斯平臺會見這位信使，你去找他吧。", progress = nil, completion = "你好，勇士。我是高嶺的牛頭人勇戰者歐洛。戰爭即將來臨，所以我找你來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39735] = {title = "斯鐸海姆", objective = "前往達拉然的紫羅蘭城塞，與空軍上將羅傑斯交談。", description = "空軍上將羅傑斯送來消息，請你到達拉然和她見面。\n\n她會在紫羅蘭城塞等你。事情聽起來十分重要。", progress = nil, completion = "很榮幸見到你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
