MultiLanguageQuestData['tw'][39763] = {title = "魔爆為誰而響", objective = "從蘇拉瑪爾的蟲舌魔爪牙身上取得10個魔化能量核心。完成後，到達拉然把核心交給馬修。", description = "<馬修把你從頭到腳掃視一遍，喃喃自語>\n\n你想要我教你這塊岩石的知識？那就先證明你的誠意。\n\n燃燒軍團運來許多惡魔機器，準備征服這個世界。這些機器的動力來源是充滿魔化能量的核心。這些核心是由它們當中最低階的手下負責運送的。\n\n把足夠的核心帶來給我，我就給你需要的資訊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39764] = {title = "耀眼殺機", objective = "從泥鼻洞穴的狗頭人身上收集靈魂囚房。", description = "靈魂守衛者攸利亞與我在運送惡魔囚犯去艾蘇納找艾萊莉時，遭到狗頭人襲擊。\n\n這些無腦的低等生物奪走了囚禁惡魔俘虜的靈魂囚房。\n\n這些水晶或許耀眼，但同時相當致命。如果水晶有任何損傷，裡面的惡魔就有可能脫逃。\n\n前往附近的洞穴，在一切太遲之前奪回靈魂囚房。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39765] = {title = "除蠟高手", objective = "從藍蠟骸骨隊長身上取回耍威風顱骨。", description = "我已經死了好幾世紀，但我的墳墓從未像這樣被侵擾過…這裡的狗頭人首領從我的墳墓偷走我的顱骨，還戴在他的頭上！\n\n他在下面的洞穴裡，但路被門擋住，你無法直接取回顱骨。狗頭人以身上戴的顱骨辨認首領，只要你戴著顱骨，以他們的智力來說也會以為你是個首領。\n\n殺掉其中一個骸骨隊長，取得他的耍威風顱骨，他們可能就會讓你進到洞穴裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39767] = {title = "Sleigh and Snowfighters", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39768] = {title = "墳前獻上蠟燭", objective = "殺死7個藍蠟盜墓者。", description = "這些狗頭人趁著天角部族受到攻擊，侵擾我們的墳墓，偷走所有他們碰得到的東西。\n\n我無法阻止牠們！請幫忙把狗頭人逐出這個神聖的墓地。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39769] = {title = "蠟門", objective = "與藍蠟守門者交談，看看他是否會讓你覲見蠟燭王。", description = "去與藍蠟守門者說話，看看牠會不會讓你去見蠟燭之王。如果你戴了顱骨就能通過，那就不枉這身氣味了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39771] = {title = "雷霆之聲", objective = "前往白虎寺，證明你有能力駕馭風暴神兵！", description = "白虎為每個想得到風暴神兵的人準備了一系列的試煉。\n\n這武器的威力很強大，你要知道，這就是萊公在泰坦時代所用的武器。\n\n來吧！我在三個大陸上都帶領過競技場隊伍獲得勝利。有我在你這隊，你不可能輸的！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39772] = {title = "你的蠟燭無人能擋", objective = "從蠟燭之王身上取回歐妮雅的顱骨。", description = "好吧，我想你現在可以去跟蠟燭之王打招呼了。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "雪盲法衣卓格縫製護胸白浪裹胸雷霆之巔胸甲您能選擇下列奬勵中的一個：\n\n統御之鍊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39773] = {title = "靈魂守衛者的命運", objective = "在泥鼻洞穴裡找到靈魂守衛者攸利亞。", description = "靈魂守衛者攸利亞在狗頭人的襲擊中受了傷，但依然堅持深入洞穴，取回失竊的靈魂裂片。他叫我在這等著，守著其餘的補給直到他回來，但我很擔心他有個萬一。\n\n請找到攸利亞。他是唯一知道如何困住惡魔的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39774] = {title = "監禁惡魔", objective = "削弱惡魔，讓學徒羅莎琳有機會把惡魔困在靈魂囚房裡。", description = "必須要監禁逃走的惡魔，不能殺死它們。攸利亞受託運送囚犯給艾萊莉以便審判，我不會辜負他的使命。\n\n我看過攸利亞困住許多惡魔。看起來…很複雜，但我想我應該能成功，只是需要你先壓制它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "雷霆之巔巨腰帶白浪鎖鍊卓格縫製束腰雪盲裹腰攸利亞的溫暖攸利亞的撫慰攸利亞的勇氣您會收到：\n\n"}
MultiLanguageQuestData['tw'][39775] = {title = "風鑄爪鉤槍", objective = "這看起來是斯鐸海姆當地的維酷人用來攀爬山脊的爪鉤槍。\n\n這東西可能會派上用場。您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n風鑄爪鉤槍"}
MultiLanguageQuestData['tw'][39776] = {title = "巨蟲", objective = "殺掉納克薩、亞薩司和奚斯特。", description = "在我們後方的雪鬃村，對於這種規模的攻擊來說簡直是毫無防禦。我會在這裡擋住卓格巴的攻擊，爭取時間讓村民撤離。\n\n卓格巴利用巨蟲挖掘地道通往地面，並且部署部隊。\n\n我會讓你率領我的軍隊，帶領他們殺掉巨蟲，切斷敵人的增援。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39777] = {title = "爭取時間", objective = "殺死10個力石卓格巴。", description = "我們需要時間撤離雪鬃村。你可以去對付那些力石卓格巴，削減他們的數量嗎？\n\n我會讓治療者去照顧那些沒辦法戰鬥，無法安全逃脫的人們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39780] = {title = "地底之王", objective = "襲擊『地底之王』達古爾。", description = "雖然我們都警告小孩別跟卓格巴進洞，但梅拉已經追進地底之王的洞窟裡了。\n\n還真是個不聽話的孩子，不過凡人皆有一死，讓我們和她並肩作戰吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "卓格縫製肩甲雷霆之巔肩衛雪盲披肩白浪襯肩雪盲頭盔卓格縫製風帽白浪護盔雷霆之巔巨盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][39781] = {title = "奈薩里奧巢穴：殺死地底之王", objective = "找到卡茲格羅斯之錘。", description = "我會指揮人民清開這堆礫石，直接迎戰達古爾的軍隊。\n\n但這會是一次佯攻。\n\n納瓦羅格提出了一個計畫，我認為應該可行。他知道一處側門，或許可直接通往達古爾所在之處。\n\n集結你的盟軍，從側門進攻吧。在那邪惡生物製造山崩擊垮我們之前，取回卡茲格羅斯之錘。我們會吸引他們的注意力，讓你有機會成功。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n地底之王之拳"}
MultiLanguageQuestData['tw'][39783] = {title = "Battle Pet - Terky", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39786] = {title = "如岩石般冰冷的賭局", objective = "前往石痕峽谷，從岩牙身上取得岩牙的顎骨。", description = "第二個目標是一隻叫作岩牙的石化蜥蜴，就住在附近的河岸。\n\n我在它身上下了重注，要是你能解決它，我保證你也能拿到分紅。\n\n我需要它的下顎當證據。快點，別讓牛頭人先幹掉它！", progress = "解決它了嗎？", completion = "哇。我覺得有天會在河岸看到你的雕像呢。等那些牛頭人回來，你就會收到豐厚的報酬…\n\n你沒發現他們的蹤影，對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39787] = {title = "詐騙賭局", objective = "到風裂丘陵引誘惡羽飛下並擊敗牠，取得惡羽尖喙。", description = "朋友，要不要來打個賭？\n\n那些牛頭人是天角部族的人，他們喜歡稱自己是一流的獵人。我賭他們一定沒辦法殺掉斯鐸海姆體型最龐大的野獸。\n\n如果你搶在他們之前殺掉野獸，我就給你分紅。要嗎？\n\n第一隻是在丘陵築巢的大老鷹。人們都叫它惡羽。你可以用一些肉引誘它，不過它住在很高的地方，所以你需要爪鉤槍才能到達那裡。我記得這裡應該有一把…", progress = "你拿到我的戰利品了嗎？", completion = "你解決它了，是嗎？等那些牛頭人知道了，一定會非常嫉妒！\n\n當然，你必須等到牛頭人回來付完賭注之後，我才能給你分紅。不過在這段時間，我又幫你找了下一個目標。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39788] = {title = "符文之林的復仇", objective = "在符文之林殺死8個骸語符文斧手和8個骸語雕刻師。", description = "骸語氏族…他們墮落了…渴望著力量。\n\n把他們從我的森林中切除…", progress = nil, completion = "把骸語氏族從這片土地上抹除之後，符文之林才能再次平靜。\n\n這是個好的開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39789] = {title = "我們的家產被吃了", objective = "到琥珀之落台地殺死10隻暮皮座狼。", description = "你好，旅行者！歡迎你在我們的營地休息，如果你打算多待一陣子，我有個小小的提議。\n\n如你所見，這片土地一直很眷顧我們，是我們賴以維生的天然寶庫。然而，最近座狼變得十分猖獗，我們的家畜已經快被吃光了。\n\n我無法解決所有的座狼，所以每當你在台地殺死一隻座狼，我就會送你一個小禮物。等你殺掉一些座狼之後，就回來找我。", progress = nil, completion = "喔，嘿！你一定在找在這邊紮營的牛頭人吧。他們要出去一會兒，不過史拿戈和我還在，有問題可以找我們！\n\n你說他們付錢要你去殺座狼？沒問題，朋友！\n\n我身上的金幣不多，不過這些貨物很有價值。自己選吧！", rewards = "您能選擇下列奬勵中的一個：\n\n神秘硬幣無價絲布樣本\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39790] = {title = "煉獄硫磺理論", objective = "將硫磺樣本帶給城底區的馬修‧瑞比斯。\n\n已提供物品：\n", description = "我已經研究過你收集來的研究報告，並提出一個理論。如我們所知，這個世界的礦石都是經歷高壓和環境變遷，長時間演變而來。\n\n但是你送來的煉獄硫磺卻因為惡魔魔法而加快其演變過程，很像是寒冰皇冠的薩鋼。\n\n如果要測試這個理論，我們需要魔法師的協助。\n\n帶著這塊硫磺去找馬修‧瑞比斯，他或許知道如何為它注入新的生命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39791] = {title = "再度安息", objective = "削弱並使用符文之林木枝讓8個受擾的祖先重歸塵土。", description = "我想要請你幫個忙，外來者。\n\n在你經過上古英雄之墓時，你一定會碰上被骸語氏族的惡行驚擾的死者靈魂。必須讓他們回到埋骨的土地中，才能夠得到死後的審判。\n\n拿著這根木枝，它藏著符文之林的精華。引導它的能量進入衰弱的靈魂，就能使其再次安息。", progress = nil, completion = "我看到你帶有符文之林木枝。是你讓祖先們的靈魂安息？\n\n雖然我不清楚你有什麼目的，外來者，但我很感謝你為我的族人所做之事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39792] = {title = "一堆肋排", objective = "前往卓頓林地，從健壯的高原符角牛身上取得8塊多肉的鬃牛肋排。", description = "既然我們還要繼續等下去，不如你去幫我們收集一些食物。那些牛頭人儲備的肉食不多了，所以他們一定很想多儲備一些肉食。\n\n聽說鬃牛肋排是這裡的特產。這裡的野生鬃牛身上根本沒幾兩肉，不過對岸的鬃牛倒是長得又肥又壯。也許你應該過去看看！\n\n別擔心，我相當肯定那邊應該沒有龍啦…", progress = "什麼也比不上肥嫩多肉的鬃牛肋排，對吧？", completion = "喔嘿…又是你！那些鬃牛對你來說當然完全不是問題。因為你畢竟是高大勇猛的英雄！\n\n不過，牛頭人還沒回來。我有點擔心他們是不是遇到什麼事情了。\n\n喔，我還是會收下這些肋排。你想換什麼東西？", rewards = "您能選擇下列奬勵中的一個：\n\n晶瑩剔透的寶石無盡好奇藥劑\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39793] = {title = "只要最好的", objective = "前往納斯洛諦，從銀尾山羊身上取得18束細山羊毛。", description = "話說，你是相當厲害的獵人，對吧？也許你可以幫這些牛頭人一點忙，收集一些罕見的毛皮。等到他們回來，一定會很感謝你！\n\n聽說斯鐸海姆的山羊毛可以織成各式各樣的紡織物。其中以銀尾山羊毛最為罕見。沒記錯的話，那邊的山上就有銀尾山羊。\n\n你何不去收集一些山羊毛？我敢肯定牛頭人一定會花大錢買下！", progress = "記得選品質好的！", completion = "你怎麼跑回來了？\n\n我是說…嘿，你終於回來了！\n\n可惜，牛頭人還沒回來，不過別擔心，我會收下你手上的東西！讓你瞧瞧我收藏的好貨。", rewards = "您能選擇下列奬勵中的一個：\n\n發芽魔豆亮晶晶的碎礦\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39796] = {title = "前往豪斯特沃", objective = "在符文之林與維達哈爾碰面。", description = "你的下一步很明確，你的雙腳知道路。跟隨它們前往豪斯特沃，見證你的命運！\n\n你要找到那棵樹，神秘符文之林的心臟。他會給你指引，還有葉子。", progress = nil, completion = "束縛…扭曲…\n\n骸語氏族…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39799] = {title = "我們的下一步", objective = "選擇第一個攻擊地點。", description = "你注意到環繞在我們身邊的霧氣了嗎？亞榭洛的刺骨寒風為我們提供絕佳掩護，讓燃燒軍團無法察覺我們的動靜！\n\n在這陣濃霧的掩護下，我們得以派出偵察小隊，繪製出相當完整的破碎群島地圖。\n\n選一個我們應該展開攻擊的地點。這次行動當然是由你來擔任先鋒，黯刃騎士團會跟隨你的領導。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39800] = {title = "葛雷邁恩的賭注", objective = "完成葛雷邁恩在天火號上的任務。", description = "天火號已經準備好前往斯鐸海姆。要是我們遭到戰火波及，我需要最好的戰士在前線迎敵。\n\n這也包括你，<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "天火號船員肩鎧第七軍團戰鬥法師裹帶天火號船員護臂天火號工程師腕甲第七軍團戰鬥法師襯肩獅鷲騎士肩墊獅鷲騎士腕輪天火號工程師披肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][39801] = {title = "四分五裂的艦隊", objective = "完成希瓦娜斯的任務，將艦隊帶往斯鐸海姆。", description = "現在萬事俱備，我們隨時都能出航。\n\n我們必須馬上出擊。不要浪費我的時間，否則我就丟下你先出發了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "黑玫瑰襯肩黑玫瑰裹腕懼翼騎士護肩懼翼騎士腕輪黑暗遊俠肩衛黑暗遊俠腕甲亡靈哨兵重肩甲亡靈哨兵護臂您會收到：\n\n"}
MultiLanguageQuestData['tw'][39803] = {title = "試煉繼續", objective = "在瓦迪司陀與哈維碰面。", description = "<在渡鴉的凝視之下，哈維的聲音繼續在你的腦海響起>\n\n聽過骸骨的聲音、才能得到勇氣！\n\n但你必須先做好準備！", progress = nil, completion = "啊，來得正是時候，英雄！我們不能再浪費時間了！\n\n如果你想要成功通過試煉，我們手頭上的工作至關重要！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39804] = {title = "說到骸骨", objective = "協助哈維屠宰麋鹿，並瞭解你的下一個試煉。", description = "你接下來必須面對勇氣試煉，這將會是場艱難的考驗！\n\n但只有笨蛋才會空著肚子上戰場。你是笨蛋嗎，外來者？\n\n不是？那就幫我這個老骨頭一把，宰了麋鹿做晚餐。我來跟你說說石頭、樹木和靈魂的故事。", progress = nil, completion = "我得說，這塊肉切得真漂亮。\n\n嗯，我想你對付骸語族應該沒什麼問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39816] = {title = "勇士：薩沙理安", objective = "歡迎你的新騎士。", description = "死亡領主，我已經找到那個離開的團員。他想重返黯刃騎士團，並希望你能親自見他一面。\n\n<莫格萊尼轉身朝附近的守衛點點頭。>\n\n他很快就會過來。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：薩沙理安"}
MultiLanguageQuestData['tw'][39817] = {title = "硫磺的秘密", objective = "把馬修告訴你的情報轉告蒂格媽媽。", description = "在你幫我收集我要的東西時，我對硫磺做了一些測試。在我引導能量時，它的反應會稍微劇烈一點。需要相當精妙的施法，才能製造出原本的生物。\n\n除非你有一大群惡魔施法者供你驅策，否則不可能重新製造這隻生物。\n\n我要說的只有這些。現在馬上離開，在我的飢餓勝過理智之前，離我越遠越好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39818] = {title = "勇士：納茲格寧姆", objective = "歡迎你的新騎士。", description = "死亡領主，我已經找到那個離開的團員。他想重返黯刃騎士團，並希望你能親自見他一面。\n\n<莫格萊尼轉身朝附近的守衛點點頭。>\n\n他很快就會過來。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：納茲格寧姆"}
MultiLanguageQuestData['tw'][39828] = {title = "Horseman and Guards Shared Criteria", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39829] = {title = "Sleigh and Guards Shared Criteria", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39830] = {title = "地獄火堡壘：獄火與硫磺", objective = "召集隊友，再一次襲擊地獄火堡壘。擊敗阿克蒙德並取回煉獄火寶典。", description = "當卡德加一行人襲擊地獄火堡壘的時候，他們遇到許多指揮惡魔的敵人，但阿克蒙德無疑是它們之中最強大的惡魔。\n\n也許，可以從他的屍體找到一些東西，解開這塊神秘硫磺的最後一個秘密。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技巧：煉獄硫磺"}
MultiLanguageQuestData['tw'][39832] = {title = "計畫與準備", objective = "與『女妖』席厄克希交談。", description = "你的武器比以往更加強大，但還需要更多靈魂，才能發揮真正的潛力。\n\n席厄克希收集了斥候送回的報告，她會告訴你敵人的位置，而他們哀號的靈魂則會進一步強化你的武器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39837] = {title = "失魂落魄", objective = "在黑爾海姆被監禁的維酷人中，找出能幫你逃離此地的人。", description = "這是黑爾海姆，卑賤亡者的國度。在這裡，喪失榮譽的靈魂被迫進行永無休止的無謂戰鬥，不斷追尋榮耀，但永遠得不到。\n\n我們不屬於這裡。\n\n我們得找方法離開。我先到前面偵察 - 你該想辦法釋放幾個被囚禁在此的靈魂。或許有人會有我們需要的答案。", progress = nil, completion = "終於獲得自由了！\n\n我才正在想辦法溜過加爾姆那頭邪惡瘋狗時，就被科瓦迪爾抓起來關到現在了！\n\n我還以為我的命運已定。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39847] = {title = "在這簽名", objective = "簽下帕林教授的合約。", description = "啊，一位銘文師！\n\n你看起來還蠻機靈的，要不要我們兩人攜手合作，探索破碎群島中的無限可能？\n\n(就是在我們腳下的巨大群島。)\n\n不過，要是不跑完所有必要的合法程序，我絕對不同意合作夥伴這種事。幫我簽署這份文件，我們就可以開始談生意了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n軍團銘文學\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39848] = {title = "靈魂買賣", objective = "面對黑爾雅，並要求從黑爾海姆獲釋。", description = "看來你的朋友沒能撐過來。很可惜，但我們得繼續前行。\n\n你得向黑爾雅提出我們的訴求。她是此地的統治者。不是我不願和你一起去，但我的出現只會讓你更難辦事。\n\n完成之後，再和我會面。我先來找找看我那些女盾侍的下落。", progress = nil, completion = "&lt;你起身時，黑爾雅的聲音充斥整個空間。&gt;\n\n沒有我的許可，誰都不許離開黑爾海姆！贏得我的喜悅，我就有可能讓你通過。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39849] = {title = "引路明燈", objective = "在黑爾海姆從血鬚身上取得引路之光。", description = "黑爾雅一定認為沒有人能完成她的挑戰。我們會證明她錯了。\n\n我不確定她做了什麼，但黑爾雅削弱了你的力量。我的女盾侍也遭受同樣的命運，她們都被黑爾雅的手下困住了。\n\n不過，可能有個方法解決。科瓦迪爾船隻上帶了一種與此地緊密相連的特殊燈籠，幫助他們在迷霧中航行。聽說這些燈籠的光線，可以解放被束縛的靈魂。\n\n附近有一艘科瓦迪爾的船隻。看看你能不能在船上找到一盞燈。", progress = "你取得燈籠了嗎？", completion = "看來這正是我們需要的東西。\n\n現在，我們可以為即將到來的戰鬥做準備了。", rewards = "不死劫掠者披氅您能選擇下列奬勵中的一個：\n\n血鬚的徽印\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39850] = {title = "碎魂", objective = "在黑爾海姆找到並釋放意志碎片、力量碎片和勇氣碎片。", description = "我想我們需要仰賴你的武器之力擊敗蓋爾，不過你現在還太虛弱，無法對抗敵人。我們必須取回你失去的靈魂碎片。\n\n黑爾雅為了妨礙你，肯定已經將碎片分散藏在在她國度的各處。如果你能找出它們的下落，用燈籠照耀應該就可以解放它們。\n\n不過，還是要多加小心。黑爾雅一定會重兵看守你的靈魂碎片。", progress = nil, completion = "沒錯，我可以感受到你的力量回復了。\n\n低估你的能耐，黑爾雅一定會後悔莫及。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39851] = {title = "冥界同盟", objective = "在黑爾海姆釋放8名受困的華爾琪拉。", description = "光靠我們的力量或許沒辦法對抗巨獸蓋爾，幸好法爾加幫我們把盟友也一起送進黑爾海姆。\n\n我發現黑爾海姆的元素生物正在折磨其中一些人。你也許會覺得，死者怎麼樣也不可能溺斃，但如果加入黑爾雅的力量，就很難說了。\n\n我沒有拯救他們的力量，不過你有引路之光，或許可以把他們救出來。\n\n找出他們的下落，別讓他們繼續受苦！", progress = nil, completion = "很高興看到女盾侍回到我的身邊。\n\n你今天不但獲得盟友，更獲得我的感激。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39853] = {title = "勝利才是永恆", objective = "在黑爾海姆的永恆戰場擊敗蓋爾。", description = "沒什麼好遲疑的了。攻擊的時機到了。\n\n我們會打倒這頭邪惡巨獸，完成與黑爾雅之間的約定。離開黑爾海姆之路正在等候我們，外來者。\n\n做好準備。", progress = nil, completion = "我們獲勝了。現在，輪到我們領取獎勵。\n\n希望黑爾雅不會想出爾反爾。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39855] = {title = "以命償還", objective = "面對黑爾雅並離開黑爾海姆。", description = "我們完成了與黑爾雅約定的挑戰。現在，我們來看看她會不會信守承諾。\n\n等你準備好之後，我們就前往王座。如果你在這地方還有其他事情待辦，我勸你趕快收拾。\n\n我會配合你的行動，外來者。", progress = nil, completion = "死者竟能從黑爾海姆回歸人世？確實相當驚人。\n\n你證明了自己的價值、通過了這場試煉。\n\n現在，去迎接你的命運吧。前往英靈殿！", rewards = "黑爾海姆引路之光華爾琪拉恩賜詛咒的科瓦迪爾之血黑爾雅的凝視地獄犬核心獄霜稜片咒縛者之鍊可敬的靈魂蓋爾之骨哀嚎之風您會收到：\n\n再生活血"}
MultiLanguageQuestData['tw'][39857] = {title = "永恆宿敵", objective = "向艾雪笛爾回報，告知她黑爾雅的挑戰。", description = "<黑爾雅的聲音在祭壇上方的空中迴盪>\n\n外來者，你說你不屬於此處，不屬於失去榮譽之列，但你的靈魂卻輕易碎裂。我怎麼知道你所說是否屬實？\n\n我不知道，所以你必須證明自己。\n\n前往永恆戰場並面對我的勇士。如果你能夠打倒他，我或許會赦免你。", progress = nil, completion = "你看起來不太對勁。\n\n我猜黑爾雅沒給你好臉色看？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39859] = {title = "吃書羊", objective = "在松岩盆地從吃飽的丘行山羊身上取回艾笛的手稿。", description = "我一直記錄著赫米特的狩獵旅程，從荊棘谷到納葛蘭然後…又到了納葛蘭，將他的偉大探險記載下來，然後化為經典故事傳世。\n\n但我真正嚮往的是打獵，我想要的是開槍，而不是寫字！\n\n赫米特答應我在完成最新的小說後，便教我如何打獵，但這裡的山羊卻吃了我的初稿！\n\n如果不能找到這些手稿，我就沒希望成為一名獵人了。", progress = "我等艾笛的初稿都等了一整天了。\n\n為史上最偉大的獵人寫上幾個字，有這麼難嗎？", completion = "我迫不及待想拿回這些手稿了！虧我之前還在煩惱地精也會有創作障礙嗎？", rewards = "您會收到：\n\n艾笛被墨水弄髒的背袋"}
MultiLanguageQuestData['tw'][39860] = {title = "血之祭儀", objective = "完成血之祭儀。", description = "奧肯‧鐵牛幫你擔保。他在河鬃人中來說算能力不錯。而在相對不確定的擔保之外，你也證明了自己的實力。\n\n在我們允許你在我們領地自由行走前，你必須完成血之祭儀，而祭儀現在已經開始了。如果你成功了，就來找我談話吧 - 雖然我很懷疑你有沒有辦法成功。\n\n進入洞穴深處，擊敗出現的敵人後回來找我。", progress = nil, completion = "感謝你拯救我。我希望現在我們能彼此信任。如果我們想擊敗這些魔化圖騰的人，就必須這樣。", rewards = "雷霆之巔腿甲雪盲裹腿白浪護腿卓格縫製腿甲納瓦羅格的指引石暗徽記鐵牛赴義您會收到：\n\n"}
MultiLanguageQuestData['tw'][39861] = {title = "收尾工作", objective = "與卡薩斯平臺的艾魯丹‧白雲談話，以飛往維爾薩拉。在抵達洛拉希爾後，與瑪法里恩‧怒風談話。", description = "瑪法里恩‧怒風成功抵達維爾薩拉，並已經將該區域整治完畢。看來我們的命運總算開始有轉機！\n\n此時此刻，他正在洛拉希爾等著你。當一切照計畫順利進行時，生命竟是如此美妙。", progress = nil, completion = "願伊露恩與你同在，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39862] = {title = "攻城卜魯", objective = "殺掉『攻城卜魯』歐古爾", description = "巨蟲不喜歡戰鬥和地表，牠們只會乖乖服從主人的命令。\n\n所以呢，在戰爭的時候，先殺蟲的主人。\n\n力石卓格巴從北方發動攻擊，而『攻城卜魯』歐古爾就是控制那些蟲的傢伙。\n\n去把他給殺了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39864] = {title = "斯鐸海姆", objective = "到達拉然的紫羅蘭城塞與納薩諾斯‧凋零者交談。", description = "納薩諾斯‧凋零者，女妖之王的勇士，召你前往達拉然。\n\n他會在紫羅蘭城塞等你。聽起來是有急事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39865] = {title = "A Tiny Scarecrow Costume", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39867] = {title = "此獅非彼獅", objective = "前往松岩盆地，從伊萊亞斯宣稱看過的獅子身上取得戰利品。", description = "我獵捕過許多珍奇異獸，但在偵察盆地的時候，我才第一次看見這樣的獅子。\n\n這頭獅子的琥珀色眼睛直視著我的雙眼，引誘我不斷靠近。這頭掠食者令人著魔的凝視讓人毫無招架之力，直到牠撲了上來，我才驚覺事情不妙。\n\n我向赫米特提過這頭奇妙的獅子，但他卻大肆訕笑了一番。我沒說謊，<name>！這頭獅子真的存在。\n\n如果你找到這頭野獸，將你的狩獵戰利品拿來給我，我有豐厚的獎賞給你。", progress = "當赫米特看到這頭奇妙獅子存在的證據時，看看他還笑不笑得出來！", completion = "所以我是對的！有著琥珀色眼睛的獅子的確存在。\n\n這裡是說好的金幣，這錢真是值得，能證明你是對的，怎麼花都值得嘛！\n\n我會把眼睛留著，但我不會讓剩下的部份白白浪費掉，開動吧！", rewards = "您會收到：\n\n食譜：椒鹽火腿"}
MultiLanguageQuestData['tw'][39869] = {title = "靈魂的代價", objective = "擊敗黑爾雅，釋放華爾拉亞戰士。", description = "[PH] As foretold, you have arrived... Helya is foolish to think I'll let her ferry me into Helheim. Odyn has already smiled upon me, my soul belongs in Valhallas. \n\nMake no mistake, I am not a prisoner. Before my death Odyn appeared to me in the form of a raven. He praised my battles in life and gave me a quest no vrykul could refuse. The Helerjar arrived... and I let them slay me.\n\nPrisoner-- nay, I am a liberator, sent by Odyn to free the souls of Valarjar.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39873] = {title = "我有不好的預感", objective = "調查納瓦羅格的疑慮。", description = "你沒有理由相信我，因為我的弟兄們在達古爾領導下，被權力沖昏頭。\n\n但我想請你調查一件事情。我有預感高嶺將發生不好的事，托洛卡與他的血圖騰部族將是罪魁禍首。\n\n如果你不相信我，就到北端的絕崖自己看看吧。", progress = nil, completion = "&lt;牢籠是空的。納瓦羅格不見了。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39874] = {title = "幾個迷人的夜晚", objective = "到達拉然附魔商店和裡面的伊爾汀‧悲矛交談。", description = "歡迎！回到達拉然看到熟面孔真是令人高興。你可能還記得北裂境的伊爾汀、凡妮莎、還有我。\n\n大法師星歌者是這家店的負責人，但他目前因祈倫托的事外出。他人不錯…通常是啦。\n\n你來得正是時候。我們遇到一個問題，希望在大法師回來前盡快解決。你願意伸出援手嗎？", progress = nil, completion = "我很高興你來了，&lt;name&gt;。在這種時候，我們真的需要另一位附魔師在店裡。", rewards = "您會學到：\n\n軍團附魔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39875] = {title = "最後一批", objective = "為伊爾汀製作2張附魔戒指 - 應變之言皮紙。你可以透過雕銘師或拍賣行取得皮紙。", description = "就像你看到的，<name>。為了對抗燃燒軍團，我們很認真地在生產附魔產品。既然你在這裡的話，我們真的需要你來幫忙處理一筆訂單。\n\n如果你有辦法的話，去拿一些皮紙，在上面附魔臨機應變屬性。我會把公式教給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39876] = {title = "協助惡魔獵人", objective = "把皮紙送到捷斯‧暗織者手中。\n\n已提供物品：\n", description = "趁我在處理這份訂單時，如果你能幫我把這批皮紙送給捷斯‧暗織者，那就幫了我一個大忙。他在艾蘇納。他和其他惡魔獵人在那裡對抗燃燒軍團好一段時間了，可能急需這些皮紙。\n\n謝謝你，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39877] = {title = "大家都有一份", objective = "在伊利達瑞陣地對6個惡魔獵人使用附魔皮紙。", description = "我們需要你的幫忙，<name>。用上了這些附魔皮紙之後，某些惡魔獵人會得到莫大的優勢。\n\n你拿去一些，剩下的我會交給另一個士兵去發。\n\n我的惡魔獵人恐怕不會停下來等你，所以你得試著在戰鬥中幫他們附魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39878] = {title = "雷鳴之擊", objective = "在雷霆圖騰與古隆‧雙尾交談。", description = "我可能在高嶺找到了新附魔的來源。雷霆圖騰牛頭人會指揮靈魂將強大的力量灌注在物品上。\n\n去找一位叫做雙尾的附魔師，看看他是否能與我們分享他的附魔知識。\n\n牛頭人應該是以樂於分享聞名的吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39879] = {title = "強如大地", objective = "擊敗暴怒的琥珀裂石怪，收集\n8塊琥珀裂石水晶，然後把水晶帶給雷霆圖騰的古隆。", description = "在這世上有許多不同類型的靈魂，<name>。有些行善，有些為惡。\n\n它們全都會和不同的材料共振，我們可以利用這個特性來替裝甲附魔。其中一種材料就是琥珀裂石怪的水晶。\n\n它們是從土地中產生的暴戾怪物，最近還被卓格巴騷擾。但無論有沒有遭到騷擾，琥珀裂石怪身上的水晶對我的族人來說，都是附魔的絕佳材料。幫我帶來一些，我就讓你見識一下這東西的妙用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39880] = {title = "禁止浪費", objective = "前往水晶裂隙搜尋廢棄的盔甲。分解盔甲並帶回15個雷霆細塵給古隆。", description = "在收集琥珀裂石怪水晶的同時，你可能會發現死去勇戰者身上的附魔護甲。琥珀裂石怪不會在意那些東西，但我們可不會白白浪費這些東西。\n\n我想讓你去取回勇戰者的護甲，然後把它們分解成材料。\n\n把那些材料帶回來給我，我的部族可以用來替新的護甲附魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39881] = {title = "古怪的附魔", objective = "在維爾薩拉的伊露恩神殿附近尋找娜拉彌雅。", description = "在這片大地上找到的新種類魔塵跟水晶都太讓人入迷了！我敢說你已經猜到了。我相信可以把它們用在更多護甲上，讓這些材料的實用性更上層樓。\n\n我想要你再出門一趟，去維爾薩拉找一位林精談話。她顯然應該能提點我們一些肩甲附魔的訣竅。\n\n她的名字是娜拉彌雅。你可以在伊露恩神殿附近找到她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39882] = {title = "暗心灌木林：光芒散盡", objective = "去暗心灌木林殺死大德魯伊葛萊達利斯，然後取回娜拉彌雅的附魔書。", description = "我曾教過夜精靈如何附魔護甲，來強化他們的力量，對抗這片土地的邪惡。其中有個精靈我特別喜歡，\n\n他叫做大德魯伊葛萊達利斯。他現在在暗心灌木林裡，打算用可怕的荒疫來破壞這個世界。\n\n我之前把附魔書借給他研究了，但現在他背叛大家，我很想把書拿回來。\n\n這個任務就交給你了，附魔師。把書拿回來給我。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n公式：拾荒者恩澤\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39883] = {title = "披上傳統", objective = "把古隆的日記帶給達拉然的奈爾桑尼斯。", description = "你知道雷霆圖騰牛頭人的處事方式了…與靈魂交談、從土地採集，不浪費東西。他們是你在破碎群島征途上的重要助力。\n\n來，把這本日記帶回去給你的附魔師朋友。其中包含了我傳授給你的課程。\n\n或許它也能對擊敗燃燒軍團這個偉大目標有點貢獻。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n公式列表：披風附魔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39884] = {title = "失去價值", objective = "殺死玄鴉堡內的夜精靈並收集他們的附魔黑羽符印。分解符印並帶回8份玄鴉細塵給娜拉彌雅，以證明他們的敗北。", description = "玄鴉堡的精靈們已經決定背叛我們。他們待在堡壘中，攻擊任何試圖進入的外來者。\n\n我不能容忍這種行為…尤其好幾年來他們還接受了我族人與這片土地上其他種族的幫助。\n\n我想要你幫我一個忙，<name>。奪下他們的附魔符印並將它們化為塵埃。將這些塵埃帶回來給我以證明你的行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39889] = {title = "誤入歧途", objective = "前往位在維爾薩拉的玄鴉堡，殺死崔蘭‧破盾者與斯塔麗絲‧強弓。", description = "夜精靈不笨，但玄鴉堡的精靈卻只會盲目地追隨他們的領導者。如果他們漠視眼前的問題，那絕對是領導者的錯。\n\n我知道其中兩位領導者，當我的家園慘遭入侵時，這兩位指揮官仍要求部隊冷眼旁觀。\n\n去玄鴉堡殺死崔蘭‧破盾者與斯塔麗絲‧強弓。讓他們的死成為警惕，警告那些明明擁有力量伸出援手，卻隔岸觀火的傢伙們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39891] = {title = "受到詛咒，但很方便", objective = "去艾蘇納的崩裂之殿找尋附魔師伊蘭雅。", description = "我需要你立即返回艾蘇納，<name>。我稍早才聽說有一位在崩裂之殿的女巫師熟知許多稀有的附魔。\n\n去找她並看看你能學到些什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39896] = {title = "DEPRECATED: The Ringer", objective = "完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][39903] = {title = "附魔之家", objective = "在斯鐸海姆調查堤格麗的家。", description = "我對破碎群島的瞭解越多，越覺得這裡是奇蹟之地。\n\n伊爾汀和我剛剛在討論一個來自斯鐸海姆的傳言，裡面提到維酷女附魔師堤格麗，曾經住在斯鐸海姆。聽說那個地方保存得十分完整，而她的附魔潛力無窮，一直在現在還有效！\n\n去她家裡調查一下或許能發現珍貴的知識，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39904] = {title = "英靈殿：女附魔師的復仇", objective = "從英靈殿取得堤格麗的附魔棒，帶回斯鐸海姆交給她。", description = "許多世紀以來，甚至在我死後，我都有能力製造可靠耐用的附魔。但自從某位貪婪的國王偷走了我的附魔棒，我就很難維持那所剩無幾的魔法了。\n\n如果你能從神御之王那裡奪回我的附魔棒，我會給你應得的獎賞。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n公式：魔法筆\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39905] = {title = "可靠的附魔", objective = "到達拉然找奈爾桑尼斯。", description = "雖然這裡依然需要你的有力支援，但你在達拉然的導師正在找你。\n\n我想再次感謝你為我們所作的一切。我的獵人們已經知道，他們在這場戰役中並不孤單。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n公式列表：戒指附魔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39906] = {title = "預備戰鬥", objective = "為埃林布萊茲製作1張附魔披風 - 力量之言皮紙、1張附魔戒指 - 致命之言皮紙及1張附魔戒指 - 精通之言皮紙。", description = "<class>，想要我的印記，你必須先在戰鬥中證明自己。有一隻我想除掉的納迦，但我的實力不足以殺死牠。\n\n在我們一起戰鬥之前，我需要你以附魔師的身分伸出援手，讓我變得更強。我知道你有不少的附魔配方在身上。\n\n幫我製作一些，這樣我才能再度變強，對世界有所貢獻。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39907] = {title = "精靈附魔", objective = "回去達拉然找奈爾桑尼斯。", description = "你取得我最信賴的夥伴的印記了，而且你也把我的愛帶了回來。\n\n我能遇見你真是太幸運了，<name>。\n\n現在回去找你的師父吧，讓他知道你學到了什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39910] = {title = "德魯伊的情義", objective = "尋找梅洛斯的掌形塑像、爪形塑像及月光塑像，並將它們帶回崩裂之殿給他。", description = "為了要給予你我的印記，<class>，我必須要先變強壯，才有辦法隨時支援你。\n\n我的塑像在納薩拉斯遺跡中休眠著。像我說的，我沒有強壯到可以自己去取得它們。\n\n但我能感覺出你很強，強大到足以解決那些破壞我的家園，而且毫無榮譽感的納迦。\n\n找到我的塑像並把它們帶回來給我。事後我就會給予你我的印記。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n曦風的附魔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39914] = {title = "哨兵的最後職責", objective = "殺死深淵指揮官埃克西斯。完成後回到崩裂之殿找埃林布萊茲。", description = "現在我更強了，是時候測試你我的實力了。我稍早提過，有個我想殺掉的強大的納迦。\n\n他的名字是深淵指揮官埃克西斯。屠殺我眾多族人的罪魁禍首就是他，後來他藏匿起來在暗中指揮軍隊。\n\n最後我總算發現他洞窟中的藏身處，就在此處的東方。讓我們為我死去的弟兄與姐妹向他復仇。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n埃林布萊茲的附魔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39916] = {title = "轉向的背叛", objective = "擊敗魔炎入口的惡魔。拿取它們的魔覆符文並將它們分解為5份邪訛之塵。完成後，回到你遇見墮落女祭司的地方。", description = "伊蘭雅女士還記得我？\n\n<薩特低頭不語，拭去了一滴眼淚。>\n\n我在一萬年前做了一個愚蠢的交易。在我得知女王和軍團結盟之後，我背叛了我的良心，加入她的麾下。我變成了這個怪物般的模樣，最後在與凡人的爭戰中消亡。\n\n現在燃燒軍團再臨，但我只能以虛弱的靈魂狀態留存。讓我附在你身上，殺死前方的惡魔吧。奪走他們的惡魔符文，讓他們灰飛煙滅。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39918] = {title = "缺席的女祭司", objective = "回到艾蘇納的崩裂之殿找附魔師伊蘭雅。", description = "在我背叛後，我從沒想過自己還能再次看著我的摯愛。但多虧你，<name>，我至少能有機會回來。\n\n去跟伊蘭雅女士談話吧，我會讓她知道，你有資格獲得我的印記。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n德蕾安娜的附魔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39920] = {title = "於青翼之上", objective = "到艾蘇納的蒼翼之憩去和卡彌拉交談。", description = "我有些好消息要告訴你，<name>。伊爾汀和我遠行到艾蘇納，並和蒼翼之憩的藍龍碰了面。\n\n其中一頭叫卡彌拉的龍是附魔師，他表示很願意和你合作，讓我們的附魔更加完美。我明白你在和那些精靈工作時受了一肚子氣，不過如果你願意回來，卡彌拉會和你合作愉快的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39921] = {title = "奈薩里奧巢穴：青色之杖", objective = "從奈薩里奧巢穴的『地底之王』達古爾身上取得天岩魔棒，從石岩之心的歐茲魯克身上取得閃耀的西風石，然後從通靈學院取得一堆古代阿坎納塵。", description = "不過在我們開始之前，必須請你幫個小忙。不瞞你說，這很難啟齒，但如果我們想合作，這件事便非得完成。\n\n因為我是被召喚來這裡的，沒有機會收拾東西。最麻煩的是，我沒帶附魔棒。\n\n與其回去拿附魔棒，重做一把新的應該比較簡單。\n\n我們需要…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39923] = {title = "深入核心", objective = "取得歐德斯、歐瑞爾、歐莫爾、以及歐里森的力量核心。當你取得四個力量核心時，將它們帶回給卡彌拉。", description = "你現在會的戒指附魔很棒，但我還知道更棒的。也就是說，我知道更適合附魔在戒指上的強大法術。\n\n根據傳說，有四具核心灌注了魔法的傀儡。這些傀儡現在在蘇拉瑪爾街道各處巡行。\n\n如果你能和一些好友一同擊敗這些傀儡，就能把它們的核心拿來給我們研究。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n公式列表：進階戒指附魔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39931] = {title = "輾碎藥草", objective = "取得20個玫瑰色顏料和2個灰黃色顏料。顏料可透過研磨草藥取得。", description = "現在我們之間不用那麼拘泥了，我們來做點真正有用的事。\n\n在我們腳下的群島上生長著全新而且充滿異國風情的藥草，是我們接下來要實驗的目標。\n\n我想請你採些藥草回來，並從中製造出一些新顏料。顏料夠用之後回來我這邊，我們看看你能不能想出什麼點子。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：職業雕紋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39932] = {title = "魚墨水", objective = "取得5份馬克拉納油、5份盤恨納迦油和5份鹽目油，然後結合成魚顏料。", description = "你知道嗎，草藥不是獲得墨水的唯一方式，其他原料也能製成墨水。\n\n話說！我一直千方百計想做出自己專屬的暗月卡。要是那些糟糕的馬戲團員辦得到，我沒理由辦不到。\n\n我們需要一些特殊材料。前往艾蘇納，幫我收集一些油液，然後研磨成合適的墨水。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39933] = {title = "卡牌專家", objective = "在戲法旅舍收集10張爐石戰記卡牌。", description = "我們已經有顏料，但還需要一種原料。\n\n戲法旅舍的訪客常會玩卡牌遊戲，有時候，他們會弄丟卡牌。去看看你能不能找到一些玩家在牌局之間弄掉的散牌。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：預言塔羅\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39934] = {title = "我們的新盟友", objective = "前往艾蘇納，找到『噬魂者』艾萊莉。", description = "你看到那些惡魔獵人了嗎？我不相信他們會全心全意幫助我們，不過他們既然已經加入，我們就要善用這股力量。\n\n你也知道，大家都需要雕紋。\n\n去看看你能從他們身上發現什麼。艾蘇納是最適合新手展開旅程的地方。\n\n我已經對你傾囊相授，相信你一定能活用所學，創造你專屬的配方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39935] = {title = "力量的代價", objective = "在伊利達瑞陣地殺死15個惡魔。", description = "你想知道身為惡魔獵人是什麼滋味嗎？這可能需要花一點時間。\n\n首先，你可以跟我們一起戰鬥。觀察我們在對抗惡魔的時候，如何運用它們的力量反過來對付它們。\n\n等你完成後，回來找我。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：魔觸靈魂雕紋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39936] = {title = "身體銘文學", objective = "到札克赫納地脈遺跡去找巴里克‧風暴行者。", description = "身為惡魔獵人，我們必須控制心中的黑暗，否則就會反過來被黑暗控制，成為惡魔的一員。這也是我們在皮膚上刻下印記的原因。\n\n在北方，有一位名叫巴里克‧風暴行者的惡魔獵人正準備強化他的印記。去找他，向他學習抑制心中惡魔的方法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39937] = {title = "相剋的能量", objective = "到札克赫納地脈遺跡，從夜落精靈和凋萎者身上收集10份地脈之塵，然後混合成地脈顏料。", description = "<name>，作為惡魔獵人，我們需要致力保持平衡。而為了保持平衡，我們在自己身上注入性質相反的力量。\n\n秘法能量與魔化能量相剋，所以我們在身體紋上秘法符文來抑制魔化能量。\n\n你是雕銘師，對吧？那麼，你應該有辦法從上方遺跡生物身上取得地脈之塵，然後混出合適的地脈顏料。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39938] = {title = "束縛內在的惡魔", objective = "協助巴里克完成儀式。", description = "現在我們已經取得所有必要的材料，可以開始進行儀式了。\n\n我會告訴你如何協助我。在我下達指示時你能不能遵循至關重要，否則儀式必定失敗。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：鵝黃之翼雕紋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39939] = {title = "雕銘知識", objective = "在艾蘇納的魔炎入口附近找到札莉雅‧影心。", description = "我們不只是和惡魔作戰那麼單純，<name>。我們必須觀察他們。\n\n我最厲害惡魔獵人之一，札莉雅‧影心，目前正在魔炎入口收集惡魔的情資。\n\n去找她。她會把該區域的惡魔進攻狀況都告訴你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39940] = {title = "魔化能量符文", objective = "研究8個魔化能量符文。", description = "仔細觀察，雕銘師，你就能學到東西。隨著惡魔散佈到整個地區，聰明人就會將符文銘刻在地面上。魔化污染已經遍佈整片山坡，但腐化最嚴重的地方卻是在這些符文周圍，任何純淨之物都無法在這附近存活。\n\n研究這些符文。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：劈啪火焰雕紋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39941] = {title = "操控至上", objective = "摧毀保護監督者菲洛拉斯的水晶，然後殺死他。", description = "我們惡魔獵人犧牲雙眼，是為了能更清楚地看見惡魔，這對我們來說是種儀式。\n\n底下有個惡魔指揮官，就藏身在他的部隊之中，一般人的眼睛卻看不見。他負責維持混沌，正如我們必須控制自身的混沌。\n\n摧毀他的守護水晶，再殺了他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n玫瑰色顏料"}
MultiLanguageQuestData['tw'][39942] = {title = "紫地根水晶", objective = "將紫地根水晶交給達拉然的帕林教授。\n\n已提供物品：\n", description = "<大部分的紫地根草在花朵正中央都有結晶纖維，但這朵的結晶發育特別良好。>\n\n<帕林教授絕對會對這很感興趣的。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：大量研磨紫地根草\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39943] = {title = "狩獵重擔", objective = "向帕林教授回報。", description = "我已經沒有其他東西能教給你了，雕銘師。伊利達瑞永遠在背後支持你對抗燃燒軍團。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：破損之翼雕紋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39944] = {title = "神秘訊息", objective = "把石板交給斯鐸海姆的尼可洛‧迅熔。", description = "考古學商店的那位女士剛剛留下了一些需要解譯的石板。再怎麼蠢的人都知道那是古維酷語，不過我把我的字典借給我的學生了，所以我現在沒辦法解譯石板。\n\n他的名字是尼可洛‧迅熔，人就在斯鐸海姆。告訴他，如果無法解譯石板，我就撤銷他的學徒資格。\n\n就是這樣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39945] = {title = "廢墟中的符文", objective = "在豪斯特沃收集10個遠古維酷符文石板。", description = "不幸的是，帕林的字典並不完整。據我們的瞭解，這邊有太多符號根本無法解譯。\n\n看來，我們必須下到維酷人稱之為豪斯特沃的地方，收集更多石版。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39946] = {title = "欲善其事，先利其器", objective = "取得一把符文骨刃。", description = "從我目前解譯的一部份內容看來，我知道這些石板是用一種特殊雕刻工具製作的。\n\n如果我們能取得這樣的工具，再加上完整的字典，我們就可以輕易製作出我們自己的石板。\n\n它們也可以用來證明，我對他們的語言解譯正確無誤。\n\n幫我取回一件這樣的工具，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39947] = {title = "沒那麼複雜？", objective = "協助尼可洛製作符文石板。", description = "好吧，我相信我已經把遺失的條目編進字典了。而且我們也拿到大砍刀…呃，小刀了。\n\n現在只剩下製作我們自己的石板，並查證這些石板的其他疑點。\n\n我相信它們不是只用來刻字，而是某種魔法裝置。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39948] = {title = "墨水橫流", objective = "將合約送給城底區的萊森。", description = "<name>，我需要你馬上幫我送個貨。\n\n沒錯，我現在已經瞭解這麼瑣碎的事情實在不適合你做…但我現在真的在忙，而且你和我都很清楚，我的時間要比你重要得多。\n\n將這些合約送給萊森，達拉然城底區的守衛隊長。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39949] = {title = "優秀雕銘師的過往", objective = "殺死墨腐並取得遭竊的暗影紅寶石。", description = "這些下水道是…某些無法承受正常達拉然生活重壓的人的「住所」。例如，這份合約的當事人。\n\n他的名字是墨腐。他曾經也是像你一樣的雕銘師，但是教授給他的壓力把他逼瘋了。\n\n<萊森把合約遞給你。>\n\n合約上寫著他偷了卡地亞珠寶公司的珠寶。把珠寶帶回來給我。他身上的其他東西都是你的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39950] = {title = "一枚奇怪的飾品", objective = "將這張破爛的塔羅牌交給帕林教授。", description = "等等，<name>，在你離開之前…你沒注意到這個嗎？\n\n<萊森從珠寶下方撕下一小塊紙片。>\n\n這不是失竊物品。看起來像是某種卡片。一定是雕銘師才懂的東西。\n\n這也許會對你有一些用處。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：預言塔羅\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39951] = {title = "玫紅精華", objective = "將玫紅精華交給達拉然的帕林教授。\n\n已提供物品：\n", description = "<從這朵花中研磨出的色素品質異常地高。>\n\n<帕林教授絕對會對這很感興趣的。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：大量研磨星輝玫瑰\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39952] = {title = "蠟黃精華", objective = "將蠟黃精華交給達拉然的帕林教授。\n\n已提供物品：\n", description = "<魔草化為一種濃稠、凝結的顏料。>雖然所有魔草產生的顏料看起來都有點危險，但這批更是閃耀著一種邪惡的能量。\n\n<帕林教授絕對會對這很感興趣的。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：大量研磨魔草\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39953] = {title = "英靈殿：勇者預言", objective = "到英靈殿取回5個華爾拉亞符印。", description = "我想該是另一次校外教學的時間了，<name>。前往英靈殿吧！\n\n華爾拉亞精通所有種類的符文設計。或許我們可以找到對新配方有用的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39954] = {title = "大量研磨技術", objective = "在達拉然的銘文學商店找到米勒的精湛技藝手冊。", description = "一些我之前的學生對於研磨曾經發表過一些不滿的意見。他們認為過程太「反覆」、「無腦」，甚至是「痛苦」。他們難道對於長久流傳的銘文學傳統毫無尊敬之情嗎？\n\n我想你也是他們的一份子，我猜對了嗎？非常好。你目前為止是一位很好的學生，所以我想這不是什麼大問題。\n\n我有一本關於大量研磨的書在這家店的某處。找到它，它就是你的了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：大量研磨伊瑟拉種子\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39955] = {title = "錯綜複雜", objective = "前往鐵爐堡，尋找威廉‧沙士比亞。", description = "好吧，我不否認。那本煽情羅曼史小說是我的。\n\n我只是為了研究筆跡而讀的，我向你保證！他筆下那樣繾綣的「B」…還有如此豐腴的「D」！\n\n事實上…你可能會從筆跡學課程中學習到不少。這些書的作者是威廉‧沙士比亞。我相信可以在鐵爐堡的圖書館找到他。\n\n別再讀了，學生。你可以下課了。還有，把我的書還給我！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39956] = {title = "經典永流傳", objective = "把未完成的煽情羅曼史小說完成。", description = "我失去我的熱情了，抄寫員。我就是無法再融入角色們的思維了。\n\n看一眼桌上那本還沒完成的書吧。看來我就是沒辦法完成它。或許由你來完成還容易一些。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：煽情羅曼史小說\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39957] = {title = "惡魔墨水", objective = "收集25瓶魔魂之血以及1份薩格拉斯之血，並將它們混合為魔魂墨水。", description = "這些符印可以做出一張很棒的新塔羅牌。事實上，這塔羅牌會相當強大。我們只要以耐用的墨水來把它們書寫上去就行了。\n\n很幸運地，我有你這種擅長找尋稀有物品的學生。\n\n在這個計畫中，我需要惡魔之血混合成的墨水。魔魂堡惡魔的鮮血很適合當作基礎。當然，你也需要用到薩格拉斯之血。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：燃燒軍團暗月卡\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39958] = {title = "僅止於皮", objective = "收集20張石皮皮革和5片雷鱗。如果你不是剝皮師，可以在拍賣場或是向別的玩家購買。", description = "歡迎你，<name>。很榮幸可以跟你這樣厲害的人共事。\n\n為了展開我們之間的合作，我們必須先收集一些材料。\n\n破碎群島上有許多奇異的生物，拿它們身上的毛皮來實驗，一定非常有趣。我們也需要用來製作鎖甲的鱗片。\n\n請去收集一些材料，這樣才能開始動工。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n軍團製皮\n\n您還會收到：\n\n石皮皮革雷鱗"}
MultiLanguageQuestData['tw'][39959] = {title = "錯綜複雜", objective = "前往幽暗城，尋找法蘭西斯‧烤培根。", description = "好吧，我不否認。那本煽情羅曼史小說是我的。\n\n我只是為了研究筆跡而讀的，我向你保證！他筆下那樣繾綣的「B」…還有如此豐腴的「D」！\n\n事實上…你可能會從筆跡學課程中學習到不少。這些書的作者是法蘭西斯‧烤培根。我相信可以在幽暗城的圖書館找到他。\n\n別再讀了，學生。你可以下課了。還有，把我的書還給我！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39960] = {title = "經典永流傳", objective = "把未完成的煽情羅曼史小說完成。", description = "我失去我的熱情了，抄寫員。我就是無法再融入角色們的思維了。\n\n看一眼桌上那本還沒完成的書吧。我好像就是沒辦法完成它。或許這對你來說還容易一些。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：煽情羅曼史小說\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39961] = {title = "尷尬的發現", objective = "把煽情羅曼史小說交給帕林教授", description = "這看起來一點都不像是銘文學教科書…還比較像是煽情羅曼史小說。這些書頁上只寫滿了廉價的激情故事，\n\n在銘文學研究中有可能派上用場嗎？但不論有沒有用，你都得面對帕林教授。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39962] = {title = "歐庫納的麻煩", objective = "尋找歐庫納‧長牙。", description = "<你打開了瓶子，發現裡面有封信。>\n\n救命！我需要有人幫我…不過可不是誰都好，我需要一名勇士！我總算逃離了歐宣諾王子的魔掌，沒想到卻被他的父親，深鬍子大王追殺。\n\n我正享受自由的時光，決定要去釣魚的時候，卻被那個巨人攻擊。我在群島上不斷的逃跑，盡力躲避那個怪物，自從…，如果有人看到這封信，請幫助我！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39983] = {title = "胡恩之戰 - 到臨", objective = "擊敗25個燃燒軍團成員。", description = "胡恩‧高嶺是我們成為一個強大部族的原因。他戰勝了威脅我們生存的燃燒軍團，並統一了許多分散的部族。\n\n體驗他的故事，你才能明白為什麼他的名字可以讓膽小的人不再畏懼，並使無懼之人也為之驚懼。", progress = nil, completion = "[操著不流利的通用語]有羽毛的說你會來，昂亞克不期待。感謝你牛頭人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39984] = {title = "過去的遺跡", objective = "找到線索以獲知蔑潮港的命運。", description = "<這篇日誌看來倉促寫下。>\n\n我不清楚我的村子怎麼了。自從迷霧籠罩碼頭後，我的族人就變了樣。\n\n有些人變得暴力又野蠻，有些人則徹底發瘋。許多人冒險進入霧中，無一歸還。\n\n在這種時候，我們通常可以仰賴我們的領導者，塔本統領。但他也被迷霧帶走了。\n\n我不知道我會有什麼下場。現在，我只能待在我的崗位上保持警戒。", progress = nil, completion = "這個海灣的迷霧不只會使船上的木頭腐爛，還會腐化船員的靈魂。\n\n不過看來你已經發現這件事了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39985] = {title = "卡德加的發現", objective = "到達拉然與大法師卡德加交談。", description = "勇士！請立即前來紫羅蘭城塞。\n\n我有個重要的發現，想要在六法議會面前告訴你。", progress = nil, completion = "謝謝你趕過來，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39986] = {title = "魔法訊息", objective = "調查達拉然的秘法異常體。", description = "過去一萬年以來，精靈都市蘇拉瑪爾都被魔法屏障保護著，就像過去的達拉然一樣。\n\n那道屏障失效了。\n\n自此之後，魔法能源的波動就從都市內不斷地湧出，彷彿池中的漣漪。我從這些波動中發現了不尋常的訊息。\n\n有一道法術，被加密在混沌之中。\n\n我在這裡重現了那道法術。這法術並不危險，但是…我對它的用途毫無頭緒！", progress = nil, completion = "一道魔法訊息，居然能夠從燃燒軍團的監視下傳出…非常聰明。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39987] = {title = "秘法的殘影", objective = "使用卡德加的魔杖尋找秘法殘影，並找到首席秘法師薩莉瑟拉。", description = "夜裔會是對抗燃燒軍團的強力盟友。可以的話，我們必須幫助薩莉瑟拉。\n\n我們應該能夠透過追蹤秘法殘影找到她，我就是用這個方法發現她的求救訊號。\n\n我可以把你傳送到她留下那個訊息的位置附近。從這裡開始，你必須搜索每一丁點秘法能量中的漣漪。\n\n我的手杖能夠幫上忙。跟著它產生的火花，它們應該會帶你前往薩莉瑟拉使用魔法的地方。", progress = nil, completion = "是個外地人…\n\n你收到了我的信息？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39988] = {title = "胡恩之戰 - 怒風", objective = "和瑪法里恩碰面。", description = "<艾切羅摩擦著你的手，然後轉過身子。它面向南方，看向你的背後。>", progress = nil, completion = "你帶著艾切羅，還有…這是什麼？塞納留斯的祝福？！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39990] = {title = "胡恩之戰 - 增援", objective = "保護瑪法里恩。", description = "塞納留斯冒了很大的風險來到此地，只為了賜福於你。他看出了你的潛力，並且選擇你成為這場戰鬥的勇士。我稍後會和你談論這件事。這真的是十分罕見的贈禮。\n\n但現在我需要你的幫助，胡恩‧高嶺。我必須完成我的咒文，才能讓林精從迷霧之外進入此地協助我們。", progress = nil, completion = "儀式完成了。現在援軍可以穿過傳送門，協助抵抗惡魔大軍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][39992] = {title = "胡恩之戰 - 納斯雷茲姆", objective = "擊敗提克迪奧斯。", description = "我在這邊編組部隊，忙得不可開交，而且還要計劃著即將到來的戰鬥。\n\n雖然我很想親手殺掉驚懼領主提克迪奧斯，但我願意把這個榮耀交到你的手中，胡恩‧高嶺。", progress = nil, completion = "你現在知道胡恩的厲害了吧？他一統部族，擊敗了可怕的強敵。", rewards = "高嶺強擊斗篷您能選擇下列奬勵中的一個：\n\n瑪洛尼之擇指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][39998] = {title = "擊退蔑潮維酷人", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][40000] = {title = "真正的獵人", objective = "獵殺日霜林地的骨喙隼鷹，證明你有當獵人的資格。", description = "我不知道為何赫米特會跟拉傑一同狩獵。他的裝置根本不可靠！\n\n一名真正的獵人不需要工具就能狩獵。他們依賴的是直覺、技巧與眼明手快。\n\n所以你敢說你有真正獵人的技巧嗎？<name>。最好不只是說說，證明給我看。\n\n殺掉幾隻在附近草原繞的骨喙隼鷹。", progress = nil, completion = "這才是真正獵人的作為。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40001] = {title = "敲響英靈之門", objective = "在怒魔營地找到維瑟。", description = "你命中注定要來到英靈殿，卻有人捷足先登。神御之王的惡魔與邪惡玷污了通往英靈殿的台階。\n\n你的龍族盟友已前來防禦大殿，但他們需要你的協助。風暴龍的領導者，稱為維瑟的龍，被維酷人抓住了。\n\n救出你的龍族朋友，勇士，將怒魔維酷掃出英靈之門！", progress = nil, completion = "我…有看錯嗎？\n\n一片敵人之中…竟出現友善的面孔？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40002] = {title = "熟悉的命運", objective = "從德拉瓦克身上取得獄卒裂片，並將維瑟從牢籠中釋放出來。", description = "我們前來防衛英靈殿…而我卻從天上被打下來…\n\n我無法自己掙脫束縛。找出製作這個牢籠的獄卒…\n\n放我自由，朋友…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40003] = {title = "消波阻浪", objective = "使用風鑄號角在英靈之門摧毀三個魔縛傳送門。", description = "斯寇瓦德和他的惡魔盟友褻瀆了英靈之門。他部隊中扭曲的秘法師召喚了傳送門，從荒蕪世界運來無數的惡魔援軍。\n\n如果我們要阻止這股浪潮，就得摧毀這些傳送門。\n\n我會集結我的友軍。帶著這個號角，找到傳送門的時候立即通知我們，我們就從空中出擊！", progress = nil, completion = "我無法理解，明明傳送門都關閉了，為什麼斯寇瓦德的惡魔部隊還能一波接一波攻擊大門！\n\n我們一定要查明他們是從什麼地方冒出來的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40004] = {title = "滅敵大將", objective = "在英靈之門擊敗加薩雷斯、卡魯亞斯、莫亞格和拉瓦瑟斯。", description = "神御之王任命了一些威力強大的惡魔，做為他的副手、領導惡魔兵力。如果我們想要結束他的攻勢，就得解決掉這些領導者。\n\n這些惡魔太過強大，一般凡人難以匹敵。但現在斯鐸海姆的力量任你支配，他們不是你的對手。\n\n打倒他們，並粉碎斯寇瓦德的攻勢！", progress = nil, completion = "打倒了惡魔領導者之後，神御之王的部隊必會潰散。\n\n不過，戰爭仍未結束。只要惡魔繼續攻擊大門，斯鐸海姆就算不上安全。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40005] = {title = "斯鐸海姆的救贖", objective = "在英靈之門擊敗神御之王斯寇瓦德。", description = "雖然底下的傳送門都摧毀了，但還有其他的。英靈之門頂端仍有神御之王親自召喚的傳送門，而各式各樣的惡魔正從那裡湧入我們的世界。\n\n我無法一個人對抗斯寇瓦德。來吧，勇士，我們主動出擊，結束這場災難！\n\n為了斯鐸海姆！", progress = nil, completion = "可惜神御之王逃走了，但他的失敗讓燃燒軍團勢力無法入侵斯鐸海姆。\n\n去英靈殿一趟吧。", rewards = "華爾琪拉之擁歐丁面罩魔縛血漿瓦爾格林之心英靈殿之炎德拉瓦克的獄卒碎片風鑄號角英靈殿嫩枝黑爾海姆號角魔腐迷霧您會收到：\n\n"}
MultiLanguageQuestData['tw'][40008] = {title = "只能殺出重圍", objective = "護送薩莉瑟拉到安全的地方。", description = "我有很多事情要說，但在這裡不方便說話。我沒辦法一直維持這道屏障。\n\n<薩莉瑟拉把精緻的藥水瓶舉到唇邊。喝了一口以後，她的雙眼發出微光。>\n\n如果我們闖出去的話，應該能在前方找到避難點。", progress = nil, completion = "你很善戰。\n\n我想應該是時候正式的向你自我介紹。", rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40009] = {title = "秘法飢渴", objective = "進入沙亞蘭，找到能滿足薩莉瑟拉渴望的東西。", description = "數千年以來，我的族人依賴夜井滋養。上古法力是我們的生命之血，沒有它，我們就會變得…嗯，你看過他們的慘狀了。\n\n<薩莉瑟拉高舉藥瓶，慢慢將最後幾滴珍貴的井水飲盡。>\n\n恐怕今天我是過於莽撞了。\n\n我的感官已經開始麻木。沒有魔法的滋養，我會轉變的。\n\n請…請幫我找到…能滋養我的…東西…什麼都好…", progress = "<薩莉瑟拉眼神渙散，身體不斷顫抖。>", completion = "&lt;薩莉瑟拉用顫抖的手拿著水晶。&gt;", rewards = "永生守衛者披風您會收到：\n\n上古守衛者胸針"}
MultiLanguageQuestData['tw'][40010] = {title = "汲取地脈", objective = "探索亞諾拉谷地，找出脈能站。", description = "建造幽暗地道的目的是為了開發蘇拉瑪爾底下的魔法地脈。隨著我們學會如何利用夜井存活下去，這座古老的設施也隨之停用。\n\n這間房間顯然正從其他地方接收能量。\n\n但現在只有涓涓細流，不過如果你能引來更多地脈能量，就能讓我們生存下去。\n\n最近的地脈能量來源在北方，在亞諾拉谷地附近。", progress = nil, completion = "你又是誰？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40011] = {title = "歐庫雷斯的工坊", objective = "將首席秘法師的徽印交給歐庫雷斯。", description = "我們得聯繫首席傳送師歐庫雷斯，他是發展了蘇拉瑪爾傳送網路的人。\n\n歐庫雷斯在舊蘇拉瑪爾有一間工坊，在大崩裂之前就在了。他可能到那避難了。\n\n<薩莉瑟拉把一枚小硬幣塞進你手中。>\n\n你找到他的話，把這個拿給他看。希望你在他看到你之前先找到他…", progress = nil, completion = "等到我這裡的工作完成後，請你帶我去找薩莉瑟拉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40012] = {title = "過去的盟友", objective = "在琥珀谷尋找秘法師克達納茲的藏身處。", description = "我本來想前往琥珀谷，希望能夠找到一名老同事。\n\n秘法師克達納茲對凋萎者深深著迷。他花了數年研究如何平息他們的凶猛天性，甚至是治好他們。\n\n但是他有一隻實驗體逃了出來，並在皇家花園內肆虐，隨後克達納茲被命令停止研究，還要殺掉他掌管的所有凋萎者。他因拒絕而遭到流放。\n\n若克達納茲還活著，他應該也快要變成凋萎者了。而凋萎者通常都被流放到舊殖民地，例如琥珀谷。", progress = nil, completion = "&lt;有人居住在此的痕跡。這份卷軸上書寫著奇異的文字，發出溫暖的光芒，使你忍不住伸出手撫摸。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40013] = {title = "紫地根草樣本", objective = "將紫地根草樣本交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "這種藥草顯然一直從土壤吸收魔法能量。地脈能量透過莖脈從根部輸送到葉子。\n\n達拉然的草藥學訓練師一定會想看看這個。", progress = nil, completion = "從外觀來看，我以為這種藥草脆弱又嬌貴，事實上…卻十分強韌。\n\n喔～看看這個！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40014] = {title = "鏟除解剖", objective = "取得純淨雌蕊和無垢雄蕊。", description = "莖、葉、花瓣都很迷人，錯不了…不過看看這裡的授粉花絲，還有花朵中央的生殖器官。其中所含的能量超過植株其他部位的總和。\n\n我推測，只能鎖定這些部位，就能用更簡潔、更有效率的方式採集紫地根草。\n\n不過，這朵花似乎有點損傷。我需要看到完整無缺的植株才能確定。", progress = "去掉這些最…「親密」的花朵部位似乎不是正確做法，不過不用擔心。它們還會長回來。\n\n就像是食人妖的身體一樣。", completion = "&lt;訓練師仔細檢查雌蕊和雄蕊，神情專注。&gt;\n\n大地之母創造紫地根草的時候，一定十分慷慨。\n\n繼續專心研究這個花朵部位，&lt;name&gt;。", rewards = "您會學到：\n\n採藥技術：紫地根草(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40015] = {title = "破爛的絲帶", objective = "與庫蕙妮‧柔行交談，瞭解紫地根草與凋萎者的關係。\n\n已提供物品：\n", description = "精心縫製的布條看起來破破爛爛、骯髒不已：明顯出自凋萎者。\n\n夜裔一族兇狠墮落的流亡者一定也在採集紫地根草…為什麼呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40016] = {title = "柳暗花明", objective = "從艾蘇納的凋萎者身上取得6根嚼過的紫地根草莖。", description = "我相信我們能夠把這條線索化為我們的優勢，<name>。\n\n凋萎者因為對法力的渴望而惡名昭彰，絕對會不顧一切奪取法力。也許我們可以研究他們如何使用紫地根草，然後藉此改良我們的採集方式。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：紫地根草(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40017] = {title = "輕柔手感", objective = "與庫蕙妮‧柔行交談，瞭解紫地根草的快速繁殖特性。", description = "在你採集紫地根草的時候，你的手拂過花朵的授粉器官，使其彼此相碰，產生反應。\n\n你可能發現了新的草藥學技巧。應該去跟達拉然的訓練師談談你的新發現。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：紫地根草(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40018] = {title = "幻夢草樣本", objective = "將幻夢草樣本交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "這株藥草呈翠綠色，薄如蟬翼，帶有黏性。\n\n達拉然的草藥師訓練師一定會想看看這個。", progress = nil, completion = "我知道這種藥草。我以前在潘達利亞的四風峽看過一次。\n\n這是幻夢草。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40019] = {title = "因禍得福", objective = "取得15株健康的幻夢草和5株感染荒疫的幻夢草。", description = "不過這株幻夢草似乎有些不同。\n\n我有個想法。\n\n維爾薩拉的荒野遭到夢魘詛咒侵襲。像這類敏感的藥草非常容易受到影響。\n\n我需要更多資訊才能下定論。幫我找一些健康的樣本，以及一些感染荒疫的樣本，進行後續研究。", progress = "可憐的植物…", completion = "正如同我所推測的。這株感染的藥草快死了…不過這或許反而對我們有利。\n\n聽著，草藥師。快枯死的幻夢草會因為受到感染而膨脹體積。採集健康的幻夢草雖然很簡單，但你可以從感染的幻夢草上採集到更多的量。", rewards = "您會學到：\n\n採藥技術：幻夢草(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40020] = {title = "死亡夢魘", objective = "前往洛拉希爾，尋找專家，瞭解荒疫對藥草的影響。\n\n已提供物品：\n", description = "這株藥草已經完全腐化了。\n\n荒疫是一股神秘力量，其複雜度已經遠超普通草藥學的範疇。只有專門研究疫病的專家才能為你分析這裡的真實狀況。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40021] = {title = "植物荒疫", objective = "在維爾薩拉殺死20隻薩特。", description = "我們必須展開報復行動。雖然我瞭解翡翠夢境和夢魘維持平衡的重要性，但這次夢魘的腐化已經完全失控！\n\n薩特。這一切都是薩特造成的。一定要讓它們付出代價！讓它們付出代價，那麼伊露恩就會賜予你豐厚的獎勵！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：幻夢草(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40022] = {title = "窒息夢魘", objective = "將荒疫枯萎藥草交給維爾薩拉的馴草者歐斯米。\n\n已提供物品：\n", description = "又一株植物死於荒疫。這株植物完全萎縮起來，導致它完全照射不到陽光。\n\n你應該把它交給洛拉希爾的馴草者歐斯米。他對此不會感到高興。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40023] = {title = "最後一根稻草", objective = "使用特索朗的召喚石，召喚並殺死特索朗。", description = "我們不能再猶豫不決，必須立即對抗這場腐化，<name>。\n\n這是我們身為英雄、身為草藥師的責任。\n\n身為英雄草藥師。\n\n殺死一般的薩特還不夠。我們必須攻擊它們的首領。帶著這株死亡的藥草前往東北方的夏拉尼爾。找到特索朗的召喚石，將這株藥草放在召喚石前面。然後…扭下他的頭。\n\n為這株植物報仇。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：幻夢草(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40024] = {title = "狐花樣本", objective = "取得20份狐花樣本，交給達拉然的庫蕙妮‧柔行。", description = "這株藥草的外觀和氣味引起你的注意…\n\n達拉然的草藥學訓練師一定十分希望研究這種嗆鼻的未知花草樣本。", progress = "<牛頭人嗅聞空氣。>", completion = "我喜歡你帶來的這株藥草，&lt;name&gt;。它讓我聯想到格古隆德捕蠅草：這兩種藥草都有一股刺鼻味。\n\n看著，如果你用這種方式採集藥草，就能稍微增加產量…", rewards = "您會學到：\n\n採藥技術：狐花(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40025] = {title = "細微咬痕", objective = "將受蠶食的狐花莖交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "這株藥草曾經被當地的某種野生動物咬過。\n\n什麼樣的動物會吃狐花呢？是熊嗎？\n\n也許達拉然的訓練師能夠為你解惑。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40026] = {title = "調查採花賊", objective = "找出以狐花為食的生物，追趕牠們，然後取得12份嚼過的狐花片。", description = "這是一種強效藥草，<name>。生物偶爾會吃些弱效藥草，但牠們通常對強效藥草避之唯恐不及。\n\n我很好奇，到底什麼樣的動物會吃狐花？是麋鹿嗎？\n\n你應該深入調查。找出以狐花為食的生物，然後看看你能不能在牠們逃跑之前，從牠們口中搶出一些狐花。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：狐花(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40028] = {title = "花衣拾取者", objective = "將狐花香味腺體交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "完成狐花的採集工作後，狐花的某個部位引起你的注意。\n\n其中一片葉子上有一個小瘤，就在與莖部相接的地方。深入調查後，你發現狐花的奇怪氣味就是從這裡散發出來。\n\n草藥學訓練師一定會很感興趣。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：狐花(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40029] = {title = "鬼燈果樣本", objective = "將20株鬼燈果交給達拉然的庫蕙妮‧柔行。", description = "對於一個沒受過草藥學訓練的人而言，這片荊棘叢可能看似毫無用處。但你所受的訓練卻明白指出這確實是非常特殊的植物。\n\n達拉然的草藥學訓練師一定想多看看這種藥草的樣本。", progress = "草藥師，你帶了什麼東西？", completion = "非常驚人的發現，&lt;name&gt;。這一定是維酷人愛用的藥草鬼燈果。我過去只在書中見過！\n\n看這裡，我會把我所知的一切告訴你…", rewards = "您會學到：\n\n採藥技術：鬼燈果(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40030] = {title = "公羊角泥鏟", objective = "將公羊角泥鏟交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "透過工具握柄上的符文記號，可以判斷這是維酷草藥師遺落的工具。\n\n顯然，那個維酷人也在採集鬼燈果。訓練師庫蕙妮提過，她過去曾在書中看過這種藥草。\n\n也許維酷人用來採集藥草的工具能夠引起她的興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40031] = {title = "維酷草藥學", objective = "前往斯鐸海姆尋找三本維酷草藥學書籍。", description = "<庫蕙妮仔細研究這把鏟子。>\n\n這是標準的挖掘工具。沒有太多有用的資訊，除了…\n\n…這確實表示維酷人還在積極採集這種藥草。\n\n維酷人應該比我們還瞭解這種藥草。我們要做的，就是查出他們把這些資訊放在哪裡。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：鬼燈果(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40032] = {title = "遺失的那一頁", objective = "將符文日記書頁交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "<這一頁似乎是從一本書上撕下來。上面寫著：>\n\n「…深海之碑，自古以來眾神鍾愛之地。\n\n他將作為祭品的鬼燈果放在碑底，口吐禱言『藥草生於藥草』，然後獲得他所需的祝福。」\n\n這段文字應該與你帶給草藥學訓練師的書籍有關。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40033] = {title = "鬼燈果", objective = "帶20株鬼燈果到斯鐸海姆的風化的石碑去，然後獲得鬼燈果的祝福。", description = "好了！看來是有位叫做托格斯的維酷草藥師，把鬼燈果當作祭品放在海邊石碑 - 想必是在斯鐸海姆 - 然後藉此獲得先祖的祝福。\n\n<庫蕙妮聳聳肩。>\n\n這值得一試，不過不知道會發生什麼事，最好找幾個人一起去。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：鬼燈果(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40034] = {title = "星輝玫瑰塵", objective = "將星輝玫瑰塵交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "你的訓練似乎毫無作用，玫瑰還是在你手中解體。\n\n達拉然的草藥學訓練師一定會想看看這個。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40035] = {title = "最溫柔的碰觸", objective = "試圖再採15朵星輝玫瑰。", description = "很可惜，我沒有任何能幫你解決問題的特殊技巧。你只是需要練習你的手法。回到那裡去，盡可能以溫柔的手法採集星輝玫瑰。", progress = nil, completion = "成功了嗎？還是失敗？\n\n就算尚未成功，但你的技巧一定有所改善。別輕易放棄，草藥師。", rewards = "您會學到：\n\n採藥技術：星輝玫瑰(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40036] = {title = "寶石鏟柄", objective = "將寶石鏟柄交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "精雕細琢的鏟柄就落在玫瑰旁邊。顯然這把華麗的鏟子一點也不耐用，鏟面已經完全掉落。\n\n草藥學訓練師可能會感興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40037] = {title = "鏟面", objective = "尋找草藥學家的破鏟。", description = "<name>，你留意到鏟柄底部的字了嗎？上面以夜裔文字寫著「草藥師薩里隆」。\n\n鏟柄對我們沒什麼用，不過也許鏟面可以告訴我們一些祕訣，減少採集星輝玫瑰的失敗次數。\n\n我會從蘇拉瑪爾開始搜尋。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：星輝玫瑰(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40038] = {title = "胡言亂語", objective = "將草寫囈語交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "一卷骯髒的羊皮紙上潦草地寫著憤怒的字眼。一段文字引起你的注意：\n\n     「以為<他/她>知道如何採集藥草\n <name><name>\n<name><name>偷走我的採藥鏟\n  切開<他的/她的>喉嚨，那時我\n\n        剛好需要\n      多一點法力\n    也許紫地根草，沒錯…」\n\n草藥學訓練師可能會對這個感興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40039] = {title = "薩里隆的墮落", objective = "將20堆星輝玫瑰塵帶到艾蘇納，使用它們逼草藥師薩里隆現身，然後從他身上搜索有關草藥學的資訊。", description = "他提到你的名字…他的採藥鏟…紫地根草…\n\n我敢肯定這一定是草藥師薩里隆的，從外觀來看，他可能已經在夜落精靈的困境下屈服了。還有，如果他在尋找紫地根草，就很可能會在艾蘇納的某處。\n\n薩里隆目前是我們進一步瞭解星輝玫瑰的唯一希望。把他找出來，不過最好多帶點人…不打一架，他大概不會就範。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：星輝玫瑰(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40040] = {title = "魔草樣本", objective = "將魔草樣本交給達拉然的庫蕙妮‧柔行。\n\n已提供物品：\n", description = "這株藥草充滿邪惡能量，表面不斷冒泡。它既光滑又乾涼，但摸起來有股刺痛感。\n\n達拉然的草藥學訓練師一定會想看看這個。", progress = nil, completion = "喔，我完全不喜歡這株藥草。非常迷人，但我不喜歡。\n\n&lt;庫蕙妮緊盯著植物中心。&gt;\n\n看一下這些種子的大小，&lt;name&gt;。我們可以利用這些種子。下次採集的時候，記得小心一點。", rewards = "您會學到：\n\n採藥技術：魔草(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40041] = {title = "魔草分析", objective = "收集萊諾‧綻原的分析、達妮‧地觸的分析和羅赫的分析。", description = "我把魔草樣本寄給一些草藥師朋友，但是還沒有收到他們的回報的消息。能不能請你追蹤他們的回覆並收集他們的分析報告呢？\n\n萊諾‧綻原目前正在安戈洛環形山工作。\n\n達妮‧地觸正在研究芙蕾雅對休拉薩盆地的影響。\n\n最後，羅赫則是一直在格古隆德的永茂林地區工作。", progress = "謝謝你願意四處奔走，<name>。", completion = "大多數都是瑣碎的技術分析，不過羅赫的分析可以立刻套用。\n\n看看這個，就是這裡…", rewards = "您會學到：\n\n採藥技術：魔草(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40042] = {title = "翡翠夢魘：精通魔草", objective = "前往翡翠夢魘並淨化塞納留斯身上的腐化。把你發現的任何東西帶回去交給達拉然的庫蕙妮。", description = "我有個理論，能夠提高採集魔花的產量，<name>。你知道，為了要瞭解某件事發生的過程，有時候得逆向操作。\n\n我最近聽說我們最偉大的守護神，塞納留斯，被腐化了。我確信這些藥草帶有的腐化跟塞納留斯體內的腐化是同一個根源。\n\n如果你能淨化塞納留斯的腐化，設法了解它的原理並將它清除，我想我們就可以用同樣的方法採收這些藥草。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：魔草(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40043] = {title = "英雄狩獵者", objective = "解決維格弗斯‧刃風的軍隊並取得他的武器。", description = "為嘲諷我的衛隊，黑爾雅將自己的軍隊取名為「黑爾拉亞」。這支軍隊由不死生物組成，專門獵殺英勇戰士，並在我的華爾琪到來前奪走他們的靈魂。其中有一位名叫維格弗斯‧刃風，是黑爾雅的親衛勇士，所用兵器為我多年前親自打造、後來遭竊的雙劍。\n\n他已返回蔑潮港，正要將一整批竊來的靈魂送往黑爾海姆。去那裡殺掉他和其他的黑爾拉亞衛隊，神劍就是你的了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40044] = {title = "霧中暗影", objective = "到獄喉淺灘擊敗史騰船長、席格芮、克杰爾和哈爾維。", description = "海灣這裡的許多科瓦迪爾原本是港口的居民，卻被海巫黑爾雅詛咒，不得不聽命於她。\n\n你看到的那些人，他們日日夜夜行走在發臭的水中。必須等到有好心人願意殺死他們，才能獲得解脫。\n\n告訴我，你是好心人嗎？", progress = nil, completion = "他們終於從痛苦中解脫了，而在斯鐸海姆的科瓦迪爾也變少了。\n\n這都是值得慶賀的事。", rewards = "席格芮的魅影罩氅符語者之索符誓護腰颶裔繫腰懼誓護腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][40045] = {title = "天性使然與後天教養", objective = "與10個沼岩蝌蚪交談。", description = "我太喜歡這些魚人了，所以不會叫你殺光所有成年魚人的。\n\n我們應該做的是讓下一代更為崇尚和平。莫奇最適合這種任務了。\n\n讓莫奇跟那些魚人蝌蚪談談，他會讓蝌蚪加入我們的。", progress = nil, completion = "莫奇獲得了不少追隨者，是吧？或許他們能協助他。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40046] = {title = "搜索淺灘", objective = "到獄喉淺灘搜沉船殘骸，尋找哈維的線索。", description = "科瓦迪爾就是為了惹惱歐丁而生，這裡就是他們的傑作。他們搶奪活人的靈魂，尚未接受審判的靈魂，導致歐丁失去他的勇士。\n\n他們把靈魂帶來這裡送給黑爾雅，不過因為迷霧的關係，我們不知道他們怎麼辦到的。\n\n你似乎不受迷霧影響。也許可以搜索一下海灣的殘骸，答案就會自己浮現。你們外來者似乎擅長揭穿那些藏得最深的秘密。", progress = "你找到答案了嗎？還是發現更多問題？", completion = "奈格法號…\n\n這麼說，黑爾雅的科瓦迪爾人能在迷霧中航行？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40047] = {title = "深呼吸，然後自爆…", objective = "取得5個河豚蛋。", description = "我最喜歡莫奇這小傢伙了。不過，為了讓這裡的魚人族群改變，他需要一些厲害的能力。\n\n這裡的水域有許多自爆河豚，我想莫奇應該可以好好利用牠們。\n\n殺掉幾隻自爆河豚，然後幫莫奇收集牠們的魚卵。", progress = "自爆河豚有一種令人驚奇的能力…就是自爆。牠們可能會是莫奇有用的工具。", completion = "自爆河豚最適合莫奇了！我會施法，讓牠們長得更快。\n\n莫奇只要丟出去，牠們就會爆炸！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40048] = {title = "人偶師的絲線。", objective = "從燃燒軍團營地：混沌的惡魔手中取得主宰符文。", description = "我知道你只是來送皮紙的，但我們可以用到你身為<class>的技巧。我們的軍力最多只能抵擋住惡魔的入侵，想將人偷渡進敵營中實在是分身乏術。\n\n他們的強大戰力就在後方，由遠距離外下達指揮命令。他們攜帶著能控制前線惡魔的附魔符文。\n\n我迫切地想好好研究那些符文。請幫我取回一個，這樣我們才能從中學習並將其用來對付軍團。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40049] = {title = "綠泥時間", objective = "游過綠泥藻，餵食莫奇6份綠泥藻。", description = "莫奇還在長大，他需要進食！有什麼比綠泥藻更適合小魚人呢？\n\n魚人水域中有很多綠泥藻，游過藻群，然後餵食莫奇！", progress = nil, completion = "莫奇似乎因為這種綠泥藻而獲得非常厲害的黏液能力。太棒了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40050] = {title = "船骸灣", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][40051] = {title = "惡魔之秘", objective = "閱讀魔秘寶典，選擇災虐或復仇專精。", description = "惡魔的致命失誤就是把它們的秘密寫在這本書上。從書本散發出來的魔化能量相當強大。\n\n不過這些能量只夠執行其中一個儀式。使用後，書本就會能量盡失。\n\n你可以自行決定我們要利用哪個秘密來對抗燃燒軍團。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40052] = {title = "古代維酷人的專長", objective = "將石板和字典交給帕林教授。", description = "這是石板和破譯的文字。你也可以把這部字典帶回去給帕林了。我會開始收拾東西，等他叫我回去達拉然。\n\n<尼可洛嘆了口氣。>\n\n希望我的狀況能警惕你，<name>。如果我是你，我會試著別讓帕林「予取予求」。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：失傳知識卷軸"}
MultiLanguageQuestData['tw'][40056] = {title = "我們的新盟友", objective = "向艾蘇納的『噬魂者』艾萊莉回報。", description = "徒弟！你麾下在艾蘇納的惡魔獵人已經為你出征了。\n\n我當然可以感謝你花費時間來抵禦燃燒軍團，但這不是荒廢研究的藉口。\n\n你抵達的時候，不如針對自己的技能設計一些新雕紋。\n\n我已經對你傾囊相授，相信你一定能活用所學，創造你專屬的配方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40057] = {title = "力量的代價", objective = "殺死15個惡魔以減緩侵略的攻勢。", description = "我很清楚，你希望透過銘文提升自己的實力。我相信我們可以一舉兩得。\n\n我需要有人協助我降低惡魔的威脅。也許跟敵人深入交流一下，會讓你有所啟發。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：魔觸靈魂雕紋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40058] = {title = "防禦的象徵", objective = "到札克赫納地脈遺跡附近找巴里克‧風暴行者。", description = "你也知道，<name>，我們這些惡魔獵人必須抑制內心黑暗的一面，我們一旦屈服，自己也會變成惡魔。\n\n在遙遠的北方，有一個叫做巴里克‧風暴行者的惡魔獵人正準備強化紋身。他會需要你協助他完成儀式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40059] = {title = "異者相斥", objective = "在札克赫納從夜落精靈身上收集地脈之塵。", description = "地脈能量從附近的廢墟中湧出。此時此刻，稱為「夜落精靈」的扭曲夜精靈正在那片區域中四處掠奪。\n\n前往上方的廢墟，幫我從夜落精靈身上收集地脈之塵。這些塵注入了秘法能量，我需要在儀式中用到它。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40060] = {title = "束縛內在的惡魔", objective = "協助巴里克完成儀式。", description = "我們現在已經萬事俱備，那就開始進行儀式。\n\n我會告訴你如何協助我完成儀式。在我下達指示時你能不能遵循至關重要，否則儀式必定失敗。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：鵝黃之翼雕紋\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40061] = {title = "了解你的敵人", objective = "在魔炎入口附近尋找札莉雅‧影心。", description = "與惡魔對戰的時候，我們也同時在研究它們。\n\n蒐集情報有助於深入瞭解它們。我派了一名惡魔獵人前往魔炎入口，蒐集當地惡魔的情報。\n\n請去找她，看看她對入侵該區域的惡魔瞭解多少。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40062] = {title = "鼓脹的夢魘豆莢", objective = "將鼓脹的夢魘豆莢交給達拉然的帕林教授。\n\n已提供物品：\n", description = "<花朵為了躲避困在裡頭的夢魘能量，將花瓣向內縮起。>\n\n<帕林教授絕對會對這很感興趣的。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：大量研磨幻夢草\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40063] = {title = "操控至上", objective = "摧毀用來保護監督者菲洛拉斯的水晶，然後殺死他。", description = "我相信你還記得你為什麼挖去你的雙眼？\n\n雖然現在我們可以看得更加清楚，不過惡魔也有辦法不讓我們看到它們身上的魔化能量。\n\n有一個惡魔指揮官在下面巡視部隊，躲在暗影中發號施令。他的斗篷經過高能水晶強化。\n\n找到並摧毀那顆水晶，然後殺死指揮官。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n玫瑰色顏料"}
MultiLanguageQuestData['tw'][40064] = {title = "叢生木質種子", objective = "將叢生木質種子交給達拉然的帕林教授。\n\n已提供物品：\n", description = "<研磨這朵花比平常還要困難，因為在濃密的花蕊中心的是密集叢生的種子。>\n\n<帕林教授絕對會對這很感興趣的。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：大量研磨狐花\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40065] = {title = "鬼燈果", objective = "將鬼燈果交給達拉然的帕林教授。\n\n已提供物品：\n", description = "<一種黏稠的物質從花朵中滲出。不是墨水…是另一種完全不同的東西。>\n\n<帕林教授絕對會對這很感興趣的。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：大量研磨鬼燈果\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40069] = {title = "幼蟲內臟", objective = "在岩蟲裂谷中，從幼小的岩蟲身上收集蠕蟲內臟。", description = "卓格巴使用這些洞穴作為訓練幼齡蠕蟲之用。\n\n這些岩蟲雖然現在年幼弱小，但假以時日，體型與力量將慢慢增大。如果我們不插手，最終這些蟲會變為龐然大物，成為卓格巴的戰鬥坐騎。\n\n而這些蟲的內臟也相當實用，我們用得上這些東西，這簡直就可以說是一石二「蟲」。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40070] = {title = "尋回鷹蛋", objective = "前往岩蟲裂谷取回鷹蛋。", description = "老鷹備受天角部族尊崇，但牠們的數量越來越少。\n\n卓格巴用鷹蛋餵食幼齡蠕蟲，好讓牠們長成健壯的戰鬥坐騎。\n\n如果卓格巴一直偷這些蛋，老鷹就可能會絕跡。\n\n進入洞穴深處，取回你找到的鷹蛋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40071] = {title = "殺死馴蟲師", objective = "殺死岩蟲裂谷裡的馴蟲師克古爾。", description = "只要馴蟲師不死，卓格巴便會不斷繁殖可怕的巨蟲。\n\n克古爾負責將幼小的岩蟲餵食和訓練成可在戰鬥中騎乘的可怕攻城蟲。\n\n深入裂谷，了結他的性命，別讓這些巨蟲孽種再次出現。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "雪盲裹腕雷霆之巔腕甲白浪環甲腕輪卓格縫製護腕您能選擇下列奬勵中的一個：\n\n克古爾的馴蟲鍊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40072] = {title = "英靈殿：取得神盾", objective = "在英靈殿中擊敗神御之王斯寇瓦德，取得阿格拉瑪之盾。", description = "怒魔維酷雖然潰不成軍，但他們的首領還活著。神御之王仍有可能爭奪阿格拉瑪之盾！\n\n你已經通過了重重試煉，絕對不能讓這件事發生。就算必須踏過斯寇瓦德的斷骨殘軀，也要取得神盾！\n\n英靈殿等著你！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n歐丁的警戒凝視"}
