MultiLanguageQuestData['tw'][40112] = {title = "胡恩之戰 - 瑪洛尼的愛將", objective = "拯救艾切羅。", description = "[操著不流利的通用語]：尊師要你讓艾切羅送信。\n\n昂亞克聽到艾切羅的打架聲。你找到牠了嗎？去幫忙，讓有羽毛的夜精靈輕鬆。", progress = nil, completion = "&lt;艾切羅抬起眼睛注視了一下，然後在你面前低下頭來。這頭生物正在感謝你出手相救。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40120] = {title = "前途黯淡", objective = "在莫爾海姆使用悶燃火把燒毀8具腐爛的屍體。", description = "你或許不清楚，但你正站在莫爾海姆的土地上。這裡是大地上最偉大戰士的家園。我們的功績宏偉、勇武無人能比。我們竟落得如此下場，實在讓我痛心。\n\n那些生物在夜暮低垂時群聚而上。我們的戰士英勇奮戰，但勢單力孤。現在他們的屍體在太陽下曝曬腐朽，沒有埋葬、沒有儀式。\n\n這不是莫爾海姆的光榮戰士應得的結局。給倒下的戰士應得的尊敬，你就能得到我們的感謝。", progress = nil, completion = "謝謝你給予我們戰士的遺骸應得的尊敬。\n\n願他們在英靈殿的廳堂中歡慶勝利。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40121] = {title = "地脈影響。", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40122] = {title = "森林守護者，塞納留斯", objective = "在維爾薩拉的洛拉希爾與瑪法里恩‧怒風交談。", description = "啊，維爾薩拉。\n\n我上次踏進這片神聖的林地，已經是很久以前的事了。太久了…\n\n我們在這裡的工作非常簡單，<class>。我們必須尋訪我的導師塞納留斯，並請教他保管伊露恩之淚的位置。有了伊露恩之淚，離封印薩格拉斯之墓和瓦解燃燒軍團，就又更進一步。\n\n在你面前的，還有無數危險至極的任務。你可以在這裡稍稍喘息。\n\n來吧，這不需要花太多時間。", progress = nil, completion = "這種腐化 - 我過去從未見過。\n\n但，我卻感覺有點熟悉…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40123] = {title = "夜裔契印", objective = "幫薩莉瑟拉包紮。", description = "<薩莉瑟拉吃痛地按住她的腹部>\n\n嗯…我沒辦法繼續無視這個傷口了，\n\n幫我包紮傷口。我會說明一切。", progress = nil, completion = "我們得想辦法奪回蘇拉瑪爾城。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40125] = {title = "奧肯多爾的樹枝", objective = "與薩莉瑟拉交談。", description = "你已經使用克達納茲的法術石安撫了無數凋萎者。但它只含有從奧肯多爾的休眠種子抽取出來的少許力量。\n\n<薩莉瑟拉高舉散發白光的樹枝。>\n\n這是從樹上掉下來的。雖然與本體分離，卻仍未死去 - 看不見的魔法紋路維繫奧肯多爾的完整。\n\n我已經重新吟誦克達納茲的符咒法術，在這根樹枝上附魔。有了它，你就能為更多凋萎者修補秘法精華。請善加利用。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n奧肯多爾的樹枝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40130] = {title = "洗淨", objective = "去諾丹尼爾之泉與墮落女祭司見面。觀看女祭司進行的淨化儀式。", description = "雖然燃燒軍團無比強大，但是他們並不是艾澤拉斯最強大的力量。\n\n我和附魔師伊蘭雅曾在某個地方渡過了無數的歡樂時光。傾注於此地的愛比惡魔魔法更具威力，<name>。\n\n前往諾丹尼爾之泉。它的水可以淨化你所收集的灰燼…或許連我都可以重新淨化。\n\n我在那邊等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40131] = {title = "石皮皮革樣本", objective = "將石皮皮革樣本，以及額外10組石皮皮革，交給達拉然的康達爾‧獵誓。", description = "這片皮革碎塊的品質可說是破碎群島當地獸皮的典型。\n\n達拉然的剝皮訓練師一定會很感興趣。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n軍團剝皮\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40132] = {title = "分毫無損", objective = "從破碎群島的野獸身上剝取20張未剝開的皮革。", description = "<訓練師仔細檢查毛皮。>\n\n這張毛皮沒辦法用，它實在小得可憐。像你這樣把它割得稀巴爛，是對生命的不敬，<name>。你輕視大自然送你的禮物。\n\n再去野外一次。剝下地上野獸的毛皮，而且，你這次必須帶回完整的毛皮。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：石皮皮革(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40133] = {title = "褲子碎片", objective = "把褲子碎片帶給高嶺上的赫米特‧奈辛瓦里。\n\n已提供物品：\n", description = "這隻野獸嘴裡咬著一塊刺繡布料。布料上繡著「辛瓦」。\n\n「辛瓦」這個詞聽起來很陌生，不過艾澤拉斯最有名的剝皮師，姓氏中間剛好是這兩個字。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40134] = {title = "高嶺毛皮", objective = "使用剝皮技能從高嶺的野獸身上取得5張熊皮、5張領角鹿獸皮和5張刃豹獸皮。", description = "這麼說來，你也是剝皮師？\n\n真是個好消息，<name>！我從沒料到我們之間還有這樣的共同點。\n\n你一定要看看我們在高嶺這裡發現的毛皮。我願意交出備用的單片眼鏡，只求能看一眼那些美麗、柔順的毛皮…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神射手單邊鏡片"}
MultiLanguageQuestData['tw'][40135] = {title = "流浪的自由", objective = "取得5張鬃牛獸皮、5張海獅豹毛皮、5張野豬皮和5張狼皮。", description = "我記得我年輕的時候，<name>。你還記得嗎？那時候責任沒那麼重…我可以隨心所欲，踏遍各地。現在，在高嶺這裡，我幾乎都得跟我的狩獵團隊一起行動。\n\n可是，破碎群島的其他地區還有那麼多有趣的生物。我會把位置標在你的地圖上，去那裡剝一些皮回來吧！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：石皮皮革(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40136] = {title = "無瑕的石皮皮革", objective = "將無瑕的石皮皮革帶到達拉然交給康達爾‧獵誓。\n\n已提供物品：\n", description = "你剝皮也有一段時間了，但是從沒看過品質這麼好的皮革樣本。強韌、柔軟、色澤漂亮…\n\n達拉然的訓練師一定會對這個非常非常感興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40137] = {title = "給史克里特的皮革", objective = "到蘇拉瑪爾找史克里特。", description = "這張毛皮證明你一直很認真學習我教給你的所有皮革知識，<name>。自從我在城裡開店後，我的技藝已經生疏了。\n\n我有一個徒弟正在蘇拉瑪爾從事剝皮事業，他叫做史克里特。不像寶刀已老的我，他的技藝仍然十分純熟，如果想繼續精進你的技藝，非去找他不可。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40138] = {title = "十字軍試煉：傳說毛皮", objective = "從十字軍試煉中取得冰嚎的皮。\n\n從巴拉丁堡取得歐庫薩的皮。\n\n從雷霆王座取得哈里登的皮。", description = "好啊，我可以訓練你。但問題是，我還要在蘇拉瑪爾這裡鍛鍊我的技術。其實你應該可以幫上忙。\n\n我需要看一下一些特殊皮革，當作比較。我需要強韌雪白的雪人皮、超級大張的惡魔皮，還有史上無敵厚的恐角龍皮。\n\n給我這些皮，我就會跟你和達拉然的老康達爾分享我的研究成果。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40139] = {title = "英靈殿：芬里爾的獸皮", objective = "從英靈殿的芬里爾身上剝取芬里爾的皮。", description = "既然你還在這裡，我有一個非你不可的任務。\n\n我聽說附近有隻又大又壞的野狼，一直為這片維酷人土地帶來各種問題。它的名字是芬里爾。\n\n我要它的皮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40140] = {title = "史克里特的皮革手冊", objective = "將史克里特的皮革手冊帶到達拉然交給康達爾‧獵誓。", description = "有了這個，我的研究總算完成了。\n\n<史克里特給你一個卷軸。>\n\n這是我在蘇拉瑪爾這裡的研究成果。把它交給康達爾，讓他教給其他剝皮師。\n\n你幫了我很大的忙，所以我把你的名字也放上去了，<name>。希望你別介意。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：石皮皮革(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40141] = {title = "雷鱗樣本", objective = "將雷鱗樣本帶到達拉然交給康達爾‧獵誓。\n\n已提供物品：\n", description = "這塊鱗片閃耀著電能。\n\n達拉然的剝皮訓練師一定會很感興趣。", progress = nil, completion = "剝皮師，有事嗎？", rewards = "您會學到：\n\n軍團剝皮\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40142] = {title = "雷鱗核心", objective = "從破碎群島的有鱗野獸身上剝取20片雷鱗火花。", description = "喔，沒錯，難以捉摸的雷鱗。\n\n我在北裂境看過類似的鱗片，天空之牆也有一些，不過這種鱗片在這裡似乎非常常見。我專門製作鎖甲的同事要是看到這個，一定會很開心。\n\n為了能更有效剝取這種鱗片，你必須先瞭解其中的力量。從獵物身上找到無法使用的破損鱗片，去除其中的火花。等到你看到火花，一定會更加瞭解雷鱗。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：雷鱗(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40143] = {title = "未完成的雷鱗特性研究論文", objective = "將未完成的雷鱗特性研究論文帶到達拉然交給康達爾‧獵誓。\n\n已提供物品：\n", description = "疊在一起的獸皮中間夾了一張紙。看起來像是剝取雷鱗的手寫指南，不過絕大部分的手稿都已經散失，因此派不上用場。\n\n也許達拉然的訓練師可以幫你找到原主。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40144] = {title = "葛莉艾兒", objective = "在艾蘇納找到葛莉艾兒。", description = "有個以艾蘇納的野外為家的剝皮師，名叫葛莉艾兒，她是個夜精靈 - 好吧，她活著的時候曾經是。\n\n卷軸可能是她的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40145] = {title = "羽絨之下", objective = "取得20片角鷹獸鱗。", description = "不過我還是可以訓練你。\n\n大家都知道角鷹獸腿部有明亮的雷鱗，不過你知道嗎？角鷹獸的羽毛下面也有一些鱗片。你只需要知道鱗片的位置。\n\n<夜精靈靈魂指出角鷹獸翅膀關節附近的幾個地方。>\n\n現在，去看看你能不能找到一些鱗片。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：雷鱗(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40146] = {title = "希摩爾與艾格妮絲", objective = "在斯鐸海姆找到希摩爾。", description = "你給我看的這份卷軸還讓我想到另一位剝皮師 - 老實說是另一對剝皮師。是我的一個學生，叫希摩爾，和他母親艾格妮絲。\n\n就我所知，他們前往斯鐸海姆獵殺風暴飛龍了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40147] = {title = "母親珍藏的小刀", objective = "取得艾格妮絲的剝皮刀", description = "前幾天，母親和我一起爬上附近的山頂，結果她覺得風景不夠美，就把她的剝皮小刀丟向我。\n\n她的小刀還留在那裡的某處。不過把它留在那裡似乎不太好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40148] = {title = "紅眼復仇", objective = "殺死15隻成年的獵風飛龍。", description = "它就突然憑空出現。那時候我正在等母親剝完她那一半的飛龍皮，然後就看到生平最大的一隻風暴龍，然後…然後…\n\n<希摩爾下定決心。>\n\n我要你殺死越多風暴龍越好。剝不剝皮隨你高興。幫我為母親報仇！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40149] = {title = "德拉寇納必須死", objective = "取得德拉寇納之鱗。", description = "奪走母親生命的風暴龍叫做德拉寇納。\n\n母親一直想把它的鱗片做成墜飾，戴在身上，但是我們找不到機會剝它的皮，因為我沒辦法獨自殺死它，而她完全不管殺戮的事。滿腦子只想剝皮。\n\n你…你不介意幫她把鱗片帶回來吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n媽媽的剝皮小刀"}
MultiLanguageQuestData['tw'][40151] = {title = "無瑕的雷鱗", objective = "將無瑕的雷鱗帶到達拉然交給康達爾‧獵誓。\n\n已提供物品：\n", description = "你剝皮也有一段時間了，但是從沒看過品質這麼好的鱗片樣本。\n\n達拉然的訓練師一定會對這個非常非常感興趣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40152] = {title = "給史克里特的鱗片", objective = "前往蘇拉瑪爾找到史克里特。", description = "你的技藝已經超越我了，<name>。我從沒看過像這樣的鱗片…更別提剝皮手法簡直是專家級別。\n\n如果你還想繼續精進，就必須去找比我更厲害的剝皮師。他的名字是史克里特，過去曾是我的徒弟。\n\n他人就在蘇拉瑪爾的野外。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40153] = {title = "重返卡拉贊：傳說鱗片", objective = "取得卡拉贊中的尼德斯之鱗、黑曜聖所中的撒爾薩里安之鱗，還有恐懼之心的加拉隆之鱗。", description = "我非常瞭解鱗片的事，不過我現在狀況不好。我花了太多時間盯著這些雷鱗，導致我忘了其他種類長什麼樣。\n\n我需要看一下一些特殊鱗片，當作比較。我需要虛空龍鱗、新鮮出爐的黑龍鱗，還有史上無敵厚的昆蟲甲殼。\n\n我需要暫時忘掉這些雷鱗，兄弟。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40154] = {title = "艾薩拉之眼：巨鱗蛇的鱗片", objective = "在艾薩拉之怒地城中，從巨鱗蛇剝取巨鱗蛇之鱗。", description = "我需要請你幫個忙。\n\n我還沒去過艾蘇納，而且最近也沒有機會離開蘇拉瑪爾。問題是，那裡有一隻巨大的蛇精讓人很想剝它的皮。真的超想剝它的皮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40155] = {title = "史克里特的剝鱗建議", objective = "將史克里特的剝鱗建議帶到達拉然交給康達爾‧獵誓。", description = "既然已經拿到所有鱗片，我已經知道所有需要知道的事了。\n\n<史克里特交給你幾張手寫稿。>\n\n這裡面有我關於雷鱗的最新發現。把它交給康達爾，你們一起研究一下。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：雷鱗(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40156] = {title = "魔能皮革樣本", objective = "將魔能皮革樣本帶到達拉然交給康達爾‧獵誓。\n\n已提供物品：\n", description = "這張惡魔皮完全不像你所熟悉的一般獸皮。\n\n達拉然的剝皮訓練師一定會很感興趣。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：魔能皮革(等級1)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40157] = {title = "不得體的任務", objective = "在蘇拉瑪爾找到史克里特。", description = "你在這附近剝到的皮讓我印象深刻，尤其是魔能皮革。\n\n我關於魔能皮革的知識有限，但我知道有個人似乎精進了這方面的技術\n\n史克里特，我的老學徒，就在蘇拉瑪爾。問他皮怎麼剝比較有效益。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40158] = {title = "暗心灌木林：惡魔不一樣", objective = "前往暗心灌木林並殺死德瑞薩隆。剝下他的皮，並帶到蘇拉瑪爾給史克里特。", description = "噢，有啊，我在這些土地上還真看到不少惡魔。而且要剝這些惡魔的皮還真不容易。\n\n它們的皮比一般動物更硬、紋理更粗，懂吧？不過，如果你打算把大部份可用的皮都扒下來，那你就需要多加練習。\n\n我聽說在暗心灌木林中有一種生物，它的皮和惡魔一樣硬。當你在剝取它的皮革時，試著順紋下刀。\n\n把它的皮革帶回來，讓我看看你是否按照我講的方式下刀。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：魔能皮革(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40159] = {title = "翡翠夢魘：奈珊卓拉的染疫皮革", objective = "取得奈珊卓拉的染疫皮革。", description = "只剩下最後一張惡魔皮要收集…不過並不是真的惡魔，而是一條龍。\n\n奈珊卓拉是強大的綠龍，但幾乎已經被夢魘腐化殆盡。只有真正的剝皮大師才有能力剝下她身上僅存、被蟲蛀的皮革。\n\n去吧，<name>。讓我瞧瞧你的本事。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：魔能皮革(等級3)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40160] = {title = "魔法蚌殼", objective = "前往魚人海岸，從占脊魚人身上收集灌能蚌殼。", description = "<蚌殼與秘法能量產生共鳴。>\n\n魚人要用秘法蚌殼做什麼？\n\n也許你的夜落精靈盟友可以善用蚌殼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40161] = {title = "地底竊能", objective = "前往魚人海岸破壞占脊法器。", description = "<name>，你看到它們了嗎？\n\n這些不是普通魚人。它們受到從艾蘇納流入這片土地的地脈所吸引。\n\n它們找到方法汲取其中的秘法能量，然後使用這股能量胡作非為。\n\n如果要讓地脈完好無損，就必須阻止這些干擾行為。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40166] = {title = "魚人騷亂", objective = "在自己身上灌注魚人海岸的脈能。", description = "我看過這些占脊魚人召喚小型元素，這對魚人而言已經很不容易了，不過它們的高階召喚師布嚕格正試著從河裡召喚拓淪塔斯。\n\n我懷疑魚人到底有沒有辦法控制像拓淪塔斯這樣強大的元素。\n\n布嚕格一定是太著迷於召喚了，才會有這種舉動。我需要一些力量強大的東西來中斷它的儀式。\n\n把身上灌滿脈能，然後回來找我吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40167] = {title = "胡恩的故事", objective = "和靈行者黯角交談，了解胡恩‧高嶺的故事。", description = "你讓各個部族團結一心，這可不是一件容易的事。這座山頭有史以來，在此之前也只成功過一次。\n\n胡恩‧高嶺曾在數千年前讓所有部族聯合起來，在先祖之戰期間齊心對抗燃燒軍團。", progress = nil, completion = "你所看到的，只是胡恩‧高嶺畢生偉業的一小部分而已。讓我們來深掘過往…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40168] = {title = "迴旋藥劑瓶", objective = "將迴旋時光扭曲藥劑帶到撒塔斯城的中心。", description = "在碰觸這瓶藥劑時，你的腦海裡突然湧上許多回憶，但這些回憶不全然是你自己的。最鮮明的一段記憶是在撒塔斯和某人交易類似的瓶子，阿達歐之光在你身後閃耀。只是不管你怎麼認真地回想，還是無法說清究竟是在何時發生的。或許這件事根本沒發生過，也有可能即將發生？", progress = nil, completion = "喔，真有趣！\n\n&lt;庫普瑞迅速拿走藥劑，認真地研究起來。&gt;\n\n看來賽夫繼續研究是對的。這個藥劑顯然不是來自於任何已知的時間線。真是太神奇了！謝謝你把它帶給我，還是說，你以前就帶給我過了？", rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][40169] = {title = "交錯的十字路口", objective = "在魔炎入口附近搜尋女祭司的蹤跡。\n\n已提供物品：\n", description = "我的一位資深學徒在戰爭期間離開了，就在我們遭到詛咒之前沒多久。\n\n我最近聽說有人目擊她出現在魔炎入口附近。我很想要再跟她說一次話。\n\n去找她吧。把她的日記拿給她，讓她知道我沒有因為她的行為而責怪她。\n\n如果她願意的話，請帶她回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40170] = {title = "業餘時刻", objective = "在松岩盆地趕走業餘獵人。", description = "獵人小屋吸引了很多自稱獵人的業餘人士。他們笨手笨腳的，只會把所有獵物都嚇走。\n\n雖然我是神射手，但對交涉卻不在行。\n\n你能否幫大家一個忙，告訴這些新手獵人去山丘那裡？", progress = nil, completion = "你似乎對應付業餘人士相當在行。或許你能幫幫我的代筆寫手艾笛？\n\n我答應過要教她怎麼打獵，但我沒時間教她基本技巧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40173] = {title = "不穩定的時光扭曲稜石", objective = "將嚴寒時光扭曲稜石交給某位對它感興趣的達拉然法師。", description = "神秘的稜石逐漸在單一時間流穩定下來的同時，它緩緩散發出刺骨冰寒的氣息，這是你自從離開北裂境之後就沒有再感受過的。相信在達拉然一定有法師會對這東西感興趣。", progress = nil, completion = "拿來我看看。\n\n&lt;奧辛恩盯著稜石研究了好一會兒，然後才交還給你。&gt;\n\n嗯…這東西…庫普瑞大概可以研究個一輩子吧。它更進一步證明了，確實有為數眾多的第三者在暗中操弄…\n\n你介意把它交給我保管嗎？", rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][40176] = {title = "從頭到腳", objective = "製作一雙結實的石皮長靴。\n\n你必須到傳奇皮革，使用納姆哈的製皮架和納姆哈的工作臺。", description = "你一直忙東忙西，<name>。我發現你似乎學會了一些新圖樣。\n\n要不要再多學一點？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：破碎群島長靴\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40177] = {title = "皮匠女士", objective = "和黛安‧坎寧斯碰面。", description = "我希望你開始跟我的學徒合作。\n\n第一位是黛安‧坎寧斯，她十分擅長製作皮甲。她跟那對雙胞胎不同，對於鎖甲沒什麼興趣。\n\n去找她談談，進一步瞭解這種新皮革。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40178] = {title = "學習製作法衣的機會", objective = "取得塑皮者法衣。", description = "北裂境的維酷人一向喜歡穿著堅固的護甲，而且他們工匠的護甲往往是最堅固的。\n\n前往斯鐸海姆，找出深諳皮甲技術的人，把他的胸甲帶回來給我。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：戰皮上衣\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40179] = {title = "斯鐸海姆蠻人", objective = "取得7件維酷皮甲束帶。", description = "下面有個叫斯鐸海姆的地方，那裡是維酷人的地盤。自從去了北裂境，我對於維酷人就有了一定的認識。\n\n他們精心打造的護甲最讓我印象深刻。\n\n如果這裡的維酷人也像北裂境的維酷人一樣擅長製皮，我敢肯定，只要研究他們的武裝，一定能學到一些東西。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：戰皮護甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40180] = {title = "鎖甲男", objective = "去見桑尼德‧怒金。", description = "我後面那兩個矮人是怒金兄弟。他們是我駐店的鎖甲製作專家。\n\n拉尼德已經決定要把他的技術用來賺錢，但他的兄弟桑尼德還是純粹喜愛製作工藝。\n\n向桑尼德自我介紹一下。或許你能跟他合作，看看如何用這些雷鱗製作出不同凡響的成品。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40181] = {title = "玄鴉強盜", objective = "「借用」5件玄鴉護甲。", description = "有人傳聞維爾薩拉有一座大城堡，裡面據說駐紮著一支英勇善戰的軍隊。當然，他們身上穿的護甲也應該不是用稻草桿隨便做做。\n\n我敢打賭，他們一定為軍隊量身打造了特殊的鎖甲，然後收藏在某個地方，就等著大家去拿。\n\n你要不要去那邊晃晃，看看能不能從他們的軍械庫「借用」些什麼。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：鬥縛護甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40182] = {title = "讓人愛不釋手", objective = "取得玄鴉堡鍊衫。", description = "玄鴉堡出產的護甲，品質都相當精良，不過我最感興趣的是他們的胸甲。\n\n可以的話，試著去找那邊的重要人物…拿走他們的胸甲，減輕他們的負擔。\n\n你也不用覺得不忍心，我聽說他們都受到詛咒。結束他們悲慘的命運，也算是好事一件。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：鬥縛鍊衫\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40183] = {title = "頂上之物", objective = "製作一張劣質戰皮面具。\n\n你必須到傳奇皮革，使用納姆哈的製皮架和納姆哈的工作臺。", description = "好吧，<name>，我要你協助我製作頭盔。\n\n首先，我們必須刮掉毛皮上的毛髮，然後進行鞣製，最後裁成大小合用的皮革。\n\n跟著我一起做。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：破碎群島頭盔\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40184] = {title = "牛頭人製皮", objective = "找赫魯‧銳蹄回報。", description = "你聽過高嶺的牛頭人部族嗎？他們與卡林多的牛頭人相去不遠。\n\n我聽說其中有位製皮大師，或許能協助我們開發一些新的製皮圖樣。\n\n前往高嶺吧，看看他們是否願意教你如何製作護甲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40185] = {title = "肩負重擔", objective = "取得羅倫恩的肩衛。", description = "我的兄弟羅倫恩在最近的一場戰爭中戰死。他的護甲被卓格巴撿走。\n\n請取回被竊之物，別讓他的人生留下任何污點。製皮師，我會給你相應的獎勵。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：戰皮肩衛\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40186] = {title = "卓格巴的超人耐力", objective = "殺掉15個卓格巴，向赫魯證明你的能力。", description = "我們現在正與稱為卓格巴的種族交戰中。長久以來，我們一直與卓格巴維持和平關係，但近期他們變得完全不懂得尊重其他族群。\n\n殺死他們。證明你值得成為牛頭人的盟友。完成之後，我會以知識獎勵你。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：高嶺製皮\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40187] = {title = "鏈結在一起", objective = "在艾蘇納找到製皮大師。", description = "<小伙子/小姑娘>，恐怕我已經把所有關於這些鱗片的知識都教給你了。我也不太曉得如何把剩下的皮革製成一套套裝。\n\n不過，我聽說艾蘇納的精靈城市裡，有一些技藝精湛的製皮師，其中的一、二位也許還健在。\n\n去那裡找位師傅。也許他們可以幫我們補足缺少的圖樣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40188] = {title = "冰涼的最好", objective = "殺死埃卓尼爾淺灘的雷納里斯。", description = "我的夥伴和我都是大崩裂的受害者。我們被信賴的友人背叛和拋棄。\n\n那名「友人」最近經常在東方的廢墟出沒，他的名字是雷納里斯。\n\n請去那裡為我們報仇，然後我會傳授你一些知識。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：艾蘇納製皮\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40189] = {title = "納迦技術", objective = "取得7個納迦肩衛。", description = "這個地區的納迦只穿著少量護甲，不過他們的護甲真的特別耐用。\n\n如果你想要製作堅固的護肩，我會先研究納迦的護甲，然後設計出結構相似的圖樣。\n\n隔壁的城市已經被迦納佔據。殺死他們，帶回他們的護甲，你就會知道我所言非虛。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：鬥縛肩甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40190] = {title = "毛皮硬化", objective = "回到高嶺並和赫魯‧銳蹄談話。", description = "回到高嶺去，<name>。我聽說他們知道如何用更有效率的方式來製作我們的圖樣。\n\n當你到那裡的時候，可以幫我說些好話嗎？我想跟他們建立交情，而不是靠你來來回回傳遞消息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40191] = {title = "銘刻故事", objective = "察看每一層製皮架。", description = "掛在我身後的鞣製皮革，上面刻印著我們部族製皮師的古老工法。\n\n上面訴說著不同師傅的個人經歷，他們憑藉著恆心和一點運氣，開創了我們專屬的製皮技藝。\n\n閱讀這些故事，然後從中學習。也許你能找到一點靈感，改善自己的工法。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：戰皮上衣(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40192] = {title = "大地之爪", objective = "取得100根潛獵者的爪子。", description = "我個人的經驗告訴我，在打造護甲的時候最好使用較為堅固的材料。它們可以支撐得更久，所以需要的數量不用多。\n\n舉個例子，我會善用松岩潛獵者的爪子。如果你能幫我取得，或許我能教你如何善用更好的材料，來提高你的效率。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：進階高嶺製皮\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40193] = {title = "茅塞頓開", objective = "回艾蘇納找瑟蕾雅。", description = "<小伙子/小姑娘>，聽好了。你做出的東西都有改進的餘地，我只是還沒想到究竟要如何用這些鱗片來改進。\n\n也許你那幽靈般的精靈朋友可以幫你。如果她真的知道答案，也許你可以回來教我們。\n\n那一定會讓這家店財源滾滾。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40194] = {title = "回收的貨物", objective = "取得5個鎖甲貨箱。", description = "我兄弟所搭的那艘船上面也載了許多品質優良的鎖甲。你也知道的，巨人大概用不上那些鎖甲，只會把它們塞在洞穴的某處。\n\n如果你可以找回那些貨物，我可以向你解釋它們的製作工法。應該可以給你一點想法，幫你改善製程。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：進階艾蘇納製皮\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40195] = {title = "即刻救援", objective = "到歐宣諾海灣找到塔卓尼斯，並將鍊甲交給他。", description = "我的兄弟塔卓尼斯搭上了航向艾蘇納的船。海巨人襲擊了那艘船，還把我的兄弟擄走了。\n\n我相信他還活在那些可怕洞穴的某處，變成巨人的奴隸。拜託你讓他重獲自由。\n\n帶上這個，如果你遇到麻煩，它會保護他。小心不要反而被巨人給抓了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40196] = {title = "冒險渴望", objective = "和梅‧法蘭西斯談談她關於坐騎護具的想法。", description = "<name>！我最近跟坐騎商人梅‧法蘭西斯談過，她問我能不能製作坐騎護具，防止冒險者從坐騎上摔下來。\n\n我想請你去找她，進一步了解這個想法。\n\n談完之後再回來找我。或許我們可以一起解決這個問題。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40197] = {title = "必備材料", objective = "取得100張石皮皮革。", description = "製作這套護具，會用到很多皮革。我是說數量超乎想像的皮革。\n\n我會定出方案，解決組裝所有部件的問題。你就負責收集皮革。\n\n收集完成之後，們就可以開始製作了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40198] = {title = "有老鼠！", objective = "前往下水道奪回3份高嶺製皮圖樣。", description = "老實說，<name>，我有時候真的倒楣到了極點。\n\n赫魯最近送來了一個包裹，裡面有一些皮甲的製作圖樣。結果我一轉身，幾隻骯髒的老鼠跑了進來，把那些圖樣叼到下水道去了！\n\n也許在我們談話的當下，它們正在用圖樣做窩。拜託，<name>，能不能請你下去一下，找回一些圖樣？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：高嶺製皮專家\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40199] = {title = "為了皮革而跑", objective = "幫桑尼德找一根鐵撬。", description = "好消息，<name>！朗格姆的皮甲與鍊甲最近送來了一批鎖甲。\n\n品質是有史以來最好的，我很想讓你也看一下，不過我似乎弄丟了我的鐵撬，沒辦法打開木箱。\n\n如果你可以跑到他們店裡，幫我帶一根多的鐵撬回來，我們就能打開這個木箱，仔細研究裡面的東西。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：艾蘇納製皮專家\n\n您還會收到：\n\n鐵撬"}
MultiLanguageQuestData['tw'][40200] = {title = "同袍之誼", objective = "和魔法動物園商店中的『母獅』莉歐談談。然後回去找納姆哈。", description = "<name>，你喜歡寵物嗎？我超愛寵物，它們實在好可愛！\n\n但我不能這樣就滿足，我最大的心願是跟它們一起玩耍。\n\n我敢肯定魔法動物園的莉歐一定知道一些有趣的玩具。你應該去找她談談！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40201] = {title = "好玩意", objective = "製作寵物床墊的原型。", description = "好的，她的想法是一條牽繩、一張床，還有一個火圈？\n\n怎麼有種要開馬戲團的感覺。不管了，這些想法我都很喜歡，等到你準備好了，我們就馬上動工。\n\n要不你負責製作床，我來負責火圈的細節。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：寵物床\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40202] = {title = "最後一課", objective = "到高嶺找赫魯‧銳蹄。", description = "<name>，赫魯要求與你會面。從他的言語看來，他已準備好傳授你他所獲知的本地製皮奧秘。\n\n我很羨慕你，<name>。你能贏得他的尊敬，也讓我為你感到驕傲。\n\n去吧，祝你好運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40203] = {title = "過去的力量", objective = "將死亡之翼的鱗片交給赫魯。", description = "就像你知道的，護甲的耐久度取決於你的製作材料。\n\n很久以前，黑龍死亡之翼曾經棲息在這座山上。在他追逐力量的過程中，他的身體變得傷痕累累，於是他就讓其他生物製作金屬鱗片來縫合他的傷口。\n\n而他本身的鱗片則掉落在地上，無人聞問。取得一塊鱗片，帶回來給我。\n\n你必須使出渾身解數，才能完成這個任務。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：戰皮面具(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40204] = {title = "過去的進化", objective = "獲得5張石化蜥蜴獸皮。", description = "隨著我們做出更堅固的護甲，我們對抗的生物也會跟著進化，學習擊敗我們的方式。我們可以再做出更好的護甲，但它們還會再隨之進化並再度擊敗我們。\n\n數百年來，我的族人不斷對抗下方台地的石化蜥蜴。我們已完全適應了彼此。\n\n去吧，殺死那些石化蜥蜴，剝下牠們的皮帶回來交給我，我會告訴你牠們是如何演化的。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：戰皮手套(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40205] = {title = "尊重過去", objective = "前往高嶺四周的四座製皮架，聽聽它們的故事。", description = "我們記錄過去犯下的錯誤，為了有所警惕，不犯相同的錯。然而，記錄歷史不單純只是為了不要重蹈覆轍，也是為了頌揚我們的成就。\n\n高嶺四處散布著許多神聖場所，掛著像這裡一樣的銘刻皮革，訴說著過去的故事。\n\n前往這些場所，獻上你的敬意，學習其中的智慧。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：戰皮束褲(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40206] = {title = "前債已償", objective = "回艾蘇納找瑟蕾雅。", description = "天啊，我以前從沒聽說過鬼魂會寄信，結果真的有鬼魂寄了一封信來，實在嚇破我的膽。\n\n瑟蕾雅寄給你的，<小伙子/小姑娘>。如果我是你，我一定會立刻趕過去。一直讓鬼魂等的話，一定會不幸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40207] = {title = "秘法鱗片", objective = "跟藍龍軍團談談，取得一片他們的鱗片。", description = "根據我的經驗，龍鱗是我過去處理過最堅硬的材料。它的質地堅固耐久，很少人可以真正善用這種材料。\n\n我很想再次處理龍鱗，<name>。處在這種形態下，我已經被束縛在這個地方，再也無法體驗這個世界。\n\n我聽說藍龍軍團佔據了艾蘇納的部分地區。也許你可以跟它們談談，請它們割捨一、二片鱗片。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：鬥縛之握(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40208] = {title = "艾薩拉之眼：海洋鱗片", objective = "前往艾薩拉之眼並取得督軍帕傑許的鍊衫。", description = "我們第一次見面時，我提到了納迦，還有他們所製作的護甲。談到最高品質的護甲，莫過於納迦酋長身上穿的那套。\n\n有一個納迦酋長就鎮守在艾薩拉之眼，他的名字是督軍帕傑許，而他所穿的鍊衫正屬傳奇品質。\n\n擊退他的部隊，拿回他的護甲，我就會指導你更多艾蘇納的製皮工法。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：鬥縛戰盔(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40209] = {title = "大地鱗片", objective = "取得斧尾石化蜥蜴族母的鱗片。", description = "雖然皮甲本身就已經夠堅韌了，如果再加上鱗片，就更非同凡響。\n\n需要的鱗片數量取決於鱗片的種類，才能為穿戴者提供完整的防護。石化蜥蜴的鱗片是最堅硬的鱗片之一。\n\n當然，完全長成的石化蜥蜴鱗片最為堅硬。洛席恩村莊附近有個石化蜥蜴的巢穴。殺死族母，然後把鱗片帶回來給我。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：鬥縛護腿(等級2)\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40210] = {title = "善用光陰", objective = "告訴納姆哈你在艾蘇納跟夜精靈合作的事。", description = "很抱歉，<name>，我已經把我會的一切都教給你了。很高興我們能建立良好的夥伴關係，達成彼此的目標。\n\n去吧，跟你在達拉然的盟友分享你所學的一切。我很肯定他們一定迫不及待想知道。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40211] = {title = "惡魔血肉", objective = "前往蘇拉瑪爾尋找製皮大師。", description = "<name>，我們目前為止都還沒有好好去研究蘇拉瑪爾的生物。特別是那裡的惡魔。\n\n我當然不會稱讚它們，不過部分惡魔生物的皮特別厚實，也是不容忽視的事實。\n\n我們可以向惡魔獵人看齊，利用那些皮革作為對抗惡魔的利器。問題是，我壓根兒不知道惡魔皮該怎麼用。\n\n也許蘇拉瑪爾那裡有人知道…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40212] = {title = "選錯邊", objective = "殺死製皮者中的叛徒，菲歐里亞、塔利安和賽雅娜。", description = "他在那兒！不在那裡的那個人！他…他…\n\n等等…不，我很抱歉。我的腦袋最近經常一片混亂。自從我被逐出公會後，真實跟虛幻就有點分不清楚。\n\n如果你想在我徹底瘋狂之前向我求教，那就幫我個忙，殺死那些與惡魔為伍，把我逐出的背叛者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40213] = {title = "畜生橫行", objective = "取得5具惡魔獵犬屍首。", description = "我邀他喝茶，他明白其中的含意！他會看到皮偶，然後說「她什麼時候跑來這裡的？」\n\n我是說…抱歉，<name>。我的思緒又飄到奇怪的地方了。你想瞭解惡魔，那種擁有厚皮的生物？\n\n我被逐出之前，我看到這些野獸在我們的城市裡到處橫行。它們是所謂的惡魔犬。殺死它們，帶回它們的屍體。\n\n那時我們再來討論它們的毛皮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40214] = {title = "魔化鞣製", objective = "用製皮架為司多里斯製作一對護腕。", description = "聽好，我不確定什麼時候我的瘋狂人格又會再跑出來，所以我們速戰速決。\n\n你想學習如何製作用來對抗惡魔的護甲？遵照我的指示，你就能完美掌握整個製程。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖清單：魔化皮革製皮\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40215] = {title = "輕鬆拿坐騎", objective = "捕捉高大北境領角鹿。", description = "<name>，我很高興你來了。我要對你說實話：我一直瞞著你進行一項秘密計畫。看啊：石皮皮甲韁繩！現在，我們只需要找到值得這項傑作的坐騎。\n\n維酷人傳唱的許多歌曲，是關於一頭有無窮精力的領角鹿。找到牠，將韁繩鞍在牠身上，然後馴服牠。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n圖樣：領角鹿騎乘鞍座"}
MultiLanguageQuestData['tw'][40216] = {title = "天生的獵人", objective = "在松岩盆地狩獵野獸，幫助艾笛學會如何打獵。", description = "艾笛寫得一手好文章，但我從沒看過她拿獵槍。她非常希望學習打獵，但有誰聽過地精獵人啊？\n\n你似乎對應付業餘人士相當在行，或許你不介意讓她跟你一起打獵？跟著像你這樣技術高超的獵人，她會學到一些東西的。\n\n你最好先從小型獵物開始。我們可不希望讓她受到挫折。", progress = nil, completion = "你身上沒有彈孔，那表示艾笛的槍法沒有我想像中那麼差！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40217] = {title = "提供箭矢", objective = "到奈辛瓦里居所把一袋箭矢交給赫米特‧奈辛瓦里。\n\n已提供物品：\n", description = "有許多新來的旅人穿越這座山的山谷，但有些人對我們的傳統渾然不知。\n\n我們的領袖關心的是更緊急的事，但我和羅斯洛卻無法對最近來到盆地一帶的獵人坐視不管。\n\n他們用槍枝和器具打獵，完全遺忘了用弓箭打獵的技藝。\n\n我知道有些人就是只會用他們習慣的方法，但或許提供箭矢可以讓這些外來者也學著用我們的方法打獵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40218] = {title = "清償前債", objective = "與瑞特辛‧焰慍交談。", description = "我有一些急事要辦，不過不久後，我就會前往懼痕裂隙，協助你進行召喚。\n\n你應該警告瑞特辛最好保持距離。我是去那裡完成我承諾的事，可不是去跟那個把議會看得比自己的朋友還重的偽君子聊天的。", progress = nil, completion = "你的消息還沒傳來這裡，琪拉就先來了。她不久前剛來到這裡，但她顯然有意避開我的目光。\n\n你居然能夠得到她的信任，這是我辦不到的。有了她的幫忙，我們應該就可以召喚傳送門了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40219] = {title = "無懼死亡之翼", objective = "見證3道幻象。", description = "很久以前，胡恩‧高嶺就在這個地方挑戰偉大的死亡之翼。\n\n我們現在就透過先祖之眼來重現那一刻。\n\n在這趟靈魂之旅的下一站，就是要找出很久以前放置的三個火盆，才能踏著胡恩的腳步見證他的功蹟。", progress = nil, completion = "胡恩‧高嶺就是這樣來到這座山，解放死亡之翼的卓格巴奴隸，並進一步取得了卡茲格羅斯之錘。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40220] = {title = "棘刺之舞", objective = "在月翼淺灘擊敗3隻薊葉棘舞者。", description = "薊葉妖精完全瘋了。\n\n我懷疑他們可能是被一些心懷惡意的棘舞者所操控。\n\n拜託你了，森林之友，找出這些蠱惑人心的鬧事者，讓這片淺灘重歸和平。", progress = nil, completion = "這下討人厭的棘舞者應該不敢靠近了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40221] = {title = "展翼而飛", objective = "在月翼淺灘拯救8個受困的月翼。", description = "這些可憐的精靈龍倍受折磨！\n\n更糟的是，薊葉妖精無聊時，便會捕捉這些精靈龍，以供後續虐待為樂。\n\n我們決不容許這種行為。\n\n若你找到任何一隻受困的月翼，就釋放他們。", progress = nil, completion = "我代表月翼，謝謝你的幫忙。", rewards = "鴉衛戰靴夜谷便鞋擁棘脛甲黑革長靴鴉衛腿甲夜谷護腿擁棘護腿黑革馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][40222] = {title = "鬼母的寶典", objective = "取得魔秘寶典。", description = "看到那個巨大的山洞了嗎？裡面有一隻力量無窮的鬼母。\n\n這當然不是什麼好消息。好消息是她身上帶的東西。\n\n她顯然在守護某種惡魔秘密。她在裡面進行燃燒軍團儀式，然後抄寫在一本書上。\n\n我們需要那股力量！我們需要她的寶典！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "力量統御者手套力量統御者手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][40224] = {title = "深淵之錘", objective = "使用瑟拉贊恩的傳送門前往破碎深淵。陪伴風暴召喚者米爾拉和索爾一起去取回末日錘。", description = "<索爾正專心聽著。>\n\n你找到它了！末日錘落入破碎深淵…但燃燒軍團還是快我們一步。如果我們加快腳步，就能追上惡魔蓋斯勳並奪回末日錘，避免這個國度繼續腐化下去。\n\n瑟拉贊恩會開啟直接通往那裡的傳送門。出發吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40225] = {title = "重整議會", objective = "和諾柏多交談，並取得陶土議會領袖的地位。", description = "和諾柏多交談，接受你在議會中的地位，<name>。在你的領導之下，陶土議會將再度興起！\n\n傳說中的艾澤拉斯之心就座落在此處的岩石中，可以當作我們的行動據點。或許靠著你的神兵武器之力，可以發掘其隱藏的位置…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40227] = {title = "居心叵測", objective = "在泰爾亞諾與泰德里斯‧羽歌交談。", description = "蘇拉瑪爾已經迷失了。\n\n我們的領袖被籠絡，接受軍團做為我們的盟友。我們本應是英雄、守護者。沈睡此地的人啊，我們再也沒有他們的風骨了。我無法與他們同住。\n\n但若切斷與夜井的聯繫，我們就會凋萎、退化成毫無心智的個體，毫無自由及尊嚴可言。連這裡都見得到…\n\n我拒絕這兩種選項，輾轉來到此處。我會找到第三條路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40228] = {title = "偵察行蹤", objective = "放出信號彈標明憤怒之翼的位置之後，殺掉牠。", description = "你證明了地精也能舉槍射擊，這不是一件簡單的事，不過真正要考驗艾笛的狩獵技巧，就要看她是否能成功追蹤一頭行蹤飄忽的野獸。\n\n傳言有隻以掠食維生的鵬鳥在盆地上空盤旋，牠受到鷹身人魔法的詛咒，但沒有人近距離看過。\n\n拿著這個信號彈，當你看到那頭鵬鳥時將它射向天空。我們看到信號後就會派遣狩獵團，打下那隻龐然大鳥！", progress = nil, completion = "我絕對不會忘記這次狩獵！\n\n艾笛會寫下我們今天的探險故事，但很少人會相信地精可以解決一隻比她大上十倍的猛禽。", rewards = "彈痕累累的胸鎧彈痕累累的護胸彈痕累累的外衣彈痕累累的長袍松岩追蹤者襯肩松岩追蹤者肩墊松岩追蹤者肩衛松岩追蹤者重肩甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][40229] = {title = "步入黑暗", objective = "在石暗岩洞與納瓦羅格交談。", description = "我的族人面臨的威脅已經平息，我想這是把你介紹給我族人認識的時候了。\n\n在石暗岩洞跟我碰面，讓你看看我們住的地方。", progress = nil, completion = "歡迎來到寒舍。你可以隨意行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40230] = {title = "喔，威猛的蝦鉗！", objective = "和莫奇的心靈同步，殺死克勞戴休斯。", description = "穴苔龍蝦人的首領克勞戴休斯，不斷下令對穴苔村進行掠奪，偷走小小魚人當點心。\n\n這樣下去不是辦法。為了證明他們的力量，莫奇和蝌蚪們也要消滅他！\n\n這是魚人的工作。\n\n使用莫奇的蛋，和他的心靈同步，讓他瞧瞧你的厲害！", progress = nil, completion = "你做到了！莫奇會是這裡年輕魚人世代的好領袖。\n\n雖然失去我的小夥伴有點感傷，但總有一天要放手的。", rewards = "河豚爆炸護脛河豚爆炸腿甲河豚爆炸裹腿河豚爆炸護脛層疊黏液重肩甲層疊黏液披肩層疊黏液肩衛層疊黏液肩墊您會收到：\n\n"}
MultiLanguageQuestData['tw'][40235] = {title = "阿伯加托仲裁者", objective = "克拉克拉克要你帶14958個頂尖水晶給他。", description = "天槌的懶惰鬼不相信他們可以出去了。我？我要趁這個時候好好弄一票。你快點弄一堆頂尖水晶來給我，我就能快點離開這個笨蛋島。我要的數量可是很精確的！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿伯加托石簇"}
MultiLanguageQuestData['tw'][40236] = {title = "黎明之光", objective = "與『威震八方』老章作伴，等待大師們宣佈消息。", description = "你能活下來真是奇蹟啊，<name>。高宗師的運氣就沒這麼好了，他的魂魄現在與先祖一同安息了，真是讓人不勝唏噓。\n\n我們現在要為那座破損的廟宇，還有我們的組織尋找新的領袖。我和其他大師商討過了，而且大家的想法都一樣。\n\n我們一致推舉你為新的領袖，<name>。你展現了無比的力量、智慧、勇氣與仁慈。\n\n請和我們一同前往廟宇，我們會在那裡宣佈我們的決定。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n禪定歸宗\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40237] = {title = "工作停擺", objective = "將20000個頂尖水晶交給罷工的鋼鐵工人。", description = "我們已經受夠了！鑄造場的工作環境太差了，到處都是火焰、歐格隆、火元素，然後還有闖來搶東西的冒險者！而且熱得要死！\n\n我已經忍無可忍！我和一些兄弟準備要開始罷工，但是我們需要幾個壯丁來保護我們。可是唯一答應我們的天槌蠢蛋又只收頂尖水晶而已。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n元素符文"}
MultiLanguageQuestData['tw'][40238] = {title = "粉碎敵計", objective = "在破碎之地摧毀三個魂匣水晶。", description = "我們墜落之後，它們早就已經在等著了，我們能做的就只是建立這個小哨站。\n\n它們現在還在從我們陣亡的同胞身上汲取靈魂，以增強它們的攻擊火力。\n\n摧毀它們的魂匣水晶，讓我們的同伴重獲自由，回到聖光的懷抱。\n\n完成以後，到戰場上找伊梅拉。她一直不見人影，但我相信她一定還活著。", progress = nil, completion = "做得好。它們還會再回來，但是我們可以利用這個空檔。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40241] = {title = "同袍之誼", objective = "和魔法動物園商店中的瑟雅談談。然後回去找納姆哈。", description = "<name>，你喜歡寵物嗎？我超愛寵物，它們實在好可愛！\n\n但我不能這樣就滿足，我最大的心願是跟它們一起玩耍。\n\n我敢肯定魔法動物園的瑟雅一定知道一些有趣的玩具。你應該去找她談談！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40244] = {title = "穿戲服的怪人", objective = "與塔瑪菈交談，飛往船骸灣。", description = "嗯，我們在海岸打獵時，碰到了這個穿戲服的怪人。他說他想跟魚人一起在水中生活…不過我很確定他腦袋不太對勁。\n\n我們回營地時，留了一位成員盯著他…想去看看嗎？\n\n你可以請那裡的塔瑪菈送你一程。", progress = nil, completion = "哈囉，冒險者！你是來幫助我跟莫奇的嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40247] = {title = "尋求協助", objective = "請卡德加提供軍團通報器的能量來源。", description = "凱莉亞‧魔魂是我們當中的佼佼者…但她卻加入了燃燒軍團的陣營。\n\n奧達奇戰刃在她手上，那是古老種族最偉大的勇士用來撕裂靈魂的武器，那名勇士只曾敗在薩格拉斯手下。\n\n我們派了一支隊伍去追蹤凱莉亞，但他們已經有段時間音訊全無。捷斯已經把軍團通報器修好，方便我們彼此聯繫 - 現在只缺能量來源。\n\n可以請你向卡德加求助嗎？我們在這個世界沒什麼朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40249] = {title = "我們必將復仇", objective = "從凱莉亞‧魔魂手上取得奧達奇戰刃。", description = "我們不會把部隊派到破碎海岸附近，因為這樣只會被打得落花流水。\n\n我覺得這件事最好由你親自處理 - 因為我們在戰場上的表現都比不上你。\n\n可以的話，請救出艾萊莉和她的人，不過奧達奇戰刃在這場戰爭顯然比人有用多了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40253] = {title = "阻止古爾丹！", objective = "進入背叛者牢獄，殺死粉碎者和大鎚，並奪取他們的魔化能量。", description = "自從在黑暗神廟擊敗伊利丹後，我們把他的屍身搬來這裡，永遠埋藏在看守者鐵獄之中。\n\n不過，古爾丹突破了我們的防線，企圖偷走背叛者的屍身。\n\n就算死了，燃燒軍團還是可以利用伊利丹的屍身。絕對不能讓古爾丹得逞。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n惡魔尖刺\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40254] = {title = "在烈火中鍛鑄", objective = "殺死伊姆婪斯並奪取他的力量。", description = "伊姆婪斯是讓人聞風喪膽的惡魔，他率領燃燒軍團的部隊征服遙遠的異界，最終成為當地的統治者。\n\n不過他卻被看守者抓了起來，就關在我們左邊的囚室裡。但像他這樣惡魔是關不了多久的。\n\n這個惡魔的力量對於能夠擊敗他的惡魔獵人而言，無疑是極具價值的獎勵。擊敗惡魔的人就能獲得超乎想像的力量。\n\n我相信那個人就是你，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n扭曲之心"}
MultiLanguageQuestData['tw'][40255] = {title = "邁向自由的唯一障礙", objective = "殺死巴斯提萊斯並奪取他的力量。", description = "我們剩下的同伴已經殺出一條血路，到前方的最後一個房間去了。\n\n通往鐵獄出口的唯一障礙，只剩下巴斯提萊斯 - 這場惡魔入侵的領導者。\n\n殺死他，取得他的力量，奪回我們的自由。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n殘影\n\n您還會收到：\n\n扭曲之心"}
MultiLanguageQuestData['tw'][40256] = {title = "邁向自由的唯一障礙", objective = "殺死巴斯提萊斯並奪取他的力量。", description = "我們剩下的同伴已經殺出一條血路，到前方的最後一個房間去了。\n\n通往鐵獄出口的唯一障礙，只剩下巴斯提萊斯 - 這場惡魔入侵的領導者。\n\n殺死他，取得他的力量，奪回我們的自由。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n扭曲之心"}
