MultiLanguageQuestData['tw'][40300] = {title = "葬儀用品", objective = "幫泰德里斯取回葬儀用品。", description = "屏障升起之前，我常來這裡。在執政議會和大博學者爭執、談論政治的時候，我在這裡看著管理者進行儀式，向死者致敬。\n\n我希望能向先人作最後一次致敬。我要往陵墓去了。如果過了這麼久的時間，還找得到聖油、喪衣和薰香，就拿來給我吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40306] = {title = "最後一章", objective = "找到百草全書。", description = "我旅途的下一步需要一本書，但是我想我無法坐視這裡如此殘破不堪。\n\n你去幫我找書，我來把紀念堂整理好。書的名字叫做百草全書，它應該在主廣場附近的圖書館中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40307] = {title = "戰刃的下落", objective = "取回萊安娜‧暗愁的戰刃。", description = "我奉命前來殺死埃雷達爾惡魔阿佐朗。在我潛入時，在魔化蝙蝠上遭到擊落，因此被抓。\n\n我開門見山地說，<name>。阿佐朗計畫用燃燒軍團的指揮艦摧毀達拉然。\n\n要想阻止他的話，我還需要被擊墜時遺失的戰刃。我想自己拿回來，但我被監禁太久，還很虛弱。\n\n到北側的火山口，也就是我被擊墜的地方尋找戰刃。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40308] = {title = "記憶的碎片", objective = "取回15個泰爾亞諾殉葬品。", description = "<美麗的精靈葬禮瓦罐破碎散落一地，顯然是被人破壞，但瓦片上卻沒有鷹身人的利爪痕跡。>\n\n<你發現沿著碎片可以一路導向一座洞窟。罪魁禍首肯定藏身其中。如果能安全取回這些古物，泰德里斯肯定會有興趣。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n泰爾亞諾先祖石板"}
MultiLanguageQuestData['tw'][40310] = {title = "船難俘虜", objective = "在寵物對戰中擊敗船難俘虜。", description = "我一生都在扮演寵物，為其他人出戰。現在該是我翻身當馴獸師的時候了！死亡的最大好處就是我可以一直當馴獸師！您會收到：\n\n\n\n等級 70–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 70–80磨亮的寵物吊飾\n\n等級 51–70亮晶晶的寵物吊飾"}
MultiLanguageQuestData['tw'][40315] = {title = "路到盡頭", objective = "在泰爾亞諾高處與泰德里斯對話。", description = "我再也無法稱蘇拉瑪爾為家了，我也拒絕成為凋萎的怪物。我已無處可歸，你懂嗎？\n\n我們只缺最後一項材料就能完成藥劑了。你會幫我的，對吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40316] = {title = "尖嘯峭壁", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][40319] = {title = "最後的材料", objective = "找到菈塔娜的弓。", description = "藥劑完成了，<name>。很快的，我們的旅途就要結束了。我還有最後一件事要你幫忙，然後我就給你報酬。\n\n內人的弓還留在這裡，但我找遍四處都不見蹤影。弓裡蘊藏著魔法。\n\n我擔心它被某個怨魂拿走了，但是要拿起這樣的一把弓需要極大的力量，小心點。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40320] = {title = "血的羈絆", objective = "在深濁洞窟內找到卡塔琳、弗喬里克和斯多克法。", description = "你就是讓托莉爾整天嚷嚷的傢伙？你說不定能幫我。\n\n我出發尋找索隆迪爾的時候，並不是一個人來的。還有三名效忠索隆迪爾的維酷人跟著我。現在如你所見，只剩下我了。\n\n找到我的族人，<name>。\n\n我不敢想像他們也遭遇跟索隆迪爾一樣的下場。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n血羈絆烙印"}
MultiLanguageQuestData['tw'][40321] = {title = "羽歌的救贖", objective = "殺掉崖巢族母。", description = "我必須承認，我沒有完全誠實地對待你，<name>。我本想要喝下藥水，回到內人身邊。\n\n但連她都不得安息…我不能再讓她失望。我要活下去，竭盡所能阻止即將來襲的災難，才有資格到她的左右。\n\n跟我來，年輕人。讓我們解決鷹身人女族長，並讓泰爾亞諾恢復過往的光榮。總不能浪費這毒藥，對吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n纏繞著愛的弓箭"}
MultiLanguageQuestData['tw'][40324] = {title = "秘法共融", objective = "餵食瑟倫300份上古法力。", description = "克達納茲嘗試與凋萎者建立連結的所有實驗都失敗了，有些實驗甚至讓他們變得更加危險。\n\n直到他發現瑟倫。\n\n他的秘法精華，也就是夏多雷的靈魂所在，受過某種特殊事物的影響。但到底是什麼？\n\n藉由將我與瑟倫的秘法精華織在一起，我能夠建立同理連結。這個連結會讓他的靈魂現身在我們面前，雖然只是殘存的一小部分。\n\n我們需要餵食他法力，很多的法力，才能開始。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40325] = {title = "記憶中的光景", objective = "協助薩莉瑟拉建立與瑟倫的秘法共融。", description = "瑟倫受到自己內心思緒擺佈。不管是什麼，那可能都難以控制。\n\n我會需要你幫忙理清即將看見的幻象，請準備面對任何挑戰。\n\n幸運的話，我們或許能夠查明瑟倫為何如此特別，以及他過往的記憶是否還殘存。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40326] = {title = "四散的記憶", objective = "調查6頁克達納茲的筆記。", description = "<隨著你的指尖掠過紙張上優雅的符號，你心中響起了與符號相應的發音。\n\n看來夜裔精靈利用法術發明了更簡單的紀錄方法。\n\n秘法師克達納茲肯定就在這附近做事。這附近肯定還有他散落的筆記。>", progress = nil, completion = "&lt;一個裝著許多頁技術筆記的袋子。快速翻閱後，你找到克達納茲的最後一篇記錄。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40327] = {title = "強度測試", objective = "護送塔卓尼斯到安全之地。", description = "好了，如果我們要離開這裡，我們就必須搞定納迦和海巨人。\n\n對於像你這樣厲害的人而言，納迦應該不是什麼大問題，不過那些海巨人實在強得難以想像。\n\n帶我安全離開這個洞穴，我就能自己回家。\n\n希望瑟蕾雅幫我做的這件護甲足以讓我撐到逃出生天為止。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：鬥縛鍊衫(等級2)"}
MultiLanguageQuestData['tw'][40328] = {title = "比死還可怕的下場", objective = "打開8個靈魂引擎的牢籠。", description = "燃燒軍團留下囚犯，絕對不是出於憐憫。\n\n死亡只是毀滅肉體…若你被燃燒軍團抓到，他們會摧毀你的靈魂。\n\n燃燒軍團藉由獻祭靈魂來驅動他們的惡魔戰爭兵器，靈魂引擎就是用來存放那些已經割取的靈魂。\n\n雖然已有無數靈魂在靈魂引擎中逝去，你依然能夠拯救倖存者。\n\n快點，在萬劫不復之前釋放他們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40329] = {title = "戰寵馴獸師：德拉諾之霸", objective = "擊敗5個德拉諾的戰寵訓練師。", description = "雖然你已多次證明了自己的能耐，但是德拉諾的荒野卻是更高層次的挑戰。擊敗以下這些藏身在野外的戰寵馴獸師，證明你才是最頂尖的戰寵大師：格古隆德的辛蕾‧亮刃，阿拉卡山的維夏爾，納葛蘭的『可怕的』塔爾，塔拉多爾的泰菈露妮，霜火峰的珈歌菈，或是影月谷的艾絲蕾。還有，你也可以挑戰會去拜訪你要塞的『收藏家』厄莉絲和庫拉‧雷蹄。\n\n戰勝他們，證明你才是德拉諾的戰寵之霸。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n無瑕的戰鬥訓練石\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40331] = {title = "沙許塔爾之牙", objective = "從蒼風灣的沙許塔爾納迦身上取得8個沙許塔爾之牙。", description = "若是索隆迪爾和納迦奮戰時我在他身邊，現在他說不定還活著。\n\n我要讓這些臭蛇會後悔從巢穴裡爬出來！\n\n殺了他們還不夠。不！我要用納迦遼牙的項鍊紀念索隆迪爾！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40332] = {title = "海灘篝火", objective = "在蒼風灣收集6根漂流木，替索隆迪爾統領辦一場火葬禮。", description = "別讓我的…屍體埋沒在…淤泥中。\n\n把我的肉身…火化。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40334] = {title = "漁夫的藥水", objective = "收集4顆斧尾石化蜥蜴的斧尾之眼、一個沙許塔爾納迦的沙許塔爾氣囊，以及一份蒼風海灣的海妖娜茲祖爾的海妖之血樣本。", description = "若你像我們一樣憎恨這些毒蛇，我請求你繼續與他們對抗。\n\n你必須在他們水中的領域內與他們戰鬥。我看你身上沒有魚鰓，所以我們要調製維酷漁夫的老藥方。\n\n材料在這附近隨處都找得到，只要你不怕弄髒手。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n海行藥水\n\n您還會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40336] = {title = "力挽狂瀾", objective = "建造一座臨時弩砲，殺死沙許塔爾遺跡中的海潮祭司沙許塔爾。", description = "海潮祭司已撤退到精靈廢墟，療養她的傷勢。\n\n在她身邊一定有保護她的護衛。要擊敗她，就得擊潰她的防禦。\n\n用你取得的零件建造一座弩砲，一舉把她解決掉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n海潮祭司的附魔珍珠"}
