MultiLanguageQuestData['tw'][40364] = {title = "泡泡危機", objective = "收集一塊針刺珊瑚，然後前往蒼風灣救出5名維酷人俘虜。", description = "<class>！海巨人已經吃掉我一半的同胞。\n\n困在這些該死的泡泡中，我們毫無生存的希望。我懇求你幫助我們逃離這裡。\n\n要注意，這些泡泡相當堅固，你需要非常尖銳的東西才能戳破它們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40368] = {title = "烏龜之力", objective = "收集7枚發光的龜鱗。", description = "為了找到並淨化腐化來源，我需要能聚集元素力量的物品。\n\n這附近的烏龜具有可以聚集並強化牠們天生魔法的鱗片。帶一些龜鱗回來給我，我們就能馬上淨化這些水元素！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一片強化的蚌殼"}
MultiLanguageQuestData['tw'][40370] = {title = "淨化不潔", objective = "擊敗蒼落守護者之中的腐化。", description = "<race>，你感覺到了嗎？舞台已經搭好，就等我們將一切導向正軌。\n\n在你離開這段時間，我追蹤了支配這片水域的元素長者。它的名字是蒼落守護者，就住在泰爾亞諾底下的水道。帶著儀式法器，它能在戰鬥中助你一臂之力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n蒼墜精華"}
MultiLanguageQuestData['tw'][40373] = {title = "新的方向", objective = "在凱恩和奧翠司當中選一個。", description = "<name>，身為伊利丹大人不在時的伊利達瑞領導者，你必須選擇你的副指揮官。\n\n凱恩或奧翠司。你只能選擇一個。\n\n選中的人會成為你的親信，他們的立場將會影響我們伊利達瑞未來的方向。但不論你選誰，我們的使命永遠不會改變。\n\n如果你需要瞭解我們的過去，請凝視審判之池。永遠別忘使我們成為惡魔獵人的犧牲。決定好人選之後，就來告訴我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "理念確認之盔理念確認頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][40378] = {title = "伊利達瑞援軍：灰舌", objective = "啟動燃燒軍團傳送門，召喚你的灰舌部隊。", description = "伊利丹大人指名讓你全權負責。現在，我們需要集結伊利達瑞的其他戰力。\n\n前面還有三道燃燒軍團傳送門。啟動傳送門，伊利達瑞就會從黑暗神廟傾巢而出。\n\n如同大多數燃燒軍團所造的物品，傳送門的動力來源是靈魂。我想我們剛才提供的靈魂足以啟動第一道傳送門了，對吧？我們召喚灰舌部隊過來吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40379] = {title = "伊利達瑞援軍：考斯卡", objective = "把一個靈魂餵給燃燒軍團傳送門啟動器，再用它來召喚考斯卡部隊。", description = "下一道傳送門位於熔岩之岸。我們的考斯卡部隊正在另一側的黑暗神廟那裡待命。\n\n我個人是不會選擇召喚納迦盟友，不過納迦領袖曾經向伊利丹大人宣示過忠誠。我們就等著看吧。\n\n我們要想辦法為傳送門提供動力。就跟上個傳送門一樣，靈魂是其能量來源。\n\n<賽維斯在說這些話時，『噬魂者』艾萊莉露齒而笑。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40384] = {title = "獵人的需求", objective = "到達拉然和艾瑪芮爾‧影衛交談。", description = "老鷹腿上綁了一封短信給你：\n\n\n\n向軍團展開反擊的時刻來了。\n\n盡快到達拉然的獵人地帶與我會面。\n\n-艾瑪芮爾‧影衛您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40385] = {title = "暗影中的長矛", objective = "獵殺高嶺之禍。", description = "多年以前，一隻腐化的夜刃豹不斷獵食我的族人。我們的酋長多羅‧高嶺帶著猛禽之爪去追殺那隻野獸，從此一去不返。\n\n我聽說現在有一隻可怕的夜刃豹潛伏在斯鐸海姆的迷霧之中。我的兄弟和我認為那就是我們的世仇。\n\n那把武器一定也在那裡！如果我們殺掉那隻野獸，取回長矛，對於對抗燃燒軍團一定有莫大幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40388] = {title = "胡恩之戰 - 影歌", objective = "在戰場上和亞羅德‧影歌碰面。", description = "在下面的戰場上發號司令的人我相信你應該很熟悉。\n\n亞羅德‧影歌對你推崇至極，他邀請你和他一塊共赴戰場。\n\n他有幾個計畫，有辦法結束這場戰鬥。", progress = nil, completion = "很高興能見到你，偉大的盟友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40390] = {title = "神聖之地", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40391] = {title = "帶我去見你的領導者", objective = "在蘇拉瑪爾和卡德加碰面。", description = "<name>，很高興你來了。\n\n這名…大法師卡德加發現了我的訊息並且召開了會議。\n\n他希望能盡快在城市的入口處跟我們碰面。\n\n你能跟我一起前往嗎？我有異樣的預感，他不會是一個人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40392] = {title = "神射手的召喚", objective = "從卡薩斯平臺搭乘角鷹獸飛往破碎海岸，與凡蕾莎‧風行者碰面。", description = "時間寶貴！如果艾蘭里亞和薩斯朵拉落入燃燒軍團手裡，失去他們只是早晚的問題。\n\n你要是準備好了，就去破碎海岸和風行者遊俠將軍會合。\n\n她把自己的角鷹獸留給你，讓你飛到那邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40395] = {title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", objective = "您會學到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n時間之道知識\n\n下列法術會施放在您身上：\n\n跳跳巨兔妖尖叫聲\n\n您還會收到：\n\n時光扭曲徽章"}
MultiLanguageQuestData['tw'][40400] = {title = "隱密行動", objective = "與凡蕾莎‧風行者交談。", description = "你一直是深受信賴的聯盟英雄，<name>。而且就像我們其他人一樣，你遭遇了無數困難險阻才走到這一步。\n\n現在，我必須要求你做更艱困的事。你願意聽我說完嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40401] = {title = "重蹈覆轍", objective = "找到走私者。", description = "我得回到蘇拉瑪爾。\n\n我是被冤枉遭到流放的！我沒辦法在這種地方生存。我需要夜井的能量…\n\n我前幾天看到刻在牆上的訊息，在水之庭園內有某人能夠協助把人偷渡進城裡。\n\n信息寫說「我們將能再次飲用夜井之水」。\n\n如果再被守衛逮到，我就沒救了。你可以幫我找到這些人嗎？等我回到城裡，一定會回報你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40402] = {title = "隱密行動", objective = "聆聽凡蕾莎‧風行者的故事。", description = "如你所知，我與部落勢不兩立。那些獸人…奪走了我的一切。讓我家破人亡。\n\n但我親眼見證了你的英勇作為，<name>。我看到你一再為艾澤拉斯挺身而出。而且就像我們其他人一樣，你遭遇了無數困難險阻才走到這一步。\n\n現在，我必須請你再次出手。你願意聽我說完嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40403] = {title = "隱密行動", objective = "聆聽凡蕾莎‧風行者所講述的事。", description = "我下了很大的決心，才決定尋求血精靈的幫忙。你的首領對我家人和許多人所做的犧牲視而不見。\n\n但我親眼見證了你的英勇作為，<name>。我看到你一再為艾澤拉斯挺身而出。而且就像我們其他人一樣，你遭遇了無數困難險阻才走到這一步。\n\n現在，我必須請你再次出手。你願意聽我說完嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40408] = {title = "傳說中的武器", objective = "選擇一種你想要的神兵武器。", description = "在聚會中，我們討論出幾把蘊藏強大力量的武器。只要交給合適的人，這些神器就能讓我們和燃燒軍團一較高下。\n\n不過我們可不能同時追查所有武器的下落。要是我們分散兵力，可能會讓敵人各個擊破。我們必須決定要集中資源取得哪把武器。\n\n這就是我請你過來的原因，<name>。作為我們最偉大的勇士，你得理性思考，決定我們的下一步。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40412] = {title = "阿佐朗非死不可", objective = "在魔魂堡擊敗阿佐朗。", description = "要不了多少時間，燃燒軍團就會發現你溜上船了。\n\n警報響起以後，無數的燃燒軍團部隊就會試圖從傳送門登上船。\n\n但我不會讓他們得逞的。\n\n我會守著這個傳送門，直到你回來為止。殺死阿佐朗並摧毀他的戰艦，我們就靠你了。\n\n我們時間不多了…你得快速出擊，別手下留情。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n挖掘出的貴族神器"}
MultiLanguageQuestData['tw'][40415] = {title = "美好時光", objective = "告訴納姆哈你在高嶺跟牛頭人合作的事。", description = "你懂得入境隨俗，成功吸收了我們所能傳授的所有知識。<name>，快去吧，向那些對抗燃燒軍團的人宣揚我們的工法。\n\n也許這能夠扭轉這場世界大戰的局勢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40417] = {title = "前進塔南森林！", objective = "到你要塞的議事廳和大酋長沃金交談。", description = "現在最重要的是把所有心力投注在塔南森林，在那裡建立據點，不要因為其他事情分心。\n\n大酋長正在議事廳準備接見你，聰明人是不會讓他等太久的…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40418] = {title = "前進塔南森林！", objective = "到你的要塞市政廳，和瓦里安‧烏瑞恩國王交談。", description = "現在最重要的是把所有心力投注在塔南森林，在那裡建立據點，不要因為其他事情分心。\n\n國王帶著隨扈正在市政廳準備接見你，讓他等太久恐怕不太明智…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40419] = {title = "救援任務", objective = "穿過傳送門，救出艾蘭里亞‧風行者。", description = "惡魔向我們透漏了開啟傳送門的方法，通向艾蘭里亞被俘之處。你跟我可穿越傳送門，調查惡魔所言是否屬實。\n\n為防有詐，魔導師日望給了我一枚傳送石，可將我們送回達拉然。\n\n這種惡魔魔法對魔導師是一種禁咒，我們動作要快。準備好就跟我說一聲，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40424] = {title = "絕望之旅", objective = "沿著路燈走，帶埃亞卓斯回去見艾斯托里。", description = "城市的入口戒備森嚴，他一定有其他路能溜進去。\n\n幸好有這酒，讓我還有足夠力量去找他。我擔心我如果受到攻擊，會沒辦法防禦或是逃跑。\n\n請陪我同行，<race>。你和這位艾斯托里是我活命的唯一機會。\n\n我記得我離開城市的時候，是沿著燈走到這裡來的。跟著路燈走，應該就能走回去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n埃亞卓斯的附魔誕生石"}
MultiLanguageQuestData['tw'][40469] = {title = "最終準備", objective = "取回6個藏匿的補給品。", description = "為了我們的蘇拉瑪爾之旅，我們需要補給品。你們兩個像現在這樣待在車裡，可不是我們停在大門這裡補給的目的，對吧？\n\n水之庭園是社交和休憩的場合，在巡邏隊過來之前，可以趁空檔儲藏些法力酒和食物，之後再回來拿。\n\n這事就交給你了，拿些補給品回來給你朋友，然後到城市北方的廢墟和我會合。我們馬上就可以出發了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40470] = {title = "生活的品質", objective = "跟隨埃亞卓斯。", description = "我好擔心，<name>。我們就快回到家了，就快要得救…\n\n艾斯托里說他知道接下來的路，可以安全送我們回去。我相信他，但既然你為了護送我們做了那麼多，能請你好人做到底嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40495] = {title = "烏薩萊許，逆風收割者", objective = "前往暮色森林的密斯特曼托莊園開始搜尋逆風收割者。", description = "書上說黑騎兵最後出現在一處名叫密斯特曼托莊園的地方。如果好朋友能找到那些騎兵，那他就能得到烏薩萊許！\n\n卡萊德斯會在這等你回來。朋友，去找烏薩萊許吧！", progress = nil, completion = "我的選擇不多。我無法獨自面對黑騎兵的另一次埋伏，而你的力量顯然相當強大。\n\n我會幫忙找你要的那把武器，但前提是你必須協助我，把他們搶走的其他東西物歸原主。\n\n就這樣說定了吧，&lt;class&gt;？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40515] = {title = "與靈魂同行", objective = "與靈行者黯角交談。", description = "你在河彎拯救的那位靈行者，他在抵達之後讓人越來越受不了。他堅持一定要讓你看看我們的處事之道，你才好面對接下來發生的事。\n\n然而，就算以靈行者的標準來看，他也是個怪人。\n\n即使如此，只有笨蛋才會忽視他的智慧。拜託你，在你有空的時候去和他談談。", progress = nil, completion = "你讓梅拉笑了。我這好像是…第一次看她笑？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40517] = {title = "雄獅之殞", objective = "把瓦里安國王的信交給安杜因國王。", description = "回來以後我還沒有離開過這艘船的甲板。艦隊必須做好開戰的準備。我不知道我們的戰場在哪裡，不過等到命令一下來，我們就得立刻出戰。\n\n老實說…我需要暫時逃避現實。其他人正在向瓦里安憑弔告別，不過我…我沒有勇氣去面對他的靈柩。面對他的兒子。\n\n瓦里安曾把他寫給安杜因的信交給我。拜託，請代替我把信交給他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40518] = {title = "破碎海岸之戰", objective = "搭乘盧梭船長的船前往破碎海岸。", description = "<name>，戰艦在碼頭的另一端等著。希望你的武器能讓你橫掃戰場。\n\n大酋長已經降落了。我猜你只要跟著惡魔的血跡走就好。", progress = nil, completion = nil, rewards = "部落先鋒磨骨錘部落先鋒長弓部落先鋒匕首部落先鋒長柄斧部落先鋒速刃部落先鋒戰錘部落先鋒法杖部落先鋒戰斧部落先鋒法師之刃部落先鋒裂斧"}
MultiLanguageQuestData['tw'][40519] = {title = "軍臨天下：軍團重返", objective = "到暴風港去找徵募員小李。\n\n已提供物品：\n", description = "聯盟的英雄，我在艾澤拉斯最黑暗的時刻寫了這封信給你們。燃燒軍團從地獄深淵回來了。\n\n我們的艦隊馬上就會航向破碎群島。如同一把巨大的長矛，我們將會刺穿燃燒軍團的防線，將它們趕回虛空。\n\n你的船隻正在暴風港等候，請動作快。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40520] = {title = "見證過去", objective = "收集風焰之瓶、姆莎之淚和暗碎水晶。", description = "我想讓你親眼看看胡恩‧高嶺在先祖之戰某場戰役中的英勇表現。\n\n為此，我需要非常特別的材料。這些東西不難取得，你可以在雷霆圖騰附近找到所有的材料。", progress = "我們在山林中認識了大地、風和水的魔法。", completion = "啊，這些東西完全符合我的需求。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40522] = {title = "部落的命運", objective = "前往葛羅瑪許堡，瞭解部落的未來。", description = "不知道還有沒有人從破碎海岸的那場血戰中生還。如果不是希瓦娜斯女士…\n\n薩魯法爾霸王要求你前往葛羅瑪許堡。他沒說原因…不過他堅持要你去見他。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40523] = {title = "閃亮亮的朋友", objective = "向提摩西‧瓊斯和斯敏克絲‧玻璃眼自我介紹。", description = "很抱歉，<先生/女士>，你確定走對商店了嗎？在這裡，我們只交易最上等的珠寶。\n\n噢，我懂了，你是一位珠寶工匠。或許我們可以共事。\n\n請向我的助理們自我介紹，他們才會瞭解你是何方神聖，以及能提供什麼服務。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n軍團珠寶設計"}
MultiLanguageQuestData['tw'][40524] = {title = "一枚很熟悉的戒指", objective = "在艾蘇納的崩塌宮殿附近找到亞狄爾祭壇，並閱讀其傳說。", description = "<name>！讓我們來談些亮晶晶的東西吧。我在找一個戒指。\n\n你看，在艾蘇納的精靈們曾經都是珠寶設計的大師…或，至少他們是如此聲稱。書本裡都在討論一個名為「法隆迪斯指環」的戒指，去到處問問不會怎麼樣吧。\n\n我們去艾蘇納吧。跟你打賭，我會比你早到！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40525] = {title = "讓指環合而為一", objective = "找出法隆迪斯指環的三個部件，帶回去給提摩西‧瓊斯。", description = "我喜歡我們相處的方式，<name>。你這麼有衝勁，就負責出力！我負責出主意！\n\n我想下一個任務只有靠你了。試著找出這些戒指，或是任何從魚人身上拿回任何剩下的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40526] = {title = "完工尾聲", objective = "使用提摩西的珠寶鉗來製造一個切割過的天岩。", description = "這個嘛，我試著修復戒指了，但寶石還需要一些加工。\n\n對了…你是個寶石切割者，<name>。你手上有工具，那你來切割那些珠寶吧！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：天岩戒環"}
MultiLanguageQuestData['tw'][40527] = {title = "完工尾聲", objective = "使用提摩西的珠寶鉗來製造一個切割過的深淵琥珀。", description = "這個嘛，我試著修復戒指了，但寶石還需要一些加工。\n\n對了…你是個寶石切割者，<name>。你手上有工具，那你來切割那些珠寶吧！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：深淵琥珀戒環"}
MultiLanguageQuestData['tw'][40528] = {title = "完工尾聲", objective = "使用提摩西的珠寶鉗來製造一個切割過的艾蘇石。", description = "這個嘛，我試著修復戒指了，但寶石還需要一些加工。\n\n對了…你是個寶石切割者，<name>。你手上有工具，那你來切割那些珠寶吧！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：艾蘇石戒環"}
MultiLanguageQuestData['tw'][40529] = {title = "黑心珠寶商", objective = "幫蒂芬妮‧卡地亞收集5個寶石碎片。寶石碎片可以透過探勘礦石原石或是從拍賣場取得。", description = "勘探礦石是我們獲得寶石的主要方法。勘探時…你會找到小而無法使用的寶石碎片。\n\n大部分的寶石商店會直接丟掉這些寶石碎片，但我們卡地亞珠寶公司可是分毫都不浪費。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：多用途的天岩"}
MultiLanguageQuestData['tw'][40530] = {title = "鑒察之眼", objective = "造訪達拉然珠寶設計店的顧客，再回去向蒂芬妮回報。", description = "<name>，我瞧不起的就是誹謗。有傳言指出我最近完成的委託品出現假貨。\n\n我們必須盡快平息這些謠言。\n\n我要你拜訪近期的幾個顧客，並看看他們的寶石。如果你自稱是個貨真價實的珠寶匠，那你應該從一哩外就能看出哪枚珠寶是假貨。\n\n這是我的顧客名單。如果你發現這些謠言屬實，請馬上回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40531] = {title = "即刻復仇", objective = "在達拉然的城底區找到哈洛德‧溫斯頓。", description = "我發誓，等我抓到他，我一定…\n\n<蒂芬妮對上了你的目光，恢復了冷靜。>\n\n<name>，我要你幫我找出我的前同事，哈洛德‧溫斯頓。我猜他已經跑遠了。\n\n你找到他以後，我希望你幫忙找回失竊的財物並歸還給我。\n\n不拘手段。不用擔心摩爾小姐的珠寶，我會再親自送新貨給她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40532] = {title = "切割寶石", objective = "使用蒂芬妮的切割工具製作致命的深淵琥珀。", description = "看到你這麼值得信賴、應變能力十足，我很樂意教你如何切割一枚致命的深淵琥珀。\n\n直接用我的切割工具來完成吧。你準備好之後，到前面去坐好。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：致命的深淵琥珀"}
MultiLanguageQuestData['tw'][40533] = {title = "切割寶石", objective = "使用蒂芬妮的切割工具製作迅速的艾蘇石。", description = "看到你這麼值得信賴、應變能力十足，我很樂意教你如何切割一枚迅速的艾蘇石。\n\n直接用我的切割工具來完成吧。你準備好之後，到前面去坐好。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：迅速的艾蘇石"}
MultiLanguageQuestData['tw'][40534] = {title = "切割寶石", objective = "使用蒂芬妮的切割工具製作精湛的皇后蛋白石。", description = "看到你這麼值得信賴、應變能力十足，我很樂意教你如何切割一枚精湛的皇后蛋白石。\n\n直接用我的切割工具來完成吧。你準備好之後，到前面去坐好。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：精湛的皇后蛋白石"}
MultiLanguageQuestData['tw'][40535] = {title = "救出卓格巴", objective = "在維爾薩拉向拉蘇妮‧星刃探詢珠寶設計大師的行蹤。", description = "在達拉然八卦傳得特別快，<name>。而最新的傳聞是在維爾薩拉的某處有位珠寶工匠大師。\n\n我要你跑一趟，找到這位大師，說不定他那裡有可以幫助店裡業績成長的設計。我在各種傳言中經常聽到「拉蘇妮‧星刃」這個名字。從她開始調查應該會是個好方向。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40536] = {title = "比珠寶更重要", objective = "在賈卜爾尋找鷹身人的項鍊時保護他，並護送他回鄰近的夜精靈營地。", description = "噢，你想瞭解賈卜爾的珠寶技術？\n\n這個嘛，賈卜爾需要你幫忙。在離開這裡之前，賈卜爾還需要鷹身人項鍊。\n\n在賈卜爾拿項鍊的時候，幫他趕走這些鷹身人，賈卜爾就告訴你他的知識。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n設計圖：天岩墜飾設計圖：艾蘇石墜飾設計圖：深淵琥珀墜飾"}
MultiLanguageQuestData['tw'][40537] = {title = "鮮血合約", objective = "在血縛紀錄簿上面簽名。", description = "<name>，等一下！我有好消息想跟你分享！但不可以跟其他人說喔，這是我們雕銘師之間的小秘密。\n\n<柔伊俏皮地對你眨眼，然後拿出一本巨大的書。>\n\n這本書是「血縛紀錄簿」。如果你把名字寫在上面，就可以學會簽訂「鮮血合約」的方法。會有一點痛啦，但真的物超所值！\n\n我自己也學了，每次用起來都超爽的！因為…呃，總之，你簽下去就懂了。\n\n怎麼樣啊？是不是有點心動啊？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40538] = {title = "寶石工藝課程", objective = "使用蒂芬妮的切割工具製作巧奪天工的漩渦藍晶。", description = "別來無恙，<name>。\n\n看來從上次見面後我們各自都很忙。我這有件事你應該有興趣。\n\n最近有批稀有的珠寶，叫做漩渦藍晶，總算送來我店裡了。\n\n我給它想出了個漂亮的設計，想給你看看怎麼把這寶石切割成實用的東西。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：多用途的漩渦藍晶"}
MultiLanguageQuestData['tw'][40539] = {title = "隱藏的意圖", objective = "幫克萊夫‧科森收集一套鑽石開鎖工具。", description = "在街上的流言都說你是一位值得信賴、很有應變能力的辦事好手。我們不妨說，這樣的評價太保守了。\n\n所以，接下來的工作是這樣。我需要一套新的開鎖工具。但常見的老式開鎖工具無法勝任。\n\n我需要一些特殊，就算受很大壓力也不會斷裂的東西。\n\n我在想，一套鑽石開鎖器可能辦得到。它應該是由鑽石打造出來的開鎖器，而不是形狀像鑽石。\n\n怎麼樣，你要不要參一腳？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：鑲嵌珠寶的開鎖工具"}
MultiLanguageQuestData['tw'][40540] = {title = "快來找我，卜魯", objective = "在斯鐸海姆找到賈卜爾。", description = "<name>，我收到…嚴格來說算是一封「信」，信的內容刻在一塊石板上。\n\n寄件人是你在維爾薩拉認識的珠寶設計大師。他說他最近會在斯鐸海姆。\n\n你見到他的時候，能不能委婉地告訴他，我們不想再收到他請你去找他的要求。我們煩都煩死了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40541] = {title = "蓄積的能量", objective = "在10隻獵風飛龍屍體上使用導引珠寶。", description = "在賈卜爾與你分享他的設計之前，他需要你協助進行一項特殊計畫。\n\n賈卜爾擁有一顆能夠容納風暴能量的寶石。寶石容納的閃電越多，就會變得越耀眼。\n\n賈卜爾認為獵風飛龍的力量與其在斯鐸海姆的天空發威，還不如化成這顆寶石的能量。\n\n你認同嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40542] = {title = "納夏爾之眼", objective = "取得2顆納夏爾之眼。", description = "致命的先知之眼…好選擇。但在我們開始切割之前，我們需要寶石。\n\n這裡有一尊巨大的遠古維酷人雕像，納夏爾。在它的眼槽中，有兩枚我們所需要的石頭。\n\n爬上雕像把珠寶之眼拿下來，將它們帶回來給賈卜爾。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：致命的先知之眼"}
MultiLanguageQuestData['tw'][40543] = {title = "納夏爾之眼", objective = "取得2顆納夏爾之眼。", description = "迅速的曙光石…好選擇。但在我們開始切割之前，我們需要寶石。\n\n在北邊的山脈中有一尊巨大的遠古維酷人雕像，索特納。在它的眼槽中，有兩枚我們所需要的石頭。\n\n爬上雕像把珠寶之眼拿下來，將它們帶回來給賈卜爾。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：迅速的曙光石"}
MultiLanguageQuestData['tw'][40544] = {title = "納夏爾之眼", objective = "取得2顆納夏爾之眼。", description = "精湛的暗影紅寶石…好選擇。但在我們開始切割之前，我們需要寶石。\n\n這裡有一尊巨大的遠古維酷人，納夏爾的雕像。在它的眼槽中，有兩枚我們所需要的寶石。\n\n爬上雕像把珠寶拿下來，將它們帶回來給賈卜爾。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：精湛的暗影紅寶石"}
MultiLanguageQuestData['tw'][40545] = {title = "阿唷，該死的！", objective = "把槍枝木箱帶給城底區的費爾戈‧廢底。\n\n已提供物品：\n", description = "真是場大災難！不，甚至還更糟，這是場陰謀！\n\n我聽說燃燒軍團回來了，所以我就對自己說，「荷巴爾特，你出人頭地的時候到了。」\n\n我做了很多槍枝，夠把惡魔轟回老家去！\n\n結果到了那裡，你猜怎麼了？大家就這麼巧都「找到」這些上古神兵來對抗惡魔！\n\n長話短說，我現在有太多槍枝，要想辦法處理掉。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n軍團工程學"}
MultiLanguageQuestData['tw'][40546] = {title = "大自然的奧秘", objective = "取回一片龍晶。", description = "賈卜爾想把他特別的水晶給你看看。沒人知道它們有什麼功用，很神秘。\n\n如果你想知道怎麼製作，賈卜爾很樂意教你。\n\n在高山上住著獵風飛龍，他們會用閃電吐息噴向山壁，有時候威力甚至大到會把岩石轉化成水晶。\n\n拿一片水晶回來給賈卜爾。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：聊天石"}
MultiLanguageQuestData['tw'][40547] = {title = "敬摯愛的達拉然", objective = "將賈卜爾裝箱並把他寄到卡地亞珠寶公司。", description = "賈卜爾在想，他應該上去達拉然並與大師討論珠寶設計。\n\n但是賈卜爾不知道怎麼上去。賈卜爾想到一個有趣的點子，可能有效。\n\n如果你把賈卜爾寄到達拉然，那他一定可以平安抵達。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40556] = {title = "賈卜爾需要你", objective = "到艾蘇納找賈卜爾。", description = "你好，<name>，\n\n賈卜爾需要你的幫忙。可以請你過來艾蘇納一趟，跟賈卜爾碰個面嗎？\n\n謝謝你，\n\n賈卜爾您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40558] = {title = "給我鑲一下", objective = "從世界各地蒐集6個部件。參考蒂芬妮的筆記，瞭解要到哪尋找各個部件。", description = "你對櫃臺上的裝置驚歎不已，裝置上有顆按鈕，不過按了似乎沒有反應。\n\n蒂芬妮告訴你這是個老舊的玩具盒，但是水晶的部件已經破碎。\n\n如果你找一顆新的水晶過來，她能把它修好，而且教你怎麼自行製作。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：寶石爭霸"}
MultiLanguageQuestData['tw'][40559] = {title = "玄鴉堡：烏鴉的睿智", objective = "前往玄鴉堡並找回一本珠寶設計書，帶回去給達拉然的提摩西‧瓊斯。", description = "<name>，我已經從我們來此的朋友口中，聽到許多和玄鴉堡有關的事，其中提到一個房間，裡面存放了各種有關物品製作的書卷。\n\n我很願意和你打賭，裡面一定有一本珠寶設計相關書藉，對我們很有幫助。\n\n前往當地，並幫我帶回任何有用的東西。在你回來之後，我會和你分享一種甜美的新設計。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：曙光指環"}
MultiLanguageQuestData['tw'][40560] = {title = "靈魂之喉：靈魂出竅", objective = "前往靈魂之喉並把逝者之戒帶回達拉然，交給提摩西‧瓊斯。", description = "我要拜託你的差事一點也不簡單，<name>。\n\n我要你去死。不過，你一定能活著回來的！\n\n有艘叫做奈格法號的船，將人世的靈魂擺渡至黃泉。據說有一件叫做逝者之戒的古代寶物就沉睡在那艘船的船艙裡。\n\n你懂我的，<name>，沒什麼比閃亮的戒指更能吸引我了。\n\n想辦法登上那艘船，然後幫我把那件古代寶物拿回來。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：預言指環"}
MultiLanguageQuestData['tw'][40561] = {title = "英靈殿：天堂的珠寶", objective = "在勇氣大廳中殺死歐丁，並把他的戒指帶回達拉然，交給提摩西‧瓊斯。", description = "皇后和國王只戴最上等的戒指！而且我聽說，有些諸神之王已經現身了。\n\n在勇氣大廳中，統治者歐丁所擁有的財寶，現世中的任何人都無法比擬。如果你剛好前往那個地方，試著幫我去…取得，比如說，他的一枚戒指。\n\n我很懷疑他會這樣把戒指交出來，所以你可能要面對一場生死對決。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：大漩渦指環"}
MultiLanguageQuestData['tw'][40562] = {title = "私相授受", objective = "取得1片夜裔透鏡、1張訂做珠寶訂單及5個夜裔珠寶盒。", description = "<name>，真高興能再見到你。我們上次聊天，好像是很久很久以前的事了。\n\n我們接到一些資訊，表示蘇拉瑪爾有一群擅長珠寶設計的夜裔精靈，可以製作出巧奪天工的項鍊。我很想去看一下他們的寶石。\n\n還有他們的設計。\n\n還有…新式透鏡似乎也不錯。聽說城市的巡察員身上就有這種透鏡。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：職業項鍊"}
MultiLanguageQuestData['tw'][40567] = {title = "暗心灌木林：進入夢魘", objective = "進入暗心灌木林，殺死薩維斯之影。", description = "我們救不了伊瑟拉，但我們確實阻止了她破壞神殿的行徑。\n\n現在我終於可以將注意力轉到我丈夫身上。\n\n我不知道他遭逢了什麼困境。我只知道，如果不馬上行動，他的一線生機就會隨之消逝。\n\n跟著薩維斯進入夢魘，找到瑪法里恩。\n\n請你盡可能救出我的丈夫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "漸微夢魘裹足漸微夢魘足靴漸微夢魘脛甲漸微夢魘長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][40568] = {title = "閃電狂怒", objective = "在索林姆之巔殺死10個怒魔維酷人。", description = "襲擊我們幼龍的這些怒魔維酷人過去叫做德雷克雅，他們是曾與我們同遵一道遠古契約的部族。現在受到神御之王的慫恿，他們背棄了自己的誓約，肆無忌憚地對龍族展開攻擊。\n\n他們應為此受到報應。\n\n喚醒你的憤怒，<class>，主動向他們開戰！", progress = nil, completion = "你讓怒魔維酷人看到什麼才是真正的力量。\n\n他們絕對不敢輕易再和你刀刃相向。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40569] = {title = "沙之傳奇", objective = "與莉莉‧風暴烈酒交談。", description = "毫無記載，我們的史料中對這把武器毫無記載！\n\n我再三查證過，連一點相關傳說都沒有。這只代表一件事：故事的起源不在潘達利亞大陸。\n\n莉莉‧風暴烈酒雖然年輕，但她雲遊四海的經歷，在本島內僅次於你。如果有人可能知道這把武器的來歷，那一定是她了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40570] = {title = "直搗蒼天", objective = "取得蒼天之拳。", description = "這塊石頭洋溢著元素之力，很有可能是當初用來對付伊爾莫特時所殘留的魔法能量！\n\n如果你走到外面，對著天空高舉石塊，應該就能釋放它的能量精華，形成一陣強大的旋風。要是旋風夠強，說不定你和夥伴還能直接乘風前往天空之牆呢！\n\n如果伊爾莫特的拳刃，也就是蒼天之拳，真的有傳說中的無窮神力，那它們必定就在那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40573] = {title = "夢魘之王", objective = "告訴薩翁‧月爪薩維斯要回來了。", description = "還好你趕上了，朋友。\n\n卡格拉西斯正要把我獻給他的主人…我還以為我死定了。\n\n我很感激你，不過我們尚未脫離險境…薩維斯回來了。\n\n夢魘之王現身於維爾薩拉，親自籌劃腐化這片土地。卡格拉西斯在準備獻祭時，忍不住向我透露了這些。\n\n我們必須找到薩翁‧月爪，在事情無可挽回之前告知他整個情況！", progress = nil, completion = "薩翁‧月爪是實力高強的德魯伊，也是這片土地的真正守護者。\n\n少了他的協助，我們怎能妄想擊敗夢魘之王？", rewards = "無情苦痛腕輪無情苦痛手環無情苦痛臂環無情苦痛臂鎧您能選擇下列奬勵中的一個：\n\n薩翁的悲痛\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40578] = {title = "致敬", objective = "殺死8個不安的亡魂或不安的幽靈。", description = "我所見的只有絕望。\n\n看哪，<race>。地面被怨靈所佔據，這些都是埋葬於此的靈魂。有什麼事情激怒了它們，使它們傾巢而出。我感受得到它們的痛苦。\n\n我會去尋找剩下的聖物，而且有座陵墓我一定要看到。已經來不及拯救這些不幸的靈魂了。請你打敗看見的每一個怨靈，使它們得到應有的安息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40579] = {title = "傳說中的武器", objective = "選擇一種你想要的神兵武器。", description = "身為此處最偉大的戰士，你需要強力的武器來貫徹你我的意志。我已俯瞰艾澤拉斯四方，找出幾樣與你相配的神兵武器。\n\n至於要以哪個武器來對抗燃燒軍團，則交由你來決定。往後有機會我們會再取回其他武器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40585] = {title = "戰爭揭幕", objective = "選擇第一個攻擊地點。", description = "燃燒軍團以為你已經死了。所以當你現身痛擊他們的時候，肯定會讓對手大吃一驚！\n\n歐丁之眼可以讓我們看到整個破碎群島，並指派戰士進行種種任務。\n\n在你綜觀全局之後，你應該選擇你第一個作戰區域。我已幫你選了幾個最佳地點！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40588] = {title = "追查詛咒", objective = "護送瑞維爾‧寇斯特從暮色森林的密斯特曼托莊園到逆風小徑的埃瑞丁營地。", description = "非常好。那我先向你自我介紹。我是聖光牧師瑞維爾‧寇斯特，也是失落神兵的尋找者。我過去曾與黑騎兵對上，這次回來是要把他們趕出這個地方。\n\n黑騎兵行蹤難以捉摸，不過我有線索可以找到他們。在過去的對抗中，我有機會一窺他們的過去。從純淨披風的祝福之視當中，我終於瞭解了黑騎兵的來歷。\n\n跟我一起前往埃瑞丁營地。我會在路上跟你解釋。", progress = nil, completion = "奇怪，黑騎兵竟然沒跟過來。不過沒關係，這是一件好事。\n\n我相信找到黑騎兵的關鍵就在這附近。讓我們開始搜索吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40593] = {title = "惡魔四伏", objective = "保護暴風要塞，擊退燃燒軍團。", description = "國王十分英明，總是著眼於軍團的威脅，<name>。而即使是現在，惡魔仍在步步進逼。\n\n伊利達瑞會助聯盟一臂之力。我們相信它們已經把目光放在艾澤拉斯各地的重要地點上。事實上，它們可能就在你們之中！\n\n我感覺到它們就在附近…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "烏瑞恩家族徽印烏瑞恩家族的恩澤烏瑞恩家族綬章您會收到：\n\n"}
MultiLanguageQuestData['tw'][40594] = {title = "天降正義", objective = "轟炸底石裂口的部隊。", description = "拋下哀痛，先殺敵人！\n\n過來，勇士，讓我的一隻戰鷹送你一程。利用我們聯合部族所賦予你的力量，協助我們從天上消滅這些卓格巴。\n\n讓我們用它們自己的屍體，堵住它們新的巢穴出入口！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40603] = {title = "尋找華爾琪拉", objective = "到斯鐸海姆的埃伊爾之殿找艾雪笛爾。", description = "我們再也不想看到那場大災難重演，必須先確保辛艾薩拉之心可以抵抗惡魔魔法，才能繼續進行下一步。\n\n偉大的艾雪笛爾表示願意協助她認同的人，她的主人或許能夠幫助我們保護辛艾薩拉之心。\n\n你應該到斯鐸海姆的埃伊爾之殿和她聊聊。我會在那裡跟你會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40604] = {title = "擾亂過去", objective = "搜索埃瑞丁營地，尋找與黑騎兵有關的線索。", description = "當年商人埃瑞丁就是在這裡設立營地，向麥迪文兜售各種可疑商品。這麼多年了，這裡居然毫無改變，從這種詭異狀況來看，我判斷這營地的主人可能還在這裡活動。\n\n協助我搜索這個營地。看看能不能找到跟黑騎兵有關的線索。", progress = nil, completion = "這本日記外表看似平凡，但當你接近時，卻發現其中散發著源源不絕的黑暗能量。\n\n你快速掃過內容後，發現這是埃瑞丁的日記，上面記載著他在逆風小徑的經歷。在日記的最後，不僅字跡產生變化，語氣也變得越來越陰沉。不斷提到「詛咒」，以及將偉大力量佔為己有的無盡欲望。\n\n而在你的瀏覽過程中，有條記錄吸引了你的目光。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40605] = {title = "常伴朋友身旁", objective = "到奧格瑪高地上方的伊利達瑞營地，與艾爾辛‧達萊交談。", description = "燃燒軍團果然膽大無比，居然敢攻擊部落的堡壘！你協助我們守住堡壘，但我現在有更重要的事要請你幫忙。\n\n看來惡魔獵人在這場戰爭中的重要性不言而喻…但我還是無法信任他們。你會代表我出使伊利達瑞。了解他們知道多少事情。研究他們的能力。如果他們背叛我們，就讓他們嚐嚐自己的手段。\n\n他們的營地位在奧格瑪的高地上。去吧。納薩諾斯和我會負責收拾殘局。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40606] = {title = "指引方向", objective = "在埃瑞丁營地尋找日記提到的羅盤。", description = "日記內容逐漸變得雜亂陰沉，字跡也越來越潦草，但其中有筆紀錄特別引人注意。\n\n「烏薩萊許。這個名字在我腦海裡迴蕩。我可以聽見它的呼喚，但從何而來？\n\n「靈魂…這一片土地與它緊密相連。難怪我們經常在這個地方迷路。這股力量從四面八方擾動羅盤的指針…\n\n「如果能夠強化這股擾動力量，羅盤說不定可以指出方向的來源…」", progress = "就是那個嗎？", completion = "這個羅盤絕對有問題。\n\n它似乎打算指向所有方向。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40607] = {title = "惡魔四伏", objective = "了解『噬魂者』艾萊莉的發現。", description = "看看四周。你看到什麼？\n\n<艾萊莉若有所思地盯著你身後。>\n\n燃燒軍團已經滲透部落…就連現在，它們也在你身邊。\n\n我們必須保護你的大酋長。\n\n等你準備好看見檯面下的事物，就告訴我一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "女妖之王的烙印女妖之王獎品女妖之王綬章您會收到：\n\n"}
MultiLanguageQuestData['tw'][40608] = {title = "印記", objective = "向華爾拉亞證明你的價值，然後從埃伊爾手中接受華爾琪拉印記。", description = "你的劍的確無比強大，但尚未完全發揮潛能。英靈殿的全能之神歐丁可賜予你神力。\n\n為了尋求他的庇佑，你必須獻上相應的獻禮。我知道你該去哪裡取得這樣的獻禮。但在此之前，你必須先獲得華爾琪拉印記。\n\n勇士，證明自己的能力，獲得我們的印記，然後就能進入埃伊爾之殿 - 女神會在那裡指引你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40611] = {title = "逆風小徑的命運", objective = "前往逆風小徑中無法安息的靈魂出現之處，以調校埃瑞丁的羅盤。", description = "日記裡提到「強化擾動羅盤的力量」。如果這個地方的靈魂真的與它緊密相連，或許就能作為我們需要的擾動力量。\n\n在逆風小徑裡，我去過好幾個地方，經常出現無法安息的靈魂。如果你讓那裡的靈魂看一下羅盤，它們說不定就能幫你鎖定正確方向。\n\n你去這些地點看看。我繼續前往卡拉贊，看看能不能找到跟黑騎兵有關的線索。", progress = nil, completion = "看來這招有用，羅盤指著河流的方向。\n\n這表示…？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40613] = {title = "靈魂之喉：取回斯瓦神盾", objective = "在傳奇難度中，前往靈魂之喉取回斯瓦神盾，並擊敗黑爾雅。", description = "斯瓦神盾原為歐丁所有，據說是用來阻擋界域下方的無盡黑暗，使英靈殿不受侵擾。\n\n而黑爾雅，這位很久以前就被逐出瓦哈拉斯閃耀殿堂的神祇竊走了斯瓦神盾，把它藏在自己的詛咒之船奈格法號裡。\n\n你必須登上奈格法號，打敗黑爾雅並取回斯瓦神盾。斯瓦神盾會是獻給歐丁最好的禮物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40614] = {title = "獻給歐丁的盛宴", objective = "到斯鐸海姆取得雷蹄肋排，到高嶺取得裂脊之脊，到艾蘇納取得地牙肉排。", description = "在惡戰之後大肆飲宴，是英靈殿的習俗。為歐丁獻上豪華盛宴，可以向他展現你想獲得祝福的決心。\n\n到斯鐸海姆取得雷蹄肋排，到高嶺取得裂脊之脊，到艾蘇納取得地牙肉排。有了這些，就能準備好與即將來臨的大戰規模相當的豪華盛宴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40615] = {title = "英靈殿：歐丁的祝福", objective = "在傳奇難度中，於英靈殿獲得歐丁的祝福。", description = "你已經準備好了，<class>。\n\n前往歐丁輝煌的殿堂，在殿內的祭壇獻上宴席。偉大的歐丁會看著你。你必須在他的注視下，通過華爾拉亞的試煉。\n\n歐丁只會祝福完成試煉的勇士。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n悍勇印記"}
MultiLanguageQuestData['tw'][40617] = {title = "回來吧，夜眼", objective = "協助莉爾芮雅‧曦風找到夜眼。", description = "陌生人，你一定得幫幫我！\n\n我的老朋友，夜眼…他本來在前方偵察，我聽到他發出警告的叫喊聲。我想趕過去找他，卻不小心踩進這個陷阱裡。\n\n差點就能找到他了，就在山嶺的另一邊。拜託請你找到他！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40618] = {title = "傳奇武器", objective = "選擇你想要的第一把神兵武器。", description = "三件武器…三種不同的道路。\n\n取得其中一件神兵武器，將是我們對抗燃燒軍團的第一步。這些武器會隨著你而成長，所以你必須謹慎選擇最適合你的，<name>。\n\n之後，你還可以去尋找其他的武器，但是你必須決定要先尋找哪一個。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40623] = {title = "黑騎兵", objective = "在卡拉贊地下墓穴擊敗黑騎兵並取得烏薩萊許。", description = "河邊有一個下水道出口，通往卡拉贊下面的墓穴。我過去不曾留意過，不過它很可能就是靈魂要我們去的地方。\n\n仔細一想，黑騎兵很可能一直躲在我們的眼皮底下！走吧，讓我們看看這條下水道通往哪裡。", progress = nil, completion = "今天，黑騎兵嘗到有始以來最大的敗績，也是暮色森林人民的一大勝利。\n\n他們欠你一分恩情，我也是。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40625] = {title = "不同來源", objective = "替克托斯找到魔化拆除器。", description = "我要你幫我找些東西。\n\n我想我就快找出一種新的魔法來源了，但是我需要工具。\n\n我沒辦法再使用我的工房，但我曾看過底下那些較小的惡魔使用工具。將他們的其中一組工具帶來給我，我就能解救我們的人民。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40632] = {title = "帶我去見你的領導者", objective = "在蘇拉瑪爾和卡德加碰面。", description = "<name>，很高興你來了。\n\n這名…大法師卡德加發現了我的訊息並且召開了會議。\n\n他希望能盡快在城市的入口處跟我們碰面。\n\n你能跟我一起前往嗎？我有異樣的預感，他不會是一個人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40633] = {title = "出發去冒險囉！", objective = "到蘭姆卡韓去見莉莉。", description = "噢，我好想去看看那些故事是不是真的！但是老爸總忙著填飽肚子，對於我想要出去探險這件事老是不太高興。他甚至告訴我，除非有人保護我，否則不准離開村子！\n\n老爸，你說真的嗎？我絕對可以好好保護自己！\n\n怎麼樣，你能保護我嗎？拜託你，帶我離開這個無聊的地方，你就會是我的英雄！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40634] = {title = "沙中雷霆", objective = "打敗奈德爾，在它身上搜尋線索。", description = "我非常熟悉伊爾莫特的傳說。據說那座掩埋在沙漠下的城市，阿姆圖爾，曾是他的家鄉。\n\n最近有一股奇異的風暴籠罩於廢墟之上，而且我收到情報，表示有個叫做奈德爾的元素開始攻擊附近的民眾。\n\n這些事件一定有關連。\n\n找到奈德爾，終結它的生命。記得搜尋它身上有沒有關於這些事件的線索。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40636] = {title = "準備攻擊", objective = "選擇一種你想要的神兵武器。", description = "燃燒軍團突擊了寂靜峰，我們不會再讓他們這麼做！\n\n我們受過嚴格的訓練，但要想成功，就需要夠強的武器，才能消滅這個強大的邪惡勢力。\n\n我們的卷軸中記載了許多力量強大的武器，但我們無法決定要先去尋找哪一把武器。\n\n宗師，就由你來決定吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40642] = {title = "力量！取得力量！", objective = "為克托斯蒐集8個惡魔精華。", description = "我需要更多力量。更多更多！\n\n我能控制能量，而他們能供我所需。雖然只是暫時的。\n\n我不會像那些弱者一樣，迎來凋萎的命運。\n\n闖進魔魂堡之中，殺死惡魔。將它們的精華帶回來給我，快去快回！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40643] = {title = "來自月光林地的傳喚", objective = "到月光林地與哈繆爾‧符文圖騰見面。\n\n已提供物品：\n", description = "<name>，你必須立刻前往月光林地。\n\n我們正在準備重大的儀式，需要你的協助。\n\n我會在那裡跟你會面，請盡快過來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40644] = {title = "翡翠夢途", objective = "協助進行儀式。", description = "儀式已準備完成。\n\n跟我來，<name>。我會帶你到進行儀式的地方。", progress = nil, completion = "做得好，&lt;name&gt;！\n\n現在通路已經開啟，我們能啟程前往維爾薩拉了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40645] = {title = "前往幻夢之林", objective = "穿過傳送門前往幻夢之林。", description = "翡翠夢途的傳送門已經開了，我們也必須在此分道揚鑣。月光林地還沒擺脫燃燒軍團的威脅，我必須確保那裡安全無虞。\n\n<name>，請你前往維爾薩拉。大德魯伊巨蹄是那裡的德魯伊領袖，他擁有無與倫比的智慧，能給我們珍貴的援助。\n\n夢境危機四伏，我會請守衛者雷姆洛斯來帶你。在傳送門的另一側與他會合吧。", progress = nil, completion = "你穿過了翡翠夢境來到這裡，實屬難得。如果你以後想盡快往返此處，這個法術能指引你。\n\n雖然通過翡翠夢途已是一大壯舉，但未來的任務將更為艱鉅。", rewards = "您會學到：\n\n夢行\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40646] = {title = "傳說中的武器", objective = "選擇一種你想要的神兵武器。", description = "我同意守衛者雷姆洛斯。如果我們想擊敗燃燒軍團，就需要具有傳說力量的武器。\n\n在我們族人的歷史中，共記載著四把著名武器。\n\n告訴我，你想先尋找哪一把？", progress = nil, completion = "選得好，&lt;name&gt;！\n\n如果你能得到那把武器的力量，我們一定可以恢復艾澤拉斯的平衡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40647] = {title = "噩夢開始", objective = "進入翡翠夢境，取得厄索克之爪。", description = "有了厄索爾的祝福，我們就能安全穿過魔法結界，抵達爪子的所在之處！\n\n現在，我們得進入夢境。在厄索爾聖壇前躺下並飲用你之前帶來的月井水，你的靈魂就會進入夢境。\n\n小心點，夢境裡處處都是危機。", progress = "你取回厄索克之爪了嗎？", completion = "我這條命是你救的，&lt;name&gt;。要不是你，我一定會死得很難看。\n\n薩維斯那個叛徒，雖然抓走了厄索克，但是至少我們拿回了他的爪子。我們還是有希望的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40649] = {title = "與蜜露恩會合", objective = "找到蜜露恩。", description = "<name>，你居然在今天來找格哈尼爾，看來我們運氣不錯。林精蜜露恩不久前才來到這裡，在那之前她都待在長年守護著法杖的聖壇。\n\n很少人知道那個位在夏達希爾根部的隱藏處所，但你已經獲得這項權利。\n\n準備好出發時，就與蜜露恩交談吧，我最後一次看到她是在東方的山丘上。", progress = nil, completion = "&lt;蜜露恩的睫毛沾著露水，同樣面帶笑容，卻眉頭輕蹙。&gt;\n\n怎…怎麼了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40650] = {title = "勇士：贊塔布拉", objective = "我一直在思考，<name>。我很久以前就放下了步行杖，過著平靜的生活，打算在晚年傳授<class>之道。\n\n不過現在戰爭讓我的家園四分五裂，我不能袖手旁觀。\n\n我會拿起法杖，再次與你踏上旅程，<name>。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：贊塔布拉\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][40652] = {title = "風之語", objective = "跟傲天者歐姆奴隆交談。", description = "我們現在必須將注意力轉到破碎群島了。\n\n傲天者歐姆奴隆蒐集了群島各處的事件情報。只要有攻擊燃燒軍團的良機，他一定會知道。\n\n去跟他談談，看看他是否有需要協助的任務。", progress = nil, completion = "你好，大&lt;class&gt;。\n\n我們面臨著無數威脅，必須快點行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40653] = {title = "擬訂計畫", objective = "選擇衛隊的第一個任務地區。", description = "燃燒軍團對艾澤拉斯的萬物帶來威脅，而夢魘則對萬物的靈魂帶來威脅。我們必須消除這兩個威脅，才能確保我們的世界不至於毀滅。\n\n有了這張地圖，我們可追蹤破碎群島各地的情況，並在威脅萌芽之際即時反應。我們目前的兵力有限，所以我們應該把資源用在刀口上。\n\n等你先看完地圖，再選擇我們要從哪裡開始。", progress = nil, completion = "是的，我同意。這是個好地方，可以讓我們專注於第一步。\n\n只要出現新的威脅，我會立刻向你通報。願伊露恩指引你的道路，大&lt;class&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40654] = {title = "利爪德魯伊", objective = "和雅里斯‧暗爪談談。", description = "有位新盟友剛加入我們。他叫作亞里斯‧暗爪，是利爪德魯伊經驗豐富的訓練師。\n\n請找他聊聊。", progress = nil, completion = "太好了。再過不久，這些利爪&lt;class&gt;就能讓部隊更強大。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40657] = {title = "魔化之路", objective = "替克托斯收集10個魔能灌注金屬板。", description = "想瞭解魔法運作方法的第一步，就是瞭解並研究這種魔法產生的物質。畢竟這就是我破解術士靈魂水晶的方法。\n\n在這深淵裡的蟲舌魔爪牙會把這種金屬板加工成建築物，用來支援和維修。這是個適當的著手之處。幫我拿一些來，我忠誠的助手！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40659] = {title = "眼冒金星", objective = "從老邁的深溝行者身上取得4隻海星。", description = "小兔兔，你以為殺殺納迦就很厲害了嗎？\n\n<斯多克法咯咯笑著。>\n\n我比較想跟長滿藤壺的巨獸來場痛快的對決。\n\n如果要讓我對你改觀，就把它們頭上的星星摘來給我。到時候我可能會考慮承認你是真正的<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40661] = {title = "保家衛國", objective = "打開你的地圖，在卡林多或東部王國尋找進行中的燃燒軍團入侵行動。前往入侵地點，破壞惡魔的計劃！", description = "燃燒軍團對這座城鎮的入侵行動早已悄悄展開。它們的惡意瀰漫整個艾澤拉斯，威脅世界的每一個角落。\n\n我們必須將它們的黑暗計劃扼殺於萌芽之際。\n\n我們已經派出斥候前往世界各地，調查燃燒軍團的行動。只要發現入侵跡象，就會將地點標記在地圖上。\n\n別讓它們好過，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40668] = {title = "艾薩拉之眼：辛艾薩拉之心", objective = "在傳奇難度中，前往艾薩拉之眼取回辛艾薩拉之心，並擊敗艾薩拉之怒。", description = "艾蘇納的海岸正遭受可怕的風暴攻擊，這是艾薩拉之眼的納迦幹的，但風暴的規模應該連他們族裡最厲害的海妖也掌控不了。\n\n他們一定用了辛艾薩拉之心。\n\n在大崩裂以前，艾薩拉的統治者就曾經使用辛艾薩拉之心強化力量，也因此得以控制永恆之井。\n\n<name>，如果你可以潛入他們的地盤，並從那些邪惡生物手中奪回辛艾薩拉之心，我們就能將這股力量用在更好的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40672] = {title = "奈薩里奧巢穴：擺盤才是關鍵", objective = "在傳奇難度中，前往奈薩里奧巢穴內擊敗『地底之王』達古爾，並取得4個合金外殼碎塊。", description = "歐丁會要求舉辦一場配得上古代試煉的宴席。宴席的好壞並非從吃下堆積如山的獸肉才開始評判，而是從上菜的盤子就開始了。\n\n在高嶺地底，奈薩里奧的舊巢穴深處，你可以找到他用來固定外皮的合金鎧甲 - 奈薩里奧就是後來的「死亡之翼」。\n\n那些合金鎧甲非常適合當盤子。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40673] = {title = "被遺忘的知識", objective = "從首席秘法師薩莉瑟拉取得月神之眼卷軸。", description = "我們確實熟悉夜裔精靈的魔法，但他們不讓我們靠近辛艾薩拉之心。那是女王的親信才有的權利。\n\n就算這樣，我們還是學會如何使用辛艾薩拉之心。\n\n有一名夜裔學者曾在數千年前研究過辛艾薩拉之心，他的筆記很詳細，後來他被處決，所寫的卷軸也成為禁書。夜落精靈逃難時，把卷軸偷偷帶走了。\n\n如果你取得卷軸，我們就能幫你。", progress = "因為曾經被夜裔精靈背叛…夜落精靈變得…非常多疑。你必須先取得信任，才有辦法接近卷軸。", completion = "&lt;薩睿納斯仔細閱讀卷軸。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40674] = {title = "詹德維克的罐子", objective = "從沙許塔爾遺跡內取回6瓶癒合之水。", description = "上次我們碰面的時候，<race>，我被關在牢籠裡。你曾經冒著生命危險幫助我的同胞。你願意再次助我一臂之力嗎？\n\n納迦的攻擊使我們傷亡慘重。我需要癒合之水才能進行治療儀式。\n\n我看過納迦使用這種水。如果找到這種水，就拿回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40675] = {title = "幽暗地道：隊長的儀式", objective = "在傳奇難度中，前往幽暗地道，從諫言者凡卓斯身上取得恆時晷儀。", description = "只有月之守衛的隊長才能掌管衛隊的力量 - 這是自古以來的規定。\n\n你必須完成繼任隊長的儀式。\n\n傳統上，候選人必須不眠不休巡邏幽暗地道三週，錯綜複雜的迷宮可以充分考驗守衛的能耐。我們應該遵守規定，但我相信還有其他方式能夠證明你自己。\n\n艾莉珊德的諫言者凡卓斯最近前往幽暗地道。殺死他，取得他的恆時晷儀。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40678] = {title = "扭曲的力量", objective = "在法隆納的終焉祭壇使用強力傳送石召喚『扭曲者』維祖爾，然後搶走他的符文束腕。", description = "時候到了，讓我們注入惡魔魔法試試看 - 這可是我所知道最強大的力量。\n\n燃燒軍團的爪牙為了迎接埃雷達爾主人，身上偶爾會帶著強力傳送石碎片。如果收集夠多碎片，就可以合成完整的傳送石，在法隆納的終焉祭壇召喚埃雷達爾領主『扭曲者』維祖爾。\n\n維祖爾佩戴的束腕可以強化力量，應該可以讓辛艾薩拉之心發揮到極致。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40683] = {title = "偉大的發明需要實驗", objective = "從魔火石化蜥蜴身上取得8個魔火脊骨。", description = "我感覺得到你全身上下都有魔力殘留，你肯定會有用處。\n\n我要研究惡魔的軀體為何能控制如此大量的魔化能量。我有很多惡魔的屍體可以研究，但應該還有某種別的東西…。幫我找來附近石化蜥蜴的脊骨，讓我研究其中的魔力殘留。\n\n沒道理要把我倆的手都弄髒，對吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40684] = {title = "荒蕪武器秘典", objective = "與卡萊德斯討論你想要的神兵武器。", description = "你帶來的書不但是你朋友們獲救的希望，還可以賦予你絕對的力量！它記載了許多對燃燒軍團而言太過危險的聖物，讓他們不得不多加提防。\n\n看一看吧，朋友。然後決定你要使用這些神兵之中的哪一件來擊敗賈岡諾斯！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40693] = {title = "Eyes of Nashal - Choice UI - Deadly Eye of Prophecy", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n致命的先知之眼"}
MultiLanguageQuestData['tw'][40694] = {title = "魔法的一小步", objective = "與克托斯交談，協助他完成儀式。", description = "迎接未來的時刻到了。\n\n我已掌握了我族人所知的所有魔法。而我將再掌握這一種。\n\n運用秘法的原理，我可以輕易掌握你這個材料中的惡魔能量。接下來，我需要活的實驗品。\n\n我們從小型的召喚儀式開始吧。替我打敗那個生物，然後看看真正的學者會怎麼做事！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破爛的魔石"}
MultiLanguageQuestData['tw'][40704] = {title = "勇士：莉莉", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40705] = {title = "牧師兩三事", objective = "前往提里斯法林地的法奧之墓，參與密談。", description = "<name><大人/女士>，我所代表的人想要籌組一支強勁的反抗軍，對抗軍團的威脅。\n\n不曉得你是否願意前往提里斯法林地的法奧之墓與他會面。他會保證你的人身安全，你也將有機會在這場衝突中扮演更關鍵的角色。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40706] = {title = "手握傳說兵器", objective = "選擇一種你想要的神兵武器。", description = "為了面對將來的試煉，你需要一把武器來增強你的能力。我這裡有一些選項讓你考慮，\n\n你得決定要先取得哪一把武器，而我對你的選擇有無比的信心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40710] = {title = "暮光之刃", objective = "阻止儀式，取得薩拉塔斯，黑暗帝國之刃。", description = "我一直與茉艾拉‧索瑞森合作，試圖剷除暮光之錘。我們聽說有一把強大的遠古諸神兵器，一把每次現世皆會造成巨大破壞的匕首。\n\n茉艾拉的雙面間諜發現一位新首領正在崛起。他試圖用這把武器進行穢邪儀式，鞏固其地位。你必須找到他、阻止儀式，並取回神兵武器。\n\n事成後，我會在達拉然跟你會面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40712] = {title = "據有力量", objective = "回達拉然的城底區找卡萊德斯。", description = "看來我誤會你了，術士。你幫助我對抗黑騎兵，榮耀了聖光。或許我原先不應該這麼武斷的。\n\n無論如何，你讓我達成了目標，將這些神兵交還給命定的擁有者。至於烏薩萊許，我覺得把它交給你才是最安全的。\n\n希望它能幫你打敗燃燒軍團，術士。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40713] = {title = "黑暗秘典", objective = "取得黑暗秘典。", description = "我有一個重大發現，<name>。\n\n靈魂核心裡有一個實力高強的術士，他持有一部強大的秘典。那部秘典內含禁忌法術，能夠召喚出最強的惡魔。\n\n就連燃燒軍團也不敢召喚這些惡魔領主，但我現在擁有的知識更甚於它們。\n\n為我奪取秘典，我就能擁有源源不絕的魔力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40714] = {title = "號令參戰", objective = "前往卡薩斯平臺與蘭克洛公爵碰面。", description = "<一道冰冷的思緒掠過你的心頭。>\n\n聽我說，<name>。\n\n燃燒軍團已經捲土重來。它們想控制我們，要我們屈服於它們的意志。真是蠢貨，它們只是回來自投羅網。\n\n你在達拉然的弟兄們已經開始到卡薩斯平臺集合了。去吧，去見蘭克洛公爵，他會解釋一切的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40715] = {title = "必要的盟友", objective = "選擇一種你想要的神兵武器。", description = "我們在這場戰爭中有個意想不到的盟友，<name>，如果要打敗燃燒軍團，我們就必須盡可能取得所有的優勢。\n\n只要天譴軍出不了北裂境，黯刃騎士團就願意權充巫妖王的左右手。而做為回報，我們的盟友則會幫我們最強的騎士尋找強大的武器 - 能夠一勞永逸殲滅燃燒軍團的神兵利器！\n\n你是我們之中的菁英，<name>。我需要你來決定想要哪種武器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40716] = {title = "第六位成員", objective = "到達拉然底下的意志之環和瑞特辛‧焰慍碰面。", description = "你好，術士。我代表黑穫議會前來與你會面。\n\n燃燒軍團即將入侵，而我們唯一的希望是取得更多力量。議會正在計畫深入扭曲虛空，召喚更多強大的惡魔同盟。儀式已經準備好了，但我們還需要一位成員。\n\n你應該知道坎瑞薩德‧埃伯洛克的不幸命運了吧。\n\n你會替補他的位置。你接受嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40717] = {title = "議會的呼喚", objective = "前往停留在逆風小徑上空的達拉然與卡德加會面。", description = "<秘法異常體轉向你，以明顯是卡德加的聲音向你說話。>\n\n我很不想在你忙於對抗燃燒軍團的時候打擾你，但我有一件…外交相關的問題要請你幫忙。我們正面臨嚴重的威脅，必須傾盡全力才能度過這次的難關。\n\n有些人不會認同這樣的安排。\n\n請到達拉然的紫羅蘭城塞外找我。我們移動了達拉然的位置，以利協防東部王國。城市目前在逆風小徑的卡拉贊上方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40718] = {title = "議會的呼喚", objective = "前往停留在逆風小徑上空的達拉然與卡德加會面。", description = "<秘法異常體轉向你，以明顯是卡德加的聲音向你說話。>\n\n我很不想在你忙於對抗燃燒軍團的時候打擾你，但我有一件…外交相關的問題要請你幫忙。我們正面臨嚴重的威脅，必須傾盡艾澤拉斯所有人民的全力才能度過這次的難關。\n\n必須讓部落重新加入祈倫托。有些人不會認同這樣的安排。\n\n請到達拉然的紫羅蘭城塞外找我。我們移動了達拉然的位置，以利協防東部王國，就在卡拉贊上方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40727] = {title = "水道漫延", objective = "殺死3個暮衛劫法師。", description = "我最近發現總是有人在偷瞄我們。\n\n我非常樂意繼續送貨給凡席爾，不過這類行動變得越來越危險。\n\n尤其在市場巡邏的暮衛，更是最關注我們的一舉一動。\n\n找出並殺死那些劫法師，好讓我安全出貨。\n\n我會帶著貨物跟隨在後。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n市集鑰匙"}
MultiLanguageQuestData['tw'][40729] = {title = "新血加入", objective = "在達拉然的意志之環中，和黑穫議會一塊兒完成召喚儀式。", description = "是時候開始進行儀式了，術士。請做好萬全準備，因為今天這個召喚儀式的困難度超乎你的想像。\n\n你準備好了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40730] = {title = "重新分配", objective = "取得20瓶秘能酒。", description = "可以想像，你認為我輕鬆就能把酒送出。\n\n<德林咯咯笑著。>\n\n如果真的那麼簡單，他的人民就不會挨餓了。\n\n<她的神情變得相當嚴肅。>\n\n這些…所謂的忠誠者，手中的酒永遠用之不竭。他們總是在舔博學者的屁股，以換取享有所需的一切。\n\n秘能酒從來不曾短缺。這只是博學者用來管理我們的手段。\n\n他們不會發現丟了幾瓶酒。因為他們的酒多到不行。\n\n搜索廣場，帶回越多酒越好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40731] = {title = "懼痕之心", objective = "打倒賈岡諾斯並帶著他的心臟，前往懼痕裂隙的主宰王座。", description = "朋友取得神兵了！現在賈岡諾斯肯定沒機會了！\n\n快點，你必須回到懼痕裂隙！或許你還來得及從賈岡諾斯的復仇中拯救你的朋友。\n\n如果你拿到主宰之心，就能號令他的軍隊！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40740] = {title = "亡者與遭譴者", objective = "前往達拉然，乘著澤歐莫斯飛到暗岩島。到了那裡之後就穿過惡魔之門，找到史力弗男爵，取得遭譴者之顎。", description = "<一股強大的心智力量再次碰觸了你的思緒。>\n\n『裂肉狂魔』葛里克斯是個巨大的惡魔。他是千百異界的屠夫，不知道有多少種族在他那把名為遭譴者之顎的利斧下滅絕。\n\n黯刃騎士團派出一支小隊想制伏他，但卻音訊杳然。你必須完成他們未竟的任務。\n\n你不會單打獨鬥，我已經先派了史力弗男爵協助你。\n\n去吧，取得遭譴者之顎，並確保葛里克斯不再危害世人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40744] = {title = "古老配方", objective = "收集6根鷹身人的爪子。", description = "蘇拉瑪爾是…過去曾是知識份子的天堂。\n\n我們在此無所不攻，從鍊金術以至最原始的魔法本身。我們怎會如此愚蠢，同意讓他們進來？\n\n看看我，還有多少事非做不可，腦袋卻又迷失在五里霧中。我的工作需要一些不好取得的材料，<race>。你願意幫我找來嗎？\n\n我需要一些鷹身人的利爪，磨成粉以後，能夠做成很有效的試劑。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n魔法強化藥水"}
MultiLanguageQuestData['tw'][40745] = {title = "輪班換手", objective = "藏在籃子中，等待守衛出現。跟蹤守衛前往他們的目的地。", description = "這是我們救出薇玲女兒的最佳機會。\n\n我來說明我們的計畫。\n\n你必須在這裡等待準備換班的守衛通過。找個地方躲起來。\n\n<西爾格林在你的地圖做了一個標記。>\n\n你可以從他們身上穿的亮紅色護甲辨認守衛。\n\n跟好他們，但不要太靠近，以免被發現。抵達目的地之後，有可能需要殺死守衛。\n\n孩子的名字叫可琳。祝你好運。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40746] = {title = "進入城中", objective = "到蘇拉瑪爾城與凡席爾會面。", description = "你該進入城內了，<name>。\n\n我要送你去拜訪我忠實的朋友凡席爾。希望你還記得他…我敢保證他還記得你。\n\n我無法與你一同前往，不過我必須再次強調，我給你的偽裝絕非萬無一失。請小心你的腳步，避開視線盯著你的人。\n\n暫時先這樣了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40747] = {title = "傳送師的精湛技藝", objective = "在歐庫雷斯的工坊內取得陳舊的傳送信標和碎裂的傳送護套。", description = "我在逃離宮殿的時候沒時間帶走我的儀器，所以我來搜刮一些設備。\n\n這間舊工坊其實是由幾間被傳送器連接在一起的房間組成的。\n\n艾莉珊德手下的傻瓜為了找我而來過這裡，但是我可以在這裡調整傳送網路，讓他們兜圈子。\n\n你進到工坊裡去，我會追蹤你的位置，確保傳送器運作正常。\n\n找到這兩個零件然後帶回來！", progress = "如果要開一個傳送網路到薩莉瑟拉那邊，就非拿到這些器材不可。", completion = "這些東西的狀況不太好，但是還算堪用。", rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40748] = {title = "網路安全", objective = "在歐庫雷斯的試驗室完成閉鎖程序。", description = "我們必須閉鎖設施。否則，我來自宮殿的尊貴同事可能會發現我的秘密，危及我幫你和薩莉瑟拉建立的傳送門。\n\n<歐庫雷斯身旁尚未啟動的調和裝置像是有生命一樣，發出嗡嗡聲。>\n\n這能帶我們前往我在山下的秘密試驗室。我們可以在那裡開始閉鎖程序，展開逃亡行動！", progress = nil, completion = "我們…成功了嗎？", rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40749] = {title = "紀念之物", objective = "放置4束月光百合花束。", description = "花朵輕輕落在你的手中，散發柔光。\n\n雖然這附近完全看不到任何花叢，不過有幾束花就放在這附近的紀念碑上。\n\n也許在其他的墓穴上放一些花，就能沖淡這裡的沉重氣氛。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40753] = {title = "布靈登6000型", objective = "我的設計初衷是為了發送禮物，而我的觀測結果顯示，你的專長則是接收禮物。\n\n那麼，要不要來場互蒙其利的交易？您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n布靈登6000型禮物包"}
MultiLanguageQuestData['tw'][40755] = {title = "大海撈針", objective = "與卡德加一起進入卡拉贊，尋找創世之柱的資料。", description = "麥格尼的訊息讓人靈機一動。有朋友能跟泰坦溝通，果然好處多多。\n\n是時候進入卡拉贊了。別嫌我囉嗦，但那裡真的非常危險。無數法術在那座高塔裡交錯縱橫，在交互作用之下，結果往往無法預測。隨時提高警覺。\n\n我會在裡面等你。給我一點時間…我需要好好整理一下思緒。這個地方充滿了我的回憶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "秘法淨化手套屠魔手甲滅魔者纏手軍團毀滅護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][40760] = {title = "密使", objective = "與『噬魂者』艾萊莉交談。", description = "我們有訪客來了…伊利達瑞，這讓情況變得更加撲朔迷離。\n\n自從他們的主人在黑暗神廟殞落以來，這些惡魔獵人就被囚禁起來。看守者願意放出他們，只代表情況已經危在旦夕。\n\n他們代表團的團長『噬魂者』艾萊莉宣稱奧格瑪面臨隱藏的威脅。我暫且准許他們在城內建立一個營地。\n\n你應該馬上去找她談談。查明他們所稱的威脅是否可信。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40761] = {title = "來自歐羅納爾的低語", objective = "調查歐羅納爾遺跡。", description = "以太族、虛無、黑暗那魯…我認為他們互有關聯。\n\n你跟費倫去找三傑聖物的時候，我去察看了下面的廢墟。那裡還有人活著，<name>。\n\n破碎者在我們西邊的建築物裡流連。我聽不懂他們說的話，但是我猜他們的心智已經失常。\n\n如果虛無是罪魁禍首，我們有必要從那裡展開調查。\n\n我也會同時著手進行研究。", progress = nil, completion = "這裡很不對勁。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40762] = {title = "走火入魔的代價", objective = "將指揮官多米泰爾的頭盔帶給洛席斯‧喚月。\n\n已提供物品：\n", description = "指揮官多米泰爾可說是夜裔精靈腐化的具體象徵。厭惡不屬於他們的力量，卻受他們大博學者所蠱惑，將毀滅月之守衛視為自己的唯一使命。\n\n將她的頭盔帶回去給洛席斯，做為她死亡的證明。", progress = nil, completion = "我才在懷疑為何突然間沒了她的消息。這對我的心情或許只是小有撫慰，但對於夜裔的部隊來說卻是極大的打擊。做得很好，&lt;name&gt;。", rewards = "您會收到：\n\n夜裔指揮官徽記"}
MultiLanguageQuestData['tw'][40763] = {title = "資源的重新分配", objective = "收集20瓶秘能酒。", description = "最近有些變動影響了秘能酒的供應。這是我們最重要的資源。\n\n薩莉瑟拉應該跟你說過，夜裔如果沒有秘能酒作為力量來源，會發生什麼事。\n\n隨著惡魔到來，已經出現配給問題。許多人已經撐不住了。\n\n盡量幫我帶回秘能酒吧，愈多愈好。我會確保它送到需要的人手中。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40783] = {title = "伊露恩之鐮", objective = "在暮光森林與瓦隆恩‧定枝碰面。", description = "我收到消息，泰蘭妲親自下令解禁伊露恩之鐮，讓這把強大的神兵協助我們奮戰。伊露恩之鐮本為瓦隆恩‧定枝調查暮色森林狼人詛咒所用，現在他本人已同意交出武器。\n\n勇士，我確信你可以使用這把武器，而不受其獸性狂怒支配。你必須前往暮色森林取得這把鐮刀，利用它來對抗我們的敵人！", progress = "這是個沉重的負擔，希望你已經做好了準備。", completion = "很高興見到你，勇士。\n\n你準備好要肩負重任了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40784] = {title = "適得其所", objective = "從瓦隆恩手中接過伊露恩之鐮。", description = "雖然我不大贊同，但泰蘭妲希望能讓伊露恩之鐮重回戰場，再次發揮能力對抗燃燒軍團的威脅。如果伊露恩之鐮是交給你這樣致力於保衛平衡的英雄使用，我也比較能放心一點。\n\n伊露恩之鐮上次釀成了不小的災難。流竄於鐮刀內的狂野力量如怒濤般驚人，使用時須知分寸。\n\n將我的話銘記在心，拿著這把鐮刀剷除我們的敵人吧。願伊露恩之光保護你。", progress = nil, completion = "瓦隆恩…\n\n那是…黑騎兵！\n\n我們受到森林的保護，他們是怎麼找到這裡的？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40785] = {title = "黑色勁敵", objective = "在暮色森林的密斯特曼托莊園開始搜尋伊露恩之鐮。", description = "我不敢相信黑騎兵追我們追到了這裡。他們對艾澤拉斯神兵的渴望已久，尋覓鐮刀已有好些時日。我原本以為這片森林能保護我們…\n\n而現在，我們失去了瓦隆恩…\n\n你必須獵捕他們，<name>。找出黑騎兵，取回鐮刀。我們上次是在暮色森林的密斯特曼托莊園遇到他們。從那裡找起吧。\n\n然後，<name>…為瓦隆恩復仇。黑騎兵必須為此付出代價。", progress = nil, completion = "我果然是對的，你在尋找鐮刀。如果要取回鐮刀，我們必須做到暮色森林居民從未嘗試過的事。\n\n我們必須獵捕黑騎兵。\n\n我之前在搜捕狼人教徒時遇到了他們，之後便一路追蹤，如今也有一段時間了。他們是這塊土地上的害蟲，他們聚藏的神兵，都是用不當的手段得來的。\n\n如果我們想要取回這件神兵，就必須找到他們的藏身處。正好，我可能有我們需要的線索。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40786] = {title = "悶燒餘燼", objective = "把悶燃的時光扭曲灰燼帶到奧格瑪給琪雅特克。", description = "當你剛碰到這餘燼的時候，觸感是冰涼的，但它會無預警地燃燒起來，又很快地熄滅。石頭在你手中的時候，火與龍的幻象在你腦海裡旋舞，但你能聽到在奧格瑪發生的對話，也能看到熟悉的傳送門景象浮現在你眼前。", progress = nil, completion = "啊，又是這些奇怪的文物。最近的時間流「已經」變得太混亂了…呃…還是它會變得「更」混亂？\n\n&lt;她大大地嘆了一口氣。&gt;", rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][40787] = {title = "悶燒餘燼", objective = "把悶燃的時光扭曲灰燼帶到暴風城給琪雅特克。", description = "當你剛碰到這餘燼的時候，觸感是冰涼的，但它會無預警地燃燒起來，又很快地熄滅。石頭在你手中的時候，火與龍的幻象在你腦海裡旋舞，但你能聽到暴風城熙熙攘攘的嘈雜聲，也能看到熟悉的傳送門景象浮現在你眼前。", progress = nil, completion = "啊，又是這些奇怪的文物。最近的時間流「已經」變得太混亂了…呃…還是它會變得「更」混亂？\n\n&lt;她大大地嘆了一口氣。&gt;", rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][40793] = {title = "計畫之中", objective = "和徐大師交談。", description = "你的武器已經達到前所未見的強度，現在該是向燃燒軍團主動出擊的時候了。\n\n徐大師在訓練場設了一個指揮桌，並從艾澤拉斯各地盟軍收集了許多情報。\n\n宗師，等你準備好，他就能為你更新戰況了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40794] = {title = "女王復仇號的命運", objective = "帶著船長日誌到達拉然的狼牙領區找瑟提斯中尉。\n\n已提供物品：\n", description = "<這是值得分享的情報。或許達拉然的狼牙領區裡有人知道如何運用這項資訊。>您會收到：\n\n", progress = nil, completion = nil, rewards = "黯狼守望披風聯盟十字軍胸甲聯盟輔助鍊衫軍情七處標準配發外衣暴風城教士法衣您會收到：\n\n提爾石板"}
MultiLanguageQuestData['tw'][40795] = {title = "戰鬥開始", objective = "選擇你在破碎群島的第一個攻擊目標。", description = "燃燒軍團在艾澤拉斯所到之處，都會成為廢墟。如果我們想在這場戰爭中取得些許勝算，我們就必須攻擊它們在破碎群島內的大本營。\n\n我畫出了一張破碎群島的地圖，並列出了我軍在那裡必須完成的任務清單。\n\n你在使用地圖之後，應該要立刻選出我們的第一個攻擊目標。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40796] = {title = "徘徊在邊緣", objective = "給阿布撒隆100份上古法力。", description = "我犯…犯錯了…\n\n<阿布撒隆呼吸急促。>\n\n我想要改正一切…我想活下去！但瘋狂…凋萎侵蝕著我。\n\n我正在…步向死亡。\n\n<阿布撒隆無助地看著你。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40798] = {title = "抓住希望", objective = "將一封信交給阿布撒隆的妻子諾瑞莎。", description = "你的仁慈打動了我，朋友。\n\n我以為自己會永遠成為空殼一般的凋萎者，居無定所四處遊蕩，但薩莉瑟拉邀請我加入她。\n\n我選擇跟族人一起留在這裡，我們會一起奪回蘇拉瑪爾。\n\n在那之前，我有一個請求。\n\n請把這封信交給我的妻子。我想告訴她我還活著，還有一些別的事務。\n\n請把你賜予我的希望也送去給她。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一小瓶弧光酒"}
MultiLanguageQuestData['tw'][40814] = {title = "生存之力", objective = "選擇一種你想要的神兵武器。", description = "長久以來，我們都依賴伊利丹大人去消滅燃燒軍團最厲害的戰士 - 很多人都擔心要是沒有他，我們剩下的力量會不足以完成任務。\n\n幸好，以後不會再有這些疑慮了。\n\n我們知道傳言中有兩對比伊利丹大人手中的戰刃更強大的武器，而且並非遙不可及。\n\n要是我們動作夠快，就能取得其中一對，而且不需要放鬆我們對燃燒軍團動向的監視行動。\n\n必須由你做出判斷，決定哪一對更值得我們花時間去爭取，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40815] = {title = "由內攻破", objective = "到法隆納的鎮壓角找珂娃絲‧血棘。", description = "我們的惡魔獵人，珂娃絲‧血棘和瑟雅娜‧夜刃帶了一小隊伊利達瑞的成員穿越法隆納。他們的任務是從內部削弱燃燒軍團的勢力。\n\n我已經有好一陣子沒聽到他們的消息了。\n\n要是你能找到他們，帶領他們完成任務，那就再好不過了。對吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40816] = {title = "生存之力", objective = "選擇一種你想要的神兵武器。", description = "我和伊利丹或許意見相左，但連我也無法否認他的力量非常強大。多次戰役中，都仰賴他解決掉燃燒軍團最厲害的手下。\n\n然而，我們現在或許有機會改變這個情況。\n\n傳言中有兩對武器，力量比伊利丹手中的戰刃更加強大，我們可以設法取得。\n\n不過，我們人數太少，沒有辦法兩對都拿到，畢竟還要繼續監視燃燒軍團的行動。我怕這大好機會稍縱即逝。\n\n身為伊利達瑞現階段的領導人，你必須做出選擇。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40819] = {title = "巧做安排", objective = "在紫羅蘭堡外與凱恩‧日怒碰面。", description = "你還記得瓦瑞迪斯嗎，<name>？他曾經是我們的首席訓練師，但在多年前和黑暗神廟一起陷落了。\n\n或許…只是我們這麼想。\n\n珂娃絲看見這個叛徒和燃燒軍團一起行動，他手上還揮舞著一對戰刃，灌注了她前所未見的能量。\n\n祈倫托將一個埃雷達爾領主關在紫羅蘭堡，他應該知道瓦瑞迪斯的要塞在哪裡。牢獄看守者也同意考慮讓我們前去找那個惡魔。\n\n該是說服他們的時候了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40823] = {title = "重建議會", objective = "在懼痕裂隙救活瑞特辛‧焰慍。", description = "看來朋友引起梅菲斯托的注意了。這真是壞消息，那個驚懼領主一定想報失去大將的仇。\n\n朋友光靠懼痕的力量不能打敗他。朋友還需要更多強大術士的幫忙，像是被抓起來的那些人。\n\n卡萊德斯覺得那個獸人還躺在你被鐐銬困住過的地方。好朋友必須救活他，然後重建議會！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40824] = {title = "懼痕之路", objective = "使用懼痕作戰計畫來選擇你的第一個區域。", description = "看來黑穫議會雖然失敗，但你卻獲得了空前的成功。懼痕的兵力會是我們得力的盟友，但可能還不夠。\n\n目前我們必須將重點放在重建議會上。我會派出密探，打聽議會成員遭到囚禁的位置，並找出其他與我們理念相同的術士。\n\n在占卜池跟我會面，我們會在那邊計畫未來的行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40829] = {title = "LFGDungeons - Draenor 6.2 - Raid Finder - 1st", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40830] = {title = "近在咫尺", objective = "將歐庫雷斯帶到位於沙亞蘭的薩莉瑟拉處。", description = "<歐庫雷斯眼神渙散，聲音斷斷續續。>\n\n我們…我們接近了嗎？\n\n好餓…", progress = nil, completion = "謝謝你救回歐庫雷斯。他對於我們的計劃是無可取代的戰力。", rewards = "您會收到：\n\n黃水晶傳送信標索引"}
MultiLanguageQuestData['tw'][40832] = {title = "無冕者的召喚", objective = "閱讀密封的信件，並依信內指示行動。", description = "我的上級對我下達嚴格的指令，務必盡快將此信送到你手裡。\n\n信件內容只有你才能看。\n\n祝你好運。", progress = nil, completion = "我聽過你的名字，&lt;name&gt;。\n\n很抱歉對你有所隱瞞，只是我們不能隨便讓人知道我們在這裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40834] = {title = "追查詛咒", objective = "護送瑞維爾‧寇斯特從暮色森林的密斯特曼托莊園到逆風小徑的埃瑞丁營地。", description = "先前在與他們的衝突中，我得以一探他們的過往。純淨披風所賜與的神聖異象，讓我看見了黑騎兵的過往身分。\n\n走吧，我們必須前往逆風小徑的埃瑞丁營地。我會在途中好好解釋。", progress = nil, completion = "奇怪，黑騎兵竟然沒跟過來。不過沒關係，這是一件好事。\n\n我相信找到黑騎兵的關鍵就在這附近。讓我們開始搜索吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40835] = {title = "擾亂過去", objective = "在埃瑞丁營地周圍尋找黑騎兵的線索。", description = "當年商人埃瑞丁就是在這裡設立營地，向麥迪文兜售各種可疑商品。這麼多年了，這裡居然毫無改變，從這種詭異狀況來看，我判斷這營地的主人可能還在這裡活動。\n\n協助我搜索這個營地。看看能不能找到跟黑騎兵有關的線索。", progress = nil, completion = "日記散發的黑暗能量不斷嗡嗡作響，上面似乎是埃瑞丁的字跡，記載著他在逆風小徑的所作所為。其中一筆引起你的注意：\n\n「夜行狼人最近騷動不已，據說伊露恩之鐮已經不在達納蘇斯。狼人總是受鐮刀吸引，可見它一定是接近這裡了。那些狼人會帶我找到它的。\n\n天殺的夜精靈以為神兵在他們的保護下很安全。他們很快就知道自己錯得離譜。」", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40837] = {title = "逆風獵殺", objective = "跟隨夜行狼人的蹤跡。", description = "是夜行狼人！如果他們在逆風小徑，那他們也一定在尋找鐮刀。\n\n我們分頭追蹤他們吧。讓我們看看他們的蹤跡通往何處…", progress = nil, completion = "狼人似乎往卡拉贊的地下墓穴移動。\n\n該不會…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40838] = {title = "黑騎兵", objective = "擊敗黑騎兵並奪下伊露恩之鐮。", description = "這個下水道閘門會通往卡拉贊的地下墓穴。我之前沒有多加留意，不過它似乎就是夜行狼人聚集之處。\n\n黑騎兵可能一直都近在咫尺，真是料想不到！來吧，讓我們看看這通往哪裡。", progress = nil, completion = "今天，黑騎兵嘗到有始以來最大的敗績，也是暮色森林人民的一大勝利。\n\n他們欠你一分恩情，我也是。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40839] = {title = "最後一位潛影", objective = "加入潛影議會。", description = "這裡是屬於無冕者的廳堂。我們殺王弒君，傾覆帝國；我們是撰寫真正歷史的無形之刃。\n\n現在坐在你面前的是潛影議會。議會負責派出無冕者之刃前往世界各地，貫徹我們的意志。\n\n而今天帶你來這裡是因為我們有個提案。我們想請你成為潛影議會的最後一席成員，並且協助我們領導無冕者。\n\n你意下如何？", progress = nil, completion = "歡迎成為無冕者，潛影&lt;name&gt;。", rewards = "您會收到：\n\n無冕者徽記"}
MultiLanguageQuestData['tw'][40840] = {title = "絕世武器", objective = "選擇要追尋的武器。", description = "長久以來，我們一直在等待能夠在廳堂之外有所作為的人。\n\n<name>，你就是我們在等的人。你會成為黑暗中的刀刃，為我們擊殺敵人。\n\n為了達到這個目的，你需要能夠殺死燃燒軍團精英的武器。\n\n葛雷邁恩、瑟希斯和瓦麗拉各自都有計畫幫你取得絕世武器，當然任務的難度也不簡單。建議你先跟他們談過之後，再作決定。", progress = nil, completion = "絕佳的選擇。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40847] = {title = "好心提議", objective = "前往藏寶海灣，在紅霧號上與艦隊上將瑟希斯會面。", description = "我想跟你打個商量。\n\n驚懼上將伊莉莎手中有一對詛咒的雙刀，南海之中人人聞之色變。她還偷走了海緣號，我最好的一艘船。\n\n海緣號目前停泊在艾蘇納的岸邊，只要你協助我奪回船隻，那麼那對雙刀就是你的了。\n\n好，如果你覺得這主意不錯，那就到紅霧號來找我。我們把船停泊在藏寶海灣，哼，可害我花了不少錢。", progress = nil, completion = "啊哈！我就知道你會來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40849] = {title = "驚懼雙刀", objective = "奪取海緣號，並且取得驚懼雙刀。", description = "我保證能平安讓你抵達伊莉莎那邊，不過一旦到了之後…嘿，我們都清楚，事情沒人說得準。\n\n計畫很簡單。我們會讓紅霧號盡量靠近，不要被人發現，然後下船。\n\n靠岸後，我們登上海緣號，鼓動和賄賂船員叛變，把船搶下來，然後開始追殺伊莉莎和她那對傳奇的雙刀。\n\n你準備好的時候就說一聲。", progress = nil, completion = "你今天表現得很好，小子。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40850] = {title = "灰石囚犯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40854] = {title = "無盡可能性", objective = "將惡魔劫奪者的外殼帶給達拉然的『扳手』狄迪。", description = "我說，反正你已經下來了，我有些東西你可能有興趣。\n\n<費爾戈指著身後，有一具躺在垃圾堆中的外殼。>\n\n我發現這東西在艾蘇納的海灘上。我很肯定只要稍微修補一下，像你這樣的工程師就可以馬上讓它動起來。\n\n用來對抗燃燒軍團可能很有用。有點像是以毒攻毒，嘿嘿！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40855] = {title = "我們在艾蘇納有人", objective = "到艾蘇納的魔炎入口附近找法戈‧燧鎖。", description = "哇嗚！好吧。這東西缺了一堆零件。\n\n你何不趁我調整它的架構時，去找些新零件還是什麼的呢？\n\n我們在艾蘇納有個同事，或許能幫得上忙。他的名字叫燧鎖。\n\n光讓他拿零件應該是不會出什麼差錯。只要別叫他做東西就好。", progress = nil, completion = "安靜一點，&lt;class&gt;！這個鬼地方到處都是惡魔。\n\n喔，狄迪派你來的？是嗎？那個小姑娘還好嗎？\n\n如果你要找惡魔零件，那我一定幫得上忙！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40856] = {title = "所費不貲", objective = "在魔炎入口收集一支惡魔劫奪者的手臂和一條惡魔劫奪者的腿。", description = "如果你需要惡魔零件，你來對了，這個地方到處都是混帳惡魔。\n\n你要找的，可能在就在此處西南方的傳送門附近。", progress = "找到你要的東西了嗎？", completion = "你和狄迪到底在拼湊什麼東西？\n\n那東西很大嗎？很危險嗎？還是很荒唐？\n\n我也要參一腳！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40857] = {title = "零件片片", objective = "在斯鐸海姆與布萊恩‧銅鬚碰面。", description = "要登記的文物太多，時間永遠不夠。\n\n很高興再次見到你，<name>。布萊恩‧銅鬚和探險者協會正在斯鐸海姆，而且需要你協助追蹤古代泰坦聖物。\n\n等你到了那裡，布萊恩就會告訴你詳細情況。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40858] = {title = "缺少的零件", objective = "回去達拉然找『扳手』狄迪。", description = "看起來你要的都拿到了。你該帶著這些補給回去找狄迪，幫我拍她的背打個招呼！", progress = nil, completion = "&lt;你對狄迪的背後拍了一掌。&gt;\n\n哇呃！我猜是燧鎖打招呼的方式？\n\n看看你帶了什麼給我！喔，好極了，這些全都能派上用場。\n\n我會用我的新發明，自動鐵錘，著手開始修理。\n\n要是你有興趣替自己也做一個，可以拿走這份藍圖。", rewards = "您會學到：\n\n結構圖：自動鐵錘"}
MultiLanguageQuestData['tw'][40859] = {title = "最新潮流：槍盔！", objective = "使用燧鎖的原型槍盔，殺掉10隻魔化的小動物。", description = "所以繫錘幫自己添了不少軍火，是嗎？棒透了！而且這給了我一個靈感「如果我們把槍裝在自己頭上呢？」\n\n哈哈，你聽我說！\n\n你看，你的手已經忙著使用現有武器，但你的頭在幹嘛？不過四處呆望而已嘛。這就是我的構想，讓你的頭也變成武器！\n\n算你運氣好，<小子/小妞>，剛好能幫我測試一下。把這個戴上。然後，去下面射殺一些被惡魔能量污染的小動物。碰！", progress = nil, completion = "我是怎麼告訴你的？這才叫做有用腦袋！\n\n你看到我是怎麼做的嗎？\n\n既然你幫我完成測試了，藍圖我會給你一份。", rewards = "您會學到：\n\n結構圖：槍盔"}
MultiLanguageQuestData['tw'][40860] = {title = "支援前線", objective = "把一箱彈藥送到維爾薩拉的法戈‧燧鎖手中。\n\n已提供物品：\n", description = "<name>，我要你幫我跑個腿。\n\n燧鎖從維爾薩拉送了口信說他們子彈不夠了。\n\n我讓他帶了足夠把整顆行星轟成兩半的彈藥過去，但是燧鎖消耗彈藥的速度就像他是拿子彈在呼吸似的。去幫他一把吧！", progress = nil, completion = "好極了！這正是我需要的！我差點要開始丟小動物當子彈了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40861] = {title = "眼光所及", objective = "在月眠之地四周取回10個可攜式子彈發射器零件。", description = "我們手中的大部份子彈都耗在我的早期發明上了。我叫它可攜式子彈發射器！\n\n沒錯。這可以用來進行無差別攻擊，不用瞄準、不用思考，我們才不需要那樣。\n\n那群植物從樹叢後面衝出來的時候，我們在東邊用了不少這些裝置。\n\n我沒有時間回去拿砲台，你能幫我拿回來嗎？不管砲台變成怎樣，都幫我拿來好嗎？", progress = "那些綠皮的混帳最好祈禱他們沒碰我的子彈噴射器！", completion = "喔，我可憐無辜的子彈噴射器！看他們對你做了什麼。\n\n嗯，至少它們是奮戰至死，我也想這樣。\n\n這是它們的結構圖。將它們設置在你不喜歡的東西附近！", rewards = "您會學到：\n\n結構圖：可攜式子彈發射器"}
MultiLanguageQuestData['tw'][40862] = {title = "充填完畢", objective = "用燧鎖的火藥炸彈殺死15隻幻光夾竹桃。", description = "如果你要進入這片森林，你會用得上一點額外的火力。在那裡面的植物可不是好對付的。\n\n我帶了一些特殊炸藥，應該能把那些肥料突變怪炸得入土為安。\n\n帶上這些，好好教訓一下那些藤蔓怪物！", progress = nil, completion = "真是個除草的好工具，嗯？哈哈！\n\n我猜你一定想要更多炸藥以待日後派上用場，已經先幫你抄好一份結構圖。\n\n我想，讓那些植物跟樹乖乖的，以免它們變得太興奮，總是件好事。", rewards = "您會學到：\n\n結構圖：火藥炸彈"}
MultiLanguageQuestData['tw'][40863] = {title = "緩事急辦", objective = "替狄迪設計的裝置找個合適的動力來源並帶回去給她。然後，看看她的新電池是否管用。", description = "好了，我把所有的問題都解決了。加了幾個螺栓和螺帽，還空出一個新的位置來放動力核。\n\n問題是，我這邊的電池似乎都不管用。我們得想個解決辦法。\n\n我需要你的協助，<name>。我們先從沿途的珠寶設計商店中找些充能寶石來試試。", progress = "希望找個合適的動力來源不會太麻煩你。", completion = "我們辦到了！這是一台功能齊全、看起來壞到骨子裡的惡魔劫奪者。\n\n如果它的動力耗光，這張結構圖上面描繪了我設計的電池。\n\n只要塞枚新的進去就可以動了。\n\n還有，你覺得我們該叫它什麼名字？我在想是不是要用個比較煞氣的，像是「劫福斯」。", rewards = "您會學到：\n\n結構圖：劫福斯電池\n\n您還會收到：\n\n劫福斯電池"}
MultiLanguageQuestData['tw'][40864] = {title = "模組改造", objective = "製作一個劫福斯點心發送模組。然後召喚劫福斯，替它安裝這個模組。", description = "既然我們已經讓這台寶貝動起來了，我們來為它安裝一些很酷的能力吧。\n\n我在修理劫福斯的時候，在它的主機板上安裝了模組連接埠，這樣我們能對它上傳任何東西。\n\n我現在把我設計的一個模組教給你，你幫我安裝到劫福斯上。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：劫福斯維修模組"}
MultiLanguageQuestData['tw'][40865] = {title = "這不是火箭科學", objective = "到斯鐸海姆尋找法戈‧燧鎖。", description = "<name>，我需要你幫忙再去找一次燧鎖。\n\n我派他去斯鐸海姆，收集某項發明所需要的材料，但是已經過了好幾天，他一直沒回來。我不擔心燧鎖，我擔心的是斯鐸海姆。\n\n去看看你能不能找到他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40866] = {title = "什麼彈殼？", objective = "殺死魚人並從它們身上收集10枚貝殼，然後帶回去給燧鎖。", description = "我知道老荷巴爾特叫你下來找什麼珍貴的魚人玻璃玩意兒，不過我自己也有東西要做！\n\n我看到那些魚人帶著形狀奇特的貝殼，剛好能完美搭配我正在做的音樂盒。\n\n給你帶隊，我會在後面跟著。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：音波環境強化器"}
MultiLanguageQuestData['tw'][40867] = {title = "泡泡龍", objective = "在他們營地附近收集12件魚人飾品。", description = "老荷巴爾特要我蒐集魚人身上的閃亮玻璃飾品，但那些死東西就是不肯爽快地交出來！\n\n我試過好鹽相勸，但我不會說魚人話，所以最後只能開槍了。\n\n或許你蒐集小珠的運氣比較好點。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40868] = {title = "非線性時空裝置", objective = "把魚人飾品帶去給達拉然的荷巴爾特‧繫錘。", description = "我得先解決這邊的事，你不如幫我拿那些飾品給荷巴爾特。\n\n更何況，我想跟我比起來，他比較中意你。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：達拉然內部蟲洞產生器"}
MultiLanguageQuestData['tw'][40869] = {title = "用過就忘", objective = "在達拉然對受傷的祈倫托守護者測試原型泵動式繃帶槍。需要的時候，使用繃帶槍校準它。", description = "他們說，「當生命給你又酸又苦的檸檬時，你可以把它做成又甜又好喝的檸檬汁。」這個嘛，生命給了我一屁股的槍枝。\n\n所以我想出了種種方法，把這些槍變成有用的工具。\n\n我最新的修改就是用一把槍來發射繃帶！想像一下，當你在戰場上看到盟友倒下時，只要拉出你的繃帶槍對他開火上繃帶，他就可以繼續作戰！\n\n我只需要你測試第一把，確保它很安全。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：壓動式繃帶槍"}
MultiLanguageQuestData['tw'][40870] = {title = "驚天一擊！", objective = "在達拉然幫狄迪從小孩子手中取回煙火。", description = "<name>，那些小流氓，他們偷走了我的煙火。\n\n你沒看到他們？就在我幫劫福斯製造一個新模組的緊要關頭，這些小鬼跑了進來，拿走我的煙火溜之大吉了。\n\n要拿回那些東西我才能完成手頭上的工作。你能幫我去拿回來嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：劫福斯煙火展示模組"}
MultiLanguageQuestData['tw'][40871] = {title = "鎖了再上", objective = "在艾蘇納找到法戈‧燧鎖。", description = "燧鎖一直在找你，<name>。我想他又需要你幫忙了。\n\n我派他回到艾蘇納去測試我的一些新發明。去歐宣諾海灣的西岸找他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40872] = {title = "轟動落幕", objective = "用槍靴在水面上滑行並取回15塊槍枝組碎片。", description = "當我在，呃，幫荷巴爾特測試這具新飛行背包時，它不知怎麼爆炸了，並把我從空中甩到後面那邊去。\n\n你可以在那邊看到水底有一堆零件。\n\n現在，這雙靴子也是荷巴爾特要我測試的，但不合我的腳。\n\n我想我們可以一石二鳥，讓你試試它的功能，同時把背包的零件從水中撿回來。\n\n提醒你一下，水中可是有鯊魚的。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：槍靴"}
MultiLanguageQuestData['tw'][40873] = {title = "保持乾燥", objective = "收集8桶火藥，並送回位於艾蘇納的法戈手中。", description = "所以，雖然我們找回了背包裡的所有零件，但我的火藥恐怕用光光了。\n\n這是我所遇上過最悲慘的事。\n\n但還有一絲希望。\n\n就在北邊不遠處，有些洞窟裡放滿被擊沉的船隻。這些海巨人可能打沉了幾艘用火砲當做武器的船艦。有火砲就少不了火藥，美妙無比的火藥。\n\n去洞窟裡面找點火藥回來。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：槍枝組"}
MultiLanguageQuestData['tw'][40874] = {title = "我也是不得已", objective = "到歐宣諾海灣殺死10名盤恨奴隸管理者。", description = "如果你跑進那些海巨人的洞窟，幫我一個忙：好好教訓那些納迦搶匪。\n\n他們抓走了我的盜賊同伴，應該要去給他們一點教訓。\n\n我原本想自己去，但要是老荷巴爾特知道我丟著他的東西不管，他會唯我是問的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40875] = {title = "暴殄天物", objective = "在海巨人洞窟中找到羅平，剃掉他的頭髮並繪製刺在頭皮上結構圖的副本。", description = "我們的盜賊朋友羅平在我們來這的時候，被骯髒的納迦給綁走了。他不見了！納迦把他拖到海灣那去了！\n\n但真正的問題是他身上有一張結構圖，記載了一個我數一數二的偉大發明。\n\n之所以是「他身上」，是因為我把結構圖刺青在他的頭頂上。以策安全嘛！\n\n當你找到他時，就把他頭給剃了，然後快速抄一份結構圖的副本。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：滅團偵測水晶塔"}
MultiLanguageQuestData['tw'][40876] = {title = "人槍一體", objective = "回到達拉然去找荷巴爾特，並向他報告燧鎖的工作內容。", description = "好吧，看來我在這邊的工作告一段落了。我會開始打包，啟程回到達拉然。\n\n如果你不介意的話，能不能轉告荷巴爾特下面發生了什麼事？或許告訴他那場爆炸讓零件散了一地、淹水、還有人被抓啥的。\n\n你是個稱職的同伴，<name>！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：更好的槍盔"}
MultiLanguageQuestData['tw'][40877] = {title = "英靈殿：開懷掃射", objective = "從英靈殿的歐丁身上取得活力符石。", description = "為了完成我的最新發明，我需要一個名為活力符石的特殊古物。\n\n據說英靈殿之王歐丁就是用它來賦予他的傀儡生命。\n\n我要求的這件事不容易辦到，我需要你從歐丁身上奪走這顆符石，把它帶回來給我。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：扳機"}
MultiLanguageQuestData['tw'][40878] = {title = "紫羅蘭堡之襲：騙過死亡", objective = "製作2個滅團偵測水晶塔。前往紫羅蘭堡取回一具電漿雷射砲，然後把這些東西都交給達拉然的『扳手』狄迪。", description = "荷巴爾特給我看過你找到的一個設計，這又給了我設計劫福斯模組的靈感。\n\n但不幸地，我沒有測試模組所需要的材料。\n\n你是否能替我做兩個滅團偵測水晶塔呢？\n\n我還需要一具電漿雷射砲，你應該可以在紫羅蘭堡中找到。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：劫福斯滅團偵測模組"}
MultiLanguageQuestData['tw'][40879] = {title = "你來我往", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：劫福斯機甲戰鬥模組"}
MultiLanguageQuestData['tw'][40880] = {title = "電擊迴路", objective = "找到布靈登的發明家。", description = "既然你人在這裡，我想，你能不能幫我追查一些事情。\n\n我猜你對布靈登不陌生吧，嗯？這個嘛，我一直在到處打聽，但似乎沒有人知道它的設計圖究竟來自何方。不過我倒是聽很多人提起一個地方：\n\n52區。\n\n想不想來趟遠足啊？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：布靈登的電路設計導覽"}
MultiLanguageQuestData['tw'][40881] = {title = "油頭油臉", objective = "回到達拉然去找『扳手』狄迪，並讓她看看你的發現。", description = "狄迪一定很想看看你找到的這份日誌，以及上面的線路圖。\n\n你應該盡快回到她身邊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n結構圖：劫福斯閃亮亮模組"}
MultiLanguageQuestData['tw'][40882] = {title = "眾星之廷：改善後座力", objective = "前往蘇拉瑪爾貴族區，為荷巴爾特取回秘法壓縮機。", description = "<name>，你一定很高興，因為我已經把燧鎖做的護目鏡改良成更新、更棒的版本。\n\n我設計的這一副威力倍增，不幸的是它的後座力也會加倍。你戴上去後一使用，恐怕脖子會斷掉。\n\n但我找到了解決之道。在蘇拉瑪爾城市深處，有一種魔法的機械裝置可以將反作用力消弭於無形。\n\n幫我找出這個裝置，我們就可以回頭談生意！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n結構圖：半自動火炮顱盔結構圖：短管火炮顱盔結構圖：雙管火炮顱盔結構圖：準星火炮顱盔"}
MultiLanguageQuestData['tw'][40883] = {title = "守衛的命運", objective = "請找到奈亞盧斯‧織星者、加勒蘇斯‧河樹及凱莉雅‧風羽的屍體，為他們舉行葬禮。", description = "<薩睿納斯仔細地打量你。>\n\n你不是他們的一員。\n\n在蘇拉瑪爾的護罩失效後不久，夜裔精靈就登門拜訪。儘管彼此間久不來往，我們仍認為他們是朋友。\n\n我們大錯特錯。\n\n他們大肆進攻我們的要塞，開始一場大屠殺。我們根本全無準備。儘管我們起身反抗，卻被打得落花流水。\n\n要塞失陷，我們的領導者喪命，屍體就橫躺在大街上。\n\n請找到他們，讓他們善終。\n\n搜索的時候，請留意有沒有倖存者。可以的話，請幫助他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n月之守衛聚焦之石"}
MultiLanguageQuestData['tw'][40890] = {title = "伊露恩之淚", objective = "使用位於達拉然中央的傳送門，將伊露恩之淚放在肖像廳裡。", description = "伊露恩之淚輕盈地浮動著，在一道空靈的月光下熠熠生輝。", progress = nil, completion = "&lt;大法師卡德加在這裡準備了空位放伊露恩之淚，其餘的創世之柱也一樣。&gt;", rewards = "夏達希爾法衣夏達希爾外套夏達希爾背心甲夏達希爾護胸您會收到：\n\n"}
