MultiLanguageQuestData['tw'][40927] = {title = "詹德維克的最後希望", objective = "到沙許塔爾岩洞與托莉爾碰面。", description = "指揮官莫提斯曾經與海巨人協商？\n\n沒有你的幫忙，這座村莊一定會被沙許塔爾和海巨人的聯軍攻破。\n\n<托莉爾靜靜站在那裡一段時間。>\n\n到蒼風灣外的地下洞穴與我會合。\n\n我想讓你見識一下足以扭轉戰局的東西。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n詹德維克統領的墜飾石"}
MultiLanguageQuestData['tw'][40929] = {title = "力量的象徵", objective = "收集8枚燃燒軍團紋章。", description = "這隻惡魔握有情報，可以讓我們知道指揮者的下落。\n\n不幸的是，他害怕他的主人更勝於害怕我們。我們得設法改變他的想法。\n\n強大的燃燒軍團士兵通常會帶著象徵他們在惡魔軍團內階級和地位的紋章。\n\n找出在魔魂堡內最強的惡魔，殺了他們，把紋章拿回來給我。\n\n我們要讓這個龍舌的奴僕知道他應該害怕的是誰…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40930] = {title = "天啟", objective = "前往暮色森林的密斯特曼托莊園尋找天啟的蹤影。", description = "<巫妖王冰冷的聲音再度充斥你的腦海中>\n\n有一把古老的劍失落於時光之中。它擁有向燃燒軍團復仇所需要的力量。\n\n這把劍叫作天啟。\n\n我察覺到現在逆風小徑的黑騎兵擁有這把劍。他們使用魔法躲過我的追查，但是沒有人能躲過天譴軍團！我的密探曾經在密斯特曼托莊園附近發現他們的蹤跡。\n\n\n前往那裡，<name>。擊敗黑騎兵，取得你的武器！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40931] = {title = "追查詛咒", objective = "護送瑞維爾‧寇斯特從暮色森林的密斯特曼托莊園到逆風小徑的埃瑞丁營地。", description = "非常好。那我先向你自我介紹。我是聖光牧師瑞維爾‧寇斯特，也是失落神兵的尋找者。我過去曾與黑騎兵對戰，這次回來是要把他們趕出這個地方。\n\n黑騎兵行蹤成謎，不過我有線索可以找到他們。在從前的對抗中，我得以一窺他們的過去。看過純淨披風賦予的幻象後，我終於瞭解黑騎兵的來歷。\n\n跟我一起前往埃瑞丁營地。我會在路上跟你解釋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40932] = {title = "擾亂過去", objective = "搜索埃瑞丁營地，尋找與黑騎兵有關的線索。", description = "這裡是商人埃瑞丁所設的營地，他從這裡不斷向麥迪文供應各種可疑商品。\n\n長久以來，這裡絲毫沒變。這種不尋常的情形，我懷疑可能和它的前主人有關係。\n\n協助我搜索這個營地。看看能不能找到跟黑騎兵有關的線索。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40933] = {title = "陰森的任務", objective = "喚醒埋在逆風小徑潮濕墓穴中的死者，直到找出知道黑騎兵所在地的指路人為止。", description = "陰濕土壤？低淺墓穴？\n\n我覺得日記中的地點是指卡拉贊附近的湖邊墓地。沒有人知道裡面埋的是誰，不過這很可能是找到黑騎兵的關鍵。\n\n你可以…跟死者交談吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40934] = {title = "黑騎兵", objective = "在卡拉贊地下墓穴擊敗黑騎兵，取得天啟。", description = "地下墓穴？我從沒聽過這種地方。難道，他是指…\n\n河邊有一個下水道出口，通往卡拉贊下面的墓穴。我過去沒有留意過，不過它很可能就通往那個鬼魂要我們去的墓穴。\n\n仔細一想，黑騎兵很可能一直躲在我們的眼皮底下！走吧，讓我們看看這條下水道通往哪裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40935] = {title = "復仇之喚", objective = "使用死亡之門前往冰封王座，接受巫妖王的印記。", description = "看來我對你有所誤解，死亡騎士。你幫助我對抗黑騎兵，榮耀了聖光。也許我實在太過武斷。\n\n你讓我得以達成目標，將這些神兵交還給命定的擁有者。至於天啟，我覺得把它交給你，才是最安全的。\n\n希望它能幫你打敗燃燒軍團，死亡騎士。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40938] = {title = "光明與虛無", objective = "協助費倫完成他的神秘任務。", description = "阿隆索斯‧法奧是一位珍貴的盟友，而且他對你的直覺非常準確。有一件能為世界帶來莫大福祉的任務，我認為只有你能協助完成。\n\n我必須帶你前往艾澤拉斯之外的遙遠地方，完成一個我族很久以前就開始的工作。你願意協助我們嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40941] = {title = "文件：進攻廢坑", objective = "對格古隆德廢坑的黑石獸人發動進攻。", description = "根據地在格古隆德廢坑的黑石獸人部隊為鋼鐵部落提供了大量軍力。如果我們可以踏平他們的領土，那麼鋼鐵部落的殘黨也會失去與我們對抗的信心。\n\n如果你決定要戰鬥的話，帶上你的朋友。黑石獸人可不太容易對付。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][40942] = {title = "文件：進攻廢坑", objective = "對格古隆德廢坑的黑石獸人發動進攻。", description = "根據地在格古隆德廢坑的黑石獸人部隊為鋼鐵部落提供了大量軍力。如果我們可以踏平他們的領土，那麼鋼鐵部落的殘黨也會失去與我們對抗的信心。\n\n如果你決定要戰鬥的話，帶上你的朋友。黑石獸人可不太容易對付。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][40943] = {title = "文件：進攻撒塔斯的中心", objective = "前往塔拉多爾的撒塔斯城，對薩格萊部隊發動進攻。", description = "撒塔斯深處的薩格萊部隊一天比一天壯大。我們已無法再坐視他們造成的威脅了。\n\n如果你決定與城市深處的薩格萊部隊交戰，請帶著戰友。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][40944] = {title = "文件：進攻撒塔斯的中心", objective = "前往塔拉多爾的撒塔斯城深處，對薩格萊部隊發動進攻。", description = "撒塔斯深處的薩格萊部隊一天比一天壯大。我們已無法再坐視他們造成的威脅了。\n\n如果你決定與城市深處的薩格萊部隊交戰，請帶著戰友。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n頂尖水晶"}
MultiLanguageQuestData['tw'][40947] = {title = "特別快遞", objective = "使用夜裔法刃從夜裔信差身上取得3疊信件。", description = "薇玲的孩子失蹤了。我大概能猜到發生什麼事，但我必須確定才行。\n\n大多數守衛都會透過信差傳達敏感訊息。其中，魔法一向是高階官員的專利。\n\n帶著這把法刃。注意不要碰到刀刃的部分。用它悄悄地攔截信差，截取他們身上的信件。\n\n運氣好的話，書信上會提到小女孩的確切位置。\n\n畢竟守衛無所不知。\n\n<西爾格林故意露出微笑。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40949] = {title = "無須眷戀", objective = "驅趕5隻徘徊的月落角鷹獸", description = "我一直在觀察你 - 你不是他們的同夥。\n\n<伊凡涅爾輕輕地咳了幾聲。>\n\n我剩下的時間不多，但在你離開之前，我還有一件事要請你幫忙。\n\n這裡的角鷹獸還在激烈奮戰，守護牠們的家園和月之守衛同伴。牠們不願接受守衛已經不在的事實。\n\n拜託…把牠們趕走。讓它們知道，這裡已經沒有值得牠們奮戰的東西了。", progress = nil, completion = "謝謝你。知道牠們不再繼續為了我們犧牲自己，我感覺好多了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40950] = {title = "表揚功績", objective = "和你的潛影同伴一塊慶祝成功取得神器。", description = "一切都照計畫進行。你的新武器就是證明。\n\n在接下來這段時間，我們就得靠你大顯神威了。但如果我們現在不辦個慶功宴，那可就是個大疏忽了。\n\n你意下如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
