MultiLanguageQuestData['tw'][40958] = {title = "運籌帷幄", objective = "到神獵廳與謀士柴薪交談。", description = "你的神兵現在已經準備好了，該是好好計畫對燃燒軍團首次攻擊的時候了。\n\n去找我們的軍師 - 謀士柴薪談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40959] = {title = "戰役開始", objective = "在指揮圖上選擇攻擊目標。", description = "燃燒軍團以為我們還沒從破碎海岸的挫敗中恢復元氣。\n\n讓我們證明它們錯了。\n\n我們的斥候已經畫出破碎群島的地圖，也盡可能收集每個地區的所有資訊，方便我們進行未來的攻擊行動。\n\n選擇首要攻擊的區域，親自率領隱獵團出征。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40960] = {title = "夜光珍珠", objective = "將夜光珍珠帶去達拉然讓大法師卡德加看看。\n\n已提供物品：\n", description = "你的魚鉤上穩穩掛著一枚前所未見的珍珠。它湛放出冰冷、穩定的光芒，而且大小與重量在你的手中不斷變動。\n\n這肯定是魔法物品，應該帶去給通曉魔法的人看看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40961] = {title = "達拉然噴泉", objective = "將夜光珍珠帶去達拉然噴泉。\n\n已提供物品：\n", description = "這是你釣上來的，對吧？我…我不是很確定你要「我」怎麼處理它。來。\n\n<卡德加輕拍你的頭。>\n\n「做得好。」\n\n至於這枚珍珠…它似乎有股魔力，但是除了這一點之外，我無法透露更多內容。或者用達拉然的噴泉洗一下，看起來會更美？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40962] = {title = "黑水", objective = "和瑪法里恩一起到月神湖探究混沌殘餘的來歷。", description = "跟我一起到月神湖畔去吧。水晶般澄澈的湖水能洗去所有黑暗的障蔽，讓事物的真貌隨之顯現。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n林地看守者的韁繩"}
MultiLanguageQuestData['tw'][40963] = {title = "掌控生死", objective = "吸引3隻野生的月落角鷹獸，解決月落棲地的夜裔精靈。", description = "我們早該知道會發生這種事。我的姐妹死了，我的朋友受傷，而且我們很可能會死在這裡。\n\n我想要復仇。\n\n<黎瑞雅交給你一個裝滿沸騰綠色液體的瓶子。>\n\n我們無法擊敗他們，但我們可以將要塞變成他們的死地。\n\n野生的角鷹獸會被瓶中的氣味吸引。如果野生角鷹獸是被這股氣味吸引來的，牠們就會變得異常凶暴。\n\n用它清出一條道路，深入要塞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40964] = {title = "裂隙猶存", objective = "到圖書館找到洛席斯‧喚月。", description = "夜裔精靈大肆進攻要塞時，我跟洛席斯在一起。\n\n他和他的元素成功地把我們大多數人送出圖書館，但輪到他自己的時候，卻被困在角落。\n\n我知道他還活著，我感覺得到！不過我無法親自回去找他，我受了重傷。\n\n峇嘴會帶你前往我們上次見到洛席斯的地點。等你做好離開的準備，就讓他知道。\n\n快點去吧，祝你好運！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40965] = {title = "挖坑埋雷", objective = "利用陷阱符文殺死50個夜裔精靈。", description = "他們洗劫了我的圖書館，<name>。\n\n如果他們想要我們的知識，我們就讓他們見識一下。\n\n這個符文可以讓你在地上施放誘捕法術。等到夜裔精靈穿過門檻，他們就會親自體會月之守衛的真正力量。\n\n給他們好好上一課！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40966] = {title = "臥虎藏龍", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40967] = {title = "殘存典籍", objective = "找出並取回《守衛名冊》、《月之魔法》、以及《恆井餘生》。", description = "有三部對我而言非常重要的秘典，但我無法拋下守護者獨自去尋找。\n\n裡面有絕對不能讓夜裔精靈得知的秘密和咒語。\n\n<洛席斯將手伸向你的額頭，三部秘典的名稱在你的腦海中浮現>\n\n如果我們無法學習典籍的奧秘，至少也應該盡量保留下來。動作快，<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔月落文字"}
MultiLanguageQuestData['tw'][40968] = {title = "回收失竊的能量", objective = "取得一個烈性法術集核。", description = "雖然我的傷不至於會讓我喪命，卻讓我失去戰鬥能力。關於如何對付剩下的夜裔精靈，我有自己的想法。\n\n他們一來，就立刻破壞了我們的防禦法陣。他們之中應該還有人帶著能夠重新啟動法陣的法器。\n\n找到法器，然後找一隻角鷹獸。牠們在堡壘四處徘徊。\n\n這些忠心的生物會帶你飛上天空，並處理好其他事情。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40969] = {title = "織星者的命運", objective = "找到席拉娜‧織星者", description = "我會把這些秘典交給薩睿納斯。\n\n我還有一件非常擔心的事，我想請你代替我去處理這件事。\n\n我的妻子席拉娜‧織星者就住在橋對面的織星者聖所裡。夜裔精靈進入要塞不久後，它就淪陷了。\n\n如果她還活著的話，她就必須要知道我們的行動。我們非常需要她的力量。\n\n替我傳達我的思念，我隨後就會跟上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40970] = {title = "始作俑者", objective = "殺死咒術師塞雷利安並取得星術師拱心石。", description = "必須阻止咒術師塞雷利安。\n\n他一到這裡就馬上去找我父親的書房，而且到現在都還沒出來。我擔心他可能找到某個非常危險的東西。\n\n它是星術師的拱心石。可用來操控要塞的防禦機制。\n\n這類魔法本來應該用來保護月之守衛，如果把它用在其他地方，就會帶來超乎想像的破壞力。\n\n請取回拱心石。必要的話，就算殺死咒術師塞雷利安也沒關係。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n星術師的指南針"}
MultiLanguageQuestData['tw'][40971] = {title = "百試百靈的誘餌", objective = "使用惰性水晶讓3名皇家咒術師超載。你必須站在法力聚焦器上，才能使用水晶。", description = "你看到這個房間外的夜裔精靈了嗎？\n\n他們把我們關在這裡，就像籠中的老鼠。在他們搜索聖所，尋找我父親的聖物時，把我們集中看管，對他們更為方便。\n\n只要一點幫助，我的同伴和我就能逃到更上層。\n\n拿著這顆水晶。站在法力聚焦符文上，用它讓一名咒術師超載。\n\n他們的召喚物就會反咬他們一口，製造一個缺口。\n\n妥善使用水晶，清出一條道路後，我們會在要塞最上方等你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][40972] = {title = "月之守衛的最後一戰", objective = "與薩睿納斯、洛席斯及席拉娜一起離開月之守衛要塞。", description = "這就是所有倖存的月之守衛。\n\n仔細看清楚。\n\n我們現在彷彿失去靈魂的空殼，這一切都要歸功於夜裔精靈。\n\n現在我們已經無能為力。如果想要活下去，我們就必須馬上離開。\n\n以後再來報復。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n月之守衛力量珠寶"}
MultiLanguageQuestData['tw'][40974] = {title = "拉托希斯的試煉", objective = "通過拉托希斯的試煉", description = "拉托希斯的睿智令我敬佩。如果要接受試煉，取得護符的你無疑是最佳人選。通過這次挑戰，<name>，你就能永遠擁有月之守衛的力量了。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40976] = {title = "謁見大酋長", objective = "與薩魯法爾霸王交談。", description = "\n\n惡魔獵人，此刻的情勢相當緊張，大酋長沃金在破碎海岸的慘敗中受了重傷。\n\n我建議你先表明願意協助部落，以免你的到來產生任何…誤會。\n\n城市的防禦目前由薩魯法爾霸王指揮。雖然他對伊利達瑞的態度有所保留，但我相信他會給你機會證明你的價值。\n\n與他交談，請他讓你進入葛羅瑪許堡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40978] = {title = "熊壞壞", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40980] = {title = "沸皮瘟疫", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40982] = {title = "第二視象", objective = "使用你的靈視。", description = "希瓦娜斯就任大酋長或許會對我們不利。她生前是鼎鼎大名的優秀遊俠，但自從被天譴軍轉化，就連女妖之王的部分盟友都存有戒心。\n\n只要有任何一點紛亂的跡象，燃燒軍團就會展開突襲。\n\n就連現在我都覺得情況有些不對勁，<name>。事情恐怕沒有看起來那麼簡單。\n\n快點，使用你的靈視。我們必須知道是否有敵人混入這裡！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40983] = {title = "惡魔四伏", objective = "保護大酋長。", description = "正如我們所懷疑的，<name>！惡魔以為可以出其不意發動奇襲。\n\n快點，準備迎戰！保護女妖之王！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "女妖之王的烙印您會收到：\n\n"}
MultiLanguageQuestData['tw'][40985] = {title = "霜鱗納迦入侵：高嶺", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][40986] = {title = "黑騎兵", objective = "在卡拉贊地下墓穴擊敗黑騎兵，取得天啟。", description = "地下墓穴？我從沒聽過這種地方。難道，他是指…\n\n河邊有一個下水道出口，通往卡拉贊下面的墓穴。我過去沒有留意過，不過它很可能就通往靈魂要我們去的墓穴。\n\n仔細一想，黑騎兵很可能一直躲在我們的眼皮底下！走吧，讓我們看看這條下水道通往哪裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40987] = {title = "復仇之喚", objective = "使用死亡之門前往冰封王座，接受巫妖王的印記。", description = "既然目標已經達成，該是我們分道揚鑣的時候了，死亡騎士。我很高興這是最後一次見到你。\n\n去吧，回去找你的黑暗主人。到此為止了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40988] = {title = "太多廚師", objective = "到達拉然與糯米會合。", description = "你好。我叫做糯米。\n\n我不得不注意到你剛才撿起的食譜…好吧，雖然難以置信，不過我本身會一點料理。\n\n不幸的是，我的戰鬥能力不高，而這個地方又很危險。相反地，你明顯就是非常厲害的<class>。\n\n到達拉然找我。也許我們可以合作一下！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n食譜：風乾鯖魚肉風乾鯖魚肉"}
MultiLanguageQuestData['tw'][40989] = {title = "揮霍的二廚", objective = "到達拉然與糯米會合。", description = "<name>？大師，是你嗎？\n\n你不認得我了嗎？是我，糯米！記得嗎？我們一起在潘達利亞烹飪？更準確地說，是你烹飪，然後我學。我那時候還不過只是個新手。\n\n哇，很高興見到你！\n\n我回到達拉然的廚房了。過來找我！也許我們可以合作一下！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n食譜：風乾鯖魚肉風乾鯖魚肉"}
MultiLanguageQuestData['tw'][40990] = {title = "很好的食譜清單", objective = "學習6個軍團食譜。", description = "我也當過冒險者，可惜我不是那塊料。烹飪才是我的熱情所在：火爐的熱浪、培根滋滋作響的聲音…簡直就是我的天堂。\n\n讓我來幫你，<name><先生/女士>。如果你可以給我一些食譜，我就能在達拉然這裡幫你改良食譜。\n\n我們會成為很優秀的團隊。你覺得呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40991] = {title = "設立實驗廚房", objective = "取得5條糯米的銀色鯖魚，然後交給糯米進行研究。", description = "我會烹飪，但我對打獵、釣魚之類的事，真的很不在行。\n\n不過，只要把食材交給我，我就會用它們來幫你研發新食譜。\n\n我們可以先從我收來的一些魚開始。魚就在廚房後面的桶子中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40996] = {title = "外包業務", objective = "與『閒語者』妮琪交談。", description = "如果可以的話，我想為你提供一些建議，協助你面對接下來的試煉與磨難：對於將無冕者的諸多資源化為助力這件事不要感到任何猶豫。\n\n在這個房間外面有一個佈告欄，是我們用來協調下屬用的。\n\n用那個佈告欄找出妮琪…她可以協助你上手。", progress = nil, completion = "我誰都不認識、什麼都不知道。\n\n唉，算了這樣騙不過任何人。我誰都認識、什麼都知道！潛影&lt;name&gt;！最近過得怎樣啊？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][40997] = {title = "致命效率", objective = "選擇你在破碎群島的第一個攻擊目標。", description = "聽說你打算前往破碎群島，這是真的嗎？\n\n消息傳出來以後，我們就立刻整合手上所有的書本、秘典和論文，總結出一份相當完整的報告！你最好先看一下。\n\n當你人在這裡的時候，這個布告欄就是無冕者發揮影響力的地方：你可以懸賞某個國王的人頭，針對魔絲布料提供獎勵…不管想到什麼，只要寫在這上面，你的手下就會幫你處理好。", progress = nil, completion = "選得好！我們有很多那個地方的情報。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41001] = {title = "擊潰沙許塔爾", objective = "在沙許塔爾遺跡殺死12個沙許塔爾納迦。", description = "沙許塔爾的部隊或許減少了，但是海潮祭司在她身邊部署了她最厲害的納迦。\n\n現在正是一舉擊垮沙許塔爾納迦的良機。\n\n要是此次我們能擊敗他們，就能瓦解這股惡勢力，拯救詹德維克。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41002] = {title = "部落的武器", objective = "在奧格瑪的伊利達瑞營地向艾爾辛‧達萊回報。", description = "看來我低估了你原有的價值。\n\n你們對接下來的戰爭不可或缺。我打算追殺這些惡魔到艾澤拉斯的天涯海角，而你們就是緊追它們不放的箭矢。\n\n告訴那些來到奧格瑪的伊利達瑞，準備為部落效力。\n\n但不要掉以輕心，你們過去曾是背叛者的手下。要是敢背叛我，就算逃到天涯海角，我也不會放過你們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41003] = {title = "皇帝的禮物", objective = "去找塔克塔克，直接飛往常春台取回雪崙，迷霧之杖。", description = "啊，是雪崙，它是末代皇帝所持有的傳奇法杖。如果讓燃燒軍團取得這把武器，它們會釋放出無法言喻的恐懼，襲捲整個大陸。我們必須阻止它們！\n\n如果想要盡快抵達常春台，你應該搭個便車直接前往大陸。猴人風箏大師塔克塔克就在寺廟的西方。立刻去找他，別耽誤了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41008] = {title = "獵人對獵人", objective = "回達拉然的獵人地帶商店，與艾瑪芮爾‧影衛交談。我感覺到纏繞在你身上的命運絲線。你的命運與讓你展開這趟旅程的古老夜精靈繫在一起。\n\n我可以把你送回那座天空之城。在那裡，你必須開始集結眾人，對抗貪而無饜的黑暗。\n\n好好表現，<name>。願猛禽之爪為你發揮強大的力量。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "我感覺到纏繞在你身上的命運絲線。你的命運與讓你展開這趟旅程的古老夜精靈繫在一起。\n\n我可以把你送回那座天空之城。在那裡，你必須開始集結眾人，對抗貪而無饜的黑暗。\n\n好好表現，<name>。願猛禽之爪為你發揮強大的力量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41009] = {title = "獵人對獵人", objective = "前往達拉然的獵人地帶商店，與艾瑪芮爾‧影衛交談。", description = "你有泰坦之擊了，現在該瞭解一下那個讓我們踏上這段旅程的夜精靈了。\n\n她可能會回到獵人地帶，就是我們之前碰到她的那間商店。不論這個艾瑪芮爾‧影衛是誰，我敢用我的鬍子打賭，她肯定在對抗燃燒軍團的戰爭裡佔了一席之地。\n\n再次感謝這段有趣的旅程，<name>。如果需要我幫忙，儘管開口！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41010] = {title = "鮮魚狂亂", objective = "跟著納特‧帕格前往薄暮嶼，然後迅速處理該區域所有的魚。", description = "<name>！\n\n<氣喘吁吁>\n\n你一定要去看看！好多魚，到處…到處都是魚！\n\n就在維爾薩拉的沿海，有東西把它們逼瘋了。\n\n這是我有生以來看過最瘋狂的釣魚活動！\n\n我在下面有艘船。帶著你的釣竿，我會帶你去那裡！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n粼光釣竿"}
