MultiLanguageQuestData['tw'][41027] = {title = "最後一口氣", objective = "在蒼風灣喝下夜落鍊金師的怪異的藥劑。<羊皮紙浸泡在海水中。上面有匆促寫成的文字。>\n\n致找到這張紙條的人，\n\n在被逐出蘇拉瑪爾之前，我是一名鍊金大師。過去，我為夜裔精靈調製了許多有益的藥水和藥劑。\n\n在燃燒軍團到來之後，他們把我的功勞忘得一乾二淨。\n\n在屈服於飢渴而凋萎之前，我想製作最後一款藥劑，讚揚我對海洋的喜愛。\n\n喝下藥劑，帶著我的祝福，探索這片無邊無際的深海吧。您會學到：\n\n", description = "<羊皮紙浸泡在海水中。上面有匆促寫成的文字。>\n\n致找到這張紙條的人，\n\n在被逐出蘇拉瑪爾之前，我是一名鍊金大師。過去，我為夜裔精靈調製了許多有益的藥水和藥劑。\n\n在燃燒軍團到來之後，他們把我的功勞忘得一乾二淨。\n\n在屈服於飢渴而凋萎之前，我想製作最後一款藥劑，讚揚我對海洋的喜愛。\n\n喝下藥劑，帶著我的祝福，探索這片無邊無際的深海吧。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n海行藥水\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][41028] = {title = "脈能網路", objective = "為泰爾亞諾脈能站的明月封印、星辰封印、野獸封印和精靈封印充能。", description = "這座脈能廠年久失修，線路中斷，要修好它就必須為中控室的封印重新充能。\n\n每個法印都需要高能脈流和低能脈流通過。將脈流導引至同一個封印，然後啟動它。\n\n至於我嘛？我負責監督。畢竟你可是來幫忙的啊。", progress = nil, completion = "我得承認你蠻厲害的，或許你真的能幫上我們的忙。", rewards = "您會收到：\n\n部分附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][41030] = {title = "取回符印", objective = "收集7個月之守衛符印。", description = "光滑的方形符印外表看似平淡無奇，但本身卻是極為沉重。\n\n將它握在手中時，掌心傳來一股劇烈的刺痛感。這是純粹力量的聚合體。\n\n如此強大的物品，不應輕易落入夜裔精靈手中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][41031] = {title = "為了人民", objective = "找到秘能酒噴泉，裝滿乾癟的秘能酒囊。然後將秘能酒分給渴求法力的夜裔精靈飲用。", description = "我們有個問題，朋友。\n\n運河對面是比較不富裕的區域。自從惡魔抵達以來，它就被封鎖了。我曾經聽過那些渴求法力的慘叫聲。\n\n把這個酒囊拿去。尋找秘光酒噴泉並裝滿它。\n\n然後去找那些受苦的人，讓他們嘗一口。就目前的情況看來，我們只能做到這樣了。\n\n你的行動絕對不能被看見，<name>。不然下場很糟。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][41032] = {title = "阻止覓法者", objective = "關閉3道覓法傳送門。", description = "夜裔精靈進軍這裡。雪上加霜的是，他們現在帶來更多援軍。\n\n我看到他們開啟通往蘇拉瑪爾的大型傳送門。\n\n他們透過這些傳送門調來他們的傀儡。我的魔法幾乎都對這些傀儡無效，因此對我而言是一大阻礙，讓我無法與其他人會合。\n\n盡量把傳送門都找出來，關閉它們。這應該可以為我們爭取一點時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41033] = {title = "回到馬爾頓", objective = "進入伊利達瑞之門，登上馬爾頓的魔錘號。", description = "傳送門功能完全正常，<name>。喔，我覺得好興奮啊！\n\n請一定要讓捷斯和其他人知道，我們非常期待你的到來。事情太多，時間太少啊。\n\n你會在上面和我們會合，對吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41034] = {title = "測試水質", objective = "在蒼風灣殺死雷茲吉拉、莫提斯和珂塔莉絲。", description = "沙許塔爾納迦已經逃不出你的手掌心了，<name>。\n\n他們絕對想不到，你會直搗他們海中的地盤。趁這個大好機會，殺死他們的指揮官。\n\n宰了他們之後，在詹德維克跟我會面。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][41035] = {title = "魔風的請求", objective = "到達拉然的紫羅蘭之門與莫爾‧魔風會合。", description = "你可能不認識我，但我需要你的協助，<name>。\n\n到紫羅蘭之門找我，我會解釋一切。\n\n請盡快。我擔心時間有限。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41036] = {title = "驚懼領主的目標", objective = "在紫羅蘭堡擊敗卡斯拉納提爾。", description = "卡斯拉納提爾逃出我的掌控，不過我知道他下一步想幹嘛。\n\n他正在尋找稱為守護者熔爐的古代聖物，數個世紀以來，提里斯法議會用這個熔爐將他們的力量灌注到守護者身上。議會把熔爐藏了起來，位置只有議會成員知道。\n\n但現在驚懼領主知道了它的位置。\n\n我們必須前往紫羅蘭堡，希望我們還來得及。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n傳送：守護者殿堂\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][41037] = {title = "不受控制的力量", objective = "啟動魔錘號，集合伊利達瑞部隊。", description = "雖然在你離開之後，我們的人一直盡責地守護這個根據地，但卻無法使用絕大部分的資源和設備。只有身具燃燒軍團領主印記的人，才能完全啟動魔錘號。\n\n還好，你的武器就有這種印記。使用它的力量啟動魔錘號，讓你的部下見識你無窮的力量！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41038] = {title = "蜜酒大師", objective = "到斯鐸海姆與艾綺菈交談。", description = "風暴蜜酒是傳說中的維酷釀酒大師梅爾芭所創。這是她在斯鐸海姆北方海岸的酒莊所在位置。\n\n如果我們能說服她分享她的神秘配方，就能取得決定性的戰鬥優勢。\n\n宗師，你擅長說服他人嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41039] = {title = "失竊配方", objective = "品嚐發酸的風暴蜜酒、淡薄的風暴蜜酒、烈火風暴蜜酒，然後殺掉莫傑恩取得風暴蜜酒配方。", description = "莫傑恩，蔑潮一族的首席釀酒師，握有風暴蜜酒的配方。\n\n我的實力一直都不足以獨自進攻他的堡壘，但有你幫忙，我想我們可以為死去的師傅報仇。從莫傑恩冰冷僵硬的手指拿回配方，是我最大的心願。\n\n等我們到了那裡，順道品嚐一下他的風暴蜜酒。我倒想看看他的釀酒技藝，是否有資格跟我師父相比。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41040] = {title = "英靈殿：釀酒大師", objective = "在英靈殿與梅爾芭交談。", description = "我研究梅爾芭的風暴蜜酒配方有了新突破。\n\n我們需要使用一個由歐丁所有的特製大鍋。\n\n這個大鍋位於英靈殿中。\n\n要進入此崇聖之處，只有一個辦法，就是贏得風暴之神的恩寵。\n\n你必須設法進入戰士大廳。要達成這項任務，你可能需要盟友的協助，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41052] = {title = "懇切的請求", objective = "到卡薩斯平臺與薩魯法爾霸王碰面。", description = "<name>，從破碎海岸一役失利之後，薩魯法爾感覺就不太一樣了。雖然他帶兵有方，而且英勇善戰，但他始終難以放下那場敗仗。\n\n恐怕他已經決定回破碎海岸了。你能找他談談嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41054] = {title = "痛失所愛", objective = "在星歌避難所和泰蘭妲‧語風交談。", description = "瑪法里恩，我的愛…\n\n我看到他出現在幻象中，先是怒氣沖天隨即憂傷不已，而現在我的心靈已感應不到他的存在。\n\n<race>，我知道我們之間毫無信賴可言，但是我仍然需要你的協助。\n\n要是你重視這個世界的聖潔，那就與我同行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41056] = {title = "愛已不在", objective = "在星歌避難所和泰蘭妲‧語風交談。", description = "瑪法里恩，我的愛…\n\n我看到他出現在幻象中，先是怒氣沖天隨即憂傷不已，而現在我的心靈已感應不到他的存在。\n\n他很強大，但降臨在這片土地的恐怖力量能吞噬一切。\n\n我必須找到他，而你必須助我一臂之力！\n\n提高警覺，<race>，跟我來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
