MultiLanguageQuestData['tw'][41146] = {title = "優雅設計", objective = "說服安娜絲特女士給你寶石切割寶典。", description = "業餘商人們只會抱怨供需，而大師們則是創造自己的供需。\n\n你拿回了我要求的最後兩塊元件。做得很好，但跟這件事比起來不過是無足輕重。\n\n你的目標是安娜絲特女士，而她有某件我非常重視的物品，精工寶石切割的設計圖。\n\n用任何手段從她身上拿到手，但要小心。她是話術的高手，會告訴你各種的謊言。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][41148] = {title = "散播愛心", objective = "為受苦的居民提供秘能酒。", description = "關於這座城市，你有很多要學習的地方。\n\n第一件事就是秘能酒。這是我們用來吸收夜井能量的飲品。沒有它，我們就會凋萎、死亡。\n\n宮殿的走狗向來吝於供應秘能酒，並將此視為控制我們的手段。我們只能保持溫順、沉默。\n\n我希望你去旅店附近找那些急需協助的人。你會看到許多人，不過那些深受配給制度所害的人一眼就能看出。\n\n帶著這瓶藥劑。救救他們，讓他們免於折磨。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][41149] = {title = "結界重啟效應", objective = "在琥珀谷啟動4個秘法結界。", description = "<這部採用夜裔優雅設計的小型裝置，因秘法能量產生細碎的爆裂聲。\n\n克達納茲的筆記提到一種將凋萎者隔離在外的結界。他似乎發現某種不會激起他們對魔法的無窮欲望的施法方式。\n\n這些或許能在你尋找失蹤的秘法師時派上用場。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用的秘法結界"}
MultiLanguageQuestData['tw'][41155] = {title = "黑騎兵", objective = "在卡拉贊地下墓穴擊敗黑騎兵並取得烏薩萊許。", description = "河邊有一個下水道出口，通往卡拉贊下面的墓穴。我過去不曾留意過，不過它很可能就是靈魂要我們去的地方。\n\n仔細一想，黑騎兵很可能一直躲在我們的眼皮底下！走吧，讓我們看看這條下水道通往哪裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41156] = {title = "據有力量", objective = "回達拉然的城底區找卡萊德斯。", description = "既然目標已經達成，該是我們分道揚鑣的時候了，術士。我很高興這是最後一次見到你。\n\n去吧，回去找你的黑暗主人。到此為止了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41157] = {title = "腐化研究", objective = "勘察斯鐸海姆的挖掘場，將200個先祖之戰碎片帶回去給布萊恩。", description = "斯鐸海姆到處都是先祖之戰所遺留下來的文物。正確來說應該是惡魔文物。\n\n我認為這些文物可以提供一些線索，讓我們進一步認識它們的領導者薩格拉斯。我已經找到一些泰坦圓盤的碎片，還需要找到剩下的碎片。\n\n你必須在斯鐸海姆東挖西挖，看看你能不能找到其他碎片，這樣我們就能重組圓盤。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n先祖之戰遺物"}
MultiLanguageQuestData['tw'][41158] = {title = "峽灣碎片", objective = "在斯鐸海姆與布萊恩‧銅鬚碰面。", description = "<name>，你有看到我放在這裡的帳本嗎？我去放臟器罈的時候，不知把它收到哪裡去了。\n\n喔，別介意。布萊恩‧銅鬚希望你去見他。他在斯鐸海姆繼續進行他的研究。\n\n動身去找布萊恩吧，告訴他我還在等他把那些剝皮日誌送來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41159] = {title = "排除法", objective = "在斯鐸海姆各地挖掘，直到找到一塊泰坦圓盤碎片。", description = "有太多地方都能挖出碎片，所以要正確找到更多泰坦圓盤的所在位置也變得越來越不容易。\n\n但是我已經想好應對措施。我需要你去排除圓盤可能存在的潛在區域，方便我們縮小在斯鐸海姆的搜索範圍。\n\n你負責一部分區域，然後我會負責其他區域。如果找到任何東西，就到這裡會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41160] = {title = "大地之力", objective = "幫露奈黎找到緋紅石之核心、 緋紅大地核心和緋紅熔岩核心。全都找到後帶回撒塔斯交給她。", description = "大地蘊藏力量，力量可以灌注到強大的武器之中。\n\n你看起來像是想知道怎麼製作這種武器的樣子。\n\n有些生物還在這個垂死的星球棲息，它們身上就有這種力量。把它們的核心帶回來給我，我就把你所尋求的知識傳授給你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設計圖：石鑄巨刃劍設計圖：大型地鑄戰錘設計圖：熔鑄戰錘"}
MultiLanguageQuestData['tw'][41161] = {title = "脫離苦海", objective = "到艾蘇納與布萊恩會合。", description = "喔，你好，<name>。我告訴你，自從我繼承了這家店，每天都頭痛不已。我好像永遠找不到我要的東西。\n\n這讓我想起一件事，布萊恩‧銅鬚希望你去見他。他在艾蘇納搜尋找那些…他正在追尋的東西。\n\n不知道我把那些白鑞酒杯放到哪裡去了…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41164] = {title = "更近一步", objective = "到蘇拉瑪爾與布萊恩會合。", description = "<name>！我剛聽說布萊恩‧銅鬚，那個著迷於泰坦的瘋狂矮人，決定到蘇拉瑪爾追尋他非常重視的圓盤。\n\n就目前的局勢而言，只有瘋了才會去那個地方挖東西。\n\n我很確定他會需要你的協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41167] = {title = "魔化碎片", objective = "將這箱勘察設備送到維爾薩拉，交給布萊恩。\n\n已提供物品：\n", description = "布萊恩‧銅鬚要我送更多勘察設備給他，不過我實在忙得沒時間。\n\n<name>，可以請你日行一善，把這箱東西交給他嗎？我會非常感謝你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41168] = {title = "《埃雷達斯的紫色山丘》", objective = "集齊《埃雷達斯的紫色山丘》的殘篇，組合成一本書。完成之後，將書交給布萊恩。", description = "現在我們又獲得補給了，終於可以回去工作了。\n\n我在這裡發現你一定會感興趣的東西，就是一張談論阿古斯世界的書頁。而且是還未遭到惡魔毒手的世界。\n\n不管怎樣，根據我的經驗，如果找到某個東西的一部分，那其他部分一定就在不遠處。\n\n繼續在維爾薩拉各地尋找更多書頁，把找到的東西帶回來給我。把我找到的書頁帶在身上，這樣你才會知道要尋找的目標。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41169] = {title = "暗心灌木林：穿過迷霧", objective = "取得《埃雷達斯的紫色山丘》的最後一章。", description = "真不敢相信，你找了這麼久，居然還缺了一章！\n\n我敢賭，一定是被那些薩特找到，給拿走了。也許是拿到一個沒人找得到的，黑漆漆的地方。\n\n我聽說有個叫做暗心灌木林的地方，最強大的薩特都在那裡。\n\n要是我猜得沒錯，我覺得你應該去那裡找找。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n《埃雷達斯的紫色山丘》"}
MultiLanguageQuestData['tw'][41170] = {title = "聖物再現", objective = "觀察布萊恩重組泰坦圓盤。", description = "好極了，好極了！現在我們已經集齊所有部分，該是還原這塊圓盤的時候了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n欺詐者印記遠古蘇拉瑪爾卷軸高嶺儀式石"}
MultiLanguageQuestData['tw'][41171] = {title = "聖匣守護者的召喚", objective = "到艾蘇納與泰瑟連‧血腥看守者會合。", description = "聖匣守護者泰瑟連要求我把能夠幫得上忙的人派到艾蘇納。\n\n既然你碰巧來到我的商店，或許你願意前往，<name>。\n\n不過記得要回來繼續為我工作。事情太多，幫手卻太少。\n\n<達莉諾絲嘆了一口氣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41172] = {title = "先祖回音", objective = "完成25個精靈貴族考古學項目。", description = "這片土地埋藏著許多秘密和古代文物。\n\n就我目前的判斷，這附近有一個力量非常強大的文物。我必須縮小搜尋範圍。\n\n我需要你挖出更多文物，並盡量研究它們。等你覺得自己有了足夠的成果，就回來找我，分享你的發現。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41173] = {title = "一線希望", objective = "前往泰瑟連在地圖上標記的位置，並進行勘察，直到找到文物為止。", description = "我已經把文物的位置標記在你的地圖上。文物就位在敵人出沒的地方，我希望你可以前往那裡，找回文物。\n\n找回文物後，把它帶回來給我，我會辨識文物的力量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n星光信標"}
MultiLanguageQuestData['tw'][41174] = {title = "這麼重也值得", objective = "到蘇拉瑪爾與泰瑟連會合。", description = "<name>，如果你是一箱黑色三葉蟲，你覺得我會把你放在哪裡？\n\n<達莉諾絲開始在店內東看西看。>\n\n喔，我想起一件事。泰瑟連要你去找他。他正在蘇拉瑪爾從事研究，需要你的幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41177] = {title = "哥布林考古學", objective = "到維爾薩拉與泰瑟連會合。", description = "我不確定你要不要加入，不過聖匣守護者已經委託哥布林協助他們發掘這片土地的文物。\n\n我希望你去一探究竟，調查這個傳聞的真實性…而且我也想知道結果如何。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41180] = {title = "不可說的力量", objective = "到蘇拉瑪爾與泰瑟連‧血腥看守者會合。", description = "<name>，我收到高階審查員發來的急訊，要求你去找他。\n\n他終於找到力量非常強大的東西，需要你協助取得那個東西。\n\n自己小心一點，<name>。只要是跟含有能量的文物有關，泰瑟連就會變得有點狂熱。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41181] = {title = "縮小範圍", objective = "勘察蘇拉瑪爾，發掘10個破舊的精靈貴族卷軸。", description = "我的看法是對的，夜裔精靈確實擁有力量強大的東西。我發現一段古代文字，提到這個東西稱為希拉克斯寶珠。\n\n就我所記得的先祖之戰文獻內容，希拉克斯是過去來到蘇拉瑪爾的惡魔領主，它把一個強大的文物交給當時的精靈，但他們得服從燃燒軍團作為回報。\n\n我還沒找到文物的切確位置，但也許做一些挖掘工作能幫我們找到答案。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41183] = {title = "學院式探勘", objective = "到艾蘇納與泰瑟連會合。", description = "<name>，很高興見到你。目前為止，你對我的商店有什麼感想？以單人經營來說，算是不錯了，對吧？\n\n順便一提，高階審查員泰瑟連一直在艾蘇納從事挖掘工作，要我通知你去找他。\n\n依我對他的了解，他大概又以為自己找到一件足以毀滅世界的重大文物了吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41186] = {title = "高嶺的歷史", objective = "到高嶺與蕾莎會合。", description = "我來看看，一…二…三…喔，你好，<name>。抱歉，我沒看到你進來。\n\n這簡直是一團亂，我真的需要一個助手。\n\n不過，我有事要拜託你，我有個考古學家同事叫蕾莎，一直想找人去高嶺幫她。\n\n我想你就是這個任務的最佳人選。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41189] = {title = "新線索", objective = "到高嶺與蕾莎會合。", description = "<name>，高嶺的蕾莎一直希望你去見她。\n\n她發現一條線索，而且顯然是與胡恩‧高嶺穿過的古代護甲套裝有關。\n\n有空的話，就去跟她碰個面。", progress = nil, completion = "這片土地所含的秘密遠超乎我的想像，&lt;name&gt;。仔細聽好…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41190] = {title = "水晶之眼", objective = "在高嶺與兩座不同的共鳴石互動。每座共鳴石需要3顆高嶺儀式石才能啟動。", description = "我已經探索過這裡的洞穴，發現了許多古代記載。\n\n其中最有趣的是卓格巴所居住的共鳴水晶。可惜的是，它們與這裡的牛頭人關係並不好，導致我的研究困難重重。\n\n我認為，你應該可以解決與卓格巴有關的任何衝突。\n\n我希望你繼續進行我的研究，調查任何跟胡恩有關的事。", progress = nil, completion = "&lt;蕾莎聽你述說你發現的故事。&gt;\n\n如果你說的是真的，意味著我一直在找的東西是胡恩戴過的項鍊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41192] = {title = "正確的道路", objective = "到高嶺與蕾莎會合。", description = "我想，這間新商店已經大致完工，不過，還是有很多地方有待改善。\n\n<name>，蕾莎要求你去高嶺找她，好像是跟麋鹿有關？\n\n我不太確定她的意思，不過你一旦有空，就盡快去找她。", progress = nil, completion = "&lt;name&gt;，我找到某個非常貼近胡恩的東西。\n\n我相信這塊骨頭是胡恩‧高嶺的動物同伴 - 艾切羅的骨頭！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41193] = {title = "安葬", objective = "找到600塊艾切羅的骸骨碎片，交給高嶺的蕾莎。然後觀察蕾莎所做的葬禮。", description = "如果我能在隨便一個地方找到骸骨碎片，就表示艾切羅的屍骨遍布在高嶺各地。\n\n我們必須找到牠的遺體，給予牠應有的隆重葬禮。\n\n喔，順便提醒一下，艾切羅是胡恩‧高嶺的坐騎和伙伴。\n\n牠應該獲得與胡恩相同的尊敬。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾切羅的靈魂"}
