MultiLanguageQuestData['tw'][41436] = {title = "深深沉眠", objective = "進入翡翠夢境，救回格哈尼爾。", description = "這張床可讓你陷入沉眠，接引你前往翡翠夢境。\n\n找個舒適的姿勢，然後喝下你帶來的月井水。我會在那裡導引你。\n\n快點行動吧，隨著時間一分一秒流逝，格哈尼爾的腐化程度也會逐漸加重。", progress = nil, completion = "潛入黑暗肆虐的翡翠夢境絕非易事，極少數&lt;class&gt;有勇氣一試，你這趟旅程恐怕困難重重。", rewards = "您會收到：\n\n"}
