MultiLanguageQuestData['tw'][41462] = {title = "長著大腳的麻煩", objective = "將怪異的雙頭巨人皮交給瑪卓尼爾‧林心。", description = "雙頭巨人的毛皮上有許多淺淺的抓痕及咬痕。看樣子他已經對當地的梟羽幼獸造成恐慌一陣子了。\n\n瑪卓尼爾‧林心會對這很有興趣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][41463] = {title = "中途失聯", objective = "找尋凱倫卓斯‧鐵林。", description = "我們從維爾薩拉撤退時，隊伍因為與邊界的薩特發生衝突而分散了。\n\n我們有其中一員沒有抵達這裡，就是密山卓斯的兄弟凱倫卓斯，我希望你能幫我把他找回來。\n\n請你搜索通往維爾薩拉那座橋樑前方的那片森林。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41464] = {title = "不是這裡，不是現在，不是永遠", objective = "使用薩特的角來摧毀3個暗魔圖騰。", description = "我無法、也不會、接受現在這裡發生的事。我的身體抗拒著我，但我會阻止這件事。\n\n<他看著你。>你會阻止這件事。\n\n這是被腐化的世界之樹夏達希爾的根。它不知為何從地底找到了這片無人到達的土地，而暗魔薩特已經開始腐化蘇拉瑪爾了。\n\n阻止他們。殺死薩特，奪取他們的角來刺穿圖騰。\n\n只有這樣我們才有希望扭轉一切。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n淨化薩特圖騰"}
MultiLanguageQuestData['tw'][41465] = {title = "高級珠寶：吹牛者的胸針", objective = "向奈特理斯‧春刃討回萊斯賓的胸針。", description = "業餘商人擔心劣質產品會讓他們丟臉。大師則擔心不好的客人會讓他們丟臉。\n\n以奈特理斯‧春刃的地位而言，他的行為逾越不少規矩，因此，在城市精英眼中屬於上不了檯面的人物。\n\n我把一枚胸針賣給了這個人，他把它別在斗蓬上。我一向只把飾品賣給地位高於我的客人。\n\n我的飾品從不會失去光澤，但是我的名譽卻非常容易受損。在他繼續降低我的格調之前，把我的作品討回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41466] = {title = "高級珠寶：高仿爪飾", objective = "向摩那斯討回萊斯賓的「藝術品」。", description = "業餘商人總是不斷回味過去的作品，拋不開過去的經驗。大師則能理解有捨才有得的真諦。\n\n數百年前…我愛慕虛榮，急於求成，卻反而親自體會何謂欲速則不達。\n\n找到他，把…它…帶回來。等到你看到它，就能理解我所說的一切。\n\n他住在這個庭院南邊的別墅附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n摩那斯的附魔雕像"}
MultiLanguageQuestData['tw'][41467] = {title = "唯一的解決途徑", objective = "焚燒夏達希爾樹根。", description = "拿著這火把，<name>。\n\n一旦夢魘腐化逐漸擴大，我們就無法扭轉它了。我們唯一希望能做到的就是摧毀它的實體。\n\n燒掉樹根。只有這樣我們才能在蘇拉瑪爾安穩生活。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][41468] = {title = "利爪之女", objective = "找到莉雅‧石爪。", description = "偉大的森林守護者厄索克在一萬年前，為了這個世界犧牲生命。厄索克死後，其爪子受到嚴加看管，以免有人濫用這股力量作惡。\n\n莉雅‧石爪和她的利爪德魯伊將厄索克視為典範，一生致力於追隨祂的腳步。要是有人知道厄索克之爪的所在之處，這人非莉雅莫屬。\n\n她和她的利爪德魯伊就住在北方的泰爾安杜獸穴。", progress = nil, completion = "厄索克之爪？\n\n我還以為在我有生之年，再也不會聽到這個名字了。目前的狀況真的這麼危急？這東西當初被封印起來是有原因的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41469] = {title = "回到鐵林居所", objective = "到鐵林居所尋找密山卓斯。", description = "我們從共存在這片土地上的生物獲得三個祝福。\n\n再加上來自伊露恩的祝福，月井在未來許多年，都會持續守護這片土地。\n\n到居所與密山卓斯會合。我很肯定，他希望你一起參加儀式。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][41473] = {title = "紅蹄長老", objective = "找尋密山卓斯與紅蹄長老。", description = "當你忙著協助河對面的梟羽幼獸，密山卓斯與索蓮德拉更往東邊前進。\n\n我相信密山卓斯可能找到下一個能提供我們祝福的生物了。\n\n河流往東北邊的蜿蜒處有一片僻靜的林間空地。在那裡，你可以找到我們的新盟友，一位名為紅蹄長老的年長雄鹿。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][41474] = {title = "灌溉未來", objective = "在肥沃土壤堆種下5顆萋草種子。", description = "如同大部分的草食性動物，我們的長角朋友們會吃下任何啃得動的綠色東西。\n\n然而我發現牠們特別喜歡找一些深色的草來吃。我相信如果我們能讓森林產出更多富含營養的雄鹿食物，就能開始贏得牠們的友誼了。\n\n我會提供你種子 - 你需要做的就是尋找適合的土壤並栽種它們。我們的魔法會完成剩下的步驟。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41475] = {title = "鹿角與狼牙", objective = "殺死8隻蘇拉瑪爾咆哮者及黯牙。", description = "現在，<name>，別誤會了 - 我是一名德魯伊。我了解大自然自有它的平衡。\n\n掠食者必須哺育，而其他將會被狩獵。我也了解對這樣的平衡亂來會有代價。\n\n這就是為什麼我行走於這片大地並…啊…計算一些東西。\n\n只要消滅一小部分你所找到的狼群，再加上一隻領頭狼。這樣應該能在不干擾平衡的前提上，減少牠們的數量好讓闇角們足以生存。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n晶化闇角鹿犄角"}
MultiLanguageQuestData['tw'][41478] = {title = "最後的祝福", objective = "和索蓮德拉‧羽降交談。", description = "我的朋友索蓮德拉‧羽降前去探索原生夜刃豹的棲息地了。\n\n我們已經擁有來自羽鬃和闇角的祝福了，也該是尋求夜刃豹祝福的時候了。她就在這片林地的北端。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][41479] = {title = "天敵", objective = "殺死8隻魔鱗石化蜥蜴。", description = "早在我們抵達這片土地的時候，我就來過這一帶了。石化蜥蜴在後來從東邊的峽谷遷移過來，侵占了夜刃豹的家園。\n\n我相信若要獲得牠們的祝福，就要清空這裡讓牠們有家可歸。\n\n殺死奪走這片土地的石化蜥蜴，<race>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41480] = {title = "魔納蜥", objective = "殺死石化蜥蜴之王魔納蜥。", description = "這裡有隻石化蜥蜴，吞下了太多夜刃豹的肉，飽到幾乎從不離開牠的洞穴。\n\n我們可以好好利用這一點。\n\n找出這隻叫做魔納蜥的石化蜥蜴，然後拿牠開刀，警告其他的石化蜥蜴。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n魔納蜥的石化眼球"}
