MultiLanguageQuestData['tw'][41606] = {title = "尋找布萊塔格", objective = "在蒼風灣找到布萊塔格。", description = "<凱爾幾乎無法言語。>\n\n那個納迦海巫…把同胞都交給海巨人了。\n\n布萊塔格是…最後一個活著的。\n\n快去找他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][41607] = {title = "漫步在宏園", objective = "找出漫步宏園裡的斥候。", description = "要對付他們的話，就必須更了解我們別離已久的同胞。\n\n我們已派出一名斥候潛入漫步宏園收集情報。哨兵軍團也派出了他們的斥候。希望她夠聰明，沒有在回報之前就被殺。\n\n他們已經有一陣子沒回報消息了，我們做好最壞的打算。\n\n找到他們，就能進一步了解目前的狀況。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
