MultiLanguageQuestData['tw'][41704] = {title = "受試者16號", objective = "將瑟倫帶給薩莉瑟拉。", description = "<瑟倫似乎仍受到秘法師法術的影響。在沒有克達納茲本人的情況下，活物可能有助於薩莉瑟拉揭露克達納茲的研究內容。>", progress = nil, completion = "克達納茲最後還是變成了怪物…\n\n他的命運實在不該如此。感謝你結束他的生命。", rewards = "您會收到：\n\n秘法師寶典"}
