MultiLanguageQuestData['tw'][41740] = {title = "科技上層樓", objective = "前往大漩渦，在艾澤拉斯之心與金礦先生交談。", description = "與元素溝通的方式有很多種。哥布林憑藉聰明才智，竟然有辦法在機械裝置上注入元素能量。我不懂他們怎麼辦到的，但在關鍵時刻，多些選項總是不錯。\n\n我們很幸運，有位「金礦先生」願意為我們效力，他的研究雖非正統，但可以大幅強化我們的力量。他就在附近等著。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][41741] = {title = "戰地部隊", objective = "使用偵察地圖，完成「戰地部隊」任務。", description = "該來測試一下新近召喚的次級元素能力如何了。察看偵察地圖，派遣你的勇士和部隊進行例行偵察任務。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
