MultiLanguageQuestData['tw'][41753] = {title = "勇士：裘貝卡‧破影者", objective = "我們必須改個碰面方式，<name>。你救我的次數已經多到數不清了。\n\n要是哪天你向人求救，我一定會還你這份情。", description = nil, progress = nil, completion = nil, rewards = nil}
