MultiLanguageQuestData['tw'][42125] = {title = "黑暗耳語", objective = "使用卡萊德斯的傳送門進入魔魂堡，並找回曼那瑞之顱。", description = "魔魂堡並不遠，但有重重保護。想大大方方地走進去非常困難，但是卡萊德斯可以幫你溜進去！\n\n我的族人設了一個用來運送財寶的傳送門，你可以從這道門進去找顱骨！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42126] = {title = "大法師歐妮雅拉", objective = "使用偵察地圖，完成「歐妮雅拉需要幫助」任務。", description = "我旁邊有張偵察地圖。你可以透過這張地圖指揮我們的盟友，執行破碎群島各地的重要工作。\n\n第一項任務非常重要。大法師歐妮雅拉是極有名望的召喚師，她在前往守護者殿堂的途中遭到攻擊。\n\n請派出大法師卡雷克去幫她一把。他是這項任務的最佳人選。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42127] = {title = "建立我們的部隊", objective = "和大法師歐妮雅拉說話，請她分享幾個水元素。", description = "大法師歐妮雅拉是一名強大的法師，她的本領可以幫上我們組織的大忙。\n\n她可以同時召喚好幾個水元素！而且幸運的是，她願意和我們分享知識。\n\n去和她談談，並且招募她的水元素。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42128] = {title = "儀式材料", objective = "在達拉然內尋找墓地細塵、一罐過熱的油、陳年雪李白蘭地和一份雄鹿血液樣本。", description = "曼那瑞之顱，噢，很棒的選擇！它非常強，擁有它的驚懼領主更強！\n\n但是它有個缺點，就是這個顱骨有自己的意志！如果我們能夠和顱骨溝通，或許有辦法說服它轉而為你效力！\n\n我們需要從漂浮城市找些材料，才能夠進行和它溝通的儀式。剛下葬墓地的灰塵、黑油和濃烈的酒精催化劑。\n\n噢，還要一點血！我知道有隻動物的血應該會很適合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42129] = {title = "星輝墜飾", objective = "從沿著維爾薩拉海岸移動的深淵女王莎蕾索身上，取得星輝墜飾。", description = "為了結束我在這裡的工作，我需要稱為星輝墜飾的魔法物品。\n\n數百年來，幻夢之林的大德魯伊將墜飾傳承給一代又一代的看守者。有一天，納迦海妖用計奪走墜飾。\n\n這個墜飾蘊藏了難以估計的秘法能量…足以用來治療這座森林。\n\n請取回墜飾，我會很感激你！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42131] = {title = "出乎意料的訪客", objective = "聽聽這些意外的訪客要說什麼。", description = "當心，<name>。我察覺到一股奇怪的能量正在房間中成形。有東西要以魔法投射進來了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n灰舌信標職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42132] = {title = "最後不代表最弱", objective = "招募『噬魂者』艾萊莉和捷斯‧暗織者成為你的勇士。", description = "我想你已經料到我準備要說的事了…早該讓艾萊莉和捷斯也加入勇士的陣容。\n\n他們兩人的規劃和準備對入侵尼斯卡拉一役功不可沒。他們的表現有目共睹，不是隨隨便便就能找到比他們更優秀的勇士。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42133] = {title = "單日送達", objective = "回神獵廳找艾瑪芮爾‧影衛。\n\n已提供物品：\n", description = "我已經將這些武器附魔，可以消除惡魔犬對魔法的天然抗性。除此之外，金屬應該可以在撞擊之下讓鱗片碎裂，提高我方盟友在對付惡魔時的傷害。\n\n雖然這種附魔不會隨著時間消失，但你應該盡快把這些武器送到需要它們的人手中。它們留在這裡越久，散發出來的能量就會吸引更多惡魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42134] = {title = "招募更多部隊", objective = "與招募員山普森交談。", description = "我們的勇士需要招募員山普森的才能，他是一名傑出的追蹤者。\n\n他對動物很有一套，輕輕鬆鬆就能馴服牠們。事實上，他已經開始把他追蹤和馴服到的動物帶進獸欄裡了。\n\n馬上去找他談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
