MultiLanguageQuestData['tw'][42213] = {title = "艾薩拉之眼：葛剛尼斯潮石", objective = "使用位於達拉然中央的傳送門，將葛剛尼斯潮石放在守護者之廳的肖像廳。", description = "<你已擊敗艾薩拉女王之怒，成功取得潮石。你應該前往達拉然底層，將它放到守護者之廳的肖像廳。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "硬殼巨腰帶明鱗護腰澀海之縛盤恨神諭者腰環您會收到：\n\n"}
MultiLanguageQuestData['tw'][42214] = {title = "為一枚戒環敲打", objective = "蒐集10個鹽目手鐲。", description = "正好你現在把注意力放在魚人身上…\n\n許多魚人都喜歡穿戴珠寶吸引配偶。我敢打賭他們有些珠寶正好讓我們派上用場。\n\n蒐集一些他們的珠寶，然後帶來給我。越濕黏越好！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42220] = {title = "遇難水手", objective = "幫10名女王復仇號的水手脫離苦難。", description = "<馬克拉納的吉爾布林以及龍蝦人從附近的沉船處抓走了無依無靠的水手。>\n\n<看來這些水手除了身中劇毒，還會有更糟的下場。還是讓他們從痛苦中解脫吧。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42222] = {title = "秘天學會報告", objective = "回到守護者殿堂。", description = "實在很難相信大法師瓦戈斯會和這種惡毒的團體有所牽連！他最好有個合理解釋，為何會來過此地…\n\n不管怎麼說，我們最好能先回守護者殿堂，把在這裡發現的事情告訴莫爾。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n水球職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42223] = {title = "偵察緋紅灌木林", objective = "在晨曦斷崖尋找莉爾芮雅‧曦風。", description = "如果你此行向東，我有一件事要請你幫忙。\n\n當我們拔營時，部份車隊先行離開，在城市四周偵察。莉爾芮雅‧曦風去太久了。\n\n如果你能幫忙查看她安全，我感激不盡。她說她是去探查晨曦斷崖的廢墟。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42224] = {title = "披上月影", objective = "探索月影聖所。", description = "我不清楚瑟倫找到什麼，但我知道他在哪裡找到它。\n\n就是西方的月影聖所。在菲阿多拉神殿之外。\n\n不管是改變瑟倫秘法精華的力量…或是讓克達納茲發明法術來安撫凋萎者的力量…源頭都在那裡。\n\n我就像是親自去過那裡一樣，所以我十分肯定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42225] = {title = "破除封印", objective = "破除海潮封印、大地封印和天空封印。", description = "<當你將聖物握在手中，薩莉瑟拉的聲音迴盪在你的腦海中。>\n\n你找到了！但上面的封印十分強大。\n\n搜索房間，尋找解除封印的方法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42226] = {title = "月影陣地", objective = "殺死一隻法多雷擲網者、法多雷喚巢蛛和法多雷奪命蛛。", description = "<干預聖物之後，似乎吸引了來自法拉納爾地底的可怕生物的注意。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42227] = {title = "深入裂隙", objective = "跟著谷行者費羅丁進入法拉納爾隧道。", description = "我保護這顆種子已經有一萬年了。你居然讓它落入法多雷手中。\n\n我本該讓你自生自滅。\n\n協助我奪回種子，償還你欠下的債。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n附魔的夜裔錢幣\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][42228] = {title = "隱秘之城", objective = "跟著歐菈希絲穿過法拉納爾隧道並殺死她。", description = "歐菈希絲低估了種子的力量。它正在蠶食她的力量，拖慢她的速度。\n\n我們必須抓住她，帶種子到安全的地方！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42229] = {title = "沙亞蘭", objective = "跟隨薩莉瑟拉，探索沙亞蘭。", description = "那個房間是完美的藏身處，現在守護者已經被解決了。\n\n跟我來。", progress = nil, completion = "像這樣暫時的家就非常理想。", rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][42230] = {title = "谷行者的負擔", objective = "在菲阿多拉神殿啟動菲阿多拉信標。", description = "種子正在覺醒。沒有力量，它很快就會枯萎死去。\n\n我們必須把種子帶離這裡，種在安全的地方。\n\n我不夠強壯，無法承受這個重擔。但你不一樣…你全身充滿力量。我能夠感覺到。\n\n請收下這顆種子。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n奧肯多爾之觸\n\n您還會收到：\n\n秘法種子箱"}
MultiLanguageQuestData['tw'][42231] = {title = "神秘的聖騎士", objective = "到達拉然與崔瓦交談。", description = "看來我們有個絕佳的機會。\n\n有一小群聖騎士前來宣稱自己知道提爾之墓的位置。他們說自己是提爾戰錘的看守者，不過那把古代武器狀況岌岌可危。\n\n我希望你去跟他們的首領崔瓦談談，進一步瞭解這把神器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
