MultiLanguageQuestData['tw'][42244] = {title = "女王復仇號的命運", objective = "將船長日誌帶給達拉然風行者聖堂裡的諫言者靜水。\n\n已提供物品：\n", description = "<這是值得分享的情報。或許達拉然的風行者聖堂裡有人知道如何運用這項資訊。>", progress = nil, completion = "&lt;諫言者往下看了你給她的物品，緊張地四處張望，對你擠出了一個誇張的微笑。她小聲地繼續說下去。&gt;\n\n你知道你拿的是什麼嗎？多虧你，這項敏感的情報才沒落入聯盟的髒手。\n\n我會親自確保這項情報被妥善存檔。", rewards = "皇家藥劑師披氅皇家藥劑師長袍柯爾克隆胸甲食人妖的輔助鎖甲裝飾亡靈哨兵上衣您會收到：\n\n提爾石板"}
MultiLanguageQuestData['tw'][42245] = {title = "DEPRECATED: Singed Note", objective = "將3瓶銀光油膏和1個野戰包送到地圖上標示的地點。抵達後，治療被魔化火焰灼傷的斥候。", description = "拜託，如果你看到這封信，請快點來救我。我在對抗燃燒軍團的時候，被嚴重燒傷。\n\n我在信裡附上一張簡要地圖，指出我與崩裂之殿的相對位置。\n\n請快點帶著補給品過來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42250] = {title = "DEPRECATED: Fevered Plea", objective = "將3個野戰包送到地圖上標示的地點。抵達後，治療發高燒的探險者。", description = "我再也撐不下去了。這個地方的高溫讓我產生幻覺。\n\n拜託，如果有人看到這則訊息，請去找我。看在聖光的份上，為我帶點藥來。\n\n我好像看到死亡之翼飛過來了…\n\n<最後一個字的墨水滴在紙條底部。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42268] = {title = "船難水手", objective = "救出10名女王復仇號的水手。", description = "<馬克拉納的吉爾布林以及龍蝦人從附近的沉船處抓了無依無靠的水手。>\n\n<水手們遭受慘無人道的虐待。看來救援行動是勢在必行了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
