MultiLanguageQuestData['tw'][42323] = {title = "DEPRECATED: Fevered Letter", objective = "將3個野戰包送到地圖上標示的地點。抵達後，治療發高燒的探險者。", description = "我被困在這座該死的山上，幾乎快凍死了，而且一定感冒了。\n\n在天寒地凍的環境中發燒，感覺真爽，不過，如果再拖下去，我恐怕看不到明天的太陽了。\n\n要是有人看到這張紙條，請帶些藥過來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42365] = {title = "集中能量", objective = "收集3份薩格拉斯之血。", description = "除了夢魘裂片外，我們還需要薩格拉斯之血，才能重新啟動艾恩裂隙的傳送門。\n\n這種稀有的施法材料可以從破碎群島取得。\n\n據傳各陣營的信使正在招募老練的冒險者，可能會提供這種材料作為報酬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42366] = {title = "惡魔越大，魔能越強", objective = "協助克托斯完成儀式。", description = "我受夠這些小事了，助手。該直接解決問題所在了。\n\n寶典就是關鍵！釋放我們人民潛能的關鍵。\n\n別擔心，年輕人。我有足夠的力量完成手上的任務。讓我們運用魔能，改變未來。\n\n跟我一同見證夏多雷的救贖！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n魔觸秘典"}
MultiLanguageQuestData['tw'][42367] = {title = "亞克薩拉斯", objective = "殺掉亞克薩拉斯。", description = "在魔炎入口中，有一隻惡魔必須得死。\n\n亞克薩拉斯是一隻狡詐邪惡的怪物。如果不解決他，他就會從魔炎入口發動突擊，瓦解我們的部隊。\n\n我認為這是絕對不能輕視的對手，一旦你準備好了，我們便一起上戰場殺掉這個惡魔。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n魔炎頸鍊攝入指環\n\n您還會收到：\n\n第二指揮徽記"}
MultiLanguageQuestData['tw'][42368] = {title = "重量不重質", objective = "消滅魔炎入口的惡魔。", description = "魔炎入口突然聚集了許多惡魔。\n\n我們必須在他們對伊利達瑞陣地發動攻擊前，把這些入侵者殺掉。\n\n你是否願意與我們一同奮戰？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42369] = {title = "欠修理的傳送門穩定裝置", objective = "放置4個被破壞的傳送門穩定裝置。", description = "這些惡魔傳送門的結構低劣，毫無技巧可言。\n\n這實在令我胃痛，而我已經數十年沒感到痛了。\n\n我「修好」了幾個燃燒軍團的傳送門穩定裝置。\n\n我要你帶著它們，「調整」在魔炎入口的主要傳送門，然後就等著看「好戲」了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42370] = {title = "第一次用魔杖就上手", objective = "練習使用魔杖擊中10個魔杖目標。", description = "我們先從魔杖開始。你的魔杖有帶著嗎？很好。\n\n我在大廳設置了幾個目標。用你的魔杖擊中越多目標越好。\n\n可別直接站在目標前面！那是作弊！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42371] = {title = "研究大廳：戰鬥研究", objective = "幫席松恩取得他想要的書，然後協助他克服其中的挑戰。", description = "這是什麼情況？一位搞不清楚狀況的新進學生，拚命想取悅院長，整天沒事在大廳閒晃？\n\n正好！我的研究需要人協助。\n\n我正在撰寫研究戰鬥的論文。幫我從那邊的書架拿點書來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42372] = {title = "魔炎入口", objective = "在魔炎入口與製鞋匠泰德碰面。", description = "監督伊利達瑞陣地的後方，是我的任務。我僱用這術士…之類的東西，來協助我。\n\n然而，我們兩人並無法勝任這重要的任務。\n\n在這裡東方的魔炎入口，聚集了大量的惡魔。這些生物已不斷開啟傳送門，召喚無數的惡魔援軍。\n\n在魔炎入口與我們碰面，只要同心協力，我們就能擊潰這群惡魔。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
