MultiLanguageQuestData['tw'][42375] = {title = "全視之眼", objective = "使用泰德的基爾羅格之眼，調查魔炎入口。", description = "盲目是一回事，愚蠢又是另一回事。\n\n我旁邊這位有眼無珠的奇葩想毫無準備就硬闖魔炎入口。\n\n哈！我認為我們應該先偵察一下比較好。\n\n來，我給你一只眼睛。別問我從哪拿來的。\n\n偵察魔炎入口，小心別傷到眼睛了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42377] = {title = "兄弟的足跡", objective = "前往北裂境的龍骨荒野，並找到加爾福特和提爾的火花。", description = "我們必須快點取得白銀之手，以免它落入有心人手裡。為了將它從結界中移出，我們需要稱為提爾的火花的聖物。我手中有一個，我的兄弟加爾福特也有一個。\n\n但他前往北裂境提爾的故鄉求救之後就失去音訊了。\n\n我想請你找出他和火花的下落。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42383] = {title = "奮起吧，勇士們", objective = "徵募風暴召喚者米爾拉和海達克西斯公爵。", description = "陶土議會奠基於成員的力量和無私奉獻。\n\n如果我們想擊退燃燒軍團，保護這個世界，就需要徵募能力出眾的勇士，讓陶土議會繼續成長、茁壯。\n\n去和風暴召喚者米爾拉和海達克西斯公爵談談，也許他們願意為我們戰鬥。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42384] = {title = "偵察報告", objective = "使用偵察地圖，完成「偵察報告」任務。", description = "在過去的日子裡，我們的組織已經花了許多時間觀察並等候。在你的領導之下，我們可以專注於我們原本的任務。\n\n看看我們周圍，<name>。艾澤拉斯比任何時候都需要我們。促成我們團結的同一個敵人，又再次威脅著我們。\n\n你應該派某人去收集斥候的報告。如此，我們可以將力量用在最急迫的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42385] = {title = "出手相救", objective = "到維爾薩拉尋找哈德森‧克勞福。", description = "我們的斥候回報，維爾薩拉有個村落受到不死獵犬的攻擊。\n\n這正是隱獵團出手的完美良機，證明我們信守承諾，協助有需要的人。\n\n你應該前往布瑞登溪，看你能提供什麼樣的援助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42386] = {title = "不死災禍", objective = "殺死布瑞登溪附近的復甦獵犬。", description = "我們的村落被不死野獸包圍了！\n\n這些怪物從不休息！從黑夜到白天都在攻擊我們。\n\n我們只能盡力擋下他們，但現在光靠村民已經無法撐下去。他們越來越累，也失去了戰鬥意志。\n\n不論是什麼事，只要能稍稍減輕重擔的話，我們都很感謝你的幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42387] = {title = "誘捕刺客", objective = "在卡萊爾小屋設下陷阱，以便抓住並殺死特瓦瑞斯隊長。", description = "就算已經沒有什麼可以掠取了，玄鴉堡的入侵者依舊不斷襲擊我們的農場和家園。\n\n我們只能期望他們在洗劫一空之後就會停止攻擊，不過看來這些無腦的不死怪物只會遵循對方指揮官下達的命令。\n\n我們得靠自己把他解決掉，但他是個十分狡滑的傢伙。我們如果打算抓住他，就是要派人去設陷阱。如果你願意協助，我可以提供補給。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42388] = {title = "緊急召喚", objective = "到神獵廳和艾瑪芮爾‧影衛交談。", description = "老鷹出現並帶了個訊息給你：\n\n\n\n我們的斥候已經回返並帶回來自全艾澤拉斯的報告。看來情況似乎比當初預料的還糟。\n\n請盡快回到神獵廳。\n\n-艾瑪芮爾‧影衛您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42389] = {title = "把希萊爾叫回來", objective = "在斯鐸海姆找到獸王希萊爾。", description = "現在那麼多人需要我們協助，也許該把一些斥候叫回來了。\n\n有位斥候名叫希萊爾。雖然她在很久之前離開她的氏族加入我們的組織，她還是常常回去保護她的族人。\n\n她保護族人的舉動值得敬佩，但這裡需要她。\n\n到斯鐸海姆尋找希萊爾，並讓她瞭解，該回來了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42390] = {title = "徵募雷克薩", objective = "到高嶺尋找雷克薩。", description = "想要發揮最強的力量，我們得讓最強的獵人加入我方。\n\n有你領導組織是個絕佳的起步，不過，如果我們打算大展身手，還需要更多高手協助。\n\n雷克薩名聲顯赫，是最偉大的獵人之一，只不過他一直沒有意願協助隱獵團。\n\n他的營地就在此地北方不遠處，和米莎一起在這塊土地上生活。或許你可以說服他加入我們的行列。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42391] = {title = "野獸咬噬", objective = "找出這場攻擊的罪魁禍「獸」，並將牠的頭帶給囚禁寇拉的法師。", description = "如果寇拉不能離開，我也不走。\n\n一群法師把她當做野獸關了起來，威脅要殺掉她。\n\n他們宣稱她得為了殺害他們的同伴負責，但我不相信這種事。寇拉是既忠誠又順從的同伴，沒有我的命令，她絕對不會攻擊別人。\n\n我追著那隻身為幕後黑手的惡魔來到這裡，跟它打了一架，卻還是讓它逃了。我身受重傷，無法繼續追過去，不過我能肯定那隻惡魔會留下一道血跡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42392] = {title = "夜晚求生", objective = "按照雷克薩的規則，在絕崖活過一個晚上。", description = "是時候實際考驗你的能力了。\n\n你的組織一直在觀察和等待，但卻少了相應的行動。\n\n證明我錯了。讓我看看，我和隱獵團是不是有什麼共通之處。\n\n如果你能在荒野中生存一晚，那我會考慮加入你們的組織。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42393] = {title = "重返家園", objective = "回到神獵廳和艾瑪芮爾‧影衛交談。", description = "寇拉已經冷靜下來了，可以飛回神獵廳。\n\n你可以告訴艾瑪芮爾，我們已經在回家的路上了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42394] = {title = "隱形防護", objective = "使用偵察地圖，派遣勇士和部隊完成「隱形防護」任務。", description = "我們不會讓達拉然城殞落的。\n\n如果燃燒軍團打算攻擊，隱獵團一定會出手阻止。\n\n我們的斥候在最近送來的報告中，列出了幾個迫切需要我們伸出援手的區域。\n\n當你準備好時，派你的獵人去解決這些威脅。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42395] = {title = "動亂通報", objective = "到南方瞭望塔和艾瑪芮爾會合。", description = "很久以前，我們把一些特殊的照明彈送給精心挑選的領導者，只有在最需要助力的時候才能使用。\n\n只要看到那種照明彈，隱獵團的領導者就應該前往最南方的瞭望塔，和發出照明彈的人會面。\n\n我不確定在抵達瞭望塔之後會見到誰，但我們得動作快。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n弓手命令職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42396] = {title = "快找！", objective = "????", description = "莫咕嚕！莫咕莫咕哇咕嚕。<菲恩雙手亂比>\n\n莫咕嚕咕嚕咕嘎嚕咕哇咕嚕。啊咕嚕莫咕莫嚕咕。咕嚕！咕莫嚕莫咕莫咕嚕…\n\n<菲恩看著你，眼神流露盼望之情。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][42397] = {title = "獵人與男爵", objective = "到斯鐸海姆尋找獵人布雷克。", description = "我們從卡德加那邊獲得一些消息，他和派去調查軍團營地的法師們失去聯絡了。他請我們提供協助，追查法師的下落。\n\n如果我們想要找出這些法師，我們就得找到一頭能夠追蹤氣息、可信任的獵犬。\n\n這樣的獵犬我只知道一頭，而且早就退休了。不過還是可以和他的主人，獵人布雷克談談，看看老男爵是否和他在一塊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42398] = {title = "喚醒嗅覺", objective = "挖出這個區域內的上古之骨，協助男爵喚醒嗅覺。", description = "恐怕老男爵已經不像全盛時期那麼風光了。他的鼻子無法像往日一樣追蹤氣息。其他人要我讓他安息，但我就是無法失去這位忠實朋友。\n\n不過，男爵在工作時一定全力以赴。如果你能帶著他到這些原野中挖出一些老骨頭，或許可以喚醒他的嗅覺。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42399] = {title = "準備上工", objective = "回到神獵廳和艾瑪芮爾‧影衛交談。", description = "如果男爵準備就緒，我隨時可以出發。\n\n只要我把營地打包並餵飽這條狗，就馬上前往獵人小屋。我很肯定他在這番挖掘之後將會胃口大開。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42400] = {title = "失蹤的法師", objective = "到蘇拉瑪爾與大法師卡德加會面。", description = "大法師已經啟程前往蘇拉瑪爾，那是失蹤法師最後所在的位置。\n\n男爵也已經出發了。看來那頭獵犬也急著重操舊業。\n\n在通往城市的路邊和他們會合。如果運氣夠好的話，男爵會聞出他們的魔法氣息，在一切太遲之前找回失蹤的法師。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42401] = {title = "魔法氣息", objective = "跟著男爵追查失蹤法師的氣息。", description = "這是失蹤的祈倫托成員最後出沒的地方。這裡沒留下什麼證據，只有一塊撕碎的布料，看來像是我們的外袍。\n\n或許這布料很小一塊，但應該帶有很濃厚的魔法氣息。我們只能期望男爵可以聞出這股氣息，追查出這位法師的下落。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42402] = {title = "要求增援", objective = "使用偵察地圖，完成「要求增援」任務。", description = "許多強大的團體都願意向隱獵團效忠。現在我們應該召集他們，協助我們擊敗哈卡爾和他的惡魔犬。\n\n派出你的勇士去見這些領導者，請他們助我們一臂之力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42403] = {title = "高嶺獵人", objective = "到高嶺尋找赫米特‧奈辛瓦里。", description = "我剛剛收到斥候的消息，他們已經找到可以招募的目標。\n\n聽說大名鼎鼎的赫米特‧奈辛瓦里在神獵廳附近設了一個營地。\n\n雖然他不是我們平時會徵募的那種獵人，但是他對大型目標的狩獵經驗可能很有用。\n\n前往他的休息處看看他是否願意協助我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42404] = {title = "協助大法師", objective = "回到神獵廳和艾瑪芮爾‧影衛交談。", description = "哈卡爾帶領著一大群以魔法為食的惡魔犬。只要他還留在艾澤拉斯，所有的法師都不安全。\n\n他和他的惡魔犬對大部分的魔法免疫，所以我需要幫忙才能殺掉他們。\n\n你已經證明自己的能力了，你願意出手解決這個惡魔嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42405] = {title = "通知我們的盟友", objective = "和大法師卡德加、赫杜倫‧亮翼、凡蕾莎‧風行者和珊蒂斯‧羽月交談。", description = "最強大的軍事陣營的領導者們都在這裡，準備萬全，並且願意協助我們。\n\n他們正等著和你直接對談，提供一些建議和如何幫助我們的措施。\n\n如果一切順利的話，我們應該可以集結資源，找出擊倒哈卡爾的方法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42406] = {title = "馴服野獸", objective = "在魔犬巢穴裡使用脈能蟲誘餌，引誘並抓住一頭惡魔幼犬。", description = "在法隆納中心的巢穴裡，到處都是惡魔犬的蹤跡。如果哈卡爾在繁殖這些野獸，他一定會挑選這個地方。\n\n我製造的誘餌味道很濃。你設置好了之後，會把附近的惡魔犬都引過來，離巢穴很近的時候才能使用。\n\n一旦惡魔犬吞了下去，就會進入虛弱狀態讓你更容易補捉。\n\n祝好運，<name>。希望你能完好無缺的回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42407] = {title = "野獸天性", objective = "回到神獵廳找艾瑪芮爾‧影衛。", description = "這種惡魔天生對魔法免疫，又因為配種而獲得對物理攻擊的抗性。它全身覆蓋層層交疊的厚實鱗片，簡直前所未見。我猜大部分的金屬都無法穿透那鎧甲般的厚皮。\n\n除非整支軍隊都配有跟你同等級的武器，否則我還是建議你先找出惡魔的弱點再對付它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n強效職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42408] = {title = "需要的材料", objective = "收集需要的製造材料。", description = "有一位才華洋溢且倍受哨兵信賴的附魔師，專門研究可以對付惡魔的附魔。\n\n她免費為哨兵服務，但需要特殊的材料才能施展附魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
