MultiLanguageQuestData['tw'][42423] = {title = "大法師瓦戈斯居所", objective = "調查大法師瓦戈斯的房間。", description = "<name>，大法師瓦戈斯消失好一陣子了，或許你可以到他位於城塞的住處看看。卡雷克會帶你過去。\n\n希望我們敬愛的同事只是像往常一樣行跡古怪罷了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42424] = {title = "跟隨他的腳步", objective = "請你的勇士去調查大法師瓦戈斯的行蹤。", description = "大法師瓦戈斯似乎參與了一些很危險的事，雖然以大法師的能力和經驗來說沒什麼好奇怪的！\n\n他可能前往幽暗地窖了，我們應該調查所有的線索，比較能瞭解他最近在做什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42425] = {title = "上上下下", objective = "使用歐仁的垂降點下降到裂縫中，取回他的物品。", description = "現在我們有了必要的蠕蟲內臟，我就能將它們做成特製的纜繩。\n\n這能讓你從橋上垂降至下方的裂縫，取回我被深岩一族偷走，丟進裂縫的物品。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42428] = {title = "亞夏曼神殿", objective = "與丹尼斯‧凝星者交談，然後前往亞夏曼之殞尋找迪藍卓斯‧閃月。", description = "強大的先祖亞夏曼在一萬年前對抗燃燒軍團的戰鬥中倒下。為了榮耀她的犧牲，虔誠的亞夏曼德魯伊將她的尖牙打造成強大的匕首。\n\n把我的璽戒帶給他們的領導者，迪藍卓斯‧閃月。這樣他就知道你帶著我的祝福。\n\n我們的飛行管理員，丹尼斯‧凝星者可以帶你前往神殿。", progress = nil, completion = "蘭薩讓你來的？雖然我想幫你，但無論你想幹嘛，都得先等等。如你所見，我們有更嚴重的問題。\n\n事實上，我們也很需要你的幫助。不如你先幫我們一把，然後我再幫你完成你來這裡的目的？\n\n你覺得如何？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42429] = {title = "黯凜的記憶", objective = "在達拉然尋找提里斯法議會的記憶。和其中一位交談以獲得其智慧。", description = "你手上那把，不會是黯凜吧？艾洛岱以前用的法杖？天啊天啊天啊…<咳咳>\n\n在第一任守護者的時代，所有提里斯法議會的成員將自己的力量匯聚於一位年輕法師身上，希望他能戰勝燃燒軍團。<氣喘聲>那些人都不在世上了…但你手中的法杖還記得這些事。\n\n你可以在達拉然的街上尋找前議會成員的記憶。這些記憶對你或許有幫助，就如同當年對艾洛岱一樣。把記憶找出來，並試著和其中一位交談！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鮮明記憶"}
MultiLanguageQuestData['tw'][42430] = {title = "亞夏曼之牙", objective = "搭乘黯牙，尋找亞夏曼之牙。", description = "我必須承認佛史托克是對的，神殿太容易成為燃燒軍團的目標。總之他現在不見了，亞夏曼之牙也被帶走了。\n\n我們必須找到他，才能把亞夏曼之牙拿回來。我應該要跟你一起去，但是我必須待在族人身邊，以免我們再次遭到襲擊。\n\n我的夥伴黯牙的嗅覺比誰都好，無論佛史托克躲在那裡，他都可以幫你找到。還有，拿著這個貝殼吧，這樣我們可以保持聯繫。\n\n願伊露恩指引你。", progress = nil, completion = "我從迪藍卓斯那裡聽說了，你不但救出亞夏曼&lt;class&gt;，還保住了神殿。\n\n我們對你的英勇事蹟由衷感謝，&lt;name&gt;。更別提你還找回亞夏曼之牙！\n\n不過，這場戰爭還沒結束。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42431] = {title = "尼索格的子嗣", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42432] = {title = "翡翠夢魘：翡翠夢魘", objective = "進入任何困難度的翡翠夢魘團隊副本，並打倒薩維斯領主。", description = "夢魘之王薩維斯仍然還活著。塞納留斯依舊身處危險，困在艾恩裂隙的深處。\n\n召喚你最強大的盟友，<name>。要直接面對恐怖的夢魘，我們一定得做好萬全的準備。\n\n等你準備好了，就進入翡翠夢魘，擊敗裏頭所有的恐懼事物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42433] = {title = "上古魔法", objective = "使用偵察地圖，完成「上古魔法」任務。", description = "如果想更瞭解古代的夜精靈，破碎群島就是關鍵，這裡肯定有無數個魔法文物藏在各式各樣的寶箱和地窖。我們得把它們找出來，別讓它們落到壞人手裡！\n\n或許你該派些勇士開始搜尋。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42434] = {title = "秘密行動", objective = "到艾蘇納與羅樊德威會合。", description = "你的勇士在艾蘇納發現，有強大的魔法從秘天學會發散出來。\n\n大法師瓦戈斯請我找莫爾來幫忙調查，但你應該知道，莫爾病得很重，沒辦法來這裡。你願意代替他嗎？\n\n你需要證明自己的能力，才能獲准進入。我們應該可以在艾蘇納的盤恨戰營找到一些有用的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42435] = {title = "準備被同化", objective = "取得秘法智慧寶珠和5個納薩拉斯卷軸，然後到秘天會所北邊與羅樊德威會合。", description = "秘天學會是危險的邪教，他們主張所有的魔法都一視同仁，值得研究，但實際上他們特別喜歡禁忌的法術。如果你送他們一件法力強大的物品，他們應該會歡迎你加入。\n\n盤恨納迦最近找到一樣東西，應該很合秘天學會的胃口：深藏於納薩拉斯學院的秘法智慧寶珠和卷軸。你必須說服盤恨納迦放棄這些寶物。\n\n我在秘天會所北方的路上等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42436] = {title = "協助我們的盟友", objective = "將補給品帶給梅拉雅‧灰羽。", description = "我們的天角部族盟友需要一些協助。\n\n他們處於鷹身人入侵的戰爭中，補給品所剩無幾。\n\n不管我們提供什麼東西，都可以幫上他們的忙，將這些女巫趕出他們的村落。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42438] = {title = "重生的希望", objective = "迪藍卓斯‧閃月請你搜索薄霧山谷的樹林，找回三顆泰爾安杜種子。", description = "<name>，亞夏曼之牙的處境很危險。在過去一萬年以來，有強大的結界避免亞夏曼之牙遭竊，但隨著時間過去，結界逐漸變得脆弱。而我最信任的三個亞夏曼德魯伊有泰爾安杜種子，可以執行儀式，重建結界。但現在樹林裡到處都是惡魔，我怕他們已經遭遇不測。\n\n無論如何都不能讓燃燒軍團取得亞夏曼之牙！我們得趁結界完全失效前拿到泰爾安杜種子！", progress = "拿到泰爾安杜種子了嗎？", completion = "謝謝你，&lt;name&gt;。\n\n我的心因為逝去的族人而感到悲傷。我發誓，燃燒軍團會為此付出代價！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42439] = {title = "救助亞夏曼德魯伊", objective = "擊倒4名埃雷達爾笞魂者，並救出他們的俘虜。", description = "抬頭看看，你就可以看見我們苦難的源頭。那些戰艦出現以後，我們就不斷地被襲擊。許多亞夏曼德魯伊淪為俘虜，直到現在我都能聽見他們遭受折磨的慘叫聲。\n\n求求你，盡你所能救出我的追隨者。他們的命運不該是落在燃燒軍團手裡。", progress = nil, completion = "&lt;迪藍卓斯點點頭。&gt;\n\n謝謝你，英雄。既然我的同胞安全了，也許我們還能扭轉戰局。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42440] = {title = "神殿危機", objective = "協助迪藍卓斯殺光剩下的侵略者。", description = "勇士，你幫了我們大忙，現在該說說為什麼來這裡了。\n\n<你告訴迪藍卓斯，大德魯伊巨蹄派你來找亞夏曼之牙。>\n\n唔…如果你一開始就這樣說，我大概會要你滾蛋吧。雖然亞夏曼之牙可是我們最珍視的寶藏，可是你今天為亞夏曼德魯伊作得太多了，而我是個信守承諾的人。\n\n好吧，我們殺光剩下的惡魔之後，就給你武器。", progress = nil, completion = "什麼？佛史托克把亞夏曼之牙帶走了？那個笨蛋，他會丟掉自己的小命！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42442] = {title = "戰鬥之夜：阿瑪麗亞", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][42444] = {title = "黑羽的災難", objective = "跟著受驚的熊鴉去找黑羽酋長。", description = "<熊鴉十分急迫地指著一個方向。\n\n似乎想要你跟著他。>", progress = nil, completion = "呱呱？\n\n&lt;熊鴉首領似乎忙著收集用於某種儀式的試劑。也許你可以幫他一下？&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42445] = {title = "尼索格的供品", objective = "到風裂丘陵收集8個完整的巨鹿角和16根完整如初的老鷹尾羽。", description = "熊鴉似乎在收集某種供品的材料，不過風暴飛龍一直在妨礙他們的工作。\n\n看起來他們需要從附近的巨鹿和老鷹身上分別取得完整的鹿角和修長的尾羽。\n\n幫他們收集剩下的材料應該不會花太多時間。", progress = "呱呱？", completion = "呱！呱！\n\n&lt;熊鴉首領看到你帶來的配方，興奮地拍動翅膀。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42446] = {title = "燒焦的羽毛", objective = "在風裂丘陵殺死8隻狂暴的獵風飛龍。", description = "呱呱！呱呱！\n\n<首領拍動翅膀，指著風暴飛龍攻擊熊鴉族人的地方。\n\n顯然他希望你幫忙解救族人。>", progress = nil, completion = "黑羽酋長向你低頭致謝。\n\n你保全了熊鴉一族的性命。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42447] = {title = "與熊鴉共舞", objective = "幫黑羽熊鴉完成獻祭儀式。", description = "<首領示意熊鴉收集供品，並指著外面的儀式法陣。>\n\n呱！呱呱呱！\n\n<他似乎想要你跟著他。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "符語者繫腰符誓束腰颶裔護腰懼誓巨腰帶黑羽裹手黑羽手套黑羽之握黑羽手甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][42449] = {title = "四騎士的回歸", objective = "到杜洛塔和薩沙理安交談。", description = "巫妖王的已經下達諭令，死亡領主，黯刃騎士團現在將聽你號令。\n\n四騎士可不是泛泛之輩，他們誕生自巫妖王親授給科爾蘇加德的純粹穢邪之力。\n\n而這股使死者復甦的穢邪力量現在就授予你了，死亡領主，我相信你會心悅誠服地收下這恩惠。\n\n四騎士將會是對抗燃燒軍團的強大盟友…而納茲格寧姆正是絕佳的首要人選。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42451] = {title = "卡雷克的計畫", objective = "到幽暗地窖附近的山脊上與卡雷苟斯會面。", description = "因為幽暗地窖附近都是燃燒軍團的勢力範圍，你的勇士沒辦法好好調查。希望你進去時，能找到更多關於大法師瓦戈斯的線索。\n\n卡雷苟斯會在魔魂堡附近的山脊上等你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42452] = {title = "尋找黯凜", objective = "在守護者殿堂調查遺落的雜物堆，看看有沒有關於阿雷希斯，黯凜最後一位持有者的線索。", description = "黯凜歷代的持有者都是法力高強的大法師，其製造者艾洛岱也不例外。艾洛岱將法杖託付給他最得意的學徒，然後再以相同的方式一代代傳承下去，直到…大法師阿雷希斯。\n\n阿雷希斯在第一次戰爭中消失了。我不知道他發生了什麼事，答案可能就在這個圖書館裡。\n\n先從這裡開始調查吧，應該會有些關於黯凜的線索。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42454] = {title = "卡茲格羅斯之錘", objective = "使用位於達拉然中央的傳送門，然後將卡茲格羅斯之錘放在艾格文的陳列室。", description = "<你已擊敗了地底之王達古爾，取得卡茲格羅斯之錘。你該將它放到達拉然下方的艾格文的陳列室。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "大地守衛裹手大地守衛纏手大地守衛手套大地守衛護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][42455] = {title = "艾洛岱的寶石", objective = "進入艾洛岱在達拉然的銀行保險庫，取得法力寶石。", description = "阿雷希斯為了完成儀式，帶了一整隊的學徒和法師部屬幫他，你可沒有這些人手。\n\n以前人們對魔法的瞭解還不夠，施展法術需要很多法力，當時我們會先把法力存在寶石，再用來施放複雜的法術。\n\n幸好我在保險庫還留有一些非常強大的法力寶石，此外還有些派得上用場的物品。跑一趟達拉然銀行吧，進入我的保險庫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
