MultiLanguageQuestData['tw'][42476] = {title = "逆風之處", objective = "在卡拉贊附近找到阿雷希斯的營地，看看有沒有關於儀式的資訊。", description = "你的研究指出，在卡拉贊附近有一個實驗地點。希望在那裡還留有我們可以用上的東西。\n\n你需要先找到那個地點，然後把所有能幫助儀式進行的物品帶回來。我會待在這裡繼續調查。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42477] = {title = "衰老的戴奧", objective = "飛往詛咒之地的腐化之痕，尋找有關衰老的戴奧的消息。", description = "文獻指出，有位叫戴奧的人是惡魔儀式的關鍵人物。該不會就是衰老的戴奧！\n\n我不知道他曾經是祈倫托的一員。我一直以為他只是個老術士，專門傳授惡魔法術給年輕人。這份文件可以解釋他為什麼換職業了。\n\n他應該握有關鍵資訊。雖然他已經退休，但我猜你可以在腐化之痕找到他。腐化之痕就在詛咒之地，去找他吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42479] = {title = "狩法獵人", objective = "在法隆納重現阿雷希斯的儀式，然後擊敗巴拉杜爾。", description = "有了那個，我們就能開始重建儀式…雖然儀式可能會有疏漏。我們必須在非常明顯的地方進行儀式，讓目標很快就能察覺我們的挑釁。\n\n根據我聽到的報告，燃燒軍團正在大力建設艾蘇納的法隆納地區。那是進行儀式的好地方，它們不會讓我們完成儀式。\n\n我們很有可能會慘死在那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42483] = {title = "將一切染紅", objective = "前往黃晶海灣，從鋼鱗身上取得鋼鱗的魚鰭。", description = "好了，我還有最後一隻野獸要請你解決。它的位置有點偏遠，不過相信我，這都是值得的。這隻我也下了重注！\n\n有一隻巨大的鯊魚沿著東海岸巡遊。當地人叫它鋼鱗。表示它的外皮幾乎牢不可破。\n\n不過，朋友，你會證明他們是錯的，對嗎？把它的魚鰭帶回來，然後那些牛頭人就必須心不甘情不願地掏出錢來。", progress = "嗯…", completion = "&lt;哥布林留下一張字條，附上一個老舊的放大鏡&gt;\n\n我真希望能夠親眼看到你的表情，不過拉茲和我還有更大的魚要釣！\n\n謝謝你送來的戰利品和肉食。我相信它們一定可以在黑市賣個好價錢，順便賣掉我們從那些愚蠢牛頭人身上偷走的貨物！我相信他們一定再也用不上了！\n\n後會無期，笨蛋！", rewards = "您會收到：\n\n鋼鱗的魚鰭拉克斯的放大鏡"}
MultiLanguageQuestData['tw'][42484] = {title = "大將再起", objective = "復生納茲格寧姆成為死亡騎士。", description = "納茲格寧姆將軍是我們世界中最強大的戰士之一，而且的忠誠無與倫比…就算他是個獸人。\n\n他有資格在死後安息，但是這個世界正哭喊著祈求生存。休息的時刻結束了…\n\n來吧，死亡領主…讓我們歡迎納茲格寧姆進入受詛咒者的懷抱。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42486] = {title = "迷路的小孩", objective = "護送可琳回到弦月旅店找她的母親薇玲。", description = "我現在想回家了，不過外面還有可怕的壞人…\n\n你會待在我身邊嗎？確定他們不會把我抓走？\n\n我不想再被關到籠裡…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n縛法珠寶盒"}
MultiLanguageQuestData['tw'][42487] = {title = "外頭的朋友", objective = "啟動傳送器，將凡席爾的禮物交給薩莉瑟拉。", description = "你在這裡幫了我們很多忙，不過你該回去找薩莉瑟拉了。\n\n附近有一個傳送器，已經棄置多年。看你能不能修好它，然後回去找她。\n\n對了，在你離開之前：\n\n<凡席爾將一瓶包好的秘能酒交給你。>\n\n把這個交給她，告訴她，我很感謝她把你派來。你幫我們補充了很多秘能酒，還讓一對母女得以團圓。\n\n真是感激不盡。有機會再見。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][42488] = {title = "薩莉瑟拉的居所", objective = "搜索薩莉瑟拉的住處，收集3塊增幅器碎片。將它們組合成秘法增幅器。", description = "正當你在城市中忙碌時，我的凋萎者研究遇到一個瓶頸。\n\n我覺得我已經快要克服這個瓶頸，但需要更先進的工具，才能解決問題。\n\n我有一個叫做秘法增幅器的東西。作用就像名字講的一樣。\n\n博學者非常可能已經下令搗毀我的住處。如果增幅器還在，應該也變成碎片了。\n\n可以的話，請將它恢復原狀。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n秘法增幅\n\n您還會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][42489] = {title = "薩莉瑟拉的抽屜", objective = "搜尋薩莉瑟拉的住所，取回她的物品。", description = "薩莉瑟拉的住處雖遭搜索，但仍然放有許多薩莉瑟拉的重要物品。把它們收集起來並帶回給她。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n深入挖掘 - 秘法師伯克蘭妮著"}
MultiLanguageQuestData['tw'][42490] = {title = "幽暗地道：開啟幽暗地道", objective = "在幽暗地道殺死諫言者凡卓斯。", description = "在蘇拉瑪爾地底深處，廢棄坑道交錯縱橫，人稱幽暗地道。自從一場災難導致那裡的法力收集器中斷運作後，坑道就遭到棄置。\n\n我不知道那裡面有什麼，不過可以肯定一件事。\n\n除了我們之外，還有很多人對那個地方感興趣。只要在那裡引起事端，與我一起向艾莉珊德效命的一名諫言者就會現身。\n\n他的名字是凡卓斯。有本事就殺死他。\n\n如果能除掉他，就能讓艾莉珊德失去一大助力，因此對我們是一場勝利。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n次元警覺寶典"}
MultiLanguageQuestData['tw'][42491] = {title = "幽暗地道：埋藏已久的資訊", objective = "從幽暗地道取得蘇拉瑪爾地脈地圖。", description = "在蘇拉瑪爾城底下，有許多交錯縱橫的通道，人們稱之為幽暗地道。\n\n由於部分山洞有崩塌的危險，因此不再有人進入地道。不過在那之後，誰知道呢？\n\n不管那裡現在有什麼，我相信你都能找到一些東西，用來確保我們之後的計畫能成功。\n\n很久以前，我的人民徹底探勘了蘇拉瑪爾境內和附近的地脈。成果應該就存放在地道的圖書館中。\n\n幫我找到那張地圖。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42493] = {title = "逼近的末末末末末日！", objective = "調查夜裔寶庫。", description = "米歐浩斯很會惹麻煩，所以如果他還在那邊，一定會去找大法師瓦戈斯。\n\n噢，還有如果你找到那些夜裔靈魂石，最好早點拿到手！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42494] = {title = "不只是個賣吃的", objective = "消滅15隻惡魔，並把你製作的魔法食品送給10位挨餓的囚犯。", description = "你的勇士消滅不少敵人。他們還找到一些挨餓的囚犯，需要協助。你的魔法法力布丁或甜餅應該可以幫他們恢復體力。\n\n同時別忘了，繼續把燃燒軍團的入侵者趕回扭曲虛空！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42501] = {title = "完成工作", objective = "前往詛咒之地，在風暴祭壇暗殺凱登‧凝影，然後檢查他的屍體尋找有用的情報。", description = "前陣子迦羅娜跑去暗殺燃燒軍團的邪教領袖，但我已經有段時間沒有她的消息了。\n\n更糟的是，她把弒君之刃帶走了。她很清楚那對匕首會對她造成負面的影響！\n\n你如果想找到迦羅娜，最好的辦法就是完成她原本在做的工作。我們的情報指向一位叫作凱登‧凝影的術士，他在詛咒之地的風暴祭壇幫新人上課。看看他身上有什麼有用的東西。\n\n當然，我的意思是先把他給宰了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42502] = {title = "無處可逃", objective = "前往暮色森林，在烏鴉嶺暗殺費爾考勒‧懷特利，然後檢查他的屍體尋找有用的線索。", description = "我們還有條線索，可能對你有幫助。有個人叫作費爾考勒‧懷特利，是邪教的核心成員。每當我們的人想接近他總是讓他溜了。\n\n最新的勘查報告顯示他現在在暮色森林烏鴉嶺的某個村落。他身上一定有重要情報。\n\n你知道該怎麼做了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42503] = {title = "解碼專家", objective = "使用邪教編碼器解讀加密訊息以得知邪教教徒的下一個聚集地點。", description = "<你獲得的訊息以強大的魔法加密，沒辦法用傳統的方法解密。>\n\n<你在費爾考勒‧懷特利身上找到的編碼器或許能幫你解密，讓你獲得關於迦羅娜以及邪教總部活動的情報。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42504] = {title = "無形之刃", objective = "幫助迦羅娜解決暴風城的帷幕之手教徒。", description = "我們不能讓暴風城被燃燒軍團擊潰。我不相信肖爾和那些軍情七處的笨蛋有辦法對付帷幕之手。\n\n我們兩人必須趁還有時間的時候，把這件事處理掉。\n\n現在整座城市都因為邪教活動而戰戰兢兢，如果你不夠謹慎，人們很可能把你視同教徒，轉而攻擊你。\n\n我知道其他的潛影成員對你的評價很高，你願意參與嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42506] = {title = "往昔聖典", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][42508] = {title = "龍可不好惹", objective = "與卡雷苟斯一起前往幽暗地窖。", description = "幽暗地窖已經從地面上消失好幾千年，因為燃燒軍團才得以重見天日。但我覺得有些地方還是繼續埋著比較好。\n\n我覺得我們就快追上大法師瓦戈斯了。他可能還在地窖中。如果想要攔截他，我們動作最好快一點。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42510] = {title = "不朽之魂", objective = "獻上鮮血祭品完成儀式，嘗試和伊利丹‧怒風的靈魂接觸。", description = "伊利丹不朽的惡魔靈魂失落於無邊無際的扭曲虛空。想和他連繫得冒著很大的風險，虛空中充斥著力量和胃口超乎我們想像的怪物。不過，如果我們要向前邁進，這一步非走不可。\n\n我們可以透過虛空法陣進行儀式。獻上鮮血祭品吧，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
