MultiLanguageQuestData['tw'][42512] = {title = "高嶺永存", objective = "擊敗達古爾。", description = "這樣應該可以了。達古爾來了，我們每一個能動的人都得上前線。去吧，我們會跟著你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42516] = {title = "力量漸增", objective = "到幻夢之林與大德魯伊蘭薩‧巨蹄交談。", description = "大德魯伊蘭薩‧巨蹄要你去找他。\n\n協防破碎群島的勇士正準備出發，我們需要你帶領他們。", progress = nil, completion = "很好。看來你的實力成長了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42517] = {title = "末日儀式", objective = "在懼痕裂隙的召喚平台進行末日儀式。", description = "你的研究讓你能夠進行非常強大的召喚儀式，如果你希望成功召喚惡魔，最好找幾個朋友來幫忙。\n\n儀式需要在上面的召喚平台進行。\n\n牢記一點，索取這種力量一向需要付出代價。並非所有參與召喚儀式的人都能存活下來，記得做好準備。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42519] = {title = "奮起吧，勇士們", objective = "招募艾瑪芮爾‧影衛和洛倫‧風暴之蹄。", description = "作為隱獵團的領導者，其他獵人都會尋求你的指引。很多人都會立誓效忠於你，為隱獵團貢獻一己之力。\n\n我知道我們之中有兩個人將你一直以來的努力都看在眼裡，因此也想要盡一份心力。\n\n請去找他們，讓他們為你分憂解勞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42520] = {title = "可怕的損失", objective = "回到守護者殿堂。", description = "我原本想說我對這個可怕的事情變化感到訝異，但是最近已經沒有什麼事可以讓我訝異了。在這個黑暗的時刻，就連我們最傑出的人也墮落了…\n\n我們最好把瓦戈斯背叛的事告訴大法師卡德加。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n提里斯護法護腕強效職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42521] = {title = "吾敵之敵…", objective = "找到米歐浩斯‧曼納斯頓。", description = "米歐浩斯‧曼納斯頓一直大吵大鬧，不斷聲明自己打算取得夜裔靈魂石。如果你能找到他，或許也能讓他為你所用。\n\n然而，他的行為往往出人意料，跟他在一起，絕對不能放鬆警惕，<name>。一旦你找到他，就用水晶聯絡我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42522] = {title = "伊利達瑞的領袖", objective = "前往樓上，正式繼任為伊利達瑞的新領袖。", description = "伊利丹正式號令你接掌一切，<name>。現在伊利達瑞歸你所管。\n\n到樓上和我碰面。我們要讓大家一起知道這件事情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42523] = {title = "接應蕾娜拉", objective = "使用偵察地圖，完成「蕾娜拉需要幫助」任務。", description = "現在我們已經徵募到了幾位勇士，我們可以運用偵察地圖來派人執行破碎群島上的重要任務。\n\n多年來，我們的斥候一直在注意有朝一日可能加入我們陣營的獵人。蕾娜拉就是這麼一位獵人。但是她在前往神獵廳的途中遭到了攻擊。\n\n建議派遣洛倫‧風暴之蹄去執行救援她的任務。他應該就是這個任務的最佳人選。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42524] = {title = "徵募部隊", objective = "與招募員蕾娜拉交談並訓練一隊弓箭手。", description = "招募員蕾娜拉是一位傑出的弓箭手，我們的勇士從她身上學到了不少技巧。\n\n她能夠命中遠方的微小目標，箭無虛發。\n\n現在去和她談談，訓練一隊弓箭手。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42525] = {title = "戰地部隊", objective = "使用偵察地圖，完成「戰地部隊」任務。", description = "該是把我們把受訓完的弓箭手派上戰場的時候了。看看偵察地圖並派遣你的勇士和部隊，踏上例行的偵察任務。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42526] = {title = "科技上層樓", objective = "到神獵廳和生存專家巴恩交談。", description = "我們真的很幸運，能夠遇到生存專家巴恩。他年輕的時候住在遙遠的潘達利亞大陸，靠著當地的動植物為生。\n\n他那利用有限資源無中生有的豐富經驗肯定能協助我們把神獵廳塑造成偉大的建築。\n\n現在去看他談談，看看他能幫我們做些什麼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42533] = {title = "荒廢的王國", objective = "到激流堡與加林‧托爾貝恩王子交談。", description = "這麼說，巫妖王已經公布四騎士的第二名成員…看來世界陷入危機時，就連國王也不得安寧。\n\n那就這樣吧，死亡領主。\n\n我會派納茲格寧姆和薩沙理安去淪陷的激流堡王國找你。\n\n加林‧托爾貝恩王子擁有他父親墳墓的鑰匙，裡面有一把名劍托卡拉爾。為了將那個國王復活成四騎士的第二名成員，我們必須想辦法進入墳墓。\n\n盡你所能說服加林協助我們…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42534] = {title = "我們最古老的敵人", objective = "收集15個枯木食人妖的腦袋。", description = "我會讓黯刃騎士進入我父親的墓地。但首先，我得請你幫個忙。\n\n我從父親手中繼承了這把劍和旌旗。我也將保護激流堡和原本市民視為我的任務。不過，還有一個工作尚未完成。\n\n枯木入侵者已經佔據了在城市原本的法師區，並架起封鎖線。在他們的邪惡之手中，我的手下損失慘重。\n\n殺光他們！把他們的腦袋帶來給我，我就把你要的東西交給你。\n\n這是激流堡之王許下的保證。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42535] = {title = "死亡…與腐朽", objective = "對10份枯木補給品使用荒疫。", description = "我的家族世世代代都在對抗枯木食人妖…他們在阿拉希出沒，就像是土地的詛咒一樣。我要把他們永遠趕出激流堡！\n\n摧毀他們的補給品，我們應該可以消滅他們重返此地的動機。對他們的補給品施放荒疫…用你們死亡騎士褻瀆事物的其他方法也可以。我不在乎。\n\n只要確保能達到目的就好！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42536] = {title = "王室之血", objective = "從加林‧托爾貝恩王子手中取得托爾卡拉。", description = "如果加林‧托爾貝恩以為他能夠背叛黯刃，那他就是個十足的蠢蛋。\n\n這一套我看膩了。家道中落的王子在浪費我們的時間，扮演著廢墟王座上的國王，讓英雄犧牲性命來拯救這個世界。\n\n要是加林‧托爾貝恩不打開他父親的墳墓，那我們就得拿走那把劍，自己動手。\n\n如果他想抵抗，那就這樣吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42537] = {title = "國王復甦", objective = "復生索拉斯‧托爾貝恩國王成為死亡騎士。", description = "索拉斯國王是世界知名的偉大戰士之一。\n\n他的人民愛戴他，而他的敵人畏懼他。他只說實話，經常說出其他人不敢講出口的事。\n\n索拉斯國王終其一生都在戰爭中渡過，他當然有資格在死後獲得平靜。但是，當一個人身邊的一切即將陷入煉獄，又怎能睡得平靜安詳。\n\n時候已到，死亡領主，該是歡迎最後一位貨真價實的激流堡國王，迎向死亡和詛咒懷抱的時候了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42539] = {title = "影襲", objective = "取得無辜者的頭骨和鮮血，然後前往夜色鎮除掉奧爾希雅‧埃伯洛克。", description = "<邪教徒似乎在夜色鎮建立了活動基地。目前已知奧爾希雅‧埃伯洛克是教徒，但是很可能所有的守夜人都有問題。>\n\n<現在最好的做法是拿到他們儀式需要用的材料，然後設法除掉奧爾希雅。迦羅娜的事情只好等等了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
