MultiLanguageQuestData['tw'][42567] = {title = "詛咒下的枯萎", objective = "找到進入脈能谷地的夜落精靈。", description = "所以瑟多努說他看到夜落精靈進入脈能谷地？\n\n我不喜歡這種事。\n\n祖父似乎還撐得住，大法師和我會看好他的。你去調查我們的洞穴吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42568] = {title = "備戰", objective = "在暴風城外找到迦羅娜‧半血。\n\n已提供物品：\n", description = "<奧爾希雅逃走了，那麼接下來就只剩一個地方要去：暴風城。>\n\n<如果迦羅娜追查邪教的進度和我相似，那她一定是在做進城的準備。>\n\n<務必在進城之前找到她。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42583] = {title = "奮起吧，勇士們", objective = "招募贊塔布拉以及納拉雷克斯。", description = "單靠自己擊退燃燒軍團是不可能的。\n\n如果我們想贏得這場戰爭，就必須像遠古時代一樣攜手合作。\n\n首先，我們需要招募更多德魯伊幫忙。找食人妖贊塔布拉以及夜精靈納拉雷克斯談談。\n\n他們兩位都是成就非凡的德魯伊，一定願意保衛幻夢之林。", progress = nil, completion = "很好，我跟贊塔布拉以及納拉雷克斯都很熟，他們一定會勇敢地為幻夢之林效力。", rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42584] = {title = "莉莉絲姊妹", objective = "使用偵察地圖，完成「莉莉絲姊妹」任務。", description = "大德魯伊，我們還需要更多盟友，才能真正發揮力量。莉莉絲姊妹正準備前往幻夢之林，她是個身懷絕技的林精，不過我們接獲消息說她可能遇到麻煩了。\n\n請派贊塔布拉去幫她一把。", progress = nil, completion = "好極了，&lt;name&gt;。贊塔布拉做得非常好。", rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42585] = {title = "徵募部隊", objective = "與莉莉絲姊妹說話，然後招募一些樹人。", description = "我們的勇士在任務途中遇到莉莉絲姊妹，她個性堅毅勇敢，領導著歡笑之女。\n\n她既是老練的戰士，又是嚴格的老師，深受林精尊敬。讓她負責招募一定能成績斐然。\n\n馬上去找她談談，然後招募一些樹人。", progress = nil, completion = "做得很好。我知道莉莉絲姊妹會幫上大忙。", rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42586] = {title = "林地防禦", objective = "使用偵察地圖，完成「林地防禦」任務。", description = "大德魯伊，有件事我們得特別留心：在維爾薩拉森林深處有一個叫作夏多雷恩的小型德魯伊哨站，正遭受薩特攻擊。\n\n立刻派出勇士解決這個威脅，<name>。我們不能放任薩特侵門踏戶！", progress = nil, completion = "這項任務成功了，而且我們的勇士還找到一片葉子，上面刻有古老的知識。或許可以拿到北方找知識古樹『傳說者』葉鬚看看，他應該會有興趣。", rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42588] = {title = "枝葉繁茂", objective = "前往維爾薩拉的幻夢之林和『傳說者』葉鬚說話。", description = "葉鬚又稱為『傳說者』是有原因的。\n\n傳聞他連大崩裂以前的事情都還記得。讓他看看勇士找到的葉子，也許可以獲得對幻夢之林有用的知識。\n\n去把東西拿給他吧。", progress = nil, completion = "做得好！看來葉鬚的建議派上用場了。", rewards = "您會收到：\n\n職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42590] = {title = "牧西的團聚", objective = "找到艾瑟‧智水，並讓她和家人在在雷霆圖騰的神錘育床團聚。", description = "你不知道我們有多感謝你，<race>。正因為有你，牧西和我丈夫才能平安。我再也不會讓他們離開我的視線了！\n\n很抱歉的是，我還要請你幫一個忙，你覺得有沒有可能找到我母親，並帶著她前來此地，讓她親眼看到她的孫子沒事了？\n\n她的名字叫艾瑟，住在雷霆圖騰北邊的峭壁那裡。", progress = nil, completion = "你的大恩大德沒齒難忘。我全家人都會把你當作朋友，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42593] = {title = "秘法之道", objective = "到達拉然的紫羅蘭城塞尋找大法師朗達拉克。", description = "要進入黑暗神廟可能有點麻煩。在黑穫議會闖入之後，阿卡瑪和他的撒塔牧師架起了一道神聖屏障。那東西擋住了我的傳送術。\n\n不過，我知道有個方法…或許…可以繞過那道防禦，讓我們直接抵達神廟頂層。\n\n很久以前，我和一位高等精靈有過…接觸。他名叫朗達拉克，後來他加入了祈倫托。\n\n如果你能有禮貌的請教他，並且提到我的名字，我敢保證他一定肯幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42594] = {title = "鬼鬼祟祟", objective = "追擊鬼鬼祟祟的小鬼，取回秘法之道魔典。", description = "很抱歉我用了立體投射影像…這幾天，我基本上必須同時出現在兩個地方。\n\n你是說，有道神聖屏障阻絕了惡魔魔法？我剛好有個東西可以繞過它來啟動懷惡族母的傳送法術。\n\n<高等精靈在他的背包中四下翻找，臉上旋即浮現出吃驚的表情。>\n\n鬼鬼祟祟的東西！那邊…那個小鬼剛剛拿著東西跑掉了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42596] = {title = "驅趕高嶺鹿", objective = "找到3頭受驚的高嶺鹿並將牠們送回麗薩‧風逐的獸欄中。", description = "陌生人！你就是我聽說的那位英雄嗎？\n\n當卓格巴引發了騷亂之後，有些年幼的鹿跑掉了！\n\n我不能自個兒去追，要不然其他的鹿可能也會亂跑。\n\n你能幫我把牠們帶回來嗎？", progress = nil, completion = "感謝你，高嶺的朋友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42597] = {title = "歐丁的召喚", objective = "到擎天堡與歐丁交談。", description = "主人，歐丁想立刻與你談談。\n\n因為你的實力持續成長，他相信你有資格直接指揮他的軍隊，並且可以開始準備了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42598] = {title = "擎天堡勇士", objective = "招募拉格瓦德‧龍裔與芬娜‧比昂多特。", description = "你即將成為世上最強軍隊的指揮官，但是你必須先證明你的領導能力，我的華爾拉亞才會徹底服從你。\n\n去找跟你一起上來的兩名維酷勇士，告訴他們，你即將承擔身為歐丁天選者的重責大任。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42601] = {title = "科技上層樓", objective = "在懼痕裂隙和古卷管理者梅琳達交談。", description = "我們真的很幸運，能夠遇到古卷管理者梅琳達。她相當特別，因為她的種族裡沒有多少人踏上我們這條路。而讓她更加獨特的地方，在於她對我們的技術抱著一絲不苟的態度。她的知識無比卓越。\n\n現在去和她談談，並詢求她的建議。有了她的協助，我們肯定能夠強化議會。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42602] = {title = "戰地部隊", objective = "使用懼痕作戰計畫，完成「訓練部隊」任務。", description = "該是把我們受訓完的小鬼派上戰場的時候了。查看懼痕作戰計畫並派遣你的勇士和部隊，踏上例行的偵察任務。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42603] = {title = "不計代價的消息", objective = "使用懼痕作戰計畫，完成「不計代價的消息」任務。", description = "既然你找到了其他術士願意協助你完成大業，我們可以運用懼痕作戰計畫來完成破碎群島上的重要任務。\n\n如果想要重建議會，我們必須先找回失蹤的成員。\n\n我們派瑞特辛和卡萊德斯去審問燃燒軍團的爪牙吧。說不定可以從它們身上找到線索，找回失蹤的議會成員。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42605] = {title = "勇士：拉格瓦德‧龍裔", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：拉格瓦德‧龍裔"}
MultiLanguageQuestData['tw'][42606] = {title = "勇士：芬娜‧比昂多特", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：芬娜‧比昂多特"}
MultiLanguageQuestData['tw'][42607] = {title = "史塔托姆隊長", objective = "使用歐丁之眼，完成「史塔托姆隊長」任務。", description = "當然，英靈殿的靈魂都很勇敢，這也是他們在這裡的原因。\n\n但是空有勇武沒辦法組成有效的軍隊。你還需要一個人來訓練這些華爾拉亞，教導他們戰鬥紀律。\n\n派你的勇士去找史塔托姆隊長。倨傲的維酷狂戰士或許不怕死，但是會害怕耶爾瑪‧史塔托姆，這樣他們才會聽從你的指揮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42608] = {title = "奮起吧，勇士們", objective = "招募卡萊德斯和瑞特辛‧焰慍。", description = "朋友很強，但是很孤單。雖然是議會首席，但議會裡的人都不見了。\n\n不過朋友不會一直孤單。朋友的力量會吸引其他人，服從朋友的領導。\n\n找出想幫忙的人，接受他們發誓效忠。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42609] = {title = "徵募部隊", objective = "和耶爾瑪‧史塔托姆隊長交談，並訓練華爾拉亞志士。", description = "史塔托姆隊長來了。我建議你最好和他談談，確保華爾拉亞的裝備齊全，隨時可以上戰場。\n\n如果我們想和燃燒軍團全面開戰，只有兩名勇士是不夠的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42610] = {title = "戰地部隊", objective = "使用歐丁之眼，完成「戰地部隊」任務。", description = "我們放任敵人為非作歹太久了。現在我們總算有軍隊能援助你的勇士，你應該派他們去解決敵人了。\n\n我們有個人被歐丁的宿敵黑爾雅俘虜了。如果你的部隊能夠平安救回『符文使』埃納爾，他可以協助我們使用強大的符文，進一步提升部隊的實力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42611] = {title = "『符文使』埃納爾", objective = "和『符文使』埃納爾說話。", description = "領導者的職責不是只有派士兵上戰場。你也必須決定如何訓練和強化我們的軍隊。\n\n找『符文使』埃納爾談談，告訴他你想如何培訓部隊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n職業大廳的榮耀大廳資源"}
