MultiLanguageQuestData['tw'][42663] = {title = "奮起吧，勇士們", objective = "徵募大法師卡雷克和大法師莫德菈。", description = "提里斯護法廢止很久了。為了擊敗燃燒軍團，我們必須徵募最厲害的法師與我們併肩作戰。大法師卡雷克和大法師莫德菈就是這樣的人選，他們很樂意助我們一臂之力。\n\n去找他們談談，請他們伸出援手。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42664] = {title = "勇士：暗影阿卡瑪", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n勇士：暗影阿卡瑪"}
MultiLanguageQuestData['tw'][42665] = {title = "加入我方", objective = "招募暗影阿卡瑪和珂娃絲‧血棘成為你的勇士。", description = "我們應該要盛大歡迎暗影阿卡瑪加入我們。讓大家看到我們對他一視同仁，不再當成外人是十分重要的事。\n\n珂娃絲‧血棘一次又一次證明她的重要性。她在戰鬥方面的技巧無庸置疑、無人能比。想要消滅敵人，你找不到比她更出色的勇士。\n\n將他們正式升為勇士的時候到了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42666] = {title = "回到魔錘號", objective = "到魔錘號與戰鬥領主蓋爾道恩交談。", description = "<name>，戰鬥領主蓋爾道恩叫我請你過去一趟。他說有一件非常重要的事，需要你助他一臂之力。\n\n他請你一回到魔錘號，就立刻去見他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42669] = {title = "攻擊準備", objective = "使用偵察地圖，完成「攻擊準備」任務。", description = "我們有薩格萊特鑰石。我們有需要的大部分力量。我們甚至還有完善的計畫。\n\n我們現在必須找到魔魂，瓦解他們從躲藏的惡魔世界發動的入侵行動。\n\n請把這件事交給我。如果你讓我擁有指揮勇士的權力，我和奪魂鐮會無所不用其極，從訊問的惡魔身上挖出所需的情報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42670] = {title = "奮起吧，勇士們", objective = "招募『受難者』奧翠司和雅夏‧鴉曲作為你的第一批勇士。", description = "懷惡族母、絲瑟諾女士和我一直在觀察你和其他伊利達瑞。旁觀者清，我們身為外來者，或許看事情的角度反而更為客觀。我們已經取得一致意見：為了防止伊利達瑞變得四分五裂，你必須開始徵募勇士。\n\n這些傑出的少數菁英將有助於你將勢力擴展到魔錘號以外的地方。\n\n我們一致推薦的兩位首選就是奧翠司和雅夏。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42671] = {title = "奮起吧，勇士們", objective = "招募凱恩‧日怒和雅夏‧鴉曲作為你的第一批勇士。", description = "懷惡族母、絲瑟諾女士和我一直在觀察你和其他伊利達瑞。旁觀者清，我們身為外來者，或許看事情的角度反而更為客觀。我們已經取得一致意見：為了防止伊利達瑞變得四分五裂，你必須開始徵募勇士。\n\n這些傑出的少數菁英將有助於你將勢力擴展到魔錘號以外的地方。\n\n我們一致推薦的兩位首選就是凱恩和雅夏。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42673] = {title = "勇士：珂娃絲‧血棘", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n勇士：珂娃絲‧血棘"}
MultiLanguageQuestData['tw'][42677] = {title = "蓋爾道恩需要的東西", objective = "使用偵察地圖，完成「蓋爾道恩需要的東西」任務。", description = "戰鬥領主蓋爾道恩願意協助我們招募更多的破碎者，一同對抗燃燒軍團。但是他得先拿到幾樣東西，什麼正確的工具之類的。\n\n你新招募的勇士正好可以派上用場。我相信這個任務一定很有挑戰性。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42678] = {title = "玄鴉堡：進入玄鴉堡", objective = "集結一個隊伍，進入玄鴉堡從丹塔利翁斯身上取得鴉眼", description = "這東西十分古老。光是翻頁都可能讓它在我手中解體。\n\n看這裡，我找到了。這裡記載著有關鴉眼的事。\n\n<瓦麗拉的手指由左至右劃過頁面。臉上露出有所發現的表情，但隨即皺起眉頭。>\n\n這裡寫說，最後一個擁有鴉眼的是黑羽堡主本人。你必須進入玄鴉堡，從他手中取得鴉眼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42679] = {title = "破碎者", objective = "和戰鬥領主蓋爾道恩交談，訓練灰舌部隊。", description = "增加人數對我們來說十分重要。相信我，我很清楚這些事情。想要快速完成這一類的任務，最好的方式就是請戰鬥領主蓋爾道恩和他的灰舌戰士出馬。\n\n你應該和他談談，讓他瞭解你需要什麼樣的破碎者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42680] = {title = "解讀密函", objective = "使用鴉眼破譯軍情七處加密信件。", description = "我們拿到鴉眼了。<name>，快用它破譯軍情七處的信件。\n\n我們必須知道其中的內容！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n無冕者腕環強效職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42681] = {title = "洛拉姆斯，是你嗎？", objective = "使用偵察地圖，完成「洛拉姆斯，是你嗎？」任務。", description = "貝拉斯‧曦刃從魔炎入口送來的偵察報告很奇怪。驚懼領主『污染者』拉瑟萊克回到這個世界了。不過，這不是奇怪的地方。\n\n怪的是他有時會殺死其他惡魔，並自稱洛拉姆斯！\n\n就我們所知，當年是有位叫作洛拉姆斯‧薩里比迪斯的惡魔獵人。洛拉姆斯為了擊敗拉瑟萊克，決定犧牲自己，被拉瑟萊克附身。\n\n請派你的勇士和灰舌戰士前往艾蘇納，查明事實真相。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42682] = {title = "額外配備", objective = "使用偵察地圖，完成「額外配備」任務。", description = "我聽到一些傳言，說你打算和長存於扭曲虛空中、伊利丹不滅的惡魔靈魂接觸。倘若如此，你會需要許多魔法道具。\n\n我花了點精神，幫你把可能用到的物品列了一份清單。我希望這可以幫上你的忙，<帥哥/美女>。", progress = nil, completion = "我們真的非得收集齊全這些材料，才能連繫上主人的靈魂嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42683] = {title = "改魔歸正", objective = "聆聽洛拉姆斯‧薩里比迪斯的故事，然後升級你的職業大廳。", description = "讓洛拉姆斯重返陣線能讓我們如虎添翼，只不過他依舊困在拉瑟萊克的體內…而且，惡魔有時會掌控那具身體。\n\n不過，他仍然是我們最強大的惡魔獵人。現在，他也摸清了驚懼領主究竟想要做什麼。\n\n我認為，要是他能和我們一塊共享這些知識和智慧，必定能大大提高這場戰爭的勝機。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][42684] = {title = "誤導軍情七處", objective = "使用偵察地圖，完成「誤導軍情七處」任務。", description = "軍情七處緊咬著我們的行動不放。我們得小心別被他們抓到我們的小辮子。\n\n我建議你用一些任務干擾敵人的耳目。派出你的勇士，指派你的部隊，實際內容我一點也不在乎。重點在於，讓他們遠離維爾薩拉，遠離玄鴉堡。\n\n至少等到我們可以解讀那封該死的信為止。", progress = nil, completion = "想不到行動如此順利。根據我們眼線報告，已經成功轉移他們的注意力。\n\n除此之外，有個我覺得或許可以用來解讀軍情七處信件的特殊物品，在斯鐸海姆被找到了。", rewards = "您會收到：\n\n"}
