MultiLanguageQuestData['tw'][42687] = {title = "戰地部隊", objective = "完成「戰地部隊」任務。", description = "我們的部隊準備好了！讓我們到戰場上驗證他們的實力吧。\n\n我們接獲情報，破碎海岸附近還有倖存者，但那裡是燃燒軍團的勢力範圍。\n\n快點派出部隊協助救援！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][42688] = {title = "愛意莫戈", objective = "????", description = "莫啊莫咕！莫咕哩咕啊莫咕莫咕！莫咕哩莫…\n\n<菲恩讓你觀看珠寶側邊的一道瑕疵。>\n\n莫莫哩咕莫啊莫咕啊莫咕莫莫咕哩。莫哩咕莫啊莫哩？莫咕哩莫咕！\n\n咕莫哩咕莫莫哩莫咕哩咕莫哩咕哩莫哩咕莫咕莫。\n\n<菲恩做出一個鑷型手勢。>\n\n咕莫哩咕莫哩咕？莫咕哩莫咕哩莫咕莫咕哩咕哩。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔莫戈莫戈愛意"}
MultiLanguageQuestData['tw'][42689] = {title = "瞭解我們的敵人", objective = "在艾蘇納與琪拉‧怒魂交談。", description = "如果我們想在對抗哈卡爾時佔上風，就得研究他所飼養的獵犬，找出它們的弱點。\n\n我知道有一個術士對惡魔的研究很廣泛。或許她看過這種獵犬，知道如何打倒它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
