MultiLanguageQuestData['tw'][42739] = {title = "毀滅符文：符文賢者弗洛基", objective = "取得弗洛基的符文。", description = "<用來困住瑪莉斯‧暗影的符石。只有對它使用符文賢者弗洛基的符文才能摧毀。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42740] = {title = "破碎海岸之戰", objective = "帶第三艦隊前往破碎海岸。", description = "這是你的船，<name>。是艘好船，經歷過許多戰役。準備好出發，就跟船長說一聲。\n\n祝你一路順風。我們對破碎海岸的情況知道得不多，但我猜瓦里安國王已經掌握戰局了。", progress = nil, completion = nil, rewards = "暴風城先鋒裂斧暴風城先鋒戰斧暴風城先鋒法師之刃暴風城先鋒護杖暴風城先鋒戰錘暴風城先鋒速刃暴風城先鋒矛戟暴風城先鋒匕首暴風城先鋒長弓暴風城先鋒磨骨錘"}
