MultiLanguageQuestData['tw'][42747] = {title = "梟獸所在之處", objective = "在逝光岩洞殺死10隻梟獸和8隻蠕動的骸泥怪。", description = "梟獸經常負責看守伊露恩的重要禁地。如果伊露恩對牠們的影響被削弱或中斷，牠們可能會變得非常危險。\n\n很遺憾，我們必須解決這些梟獸。最近出現在維爾薩拉的干擾使得這些生物陷入瘋狂。\n\n一旦有一隻失控，就只有一個解決辦法。\n\n我無法親手殺害伊露恩的造物，不過我知道這件事不得不做。", progress = nil, completion = "我真的不希望走到這一步。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42748] = {title = "翡翠姐妹", objective = "在逝光岩洞拯救6個月光之女。", description = "這裡的梟獸已經失去與伊露恩的連結。\n\n一群林精闖入牠們的地盤，發掘事情的真相，卻無人平安歸來。\n\n我有非常不好的預感，她們一定急需救援。\n\n正當我試著拯救梟獸的時候，能不能拜託你前往岩洞，救出你路上碰到的姐妹。", progress = nil, completion = "梟獸在…熔化林精，用他們的骨頭製造爪牙！怎…怎麼可能發生這種事？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42749] = {title = "奇怪的枕邊人", objective = "到英靈之門的橋上和瑪莉斯‧暗影會合並殺死洛克亞柏。", description = "我來到此地的原因，是想要抓住或是殺掉一個名叫洛克亞柏的惡魔領主。不過，我現在沒心情活捉他了。\n\n我會拿起武器，前往英靈之門前的橋樑。那個地方到處都是數量驚人的怒魔維酷人和惡魔。\n\n不過，你以為我是怎麼被抓的？\n\n所以我寧可不要回到那裡。不過，我想我知道一個方法，可以讓那頭惡魔來找我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42750] = {title = "攝夢符", objective = "在逝光岩洞用梟獸圖騰為攝夢符充能。", description = "我撐不了太久…\n\n我把攝夢符帶來了。我用它來竊取梟獸圖騰的魔法。\n\n要破壞困住守衛者雷姆洛斯的屏障，這是唯一的方式。\n\n請代替我繼續撐下去。", progress = nil, completion = "我認識蕾菈娜…她曾經是最受雷姆洛斯寵愛的人，非常善良。如果如她所說，雷姆洛斯已經被抓了，我們就沒時間哀悼她的死亡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42751] = {title = "月之劫奪者", objective = "在幽暗峽谷擊敗骨流，然後救出守衛者雷姆洛斯。", description = "我們立刻啟程！如果守衛者雷姆洛斯陷入危機，我們必須保護他。\n\n透過攝夢符，我們應該能夠進入梟獸骨流的巢穴。\n\n我們必須擊敗牠，才能救出守衛者雷姆洛斯！", progress = nil, completion = "我傷得很重，魔力也所剩無幾。我必須盡快恢復體力和魔力，回到幻夢之林。\n\n以凡人的能力，已經救不了這裡的梟獸了，也許有一天伊露恩的光芒會再次灑落在牠們身上。\n\n謝謝你，&lt;name&gt;。願你一路平安。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42752] = {title = "看守者鐵獄：入侵鐵獄", objective = "取回薩格萊特鑰石。", description = "<剩下的問題就是前往艾蘇納西南方的看守者之島了。你在那邊需要一路打進看守者鐵獄，深入到最底層，回到你原本被囚禁的地方。>\n\n<在那個名為背叛者牢獄的地方，也就是看守者原本放置伊利丹屍體的所在處，你可以找到薩格萊特鑰石。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42753] = {title = "看守者鐵獄：入侵鐵獄", objective = "取回薩格萊特鑰石。", description = "看守者信守了他們的承諾。剩下的問題就是前往艾蘇納西南方的看守者之島了。你在那邊需要一路打進看守者鐵獄，深入到最底層，回到我們原本被囚禁的地方。\n\n在那個名為背叛者牢獄的地方，也就是看守者原本放置主人屍體的所在處，你可以找到薩格萊特鑰石。\n\n祝你好運，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42754] = {title = "躍傳功能", objective = "收集魔化引擎燃料噴嘴、靈魂設定矩陣、魔化引擎點火器，以及邪惡靈魂轉換器。", description = "雖然魔錘號已經獲得了充沛的動力，可惜的是躍傳引擎還是無法運作。要入侵惡魔世界，我們就得啟動指揮中心的空間躍傳功能。\n\n我們需要更換一些零件。\n\n還好，我們的運氣不錯。燃燒軍團帶了幾座指揮中心和靈魂引擎，一塊抵達破碎群島。你可以在艾蘇納找的法隆納，還有蘇拉瑪爾的魔魂堡找到它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42756] = {title = "飢渴末路", objective = "殺死艾爾伊斯和他的傀儡。", description = "我很虛弱。飢餓可以毀滅一切，朋友。我現在知道為什麼你的龍會在這些池子裡休息了。\n\n<咳咳>\n\n我是來警告你的，但…看來已經太遲了。\n\n我聽到他就在外面。艾爾伊斯…已經…來了…您會收到：\n\n", progress = nil, completion = nil, rewards = "祝福過的洛席恩之石永恆傀儡核心蒼翼之血腐化的地脈水晶蔚藍烈焰脈能谷地之霜賽諾苟斯的決心活力灌注水晶賽諾苟斯的絕望藍翼的奸詐伊露恩的淚珠發散的脈能水晶地脈注入之血魔觸法力寶石斯黛拉茍莎之怒賽諾苟斯之息強固遠古龍鱗水晶化的龍蛋卑下的汲取精華憂鬱之風秘能蒼藍法杖您會收到：\n\n賽諾苟斯的恩澤"}
MultiLanguageQuestData['tw'][42757] = {title = "靈魂之喉：海洋威脅", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][42758] = {title = "你需要一艘大一點的船！", objective = "拔回33枚尖利鯊齒。", description = "鯊魚。對我們海盜來說，它們是最大的威脅。嗯…至少僅次於壞血病、搶戰利品和司法制度。幸運的是，我們今天處理鯊魚的問題就好。\n\n從它們的醜臉上拔些牙齒，帶回來給我。我需要一條新項鍊！", progress = "我要的是三十三枚尖利鯊齒。少一枚都不行，小子。", completion = "哎呀！這一枚還沾著血！看來他狠狠的咬了你一口吶，小子！", rewards = "您會收到：\n\n緊急用海盜裝扮龍石"}
MultiLanguageQuestData['tw'][42762] = {title = "漫行者之伴", objective = "與塔克塔克交談後飛往天僧寺，然後和美猴王見面。", description = "福山之杖…明智的選擇。如果傳說是真的，它的力量對我們而言不可或缺。\n\n我們認為美猴王持有的法杖可能就是傳說中的福山之杖，但美猴王和法杖已經失蹤超過一年。\n\n美猴王最後現身的地方在天僧寺。做好萬全準備！他一向以難以捉摸而聞名。\n\n猴人風箏大師塔克塔克就在寺廟的西方。立刻去找他，別耽誤了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42764] = {title = "眾星之廷：機器幻影", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][42765] = {title = "僧院的試煉", objective = "與美猴王一起前往玉蛟寺，取得福山之杖，漫行者之伴。", description = "我的法杖威力超強，但我不是它的主人，所以力量很快就會消失。\n\n法杖是玉龍的禮物，我只是暫時借用一下。任務結束之後，法杖就還給她了。\n\n玉龍才是法杖的守衛者，她幫有福的人保管法杖。我們現在去找她，向她提出你的請求。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42766] = {title = "桶中之謎", objective = "依美猴王提供的謎語尋找物品。", description = "我的武器最適合打架，\n不打架來夾菜嘛好呷。\n\n頂頭綁了心愛小酒壺，\n裡頭燒酒飲落熱呼呼。\n\n找武器先把酒壺灌飽，\n濃濃烈烈喝了心情好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42767] = {title = "土地之謎", objective = "依美猴王提供的謎語尋找物品。", description = "我的武器雖強，但不拿來打人\n我想保護弱小，旨在積德累仁\n\n在谷裡的人們，從早到晚工作\n勞動後的結果，你今晚拿給我\n\n我想要一袋米，不是隨便的米\n是被火焰吻過，特殊的一袋米\n\n把我要的物品拿來吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42768] = {title = "純淨之謎", objective = "依美猴王提供的謎語尋找物品。", description = "你想要我的武器？那就回答我的謎題吧。\n\n  「我找的東西又曲又彎卻無脊，\n\n   東奔西跑留下混沌宛若遊戲。\n\n   有時帶來生命，有時帶來永憩，\n\n   少量時不錯，大量時偷人氣息。\n\n   它就像像塵土一樣平凡無奇，\n\n   但這也是最奇怪的地方，因為\n\n   只有純淨之池才能找到而已。」\n\n把我要的物品拿來吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42769] = {title = "眾星之廷：帶回眼睛", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][42770] = {title = "尋求指引", objective = "前往西瘟疫之地，在烏瑟之墓和麥斯威爾‧泰羅索斯領主說話。", description = "提里奧大領主也許不在了，但是灰燼使者還在世上。它的力量足以摧毀燃燒軍團。我們必須找到它！\n\n我也希望它還在提里奧當初倒下的地方，但事情沒那麼簡單。現在它有可能在那塊該死的地方的任何一個角落。\n\n我想有位老朋友或許能幫我們找到這把劍。我希望你能相信我，去一趟瘟疫之地探訪烏瑟之墓。我們會在那裡找到答案。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42771] = {title = "恢復平靜", objective = "淨化9個靈魂。", description = "因為聖光受到侵擾，導致墓地裡迷失的靈魂紛紛往生者的世界移動。其實，他們只是渴求慰藉…就像我們一樣，失去提里奧大領主的日子實在太黑暗了。\n\n無奈的是我們曾經發誓保護這裡，而他們的騷動已經褻瀆了墓地。如果想讓此地恢復平靜，只能淨化這些靈魂了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42772] = {title = "神聖之地", objective = "淨化悔恨嶺的墓地。", description = "我們必須確保埋葬在此的逝者不受騷擾。如果任憑這些靈魂四處遊蕩，聖光也會受到影響。\n\n這個情況不能繼續下去。\n\n我會繼續保持結界，避免迷失的靈魂闖入光明使者的安息地。如果你可以淨化墓地，就能結束這場混亂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42773] = {title = "聖光顯形", objective = "與『光明使者』烏瑟交談。", description = "我們找的這位老朋友，其實在很久以前就離開人世。\n\n『光明使者』烏瑟是我所知的聖騎士當中，最了解聖光的。如果我們向他求助，他也許能幫我們找到灰燼使者。\n\n儀式備妥了。你準備好的話，就去墓地吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42774] = {title = "希望猶存", objective = "前往聖光之願禮拜堂和麥斯威爾‧泰羅索斯領主碰面。\n\n已提供物品：\n", description = "提里奧…竟然還活著！我們得去救他。\n\n聖光之願禮拜堂離這裡不遠。我們必須集結軍力，然後立刻前往破碎海岸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42775] = {title = "計畫中的關鍵", objective = "將薩格萊特鑰石放在偵察地圖上。", description = "我們有阿卡瑪的知識。寇達娜‧魔歌已經被消滅。而且，我們也拿到了薩格萊特鑰石。\n\n一切都非常順利。\n\n這份榮耀屬於你，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42776] = {title = "強者成雙", objective = "徵募貝拉斯‧曦刃和懷惡族母成為你的勇士。", description = "隨著我們的部隊成長，我們的勢力不斷向外擴張，你現在需要更多值得信賴的勇士來負責重大任務。\n\n現在你該從所有勇士之中，挑選能力最強的兩位加以晉級了。\n\n就我的看法，你應該考慮徵募貝拉斯和懷惡族母。這兩位都已經證明了他們是不可或缺的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n碎裂深淵裹腕強效職業大廳的榮耀大廳資源"}
