MultiLanguageQuestData['tw'][42857] = {title = "潮濕樹籬", objective = "前往灰白曠野，收集5個富含水分的灰白氈果。", description = "這些水果看來是劣魔的食物。\n\n如果將這些水果從村莊移走，老灰背或許會承你的情。", progress = "你發現我可能感興趣的果實？", completion = "啊，是的，這是劣魔的補給食品。或許我能利用這個將牠們引走。謝謝你。", rewards = "您會收到：\n\n"}
