MultiLanguageQuestData['tw'][42882] = {title = "血色屠殺", objective = "殺掉16個血色十字軍。", description = "我們來此只為了一個目的，喚醒莎莉‧懷特邁恩成為黯刃騎士。我們不達成目的之前絕不停手。\n\n不過，艾澤拉斯的人民也受夠血色十字軍的威脅了。所以，我們今天在此的工作，在每一位十字軍倒下、每一塊石頭崩毀、每一面旌旗燒光之前都不算結束。\n\n來吧，死亡領主，讓我們把血色十字軍化為廢墟吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42883] = {title = "劣魔大暴動", objective = "在灰白曠野殺死8隻眼神瘋狂的地底劣魔。", description = "劣魔發狂了，他們肆意攻擊我的同伴，摧毀我們的村莊！\n\n拜託你了，陌生人，幫我們除去這些惡毒的生物。", progress = nil, completion = "謝謝你，&lt;name&gt;。這個村子隨時歡迎你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42884] = {title = "基層行動", objective = "使用老灰背的法杖在灰白曠野摧毀5叢糾纏荊棘。", description = "當我返家時，前門被充滿魔力的根鬚阻擋住。\n\n我有辦法除去這些根鬚，但我的族人卻很少有能力自行處理。\n\n拿著我的法杖。它的力量可輕易解開擋路的根鬚。", progress = nil, completion = "劣魔將我們的年輕人困在木屋內。多虧你慷慨仗義，他們已脫離險境。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42885] = {title = "大領主的命令", objective = "完成「大領主的命令：宿敵」任務。", description = "當務之急是追查驚懼領主巴納札爾的下落。派出我們組織的防衛者去調查它最近的動向。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42886] = {title = "前往法隆納", objective = "到舊岸之徑與復仇者波羅斯交談。", description = "我們一直在密切關注艾蘇納當地的燃燒軍團在法隆納的行動。\n\n我們的情報指出，有個高階尉官，很可能是驚懼領主巴納札爾本人，正在那個地區展開行動。\n\n這會是我們重重打擊燃燒軍團領導階層的機會。\n\n復仇者波羅斯負責指揮我們的前線部隊。他一定會樂於接受你的協助，大領主。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42887] = {title = "此即懲戒", objective = "到法隆納南方殺死20隻惡魔。", description = "怒氣在我心中翻騰，有如悶燒的煤炭。\n\n只要輕輕一撥，就會立刻燃起熊熊怒火。\n\n燃燒軍團對艾克索達的攻擊行動正好是導火線，大領主。我上次只能眼睜睜看著我的兄弟死去。\n\n不過這次，我將會親自成為劊子手。我會討回公道！大領主，幫我屠殺你在法隆納南方碰見的任何惡魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42888] = {title = "通訊球", objective = "破壞3顆燃燒軍團球體。", description = "我們有重要的工作要做，大領主。\n\n遍布在軍團營地的球體對燃燒軍團的計畫和戰略非常重要。\n\n只要破壞球體就能對他們造成重大損失。我會跟你一起去，大領主，直到達成目標為止。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42889] = {title = "回家的路", objective = "啟動信標。", description = "哈囉？我是首席傳送師歐庫雷斯。看來你安然脫身了！\n\n在我們交談的當下，我也在鎖定你的位置。我需要你啟動你那端的信標，好在我們之間建立傳送連結。\n\n明白了嗎？好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42890] = {title = "命令寶典", objective = "收集1本命令寶典，援救復仇者波羅斯。", description = "波羅斯出事了。\n\n惡魔領主賈沃斯負責看守西方的坑道，而波羅斯被困在那裡。\n\n我們必須擊敗賈沃斯，取得他手中的命令寶典，然後救出復仇者波羅斯。\n\n我跟你一起去，大領主！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n侍從之誓職業大廳的榮耀大廳資源"}
