MultiLanguageQuestData['tw'][42966] = {title = "大領主的命令", objective = "完成「大領主的命令：神聖聯盟」任務。", description = "正確的決定，大領主。我們應該更努力徵募新兵，讓部隊軍容壯盛。讓我們派勇士去完成任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42967] = {title = "大領主的命令", objective = "完成「大領主的命令：抵禦燃燒軍團」任務。", description = "說得好，大領主。燃燒軍團不是一個單一的敵人…應該想成一隻多頭的龐然巨獸。\n\n想要擊敗它們，就必須時時注意每個前線的情況。\n\n讓我們派出勇士去阻止燃燒軍團的入侵行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][42968] = {title = "大領主的命令", objective = "完成「大領主的命令：取得補給」任務。", description = "你是對的，大領主。沒有良好的後勤，我們的軍事行動也無法成功。\n\n這代表我們需要源源不絕的武器、食物、藥物及其他必需品。\n\n讓我們派出勇士去建立一條補給線。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
