MultiLanguageQuestData['tw'][43249] = {title = "鴉眼", objective = "聆聽瓦麗拉訴說鴉眼的故事。", description = "軍情七處的信件至關重要。我們必須揭露其中的秘密，否則一切就太遲了。但是目前，連我們最厲害的破譯人員都束手無策。\n\n唯一的好消息是，我們現在知道神話說的是真的。鴉眼真的存在。\n\n我們去告訴其他人吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43250] = {title = "前往鴉廷", objective = "到維爾薩拉的鴉廷與瓦麗拉‧桑古納爾會合。", description = "玄鴉堡的鴉廷是我們第一個要搜索的地方。那是克塔羅斯‧黑羽堡主的家族嶺地。他是先祖之戰的夜精靈英雄。我的一些老祖宗就葬在那裡的墓地中。\n\n我們直接在那裡會和，不要被人跟蹤。軍情七處是諜報高手。我們必須技高一籌。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43251] = {title = "尋找鴉眼", objective = "撬開古代箱子的鎖，找到鴉眼。", description = "鴉眼應該就在這座庭院的某處。這裡是黑羽手下生前用來規劃策略的地方。哼，看來他們連死後也在繼續這麼做。\n\n寶石一定就在這裡附近。你的開鎖技能應該能派上用場。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43252] = {title = "永遠不得安息", objective = "讓瑟絲妲‧凝星者、曼德睿‧夜禍和特瑞爾‧月刃獲得安息。", description = "我的祖先就埋在西方的墓園中。不管是什麼原因造成死者復生，他們的靈魂現在不得安寧。\n\n所有血精靈都是高等精靈的後代，而高等精靈在世界崩裂之前，都是來自這片土地。\n\n我實在下不了手。你可以讓我的祖先安息嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43253] = {title = "靈魂之喉：古老的維酷傳說", objective = "召集人馬，到靈魂之喉的亡者之船奈格法號上取得鴉眼石板的拓印。", description = "我們在斯鐸海姆的牽制戰術揭露了一些我原本以為只是神話的重要情報。\n\n傳說中，早在人類崛起之前，維酷人製作了一顆魔法寶石。那顆寶石據說能夠…\n\n<瓦麗拉沒繼續說下去，朝四周看了看，露出苦笑的表情。>\n\n我還不想說太多。至少在找到證據之前。\n\n不幸的是，唯一能獲得證據的方法卻在靈魂之喉的奈格法號上…也就是亡者之船。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][43254] = {title = "破壞儀式", objective = "搭乘魔化蝙蝠前往薩格拉斯之墓，然後盜取薩格拉斯權杖。", description = "好戲上場了，朋友！古爾丹打算舉行一個盛大的儀式，讓世界毀滅。卡萊德斯確定拿到權杖就能阻止他的計畫。\n\n坐這隻蝙蝠去薩格拉斯之墓，找到舉行儀式的地方，偷走權杖。喔…然後跑走！\n\n卡萊德斯會盡量幫忙！祝你好運，朋友！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43259] = {title = "險樹勿近", objective = "調查布瑞登溪的扭曲之樹。", description = "<race>，必須先警告你。維爾薩拉潛伏著巨大的邪惡力量。我親眼見識過，而無一日不想忘記。如果你聽從我的建議，切記離布瑞登溪的扭曲之樹遠點。", progress = nil, completion = "於是你在扭曲之樹前，\n\n讓我透露敵人的姓名，\n\n請聽完我的悲慘故事，\n\n就能聽到姊妹的悲鳴…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43261] = {title = "勇士：凡妮莎‧范克里夫", objective = "經過這麼多事，你還想讓我成為你的勇士？\n\n<凡妮莎停頓了一陣子才開口，臉上露出不可思議的表情。>\n\n好吧，不過我只照我自己的方法做事。懂嗎？", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][43262] = {title = "勇士：迦羅娜‧半血", objective = "<迦羅娜的手指靈巧地耍弄小刀，然後熟練地插回腰際。>\n\n只要獵殺的目標具有挑戰性，不管什麼任務，我都樂意接受。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][43264] = {title = "奮起吧，勇士們", objective = "招募納茲格寧姆和薩沙理安。", description = "你很強大，死亡領主，但空有力量是不夠的。\n\n如果我們想使世界倖免於燃燒軍團，你就需要強大的盟友。黯刃騎士團就交給你掌管了，希望你能妥善地利用他們。\n\n去找納茲格寧姆和薩沙理安談談吧。在對抗燃燒軍團的戰爭中，他們會是你得力的助手。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][43265] = {title = "招募新血", objective = "使用偵察地圖，完成「招募新血」任務。", description = "現在你招募隸屬你的勇士了，便可以用偵察地圖完成破碎群島的重要任務。\n\n第一個任務對我們組織的成長和影響至關重要。請納茲格寧姆和薩沙理安開始為黯刃騎士團招募新成員。\n\n如果我們想擊敗燃燒軍團，就需要更多成員。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43266] = {title = "徵募部隊", objective = "和黑暗召喚師馬洛討論關於召喚食屍鬼的事。", description = "有位強大的死靈法師加入黯刃騎士團了。\n\n黑暗召喚師馬洛不辭千里，從暗影之境的深處來此。他會成為黯刃騎士團有力的盟友。\n\n和黑暗召喚師馬洛討論為黯刃騎士團準備食屍鬼大軍的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43267] = {title = "戰地部隊", objective = "使用指揮桌，完成「戰地部隊」任務。", description = "該是把這批新鮮的食屍鬼送往戰場的時候了。看看指揮桌，為你的勇士和部隊指派例行的偵察任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43268] = {title = "科技上層樓", objective = "在亞榭洛與古卷管理者祖巴席說話。", description = "古卷管理者祖巴席一直在研究亡域－也就是我們說的亞榭洛。\n\n透過他的研究，他找到數種可以強化黯黑堡的方法。\n\n立即和古卷管理者祖巴席說話，他很樂意分享這些方法。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][43270] = {title = "奮起吧，勇士們", objective = "徵募卡莉雅‧米奈希爾和高階女祭司伊莎納。", description = "身為牧道會的領導者，其他牧師都會尋求你的指引。很多人都會立誓效忠於你，盡其所能打倒燃燒軍團。\n\n自從你在淨化儀式中展現實力後，一定有很多人迫不及待想為你效力。找出那些牧師，讓他們為你分憂解勞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
