MultiLanguageQuestData['tw'][43349] = {title = "阿格拉瑪之盾", objective = "將阿格拉瑪之盾安置在達拉然的守護者之廳。", description = "現在聖盾遠離燃燒軍團魔爪，我們應將它帶回達拉然妥善看管，然後再繼續搜尋其餘的創世之柱。\n\n將它放在達拉然中央的傳送室應該相當安全，直到我們再次需要它。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "縛勇長褲縛勇裹腿縛勇護脛縛勇腿鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][43352] = {title = "資產保全", objective = "保護亞魯因的私藏物，不讓城市守衛奪走。", description = "惡魔跟守衛都這麼焦躁不安，我快沒有安全的地方存放違禁品了。守衛已經發現我其中一個最喜歡的儲藏點，隨時都會將把我的貨物運走。\n\n去我私藏物品的地點，讓他們知難而退。你需要使用爪鉤才能抵達那裡 - 觀察岩壁，尋找適合的著力點。\n\n事成之後，保證有你的好處。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n「借來的」精靈貴族魔導師聖杯"}
MultiLanguageQuestData['tw'][43359] = {title = "適合英雄的武器", objective = "前往咆哮山的熔爐前方指定地點，然後舉起你的武器。", description = "宗師，你在組織危急存亡時拯救了我們。\n\n你的英勇行為告訴我們，只要有決心和行動，就能克服任何挑戰。我們以你為典範，付出更多努力，終於開發了一種技巧，能夠喚醒武器蘊藏的真正潛力。\n\n請站在咆哮山的熔爐前，高舉你的武器。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43360] = {title = "裂片林精", objective = "在破碎之處內殺掉6名裂片林精。", description = "我在這片土地上行走多年，見識過各種形式的腐化。\n\n徘徊在這個大廳裡面的生物，都是因為死去的奧肯多爾而被魔法給扭曲。這些林精迷失了生存之道，已無法受到拯救。\n\n你必須殺掉他們。結束他們的苦難。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][43361] = {title = "災禍碎片", objective = "收集5個晶化樹皮。", description = "之前失敗的奧肯多爾，殘枝就在前方的大廳中。\n\n我要取得晶化樹木的碎片，嘗試分析。我們必須找出這場災變的根本原因。\n\n只有這樣，才有可能避免災難再次發生。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][43362] = {title = "幻夢沃土", objective = "在翡翠夢途收集淨化生命精華。", description = "這棵奧肯多爾屬於古老的樹種。它們並不是被培養，而是被創造出來的。樹中結合了秘法能量與原始的德魯伊魔法，兩者融合產生比原本更為強大的力量。\n\n然而秘法快要把整棵樹吞噬了。\n\n我們可以恢復平衡，但是需要用到荒野的魔法。這種魔法不存在於這個界域。\n\n你必須進入翡翠夢途，然後從那裡帶回純粹的生命精華。\n\n只有這樣，才能讓奧肯多爾保持穩定，並且再次成長茁壯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夢之淚"}
MultiLanguageQuestData['tw'][43363] = {title = "冬幕節禮物", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n冬幕節禮物"}
MultiLanguageQuestData['tw'][43364] = {title = "輕輕搖晃過的禮物", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n輕輕搖晃過的禮物"}
MultiLanguageQuestData['tw'][43365] = {title = "循環不已", objective = "在屍體上種下100顆夢境種子。", description = "好耶！林地重生相當順利。百花感謝你幫助它們。\n\n我們能夠拯救林地的許多生命，只可惜，同樣有許多生靈就此消逝。\n\n亮翼非常傷心！\n\n不過你幫得上忙！帶著這袋夢境種子。把它們種在新鮮的屍體上，不久之後，又會開出新的花朵！\n\n死亡也非常美麗，有了死亡，才能重獲新生。生生死死，循環不已！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43368] = {title = "勇士：亮翼", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][43370] = {title = "全新發明", objective = "我能夠做一個道具讓你改變哈提的外觀，不過製作材料很麻煩。我需要你前往斯鐸海姆，從獵風飛龍身上取下風暴腺體，然後再到維爾薩拉的薩斯塔拉附近，從石血鷹身人身上取得完好如初的鷹身人羽毛。艾蘇納的納薩拉斯遺跡附近有盤恨納迦，從他們身上可以獲得反光鱗片。最後，你得跑一趟高嶺闇盲沼澤地，從海縛秘法師身上找到純淨靈魂精華。", description = "我一直在研究能夠改變野獸構造的技術，尤其是它們的外觀。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n本質轉換器"}
MultiLanguageQuestData['tw'][43371] = {title = "馳援前線", objective = "使用指揮圖，完成「馳援前線」任務。", description = "我們組織的許多人已經在前線奮戰太長一段時間，協助那些努力瓦解燃燒軍團野心的人。\n\n是時候派出接防部隊，讓我們的盟友能夠喘一口氣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43372] = {title = "虛無中的低語", objective = "到虛無聖堂與吉爾納‧灰苔交談。", description = "我們的牧師正在休息並恢復精神，但有一個人偏偏與眾不同。吉爾納‧灰苔流連在虛無聖堂中，不斷瘋狂大笑。\n\n他拒絕離開，不過他的行為讓其他牧師很不安。\n\n也許你應該找他談談，看看他出了什麼問題。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43373] = {title = "最好與最聰明的", objective = "前往艾蘇納尋找薩布拉‧海克斯。", description = "如果我們想要從吉爾納的胡言亂語中找到真相，我必須施放一個幻象。\n\n這個幻象可跟平常不一樣，不過我們有最優異、最天才的鍊金師，可以製作一種精粹，來讓我看見幻象。\n\n請去艾蘇納找他們，他們現在正在支援前線。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43374] = {title = "魚人心控", objective = "從埃卓尼爾淺灘的魚人手中拯救雅里亞‧賢語者。", description = "在雅里亞和我將解毒劑送到法隆納前線的途中，我們遭到一群魚人攻擊。我們丟下解毒劑，慌忙逃命，不過雅里亞沒順利逃出營地。顯然，我的情況也沒多好，我的骨頭被變成石頭，痛得要死。\n\n雅里亞可能還活著，只是被抓走了。拜託，你必須找到她！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43375] = {title = "綽綽有餘", objective = "從散落在埃卓尼爾淺灘的補給箱中取回魔蝠解毒藥膏。", description = "我們企圖逃離魚人時，雅里亞和我拋下了原先要送給法隆納惡魔獵人的補給箱。\n\n箱子裡面裝著我們花費無數時間和材料製作的藥膏。如果不拿回那些補給品，恐怕我們在前線的盟友會受到不少折磨。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43376] = {title = "問題托盤", objective = "到艾蘇納的法隆納前線，對生病的惡魔獵人使用藥膏。", description = "施放幻象並不是一件容易的事。光是收集藥劑的材料就會花上許多時間，而我們現在時間緊迫。在我們談話的當下，前線的許多人正在受苦，需要我們原本應送達的藥膏。\n\n要是我們分工合作，應該就能度過難關。\n\n薩布拉和我會找到製作費倫所需藥劑的材料，但你必須將藥膏送到法隆納，治療惡魔獵人。這樣的安排很公平吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43377] = {title = "英靈殿：聖光火花", objective = "前往英靈殿地城，從海爾珈身上取得聖光火花。", description = "別忽視預言者的幻象，<name>，否則我們所知道、鍾愛的一切都將被燃燒軍團破壞殆盡。\n\n我們必須謹記：聖光必須與我們同在。\n\n你可以在英靈殿找到海爾珈，她即將受選成為華爾琪。從她身上取得聖光火花，然後放入我們的神殿。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43378] = {title = "艾薩拉之眼：透過鏡片看世界", objective = "到艾薩拉之眼副本，從盤恨女士身上取得海潮鏡片。", description = "我們有製作費倫藥劑所需的材料，不過，為了讓其他人也能見證他的預視，我們需要一些東西，以便將心中的影像投射出來。\n\n附近納迦身上的鏡片正好合用，不過我不認為它們會心甘情願地交出來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43379] = {title = "費倫之所見", objective = "使用海潮鏡片，見證預言者費倫所見的景象。", description = "我已經有了投影幻象所需的一切，但還有一個問題：你準備好見證了嗎？就算只是稍稍窺見未來，都會為靈魂帶來沉重的負擔。\n\n一旦我喝下藥劑，很快就會投影幻象。凝視海潮鏡片，你就能看見我所見的畫面。\n\n準備好開始時，就告訴我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n侍僧誓言職業大廳的榮耀大廳資源"}
