MultiLanguageQuestData['tw'][43383] = {title = "喚醒聖光", objective = "完成職業大廳任務，收集純淨聖光。", description = "只有從各處聖地收集來的純淨聖光，才能夠讓聖光火花成長。\n\n餵養聖光火花。隨著它日漸茁壯，甚至可能伴隨於你左右，永遠與你同在。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43384] = {title = "惡魔符文", objective = "從破碎群島的惡魔身上收集惡魔符石。", description = "我不能冷眼旁觀，任憑燃燒軍團摧毀我們的家園。\n\n我研究他們的語言有一段時間了，能夠解讀任何我能夠獲得的符文，不過我的資源相當有限。\n\n如果我有更多符文可以研究，我可能可以發現一些資訊，幫助我們找到巴納札爾。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43385] = {title = "滲透敵人", objective = "使用指揮圖，完成「滲透敵人」任務。", description = "聖光在上，我們應該集中精神，看看敵人之中是否有可以拉攏過來的目標。\n\n你的勇士應該能夠潛入敵陣，讓我們進一步瞭解如何辦到這件事。\n\n然而，這是一個很危險的任務。萬事小心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43386] = {title = "突襲軍使者", objective = "到新壁爐谷與過去的敵人結盟。", description = "我們發現北裂境的血色突襲軍出現叛徒。\n\n我知道這件事有點不可思議，他們之中居然有人能為我們所用，不過我們必須試試。\n\n預言曾經說過，古老的敵人會成為新的盟友。這絕對值得調查，試試看能否讓這些人回歸聖光。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][43387] = {title = "血色救贖", objective = "到新壁爐谷殺死血色突襲軍的成員，協助『異教徒』瑪莉拉救贖自己。", description = "聖光與我同在，<name>！這是我有生以來第一次感受到它的存在！\n\n我原已喪失希望，準備為我以血色十字軍之名所犯的罪償命，但你就這樣出現在我面前！你是我獲得救贖的希望。\n\n求求你，讓我證明自己有資格從頭來過。殺死我曾經效忠的那些人！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43388] = {title = "解放叛徒", objective = "到新壁爐谷拯救突襲軍變節者。", description = "你知道，還有很多人像我一樣。很多人早已揭穿血色十字軍所蒙蔽的真相。\n\n他們被關進牢中，過著豬狗不如的日子，只因為他們的信念早已背離突襲軍深信不已的正義與神聖。\n\n他們渴望自我救贖。要是你認為他們值得一救，我們應該試著放出他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43389] = {title = "不速之客", objective = "回到虛空之光神殿找阿隆索斯‧法奧。", description = "你把我從絞刑架救了下來，幫我逃過一劫，但你讓我共同對抗血色突襲軍，才真正讓我從揮之不去的罪惡感中解脫。\n\n我想犧牲小我，完成大我，這是不會違背聖光旨意的正道。\n\n讓我前往你的神殿，乞求預言者的原諒。我或許是個不速之客，但我必須走這一遭，才能完成自我救贖。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43390] = {title = "被遺忘的暗影", objective = "前往暮色森林，與被遺忘的暗影成員會合。", description = "聖光與我們同在，就連敵人也歸化過來。你表現得很好，成功實現預言，但事情還沒結束。\n\n暗影必須興起。我們必須復興被遺忘的暗影。\n\n你可以在暮色森林的墓地找到剩餘的教徒。他們一直在為死去的教主守墓。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43391] = {title = "虛無秘聞", objective = "從暮光領主厄古羅克手中取回娜塔莉的日記。", description = "我們的領導者堅守信念卻慘遭謀殺，這是大多數人所相信的說法。\n\n而娜塔莉‧瑟琳也早已知道自己的命運，於是她採取一些措施，防範無可避免的死亡。\n\n遭到暗殺的那一晚，娜塔莉將靈魂送至虛無，藏在只有娜塔莉自己才知道的地方。\n\n她在其中一本日記中寫下還魂的法術，但日記早已落入那些想要她死的人手中。\n\n沒有她的日記，我們就永遠無法讓她還魂。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43392] = {title = "深入虛無", objective = "在地下墓穴的暗影祭壇朗讀娜塔莉的日記，進入虛無並尋回她的靈魂。", description = "這毫無疑問是娜塔莉的筆跡。雖然字跡潦草，但訊息卻很明確：這本日記中的咒語會帶我們找到娜塔莉的靈魂，但必須在地下墓穴的暗影祭壇施法。\n\n歐迪莎和我必須負責看守娜塔莉的身體，但你的力量非常強大，應該可以輕鬆施展法術。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43393] = {title = "暗影崛起", objective = "回到虛空之光神殿找阿隆索斯‧法奧。", description = "我回來的消息很快就會傳到與我志同道合的人耳裡。艾澤拉斯很快就會看到暗影崛起，不過我猜這一切都在你的預料之中。\n\n無論你的計畫是什麼，希望被遺忘的暗影仍是你的盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43394] = {title = "突破軍團防線", objective = "使用魔炎入口的惡魔傳送門進入尼斯卡拉並找到阿波尼‧亮鬃。", description = "我接到大領主的指示，表示有一群聖騎士和牧師在魔炎入口的戰爭爆發後被俘虜了。你的女祭司德菈絲‧月牙也在那些人當中。\n\n惡魔透過傳送門，把他們全部送入尼斯卡拉的軍團要塞。\n\n如果想要救出他們，我們需要牧道會的協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43395] = {title = "聖光的盟友", objective = "拯救白銀之手騎士或牧道會牧師，並救出『救贖者』阿拉特和德菈絲‧月牙。", description = "阿拉特、德菈絲以及許多其他的盟友都還在這個荒廢世界的某處。\n\n我們不能捨棄他們，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43396] = {title = "敵人的心靈", objective = "尋找燃燒軍團情報、星圖和費倫的影像，然後殺死育母蛛后雅瑞米斯。", description = "惡魔獄卒提到它們即將展開入侵。它們的軍隊正在集結，準備進行大動作，這讓我非常擔心。\n\n讓我們盡可能追查有關惡魔計畫的訊息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43397] = {title = "團結一心", objective = "前往聖光會堂與莉雅德倫女士交談，並旁聽作戰會議。", description = "你和德菈絲之前跟聖騎士打過交道，也許他們願意讓你旁聽戰事協商。\n\n前往聖光會堂，請求聖騎士協助我們守護虛空之光神殿，擊退巴納札爾。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43398] = {title = "勇士：阿隆索斯‧法奧", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：阿隆索斯‧法奧"}
MultiLanguageQuestData['tw'][43399] = {title = "強化神殿防禦", objective = "完成10個世界任務。", description = "我們所有人都非常努力，想把這座神殿變成所有牧師的驕傲，要是讓它落入燃燒軍團手中，那就太可惜了。\n\n我們必須強化防禦，準備迎接軍團的攻勢。有了足夠的資源，就能將神殿經營成牢不可破的堡壘。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43400] = {title = "輝石", objective = "派出勇士執行「輝石」系列任務，收集50塊輝石。", description = "為了再次備戰，我們需要盡可能取得最好的護甲和武器。\n\n輝石是一種附魔材料，對惡魔魔法的抗性很高。\n\n在破碎群島的各地都可以發現少量的輝石，許多當地的住民也會將它用在金屬工藝上。\n\n我們應該派我們的勇士鎖定破碎群島四周的敵人 - 他們的儲備中應該有大量的輝石。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43401] = {title = "闇境明燈", objective = "與聖騎士同心協力守護虛空之光神殿，殺死巴納札爾。", description = "燃燒軍團已經發動攻擊！\n\n我會留在這裡，準備防守神殿。你必須馬上前往達拉然，告訴盟友開戰的消息！\n\n動作快點，<name>。我不知道我們還能擋住巴納札爾多久。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43402] = {title = "虛空之光大祭司", objective = "傾聽牧道會對你的讚揚。", description = "你已經實現預言，不只如此，你還讓艾澤拉斯的牧師團結一心。\n\n我們應該花點時間，細數你所達到的成就。您會收到：\n\n", progress = nil, completion = nil, rewards = "盟之聖光盟之秘紋盟之血肉盟之魔禦盟之烈焰盟之冰心盟之銳志盟之富饒盟之夕暮盟之風暴您會收到：\n\n大祭司長袍強效職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][43403] = {title = "保衛群島", objective = "完成10個世界任務。", description = "作為德魯伊，我們的工作是守護自然…進而守護我們的家園艾澤拉斯。\n\n破碎群島各處衝突不斷。燃燒軍團步步進逼，無數盟友向我們求援。\n\n在我們能夠對夢魘發動攻勢之前，必須先把力量集中在防守。\n\n協助破碎群島各地的盟友，等到局勢穩定後，再回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43407] = {title = "適合英雄的武器", objective = "前往靈魂熔爐前方指定地點，然後舉起你的武器。", description = "很高興向你報告，靈魂熔爐的改善工程已經完成！\n\n當你準備好了，我們就可以用靈魂熔爐強化你的武器！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43409] = {title = "適合英雄的武器", objective = "前往遠古種子前方指定地點，然後舉起你的武器。", description = "<class>t，在我們短暫的相處過程中，你為議會貢獻良多。\n\n你的決心啟發了我們，讓我們發明了新的技術，可以將你武器的力量連結到翡翠夢境本身！\n\n現在萬事俱備，等你準備好了，就能開始。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43412] = {title = "適合英雄的武器", objective = "前往納斯雷茲姆詛咒熔爐前方指定地點，然後舉起你的武器。", description = "我很高興宣布，熔爐的強化作業已經完成了！\n\n等你準備好了，我們就能用它釋放武器的真正潛力！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43414] = {title = "適合英雄的武器", objective = "前往魔血祭壇前方指定地點，然後舉起你的武器。", description = "<class>t，我們針對魔血祭壇的研究有成果了。我們研究出來的儀式可以解開神兵武器的全部力量。\n\n只要你說一聲，我們就可以立刻開始！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43415] = {title = "適合英雄的武器", objective = "前往守護者熔爐前方指定地點，然後舉起你的武器。", description = "<class>t，在我們短暫的相處過程中，你為我們貢獻良多。\n\n你的一言一行讓我們有所啟發，讓我們的努力更有斬獲。我很自豪地報告，我們發現了全新技巧，很可能對你有用。\n\n你有空的話，<class>t，我很樂意向你說明我們的研究成果。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43418] = {title = "適合英雄的武器", objective = "前往遠古元素祭壇前方指定地點，然後舉起你的武器。", description = "先知，自從你加入以後，為陶土議會帶來莫大的幫助。\n\n你的努力，我們都看在眼裡。靈界也看在眼裡。他們對於你的所作所為感到欣慰，於是教導我如何強化你的武器，讓它完全發揮潛能！\n\n儀式已經準備好了，你說一聲，我們就可以開始。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43420] = {title = "適合英雄的武器", objective = "前往光影祭壇前方指定地點，然後舉起你的武器。", description = "<class>t，我們相處的時間雖然很短，但你為牧道會帶來了莫大幫助。現在光影祭壇的工作完成了，該是我們協助你的時候了。我們已經找到方法解開你的武器潛能！\n\n來吧，請在祭壇前高舉你的武器。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43422] = {title = "適合英雄的武器", objective = "前往無冕者爐缸前方指定地點，然後舉起你的武器。", description = "真令人開心，爐缸已經改良完成！\n\n當你準備好了，我們就可以用爐缸來解開武器的真實潛力！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43423] = {title = "適合英雄的武器", objective = "前往永獵祭壇前方指定地點，然後舉起你的武器。", description = "我很高興宣布，永獵祭壇已經強化完成！\n\n等你準備好，就能用它釋放武器的所有潛力！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43424] = {title = "適合英雄的武器", objective = "前往遠古諸王祭壇前方指定地點，然後舉起你的武器。", description = "<class>t，你讓白銀之手團結在一起，完成了之前的<class>t無法達成的成就。你讓我們知道，只要有決心和對聖光的堅定信仰，就能克服任何挑戰。\n\n以你為典範，我們的工匠盡心盡力改造了遠古諸王祭壇，讓它可以釋放武器的真正潛力。\n\n他們現在大功告成了！準備好了就請向前一步，我們就能開始了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][43425] = {title = "適合英雄的武器", objective = "在熔爐和歐丁見面，然後在指定地點舉起武器。", description = "我一直在看著你，<name>。\n\n你一次又一次高舉武器帶領華爾拉亞邁向勝利，英靈殿一次又一次為你的勝利歡呼！\n\n現在熔爐獲得了改進，也該解放你的武器潛能了！來熔爐找我吧，英雄。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n英雄武裝\n\n您還會收到：\n\n"}
