MultiLanguageQuestData['tw'][43514] = {title = "往日榮光", objective = "從佛里迪斯‧法隆身上取得虛榮之飲。", description = "辛艾薩拉之心透過強大的防護法術與艾薩拉的精英調合，如果我們現在使用這股力量，就只是自尋死路。\n\n然而或許有辦法繞過這些結界。\n\n法隆迪斯親王等人曾隸屬艾薩拉帝國，手上應該留有一些紀念品，其中一定有虛榮之飲。據說女王曾用這種東西控制追隨者的思想。\n\n看看你能不能說服他們交出一瓶。", progress = "可能得花點功夫才能說服法隆迪斯的人交出藥劑，他們之中有些人還緊抓著過去的榮光不放。", completion = "很好，這樣我們就有辦法解除辛艾薩拉之心的防護魔法了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43517] = {title = "暗心灌木林：墮落的力量", objective = "在傳奇難度中，前往暗心灌木林從橡心身上取得腐化精華，並擊敗薩維斯之影。", description = "一旦我們有正確的工具，就能使用辛艾薩拉之心將強大的力量注入你的神兵武器。我們只需要一個力量來源。\n\n在暗心灌木林深處有一棵古樹叫橡心，原本是夏達希爾偉大的保衛者。遺憾的是它已經像其他許多古樹一樣，沉淪於夢魘之中。\n\n隨著黑暗在它心中生根茁壯，腐化精華也隨之強化。請你取回精華，以便取其力量，讓高貴的橡心得以安息。", progress = "你拿到精華了？", completion = "那棵古樹總算重獲安寧。\n\n希望它沒有白白犧牲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43518] = {title = "調製黑暗", objective = "取得30份薩格拉斯之血。", description = "不是我想懷疑賽諾苟斯的計畫，但是我擔心能否讓龍心保持穩定，尤其現在還有夢魘能量的影響。\n\n別被名字誤導了，薩格拉斯之血是工藝大師常用的調製劑。我認為我們的儀式也用得上。\n\n你在各地冒險時可以多注意，看能不能找到薩格拉斯之血。要確保儀式穩定進行，需要的量應該不少。", progress = "要拿到這東西可能不簡單，但我不想要碰運氣。", completion = "太好了！這下應該行得通了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43519] = {title = "清澈的力量", objective = "使用辛艾薩拉之心吸收腐化精華的力量。", description = "萬事俱備，<name>。\n\n準備好了，就拿起你的神兵武器，將能量引導至辛艾薩拉之心，吸收夢魘精華的力量。\n\n我會用你提供的血液確保儀式安全無虞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啟動精華"}
MultiLanguageQuestData['tw'][43520] = {title = "翡翠夢魘：夢魘之中", objective = "在普通或更高難度的翡翠夢魘中，取得死凝瞳膜和夢魘之王犄角。", description = "我們必須確保夢魘再也不會腐化翡翠夢境。\n\n在腐化中心，有一個稱為伊蓋諾斯的怪獸，可說是活生生、血淋淋的恐懼化身。你會在旅程中常常看到這個怪獸。\n\n請你務必消滅它，以及夢魘之王本體…薩維斯。\n\n每次消滅它以後，就將一小塊碎片交給我。我們可以研究碎片，瞭解夢魘擴散的原因。", progress = "任務完成了嗎？", completion = "這…比我們需要的多太多了。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43521] = {title = "翡翠夢魘：力量精華", objective = "在普通或更高難度的翡翠夢魘中，取得30個腐化精華。", description = "既然我們現在比較瞭解辛艾薩拉之心的能力，該激發它真正的潛能了。\n\n在翡翠夢魘中，你會發現不該存在的生物，那些怪物完全背離了夢境的本質。\n\n也背棄了綠龍的精神。\n\n如同橡心，怪物身上都有腐化精華，而且力量更強。請盡可能收集腐化精華，我們會以其人之道，還治其人之身。", progress = "接下來的任務不容易，但我對你有信心。", completion = "你擁有與我們不相上下的勇氣\n\n做得好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43522] = {title = "必要的消耗", objective = "使用辛艾薩拉之心吸收腐化精華所有的力量。", description = "就像之前一樣，<name>，等你準備好了就舉起神兵武器，將它的能量引導到辛艾薩拉之心上，我們就能激發精華的力量。\n\n別擔心，你收集的血還夠用，儀式可以順利進行。", progress = nil, completion = "我只能為你做到這個地步，小傢伙。如果你還想要更多的力量，必須想其他辦法了。", rewards = "您會收到：\n\n充溢精華"}
MultiLanguageQuestData['tw'][43523] = {title = "清償債務", objective = "前往蘇拉瑪爾，在沙亞蘭裡面與大法師卡雷克會合。", description = "許多年前，月之守衛曾在先祖之戰對抗燃燒軍團。近距離接觸敵人的經驗對我們而言是珍貴無比的知識。\n\n自從你救了薩睿納斯和他的族人，他們一直留在沙亞蘭。我們何不去拜訪他們，看看他們能否提供一些幫助？", progress = nil, completion = "讓我們與薩睿納斯交談，討論接下來的計畫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43524] = {title = "眾星之廷：文意圓滿", objective = "在傳奇難度中，在眾星之廷找到洛席斯的《結界、符印以及夜裔習俗》第一版。", description = "有這麼多書，為什麼偏偏是那一本？！喔，月神，我真是一個容易上當的傻瓜。\n\n很抱歉，你根本不知道我在說什麼。\n\n我把《結界、符印以及夜裔習俗》第一版借給好朋友 - 我的意思是，從前的好朋友 - 結果那個人居然背叛我。\n\n不幸的是那本書裡面有一個儀式需要用到的咒術。\n\n可以的話，請取回那本書，但記得小心一點，它非常珍貴！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43525] = {title = "看守者鐵獄：不告而取", objective = "在傳奇難度中，到看守者鐵獄取回牽制水晶。", description = "看守者在艾蘇納的山底建立一座龐大的秘密監獄，裡頭關了各式各樣的可怕生物。\n\n也許…更準確的說法是「曾經建立」。\n\n這是我們的機會。看守者用強大的牽制水晶關押囚犯，要是能找到完好的水晶，就能用來限制辛艾薩拉之心的力量。\n\n反正他們也用不著了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43526] = {title = "真正的考驗", objective = "使用辛艾薩拉之心，從扭曲的符文束腕吸收力量。", description = "維祖爾的符文束腕比預期更強大。這是好事，本來力量就是越強越好，但要是法術結構不夠穩定，就非常可能引發大災難。\n\n我們應該可以利用你取回的恆時晷儀，將惡魔能量侷限在控制力場中…不過記得提高警覺，以免發生意外。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43527] = {title = "援救守衛", objective = "在蘇拉瑪爾完成「月之守衛要塞」故事情節，然後到沙亞蘭與大法師卡雷克會合。", description = "月之守衛曾是艾澤拉斯最強大的巫士，很多人以為他們在先祖之戰就全軍覆沒，但他們似乎在蘇拉瑪爾的古代堡壘存活下來！\n\n如果他們仍與燃燒軍團誓不兩立，一定會是值得爭取的盟友。\n\n<name>，要是你能救出剩下的月之守衛，我就會努力說服六法議會提供更多協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43528] = {title = "進攻計畫", objective = "等待暗夜堡開啟，然後到沙亞蘭與大法師卡雷克會合。", description = "多虧你努力不懈，辛艾薩拉之心已經可以抵擋燃燒軍團的力量。現在終於來到旅途的最後一站，古爾丹本人所在的暗夜堡就矗立在我們面前。\n\n我們需要想個辦法混進去。\n\n我正在和六法議會的其他成員合作，想辦法創造一個入口。一旦我們成功，就可以和沙亞蘭的月之守衛會合，我們還需要他們幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43530] = {title = "暗夜堡：妄自尊大", objective = "在普通或更高難度的暗夜堡中取得提里埃斯之核和大博學者艾莉珊德的千年秘典。", description = "大博學者艾莉珊德和她的支持者已經失去理智，他們真的相信與燃燒軍團結盟，就能毀滅他們以外的一切事物！\n\n他們恐怕已經無藥可救，不過他們手中仍有強大的物品，可以幫我們強化辛艾薩拉之心的力量。\n\n在你進攻暗夜堡的時候，記得取回瘋狂傀儡提里埃斯的能量核心，以及大博學者艾莉珊德的法術書。\n\n祝你好運。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43531] = {title = "暗夜堡：進入暗夜堡", objective = "在普通或更高難度的暗夜堡中，收集20塊暗夜裂片。", description = "就快大功告成了。既然辛艾薩拉之心已經可以安全吸收惡魔魔法，我們就得盡快取得最強大的力量來源。\n\n古爾丹把最強大的夜裔精靈調回暗夜堡，以助他一臂之力。暗夜堡上方的惡魔能量風暴已經滲入這些夜裔精靈的身體，同時也滲入他們隨身攜帶的夜井結晶裂片。\n\n那些裂片正是我們需要的，<name>。在進攻過程中，請盡量保留暗夜裂片。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43532] = {title = "暗夜堡：黑暗呼喚", objective = "在普通或更高難度中，取得一枚古爾丹之眼，然後帶去給大法師卡雷克。", description = "<name>，在我們進行儀式之前，還有件事得請你幫忙。\n\n古爾丹必須受到制裁。\n\n終止他的謊言、欺騙還有詭計。這些花招再也救不了他了。\n\n結束後，拿回一個他召喚出來的眼睛。把他的力量用在良善的地方，這會是個適合他的結局。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43533] = {title = "足以抗衡的力量", objective = "在月之爐使用辛艾薩拉之心，同時吸收暗夜裂片和古爾丹之眼的力量。", description = "辛苦工作這麼久，終於看到收穫。\n\n洛席斯提過，月之守衛要塞深處有個地方，曾用來為新守衛注入龐大的力量。那裡最適合使用或強化暗夜裂片了。\n\n準備好了就到那裡找我，我們可以用辛艾薩拉之心，徹底釋放神兵武器蘊藏的強大潛能。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上古能量\n\n您還會收到：\n\n辛艾薩拉之心"}
MultiLanguageQuestData['tw'][43534] = {title = "薩格拉斯之血", objective = "收集3枚薩格拉斯之血。", description = "我們需要魔力強大的材料才能將魔法灌注到我們的武器和護甲。有一種稀有的材料正好符合需求：薩格拉斯之血。\n\n我們會需要相當多的數量，等你收集夠了就帶過來交給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43535] = {title = "翻譯內容：危險！", objective = "到聖光會堂與阿波尼‧亮鬃交談。", description = "<德菈絲把魔化之血抹在詞典的書頁上，陌生符印倏地迸現在紙張上。她發狂似的振筆疾書。>\n\n我的天啊…這裡面詳細記錄了燃燒軍團入侵部隊在魔炎入口的部署狀況。它們正準備開啟直接通往惡魔世界尼斯卡拉的傳送門！這事關重大，我們必須馬上通知你的盟友。\n\n如果你要返回聖光之願禮拜堂，我可以跟你同行嗎？我想要盡我所能提供協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43539] = {title = "『騎士』撒拉納", objective = "完成「『騎士』撒拉納」任務。", description = "四騎士需要最好的戰駒。這不是輕鬆的任務。\n\n我已經安排好前往暗影之境的任務，這就是我們接下來的計畫。\n\n任務的目標是找到黑騎兵的領導者『騎士』撒拉納，召他到亞榭洛。\n\n目前這個任務正在等候你的指派。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43540] = {title = "敵人的心靈", objective = "尋找燃燒軍團情報、星圖和費倫的影像，然後殺死育母蛛后雅瑞米斯。", description = "惡魔獄卒提到它們即將展開入侵。它們的軍隊正因為某個大計畫集結，這讓我非常擔心。\n\n讓我們盡可能追查有關惡魔計畫的訊息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43541] = {title = "團結一心", objective = "與德菈絲‧月牙交談，並旁聽作戰會議。", description = "很高興看到你安然歸來，大領主。德菈絲‧月牙和牧道會的代表已經到了。\n\n這些牧師前來討論他們隱藏在扭曲虛空深處的權力中心，也就是虛空之光神殿。\n\n如同你們所知，燃燒軍團尋找他們的據點已經有一段時間了，而現在…燃燒軍團終於找到了。\n\n白銀之手同意聽聽他們的來意。大領主，你想加入討論嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n白銀之手束腕強效職業大廳的榮耀大廳資源"}
MultiLanguageQuestData['tw'][43545] = {title = "玄鴉堡：玄鴉堡之主", objective = "前往玄鴉堡擊敗克塔羅斯‧黑羽堡主。", description = "在調查玄鴉堡的遺跡時，我們的勇士遇到埋伏！玄鴉堡堡主似乎已經與燃燒軍團結盟。\n\n我們需要你的協助，擊潰他日益壯大的軍隊，並且擊敗他本人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鬧鬼的黑羽遺物"}
MultiLanguageQuestData['tw'][43546] = {title = "翡翠夢魘：伊蓋諾斯", objective = "在翡翠夢魘擊敗伊蓋諾斯。", description = "我們的勇士發現了腐化的源頭。翡翠夢境已經被燃燒軍團感染，如果我們不盡力阻止它們，這只會是腐化的開端。必須扼制整個局勢。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夢魘寶箱"}
MultiLanguageQuestData['tw'][43547] = {title = "翡翠夢魘：伊蓋諾斯", objective = "在翡翠夢魘擊敗伊蓋諾斯。", description = "我們的勇士發現了腐化的源頭。翡翠夢境已經被燃燒軍團滲透，如果我們不想辦法阻止它們，這只會是腐化的開端。必須扼制整個局勢。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夢魘寶箱"}
MultiLanguageQuestData['tw'][43548] = {title = "翡翠夢魘：伊蓋諾斯", objective = "在翡翠夢魘擊敗伊蓋諾斯。", description = "我們的勇士發現了腐化的源頭。翡翠夢境已經被燃燒軍團滲透，如果我們不想辦法阻止它們，這只會是腐化的開端。必須扼制整個局勢。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夢魘寶箱"}
MultiLanguageQuestData['tw'][43549] = {title = "翡翠夢魘：伊蓋諾斯", objective = "在翡翠夢魘擊敗伊蓋諾斯。", description = "我們的勇士發現了腐化的源頭。翡翠夢境已經被燃燒軍團滲透，如果我們不想辦法阻止它們，這只會是腐化的開端。必須扼制整個局勢。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夢魘寶箱"}
MultiLanguageQuestData['tw'][43550] = {title = "眾星之廷：進入眾星之廷", objective = "前往眾星之廷擊敗諫言者梅朗卓斯。", description = "今天的天氣最適合開派對了，不是嗎？\n\n前往眾星之廷，大博學者可能會親自現身，說服貴族認同燃燒軍團巡邏兵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夜裔背包"}
MultiLanguageQuestData['tw'][43551] = {title = "暗心灌木林：進入暗心灌木林", objective = "在暗心灌木林擊敗薩維斯之影。", description = "薩維斯在夏達希爾的枝幹底下發揮邪惡的影響力，將原本純淨的德魯伊林地予以扭曲腐化。\n\n不僅如此，薩維斯還俘虜了許多德魯伊，以緩慢又痛苦的方式折磨他們。我們應該前往暗心灌木林，阻止他的邪惡計畫。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n被掠奪的看守者寶箱"}
MultiLanguageQuestData['tw'][43552] = {title = "艾薩拉之眼：進入艾薩拉之眼", objective = "前往艾薩拉之眼擊敗艾薩拉之怒。", description = "我們的調查結果顯示，艾薩拉女王親自下令，要求納迦準備召喚強大的怪物，讓艾薩拉的力量襲捲整個破碎群島。\n\n前往艾薩拉之眼，阻止這場儀式。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n防水拾荒背包"}
MultiLanguageQuestData['tw'][43553] = {title = "靈魂之喉：進入靈魂之喉", objective = "前往靈魂之喉擊敗黑爾雅。", description = "我們的斥候表示，被詛咒的維酷人被迫登上亡者之船奈格法號。\n\n前往靈魂之喉擊敗黑爾雅，阻止她繼續收集更多不幸的可憐靈魂。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n海草包覆的背袋"}
MultiLanguageQuestData['tw'][43554] = {title = "奈薩里奧巢穴：進入奈薩里奧巢穴", objective = "前往奈薩里奧巢穴擊敗達古爾。", description = "我們的斥候發現，卓格巴不只取得泰坦聖物，還建立了一支大軍，足以威脅整個世界。\n\n在卓格巴的軍隊展開全面攻勢之前，深入地下巢穴世界，阻止地底之王。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n黑龍寶箱"}
MultiLanguageQuestData['tw'][43555] = {title = "幽暗地道：進入幽暗地道", objective = "於幽暗地道擊敗諫言者凡卓斯。", description = "幽暗地道比我們想像的還要錯綜複雜，而且危機四伏。要想攻下那座城市，我們必須先解決地底的問題。\n\n進入幽暗地道，消滅所有敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n未標記的蘇拉瑪爾寶庫木箱"}
MultiLanguageQuestData['tw'][43556] = {title = "看守者鐵獄：進入看守者鐵獄", objective = "擊敗看守者鐵獄中的寇達娜‧魔歌。", description = "看守者鐵獄的情況比我們想像的還糟。原本的囚犯變成獄卒，全面佔領整個監獄。不過，我們最新的情報指出，寇達娜‧魔歌可能還在那裡。\n\n進入看守者鐵獄，淨化那裡的邪惡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n沒收材料袋"}
MultiLanguageQuestData['tw'][43557] = {title = "紫羅蘭堡之襲：紫羅蘭堡", objective = "擊敗紫羅蘭堡之襲的罪魁禍首。", description = "紫羅蘭堡關了許多巫妖王麾下的大將，而且燃燒軍團的間諜可能已經潛入。我們必須前往那裡阻止惡魔，別讓它們放出任何囚犯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紫羅蘭堡違禁品置物箱"}
MultiLanguageQuestData['tw'][43558] = {title = "馭風者的桎梏", objective = "取得兩個馭風者的桎梏以及10塊煉獄硫磺。", description = "現在桑德蘭再次以天空之牆領主的身分崛起，或許你可以拿某樣東西來交換那對可憎的武器。但是只有一個桎梏是沒有用的。\n\n把兩個桎梏，還有用來結合桎梏的強力礦石帶來。然後我就會安排你和『馭風者』桑德蘭見面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43560] = {title = "覲見馭風者", objective = "見到桑德蘭。", description = "我信守承諾，『馭風者』桑德蘭在等你。\n\n記住，如果你有絲毫背叛的念頭，馭風者是不會被騙的。別多話，或許這次會面有好結果。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n四散之風"}
MultiLanguageQuestData['tw'][43561] = {title = "我相信我會飛！", objective = "為史尼卡洛斯‧飛球收集6根脫換的羽毛。", description = "別再浪費時間解釋一切，只要知道，我有辦法逃離這個…這個…<仔細檢查他的訂製服，然後很快看一下附近的一堆糞便。>\n\n這個地方真臭！不過你幫得上忙！\n\n這裡的這些羽毛對我的逃脫計畫不可或缺。如果你不介意，我敢肯定這裡的羽毛夠我們兩個人用！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n角鷹獸之羽"}
MultiLanguageQuestData['tw'][43562] = {title = "能量全開", objective = "啟動蘇拉瑪爾的所有地脈饋流，然後與薇兒塔交談。", description = "奧肯多爾正在汲取超級龐大的能量。\n\n就算地脈饋流全速供應，能量也可能不足。\n\n首先，讓我們確認連接至沙亞蘭的所有潛在地脈導管都已經啟動。\n\n然後我就能嘗試加大輸出，希望能夠滿足這間工廠的需求。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n自由漂浮的地脈火花"}
MultiLanguageQuestData['tw'][43563] = {title = "瞬效法力風暴發射器", objective = "從拱時防衛者身上收集4片防曲護板。", description = "歐庫雷斯的理論十分完整。大膽，但是可行。\n\n一個小範圍的扭曲力場就能封閉並催化夜流中樞的法力，使其形成類似奧肯多爾失去平衡時的法力風暴。\n\n我會製作能夠產生扭曲力場的裝置，不過我需要材料。\n\n特別是能夠對抗扭曲力場的合金，例如貴族區的高級守衛傀儡的裝甲護板。\n\n那些傀儡具有致命的危險性。要是有人欠你一份人情，正好叫他們來幫忙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n注入法力的拱時能量核心"}
MultiLanguageQuestData['tw'][43564] = {title = "流量控制", objective = "封閉路納斯特大道、遊行場、以及午夜庭園的地道出口。", description = "如果一切按照計畫進行，法力風暴會激化地脈能量，導致能量大量湧入地道。\n\n如果要讓這股能量抵達沙亞蘭，我們就必須封閉沿途所有出口。只要有一處沒封好，一切就前功盡棄，而且從那邊噴出的能量會讓數以百計的人瞬間蒸發。\n\n薩莉瑟拉最好對這顆樹有十足把握。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][43565] = {title = "帶回信標", objective = "使用進階傳送信標調查蘇拉瑪爾城的永月平民區、永月市集及海妖守望。", description = "我們需要的中樞在幽暗地道裡，但自從你…呃…「拜訪」諫言者梅朗卓斯之後，幽暗地道的防禦提升了一個等級。\n\n我們僅剩的合理選項就是將你的突襲隊直接傳送進去。\n\n這是沒有定位的長途傳送。換句話說，就是難度超級高。\n\n帶著這個信標，然後調查蘇拉瑪爾城的平民區，然後把信標帶回來，讓我分析結果。\n\n這樣一來，我就能盡量把你傳送到中樞附近！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][43566] = {title = "凋萎進程", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][43567] = {title = "背水一戰", objective = "完成「背水一戰」事件。\n\n首席傳送師歐庫雷斯可以展開事件。", description = "該是執行計劃的時候了。\n\n歐庫雷斯會將你、亞魯因和我傳送到幽暗地道，我們會在夜流中樞引發一股法力風暴。\n\n薇兒塔會留在這裡，準備讓沙亞蘭接收大量湧入的秘法能量，希望這可以滿足奧肯多爾。\n\n$p…我們有句諺語：「高處不勝寒。」只有背負領導這個重責大任的人，才能真正了解同伴的可貴。\n\n說實話，有你們同行，我並不覺得孤單。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n法力風暴能量結晶"}
MultiLanguageQuestData['tw'][43568] = {title = "奧肯多爾，遠古魔導師之禮賜", objective = "拾取奧肯多爾果實，與首席傳送師歐庫雷斯、秘法師薇兒塔和首席秘法師薩莉瑟拉分享。", description = "千萬年前，在奎爾多雷才剛開始探索秘法的奧妙時，有一小群德魯伊和最早的精靈法師見面。\n\n在皙白的月光下，他們成立了一個組織，旨在憑藉大自然的力量，為秘法帶來平衡。奧肯多爾便是為此而生。\n\n我隸屬於這個組織的師長們已經殞沒很久了。但他們留下的一切並未消逝。\n\n他們的贈禮能治癒夏多雷的靈魂。讓他們吃下吧，然後他們就能歸於完整。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n秘能果"}
MultiLanguageQuestData['tw'][43569] = {title = "亞魯因的請求", objective = "找到亞魯艾兒，將一顆奧肯多爾果實交給她。", description = "我從沒想過我必須看到這個…\n\n<凡席爾舉起手中的卷軸。>\n\n亞魯因做了…備案…以防自己失敗。內容不多，但我要完成他最後的請求。\n\n<凡席爾將卷軸交給你。>\n\n前往標記在這張地圖上的位置。帶著這顆奧肯多爾果實，把它送到名叫亞魯艾兒的女性手中。亞魯因明確地指出，他所有的獎勵都要交付給她。\n\n原來，他早就知道自己的犧牲有什麼意義。我一直都誤解他了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][43571] = {title = "奈薩里奧巢穴：地底之王髮辮", objective = "到奈薩里奧巢穴取得地底之王髮辮。", description = "你好，死亡領主。自從我們第一次見面以來，對你而言，已經過了好多年，但對我而言，不過只是幾天而已。\n\n騎士與坐騎之間的穢邪連繫不容輕忽。唯有力量才能帶來更多力量，死亡領主。請別忘記這個事實！\n\n我可以為騎士與坐騎締造牢不可破的連繫，但為此我需要力量強大的媒介。\n\n我需要的第一件東西是地底之王髮辮，那是一個代代相傳的黑暗薩滿飾物。\n\n目前它在地底之王達古爾手裡。", progress = "你取得地底之王髮辮了嗎？", completion = "做得很好，死亡領主。這條穗帶的繩線將會用來製作坐騎的韁繩。\n\n相信達古爾一定不想交出它，對吧？\n\n&lt;撒拉納現出一抹邪惡的笑容。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43572] = {title = "暗心灌木林：夢魘之鞭", objective = "從暗心灌木林取回夢魘之鞭。", description = "天啟的暗黑坐騎是充滿憤怒與冷酷、不屈不撓的生物。他們永遠不會被人馴服…只是暫時屈服。\n\n我們需要的下一個力量之源是生於憎恨、製於翡翠夢魘的物品。人們稱它為夢魘之鞭。\n\n夢魘之鞭擁有讓活生生的靈魂喪失一切希望、一切光明的力量。\n\n夢魘之鞭的持有者是薩維斯之影。請擊敗他，將夢魘之鞭交給我！\n\n我會用它駕馭被詛咒的坐騎！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43573] = {title = "增加戰爭援助", objective = "完成10個世界任務。", description = "四騎士的任務至關重大，但我們必須將注意力轉移到戰場前線。\n\n我們在戰場上的傑出表現震驚了燃燒軍團，因此，它們增加了進攻頻率和強度。\n\n有鑑於情勢惡化，我們也必須強化抵抗能力！\n\n之後，我們才能將注意力轉回到四騎士。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43574] = {title = "靈魂之喉：亡者之槌", objective = "從黑爾海姆取得亡者之槌。", description = "我們收集到了所有必要的物品。受詛咒的穢邪戰馬鐵蹄很快就會踏過燃燒軍團的大軍。\n\n然而我們的工作尚未完成，還有一件東西還沒取得…\n\n亡者女王黑爾雅潛伏在黑爾海姆深處，統治著亡者的世界。她擁有一把注入無數死去戰士靈魂的大槌。\n\n請將亡者之槌帶來給我，有了它，我就能鑄造牢不可破的馬鎧…任何惡魔都破壞不了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43576] = {title = "在避難所會合", objective = "回到星歌避難所。", description = "在這個地方我不能清楚思考。\n\n雖然月井仍舊十分純淨，但夢魘的腐化作用仍未消散。\n\n來吧，讓我們回到避難所，大家一起集思廣益。然後我們會繼續追尋我的丈夫。", progress = nil, completion = "我的心靈已經變得更加敏銳。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43577] = {title = "佔領傳送門", objective = "完成任務：調查魔魂堡、準備迎接及最後機會。", description = "是時候開始反攻燃燒軍團了。\n\n燃燒軍團在破碎群島各地建立許多傳送門。\n\n要是你的部隊能夠成功奪下作用中的傳送門，海姆達爾就能用你收集的符石，將傳送門連結到囚禁霍迪爾的鬼地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43581] = {title = "耐心等待", objective = "等待翡翠夢魘開啟，然後回到艾蘇納找賽諾苟斯。", description = "你在灌木林所面對恐懼只不過是開頭。在翡翠夢魘中，你將會直接面對讓艾澤拉斯所有生靈不得安寧的腐化本身。\n\n但時候未到。\n\n我們還沒辦法破解保護薩維斯邪惡領域的魔法。等我們破解魔法後，你必須回到這裡，這裡還有很多事要做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43582] = {title = "蘇儸紀公園", objective = "騎乘蘇艾許，擊敗50個敵人。", description = "我們有一隻魔暴龍。\n\n看來她現在把你當成了獸群領袖。她應該會對你唯命是從。\n\n她看來餓了。你何不暫時解開她的韁繩？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鈷藍琥珀水晶"}
MultiLanguageQuestData['tw'][43583] = {title = "生命會找到出路", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][43585] = {title = "全面備戰", objective = "完成「協助華爾琪拉」、「海上迷航」和「海巨人之奴」任務。", description = "在召集盟友與我們一起對燃燒軍團展開最後決戰之前，我們會盡量充實自己的實力。\n\n破碎群島還有許多工作要做，在那裡取得的每一場勝利，都能化作擊潰敵人的助力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43586] = {title = "靈魂之喉：給黑爾雅的訊息", objective = "到靈魂之喉擊敗黑爾雅。", description = "我們沒辦法在腹背受敵的情況下獲勝。\n\n如果想爭取一點對付燃燒軍團的餘裕，就得對黑爾雅取得決定性的勝利。我們的目標不是她的軍隊，也不是她的尉官，而是幽界之母本人。\n\n前往靈魂之喉擊敗黑爾雅吧，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43587] = {title = "地脈饋流：艾洛爾善", objective = "對地脈饋流注入上古法力。", description = "<地脈饋流似乎完整無缺、毫無損傷，但未正常運作。注入上古法力後，應該就能讓它再次正常運作。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43588] = {title = "地脈饋流：克爾巴洛", objective = "守護地脈饋流並對它注入上古法力。", description = "<這饋流似乎得從地脈吸取能量，以便完全正常運作。\n\n你應該可以對它注入法力，但需要幾分鐘的時間汲取足夠的地脈能量，才可接受注入。\n\n提高警覺，其他生物可能會注意到秘法能量的波動…>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43590] = {title = "地脈饋流：月落脈能站", objective = "尋找損壞的脈能圓盤，然後修好地脈饋流。", description = "<這處地脈饋流似乎已經受損。上方的大型收集器損壞。\n\n損壞的零件一定就在這附近。地板上有粗糙的磨損痕跡，似乎是由某種生物造成，其體型比洞穴裡面的生物大上許多。\n\n應該非常非常大。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n古代聚焦水晶工作坊"}
MultiLanguageQuestData['tw'][43591] = {title = "地脈饋流：艾瑟納爾脈能站", objective = "收集6個地脈饋流碎片，然後灌注上古法力。", description = "<這個地脈似乎已經受損，需要維修。\n\n主圓柱的許多大型零件遺失，秘法能量在縫隙中劈啪作響。\n\n附近的元素四處遊走，似乎正在撿拾殘骸，將其吸收到體內。遺失的零件說不定就在它們身上…>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
