MultiLanguageQuestData['tw'][43810] = {title = "開始正事", objective = "進入漫步宏園並殺死15個防衛者。", description = "<name>，事有輕重緩急，首先我們要建立營地。\n\n我們沒有長期抗戰的時間和資源，也無法對他們採取斷水斷糧的計策。\n\n他們主要的戰線都在城內，不過還是有可能在我們設置防線的時候發動攻擊。\n\n大膽進入他們的陣地，讓他們知道要對付經歷過數千年征戰的卡多雷，可沒那麼簡單。找出他們的弱點，攻其不備。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n受祝福的卡多雷旗幟"}
MultiLanguageQuestData['tw'][43811] = {title = "路納斯特莊園傳送器啟動！", objective = "對傳送信標注入上古法力。", description = "<傳送信標已經停用，但完好無缺。只要用一些上古法力，就可以讓它恢復正常運作。>", progress = "<信標冰冷而黑暗。>", completion = "&lt;當你注入上古法力時，信標不斷發光。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43812] = {title = "開始正事", objective = "進入漫步宏園並殺死15個防衛者。", description = "<name>，辦正事的時候到了。時間所剩不多。\n\n雖然我們無法為長期抗戰做準備，但還是需要建立作戰營地。我不認為夜裔會在我們架設營地時安分地待在城市裡。\n\n他們已經展開了防禦措施。進入城市，打探我們要面對的是什麼。你要在我們做準備的時候，從內部進行破壞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的辛多雷旗幟"}
