MultiLanguageQuestData['tw'][43991] = {title = "保衛者", objective = "使用你的德魯伊力量在野性之石、守護者之石、恢復之石以及平衡之石與守護者們溝通。", description = "為了徹底釋放塑像的力量，我們需要四種荒野精華，分別是殘暴精華、癒合精華、平衡精華及堅毅精華。\n\n要找到這些精華，我們必須詢問森林的保衛者。\n\n前往翡翠夢途，釋放古代德魯伊之石的力量，保衛者們只會在能與自然溝通的人面前現身。", progress = nil, completion = "你感覺到自然的保衛者了嗎？他們無所不在，常伴你我左右。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][43994] = {title = "餵食薩莉瑟拉", objective = "<薩莉瑟拉不由自主地顫抖，幾乎說不出話。>", description = nil, progress = "<薩莉瑟拉不由自主地顫抖，幾乎說不出話。>", completion = "&lt;她小心翼翼地將水晶從你手中一顆一顆拿走。&gt;", rewards = nil}
MultiLanguageQuestData['tw'][43995] = {title = "餵食薇兒塔", objective = "<薇兒塔沒有回應。她的表情暴露了傾洩而出的深沉痛苦。>", description = nil, progress = "<薇兒塔沒有回應。她的表情暴露了傾洩而出的深沉痛苦。>", completion = "&lt;她猶豫了一下，才收下水晶。&gt;", rewards = nil}
