MultiLanguageQuestData['tw'][44082] = {title = "黯刃騎士團", objective = "與寇格茲‧亡斧交談。", description = "寇格茲‧亡斧已經來到亞榭洛，協助我們徵募更多死亡騎士。他擅長發掘有潛力的人才。\n\n我必須鄭重強調，我們的當務之急，是在與燃燒軍團開戰期間不斷補充人員。\n\n惡魔大軍幾近於源源不絕，而我們卻勢單力薄。\n\n準備好徵募更多死亡騎士時，就去找寇格茲談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44083] = {title = "第一位通靈師的魔典", objective = "從破碎群島的人形生物勇士身上收集13個顱骨，並將顱骨帶到處決者祭壇去。祭壇在逆風小徑那邊，位於摩根墓場附近的墓穴裡。", description = "這本古老的秘典似乎是莎泰爾的法術書，她是史上第一位通靈師。\n\n書中記載許多詛咒和咒語，包括某個特殊儀式的詳細說明，可以用來強化烏薩萊許，逆風收割者。莎泰爾稱這個儀式為「處決者的儀式」。\n\n不過莎泰爾在完成儀式前就遭遇不測了。她已經選好適合儀式的地點，或許你可以代她完成工作？\n\n首先，你需要一些顱骨。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44084] = {title = "為瑪苟報仇", objective = "殺死8個葡萄園監工或葡萄園看守者。", description = "<賽弗林語無倫次，氣得臉色發白。>\n\n他們怎能這麼做？瑪苟對他們言聽計從，任勞任怨！秘能酒從未停止生產，就算他們不斷虐待我們！虐待她！\n\n我沒辦法接受。我們必須為瑪苟報仇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夜裔典籍：釀造完美秘能酒"}
MultiLanguageQuestData['tw'][44087] = {title = "回到魔錘號", objective = "到魔錘號與戰鬥領主蓋爾道恩交談。", description = "<name>，戰鬥領主蓋爾道恩叫我請你過去一趟。他說有一件非常重要的事，需要你助他一臂之力。\n\n他請你一回到魔錘號，就立刻去見他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44089] = {title = "強化武力", objective = "與卡萊德斯討論最後一件神兵武器。", description = "書上說還有一件神兵武器，如果朋友想打敗敵人，或許有幫助。\n\n朋友要嗎？要嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44090] = {title = "忠誠之誓", objective = "回到神獵廳找祭壇看守者畢恩。", description = "老鷹出現並帶了個訊息給你：\n\n\n\n希望你一切都好。\n\n雍亞拉預言的已經廣為人知。很多人都想對隱獵團的新領導者效忠。\n\n請回神獵廳找我，進一步討論此事。\n\n- 祭壇看守者畢恩您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44092] = {title = "保家衛國", objective = "打開你的地圖，在卡林多或東部王國尋找進行中的燃燒軍團入侵行動。前往入侵地點，破壞惡魔的計劃！", description = "燃燒軍團對這座城鎮的入侵行動早已悄悄展開。它們的惡意瀰漫整個艾澤拉斯，威脅世界的每一個角落。\n\n我們必須將它們的黑暗計劃扼殺於萌芽之際。\n\n我們已經派出斥候前往世界各地，調查燃燒軍團的行動。只要發現入侵跡象，就會將地點標記在地圖上。\n\n別讓它們好過，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44098] = {title = "徵募學徒", objective = "與大咒術師米米克說話。", description = "大咒術師米米克已經到了，她專門來幫我們招募新血。她會選出最有前途的學徒，讓他們快速完成訓練。許多強大的咒術師都曾在她門下學習！\n\n請找她談談，徵募她的學徒，壯大我們的陣容。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44099] = {title = "共同的朋友", objective = "回到懼痕裂隙找卡萊德斯。", description = "很高興看到你沒事。\n\n我是我們共同的朋友卡萊德斯派來的人。他很想跟你見個面。\n\n請盡早回到懼痕裂隙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44100] = {title = "正式引見", objective = "回到虛空之光神殿找阿隆索斯‧法奧。", description = "很高興居然能找到你。\n\n我有來自阿隆索斯‧法奧的訊息。\n\n他表示，見面會已經準備妥當，請你盡早趕到虛空之光神殿。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44101] = {title = "補給品來了", objective = "挑戰並擊敗正在附近掠奪資源的恐怖圖騰勇士。", description = "這些是要送往陶土議會的補給品，但還沒經過處理。似乎被翻過了，還洗劫了不少東西。你合理地推測是恐怖圖騰部族所為。原因是他們的一名勇士正在附近，大剌剌地偷拿你的東西。\n\n挑戰恐怖圖騰，保護你的資源！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n魔化護甲改良工具勇士裝備箱\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][44106] = {title = "博學大德魯伊", objective = "在薩斯塔拉尋找艾洛瑟。", description = "艾洛瑟就住在古老林地薩斯塔拉。他在那裡與大自然交流，並教導他的侍僧治療與護存學識之道。\n\n請找到他，告訴他這裡急需他的力量。", progress = nil, completion = "歡迎你，&lt;name&gt;。你的英雄事蹟已經從幻夢之林傳遍各地。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44112] = {title = "交易夢藥水", objective = "使用夜裔藥劑製作伊瑟拉之夢藥水。", description = "從你的穿著研判，我猜你是鍊金師吧？\n\n如果你肯付合理價錢，我便願意為你提供服務。\n\n我已經離開蘇拉瑪爾好一段時間了。我渴望得到伊瑟拉之夢藥水。如欲調製藥水，你需要幻夢草與夢旅者之淚的葉子。\n\n你在不遠的廢墟空地便可採得。燒瓶在此，請幫我調製藥水。事成之後，我將有求必應。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44113] = {title = "危險：亞克洛諾斯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44114] = {title = "危險：博學者薇萊莎", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44116] = {title = "黃晶海灣神秘事件", objective = "在斯鐸海姆的黃晶海灣與艦隊上將瑟希斯交談。", description = "燃燒軍團正侵略艾澤拉斯，而軍情七處居然浪費寶貴的資源追捕並暗殺他們的一名頂尖探員？\n\n其中一定有隱情…\n\n我們一定要找出背後的來龍去脈。為什麼琥珀‧吉爾妮會被自己的組織追殺？\n\n他身上的加密信件應該有線索…不過我們還需要更多的情報。\n\n你在達拉然跟蹤的那名軍情七處刺客提到過黃晶海灣…在黃晶海灣打聽些線索，然後我們來看看信件解密以後，上面寫了什麼。", progress = nil, completion = "你最好不要出聲，夥計…有一幫海盜在前面！當然，不是你會想招惹的那種類型…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44117] = {title = "喝蘭姆酒的快樂時光總是過得特別快！", objective = "收集10瓶血刃蘭姆酒。", description = "世界上比血刃還要更兇狠的海盜不多！他們可是貨真價實的海上老手！\n\n話雖如此…他們釀蘭姆酒的技術可厲害了！我老實跟你說，<name>…世界上比血刃海盜他們的酒還好喝的蘭姆酒可少了。\n\n既然你都要去找線索了，順便幫我帶幾瓶回來怎麼樣？\n\n拿得動多少就帶多少，我一定會給你豐厚的報酬！以海盜的榮譽發誓，<name>！", progress = "你拿到香料蘭姆酒了嗎，<name>？", completion = "&lt;艦隊上將瑟希斯拔開酒瓶的軟木塞，豪飲一大口酒。&gt;\n\n對啦，就是這味，&lt;name&gt;。幹得好！", rewards = "您會收到：\n\n"}
