MultiLanguageQuestData['tw'][44274] = {title = "眾星之廷：進入眾星之廷", objective = "在眾星之廷擊敗諫言者梅朗卓斯。", description = "今天的天氣最適合開派對了，不是嗎？\n\n前往眾星之廷，大博學者可能會親自現身，說服貴族認同燃燒軍團巡邏兵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夜裔背包"}
