MultiLanguageQuestData['tw'][44443] = {title = "遠古武器", objective = "請選擇要尋找的第四件神兵武器。", description = "你已經證明自己是獨一無二的德魯伊，但如果我們想要擊退燃燒軍團，就必須把握所有機會，預先準備好面對各種敵人。\n\n還有最後一件遠古武器，或許你可以考慮一下。它可以讓你變得更強大。無論燃燒軍團怎麼對付你，都不用害怕。\n\n請讓我知道你的決定。", progress = nil, completion = "這個決定不錯。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44448] = {title = "光與暗之間", objective = "將伊露恩之淚帶到職業大廳的聖光之心。", description = "伊露恩之淚已經幫你準備好了，<name>，接下來我也不知道該怎麼做。把神器帶回你的職業大廳，並嘗試對聖光之心使用。\n\n讓它們接觸看看？說真的，我也沒比你懂多少。\n\n希望會成功！", progress = nil, completion = "死了？泰坦們死了？\n\n&lt;卡德加沉思了一會。&gt;\n\n這的確能解釋非常多事情，但我還是忍不住感到無比的哀傷。一直以來都只有我們獨自奮鬥，眾神在我們還沒出生之前就死了。\n\n至於聖光軍團和伊利丹，我感到不知所措，我從來沒感到如此無助過，\n\n伊利丹死了，而聖光軍團為了我們在群星間進行永無止盡的戰爭。\n\n我需要休息一會，&lt;name&gt;，這消息對一個老人來說太難承受了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44449] = {title = "進階淬火", objective = "為艾拉得製作一對特硬脈石臂甲。", description = "既然我們已經請來一位冰霜法師，測試這個方法應該是輕而易舉。\n\n這是我想請你製作的物品清單。馬上開工，好了就把臂甲交給我。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44457] = {title = "姊弟情深", objective = "在玄鴉監牢找到瑪翼夫‧影歌。\n\n已提供物品：\n", description = "瑪翼夫就在監獄的某處。在我來這裡的路上，我發現她丟棄的護甲。\n\n我知道你們兩人之間過去有些不合。我相信那不會是什麼大問題。\n\n讓我們分頭行事，加快搜索牢房的速度。我們得找到她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44463] = {title = "惡魔四伏", objective = "保護國王。", description = "正如我們所料，<name>！惡魔以為可以出其不意偷襲我們。\n\n快點，準備迎戰！警告國王！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "烏瑞恩家族徽印您會收到：\n\n"}
MultiLanguageQuestData['tw'][44464] = {title = "復甦", objective = "在維爾薩拉見證伊利丹‧怒風復甦。", description = "聖光之心是伊利丹‧怒風重生所需要的憑藉，也是我最後能奉獻給聖光的東西。\n\n伊利丹已經死了，他的靈魂在虛空中徘徊。我們必須先將聖光之心準備好，才能取回他的靈魂。\n\n在兩個世界之間，存在著伊利丹往日的回音，你必須找到這些回音。\n\n從生命的起源開始吧，<name>，從誕生的那一刻找起。找到伊利丹在維爾薩拉的出生地點，喚醒過往的記憶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44465] = {title = "徵募喚地者", objective = "與費琳達‧弗萊聊聊。", description = "費琳達‧弗萊最近加入了艾澤拉斯之心，她負責監督新兵，並訓練喚地者。\n\n我建議妳有空時盡快找她聊聊，先知<name>。喚地者是強大的薩滿，能大大地振奮我們的士氣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44466] = {title = "未明之道", objective = "在維爾薩拉的幻夢之林見證伊利丹的適應能力。", description = "伊利丹年輕的時候，幾乎都和他的雙胞胎哥哥瑪法里恩待在維爾薩拉。\n\n那時他們兩人正在接受半神塞納留斯的訓練，也同時相互爭奪年輕的女祭司，泰蘭妲的青睞。\n\n我們接著必須到幻夢之林去。伊利丹真正的宿命在那個地方誕生。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44471] = {title = "第二視象", objective = "使用你的靈視。", description = "雖然安杜因國王有個高貴的靈魂，但似乎缺乏他父親的魄力。聯盟現在需要一位能果斷行事的領導人。只要有暴露任何弱點，燃燒軍團就會展開突襲。\n\n就連現在我都覺得情況有些不對勁，<name>。事情恐怕沒有看起來那麼簡單。\n\n快點，使用你的靈視。我們必須知道是否有敵人混入這裡！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44473] = {title = "聯盟的武器", objective = "到暴風城的法師區與伊利達瑞會合。", description = "一開始，我不確定是否該讓伊利達瑞進駐城裏。不過你救了我們所有人的命。\n\n你可以在法師區建立營地。要與燃燒軍團決一死戰，你的能力對聯盟而言不可或缺。\n\n但不要掉以輕心。要是你的人被自身的魔化能量反噬，我們會毫不留情地把你們視為惡魔的同類。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44479] = {title = "黑羽的經歷", objective = "在維爾薩拉的玄鴉堡體驗黑羽的經歷。", description = "多年以後，當先祖之戰打得如火如荼，燃燒軍團出兵攻佔這個世界時，伊利丹遇見了名叫克塔羅斯‧黑羽的軍事領袖。他也發現伊利丹本身潛力無窮，最後甚至推選他成為月之守衛的指揮官，統領這支強大的夜精靈巫士衛隊。\n\n我們必須前往維爾薩拉西岸的玄鴉堡，重新經歷這段回憶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "魔炎裹手伊露恩長袍魔裔手套月之守衛長袍禦天者之握黑羽鎖甲護胸守衛胸甲破陣者護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][44480] = {title = "在我父親的家裡", objective = "到卡林多大陸的艾薩拉見證伊利丹的犧牲。", description = "大多數的凡人都無法理解燃燒軍團的真相。而發現其真相的人，卻經常拒絕相信其意義。這類知識的重量乃是凡軀所無法承擔的。犧牲這麼多的自我，將會使靈魂從此改變。\n\n在最偉大的英雄當中，只有極少數人能夠瞭解那種形式的犧牲。讓我們藉由伊利丹的雙眼見證一切。\n\n我們必須前往卡林多大陸的艾薩拉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44481] = {title = "未竟的命運", objective = "在外域邊境的影月谷見證真正的背叛。", description = "儘管他的形象和預言中的金色瞳仁之子大不相同，而且還以放逐者的身分生活在破碎世界的邊境，但他的動機始終不變。他唯一在意的，就是攻擊燃燒軍團，終結它們的侵略行動。\n\n然而，造化弄人，他最後卻不是敗在燃燒軍團手中。\n\n我們必須前往外域，經歷伊利丹最後的回憶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "背叛頭盔伊利達瑞高階領主風帽薩格拉斯的純淨幻象深奧面鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][44486] = {title = "燒壞的秘典", objective = "把燒壞的秘典拿給達拉然的勞勃‧紐赫希。", description = "秘典裡大半的精靈文字都已被魔化火焰燒焦。\n\n達拉然的圖書館長是修復書籍的高手，也許他可以把秘典恢復到可以辨識的程度。", progress = "噢，這個又是什麼？", completion = "啊，燒焦的部分可以用某種鍊金酊劑復原，\n\n有意思。正規的達納蘇斯書寫風格…內容卻是惡魔崇拜。\n\n我想我知道這是誰寫的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44487] = {title = "浸濕的秘典", objective = "把浸濕的秘典拿給達拉然的勞勃‧紐赫希。", description = "雖然書上帶有魔法，但還是因為泡水而毀損了。\n\n達拉然的圖書館長是修復書籍的高手，或許他有辦法修復。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44488] = {title = "不祥的秘典", objective = "把燒壞的秘典拿給達拉然的勞勃‧紐赫希。", description = "秘典裡大半的精靈文字都已被魔化火焰燒焦。\n\n達拉然的圖書館長是修復書籍的高手，也許他可以把秘典恢復到可以辨識的程度。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44489] = {title = "萊安娜‧暗愁", objective = "破壞靈魂收割者。", description = "<你的伊利達瑞同伴萊安娜‧暗愁無助的漂浮在你面前。她的靈魂緩緩地被收割者水晶吸去。>\n\n<若要將她從靜滯救出，你必須破壞靈魂收割者。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44490] = {title = "『吞噬者』恐翼", objective = "殺死『吞噬者』恐翼。", description = "謝謝你把我從囚禁中拯救出來，<name>。\n\n然而，阿佐朗不是好對付的惡魔。他是極為強大的埃雷達爾，在燃燒軍團中地位崇高。\n\n在我們去找他之前，必須先打敗另一個敵人。\n\n『吞噬者』恐翼是最為強大的魔蝠。把蜥蜴肉放在北方的祭壇上，等到恐翼出現就殺了她。\n\n提她的頭來見我，平息我對復仇的渴望。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n石化惡魔心臟"}
MultiLanguageQuestData['tw'][44492] = {title = "地脈學徒", objective = "與秘法師薇兒塔談話。", description = "做得好，居然能找到額外的地脈饋流。\n\n就一名外來者而言，你挺有能力的。\n\n讓我告訴你一些有關地脈力量的秘密。這應該可以幫助你在蘇拉瑪爾的生物身上尋覓上古法力。我知道這是件可怕的工作，所以我把它交給你！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上古法力拾荒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][44493] = {title = "地脈專家", objective = "與秘法師薇兒塔談話。", description = "我們的地脈饋流越來越強了。\n\n饋流越強，我就越能了解上古法力。\n\n當然，做為我的學徒，你會受益於我的發現。仔細聽好，我會教你用更可靠的方法，抽取敵人身上的力量。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上古法力拾荒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][44495] = {title = "地脈大師", objective = "與秘法師薇兒塔談話。", description = "你真讓我驚訝，外來者。在講述古老地脈的第一堂課，我本來以為你會迷失在冒險、尋寶這一類的白日夢中。\n\n結果你證明自己是相當有資質的學生。\n\n我們的地脈饋流變得極為強大。透過觀察它的成長，我對秘法和法力本質也有了更深刻的認識。\n\n現在讓我為你上最後一堂課，協助你找到更多上古法力。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上古法力拾荒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][44496] = {title = "未竟的命運", objective = "在外域邊境的影月谷見證真正的背叛。", description = "儘管他的形象和預言中的金色瞳仁之子大不相同，而且還以放逐者的身分生活在破碎世界的邊境，但他的動機始終不變。他唯一在意的，就是攻擊燃燒軍團，終結它們的侵略行動。\n\n然而，造化弄人，他最後卻不是敗在燃燒軍團手中。\n\n我們必須前往外域，經歷伊利丹最後的回憶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "背叛頭盔伊利達瑞高階領主風帽薩格拉斯的純淨幻象深奧面鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][44497] = {title = "未竟的命運", objective = "在外域邊境的影月谷見證真正的背叛。", description = "儘管他的形象和預言中的金色瞳仁之子大不相同，而且還以放逐者的身分生活在破碎世界的邊境，但他的動機始終不變。他唯一在意的，就是攻擊燃燒軍團，終結它們的侵略行動。\n\n然而，造化弄人，他最後卻不是敗在燃燒軍團手中。\n\n我們必須前往外域，經歷伊利丹最後的回憶。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "背叛頭盔伊利達瑞高階領主風帽薩格拉斯的純淨幻象深奧面鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][44500] = {title = "作者！作者！", objective = "請卡德加開始進行儀式，召喚第一任守護者艾洛岱的靈魂。", description = "我們已經看過從卡拉贊取回的寶典。雖然我們找到創世之柱的相關資料，但有一則重要資訊卻已經被人從書中刪掉…就是創世之柱的所在位置。\n\n幸運的是，我們找到一位從事相關研究的專家。\n\n作者艾洛岱是第一任的提里斯法守護者。他現在已經與守護者熔爐合而為一，由我們安置在安全的地方。我想該是請他出馬的時候了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44543] = {title = "破碎海岸之戰", objective = "騎乘雙足飛龍前往破碎海岸。", description = "<name>，這隻雙足飛龍會帶你到破碎海岸。希望你的武器能讓你橫掃戰場。\n\n大酋長已經降落了。我猜你只要跟著惡魔的血跡走就好。", progress = nil, completion = nil, rewards = "部落先鋒磨骨錘部落先鋒長弓部落先鋒匕首部落先鋒長柄斧部落先鋒速刃部落先鋒戰錘部落先鋒法杖部落先鋒戰斧部落先鋒法師之刃部落先鋒裂斧"}
MultiLanguageQuestData['tw'][44544] = {title = "陶土議會的召喚", objective = "與預言者沙費歐交談。", description = "終於找到你了！\n\n我帶來了預言者沙費歐的訊息。\n\n先知，陶土議會需要你。請盡快回到艾澤拉斯之心。預言者沙費歐正殷切地等候你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44545] = {title = "乘勝追擊", objective = "在職業大廳的指揮圖上選擇下一個攻擊目標。", description = "<確保了創世之柱的安全之後，正好可以一鼓作氣繼續努力。>\n\n<你想起了你的組織曾經替你收集了資訊，在旅途中或許有所幫助。在繼續之前先看看這些資訊或許是個好主意。>完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44546] = {title = "摧毀化學製藥公司", objective = "殺死12個王冠化學製藥公司的員工，用凸栓的克銀炸彈摧毀銀松森林中影牙城堡南邊的一輛化學貨車，然後回到奧格瑪找警探史內卜‧凸栓。", description = "這本帳簿記載了好多地點。朋友，我需要你去調查並採取行動。這事已經進行得夠久了。\n\n我要你去查查這條記錄，就在銀松森林中影牙城堡的南邊。感覺非常不妙。去那裡給他們一點教訓吧。\n\n噢，如果你發現任何又大又可怕的問題，必須要馬上消滅掉，就用這個炸彈炸掉它。", progress = nil, completion = "做得好，小子。你值得小小獎勵一番。然後，嘿，如果明天你有時間就回來找我，我或許有事情要拜託你。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][44547] = {title = "暴怒島", objective = "在職業大廳的指揮圖上選擇下一個攻擊目標。", description = "<歡慶勝利之餘，你心裡很清楚還需要找到好幾個創世之柱，才有可能一舉擊敗燃燒軍團。>\n\n<你的組織找到破碎群島其它藏有創世之柱的未知區域。去看看這些資訊應該能協助你決定接下來的動向。>完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44548] = {title = "寸草不留", objective = "在職業大廳的指揮圖上選擇下一個攻擊目標。", description = "<四周擺放著你已經取得的創世之柱，但你知道工作還沒結束。>\n\n<你的組織仍持續搜索群島，尋找任何可能有用的資訊。再次出發探險之前最好先聽聽他們的回報。>完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44549] = {title = "群島之主", objective = "在職業大廳的指揮圖檢視你在破碎群島的其他進攻地點。", description = "<你的組織詳細計畫進攻破碎群島並取得創世之柱。如今終於只剩最後一個地區了。>\n\n<勝利感覺近在眼前，但再看看組織的情報最後一次，百利而無一害。>完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44550] = {title = "回到亞榭洛", objective = "與『女妖』席厄克希交談。", description = "死亡領主，必須請你回亞榭洛一趟。\n\n對抗燃燒軍團的戰爭正打得如火如荼。黯刃騎士團需要你的指示。\n\n請盡快回到亞榭洛，找到『女妖』席厄克希。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44555] = {title = "卡德加的發現", objective = "在達拉然與大法師卡德加交談。", description = "勇士！請立即前來紫羅蘭城塞。\n\n我有個重要的發現，想要在六法議會面前告訴你。", progress = nil, completion = "謝謝你趕過來，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44557] = {title = "數量有限", objective = "關閉4個傳送門並在逆風小徑殺死20個惡魔。", description = "看來我所設置的防禦，還沒有全部被擊潰。燃燒軍團無法在卡拉贊內部跟附近開啟傳送門…至少目前還不行。\n\n他們似乎是從逆風小徑地底的墓穴派遣援軍。關閉那裡的傳送門，或許能為我們爭取足夠的時間，把他們趕出卡拉贊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44558] = {title = "摧毀化學製藥公司", objective = "殺死12個王冠化學製藥公司的員工，用凸栓的克銀炸彈摧毀銀松森林中影牙城堡南邊的一輛化學貨車，然後回到暴風城找巡官史尼卜‧凸栓。", description = "這本帳簿記載了好多地點。朋友，我需要你去調查並採取行動。這事已經進行得夠久了。\n\n我要你去查查這條記錄，就在銀松森林中影牙城堡的南邊。感覺非常不妙。去那裡給他們一點教訓吧。\n\n噢，如果你發現任何又大又可怕的問題，必須要馬上消滅掉，就用這個炸彈炸掉它。", progress = nil, completion = "做得好，小子。你值得小小獎勵一番。然後，嘿，如果明天你有時間就回來找我，我或許有事情要拜託你。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][44559] = {title = "尋找配方", objective = "取得王冠化學製藥公司的其他部分配方，再回到奧格瑪找警探史內卜‧凸栓。", description = "這似乎是王冠化學製藥公司新藥劑的部分配方。其他的部分一定就在附近。", progress = nil, completion = "啊哈！有了這個，我們就能調製這恐怖東西的解藥了。感謝你把它帶來給我。", rewards = "您會收到：\n\n愛之硬幣王冠製藥「超級萬能解」藥劑"}
MultiLanguageQuestData['tw'][44560] = {title = "尋找配方", objective = "取得王冠化學製藥公司的其他部分配方，再回到暴風城找巡官史尼卜‧凸栓。", description = "這似乎是王冠化學製藥公司新藥劑的部分配方。其他的部分一定就在附近。", progress = nil, completion = "啊哈！有了這個，我們就能調製這恐怖東西的解藥了。感謝你把它帶來給我。", rewards = "您會收到：\n\n\n\n等級 10–61王冠製藥「超級萬能解」藥劑\n\n等級 1–61愛之硬幣"}
MultiLanguageQuestData['tw'][44561] = {title = "希望的種子", objective = "於夜落精靈的聲望達到尊敬。", description = "薩莉瑟拉派你來找奧肯多爾，真是明智之舉，雖然她低估了奧肯多爾的力量。\n\n她會懂的，其他人也是。\n\n但這需要時間。在飢餓啃噬他們的靈魂之際，夜落精靈需要你的幫助才能存續。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44562] = {title = "逐漸茁壯", objective = "於夜落精靈的聲望達到崇敬。", description = "長久以來，魔法對精靈而言是種罪愆。魔法形塑我們，帶領我們脫離黑暗，但只要失去平衡，我們也會受到形體毀滅、墮入黑暗的威脅。\n\n夏多雷太過心高氣傲，不願承認事實，但他們確實太過耽溺。他們無法找到和諧。\n\n我能感覺到夜落精靈有此潛力，失去一切總算讓他們學會謙卑。他們也因此更加茁壯。\n\n堅持下去，$p。幫助夜落精靈再度壯大。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n谷行者咒符"}
MultiLanguageQuestData['tw'][44563] = {title = "夜落精靈的救贖", objective = "於夜落精靈的聲望達到崇拜。", description = "很快地，季節的變化會降臨，夜落精靈也會遵從命運的指示。\n\n你給了他們希望，也幫助他們走上了救贖之路。他們在這個時候非常需要你。\n\n我們都是。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n谷行者的祝福"}
MultiLanguageQuestData['tw'][44570] = {title = "榮耀火焰", objective = "榮耀阿拉卡山的仲夏篝火。", description = "仲夏火焰節慶是一個紀念元素的時節。火焰的元素會激起我們內心的激情。很多時候，這種激情將會化為積極的行動。但是在這裡，我們只把這股熱情專注在崇敬上。\n\n我們榮耀火焰是為一種傳統的儀式，你願意加入我們一起榮耀火焰嗎，<name>？", progress = nil, completion = "榮耀阿拉卡山的火焰。", rewards = "您會收到：\n\n燃燒之花"}
