MultiLanguageQuestData['tw'][44636] = {title = "建立軍隊", objective = "當你準備好帶領凋萎者進行第一項戰鬥訓練任務，就和薩莉瑟拉交談。", description = "我們必須放眼未來。有朝一日我們會需要一支軍隊。\n\n如今證明了凋萎者並非無藥可救。他們仍然可以學習、仍然可以型塑。\n\n我希望由你擔任他們的戰鬥訓練師，<name>。跟我來。我們可以把鄰近的廢墟當作競技場，鍛煉他們。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][44663] = {title = "傳瞬之間", objective = "見證達拉然傳送到破碎群島的過程。", description = "<卡德加熟悉的聲音從秘法生物傳來。>\n\n<name>，艾澤拉斯需要你！\n\n找遍奧杜亞和卡拉贊之後，我們終於得知擊敗燃燒軍團的關鍵：名為創世之柱的五樣遠古神器。\n\n我們必須把達拉然移往破碎群島，尋找這些神器。由於祈倫托的領導人珍娜…目前不在這裡，藍龍軍團的卡雷苟斯前來協助我們。\n\n燃燒軍團正在進攻我們在逆風小徑上方的位置。快來！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n達拉然爐石靜心之卷"}
MultiLanguageQuestData['tw'][44667] = {title = "華爾拉亞的意志", objective = "完成10個世界任務。", description = "準備進攻燃燒軍團世界的同時，也不能讓已經在我們世界的敵人歇息。\n\n你的軍隊目前在想辦法奪取敵人的傳送門。你最好先回到破碎群島繼續和敵人作戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44672] = {title = "上古法力", objective = "從節點取得3份上古法力。", description = "少了夜井的力量，我和我的同伴只能依賴大地本身維持生存。\n\n地脈深處的上古法力可能以不同的形式出現在地面，最常見的是水晶或寶石。\n\n<薩莉瑟拉撿起一塊小石頭、嘴裡吟誦法術，然後以指尖在石頭上面畫出符文。>\n\n當你接近上古法力時，這顆石頭就會發光。請盡可能多收集一點！在接下來的幾週期間，這會是無比珍貴的資源。", progress = nil, completion = "隨時注意蘇拉瑪爾四處有沒有出現這類結晶。我們一定用得上。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44680] = {title = "身先士卒", objective = "完成10個世界任務。", description = "我們不能讓目前的情勢影響隱獵團守護艾澤拉斯人民的使命。\n\n世界上有許多需要我們協助的人。\n\n身為我們的領導者，希望你能成為助人的典範。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44682] = {title = "無與倫比的力量", objective = "完成10個世界任務。", description = "<name>，我們四週充斥著能量，等著我們學會駕馭。\n\n你必須勇闖世界，為議會奪得力量！\n\n首席如果擁有這種無與倫比的力量，議會一定能輕易擊敗所有敵人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44683] = {title = "守衛地脈", objective = "確保卡拉贊底下的東部地脈和西部地脈安全。", description = "卡拉贊坐落在地脈匯合處。一開始之所以會選擇這個位置就是因為這樣…而燃燒軍團也注意到這點了。\n\n如果惡魔想取得地脈的能量，一定是要執行某種特別邪惡的計畫。<name>，你必須阻止他們獲得地脈的能量，我們才有可能奪回卡拉贊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n脈能與魔能轉換器"}
MultiLanguageQuestData['tw'][44684] = {title = "深入的腐敗", objective = "從逆風小徑底下的洞穴找到腐化土壤精華和腐化之水精華。", description = "燃燒軍團接觸到的任何事物，都會留下腐化的痕跡。如果我能研究他們所留下的魔法，或許就能查出他們對卡拉贊的目的是什麼。\n\n這個瓶子經過特別強化，能容納魔化魔法。如果你能幫我帶回傳送門附近的腐化水和土壤精華，我就能進一步揭開他們的計謀。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n出土的法杖頭"}
MultiLanguageQuestData['tw'][44685] = {title = "奪回壁壘", objective = "在逆風小徑沿著高塔周圍在東邊、南邊和北邊佈下結界。", description = "我們已保住地脈，現在該去鞏固卡拉贊的周邊了。\n\n在塔的外圍，有幾個地點的腐化尚未控制住。把它們找出來，用這些結界擋住腐化。\n\n加上我們目前所完成的進度，加強防禦應該就能暫時阻擋剩餘的軍團勢力，為我們爭取一點時間找出誰在幕後指使。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n超載結界法器"}
MultiLanguageQuestData['tw'][44686] = {title = "整頓思考", objective = "審問蟲舌魔俘虜。它就在逆風小徑高塔北邊的建築物裡。", description = "我研究這些樣本的時候，你先去這座建築的北角找我們的巡邏兵。聽說他們俘虜了一名惡魔。\n\n去吧，立刻審問那個惡魔，盡量打探消息。動作要快！我們時間恐怕不多了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44689] = {title = "提里斯護法之力", objective = "完成10個世界任務。", description = "破碎群島各處都傳來需要提里斯護法協助對抗燃燒軍團的請求。繼續追蹤大法師瓦戈斯的同時，我們不能忘記護法的主要任務仍是驅逐惡魔，並且保護艾澤拉斯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][44690] = {title = "嗜血渴望", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44691] = {title = "飢餓難耐", objective = "將上古法力餵給首席傳送師歐庫雷斯。", description = "我們必須盡快讓首席傳送師歐庫雷斯重新振作。\n\n不管用什麼方法，都要找到上古法力，然後餵給他。", progress = nil, completion = "啊，這樣感覺好多了。謝謝你！\n\n開始上工吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44694] = {title = "一戰一戰來", objective = "完成10個世界任務。", description = "在成為惡魔獵人之前，我曾研習秘法技藝。我仍保有少許相關知識，但體內的魔能害我幾乎完全無法使用秘法。\n\n我少數還保有的能力，是偶爾能望見遠處的情景。你看過我使用虛空法陣施展這類法術。而我現在看見的情況相當不妙。\n\n我們必須對抗的勢力不只有燃燒軍團。你必須盡快行動，破碎群島才不會整個淪陷。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
