MultiLanguageQuestData['tw'][44700] = {title = "斯鐸海姆", objective = "前往達拉然的紫羅蘭城塞，與空軍上將羅傑斯交談。", description = "<name>，能找到你真是太好了！\n\n空軍上將羅傑斯請你到達拉然和她見面。聽起來十分重要。她在紫羅蘭城塞等你。\n\n請務必盡快前往！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44701] = {title = "斯鐸海姆", objective = "到達拉然的紫羅蘭城塞與納薩諾斯‧凋零者交談。", description = "<name>，還好找到你了！\n\n納薩諾斯‧凋零者，女妖之王的勇士，召喚你前往達拉然。聽起來是有急事。他應該會在紫羅蘭城塞等你。\n\n請盡快前往！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44719] = {title = "突襲聖所", objective = "與歐庫雷斯交談，開始攻擊行動。", description = "時候到了。薇兒塔已準備好摧毀保護著聖所缺口的屏障。我會把你傳送到缺口，你負責清除那附近的敵人。\n\n拿著這些傳送之球。如果需要援軍，就用這個來召喚凋萎者。\n\n我們得在敵人建立新的防禦之前展開攻擊。等你準備好了讓我知道，我們就立刻開始行動。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗夜堡鑰匙"}
MultiLanguageQuestData['tw'][44720] = {title = "呼喚行動", objective = "在瓦迪司陀找到哈維。", description = "<烏鴉看進你的雙眼，你的腦中也響起熟悉的聲音。>\n\n勇士，我需要你的協助。看來黑爾雅已經準備出手了。\n\n做好準備，然後過來找我。", progress = nil, completion = "謝謝你趕來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44721] = {title = "黑爾雅的征服行動", objective = "搜索蔑潮港，尋找黑爾雅部隊的行蹤。", description = "如果黑爾雅在準備進攻破碎群島，我們必須有所防範。\n\n前往蔑潮港偵察她的部隊。我們來看看黑爾雅是否愚蠢到想來對付我。", progress = nil, completion = "看來不得不出手了…", rewards = "您會學到：\n\n黑爾拉亞世界任務\n\n您還會收到：\n\n吞霧捕魂者"}
MultiLanguageQuestData['tw'][44722] = {title = "幻滅的背叛者", objective = "在永月露臺和西爾格林碰面。", description = "城裡的氣氛沒什麼改善，不過我們或許能利用這一點。\n\n西爾格林要你去露臺找他。看來艾莉珊德的手下也因為她的瘋狂而紛紛逃走。\n\n有個反叛者獲得晉升，並且想幫助我們。\n\n好好接待這個人，<name>。我們需要所有盟友，才能度過這段黑暗的時刻。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44723] = {title = "更多跟我一樣的人", objective = "對暮衛征服者使用暮色百合符印，以找出5個逃兵。", description = "你好，外來者。\n\n我是薇可朵。我是艾莉珊德的手下，幫她維持城內的安寧。為了更多人的利益，我曾甘願跟惡魔並肩作戰，也忍受過更糟的事。\n\n弦月旅店的那場大屠殺，證明了夜裔的福祉已經不再是她的目標。她只想到她自己。\n\n還有其他人的想法跟我一樣，他們只需要明白還有別的選擇。\n\n我們都知道暮色百合。讓艾斯特瓦港的守衛看看這個符印。那些人全都見識過艾莉珊德的冷血殘酷。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔的夜裔錢幣"}
MultiLanguageQuestData['tw'][44724] = {title = "失蹤的居民", objective = "在艾斯特瓦港從惡魔身上取得一個燃燒軍團通報器。", description = "我們的新朋友帶來讓人不安的消息。\n\n她說看到大批居民被鍊起來拖往喚星者居所。他們的目的地似乎是艾斯特瓦港。\n\n被帶往那裡的居民，從沒有人回來過。更糟的是，那個地區現在出現大批的惡魔。\n\n我需要你找出那些人的下落。潛入港口，收集你能找到的情報。\n\n從燃燒軍團那些敗類開始找起，或許能從它們的屍體上發現進一步的線索。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44725] = {title = "充當人質", objective = "前往艾斯特瓦港並混進俘虜之中，一起被帶到魔魂堡。", description = "我們的同胞被當成獻給燃燒軍團的祭品！\n\n我們得攔截運送的船隻，才能終止這場交易。朋友，恐怕需要你假扮成俘虜。\n\n在你提出疑慮之前，我希望你多一點信心。\n\n我們會搭乘德林的其中一艘船尾隨你們，一旦發現他們的目的地，就救你出來。\n\n前往港口找一群俘虜，混入他們當中。讓他們把你帶走。\n\n我們會緊跟在後。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44726] = {title = "靈魂交易", objective = "在魔魂前線殺死亞戈斯。", description = "在你找出並殺掉掌管這個營地的惡魔時，我們會守在這裡。\n\n殺死亞戈斯並不能阻止這個人口走私行動，不過可以暫時拖延他們，直到我們想出幫助這些人的方法。\n\n快去吧，他就在這個山脊的頂端。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n斬魂者印記"}
MultiLanguageQuestData['tw'][44727] = {title = "走私成功！", objective = "在魔魂前線釋放瑪莉貝斯和5個俘虜。", description = "請救我離開這裡！\n\n雖然金屬條已經脆化了，但我實在太虛弱…\n\n其他人！還有好多人！請幫幫我們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44729] = {title = "勇氣試煉：歐丁的眷顧", objective = "在勇氣試煉團隊副本中獲得歐丁的眷顧。", description = "對付那狡猾巫女的時刻到了。我猜想你應該最有資格給她最後一擊，但我還是要親手確認看看。\n\n到英靈殿來找我，我們來測試一下你的意志有多堅強。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n泰坦恩賜"}
