MultiLanguageQuestData['tw'][44785] = {title = "下午茶會", objective = "找到艾比‧路易斯。", description = "我…我很抱歉。我…沒辦法…\n\n\n<你聽到身後的腳步聲。>\n\n\n艾…艾比？你怎麼…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "小象鼻啃滋龍先生史椎市長您會收到：\n\n"}
