MultiLanguageQuestData['tw'][44949] = {title = "人類的氣味", objective = "帶你的雪羽小龍隼到暴風城的鑲金玫瑰。", description = "<你發現雪羽小龍隼只要附近有人類就會顫抖。看起來是嚇壞了。或許帶牠到人類密集的地方，可以讓牠習慣人類的氣味。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44950] = {title = "狩獵訓練：北地猛鴞", objective = "派雪羽小龍隼在高嶺擊敗3隻北地猛鴞。<你的雪羽小龍隼在你靠近其他動物時就開始激動，看到高嶺的北地猛鴞時尤其如此。有猛鴞在附近時小龍隼就會豎起身上的羽毛，嘎嘎大叫。看來這是牠的掠食本能。> \n\n<看來你得帶龍隼出去狩獵了。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的雪羽小龍隼在你靠近其他動物時就開始激動，看到高嶺的北地猛鴞時尤其如此。有猛鴞在附近時小龍隼就會豎起身上的羽毛，嘎嘎大叫。看來這是牠的掠食本能。> \n\n<看來你得帶龍隼出去狩獵了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44952] = {title = "玄鴉堡：深淵之珍", objective = "前往黑石深淵並取得貝爾加之心、洛考爾之心、伊森迪奧斯的精華和瑪格姆斯的精華。取得以上四樣東西以後，到黑石深淵底部、熔火之心入口附近的黑熔爐將它們合而為一，並將合成的這顆黑石紅晶交給永望鎮的維撒克。", description = "歡迎來到永望鎮。不知道你對新武器有沒有興趣呢？\n\n你也知道，我在這間店裡不光是想賣能讓敵人死無全屍的武器，我也想賣稀有的珠寶。\n\n或許我們能想辦法拿到我一直很想要的珠寶。我有一些很棒的鍛造設計圖，你可能會有興趣，這就當作是給你的報酬。\n\n現在，我們來聊聊細節…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設計圖：黎明之鋒"}
MultiLanguageQuestData['tw'][44953] = {title = "高嶺的盟友", objective = "帶著你的雪羽小龍隼在高嶺完成5個世界任務。<在你靠近雷霆圖騰時，你的雪羽小龍隼發出一聲低沉的吼叫。> \n\n<高嶺部族毫不遲疑地開始驅逐小龍隼。對小龍隼而言，高嶺部族是個威脅，牠發出低吼聲可能是為了要保護你。>\n\n<讓你的龍隼明白，你們和高嶺部族可以和平共處。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<在你靠近雷霆圖騰時，你的雪羽小龍隼發出一聲低沉的吼叫。> \n\n<高嶺部族毫不遲疑地開始驅逐小龍隼。對小龍隼而言，高嶺部族是個威脅，牠發出低吼聲可能是為了要保護你。>\n\n<讓你的龍隼明白，你們和高嶺部族可以和平共處。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44954] = {title = "與雪羽團隊合作", objective = "派你的雪羽小龍隼在破碎群島贏得3個寵物對戰世界任務。<你的雪羽小龍隼看著你，發出叫聲。看樣子牠想跟你並肩合作！>\n\n<為了觀摩學習，戰鬥時請務必帶著小龍隼一起出戰，將其安排為第一個進入戰鬥的寵物，並確保牠不會在戰鬥中死亡。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的雪羽小龍隼看著你，發出叫聲。看樣子牠想跟你並肩合作！>\n\n<為了觀摩學習，戰鬥時請務必帶著小龍隼一起出戰，將其安排為第一個進入戰鬥的寵物，並確保牠不會在戰鬥中死亡。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44955] = {title = "沙亞蘭的訪客", objective = "在沙亞蘭外與陌生人碰面。", description = "你在城裡的時候，有個人來到了沙亞蘭。她專程來找你。\n\n我不認得她的臉，也對她的聲音沒印象，不過她似乎值得信賴而且很誠懇。\n\n她就在洞穴外頭。去跟她見面，了解她來這裡的目的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n飛天沙漏"}
MultiLanguageQuestData['tw'][44956] = {title = "致命獵物", objective = "帶著你的雪羽小龍隼完成1個稀有精英世界任務。", description = "<在最近幾場寵物對戰中，你的雪羽小龍隼似乎對你的戰鬥技能更感興趣了。如果能觀看你和強敵戰鬥的話，或許牠能學到一些新的招式。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44957] = {title = "狩獵訓練：刺尾海狸", objective = "派雪羽小龍隼在高嶺擊敗3隻刺尾海狸。<你的雪羽小龍隼最近對於跟隨海狸的蹤跡很感興趣。牠一定是找到新的獵物種類了。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的雪羽小龍隼最近對於跟隨海狸的蹤跡很感興趣。牠一定是找到新的獵物種類了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44958] = {title = "不友善的陣營", objective = "帶著你的雪羽小龍隼完成3個PvP世界任務。<最近遇到另一個陣營的成員時，你的雪羽小龍隼會直接走上前接近對方，一點都不害怕。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<最近遇到另一個陣營的成員時，你的雪羽小龍隼會直接走上前接近對方，一點都不害怕。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44959] = {title = "跟雪羽小龍隼培養感情", objective = "從達拉然的蘇珊娜‧艾維羅那裡買一個小包裹給你的雪羽小龍隼。", description = "<你的雪羽小龍隼一直翻你的背包，弄得一片混亂。每次你把牠推開，牠就對你大聲嘶叫，並且用頭撞你。或許你可以給他一個小包裹，引開牠的注意力？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n小包裹"}
MultiLanguageQuestData['tw'][44960] = {title = "狩獵訓練：泥殼海螺", objective = "派你的雪羽小龍隼和2隻飛行寵物在高嶺擊敗3隻泥殼海螺。<你的雪羽小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕高嶺的海螺很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的雪羽小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕高嶺的海螺很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44961] = {title = "團隊訓練：納拉薩斯", objective = "帶著你的雪羽小龍隼在高嶺的奈薩里奧巢穴擊敗納拉薩斯。", description = "<雖然打贏了，但是你的雪羽小龍隼在先前幾場戰鬥中，對牠的夥伴又叫又啄。讓牠明白什麼叫做團隊合作應該會有所幫助。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44962] = {title = "狩獵訓練：珊背招潮蟹", objective = "派你的雪羽小龍隼和2隻元素生物在高嶺擊敗3隻珊背招潮蟹。<你的雪羽小龍隼似乎對你寵物園中的元素生物特別有戒心。牠們需要學習該如何合作才能和睦相處。一起獵殺牠最近喜歡的新獵物或許能改善這一點。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的雪羽小龍隼似乎對你寵物園中的元素生物特別有戒心。牠們需要學習該如何合作才能和睦相處。一起獵殺牠最近喜歡的新獵物或許能改善這一點。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44964] = {title = "就放在這裡", objective = "前往蘇拉瑪爾的泰洛薩蘭、克爾巴洛和艾洛爾善，在這三個地方的能量來源放置能量干擾器。", description = "薇兒塔有個解除聖所能量屏障的計畫。\n\n在整個蘇拉瑪爾有許多關鍵的幽暗地道所在，正在為屏障提供能量。她做的這些能量干擾器，一啟動就能從遠端截斷各處的能量連結，讓屏障失效。\n\n帶著這些裝置，將它們裝在地脈上。然後回到這裡，準備對聖所發動奇襲。", progress = nil, completion = "準備工作就快完成了。歐庫雷斯很快就能把我們傳送過去。", rewards = "您會收到：\n\n力量不足的調節水晶"}
MultiLanguageQuestData['tw'][44967] = {title = "團隊訓練：厄索克", objective = "帶著你的雪羽小龍隼在翡翠夢境擊敗厄索克。", description = "<你的雪羽小龍隼在感到威脅的時候還是會跟其他的戰寵打架。牠得學會在面對壓力時處之泰然，就算眼前是巨大的怪獸也一樣。讓牠見識一下如何利用團隊合作來擊敗巨大的野獸，或許會有所幫助。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][44968] = {title = "雪羽團隊大戰", objective = "派你的雪羽小龍隼和2個不死生物贏得3個寵物對戰世界任務。<看樣子你的雪羽小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<看樣子你的雪羽小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44969] = {title = "雪羽家族團聚", objective = "讓雪羽小龍隼返回高嶺的迷霧海岸。", description = "<你的雪羽小龍隼最近一直無精打采的。牠似乎很憂鬱。或許讓牠返回家鄉的時候到了？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n雪羽狩獵者"}
