MultiLanguageQuestData['tw'][44981] = {title = "不仁慈的陣營", objective = "帶著你的恐喙小龍隼完成3個PvP世界任務。<最近遇到另一個陣營的成員時，你的恐喙小龍隼會向他們發出叫聲討食物吃。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<最近遇到另一個陣營的成員時，你的恐喙小龍隼會向他們發出叫聲討食物吃。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44982] = {title = "跟恐喙小龍隼培養感情", objective = "從達拉然的發條助手那裡買一副假牙給你的恐喙小龍隼。", description = "<你的恐喙小龍隼對你豎起全身羽毛，發出帶有爭霸意味的吼叫。看到你並沒有因害怕而退縮，牠似乎很不滿意。牠可能會想要裝扮成成年龍隼，再試一次。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n假牙"}
MultiLanguageQuestData['tw'][44983] = {title = "狩獵訓練：黃金雛鷹", objective = "派你的恐喙小龍隼和2隻飛行寵物在斯鐸海姆擊敗3隻黃金雛鷹。<你的恐喙小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕斯鐸海姆的鷹類很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的恐喙小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕斯鐸海姆的鷹類很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44984] = {title = "團隊訓練：芬里爾", objective = "帶著你的恐喙小龍隼在斯鐸海姆的英靈殿擊敗芬里爾。", description = "<你的恐喙小龍隼先前幾場戰鬥中，會怯懦地避開其他飛行生物。讓牠明白什麼叫做團隊合作應該會有所幫助。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44985] = {title = "狩獵訓練：雷擊海狸", objective = "派你的恐喙小龍隼和2隻機械寵物在斯鐸海姆擊敗3隻雷擊海狸。<每次你們經過聲音響亮的機械，你的恐喙小龍隼就會用充滿戒備地眼神盯著看。你開始猜想牠是不是曾經跟某個機械寵物有什麼過節。牠們需要學習該如何合作才能和睦相處。一起獵殺牠最近喜歡的新獵物或許能改善這一點。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<每次你們經過聲音響亮的機械，你的恐喙小龍隼就會用充滿戒備地眼神盯著看。你開始猜想牠是不是曾經跟某個機械寵物有什麼過節。牠們需要學習該如何合作才能和睦相處。一起獵殺牠最近喜歡的新獵物或許能改善這一點。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44986] = {title = "團隊訓練：克羅索斯", objective = "帶著你的恐喙小龍隼在暗夜堡擊敗克羅索斯。", description = "<你的恐喙小龍隼在附近有巨大生物時都會驚恐地嘎嘎大叫，就算這些生物很友善也一樣。牠得學會在壓力之下保持冷靜，就算眼前是體型好幾倍大的生物也一樣。讓牠見識一下如何利用團隊合作來擊敗像山一樣巨大的怪物，或許會有所幫助。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][44987] = {title = "恐喙團隊大戰", objective = "派你的恐喙小龍隼和2隻人形生物贏得3個寵物對戰世界任務。<看樣子你的恐喙小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<看樣子你的恐喙小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][44988] = {title = "恐喙家族團聚", objective = "讓恐喙小龍隼返回斯鐸海姆的海鷗岩。", description = "<你的恐喙小龍隼不斷發出微弱又憂鬱的叫聲。牠似乎很憂鬱。或許讓牠返回家鄉的時候到了？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n豔麗恐喙"}
