MultiLanguageQuestData['tw'][45004] = {title = "狩獵訓練：皇羽幼雛", objective = "派你的嗜血小龍隼在艾蘇納擊敗3隻皇羽幼雛。<你的嗜血小龍隼興奮地拍打著翅膀，還用牠的喙摩擦著艾蘇納的樹幹。牠一定是找到新的獵物種類了。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的嗜血小龍隼興奮地拍打著翅膀，還用牠的喙摩擦著艾蘇納的樹幹。牠一定是找到新的獵物種類了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45005] = {title = "不合作的陣營", objective = "帶著你的銳爪小龍隼完成3個PvP世界任務。<最近遇到另一個陣營的成員時，你的銳爪小龍隼會想要跟他們的寵物一起玩。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<最近遇到另一個陣營的成員時，你的銳爪小龍隼會想要跟他們的寵物一起玩。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45006] = {title = "不討喜的陣營", objective = "帶著你的嗜血小龍隼完成3個PvP世界任務。<最近遇到另一個陣營的成員時，你的嗜血小龍隼會好奇地對著他們的背包嗅個不停。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<最近遇到另一個陣營的成員時，你的嗜血小龍隼會好奇地對著他們的背包嗅個不停。牠似乎不明白對方是敵人。最好加以教導，以防萬一。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45007] = {title = "跟銳爪小龍隼培養感情", objective = "從達拉然的梅爾‧林森那裡買一根骯髒的湯匙給你的銳爪小龍隼。", description = "<每次你進入旅店，你的銳爪小龍隼就會本能地翻倒鍋碗瓢盆，弄得一團糟。牠似乎很愛打翻還沒收起的餐盤，尤其是沒有洗過的。要是牠能有一支自己的餐具，或許就能改善這種行為。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n骯髒的湯匙"}
MultiLanguageQuestData['tw'][45008] = {title = "跟嗜血小龍隼培養感情", objective = "從達拉然的依利絲‧櫻草那裡買一朵紫色花卉給你的嗜血小龍隼。", description = "<看來你的嗜血小龍隼很愛在花叢中打滾。你猜想這種生物之所以熱愛開花植物，大概是因為這在從前能幫助牠們找到食用的果實。送牠一朵花，牠應該會感到非常開心！>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紫色花卉"}
MultiLanguageQuestData['tw'][45009] = {title = "狩獵訓練：赤褐環尾浣熊", objective = "派你的銳爪小龍隼和2隻飛行寵物在維爾薩拉擊敗3隻赤褐環尾浣熊。<你的銳爪小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕維爾薩拉的浣熊很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的銳爪小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕維爾薩拉的浣熊很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45010] = {title = "狩獵訓練：年幼鑿背蟹", objective = "派你的嗜血小龍隼和2隻飛行寵物在艾蘇納擊敗3隻年幼鑿背蟹。<你的嗜血小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕艾蘇納的蟹類很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的嗜血小龍隼已經和其他飛行寵物變成朋友了。牠們似乎對獵捕艾蘇納的蟹類很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45011] = {title = "團隊訓練：德瑞薩隆", objective = "帶著你的銳爪小龍隼在維爾薩拉的暗心灌木林擊敗德瑞薩隆。", description = "<你的銳爪小龍隼似乎對你的其他戰寵不怎麼感興趣，在戰鬥中對牠們視而不見。讓牠明白什麼叫做團隊合作應該會有所幫助。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45012] = {title = "團隊訓練：巨鱗蛇", objective = "帶著你的嗜血小龍隼在艾蘇納的艾薩拉之眼擊敗巨鱗蛇。", description = "<雖然打贏了，但是你的嗜血小龍隼卻在戰鬥中的關鍵時刻讓你的其他寵物無法專心。讓牠明白什麼叫做團隊合作應該會有所幫助。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45013] = {title = "狩獵訓練：谷地振翼蛾", objective = "派你的銳爪小龍隼和2隻水棲寵物在維爾薩拉擊敗3隻谷地振翼蛾。<你的銳爪小龍隼堅決不願靠近有水的地方，每次你涉水，牠就會一面叫一面猛抓地面。或許跟水棲生物一起合作能幫助牠減輕這種恐懼。一起獵殺牠最近喜歡的新獵物或許能改善這一點。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<你的銳爪小龍隼堅決不願靠近有水的地方，每次你涉水，牠就會一面叫一面猛抓地面。或許跟水棲生物一起合作能幫助牠減輕這種恐懼。一起獵殺牠最近喜歡的新獵物或許能改善這一點。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45014] = {title = "狩獵訓練：魔化蜘蛛", objective = "派你的嗜血小龍隼和2隻小動物在艾蘇納擊敗3隻魔化蜘蛛。<每當你回到旅店休息，你的小龍隼就會爬上家具，拒絕待在地板上。牠會從一個物品跳到另一個物品上，把東西翻倒弄得一團亂。你想到這可能是因為之前跳蚤弄得牠很不舒服。讓牠跟小動物戰寵一起獵殺新獵物，或許能幫助牠克服這分恐懼。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<每當你回到旅店休息，你的小龍隼就會爬上家具，拒絕待在地板上。牠會從一個物品跳到另一個物品上，把東西翻倒弄得一團亂。你想到這可能是因為之前跳蚤弄得牠很不舒服。讓牠跟小動物戰寵一起獵殺新獵物，或許能幫助牠克服這分恐懼。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45015] = {title = "團隊訓練：薩維斯", objective = "帶著你的銳爪小龍隼在翡翠夢境擊敗薩維斯。", description = "<你的銳爪小龍隼在你挑戰世界中的強大生物時，會躲進你的背包。牠得學會在壓力之下保持冷靜，就算眼前要面對的是最邪惡的夢魘。讓牠見識一下如何利用團隊合作來擊敗可怕的敵人，或許會有所幫助。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][45016] = {title = "團隊訓練：斯寇派隆", objective = "帶著你的嗜血小龍隼在暗夜堡擊敗斯寇派隆。", description = "<你的嗜血小龍隼會對著巨大的怪獸嚎叫，似乎一點也不擔心自己孤軍勢薄。牠需要學會什麼叫做人多力量大。讓牠見識一下如何利用團隊合作來擊敗巨大的怪獸，或許會有所幫助。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][45017] = {title = "銳爪團隊大戰", objective = "派你的銳爪小龍隼和2隻魔法生物贏得3個寵物對戰世界任務。<看樣子你的銳爪小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<看樣子你的銳爪小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45018] = {title = "嗜血團隊大戰", objective = "派你的嗜血小龍隼和2隻野獸贏得3個寵物對戰世界任務。<看樣子你的嗜血小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", description = "<看樣子你的嗜血小龍隼已做好跟你一起挑戰下一輪戰鬥的準備，好顯示牠已經學會什麼叫做團隊合作。讓牠跟不同的搭檔合作應該能測出牠的能耐。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45019] = {title = "銳爪家族團聚", objective = "讓銳爪小龍隼返回維爾薩拉的滴翠崖。", description = "<你的銳爪小龍隼最近都不吃東西。牠似乎很憂鬱。或許讓牠返回家鄉的時候到了？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n翠綠銳爪"}
MultiLanguageQuestData['tw'][45020] = {title = "嗜血家族團聚", objective = "讓嗜血小龍隼返回艾蘇納的亞魯凡儂三角洲。", description = "<你的嗜血小龍隼不願意喝水。牠似乎很憂鬱。或許讓牠返回家鄉的時候到了？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n血腥掠食者"}
MultiLanguageQuestData['tw'][45021] = {title = "答案未知", objective = "在艾蘇納境內找到裘貝卡‧破影者。", description = "你有注意到裘貝卡行為怪怪的嗎？我知道她本來就不太與人親近，但她最近好像比以前還孤僻了。\n\n我猜她還在想議會之前的領袖坎瑞薩德。裘貝卡原本堅守承諾放逐坎瑞薩德，直到燃燒軍團把她抓走當作囚犯。\n\n坎瑞薩德的命運尚不可知，但顯然這讓我們的朋友相當擔憂。她最後跟我說的話，是她感覺到坎瑞薩德出現在艾蘇納。別讓她獨自面對。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45024] = {title = "翦除秘教", objective = "前往魔火洞穴並殺死綠焰秘教的成員。", description = "坎瑞薩德的誘惑令人難以抗拒。即便他不在這個世界，仍有許多人不計代價想接近他，希望分享他的力量。\n\n法隆納這裡有一群狂熱者，千方百計想將坎瑞薩德帶回這個世界。這是我從囚犯那裡聽來的消息。\n\n我們不能讓他們得逞，<name>。找出他們的據點，盡力除掉他們，越多越好。\n\n我會繼續待在這裡，看看能不能發現他們的其他意圖。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45025] = {title = "竊取力量之源", objective = "取得5個惡魔水晶。", description = "我的囚犯很健談，<name>。他告訴我，綠焰秘教正在利用魔化能量，想將被放逐的坎瑞薩德帶回這個世界。\n\n在他們的據點中，他們為惡魔水晶充能，使其含有大量的惡魔魔法。沒有足夠的力量執行儀式，那些秘教徒就難以完成任務。\n\n偷走他們的惡魔水晶，但不要毀了它們。這麼強大的東西，總能派上用場。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45026] = {title = "消耗魔化能量", objective = "駕馭惡魔水晶的力量並在法隆納殺死惡魔以消耗其能量。", description = "放逐坎瑞薩德的法術正在衰弱，到時他就會回到我們的世界。\n\n我們必須不計一切代價，避免他跟他的力量落入燃燒軍團手中。\n\n如果我的老朋友還存在於那個惡魔體內，也許我們可以把他帶回來。\n\n你找回的水晶以魔化能量作為能量來源。我們可以用對能量飢渴的水晶將吞噬坎瑞薩德的魔法抽離。\n\n但首先，必須先耗盡水晶的力量。利用水晶殺死惡魔，就能使其中的能量枯竭。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45027] = {title = "前往破碎海岸", objective = "前往破碎海岸。", description = "坎瑞薩德思想扭曲的追隨者似乎已經在破碎海岸準備進行儀式了。\n\n我們必須盡快行動。不能讓燃燒軍團把坎瑞薩德當成武器使用。\n\n我們的侍僧已經在待命。等你準備好，就能在破碎海岸進行召喚儀式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45028] = {title = "坎瑞薩德的命運", objective = "使用惡魔水晶從坎瑞薩德身上汲取魔化能量。", description = "我能感覺到他的存在，虛空領主！坎瑞薩德就在這裡！他的追隨者已經在附近的小徑紮營，在我們說話的同時，他們已經在舉行儀式要將他帶回來了。\n\n快，拿著惡魔水晶。用它們在坎瑞薩德周圍設立法陣。\n\n如果正確放置，水晶會彼此相連，並開始吸收魔化能量。\n\n去吧，不能錯過這個機會！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
