MultiLanguageQuestData['tw'][45035] = {title = "戰爭的呼喚", objective = nil, description = "這些惡魔毫無榮譽可言！它們不敢光明正大跟我們正面對決，反而躲在路障和攻城武器後面。\n\n華爾拉亞是為了戰爭的榮耀而來，我們才不會被懦夫的戰術擊退！\n\n摧毀它們的砲台，破壞它們的屏障，英勇的華爾拉亞將讓它們見識真正的戰鬥精神！塵埃落定之時，那些惡魔將屍橫遍野…華爾拉亞將立於不敗之地！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45044] = {title = "已成絕響", objective = "把嚴重損壞的黑暗之矛帶到安戈洛環形山的苔蘚堆交給寇贊。\n\n已提供物品：\n", description = "你找到的長矛上有食人妖鍛造品的設計特徵。\n\n或許在安戈洛這裡的營地裡會有人知道詳情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
