MultiLanguageQuestData['tw'][45143] = {title = "審判將至", objective = "使用大領主的審判以斷定白銀之手新兵的能力。", description = "我們在破碎海岸的精采表現，已經引起許多聖騎士的興趣，他們有意在你的麾下作戰。他們的素質參差不齊，不過唯有你能做出評判。\n\n招募的新兵正在禮拜堂外的營地徘徊，等著你去評判。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45145] = {title = "月牙家族聖物", objective = "在闇影澤內找回月牙家族聖物。", description = "按照承諾，這是能開啟我家族鎖盒的月牙鑰匙，不過裡面沒留下什麼值錢的東西。\n\n相信不管找到什麼，你都會交給德菈絲吧？祖先的東西，不論值不值錢，都應該留在我們家族裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][45146] = {title = "符文解讀", objective = "在破碎群島從惡魔身上取得10個魔化之血。", description = "這個卷軸有些奇怪。沒受過訓練的人看來，卷軸是空白的，但當我把卷軸高舉在光線下時，就能看到符文短暫顯現。\n\n就像許多惡魔符文一樣，我必須用魔化之血才能解開用來隱藏卷軸訊息的魔法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45147] = {title = "摧毀魔石", objective = "摧毀魔石墜飾。", description = "<德菈絲瞠目結舌，卷軸從她手中掉到地上。>\n\n這不可能…符文…記載了燃燒軍團跟我祖先之間的約定。這項黑暗交易讓我的祖先在世時不會受到惡魔危害，但相對地，其靈魂將屬於燃燒軍團。\n\n這個惡魔墜飾便是約定的化身，戴上之後，便無法取下。\n\n快點，<name>。使用你的神兵武器摧毀這件受詛咒的珠寶！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45148] = {title = "誓約破壞者", objective = "前往破碎海岸並殺死誓縛者奏拉克。", description = "許多年前，我跟一個看起來跟我沒什麼兩樣的男人訂下契約。他承諾提供的保護，條件好到讓人不禁起疑，但我當時急於尋求那樣的力量。\n\n直到我用鮮血簽下契約後，驚懼領主奏拉克才表明他的身份。\n\n只要他還活著的一天，我的祖先將永遠束縛於燃燒軍團，讓我們的敵人得以支配大量身不由己的士兵。\n\n前往破碎海岸並殺死誓縛者奏拉克。他一死，便能破除他對祖先的束縛。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n受祝福的提爾雕像"}
MultiLanguageQuestData['tw'][45149] = {title = "終止月牙詛咒", objective = "摧毀魔化墜飾以釋放弦月遺跡的魔縛靈魂。", description = "我們必須窮盡所能破除祖先身上的詛咒。\n\n燃燒軍團在亡者安息的廢墟紮營，準備利用許久以前所立下的可怕約定。\n\n每一位祖先都被這個墜飾詛咒，他們的靈魂都受到惡魔主宰所束縛。墜飾拿不下來，但你證明了只要力量足夠強大，就能將它摧毀。\n\n終止荼毒祖先的詛咒，解放他們的靈魂！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45159] = {title = "立方體難題", objective = "把神秘立方體帶給達拉然的博學者達莉諾絲。\n\n已提供物品：\n", description = "<你找到了一個神秘立方體。它的設計你前所未見，不過它毫無疑問是遠古的產物。\n\n立方體的表面嵌有魔法符文。雖然目前沒有啟動，但是有必要調查這東西的特性。\n\n要是你能把它拿去達拉然交給博學者達莉諾絲，她應該能夠告訴你更多的資訊。>", progress = nil, completion = "&lt;達莉諾絲凝視著你交給她的這件文物。&gt;\n\n這個設計實在太有趣了！它讓我想到我很久以前還是學徒時所讀過的一件古玩。但這應該不可能是那東西。從來沒有人發現過這種裝置。\n\n嗯，不知道它還能不能用。只有一個辦法可以知道…", rewards = nil}
MultiLanguageQuestData['tw'][45160] = {title = "立方體脈流", objective = "從蘇拉瑪爾取得300份上古法力。", description = "要知道這個立方體的用處的話，我們就需要提供它動力。嗯，我想到一個辦法…\n\n夜裔渴望著一種你一定也知道的物質，叫做上古法力。像這樣一個遠古的文物，用上古法力應該正好。等你收集到足夠的量，我們就能試著啟動它。\n\n在蘇拉瑪爾的時候千萬小心！要是讓這個珍奇的立方體再次從歷史中消失，就太可惜了。", progress = nil, completion = "你已經收集到足夠的上古法力好注入立方體了嗎？", rewards = "您會學到：\n\n法力灌注"}
MultiLanguageQuestData['tw'][45162] = {title = "重錘落下", objective = "前往鬥陣俱樂部。", description = "你的勇士在鬥陣對決中戰勝了戰錘議會。將這個「戰利品」帶去鬥陣俱樂部當作獲勝的證明。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鬥陣金幣"}
MultiLanguageQuestData['tw'][45163] = {title = "清潔溜溜", objective = "將斷掉的掃帚柄帶回鬥陣俱樂部。", description = "你的勇士們凱旋而歸。他們說著自己如何把『清潔工』比爾「清理」了一番。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鬥陣金幣"}
MultiLanguageQuestData['tw'][45172] = {title = "開戰！", objective = "參與任一戰場並獲勝。", description = "你的勇士回來了，他們在戰場上冒險，報告中詳細描述各種奇妙的旅程以及他們戰勝死亡所完成的豐功偉業。在這種情況搖擺不定的戰局，永遠都需要更多英雄伸出援手，展現力量和榮耀。\n\n你願意響應號召嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋戰場戰利品"}
MultiLanguageQuestData['tw'][45173] = {title = "非常時期", objective = "參與任一戰場並獲勝。", description = "戰爭還在持續。跟以往一樣，我們偉大的戰場需要你。加入戰鬥，擊敗你的敵人，為你的陣營贏得榮耀。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n士兵的置物箱"}
MultiLanguageQuestData['tw'][45174] = {title = "尋找伊利丹‧怒風", objective = "在艾蘇納的伊利達瑞陣地找到『噬魂者』艾萊莉。", description = "伊利達瑞的占卜師『噬魂者』艾萊莉，尋找伊利丹的靈魂已有一段時日。她相信現在終於找到了靈魂的所在地點，需要你協助將它取回。\n\n去艾蘇納的伊利達瑞陣地，盡你所能幫助她。\n\n如果薩格拉斯真的計畫利用伊利丹的身體做為他復生的容器，那麼，讓伊利丹的靈魂回到軀體中將是阻止黑暗泰坦降臨這個世界關鍵性的一環！", progress = nil, completion = "那魯聽到我的呼喚了？有意思…\n\n很好，我們就開始著手進行吧。我們終於找到伊利丹的靈魂了，所在位置出人意料之外。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45175] = {title = "伊利達瑞的靈魂稜石", objective = "從軍團地城最後首領身上，取得5個殘留的靈魂碎片。\n\n地城難度越高，獲得殘留的靈魂碎片機率與數量就越高。", description = "唉，主人靈魂的所在地點暫時還不需要你操心，<name>。首先，我們得打造一個強到足以容納主人那無盡混沌能量的靈魂稜石。\n\n我需要你從世界各處的強大生物身上收集殘留的靈魂碎片。幫我帶回足夠的量，我就能打造一個留得住主人靈魂的稜石，至少能撐到那魯接手為止。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "虛空之繫腰索伊利達瑞遠征軟靴虛空行者腰帶伊利達瑞遠征薄靴虛空之擰鍊甲腰帶伊利達瑞遠征長靴虛空之觸束腰伊利達瑞遠征脛甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][45176] = {title = "勇氣試煉：過往與來日的暗影之王", objective = "在勇氣試煉團隊副本中擊敗黑爾雅，然後使用伊利達瑞的靈魂稜石捕捉伊利丹的靈魂。", description = "尋找主人的身體費了我們一番功夫，最後終於找到是在蘇拉瑪爾的暗夜堡。根據我們的線報，古爾丹正在對夜井做最後的準備，要利用夜井的力量迎接薩格拉斯進入伊利丹的身體。\n\n要阻止這件事的唯一辦法，就是讓伊利丹不朽的靈魂回到自己的身體中。\n\n拿著伊利達瑞的靈魂稜石進入黑爾海姆。擊敗黑爾雅，然後對伊利丹的靈魂使用稜石！完成之後再把它帶回來聖光之心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "旋魂裹手虛空行軍襯肩暗影再臨手套煉獄行軍肩墊死亡之握纏手燃炎意志披肩縛魂者護手十字軍的煉獄肩鎧您會收到：\n\n"}
MultiLanguageQuestData['tw'][45177] = {title = "暗夜堡", objective = "前往達拉然的紫羅蘭城塞把聖光之心交給卡德加。", description = "伊利丹的靈魂安全地待在聖光之心裡。把這個容器交給卡德加，然後跟他說明以下指示：\n\n在古爾丹撕裂天空將黑暗泰坦迎入這個世界之際，啟動這個容器的力量，將伊利丹的靈魂釋放回他的身體。\n\n去吧，<name>。時間不多了。黑暗儀式隨時可能開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45178] = {title = "抑制傳染病", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45179] = {title = "萬眾擁戴", objective = "在競技場戰鬥並獲勝。", description = "這封信邀請你參加艾澤拉斯史上最盛大的事件：競技場戰鬥！鬥士們能在這裡贏得榮耀，讓每個人都記得他們的名字。至少會記到下一個賽季開始為止。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n士兵的置物箱"}
MultiLanguageQuestData['tw'][45180] = {title = "戰爭之島", objective = "在艾斯蘭完成任務。", description = "你的勇士回來了，他們看起來傷痕累累，非常疲倦。當你握著他們帶回來的旌旗，心中突然感到鬥志昂揚，好像有大事就要發生。他們在報告中提到一個名為艾斯蘭的島嶼，有許多英雄在那裡長年爭鬥，戰況搖擺不定。每當有一方快要獲得勝利，另一方立刻奮勇突擊，奪回優勢。\n\n艾斯蘭需要你的幫助。你願意響應號召嗎？", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45182] = {title = "冰霜：扭曲的雙胞胎弟弟", objective = "在達拉然的戲法旅舍與卡拉孟‧法哲理碰面。", description = "我的老朋友卡拉孟‧法哲理要求我幫忙找出他的弟弟瑞斯特。卡拉孟擔心瑞斯特正在接觸黑暗力量，想要阻止他。\n\n瑞斯特原本在祈倫托接受訓練，但他對力量的渴求促使他開始鑽研死靈禁術。後來被人發現了，從此被祈倫托除名。\n\n去戲法旅舍找卡拉孟，看你能否助他一臂之力。\n\n您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45185] = {title = "來自暗影的訊息", objective = "搜索戲法旅舍上層的房間，尋找雷斯特‧法哲理下落的線索。", description = "我知道我弟弟誤入歧途，但他恐怕已經落入難以想像的邪惡深淵中。他最近開始跟混入達拉然的黑暗教徒私下碰面。\n\n我來到這裡努力說服他不要一錯再錯，但他依然不為所動。而現在，他人卻不見了。\n\n我最後一次見到雷斯特，當時他是待在樓上的房間裡。我在那裡找不到任何線索，但你可能會有所發現。", progress = "你有發現什麼嗎？", completion = "一封信？某個教徒寫的？\n\n這很可能正是我們需要的線索！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45187] = {title = "城底區的秘密", objective = "詢問城底區居民，打聽雷斯特‧法哲理的下落。", description = "所以我弟弟不告而別，就是為了跟這些教徒一起進行儀式？這解釋了他離開的原因，但我們仍不知道他去了哪裡…\n\n等等！這封信提到有「虛空之誓」的教徒在城底區尋找施法材料。要是我們動作快點，說不定還找得到他們！", progress = "有任何線索嗎，<name>？", completion = "呃…這鐵定有什麼…含意。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45188] = {title = "議會的智慧", objective = "將虛空之誓宣言帶到達拉然的紫羅蘭城塞給大法師卡連恩。", description = "抱歉，<name>，我對這東西毫無頭緒。解謎一向不是我的拿手絕活。\n\n我們應該把教徒寫的東西交給大法師。說不定他能夠看出什麼。", progress = nil, completion = "這是什麼，教徒宣言？\n\n看來，雷斯特是真的走上一條黑暗的邪道了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45190] = {title = "最薄弱的地方", objective = "在破碎海岸的魔裂谷地與卡拉孟‧法哲理碰面。", description = "雖然我從未聽說過這個「虛空之誓」教派，但從這個宣言看來，鐵定也不是什麼好東西。\n\n我確實有些推論。宣言上寫著「外層最薄的地方」。我猜想這是指艾澤拉斯和扭曲虛空之間的屏障最薄弱的地方：薩格拉斯之墓。\n\n我們的部隊在破碎海岸設立據點，這對雷斯特和他的教徒盟友來說，正是潛入陵墓的好時機。建議你趕緊去阻止他們。", progress = nil, completion = "我弟弟在這裡！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45192] = {title = "撕裂符文", objective = "通過魔裂谷地的屏障，面對雷斯特‧法哲理。", description = "我弟弟和那些教徒正在洞穴的另一端進行某種儀式。我嘗試介入，但我弟弟卻設下了魔法屏障，阻擋我的去路。\n\n要是你能找出通過屏障的方法，說不定我們就還來得及阻止他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45193] = {title = "慢了一步", objective = "回到達拉然的紫羅蘭城塞找卡德加。", description = "看來我們追不到雷斯特了，但至少他和那些教徒的威脅已經大幅降低。\n\n我們應該回去找祈倫托，他們或許能幫助我們計劃下一步該怎麼做。", progress = nil, completion = "雷斯特逃走了？真不幸。\n\n不過，得知虛空之誓的教徒已不再潛伏於達拉然，好歹讓人鬆了一口氣。這都要感謝你的協助。\n\n祈倫托會馬上開始研究，如何在扭曲虛空找到雷斯特。等我們想出能找到他的辦法後，我會派人去找你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45203] = {title = "遺跡之戰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45207] = {title = "夜裔學徒", objective = "在緋紅灌木林跟秘法師萊恩娜碰面。", description = "如果你不介意多走幾步路，我很樂意向你介紹我的新學徒。她現在正在戰場上，監視效忠燃燒軍團的魔裔反抗軍營地。\n\n身為首位加入提里斯護法的夜裔，她一定急著證明自己的能力！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45209] = {title = "占卜之眼", objective = "在啟示平台調查4個暮衛占卜寶珠。", description = "一直以來，黎利斯會定期用魔法從暗夜堡向我們傳遞訊息，直到最近才突然停止。她一直很小心地隱藏這些訊息，只有最機靈的占卜者才有可能發現。\n\n不可能從宮中攔截訊息…夜井的干擾太強…\n\n一定是啟示平台！暮衛一定在那裡設置了監聽站。\n\n檢查占卜寶珠，尋找黎利斯訊息的痕跡。我們必須知道她想告訴我們什麼！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n超載的占卜寶珠"}
MultiLanguageQuestData['tw'][45238] = {title = "重返卡拉贊：立方體焦點", objective = "在卡拉贊內從法力吞噬者身上取得魔力法器", description = "可惡！看來用上古法力沒效。我需要從頭思考一遍，要集中注意並且…\n\n慢著，我想到了！就是集中！要啟動這個立方體，就得用魔力法器集中上古法力的能量。\n\n我聽說在卡拉贊有一隻法力龍鰻，能集中法力能量。那或許正是我們所需要的！\n\n不過你得當心，根據我收到的情報，那隻龍鰻超級大隻！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45239] = {title = "立方體聚合", objective = "啟動神秘立方體", description = "成功了！立方體的魔法恢復了！我等不及要目睹它的效果了！\n\n既然是你負責跑腿，也該讓你親自啟動它。要試試看嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n記憶立方體"}
MultiLanguageQuestData['tw'][45240] = {title = "做好準備", objective = "穿過大領主達瑞安‧莫格萊尼附近的死亡之門，再與米奈娃‧鴉愁碰面。", description = "死亡領主，我們找到一個很重要，而且具有強大力量的傳家寶…霜牙的韁繩，現在就在冰冠城塞！我們必須去拿回來，不能讓韁繩落入其他人手中。\n\n你想親自取回韁繩嗎？我已經先派米奈娃‧鴉愁去偵察了。你見過她，對吧？她的能力令人印象深刻，如果你願意指導她，一定能變得更強。\n\n我幫你開死亡之門，去見見她吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45243] = {title = "乘著丹密爾的雙翼", objective = "騎著丹密爾前往破碎海岸。", description = "時機已到，$p。我們的軍隊有了這些龍群，便能準備襲擊破碎海岸。一大群惡魔出現在我們其中一個營地附近，數量之多，我們的任何盟友都無法應付。\n\n有誰比那些不畏懼死亡、擁有大型秘密武器的人更適合擊敗惡魔呢？\n\n乘上丹密爾吧。我們在那裡碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45251] = {title = "有備無患", objective = "在破碎海岸與埃薩碰面。", description = "傀儡生成裝置？真是有創意的解決方案！\n\n也許我們可以引導卡斯拉納提爾的力量，卻不需要放了他。不過在我們嘗試之前，我想再加一層防護，以防萬一。我不會讓任何人說我在找藉口！\n\n準備好了就到破碎海岸與我會合！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45260] = {title = "按部就班", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "外來者，感謝你前來。很高興再次見到你。\n\n城裡有狀況需要你協助，不過首先…\n\n我們來談談希望。\n\n<薩莉瑟拉指著奧肯多爾。>\n\n奧肯多爾果實能讓我的同胞從夜井中解放。然而，果實成熟的速度有限。要讓所有人都得到救贖，需要時間。\n\n我想請你在果實成熟時幫忙分發。請拿著這個，你可以將果實送給任何人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45261] = {title = "繼續提供解藥", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "在弦月旅店發生那些事後，這裡的難民靠奧肯多爾果實來永遠擺脫夜井的需求變得更迫切了。\n\n幸好，這棵樹又結了許多果實。我想再次請求你，把這顆果實拿給這裡的一位沙亞蘭居民。\n\n等你完成後，我們再進一步討論這座城市的發展。西爾格林報告說亞魯艾兒是很棒的學生，他們兩人正在繼續疏散居民。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45262] = {title = "來自黎利斯的訊息", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "奧肯多爾再度結果了，結得真是時候。黎利斯送了消息來，她似乎找到關於凡席爾的線索了。希望我們早快找到他。他比我們更值得擁有這項禮物。\n\n在我解讀黎利斯訊息內容的時候，麻煩你把果實交給沙亞蘭這裡的其他居民。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45263] = {title = "會議前的點心", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "凡席爾在這裡，讓大家的士氣振奮不少。雖然有些人會想念城市，但我敢說，他們已經開始愛上這全新的自由。\n\n我一定會讓他們重返城市。\n\n你和我需要出席一場重要的會議。在我們去之前，先分發一些奧肯多爾果實吧。\n\n我要大家知道，雖然我必須暫時離開，但我沒有遺棄他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45265] = {title = "餵飽反抗軍", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "每天都有更多的夜裔逃離蘇拉瑪爾來加入我們。\n\n我們的軍隊日益龐大，再加上像你這樣的偉大英雄，還有部落與聯盟的軍隊，我們的勝利指日可待。\n\n幫我分發更多的奧肯多爾果實，每一顆都代表著一個從夜井中解放的嶄新人生！\n\n分發完之後，我們該來談談如何在攻城行動中協助盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45266] = {title = "聯合戰線", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "我們的戰士都拿到武器了，士氣非常高昂，就連聯盟與部落的精靈也都停止爭吵。\n\n我們幾乎做好攻擊城市的準備。\n\n把本週的果實分發出去，然後準備進攻。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45267] = {title = "進攻之前", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "我在暗夜堡做了大半輩子的研究…\n\n沒想到竟然會有要攻打暗夜堡的一天。\n\n時間不等人。戰爭很快就會開始。\n\n拜託你，照往例再給別的難民奧肯多爾果實吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45268] = {title = "諫言者與秘法師", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "由艾莉珊德所指派的新任首席秘法師，叫做…安妲麗絲。要是她就像我所聽說的一樣危險，那黎利斯恐怕凶多吉少了。\n\n抱歉，我不該有這種念頭。只是我剛剛收到令人不安的消息。\n\n幫我分送這批剛採收的奧肯多爾果實，我們再來討論這件事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45269] = {title = "自由的滋味", objective = "在沙亞蘭餵蘇拉瑪爾難民吃奧肯多爾果實。", description = "我們已經盡可能做好準備。等薇兒塔的計畫一啟動，我們就能攻擊秩序聖所，了結安妲麗絲。她一定想不到我們會訓練凋萎者抵抗魔能，傲慢將會導致她的毀滅。\n\n來吧，我們最後再去分發一次果實。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45271] = {title = "起義", objective = "在沙亞蘭與首席秘法師薩莉瑟拉交談。", description = "首席秘法師薩莉瑟拉收到關於夜落反抗軍的壞消息，需要你的協助。\n\n到蘇拉瑪爾的沙亞蘭去跟她碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45272] = {title = "起義：失蹤的居民", objective = "在沙亞蘭與首席秘法師薩莉瑟拉交談。", description = "首席秘法師薩莉瑟拉提出了請求，要你幫忙尋找她失蹤的同胞。\n\n她從一位意想不到的盟友那裡得到了線索。\n\n到蘇拉瑪爾的沙亞蘭去跟她碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45277] = {title = "起義：殘月", objective = "在沙亞蘭與首席秘法師薩莉瑟拉交談。", description = "首席秘法師薩莉瑟拉傳訊說：黎利斯那裡有消息傳來。我們需要你的協助。\n\n到蘇拉瑪爾的沙亞蘭去，看能幫上什麼忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
