MultiLanguageQuestData['tw'][45312] = {title = "把肉糰打得團團轉", objective = "將毛髮帶去鬥陣俱樂部。", description = "你的勇士們帶了一撮沾血、糾纏而且很臭的毛髮回來。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者： 肉糰"}
MultiLanguageQuestData['tw'][45316] = {title = "鞏固蘇拉瑪爾", objective = "在蘇拉瑪爾完成10個世界任務。", description = "艾莉珊德的計畫造成了反效果。她以為拿弦月旅店殺雞儆猴就能瓦解反抗軍。\n\n結果卻點燃夏多雷的怒火，比我親自激勵都還有效。\n\n我們必須繼續在蘇拉瑪爾的每一個角落對抗艾莉珊德和燃燒軍團。\n\n讓人民知道希望猶在，還有英雄願意為他們而戰！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45317] = {title = "全面出擊", objective = "完成5個職業大廳任務。", description = "我們大致完成了進攻城市的準備。你的功勞不可抹滅，<name>。\n\n不過別忘了，你同時也是個<class>t。你的部隊仰賴你指揮。獨自一人是無法對抗燃燒軍團的。\n\n繼續盡你的義務。指引艾澤拉斯的<class>，最後我們一定會獲得勝利的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45329] = {title = "行動：傳送門", objective = "關閉3個燃燒軍團傳送門。", description = "這是大規模入侵，但對於斬魔者來說絕對不算什麼。該讓那些武器派上用場了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45330] = {title = "偵察團", objective = "找到絲瑟諾女士和10個伊利達瑞斥候。", description = "要找到失蹤的斥候和絲瑟諾女士可能並不容易。我懷疑某一方並不想被找到。\n\n盡你所能，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45331] = {title = "返回亞榭洛", objective = "回到亞榭洛找大領主達瑞安‧莫格萊尼。", description = "距離我們上次見面你又成長了不少，<name>。既然現在我們有了韁繩，就來看看莫格萊尼計畫要如何使用。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][45342] = {title = "實施醫療", objective = "對染病的軍團之殞鬥士使用疫病抑制劑。", description = "不幸的是，許多你的盟友已經在被惡魔腐化的海岸上戰鬥。\n\n許多人受疫病所苦，這樣永遠無法在戰場上取得優勢。\n\n帶著抑制劑，治好你的盟友。\n\n我跟羅蘭會負責處理這裡的傷患。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45343] = {title = "奇怪的疫病", objective = "在高嶺找到艾薩萊斯特。", description = "我收到消息，高嶺地區的一處海岸爆發了奇怪的疫病。\n\n當地部族因為害怕染上這種目前無藥可醫的疾病，已經撤離那個地方。\n\n我們的一名成員在那個地方旅行時，她的同伴也生病了。她向牧道會尋求協助。找到她，大祭司。盡你所能阻止疫病的傳播。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45344] = {title = "採集病原體樣本", objective = "從高嶺西部沿岸的毒氣魔池取得被汙染的樣本。", description = "如你所見，我的同伴病得很重。\n\n他一定得了跟牛頭人一樣的病。他們整個營地的人都病死了！\n\n一定跟惡魔脫不了關係，但所有已知的治療方法都無效。\n\n我不遺餘力地想找出解藥，但羅蘭可能時日不多了。\n\n我真的很需要協助。如果能取得一些病原體樣本，應該可以加快進度。\n\n記得不要直接接觸感染源。漂浮術應該很有用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45345] = {title = "淘氣的妖精", objective = "對碳蹄丘行者使用驅散魔法讓淘氣的妖精現身，並取得其身上的閃亮粉塵。", description = "這可是鮮為人知的秘密，妖精用於施展不同伎倆的粉塵其實具有恢復效果。\n\n有些鍊金師對這種說法抱持懷疑，不過，他們會駁斥這種說法，只是因為他們沒辦法親手取得過這種罕見材料。\n\n妖精會用幻覺隱藏自己，避免被察覺。\n\n附近的山羊發出奇怪的閃亮光芒，很可能是妖精所偽裝的。\n\n驅散它們身上的魔法，讓它們現身。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45346] = {title = "蹣跚漫步的樣本", objective = "對易毀屍骸使用束縛不死生物，以便用屍骸收藏匣取得樣本。", description = "魔化疫病共有三個階段。\n\n一開始的症狀是持續不斷地咳痰。\n\n接著皮膚會變成病態的深綠色。\n\n第三階段是完全變形。受害者會變成一具喪失自我的走屍。這是我認為能取得最多疫病資訊的階段。\n\n我有一個裝置，能安全地保存樣本，但在收集樣本前，必須先將目標銬住。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45347] = {title = "製作解藥", objective = "在未化驗的藥劑裡灌注魔法，再對羅蘭‧阿博納斯使用。", description = "我使用你為我收集的東西做出了解藥，希望有效。現在只缺強而有力的魔法，我希望你願意提供。\n\n藥劑在我的鍊金工作臺上。\n\n請快一點，<name>，羅蘭越來越虛弱了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45348] = {title = "妥善保管", objective = "把疫病抑制劑帶到虛空之光神殿給阿隆索斯‧法奧。", description = "看起來，神聖與暗影魔法的微妙平衡是治療此疫病的關鍵。顯然，解藥需要再做一些調整，減少不必要的副作用，例如死亡。\n\n在此同時，請把抑制劑帶回虛空之光神殿，安全保存。我會努力研究，找出疫病的來源。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][45349] = {title = "前往破碎海岸", objective = "前往破碎海岸。", description = "在破碎海岸戰鬥的人傳來消息。疫病的來源似乎確定在西部沿岸的一座小島。\n\n許多盟友都已經染病。我們必須趕緊採取行動，確保疫病不會擴散開來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45350] = {title = "對抗疫病", objective = "殺死『腐化者』奧祖客並摧毀他的魔能擴散水晶以遏止疫病。", description = "我一路追查疫病的源頭，來到這處海岸。燃燒軍團使用魔能擴散水晶來散佈感染的魔化腐質，讓任何接觸到的人都得病。\n\n除掉『腐化者』奧祖客及他的魔能擴散水晶，以便防治疫病。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45354] = {title = "消除稜碟能量", objective = "完成試煉，消除稜碟多餘的能量。", description = "這些稜碟彼此的距離太近了，不斷散發能量！我們最好把稜碟帶走，以免它們在這神聖的地方造成災難。\n\n我會把稜碟送到一個能夠控制能量，不會發生爆炸的地方。這個地方就是永恆之眼。\n\n我們可以在那裡完成安東尼達斯沒做完的工作。準備好出發就跟我說一聲吧。", progress = nil, completion = "看來說你大&lt;class&gt;的地位是努力得來的實在太過含蓄。你今天的成就證明你生來就是大&lt;class&gt;的料。\n\n現在，乘上你的新坐騎，以知識的力量對抗燃燒軍團。", rewards = "您會學到：\n\n大法師稜彩圓盤\n\n您還會收到：\n\n"}
