MultiLanguageQuestData['tw'][45381] = {title = "暗夜堡：夏多雷咒符", objective = "在普通難度的暗夜堡中，從艾莉珊德身上收集4個時空回音。", description = "建造暗夜堡的時候，我們的同胞鑄造了一種能通行各個大廳的咒符。只要用了這個咒符，就能在宮殿裡通行無阻，直接找上那個博學者。使用夜井的能量碎片，就能找出這個咒符，終結這場愚蠢的戰爭…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夏多雷咒符"}
MultiLanguageQuestData['tw'][45382] = {title = "暗夜堡：夏多雷咒符", objective = "在英雄難度的暗夜堡中，從艾莉珊德身上收集4個時空回音。", description = "建造暗夜堡的時候，我們的同胞鑄造了一種能通行各個大廳的咒符。只要用了這個咒符，就能在宮殿裡通行無阻，直接找上那個博學者。使用夜井的能量碎片，就能找出這個咒符，終結這場愚蠢的戰爭…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夏多雷咒符"}
MultiLanguageQuestData['tw'][45383] = {title = "暗夜堡：夏多雷咒符", objective = "在傳奇難度的暗夜堡中，從艾莉珊德身上收集4個時空回音。", description = "建造暗夜堡的時候，我們的同胞鑄造了一種能通行各個大廳的咒符。只要用了這個咒符，就能在宮殿裡通行無阻，直接找上那個博學者。使用夜井的能量碎片，就能找出這個咒符，終結這場愚蠢的戰爭…", progress = "少了咒符，我們就只能一路殺進這座城市。", completion = "這些碎片所蘊含的力量，能讓我把咒符呼喚過來。做得好！", rewards = "您會收到：\n\n夏多雷咒符"}
MultiLanguageQuestData['tw'][45385] = {title = "我們必須做好準備！", objective = "到破碎海岸上的伊利達瑞營地與絲瑟諾女士交談。", description = "燃燒軍團的戰艦暫時離開了。他們早晚會再次發動攻擊，我們必須做好準備。\n\n我們必須立刻進行維修！絲瑟諾女士搶先去尋找零件了。那傢伙只要能待在地面上，什麼都願意做，哈！\n\n她正在破碎海岸等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45390] = {title = "維酷人的靈魂", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45392] = {title = "黑暗的勿忘我", objective = "把薇蘿娜拉的備用兜帽交給亡獵者穆爾戈斯。", description = "送花…確實有點感人。\n\n<薇蘿娜拉輕輕嗅了嗅一朵黑色玫瑰。>\n\n我有個備用的兜帽。不是什麼華麗的東西，但或許穆爾戈斯願意收下。\n\n記得叫他千萬別想太多或什麼的。我只是想回報一下他的好意。\n\n希望這件事情你別告訴任何人。送禮物給愛慕者稍微有點違反黑暗遊俠的行事準則。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45398] = {title = "駕馭力量", objective = "殺死安鐸‧馴龍者並取得霜牙的韁繩。", description = "這群蠢蛋竟然用霜牙的韁繩來制服冰霜巨龍。他們的領袖安鐸坐在育母背上，嘲笑著我們。\n\n他時日不多了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45399] = {title = "撕毀斯威崔克", objective = "殺死8個斯威崔克維酷人並使其復生。", description = "就我所知，作業的規矩如下。凡人踏入寒冰皇冠。凡人被殺得片甲不留。凡人重生為天譴軍。\n\n可不能讓這些蠢蛋貿然進來這裡為所欲為，再安然無恙地離開。該把他們變成貨真價實的無腦人士了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45404] = {title = "酒坊的危機", objective = "協助愛瑪伊找到釀酒大師白蘭琪並守衛風暴烈酒酒坊。", description = "對這突如其來的攻擊，我們根本毫無準備。釀酒大師白蘭琪恐怕被俘虜了，或甚至更糟…\n\n請助我一臂之力，宗師！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][45406] = {title = "風暴之怒", objective = "消滅盾息之島上的燃燒軍團部隊。", description = "我們沒時間準備了，必須馬上行動！\n\n跟我來，小傢伙。由你負責指引瞄準方向，我們用雷擊和閃電淨化這座島！", progress = nil, completion = "今天不會是你的末日，勇士。燃燒軍團進逼英靈之門，要是沒有你，就鐵定會失守。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45412] = {title = "防護：伊利達瑞的援助", objective = "在達拉然的街道上找到珂娃絲‧血棘。", description = "除了我們以外，也有其他人想揭發燃燒軍團企圖滲透達拉然的陰謀。\n\n伊利達瑞的珂娃絲‧血棘主動在城市街道上巡邏，調查近日攻擊事件的原因。\n\n我並不完全信任這些「惡魔獵人」，但至少他們沒有愧對這個稱號。我建議你在燃燒軍團再次攻擊前先找到她，看看她有什麼發現。\n\n您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45413] = {title = "收集情報", objective = "詢問達拉然銀行內的民眾，調查失竊的東西是什麼。", description = "燃燒軍團派出一隻又一隻的惡魔，企圖闖入達拉然城裡的祈倫托寶庫，但我們不清楚他們的目的為何。\n\n看來他們終究還是闖入了。\n\n我們必須盡快查清楚他們偷了什麼東西，別讓他們有機會使用它。\n\n向生還者打聽消息，然後我會使用我的靈視，確保沒有任何惡魔依然潛伏在此。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45414] = {title = "證實疑慮", objective = "在達拉然找到預言者費倫。", description = "卡魯歐大領主曾是燃燒軍團最厲害的將領，那顆心臟事是他僅存的遺骸。\n\n多年前，卡魯歐的軍隊差一點就突破黑暗之門，擊潰外域的艾澤拉斯聯軍。我們伊利達瑞先發制人，攔阻了他的攻擊。\n\n我擔心燃燒軍團打算用這顆心臟，加快卡魯歐在虛空的重生速度。我們必須馬上去找預言者費倫，只有他能告訴我們真相。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45415] = {title = "兩界之間", objective = "在外域的命運階梯建造通往扭曲虛空的傳送門。", description = "卡魯歐會帶來毀滅性的災難，但他的力量尚未完全恢復。他的爪牙已帶著他的心臟，加快他在虛空的重生速度。\n\n我們的時間所剩無幾。\n\n前往外域的命運階梯，那裡正是卡魯歐敗亡的地方，也是和他的靈魂連結最強的地方。你必須在那裡開啟通往扭曲虛空的通道。\n\n我必須為接下來的戰鬥做足準備。祝你好運，勇士。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45416] = {title = "卡魯歐歸來", objective = "在扭曲虛空消滅卡魯歐大領主。與戰事參謀維朵莉亞交談以前往該處。", description = "我收到一封珂娃絲的信函，以及該如何送你過去那裡的說明。\n\n我能將你傳送到他們身邊進行戰鬥，但你需要一些虛空裂片，才能強行進入扭曲虛空。\n\n收集足夠的裂片之後再回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45417] = {title = "暗夜堡：暗影議會領袖", objective = "在暗夜堡擊敗古爾丹。", description = "古爾丹正在使用夜井的力量，想把薩格拉斯拉進這個世界。\n\n召集你的夥伴，一起攻入暗夜堡頂端。\n\n我會準備好聖光之心，一旦時機成熟就跟你們會合。\n\n讓我們同心協力一舉消滅古爾丹。", progress = nil, completion = "罪有應得。", rewards = "您會收到：\n\n暗影議會首盔"}
MultiLanguageQuestData['tw'][45420] = {title = "暗夜堡：阿曼蘇爾之眼", objective = "協助卡德加運送阿曼蘇爾之眼。", description = "我們打贏了，但是這場仗還沒有結束。\n\n如果要阻止惡魔繼續湧入艾澤拉斯，就得拿創世之柱來封印薩格拉斯之墓。\n\n<卡德加看往地上的阿曼蘇爾之眼。>\n\n那個東西…看來不適合隨身攜帶。\n\n或許我可以利用它本身的力量將它傳送至達拉然。好像也只能試試看了！", progress = nil, completion = "有了阿曼蘇爾之眼，我們就快可以封住傳送門了。", rewards = "您會學到：\n\n阿曼蘇爾之視\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][45422] = {title = "神御之王敕令", objective = "在傳奇難度中，擊敗英靈殿裡的神御之王斯寇瓦德。", description = "我們的斥侯從斯鐸海姆帶來了壞消息。\n\n神御之王斯寇瓦德在從古爾丹那裡接獲新命令。在那之後他的部隊展開了更加猛烈的攻勢。\n\n我們必須想辦法得知命令的內容，<name>。\n\n即便收到新命令，神御之王還是對泰坦守衛者歐丁無比執著。去英靈殿攔截斯寇瓦德，或許你就能得知他的燃燒軍團主人到底下了什麼命令。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45423] = {title = "哀嚎的小動物", objective = "在哀嚎洞穴擊敗萌芽的永生孢子。", description = "很高興你來了，<name>。\n\n自從納拉雷克斯醒來以後，洞穴中一直傳出微弱的哀嚎聲。起先，我們懷疑是一些變異小動物還活著。但深入調查後，我們發現牠們不斷成長繁殖，數量遠遠超出我們的想像。這可能跟永生的沃爾丹的屍體有關，但目前還無法肯定。就是這樣我們才想派你出動。\n\n最近，我還看到可疑的足跡通往洞穴深處。看來除了我們之外，有別人也展開行動了，請務必小心一點。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n魔噗連線：哀嚎洞穴\n\n您還會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][45425] = {title = "返回林地", objective = "回到幻夢之林找蘭薩‧巨蹄。", description = "真是天大的好消息！殺了指揮官以後，德魯伊和先祖應該安全了。復仇成功只是錦上添花。\n\n我們應該通知蘭薩，讓他知道我們的進度。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n完好無損的夏達希爾樹葉"}
MultiLanguageQuestData['tw'][45426] = {title = "大自然的反擊", objective = "回到幻夢之林找蘭薩‧巨蹄。", description = "<name>，你必須讓幻夢之林知道我被攻擊了。跟其他德魯伊說，如果不阻止燃燒軍團，這種侵略行動會不斷發生。\n\n謝謝你幫忙，我能感覺到魔化能量開始從血管退散了，雖然還要一點時間。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][45437] = {title = "緊急狀況", objective = "在守護者殿堂找到莫爾的訪客。", description = "大法師，<name>！我們有位貴賓。當你有空的時候，請來我的居所找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
