MultiLanguageQuestData['tw'][45812] = {title = "進攻維爾薩拉", objective = "把燃燒軍團的部隊趕出維爾薩拉。", description = "燃燒軍團在我們的土地上橫行。找到它們的部隊並消滅威脅，不然就太遲了！", progress = nil, completion = "我們必須繼續奮戰。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45813] = {title = "妳在哪，親愛的", objective = "幫助朵莉亞維持「偽裝」，並問問旅店附近的人，看看朵莉亞究竟到哪裡去了。", description = "多麼悲慘的命運！我們帶著珠寶來換取我愛人的自由，但她不見了！我們來問問這好地方的顧客吧，或許這些人知道她發生了什麼事。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：北郡的瑪克西米利安"}
MultiLanguageQuestData['tw'][45816] = {title = "選擇要支援的職業大廳", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45833] = {title = "海盜灣", objective = "在艾蘇納的亡者海灣與泰絲‧葛雷邁恩和瑟希斯碰面。", description = "雖然我們在破碎海岸有所斬獲，但我認為無冕者應該在陰影中展開下一步戰術。\n\n我們接獲消息，在主島之外有一個大洞穴，那裡有強大的惡魔計劃要擊敗我們。泰絲和瑟希斯有個計畫，但他們需要你協助執行。他們正在艾蘇納的亡者海灣等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45834] = {title = "失竊的靈魂", objective = "釋放15個失竊的靈魂。", description = "歐丁的勇者受困於永恆戰場的靈魂之泉。假如他們的命運沒有脫軌，他們本該成為華爾拉亞。\n\n現在，你能幫助他們恢復該有的地位。摧毀靈魂之泉，釋放他們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45835] = {title = "假命令", objective = "在指定地點偷偷放置假命令。", description = "解決普里克斯後，這個消息會如野火般傳到這裡每個海盜耳裡。我請瑟希斯用她的字跡偽造一些命令，把這裡的手下引開，為我們爭取更多時間。\n\n把假命令放到標記的位置。很快就會看到效果。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45836] = {title = "喬拉齊的號召", objective = "回到潛影之廳找喬拉齊‧拉文霍德領主。", description = "如此一來，計畫的第一階段就大功告成了。我們最好回去找喬拉齊，告訴他好消息。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][45837] = {title = "魔苔蔓延", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45838] = {title = "進攻艾蘇納", objective = "把燃燒軍團的部隊趕出艾蘇納。", description = "惡魔直撲我們的領地，對所有居民造成嚴重危害。\n\n趁現在還有機會，趕緊除掉他們的威脅。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45839] = {title = "進攻斯鐸海姆", objective = "把燃燒軍團的部隊趕出斯鐸海姆。", description = "我們的死敵燃燒軍團竟敢攻擊斯鐸海姆！\n\n勇士，該展現你的英勇了！找到燃燒軍團的部隊並將它們全部殲滅！", progress = nil, completion = "燃燒軍團的部隊在這些山崖後方聚集，正準備發動攻擊。它們的數量隨著時間越來越多。\n\n我們必須在全軍覆沒前先發制人！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45840] = {title = "進攻高嶺", objective = "把燃燒軍團的部隊趕出高嶺。", description = "在我有生之年，曾經歷過不少干擾和威脅，但我從未看過如此輕賤生命的行為。\n\n惡魔燒盡我們的土地，讓我們的族人受苦受難，但我們不能坐視不管，任它們威脅我們歷經千辛萬苦所成就的一切。\n\n順勢而起，<name>。該是起身對抗燃燒軍團的時候了！", progress = nil, completion = "我很抱歉，&lt;name&gt;。希望我和艾維希沒有冒犯你。在兵荒馬亂的情況下，最好小心為上。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45841] = {title = "回報勝利", objective = "在達拉然與大法師莫德菈交談。", description = "你應該去找祈倫托。他們鐵定想聽到這個好消息！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45842] = {title = "六法議會的禮物", objective = "在紫羅蘭城塞高舉你的武器，接受六法議會的贈禮。", description = "<name>，若是沒有你，燃燒軍團最強的手下仍會繼續在艾澤拉斯橫行，破壞我們辛苦贏來的戰果。\n\n這項義舉不僅值得讚賞，更要有實質的獎勵。\n\n若你願意接受，我們想分贈一點自己的棉薄之力，作為你英勇對抗黑暗的正式獎勵。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][45843] = {title = "暗黑預兆", objective = "在達拉然與大法師莫德菈交談。", description = "我們無法獨自擊敗卡魯歐。\n\n等傳送門穩定之後，我會想辦法通知你，然後我們就能解決這個惡魔大領主。\n\n在此同時，你應該告知祈倫托有關瓦肅恩的死訊，以及卡魯歐回歸的消息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45844] = {title = "安東尼達斯的愛好", objective = "在守護者殿堂與大法師卡雷克交談。", description = "大法師卡雷克請你回守護者殿堂一趟。他有一些發現，希望能早點跟你談談。\n\n請你盡快去見他一面。", progress = nil, completion = "大&lt;class&gt;，我找到一個你可能會想看看的東西，是大&lt;class&gt;安東尼達斯生前的日記。他在日記中提到某件未完成的工作，也許我們能幫他完成。\n\n是一種會飛的稜碟，會自動配合騎乘者的專精。\n\n可是我需要你幫忙才能把稜碟通通找齊。據我所知，安東尼達斯在生前就把稜碟分送給信任的朋友了。也許你能說服他們把稜碟交給我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45845] = {title = "內藏火焰之力", objective = "向卡德加打聽火焰稜碟的事。與他交談後，遵照他的指示去做。", description = "日記中第一個提到的是火焰稜碟。當年他去調查熔火之心的入口，曾經把火焰能量灌注到稜碟裡。\n\n但是這股能量太強，無法控制，於是他請卡德加把稜碟帶到卡拉贊研究，看有什麼書提到控制火焰的方法。\n\n也許可以問問卡德加，那個稜碟後來怎麼了。", progress = "卡德加還記得他用這個東西做了什麼事嗎？", completion = "你拿回來了！正如安東尼達斯所述，它仍具有強大的火焰魔法！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45846] = {title = "灌注冰霜", objective = "前往達拉然陷坑與大法師賽卓克交談，問他冰霜稜碟在哪裡。", description = "安東尼達斯的第二個稜碟灌注了冰霜能量。他提到另一位大法師賽卓克，兩人同心協力透過儀式把能量灌注到稜碟裡，但他們灌注得太多。\n\n如果我沒記錯，賽卓克現在還在達拉然陷坑準備達拉然的重建工作。\n\n希望他知道去哪裡找冰霜稜碟。", progress = "達拉然從前的所在地被破壞成這樣，誰會知道稜碟在哪裡？", completion = "巨魔把它拿走了？那些野人恨不得拿走所有東西。\n\n無論如何，你能找到它真是太好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45847] = {title = "近在咫尺", objective = "與大法師瑟琳卓交談，問她達拉然的秘法稜碟在哪裡。", description = "第三個稜碟用的是安東尼達斯自己的秘法能量。這是他在巔峰時期做的事，但和其他兩個稜碟一樣，他沒有把工作完成。\n\n他說稜碟最後交給了大法師瑟琳卓…\n\n呃，這不就是達拉然的傳送門訓練師嗎？她一定知道稜碟在哪！\n\n快，去找她。", progress = "在她那裡嗎？", completion = "原來它一直都在達拉然。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][45848] = {title = "海盜專用", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n啄啄鳥"}
MultiLanguageQuestData['tw'][45856] = {title = "維爾薩拉之戰", objective = "在維爾薩拉擊敗恐懼輔臣葛拉托克。", description = "早在這些攻擊一開始發動時，我就覺得那些惡魔好像知道我們的計畫，能預測我們的一舉一動。想要終結這一切，就必須集中攻擊野獸的要害。\n\n你的所作所為證明這些戰鬥之所以能勝，並非單憑勇氣，還需要意志和犧牲。我請求你再一次與盟友站在戰場上，終結這瘋狂的一切。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n塞納留斯的角"}
