MultiLanguageQuestData['tw'][46110] = {title = "斯鐸海姆之戰", objective = "在斯鐸海姆擊敗領主指揮官埃勒克席斯。", description = "你成功消滅了燃燒軍團在盾息之島的部隊，但它們還在持續進攻。\n\n只有一個方法能終止這一切。你必須潛入敵陣，找到它們的指揮官，並摘下那顆邪惡的腦袋！", progress = nil, completion = "做得好，&lt;name&gt;！真的非常好！\n\n燃燒軍團一定會後悔覬覦斯鐸海姆的土地！", rewards = "您會收到：\n\n晉升者咒符"}
