MultiLanguageQuestData['tw'][46237] = {title = "召血者的公文", objective = "在懼痕裂隙與莫蘇爾‧召血者交談。", description = "術士！我們有來自懼痕裂隙的消息。\n\n烏鴉從莫蘇爾‧召血者那裡帶來一個消息，請你立刻前往懼痕裂隙與他會面！", progress = nil, completion = "我們的任務並不簡單，但等到結束後，我們就能成為克索諾斯真正的主人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46238] = {title = "建造傳送門", objective = "取得5個魔岩、3個渾沌的尖晶石和1份不屈藥水。這些物品可透過採集、使用專業技能製作或在拍賣場購買取得。", description = "如果我們希望與克索諾斯建立穩定連結，就需要一道特別堅固的傳送門。可惜的是，我們無法憑空召喚出這種傳送門。\n\n我需要你去收集必要的材料。拿到材料後，我會立刻讓莫阿格建造傳送門。\n\n這是我們需要的材料清單。", progress = "你收集到必要的材料了嗎？", completion = "太好了。這些不屈藥水應該足以支撐魔岩並穩固傳送門的結構，而這些渾沌的尖晶石應該能有效集中傳送門的魔法。\n\n我會盡快讓莫阿格動工。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46239] = {title = "魔核", objective = "從入侵破碎群島的燃燒軍團指揮官身上取得一個超載魔核。", description = "對術士而言，想打開通往燃燒軍團世界的傳送門還算容易，但要讓傳送門一直開著，就需要極大的能量。\n\n所以我們得找到可靠的魔化能量來源。\n\n我知道燃燒軍團的指揮官會用強大的魔核控制戰艦。只要擊敗指揮官，就能搶走魔核。", progress = "你拿到魔核了嗎？", completion = "你一進入懼痕裂隙，我立刻感覺到魔核散發出魔化能量。\n\n我想這絕對合用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46240] = {title = "給我燃料，給我火焰", objective = "在維爾薩拉的逝光岩洞內從梟獸身上取得50份梟獸之血。", description = "光憑強大的魔核並無法為傳送門供給足夠的能量。如同所有強大的引擎，它還需要燃料。魔化能量的引擎必須燃燒生命力才能運轉。\n\n我們需要充滿魔法能量的血，才能讓魔核持續運作，穩定我們與克索諾斯的連結。幸好我有相關經驗，我恰好知道取得這種血液的地方。\n\n你需要罐子之類的東西。", progress = "你榨乾梟獸的血了嗎？", completion = "你收集了很多血。我很佩服，&lt;name&gt;。\n\n我乾脆開始囤積這種東西好了。它有好多用途！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46241] = {title = "赫爾努拉斯的手下", objective = "在破碎海岸的黑暗監獄內使用魅魔的誘惑以訊問克索諾斯教徒。", description = "驚懼領主赫爾努拉斯將召喚石贈給他的副官，能用來召喚並束縛克索諾斯的恐懼戰馬，讓其臣服於他們的命令。這種石頭應該能幫我們引出憤怒戰馬。\n\n有人看到克索諾斯教徒出現在破碎海岸，幫助燃燒軍團。合理推測，他們的領袖應該握有赫爾努拉斯給的召喚石。\n\n你的魅魔應該能誘惑教徒吐露真相。找到知道領袖下落的教徒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46242] = {title = "驚懼領主的呼喚", objective = "在破碎海岸的黑暗監獄內，從『妖術師』祖麗娃身上取得克索諾斯召喚石。", description = "根據教徒的說法，你在找的領袖應該就在塔裡，監視黑暗監獄的一舉一動。", progress = "你找到召喚石了？", completion = "我一直都想拿到驚懼領主的召喚石。如果不是為了這個任務，我們應該有辦法幫一整個軍隊準備恐懼戰馬。\n\n不過這個任務顯然更重要。亞瑞克薩斯一定無法在召喚石的誘惑下控制憤怒戰馬。只要繼續維持傳送門，牠就會現身。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46243] = {title = "克索諾斯憤怒戰馬", objective = "在懼痕裂隙的召喚平台上完成儀式，以控制憤怒戰馬。", description = "時機已到，一切準備就緒。等你準備好了，我們就會開啟通往克索諾斯的門戶，迫使亞瑞克薩斯和憤怒戰馬現身。\n\n跟我一起前往召喚平台。我們將在那裡進行儀式。\n\n做好準備，<name>。這項任務可不簡單。", progress = nil, completion = "我們已經準備好要將憤怒戰馬交給你了，虛空領主。牠桀驁不遜，絕不會輕易服從。\n\n我必須說，我有點忌妒。我從未見過如此兇猛的野獸，我們的侍徒完全控制不住牠。", rewards = "您會學到：\n\n虛空領主混沌憤怒戰馬\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][46244] = {title = "永夜聖殿：神盾祭壇", objective = "擊敗梅菲斯托領主並將阿格拉瑪之盾放在永夜祭壇上。", description = "勇士，我們準備好進攻薩格拉斯之墓了。\n\n我研究了艾格文的文本。她是多年前擊敗黑暗泰坦化身的守護者。她寫說如果結界遭到破壞，可以將阿格拉瑪之盾放置在永夜聖殿的聖壇上啟動安全裝置。\n\n<name>，你是收集所有創世之柱的英雄。召集夥伴，進入神殿。務必小心，梅菲斯托一定會用盡各種手段，企圖阻止你放置神盾。你一定要成功！", progress = nil, completion = "梅菲斯托死了，聖殿也安全了，但薩格拉斯之墓下層仍然遭到燃燒軍團佔據。\n\n這並不是我們期望得到的結果，但這場戰鬥還沒結束，&lt;name&gt;。\n\n不要停手，不要給燃燒軍團喘息的機會，要讓它們無處可躲。等我們準備好，就要奪下薩格拉斯之墓、將惡魔趕出艾澤拉斯！", rewards = "成熟的明日花苗惡魔指揮信標煉獄之油吸熱稜鏡月亮石刻像純粹的秘法粉末梅菲斯托的肋骨濃縮風暴之怒貴族殉難者之血沒被動過的聖潔蠟燭"}
MultiLanguageQuestData['tw'][46245] = {title = "開始建造", objective = "使用建築桌捐獻軍團之殞戰爭物資以建造法師塔、虛空干擾裝置或指揮所。", description = "現在補給品收到了，得有人決定接下來要繼續建造的建築物。\n\n嗯，既然你是<class>t，就由你決定吧。\n\n選擇接下來要繼續建造的建築物。", progress = nil, completion = "朋友，真是明智的選擇！雖然所有選擇都很好，但這裡情況這麼糟，大家隨時都有可能被惡魔殺掉，還是多來一點正能量比較好。\n\n你如果找到更多補給品，就帶回這裡，我會確保補給品用在你指定建造的建築物。\n\n呼！囉嗦的話說完了，該喝一杯啦！", rewards = nil}
MultiLanguageQuestData['tw'][46246] = {title = "擊敗它們", objective = "在破碎群海岸殺死100個惡魔。", description = "魔化風暴不斷地在破碎海岸降下惡魔爪牙。基爾加丹以為他的軍隊會無窮無盡，他的資源永遠不會耗竭。\n\n我們會讓他知道自己大錯特錯。\n\n好好懲戒他手下的爪牙吧，<class>t。把惡魔一個接一個擊倒，讓你的武器沾滿它們的鮮血。等它們哭著求饒的時候，就把它們趕回扭曲虛空，任由它們哭叫吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n虛空裂片"}
MultiLanguageQuestData['tw'][46247] = {title = "保衛破碎群島", objective = "在破碎群島擊退一場惡魔入侵。", description = "致力從燃燒軍團手中奪回破碎海岸的同時，我們也不能讓其它地區落入惡魔的魔掌。\n\n基爾加丹派遣部隊到破碎群島各處，威脅我們新盟友的家園。在這危急存亡之際，你必須回應他們的求救。\n\n請盡快擊退惡魔的入侵部隊，<class>t。軍團之殞會守住破碎海岸。", progress = nil, completion = "這是場光榮的勝利，虛空領主。\n\n即便如此，也不能鬆懈！只要是燃燒軍團出手的地方，我們就必須全力還擊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46248] = {title = "實現預言", objective = "完成8個破碎海岸世界任務。", description = "我這一生中看過許多預言，有一些讓我充滿希望…有一些則令人絕望。\n\n我已經看到了，我們就快戰勝基爾加丹，可是預言只會指出未來的方向，需要努力，才有可能實現。\n\n所以<name>，這一切又要拜託你了。我知道你已經為這個世界做了很多，但你還必須付出更多。去破碎海岸戰鬥吧！為這個世界塑造一個沒有燃燒軍團的未來！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n團結之力軍團之殞戰爭物資"}
MultiLanguageQuestData['tw'][46249] = {title = "勇往直前", objective = "在你的職業大廳成功做完一個軍團之殞任務。", description = "你的職業組織完成了非常重要的任務，<class>t。你的勇士們成功地再次及時阻止燃燒軍團入侵。\n\n在我們準備襲擊薩格拉斯之墓時，也不能讓那些惡魔好過。壓制它們，不能放鬆，這樣一來就能讓它們暴露弱點，我們也能利用這些弱點獲得優勢。\n\n派出你的勇士，<name>。這些任務至關重要，就全看他們的了…我們和基爾加丹的對決近在眼前，更是不能放鬆。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇士裝備箱大廳資源"}
MultiLanguageQuestData['tw'][46250] = {title = "擒賊必擒王…", objective = "在破碎海岸殺死稀有的精英惡魔指揮官。", description = "破碎海岸到處都是燃燒軍團的雜碎，我們對每個惡魔都應該碎屍萬段、絕不容情。\n\n但有些惡魔顯然更為陰險狡詐，強大的勇士集結其他惡魔，為了遂行它們邪惡的意圖。\n\n擊敗這些惡魔勇士，就能讓它們的同類聞風喪膽、驚疑不定。打擊燃燒軍團的士氣，我們就能展開反擊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n虛空裂片"}
MultiLanguageQuestData['tw'][46251] = {title = "虛空裂片", objective = "在破碎海岸取得2500個虛空裂片。", description = "你可能已經注意到了，惡魔死後會留下虛空裂片，這是扭曲虛空的能量結晶。我正在做實驗，需要大量的能量結晶…確切來說，需要$1oa個虛空裂片。\n\n你為什麼露出那種表情？我們討論過了吧，這都是我仔細算過的。\n\n總之，我需要剛好$1oa個虛空裂片，少一個就不夠了，多一個就很奇怪。\n\n別再質疑我的算式了，快去！", progress = "你拿到虛空裂片了？希望你數學不錯，如果弄錯裂片的數量，我可不會負責。", completion = "後來有人跟我說，有時候我做事，呃，可能太求好心切了。\n\n關於這個嘛…&lt;咳咳&gt;好像確實如此。\n\n其實我只需要一個虛空裂片就夠了，不用那麼多。剩下的虛空裂片怎麼處置，你應該可以自己想吧？\n\n好了，這件事就這樣吧。", rewards = "您會收到：\n\n虛空裂片"}
MultiLanguageQuestData['tw'][46252] = {title = "無法容忍的侵襲", objective = "在法隆納或魔魂堡殺死50個惡魔。", description = "我們在破碎海岸對抗燃燒軍團的同時，那些惡魔也在進攻附近地區。我們不能坐視這種情況。\n\n法隆納和魔魂堡的惡魔堡壘已經威脅到艾蘇納和蘇拉瑪爾的安全。選一個進攻地點，削弱惡魔軍力。\n\n等你回來，我希望看到你雙手沾滿惡魔的鮮血。然後我們再一起去薩格拉斯之墓對付基爾加丹。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n虛空裂片"}
MultiLanguageQuestData['tw'][46253] = {title = "創世之柱", objective = "使用創世之柱封印薩格拉斯之墓。", description = "我們在破碎海岸的戰役來到了轉捩點。軍團之殞部隊現在準備好突破薩格拉斯之墓、封鎖燃燒軍團進入我們世界的通道。\n\n現在就是出手的時機，<name>。\n\n阿格拉瑪之盾放在聖殿中了。尊者艾格文的影像告訴我們，必須使用其它的創世之柱才能封印薩格拉斯之墓。沒有人比你更適合將這些遠古聖物放置歸位，永遠封鎖魔化風暴。", progress = nil, completion = "創世之柱就位了。薩格拉斯之墓封印完畢，艾格文的影像也終於能安息。\n\n&lt;卡德加的手指向天空。&gt;\n\n很可惜，我們沒得休息。\n\n雖然你今天大獲全勝，但我們沒時間慶祝。最終決戰就在眼前。盡快準備好。", rewards = "您會收到：\n\n孤傲守護者的破損封印"}
