MultiLanguageQuestData['tw'][46266] = {title = "斬魔者回歸", objective = "登上魔錘號找珂娃絲回報。", description = "如果你跟我一樣，一定也會想待在平穩的地面上！\n\n但是，看來我們最好還是立刻回到魔錘號上，讓珂娃絲完成維修工作。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n馬爾頓靈魂水晶"}
MultiLanguageQuestData['tw'][46267] = {title = "戰鬥領主回歸", objective = "在擎天堡與歐丁交談。", description = "戰鬥領主<name>，歐丁一定想聽聽你在這裡的光榮戰績！\n\n等你準備好了，我會協助你返回擎天堡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鑲金的擎天堡巨盾"}
MultiLanguageQuestData['tw'][46268] = {title = "尋獲的紀念物", objective = "把羅盤帶到暴風要塞交給安杜因‧烏瑞恩國王。", description = "<飾品的黃銅外殼以精巧的花紋雕飾，由於屢經岩石和海浪擊打，許多細節已經模糊。如果清除扣環的鹽和泥沙，應該可以打開蓋子。\n\n是一個羅盤…至少曾經是。盤面的玻璃已經碎了，指針扭曲，沒辦法動。\n\n蓋內畫有肖像，顏料因為長期泡在海水中已經變淡，但肖像的主角毋庸置疑：是年幼的安杜因‧烏瑞恩。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一疊皇家信紙"}
MultiLanguageQuestData['tw'][46270] = {title = "reuse me", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46272] = {title = "奉旨覲見", objective = "在暴風要塞與吉恩‧葛雷邁恩碰面。", description = "你好，<name>。\n\n皇室下旨召你前往暴風要塞。國王急需你的協助！\n\n請盡速回到暴風城。\n\n葛雷邁恩國王希望你盡速趕到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46274] = {title = "開導國王", objective = "在聖光大教堂內尋找安杜因‧烏瑞恩國王。", description = "自從你把安杜因父親的羅盤交給他後，他就變了。他變得無精打采…心煩意亂。\n\n我們試著開導他，卻徒勞無功。昨日早上，他一言不發就離開要塞。\n\n當然，我命令守衛跟著他。他去大教堂禱告，之後就一直待在那裡。\n\n是你讓他變得鬱鬱寡歡！你必須說服那個男孩盡到他應盡的責任。我們還有不能輸的仗要打！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46275] = {title = "王國之心", objective = "陪同安杜因國王在暴風城裡走走。", description = "我的父親是個傳奇人物。他監督暴風城的重建工作，正面迎戰巨龍，還帶領聯盟獲得無數勝利。\n\n結果有一天，他就這樣…走了。\n\n我戴著他的王冠，頂著他的頭銜。我不費吹灰之力就得到這些…得到人民的信賴。\n\n戰爭期間，我都躲在要塞中，身旁都是守衛和顧問。我需要到暴風城的街上走走，瞭解我的人民心中到底是懷著希望還是恐懼。\n\n歡迎你與我同行。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鑲金的祈禱串珠"}
MultiLanguageQuestData['tw'][46277] = {title = "協助建造法師塔", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n次級團結之力虛空裂片"}
MultiLanguageQuestData['tw'][46278] = {title = "退還給寄件人", objective = "退還9個遭退回的信件。", description = "你來得正是時候！\n\n最近的郵件恐怕就沒那麼準時了。\n\n我們的人手嚴重短缺，但是送件需求量卻處在前所未見的高峰期。我們完全應付不來！\n\n我也想跟你聊天，可是我得先趕上進度才能喘一口氣。\n\n該做的事要先做。有幾包遭退回的信件不見了，你可以幫我把它們全部找回來，然後退還給寄件人嗎？", progress = nil, completion = "你真是天生吃這行飯的！\n\n欸，你願不願意多待一段時間？我實在很需要幫手！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46279] = {title = "札剛", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46282] = {title = "國王之道", objective = "陪同安杜因國王前往薩格拉斯之墓。", description = "現在，我已經親眼見識過破碎海岸的慘狀，還有燃燒軍團的可怕，我的雙眼已經變得清亮澄明，能看清真正重要的事。\n\n我說的不是高深莫測的邪惡敵人，而是這些可怕的惡魔讓我的子民們起身反抗、不畏犧牲，激發出如此可貴的情操。\n\n父親曾經告訴我，每個國王都必須承擔王冠帶來的重擔。在這一刻，我肩上的責任變得前所未有地沉重…\n\n請帶我到父親慷慨捐軀的地方，我要向他的英勇犧牲致意。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n損壞的腕帶"}
MultiLanguageQuestData['tw'][46286] = {title = "軍團之殞物資", objective = "在破碎海岸完成世界任務或殺死稀有精英以獲得軍團之殞戰爭物資。", description = "要是不建築其它防禦工事，我們在破碎海岸的立足點絕對不堪一擊。我們絕不容許這種事發生。\n\n為此，我們已經開始建造三個重要建築物：法師塔、虛空干擾裝置和指揮所。每一棟建築物都會是對抗燃燒軍團的寶貴助力。\n\n需要軍團之殞戰爭物資，才能推動這些建築物的建造進度。等你收集到必要的物資後，就來找我，我會負責分配資源。", progress = nil, completion = "好極了，就是這樣啦！\n\n喂！開工啦！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46288] = {title = "人人上前線", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46290] = {title = "大法師回歸", objective = "在守護者殿堂與莫爾交談。", description = "既然達拉然再度受到保護，我們就能稍微鬆一口氣。\n\n是時候回到守護者殿堂了。我相信莫爾正焦急地等著我們的捷報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n提里斯護法秘能卷軸"}
MultiLanguageQuestData['tw'][46291] = {title = "死亡礦坑大反擊", objective = "在死亡礦坑擊敗餅乾廚餘。", description = "是布芮妮派你來的？是她的話，訊息免費。別說我打小報告就好。\n\n我在死亡礦坑很多年了，這裡的生活很愜意。但幾天前，礦坑裡傳來很多噪音。如果你想悄悄溜進去調查，我可以用礦車帶你進去，誰都不會發現的。\n\n準備好就跟我說一聲吧。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n魔噗連線：西部荒野\n\n您還會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][46292] = {title = "寵物對戰挑戰：死亡礦坑", objective = "在死亡礦坑擊敗餅乾廚餘。", description = "死亡礦坑還需要善後，看來你上次沒掃蕩乾淨。\n\n我們要再用礦坑推車那一招，只是，這次要更火爆些。你想玩火嗎？不想？好吧。等你準備好了來找我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n舊瓶蓋"}
MultiLanguageQuestData['tw'][46293] = {title = "死亡礦坑…第三部？", objective = "去西部荒野的死亡礦坑外面找『贓物佬』馬庫斯‧布朗。", description = "我聽說死亡礦坑裡面出現異常的動靜。看過你在哀嚎洞穴的表現之後，我認為你就是去調查的不二人選！\n\n我在西部荒野有個朋友。他不怎麼起眼，可是很機靈，或許他已經掌握了西部荒野的近況。我們打敗范克里夫家的人…兩次了。不知道這次又是誰在搞鬼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46297] = {title = "無窮之力", objective = "殺死12個惡魔。", description = "這裡不是安全之處，燃燒軍團已經出動所有兵力要保護阿古斯。\n\n底下的攻城營地到處都是惡魔，要阻擋我們運用梵迪卡爾的武器。\n\n一定要在武器完全充能之前解決這些惡魔，否則阿古斯就會是我們的葬身之地。", progress = nil, completion = "該來對付主要武器了。", rewards = "墮落黑暗秘紋厄運召喚者的心臟毀滅者定標水晶不穩定的毀滅者炸藥魔縛苦工的憂鬱聖光軍團紋章主宰鐐銬頑抗生命印記疤翼之爪獰笑邪惡犬魔顱骨您會收到：\n\n"}
MultiLanguageQuestData['tw'][46305] = {title = "索林姆的火焰", objective = "說服德雷克雅神殿守護者讓你拿走索林姆之焰。", description = "不久前，德雷克雅和索林尼爾還相敬如賓。當斯寇瓦德掌權後，情況才變了。遠古的德雷克雅幽魂看守著這座山巔，這裡似乎是某個神聖墓地。他是儀祭火焰的守衛者，這正好是我們召喚育母所需要的。\n\n我們試著說服他把火焰給我們好了。我相信他會…一定會明理。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46308] = {title = "留下蹤跡", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46314] = {title = "復仇：尋找珂娃絲", objective = "在達拉然的街道上找到珂娃絲‧血棘。", description = "除了我們以外，也有其他人想揭發燃燒軍團企圖滲透達拉然的陰謀。\n\n珂娃絲‧血棘，你的伊利達瑞戰友，正主動在城市街道上巡邏，調查近日攻擊事件的原因。\n\n我並不完全信任你們，但至少你們沒有愧對「惡魔獵人」這個稱號。我建議你在燃燒軍團再次攻擊前先找到珂娃絲，看看她有什麼發現。\n\n您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46317] = {title = "猛禽的呼喚", objective = "在幻夢之林與黎沙莉‧烏鴉交談。", description = "燃燒軍團正再度對海加爾的艾維娜聖壇發動攻擊！\n\n黎沙莉‧烏鴉正在籌組一支反攻部隊，她請你立刻前往幻夢之林。\n\n我們會在這裡全力抵擋。祝你好運，大德魯伊！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46318] = {title = "守衛艾維娜", objective = "協助黎沙莉防衛海加爾的艾維娜聖壇，再回到幻夢之林找她。", description = "情況緊急。燃燒軍團又開始攻擊海加爾的艾維娜聖壇了！它們一定有什麼特別的目的，但我還不確定是什麼。\n\n我們這些猛禽德魯伊擅長巡邏和滲透，但…耐力不怎麼好。他們堅持不了太久！我們必須前去支援！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46319] = {title = "別想奪走我的天空", objective = "處理掉『闇影』因法薩爾，並取回艾維娜塑像。", description = "艾維娜聖壇遭惡魔攻陷，艾維娜塑像被偷走了。\n\n那個塑像將猛禽德魯伊與艾維娜授予我們的飛行能量連結在一起。\n\n猛禽德魯伊決定找個更安全的地方重建新聖壇，就在幻夢之林這裡。\n\n與此同時，我要去奪回我們的塑像了。如果你想提供協助，就到艾蘇納與我會面，前往我們追蹤因法薩爾的地方。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n大德魯伊月翼形態\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][46320] = {title = "解藥的希望", objective = "回到五晨寺找釀酒大師白蘭琪的靈魂。", description = "希望你有找到足夠的魔化毒藥樣本，順利製造出解藥。\n\n我們回五晨寺見！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46322] = {title = "海盜灣", objective = "在艾蘇納的亡者海灣和莉莉安‧佛斯與瑟希斯碰面。", description = "雖然我們在破碎海岸有所斬獲，但我認為無冕者應該在陰影中展開下一步戰術。\n\n我們接獲消息，在主島之外有一個大洞穴，那裡有強大的惡魔計劃要擊敗我們。我們的盜賊同伴莉莉安‧佛斯和瑟希斯擬定了計畫，能夠解決惡魔，但他們需要你的幫助。他們正在艾蘇納的亡者海灣等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46323] = {title = "箱子裡有什麼？", objective = "殺死神槍手普里克斯並取得魔能灌注火藥箱。", description = "我們的目標是取得注入某種魔能的火藥箱。我不曉得這裡的海盜是如何拿到手的，但它的危險性遠超乎他們的想像。我向你保證，它在我們手裡會更…有用處。\n\n神槍手普里克斯應該會在海灣深處，靠近水邊的地方。從她身上搶來我們需要的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46324] = {title = "假命令", objective = "在指定地點偷偷放置假命令。", description = "我們必須採取一些預防措施。你暗殺神槍手後，海盜一定會開始找你。我請瑟希斯用她的字跡偽造了一些命令，應該可以為我們爭取一些時間。\n\n將假命令散佈在標記的位置。這樣應該就可以避開危險。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
