MultiLanguageQuestData['tw'][46326] = {title = "喬拉齊的號召", objective = "回到潛影之廳找喬拉齊‧拉文霍德領主。", description = "如此一來，計畫的第一階段就大功告成了。我們回去找喬拉齊，告訴他可以繼續了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][46327] = {title = "暗影交易", objective = "在達拉然底下的守護者之廳與瑞特辛‧焰慍碰面。", description = "根據你拼湊出來的線索，蕾薇亞似乎想要在達拉然下方的圖書館進行一場儀式…應該就是想召喚出她極度著迷的「亞加薩」。這恐怕有點超出我的專業領域，我必須得尋求外援。\n\n我會派人請黑穫議會提供援助。他們的術士會在守護者之廳與你會面，協助你進行調查。\n\n希望我們還來得及。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46333] = {title = "在岩臺生存", objective = "返回魔錘號並與懷惡族母交談。", description = "斬魔者$p，懷惡族母要求你回到魔錘號與她會面。請你盡快去見她。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46334] = {title = "魔化歸來", objective = "與凱菈‧光刃交談以安全飛往魔翼岩臺，並完成魔翼岩臺事件。", description = "馬爾頓擁有很多祕密，我們在接管魔錘號不久後，發現了其中一個秘密。那是某片滿是魔化蝙蝠的繁殖地。\n\n我們抓了一些幼蝠，想將牠們訓練成對抗燃燒軍團的利器。\n\n但在幾天前，我們抓到更有價值的東西，跟你的身份十分相配，斬魔者。\n\n與凱菈交談，她會帶你到岩臺。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n斬魔者破魔尖嘯獸\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][46335] = {title = "提里斯護法寶庫", objective = "在守護者殿堂找到5個遠古文物。", description = "達拉然的武器源自於秘法，但不代表我們不能試試看其他方法。\n\n提里斯護法的保險庫中存有大量的魔法裝置…何不到處看看有沒有什麼東西派得上用場？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46336] = {title = "金色信箋", objective = "在神獵廳閱讀金色信函。", description = "神獵手，我們收到來自神獵廳的消息，某張桌子上放著一封金光閃閃的信，收信人寫著你的名字。\n\n沒人知道它是如何出現的，某個人的狼想打開它，結果卻滿嘴都是燒焦的毛。看來只有你能打開它了。\n\n我們會在你進行調查時，好好守住堡壘。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46337] = {title = "荒野之夜", objective = "請歐丁的信使帶你到永獵之原。", description = "<信裡的金色字跡流暢舒展。讀信時，彷彿能聽見歐丁洪亮的嗓音唸著那些句子。>\n\n荒野之夜已然來臨。\n\n今晚，我們將飽餐一頓，紀念傳說中的野獸。\n\n牠們更會在永獵之原重獲新生。\n\n我們之中必須有一人前往荒野，讓牠們的靈魂再次獲得安息。\n\n如果你希望與我們同行，我的信使已經恭候你多時了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n神獵手忠誠狼鷹\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][46338] = {title = "創意的解決方式", objective = "和亞莉談談。", description = "夜裔靈魂石可能是最有希望的，但必須想出不會讓卡斯拉納提爾脫逃的安全方法。如果讓他逃到達拉然的街區…\n\n我們該詢問我們的朋友，亞莉。她會知道要做哪些修改。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46339] = {title = "鎖鑰官歐爾利斯", objective = "殺死鎖鑰官歐爾利斯並搜查他身上的物品。", description = "前面林地那邊，魔裔叛軍似乎正在看守一個傳送器。不知道它通往哪裡？\n\n可以合理假設我們必須殺了鎖鑰官歐爾利斯才能進入。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46340] = {title = "關上大門", objective = "回到達拉然的紫羅蘭城塞找大法師卡德加。", description = "我們必須在曦格琳對上歐丁前先找到她，但我們的路被堵住了。歐丁一發現曦格琳出手攻擊，就會立刻關閉英靈之門。你必須另尋他路進入英靈殿。\n\n我對傳送門一竅不通，但你的祈倫托朋友似乎非常在行。現在就去找他們，然後想辦法進去。\n\n我很感激你為曦格琳所做的一切，<class>。我只希望我們能讓她獲得救贖。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46341] = {title = "班盧的故事", objective = "聆聽卜大師的故事。", description = "嗨，想必你就是現任宗師吧。\n\n<卜大師斜眼看著你，哼了一聲。>\n\n現在的年輕人真是耐不住性子，滿腦子只想著殺個痛快。\n\n連好好聽故事的時間都沒有了，不管故事多精彩都一樣，對吧？\n\n把拳頭放下吧，讓我這個老傢伙跟你們說個故事。\n\n或許可以順便請我喝一杯？", progress = nil, completion = "謝謝你們的耐心聆聽和好酒。", rewards = nil}
MultiLanguageQuestData['tw'][46342] = {title = "回到破碎的山峰", objective = "在寂靜峰和卜大師碰面。", description = "當然，這不只是個故事。班盧是每一代宗師的私人坐騎，陪他們一起旅行，是忠誠可靠的夥伴。\n\n但…自從你成為宗師以後，他一直沒出現。真讓人擔心。\n\n他最後一次現身是在寂靜峰，就在高宗師圓寂以後。\n\n我們必須從那裡開始找他。", progress = nil, completion = "死得毫無意義，到底是何苦？\n\n&lt;卜大師面色凝重地站在傳送門前，搖了搖頭。&gt;", rewards = nil}
MultiLanguageQuestData['tw'][46343] = {title = "班盧的蹤跡", objective = "跟隨班盧的蹤跡。", description = "高宗師的事恍若隔世。\n\n班盧服侍過每一代宗師，但他和高宗師的情誼最深。\n\n多年來他們一起四處遊歷，結交朋友，維護得來不易的和平。\n\n我無法想像高宗師的死對班盧而言有多痛苦。\n\n這附近一定有班盧的線索。仔細找找吧。", progress = nil, completion = "我這把老骨頭需要休息一下。但我們旅途似乎向前跨了一步。\n\n那邊的咕嚕摩或許能提供一點幫助。你何不在我休息的時候，和他說說話呢？", rewards = nil}
MultiLanguageQuestData['tw'][46344] = {title = "臭臭的幸運星", objective = "收集3個臭臭的幸運星碎片。", description = "喂！拜託幫幫我！可惡的猴人偷了臭臭的幸運星！\n\n臭臭一直很倒楣。一轉頭就發現背包起火了。\n\n臭臭不敢滅火，萬一有更多壞事發生怎麼辦？萬一是更糟的事怎麼辦！\n\n幫臭臭打敗猴人吧，好嗎？把幸運星拿回來，臭臭會盡全力幫你！", progress = "找到我的幸運星了嗎？這裡變得有點熱。", completion = "臭臭有個新主意！不要滅掉背包的火！\n\n背包著火就不會再發生壞事！著火的背包是臭臭新的幸運星！舊的背包留給你吧。\n\n噢，你在找大老虎嗎？臭臭有看見發光的大老虎。往僧院去了。臭臭有幫上忙嗎？", rewards = "您會收到：\n\n臭臭的幸運星"}
MultiLanguageQuestData['tw'][46345] = {title = "直搗黃龍", objective = "使用傳送器。", description = "希望你已經準備好要進行一場冒險。來看看傳送器通往哪裡，如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][46346] = {title = "班盧的影子", objective = "在影潘僧院和卜大師碰面。", description = "感謝你協助臭臭‧山巔，宗師。我們得知更多關於班盧的消息了。\n\n你不用護送我前往影潘僧院。我自己一個人沒問題的。\n\n到那裡跟我碰頭，我們再繼續尋找。", progress = nil, completion = "我才剛開始進行冥想，宗師。我們可能有另一條線索…", rewards = nil}
MultiLanguageQuestData['tw'][46347] = {title = "清除惡煞", objective = "協助指揮官沈黎處理殘餘的煞。", description = "我與影潘談過，如果我們協助他們完成某項任務，他們就會向我們透露一些消息。\n\n與指揮官沈黎交談。在你協助他們的時候，我會繼續冥想。", progress = nil, completion = "影潘非常感激，宗師。\n\n我們是否該繼…你腳上黑黑的東西是什麼？", rewards = nil}
MultiLanguageQuestData['tw'][46348] = {title = "通往班盧的河川", objective = "到東南邊與水語者琉立會面。", description = "我們還是沒找到班盧在哪裡，但我知道誰有可能知道。\n\n有個錦魚人住在東南邊，名字叫水語者琉立。\n\n也許他見過班盧。或者我們能請他問問河川，班盧最近現身的地方在哪裡？\n\n不過啊，宗師，我的關節沒辦法這樣奔波了。我先在這裡休息一會兒，之後再趕上你。", progress = nil, completion = "你好。真是稀客，&lt;class&gt;宗師竟會來拜訪我。我能幫上什麼忙嗎？", rewards = nil}
MultiLanguageQuestData['tw'][46349] = {title = "給琉立的百合", objective = "替水語者琉立收集6朵月光百合。", description = "我沒見過班盧，但河水一定知道他的去向。\n\n白虎寺附近的山坡上，有一種花長在湖中。這種花只會在心地純潔的人面前綻放。\n\n把六朵月光百合帶來給我，我就能用花與河川對話。", progress = "宗師，收集到月光百合了嗎？", completion = "謝謝你。讓我為你找尋答案。", rewards = nil}
MultiLanguageQuestData['tw'][46350] = {title = "班盧的試煉", objective = "在瀑布底下找到班盧。", description = "啊，我感覺到水中有很強的波動！水珠落下的位置總是不遠。\n\n班盧就在附近。\n\n<琉立閉上雙眼，將百合放入水中。百合緩緩飄向東方。>\n\n班盧正在東邊瀑布底下等你。", progress = nil, completion = "我很榮幸能背著你從心光廟走到五晨寺，這是歷來傳統。每一代宗師都走過這條路。", rewards = "您會學到：\n\n班盧，宗師良伴\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][46351] = {title = "仔細藏好以策安全", objective = "到守護者殿堂找亞莉。", description = "你找到的護盾產生器沒有表面上那麼單純。我的長老們想必不會同意與外來者分享如此先進的科技…\n\n然而…你救了我們的性命、賦予我們自由。\n\n我同意讓你們使用。只是…關於它的存在，請謹慎保密，大法師<name>。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大廳資源"}
MultiLanguageQuestData['tw'][46353] = {title = "哪位大師？", objective = "到五晨寺外晨風村與卜大師會面。", description = "你好，我剛接獲消息，卜大師從漫長的靈魂之旅回來了，正在五晨寺外的晨風村休息。\n\n大家已經好一陣子沒見到他或聽到他的消息了，但他指名要跟你見面。\n\n宗師，別擔心這裡，快出發吧。", progress = nil, completion = "謝謝你過來，宗師。", rewards = nil}
MultiLanguageQuestData['tw'][46360] = {title = "讓人頭暈目眩", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46499] = {title = "蜘蛛，是嗎？", objective = "在蜘蛛岩洞尋找傳聞中的寶藏。", description = "我感覺好像牠們還在我身上爬來爬去。我才壓破一顆蛋，突然從頭到腳都爬滿了小蜘蛛。\n\n<打了個寒顫>\n\n結果寶藏就丟在那裡沒人拿。下一個去尋寶的人最好別是蜘蛛控制狂…呃，蜘蛛空氣槍？蜘蛛恐怖症？反正就是怕蜘蛛的意思！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n合成立方氧化鋯"}
MultiLanguageQuestData['tw'][46500] = {title = "薩格拉斯之墓：深淵傳說", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][46501] = {title = "盜墓", objective = "在靈魂遺跡尋找傳聞中的寶藏。", description = "我不是盜墓者，不過，如果寶藏就直接放在一大堆骨頭上，這樣算是盜墓嗎？它又沒被埋起來。以防萬一，我這次還是先不參加好了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n精緻珠寶鑰匙"}
