MultiLanguageQuestData['tw'][47129] = {title = "薩格拉斯之墓：欺詐者", objective = "在薩格拉斯之墓中擊敗基爾加丹。", description = "只有欺詐者基爾加丹最強大的僕人才會佩戴這種徽印。這表示基爾加丹已經來到薩格拉斯之墓了。我們必須打倒基爾加丹。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n惡魔寶箱"}
MultiLanguageQuestData['tw'][47130] = {title = "非正式喪禮", objective = "使用祭儀火炬，燒毀贊達拉屍體。", description = "鮮血食人妖利用我們人民的屍體來進行他們的鮮血魔法。今天我要終止這場惡行。\n\n我會處理這些屍體。這把火炬給你，它的火焰受到伯昂撒姆第祭司的祝福。伯昂撒姆第是掌管死亡的羅亞。\n\n你必須燒掉我們人民的每一具屍體。每燒掉一具屍體，這些怪物的鮮血魔法力量就會減弱一分。", progress = nil, completion = "我的人民不應該遭受如此待遇。等這件事結束後，我們會在祖達薩為他們進行適宜的祭祀儀式。", rewards = "剝皮儀祭手套納茲曼戰鎧護手羅亞語者的手套死亡誓願護手納茲曼戰鎧護脛羅亞語者的護腿死亡誓願護腿剝皮儀祭馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][47132] = {title = "魔焰與冰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47134] = {title = "阻止燃燒軍團劫獄", objective = "在燃燒軍團救出高階審判官雷加爾之前找到他。", description = "高階審判官雷加爾和阿古斯的惡魔有某種連結，使他成為不死之身。很久以前，那魯把他囚禁在亞克崔茲。 \n\n當凱爾薩斯‧逐日者的部隊攻擊城塞時，我們被迫乘上艾克索達逃走。\n\n在燃燒軍團最近一次入侵艾澤拉斯時，有些惡魔囚犯逃出了亞克崔茲，不過雷加爾還在。絕對不能讓這些惡魔把他救出去，我會研究他的秘密，想辦法破解他的不死之身。\n\n我可以把你送到附近，剩下的就靠你自己了。", progress = nil, completion = "你已經盡力了，&lt;name&gt;，但惡魔終究是贏了這一回合。\n\n雷加爾很快就會得到力量並且攻擊我們。不過在你忙著阻止他的時候，我已經發現他永生不朽的秘密了！", rewards = "您會收到：\n\n虛無之核控制棒"}
MultiLanguageQuestData['tw'][47135] = {title = "為了他們好", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47137] = {title = "軍團之殞勇士", objective = "回到你的職業大廳，然後招募一名新勇士。", description = "奪回破碎海岸的戰爭耗用了我們大量資源。但我們絕不能鬆懈，否則燃燒軍團會一舉顛覆我們所有的努力。\n\n你的組織成員已經付出了許多，但我們還需要他們繼續支援。\n\n召集你的勇士、盡可能提升戰力。這片土地中或許還有我們還沒發現的力量，能夠幫助我們扭轉戰勢。", progress = nil, completion = "&lt;name&gt;，你又幫我們找到了一名強大的盟友！\n\n對抗燃燒軍團的戰力又增加了一些。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47139] = {title = "魔巡號印記", objective = "收集50個魔巡號印記。", description = "魔巡號從天而降，讓破碎海岸陷入恐懼之中，惡魔像洪水般不斷湧入，襲擊我們的部隊。它們想阻止我們拿下薩格拉斯之墓。\n\n它們要失望了。\n\n去吧，把最強大的惡魔引誘出來，然後殺掉，奪取這些惡魔身上的印記。讓燃燒軍團知道我們的實力，讓它們學會恐懼！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n已逝世界的裂片"}
MultiLanguageQuestData['tw'][47148] = {title = "別開生面", objective = "贏得一場PvP亂鬥。", description = "即便是最嗜血的鬥士，也會逐漸心生厭倦，最終徹底遠離這場永無止盡的戰爭糾葛。他們想用新的方式來證明自己的勇武、消滅他們的敵人。\n\n加入這場決鬥，在一場拋開傳統規則的限時事件中，與對手交戰。", progress = nil, completion = "沒想到會有這種戰場。", rewards = "您會收到：\n\n榮譽獎章征服點數榮譽點數青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][47180] = {title = "脈動的瘋狂", objective = "驅散5個虛無化身。", description = "這個破碎者還是有神智清明的時候，雖然並非總是如此。\n\n我能感覺到附近有虛無能量，不過力量很有限。驅散這些虛無的化身可以讓這個破碎者神智清楚一點。\n\n或許我們可以用你找到的導言碎片，那上面還有聖光的力量。\n\n我會想辦法弄清楚他說的話是什麼意思，或許我們能釐清這裡究竟發生了什麼事。", progress = nil, completion = "我感覺到虛無的影響在消退。或許我們現在可以弄清楚這裡發生了什麼事。", rewards = "您會收到：\n\n沐聖祈禱刻像朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47181] = {title = "冒煙的槍", objective = "使用弗林的手槍，朝港口統領辦公室的水桶開槍。", description = "艾胥凡公司那群蠢貨！把你扔進托達戈爾是他們犯過最嚴重的錯誤。\n\n我們偷來的這種新粉末，可能是擊敗他們的關鍵。\n\n我們先向大家展示一下這東西的威力吧？\n\n<弗林捏起一小撮發光的粉末塞進手槍裡。>\n\n去吧，朝那兒的桶子開槍看看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47182] = {title = "死期已屆", objective = "標記阿古斯心井的位置，以利梵迪卡爾的槍砲瞄準。消滅燃燒軍團守軍，並從高階審判官雷加爾身上取得阿古斯的惡魔之心。", description = "我明白了很多事。高階審判官雷加爾的大本營就在山脈另一邊的燃燒軍團城塞附近。他把自己永生不死的泉源，也就是阿古斯的惡魔之心藏在那裡。惡魔之心則是從直接通往阿古斯核心的魔心泉井裡得到能量。\n\n他打算攻擊你，所以你一定要先下手為強。標記出泉井的位置，我會用梵迪卡爾的槍砲降下神聖之火消滅這些泉井。只要雷加爾與阿古斯魔能的連結沒了，我們就可以殺了他，拿到惡魔之心。", progress = "你把高階審判官雷加爾解決掉了嗎？", completion = "你真是個英雄，&lt;name&gt;。就算惡魔們救出了永生不死的雷加爾，他也不是你的對手！或許惡魔之心對你來說會有用處，在系統核心可以看到，由你自由運用。", rewards = "您會學到：\n\n阿古斯的惡魔之心\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47183] = {title = "阿卡漢的計畫", objective = "跟隨阿卡漢前往艾索隆。", description = "阿卡漢記起來了。他記得會…對…會出現救星。\n\n跟阿卡漢來。艾索隆在呼喚！我們要奉獻溫柔的話語給聖光。聖光會消滅黑暗。\n\n<阿卡漢帶著戒心打量著艾蘭里亞。>\n\n阿卡漢會小心盯著這個人。", progress = nil, completion = "我早該知道會這樣的。", rewards = "您會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47184] = {title = "阿卡漢的歷險", objective = "前往虛無裂口面對阿卡漢。", description = "不管呼喚他的是什麼，一定不懷好意。我們有必要跟他一起去。\n\n<name>，在我們走進傳送門之前…要做好戰鬥的準備。虛無造成的影響很少會是好事。", progress = nil, completion = "跟我想的一樣，虛無造成的影響不會是什麼好事。我們得繼續前進。", rewards = "您會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47186] = {title = "賢者聖所", objective = "在賢者聖所跟第七軍團法師說話。", description = "看來我們接下來要一起合作了。\n\n雖然塞勒斯已經安排了往來暴風城的航線，但我想你平日應該會想要更便捷的交通方式。\n\n等一下上樓，出去左轉，會看到浪潮賢者研究魔法儀式的實驗室。\n\n你們聯盟法師應該也知道那間房間的力量。\n\n請跟那些法師說，如果他們想開傳送門，可以開在那個房間。港口的守衛會確保房間安全無虞。", progress = nil, completion = "都安排好了？\n\n你來得正好，你要的報告來了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47188] = {title = "羅亞的援助", objective = "與塔蘭姬和洛克漢討論，決定你的下一步。", description = "可惡的古翰，讓鮮血食人妖變得更強了…現在他們正在強化一個巨大的魔像！\n\n我們必須好好計畫一下，才能摧毀那個魔像、古翰和鮮血食人妖，這恐怕不是件容易的事。\n\n不過，我想到一個方法了。", progress = nil, completion = "唯有請羅亞幫忙，才有辦法阻止鮮血食人妖。\n\n我們趕快採取行動吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47189] = {title = "王國分裂", objective = "查看港口統領辦公室的偵察地圖。", description = "庫爾提拉斯必須團結，才能成為聯盟的助力。\n\n我們先弄清楚各大領地的局勢。\n\n然後你可以參考後面這個地圖，決定接下來從哪裡展開行動。", progress = nil, completion = "我們會盡力支持你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47198] = {title = "留我們活口", objective = "治療8個受傷的俘虜。", description = "鮮血食人妖的毒藥足以令人癱瘓，但還不至於致命。看來他們打算留我們活口。\n\n看來我最好不要去想原因。\n\n我盡快製作了一些解毒劑，但我需要像你這樣的人去幫忙測試效果。拿著我製作的所有藥劑，看看能不能讓那些士兵復元。", progress = nil, completion = "解毒劑有效？太好了！我會找幾個傷者幫忙我，多做一點藥劑。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47199] = {title = "血門", objective = "前往血門。", description = "我們剛剛收到消息，有一支鮮血食人妖的部隊在侵略我們的北方邊境。\n\n神王拉斯塔哈正在呼叫援軍。\n\n你比我們任何人都瞭解這股威脅勢力。快過去盡你所能地協助他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47200] = {title = "嗜血生物", objective = "殺死6隻血腹飛行者。", description = "殺了那些血腹飛行者，別讓牠們把全部的士兵都帶走！我會命令部隊準備從側面出擊。", progress = nil, completion = "終於可以喘息一下了。我們應該趁現在主動出擊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47201] = {title = "洛克漢", objective = "騎乘老洛塔納加入戰鬥並找到洛克漢。", description = "我的斥候回報說，你的暗矛暗影獵手洛克漢已經從納茲米爾回來，現在被困在遠方的大門那裡。\n\n我們需要從側面進擊才能突破這輪猛攻。\n\n老洛塔納已經就位了。騎上牠，從側邊擊潰鮮血食人妖的部隊吧。\n\n到那邊之後，就去找洛克漢。\n\n噢，$p，小心一點。那個地方可是充滿了黑暗魔法。", progress = nil, completion = "哈！還以為我就快要跟伯昂撒姆第相見歡了。看來不會。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47202] = {title = "國王口信", objective = "跟預言者費倫說話。", description = "我要去破碎海岸，我想親眼看看父親死去的地方。\n\n只有像父親那麼偉大的國王，才配得上暴風城…我必須親身體會人民面臨的威脅，才有可能像父親那麼偉大。\n\n請跟所有諫言者說我去破碎海岸了。我應該親自告訴他們的，但這樣他們就不會讓我去了。\n\n我先去審判角等你。再見。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47203] = {title = "幽影幢幢", objective = "跟艾蘭里亞‧風行者和暗域行者一起調查影幽谷。", description = "那是暗域行者，我對虛無所了解的一切，都是他教我的，不過這還不是他的全副本事。\n\n要是他在這裡，那這個以太族的出現就讓我覺得更蹊蹺了。我以為他們族裡像他這樣的就只有一個，但我現在發現另一個跟虛無深有淵源的…\n\n來吧，如果想知道他了解些什麼，就必須照他的遊戲規則走。看樣子他是往北邊的影幽谷去了。", progress = nil, completion = "&lt;艾蘭里亞似乎突然說不出話來。&gt;", rewards = "您會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47204] = {title = "全新陣線", objective = "消滅鮮血食人妖部隊。", description = "殺死贊達拉人以外的所有生物！", progress = nil, completion = "這樣看起來數量是很多，不過相信我，後面還有更多敵人等著我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47205] = {title = "戰母", objective = "殺死戰母夏茲瑞卡。", description = "老洛塔納被那些邪惡的鮮血食人妖帶來的戰母詛咒了。我們必須殺死她，才能讓這頭老恐角龍重回戰場。", progress = nil, completion = "那個邪惡的東西殺死了跟我一起來的半數斥候。你做得很好。", rewards = "鮮血圍城披氅您能選擇下列奬勵中的一個：\n\n夏茲瑞卡的詛咒之戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47217] = {title = "黑暗之源", objective = "關閉5個虛無集能器。", description = "<name>，我想我能理解他想告訴我們的事。\n\n我感覺到前面有一股正在凝聚的力量，它們一定是要把虛無召喚來這裡。\n\n我們得阻止它們讓這整座城市陷入黑暗。找到那個來源，不管用什麼方式都一定要阻斷。\n\n我跟暗域行者還有事情必須完成。", progress = nil, completion = "我們頂多是爭取到一點時間。", rewards = "您會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47218] = {title = "影衛哨站", objective = "殺死15個以太族影衛。", description = "你現在應該已經明白了，我有一些同胞向虛無的呼喚屈服了。\n\n我原本希望有更多意志堅強的人能抵抗誘惑，但卻不是如此，這讓我很失望。\n\n我也感到很無奈，如果要達到我們的目標，就必須消滅這些意志薄弱的生物。", progress = "<name>，鋌而走險就是要承擔風險。", completion = "我很高興知道我們的目標一致。或許我會需要你們的幫忙。", rewards = "您會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47219] = {title = "做好準備", objective = "擊敗納拉索斯並取得他的心臟。", description = "經過考慮之後，我決定再給艾蘭里亞一次追尋命運的機會。\n\n我想你不明白我的意思，凡人。\n\n<暗域行者笑了。>\n\n前面有一座影衛營地，到營地的深處跟我會合，我的同胞會準備召喚儀式，為風行者提供足夠的能量。\n\n你會親眼目睹她獲得操控虛無的力量。", progress = "<name>，我很清楚要走的路。", completion = "&lt;艾蘭里亞拿起心臟。&gt;\n\n這就是下一步，&lt;name&gt;。謝謝你這一路的協助。", rewards = "您會收到：\n\n餘留的虛無迴響朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47220] = {title = "黑暗中的信標", objective = "返回梵迪卡爾，把納拉索斯的殘軀帶給費倫。", description = "剛剛…還真驚險。\n\n<艾蘭里亞揉著她的額頭。>\n\n呃，我無法集中精神。我需要你幫忙回去找費倫，把這個交給他。\n\n<她把某個沉甸甸的冰冷物品放在你手上。>\n\n我不知道為什麼，但是我覺得他應該看看這個東西。\n\n把我們的發現告訴他。羅穆爾一定在觀察我們的行動，要是幸運的話，他應該已經幫我們設置好信標了。", progress = "這是什麼？好黑暗…", completion = "&lt;name&gt;，你帶了什麼來？\n\n\n\n這個東西啊…", rewards = "您會學到：\n\n光鑄信標：影衛哨站\n\n您還會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47221] = {title = "命運之手", objective = "在暴風港跟要護送你前往艾克索達的人會合。", description = "$p，\n\n我們讓燃燒軍團節節敗退，如今是該一舉結束這場戰爭的時候了。\n\n遠征阿古斯的準備工作已經進入最終階段。\n\n請盡快前往暴風港。那裡的船艦會帶領你和你的盟友前往藍謎島。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47222] = {title = "走海路", objective = "跟凡蕾莎‧風行者交談然後航向艾克索達。", description = "薩格拉斯之墓的戰役只不過是個開始。如果不徹底摧毀燃燒軍團，它們早晚會東山再起，而且更為強大。\n\n我們會先經由海路前往藍謎島，避人耳目。燃燒軍團越晚發現我們的行動越好。\n\n準備好出發就跟我說吧。", progress = nil, completion = "願聖光保佑我們所有人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47223] = {title = "聖光出征", objective = "前往艾克索達的聖光地窖跟預言者費倫碰面。", description = "預言者費倫和其他人都去聖光地窖集合了。沿著這條路走下去就會看到入口。\n\n我們最好馬上去找預言者，以免延誤進攻的時機。", progress = nil, completion = "感謝聖光，你來了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47224] = {title = "梵迪卡爾", objective = "登上梵迪卡爾。", description = "一切都準備好了。我們只要建立傳送到船艦所需要的信標，就可以展開進攻了。\n\n信標部署好以後，用手輕觸信標表面就能傳送到梵迪卡爾。梵迪卡爾是要帶領我們復仇的船艦。", progress = nil, completion = "我等這一天已經等很多年了。\n\n看看德萊尼的榮耀：梵迪卡爾！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47226] = {title = "小恐角龍孤兒", objective = "在戰獸欄找到能照顧小恐角龍的人。", description = "<倖存的小恐角龍看著牠母親的屍體，可憐兮兮地嗚咽著。\n\n牠用滿懷希望的眼神看著你，似乎想跟隨你。\n\n或許你能在附近的戰獸欄找到人照顧牠？>", progress = nil, completion = "你就是大家在說的部落人？我還以為你會更壯一點。哈！\n\n嘿！你帶了什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47228] = {title = "席帕拉生態", objective = "殺死8個席帕拉捕獵者。", description = "我真的很希望這個地方不要這麼可怕。\n\n無論如何，贊達拉人對於淨空此地進行考古探索，真是一點忙都幫不上。在我們開始探查席帕拉的秘密之前，我們必須保證這裡安全無虞，讓那些不擅長戰鬥的人好好做事。\n\n你會發現前面的遺跡已經被各種肉食性野獸入侵。膽敢前往冒險的勇者全都沒能回來。\n\n絕對不能讓這裡的生態阻礙我們的進展，<name>。懂了嗎？", progress = nil, completion = "聽說這個地區很適合這種生物居住。就讓牠們到…其他地方去繼續繁衍吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47229] = {title = "托卡利壁壘", objective = "騎乘老洛塔納衝上戰場對抗鮮血食人妖。", description = "至少我們讓老洛塔納振作起來了。做好駕馭她的準備吧。\n\n掩護我們，這樣塔蘭姬才有辦法一路打過來。", progress = nil, completion = "謝謝你！不過我們不能留在這裡。又有鮮血食人妖來了。我父王呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47235] = {title = "拭目以待", objective = "在席帕拉放置3架占卜儀。", description = "我們在幫部落找一個叫席帕拉之眼的聖物。\n\n但這裡的人完全派不上用場，泰夏拉小姐堅持要我們使用她的勘察設備。\n\n我討厭瞎猜。我想改用更直接的方法：占卜術。\n\n我會在地圖上標記三個地點，我想在這三個地點各放一架占卜儀。占卜儀收集到的數據可以把聖物的方位分析出來，然後我們就可以開工了。", progress = nil, completion = "做得好。等我一下，我看看數據，然後就可以出發了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47238] = {title = "三傑議會之座", objective = "尋找知識之冠。", description = "我們拿到了覺醒符印，但是需要完整的三傑聖物才能發揮作用。\n\n就算明知道路拉在三傑議會之座等著我們，我們還是深入險地。\n\n這是九死一生的任務，要不是因為非這麼做不可，我絕對不會要求你們。\n\n我們一起下去吧，跟我來。", progress = nil, completion = "這的確是壞消息。最好根據艾蘭里亞的線索做好應變計畫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47241] = {title = "死亡之影", objective = "搜尋羅亞伯昂撒姆第所在之處的線索。", description = "我們有四位羅亞，但是我們只知道…伯昂撒姆第的下落。\n\n這讓我相當不安，而我準備好了，會不計代價阻止鮮血食人妖，就算要與掌管死亡的羅亞接觸也無法阻止我。\n\n幾百年前，伯昂撒姆第在納茲米爾這裡有座神廟。我的占卜師算出北邊幾個地點，我也感應到那裡有某種神靈的存在。去那裡搜尋一下。\n\n動作快，<name>，如果我們不能獲得伯昂撒姆第的協助，祖達薩就會陷落！", progress = nil, completion = "你在找伯昂撒姆第的神廟？你一定是走投無路才會想去那裡。\n\n算你走運，我也要往那裡去。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47244] = {title = "靈魂獻祭", objective = "擊敗鮮血女巫納吉瑪。", description = "只有兩種人會踏進伯昂撒姆第的神廟，那就是想跟死神打交道的人，或是死人。你身體沒有發臭，所以我猜你是想去打交道。\n\n我也要去神廟，要不要做個交易？\n\n看到過橋之後的地方了嗎？那裡有一名叫做納吉瑪的女巫，我一直在追蹤她的行蹤。鮮血食人妖是爛到骨子裡了，但是他們的靈魂非常適合獻給伯昂撒姆第。那個女巫太強了，我打不贏，如果你殺了她，我就帶你到神廟去。\n\n我保證會帶你去。", progress = nil, completion = "這樣應該就可以了。她的靈魂會是完美的祭品。\n\n現在，在我們去神廟前，還有一件事情要做…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47245] = {title = "獲得訊息", objective = "調查騷動。", description = "雖然羅亞很強大，但是我們需要士兵，才有機會阻止鮮血食人妖。如果我們讓他們完成那個巨像，祖達薩和我們的人民都會完蛋的！\n\n我們需要部落的協助！\n\n這裡的狀況已經通知大酋長了，一旦收到她的回覆，我們就可以行…\n\n等等…那是什麼聲音？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47247] = {title = "亡靈之怨", objective = "擊敗妖術女祭司提澤雅與督軍瑪拉賈。", description = "伯昂撒姆第知道你為何來此，你來尋求我的幫忙。\n\n<伯昂撒姆第沉靜地估量你。>\n\n我有一項考驗，來瞧瞧你是否值得伯昂撒姆第花時間。\n\n有些幽魂在讚頌著某個名叫「古翰」的東西，不再信仰我了。在我自己的神廟裡，決不容許如此不敬之事！\n\n去制伏那些最強大的古老幽魂。\n\n若你能辦好這件事，那就值得我花點時間在你身上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "納茲曼戰鎧束腰羅亞語者之索死亡誓願腰帶剝皮儀祭腰帶剝皮儀祭之握納茲曼戰鎧之握羅亞語者之握死亡誓願之握您會收到：\n\n"}
MultiLanguageQuestData['tw'][47248] = {title = "至死不渝", objective = "取得瓦賈布的獠牙戒指。", description = "我不知道你是誰，但是我需要你的幫忙。\n\n我的摯愛瓦賈布告訴我，他要放棄牧師的終身不婚誓約，和我廝守終身。\n\n不過，當我的生命走到最後一刻時，我知道我沒有辦法獨自先走一步。於是我歸來後一直在此地徘徊…有如一輩子之久，但是瓦賈布從未出現！\n\n我在這個世界停留太久了。\n\n拜託，拜託你，把瓦賈布的遺物帶回來給我！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47249] = {title = "靈魂之契", objective = "到靈魂之廷與伯昂撒姆第談話，並且完成儀式。", description = "我交付的任務你做得很好，我認為你很有潛力。或許你值得讓我跟你做交易。\n\n很好，我會賦予你力量，讓你擊敗敵人。條件是，你必須為伯昂撒姆第帶回一百萬條靈魂！別被嚇到，這對你來說應該易如反掌才對。\n\n好，到靈魂之廷找我。我們會在那裡敲定契約剩下的部份。您會學到：\n\n", progress = nil, completion = nil, rewards = "儀祭肢體砍斧曼波妖術斧血儀剁頭斧死亡獵者巨弓死誓之刃強大的魂能放血者墓地看守者的長杖恐怖怪物屠刃您會學到：\n\n伯昂撒姆第的恩澤\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47250] = {title = "後會有期", objective = "前往佐巴爾遺跡，並與漢札布談話。", description = "嗯…你該離開了。\n\n你還需要為伯昂撒姆第將許多鮮血食人妖的靈魂引領到彼界，不過這裡找不到鮮血食人妖了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47251] = {title = "歡樂時光", objective = "前往奧格瑪的精神谷，與歷史學家裘帕會面。", description = "<name>，我不想讓你擔心，但我們可能遇到…時光異常現象了。\n\n你聽過一句話嗎？「過去的事，不會真的過去。」\n\n來奧格瑪精神谷找我吧，我們得好好聊聊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47252] = {title = "歡樂時光", objective = "前往暴風城皇家圖書館，與歷史學家洛爾會面。", description = "<name>，我不想讓你擔心，但我們可能遇到…時光異常現象了。\n\n你聽過一句話嗎？「過去的事，不會真的過去。」\n\n來暴風城皇家圖書館找我吧，我們得好好聊聊。", progress = nil, completion = "你來了，&lt;name&gt;！你一定接到我的信了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47253] = {title = "經典故事", objective = "在詛咒之地擊敗卡札克領主，在艾薩拉擊敗艾索雷苟斯，並在通往翡翠夢境的某個傳送門擊敗夢魘之龍。", description = "很久以前，這個世界到處都是巨大、可怕的怪物，無論多麼弱小的生物都奮勇抵抗。\n\n我所說的就是至高領主卡札克、艾索雷苟斯、夢魘之龍這樣的怪物。\n\n聽說他們的寶物豐厚至極，有人為了奪取寶物，甚至會組軍隊連夜等待機會。\n\n我們發現這些怪物所在之處，剛好就是時間之道發生異常狀況的地點。\n\n你願意去調查嗎？每年到了這時候總是有奇怪的事情發生。", progress = "不過就是回憶嘛！", completion = "我們花一點時間回想過去發生的事吧，不可以忘記歷史的教訓，否則歷史一定會重演，災難就會再次發生。", rewards = "您會收到：\n\n時光扭曲徽章"}
MultiLanguageQuestData['tw'][47254] = {title = "經典故事", objective = "在詛咒之地擊敗卡札克領主，在艾薩拉擊敗艾索雷苟斯，並在通往翡翠夢境的某個傳送門擊敗夢魘之龍。", description = "很久以前，這個世界到處都是巨大、可怕的怪物，無論多麼弱小的生物都奮勇抵抗。\n\n我所說的就是至高領主卡札克、艾索雷苟斯、夢魘之龍這樣的怪物。\n\n聽說他們的寶物豐厚至極，有人為了奪取寶物，甚至會組軍隊連夜等待機會。\n\n巨龍發現這些怪物所在之處，剛好就是時間之道發生異常狀況的地點。\n\n他們要我尋找勇士去調查一番。", progress = nil, completion = "喔，回憶啊。我挺身而出，對付過去的敵人。我從這些戰鬥中獲益良多。擊敗敵人，從中獲取經驗，這些經驗能讓你下次面對擋路的傢伙時，更加游刃有餘。", rewards = "您會收到：\n\n時光好物包青銅龍慶典藏寶箱時光扭曲徽章青銅龍慶典代幣時光扭曲徽章"}
MultiLanguageQuestData['tw'][47257] = {title = "席帕拉的骸骨", objective = "前往席帕拉跟審查員泰夏拉‧血腥看守者說話。", description = "在遙遠的南邊，你會看到一頭遠古生物留下來的白骨。那就是席帕拉，第一頭魔暴龍始祖。她是瑞贊的母親，也是所有魔暴龍的育母。現在那個地方是野獸的天下，贊達拉已經不住在那裡了。\n\n我聽到了一些傳言，指出有你們部落的人抵達那裡，想要在她的骸骨裡面尋找什麼事物。\n\n這樣做實在太莽撞了。去調查這件事，好嗎？", progress = nil, completion = "這是我期待了一輩子的重大發現。我會讓我父親引以為傲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47258] = {title = "攻城準備", objective = "與貝恩‧血蹄交談。", description = "看來我們得為攻城戰做準備了。現在，回到達薩亞洛去找你們部落的人。為接下來的戰事做準備。\n\n要是納茲米爾的部隊湧來，我會送出消息的。", progress = nil, completion = "雖然我們的大酋長未來可能會為某些原因退卻，但我相信我們會帶著榮耀協助贊達拉。\n\n這不只是為了獲得戰爭中的盟友。更是部落創立的初衷，協助那些急需協助的人。\n\n就像索爾曾經保護我的人民一樣，因此我們一定要設法拯救贊達拉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47259] = {title = "照顧恐角龍", objective = "餵食你的恐角龍寶寶。", description = "管理員巴茲寇奇真的很懂得怎麼跟這些小傢伙相處。看來這隻小恐龍會跟著你，是因為巴茲寇奇已經死了。\n\n我沒有那麼多時間再去找新的管理員，你能幫我做件事嗎？\n\n這件事不輕鬆，而且這些小恐龍很快就會認定你。要是你照顧牠，就等於立下承諾。小傢伙會很依賴你，我希望你能照顧牠，別讓牠挨餓或受傷。\n\n不過最重要的還是食物。圍欄和下面的河邊有很多可以吃的東西。", progress = nil, completion = "做得不錯，恐角龍寶寶看起來變強壯了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47260] = {title = "可能會有副作用…", objective = "在戰獸欄與獸王洛卡拉交談。", description = "<你的恐角龍夥伴一直在打嗝。每次打嗝體型都會隨之變大或縮小。牠沮喪地對著你嗚咽。 \n\n你可能需要找人幫忙。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47261] = {title = "恐角龍訓練指南", objective = "和戰獸大師布克霍交談，選擇訓練你的恐角龍。", description = "不管你餵你的小寶貝吃什麼，我也要來一點 - 哇！\n\n現在牠長大了，該把牠訓練成為可靠的戰鬥夥伴了。\n\n我們來看看，牠會怎麼面對困難的挑戰？\n\n當你準備好要開始時，和戰獸大師布克霍談話。", progress = nil, completion = "好險。至少看起來很有娛樂效果！哈哈哈！\n\n我想你們很快就會佔有一席之地！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47262] = {title = "消滅鮮血食人妖", objective = "殺掉鮮血食人妖的女族長艾提娜。", description = "羅亞今天對我們露出了微笑。這些鮮血食人妖的「女族長」就在前方，她是一個叫做艾提娜的恐怖怪獸。\n\n計畫有些變動，<name>，我們現在就來解決這個威脅。只要殺掉艾提娜，鮮血食人妖就會陷入混亂。\n\n她是個很強的妖術師。你先開始戰鬥，我會趁她鬆懈時偷襲。\n\n我們開始動身吧。我們得在今天結束前回到祖達薩。", progress = nil, completion = "艾提娜休想逃出我們的手掌心。繼續追。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47263] = {title = "揭曉時刻", objective = "協助塔蘭姬公主追擊艾提娜。", description = "我感覺到艾提娜的黑暗魔法從前方傳來。不管她打算為這個「古翰」做什麼，我們都要阻止她。\n\n準備好面對各種狀況，<name>，我們不清楚艾提娜的力量究竟是什麼。\n\n不過我知道一件事，如果古翰威脅到我的人民，他就非死不可，就像艾提娜一樣。", progress = nil, completion = "鮮血食人妖帶來的威脅比我想像的更大，那個魔像的威力足以摧毀整個祖達薩。\n\n除了部落，我們需要借助其他外力才能制止他們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47264] = {title = "不留活口", objective = "殺掉6名鮮血食人妖。", description = "現在你知道我的父親拒絕承認的事實是什麼了。鮮血食人妖在屠殺我們的人…我們一定得阻止他們。\n\n<name>，計畫很簡單，我們出發，去解決鮮血食人妖，能殺多少就殺多少。你往東，我往北。\n\n之後和我碰頭，我們看看還有什麼能做的。我們要讓這些鮮血食人妖畏懼贊達拉！", progress = nil, completion = "完成了？很好，距離我們的目的又更進一步了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47272] = {title = "恐角龍生長激素", objective = "收集10塊冒著熱氣的新鮮腐肉。", description = "你這隻小動物真可愛。但牠這麼小，恐怕只會是個麻煩。\n\n想幫你的朋友賺點錢嗎？這可是個大好機會，可是那些食人妖都不聽我的！\n\n我告訴你，我會做一種營養補充品，可以讓你的胸口長毛！呃，是你這隻小恐龍的胸口！\n\n我知道恐角龍吃素，但那些大型掠食者吃肉可是有原因的！\n\n想要快速成長需要攝取蛋白質，很多很多蛋白質。\n\n有興趣嗎？", progress = "如何？拿到我要的所有東西了嗎？", completion = "肉是種很神奇的東西，你懂的！\n\n呃，至於細節嘛，現階段你還是先保密好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47283] = {title = "大刀闊斧！", objective = "找一把耐用的斧頭，從附近小樹收集5份剛砍下來的木頭。", description = "你好，<name>。\n\n我一直在留意斧頭技術出眾的高手。\n\n如果你有辦法輕鬆移除那株小樹，我一定能幫你找到更適合的工作。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n伐木工之斧\n\n您還會收到：\n\n木頭"}
MultiLanguageQuestData['tw'][47287] = {title = "梵迪卡爾系統核心", objective = "把聖光審判連結到梵迪卡爾系統核心。", description = "在阿古斯發生的很多事情讓我感到憂慮，但我更為瑟拉的命運憂心。有時候我會想，我們所做的真的是對的嗎？\n\n但我們必須堅持下去。我會處理好梵迪卡爾的系統核心，讓你們在需要的時候可以呼叫這艘船艦上的火力支援。\n\n到這艘船中央的船艙裡，系統核心就在裡面。只要連結上，不管是現有的能力或者未來獲得的能力，你都可以自由運用。", progress = nil, completion = "現在，你只要使用核心傳輸器，就可以呼叫聖光審判火力支援。\n\n或許在旅途中，你會找到其他可以連結到系統核心的東西。我已經重導了足夠的力量到系統核心，不管你連結什麼都不會有問題。 \n\n一切順利，我的朋友。", rewards = "您會學到：\n\n聖光審判\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47289] = {title = "熊熊和茶茶", objective = "找到啃滋龍先生、小象鼻和史椎市長來參加下午茶會。", description = "這裡沒有人可以陪我一起玩，但是這位<先生/女士>，你可以，對不對？\n\n喝茶的時間到了！拜託你，幫我把其他客人帶過來！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47290] = {title = "世界事件地城 - 胡默爾", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47310] = {title = "小睡時間", objective = "在獸欄裡安頓你的恐角龍。", description = "經過如此刺激的一天，你那隻不怎麼小的傢伙看來有點累。我敢說你們兩個都需要休息，對吧？\n\n等你們恢復精神以後再來吧。", progress = nil, completion = "這段時間我會幫你照顧這個小傢伙。你就繼續去冒險吧，去多了解一下贊達拉的一切。等你們倆都準備好了，我會有事情給你們做的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47311] = {title = "看我的頭錘", objective = "協助你的小恐龍與12個生物作戰。", description = "看來你的小恐龍養得不錯。很好。繼續保持下去。\n\n接下來，你要教小恐龍怎麼保護自己。在野外，恐角龍是很多大型生物的獵物，對羽冠龍這類的生物來說，小恐角龍是很容易得手的獵物。\n\n到荒野之中，教你的小恐龍該怎麼抵擋這些生物的襲擊。\n\n關鍵就在牠的角，<name>。", progress = nil, completion = "我在你的小恐龍眼神中看到了自信。很好。牠就需要自信。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47312] = {title = "女王之羽", objective = "殺死女王之羽，並拔下一根她的羽毛。", description = "啊，就是你接手了巴茲寇奇的那群恐龍對吧。反正也所剩不多了。\n\n我知道是誰殺了他，我早就警告過他了。女王之羽是頭惡毒的暴掠龍，比其他的恐龍更巨大、也更聰明。這附近大多數的蛋都是她生的。\n\n我通常會讚賞野獸的力量，但她已經變成一個大麻煩了。\n\n你可以在餵食場看到她正在守著自己的巢穴。殺死她，拔下她頭上的一根羽毛做為證明。", progress = "女王之羽還在煩我們嗎？", completion = "很好。現在少了那頭嗜血的恐龍，或許我們可以再安排一個人，回去看管那一窩野獸…嗯。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47313] = {title = "謹慎討論", objective = "詢問達薩亞洛的執法者。", description = "賈克拉傑將軍不值得信任。\n\n他另有目的，但我不清楚是什麼。\n\n不管是誰質疑他的行動，都會被他埋進沙裡。\n\n只要他還握有權力，我的城市就不得安寧。\n\n跟他的護衛談談，看看能不能有什麼發現。記得小心行事，我們可不想引起賈克拉傑的注意。", progress = nil, completion = "到處問這種問題，你只會樹立敵人，不會交到朋友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47314] = {title = "流放的謠言", objective = "跟隨刃衛卡嘉。", description = "塔蘭姬派你來的，是吧？\n\n公主該知道的是，現在公開提出這種問題可是一點都不安全。\n\n戰衛洛琪拉大膽地問了，從此以後就音訊全無。\n\n謠傳她已經被流放到沃魯敦去了。", progress = nil, completion = "我們不會讓洛琪拉和她得到的情報消逝在沙漠之中。", rewards = "您能選擇下列奬勵中的一個：\n\n豁免之鍊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47315] = {title = "前進沙漠", objective = "飛到沃魯敦的沙漠尋找戰衛洛琪拉。", description = "無論洛琪拉發現什麼，重要性絕對非同小可，才會被宣判死刑丟到沙漠裡。\n\n我們必須到沃魯敦找她。\n\n絕對不能讓洛琪拉所知道的賈克拉傑秘密，與她一起埋葬在沙丘裡。", progress = nil, completion = "這些蛇人一定要為今天對我家園的所做所為付出代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47316] = {title = "沙裡的秘密", objective = "找回日誌的遺失書頁。", description = "我找到這本埋在沙裡的日誌。\n\n基羅想把它丟進火裡燒了。\n\n「我們的貨車沒有空間放日誌，米若。那東西又有什麼用途？」\n\n別告訴他是我講的，但我覺得這實在太神奇了！你能想像裡面埋藏了什麼樣的秘密嗎？\n\n有好幾頁不見了，但我敢說你可以在沙丘裡找回這些書頁！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47317] = {title = "尋找倖存者", objective = "在失事地點附近尋找倖存者。", description = "看到你平安無事真好，其他人怎麼樣了？他們在沙漠裡死了嗎？\n\n你必須回到失事地點，看看其他人是否還活著。\n\n我會到處問問，看看這些狐狸人有沒有洛琪拉的消息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47319] = {title = "救命毒素", objective = "收集15個沙刺蜂毒腺。", description = "米若在沙丘裡找到你的朋友。閃電差點就要了她的命。要是不治療的話也活不成的。\n\n林地裡面的黃蜂刺人很痛，但牠們的毒素也有促進康復的效果。\n\n我能從牠們的腺體中萃取所需的物質。\n\n只要有足夠的毒素，我們應該就能治療你朋友的傷勢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47320] = {title = "油膏療法", objective = "在刃衛卡嘉身上使用滋補油膏。", description = "這是我答應給你的油膏，應該能治療你朋友的傷。\n\n把它抹在任何外露的傷口上。\n\n應該會立即見效。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47321] = {title = "拿回小玩意兒", objective = "在巨蛇之顎從塞斯拉克人手中收集6個小玩意兒。", description = "妮莎告訴我你來這尋找一名被放逐者。叫做洛琪拉的人？\n\n我們不認識她，但我們或許能幫你找到她。\n\n你幫我們，我們就幫你。一言為定？\n\n我們靠回收度日。我們把找到的物品拿來交易，但襲擊我們地穴的塞斯拉克人搶走了不少小玩意兒。  \n\n我很清楚塞斯拉克人十分殘暴，但從來沒想過他們會如此貪婪。\n\n把塞斯拉克人拿走的東西帶回來，我就會為你提供一條穿過沙丘的安全道路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47322] = {title = "協助逃難", objective = "從巨蛇之顎中救出哈卡希和奇普。", description = "就算塞斯拉克很強壯，但我們速度快。嗯，至少我和梅卡魯夠快。\n\n我們被緊追不放，勉強逃回貨車。\n\n我猜，其他人就沒那麼幸運了。我們等了好一陣子，卻沒有他們的蹤跡。\n\n如果你打算進入深處，能不能找找我們的朋友？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "流放精兵足靴末風便鞋強韌流亡者長靴灼沙薄靴流放精兵巨腰帶末風之索強韌流亡者腰鍊灼沙腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][47324] = {title = "意想不到的盟友", objective = "飛往虔信者聖所。", description = "我相信這就是其中一把守護者之鑰！但只有瓦里克才知道是不是。\n\n我們得馬上前往聖所。\n\n等你準備好以後，我的翼手龍可以帶我們飛過去，但我們動作要快一點。", progress = nil, completion = "我們不能讓那些無信者佔領這座神廟！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47327] = {title = "回敬他們的攻擊", objective = "在廢棄地穴殺掉塞斯拉克。", description = "這些塞斯拉克攻擊了我們的地穴，不能就此放任不管。\n\n他們必須瞭解，在沙漠中的一切作為，都要付出代價。\n\n塞斯拉克唯一能理解的語言就是血債血還，我們就讓他們嚐嚐這個教訓。\n\n<妮莎停下來看著你，懷疑你是否知道她在說什麼。>\n\n我指的是，我們得宰掉這邊的塞斯拉克。誰都別放過。", progress = nil, completion = "他們的鮮血流下沙丘，倒灌回他們的要塞裡。如果這些塞斯拉克還有膽子再攻擊我們的地穴，一定會三思而後行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47329] = {title = "一脈相傳", objective = "幫泰夏拉‧血腥看守者尋找席帕拉化石。", description = "你好，<name>。\n\n我謹代表我父親，高階審查員泰瑟連‧血腥看守者，到這裡檢視所有出土的化石、文物和神器。\n\n我的消息來源告訴我，有個物品能讓部落如虎添翼的東西，就埋藏在這裡。\n\n我需要你的協助才能把它挖出來。你也知道，這些夜裔精靈動作實在說不上靈巧。他們也不太喜歡親自動手。\n\n能不能請你好心幫忙，做個榜樣給他們看看？", progress = nil, completion = "你還真的動手挖！太神奇了。我們夜裔精靈可是無所不用其極地避免親自動手呢。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47330] = {title = "世界之魂的恐懼", objective = "在休拉薩盆地與麥格尼碰面，並聆聽他的警示。", description = "勇士，麥格尼需要你幫忙！\n\n代言者有話要告訴你，好像是來自艾澤拉斯的消息。他聽不懂艾澤拉斯想說什麼，但…還是讓他自己解釋吧。\n\n他在北裂境的休拉薩盆地，馬上就會聯絡你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n防衛傀儡識別碼"}
MultiLanguageQuestData['tw'][47332] = {title = "你的下一步", objective = "選擇你在贊達拉想進行的下一步。塔蘭姬公主計畫朝北前往納茲米爾。她認為那裡的鮮血食人妖是個威脅，她父王卻不願認真看待這件事。\n\n賈克拉傑將軍憎恨部落，這個人也不值得信賴。只要他還能掌權，這個城市就不可能安全。\n\n你也會需要在祖達薩贏得神王拉斯塔哈的信任。這座城市很大，也有許多秘密。", description = "塔蘭姬公主計畫朝北前往納茲米爾。她認為那裡的鮮血食人妖是個威脅，她父王卻不願認真看待這件事。\n\n賈克拉傑將軍憎恨部落，這個人也不值得信賴。只要他還能掌權，這個城市就不可能安全。\n\n你也會需要在祖達薩贏得神王拉斯塔哈的信任。這座城市很大，也有許多秘密。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47416] = {title = "三傑議會之影", objective = "返回梵迪卡爾。", description = "塔爾加斯所說的話比我想像中更有份量。他在最後想傷害我而說的那句話，給了我們答案。\n\n知識之冠就在三傑議會之座，而且受到嚴密的看守。\n\n如果我懷疑的事情沒錯，眼前會遇到無法想像的威脅。\n\n黑暗那魯。\n\n我們應該回梵迪卡爾去計畫下一步該怎麼做。", progress = nil, completion = "我很擔心路拉，這真是…難以置信。\n\n她一定受了很多折磨…", rewards = "您會學到：\n\n基爾加丹高臺世界任務\n\n您還會收到：\n\n光鍛骨鎧"}
MultiLanguageQuestData['tw'][47418] = {title = "成長之痛", objective = "餵你的恐角龍寶寶服用恐角龍生長激素。", description = "這些食人妖還真是錯過了大好機會！他們總是抱怨野獸不夠用，但是他們試過大量配種了沒？沒有！\n\n有了我的恐角龍生長激素，牠們很快就會擠滿獸欄！當然，數量過多會有疾病和排泄物的問題，但我相信這些問題都可以解決。\n\n哈哈哈，這一定會很棒！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47422] = {title = "情勢危殆", objective = "殺死崛加達。", description = "好消息是，我們找到腐化的源頭了。\n\n壞消息是，源頭是個在贊庫爾頂端舉行的儀式。\n\n那些使用鮮血魔法的異端在上面強化凶暴食人妖。\n\n他們到底是怎麼在沒有人發現的情況下一路到頂端去的，大概夠我跟拉爾爭論一整年了。\n\n走吧，把這件事徹底解決。", progress = nil, completion = "我不會讓這鮮血玷污我的神廟！", rewards = "受帕骷祝福的巨弓戰爭德魯伊的割刃帕骷擁護者之爪赤紅教徒權杖蘿蒂最愛的長矛雷爾的備用妖術法器崛加達的巨劍赤紅教徒懲戒錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][47423] = {title = "禁忌魔法", objective = "在天選者臺地殺死9名赤紅教徒。", description = "你來得正是時候，$p。我需要像你這樣的人。\n\n亞茲瑪的間諜說，有鮮血教徒混進我們當中。神王拉斯塔哈下令要我找出使用鮮血魔法的食人妖並殺了他們。\n\n帶著這個圖騰，揪出身上帶有鮮血魔法惡臭的傢伙，把他們從這神聖之地上剷除。\n\n完成以後，去叫那個懶惰的妖術之王拉爾勤奮一點，幫忙保衛這個地方。", progress = nil, completion = "什麼？那個狡猾又邪惡的迅猛龍狂熱者竟敢說我沒有盡到責任？呸！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47428] = {title = "小貓咪？", objective = "在谷溪森林找到小親親。", description = "在開始品茶之前，你必須找到最後一位客人！\n\n小親親非常喜歡森林，我敢說我們會在那找到他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47430] = {title = "觀察梟獸", objective = "觀察附近的梟獸寶寶跳舞、施放月火術、還有睡覺，看看你能學到什麼。", description = "<瑪嘎希望你向這裡的梟獸多多學習。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n梟獸寶寶\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47431] = {title = "集結聖光", objective = "在克庫營地與圖拉揚碰面。", description = "<name>，我和艾蘭里亞都渴望有更多時間能陪伴兒子，可是我們不能再等了，現在就要攻擊。\n\n聖光軍團雖然四分五裂，但我們還沒有一敗塗地。倖存的人應該會待在瑟納達爾的殘骸附近。集合所有人救出瑟拉，我們才有贏的機會。\n\n我們已經解決了深淵領主，前往瑟納達爾的路現在安全了。事不宜遲，趕快到下面的克庫營地跟我會合。", progress = nil, completion = "我們建立了一個據點，很好。\n\n向敵人發動攻擊的時候到了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47432] = {title = "做出決定", objective = "與神王拉斯塔哈交談。", description = "既然你已經決定自己身在祖達薩時會支持的守護神羅亞，你應該讓神王知道你的選擇。\n\n對於你選擇追隨偉大的帕骷，他會感到欣慰的。", progress = nil, completion = "看來，你選擇了追隨帕骷。願戰場上的風永遠為你而起。\n\n至於我，我追隨瑞贊，魔暴龍帝王羅亞。但我跟他有好多年沒有說過話了。\n\n或許我這陣子該去拜訪他。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][47433] = {title = "積極防衛", objective = "和妖術之王拉爾一起巡邏天空。", description = "我來猜猜看，蘿蒂要你把帶有鮮血魔法氣息味的食人妖全都殺掉，對吧？這樣根本就沒有用。\n\n聽好，鮮血魔法藉由古老的方式傳播，因為北方邊界的城牆倒塌，我們的人才會屈服於它的誘惑。\n\n來，我們騎一小段路去巡邏靠進納茲米爾的邊界，那裡是所有壞事的源頭。", progress = nil, completion = "噢，那彎牙的大鼻子想用飛行之旅和符咒博取你的心，是吧？", rewards = "詹巴尼纏手拉斯塔瑞護手贊庫爾裹手托卡利手套拉斯塔瑞護腰贊庫爾束帶托卡利束腰詹巴尼裹腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][47434] = {title = "維持秩序", objective = "趕走20隻翼手龍寶寶。", description = "「不太一樣的事」？拉爾只說了這些？\n\n他的翼手龍群霸占了贊庫爾庭院，大家都快被逼瘋了。\n\n在牠們受到傷害或傷到別人之前，把牠們趕走吧。", progress = nil, completion = "你為什麼要把我的翼手龍趕走？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47435] = {title = "翼地紛爭", objective = "殺死6隻血怒翼手龍。", description = "贊庫爾的庭院被受到黑暗儀式影響的翼手龍佔領了。力量在這裡融合，使人很難分辨是誰或者是什麼造成的。\n\n我得找出源頭。在此同時，你把這個拿去，這是剛克的力量，可以召喚他的盟友協助你戰鬥。殺死那些因黑暗儀式而發狂的翼手龍。\n\n完成之後，叫拉爾好好控制他的寵物們。", progress = nil, completion = "你有必要殺這麼多嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47437] = {title = "看誰更虔誠", objective = "殺死3個腐化的贊庫爾守護者。", description = "好，我知道事態嚴重，但她竟然把羅亞的力量給了你？這對我來說，比起處理鮮血食人妖的威脅，蘿蒂似乎更想招募同夥。\n\n我背後的神廟裡有三個守護者。當我走進去時，那些傢伙竟然想殺了我。居然想殺我！\n\n有人腐化了我們自己的守護者。\n\n來，我要把我的羅亞之聲，也就是翼手龍帕骷，借給你。想辦法消除那些腐化吧。", progress = nil, completion = "這比我們想的還要糟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47438] = {title = "選邊站", objective = "選擇一位羅亞。", description = "聽著，這件事已經拖太久了，$p。我不是一個吝嗇的人，但我不能讓你在兩位羅亞之間左右逢源。\n\n選擇羅亞的時候到了，他們可不怎麼樂於分享。", progress = nil, completion = "你已經做出決定了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47439] = {title = "獸群之王剛克", objective = "和剛克談條件。", description = "你可以在西邊的羅亞庭園中，找到巢穴中的剛克。\n\n你應該可以看到他的圖騰。跑過圖騰附近可以提高你的速度。\n\n我會繼續清除神廟裡的異端。\n\n在那個羅亞面前記得要有禮貌，不然他可能會咬斷你的喉嚨。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47440] = {title = "萬風之王帕骷", objective = "和帕骷交換條件。", description = "來，和我一起騎乘『風王』阿塔，他會帶我們去找帕骷。\n\n噢，在羅亞面前記得保持禮貌。帕骷會把她不喜歡的傢伙從高處重重摔到石頭上面。", progress = nil, completion = "噢，她沒把你摔死，這可是個好現象。來，讓眾人知道你的選擇吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47441] = {title = "有害生物", objective = "在佐卡洛殺死8隻小偷鉗嘴龍。", description = "我猜猜，羽冠龍也偷了你的東西？聽著，我沒空去翻這些愛咬人的怪獸叼走的每個垃圾。\n\n你要硬幣的話，去找那些小偷要吧。\n\n沒事的話別來煩我。", progress = nil, completion = "要從小偷這裡偷東西的小偷來了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47442] = {title = "迦尼的詛咒", objective = "通過迦尼的試煉。", description = "你這個小偷和殺手，站在你面前的可是拾荒者的守護神、竊賊之王、垃圾之神、手下之統帥暨秘密守衛者。\n\n你站在我面前，身著價值連城的衣飾，還帶著比我最忠誠的信徒身價還高昂的武器。\n\n我想現在正是幫你上一課的好時機。或許我得讓尊貴又強大的你看看，什麼叫做在陰溝裡翻船。", progress = nil, completion = "哈哈！做得好，富有的陌生人。在這些地方的時候，記得保持警覺。你不知道什麼時候我的孩子會把你引到什麼好地方。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][47445] = {title = "贊庫爾議會", objective = "在佐卡洛與戰鬥德魯伊蘿蒂交談。", description = "就是你，部落代表。\n\n我手下的間諜告訴我，有人在我們的神聖贊庫爾神殿裡學習黑暗的魔法。\n\n國王派了蘿蒂和拉爾去處理這個問題，但是那兩個沒事只會爭吵的議會成員，對他們自己的追隨者太過心軟。\n\n我們需要一個比較…不會感情用事的人。\n\n到佐卡洛下面去和戰鬥德魯伊蘿蒂碰面，她會告訴你其他事情。", progress = nil, completion = "歡迎來到贊庫爾，&lt;name&gt;。你要踏上的是神聖的土地。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47456] = {title = "安撫虛無", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47473] = {title = "評估敵情", objective = "與圖拉揚交談。", description = "這不是圖拉揚想聽到的消息，但我也沒辦法了。如果現在去攻擊燃燒軍團核心，我們絕對會一敗塗地。\n\n必須再想想辦法。我不知道還能做什麼，但總會有辦法的。\n\n別讓圖拉揚等太久。我們繼續前進吧。", progress = nil, completion = "&lt;圖拉揚靜靜地聽著，表情嚴肅。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47485] = {title = "艾胥凡貿易公司", objective = "前往東點站找卡格尼說話。在信風市場搭上威爾‧梅爾本的渡船。", description = "聽好了，艾胥凡的嘍囉身上帶著這種新型粉末，威力足以把戰艦炸成兩半，軍隊卻毫不知情。\n\n我們必須查出粉末到底有多少，以及他們打算把粉末運到哪裡。\n\n我有個老朋友在艾胥凡鑄造廠旁的渡船行。他可能聽到一點風聲。\n\n你可以從信風市場搭渡船去東點站。抵達後，找個叫卡格尼的人。告訴他是我派你來的。他欠我人情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47486] = {title = "可疑的貨物", objective = "在艾胥凡鑄造廠檢查5個標示好的貨物。", description = "如果是平時，我一個字都不會告訴你…但看在塞勒斯的份上，我就跟你說吧。\n\n艾胥凡正在進行一個大計畫。\n\n他們整個廠不眠不休地工作。甚至還找了打手來「激勵」大家努力工作。\n\n我不知道他們在製造什麼，但我知道這些東西不會從這裡運送到波拉勒斯。\n\n如果我笨到敢去廠裡打聽，應該會先檢查貨物本身，看看上面有沒有運輸標籤。\n\n但我沒那麼笨，所以這種事就交給你了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][47487] = {title = "勞資糾紛", objective = "殺死10名公司警備兵、公司執法者、公司步槍兵。", description = "艾胥凡公司對手下極為嚴苛，搞得他們想罷工！\n\n於是公司雇了一群暴徒驅散那些工人，把他們都趕回去工作。\n\n聽說他們甚至會對想離職的人開槍。\n\n你去那裡的時候，要不要順便讓他們嚐嚐暴力的滋味？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47488] = {title = "小小搬運工", objective = "在艾胥凡公司鑄造廠救出6個童工。", description = "<啜泣聲>\n\n他們說會放走我們，讓我們吃飽穿暖。\n\n<奧利薇用外套袖子抹鼻子。>\n\n可是他們很壞！而且工作很辛苦，只要我們想休息，就會對我們大吼大叫！\n\n<啜泣聲>\n\n我逃出來了，但我的朋友還在裡面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47489] = {title = "裝箱送走", objective = "躲在處女號上。", description = "<弗林拉高衣領，壓低聲音跟你說話。>\n\n看到那艘船了嗎？我認得那艘船。\n\n就直接跟你說吧，那船長跟我有段小插曲。\n\n那是走私船。非法武器肯定就在上面。我敢用我的大衣打賭…而且我真的很喜歡這件大衣。\n\n必須查查船會開到什麼地方…\n\n你能擠進狹小的空間嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47491] = {title = "受詛咒的殘餘物", objective = "為伯昂撒姆第蒐集6塊腐朽的血石。", description = "自從幽魂開始呼喚這個「古翰」，我的神廟就充斥著令人無法忍受的屍臭。\n\n不死怪物雖然人神不容，但用來製造他們的血石卻相當強大。伯昂撒姆第可能用得上這些血石。\n\n若你想向我展現你的熱誠，那麼就為我淨化這些充斥神廟的汙穢，然後把它們的血石帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47493] = {title = "一個孤單的幽魂", objective = "在亡者之城尋找珂烏菈。", description = "一個名叫珂烏菈的幼童靈魂在我的神廟裡徘徊。她的母親許多年前將這個孩子奉獻給我，認為做出這個巨大的犧牲，我就不會將她召喚至彼界。\n\n嗯，她對了一半，所以我還沒有取她性命；但另一方面她錯了，她的小孩能決定何時與她的母親團聚。依我看來，這個小孩不想再等下去了。\n\n他們兩個都是彼界的子民。\n\n去吧，讓那個小孩與她的母親重逢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47496] = {title = "碉堡破壞者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47497] = {title = "和金牙幫會面", objective = "和金牙旅店的工作人員會面。", description = "你好，旅行者，歡迎來到金牙旅店！\n\n除非你是來這邊殺我們…如果是的話，給我滾出去。\n\n要不然，請坐下來享受大餐！\n\n我是指，不要理那團爛餐。吃大餐！不要吃爛餐。別理它！\n\n<倫卡轉動戴了眼罩的顱骨，開始用贊達拉話破口大吼。>\n\n哈，別理他。金牙旅店歡迎流放者來此落腳，在惡劣沙丘地帶只有這家奢華旅舍。\n\n來，容我向介紹你其他工作人員。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47498] = {title = "倫卡的失蹤朋友", objective = "在亡者山隘找到蘇爾森。", description = "當你前往亡者山隘時，記得跟蘇爾森打個招呼。\n\n就算他幾乎都離我遠遠的，他也還是我最好的朋友！哈！\n\n不過，說真的，他上到崖頂好些日子了。如果你找到他的話，說服他回到旅店裡來。少了他的協助，就無法補齊我們的自助早餐吧。\n\n噢，如果你找不到蘇爾森，我就得想辦法替代他，對了，我還想問一個完全無關的問題：你的腦袋有多寬？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][47499] = {title = "塑像的收集", objective = "收集束縛塑像、不朽塑像和獻祭塑像。", description = "在那道詛咒降臨之前，我們都是效命於一位善良船長的忠實船員，但是那道詛咒腐化了海盜之王贊姆蘭，讓他變得既殘酷又專制。\n\n現在，他視我們為奴隸而非船員。我們被迫要為他的戰利品面對戰鬥和死亡，自己卻分不到任何財寶。更不要說還有那些懲罰。\n\n現在我們四個不想再當他的奴隸了。\n\n有幾個船員看守著贊姆蘭用來詛咒我們的塑像。殺了他們，拿走塑像。我想看看我們能不能打破它們。只是為了好玩。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "贊姆蘭船員披風解放的束縛塑像您會收到：\n\n"}
MultiLanguageQuestData['tw'][47501] = {title = "下流飲料的下流工作", objective = "從亡者山隘的死亡咬噬蠍子身上，收集20份腐蝕性蠍血。", description = "在金牙旅店的顧客得工作才能留下來。你要不要到工作場所之外的遊覽場所，幫我清理一些蠍子？那可是美妙無比的亡者山隘！\n\n一般情況下，你得購買我們的酋長套裝行程才能進去，不過我就幫你破個例。\n\n我還打算加入我們的蠍子國王套裝行程，全天蠍血無限暢飲，每天都行！\n\n現在只有一件事比較難辦：我們的蠍血用光了。帶些蠍血回來，我就可以馬上幫我們做出一批飲料。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47502] = {title = "巨顱犯罪計畫", objective = "從沙怒藏身處救出被綁架的金牙幫成員。", description = "沙怒暴徒趁你離開的時候發動攻擊，把金牙幫都綁走了！\n\n我們得把他們救回來。\n\n我們還在祖達薩的時候，曼佐一直都是我們行竊計畫的軍師，但我可以想出一個計畫，把他們從這團混亂中救出來。\n\n<倫卡想了一陣子。>\n\n我想到了！你去救他們！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "強韌流亡者照料手套末風照料手套流放精兵照料手套灼沙照料手套您能選擇下列奬勵中的一個：\n\n曝曬綠洲指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47503] = {title = "奴隸商人葛斯達肯", objective = "在沙怒藏身處殺死奴隸商人葛斯達肯。", description = "我現在正式宣佈，從今天起，沙怒食人妖不准再踏進金牙旅店！\n\n跑來洗劫這裡、綁架員工，然後用各式各樣的水果和蔬菜嘲弄老闆，別以為最後拍拍屁股走人就沒事了！\n\n我們得教訓那些惡棍，讓他們知道惹火金牙幫有什麼下場！\n\n在這場攻擊中，對其他沙怒食人妖發號施令的是奴隸商人葛斯達肯。\n\n把他解決掉，然後留點活口把消息傳出去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47507] = {title = "卡薩頓", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47508] = {title = "全力攻擊", objective = "進入一座光鑄砲台，殺死30隻發狂的瘟翼魔蝠。", description = "你要小心，空中有無數的蝙蝠。我們需要呼叫遠程支援，但是一直騰不出空檔。\n\n燃燒軍團應該還沒有摧毀所有的砲台，如果你能找到一座，就能讓這些有翅膀的惡魔嘗到被聖光懲罰的滋味。", progress = nil, completion = "我們就算被困在地面，也不表示要放任牠們在天上逞威風！", rewards = "您會收到：\n\n光鑄砲彈"}
MultiLanguageQuestData['tw'][47509] = {title = "天選者臺地", objective = "在天選者臺地附近與『縛浪者』卡薩金碰面。", description = "這場背叛讓贊達拉難以釋懷。有半數的贊庫爾議會成員和他們的追隨者都站在祖爾和他的…血神那邊。\n\n幸運的是，並不是每個贊達拉子民都參與了這場叛變。\n\n我們要先解決袓爾的信徒，別讓他們集結更多人。最好就從贊庫爾開始行動。\n\n去那裡看看你能不能集結仍然對國王效忠的贊達拉人。", progress = nil, completion = "&lt;name&gt;，很高興看到你還沒死。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47512] = {title = "納茲米爾", objective = "和塔蘭姬公主談話。", description = "在詛咒沼澤納茲米爾的鮮血食人妖威脅著要毀掉整個祖達薩。\n\n塔蘭姬公主需要部落的協助，派出一隊人馬直取鮮血食人妖的心臟地帶，並且終結他們對祖達薩的威脅。", progress = nil, completion = "納茲米爾沼澤對我的人民造成莫大的威脅。我很高興你願意幫助我們處理這個問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47513] = {title = "沃魯敦", objective = "和塔蘭姬公主談話。", description = "賈克拉傑將軍憎惡部落，而且不值得信任。只要他還握有權力，這座城市就不再安全。\n\n起疑的不是只有我們。與塔蘭姬公主交談以繼續追查。", progress = nil, completion = "賈克拉傑對我的王國和你的部落，帶來嚴重的威脅。最好能由你來調查他的舉動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47514] = {title = "祖達薩", objective = "和塔蘭姬公主談話。", description = "神王拉斯塔哈是一位相當古老的統治者，很難立即對新盟友投以信任。如果我們想要讓他派出艦隊相助，我們就必須先贏得他的信任。\n\n祖達薩是贊達拉帝國的權力寶座，若想贏得這些潛在盟友的信任，很適合從這邊著手。", progress = nil, completion = "想要贏得我父王的信任並不容易。\n\n相信我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47518] = {title = "拉爾", objective = "殺死酷拉札克並解救妖術之王拉爾。", description = "酷拉札克這個穿著牧師服的叛徒，以為只要折磨夠多我們的人，就能傷害到我們的羅亞。\n\n他們甚至把我的丈夫拉爾抓到贊庫爾的頂端去了。換做別的時候，丈夫送給他們也就算了，但他們是要利用他和帕骷之間的連結來削弱那個羅亞。\n\n這樣絕對不行。我們要快點到贊庫爾頂端去，拯救我那個沒用的丈夫。", progress = nil, completion = "啊…你一定要帶蘿蒂來嗎？她絕對會一直提起這件事的。", rewards = "拉斯塔瑞戰脛贊庫爾護腿托卡利馬褲詹巴尼束褲詹巴尼之索托卡利裹腰贊庫爾裹腰拉斯塔瑞腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][47520] = {title = "隔牆有耳", objective = "在贊庫爾殺死8隻蜘蛛。", description = "亞茲瑪，間諜夫人。\n\n呸！只會利用蜘蛛的叛徒。她選擇站在祖爾那邊，利用她信奉的羅亞沙德拉的孩子監視、追蹤我們的所作所為。\n\n我們必須殺掉我們看到的每一隻蜘蛛，不然那叛徒亞茲瑪就會知道我們的一舉一動。", progress = nil, completion = "做得好，這樣亞茲瑪就沒有耳目了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47521] = {title = "午夜的羅亞庭園", objective = "和妖術之王拉爾一起飛往羅亞庭園。", description = "亞茲瑪和她的食人妖手下沃卡爾，已經把大多數的部隊撤回了羅亞庭園。\n\n那裡的情況不對勁，我從靈魂深處感受到了。帕骷在那裡有危險，其他擁有追隨者的羅亞也一樣。\n\n來吧，和我一起飛去那裡，消滅那些異端分子。", progress = nil, completion = "我們可以從這邊開始對敵人展開反擊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47522] = {title = "獵人", objective = "拯救剛克。", description = "剛克有危險了。我能聽到他的呼喚。\n\n我的羅亞救過我的命好幾次，該是回報恩情的時候了。\n\n來吧，到位於羅亞庭園西邊的剛克巢穴跟我會合，我們要拯救一名神祇。", progress = nil, completion = "他們想要殺死我們。他們想要擊破我們。\n\n他們所有舉動只會讓我們團結一致，成就贊達拉有史以來最大的獵殺行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47523] = {title = "發現亂象：黑暗神廟", objective = "重現黑暗神廟的戰鬥。", description = "<name>，你總是這麼準時。\n\n先講好消息，反正對我來說現在跟未來都一樣。多虧過去和未來的你發現的時光扭曲物品，我們現在能準確發覺哪裡會出現新的類似物品。\n\n壞消息是，我們之所以能確認這種技巧有效，就是因為黑暗神廟發生了改變、造成所有時空都出現亂象！我們需要你去確認當時的進攻結果跟之前一模一樣、消除任何不穩定因素。", progress = "小心，一定要讓進攻神廟的結果跟之前完全一樣。只要一隻蜻蜓多拍一次翅膀，你們搞不好就會真的殺死伊利丹！那樣的話我們就徹底完蛋了！", completion = "這是什麼，&lt;name&gt;？\n\n\n\n\n這些是進攻馬爾頓的作戰計畫，難道我們太晚行動了？\n\n但奇怪的是，這些計畫好像比原本還要更好！這應該不是燃燒軍團所為，不然伊利丹一定會發現惡魔干預。如果不是燃燒軍團，到底是誰？", rewards = "您會收到：\n\n時光扭曲寶箱時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][47525] = {title = "低調行事", objective = "調查蛙沼。", description = "老兄，大事不妙了。鮮血食人妖有動靜了！他們在附近設置一個大型營地，還派了一支小型部隊到南邊的島上。\n\n我們目前完全沒有抵抗能力，如果被他們發現，那就完蛋了！我們必須偵察他們的動向，然後解決他們。\n\n現在最好的選擇，就是先偵察南邊的島。你想加入我嗎？我準備要動身了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47526] = {title = "重砲出擊", objective = "找到並且召回聖光審判。", description = "聖光審判有個安全機制，能夠避免它落到敵人的手中。我們可以啟動它的召回機制，這樣可以把它傳送到任何一艘船艦上。\n\n瑟納達爾損壞了，你應該把它召回到你的船上，它的火力一定會派上用場。\n\n不過這個過程需要時間，而且很可能會引起燃燒軍團注意。你要做好準備。", progress = nil, completion = "&lt;控制面板發出柔和的金色光芒。羅穆爾說過，啟動之後就能把砲台傳送到梵迪卡爾。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47527] = {title = "異端儀式", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47528] = {title = "謊言夫人", objective = "在羅亞庭園擊敗亞茲瑪和沃卡爾。", description = "如果你已經解決這些普通羅亞的問題，或許可以來幫幫我的羅亞，沙德拉。\n\n我的「大祭司」亞茲瑪，就是這一切的幕後黑手。如果她命令手下殺死其他羅亞，我只能推測她也同樣想要犧牲我的羅亞。\n\n沙德拉的神廟就在羅亞庭園的西北方。你必須阻止間諜夫人的殺戮行為。", progress = nil, completion = "沙德拉被…吞噬了？在祖爾德拉克聽說過這樣的異教，但從來沒在祖達薩發生…", rewards = "間諜仕女砍斧毒液之后長弓沙德拉侍徒妖術刀妖術之王矛戟羅亞防衛者戰鬥斧墮落蜘蛛手斧羅亞防衛者長矛沙德拉侍徒匕首您會收到：\n\n"}
MultiLanguageQuestData['tw'][47540] = {title = "以圖騰恢復神力", objective = "啟動圖騰的力量，然後恢復奎格瓦的神力。", description = "我吃飽了，身體充滿活力。我現在可以讓自己的古老力量在全身流動，暫時免於他們鮮血詛咒以及吸血能力的影響。\n\n使用微光蠅的魔法，將我的力量從圖騰中轉移回我的身體裡面。\n我的力量很快就會恢復，然後我們就能摧毀那支企圖過河掠奪我的軍隊。", progress = nil, completion = "我的力量恢復了，就像擁有好幾百名信徒給我信仰力量那樣。雖然我的力量會逐漸消退，但是我會再次讓那群食人妖知道奎格瓦有多可怕！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47541] = {title = "攻擊是最好的防禦", objective = "在破碎之地殺死20個攻擊者。", description = "你把大主教圖拉揚帶回我們的身邊，我們實在是太感激你了。\n\n我們還需要你全力支援。你看到那些挺身奮戰的士兵了嗎？請保護他們，殺死敵人。\n\n你或許會覺得這些話從牧師的嘴裡說出來有點偏激，可是每殺掉一個曼那瑞，我們的威脅就會少一分。\n\n讓他們知道聖光會保護遵循它的信徒，也可以焚燒邪惡。\n\n完成之後，就去找伊梅拉。她的部隊人數更少，更需要你的協助。", progress = nil, completion = "你做得很好。感謝你的幫忙，聖光變得更加明亮。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47542] = {title = "攻城大師沃蘭", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47543] = {title = "克羅米死亡之日", objective = "與克羅米交談，穿梭到未來並找出她的死因。", description = "<name>！我正好想到你！你來得正巧！\n\n我剛剛在檢查時間之道的偏差狀況，結果發現…意外的狀況。大事不妙了。\n\n我很快就要死了。慘吧。\n\n我正打算跳到未來去查清楚為什麼、怎麼死的，還有是誰幹的…不過要是有像你這樣的<race>陪我，我會比較放心。要一起去嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章"}
MultiLanguageQuestData['tw'][47545] = {title = "扭轉時光", objective = "再度與克羅米交談，然後穿梭到未來向其他龍眠特使探聽進一步的消息。", description = "既然我們知道對方什麼時候攻擊，還有會從哪裡攻擊，這樣就有進展了！接下來只要找到更多資訊，然後阻止攻擊就好！\n\n等你準備好再試一次，就跟我說吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章"}
MultiLanguageQuestData['tw'][47550] = {title = "身為時光行者的優勢", objective = "三度與克羅米交談，穿梭到未來並再次設法拯救她。", description = "那個處心積慮想殺我的人，應該覺得很棘手，因為我可是時間之道的高手！我們可以重來、重來、再重來，直到我沒有死為止。\n\n幾秒鐘好像來不及阻止攻擊。改成四小時，應該夠吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章"}
