MultiLanguageQuestData['tw'][47564] = {title = "補給自助餐", objective = "收集10枚哨花多汁果實。", description = "想像一下，$p。你喝完蠍血、屠殺沙怒、和你最好的朋友蘇爾森開著玩笑，過完一天後在金牙旅店裡醒了過來。\n\n你還沒完全恢復神智，也還沒什麼精神。在這個關鍵時刻，你最需要的是什麼？\n\n當然是吃到飽的自助早餐吧！\n\n我正在準備材料，但我需要一些水果來均衡我的菜單，幸運的是，我在外面的綠洲看到一些。\n\n把那些水果帶回來，我就讓你成為自助餐的終身會員。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47566] = {title = "加爾梭斯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47570] = {title = "不為人知的動機", objective = "找出納迦的侵略計畫。", description = "我不懂的是，納迦為什麼要對這個小小的漁村大動干戈。\n\n為什麼要在我們這個單純的部族上浪費時間？我們並不具備納迦想要的力量。這根本沒道理啊！\n\n他們一定在尋求某種不同的事物…\n\n去黑木淺灘徹底搜尋，瞭解他們的計畫。不管那些納迦在找什麼，那玩意一定很強大。\n\n或許，如果我們搶先取得，就可以用來對付他們！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][47571] = {title = "長者的睿智", objective = "將入侵計畫帶給長者庫巴卡。", description = "納迦正在搜尋一枚威力強大的神器，名為潮汐之戒。\n\n從他們的侵略計畫看來，這枚戒指在很久之前對抗偉大的虎之羅亞，伊拉卡‧諾‧金布爾的戰爭中遺失了。\n\n伊拉卡‧諾‧金布爾的神殿就在北邊不遠之處，如果那位羅亞在早年有足夠的力量打倒納迦，或許他能夠再次展現神威！\n\n我們一定要把這個發現告訴部族的其他人！\n\n帶著侵略計畫去找長者庫巴卡，他是我們部族中年紀最大、最睿智的成員。他知道該怎麼做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47573] = {title = "叢網侵襲", objective = "殺死6頭叢網爬行者和30頭叢網幼蛛。", description = "神殿的外牆是我們抵禦納迦的主要防護，但是整座神殿裡面到處都是叢林蜘蛛。\n\n我們得清掉這些盤踞在此的生物，才能讓整個部族進入神殿落腳。\n\n冒險踏入廢墟下層，並毀掉蜘蛛在那邊架設的巢穴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47574] = {title = "統統被網住", objective = "釋放8名托塔卡族人。", description = "在神殿廢墟下層到處都是厚重蛛網和蜘蛛卵囊。\n\n我們有些族人前往下層廢墟想要清理蜘蛛，但他們再也沒回來了。\n\n我很擔心他們的安危。\n\n請在一切太遲之前，前往廢墟下層並解救我們的同胞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47576] = {title = "猛虎之怒", objective = "擊退納迦的入侵。", description = "托塔卡將會獲得我的加護。在我們交談的同時，有一支納迦軍隊已經從深處浮現，前來攻擊我的神殿。\n\n對於上次的落敗，這些納迦也忘得也太快了！\n\n他們想要取回潮汐之戒。我殺掉艾薩拉前任勇士梅普吉拉的時候，把對方所擁有的這枚強大神器留下來當作紀念品。\n\n我會將你送往戰場，成為我的化身，並對納迦降下毀滅之雨。他們已經忘了對抗我的追隨者會有什麼下場。\n\n你去提醒他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "榮耀之虎披風灼沙護腿強韌流亡者腿鎧末風束褲流放精兵護腿片您會收到：\n\n"}
MultiLanguageQuestData['tw'][47577] = {title = "來自大海", objective = "質問8位納迦的靈魂。", description = "你可以在我們的營地裡好好休息，放鬆疲累的雙腿，恐怕我沒什麼東西可以款待你。\n\n納迦把我們從海邊的營地趕來此地，我們再也無法捕漁或是獵殺螃蟹。如果我們無法奪回潟湖，恐怕活不了多久。\n\n可是，光奪回瀉湖還不夠。我們必須查明納迦攻擊我們的原因。他們到底想要找些什麼？\n\n帶著這份古老卷軸，並用它來召喚納迦的靈魂。\n\n只有在法術的控制之下，他們才會吐露實情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47578] = {title = "羅亞的印記", objective = "在金布爾聖壇和金布爾溝通。", description = "你已經證明有資格獲得我的祝福，<name>。\n\n這表示如果你選擇我做為你的羅亞，你可以在需要的時候呼喚我的力量。\n\n到我的聖壇進行溝通，並做出你的選擇。\n\n要知道，不管你的選擇為何，都隨時歡迎你來到這座建築內。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47580] = {title = "梅普吉拉的詛咒", objective = "擊敗梅普吉拉的靈魂。", description = "百年之前，海洋女巫梅普吉拉帶著納迦大軍，入侵我的神殿。\n\n我的追隨者奮勇作戰，但是我抵達得太晚，沒能拯救他們。\n\n我輕鬆擊敗納迦的軍隊，可是當我的利齒咬住梅普吉拉時，她對我的追隨者靈魂降下一道詛咒，將他們封鎖在永遠都打不贏的永恆戰場中。\n\n這個面具可以讓你擁有足夠的力量，進入靈魂領域並終結他們的夢魘。\n\n擊敗梅普吉拉的靈魂，詛咒就會崩解。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47581] = {title = "金布爾的祝福", objective = "取得潮汐之戒。", description = "神殿入口被某種魔法屏障封住了。\n\n從我的卷軸看來，只有取得潮汐之戒的人才能降下這道屏障。\n\n在神殿庭園的某個角落有尊雕像，擁有能讓戒指顯露出來的力量。但是廢墟裡面到處都是叢林蜘蛛。光靠我和圖魯，沒有足夠的本事去探索廢墟下層。\n\n如果你能取得潮汐之戒並踏入神殿，或許我們就可以面對納迦了！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n潮汐之戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47583] = {title = "死吧，死吧，雙帆龍", objective = "殺死8隻劇毒雙帆龍。", description = "我們在比賽，你、我和這些野蠻人。\n\n我覺得這…很有趣。\n\n你可以在南邊找到雙帆龍。我要對你下戰帖，<class>，看誰能殺死更多雙帆龍。\n\n你想來賭一把嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47584] = {title = "芒刺在側", objective = "在保護區殺死12隻刺甲龍。", description = "你們這些傻瓜，老是用大驚小怪的口吻談論獵殺「大傢伙」。呸！\n\n沒有人比我的族人更懂得獵殺大型獵物。我們精妙的狩獵技巧可是世代相傳。\n\n我就是來證明這一點的。\n\n我敢打賭，你在這個區域能宰掉的刺甲龍一定不會超過十一隻。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47585] = {title = "捕獵者", objective = "在保護區內再找到2個獵人。", description = "<他背後有傷口，可能是刀傷。\n\n看來這裡不只是打獵這麼單純。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47586] = {title = "追捕獵人", objective = "追蹤赫米特‧奈辛瓦里。", description = "你那位狩獵之王奈辛瓦里，是這裡的絕佳獵物。我甚至還想親自追捕他。\n\n但現在已經有人在追蹤他了，而且那位獵人也很危險。\n\n如果你想拯救你的狩獵之王，你最好趕快出發。等到他開始埋伏，一切就太遲了。你不但找到不目標，而且還不知道是什麼東西擊中你！\n\n我想他應該是向西邊去了…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47587] = {title = "獵頭者裘歐", objective = "殺死獵頭者裘歐。", description = "他說他在追殺你。我不是獵物，我是誘餌！\n\n在你後面！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "源途狩旅團巨弓克塔爾牙刃野獠象牙鬥棍大獵捕碎顱錘源途狩旅團法杖獵頭者裘歐的砍刀大獵捕戰刃獵頭者裘歐的長杖野獠象牙碎顱錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][47588] = {title = "狩獵之王", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47589] = {title = "正義之怒", objective = "摧毀3個軍團毀滅者。", description = "毀滅者正在轟炸我軍部隊，讓我們無法前進。我只能再擋一陣子。\n\n勇士，你必須突破它們的陣線，關閉保護毀滅者的屏障。\n\n如果你能摧毀維持屏障的定位器，我就能從遠處淨化它們。", progress = nil, completion = "或許我們還有勝算。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47591] = {title = "買燈嗎？", objective = "跟格利夫塔購買可疑的油燈。", description = "喂，要買燈嗎？你不會後悔的。", progress = "你一定不會後悔的。", completion = "我就說這是個好主意吧！", rewards = "您會收到：\n\n滿是油垢的燈"}
MultiLanguageQuestData['tw'][47592] = {title = "像鑽石一樣閃閃發光", objective = "跟格利夫塔購買純天然有機燈具清潔工具組，然後清潔滿是油垢的燈。", description = "喔，抱歉，那盞燈看起來需要好好清洗才能用。我剛好有在賣清潔工具。", progress = "超划算的啦。", completion = "喔喔喔，讓我看看！", rewards = nil}
MultiLanguageQuestData['tw'][47594] = {title = "交給我吧，謝囉！", objective = "幫格利夫塔取得10,000枚浮雲之幣。", description = "你說這種硬幣，會憑空消失？聽起來太棒了，我知道要交給哪個傢伙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47595] = {title = "供需過剩，但來者不拒", objective = "幫格利夫塔取得10,000枚浮雲之幣。", description = "如果你想要繼續收集，格利夫塔不會有意見。不過我已經不需要那麼多了，所以你的報酬也會變少。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47596] = {title = "替代方案？才沒有這種東西咧", objective = "找回A.M.O.D.的所有零件。", description = "聽著，我老實跟你說。我們這台被簡稱為「A.M.O.D.」的「轟天絕命無敵機甲」，可是目前為止所製造最精良最棒的傑作；它具備了機動性、火力強大，實在是巧奪天工、獨一無二！我的意思是，沒有它的話，我們的計畫就整個泡湯了啦！我們必須回收零件，然後重新組裝起來才行！\n\n那個傻大個海巨人拆了機甲，零件還散落在海岸四處。去回收零件，我來重新組裝看看。", progress = "拿到那些零件了嗎？", completion = "看來你都找齊了…嗯…至少我們先把重要的東西拿到手了，接下來有大型修復工作等著我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47597] = {title = "一個哥布林也不能少", objective = "找到並解救失蹤的哥布林戰隊隊員。", description = "動作不快點的話，任務就沒指望了啦！\n\n我找到一個設置新基地的完美地點。在我去確保地點安全的時候，我要你去解救其他人員，將他們帶回來。我們為了此刻已經訓練無數次了。只要指引他們會合點的方向，他們就能找到路。\n\n沒多少時間了，快快快！", progress = nil, completion = "大家都回來了，真有你的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47598] = {title = "偷拐搶騙", objective = "到破碎拱門從納迦手上收集20塊古代泰坦聖物。", description = "船艦沉沒、A.M.O.D.損毀。為了這項任務，我們損失慘重…而且污水企業向來不買意外險的。債主聽一定會找我們算帳！我們得彌補這些損失才行。\n\n海灘上到處都是納迦，他們想在殘骸裡回收工藝品。要不要去分一杯羹，把錢賺回來呢？我一定能夠找到願意出錢的買家。\n\n分帳方式嘛…我八，你二，這樣很公平吧？", progress = "有找到什麼好貨嗎？", completion = "大豐收！這下子污水企業不會來找我們麻煩了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47599] = {title = "熱血復仇", objective = "使用提克爾的火箭發射器殺掉4個邪鱗巨獸。", description = "聽著，老大不想在這裡大動干戈，但是我們也不能讓這幫納迦以為我們好欺負。你也同意，對吧？\n\n這些納迦派巨獸去毀掉我們的船上剩下的東西。你帶著我的火箭發射器，去給他們點顏色看看，讓他們知道我們的厲害！", progress = nil, completion = "就是這樣！讓我們為那些可憐的怪物默哀三分鐘。\n\n這樣就…完成了！", rewards = "納茲曼戰鎧護腰羅亞語者的繫腰死亡誓願束腰剝皮儀祭裹腰提克爾的備用催化劑您會收到：\n\n"}
MultiLanguageQuestData['tw'][47601] = {title = "實戰評估", objective = "使用A.M.O.D.來摧毀納迦營地，並擊敗葛羅巴森。", description = "我們把A.M.O.D.修好了，不過這是相當精良的設備，我們必須先微調一番，免得誤傷自己人。\n\n幸運的是，那個破壞我們器材的巨人旁邊有幾座納迦營地，那可是絕佳的試射對象。\n\n我們會把A.M.O.D.部署在建築物外面。等我們弄好以後，你負責操縱，在我微調火炮的時候，幫我試射幾發看看。\n\n不會有事的啦…除非發生什麼意外…", progress = nil, completion = "很好！再調整幾個地方就完成了，哪有我們解決不了的問題，對吧？\n\n喔，對了…打得漂亮！", rewards = "納茲曼戰鎧護脛羅亞語者的長褲死亡誓願腿甲剝皮儀祭裹腿您能選擇下列奬勵中的一個：\n\n備用穩定器指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47602] = {title = "準備行動", objective = "前往幽暗谷，與塔蘭姬公主談話。", description = "設置大砲底盤要花點時間。將大型裝備舉起怎麼這麼難啊？\n\n你要不要利用這個空檔，去你朋友那邊確認一下？看看他們準備好沒了有。我可不希望因為他們準備不周，害這座大砲「再次」受到伏擊。", progress = nil, completion = "你說納迦？\n\n聽起來是個不小的危機。我很高興你有辦法逢凶化吉！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47603] = {title = "神秘而偉大的艾拉巴斯", objective = "跟艾拉巴斯交談。", description = "渺小的凡人，我看到你了！感謝你對這盞燈如此關愛！", progress = "整個世界都在顫抖，因為魔法的重量而顫抖。這些人的口袋裡滿滿都是魔法。", completion = "你真的看不到嗎？我都能感覺到他們口袋裡的魔法了！", rewards = nil}
MultiLanguageQuestData['tw'][47604] = {title = "魔法之地", objective = "再跟艾拉巴斯交談一次。", description = "我知道問題在哪裡了。你的小眼睛太弱，看不見這些精靈散落在各處的法力附魔精品。精靈們一直都佩戴著珠寶，只是你看不見。\n\n親愛的新夥伴，我們來合作吧！我的油燈現在嚴重缺乏魔法，而且我一直想要更漂亮的裝飾。我們可以做個交易。我負責揭開邪惡的真面目，然後你把偷到的東西交給我。", progress = nil, completion = "太好了，真是太好了。這樣一來我們就能一起獲利了，小幫手。", rewards = nil}
MultiLanguageQuestData['tw'][47605] = {title = "浮雲之幣", objective = "再與艾拉巴斯交談一次。", description = "我對這些原本在此地居民口袋裡的魔法飾品很感興趣，也很願意提供協助，幫你取得這些東西，<name>。 \n\n不過，很抱歉我沒辦法用這個世界通行的貨幣支付款項。我能給你的是稍縱即逝，浮雲般的貨幣。不管怎樣都比沒有好，對吧！\n\n帶著我的油燈。放下你在裡面偷到的寶物，我就會把貨幣給你。說不定油燈的前任主人會用得著。", progress = nil, completion = "我把油燈交給你了，希望我們的合作能有豐厚的收穫。", rewards = "您會收到：\n\n艾拉巴斯神燈"}
MultiLanguageQuestData['tw'][47606] = {title = "忠誠本身就是獎勵", objective = "獲得一千枚浮雲之幣。", description = "這是給你的挑戰，凡人。只要得到一千枚我給的貨幣，我就能強化這盞燈，還有裡面的幻象。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n發亮的艾拉巴斯神燈"}
MultiLanguageQuestData['tw'][47607] = {title = "華麗的神燈精靈", objective = "在破碎群島居民口袋裡找到稀有的寶物。", description = "從我剛強化過的油燈可以進一步感覺到這些精靈和惡魔身上有更具價值的飾品。去幫我找回來！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n閃耀的艾拉巴斯神燈"}
MultiLanguageQuestData['tw'][47621] = {title = "真正的羅亞盛宴", objective = "在納茲米爾的蛙沼上層殺野獸並取得牠們的肉。", description = "鮮血食人妖的攻擊接連不斷，剛剛終於停下來。他們讓我變得非常虛弱，我必須恢復力量才行。在過去，我的信徒常常會把附近一帶的肉當作為供品獻給我。\n\n去帶一大堆鮮肉給我，讓我好好飽餐一頓。等我恢復力氣，我們會讓他們再也沒辦法發動攻擊。", progress = "我餓了。", completion = "&lt;奎格瓦一陣狼吞虎嚥，沒幾下就把肉全吃光。&gt;真棒！我餓太久了。我的信徒死去以後，我的飢餓感就每日遽增。\n\n或許當更多人信仰我時，進食會再一次成為單純的享受。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47622] = {title = "魔法光芒", objective = "在蛙沼上層收集漂亮的微光蠅。", description = "很久很久以前，當食人妖開始聆聽黑暗的細語時，我將部分力量灌注到我巢穴周圍的圖騰裡面。我現在需要收回那股力量。\n\n在這裡北邊的沼澤，棲息著一群微光蠅，牠的魔法精華能用來汲取儲存在圖騰裡的力量。去收集微光蠅，然後回來找我；然後我會讓你見識見識我巔峰時期有多強大。", progress = nil, completion = "在他們屠殺我的信徒之前，我就該這樣做了，但是鮮血食人妖的力量一直都很強大。\n\n我們是否能夠存活下去，全靠你了。", rewards = "誘人的螢火蟲燈籠鑲金睡蓮葉您會收到：\n\n"}
MultiLanguageQuestData['tw'][47623] = {title = "最後的奎格瓦巫醫", objective = "取得復生權杖，然後使用權杖對贊提莫舉行奎格瓦儀式。", description = "吾名為奎格瓦，過去我的力量比現在強很多。我詛咒鮮血食人妖與他們那個黑暗神祇！他們將我的信徒趕盡殺絕，最後只剩下贊提莫。現在，就連他也死了。\n\n我要對鮮血食人妖展開復仇，不過現在必須先為我的最後一位巫醫送別。我身旁沒有其他人，因此必須由你來舉行儀式。\n\n然後，我們再來商討復仇大計。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47624] = {title = "將其埋藏", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47625] = {title = "我們的儀式", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47627] = {title = "復仇", objective = "摧毀毀滅之冠的攻城武器。", description = "聖光軍團一定會奮戰到底。\n\n我們的部隊會攻擊主要營地，我們則要負責摧毀它們的攻城武器。\n\n復仇的第一步就從這裡開始。", progress = "要是不解決它們的武器，我們就永遠無法突破困境。", completion = "我們太小看燃燒軍團的詭計了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47631] = {title = "與獻酒號會合", objective = "在漂移淺灘與派奇談話。", description = "老兄，我跟你坦白說吧，我對哥布林以及他們的滑稽把戲沒什麼耐心。\n\n去跟他們的領袖會面，確定他的手下與武器都準備就緒。如果我們失敗了，祖達薩會被鮮血食人妖攻陷。\n\n祝你好運，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47638] = {title = "強大的靈魂", objective = "參與金牙幫的入幫儀式。", description = "你證明了你夠資格，$p。如果你想加入的話，我們很樂意接納你成為金牙幫的一員。\n\n儀式用的飲料準備好了，煮沸的蠍血攙入怒翼「蜂蜜」！\n\n別在乎那股氣味，它美味無比。嘗起來不會嚇死人，也不會害死你，通常啦。\n\n當你準備加入金牙幫的時候告訴我一聲。我會讓你和整個幫派稱兄道弟，該是和你一塊分享我們遠見的時候了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47641] = {title = "反抗勢力", objective = "尋找反抗的跡象。", description = "我們的部隊在守衛梵迪卡爾的時候損失慘重，<name>。我們需要盟友。\n\n聖光軍團會招納在燃燒軍團的血腥遠征中倖存的人，以加強他們的兵力。我們也要這麼做。\n\n我感覺到附近有你釋放的燃燒軍團奴隸，我在想他們是否會反抗燃燒軍團。\n\n要是你能跟我一起去看看就太好了，$p。", progress = nil, completion = "一定就是這裡了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47642] = {title = "靈魂水晶", objective = "找出躲在晶紅龍殿樹中的巫妖。<三枚裂片互相吻合，組合成大型水晶。巫妖強大的幻象在水晶表面浮現。>\n\n<巫妖開始說話：>\n\n分散晶紅守護者的注意力，我會遵從主人的意志，從神樹內部展開攻擊。", description = "<三枚裂片互相吻合，組合成大型水晶。巫妖強大的幻象在水晶表面浮現。>\n\n<巫妖開始說話：>\n\n分散晶紅守護者的注意力，我會遵從主人的意志，從神樹內部展開攻擊。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47643] = {title = "古樹的智慧", objective = "找出躲在翡翠龍殿中的薩特。古樹給了我們三個線索：\n\n「…夢魘…」\n\n「…水邊…」\n\n「…在龍掌中…」\n\n只要找到古樹形容的地點，是不是就能找到攻擊克羅米的敵人？", description = "古樹給了我們三個線索：\n\n「…夢魘…」\n\n「…水邊…」\n\n「…在龍掌中…」\n\n只要找到古樹形容的地點，是不是就能找到攻擊克羅米的敵人？", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47644] = {title = "魔核之石", objective = "找出躲在黑曜龍殿洞口附近的驚懼領主。<魔核之石深處傳來驚懼領主陰沉的聲音：>\n\n遵命，主人，就照你說的時間，一定會成功的。那頭青銅龍毫無頭緒。只要從黑曜龍殿射擊，我就能成功。", description = "<魔核之石深處傳來驚懼領主陰沉的聲音：>\n\n遵命，主人，就照你說的時間，一定會成功的。那頭青銅龍毫無頭緒。只要從黑曜龍殿射擊，我就能成功。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47645] = {title = "虛無呼喚者的卷軸", objective = "找出躲在蒼藍龍殿頂端的虛無生物。<卷軸碎片可以組合在一起，顯現某種破碎、但可以閱讀的訊息：>\n\n時候到了，開始在蒼藍龍殿上方進行召喚。那頭青銅龍將被虛無吞沒。這是主人的命令，我們必定服從。", description = "<卷軸碎片可以組合在一起，顯現某種破碎、但可以閱讀的訊息：>\n\n時候到了，開始在蒼藍龍殿上方進行召喚。那頭青銅龍將被虛無吞沒。這是主人的命令，我們必定服從。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47646] = {title = "四處捕捉", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47647] = {title = "贊姆蘭的怪物", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47652] = {title = "聖光之母", objective = "在瑟納達爾內找到瑟拉。", description = "<name>，我們一定要去確認聖光之母是不是還活著。\n\n瑟拉因為把自己的聖光之心送到艾澤拉斯而變得虛弱，但她是至高那魯，她就是聖光，是不可能消散的。\n\n我們去瑟納達爾找她吧。聖光保佑，希望她會回來再度指引我們。", progress = nil, completion = "讚美聖光！這是黑暗的一天，許多人失去了性命。\n\n可是聖光軍團撐過來了。聖光之母的預言一定會實現。\n\n這一切都早已註定。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47653] = {title = "聖光歸來", objective = "與圖拉揚交談以返回梵迪卡爾。", description = "我們救出瑟拉了！這是一場重要的勝利。\n\n聖光之母應該已經回到梵迪卡爾了。她一定會想跟你談談。要解釋的事情實在太多…\n\n羅穆爾應該可以把我們傳回船上。準備好的時候就跟我說一聲。", progress = nil, completion = "聖光軍團撐過來了。聖光之母的預言就要實現。\n\n這一切早已註定。", rewards = "您會學到：\n\n光鑄信標：破碎之地\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47654] = {title = "三傑議會之座：知識之冠", objective = "殺死路拉，取回知識之冠。", description = "<name>，東西都準備好了。\n\n艾蘭里亞‧風行者會在三傑議會之座等你。\n\n朋友，不要單獨前往。你需要盟友才能拿到知識之冠…才有辦法面對現在的路拉。\n\n我會讓梵迪卡爾就緒，等你回來。願聖光在那黑暗中仍與你相隨。", progress = "<name>，我知道這是個沉重的擔子。但我相信你不會讓我失望。", completion = "完成了。我因為路拉的死亡而悲傷，但至少你讓她安息了。\n\n一旦安置好知識之冠，梵迪卡爾就有辦法承受燃燒軍團邪惡的攻擊。安托洛斯必敗！", rewards = "您會學到：\n\n埃雷達斯西部世界任務\n\n您還會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][47659] = {title = "追捕獵人", objective = "在蛙沼附近殺死戰母暴鐵瑪。", description = "拜託，夥計，救救我們。蛙沼受到攻擊了！我的主人是偉大的羅亞「奎格瓦」，他不願屈服在鮮血食人妖以及他們那位黑暗神祇的意志之下，所以現在他們想強行奪取主人的力量！他們殺害他的子民、搶走他的力量圖騰。如果我們沒辦法終結這種瘋狂行徑，他們甚至要綁走奎格瓦當成祭品！\n\n阻止他們！殺掉他們的領袖。或許這樣就能暫時拖延他們的行動。我也能爭取到一點時間，尋找更一勞永逸的解決方案。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "染血戰母巨披風羅亞語者的腕輪納茲曼戰鎧臂甲死亡誓願束腕剝皮儀祭臂環您會收到：\n\n"}
MultiLanguageQuestData['tw'][47660] = {title = "空虛的塑像", objective = "從蛙沼裡的鮮血食人妖營地收集被偷走的奎格瓦塑像。", description = "鮮血食人妖想要弱化奎格瓦，奪取他的力量。因此他們偷走他的力量塑像，然後加以破壞，好吸取塑像裡面的魔力。\n\n想讓奎格瓦恢復，就必須盡可能去回收這些塑像，我們要讓奎格瓦恢復到原有的力量，一口氣殲滅他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47663] = {title = "適時送達的撒塔斯邀請函", objective = "去撒塔斯找沃爾慕。", description = "從目前星盤看來火焰之星的軌跡非常奇特，它的呼喚穿透整個宇宙。去撒塔斯城找一位叫做沃爾慕的智者，她需要你幫忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47685] = {title = "守門者的挑戰：狡詐", objective = "收集敏銳碎片、機智碎片和狡黠碎片，然後把它們合併成狡詐印記。", description = "阿克蒙德對他的學生期望很高。只有最靈活的腦袋、最聰敏的心智才能真正掌握我們魔法中的精義。\n\n我猜你聽不懂我在說什麼。\n\n左手邊這條路會帶你們通往三座雕像。利用那些雕像來收集狡詐印記。\n\n為了公平起見，我無法提供這場試煉的相關線索。如果你真的因為某種奇蹟而通過試煉，我會正式認可你的…才智。", progress = "展示狡詐印記，不然別來煩我。", completion = "喔，你成功了。\n\n真沒想到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47686] = {title = "不簡單的起步", objective = "在秘法講修院和大法師伊梅拉會合。", description = "可以開始尋找三傑聖物了。我們先去找阿克蒙德的覺醒符印。\n\n往東北邊去，你會找到曾經是阿古斯最好的魔法學院的遺跡，阿克蒙德就是在那裡學習秘法的。我想不出他還會把東西藏在哪。\n\n一定會有人在那裡看守。我們可以請法芮雅的部隊協助我們。", progress = nil, completion = "這個地方充滿秘密。幸好，我知道該怎麼開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47687] = {title = "守門者的挑戰：精通", objective = "擊敗首輔賈拉蘇、總領事維菈拉和大喚醒者亞岡。", description = "阿克蒙德被渴求力量的野心所吞噬，只有和他一樣渴求力量，才有可能在他的指導下有良好的表現。\n\n你要面對的，是阿克蒙德剩下的得意門生。這三個門徒各自擁有強大的力量，講修院至今仍在紀念他們。\n\n他們的靈魂會想盡辦法殺了你。\n\n盡你所能擊敗他們三個，想辦法全身而退，我就會認可你的力量。", progress = nil, completion = "我得承認，你確實厲害。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47688] = {title = "侵略型物種", objective = "收集30份部分消化的秘法。", description = "我們應該再另外找一個能量的來源，以防導體的能源不夠。\n\n幸運的是，我知道該去哪裡找備用的能源。\n\n阿古斯的原生獵能豹向來喜歡獨來獨往，但喚醒者身上的魔法似乎引來了大批的獵能豹。\n\n這時候就別想著維護生態平衡了，獵能豹吞噬的是能量。\n\n殺死牠們，看你能不能回收一部分牠們所吞噬的能量。", progress = "備用方案總是多多益善。你拿到我們需要的東西了嗎？", completion = "沒想到成品會這麼…有黏性。\n\n&lt;伊梅拉在她的長袍上不斷擦手。&gt;\n\n這樣就行了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47689] = {title = "守門者的挑戰：堅毅", objective = "克服堅毅試煉", description = "我的主人阿克蒙德向來果斷，絕不拖泥帶水。\n\n他用以馭下的方式就是挫折還要更挫折，罰了還要再處罰。只有完全臣服於他的人才能獲得他的青睞。\n\n講修院的對面有一座很大的建築。進去以後，你的目標就是通過所有必須完成的試煉。\n\n只要你毫髮無傷地出來，我就願意承認你有繼續走下去的堅強意志。", progress = nil, completion = "要是你能活那麼久，或許我就會讓你知道講修院的秘密。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47690] = {title = "污染者的寶物", objective = "擊敗阿克蒙德，拿到覺醒符印。", description = "看來你沒有這麼容易退縮。很好。\n\n你有去尋找符印的資格。但是你可不要誤會了，我只是放你過去，不代表你真的能拿到符印。\n\n你會在前面遇到最大的挑戰。\n\n你必須前往議政廳對抗阿克蒙德，只有擊敗講修院的主人，符印才會是你的。\n\n很少有人能完成這件事。希望他不會讓你死得太慘。", progress = "是如假包換的阿克蒙德…這是怎麼一回事？", completion = "我從沒感受過這種力量…\n\n&lt;伊梅拉小心翼翼地翻看裂片。&gt;\n\n這個東西應該要立刻交給費倫。", rewards = "您會收到：\n\n毀壞的講修院紋章"}
MultiLanguageQuestData['tw'][47691] = {title = "尋找預言者", objective = "找到費倫。", description = "我很肯定費倫就在附近。要是他被抓了，我們一定會知道。\n\n不管怎樣，事不宜遲。費倫為了阻止燃燒軍團做了這麼多事，它們可是無所不用其極地想找到他。我不敢想像要是費倫真的落到它們手裡，到底會怎麼樣。\n\n所以我要跟你們一起去。\n\n我們一定會找到費倫，協助他找到知識之冠。我們要對他有信心，否則一切就都完了。", progress = nil, completion = "你在我回想事情的時候出現在我面前。\n\n&lt;費倫表情疲憊地看著你。&gt;\n\n我們沒有時間悲傷了，必須繼續前進。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47695] = {title = "浪中警訊", objective = "在霧崖海岸殺死8名哀號海妖。", description = "海妖只會帶來麻煩！他們一天到晚抓走我們的人，而那些人就此消失無蹤。如果他們一直這樣，我們怎麼有辦法把貨物快速運到波拉勒斯呢？\n\n既然你已經要下去了…你可以幫忙讓海妖的數量稍微減少一點嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47696] = {title = "可怕的奎格瓦", objective = "運用奎格瓦的神力，化解鮮血食人妖的反擊攻勢。", description = "你之前的攻擊行為激怒了鮮血食人妖。他們現在派了一支軍隊想奪走一切，不過太遲了！我可是奎格瓦！想吞掉我？我吞掉他們還差不多！\n\n到刃顎河岸找我。你會親眼見識到我的力量，而我也會見識到你的。", progress = nil, completion = "那些野蠻人一看到奎格瓦就跑！這讓我很高興！\n\n但是，如果我們沒辦法阻止他們所信奉的那位邪神，他們一定會帶著更龐大的部隊回來。只要你對抗他們，我就會把我的神力賜給你。\n\n當復仇之日來臨時，我會助你一臂之力。", rewards = "剝皮儀祭之握納茲曼戰鎧戰鬥手套羅亞語者的裹手死亡誓願手套納茲曼戰鎧踏靴羅亞語者的便鞋死亡誓願長靴剝皮儀祭裹足您會學到：\n\n奎格瓦的恩澤\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47697] = {title = "奎格瓦之助", objective = "向塔蘭姬公主報告你的成果。", description = "做得好，<name>！\n\n在我們離開前，我聽說塔蘭姬公主正前往幽暗谷。她現在應該已經到了。\n\n我們應該回去了。她一定很想知道你是怎麼取勝的！", progress = nil, completion = "奎格瓦在未來的戰鬥中絕對是強大的盟友。等我們擊敗鮮血食人妖時，一定會有許多贊達拉子民來祭拜他。", rewards = "您會收到：\n\n"}
