MultiLanguageQuestData['tw'][47705] = {title = "深陷敵陣", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47706] = {title = "追捕克塔爾王", objective = "帶回克塔爾的顱骨。", description = "獵人！這個挑戰的目標是保護區之王。\n\n克塔爾王是個強大的捕獵者，聰明又迅速。誰能為我把他的頭帶來，就能得到黃金與榮耀。", progress = "狩獵愉快。", completion = "令人佩服。國王被迫遜位了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47707] = {title = "燒毀", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47709] = {title = "偉大的諾姆瑞根路跑", objective = "賽跑到藏寶海灣。", description = "準備好參加路跑大賽了嗎，<name>？\n\n每一年，都會有很多地精從世界各地遠道而來，就只為了從諾姆瑞根一路跑到藏寶海灣！\n\n路跑的目的在於提醒大家，無論多麼崇高的目標，就算是矮小的地精也能辦到。不管跑得快還是跑得慢、跟朋友一起跑還是自己一個人跑，只要不斷嘗試一定能成功！記得拉好筋、做好熱身，出去讓世界見識地精的厲害！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][47711] = {title = "臭蛇之首", objective = "殺掉破碎拱門的領主史利辛。", description = "我在偵察這個區域時，看到一名穿著裝甲的大型納迦對其他臭蛇頤指氣使。我的直覺告訴我，他一定是他們的老大。\n\n只要有人指揮納迦，我們在這裡的行動就會備受威脅。去除掉他。", progress = nil, completion = "很好，那應該能幫我們爭取到一些優勢。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47712] = {title = "毀滅者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47716] = {title = "搜尋廢墟", objective = "到祖爾亞金找喬瓦芭。", description = "沙丘上到處都是殺手，沒有安全之處，但我們還是要繼續前進。\n\n廢墟就離這裡不遠了。\n\n我們繼續步行搜尋吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
