MultiLanguageQuestData['tw'][47725] = {title = "薩格拉斯之墓：艾格文之道", objective = "從普通難度薩格拉斯之墓的戒守聖女身上取得4枚守護者徽印碎片。", description = "封印薩格拉斯之墓時，我把封印的最後一塊交給了戒守聖女。只要拿到它，就能在墓地裡自由移動，不過我不清楚聖女後來怎麼了，恐怕已經遭遇不測。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47726] = {title = "薩格拉斯之墓：艾格文之道", objective = "從英雄難度薩格拉斯之墓的戒守聖女身上取得4枚守護者徽印碎片。", description = "封印薩格拉斯之墓時，我把封印的最後一塊交給了戒守聖女。只要拿到它，就能在墓地裡自由移動，不過我不清楚聖女後來怎麼了，恐怕已經遭遇不測。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47727] = {title = "薩格拉斯之墓：艾格文之道", objective = "從傳奇難度薩格拉斯之墓的戒守聖女身上取得4枚守護者徽印碎片。", description = "封印薩格拉斯之墓時，我把封印的最後一塊交給了戒守聖女。只要拿到它，就能在墓地裡自由移動，不過我不清楚聖女後來怎麼了，恐怕已經遭遇不測。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47728] = {title = "『邪惡魔女』泰莉絲塔", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47733] = {title = "羅亞發言者的背叛", objective = "殺死羅亞發言者基哈拉。", description = "陌生人，聽好。我沒多少時間了。\n\n當卓蘭妮把國王帶到我們這裡時，我在村子裡。說是要保守這個秘密，要不然祖爾會找到我們。\n\n你看看四周。他們找到了！\n\n我知道…我知道那不是先知做的。我們的羅亞發言者對卓蘭妮說了漂亮話，說她會幫忙，然後轉身就把我們都出賣了。\n\n我們現在瀕臨死亡，都是基哈拉的錯。是她讓這一切降臨在我們身上！\n\n殺了她…讓她付出代價！", progress = nil, completion = "那個蛇蠍般的女人協助祖爾找出國王！她最好是死了，否則我會親自解決她。\n\n&lt;卓蘭妮吐了口口水。&gt;\n\n伯昂撒姆第可以留著她。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47734] = {title = "狼狽為奸", objective = "殺死靈魂撕裂者高譚和黑暗編織者吉坦。", description = "瑞贊正在努力對抗束縛，我們卻到不了他身邊。\n\n那個被祖爾召喚到這裡來的魔古升起一面護盾，抵制了我的魔法。找出那個傢伙並殺死它，破除我和羅亞之間的障礙。\n\n我必須集中精神才能面對接下來的戰鬥。他們會在今天好好嚐嚐兩位王者的怒火。", progress = nil, completion = "很好。前進的道路暢通了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47735] = {title = "古老托爾托拉靈藥", objective = "為長老酋爾收集一個毒化河豚脊刺、一塊雷龍鱗片和陳年螃蟹口沫。", description = "啊，是的，事態緊急。我們必須盡快行動，但不能草率行事。\n\n有一個辦法能救拉斯塔哈，但需要三種非常特別的材料。聽好了，年輕人。\n\n第一個是螃蟹嘴裡的泡沫。越陳，越好。\n\n第二個是河豚的脊椎。有毒！\n\n第三個是雷龍鱗片。\n\n為什麼？這是我們族人的秘密，<name>。長壽就像最珍稀的花朵一樣，是需要培養的…要小心翼翼，並且不斷練習。", progress = "治療的品質幾乎全取決於材料的品質。", completion = "這些很好。我很快就會解釋它們的用途。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47736] = {title = "讓頭顱落地", objective = "收集12顆贊達拉叛徒的頭顱。", description = "祖爾的部隊想要攻佔帝王羅亞的神廟。\n\n你一定要讓這些叛徒知道他們的行動代表什麼。\n\n掃蕩褻瀆神廟的汙穢之徒，消滅那些唾棄羅亞的人。把他們的腦袋帶給我，讓我提醒其他人背叛信仰和神王有什麼下場。\n\n在你處理完這些沒有用的傢伙之後，就來找我們。瑞贊的祭壇就在神廟庭園深處。\n\n以拉斯塔哈之名，讓頭顱落地吧！", progress = "輪到我們送道訊息給這些叛徒了。", completion = "留下訊息時，使用他們能理解的語言總是好的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47737] = {title = "瑞贊神殿", objective = "在瑞贊神殿和神王拉斯塔哈會面。", description = "撰史者的消息很不妙。如果祖爾真的打算犧牲瑞贊…\n\n絕對不行！我誓死保護我的羅亞。\n\n來吧，<name>，我們到瑞贊神廟去。一定要立刻阻止這樣的行為！", progress = nil, completion = "&lt;拉斯塔哈怒視著他面前的祭司屍體。&gt;\n\n祖爾會為這件事付出代價。那些追隨他的人必將受苦，我說到做到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47738] = {title = "羅亞的意志", objective = "在賈米爾的小屋放置瑞贊塑像，並說服瑞贊喚回拉斯塔哈的靈魂。", description = "酋爾的藥劑治好了拉斯塔哈的肉身，但他的靈魂還沒有回來。現在只有一件事可以阻止他。\n\n死亡。\n\n他踏入了伯昂撒姆第的暗影之中。在多數情況下，我們無能為力。但是…和他有連結的是另一個羅亞。一個接納忠誠，賦予他生命力的羅亞。\n\n你必須召喚瑞贊，帝王羅亞，並請他找回老拉斯塔哈的靈魂。\n\n從這條路往上走，你會看到我的帳篷。把這塑像放在那裡，然後等待。如果我們運氣好，他就會現身協助我們。\n\n如果他沒來，那…很高興能認識你。", progress = nil, completion = "&lt;拉斯塔哈堅毅地對著你笑。&gt;\n\n看來你見過羅亞了，我知道那種感覺。我下次見到瑞贊時，他肯定有話要對我說。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47739] = {title = "復仇的氣味", objective = "從札巴哈里的祖爾追隨者身上，收集12份叛徒之血。", description = "我了解我的國王，我也知道他不是軟弱的人。他的靈魂在這場背叛的重擔下掙扎，困惑在他的靈魂裡生根，我不禁擔心他的死期已近。\n\n我們得讓他想起肩負的使命。他的憤怒。\n\n我聽到下面的村子裡傳出驚恐的叫聲。祖爾的追隨者為了獵殺他，正在折磨札巴哈里人。殺死那些膽敢傷害他人民的惡徒，並把他們的血帶來給我。\n\n或許復仇的氣味可以喚醒老拉斯塔哈體內的魔暴龍。", progress = "希望我們還來得及，<name>。", completion = "鮮血氣息是喚醒魔暴龍的有效方法。骯髒的叛徒之血效果更好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47740] = {title = "神王之殿", objective = "淨化3座瑞贊的雕像。", description = "我聽到了瑞贊的呼喚，我會回應，但會先需要你的協助。\n\n我們的羅亞賜給我們許多恩澤，而我們以崇敬之心回報。貢品、獻祭和塑像都是我們獲得恩賜的媒介，但是對我們的羅亞來說，它們意義深遠。\n\n它們是力量的泉源。\n\n祖爾的爪牙開始腐化這些獻給瑞贊的偉大黃金塑像。就連現在，我都可以感受到他的力量正在衰落。\n\n阻止他們。淨化獻給偉大獵手的塑像。教導他們如何尊重王室。", progress = nil, completion = "我的羅亞還沒死。現在確保他能維持那個樣子。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47741] = {title = "犧牲一位羅亞", objective = "殺死維納克多爾並阻止瑞贊的獻祭。", description = "瑞贊的力量正在衰退。想篡奪我王位的人就要得逞了。\n\n我曾經在書上讀到祖爾德拉克的恐懼，我也看過這些舉動造成的後果。光是想到我的人民會把這種異端帶來這裡，簡直是…難以想像。\n\n<拉斯塔哈在盛怒中狂嗥。>\n\n來吧！我們會終結這個膽敢對所有羅亞不敬的叛徒！\n\nDi'chuka，瑞贊！", progress = nil, completion = "&lt;隨著瑞贊在暴怒之中復原，露出巨大的形象，全身浴血。&gt;\n\n異教徒。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][47742] = {title = "祖爾的叛變", objective = "登上旗艦拉斯塔哈之力，並殺死10位叛變的贊達拉食人妖。", description = "像拉斯塔哈之力這樣的船艦，少了船員就無法出航。\n\n這表示那艘船上的贊達拉人已經屈從於祖爾的陰謀詭計，而且和他一樣背叛了國王。\n\n登上我的船艦。殺死那些想要起義反對國王的人。我們一個活口都不留。\n\n叛國的下場就是死！", progress = nil, completion = "鮮血染紅了你的雙手。很好。叛變就得付出終極代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47743] = {title = "光與影之子", objective = "跟圖拉揚交談，復活瑟拉。", description = "時候到了，<name>。\n\n瑟拉回來了。我們有聖光之心，她的天選者也在這裡。\n\n跟我來，我們來讓她復活。對付敵人的全新道路就要展開。\n\n等你準備好了，就跟我說一聲。", progress = nil, completion = "我沒想到瑟拉會這樣。當然也沒辦法預知伊利丹會有這種反應。\n\n我們必須確保這些事不會打擊盟友的士氣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47744] = {title = "菸草、肉品和漂亮的花", objective = "取得鹽漬鹿肉乾、格里姆的特殊混合菸草和金盞花束。", description = "孩子，這座城市的後方遭到封鎖。我手上是有鑰匙沒錯，但是我不認識你。\n\n<艾默利慎重地拍了拍他的口袋。>\n\n聽好，你似乎是個正直的好人，我想幫你。幫我找些鹿肉、菸草和一束黃色鮮花回來，說不定我會為你破個例。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時間之沙"}
