MultiLanguageQuestData['tw'][47754] = {title = "牛刀小試", objective = "用聖光審判摧毀擋住瑟納達爾入口的碎石堆。", description = "<name>，你聽得到嗎？很好。\n\n聖光審判已經裝在梵迪卡爾上，可以開始使用了。\n\n我們可以用它來清除擋住瑟納達爾的障礙物，也可以用它來消滅敵人。\n\n不過新功能最好都要先完整測試一下。以防萬一。下面應該有很多適合拿來試驗的目標。", progress = nil, completion = "非常好。道路清空了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47755] = {title = "如痴如醉", objective = "在霧崖海岸解救6名被迷惑的水手。", description = "拜託你幫幫我！我們為了趕交貨時間，改走前面這個岩洞。老天爺…沒想到就此鑄成大錯，這裡到處都是海妖！\n\n只有一種東西能比女人更吸引船員，那就是烈酒！把這拿去，幫他們恢復理智，順便加上兩巴掌，削弱海妖的魔力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
