MultiLanguageQuestData['tw'][47867] = {title = "走海路", objective = "和莉雅德倫女士交談，朝艾克索達出航。", description = "德萊尼打造了一艘飛船，可以把我們平安送到阿古斯。此時此刻，他們正在藍謎島集結入侵部隊。\n\n我們在海邊和他們會合。燃燒軍團肯定會看緊通往它們世界的傳送門。我們必須掌握奇襲的優勢。\n\n準備好的時候告訴我一聲。", progress = nil, completion = "願聖光保佑我們所有人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47868] = {title = "亡者之城", objective = "在亡者之城的中庭與漢札布談話。", description = "我出言必諾，有債必還。\n\n伯昂撒姆第是一名強大的羅亞，你需要進行一個強大的儀式，才能得到他的青睞。\n\n你很走運。我知道該怎麼做。\n\n伯昂撒姆第的神廟「亡者之城」，就在北邊。到中庭跟我碰面，我會安排你晉見掌管死亡的羅亞。", progress = nil, completion = "啊，你來了。要準備開始了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47870] = {title = "死人不會告密", objective = "殺死蘭達爾偵察隊其餘成員。", description = "我受雇於艾胥凡公司，我們是艾澤萊晶岩貿易的龍頭。\n\n當我接下這份工作時，沒人告訴我會有去無回！\n\n我會用盡一切辦法逃離這些沙丘，包括暫時跟你合作。\n\n或許我們可以互相幫個忙？\n\n要是你願意幫我逃離這片該死的沙漠，我可以把船長保險箱的密碼告訴你。\n\n要讓我的計畫成功，我探險隊的同伴非死不可。不能讓他們洩漏我失蹤的事…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "流放精兵護腰末風繫腰灼沙腰環強韌流亡者束腰灼沙之握流放精兵之握末風之握強韌流亡者之握您會收到：\n\n"}
MultiLanguageQuestData['tw'][47871] = {title = "航行必需品", objective = "收集一頂水手帽、航海地圖和老舊的望遠鏡。", description = "雖然這艘船看起來不怎麼樣，但是她能帶我回波拉勒斯。\n\n在我出航前，還需要幾件航海必需品。\n\n幸好，我需要的所有東西，艾胥凡營地都有。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47873] = {title = "隊長的寶箱", objective = "掠奪哈特弗德船長的寶箱。", description = "嗯，我猜你已經都猜到了吧，欸？\n\n我從來就沒打算放棄那些船員，我只是想要扶搖直上。在這方面，你幫我出了不少力。\n\n說到出力，我相信這和哈特弗德船長船長的帶鎖箱有點關係。\n\n密碼在這裡，做為殺死船長的一點回報。就像我保證的一樣。都是你的了！\n\n現在，請你對我們之間的這點小交易保守秘密，好嗎？我可不打算讓這樣的事情，毀了這麼有利潤的合作關係！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][47874] = {title = "撥雲見日", objective = "跟隨戰衛洛琪拉。", description = "是你帶卡嘉過來的？我叫她不要來找我。不安全…\n\n我的頭腦還是不太清楚，但記憶正在逐漸恢復。賈克拉傑…武器…\n\n來吧，我們去吸點新鮮空氣。我會告訴你我的發現。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][47880] = {title = "獻給死亡的供品", objective = "用漢札布的儀式神像，畫出儀式法陣，然後擊打靈魂之鼓來完成儀式。", description = "儀式萬事俱備，現在可以開始了。\n\n我必須吟唱古老的咒語，儀式才能成功。這是相當耗費心神的任務，因此我需要你拿著魔精神像，畫出儀式法陣，然後擊鼓。\n\n如果一切順利，伯昂撒姆第就會邀請我們進入神廟。\n\n不然，我們就會失去自己的靈魂。\n\n千萬別犯錯。", progress = nil, completion = "你敢來這裡，實在相當有勇氣，不過想尋求伯昂撒姆第的協助，光有勇氣是不夠的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47882] = {title = "魔法講修院", objective = "穩定8個混亂的能量導體。", description = "我有個辦法。這個傀儡可以派上用場，我們只需要想辦法讓它醒過來。\n\n我們以前在整座講修院裡面存放了大量的能量導體，我猜它們應該還可以用。\n\n這個給你。\n\n<伊梅拉交給你一個散發著強烈光芒的水晶。>\n\n這裡面的魔法能量可以讓混亂的導體能量變得穩定，最多可以使用八次左右。\n\n只要能夠穩定其中幾個導體，應該就可以恢復整個能量網路。", progress = nil, completion = "好極了，導體都恢復運作了。\n\n不過跟我預想的不一樣，這個傀儡還沒有醒過來。", rewards = "您會收到：\n\n尚未完全充能的導管"}
MultiLanguageQuestData['tw'][47883] = {title = "最漫長的守望", objective = "喚醒守門者。", description = "還好我們有備用的能源。雖然導體已經啟動了，傀儡還是一動也不動。\n\n它可能已經失去動力很久了。可能跟埃雷達斯浮在阿古斯上空的時間一樣久。\n\n它守在這裡的時間還真漫長。\n\n<伊梅拉看著這個傀儡，沉默了好長一段時間。>\n\n你去搖搖它試試看。我們又給了它一些魔法，說不定再搖一下它就會醒過來。", progress = nil, completion = "陌生人，做好準備。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47889] = {title = "代言者的呼喚", objective = "在克庫營地與麥格尼碰面。", description = "麥格尼派你去克庫營地跟他碰面。他找到一樣東西，認為這可以幫我們抵抗燃燒軍團的無盡大軍。\n\n如果要打贏這場仗，我們就要盡可能得到協助。你應該去找他。", progress = nil, completion = "謝謝你來找我，小姑娘，你得看看這個東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47890] = {title = "折磨的景象", objective = "啟動聖石，和麥格尼一起目睹阿古斯的幻景。", description = "自從我來到阿古斯之後就一直聽到耳語。聽起來就像艾澤拉斯…但卻不是她。\n\n我相信阿古斯也是泰坦，他在求我們伸出援手！\n\n破碎者藏有一個聖物，那個聖物對他們來說非常神聖。哈圖恩說他們曾經從聖物裡面聽到耳語…我猜那個東西一定跟阿古斯有某種連結。\n\n聖物就在這裡，我們應該來查個究竟。", progress = nil, completion = "我不知道薩格拉斯是怎麼讓阿格拉瑪復活的，不過這對我們來說是壞消息，相信我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47891] = {title = "壞消息", objective = "回梵迪卡爾找圖拉揚。", description = "<name>，艾澤拉斯送我們過來這裡是對的。我們一定要阻止薩格拉斯的計畫，否則這一切結束之後我們會失去自己的家園。\n\n你應該回去找圖拉揚，告訴他我們發現了什麼。我留在這裡，看能不能蒐集到可以派上用場的資源。", progress = nil, completion = "麥格尼讓你看了什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47892] = {title = "直搗城塞", objective = "前往命運之角。", description = "我們已經占領了納斯拉薩斯堡附近的區域，那是燃燒軍團在阿古斯的主要軍事基地。\n\n趁現在發動攻擊，全力進攻，我們應該把握這個機會一舉扭轉局勢。", progress = nil, completion = "如果我們不加快腳步，這裡的惡魔很快就會消滅我們。", rewards = "您會學到：\n\n光鑄信標：命運之角\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47894] = {title = "四處跳躍", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47895] = {title = "伯特的機器人", objective = "在寵物對戰中擊敗伯特。", description = "如果我要清理諾姆瑞根，我就得準備對抗各種老鼠、蟑螂，搞不好還包括可怕的變種老鼠蟑螂。\n\n我的意思是，我得讓這些機器人進行測試！真槍實彈、實際上陣的演練。\n\n你的寵物準備進行程式碼審查了嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n一袋麻瘋寵物用品"}
MultiLanguageQuestData['tw'][47897] = {title = "贊庫爾叛徒", objective = "殺死10名贊庫爾叛徒。", description = "他們一直在詆毀我們的羅亞，宣稱他們是偽神。\n\n他們又開始玩過去的老方法，崇尚鮮血、獻祭和屈從。\n\n我都不知道該怎麼說這有多羞辱人。殺死所有你遇到的叛徒。", progress = nil, completion = "你殺了多少人？嗯，這是個開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47904] = {title = "保護真正的未來", objective = "克羅米之死事件中，在同一次嘗試內，阻止黑曜、晶紅、蒼藍還有翡翠龍殿的攻擊。", description = "我知道這看起來像我自私的請求，<name>。但我請你幫我真的不只是因為我不想被殺。\n\n我需要你的幫助是因為這不是我命中注定的死法。我一定會死…我看過未來了！但不是現在。再說，為了私人理由胡亂干擾時間之道違反了青銅龍軍團堅守的信念！我當然不可能這麼做。\n\n我們去阻止四座龍殿發生的攻擊吧。那樣應該就行了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章"}
MultiLanguageQuestData['tw'][47906] = {title = "克羅米之死", objective = "克羅米之死事件中，在同一次嘗試內，阻止所有八個針對克羅米的攻擊。", description = "看來我們要阻止所有八個針對我的攻擊行動。而且要在十五分鐘的間隔內完成。\n\n就算是我，聽起來時間也是不太夠。\n\n但也沒有人比我們更有可能勝任這個任務。你準備好了嗎，<name>？您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n套裝：時光占卜者華服套裝：時光守護者鎧甲套裝：裂隙之痕法衣套裝：紀元哨衛鎖甲\n\n您還會收到：\n\n時光扭曲徽章"}
MultiLanguageQuestData['tw'][47915] = {title = "拯救俘虜", objective = "找回蘿蒂的神像。", description = "我們會盡力不讓戰鬥發生在贊庫爾以外的區域，但是我們撐不了太久。\n\n如果你想幫忙，就先釋放戰鬥德魯伊蘿蒂。那些傢伙正在上面的平台，想用黑暗儀式傷害她。\n\n她的靈魂被綁縛在一個神像上。如果你要救她，就得找到那個神像。", progress = "找到…那個…神像。", completion = "終於自由了！噢，現在換他們受苦了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47918] = {title = "為了奎格瓦", objective = "到蛙沼上層和暗影獵手納雷茲會面。", description = "還有其他勢力試圖干擾我的青蛙。那些惡毒的納迦攻擊我的海岸，還從我的青蛙身上榨取魔法！\n\n他們試圖把我的追隨者，當做滿足對法力飢渴的大餐，此等行徑非得阻止不可！\n\n目前有一位名叫納雷茲的暗影獵手正在對付他們。你一定要去協助她，阻止納迦繼續吞噬我的青蛙！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47919] = {title = "向食人陋習說不", objective = "殺掉嗜屍者賈拉卡、勇吉、與納格夏。", description = "修克當然是被納薩沃食人妖抓走的！怎麼這麼容易就被抓了？\n\n我已經厭倦逃離這些食人妖的生活了，所以要你去把事情了結。\n\n納薩沃有三個強大的食人妖巫醫，叫做「嗜屍者」。除掉他們，他們部族就會陷入大亂。\n\n當然，這項行動有可能全盤皆輸，讓我今天的霉運雪上加霜。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47924] = {title = "清除瀆神之物", objective = "使用卡喬許的獄火卷軸摧毀5根瀆神圖騰。", description = "我恨這個地方！我只想要回家，但我不行，因為呆子修克不見了！\n\n聽著，<race>t，如果你幫助我找到那傻蛋，我一定會大大獎勵你。\n\n我有方法能找到修克，但是這些爛圖騰擋住了我的魔法！啊，真是廢話。\n\n拿著這個卷軸，用它來燒毀這些圖騰。我先在附近看看那個呆子是不是在哪裡睡著了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47925] = {title = "今日特餐：修克", objective = "從納薩沃食人妖手中救出修克。", description = "我不知道修克那個傻蛋到底做了什麼傻事，才會被納薩沃抓住，不過等我們把他救出來之後就會曉得了。\n\n跟你打賭，他們一定打算把修克當作大餐給吃了。你必須盡快把他救出來！\n\n修克是我認識的傻蛋裡面，體型最大的，你帶走那些食人妖的「大餐」，他們一定會不高興。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "納茲曼戰鎧腿甲羅亞語者的束腰死亡誓願護脛剝皮儀祭長褲納茲曼戰鎧腰鎧羅亞語者的束帶死亡誓願鎖鏈剝皮儀祭腰環您會收到：\n\n"}
MultiLanguageQuestData['tw'][47928] = {title = "給羅亞的貢品", objective = "與伊拉卡‧諾‧金布爾見面。", description = "現在正是你和偉大的伊拉卡‧諾‧金布爾連繫的時候。\n\n目睹如此古老而強大的神祇現身，我只能想像那是什麼樣的光景。你已經獲得了潮汐之戒，所以有資格和羅亞交談的非你莫屬。\n\n請向羅亞呈上我們部族所提供的貢品。告訴他，我們想要對抗納迦的祈求。\n\n想要存活下來，伊拉卡‧諾‧金布爾是我們唯一的希望。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47939] = {title = "如果鑰匙無誤…", objective = "收集6把艾胥凡商人鑰匙。", description = "這些艾胥凡的傢伙簡直無法理喻。我想和他們談判以重獲自由，但我開出的任何條件都被他們拒絕。\n\n他們只想要那礦坑裡冒出來的東西。我們族裡的人都知道最好不要靠近那玩意，那東西非常不穩定。\n\n礦坑裡有囚犯被迫萃取那東西。至於籠子裡的我們？我們是候補。只要有人死在礦坑，他們就再派批人進去。\n\n如果你能釋放我，我一定會讓你獲得報酬！我們只要找出可以打開這個籠子的鑰匙…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47943] = {title = "抓螃蟹", objective = "捕捉8隻鉗爪螯蟹。", description = "我們被困在此地，糧食和補給品都少得可憐。\n\n這個地區的塞斯拉克掌控了西側的土地，而該死的納迦盤踞在東邊的水域。我們被荒蕪的沙漠和敵意十足的海洋夾在中間。\n\n如果你能前往瀉湖去面對納迦的威脅，能不能幫我們帶點螃蟹回來果腹？\n\n少了食物，恐怕我們的部族馬上就撐不住了…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47945] = {title = "當好人，做好市！", objective = "到鑿刻匠港口和湯瑪斯‧史托頓碰面。", description = "內陸人，非常感謝你幫助我們脫離困境。真不想一直麻煩你，但你願意再幫忙解決另一件事嗎？\n\n在詛咒還沒降臨村落以前，鑿刻匠港口進口的香腸就開始變少了。如果拿不到香腸，我的家人就只能餓肚子！\n\n你願意幫幫誠實、可靠的香腸商人嗎？鑿刻匠港口離這裡不遠，這條路繼續走下去就到了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47946] = {title = "別讓他們變培根", objective = "為崔佛‧海泰德、凱爾‧賽爾弗、崔維斯‧戴布雷克及伯克‧史蒂芬森鬆綁。", description = "<class>，這聽起來會很怪，但我有一些工人被變成豬了！幸好我當時外出去辦事，不然我也會變成豬的！我的人現在都被綁起來，等著進行…加工處理。\n\n<湯瑪斯壓下一股要反胃的衝動。>\n\n我應付不了那些怪物，但你看起來似乎可以。我不確定這會不會有幫助，但我發誓，我聽到倉庫那裡傳來瘋狂的笑聲。\n\n拜託你…救救我的人吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47947] = {title = "大壞狼", objective = "在鑿刻匠港口殺死10隻妖異嗥狼。", description = "這裡到處都是雙眼詭異又會發光的惡狼！我不知道那是什麼，也不知道為什麼眼睛會發光，只知道這絕對不是什麼好事。一定要除掉牠們！\n\n拜託你，<class>，殺掉狼群，別讓牠們傷害我朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47948] = {title = "豬肉塊", objective = "殺死屠夫羅蘭。", description = "羅蘭‧鋼鋸是我見過最優秀的屠夫…但是他瘋了！他還在把豬加工成香腸！\n\n你必須阻止他！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "落港村短斧羅蘭的拍肉錘鋼鋸切肉刀荒秋谷長步槍瘋狂屠夫之錘豬血污漬軍刀老巫婆的湯勺剁肉長矛您會收到：\n\n"}
MultiLanguageQuestData['tw'][47949] = {title = "那不是我的魔像", objective = "將豬魔像交給湯瑪斯‧史托頓。\n\n已提供物品：\n", description = "<你靠近的時候，豬魔像的玻璃眼球似乎也在跟著你轉動。這尊女巫魔像散發出黑暗的能量，一定就是因為這樣，工人才會變成豬的。\n\n或許湯瑪斯‧史托頓會知道該怎麼處理它。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47950] = {title = "解救這些豬", objective = "將豬魔像丟進營火。", description = "我的人會變成豬變不回來，一定就是那個鬼東西害的。\n\n嗯…沒有多少東西能耐得住火焰的淨化！不如燒了它！\n\n把它丟進營火吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47952] = {title = "消失的艦隊", objective = "使用通行證搭渡船到斯陀頌恩修道院。", description = "浪潮賢者在波拉勒斯這裡有一座龐大的修道院。我們就從那裡開始尋找艦隊吧。\n\n那裡一定會有人知道什麼，對吧？一整支傳奇般的庫爾提拉斯艦隊消失不可能只是個意外！\n\n我們必須搭乘渡船前往修道院，記得一定要帶好你的通行證！", progress = nil, completion = "放亮你的照子。我不知道是否所有人都歡迎我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47953] = {title = "『決選者』泰瑞克", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][47959] = {title = "戰衛的足跡", objective = "和米若的商隊一起上路，尋找戰衛洛琪拉。", description = "洛琪拉的日誌上說她往南方去了，這是我們僅有的線索。\n\n米若也要朝那個方向前進，她邀請我們同行。\n\n這些狐狸人比我認識的任何食人妖都了解沙漠。\n\n如果我們一起走的話，存活的機率最高。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47960] = {title = "提拉加德海灣", objective = "前往調查艾胥凡貿易公司。", description = "我們一定要說服凱瑟琳‧普勞德摩爾，願意讓庫爾提拉斯加入聯盟。弗林覺得艾胥凡貿易公司的新火藥是我們最好的線索。", progress = nil, completion = "有你幫忙，或許人民可以對普勞德摩爾的領導能力重拾信心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47961] = {title = "佐司瓦", objective = "提議和威奎斯特家族接觸。", description = "威奎斯特家族堅定的保護者分佈在西側邊境，不過最近斷了連繫。我們一定要取得這些人的協助，才能讓庫爾提拉斯再度團結起來，歸於普勞德摩爾麾下。", progress = nil, completion = "我只有在狩獵的旅途中踏足佐司瓦一次。那是一片崎嶇不平的土地，擁有黑暗的歷史和善於猜疑的人民。為這個任務做好準備。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47962] = {title = "斯陀頌恩谷地", objective = "前往調查失蹤的庫爾提拉斯艦隊。", description = "庫爾提拉斯艦隊從海上消失了。斯陀頌恩那些操弄神秘海洋魔法的浪潮賢者，可能是找到傳說艦隊的唯一辦法。", progress = nil, completion = "浪潮賢者平時就對外來者異常警惕。我會陪你執行任務，或許這次我們可以查到一些答案。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47963] = {title = "遠古之刑", objective = "救出帕骷。", description = "這比我預期的還要糟。帕骷在我心裡哭喊。他們正在對她做某件事，古老又可怕，像是很久以前會發生的事。\n\n她一定就在附近，就在這裡的南邊。來吧，$p，到帕骷棲息處和我見面，我們一起去救她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47965] = {title = "毀棄的神殿", objective = "和堤恰談話。", description = "想要對抗納迦，這位羅亞可能是我們的最後希望，但是神殿破損不堪，無人看管。\n\n我派了兩位部族人員前去勘查廢墟，或許他們可以協助你和伊拉卡‧諾‧金布爾連繫。\n\n如果羅亞的靈魂還留在神殿中，我們一定要找出一個方式，請他傾聽我們的懇求。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47967] = {title = "捕捉塔巴克", objective = "將3隻野生蹬崖塔巴克帶回去給騎兵長吉瑞克。", description = "要是沒有蹬崖塔巴克，我手下的戰士面對燃燒軍團部隊的時候就沒有勝算。要是你們能抓到幾隻帶回來給我，戰士們就更有能力保衛我們的人民了。", progress = nil, completion = "有了這些新坐騎，我們就有勝算了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47968] = {title = "跡象和徵兆", objective = "調查落港村村民留下的文字。", description = "<懷特村長被法術擊中時正在張貼的公告顯示，近日村裡發生了些奇怪的事情。\n\n這些事件很可能都和施咒的人有關連。\n\n或許其他村民那裡也會有記錄，能對魔法的來源提供一些線索。>", progress = nil, completion = "&lt;你所找到的記錄都有一個共同點，全都指向一名最近剛來到村裡的老婦人。\n\n這本記錄簿可能會有跟她下落有關的線索。&gt;", rewards = "您能選擇下列奬勵中的一個：\n\n棄置的好運墜飾\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47969] = {title = "落港村的詛咒", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47978] = {title = "難以捉摸的老婦人", objective = "到海倫娜‧簡托位於落港村外的住所找她。", description = "<記錄簿顯示，有個名叫海倫娜‧簡托的老婦人最近剛搬到這裡，在鎮外道路的另一頭住了下來。\n\n從村民留下來的文字可以看出，她和村裡最近出現的各種疾病都有某種關聯。\n\n她有可能知道這個法術背後的真相，希望法術還沒有對她造成影響。>", progress = nil, completion = "噢，你好啊，年輕的小姑娘。\n\n落港村不常出現訪客。你來找我有什麼事嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47979] = {title = "獵巫", objective = "在隱蔽丘陵聆聽海倫娜‧簡托的故事。", description = "對村民施放詛咒？我的天，真是太可怕了！\n\n不過，老實說，落港村最近的確發生不少怪事。我在想，會不會就是這些事引起的？\n\n拉張椅子坐坐，喝點茶吧。我會把我知道的都告訴你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47980] = {title = "狂怒的動物", objective = "在隱蔽丘陵殺死10隻被控制的動物。", description = "<丘陵這裡的野生動物似乎被海倫娜施了法，而這個村民似乎成為了牠們的受害者。\n\n落港村最近常常有人失蹤，一定就是因為牠們。\n\n要是能減少牠們的數量，或許就可以降低牠們對村民造成的威脅。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47981] = {title = "打破詛咒", objective = "摧毀4個隱蔽丘陵的小型咒像。", description = "<看來海倫娜在匆忙之中遺落了她的法術書。書中詳細地記載了她用來困縛落港村村民的儀式。\n\n維持村子裡這道法術的咒像，看來是受到圍繞村子的小型咒像保護。如果摧毀那些小型咒像，你或許就能解決掉詛咒村民的咒像了。>", progress = nil, completion = "&lt;縈繞著咒像的魔法能量已經消散。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47982] = {title = "最後的咒像", objective = "在落港村摧毀被詛咒的咒像。", description = "<咒像的防護已經消失了。\n\n接下來就能破壞咒像本身了。>", progress = nil, completion = "怎麼…回事？我站在這裡多久了？\n\n詛咒！？你說整個村子就這樣…停住了？我就知道那個老太婆很不對勁…\n\n看來落港村欠你一個很大的人情，陌生人。", rewards = "威奎斯特民兵護脛邪織護腿尋巫者腿甲放逐者馬褲邪織腕輪威奎斯特民兵護腕尋巫者護腕放逐者護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][47986] = {title = "過去的傷痕", objective = "取回祈願陣列、復仇者裝甲和審判核心。", description = "聖光軍團靠著機甲在阿古斯贏過許多場戰爭。雖然機甲很強大，但也不是每具機甲都能完好無缺。\n\n等我完成機甲的改造之後應該可以提高我們的優勢，但我還缺少幾個關鍵的零件。\n\n我們在納斯拉薩斯打過幾場仗，或許可以從那裡的殘骸中收集到一些有用的東西。如果你能找到我需要的零件，就能讓燃燒軍團嘗嘗我們的厲害。", progress = "你拿到零件了嗎？", completion = "太好了！謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47987] = {title = "預防手段", objective = "用預言者咒符淨化9名陣亡的聖光軍團戰士。", description = "燃燒軍團真讓我覺得噁心。它們打贏的每場仗、征服的每一個世界，都讓它們擁有更多靈魂，拿來作為發動更多戰爭的能量。\n\n它們還沒有腐化在堡壘中陣亡的所有靈魂，但我想這只是遲早的事。拜託你，帶上這個咒符進到堡壘裡面，用它來淨化你所發現的屍體。\n\n他們不應該受這種苦。", progress = nil, completion = "謝謝你，&lt;name&gt;。你的行動讓燃燒軍團少了幾分力量，也讓亡者得到了應有的平靜。", rewards = "您會收到：\n\n沐聖戰士紀念物"}
MultiLanguageQuestData['tw'][47988] = {title = "混沌理論", objective = "殺死12個納斯拉薩斯斬肉者、納斯拉薩斯末日射手或飢餓的獵魂者，以及1個納斯雷茲姆災禍領主。", description = "雖然燃燒軍團力量驚人而且數量龐大，但是它們還是需要良好的組織才能有效作戰。擾亂它們的陣腳…讓它們變成一盤散沙。\n\n計畫很簡單，讓它們方寸大亂，我們就能打贏這場仗。", progress = nil, completion = "它們的部隊秩序大亂了，我們趁機推進吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47989] = {title = "末日使者", objective = "殺死赫勒媞卡女士和阿波崔絲女士。", description = "眼前是個難得的機會。\n\n我們的斥候在西邊的魔化池發現兩個正在指揮燃燒軍團備戰的希瓦拉女祭司。\n\n薩格拉斯親選的手下大將向來不會離開安托洛斯，如果殺死這兩個希瓦拉女妖，或許能讓黑暗泰坦的親信感到一絲恐懼。", progress = nil, completion = "你很厲害。沒有那兩個女妖增強惡魔的力量，我們或許還有點勝算。", rewards = "您會收到：\n\n一瓶「神聖的」魔化液體"}
MultiLanguageQuestData['tw'][47990] = {title = "只要一點魔能", objective = "取得一個無瑕魔核。", description = "我們的機甲快要準備完成了！現在只需要把能量灌注到系統裡就可以啟動了。\n\n有術士在下面的池子裡使用魔能把阿古斯的一部分製作成有生命的攻城武器。如果你能幫我拿回一個，就可以啟動機甲的審判核心！", progress = "記住，要完美無瑕的才可以！", completion = "沒錯！就是這個！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47991] = {title = "黑暗詭計", objective = "摧毀3個苦痛魔塔。", description = "埃雷達爾很擅長操控在這個世界裡流動的魔能。那些沒有成為活體武器的，建造了其他的武器，像是苦痛魔塔。\n\n有這些魔塔在，就連想要偷偷潛入敵人的基地都很困難。我們必須摧毀魔塔，讓數量減少，才可以順利進入敵人的要塞。", progress = nil, completion = "任何戰爭都無法靠單一行動獲勝，它們少了那些魔塔的保護，我們遲早會攻破要塞。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47992] = {title = "正義的曙光", objective = "使用光鑄機甲控制住復仇者之庭。", description = "謝謝你的幫忙，敵人陷入了混亂，它們的防禦也失去了作用。\n\n我們必須控制魔塔四周的區域，準備圍剿它們的指揮官。\n\n你已經取得在戰場上使用機甲的資格了。等到清空路上的敵人，我們就跟你一起殺進去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47993] = {title = "魔塔之王", objective = "擊敗納斯拉薩斯領主。", description = "納斯拉薩斯領主統治著這座堡壘，這是他在多年前協助燃燒軍團占領阿古斯的獎賞。\n\n仔細聽好，雖然他很強大，但是權力讓他變得驕傲自滿。\n\n利用他傲慢的弱點，用你的機甲好好教訓他。我們很快就會攻進庭院！", progress = nil, completion = "以聖光之名…", rewards = "您會學到：\n\n納斯拉薩斯堡世界任務\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47994] = {title = "建立連結", objective = "經過了徹底的測試，我會趕緊吩咐工藝師為機甲充能，這樣你才能在戰場上召喚它。你可以隨時在系統核心選擇你要的能力。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n光鑄機甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][47995] = {title = "大刀闊斧", objective = "找到神射手巴瑞特、大復仇者索沃斯和大劍師特來蒙。", description = "<name>，我的士兵都還在戰場上。\n\n請你幫我去找巴瑞特、索沃斯和特來蒙。燃燒軍團打過來的時候，費倫要他們守衛這個區域。\n\n請幫我傳達命令，要他們立刻去跟費倫會合。\n\n我需要你大刀闊斧，消滅阻礙你的軍隊。做你該做的。\n\n願聖光保佑你平安。", progress = nil, completion = "法芮雅的部隊是聖光軍團裡的精銳。有了他們，我們就勝券在握了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47996] = {title = "喉魔滅絕", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][47998] = {title = "除掉食人族", objective = "殺死10名納薩沃食人者。", description = "我跟修克兩個，之前和納薩沃有過幾次爭執。一定是這樣他們會抓走那傻蛋。\n\n那個部族裡面的女人會吃掉男人…以及任何落入她們手中的外人。我很肯定，她們一定準備拿修克來大快朵頤。\n\n幫我們大家一個忙，去殺掉幾個食人族吧。少了他們，世界會更好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48002] = {title = "物資匱乏", objective = "前往灰石林回收12個空瓶。", description = "嗨，<name>，能見到同行真好。\n\n長久以來，我一直提供對抗惡魔需要用到的藥水，可是這陣子物資不夠用了。原本哨兵隊巡視時都會把剩下的空瓶帶回來，但現在能安全返回的哨兵越來越少。\n\n我已經盡可能回收利用，你看，那些空瓶對我來說很重要。如果你願意幫我回收空瓶，我就跟你分享擊退惡魔的妙方。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：聖光之血藥劑"}
MultiLanguageQuestData['tw'][48003] = {title = "領主的邀請", objective = "到諾爾威頓莊園和諾爾威頓領主碰面。", description = "諾爾威頓領主想親自感謝你救了他兒子。要不要來莊園逛逛？我們正在準備慶典，歡迎所有人參加。\n\n我們會直接過去告訴他發生了什麼事。到時見囉！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][48004] = {title = "初試身手", objective = "騎上古柏並練習你的庫爾提拉斯騎乘技巧。", description = "你或許已經知道怎麼騎馬，但你肯定比不上庫爾提拉斯式的騎術！\n\n我們可以借你一匹馬參加慶典。就讓你騎古柏吧。很多新手都是跟他一起訓練成長的！\n\n上馬進入馬場，我們來看看你有什麼本事！我猜你一定能學得很快！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48005] = {title = "貴客蒞臨", objective = "參觀莊園，並且參與慶典。", description = "<name>，我親愛的朋友，希望你能盡情享受慶典。我每年都會舉辦這場盛大活動，把全庫爾提拉斯的騎士通通聚集到這邊！\n\n你可是慶典最尊貴的嘉賓。請不要拘束，逛逛莊園，享受美食、好酒，多認識一些朋友吧！請！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48008] = {title = "危險物品", objective = "燒毀5個被感染的貨物。", description = "等到我發現情況不對，已經太遲了。\n\n大家的行動愈來愈怪，起初我不以為意，畢竟他們看起來還是在努力工作。\n\n我檢查貨物時，有隻幼蟲跳出來，想吸住我的臉。我把牠解決掉了，但事情已經失控了。\n\n所有的貨物都被感染了。拿著這把火炬，毀掉所有貨物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48009] = {title = "背叛衛隊", objective = "殺死10名神智不清的執法者。", description = "我的手下已經陷得太深。\n\n他們受邪惡的力量影響，無法脫身。\n\n解決他們時不必猶豫，當他們踏上歧途，就很清楚會有什麼後果。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48013] = {title = "追蹤拾荒者", objective = "在安尼希蘭陷坑殺死14個魔焰拾荒者。", description = "<name>，我跟你提過嗎？哨兵會用我的追蹤藥水去追蹤惡魔，特別是魔焰犬魔。\n\n這種惡魔會把附近的暗星之芒吃光，害我們常常缺乏草藥。\n\n如果你可以幫忙減少它們的數量，我們就不用長途跋涉去採草藥了。你可以在安尼希蘭陷坑找到這些惡魔。\n\n作為回報，我可以教你怎麼調製這種追蹤藥水。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n配方：那魯之淚"}
MultiLanguageQuestData['tw'][48014] = {title = "清除烏合之眾", objective = "在拾荒者海岸殺死6個吉爾布林。", description = "納迦派出他們那些體型小、邪惡又臭得要命的僕從進入我們的營地。真是惹人厭。\n\n如果我們放任不管，他們的數量就會越來越多，很可能會造成威脅。\n\n你看起來又可靠動作又快，或許可以幫我清掉他們？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48015] = {title = "格拉爾的卷軸", objective = "取得3個托爾托卷軸。", description = "這些吉爾布林實在太荒謬了！他們就像一群生氣的蜜蜂，在附近嗡嗡嗡地叫個不停。\n\n嗯，或許不像蜜蜂。蜜蜂很有用，會生產蜂蜜，而且不會偷東西。\n\n他們洗劫了我們的卷軸。雖然大多數都不能用，但其中有三個卷軸…可是蘊藏無窮力量。\n\n如果他們把這些東西送回納迦主人手裡，事情就麻煩了。請想辦法清理他們造成的一團混亂，並把我們的卷軸帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48016] = {title = "進階鍊金術", objective = "把75朵暗星之芒、5個原始薩格拉斯精華、一個束縛煉獄鍊金石帶給傅南。", description = "我有看到其他鍊金師帶著特殊的飾品來到我們的營地，好像叫什麼…「鍊金石」？\n\n我可以感受到那種石頭散發出強大的力量，但那是被惡魔汙染過的力量。生長在這個星球上的草藥具有優秀的淨化能力，我常用來淨化草木中找到的原始薩格拉斯精華。\n\n如果把淨化過的薩格拉斯精華用在鍊金石上，或許有辦法提升鍊金石的力量。", progress = "我知道要準備那麼多東西很不容易，但請相信我，這絕對是必要的。", completion = "啊，你把東西帶來了！這項技術讓你用來對抗燃燒軍團應該更有用處。\n\n仔細聽我解說吧…", rewards = "您會學到：\n\n配方：暗星鍊金石"}
MultiLanguageQuestData['tw'][48021] = {title = "克羅米", objective = "在龍骨荒野與克羅米達到「時空跳躍者」友誼等級 。", description = "<name>，是你嗎？\n\n我覺得時間線有點不對勁。我需要你幫忙！\n\n到龍骨荒野的龍眠神殿來找我，我會讓你知道。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n尋路者的日晷"}
MultiLanguageQuestData['tw'][48025] = {title = "晚點再拿", objective = "隱藏格拉爾的古物。", description = "我們需要時間才有辦法從這個地方找回聖物，但納迦不會給我們這些時間。\n\n不過，我們想出了一個計畫。\n\n只要把我們不想讓他們發現的東西藏起來，等個十年或二十年再回來。到時他們早就忘掉這個地方了。\n\n把這個幻象卷軸拿去，用它們來隱藏以力量聞名的聖物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48026] = {title = "浪潮之下", objective = "殺死召喚者希爾伐許和低語恐獸。", description = "這些女巫真放肆！在我的神廟？\n\n希爾伐許越過了她所無法駕馭的領域。那裡有一股黑暗正在尋找他們，而他們居然加以呼喚！那些回應呼喚的事物，會把她的族人化為沒有靈魂的工具。\n\n我可以感受到它在我們下方移動，環繞著我們。我可以感受全身傳來的顫抖。\n\n那邊傳來一股力量，其重量遠勝於最深邃的海洋。\n\n我們一定要阻止他們。這裡不歡迎他們！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "強化鯊魚齒您能選擇下列奬勵中的一個：\n\n低語海巫之戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][48027] = {title = "阿古斯的光芒", objective = "在阿古斯找到能教你怎麼處理暗星之芒的人。\n\n已提供物品：\n", description = "<沒想到這個星球竟然存在如此純淨的生命。你小心翼翼採下花朵，有一股微小的力量湧現，然後消失。>\n\n<花在你手中粉碎了。在這個連聖光都不願眷顧的星球，不知道還有沒有人知道如何處理這種珍稀植物。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：暗星之芒(等級1)"}
MultiLanguageQuestData['tw'][48028] = {title = "固執的小花", objective = "問傅南如何採集初生的暗星之芒。\n\n已提供物品：\n", description = "<你在採集暗星之芒時發現有些初生的小花非常難摘。也許傅南可以教你怎麼採集初生的暗星之芒。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：暗星之芒(等級2)"}
MultiLanguageQuestData['tw'][48029] = {title = "光芒之心", objective = "問傅南為什麼暗星之芒的根部會閃閃發光。\n\n已提供物品：\n", description = "<你接觸暗星之芒也好一陣子了，發現這種植物的根部很特別，有像繭一樣的殼緊緊包住，縫隙間散發出微弱的光芒。>\n\n<也許傅南能說明為什麼會這樣閃閃發光。>", progress = nil, completion = "這朵暗星之芒好像已經完全信任你了，漸漸對你敞開心房。\n\n注意自己的意念，你就能得到暗星之芒。", rewards = "您會學到：\n\n採藥技術：暗星之芒(等級3)"}
MultiLanguageQuestData['tw'][48034] = {title = "燦鐵礦床岩塊", objective = "在梵迪卡爾找到能教你怎麼開採燦鐵礦床的人。\n\n已提供物品：\n", description = "<當你用採礦鎬敲擊礦石時，會發出一聲巨響，然後敲下一小塊礦石。照這樣子看來，你會需要一整天才能從這採到足夠的礦石。>\n\n<或許有人可以告訴你比較有效的採礦方式。>", progress = nil, completion = "想採集燦鐵，必須用精準的敲擊方式才能得到最好的礦石。把你的採礦鎬對準礦石最明亮的地方，可能是很小的點，所以精準很重要。\n\n這樣一來可以提高敲開礦床的速度，你採集礦石的速度也會加快。", rewards = "您會學到：\n\n採礦技術：燦鐵礦床"}
MultiLanguageQuestData['tw'][48035] = {title = "調整敲擊角度", objective = "與卡密爾交談以了解是否有更好的方式來開採燦鐵礦床。\n\n已提供物品：\n", description = "<看著採集這個礦床時落下的燦鐵礦屑，你在想是否有辦法避免部分礦床在敲擊時碎裂。>\n\n<或許卡密爾能告訴你進一步的資訊。>", progress = nil, completion = "我先前提過，想採集燦鐵的話，精準才是關鍵。你已經知道要敲擊正確的點了，現在要學習的是用正確的角度敲擊。\n\n放下你的採礦鎬，我來示範一下正確的方式…", rewards = "您會學到：\n\n採礦技術：燦鐵礦床"}
MultiLanguageQuestData['tw'][48036] = {title = "提升精準度", objective = "與卡密爾交談以了解是否還有比先前更好的方式來開採燦鐵礦床。\n\n已提供物品：\n", description = "<雖然你已知道如何取得大量礦石，但這些礦石的核心都已損壞，無法使用。如果仔細看，可以發現是你的敲擊方式破壞了礦石結構。>\n\n<或許你還需要再向卡密爾請教，改正這個問題。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：燦鐵礦床"}
MultiLanguageQuestData['tw'][48037] = {title = "燦鐵礦層岩塊", objective = "在梵迪卡爾找到能教你怎麼開採燦鐵礦層的人。\n\n已提供物品：\n", description = "<一開始，你認為礦石表面就像鏡子，映照著你頭頂上的星空。但在敲下一塊之後，你發現星雲狀的紋路源自於礦石本身的結構。>\n\n<或許梵迪卡爾那裡有人可以給你一些建議，幫助你更有效地採礦。>", progress = nil, completion = "燦鐵在採集下來以後，看起來非常璀燦耀眼。正如開採礦床需要精準，開採礦層則需要清除雜石。\n\n如果你能花點時間清除周圍的岩石，就會發現更多可以採集的礦石。", rewards = "您會學到：\n\n採礦技術：燦鐵礦層"}
MultiLanguageQuestData['tw'][48038] = {title = "不要光是敲打", objective = "與卡密爾交談以得知如何從燦鐵礦層中採得更多礦石。\n\n已提供物品：\n", description = "<即使你已經知道該怎麼清除礦石周圍的雜石，大型的燦鐵礦石還是跟周圍的岩石緊緊相連。清除這些雜石的話，可能無法如你所願得到純粹的燦鐵礦石。>\n\n<或許卡密爾知道該怎麼把礦石從這些岩石當中挖出來。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：燦鐵礦層"}
MultiLanguageQuestData['tw'][48039] = {title = "拿捏平衡", objective = "與卡密爾交談以得知如何從燦鐵礦層中採得比原本更多的礦石。\n\n已提供物品：\n", description = "<一旦敲到礦層的底部，你只會得到細小的礦石碎片。不過全部收集起來，應該還夠我們用。<\n\n<卡密爾或許知道該如何避免這種事情發生。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：燦鐵礦層"}
MultiLanguageQuestData['tw'][48040] = {title = "受污染的屍塊", objective = "在梵迪卡爾尋找能夠教你剝下魔質皮革的人。\n\n已提供物品：\n", description = "<當你開始小心翼翼剝下屍體的皮，發現皮革因為屍體潰爛而快速腐化。>\n\n<如果用扯的，只能取得少量皮革，而且還有魔化能量的味道。或許在梵迪卡爾有人更瞭解這種邪惡的皮革。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：魔質皮革(等級1)"}
MultiLanguageQuestData['tw'][48041] = {title = "大刀闊斧", objective = "與安斯塔討論如何更有效率地剝下魔質皮革。\n\n已提供物品：\n", description = "<雖然你已經可以更快速地剝下皮革，但在你徹底剝除皮革之前，皮革還是有很多地方受損。>\n\n<安斯塔或許知道如何在腐化之前剝下更多皮革。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：魔質皮革(等級2)"}
MultiLanguageQuestData['tw'][48042] = {title = "解剖的順序", objective = "與安斯塔討論如何用更好的方法解剖阿古斯的野獸。\n\n已提供物品：\n", description = "<皮革的數量已經很充足了，但你搶在腐化之前收集的牙齒和爪子數量還是很少。>\n\n<由於不知道如何保住最多的牙齒和爪子，你想再回梵迪卡爾找安斯塔，再向他請教最後一次。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：魔質皮革(等級3)"}
MultiLanguageQuestData['tw'][48053] = {title = "錨的原料", objective = "將一箱魔岩交給暴風港的沃科特‧薩頓。", description = "<name>，我想請你幫個小忙。暴風港的海軍艦隊向我要了大量的魔岩，要用來打造船艦。\n\n但我現在忙著協調蒐集工作，所有的信差也都不在。你介意替我跑個腿，把貨送去給他們嗎？\n\n我聽說達拉然狼牙領區有一道通往暴風城的傳送門，所以這趟旅程應該不會太遠。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：魔岩錨具"}
MultiLanguageQuestData['tw'][48054] = {title = "錨的原料", objective = "將一箱魔岩交給污水碼頭的克魯妲‧雷手。", description = "<name>，我想請你幫個小忙。污水碼頭的海軍艦隊向我要了大量的魔岩，要用來打造船艦。\n\n但我現在忙著協調蒐集工作，所有的信差也都不在。你介意替我跑個腿，把貨送去給他們嗎？\n\n我聽說達拉然風行者聖堂有一道通往奧格瑪的傳送門，所以這趟旅程應該不會太遠。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：魔岩錨具"}
MultiLanguageQuestData['tw'][48055] = {title = "燦鐵之力", objective = "製作燦鐵胸甲。你可以在阿古斯蒐集礦石，也能從其他玩家或拍賣場取得所需的材料。", description = "看來你對我的護甲很感興趣。這是用阿古斯最好的材料做成的，這種材料叫燦鐵。我對製作胸甲特別專精。\n\n我可以讓你看看要怎麼做，不過你恐怕要自己準備材料才行。我們的礦石存量不多，所以我們沒有多餘的礦石供你使用。\n\n設計圖就在這裡，這樣你就知道該去找什麼了…您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：燦鐵胸甲"}
MultiLanguageQuestData['tw'][48056] = {title = "重力的考驗", objective = "在達拉然幫助荷巴爾特校準原型反重力鞋套。", description = "我在想辦法讓所有人都能在那個叫做阿古爾還是什麼東西的地方自由移動。我發現那裡的重力和我們這裡不同，所以研發了可以裝在你的鞋子、蹄或任何腳部裝備上的設備。\n\n結果後來有人告訴我，那裡的重力和我們的一模一樣！\n\n不管怎樣，我都應該要讓原型產品派上用場，你願意幫助我嗎？等事情結束後，你可以把這些東西賣給小孩，或許啦。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：反重力鞋套"}
MultiLanguageQuestData['tw'][48065] = {title = "外星探險", objective = "在地圖上標記的位置使用離子地貌紀錄器。任務完成後再回去找狄迪。", description = "<name>，聽說你已經去過天空中那顆綠色的大星球，聽說那裡到處都是惡魔。\n\n我們或許可以為那顆星球製作另一個蟲洞產生器，如此一來在那裡移動會簡單許多。\n\n問題是我們需要那個星球的地貌數據，我很樂意去，但…我得留在這裡顧店，我不放心把店交給這些半吊子。\n\n這給你，去幫我取得數據，可以嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n結構圖：蟲洞產生器：阿古斯"}
MultiLanguageQuestData['tw'][48066] = {title = "宴請親族", objective = "在莫高雷的雷霆崖跟貝恩‧血蹄碰面。", description = "啊，高嶺牛頭人。自從我們打倒軍團之後，他們一直是我們的盟友。\n\n你想不想聽聽他們怎麼加入部落？那真是精彩的故事！\n\n這要從貝恩‧血蹄與梅拉‧高嶺開始說起。貝恩在雷霆崖舉辦了一場盛宴，來歡迎高嶺牛頭人…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48067] = {title = "籠罩雷霆崖的暗影", objective = "在雷霆崖殺死4個黑暗觸鬚和12個烏蓋涅斯之影。", description = "邪惡降臨了。我不相信這會是高嶺牛頭人在背後搞鬼。\n\n這種刺耳雜音，聽起來有些熟悉。該不會是…\n\n可惡！是古神的爪牙在攻擊我們！<name>，我們一定要保護雷霆崖！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48069] = {title = "扳手的呼喚", objective = "到達拉然找『扳手』狄迪。", description = "<name>，『扳手』狄迪要你回達拉然找她，你最好去看看她做了什麼。聽說是蠻不錯的東西。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][48070] = {title = "諾爾威頓慶典", objective = "前往狐穴森林邊界和艾比‧瓦金斯見面。", description = "敬啟者：\n\n恭請光臨第15屆諾爾威頓馬術暨狩獵慶典！\n\n庫爾提拉斯各界人士將以精湛的馬術和狩獵活動慶賀生命的華麗饗宴，屆時所有品味相若、想法相近的貴賓都有機會更熟悉彼此。\n\n狩獵活動會率先登場，由艾比‧瓦金斯在狐穴森林展開序幕。狩獵活動結束後，會在諾爾威頓莊園展開馬術活動。\n\n希望能邀請你共襄盛舉！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48074] = {title = "我的織布機", objective = "前往亞林諾爾庭園取回綺拉的光紡織布機。", description = "我在趕往瑟納達爾時，丟下了一件非常珍貴的工具，就是我的光紡織布機。少了它，我得花更久的時間才能為盟友製作強力服飾。\n\n但你實力堅強，比我強大很多，或許你可以助我一臂之力。如果你哪天剛好在亞林諾爾庭園，可以幫我取回織布機，然後帶來給我嗎？\n\n我會很樂意向你分享關於光紡技法的知識。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n圖樣：光紡馬褲(等級1)"}
MultiLanguageQuestData['tw'][48075] = {title = "色彩繽紛的鑰匙", objective = "前往沃羅的家並一一使用這勘探燦鐵所獲得的六枚寶石打開他的箱子。取得他的珠寶設計書籍並回到梵迪卡爾找他。", description = "<name>，聽說你是珠寶設計師。我也是，但我擔心我的設計會被燃燒軍團奪走。\n\n我在逃出家園時還以為能再回去，但我恐怕太天真了。我把珠寶設計書留在家裡，那是我最珍貴的財產。\n\n你很強壯，應該可以突破重圍，請你去我家幫我把書拿回來！\n\n我把書鎖在一個特製寶箱內，需要這片土地上的寶石才能解鎖。每種寶石都需要一顆才行。", progress = "要打開箱子不會很困難，只要把寶石放到適當的位置上就好。", completion = "我的書！看起來還完好如初，感謝聖光保佑。\n\n看這裡，&lt;name&gt;。\n\n\n\n這些設計可以教你把寶石變成具有力量的配件。", rewards = "您會學到：\n\n設計圖清單：阿古斯寶石雕刻"}
MultiLanguageQuestData['tw'][48076] = {title = "巔峰之作", objective = "為沃羅製作燦鐵皇冠。你可以在阿古斯探勘礦石，也能從其他玩家或拍賣場取得所需的材料。", description = "有鑒於這本書差點就永遠不見天日，我認為不應該把這麼豐富的知識封存起來，我決定把知識傳授給你，<name>。\n\n我最新的設計特別令我感到驕傲，我把它稱為燦鐵皇冠。不同的燦鐵皇冠具有不同的寶石組合，進而產生不同力量及效果。\n\n讓我先教你如何製作，再告訴你不同的寶石組合如何產生不同效果。", progress = "或許有朝一日你也會遇到一個學徒，然後把所有知識傳授給他。", completion = "做得好，&lt;name&gt;。再來是另一個組合…", rewards = "您會學到：\n\n設計圖清單：阿古斯頭冠"}
MultiLanguageQuestData['tw'][48077] = {title = "獵鼬行動", objective = "從輕足鼬身上收集5張柔軟的鼬皮。", description = "波拉勒斯的貴族最喜歡獵鼬了。這是結合決心、耐心、技巧的活動。你能面對挑戰嗎？\n\n鼬是敏捷、鬼祟、機靈的動物，想在森林逮到鼬幾乎是不可能的，最好的方法就是去鼬的巢穴，把鼬嚇出來。\n\n去找鼬的巢穴吧，然後把柔軟的鼬皮帶回來。這種柔軟的毛皮很受貴族歡迎。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "劫海者重腿甲領航員束褲翼艇鎖鍊護腿掠劫者束褲領航員束腕劫海者腕甲翼艇束腕掠劫者束腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][48078] = {title = "保持平衡", objective = "收集魔質皮革與光紡布，並使用安斯塔的鞣製油製作12份淨化魔質皮革。", description = "以前我還能用這裡的野獸製作珍品，但之後燃燒軍團來襲，消滅了所有珍奇異獸。\n\n逼得我只能用它們汙染過的皮革為盟友製作護甲。不過我發現了去除污染的方法。\n\n我們使用的布料是由注入聖光能量的特殊絲線製成，我研發出一種油，可以在與布料結合時淨化皮革，讓皮革適合使用。\n\n來，試試我的油，自己親眼見證一下。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n圖樣清單：阿古斯製皮"}
MultiLanguageQuestData['tw'][48079] = {title = "返回高嶺", objective = "在高嶺的雷霆圖騰和梅拉‧高嶺見面。", description = "靈行者黯角的處境還是非常危險。他和梅拉已經回到高嶺，但我認為他們還是需要我們伸出援手。\n\n我們應該前往雷霆圖騰，盡全力治療黯角。或許這樣一來，能使我們兩族之間的關係更為緊密。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48080] = {title = "危險刺激的狩獵", objective = "收集8根粗壯的野豬獠牙。", description = "這些貴族真以為殺掉幾隻鼬鼠就算狩獵高手？哈！\n\n如果不危險刺激，又怎麼能算狩獵？這座森林有野豬出沒，在山區野豬跑得比我們還快！或許你可以去殺幾頭野豬，把獠牙帶回來當證據？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48081] = {title = "飄浮的廢墟", objective = "前往埃雷達斯。", description = "雖然早就知道燃燒軍團是可怕的對手，不過這陣子的戰況顯示，我們恐怕已經力有未逮。我們犧牲了這麼多，不能在這個重要的時刻失敗。\n\n我知道在我的故鄉埃雷達斯有個聖物，它可能是我們獲勝的關鍵。一定要讓梵迪卡爾飛往阿古斯的上空，前往那座飄浮的廢墟。\n\n我們或許會在那裡找到勝利的希望。", progress = nil, completion = "&lt;費倫緊盯著眼前的廢墟。&gt;\n\n我回到家了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48087] = {title = "取馬", objective = "去山頂的莊園取回諾爾威頓領主的愛馬「玫瑰」。", description = "朋友，我對你印象不錯！\n\n我跟你說，其他客人隨時都會出現。你能幫我去山上的莊園，把我最愛的馬帶來嗎？\n\n想像一下，所有貴賓對你的第一印象就是坐在全提拉加德最尊貴不凡的馬上！很妙吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48088] = {title = "穴居怪的派對厲害", objective = "在諾爾威頓莊園殺死20個汙石穴居怪。", description = "穴居怪？出現在我的派對中？\n\n祖父在許多年之前把牠們趕回霧臨之隙，才建立了這座莊園。誰想到牠們在過了這麼多年之後會反撲？\n\n這樣正好能讓今年的慶典比往常更盛大！\n\n讓我們親眼目睹你的英勇氣概，<name>！騎上古柏，擊敗穴居怪！把牠們綁起來拖著跑，或者用魚叉戳牠們…隨便什麼都好！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "狂歡者之鋒陷鼬刺拳穴居怪打擊者汙石滅錘諾爾威頓長柄斧奧椎亞斯領主的巨杖粗脖幫騎士手斧谷喙狩獵步槍馬術家鞍具小刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][48089] = {title = "山岳之聲", objective = "使用崇山戰鬥號角來激勵8名庫爾提拉斯人。", description = "庫爾提拉斯人沒有那麼容易屈服！\n\n拿著這把號角。這是我們在山裡互相警告危險或衝鋒陷陣用的號角。用號角激勵盟友，一起對抗穴居怪！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48090] = {title = "奎格瓦的勇士", objective = "搭救睿智的闊卓、機靈的沃克古格、以及無畏的瓦薩許。", description = "真是一團亂，<name>。那些納迦從奎格瓦的青蛙身上汲取魔力供自己享用！\n\n那裡有三隻青蛙，都是奎格瓦的勇士，在我們交談的時候身陷苦難。\n\n拿著這瓶藥水，它可以恢復那些尊貴青蛙的力量。他們不應該被這些「蛇」精病榨乾。\n\n我會待在這裡，那個運氣好的納迦居然讓我受傷。我這一輩子都想見到奎格瓦，而我居然讓納迦傷到了我！", progress = nil, completion = "你辦到了！奎格瓦會很高興的，我敢說一定會。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48091] = {title = "『背叛者』瓦卡斯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][48092] = {title = "青蛙的復仇", objective = "擊敗女祭司札爾卓希亞。", description = "這裡的納迦由一名叫做札爾卓希亞的女祭司領導。就是她想出如何從青蛙身上吸取魔力。\n\n除非吸乾每一隻青蛙的魔力，否則札爾卓希亞絕對不會停手。\n\n殺掉女祭司，辦到我無法完成的事，讓納迦知道奎格瓦可不是什麼弱小的羅亞。\n\n我會向奎格瓦祈禱你的成功。", progress = nil, completion = "札爾卓希亞死了，納迦很快就會敗逃。你完成我未能做到的工作，我為此向你致上謝意。\n\n願奎格瓦祝福你，希望他不久會接受我對他的虔誠之心。", rewards = "您會收到：\n\n艾澤萊晶岩"}
