MultiLanguageQuestData['tw'][48399] = {title = "黑(鐵)潮來襲", objective = "殺死7名黑鐵矮人。", description = "紅色的眼睛…火一般的鬍子…黝黑的皮膚。只有黑鐵矮人有這些特徵，在今天以前，我還沒親眼見過黑鐵矮人。\n\n據我所知，他們是聯盟派來跑腿的。考慮到我方的效忠對象，我想現在正是進一步證明我們對部落忠誠的好機會。\n\n黑鐵矮人非死不可，一定要讓他們連這沙灘上的一吋地都佔不到。", progress = nil, completion = "我們的立場絕對不能有一絲動搖，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48400] = {title = "大型偷竊傳送術", objective = "殺死烏爾達‧魔焰，並將傳送信標放在席帕拉之眼附近。", description = "不能把席帕拉之眼交給他們，<name>。\n\n幸好，我不但是個考古學家，也是位傳送師。我的老師的女老師曾經受過首席傳送師歐庫雷斯親自指點。只要運用這些技術，我就可以把聖物拿回來。\n\n你只需要把這些傳送信標放在席帕拉之眼附近。接下來我就可以把它和你一起平平安安地送回營地。聯盟只會空手而歸。\n\n趁你人在那個地方時，順便把我的「感謝之情」傳達給那個從我們手中奪取席帕拉之眼的負責人身上。", progress = nil, completion = "啊…任由這種魔法擺布一定是種很絕望的事。做得好。", rewards = "聖匣探險者披氅拉斯塔瑞足靴贊庫爾裹足托卡利足靴詹巴尼足靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][48402] = {title = "劇毒之觸", objective = "使用吹箭弱化5名血獵人食人妖。", description = "你…我看到你與贊提莫談話。拜託，我沒多少時間了…\n\n這些食人妖是為我們的血液而來。在這傢伙毒發身亡前，我已經失血過多到快要死掉的地步了。\n\n去它的屍體找一下，吹箭以及飛鏢應該都還在。用飛鏢沾上我的血液，然後去解決這些食人妖，能殺多少算多少。\n\n我絕不會白白死去！既然這些食人妖這麼想要我們的血，那就給他們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48403] = {title = "無邊黑暗", objective = "擊敗『無邊黑暗』烏蓋涅斯。", description = "數千年來，我們一直把無邊黑暗鎮壓在此。這些結界屹立不搖…保護著高嶺。\n\n現在結界失效了，邪惡力量再度出現。\n\n糾纏著我們夢境的黑暗…狗頭人在驚恐的囈語中低聲提到的黑暗…成真了。\n\n上古諸神的使者烏蓋涅斯在為他的主人鋪路，要是我們不能齊心擊敗他，一切都會毀於一旦。\n\n勇士，你必須用盡全力。我們所有人都一樣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48404] = {title = "頑童", objective = "阻止5名街頭頑童偷竊。", description = "那邊的！你好手好腳，而且缺錢用嗎？我想聘雇你。\n\n這些沒規矩、邪惡、又沒爸媽教導的小孩又開始偷我的卷軸了。這些卷軸落到壞人手裡會很危險。\n\n更糟的是，我相信這些無家可歸的小孩是有組織的。\n\n去找這些街頭頑童，從他們身上搜出東西，我就付你錢。", progress = nil, completion = "付錢讓你做我年輕時能做的事，真讓我心痛，但我的腿確實不如以前快了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48405] = {title = "豪郝先生", objective = "找出並殺死豪郝先生。", description = "我向來是個不喜歡暴力的托爾托人，但我最不能忍受的就是看到無賴利用小孩為自己賺錢。\n\n這些街頭頑童似乎是奉某個領頭人之名行事。我知道他們叫他「豪郝先生」，雖然我懷疑這名字是否故意取得如此諷刺。\n\n我這邊有個能讓你和頑童一起行動的卷軸，看看他們會不會帶你找到豪郝先生。如果你找到他，殺了他吧，我會給你賞金的。", progress = nil, completion = "很好，街上又少了一名邪惡的食人妖。當然，你可以假定他們很快會再度組織起來，他們總是這樣。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][48419] = {title = "誘惑與魅惑", objective = "搜尋弗林‧晴風。", description = "你來事故現場找朋友嗎？\n\n如果他沒死，可能會去我們營地。\n\n如果他現在沒在營地烤乾屁股，那可能就…這附近有很多可憐的傢伙都被海妖的歌聲虜走了。\n\n你去潮地前應該先去營地看看。找我們老大，火爆阿珍。如果有新的倖存者出現，她一定知道。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48421] = {title = "赤色潮水", objective = "殺死8名哀號海妖。", description = "該死的蛇蠍女！\n\n她們的歌聲讓男人心智出遊，血液發燙。\n\n我的船擱淺了，貨物都丟了。\n\n只能戰鬥了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "劫海者脛甲領航員便鞋翼艇長靴掠劫者長靴基爾森的染血披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][48433] = {title = "團結一心，為了部落！", objective = "到駐奧格瑪大使館和紀‧火爪談談，聽聽這個故事的結局。", description = "原本只是互相認識的簡單聚餐，最後卻變成大家拿起武器、一起對抗想要吞噬這個世界的古老邪惡勢力。\n\n我就喜歡這樣！\n\n你所做的一切幫助我們鞏固奧格瑪和高嶺之間的同盟，這些牛頭人對部落來說會是很有價值的助力。\n\n大酋長一定會很高興。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n高嶺雷蹄鹿"}
MultiLanguageQuestData['tw'][48434] = {title = "黯角怎麼樣了？", objective = "回雷霆圖騰查看黯角的情況。", description = "我們已經恢復三個結界，雖然這座山還沒有完全安全無虞，但我們的努力應該足以救出被暗影困住的黯角。\n\n我們先回雷霆圖騰看看他怎麼樣了。希望黯角能多告訴我們一點，到底冥闇一族在圖謀什麼，他們侍奉的又是怎樣的邪惡勢力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48440] = {title = "深入黑暗", objective = "登上梵迪卡爾，前往阿古斯。", description = "我們今天的所做所為，都是為了艾澤拉斯。在燃燒軍團的邪惡遠征中，我們損失慘重。\n\n在你準備好之後，我們就會讓梵迪卡爾長驅直入，直攻燃燒軍團的核心。\n\n阿古斯等著我們。", progress = nil, completion = "我們必須盡快行動！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48441] = {title = "暗殞峰剩餘物資", objective = "使用偵察地圖，完成「暗殞峰補給品」任務。", description = "我的騎士有塔巴克，但我的族人還需要補給品。他們需要食物、工具和武器。\n\n數千年以來，我們不斷遷徒，一旦被燃燒軍團發現就只能更換營地。每次都來不及帶走財物，只能把物資留下。\n\n你很強，你的手下也是，但你們不瞭解阿古斯。這個星球就像燃燒軍團一樣，會毫不留情地毀滅你。如果你能幫我們帶來留在暗殞峰的物資，我就派人當你的嚮導，讓你們有機會活著穿越阿古斯荒原。", progress = nil, completion = "謝謝你幫我們拿回物資。我們會履行諾言，為你在阿古斯指路。", rewards = "您會學到：\n\n克庫恩裝備"}
MultiLanguageQuestData['tw'][48442] = {title = "納斯拉薩斯堡：準備工作", objective = "將6位勇士的物品等級升到900。", description = "被抓進納斯拉薩斯堡的克庫囚犯只有兩種下場：不是吞噬魔化能量，轉變為燃燒軍團忠誠的士兵，就是被改造軀體，變成可怕的厄祖獸。\n\n趁著燃燒軍團的注意力都放在聖光軍團上，我想把握機會，把族人救出來。我想拜託你幫忙。\n\n但在發動攻擊以前，必須先幫你的部隊準備好需要的裝備。", progress = nil, completion = "克庫很快就能攻進納斯拉薩斯。我的族人都快等不及了。", rewards = nil}
MultiLanguageQuestData['tw'][48443] = {title = "納斯拉薩斯堡：救援任務", objective = "使用偵察地圖，完成「脫離納斯拉薩斯」任務。", description = "你的部隊現在已經有足夠的裝備，有能力把我的族人從納斯拉薩斯救出來了。派你的勇士加入攻擊行動，我們一起阻止燃燒軍團，別讓它們繼續在這個地區橫行霸道。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n克庫恩任務"}
MultiLanguageQuestData['tw'][48445] = {title = "歐羅納爾遺跡", objective = "使用偵察地圖，完成「瀕臨瘋狂」任務。", description = "還有許多克庫在地底的城市逗留，他們躲在陰暗中不肯離開。我不會放棄他們。\n\n阿卡漢原本是領導者，有些追隨他的人還留在歐羅納爾遺跡，在現實和毀滅的邊際擺盪。快去請你的職業組織來幫忙搜索歐羅納爾遺跡，或許還有能救的人。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n埃雷達斯裝備"}
MultiLanguageQuestData['tw'][48446] = {title = "古老埃雷達爾遺物", objective = "將6位勇士的物品等級升到925。", description = "是我害了阿卡漢。我不會再失敗了。\n\n要是想拯救克庫，就必須把以太族從埃雷達斯趕出去。雖然路拉已經被消滅了，但虛無仍然在影衛哨站盤旋不去。\n\n在我們開始行動前，你應該先確保手下能抵擋暗影。派你的勇士去附近的遺址，尋找古老埃雷達爾遺留下來的武裝吧。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][48447] = {title = "擊退影衛", objective = "使用偵察地圖，完成「擊退影衛」任務。", description = "我又需要向你的職業組織尋求幫助了。我想永遠剷除影衛的威脅。當你對抗燃燒軍團時，我們會對抗虛無。只要你派出部隊，我們就可以展開行動。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n埃雷達斯任務"}
MultiLanguageQuestData['tw'][48448] = {title = "阻止燃燒軍團的戰爭機器", objective = "使用偵察地圖，完成「荒原行動」任務。", description = "<class>t，我需要你幫忙。為了削弱燃燒軍團在安托洛斯荒原以外的戰力，聖光軍團打算攻擊靈魂魔爐、航運站和塑造者高臺。可是我們沒有足夠的兵力同時兼顧達成任務和保衛基地的責任。\n\n你可以代表我們聯絡<class>嗎？如果他們願意幫忙，這件事或許就有機會成功，我們或許就能癱瘓燃燒軍團的戰爭機器。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n光鑄裝備"}
MultiLanguageQuestData['tw'][48452] = {title = "鮮血市集", objective = "收集3個黑暗神像並摧毀呼召之杯。", description = "你和塔蘭姬公主一起來的嗎？\n\n我需要找人執行一項討人厭的任務。赤紅教徒弄得像是在開鮮血魔法市集一樣，這太糟糕了，老兄，非常糟糕。\n\n我要你往下到那片平原去，帶回證明他們使用鮮血魔法的證據。另外，摧毀他們的酒杯，大酒杯，千萬別忘了那個酒杯。", progress = "在祖達薩，禁止這些魔法不是沒原因的。他們說如果你屈服於這種魔法，會聽到幻聽。至於獻祭，那是低等部族實踐的惡習。", completion = "鮮血魔法是種感染，要是不杜絕的話，就會像疾病一樣擴散。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48453] = {title = "反擊", objective = "在灰石林殺死8個埃雷達爾祭儀師和薩菈扎德女士。", description = "如你所見，灰石林的祭儀師會綁架我們的同胞，在他們身上進行各種可怕儀式。他們的怨靈轉變為扭曲的生物四處遊蕩。絕對不能原諒這些祭儀師的惡行。殺死這些祭儀師，越多越好，尤其別漏掉那個帶頭的黑暗惡魔。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48454] = {title = "邪惡的證據", objective = "與『神王之刃』卓蘭妮交談。", description = "賈克拉傑拒絕巡邏這個區域，亞茲瑪的間諜沒有警告我們，告訴我們城市底下有什麼暗中運作的陰謀，祖爾也未能預知鮮血魔法就在我們眼皮子底下日漸壯大。\n\n這些都是非常嚴重的指控，而證據就在你手裡。將證據交給『神王之刃』卓蘭妮。她會明白其中的含意，也能以最好的方式向國王稟報。", progress = nil, completion = "有人在光天化日之下施展血魔法？令人無法容忍。\n\n謝謝你送來這個情報，做得很好。當神王拉斯塔哈的議會成員不在，我會直接向他稟報。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][48455] = {title = "解決暮鬃", objective = "在灰石林殺死10隻獵能豹。", description = "在這座森林裡，還是有各種塔巴克和獵能豹到處出沒。不過，這兩者的數量平衡已經受到干擾，現在獵能豹已經快把塔巴克趕盡殺絕了。為了確保牠們的存活，我們必須削減獵能豹的數量。\n\n快了結牠們的痛苦。迅速下手，讓牠們痛快解脫。", progress = nil, completion = "要維持森林的平衡，才能讓它永保常青。", rewards = "您會收到：\n\n暮鬃背甲"}
MultiLanguageQuestData['tw'][48456] = {title = "巫醫迦菈", objective = "找到巫醫迦菈。", description = "$p，我聽說我有一個老朋友在這裡，而且需要有力的幫手。\n\n巫醫迦菈。她是個老太婆，但羅亞覺得她很有趣，所以讓她待在這。\n\n幫我找到她，並盡你所能幫助她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48460] = {title = "馴獸師", objective = "前往灰石林與騎兵長吉瑞克談話。", description = "強大的邪惡猛獸在阿古斯肆虐，其中最可怕的幾個就在我們的森林裡。我的馴獸師正在森林的邊緣等候增援。他等的援軍就是你。\n\n去找騎兵長吉瑞克，他會提供更多消息。", progress = nil, completion = "我害怕這座森林終將失落。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48461] = {title = "攻其不備", objective = "進入一個侵略點，擊敗一個燃燒軍團指揮官。", description = "燃燒軍團狂熱的遠征，讓它們的防線變得單薄。當它們集中兵力防禦阿古斯時，我們可以轉而前往其他世界，擊敗它們的部隊。\n\n前往阿古斯的侵略點，讓燃燒軍團明白它們也同樣逃不過死亡。", progress = nil, completion = "我們要拿下燃燒軍團控制的世界，只是手到擒來的事…", rewards = "您會收到：\n\n朦朧的阿古岩"}
