MultiLanguageQuestData['tw'][48634] = {title = "繼續資助克庫恩", objective = "收集900大廳資源。", description = "我們在這個荒涼的地方活得很辛苦，這裡物資缺乏，族人時時刻刻都得尋找物資，才能勉強存活。如果能有更多物資，我就可以派遣另一個山脊行者協助你。\n\n外界者，你覺得這個提議如何？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n克庫山脊行者"}
MultiLanguageQuestData['tw'][48635] = {title = "進一步的虛無療法", objective = "收集100枚濃縮虛無碎片。", description = "所有受到暗影影響的生物在死後都會留下虛無的痕跡。如果你在城市中收集到虛無的話，可以來找我。我會加以蒸餾，產生更純粹的虛無。\n\n這樣就可以救更多族人了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n淨化虛無的克庫"}
MultiLanguageQuestData['tw'][48636] = {title = "為安托洛斯戰役提供物資", objective = "完成10個侵略點任務。", description = "燃燒的遠征需要大量物資，這些物資來自於它們佔領的世界。穿過燃燒軍團傳送門，消滅惡魔，然後截斷物資輸送。別讓它們的戰爭機器繼續運作。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n光鑄奮擊者"}
