MultiLanguageQuestData['tw'][48879] = {title = "獵食獵鷹蛋", objective = "收集12個獵鷹蛋。", description = "在阿蘭娜派我們去狩獵以前，有件更緊急的事要先處理…\n\n我餓壞了！沒有人能空著肚子去打獵！\n\n這一帶有獵鷹出沒，這附近一定有獵鷹蛋。我不確定做成荷包蛋好不好吃，但我向來喜歡冒險！\n\n親愛的<class>，我們去打獵前，你可不可以先帶幾個蛋回來？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48880] = {title = "討人厭的河鷗", objective = "殺死10隻泥鰍小屋附近的衛地河鷗。", description = "一定…要抓…需要更多…\n\n那些河鷗…亂咬…亂抓…亂搶…\n\n必須把牠們解決掉…可是…我要…抓…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48881] = {title = "收線這回事", objective = "收回5根噬鉗海岸上的釣竿。", description = "<這些釣竿一定是亞特離開海灘時留下來的。釣竿上大多都鉤著釣餌。\n\n或許你該把線收一下，看看上頭鉤的是什麼？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n釣手亞特的泥鰍餌"}
MultiLanguageQuestData['tw'][48882] = {title = "我愛魚內臟，這是真心話", objective = "在泥鰍小屋附近從完整的泥鰍身上收集9份泥鰍內臟。", description = "<看來河鷗從亞特那裡偷走的魚，有些還是完整的。\n\n他要是得到這些魚的內臟，應該會很開心。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48883] = {title = "難纏的大河鷗", objective = "殺死泥鰍小屋的鹽喙。", description = "還有一隻…搶了我的餌…我的魚…\n\n我的手指…\n\n殺了牠…我就…給你獎勵…您會收到：\n\n", progress = nil, completion = nil, rewards = "釣技便鞋釣技足靴釣技涉水長靴釣技踏靴您會收到：\n\n釣技袋裝魚"}
MultiLanguageQuestData['tw'][48887] = {title = "淨化心靈", objective = "在雷霆聖壇冥想，並與你的心魔戰鬥。", description = "若你想邀請亞昆達進入你的心靈，就不能讓恐懼或是悔恨而停滯。\n\n在雷霆聖壇冥想，並與潛伏在你心靈幽微之處的惡魔戰鬥。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][48888] = {title = "此泉為永恆", objective = "在永恆之泉附近殺死紅岩食腐土狼。", description = "水是沙丘裡的神聖資源，但在神殿裡的人永遠不怕口渴。\n\n亞昆達主宰風暴，讓附近的水泉永不乾涸。\n\n不幸的是，我們的永恆水源也吸引了各種不同的動物，前來感染我們的神殿。\n\n在你回來之前，消滅他們在山谷中的蹤跡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48889] = {title = "修補過去", objective = "在梅雅妮修復亞昆達心靈時保護她。", description = "這解釋了為何羅亞一直沒有動作。亞昆達忘了自己是誰！\n\n一定有某人或某物在濫用他的力量。\n\n我們不知道要怎麼在不與羅亞溝通的情況下協助他。\n\n我能進行一項有機會修復亞昆達心靈的儀式，但並不是沒有風險。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48890] = {title = "如何當個鮮血食人妖", objective = "試煉5名尚未經歷考驗的苦工。", description = "如果你不想讓任何人起疑，你必須徹底融入，做些下流的事情。\n\n營地周圍有些被綁起來的苦工，他們是儀式的一部份，透過鞭打的試煉讓他們更強大。\n\n沒通過儀式的人成為祭品，成功的人獲准加入對抗贊達拉的行列。\n\n如果你要融入他們，就必須執行儀式，給予那些苦工「試煉」。很詭異，但他們就是如此行事。", progress = nil, completion = "幹得好，沒有人對你起疑，沒有人在壓力下崩潰吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48894] = {title = "真理試煉", objective = "向崇高的亞昆達說出你的名字。", description = "我們神殿中的人已經拋棄了他們的過往，他們全心侍奉亞昆達。\n\n最後一項測試或許是最重要的一項。\n\n這才是關鍵時刻。\n\n你必須說出你的名字，是你從今天開始要使用的新名字。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48895] = {title = "完美的祭品", objective = "到亞昆達神殿對崇高的亞昆達獻上祭品。", description = "我只剩下這份祭品，但你的朋友身陷危險，我不能為了自己而獨占它。\n\n她救了我的命，現在換我救她了。\n\n把這祭品拿去，別讓我說第二次。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48896] = {title = "過往的知識", objective = "和米若的商隊一起上路，尋找喬瓦芭。", description = "我有一位老朋友，她自願前來沙漠以追求過往的知識。\n\n如果有人可以找到這把武器，那一定非喬瓦芭莫屬。\n\n我上次聽說她正計畫去挖掘大金字塔周圍的遺跡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48897] = {title = "達成協議", objective = "和神王拉斯塔哈談話。", description = "既然你已經決定自己身在祖達薩時會支持的守護神羅亞，你應該讓神王知道你的選擇。\n\n對於你選擇追隨強悍的剛克，他會感到欣慰的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][48898] = {title = "幸運護符", objective = "前往跳岩瀑布取得幸運尾的尾巴。", description = "雖然爸爸絕對不會承認，但是他真的很迷信。他在馬背上如果沒握著幸運護符就絕對不可能安心！\n\n聽說附近有隻狐狸，吃了很多雞，卻一直都沒被抓到。我想這隻狐狸應該很幸運吧！如果你能把這隻狐狸的尾巴送給爸爸，他應該也會覺得很幸運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48899] = {title = "安全第一", objective = "在跳岩瀑布收集8個耐用的貝殼。", description = "我嚮往騎士和馬之間的心靈連結，但除非親身體驗，否則我是不可能真正了解的。\n\n可是，嗯，你也知道的…護甲！如果沒有適當的防護措施，我怎麼敢騎上這種美妙的生物呢？\n\n我剛剛在附近看到瀑布。瀑布的岸邊一定有貝殼！為了安全起見，你願意幫年老的托爾托收集貝殼嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48902] = {title = "爆發般的能量", objective = "從跳岩瀑布的毒鱗滑鰻身上，收集6份脈動萃取物。", description = "你聽過鰻魚汁嗎？我不知道<race>喝下去是否安全，但是托爾托超愛鰻魚汁！鰻魚汁可以提供爆發般的能量，只要喝下鰻魚汁，就算是最年長的托爾托也可以健步如飛。\n\n我在旅途中看過鰻魚，就在莊園北邊。你能不能幫爸爸收集鰻魚身上的毒液？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48903] = {title = "最適合的馬", objective = "幫馬喬選馬，然後幫馬喬騎上馬。", description = "你幫我準備了這麼多東西…現在我該上馬了，對吧？\n\n嘿！我已經有三百年沒這麼緊張了！你可以幫我找適合的馬嗎？我沒辦法決定！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "堅實貝殼屏障幸運尾騎士披風托爾托旅行燈您會收到：\n\n"}
MultiLanguageQuestData['tw'][48904] = {title = "取得魚餌", objective = "在噬鉗海岸從噬鉗蟹身上收集15塊噬鉗蟹肉。", description = "魚餌…都快沒了…一定要抓…\n\n螃蟹…找到牠們…多抓一點…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][48909] = {title = "高貴職責", objective = "追殺危險的獵物。", description = "從屍體的狀態看起來，我推測摧毀營地的是擁有驚人利爪或尖牙的野獸。你說這條小徑可以往西走？阿蘭娜的獵人通常會結伴常駐在這個營地。也許有人已經去追這頭野獸了。\n\n快！我不想一整天都無所事事。我們也去追這危險的獵物吧！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "劫海者腰帶領航員之索翼艇腰鍊掠劫者繫腰您能選擇下列奬勵中的一個：\n\n坎寧斯領主的璽戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][48910] = {title = "資助克庫恩", objective = "收集150大廳資源。", description = "我們在這個荒涼的地方活得很辛苦，這裡物資缺乏，族人時時刻刻都得尋找物資，才能勉強存活。如果能有更多物資，我就可以派遣另一個山脊行者協助你。\n\n外界者，你覺得這個提議如何？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n克庫山脊行者"}
MultiLanguageQuestData['tw'][48911] = {title = "虛無療法", objective = "收集100枚濃縮虛無碎片。", description = "所有受到暗影影響的生物在死後都會留下虛無的痕跡。如果你在城市旅行中收集到虛無，可以來找我。我會淨化虛無，製造出更純粹的型態。\n\n這樣就可以救更多族人了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n淨化虛無的克庫"}
MultiLanguageQuestData['tw'][48912] = {title = "為安托洛斯戰役提供補給品", objective = "完成10個侵略點任務。", description = "燃燒的遠征需要大量物資，這些物資來自於它們佔領的世界。穿過燃燒軍團傳送門，消滅惡魔，然後截斷物資輸送。別讓它們的戰爭機器繼續運作。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n光鑄奮擊者"}
MultiLanguageQuestData['tw'][48913] = {title = "蒙那萊礦床－階級1解鎖", objective = "在阿古斯找到能教你怎麼處理暗星之芒的人。", description = "沒想到這個星球竟然存在如此純淨的生命。你小心翼翼採下花朵，有一股微小的力量湧現，然後消失。\n\n花在你手中粉碎了。在這個連聖光都不願眷顧的星球，不知道還有沒有人知道如何處理這種珍稀植物。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：蒙那萊礦床(等級1)"}
