MultiLanguageQuestData['tw'][49218] = {title = "船難者", objective = "在漂流角找火爆阿珍談談。", description = "看來海妖又出手了，她們沒把你生吞活剝算你走運。\n\n如果你想買補給品或是在火邊取暖，我身後的山丘上有營地。\n\n那邊每個人都跟你一樣，被海浪沖上來的。我猜總共有四、五艘船難的生還者，大家團結互助，想辦法活下來。\n\n去找火爆阿珍談談吧。別被她的外號嚇到了，其實火爆阿珍人很好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49223] = {title = "放長線釣大魚", objective = "殺死克倫頓。", description = "我的年輕朋友，又見面了！我有好消息。\n\n我們都很熟的那個克倫頓…就是那個在自由港騙我們的那個克倫頓…終於離開藏身處了。\n\n我透過好幾個中間人一直跟他通信，甚至透過代理做了幾次交易贏取信任。我們最近一次通信，他終於同意親自現身交易。\n\n他以為要見的是皮克西‧紡火小姐…熱愛盜獵毛皮的地精美髮師。\n\n但他真正要見的人，其實是你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49224] = {title = "虛空之光熔爐", objective = "使用虛空之光熔爐，將虛空之光強化效果注入一個聖物中。", description = "熔爐因為充滿能量而嗡嗡作響。再過不久我們的武器就會比星辰還燦爛！\n\n一定要擁有這種力量，才有可能在這裡擊敗燃燒軍團。\n\n<name>，這段時間以來，你承受了莫大的挫折和磨難，熔爐就交給你啟動吧，這是屬於你的榮耀。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49225] = {title = "追隨隊長", objective = "找到希爾德‧破火者。", description = "當地的居民和協會攜手合作，要在山丘上的洞穴裡尋回聖物。但我們似乎激怒了以前住在這裡的居民。海軍目前能確保探險隊的安全，但我不知道他們能撐多久。\n\n在事情更糟以前，我們需要你的幫忙！去找希爾德‧破火者，我們這位探險隊隊長跑回洞裡去拿東西了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49226] = {title = "姊姊，別唱了", objective = "殺死帕希歐珮和諾培。", description = "潮路上的海妖已經毀了無數的船，剷除她們對所有水手來說都是一大福音。\n\n但你不可能把她們全殺了，只有傻瓜才會想這麼做。\n\n真正危險的是那些長老，被稱為「姊姊」的那些海妖，她們比年輕的海妖更高大、聰明也更強壯。她們的聲音能在海上傳得老遠，造成所謂的「大豐收」。\n\n我已經追蹤其中兩個到潮路北端的洞穴，但沒辦法獨自除掉她們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49227] = {title = "萬用鑰匙", objective = "取得莫里森的萬用鑰匙，然後用它來釋放8位狐狸人俘虜。", description = "我們在這邊找到的鑰匙都不符！我們需要另一個計畫…\n\n我聽說那個監督者莫里森有一把萬用鑰匙，可以打開營地裡的每一把鎖。那很危險，但我要你幫我拿到那把鑰匙！\n\n莫里森負責管理礦坑營運，你可以在洞穴裡找到她。拿到鑰匙之後，務必救出眼前任何狐狸人俘虜。\n\n在你救出我的朋友後，回來這裡放我出來。祝你好運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49229] = {title = "遺跡的反撲", objective = "殺死6名古老的防衛者。", description = "有東西觸發了洞穴裡的陷阱，現在遺跡活過來了。我們被困在洞穴裡的那些人一定不擅長戰鬥。\n\n你可以幫忙解決遺跡裡的怪物，好讓我的人有機會逃生嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49230] = {title = "當地美食", objective = "收集5條多汁的潛伏者尾巴。", description = "我要餓死了。\n\n不是像我剛上岸那樣真的要餓死了，但你懂的…情感上要餓死了。\n\n最近都抓不到牡蠣，海草湯又讓我腸胃不舒服，如果我繼續喝海草湯，其他船難者可能真的會把我丟下海餵鯊魚。\n\n那些浪潮潛伏者怎麼樣？看起來很美味，我敢打賭，清蒸一定很好吃。\n\n你可以幫我抓一些嗎？我不擅長狩獵，但一定會分你吃的！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n水手派"}
MultiLanguageQuestData['tw'][49232] = {title = "收拾殘局", objective = "收集6個佐司特聖物。", description = "我跟伯奇在幫探險隊做實地考察。我不擅長戰鬥，但我不能再犯錯了，要不然他們可能會把我降級！\n\n你可以幫我取回洞穴內箱子裡的聖物嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49233] = {title = "我是德魯伊，不是牧師", objective = "淨化5名被詛咒的入侵者。", description = "入侵者的古老遺骸因為我們觸發主陷阱復活了。\n\n那個曲熔一直跟我求救，我雖然不是轉化不死族的專家，但似乎找到了解決的方法。\n\n我把法杖改良了一下，應該可以移除詛咒。拿去吧，看能不能幫上忙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49234] = {title = "離水的海軍", objective = "殺掉甦醒的守護者。", description = "我們撤離洞穴時，有個超大的石頭生物殺了很多海軍。那傢伙沒有繼續追我們，但它實在太危險，不能無視。\n\n我們必須把它處理掉！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "劫海者腿甲領航員毛褲翼艇束褲掠劫者窄褲掠劫者之握劫海者粉碎手套領航員手套翼艇之襲您會收到：\n\n"}
MultiLanguageQuestData['tw'][49239] = {title = "穿戴得宜", objective = "戴上鐵潮帽子，跟弗林一起進入自由港。", description = "本來自由港大家都可以任意進出，但現在鐵潮劫掠者把自由港占為己有，封鎖了整個區域，拒絕外人進入。\n\n幸好他們正在招募新人。\n\n把這戴上，別去想它是哪裡來的。\n\n我們要假扮成鐵潮新人，混進去收集情報，再趕回波拉勒斯吃晚餐！塞勒斯雖然脾氣很差，但廚藝還不賴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49242] = {title = "刺或者被刺", objective = "殺死6隻霍桑農地的衛地針刺鼠。", description = "噢，你好。抱歉，我們這邊很少有內陸人會來。\n\n這塊耕地原本是我丈夫山姆的農田，他以前每天都會照顧這片洋蔥田，後來詛咒降臨谷溪村，也把他給帶走了。\n\n我丈夫走了之後，這塊農地就是我僅有的寶貝了，那些針刺鼠連這個也要跟我搶。\n\n雖然我很不想麻煩陌生人，但可以請你幫我解決針刺鼠的問題嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49259] = {title = "伸張正義", objective = "和露西爾‧威奎斯特一起離開吊人角。", description = "感謝你在眾人面前救了我，<class>。我欠你一個人情，這件事我一定會讓父親知道。\n\n這段期間我們應該去查查這個禍心女巫會到底是什麼，她們又在我們的土地上做些什麼。希望元帥能給我們一點訊息。\n\n有件事要先解決。你能解開這些繩索嗎？我的皮膚都磨破了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "瑞德的戰斧獵巫者之弩元帥的長戟銀木法杖剋巫巨劍妖禦法刃巫婆短匕咒化鐮刀埃弗雷的晨星戈爾歐希重錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][49260] = {title = "幫忙把風", objective = "保護考古學家破火者。", description = "我來這裡是想把聖物帶走，越多越好。溜進來很容易，但只要開始打包，就一定會被那些傢伙發現。\n\n你可以幫我把風，讓我把聖物放進背包裡嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49261] = {title = "易怒員工燉肉", objective = "從沙地蟹身上收集粗糙的蟹肉。", description = "你不是應該在礦坑裡嗎？聽好，如果你不想去，我不會告訴莫里森的。我自己也不想被卡在那些礦坑裡。\n\n不過，我們這裡需要一些協助。船員們都飢腸轆轆，這幾個禮拜，除了泥巴水和偶爾抓到的老鼠之外，沒吃過其他東西。\n\n我聽說一位水手可以烹煮出上好的螃蟹燉肉。你可不可以幫我們找些肉回來？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49262] = {title = "幫派剋星", objective = "面對8位可疑的水手。", description = "遠離家園的時候，你很難管理一艘船艦。如果水手上岸時間太久，他們就會有焦躁不安的傾向。\n\n我收到的報告指出水手在附近鬼鬼祟祟偷取補給品。如果那些船員自以為能在我的監管下偷取雇主的東西，那他們就等著被修理一頓吧！\n\n我需要有人去破壞這些見不得人的交易，並對船員傳達一個訊息。\n\n偷竊是無法容忍的！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49266] = {title = "萬世熔爐", objective = "見證光鑄儀式的過程。", description = "光鑄戰士一直都是對抗燃燒軍團的希望明燈。\n\n不過很少人知道，要成為聖光之怒的化身，需要付出多大的代價。\n\n聖光軍團的這幾位勇士，已經準備好要接受他們最終的試煉。\n\n是否有這個榮幸請你見證這場儀式？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49268] = {title = "鯊魚出沒", objective = "殺死6條入侵的懼喉。", description = "最近有一大群鯊魚游到港口附近的淺水。我以前遇過生物攜帶外來污染源到岸邊，引發輕微的疾病。\n\n或許鯊魚從深海帶來了某種東西？殺掉幾條遊蕩到碼頭附近的鯊魚吧，我來聽聽看潮汐的聲音有沒有變化。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49274] = {title = "摩格姆的調查", objective = "在席帕拉廢墟中檢查『挖掘者』摩格姆‧燼燧的勘測裝備。", description = "喂。反正你已經下海了，要不要做個交易？\n\n我就直說了，這裡有一個聖物叫席帕拉之息。我不清楚席帕拉是何方神聖，或聯盟為什麼想要席帕拉之息，但如果我們能拿到手的話，就有為數不少的金幣入袋。\n\n這表示裡面也有你的一份，如果你懂我在說些什麼。\n\n我已經開始用器材展開調查，但現在還沒結果。進入廢墟裡面，輕輕踢一下你看到的箱子，加快它們的運作。", progress = nil, completion = "如果你不想知道答案，就不要提問題，&lt;name&gt;。\n\n不過你的表現不錯，而且現在我找到我需要的東西，可以追查氣息的下落。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49276] = {title = "探索的快感", objective = "協助艾卡蒂雅‧鑿石找出一塊席帕拉化石。", description = "我叫艾卡蒂雅，艾卡蒂雅‧鑿石！\n\n我代表探險者協會在這個挖掘場的利益。只要有哪邊的泥土無人翻動，我們會很高興地衝過去挖掘。\n\n<艾卡蒂雅的笑容開始消失。>\n\n不過，這些黑鐵矮人往下鑽的速度又快又猛，讓我覺得很不安。看起來你是個強壯又能力出眾的聯盟成員，你覺得你能不能，呃…帶頭做個榜樣？\n\n去吧，我們需要你去找塊新出土的化石。", progress = nil, completion = "我們都很清楚，你不是那麼喜歡讓一堆泥巴卡在你的指甲裡面。\n\n不客氣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49278] = {title = "靈魂復甦", objective = "用漢札布的符咒讓佐巴爾的靈魂復甦。", description = "這裡是伯昂撒姆第的聖地，但現在只不過是個廢墟。就連靈魂也逃不過時間的洗禮而逐漸消逝，只留下他們那乾枯的空殼。\n\n我們得讓它們恢復原樣。\n\n來，我一直把狩獵而來的靈魂收集在這個符咒裡面。對乾枯的靈魂使用符咒，讓這個地方重現原本的樣貌。", progress = nil, completion = "靈魂又再次守護著佐巴爾遺跡！\n\n現在，來談談我們的約定…", rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][49282] = {title = "摩格姆的進一步調查", objective = "協助『挖掘者』摩格姆‧燼燧進行勘察。", description = "我已經看過那個小盒子收集到的數據，我想我知道接下來該去邊找。席帕拉之息差不多算是我的囊中之物了。\n\n你應該到廢墟中央跟我碰面，就在山邊那個巨大、古老，像在睨視一切的骷髏下面，繼續我的勘察工作。\n\n要解讀這些裝置上的數據並不容易，而且我想那邊不會只有我們。\n\n你能不能幫我守好背後？", progress = nil, completion = "那個沒品的下流小 - 偷！！\n\n我們得追上她，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49283] = {title = "誰在追尋追尋者？", objective = "在東南方的海岸邊，找到追尋者，然後和霸圖交談。", description = "我告訴你，贊達拉充滿各種古老的秘密。非常迷人。\n\n我們聽到關於某個地區的消息，就在這裡的東南方，船艦會在那裡迷失方向，有些甚至還消失了！\n\n拉庫和一群特別好奇的追尋者去探索那附近的海灣已經有一陣子了。船骸和神秘事件，有什麼不去的理由？\n\n我們現在應該得到他們的消息才對。我們托爾托人雖然動作不快，但我們很可靠。\n\n你可以去看看他們，確保他們的安全嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49284] = {title = "時機正好", objective = "使用調諧的尋覓卷軸追蹤並找到失蹤的探險者。", description = "你來的時機真是剛好，<class>。\n\n我們本來計畫要調查這個地方，那是兩天以前的事了，目前還沒有人回來。\n\n我不想莽莽撞撞，太快向城裡通報。但我不能就讓這裡空著，也不能拋棄小科巴。\n\n把這卷軸拿去，看看你能找到誰，或找到什麼。把你能找到的都帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49285] = {title = "小小的寶藏", objective = "找到科巴所有的寶藏。", description = "我的家人在田野裡做研究，所以我聽他們的話，在這裡耐心地等。\n\n那些怪物就突然過來搶走我的寶藏！還把我最要好的朋友帶走了，那是我的蛞蝓史皮吉！\n\n怪物把所有東西都搶走了，跑得遠遠的。可是我跑不快…\n\n可以請你幫我把東西都搶回來，也幫忙找回我的家人嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n史皮吉"}
MultiLanguageQuestData['tw'][49286] = {title = "牢籠中的智者", objective = "從斯利蘇身上拿取鑰匙。", description = "噢，你好，朋友。\n\n看來數量比我們預期的還多。\n\n我們不斷地搜尋、發現、研究…然後我們就被抓了。這裡有納迦，是我們沒料到的事。\n\n在這座洞窟裡有個齷齪的傢伙，如果你能從他身上弄到鑰匙，就可以幫我們一個大忙。\n\n別擔心，我們哪裡都不會去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49287] = {title = "失落的托爾托", objective = "拯救被納瑟席抓走的托爾托人。", description = "海潮祭司納瑟須在上面的一座池子裡對他們找到的某塊石頭施法引導。她已經嘗試了好幾天，他們越來越絕望。\n\n我團隊裡剩下的成員都被抓去關在籠子裡。他們想要從我們身上套取我們根本就不知道的秘密。\n\n當他們意識到我們托爾托人不受威脅時，我覺得納迦會做出非常兇蠻的事。\n\n想辦法救出追尋者。我們一起阻撓納迦的計畫吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49288] = {title = "卷軸獵人", objective = "收集5個追尋者卷軸。", description = "當他們俘虜我們時，拿走我們手邊的一切東西-包括我們神奇的卷軸！\n\n這些納迦女巫正在聚集風暴。他們不想讓人知道他們在這做什麼，並為他們的女王尋求力量。\n\n我們看穿了他們的瘋狂，他們是為某個目標而行動。\n\n把我們的作品從納瑟席風暴操控者手中拿回來，不然他們可能會將它們用於邪惡之事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49289] = {title = "特殊的石頭", objective = "擊敗海潮祭司納瑟須，並查明納迦前來此地的原因。", description = "海潮祭司納瑟須就在這座山丘上，<name>。\n\n這裡有某個東西，某個艾薩拉非常想要的東西。\n\n絕對不能讓納迦得逞。不過，如果你找到那種石頭的話，就把它帶回來給我們。\n\n把這個卷軸拿去，它能在戰鬥中幫助你。\n\n該把納瑟須和她的部隊就此趕回大海，別讓他們再回來了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "拉斯塔瑞腰鎧贊庫爾之索托卡利腰帶詹巴尼腰帶海潮祭司巨披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][49290] = {title = "完美年分", objective = "將百年波本威士忌送到自由港的克倫頓手中。", description = "年輕人，你好。我叫羅可，專門買賣特殊貨品和異國製品。\n\n<羅可從甲殼下掏出小酒桶。>\n\n這桶波本威士忌已經一百年了。我很確定，因為我是一百年前帶來的。\n\n自由港有人想用稀有的卷軸跟我換這桶酒，但我被擋在外面進不去。看來這裡也沒那麼「自由」。\n\n如果你有辦法進去，或許可以幫我完成交易？我欠你一份情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49292] = {title = "海藻奶昔", objective = "把淨化藥劑分送給釣點碼頭6名噁心作嘔的村民。", description = "既然我能正確製作藥劑，當務之急就是把藥拿去給所有病人。\n\n拜託你，拿著這個杯子，一定要讓所有病人都獲得藥劑。其他事情就交給我吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49293] = {title = "突襲侵略點", objective = "完成3個一般侵略點。", description = "我們絕對不能把任何一個世界拱手讓給燃燒軍團。在侵略點持續進攻，把燃燒軍團踏個粉碎。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n朦朧的阿古岩"}
MultiLanguageQuestData['tw'][49295] = {title = "清理一番", objective = "在板木灘殺死8隻的咒化邪獸。", description = "我們總算守住了這座山丘，但是那些邪惡的怪物已經包圍了我們。\n\n要是不把兩側的怪物處理掉，我們大概到不了鎮上。該你上場了，<class>。\n\n看看你能不能到伐木場上削減牠們的數量。這樣的話，我們在前進的時候，就只需要專心對付前方的阻礙了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49299] = {title = "有內奸", objective = "殺死監督者貝茲。", description = "小子，我不想粉飾太平，這裡已經一團亂了。\n\n領導者墮落了，把自己的靈魂出賣給某種黑暗力量，連工人的靈魂都一起賣了。\n\n我會反抗到底。\n\n監督者貝茲為了獲得更強大的力量，出賣衛隊。讓他看看自己有多愚蠢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "領航員裹足掠劫者輕鞋翼艇涉水長靴劫海者長靴領航員裹腰掠劫者之索翼艇裹腰劫海者繫腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][49300] = {title = "生物腐化", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49302] = {title = "最致命的獵物", objective = "和歐克雷同行前往海洋之門，然後殺死維克高斯。", description = "喂！別浪費時間了！\n\n看來迪普瓦登留了一手…這可精采了！\n\n這會是千古留名的大狩獵，我不會讓你錯過的。\n\n歐克雷會帶你飛到城牆外。準備好了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "鱗懼分割刃釣點連弩海洋祭司法刃碼頭搬運工鬥棍馴浪者三叉戟攻喉步兵劍獵鯊者戰刃釣手長杖魚販剖魚刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][49309] = {title = "雷霆隕落", objective = "殺死督軍卡奧。", description = "督軍卡奧在這艘戰艦上指揮魔古軍團。該結束這場侵略行動了。\n\n我應該可以抵擋前來援助卡奧的單兵，但我沒有辦法讓屏障維持太久。\n\n小心，卡奧是雷霆國王頂尖的將軍之一。他沒那麼容易打敗。", progress = "沒有卡奧的領導，魔古很快就會戰敗。", completion = "國王有危險！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49310] = {title = "預言者的手段", objective = "搭乘疤喙前往達薩亞洛。", description = "神王拉斯塔哈危在旦夕。祖爾比表面上看起來更加強大。\n\n我們的時間所剩無幾。你必須在祖爾展開行動之前警告神王。\n\n哈布圖和卓蘭妮可以帶你過去。現在快走！", progress = nil, completion = "我們遭到背叛了。", rewards = "拉斯塔瑞頭盔贊庫爾風帽托卡利罩盔詹巴尼兜帽詹巴尼肩墊拉斯塔瑞肩鎧贊庫爾披肩托卡利肩甲托卡利罩盔托卡利肩甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][49314] = {title = "追捕札佐克斯", objective = "到墓塚去找暗影獵手達朱爾。", description = "<name>，或許你可以幫我一個忙。\n\n塔蘭姬說，她的僕從卡卓恩和暗影獵手達朱爾，兩人跑去追捕一名叫札佐克斯的巫妖。\n\n他們跑去一個叫墓塚的地方。我有點擔心他們會應付不來。\n\n你可以去找他們，看看他們需不需要幫助嗎？我們不能再損失任何盟友了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
