MultiLanguageQuestData['tw'][49417] = {title = "粗脖幫騎士", objective = "捕捉鴻羽。", description = "勞夫說又有工作要給你。\n\n有個有錢的軟腳蝦願意出非常高的價錢買公獅鷲獸首領，目前惟一符合條件的是鴻羽。我必須趕回營地幫忙訓練一隻特別頑劣的母獅鷲獸，所以你必須一個人完成這個任務。\n\n找到鴻羽，然後朝鴻羽使用束縛射擊。接下來該怎麼做只能靠你自由發揮了。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "劫海者護足領航員步靴翼艇行者靴掠劫者行者靴您能選擇下列奬勵中的一個：\n\n獅鷲騎士戒指\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49418] = {title = "塔克老大", objective = "前往位於消逝冰河的粗脖幫營地，跟塔克老大碰面。", description = "你的表現優異，顯然是這裡最厲害的高手。塔克老大會見你的。他在北邊的消逝冰河巡查營地。去幫幫他吧。\n\n喔，對了，建議你別直視他的眼睛…或腳…或他附近任何地方。跟他說話時，乾脆把眼睛閉起來吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49419] = {title = "好冷", objective = "找到崖邊溫泉的熱源。", description = "拜偷幫幫偶！噢，四尼。偶還能稍微動動嘴存。\n\n幫偶找個能把偶救粗氣的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49421] = {title = "獵殺祖爾", objective = "前往佐卡洛與神王拉斯塔哈會面。", description = "祖爾把他的部隊都撤回先知神廟的要塞了。\n\n拉斯塔哈傳來消息，表示他正在佐卡洛整備一支軍隊，召集所有能拿起武器的忠貞之士。看來效忠舊王的人比祖爾預期的還多。\n\n那表示神王還有三位最古老的羅亞在身邊。\n\n快過去協助他們的軍隊。", progress = nil, completion = "要殺一個能預見未來的人，最好能謹慎再謹慎。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49422] = {title = "異教徒", objective = "到先知神廟獵殺異教徒。", description = "襲擊祖爾的狂熱信徒和魔古盟友，以獵捕者之怒追殺他們，將他們全部殲滅，讓他們為背叛付出代價。", progress = nil, completion = "等到天空沒有弩砲的威脅以後，帕骷就可以開始做她最喜歡的事：把惹毛她的傢伙從很高的地方重重摔下去。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49424] = {title = "完整的預言", objective = "尋找並閱讀3份祖爾的記述。", description = "那個蛇蠍般的預言者祖爾。我一直都不信任他。總覺得他從來就不打算告訴我們完整的預言內容。\n\n進入這個「預言者」的神廟，看看他是否記述了任何預知幻象。\n\n我們必須瞭解我們的獵物有什麼意圖，才能展開真正的獵殺。", progress = nil, completion = "祖爾已經墮落到那麼低下的程度，不惜復活達薩？祖爾還有那個臉自稱贊達拉嗎？", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49425] = {title = "黃金之城", objective = "在通往阿塔達薩的路上擊破祖爾的部隊。", description = "瑞贊和拉斯塔哈沒有等我們。他們已經上山朝黃金之城阿塔達薩而去了。\n\n你、我跟蘿蒂要立刻追上去，為他們提供空中支援。快跳上來。", progress = nil, completion = "祖爾想要阻攔我進入我的地盤？我會吞噬他的靈魂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49426] = {title = "國王的策略", objective = "加入瑞贊與拉斯塔哈的阿塔達薩圍攻戰。", description = "阿塔達薩是諸王之墓。信奉我的列位先王。我最強大的追隨者。\n\n我會在今天大啖祖爾的血肉。\n\n來，$p，跟上。我們的獵物不管是力量或數量都不足以封鎖這個入口。讓我們擊潰這些異教徒。", progress = nil, completion = "他…他走了…", rewards = "拉斯塔瑞胸甲托卡利鎖甲護胸詹巴尼上衣贊庫爾衣飾詹巴尼面具托卡利護盔贊庫爾頭冠拉斯塔瑞盔帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][49427] = {title = "這不是我們的紫精靈", objective = "在席帕拉東邊海岸殺死8個部落的人。", description = "你知道的，<name>，雖然這些精靈也是一身紫皮膚，但我不覺得他們會站在聯盟這邊。\n\n至少，他們表現出的強硬態度讓我這個黑鐵矮人很不舒服。\n\n雖然有一丁點惹火部落的可能性，不過你不介意去殺幾個吧？", progress = nil, completion = "我就猜他們不怎麼友善。好吧，至少我放心了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49428] = {title = "大型偷竊傳送術", objective = "殺死第三傳送師賽拉妮爾並取回席帕拉之息。", description = "我可沒打算來場公平競爭，<name>。\n\n但是從我們眼皮底下直接傳送跑掉，讓我覺得這手段太下流。\n\n去教訓那些精靈，讓他們知道從聯盟手裡偷東西有什麼下場。如果他們喜歡玩陰的，我們也不會輸。", progress = "你把席帕拉之息拿回來了嗎？", completion = "我可是信守承諾的矮人，&lt;name&gt;。\n\n這是你的份。我會親自監督這裡的…壺…隨著我對你的讚頌之詞抵達聯盟。\n\n不太容易…留下印象，不是嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49431] = {title = "溫暖又舒適", objective = "收集99份色氣精華。", description = "嘿！這地方很夢幻吧？我覺得好放鬆。當然如果那些雲霧混蛋不來煩我，我會更放鬆。\n\n你可以幫我修理那些雲霧混蛋嗎？噢，對了，把精華帶回來給我，那些精華可以讓澡盆變得溫暖舒適。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "劫海者扣環領航員繫腰翼艇環帶掠劫者裹腰葛里敦的緞質毛巾您會收到：\n\n"}
MultiLanguageQuestData['tw'][49432] = {title = "棄魂", objective = "在亡者之城幫珂烏菈找到媽媽。", description = "我的媽媽呢？你有沒有見到我媽媽？\n\n她說：「我馬上就回來。」我是個好女孩，我乖乖等。我等了又等，我已經不確定我在這邊等多久了。\n\n這邊好冷、好孤單。嘿…你能不能幫我找媽媽？我保證不會添麻煩。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49433] = {title = "雪怪群", objective = "殺死10隻雪怪。", description = "雖然還不知道他們被帶去哪裡，但已經知道是誰幹的。我們粗脖幫相信一命換一命，有時候甚至兩命。\n\n殺些雪怪吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49435] = {title = "他們去哪了？", objective = "尋找關於失蹤粗脖幫眾的線索。", description = "聽好了。\n\n我的手下失蹤了。你要幫我找人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49437] = {title = "破舊的便箋", objective = "在蛇蜿峽谷殺死夏斯卡。", description = "<紙條上面簡短的字是用鮮血寫成的。>\n\n在我被流放後馬上就被他們就抓到了我。我太虛弱當不成奴隸，偏偏又太瘦不足以當野獸的飼料。\n\n他們本想殺了我，但一個叫夏斯卡的人出手干預，他說覺得看著我在囚犯之間餓死應該會很有趣。\n\n我的人生沒有多光明正大，我沒有資格要求什麼。但如果有其他贊達拉同伴發現這張紙，我有一個請求…\n\n拿把刀刺進夏斯卡的肚子，然後扭轉刀柄直到那毒蛇死去！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49439] = {title = "老大的復仇", objective = "殺死轟撲。", description = "我不會說什麼血債血還的，但這裡面的傢伙殺了我的手下，無論是什麼東西，我都不會讓牠活下去。\n\n所有人戰鬥，不准放棄。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49440] = {title = "鮮血食人妖的外表", objective = "協助巫醫科加布完成他的儀式，讓你偽裝成鮮血食人妖。", description = "喬崇加是我們前去滲透鮮血食人妖的斥候之一，但我們再也沒有收到他的消息。\n\n我需要你幫忙找出喬崇加，看看他有沒有從鮮血食人妖那邊獲得什麼情報。\n\n如果你要進去找他，得先變成一名女性鮮血食人妖。她們享有最大限度的自由，可以四處走動。我有個儀式可以讓你變身。\n\n幫忙我準備儀式，好賦予你鮮血食人妖的外觀。", progress = nil, completion = "儀式完成，你準備好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49443] = {title = "獵巫課程", objective = "在露西爾‧威奎斯特研讀銀燼書卷時提供協助。", description = "雖然我非常肯定編撰這本典籍所投入的心力，但這東西讀起來簡直像是攻城武器的工程說明！\n\n我需要一些時間來爬梳這些資訊，才有辦法找出可能對我們有用的情報。如果你有時間的話，希望你能幫我個忙。\n\n首先，這裡可能需要一點燈光…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49444] = {title = "安德弗特", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][49445] = {title = "交易原始精華", objective = "你一定已經知道了，只要使用原始薩格拉斯精華這種寶貴的材料，就能為物品灌注強大的力量。我們需要盡可能提高力量，才有辦法對抗燃燒軍團。\n\n把你找到的薩格拉斯精華帶來給我，我會用我有的東西來跟你交換。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][49449] = {title = "製皮－階級1解鎖", objective = "在阿古斯找到能教你怎麼處理暗星之芒的人。", description = "沒想到這個星球竟然存在如此純淨的生命。你小心翼翼採下花朵，有一股微小的力量湧現，然後消失。\n\n花在你手中粉碎了。在這個連聖光都不願眷顧的星球，不知道還有沒有人知道如何處理這種珍稀植物。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][49450] = {title = "事故回報", objective = "在蕨木山脊殺死10隻被控制的野獸。", description = "難怪工人都不敢進森林。通常熊和蜘蛛都會盡量遠離人類…\n\n但這些不是普通的野獸！\n\n如果生產因此停頓，父親一定會火冒三丈。拜託你，殺掉這些野獸，讓山脊恢復安全！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49451] = {title = "休假請求", objective = "前往阿格森鋸木場解救5名被纏住的伐木工。", description = "我的父親什麼都不知道。他總是關在自己的辦公室，工作到深夜…\n\n你看看，我是他的獨子，但我跟他的員工一起在這裡被困住了。我們顯然出事了！但父親絕對不會相信的。\n\n如果他不肯調查攻擊，那我就自己來！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49452] = {title = "赤字", objective = "從死去的阿格森伐木工身上收集5把失而復得的斧頭。", description = "我的員工認為我們被攻擊了，他們說野獸和木頭人把工人殺了。\n\n但我說，我們損失了貴重物資！\n\n你知道有多少把公司配備的斧頭就這樣丟了嗎？每一把都是我辛苦賺錢買的！\n\n我要你去把那些裝備拿回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49453] = {title = "壩託，救救河狸", objective = "把6隻嚼木河狸趕回水中。", description = "伐木工正在摧毀森林，野生動物的處境岌岌可危！\n\n河狸需要這些木頭才能建築水壩，但現在他們只能四處收集木頭碎塊。\n\n這裡不安全了！拜託你幫我把河狸趕回安全的水中。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49454] = {title = "害蟲防治", objective = "摧毀12顆苔牙卵。", description = "森林裡的蜘蛛卵太多了，到處都是密密麻麻的。\n\n如果這是最近才發生的事…那這些卵肯定腐化了！我們不能繼續讓卵孵出這種凶惡的蜘蛛。\n\n你去森林時，順便把卵毀了吧。如果蜘蛛再多下去，我們就無法阻止牠們擴散了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49455] = {title = "製皮－階級2解鎖", objective = "在阿古斯找到能教你怎麼處理暗星之芒的人。", description = "沒想到這個星球竟然存在如此純淨的生命。你小心翼翼採下花朵，有一股微小的力量湧現，然後消失。\n\n花在你手中粉碎了。在這個連聖光都不願眷顧的星球，不知道還有沒有人知道如何處理這種珍稀植物。", progress = nil, completion = nil, rewards = nil}
