MultiLanguageQuestData['tw'][49464] = {title = "尖角蜥尾", objective = "從蘚顎尖角蜥身上取得5條尖角蜥尾。", description = "在庫爾提拉斯上流社會之間傳有一道菜，只有最用心的廚師才做得出來。貴族為了嚐到這道精心調味、悉心烹煮的佳餚，往往花上大把金子也在所不惜。\n\n沒錯，我說的就是尖角蜥尾！\n\n我一定得找出料理這稀世美味最好的方法！清燙？紅燒？水煮？或許蒸煮或汆燙比較適合！\n\n總之，我需要一些尾巴來試試看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49465] = {title = "資源最大化", objective = "在阿格森鋸木場收集5個木頭裝飾的顱骨。", description = "讓我告訴你，我的員工是什麼德性。\n\n他們總是把事情講得太誇張！我給他們薪水，給他們穩定的好工作，結果他們怎麼報答我？只會找一堆沒辦法上工的藉口！\n\n他們說那些樹活過來了。樹？走來走去打架的樹？如果要說謊，至少也說個可信度高一點的吧！\n\n如果他們想說服我，我就要看到真實的證據。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49467] = {title = "森林女巫", objective = "殺死蕨木山脊的森林女巫。", description = "女…女巫？！\n\n我，呃…我很想幫你，我真的想，但…我必須去跟爸爸報告。\n\n為什麼你不自己去阻止那個女巫？像你這麼勇敢的冒險者，解決女巫應該不成問題。\n\n我很確定父親一定會好好獎賞你的！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "佩圖拉墜盒您會收到：\n\n"}
MultiLanguageQuestData['tw'][49468] = {title = "網上情報", objective = "拯救5名被網住的伐木工。", description = "就算有工人一直待在森林中與野獸為伍，我也不覺得奇怪。有些工人真的非常認真工作，雖然父親不想承認。\n\n現在這些工人被蜘蛛抓住了！\n\n也許這些工人可以幫助我們瞭解這個地方。把他們從蛛網中救出來，看看他們知道什麼事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49472] = {title = "泰坦級的研究", objective = "帶50個覺醒精華給秘匠維里迪。", description = "就算伊利丹推了天命之手一把，但讓阿古斯這麼靠近艾澤拉斯，卻加快了夜井崩塌所引發的反應。\n\n我認為燃燒軍團在阿古斯的行動，會讓我們多年來在不知情的狀況下所汲取的力量更不穩定。\n\n這顯然還需要再深入研究。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n覺醒泰坦精華"}
MultiLanguageQuestData['tw'][49473] = {title = "泰坦級的研究", objective = "帶50個覺醒精華給秘匠維里迪。", description = "這個物質的反應程度一天比一天來得強。這樣下去就算打贏燃燒軍團，也可能失去對我們來說更加寶貴的東西。\n\n或許這是將來會出現巨大動盪的預兆？世界會面臨什麼樣的命運呢，<name>？\n\n我這輩子都在熔爐中尋找答案，也打算繼續這麼做。不過，你要的答案，可能藏在別的地方。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n覺醒泰坦精華"}
MultiLanguageQuestData['tw'][49474] = {title = "詛咒裂片", objective = "把詛咒裂片帶去破碎群島給達拉然的秘匠維里迪。", description = "<你看到一塊不斷變換色彩的奇異金屬裂片。你一碰到它，裂片的一端就開始膨脹，然後漸漸融化。液體滴落地上的時候，你聽到嘶嘶聲，接著就有一股惡臭撲鼻而來。\n\n達拉然的金屬工匠或許會知道這是什麼東西。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49477] = {title = "意外的援軍", objective = "找到查德維克‧帕克斯頓，被遺忘者偵察隊長。", description = "<你在地上找到一張破碎的部落公文…\n\n看樣子有一名叫做查德維克‧帕克斯頓的男子，率領著一群被遺忘者，被派到這裡來調查納茲米爾。\n\n你無法辨識出他們被派來的原因，但公文上有他們所要前往的坐標位置。\n\n或許你能在那個坐標位置找到這些偵察兵，招募他們一起對抗鮮血食人妖。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49479] = {title = "不管他們該不該這麼做", objective = "讓英格麗強化喚天者寶石。", description = "塞斯拉克似乎相信，在納茲米爾有某種東西能釋放這顆寶石內的毀滅能量。\n\n我們沒有那個東西，不過我們有其他選擇：某位願意用魔法做實驗的瘋狂術士。\n\n去與英格麗談話，看看她能不能解放這顆寶石真正的力量吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49488] = {title = "塔爾古魯", objective = "前往塔爾古魯與預言者祖爾會面。", description = "我的先知是忠實的僕人，但他總是喜歡堅持己見。\n\n我派他去塔爾古魯收拾自己造成的殘局。他的其中一個學徒，一位名叫沃爾詹巴的巫醫將古拉巴什據為己有，還將我的守衛趕了出來。\n\n到塔爾古魯和祖爾會面，並確保這件麻煩事能確實解決。不要讓他…分心。", progress = nil, completion = "啊，對，我的新護衛！\n\n你為執行神王的旨意而來，我可不想看到老拉斯塔哈對你感到失望，看到你在暴風城的表現之後更是如此。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49489] = {title = "需要加個身體", objective = "「改良」2份阿塔詹巴侍僧製作的藥劑。", description = "我來這理主要是想對付我那個任性的學生。至於他的追隨者，我就留給你了。\n\n我看到的未來讓人…很不安。河流被毒素染紅，街道到處都是死屍。而這些…「詹巴尼」聲稱他們是祖達薩的新任統治者。絕對不能讓這件事發生。\n\n你最幸運的一點，在於我知道該如何避免這樣的命運。我想你會發現他們的大鍋還少了一個關鍵的材料。\n\n<他盯著你看。>\n\n或許，加個人的身體進去？", progress = nil, completion = "他們都說要以毒攻毒。在這種情況下，就用毒藥去攻扯他們前輩後腿的白癡吧。", rewards = "拉斯塔瑞腿甲贊庫爾裹腿托卡利腿甲詹巴尼馬褲您能選擇下列奬勵中的一個：\n\n靈魂扭曲者之戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49490] = {title = "眾聲之甕", objective = "在塔爾古魯從敵人身上收集30盎司的靈魂。", description = "沃爾詹巴確實能看見預知幻象，就連現在，他也在對我們採取預防措施。\n\n遺憾的是，他的預知幻象並不完整。你要同時幫我準備取他性命，還要解決掉他的追隨者。你要使用的工具叫做眾聲之甕。\n\n帶著它，冒險進入塔爾古魯。把他的追隨者殺了，並摧毀他們的魔像和面具。他們的靈魂一旦釋放，就會進入甕中。\n\n噢，帶著這個甕的時候可別丟了性命，這個眾聲之甕可是來者不拒。", progress = nil, completion = "一切都照計畫進行。別擔心他們，這就是他們的命運。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49491] = {title = "巫毒的養料", objective = "收集8個巫毒圖騰。", description = "沒時間了！他們在吸取我們的靈魂…利用我們…黑暗巫毒…\n\n<羅亞女祭司伊茲塔的靈魂變得模糊，她的聲音既輕柔又遙遠。>\n\n那些圖騰…燒了它們…\n\n我們就自由了…！", progress = "<火盆熊熊燃燒。>", completion = "&lt;正當火焰吞噬圖騰時，古拉巴什之魂從灰燼中竄出。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49492] = {title = "沃爾詹巴的傲慢", objective = "摧毀沃爾詹巴的面具。", description = "沃爾詹巴以為自己的預言能力已經超越了我。我多年前就警告過，這種傲慢不可取，但他顯然沒有聽進去。\n\n<祖爾咯咯笑著。>\n\n想也知道，他一定會想辦法阻止我們踏進他的聖所。你要聽他的話也可以，不過別忘了，他只是想盡辦法要自保。他的理智已經被恐懼摧毀。\n\n摧毀他的面具，我們就能毫髮無傷地走過這條通道。", progress = nil, completion = "我說過了，他的理智已經被恐懼摧毀。", rewards = "詹巴尼偏折盾詹巴尼妖術法器沃爾詹巴塑像您會收到：\n\n"}
MultiLanguageQuestData['tw'][49493] = {title = "祖爾的道德困境", objective = "釋放9個心奴。", description = "嗯。\n\n古拉巴什以背叛與軟弱聞名，他們在祖爾格拉布的所作所為將成為難以磨滅的歷史污點。\n\n從另一方面來說…\n\n那些贊達拉人高高在上，使役奴隸。我們既強壯又有能耐。這座偉大城市裡出現心奴無異令人蒙羞。\n\n我知道有種吟誦，可以解放他們的心智。在心奴附近使用，就可以解放他們。\n\n要不然你也可以直接殺了他們，對我來說沒有任何差別。", progress = nil, completion = "軟弱或自大…我常常在想贊達拉人到底是哪一種。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49494] = {title = "祖凡比佳釀", objective = "殺死祖凡比釀酒師瑟卡。", description = "祖凡比佳釀是不是巫醫最狠毒的藥劑還有待商榷。\n\n大鍋的主人可以用心靈力量驅動祖凡比佳釀，只要吸入它的迷煙就會喪失心志，成為聽命行事又容易操控的對象。\n\n這是種低劣的魔法，只有精通此道的巫醫才知道製作它的古老咒語與配方。如果要根除這種佳釀的效果，就必須殺掉釀造它的巫醫。\n\n找出在此潛伏的祖凡比釀酒師，一定要讓這種知識就此失傳。", progress = nil, completion = "很好，總算從源頭遏止了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49495] = {title = "實現命運", objective = "破壞沃爾詹巴的保命手段。", description = "沃爾詹巴忙著鞏固自己的力量。他的預知幻象已經展示出他會戰鬥，甚至可能會死，所以他為了保命而無所不用其極。\n\n我需要你當我的左右手，因為我一旦現身他就會出現。你要解除他為這天所做的一切準備。\n\n照我說的做，我們就能得到國王的賞識。", progress = nil, completion = "&lt;祖爾搓著雙手。&gt;\n\n很好，現在我們準備好把他拖出來了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49522] = {title = "克倫頓的報酬", objective = "打開滿是灰塵的陳舊木箱。", description = "做得好，朋友。真的，非常出色。\n\n看到放在房間角落，滿是灰塵的木箱了嗎？你可以在裡面找到我們協議好的內容：古老的卷軸，以及一大袋金幣。\n\n請，領取你的獎勵。這是你應得的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49523] = {title = "交易失敗", objective = "去信風市場跟羅可說話。", description = "<克倫頓逃走了！\n\n一開始安排這次交易的托爾托商人羅可…他需要知道發生了什麼事。\n\n你們上次談話中，羅可提到會去波拉勒斯。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49529] = {title = "大掃除", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49531] = {title = "行銷之美", objective = "在渡假村與各個景點和野生動物自拍。", description = "我們噴框家的人雖然不是哥布林，但是看到商機我們還是會及時把握的！渡假村工作人員正在受訓，這個地方也正在整頓，現在我們只需要打響名氣！\n\n<沃福德拿起一個很眼熟的盒子。>\n\n看啊！美妙的地精工程傑作，自拍相機！現在，要是有個大方的<race>願意捕捉這地方的光采就好了。\n\n記得，你要看起來很享受喔！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n過度設計的閃光燈\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49532] = {title = "大酋長的命令：影月谷！", objective = "到外域的影月谷與血衛士高莫克交談。", description = "所有身強體壯的部落成員都必須前往外域的影月谷，向血衛士高莫克報到。\n\n燃燒軍團想包圍影月村，不過我們的柯爾克隆精英部隊會讓它們瞧瞧膽敢跟部落作對會是什麼下場。\n\n擊潰燃燒軍團。\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49533] = {title = "大酋長的命令：凜風峽灣！", objective = "到凜風峽灣與藥劑師黎珊達交談。", description = "所有身強體壯的部落成員都必須前往凜風峽灣，向藥劑師黎珊達報到。\n\n被遺忘者在北裂境東岸建立了要塞。\n\n現在正是向天譴軍團進攻的時機，我們除了展現兵力，還有皇家藥劑師學會新研發的病毒。\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49534] = {title = "大酋長的命令：祖爾德拉克！", objective = "到祖爾德拉克與十字軍領主蘭迪加交談。", description = "所有身強體壯的部落成員都必須前往祖爾德拉克，向十字軍領主蘭迪加報到。\n\n天譴軍團正在祖爾德拉克殘殺當地的居民，並且把他們轉化成天譴軍麾下的不死怪物。\n\n協助銀白十字軍和黯刃騎士團平息這場威脅。\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49535] = {title = "大酋長的命令：休拉薩盆地！", objective = "到水晶之歌森林上方的達拉然與大法師潘塔魯斯交談。", description = "所有身強體壯的部落成員都必須前往水晶之歌森林上方的達拉然，向大法師潘塔魯斯報到。\n\n赫米特‧奈辛瓦里，還有他的遠征隊，先前已被派去探索休拉薩盆地，但是他們卻失蹤了。\n\n我們對林木蓊鬱的休拉薩了解不多，但是這座盆地藏有的秘密，或許能讓我們在對抗巫妖王時占到優勢。\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49536] = {title = "大酋長的命令：風暴群山！", objective = "對水晶之歌森林上方的達拉然與倫‧杜克坦交談。", description = "所有身強體壯的部落成員都必須前往水晶之歌森林上方的達拉然向倫‧杜克坦報到。\n\nK3的哥布林在風暴群山建了一座城市，還派出他們的大使四處招募冒險者。\n\n找倫‧杜克坦談談，看看K3的人有什麼需要。他們會是我們對付巫妖王的寶貴盟友。\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49537] = {title = "大酋長的命令：寒冰皇冠！", objective = "到水晶之歌森林上方的達拉然與空奪者克朗交談。", description = "所有身強體壯的部落成員都必須前往水晶之歌森林上方的達拉然，向空奪者克朗報到。\n\n戰歌進攻部隊需要更多冒險者，才能一鼓作氣對冰冠城塞發動猛攻，直取阿薩斯。\n\n時候到了，我們要讓巫妖王付出代價！\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49538] = {title = "大酋長的命令：翠玉林！", objective = "到葛羅瑪許堡向納茲格寧姆將軍報到。", description = "所有身強體壯的部落成員都必須前往奧格瑪，向納茲格寧姆將軍報到。\n\n我們對近對聯盟的海戰捷報連連，讓大家意志更為堅定。\n\n到葛羅瑪許堡報到，助部落的入侵艦隊一臂之力。\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49539] = {title = "大酋長的命令：四風峽！", objective = "到四風峽與老陳‧風暴烈酒交談。", description = "所有身強體壯的部落成員都必須前往四風峽向老陳‧風暴烈酒報到。\n\n風暴烈酒家的冒險精神，是值得部落借鑑的地方。\n\n和風暴烈酒家的人同行，探索潘達利亞的秘密。\n\n為了部落！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49540] = {title = "大酋長的命令：喀撒朗蠻荒！", objective = "到喀撒朗蠻荒與肯‧肯交談。", description = "所有身強體壯的部落成員都必須前往喀撒朗蠻荒，向祝家守望站報到。\n\n有傳聞指出，喀撒朗蠻荒的熊貓人出現了異常的行為。\n\n到祝家守望站與肯‧肯交談。或許他會知道是什麼原因讓這些熊貓人變得無精打采。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
