MultiLanguageQuestData['tw'][49801] = {title = "積極培育計畫", objective = "從侵略性的刃翼身上採收8枚膽囊。", description = "有攻擊性很好。我同意詹加拉的話，如果要讓這件事成功，班金就不能再如此被動了。\n\n以鍊金術來看，對這種野獸而言，牠們的攻擊性來自膽囊裡面的一種物質。這裡的刃翼侵略性很強，因此，牠們也有遠大於我們所需的攻擊性。\n\n只要從牠們身上收集一定數量的膽囊，我就能製作出一種藥，讓我們的好傢伙能立刻再次上陣。", progress = "你拿到我要的所有膽囊了嗎？科學從來就不保證安全…", completion = "這正是我需要的！也太臭了吧！\n\n有了這些膽囊，我可以做出足夠的兇暴配方，讓一頭大得像頭雷龍的生物用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49803] = {title = "更換守衛", objective = "向亞羅姆之地的瓊安‧科利爾東上尉、尤里克少尉、麥斯少尉、斯騰泰德中尉和馴鷹者諾特利發出召集令。", description = "你是非常厲害的<class>，內陸人，這點不用懷疑。但我們如果想安全抵達威奎斯特莊園，就需要其他助力。一支小型隊伍會是最理想的，這樣一來戰力足以對抗女巫的威脅，也依然能保持低調。\n\n<瑞德拿出一疊信件。>\n\n我已經寫了新的命令給我最優秀的幾個手下，要他們加入你的燼火會。這些士兵會向你和威奎斯特小姐報到。請將這些信件拿給他們，好讓他們準備出動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49804] = {title = "敏銳的思維", objective = "用露西爾的縫衣針測試10名寇連恩難民，讓隱藏在亞羅姆之地的女巫現出原形。", description = "我有理由相信女巫會已滲透亞羅姆之地。寇連恩的難民湧進這裡，因此有很多陌生的面孔。我們也知道，他們能用魔法把自己的外表變得跟我們一樣。\n\n這根針是純銀打造的。如果女巫的弱點真的是白銀，那麼只要用銀針輕輕一刺，就可以破除她們的咒術！\n\n難民被刺了之後可能會不高興，但他們必須了解，這樣做是為了這個城鎮好…或許也是為了整個佐司瓦好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n露西爾的縫衣針"}
MultiLanguageQuestData['tw'][49805] = {title = "惡意的陷阱", objective = "在亞羅姆之地摧毀12個禍心物品。", description = "<看來有個粗心的女巫不想讓人發現這本魔典，卻沒有藏好。把女巫會的鬼玩意留在這裡，要是讓某個倒楣的村民發現，絕對不會有好事。\n\n最好找出女巫會在亞羅姆之地所留下的陷阱，並加以摧毀。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49806] = {title = "暗中行事", objective = "探索粗略地圖上標記的地點。", description = "<在女巫的物品中，有張亞羅姆之地的地圖，畫得相當粗略。\n\n有個符號標示出一個入口，看起來像是能通往其中一棟建築底下的地窖。\n\n如果這個地點對女巫會來說很重要，或許值得你一探究竟。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49807] = {title = "新的組織", objective = "將審判官的服裝交給從亞羅姆之地招募的士兵。", description = "在我們離開之前，我還有一個任務想拜託你。\n\n在你忙著招募審判官，還有把女巫會趕出亞羅姆之地的時候，我向當地的裁縫師下了訂單。\n\n我請他根據書卷中的草稿，仿製了一些和遠古燼火會同樣的服裝。\n\n既然接下來要由你來領導我們的審判官，我覺得你來把衣服交給他們，是再適合不過了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49809] = {title = "阿塔達薩：從幻影現身", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][49810] = {title = "野獸媒人", objective = "將巫醫詹加拉的巫毒圖騰放在兩隻雷龍附近。", description = "我們有個問題，跟愛有關，而你來的正是時候。\n\n這兩隻白色的殘暴龍，溫和的班金和易怒的瑪卡番，是它們這族最後的希望。其他的殘暴龍不是病死就是被獵人殺死了。\n\n但牠們沒心情談戀愛。希望你可以幫助我和我的新朋友卡菈，這是唯一讓牠們擁有未來的機會。\n\n將我的巫毒圖騰放在這兩隻殘暴龍附近，這樣我才能察覺牠們的感受，藉此瞭解我們如何幫助牠們。", progress = nil, completion = "我們需要幫班金重振雄風，也讓瑪卡番「心情好」。該用巫毒方法還是科學方法好呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49812] = {title = "達拉然的德菈絲", objective = "去達拉然的安東尼達斯紀念碑找德菈絲‧月牙。", description = "德菈絲‧月牙需要我們幫忙。她會協助我們解讀命令寶典作為回報。\n\n請你盡快去找她。她經常去祈倫托過去偉大的領導者安東尼達斯的紀念碑附近。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49813] = {title = "冒險的呼喚", objective = "使用特殊任務，選擇你下一個要冒險的地點。", description = "你的英勇事蹟傳遍了整個艾澤拉斯…甚至傳進了別的世界。有其他地方需要借助你的力量。\n\n你是否願意進入黑暗之門並前往殘破的外域對抗燃燒軍團呢？\n\n還是要飛往北裂境，參戰討伐巫妖王？\n\n你自己決定吧，冒險者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49814] = {title = "雷龍用的薰香", objective = "找到7束芳香燈心草好為易怒的瑪卡番調製薰香。", description = "氣氛對愛情至關重要，而易怒的瑪卡番可沒那個心情。\n\n巫毒薰香，特別是我這樣的巫醫專家特別為雷龍調製出的薰香，一定會點燃她心中的母性火花。\n\n有種芳香燈心草最有效，而且叢林裡就有。\n\n贊達拉燈心草長在這附近的水邊。幫我多拿一點來，我就能做出一大捆薰香，足以營造愛的氣氛。", progress = "到植物繁茂的水域去找燈心草，我可以用巫毒術為雷龍做點薰香。", completion = "做得好！我會把這些燈心草編織成一捆薰香，並對牠們施放我最棒的法術。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49816] = {title = "燃燒的遠征：前往外域！", objective = "穿過詛咒之地的黑暗之門。\n\n在奧格瑪傳送室的索爾瑪法師可以協助你抵達該地。", description = "燃燒軍團這支無窮無盡的惡魔大軍，大舉進攻外域這個滿目瘡痍的獸人家園。我們需要部落的冒險者去保護殘存的外域，別讓惡魔完全毀滅這個地方。\n\n先到詛咒之地，然後再通過黑暗之門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49817] = {title = "前往北裂境！", objective = "搭乘飛艇開往北裂境。\n\n你可以在提里斯法林地登艇飛向凜風峽灣，或是在奧格瑪登艇前往北風凍原。", description = "巫妖王在北方開始蠢動。\n\n不死大軍聽從他的指揮，橫越北裂境，在所到之處一路散播疫病。\n\n<name>，我們需要你去阻止它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49818] = {title = "戴林堡之難", objective = "到海風村和包爾中尉報到。", description = "上級派我到布瑞納丹，尋找一位浪潮賢者協助我們在戴林堡西邊的相關事宜。納迦對堡壘發動了另一波攻擊，規模比之前的都大。\n\n包爾中尉正在堡壘附近的村落協助市民，她需要手邊的一切援助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49831] = {title = "來自深淵", objective = "在堤岸上抵禦艾薩拉的攻擊。", description = "我們得準備抵擋敵人攻擊。\n\n操縱火砲！\n\n不計一切，防禦堤岸！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "戴林堡手斧風暴守望令杖塞斯吉爾女潮侍權杖普勞德摩爾軍隊長矛塞斯吉爾鱗衛之杖風暴守望短棒戴林堡矛槍凱蘭的長小刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][49832] = {title = "無法辨識的卷軸", objective = "將卷軸拿給迎風海岸邊的托爾托人。", description = "<裝在防水容器內的是一個年代和出處不明的卷軸，上面的字已經無法辨認。\n\n或許海岸邊的托爾托人會有辦法解讀這羊皮紙上寫的東西？>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49846] = {title = "兩道戰線", objective = "使用特殊任務，選擇你下一個要冒險的地點。", description = "<name>！我們要再一次請你協助部落處理重要的事務。\n\n你能幫助部落對抗死亡之翼和暮光之錘嗎？\n\n還是你願意往南飛去潘達利亞，取得資源，別讓聯盟捷足先登？\n\n決定好了就前往戰場吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49851] = {title = "大災變緊急應變人員", objective = "到奧格瑪向先知克洛加爾報到。", description = "死亡之翼，是帶來死亡的巨龍，他派出爪牙到處殺害艾澤拉斯的生靈。\n\n如果想進一步了解遭死亡之翼鎖定的海加爾山、瓦許伊爾及其他地區情況如何，奧格瑪的先知克洛加爾能為你提供情報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49852] = {title = "前往潘達利亞！", objective = "到奧格瑪的葛羅瑪許堡報到。", description = "你受命立刻趕往葛羅瑪許堡報到。\n\n我們接獲消息，在南邊發現一處蘊含豐富資源的大陸，我們要派你和一隊士兵到那裡去為部落奪回資源。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49855] = {title = "海加爾山的災難", objective = "與塞納里奧使者黑蹄交談，以傳送進入月光林地。", description = "我們收到塞納里奧議會的兄弟回報，死亡之翼的爪牙正發動攻擊，企圖破壞世界之樹，威脅將它整個燒掉！\n\n去找塞納里奧使者黑蹄交談，他會讓你進入月光林地。黑蹄就在奧格瑪智慧谷的牛頭人區。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49860] = {title = "冒險的呼喚", objective = "使用特殊任務，選擇你下一個要冒險的地點。", description = "你的英勇事蹟傳遍了整個艾澤拉斯…甚至傳進了別的世界。有其他地方需要借助你的力量。\n\n你是否願意進入黑暗之門並前往殘破的外域對抗燃燒軍團呢？\n\n還是要飛往北裂境，參戰討伐巫妖王？\n\n你自己決定吧，冒險者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49862] = {title = "燃燒的遠征：前往外域！", objective = "穿過詛咒之地的黑暗之門。\n\n在法師區的榮譽堡法師可以協助你抵達該地。", description = "燃燒軍團這支無窮無盡的惡魔大軍，大舉進攻外域這個滿目瘡痍的德萊尼家園。我們需要聯盟的冒險者去保護殘存的外域，別讓惡魔完全毀滅這個地方。\n\n先到詛咒之地，然後再通過黑暗之門。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49863] = {title = "巫妖王之怒：前往北裂境！", objective = "快登船前往北裂境。\n\n你可以從暴風港搭船前往北風凍原，或是從濕地搭船前往凜風峽灣。", description = "巫妖王在北方開始蠢動。\n\n不死大軍聽從他的指揮，橫越北裂境，在所到之處一路散播疫病。\n\n<name>，我們需要你去阻止它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49864] = {title = "兩道戰線", objective = "使用特殊任務，選擇你下一個要冒險的地點。", description = "<name>！我們要再一次請你協助聯盟處理重要的事務。\n\n你能幫助聯盟對抗死亡之翼和暮光之錘嗎？\n\n還是你願意往南飛去潘達利亞，取得資源，別讓部落捷足先登？\n\n決定好了就前往戰場吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49865] = {title = "大災變緊急應變人員", objective = "到暴風城向語地者納拉亞特報到。", description = "死亡之翼，是帶來死亡的巨龍，他派出爪牙到處殺害艾澤拉斯的生靈。\n\n如果想進一步了解遭死亡之翼鎖定的海加爾山、瓦許伊爾及其他地區情況如何，語地者納拉亞特能為你提供情報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49866] = {title = "潘達利亞之謎：前往潘達利亞！", objective = "到暴風城向瑞爾‧夜風報到。", description = "請立刻趕到暴風要塞，聆聽瓦里安‧烏瑞恩國王的任務簡報。\n\n我們收到消息，南方的海上發生了衝突，需要經驗豐富的<class>去幫我們查明狀況。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49869] = {title = "絕望的防禦", objective = "向塔倫福德中尉報到。", description = "守在這裡的士兵正在盡力抵抗，但他們快守不住了。海盜已經很多年不敢攻打戴林之門，他們的勢力從來沒有像現在這麼龐大。\n\n如果你擅長戰鬥，塔倫福德中尉一定會想見你。\n\n他就在前方組織民兵。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49870] = {title = "體型決定一切", objective = "對班金使用「巫」化兇暴配方。", description = "讓溫和的班金變得，我們說「迷你」吧，意外的副作用就是，現在他小到可以進入風毒蛇獸王的洞穴了！\n\n那野獸名叫幽暗之尾，如果班金擊敗牠，他就會覺得這是他的領地，並想在上面生一堆小雷龍。這樣他就會想找個伴。如果瑪卡番願意接受，就是皆大歡喜的局面！\n\n去再給他一劑配方吧！", progress = "體型不是一切。如果班金很小，就可以抵達更多地方…並在那邊作戰！", completion = "太不可思議了！我在這裡就可以聽到他的噴氣聲和踏地聲。\n\n做得好，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49871] = {title = "逆勢而行", objective = "殺死督軍席奧，然後點燃烽火。", description = "魔古越來越絕望。哈！或許想在羅亞之怒降在身上之前逃之夭夭！\n\n那個督軍的寵物法師架設了路障，並攻佔了高塔。\n\n如果你能避開那些尖針，這些聚雷針可能會讓你感覺非常好。另一個說法就是充能。\n\n找到督軍席奧，解除他生命中的特權。\n\n然後讓我們的人民知道，我們已經奪回帕骷之息了！\n\n這個魔精在強化之下，可以在猛烈的爆炸中點燃這座塔。", progress = nil, completion = "不錯，&lt;name&gt;！我們的任務就快完成了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49873] = {title = "犧牲之令", objective = "詢問克隆娜犧牲之令的事。等她提供你需要的資訊以後，依照她的指示做。", description = "<你往書卷裡看，你看到一段文字出現，發出鮮紅色的光芒。>\n\n「鮮血欲結盟，汝必定契約，\n求汝為此犧牲。\n尋覓弱者，絕不謙讓，\n因果報償，汝將受治癒。」\n\n<隨著你讀完這段文字，你注意到手中出現了一個卷軸。\n\n它的頂部寫著標題：「犧牲之令」。卷軸剩下的部分則寫滿了許多你不認得的符文。但，卻沒有任何關於卷軸該如何使用的說明…>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鮮血合約：犧牲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49874] = {title = "遵循書卷", objective = "進一步調查放血手冊以開始你的試煉。", description = "隨著你打開書本，你盯著空白的一頁，等待什麼事發生。\n\n你直覺地翻到下一頁，發現它也是空白的。或許你進一步的試煉在書裡等著你？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鮮血合約：血腥\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49876] = {title = "最後試煉", objective = "到沃魯敦的虔信者殿堂找斐里斯以展開你的鮮血試煉。", description = "我能給你的只有這些了，年輕的雕銘師。但你的旅程還沒結束。\n\n如果你對其他更致命的鮮血合約感興趣，也願意跑遠一點，你可以繼續旅行到贊達拉。\n\n到那裡的時候，去一個叫沃魯敦的地方，找一名叫斐里斯的塞斯拉克。\n\n<克隆娜拿起一個怪異的罐子並打開蓋子。一股有史以來最可怕的臭味從中洋溢出來，讓你噁心到天旋地轉。>\n\n醃漬鱷魚蛋是我的最愛。你要不要來一點？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49877] = {title = "瑟沙利斯神廟：閱取恩澤", objective = "從瑟沙利斯神廟取回滅亡之書。", description = "當無信者掌權的時候，我們虔信者逃出了我們偉大的神殿並在此落腳。\n\n不過在流亡途中，有許多人被迫放棄我們的所有物。\n\n我自己就留下了一本用來學習滅亡合約用的書籍。如果你想要繼續進行試煉，你就得幫我把書拿回來，<name>。\n\n我相信你不會讓我失望的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49878] = {title = "寫下保護", objective = "收集贊姆蘭海盜的骸骨並把它們磨成細粉。把粉末和你的鮮血混合以製成骨膠墨水，再簽署血衛編年史。", description = "<隨著你打開書本翻閱頁面，看到書上都是勇士站在一頭巨獸身旁的圖案。\n\n你最後翻到一頁空白，並碰了碰書頁。古老語言形成的符文逐一出現，很快地被翻譯成你能閱讀的語言。>\n\n「居其中者，生靈守衛，\n混合血骨，\n以筆塗染。\n雕者之血，\n土地之骨，\n完美磨製，\n親手簽署。」您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鮮血合約：血衛\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49879] = {title = "和死神擦肩", objective = "拿起羽毛筆，開始你的試煉。", description = "<隨著你打開書本，一股寒意席捲全身。你閱讀文字段落，一邊驅趕那股寒意。>\n\n「此等致命協議，鮮血澆注而成，\n一滴誓言墨水，\n帶著幸運筆劃。\n信守你的文句，\n隨著呼吸吟誦，\n惟恐佚失路途，\n呼號死亡降臨。」\n\n<隨著你唸完咒語，一支羽毛筆出現在書的旁邊。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鮮血合約：滅亡\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49881] = {title = "最終的段落", objective = "在祖達薩南邊找到彌朱以開始你最後的試煉。", description = "看來你在這邊的事情做完了，<name>。再次感謝你幫我把書拿回來。\n\n但容我告訴你一個小秘密，這還算簡單的。等你見到宗師就知道了。\n\n如果你還沒注意到的話，你需要一根特殊的羽毛筆才能啟用這些合約。而且他就是那個告訴你如何製作它的人。\n\n他的名字叫彌朱，就住在祖達薩南方海岸外的一座島上。祝你好運，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49882] = {title = "羽毛筆的試驗", objective = "當你準備面對最後試煉時和彌朱交談，並收集製作你專用羽毛筆的知識。", description = "你正在尋找的配方，年輕人，是菈娜薩爾的血紅羽毛筆。我…\n\n<彌朱對著一大堆東西示意。>\n\n我只知道還有一個人有…呃…某個地方。但要先警告你，這場試煉可能會召致你的毀滅！\n\n我會施放全數四份契約來對抗你，你必須擊敗裡面的每一個生物，並從生物身上習得刻在你羽毛筆上的符文。\n\n一旦你學會全數四個符文，你的試煉就完成了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n設計圖：菈娜薩爾的血紅羽毛筆\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49884] = {title = "希望的藍光", objective = "和格瑞茲古船長一起飛行，並點燃塔上的烽火。", description = "只剩最後一步了！\n\n第二座塔表示艦隊回到我們手上了！\n\n爬上來，我們會解決這件事！", progress = nil, completion = "你拯救了艦隊，並保護了諸王海灣！\n\n你做得很好，&lt;name&gt;！我們船長要聰明得多。", rewards = "藍色烈焰術火炬黃金艦隊圓盾托卡利纏手贊庫爾纏手拉斯塔瑞手套詹巴尼手甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][49886] = {title = "用你的鼻子去聞", objective = "使用韓福瑞找出並殺死5名驚慌的挖洞工。", description = "那邊的！我需要你的幫忙！\n\n地面並不安全。野豬人已經在我們腳下建立了坑道網，讓他們跳出來突襲沒注意的路人。\n\n幸好，韓福瑞的鼻子聞得出棘背野豬人，就算在地下也聞得出來。把他們找出來，讓農場變得更安全。\n\n東北邊的田裡有大群棘背野豬人。祝狩獵好運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49887] = {title = "強迫的勞工", objective = "釋放山繆‧威廉斯。", description = "<工人奮力抵抗束縛他的魔法，開口說話。>\n\n幫…幫…我們…\n\n<他痛苦地舉起一根手指，指向附近的錨。>\n\n拜託…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49888] = {title = "阿塔達薩：一個小魔精", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][49890] = {title = "佐司特的敗亡", objective = "調查冰洞。", description = "我在洞穴入口那裡還有看到其他的雕刻。來吧，我們去看看還有什麼。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "幻光水銀披氅您能選擇下列奬勵中的一個：\n\n羅瓦伍德戒環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49896] = {title = "前往獵鷹林！", objective = "到獵鷹林外與審判官科利爾東碰面。", description = "我們確實好好地利用了待在這裡的時間。還有少數剩下的佐司特勢力，但亞羅姆之地的守衛應該有辦法應付。我懷疑佐司特領袖和他的魔法，對這裡的影響可能還更為深遠。\n\n但是我們必須繼續前往獵鷹林進行任務。沿著遺跡另一頭的道路就可以抵達那裡。\n\n我會騎在前頭，我們城鎮外碰頭！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49897] = {title = "創造地精奇觀", objective = "捉5隻普通雞。", description = "你知道大家喜歡什麼嗎？沒辦法解釋的事情！問題是這裡所有事情都可以解釋。\n\n所以我有個計畫，我要自己創造地精奇觀。有些傳說提過某種奇怪的雞蛇混種生物，可以把人變成石頭。我已經有雞了，我們需要蛇。\n\n這個問題很容易解決。去捉雞，然後把機械尾巴黏在牠們身上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49898] = {title = "毋庸置疑的勝利", objective = "殺死15個佐司特骷髏。", description = "<這個隊長的鬼魂在開口說話時繼續作戰，再度陷入激烈的戰鬥中，完全沒注意到當年那場戰爭好幾百年前就結束了。>\n\n你站在那邊做什麼？我們好不容易撐到他們只剩最後的戰士和那些該死的符文傀儡，不過戰爭還沒結束！\n\n威奎斯特上校需要我們才能夠守住這條陣線！盡你所能消滅這些防衛者，我們今天或許還能看到這場戰爭結束。快點滾過去！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49901] = {title = "阿塔達薩：亞茲瑪墮落女祭司", objective = "在阿塔達薩擊敗亞茲瑪。", description = "祖爾知道我們不能讓開國神王從墳墓裡甦醒，達薩對於祖爾夢想中的食人妖帝國來說不只是個門面，還會是股可以和羅亞匹敵的力量。\n\n但我不能讓祖爾逃走，我會帶著我的人追蹤祖爾，但我要你帶著你的人進入阿塔達薩。亞茲瑪正在想辦法爭取時間，不讓墳墓的封印遭到解除。你必須突破重圍才能接近她，而且還需要盟友的幫助。殺了她。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49902] = {title = "前往幽暗谷。", objective = "招募托爾托人與你一同前往幽暗谷。", description = "在納茲米爾，能讓洛克漢和其他部落朋友安全躲藏的地方只有一個，那就是幽暗谷。\n\n你很幸運，那地方離奎格瓦的洞穴很近，我們將幽暗谷當成我們朝聖之旅的最後一站。\n\n請沿著我地圖上標示的道路前往幽暗谷，半路上若遇到托爾托人，告訴他們，在那裡跟我會合。\n\n他們一定很想知道這場戰役的結局。我們會過去那裡，把路上見到的人一起帶過去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49905] = {title = "情節轉折", objective = "殺死沃爾詹巴。", description = "了結沃爾詹巴的時候到了。\n\n我想把話說清楚。他還是有辦法殺了你。你的命運比起我的，更是取決於你對抗我這位前任學生的能力。\n\n他會帶著面具和巫毒術，也會想盡辦法殺掉你。我們所做的只是讓他無法再作弊。\n\n祝你好運。看在你的份上，希望你不會失敗。", progress = nil, completion = "死亡是一種手段，&lt;name&gt;。別忘了這點。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49908] = {title = "回到布瑞納丹", objective = "到布瑞納丹向侍從奧古斯圖斯三世回報。", description = "感謝你的協助，大多數的納迦都清光了。如此一來，他們再度發動攻擊之前，會先仔細考慮清楚。\n\n你能不能回到布瑞納丹告訴侍從奧古斯圖斯三世，要他回平時駐守的哨站？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49917] = {title = "一定要卡迦邁！", objective = "前往藤中村。", description = "我等了好一段時間想和國王談話，但他都不見我！這位傲慢的奴僕也不肯理我。\n\n城外的藤中村就要大難臨頭了。在所有部落成員登陸港口之後，有些哥布林聽到了我們舊卡迦邁礦場的風聲。他們衝過去的速度之快，就像死亡之翼的利牙要在他們身後追著咬噬一樣。\n\n但那座礦場很危險，非常危險。你可以到村裡去，讓那些哥布林清醒一點嗎？", progress = nil, completion = "你來得正是時候，朋友。如果祖達薩這裡真的有卡迦邁，就會有一大堆事情要做！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49918] = {title = "猩猩峽谷", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49919] = {title = "豐富的卡迦邁礦石", objective = "在猩猩峽谷掃描卡迦邁礦區蒸汽孔。", description = "卡迦邁！光是說出這個字就讓我美麗的大耳朵嗡嗡作響。\n\n多年來，這些贊達拉人就坐在這巨大的礦床上。而他們因為幾隻會說話的猩猩就放棄了它。根據哥布林法律，它是我們的了！\n\n讓我們來看看這礦床的濃度有多高。去看看那些散發出卡迦邁煙霧的噴氣孔。\n\n到峽谷裡去，把我的掃描器放到那些蒸汽孔上，它們就會包辦後續工作。", progress = nil, completion = "謝謝你，傻瓜！我是說，朋友。\n\n這裡的卡迦邁夠我們開挖了。但這麼多會講話的猩猩擋路真是糟糕。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49920] = {title = "猩際大戰", objective = "拯救6隻反戰猩猩。", description = "你來的時機正好，陌生人。我感謝你的協助。\n\n猩猩峽谷現在並不平靜。卡迦邁賦予我們聰明智慧。但也隨之帶來戰爭。\n\n我的同伴們都不是好戰份子，無論是對贊達拉食人妖還是對我們猩猩同類們都一樣。可是，就是因為我們如此被動，所以才會遭到迫害。\n\n請釋放我的夥伴。他們就在峽谷各處的牢籠中，被人看守著。動作快一點！", progress = nil, completion = "謝謝你，我的朋友！你為我的夥伴帶來自由，真是無比英勇。我們晚點再多聊聊吧。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49922] = {title = "達卡王", objective = "殺死達卡王。", description = "這些贊達拉人不會靠近猩猩峽谷。這都是因為他們很害怕！\n\n不過就是幾隻會說話的猩猩嘛。特別是一隻「大傢伙」，贊達拉人都是這麼叫他的。\n\n我們要做的就是除掉達卡王，這樣所有的村民就會列隊歡迎我們！或者至少會讓我們挖卡迦邁礦。\n\n你能應付一隻大猩猩嗎，朋友？", progress = nil, completion = "很好，少了一個傻瓜要對付。卡迦邁幾乎就要到手了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49926] = {title = "通往寇連恩的路", objective = "在佐司瓦的看守者高地和瑞德元帥碰面。", description = "威奎斯特領主和夫人被困在威奎斯特莊園。我們要先勇闖寇連恩城，才有辦法找到他們。禍心女巫會目前嚴密控制了這座城市。\n\n我們首要之務應該是設立哨站。我們的斥候發現看守者高地的塔樓防守不嚴。我認為應該從他們手裡佔領塔樓。\n\n現在一切由你指揮，審判官。你一聲令下，我們就行動。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49928] = {title = "虛無精靈的傳承", objective = "在特洛古斯裂隙與艾蘭里亞‧風行者碰面。", description = "你在艾澤拉斯的這段旅程中，完全學會駕馭一直想控制你的這股力量。\n\n你已經成為聯盟不可或缺的一大助力，$p。回到虛無裂隙吧，我們想表揚你的成就。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n刃多雷傳承護甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49929] = {title = "召集盟友", objective = "到暴風城大使館與艾莎‧雲詠會面。", description = "整個艾澤拉斯陷入了危機，聯盟現在處境艱難。\n\n想要保護朋友的安全，唯一途徑就是尋找新的盟友。\n\n身為大使的職責，就是出力尋找這些盟友。來暴風城的大使館，我肯定需要你的協助。", progress = nil, completion = "多謝你能趕來，&lt;name&gt;。要找到新盟友並不容易，但你的支援可以提供莫大助益。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49930] = {title = "召集盟友", objective = "到駐奧格瑪大使館和紀‧火爪會面。", description = "你好，勇士！我被指派為部落的外交大使，與四面八方的盟友會面。\n\n我的職責就是尋找志向共同、精神相繫的對象，並和他們談談加入部落的可能性。\n\n如果能夠獲得部落英雄的協助，一定能發揮莫大助益，那個人就是你！你有空的時候，到奧格瑪的大使館和我會面。", progress = nil, completion = "真高興見到你，&lt;name&gt;。我們已經見過了許多適合加入部落的盟友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49931] = {title = "泰坦之怒", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49932] = {title = "不再沉睡", objective = "在幽暗谷外面查看未啟動的泰坦守衛者。", description = "有幾件事值得你留意一下。反正那些哥布林還沒準備好，你還有時間。\n\n附近有座雕像。不過，在飽經訓練的托爾托人眼中，它可是不僅如此。那是一台失去活動能力的泰坦守衛者！\n\n自從你協助過奎格瓦後，那東西就一直傳出雜音。它一定是在想辦法自我重啟！\n\n我敢打賭，你身上那個看起來和泰坦很有關聯的護符可以協助它重新啟動。如果有了泰坦守衛者的協助，我們在對抗鮮血食人妖時就無人能敵了。\n\n去看看你能否重啟這名泰坦！", progress = "偵測到核心。感謝取回。", completion = "需要你的協助，我們必須馬上開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49933] = {title = "為了部落", objective = "在駐奧格瑪大使館與黑衛大使見面。", description = "經過了漫長的隔絕與孤立，我們終於準備好要再度崛起。與部落結盟讓我們得以重新開始，我們一定要好好把握這個絕無僅有的機會。\n\n前去奧格瑪一趟。你在艾澤拉斯的冒險要從那裡展開。奮戰吧，保護這片土地，並且為夏多雷爭取一席之地。\n\n讓世人見識我們的能耐，<class>。為部落帶來榮耀，同時，這也會為蘇拉瑪爾帶來榮耀。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夏多雷外袍希瓦娜斯‧風行者女士的信"}
MultiLanguageQuestData['tw'][49935] = {title = "如何修復泰坦守衛者", objective = "從全毀的泰坦守衛者中取出泰坦資料核心。", description = "在附近建築中的主要主統有修復可能。初期目標：修復輔助系統。\n\n掃描偵測到三個倒下的泰坦守衛者。取出核心。泰坦守衛者赫茲羅可從核心擷取資料。\n\n泰坦守衛者赫茲羅目標：重啟輔助系統，前往附近建築，修復全數主要系統，封鎖腐化。\n\n結果：腐化隔離完畢。泰坦守衛者赫茲羅得以協助對抗鮮血食人妖。\n\n資料庫查無「鮮血食人妖」定義。", progress = "插入資料核心。", completion = "取得核心。即將進行資料驗證跟合併。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49937] = {title = "找回古物", objective = "從納茲瓦薩幽靈身上取得25個泰坦裝甲。", description = "區域掃描顯示，身披鎧甲的鬼魂在這地區四處遊蕩。目的：保衛建築，其活動現象由腐化造成。\n\n偵測到鬼魂護甲中有泰坦裝甲遺物。要求：取回遺物。\n\n泰坦守衛者赫茲羅能拆解泰坦裝甲，重鑄成可用來對抗腐化大軍的武器。", progress = "需要泰坦裝甲。", completion = "泰坦裝甲數量充足。等到功能修復，立即進行鑄造。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49938] = {title = "被腐化的土地", objective = "殺掉12個注血鞭笞者。", description = "附近偵測到超標等級的腐化物體。掃描顯示，植物群亦遭受腐化。\n\n必須根除遭到腐化的所有物體。要求：摧毀任何被腐化的植物。", progress = nil, completion = "植被腐化的程度已經降低到可接受的程度。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49939] = {title = "永別了，女巫", objective = "殺死女巫諾艾拉‧石南。", description = "我們幫防衛者爭取到了喘息的空間，但是那些怪物還是一直在攻擊路障！\n\n籌畫這件事的女巫趁著我們攻擊她的手下時逃走，我看到她到山丘上的宅邸裡去了。我會繼續在這裡守住陣地。\n\n你一定要到宅邸裡把女巫殺了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49940] = {title = "沙痕裂口", objective = "前往沙痕裂口與刃衛桑姬碰面。", description = "我聽到關於沙子與蛇的怨言。\n\n這項請願來自於祖達薩邊緣一座小村莊，大概只有幾座農場，我想應該叫多 - 什麼的。不知道他們為了什麼而求援。去看看發生什麼事。\n\n已經先派刃衛桑姬過去了。她應該能幫你迅速了解…情況。", progress = nil, completion = "拉斯塔哈終於派人來了！\n\n希望你不怕蛇，夥伴。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49941] = {title = "骸骨加工", objective = "用泰坦操控器削弱復活的巨怪，然後從這些怪物身上收集15塊骸骨。", description = "受腐化影響的不死生命體已包圍附近建築。無法靠近；必須訂立計畫。\n\n正在計算評估。\n\n完畢。腐化力量設計出大型生物，「復活的巨怪」聚集於腐化源頭附近。\n\n將取回的裝甲重製為泰坦武器，用以削弱巨怪、收集骸骨。\n\n執行骸骨摧毀程序，避免產生更多巨怪。", progress = "插入復活的巨怪骸骨，然後繼續。", completion = "即將展開骸骨摧毀程序。", rewards = "您能選擇下列奬勵中的一個：\n\n潛能激發裝置\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][49943] = {title = "鮮血合約", objective = "在血縛紀錄簿上面簽名。", description = "嘿，<name>！我有件令人興奮的事情要跟你說，但你一定要保密。這是我們雕銘師的秘密。\n\n<葛拉朱爾向你點點頭，拉出一本巨大的書卷。>\n\n這是一本血縛紀錄簿。把你的名字簽上去，我就教你如何製作「鮮血合約」這種危險的東西，但很值得。\n\n我只知道其中一種，而且我以前在使用它時簡直是被沖昏了頭，理由嘛…嗯，你馬上就知道了。\n\n所以，你意下如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49944] = {title = "轉進佐司特", objective = "到佐司瓦的走私者海灣找克隆娜。", description = "你可以在許多地方找到鮮血雕銘大師，傳授你必備的知識。我建議你該找的第一位大師是克隆娜。\n\n她有點…至少可以古怪來形容。她是少數幾位見多識廣的托爾托。\n\n她就是那個教我如何啟用鮮血合約的人！\n\n她喜歡在佐司瓦西岸一帶的走私者海灣閒晃。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49946] = {title = "最後試煉", objective = "到沃魯敦的虔信者殿堂找斐里斯以展開你的鮮血試煉。", description = "我只能教你這麼多了，年輕的雕銘師。但你的旅程還沒結束。\n\n如果你對其他致命的鮮血合約感興趣，也願意跑遠一點，你可以繼續旅行到贊達拉。\n\n到那裡的時候，去一個叫沃魯敦的地方，找一名叫斐里斯的塞斯拉克。\n\n<克隆娜拿起一個怪異的罐子並打開蓋子。一股有史以來最可怕的臭味從中洋溢出來，讓你噁心到天旋地轉。>\n\n醃漬鱷魚蛋是我的最愛。你要不要來一點？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49949] = {title = "不受歡迎的不死生物", objective = "在納茲瓦薩殺掉15個不死生物。", description = "腐化的力量正在復活附近亡骸，使其轉化為怪物。必須加以制止。\n\n無法全數殲滅，但是能減少數量。減少數量，等同減少隔離區之外的腐化影響。\n\n消滅周邊之不死生物。於此同時，守衛者赫茲羅的系統將繼續執行重開機作業。\n\n重開機目的：恢復腐化本質相關資料。", progress = nil, completion = "不死生物威脅等級降低至可接受範圍。仍需找到避開目標之可行方案，方能進入隔離區。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49950] = {title = "淨血", objective = "消滅4顆腐化能量球。", description = "<你看到一枚奇怪的鮮血寶珠，散發出痛苦和毀滅的低語。\n\n這一定就是赫茲羅一直在尋找的腐化能量來源。它們看起來相當容易摧毀。\n\n你可以在神殿庭園能看到更多寶珠。或許摧毀掉它們之後，有助於削弱這個區域的腐化。>", progress = nil, completion = "未偵測到腐化能量源。必須持續修復，不能重蹈覆轍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49955] = {title = "不該出現在此界域", objective = "消滅6個無面者。", description = "系統復原進行中。資料恢復完畢。腐化源頭來自於古神實體。\n\n偵測到附近多數實體，阻礙分析與隔離納茲米爾腐化的目標。\n\n實體從虛無中浮現，受到古神的腐化所吸引。\n\n請求消滅虛無實體。虛無存在妨礙了系統修復。", progress = nil, completion = "古神爪牙數量暫時減少。少了適當的隔離程序，此為暫時現象。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49956] = {title = "禁止虛無入內", objective = "封印4個虛無傳送門。", description = "掃描指出附近建築發生現實誤差。傳送門直接與虛無連結。\n\n目前推論結果，腐化源頭為古神，虛無被古神腐化能量吸引至此。\n\n必須封印傳送門，隔離被古神腐化吸引的實體。\n\n拿著這個裝置。感謝你為系統提供能量，泰坦守衛者赫茲羅才能鑄造出這個裝置。\n\n使用裝置封印虛無傳送門，防止更多虛無實體進入這個區域。", progress = nil, completion = "未偵測到虛無傳送門。必須維持下去。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49957] = {title = "取回協定", objective = "從霸王凱拉克西斯身上取回隔離協定。", description = "系統修復進行中。缺少關鍵因子：隔離協定。\n\n隔離協定可使防禦系統全面重啟，讓泰坦守衛者赫茲羅正確隔離。\n\n掃瞄結果顯示，神廟內部大型生物將隔離協定石片吸收到體內。此生物存在於此界域和虛無之間。\n\n要求：消滅該生物並取回協定。", progress = "請出示隔離協定。", completion = "已經取得隔離協定，展開系統重啟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49960] = {title = "咬他！", objective = "擊敗工頭剃瘤。", description = "我非常肯定，韓福瑞是個出色的追蹤者。如果牠鎖定了野豬人，牠也是最難纏、最生氣、最頑固的狗。這點肯定很有幫助。\n\n就在我們的鼻子下，那工頭率領了一群挖洞工，給我們帶來最麻煩的災難。如果你能除掉他，我們要在農地裡移動應該會更輕鬆。\n\n韓福瑞看起來有點餓，你不覺得嗎？你何不把牠也帶去一起執行任務？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49965] = {title = "戰爭龍群", objective = "和剛克一塊騎行到預言者神廟。", description = "祖爾發動了政變，但他卻沒能為自己守住金字塔。對於那些聚於他的麾下，準備和他一起叛變的人來說，他也沒有做出任何行動。\n\n這不禁讓我想到，他是不是打算籠絡達薩亞洛的人心。\n\n我們得搞清楚他想要做什麼。和剛克的學徒一起前往預言者神廟。在你抵達之後，找到戰鬥德魯伊蘿蒂，以獲得接下來的命令。", progress = nil, completion = "鮮血正在呼喚鮮血。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49969] = {title = "喚醒神祇", objective = "收集納迦血肉塊，做為獻給格拉爾的祭品。", description = "你看到東邊的那座沉沒廢墟了嗎？不久之前，那原本是格拉爾、一位鯊魚羅亞的神殿。\n\n納迦搗毀他的神殿，現在又偷取他的秘密。如果這是為了做善事，我就認顆石頭當爸爸。\n\n能讓格拉爾知道發生什麼事應該是明智之舉，我不認為他會認同這一切。\n\n格拉爾十分強大，擁有非常豐富的海洋知識，沒有人能比得上他。如果你身邊有個這樣的同伴，有益無害。\n\n用一些新鮮、血腥的納迦肉，應該可以把他引出來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49973] = {title = "薩莉瑟拉的住所", objective = "到蘇拉瑪爾前往首席秘法師的莊園與莉雅德倫女士見面。", description = "你想不想聽聽夜裔精靈加入部落的故事？\n\n我們協助夜裔精靈解放蘇拉瑪爾、對抗大博學者艾莉珊德和燃燒軍團的暴政，獲得了他們的信任。\n\n後來洛索瑪‧塞隆邀請他們到奎爾薩拉斯。莉雅德倫女士更進一步邀請了首席秘法師薩莉瑟拉加入這段旅程…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49975] = {title = "與世長辭", objective = "完成釋放儀式。", description = "這條通道穿過風暴聖壇一路流到大海。我們會在這裡釋放死者的靈魂。\n\n根據傳說，當我們的靈魂穿越聖壇時，他們就會在祝福的儀式之下，為通過的所有庫爾提拉斯船艦祈福。\n\n這樣一來，我們斯陀頌恩人就能永遠為我們的人民服務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49977] = {title = "奧格瑪的召喚", objective = "與納薩諾斯‧凋零者交談。", description = "大酋長要你盡快返回奧格瑪。有件急事要你去做。\n\n等你到了我會再詳細說明。\n\n我在葛羅瑪許堡的入口附近等你。黑暗女王有任務要交給你，<name>。別讓她等太久…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][49980] = {title = "隔離程序", objective = "觀看泰坦守衛者赫茲羅搜索資料庫、找出方法，處理納茲米爾的古神腐化問題。", description = "掃描結果，建築物無法運作，無法維修。\n\n泰坦守衛者赫茲羅的資料庫全面復原。資料內可能有解決方案。\n\n需要時間搜尋資料，尋找隔離古神腐化的途徑。\n\n請在泰坦守衛者赫茲羅搜索資料時待命。", progress = nil, completion = "執行新協定。消滅鮮血食人妖為最優先事項。", rewards = "沒落之國砍斧沒落之國反曲弓退化帝國短刃第一城市手鐮受遠古羅亞祝福的釘錘腐化的部族擊頭錘納茲曼長杖納茲曼妖術刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][49985] = {title = "回到幽暗谷", objective = "到安圖爾納茲曼外和泰坦守衛者赫茲羅會面，以返回幽暗谷。", description = "主導摧毀封印的幕後主使者為古神古翰，號令鮮血食人妖摧毀祖達薩最後封印。\n\n泰坦守衛者赫茲羅必須協助消滅鮮血食人妖，不能讓祖達薩的封印就此毀滅而解放古翰。\n\n必須離開安圖爾納茲曼內部。到神殿外面和泰坦守衛者赫茲羅會面，協助回到幽暗谷。\n\n在工作完成後，泰坦守衛者赫茲羅得必須與古翰隔離設施裡的其他守衛者聯繫。", progress = nil, completion = "完成了，追擊鮮血食人妖所需要的所有要件都備齊了，馬上動身吧。", rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][49994] = {title = "帥氣滑動", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][49995] = {title = "造船陰謀", objective = "取回8個戰艦藍圖。", description = "我們在船塢建造的船有點不對勁。我從沒看過藍圖，但從我過去的造船經驗來看，它不是一般的船。\n\n他們把所有的資料都留在鹹水坊，延著路往上不遠之處。裡面滿是民兵。\n\n如果你拿到足夠的資料，我們應該可以搞清楚斯陀頌恩領主和他的手下在搞什麼鬼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][49996] = {title = "重整軍備", objective = "取得12件風暴灌注武器。", description = "這谷地的人都很正直，<name>。他們亟欲奪回他們家鄉的主導權。\n\n我們必須協助他們。\n\n從這條路往上走就能到鹹水坊。那裡負責供應斯陀頌恩家族大部分的武器，所以應該會有很多可以拿來用。\n\n如果你能收集足夠的武器，我會帶領我們的這些朋友做一些基本訓練。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "大海戰斧鹹水坊靴中刀風暴灌注打擊拳套雷狙步槍鹹水坊碎顱錘海潮守衛魚叉風暴灌注尖杖海潮守衛法刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][49997] = {title = "風暴審判", objective = "面對語濤者里德。", description = "當我在儀式中對洋流敞開心靈時，可以感受到斯陀頌恩領主的黨羽。\n\n語濤者里德。如果說有人能找回失蹤的艦隊，非他莫屬。\n\n如果我的弟兄打算和自己的人民作對，我不會袖手旁觀。去他的誓約。\n\n我們一定要逼里德看清一切。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][49998] = {title = "深處之聲", objective = "協助派克修士調查他的預兆。", description = "其他人趕向霧潮集會所了。我不認為他們會受到什麼熱烈歡迎。\n\n我們正要過去和他們會合，但我得先做一件事。\n\n雖然里德撤退了，我還是感覺到附近有股可怕的黑暗勢力，我想要聆聽海潮尋求答案。如果你能同行、應付路上可能遇到的危險，我會很感激的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50000] = {title = "全力剷除", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][50001] = {title = "絕命毒巫", objective = "殺死15個石南木生物和女巫。", description = "城鎮被攻陷了！\n\n守衛已經撐不住，更糟糕的是有些居民還被女巫的魔法影響了。這些居民現在就像邪惡的野獸一樣，只會盲目服從命令。\n\n我們一定要解救這些可憐的居民，把殘害他們的怪物徹底解決掉！\n\n看看你能不能想辦法減少鎮上的怪物數量！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50002] = {title = "那個『珍貴的』貨物", objective = "在霧崖海岸找到那個『珍貴的』貨物。", description = "我們不是艦隊唯一受困的船。我們的指揮艦在東邊擱淺了，船上有非常珍貴的貨物，我需要你去把貨物帶來這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50003] = {title = "第一個據點", objective = "在看守者高地擊敗女巫愛德菈。", description = "如你所見，女巫會從我的守衛當中徵召手下對抗我們。雖然跟自己人作戰讓我非常痛心，但這些人已經被女巫會的魔法腐化得太深，無可救藥了。\n\n對他們來說，殺死他們就是最仁慈的做法。\n\n我和審判官們會解決駐守在外面的守衛，帶頭的領袖就交給你對付了。\n\n你的審判官們在等你下令，<class>。準備好要去攻下這座塔了嗎？您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "威奎斯特審判官之盾首席女巫的燈籠您能選擇下列奬勵中的一個：\n\n復活破壞者指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][50005] = {title = "牽我的手", objective = "護送佩妮回到她父親身邊。", description = "現在就帶我去找爸爸！\n\n等等！你要牽著我的手才可以…您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "掠劫者手套劫海者手套領航員裹手翼艇之握您能選擇下列奬勵中的一個：\n\n佩妮的友誼戒指\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][50009] = {title = "船難搜救隊", objective = nil, description = "霧崖海岸到處都是海妖和尖角蜥！把他們殺了，然後帶走船上剩下的貨物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50026] = {title = "救救我們的船員", objective = "到霧崖海岸找亨利‧哈德維克。", description = "噢，感謝星光！我們的船擱淺了，我們的人非常需要幫忙。\n\n到山下的船遇難的地方找亨利‧哈德維克。他還留在那邊盡量幫助其他人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
