MultiLanguageQuestData['tw'][50370] = {title = "深入森林", objective = "和科利爾東、艾希頓和韋伯一起進入森林深處。", description = "我們必須深入這片森林。那些女巫顯然在謀畫某些事，比我們想像中更可怕的事。\n\n雖然我有責任帶艾希頓大師回去找露西爾小姐，但我同樣也有責任去弄查明威脅我們生命安全的邪惡勢力在圖謀什麼，並且想辦法加以阻止。\n\n進入森林深處一定會有危險，但我相信冒這個險是值得的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50371] = {title = "暴風城的召喚", objective = "在暴風城和馬迪亞斯·肖爾見面。", description = "烏瑞恩國王要你盡快返回暴風城。有件急事需要你去辦。\n\n等你到了我會再詳細說明。\n\n我在雄獅陵園等你。請快一點…機會稍縱即逝！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50372] = {title = "沙漠研究", objective = "和譚美‧技旋交談。", description = "薩格拉斯的黑暗劍刃使這片大地籠罩著毀滅的陰影。\n\n我們原本以為異種蟲巢在攻擊之下都已遭到摧毀，但我收到的回報表示，異種蟲又出現了。\n\n我們需要找出異種蟲如何躲過這場浩劫，以及劍刃對蟲巢造成了何種影響。\n\n國王想要解剖存活的異種蟲進行研究。\n\n譚美‧技旋會負責這個研究，她需要一個「抓蟲人」。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50373] = {title = "突來訪客", objective = "和大法師卡德加交談。", description = "希利蘇斯的情況似乎越來越引人注意。\n\n大法師卡德加在你離開的時候來到這裡。他似乎是專程來這裡找你的，<name>。\n\n看來這件事很緊急，建議你快點去找他談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50374] = {title = "艾澤拉斯之血", objective = "傳遞麥格尼‧銅鬚的訊息。", description = "聯盟和部落的領袖，真的知道他們在爭奪什麼嗎？\n\n從世界創口湧出的物質，其實是艾澤拉斯的生命之源！\n\n我們該做的是治療傷口，而不是爭奪力量！艾澤拉斯是我們唯一的家園，我們不能讓她就這樣死去！\n\n<name>，我信任你，而且我知道你的意見對聯盟的人來說很有分量。你必須勸阻他們，停止這種瘋狂的行為！\n\n只有這樣，世界才會有希望…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50376] = {title = "玩命戰利品：釣大魚", objective = "聽聽虎克船長的故事。", description = "你敢相信這些飯桶多有種嗎？在這座泊船處訊問船長本人？\n\n呸！\n\n把你的耳朵靠過來一下，靠久一點也行。我有一個故事，絕對會讓你想把杯子注滿酒、渾身長滿雞皮疙瘩！\n\n在這麼多海域中，那是我所劫奪過最大、最致命的戰利品…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50381] = {title = "大帽子搶案", objective = "成功偷取提克蘇的帽子。\n\n如果你的羽冠龍偽裝不見了，回去找迦尼再要一個。", description = "商人在這條路上來來去去，帶著貨物往往返返發大財。\n\n其中一位叫提克蘇的大老兄最差勁。他連手腳都拿來交易，甚至得讓食人妖花點時間把身體長回來。\n\n他最大的驕傲？他的帽子。\n\n當我的信使，有錢的老兄。嚇嚇這個笨重的野獸，並把提克蘇敲下來。把他的帽子拿來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50384] = {title = "Doug Test - Completable Quest4", objective = "到劍刃山脈的血之環找沙伯邁恩男爵談談。", description = "<name>，當你出去對付<class>的時候，沙伯邁恩男爵派他的寵物龍帶來一個訊息。\n\n他在找你本人。據我了解，他想要你率領他自己對古羅的戰鬥。\n\n我猜測你是在整個外域裡最有資格幫助他的人，但是如果我是你，我會先與兩位朋友聯繫，並且要他們在血之環加入你的行列。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n邪惡鬥士皮甲外衣"}
MultiLanguageQuestData['tw'][50385] = {title = "不屈不撓的意志力", objective = "淨化3座溺斃祭壇。", description = "就算只是一下子，它的控制力量變弱了。我們必須重新佔領這個地方！\n\n不斷拍翅的惡夢魔女已經侵入了海灣洞穴。帶上神聖的祝福，冒險踏入黑暗，找出他們的祭壇！\n\n從我們的土地上，淨化他們的不潔之物！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50386] = {title = "將他們趕出來", objective = "在遺忘海灣調查並擊敗4座建築內的東西。", description = "他們在陰影中躲藏，在海水瀰漫的洞穴出沒。海水表面閃著純淨的微光，底下卻潛伏著黑暗。\n\n我見過他們。他們折磨我的夢境，他們的低語令人發狂。他們提到了主人，還想挖掘我的心防…\n\n搜尋懸崖，找出他們的窩巢。找出藏在裡頭的事物，消滅那裡的一切。", progress = nil, completion = "那些東西被趕回去了，短期內是如此。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50387] = {title = "飾品與小玩意", objective = "取回3箱遭竊的補給品。", description = "在浪潮之下，這些恐懼之物不想待在他們的棲息處。\n\n他們在夜色中現身，從村民身上偷取東西，沉溺在他們的貪欲中。他們使用這些補給品來對抗我們，並做為儀式之用。那是一種召喚儀式，能與超乎我們想像的恐懼力量溝通。\n\n我對百姓毫不關心，但我不想看到這些海水中的小偷到處放肆。讓他們從掠劫中解脫，給他們痛苦的教訓。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50388] = {title = "野心的重量", objective = "擊敗溺水船長。", description = "就像其他聚落一樣，我太依賴水手和船舶來運送補給品。他們很勤勞，也不會多問什麼，幫了我不少忙。\n\n可想而知，許多敵人開始注意到他們，包括那些浪潮之下的敵人。他們的錨受到詛咒，他們甚至還來不及出聲，就被拖進海底。\n\n我看過那些人，他們拉起了永恆的船帆、唱著受詛咒的水手之歌。想讓這片水域恢復安全，一定要讓他們安息，永遠安息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50389] = {title = "惡毒念頭", objective = "殺死迷音女妖。", description = "很久以前，有個少女。\n\n她是個早熟的孩子，愛唱歌，喜歡模仿我的一舉一動，一開始，我覺得她挺可愛的。\n\n有一次她在碼頭邊緣散步，旁邊有一座瞪大著眼睛的雕像，她被圍在雕像上的繩子纏住了。就在那時，海水一陣起伏，把女孩和雕像一起沖進海裡。\n\n我到現在還能聽到她的歌聲。一開始我以為這是幻聽，不過是海浪打出的聲音。但我現在發現那個歌聲帶有邪惡的氣息。\n\n她必須死。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50391] = {title = "玩命戰利品：主砲手釣魚", objective = "傾聽主砲手賴恩的故事。", description = "我告訴你，虎克的腦袋裡有個螺絲鬆了。一群鯊魚團結合作…呸！\n\n不過，這倒是讓我想到一個我最喜歡的故事。我有沒有跟你說過，我有一次抓到了全艾澤拉斯最大、最致命，觸手最多的野獸？\n\n總之，我應該是沒說過，我應該不會在清醒的時候講這個。那一天和平常都不一樣…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50393] = {title = "帕骷之子", objective = "將翼手龍蛋交給翼手龍峭壁的帕骷。\n\n已提供物品：\n", description = "<溫熱的翼手龍蛋顫動著。它馬上就要孵化了。>\n\n或許有什麼翼手龍的羅亞可以幫助你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50394] = {title = "麻煩歸你", objective = "將翼手龍蛋放在空巢中，等它孵化。", description = "嗯，這顆蛋不是出自我這窩蛋，而且我的幼雛不需要其他兄弟姐妹。\n\n<帕骷像是微笑，又像咆哮，露出滿嘴尖齒。>\n\n你必須照料這個小東西，而且最好動作快點。\n\n它很快就會孵化了。\n\n給你一點小建議。如果你想讓那個小傢伙喜歡上你，最好讓它孵化時第一眼就看到你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50395] = {title = "天空的呼喚", objective = "看著你的幼龍第一次飛入大千世界。", description = "<夸風龍將頭轉向懸崖，發出密集的啁啾聲。牠張開小小的翅膀，奮力拍動。>\n\n離巢的時候到了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50396] = {title = "翼手龍的命運", objective = "向帕骷求助。", description = "<夸風嚮往地凝視地平線，發出熱切的叫聲。\n\n你可以從天上抓下翼手龍，卻奪不走它對天空的嚮往。該有所作為了。\n\n或許帕骷能提供一些建議。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50397] = {title = "飛空渴望", objective = "要飛了？", description = "<夸風仔細的研究著你的動作。一側的金黃色眼珠一直盯著你，毫不動搖。>\n\n嗄啊。\n\n<牠轉頭對著地平線，把雙翼張到最大。>\n\n嗄啊！\n\n<時候終於到了嗎？>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50401] = {title = "害怕墜落", objective = "尋找你的小翼手龍，說服它回巢。", description = "有些幼龍很快就能學會飛行。至少你的幼龍知道一直展開雙翼。\n\n我不會太擔心它的安全 - 體型越小，就越容易彈起。\n\n這次雖然失敗了…但幼龍必須不斷嘗試，它們必須學會不怕墜落。你得負起責任教會它。\n\n<羅亞露出滿嘴利齒，對你微笑。>\n\n如果它學習意願低落，你可以考慮誘之以利。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50402] = {title = "哩伊伊伊伊！", objective = "找到小翼手龍不舒服的原因並設法解決。", description = "<夸風看著你好一陣子，然後張口發出持續不斷的尖叫聲。\n\n你需要協助。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50412] = {title = "重回巢穴", objective = "把夸風送回翼手龍峭壁的巢穴。", description = "<夸風抬頭一臉信任地看著你。>\n\n現在正是帶牠回巢的好時機。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50417] = {title = "沒落時刻", objective = "找出神秘信件的作者。", description = "浪潮之下潛藏著一道恐懼，它試圖毀滅我的家人、我的住所，還有我的遺產。\n\n你一定得過來追尋你的命運，讓我們從深海的恐懼中解脫！\n\n到東邊的莊園找我們，就在群島之間。我們曾經居住在巨大堡壘的庇陰之下，過著豐裕的生活。我們曾相信祭司可以讓我們遠離下頭的無邊黑暗。如今黑暗已經浮現，在我們睡夢中呢喃著瘋狂。\n\n快點。我的生命早已受到詛咒，現在更是最黑暗的時刻。", progress = nil, completion = "你回應了信件的請求。現在你被束縛在此地了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50418] = {title = "玩命戰利品：下潛游泳", objective = "仔細「聆聽」『辛可』的「故事」。", description = "呣呣！\n\n呣呣呣呣呣。呣呣呣。\n\n呣。\n\n呣呣？呣！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
