MultiLanguageQuestData['tw'][50769] = {title = "暴風城撤離", objective = "完成「暴風城撤離」事件。", description = "我的女王無比精明。如果我們要滲透暴風城，我們需要整個部落的最佳能手，組成一支夠精簡的隊伍，才能滲透到聯盟的核心領地而不被發現。\n\n<納薩諾斯凝視著集結隊伍，撫著下巴。>\n\n是的，我懂了。\n\n前方的路很明確。在你準備好要進行大酋長的任務時，就來找我談談，<name>。", progress = "我們絕不能讓大酋長失望。", completion = "很好，我們到了，祖達薩。我們最好暫時先跟緊塔蘭姬和祖爾。大酋長一定想知道接下來發生的事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50770] = {title = "有效抗毒劑", objective = "讓賽里克喝下抗毒劑。", description = "抗毒劑準備好了。\n\n我已經盡量趕了，希望毒蠍毒液還沒有發作。\n\n把這個抗毒劑拿去，幫忙餵他全部喝下去。\n\n不用多久時間，就能知道抗毒劑有沒有效。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50771] = {title = "呼叫：清道夫", objective = "為採礦隊辨識並標記5處艾澤萊晶岩礦床。", description = "整個海灘都是把沙塵弄滿天的瑟拉阿貓阿狗，我們的清掃員要到礦點那邊真是困難。\n\n有些成員想要去別的地方看看，但我們沒拿到加里維克斯的石頭才不會走。\n\n告訴你一個秘密，<class>，我們這次的任務獎賞可是多到誇張。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50773] = {title = "你是鯊", objective = "殺掉20隻魚人。", description = "你有沒有被鯊魚咬過？我有，好幾次。那很痛。\n\n通常魚人很難逃過鯊魚的攻擊。\n\n我在構思的儀式已經可以進行。你準備好就告訴我一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "里凱的儀式串珠您會收到：\n\n"}
MultiLanguageQuestData['tw'][50774] = {title = "一個機器人都不能少", objective = "幫助爾力。", description = "你不但拋下了爾力，還讓一頭大蟲吞了他！他是有感情，呃…有金融方面的價值。\n\n我們絕不拋棄任何機器人！\n\n殺死那條蟲，並把爾力帶回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50775] = {title = "給我們一點沙", objective = "收集20堆沙。", description = "這些傢伙消耗「彈藥」的速度太快，我們根本來不及補充！\n\n我告訴他們，我們就在沙灘上，你們就在噴沙機內，吸起來就行了！\n\n他們說這違反了地方分會的整潔駕駛條例。\n\n我聽他們在放屁。\n\n幫我們送來更多沙。那些沙子怪物一定有一大堆沙！\n\n我們會送上讓你滿意的謝禮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50776] = {title = "虛假先知", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][50777] = {title = "風暴甦醒", objective = "集結12位叛逃的浪潮賢者。", description = "我目前必須顧好山繆，我擔心黑暗會侵襲他的心智。\n\n我們周圍死去的男女是從莊園叛逃出來的人。賢者崗內有更多像這樣的人。\n\n找到他們，向他們宣告「風暴甦醒」。關於我們使命消息已經傳出去了，我們需要盡可能讓更多人站在我們這邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50778] = {title = "扭曲的企圖", objective = "殺死被束縛的風暴和被奴役的狂潮。", description = "航向…濃霧之中…\n\n一道下方的光芒…在黑暗之中。\n\n水在高漲…源頭來自…那股痛苦…\n\n啊啊啊，那股痛苦！\n\n快停下來。快停下來。讓那股痛苦停下來！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50779] = {title = "全面淨化", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50780] = {title = "約束之誓", objective = "取回潮汐之杖。", description = "我可是發了誓言，可惡。我們當初都發過。\n\n斯陀頌恩領主發出第一批命令的時候…嗯，你也看到結果了。重要的是我們宣誓要對我們的人民忠誠，不是對那個出賣靈魂的領主忠誠。\n\n他不在這裡，他現在已經抵達聖壇深處，沒有外來者能夠活著通過海峽的…\n\n除非有海潮守衛開路。\n\n<維多利亞盯著你。>\n\n潮汐之杖是通往前門的鑰匙，它就放在這裡。把它拿來，我就帶你去找他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50781] = {title = "遙遠的橋樑", objective = "以潮汐之杖打開風暴之徑。", description = "原本跨越此地的橋樑，是通往聖壇的唯一陸路。\n\n看來斯陀頌恩領主已經封住了橋，為自己爭取時間。我們試著重新開啟道路，但一直無法成功。\n\n不過，你取回的這把潮汐之杖或許可以讓我們鬆一口氣。海潮守衛精兵將它當做某種鑰匙，維繫跨越危險水域的風暴之徑。\n\n我們將再試一次儀式…不過請你拿好那把節杖。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
