MultiLanguageQuestData['tw'][50787] = {title = "我方的證據", objective = "揭露艾胥凡女士對凱瑟琳‧普勞德摩爾的叛變。", description = "普莉希拉‧艾胥凡多年以來一直深受凱瑟琳信賴。她們雙雙在塞拉摩失去丈夫以前就交情深厚，普莉希拉一直是凱瑟琳的摯友跟顧問。\n\n凱瑟琳當然也跟所有人一樣聽過普莉希拉的流言。無論是基於恐懼或信任，凱瑟琳選擇忽略流言。\n\n該讓她清醒了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50788] = {title = "內賊", objective = "在聯合廣場殺死6名艾胥凡戰鬥員。", description = "我們必須把凱瑟琳護送到安全的地方。\n\n幫我們解決這些叛徒！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50789] = {title = "一掃而空", objective = "在聯合廣場摧毀4個冒煙的貨物。", description = "看來普莉希拉有備用計畫。她的手下放了某種煙霧彈，想掩護她逃走。\n\n清除煙霧，讓平民撤離，我們才能守住這個地區！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50790] = {title = "緊追不捨", objective = "騎普勞德摩爾戰騎追普莉希拉‧艾胥凡。", description = "普莉希拉騎馬逃走了！快騎我們的戰騎追她！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50791] = {title = "嘎啊啊啊…", objective = "把夸風抱起來安撫。", description = "<夸風把頭藏到翅膀下。>\n\n嗄啊…\n\n<或許對這個小傢伙展現一點關愛可以讓他振作起來。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
