MultiLanguageQuestData['tw'][50900] = {title = "或許等你大一點", objective = "回到翼手龍峭壁的巢穴。", description = "<帕骷眯起眼看著那頭年幼翼手龍。>\n\n好吧，我沒點子了。我兒子會帶你回到巢穴。別擔心，這頭很會飛。\n\n你的小東西得自行回去。這可以塑造牠的性格。\n\n或許牠過一段時間之後，可以從這種荒謬的自信不足中走出來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50901] = {title = "羽冠龍大驚奇", objective = "在迦尼對賽薩金的惡作劇中活下來。\n\n如果你的羽冠龍偽裝不見了，回去找迦尼再要一個。", description = "在沃魯敦的沙裡到處都是殘酷的生物，但沒有一種能比得上贊達拉送來的雜碎。\n\n其中一個罪犯就在這裡，藏身在熱沙這個地方。他的名字叫賽薩金，而且他是國王的前任主廚。他有沒有告訴過你，他最著名的菜餚叫做「羽冠龍大驚奇」？猜猜主要材料是什麼。\n\n他的地位一落千丈，但是對迦尼來說，光這樣還差得遠呢。現在來讓他面上無光吧。\n\n只要別讓沙漠裡的生物看到你就好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50903] = {title = "失蹤的大師", objective = "找到艾希頓大師。", description = "在那些怪物攻擊城鎮的時候，我跟艾希頓大師匆匆忙忙拿了一點醫療用品就跑去找洛伊斯頓鎮長了。他沒能來得及躲到路障後面。\n\n要是他還活著…像他那麼瘋確實不無可能…他大概會窩在自己的小屋裡，身邊還有一堆藥劑和炸藥。\n\n對了，你可以去他的地下室看看，我不會靠近那個鬼地 - 我是說，我會去看看花園有什麼東西。\n\n小心不要被燒死了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50904] = {title = "廢棄走道", objective = "在阿圖亞曼找到刃衛卡嘉和戰衛洛琪拉。", description = "我的人民在好幾個世紀之前就知道這條遠古走道，但目前為止都沒人敢踏進去。\n\n這條走道直達揭滅者謎思拉克斯的墓地，而且傳說指出他的力量依舊在洞穴裡發散。誰知道在裡面有什麼樣的恐懼在等我們…\n\n看來你的朋友已經早一步進去尋找賈克拉傑，阻止他復活死去的謎思拉克斯。\n\n我們不能再浪費時間了。在對抗賈克拉傑的力量之前，我們必須找到卡嘉和洛琪拉！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50908] = {title = "聞起來像個麻煩", objective = "殺死部隊指揮官奧加斯和都莫克。", description = "部落在布瑞納丹灑下了不少鮮血。現在該再多灑一點了。\n\n鮮血的氣味會讓山丘上的捕獵者發狂。我們在狩獵時會用這一點來引誘動物。\n\n部落軍隊佔據了山丘上的洞穴。把這些氣味瓶丟進部隊指揮官策畫攻擊的洞穴。這股味道應該會引來山丘上的所有生物，全都朝他們進攻！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][50909] = {title = "火力至上", objective = "幫我們找回15把叛軍武器。", description = "這是我們的新家，我們會為了保護家園而戰！\n\n我們的人數或許不如對方，但絕對不會在火力上屈居劣勢。\n\n只要是斧頭、長劍、長矛、十字弓或槍枝都給我帶過來，幫助我們的反抗行動！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50910] = {title = "危險遊戲", objective = "殺光山丘上的被遺忘者刺客。", description = "部落的人嚇不倒我們，但有群被遺忘者刺客今天殺了我們兩個人。我們一直沒能追查到他們，真的很需要你的幫忙。\n\n他們是擅長偷襲的危險對手，千萬不要手下留情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50911] = {title = "一夫當關，對抗部落", objective = "殺掉10名部落成員。", description = "在狀況變得不對勁以後，我和幾個朋友決定幫助寇連恩的人，讓他們能夠平安前往亞羅姆之地避難。我發現山上有動靜，所以決定折回來查看一下，如果你覺得城鎮現在這個狀況還不算糟，那我告訴你，現在有更嚴重的問題要面對。\n\n那就是，部落。\n\n<麥凱利斯吐了口口水。>\n\n這是我們的土地，這些混帳沒有立足之地。讓這片雪地染上他們的鮮血吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50912] = {title = "發動引擎", objective = "找到引擎鑰匙。", description = "<有台哥布林採礦機器陷在雪堆裡，露出半個機身。\n\n雖然埋在雪裡，但看起來還是堪用。只要找到引擎鑰匙就可以了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50913] = {title = "亞昆達的祝福", objective = "到亞昆達的聖壇進行溝通。", description = "你證明有資格獲得我的祝福，<name>。\n\n這表示如果你選擇我做為你的羅亞，你可以在需要的時候呼喚我的力量。\n\n到我的聖壇進行溝通，並接受我的贈禮。\n\n要知道，不管你的選擇為何，都隨時歡迎你來到這座建築內。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50929] = {title = "大家的粉末", objective = "打開6個箱子，拿走裡面艾澤萊晶岩。", description = "山上那些部落混帳好像在開採某種我沒有看過的礦石。\n\n他們大老遠跑到這裡來採礦，這礦石一定很有價值。你能找到多少就拿走多少！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][50930] = {title = "時尚追風人", objective = "帶著夸風，乘上巨龍風箏再次飛行。", description = "<夸風看著風箏，然後回頭看著你。牠再次看著風箏，然後謹慎地的用腦袋推了一下。牠慢慢地把目光移回你身上。>\n\n嗄啊。\n\n<該是再飛一次的時候了！>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50933] = {title = "一場不幸的事件", objective = "查明帝國守衛發生什麼事。", description = "你無法辨認出這具屍體究竟是誰，但是從身上的衣服看來，應該是祖達薩的帝國守衛。\n\n快速搜索這個地區之後，你找到一條血淋淋的足跡往西邊延伸過去。或許跟著前進就可以查明死因。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][50934] = {title = "偶然目擊", objective = "調查失蹤的贊達拉人。", description = "其中一位守備人員說，他在河流對岸看到一堆鮮血食人妖追著贊達拉人。\n\n他身上的穿著比較像你們這群人。為什麼你們這群人老是在這個地方碰上麻煩？\n\n我會在你的地圖上標出最後看到他的位置。別把一群鮮血食人妖引到這邊就好，行嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
