MultiLanguageQuestData['tw'][50960] = {title = "史威特的命令", objective = "把史威特的命令帶到佐司瓦交給露西爾‧威奎斯特。", description = "<有封信從船長的日誌露出了一角，上面有哈蘭‧史威特的印記。\n\n看樣子這些海盜是聽從史威特的命令，要進一步摧毀威奎斯特家族的勢力。\n\n一定要馬上告訴露西爾這件事！>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
