MultiLanguageQuestData['tw'][51071] = {title = "懸賞：刀齒獸女皇", objective = "殺死一隻刀齒獸女皇", description = "致所有尋求挑戰的勇者：\n\n去找出兇惡的刀齒獸女皇，然後殺掉牠。這是祖達薩最強壯、最兇殘的刀齒獸。\n\n在藤中村路邊到處可以發現虎群蹤跡。\n\n成功的人會獲得獎勵！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51072] = {title = "懸賞：捶拳猩猩首領", objective = "殺死捶拳猩猩首領", description = "致所有尋求挑戰的勇者：\n\n找到捶拳猩猩首領，想敗法擊敗牠。牠是野生猩猩中最巨大也最危險的一個。\n\n從藤中村一路過來都可以發現牠們的蹤跡。\n\n只要成功就能獲得獎勵！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
