MultiLanguageQuestData['tw'][51159] = {title = "拿出重砲", objective = "運送火砲。", description = "<這門火砲的狀況還不錯，可以提供強大火力來阻擋部落的進逼。\n\n把這個帶去艾克哈特小屋給莉亞‧瑪提諾，對他們的防禦很有幫助。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][51161] = {title = "懸賞：薩羅科", objective = "找到並殺死惡棍薩羅科。", description = "致任何擁有榮耀與銳利刀劍的人：\n\n找到並殺死小偷薩羅科。\n\n背叛流放者同夥的人沒有資格活下去。\n\n除掉他的人，會獲得應得的獎賞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51162] = {title = "懸賞：叛徒塔茲萊卡", objective = "找到並殺死叛徒塔茲萊卡。", description = "通告所有商隊和旅客：\n\n務必提防叛徒塔茲萊卡，這具骷髏會在贊姆蘭港附近道路上偷襲旅客。如果你非走那條路不可，動作加快、並避開任何廢墟。\n\n已經有好幾支商隊合力懸賞塔茲萊卡。\n\n想要領取賞金的人，請到末風營地尋找諾拉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51164] = {title = "懸賞：眼鏡蛇遠足參加者", objective = "殺死瑟瑞斯。", description = "金牙旅店的顧客請注意：\n\n我們很榮幸地宣佈，在我們的系列遠足活動中添增了一項新內容！\n\n全新的巨大致命、無人可擋殺手眼鏡蛇近距離體驗現正推出！\n\n這個活動無需登記，你們已經自動成為這項活動的志願者。\n\n如欲參與活動，只要前往旅店北邊的沙丘，並想辦法不被在當地徘徊的巨大眼鏡蛇咬死就好。\n\n目前我們尚未對本活動提供嚮導服務。祝您玩得愉快！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51165] = {title = "懸賞：維薩里克沙探", objective = "找到並殺死維薩里克沙探。", description = "致任何想讓無信者帝國滅亡的人：\n\n維薩里克沙探被人看見在東邊的沙丘中遊走。去集結戰鬥人員來打敗他吧！\n\n成功的人會收到應得的獎賞。", progress = nil, completion = "維薩里克的死對無信者勢力來說，無疑會個毀滅性的打擊。", rewards = "您會收到：\n\n艾澤萊晶岩"}
