MultiLanguageQuestData['tw'][51199] = {title = "狩獵榮耀", objective = "前往狐穴森林邊界和艾比‧瓦金斯見面。", description = "朋友，你來參加慶典嗎？\n\n我們還在準備，但狩獵早就該開始了！\n\n如果你想參加，到狐穴森林跟艾比見面。她會幫你準備的。\n\n狩獵愉快！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51200] = {title = "黑羊", objective = "找到並拯救米利。", description = "我知道，米利很少跟著大家一起行動。平常這樣不會有什麼問題。她跑開一會兒，去做自己想做的事，然後時間到了就回到羊群裡來。\n\n最近山丘一帶變得很危險，尤其是那一帶遊蕩的狼群和巨人…她已經好一段時間沒回來了，我很擔心她的安危。\n\n你可以幫我去找她嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51201] = {title = "食人妖說出的情報", objective = "和贊達拉食人妖俘虜說話，了解他們到底是怎麼弄沉聯盟艦隊的。", description = "<class>，你來的時機…真是剛好。我的船艦都被毀了，手下有半數的人都葬身海底，還活著的狀況也好不到哪去。簡單來說我們完蛋了。\n\n不過，聯盟不會就這樣倒下。\n\n這場災難是贊達拉食人妖造成的，在我們殺光他們、逃出這座被聖光遺棄的島嶼之前，要先知道他們到底做了什麼才行。", progress = nil, completion = "你說塔蘭姬…公主？好，我知道了。\n\n我們必須向烏瑞恩國王稟報才行。這位贊達拉公主很快就會知道，與聯盟為敵會是怎樣的下場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51203] = {title = "狼來了", objective = "殺掉10隻兇野利爪狼。", description = "那些狼最近對我的羊群下手。其實，要不是巨人來到這邊、迫使狼群離開原本的狩獵區，牠們也不至於造成多大的麻煩。\n\n實在很不好意思，不過可以請你稍微削減一下牠們的數量嗎？只要前來狩獵的狼數量變少，我們應該就可以喘口氣。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51204] = {title = "懸賞：利爪獸王", objective = "殺死利爪獸王。", description = "急需冒險者！\n\n狼群一直攻擊我的羊群！我沒有辦法反擊。\n\n我看到其中一隻塊頭特別大，率領了幾波襲擊。\n\n拜託，如果任何人能幫得上忙，只要能力所及，我願意支付任何報酬。\n\n- 牧羊人瑪麗‧安‧密爾布克您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51205] = {title = "啊啊，老鼠！", objective = "收集8頭污穢老鼠。", description = "我可不是為來這種事賣命的！我只想回去做一些單純的工作，像是磨小麥、喝蜜酒之類的。\n\n就像這邊的情況還不夠糟一樣，出現了一支老鼠大軍四處搜刮小屋，但是我不敢殺生。\n\n來，我最近在港口附近碰到一個瘋癲地精，這是從他那裡拿來的。我想這東西可能是用來驅蜂的，或許你可以用在老鼠身上試試？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51207] = {title = "炸巨人", objective = "以麵粉炸彈殺掉8個雙頭巨人。", description = "好了，這裡有個東西，是我用你帶回來的額外材料趕工製作的。\n\n這附近沒有什麼可以用來當武器的，不過火藥和麵粉倒是很多，可以用來做成超猛的炸藥！\n\n把這些好東西丟給噁心的雙頭巨人，應該可以擾亂他們好一陣子，夠讓你打爆他們的腦袋了！\n\n你是不是以為，我只是個烤餅乾招待路人的善良老婆婆？哈！我當年可是個火藥大師。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "語潮者輕鞋暗水裹足風暴追逐者護足驚懼海盜護足語潮者裹腕暗水裹腕風暴追逐者束腕驚懼海盜臂甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][51208] = {title = "穀物回收", objective = "收集10個穀物袋。", description = "糧倉老鼠肆虐，再加上巨人洗劫我們的貨物，我們的糧食告急。\n\n我在逃出來的過程中，看到毀壞的貨車周圍散落了一些裝著穀物的袋子。\n\n如果你能夠把東西帶回來，不管什麼都好，我都十分感激。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51209] = {title = "強大的果克菲斯", objective = "用一袋老鼠殺死果克菲斯。", description = "奶奶總是叫我堅強一點…我們最近實在過得太安逸了。\n\n聽說巨人很怕老鼠，所以我就想說…「嘿，查爾斯，有個很棒的主意：我們把$p抓來的老鼠放到雙頭巨人那邊試試看。」\n\n我想變得堅強一點，結果卻變成這樣。我被卡在這個地方，只能祈禱我不會被踩成肉餅。\n\n他們的老大就在那座山丘上。來，帶著這些老鼠去試試看，希望我的想法沒錯！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51210] = {title = "反擊圍兵", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51211] = {title = "艾澤拉斯之心", objective = "前往心之室，與艾澤拉斯對話。", description = "我們的世界正在步入死亡，<name>。薩格拉斯造成的傷害太過嚴重，她的傷痛使得元素生物逐漸陷入瘋狂！\n\n我可以聽見艾澤拉斯的聲音，但光憑代言者並救不了她。\n\n她需要她的勇士。\n\n在地底深處有個名叫心之室的泰坦遺址，我感應到她想在那裡與你對話。\n\n跟我一起進入那裡，那可能是我們唯一能救她的機會！", progress = nil, completion = "艾澤拉斯之心…那是治癒她的傷口的關鍵！", rewards = "您會收到：\n\n艾澤拉斯之心"}
MultiLanguageQuestData['tw'][51212] = {title = "威奎斯特莊園：古怪的廚房", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51213] = {title = "威奎斯特莊園：「巫」法原諒", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51214] = {title = "當個好心人", objective = "收集水桶、麵粉袋和木材，然後交給瑪莉‧達文波特。", description = "你一眼就能看到石頭從天上掉下來對吧？雙頭巨人正在圍攻我們！\n\n如果你能好心幫個忙，我會十分感激。我們得先幫你張羅好對抗他們的東西，否則我們沒有擊敗他們的可能。\n\n你可以去磨石村附近幫我找幾樣東西嗎？一點水，一袋麵粉和一捆木材應該就行。\n\n我已經派我孫子查爾斯去找其他東西，只不過他出去一段時間了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51215] = {title = "擠山羊奶", objective = "收集6份山羊奶。", description = "很不巧，密爾布克的羊群最近沒生產什麼東西。狼群聚集在那附近，那些可憐的東西一定嚇得半死。\n\n山丘上有野生山羊，而且牠們比綿羊更大膽。\n\n如果你找到幾頭年輕山羊，或許可以想辦法跟牠們討一點新鮮、美味的羊奶！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51216] = {title = "威奎斯特莊園：撲殺烏鴉", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51217] = {title = "懸賞：雅索剛", objective = "找到並殺死雅索剛。", description = "奉風暴守望的命令。\n\n找到並殺死外國間諜雅索剛。\n\n有個外國特務躲在我們的地盤，她要為危害斯陀頌恩人民的恐怖行動負責。\n\n剷除她的人會獲得應得的獎賞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51218] = {title = "未送達的包裹", objective = "把包裹交給瑪莉‧達文波特。", description = "<被洗劫的推車破爛不堪，只剩下一個包裹藏在打翻的穀物中，上面的收件人是磨石村的瑪莉‧達文波特。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51220] = {title = "深海風險", objective = "消滅6位海洋工匠", description = "雖然艾特文神通廣大，這風險投資公司對他來說依然是威脅。我需要你在前進的同時，照看艾特文以及托奇。\n\n解決這一路上潛伏在水裡的風險投資公司海洋工匠。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51221] = {title = "立即應變", objective = "除掉利希亞‧寇斯卡特", description = "時間很急迫，而且少了你的協助，會有更多生物就此死亡。風險投資公司準備了一台巨大的挖掘機，想要切開暗礁並毀掉這座洞穴。他們指派了一位特別技工，以確保這個工作能正確執行。\n\n你得馬上行動，$p。解決那個營地的技工，應該可以爭取一些時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51222] = {title = "你的就是我的", objective = "收集10枚水雷。", description = "我還記得在潘達利亞時，看到一位半丘居民把猴人的便便丟回去，擊敗了攻擊的猴人。\n\n猴人完全沒想過該如何面對自己的武器。我們可以在這裡應用類似的戰術。我們可以收集風險投資公司的水雷，用來對付入侵者。\n\n用你的鉤子綁住水雷，我和艾特文負責把它們拖上去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51223] = {title = "踏過碎玻璃", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51224] = {title = "利益與偵察", objective = "搭乘加里維克斯的戰鬥機動車護送加里維克斯和伊崔格。\n\n要是你跟加里維克斯和伊崔格走散了，可以回任行港找到他們。", description = "這本來應該是個秘密行動。但很不幸地，我們的貿易親王堅持要一起來…而且還乘坐對部落來說最吵、最顯眼的車輛。\n\n幸好你也和我一起來了，<name>。\n\n我們出發吧。我們對佐司瓦這個地方幾乎一無所知，該探查一下了。", progress = nil, completion = "總覺得這片森林有什麼地方不對勁。\n\n等等…那是什麼？！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51225] = {title = "信天翁發轟", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51226] = {title = "雙面夾擊", objective = "殺死8隻鹽牙尖角蜥。", description = "在海灘那邊的超大型尖角蜥突然成群闖入營地。\n\n我們通常每個星期都會對付一兩隻，但牠們現在好像整窩都爬上懸崖，不知道是不是被血的味道吸引過來的。\n\n這些尖角蜥會對我們剩下的人造成威脅，殺光牠們！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51228] = {title = "速食肉，可立即享用", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51229] = {title = "建立灘頭堡", objective = "在沃魯敦插上聯盟旌旗並架設你的基地。", description = "我不會讓李奧納德二等兵白白犧牲的。在那些塞斯拉克人回來之前，趕快派人去加強此地防禦工事吧。\n\n來，把這個旗幟插在顯眼的地方，船艦看到就知道這裡很安全。插在碼頭旁邊的平台應該就可以了。", progress = nil, completion = "船員設立營地的速度破了紀錄！你拿下灘頭陣地了，做得好。\n\n現在，來談談爾梅中士的事情...", rewards = nil}
MultiLanguageQuestData['tw'][51230] = {title = "緊急移植", objective = "把10顆河芽草種子種在河邊的泥地。", description = "河芽草是我們的珍貴資源。它不僅具備強大的魔法屬性，我們也用它來餵食訓練過的許多野獸，或是直接拿來食用。\n\n然而，鮮血食人妖一直在往河裡傾倒許多受詛咒的髒血。或許這不是他們的目的，但如果我們不趕快行動，這種汙染可能會讓所有河芽草滅絕。\n\n我需要你拿著把這把種子，種在河邊的泥地裡。做為回報，我會教你如何在採集這種草時更有效率。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：河芽草(等級2)"}
MultiLanguageQuestData['tw'][51231] = {title = "懼怕女巫", objective = "調查出現在前面的東西，並保護伊崔格和加里維克斯。", description = "你看到那個…在前面那團藤蔓裡的東西了嗎？那個是…<伊崔格顫抖著。>\n\n被裹在那棵樹裡的，是…哥布林嗎？", progress = nil, completion = "我就說這個地方不太對勁吧…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51232] = {title = "百位食人妖的抵抗", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51233] = {title = "希望山上沒有女巫", objective = "載伊崔格和加里維克斯到山上去。", description = "<加里維克斯在跟那個長者說過話以後，看起來有點慌張。>\n\n我說啊，呃…我在想我們最好去其他地方建立我們的根據地。或許，到山上碰碰運氣？反正，不要在這裡，不要在有女巫的地方好嗎？", progress = nil, completion = "這樣…應該就可以了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51234] = {title = "克拉佐法拉茲哨站", objective = "在克拉佐法拉茲哨站使用哥布林裝置，建立你在佐司瓦的根據地。", description = "我已經花了不少力氣，想辦法建立我們的根據地。我們現在該做的，就是把科技裝置都部署完畢，我們在佐司瓦這裡要做的事就大功告成了。\n\n你去把基地建置完成，我來看看能不能找到狼人機車的零件。", progress = nil, completion = "走吧，真是太好了。\n\n嘿，你看！有火箭兵來了！", rewards = "您會收到：\n\n"}
