MultiLanguageQuestData['tw'][51239] = {title = "不含說明書", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51240] = {title = "懸賞：錨面巨鯊", objective = "在任行港附近的海域殺死錨面巨鯊。", description = "殺了那條鯊魚，牠吞了我的腿！還有我的船員！還有我的船！連船錨都不放過！\n\n牠就在海裡到處游，尋找下一個目標。去把牠殺了。\n\n我把獎勵交給瑟希‧散砲，要是你辦到就把獎勵給你。\n\n<佈告上簽了「渣拴船長」的名字>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
