MultiLanguageQuestData['tw'][51331] = {title = "鑽地策略", objective = "在席帕拉的鑽地機裡，救出4位黑鐵碎地者。", description = "看來我們的行動被敵人料個正著。在我們發展精鍊艾澤萊晶岩的技術時，這些哥布林也在做一模一樣的事。\n\n我們才在這邊落腳不到五分鐘，那群部落就跑來干擾我們的行動。\n\n我們有幾位很重要的薩滿，就在那片海灘上的鑽地機裡等得不耐煩了。\n\n你拿著鑰匙去清條路出來，讓他們平安抵達。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51332] = {title = "橫越海洋的旅程", objective = "到祖達薩向貿易親王加里維克斯回報。", description = "我知道你想在佐司瓦建立我們的根據地，不過要完成這個任務，就需要貿易親王加里維克斯的幫助。\n\n我知道，這個人選讓人意外，不過我聽說佐司瓦有艾澤萊晶岩，而貿易親王很想找這些東西。", progress = nil, completion = "對了，&lt;name&gt;，你有沒有去過佐司瓦？\n\n我們接下來要去那裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51333] = {title = "起錨！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51335] = {title = "餅乾與奶", objective = "享受瑪莉的新鮮烘焙餅乾與牛奶。", description = "感謝你幫我們收集這些東西。\n\n我可不能讓你空著肚子去對付那些兇很的雙頭巨人。要不然，我跟那些可怕的怪物有什麼兩樣，對吧？\n\n$p，你可以休息一下，我趁這段時間幫你準備剛烤出來的餅乾，還有一點熱羊奶！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51339] = {title = "清理鷸鳥", objective = "清理8頭油膩膩的沙喙鷸鳥", description = "風險投資公司用有毒的油料污染了我們的純淨水源。\n\n我的人民夠強壯，他們會撐到時機成熟的時候，一舉反擊那些人。但是脆弱的嫩皮生物可熬不了。我們現在就得行動，才能解救牠們度過這場危機。\n\n看到任何油膩膩的沙喙鷸鳥就抓起來擦乾淨。動作快點，免得為時已晚。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "諾菈的披巾語潮者臂環暗水臂環風暴追逐者腕甲驚懼海盜腕甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][51340] = {title = "到佐司瓦！", objective = "與伊崔格和恐衛上將黛特賽爾交談。", description = "艾澤萊晶岩就在這裡了，<name>。你感覺到了嗎？\n\n佐司瓦 - 就在庫爾提拉斯 - 底下顯然有豐富的艾澤萊晶岩礦層。艾澤萊晶岩就代表財富，財富就代表贏得這場對聯盟的戰爭…這樣就能帶來更多財富。\n\n我們一定要拿到這些艾澤萊晶岩！\n\n去找伊崔格和黛特賽爾聊聊，這樣我們就能趕快出發。時間就是金錢！", progress = nil, completion = "我們到了。該是看看聯盟到底想做什麼的時候了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51341] = {title = "海洋之女", objective = "陪珍娜‧普勞德摩爾一起去見凱瑟琳‧普勞德摩爾。", description = "我們沒辦法更接近要塞了。接下來得從這邊走過去。\n\n回到波拉勒斯，就勾起我以為早就忘記的情感…時間就像潮水沖刷石子，撫平記憶的稜角。\n\n現在這一切都好痛。\n\n我不知道最後會是什麼結果…只知道，總得試試。", progress = nil, completion = "希望你有睡個好覺，你需要充足的力量。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51342] = {title = "激流堡之役", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51343] = {title = "游泳課程", objective = "收集三份卷軸。", description = "幾千年來，我們在艾澤拉斯的深處遊盪，但從未有陸地人與我們同行。為了協助我們，你必須學會像我們一樣在水域間跋涉。\n\n這三份海洋卷軸應該能賦予你足夠的能量，讓你像我們一樣在水下移動並存活。\n\n將協和魚鰭、無盡潮汐、以及優雅之息的卷軸帶來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51349] = {title = "榮譽束縛", objective = "在沃魯敦找到爾梅中士。", description = "爾梅中士是一個有榮譽心的人，他從不丟下自己人。不過這種責任感總有一天會害死他。\n\n我甚至不知道這座島上有什麼樣的威脅，但可以肯定沒有資源用來搜尋一個失蹤的海盜。\n\n我希望你去找到他，並用盡辦法讓這個笨蛋放棄他在做的蠢事，回到營地。最後有人看到他往東南方去了。我建議你從那邊開始找。", progress = nil, completion = "龍禍派你來找我，嗯？哼，他得再等一下了。\n\n這個玩意兒知道詹姆士二等兵被帶到哪裡去了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51350] = {title = "出乎意料的協助", objective = "在骨徑峽谷收集8個刺梨根。", description = "我在閃躲那些塞斯拉克人的時候，看到這傢伙被丟在路邊等死。我覺得他跟其他傢伙不太一樣，因為他看起來被操得相當慘。\n\n在他昏過去之前我們有講過幾句話，他說他知道我們的人被帶去什麼地方！\n\n我們得查明這傢伙知道什麼！\n\n我需要幫這些傷口調製一些藥膏，我在附近看到一些仙人掌，應該可以當做不錯的藥引。", progress = "找到藥膏所需的仙人掌了嗎？", completion = "這些應該會管用！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51351] = {title = "有毒尖刺", objective = "在骨徑峽谷收集8根鹽脊尖刺。", description = "我很驚訝這蛇人竟然還活著。讓我們單獨談談。看看這個！\n\n<爾梅拿著一根針狀的尖刺。>\n\n看起來這是來自於峽谷底部那些到處晃來晃去的巨大昆蟲。我用我的臂章打賭，這玩意有毒。\n\n你知道他們怎麼說的，能殺人的也能救人。\n\n去多找一些這種尖刺，我想如果我可以把這跟他要的仙人掌混合，我們可以做出很好的抗毒血清來治療他的傷。", progress = "幫我弄到尖刺了嗎？", completion = "就是這個沒錯！希望你沒被扎得太兇。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51352] = {title = "不要玩火", objective = "消滅10位風險投資公司縱火狂和2位風險投資公司油料工。", description = "這些風險投資公司的惡棍點燃了他們採收而來的油料，想要把我們趕出這塊土地。\n\n他們的計畫有個弱點。如果巨浪弄熄了每一根火把，他們的油料就點不著了。你可以成為我們的巨浪！\n\n熄滅此地的所有火焰，我們就能打贏這一場仗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51353] = {title = "艾特文的洞穴", objective = "到艾特文的洞穴尋找羅洛賈。", description = "托奇已經研究出一個戰術，聽起來非常復古。不過想要擊敗風險投資公司，我們得從寧靜之水的泡沫中喚醒艾特文。\n\n到艾特文的洞穴尋找羅洛賈，我們就可以開始了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51355] = {title = "超級秘密魚", objective = "把這條魚帶給機械岡的丹妮爾‧垂釣。\n\n已提供物品：\n", description = "<機械岡的丹妮爾‧垂釣可能會對這條魚有興趣。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘魚餌"}
MultiLanguageQuestData['tw'][51356] = {title = "懸賞：女巫莉莉雅絲", objective = "在寇連恩從女巫莉莉雅絲身上取得女巫莉莉雅絲的頭。", description = "威奎斯特守衛需要一個身強體健的人幫忙消滅寇連恩的威脅。\n\n他們要抓一個名叫莉莉雅絲的女巫，她虐殺了許多鎮民。殺了她，就是為整個佐司瓦帶來福祉。\n\n把她的頭帶過來，你就可以得到獎勵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51357] = {title = "整裝待發", objective = "為妮莎挑選一把武器。", description = "塞斯拉克沒有馬上殺掉你，表示你一定很特別。\n\n又或者你在奴隸市場能賣好價錢。\n\n不過別擔心，我們會離開這裡。\n\n我在入口處有一輛貨車，但沒有武器可供戰鬥。\n\n幸好，塞斯拉克似乎有不少武器。", progress = nil, completion = "用他們的武器來對付他們。我喜歡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51358] = {title = "懸賞：獅鷲獸小偷", objective = "殺死掠取者林德爾和無聲的波里斯。", description = "警告所有獅鷲獸主人！\n\n千萬別讓獅鷲獸離開視線，我們已接獲數起獅鷲獸在夜間失竊的案例。\n\n如果有人可以捕緝竊賊，將可獲得豐厚獎勵！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51359] = {title = "火源之界碎片", objective = "讓不穩定的熔岩穩定後，再用熔岩元素擊敗200位污水哥布林。", description = "和你有關的傳言似乎被吹捧上天了，但看來你還蠻能幹的，沒錯吧？\n\n我低估了你，<name>。在這方面，我道歉，但別告訴塞林。\n\n現在儀式所需的元件都準備好了。你只需要把火源之界溶渣加進不穩定的熔岩裡，就會有位火源之界的巨大生物聽從我們的號令。\n\n你可以控制它，在近乎無敵的前提下消滅附近哥布林威脅。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51360] = {title = "巨大的錨草豆莢", objective = "將巨大的錨草豆莢拿給迪卡蘭‧辛諾。\n\n已提供物品：\n", description = "從你收集過的植物來看，你從來沒碰過這種尺寸的錨草豆莢。不管它基於什麼樣的理由變得這麼大顆，一定可以從中學到不少知識。\n\n你的思緒飛回迪卡蘭那邊，想要回憶你之前看過的書本中，有沒有任何蛛絲馬絲。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51361] = {title = "更多錨草豆莢", objective = "從錨草上採集9枚成熟的錨草豆莢。", description = "庫爾提拉斯的每個人都知道錨草是商人帶來的壞東西。\n\n它在這種環境下長得很好，並開始從其他植物上吸取養分，所以我們得努力阻止它四處蔓生；但是它也具有強大的魔法精華，所以無法將它根除。\n\n不過，如果它產生變種並開始散播更多種子，我們可能需要全面清除它。\n\n去把最大的豆莢拿來，我們得看看這是不是單一突變。我會對這顆進行解剖，看看能有什麼發現。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：錨草(等級3)"}
MultiLanguageQuestData['tw'][51364] = {title = "炸出逃生路", objective = "找到妮莎的貨車並搭乘它到安全地帶。", description = "好吧，$p。我想我們該腳底抹油了。\n\n希望我的貨車還在附近。\n\n我會駕車前往藏身處，我要你把炸藥丟向任何膽敢尾隨我們的塞斯拉克。", progress = nil, completion = "這就是和你一塊飛進來的食人妖，對吧？至少，她現在還活著。", rewards = "沙術者的傳導彎刀獠牙呼喚者的法杖塞斯拉克衛兵法杖沙地斥候波刃劍塞斯拉克沙地斥候之弓塞斯拉克戰爭使者彎刀塞斯拉克劫毀者之爪塞斯拉克侵略者彎刀塞斯拉克衛兵彎刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][51365] = {title = "文化意義", objective = "向波拉勒斯的人們學習海莖草的重要性。", description = "我注意到你採集植物的技巧進步了，但我也注意到你只把每朵花朵和葉子當成物品看待。這些島嶼的花卉有豐富的歷史，對我們有很大的文化意義。\n\n把這個海莖草拿去，到鎮上去走一遭，問問鎮上的男女這株草對他們有什麼意義。遷就我一下，我不會浪費你的時間的。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：海莖草(等級2)"}
MultiLanguageQuestData['tw'][51366] = {title = "使用解毒藥膏", objective = "在瓦里克身上施用解毒藥膏。", description = "解毒藥準備好了。\n\n它聞起來有種死亡的味道，而且嚐起來更可怕，但是它的後勁應該夠力，希望我們還來得及讓它發揮作用。\n\n來，把這些藥膏塗在他的傷口上，應該會馬上生效。", progress = nil, completion = "我可以感受到生命重新注入我的肢體。多謝你，陌生人！\n\n恐怕我們沒有時間進一步自我介紹，你的朋友被無信者抓走了！\n\n別擔心，我的人民會很樂意協助你，以報答你的好心腸。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51367] = {title = "懸賞：狂暴的大地守衛", objective = "在諾爾威頓莊園西側殺死狂暴的大地守衛。", description = "去釣點時要特別小心！\n\n有座山丘上出現了巨大無比的大地生物，威脅所有靠近的人。\n\n任何冒險者只要能解決這個大地守衛，即可獲得豐富獎勵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51368] = {title = "懸賞：巨大黃蜂", objective = "殺死巨大黃蜂.。", description = "我受夠了，我要懸賞那隻混帳黃蜂。\n\n每當我想用老方法空手釣魚，那個山裡的王八蛋就來找我麻煩。\n\n無論是誰快點解決那隻蟲！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51369] = {title = "異地之友", objective = "飛往虔信者聖所。", description = "我看過一個像你朋友那樣的生物，我們被我那群無情同胞「無信者」抓了起來。\n\n在我被丟在路邊之前，我給了他一件貴重物品，要他好好保護。所以我當然也希望你的朋友能平安歸來。\n\n我的人民將會為你提供協助。來吧，我來呼叫翼手龍載我們一程。合力之下，我們應該可以查明你的士兵朋友被帶到什麼地方去了。", progress = nil, completion = "噢，糟糕！無信者在攻擊神殿！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51370] = {title = "物資短缺獎勵", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n受戰火摧殘的合作背包"}
MultiLanguageQuestData['tw'][51371] = {title = "喜歡的供品", objective = "收集50份海草。", description = "艾特文在墨黑洞窟的大淨化時救了許多托爾托人。為了感謝他的英勇行為，我們讓他在這裡的寧靜水泡中歇息。如果要慫恿他重回我們的世界，就需要一個能取悅他的供品。\n\n生長在外面的海草是艾特文最喜歡的餐點。它的鹹味一定會吸引艾特文離開氣泡，進入我們的世界。你可以從洞窟外面的生物身上、或是到生長繁茂的珊瑚上收集海草。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
