MultiLanguageQuestData['tw'][51418] = {title = "席帕拉", objective = "在塔蘭姬的責難搭乘小艇，前往席帕拉。", description = "<name>！這邊狀態怎樣？\n\n哇喔，到處都是部落士兵，還有贊達拉食人妖，幾乎一台機器都沒有啊。\n\n看狀況，現在該做的是和黑鐵矮人一起撤回席帕拉了。把據點建在那邊再適合不過了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51421] = {title = "別想嚇唬老子", objective = "陪伴暗影獵手泰巾前往提拉加德海灣。", description = "看起來我們當地的暗影獵手成功拿到一艘小型海盜單桅帆船。\n\n我們派他去提拉加德海灣尋找據點，看起來他想出了一個計畫。\n\n泰巾需要你的幫助，是私事。別讓他等太久。", progress = nil, completion = "歡迎來到提拉加德，老大。你準備開始會談了嗎？", rewards = "您會收到：\n\n"}
