MultiLanguageQuestData['tw'][51435] = {title = "神氣活現時尚風", objective = "從一箱海盜裝束中，披上海盜偽裝。", description = "事情一件一件來，老大。除非你穿上合適的服裝，否則別想和海盜交涉。\n\n我也不是什麼時尚專家，不過我看得出來你現在穿的那套衣服就是不管用。\n\n算你幸運，我收集了一整箱的海盜服裝。不要問怎麼來的。只是想增添點海盜品味。", progress = nil, completion = "這才像話嘛，老大！你看起來就像個私掠老手！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51436] = {title = "與海盜交涉", objective = "跟著暗影獵手泰巾並和大副歐雯斯見面。", description = "其中有些海盜看不慣這裡的領導風範。\n\n我曾經耳聞他們是最後、真正自由的海盜。其他人不過是為一個叫艾胥凡的女士賣命。\n\n這點我倒不是很在乎，但是這些霧帆掠劫者的船長似乎也想為她賣命。\n\n我們得出點力阻止這件事，成功的回報就是能在這邊建立一個據點。", progress = nil, completion = "我不在乎你們陣營之間的戰爭，&lt;name&gt;。只要你願意拯救我的船員，我之後一定會鼎力相助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51437] = {title = "偷偷加料", objective = "刺穿6個烈酒桶。", description = "引發叛變的第一步是什麼？就是讓上頭看起來毫無領導能力。\n\n既然船長打算把我們的靈魂賣給艾胥凡，那我們也只好來點下三濫的手段。\n\n我很不想這麼說…但我們得銷毀那些酒。\n\n接下來只要一轉眼，船員就會對船長火冒三丈了。", progress = nil, completion = "那才不是我…\n\n你知道嗎？管用了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51438] = {title = "標記我們的領土", objective = "在劫掠港插上部落旌旗。", description = "這裡會是一個像樣的據點，老大！\n\n我會幫忙建設，把這地方變成一座好基地。\n\n我想我們需要一點鼓舞。\n\n我們正式開始吧。", progress = nil, completion = "這個地方很快就會有家的感覺了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51439] = {title = "收集砲彈", objective = "從霧帆砲手那裡取得3顆霧帆砲彈。", description = "老大，剛剛經過港口的時候，我想到一個點子。\n\n你有看到那些砲彈旁邊的大個子嗎？\n\n弄些彈藥，把它們帶來給我，應該會派上用場。", progress = "你有砲彈嗎？", completion = "哥布林們會愛死這個，老兄。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51440] = {title = "風向的改變", objective = "把這些捏造的命令送給船務長泰琳、軍需官基利安和領航員斯維應克。", description = "<name>，異議的耳語已經傳遍港口。\n\n到處都有不想放棄自由的海盜在發牢騷！\n\n有謠言說有些當權人士和我互通款曲。\n\n我捏造了一些給船長的信件，把信送出去…看看誰會上鉤。\n\n或者，看看誰會來阻擾我們。", progress = nil, completion = "我也希望泰琳能發現真相。啊，反正也無所謂了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51441] = {title = "爆掉囉！", objective = "使用哥布林工程學攜帶型火砲擊沉3艘霧帆小艇。", description = "我們的哥布林工程師一直在努力調整一些火砲供我們使用。\n\n對他們來說，你收回來的那些砲彈是最完美的彈藥。\n\n在那座港灣裡的小艇，正準備把戰利品送到歐雯斯的敵人手中。用這門火砲擊沉它們，讓他們無路可逃！", progress = nil, completion = "現在我們要有場自己的判亂了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51442] = {title = "現在我是船長了", objective = "殺死瑞尼克船長。", description = "好吧，<name>…該把船長捲入這場叛亂了。\n\n瑞尼克坐在他的山洞裡，準備把我們的靈魂出賣給艾胥凡。\n\n擊敗他，我就讓你把我的港口當作你自己的使用。", progress = nil, completion = "歐雯斯船長…\n\n這裡有一個很明顯的圈圈，你不覺得嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51443] = {title = "決戰艾澤拉斯：任務聲明", objective = "在奧格瑪從大酋長希瓦娜斯‧風行者手中接獲你的任務。", description = "<name>！大酋長召喚你去執行一項極度機密的任務。\n\n部落的未來危在旦夕。", progress = nil, completion = "黑暗女王對我們無比信任。我們不會讓她失望，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51444] = {title = "艾澤萊晶岩強化", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51445] = {title = "瑟洛斯，荒疫之原", objective = "在瑟洛斯，荒疫之原找到珍娜。", description = "荒疫之原…\n\n如果傳說屬實，那我們會在裡面看到前所未有的苦難與折磨…\n\n…但如果我非得忍受這一切才能挽救我犯下的過錯，那我將會欣然接受。\n\n你願意一塊來嗎，<class>？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51446] = {title = "認識甜花", objective = "在佐司瓦找到薰薰‧甜花。", description = "你已經從這些島嶼上見證並學習了許多知識，但贊達拉不是你能學習的唯一地方。我聽說過一種沒辦法在這些島嶼生長的花，\n\n如果你想要進一步瞭解它，你需要去找比我更有知識的人。你很幸運，我知道有人或許可以教你。\n\n她的名字是薰薰‧甜花，我上次聽說她在人類島嶼佐司瓦的任行港近郊開了一間店。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51447] = {title = "芳香花粉", objective = "把被花粉包裹的黃蜂拿給賈登‧弗拉。\n\n已提供物品：\n", description = "收集花粉時，你找到一隻被花粉包覆的死黃蜂。你知道這個小傢伙藏有秘密，能讓採集花粉更有效率，但你卻想不出答案。\n\n或許你問問賈登，他會有些想法。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51448] = {title = "向高手學習", objective = "喝下賈登的藥水，讓黃蜂開始採收你的花粉。", description = "你想知道這些黃蜂為什麼這麼擅長採集花粉，但只要你一踏進它們的領地，它們就會開始採取防禦行為。這是個問題，不過我有個解決辦法。\n\n拿著這罐藥水，到沃魯敦的刺針林地把藥水喝了，你就會變成植物。\n\n計畫是這樣子：你去外面把藥水喝了，親眼看到黃蜂工作的樣子。等藥效退了之後，回來告訴我你觀察到什麼。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：海妖花粉(等級2)"}
MultiLanguageQuestData['tw'][51450] = {title = "開採艾澤萊晶岩", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51451] = {title = "黏稠噁心的花朵", objective = "把黏稠噁心的花朵拿給賈登‧弗拉。\n\n已提供物品：\n", description = "你用黃蜂學來的採集方法，像平常一樣翻找著花粉。然而，當你把手從花朵上拿開時，卻沒發現任何花粉。\n\n當你朝往花瓣圍成的圓圈內部探頭時，雖然這朵花已經成熟了，卻一粒花粉都沒看到。在仔細觀察之下，你發現花朵充滿了黏稠的液體。這會是花朵產生的物質嗎？\n\n雖然觸感很噁心，你還是小心地拔起花朵準備帶去給賈登。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][51452] = {title = "花粉衝擊", objective = "收集12捧濕花粉。", description = "看來是某種野獸成功用舌頭把花粉舔食掉了。雖然我很好奇是什麼生物做了這樣的事情，但我想那不重要。\n\n你應該可以做到這種方法，用不到什麼稀有又危險的材料。\n\n下次你找到一朵海妖之棘時，弄濕你的手套讓花粉黏在上面。水、酒、血…應該都管用。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：海妖花粉(等級3)"}
