MultiLanguageQuestData['tw'][51513] = {title = "札拉贊恩的回歸", objective = "到回音群島去找加德林大師。", description = "<name>，我從來沒有像今天這麼迫切需要你的協助。我的家園被攻擊了。\n\n我自己也才剛剛得知。加德林大師正在求援，札拉贊恩，我們暗矛的古老敵人回到了回音群島，而且帶了一支不死軍隊回來。\n\n札拉贊恩曾經殺死許多暗矛子民並褻瀆他們的靈魂。你願不願和和我一塊去打倒這個叛徒？我們可以搭乘從贊達拉港出發的船。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51514] = {title = "破碎交易", objective = "在暗矛島上消滅20個無腦的食人妖。", description = "這些沒有思想的不死生物就是一直冒出來。比起上一次札拉贊恩帶來的威脅，這次他們簡直是強得離譜。\n\n拜託你，幫我們驅逐這些不死怪物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51515] = {title = "為沃金復仇", objective = "摧毀札拉贊恩。", description = "如果我們真的想要摧毀札拉贊恩，我們就需要某種能破壞靈魂的東西。\n\n那把沃金的戰刃有可能辦到這一點。\n\n打從好幾年之前，札拉贊恩就在他倒下的地方徘徊。洛克漢和塔蘭姬已經前去面對他了。\n\n去吧，殺死札拉贊恩，並在它脫逃之前將戰刃插進他的靈魂之中。讓我們期望沃金的交易具有足夠力量，毀掉那個敵人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51516] = {title = "阿塔達薩：大酋長的骨灰", objective = "帶著沃金的骨灰前往阿塔達薩。", description = "我最近從暗矛部族身上學到了許多事。事實上，在我小時候聽到沃金蔑視祖爾的魯莽命令的故事後，我就一直很仰慕他們。\n\n沃金原本是部落大酋長，暗矛的領導者，而且成就遠超過大多數的食人妖。\n\n他的骨灰應該以國王的身分加以榮耀。\n\n帶著我的祝福，把這份骨灰送到阿塔達薩，並讓應有的榮耀加諸在你們的前任大酋長身上。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][51517] = {title = "你欠我一條靈魂", objective = "帶著沃金的骨灰甕到納茲米爾去找伯昂撒姆第。\n\n已提供物品：\n", description = "你不能把那東西留在這裡。\n\n老沃金並沒有在我的屋簷下跳舞，而我已經好一陣子沒看到他的靈魂了。\n\n它的失蹤，讓我用來困住札拉贊恩的束縛因此破碎。\n\n所以…我要你舉著那個沉重的大甕，然後帶著它進入我的亡域。\n\n沃金得在我的地盤上和我面對面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51518] = {title = "迷失的靈魂", objective = "在贊達拉港與塔蘭姬公主談話。", description = "我們該談談老沃金消失的靈魂了。\n\n這不是單純的交易或人生儀式，靈魂可不會無故消失。\n\n有一些朋友可以幫你追尋沃金的靈魂，沃金生前的朋友應該有足夠力量找到死後的他。就算不行，塔蘭姬一定幫得上忙。 \n\n前往塔蘭姬停在贊達拉港的船艦，就是你前來此地時所搭的那艘船。你可能需要玩點招魂的伎倆。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51519] = {title = "靈魂的呼喚", objective = "觀看塔蘭姬的儀式。", description = "要辦到這件事，我們必須觸及遙遠的暗影之境。如果連伯昂撒姆第都看不到沃金所在之處，那他可能是迷失在某處，或是躲了起來。\n\n不論如何，我只能期望在此地集結的暗矛子民，和他之間分享的束縛能引導他出現在我們面前。\n\n密切注意，在儀式開始之後不要讓它中斷。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51520] = {title = "亡者的正義", objective = "讓沃金的戰刃從古翰屍體吸取鮮血。", description = "為了失去羅亞的兒女們，為了贊達拉之心，一定要殺死古翰，並向所有必要之人展示他死亡證據，才能夠伸張正義。\n\n帶著我的戰刃，刺入那頭野獸的屍體，並讓塔蘭姬展現在她的人民眼前。\n\n讓和平從贊達拉人的心中開始萌芽。", progress = "瘋狂與黑暗，現在已經移到了彼界。痛苦之鉅，堪稱宏大。", completion = "在數不清的世代中，食人妖一直受到這個敵人的威脅。我們或許不清楚他的名字，但我們都感受到他的詛咒。\n\n今天，你為上千世代的食人妖伸張了正義。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51521] = {title = "贊達拉的真正領袖", objective = "和塔蘭姬一塊把沃金的戰刃呈獻在贊達拉人民面前。", description = "現在，帶著我的戰刃與塔蘭姬同行。讓她把你的勝利展現在人民面前。讓食人妖知道正義為何物，並瞭解領袖的力量。", progress = nil, completion = "即使塔蘭姬仍有所存疑，但她就是贊達拉的真正領袖。在引導之下，她會讓她父親的統治相形失色。\n\n至於現在，你獲得了我的感謝。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][51526] = {title = "酋長的命令", objective = "向祖達薩的高階督軍克洛姆什報到。", description = "我們在庫爾提拉斯的最佳戰略重地是戰牙堡，絕對不能淪陷！\n\n大酋長已經派了高階督軍克洛姆什來負責我方增援部隊，我命令你以最快的速度向他報到。", progress = nil, completion = "快點準備好，&lt;name&gt;。我們有場仗要打。", rewards = "您會收到：\n\n"}
