MultiLanguageQuestData['tw'][52014] = {title = "儀式的準備", objective = "開採未聖化的風暴白銀礦石，將它融鑄成未聖化的風暴白銀條，並讓它們接受詠潮者德贊的祝福。", description = "有人向我要一批風暴白銀。那是種很棒的金屬，質輕而且抗腐蝕。我們所有船隻都會用到它。它十分堅硬，連納迦都拿來製作武器的部件！\n\n不過，用在船上的每一塊零件都需要受到詠潮者的祝福。我可不會為這種胡扯八道的說法左右。我才不相信它需要什麼額外祝福，但我哪知道？\n\n幫我採集滿滿一桶風暴白銀並讓它接受祝福，我就教你更輕鬆的開採方式。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：風暴白銀礦床(等級2)"}
MultiLanguageQuestData['tw'][52015] = {title = "海水中的正義", objective = "收集100根被偷走的風暴白銀碇。", description = "<name>，我剛剛接到一個消息，我們有艘船遭到攻擊，有一整批風暴白銀被偷了！\n\n那種神聖的材料無可取代。一旦它受過詠潮者的祝福，就得埋藏在水下一年之久！雖然我對這種胡說八道不以為意，其他人可不這樣想，也會因此不讓那艘船出海。\n\n據我所知，一群納迦尾隨了那艘船艦，查看金屬埋在海床的什麼地方，然後殺死船員，搶奪貨物。\n\n殺死那些納迦，幫我把金屬拿回來！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：風暴白銀礦床(等級3)"}
MultiLanguageQuestData['tw'][52016] = {title = "酩酊大醉", objective = "幫醉鬼比魯帶些他喜歡的酒，習得他的採礦知識。", description = "你想要進一步了解風暴白銀？\n\n很好，如果你在開採礦層時犯了錯，你可能會敲出一陣致命的金屬粉塵煙霧。你可以滾了。\n\n<過了一陣子，瑟考特的表情和緩許多。>\n\n我很忙，如果你真的不想死的話，應該跟我之前的學徒比魯談談。他常在「靈魂與你同在」旅店裡爛醉如泥，但他還是有點料的。\n\n跟旅店老闆席莫談談，請比魯喝杯酒。如果他喜歡那杯酒，就會開口。如果不喜歡…希望你身上的錢夠多，多請幾杯就對了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：風暴白銀礦層(等級2)"}
MultiLanguageQuestData['tw'][52017] = {title = "回去找比魯", objective = "和醉鬼比魯談談。", description = "噢，你還在這裡啊？\n\n這個嘛，我是很想幫你啦，但身為全城唯一的金匠，我實在是忙得不可開交。\n\n我聽說你跟比魯相處融洽。如果你還想學習更多知識的話，我很確定他記得更多技巧。\n\n問問他能不能再教你幾招。告訴他，如果他能讓你今天之內不再跑來煩我，我就不會再把笨蛋礦工派去他那邊。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][52023] = {title = "通知部落", objective = "與貝恩‧血蹄談話。", description = "賈克拉傑將軍被擊敗了，但是，儘管我們極力阻止，他的計畫還是得逞了，成功召喚出謎思拉克斯。\n\n若不是瑟沙利斯的垂憐，我們可能無法活著離開阿圖亞曼。\n\n我們必須告訴盟友在沃魯敦發生的事。\n\n我會親自晉見塔蘭姬公主，你負責回去通知部落。我們需要集結每一份力量。\n\n總有一天我們會再相逢的，<name>。很榮幸能與你並肩作戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52024] = {title = "通知部落", objective = "與貝恩‧血蹄談話。賈克拉傑將軍被擊敗了，但是，儘管我們極力阻止，他的計畫還是得逞了，成功召喚出謎思拉克斯。\n\n若不是瑟沙利斯的垂憐，我們可能無法活著離開阿圖亞曼。\n\n我們必須告訴盟友在沃魯敦發生的事。\n\n我會親自晉見塔蘭姬公主，你負責回去通知部落。我們需要集結每一份力量。\n\n總有一天我們會再相逢的，<name>。很榮幸能與你並肩作戰。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "賈克拉傑將軍被擊敗了，但是，儘管我們極力阻止，他的計畫還是得逞了，成功召喚出謎思拉克斯。\n\n若不是瑟沙利斯的垂憐，我們可能無法活著離開阿圖亞曼。\n\n我們必須告訴盟友在沃魯敦發生的事。\n\n我會親自晉見塔蘭姬公主，你負責回去通知部落。我們需要集結每一份力量。\n\n總有一天我們會再相逢的，<name>。很榮幸能與你並肩作戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52026] = {title = "越洋暗殺", objective = "和傑塔瑞斯上將談話，出航前往沃魯敦。", description = "<name>，準備好要出擊了嗎？\n\n馬迪亞斯‧肖爾正在匯整一長串需要優先攻擊的部落目標，排行第一的是個很有影響力的血精靈，名叫阿列薩爾‧日衛者。情報指出他是聖匣守護者位階最高的成員，是挖掘部隊的血精靈精英。\n\n他就站在沃魯敦沙漠中心的顯眼之處，好像在求人來暗殺他一樣。我們動手吧？", progress = nil, completion = "我們到了，開始吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52027] = {title = "沃魯敦計畫", objective = "與海弗德‧龍禍和珊蒂斯‧羽月討論戰術。", description = "我們的目標：阿列薩爾‧日衛者，他是聖匣守護者的高階審查員。\n\n不過，在我們盲目衝進沙丘之前，我想請你和其他人參加一場簡短的戰術會議。", progress = nil, completion = "我很欣賞珊蒂斯的…率直。\n\n我們兩個計畫同時進行。走吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52028] = {title = "徹查沙漠", objective = "在沃魯敦搜尋部落的舉動。", description = "那麼，可以開始行動了。\n\n我跟你走，<name>。留意部落的舉動。", progress = nil, completion = "我覺得她還沒發現我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52029] = {title = "骯髒工作", objective = "殺死娜絲萊拉，查明她知道些什麼。", description = "那個調查員穿著聖匣守護者的外袍。日衛者一定是雇用哥布林來處理骯髒的工作，才能躺在陰影下面悠閒。\n\n<珊蒂斯把一根箭搭上弦。>\n\n我們來看看她知道些什麼。", progress = "那個哥布林打算做什麼？", completion = "&lt;海弗德在閱讀你取得的聖匣守護者文件。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52030] = {title = "繼續搜查", objective = "尋找部落的蹤跡。", description = "古茲柏得花點時間來安置炸藥。我們先繼續向南走，尋找部落的其他活動跡象。", progress = nil, completion = "在上面，廢墟旁邊。你看到他們了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52031] = {title = "聖匣守護者的經典惡行", objective = "協助珊蒂斯刺殺艾莉莎‧帷歌和達克斯‧砲手，並且查明他們知道些什麼。", description = "又是哥布林調查員，而且這個正在向某位血精靈監督者之類的人士回報。我們逐步接近他們了，<name>。\n\n你很清楚該怎麼做。", progress = "日衛者馬上會落入我們手中。", completion = "一張地圖！太棒了。這應該可以為我們提供必要資訊…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52032] = {title = "絕不中止搜查", objective = "繼續尋找部落的蹤跡。", description = "<海弗德看了地圖最後一眼，然後把它摺了起來。>\n\n那麼就向南走。", progress = nil, completion = "我們在此地掌握到一個好機會，&lt;name&gt;。如果沒好好把握的話，那就實在太可惜。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52033] = {title = "懸賞：霜寒獵母", objective = "消滅高徑之路附近的霜寒獵母。", description = "如果有人能追蹤並消滅在高徑之路出沒的霜寒獵母，威奎斯特守衛願意提供獎勵。\n\n追蹤她的時候務必謹慎。她是一頭兇殘無比的野獸，最著名的本領就是伏擊經驗老到的獵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][52034] = {title = "給贊達拉的訊息", objective = "殺死12名贊達拉流放者。", description = "我知道我們來這邊是為了獵殺部落，不過這是一個機會。\n\n就算他們沒有遭到放逐，這些可是贊達拉食人妖，贊達拉人幾乎都在和部落打好關係。\n\n為他們示範一下，我們會如何款待部落的朋友。", progress = nil, completion = "希望你有留幾個活口。\n\n這樣其他人才會知道要害怕我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52035] = {title = "臨時起意", objective = "收集15個贊達拉水罐和15份贊達拉口糧。", description = "我們整架旋翼機的儲存空間都用來存放炸彈。事實上，裡面還留下不少炸彈。不幸的是，那表示我們沒辦法攜帶維生所需的飲水和口糧。\n\n沙漠的居民貯藏補給品的方式相當有效率。我相信前面那些贊達拉食人妖，就算少了幾箱補給品也不會在意。", progress = "<海弗德對你堅決地點了點頭。>", completion = "出色的偵察行動。做得好。\n\n&lt;海弗德動手把飲水和口糧分給隊伍中的其他人。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52036] = {title = "他們有羊駝", objective = "使用超安全電擊羊駝套索以抓回一頭迷路的羊駝，然後將牠帶回去給爆破工程師戰絲。", description = "你看到了嗎？你看到了嗎？那些毛茸茸的羊駝？！\n\n我一直都想要一頭…我是說，啊，嗯咳咳！我想要取得一頭羊駝，作為研究之用。這是基於科學理由，和毛茸茸完全沒關係。\n\n拿著，用這個東西應該可以讓你套一頭回來。", progress = nil, completion = "真是太可愛了。看看她！\n\n看‧看‧她。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52038] = {title = "分頭行事", objective = "繼續往西南方前進，跨越沙漠。", description = "<海弗德再次低頭看著地圖。>\n\n聖匣守護者最後一座挖掘場位於此地的西南方。\n\n<name>，你和珊蒂斯負責在挖掘場安置炸藥。我會和戰絲一塊建立一個安全引爆場所。", progress = nil, completion = "&lt;珊蒂斯舔了舔嘴唇，滿臉期待的模樣。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52039] = {title = "延遲死亡", objective = "埋設8枚死亡遙控炸彈。", description = "光靠我們就能辦好這件暗殺工作，不過我想順便在敵人的挖掘場附近安裝些地精炸彈也無傷大雅。\n\n這些炸彈可以遠端引爆，所以盡量埋在沙中，這樣才不會引人注目。", progress = nil, completion = "完成了？很好。那走吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52040] = {title = "箭矢滿載", objective = "和珊蒂斯一塊獵殺阿列薩爾‧日衛者。", description = "用不到海弗德那過度複雜的沙漠爆破行動。我們可以從這邊動手，馬上解決掉阿列薩爾‧日衛者。\n\n他就在那邊。我們可以就這樣…宰掉他。\n\n你去吸引他的注意。我會在他最沒防備的時候出手。你準備好了嗎？", progress = nil, completion = "如果海弗德發現我們幫他完成了工作，他會不會不開心？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52041] = {title = "向龍禍回報", objective = "在沃魯敦向海弗德‧龍禍報到。", description = "我們在此地的工作完成了。海弗德和戰絲應該在下面更遠的海岸，往東走。\n\n如果你不介意的話，我們那邊見。", progress = nil, completion = "阿列薩爾死了？\n\n我想那是好事…只不過這讓我的計畫少了一點樂趣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52042] = {title = "大爆炸", objective = "和爆破工程師戰絲交談，啟動沃魯敦爆炸裝置。", description = "不過，我們已經安置好所有炸藥，而且沒有任何事物可以阻擾我們進行引爆，讓部落的挖掘場化為廢土。\n\n在你準備好之後和戰絲交談，我們就可以讓這爆炸性地精科技發揮它的作用！", progress = nil, completion = "哈哈！那應該可以把聖匣守護者的進度炸回幾個月之前。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52043] = {title = "葡萄的憤怒", objective = "帶一瓶醃菜汁、一座培根山、一堆香腸，還有堆成山的蛋給醉鬼比魯。", description = "你看起來很眼熟。你欠我錢嗎？等一下…不，不是欠錢。\n\n如果你打算來學點東西，我可以讓你看看我的秘密採礦技巧，但…嗚哦…\n\n我眼前的東西都在飛舞，連正前方是哪邊都分不清。呃…感覺上就像有人拿著十字鎬在猛敲我的腦袋。\n\n想要治好宿醉的最佳良方就是醃菜汁，再加上一頓豐盛的早餐。\n\n這樣吧，幫我把這些東西帶來，最好安靜又快速，我就把你想學的東西都告訴你。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：風暴白銀礦層(等級3)"}
MultiLanguageQuestData['tw'][52044] = {title = "超大白金裂片", objective = "把超大白金裂片帶給米拉‧卡柏特。\n\n已提供物品：\n", description = "在運氣絕佳的情況下，你費盡九牛二虎之力才挖出一大片白金，而不是幾塊較小的碎片。\n\n你不禁猜想米拉能不能教你什麼方法，讓你每次開採都能採收到這麼多礦。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：白金礦床(等級2)"}
MultiLanguageQuestData['tw'][52045] = {title = "強登巡邏", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][52046] = {title = "超大白金裂片", objective = "把超大白金裂片帶給金匠瑟考特。\n\n已提供物品：\n", description = "在運氣絕佳的情況下，你費盡九牛二虎之力才挖出一大片白金，而不是幾塊較小的碎片。\n\n你不禁猜想瑟考特能不能教你什麼方法，讓你每次開採都能採收到這麼多礦。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：白金礦床(等級2)"}
MultiLanguageQuestData['tw'][52047] = {title = "對抗風暴", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][52049] = {title = "地圖上的X標記！", objective = "在佐司瓦尋找破爛地圖上的標記。\n\n已提供物品：\n", description = "你在礦床旁邊找到一張摺起來的破舊紙張\n\n打開之後，發現是佐司瓦的地圖，而且西海岸有個X記號。\n\n紙張上寫著幾首淺白的詩，其中一首引起你的注意。\n\n「過去我是海盜，\n只愛飲酒作樂。\n後來不做海盜，\n現在挖寶為樂。」\n\n留下這張紙的人似乎花了很多時間在這片土地挖礦。他們或許能給你一些啟發。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][52050] = {title = "更有挑戰性的職涯", objective = "收集20塊白金碎礦。", description = "和你想像的一樣，海盜之血在我的體內流動。我把生命中的黃金時期都花在掠劫和強奪。\n\n我最喜歡的部份，就是把塞滿黃金和珠寶的箱子，埋在只有你知道的地方。\n\n唉，那樣的生活對我現在來說太亂來了。吹牛皮讓我滿心疲累，烈酒讓我翻腸倒胃。不過…我還是可以幫自個埋藏寶藏。\n\n幫我帶些值得埋藏的東西，我就把這幾年學到的一切都傳授給你。\n\n好了，要當我的手下嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：白金礦床(等級3)"}
