MultiLanguageQuestData['tw'][52118] = {title = "砍個精光", objective = "找一把耐用的斧頭，從附近小樹收集5份剛砍下來的木頭。", description = "我從來就不在乎戰爭，但如果這些惡魔以為他們能搶下這座伐木廠？想都別想。\n\n最好快點清空這個區域。拿把斧頭，讓我看看你的本事。", progress = "你還在等什麼？", completion = "你還挺有天分的嘛。", rewards = "您會學到：\n\n伐木工之斧\n\n您還會收到：\n\n木頭"}
