MultiLanguageQuestData['tw'][52183] = {title = "計畫成形", objective = "聽聽納薩諾斯的計畫，再前往劫掠港。", description = "有了德瑞克‧普勞德摩爾的屍體在手，對我們接下來的計畫是一大利多。\n\n瓦倫泰已經復甦了，但我想最好先不要讓德瑞克活過來。\n\n該是運用我們的新盟友，成為我方優勢的時候了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52184] = {title = "儀式聖物", objective = "在斯陀頌恩修道院收集明晰羅盤、深海古物和大海之鑰。", description = "我被派來和你執行這個任務是有理由的，而且不單是因為我很熟的關係。深淵權杖被一個儀式封住，它的三塊零件是由建築物裡的三個不同副官所持有。\n\n你去拿聖物，我來執行儀式，權杖到手立刻離開。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52185] = {title = "定位精確的傳送門", objective = "使用通往波拉勒斯的傳送門，並在斯陀頌恩修道院和湯瑪斯‧澤靈會面。", description = "我們已經控制住前線了。我正打算派你和澤靈前往波拉勒斯，去拿深淵權杖。\n\n歐庫雷斯成功把一座傳送門定位到安全地帶。快走。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52186] = {title = "大批衛隊", objective = "在海妖之女號和英勇玫瑰號上殺死12位普勞德摩爾衛隊成員。\n\n荷巴爾特‧繫錘會帶你飛到船上。", description = "如果一切都按照計畫進行，普勞德摩爾已經派出精英部隊，去搶回她兒子的屍體。\n\n讓我們確定這些人不會妨礙我們的真正任務，怎樣？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52187] = {title = "老同行", objective = "殺死海妖之女號上的賈斯托德船長與衛隊指揮官創克賽爾，還有英勇玫瑰號上的舵手米芮雅。\n\n荷巴爾特‧繫錘會帶你飛到船上。", description = "負責這兩艘船的人是我的老同行，<name>。\n\n他們仰賴詐欺和黑函升到這個地位，而不是像我這樣努力工作。\n\n我想他們應該受到正義之錘的制裁。或者換成任何一種你喜歡的武器都可以。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52188] = {title = "浪潮賢者的教誨", objective = "在斯陀頌恩修道院收集5份浪潮賢者研究紀錄。", description = "這些人已經不再是浪潮賢者了。他們沒資格背負我們的稱號、我們的聲望，或是我們的知識。\n\n所以我們的諸多教誨都散落在這座修道院裡，對我們剩下來的人而言形同失傳。\n\n我們必須取回這些著作。留在我手中至少比他們好。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52189] = {title = "喪失靈魂", objective = "在斯陀頌恩修道院殺死8名浪潮賢者圖書管理員或浪潮賢者召喚師。", description = "此地的浪潮賢者已經獻身給黑暗魔法。他們將自身獻給他們無法瞭解、我的人民深受其苦的力量。\n\n我認得過去的他們，我在浪潮中的兄弟和姐妹。但現在他們都迷失了。\n\n我猜我也一樣。\n\n挽回浪潮賢者的名聲！殺死這些叛徒！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52190] = {title = "搶得先機", objective = "協助澤靈取回斯陀頌恩修道院中的深淵權杖。", description = "我們必須取回深淵權杖，在庫爾提拉斯的艦隊擊破我們在劫掠港的防線之前離開這裡。\n\n我趁你們不在的時候做了點研究，我想我找到了進行儀式的地點。\n\n等你準備好了，我們就出發吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52191] = {title = "命繫人質", objective = "協助納薩諾斯‧凋零者面對最後的普勞德摩爾部隊。", description = "正如莉莉安所言，看來還有一位最後的訪客。\n\n我們去拜訪他吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52192] = {title = "海潮的協助", objective = "和納薩諾斯‧凋零者交談，以回到祖達薩。", description = "有了德瑞克的屍體和深淵權杖在手，我們今天在此地的攻佔行動已經完成了。讓我們從他們的眼皮下消失吧。\n\n等你準備好，我們就回去祖達薩。希瓦娜斯一定在等我們的勝利消息。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52194] = {title = "悔不當初", objective = "到普勞德摩爾城堡旁的紀念碑與吉恩‧葛雷邁恩見面。", description = "<name>，吉恩‧葛雷邁恩留了這封信給你。他說很緊急。我正準備去找你。\n\n<拆開信後，內容如下。>\n「<name>：\n\n庫爾提拉斯現在能團結起來、願意援助聯盟，都是你的功勞，或許你有辦法讓她們母女重修舊好。\n\n來普勞德摩爾城堡家族紀念碑找我。或許我們可以說服普勞德摩爾海軍總帥暫緩她女兒的死刑。\n\n- 吉恩‧葛雷邁恩」", progress = nil, completion = "&lt;凱瑟琳移開目光。&gt;\n\n普莉希拉…艾胥凡女士說服我放逐自己的女兒。我現在已經知道這一切都是為了她的私利，不知道我的女兒是不是還活著。", rewards = "您會收到：\n\n"}
