MultiLanguageQuestData['tw'][52213] = {title = "遠古剝皮小刀", objective = "把遠古剝皮小刀帶去給剝皮高手拉娜。\n\n已提供物品：\n", description = "在野獸留疤的血肉下面，你在牠表皮下的凹陷處，找到了一把黃金刀刃。\n\n在小心翼翼抽出這把刀刃之後，你不禁猜測這是不是一把古老的贊達拉剝皮小刀。\n\n你應該讓剝皮高手拉娜看看這東西。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：皮革採集(等級3)"}
MultiLanguageQuestData['tw'][52214] = {title = "儀祭法衣", objective = "在納茲米爾從原生鉗嘴鱷身上剝下3張完好皮革。", description = "贊荷請我幫他收集一些材料來製作幾件儀祭護甲。\n\n他要的是幾片鱷魚皮，但我手頭的皮不是有瑕疪，就是上面有疤痕。\n\n我需要你幫我帶來足夠的新鮮鱷魚皮，而且要完好如初。\n\n據我所知，最好的來源是納茲米爾的原生鉗嘴鱷，因為牠們的表皮通常都夠厚，打鬥的時候不會留下疤痕。\n\n如果你能幫我這個忙，我就會讓你看看怎麼做才能從，呃…有鱗的生物身上，採到更多鱗片。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：鱗片採集(等級2)"}
MultiLanguageQuestData['tw'][52215] = {title = "厚重的絲線", objective = "在沃魯敦從叢網爬行者身上剝下5條厚重蜘網絲線。", description = "<name>！我正在等你現身！\n\n贊荷最近把他手頭的儀祭護甲做好了，但有一個問題。\n\n他說他用的線實在太細，皮革的重量把縫線都扯斷了。\n\n他問我能不能找些撐得住的材料，而我能想到的最佳選擇就是叢網爬行者的厚絲。\n\n你可以在沃魯敦北邊找到牠們。從牠們的厚重蜘網中抽些絲線回來給我，我就把鱗片相關的所有知識傾囊相授。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：鱗片採集(等級3)"}
MultiLanguageQuestData['tw'][52216] = {title = "甲殼皮甲", objective = "收集未破損的龍蝦人甲殼。", description = "我和贊荷打了一個賭，想要找出哪種皮革最適合用來製作護甲，才能抵擋穿刺和砍劈類的攻擊。\n\n他說鱗片最好，但我想到一個更好的東西。\n\n我覺得龍蝦人的外骨骼，可以當做天然的鎧甲使用。\n\n幫我弄一塊惡潮龍蝦人的甲殼，我就教你怎麼做才能在剝皮的時候，以更有效率的方式從生物身上採收骨頭。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：骸骨採集(等級2)"}
MultiLanguageQuestData['tw'][52217] = {title = "帝王的羅亞", objective = "收集瑞贊的骨骸碎片。", description = "嘿，<name>！來這邊。噓。近一點。\n\n<拉娜的聲音壓低到幾乎細不可聞。>\n\n我有件事要你幫我辦。這事可能有點褻瀆神明，但…呃…\n\n瑞贊原本曾是帝王羅亞，但是他被帶到了阿塔達薩，而且發生在他身上的事讓我無比悲傷。\n\n我要你去那邊，並幫我偷一根他的骨頭回來。不用到一整根。一塊破片。我不管它多小都行。\n\n請幫我辦好這件事，我就把剝皮時如何收集骨頭的一切知識統統告訴你。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：骸骨採集(等級3)"}
MultiLanguageQuestData['tw'][52218] = {title = "夜色恐懼", objective = "在寵物對戰中擊敗格里席斯‧微爆。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][52219] = {title = "目標：血親王德萊芬", objective = "在納茲米爾的崩塌坑道中與基沙恩會面。", description = "我們一定要殺死血親王德萊芬和他的追隨者。我知道他們打算前往一個地方。計畫是這樣。\n\n你和基沙恩從通道進去充當誘餌，讓德萊芬誤判安全性。\n\n我很快就會帶領哨兵封鎖入口，圍捕他和他的盟友。\n\n然後我們把他們全殺光。我會發出消息，讓其他人開始行動。\n\n我們走。", progress = nil, completion = "基沙恩已經復原，而我也已經派出斥候去收回哨兵的屍體了。\n\n他們因奮勇對抗一頭怪物而死。基沙恩和我將授予他們最高的榮譽。\n\n對於這邊發生的事，我會送一份報告給海弗德。我們必須把摧毀德萊芬視為最高優先。\n\n感謝你的幫助，&lt;name&gt;。沒有你，我們絕對辦不到。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][52221] = {title = "任務報告：石拳哨站", objective = "把捷報傳給納薩諾斯‧凋零者。", description = "<你的追隨者送來一份襲擊石拳哨站的報告。\n\n根據報告描述，那是一場硬仗，不過還是成功全滅那群原本住在前哨站裡的強盜了。\n\n登上女妖之嚎，把報告送給納薩諾斯‧凋零者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52222] = {title = "石拳哨站", objective = "為部落攻佔石拳哨站。", description = "你在提拉加德海灣對石拳哨站進行的侵略戰十分成功。做得好。\n\n現在我們可以攻佔前哨站了。\n\n前往提拉加德海灣的石拳哨站，並在那邊興建防禦工事。\n\n在對抗聯盟的戰役上，將會以石拳哨站做為主要據點。\n\n帶著榮譽前進！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52223] = {title = "鹽鉗", objective = "殺死鹽鉗，然後把牠的「腦袋」帶給卡蜜拉‧暗空。", description = "你！<name>！我有筆生意提案要找你！\n\n有頭大得像怪物的螃蟹在我最愛的幾個狩獵地點附近築了巢。\n\n因為海妖的關係，我已經被迫放棄好幾個狩獵場，我可受不了螃蟹再來給我搗蛋！\n\n把鹽鉗的腦袋帶來給我！我就教你怎麼樣在剝皮時獲得更多皮革。\n\n<卡蜜拉停了好一會兒，整理她的思緒。>\n\n抱歉，我老是以為每一種生物都有腦袋。只要把足以證明牠死掉的部位帶來給我就行了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：皮革採集(等級2)"}
MultiLanguageQuestData['tw'][52224] = {title = "象牙握柄匕首", objective = "將象牙握柄匕首帶去給卡蜜拉‧暗空。\n\n已提供物品：\n", description = "在剝除野獸皮革時，你摸到野獸的胃裡有團硬塊。\n\n進一步查看時，你發現那是一把匕首，有著雕工精美的象牙握柄。\n\n把它小心的拔出來之後，你不禁好奇卡蜜拉‧暗空會對這東西有多少認識。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：皮革採集(等級3)"}
MultiLanguageQuestData['tw'][52225] = {title = "追逐時尚", objective = "在佐司瓦從淺灘尖角蜥身上剝下3張完好的尖角蜥皮革。", description = "儘管我一而再、再而三聲明我不是製皮師，但這座城市腦滿腸肥的貴族還是委託我，要用最好的尖角蜥皮幫他做條腰帶。\n\n所以…我打算把材料湊一湊，跟一部分的錢一起交給卡珊卓拉來製作腰帶，差價我當然就留著了。\n\n問題就在，我需要你幫我弄點尖角蜥皮回來，數量要足以繞行一位領主的大肚腩。\n\n我會檢查你的努力成果，挑出幾個重點給你指導，讓你以後可以採收到更多皮革，來當作報酬。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：鱗片採集(等級2)"}
MultiLanguageQuestData['tw'][52226] = {title = "龜肉湯", objective = "從富源岩殼龜身上剝下5張硫化斑點皮。", description = "我不敢相信我一直受困在這座城市中！\n\n你會幫我的，對吧？\n\n我知道，我聽說這些烏龜過去一直在溫泉裡生活。\n\n有趣的是，有些溶在水中的硫磺滲進牠們的鱗甲，形成有趣的圖案。\n\n我忙到沒空自己去調查，但如果你可以跑一趟並幫我弄點牠們的皮革回來，我就會更願意教你剝除鱗片生物的其他知識做為交換。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：鱗片採集(等級3)"}
MultiLanguageQuestData['tw'][52227] = {title = "骨針", objective = "收集一根無瑕的刺針。", description = "<你看到卡蜜拉正忙著吸吮手上的傷口。>\n\n嘿，你能幫我一個忙嗎？我正在縫合這塊皮革上的打鬥裂口，結果我最後一根針就這樣斷了，現在我需要一根新的。\n\n我在佐司瓦的海岸上看過針刺鼠，牠們的刺針應該很合用。\n\n幫我拿一根狀況良好的刺針，我就教你如何在剝皮時採收到更多骨頭。\n\n<卡蜜拉看著她的雙手。>\n\n現在，如果你不介意的話，我得在它感染之前找位治療師。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：骸骨採集(等級2)"}
MultiLanguageQuestData['tw'][52228] = {title = "阿塔達薩：一根不會斷的骨針", objective = "前往阿塔達薩並收集瑞贊的骨頭碎片。", description = "嘿，<name>，來找工作嗎？\n\n我從聯盟的情報網中，聽到食人妖有個死掉的神祗還是什麼類似的東西。我想他的名字叫「瑞贊」，位於阿塔達薩。\n\n自從我上次弄斷骨針之後，我忍不住想如果用神的骨頭來做針，一定會堅不可摧，對吧？\n\n我要你去幫我偷一根他的骨頭。要不然，至少給我一塊碎片，只要大到足以刻出針眼加以使用就好。\n\n至於代價嘛，我會讓你看看我採收骨頭的所有絕活。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：骸骨採集(等級3)"}
