MultiLanguageQuestData['tw'][52275] = {title = "任務報告：疾風哨站", objective = "把捷報傳給納薩諾斯‧凋零者。", description = "你的追隨者送來一份跟疾風哨站任務相關的報告。\n\n報告裡詳細指出勝利得來不易，但先前在哨站肆虐的所有巫木怪獸都已經遭到誅滅。\n\n把這份報告交給女妖之嚎船上的納薩諾斯‧凋零者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][52276] = {title = "疾風哨站", objective = "為部落攻佔疾風哨站。", description = "你對佐司瓦、疾風哨站規劃的侵略戰十分成功。做得好。\n\n現在我們可以攻佔前哨站了。\n\n前往佐司瓦的疾風哨站，並在那邊興建防禦工事。\n\n疾風哨站將成為我們與聯盟作戰時的主要據點。\n\n帶著榮譽前進！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
