MultiLanguageQuestData['tw'][53070] = {title = "行動：扒手", objective = "在波拉勒斯港的風之救贖上與海弗德‧龍禍會面。", description = "現在該為下一場任務再開個會，只不過珊蒂斯和我對於該做什麼事情意見分歧。\n\n在風之救贖上和我們會面。", progress = nil, completion = "我覺得我們離結論不遠了，&lt;name&gt;。或許你現身此地可以提供協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53071] = {title = "行動：獅鷲獸之爪", objective = "在波拉勒斯港的風之救贖上與海弗德‧龍禍會面。", description = "軍情七處收到一些有趣的情資。\n\n我要你馬上回到風之救贖，協助決定我們下一個行動目標。", progress = nil, completion = "感謝你全速趕來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53072] = {title = "行動：直取心臟", objective = "在波拉勒斯港的風之救贖上與海弗德‧龍禍會面。", description = "我們已經解決掉為數不少的高度優先目標，<name>。這都要感謝你的協助。\n\n現在該是直擊贊達拉帝國心臟的時候了。\n\n儘速到風之救贖上報到。我們從那邊著手。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53073] = {title = "勾角地調查行動", objective = "到勾角地與崔布雷德總元帥交談。", description = "相信你一定聽到勾角地不斷傳來戰鬥聲響。\n\n我們派斥候去探查一番，了解為什麼一直打個不停，沒料到居然發現一個訓練場。\n\n勾角地的丹尼爾‧普爾勾正在信風市場附近經營某種決鬥表演。在我們的戰爭總部找到崔布雷德總元帥，並查明他們有什麼新消息。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][53074] = {title = "增援部隊", objective = "與馬迪亞斯‧肖爾交談以發佈一道招募令。", description = "你收集到的資源可以用來招募新部隊來推進戰事。\n\n定期回到我這邊，為你的任務發佈新的招募令。\n\n如果你有資源可用，你應該用它們來發佈你的第一道招募令。\n\n在我們交談的時候，戰事仍在不斷進行。我們會需要這些新兵的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53075] = {title = "決鬥俱樂部", objective = "與附近的保鏢交談。", description = "我就說像你這樣身經百戰的<race>一定可以在決鬥俱樂部的訓練中獲益。跟附近的保鏢談談，加入大屠殺的行列。", progress = nil, completion = nil, rewards = nil}
