MultiLanguageQuestData['tw'][53149] = {title = "殲滅枯木", objective = "在阿拉希高地殺死20個枯木部族食人妖。", description = "枯木部族在阿拉希高地傳承以久，一向殘忍無比。\n\n除了以暴制暴，別無他法。", progress = nil, completion = "擊敗食人妖了嗎？做得很好。", rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][53150] = {title = "殲滅枯木", objective = "在阿拉希高地殺死20個枯木部族食人妖。", description = "嗜血的枯木部族一向拒絕加入部落…既然現在部落已經佔領阿拉希，聯盟做不到的事，就由我們來達成。\n\n將森林食人妖趕出高地。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][53151] = {title = "任務報告：獸穴的恐狼", objective = "把任務報告送給納薩諾斯‧凋零者。", description = "<你的追隨者送來一份狼穴的任務報告。\n\n報告裡詳細指出任務相當成功，而且現在多了一群保護哨站的恐狼。\n\n把報告送給女妖之嚎上的納薩諾斯‧凋零者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53152] = {title = "狼穴的狼", objective = "跟穆克拉爾‧黑脈說話。", description = "看來提拉加德海灣的狼穴任務相當成功。<name>，做得好。\n\n現在哨站附近的區域有一群恐狼定期巡邏。\n\n去狼穴看看這些狼的訓練程度有沒有符合標準。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53153] = {title = "污染者去死！", objective = "在格沙克農場殺死20個污染者。", description = "即便幽暗城毀滅了，污染者仍在阿拉希高地頑強抵抗。\n\n格沙克農場將再一次屬於聯盟。去吧，擊敗被遺忘者。", progress = nil, completion = "你把他們趕走了？做得很好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53154] = {title = "聯軍終將落敗", objective = "在達比雷農莊殺死20個阿拉索聯軍士兵。", description = "就算激流堡陷落了，阿拉索聯軍仍持續在高地出沒。\n\n北方農場將會屬於部落。去吧，擊敗人類。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53155] = {title = "滿是凹痕的硬幣", objective = "將滿是凹痕的硬幣帶給翠玉林的米利‧蕩酒。\n\n已提供物品：\n", description = "<這枚破舊的硬幣顯然轉手多次。因為經年累月曝露在無盡之海的海風中，邊緣有些鏽蝕，而且它的外觀有點不太尋常。\n\n你看到好幾枚這樣的硬幣散落在島上，看來使用得相當頻繁。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53159] = {title = "阿拉希捐獻：粗製皮革", objective = "在波拉勒斯港捐獻60張粗製皮革給夏琳。", description = "我們現在該扼殺這樣的競爭了，你不覺得嗎？在你的協助下，我們可以確保盟友獲得必要的貨物和護甲，準備即將到來的戰爭。\n\n讓們保證我們的盟友能準備萬全。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53160] = {title = "古代墓穴鑰匙", objective = "把鑰匙帶到恆春谷的博學行者阿洲。\n\n已提供物品：\n", description = "<從島上的魔古身上找到了一具魔法裝置，卻似乎沒有動力了。\n\n你想起用來啟動潘達利亞魔古寶庫的遠古泰坦機械，有著十分類似的外觀。\n\n這一具特殊裝置，似乎帶來更為不祥的預感。\n\n或許博學行者會知道這個裝置有什麼乾坤。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53161] = {title = "暗礁之戒", objective = "解開這道謎題。\n\n已提供物品：\n", description = "<一道迷霧之光盤旋在這枚戒指上面，就像是在輕撫著它。\n\n光是拿著這個東西，你的靈魂深處就湧出一股不安感。感覺上，它像是一支隱形、冰寒的手，從亡者的土地伸了過來，一直在拉你。\n\n這絕對是黑爾雅的力量。\n\n華爾拉亞會想瞭解這個東西。>", progress = nil, completion = "另一枚戒指？嗯哼。對，最近我們經常看到這些東西。\n\n&lt;瓦德瑪皺起了眉頭。&gt;\n\n黑爾雅的力量正在增張。\n\n怎麼，小個子，你嚇到了？你以為她被打敗了？\n\n&lt;瓦德瑪開懷大笑。&gt;\n\n你怎麼可能殺掉死亡！\n\n感謝你今天讓我笑得很開心，小朋友。\n\n歐丁聽到你在搜集艾澤萊晶岩的消息，我們盡力幫你找了一些。\n\n來，這是給你的。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53162] = {title = "辛迪加的罪孽", objective = "在達比雷農莊殺死20個辛迪加成員。", description = "污染者已經是一大麻煩了，辛迪加問諜還不停從奧特蘭克山脈溜下來，趕跑老實的聯盟農夫。\n\n給他們一點顏色瞧瞧。", progress = nil, completion = "已經把辛迪加趕回奧特蘭克了？做得很好。", rewards = "您會收到：\n\n戰爭物資"}
MultiLanguageQuestData['tw'][53163] = {title = "血喚角杯", objective = "把角杯帶去給維達哈爾。\n\n已提供物品：\n", description = "<從一位血喚維酷人身上找到個巨大角杯。\n\n它打造的極為結實，得以熬過無盡之海上的多年遊歷洗禮，還依舊完整。\n\n在你握著角杯時，你想起那些維酷人對艾澤萊晶岩有著無比的熱切之情，但又是為了什麼？\n\n或許其他維酷部族會更加瞭解喚血氏族，以及他們的動機何在。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53164] = {title = "音石", objective = "到螳螂荒原讓哨兵指揮官祈潘看看這枚石頭。\n\n已提供物品：\n", description = "<隨著你的觸碰，石頭開始震動。那股共鳴頻率傳入你的身體，讓你覺得精神舒暢。\n\n螳螂人可能運用這些石頭，讓他們得以飛行長遠距離、跨過海面。\n\n在杉齊爾被消滅之後，螳螂人已經受到嚴重打擊，應該不會群聚活動，在島上看到他們更是令人倍感意外。\n\n在潘達利亞的居民可能有更多消息。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
