MultiLanguageQuestData['tw'][53190] = {title = "驅邪", objective = "在激流堡殺死20個心懷仇怨的鬼魂。", description = "就算死了，愚蠢的聯盟還是緊抓著部落的土地不放。\n\n將他們心懷仇怨的鬼魂逐出激流堡的廢墟，以免這股腐惡繼續擴散。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53192] = {title = "重新流放", objective = "在阿拉希高地殺死20個橫行霸道的元素生物。", description = "各式各樣的元素生物在高地橫行霸道。\n\n讓它們回歸原始混沌。", progress = nil, completion = "已經放逐了那些元素生物？做得很好。", rewards = "您會收到：\n\n戰爭物資"}
