MultiLanguageQuestData['tw'][53194] = {title = "上前線", objective = "和伊芙拉‧晨翼交談並傳送到激流堡，然後向羅德里克‧布魯斯頓隊長報到。", description = "請你去看看阿拉希高地。目前戰事已經陷入僵局，但是當它再度白熱化時，我們需要你上前線。\n\n伊芙拉‧晨翼會負責維持直通激流堡的傳送門。她可以幫助你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53195] = {title = "阿拉希捐獻：亞昆達之噬", objective = "幫波拉勒斯港的雀爾希‧史傳德收集20份海妖花粉。", description = "你好啊！\n\n在戰爭局勢劍拔弩張的現在，由我來擔任你的草藥學與鍊金術捐贈連繫人！能見到你真是榮幸！\n\n現在，讓我們來看看…啊，是的。海妖花粉。從昨天晚上的報告指出，我們的存量開始短缺。如果你能捐獻我們的戰備，對我們可以提供很大的協助。", progress = "你幫我拿到藥草了嗎？", completion = "這種草藥的香味絕對不會認錯。\n\n我保證會好好運用。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53196] = {title = "清光海盜！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][53197] = {title = "前線巡禮", objective = "向工頭圖莉、伐木工里歐和格雷森‧貝爾報到。", description = "部落已經好一陣子都沒發動攻擊了。老實說，我們也一樣。現在去外面進行偵察應該很安全了。\n\n去礦坑與伐木場見見我們的工頭。能知道他們還在崗位上活得好好的是件好事，再說，這趟旅程應該會讓你對這塊土地有些瞭解。\n\n說到這個，你可以和飛行管理員格雷森‧貝爾談談，他能幫你飛快的掃視一下敵方基地。好像叫做「亞格洛克」還是什麼來著，反正是不知道有什麼意義的獸人名字。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53198] = {title = "回到波拉勒斯", objective = "和伊芙拉‧晨翼交談以回到波拉勒斯。", description = "現在這樣應該就可以了。要是戰事又越演越烈的話，我們就會再見面的。誰也說不準是什麼時候。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n戰爭前線：激流堡之役\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][53205] = {title = "阿拉希捐獻：蒙那萊礦石", objective = "收集20枚蒙那萊礦石給波拉勒斯港的布朗鐸‧暗鬚。", description = "你看起來就像是會帶了不少礦石到處跑的<小夥子/小姑娘>！如果我沒看錯你的話，我們需要你出點力，提供一些戰時礦材。\n\n你手頭有多出來的礦石嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53207] = {title = "戰爭前線的逼近", objective = "到祖達薩向斯洛克報到。", description = "我們要有遠見，目光不能跼限於庫爾提拉斯。聯盟依舊會在其他地方對我們的部隊施壓。\n\n我們最感興趣的地方是阿拉希高地，靠近激流堡附近。我們在那個地區架設了一座營地，試圖攻下激流堡。\n\n去和斯洛克談談，他是負責這類特殊戰爭前線部門的招募軍官。他一定很需要一位像你這樣的<class>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53208] = {title = "上前線", objective = "和德露莎‧虛牙交談以傳送到亞格洛克，然後向威斯特‧銀盜報到。", description = "我們正在阿拉希高地開戰。目前戰事已經陷入僵局，但是當它再度白熱化時，我們需要你上前線。\n\n德露莎‧虛牙會負責維繫直通亞格洛克的傳送門。她可以幫助你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53209] = {title = "戰爭前線貢獻", objective = "進行戰備捐獻。你可以捐獻黃金、戰爭資源或是打造好的裝備。每天只會有幾位非玩家人物接受捐贈。", description = "訓練精良的部隊只能帶我們走到這一步，<name>。我們需要金錢、食物和補給品，才能讓我們的軍隊吃飽去作戰。\n\n盡你所能，展現你令人驕傲的一面。為了部落！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n榮勛軍團"}
MultiLanguageQuestData['tw'][53210] = {title = "前線巡禮", objective = "向工頭卓格、戈爾和飛行工程師克拉佐報到。", description = "聯盟已經好一陣子都沒發動攻擊了。事實上，我們也一樣。現在去外面進行偵察應該很安全了。\n\n去礦坑與伐木場見見我們的工頭。能知道他們還在崗位上活得好好的是件好事，再說，這趟旅程應該會讓你對這塊土地有些瞭解。\n\n說到這個，你可以和飛行工程師克拉佐談談，他可以讓你以飛快的速度一覽激流堡，你才能親眼看到我們正在對付的敵人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53211] = {title = "阿拉希捐獻：濱海治療藥水", objective = "幫波拉勒斯港的雀爾希‧史傳德收集10瓶濱海治療藥水。", description = "我收到一些消息，有些盟友打算為即將到來的戰爭儲存一些補充品。如果你剛好找到幾瓶濱海治療藥水，我會很樂意將它們加入我們的存貨。", progress = "不知道你有沒有多的治療藥水。\n\n我正在想辦法為即將到來的戰鬥張羅足夠的補給品。", completion = "噢，不…\n\n&lt;雀爾希在一瓶藥水掉到地面之前及時接住了它。&gt;\n\n差一點就毀了！\n\n如果我搞砸了它們，就沒什麼用了，對吧？\n\n再次感謝你，&lt;name&gt;！", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53212] = {title = "回到祖達薩", objective = "和德露莎‧虛牙交談以回到祖達薩。", description = "那麼，那應該要馬上進行。如果戰鬥的烈火再度燃起，我們會再次聯絡。說真的，每一天都有可能。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n戰爭前線：激流堡之役\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][53213] = {title = "阿拉希捐獻：濱海法力藥水", objective = "帶10瓶濱海法力藥水去給波拉勒斯港的雀爾希‧史傳德。", description = "我們最後一批鍊金材料貨物已經送往儲存地點了。我們忙著把存貨補回到正常量，但我很擔心我們達不到配額。\n\n你該不會剛好知道去哪邊弄到更多法力藥水吧，嗯？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53216] = {title = "阿拉希捐獻：閃鱗", objective = "在波拉勒斯港捐獻100張片閃鱗給夏琳。", description = "我就直說了：我們需要閃鱗！\n\n很抱歉我得講得這麼直接，但已經沒有時間了。\n\n如果你剛好在旅程中碰到這類的物品，我一定會樂意善加運用。在即將到來的戰場上，幫我們的好好打扮一下才是最重要的，你也同意吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53217] = {title = "阿拉希捐獻：粗製皮革坐騎護具", objective = "幫波拉勒斯港的夏琳收集5具粗製皮革坐騎護具。", description = "在即將到來的戰爭中，不只是我們的盟友需要防護，還有我們的馬科朋友！\n\n你能不能幫個忙，讓我們的盟友在接下來的戰鬥之前，拿到眼前最棒的護甲？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53218] = {title = "阿拉希捐獻：蒙那萊硬化蹄甲", objective = "收集2具蒙那萊硬化蹄甲給波拉勒斯港的布朗鐸‧暗鬚。", description = "戰爭的勝敗並非只看哪一方的護甲最好、刀刃最利，但這肯定可以幫上忙！事實上，不只你的盟友需要協助，還有我們的戰爭野獸。\n\n如果你能為我們勇敢的野獸提供其他蹄甲，我一定會確保我們的蹄鐵匠好好照顧它們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53219] = {title = "阿拉希捐獻：蒙那萊硬化鐙索", objective = "收集2具蒙那萊硬化鐙索給波拉勒斯港的布朗鐸‧暗鬚。", description = "像目前這種時刻，能夠隨時準備上戰場才是最重要的。為我們的野獸搭配合適的鐙索，就是正確的第一步。\n\n如果你能幫我帶幾條來，我敢保證一定會好好發揮它們的功效。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53221] = {title = "任務報告：遺失的補給品", objective = "把任務報告送給海弗德‧龍禍。", description = "你的追隨者送來一份禿鷹巢的任務報告。\n\n根據報告，任務非常成功，而且遺失的補給品都找到了。\n\n將報告帶給風之救贖上的高階指揮官龍禍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53222] = {title = "必備的補給品", objective = "與巴茲‧曲軋談話。", description = "找回補給品的任務成功了。做得好，<name>。\n\n有問題的補給品貨物，都是由禿鷹巢的巴茲‧曲軋訂的。你應該去沃魯敦的哨站看看，確定一下所有遺失的補給品都有紀錄。\n\n一路前往沃魯敦的禿鷹巢，並和巴茲‧曲軋交談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][53223] = {title = "阿拉希捐獻：燒烤鯰魚", objective = "為波拉勒斯港的塞內德拉斯收集5份燒烤鯰魚。", description = "你好，旅行者。\n\n我授命確保我方的食物補給品永遠不匱乏，而且我們的魚類補給最近十分短缺。你有沒有什麼可以捐贈的？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53224] = {title = "阿拉希捐獻：調味腰內肉", objective = "為波拉勒斯港的塞內德拉斯收集20份調味腰內肉。", description = "一塊上好、營養豐富的肉可以在我方盟友踏向戰場前滋養他們的身心，在狂風吹拂與冰寒夜晚的寒氣滯留在空中時，還可以烹調成一份燉肉讓他們好好享用。\n\n如果你帶來一些新鮮的調味腰內肉，我會十分樂意提供給我們的補給官。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][53225] = {title = "阿拉希捐獻：無盡之海鯰魚", objective = "為波拉勒斯港的塞內德拉斯收集40隻無盡之海鯰魚。", description = "魚 - 那是晚餐用的！至少我們的補給官是這樣說的。而且這一周的主菜就是用其中一種美味材料 - 鯰魚。\n\n如果我們想讓盟友吃飽飽，並將漁獲量存到滿，我們得馬上收集其他貨物，並開始進行餐點的準備。\n\n如果你發現身處於大量鯰魚之間游動，我會很樂意把它們都送進我們的儲藏庫。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
