MultiLanguageQuestData['tw'][53701] = {title = "佐司特志業", objective = "把入侵佐司瓦的部落軍隊趕走。", description = "部落軍隊正在攻入佐司瓦核心。守住防線，把他們趕回老家。庫爾提拉斯是我們的！", progress = "部落還在攻擊佐司瓦，我們不能鬆懈！", completion = "部落真是罪有應得。", rewards = "您會收到：\n\n第七軍團裝備箱勝利滋味第七軍團軍功獎章"}
