MultiLanguageQuestData['tw'][54015] = {title = "深入前方", objective = "到納沙塔爾與薩莉瑟拉和洛索瑪會面。", description = "在我們離開後，我可以讓這道屏障維持一陣子，但我們不可能一直留在這裡。\n\n這些士兵很快就會面臨威脅。\n\n我們必須深入這個地方，尋找更加容易防守的地點。", progress = nil, completion = "小心一點！別引起敵人注意。", rewards = "您會收到：\n\n"}
