MultiLanguageQuestData['tw'][54018] = {title = "送你一程", objective = "在納沙塔爾與洛索瑪‧塞隆會面。", description = "到底發生什麼事！也就是說，到底發生什麼事？沒錯，這個反應很合理，不是嗎？\n\n我發現我們的處境很有意思！但也很糟糕。\n\n原本是說…對了，洛索瑪叫我立刻派你去找他。他需要你的專業，$p。\n\n我會把你安全送到瀑布下面。祝你好運！", progress = nil, completion = "我們已經損失慘重，&lt;name&gt;。讓我們同心協力，避免更多損失。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54020] = {title = "刺殺行動：幽水島域", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54021] = {title = "首席秘法師", objective = "到納沙塔爾與首席秘法師薩莉瑟拉會面。", description = "我們的情勢險峻，$p。\n\n部落艦隊在達薩亞洛之戰遭逢重創。納迦設下的這個陷阱，讓我們損失慘重。\n\n生還者回報說，看到納迦抓走俘虜。薩莉瑟拉已經先行前往，看看她可以幫上他們什麼忙。\n\n在你幫助首席秘法師展開行動之時，我會處理好這邊的事。我的遊俠會盡可能提供協助。", progress = nil, completion = "啊，&lt;name&gt;。你撐過那場攻擊了，太好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54022] = {title = "梅卡托克的戰鬥計畫", objective = "找到梅卡托克的戰鬥計畫", description = "<你找到了一部份的計畫書，指出梅卡托克和他的飛船會在提拉加德海灣的哪個位置。\n\n如果你可以找到另一半的計畫書，應該就可以對這個地精領袖發動一波突擊。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54026] = {title = "完工了", objective = "回到奧格瑪的葛羅瑪許堡向指揮官卓許報告。", description = "我會在這邊多待一陣子，確保苦工都回頭工作。\n\n你應該回去奧格瑪，讓指揮官卓許知道他不需要再為哨站的事情苦惱了。", progress = nil, completion = "苦工回來了？那真是好消息。\n\n為了他們好，但願這種事不會再次發生。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54027] = {title = "威脅消除", objective = "回到奧格瑪的葛羅瑪許堡向刃衛桑姬報告。", description = "太好了，這樣納迦就無法作怪了！\n\n向刃衛桑姬回報這個好消息的榮耀就交給你了，告訴她祖達薩海岸的威脅解除了。", progress = nil, completion = "納迦的威脅解除了？很好，我相信你說的話，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54028] = {title = "機甲對飛艇", objective = "坐進G.M.O.D轟掉聯盟飛船，並且對付梅卡托克。", description = "多虧你找到了他們的戰鬥計畫，我們一切都準備好了。梅卡托克看來目前不在飛船上。\n\n計畫是這樣的。我們先重創他的船艦，然後等梅卡托克回來拯救他的朋友。\n\n但是到時候，他只會看到你和我站在燃燒的甲板上，等著解決他！\n\n坐進機甲吧，<name>，我們有一艘飛船和一個地精要炸上天！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54031] = {title = "羅亞的凝視：奎格瓦", objective = "「見證」奎格瓦的試煉。", description = "你好，又見面了，小東西。\n\n我看得出塔蘭姬挑了一位夠資格的見證人。我會測試塔蘭姬願意為人民做出什麼樣的犧牲、衡量她對捍衛弱者的信念。許多偉大的統治者都沒能通過這個挑戰，還是成為雄霸一方的君主。\n\n但只有倍受敬愛、發現身邊滿是忠誠的追隨者之人，才能瞭解虔誠之心對人民有多重要。\n\n你將協助我進行這場試煉。在你準備開始時和我交談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54032] = {title = "羅亞的凝視：帕骷", objective = "完成帕骷的試煉。", description = "還有兩位羅亞宣告他們有意考驗塔蘭姬。下一位是帕骷。她在這些臺階頂端等候兩位。\n\n我應該用不著警告你，她的天性有如暴風雨般，也無需強調她很喜歡看著其他人從高處掉下去。\n\n祝你好運，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54033] = {title = "羅亞的凝視：剛克", objective = "完成剛克的試煉。", description = "獸群之王要求當下一個和塔蘭姬交談的羅亞。他就在下一個臺地的臺階上。\n\n我不認為他會對你提出跟我一樣的要求，但我相信他所說的話，和你來此的目的有關。\n\n<奎格瓦一邊的巨大眼睛眨了眨。>\n\n別以為我們不知道你有什麼意圖，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54034] = {title = "羅亞的凝視：伯昂撒姆第", objective = "完成伯昂撒姆第的試煉。", description = "<帕骷的浮力消退了。>\n\n在一般情況下，最終試煉是由瑞贊主持，但是帝王羅亞已不復存在。\n\n看來老拉斯塔哈挑了一個新歡來取代他的位置。\n\n<帕骷輕蔑地笑著。>\n\n好好享受吧。伯昂撒姆第在神殿中等著你們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54036] = {title = "特別流程", objective = "與糯米交談。", description = "你可能已經發現，葡萄酒商勒修斯確實十分精於釀酒工藝，但他的古老配方是專為迎合夜裔精靈的口味所設計的。\n\n我們需要來點不一樣的，才能取悅部落各方人士的品味。\n\n去和糯米談談，看看他有沒有什麼想法可以促成這件事。", progress = nil, completion = "很高興再見到你，&lt;name&gt;。我已經改良了葡萄酒商的配方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54041] = {title = "全數殲滅", objective = "殺死8名隱身亡靈哨兵。", description = "你看到下面海灘的那座營地了嗎？\n\n部落跟蹤泰蘭妲到這裡。\n\n這裡肯定還有其他人躲在暗處，等著她回到此地。\n\n殺了他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54042] = {title = "黑海岸的動亂", objective = "和恐衛上將黛特賽爾交談，前往黑海岸向納薩諾斯回報。", description = "我們接到黑海岸的報告，非常令人擔憂。\n\n這個地方原本是戒備森嚴的部落城塞，現在則籠罩於人為的黑暗之下。明月已變得一片漆黑。\n\n我們的主力部隊增援還未抵達那裡的哨站，我們突然變得寡不敵眾。納薩諾斯要你前往黑海岸與他會面，並找出發生什麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54043] = {title = "更多的黑暗遊俠", objective = "殺死復仇哨兵和弓箭手，並命令布萊妮雅復活他們成為黑暗遊俠。", description = "夜精靈發動的伏擊讓我們人手大為不足。若我們想守住黑海岸，就必須請求援軍。\n\n布萊妮雅，黑暗女王的其中一名華爾琪，能提供我們援軍。擊殺夜精靈，然後號令布萊妮雅復活他們，為我方效力。如果有人不願意…那就解決他們。\n\n我講得還不夠清楚嗎？去吧。黑暗女王對這些黑暗遊俠自有打算。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n黑暗遊俠的備用風帽"}
MultiLanguageQuestData['tw'][54044] = {title = "黑月升起", objective = "從勾拉斯、艾維斯和瑪麗拉中尉身上榨出情報。", description = "黑海岸從來不是一個陽光明媚的地方，但這裡發生了奇怪的事件。黑色的月亮懸在空中，詭異的光芒壟罩一切。\n\n我派去森林探查的斥候沒有一個回來。這些夜精靈正在圖謀些什麼，而我必須知道他們的動向。\n\n我們沒辦法從普通人員身上找到想要的情報。獵捕他們的軍官。不論用什麼手段，務必逼他們吐實。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54045] = {title = "逃離藤蔓！", objective = "釋放被藤蔓困住的哥布林收割機。", description = "太糟糕了，<name>！我們的收割機沒在收割東西！\n\n我們拚著老命在砍這些樹，但是有人不斷用藤蔓纏住我們的機械！附近潛伏那麼多夜精靈，我可不想出去。\n\n看看你能不能去森林裡，把我的機器救出來！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54046] = {title = "長林暗光", objective = "將迷失的幽光帶到洛丹諾海灘，交給納薩諾斯‧凋零者。", description = "<幽光閃爍的方式令人困惑。它似乎打算跟隨你。\n\n或許它有納薩諾斯想要的情報。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54047] = {title = "希望死寂之處", objective = "找到德拉茵‧夏月的屍體。", description = "我們必須在重振士氣的夜精靈攻陷我們之前，執行黑暗女王的命令。\n\n我們要找的是一名夜精靈。你可能還記得，我們上次前往黑海岸遇到的女夜精靈。你運氣好，她已經死了…所以她應該比我們遇到的那些生者還要容易應付點。\n\n當你找到她的屍首，就打個訊號給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54049] = {title = "暗夜亡者", objective = "在華爾琪復活德拉茵和西拉時，保護她們。", description = "這是黑暗女王的黑海岸計畫的關鍵。我們要在這裡把亡者復活為被遺忘者以及部落的新勇士。\n\n保護華爾琪。我們不能容許任何人、任何事物打斷她們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54050] = {title = "劫後餘燼", objective = "和納薩諾斯‧凋零者交談。", description = "我們都懷抱著各自的理由接受了華爾琪的贈禮。但現在不是討論這些事情的時機。\n\n希瓦娜斯今天受到重挫，失去了布萊妮雅。聯盟很快就會軍臨此處，我們沒有時間休息。\n\n納薩諾斯請你過去，有些東西一定要你親眼看看。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n布萊妮雅的信標"}
MultiLanguageQuestData['tw'][54051] = {title = "納迦來襲！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54052] = {title = "任務之落", objective = "殺死8位河爪豺狼人並擊敗吠爪。", description = "抱歉，夥伴！剛上船的！你比較像個使劍的，對嗎？！\n\n不表示一定要你從這方面著手啦！只不過我們這群人的關係有點緊密，我指我和此地的船員！\n\n你能幫我們一個忙嗎？！有些直起身子的狗挑了一個死寂之夜攻擊我們！害我們從營地逃出來的時候身上只剩內衣褲！\n\n或許你能幫個忙？他們其中有頭身體巨大的當老大！因為它的爪子超大，而且對我們吠著不停，所以我們都叫它吠爪！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54058] = {title = "出乎意外的結果", objective = "在佐司瓦找到虛無石。", description = "<薩拉塔斯再度開口。>\n\n恩若司的僕從開始蠢動，打算迎接主人的歸來。他們想要掀起一場肅清的波濤，消滅所有懷疑他們的人。\n\n想要舉行這種儀式需要三項威力強大的聖物。分別來自虛無、風暴和海洋。\n\n那個虛無聖物…我可以感覺得到，它正在呼喚我。我無法確定它被強化了還是受到腐化。它在一個懸崖上，俯視著海洋。\n\n來吧，<class>。我們得好好利用這份恩賜。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54059] = {title = "黑夜戰士", objective = "和迷失的幽光交談，調查月亮化為黑暗的原因。", description = "看來這些夜精靈不會輕易告訴我們任何情報，但或許你抓到的幽光願意。\n\n看你能不能讓幽光告訴我們這裡發生什麼事。我不在乎你用什麼手段。\n\n讓諾拉斯神父接手，處理這個幽光您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
