MultiLanguageQuestData['tw'][54120] = {title = "前往奧格瑪", objective = "帶著沃金的戰刃到杜洛塔的薩魯法爾防線和加德林大師會面。\n\n已提供物品：\n", description = "在我意識中有一團黑影蒙蔽了我的記憶，害我想不清楚任命希瓦娜斯為大酋長那天發生的事情。\n\n帶著我的武器到奧格瑪，到我被火化的火堆。\n\n加德林大師有足夠在火堆上召喚我的魂能。\n\n去吧，我們在那邊見。", progress = nil, completion = "雖然沃金對我的本領很有信心，我還是請了一些盟友來協助我們。這件事可不容易。塔蘭姬才是這個儀式的最佳人選，但我會盡我所能。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54121] = {title = "幫艾胥凡越獄", objective = "在提拉加德海灣和薇兒塔碰面。", description = "黑暗女王希望能獲得另一個潛在的盟友，攜手對抗聯盟。\n\n艾胥凡公司的首領，艾胥凡女士，一直都是庫爾提拉斯最大的敵人…直到她被抓走。\n\n我們得把她放出來。\n\n到提拉加德海灣和薇兒塔碰面。她和雷克薩打算進行一個計畫，幫艾胥凡逃獄。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54123] = {title = "通通裝進我的機甲！", objective = "使用艾澤萊晶岩吸取器，從艾澤萊晶岩泥漿上取回艾澤萊晶岩。", description = "來看看這個！這是我最新發明，交由其他人來打造的結晶，加里維克斯的死亡機甲！\n\n我把你找回來的所有艾澤萊晶岩都塞進去當燃料了，但是還需要多塞一點讓它更帶勁。\n\n我們原本應該可以在這裡獲得晶岩，但有某種艾澤萊晶岩黏液怪在搗亂！\n\n我的朋友派奇幫我造了一台艾澤萊晶岩真空裝置。我要你從這些泥漿身上吸取艾澤萊晶岩！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54124] = {title = "慣老闆守則101", objective = "解救6個沒保險的哥布林工人。", description = "喂，<name>！我才離開A.M.O.D.兩秒去應付老加里維克斯，而現在艾澤萊晶岩黏液都淹到我的膝蓋了！\n\n聽著，這樣好了，我要你從這些怪物手上救出一些哥布林。\n\n老實說，我沒有為他們支付艾澤萊晶岩怪物相關職災的保險費。\n\n怎樣？誰知道這些泥漿怪會出現攻擊他們嘛！\n\n幫我個忙，把這些哥布林弄出去！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n綜合哥布林保險套餐"}
MultiLanguageQuestData['tw'][54126] = {title = "如刃之鋒", objective = "到滅絕峭崖和薩拉塔斯會面。", description = "聖物已經到手…正如命運所注定。\n\n要揭露遠大的真相，還需要最後一步。\n\n納迦想要從充滿遠古力量的地方，召喚他們的風暴。這個地方在不同的年代有不同的名字，而你們凡人稱它為滅絕峭崖。\n\n我先過去準備。去那裡找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54127] = {title = "火箭飛躍", objective = "驅逐膽敢攻擊提拉加德海灣的部落軍隊。", description = "部落軍隊正在攻擊提拉加德海灣。膽敢涉足我們的土地，那就讓他們後悔踏上我們的土地！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54128] = {title = "必要的預防措施", objective = "檢查G.M.O.D的系統。", description = "那真是太酷了！我們瓦解了梅卡托克的弱小軍隊。\n\n我們找出了那小王八蛋以及他飛艇的位置，他就是在那裡控制所有機甲，啊，報廢的機甲。\n\n計畫是這樣的，我們要飛往那裡，痛扁那個怪胎，然後摧毀他的飛艇！\n\n現在呢，我可不是白癡，<name>，我是世上最聰明的哥布林。首先，我們必須採取所謂的必要預防措施。\n\n拿著這個手冊，我要你確定G.M.O.D已經準備就緒！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54129] = {title = "大副馬隆", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54130] = {title = "我們的新朋友", objective = "帶著你的人類孤兒前往駐暴風城大使館。如果你抵達時沒看到孤兒，記得叫他出來。", description = "我聽說聯盟正在成長！越來越多不同的種族持續加入我們，對抗殘暴的部落。\n\n我不是很確定大使館在哪裡，但我聽說在暴風城的某個角落。你能不能帶我去看看？我想要見見我們的新朋友！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54132] = {title = "部落英雄群集", objective = "帶領部落進攻斯陀頌恩谷地。", description = "聯盟已開始對斯陀頌恩谷地的部落部隊進行協同作戰。擊敗敵方部隊，將他們逐出去！", progress = nil, completion = "我聽說烏薩對你在斯陀頌恩的表現給予高度評價…你一定很不賴，因為她誰都討厭！", rewards = "您會收到：\n\n榮勛軍團裝備箱榮勛軍團軍功獎章"}
MultiLanguageQuestData['tw'][54134] = {title = "優秀英雄", objective = "帶領聯盟進攻沃魯敦。", description = "聯盟在沃魯敦握有優勢。我們現在攻擊！你將帶領我們的部隊迎向勝利！", progress = nil, completion = "真希望我能親眼看到沃魯敦的最後戰役！我聽說那場戰事非常驚人…如果有更多像你這樣的士兵，說不定這場戰爭明天就會結束了。", rewards = "您會收到：\n\n第七軍團裝備箱第七軍團軍功獎章艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][54135] = {title = "沼澤嬉戲", objective = "趕走攻擊納茲米爾的聯盟部隊。", description = "聯盟軍隊登陸納茲米爾海岸，快將他們趕回海裡面。贊達拉是我們的！", progress = nil, completion = "感謝你，&lt;name&gt;。我們決不能讓任何人從我們手中奪走這片土地。\n\n無論是鮮血食人妖、聯盟，或是任何外來者都不行。\n\n這塊土地屬於贊達拉…還有部落。直到永遠。", rewards = "您會收到：\n\n榮勛軍團裝備箱勝利滋味榮勛軍團軍功獎章"}
MultiLanguageQuestData['tw'][54136] = {title = "進軍沼澤", objective = "帶領聯盟進攻納茲米爾。", description = "聯盟正在對納茲米爾的部落展開全面攻擊。打倒部落軍隊，把他們趕跑！", progress = nil, completion = "納茲米爾或許看似不重要，但我們控制的每塊領土，都會為未來打開更多戰略選項。\n\n此外，我聽說你對部落的艦隊造成不小的破壞。哈！光是這樣就值得走一遭了。", rewards = "您會收到：\n\n第七軍團裝備箱第七軍團軍功獎章"}
MultiLanguageQuestData['tw'][54137] = {title = "每一個暗處", objective = "帶領部落進攻佐司瓦。", description = "聯盟在佐司瓦的控制力相當弱，我們會為了部落征服此地！", progress = nil, completion = "無論聯盟躲在哪裡… 我們都會把他們找出來。\n\n我很高興洛克漢與暗矛在我們這邊。", rewards = "您會收到：\n\n榮勛軍團裝備箱榮勛軍團軍功獎章"}
MultiLanguageQuestData['tw'][54138] = {title = "儀式狂亂", objective = "帶領聯盟進攻祖達薩。", description = "聯盟已經開始對贊達拉帝國的中心發動攻擊。在部落自己的地盤擊敗部落吧！讓他們知道聯盟的力量！", progress = nil, completion = "我讀過博學者奧姆里克的報告了…聽來我們在那裡做了一次相當精彩的武力展示。現在部落一定知道我們所能駕馭的力量遠超過他們的。", rewards = "您會收到：\n\n第七軍團裝備箱第七軍團軍功獎章"}
MultiLanguageQuestData['tw'][54139] = {title = "戰爭來襲", objective = "在大封印與神王拉斯塔哈交談。", description = "<name>，該動身了。我們收到消息，聯盟正打算穿越納茲米爾發動攻勢。\n\n前往大封印，神王拉斯塔哈和塔蘭姬公主在那邊擬定攻擊計畫。\n\n毫無疑問，我們一定可以擊潰聯盟。對方一定是笨蛋才會穿越納茲米爾來攻打我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54140] = {title = "動員贊達拉", objective = "動員贊達拉艦隊、戰士和飛行部隊。", description = "聯盟居然想攻擊納茲米爾，該讓那些蠢蛋見識贊達拉的怒火燒得有多旺了。\n\n我們必須召集艦隊、戰士和空中部隊，馬上朝納茲米爾出發。\n\n我會在血門協助部隊。這裡列出了一連串的交談對象，都是動員我方部隊的關鍵人員。\n\n快點行動，我們必須以最快的速度阻止聯盟。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54141] = {title = "艾薩拉勳章", objective = "將勳章拿給收藏家卡裘。", description = "<你在納迦的身上找到一枚金屬碟狀物品，上面寫著精靈文字，但是看起來卻十分陌生。你認為這有可能是納沙塔爾文。\n\n也許熟知納迦文物的人能翻譯這種文字。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54143] = {title = "高空俯視", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54144] = {title = "艾薩拉的命令", objective = "拿匕首到臨時祭壇。", description = "<卡裘研究了勳章，做出了奇怪的表情。>\n\n呃…納迦。\n\n勳章上刻了命令，看起來這些納迦受命入侵海岸，打算奪取有強大力量的聖物。\n\n我正好最近拿到了某個東西。你有看到那邊的匕首嗎？這個東西讓我毛骨悚然，我發誓我聽到它在對我低語。\n\n我是在斯陀頌恩谷地找到的，當時放在一個臨時的祭壇上。如果你能把它帶回那邊，或許可以找出更多線索，查明納迦打算拿它做些什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54145] = {title = "死亡羅亞", objective = "面對伯昂撒姆第。", description = "伯昂撒姆第是很危險的羅亞，但就算連我都不相信他會在沃金臨終時對他低語，指定由希瓦娜斯接任。感覺不太對勁…這麼說吧，不死族不合他的胃口。而且從我對這個大酋長的觀察看來，她對死亡也沒什麼興趣。\n\n我們和伯昂撒姆第交涉時一定要心懷敬意，不然就會嘗到苦果。來吧，別走散了。", progress = nil, completion = "給我聽仔細了，老兄。通常呢，你不敬的表現會讓老伯昂撒姆第很生氣。但我決定暫時先不追究。\n\n你所說的東西聽起來很像一種邪惡的毒咒。我要你從我的一些…「老朋友」那邊打聽更多情報。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54146] = {title = "強大的新盟友", objective = "帶著你的獸人孤兒前往駐奧格瑪大使館。如果你抵達時沒看到孤兒，記得叫他出來。", description = "我聽一些冒險者說他們成為部落的新盟友，和其他人都不一樣！最棒的一點？他們都在這裡，在奧格瑪！\n\n我不知道大使館在什麼地方…但我敢說你一定知道！你能帶我去嗎？我聽說有來自另一個星球的獸人！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54147] = {title = "面對華爾琪", objective = "護送沃金的靈魂去找埃伊爾。", description = "沃金的靈魂越來越強大，我應該不需要再持續這個儀式，一樣可以讓他留在這裡。\n\n這實在是太幸運了，因為伯昂撒姆第對我提出了警告，埃伊爾可能不樂於見到我。顯然她和伯昂撒姆第之間有一段過去，連羅亞也不願多談。\n\n等你準備好我們就可以開始了。", progress = nil, completion = "啊…埃伊爾。她相當不會控制自己的脾氣，性情又十分驕縱。她已經好幾個世紀不跟我說話了。我以為沃金重返一定跟她脫不了關係。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54154] = {title = "山丘上的間諜", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54156] = {title = "殺出血路", objective = "在血門內殺掉15個聯盟士兵。", description = "聯盟和庫爾提拉斯的主力艦隊在納茲米爾外海，但我們也不能輕忽這裡的部隊。\n\n似乎有一股奇怪的霧氣從納茲米爾湧來。那些庫爾提拉斯人一定用他們的某種巫術讓我們變得虛弱。\n\n我們必須從聯盟蠢貨的包圍中殺出一條血路。想辦法削弱聯盟來協助我們的軍隊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54157] = {title = "絕不放棄任何人", objective = "解救洛克漢。", description = "在此的各位戰士告訴我洛克漢英勇不屈，在被擊敗之前擋住了聯盟和他們的勇士。\n\n洛克漢還在血門裡，被某個叫做光鑄的生物抓了起來。\n\n我必須待在這裡協助守住戰線。我需要你去解救洛克漢！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54161] = {title = "天知地知佐司特知", objective = "從上古佐司特聖物上面移除附魔，瞭解它的構成。", description = "Bal'a dash，<name>。\n\n如果你有空的話，我需要你幫個忙。我最近收到一批從庫爾提拉斯走私出來的佐司特聖物。\n\n大部份都是普普通通的附魔，但有一個相當獨特。光是握著它就讓我的寒毛直豎。\n\n既然你是我最厲害的學徒，我在想如果我們合力分解它，看看它的材料成分，說不定能學到新東西。\n\n你覺得呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
