MultiLanguageQuestData['tw'][54169] = {title = "盜竊寶庫", objective = "從贊達拉的寶庫取回深淵權杖。", description = "深淵權杖是浪潮賢者的強大神器，而且對艦隊而言形同嚴重威脅。部落偷走了它，目前放在贊達拉的寶庫中。\n\n風暴守望偽造了一把權杖。你的首要任務就是在不驚動任何人的前提之下取回真品。\n\n在你準備好按照計畫行事時，就跟我說一聲。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
