MultiLanguageQuestData['tw'][54191] = {title = "改變航向", objective = "回到波拉勒斯港登上風之救贖，向海弗德‧龍禍報到。", description = "勇士，這場行動現在得靠我們了。\n\n目前正在蘊釀的事情，將會改變這場戰爭的走向。\n\n盡快到風之救贖上向我報到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54192] = {title = "敏感情報", objective = "到祖達薩與凱爾希‧鋼火會面。", description = "我從凱爾希‧鋼火手中收到一份報告，她宣稱發現了某種事物，會對我們的抗戰準備提供莫大助益。\n\n她拒絕透露任何細節，宣稱這麼敏感的情報一定要保持機密。\n\n看來你需要親自和她談談。\n\n她在席帕拉等你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54193] = {title = "這就叫做大！", objective = "聽聽梅格絲和莫頓的計畫。", description = "$p，請容我介紹梅格絲和莫頓，這兩位地精將會為聯盟帶來巨大優勢！\n\n他們正在調整一台裝置，可以把任何常見動物變成巨大無比、無人能擋的野獸，然後朝我們的敵人直衝而去！\n\n其中的細節我就交給梅格絲和莫頓說明，但我敢向你保證，這種科技可以改變一切！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54194] = {title = "絕「大」力量", objective = "用庫爾提拉斯咯咯雞來測試巨化儀。", description = "我們正在為巨化儀打造控制裝置，但我們得先測試它的核心。那才是真正的力量所在！\n\n這項科技領先部落好幾年，但簡單到連獸人都會用！\n\n對準按下去！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54195] = {title = "聰明的野獸", objective = "在猩猩峽谷內尋找葛隆。", description = "為讓實驗有最佳的結果，巨化儀應用在有相當智能的個體上。\n\n幸好我們的夥伴有足夠的聰明才智。\n\n他與自己的同胞已受到卡迦邁礦石強化，給予他們超人的智力！\n\n前往峽谷，讓葛隆知道我們已準備展開巨化程序！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54196] = {title = "走投無路", objective = "在猩猩峽谷殺掉12個污水哥布林。", description = "我的族人和其他動物一樣遭到獵捕。\n\n我們試著透過文明會談方式來尋求解決之道，但是這些盜獵者對我們能夠理性思考感到畏懼。他們陶醉在暴行之中。\n\n我問你，$p：誰才是真正的動物？\n\n要降到他們的水準讓我覺得很難過，但我沒有其他選擇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54197] = {title = "達卡尼爭自由", objective = "在猩猩峽谷釋放8位高等達卡尼猩猩。", description = "你見過達卡尼受到什麼樣的野蠻待遇嗎？被趕入畜欄監禁、等著被宰殺，或是面對更慘的下場…\n\n我一定要看到我的同胞重獲自由才能夠安心離開這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54198] = {title = "苦甜摻半的道別", objective = "在葛隆的洞穴裡與葛隆會面。", description = "你之前協助我整頓村落，讓我可以安心離開，現在我該準備一下了。\n\n到洞穴裡面和我會合，我會在那邊向大家道別。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54199] = {title = "眾人的需求", objective = "護送葛隆至席帕拉。", description = "自從峽谷開始冒出卡迦邁之後，我一直在尋找答案。為什麼我要背負智慧的重擔？我的生命又有什麼意義？\n\n我已經在巨化儀找到我的答案。\n\n我注定要協助聯盟擊敗部落。\n\n若我能在志願中拯救性命，那我的選擇就很清楚了。\n\n犧牲小我，完成大我。\n\n我準備好了，$p。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54200] = {title = "基礎評估", objective = "幫忙收集葛隆在速度、智力與力量方面的基礎資料。", description = "在我們使用巨化儀之前，我們需要收集一些基礎資料。\n\n我們將會針對速度、智慧和力量，請葛隆進行一些相關的簡單任務。\n\n這可以協助我們評估巨化之後的增幅程度。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54201] = {title = "為葛隆量身訂製", objective = "收集12塊艾澤萊晶岩礦石。", description = "葛隆的體型原本就大到令人訝異。事實上，要是不做一點修改，我想巨化儀很難套在他的腦袋瓜上。\n\n我需要不少礦石才能完成必要的調整，不過我們運氣不錯。附近的哥布林已經幫我們把礦採好了，我們只要從他們手中拿礦就好！\n\n幫我們弄回一批艾澤萊晶岩灌能礦石，我們就可以上工了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54202] = {title = "校正核心", objective = "在污水富礦中，對死掉的生物使用巨化儀來校正核心。", description = "巨化儀差不多準備好了！現在只差校正核心。\n\n想要避免引發災難性的後果，放在一頭死掉的東西上面使用。\n\n這個工作應該輕而易舉！\n\n我有一個預感，你最擅長的本事就是把活的東西弄成死的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54203] = {title = "巨化金鋼", objective = "在葛隆巨化之後進行測試。", description = "在我們開始之前，我會先把流程告訴你。\n\n巨化儀以遙控方式啟動。\n\n看到這顆紅色的大按鈕了嗎？\n\n<梅格絲指了指手中的裝置。>\n\n這會讓奔騰能量流竄到穿戴者身上，讓他們變大。\n\n為了安全上的考量，你應該和葛隆待在基地這裡。\n\n我想就是這樣了！你準備見證科學了嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54204] = {title = "全廟摧毀", objective = "指揮葛隆，在先知神廟擊敗部落。", description = "葛隆是我們最偉大的成就，而且他準好備出擊了！\n\n部落正在北邊的神廟集結部隊。\n\n博學者奧姆里克的傳送門可以讓你可以馬上抵達，葛隆就可以開工了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54205] = {title = "乖寶寶，好好睡", objective = "對葛隆使用鎮定飛鏢。", description = "我不敢保證這些鐵鍊能困住他多久。\n\n葛隆得稍微打個盹，直到他準備下次出擊。\n\n用這枚飛鏢。上面沾有某種可以放倒恐角龍的藥，而且是雙倍劑量，應該會有用。\n\n葛隆一定希望這件事由你來做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54206] = {title = "沉睡的密探", objective = "回到波拉勒斯港向海弗德‧龍禍報告。", description = "你在這裡的工作都完成了，$p。莫頓和梅格絲可以接手後續工作。\n\n回到波拉勒斯，向海弗德報告我們已經擁有這項武器了。\n\n不用擔心葛隆。莫頓和梅格絲會好好照顧他的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54207] = {title = "奪回哨站", objective = "在納茲米爾與妖術之王拉爾會面。", description = "我們可以對付剩下的聯盟勢力。我收到一份報告，指出妖術之王拉爾的部隊在前面碰上了麻煩。\n\n他宣稱有一陣更濃的霧籠罩了納茲米爾。聯盟一定用了什麼技倆來拖慢我們的腳步。\n\n前往納茲米爾，看看有什麼辦法能夠協助妖術之王拉爾。我們必須抵達艦隊所在地，摧毀聯盟！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54208] = {title = "掃雷機", objective = "在淪陷哨站拆除10個陷阱。", description = "聯盟不但靠著煩人的濃霧延緩我們的行動，而且還在整個區域鋪下了陷阱。\n\n如果我們的部隊貿然穿越滿是陷阱的區域，一定會受到大量傷亡。\n\n我聽說你很擅長暗中行動。善用你的天份，拆除這個區域的陷阱。\n\n你拆除這些陷阱的時候，我會負責從聯盟手中搶回哥布林的零件。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54211] = {title = "哥布林戰隊全員集合", objective = "救出哥布林戰隊。", description = "呦！如果我們想修好A.F.M.O.D.，就必須把其餘的哥布林戰隊隊員找回來！\n\n所以呢，我們的機甲變廢鐵了，還蠻慘的。其他哥布林戰隊還躲在外面，等候一切平安的消息。\n\n拿著這個追蹤器。如果你走到戰隊其中一人身邊，它就會告訴你。當你走到夠近的地方，應該就會看到他們。\n\n那個訊號會告訴附近的隊員現在很安全，可以離開藏身處並回到這裡。\n\n有對的哥布林人選和零件，我們很快就能擊敗聯盟！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54212] = {title = "重新打造A.F.M.O.D.", objective = "從吉爾尼斯伏擊者和夜精靈哨兵手中取回10個A.F.M.O.D.零件。", description = "好吧，我們得穿過這場瘋狂迷霧尾隨聯盟。我們必須重新奪回前方的佐巴爾遺跡。\n\n只要能修好我們的機甲，A.F.M.O.D，那就是小事一椿，因為這可是超殺的飛行機甲！\n\n聯盟的第一波攻擊把它給打壞了，而且還打包帶走了一堆零件。去把那些零件拿回來，我們就有辦法馬上修好這玩意兒！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54213] = {title = "動起來吧！", objective = "與塔蘭姬交談以啟動A.F.M.O.D.。", description = "我們把A.F.M.O.D.修好了，運作完全正常！呃，唯一的問題是它沒有動力。\n\n塔蘭姬公主似乎有辦法協助我們。詢問她是否能讓機甲啟動！\n\n我們一旦準備就緒，就能用這台機器殲滅聯盟，奪回祖爾詹遺跡，反攻炸毀那個艦隊！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54224] = {title = "祖爾詹遺跡之戰", objective = "駕駛A.F.M.O.D奪回祖爾詹遺跡。", description = "洛琪拉將軍已經和軍隊一同推進。除非我們讓這場霧消失，拉爾與他的部隊依然動彈不得。\n\n你必須駕駛A.F.M.O.D，幫助我方部隊奪回祖爾詹遺跡。只有這樣，我們才能繼續前進，阻止聯盟還有這場霧。\n\n洛克漢跟我會加入你。我們必須讓聯盟知道，我們會迅速地取得決定性的勝利。\n\n我要讓敵人在死前向我們跪地求饒。這就是玷汙我們土地的代價。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54225] = {title = "任務報告：大封印", objective = "把任務報告送給納薩諾斯‧凋零者。", description = "你的追隨者送來一份大封印的任務報告。\n\n上面描述了任務成功的細節，而且已經蓋好了任務指揮桌。\n\n把報告交給女妖之嚎艦上的納薩諾斯‧凋零者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54231] = {title = "哨站升級：大封印", objective = "在大封印查看任務指揮桌。", description = "大封印的任務相當成功。做得好，<name>。\n\n現在有一張任務指揮桌可用了。\n\n去大封印那裡，看看部隊的工作成果是否符合我們的標準。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
