MultiLanguageQuestData['tw'][54239] = {title = "任務報告：祖爾詹遺跡", objective = "把任務報告送給納薩諾斯‧凋零者。", description = "你的追隨者送來一份祖爾詹遺跡的任務報告。\n\n內容記載因為任務成功而提高了羅亞之力，現在恩惠可以持續更長的時間。\n\n把報告交給女妖之嚎艦上的納薩諾斯‧凋零者。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54240] = {title = "哨站升級：祖爾詹遺跡", objective = "從祖爾詹遺跡的祭壇上選擇一項羅亞的恩惠。", description = "祖爾詹遺跡的任務相當成功。做得好，<name>。\n\n羅亞的恩惠現在更加強大，而且只要你身處贊達拉，就可以沐浴在它的恩惠下。\n\n前往祖爾詹遺跡，在祭壇上選擇一項羅亞的恩惠。", progress = nil, completion = nil, rewards = nil}
