MultiLanguageQuestData['tw'][54258] = {title = "任務報告：狐狸人藏身處", objective = "把任務報告送給納薩諾斯‧凋零者。", description = "<你的追隨者送來一份狐狸人藏身處的任務報告。\n\n它描述了任務的成功細節，而且現在可以使用商隊了。\n\n把報告送去給女妖之嚎上的納薩諾斯‧凋零者。", progress = "關於狐狸人藏身處的任務，你有什麼消息嗎？", completion = "看來狐狸人藏身處的任務相當成功。做得好，&lt;name&gt;。", rewards = nil}
MultiLanguageQuestData['tw'][54260] = {title = "哨站升級：狐狸人藏身處", objective = "到狐狸人藏身處和商隊老闆談話。", description = "看來狐狸人藏身處的任務相當成功。做得好，<name>。\n\n商隊老闆十分感謝我們的協助，想要回報我們。\n\n前往狐狸人藏身處和商隊老闆談談，看他們能為你做些什麼。", progress = nil, completion = "你一定要相信我，能夠脫離無信者的魔掌，我實在是太高興了！多謝你！\n\n如果你需要商隊送你一程，告訴我們一聲就好。\n\n說真的，現在馬上可以！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54262] = {title = "任務報告：布瑞納丹", objective = "把報告送給海弗德‧龍禍。", description = "<你的追隨者送來一份布瑞納丹的任務報告。\n\n裡面詳細描述他們如何成功取得收割者。\n\n將報告帶給風之救贖上的高階指揮官龍禍。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54263] = {title = "哨站升級：布瑞納丹", objective = "和布瑞納丹的漢克‧哈里遜交談。", description = "布瑞納丹任務相當成功。做得好，<name>。\n\n我們現在已經取得了傳說中速度飛快的收割者讓你搭乘。聽起來好像有點奇怪，我是怎麼知道的？\n\n前往布瑞納丹去詢問關於這項升級的細節。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][54265] = {title = "艾薩拉的命令", objective = "找回薩拉塔斯，並且前往臨時祭壇。", description = "勳章上刻了命令，看起來這些納迦受命入侵海岸，打算奪取有強大力量的聖物。\n\n<卡裘認真的打量你。>\n\n我聽過一些傳聞，有個牧師帶著一把恐怖匕首對抗燃燒軍團。據說這把叫薩拉塔斯的匕首…會告訴他人深淵的秘密。說不定我們能靠它找出納迦的目標。\n\n據說納迦在斯陀頌恩谷地設了一座祭壇。如果你帶薩拉塔斯去那裡，它可能會說出重要的線索。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
