MultiLanguageQuestData['tw'][54282] = {title = "達薩亞洛之戰", objective = "在達薩亞洛之戰的團隊副本中擊敗珍娜‧普勞德摩爾。", description = "贊達拉遭受攻擊！我的人民四下逃竄，聯盟正在我的街道上橫行。\n\n洛琪拉的斥候回報，領導這場攻擊的正是珍娜‧普勞德摩爾。\n\n她和她的人民一定要為這場無恥攻擊付出代價。\n\n召集你的盟友，將聯盟趕回去。我們一定要保護我父親，消滅來犯的聯盟！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54284] = {title = "任務報告：漂流角", objective = "把報告送給海弗德‧龍禍。", description = "<你的追隨者送來一份漂流角的任務報告。\n\n裡面詳細描述他們如何成功取得一門超大火砲。\n\n將報告帶給風之救贖上的高階指揮官龍禍。", progress = nil, completion = nil, rewards = nil}
