MultiLanguageQuestData['tw'][54288] = {title = "哨站升級：漂流角", objective = "到漂流角和火爆傑克交談。", description = "在漂流角任務相當成功。做得好，<name>。\n\n我們取得了一門超大火砲的控制權，保證讓你用最快速度前往提拉加德海灣。幸好我不打算用那種方式繞路。\n\n前往漂流角並詢問這項升級。", progress = nil, completion = nil, rewards = nil}
