MultiLanguageQuestData['tw'][54682] = {title = "消失的利刃", objective = "把薩拉塔斯消失的事告訴安杜因國王。", description = "<薩拉塔斯的回音繚繞不去，雖然潛藏在匕首中的意識消失了，它還是散發一股力量。\n\n你感覺到這武器現在傳來了不同的聲音，有不同的目的…\n\n你覺得必須警告國王，現在匕首可能落在敵人手中。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54683] = {title = "黑暗之刃", objective = "把匕首帶給大酋長希瓦娜斯‧風行者。", description = "<這把曾名為薩拉塔斯的利刃，就在你前方地上。雖然裡頭潛藏的意識消失了，刀身還是散發一股力量。\n\n這武器似乎傳來了另外一種聲音，有著另外的目的…\n\n你決定把這把武器帶給大酋長。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
