MultiLanguageQuestData['tw'][54913] = {title = "天才的靈感", objective = "到風暴群山的發明者圖書館與彌米倫會面。", description = "<name>，我有個好消息！\n\n在薩格拉斯的不幸事件之後，我安裝了幾個偵測中繼點，最近卻被一種能量訊號干擾了！\n\n我需要更多資料才能確認，但是根據初步辨認結果，那股能量來自哈提！我們也許還有辦法救牠！\n\n哈提的靈魂一直和你連繫著，所以我需要你的協助…馬上到風暴群山，在我的圖書館會面！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54915] = {title = "線上遙距勘測", objective = "協助彌米倫找到哈提的精華。", description = "當泰坦之擊的力量在希利蘇斯耗盡時，哈堤設法將自身精華與雷焰切離開來，及時避免遭到摧毀的命運。\n\n唯一的問題就是，牠的精華散落在艾澤拉斯，而且我們不清楚落在什麼地方。\n\n現在既然有了牠的能量訊號，我們應該可以利用三角定位法，鎖定哈提的位置。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54916] = {title = "獵人教條", objective = "在風暴神殿用雷焰吸收哈提的精華。", description = "透過神奇的偉大科學，我可以精確維持雷焰的能量，以達成這個目的。\n\n你只需要進入風暴神殿，把哈提的能量吸收進去就好。只要…有點像是要為他指引方向。\n\n噢，而且要記住，這只是哈提的一部份，所以在壓制他以完成吸收之前，你可能會碰上一些技術性上的困難。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54917] = {title = "付諸鮮血", objective = "在希利蘇斯的世界創口用雷焰吸收哈提的精華。", description = "如果彌米倫的酷炫機器沒算錯，另一半的哈提就在希利蘇斯世界創口附近。\n\n我們必須馬上動身。就算裡面只有部份精華，我還是可以感覺得到他正在快速消失！\n\n這是場漫長的旅程，<小夥子/小姑娘>。我們走吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54918] = {title = "想像的靈感", objective = "使用奧杜亞外的傳送器到彌米倫的工坊和他會合。", description = "為了幫哈提重新構成，我已經轉移了所有不必要的動力，所以我沒辦法把你從此地傳送到奧杜亞。\n\n你這一路上要特別注意雷焰。它充滿了極不安定的能量，只要撞到任何地方，就會導致很嚴重的麻煩！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54919] = {title = "雷霆的羈絆", objective = "重組哈提。", description = "當你把哈提的精華注入雷焰時，我想出了一個完美無缺的計畫，簡直就是科學界的驚世創舉！\n\n我就不拿技術層面的問題來煩你。只要跟著我的指示，哈提就會馬上重現在你面前！\n\n…要不然我們都會爆炸。但我們在追尋知識和拯救我們那毛絨絨的夥伴時，都該不遺餘力…你也這麼認為吧？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n哈提重生\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][54920] = {title = "心繫家園", objective = "到風暴神殿和索林姆會面。", description = "重組程序絕對完美無缺！結果出色無比，而且還有很多資料可供分析！\n\n我不是很確定索林姆想給你看什麼，但你最好馬上前往風暴神殿。如果讓他等太久，他的脾氣會不太好。\n\n你可以用我的傳送器直接到奧杜亞外面。目前常用的出入口…恐怕無法運作。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54922] = {title = "專用螺帽和螺栓", objective = "收集1000個備用零件。", description = "我開始處理腿部零件。這部份的傳動裝置大半是從我們從垃圾堆裡挖出來的備用零件組成。\n\n想修好這個東西，我們肯定需要用到大量的備用零件。看看你能找到什麼。", progress = "幫我拿那些備用零件來！", completion = "做得好，這真是幫了大忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54925] = {title = "真是異端！", objective = "殺死高階教士卡姬拉。", description = "我手下的高等教士躲在他們之間反抗塔蘭姬。這樣的異端令人不齒。\n\n我絕對不會容忍！\n\n<她用手中的長矛對著面前的高等教士。>\n\n這一位很明智的承認了幕後主使的身份，就是我的副手，卡姬拉。\n\n我原本願意聽她說，但是她卻用了其他方式來傳達她的顧慮。現在得好好處理她。\n\n你可以在天選者臺地找到她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54929] = {title = "準備大鬧", objective = "從邦多‧巨塊手中取得十六號伺服電機螺線管。", description = "如果我們想修好這玩意的控制，我們需要一根全新的十六號伺服電機螺線管。\n\n邦多機械場中的幫眾手中可能有一根，但他們通常不怎麼樂於助人。\n\n和邦多談談，看你能不能幫我們弄根回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54930] = {title = "機械解放", objective = "在鱗牙哨站釋放機械魔像。", description = "既然你成功打斷了我的小睡，表示我的警戒功夫還不到家。\n\n都是因為塞斯拉克，除了偷走了我的機具和電器之外，還偷了我的機甲！那些白癡連鑰匙都沒拿！\n\n<葛利吉斯大笑>\n\n來，拿著我的鑰匙，把我的機甲弄回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54933] = {title = "釋放聖光", objective = "使用聖光之子的聖光，驅散附近的死靈能量。", description = "啊…你和巨魔不是一夥的。拜託，你一定要幫我。\n\n我被黑暗魔法強制束縛在這個地方。我懇請你釋放我。\n\n拿一片我的聖光。用它驅散持續把我囚禁在此處的死靈能量。", progress = nil, completion = "感謝你的協助，&lt;name&gt;。我必須離開這個世界了，但祝你好運。\n\n帶著我的祝福吧。希望可以協助你對抗這些怪物。", rewards = "您會學到：\n\n聖光之速\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][54938] = {title = "兄弟的協助", objective = "前往納茲米爾，在奧迪爾外面與麥格尼會面。", description = "我們需要所有能動用的幫手來拯救這顆星球。\n\n我有個點子。\n\n去納茲米爾的黑暗之心外面和我碰面。我們得同心協力，找到可以幫助我們的人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54939] = {title = "如銅鬚般頑固", objective = "搭乘布萊恩的飛行器進入奧迪爾。\n\n如果你迷路了，使用奧迪爾入口外面的傳送器。", description = "這個提議很有布萊恩的風格，但如果我也坐上去，這台飛行器就會像石頭一樣掉下去。最好只載你們兩個就好。\n\n布萊恩會載你飛到奧迪爾。我自己會找路到裡面和你會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54940] = {title = "不可或缺的母親大人", objective = "帶著麥格尼會面母親大人，並啟動甬道之門控制臺", description = "雖然我是艾澤拉斯的代言者，但是布萊恩才是泰坦考古學的專家。如果他說母親大人能幫助我們拯救艾澤拉斯，那我絕對相信她。\n\n來吧，勇士。我們聽聽她能提供什麼建議。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54941] = {title = "灘頭偵查", objective = "在灰燼灘頭找到安寇恩斥候。", description = "位於哨站的我方斥候，已經好一段時間沒有送消息回來了。\n\n他們可能是因為納迦攻擊的關係，所以無法和我們連繫。我得去瞭解一下他們的情況，並掌握納迦軍隊最新的動向。\n\n你應該和我一塊來，對你而言，這是個與更多氏族成員會面的大好機會，還可以近距離觀察我們的行動方式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54945] = {title = "動工修復", objective = "修理裝置。", description = "我推測這東西是個通訊轉繼點。它目前停擺了，但只要靠地精的足智多謀再加上有你當後盾，應該可以馬上解決這個問題！\n\n我需要你幫忙讓這個裝置恢復運轉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54946] = {title = "向吉菈報到", objective = "在波拉勒斯和吉菈‧交線會面。", description = "機械岡國王認為我有足夠的價值，真是太幸運了！\n\n我會派出我的助理吉菈‧交線前往波拉勒斯集結一支新隊伍。到那邊和她會面，努力幫助她吧。\n\n我很快就會加入你們兩位的行列。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54947] = {title = "小隊編制", objective = "集結隊伍成員。", description = "想要在機械岡的遠征隊中存活下來，我覺得隊伍成員一定要具備一項極為重要的特質。\n\n那個特質就是…身為地精！\n\n集結這些地精並到起飛點，向技工大師歐沃斯巴克和我報到。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54949] = {title = "餵飽更多張嘴", objective = "收集30塊鉗殼龜肉。", description = "納迦的攻擊簡直是無休無止，幾乎沒時間外出狩獵食物和補給品。\n\n你帶了許多士兵來到我們的營地，所以我們得抓緊每一個打獵的機會，否則糧食一下子就吃完了。", progress = "從這場狩獵中獲得的肉品足以滋養我們的身心。", completion = "想要讓疲累的士兵打起精神、回復全身的力氣，還有什麼比這種鮮肉來得有效！", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][54951] = {title = "緊急救助", objective = "在奧斯汀‧哈克斯沃、畢雍‧壯手和基拉身上使用急救包。", description = "在著手搜尋我的…搜尋失蹤的遠征隊之前，我們得先幫大家治療。\n\n拿好這個急救包去照顧傷者。別拋棄任何人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n空的急救包"}
MultiLanguageQuestData['tw'][54952] = {title = "搜尋失蹤的遠征隊", objective = "搜尋附近的營地，找出遠征隊倖存者。", description = "我在前方的殘骸附近看到一些火光。我們應該前去調查，看看是否還有倖存者。\n\n你是新兵裡面最菜的，你跟我一塊走。其他人會在島上搜尋線索。\n\n我們走。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54958] = {title = "夜間航行", objective = "搭乘船隻前往迅捷復仇號並找到德瑞克‧普勞德摩爾。", description = "希瓦娜斯這回太過份了。就算我們與聯盟在打仗，還是有些我們絕對不能跨越的界線。\n\n我一定要導正這個情勢，可是我需要你的協助。德瑞克‧普勞德摩爾被關在迅捷復仇號上，目前正停泊在這裡的港口進行補給。\n\n我們一定要帶著他回到家人身邊。你願意和我來嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54959] = {title = "鎖頭與鑰匙", objective = "在迅捷復仇號上收集船長的鑰匙、藥劑師的鑰匙和領航員的鑰匙，然後用它們打開強化牢籠。", description = "三把鑰匙？看來希瓦娜斯不信任他們，因此把普勞德摩爾的鑰匙分散到不同人身上。\n\n如果我們打不開這座牢籠，就別想救出德瑞克‧普勞德摩爾。\n\n在我們清理這艘船的過程中，留意任何鑰匙。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54960] = {title = "苦澀的重聚", objective = "和湯瑪斯‧澤靈交談，朝著塞拉摩出航。", description = "我們成功了！澤靈會讓船航向塞拉摩，現在我們可以解決這件令人作噁的事情，一勞永逸！\n\n在你準備離開時，和澤靈交談，我們就出航。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][54961] = {title = "矯正過錯", objective = "在提拉加德海灣的劫掠港與貝恩‧血蹄會面。", description = "勇士！貝恩‧血蹄要我向你轉達緊急的請求。他請你到劫掠港和他會面談論一個…敏感情況。\n\n這個請求請務必向所有人保密，<class>。\n\n願先祖護佑你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54964] = {title = "通往核心的單程票", objective = "帶母親大人撤離奧迪爾", description = "這些泰坦設施每次都讓我很驚訝。我不知道他們還有多少布萊恩沒有發掘的秘密。\n\n我只希望其中握有拯救艾澤拉斯的答案。\n\n是時候帶母親大人去心之室了。勇士，做好萬全準備。你永遠都不知道開啟泰坦機械會發生什麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54965] = {title = "支離破碎的機器人", objective = "已經將12個再度活動的機器人送去給波爾頓‧簧火。", description = "我的工作就是切碎機器人。你帶來的任何機器人都會在廢料機中打碎成有用的零件。這是我們的雙贏！\n\n使用機器人充能器把壞掉的機器人帶來給我，我們就可以將他們打碎成備用零件。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][54969] = {title = "送你一程", objective = "跳下瀑布。", description = "我們已經失去大部分的兵力。再有損失，我們就會無法作戰。\n\n這殘骸是擋不住納迦的，我們不能繼續待在這裡了，必須去找掩護。\n\n$p，你現在必須相信我，從瀑布跳下去吧，你會安全降落的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54972] = {title = "回家的路", objective = "協助珍娜開啟一個通往波拉勒斯的傳送門。", description = "我們之所以能活下來，都要多虧安寇恩的解救，以及艾薩拉把我們當玩具耍的渴望。\n\n我們以後會更瞭解歐卡尼的人民，這點我很肯定。\n\n現在，我們必須建立一個回家的傳送門，雖然艾薩拉封鎖了我們傳統的魔法旅行管道，但我可以感應到強大的能量正在這附近匯聚。\n\n我認為，我們可以用它來開啟回家的路。", progress = nil, completion = "我們十分幸運，能遇上安寇恩。或許事情並不如表面上那麼悲觀。", rewards = "第七軍團士兵長袍第七軍團士兵外衣第七軍團士兵襯肩第七軍團士兵兜帽第七軍團士兵披肩第七軍團士兵面具第七軍團士兵護肩第七軍團士兵頭盔第七軍團士兵鍊甲第七軍團士兵重肩甲第七軍團士兵首盔第七軍團士兵護胸您會收到：\n\n"}
MultiLanguageQuestData['tw'][54975] = {title = "短暫的歇息", objective = "支援你在納沙塔爾的盟友，讓其中一位升到等級3。", description = "我們有許多事情要做，<name>。不過我們精疲力盡、需要休息。在疲累時下的決定，幾乎都是錯的決定。\n\n安寇恩向我們敞開家門，但他們幾乎無力自保。我們應該在想出下一步的這段期間，盡一切力量支援他們。\n\n看你能在他們的狩獵隊伍中提供什麼樣的協助。這可能是我們在這個地方生存的唯一方式。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n明晰之夢珍珠艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54976] = {title = "吉爾尼斯的陰影", objective = "到暴風要塞與泰絲‧葛雷邁恩會面。", description = "吉爾尼斯的勇士！\n\n我為你送來一封泰絲‧葛雷邁恩公主的信件。她要你立刻前往暴風要塞。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n吉爾尼斯的傳承\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][54977] = {title = "深入暮色森林", objective = "到暮色森林與維珊卓拉‧風爪交談。", description = "我曾在泰達希爾見過一位夜精靈，這位維珊卓拉‧風爪或許可以教導泰絲，且不會訴諸於如此極端的手段。她最早的時候就有在幫我們的同胞抒解痛苦了。\n\n維珊卓拉目前正在暮色森林協助烏鴉嶺的居民，治療當地充滿野性的狼人。想要找一個最瞭解詛咒的人，非她莫屬。\n\n在此提出一個比較私人的請求，請不要讓我女兒魯莽行事。她這點像極了她父親。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54978] = {title = "力挽狂瀾", objective = "在庫爾提拉斯、贊達拉、納沙塔爾、奧丹姆或恆春谷的任何地方殺死25位50級以上的部落成員。", description = "根據報告，庫爾提拉斯和贊達拉兩地的部落兵力具有壓倒性的優勢。\n\n以數量壓制聯盟，可是部落方的老把戲，不過這次我們不會讓對方得逞。\n\n盡你所能，在各地削減敵人數量。建議你帶著援軍一同前往。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩征服點數"}
MultiLanguageQuestData['tw'][54979] = {title = "力挽狂瀾", objective = "在庫爾提拉斯、贊達拉、納沙塔爾、奧丹姆或恆春谷的任何地方殺死25位50級以上的聯盟成員。", description = "看來由於我們過度放任，讓聯盟兵員人數壯大到變成一個問題。如果這些報告無誤，對方兵力幾乎多到不管我方哪個據點都擋不住的地步。\n\n<class>，快點準備一下，帶幾個你信任的盟友去削減聯盟兵力！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54980] = {title = "夜行狼人之禍", objective = "制伏血眼，並帶著她返回烏鴉嶺。", description = "葛雷邁恩公主把目前的狀況告訴我了，我的確有辦法。\n\n但首先你得先幫我忙。夜行狼人群最近出現了一位特別兇殘的成員，一直在攻擊暮色森林的居民，人們稱之為「血眼」。帶著哈里斯先生的鎮靜劑，把那頭狼人活捉回來。她會成為完美的測試療法受試者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54981] = {title = "對月嚎叫", objective = "收集伊露恩的恩典花朵。", description = "暮色森林與翡翠夢境有直接連繫。透過這樣的連繫，我或許能召喚先祖戈德林。他可以讓公主試試看，她不惜冒險也要追尋的詛咒是什麼樣子。\n\n有一種罕見的花朵生長在森林東側，收集花朵，然後到暮光森林和我會合。這可以協助我完成儀式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54982] = {title = "獵人之靈", objective = "取得霧牙狼群身上的尖牙。", description = "為了這個儀式，我需要的另一個東西是狼牙。\n\n最近有群狼在密斯特曼托莊園附近落腳，把牠們的尖牙帶來給我。我會在暮光森林等你回來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54983] = {title = "喚醒夢旅者", objective = "在維珊卓拉‧風爪召喚戈德林時保護她。", description = "召喚先祖的材料都準備好了。\n\n剛開始可能有些不請自來的訪客回應召喚。在我舉行儀式時保護我！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54984] = {title = "別吵醒沉睡的狼", objective = "進入夢境之門並為泰絲引路。", description = "我扭曲了一部份的翡翠夢境並連接到泰絲的精神世界，讓她的精神體在其中徘徊。雖然我已經把贈禮交給她了，但她還是需要一位嚮導。\n\n從我背後的傳送門進入夢境。我會把你送到她沉睡的地方。看看你能不能讓她看清，怒火如何讓凡人陷入盲目。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54986] = {title = "恩若司的幻象獎勵", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n[PH] N'Zoth Cache"}
MultiLanguageQuestData['tw'][54990] = {title = "新上任的衛兵", objective = "到暴風要塞與泰絲‧葛雷邁恩會合。", description = "我得再和父母談談。我想我父親和我有點事要討論。\n\n到暴風要塞和我會面。我想用比較正式的禮儀來感謝你。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n吉爾尼斯的傳承\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][54992] = {title = "冰山現一角", objective = "登上遠征隊旋翼機", description = "旋翼機上面的座標鎖定好了。你和上尉撬簧帶頭飛行。技工大師歐沃斯巴克希望能讓經驗最老道的飛行員帶頭，解決任何麻煩。\n\n你一準備完，就登上旋翼機吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54995] = {title = "穿越時光的破碎之路", objective = "完成5次時光漫遊地城冒險。", description = "兇蠻之星在大地上空閃耀，將對行經之路的一切事物造成莫大威脅。這顆星星象徵著許多事物：獸性、兇殘與尊貴。在它的影響下，有可能開啟全新道路、通往遠方，甚至通往另一個時間。沒有任何智者能夠確實瞭解這個自然跡象，但財富將會眷顧於果敢之人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][54997] = {title = "水中喋血", objective = "在迅捷復仇號上，擊敗6名船員。", description = "救出普勞德摩爾之後，我們還得佔領這艘船、把他送到塞拉摩，他的妹妹會在那邊等候。\n\n澤靈的魔法會引導這艘船抵達定點，不過我們得先解決船員。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][54999] = {title = "掛羊頭賣狗肉", objective = "展開「拋餌」任務，並且在贊達拉港登上女妖之嚎，向納薩諾斯‧凋零者報到。", description = "如果我們想力挽狂瀾，就要轉移希瓦娜斯的注意力。我會把船開到置燭碼頭附近，那個地方最近落入了鐵潮海盜的手中。到了之後，我會讓它看起來像是遭到海盜蹂躪的樣子。\n\n你的工作就是確保希瓦娜斯的部隊找到這艘船。\n\n你得向納薩諾斯回報你在那個區域發現了一艘被遺忘者船隻。你和德瑞克‧普勞德摩爾沒什麼連繫，所以應該不會招惹疑心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55003] = {title = "來打架啊", objective = "在畢茲摩鬥陣俱樂部贏得3場戰鬥。", description = "對了。\n\n<指揮官放下手中的筆記本>\n\n我的調查小隊需要一個厲害的<class>。我們最近人員短缺，老實說，我也沒人手可以找了。\n\n在這之前，你要不要進去競技場打個幾場，讓我見識一下你的技術如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55005] = {title = "財務投資獎勵", objective = "從溫尼費德‧布朗尼領主的猜猜樂中贏走100枚鬥陣金幣。\n\n如果賭局還沒開始，可以向烏拉妮購買賭豪合約。", description = "我看到布朗尼領主在那裡開了賭局，要人猜誰會勝出，贏家可以得到鬥陣金幣。\n\n你去看看能不能找出賭局的規則。如果你贏到足夠的錢，他可能就願意開口了…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55008] = {title = "證據包：溫尼費德‧布朗尼領主", objective = "把證據包帶去給指揮官達洛。", description = "我全都聽到了。那傢伙大聲宣揚他犯的罪和欠了多少債，對吧？\n\n看來我們有辦法質問他了。我準備了一袋證據給指揮官達洛。\n\n你做得不錯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55010] = {title = "靈魂破片", objective = "在打鬥者獎金袋中尋找「有靈魂」的東西。\n\n在畢茲摩鬥陣俱樂部獲勝的人可以得到打鬥者獎金袋。某些類型的獎金袋可能有更多東西。", description = "<歐弗蘭諾提在自言自語。>\n\n啊，真是亂七八糟…它又餓了。我要去哪裡找這麼多靈魂餵它？噢…如果我能偷那些打鬥者獎金袋…\n\n<他注意到你。>\n\n噢！嗨呀！剛剛是我這個清白的術士在亂發牢騷，沒什麼可疑的！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55011] = {title = "超級靈魂破片", objective = "從格鬥者獎金取得3個超級靈魂破片，從格鬥中勝出可以獲得格鬥者獎金。\n\n格鬥是多人的團隊戰鬥，畢茲摩鬥陣俱樂部的所有決鬥者一起對抗強大的敵人。任何人都能向烏拉妮購買格鬥卡以發起格鬥。", description = "<歐弗蘭諾提又開始自言自語：>\n\n但是這些夠大嗎？它現在這麼渴望靈魂，如果沒辦法滿足它，它會生氣，我們可不想看到降在暴風城中間。天啊、天啊…\n\n<他注意到你在附近徘徊。>\n\n噢！那個<race>還在啊！嘿嘿，別管我！沒什麼邪惡的事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55023] = {title = "畢茲摩鬥陣俱樂部等你來！", objective = "攜帶邀請函至畢茲摩的鬥陣俱樂部。\n\n已提供物品：\n", description = "對又老又窮的貿易區感到厭倦了嗎？不如來畢茲摩鬥陣俱樂部，用打鬥來帶來歡樂吧！\n\n你可能贏，也可能會慘死，但無論結果如何，你都會有一段美好的體驗。\n\n帶邀請函去找門口附近的韓‧重掌吧！鬥陣俱樂部，歡迎來挑戰！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55028] = {title = "這是回收工作…", objective = "在廢棄垃圾堆對死亡的V-300哨兵犬使用線圈電流收集器，然後使用線圈電流收集器取得鎖在強化結構圖寶箱裡面的超U質扳手結構圖。", description = "<name>，很高興你能來。\n\n不管是能用來製作強大建構體的超U質扳手還是它的結構圖，都已遺失多年。情報指出這份結構圖曾經出現在廢棄垃圾堆的上鎖儲藏箱裡。\n\n你得讓它的電力屏障超載才能夠開啟。帶著我的電流收集器並從當地的哨兵上面吸取一些電流，然後把箱子轟開！\n\n<蕾拉用手指比了個手槍的樣子並發出爆炸聲>\n\n想來場尋寶遊戲嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55030] = {title = "藍圖：廢料陷阱", objective = "將藍圖上傳至帕斯卡K1N6型的資料庫。\n\n已提供物品：\n", description = "<這張藍圖詳述了如何製作某種地雷，但只需要用到一些金屬碎塊。\n\n你應該可以將藍圖上傳至帕斯卡K1N6型在鏽栓鎮的資料庫。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上傳：廢料陷阱\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][55031] = {title = "這是回收工作…", objective = "在廢棄垃圾堆對死亡的V-300哨兵犬使用線圈電流收集器，然後使用線圈電流收集器取得鎖在強化結構圖寶箱裡面的超U質扳手結構圖。", description = "<name>，很高興你能來。\n\n不管是能用來製作強大傀儡的超U質扳手、或是製作的方法都已消失多年。情報指出，之前這份結構圖就在廢棄垃圾堆的上鎖儲藏箱裡面。\n\n你得讓它的電力屏障超載才能夠取得結構圖。帶著我的電流收集器去吸取當地哨兵體內潛藏的電流，然後把箱子轟開！\n\n<咻嘎用手指比了個手槍的樣子並發出爆炸聲>\n\n準備好來場尋寶之旅了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55032] = {title = "解放反抗勢力", objective = "釋放6名龍蝦人奴隸。", description = "納迦奴役了一支龍蝦人部族，並將他們當成一群毫無思考能力的奴隸，派他們做苦工。\n\n就算納迦部隊人多勢眾，但是龍蝦人的體型和力量都佔優勢。\n\n如果我們能讓龍蝦人擺脫控制，他們一定會全力反撲納迦監督者，讓艾薩拉女王的計畫橫生枝節。", progress = nil, completion = "納迦絕對擋不住我們釋放出來的龍蝦人囚犯。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][55033] = {title = "讓艾胥凡化為灰燼", objective = "在自由港殺死艾胥凡忠誠者。", description = "這個地方就是艾胥凡忠誠者的聚集地，<name>。\n\n我們要不要幫庫爾提拉斯人一個忙，解決掉幾個。\n\n<凱爾希露齒而笑。＞\n\n我在到這裡來的路上已經開始動手了，但附近還有一大堆！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55034] = {title = "掛羊頭賣狗肉", objective = "展開「拋餌」任務，並且在贊達拉港登上女妖之嚎，向納薩諾斯‧凋零者報到。", description = "如果我們力挽狂瀾，就得轉移希瓦娜斯的注意力。你得派你的手下搭船前往置燭碼頭，讓他們把它偽裝成遭到海盜洗劫。\n\n你的工作就是確保希瓦娜斯的部隊找到那邊的船隻。\n\n你得向納薩諾斯回報你在那個區域發現了一艘被遺忘者船隻。你和德瑞克‧普勞德摩爾沒什麼連繫，所以應該不會招惹疑心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55036] = {title = "可怕的地方", objective = "完成一場恩若司的幻象。", description = "你可能已經注意到，艾澤拉斯各地出現了種種紛擾。上古之神正在崛起，對我們所有人而言，這都是壞消息。\n\n這種無盡真理之柱會在偶然的情況下出現。這名字真神奇，你不覺得嗎？我很擅長幫事物命名。\n\n我剛剛講到哪邊了？噢，對沒錯，這些柱子可以讓我們進入古神的意識。它們會讓你看到一段暗示，瞭解接下來會有什麼東西迎面而來，以及我們沒擊敗他的話世界會變成什麼樣子。\n\n你願意親自看看嗎？", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][55039] = {title = "造船專家", objective = "取得來自海軍總帥的信，並在布瑞納丹和塞勒斯‧克瑞斯福會面。", description = "我現在想起來了…\n\n朵莉安‧艾特瓦特是位保密至上的建船匠。他們最出名之處就是用結界阻止任何人窺探他們的造船工作。所以每當他們的作品現身時，都會引發一陣騷動。\n\n我最後聽到的消息是，他們退休之後住在斯陀頌恩谷地，但是我不確定這個消息有多可靠。\n\n嗯，我們應該去一趟布瑞納丹，許多路在那裡交會，如果有人知道上哪裡去找我們的造船匠，肯定就在那邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55040] = {title = "查看內部", objective = "進入保險庫。", description = "這座保險庫一定藏有地精科技！我相信這一定是帶領我們找到機械岡國王的關鍵！\n\n不過，我不能身入險地，就由你帶頭進入保險庫。\n\n好啦，我們還在等什麼？我們來看看裡面有什麼東西！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55043] = {title = "遠航聽人吹牛去", objective = "在布瑞納丹打聽船匠的消息。", description = "對於從何處著手，我有一個想法，但是問問本地人也不錯。\n\n我想用不著提醒你打聽到的消息不需要盡信，<name>。我的族人在加油添醋這方面的本事，絕對是毋庸置疑。\n\n在你有機會四下打聽的時候，我到金酒瓶和你碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55044] = {title = "不斬來使", objective = "傾聽瓦麗拉的訊息。", description = "當瓦里安國王還是一位名叫洛戈許的鬥士時，他與瓦麗拉‧桑古納爾一塊奮戰。他對她無比信任並容許軍情七處和她之間維持著一種…真誠的關係。瓦麗拉的忠誠也轉移到安杜因國王身上。\n\n在對抗軍團的戰鬥中，我才瞭解她可以處理…獨立行動。她可以深入一些我部份探員無法觸及之處。\n\n我們應該聽聽她帶來的消息。我可以想像這個消息來源會很有意思。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55045] = {title = "哥哥的守護者", objective = "與珍娜一塊啟航，並在塞拉摩附近海岸與貝恩會面。", description = "瓦麗拉說這不是陷阱，雖然我相信她，可是我認為部落一定會暗中動手腳。\n\n<name>，我需要你與我同行。我願意與貝恩會面，但我不會孤身前去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戰爭物資艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55047] = {title = "固守戰牙堡", objective = "到斯陀頌恩谷地的戰牙堡與米達老闆會面。", description = "<name>，黑暗女王有件很重要的工作要交給你辦。\n\n戰牙堡已經在為部落領袖的會談加強戒備。我想我不需要強調這一次聚會的安全警戒被拉到最高層級。\n\n加里維克斯那個哥布林派了他手下的爪牙去掃盪這個區域，免得有任何…不速之客。我需要你去確定他們有乖乖完成任務。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55048] = {title = "間諜遊戲", objective = "在大切口使用電子混亂投射器讓10位軍情七處的間諜現形並加以擊殺。", description = "聯盟肯定聽到風聲，然後派出軍情七處的間諜想竊聽這次會面的內容。\n\n問題在於他們用了某種地精科技避開我們的偵測器。只要運用我方某種科技，應該可以製造什麼東西來對抗他們使用的技術，但是範圍很短。\n\n我需要你帶著它進入原野，然後尋找軍情七處的活動證據。你覺得他們在附近時，只要猛按這東西上的按鈕，就可以把他們電到不得不現身。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55049] = {title = "破壞通訊", objective = "在戰牙堡附近摧毀3個軍情七處監聽設備。", description = "看來軍情七處帶到戰場上的不只是潛行裝置。從我方斥候回報看來，在戰牙堡附近的關鍵地點，設置了一些像是監聽設備的東西。\n\n當然了，這些東西非清掉不可，但拜這些看不到的間諜所賜，我們的嘍囉無法靠近。\n\n趁你人在外面，順手教訓一下他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55050] = {title = "請出示票券？", objective = "從戰牙堡趕走5位沒有門票的觀眾。", description = "還有一個問題需要你幫個忙，<class>。\n\n加里維克斯很清楚這場會面有多麼盛大，所以他當然想要賣門票。問題是我剛剛清點人數，這裡的人頭比賣出去的票還多，所以有些觀眾想看免錢。\n\n我們的打手都跑到大切口死在聯盟間諜手中，所以我們需要點幫手。想不想老老實實賺筆錢？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紀念票卷"}
MultiLanguageQuestData['tw'][55051] = {title = "展示權力", objective = "和納薩諾斯‧凋零者交談，見證在戰牙堡的領袖會議。", description = "看來所有要角在此齊聚一堂了。這場盛會馬上就會開始。\n\n你應該去找個好位置。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55052] = {title = "固守戰牙堡", objective = "到斯陀頌恩谷地的戰牙堡與米達老闆會面。", description = "<name>，黑暗女王再次需要你的效力。\n\n叛徒貝恩已經被帶到了戰牙堡，面對所有的領袖。在我們交談的同時，已經開始進行固守該地的準備工作。\n\n這些工作主要是由加里維克斯的手下進行，我覺得這些傢伙連個狗窩都看不緊。你將前往戰牙堡，把那個地方守得密不通風。\n\n我們都靠你了，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55053] = {title = "回家的路", objective = "協助歐庫雷斯開啟通往祖達薩的傳送門。", description = "我們可以運用其中蘊藏的力量，開啟通往家鄉的傳送門。\n\n我需要你的協助。很有趣不是嗎？你居然成了我的助手！\n\n啊，沒錯，跟我過來，你唯一需要做的，就是拿著你的艾澤拉斯之心揮一揮，剩下的交給我就好。", progress = nil, completion = "成果相當完美！", rewards = "榮勛軍團工藝師長袍榮勛軍團先鋒鍊甲榮勛軍團先遣騎外套榮勛軍團工藝師襯肩榮勛軍團工藝師面罩榮勛軍團先遣騎肩衛榮勛軍團先遣騎首盔榮勛軍團先鋒肩衛榮勛軍團先鋒顱甲榮勛軍團百夫長重肩甲榮勛軍團百夫長巨盔榮勛軍團百夫長胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][55054] = {title = "劇變", objective = "和瀑布頂端的首席傳送師歐庫雷斯說話。", description = "我們附近都是傷亡人士和其他殘骸。\n\n感覺就像戰爭一樣，對嗎？\n\n歐庫雷斯和其他人已經先行一步，去探望士兵。\n\n或許你也應該去看看他們？", progress = nil, completion = "不用擔心，&lt;name&gt;。我也不會一聲不吭就用魔法把你送到海裡！不過，我想我們已經在海裡了，對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55055] = {title = "打造更大的捕魚陷阱", objective = "打造百噚誘餌。", description = "靠這些小鯉和一些備用零件，你應該可以打造出一具百噚誘餌。\n\n到鏽栓鎮去找帕斯卡K1N6型並打造出一枚。\n\n然後回到這裡，我們來撈大魚！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n百噚誘餌"}
