MultiLanguageQuestData['tw'][55087] = {title = "風暴集結", objective = "到波拉勒斯附近的普勞德摩爾城堡向珍娜‧普勞德摩爾報到。", description = "我在處理納迦入侵時，普勞德摩爾女士正打算前去對付斯陀頌恩谷地的部落，並找出我方間諜在那邊出了什麼事。\n\n你可以在普勞德摩爾城堡附近找到她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55088] = {title = "戰地失聯", objective = "在斯陀頌恩谷地協助負傷的間諜。", description = "當肖爾和我抵達此地時，發現我方大多數的探員都死了。大多數，不是全部。\n\n踏入戰場並找出我方的戰地探員。他們可能更瞭解部落在戰牙堡的計畫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55089] = {title = "搶救肖爾大兵", objective = "在戰牙堡上方的哀嚎陷坑找到馬迪亞斯‧肖爾。", description = "嗯。肖爾說過，只要恢復通訊就會向我們回報，結果卻無聲無息。他可能和其他間諜一樣，碰到類似的麻煩。\n\n我會留在這邊守住監聽哨。你去找肖爾，他原本朝著戰牙堡上方、瀑布頂端附近的峭壁出發。不知道為什麼，那些苦工把那個地方叫做「哀嚎陷坑」。我敢說那一定是個好地方。\n\n不管他對抗的東西是什麼，幫我從背後捅一刀，好嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55090] = {title = "大敵集結", objective = "觀察部落的集會。", description = "在我受到擾亂之前設法查明了這次部落集結的詳細情報。希瓦娜斯召集了部落領袖與其盟友。至於他們有什麼目的，我說不上來。\n\n想要擊倒她，我們的準備尚且不足 - 她身邊的防護太過周全。不過，或許我們可以進一步探查，找出日後對戰事有助益的情報。\n\n行事小心，機靈一點。我會盯緊其他的守衛。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55092] = {title = "力量干擾", objective = "到艾薩拉之矛摧毀5個地脈蓄電池。", description = "納迦發掘附近地脈所蘊藏的力量，並找到方法運用這股力量。\n\n摧毀他們的裝置，別讓他們用這股力量對我們不利。", progress = nil, completion = "希望我們永遠不會發現，他們汲取這些力量的目的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55094] = {title = "保持低調、動作快一點！", objective = "跟隨奈莉‧銳鰭。", description = "這條路徑直通我們的家園。我們必須小心一點。\n\n奈莉生存法則第六條：隨時做好準備！\n\n我們走！", progress = nil, completion = "總算可以稍微鬆一口氣了。但我們不能大意，艾薩拉的詭計肯定比我們知道的還多。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55095] = {title = "劇變", objective = "在瀑布上方與珍娜‧普勞德摩爾女士說話。", description = "喪失了那麼多人命…納迦的襲擊還永無止盡！\n\n我向你道歉，$p，這不是國王該有的態度。\n\n我們沒時間慢慢思考自己的困境了。\n\n我們去和珍娜見面，從這危險的地方躍入未知的領域吧。", progress = nil, completion = "終於有好消息，我們的勇士已經從混亂中甦醒了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55096] = {title = "送訊給吾父", objective = "駭入一具投影器，打出鏽栓反抗軍的紋章並保護它。", description = "我的人民再次免於危機…至少目前為止。\n\n只要機械岡國王覺得我們好欺負，就會不斷派兵過來。\n\n我們必須讓他知道我們不是好惹的。\n\n爬上堡壘頂端，然後駭入我父親的一台投影器，讓鏽栓反抗軍旗幟以帥氣的姿態飄揚在整座島上。\n\n我敢打包票，這一定會吸引我父親，機械岡國王的注意。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55101] = {title = "廢料場工程和你", objective = "用帕斯卡K1N6型製作一枚廢料手榴彈。", description = "看啊，傳說中的帕斯卡鏽栓工坊 - 我的工坊！\n\n無數發明就在這個地方化為現實，包括我最棒的發明，帕斯卡K1N6型！\n\n帕斯卡K1N6型能造出任何東西…只要你手上有藍圖。\n\n托你的福，才能讓K1N6型平安的回到鏽栓，你想不想知道如何存取他的藍圖資料庫？", progress = "記住，你可以從機械岡的任何東西上面收集備用零件。", completion = "帕斯卡K1N6型是神奇的廢料場工程結晶！現代奇觀！\n\n我有沒有提過他是我獨立發明的？我一定講過了。", rewards = "您會學到：\n\n上傳：廢料手榴彈\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][55103] = {title = "構想來自四面八方", objective = "在機械岡尋找可以為你啟發1個新點子的人或事。", description = "我們第一次見面時，我沒留意到你內心洋溢著技工火花。\n\n但是，我看過你找來上傳到帕斯卡K1N6型資料庫的所有藍圖。\n\n我錯了。而且我很高興我犯了這個錯，我的新進垃圾場工程學徒！\n\n不過，這是你在創意發展方面的危險時刻。\n\n你絕對不能志得意滿！\n\n放下手頭的工作去尋找新創意。去和啟發你的建築師、島上的逆向工程機器人談談，並開啟全新的想法，不管這些點子是怎麼來的！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n發想全新的發明\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][55111] = {title = "生物研究：贊季爾納迦", objective = "使用梅丁的卷軸，收集關於納沙塔爾裡各種生物的資料。", description = "<魔法卷軸上潦草地寫著梅汀對於贊季爾納迦的不完整筆記。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n生物手冊：贊季爾納迦稜光法力珍珠"}
MultiLanguageQuestData['tw'][55116] = {title = "取得線索", objective = "殺死霍頓‧法蘭西斯，以取得他的密碼解譯器。", description = "我敢打賭那頁胡說八道的內容是加密訊息。我們可以把它送回暴風城，由我們的破譯人員進行解譯，或是我們直接打破幾個人的腦袋，把密碼解譯器找出來。\n\n我想我們不如省點時間，就這樣做吧。\n\n那個負責的傢伙可能握有我們想要的東西。不如你去解決他，並看看能不能找到什麼。就算你什麼都沒拿到，少了領袖的忠誠者也無法造成多大的麻煩。這是個雙贏策略！\n\n嗯，我想對我們來說是這樣啦。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55117] = {title = "信件解密", objective = "查明艾胥凡女士計畫的相關資訊。", description = "我想艾胥凡曾經和她的忠誠者連繫，但我不清楚他們接到什麼命令。\n\n進入他們的營地，看看你是否能看懂他們的信件。我們可能要找出某些東西，才能帶領我們查出艾胥凡女士的藏身處，或是下一步有什麼打算。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55118] = {title = "收拾麻煩", objective = "到自由港與凱爾希‧鋼火會面。", description = "我們對抗部落的戰役漸居上風，但還是有些螺絲得上緊一點。\n\n艾胥凡女士已經從托達戈爾逃獄了，是部落幫了她一把。我們不知道她在哪裡，也不清楚她在策劃些什麼。我派凱爾希出去追蹤幾個艾胥凡的忠誠人士。她找到他們的行蹤並請求援助。\n\n她正在自由港等候。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55119] = {title = "報到！", objective = "到波拉勒斯向海弗德‧龍禍報告。", description = "嗯，看來艾胥凡已經好一段時間沒連繫了，但這位「顧客」可能是個麻煩。\n\n你今天的表現很出色，<name>。那些忠誠者可能好一段時間都不敢惹麻煩了，嘿嘿。\n\n我準備回程，你把這封信帶給高階指揮官。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55121] = {title = "馬爾迪瓦司實驗室", objective = "啟動馬爾迪瓦司實驗室的元素精華。", description = "<有幾頁全是關於某種實驗的註記，隨後是一段匆促寫成的日誌。>\n\n終於，我關於基礎元素之研究已開花結果！\n\n小心地使用正確的基礎材料，再加上一點奧秘力量，我已成功結合元素的精華並創造出生命！\n\n我們還需要進一步的調查，來判別混合哪些元素會產出何樣生命！\n\n<文字至此結束。>", progress = nil, completion = "&lt;系統的魔法似乎已乾涸。或許過一段時間後，它就能再度使用。&gt;", rewards = "您會收到：\n\n稜光法力珍珠稜光法力珍珠"}
MultiLanguageQuestData['tw'][55122] = {title = "瘋狂魚人", objective = "從魚人手中取回6個急救包。", description = "很高興看到你毫髮無傷。\n\n從附近的船隻殘骸看來，我想比較保守的說法是，失蹤遠征隊在此地觸了礁。\n\n在其他倖存者恢復之前，我們暫時動彈不得。\n\n不幸的是，我們殘存的補給品被魚人偷走了！真是群煩人的傢伙…\n\n我需要你找回足夠的急救包補給品來協助傷者。\n\n然後我們就可以開始尋找失蹤的遠征隊了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
