MultiLanguageQuestData['tw'][55153] = {title = "協同建設", objective = "在機械岡找出建築計畫並協助建造。", description = "在整座島上處處可以找到建築計畫。你可以自行建造其中幾種，但碰上了大型計畫上，你就需要協助。\n\n四下詢問並看看其他已經在進行的計畫，或者自己動手，找出哪一個最感興趣。\n\n建築計畫會四處移動，而且每天可能都不一樣，所以在你的探索過程中，留意新計畫的出現。\n\n如果你對目前有什麼樣的建築計畫有興趣，儘管問我就對了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55171] = {title = "諜對諜", objective = "完成任務「暗探戰牙堡」", description = "納迦攻擊正在加重，但我們要應付的難題還不只如此。我們接獲的消息，指出部落在斯陀頌恩谷地戰牙堡的活動越來越頻繁。\n\n派出我們的探員前去調查他們在那邊做什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55173] = {title = "一路向北", objective = "向北方偵察並找出奧斯汀‧哈克斯沃。", description = "野豬人綁架了遠征隊的其他人，並帶著他們往北移動。\n\n我聽野豬人提到，要為某種儀式尋找更多祭品。\n\n拜託，你一定要拯救他們！蓋瑞克船長的兒子也是其中一人，他發誓他母親一定會來救我們的。", progress = nil, completion = "我有些好消息和一些非常、非常糟糕的消息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55174] = {title = "烤肉", objective = "從廢棄營地附近的野生動物身上取得5塊生肉，然後用營火烹調。", description = "這位是艾拉莉雅，失蹤遠征隊之中的德萊尼薩滿。\n\n她已經快要餓死了。我們得幫她找點東西吃！\n\n殺死附近的野生動物取肉。把你找到的任何東西帶過來這邊烹調。\n\n如果能讓艾拉莉雅恢復體力，她應該可以告訴我們其他人出了什麼事。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n硬肉乾"}
MultiLanguageQuestData['tw'][55175] = {title = "路之所向", objective = "和歐卡尼一起前往梅札米爾。", description = "我的人知道很多這地方的秘密，只要你證明自己是有價值的盟友，我們就會告訴你這些秘密。\n\n首先，我們必須在梅札米爾重新集結。在那裡，我們至少有個逆轉情勢的立足點。", progress = nil, completion = "到目前為止，這些安寇恩已經證明了他們是強大的盟友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55177] = {title = "撕裂的接縫", objective = "等你準備好跟德羅米一起離開調查這個異常事件，就去找德羅米說話。", description = "我覺得好奇怪…很虛弱。好像有某種東西影響到我的存在本質。\n\n<name>，你可以陪我去嗎？我需要你幫忙…如果接下來發生可怕的事情，至少有人知道。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55179] = {title = "協調反擊", objective = "在斯陀頌恩谷地找到凱爾希‧鋼火。", description = "肖爾大師已經在斯陀頌恩谷地的部落基地附近佈署了好幾位聯盟間諜。只要間諜沒有定時回報，他就會帶著凱爾希‧鋼火前去調查。\n\n現在沒有定時回報的人，輪到肖爾大師了。\n\n我得派人潛進去查明失蹤人員，並為他們提供所有協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55182] = {title = "有待拼湊", objective = "從部落軍隊手中取得監聽器材零件。", description = "部落在準備進行計畫之前，徹底掃蕩了這個區域。他們毀掉我們設下的監聽哨，而肖爾大師要我重建回來。\n\n我想盡辦法回收大多數零件，但還缺少幾塊。\n\n幸運的是，我一直盯著那些工人，他們一直在撿機器的零件。去把我們的設備搶回來，我才能完成剩下的工作。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55183] = {title = "尋找制高點", objective = "在戰牙堡南邊山丘上與凱爾希‧鋼火會面。", description = "我們只有一次機會能重建好通訊網路，所以得找到一個好地點。正好，我看上了一塊地方！\n\n趁你在下面團團轉的時候，我弄了一些偽裝並把一堆機械運上那邊。\n\n什麼？你以為你離開之後，我就只是坐在這邊磨匕首嗎？\n\n呃，好吧，我是有磨啦。不管怎麼說，我們山丘上見！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55184] = {title = "禁忌的野豬人死靈法術", objective = "在野豬人棘地殺死7名野豬人。", description = "野豬人是原始又蠻勇的種族。他們很少使用地卜術以外的魔法。\n\n但這些野豬人似乎涉獵了死靈法術。一定要阻止他們。\n\n殺死前方巢穴中的野豬人。不能任他們喚醒不死大軍！", progress = nil, completion = "做得好。希望野豬人能明白死靈法術無法為他們帶來更多力量。", rewards = "遠征隊鎧甲戰靴遠征隊布甲長靴遠征隊鎖甲脛甲遠征隊皮甲長靴遠征隊鎧甲戰靴遠征隊布甲長靴遠征隊鎖甲脛甲遠征隊皮甲長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][55185] = {title = "聽好！", objective = "在斯陀頌恩谷地保護凱爾希‧鋼火。", description = "好了！一旦我們架好這玩意並讓它開始運轉，我們就可以發送訊息了！至少在谷地沒問題。\n\n這會有點難搞，但是我已經把這些東西的說明書從頭到尾都看完了。\n\n<凱爾希拍了拍監聽裝置的頂端。>\n\n我要開始拼湊這玩意了。你幫我留意部落的動靜。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55186] = {title = "擊敗野豬人", objective = "殺死地領主奎克歐格。", description = "我目前的情報指出，這些野蠻的野豬人正在對一名遠征隊成員進行死靈儀式。\n\n野豬人的領袖為地領主奎克歐格。他就是那個想要取走我們朋友生命的人。\n\n殺死奎克歐格，拯救遠征隊成員。他或許知道其他人被帶去哪了。", progress = nil, completion = "多謝你救我一命！他們說這不過是場普普通通、平淡無奇的遠征。\n\n絕對不是！而且我開心到不行！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55188] = {title = "撕裂的接縫", objective = "等你準備好跟德羅米一起離開調查這個異常事件，就去找德羅米說話。", description = "我覺得好奇怪…很虛弱。好像有某種東西影響到我的存在本質。\n\n<name>，你可以陪我去嗎？我需要你幫忙…如果接下來發生可怕的事情，至少有人知道。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55193] = {title = "斥候機器人5000", objective = "使用斥候機器人5000找到亨利‧蓋瑞克。", description = "你在找亨利‧蓋瑞克，對吧？他是個好人，有點陰沉，但是人很好！\n\n能救到我算你走運，我叫林迪‧螺絲庫，非凡發明家！\n\n我的斥候機器人5000已經準備好了，它可以在天上飛，讓你偵察整個區域。\n\n給你這個機會，用我的斥候機器人5000來找亨利和其他遠征隊成員！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55194] = {title = "補給滿載", objective = "向軍需官里赫特購買任何物品，並把你的東西賣給她。", description = "軍需官里赫特從從島上的殘骸中回收了一些補給品。\n\n你要不要去拜訪她一下，看有沒有什麼東西可以派上用場？\n\n你最好為接下來的戰鬥找好裝備。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n標準配發背包"}
MultiLanguageQuestData['tw'][55195] = {title = "迴響", objective = "使用雷焰來召喚哈提的精華。", description = "哈提的靈魂永遠與你的靈魂緊緊相繫，獵人，不過它現在也同樣與風暴神殿有所連結，恐怕就像希利蘇斯那樣。\n\n雷焰也有相同的聯繫。只要在這裡把雷焰連結起來，你就可以呼喚哈提靈魂的不同化身，將其與你的靈魂緊緊相繫。\n\n別擔心。我和史科爾以性命擔保，一定會看好雷焰的！保證很安全。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n雷霆鏈結\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][55196] = {title = "鷹身人問題", objective = "在鷹身人棲息地附近和亨利‧蓋瑞克會面。", description = "謝謝你救我，<name>。我會盡全力幫你的忙。\n\n我們要在巨魔進行黑暗儀式獻祭前，救出遠征隊的其他倖存者！\n\n我看到一位生還者被鷹身人拖走了，他們在北邊有一個巢穴。\n\n基拉和我會在那邊和你會面，並準備好偵察報告。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55208] = {title = "Kevin Live Update Test Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][55210] = {title = "不內附電池", objective = "收集10枚受損的儲能裝置。", description = "$p，你救了我和親愛的姐妹，保證你不會後悔。\n\n我們是新科技革命的先鋒，用難以置信的科技提供良機，改善所有人的生活！\n\n不過，在辦到這一點之前，需要為實驗室提供足夠動力。這些機械岡無賴對我們的器材造成了不少損壞。\n\n在這附近很難找到充滿電力的儲能裝置，但我可以用舊的替代。\n\n在城鎮附近看看，從上一次攻擊的殘骸中找找。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][55211] = {title = "鏽栓充電", objective = "使用NRG-100為6枚發電機儲能裝置充電。", description = "除非我們把個人發電機的儲能裝置充飽，否則它完全派不上用場。\n\n正如我親愛的兄弟所言，能量電池是革新的生命之血。機械岡的所有東西都需要電力，而儲能裝置以美妙的共通形式傳輸電力。\n\n不過，大多數人只會把用盡的電池丟掉。\n\n親愛的實驗對象，這些人都是笨蛋。\n\n我們打造了一項科技，可以讓少數的儲能裝置回復滿載電力。\n\n你願意幫我們測試嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n儲能裝置"}
MultiLanguageQuestData['tw'][55213] = {title = "人人都有儲能裝置拿", objective = "在機械岡找出5枚耗盡的儲能裝置。\n\n然後協助完成充能站建築計畫，並用它來為耗盡的儲能裝置充電。", description = "城裡到處流傳，指出邦多的機械場有座充能站，會在今天修復！\n\n想要把耗盡的儲能裝置充滿，最好的方式就是充能站。不管那些電池是放在你的袋子、別人的袋子，或是那些尚未取得但可以合法摧毀的機器人內部，通通都可以用。\n\n在你取得用盡的儲能裝置後，在邦多的機械場幫忙建造充能站，並把你手中用盡的儲能裝置都充飽！", progress = nil, completion = "太棒了！希望這些兇狠的穴居怪能讓你平平安安的充飽電。\n\n他們就是無法從任何角度去理解科技。老實說，我真為他們覺得丟臉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55214] = {title = "接縫緊繃", objective = "跟隨德羅米穿過時間裂隙。", description = "<name>，請…請等一下。\n\n<德羅米看起來相當困惑，緊抓著你的肩膀支撐身體。她扶著額頭默默站著。\n\n然後她彷彿從某種狀態努力復原，挺直身子看著你。>\n\n我的記憶有遺缺的部分。有某些對我而言重要的東西，現在遺失了。<name>，我們無論如何都必須阻止她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
