MultiLanguageQuestData['tw'][55528] = {title = "遊戲時間結束了", objective = "消滅12頭穴居怪。", description = "自從我們抵達此處之後，這些穴居怪就一直在掠奪我們的補給品，現在我們有了火力，就靠你去阻止他們了！\n\n讓我們好好教訓這些穴居怪，離我們的東西遠一點！", progress = nil, completion = "你贏得了你的酬勞，&lt;race&gt;！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80儲能裝置\n\n等級 11–80耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][55529] = {title = "無援", objective = "將海水甜菜、未辨識的物體、脹氣魚及黏滑的納迦眼球交給莫嚕。", description = "<這隻魚人似乎餓了。它旁邊畫了幾個簡陋的圖畫，似乎是購物清單。也許你可以幫幫這隻生物。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n骯髒的法力珍珠手鐲"}
MultiLanguageQuestData['tw'][55530] = {title = "更安全的地方", objective = "護送莫嚕回新鄉。", description = "<這個魚人似乎狀況不太好，也許他跟你的盟友一起待在新鄉比較安全。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55531] = {title = "會挖到什麼？", objective = "完成鹵石灣事件。", description = "<雖然因反覆使用而磨損，鎬似乎依然勉強可以使用。附近或許有東西可以採？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n奧司曼礦石稜光法力珍珠"}
MultiLanguageQuestData['tw'][55533] = {title = "母親知我心", objective = "在心之室裡跟母親大人談話。", description = "現在這個房間穩定下來了，我們可以把注意力放在強化艾澤拉斯之心上面！\n\n母親大人表示她已經完成了精密的計算。和她談談，勇士。看看我們能否進一步強化艾澤拉斯送給你的驚人禮物。", progress = nil, completion = "分析完畢。為了預防發生星球規模的大滅絕，必須強化艾澤拉斯之心。\n\n目標：尋找相容精華。優先權：至關重要。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55534] = {title = "鏽栓留聲機", objective = "把留聲機放到鏽栓的爛醉工匠酒吧裡。\n\n已提供物品：\n", description = "<你所鍛造出來的大型留聲機可以讓音樂響徹在鏽栓的各個角落。\n\n現在你只需要把它放到合適的地點就行了。>", progress = nil, completion = "&lt;這裡看起來是放置留聲機的絕佳地點。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55535] = {title = "爛醉工匠酒吧", objective = "把鏽栓冰酒器放到鏽栓的爛醉工匠酒吧裡。你所製作的巨大冰酒器應該足以容納鏽栓反抗軍的所有飲料。\n\n在鏽栓裡找個地方把它設置好，並讓城鎮的人們知道冰酒器已經可以使用了！您會收到：\n\n完成任務後，你將獲得：\n\n", description = "你所製作的巨大冰酒器應該足以容納鏽栓反抗軍的所有飲料。\n\n在鏽栓裡找個地方把它設置好，並讓城鎮的人們知道冰酒器已經可以使用了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55558] = {title = "一個螺釘孔", objective = "在烏特瑪之地與珊蒂斯‧羽月會面。", description = "<name>，我們必須找到一個強大的武器，來對抗防守潮汐合流的納迦。我確定這樣的東西，應該在艾薩拉其中一個爪牙的手中。\n\n多虧我們的新盟友，我們已找出她其中一個女僕在辛艾薩拉廢墟內的位置。這趟旅程會相當危險。幸好運氣不錯，盟友在附近有個地點可供我們做為集結地。\n\n我在你的地圖上標示出位置了，盡快到那裡與我會面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55560] = {title = "烏特瑪的復仇", objective = "殺掉10隻龍蝦人。", description = "我們安寇恩是一支小部族。我們倖存的人不多。\n\n這個地方本來到處都是龍蝦人，然後烏特瑪來了。他們本來躲在這裡避免納迦的侵害，但卻遇到了龍蝦人。他們在戰鬥中被基爾卡羅克殺害。\n\n若你想要對安寇恩有貢獻，請在烏特瑪的回憶中成為復仇的助力。摧毀龍蝦人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55561] = {title = "辛艾薩拉的遺址", objective = "在艾薩拉的雕像旁與珊蒂斯會面。", description = "辛艾薩拉，曾是夜精靈文明的首都，在大崩裂時壞滅。艾薩拉女王背叛了自己的人民，坐視恩若司腐化他們，把他們變成納迦。\n\n它現在淪落為廢墟，陷入混亂之中。\n\n我們必須了解它的情況。在艾薩拉的雕像旁與我會面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55565] = {title = "提高法力儲能", objective = "收集10個元素核心。", description = "就算有潮石的力量，驅退潮汐之牆也不是一件容易的事。這地區的魔法能量波動太不穩定了。\n\n我們必須提高我們的魔法儲能，這會需要所謂的法力電池。運河旁的受汙染元素生物，正巧有我們所需要的元素核心。\n\n我們的目的有兩個。在腐化蔓延前，清除受汙染的元素生物，同時取回它們的核心，好讓我們控制水勢。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55569] = {title = "痛苦的殘影", objective = "與在精靈貴族莊園四處遊蕩的靈魂談話。", description = "這些靈魂…他們是精靈貴族。艾薩拉的親信。艾薩拉經寵信的人經常變動，但這些人…她一直非常信任。\n\n我不知道為何他們的靈魂在這裡。我們應該進一步調查。看看你是否能與他們溝通，找出他們的靈魂徘徊此處的原因。\n\n她怎麼能棄他們不顧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55570] = {title = "廢墟裡的秘密", objective = "搜尋蘊含力量之物。", description = "這裡曾是具有超凡力量的地方。居住於此的精靈貴族會舉辦鋪張的宴會，生活奢華。\n\n辛艾薩拉原本位於永恆之井的岸邊，吸引帝國各處的強大法師來此研究。我懷疑，雖然多年來位於海底深處，這裡依然埋藏了許多秘寶與厲害的神器。\n\n與留下來的靈魂談話，看看你能找出什麼。一定會東西能協助我們擊敗潮石守護者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55571] = {title = "協助他們看見真相", objective = "把艾薩拉的事告訴這些靈魂。", description = "<name>，你收集的情報令人擔心。這些靈魂徘徊此處不走，是因為即便到了現在，他們依然相信艾薩拉統治有方。她將他們的靈魂賣給了虛無，而他們依然對她深信不疑。\n\n我知道我們有其他更重要的問題，但我不能坐視不管。\n\n告訴他們，與他們對談，告訴他們艾薩拉的背叛。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55573] = {title = "淨化污染者", objective = "驅逐伊露恩諾的納迦。", description = "艾薩拉的確驕縱自戀，每件事物皆須出現她的名諱、每件事情都是為了她的榮耀。她遺忘了我們人民與伊露恩之間的連結。又或許她認為那根本無關緊要？\n\n墮入邪道的艾薩拉與她的手下，褻瀆這塊地方太久了。\n\n我們要讓他們知道伊露恩有仇必報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55574] = {title = "艾薩拉之槍", objective = "殺掉艾薩拉的女僕。", description = "這些靈魂不斷提到艾薩拉之槍。起初，我以為這指的是目前堅守在伊露恩諾不出的女僕。\n\n但是，現在我認為這指的是蘇拉瑪爾之槍。那是強大的武器，我們長久以來都以為已從世上消失。艾薩拉的確喜歡將神物占為己有。\n\n無論如何，我們必須擊敗她在伊露恩諾的女僕。能取走蘇拉瑪爾之槍，將是天降之喜。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55575] = {title = "一位地精的垃圾", objective = "用稀有金屬收集器取得100塊稀有金屬。", description = "在這些垃圾堆裡面到處都是稀有金屬：達拉然鈦、蘇拉瑪爾礦，甚至連地精鋼都有！\n\n自從寶庫大門對波拉勒斯開放之後，我就沒辦法輕鬆弄到那麼多金幣了！你幫我收集一些金屬，我的朋友老高會轉到黑市去賣。\n\n我弄到一台裝置，可以直接把金屬從垃圾堆拉出來！", progress = "這一定可以大賺一筆！", completion = "這肯定很暢銷。這份利潤是給你的！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80儲能裝置耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][55578] = {title = "托達戈爾：海潮寶石", objective = "和『滑頭』曹頓交談，進一步瞭解失蹤物件的下落。", description = "<當你凝視著面前的聖壇，忍不住讚嘆它的製作工藝。\n\n以青碧寶石的無縫構造，排列成放射線的圖案，朝統一的中心點集中。\n\n單一且空無一物的中心點。你猜想這一定是某種錯誤。快速檢視這個區域之後，你找不到任何適合放在中心位置的事物。\n\n不過，這裡好像有個醉漢在咆哮。或許他知道聖壇失蹤物件的下落。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55579] = {title = "敲擊地表", objective = "前往嚎風丘並收集20枚金柱石裂片。", description = "<在你的調查過程中，你發現聖壇上有好幾個應該放置珠寶的地方，卻沒看到珠寶的蹤影。\n\n而且珠寶上也有一些裂痕。在查看你手中的筆記之後，發現土靈提到這些珠寶是從西北方不遠處的山區勘探而得的。\n\n或許你可以探勘這個地區的土地，找到更多同類型的珠寶。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55580] = {title = "高度勘探", objective = "在戈爾歐希展開調查，尋找用來製作聖壇的珠寶線索。", description = "<你檢視聖壇，看到表面鑲嵌的幾枚寶石已經裂開了，需要換新。\n\n你檢查手中的筆記後，發現土靈從南邊的土元素身上粹取出寶石。\n\n你比對了地圖，不禁猜測這是不是指那堆原本是古代聚落的廢墟，現在裡面到處都是傀儡和不死生物。\n\n或許調查這個地方還能尋獲一些線索，指引你找出這些珠寶。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55581] = {title = "太陽點綴的沙丘", objective = "前往地圖標示的寶石所在地，取回8枚寶石，數量夠了以後再進行打磨和塑形的工作。", description = "<在勘察這座聖壇之後，你認為這個地區的風沙磨耗了鑲嵌在上面的寶石，使得某些寶石變了樣甚至龜裂。\n\n查看你的筆記，土靈提到他見過灑滿了橘色寶石的沙丘。他說那讓他想到這個地區的溫和陽光。\n\n查看筆記，沙丘似乎就在你當前所在地點的南邊。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55582] = {title = "阿塔達薩：金玉其外，敗絮其…", objective = "前往阿塔達薩，搜尋替換的寶石。", description = "<你檢查了一下，發現聖壇很乾淨，不過中央的寶石嚴重損毀，必須替換才行。\n\n你參考手中的聖壇筆記，查出這種寶石是來自於某個被稱為「黃金聖所」的地方。\n\n根據判斷，這指的一定是阿塔達薩。也許你在那座古老城市能找到其他寶石來替換。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55583] = {title = "除舊佈新", objective = "切割4個浮動的紅碧璽，並換上新寶石。", description = "<在搜查聖壇之後，你注意到某些東西很…熟悉。這些寶石的切割方式，很像你在切割紅碧璽的工法，只不過更原始、更單純。\n\n時光顯然在這些寶石上留下了不少痕跡，有些受到風化之後碎掉了一部份。\n\n用同類寶石加上同樣的切割方式來修復這座聖壇，應該不難。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
