MultiLanguageQuestData['tw'][55618] = {title = "心之熔爐", objective = "和母親大人交談以啟用心之熔爐。", description = "心之熔爐能量提升，指出黑龍精華的存在。\n\n建議：進行心之熔爐啟動程序。", progress = nil, completion = "能量來源認可。熔爐啟動完畢。", rewards = "您會學到：\n\n心之熔爐\n\n您還會收到：\n\n"}
