MultiLanguageQuestData['tw'][55622] = {title = "今天開上路", objective = "取得500S型電子能量核心。", description = "整台坐騎打磨得光亮無比，看起來棒透了。我們差不多完工了！\n\n我把能量核心結構圖送去給帕斯卡-K1N6了，只要你把零件帶過去，他就能造出一個全新的500S型電子能量核心。\n\n在我們把能量核心裝進去之後，你今天就可以駕著這台機器人離開！", progress = "你拿到核心了嗎？", completion = "他們再也沒辦法偷我們的東西了！", rewards = "您會收到：\n\n廢鑄機械蛛"}
MultiLanguageQuestData['tw'][55625] = {title = "力量超乎想像的珍珠", objective = "收集8顆附魔珍珠。", description = "當永恆之井在幾千年前遭到毀滅時，這塊土地被打入深海，並釋放出一道強大的魔法能量風暴。\n\n這道魔法能量依舊殘留至今。\n\n從這些灌注了上古法力的蚌殼中收集珍珠。在對抗納迦的戰役中，這些附魔珍珠有可能成為我們手中的強大武器！", progress = "為了對抗納迦，我們必須把握每一分優勢。", completion = "你做得很好。我感覺得到這些珍珠散發出一道強大能量。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
MultiLanguageQuestData['tw'][55630] = {title = "動工修復", objective = "修好保險庫的機器。", description = "這些地精真的以為光是搗毀一台機器，就足以讓像我這樣的哥布林，搞不懂這個地方用了什麼科技？\n\n不管是什麼樣的垃圾，老史卡吉特和我都有辦法修得好，而且甚至還會跑得比原本全新的時候還要順呢！\n\n所以這樣吧，你跟著史卡吉特看看能不能把它拼湊回來。\n\n然後我趁這時候和這位地精朋友聊聊，看她對這些科技有多少瞭解。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55632] = {title = "你只能這麼高", objective = "叫加茲魯維啟動裝置。", description = "你和技工讓這台機器復原並運作的速度，比我預期得還快。\n\n我們逮到的地精守口如瓶，但那應該不成問題。我可以從這邊接手。\n\n在你準備好之後告訴我一聲。在這台機器全速運作之後，我們終於可以見證它的功用了。\n\n我希望它會壓出金幣來…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55633] = {title = "沉沒箱子", objective = "找到瀉湖底部的黃銅鑰匙。", description = "<這個浸水的箱子似乎還能回收，但裡面的東西讓它重到連抬都抬不動。\n\n上面的鎖似乎還管用。\n\n或許附近可以找到鑰匙…>", progress = "<這個箱子鎖住了，沒鑰匙打不開。>", completion = "&lt;雖然花了你不少功夫，但鎖終於打開了…&gt;", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][55635] = {title = "風中之聲", objective = "在佐司瓦尋找神秘的聲音從何而來。", description = "<一道遙遠、神秘的聲音充斥在你的腦海。>\n\n我的附魔尚未遺忘…\n\n來找我…\n\n佐司瓦…\n\n落港村…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55636] = {title = "畢生成果", objective = "收集6份古代卷軸和6份秘法寶典。", description = "<一道聲音從死亡帷幕後方向你低語。>\n\n遠在大崩裂撕裂我們的世界之前，我就在研究秘法的神祕力量。\n\n我在這場毀滅之中消亡，成果就此遺失。\n\n在這個地區搜尋我的遠古著作，讓我的靈魂得以安息…", progress = "書架上看來空無一物…", completion = "當你把秘法寶典和古代卷軸放滿書架時，肩上一股沉重的壓力頓時煙消雲散。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
MultiLanguageQuestData['tw'][55637] = {title = "可憐的不幸靈魂", objective = "讓8位受折磨的靈魂安息。", description = "這座偉大的城市在大崩裂期間被轟進深淵之中，也喪失了無數的生命。\n\n我們之中運氣好的得以在爆炸之中死個痛快，但那些倖存下來的人，卻只能在冰冷、無情的大海波濤下備受折磨而亡。\n\n直到今日，這些可憐、不幸的靈魂依舊要面對比死亡還悲慘命的運。他們永無止境地溺水，被迫體驗死亡那一刻的折磨。\n\n讓他們得以長眠，讓他們的靈魂終於得以安息。", progress = nil, completion = "他們再也沒辦法取回久遠之前就失去的生命，但至少不用繼續承擔那樣的痛苦。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][55638] = {title = "釀造藻莓酒", objective = "將藻莓酒帶到梅汀的挑戰，並交到梅汀手中。", description = "<這是一個空空如也的藻莓酒桶。\n\n如果有人能裝滿它，附近可能有人會滿懷感激。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55639] = {title = "坑洞潛伏是何人", objective = "救出5名受困的遠征隊成員。", description = "微風告訴我，坑洞中還有人被困住。看來裡面還有其他遠征隊成員。\n\n恐怕我得靠你深入坑洞，才能拯救這些倖存者。\n\n總共應該有六位…不過微風透露了，其中一位特別遠…\n\n最後一位倖存者很有可能是在坑洞的底端。\n\n<name>，祝你好運。還有…別讓蜘蛛跟著你爬上來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊布甲腕輪遠征隊鎧甲臂甲遠征隊鎖甲臂環遠征隊皮甲護腕遠征隊布甲腕輪遠征隊鎧甲臂甲遠征隊鎖甲臂環遠征隊皮甲護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][55640] = {title = "暴風城幻象", objective = "完成暴風城幻象。", description = "潛入恩若司的心智來弱化他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n腐化的紀念物"}
MultiLanguageQuestData['tw'][55645] = {title = "貴客來訪", objective = "和技工大師歐沃斯巴克一塊探索附近的城鎮。", description = "就是這裡！傳說中的機械岡！\n\n當代最偉大的發現，而且你就在此地見證我的事蹟！\n\n<技工大師歐沃斯巴克挺起胸膛，順了順長袍，並露出自信的微笑。>\n\n我準備向機械岡的人們發表演說。你可以和我同行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55646] = {title = "機械岡傳說", objective = "在提拉加德海灣的廢棄垃圾堆與加茲魯維會面。", description = "嗨呀，$p。我剛剛才跟史卡吉特在講，希望能在這邊撞見你。\n\n我聽到一點風聲，指出聯盟正在策畫一項行動，打算開啟提拉加德海灣的某座舊保險庫。\n\n按照地精的傳統風格，技工大師歐沃斯巴克會過度反應得像瘋子一樣，宣稱它是某種遺失的關鍵，可以找到地精童話故事中的機械岡。\n\n<加茲魯維輕蔑大笑。>\n\n我根本不相信這種事，但不管那座保險庫藏了什麼科技，我都想要分杯羮。你要加入嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55647] = {title = "耳際催促", objective = "靜候聯盟離開保險庫。", description = "壞消息，我們來得太遲了。\n\n在我們抵達之前，聯盟就踏遍了整座保險庫。\n\n幸運的是，裡面引發了某種騷動讓他們某些人逃得飛快。\n\n不過，大多數人還留在保險庫中，包括那個瘋狂的膨風仔技工大師歐沃斯巴克。\n\n我們給他們一點時間清場，才不會一踏進去就碰到火砲齊射。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55648] = {title = "鳩佔鵲巢", objective = "帶領加茲魯維的手下進入保險庫。", description = "歐沃斯巴克離開，海灘上也安全了。我們進入保險庫看看，裡面到底是怎麼回事。\n\n不管是不是機械岡，裡面最好有些夠厲害的東西，值得我們在這趟旅途耗費那麼多時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55649] = {title = "機械岡的機械科技", objective = "騎乘技工空中潛隱機前往祖達薩碼頭。", description = "看來機械岡不是童話故事？不得不承認我蠻驚訝的。\n\n不過，如果他們從那個國王手中弄出來的科技值得我們下手，那我就超級、超級高興我之前是錯的！\n\n我們不能貿然行事。今天死了一個好部下。在我的眼皮子下不能再發生一次。\n\n到祖達薩碼頭和我還有史卡吉特會合，我們馬上編組一支遠征隊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55650] = {title = "一流團隊", objective = "取得所需的一切，並朝機械岡展開遠征。", description = "你聽到加茲魯維說的話了。老大要這場遠征平平順順，不抄捷徑，不拖泥帶水。\n\n我知道你曾經和加里維克斯共事。我們不會用那種行動方式。\n\n我們期望組員能發揮出最大功效，所以我們論功行賞，而且好好照顧他們。獲得的回報，就是我們擁有全世界最棒的哥布林成員，而且他們任何方面都不會輸。\n\n這裡有一份名單，列了我們邁向成功的人選。別擔心，加茲魯維會支付所有開銷。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55651] = {title = "前往機械岡！", objective = "和克羅茲船長交談，前往機械岡。", description = "不論機械岡派什麼東西來岸邊迎接我們，我們都得靠這批船員來應付。\n\n我很清楚這個瘋狂國王會用什麼東西來歡迎我們。我敢說，槍砲齊射免不了。\n\n所以，我們得用這艘潛艇靜悄悄的溜進去。放低姿態確保我們的安全。\n\n在你準備出發時，去和克羅茲船長談談。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55652] = {title = "指南灣", objective = "與加茲魯維及其他組員一同使用火箭包進入指南灣。", description = "看來我們成功溜進來了。\n\n史卡吉特的人可在那片海灘上搭建商店，但我們必須先確保他們能安全著陸。\n\n讓我們快速巡飛一圈，查探要如何擊破這個地方。\n\n那座山丘上的城鎮看來大有可為…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55657] = {title = "在赤紅雙翼的暗影中", objective = "和卡雷苟斯交談一塊兒飛行到朱紅壁壘，找出雅立史卓莎並探索威脅源頭。", description = "在巨龍精華的力量出現在這個世界後，雅立史卓莎還會失聯這麼久，實在不像她的行事風格。\n\n盟友會留在這裡照顧傷患，我們必須馬上去找生命守縛者。\n\n在你準備好之後，我們一塊兒去朱紅壁壘。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n淬鍊血色育母鱗片艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55658] = {title = "四散的線索", objective = "挖掘島嶼歷史的線索。", description = "在機械岡國王取得這座島嶼時，還有其他人住在此地。這些人民的歷史無人聞問，深埋在這些髒污和垃圾下面。在你的協助下，我們能進一步瞭解先前的居民。\n\n芬利爵士曾經見過一些不尋常的文物，並在地圖上標好了地點。到那邊和他會面，看看你能找到什麼線索。", progress = "動身吧。歷史正在等你挖掘！", completion = "辦得好！我們馬上就可以追根究底了！", rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][55659] = {title = "大崩裂聖物", objective = "收集10塊精靈貴族聖物。", description = "在海底找到失落的文明遺跡，這種好事可不是天天有！\n\n我從沒想過有一天能夠探索納沙塔爾的失落之城…而且還是採在結實的地面上！\n\n這裡有許多秘密等我們去發掘。如果你找到任何古代精靈貴族文物，請帶來給我。這些文物可以為我們提供珍貴的線索，一探大崩裂的來龍去脈。\n\n我覺得我們所知道的只是冰山一角…", progress = "不管大海的波濤下隱藏了什麼神祕，現在正是讓它重見天日的時候！", completion = "真厲害！看看你找回來的這堆精靈貴族聖物！我馬上開始調查。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][55661] = {title = "以毒攻毒", objective = "對一頭嚙龍恐喉使用收集而來的毒液加以弱化，並取得它們的尖牙。", description = "嚙龍的毒液有許多用途。\n\n可以直接製作用來治療的抗毐血清，或是收集毒液來攻擊納迦。\n\n我們就不要再拐彎抹角了吧。\n\n對一頭恐喉使用收集來的毒液加以弱化，然後殺死他並把他們的尖牙帶來給我。\n\n我們也許可以組合出某種好用的東西。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55662] = {title = "秘法貯藏箱", objective = "找到秘法貯藏箱的鑰匙。", description = "<這口沉重的強化寶箱是出自納迦之手，似乎加上了某種魔法鎖。\n\n就算沒了魔法強化，這個貯藏箱還是需要某種鑰匙才打得開。\n\n鑰匙很可能在附近的納迦士兵手中。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][55663] = {title = "壞掉的控制者", objective = "救出奴隸，並摧毀無情控制者。", description = "朋友，我已經回天乏術了。\n\n那些控制者讓我們日夜不停的工作，完全無法休息。\n\n我們失去了太多人。\n\n求求你，救出其他人！別讓他們步上我的後塵！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55664] = {title = "士氣重挫", objective = "破壞希拉凱斯庫房內的所有活動。", description = "這個地方是一切腐化的源頭。 \n\n被抓來此處的海布林都身心受創。\n\n打擊他們的痛處、擊碎他們的力量、殺掉你眼前的每位納迦，大鬧一場！\n\n我們敲出的每一條裂縫，都會弱化他們的根基。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55665] = {title = "黑暗花園", objective = "殺死納迦，釋放被關押在皇家花園折磨的可憐生物。", description = "聽好，<name>，我知道我們有一場更大的仗要打，但這些花園也太可怕了。\n\n無辜的生物被抓起來監禁，不過是為了取悅納迦。\n\n他們把生物帶出來拷問、改變他們、重創他們…你知道我在說什麼。\n\n幫我救出這些納迦的階下囚，好好懲罰納迦的傲慢！", progress = nil, completion = "我很確定我聽到一隻水獺笑著跑過去。\n\n你的戰鬥技巧真出色。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 波恩‧括鰭稜光法力珍珠"}
