MultiLanguageQuestData['tw'][55687] = {title = "遠征GG-118微型火箭包", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][55688] = {title = "擴大的神秘", objective = "收集10枚上古符文石。", description = "這些符文石可能是出自於維酷之手。難道維酷人曾經造訪過這座島嶼？\n\n符文石出現的地方，通常不會只有一枚。這些鞭笞者的根會被符文石魔法所吸引，如果還有其他符文石埋在地下，或許會被鞭笞者的根纏住！\n\n清理這些鞭笞者，看看你能不能從糾纏的根部找到符文石。您會收到：\n\n\n\n等級 60–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 60–80耗盡的儲能裝置\n\n等級 11–80備用零件\n\n等級 60–70儲能裝置"}
MultiLanguageQuestData['tw'][55694] = {title = "水中有東西", objective = "殺掉腐化者之眼。", description = "安寇恩不只得對抗納迦，還得面對恩若司的懼獸等威脅。我們很早就知道，就算只讓他感染最小的東西，他也會成長，腐化一切事物。\n\n這個地方的水路附近潛伏著巨大的邪惡。必須有人處理它。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55695] = {title = "新坐騎的臭味", objective = "收集8份金黃輪齒膏。", description = "機械岡城每星期都會排出過多的油料，並流經排水區。這也就是為什麼此地像個化學毒窟！\n\n今天，他們排出一堆金黃輪齒膏。這東西非常神奇！我用它製作空氣清香劑。可以讓任何坐騎聞起來就像全新的！\n\n查看排水區中的所有管路，看你能不能收集到一些有用的東西。", progress = "我還是用得到那個輪齒膏。", completion = "我的空氣清淨機快不夠用了。這可以讓我馬上趕出一批！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80耗盡的儲能裝置\n\n等級 60–70儲能裝置"}
MultiLanguageQuestData['tw'][55696] = {title = "試駕", objective = "以極速開著它抵達檢查點，並測試緊急剎車系統。", description = "雖然還有很多事情得做，但它會動了！我們得好好測試一下引擎、剎車和迴旋儀平衡螺線管。\n\n你要不要把它開出去跑跑看、測試性能如何？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55697] = {title = "跑腿工作", objective = "收集4支機械蛛腿和12根趾彈簧。", description = "這頭坐騎的腿部和電路鏽死了！如果想讓它爬爬走，我們就得弄點新的回來。\n\n前幾個禮拜，邦多和他的幫眾衝進了廢骨之穴，打算把穴居怪嚇跑。但穴居怪把他們的爬行者都扯個稀巴爛！那些零件在廢骨之穴裡散得到處都是。\n\n看你能不能從穴居怪手中把這些零件拿回來。", progress = "我們需要那些腿。", completion = "有了這些零件，表示我們想要乘坐這玩意兒的日子更近了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55701] = {title = "嚙龍爪", objective = "收集10支嚙龍爪。", description = "嚙龍是種成群結隊、集體獵食的兇殘生物。在納沙塔爾，我們得無時不刻地提防它們出現。\n\n它們是十分狡猾的野獸，特別喜歡偷襲負傷或是虛弱的獵物。我們得降低這個區域的嚙龍數量。\n\n我們可不想在打倒納迦的時候，被一群嗜血的嚙龍給解決！\n\n獵殺附近的嚙龍，並將每一頭獵物的爪子帶來給我，方便我追蹤它們的數量。", progress = "不能低估嚙龍的威脅。", completion = "做得好，&lt;name&gt;。納沙塔爾的嚙龍數量越少越好。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][55707] = {title = "第一個免費", objective = "取回穿孔卡片背袋。", description = "這個口袋大小的電腦裝置，可以靠著插入打孔卡進行升級以改善它的效率。\n\n我是可以給你一張打孔卡，但有一個特別狡猾的穴居怪偷走了一整袋卡片，他叫『八姆指』摩恰卡。\n\n殺死『八姆指』摩恰卡，取回我的背袋，我就免費幫你做一張打孔卡！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n萬用效率型主機板子程式：極速超頻"}
MultiLanguageQuestData['tw'][55708] = {title = "升級", objective = "收集20枚微型齒輪。", description = "好吧，看看你，<race>…\n\n<克利斯蒂用機械雙眼飛快掃瞄你的身體。>\n\n沒我預期的那麼驚人。\n\n機械岡國王採用全面機械化部隊。但你…你身上的過剩血肉，不足和機械分庭抗禮。\n\n沒錯，我們只要做些改變…或許來個頭部神經升級！\n\n從附近的摩托蜘蛛身上取得幾個微型齒輪，我就可以馬上修好你！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n口袋型運算裝置"}
