MultiLanguageQuestData['tw'][55832] = {title = "懸賞：更多螃蟹", objective = "殺死25隻螃蟹。", description = "納沙塔爾境內的螃蟹數量急速增長，危及當地的植物生態。基於保育目的，請削減螃蟹的數量。\n\n請向軍需官回報，領取你的獎勵。", progress = nil, completion = "這會減輕我們在納沙塔爾的壓力。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][55833] = {title = "懸賞：更多嚙龍", objective = "殺死15隻嚙龍。", description = "嚙龍是納沙塔爾最危險的生物。納迦飼養牠們來做壞事，利用牠們來追蹤獵物。\n\n如果不希望納迦察覺我們的位置，就必須立刻解決這些嚙龍。\n\n完成後，請向軍需官回報，領取你的獎勵。", progress = nil, completion = "這會減輕我們在納沙塔爾的壓力。", rewards = "您會收到：\n\n艾澤萊晶岩戰爭物資戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][55834] = {title = "懸賞：更多深海魟魚", objective = "殺死15隻深海魟魚。", description = "大量繁殖的深海魟魚把東邊的珊瑚芽都快吃光了。如果不出手削減它們的數量，馬上就會面臨環境浩劫。\n\n結束後，請向軍需官回報，領取你的獎勵。", progress = nil, completion = "這會減輕我們在納沙塔爾的壓力。", rewards = "您會收到：\n\n艾澤萊晶岩戰爭物資戰爭物資稜光法力珍珠"}
MultiLanguageQuestData['tw'][55836] = {title = "懸賞：精英納迦部隊", objective = "殺死5個精英納迦。", description = "攻擊納沙塔爾境內的精英納迦部隊。一旦我們除掉他們的領導者，我們的人在行動時也會更順暢。\n\n請向軍需官回報，領取你的獎勵。", progress = nil, completion = "這會減輕我們在納沙塔爾的壓力。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55837] = {title = "懸賞：危險生物", objective = "在納沙塔爾殺死1隻稀有生物。", description = "納沙塔爾境內的某些生物遠比它的同類還要危險。你的任務就是找到並擊敗它們。\n\n事成之後，請向軍需官回報，領取你的獎勵。", progress = nil, completion = "這會減輕我們在納沙塔爾的壓力。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55845] = {title = "攻擊計畫", objective = "收集8份攻擊計畫。", description = "<這份攻擊計畫寫在羊皮紙上，以螢光烏賊墨水書寫，束成一綑並加上艾薩拉的印信。>\n\n女王頒布命令：\n\n艾薩拉女王對所有納迦部隊下令，準備全力對付進犯我們土地的聯盟侵略者。攻擊細節已經分發到各單位的指揮官手中。\n\n聯盟將會在女王的力量之下顫抖！", progress = "你從前線帶了什麼消息回來？", completion = "做得非常好，&lt;class&gt;。你為聯盟貢獻良多。有了這些計畫在手，我們就能在攻擊前先做好防禦準備。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][55846] = {title = "禁忌儀式", objective = "收集8冊束縛秘典。", description = "納迦利用禁忌的黑暗儀式制伏元素，讓元素服從他們的意志。\n\n然而，這樣的儀式會破壞與這個世界息息相關的元素平衡，必須有人阻止這個儀式。\n\n幸運的是，納迦使用的儀式過於複雜，無法光憑記憶施行。儀式的方法紀錄在古代典籍之中。\n\n如果我們摧毀寫有儀式的遠古秘典，納迦就會永遠失去執行儀式所需的知識。\n\n取回秘典，我會親自摧毀它們。", progress = "你拿到秘典了嗎？", completion = "我會立即銷毀這些束縛秘典，願奈普圖隆為你指引路途，&lt;class&gt;。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
MultiLanguageQuestData['tw'][55849] = {title = "廢料回收機", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][55851] = {title = "關鍵性的強化", objective = "前往希利蘇斯，在修復完成的心之室和麥格尼會面。", description = "勇士，有個天大的好消息！\n\n我知道你現在忙著對抗納迦威脅，不過還是要請你回心之室一趟！母親大人計算完畢，現在她對我們下一步該怎麼做有頭緒了！\n\n盡快回到希利蘇斯。艾澤拉斯需要你！", progress = nil, completion = "歡迎回來，勇士！在母親大人計算完畢之後，可是有一堆事要辦！\n\n我們開始吧，好嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55860] = {title = "海蛞蝓黏液", objective = "在血鰭村內，從冷光蛞蝓身上收集8個生體螢光黏液。", description = "我小小的研究指出，淬煉的過程會產出一種肉眼無法看見的副產品，但只要透過折射過的生體螢光就能輕易顯現。\n\n海底到處都是能製造生體螢光的生物，我們能用來追蹤這個武器庫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55861] = {title = "殘渣指引你的道路", objective = "沿著晶岩殘餘的蹤跡，找出艾澤萊晶岩武器庫。", description = "我設計出一種裝置，開啟時會發散生體螢光，讓你看到任何殘留的艾澤萊晶岩殘渣。\n\n它應該能清楚顯示武器庫的蹤跡。\n\n祝你好運，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55862] = {title = "洞察敵軍", objective = "與奈莉談話，進一步瞭解納沙塔爾的納迦。", description = "我們不曉得這片土地有什麼正等著我們。在我們知道自己面對什麼敵人前，我們不能輕舉妄動。\n\n雖然我們的新盟友在納迦手下過得生不如死，不過他們不會白白受苦。\n\n海布林應該對艾薩拉的部隊瞭若指掌。\n\n有了他們的幫忙，我們或許能進一步瞭解敵人的作戰方式。\n\n與奈莉交談並向她請益。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55863] = {title = "衰減的知識", objective = "從汲取心智的澤亞洛伊手上救出小芬、寇諾及艾絲瑪。", description = "艾薩拉的殘酷，海布林最清楚。\n\n她命令黑暗生物誘捕我的族人，扭曲他們的心智。他們蠶食族人的記憶，直到族人變成空無一物的空殼。\n\n如果你能快點找到他們，也許他們還有得救的機會。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55864] = {title = "代價是死亡", objective = "在贊季爾沙灘與深海奴隸監獄內殺死10名納迦。", description = "我們過去一直相信，大海廣闊無邊，足以成為任何生物的家園。\n\n不幸的是，納迦不這麼認為。\n\n他們屠殺、抓捕我們的族人，毫不慈悲。該是讓他們付出代價的時候了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55865] = {title = "納迦的情報", objective = "照料海布林的傷勢，然後聽取小芬關於納迦的情報。", description = "能夠重拾自我，感覺真好。謝謝你，這都是你的功勞。\n\n澤亞洛伊的影響還是讓我的頭隱隱作痛，但其他人的狀況好像比我更糟。\n\n幫忙塗一些藥膏在他們的傷口，然後我就會把我對納迦所知的一切都告訴你。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n海底束腰海底護腕海底披風\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][55866] = {title = "間諜行動", objective = "假裝心智受到禁錮，以探查贊季爾殿堂。", description = "獨自闖進他們的大本營，根本等於是送死。\n\n贊季爾對外來者一律是格殺勿論。\n\n想進去而不被殺掉，唯一的方法就是假裝受到澤亞洛伊控制。\n\n但是，心智被操控的人也必須進行勞役。\n\n所以你必須服從所有命令，否則他們會知道你仍保有自己的意識。\n\n只要讓贊季爾相信你的心智受到控制，你就比較容易在他們的領地行走、發掘他們的秘密。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55867] = {title = "熱愛水晶", objective = "從囤積者莫爾古身上收集一顆深海水晶。", description = "只要我們有適當的工具，找到武器庫應該不是問題。只需要一點光線與大量的生體螢光液就可以了。\n\n看起來似乎很簡單，對吧？但關鍵就在於用來折射光線的深海水晶。\n\n聽說血鰭部族熱愛這些水晶，你應該輕易就能拿到一個。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠"}
MultiLanguageQuestData['tw'][55868] = {title = "殘渣指引你的道路", objective = "沿著晶岩殘餘的蹤跡，找出艾澤萊晶岩武器庫。", description = "我早就設計出一台裝置，開啟時會發散生體螢光，讓你看到任何殘留的艾澤萊晶岩殘渣。\n\n它應該能清楚顯示武器庫的蹤跡。\n\n祝你好運，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55869] = {title = "清空武器庫", objective = "解決普莉希拉‧艾胥凡與她的手下。", description = "<檢查武器箱的時候，洞穴裡傳來一陣騷動。一個熟悉的聲音正吼著發號施令。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][55870] = {title = "海蛞蝓黏液", objective = "在血鰭村內，從冷光蛞蝓身上收集8個生體螢光黏液。", description = "艾澤萊晶岩淬煉的過程會產出一種肉眼無法看見的副產品，但只要透過折射過的生體螢光就能輕易顯現。\n\n海底到處都是能製造生體螢光的生物，我們能用來追蹤這個武器庫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55871] = {title = "集結朋友", objective = "為納姆收集沙爪蟹和淤泥蠕行者。", description = "外面十分危險。\n\n在海布林海窟很安全。\n\n我們找到迷路的螃蟹、蛞蝓，還有其他朋友。\n\n他們會在這裡獲得一個新的名字和新家。\n\n尋找這樣的朋友，並帶他們回家。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 波恩‧括鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55872] = {title = "他們的藏身之處", objective = "使用新鮮的海綿讓5位贊季爾納迦刺客現身，並殺死他們。", description = "那些鬼鬼祟祟的蛇類開始派出刺客了。\n\n他們藏身在附近，宰殺那些他們無法運送到奴隸監獄的人。\n\n就連海綿都不想要和他們有掛勾！\n\n這些孢子可以讓奸險的納迦現身…然後你就可以直接殺掉他們。\n\n我們一定要保護人民的安全！", progress = "你把他們都找出來了嗎？", completion = "哈！他們恨死那種東西了。\n\n摧毀得漂亮。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55873] = {title = "殺死海渣渣", objective = "殺死海渣渣。", description = "呣格勒！呣格嚕呣格呣爾格爾，古呣呣爾格爾拉魯格爾。\n\n<拉格呣爾焦急地四處跳躍，並指著洞穴。>\n\n格呣勒格呣爾格拉格呣爾格呣，呣爾格克瑞屈格勒爾。\n\n<他露出一個害怕的面孔，並用雙手做出一個箝擊動作。>\n\n呣爾格拉格勒格，呣爾格呣呣爾！呣爾格格呣爾，拉爾格。", progress = nil, completion = "拉呣呣爾格爾！魯爾呣爾格，呣爾格！\n\n&lt;拉格呣爾笑了。&gt;", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55874] = {title = "塞住噴泉", objective = "封住所有不穩定的噴泉。", description = "我們隨時都會被噴泉擊中。\n\n潮石的效果散佈得很廣。\n\n我們必須盡一切所能，預防進一步的破壞。\n\n用這種密封材料拖延下一波噴發！", progress = nil, completion = "你有被打中嗎？我覺得你有。\n\n這很正常！做得漂亮。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55875] = {title = "塞住噴泉", objective = "封住所有不穩定的噴泉。", description = "看好這個地點就對了…隨時都有可能…\n\n在這些噴泉噴發之後，衝過去將它封住。\n\n它們搖得越兇，分崩離析的情況就越慘！\n\n我們得制住這些東西。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55876] = {title = "塞住噴泉", objective = "封住所有不穩定的噴泉。", description = "地震！蛇！水從四面八方湧來。\n\n這附近到底出了什麼事？\n\n奈莉提過，為了防禦，我們得塞住一些洞，沒想到她居然是認真的。\n\n帶點濃稠黏液，在下一次噴發之前，把洞黏起來。", progress = nil, completion = "沒錯！那還真是個麻煩的英雄行為！", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55877] = {title = "塞住噴泉", objective = "封住所有不穩定的噴泉。", description = "我們一直在關注這些不穩定的噴泉。\n\n自從水退開之後，大海一直想找個方式重返這裡。\n\n如果我們讓它四處爆發，我們就完蛋了！\n\n幫我把這些洞塞好！\n\n不過，要小心，我發現有個困難的地方，在於你需要暴力一點。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55878] = {title = "塞住噴泉", objective = "封住所有不穩定的噴泉。", description = "你聽說噴泉的事了嗎？\n\n你可以看到水正在填滿它原先所在的區域，每個新露出來的地方都一樣。\n\n海洋十分憤怒。我也不覺得她有多喜歡艾薩拉。\n\n我們會繼續填滿這東西，直到我們找到一個一勞永逸的解決方案。", progress = nil, completion = "謝謝你，朋友。\n\n我有種感覺，那撐不了太久。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55879] = {title = "騎乘科學強化的野豬", objective = "騎乘巨型野豬摧毀不死大軍。", description = "我們不清楚尺寸修改器的效果能持續多久，所以我們得馬上行動。\n\n我們要騎著這頭巨型野豬掃盪擋在我們跟亨利之間的那支不死軍隊。\n\n大型的敵人散發著黑暗能量。如果能摧毀他們，很可能會一併消滅附近的敵人。\n\n希望亨利有更多關於巨魔計畫的資訊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊之斧遠征隊長弓遠征隊法杖遠征隊法杖遠征隊巨斧遠征隊巨劍遠征隊法杖遠征隊法杖遠征隊長弓遠征隊短劍遠征隊匕首遠征隊匕首遠征隊鬥棍遠征隊鬥棍您會收到：\n\n"}
MultiLanguageQuestData['tw'][55880] = {title = "重新分配動力", objective = "使用NRG-100型為6枚儲能裝置充電。", description = "歡迎回來，親愛的實驗對象。\n\n今天的實驗是…\n\n<普莉絲蒂翻動一些紙張並露出微笑。>\n\n…我的寵物計畫，NRG-100型！\n\n我很榮幸在此宣佈，我在效率、潛能與毀滅性貢獻了諸多改善。\n\n而且，犧牲的部分只有穩定性！\n\n準備開始的時候，就牽住NRG-100型吧。", progress = nil, completion = "神奇的實驗，親愛的實驗對象！\n\n跟據這些結果，我會對NRG-100進行下一步改裝。接下來就是在幾天內讓它準備萬全，進行後續測試。", rewards = "您會收到：\n\n儲能裝置"}
MultiLanguageQuestData['tw'][55881] = {title = "淨化圖騰", objective = "在5根鷹身人圖騰上放火。", description = "整個區域到處都是四散的鷹身人圖騰。\n\n鷹身人最出名的一點，就是運用他們的魔法來腐化四周的一切。就算是現在，我也可以聽到空中的邪惡低語…\n\n我們一定要摧毀這些圖騰，免得有人被他們的黑暗魔法污染！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊鎧甲束腰遠征隊布索遠征隊鎖甲護腰遠征隊皮甲腰帶遠征隊鎧甲束腰遠征隊鎖甲護腰遠征隊皮甲腰帶遠征隊布索您會收到：\n\n"}
MultiLanguageQuestData['tw'][55882] = {title = "給基地的訊息", objective = "回到聯盟營地並與蓋瑞克船長交談。", description = "我們辦到了！真痛快！當冒險者都是這種感覺嗎？\n\n我很喜歡！\n\n我們回營地向船長回報成果吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊鎧甲腿甲遠征隊布甲護腿遠征隊鎖甲護腿遠征隊皮甲腿甲遠征隊鎧甲腿甲遠征隊布甲護腿遠征隊鎖甲護腿遠征隊皮甲腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][55883] = {title = "飛嘯如魟", objective = "帶7枚深海魟魚卵。", description = "我想要找到還沒孵化的深海魟魚卵，這樣子我們才能和它們締結連繫。\n\n至少，在我們沒辦法游泳時，我們可以飛！\n\n幫我帶更多卵來，這樣我們就能開新的工作，不如就叫魟魚騎士吧！", progress = "你有找到很多蛋嗎？", completion = "啊！完美！我們馬上就可以感受到勁風吹拂了！", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 波恩‧括鰭稜光法力珍珠"}
