MultiLanguageQuestData['tw'][55983] = {title = "更安全的地方", objective = "護送莫嚕前往梅札米爾。", description = "<這個魚人似乎狀況不太好。也許跟你的盟友一起待在梅札米爾比較安全。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55984] = {title = "一流的防禦", objective = "殺死50個納迦。", description = "科奧叫我盯緊納迦，所以我就在這看著納迦。\n\n他們很壞欸，朋友，你知道的…真是…可怕、恐怖，惡劣的怪物。 \n\n我不覺得我還能繼續冷眼旁觀。\n\n他們說最好的防禦就是…什麼來著…\n\n幫我教訓他們，想耍壞，就輾爛！", progress = nil, completion = "這是我最開心的一天。謝謝你，朋友。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][55985] = {title = "超級閃亮亮", objective = "收集10枚灌魔珍珠。", description = "在下面的池子裡，有些小小的可愛珍珠。 \n\n在某種艾薩利的儀式中，會將它們丟進去。\n\n我根本不知道它們代表了什麼含意，不過我想要拿點回來。\n\n拜託，能當個可愛的潛水伕，下去幫我撈一點嗎！", progress = "你把珍珠都拿回來了嗎？", completion = "我感覺到它們在發光！柔光透過我的雙手，灑在海床上。\n\n真美。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55986] = {title = "打破幾顆蛋", objective = "摧毀10個盤淵蛋。", description = "這個房間真是又可愛、又嚇人。\n\n在此處出生的東西，會毀掉無數的生命。\n\n我們沒辦破壞豆莢，但我們可以對付負責守護的毒蛇，打破牠們的蛋。\n\n處理掉這些蛋，多一顆是一顆。\n\n可憐的蛋…", progress = nil, completion = "負責守護納迦的飛蛇，數量越少越好。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55988] = {title = "正如待宰的巨魔", objective = "在暗槌城塞裡殺死8隻巨魔。", description = "情況很遭，<name>。凱爾菈隊長被魔髮束縛了了，巨魔正在準備攻擊我們的朋友，而且他們的儀式快要完成了！\n\n我得保持冷靜。我們不能現在放棄，對吧？\n\n聽起來可能很冒險，但我們需要對巨魔開戰。\n\n我們處於敵人陣營中，如果展開突襲，就能轉移針對營地的敵人注意力。\n\n盡你所能擊倒巨魔，這樣他們應該就沒辦法攻擊我們的朋友了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊皮甲手套遠征隊鎧甲護手遠征隊布甲手套遠征隊鎖甲護手遠征隊皮甲手套遠征隊鎧甲護手遠征隊布甲手套遠征隊鎖甲護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][55989] = {title = "投石車毀滅", objective = "在暗槌城塞裡炸掉4台投石車。", description = "那些巨魔好像打算攻擊我們在營地的朋友！\n\n我看到他們準備了幾輛投石車。我沒想過這些笨蛋能使用那樣的武器。\n\n慶幸的是，感謝林迪那個小傢伙，我帶了一些特別的東西。\n\n拿著這些炸彈。它們可以對巨魔的投石車發揮奇效！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55990] = {title = "控制他們的石頭", objective = "從賈格納、烏格和古郎克手中取得結界石，並釋放凱爾菈隊長。", description = "凱爾菈隊長無法撐太久。我們得取得結界石，在她被害死前打斷儀式。\n\n我們會在這邊擋住敵人。你去解決巨魔副官，取得那些結界石！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][55991] = {title = "通往開始的結束", objective = "騎乘聯盟獅鷲獸回到暴風城。", description = "現在增援部隊抵達，暴風雨平息，我們也該回暴風城了。\n\n<name>，在這場行動中，你和其他新兵的表現都非常傑出。我像國王報告時，一定會表揚你們的貢獻。\n\n騎上獅鷲獸吧。該回家了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊布甲長袍遠征隊鎧甲護軀遠征隊鎖甲護甲遠征隊皮甲外套遠征隊布甲長袍遠征隊鎧甲護軀遠征隊鎖甲護甲遠征隊皮甲外套您會收到：\n\n"}
MultiLanguageQuestData['tw'][55992] = {title = "地城：暗槌城塞", objective = "完成地城「暗槌城塞」。", description = "戈爾果斯打算讓一頭威力強大的龍死而復生，那頭龍叫做雷妮爾。\n\n他在城塞頂端進行黑暗儀式。你救了我和我的成員，阻礙了他的計畫。\n\n現在你必須衝進城塞，阻止他完成儀式。他的黑暗法術，是對聖光的褻瀆。\n\n我們需要手頭的每一分助力。戈爾果斯最精英的副手在城塞裡等著我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "遠征隊鎧甲頭盔遠征隊布甲兜帽遠征隊鎖甲頭盔遠征隊皮甲頭盔遠征隊鎧甲頭盔遠征隊布甲兜帽遠征隊鎖甲頭盔遠征隊皮甲頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][55993] = {title = "少許優勢", objective = "收集12根刺棘蟹尖刺。", description = "在最黑暗的洞穴中，納迦的城市下方，你可以找到它們。\n\n恐怖的小螃蟹，長著尖銳鋒利的脊刺。\n\n我想也許可以找個方式來使用它們。飛行物體在水裡的效果並不好，但現在…\n\n幫我們收集幾個回來！\n\n小心，其中有些螃蟹可能比你想像中的狡猾。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][55994] = {title = "別喝為上", objective = "取回12個被偷的油料容器。", description = "這些穴居怪盯著我們的一舉一動。\n\n他們看到我們把油料倒進各種不同的機器，所以他們現在開始偷油來喝。我猜，他們認為喝油就可以讓他們化為機器之身！\n\n我們得在他們把油喝光之前拿回來！", progress = "快點把油拿回來！", completion = "你做得很漂亮。", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80儲能裝置耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][55995] = {title = "我們可以修好它", objective = "從廢瓦據點的敵人身上收集40個備用零件和1枚儲能裝置 。", description = "<看來鑽探機具足以打穿附近的殘骸，但顯然已經壞了。\n\n如果你能收集到需要的零件，伊拉敏王子應該可以告訴你如何修好它。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件儲能裝置"}
MultiLanguageQuestData['tw'][55997] = {title = "飢腸轆轆的多頭蛇", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][56000] = {title = "我們有螃蟹！", objective = "收集12隻爆鉗螃蟹。", description = "<name>，你來得正是時候。獵螃蟹的所有準備工作都完成了！\n\n好吧，好吧…我知道你在想什麼。D.H.E.T.A.的創始成員怎麼能容許狩獵這種事？\n\n我就對你實話實說吧，<name>。我這邊滿是飢腸轆轆的魚人，他們只吃三種東西：螃蟹、魚，和人。\n\n如果這個理由還不夠，這個區域的螃蟹過剩，正在消滅本地的蛆蟲數量！\n\n在我們採取行動之前，要死掉多少條無辜的蛆蟲，<name>？", progress = "在我們採取行動之前，要死掉多少條無辜的蛆蟲，<name>？", completion = "你拿回來的螃蟹籠還真不少，&lt;name&gt;。太棒了！請把它們丟在酒吧後面，接下來我處理就好。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][56001] = {title = "醉醺醺的盛怒魚人", objective = "收集12桶「摻海」淡啤酒。", description = "那些可惡的血鰭帶著所有啤酒跑掉了！\n\n我一直在實驗，想用納沙塔爾的本地材料來釀酒。不過這還沒完成，目前我必須仰賴從船艦殘骸中找到的殘存酒品。\n\n我的啤酒存貨本來就不多了，但是托那些血鰭魚人小偷的福，現在一滴都不剩！如果我們不把東西弄回來，馬上就要面對一群火冒三丈的客人。\n\n請在一切還不算太遲之前，從血鰭村把被偷的啤酒拿回來！", progress = "那些可惡的血鰭帶著所有啤酒跑掉了！", completion = "太好了，&lt;name&gt;！你取回的啤酒量還真不少，和被偷的量差不多。這些血鰭簡直是一無是處，淨會惹麻煩！", rewards = "您會收到：\n\n串烤鰻魚肉食譜：串烤鰻魚肉稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][56002] = {title = "呣戈洛奇的呣戈咕嚕", objective = "從血鰭村取得呣戈洛奇的呣戈咕嚕。", description = "我的廚師呣戈洛奇把呣戈咕嚕搞丟了，要是我們不找回來，他就不工作。\n\n我整座酒吧滿是飢餓魚人，在呣戈洛奇開工之前沒東西可以餵飽他們。要是沒辦法儘快為呣戈洛奇找回呣戈咕嚕的話，馬上就要有一場暴動了！\n\n我不知道你怎麼想，但我絕對不想成為今晚的主菜。\n\n稍早有些血鰭在附近徘徊。到血鰭村搜尋呣戈咕嚕的下落，找到之後馬上把它帶回來給我。", progress = "要是沒辦法儘快幫呣戈洛奇找回他的呣戈咕嚕的話，馬上就要有一場暴動了！", completion = "你找到它了！原來這就是呣戈咕嚕？我還以為它會更大一些。你把它送還給呣戈洛奇的話，他一定會很開心的！", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
