MultiLanguageQuestData['tw'][56053] = {title = "最後行動", objective = "殺死邦多‧巨塊。", description = "接受足量機械化的我們想辦法活了下來，但這不是重點。邦多‧巨塊為了全面機械化，不惜出賣我們並打造巨大機器人攻擊鏽栓。\n\n他會持續與我們作對，直到我們剩下的人全數死亡。\n\n我們必須即刻除掉這項威脅。", progress = "你能幫我應付這項威脅嗎？", completion = "我們可以現在開始重建。", rewards = "您會收到：\n\n備用零件"}
