MultiLanguageQuestData['tw'][56082] = {title = "機械人暴怒", objective = "殺死15個攻擊的機器人。", description = "打從我們登陸之後，這些機器人一直在攻擊我們。我們得守住海灘！\n\n我的遠征隊守衛需要你的協助，<name>。幫我個忙，毀掉海灘和林地中的機器人。您會收到：\n\n\n\n任意等級", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 80–80儲能裝置\n\n等級 60–80耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56083] = {title = "不安全的工作環境", objective = "殺死15個攻擊的機器人。", description = "這些機器人真的死不放棄耶！\n\n我們花大錢請了世界上最優秀、最聰明的哥布林，不能讓那些秀逗的機器害他們無法輪班。\n\n因為這種不安全的工作環境，技工工會的代表現在正在瘋狂嘮叨，快去保護工人！", progress = nil, completion = "謝了，&lt;name&gt;。技工跟我都欠你一次。", rewards = "您會收到：\n\n\n\n等級 60–80耗盡的儲能裝置\n\n等級 51–80備用零件\n\n等級 60–70儲能裝置"}
MultiLanguageQuestData['tw'][56086] = {title = "藍圖：全像數位化繼電器", objective = "將藍圖上傳至帕斯卡K1N6型的資料庫。\n\n已提供物品：\n", description = "<這張藍圖詳述了如何製作某種全像傳送器。\n\n你應該可以將藍圖上傳到帕斯卡K1N6型在鏽栓鎮的資料庫。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上傳：全像數位化繼電器\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56087] = {title = "藍圖：實驗性冒險者強化", objective = "將藍圖上傳至帕斯卡K1N6型的資料庫。\n\n已提供物品：\n", description = "<這張藍圖詳述某種環狀東西的製作方式…也許是某種戒指或飾品？\n\n你應該可以將藍圖上傳到帕斯卡K1N6型在鏽栓鎮的資料庫。>", progress = nil, completion = "你有拿到新藍圖嗎，我的肉身朋友？\n\n我會盡速將它加入我的資料庫。", rewards = "您會學到：\n\n上傳：實驗性冒險者強化\n\n您還會收到：\n\n"}
