MultiLanguageQuestData['tw'][56131] = {title = "安全第一", objective = "在機械岡島上擊敗稀有敵人。", description = "有許多危險的生物和我父親的盟友，都在尋找毀掉我們的良機。\n\n幫忙守住這座島，找出並消滅五個我們最強大的敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n電流振動器"}
MultiLanguageQuestData['tw'][56136] = {title = "英雄戰爭前線：激流堡之役", objective = "在激流堡之役擊敗部落。", description = "如果部落以為他們能打下激流堡，那就太天真了！阿拉希不會淪陷的！\n\n做好作戰準備。", progress = nil, completion = "打得很出色，&lt;name&gt;，但我怕還沒到放鬆戒備的時候。我很確定在重建激流堡時，敵人不會呆坐在那裡。", rewards = "您會收到：\n\n戰爭前線裝備箱第七軍團軍功獎章艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56137] = {title = "英雄戰爭前線：激流堡之役", objective = "在激流堡之役擊敗聯盟。", description = "我們的敵人正無所不用其極地佔領阿拉希，我們絕不能眼睜睜看阿拉希淪陷！在要塞重建好之前，我們必須阻止他們！\n\n拿起武器，我們要和聯盟作戰了。", progress = nil, completion = "一場精彩的戰鬥，&lt;name&gt;。你再次證明你是部落的偉大戰士。", rewards = "您會收到：\n\n戰爭前線裝備箱榮勛軍團軍功獎章艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56139] = {title = "廢料場寶藏", objective = nil, description = "這邊的每個人都需要努力工作，才能找到我們需要的資源。\n\n尋找並開啟島上的十個機械箱。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n電流振動器"}
MultiLanguageQuestData['tw'][56141] = {title = "安全第一", objective = "在機械岡島上擊敗稀有敵人。", description = "有許多危險的生物和我父親的盟友，都在尋找毀掉我們的良機。\n\n幫忙守住這座島，找出並消滅五個我們最強大的敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n電流振動器"}
MultiLanguageQuestData['tw'][56142] = {title = "適應、改進、克服！", objective = "20個純淨獵犬螺栓、4個腳架XS、以及2個哨兵腳根。", description = "伊塞菈‧械損還活著，她是鏽栓最強的鬥士，但她的腿斷了。若我們要生存下來，我會需要零件來修復她並進行升級。\n\n這裡到處都是可供我們回收零件的機器。只要持之以恆，我們應該就能把伊茲拉的腿修好。\n\n幫我取得下列零件。", progress = "我們需要開始搜尋！", completion = "這些狀況非常好！", rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][56143] = {title = "艾琳娜教授的命運", objective = "擊敗嚙龍族母，收集記憶核心，然後啟動回憶塔，見證艾琳娜教授的命運。", description = "從它的外觀來看，艾琳娜的故事應該有個非常有趣的結局。這裡的這個水晶塔一直出問題，不過我應該知道原因！\n\n這些東西使用回憶核心，也就是在寶珠中心找到的小水晶。我敢說那座古老的法師塔裡就有一個。\n\n那裡有個比恐喉還大的嚙龍，所以，拿去吧，卷軸就是要用在這種時候。應該能在戰鬥中派上用場。她真的超大！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56144] = {title = "老娜夏之爪", objective = "帶著老娜夏之爪去找蜜背女王蜂領取獎勵。\n\n已提供物品：\n", description = "老熊的爪子上沾滿了蜂蜜。看來在你阻止她之前，已經洗劫了好幾個蜂巢。\n\n女王蜂一定會對這東西感興趣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n光亮熊肉"}
MultiLanguageQuestData['tw'][56145] = {title = "藍圖：先進冒險者強化", objective = "將藍圖上傳至帕斯卡K1N6型的資料庫。\n\n已提供物品：\n", description = "<此藍圖詳述了如何將更強大的力量凝聚至一只戒指或飾品上！\n\n你應該可以將藍圖上傳到帕斯卡K1N6型在鏽栓鎮的資料庫。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上傳：先進冒險者強化\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56146] = {title = "釀造藻莓酒", objective = "將藻莓酒帶到梅汀的挑戰，並交到梅汀手中。", description = "<這是一個空空如也的藻莓酒桶。\n\n如果有人能裝滿它，附近可能有人會滿懷感激。>", progress = "你幫我帶了什麼來嗎？", completion = "噢，你很清楚大姊姊喜歡些什麼！", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][56148] = {title = "戰鬥的號角：納沙塔爾", objective = "殺掉納沙塔爾的聯盟。", description = "我們在納沙塔爾的計畫，受到湧入的聯盟敗類破壞。\n\n盡可能地殺光他們，然後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][56149] = {title = "全部餵飽", objective = "收集10塊深海肉塊。", description = "我十分感謝你的聯盟為我的人民提供協助，但我們短缺食物與補給品，狀況已經迫在眉睫。\n\n如果我們不收集足夠的資源來照顧聯盟和我的氏族，我們會在一個星期內把食物耗盡。\n\n幸好，這個區域看來有數量充足的深海魟魚，但我需要狩獵方面的協助，才能為我們的營地收集到足夠的糧食。\n\n拿著這根深海繩鉤，用它從水面上方來捕捉深海魟魚。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][56151] = {title = "波恩最愛的菜餚", objective = "收集15個新鮮的鰻魚肉。", description = "波恩一直在幫忙照顧我們救回來的每個人。\n\n你能不能從南邊的鰻魚身上收集一些肉類？\n\n我要偶爾報答他一下，烹調他最喜歡的菜餚。\n\n這道菜對養傷的人也有很棒的療效。\n\n我敢保證，那就是美味的力量！", progress = "你拿到足夠的肉類了？", completion = "對我們來說，這真是道特別的佳餚。\n\n多謝你！", rewards = "您會收到：\n\n串烤鰻魚肉稜光法力珍珠納沙塔爾盟友 - 波恩‧括鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56152] = {title = "鱗片加工", objective = "收集20片多頭蛇鱗片。", description = "<class>，我很需要你的幫忙。我一直在獵殺附近的多頭蛇以取得鱗片，但我的武器在近距離戰鬥時弄壞了。\n\n多頭蛇的鱗片可以為戰士製作耐用且具有彈性的護甲。我們的氏族需要鱗片才能製作並修理我們的護甲。\n\n如果我們無法馬上補充材料，在對抗納迦的戰鬥中就會面臨裝備不足的問題。", progress = "你的狩獵完成了嗎？", completion = "多謝你，&lt;class&gt;。這些鱗片可以在對抗納迦的戰鬥中，為我們提供莫大助力。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][56153] = {title = "最美味的蚌", objective = "收集10枚奈普圖恩蚌。", description = "奈普圖恩蚌是安寇恩飲食的重要一環。\n\n很多人都忘了在戰爭期間，補充足夠的養份有多重要。一位戰士可以帶著最精銳的武器進行訓練，但如果空著肚子或身體不適，在戰場上只能當塊絆腳石。\n\n現在梅札米爾已經成為你們聯盟的家園，我們一定要努力工作，收集足夠的食物來餵飽我們的士兵。\n\n你盡可能收集奈普圖恩蚌，越多越好，我來負責把它們安全送回營地。", progress = "你收集到奈普圖恩蚌了嗎？", completion = "這些會很管用的。\n\n謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][56154] = {title = "他們的藏身之處", objective = "使用新鮮的海綿讓5位贊季爾納迦刺客現身，並殺死他們。", description = "納迦開始派出刺客打擊我們的勢力了。\n\n他們藏身在附近，把那些他們沒辦法運到奴隸監獄的人都殺掉。\n\n帶上這塊特殊的海綿吧。這些孢子可以讓奸險的納迦現身。\n\n一旦刺客現身就把他們殺了，別讓他們有時間去找救兵。\n\n艾薩拉會滅亡的！", progress = nil, completion = "做得很好，&lt;class&gt;。現在走在路上更安全了。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][56155] = {title = "塞住噴泉", objective = "將5座不穩定的噴泉密封起來，並殺死受打擾的海藻團。", description = "這些危險的噴泉極不穩定、任何時候都有可能噴發。\n\n恐怕艾薩拉濫用潮石後，對納沙塔爾的元素造成了無法挽救的傷害。\n\n我們必須盡一切所能，預防進一步的破壞。\n\n帶著這種密封材料，並用它擋住下一波噴發。我趁這段時間，盡可能地安撫元素。", progress = nil, completion = "做得好，&lt;name&gt;。感謝你協助我封住噴泉，才能讓元素穩定下來，並將壓力引導到安全的地方。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
MultiLanguageQuestData['tw'][56156] = {title = "淬鍊後的刀刃", objective = "和劍客伊野斬一塊殺死15名納迦。", description = "我手中的刀刃剛剛鑄好，該用敵人的鮮血來淬鍊一番了。\n\n我聽說你精通數項戰技。我也十分擅長與死亡打交道，能和你並肩作戰是我的榮幸。\n\n和我同行吧，<class>，只要合力出擊，我們會讓敵人血流成河。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n世界任務\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56157] = {title = "塞住噴泉", objective = "將5座不穩定的噴泉密封起來，並殺死受打擾的海藻團。", description = "附近有幾座噴泉馬上就會噴發。\n\n不幸的是，這裡的元素不夠穩定，無法控制這股噴發力量。\n\n在我透過元素重新引導壓力，送到納沙塔爾安全地區宣洩時，需要有人塞住這些噴泉。\n\n趁我在回復元素的平衡時，帶著這種密封材料塞住噴泉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
MultiLanguageQuestData['tw'][56158] = {title = "塞住噴泉", objective = "封住7座不穩定的噴泉。", description = "在艾薩拉濫用潮石之後，元素變得越來越不穩定。\n\n附近的噴泉隨時都會噴發。每一次的噴發都有可能會摧毀地表上那細緻的生態平衡。\n\n趁我在回復元素的平衡時，帶著這種密封材料塞住噴泉，我才能重新分配地底爆發壓力，引導到安全地區宣洩。", progress = nil, completion = "做得好，&lt;name&gt;。感謝你協助我封住噴泉，才能讓元素穩定下來，並將壓力引導到安全的地方。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
MultiLanguageQuestData['tw'][56159] = {title = "塞住噴泉", objective = "封住7座不穩定的噴泉。", description = "這些危險的噴泉極不穩定、任何時候都有可能噴發。\n\n恐怕艾薩拉濫用潮石後，對納沙塔爾的元素造成了無法挽救的傷害。\n\n我們必須盡一切所能，預防進一步的破壞。\n\n帶著這種密封材料，並用它擋住下一波噴發。我趁這段時間，盡可能地安撫元素。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 先知歐里稜光法力珍珠"}
MultiLanguageQuestData['tw'][56160] = {title = "塞住噴泉", objective = "封住6座不穩定的噴泉。", description = "附近有幾座噴泉馬上就會噴發。\n\n不幸的是，這裡的元素不夠穩定，無法控制這股噴發力量。\n\n在我透過元素重新引導壓力，送到納沙塔爾安全地區宣洩時，需要有人塞住這些噴泉。\n\n趁我在回復元素的平衡時，帶著這種密封材料塞住噴泉。", progress = nil, completion = "做得好，&lt;name&gt;。感謝你協助我封住噴泉，才能讓元素穩定下來，並將壓力引導到安全的地方。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 劍客伊野斬稜光法力珍珠"}
MultiLanguageQuestData['tw'][56161] = {title = "返回大海", objective = "回到納茲札特的新鄉。", description = "現在控制住這裡的狀況了，我相信納沙塔爾那邊需要你幫忙！\n\n你何不返回海上，呃，或是返回海中，幫一下新來的人呢？", progress = nil, completion = "歡迎回來。我們還有工作要完成。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56162] = {title = "返回大海", objective = "回去納沙塔爾的梅札米爾。", description = "現在控制住這裡的狀況了，我相信納沙塔爾那邊需要你幫忙！\n\n你何不返回海上，呃，或是返回海中，幫一下新來的人呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
