MultiLanguageQuestData['tw'][56209] = {title = "起源大廳", objective = "擊敗阿瑪賽特的部隊，並重新啟動起源大廳的熔爐。", description = "看來起源大廳被一群自稱為阿瑪賽特的托維爾人佔據了。他們個個都是新面孔，而且來意不善，我對他們的瞭解也很有限。\n\n我們必須進到裡面重新啟動熔爐，否則艾澤拉斯就糟糕了！", progress = nil, completion = "我們修好熔爐了，卻來不及阻止恩若司癱瘓系統。\n\n我們恐怕還有很多事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56210] = {title = "顯現石", objective = "在納沙塔爾找出被魔法隱藏起來的寶藏。", description = "我有個禮物給你，<name>。\n\n這是你前所未見的石頭。對不知情的人來說，它似乎只是顆平凡的石頭，但它的價值遠不只如此。\n\n這是顆顯現石。它可顯示被魔法所隱藏的物品。當附近有異常狀況時，裡面鏤刻的符文就會開始發光。\n\n使用石頭來顯露被遠古魔法所隱藏的寶藏。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n顯現石"}
MultiLanguageQuestData['tw'][56211] = {title = "顯現石", objective = "在納沙塔爾找出被魔法隱藏起來的寶藏。", description = "我有個禮物給你，<name>。\n\n這是你前所未見的石頭。對不知情的人來說，它似乎只是顆平凡的石頭，但它的價值遠不只如此。\n\n這是顆顯現石。它可顯示被魔法所隱藏的物品。當附近有異常狀況時，裡面鏤刻的符文就會開始發光。\n\n使用石頭來顯露被遠古魔法所隱藏的寶藏。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n顯現石"}
MultiLanguageQuestData['tw'][56214] = {title = "乖女孩", objective = "從你的夥伴手中接受禮物。我在你身邊學到了好多東西，真不敢相信我們殺死了多少納迦！\n\n你剛來的時候，我還很懷疑你會不會有所作為。我們已經在這裡戰鬥了好久好久。我差點就失去了希望。\n\n可是現在，我們終於看到了離開黑暗深淵的一條出路！\n\n我們剛建立新鄉的時候，我收留了一隻嚙龍寶寶，後來我就一直在訓練她。我想…我希望你能擁有她。\n\n她會是一個很好的坐騎…也會是忠誠的朋友。您會收到：\n\n", description = "我在你身邊學到了好多東西，真不敢相信我們殺死了多少納迦！\n\n你剛來的時候，我還很懷疑你會不會有所作為。我們已經在這裡戰鬥了好久好久。我差點就失去了希望。\n\n可是現在，我們終於看到了離開黑暗深淵的一條出路！\n\n我們剛建立新鄉的時候，我收留了一隻嚙龍寶寶，後來我就一直在訓練她。我想…我希望你能擁有她。\n\n她會是一個很好的坐騎…也會是忠誠的朋友。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n嚙龍海藻潛獵者"}
MultiLanguageQuestData['tw'][56215] = {title = "閃亮甲殼", objective = "從你的夥伴手中接受禮物。你好啊，朋友。我只是想讓你知道，和你一起旅行是我這輩子做過最棒的事！\n\n我以前都不認為，我能學會這麼多戰鬥的技巧，可是現在，我覺得我可以繼續撐下去了。\n\n我會守護所有沒有能力保護自己的小傢伙！\n\n<波恩從某個地方拿出一隻螃蟹，螃蟹的甲殼十分亮眼。>\n\n就像這個小傢伙。我是在我們之前出去的時候找到他的。他當時看起來好害怕。\n\n嘿，你不如把他帶走吧？您會收到：\n\n", description = "你好啊，朋友。我只是想讓你知道，和你一起旅行是我這輩子做過最棒的事！\n\n我以前都不認為，我能學會這麼多戰鬥的技巧，可是現在，我覺得我可以繼續撐下去了。\n\n我會守護所有沒有能力保護自己的小傢伙！\n\n<波恩從某個地方拿出一隻螃蟹，螃蟹的甲殼十分亮眼。>\n\n就像這個小傢伙。我是在我們之前出去的時候找到他的。他當時看起來好害怕。\n\n嘿，你不如把他帶走吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n亮麗微光殼蟹"}
MultiLanguageQuestData['tw'][56216] = {title = "最後的傳人", objective = "從你的夥伴手中接受禮物。我們一起面對了許多敵人，而且每次都贏得了勝利。我們現在能安全待在這裡，都多虧了你，也感謝你教會我戰鬥的技巧。\n\n老實跟你說，朋友。我沒想到我能活這麼久。\n\n我們族人以前有家族，也有傳統。我們會在護符上雕刻符號，世世代代在深海獵人之間相傳。不管是祈求好運還是力量，每個家族都有自己的符咒。\n\n這個是我的。我沒有可以傳承的後代。希望你能擁有它。您會收到：\n\n", description = "我們一起面對了許多敵人，而且每次都贏得了勝利。我們現在能安全待在這裡，都多虧了你，也感謝你教會我戰鬥的技巧。\n\n老實跟你說，朋友。我沒想到我能活這麼久。\n\n我們族人以前有家族，也有傳統。我們會在護符上雕刻符號，世世代代在深海獵人之間相傳。不管是祈求好運還是力量，每個家族都有自己的符咒。\n\n這個是我的。我沒有可以傳承的後代。希望你能擁有它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n安寇恩雕刻護符"}
MultiLanguageQuestData['tw'][56217] = {title = "馴化野性", objective = "從你的夥伴手中接受禮物。我們相處的這段期間，我學到了非常多。我更瞭解自己的能力，也更清楚你的族人。\n\n面對挑戰時，你的表現非常英勇無私，就像我們自己人一樣。你跟我是同類人。\n\n這段時間以來，我一直在訓練一隻我之前發現的小嚙龍。他是隻很優秀的坐騎，我一直在等待有資格駕馭他的獵人。我想，我已經找到了夠格的獵人。\n\n來，他是你的了。您會收到：\n\n", description = "我們相處的這段期間，我學到了非常多。我更瞭解自己的能力，也更清楚你的族人。\n\n面對挑戰時，你的表現非常英勇無私，就像我們自己人一樣。你跟我是同類人。\n\n這段時間以來，我一直在訓練一隻我之前發現的小嚙龍。他是隻很優秀的坐騎，我一直在等待有資格駕馭他的獵人。我想，我已經找到了夠格的獵人。\n\n來，他是你的了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n深海珊瑚嚙龍"}
MultiLanguageQuestData['tw'][56218] = {title = "深海之美", objective = "從你的夥伴手中接受禮物。我們一起殺死了許多敵人，在沙場上灑了很多血。和你並肩作戰之後，我的實力足足進步了十倍。\n\n然而，我們千萬不能忘記，這裡曾是個和平之地。從前，我的族人能自由穿梭在洞穴和珊瑚礁之間。\n\n這裡還是有美好的事物，就在深海裡，在我們周圍。花點時間坐下來，享受你周遭的寧靜吧。你看，這裡有隻螃蟹的外殼好鮮豔。\n\n看到了嗎？就算是現在，這裡還是很美。您會收到：\n\n", description = "我們一起殺死了許多敵人，在沙場上灑了很多血。和你並肩作戰之後，我的實力足足進步了十倍。\n\n然而，我們千萬不能忘記，這裡曾是個和平之地。從前，我的族人能自由穿梭在洞穴和珊瑚礁之間。\n\n這裡還是有美好的事物，就在深海裡，在我們周圍。花點時間坐下來，享受你周遭的寧靜吧。你看，這裡有隻螃蟹的外殼好鮮豔。\n\n看到了嗎？就算是現在，這裡還是很美。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n耀眼微光殼蟹"}
MultiLanguageQuestData['tw'][56219] = {title = "淚水之典", objective = "從你的夥伴手中接受禮物。我們已經並肩作戰好一段時間了。我都沒想到，像我這樣的老水手，獵殺納迦的技巧還能有所進步，不過我們確實辦到了。\n\n我有東西要給你看…\n\n<維姆從他的背包拿出一本書。>\n\n遺忘是我們最不該做的事。\n\n我在這本書裡寫下許多名字，每一個名字都是破縛者的一員。現在他們都走了。\n\n我永遠不會忘記他們的名字。\n\n我想讓你擁有這本書。去告訴大家吧。告訴大家這些人是誰，告訴大家我們在這裡做了什麼。您會收到：\n\n", description = "我們已經並肩作戰好一段時間了。我都沒想到，像我這樣的老水手，獵殺納迦的技巧還能有所進步，不過我們確實辦到了。\n\n我有東西要給你看…\n\n<維姆從他的背包拿出一本書。>\n\n遺忘是我們最不該做的事。\n\n我在這本書裡寫下許多名字，每一個名字都是破縛者的一員。現在他們都走了。\n\n我永遠不會忘記他們的名字。\n\n我想讓你擁有這本書。去告訴大家吧。告訴大家這些人是誰，告訴大家我們在這裡做了什麼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破縛者之書"}
MultiLanguageQuestData['tw'][56222] = {title = "懸賞：納茲潔斯女士", objective = "取回納茲潔斯女士的頭顱。", description = "因攻擊納沙塔爾人民而受到懸賞。\n\n納茲潔斯女士一直在驅策武器大師打造更殘忍裝置。\n\n她最後出現在贊季爾殿堂。她很惡毒，小心行事。\n\n完成這個任務後，向喚海者烏拿回報以取得表揚。", progress = "她的統治結束了嗎？", completion = "辦得漂亮，&lt;class&gt;。納茲潔斯女士一直是此地人們的背上芒刺。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][56223] = {title = "懸賞：指揮官薩傑斯", objective = "取回指揮官薩傑斯的頭顱。", description = "因攻擊納沙塔爾人民而受到懸賞。\n\n指揮官薩傑斯試圖奴役部落的大量倖存者。\n\n他在贊季爾殿堂中指揮奴隸主，務必小心應對！\n\n在完成這個任務後，向喚海者烏拿回報以取得表揚。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56224] = {title = "懸賞：哈賈斯領主", objective = "取回哈賈斯領主的頭顱。", description = "因攻擊納沙塔爾人民而受到懸賞。\n\n哈賈斯領主試圖奴役部落的大量倖存者。\n\n他在贊季爾沙灘指揮奴隸主，務必小心應對！\n\n在完成這個任務後，向喚海者烏拿回報以取得表揚。", progress = "找到惡棍了嗎？", completion = "像他這麼無恥的傢伙，最好讓他人頭落地。\n\n你讓這個世界變得更美好了。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][56225] = {title = "懸賞：納吉絲女士", objective = "取回納吉絲女士的頭顱。", description = "因攻擊部落而受到懸賞。\n\n納吉絲女士領導了數場掠奪戰，並伏擊我方士兵。\n\n她最後出現在贊季爾殿堂外圍地區，務必小心應對！\n\n完成這個任務後，向喚海者烏拿回報以取得表揚。", progress = "你讓她閉嘴了嗎？", completion = "納吉絲女士帶來一片黑暗，現在整個世界看起來更明亮了。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56226] = {title = "懸賞：格勒索格", objective = "取回格勒索格的眼球。", description = "格勒索格要為許多消逝的破縛者生命付出代價。\n\n他們已經把諸多痛苦和我們分享了，把他的眼球帶回來。\n\n他就住在盤淵通道中。務必小心應對！\n\n完成這個任務後，向喚海者烏拿回報以取得表揚。", progress = "這是你第一次摘人眼珠嗎？", completion = "恐怖的觸手再也不會折磨他們了。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][56227] = {title = "懸賞：審判官伊絲里薩", objective = "取回審判官伊絲里薩的頭。", description = "因攻擊部落而受到懸賞！\n\n審判官伊絲里薩領導了數場掠奪戰，伏擊我方士兵。\n\n他最後出現在龍牙盆地附近。務必小心應對！\n\n在完成這個任務後，向喚海者烏拿回報以取得表揚。", progress = "你有讓他銳氣盡失了嗎？", completion = "倒了一個施暴者，還有很多個。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56231] = {title = "強化貯藏箱", objective = "找到納迦貯藏箱的鑰匙。", description = "<這口沉重的強化寶箱是出自納迦之手，似乎加上了某種魔法鎖。\n\n就算沒了魔法強化，這個貯藏箱還是需要某種鑰匙才打得開。\n\n鑰匙很可能在附近的納迦指揮官手中。", progress = "這個箱子鎖住了，沒鑰匙打不開。", completion = "當你轉動鑰匙的時候，你可以聽到箱裡的沉重栓子啪的一聲，帶著可觀的力量把箱子震開…", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 維姆‧鹽心稜光法力珍珠"}
MultiLanguageQuestData['tw'][56233] = {title = "秘法貯藏箱", objective = "找到納迦貯藏箱的鑰匙。", description = "這口沉重的強化寶箱是出自納迦之手，似乎加上了某種魔法鎖。\n\n就算沒了魔法強化，這個貯藏箱還是需要某種鑰匙才打得開。\n\n這樣的鑰匙很可能在附近的納迦指揮官手中。", progress = "這個箱子鎖住了，沒鑰匙打不開。", completion = "在你插入鑰匙時，魔法屏障開始消散…", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 波恩‧括鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56234] = {title = "朋友有難", objective = "支援你在納沙塔爾的盟友，先知歐里、獵手阿卡納和劍客伊野斬總計獲得3000點經驗點數。", description = "普莉希拉應該不會就此罷手，但至少她已經不再是我們的燃眉之急了。\n\n我們得仔細思考一下我們的下一步行動。在此同時，我們應該繼續與我們的新盟友安寇恩建立良好的關係。和他們合力固守這個區域並磨練他們的技巧，我們尚未脫離險境。\n\n恐怕最大的戰爭尚未到來。讓我們向他們展示，只要同心協力，我們就可以成功打敗艾薩拉的大軍！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n野心具現珍珠"}
MultiLanguageQuestData['tw'][56235] = {title = "深入納沙塔爾", objective = "支援你在納沙塔爾的盟友，讓其中一位升到等級3。", description = "我們還有很多事要做，<name>。但我們的部隊精疲力盡、需要休息。在疲勞下做出的決定，通常都是錯的。\n\n這些「破縛者」派出所有部隊來協助我們。如果想在艾薩拉的兵力之下求生存，就得支援我們的新盟友。\n\n和他們的一位獵人同行，並協助他們完成工作，我們會留在此地討論下一步行動。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n明晰之夢珍珠艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56236] = {title = "再接再厲", objective = "支援你在納沙塔爾的盟友，維姆‧鹽心、波恩‧括鰭和奈莉‧銳鰭總計獲得2400點經驗點數。", description = "艾胥凡暫時不會礙事了，但我們的處境還是相當危險。\n\n我得仔細思考我們的下一步行動，<name>。在此同時，我們應該繼續與新盟友破縛者建立良好的關係。在戰鬥中考驗他們，盡你所能的訓練他們。在往後的戰鬥中，我們需要他們的助力。\n\n我們會向他們證明，只要團結一心，就沒有無法突破的阻礙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n野心具現珍珠"}
MultiLanguageQuestData['tw'][56239] = {title = "怪異的銀刀", objective = "詢問安寇恩有關銀刀的事。\n\n已提供物品：\n", description = "<這把銀刀小巧又有點華麗，你發現它就在一個寶箱裡。\n\n比起戰鬥，這個更可能是用來進食或準備食物，納迦為什麼會需要這種東西？\n\n安寇恩可能會知道…>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56240] = {title = "怪異的銀刀", objective = "詢問破縛者有關銀刀的事。\n\n已提供物品：\n", description = "<這把銀刀小巧又有點華麗，你發現它就在一個寶箱裡。\n\n比起戰鬥，這個更可能是用來進食或準備食物，納迦為什麼會需要這種東西？\n\n破縛者可能會知道…>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56241] = {title = "預留線索", objective = "搜索辛艾薩拉，尋找有關奇異秘法寶箱的資訊。", description = "我們也曾找到類似的寶箱，就跟你說的一樣。我們相信，它們是在納迦之前來到這裡的人所留下的。\n\n有些甚至還被奇異的秘法符文封印，納迦似乎對那些符文最感興趣。\n\n我對它們知道得不多，只知道它們最常在城市廢墟出現。\n\n如果你打算解讀它們的歷史，我會從那裡著手。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56242] = {title = "預留線索", objective = "搜索辛艾薩拉，尋找有關奇異秘法寶箱的資訊。", description = "如果你在那些寶箱發現你不需要的東西，歡迎隨時帶來給我。\n\n我自己也發現過一些。看起來不像是納迦的東西，很可能屬於之前住在這座城市的人。\n\n有些被秘法魔法牢牢封印，我有看納迦拿過，很可能是從那裡面得到好東西了。\n\n我就只知道這些。如果你想上點歷史課，建議去城市廢墟裡面繞繞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56243] = {title = "死者的日記", objective = "搜索納沙塔爾的辛艾薩拉，尋找其他日記。", description = "<保存這本日記的附魔完好無缺，但正逐漸消逝。似乎是一個市民的日記。你隨便翻開一頁…>\n\n然後他膽大妄為地進入我們的召喚法陣，要求我們立即離開他的研究空間。誰會故意闖進混亂的召喚儀式之中？他簡直是瘋了。我們現在都這麼稱呼他，『狂人』馬爾迪瓦司。\n\n當然，他被次級召喚生物咬傷了腳，而且…\n\n<後面還有，沒什麼用，不過你推測可能還有更多這種秘典。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56244] = {title = "死者的日記", objective = "搜索納沙塔爾的辛艾薩拉，尋找其他日記。", description = "<保存這本日記的附魔完好無缺，但正逐漸消逝。似乎是一個市民的日記。你隨便翻開一頁…>\n\n然後他膽大妄為地進入我們的召喚法陣，要求我們立即離開他的研究空間。誰會故意闖進混亂的召喚儀式之中？他簡直是瘋了。我們現在都這麼稱呼他，『狂人』馬爾迪瓦司。\n\n當然，他被次級召喚生物咬傷了腳，而且…\n\n<後面還有，沒什麼用，不過你推測可能還有更多這種秘典。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56245] = {title = "魔法鎖", objective = "解開馬爾迪瓦司的秘法謎題，解開魔法鎖。", description = "<鎖似乎被魔法機制所保護著。\n\n顯然是馬爾迪瓦司的發明之一，根據日記的內容，你可以推斷，它很可能是用秘法謎題上鎖的。\n\n你環視房間，看到水中有些古怪。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56246] = {title = "魔法鎖", objective = "解開馬爾迪瓦司的秘法謎題，解開魔法鎖。", description = "<鎖似乎被魔法機制所保護著。\n\n顯然是馬爾迪瓦司的發明之一，根據日記的內容，你可以推斷，它很可能是用秘法謎題上鎖的。\n\n你環視房間，看到水中有些古怪。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56247] = {title = "寶物的故事", objective = "到納沙塔爾向工匠伊塔努回報。", description = "<你發現了馬爾迪瓦司的來歷，他是曾經住在這座城市的魔法師，是他製作了散布在納沙塔爾各處的秘法寶箱。\n\n根據聽到的事蹟，他是個不受歡迎的人物，但他卻不以為意，因為他個人十分特立獨行。\n\n你也發現並解鎖他其中一個「無法破解的」秘法鎖。這個知識或許能在之後的旅程中派上用場。\n\n工匠伊塔努一定很想聽到這個故事的結局。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n納沙塔爾古物\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56248] = {title = "寶物的故事", objective = "到納沙塔爾的新鄉向『尋寶者』寶兒塔回報。", description = "<你發現了馬爾迪瓦司的來歷，他是曾經住在這座城市的魔法師，是他製作了散布在納沙塔爾各處的秘法寶箱。\n\n根據聽到的事蹟，他是個不受歡迎的人物，但他卻不以為意，因為他個人十分特立獨行。\n\n你也發現並解鎖他其中一個「無法破解的」秘法鎖。這個知識或許能在之後的旅程中派上用場。\n\n『尋寶者』寶兒塔一定很想聽到這個故事的結局。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n納沙塔爾古物\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56249] = {title = "我是垃圾大師", objective = "把垃圾大師的披肩交給迦尼。", description = "你有什麼事嗎，有錢人？\n\n哈！你自以為是垃圾大師？在你眼前的可是垃圾之神！廢物的統治者！所有丟棄和不要事物的大師！\n\n原來你不想要那件又老又破舊的披風，耶？迦尼有更好的東西。\n\n你只要把那個老披風給我，迦尼就會好好照顧你…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n裝飾豐富的簾子"}
MultiLanguageQuestData['tw'][56250] = {title = "我是垃圾大師", objective = "把垃圾大師的披肩交給迦尼。", description = "你有什麼事嗎，有錢人？\n\n哈！你自以為是垃圾大師？在你眼前的可是垃圾之神！廢物的統治者！所有丟棄和不要事物的大師！\n\n原來你不想要那件又老又破舊的披風，耶？迦尼有更好的東西。\n\n你只要把那個老披風給我，迦尼就會好好照顧你…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n裝飾豐富的簾子"}
MultiLanguageQuestData['tw'][56256] = {title = "奧特蘭克戰場", objective = "進入奧特蘭克山谷，擊敗部落將軍德雷克塔爾。", description = "探險者協會的報告說，在奧特蘭克山谷中隱藏著許多神器，但是霜狼氏族的獸人不會讓我們接近它們。我們不能讓部落阻止我們對於學術的追求！擊敗霜狼的統帥，德雷克塔爾。他死了之後，獸人一定會分崩離析。\n\n德雷克塔爾就在奧特蘭克山谷南邊的霜狼要塞終。擊敗他，再回來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56257] = {title = "奧特蘭克戰場", objective = "進入奧特蘭克山谷並擊敗矮人將軍范達爾‧雷矛。", description = "雷矛部族的矮人和他們的盟友正在入侵奧特蘭克山谷，我們必須和他們決一死戰！\n\n必須擊敗統帥范達爾‧雷矛才能在奧特蘭克贏得勝利。\n\n范達爾會在奧特蘭克山谷北面的丹巴達爾。\n\n摧毀他，<name>，再回來找我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服點數"}
MultiLanguageQuestData['tw'][56258] = {title = "『森林之王』伊弗斯", objective = "殺死部落的人並從他們身上帶回一個風暴水晶給在奧特蘭克山谷的大德魯伊雷弗拉爾。", description = "霜狼氏族被一種墮落的元素能量保護著。如果我們不加以注意的話，他們的薩滿必然會利用這種力量來毀掉我們。\n\n這種能量已經不是議會可以控制的了！我們必須找到伊弗斯，尋求他的幫助。\n\n霜狼氏族的戰士身上帶著一種名叫暴風水晶的符咒，我們可以用這些符咒來召喚伊弗斯。快去拿來那些水晶吧，<name>！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][56259] = {title = "『冰雪之王』洛克霍拉", objective = "殺死聯盟的人並從他們身上把雷矛之血帶回去給在奧特蘭克山谷的霜狼村裡的原獵者瑟魯加。", description = "我來自雷霆崖，<race>。凱恩親自指示我在眼前這個艱難的時刻協助霜狼氏族。\n\n我們簡單明瞭地說吧，你必須擊倒我們的敵人，把他們的鮮血交給我。一旦我收集到了足夠的鮮血，召喚儀式就可以開始了。\n\n當元素之王衝入矮人的部隊中時，勝利就是我們的了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][56260] = {title = "解封的力量", objective = "返回心之室。", description = "勇士，在心之室有個特別的小驚喜。\n\n我不會爆料破壞你的興致，不過你最好快點過來。", progress = nil, completion = "我們有些好消息要告訴你，勇士！你一定會喜歡的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56261] = {title = "返回心之室", objective = "返回心之室。", description = "你好，艾澤拉斯的勇士。\n\n母親大人一直在觀察你跟艾澤拉斯之心的進展，她很高興你這麼努力讓它成長茁壯。\n\n至少我們認為她很開心，想要判斷她的情緒一直都很難。\n\n反正呢，有空就回來心之室一趟。我們還有很多該做的事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56262] = {title = "返回心之室", objective = "返回心之室。", description = "艾澤拉斯之心日益強大，它就是扭轉一切的關鍵。\n\n勇士，過來心之室，這裡需要你發揮一下本領。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56263] = {title = "解封的力量", objective = "返回心之室。", description = "勇士，在心之室有個特別的小驚喜。\n\n我不會爆料破壞你的興致，不過你最好快點過來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56264] = {title = "我們有螃蟹！", objective = "收集12隻爆鉗螃蟹。", description = "<name>，你來得正是時候。獵螃蟹的所有準備工作都完成了！\n\n好吧，好吧…我知道你在想什麼。D.H.E.T.A.的創始成員怎麼能容許狩獵這種事？\n\n我就對你實話實說吧，<name>。我這邊滿是飢腸轆轆的魚人，他們只吃三種東西：螃蟹、魚，和人。\n\n如果這個理由還不夠，這個區域的螃蟹過剩，正在消滅本地的蛆蟲數量！\n\n在我們採取行動之前，要死掉多少條無辜的蛆蟲，<name>？", progress = "在我們採取行動之前，要死掉多少條無辜的蛆蟲，<name>？", completion = "你拿回來的螃蟹籠還真不少，&lt;name&gt;。太棒了！請把它們丟在酒吧後面，接下來我處理就好。", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 波恩‧括鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56265] = {title = "醉醺醺的盛怒魚人", objective = "收集12桶「摻海」淡啤酒。", description = "那些可惡的血鰭帶著所有啤酒跑掉了！\n\n我一直在實驗，想用納沙塔爾的本地材料來釀酒。不過這還沒完成，目前我必須仰賴從船艦殘骸中找到的殘存酒品。\n\n我的啤酒存貨本來就不多了，但是托那些血鰭魚人小偷的福，現在一滴都不剩！如果我們不把東西弄回來，馬上就要面對一群火冒三丈的客人。\n\n請在一切還不算太遲之前，從血鰭村把被偷的啤酒拿回來！", progress = "請告訴我，你找到啤酒了。", completion = "太好了，&lt;name&gt;！你取回的啤酒量還真不少，和被偷的量差不多。這些血鰭簡直是一無是處，淨會惹麻煩！", rewards = "您會收到：\n\n串烤鰻魚肉食譜：串烤鰻魚肉稜光法力珍珠納沙塔爾盟友 - 波恩‧括鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56266] = {title = "呣戈洛奇的呣戈咕嚕", objective = "從血鰭村取得呣戈洛奇的呣戈咕嚕。", description = "我的廚師呣戈洛奇把呣戈咕嚕搞丟了，要是我們不找回來，他就不工作。\n\n我整座酒吧滿是飢餓魚人，在呣戈洛奇開工之前沒東西可以餵飽他們。要是沒辦法儘快為呣戈洛奇找回呣戈咕嚕的話，馬上就要有一場暴動了！\n\n我不知道你怎麼想，但我絕對不想成為今晚的主菜。\n\n稍早有些血鰭在附近徘徊。到血鰭村搜尋呣戈咕嚕的下落，找到之後馬上把它帶回來給我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 奈莉‧銳鰭稜光法力珍珠"}
MultiLanguageQuestData['tw'][56267] = {title = "恩若司的低語", objective = "在心之室裡跟卡雷苟斯談話。", description = "你會不會好奇我當初是怎麼來到心之室這裡的？\n\n我當然是自願來到這裡的，但過程中有一段時間，好多人都在找尋我。\n\n卡雷苟斯還記得當時的事情。如果你想要知道我那時候如何同時避過代言者和古神的耳目，可以去請他告訴你詳細的經過。", progress = nil, completion = "我知道恩若司擁有無上神力，但是竟然能觸及待在心之室裡安全之地的黯角…\n\n我們必須做點什麼！要不然沒有人是安全的了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56301] = {title = "搶奪黃金", objective = "取回魚人寶藏。", description = "我聽過不少關於亡父、亡母、以及家傳寶藏的故事。完全不相信。我們全都趕來此處，打算搶在這些機械笨蛋之前奪走海盜黃金！\n\n如果這裡真的有黃金，一定就放在那群魚人守護的大箱子裡。\n\n殺掉他們的酋長、搜刮寶箱，然後我們五五分帳，因為情報是我透露的。", progress = "去拿黃金！", completion = "很高興能和你合作，這是你的那份錢！", rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][56304] = {title = "精靈貴族的性命", objective = "陪著凱爾亞‧月落進精靈貴族莊園，尋找她父親的靈魂。", description = "那邊那個，我需要一點幫助。\n\n在我過去稱為家鄉的地方，每個人都在洪水中喪命。我還不知道我的父親科林的下落。\n\n重回現場會讓我非常傷心，而且那裡有復仇靈魂在徘徊，早已不再是淨土。你可以幫我查一下父親的下落嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56305] = {title = "我們來釣魚！", objective = "捕捉並殺死深水巨喉。", description = "我們可能需要一些朋友的協助，才能把這尾魚弄上岸。\n\n在你準備開始時，使用百噚誘餌。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56306] = {title = "家傳珠寶", objective = "找回75枚家傳珠寶", description = "該死的海盜把我的珠寶偷走了…呃，我是指我姐的…嗯，老媽的珠寶。對，就是這樣。\n\n重點是，他們偷走了東西然後分灑在泥堆和藏寶箱中。或許還有幾台機器人和魚人分了一杯羹。\n\n我媽並不貪婪，她只想要幾條黃金項鍊和許多鑽石。我願意為這些東西付你錢。", progress = "幫我兄弟把那些珠寶偷回來！", completion = "所有珠寶都是我的！", rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][56308] = {title = "突擊戰：亞基蟲再現", objective = "在奧丹姆擊退亞基的攻勢。", description = "我們這邊快要被敵人給攻陷了。亞基蟲群的數量突然大增，我從來沒看過這麼多亞基蟲群！\n\n不知道我們還能堅守陣線多久。我們需要你去擊退敵人！", progress = nil, completion = "你拯救了我們的營地，也拯救了我們的人民。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n亞基蟲群寶箱艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56309] = {title = "友人溺亡之城", objective = "幫助珊蒂斯‧羽月搜索沉沒市場。", description = "勇士，我想請你幫我辦件私事，因為這件事我覺得不適合交給哨兵去做。\n\n這…這件事與聯盟無關，與戰爭無關，甚至與我們跟艾薩拉的戰鬥無關。單純只是我的私事。\n\n在我小的時候，燃燒軍團進攻我的城市。很多逃來這裡的倖存者不是溺死，就是碰上更悽慘的事。我必須知道他們後來怎麼了。\n\n你可以幫我找找他們的下落嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56310] = {title = "友人溺亡之城", objective = "幫助首席秘法師薩莉瑟拉搜尋沉沒市場。", description = "勇士，我有一個私人請託。這次不是為了部落，也不是為了這場戰爭。\n\n自從我上次走在這些街道上以來，已經過了一萬多年。這些人裡面有很多我都認識，我甚至還訓練過其中的一些人。\n\n你可以跟我一起去看看他們都經歷了些什麼事嗎？路途凶險，我怕我在試著窺探悲傷的過往時沒辦法冷靜。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56311] = {title = "溺無止境", objective = "護送珊蒂斯‧羽月通過沉沒市場。", description = "跟緊一點，勇士。我有一些魔法物品，說不定可以幫助我們短暫抵擋魔法攻擊，不過艾薩拉是我們一族有史以來最偉大的法師。\n\n面對她的力量，我不覺得這些小東西撐得了多久，甚至連有沒有用都不知道。\n\n準備好了就與我說一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56312] = {title = "溺無止境", objective = "護送首席秘法師薩莉瑟拉穿越沉沒市場。", description = "艾薩拉女王盯上我們了。我們得謹慎行事。\n\n不知道她會耍什麼花樣，跟緊我。不管這個威脅是什麼，我們都得突破它才能夠找到希瓦菈。\n\n準備好繼續上路之後，來找我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56313] = {title = "戰火之源", objective = "與契約記憶交談。", description = "我們四周有非常強大的魔法，是很久以前艾薩拉施法留下的餘波。\n\n如果你有足夠的勇氣與這個餘波交流，我會在旁邊掩護你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56314] = {title = "戰爭使者", objective = "與契約記憶交談。", description = "我們四周有非常強大的魔法，是很久以前艾薩拉施法留下的餘波。\n\n如果你有足夠的勇氣與這個餘波交流，我會在旁邊掩護你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56315] = {title = "這是他們的決定", objective = "救助珊蒂斯‧羽月。", description = "艾薩拉弄得世界四分五裂還不夠，現在還想把我們剩下的族人一起拖入深淵！\n\n那些不願成為納迦的人，就被困在這種半死不活的狀態，被束縛在這些淹水的廢墟之中。\n\n如果我們真的找到我朋友，我真害怕目睹他的慘況。\n\n等等，你有聽到什麼聲音嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56316] = {title = "這是他們的決定", objective = "幫助首席秘法師薩莉瑟拉。", description = "艾薩拉弄得世界四分五裂還不夠，現在還想把我們剩下的族人一起拖入深淵！\n\n那些不願成為納迦的人，就被困在這種半死不活的狀態，被束縛在這些淹水的廢墟之中。\n\n我開始擔心找到希瓦菈會怎樣。\n\n等等，你有聽到什麼聲音嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56319] = {title = "迅充合約", objective = "同意迅充合約。", description = "真是好消息，親愛的實驗對象！\n\n我兄弟和我合力修復了研究實驗室的65%功能。\n\n我們希望能在短期內恢復常態研究，但需要一批全新的勇敢實驗對象，協助我們將自然與科學的定理推展到極限！\n\n如果你有興趣的話，只需要先行同意我們的標準口頭合約…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56320] = {title = "第一次充能免費！", objective = "在邦多的機械場進入充能站，並用它充飽一個用盡的儲能裝置。", description = "親愛的實驗對象，你能感受到能量從地面向外擴散嗎？\n\n<弗力普深深的吸了一口氣。>\n\n少了電力帶來的刺激感，任何意義都不復存在。\n\n我和親愛的姐妹從埋藏在地下的高壓電纜偷接電力，但是最充足的電力還是在邦多的機械場。他密藏了整座機械岡城最粗壯的電纜，只供自個享用！\n\n如果你想充飽用盡的儲能裝置，你得想辦法從芙菈斯那邊進入充能站。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56321] = {title = "拯救科林", objective = "擊敗暗影施法者薇可翠絲。", description = "我的父親正受到那個納迦的折磨！\n\n<name>，我需要你幫我救他。我們不能讓納迦奴役他的靈魂。\n\n快點，如果我們不馬上行動，他就會落到跟其他人一樣的下場！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56322] = {title = "內藏的烈酒元素", objective = "前往啤酒節場地和釀酒大師阿清交談。", description = "<在釀造酒回到原本的平靜形態時，出現了一個奇怪的酒桶。\n\n或許釀酒大師阿清更瞭解這種奇怪現象。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章龍石"}
MultiLanguageQuestData['tw'][56324] = {title = "第一次充能要收費！", objective = "將使用費交給芙菈斯，然後用充能站充飽一個空的儲能裝置。", description = "你想要在我們的動力塔外面為儲能裝置充能？\n\n我完全不覺得意外，每個人都想。\n\n而且每個人都得付錢。你聽懂的話，我就不用再說一次。\n\n<芙菈斯朝背後吐口水。>\n\n我看得出你是新手。邦多為你們這些菜鳥提供了特別交易。\n\n單次充能，特別優惠價。\n\n要嗎？這種好事打著燈籠都找不到哦。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n存取權限：充能站\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56325] = {title = "力挽狂潮", objective = "突襲納迦營地，並取得葛剛尼斯潮石的控制權。", description = "沒有時間了，我們必須搶走葛剛尼斯潮石，使用標槍是最有可能突破周圍屏障的方法。\n\n守護者的力量非常可怕，但如果我們想向艾薩拉開戰，就必須擊敗它。我們的兵力將陣列在下方，就在他們的營地外。\n\n<name>，我把蘇拉瑪爾之槍託付給你。我們在即將來臨的戰鬥中會需要你的力量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠"}
MultiLanguageQuestData['tw'][56326] = {title = "從烏鴉口中救援", objective = "救出8位受傷的機械地精。", description = "有一大群烏鴉在獵殺鏽栓居民，實在令人反胃！\n\n伊拉敏王子請我盡可能的救出市民，但我也需要你的協助。我一路追查烏鴉下落來到這座山丘。我們把烏鴉從天上轟掉，然後由你去救機械地精。\n\n如果你需要我幫忙把烏鴉打下來，就用我的標記槍。", progress = nil, completion = "你就跟大家說的一樣厲害。", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80儲能裝置耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56327] = {title = "支離破碎的機器人", objective = "已經將12個再度活動的機器人送去給波爾頓‧簧火。", description = "我的工作就是切碎機器人。你帶來的任何機器人都會在廢料機中打碎成有用的零件。這是我們的雙贏！\n\n使用機器人充能器把壞掉的機器人帶來給我，我們就可以將他們打碎成備用零件。", progress = nil, completion = "我喜歡這些備用零件！你可以在這裡把機器人磨碎，想磨就磨！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 53–80耗盡的儲能裝置\n\n等級 60–70儲能裝置"}
MultiLanguageQuestData['tw'][56328] = {title = "別喝為上", objective = "取回12個被偷的油料容器。", description = "這些穴居怪盯著我們的一舉一動。\n\n他們看到我們把油料倒進各種不同的機器，所以他們現在開始偷油來喝。我猜，他們認為喝油就可以讓他們化為機器之身！\n\n我們得在他們把油喝光之前拿回來！", progress = "快點把油拿回來！", completion = "你做得很漂亮。", rewards = "您會收到：\n\n備用零件儲能裝置耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56334] = {title = "失控的機器人", objective = "破壞迴旋電擊機器人", description = "它失控了！\n\n我叫他們不要這麼做，但他們就是不聽。現在它完全失控，屠殺上面每個人。那是一台實驗性的旋風機器人。這種東西根本就不該造出來的！\n\n我們必須快點阻止它，不能讓它衝下來尋找更多受害者！\n\n破壞迴旋電擊機器人。", progress = nil, completion = "你的表現超越了那些只會打造機器人的傢伙。", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80儲能裝置耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56335] = {title = "想充能？就付錢！", objective = "將使用費交給芙菈斯，然後用充能站充飽一個儲能裝置。", description = "你想要在我們的動力塔外面為儲能裝置充能？\n\n我完全不覺得意外，每個人都想。\n\n而且每個人都得付錢。你聽懂的話，我就不用再說一次。\n\n<芙菈斯朝背後吐口水。>\n\n我看得出你是新手。邦多為你們這些菜鳥提供了特別交易。\n\n單次充能，特別優惠價。\n\n要嗎？這種好事打著燈籠都找不到哦。", progress = "你想要在我們的動力塔外面為儲能裝置充能？\n\n想要哭訴就省省吧。每個人都要付錢。\n\n<芙菈斯朝背後吐口水。>\n\n絕無例外。", completion = "允許限量存取。\n\n隨便你怎麼充，別把東西搞壞就好。\n\n&lt;芙菈斯朝背後吐口水。&gt;\n\n最重要的是，別管閒事。", rewards = "您會學到：\n\n存取權限：充能站"}
MultiLanguageQuestData['tw'][56336] = {title = "解密文物碎片", objective = "暴風之盾堡壘的艾希嵐要你到艾斯蘭主要道路外的外圍地區殺死一些生物，並帶回50個文物碎片。", description = "這些文物碎片似乎是來自我們在艾斯蘭外圍地帶所看到的那些生物。去那裡殺掉所有你看到的生物，並帶回至少50個碎片給暴風之盾堡壘裡的營火附近的法師艾希嵐。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56337] = {title = "解密文物碎片", objective = "戰爭之矛前哨站的芙拉要你到艾斯蘭主要道路外的外圍地區殺死一些生物並帶回50個文物碎片。", description = "這些文物碎片似乎是來自我們在艾斯蘭外圍地帶所看到的那些生物。\n\n去那裡殺掉所有你看到的生物，並帶回至少50個碎片給在戰爭之矛前哨站的法師芙拉。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56338] = {title = "沃拉斯必須死", objective = "殺死在艾斯蘭部落營地戰爭之矛裡的高階督軍沃拉斯。", description = "部落正阻礙著我們完成在艾斯蘭這裡的任務。他們的首領是高階督軍沃拉斯。他必須倒下。\n\n穿越過中央道路，進到戰爭之矛並殺死沃拉斯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服點數征服點數"}
MultiLanguageQuestData['tw'][56339] = {title = "崔布雷德必須死", objective = "殺死在艾斯蘭的聯盟營地暴風之盾要塞裡的崔布雷德總元帥。", description = "在艾斯蘭的戰鬥已經持續太久了。看起來好像是崔布雷德總元帥在帶頭打仗。只要她一死，聯盟就會土崩瓦解。\n\n向前推進，越過中央道路，一路殺到他們的要塞裡並取下崔布雷德的首級。\n\n為了部落！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服點數征服點數"}
MultiLanguageQuestData['tw'][56341] = {title = "恐酒齒輪", objective = "前往啤酒節場地和薇菈‧焰血交談。", description = "<恐酒的黑鐵同夥逃走了，只留下一小塊鑽地機零件。\n\n或許你的黑鐵盟友會想聽聽你的勝利事蹟。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章龍石"}
MultiLanguageQuestData['tw'][56344] = {title = "前往暗槌城塞", objective = "在暗槌城塞外面和蓋瑞克船長會面。", description = "現在只剩遠征隊的隊長還沒救出來了。林迪的斥候機器人發現她就在暗槌城塞外頭。\n\n美芮迪想出一個…有趣的隊長拯救計畫。這可能是我們的唯一機會。\n\n來吧，我們去暗槌城塞的陰影下會合，拯救行動得從那邊開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56346] = {title = "古代科技", objective = "把破損的能量核心帶去給梅札米爾的講師烏魯阿卡。\n\n已提供物品：\n", description = "<你回想了與納迦交手的經驗，以及他們擁有多少力量，你認為運用他們的力量來反制他們可能沒辦法帶來足夠的優勢。\n\n也許梅札米爾的講師烏魯阿卡可以幫助你修復這個核心，讓你用它來抵擋納迦的入侵。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56347] = {title = "來自海底深淵的機會", objective = "向工匠歐卡塔取得15個深淵裂片。", description = "<name>，我認為我們可以用這種東西來把護甲打造得更堅固一點。透過轉移它的能量，我們可以把鍛造出來的物品提升到前所未有的強度。\n\n不過沒這麼快就能夠辦到。我們得先修好這個裝置才行。\n\n要修理它需要一些強大的材料，通常要從這個區域裡那些比較厲害的生物身上才能收集到。\n\n不過，工匠歐卡塔十分擅長收集我們需要的材料，我會去確認他手頭有什麼東西。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n深淵法器\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56348] = {title = "永恆宮殿：我們可以使它更強大…", objective = "從永恆宮殿最強大的生物身上收集20個永恆光珠。", description = "修好了，在修理它的時候我突然想到，它其實還可以再輸出更多的能量。\n\n當然了，這會需要更強大的材料來升級它，能收集這種材料的地方，我只想得到永恆宮殿。\n\n艾薩拉的軍隊甚至是她自己都隨身攜帶著力量極其強大的物品。如果你可以帶一些那種東西回來，我至少能測試看看我的理論可不可行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56349] = {title = "永恆宮殿：突破極限", objective = "從永恆宮殿最強大的生物身上收集200個永恆光珠。", description = "現在知道怎麼強化這項工具的威力了，也許我們可以再更進一步擴展它的性能。\n\n帶更多那種飾物來給我。越多越好。\n\n我們來看看這玩意兒的極限可以到多少。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56350] = {title = "偵查宮殿", objective = "與珍娜‧普勞德摩爾女士交談以觀察偵查隊。", description = "<name>，我們不能永遠躲在這裡。必須有人去對付艾薩拉。\n\n不知道她設置了什麼防禦措施，貿然襲擊她的宮殿是不智之舉。你不在的時候，我已經派了一支偵查隊，但他們還沒有回報。\n\n我開始擔心了，<name>。等你準備好再告訴我，我會開始一個儀式，看看我們的偵查隊發生了什麼事。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n海底護腿海底足靴海底護手\n\n您還會收到：\n\n稜光法力珍珠"}
MultiLanguageQuestData['tw'][56351] = {title = "永恆宮殿：突破極限", objective = "從永恆宮殿最強大的生物身上收集200個永恆光珠。", description = "現在知道怎麼強化這項工具的威力了，也許我們可以再更進一步擴展它的性能。\n\n帶更多那種飾物來給我。越多越好。\n\n我們來看看這玩意兒的極限可以到多少。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56352] = {title = "永恆宮殿：我們可以使它更強大…", objective = "從永恆宮殿最強大的生物身上收集20個永恆光珠。", description = "修好了，在修理它的時候我突然想到，它其實還可以再輸出更多的能量。\n\n當然了，這會需要更強大的材料來升級它，能收集這種材料的地方，我只想得到永恆宮殿。\n\n艾薩拉的軍隊甚至是她自己都隨身攜帶著力量極其強大的物品。如果你可以帶一些那種東西回來，我至少能測試看看我的理論可不可行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56353] = {title = "來自海底深淵的機會", objective = "向『尋寶者』普洛克取得15個深淵裂片。", description = "<name>，我認為我們可以用這種東西來把護甲打造得更堅固一點。透過轉移它的能量，我們可以把鍛造出來的物品提升到前所未有的強度。\n\n不過沒這麼快就能夠辦到。我們得先修好這個裝置才行。\n\n要修理它需要一些強大的材料，通常要從這個區域裡那些比較厲害的生物身上才能收集到。\n\n不過，『尋寶者』普洛克十分擅長收集我們需要的材料，我會去確認他手頭有什麼東西。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n深淵法器\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56354] = {title = "古代科技", objective = "把破損的能量核心帶去給新鄉的羅姆。\n\n已提供物品：\n", description = "<你回想了與納迦交手的經驗，以及他們擁有多少力量，你認為運用他們的力量來反制他們可能沒辦法帶來足夠的優勢。\n\n也許新鄉的羅姆可以幫助你修復這個核心，讓你用它來抵擋納迦的入侵。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56355] = {title = "身經百戰", objective = "到各處消滅10個升級版、電鍍或是鏽蝕哨衛。", description = "在對抗機械岡國王的部隊時，有一把這樣的武器真的可以逆轉局勢。讓我們來看看他們的裝備，是否足以抵抗我們的新玩具。\n\n盡你所能解決機械岡國王的哨兵。", progress = "去殺些東西吧！", completion = "這樣才像話！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80儲能裝置\n\n等級 11–80耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56356] = {title = "永恆宮殿：女王的賭注", objective = "在永恆宮殿擊敗艾薩拉女王。", description = "沒有礙事的人了。前往宮殿吧，<name>。\n\n自負浮華女王可是足以跟上古之神分庭抗禮的角色，要是能打敗她絕對會是一個大成就。\n\n別搞錯了，艾薩拉可是當今最強大的巫女之一。我們不可以小看她的力量，也不可以小看她的計謀，她可是花了數千年的時間在準備與她的敵人作戰呢。但即便如此，我們也只有打敗她一途。\n\n我們都準備好了，就等你了。該前去赴她的邀約了嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56358] = {title = "永恆宮殿：女王的賭注", objective = "在永恆宮殿擊敗艾薩拉女王。", description = "我們已經打開通往皇宮的路了。我們必須做個了結。\n\n艾薩拉女王是現存最強大的巫女。在我們的大法師都還沒出生的數千年前，她就已經精通了各項魔法。\n\n但我們不能輸。要是敗了，她和她的暗黑僕從們將會任憑他們的意念重新改造整個艾澤拉斯。\n\n勇士，我們必須擊敗艾薩拉。你準備好了嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56361] = {title = "鏽栓調撥單：潮沫亞麻布", objective = "將20張潮沫亞麻布帶給吉菈‧交線。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n驅質備用零件戰爭物資戰爭物資戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][56362] = {title = "鏽栓調撥單：潮沫亞麻布", objective = "將20枚風暴白銀礦石帶給史卡吉特。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 60–80備用零件\n\n等級 60–60驅質戰爭物資戰爭物資戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][56365] = {title = "好心點，幫忙倒轉", objective = "將全像投影球交給鏽栓鎮的伊塞菈‧械損。", description = "你存在於此地是因為時間異常的關係，可是你必須回到你自己的時代，並在那裡幫助我們。\n\n我們可以從附近的保險箱機器人身上的全像投影球取得重要資料，趕在機械岡國王使用機械歸源器前將他擊敗。\n\n在你的時空中，把全像投影球拿給我。運氣好的話，我就能翻轉歷史，防止現在這個現實發生。", progress = nil, completion = "希望你把這個帶來給我，不會造成整個平行宇宙分歧。", rewards = "您會收到：\n\n\n\n等級 70–80儲能裝置\n\n等級 60–80備用零件耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56370] = {title = "打破幾枚蛋", objective = "毀掉10枚盤淵蛋。", description = "納迦利用這些洞穴來孵化他們那致命的盤淵毒蛇。\n\n在灌注黑暗虛無魔法之後，這些盤淵毒蛇特別危險。\n\n我們一定要在情況還來得及挽救之前阻止這一切。納迦兵力已經夠強大了，我不敢去想像萬一艾薩拉把這批盤淵毒蛇納入她的旗下，會發生什麼事。\n\n我們唯一的希望，就是在孵化之前把盤淵蛋都打破。", progress = nil, completion = "你做得很好，&lt;name&gt;。我們不能任由納迦組出變種的盤淵毒蛇軍隊。我們還是得繼續盯緊這個地方…", rewards = "您會收到：\n\n稜光法力珍珠納沙塔爾盟友 - 獵手阿卡納稜光法力珍珠"}
MultiLanguageQuestData['tw'][56371] = {title = "暮光雛龍的鱗片", objective = "帶這片龍鱗去濕地格瑞姆巴托上方給恩雅瞧瞧。\n\n已提供物品：\n", description = "<從幼小的暮光雛龍身上所掉下來的一片還沒長齊的龍鱗。\n\n又出現越來越多的暮光之龍了。這看起來頗為可疑。\n\n你應該帶這片龍鱗去給濕地格瑞姆巴托上方的恩雅瞧瞧，也許她最近有看到些動靜。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56372] = {title = "猴人圖騰", objective = "前往啤酒節場地和阿弟交談。", description = "<將猴人成功趕跑後，啤酒節重現生機。\n\n不過問題仍在：猴人是怎麼來到丹莫洛的？或許你可以問問某些擅長導航和旅行的人。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章龍石"}
MultiLanguageQuestData['tw'][56373] = {title = "吞猛浪的吞噬者", objective = "殺死猛浪吞噬者並抓取3尾泡泡眼小猛浪。", description = "附近的池塘裡，原本有很多泡泡眼小猛浪。但它們卻從上個星期開始一個個消失掉！\n\n有一個大型水元素在吞噬所有的魚！它們還活著，但只能在水元素體內游動。\n\n我需要你殺掉那頭元素，並抓三頭泡泡眼小猛浪回來讓我檢視它們的情況。", progress = "你殺掉那個元素了嗎？", completion = "你今天救了很多猛浪！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80儲能裝置耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56374] = {title = "泰坦級問題", objective = "到奧丹姆的起源大廳與麥格尼‧銅鬚會面。", description = "不能浪費時間了。\n\n少了起源熔爐，艾澤拉斯無力抵抗恩若司的腐化。而且，那裡面還有足以毀滅艾澤拉斯上所有生靈的武器！\n\n我們必須馬上前往熔爐。母親大人能守住這個要塞。\n\n快點，我會在那裡跟你會合。", progress = nil, completion = "你來得正是時候，&lt;name&gt;。\n\n這整個地方都失控了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56375] = {title = "前往蘭姆卡韓", objective = "到蘭姆卡韓與法歐瑞斯王會面。", description = "看來我們得等上一陣子，等母親大人瞭解如何使用熔爐。在這段期間，我們可以保護這裡，不讓人進一步破壞。\n\n你應該去蘭姆卡韓和托維爾人談談。我知道你曾經幫助過他們，所以他們或許可以助我們一臂之力，防止熔爐落入邪魔歪道手中。", progress = nil, completion = "&lt;class&gt;，歡迎來奧丹姆。\n\n我很想更熱情地招待你，不過我的人民恐怕又再次身陷危險處境。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56376] = {title = "步步進逼的威脅", objective = "在奧丹姆完成一場突擊戰。", description = "對托維爾來說，保護奧丹姆當地的泰坦造物是神聖的天職。不過，我們的人數正在減少，而我們每天所要面對的威脅則是日益壯大。\n\n即便有了新盟友的力量，我們也只能勉強擋住這些敵人。只要敵人之中有任何一方實力大增，就有可能壓倒我方、危及熔爐。這時就得靠你出力了。\n\n和卡姆塞斯將軍交談，瞭解我們當前的局勢。", progress = nil, completion = "威脅減輕了…至少目前是這樣。\n\n我們的斥候會繼續監視敵方的動靜。如果運氣夠好，我們應該可以在他們朝熔爐移動之前就擋住他們。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n死亡之門象徵艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56377] = {title = "熔鑄不停歇", objective = "到心之室找到麥格尼‧銅鬚，瞭解起源熔爐的事。", description = "感謝你在熔爐幫我一把。恩若司能夠以這麼快的速度滲透熔爐實在令人訝異，但至少我們及時抵達，在全面崩毀之前保住了它！\n\n現在，接下來的工作就是讓運轉效能回到百分之百。母親大人正在構思解決方案，而且我們應該有計畫了。", progress = nil, completion = "勇士，我們好像來了一場不得了的冒險了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56378] = {title = "失蹤的船員", objective = "救援失蹤的船員。", description = "難以置信。幾乎整個艦隊都…消失了！\n\n我們必須派遣船艦執行任務來支援我們的行動，但我現在要怎麼辦？\n\n若我們想振作過來，就必須由我人民裡的菁英助陣。我知道機會渺茫，但我需要你出去尋找他們。活著當然是最好。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：船長"}
MultiLanguageQuestData['tw'][56379] = {title = "失蹤的船員", objective = "救援失蹤的船員。", description = "難以置信。幾乎整個艦隊都…消失了！\n\n我們必須派遣船艦執行任務來支援我們的行動，但我現在要怎麼辦？\n\n若我們想振作過來，就必須由我人民裡的菁英助陣。我知道機會渺茫，但我需要你出去尋找他們。活著當然是最好。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：船長"}
MultiLanguageQuestData['tw'][56380] = {title = "落地", objective = "摧毀空中巡邏機XZ-2型", description = "機械岡國王有一具較早期的飛空單位出現了機械方面的問題，目前停靠在附近。\n\n他們正試圖修好它，所以我們得趁它還脆弱的時候行動。\n\n在他們修好空中巡邏機XZ-2型之前毀掉它。", progress = nil, completion = "我們的部隊又少了一個威脅。", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80耗盡的儲能裝置\n\n等級 60–70儲能裝置"}
