MultiLanguageQuestData['tw'][56429] = {title = "身陷險境", objective = "跟隨洛索瑪和薩莉瑟拉一起深入納沙塔爾。", description = "我不喜歡那個聲音…聽起來就像一支大軍！\n\n我們必須調查一下。\n\n在我們調查的時候，盡量別吸引太多注意。如果下面那裡有一支大軍，我們就必須快點找到藏身處。", progress = nil, completion = "這些納迦很快就要成為不受歡迎的人物了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56430] = {title = "誓死抵抗", objective = "問問羅姆有關辛葵觸鬚的事。\n\n已提供物品：\n", description = "<在處理辛葵一段時間之後，你從主幹上拔出了一根它的觸鬚。於此同時，觸鬚縮了回去，纏繞著不讓你拿到長在裡面的花朵。也許羅姆會知道該怎麼破解這株草藥的自我防衛機制。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採藥技術：辛葵(等級3)"}
MultiLanguageQuestData['tw'][56431] = {title = "少量的奧司曼", objective = "問問羅姆有關奧司曼裂片的事。\n\n已提供物品：\n", description = "<你挖了挖礦石，並撿起掉到地上的幾個碎片。肯定有個方法可以採這種礦，又不浪費掉它的任何一丁點資源。也許羅姆會知道該怎麼更有效率地採集這種礦物。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：奧司曼礦床(等級3)"}
MultiLanguageQuestData['tw'][56432] = {title = "狀礦連連", objective = "問問羅姆有關奧司曼粉塵的事。\n\n已提供物品：\n", description = "<你挖了挖礦，發現礦石的一大部分化為粉塵落到了你的腳邊。不過這種方式有維持住它的形狀，應該足夠拿來製作一些東西了。\n\n也許可以去跟羅姆聊聊，說不定有方法可以不讓這種損失發生。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n採礦技術：奧司曼礦層(等級3)"}
MultiLanguageQuestData['tw'][56433] = {title = "水淹聯盟", objective = "在戰爭模式下，於納沙塔爾殺掉25名聯盟玩家。", description = "聯盟緊咬著我們不放，不能容許他們繼續打斷我們的計畫。把他們的勇士逼入水之墓。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時佚戰場紀念物"}
MultiLanguageQuestData['tw'][56434] = {title = "懸賞：爆彈鼠和攔路穴居怪", objective = "消滅爆彈鼠和攔路穴居怪。", description = "他們在垃圾場四處大鬧，造成動亂與混沌，導致儲能裝置、備用零件遭到偷竊，吃掉了絕無僅有的機械雞翅還不付錢。\n\n特別注意攔路穴居怪，它會對活物施加暴力。\n\n消滅這兩位重罪犯是第一要務。", progress = nil, completion = "我們已經看膩這兩個傢伙了！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80耗盡的儲能裝置\n\n等級 60–70儲能裝置"}
MultiLanguageQuestData['tw'][56436] = {title = "小頭顱", objective = "把小頭顱拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<你在泥漿怪凝膠狀的外層底下找到了一個小骷髏。\n\n鏽栓鎮那邊恐怕有人失蹤了。\n\n你撿起頭顱，說不定還有機會認屍。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件儲能裝置"}
MultiLanguageQuestData['tw'][56437] = {title = "生鏽的管子", objective = "把生鏽的管子拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<故障的拾荒機器人現在成了一堆金屬，它的信號管有一側露在殘骸外頭。\n\n你把管子給取了出來。鏽栓的居民似乎是用垃圾來交易的，也許會有人想要這個東西。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件箱"}
MultiLanguageQuestData['tw'][56438] = {title = "閃爍的警報器", objective = "把閃爍的警報器拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<雖然機器人已經被摧毀了，但是警報器卻仍然在閃爍著。\n\n這顯然是機械岡國王很重要的哨衛。鏽栓的居民應該會想要知道它的死訊。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件儲能裝置"}
MultiLanguageQuestData['tw'][56439] = {title = "機械卵囊", objective = "把機械卵囊拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<你在故障的蜘蛛機器體內找到了機械卵囊。\n\n這不合理，機器不該用這種方式繁殖的。\n\n還是說其實會？\n\n鏽栓應該有人能解惑。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鎖鏈點火器線圈備用零件"}
MultiLanguageQuestData['tw'][56440] = {title = "小動物噴灑劑", objective = "把小動物噴灑劑拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<在機器人的殘骸裡面，你找到了一個裝有殺小動物噴劑的密封罐頭。\n\n它可以摧毀一切生命，就連老鼠這麼小隻的生物都能屠殺殆盡，看起來有些殘忍，但很符合機械岡國王的作風。\n\n鏽栓應該有人能提供更進一步的情報。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n電流振動器備用零件"}
MultiLanguageQuestData['tw'][56441] = {title = "咕咕盒", objective = "把咕咕盒拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<在閃著火花、冒著煙的單位35的殘骸中，你找到了一個小小的黑色立方體。\n\n看樣子是由金屬物質構成的，似乎沒什麼威脅性。\n\n定睛一看，你發現在金屬上刻有一個字詞 - 「咕咕盒」。\n\n這隻奇特的機械鳥禽運作的方式相當怪異。鏽栓應該會有人想要好好地來研究一番。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件箱"}
MultiLanguageQuestData['tw'][56442] = {title = "故障的單位6", objective = "把故障的單位6拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<單位6坐在這裡，對你的攻擊不為所動。\n\n這隻機械青蛙令你感到不對勁。它似乎是在模仿青蛙的習性，但它的行為有一種說不上來的怪異。\n\n附近的機械青蛙沒有一隻像它這樣。\n\n與其拆下它的零件回去研究，你索性把整隻青蛙都給帶走。畢竟它只有這麼一丁點大。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56443] = {title = "機械眼", objective = "把機械眼拿去機械岡島上的鏽栓給薇菈‧寂輪看。\n\n已提供物品：\n", description = "<單位17的機械體散成一堆金屬時，其中一顆眼睛亮了起來。\n\n你聽到了啪一聲的聲響，緊接著在一個小爆炸後，一顆眼珠子從頭裡飛了出來。\n\n你撿起眼睛，發現它抽搐了幾下，之後便失去了能量。\n\n鏽栓的居民好像很喜歡垃圾，也許他們會對這東西感興趣。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鎖鏈點火器線圈"}
MultiLanguageQuestData['tw'][56444] = {title = "擺尾王子的戳戳叉子", objective = "到納沙塔爾的梅札米爾，將擺尾王子的戳戳叉子拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<落敗王子的堅韌魚叉。\n\n它似乎半點力量都沒有。事實上，它看起來相當平凡，還有點生鏽。\n\n你還是把它裝進口袋裡。說不定工匠伊塔努會有興趣？>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56445] = {title = "擺尾王子的戳戳叉子", objective = "到納沙塔爾的新鄉，將擺尾王子的戳戳叉子拿給『尋寶者』寶兒塔看。\n\n已提供物品：\n", description = "<落敗王子的堅韌魚叉。\n\n它似乎半點力量都沒有。事實上，它看起來相當平凡，還有點生鏽。\n\n你還是把它裝進口袋裡。說不定『尋寶者』寶兒塔會有興趣？>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56446] = {title = "皮囊毒腺", objective = "到納沙塔爾的梅札米爾，將皮囊毒腺拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<你從嚙龍屍體上撬下皮革般的腺體。幾滴毒液從一端的開口灑出，滴到地面就發出嘶嘶聲，留下一個個小洞。\n\n這種劇毒似乎很厲害，最好把它帶回梅札米爾。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56447] = {title = "消化一半的深海珊瑚孢囊", objective = "到納沙塔爾的梅札米爾，將消化一半的深海珊瑚孢囊拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<檢查這隻攻擊性意外高的深海魟魚時，你發現了幾個消化到一半的孢囊。\n\n你在這個地區的珊瑚身上看過類似的孢囊，似乎是深海魟魚的食物之一。\n\n這或許可以解釋它們奇怪的飛行能力。\n\n工匠伊塔努可能會更清楚。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56448] = {title = "刺棘蟹蛻殼", objective = "到納沙塔爾的梅札米爾，將刺棘蟹蛻殼拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<被擊敗的刺棘蟹的蛻殼，這是在納沙塔爾首度發現的一種兇蟹。\n\n殼上的棘刺相當銳利。\n\n這可能對工匠伊塔努有用。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56449] = {title = "珠光外殼", objective = "到納沙塔爾的梅札米爾，將珠光外殼拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<落敗寄居蟹的超大硬化外殼。\n\n外殼本身比寄居蟹大上許多，而且從不同角度觀看，呈現的色澤也不同。\n\n梅札米爾一定有人會對這個漂亮的外殼感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56450] = {title = "鰻魚黏膠", objective = "到納沙塔爾的梅札米爾，將鰻魚黏膠拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<你檢查深海鰻魚的屍體，只發現牠全身佈滿奇怪的黏液。\n\n黏液沾滿你的手掌和手臂，而且似乎很難清除。\n\n你的一個深海盟友可能對此有更多瞭解。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56451] = {title = "斑駁的多頭蛇鱗片", objective = "到納沙塔爾的梅札米爾，將斑駁的多頭蛇鱗片拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<最近擊敗的多頭蛇幼獸的鱗片，似乎是由數個顏色混合而成。\n\n這個地區的多頭蛇似乎為了爭奪地盤而戰，你的新盟友可能會更清楚。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56452] = {title = "怪異的器官", objective = "到納沙塔爾的梅札米爾，將怪異的器官拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<你在屈心魔的屍體中發現一個怪異的器官，一拿起它，你的頭就開始抽痛。\n\n這種章魚般的生物一直以來都是艾澤拉斯的謎，透過這個器官，或許可以多瞭解牠們一點。\n\n梅札米爾的某人可能會更清楚。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56453] = {title = "蔓生石", objective = "到納沙塔爾的梅札米爾，將蔓生石拿給工匠伊塔努看。\n\n已提供物品：\n", description = "<從你最近擊敗的土元素身上取出的石頭，上面覆蓋著海藻及其他各種海中植物。\n\n你很少在深海中看過這種生物，也許它們身上有什麼故事。\n\n你的新海底盟友可能會更清楚。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
