MultiLanguageQuestData['tw'][56469] = {title = "海盜？我恨死這些傢伙了！", objective = "將老舊的海盜帽交給里諾‧傑克森。\n\n已提供物品：\n", description = "<一頂老舊的海盜帽，似乎不屬於這座島，也許里諾‧傑克森會知道該怎麼處理。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][56470] = {title = "給狗狗骨頭", objective = "從巨大嗜髓蟲身上收集12個嗜髓蟲肉。", description = "路易森把狗骨頭借給我要幫我找出一些嗜髓蟲，但是我忙著盯著這些爐子。你可以當個好人幫我獵一些回來嗎？\n\n狗骨頭最愛撲向小型的啃咬者，但他會發出吵雜的聲音。而大型的嗜髓蟲會被這些聲音嚇跑，這就是你該出手的時候了。\n\n用這個骨頭把狗骨頭引誘到啃咬者附近就對了。噢對了，別忘了從嗜髓蟲身上收集一些血肉，那才是你真正的目標。", progress = "你收集到肉了嗎？", completion = "好極了！這一定能做成超好吃的東西！", rewards = "您會收到：\n\n\n\n任意等級托馬林的調味水晶優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][56471] = {title = "血本無歸", objective = "毀掉紅色擊打者、橘色擊打者和灰色擊打者", description = "這塊土地已經蒙受了如此巨大的災難，卻還有可能變得更糟！\n\n風險投資公司來了，他們會用盡一切本事剝削每一份利益，直到什麼都不剩！我們一定要讓他們在此地的投資毫無利潤，他們才會捲鋪蓋離開。\n\n毀掉他們帶來的三座昂貴的保全單位，他們就有可能去找其他更有賺頭的投資。", progress = nil, completion = "這肯定會重創他們的收益。現在看他們會不會離開！", rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 56–80耗盡的儲能裝置\n\n等級 50–80儲能裝置"}
MultiLanguageQuestData['tw'][56472] = {title = "奧丹姆協議", objective = "到蘭姆卡韓瞭解奧丹姆面臨的威脅。", description = "你想要找人一起保護起源熔爐？看來我們的目標是一致的。\n\n以熔爐的真正規模來看，起源大廳不過是其中一小塊。對奧丹姆的任何威脅，都有可能危及熔爐，而且最近出現了許多對奧丹姆不懷好意的敵人。\n\n當這些廢土漫遊者突然不請自來時，我們正打算召集高階議會開會。不如你也一起出席，瞭解這些威脅？", progress = "在我們繼續之前，我們應該盡力瞭解奧丹姆面臨的威脅。", completion = "我們與廢土漫遊者合作，而探險者協會將協助我們守住奧丹姆。\n\n儘管集結了這麼多力量，沒有你的幫助，我們可能還是無法擋住這些敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56473] = {title = "淬毒蜘蛛牙", objective = "帶著淬毒蜘蛛牙去找蜜背女王蜂以取得獎勵。\n\n已提供物品：\n", description = "就算是最謹慎的蜂，都有可能成為這些巨大蜘蛛的獵物。牠們躲在花床附近，並在蜜蜂採收時展開伏擊。多虧了你，蜜蜂少一隻蜘蛛需要擔心了。\n\n女王蜂一定會對這東西感興趣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n普通的蜘蛛牙"}
MultiLanguageQuestData['tw'][56474] = {title = "蜂巢殺手毒刺", objective = "把蜂巢殺手毒刺帶去交給蜜背女王蜂就可以獲得獎勵。\n\n已提供物品：\n", description = "黃蜂是蜜鋒的天敵，而且沒有任何黃蜂比這隻專門獵殺蜜蜂的殺手更致命。多虧了你，牠再也無法讓巢穴陷入恐慌了。\n\n女王蜂一定會對這東西感興趣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n發光的刺"}
MultiLanguageQuestData['tw'][56475] = {title = "螺旋雪人角", objective = "帶著螺旋雪人角去找蜜背女王蜂以取得獎勵。\n\n已提供物品：\n", description = "新鮮蜂蜜的香甜氣味會吸引各式各樣的生物，但很少有動物願意忍受大型蜜蜂疼痛甚至致命的叮咬。不過，這個雪人，一直都是巢穴的背後芒刺，直到現在為止。\n\n女王蜂一定會對這東西感興趣。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n穿孔的螺旋角"}
MultiLanguageQuestData['tw'][56489] = {title = "無法安息的死者", objective = "到東瘟疫之地的斯坦索姆外頭的僕從入口找尚恩‧威克斯。", description = "有傳聞說斯坦索姆到處都在發生著新的邪惡事件。我們需要你去東瘟疫之地一趟，把徘徊在那裡的所有新邪惡勢力給剷除掉。\n\n我們有跟銀白十字軍的一位成員聯繫上，他答應會幫助你進入斯坦索姆，並且找到這股新的邪惡勢力的根源。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56490] = {title = "無法安息的死者", objective = "到東瘟疫之地的斯坦索姆外頭的僕從入口找尚恩‧威克斯。", description = "有傳聞說斯坦索姆到處都在發生著新的邪惡事件。我們需要你去東瘟疫之地一趟，把徘徊在那裡的所有新邪惡勢力給剷除掉。\n\n我們有跟銀白十字軍的一位成員聯繫上，他答應會幫助你進入斯坦索姆，並且找到這股新的邪惡勢力的根源。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56491] = {title = "斯坦索姆微不足道的恐懼", objective = "擊敗黑鬃。", description = "這幾天天譴軍團在斯坦索姆內出現的頻率大幅地增加。空氣中滿是死靈法術的惡臭，城牆裡面也時不時會傳出尖叫聲，足以讓你連續好幾個禮拜都感到背脊發涼。\n\n我還沒自己冒險進去過，但裡頭一定有著新的邪惡力量在作祟。我有進入這個入口的鑰匙，可以帶你進去讓你親眼瞧瞧。\n\n準備好的時候告訴我一聲。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n魔噗連線：斯坦索姆\n\n您還會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][56492] = {title = "寵物對戰挑戰：斯坦索姆", objective = "擊敗黑鬃。", description = "邪惡勢力再次回來侵襲斯坦索姆了。死靈法術和天譴軍團的毛病就在這裡，他們總是能夠復活然後又再跑回來！\n\n我可以再把我們弄進去一次，但我怕那些邪惡勢力都已經回來了。你確定還要再回去那裡？那個地方讓我感到毛骨悚然。如果你真的想要再回去的話，我會放你進去的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n淨化的顱骨"}
MultiLanguageQuestData['tw'][56493] = {title = "直接手段", objective = "消滅12位風險投資公司雇員。", description = "瑪奧卡真是好心腸，他很擅長照顧小傢伙，總是陪他們玩遊戲和講故事。\n\n不過，我們實在不喜歡那些風險投資公司的人，所以我建議採取更直接的手段。\n\n試試看殺光他們。", progress = nil, completion = "你傳達了他們永遠都不會忘記的訊息。", rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][56494] = {title = "戰鬥前夕", objective = "與馬迪亞斯‧肖爾交談。", description = "<name>，時候到了。\n\n我們擊敗了艾薩拉，不過還有希瓦娜斯要對付。雖然目前情況並不理想，不過我們已經動員了所有可用部隊，準備結束這場戰爭。\n\n烏瑞恩國王要我在會合之前，先向你做個當前局勢的簡報。有些十分…有趣的發展。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56495] = {title = "違逆我們的行動", objective = "在奧格瑪與希瓦娜斯會面。", description = "<name>，黑暗女王要你前去奧格瑪。\n\n看來老鼠終於從洞裡爬出來了，這樣子我們比較容易一舉消滅他們。\n\n別拖拖拉拉的，我們等這刻等很久了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56496] = {title = "戰鬥前夕", objective = "與洛索瑪談話。", description = "<name>，我們得談談部落…還有大酋長的事。\n\n這場戰爭耗損甚鉅，再加上對抗艾薩拉的戰鬥，消耗掉我們僅存的資源。部落再次分裂，而聯盟的情況也好不到哪裡去。\n\n現在希瓦娜斯的地位，足以摧毀她視為敵人的所有對象。那當然就是指我們。\n\n我一直希望我的老朋友願意講道理，但是現在…\n\n薩魯法爾霸王正在集結我們僅存的人手，包括一些難以置信的盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56499] = {title = "席捲戰場", objective = "贏得一場PvP海嶼遠征、普通戰場和史詩戰場。", description = "我們不能讓任何一條戰線鬆懈下來，繼續向前推進。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n翻騰的敗亡之血抑制力量之球艾澤萊晶殼時光石英"}
