MultiLanguageQuestData['tw'][56534] = {title = "世界之脈的傳聞", objective = "收集3個世界之脈情報。", description = "收集更多情報，協助你的追隨者查明波動的世界之脈位置。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n調查傳聞"}
MultiLanguageQuestData['tw'][56536] = {title = "處境堪慮", objective = "到崑萊峰的魔古山寶庫外與麥格尼‧銅鬚會面。", description = "就我所知，魔古山寶庫還是處於廢棄狀態。\n\n如果我們想要抵達引擎所在的地方，應該不會太難，畢竟那裡的魔古守護者早就敗在我們手中了。\n\n好啦，你還在等什麼？我們去啟動那具引擎吧！", progress = "處境堪慮，對吧？", completion = "那道琥珀屏障看來幾乎牢不可破。\n\n我們好像陷入僵局了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56537] = {title = "神祕符印", objective = "將神祕魔古符印交給恆春谷知識之座的博學行者阿洲。", description = "<死亡的魔古手中抓著一個符印，代表他所屬的神秘氏族。\n\n如果深入調查他的氏族，或許可以進一步瞭解螳螂人為何大肆入侵魔古山寶庫，以及如何戰勝他們。\n\n博學行者阿洲是最瞭解潘達利亞的人。他或許有辦法追查這枚魔古符印的出處。>", progress = nil, completion = "這麼說，魔古山寶庫被螳螂人佔領了？確實讓人有點措手不及，不過並非出乎意料。\n\n但是請魔古幫忙奪回那裡，那就真的是天外飛來一筆了。就我所知，他們連話都說不好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56538] = {title = "魔古氏族", objective = "在知識之座協助博學行者阿洲找出神祕魔古符印的起源。", description = "你說有個魔古向你求助？這還真不尋常。\n\n我很樂意協助你查明這枚符印的出處。老實說，光是有可能找到一支不完全敵視我們的魔古氏族，就讓我很有興趣了。想想那可以找到多少可能性！\n\n我們開始辦正事吧。我們得參考恆春谷中記載魔古氏族的書冊來縮小範圍。", progress = nil, completion = "如果魔古再一次追尋萊公的腳步，或許就能結束征戰不休的日子。\n\n這實在太讓人興奮了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56539] = {title = "尋找萊加尼", objective = "從恆春谷的魔古身上收集魔古偵察報告。", description = "現在我們對這支氏族有了初步概念，下一個問題是，我們該去哪裡找他們？\n\n魔古之間會持續內鬥，所以每個氏族都會保留一些紀錄，記載他們的競爭對手在哪裡。如果我們能找到這樣的資訊，就可能帶我們找到萊加尼。\n\n去找魔古的勇士。他們身上最可能帶著指出敵人所在位置的報告。", progress = "你找到偵察報告了嗎？", completion = "太好了。這不只能幫我們找到萊加尼，還對金蓮會的防禦工作大有助益。\n\n這真的是很有價值的情報！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56540] = {title = "不屈不撓的明證", objective = "從入侵恆春谷的指揮官手中取得一件征服者的戰利品。", description = "既然至高守衛者如此堅信我們毫無戰勝敵人的可能，或許來場實力展演能改變他的想法。\n\n我不是很確定你應該怎麼做，但如果你能戰勝入侵恆春谷的威脅，取得勝利，說不訂就能說服他，應該要開始採取行動了。", progress = "這次又是什麼？", completion = "你成功擊敗了恩若司的將領？的確是值得讚許的功績，但艾澤拉斯的敵人依然數之不盡。\n\n燃燒軍團、上古之神、虛無…它們的魔掌遲早會觸碰到這個世界。\n\n…但我的看法也…不見得每次都正確。", rewards = "陰惡巨怪肩鎧陰惡巨怪頭盔陰惡巨怪鍊衫惡毒折磨者肩冑惡毒折磨者頭罩惡毒折磨者護軀貪婪之口披肩貪婪之口面具貪婪之口外衣邪惡操縱者襯肩邪惡操縱者兜帽邪惡操縱者法衣您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56541] = {title = "納拉卡煞引擎", objective = "沿著魔古山宮的密道前進，重新啟動納拉卡煞引擎。", description = "你們證明了我過去的看法有誤，希望這次也能對你們刮目相看。\n\n放置納拉卡煞引擎的泰坦建築物延伸到潘達利亞的每個角落。除了魔古山寶庫之外，還有其他地方可以去。\n\n這樣的通道很多，但最近的道路是穿過魔古山宮。在這座皇宮下面的房間，和泰坦遺址的內部相連。\n\n到那裡尋找你的命運吧，勇士。", progress = nil, completion = "勇士，你為萊加尼做了很偉大的事。\n\n希望納拉卡煞引擎能提供你所追尋的力量。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56542] = {title = "重拾希望", objective = "和萊公交談後返回心之室。", description = "你的堅忍不拔，讓我對這個世界充滿希望。\n\n我們一起回你的「心之室」吧。身為起源熔爐的管理員，相信我可以助你一臂之力，讓它恢復正常。\n\n準備好就告訴我一聲，我帶大家一起過去。", progress = nil, completion = "我們不只成功恢復起源熔爐的動力，居然還把最初安裝它的泰坦守衛者帶了回來！\n\n不過信不信由你，好消息不只這個！", rewards = "您能選擇下列奬勵中的一個：\n\n不死之葉聚能星尖刺\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56550] = {title = "清理屍體", objective = "燒掉8具有蟲卵的屍體。", description = "這些可怕的昆蟲傾巢而出攻擊我們的營地，弟兄們一個接一個倒下。\n\n這種差事我不好意思麻煩別人，但我們真的很需要盡快把屍體處理掉。\n\n我們不能讓死者成為孕育他們那噁心蟲卵的溫床。", progress = nil, completion = "希望這樣可以遏止他們的數量繼續成長。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][56552] = {title = "不列入記錄的鬥毆", objective = "在機械岡和古魯波‧恐怖戰錘的手下鬥毆。", description = "加茲魯維也雇了你來當保鑣？他還真的只雇用最厲害的人，是吧？哈！\n\n出手大方，但規矩和大便一樣：在城內不准打鬥，絕無例外。呸！\n\n<烏薩從她的杯子裡狂飲了一口。>\n\n除非能讓那個小不點看管者王子認定我們是美妙的小天使，否則他不願把手中的科技交給我們…哈！\n\n不過加茲魯維可沒有說，不能在城鎮外面打鬥的話。\n\n我叫我的小隊在外圍待命，只要古魯波那群清道夫那滿是鬍子的臉出現，就上前大鬧一番。\n\n你要加入嗎？", progress = nil, completion = "哈哈哈！看看古魯波的蠢臉！\n\n他一臉不敢置信的樣子！哈哈哈！笑死人！", rewards = "您會收到：\n\n\n\n等級 60–80儲能裝置耗盡的儲能裝置\n\n等級 11–80備用零件"}
MultiLanguageQuestData['tw'][56557] = {title = "非正規行動", objective = "在機械岡殺死5位聯盟玩家。", description = "只有兩件事比戰鬥更有趣，第一件事就是講垃圾話！\n\n<烏薩對著古魯波‧恐怖戰錘叫罵著不雅字句。>\n\n自從奧特蘭克之後，那個滿臉鬍鬚的矮子一直是我的肉中刺…好像永遠都甩不掉他。\n\n我們打了個賭，看看誰才是島上最棒的鬥士。\n\n你想不想幫我贏得這場賭注？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n備用零件"}
MultiLanguageQuestData['tw'][56558] = {title = "不列入記錄的鬥毆", objective = "在機械岡與烏薩‧鑿眼的部下鬥毆。", description = "*噗嚕嚕嚕*好了，聽好。我們目前的處境有點尷尬。\n\n除了這堆爛酒喝起來像機油以外，那個豬頭烏薩一直在唱衰我們的部隊。\n\n衰的會是她，因為現在*嗚嚕嚕嚕*要你去出去外面，看到幾頭部落豬就教訓幾頭。\n\n大致上來說，我們不該在外面鬥毆，所以這也算不上是什麼正式命令…您會收到：\n\n\n\n任意等級", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n任意等級備用零件\n\n等級 60–80耗盡的儲能裝置\n\n等級 60–70儲能裝置"}
MultiLanguageQuestData['tw'][56559] = {title = "非正規行動", objective = "在機械岡殺死5位部落玩家。", description = "唉，<name>，我打算和烏薩打個小賭，你的本事會派得上用場。\n\n我跟她打賭，你能在她養的狗打倒我們這邊五人之前，搶先在島上打倒她的五位朋友。\n\n你應該沒問題吧，$u小夥子:小姑娘;？當然沒問題啦，啊哈哈哈哈！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56560] = {title = "可疑的發現", objective = "將附魔水晶拿給新鄉的納夫。\n\n已提供物品：\n", description = "<這顆水晶發出一種令人著迷的亮光，你難以把目光從它身上移開。\n\n也許破縛者可以告訴你更多有關它的情報。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜彩水晶"}
MultiLanguageQuestData['tw'][56561] = {title = "可疑的發現", objective = "把附魔水晶帶去給梅札米爾的講師歐卡努。\n\n已提供物品：\n", description = "<這顆水晶發出一種令人著迷的亮光，你難以把目光從它身上移開。\n\n也許安寇恩可以告訴你更多有關它的情報。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜彩水晶"}
MultiLanguageQuestData['tw'][56563] = {title = "縮水問題", objective = "問問羅姆有關乾枯的皮革的事。\n\n已提供物品：\n", description = "<在剝了無數生物的皮之後，你發現在皮革被曬乾的情況下會損失許多能用的部分。破縛者似乎對如何運用這種材料有相當程度的瞭解，或許羅姆可以跟你分享一些他的知識。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：掘泥皮革(等級3)"}
MultiLanguageQuestData['tw'][56566] = {title = "千鈞一鱗", objective = "向羅姆詢問剝落的崖鱗的問題。\n\n已提供物品：\n", description = "<在你把皮從動物屍體上剝下來時，你注意到許多鱗片從皮膚上剝落，扯出了一些小洞，讓部分的獸皮變得無法使用。破縛者似乎對使用這種材料很有一套，或許羅姆能跟你分享他的心得。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n剝皮技術：崖鱗(等級3)"}
MultiLanguageQuestData['tw'][56570] = {title = "訂單：強效洪流精煉藥劑", objective = "你是來送補給品的嗎？", description = nil, progress = "你是來送補給品的嗎？", completion = "謝謝你協助我們，朋友。我們急需這些藥劑。", rewards = "您會收到：\n\n配方：強效洪流精煉藥劑艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56572] = {title = "玩具你我他", objective = "在機械岡掃描生物", description = "我一定要用老少咸宜的方式，和全艾澤拉斯一塊兒分享這個地方的奇觀。我會使用這裡的科技來製造一系列前所未見的新玩具！\n\n我的外觀刻面掃描器，可以幫我製造島上任何東西的完美複製品。\n\n我只需要一位樂意協助的人，比如說像你這樣的人，在這個區域掃瞄幾件事物。", progress = nil, completion = "第一批玩具已經準備好登場了！", rewards = "您會收到：\n\n\n\n任意等級備用零件艾澤拉斯迷你玩偶：入門包\n\n等級 60–80儲能裝置\n\n等級 20–80耗盡的儲能裝置"}
MultiLanguageQuestData['tw'][56573] = {title = "認證二手貨", objective = "收集15根回收的機械地精附肢。", description = "首先我想告訴你，你永遠都會是我們最喜愛的實驗對象。\n\n但我們的實驗需要遠超過單一實驗對象所能提供的犧牲。而且有時候，部份的實驗對象需要全新的肢體。\n\n我敬愛的手足和我想出了一個概念的雛型，得以延長機械附肢的平均生命周期。但我們手邊可以用來實驗的元件都用光了。\n\n從城鎮外面的垃圾場回收一些附肢，我們才能繼續實驗。", progress = "不用擔心任何故障或是少了什麼零件，不管你找到什麼東西，吉兒都會幫我們修好。", completion = "太讚了！這應該夠我們用上…\n\n&lt;普莉絲蒂數著附肢的數量，然後草草寫在筆記本內。&gt;\n\n…至少3個小時。哇，我們真的翻遍了這些附肢！", rewards = "您會收到：\n\n儲能裝置"}
MultiLanguageQuestData['tw'][56574] = {title = "琥珀中的倒影", objective = "把被污泥覆蓋的琥珀帶給蟠龍脊的影潘。", description = "<一滴黏稠的黑暗污泥從這一大塊琥珀上滴了下來。你想把它擦乾淨，卻徒勞無功，因為污泥似乎是由琥珀所構成的。\n\n在你握緊它的時候，一道無法辨明的低語聲在你的意識深處響起。\n\n影潘一定會很想要好好調查這個東西。>", progress = nil, completion = "&lt;name&gt;，你手裡拿著什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56575] = {title = "重回柯爾斐斯", objective = "調查柯爾斐斯。", description = "你是在蟲群身上找到這東西的？它滲出著腐化…滲出著力量。如果其他螳螂人琥珀也受到這種腐化的影響，我們可能會面臨可怕的威脅。\n\n柯爾斐斯在悚然荒野西邊遙遠的地方，它是一棵巨大的奇帕利樹，可以為蟲群生產大多數的琥珀。從那個地方，我們可以判斷他們所存放的琥珀，有多少已經灌注了上古之神的能量。\n\n我會在樹木附近和你會合。", progress = nil, completion = "看來螳螂人正在腐化整棵樹。這比我想像的更糟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56576] = {title = "撲殺亞基", objective = "殺死10頭亞基穿刺者。", description = "他們的數量太多，在我們身邊飛來飛去，想起飛都有問題。\n\n就這樣啟動飛機引擎的話，不用幾秒就會驚動他們，害我們整個被淹沒！\n\n所以，這些蟲子一定得入土為安…而且越快越好。知道我在說什麼吧？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56577] = {title = "癱瘓巢穴", objective = "在柯爾斐斯殺死12個闊席克螳螂人。", description = "此地的螳螂人幾乎瘋狂，忙著從樹上採收琥珀。\n\n或許殺個一群可以降低他們的工作效率。", progress = nil, completion = "雖然這只能治標不治本，但應該可以為我們爭取到一點時間。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56578] = {title = "朽到根裡", objective = "在珀光密殿阻止腐化源頭。", description = "螳螂人在奇帕利柯爾下方建造了一個巨大房間，用來照顧這棵樹木。那裡一定就是腐化的根源。\n\n我們得進入那個房間，阻止他們。絕對不能讓恩若司強化蟲群。", progress = nil, completion = "無面者？對螳螂人來說，奇帕利樹是神聖的化身…但看來他們對古神更加忠誠。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56580] = {title = "琥珀的秘密", objective = "收集8塊腐化的琥珀。", description = "有一小群札拉席克盤踞在珀光密殿，那是直接隸屬於新女皇的螳螂人。或許可以在他們身上找到你之前發現的那種琥珀。\n\n影潘一定很想要研究更多琥珀。", progress = "我們一直都害怕這一天會到來…", completion = "又有腐化的琥珀了。我得把這些帶回要塞。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56616] = {title = "老面孔，新問題", objective = "殺死看守者維薩斯", description = "看來恩若司的爪牙注意到我們的存在了。\n\n我們是不是該去拜訪一下？", progress = nil, completion = "又一位恩若司的密探。看來螳螂人深得他的青睞。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56617] = {title = "團結的蟲群", objective = "潛入卡拉西斐斯。", description = "看來螳螂人早在我們前來…干預之前，就已經開始製作這種腐化的琥珀。他們應該是把大量的琥珀都存放在某處了。\n\n影潘斥候屢次回報，說是在卡拉西斐斯那裡現身的蟲群戰士越來越多了。我敢打賭，他們一定是在看守腐化的琥珀。\n\n在那裡和我碰面。如果有機會摧毀那批琥珀，我們就絕對不能錯過。", progress = nil, completion = "如果任由腐化琥珀強化整個蟲群，恩若司就會擁有一支沒人擋得住的大軍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56621] = {title = "真正究極之力", objective = "到科技活化的泥潭收集15個被遺棄的科技零件。", description = "當我說電力就是生命的時候，我不只是在比喻而已，我親愛的實驗對象。\n\n只要利用得當，電力本身可以創造出生命，至少能創造出夠像的複製品，讓我們的目的可以達成。\n\n排水區的泥潭深處中藏有大量棄置的科技零件，這次也不例外，機械岡的垃圾就是我們的寶藏。\n\n我的裝置終於改良完成了，它能使污泥動起來，讓那項科技零件浮出表面到你眼前。\n\n你只要用這個把科技零件拿來就好了！", progress = "請詳細記錄你在使用發動機-7143時遇到的任何不良副作用。", completion = "成果真豐富！\n\n而且你說，發動機-7143「沒有」讓你的腸子有火燒的灼熱感？\n\n&lt;弗力普著做了簡短的筆記。&gt;\n\n真是太美妙了！", rewards = "您會收到：\n\n儲能裝置"}
MultiLanguageQuestData['tw'][56623] = {title = "艾斯蘭制霸", objective = "在艾斯蘭的所有活動地點擊敗部落軍隊，並殺死高階督軍沃拉斯。", description = "如同我們擔心的，部落正在想辦法擄掠這這座島來鞏固他們的防線。去讓他們瞧瞧，聯盟不會容忍這樣的侵略行為。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][56640] = {title = "幸運的靈魂", objective = "到艾薩拉之矛解救7名被俘的士兵。", description = "你和我躲過了這次攻擊，也暫時躲過了敵人的追捕。\n\n並不是所有的人都這麼幸運。\n\n我們的許多盟友現在都在納迦的手上，我們必須把他們救出來，不然他們就會死去，或是遭受到更糟糕的對待。", progress = nil, completion = "我們的軍隊受到了重創，但我們終會重建軍力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56641] = {title = "力量干擾", objective = "到艾薩拉之矛摧毀5個地脈蓄電池。", description = "納迦正在挖掘一種潛在的力量，他們在將能量注入某種裝置之中。\n\n我不知道他們為何要取得這種力量，不過，在他們拿這些東西來對付我們之前，先把它們摧毀，肯定對我們有利。", progress = nil, completion = "有時候，破壞別人的玩具是件很痛快的事情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56642] = {title = "洶湧暗潮", objective = "殺死海潮祭司艾森卓絲。", description = "海潮祭司在水池上方主導著某種邪惡的儀式。\n\n我們靠近的時候，不要往水池裡看，否則你會看到我們的盟友溺水的景象。\n\n我們必須阻止這個儀式，而海潮祭司就是關鍵。", progress = nil, completion = "我們一殺死海潮祭司，儀式就停止了。", rewards = "第七軍團士兵長弓第七軍團士兵匕首第七軍團士兵長戟第七軍團士兵護杖第七軍團士兵長劍第七軍團士兵巨刃劍第七軍團士兵香爐第七軍團士兵法術錘第七軍團士兵盾牌第七軍團士兵的劈顱者第七軍團士兵巨錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][56643] = {title = "進退兩難", objective = "在艾薩拉之矛的洞穴中和珍娜與吉恩會面。", description = "葛雷邁恩國王和普勞德摩爾女士應該已經在我們約好要碰面的洞穴了。\n\n我們別讓他們等太久。", progress = nil, completion = "我已經受夠這個地方了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56644] = {title = "身陷險境", objective = "和珍娜與吉恩一起往納沙塔爾深處移動。", description = "如果我們要確保大家的安全，我們必須快點行動。\n\n這個洞穴難以防衛，而我們軍隊大部分人的處境更加危險。\n\n我們來進一步搜索吧。", progress = nil, completion = "我們一直在觀察你，你的人似乎很有能力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56645] = {title = "蟲群之心", objective = "和陶氏一塊搭上影潘風箏。", description = "我們得搞清楚自己正面臨著什麼樣的處境。在回到蟠龍脊之前，我們應該利用這個機會來探查一下蟲群。\n\n我會帶著大夥兒飛越恐懼之心。我們應該可以從上空勘察杉札拉女皇的部隊。藉此來判斷恩若司的勢力延伸得有多廣。", progress = nil, completion = "真是千鈞一髮。&lt;name&gt;，謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56647] = {title = "螳螂人的威脅", objective = "回到靜默聖地去找颶語者齊恩。", description = "螳螂人一直在腐化他們的奇帕利樹，並將恩若司的力量灌注到琥珀之中。光是蟲群本身就已經極具威脅性了。恩若司可能還可以進一步把它們轉化成更加恐怖的事物。\n\n得把這件事告訴影潘才行。我建議你把這個情報也告訴其他盟友。", progress = nil, completion = "螳螂人甘願讓自己的奇帕利樹被腐化，從這件事就可以看出他們對恩若司的忠誠。\n\n謝謝你知會我們。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56648] = {title = "戰鬥的號角：納沙塔爾", objective = "殺掉納沙塔爾的部落。", description = "我們在納沙塔爾的任務正受到部落入侵的影響。\n\n進入納沙塔爾，能殺多少就殺多少吧。", progress = nil, completion = "做得好，&lt;class&gt;。", rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][56649] = {title = "戰鬥的號角：機械岡", objective = "殺掉機械岡內的部落。", description = "我們在機械岡的任務正受到部落入侵的影響。\n\n進入機械岡，能殺多少就殺多少吧。", progress = nil, completion = "做得好，&lt;class&gt;。", rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][56650] = {title = "戰鬥的號角：機械岡", objective = "殺掉機械岡內的聯盟。", description = "我們在機械岡的計畫，受到湧入的聯盟敗類破壞。\n\n盡全力解決他們，然後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][56714] = {title = "內藏的烈酒元素", objective = "在啤酒節活動區和釀酒大師老陶交談。", description = "<在釀造酒回到原本的平靜形態時，出現了一個奇怪的酒桶。\n\n或許釀酒大師老陶更瞭解這種奇怪現象。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章龍石"}
MultiLanguageQuestData['tw'][56715] = {title = "猴人圖騰", objective = "在啤酒節活動區和澤恩妲談談。", description = "<將猴人成功趕跑後，啤酒節重現生機。\n\n不過問題就自動浮現：猴人是怎麼到杜洛塔來的？或許啤酒節活動區有人跟他們打過交道。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章龍石"}
MultiLanguageQuestData['tw'][56716] = {title = "恐酒齒輪", objective = "在啤酒節活動區和布力克斯‧修械交談。", description = "<恐酒的黑鐵同夥逃走了，只留下一小塊鑽地機零件。\n\n你知道，他們以前也襲擊過啤酒節活動。或許有哥布林會願意聽聽你的勝利事蹟。>", progress = nil, completion = "所以恐酒還是不放棄，是吧？\n\n嗯，謝謝你又把他的手下處理掉了。多虧有你，我才能繼續做生意！作為獎勵，把這些獎章拿去吧…不過，記得以後要回來使用它們！", rewards = "您會收到：\n\n啤酒節獎品章龍石"}
MultiLanguageQuestData['tw'][56719] = {title = "這不是地雷", objective = "清除剃刀嶺和奧格瑪關口之間的巨石、地雷和其他障礙。", description = "你來得正是時候，<name>，通往奧格瑪的某段峽谷通道崩塌，看來是希瓦娜斯忠誠者下的手。\n\n我們和先鋒部隊之間的連繫中斷，如果我們沒辦法馬上支援他們，恐怕只能眼睜睜看著他們全滅。我們的部隊人數不足，不能任他們在另一邊長期受困。\n\n技工大師歐沃斯巴克和加茲魯維想出一個解決方案。動作快，盡你所能去協助他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56739] = {title = "崇拜的力量", objective = "摧毀3個秘法能量轉化器。", description = "我過去也和他們一樣，陷入一種迴圈之中，等待艾薩拉來救我。我們的靈魂被困在這個地方。\n\n這些廢墟的其他地方也有納迦，他們有一種神奇的寶珠…我認為，他們在利用我們，把我們當成他們秘法實驗的燃料。他們從我們的靈魂和對艾薩拉的崇拜中吸收能量。這也讓我們變得非常虛弱，無法擺脫束縛。\n\n摧毀那些寶珠，一旦連結被破壞，我們就能獲得力量，離開這裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56740] = {title = "備用零件箱", objective = "和帕斯卡K1N6型一塊製作$1oa件廢料場工程物品。", description = "我敢說，你一定也同意帕斯卡K1N6型是你看過最偉大的發明！\n\n如果你還沒能完全信服，試著讓它發揮極限。我不介意！\n\n給他更多的資源和藍圖，他會為你製作任何需要的東西！", progress = nil, completion = "看看你包包裡有多少備用零件！你開始有個正港垃圾場技工的樣子了。\n\n不過，我要給你一個小提醒，只有業餘的傢伙才會把東西這樣亂糟糟的堆在一起。\n\n真正的專家會打理得好好的，這樣我們才能裝更多東西。\n\n來，我示範給你看。", rewards = "您會學到：\n\n上傳：零件藍圖\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][56741] = {title = "命運之槍", objective = "回梅札米爾找珍娜‧普勞德摩爾。", description = "在大崩裂之前，標槍是蘇拉瑪爾最強大的魔法產物。這正是我們需要的東西，有了這個，我們就能攻破守衛者和潮石的結界。\n\n我們必須盡快返梅札米爾，普勞德摩爾女士需要知道我們成功的消息。\n\n這會改變我們在納沙塔爾這裡的整個戰況，<name>。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56746] = {title = "我們的專線", objective = "和帕斯卡K1N6型一塊製作$1oa件廢料場工程物品。\n\n已提供物品：\n", description = "我敢說，你一定也同意帕斯卡K1N6型是你看過最偉大的發明！\n\n如果你還沒能完全信服，試著讓它發揮極限。我不介意！\n\n給他更多的資源和藍圖，他會為你製作任何需要的東西！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n藍圖：加密黑市無線電"}
MultiLanguageQuestData['tw'][56748] = {title = "啤酒節大胃王比賽", objective = "參加啤酒節大胃王比賽。", description = "哈囉，<class>！希望你來之前沒有吃什麼東西！\n\n以前在德拉諾，我們在過節的時候常常舉辦大胃王比賽，作為一種慶祝的方式。後來換我們主辦啤酒節時，我們就覺得，最適合加進活動的就是這個了！\n\n坐一下，讓我們看看你有多能吃吧。如果你在開始前想知道更多細節，儘管問就對了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章龍石"}
