MultiLanguageQuestData['tw'][56775] = {title = "暖身", objective = "與作戰假人戰鬥來進行暖身。", description = "準備好，<name>。我們正在接近前一支遠征隊失蹤的島嶼。\n\n用這些戰鬥假人暖個身。我們需要每個人都準備萬全，才能在島上應付未知。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56777] = {title = "來自氏族的禮物", objective = "和使者尤提亞會面。", description = "<name>，使者尤提亞請我通知你，希望你有機會時可以回梅札米爾一趟。\n\n你在對抗納迦的戰鬥中表現出十足的勇氣和膽識，為了表示我們的感激，我們的氏族準備了一份禮物要給你。\n\n我們的補給品禮物一定能有效加強你的武裝，成為你繼續對抗艾薩拉的最佳助力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納沙塔爾生存包"}
MultiLanguageQuestData['tw'][56778] = {title = "黑暗中的閃光", objective = "掠奪亮鱗保險箱", description = "納沙塔爾各地隱藏著許多寶藏。\n\n最近，我在離這不遠的洞穴裡發現一個閃閃發光的東西。那好像是某種保險箱。\n\n我建議我們回去調查一下。裡面的物品或許很有價值，我們跟納迦戰鬥時能派上用場。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n微微發光的補給品"}
MultiLanguageQuestData['tw'][56779] = {title = "英勇的獎賞", objective = "和使者尤提亞會面。", description = "<class>，你在戰場上的表現為你的聯盟帶來了榮耀。\n\n使者尤提亞已經發出消息，要請你回梅札米爾接受我們氏族的獎勵。\n\n希望你一有空就返回梅札米爾。\n\n能與你並肩作戰是我的榮幸。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n安寇恩表揚箱"}
MultiLanguageQuestData['tw'][56780] = {title = "隱匿但危險", objective = "掠奪神秘寶箱。", description = "納迦在整個納沙塔爾藏了許多有用的寶藏。\n\n我聽說，在離這不遠的地方有一個寶藏堆。那裡很危險，不過也很值得調查一番。\n\n寶箱中可能會有不為人知的珍寶，在我們對抗納迦的時候也許能派上用場。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n偷來的納迦貯藏箱"}
MultiLanguageQuestData['tw'][56781] = {title = "深淵中的寶藏", objective = "掠奪神秘的寶箱。", description = "納沙塔爾的納迦城塞有許多珍寶正待人發掘。\n\n前陣子，我注意到一個神秘的寶箱。那個地區的納迦部隊戒備森嚴，所以不管寶箱裝的是什麼，一定是很有價值的東西。\n\n我們應該回去調查一下寶箱。無論裡面裝的是什麼，由我們來掌握都會比較好，可不能讓敵人來使用。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘的艾薩拉箱"}
MultiLanguageQuestData['tw'][56782] = {title = "使者的禮物", objective = "和使者尤提亞會面。", description = "<name>，使者尤提亞希望你能到梅札米爾去。\n\n我相信使者已經準備了不少物品，能對你的旅程有幫助。\n\n希望你一有空就返回梅札米爾，接受使者的禮物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納沙塔爾生存包"}
MultiLanguageQuestData['tw'][56783] = {title = "亮鱗保險箱", objective = "掠奪亮鱗保險箱", description = "在這些古老的廢墟中，有許多寶藏待人發掘。\n\n前陣子，我在離這不遠的一個洞穴裡發現了一個奇怪的箱子。\n\n裡面的物品或許很有價值，我們跟艾薩拉女王決鬥時能派上用場。\n\n我們應該回去調查一下寶箱。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n微微發光的補給品"}
MultiLanguageQuestData['tw'][56784] = {title = "好用的補給品", objective = "和使者尤提亞會面。", description = "使者尤提亞正在等你返回梅札米爾。\n\n使者已經打包了一些好用的補給品，對你的旅程會很有幫助。\n\n請接受這個禮物與我們氏族的感謝。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n安寇恩表揚箱"}
MultiLanguageQuestData['tw'][56785] = {title = "神秘寶箱", objective = "開啟神秘寶箱。", description = "我們在探索納沙塔爾時發現了許多珍奇寶藏。我相信我又找到了另一個藏寶地點，有貴重神器正待取回。\n\n沒多久前，我注意到遠方有個奇怪的東西在發光。我想那可能是個藏寶箱。\n\n我們應該去調查那個物體。如果它是個藏寶箱，在協助我們擊敗納迦方面，裡面的東西可能十分重要。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n偷來的納迦貯藏箱"}
MultiLanguageQuestData['tw'][56786] = {title = "納迦的寶藏", objective = "掠奪神秘的寶箱。", description = "納迦把他們戰爭的戰利品藏在納沙塔爾各處。\n\n之前我們冒險的時候，我注意到一個看起來很神秘的寶箱。寶箱位於納迦領地的深處，所以我想，裡面的東西很可能價值連城。\n\n我們應該把寶箱裡的東西拿來。無論裡面裝的是什麼，由我們來掌握都會比較好，可不能讓敵人來使用。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘的艾薩拉箱"}
MultiLanguageQuestData['tw'][56787] = {title = "額外的補給品", objective = "和使者尤提亞會面。", description = "<name>，使者尤提亞吩咐過，要請你有時間的時候回梅札米爾一趟。\n\n使者有一些額外的補給品，或許能幫助你對抗納迦。\n\n請你一有空就回梅札米爾，並接受使者的禮物，以及我們整個氏族的感謝。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納沙塔爾生存包"}
MultiLanguageQuestData['tw'][56788] = {title = "收復的寶藏", objective = "掠奪亮鱗保險箱", description = "納迦在納沙塔爾各處放了許多戰爭得來的不義之財。只要看到這些戰利品，我們就該把他們奪回來，才能永遠阻止他們的暴行。\n\n我在附近的一個洞穴裡注意到一個奇怪的箱子。它似乎是納迦的產物。\n\n我們應該把寶箱裡的東西拿來。裡面的物品或許很有價值，我們跟納迦戰鬥時能派上用場。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n微微發光的補給品"}
MultiLanguageQuestData['tw'][56789] = {title = "補給品禮物", objective = "和使者尤提亞會面。", description = "使者尤提亞吩咐過，要請你一有空的時候就回梅札米爾一趟。\n\n使者已經收集了一份補給品禮物，讓你能做好更充足的準備來對抗納迦。\n\n希望你一有空就返回梅札米爾。請接受這個禮物與我們氏族的感謝。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n安寇恩表揚箱"}
MultiLanguageQuestData['tw'][56790] = {title = "尋寶去", objective = "掠奪神秘寶箱。", description = "納迦把寶藏藏在納沙塔爾的各處。\n\n不久前，我注意到一個做工精美的寶箱藏在一個非常顯眼的地方。那個地區戒備森嚴，不過這種小障礙還不足以讓我們打退堂鼓。\n\n我們應該回到那裡去，把寶箱裡裝的東西帶回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n偷來的納迦貯藏箱"}
MultiLanguageQuestData['tw'][56791] = {title = "謎樣的寶藏", objective = "掠奪神秘的寶箱。", description = "我們在探索納沙塔爾的時候，找到了大量的寶藏。我相信，我又找到一個等人打開的寶箱了。\n\n前陣子，我注意到一個神秘的寶箱。它放在一個極其危險的區域，所以，不管寶箱裝的是什麼，一定是很有價值的東西。\n\n我們的任務就是把寶箱裡的東西帶回來。無論裡面裝的是什麼，由我們來掌握都會比較好，可不能讓敵人來使用。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘的艾薩拉箱"}
