MultiLanguageQuestData['tw'][56803] = {title = "只是朋友", objective = "前往新鄉拜訪安托莉亞‧海珠。", description = "聽著，弱雞，我得確保輕微的海流不會把你撞倒。\n\n我叫安托莉亞想想辦法，看她能不能湊合點什麼，讓你在這裡不會這麼沒用。\n\n我看了上一場戰鬥的表現，覺得我們最好早點回去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納沙塔爾生存包"}
MultiLanguageQuestData['tw'][56804] = {title = "有你這樣的朋友，誰還需要海葵？", objective = "看看維姆的寶箱裡有什麼。我有時會到贊季爾殿堂玩玩，有很多凶狠的納迦在那邊閒晃。\n\n我會偷一些可能有用的東西，把它們藏在以後我可以回去拿的地方。\n\n我有一陣子沒下去了。\n\n我在那邊放的東西，或許有一些你用得上的。您會收到：\n\n", description = "我有時會到贊季爾殿堂玩玩，有很多凶狠的納迦在那邊閒晃。\n\n我會偷一些可能有用的東西，把它們藏在以後我可以回去拿的地方。\n\n我有一陣子沒下去了。\n\n我在那邊放的東西，或許有一些你用得上的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n維姆回收的補給品"}
MultiLanguageQuestData['tw'][56805] = {title = "好朋友就該這樣", objective = "前往新鄉拜訪安托莉亞‧海珠。", description = "嗯。我不是要承認什麼事，不過我啊，好像有可能，不是絕對，而是有可能搞錯了你的整件…事情。\n\n雖然我們對彼此的耐性可能只剩一點點，不過安托莉亞提到，她又有貨要交給你了。\n\n我們應該去新鄉一趟。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破縛者表揚箱"}
MultiLanguageQuestData['tw'][56806] = {title = "永遠的朋友", objective = "看看維姆的酒。你現在可能已經注意到，我和海巨人相處得很不錯。\n\n他們大部分時間喜歡獨處。他們喜歡開懷大笑，也喜歡跟你講莫名其妙的故事。\n\n多麼簡單的生活。\n\n除了砍殺納迦之外，我們確實還有一個共同的興趣，我們都喜歡品嘗特別的酒。\n\n梅汀最近帶來了一桶很棒的新貨，我把它藏了起來。等它醞釀成熟可以打開時，我就請大家喝酒！\n\n來，你可以看看！您會收到：\n\n", description = "你現在可能已經注意到，我和海巨人相處得很不錯。\n\n他們大部分時間喜歡獨處。他們喜歡開懷大笑，也喜歡跟你講莫名其妙的故事。\n\n多麼簡單的生活。\n\n除了砍殺納迦之外，我們確實還有一個共同的興趣，我們都喜歡品嘗特別的酒。\n\n梅汀最近帶來了一桶很棒的新貨，我把它藏了起來。等它醞釀成熟可以打開時，我就請大家喝酒！\n\n來，你可以看看！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n泡酒的補給品"}
MultiLanguageQuestData['tw'][56807] = {title = "真朋友會幫忙藏屍體", objective = "找到果姆的燈。屍體…寶藏…\n\n我都見識過了，不過，要找到值得結交的朋友，這種事久久才有一次。\n\n我很慶幸我選擇把你當成朋友。\n\n所以，回到朋友這個話題…還有一個地方我也想讓你看看。您會收到：\n\n", description = "屍體…寶藏…\n\n我都見識過了，不過，要找到值得結交的朋友，這種事久久才有一次。\n\n我很慶幸我選擇把你當成朋友。\n\n所以，回到朋友這個話題…還有一個地方我也想讓你看看。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n維姆的謝禮"}
MultiLanguageQuestData['tw'][56808] = {title = "我們會是好朋友", objective = "前往新鄉拜訪安托莉亞‧海珠，領取你的禮物。", description = "了解你的過程一定會很有趣。你這人還不錯嘛！\n\n我們為你準備了一個小禮物，要歡迎你到這地方來。\n\n我希望安托莉亞準備的東西不會太差，她的時間並不多。", progress = nil, completion = "看來你在這裡適應得很不錯。繼續努力吧，年輕人！", rewards = "您會收到：\n\n納沙塔爾生存包"}
MultiLanguageQuestData['tw'][56809] = {title = "超級好朋友", objective = "看看波恩的袋子裡有什麼。你是個宇宙超級無敵棒的朋友！\n\n我有時候會去一個地方拜訪我的小夥伴。我把我找到的一些好東西放在那裡的一個袋子裡。\n\n你想看嗎？\n\n我在問什麼？你當然想啦，我們走吧！您會收到：\n\n", description = "你是個宇宙超級無敵棒的朋友！\n\n我有時候會去一個地方拜訪我的小夥伴。我把我找到的一些好東西放在那裡的一個袋子裡。\n\n你想看嗎？\n\n我在問什麼？你當然想啦，我們走吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n波恩整理好的東西"}
MultiLanguageQuestData['tw'][56810] = {title = "真是位好朋友", objective = "前往新鄉拜訪安托莉亞‧海珠，領取你的禮物。", description = "我的朋友，和你度過的每一天都是一場新的冒險。\n\n你們的船艦沉了我感到很遺憾，但我真高興我們相遇了！\n\n我聽到謠言說，安托莉亞發現了更多的好東西！\n\n我們應該順道去看看她這次找到了什麼！", progress = nil, completion = "我好久沒看到波恩這麼開心了。\n\n這一切都是你應得的！", rewards = "您會收到：\n\n破縛者表揚箱"}
MultiLanguageQuestData['tw'][56811] = {title = "我是你的好朋友", objective = "查看波恩的藏身洞。我喜歡和朋友一起去探索幾個地方。\n\n我還真的發現了這個驚人的…我不知道是什麼東西。\n\n你能和我一起去看看嗎？您會收到：\n\n", description = "我喜歡和朋友一起去探索幾個地方。\n\n我還真的發現了這個驚人的…我不知道是什麼東西。\n\n你能和我一起去看看嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n波恩的儲藏補給品"}
MultiLanguageQuestData['tw'][56812] = {title = "友誼真神奇", objective = "尋找波恩的神奇寶物。和你在一起的每一天都讓我覺得，我每天都在成為更好的海布林。\n\n你不知道，這對我有多重要。\n\n我會覺得，我想做得更多、更好…幫更多忙。\n\n現在，我開始為破縛者做出真正的貢獻了。\n\n這都要歸功於你。您會收到：\n\n", description = "和你在一起的每一天都讓我覺得，我每天都在成為更好的海布林。\n\n你不知道，這對我有多重要。\n\n我會覺得，我想做得更多、更好…幫更多忙。\n\n現在，我開始為破縛者做出真正的貢獻了。\n\n這都要歸功於你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n棘衛補給品"}
MultiLanguageQuestData['tw'][56813] = {title = "出乎意料的朋友", objective = "前往新鄉拜訪安托莉亞‧海珠，領取你的禮物。", description = "哦，<name>，我差點忘了！\n\n為了讓你在納沙塔爾的任務更順利，安托莉亞和我整理了一些你可能需要的物品。\n\n最好趁有空的時候，去拿一下那些東西！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納沙塔爾生存包"}
MultiLanguageQuestData['tw'][56814] = {title = "需要朋友的時候", objective = "找到奈莉的箱子。你還不差嘛，以一個…什麼來著？<race>？\n\n我喜歡這種時刻，會提醒我不要只看外表。哈！\n\n不過說真的，說到把東西藏在顯眼的地方，我確實有把一些東西收在一個納迦木箱裡。那個箱子很靠近他們在艾薩拉之矛的其中一個營地，所以他們永遠不會猜到那是我的！\n\n我們去看它還在不在那裡吧。您會收到：\n\n", description = "你還不差嘛，以一個…什麼來著？<race>？\n\n我喜歡這種時刻，會提醒我不要只看外表。哈！\n\n不過說真的，說到把東西藏在顯眼的地方，我確實有把一些東西收在一個納迦木箱裡。那個箱子很靠近他們在艾薩拉之矛的其中一個營地，所以他們永遠不會猜到那是我的！\n\n我們去看它還在不在那裡吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n巧妙隱藏的補給品"}
MultiLanguageQuestData['tw'][56815] = {title = "朋友的一點小忙", objective = "前往新鄉拜訪安托莉亞‧海珠，領取你的禮物。", description = "除了我們幾個倖存者以外，我已經好久沒有遇到值得信任的人了。\n\n我都忘了這種感覺有多好。\n\n謝謝你讓我重溫這種感覺。\n\n安托莉亞現在整理好你剩下的禮物了。我們應該去找她問問看！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破縛者表揚箱"}
MultiLanguageQuestData['tw'][56816] = {title = "海布林最好的朋友", objective = "檢視奈莉的發現。在我們的抗戰中，知識就是最好的武器。\n\n認識你就是很好的證明！\n\n我找到了某個東西，它能讓我看到我以前都看不到的東西。\n\n就算沒有水，我也能看到很遠！我現在都會時不時用它來看看納沙塔爾的情況。\n\n我直接給你看吧！您會收到：\n\n", description = "在我們的抗戰中，知識就是最好的武器。\n\n認識你就是很好的證明！\n\n我找到了某個東西，它能讓我看到我以前都看不到的東西。\n\n就算沒有水，我也能看到很遠！我現在都會時不時用它來看看納沙塔爾的情況。\n\n我直接給你看吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n奈莉的整齊補給品"}
MultiLanguageQuestData['tw'][56817] = {title = "謝謝你當我朋友", objective = "享受奈莉的私房景點。自從水牆出現以來，這裡發生了很大的變化。\n\n我發現了一個小地方，你可以在那體驗浪花灑在臉上的感覺。\n\n有時我會騎到那裡放鬆一下。\n\n如果你想去，我可以帶你去。您會收到：\n\n", description = "自從水牆出現以來，這裡發生了很大的變化。\n\n我發現了一個小地方，你可以在那體驗浪花灑在臉上的感覺。\n\n有時我會騎到那裡放鬆一下。\n\n如果你想去，我可以帶你去。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n奈莉的備用補給品"}
