MultiLanguageQuestData['tw'][56829] = {title = "底棲生物", objective = "找到棍臉和宮務大臣。", description = "喔，真糟糕，實在太糟糕了。\n\n每次有人誤入這個地方，往往從此人間蒸發。一旦誤入這個地方…往往都會以某種型式永遠留在這裡。\n\n我們來做個交易吧。既然你是淵喉行者，你負責去找棍臉和宮務大臣，我則留在這裡負責修好馬車，然後趕在有東西想吃掉我們、幹掉我們之前，全部人一起離開這裡。", progress = nil, completion = "啊，很好，沒人淪為食物。\n\n馬車修好了，隨時都能出發。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56830] = {title = "來自深淵的召喚", objective = "您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56839] = {title = "『駭人』屠爪", objective = "擊敗『駭人』屠爪。", description = "<你看到巨魔製作的一面粗糙告示牌。寫著一個警告。>\n\n大熊！超壞！\n\n大熊守住大巨魔財寶！\n\n在儀式後殺！取得財寶，更強大！", progress = nil, completion = "&lt;你找到了一個寶箱，就跟巨魔告示牌上寫的一樣！&gt;", rewards = "遠征隊皮甲肩甲遠征隊鎧甲肩衛遠征隊布甲披肩遠征隊鎖甲肩甲遠征隊皮甲肩甲遠征隊鎧甲肩衛遠征隊布甲披肩遠征隊鎖甲肩甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][56842] = {title = "保存月光", objective = "在世界各地的月井，完成月之儀式。你可以在梣谷、費伍德森林、菲拉斯、月光林地、石爪山脈、暮色森林和海加爾山找到月井。\n\n如果你的月之祝福失效，就得重頭開始。", description = "多年以來，這把法杖一直在為我效力。它一直陪在我身邊，歷經各種試鍊…而且隨著我的年紀增長，發現我一直在從它身上學習更多事物。\n\n在每個新年慶典它都會開花，沐浴在伊露恩的光輝下。它們為我帶來喜悅，我真希望它們能終年盛開。我有個辦法…但我這身老骨頭禁不住旅途奔波。\n\n或許你能幫我完成這趟旅程？前往全世界的月井，讓我的法杖在井中的月光下強化。我的花朵就會留存下來。", progress = nil, completion = "你做到了！我可以從中感受到伊露恩的力量。現在我可以和我的花朵相伴，一直到老了。\n\n或許我也能幫你辦到同樣的事。如果你手中有些想要保存的花朵，帶來給我。或許我幫得上忙。", rewards = "您會收到：\n\n先祖硬幣"}
MultiLanguageQuestData['tw'][56889] = {title = "受傷的廢土漫遊者", objective = "為6位廢土工人治療。", description = "啊，朋友，你是回來繼續幫忙的嗎？\n\n就像你所看到的，我們依然在和這些生物戰鬥，牠們簡直源源不絕。\n\n這是場消耗戰，我們的傷亡越來越慘重，處於相當不利的情況。\n\n拜託了，去協助廢墟裡的傷者吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩聚合幻象艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][56903] = {title = "勇氣之冠", objective = "從永歌森林、辛特蘭和莫高雷收集花朵。", description = "我看得出你對粉紅色花朵有所偏好。很可惜的是，編成花環的花遲早會凋謝。\n\n或許我能幫得上忙。\n\n雖然這些只是普通的花朵，我知道有一種類似的花，只在新年慶典綻放。如果你能幫我取回這些花，我可以為它們灌注伊露恩的力量，讓你能整年享受它們的美麗。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n無窮勇氣頭冠"}
MultiLanguageQuestData['tw'][56904] = {title = "豐饒之冠", objective = "從安戈洛環形山、荊棘谷和北貧瘠之地收集花朵。", description = "你的花冠真是五彩繽紛！如此美妙的粉紅、黃、藍搭配…要是能保存下來就好了。\n\n雖然這些花朵無法永存，但我知道有別的花可以！\n\n在每年的新年慶典都會綻放類似的花朵。因為你的所作所為，讓我瞭解它們與伊露恩之間有一股我能進一步加強的連繫。幫我取得花朵，我們就可以編成花冠，讓你享用一整年！", progress = "伊露恩一向對花朵抱有好感。這些在新年慶典中綻放的花朵十分特殊。", completion = "好豐富的色彩！這些花朵會讓所有人一看到就滿心歡喜。\n\n這頂花冠應該可以為你帶來永世昌盛。", rewards = "您會收到：\n\n永久豐饒頭冠"}
MultiLanguageQuestData['tw'][56905] = {title = "暗花之冠", objective = "從暮色森林、銀松森林和淒涼之地收集花朵。", description = "如此憂鬱的花朵…但它們具備自成一格的美麗，你不覺得嗎？要是它們能保存下來就好了。\n\n容我提供協助。\n\n每次的新年慶典，類似你手中的花朵就會在全世界盛開。它們與伊露恩之間有一股…我能進一步強化的連繫。如果你把它們帶來給我，我可以加以保存，讓它們在一般花朵凋謝的期限之後，依舊可以觀賞。", progress = "在新年慶典綻放的花朵具備特殊本質。我相信它受到了伊露恩之光的眷顧。", completion = "啊，真是令人心平氣和的花。我感受到一股莊重的平靜從中散發出來。\n\n這頂花冠應該能用無聲的優雅來支持你。", rewards = "您會收到：\n\n永恆追悼頭冠"}
MultiLanguageQuestData['tw'][56906] = {title = "幸運之冠", objective = "從冬泉谷、丹莫洛和希爾斯布萊德丘陵收集花朵。", description = "這些花讓我想到了伊露恩！我終年戴著類似的花冠，來提醒自己她的恩典無處不在。\n\n或許你也想要一個？\n\n你的花冠是用一般的花朵編成，有一天會凋謝死亡。對如此精緻的美妙事物而言是不幸之事，但我的花冠是用類似的花朵，但卻是在去年這個時候做的！如果你能把新年慶典期間綻放的特殊花朵帶給我，我就能祝福它們，讓你也能享受花冠一整年！", progress = "這話就我們兩人知道就好，我相信這些是伊露恩最喜歡的花朵。它們映射出華麗的月光光輝！", completion = "啊，和我一樣的花朵。我可以從中感受到伊露恩的存在。\n\n這頂花冠應該可以為你這一生帶來幸福。", rewards = "您會收到：\n\n永遠幸運頭冠"}
MultiLanguageQuestData['tw'][56907] = {title = "油漆瓶：超核紅", objective = "把物品帶去給克拉姆‧克拉達。\n\n已提供物品：\n", description = "<克拉姆‧克拉達應該用得到這東西。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56908] = {title = "油漆瓶：哥布林綠", objective = "把物品帶去給克拉姆‧克拉達。\n\n已提供物品：\n", description = "<克拉姆‧克拉達應該用得到這東西。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n上色新漆\n\n您還會收到：\n\n"}
