MultiLanguageQuestData['tw'][56942] = {title = "再次上路", objective = "搭乘馬車。", description = "好了，大夥！全都上車！", progress = nil, completion = "我們的馬車是過不去那裡的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56955] = {title = "路上的叛軍", objective = "殺死5個石源魔叛軍。", description = "太糟糕了，石源魔叛軍偷襲了稅務官的直屬車隊。而大總管正是管轄這個結界的當地收割者。\n\n我們必須突破重圍。在這戰場的另一端，有座通往暗隱村的橋。主宰通常會在那裡部署一些他直屬的石源魔軍團部隊。\n\n為我們殺出一條血路，淵喉行者。凡是擋路者，格殺勿論。我們不能讓戴納瑟斯王久等。", progress = nil, completion = "你在戰鬥方面極具天賦。也許再花個幾百年，再加上一點點謙虛，我們就能讓你脫胎換骨。", rewards = "石鑄束腰痛苦赦免束帶獵魂者腰帶夜幕腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][56969] = {title = "古老的暗礁行者樹皮", objective = "嗯？怎麼了？", description = nil, progress = "嗯？怎麼了？", completion = "暗礁行者的皮有很多用途，從建築到護甲都用得到。\n\n這一塊一定是從相當古老的暗礁行者上面剝下來的，因為超大一片！這下子可以做出好多東西來。\n\n謝謝你，我會把獎勵送去營地！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56970] = {title = "暗礁行者樹皮", objective = "嗯？怎麼了？", description = nil, progress = "嗯？怎麼了？", completion = "暗礁行者的皮有很多用途，從建築到護甲都用得到。\n\n謝謝你，我會把獎勵送去營地！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56971] = {title = "鰻魚片", objective = "嗯？怎麼了？", description = nil, progress = "嗯？怎麼了？", completion = "我最喜歡這個了！你怎麼知道的？\n\n我會在營地料理這個，這樣大家都能一起享用。", rewards = "您會收到：\n\n納沙塔爾盟友 - 維姆‧鹽心"}
MultiLanguageQuestData['tw'][56972] = {title = "魟魚鰭", objective = "嗯？怎麼了？", description = nil, progress = "嗯？怎麼了？", completion = "你帶來的魚翅很棒又多汁。\n\n我會好好料理給大家吃。", rewards = "您會收到：\n\n納沙塔爾盟友 - 奈莉‧銳鰭"}
MultiLanguageQuestData['tw'][56973] = {title = "巨大螃蟹腳", objective = "嗯？怎麼了？", description = nil, progress = "嗯？怎麼了？", completion = "哇喔，這根真大，看起來好好吃！\n\n今天晚上我要用它來煮湯，大家一定會超開心的。", rewards = "您會收到：\n\n納沙塔爾盟友 - 波恩‧括鰭"}
MultiLanguageQuestData['tw'][56978] = {title = "前往暗隱村", objective = "護送宮務大臣前往暗隱村。", description = "這座橋的另一端就是暗隱村，正由戴納瑟斯王的效忠者嚴加看守。這些可悲的叛軍絕不敢越雷池一步。\n\n不過，外人想要進入也是難如登天。好了，靈魄交給我來保管，你負責確保不會有人再把我們丟回歿路沼澤。", progress = nil, completion = "現在或許還看不出來，但這場叛亂已經氣數已盡。那些膽敢反抗主宰的傢伙，將會體驗到前所未有的痛苦與磨難。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56979] = {title = "挽救攻城機具", objective = "移除8個可疑的木箱。", description = "在岩石崩塌的混亂中，希瓦娜斯派出的破壞部隊溜過我們的衛哨，並且在我們的攻城武器上安置了炸藥。\n\n我們已經損失了好幾台了，不能再繼續損失下去。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56980] = {title = "滲透進來的敵人", objective = "殺死10名可疑的技師或忠誠派刺客。", description = "雖然有些部落人士加入我方，但是在奧格瑪仍有許多人效忠希瓦娜斯。她的破壞部隊和刺客偽裝成我們的士兵，滲透進來了。\n\n阻止你碰到的所有忠誠者，別讓他們造成進一步破壞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56981] = {title = "戰略佈署", objective = "送交安杜因的佈署命令。", description = "薩魯法爾主張，攻下奧格瑪的關鍵在於找出多個突破口。他長年負責城市的防禦，而且比任何人都清楚防禦上的弱點。雖然我方兵力會因此分散，不過我在這方面信任他的判斷。\n\n我們一定要同時鞏固雷霆崖的防禦，以免希瓦娜斯趁我們大軍在此集結時展開突襲。\n\n將這些佈署命令送到我方軍官手上。我們會同時襲擊奧格瑪的每一座大門，並且保護雷霆崖。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56982] = {title = "奧格瑪的正門前方", objective = "在奧格瑪的正門展開戰鬥。", description = "我們要盡量為這場戰鬥做好準備，$p。\n\n我祈禱，戰鬥結束時我們都能存活下來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][56993] = {title = "勝利的代價", objective = "召回聯盟部隊並告知一切經過。", description = "薩魯法爾…怎麼會發生這種事…\n\n<珍娜花了一點時間平復心情。>\n\n聯盟很清楚薩魯法爾霸王不但是個死敵，也是個無可取代的盟友。\n\n安杜因一定想在心中悼念他。召回我們的部隊，並告訴他們此地發生的事。吉恩的士兵被派往西側大門。你可以去那邊找他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57001] = {title = "榮譽谷", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57002] = {title = "老兵", objective = "在奧格瑪的正門和珍娜交談。", description = "不管他內心有什麼疑慮，薩魯法爾是位高尚的士兵。\n\n他不但阻止了部落的內戰，也預防了聯盟崩毀的潛在危機。他結束了希瓦娜斯的統治，並付出自己的生命來拯數許多人。\n\n我們應該要悼念他的犧牲。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n戰場表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57003] = {title = "屬於你自己的力量", objective = "請虛空編織師左蘭升級一件海底護甲。", description = "對一個靜置在海床上的東西來說，這個東西還蘊藏著力量。\n\n帶一件海底護甲給虛空編織師左蘭。他一直帶著好奇的目光打量著它。\n\n去迎合那個以太族，讓他仔細看看。\n\n或許他能給出一些建議。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57004] = {title = "屬於你自己的力量", objective = "請虛空編織師司杜薩升級一件海底護甲。", description = "你攜帶的海底護甲已經在浪潮下遺失多年。\n\n裡面還潛藏了一些力量。\n\n虛空編織師司杜薩或許可以提供一些見解。\n\n帶著你的發現去找我們那位無畏的以太族朋友，看看他有什麼辦法。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57005] = {title = "成為朋友", objective = "使用呼喚海螺，選擇一位盟友，然後完成3個盟友任務。", description = "如果你需要朋友的話，我們之中最勇敢的海布林自願加入你的冒險行列。\n\n你會發現他們都具備獨特的興趣，而且每天都會在你的地圖上標示出不同的機會。\n\n在你準備好的時候就吹響海螺，選擇想要加入你的人士，出發探索納沙塔爾！\n\n選擇時務必慎重！你每天只能選擇一位朋友。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠"}
MultiLanguageQuestData['tw'][57006] = {title = "寶貴的盟友", objective = "使用深焰營火，選擇一位盟友，然後完成3個盟友任務。", description = "我們之中最勇敢的安寇恩自願加入你的冒險行列。\n\n你會發現每一位都具備獨特的興趣，而且每天都會在你的地圖上標示出不同的機會。\n\n在你準備好的時候使用深焰營火。選擇一位高貴盟友加入你的行列，然後探索納沙塔爾的其他地區。\n\n選擇時務必慎重！一天只能選擇一位。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠"}
MultiLanguageQuestData['tw'][57007] = {title = "主宰的邀請", objective = "搭乘暗隱村馬車。", description = "偉大的戴納瑟斯王，瑞文崔斯之主，汎希爾的領袖，吩咐他忠心的宮務大臣，也就是我，將你毫髮無傷地送到他的私人庭園。對於一個活著的凡人來說，這可是前所未有的恩典。\n\n你應該感到榮幸。\n\n來吧，跟我一起搭乘馬車，我們應該風風光光地前往城堡。", progress = nil, completion = "喔，很好，還沒死啊？\n\n你看到宮務大臣或棍臉降落的地方了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57008] = {title = "突擊戰：交戰的氏族", objective = "在恆春谷擊退魔古的攻勢。", description = "恆春谷的防衛者才剛遭受完恩若司攻擊，那些投機取巧的魔古氏族就想要趁這個時候佔領恆春谷。\n\n他們既膽小又愚蠢。\n\n讓他們知道自己是錯誤的。", progress = nil, completion = "這些冒牌者會明白，他們如果不加入萊加尼，就只有死路一條。\n\n你讓他們見識到了這點，做得好。", rewards = "您會收到：\n\n墮落魔古寶箱艾澤萊晶岩"}
MultiLanguageQuestData['tw'][57009] = {title = "追求地精名聲更待何時", objective = "到波拉勒斯與技工大師歐沃斯巴克會面。", description = "技工大師歐沃斯巴克需要你在一支重要的研究遠征中提供協助。\n\n能夠和備受尊敬的大工匠共事，肯定能對你的事業提供助益。我在過去就獲得數不清的好處！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57010] = {title = "駕馭神力", objective = "使用心之熔爐頂端的石化黑鱗片，將它的力量灌注到艾澤拉斯之心。", description = "心之熔爐可以使用了。\n\n啟動最後的同調程序。\n\n正在等候來自勇士單位<name>的輸入。", progress = nil, completion = "很好！很好！看起來跟母親大人說的一樣！艾澤拉斯之心獲得新能力了！\n\n其他精華一定散佈在艾澤拉斯其他地方，一定要找出來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57022] = {title = "突擊戰：阿瑪賽特進軍", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57023] = {title = "加重過的魔古文物", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57024] = {title = "機械岡的傳聞", objective = "到達薩亞洛的大封印外面和加茲魯維會面。", description = "我就知道我不該和技工一塊進行的…\n\n加茲魯維的手下肯定可以分一杯羹，還不用冒任何風險。我聽說他們準備展開什麼大計畫…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57025] = {title = "向瑞文崔斯求助", objective = "前往瑞文崔斯。", description = "說到抽取靈魄，瑞文崔斯很可能是最有…效率的…，或許他們可以提供別人辦不到的協助。\n\n先說一下，儘管靈魂有時會從瑞文崔斯歸來，但回來的時候，它們都會變了一個樣。那是個可怕的地方，審斷者認定有機會獲得救贖的靈魂才會被送去那裡。\n\n不過，這條路走起來並不輕鬆。\n\n卡薛爾會協助你打開一道通往瑞文崔斯的傳送門。到樞運之環和他會面。", progress = nil, completion = "招待不周，請見諒。這裡通常有個負責迎客的汎希爾人。我們已經有段時間沒看到有人穿過那道門了。\n\n不過還好，比起晨間體罰，我對於歡迎辭更加瞭解。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57026] = {title = "罪孽石", objective = "四處看一看。", description = "嗯，你和其他人不一樣。正常來說，你抵達此地之前就已經死了。喔，好吧。罪孽就是罪孽、石塊就是石塊，正如其形。\n\n讓我們整理一下你的罪孽石。麻煩你，這邊走。", progress = nil, completion = "希望這些討厭生物的瘋狂嘮叨不會讓你感到太過無趣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57037] = {title = "原音重現", objective = "淨化純潔禱鐘與和諧禱鐘。", description = "那些禱鐘！那個鐘聲！\n\n禱鐘的聲音被扭曲了！要是它們繼續發出這種聲音，我們所有人都會屈服。\n\n<伊芮迪雅將她的錘子塞到你手中。>\n\n找到神殿中的巨大禱鐘，用我的錘子敲鐘。希望錘子的純淨之音能讓鐘聲恢復成真正的原音！\n\n我會聆聽那響亮清澈的聲音，在橋邊跟你會合。趕快出發！", progress = nil, completion = "我可以再一次聽到它們的鐘聲了。它撼動了我的心靈，但最大聲的雜音還在，我們必須將它停下，不然我們所鐘愛的一切將不復存在。", rewards = "旋律保衛者壁壘音律迴響禱鐘您會收到：\n\n"}
MultiLanguageQuestData['tw'][57039] = {title = "精神谷", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57043] = {title = "老朋友，新契機", objective = "到荊棘谷與賽希‧硬心交談。", description = "欸，這不是<name>嗎！你正是我們要找的哥布林！\n\n自從凱贊一別之後，已經好久沒見了，對吧？想當年我們一起四處闖盪，真是美好時光！\n\n不過我不是來讓你感傷的，賽希‧硬心派我來找你。她打算把大家找回來，一起做件大事！很大的事！\n\n聽我說，我是很想和你多聚聚，但我得閃了。時間就是金錢啊，你懂吧？\n\n如果你想參一腳，就去找賽希。她會把細節通通告訴你！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n凱贊的傳承\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57045] = {title = "特別快遞", objective = "將包裹交給荷巴爾特‧繫錘。", description = "很高興你終於來了，<name>。我有個很重要的東西要送，而你是我最信任的哥布林。\n\n好啦，好啦。我知道這只是嘴巴說說，但這一陣子很難找到好幫手！\n\n這個包裹得送到荷巴爾特‧繫錘手中。他在廢坑市集有個工坊，我需要你把貨物送過去。他最近在搞一件大事業！\n\n把包裹送過去，而且看在錢的份上…請小心輕放！\n\n你絕對不知道我花了多少時間在找這玩意兒！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57049] = {title = "萬魂殿", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57051] = {title = "討債！", objective = "討回8筆未結清的債務。", description = "你需要熱插頭？好吧，你找對地方了，小朋友。\n\n但想要賒帳取貨，門都沒有。有太多混蛋老是賴帳不還錢，我一直覺得很頭大，要是不能先拿到款項，很快就會關門大吉。\n\n<克蘭克‧油管想了一陣子。>\n\n聽好，這樣吧…如果你能叫那些素行不良的混混把欠我的錢吐出來，我就把熱插頭當報酬送你。\n\n別的地方可找不到這麼划算的交易！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57053] = {title = "鈍器攻擊測試", objective = "完成荷巴爾特‧繫錘的實驗。", description = "既然有熱插頭了，該準備下個階段的X-52型單兵護甲原型測試了！\n\n不幸的是，我的實驗室助理不是辭職，就是殉職。真是太慘了！但他們的不幸就是你的好運，<name>…現在得由你來試穿X-52型單兵護甲！\n\n好興奮啊！\n\n下一次測試，將會由我的新任機械實驗室助理來主持。前往主工坊，按下紅色大按鈕就可以開始。\n\n別擔心，我會透過X-52內建的對講機提供指示。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57058] = {title = "踩地雷", objective = "從地雷區取回清涼椰子冷飲。", description = "X-52型單兵護甲原型準備進行最終測試！\n\n<name>，你承受得住刺耳的噪音和突如其來的連續能量爆發嗎？\n\n在最後的測試中，我們打算把你關在X-52型單兵護甲裡面，並派你走過地雷區！\n\n我在地雷區中間放了一杯清涼椰子冷飲。如果你能度過途中避無可避的爆炸，就可以將那杯飲料視為抵達綠洲的最佳獎勵！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57067] = {title = "魔古壓境", objective = "到聖獸天尊之門和老陳與莉莉‧風暴烈酒會面。", description = "時候到了。其他的魔古氏族鎖定了恆春谷。\n\n絕對不能讓他們征服那個地方。\n\n你有幾位盟友已經前去大門那裡探查他們的規模和兵力。如果你自認有資格面對這樣的任務，就去那邊和他們會合吧。", progress = nil, completion = "上次看到這麼多魔古集結在一起的日子，可能要追溯到…呃，我想不起來了！\n\n我們一定要謹慎應對。他們已經霸佔了整片平原。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57068] = {title = "風箏監視", objective = "坐上老陳的風箏前去偵察魔古大軍。", description = "我們聽說有魔古在攻擊，但我從來沒料到數量如此龐大！\n\n一定有什麼辦法可以在他們徹底拿下恆春谷之前擋住他們。快，我們快飛過去探查他們的數量。\n\n我們剛好有一個可以乘載三個人的風箏。平常可以多載幾個，但我中午吃太飽了。", progress = nil, completion = "噢，不，我們迫降的力道太猛烈了。老陳叔叔爬不起來！而且到處都是魔古！\n\n沒關係。沒事的。我們會想出辦法的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57069] = {title = "擒賊必先擒王", objective = "殺死魔古指揮官。", description = "好。我們被三支魔古大軍包夾，而且老陳叔叔傷勢過重，暫時還沒辦法行動。\n\n但也並不是毫無希望。我們現在有機會解決這些軍隊的領袖。或許這麼做可以拖慢他們的腳步，甚至吸引他們的注意力，讓我們有足夠時間回到大門！\n\n看你能不能去外面那邊解決掉最大、最兇猛的魔古。那些傢伙一定是指揮官。", progress = nil, completion = "做得好。少了領袖，魔古的威脅就沒那麼可怕了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57070] = {title = "魔古大屠殺", objective = "在崑萊峰殺死魔古。", description = "我想目前的情況可以用我朋友常說的「目標滿天下」來形容。更合適的說法是「被包圍的我們八成沒救了」。\n\n你知道這是什麼意思。我們得盡可能殺光這些魔古。你想用什麼方式，我都沒意見，只要能解決掉他們就行了！", progress = nil, completion = "倒下的魔古還真多。希望這樣可以削減他們的數量，讓我們逃出此地。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57071] = {title = "一滴酒都不能少", objective = "在崑萊峰找到被丟棄的酒桶。", description = "我的頭…好痛。只剩一個辦法了。\n\n我們之前曾經從一支廢棄啤酒商隊的上頭飛過。我們必須找到那支商隊，拯救那批酒！那應該可以讓我重拾全部的力量。\n\n此外，如果我們能找回那批酒，在恆春谷奮戰的人們也會士氣大振。", progress = nil, completion = "&lt;這些一定就是老陳在空中飛行時所看到的酒桶。\n\n你一個人是搬不動的。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57072] = {title = "樣樣精通的犛牛", objective = "找些東西幫你把酒運回去給魔古岬的老陳。", description = "<這些酒桶又重、數量又多，只憑你自己一個人是搬不動的。\n\n或許你能找個東西或是幫手來協助你。>", progress = nil, completion = "這是什麼？你找到了一頭犛牛？\n\n還不只這樣，你連酒都給運回來了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57074] = {title = "背門一戰", objective = "和老陳與莉莉騎乘默比，回到聖獸天尊之門。", description = "你能發現這批酒，還有一頭扛得動的犛牛，實在太幸運了。\n\n但我們不能留在此地。在經過莉莉的治療後，我已經可以行動了。我們可以坐上犛牛回到大門，希望那些魔古在我們行經的過程中不會注意到我們。\n\n準備要離開的時候告訴我一聲。", progress = nil, completion = "我們通過了！接下來，我們要怎麼對付這些魔古呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57075] = {title = "勇氣之水", objective = "騎乘默比並用酒的力量擊潰魔古大軍。", description = "我們得想辦法對付這些魔古。至少要在他們侵略恆春谷之前，削減他們的數量！\n\n雖然老陳叔叔很喜歡他的酒，但是我想我們可以把它用在更重要的事情上面。咱們跳上那頭犛牛，讓魔古嚐嚐他們最害怕的東西吧！", progress = nil, completion = "風味絕佳的酒都…沒了。\n\n但我們往好處想。現在，和我們對峙的魔古更少了。我們該返回基地了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57076] = {title = "回到霧臨", objective = "回到恆春谷的靜默聖地去找颶語者齊恩。", description = "這裡沒有我們能做的事了。我們很清楚，魔古是個明確的威脅。\n\n如果我們守不住恆春谷，讓此地落入他們手中，熔爐就危險了。\n\n我們回去霧臨村向萊加尼回報吧。他們一定很想知道我們正面臨著什麼樣的處境。", progress = nil, completion = "這麼說，其他氏族打算舉兵侵略恆春谷囉？\n\n我們會向他們展示什麼才是真正的力量。", rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][57077] = {title = "誠徵買主！", objective = "到荊棘谷與賽希‧硬心交談。", description = "X-52型單兵護甲終於完成了，加里維克斯也夾著尾巴落荒而逃！\n\n這一切都要感謝你，<name>！\n\n但我們的工作尚未結束…最棒的部份才要開始。我們要舉辦一場拍賣會，將X-52型單兵護甲賣給出價最高的買主！\n\n賽希‧硬心應該有一份名單，上面列出感興趣的買家。跑一趟硬心藏匿處，讓她知道我們準備拍賣了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57078] = {title = "VIP名單", objective = "送出繫錘私人拍賣會邀請函。", description = "在你忙著協助繫錘打造他的最新發明時，我用盡各種方法尋找有潛力的買主！\n\n這會是場私人拍賣會，所以我們只打算邀請最聰明的一流人士、頂尖的精英、人上之人…懂了嗎？\n\n我已經把潛力買主縮小到一份「超上流」名單，只把最富有、最豪華、人脈最廣的哥布林列入其中…當然，加里維克斯已經被剔除掉了！\n\n去送交這些邀請函，我趁這個空檔為拍賣會做最後準備！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57079] = {title = "把他趕出廢坑市集！", objective = "完成廢坑市集事件。", description = "天啊，見到你真是太棒了！我們碰上大麻煩了…\n\n在你去送邀請函的時候，加里維克斯和他的手下全面佔領了廢坑市集！他們把荷巴爾特‧繫錘關了起來，逼他交出X-52型單兵護甲！\n\n你要趕快阻止加里維克斯，否則一切就完了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57085] = {title = "強力戰車", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57086] = {title = "瘋狂法師留下的寶貝", objective = "調查馬爾迪瓦司實驗室", description = "<這個相當大塊的寶石底部刻著：\n\n「馬爾迪瓦司所有物」。如果拾獲請送至我的實驗室。\n\n說不定這個實驗室就在附近？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜光法力珍珠稜光法力珍珠"}
MultiLanguageQuestData['tw'][57087] = {title = "巴魯克殲滅者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57088] = {title = "這不是地雷", objective = "清除剃刀嶺和奧格瑪關口之間的巨石、地雷和其他障礙。", description = "通往奧格瑪的峽谷道路部份崩塌，看來是希瓦娜斯忠誠者下的手。現在我們的部隊被隔開了。\n\n我們必須支援我方的前線部隊，要不然女妖就能以逸代勞、一個一個解決掉我們。我們走了那麼遠，可不是來這邊被千刀萬剮的。\n\n加茲魯維和一位聯盟地精相信他們有解決之道。你最好能確定他們的計畫不會危害到自身。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57089] = {title = "維爾席克孵化場", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57090] = {title = "拯救攻城機具", objective = "移除8個可疑的木箱。", description = "那個女妖的間諜趁著岩石崩塌、現場一片混亂的時候，穿越我們的守衛。他們已經在我們的攻城武器上面裝設了炸彈。\n\n處理掉那些炸彈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57095] = {title = "老兵", objective = "追悼薩魯法爾霸王。", description = "不管其他人怎麼說，他是位值得尊敬的獸人。他譜下了自身的傳奇，這是所有部落戰士的理想典範。\n\n他獻出他的生命，彌補部落中的鴻溝，並讓我們有機會鑄造一條全新的前進之路。他是一位死得其所的戰士。這是一位英雄之死。\n\n我們應該要向他的犧牲追思悼念。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n戰場表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57098] = {title = "恐懼林地", objective = "到恐懼林地和懼獵者會面。", description = "啊，的確。你把控罪者帶到我面前幫了一個大忙，淵喉行者。\n\n為了慶祝這件事，我堅持邀請你參與一場瑞文崔斯的神聖傳統：悔罪之狩。我們的職責就是將羞辱般的恐懼打進那些最…頑強靈魂的內心。\n\n想要有所改變，恐懼可以提供強大動力。\n\n到下面的恐懼林地和懼獵者會面。你會在那邊預做整備。", progress = nil, completion = "歡迎來到恐懼林地。\n\n你可以在這邊看到靈魄的初步處理過程，也就是你在追尋的事物。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57099] = {title = "A Dreadful Roundup", objective = "Collect 6 Condemned Souls.", description = "Welcome to The Banewood, Maw Walker.\n\nAs Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt.\n\nIn the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57100] = {title = "Feeding Time is Over", objective = "Kill Winged Terrorbeasts and collect 6 of their fangs.", description = "A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast.\n\nTheir fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. \n\nGo and collect some from their corpses. Their population is a bit large right now anyhow.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57101] = {title = "參天蛟籠", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57102] = {title = "抱歉借魄一下", objective = "從附近的百衛身上收集靈魄。", description = "對，接待員。\n\n看來這台助憶士被關掉了。最近靈魄過度缺乏，又沒有新的靈魂來到我們的大門…我想這應該是為了節約能源，畢竟靈魄可是珍貴的資源。\n\n附近還有一些百衛機兵，它們的一部分靈魄應該就足夠我們使用了。\n\n啊！我們有位樂於助人的侍者在此地提供協助。她會協助你完成收集工作。\n\n取得足夠的靈魄之後再回來，我們就可以再次為接待員充飽能量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
