MultiLanguageQuestData['tw'][57112] = {title = "Test Shared Quest", objective = nil, description = "無", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57113] = {title = "追蹤萊索妮雅", objective = "到謙遜神殿外找克蕾雅。", description = "我們的斥候回報萊索妮雅和烏瑟正在前往謙遜神殿。\n\n身為棄誓者實質的領導者，我們可不能讓她就這樣輕輕鬆鬆扭曲周遭人士的想法。\n\n\n謙遜的追隨者們沒有回應我們的呼喚。我已經派了克蕾雅先去觀察情況，到神殿外面找她。", progress = nil, completion = "神殿裡到處都是棄誓者，我們必須找到生還者！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57114] = {title = "空中偵察", objective = "與克蕾雅一起飛行，尋找生還者。", description = "神殿裡都是效忠棄誓者的手下。\n\n如果我還是志士，這個任務就有點太龐大了。還好我現在已經不是了。\n\n我們要從空中調查情況。我們一起面對挑戰，盡可能找出生還者。", progress = nil, completion = "幸好你們兩個找到我們了。\n\n很多人都受了傷，我可以維持傷者的生命，但這會花上我所有的心力。你們必須幫我們擊退棄誓者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57115] = {title = "謙遜神聖卷軸", objective = "收集5個神聖卷軸。", description = "棄誓者正在圖書館東翻西找，從我們的藏書中尋找特定文稿。\n\n我們絕不能讓他們找到想要的卷軸。去找那些棄置的卷軸，帶回來給我保管。", progress = "散落在神殿中的卷軸涵蓋很多主題，例如不同世界的資訊、訓練之柱及古代儀式。", completion = "他們似乎想要進行我們最強力的儀式，並且正在收集相關情報。但這是為了什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57116] = {title = "屈服於傲慢", objective = "阻止棄誓者進行儀式，解放5個背負重擔的志士。", description = "志士之所以在這座神殿花費這麼多時間，是因為他們還不能正視自己的傲慢。\n\n曾經，我也是他們的一員。\n\n在監視的過程中，我發現棄誓者會逼迫這些志士與他們同流合汙，在無法利用之後又棄之敝屣。\n\n你必須阻止棄誓者，讓那些志士免於遭受悲慘的命運。", progress = nil, completion = "謝謝你，&lt;name&gt;。這些志士會繼續自我砥礪，為昇靈堡效力。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][57117] = {title = "自食惡果", objective = "到美德露臺擊敗15個棄誓者士兵。", description = "萊索妮雅的部隊洗劫了我們的神殿…他們早已背離御靈者的懷抱。\n\n儘管難以說出口，但你必須擊敗他們，別讓他們再繼續荼毒我們的族人。\n\n帶著憐憫一起去。既然它的力量已經恢復，它一定可以派上用場。", progress = nil, completion = "我的兄弟姐妹，跟棄誓者戰鬥…絕非易事。", rewards = "您會收到：\n\n無私御靈者符印名望名望"}
MultiLanguageQuestData['tw'][57118] = {title = "淵喉扭曲", objective = "到美德露臺摧毀3個靈魄收集器。", description = "萊索妮雅的士兵正在改造靈魄收集器，準備將淵喉能量散播到神殿各處。他們一邊阻撓我們的部隊，一邊壯大自己的勢力。\n\n收集器已經遭到腐化，拿著憐憫摧毀它們，扼止萊索妮雅的野心。", progress = nil, completion = "別擔心收集器。隨著乾旱降臨，它們早就有很長一段時間沒有運作了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57120] = {title = "『謙遜之刃』憐憫", objective = "殺死化身，為『謙遜之刃』憐憫充能。", description = "<你發現一把熟悉的劍，插在棄誓者的屍體上。謙遜楷模一定是為了追上萊索妮雅，把劍留在這裡。\n\n它看起來毫無光彩，靈魄像是被用光了一樣。或許你可以恢復它原本光亮的模樣。>", progress = nil, completion = "是憐憫！\n\n神聖楷模急著去追萊索妮雅，居然忘了帶上他的劍。這或許是將棄誓者趕出神殿的關鍵。\n\n你拿走劍吧，希望它會派上用場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57121] = {title = "淵喉的力量", objective = "和克蕾雅一起進入淵喉，並在墮滅堡外面和她會面。", description = "萊索妮雅逃進淵喉，要進行她的黑暗儀式，你是唯一能追上她的人。\n\n帶上克蕾雅和我的劍，一定要阻止萊索妮雅。", progress = nil, completion = "這裡的壓迫感，就像是真的有重擔壓在我的身體上一樣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57122] = {title = "走偏的道路", objective = "釋放5個被俘虜的棄誓者。", description = "經過初步偵察後，揭露了我起初不相信的事實。\n\n淵誓者把俘虜的棄誓者關在這裡，不顧他們的意願強行轉化他們。\n\n儘管棄誓者反抗御靈者，但他們還是琪瑞安。我們有責任解救他們。", progress = nil, completion = "被御靈者放逐…被萊索妮雅辜負…\n\n他們還能去哪裡？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57123] = {title = "墮落琪瑞安", objective = "殺死15個淵誓者。", description = "淵誓琪瑞安…自從我們初次相遇以來，我只看過那個幻象。\n\n我不會膽怯。他們是昇靈堡之敵，御靈者之敵，我們有責任擊敗他們。", progress = nil, completion = "要是我的心智也被淵喉扭曲的話…請你務必要了結我。\n\n光是想就令人難以忍受。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57124] = {title = "打擊意志", objective = "到統御祭壇迎戰萊索妮雅。", description = "我感覺自己被西邊的兩座橋吸引…\n\n萊索妮雅一定在那裡。\n\n來吧，<name>。我們必須攔下她，不能再讓她逃跑。誰知道她還有什麼企圖。", progress = nil, completion = "看來…我真的是笨蛋。", rewards = "無私收集者胸鎧無私引渡者護胸無私看守者胸鎧無私熔爐士外衣您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][57125] = {title = "緬思時刻", objective = "與克蕾雅交談離開淵喉，然後返回樂土堡找軍政官阿德雷特斯。", description = "當我知道德沃絲有很強大的盟友時，我視而不見。當萊索妮雅崛起時…我的忠誠令我盲目。\n\n我有很多事要反省。\n\n我們或許不是盟友，但我有一個請求。拜託你，護送我離開這個可怕的地方。我不會插手你的事…但請不要把我留在淵喉。", progress = nil, completion = "聽到萊索妮雅再次逃過我們的追捕，真令人惋惜…她的主人現身再加上她的新力量，令人相當擔憂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57126] = {title = "…並跟著大海走。", objective = "和德瑞克‧普勞德摩爾與卡莉雅‧米奈希爾會面。", description = "我兄弟德瑞克死於第二次戰爭，但女妖之王違背了他的意願，將他從死亡後喚醒。要不是貝恩‧血蹄的英勇反抗行動，德瑞克就會被轉化成對付家族的武器。\n\n在他甦醒之後，活在折磨之中。我擔心的我們會再度失去他，但是他已經獲得了一位剛剛復活的老朋友協助，卡莉雅‧米奈希爾正在開導他，讓他從絕望邊緣走回來。\n\n我正要去拜訪他們。要不要一塊來？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57129] = {title = "智慧谷", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57131] = {title = "狩獵開始", objective = "在殘墓山丘完成狩獵儀式。", description = "在進行悔罪之狩前，還有一個步驟。\n\n你和其他獵人會先從這些靈魂吸出一縷靈魄。  這一步很容易。只要待在恐懼林地，靈魂都會釋放出靈魄的蹤跡。\n\n我們汎希爾人會利用這縷靈魄來追蹤獵物的恐懼。\n\n此外，我也想鄭重請你宣布狩獵開始。\n\n<懼獵者交給你一根靈魄樁釘和一枚中空懼蝠牙。>\n\n用這些工具完成任務。", progress = nil, completion = "做得好。或許你在死後可以成為一位傑出獵人。\n\n我幾乎可以品嚐到我們即將引發的恐懼滋味。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57136] = {title = "悔罪之狩", objective = "在殘墓山丘和懼獵者交談，並參加悔罪之狩。", description = "你會撲向這些可憐的靈魂。記住，你所施加的恐懼，就是在協助對方和瑞文崔斯，充滿恐懼的靈魂就無力造反。\n\n主宰要求你親自狩獵控罪者，不過我們先來獵殺其他目標。\n\n我可以在你的第一場狩獵提供指導。", progress = nil, completion = "做得好。我們打進去的恐懼，可以讓我們為瑞文崔斯抽出大量的靈魄。\n\n轉向我們的最後目標。", rewards = "您能選擇下列奬勵中的一個：\n\n石獸之眼戒指\n\n您還會收到：\n\n"}
