MultiLanguageQuestData['tw'][57155] = {title = "弄瞎眼睛", objective = "與派克修士交談，淨化你的「賜禮」。啊，太好了，你就是那位我想找的<class>。\n\n我還是可以從你身上感受到恩若司的影響。除非我們能夠徹底清除他的感染，否則無法從深淵之神手中取得全面勝利。\n\n經過研究，我學到一個比較沒那麼痛苦的方式來清除感染。\n\n準備好就和我談談，我們來結束這場夢魘。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "啊，太好了，你就是那位我想找的<class>。\n\n我還是可以從你身上感受到恩若司的影響。除非我們能夠徹底清除他的感染，否則無法從深淵之神手中取得全面勝利。\n\n經過研究，我學到一個比較沒那麼痛苦的方式來清除感染。\n\n準備好就和我談談，我們來結束這場夢魘。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57157] = {title = "突擊戰：黑暗帝國", objective = "在奧丹姆擊退恩若司的攻勢。", description = "就跟幻象所預言的一樣。黑暗之力想要奪取起源熔爐。\n\n必須阻止他們，要不然艾澤拉斯就會迎來末日！", progress = nil, completion = "聲音停止了。幻象讓我看見了破曉時分。\n\n多虧有你，我們今天才得以倖存。", rewards = "您會收到：\n\n黑暗帝國寶箱艾澤萊晶岩"}
MultiLanguageQuestData['tw'][57158] = {title = "電能強化", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57159] = {title = "真相的倒影", objective = "跟著控罪者穿過鏡子，並見證瑞文崔斯的真相。", description = "我派遣遠離此地的懼獵者帶著那具陷阱為我們爭取一些時間。\n\n在這面鏡子的另一邊，就是納撒亞城深處，同時是戴納瑟斯的堡壘。在那邊，戴納瑟斯正準備和他的一位僕人會面。\n\n穿過鏡子和我會合，<name>，你應該親眼看看這場「乾旱」的真實面貌。", progress = nil, completion = "我們差點就來不及了。戴納瑟斯一定會馬上尾隨我們而來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57161] = {title = "髒事換人做", objective = "為宮務大臣淨空橋樑。", description = "你聽到戴納瑟斯王說什麼了。今天，我晉升到收割者廷衛。\n\n你的運氣很好，有這個榮幸見證我的權力一飛登天。\n\n叛徒用路障擋住了面前的橋樑。為我清出一條路，我才能在不受打擾之下踏步而過。\n\n現在我手握收割者的勳章，沒有什麼能擋得住我。\n\n但我不想在這群烏合之眾身上浪費我的力量。", progress = nil, completion = "&lt;艾可隆咕噥了一聲。&gt;你來遲了。", rewards = "您能選擇下列奬勵中的一個：\n\n宮務大臣的暗晦璽戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57164] = {title = "吞噬這個", objective = "在禍孽森林中消滅吞噬者。", description = "靈魂是我們的主要目標，不過也會出現其他挑戰。\n\n有人看到吞噬者在禍孽森林到處肆虐，這種噁心的害蟲會吞噬我們賴以生存的靈魄。對任何夠格的獵人來說都算得上是挑戰，對吧？\n\n我應該感謝主宰，吞噬者只出沒在幾個與世隔絕的區域，雖然我不願意去思考，不過實際數量可能有好幾倍之多。在構成真正的威脅之前，讓我們搶先將其殲滅。", progress = nil, completion = "在你主宰恐懼之後，沒有什麼擋得住你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57171] = {title = "金枝守護者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57173] = {title = "控罪者的罪孽石", objective = "調查控罪者的罪孽石。", description = "宮務大臣滿意之後才會越過橋樑。\n\n在他抵達之前，你去取得控罪者的罪孽石。\n\n像宮務大臣那麼聰明的汎希爾會把罪孽石藏起來，這樣其他人才無法用來對付自己。\n\n控罪者太過自傲，從來不隱藏她的罪孽石。相反的，她放在一個人人都看得到的地方。\n\n為了吹噓她所克服的諸多罪孽。\n\n自豪、傲慢，還有最重要的一點，愚蠢。\n\n她的罪孽石就放在我們面前的祭壇上，似乎無人看守。把它拿下來。", progress = nil, completion = "你真的只有這點本事？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57174] = {title = "石源魔", objective = "收集靈魄牢籠，然後喚醒6個石源魔守護者。", description = "石源魔軍團根本還沒到這裡？這未免太誇張了。\n\n如果我們不快點做些什麼，叛軍就會攻陷這個骯髒的小村莊。\n\n好了，帶著靈魄，前去啟動部署在暗隱村外圍的幾個石源魔。將所剩的物資交給軍需官，告訴她做好自己的工作。\n\n我會試著聯絡主宰，看看他能否派援軍過來。", progress = nil, completion = "我們的稅收就只剩下這麼一點？稅務官可不是什麼通情達理的人。我們或許需要快點再徵一次稅，不然他就會把我們所有人流放到餘燼區。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57175] = {title = "審判官維爾海姆的罪孽石", objective = "收集3塊隱藏的罪孽石碎片。", description = "審判官維爾海姆非常謹慎地保護著自己的罪孽石。\n\n他認為只要打碎成好幾塊並藏在不為人知之處，我們就找不到他的罪孽石 。\n\n不過他的計畫和大多數人一樣，有著相同的弱點：信賴意志軟弱的爪牙。\n\n我「審問」了幾個泥掘者，得知他們幫忙審判官把罪孽石碎片藏在哪裡。\n\n找出所有碎片，然後帶來給我。", progress = nil, completion = "&lt;當艾可隆握住這枚罪孽石的碎片時，靈魄將每一塊碎片拉攏，重新聚合成一塊完整的罪孽石。&gt;\n\n準備進行下一步。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57176] = {title = "送交罪孽石", objective = "與艾可隆一塊飛行，把控罪者的罪孽石交給宮務大臣。", description = "宮務大臣正在抵抗控罪者，為我們爭取必要的時間，好打破她罪孽石上的結界。\n\n但是，都要感謝你的拖延，令我們對他的增援遲遲未到。\n\n我會收集控罪者的罪孽石，並帶著我們進入戰場。", progress = nil, completion = "老實說，這是我看過最大的罪孽石。\n\n要找出弱點一定很容易。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57177] = {title = "嶄新的開始", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57178] = {title = "謁見主宰", objective = "謁見戴納瑟斯王。", description = "淵喉行者，我是凱厄將軍。那些替主宰效命的石源魔都在我的指揮之下。\n\n從這裡到戴納瑟斯王的道路已經不是我的部隊的管轄範圍。我的部隊正準備從這個結界開拔，去別的地方供主宰驅策。\n\n戴納瑟斯王派我帶你直接去見他。請乘上秘思奇亞。", progress = "跟戴納瑟斯王說話時，記得注意你的言行舉止。他可是比你的世界還要古老的人物。", completion = "等等！請留步，淵喉行者，容我向主宰通報一下。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57179] = {title = "瑞文崔斯管理權", objective = "接受主宰的恩澤。", description = "$p，自豪的<race><class>。我知道你的名字，還有你的功績。我可以嚐到你的悔恨和你的羞愧。\n\n更重要的是，我知道你有什麼潛力。你可以成為暗影之境的信標，集結落後之人。我的人民需要一個象徵，將這些官冕堂皇的爭吵放在一邊，並出力矯正足以影響所有現實的問題。\n\n在你面前是收割者廷衛，是最忠誠、我最信賴的汎希爾。原本有7人，現在只剩4人。\n\n向他們自我介紹一下，不管他們身在何處，我的力量都會同行。", progress = nil, completion = "現在，淵喉行者，在這個國度中，以經我授意的武器之姿崛起吧。", rewards = "您會學到：\n\n靈霧繚繞\n\n下列法術會施放在您身上：\n\n召喚歹徒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57180] = {title = "控罪者的秘密", objective = "協助宮務大臣擊敗控罪者。", description = "現在控罪者的罪孽石在我手中，終於可以一口氣終止她那叛逆的行徑了！\n\n在我研讀這枚罪孽石時保護我，你的獎勵就是成為我的首席侍從。\n\n在我運用難以置信的力量擊潰她之後，我會掌控贖罪之殿，然後接受主宰的獎勵。\n\n以此功績，代表我將會擠身收割者廷衛！", progress = nil, completion = "&lt;宮務大臣帶著諷刺般的笑容。&gt;\n\n贖罪之殿現在歸我控制了。", rewards = "絕望石板您會收到：\n\n"}
MultiLanguageQuestData['tw'][57182] = {title = "控罪者的命運", objective = "騎乘秘思奇亞並把控罪者送給戴納瑟斯王。", description = "你現在的地位足以代表收割者了，淵喉行者。\n\n<宮務大臣深吸了一口氣並露出笑容。>\n\n我會用控罪者的勳章來強化我在贖罪之殿的據點。\n\n同時，主宰要求你把控罪者和他先前出借的勳章送過去。\n\n秘思奇亞馬上就會載你過去。不要讓主宰空等。", progress = "我猜，之前我借給宮務大臣的勳章在你身上？", completion = "&lt;當你把勳章遞到他手上時，戴納瑟斯王露出了笑容。&gt;\n\n知道你值得我託付如此強大的力量，讓我倍感欣慰。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57185] = {title = "職責所在", objective = "向德瑞文將軍、『霧刃』娜迪亞和倫德自我介紹。", description = "歡迎加入這次作戰，<name>，你現在站在我們這邊了。\n\n花點時間自我介紹一下。我會和德瑞文在小屋和你會面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57189] = {title = "擊破希望破除者", objective = "在掘息坑利用濃縮靈魄瓶來擊敗希望破滅者。", description = "<name>，懼獵者想必已經派獵人進入禍孽森林四下搜查我們的蹤跡。\n\n德瑞文通知我，在我們交談的當下，她手下有幾位頂尖獵人正在掃蕩掘息坑。我們可以利用這一點當做我們的優勢。殺死他們，應該足以吸引她的注意。\n\n<控罪者遞給你一組亮紅色的瓶子。>\n\n將這些東西丟向她的獵人，應該可以吸引在此地肆虐的吞噬者注意。", progress = nil, completion = "效果似乎比預期的更好。\n\n完美。懼獵者根本沒有機會。", rewards = "鋼縛尖底盾烈性精華之瓶兇惡懼刃鋒利懼刃堅實的希望破滅者細劍靈巧的希望破滅者細劍裂球釘頭錘您會收到：\n\n"}
MultiLanguageQuestData['tw'][57190] = {title = "他們連自己怎麼死的都不知道", objective = "放置8個做了手腳的靈魄容器。", description = "除非我們能逆轉情勢，否則把懼獵者引到這邊來也毫無作用。她一定會帶著一小支軍隊現身。\n\n安置這些靈魄容器。在時機成熟時，我們會把裡面的東西散播到空氣中，把濃厚的靈魄灑在他們身上。\n\n這應該可以讓盤踞此地的吞噬者撲向他們，就像飛蛾撲火一樣。", progress = nil, completion = "吞噬者會把他們撕成碎片。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57198] = {title = "責任感", objective = "竊聽珍娜‧普勞德摩爾的會談。", description = "德瑞克自由了。我有許多事情必須要向他贖罪。\n\n有傳言說，珍娜要和她的哥哥見面。\n\n去斯陀頌恩谷地的海風村吧，希望你可以在那裡打聽到…嗯，這麼說吧，我是想顧全大局。\n\n如果你發現了有意思的事，我會非常感激的。\n\n目前這件事暫時不要告訴任何人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57205] = {title = "顛跛之路", objective = "防守並佔領兩個地點", description = "這塊領地對於我們的防禦具有戰略意義，不能被這些憎惡體逼迫撤退！\n\n控制兩個在你地圖上標示的地點。防禦敵人的攻擊，直到插下旗幟、成功佔領地點為止。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57207] = {title = "萊索妮雅的計畫", objective = "面對萊索妮雅。", description = "萊索妮雅擊敗了神聖楷模，她擁有的淵喉力量太強了。\n\n我們一定要阻止她。", progress = "<謙遜楷模痛苦地抱住身體。>", completion = "我很虛弱，但我會好起來。\n\n我這裡沒有她要找的那種傲慢。", rewards = "您會收到：\n\n"}
