MultiLanguageQuestData['tw'][57380] = {title = "自取滅亡", objective = "偽造將你流放到餘燼區的正式文件。", description = "餘燼區只有爛傢伙！\n\n<岩石頭瞥了你一眼，搖搖頭。>\n\n你不像是爛傢伙！\n\n爛傢伙都會帶著罪狀！", progress = "爛傢伙身上都帶著罪狀！", completion = "這個罪狀看起來很糟…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57381] = {title = "最厲害的鬥劍士", objective = "釋放『霧刃』娜迪亞。", description = "一個凡人出現在瑞文崔斯。唉呀…你正好適合成為一場大冒險的頭領。\n\n你可以稱呼我為『霧刃』娜迪亞，不是我在吹牛，我可是有史以來最厲害的鬥劍士。\n\n我這淒慘的模樣，就是告誡人們千萬不要先收錢再辦事。救我出來，那麼，在我對你失去興趣之前，我願意暫時供你驅策。\n\n我們說定了嗎？", progress = "那神聖鋼鐵的確令人望而生畏。", completion = "太有趣了！我已經好幾百年不曾覺得這麼有活力了。你這個人實在太…與眾不同，而且充滿朝氣。\n\n我可以繼續協助你，直到你準備離開歿路沼澤為止，到時候，我們就必須暫時分道揚鑣了。我跟那個把我送進牢籠的人，還有一些帳要算。", rewards = "決鬥者大師的字據您會收到：\n\n"}
MultiLanguageQuestData['tw'][57384] = {title = "癒合中的怪物", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57386] = {title = "如果你祈求和平…", objective = "進入瑪卓薩斯。", description = "瑪卓薩斯是一塊醉心於鬥爭和衝突的土地。但他們應該要心懷榮耀。\n\n如果他們將榮耀拋諸腦後，那他們或許會把部隊推向昇靈堡。\n\n小心，在那道門後處處是危機。它是個充滿了英雄與惡徒的地方。", progress = nil, completion = "怎麼了？你為什麼沒去戰鬥？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57390] = {title = "劍下亡魂", objective = "到苦痛劇場擊敗30個對手。", description = "搞什麼？你這個失敗者！鬥士，你們家族的榮耀不見了嗎？\n\n唉，這場乾旱讓我們沒什麼選擇，看來這就是瑪卓薩斯能派出的最強人選了。\n\n還記得以前，最強的靈魂到來，然後被分配到五個家族裡…\n\n我不多說了，比賽要開始了。進入競技場，為榮耀而戰！\n\n你看起來沒辦法撐太久，你就在你最後的時間裡，盡可能打響你自己的名號吧。", progress = nil, completion = "你活下來了？真想不到…\n\n這真是出乎我的意料。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57391] = {title = "重組「石化詛咒」", objective = "為怒西昂前往心之室，從恐怖幻象取回「石化詛咒」撕下的書頁。", description = "我在研究奈奧羅薩的過程中常常需要參考這本書，它是由新進的教徒寫成，記載了「泰坦的謊言」和對艾澤拉斯居民所做的「不義之舉」。\n\n那都是瘋言瘋語，目的是讓讀者逐漸無法接受現實。\n\n不過，研讀這本書可以更了解古神的力量，並且量身訂做出更能抵抗這股力量的披風。\n\n所以請你盡可能把這本書的書頁帶來給我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n腐化核心"}
MultiLanguageQuestData['tw'][57392] = {title = "重組「石化詛咒」", objective = "為怒西昂前往心之室，從恐怖幻象取回「石化詛咒」撕下的書頁。", description = "保守地說，目前為止這本書的內容很讓人不安。但是我已經逐漸解讀出恩若斯力量本質的重要資訊，並且也根據資訊修改了你的披風。\n\n不過，我們還有很多事情得要了解，你在深入幻象的時候繼續尋找那些書頁吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n腐化核心"}
MultiLanguageQuestData['tw'][57393] = {title = "穿越黑暗", objective = "為怒西昂前往心之室，從恐怖幻象的深淵取回「恐懼血肉」。", description = "你應該已經注意到，你越是深入幻象，披風的保護能力就越弱。\n\n為了更能抵抗恩若斯的影響，我們就要更深入地了解他那邪惡的力量。\n\n繼續往幻象深處挖掘知識，這樣我們很快就能找到答案。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恐怖核心"}
MultiLanguageQuestData['tw'][57394] = {title = "重組「恐懼血肉」", objective = "為怒西昂前往心之室，從恐怖幻象的腐化區域和失落區域取回「恐懼血肉」撕下的書頁。", description = "另一本被恩若斯逼瘋的人所寫的書，我不敢想像那裡面寫著什麼惡毒的文字。\n\n不過，如果要強化你的披風，就要更了解我們得抵抗的東西。去找出剩下的書頁吧，這樣我們才能拼湊出完整的文本，讓我們更理解恩若斯的力量。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恐怖核心"}
MultiLanguageQuestData['tw'][57395] = {title = "重組「恐懼血肉」", objective = "為怒西昂前往心之室，從恐怖幻象的腐化區域和失落區域取回「恐懼血肉」撕下的書頁。", description = "古神的追隨者認定血肉是贈禮，不是詛咒。這本書也認為古神充滿慈悲，賦予我們如此慷慨的祝福。\n\n那至於讓腐化毫不受限的蔓延這件事，當然是完全沒有在書中提到。\n\n幫我收集更多書頁。即使這些文字如此令人髮指，研讀它們還是能讓你的披風效果更強。", progress = "有要分享的東西嗎？", completion = "看來你找到更多書頁了，做得好。", rewards = "您會收到：\n\n恐怖核心"}
MultiLanguageQuestData['tw'][57396] = {title = "重組「恐懼血肉」", objective = "為怒西昂前往心之室，從恐怖幻象的腐化區域和失落區域取回「恐懼血肉」撕下的書頁。", description = "古神的追隨者認定血肉是贈禮，不是詛咒。這本書也認為古神充滿慈悲，賦予我們如此慷慨的祝福。\n\n那至於讓腐化毫不受限的蔓延這件事，當然是完全沒有在書中提到。\n\n幫我收集更多書頁。即使這些文字如此令人髮指，研讀它們還是能讓你的披風效果更強。", progress = "快完成一半了，<name>。\n\n你找到任何新東西了嗎？", completion = "太棒了。我們的工作進展順利。", rewards = "您會收到：\n\n恐怖核心"}
MultiLanguageQuestData['tw'][57397] = {title = "重組「恐懼血肉」", objective = "為怒西昂前往心之室，從恐怖幻象的腐化區域和失落區域取回「恐懼血肉」撕下的書頁。", description = "在古神低語裡最陰險的部分，或許就是其中還留著最小部分的真相。那會讓你暖上心頭、如沐春風。\n\n但你已經勇敢進入了恩若斯的幻象，你看見了它們計畫的最終目的，知道血肉詛咒從來就不是什麼溫暖舒適的東西。\n\n繼續收集書頁，我們就快要拚湊出整本書了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恐怖核心"}
MultiLanguageQuestData['tw'][57398] = {title = "行走於黑暗", objective = "為怒西昂前往心之室，從恐怖幻象的失落區域取回「最終真相」。", description = "結局即將到來，這些幻象最黑暗的一面正在等待著。\n\n我們的努力付出讓你得以全副武裝，出發尋找這些幻象最恐怖的化身。最終答案就在彼方。我們為奈奧羅薩所做的準備就快要完成了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n虛誕核心"}
MultiLanguageQuestData['tw'][57399] = {title = "重組「最終真相」", objective = "為怒西昂前往心之室，從恐怖幻象的失落區域取回「最終真相」撕下的書頁。", description = "我知道這本書，它是那些古神信徒的聖典，裡面記載著虛無最深處的秘密和最艱澀的謎團。只有最虔誠的教徒能夠目睹書上的文字。\n\n即使不完整，但光是拿著它就會讓我起雞皮疙瘩。我得好好小心，不要一次研讀太多章節。\n\n儘管如此，我們還是要找到那些遺失的書頁，研究才能繼續。去恩若斯幻象中最黑暗的角落，把書頁帶回來吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n虛誕核心"}
MultiLanguageQuestData['tw'][57400] = {title = "重組「最終真相」", objective = "為怒西昂前往心之室，從恐怖幻象的失落區域取回「最終真相」撕下的書頁。", description = "我不敢把這些書頁上寫著的恐怖紀錄朗讀出來。我在閱讀這些文字的時候，它們似乎還會移動、變形，就好像要把我逼瘋一樣。\n\n這工作很費力，但如果我們要為危險的奈奧羅薩做好準備，這就是必要的工作。這過程會像書裡的敘述一樣讓人不安，而且真正開始工作以後，挑戰更會與日俱增。\n\n繼續幫我找書頁，<name>。只不過…要把研讀的工作交給我。", progress = "我們能走到這一步都是你的功勞，<name>。你有什麼想要分享的嗎？", completion = "我們的旅程就快結束了。黑暗聚集。", rewards = "您會收到：\n\n虛誕核心"}
MultiLanguageQuestData['tw'][57401] = {title = "重組「最終真相」", objective = "為怒西昂前往心之室，從恐怖幻象的失落區域取回「最終真相」撕下的書頁。", description = "我研究古神的秘密有一段時間了。我走遍艾澤拉斯找尋深奧的文本、失落的檔案和違禁的知識，都是要為即將來臨的恐懼做準備。\n\n為了這本書裡那股深不見底的瘋狂，我做了不知道多少研究和準備。這種純粹的瘋狂唯有古神語足以傳達。\n\n幫我找到這本詛咒之書最後的書頁，<name>。我要把該學的都學完，然後再也不碰這本書。", progress = "奈奧羅薩的低語包圍我們。我認為你已經準備好進行最後的任務了，對吧？", completion = "工作完成了。他們寫下了一段不斷墮落，直到完全瘋狂的故事。如何從一個謊言編到另一個謊言，直到對現實的信念產生質疑。在這裡找不到任何「真相」。\n\n你不再需要逃避那些低語了，&lt;name&gt;。你準備好讓它們沉默了。", rewards = "您會收到：\n\n虛誕核心"}
MultiLanguageQuestData['tw'][57402] = {title = "重組「石化詛咒」", objective = "為怒西昂前往心之室，從恐怖幻象取回「石化詛咒」撕下的書頁。", description = "恩若斯如此陰險狡詐，我可以預期在讀過這些文字之後，那些容易受影響的心靈會因此而轉向對抗泰坦。不過我們沒那麼容易受到操控，對吧。\n\n這本書快完成了，繼續在幻象中收集書頁吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n腐化核心"}
MultiLanguageQuestData['tw'][57403] = {title = "重組「恐懼血肉」", objective = "為怒西昂前往心之室，從恐怖幻象的腐化區域和失落區域取回「恐懼血肉」撕下的書頁。", description = "在古神低語裡最陰險的部分，或許就是其中還留著最小部分的真相。那會讓你暖上心頭、如沐春風。\n\n但你已經勇敢進入了恩若斯的幻象，你看見了它們計畫的最終目的，知道血肉詛咒從來就不是什麼溫暖舒適的東西。\n\n繼續收集書頁，我們就快要拚湊出整本書了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恐怖核心"}
MultiLanguageQuestData['tw'][57404] = {title = "劫毀蜂巢", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57405] = {title = "追逐瘋狂", objective = "查明迷失的希比兒想告訴你的事。", description = "<這個處境淒慘的汎希爾人蹣跚而行，一邊抓著地面，一邊胡言亂語。\n\n對方突然抬頭看，用手指指著你。>\n\n沒有渡船的仇敵不謹慎就不會開心！\n\n<對方似乎正在等你回應。>", progress = nil, completion = "好吧，你真是個出乎意料的客人。\n\n我手上恐怕沒有好茶招待你，失禮了，請見諒。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57414] = {title = "Mount Up Test", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57425] = {title = "機遇之地", objective = "擊敗高位勇士梅斯卡。", description = "<大師的宏亮聲音蓋過觀眾的喧譁聲。>\n\n時候到了！最後一場比賽要開始了！\n\n這兩名瑪卓薩斯的鬥士不斷地解決一個又一個挑戰者。現在剩下的最後一件事就是…\n\n挑戰殺死對方！", progress = nil, completion = "很久以前，統御者創立了這場比賽，來展示瑪卓薩斯的力量。\n\n但現在，比賽成為了一場不留餘力的全面戰爭。", rewards = "欺詐密探肩甲冷酷處刑者護肩屍體縫補師披肩血肉建構者披肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][57426] = {title = "我可怕的早晨", objective = "殺死侯爵打擊者。", description = "你絕對不會相信我遇到什麼事！\n\n侯爵打擊者和他的那群手下趁著我每天出去散步的時候襲擊我！\n\n他們做出很多糟糕又不紳士的行為，而且還毀了我的陽傘。\n\n真是有始以來最大的悲劇！\n\n沒有陽傘，我恐怕就會被詛咒這片土地的聖光燒得體無完膚。\n\n候爵的根據地就在附近，那裡聖光照射不到，令人嚮往。你可以幫我的陽傘報仇，教那群惡棍一點做人的道理嗎？", progress = nil, completion = "&lt;暴露在聖光下顯然令希奧塔無法控制自我。&gt;\n\n正義…為了陽傘…到處都是…", rewards = "牢握陽傘手套佳賓斯保養過的護手塔賓斯茶壺防燙長手套抗食屍鬼利齒之握您會收到：\n\n"}
MultiLanguageQuestData['tw'][57427] = {title = "見光死", objective = "殺死12個灰燼食屍鬼。", description = "你遇到灰燼食屍鬼了嗎？他們在地上蹣跚爬行，看到東西就撲過去，餐桌禮儀非常不及格。\n\n如果汎希爾人暴露在聖光下太久，都會迎來這淒慘的下場。無止盡的痛苦將會依序摧殘我們的意志、心靈，最後是我們的身體。\n\n其實只要做法正確，並且即時治療，就有機會逆轉聖光的傷害。\n\n不過在這個聖光肆虐的火坑中，那些灰燼食屍鬼已經沒救了，讓他們早點解脫吧。", progress = nil, completion = "&lt;暴露在聖光下顯然令希奧塔無法控制自我。&gt;\n\n我致上…最誠摯的道歉…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57428] = {title = "希奧塔的任務", objective = "收集8片燒焦的木板和8塊皇室碎布。", description = "喔，控罪者派你來的？真熱心！\n\n沒錯，我確實知道雷納瑟王子的下落…至少知道大概下落。\n\n在我們對主宰要塞的攻擊行動失敗後，雙雙被抓。我被流放到餘燼區，不過王子則是被拖去罪殞城。\n\n我計劃著要逃離這片聖光肆虐之地，繼續追隨王子，不過這裡的聖光…讓人難以思考。\n\n我原本有一把陽傘保護，不過有群惡棍毀了它。幫我修好陽傘，我們就能一起去找王子。", progress = "要是你找得到的話，我喜歡的顏色是粉色和白色。", completion = "&lt;暴露在聖光下顯然令希奧塔無法控制自我。&gt;\n\n佳賓斯…你在哪裡？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57429] = {title = "融合柴堆", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57442] = {title = "迷失於乾枯之地", objective = "找到希奧塔的藏身處。", description = "<暴露在聖光下使得希奧塔語無倫次。\n\n他沒告訴你如何前往他的藏身處，反而一直唸唸有詞，並且到處亂指。>\n\n迷失…希比…塔賓斯…茶會遲到…\n\n<你必須用別的辦法找到希奧塔的藏身處。>", progress = nil, completion = "&lt;佳賓斯與塔賓斯一搭一唱。&gt;\n\n這可不妙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57443] = {title = "苦差事：拆除小隊", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57444] = {title = "日行一善", objective = "殺死3個棄誓晉升者。", description = "<name>！你沒事，太好了。\n\n很多過去為這個地方效力的晉升者都背叛我們了。徹底摒棄琪瑞安一直以來所秉持的價值…實在無法想像。\n\n<侍僧將一把沉重的長矛放在你手中。>\n\n這是一件在今天以前看似毫無用處的工具。它的唯一用處是讓觸及的對象自我反省。這能讓他們知道自己選擇的道路是錯誤的。\n\n如果他們還是執迷不悟，那就表示他們已無可救藥，只能解決他們。", progress = nil, completion = "我見證了他們的死亡，但他們似乎罪不至此。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57445] = {title = "阿欽的拉麵推車", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57446] = {title = "敵對的舊識", objective = "面對萊索妮雅，淨化巨大禱鐘。", description = "我內心充滿驚恐。如果現在真的是萊索妮雅在率領他們…\n\n錯了。重要的是我們恢復了禱鐘。只要它們的聲音還有一絲腐化，那所有聽見鐘聲的都會和這座神殿一樣受到折磨，整個昇靈堡屈服不過是時間問題罷了。\n\n他們一定會千方百計阻止你。我會盡可能拖住他們的領袖。\n\n要是我沒能生還…我的侍徒會安全地送你離開這裡。莫忘職責。", progress = nil, completion = "我們的戰鬥尚未結束，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57447] = {title = "純潔的特權", objective = "與維希芬妮一起飛往純潔倒影。", description = "<name>，你感覺到了嗎？\n\n那隻緊抓你喉嚨的冰冷之手？那股寒意是不是在你的胸口徘徊不去？那就是淵喉之觸，如同御靈者的意志一樣千真萬確。\n\n我不知道萊索妮雅是如何得到這股力量，但我們必須盡快行動。\n\n我會將這裡發生的事告知御靈者，而你則在我無法觸及之處行動。我會邊飛邊解釋。\n\n等你準備好離開神殿，就與我交談。", progress = nil, completion = "我們今天一刻都不得閒，對吧？\n\n&lt;克蕾雅謹慎地看著碎片。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57448] = {title = "我們的新盟友", objective = "見證貝恩歡迎狐狸人加入部落。", description = "就算在和平時期，部落也是有自己的問題要處理。\n\n雖然這些問題有時會讓人喘不過氣來，但絕對不該就此阻止我們、害我們忘掉身為部落的意義。\n\n我們不該在艱難時刻拒人於千里之外。我們團結一心，堅忍不拔。\n\n而那時候，我竟然忘了這一點。在面對我們新盟友的時候，我被各方紛擾埋沒。我漫不經心地支開了狐狸人。\n\n我只希望在他們心中，部落的重要性，依舊等同於我對他們的重視程度。", progress = nil, completion = "狐狸人加入部落。這是十分務實的合作關係，你不覺得嗎？如果沒有你的協助，絕對不可能發生的。\n\n多謝你，&lt;name&gt;，我們在沙丘之外多了一個家園。", rewards = "您會收到：\n\n商隊土狼"}
MultiLanguageQuestData['tw'][57449] = {title = "恩若司執行者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57453] = {title = "喚蟲者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57454] = {title = "寂靜的菇柄之域", objective = "到菇柄之域外與寇提納留斯談話。", description = "嗯。情況…不太理想。但還不到慌張的時候！\n\n妖精之環與這裡的連結斷開已經是很久以前的事了，我們大概得前往源頭才能接回來！\n\n不幸的是，自從危機發生以來，首席蘑菇法師寇提納留斯就一直音信全無。\n\n拜託，請找到他，協助我們重新連接妖精之環！從夢歌沼地往西走，前往菇柄之域。只要跟著蘑菇走，就不會錯過。", progress = nil, completion = "總算來了個友善的面孔！你跟獵者是一起的嗎？你看起來不像這附近的人…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57455] = {title = "進擊的蘑菇", objective = "在菇柄之域使用孢子囊，在15蒙面妖精身上種植蘑菇。", description = "蘑菇遭到攻擊了！我需要你幫忙，不然我們可能會失去所有蘑菇！\n\n有一些戴著奇怪面具的妖精闖進來，要求使用蘑菇環。我告訴他們，蘑菇環因為靈魄乾旱的關係關閉了，結果他們就發動攻擊！\n\n我太弱了，無力反擊，而且也進不去蘑菇環的中心。他們大肆破壞，不過我們倒不是完全沒辦法了。\n\n拿著這些孢子，撒一些在他們的屍體上，我們就能重建蘑菇環。死了以後，我們的敵人還是要為亞登曠野做出貢獻。", progress = nil, completion = "他們的屍體會提供妖精之環成長所需的養分。他們的死亡很有價值。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57456] = {title = "飲魂者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57457] = {title = "Shaking 'Shrooms", objective = "Shake 8 Swollen Mushroom Stalks.", description = "The mushrooms in there need your help, <class>!\n\nSome of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there.\n\nIf you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57458] = {title = "修復蘑菇環", objective = "使用真菌信標修復6株受損的蘑菇。", description = "雖然這裡現在滿目瘡痍，但總有一天會恢復原貌。\n\n這裡被破壞，也導致我的主人非常虛弱，不過蘑菇是生命力很強的生物。只要提供各地的蘑菇環足夠的能量，它們就能恢復力量。\n\n拿著這個信標，對蘑菇環附近受損的蘑菇使用，親眼見證大自然如何快速治療自己的傷口。", progress = nil, completion = "團結就是力量。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57459] = {title = "為蘑菇而戰", objective = "協助寇提納留斯守護瑪拉茲莫斯。", description = "看吶，這就是瑪拉茲莫斯。\n\n這是它的家，它的心臟。生長在亞登曠野，甚至是整個暗影之境的蘑菇，都是源自這裡，而蒙面妖精卻想將這裡佔為己有。身為首席蘑菇法師，我絕不允許這種事發生。\n\n敵人看似失去心智，但他們其實非常狡猾，他們現在應該已經追蹤到我的位置了。\n\n我要在這裡背水一戰，希望瑪拉茲莫斯的力量能夠助我戰勝敵人。\n\n<class>，你願意與我並肩作戰嗎？", progress = nil, completion = "&lt;該是你出場的時候了！幸好我把那些小傢伙照顧的還不錯，對吧？&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57460] = {title = "塔賓斯的茶", objective = "協助塔賓斯沖泡特殊茶水，治療希奧塔。", description = "希奧塔教塔賓斯沖泡可驅散聖光的特殊茶水！\n\n塔賓斯泡的茶很好喝！\n\n看著塔賓斯讓希奧塔心情變好！\n\n那麼塔賓斯的心情也會變好！", progress = nil, completion = "茶泡好了！塔賓斯交給希奧塔！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57461] = {title = "平靜的散步", objective = "護送希奧塔前往癲狂聖所。", description = "希望在聖光的影響下，我沒有過於失控。我努力試著控制自己，但聖光帶來的痛苦…令人發狂。\n\n無論如何，那杯茶讓我再次清醒過來！\n\n我上次看到雷納瑟王子時，主宰正把他拖去餘燼區隱約可見的那座高塔。\n\n我和幾個人一直試著從下方進入塔內，不過遇到了一些…阻礙。\n\n等你準備好出發時，我會帶你去我們的臨時總部「癲狂聖所」。", progress = nil, completion = "&lt;希奧塔慢慢地喝了一口茶。&gt;\n\n真是一次愉快的散步！", rewards = "燼刻束腰侯爵花邊腕輪碎眼護胸光染護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][57462] = {title = "捕夢者", objective = "取得200塊瘋狂碎片。取得碎片的管道有：奈奧羅薩的首領、世界首領、打贏戰場和競技場、達成榮譽擊殺。", description = "虛無法器似乎還算穩定，聚累能量的功能依然完整。我敢說，我們還可以再進一步強化它。\n\n繼續獵殺和打敗強敵，取得更多恩若司殘留的力量。這一次，我們要把更多的古神之力灌注到法器。我有信心，它的魔法隔絕力場應該還撐得住。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n恐怖的虛無法器\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57463] = {title = "清理菌絲網", objective = "與瑪拉茲莫斯一起透過妖精之環移動，擊敗30個入侵者。", description = "<蒼老而宏亮的聲音響徹你的內心。>\n\n哼，有更多過來了。\n\n我不希望受到更多傷害，不過我也不希望你們認為我對你和寇提所做的貢獻毫無感激之情。\n\n你要不要使用妖精之環，好好教訓那些笨蛋一下？讓他們知道不該來招惹瑪拉茲莫斯和他的妖精之環！", progress = nil, completion = "哈！我已經好多年沒感到這麼活力充沛了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57464] = {title = "維持法器", objective = "取得20塊瘋狂碎片。取得碎片的管道有：奈奧羅薩的首領、世界首領、打贏戰場和競技場、達成榮譽擊殺。", description = "目前的虛無法器只有微乎其微的恩若司之力。但只要我們繼續強化它，就能製作出更有效的武器來對付恩若司。\n\n恩若司的影響無所不在，<name>，而越強大的敵人身上凝聚的腐化之力也越強。去消滅這些對手，奪取古神殘存在他們身上的力量。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n強化的虛無法器\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57465] = {title = "苦差事：木工", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57470] = {title = "惡劣的發現", objective = "跟著德哈卡前往珈爾瑪的高塔", description = "$p，跟我來吧。我可以解釋，但你自己親眼看看，會比較好理解。", progress = nil, completion = "珈爾瑪的貪婪真是沒有極限。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57471] = {title = "苦差事", objective = "將骯髒的碎石丟入爛泥池。", description = "爛泥池的情況簡直一團混亂。靈魄短缺的影響也開始在這裡發酵。\n\n你看，爛泥池需要穢物和纖維，才能有效製造出泥掘者。問題是，每次我試著處理池子的時候，該死的吞噬者就會爬到我背上！\n\n現在未經處理的爛泥開始形成這些元素生物！你可以把一些骯髒的碎石丟進池裡，讓池子恢復原狀嗎？", progress = nil, completion = "我在這裡就聞到了，&lt;name&gt;，感激不盡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57473] = {title = "貴重物品", objective = "打開華麗的箱子。", description = "這個箱子不太一樣。它比其他的大，更重要的是它上鎖了。\n\n<莫格萊尼大力把鎖敲下來。>\n\n現在，我們來看看裡面有什麼。", progress = "他們怎麼拿到那個的？", completion = "是統御者的披肩…命運今天眷顧我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57474] = {title = "泥掘者的工作", objective = "找到一個泥掘者，帶它到礫石堆旁。等它挖掘礫石堆，然後取回束縛寶石。", description = "你修好了爛泥池，所以我們可以製造一些泥掘者了，但那些吞噬者可能會一直惹麻煩。\n\n我們需要一枚束縛寶石，才能讓泥掘者變成大個兒來保護池子。\n\n我會讓你學會如何崛出一些廢棄的泥掘者，好派上用場。\n\n派它們去礫石堆挖掘，幫我們找出一枚束縛寶石，我們就可以把它們全部重塑成大個子，把這些吞噬者踢出去！", progress = "你拿到寶石了嗎？", completion = "上面沾了一點吞噬者黏液，不過沒關係。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57475] = {title = "送回披肩", objective = "回到統御者之座找德拉卡。", description = "統御者披肩…\n\n我簡直不敢相信。那東西居然在珈爾瑪手中，然後他們居然沒用來對付我們，而且我們居然還把它拿回來了。\n\n這是我們收復瑪卓薩斯的關鍵物品，得馬上把它送回統御者之座給德拉卡女爵。", progress = nil, completion = "我會再派一些斥候繼續搜，但…這…這真是我們走運。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57476] = {title = "維爾席克餵食場", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57477] = {title = "我們需要大一點的泥掘者", objective = "見證儀式。", description = "謝謝你拿到石頭，<name>。你不在的時候，我也沒閒著，又造出更多泥掘者了。\n\n現在我們只需要讓這些泥掘者進化成大個兒。", progress = "你想幹嘛？", completion = "布托斯準備好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57481] = {title = "乘著爛泥", objective = "登上布托斯，鎮壓入侵的吞噬者。", description = "布托斯準備好拍碎扁吞噬者的頭顱了。\n\n坐上去。", progress = nil, completion = "幹得太好了，&lt;name&gt;。\n\n大個兒有點太犯規了…有時候啦。", rewards = "硬化戰靴震擊鍊靴氣流薄靴遨翔足靴您會學到：\n\n泥掘者堆肥綱要101\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57484] = {title = "喚醒儀式", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57486] = {title = "衰竭的能量", objective = "在普勞德摩爾城堡和凱爾希‧鋼火會面。", description = "梅卡托克救生艙的動力正在下降。\n\n我們已經無法聽見他有沒有在講話。\n\n就算庫爾提拉斯的治療師全力施救，他的脈膊也還是開始趨緩。\n\n我有個點子，但我需要你的協助。\n\n到普勞德摩爾城堡和我會面。我們得馬上動身。", progress = nil, completion = "我們準備要做的事好像…呃…沒有獲得批准。\n\n我們晚點再來懇求原諒好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57487] = {title = "尋找幫手", objective = "協助凱爾希將梅卡托克的救生艙運送到機械岡。", description = "我認為有一個方式可以幫助梅卡托克，但有些人可能會無法接受…\n\n機械地精擁有最先進的生化機械修補與改良的技術。\n\n哪怕只有一點點的機會可以幫助他，我們也要試試看！在勾角地的港口，有一些機械地精正準備把補給品送去島上。沒有人會注意多了一箱貨物。我們只需要偷改其中一架旋翼機的飛行路線。\n\n你願意幫我把梅卡托克的救生艙送到機械岡嗎？", progress = nil, completion = "能夠協助地位崇高的大工匠梅卡托克，是我的榮幸！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57488] = {title = "初步的計畫", objective = "收集4份耐熱軟泥和6塊獲得的機械零件。", description = "我想我可以修改一個現有裝置，用它去接觸傑爾賓‧梅卡托克，同時不會干擾到他的生命維持功能。\n\n我需要你幫我取得一些物品。\n\n你可以在垃圾場附近的區域找到廢料機器人和廢料獵犬。這些是備用零件的上好來源，可供我的建造計畫使用。\n\n排水區是一些超級黏答答朋友的家園。我們目前需要耐熱潤滑劑，它們身上的黏液正好可以作為這種用途。", progress = "找到所有材料了嗎？", completion = "好極了，這些材料很合用。\n\n做得非常好，&lt;name&gt;！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57490] = {title = "駛向安全之處", objective = "擊敗拾荒的穴居怪，並取回梅卡托克的救生艙。", description = "我們有衛兵看到穴居怪擊落攜帶著梅卡托克救生艙的旋翼機。\n\n自從我們開始從提拉加德進口貨物後，他們一直都是我們背後的芒刺。\n\n匹斯頓是位前景看好的年輕發明家，他有一台車輛可以應付這個工作。到邦多的機械場和他的團隊會合。\n\n請快點把救生艙帶回來！如果他們硬把救生艙撬開，我不知道傑爾賓會出什麼事。\n\n然後…既然你要過去那邊，我們不會介意你順道做點「淨灘」活動的。", progress = nil, completion = "希望裡面那位可憐的傢伙沒被搖到暈頭轉向。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57491] = {title = "更好…更強…更少傷亡", objective = "從乖僻的單位身上收集神經加速器、全電磁強化器和流體動能伺服馬達。", description = "雖然機械崗國王瘋了，他的手下在機械方面的發明也還是無人能及。\n\n在機械岡還有幾個殘存的創作物，不願接受機械岡國王退位的消息。\n\n在正常的情況下，戰敗後的邏輯結論應該是要撤退。但有些人的邏輯不怎麼樣。\n\n他們目前配備著最先進的科技成果。我相信，只要從這些單位身上取得特定組件，就可以讓我們重建的工程事半功倍。", progress = "你拿到我們需要的零件了嗎？", completion = "幾乎連刮痕都看不到！\n\n你知道嗎？裝幾個升級物品就可以為自己省下一半的時間。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57492] = {title = "是他？", objective = "在機械岡從地精和機械地精身上收集資訊。", description = "在機械岡和一些地精談談，不管是否經過改造的都行。問問我的人民，看他們對自己族類的領袖有什麼期望。問問我們的新朋友，對他們目前的領袖最欣賞的特質是什麼。\n\n據我所知，大工匠之所以領導人民是基於必要性，他本人從來就不想要那個王位。但我認為，地精應該再次統一。\n\n我正在尋找一個經得起重重考驗的解決方案。你能幫我收集需要的資訊嗎？", progress = nil, completion = "太好了、太好了！很符合我期望的結果。你強化了我的理論。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57493] = {title = "心理調整", objective = "在克利斯蒂下令時啟動同步儀。", description = "我們現在對梅卡托克這個人有了基本的瞭解，看起來他還有一些改進的空間。\n\n但在讓他離開救生艙之前，我們還需要你的協助才能讓他穩定下來，以及進行同步。\n\n請到同步儀旁邊就位。我會進行一些調整，當我下令時你就得啟動機器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57494] = {title = "堅強的心", objective = "取回電火反應爐並完成梅卡托克的程序。", description = "我們在廢瓦據點附近看到一枚照明彈。\n\n回收小組已經取得動力源，而且我們再也不用擔心機械岡國王的殲滅爆彈了！它的核心將獲得全新的用途。\n\n這真是天大的好消息！\n\n不過，那枚照明彈也表示他們後有追兵，需要你的協助來擺脫敵人，並且帶回電火反應爐。\n\n請快一點，我們只差臨門一腳了。", progress = nil, completion = "我十分滿意。\n\n在40%的成功機率下，原本我並不確定所有的變數是否能產生我們想要的結果。\n\n這是一大串的幸運累積的結果。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57495] = {title = "機械岡的未來", objective = "前往機械岡城的至尊技工坊。", description = "如今機械岡城已經清除掉剩餘的威脅，它又回復成以前那個地精與機械地精可以和平共存的繁榮之地了。\n\n是時候跟伊拉敏王子談談有關我們人民未來的事情了。我誠心希望我們可以締結同盟，並且一直維持這樣的關係！\n\n等你準備好之後，就來至尊技工坊參加特別會議吧。", progress = nil, completion = "今天對地精和機械地精來說，都是個充滿榮耀的日子！沒有你我們是辦不到的，&lt;name&gt;！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57496] = {title = "晉升", objective = "清理殘存的機械岡衛兵。", description = "我們必須以善行回報機械地精為我們付出的一切努力。\n\n讓我們清理殘留在機械岡的危險創作物。\n\n奪回他們的家園後，伊拉敏王子和他的人民才能踏上光明前程。\n\n有了各位這樣的隊伍，我們一定可以快速整頓機械岡國王剩下的忠誠者。\n\n在你準備出發時告訴我一聲！", progress = nil, completion = "真是太刺激了！\n\n這個世界變得更巨大遼闊了，朋友！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57497] = {title = "發佈消息", objective = "到暴風城向艾莎‧雲詠報告最新消息。", description = "原本我們只是要拯救一條性命，而最後的成果卻遠不只如此！\n\n少了你，我們真的辦不到，<name>。能夠看到所有地精共組未來，真是讓人太開心了。\n\n回到暴風城，把這個好消息散播出去！", progress = nil, completion = "出色的成果，&lt;name&gt;！\n\n我會把你的好消息轉告給聯盟的所有領袖。\n\n期待能夠多收集到一些新玩具…", rewards = "您會收到：\n\n機械岡機械陸行鳥"}
MultiLanguageQuestData['tw'][57506] = {title = "消逝的光輝", objective = "到淵喉內尋找琪瑞安志士，將他們的靈魂帶回樂土堡。", description = "有些志士天真地以為他們能夠進入淵喉，讓那個黑暗深淵有所改變。\n\n不幸的是，他們錯估了情勢，進入淵喉就意味著永無止盡的詛咒。\n\n但你是例外。\n\n請調查他們的下落，如果你能找到他們，他們的靈魂或許能再一次得到自由。", progress = nil, completion = nil, rewards = nil}
