MultiLanguageQuestData['tw'][57524] = {title = "存取檔案", objective = "與母親大人交談以啟動泰坦研究資料庫，然後檢視檔案。", description = "你收集到的資訊讓我們更加瞭解這些化身。\n\n我認為母親大人正等著跟你分享一些發現。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n檔案研究資料庫\n\n您還會收到：\n\n聚合幻象"}
MultiLanguageQuestData['tw'][57529] = {title = "花園動盪", objective = "和息痛花園下坡處的柔希梅交談。", description = "請原諒我無法起身。我不想要打擾到這些生物。\n\n如果你想要幫助昇靈堡的生物的話，柔希梅那裡需要幫手協助奪回我們的花園。順著這條路繼續走就可以找到她了。\n\n莫忘職責。", progress = nil, completion = "噢，你是來幫忙的嗎？太好了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57530] = {title = "珈爾瑪的高塔", objective = "搜索珈爾瑪的高塔。", description = "珈爾瑪會收集任何他覺得有力量的物品。\n\n我們要搜索這座高塔。那裡一定有我們能利用的東西。", progress = nil, completion = "那一定是重要的東西。我們打開看看吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57531] = {title = "不幸的處境", objective = "擊敗柯斯塔，取回勞倫特的行囊。", description = "勞倫特，主宰的鏡子製作者。很高興見到你。我現在衣冠不整，還請見諒。我發現自己似乎陷入最不幸的處境。\n\n我本來打算代表王室出差，結果我的鏡子居然把我送到這片荒地。\n\n我才剛到不久，一群流亡者就從我背後撕破我的衣服，導致我根本無法離開這個不毛之地。\n\n助我一臂之力，我會努力製作鏡子，讓我們逃離這個該死的地方。", progress = "你拿回我的行囊了嗎？", completion = "就這樣？你確定沒漏掉嗎？", rewards = "石鑄巨腰帶痛苦赦免之索獵魂者繫腰夜幕腰索您會收到：\n\n"}
MultiLanguageQuestData['tw'][57532] = {title = "尋覓碎片", objective = "跟隨勞倫特並收集鏡子碎片。", description = "原諒我，我並不想一副不知感恩的模樣，不過我的鏡子碎片不見了。\n\n其實我不該這麼大驚小怪，那些碎片的力量極為強大，這裡的惡棍一定對它們愛不釋手。\n\n但是，我不會就這樣放棄。\n\n主宰派他的石頭僕役把這一區的鏡子全部砸碎，我們應該能在附近找到不少碎片。", progress = "希夢恩不該出現在這裡！", completion = "這一定是出了什麼差錯！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57533] = {title = "聖光之罰", objective = "解救5個皮膚起泡的流亡者。", description = "我們被流放到這裡的理由各有不同，只是到了這裡，我們都只有一個目標，那就是不讓自己灰飛煙滅。\n\n隱蔽者控制了聖光照耀不到的區域，擅自闖入他們堡壘的人，都會受到懲罰。我們的身體嚴重燙傷，冒出水泡，但我們卻死不了，無以復加的痛苦讓我們漸漸陷入瘋狂。\n\n我不會宣稱自己知道那些困在聖光中的人犯了什麼罪，但我知道這裡不是淵喉，懲罰並不是我們的職責。\n\n既然你救了我，還請順手救救其他人。", progress = nil, completion = "你解救他們了，對嗎？希望他們能找到聖光照耀不到的地方，稍作喘息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57534] = {title = "轉瞬成灰", objective = "殺死10個灰燼劫毀者。", description = "流亡者真的都會落到這種下場？把他們丟在這裡燒成灰燼？\n\n主宰怎麼能允許這種事？太殘酷了。根本冷血無情。\n\n沒有任何汎希爾人會想以這種姿態活著。\n\n你必須了結他們的痛苦。", progress = nil, completion = "到現在才看清戴納瑟斯王的真面目，對自己的子民做出這種事的人，根本不值得追隨。", rewards = "痛苦赦免束腕石鑄腕甲獵魂者腕甲夜幕護腕您能選擇下列奬勵中的一個：\n\n餘燼灼燒指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57535] = {title = "逃離主宰的魔掌", objective = "收集10枚鏡子碎片。", description = "我從沒這麼想逃離這個地方，不過在看到這裡發生的事後，我已經無法再為主宰效力了。\n\n希夢恩和我討論好了，在你的協助下，我會製作一面鏡子，通往王子掌控的聖所。我們會離開這個地方，發誓效忠雷納瑟。\n\n首先，我需要鏡子的碎片。隱蔽者似乎有不少碎片，而且沒有碎片，他們就無法設陷阱，也是好事一樁。", progress = "你收集到碎片了嗎？", completion = "&lt;勞倫特很仔細地檢查了碎片，才開口說話。&gt;\n\n很好，我確定這些可以用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57536] = {title = "打造鏡子，而非打破鏡子", objective = "守護勞倫特和希夢恩，阻擋石源魔軍團的攻擊者。", description = "戴納瑟斯不允許在餘燼區設置鏡子，他的石頭僕役會把反光的東西全都砸個粉碎。\n\n在我製作鏡子的時候，我需要你保持警戒，主宰的爪牙絕對會試圖阻止我們。\n\n準備好了嗎？", progress = nil, completion = "希夢恩說得對，我們可沒時間閒聊。至少現在沒有。\n\n我們修復的鏡子會送你去安全的地方。", rewards = "漫溢的燼火之鏡您能選擇下列奬勵中的一個：\n\n滿盈餘燼裂片\n\n您還會學到：\n\n失傳的鏡子工藝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57537] = {title = "掩蓋我們的行蹤", objective = "與德拉卡騎乘坐騎前往天選者家族領地。", description = "我隸屬於天選者家族。我們在南方有座要塞，那裡應該很安全。\n\n我們騎乘飛行坐騎走完剩下的路程，等你準備好了，就走到我的殘翼獸身邊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57538] = {title = "擾亂安寧", objective = "殺死10個渴求靈魄的生物。", description = "靈魄乾旱不只讓琪瑞安族受苦。連昇靈堡的野生動物也受到波及！\n\n許多生物出現攻擊性，變得很兇猛，尤其是龍鰻和雲羽鷹。牠們開始獵殺其他野生動物，而且已經無藥可救。\n\n必須要有人清除掉花園裡面那些飢餓的生物，我們才能繼續在這裡冥想。如果我們無法冥想，缺乏靈魄的困境會變得更糟！", progress = nil, completion = "我們現在可以好好盡責了，我很希望能繼續冥想。謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57540] = {title = "崑蟲孵化器", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57541] = {title = "虛無的呼喚", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
