MultiLanguageQuestData['tw'][57568] = {title = "愛之深責之切", objective = "從凱拉的巢穴裡取回可琳娜的舒緩杖。", description = "我的天啊！凱拉帶著舒緩杖飛走了！\n\n我看到她飛往西邊的巢穴去了。我要先警告你，她在巢穴裡面的時候，防衛心特別強烈。請務必小心，不用刻意溫柔對待她，她很耐打的。\n\n帶著她的玩具球吧，她最喜歡這個東西，或許可以用來引開她的注意力。", progress = "你拿到舒緩杖了嗎？", completion = "有了舒緩杖和可琳娜的指引，我就能讓這裡暫時恢復往日的生機。謝謝你，&lt;name&gt;。", rewards = "英勇志士手套審判志士護手純潔志士手套謙恭志士護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][57571] = {title = "移動鏡子", objective = "改變鏡子碎片的方向，救出希夢恩。", description = "這到底是什麼可怕的陷阱？聖光居然直接反射到她身上！\n\n希夢恩是我非常要好的朋友！把她從那東西上面放下來，拜託！", progress = nil, completion = "戴納瑟斯或許不是放置鏡子的人，但我會出現在這裡，全都是他的錯。\n\n他會把他認為可疑的人送來這裡受苦，就算是我這種忠心的僕人也不例外。", rewards = "您會收到：\n\n"}
