MultiLanguageQuestData['tw'][57771] = {title = "不請自來的入侵", objective = "從12個石崗哨石源魔身上吸取靈魄。然後，為城鎮中央的靈魄之井補充靈魄。", description = "稅務官派遣他的石源魔從這些市民身上進一步收割靈魄。這種事情已經持續多久了？這些舉止散發著深不見底的貪婪。\n\n這種兩難局面只有一個解決方案：送出訊息。碾碎這些鎮壓者。汲取他們的靈魄，並送回石崗哨的靈魄之井。\n\n不但解決侵略行為，還能鼓舞被蹂躪的靈魂。一石二鳥。\n\n<德拉卡把一個靈魄容器交到你手中。>\n\n把這拿去。我之前從另一位守衛手中偷來的。", progress = nil, completion = "化石為礫。\n\n做得好。", rewards = "您會收到：\n\n收稅人的容器"}
MultiLanguageQuestData['tw'][57772] = {title = "尖牙與士氣", objective = "以雷納瑟王子的敕令來鼓舞8個石崗哨居民。", description = "石崗哨居民被稅務官的貪婪壓榨到什麼油水都沒剩。\n\n雖然有些人拿起武器反抗這些不義之舉，大多數人只有被蹂躪的份。我們需要把拉攏他們才能把他拉下台。\n\n<雷納瑟王子交給你一個沉重的卷軸，裡面的靈魄滿到滴出來。>\n\n去吧，讓他們看看鎮壓者的偽善！用庇護所的保證，引導他們來我身邊。", progress = nil, completion = "有更多人願意加入起義的行列。他們可以獲知真相。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57773] = {title = "關閉裂口", objective = "在奧丹姆尋找並關閉3道虛無裂口。", description = "我方戰士在四周的叢林中目睹到汙穢的形體從好幾道虛無裂口裡出現。\n\n它們羸弱不堪，顯然是想在正規部隊抵達之前，試探我方的防禦。\n\n不過，如果我們對這樣的威脅置之不理，那麼被他們那群砲灰淹沒也只是時間早晚的問題。\n\n找個方法，關閉那些傳送門！", progress = nil, completion = "那應該…暫時足以擋住這波浪潮。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][57774] = {title = "九命怪貓", objective = "消滅8位奈斐賽特居民。", description = "最近回來的斥候個個氣若游絲，帶著讓我頗為…不安的報告。\n\n有人在城市南方的街道上，看到四處徘徊的奈斐賽特。\n\n這通常沒什麼好緊張的，只不過，奈斐賽特早在先前就徹底滅絕了才對。\n\n我必須請你進一步調查此事…如果這些報告所描述的邪惡魔法確實存在，你必須盡你所能阻止這樣的威脅！", progress = nil, completion = "我不敢相信我聽到的事…\n\n這真的比我擔心的還糟。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][57778] = {title = "瑪卓薩斯任務", objective = "去努拉齊爾和低語者維恩碰面。", description = "我們不可能奢望在沒有亡城的情況下，就守住統御者之座。卡莉克回報說，瓦許已經準備展開她的計畫。\n\n到努拉齊爾找她和蛛眼家族的其他人。做你該做的事吧。", progress = nil, completion = "很高興看見你回來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57787] = {title = "追尋道路", objective = "繼續沿著路走，前往特那瓦勒。", description = "這片樹林的工作大致上告一段落了。月莓女士說她會在特那瓦勒和你會面。跟著路走就在前面一點而已。我先飛過去，讓所有人知道你的到來。\n\n只要沿著路走，你就不會被吃掉。大概吧。待會見！", progress = nil, completion = "羽光說你信守承諾。真是太好了。\n\n我有好消息！我們可能可以在女王抵達特那瓦勒的時候安排讓你覲見。是不是很棒啊？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57816] = {title = "織夢者", objective = "到靜謐水塘與織夢者交談。", description = "特那瓦勒迴盪著不安的風。樹枝因為女王即將到來而顫抖不安。我們必須調整好。\n\n織夢者的翅膀因為擔憂而垂下。他照顧的野性種子中也有混沌的能量在渦旋。\n\n安撫林地水域的不安躁動、讓這裡恢復和諧。也讓織夢者重新展翅。", progress = nil, completion = "你是新來的，對吧？不是妖精，不是靈魂，也不是準備寄宿於野性種子之人。\n\n樹林長派你來這裡幫我？這樣啊，事情發展真是太有意思了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57818] = {title = "蛹不浪費", objective = "撿起耗盡的野性種子，將它放入小果姆飼育區，誘導小果姆吃掉它。", description = "小果姆是非常勤勞的生物，我們的果姆礦質通常是從牠們身上取得。\n\n小果姆小巧可愛，食量卻很大，就像這裡的咕嚕寶！不過他現在還不餓，因為我才剛剛餵過他。看看那個小肚子…\n\n<咳咳>。我離題了。\n\n只要誘導一下，小果姆就會食用未充滿靈魄的任何東西。牠們認為那非常美味。\n\n拿著那裡的野性種子，把它放入牠們的飼育區。看看你能不能讓小果姆吃掉它！", progress = "你餵那些小果姆了嗎？", completion = "做得好！\n\n有時候，小果姆很容易就會分心，不過牠們還是很有用處的小生物。\n\n不過僅限於牠們小時候。\n\n大果姆就不是這麼一回事。不過別擔心！我敢肯定我們不用對上大的傢伙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57824] = {title = "採集日", objective = "對著咕嚕寶使用馴牧果姆杖，然後從吃飽的小果姆的身上收集果姆礦質。", description = "現在我們可以幫守護者寇達收集果姆礦質了！\n\n只要小果姆吃了東西，我們就能「鼓勵」牠們…還回來。牠們還來的東西，就稱為果姆礦質！\n\n馴牧果姆杖應該可以在安全的情況下，鼓勵牠們吐出來。\n\n去吧，先在可愛的咕嚕寶身上試試。\n\n我擔心的是其他小果姆會有什麼反應。牠們最近的行為太奇怪了！", progress = "我很好奇，要是我讓馴牧果姆杖超載，會發生什麼事…會不會更有效率呢？還是會讓東西爆炸？\n\n…爆炸的機率大概比較大。", completion = "喔，事情不太對勁！小果姆應該要恢復到正常、可愛又嬌小的樣子。\n\n以女王之名啊，牠們出了什麼事？\n\n而且沒辦法拿到更多果姆礦質給寇達了！這樣完全不行啊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57825] = {title = "守護者寇達的快遞", objective = "到特那瓦勒將果姆礦質交給守護者寇達。\n\n已提供物品：\n", description = "這真的讓人太不安了。現在果姆變得太…狂暴了！\n\n我在想，是不是因為靈魄乾旱的關係，導致牠們看到什麼就吃。\n\n而且這些果姆礦質也不夠，我不想讓寇達失望…\n\n不過，我也不想讓你在收集礦質上遇到更多麻煩。我決定自己進入附近的地穴，看看能不能幫她找到更多礦質。\n\n幫我把這些果姆礦質交給她，好嗎？", progress = nil, completion = "沙洛大師自己跑去地穴，打算收集更多果姆礦質？\n\n…為了我？\n\n那個莽撞的粗角希瓦爾！他會害死自己啊！", rewards = "您能選擇下列奬勵中的一個：\n\n果姆礦質頸甲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57850] = {title = "傳奇夥伴", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章"}
