MultiLanguageQuestData['tw'][57853] = {title = "猛戰精兵小隊", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n榮譽獎章"}
MultiLanguageQuestData['tw'][57860] = {title = "如何成為棄誓者", objective = "在卡莉歐普之眠收集3個棄誓者制服組件及1個軍需官徽記。", description = "棄誓者佔據了卡莉歐普之眠，正在掠奪那裡的古物。他們一定是在尋找卡莉歐普之矛，那是一個具有強大力量的聖物。\n\n他們數量實在是太多了，我們根本不是他們的對手。說不定還有其他辦法？\n\n有一小群志士正在搬運神殿裡的神器。如果你能從他們身上收集到制服以及軍需官徽記，我們就可以讓你偷偷混入神殿。", progress = "你拿到偽裝需要的所有東西了嗎？", completion = "你對這個裝甲做了什麼好事？看來你是個粗魯，但有效率的鬥士啊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57861] = {title = "保持自然就對了", objective = "在卡莉歐普之眠深處找到工藝師莉吉埃雅。", description = "有了這個偽裝，你就可以混進去了。裡面…有個我認識的棄誓者工藝師，她應該能幫上忙。不過，你必須得到她的信任。\n\n最重要的是，你必須趕在棄誓者之前，搶先取得卡莉歐普之矛。雖然神殿戒備森嚴，但他們遲早會找到它。\n\n其實我有點罪惡感。很多志士原本都是我的朋友。那些日子早已不再。", progress = nil, completion = "怎麼了？不要在那邊閒晃。\n\n喔，是你…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57865] = {title = "迴盪千古的智慧", objective = "找到長者關娜、長者芬楠和格魯恩科魯克。", description = "嗯。即使我想給她武器，我也力不從心，因為我們的林地正遭受攻擊！\n\n在生長工坊的那起攻擊事件中，我的族人大多數都被迫離開了，但是有幾位長者留了下來。不知道他們是想要拖住敵人，還是想要確保朋友的安全，總之他們不在這個安全的地方。\n\n每位長者都擁有相當精湛的技藝，只要一眨眼的工夫就能夠製作出武器。拯救那些長者，之後再來談要如何借助他們的長才幫助亞登曠野。", progress = nil, completion = "太好了！真高興你及時找到他們。在他們上工之前，我們必須先把威脅處理掉，這樣他們才能放心繼續打造東西。我相信蘇兒珈會諒解的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57866] = {title = "無法抽身", objective = "在生長工坊殺死12個脆樹皮入侵者。", description = "如果你想要得到我的幫助，就得先助我一臂之力。\n\n有一群木魈襲擊了東北方的生長工坊。他們在那裡大搞破壞，我可不會放任這些入侵者在我的領地裡撒野。\n\n去給他們一點教訓。如果他們不肯走，就把他們就地處決！", progress = nil, completion = "很好。強者生存是大自然的法則。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57867] = {title = "眉毛上的汗珠", objective = "解除6個受詛咒的工具。", description = "啊，是外來者！這種任務正適合由你來做。\n\n木魈是出了名的調皮搗蛋。他們在我們的工具和補給品下詛咒，還困住了沒有戒心的工人。\n\n但他們跟我們一樣，下詛咒都必須遵守規則。你需要閃塵來處理籃子、輕絲線來處理豎琴，還有薄荷清新好口氣來處理捕魂網。還真奇特！\n\n祝你好運！你處理好之後，記得跟懸瀑女士說一聲。她聽到消息一定會很開心的！", progress = nil, completion = "受詛咒的工具？你把它們帶回來了？噢詛咒被解除了？不得不說，我真沒想到你可以做得這麼漂亮。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57868] = {title = "工匠不需要工具", objective = "找到芬楠的好運槌。", description = "噢，我很好！只是有件小事…\n\n有個怪物把我的好運槌給奪走了！我不能丟下我的好運槌不管。雖然我幾乎沒怎麼在用它了，但是它能帶給我好運，所以我總是帶在身邊。\n\n拜託，沒有它我都不知道怎麼打造東西了。請幫我注意看看它的蹤影，好嗎？", progress = "它很小一個，而且充滿幸運。你看到的時候一定認得出來。", completion = "噢，你找到它了！好幸運呀，我就說吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57869] = {title = "收集能量", objective = "收集6個河水累積器。", description = "你跟其他人不一樣。\n\n這裡的水攜帶著深層的能量。那是被大多數人遺忘的能量。但是木靈還記得。\n\n能量在大地之中流動，就像水跟能量一起流動一樣。我們可以暫時捕捉這種流動，化成水滴。一滴一滴地慢慢滴入容器當中。\n\n尋找瀑布底下的容器。汲取能量。", progress = "滴滴滴，瀑布由此累積。答答答，能量逐漸積聚。這就是大地的能量。", completion = "有好多能量在流竄。我們只要最小的一部分就夠了。我很滿意你的表現。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57870] = {title = "來玩遊戲吧", objective = "用表情回答愛玩的欺詐者的謎題，藉此贏得鬥智競賽。", description = "別擔心我。現在有更大的麻煩。\n\n在那波攻擊中，我聽說他們的首領就在附近。我一直在這裡監視著，但還沒有看到他們的蹤影。他們一定是使用了某種魔法來隱藏行蹤。\n\n我還沒看過不喜歡玩遊戲的木魈。如果你看到想要玩遊戲的妖精，而且有把握能贏的話，或許可以趁機了解他們的首領。", progress = nil, completion = "真是有意思。這應該相當有用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57871] = {title = "技高一籌", objective = "擊敗邪惡的沃特。", description = "現在我們可以擊倒他們的首領了，朋友。\n\n我身邊剛好有一大袋噴嚏花粉。你把它拿去瀑布頂端的工坊那裡，然後在附近的地板上撒一點這種粉末吧。如果他們還死賴著不走，應該就會招致…很不幸的後果。\n\n與此同時，我會召集其他長者，並前往爍瀑盆地。在完成任務之後，記得去跟女士交談。", progress = nil, completion = "啊，英雄回來了！謝謝你解救了我的補給品。在現在這種嚴峻的時期，我們的林地非常需要這些東西。", rewards = "靈魂篩選者根鬚喚醒者蕨葉您會收到：\n\n"}
MultiLanguageQuestData['tw'][57872] = {title = "Bring More Friends!", objective = "Locate Roriel.This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.您會收到：\n\n完成任務後，你將獲得：\n\n", description = "This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57873] = {title = "奧爾希斯的消息", objective = "調查奧爾希斯的狀況。", description = "如你所見，<name>，我們光是應付這些噁心的蟲子就忙不過來了。\n\n我們從南方過來的商隊一直沒能抵達，最近也從勉強抵達此地的人口中，聽到了令人不安的報告。\n\n我已經派出巡邏隊前往奧爾希斯調查，但他們早該回來了。\n\n能不能請你去探查一下情況？", progress = nil, completion = "就算太陽沒把我烤焦，蟲子也不會放過我。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57875] = {title = "謙遜印記", objective = "在卡莉歐普第一大廳取得謙遜印記。", description = "軍需官，你來了。\n\n那些蠢貨連第一道屏障都還沒突破。我們必須進入那個洞穴，才有可能拿到卡莉歐普之矛。\n\n我們的研究發現了一句話：「唯有謙遜之人方能尋得道路。即便英雄人物亦受美德感召。」但是那些蠢貨光是那個線索就摸索了好多年。\n\n去看看問題出在哪裡，然後趕快進去那個洞穴！我們需要印記才能打開最後一個寶庫。", progress = "你有拿到印記嗎？", completion = "做得好，軍需官。卡莉歐普之矛就快要到手了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57876] = {title = "開始的結束", objective = "與奧睿博司中的「審斷者之聲」塔因納拉交談。", description = "<雷納瑟很勉強才有辦法開口講話，傷勢多重非常明顯。>\n\n我早知道戴納瑟斯在貯藏靈魄，但這…這已經超乎想像了。\n\n閻獄之主一定會用這股力量來打碎他的束縛。萬一他從淵喉脫身，每一個死亡國度都會覆滅。\n\n我們一定要繼續對戴納瑟斯施壓。不過，我們獨力作戰的勝機渺茫。\n\n和德瑞文一塊回到奧睿博司，並和「榮耀之聲」塔因納拉交談。把你今天的所見所聞告訴她，並懇請她展開行動", progress = nil, completion = "我們感受到，發生了一些可怕的事情。快點，把一切都告訴我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57877] = {title = "朦朧的黑暗", objective = "揭露閻獄之主的計畫。", description = "能看到你從瑞文崔斯平安歸來真好，<name>。我們感受到一場叛變已經讓無限的命運絲線產生飄移。\n\n淵喉的力量逐漸增長，我們一定要找出原因。", progress = "你負責帶來這個消息，就必定要承擔它的重擔。", completion = "你做得很好。希望你能持續努力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57878] = {title = "選擇你的使命", objective = "和誓盟交談。決定你的未來如何與使命交會。", description = "每個誓盟對暗影之境都很重要。他們之間經常有所爭執，不過這也是使命的一環。\n\n所有誓盟都需要成長，才能面對閻獄之主的威脅。但你不能分頭效力，只能專注在一條路徑上。其他凡人有可能採取不同的選擇。\n\n你選邊站的時刻到了。\n\n和你的盟友交談。然後在我面前的暗影之境地圖做出你的選擇。", progress = nil, completion = "一切都如預期。永遠信賴審斷者的計畫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57880] = {title = "舊城門內的莊園", objective = "將希奧塔的便條交給舊城門內的波格丹。", description = "我應該知道如何在不樹立新敵人的情況下，順利拿到女伯爵的勳章。\n\n在被驅趕到聖光底下之前，我曾是女伯爵宮廷中位高權重的侍臣。她賜予我一間莊園，裡面有辦法直接連通她的私人房間。\n\n如果這間莊園還在，你就能藉此溜進女伯爵的莊園，在不見血的情況下偷走勳章。\n\n把這張紙條交給我最信賴的管家波格丹。他會盡全力協助你。", progress = "這是什麼？公爵寫的紙條？", completion = "&lt;波格丹迅速讀完紙條的內容，他的眼淚奪眶而出，臉上卻露出微笑。&gt;\n\n公爵還活著？真是天大的好消息！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57881] = {title = "重建的關鍵", objective = "到舊城門內從雷德拉夫的幫傭身上拿回華麗的鑰匙。", description = "如果要重開莊園，就必須先拿到鑰匙！\n\n在希奧塔被放逐到餘燼區時，他失去了所有頭銜和財產，這意味著那間莊園已經落入另一個貴族手裡。\n\n新主人的身分成謎，不過莊園的幫傭到舊城門內辦事時，身上幾乎都會帶著鑰匙。\n\n拿回鑰匙，我們就能開始著手重建莊園。", progress = "你拿回鑰匙了嗎？", completion = "啊，就是這把！我們現在應該可以順利進入莊園了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57882] = {title = "重建莊園", objective = "將聘用書交給杜米塔、艾琳娜和弗洛林。", description = "不幸的是，莊園的所有權轉手後，所有的幫傭都被遣散，被迫另尋出路。在我們當中，有些人順利在不錯的莊園找到適合的工作。畢竟人人都需要酒侍！\n\n其他人就沒那麼幸運了。他們還在舊城門這裡，打零工混口飯吃。只要他們知道我們在重建莊園，一定都會迫不及待地想回來為公爵工作。\n\n找出他們，送上這份聘用書。", progress = nil, completion = "不用擔心弗洛林，他會想通的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57884] = {title = "奪回荊陵莊園", objective = "殺死尼古拉子爵並奪回荊陵莊園。", description = "我做了一些調查，發現荊陵莊園的新主人是尼古拉子爵。\n\n他是個骯髒的傢伙，我們需要花上好幾週才能除去他留在莊園的惡臭！\n\n希望你能用更及時的方式幫我們除掉他。\n\n我會召集剩下的人手，讓我們一起奪回荊陵莊園吧。", progress = nil, completion = "為什麼那位女士會選這種粗鄙之人當她的情人呢？算了，反正荊陵莊園再次回到我們手中就好。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][57885] = {title = "悄悄潛入", objective = "使用華麗的鏡子進入女伯爵的房間。", description = "我可以向你保證，我們離開時可不是這個模樣。而且我們也絕對不會讓莊園淪落到這副慘況。\n\n至少莊園還算完好，這是最重要的。你可以利用它小心翼翼地潛入女伯爵的私人房間，取回勳章。\n\n去吧，在我們的事還沒傳開之前，快點行動。你不在的時候，我們會盡最大努力讓莊園恢復原貌。", progress = nil, completion = "能夠當面見到可敬的淵喉行者本人，真是一大榮幸。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57886] = {title = "餐桌上的交易", objective = "享受女伯爵的款待，並聽取她的提案。", description = "儘管你不請自來，但倒也在預料之中。在我的地盤中，任何風吹草動都逃不過我的法眼。\n\n閒話說到這，我們一起吃頓飯，聊聊正事吧。\n\n相信我們一定能找到辦法，得到各自想要的東西。", progress = nil, completion = "那麼，我們達成協議了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57887] = {title = "殺死信差", objective = "從雷德拉夫信差身上取得反叛的書信。", description = "我一向對地盤中的任何風吹草動瞭若指掌。\n\n傳統上，我們利用石惡魔來傳遞消息，不過我的線人向我示警，表示最近舊城門那裡情況有異。\n\n有個汎希爾人受雇為兩個不明人士傳遞消息，每當有人隱藏自己的身分行事時，永遠不會是什麼好事。\n\n找到這個信差，取得他身上的密函。", progress = "事情辦好了嗎？", completion = "&lt;女伯爵面無表情地仔細閱讀書信，不過手卻隨著閱讀過程越抓越緊。&gt;\n\n這封信是艾爾摩家族的安德烈寫的，我認得他潦草的筆跡。看來他圖謀推翻我。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][57888] = {title = "請君入甕", objective = "將邀請函交給雷德拉夫區的每個名門望族。", description = "信中寫得很清楚，安德烈不願屈居在我之下，不過對於共謀者的身分卻隻字未提。\n\n我們現在只知道，他們會想辦法混進我今晚舉行的晚會，以便執行他們的計畫。不如我們來幫他們省點麻煩吧？\n\n去雷德拉夫區一趟，將邀請函發給各個名門望族。這樣一來，就能確保那些叛徒一定會現身。", progress = nil, completion = "我的晚會可是惡名昭彰，沒有人會拒絕受邀參加。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57889] = {title = "意外的縱火犯", objective = "殺死安德烈勛爵，並對他的莊園放火。", description = "想撬開安德烈的嘴，讓他主動供出他的合作對象，是不切實際的事。他不會輕易開口，而且我們不能讓他的共犯察覺到不對勁。\n\n我們必須除掉他，而且必須布置得像是一場意外。\n\n等到解決安德烈後，就在他的地毯上放火，讓整座莊園付之一炬。\n\n你絕不希望讓安德烈這樣的人掌權，他手段殘忍，而且冷酷無情。", progress = nil, completion = "你做得很徹底，對吧？我從這裡就能看見熊熊火光。你不在的時候，我趁閒暇之餘修改了一些護腿好符合你的身材，我很肯定沒搞錯你的尺寸。", rewards = "您會收到：\n\n恐懼哨衛烏黑腿甲破魂者烏黑護腿懼獵者烏黑護腿烏黑死亡帷罩馬褲"}
MultiLanguageQuestData['tw'][57890] = {title = "美麗卻致命", objective = "到雷德拉夫區的花園收集50朵暮沼蘑菇。", description = "雷德拉夫區是瑞文崔斯的富人區，住著最富裕的汎希爾人，那邊的居民為了維護他們奢華的花園，不惜花大錢。\n\n我必須說，這些付出很值得。因為雷德拉夫區是唯一適合生長暮沼蘑菇的地方，它們美麗又致命。\n\n你願意幫我採一些嗎？它們的用途非常多元，手邊留些存貨準沒錯。", progress = "你拿到蘑菇了嗎？", completion = "&lt;女伯爵帶著一抹諷刺的微笑，看著那些蘑菇。&gt;\n\n鮮豔的色彩意味著孢子毒性猛烈。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57891] = {title = "明察暗訪", objective = "參加女伯爵的晚會，與賓客交談，查清背叛的家族。", description = "等到宴會開始，我身邊會擠滿想來依附權勢的貴族。\n\n這就是我要你混進宴會的原因，跟參加者搭話，看看你能不能查出是哪個家族密謀反叛。\n\n留意一點，無論是不是受到邀請的賓客，這些貴族都能一眼看出外來者。你並非每次都能獲得熱情的對待。", progress = nil, completion = "你查出是哪個家族密謀反叛了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57892] = {title = "立即伸張正義", objective = "公布背叛家族的名字，伸張正義。", description = "在參加宴會的人當中，或許很多人都想要對我不利。\n\n相信你已經很敬業地查清是哪個家族與安德烈合作了吧？\n\n等到他們的名字被公諸於世，相信你一定會立刻伸張正義。", progress = nil, completion = "正義得以伸張，動亂得到平息。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][57893] = {title = "非敵非友", objective = "到罪殞城將勳章交給雷納瑟王子。", description = "希望你已經充分認知到我扮演的角色有多麼重要。\n\n我舉辦宴會，可不是只為了吃喝玩樂。娛樂那些名門望族，有助於平息動亂。如果他們被這些瑣事佔據，就沒時間搞陰謀詭計。\n\n有時候，不戰而勝，才是最上策。把我的勳章送給你，就是最好的例子。\n\n我們或許不是盟友，但也不是敵人。", progress = "你拿到勳章了嗎？", completion = "女伯爵就這樣和平地奉上她的勳章？她說不定可以成為我們的潛在盟友…", rewards = "您會學到：\n\n女伯爵\n\n您還會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][57895] = {title = "樂土堡", objective = "和軍政官阿德雷特斯一同前往樂土堡。", description = "還剩一個步驟，你才算正式加入我們。\n\n你現在要前往樂土堡，它是通往晉升之巔其他地區的入口，也是晉升者守護昇靈堡的制高點和志士們受訓的地方。\n\n到了以後，我們會確保你有樂土堡提供的資源。既然你沒有翅膀，那我護送你過去吧。", progress = nil, completion = "歡迎回家，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57897] = {title = "獨行的危險", objective = "在羈絆聖堂與靈魂嚮導戴莉亞談話。", description = "在我們開始清理戴納瑟斯的混亂之前，你還有一件事要做。\n\n你必須有個靈魂之絆。\n\n所有琪瑞安都會經歷這個神聖儀式，儘管通常是在他們謁見御靈者之前的數紀元前。\n\n靈魂嚮導戴莉亞會引導你完成這個儀式，請到下方的房間找她。", progress = nil, completion = "就算是現在，你的靈魂依然比大多數人更加明亮。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57898] = {title = "當靈魂遇見身體", objective = "完成靈魂之絆儀式。", description = "與其他人建立靈魂之絆，並非不可逆的過程。然而，建立靈魂之絆也絕非易事。\n\n你們將會體驗彼此的過去，你們的希望、恐懼、夢想，甚至回憶本身…前提是還有任何回憶留存的話。你們將會在真正意義上達到魂靈相連的境界。\n\n完成後，你們之間的羈絆將會超越物理空間，你也會徹底變強。不只是武力方面，連精神上也是。", progress = nil, completion = "你們共同的旅程才剛剛開始。", rewards = "您會學到：\n\n靈魂之絆：佩拉苟斯\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57899] = {title = "更多工作？", objective = "啟用指揮桌。", description = "在你的世界，有句俗話說：「你無法同時出現在兩個地方。」\n\n如果沒有靈魂之絆，確實是如此。你該感到幸運，因為我們解決了這個問題。這是凡人才有的物理限制。\n\n到上方的壁壘啟用樂土堡最新的設施，然後去找闊洛斯，到時你就明白了。", progress = nil, completion = "我是闊洛斯，這座堡壘的首席通訊員。幸會。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57900] = {title = "穿過暗影之境", objective = "使用指揮桌展開一場冒險。", description = "身為琪瑞安，我們有責任確保每一個進入暗影之境的靈魂都前往適合的永恆國度。\n\n但是，這份永恆的職責並不止於奧睿博司。\n\n暗影之境中有無數需要關注的事，遠超出我們能應付的範圍。朋友啊，這時候，就是我出馬的時候了。\n\n請把我當作你的千里眼。請容我以一個簡單的工作，來示範你們能如何從我的服務中獲益。", progress = nil, completion = "看吧，我的凡人朋友，這就是那麼簡單。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57901] = {title = "剩下的一切", objective = "啟動靈魄傳導器。", description = "就像你必須和靈魂之絆的同伴合作，永遠共同維持我們國度的和平一樣，你也必須恢復上方天空的靈魄之流。\n\n卡菲斯是偉大的米卡尼寇斯之徒，專門將我們所持有的靈魄導向最需要的神殿。\n\n在這場殘害我們的靈魄枯竭中，如果有誰能提供協助，非她莫屬。", progress = nil, completion = "有人說過你！過來！我也想認識你！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57903] = {title = "空中的力量", objective = "使用靈魄傳導器將靈魄引導到昇靈堡的某個地點。", description = "你在這裡看到的這部裝置，是用來將靈魄送到神殿，幫助我們的族人。\n\n隨著每座神殿的靈魄重新流動，它就能再一次發揮作用。你會發現這些功能對你的旅程很有用，甚至會發現有全新挑戰等著你去面對。\n\n等你將一些靈魄送來我們的聖所，再使用這部裝置將靈魄導向某座神殿，就能親眼見證成果。", progress = nil, completion = "很好，靈魄再次流動了起來。你可以定期回來操作這部裝置，引導更多靈魄。\n\n只要你收集更多靈魄並導入昇靈堡，靈魄流就會越來越強。儘管現在還維持不了多久，但最終你將能強化靈魄流，建立永久的連接。\n\n過去，靈魄流曾照亮昇靈堡的天空。在你的幫助下，一定能重現這幅景象。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57904] = {title = "永恆的職責", objective = "向軍政官阿德雷特斯回報。", description = "淵喉行者，你已經正式加入我們的神聖誓盟，琪瑞安的身分會讓你永遠引以為傲。我們面前將會出現許多挑戰，但我們會一起面對。\n\n現在，回去找軍政官阿德雷特斯，告訴他你的訓練已經完成。我們最近人手嚴重不足，相信他一定需要你的幫助。\n\n<name>，莫忘職責。", progress = nil, completion = "謹代表榮耀的御靈者，願你永遠遵循道路，邁向更光明的未來。", rewards = "您會收到：\n\n無私收集者護手無私引渡者護手無私看守者護手無私熔爐士手套名望名望"}
MultiLanguageQuestData['tw'][57905] = {title = "獨特機會", objective = "在羈絆聖堂與靈魂嚮導戴莉亞談話。", description = "如果沒有靈魂自願確保樂土堡的許多功能正常運作，就算用上暗影之境的所有靈魄，也無法讓樂土堡重返榮耀。\n\n靈魂嚮導戴莉亞是我們經驗最豐富的看守者。她一直負責將靈魂再一次送到這些大廳。\n\n你應該去羈絆聖堂拜訪她一下，看看能提供什麼協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57908] = {title = "通往真正的試煉", objective = "到志士試煉場與克蕾雅和佩拉苟斯談話。", description = "我必須老實說，<name>，一開始看到你，我根本不抱什麼希望。\n\n克蕾雅深信，你的到來是昇靈堡的情況開始好轉的徵兆。我那時還…有點懷疑。\n\n<熔爐士指了指她的熔爐。>\n\n你為我所做的事，我銘記在心。試煉場外面有一條路，想要踏上它，你必須先通過試煉。試煉非常困難，一般人通常需要數個紀元才能通過。\n\n你不是一般人。\n\n克蕾雅和佩拉苟斯會告訴你更多細節，他們在練習場附近等你。", progress = nil, completion = "熔爐士的感激之深，遠超你的理解。\n\n現在，你必須將注意力重新放在我們來這裡的目的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57909] = {title = "評估你的耐力", objective = "參與8場戰鬥冥想。", description = "接下來的試煉會從不同層面考驗你。如同克蕾雅，我希望測出你承受磨難的意願。\n\n看看你四周，這裡的志士都在為了你即將迎來的試煉接受訓練。有些人已經在這裡磨練技藝長達數百年，數千年。有些人成長得很快，有些人則不是。\n\n你的任務是邀請他們來場點到為止的比試。琪瑞安族都將這類比試稱為戰鬥冥想。\n\n幫助他們集中精神，他們也會同樣幫助你。\n\n等你覺得可以繼續的時候，就回來找我。", progress = nil, completion = "能在這麼短的時間內跟這麼多人比試，你的耐力的確無與倫比。\n\n我已經厭倦了只讓你展現實力。\n\n&lt;佩拉苟斯笑了笑。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57912] = {title = "天選者男爵", objective = "到長矛之尖與維拉斯男爵會面。", description = "我們在長矛之尖的部隊遭到藩侯珈爾瑪的先鋒部隊進攻。如果維拉斯親自率軍守禦，那麼情況一定相當危急。\n\n傀儡家族塑造血肉，為其部隊鑄造軀體。他們原是不可或缺的盟友，如今卻成為令人膽寒的敵人。\n\n藩侯克利瑟斯相信你的力量。而你的力量一定會派上用場。", progress = nil, completion = "我對你寄予厚望，凡人。你會協助帶領前線部隊，攻擊傀儡大軍！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57914] = {title = "知識印記", objective = "取得知識印記。", description = "我還有一件事需要你的協助。我的研究人員和審問者在第二個房間裡不眠不休地工作著。但截至目前為止，他們一點進展都沒有。\n\n你去找他們談談，看看他們有沒有什麼發現。告訴他們，如果他們還是一無所獲，我很快就會讓他們人頭落地了。\n\n幫我拿到印記，軍需官！", progress = "你把印記帶來了嗎？如果還沒，為什麼來找我講話？", completion = "又距離我的目標更近一步了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57915] = {title = "尋找倖存者", objective = "在奧爾希斯查看8位廢土漫遊者。", description = "怪蟲從四面八方襲來…根本沒有時間反應或逃命。\n\n很多朋友還沒反應過來就死了，其他人則是努力揮舞手邊的工具奮戰。\n\n我是個懦夫。我在動亂中轉身逃走，沒上前幫忙。\n\n現在，我被困在這裡，糧食和水都耗光了，怕到沒膽子尋找倖存者。\n\n拜託你，我求求你在奧爾希斯尋找倖存者，幫幫他們…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57918] = {title = "赦免靈魂", objective = "到赦罪墓穴找控罪者。", description = "淵喉行者，你對於瑞文崔斯的作用還一知半解，對吧？\n\n送來我們這裡的靈魂都徘徊在永世不得超生的邊緣。即便無微不至的細心照料，也並非每個靈魂都能逃離淵喉的魔掌，迎來更美好的未來。\n\n但這也只有在理想狀況下才會發生。\n\n目前，由於你把宮務大臣送進贖罪之殿，我們反而見證了最糟的狀況。\n\n我們必須回到贖罪之殿，恢復那裡的秩序。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57919] = {title = "濫用力量", objective = "制伏受虐的靈魂。", description = "那些靈魂都在宮務大臣底下受盡折磨。\n\n我們汎希爾族能讓靈魂聽令於我們，這樣我們才能引導它們洗滌罪孽，不管它們願不願意。\n\n不過，宮務大臣卻將我們的聖物和儀式拿來虐待他所管轄的靈魂。他將靈魂束縛在它們的罪孽石上，扭曲了靈魂的本質！\n\n對受虐的靈魂使用這些儀式鎖鍊，讓它聽令於你。我們必須試著赦免它。", progress = nil, completion = "那個靈魂永遠消亡了。大好的可能性全都浪費了…\n\n宮務大臣一定會為此付出代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57920] = {title = "合適的靈魂", objective = "制伏4個逃跑的靈魂，將它們交給控罪者。", description = "我們必須盡可能拯救越多靈魂越好，別讓它們步上剛才那個靈魂的後塵。\n\n搜索大廳，尋找幸運逃離宮務大臣魔爪的靈魂。制伏它們，然後將它們帶到贖罪之殿交給我。\n\n透過分工合作，就能確保每個靈魂都獲得妥善的處理和照顧。", progress = nil, completion = "每個失落的靈魂都必須獲得照顧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57921] = {title = "合適的用品", objective = "收集汎希爾祭儀長袍、匕首及秘典。", description = "我們必須遵守非常具體的程序，才能讓所看管的靈魂獲得最好的照顧。你和我都必須嚴格遵守程序。\n\n我可以遮掩你俗艷的外表，不過你必須自行取得必要的儀式用品。\n\n從附近侍奉宮務大臣的墮落汎希爾人取得那些用品。", progress = "我們會照規矩來。", completion = "很好。可以開始進行儀式了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57922] = {title = "合適的懲罰", objective = "殺死『奪魂者』法特。", description = "幸好，我不是唯一一個記得贖罪之殿及其僕人的高貴使命的人。\n\n這些誓復者祭儀師一直在私底下維持大廳的完整性。\n\n根據他們的報告，宮務大臣仰賴一個天賦異稟的奪魂者，由他教導其他祭儀師腐化靈魂的方式。\n\n讓他接受應有的制裁。", progress = nil, completion = "他其實應該到淵喉接受制裁，不過這樣就夠了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57923] = {title = "赦免儀式", objective = "協助控罪者完成赦免儀式。", description = "赦免儀式便是強迫靈魂捨棄生前重擔的神聖儀軌。\n\n如果想讓儀式生效且效果長存，參與的靈魂必須是心甘情願。我們通常需要耗費無數歲月，才能讓一個靈魂準備好接受赦免儀式。\n\n宮務大臣背棄了他的職責，看情況這些靈魂早該接受赦免了，因為靈魄已經要滿出來了。\n\n我們自己來執行儀式，讓這些靈魂早一步踏上下一段旅程。", progress = nil, completion = "赦免不會憑空降臨，也不該如此。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57924] = {title = "審判儀式", objective = "參與審判儀式。", description = "赦免儀式總算完成了，每個靈魂都必須面對它在瑞文崔斯的最後審判。\n\n可能的裁決共有三個：\n如果無可救藥，就會打入淵喉，永世不得超生。\n\n如果完全滌去罪孽，不是晉升為汎希爾的一員，就是送回去給審斷者重新分發。\n\n我們最神聖的儀式「審判」會決定它們的命運。\n\n現在剛好正在進行一場審判。我會幫你偽裝一下，好讓你旁聽，確保裁決公正無私。", progress = nil, completion = "為了拯救這個靈魂，我付出的犧牲遠超你的瞭解。\n\n不過重來一次我還是會這麼做，因為這是對的事。你能理解嗎？", rewards = "您會學到：\n\n汎希爾儀式\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57925] = {title = "文獻管理員費恩", objective = "向文獻管理員費恩自我介紹。", description = "很好，我們的偽裝是多餘的。打斷他們墮落的儀式後，我們一定變成不受歡迎的人物。\n\n在這個多事之秋，一些意志堅定的汎希爾人還是繼續待在這些廳堂中。那些尚未拋棄使命感的人，仍在履行自己的職責。\n\n文獻管理員費恩就是其中一人，請盡你所能助他一臂之力。我們需要他的智慧，才能消弭宮務大臣對這些廳堂的掌控。\n\n我必須指導葛雷希特，他還有很多要學。", progress = nil, completion = "不久前，好幾個非常生氣的法官才經過這裡。\n\n&lt;文獻管理員費恩露出微笑。&gt;\n\n快點告訴我你是怎麼激怒他們的，別漏掉任何一個細節！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57926] = {title = "罪孽石文獻", objective = "收集100本罪孽石記錄簿。", description = "你說審判官泰利安負責監督儀式過程？\n\n<文獻管理員費恩搜尋這房間中的大量文獻。>\n\n我們這些文獻管理員嚴謹地記錄了每一個通過這些廳堂的靈魂。\n\n至少我們本該這麼做。強大的汎希爾人的罪孽石往往會不翼而飛。\n\n<文獻管理員費恩翻個白眼。>\n\n這裡沒有他的罪孽石。不是他早就把它偷走了，就是有人把它藏了起來，準備抹黑他。\n\n幫我完成我的文獻，之後不管你要那顆罪孽石，我都會幫你找來。", progress = "罪孽石是瑞文崔斯最強大的武器，", completion = "&lt;當你將文獻交給他時，文獻管理員費恩眼睛發亮。&gt;\n\n這筆交易實在太划算了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57927] = {title = "重組特梅爾", objective = "收集特梅爾的頭、身體及翅膀。", description = "瑞文崔斯的中心思想就是懺悟，每個人都需要懺悟，就連你也不例外…\n\n<墓穴守衛者凱希爾笑了笑。>\n\n別害怕，我並不打算為了你先前對我的冒犯而找你報仇。\n\n但我也無法將特梅爾交給你。\n\n你看，因為你英明的選擇，宮務大臣才會接管這些殿堂，並且將特梅爾視為不利他統治的威脅。\n\n他的手下將特梅爾打得四分五裂，然後把殘軀丟到這些墓穴中。這也不是我第一次得重造他。", progress = "不管特梅爾損壞得多嚴重，我都能讓他復活。", completion = "&lt;墓穴守衛者凱希爾檢視你交給他的特梅爾殘軀。&gt;\n\n特梅爾，他們下手真狠，不是嗎？沒有我修不好的東西…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57928] = {title = "贖罪墓穴鑰匙", objective = "開啟贖罪墓穴。", description = "<這把鑰匙上標示的符印與贖罪之殿的墓穴相符。宮務大臣到底在那裡藏了什麼東西？>", progress = nil, completion = "贖罪墓穴本是用來收容靈魂，那些靈魂需要多一點…關注，才能進行後續儀式。\n\n結果宮務大臣那些智障手下居然將墓穴當成牢房和藏寶庫。要是你願意一找到鑰匙就來開啟墓穴，就真的是幫了我們大忙了。", rewards = "您會學到：\n\n贖罪墓穴\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57929] = {title = "獵殺審判官", objective = "殺死審判官泰利安。", description = "你或許已經注意到了，審判官受到宮務大臣的魔法保護。這應該是使用了主宰的勳章。\n\n不過，既然我們拿到審判官泰利安的罪孽石，就表示我們有能力破除那些防禦魔法。\n\n找到審判官，命令特梅爾朗讀他的罪孽石。只要宣告審判官的真名和罪孽，就能破除他的防禦，能在短時間內對他造成傷害。\n\n準備出擊。", progress = nil, completion = "他是罪有應得。\n\n希望我們之後還能一起打倒更多墮落的審判官。", rewards = "您會學到：\n\n審判官罪孽石\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][57931] = {title = "芬連克斯故障", objective = "到黃金牧場尋找迦塔馬托斯，並將它送回位在煉火哨站的石臺。", description = "作為訓練的一部分，我命令芬連克斯裝置去巡視原野，留意野生動物及任何異常情況。\n\n不幸的是，上次回來的時候，數量少了一個。\n\n請去黃金牧場搜索一下，找到失蹤的單位，送它回來這裡。", progress = nil, completion = "這個芬連克斯似乎故障了，我們必須修復他。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57932] = {title = "汲取資源", objective = "從金輝雲行者身上吸取靈魄5次。", description = "修復通常很簡單，靈魄無所不在！\n\n如今靈魄枯竭，我們無法直接從空氣中汲取，此時便需要其他來源！\n\n這給你。從雲行者身上吸取靈魄。雖然不盡理想，但現在情況緊急。", progress = nil, completion = "這應該足以修復迦塔馬托斯了，而且還有剩下的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57933] = {title = "我們可以修好他", objective = "幫忙佩羅迪斯修復迦塔馬托斯。", description = "迦塔馬托斯需要進行無數次修復，才能正常運作。\n\n保養芬連克斯是必要工作。請出手相助，以便迅速完成徹底修復。", progress = "只要你確保芬連克斯處於正常運作，他們就會毫不遲疑地執行命令。", completion = "雖然外表已經恢復如初，不過他必須經過重新測試和訓練。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57934] = {title = "戰鬥教練", objective = "帶迦塔馬托斯到野獸大廳，殺死8隻焦慮的翼靈蛇。", description = "我們的芬連克斯擅長戰鬥，他們經過完善訓練，可用腳制服敵人，同時還能獵殺暴走的野獸。\n\n我需要你去測試一下迦塔馬托斯的戰鬥程式。帶他進入下方的山洞，用那裡的翼靈蛇訓練戰鬥技巧。", progress = nil, completion = "太好了。他的戰鬥程式沒有問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57935] = {title = "雷射定位", objective = "帶迦塔馬托斯進入野獸大廳，然後指示他找到6顆訓練寶石。", description = "芬連克斯具備精準的搜索機制，可完美執行偵察工作。\n\n在下方的洞穴中，我們隨機放置一些寶石，並訓練芬連克斯找到這些寶石。帶迦塔馬托斯到下面去，進行一些演練，校準他的訓練資料。", progress = "芬連克斯追蹤和鎖定目標時，所涉及的技術層面相當引人入勝。\n\n不過，你看起來不像是對這種細節感興趣的人。", completion = "我敢說拉里翁一定做不到這種精準追蹤！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57936] = {title = "高級編程", objective = "到野獸大廳殺死萊尼德。", description = "芬連克斯完全聽令行事，從不會抗命！\n\n拉里翁是無腦的野獸，善於攻擊，說不定還會吃掉侍者！\n\n附近棲息著未馴化的拉里翁，常常追著侍者跑，超可怕的！拜託把牠解決掉。", progress = nil, completion = "終於可以安心了，再也沒有會吃人的野生拉里翁。呼…", rewards = "審判志士戰靴純潔志士足靴謙恭志士脛甲英勇志士長靴純潔志士裹腕審判志士裹腕謙恭志士裹腕英勇志士裹腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][57937] = {title = "戰術陣型", objective = "協助迦塔馬托斯學習三種隊形的正確走位。", description = "進行芬連克斯的編隊訓練時，最重要的一環是隊形訓練。他們必須清楚標準的琪瑞安戰鬥隊形，並且知道如何變換隊形。\n\n迦塔馬托斯缺少了最後的隊形訓練資訊。請協助訓練他。", progress = "優秀的士兵總是聽令行事。", completion = "學會之後，我相信迦塔馬托斯已經恢復正常運作了。\n\n感謝你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57947] = {title = "谷地的靈魂", objective = "到靈魂谷地找丘發。", description = "森林裡的動物，多是變換形體的凡人靈魂，在谷地追逐嬉戲。牠們的靈魄滋養曠野，如同雨水滋養樹葉。\n\n但危險暗中逼近。充滿惡意的黑暗風暴襲捲樹林。尋求庇護的生物卻反而身陷險境。\n\n拯救牠們吧。", progress = nil, completion = "什麼？什麼？\n\n是高樹派你來幫我們的嗎？幫幫我們！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57948] = {title = "無力贈與", objective = "在靈魂谷地使史蘭克能、盧里和阿嗚恢復靈魂幻體。", description = "噢，不，不！\n\n我的朋友，他們給得太多了。給了太多自己的靈魄，他們失去了形態！我們來到這裡時，都會化成不同的形態。化成適合我們的樣子！\n\n但我們貢獻自己的靈魄，無私奉獻！為了幫助林地。我們貢獻了好多靈魄，有時會太多。\n\n我還有一些靈魄。我還保有我的形態！帶我去找我的朋友！我們可以幫他們重新化形！", progress = nil, completion = "你找到他們了！你找到我的朋友了！他們恢復形態了！\n\n現在我們還有最後一件事要做。最後一件事！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57949] = {title = "他們得冷靜下來", objective = "在靈魂谷地擊敗木魈，並使用捕魂網從他們身上取回受竊的靈魄。", description = "木魈！該死的木魈。他們來到林地。他們毀了一切！\n\n他們從捕魂網上拿走了靈魄！我們一直在收集，沒錯。為了高樹和林地收集靈魄。木魈必須付出代價！\n\n痛扁他們一頓！然後用這面捕魂網把靈魄拿回來。我們需要它！他們不需要！", progress = "你殺了他們了嗎？你讓他們付出代價了嗎？", completion = "被偷了！他們偷了靈魄！他們像瘋了一樣跑過來然後…\n\n等等，這樣很正常。他們一直都那麼壞。那些愚蠢的木魈！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57950] = {title = "傲慢的米吉克", objective = "擊敗傲慢的米吉克。", description = "壞木魈！超壞！他們拿走我們的靈魄。我們失去了形態！其中有一個最狠。\n\n米吉克！他對其他壞妖精發號施令。他還騎了一隻果姆！又大又噁的果姆！\n\n打他。打他！", progress = nil, completion = "不見了！壞木魈不見了！靈魂谷地又是我們的了。\n\n現在走吧。我們該走了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57951] = {title = "靈魂歸來", objective = "在特那瓦勒向塔許莫爾樹林長回報你的成果。", description = "去找樹，去找樹！我們差不多要回去林地了。\n\n我們有了我們的靈魄。我們有了我們的形態。高樹需要靈魄。高樹會很開心！\n\n我會在那邊等你！", progress = nil, completion = "橡實長成森林，靈魂供應靈魄。儘管渺小，我們的命運全賴於此。\n\n森林發出感激的嘆息。", rewards = "星蔽手套林地看守者護手靈魂看管者裹手夢棘手甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][57952] = {title = "急徵果姆礦質", objective = "到靜謐水塘旁找沙洛大師。", description = "爍瀑盆地是這附近的另一座林地。他們發出求救信息，表示急需果姆礦質。\n\n雖然這種礦質的來源不特別光采，但對於工匠而言，卻是十分重要的原料。隨著靈魄乾旱持續肆虐，礦質變得越來越難收集。\n\n我很想幫他們一把，把多餘的資源送給他們。\n\n拜託，到靜謐水塘旁找沙洛大師，他在那裡飼養了一小群小果姆。\n\n請他提供更多果姆礦質。", progress = nil, completion = "寇達需要果姆礦質？\n\n&lt;沙洛大師露出興奮的神情。&gt;\n\n我很樂意滿足她的要求！來，讓我教你該怎麼做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57954] = {title = "燒毀屍體", objective = "燒掉10具有蟲卵的屍體。", description = "這種蟲似乎會在附近的屍體上到處下蛋。\n\n牠們把這些死者當作食物，藉此來生出更多可怕的東西。令人作嘔！\n\n我們可以晚點再為死者哀悼，但是萬一有更多蟲孵化出來，我們就活不到那個時候了。\n\n燒掉屍體，把蟲卵毀了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57955] = {title = "前往安卡騰港", objective = "到安卡騰港尋找追蹤者薩瑪拉。", description = "我恐怕還沒有足夠的力量可以再次深入沙漠面對那些怪物。\n\n請前往南方，在一個之前名叫舒諾茲營地的開採區尋找追蹤者薩瑪拉。\n\n叫她攔下任何想要取道此地的商隊，免得其他人遭到伏擊，面臨一樣的恐怖命運。\n\n我們一定要把消息傳遍奧丹姆，以免大家的部隊被各個擊破！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57956] = {title = "廢土漫遊者宿主", objective = "殺死6個廢土漫遊者宿主。", description = "那些蟲子在我們士兵的屍體下蛋，真的是太可怕了。\n\n有些屍體還爬了起來，變成腐敗腫脹的噁心怪物。\n\n在它們繼續利用我們的死者增兵之前，我們必須阻止它們。\n\n這不是令人愉悅的任務…不過我必須請你幫我消滅它們，燒掉屍體。\n\n可以的話，去我後面的地方拿炸彈。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57959] = {title = "英雄戰爭前線：黑海岸之戰", objective = "在黑海岸之戰擊敗聯盟。", description = "黑海岸屬於部落！我們一定要堅守陣地，維持我們對卡林多的統治。\n\n準備好。戰鬥即將開始！", progress = nil, completion = "打得漂亮，&lt;name&gt;。雖然我確信，聯盟很快又會嘗試出兵奪回黑海岸。不過到時候，我們也會準備好應戰！", rewards = "您會收到：\n\n亡靈守衛裝備箱榮勛軍團軍功獎章艾澤萊晶岩奈奧羅薩回音奈奧羅薩回音"}
MultiLanguageQuestData['tw'][57960] = {title = "英雄戰爭前線：黑海岸之戰", objective = "在黑海岸之戰擊敗部落。", description = "我們不能容忍部落繼續霸占我們的領土。\n\n而今天，夜精靈不會孤軍奮戰。黑海岸一定會再度回到他們的手中。\n\n為了聯盟！", progress = nil, completion = "感謝你，今天這一仗我們獲勝了。但是這場戰爭不會那麼快就結束。\n\n為了聯盟！", rewards = "您會收到：\n\n哨兵裝備箱第七軍團軍功獎章艾澤萊晶岩奈奧羅薩回音奈奧羅薩回音"}
MultiLanguageQuestData['tw'][57964] = {title = "復仇很簡單", objective = "殺死15個融骨部隊。", description = "我們有很多人還留在這裡，試圖在這片廢墟中生存。\n\n這些傀儡經常侵入我們的地盤。它們能偷就偷，並且擄走我們的人拖去實驗室裡回收。\n\n解決方案就是以暴制暴，而且由你來動手！", progress = nil, completion = "你想要的話，可以多殺幾個。", rewards = "您會收到：\n\n戰鬥之焰血煉勳章血煉戒環血煉披氅腫脹怪異心臟束縛防護骨匣穩定的瘟疫品種通靈塔聚焦水晶保存良好的超凡腦殼血絲長袍鋼核胸鎧屍皮手套\n                            顯示 19 更多                        鋼核護手血絲手套肉鱗護手屍皮肩甲鋼核護肩血絲披肩肉鱗披肩血絲裹腕鋼核裹腕肉鱗裹腕屍皮裹腕疫蝕穿刺瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐感激禮賜"}
MultiLanguageQuestData['tw'][57966] = {title = "你先請", objective = "拆除卡莉歐普第三大廳的陷阱，前往最後一個房間。", description = "你這個人挺有用的。所以，我要派你去拆除掉這個大廳裡的防禦工事。\n\n請多保重，不要一下就掛掉了。我可不希望再等個幾千年才能拿到那把長矛。", progress = nil, completion = "你的努力帶來了我想要的成果。為了犒賞你，我不會殺你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57967] = {title = "應屬之地", objective = "在樂土堡的應屬之地奉上卡莉歐普之矛。", description = "在那些有決策力的人眼中，你已經證明自己是貨真價實的英雄。\n\n感謝你讓我有幸能拿起它，即便只是極為短暫的一下子。然而，只有你才有資格將這支矛供奉在它應屬的長眠之處。\n\n我們在樂土堡會合吧，那裡正是供奉這支矛的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57968] = {title = "廢土漫遊屍路", objective = "殺死6個廢土漫遊者宿主。", description = "這些骯髒的怪物到底有幾隻啊？\n\n我無法忍受有人褻瀆我們的死者，尤其還把他們當作噁心昆蟲大軍的飼料，更是讓我忍無可忍。\n\n盡你所能屠殺昆蟲，能用火的話最好！", progress = nil, completion = "他們真的是怎麼殺也殺不完…", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][57969] = {title = "協助傷者", objective = "為8位廢土工人治療。", description = "我的朋友，正如你在此地所見，我們被這些可怕的怪物圍攻。\n\n許多朋友都成為這些怪物的獵物，但幸運的是，我們在此地集結的戰士夠多，足以抵擋來犯的威脅…至少目前是這樣。\n\n如果你能提供協助，拜託照顧好我們的傷患，並為他們清出一條可以逃出廢墟的道路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57970] = {title = "破滅者塞可尼克斯", objective = "殺死破滅者塞可尼克斯", description = "阿卡莉和一群戰士正在廢墟中心和一頭巨大的怪物交戰。\n\n沒有什麼敵人是她打不倒的，但這頭怪物早晚都會耗盡他們的力氣。\n\n雖然敵人被戰士們纏住了，但萬一他們倒下，廢墟肯定會被淹沒。\n\n拜託你，動作快點。有了你的協助，他們一定可以打倒這頭巨大的敵人。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57971] = {title = "亞蒙廢墟", objective = "前往亞蒙廢墟。", description = "這些東西似乎是突然冒出來的，而且到處都是！\n\n這可能是一波有組織的攻擊，或者這些東西多到我們無法理解的程度。\n\n不論如何，這對我們都很不利…真的，真的很不利。\n\n$p，我需要你跑一趟亞蒙廢墟，看看當地情況如何。\n\n如果他們需要協助，請伸出援手！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57973] = {title = "英雄：黑海岸之戰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57974] = {title = "英雄：黑海岸之戰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][57976] = {title = "以身作則", objective = "殺死12個鋼皮前鋒兵或鋼皮殘暴者。", description = "藩侯克利瑟斯對你的期望很高，凡人。讓這些士兵見識一下競技場的真正勇士如何殲滅敵人並奪取勝利！\n\n與這些背叛的傀儡對峙。不留活口！", progress = nil, completion = "那應該可以把恐懼灌進他們失竊的心裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57977] = {title = "急需幫助的神殿", objective = "協助純潔神殿內的侍徒。", description = "<伊芮迪雅居高臨下地看著你。>\n\n你看來像個新人。\n\n<伊芮迪雅皺著眉頭。>\n\n很抱歉，現在恐怕無法為你舉行迎新典禮。如同我的侍徒告訴你的，我們希望所有有空的志士都能鼎力相助，照顧受我們庇護的人。\n\n有關需要進行的實際工作內容，你無須太過擔憂，效忠這座神殿的人都會指導你。請去找神殿內的侍徒。\n\n在你提供幫助後，可到神殿內找我。", progress = nil, completion = "你已經證明自己能夠勝任這項任務，感激不盡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57979] = {title = "攻擊舉動", objective = "殺死埃爾佛將軍。", description = "做得好，$p，我們在傷亡最少的情況下向前推進。\n\n從這個全新的前線陣地，我們可以直擊敵軍指揮官。你所集結的部隊會一塊攻擊。合力之下，我們會為戰爭劃下關鍵性的句點。\n\n找到埃爾佛將軍並吹響號角。", progress = nil, completion = "你的領導能力令人激賞，這些部隊將會誓死追隨你！", rewards = "回收的傭兵披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][57982] = {title = "破除屏障", objective = "想辦法穿過靈魂屏障。", description = "和我猜測的一樣，縫肉的助手正在執行他的工作。不管他們在打造些什麼，我們都得摧毀。\n\n他們利用靈魂屏障和幾個膽汁噴射器把房間守得滴水不漏，我們得找個方法穿過防禦！\n\n索雷斯說他有個提案。", progress = nil, completion = "看來這些琪瑞安要比我想像的更堅強。我們去為他們的死去同胞復仇。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57983] = {title = "願御靈者拯救我們", objective = "拯救在監禁牢房中的靈魂。", description = "大多數的志士在一抵達就被屠殺然後肢解了。但這些人算運氣好的。\n\n首席縫補師認為我全身上下值得摘取的只有…眼睛。然後我被拋下自生自滅。願御靈者拯救我，那些哀號…\n\n我想附近還有其他倖存者。你能幫我釋放他們嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57984] = {title = "負責人士", objective = "殺死西維爾醫生、清點者海莫利斯和溶解者克凡。", description = "他們一直在收集琪瑞安…還有我們的屍體…為了某種黑暗用途。\n\n不管他們在計畫什麼，我們都一定要阻止。\n\n我聽說這裡由三個人負責管理。我們必須找出他們並一一殲滅。", progress = nil, completion = "看來有個家族的男爵正在監督這次行動…而且他沒注意到我們脫身了。\n\n我們有機會打倒他！", rewards = "屍體縫補師裹腕冷酷處刑者裹腕血肉建構者裹腕欺詐密探裹腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][57985] = {title = "伸出援手", objective = "摧毀10個無用的靈魄體。", description = "屍體會先帶來這座坑洞進行處理。在塑造成全新傀儡之前，他們的血肉得經過液化再凝結的程序。\n\n我們可以從池子裡抽取尚未成形的活化物質來減緩生產速度。用這把鉤子應該能行。\n\n別讓哈理斯男爵抓到你。他以殘忍聞名，就算對象是家族成員也一樣。", progress = nil, completion = "讓新傀儡的生產速度變慢，應該可以讓我們的士兵稍微喘口氣，不管有多短暫都好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57986] = {title = "義不容辭的重擔", objective = "協助寇嗚和寇亞找回6個喪命的琪瑞安。", description = "梅維斯或許是為了血腥而來，但我要的是讓死去同胞免於可怕的命運。\n\n我的琪瑞安同胞大多數在剛抵達時，或是在戰鬥中就遭到殺害了。如果他們的屍體要丟到這個坑裡，或許我們可以在他們被丟進去之前，早一步將他們找回來。\n\n帶著侍者同行，收集我同胞的屍體。我不會讓他們被做成怪物。", progress = nil, completion = "多謝你，&lt;name&gt;。雖然他們再也回不來了，至少他們的遺骸不會遭到褻瀆。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57987] = {title = "致命的擾亂", objective = "殺死15個戰爭縫補部隊的士兵。", description = "就算維拉斯無法成功襲擊傀儡家族，但混進來的我們還是可以讓他們大大失血。\n\n盡你所能屠殺。我會獵殺這些新產品的策劃者。", progress = nil, completion = "自滿是士兵的最大敵人。戰爭中人人自危，就算躲在自家堡壘的城牆後面也不能鬆懈。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57989] = {title = "卡莉歐普之矛", objective = "擊敗工藝師莉吉埃雅並取得卡莉歐普之矛。", description = "我終於拿到卡莉歐普之矛啦！\n\n有了它，我就可以殺光棄誓者的所有敵人了。看我怎麼收拾他們！", progress = "你找到長矛了嗎？", completion = "是卡莉歐普之矛！你成功把它從棄誓者手中拿回來了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57990] = {title = "日陽方尖碑", objective = "在日陽方尖碑找到滅絕者札菈。", description = "我還有件事想請你幫忙，朋友。這件事關係到我們在這裡的存亡。\n\n我們的同伴札菈決定一肩扛起重任，設法爬上東側的高原，取得留在那裡的老式轟炸機。\n\n到目前為止，我們一直沒辦法把消息送回艾瑞克手中。\n\n不過，如果你可以協助她取得一架堪用的飛機，我們或許還有機會。\n\n希望他們可以在我們被攻陷之前派些支援過來…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][57993] = {title = "二對二", objective = "擊敗『血肉工匠』夏瑞斯和首席學徒馬克瑞斯。", description = "完全用琪瑞安血肉打造出來的傀儡…\n\n這完全背叛了瑪卓薩斯的意義！我們該做的是保衛暗影之境和其中的一切事物，而不是屠殺並剝削！\n\n來吧，$p！我們現在結束這一切！", progress = nil, completion = "我在這具傀儡上感受到某種東西…某種熟悉的…", rewards = "屍體縫補師長袍冷酷處刑者胸鎧血肉建構者鎖甲護胸欺詐密探外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][57994] = {title = "困於血肉", objective = "控制融魂傀儡，並逃出傀儡家族領地。", description = "死去琪瑞安的靈魂…我可以感受到他們的痛苦和混亂。他們被困在這具傀儡中！\n\n求求你，我們絕對不能摧毀它。這麼做只會讓裡面的靈魂，我同胞的靈魂，直接湮滅。\n\n或許…或許他們可以協助我們奔向自由。我會在你指揮它的行動時，安撫傀儡中的靈魂。", progress = nil, completion = "我們逃出來了！\n\n我們先在這裡養精蓄銳。至少要等我們找出回昇靈堡的方式。\n\n感謝你讓我見識什麼叫做勇氣，朋友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58007] = {title = "盯住問題", objective = "與瓦許交談，開始執行她的計畫。", description = "我們的敵人在門前集合了，光靠大膽的空中攻擊，沒辦法永遠擋住他們。\n\n瓦許有個永久守住陣地的計畫，如果有你幫忙，或許真的能成功。\n\n盡你所能的協助她。她和你同行時似乎…比較好相處。", progress = nil, completion = "我們的敵人會為反抗我們後悔。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58008] = {title = "補充燃料", objective = "收集6個燃料罐。", description = "所以，我跑來查看這些飛機…然後你絕對不會相信的，每一架飛機的油箱都空空如也！\n\n附近散落著幾個罐子，裡面肯定還留了一些燃料。\n\n我本來想要自己去收集，但這些該死的蟲子不知道從哪裡冒出來，開始淹沒這個地方。\n\n光靠我一個人沒辦法對付這群東西，你能幫個忙嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58009] = {title = "飛上月球", objective = "解決月亮方尖碑的亞基蟲群威脅。", description = "好吧！該腳底抹油，快點離開這裡了。\n\n我們得儘快回到營地，把這裡發生的事告訴艾瑞克。\n\n去轟炸機那邊，我們把燃料加滿。\n\n我來開，但我會把砲手席留給你，讓我們在回程多轟掉幾隻蟲！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58010] = {title = "再來、再來！", objective = "收集16個亞基蟲碎塊。", description = "我們需要更多亞基樣本，$p。越多越好！\n\n我已經有了很驚人的發現，但還有許多事情需要瞭解。\n\n只要能更深入研究，加上運氣好的話，說不定可以漸漸找出他們的弱點。", progress = "你有找到更多樣本嗎？", completion = "太棒了，謝謝你幫忙收集這些樣本。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58011] = {title = "蟲咬", objective = "收集6枚腫脹毒囊。", description = "藩侯史特拉達瑪相當期待我們最新的藥水完成！\n\n不過，我不知道把毒液囊放到哪裡去了，真丟臉。我最近感覺不太對勁‥\n\n可以幫我一個忙，多拿點毒液囊過來嗎？我們的工作沒有毒液囊就不能繼續！", progress = "我把毒液囊放在哪裡…？", completion = "你找到我的毒液囊了！真是個有用的學徒！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58016] = {title = "大量孢子", objective = "採收8個牽絲孢子。", description = "我最聰明的學徒啊，你終於回來找我了！\n\n你害我擔心死了。你知道嗎？我正在進行一個實驗時，聽到一陣超大的噹啷聲響…我才發現我人在此地，但你卻不見了！\n\n不管你跑去哪邊都無關緊要。你回來了，我們還有很多事要做！\n\n來吧，我的學徒…我們得先把我們的材料找回來！\n\n你有聞到孢子在我們四周萌芽嗎？我們應該去拔一些過來，用在我們努力的成果上。", progress = nil, completion = "真是神奇的孢子，我的學徒！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58022] = {title = "收尾工作", objective = "使用馴牧果姆杖，從黃塵地穴的果姆身上收集野生果姆礦質。", description = "我們的主要目標是找到沙洛。但過程中也有其它機會。\n\n拿著沙洛掉落的馴牧果姆杖。我知道他改良了這根杖，好讓它也能對野生果姆生效。\n\n對著地穴中的果姆使用它，看看你能不能收集到牠們的果姆礦質。\n\n別浪費時間在小果姆身上，從大果姆身上取得更強大的礦質。\n\n要是我們能夠收集到足夠礦質，並且找到那個傻瓜希瓦爾，下次絕不會讓他一股腦地衝進地穴。", progress = "成果如何？", completion = "做得好。你已經收集了足夠的果姆礦質，希望能夠藉此阻止沙洛，不要再孤身溜進巢穴。\n\n除此之外，我們應該還能分一些給我們在亮瀑的朋友。\n\n謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58023] = {title = "一個大問題", objective = "打倒果姆族母。", description = "我們一定要追上沙洛大師。特那瓦勒需要他！我也…我…\n\n我去向樹林長回報。必須讓他們知道沙洛有危險。之後我自己也會從南邊進入地穴，幫你擊敗它。\n\n現在的話，你先看看能有什麼發現。我不相信他就這樣走了。\n\n那隻怪物會見識到沃爾凱的憤怒。", progress = nil, completion = "做得好。你對那隻野獸造成足夠的刺激，迫使她吐出沙洛。她現在躲回自己的巢穴了。\n\n她無路可逃了。\n\n我們來結束這一切。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58024] = {title = "鑽來鑽去", objective = "到黃塵地穴弄塌果姆地穴。", description = "<地面有剛挖過的痕跡，而且有跡象表示坑道遍布整個地方。\n\n弄塌幾個地穴有助於防止果姆繼續侵犯特那瓦勒。>", progress = nil, completion = "果姆又在亞登曠野底下挖出了更多地穴？這真是個壞消息。\n\n謝謝你動手把地穴封閉起來。這應該可以為我們爭取一點時間，鞏固我們的防禦。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58025] = {title = "地底女王", objective = "殺死果姆族母。", description = "你一路追著那隻巨大的果姆到達她的巢穴，而我們也找到沙洛大師。\n\n雖然不是毫髮無傷，不過至少還活著，這樣就夠了。\n\n還剩下最後一件工作，讓我們結束這一切。", progress = nil, completion = "這怎麼可能？族母她…牠們在吞食靈蛹。萬一其它的果姆都像她這樣呢？\n\n我們得馬上回報這件事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58026] = {title = "當果姆開始噬神…", objective = "到特那瓦勒向塔許莫爾樹林長回報。", description = "我們在這裡沒什麼事可做了。我會送沙洛大師安全回到特那瓦勒。\n\n等你到了，就向樹林長回報我們的發現。\n\n假如果姆開始吃死掉的野性種子，並且吸收寄宿在其中的靈魂的力量，那我們就麻煩大了。", progress = nil, completion = "使用話語者，必然也能思考。截然不同的女王誕生了。\n\n森林憂慮不已。這絕不會是最後一個。", rewards = "林地看守者護脛靈魂看管者護腿夢棘腿甲星蔽馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][58027] = {title = "有人要來點軟泥嗎？", objective = "用瑪利雷斯的大鍋製作出一顆瘟裔軟泥怪。", description = "儘管我知道我們都急著完成藥水，但我要和你分享最重要的一課，就是耐心。\n\n當然了，耐心之外還有軟泥。\n\n在軟泥的幫助下，我們能讓實驗室恢復正常運作。就像我教你的一樣，把你的材料丟進大鍋混合。不斷攪動直到黏性剛好…\n\n喔，聽好了，你要像從來沒有調合過自己的有意識生物一樣！\n\n開始吧，我的學徒！軟泥正在呼喚你！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n瘟裔軟泥怪"}
MultiLanguageQuestData['tw'][58031] = {title = "科學應用", objective = "在瘟疫浸過的殘骸中收集瑪利雷斯的研究日誌的缺頁。", description = "<原本在瑪利雷斯桌上的老舊論文，現在變得支離破碎，還缺了不少頁。\n\n還能辨識的條目應該是瑪利雷斯在神智正常的時候寫下的，很可能是在瘟疫家族滅亡之前。\n\n如果你找到論文缺少的那幾頁，或許就能進一步瞭解瘟疫家族到底發生過什麼事。>", progress = nil, completion = "噢…這些又是什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58036] = {title = "危險的廢物收集", objective = "收集6件實驗室設備。", description = "啊，軟泥怪…我們最好的朋友，而且絕對實用！它們可以協助我們製造藥水。\n\n但我們的工具丟的到處都是，還泡在有毒的殘渣裡。要是我不重視實驗室安全，藩候史特拉達瑪一定會對我失望透頂！\n\n你的軟泥可以在殘渣中到處搜索，並稀釋瘟疫的有害成份。然後只要把器材從軟泥身上拔出來就成了！\n\n軟泥…要是少了它們，我們該怎麼辦？", progress = "你的軟泥怪派上用場了嗎？我敢說它一定管用！", completion = "你和軟泥簡直是合作無間！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58037] = {title = "融入獅群", objective = "向5隻被馴服的拉里翁自我介紹。", description = "佩羅迪斯堅持認為，芬連克斯比所有獨立自主的生物都還要優秀，總是能一絲不苛地完成命令。\n\n但這樣有什麼特色呢？你努力之後有獲得什麼回報嗎？\n\n拉里翁是非常出色的同伴，不過你必須先跟牠們培養感情。向我的獅群介紹你自己。你會發現，每隻拉里翁都有自己的性格。", progress = nil, completion = "我的獅群通常非常提防新面孔，不過牠們似乎已經接納你了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58038] = {title = "全天然潔牙玩具", objective = "到黃金牧場，從金輝雲行者身上收集5副雲行者的犄角。", description = "照顧拉里翁的重要工作就是滿足牠們，讓牠們開心。\n\n拉里翁必須確保牙齒既銳利又健康，所以需要咬東西。如果不提供東西讓牠們咬，牠們可能會變成破壞狂。\n\n牠們最喜歡的潔牙玩具是雲行者的犄角，而雲行者就棲息在附近的原野。拜託，收集一些犄角，讓獅群磨磨牙。", progress = "犄角非常適合當作野獸潔牙玩具，確保牙齒銳利又乾淨。", completion = "有了更多犄角可以咬，拉里翁一定會很高興！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58039] = {title = "逃逸的拉里翁", objective = "到黃金牧場尋找安狄拉，並將她送回內梅雅的居所。", description = "比起其他拉里翁，有些拉里翁會更加嚴格挑選建立羈絆的人。\n\n蘭提歐斯是我的夥伴，我願意將我的性命交付給他。我同樣喜愛其他拉里翁，不過他已經是我不可分割的一部分。\n\n我這裡有隻拉里翁名叫安狄拉，我遲遲都無法與她建立羈絆。她又再一次逃跑，在牧場裡到處亂跑，我擔心她會惹出麻煩。\n\n可以請你找到她，並且帶她回家嗎？", progress = nil, completion = "太神奇了！安狄拉似乎對你很有好感。你有沒有興趣進一步與她建立羈絆？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58040] = {title = "一手持槍，一手執韁", objective = "到雄翼棲息地殺死5隻雄翼雲羽鷹。", description = "芬連克斯有什麼好的，拉里翁可是有個大大的優點。\n\n翅膀！\n\n與拉里翁建立羈絆後，無論在地上或在空中，牠都能陪著你一起狩獵。\n\n帶著我的標槍和安狄拉，然後到原野上狩獵雲羽鷹，你就能親自體會有拉里翁做伴的好處！", progress = nil, completion = "看到拉里翁飛上天空，協助撲殺獵物，真是令人滿意的體驗。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58041] = {title = "供養獅群", objective = "收集10個雲羽鷹精華。", description = "就算是暗影之境的生物也需要進食。牠們的進食方式或許與你世界的生物不同，但本質極為相近。\n\n獅群最喜歡的獵物是附近的年輕雲羽鷹。帶安狄拉去狩獵覓食，向她證明你能對獅群有所貢獻。", progress = "拉里翁的羈絆會隨著狩獵逐漸加深。與安狄拉合作，收集有助於培養感情的食物。", completion = "如果想要贏得忠誠，就必須為獅群提供食物。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58042] = {title = "乘著拉里翁的雙翼", objective = "騎乘安狄拉，然後完成飛行課程。", description = "身為無法飛行的生物，你永遠不能感受與夥伴一同飛翔的快感，這真是一大遺憾。\n\n不過…你還是有機會與安狄拉一同飛翔。\n\n安狄拉似乎相當信任你，我之前從未看過她這樣對其他人。你要不要試一下飛行課程？\n\n與安狄拉一起飛上天空，然後試著穿過那些圓環。記得不要偏離路線，或花太多時間穿過圓環，不然她就會把你拋在身後！", progress = "我安排了飛行課程，訓練拉里翁聽從空中指令。牠們知道該去哪裡！", completion = "翱翔空中的快感，還有拉里翁溫馴的振翅聲…\n\n儘管我自己也有翅膀，但感覺完全不一樣。", rewards = "審判志士腿甲純潔志士護腿謙恭志士護腿英勇志士馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][58045] = {title = "疫濃於水", objective = "殺死狡詐的寇林。", description = "靠近點，我的學徒…我有一個超級重要的任務！\n\n最近有個死靈法師來到我們的家族，他是巫妖藩侯辛丹派來的！他似乎很有禮貌，一直想要伸出援手，協助女士完成最不穩定的創作品。\n\n但我變聰明了，我的學徒。他一直鬼鬼祟祟，刺探我們最機密的實驗…\n\n他打算偷走我們的軟泥！一定是！\n\n你應該嚴正警告他一下，別讓我們的朋友受到任何傷害！", progress = nil, completion = "我們的軟泥怪安全了，親愛的學徒！", rewards = "受寵學徒手套威嚇新兵粉碎手套受歡迎弟子長手套受寵狂熱者護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][58060] = {title = "深夜市集", objective = "到瑞文崔斯的深夜市集，將倉促打包的包裹交給塔魯卡。\n\n已提供物品：\n", description = "<德拉寇示意你壓低聲音>\n\n我需要一些協助，我保證一定會給你豐厚的報酬。\n\n禍孽森林的邊緣有一些廢墟，仲介者在那些廢墟中建了一個市集。他們不讓我回去那裡，原因是他們認為我的商品不符合他們的標準。\n\n但你不一樣…你是淵喉行者！用這個包裹去跟他們換一些亞登曠野的蘇莓回來。\n\n千萬別說是我派你去的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58062] = {title = "貴客臨門", objective = "到深夜市集與塔瑟菈交談。", description = "聽著，你顯然是在幫德拉寇跑腿。\n\n塔瑟菈是這個地方的老大，我相信她會很樂意跟你這樣實力高強的人做生意。\n\n她在山丘上面的莊園裡面，建議你別讓她久等。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58068] = {title = "…就算是最離譜的要求！", objective = "查明大道勇士的需求。", description = "競賽粉絲，是吧？光是在旁邊看比賽，你應該不滿足吧？\n\n我會給你一個小工作，不但可以幫上我的忙，也讓你有機會見見其他有名的競爭者。\n\n如你所見，我們剩下的三個家族都派遣勇士前來參加征服競賽。和他們談談，看看他們需要什麼。", progress = nil, completion = "少了你的協助，我們必敗無疑。真的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58069] = {title = "珍品：汎希爾日誌", objective = "到瑞文崔斯的深夜市集，將汎希爾日誌交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "&lt;你獻上的日誌讓塔瑟菈精神一振。&gt;\n\n啊，這裡面寫了什麼？\n\n看起來像是個人日誌。真是有意思。有一篇居然是控罪者寫的！\n\n能夠拜讀絕對是一大樂事。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58070] = {title = "珍品：獵魂者之刃", objective = "到瑞文崔斯的深夜市集，將獵魂者之刃交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "你今天帶了什麼給我？\n\n喔，我知道了，是獵魂者細劍的刀刃。對於那些想進一步鑽研決鬥技巧的人來說，這東西很有價值。\n\n&lt;name&gt;，謝謝，我的客人一定會開心到不行。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58071] = {title = "珍品：挖掘工爛泥瓶", objective = "到瑞文崔斯的深夜市集，將挖掘工爛泥瓶交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "那是什麼可怕的臭味？\n\n&lt;你將瓶子呈獻給塔瑟菈。&gt;\n\n那好吧，雖然氣味非常難聞，不過裡面的東西價值不菲。泥掘者就是用這種原初軟泥製造而成的。\n\n不管其他人開價多少，我出雙倍。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58072] = {title = "珍品：石化的石魔", objective = "到瑞文崔斯的深夜市集，將石化的石魔交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "那真的是我想的那個東西嗎？\n\n&lt;塔瑟菈仔細檢查石魔。&gt;\n\n保存得很好！我已經等不及想研究每個細節了。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58073] = {title = "珍品：國王的肖像", objective = "到瑞文崔斯的深夜市集，將國王的肖像交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "很棒的作品，每個細節都栩栩如生。\n\n了不起的大發現，&lt;name&gt;。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58074] = {title = "珍品：靈魂記錄簿", objective = "到瑞文崔斯的深夜市集，將靈魂記錄簿交點塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "這份名單上寫滿密密麻麻的名字。這對我的研究很有幫助。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58075] = {title = "珍品：泥掘者的工具桶", objective = "到瑞文崔斯的深夜市集，將泥掘者的工具桶交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "嗯，這是什麼？啊，俗話說是吃飯用的傢伙。\n\n我其實對這沒興趣，不過我有些對基礎建設感興趣的客人，一定會對這件收藏品愛不釋手。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58077] = {title = "珍品：完美設計的手持鏡", objective = "到瑞文崔斯的深夜市集，將完美設計的手持鏡交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "真是巧奪天工。\n\n這一定是出自勞倫特之手，非常適合將人無聲無息地傳送到瑞文崔斯各地。\n\n我們一定會善加利用的。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58078] = {title = "珍品：一瓶雷德拉夫酒", objective = "到瑞文崔斯的深夜市集，將一瓶雷德拉夫酒交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "太奢華了！雷德拉夫酒！\n\n我現在陷入兩難，到底應該自己收藏起來，還是應該用這瓶夢寐以求的好酒換取其他地方的貴重神器。\n\n對了，這是你的報酬。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58079] = {title = "珍品：完好如初的懼蝠尖牙", objective = "到瑞文崔斯的深夜市集，將完好如初的懼蝠尖牙交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "你帶來什麼東西？啊，原來是完整的懼蝠尖牙。\n\n考量到懼蝠咬人總是毫不留情，的確是稀罕的寶貝。謝謝你能送這個來。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58080] = {title = "珍品：閃亮的櫻草項鍊", objective = "到瑞文崔斯的深夜市集，將閃亮的櫻草項鍊交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "喔，太漂亮了吧。真是有意思。\n\n&lt;塔瑟菈仔細檢查項鍊。&gt;\n\n他們是從哪裡弄到這種材料的？我已經好一陣子沒看到了。看來值得研究一番。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58081] = {title = "珍品：愛與恐懼", objective = "到瑞文崔斯的深夜市集，將愛與恐懼交給塔瑟菈。\n\n已提供物品：\n", description = "仲介者會對這件東西非常感興趣。\n\n根據你先前與深夜市集的約定，你應該把東西交給塔瑟菈。\n\n你將會得到豐厚的獎勵。", progress = nil, completion = "詩集？汎希爾人寫的？\n\n真是太出乎我意料之外了。我已經等不及想深入分析寫作風格。", rewards = "您會收到：\n\n小顆靈魄球商集團交易容器"}
MultiLanguageQuestData['tw'][58084] = {title = "靈魂陷阱", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58086] = {title = "謊言之主", objective = "擊敗戴納瑟斯王。", description = "再一次面對死亡的獠牙，拔出劍來，笑看遺忘。我們一起迎戰死亡，讓它一敗塗地吧。\n\n確定自己已經做好持久戰的準備，只要我們一現身，就再也沒有後悔的餘地。\n\n等你準備好了，就將中央的鏡子對準納撒亞城的大門，我們會以快狠準的方式，出現在燃燒的敵人面前。", progress = nil, completion = "他做了什麼？", rewards = "石鑄頭罩痛苦赦免長袍石鑄鍊衫獵魂者外衣夜幕護軀痛苦赦免風帽獵魂者頭盔夜幕頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][58087] = {title = "摧毀能量來源", objective = "在懼珠淺灘毀掉3枚納瑟席儲能裝置。", description = "喚潮者聶札菈是一切的主導者。只要我們能除掉她，剩下的納迦就會分崩離析。但要解決她可不容易，因為她從附近儲能裝置汲取能量，架起一道保護她的魔法屏障。\n\n如果我們能摧毀源頭，我們就能消滅聶札菈。", progress = nil, completion = "這下喚潮者聶札菈沒辦法躲在屏障後面了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58088] = {title = "生氣勃勃", objective = "到挑戰者大道尋找擁有強化藥水的某人。", description = "我為你的「天賦」想出了一個合適工作。\n\n你聽說過瘟疫家族嗎？他們是劇毒與藥水的製作者，後來遭受悲劇性的意外…真的…真的很丟臉。\n\n但問題就出在這裡：長年以來我一直使用瘟疫設計者的藥水讓我在競技場表現得更好。沒有這些藥水，我覺得打鬥開始拖泥帶水。\n\n仲介者身上有這種藥水，但他們不喜歡我，你可以幫我弄些藥水來嗎？", progress = nil, completion = "我知道是挑釁者米諾娃派你來的，在求勝方面，她絕不落人後。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58089] = {title = "測試任務", objective = nil, description = "是任務！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58090] = {title = "副作用", objective = "將藥水送給挑釁者米諾娃。", description = "挑釁者米諾娃使用強化藥水的話，會讓我們難以預測下注方向。這樣非常不健康，尤其是在我們的獲利上！\n\n交了費用以後，歐拉瑞納會給你「特殊」的強化劑，米諾娃絕對無法抵抗。這款藥水能將飲用者變成終極戰士，但也會讓他們了解適可而止的道理。\n\n我等不及想看到米諾娃下一次在競技場上的表現了！", progress = "這真是出人意表。", completion = "挑釁者米諾娃必須喪失她的比賽資格。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58092] = {title = "贖罪之殿：你的赦免", objective = "到贖罪之殿內殺死宮務大臣。", description = "比起宮務大臣在贖罪之殿為所欲為所帶來的危害，這些廳堂外的墮落根本不值一提。\n\n如果你真的打算撥亂導正，你就必須親手解決你造的孽。\n\n彌補你自己的過錯，殺死宮務大臣，那麼我們就能讓這個地方再次變得井然有序。", progress = nil, completion = "這是讓贖罪之殿重返榮耀的一大步…但不是最後一步。\n\n我應該立刻向控罪者報信。", rewards = "您會收到：\n\n宮務大臣的披風"}
MultiLanguageQuestData['tw'][58093] = {title = "被遺忘的使命", objective = "到赦罪墓穴找控罪者。", description = "我不是想跟你爭執，淵喉行者。\n\n宮務大臣和他可惡的追隨者用他們墮落的儀式玷汙這些大廳。任意虐待靈魂，摧毀它們的可能性，只為了追求可悲的力量。\n\n控罪者永遠不會容許這種事發生。我聽說你跟她還有一些往來，如果真是如此，請將這裡的情況告訴她。\n\n她會教訓一下這些墮落的狗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58095] = {title = "苦痛劇場：需要幫手", objective = "進入苦痛劇場地城並擊敗其中的勇士。", description = "啊，兄弟，巫妖勇士已經退出比賽了。\n\n好吧，那…看來我們有空缺了！有沒有想要取代她的？\n\n或許可以替他們家族提高勝率？\n\n有人嗎？\n\n噢，<name>！你自願真是太好了。不準備就直接參賽，就是最能磨練自己的方式！\n\n記住，不是所有人都能贏。", progress = nil, completion = "表演得真精彩，淵喉行者。", rewards = "您會收到：\n\n束縛防護骨匣"}
MultiLanguageQuestData['tw'][58096] = {title = "來自萊加尼的補給品", objective = "到恆春谷與張古交談，取得你的獎勵。", description = "萊加尼非常感謝你為我們做的每件事情。\n\n請讓我們用這些補給品表達感激之情，如果你願意繼續幫助我們，我保證之後會提供更多補給品。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n萊加尼補給品艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58097] = {title = "來自奧丹姆協議者的補給品", objective = "到奧丹姆與補給官蔻菈交談，取得你的獎勵。", description = "奧丹姆協議者非常感謝你為我們做的每件事情。\n\n請讓我們用這些補給品表達感激之情，如果你願意繼續幫助我們，我保證之後會提供更多補給品。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n奧丹姆協議者補給品艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58103] = {title = "驕傲的野獸或精密的機械", objective = "與佩羅迪斯和內梅雅會面，然後挑隻坐騎。", description = "希望你與芬連克斯相處過後，能讓你下定決心，<name>。\n\n我們去找內梅雅吧。到時候，你就能判斷誰的生活方式更加卓越，值得你追尋。", progress = nil, completion = "完成了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58104] = {title = "籌劃演出", objective = "與月莓女士交流。", description = "你是凜冬之廷的新勇士，當然需要向其他暗夜妖精隆重介紹一下。場面必須夠盛大、夠前衛，讓人永生難忘。要讓大家確確實實認識你這個人，還有你的世界。一切都要…不同凡響。\n\n一般來說，這種盛大的場面都需要花費無數時間籌劃。不過我們現在沒有這麼多時間！只好見機行事了。\n\n<月莓眨了眨眼。>\n\n跟我交流一下，我會挑出幾個重點！然後我會確保這是一場千載難逢的表演！", progress = nil, completion = "喔，太好了！你來了！沒時間排練了，不過那應該不是什麼大問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58122] = {title = "為了部落", objective = "在駐奧格瑪大使館與黑衛大使見面。", description = "真是場精采的冒險，<class>！\n\n有這麼多值得探索…這麼多值得發掘。這真是令人開心的時刻！\n\n我們會讓部落的盟友瞭解，身邊有些聰明的狐狸人能帶來什麼優勢。\n\n請到奧格瑪大使館和大使會面。\n\n<name>，我在那裡等你！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n狐狸人外袍"}
MultiLanguageQuestData['tw'][58124] = {title = "陌生人在陌生地", objective = "與克羅米交談。", description = "你好，我是黑衛大使。\n\n我很榮幸歡迎你來奧格瑪，<race>。\n\n<黑衛露出了難以讓人放心的笑容。>\n\n你即將踏上一生中最精彩的冒險旅程，我向你保證…呃…\n\n搞什麼啊？我整天都在講相同的台詞打招呼。我受夠了。\n\n去沙漏頂端那邊找克羅米，然後再去找你的特使。快去吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58127] = {title = "審判官罪孽石", objective = "有了我的文獻，識別並重新製作一個審判官的罪孽石應該不是什麼太困難的工作。", description = nil, progress = "有了我的文獻，識別並重新製作一個審判官的罪孽石應該不是什麼太困難的工作。", completion = "對於像你這麼厲害的淵喉行者來說，打倒審判官應該不成問題吧。\n\n獵殺愉快。", rewards = "您會收到：\n\n審判官罪孽石"}
MultiLanguageQuestData['tw'][58128] = {title = "高階審判官罪孽石", objective = "即便有了我的文獻，識別並重新製作一個高階審判官的罪孽石仍是困難重重。", description = nil, progress = "即便有了我的文獻，識別並重新製作一個高階審判官的罪孽石仍是困難重重。", completion = "高階審判官是極為強大的敵人。如果打算直接挑戰他們，最好帶上一、二個朋友。\n\n獵殺愉快。", rewards = "您會收到：\n\n高階審判官罪孽石"}
