MultiLanguageQuestData['tw'][58146] = {title = "為了聯盟", objective = "在駐暴風城大使館與穆爾加德大使見面。", description = "身為大工匠暨地精和機械地精的領袖，我很榮幸能歡迎你們加入聯盟！\n\n這個充滿冒險的世界，正在機械岡城牆外面等著你去探索。\n\n在你準備好之後，踏上傳送器。穆爾加德大使會在暴風城大使館等你。\n\n我們會為你提供多種潛在的進化管道。\n\n好好選擇、不斷改良，然後記得分享你的資料。", progress = nil, completion = "啊，你來了，&lt;name&gt;！我們一直在調查…呃…我是說泡茶等你！", rewards = "您會收到：\n\n機械岡地精外袍安杜因‧烏瑞恩國王的信"}
MultiLanguageQuestData['tw'][58147] = {title = "陌生人在陌生地", objective = "在暴風城找到克羅米。", description = "歡迎來到暴風城，<class>。是我邀請你來探索我們這座美好的城市。嘿，你看起來很適合夜生活。在暴風城有很多音樂飄揚的出名旅店！\n\n啊，但你之後再去吧。有頭青銅龍說她想見你。她就在附近的樹下，而且竟然坐在沙漏上！\n\n然後，有名機械地精特使正等著歡迎你造訪本市。聽起來你今天會很忙喔！\n\n祝你在這一切順利，<name>！", progress = nil, completion = "你會成為一位很棒的&lt;race&gt;代表。\n\n出門在外也要保持閃閃發光，朋友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58151] = {title = "恩若司的爪牙", objective = "在幻象中擊敗20個恩若司的爪牙。", description = "或許有一天，這些越發黑暗、卻又熟悉無比的低語聲，會蓋過環繞著我們的嚎叫之風。\n\n一定要想想辦法。\n\n進入黑暗之中，<name>，打倒敵人。", progress = nil, completion = "你的功績有目共睹。這方面我敢打包票。", rewards = "您會收到：\n\n永恆靈魂之息腐化的紀念物腐化的紀念物聚合幻象聚合幻象"}
MultiLanguageQuestData['tw'][58155] = {title = "黑暗中的援手", objective = "從幻象中救出8個靈魂。", description = "想像一下，被困在一個你從來都不知道的世界、一個就連你自身存在都撲朔迷離的現實裡的那種感覺。\n\n思緒、恐懼和邪惡的欲望遮蔽了你的心智，伴隨著無法抵抗的誘惑。\n\n有太多人沒能擋住這樣的誘惑，迷失在無邊黑暗中，但仍有幸免於難之人。\n\n盡你所能去保護那些奮勇對抗黑暗的人。我們絕對不能讓他們倒下。", progress = nil, completion = "輕蔑的低語聲正在等候。保持警覺，&lt;name&gt;。", rewards = "您會收到：\n\n永恆靈魂之息腐化的紀念物腐化的紀念物聚合幻象聚合幻象"}
MultiLanguageQuestData['tw'][58156] = {title = "征服無邊黑暗", objective = "在幻象中驅散恩若司的腐化。", description = "黑暗蔓延。循環不止。\n\n盡你所能去封鎖恩若司的勢力。如果我們不去對抗這股腐化，那麼我們終有一天會被捲入無盡的黑暗當中。", progress = nil, completion = "你對遏止腐化所做出的貢獻難以估計，&lt;name&gt;。", rewards = "您會收到：\n\n永恆靈魂之息腐化的紀念物腐化的紀念物聚合幻象聚合幻象"}
MultiLanguageQuestData['tw'][58157] = {title = "祝你好運", objective = "重現燃燒軍團第三次入侵艾澤拉斯。", description = "節目就要開始了！你…你要穿這樣？好吧，我想應該沒差。\n\n為了隆重介紹你，我們要忠實重現最近發生在埃辛諾斯上的戰役和事件，呃，艾澤拉斯。那是你來的地方，對吧？\n\n星光劇團非常熱心，自願協助我們完成這次表演。我們也邀請幾個特別來賓客串演出！\n\n別擔心劇本的事。反正這是你的故事！\n\n盡量別把舞台弄到血淋淋就是了。舞台很難清洗。", progress = "至少還不算…太糟。", completion = "還不錯！雖然不好，但還不錯。快一點，我們必須協助搭設下一場的舞台！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58158] = {title = "第四次大展…呃…大戰", objective = "搭設舞台，然後協助重現燃燒軍團殞落後的事件。", description = "你的戲劇形式自我介紹的下一幕要開演了：艾澤瑞斯年度大戲！\n\n艾澤拉斯。好吧，我實在記不住每個世界的名字。\n\n幫忙搭設舞台，然後回來這裡。你必須客串演出幾個其他角色，才會再次以你自己的身分登場。\n\n快點行動吧！我們還有很多事要做！", progress = nil, completion = "老實說，我從沒看過像這樣的表演。\n\n現在…最後盛大的收場！這場在你的世界開打的大戰，一定會讓凜冬之廷的人看得津津有味！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58159] = {title = "我的動機是什麼？", objective = "表演最後一幕！", description = "現在，來到最後一幕！這場驚人的表演會重現艾澤索斯最近面臨的考驗！\n\n<羽光看了一下小抄。>\n\n艾澤拉斯。隨便啦。這次登場的有：人造的神、強大的冰雪魔法公主、惡名昭彰的女王，還有最詭異恐怖的遠古異魔。像這種充滿末世感的好戲，有誰不愛呢？\n\n你這次要繼續飾演你自己，就去…做一些英雄該做的事情吧！", progress = nil, completion = "相當不錯的表演！\n\n大家現在應該都更了解你的世界的故事，還有你在其中扮演的角色。\n\n下次的舞台設計會更…完善一點。現在的話…\n\n&lt;月莓朝伊瑟拉點點頭。&gt;\n\n你的朋友好像有話跟你說。別講太久，我們還要在森林之心舉行最後的入盟典禮。", rewards = "您會收到：\n\n夢輝符文雄鹿"}
MultiLanguageQuestData['tw'][58160] = {title = "為了女王和林地！", objective = "與伊瑟拉一起返回心之樹，以加入誓盟。", description = "真是讓人震驚的表演…各方面來說都是。\n\n我不在的這段時間，艾澤拉斯發生了好多事情。但有一場我的夢，沒有出現在舞台上。\n\n我夢見泰蘭妲被黑暗籠罩、被憤怒和復仇的渴望扭曲。我看見禁忌的儀式、黑夜戰士的覺醒，還有必然招致悲劇收尾的狩獵。那一定也是真的。\n\n<伊瑟拉搖了搖頭。>\n\n凜冬女王在森林之心等你。我們還是出發吧。", progress = "歡迎加入獵者。", completion = "你在這裡的舉動也會對帷幕外的世界產生影響。幫助森林，或許也能拯救凡間的所有世界。", rewards = "您會學到：\n\n狂野靈魂\n\n下列法術會施放在您身上：\n\n提高所有抗性 15\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58161] = {title = "消失的森林", objective = "找到帕提克。", description = "能佔用你一點時間嗎，朋友？\n\n沒多久之前，有一個名叫帕提克的希瓦爾來我的林地尋求協助。他說他的村落遭到果姆的攻擊，處於全面崩塌的危險。我那時告訴他，我們沒有辦法分派任何士兵，但歡迎他們的人撤到我們這邊避難。\n\n不過，自從他離開到現在已經過了好一段時間，而且那個區域再也沒有傳出任何消息。\n\n能請你去調查一下嗎？他來自東北方。", progress = nil, completion = "不，不…發生了什麼事？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58162] = {title = "神秘的面具", objective = "收集15具無臉面具。", description = "村落、我的朋友，都沒了。他們都不在了。\n\n我從附近林地回來，發現他們變成…這樣。就連我最好的朋友，拉瓦希也在內！他朝我衝來，心中只有怒火。\n\n現在他們都帶著面具，也失去了本性。\n\n拜託你，讓他們脫離這樣的命運。把他們的面具帶來給我，或許我們就可以解開這個謎團。", progress = "那麼多人都出事了，我不覺得我離開了那麼久…", completion = "從這些面具一定能找出村民為什麼被附身的線索。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58163] = {title = "絕望中的解決之道", objective = "找到遺失的日誌書頁。", description = "<一本老舊但手工精細的日誌吸引了你的目光。\n\n翻閱其中的內容後，很顯然這本日記屬於暗夜妖精團體中的重要人士所擁有。最後幾頁被撕掉了。\n\n或許找到其他幾頁之後，就能夠協助帕提克查明此地發生了什麼事。>", progress = "你拿著的是什麼東西？", completion = "&lt;帕提克飛快的看完最後幾頁。臉上變得毫無血色。&gt;", rewards = "凋林裂片您會收到：\n\n"}
MultiLanguageQuestData['tw'][58164] = {title = "狂熱心智", objective = "救出8位受困的暗夜妖精。", description = "我的族人還有倖存者！我們一定要拯救他們！\n\n囚犯被關在籠子裡，散布在整座山脊，靜候他們面前的可怕命運。\n\n拜託你，讓他們重獲自由。我們不能讓拉瓦希身上的事，發生在他們身上！", progress = nil, completion = "真少…不過，每救出一個人，就表示我們多一位對抗這場瘋狂的朋友！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58165] = {title = "斬草除根", objective = "殺死苦飛、菲歐娜‧荒棘和『狂旋風』黎沃爾。", description = "這就是我最擔心的，朋友。整個村落都被轉化了，就像拉瓦希一樣。\n\n黎沃爾很快就會轉化其他長老。他們都是各自領域中的佼佼者。勇敢的菲歐娜，靈巧的苦飛…\n\n要這麼說讓我痛苦萬分，但一定要殺了他們。為了亞登曠野和林地著想，必須趕在他們為害整塊土地之前，殺死我們先前的領袖！", progress = "如果他們墮落了，那我們還有什麼希望可言？", completion = "&lt;帕提克深吸一口氣然後面色發白。&gt;\n\n那就是所有人了，對嗎？很好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58166] = {title = "不明的攻擊者", objective = "到特那瓦勒將奇怪的符文石交給塔許莫爾樹林長。\n\n已提供物品：\n", description = "這一定就是他找到的石頭。我不認得這個印記。\n\n你應該把這個帶給附近的樹林長。他們不但睿智，而且保有森林中的許多知識，包含遠方的界域在內。他們知道該怎麼做。", progress = nil, completion = "年輕人，你在急什麼？", rewards = "靈魂看管者腕輪林地看守者護臂夢棘腕甲星蔽護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][58167] = {title = "預防措施", objective = "在幻象中摧毀3個虛無傳送門。", description = "一波波的黑暗，持續侵襲著我們的世界。恐怕我們腳邊的黑水馬上就要淹沒我們了。或許是時候該採取不同的做法了。\n\n一路深入扭曲國度，並找出他們的黑暗之門。如果能延緩他們的腳步，或許可以為我們爭取到足夠的時間，揭露對方的致命弱點。", progress = nil, completion = "我們可以稍微喘口氣了。希望這種情況可以持續下去。", rewards = "您會收到：\n\n永恆靈魂之息腐化的紀念物腐化的紀念物聚合幻象聚合幻象"}
MultiLanguageQuestData['tw'][58168] = {title = "一個黑暗、糟透了的現實", objective = "在幻象中擊敗6名暗凝看守者。", description = "他們的眼睛一直盯著我們，<name>，從陰影中監視著我們的一舉一動。難怪我一直覺得我們的努力…有所不足。\n\n並不是要你來獨立承擔這個過錯。我們很久之前就該猜到這一點了。\n\n如果我們想要抱持著有意義的期望繼續努力下去，就得在暗地裡行事。\n\n我們的老朋友提供了一種藥劑，可以讓敵人行蹤暴露。雖然它可能有些…未知的副作用，但可以讓飲用者看清無邊黑暗的真實面貌。", progress = nil, completion = "罩子放亮點，&lt;name&gt;。", rewards = "您會收到：\n\n永恆靈魂之息腐化的紀念物腐化的紀念物聚合幻象聚合幻象"}
MultiLanguageQuestData['tw'][58174] = {title = "志士的職責", objective = "返回志士之墓。", description = "我認為，我們都一致同意這樣的回覆…有點空洞。\n\n我選擇相信我們已經盡了最大的努力，我們所有人。我不清楚接下來會發生什麼事，但或許道路會自行揭示。在這段期間，我和佩拉苟斯會回到志士之墓，休息片刻。\n\n我們在那邊見，但是不用急。", progress = nil, completion = "&lt;克蕾雅對你露出和煦的笑容。&gt;\n\n這表示你打算留下嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58175] = {title = "永恆熔爐", objective = "到永恆熔爐找米卡尼寇斯。", description = "首席熔爐士已經接下重新打造晉升紋章的重責大任。\n\n但需要的工具或材料也是非比尋常，包括初代熔爐士之錘「斐斯托斯，紀元創生者」。它位在永恆熔爐的初代熔爐士聖壇中。\n\n棄誓者已經佔領這個熔爐，源源不絕地製造自己的百衛機兵大軍。你必須到熔爐找米卡尼寇斯，擊退棄誓者，然後取回斐斯托斯，讓它為我們所用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58176] = {title = "侍者同根生", objective = "釋放5名被抓走的鍛造助手。", description = "喂！淵喉行者！\n\n以前熔爐非常忙碌，很多鍛造助手各司其職！\n\n然後棄誓者來了，有些人聽命於他們，加入他們那一邊。\n\n不過不是全部！沒錯，救出鍛造助手，他們就能幫助我們。非救他們不可！", progress = nil, completion = "你辦到了！今天有很多鍛造助手回來。或許有一天其他人也會回來？\n\n我們會幫忙的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58177] = {title = "重新提煉", objective = "從百衛機兵身上收集污化的百衛機兵組件，然後放入永恆熔爐熔煉，收集8塊淨化金屬。", description = "我會找到斐斯托斯。在此同時，給你一個任務！\n\n棄誓者利用我的熔爐製造他們的百衛機兵大軍，他們的邪惡企圖扭曲了我們使用的金屬！\n\n摧毀他們的百衛機兵，拿走它們的零件。將零件放入熔爐中熔煉，淨化那些金屬，然後回來找我。\n\n我的計畫會用到很多金屬。", progress = "我把資源藏在這裡，結果全被棄誓者偷走了！我可咽不下這口氣。", completion = "我們應該把這種金屬用在很多地方，例如紋章，還有我的巨人！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58178] = {title = "永遠的夥伴", objective = "協助米卡尼寇斯完成他最好的作品。", description = "返回堡壘之前，還有一件事要做。\n\n擊敗棄誓者和他們的百衛機兵大軍！\n\n這個巨人可以助你一臂之力。它可是我有始以來最好的作品！\n\n我需要有人來助我一臂之力，你雀屏中選了。", progress = nil, completion = "體現我內在力量的夥伴。\n\n無與倫比的百衛機兵！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58179] = {title = "最稱手的工具", objective = "收集米卡尼寇斯的魂鋼鉗、閃亮的漂流法珠核心及恩典花瓣薰香爐。", description = "米卡尼寇斯不是普通的侍者，他很有智慧！很有才華！是我們當中最聰明的！\n\n而且非常特別！\n\n沒有自己的工具，他就做不了事。棄誓者把他的工具隨便丟在熔爐附近！\n\n你想要重新打造紋章？那就取回他的工具！", progress = "我沒辦法在這種環境下工作。", completion = "西卡派你去取回我的工具？\n\n她很清楚我需要什麼東西，才能發揮所長。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58180] = {title = "斐斯托斯，紀元創生者", objective = "從監督者阿提克斯身上取回斐斯托斯，紀元創生者。", description = "根據西卡的報告，棄誓者幾乎無所不在。他們不只接管了生產作業，也佔領了高地！\n\n他們從山崖上排兵布陣，捎信給他們的領導者。\n\n他們還洗劫初代熔爐士聖壇，拿走了她的錘子，我的錘子！\n\n擊敗他們的指揮官、取回斐斯托斯。請馬上動身！", progress = "沒有斐斯托斯，我們就無法打造紋章。", completion = "斐斯托斯回來了！勝利的一天。\n\n感激不盡，朋友。這把錘子已經傳承了無數紀元！我這雙技藝精湛的手才是它的歸宿。", rewards = "無私收集者腕甲無私引渡者護腕無私看守者裹腕無私熔爐士裹腕您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58181] = {title = "打造基座", objective = "完成晉升紋章。", description = "紋章就快完成了。\n\n我決定把最後一道手續交給你完成。\n\n你貢獻良多。好了，接過斐斯托斯，敲下這最後一擊！", progress = nil, completion = "太完美了！\n\n美到不行，對吧？不過還差一點，慢工才能出細活。", rewards = "您能選擇下列奬勵中的一個：\n\n勇氣芬連克斯\n\n您還會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58182] = {title = "瓦解敵人", objective = "騎乘布隆，然後到永恆熔爐擊敗30個棄誓者士兵，同時拆解2個巨像。", description = "棄誓者正在動員！\n\n我們不能讓他們進軍。\n\n與布隆同調，將你的力量分享給他。\n\n集我們三人之力，摧毀這支新生的機兵大軍吧！", progress = nil, completion = "太爽了！有了你的力量，布隆又變得更強了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58183] = {title = "熔爐士的朋友", objective = "返回樂土堡找軍政官阿德雷特斯。", description = "有了斐斯托斯，我們就能開始打造紋章了。\n\n我們回去樂土堡吧。勝利在望！", progress = nil, completion = "米卡尼寇斯不久前帶著他新做的百衛機兵回來了，那東西的確相當特別。\n\n當然，斐斯托斯又回到琪瑞安手中，也是令人振奮的好消息。御靈者一定會很高興。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58184] = {title = "老派的方法", objective = "到內梅雅的居所與內梅雅談話。", description = "你有馴服芬連克斯的才能，相信你能在這裡幫上不少忙。\n\n當然，在你下定決心之前，我懇求你攀越山丘，向我的對手「內梅雅」引薦自己。她相信，比起我完美的芬連克斯，她那不可理喻又脫序的拉里翁才是更好的夥伴。\n\n體驗她的生活方式之後，你就會知道我這裡實在好上太多了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58185] = {title = "沒有靈魂的成功", objective = "到煉火哨站與佩羅迪斯談話。", description = "拉里翁似乎真的很喜歡跟你相處，尤其是安狄拉。\n\n希望你已漸漸瞭解，與自由奔放的生物相處，感覺有多麼微妙。\n\n現在你必須去找佩羅迪斯，他就在山丘下面。他的芬連克斯或許能力出眾，但是與他們相處總有一種揮之不去的空虛感。\n\n我敢說，跟芬連克斯相處過後，你只會更加喜歡拉里翁。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58207] = {title = "瘋狂逃跑", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58208] = {title = "衝擊準備", objective = "在船內尋找蓋瑞克船長。", description = "暖身運動結束了。我可以告訴你，你和其他生力軍倍受期待。\n\n等一下…那是什麼聲音？有什麼大東西朝我們的方向逼近了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58209] = {title = "堅守陣地", objective = "與士兵柯爾比劃。", description = "我希望這場雨不是壞兆頭…我原本以為這只是一場單純的救援任務。\n\n你來和我比劃比劃。我們得確定著陸之後你有本事照顧好自己。\n\n來看看你有什麼本事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58211] = {title = "滿滿幫浦", objective = "在冒泡淤泥附近使用淤泥幫浦，收集15個回收的齒輪。", description = "在亡城崩解時，有很多零件都埋進了外面奔流的河床裡。希望你有決心要修復這個地方，因為我們要把這些零件挖回來！\n\n拿著這個幫浦。如果你發現了某處的淤泥在冒泡，那就是有零件的徵兆！\n\n只是把它拉上來的時候，得要小心一點！你可能會碰上一些阻礙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戰鬥之焰跳動的憎惡體核心血煉勳章血煉披氅腫脹怪異心臟束縛防護骨匣穩定的瘟疫品種通靈塔聚焦水晶保存良好的超凡腦殼魔法防護的論文血絲長袍鋼核胸鎧\n                            顯示 16 更多                        肉鱗鎖甲護胸鋼核戰靴血絲足靴屍皮長靴鋼核束腰血絲之索肉鱗腰帶肉鱗裹腕血煉骨鋸瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐感激禮賜"}
MultiLanguageQuestData['tw'][58214] = {title = "緊急照護", objective = "到波拉勒斯找凱爾希‧鋼火。", description = "時間算得真準，<name>。\n\n凱爾希‧鋼火一直在對主城發送通訊，尋求協助。\n\n梅卡托克的情況十分危險，時間寶貴。\n\n快點前往波拉勒斯港，她正在等你。", progress = nil, completion = "你來得正是時候。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58216] = {title = "血盆大口", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58221] = {title = "追求平等", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58229] = {title = "振奮咆哮", objective = "在奧丹姆殺死3個稀有的恩若司爪牙。", description = "我們的土地被古神的爪牙感染。他們攻擊每一條前線，甚至襲擊我們士兵的內心。\n\n我們的部隊撐不了多久。我們得打出決定性的一擊，讓他們重振一些士氣。\n\n想辦法找出最巨大、最滑溜、滿臉觸手的怪物，然後打敗它們。我的手下將會以你為榜樣，重新振作起來。", progress = nil, completion = "我的弟兄會因為你今天的勝利打起精神。\n\n&lt;class&gt;，蘭姆卡韓欠你一份人情。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58230] = {title = "弄瞎眼睛", objective = "到奧丹姆的雅奇涅特原野殺死6個汙穢觀察者。", description = "最近，有一股奇怪的力量一直在干擾我的視野。永不休息的眼球刺穿帷幕，粉碎了我的千里眼。\n\n敵人的眼珠窺視我們的靈魂深處，穿透我們的心智。如果我們真的想要清除這塊土地上的詛咒，就要將它們連根鏟除。", progress = nil, completion = "那些眼睛閉上了，我的千里眼也回來了。\n\n&lt;class&gt;，謝謝你。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58231] = {title = "瘋狂中的智慧", objective = "到奧丹姆從黑暗帝國教徒身上收集10篇瘋狂文章。", description = "我在幻象中聽到…一些聲音…\n\n他們的話語毫無意義，但卻隨著時間過去自成規律。我相信這些聲音想傳達什麼重要的東西，但我還沒辦法解讀半個字。\n\n我們需要從源頭學習。當你遇到那些黑暗生物的時候，從那些教徒身上尋找任何手稿。想要瞭解潛藏在瘋狂之下的訊息，他們自言自語的內容可能就是關鍵。", progress = "你找到文章了嗎？", completion = "如我所料，這些教徒的文章似乎毫無邏輯可言。\n\n希望這些胡言亂語中埋藏著一些真相。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58232] = {title = "失序中的秩序", objective = "到奧丹姆殺死6個恩若司的無面者爪牙。", description = "距離上一次托維爾起身對抗古神的部隊，已經過了很長一段時間，因此對古神部隊的戰術知識，我們的理解相當有限。\n\n不過，有一條教戰守則永遠管用。打倒發號施令者就可以弱化敵人，比打敗普通士兵有用得多。\n\n我觀察到，體型較大的無面者爪牙在古神部隊中擔任指揮官。讓它們再也無法發號施令，或許我們可以在他們之中掀起混亂。", progress = nil, completion = "對他們指揮官的關鍵一擊，能夠為我們爭取一點時間。\n\n謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58233] = {title = "扭曲腐化者", objective = "到奧丹姆殺死10隻噬屍獸。", description = "伴隨侵略部隊出現的血肉巨獸乍看之下只是有點麻煩，但它們體內與古神的腐化之力有極深厚的連結。\n\n它們就像瘟疫一樣，不論在什麼地方落足，都會散播恩若司的腐化，慢慢扭曲大地的型態。\n\n一定要消滅它們。", progress = nil, completion = "每殺死一個扭曲的恩若司化身，奧丹姆都能稍微鬆一口氣。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58234] = {title = "來路不明", objective = "到奧丹姆從泥漿怪身上收集8份聚合腐化。", description = "我的千里眼能為蘭姆卡韓的人民提供重大的戰略價值。不過，我看到的幻象最近開始會折損我的身體。\n\n我想出一種藥水，有助於弱化這些幻象帶來的傷害，但它需要和古神腐化相連的精華。\n\n如果你能夠幫我取回一些樣本，這對我們而言將是莫大的貢獻。", progress = "你拿到材料了嗎？", completion = "你帶著樣本回來了嗎？太好了。\n\n希望這能達到預定的效果。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58235] = {title = "黑暗帝國之錨", objective = "到奧丹姆摧毀6座黑暗帝國方尖碑。", description = "這次入侵讓我方措手不及，黑暗帝國風格的建築物從虛空之中實體化，古神的部隊從中傾巢而出。我們完全不清楚他們是怎麼來的，或是來自何方。\n\n不過，每當新建築物出現之前，都會先出現邪惡的方尖碑。我們認為這些方尖碑的作用是定位，藉此引進更多古神部隊。\n\n如果我們想要阻絕這波入侵行動，一定要摧毀方尖碑。", progress = nil, completion = "儘管威脅仍然如影隨形，不過知道拖慢了敵人增援部隊的速度，還是讓人大感寬慰。\n\n我們或許能夠活著看到這場戰爭結束。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58236] = {title = "毀滅信物", objective = "在奧丹姆摧毀6面黑暗帝國旌旗。", description = "這支黑暗軍團的教徒，帶著他們暴君的象徵，持續玷污我們的大地。\n\n那些喪失心智的追隨者集結在這些旗幟之下，將它們視為穢邪的偶像來膜拜。\n\n把這些東西燒了，從我們的大地上淨化它們的痕跡。", progress = nil, completion = "很好。能讓這些可恥的符印不再玷汙我們的土地，真是太好了。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58237] = {title = "淨化奧丹姆", objective = "到奧丹姆摧毀6個腐化腫瘤。", description = "只要恩若司的部隊留在奧丹姆，他的腐化就會不斷滲入這塊土地。\n\n就算我們能趕走他的爪牙，或許仍無法彌補奧丹姆受到的傷害。\n\n我們一定要查明腐化的根源並消滅它。", progress = nil, completion = "即使是現在，我仍可感覺到恩若司的腐化正在衰退。\n\n你做得很好。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58238] = {title = "飽受折磨的失落者", objective = "到奧丹姆的托維爾的失落之城，從痛苦牢房中釋放6個蘭姆卡韓居民。", description = "蘭姆卡韓的居民成功逃離恩若司的攻擊。\n\n但在失落之城的兄弟們就沒這麼幸運了。那些沒有當場死亡的人們成為階下囚，只能淪為恩若司爪牙的拷問對象。\n\n我知道，你會挺身對抗恩若司的部隊。如果你能同時解救我們的同胞，蘭姆卡韓會欠你一份人情。", progress = nil, completion = "我們的居民欠你一份他們可能永遠償還不了的恩情，&lt;name&gt;。\n\n蘭姆卡韓感謝你的義舉。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58239] = {title = "從盜匪學到的教訓", objective = "在奧丹姆掠奪3個黑暗帝國寶箱。", description = "好幾代的廢土漫遊者都是盜匪，不是當山賊，就是做海盜。雖然我們決定放下那樣的生活，尋求平安度日的機會，但我們從未忘卻那些日子學到的教訓。\n\n當前情況讓我想到一個十分貼切的教訓，就是當我們面對難以匹敵的對手時，用他們的武器來反制對方通常能獲得奇效。\n\n找出他們隱藏的寶箱，能拿什麼就拿什麼。或許你可以找到某些足以扭轉局勢的東西。", progress = nil, completion = "希望你找到你在找的東西。\n\n在這場戰鬥中，任何幫助我們都來者不拒。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
