MultiLanguageQuestData['tw'][58260] = {title = "蛛后與未來的王", objective = "殺死1隻掘髓蜂后，並收集5隻掘髓幼蟲。", description = "一群掘髓蜂后在我們家園的上頭不停產卵。我們或許可以好好利用這一點。\n\n在推金的幫助下，消滅蜂后，取回卵中的幼蟲。\n\n那些幼蟲對我很有用，或許可以讓掘髓蜂為我們所用。", progress = "這是個骯髒的工作，但是我們需要那些幼蟲。", completion = "現在要好好地來利用它們。", rewards = "您會收到：\n\n戰鬥之焰回春藥水腐蝕液體瓶跳動的憎惡體核心血煉勳章血煉戒環腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼魔法防護的論文血絲長袍鋼核胸鎧\n                            顯示 16 更多                        肉鱗鎖甲護胸鋼核護手血絲手套肉鱗護手血絲裹腕鋼核裹腕屍皮裹腕血煉巨劍疫蝕劈斧瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐感激禮賜"}
MultiLanguageQuestData['tw'][58264] = {title = "起床、站起來、出去", objective = "幫助8個被制服的飛靈。", description = "他們需要你的幫助！\n\n並非所有的飛靈都已經變異了。有些飛靈仍是囚犯，但是他們臉上都戴著面具…\n\n你一定要幫助他們！我的力量不足以拆下他們的面具，但是你可以！你也可以擋住守衛，不讓他們靠近我們！", progress = nil, completion = "你救了我的朋友！\n\n&lt;櫻草向你微微笑了一下。&gt;\n\n我…我們倆合作無間，你說是吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58265] = {title = "源源不絕的壞人", objective = "在爍枝殺死15個戴著面具的暗夜妖精。", description = "旅行者，這附近有股刺鼻的臭味。西邊的空氣中瀰漫著惡毒的腐爛氣息。\n\n位於重生之路旁的爍枝長久以來都是個和平之地。那裡的飛靈歡欣鼓舞地過著愜意的生活。可如今，他們的林地陷入了一片寂靜。\n\n根據斥候回報，那裡有戴著面具的詭異暗夜妖精出沒。我對他們的瞭解不多，只知道他們是個威脅。\n\n為了亞登曠野著想，我們必須消滅掉他們。殺掉所有你遇到的暗夜妖精。", progress = nil, completion = "這是一份殘酷的差事，但卻是必要的。願他們能夠重生，再次成為對亞登曠野有貢獻的人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58266] = {title = "炸個痛快", objective = "使用櫻草的煙火粉末破壞5座儀式祭壇。", description = "我以前看過儀式的情況。太…嚇人了。\n\n不過祭壇似乎是關鍵。只要能拿到我的煙火粉末，我就能把它們炸成碎片！\n\n<櫻草沉默了一下，然後深吸一口氣。>\n\n要是你能拿到粉末，同時保護我，我們就能炸掉那些祭壇。\n\n我在我們的住處偷偷藏了不少粉末。他們似乎完全不當一回事。\n\n你沒有翅膀，不過一撮飛靈之塵應該能讓你暫時擁有飛行能力。\n\n趁我還沒改變主意之前，趕快行動吧！", progress = nil, completion = "我們辦到了！所有祭壇都被炸爛了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58267] = {title = "面具底下", objective = "在爍枝面對被附身的飛靈首領。", description = "是時候做個了斷了。\n\n我剛躲起來的時候，看到東北方的平台上有個黑色的人影。我想那就是他們的首領。\n\n他們現在已經無法再進行任何儀式了，我們應該可以把他們嚇跑。\n\n<櫻草停頓了一會兒。>\n\n我…我想要跟你說聲謝謝。要是沒有你的幫忙，我自己一個人根本不可能辦到。好了，我們去趕走這名敵人，把村莊奪回來吧！", progress = nil, completion = "我知道了。真是壞消息。", rewards = "您能選擇下列奬勵中的一個：\n\n爍枝之環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58268] = {title = "佔領制高點", objective = "摧毀三處敵方陣地。", description = "傀儡家族指揮官埃爾佛將軍，是戰術方面的大師。正面對決絕對贏不了他，只會演變成一場屠殺。\n\n他的部隊在我軍側翼並固守著制高點。他可以從那個陣地朝我軍降下毀滅性攻擊，而我們毫無還手的餘地。\n\n我們得在這種情況發生之前，拿下那座山脊。", progress = nil, completion = "只要肅清那個山脊，我們就能安全地向前推進。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58271] = {title = "虛焰儀式", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58272] = {title = "言語的力量", objective = "收集9個反叛軍小手冊。", description = "石源魔叛軍遺留了徵兵的小冊子，幫汎希爾族收集這些東西，或許能獲得他們的好感。", progress = "內容既粗俗又邪惡，字跡卻是優雅得不像話。王子的字一向寫得不錯，就是品味不怎麼好。", completion = "呃，原來是髒東西。交給我吧，我會妥善處理掉。\n\n來，給你謝禮。也許這個獎勵能讓你擦擦摸過髒東西的手。", rewards = "您會收到：\n\n幽魂手帕"}
MultiLanguageQuestData['tw'][58274] = {title = "恩若司的僕人", objective = "使用「恩萊斯，恩若司的碎片」轉換陣營，從聯盟變成恩若司的效忠者。然後在不死亡的情況下殺死10個聯盟玩家。", description = "<class>…\n\n我一直在看著你…我感受到你的嗜血飢渴。\n\n但你為虛偽的先知效忠…聯盟不過是個幻影…我是神！\n\n向我證明你有資格獲得我的贈禮…殺死那些即將背叛你的人…\n\n殺掉…聯盟！", progress = nil, completion = nil, rewards = nil}
