MultiLanguageQuestData['tw'][58351] = {title = "山丘上的耳目", objective = "帶著天選屍犬揪出隱藏的間諜。", description = "其他家族尚未發動全面攻擊，但不要把他們的懦弱，誤以為是沒有能力。\n\n夠份量的戰術家都很清楚諜報的價值。我懷疑在我們交談的時候，敵方的密探就已經潛伏到我們之間了。\n\n帶著我的獵犬。牠可以靠氣味聞出我們的敵人。找出害蟲之後，殲滅他們。", progress = nil, completion = "既然他們沒辦法躲開偵查，自然就沒資格活著。", rewards = "您會收到：\n\n"}
