MultiLanguageQuestData['tw'][58372] = {title = "帶路", objective = "護送看守者艾密爾離開懊悔墓穴。", description = "該走了，後面還會有更多刺客。\n\n我可以提供一些黑暗的掩護，不過要切記這道法術不是絕對可靠的。\n\n說得夠多了，監管者需要我和我手中的鏡子裂片，盡快回到她身邊。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恐懼哨衛烏黑束腰破魂者烏黑束帶懼獵者烏黑腰帶烏黑死亡帷罩腰帶"}
MultiLanguageQuestData['tw'][58373] = {title = "奈奧羅薩：母親大人的指引", objective = "在普通難度的奈奧羅薩，甦醒之城裡，從萊公身上收集4個泰坦核心、從薇希歐娜身上收集4個龍之心、從伊蓋諾斯身上收集4個預言之眼。", description = "奈奧羅薩違背了空間與時間的定律，我們或許可以把這一點化作優勢。\n\n母親大人的理論是，如果我們能夠從被恩若司選中的生物身上取得某些東西，就可以使用它們來扭曲空間，加快我們日後的通行速度。但是，他們應該不會自願把東西交出來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58374] = {title = "奈奧羅薩：母親大人的指引", objective = "在英雄難度的奈奧羅薩，甦醒之城裡，從萊公身上收集4個泰坦核心、從薇希歐娜身上收集4個龍之心、從伊蓋諾斯身上收集4個預言之眼。", description = "奈奧羅薩違背了空間與時間的定律，我們或許可以把這一點化作優勢。\n\n母親大人的理論是，如果我們能夠從被恩若司選中的生物身上取得某些東西，就可以使用它們來扭曲空間，加快我們日後的通行速度。但是，他們應該不會自願把東西交出來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58375] = {title = "奈奧羅薩：母親大人的指引", objective = "在傳奇難度的奈奧羅薩，甦醒之城裡，從萊公身上收集4個泰坦核心、從薇希歐娜身上收集4個龍之心、從伊蓋諾斯身上收集4個預言之眼。", description = "奈奧羅薩違背了空間與時間的定律，我們或許可以把這一點化作優勢。\n\n母親大人的理論是，如果我們能夠從被恩若司選中的生物身上取得某些東西，就可以使用它們來扭曲空間，加快我們日後的通行速度。但是，他們應該不會自願把東西交出來。", progress = "沒有所需的物品，母親大人就無法確保通行的安全。", completion = "有了這些物品，母親大人就能確保我們能夠安全地進入這個區域。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58376] = {title = "傀儡材料：死靈油", objective = "將這個材料送回去給屠夫區的拉桑。\n\n已提供物品：\n", description = "<這可以用來造出強大的憎惡體。或許拉桑知道要怎麼使用它。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n死靈油"}
MultiLanguageQuestData['tw'][58379] = {title = "傀儡材料：強韌的皮革", objective = "把這個材料交給屠夫區的拉桑。\n\n已提供物品：\n", description = "<這可以用來造出強大的憎惡體。或許拉桑知道要怎麼使用它。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n強韌的皮革"}
MultiLanguageQuestData['tw'][58382] = {title = "值得一救的人", objective = "在罪殞城釋放凱爾薩斯‧逐日者。", description = "你認識凱爾薩斯‧逐日者嗎？在你的世界，他曾是一個強大的領導者。\n\n那股久久不散的力量蘊藏龐大的靈魄，吸引了主宰的注意，他對凱爾薩斯的靈魂造成永久的傷害。\n\n<控罪者厭惡地撇了撇嘴。>\n\n每個靈魂都應該有機會得到救贖，$p。\n\n如果你不相信這點，至少也該相信這個靈魂雖然強大無比，卻也在自我毀滅的邊緣。\n\n釋放他，好讓我們一起踏上他的救贖之路。", progress = nil, completion = "想要救贖凱爾薩斯‧逐日者並不容易，結果也充滿不確定性。\n\n但無論如何，我們都必須冒險一試。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58383] = {title = "凱爾薩斯‧逐日者的諸多罪行", objective = "協助控罪者辨識凱爾薩斯‧逐日者的罪孽。", description = "當我們把凱爾薩斯‧逐日者從納撒亞城救出來時，他的情況相當危急。\n\n戴納瑟斯對凱爾薩斯注入數量難以想像的靈魄，每一縷靈魄都承載著其他人的罪孽。\n\n這讓他的靈魂無比強大，但也極不穩定，混亂失序，處於崩潰邊緣。\n\n相信我，凱爾薩斯‧逐日者自身的罪孽已經夠他受的了。\n\n他靈魂中的罪孽堆積如山，請協助我辨識出哪些才是他真正應該背負的重擔。", progress = nil, completion = "先說清楚，我們不會赦免凱爾薩斯‧逐日者所犯下的罪。\n\n他可能永遠無法贖罪，是否改變，最終只有他自己能決定。\n\n不過我們必須讓他的靈魂穩定下來，至少讓他有機會做出決定。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58384] = {title = "留下的泥掘者", objective = "協助10個泥掘者逃離暗牆哨塔。", description = "雷納瑟王子逃離暗牆哨塔時，他被迫拋下許多人和許多東西。\n\n強大的聖物和武器早就都被搬到主宰的老巢。不過王子的泥掘者被迫留下來，為阿諛主宰的卑鄙小人效力。\n\n泥掘者看到你一定很開心，這代表王子沒忘了他們。\n\n如果他們願意戰鬥，就幫助他們逃跑，我一定會把他們安全送到罪殞城。", progress = nil, completion = "我必須承認，我沒想到泥掘者居然這麼迫不及待，想為自己的自由而戰。\n\n我想，這是因為我們都把王子當成榜樣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58385] = {title = "學習奉獻", objective = "協助凱爾薩斯重新活化王子的寵物維德尼克，以及其他在暗牆哨塔休眠的石源魔。", description = "凱爾薩斯目前的狀態仍極不穩定，滿載的靈魄快把他擠爆了。\n\n他也是一個自大又自私的蠢貨。\n\n幸好，我有個一舉兩得的好辦法。\n\n真正的領導者會奉獻自我，拯救自己底下的人。\n\n主宰的部隊把很多石源魔和石獸留在暗牆哨塔休眠，其中包括王子的寵物。\n\n命令凱爾薩斯交出他體內的一部分靈魄，重新活化那些休眠的石源魔，助我們一臂之力。", progress = nil, completion = "凱爾薩斯‧逐日者應該準備好進行赦免儀式了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58386] = {title = "使用我的力量", objective = "協助凱爾薩斯對戰篡位者希夢娜。", description = "<凱爾薩斯四處張望，確定控罪者聽不見。>\n\n控罪者太過執著於我的短處，以至於她看不見我的長處！\n\n儘管已經死亡，但我還是強大無比。控罪者親口說戴納瑟斯對我注入靈魄，讓我變得強大。\n\n我們就用我擁有的這股力量來做好事！\n\n這座塔過去屬於這個國度的王子，對吧？我們去找他的篡位者報仇雪恨吧！\n\n有仇報仇是我個人的原則。", progress = nil, completion = "我不期待凱爾薩斯會立即認同或甚至理解憐憫的價值。\n\n赦免是一個非常漫長的過程，這只不過是第一步。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58387] = {title = "個人造業個人擔", objective = "完成凱爾薩斯‧逐日者的抽取儀式。", description = "主宰透過黑暗的腐化過程，將凱爾薩斯的罪孽石與他的靈魂束縛在一起，這令凱爾薩斯傷痕累累，不堪負荷。\n\n他身上背負的不光是他自己的罪孽，還有其他無數靈魂的罪孽。這個重擔連最高貴的靈魂都難以承受，更何況凱爾薩斯這樣的人。\n\n只希望你與凱爾薩斯共度的時光，能讓他的靈魂做好進行儀式的準備。\n\n我必須移除不屬於他靈魂的罪孽，化解那難以負荷的重擔，否則我們將會永遠失去他。", progress = nil, completion = "結果不算非常圓滿，可是至少還能接受。背負他人的罪孽是個沉重的負擔，他現在終於解脫了。你要的話，可以拿走這條鎖鍊，象徵你勇於承擔自己的罪孽，凱爾薩斯已經不再需要它了。", rewards = "您會收到：\n\n凱爾的黑暗罪孽石鍊"}
MultiLanguageQuestData['tw'][58388] = {title = "布雷貝爾叛徒", objective = "殺死4個布雷貝爾監督者。", description = "當王子在暗牆哨塔孤立無援時，他向聖杯區這裡的許多名門望族求援。\n\n但無人響應。\n\n多數人為了自保，大多袖手旁觀。這種做法雖然可恥，但不難理解。\n\n不過，有個家族反倒落井下石。布雷貝爾領主趁人之危，派了他的石源魔支援主宰的大軍。\n\n雷納瑟王子對他的背叛耿耿於懷。\n\n凱爾薩斯想要復仇嗎？那就去復仇吧。先拿石源魔開刀。", progress = nil, completion = "布雷貝爾的汎希爾人是否感到後悔了呢？\n\n我們主要還是想招募一些生力軍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58389] = {title = "瑪卓薩斯武器", objective = "收集8把瑪卓薩斯武器。", description = "<你發現的武器似乎與多數汎希爾人持有的武器不同，不過上面的印記顯然似曾相識…\n\n最好多收集幾把同樣的武器，然後交給控罪者。>", progress = "你帶了什麼來？那些不屬於此地…", completion = "布雷貝爾汎希爾揮舞著瑪卓薩斯軍隊的武器？\n\n這也表示…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58391] = {title = "死道友不死貧道", objective = "刺探稅務官與他的瑪卓薩斯聯絡人的會議。", description = "看來我又欠你一次人情了，$p。\n\n我決不會像控罪者所堅持的，告訴你赦免我罪孽的最好方式。\n\n不過…\n\n說到這裡，稅務官準備在暗隱村跟他的聯絡人碰面。你知道地點在哪裡嗎？\n\n如果你知道，我們可以調查一番，收集更多資訊，然後把收集到的資訊交給控罪者和雷納瑟王子。\n\n我認為那對他們很有幫助。\n\n對我而言，也是一種熱心助人的表現，你不覺得嗎？", progress = nil, completion = "一個巫妖？就在附近？\n\n你感覺到它了嗎？我過去感覺得到…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58392] = {title = "死亡之盡的毀滅", objective = "在死亡之盡摧毀瑪卓薩斯營地。", description = "看來我們發現了一個有待追查的共同敵人，$p。\n\n不管那個死靈法師逃到哪裡，肯定都會有一大堆叛徒、來自其他國度的不死軍隊，而且至少還有一個巫妖…\n\n殺死這樣的東西算不上罪惡。消滅這座營地中的侵略者和叛徒，是一件善行。\n\n我所渴望的善行。讓我們立刻展開追擊。", progress = nil, completion = "叛徒和懦夫…我沒時間理他們！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58393] = {title = "策略性處決", objective = "到死亡之盡殺死泥掘者巨人。", description = "我必須說，我不清楚稅務官的靈魄共用計畫到底會造成什麼後果。\n\n但我很清楚一個得到權力的巫妖所帶來的危險。\n\n我也非常清楚化解這場危機對控罪者十分重要，所以，以我當下的處境，對我也十分重要。\n\n我們應該消滅靈魄交易背後的勢力。只要沒了那個，交易自然會中止。", progress = nil, completion = "他們的體型越大…最後的爆炸也越盛大。哈！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58394] = {title = "維克斯艾菈女士", objective = "殺死維克斯艾菈女士。", description = "你感覺到了嗎？令你毛骨聳然的…能量…力量…\n\n她在這裡，那個巫妖。\n\n帶我去找她，我必須用我自己的方式跟她談談。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58395] = {title = "大仇得報", objective = "將凱爾薩斯送回罪殞城，向雷納瑟王子回報。", description = "在太陽之井被毀、我的人民幾乎滅絕之後，我發誓要對阿薩斯和科爾蘇加德復仇。但我需要力量才能實現這一步，為了掌握那股力量，我…\n\n<凱爾薩斯安靜下來。>\n\n我…已經準備回到罪殞城了。為了應付接下來的事，我必須回復力量。\n\n在控罪者一直對我耳提面命之餘，我有…很多事要思考。\n\n我們先告訴盟友目前發現了哪些敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n破魂者烏黑法衣恐懼哨衛烏黑胸鎧懼獵者烏黑鍊衫烏黑死亡帷罩外衣名望名望"}
MultiLanguageQuestData['tw'][58406] = {title = "前往瑪卓薩斯的鏡子", objective = "去罪殞城堡壘找勞倫特。", description = "我聽到一些消息，勞倫特的修復工作有了重要進展。\n\n一旦鏡子復原之後，就可以搞清楚我們得花多少功夫才能找回最後一個勳章。\n\n前往堡壘看看他的工作是否接近尾聲。", progress = nil, completion = "這面鏡子是我的最偉大成就。它直接連到浮在瑪卓薩斯骸骨之原上空的亡城。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58407] = {title = "統治勳章", objective = "使用勞倫特的鏡子進入瑪卓薩斯，並從科爾蘇加德手中取回統治勳章。", description = "勞倫特說得沒錯，我們立刻啟程。\n\n這面鏡子是我們直搗瑪卓薩斯核心的入口。\n\n在凱爾薩斯的配合下，我們會找到科爾蘇加德，並奪回他私自占為己有的統治勳章。", progress = nil, completion = "現在瑞文崔斯可以恢復它的真正作用了。願我們共同邁向光明的未來。\n\n&lt;雷納瑟王子微笑著。&gt;\n\n我注意到我忠實的石獸維德尼克，牠看來和你很親近，就像和我一樣。\n\n如果你想要帶著牠，我相信他也會很高興能陪伴你。這樣你們同行前往下一場戰鬥時，你就能將恐懼植入敵人的心中。", rewards = "您能選擇下列奬勵中的一個：\n\n頂點靈魄珠奇蹟靈魄珠蒼穹靈魄球敬意靈魄球神秘靈魄球憎恨靈魄球\n\n您還會收到：\n\n戰石獸維德尼克名望"}
MultiLanguageQuestData['tw'][58420] = {title = "煩人的干擾", objective = "到恆春谷殺死7個魷尾猴人。", description = "猴人是弱小的投機者。因此他們之中的某些人會把前途押在古神之上，我一點都不意外。\n\n我們應該在他們還不成氣候的時候解決他們。", progress = nil, completion = "很好。少了他們的臭味，恆春谷變得更好了。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58421] = {title = "特殊通行證", objective = "收集審查人妲希安娜、審查人博義安及審查人依翁娜塔的尖牙。", description = "要取得勳章，我們需要瑪提歐手中的另一塊鏡子裂片。他很可能藏身在我之前位於亞崎汎姆的莊園。\n\n那個地方由一位叫做諾門的忠誠泥掘者看守。諾門只管職責盡忠，天打雷劈都不放在眼裡。\n\n瑪提歐很可能保留了進出莊園的老規則。擁有那些尖牙的人得以通行。如果你在他的行動中收集指揮官尖牙，諾門就會放你通行。", progress = "喂，你想進入莊園嗎？讓我看看你的尖牙。", completion = "&lt;諾門仔細的審視尖牙。&gt;\n\n檢查好了。奇怪的是你怎麼可能拿到這麼多。\n\n是說，你不像個汎希爾。\n\n&lt;諾門聳聳肩。&gt;\n\n我也不在乎。你有尖牙，你進去。這是規則。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58422] = {title = "征服者印記", objective = "到恆春谷燒掉6面黑暗帝國旌旗。", description = "入侵的恩若司爪牙侵佔了他們無權擁有的土地。\n\n就算只有一個萊加尼還活著，也不會讓他們征服恆春谷。\n\n燒掉他們的旌旗，警告他們。", progress = nil, completion = "很好。\n\n這些入侵者應該知道我們不會輕易屈服了。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58423] = {title = "他們之中的最強者", objective = "在恆春谷擊敗3個稀有的恩若司僕從。", description = "你在過去的戰鬥中展現出強大的實力，不過每一天都會有新的敵人襲擊恆春谷。\n\n找出我們對手之中的最強者，讓他們在盟友面前一敗塗地。", progress = nil, completion = "當他們的勇士倒在他們面前時，就連古神的爪牙都必須暫緩腳步。\n\n隨著戰火持續延繞，別忘了此事。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58424] = {title = "鑑別護符", objective = "到亞崎汎姆殺死12個亞崎汎姆入侵者和5個挖掘場執法者。", description = "亞崎汎姆到處都是戴納瑟斯的僕人。\n\n我們一定要消滅這些入侵者。從他們的樣子看來，打算把亞崎汎姆撕成兩半尋找監管者勳章的任何蹤跡。\n\n<name>，快行動，趕在太遲之前阻止他們。", progress = nil, completion = "沒錯！剩下的鼠輩一定再也不敢輕易跟戴納瑟斯合作。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58426] = {title = "失敗的陰影", objective = "到暗牆哨塔找控罪者和凱爾薩斯。", description = "我會親自處理凱爾薩斯‧逐日者的赦免。以他目前的狀態和創傷，絕對需要外力介入和矯正手段。\n\n我很歡迎你助我一臂之力。我感應到你與凱爾薩斯有所連結，你在場的話，或許能幫他踏上較好的道路。\n\n如果你願意，請到暗牆哨塔找我們。\n\n雷納瑟王子曾在那裡遭遇一大挫敗，希望這次的結局能夠有所不同。", progress = nil, completion = "很高興你來了。我們開始吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58428] = {title = "墓穴破壞者", objective = "收集碎石木槌，破壞墓門，搜尋死亡之蓮花粉。", description = "真抱歉，<name>，還有一件事我忘了提。\n\n在這面鏡子重合之後，就會刻意施加詛咒。\n\n你得找到我的死亡之蓮花粉，就放在亞崎汎姆的其中一座地穴裡面…可是我想不起是哪一座。\n\n<name>，你恐怕得用暴力來解決這個問題。", progress = "你拿到粉末了嗎？", completion = "太棒了。現在我們可以安全地進入鏡子了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58431] = {title = "藥水池", objective = "把三個滲液素材：黏性油帶到藥水池。", description = "讓我教你關於藥水池的相關知識。我們在這裡創作出來的藥水，具備各種增益效果。\n\n在四周廢墟殺死軟泥怪，然後收集它們身上可能掉落的滲液素材：黏性油。每隻軟泥怪都能生成大量的黏性油，所以你一次只能攜帶一隻軟泥怪生成的量。\n\n把黏性油帶到藥水池邊丟進去。", progress = "你帶來的油夠用嗎？", completion = "我們應該共飲你所釀造的這種好東西！", rewards = "您能選擇下列奬勵中的一個：\n\n鬼靈治療藥水鬼靈法力藥水\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58432] = {title = "老舊的和用過的東西", objective = "在瑪卓薩斯用寇迪去尋找並收集10份有用的回收物。", description = "想要新的幸運星嗎？寇迪最會找幸運星！\n\n想和寇迪到處看看嗎？\n\n<寇迪的大眼睛充滿懇求地看著你。>", progress = "找到什麼好東西了嗎？", completion = "這些是非常寶貴的資源。謝謝你，淵喉行者。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者巨披風縫補咒術師斗篷\n\n等級 60–60縫補之魂披風縫補策略家披氅\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][58433] = {title = "靈魄耗損", objective = "取回靈魄罐。", description = "這不是什麼簡單的劫掠或造反，這些石源魔打算竊取這支車隊運載的靈魄。\n\n那批靈魄是要繳給主宰的稅，現在是靈魄乾旱期，我們不能讓這些雞鳴狗盜之徒偷走我們辛苦收集的靈魄。\n\n可以的話，請討回失竊的靈魄，我會處理你的壞名聲。", progress = "你找到什麼了嗎？", completion = "做得好，凡人。石源魔需要靈魄才能生存，否則，他們就會重新變成一堆石頭。比起殺死三十個石源叛軍，這想必更能打擊他們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58435] = {title = "狐狸人的傳承", objective = "到沃魯敦的狐狸人藏身處與哈嘎希會合。", description = "多虧了你的努力，部落終於真正體認到狐狸人的價值。\n\n你是我所知道…最狐狸人的狐狸人！\n\n到沃魯敦的狐狸人藏身處找我。基羅叫我做了一個小紀念物，感謝你的努力。", progress = nil, completion = "你的冒險精神、本領、對探索的熱情…你真是讓我們引以為豪。讓我們加入，部落一定會更好！\n\n基於這一點，&lt;name&gt;，請收下這個禮物。無論你去哪裡，我們永遠與你同在。", rewards = "您會學到：\n\n狐狸人的傳承\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58436] = {title = "機械地精的傳承", objective = "到機械岡城與伊拉敏王子會合。", description = "<name>，我們相當滿意你的進展。你在聯盟面前充分展露了我們的優點。\n\n請盡速返回機械岡城。華倫幫你準備了一份禮物。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n機械地精的傳承\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58437] = {title = "整體的組件", objective = "標示15具屍體供採集之用", description = "戴米恩有些很棒的夢想，但如果沒有更多憎惡體，這座訓練設施就不會成功！\n\n不過，我有個計畫！如果我們無法徵募到更多憎惡體，那我們就該自行製作！\n\n我需要你去製造一些屍體，然後插上標示用的旗子供人採收。其他的交給我。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
