MultiLanguageQuestData['tw'][58439] = {title = "血盆大口", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58440] = {title = "鏡子啊鏡子…", objective = "進入監管者的鏡子。然後，取得貪婪勳章。", description = "<name>，萬事具備，可以讓你過去了。\n\n我的勳章就放在鏡子的另一側。穿過鏡子之後，我的勳章就會在那裡的…某處。\n\n請小心。就算我的心智弱化，可是我還記得我曾和控罪者一塊工作，為地穴內部提供防護。\n\n我應該有辦法把此地的一切都告訴你，不過我擔心的是此地已經不像我記憶中的樣子了。", progress = "我的勳章？你拿到了嗎？", completion = "你找到勳章了！真希望你是在更好的情況下找到的。我好懷念有事情值得慶祝的感覺。\n\n不過我應該給你獎勵。沒錯，一點獎勵！你一定要收下，希望能幫到你的忙！", rewards = "您會收到：\n\n墓穴石獸"}
MultiLanguageQuestData['tw'][58442] = {title = "血盆大口", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58443] = {title = "繼續監護凱爾薩斯", objective = "到聖杯區找控罪者和凱爾薩斯。", description = "凱爾薩斯已經從主宰扭曲的腐化中解脫，但還不算是真正自由。\n\n他本身所背負的罪孽就足以讓他墮入淵喉。\n\n我們必須全力以赴，鼓勵和強迫他彌補自己的過錯。如果他無法為他生前的過錯贖罪，將會永世不得超生。\n\n你對他有正面影響，拜託，請跟我們一起去聖杯區，進行他的下一課。", progress = nil, completion = "我們準備開始進行下一課了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58444] = {title = "回到罪殞城", objective = "將勳章送到罪殞城，交給雷納瑟王子。", description = "<name>，我們一定要盡快把勳章帶回罪殞城。\n\n我們看到瑪提歐的部隊有多兇殘，如果我們再徘徊下去，想像一下戴納瑟斯會帶來什麼樣的毀滅。\n\n我馬上就回到赦罪墓穴。靠著你完成的一切成果，我可以重拾我的工作。\n\n我的第一道命令就是招募一位新的罪孽看守者。噢，我好害怕面談…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58445] = {title = "制住黑夜", objective = "瞭解塞爾納斯的計畫。", description = "<name>，你來了真是太好了。\n\n塞爾納斯說他可能知道如何幫助泰蘭妲，拯救她免於遭受塞爾納斯成為黑夜戰士時遭遇的命運。\n\n我們聽聽看他怎麼說。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58446] = {title = "尋找追蹤高手", objective = "與赫恩勛爵談話，並找出曠野獵者追蹤高手的所在位置。", description = "我們需要追蹤專家幫忙才能找到其他的黑夜戰士。\n\n曠野獵者在這方面的技能無人能敵。任何獵物都逃不過他們的追蹤。\n\n與赫恩勛爵談話。如果能請他們旗下的追蹤者幫忙，你一定能成功。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58447] = {title = "狩獵怪物", objective = "尋找線索，並循跡追蹤，進一步瞭解吞界者。", description = "做好準備，<class>。我們在獵殺的可是吞界者。\n\n它們是體型最大的吞噬者，這種巨大的生物可以在轉瞬之間吸乾一整個地區內的靈魄。\n\n亞登曠野目前受到靈魄乾旱影響。吞界者在這裡絕對會釀成莫大災難。\n\n不過，我們還是不能冒進，我們必須先充分瞭解我們的獵物。隨我一起進入長者之地。就算是這種生物，也是會留下足跡的。\n\n我們要瞭解它，才能殺掉它。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58449] = {title = "胃食道逆流", objective = "對果姆蟲巢的果姆使用馴牧果姆杖，以取得50個鼓鼓的消化囊。", description = "我們需要先做足準備，才能夠迎戰沃勒斯。\n\n亞登曠野的果姆分泌的消化液，可以把食物中的靈魄分離出來。吞噬者吃掉牠們的話，會產生相當大的不適感。\n\n不過那頭野獸身形巨大，需要有很大的量才能對牠產生效果。在東邊的巢穴中應該有許多果姆。\n\n很久以前，一名工匠給了我一把工具，他說如果哪天有需要，能夠在對付果姆時派上用場。你可以借去用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58450] = {title = "靈魄本能", objective = "收集8份生命硬質化靈魄。", description = "沃勒斯顯然沒有意願離開長者之地。我們必須確保當我們準備好戰鬥時，有辦法引誘牠送上門來。\n\n你有在我們發現它的那片空地裡注意到野性種子嗎？沃勒斯一定吞食了裡頭蘊含的濃縮靈魄。\n\n果姆蟲巢裡面應該還有一些耗盡的野性種子，是在乾旱發生之前留下來的。我們要製造出沃勒斯無法抗拒的誘餌。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58451] = {title = "吞界者沃勒斯", objective = "殺死沃勒斯。", description = "準備工作完成，<name>。接下來只要殺掉牠就可以了。\n\n我們要安置誘餌，弱化那頭野獸，然後給牠最後一擊。\n\n狩獵是一場考驗意志的戰鬥。生與死之間只有一線之隔。這是亙古不變的道理，無論在艾澤拉斯還是亞登曠野都一樣。\n\n開始戰鬥吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58452] = {title = "追蹤暗影", objective = "在森林之心與伊瑟拉交談。", description = "獵物已死，我的任務也完成了。木靈完全有辦法保護自己的家園不受小型吞噬者侵犯。大自然會自己找到出路的。\n\n我會向赫恩勛爵回報，然後回去森林之心和你碰頭。到時候再看看我的下一個狩獵目標是什麼。您會收到：\n\n", progress = nil, completion = nil, rewards = "妖精編織護腿橡心馬褲女王近衛護脛符文看守者腿甲您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58454] = {title = "眾所矚目的決鬥", objective = "到苦痛劇場擊敗『劈骨者』薩蓓耶。", description = "你所貢獻的靈魄為我們在這裡的行動帶來莫大助益。我們許多赫赫有名的競爭對手都被新的靈魄脈流引來這裡。\n\n你願意與有名的薩蓓耶一戰，試試自己的能耐嗎？如果你能擊敗她，大家都能獲得龐大利益。\n\n我可以把她加入賽程表，如果你擊敗其他挑戰者，她很快就會現身。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58455] = {title = "暗中對決", objective = "到黑石山的黑石深淵入口外找伯特‧麥可林。", description = "換我們出擊了！我們找到幽暗人影一直以來的藏身處，現在正是主動出擊、阻止他們計畫的好時機。他們的行動基地就在黑石深淵。一切都看你的了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58456] = {title = "暗中對決", objective = "到黑石山的黑石深淵入口外找伯特‧麥可林。", description = "換我們出擊了！我們找到幽暗人影一直以來的藏身處，現在正是主動出擊、阻止他們計畫的好時機。他們的行動基地就在黑石深淵。一切都看你的了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58457] = {title = "黑石之影", objective = "阻止幽暗人影。", description = "我們終於找到那些煩人的幽暗人影的藏身處，他們應該都在那裡。他們似乎能力高超，如果想要贏，最好帶著你最優秀的隊伍一起進去。\n\n準備好的時候告訴我一聲。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n魔噗連線：黑石深淵\n\n您還會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][58458] = {title = "寵物對戰挑戰：黑石深淵", objective = "阻止幽暗人影。", description = "那些幽暗人影又在策劃一些陰謀了，你確定要跟他們一戰嗎？如果你真的想回去那裡，我是不會阻止你的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗影寶石"}
MultiLanguageQuestData['tw'][58460] = {title = "瘋狂之禍首", objective = "到恆春谷擊敗6個恩若司的無面者爪牙。", description = "恩拉奇一直以來都是古神部隊中的指揮官和監工。他們出現在戰場上，就意味著這次侵略是早有預謀的行動，而非臨時的腐化。\n\n在為首的這些無面者領導下，古神雜亂無章的部隊變成一支所向披靡的大軍。\n\n我們必須將擊敗這些生物視為第一要務。如此一來，我們才能在與恩若司的戰鬥中佔上風。", progress = nil, completion = "恆春谷的恩若司部隊失去了領導者，目前應該是軍心渙散的狀態。\n\n這點為我們帶來優勢，一口氣殲滅他們的時候到了。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58461] = {title = "古老瘋狂秘典", objective = "到恆春谷從克西爾敵人身上收集8本古老瘋狂秘典。", description = "在現在這種時候，恆春谷的所有居民都必須貢獻己力，做好自己的工作。遺憾的是，我一向對戰鬥不怎麼在行，所以在這方面幫不上什麼忙。\n\n不過，我還是能夠有所貢獻。聽我說，我們對於所面對的入侵者幾乎一無所知，而知識則可以化為非常強大的武器。\n\n我記得我看過一些克西爾身上帶著秘典。如果你可以帶幾本秘典給我，說不定我能從裡面的內容找到一些有用的資訊。", progress = "你成功取得秘典了嗎？", completion = "沒錯，這正是我在找的東西！我馬上開始研究這些秘典！\n\n啊，能派上用場真是太好了！", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58462] = {title = "靈魂之窗", objective = "到恆春谷殺死6顆帝國之眼。", description = "我們的敵人光是派他們致命的大軍來攻擊我們還不夠，那些爪牙居然連我們防衛者的內心也不放過。\n\n我指的當然是那些眼睛。它們窺視戰士的心靈，激起心中最黑暗的恐懼。\n\n如果想要擊敗敵人，就必須摧毀它們。", progress = nil, completion = "那些邪惡的眼睛都消失了，我們戰士的勇氣也回來了。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58463] = {title = "瘋狂滋生", objective = "到恆春谷殺死10隻噬屍獸。", description = "恆春谷好不容易順利擺脫煞的陰影，恢復昔日的美麗，如今古神又再次染指這裡，實在是讓人火冒三丈！\n\n我們必須在古神再次徹底腐化這片土地之前，根除他的腐化。我看過隨著恩若司部隊出征的噬屍獸沿途散播腐化。\n\n確保他們的征途到此為止。", progress = nil, completion = "你做的很好。\n\n我們絕不能讓恩若司得到這片土地！", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58464] = {title = "深巢屠滅", objective = "到恆春谷的繁花礦坑，殺死10個深巢螳螂人。", description = "一群自稱為「深巢」的螳螂人佔領了繁花礦坑。這些螳螂人已經完全屈服於上古之神的腐化，因此也特別危險。\n\n我們不能任由深巢螳螂人在恆春谷裡面橫行。做你該做的事吧。", progress = nil, completion = "螳螂人不知道撤退兩個字怎麼寫，不過我們會把他們趕回去。\n\n至少你已經讓減少對方數量了。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58465] = {title = "實體腐化", objective = "在恆春谷殺死8個惡臭膿液。", description = "古神的腐化往往邪惡無比，有時甚至會化為實體。\n\n過去的煞就是很好的例子，這次也一樣。\n\n一看到這種形態的腐化，就立刻出手消滅。絕不能放任它成長茁壯。", progress = nil, completion = "我在你的武器上看到恩若司腐化的汙漬。\n\n打得漂亮，&lt;class&gt;。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58466] = {title = "虛空的折磨", objective = "在恆春谷釋放6個遠古熊貓人古靈。", description = "恩若司想要統御恆春谷的生者，雪上加霜的是，我的斥候回報說他們現在甚至還想統御亡者！\n\n影潘為了守護生者已經忙得不可開交。我們可以拜託你去終結他們的惡行嗎？", progress = nil, completion = "我一開始其實對你們抱有戒心，不過看來你們真的把潘達利亞的安危放在心上。\n\n謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58467] = {title = "身體與心靈的囚犯", objective = "到恆春谷拯救6個被俘虜的熊貓人。", description = "恩若司的部隊突然襲擊恆春谷。等到我和影潘來援的時候，很多金蓮會的人都被古神的部隊俘虜了。\n\n即便我們雙方聯手，也只能擋住入侵者，不讓他們抓走更多人。不過，那些被抓走的人仍在古神手中。\n\n我知道我們之間有分歧，<name>，不過，要是你可以幫忙救回他們，影潘一定會報恩。", progress = nil, completion = "我不希望老是想著要是沒被救出，那些人的下場到底會如何。\n\n&lt;class&gt;，你是真正的潘達利亞勇士。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58468] = {title = "暗意漸生", objective = "到恆春谷的繁花礦坑，摧毀6個腐化孵化器。", description = "影潘斥候在繁花礦坑裡發現了新的螳螂人孵化巢的蹤跡。看來這些深巢螳螂人打算創造新的腐化生物來效忠恩若司。\n\n要是讓這些卵孵化，受到上古之神強化的新蟲群就會佈滿恆春谷的天空，讓潘達利亞陷入黑暗。\n\n我們絕不容許這種事發生，對吧？", progress = nil, completion = "威脅減輕了，至少目前如此。\n\n記得留意任何新的孵化巢，不能把這些深巢螳螂人放著不管。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58469] = {title = "谷中的裂口", objective = "到恆春谷關閉3個虛無裂口。", description = "恩若司的影響在恆春谷蔓延開來，我們的現實也開始崩毀。\n\n上古之神的力量在我們的世界裡撕開裂口，成為他的爪牙從黑暗領域入侵這裡的大門。\n\n只要裂口還存在，我們就無法擺脫恩若司的魔掌。關閉這些裂口，阻止這波腐化的浪潮！", progress = nil, completion = "通道已關閉，恆春谷也多少恢復原樣了。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58470] = {title = "腐化的好奇心", objective = "到恆春谷，從黑暗帝國寶箱中收集3個黑暗帝國文物。", description = "我了解黑暗帝國對潘達利亞來說是莫大的威脅，但這也不失為一個契機！\n\n雖然我們過去曾對抗過他們好幾次，但對於上古之神或是恩若司的神秘領域奈奧羅薩依舊所知甚少。\n\n在研究古代文明時，我們經常得依靠古文物來解開遺失在時光裡的奧秘。不知道是不是也能在古神的軍隊裡找到這樣的文物？\n\n去查一查也無妨，對吧？", progress = "你發現什麼事了嗎？", completion = "好極了！想想看，我們可以透過這些神器解開哪些古老的謎團！\n\n希望你在取得它們的時候沒有遇到太多的麻煩。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58471] = {title = "主動記錄", objective = "到恆春谷使用博學行者的筆記本，收集關於無面者、克西爾、噬屍獸的記錄。", description = "儘管煞的形成與古神脫不了關係，潘達利亞的人還是對它們一知半解。\n\n我想趁這個機會盡可能收集它們的資訊，放到博學行者的書庫中。當然，如果它們想殺我們，事情就會變得有點難辦。\n\n不過對你來說應該不是什麼問題。可以幫我一個忙，記錄一下你在外面遇到的煞嗎？這或許可以讓我們好好瞭解我們的對手。", progress = nil, completion = "太好了！資料非常齊全！\n\n不過我有一個問題，你是如何一邊戰鬥，一邊記下如此工整的筆記？", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58472] = {title = "向武器告別", objective = "到死亡之盡摧毀瑪卓薩斯營地。", description = "瑪卓薩斯的營地就在我們後方。我不在乎你把他們當成盟友還是叛徒，把他們趕出瑞文崔斯就對了。\n\n摧毀他們的營地，讓那個營地從我們的土地上消失，然後確定不會再次發生這種事。\n\n手段不重要，重要的是，讓這些異教徒記住在太歲頭上動土會有什麼後果。", progress = nil, completion = "用這件事來證明我們的榮耀感吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58473] = {title = "特那諾的迴響", objective = "到特那諾找亞拉隆。", description = "顯然我們需要更多的靈魄，超過這片林地所能供應的量。我想到了一個辦法。\n\n蒙面的妖精一直在收集靈魄，原因我們還不知道。我們應該設法搶回來。\n\n曠野獵者追蹤蒙面妖精到了特那諾…那是我先前的林地。\n\n我很久沒在那裡的枝葉下漫步了。那座林地遭到荒棄凋零，為了讓其他林地能延續下去。\n\n記憶還很鮮明…", progress = nil, completion = "我從沒想過我會回到特那諾。這個地方充滿了太多記憶。太多悔恨…\n\n但現在不是感傷的時候。我們必須趕緊行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58476] = {title = "雷霆召來", objective = "到恆春谷殺死12個參天魔古。", description = "可以肯定的是，所有魔古氏族都是威脅，不過對金蓮會威脅最大的，莫過於參天氏族。\n\n即便是現在，他們的數量在黃金寶塔外越聚越多。我們的許多戰士都是經驗不足的新人。面對魔古的攻擊，他們撐不了多久。\n\n像你這樣經驗豐富的<class>應該可以大幅拖慢他們的腳步。\n\n能幫個忙嗎？", progress = nil, completion = "你今天很可能救了不少金蓮會戰士的命。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58477] = {title = "自血、土、骨而生", objective = "到恆春谷從多卡尼魔古及其盟友身上收集100個活化血珠。", description = "多卡尼氏族自認是古代靈魂魔法的適任者，但他們的魔像和靈體不過是靈魂真正力量的一小部分。\n\n奪走他們無比重視的血珠，交給萊加尼用於更好的用途。", progress = "你帶了什麼來？", completion = "這些很合用。\n\n去吧，一定還有需要你的地方。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58478] = {title = "沒有不碎的石頭", objective = "在恆春谷殺死10個巴魯克魔古。", description = "當那些好戰的氏族來到恆春谷時，巴魯克氏族自稱有資格擁有郭萊這片古老土地。\n\n他們根本沒有。\n\n讓這些僭取者知道自己的身分，那麼你或許可以贏得萊加尼的些許好感。", progress = nil, completion = "巴魯克氏族很快就會明白他們對萊加尼來說不算什麼。\n\n做得好。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58479] = {title = "閃電暴擊", objective = "到恆春谷摧毀6根聚雷針。", description = "參天魔古喜歡掌握風暴的力量，但還是會使用機器來操縱從天而降的閃電。\n\n讓這群冒牌貨看看，風暴與雷霆的真實力量來自於內在。打壞他們的玩具，看看他們還能怎麼辦。", progress = nil, completion = "哈！我們就來看看這些人稱「風暴之主」的傢伙少了寶貴的裝置，該如何是好！\n\n這應該會很精彩。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58480] = {title = "追根究柢", objective = "到特那諾調查耗盡的捕魂網，找到林地中聚集最多靈魄的地方。", description = "在我的林地凋零的時候，我響應女王的召喚，加入曠野獵者。\n\n特納諾回不來了。但看到敵人爬滿整座森林還是讓我心痛。\n\n我們需要很多靈魄。蒙面妖精一定在林地裡藏了大量庫存。我們只需要找出來在哪裡。\n\n他們很可能用了補魂網收集跟運輸靈魄。如果讓我檢查補魂網，應該就能找出蹤跡。", progress = nil, completion = "佐司特竊取的靈魄比我預期的還多。他們居然在乾旱時期奪走了這麼多…\n\n我們必須盡可能取回來。不只是為了野性種子，也為了阻止佐司特的陰謀詭計。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58481] = {title = "血之儀式", objective = "到恆春谷摧毀6座鮮血之泉。", description = "我和安吉打過許多場仗，所以知道該如何對付魔古，但是這些多卡尼所使用的鮮血魔法真是令人不安！\n\n他們光是殺死遇到的每個人還不夠，居然還用這些屍體來進行穢邪儀式？我實在是無法接受！\n\n幫我一個忙。萬一你碰上這種儀式，阻止他們！就算是我們的敵人，也不該被他們的黑暗魔法褻瀆。", progress = nil, completion = "知道你結束了那些儀式，真讓我鬆了一口氣。\n\n我只要一想到就覺得噁心。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58483] = {title = "紀念物", objective = "殺死特那諾的敵人，並從他們身上收集被偷的紀念物。", description = "在心木林地，我聽到特那諾凋零的消息。我從沒想過我會親眼見證。\n\n這讓我非常地悲愴。我也不免想像…我的老林地是否也會遭遇同樣的下場。\n\n我不敢相信，這裡曾經的一切真的都已經消逝了。\n\n也許還是有一些能夠回收的紀念物，一些能夠悼念亡者的東西。", progress = "心木林地的下場也會是如此嗎？我的老家也是？", completion = "謝謝你。\n\n我知道這些不過是物品，但它們意義重大。有時候，光是拿著能緬懷自己過去的東西，就足以感到慰藉。\n\n這意味著我們並未失去一切。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58484] = {title = "拿多少算多少", objective = "從特那諾的儲備處拿走掠奪的靈魄。", description = "我們知道這些入侵者佔據了林地。\n\n但理由何在？他們為什麼要收集靈魄，聚集在一個地方？\n\n他們到底是怎麼進入亞登曠野的？\n\n我們應該保持警戒，然後找到多少靈魄就拿多少。這樣或許多少能在失去這麼多之後，稍稍扳回一城。", progress = "我有時候會哀悼失去的一切。但很快就會想起還有很多工作需要做。", completion = "這些靈魄能幫助織夢者完成儀式…或許還能拯救原先可能消逝的其他靈魂。\n\n做得好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58485] = {title = "為垮而造", objective = "到恆春谷摧毀6座魔古雕像。", description = "巴魯克人使用死靈禁術，把倒下魔古的靈魂囚禁在為他們而戰的雕像中。\n\n這種作法對我們的同胞來說是一種恥辱，絕對不能再繼續下去。\n\n打破他們寶貴的雕像，讓他們沒有容器可以容納偷來的靈魂。", progress = nil, completion = "他們這個氏族會隨著雕像的崩塌一起毀滅。\n\n你表現得不錯。", rewards = "您會收到：\n\n艾澤萊晶岩戰爭物資戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58486] = {title = "佐司特別擋路", objective = "殺死『瑟洛斯壁壘』沃魯斯，並前往傾樹之心。", description = "只有林地之心才有可能容納我感受到的巨量靈魄。\n\n當我的林地遭到犧牲時，林地之心中的靈魄被取了出來。但現在，那裡再一次充滿了靈魄。\n\n這些是從其它林地偷來的靈魄。\n\n我們必須拿下林地之心，不只為了我們自己，更為了整個森林。\n\n我猜一定會有人出來阻止我們。做好面對危險的準備。", progress = nil, completion = "我們抵達樹心了。做得好。\n\n如果所有佐司特都像他那樣，那亞登曠野的情勢相當危險了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58487] = {title = "來搶盜掠者", objective = "到恆春谷搜刮3個魔古的財寶。", description = "我們對雷神寶藏的掠奪也確保了雷王的垮台。我認為我們現在也應該採取相同的策略。\n\n找出魔古氏族囤積的寶藏，然後全部奪走。\n\n我們必須盡一切的努力阻擋他們進逼。", progress = nil, completion = "做得很好。我們應該繼續把這些物資從敵人手上奪走。\n\n就算只是對敵人採取最小程度的干擾，也有辦法扭轉戰局。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58488] = {title = "取出樹心", objective = "摧毀屏障並取得特那諾之心。", description = "我果然沒猜錯！在林地之心中存放了大量靈魄。\n\n一定是佐司特從亞登曠野的各處收集而來的。\n\n現在，我們要全部拿回來。\n\n快點，摧毀屏障並拿起林地之心。我跟妮亞會保護你。", progress = "我們要取回這些靈魄。不能讓佐司特恣意糟蹋。", completion = "現在林地之心落到我們手中，我們得想辦法離開此處。\n\n而且我聽到遠方有敵人的聲響傳來…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58490] = {title = "死亡宣告", objective = "消滅敵方部隊和陣地。", description = "我們的防禦異常薄弱，不過敵人仍然遲遲不敢進攻。\n\n只要他們心存恐懼，就不會輕易試探我們的防禦能力。\n\n你必須讓敵人一直處於緊繃狀態，沿著戰線攻擊他們的陣地。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58496] = {title = "不受歡迎的顧問", objective = "到暴風要塞與安杜因‧烏瑞恩國王交談。", description = "<信中有安杜因‧烏瑞恩國王的訊息。>\n\n<name>，\n\n即便部落和聯盟的部隊共同合作，我們還是找不到恩若司部隊的蹤影。自從恩若司解放以來，他屢次都能避開我們。\n\n只有聖光知道他會對艾澤拉斯帶來什麼浩劫。\n\n到暴風要塞找我。我們必須趁為時不晚，好好制定計畫，揭露恩若司的陰謀！\n\n願聖光加快你的腳步，\n安杜因‧烏瑞恩國王", progress = nil, completion = "恩若司的腐化似乎已經開始染指我們的心靈。我們不能再浪費時間了。\n\n與麥格尼和怒西昂同行，看看你能有什麼發現。我會確保我們的部隊做好抵禦任何攻擊的準備。\n\n祝你好運。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58498] = {title = "戰士之王回歸", objective = "在暴風要塞與麥格尼同行，取回破懼錘。", description = "你為艾澤拉斯貢獻良多，勇士，不過，很遺憾，我必須要求你付出更多。恩若司已經掙脫束縛，不知會在何時何地發動攻擊。\n\n這場戰爭光靠你一個人絕對無法應付。時機來臨時，我會拿起戰錘與你並肩作戰！\n\n但，首先，我們得把它給拿回來。", progress = "需要什麼協助嗎，勇士？", completion = "能夠再次回到戰場的感覺真好。\n\n我們走吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58502] = {title = "心之所在", objective = "返回心之室。", description = "我們該執行怒西昂的計畫了。\n\n他會返回心之室，所以我們應該跟他在那裡會合。", progress = nil, completion = "很好，人都齊了。\n\n我們開始吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58504] = {title = "責難", objective = "到瑞文崔斯的贖罪之殿與控罪者會面。", description = "我們接獲來自瑞文崔斯的消息。瑪卓薩斯的謀反者似乎一直在躲藏在他們那裡。\n\n罪殞城的特使希望討論我們發現的靈魄庫存。\n\n跟我走一趟，我們馬上出發。", progress = nil, completion = "這是我的榮幸。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58505] = {title = "死亡預告", objective = "消滅敵方部隊和陣地。", description = "我們的防禦異常薄弱，不過敵人仍然遲遲不敢進攻。\n\n只要他們心存恐懼，就不會輕易試探我們的防禦能力。\n\n你必須讓敵人一直處於緊繃狀態，沿著戰線攻擊他們的陣地。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58506] = {title = "網路診斷", objective = "到心之室啟動泰坦控制臺，檢查艾澤拉斯各地的泰坦熔爐狀態。", description = "遺憾的是，我們毫無線索，不知道恩若司在逃脫後究竟潛伏在哪裡。不過，我們可以大致確定他的攻擊地點。\n\n在守護者囚禁上古諸神之時，他們建立了防止泰坦熔爐受到腐化的防禦機制。假如恩若司想要腐化艾澤拉斯，就必須先解除防禦機制。\n\n幸好，我們已經跟防禦機制建立連結，可以直接從這裡監控狀況。過去看一下吧。", progress = nil, completion = "我原本希望我們能有更多時間準備。\n\n看來現在就必須行動了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58515] = {title = "搜集卷軸", objective = "從謙遜神殿收集琪瑞安的資料。", description = "琪瑞安以他們收藏的卷軸和筆記聞名。我對描述琪瑞安成員的資訊特別感興趣。\n\n為什麼有些偉大的戰士會被送往昇靈堡，而不是瑪卓薩斯呢？\n\n或許研究能給我們一點方向。", progress = "來看看那些紙張跑去哪了？", completion = "這很有幫助。這麼多人不願意分享知識，真是太可惜了。光是囤積知識一點用都沒有。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者肩鎧縫補之魂護肩縫補策略家肩甲\n\n等級 60–60縫補咒術師披肩\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][58518] = {title = "凡走過必留下痕跡", objective = "找到相關證據，釐清是誰將瑪卓薩斯武器供應給汎希爾族。", description = "在這裡發現那些古怪的武器，你似乎很驚訝。\n\n我也感覺到其力量的本質，異常地熟悉…\n\n我們必須查清這批武器的來源，以及是誰注入這股力量。\n\n<凱爾薩斯笑了笑。>\n\n如果我和你一起把證據交給控罪者，或許她會讓我們一起去追殺這一切的幕後黑手！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58523] = {title = "你跟死了一樣", objective = "跟隨控罪者前往瑪卓薩斯營地。", description = "我早有預期你會幫忙，但我在等待結果。\n\n我們進行了偵查，並且在歿路沼澤找到了一座瑪卓薩斯營地。我們推測你們的人一直在汲取主宰的靈魄庫存。\n\n我已經安排運輸工具載我們過去。我們要快點行動。", progress = nil, completion = "我們已經抵達了，時間寶貴。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58524] = {title = "天降閃光", objective = "與月莓女士交談並逃出特那諾。", description = "你找到林地之心了！而且它還充滿了靈魄！\n\n佐司特對於你把樹林之心拿走，好像有點不太高興。他們在林地各處傾巢而出！\n\n我們得讓你和其他人平安撤離。\n\n我幫得上忙。來點閃亮亮的混亂場面，你覺得如何？", progress = nil, completion = "你就這樣從林地中心找到並拿走他們的靈魄？\n\n織夢者一定會欣喜若狂。但我猜我們很快就會遇到怒氣衝天的訪客。\n\n我們得動作加快…在被追上之前協助這枚野性種子中的靈魂。", rewards = "爍翼巨披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][58525] = {title = "歷史的兩面", objective = "找到「骨與石之上」與「瑪卓薩斯之惡」這兩本書。", description = "你們凡人都說歷史是贏家寫的，但在暗影之境，我發現不一定是這樣。\n\n每個人都有自己版本的故事。我想知道每一個版本。\n\n有個歷史書的作者選擇居住在瑞文崔斯的暗殞之塔。他從汎希爾的角度描述了入侵事件和統御者周遭發生的戰鬥。\n\n如果我們能找到她的著作…", progress = nil, completion = "你找到了！這是個觀察汎希爾內心的好機會。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者肩鎧縫補之魂護肩縫補咒術師披肩縫補策略家肩甲\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][58530] = {title = "隱藏的鏡子", objective = "使用勞倫特的小型窺鏡顯現昇靈堡裡隱藏的鏡子。", description = "如果雷納瑟打算動用收割者的勳章，他需要一個導體才能把那股力量凝聚起來。戴納瑟斯的腐化汙染了瑞文崔斯的熔爐，現在最理想的可能性是昇靈堡。\n\n昇靈堡不會容許我們這些瑞文崔斯的居民，經由奧睿博司抵達該地。\n\n我們需要你去啟動一面很久以前就隱藏起來的鏡子。把這拿去。\n\n我們把它藏在一個鮮少有人使用的地方，薄霧飛地。那裡應該不會有任何人，尤其是在這種乾旱的時節。", progress = nil, completion = "我上次看到這些平原，已經是好久以前的事了。\n\n我有點訝異，幻象居然一直都在。多年前以主宰名義行動的時候，就已經把它隱藏在這裡了。\n\n別在意，我們動作快點。我們可不是來隨處觀察的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58555] = {title = "緊張的團聚", objective = "在永恆熔爐跟德瑞文將軍和希奧塔會面。", description = "我們正在尋找首席熔爐士，米卡尼寇斯。\n\n只有他才能打造出我們需要的裝置。我看過幾件他的作品。他所研製的武器和傀儡令人印象深刻，甚至足以和我們最強大的石源魔匹敵。\n\n上次我碰到他，是在他的工坊那裡，就是那個被稱作永恆熔爐的地方，那裡令人嘆為觀止。\n\n我們在那裡跟你會合。集體行動可能會太引人注目。", progress = nil, completion = "讓我負責談話。只要走錯一步，他們一定會撤銷對我們的信賴。\n\n現在不是國度之間血腥屠殺的時候。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58557] = {title = "來自罪殞城的協助", objective = "到瑞文崔斯的暗隱村找監管者。", description = "為了擊敗棄誓者，必須幫紋章找一個能彌補過去錯誤，並且向前邁進的神器。\n\n我想到了某個神器。\n\n很久以前，很多靈魂從瑞文崔斯來到昇靈堡。那些靈魂比之前從瑞文崔斯來的，要純潔的多。\n\n他們帶著悔悟徽印的印記，這個法器促進了他們的淨化。\n\n前往瑞文崔斯，找到這枚徽印，以便借用它的力量。", progress = nil, completion = "真的很抱歉，但我沒有別的答案了…淵喉讓我有點神智不清。\n\n我會盡我最大的努力提供協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58558] = {title = "間接情報", objective = "到聖杯區，從聖杯信差身上收集傳聞。", description = "女伯爵掌握了每個瑞文崔斯貴族的命運和當下行動。這是讓貴族為她效命的最好方法。\n\n不過，她也有黑暗的秘密。不管她說了什麼，她原本也是凡人。\n\n我們要找到女伯爵存放自己罪孽石的地方。當然，這不簡單。\n\n我們要先收集情報。聖杯區的汎希爾居民常常傳一些小道消息。從信差身上拿到信件，找出其中有趣的消息。", progress = nil, completion = "有三個家族受到女伯爵的特別恩惠…真有意思。\n\n聽起來你可能要去雷德拉夫區探索一番！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58559] = {title = "主宰的眼線", objective = "到聖杯區殺死『全知者』伊娃菈、守護者瑪斯特魯司及『撕裂者』克拉爾。", description = "進入這座城市讓我提心吊膽，你應該已經注意到我們在這裡有多麼…顯眼。\n\n戴納瑟斯的效忠者到處都有眼線，而且再也沒有比石源魔更忠心的士兵。\n\n他們的耳目隨時監控著聖杯區，解決他們的首領，確保沒有人能在我們取得徽印之前，將我們的消息上報。", progress = nil, completion = "這座城市讓我起雞皮疙瘩。我總覺得一直有人盯著我，人們總在我的背後竊竊私話。\n\n除掉石源魔的首領後，應該能讓情報慢一點傳回戴納瑟斯的效忠者耳中。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58560] = {title = "哥德風", objective = "到聖杯區，從聖杯區居民和衣物箱收集5件汎希爾衣物。", description = "要不受注意地進入這座城市，不像我想的那麼簡單。\n\n我風塵僕僕地一路走來，結果遇到這些…小傢伙。\n\n或許克蕾雅是對的，我在這裡太過引人注目，反而綁手綁腳。\n\n還是我應該偽裝一下？拜託，幫我收集幾件汎希爾服裝，讓我可以偽裝。", progress = nil, completion = "&lt;佩拉苟斯仔細檢查你交給他的衣物。&gt;\n\n這布料真好…我想這樣應該可以！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58561] = {title = "女伯爵的裂片", objective = "收集3枚女伯爵的裂片。", description = "汎希爾會利用附魔鏡子進行長距離的旅行。我們要找的鑰匙可不像昇靈堡的鑰匙，而是鏡子的裂片，那可以帶我們到罪孽石的所在地。\n\n根據你找到的情報，我們已經知道哪三個家族擁有我們所需要的裂片。\n\n分別是櫻草、暗脈及罪牙。\n\n前往他們的莊園，取得裂片。我們負責找到鏡框，才能把裂片拼湊起來。", progress = nil, completion = "我相信你一定在貴族那裡引起了不小的騷動。我們的動作要快。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58562] = {title = "收集粉末", objective = "到雷德拉夫區尋找死亡之蓮，收集30片死亡之蓮花瓣。", description = "我很了解女伯爵。她的罪孽石絕對不是鑰匙就能搞定的。\n\n她很喜歡利用詛咒來防護她的傳送門。但我可以製造一種殘餘物，應該能保護我們，不過我需要一些非常特別的花瓣，這種花生長在雷德拉夫區的花園中。\n\n去收集那些花瓣，我才能保護我們不受危險。", progress = "我需要很多花瓣，才能保護我們四個。", completion = "&lt;監管者仔細檢查花瓣。&gt;\n\n或許有點難以想像，但我相信我可以讓它派上用場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58563] = {title = "穿過鏡面", objective = "穿過鏡子，取得女伯爵的罪孽石。", description = "鏡框位在雷德拉夫大廳的最底層。克蕾雅和佩拉苟斯已經在那裡等你了。\n\n有了這些裂片，我就能把鏡子拼好。\n\n我們穿過鏡子、拿走罪孽石，然後去跟女伯爵談判。別讓任何人事物阻礙我們。", progress = "汎希爾帶著他們的過去，肩上始終有著負擔。\n\n我們琪瑞安不會和過去有所牽扯。", completion = "這顆石頭蘊藏極為龐大的力量。\n\n你的過去可能會成為傷害自己的利器，因此我們選擇解放自己。", rewards = "無私輝環您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58564] = {title = "過往罪孽", objective = "穿過鏡子，面見女伯爵。", description = "女伯爵的威望建立在她是天生的汎希爾身上，而不是靈魂。\n\n向世界揭露她的罪孽石會引發一場災難。那對我們想找的消息有幫助。\n\n她會告訴我們愛爾文在哪裡，封印在哪裡。\n\n這面鏡子通向她的莊園，我會在你後面支援你，但琪瑞安會在這裡待命。\n\n別讓她威脅你，你才是主導的人。", progress = "淵喉行者，你應該慶幸監管者是站在你那邊。\n\n如果這齣鬧劇是你自導自演，你可能再也見不到你重要的昇靈堡了。", completion = "我可以告訴你悔悟徽印的事。\n\n然後請你識相點，立刻離開。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58565] = {title = "聖光之地", objective = "到餘燼區的癲狂聖所找希奧塔。", description = "餘燼區是被瑞文崔斯社會放逐的人的聚集地，被放逐的原因包括起兵造反、冒犯貴族，或單純只是說戴納瑟斯的壞話。\n\n那裡是個飽受聖光燒灼的地方，如果汎希爾人找不到暗處能躲，絕對會被逼瘋。\n\n如果愛爾文被放逐到那裡，那可能已經太遲了。\n\n我們去癲狂聖所拜訪希奧塔吧。我相信他一定很高興看到你。", progress = nil, completion = "啊，&lt;name&gt;，歡迎回到瑞文崔斯！\n\n請容我幫你聯絡或許能幫到忙的人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58566] = {title = "坐而言不如起而行", objective = "跟隨心靈灼傷的愛爾文穿過灰燼通道。", description = "<這名灰燼食屍鬼仔細觀察你，仔細檢查你的武器和護甲。\n\n接著他將目光從你身上移向與你同行的琪瑞安夥伴，然後再繼續觀察向他點頭示意的希奧塔。\n\n愛爾文示意要你跟他走。>", progress = nil, completion = "&lt;愛爾文先看向你，再看向克蕾雅。\n\n他點點頭，眼神充滿決心。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58567] = {title = "蟄伏於黑暗", objective = "到灰燼通道殺死8個汎希爾流亡者。", description = "我直到最近才聽聞餘燼區的事。\n\n既驚人…但又令人恐懼。\n\n聖光燒灼這裡的汎希爾人，將他們的身體烤焦，讓他們的精神瀕臨崩潰。\n\n只有黑暗才能緩解痛苦，但惡棍們已經拆除了庇護所外面每一塊遮蔽物。\n\n他們毫無救贖可能，只有正義能處理他們。", progress = nil, completion = "一旦人們陷溺於自己的惡念之中，就必須接受相應的審判。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58568] = {title = "聖光救贖", objective = "到灰燼通道收集25顆灌木莓。", description = "這一路上，我們從很多灰燼食屍鬼身邊經過，他們被聖光燙得滿是傷痕，發出痛苦的哭喊。\n\n見過愛爾文和這裡的其他人之後，我為他們心痛不已。\n\n他們被折磨得不成人樣，每天過著生不如死的日子。\n\n求求你，去灰燼通道採集一些莓果。我認為能夠將靈魄轉移到他們身上，轉化成治療藥膏，緩解他們的疼痛。\n\n這至少是我能做的。", progress = "餘燼區的居民已經為自己的錯誤受盡折磨。\n\n聖光賜下如此刑罰，實在太重了。", completion = "幫助受苦的人是我的職責。這種藥膏能讓他們好一點。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58569] = {title = "愚蠢的嫉妒", objective = "殺死公爵維爾烈，取回悔悟徽印。", description = "<愛爾文指著岩臺上的一名汎希爾人。\n\n他發出微弱又低沉的咕噥聲。>", progress = "是愛爾文帶我們過來的，我們必須取得徽印！", completion = "這真的是嗎？我們一直在找的東西…", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58570] = {title = "臨別贈言", objective = "到癲狂聖所與監管者交談，然後返回樂土堡。", description = "既然拿到徽印了，我們必須立刻返回昇靈堡。\n\n愛爾文已經伸張了他的正義，他也留下了徽印，交到我們手裡。\n\n我們就在癲狂聖所道別，然後啟程回家吧。\n\n我很期待回到昇靈堡那片藍天綠地的懷抱中。", progress = nil, completion = "卡莉賽恩的報告令人擔憂…不過那不是我的問題！徽印應該正常運作中。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58571] = {title = "悔悟徽印", objective = "將悔悟徽印放入晉升紋章。", description = "徽印已經準備完成了。\n\n把它插入紋章裡吧。動作不要太粗魯，但是力道要夠！動作要乾淨俐落，手不能晃。", progress = "<寶珠懸在你面前，手中的徽印快速脈動著。>", completion = "&lt;當你把手移開悔悟徽印時，你看到上頭閃爍著蘊含力量的光芒。\n\n真是個非凡的物品，雖然不是很明顯，但它和昇靈堡以及瑞文崔斯的居民以許多不同的方式相連接著。&gt;", rewards = "無私收集者巨盔無私引渡者護盔無私看守者頭盔無私熔爐士頭盔您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58575] = {title = "惟吾僅有", objective = "收集12把亡者的武器。", description = "很多競技者都在苦痛劇場結束一生。不過他們的武器都還是光亮如新！\n\n幫新手準備裝備代價十分高昂，尤其你根本不確定他們能不能撐過第一輪。因此，我們會為他們提供「九成新」的裝備。\n\n幫我收集那些裝備，好嗎？我們做人就是要惜福！", progress = "你收集的武器可以幫到未來的勇士！", completion = "這些武器將受到妥善運用。希望我們不用再派人去收集它們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58582] = {title = "黑龍王子的回歸", objective = "到達薩亞洛的大封印和瓦麗拉‧桑古納爾交談。", description = "<信中有瓦麗拉‧桑古納爾的訊息。>\n\n<name>，\n\n我剛剛還在暴風城，與烏瑞恩國王開了一場會議。\n\n我們有許多事情要談。\n\n馬上到大封印和我會面。\n\nAl diel shala，\n瓦麗拉", progress = nil, completion = "我希望那位怒西昂的專業意見可以帶領我們找到古神。\n\n我們實在沒什麼辦法。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58583] = {title = "心之所在", objective = "在心之室和麥格尼‧銅鬚會面。", description = "代言者已經提出請求，要我派你去協助他和怒西昂完成工作。\n\n你證明了自己是艾澤拉斯的最強盟友，而且我想你也會在接下來的戰鬥中扮演著重要角色。\n\n希望部落和聯盟剩下的人，能將彼此的爭執放在一邊，面對共同的敵人。", progress = nil, completion = "啊，你趕上了！而且你來得正好！\n\n怒西昂有一個計畫，有可能讓我們智取恩若司。當古神露出真面目時，我們需要你出手攻擊！\n\n我們開始吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58584] = {title = "彌補錯誤", objective = "在永恆熔爐和希奧塔交談。然後，揭露並摧毀5座隱藏的靈魄虹吸裝置。", description = "凱厄將軍很久以前為了戴納瑟斯的任務來到這裡。\n\n在那場任務中，他們隱藏了靈魄虹吸裝置，讓行蹤無法被偵測到，然後限制了這間工坊能夠使用的靈魄量。如此會讓這個區域極不穩定。棄誓者一定注意到了，而且還利用了這個弱點。\n\n過去的行動違反了我們的目標。帶著希奧塔，摧毀這些虹吸裝置。", progress = nil, completion = "大功告成。\n\n這樣應該能讓靈魄再次回歸。\n\n你為我們貢獻良多。我想不出比你更有資格披上這件披風的人。", rewards = "您會收到：\n\n破魂者烏黑披氅烏黑死亡帷罩披風懼獵者烏黑披風恐懼哨衛烏黑披風"}
MultiLanguageQuestData['tw'][58585] = {title = "不是朋友", objective = "在永恆熔爐殺死法茉絲並取回米卡尼寇斯的工具箱。", description = "工具，沒有工具我要怎麼工作！\n\n我的前學徒法茉絲跑去投靠棄誓者後，就把工具全都偷走了。\n\n我真是傷心透頂。她的前途原本是如此光明璀燦。\n\n一定要阻止她。", progress = "我需要我的工具。少了工具，我就無法完成工作了。", completion = "啊，我的工具。至少法茉絲有好好照顧它們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58586] = {title = "合適的材料", objective = "破壞棄誓者傀儡，收集5塊污化的百衛機兵組件並加以熔鍊。", description = "如果打算製作某種可以用在任務上的東西，我們就需要一些金屬。\n\n棄誓者傀儡有金屬零件，很符合我們的需求。但因為被棄誓者汙染了，所以會需要進一步加工。\n\n收集那些金屬，再用永恆熔爐的火焰熔鍊它們，就能淨化腐化。", progress = "你拿到金屬了嗎？", completion = "這些金屬很合用。做得很好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58589] = {title = "無法安息的夢旅者", objective = "到夢壇盆地的聖壇上，讓灌注的樹心同調。", description = "既然我們拿到需要的靈魄了，就必須讓特那諾之心與冬日窪地的夢壇同調。\n\n然後，我們才能將這顆野性種子的夢魘攤在陽光底下，並且加以驅散。\n\n帶著特那諾之心前往夢壇盆地的夢壇，就在冬日窪地外面沒多遠。然後將特那諾之心帶回來野性種子這裡，完成儀式的準備工作。\n\n不過請小心。佐司特的爪牙似乎聚集在林地附近。", progress = nil, completion = "你簡直是天生好手。現在我們可以揭露靈魂夢魘的真面目，並且直接著手處理了。\n\n如果成功的話，她會變得平靜許多。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58590] = {title = "夢旅者的幻象：起源", objective = "與靈魂的起源幻象纏鬥。\n\n如果離開幻象，與夢壇盆地的夢旅者的幻象傳送門互動，就能再次進入。", description = "這顆野性種子裡面的靈魂夢到她出生和年輕的時候，那時她的世界才剛剛誕生。\n\n前往冬日窪地外面的第一座夢壇。在夢壇上冥想，並安撫重現她誕生之初的幻象。", progress = nil, completion = "我們都有各自的起源故事。有時候是出乎意料的發展。至於我，就像一朵花一樣，突然就從地面破土而出。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58591] = {title = "掠奪者", objective = "殺死枯蔑佐司特和染疫者，並擊敗『掠奪者』絲克爾。", description = "你在特那諾的作為惹怒了佐司特。\n\n那些象徵凋零和毀滅的生物大舉進犯我們的邊界，已經開始突破我們的防禦。\n\n如今我們知道了他們的真面目，明白了敵人的本質。\n\n打倒他們！這能為我們爭取時間，讓你進行織夢者的儀式。", progress = nil, completion = "這次的攻擊只是開始，不過對他們而言仍是重重一擊。謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58592] = {title = "照看照料者", objective = "到夢壇盆地釋放靈魂看管者。", description = "這些佐司特突擊的速度太快了。他們抓走了一些這片林地的靈魂看管者！\n\n一下靈魄乾旱，一下怪物來襲，這絕不是什麼輕鬆的工作。我這是親身經驗分享。\n\n拜託你，能不能把他們從那些入侵者施放的可怕魔法中解救出來。", progress = nil, completion = "那些佐司特對待妖精真的非常殘忍！靈魂看管者只是想做好自己的工作…\n\n謝謝你幫了他們一把。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58593] = {title = "夢境末路", objective = "見證這個靈魂生命的終結。", description = "時候到了。當你全面進入靈魂的夢境後，這個儀式就會完成。\n\n你會跟她完全融為一體。各種方面都是。\n\n她正一次又一次重複經歷死亡的過程。她無法釋懷、受此折磨。是由於死去的方式所致，她完全失去了控制，傷害到摯愛之人。\n\n當你準備好親身潛入她臨終場面的幻象時，就告訴我。", progress = nil, completion = "如此偉大的靈魂，卻擁有如此可怕的結局…\n\n原來那就是她與你產生羈絆的原因！因為你們都來自同一個世界，艾澤拉斯！\n\n現在，我總算感應到她的夢魘逐漸消退。她終於恢復了至少一點點的平靜。\n\n謝謝你，朋友。", rewards = "林地看守者巨盔靈魂看管者兜帽夢棘頭盔星蔽頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][58595] = {title = "破滅之柱", objective = "到恆春谷摧毀6座黑暗帝國方尖碑。", description = "在久遠的過去裡，上古之神的黑色方尖碑就預示了他們軍隊的到來。克西爾和恩拉奇之中的黑暗咒術師會利用這些方尖碑在我們的世界裡建立據點，然後引入更多的古神僕從。\n\n今天，我們在戰場上，到處都看到這種方尖碑。只要方尖碑還豎立著，恩若司的軍隊數量就是無窮無盡。\n\n別讓這種事發生。", progress = nil, completion = "你摧毀方尖碑了？很好，絕對不能對古神放鬆戒備。\n\n戰鬥的時候記住這句話。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58599] = {title = "阻止泥掘者", objective = "殺死3名巨型泥掘者。", description = "首先，我們破壞他們的行動。有問題之後再問。\n\n進來的時候，我從瞰臺勘察過了，死靈法師會為充滿虹吸靈魄的水晶充能，三個泥掘者再把它們堆上推車。\n\n殺死那些泥掘者，就能阻止他們的行動。", progress = nil, completion = "做得好。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58600] = {title = "完美的圓形", objective = "搜尋完美環形模具。", description = "我想到了一個完美設計，剛好符合你的需求…能夠引導收割者力量的王冠。\n\n還需要一個工具來組合它，一個模具。環形物件不太好處理。\n\n去我的舊儲藏室找找，那邊有個完美的模具。我很確定。\n\n可能在我那些舊箱子裡面，你要不要去翻翻看？", progress = "皇冠一定要完美無缺！", completion = "打造得完美無缺。正是我們要的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58601] = {title = "資訊網路", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58603] = {title = "斐斯托斯，紀元創生者", objective = "從監督者阿提克斯身上取回斐斯托斯，紀元創生者。", description = "少了某種神聖之力。\n\n棄誓者洗劫了初代熔爐士聖壇，拿走她的錘子，我的錘子！\n\n擊敗他們的指揮官，取回斐斯托斯。請馬上動身！", progress = "沒有斐斯托斯，我們無法鑄造你的王冠！", completion = "斐斯托斯回來了！勝利的一天。\n\n感激不盡，朋友。這把錘子已經傳承了無數紀元！我這雙技藝精湛的手才是它的歸宿。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58605] = {title = "業餘之夜", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58606] = {title = "零碎的調查", objective = "收集16個亞基蟲碎塊。", description = "$p，這可能是畢生的大發現！\n\n我現在還不敢打包票，但我懷疑這些蟲子就是所謂的亞基蟲族。\n\n協會裡還留存著少數幾份完整的報告。但這些生物的最後描述提到了一場介於克蘇拉希、亞基和早期食人妖文明的大戰。\n\n我們一直假設它們已經全部滅絕，結果它們只是又被…製造出來。\n\n可以幫我收集一些樣本供我研究嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58608] = {title = "那就是叛國", objective = "殺死維克斯艾菈女士。", description = "我們阻止了他們的行動，不過我們還有更多事要做。\n\n辛丹一定派了人來監視營地。\n\n找到負責人，並且殺了他。到時候，我們才能確定他們的計畫真的失敗了。", progress = "還有更多陰謀…", completion = "監禁者…絕對統治肩鎧…\n\n這個叫科爾蘇加德的巫妖一直在興風作浪。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58609] = {title = "奪取王座", objective = "在瑪卓薩斯的統御者之座向德拉卡女爵回報。", description = "明智的選擇，<name>。在你的指揮下，我們一定能讓瑪卓薩斯重返榮耀。\n\n你的力量能讓整個暗影之境變得更好。只有加入死靈領主的行列，你才能徹底發揮潛能。\n\n現在，快點前往統御者之座。德拉卡女爵會在那裡等你，並提供後續指示。", progress = nil, completion = "歡迎回來繼續戰鬥，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58610] = {title = "伊露恩代言者", objective = "到女王的花園附近找塞爾納斯。", description = "<name>，命運對我們微笑了。我們在亞登曠野找到一位過去曾是黑夜戰士的靈魂。就像泰蘭妲現在一樣。\n\n他的名字叫做塞爾納斯。我聽說他在幫忙照顧那些在黑夜花園休息的靈魂。\n\n找到他，向他求助吧。希望他擁有對我們有幫助的知識。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58615] = {title = "黑暗中的低語", objective = "在心之室找出恩若司的低語來源。", description = "你也聽到了？那可不是好事。\n\n要是恩若司進入這個房間，我們就全部完蛋了！\n\n我們得搞懂他是從什麼地方連通到這裡，然後將它阻絕在外，預防他對我們做出低語之外的事！", progress = nil, completion = "我們做了什麼？\n\n如果不是萊公的犧牲，這裡可能已經淪入恩若司的掌握，而艾澤拉斯就會任他宰割了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58616] = {title = "鑄造勇士", objective = "與骸骨工匠黑彌爾聊聊符文刃的事。", description = "在抵達那塊石頭的所有靈魂當中，只有你發現了它真正的用途。\n\n我不是狂熱迷信的人，但顯然這儀式有更深的意義。我們應該要進一步調查，才是明智的做法。\n\n去骸骨工匠黑彌爾的熔爐旁找她。她是瑪卓薩斯最有名的鐵匠，也是統御者親自教導的學徒中，僅存的最後一位。\n\n她一定知道該怎麼做。", progress = "還有別的事嗎？", completion = "這得要花一點功夫才行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58617] = {title = "上情下達", objective = "傳令給召喚師佩雷斯、訓練中士泰利斯及武鬥士梅維斯。", description = "傳令是勝利的關鍵。如果命令無法傳達，那最偉大的戰略家也毫無用武之地。\n\n將我的命令傳給召喚師佩雷斯、訓練中士泰利斯及武鬥士梅維斯。\n\n而且越快越好！每多浪費一刻，就有一個敵人會獲得優勢！", progress = nil, completion = "那樣應該確保我們備戰完成了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58618] = {title = "鑄骨附魔", objective = "殺死骨髓之顎，從牠的屍體收集強化骨頭。", description = "強大的武器需要有強大的配件，我正好知道有東西符合我們的需求。\n\n最近我們的士兵把一隻傀儡家族訓練的怪物困在城塞的東側。維拉斯堅持我們可以從那隻怪物的心靈裡抽取「情報」！\n\n哼，統御者的意志會勝過男爵充滿野心的慾望的！\n\n那隻怪物的骨骼正好適合鑄造這把武器的刀柄。你該去拿回那些骨骼！", progress = "你夠膽去處理它嗎？", completion = "很好！我就知道它根本不是你的對手。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58619] = {title = "字裡行間", objective = "跟隨塔伊蘭前往知識墓穴，聽聽他的請求。", description = "啊，凡人，我還真幸運，謙卑的塔伊蘭剛好站在這裡，而你，大家津津樂道的外來者，剛好經過這裡！\n\n依據分工合作和互蒙其利的精神，我想跟你討論一件事。\n\n這附近有個稱為知識墓穴的地方，裡面存放了不少兵法書。我擔心書裡記載的知識很快就會消逝。\n\n如果你願意護送我到墓穴，我可以分享一些有用的情報。", progress = nil, completion = "凡人，你準備幫我搶救這些珍貴手稿了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58620] = {title = "靈魄流動", objective = "使靈魄流向鎖定的方尖碑。", description = "<name>，要進入這座墓穴可真不容易！\n\n不僅有難纏的守護者，還有複雜的魔法鎖把門給封住了。\n\n要打開門，就必須供應靈魄給那兩座控制著門鎖的方尖碑。還好，我們可以用這附近的強化水晶來達成目的。\n\n找到那些水晶，重新導引靈魄到方尖碑。墓穴裡的秘密馬上就要變成我們的了！", progress = nil, completion = "你成功了，門已經打開了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58621] = {title = "跟著我複誦", objective = "閱讀五個家族的符文石，然後對每塊石頭執行正確的「/表情」指令，向其致敬。", description = "統御者在墓穴四周安排了多個守護者，保護裡頭的知識。而每一位守護者都是五大家族的理念的化身。\n\n要進入墓穴，就得打敗這些守護者，證明你的價值。\n\n找出代表瑪卓薩斯各大家族的符石。注意符石上所刻的文字，然後向每個家族的代表價值致敬。\n\n正確致敬之後，守護者就會現身。然後再將他們打敗。", progress = "統御者的確非常聰明。", completion = "那些守護者都解決完畢，我們可以專心解鎖大門了。", rewards = "您能選擇下列奬勵中的一個：\n\n學習者璽戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58622] = {title = "書架上的秘密", objective = "找回收藏在墓穴中的典籍。", description = "既然墓穴的大門已經解鎖，我們就能進去裡面了。\n\n這裡的「我們」指的就是「你」。至少在安全無虞之前。\n\n裡面珍藏的書籍都是出自瑪卓薩斯的無數軍事天才之手。為了死靈領主的未來，請盡你所能，收集這些珍貴的書籍。\n\n合理推測，這些書籍都受到陷阱保護。統御者不會讓任何人隨隨便便染指這些知識。\n\n等你清出一條路，我就會跟你會合。", progress = nil, completion = "到目前為止都做得很好。\n\n我們就快能看到那些秘密文獻了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58623] = {title = "集齊一整套", objective = "收集勝利之籍。", description = "這只是第一卷？\n\n光只有第一卷不夠，這種稀世珍寶要湊成一套才有用！\n\n盡量收集其他部份，我會成立一支大型探險隊，將這些書卷全部搬走。", progress = "找齊了嗎？", completion = "挽救了好多珍貴的知識，這一切多虧了你的幫忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58624] = {title = "絕對統治肩鎧", objective = "帶著絕對統治肩鎧回到統御者之座。", description = "現在，我們知道誰該為瑪卓薩斯的亂局負責。\n\n如果科爾蘇加德真的跟監禁者結盟，那麼他所擁有的力量絕對超乎任何人的想像。\n\n我們必須圍攻祭儀家族，不過我們需要時間準備。在沒有周全計畫的情況下，貿然發動攻擊，只會註定失敗。\n\n現在，先將肩鎧送回統御者之座。我們在那裡會合。", progress = nil, completion = "戰鬥才剛剛開始。", rewards = "刃誓先驅者肩鎧刃誓之魂護肩刃誓咒術師披肩刃誓策略家肩甲您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58630] = {title = "收割者之冠", objective = "到永恆熔爐找米卡尼寇斯。然後，協助他鑄造收割者之冠。", description = "你打算凝聚的力量非常不穩定，需要永恆熔爐的火焰才有可能辦到。\n\n沒有烈焰的加持，它恐怕會反過來壓制持有者。\n\n帶汎希爾朋友過來，他的魔法會派上用場。需要靠你來吸取雜質。\n\n<米卡尼寇斯交給你一個典雅的容器。>\n\n使用這個吸納在過程中燒出的雜質。", progress = nil, completion = "完美。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58631] = {title = "踏入夢境", objective = "在心之室和母親大人交談，追蹤萊公的下落。", description = "我不敢相信萊公犧牲自己來拯救我們。我們不能丟下他！\n\n一定有什麼辦法可以查明他的下落。\n\n我們問問母親大人，有沒有辦法可以追蹤他！", progress = nil, completion = "那道傳送門一定是通往恩若司領域的入口。\n\n如果想把萊公救回來，然後徹底解決恩若司，這可能是我們唯一的機會！", rewards = "您會收到：\n\n恐怖幻象容器"}
MultiLanguageQuestData['tw'][58632] = {title = "奈奧羅薩，甦醒之城：腐化者的末路", objective = "在奈奧羅薩，甦醒之城擊敗恩若司。", description = "透過魔古的研究，母親大人和萊公找到一個方式，可以透過心之室來聚焦熔爐的起源協定。唯一的問題就是找出它該射向何方。\n\n一直到現在，這個問題才迎刃而解。\n\n帶著這些錨具，穿過那道傳送門。你得把它們安置在一些顯眼的地標上，我們才能把武器聚焦在那裡。在設置完成後，我們就可以開火了。\n\n你只有一次機會。好好把握！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58634] = {title = "開啟大門", objective = "與母親大人交談，在心之室建立陰暗傳送門。", description = "現實的脈絡斷裂了。不過應該不需要我告訴你，<name>。畢竟你已經親眼見證。\n\n這些現實遲早會合而為一，籠罩在永恆黑暗之中。與其東躲西藏，也許現在正是我們擁抱黑暗的時候。\n\n有了泰坦朋友的幫助，我們或許可以將這個現實化為一根針，穿過另一個現實化成的布，達成穿針引線的效果。\n\n畢竟，瞭解敵人的意圖，就等於瞭解敵人的弱點。", progress = nil, completion = "時候到了，我們該準備面對最深沉黑暗的挑戰。", rewards = "您會學到：\n\n陰暗傳送門\n\n您還會收到：\n\n聚合幻象"}
MultiLanguageQuestData['tw'][58636] = {title = "盯緊阿瑪賽特", objective = "在奧丹姆和高等探險者德羅拉一塊偵察阿瑪賽特的領土。", description = "僅代表探險者協會，我想要感謝你協助我們建立奧丹姆協議者，並為我們爭取到一些來自蘭姆卡韓的助力。\n\n看在有可能更瞭解敵人的好處上，蘭姆卡韓允許我們探索阿瑪賽特陵墓。不過，不幸的是，他們的部隊散得太廣，難以提供保護。\n\n我希望你能在這方面出點力。\n\n你能不能撥出一點時間，探探他們是什麼來路？我們可以先從空中觀察著手。", progress = nil, completion = "要記錄的事情好多啊！真希望在獅鷲獸背上寫筆記能容易一點。\n\n不過，我想我們看到的只能算冰山一角。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58638] = {title = "深度潛入", objective = "在高等探險者德羅拉解譯日長石露台上的阿瑪賽特紀念碑時保護她。", description = "這些阿瑪賽特不太對勁。為什麼泰坦的守護者會著手攻擊並破壞起源熔爐？\n\n我們需要近距離觀察。我在那邊的露台上看到一個紀念碑，或許上面的記述可以讓我們更瞭解這些托維爾。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58639] = {title = "埋藏的歷史", objective = "在奧丹姆尋找並收集6個阿瑪賽特文物。", description = "自從阿瑪賽特從這個區域現身後，我們可以合理推測，他們把自身文明的文物藏在黃沙之中。\n\n看來該進行一些例行的挖掘工作了！\n\n在這附近的沙丘下面，一定埋藏著一大片阿瑪賽特的舊有領土。我們來看看能從中挖出什麼！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58640] = {title = "防護的弱點", objective = "在高等探險者德羅拉解譯起源大廳外面的阿瑪賽特紀念碑時保護她。", description = "以你幫我們挖掘出來的古物來判斷，阿瑪賽特是一個以保護泰坦成果為傲的部族。\n\n這一點證實了我們的假設，也指出他們身上一定發生過某些激烈的變化，導致他們開始破壞原本發誓要保護的一切。\n\n我們應該繼續追查他們的文獻。我想我在起源大廳外面看到不少近期的紀念碑。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58641] = {title = "腐化的追尋者", objective = "到奧丹姆從觸日阿瑪賽特身上收集太陽之王敕令。", description = "要說是誰能更瞭解石板上提及的「腐化」，肯定就是那些負責驅逐它的觸日者。\n\n當然了，我不認為他們會自願交出任何資訊。\n\n不過我運氣不錯，你對使用暴力的調查方式頗有心得，不是嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58642] = {title = "共同的目標", objective = "在高等探險者德羅拉解譯眾星之間的阿瑪賽特石板時保護她。", description = "你找到的敕令中，提到一個擊敗古神的計畫。\n\n我知道阿瑪賽特不太可能和我們攜手合作朝目標邁進，但是如果他們這個計畫有辦法解決恩若司，就值得我們一探究竟。\n\n敕令中提到晉升引擎。我想那可能就是我們之前看到、他們稱為日能強化裝置的東西。我們應該到下面一探究竟，希望能夠瞭解他們的計畫！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58643] = {title = "全面毀滅的保證", objective = "警告起源大廳的守衛者，告知阿瑪賽特的計畫。", description = "阿瑪賽特想要把起源熔爐搶回去，然後用它來終結艾澤拉斯上連同古神在內的所有生物！\n\n他們隨時都可能發動攻擊，我們必須警告熔爐的守衛者！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58645] = {title = "值得拯救的世界", objective = "阻止阿瑪賽特勢力攻佔起源大廳。", description = "我們擋不住他們，他們的戰士…身邊籠罩著太陽的火焰…\n\n他們要用熔爐…來終結萬物…\n\n去吧…我會…撐下來…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58646] = {title = "再咬咬看啊！", objective = "在奧丹姆殺死8頭食腐沙丘行者。", description = "那些癩皮土狼會啃掉它們挖出來的任何東西，包括那些無價古物！\n\n這樣說吧，我們不能容忍奧丹姆的歷史毀在狗嘴中。\n\n我們恐怕得削減它們的數量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58647] = {title = "破損的網", objective = "協助修復捕魂網。", description = "我的丈夫過去曾是我們族人的伊露恩代言者…直到他成為黑夜戰士。他對這件事的感覺…有點難以言喻。\n\n木魈一直在撕毀花園裡的捕魂網。可以請你幫我修好嗎？工作的同時我會跟你們說我們的故事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58654] = {title = "給收割者的請求", objective = "把彌海菈的字條交給宮務大臣。\n\n已提供物品：\n", description = "你在奇怪的時間點到來。我們要繳給稅務官的稅一天比一天多，但我們收獲的靈魄卻一天比一天少。\n\n我們這裡處理的靈魂已經面臨最終審判，但我們資源不足，無法在不危害村莊的情況下收割它們。\n\n如果你在宮務大臣面前說得上話，你或許能傳消息給主宰本人。\n\n來，收下這封信。請務必把信送到宮務大臣手中。", progress = nil, completion = "喔，那些農民求你幫忙，對吧？\n\n足夠忠心的人就知道，要讓瑞文崔斯屹立不搖，有時候犧牲是不可避免的。的確，靈魄近來嚴重不足，而新的靈魂也極度缺乏。\n\n但不管多麼辛苦，我們都必須盡到自己的本分。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58656] = {title = "皇冠的重擔…", objective = "測試收割者之冠，擊敗運作中的巨像。", description = "收割者之冠的不穩定，源自戴納瑟斯王殘留在勳章上的影響。試用幾次應該就能消除。\n\n裝入你的其中一個勳章，見證其力量凝聚在充滿破壞力的武器上。\n\n現在時機正好，棄誓者完成了巨像傀儡。摧毀它們，讓棄誓者迎來他們渴望的末日。\n\n小心點，希奧塔告訴過我，這之中的魔法強大無比。收割者之冠永不饜足，必須小心掌控。", progress = nil, completion = "你還活著。收割者之冠開始吞食你的靈魂，\n\n看來還需要改進一下。米卡尼寇斯說了，戴納瑟斯王的影響還殘留在收割者之冠上。\n\n他說他有辦法解決。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58660] = {title = "潛伏的恐懼", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58661] = {title = "潛伏的恐懼", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58662] = {title = "潛伏的恐懼", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58665] = {title = "反叛的靈魂", objective = "到西瑟佛隱居地找拉桑和艾曼妮。", description = "請聽我們說，淵喉行者。\n\n當藩侯珈爾瑪對昇靈堡發動攻擊時，有許多人像我和艾曼妮一樣，反對他的行動。\n\n珈爾瑪深怕有人非議，將許多靈魂從傀儡中移出來並囚禁。艾曼妮逃出了監禁，但大多數人沒辦到。\n\n協助我們釋放其他靈魂，我們就可以為你建造一支傀儡大軍，遠勝於為珈爾瑪效力的部隊。", progress = nil, completion = "別讓艾曼妮那酸溜溜的性格嚇到你。我們非常感謝你的協助，淵喉行者！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58667] = {title = "黑曜精華", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58668] = {title = "找到去路", objective = "帶拉桑和艾曼妮前往身體零件銀行。", description = "長久以來，我一直在縫合場中裡實習。我甚至曾經在身體零件銀行中，和縫補師縫肉合作設計艾曼妮的上一具傀儡。\n\n如果我們能掌控身體零件銀行，我們就可以取得必要的零件來重建艾曼妮，並為我們救出來的其他靈魂製作全新的身體。\n\n帶我們過去，看看我們能不能讓它運作。", progress = nil, completion = "我從來沒想過會回到這個地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58669] = {title = "修整花園", objective = "殺死15隻鐮棘木魈。", description = "有時候，木魈會入侵這裡的花園，散播惡作劇與混亂。他們帶來的麻煩真是一言難盡。\n\n曠野獵者通常會制止他們搗亂，不過獵人們最近無暇分神這種小事情。我和塞爾納斯一直在協助清除花園的木魈，不過他現在跑去生悶氣了。\n\n<可達林搖了搖頭。>\n\n如果你能幫我清除出沒在女王花園的害蟲，那就太感激了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58670] = {title = "屠殺之女", objective = "協助艾曼妮追殺清單上的每一個人。", description = "我在被囚禁的時候，列出了背叛我的傀儡清單…這份清單很長很長！\n\n幫我教訓這些傀儡，要他們悔過！清單上的每一個我都要除掉，包括頭號叛徒，縫補場管理者帕拉克！", progress = nil, completion = "我認為我們的意思傳達得很清楚了，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58671] = {title = "困在其中", objective = "到乙太寶庫解救10個被囚禁的靈魂。", description = "有許多靈魂反對藩侯珈爾瑪攻擊昇靈堡。那些表達意見的人被奪走了身體，被囚禁在乙太寶庫，直到我們的靈魂在缺乏靈魄下消散。\n\n我的朋友還被囚禁在寶庫中，我們會釋放他們，並打造一支傀儡大軍來為你作戰！", progress = nil, completion = "我們合作無間呢，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58672] = {title = "勇士雲集", objective = "到奧格瑪與瓦麗拉‧桑古納爾交談。", description = "部落的領袖齊聚奧格瑪，準備提名新的部落大酋長。\n\n身為部落的傑出勇士，你也必須出席這場會議。這場集會將在奧格瑪的大使館舉行。\n\n我會先行一步。你一到奧格瑪，就來找我，我會跟其他人一起等候你。\n\n事不宜遲，勇士。這次的聚會將決定部落的未來…", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58673] = {title = "部落的大酋長", objective = "見證勇士們的集會。", description = "決定下任部落大酋長的會議即將開始。\n\n部落的其他領袖都已經抵達。他們都在大使館等你。\n\n準備好了就告訴我一聲，我們會一起向其他人問好。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58674] = {title = "勇士雲集", objective = "到暴風城與馬迪亞斯‧肖爾交談。", description = "烏瑞恩國王邀請聯盟領袖前來暴風城一敘。\n\n你也被特別要求一同出席。這場集會將在大使館舉行。\n\n你到了暴風城之後就來找我，我會跟其他人一起等著你。\n\n請儘快動身，<name>。讓國王久等實乃不智之舉…", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58675] = {title = "和平的代價", objective = "見證烏瑞恩國王發表演說。", description = "國王很快就會發表演說，帶來他出訪部落之後的最新消息。\n\n聯盟的其他領袖都已經抵達。他們一定都很想聽聽烏瑞恩國王要說的話。\n\n準備好了就告訴我一聲，我們一起去見國王。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58676] = {title = "休眠的毀滅者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58677] = {title = "切膚之痛", objective = "取得艾曼妮的頂級皮膚", description = "這份工作可能超越了你的理解能力，但你還是聽好了：\n\n身為傀儡，整個暗影之境都怕我。我的傀儡擁有頂級的皮膚，凡人的武器無法傷我，那是花費了好多年才能達到完美的藝術品。\n\n我從傀儡中被移除之後，法多‧伊斯卡這傢伙高興地偷走了皮膚。他把它留在自己身上當作紀念。\n\n殺了法多‧伊斯卡，把我的皮膚奪回來！", progress = "如果我還活著，你可能會是我的朋友，或是我的晚餐。", completion = "你讓我的冷血沸騰了。你或許是個夠格的盟友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58679] = {title = "休眠的毀滅者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58680] = {title = "鬆脫的線", objective = "找到串插針、鋒絲線軸和凝血貼片。", description = "我們還少了幾個縫製傀儡的工具和零件。如果要重建我的傀儡，這些東西絕不能少！\n\n搜尋附近區域。看看能不能找到我們需要的東西。\n\n去桌子上找串插針，然後在搬運工身上可以找到鋒絲線軸，並從你殺死的傀儡身上找到凝血貼片。", progress = "你在這方面很厲害。", completion = "你該考慮換個傀儡化的身軀，或許改天我可以幫你設計一具。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58686] = {title = "量產武器", objective = "讓組裝實驗室開始運作。", description = "我們的運氣真好！\n\n縫補師縫肉和他的助手還沒從昇靈堡回來。整座縫合場只有幾個守衛。\n\n我們的動作要快，看看能不能讓儀器運作起來。啟動之後，就可以開始生產了。", progress = nil, completion = "我們快搞定了！只要再一個步驟就可以完成傀儡！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58704] = {title = "黑夜花園", objective = "到中央花園殺死木魈。", description = "這一區應該這樣就可以了。現在我們要去照顧內花園。完成之後，我再去處理我固執的丈夫。\n\n希望剩下的木魈已經聽到我們對付他們的同伴，早已逃之夭夭。您會收到：\n\n", progress = nil, completion = nil, rewards = "妖精編織便鞋橡心裹踝女王近衛脛甲符文看守者長靴您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58705] = {title = "杉札拉女皇", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58706] = {title = "解體獵物", objective = "幫助胡恩‧高嶺分割吞噬者。", description = "<胡恩在聽完你的說明之後，陷入了沉思。>\n\n我想我瞭解了，<name>。但我沒辦法現在馬上幫你。\n\n我會好好跟你說明。與此同時，可以幫我切割這個屍體嗎？每個獵物身上都有可以學習的事物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58707] = {title = "遍尋幻象", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n恐怖幻象容器"}
MultiLanguageQuestData['tw'][58708] = {title = "追求地精名聲更待何時", objective = "到波拉勒斯與技工大師歐沃斯巴克會面。", description = "技工大師歐沃斯巴克需要你加入一場重要的研究遠征行動並提供協助。\n\n能夠和備受尊崇的大工匠共事，肯定能對你的事業提供助益。像我在過去就獲得了數不清的好處！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58714] = {title = "森林中的眼線", objective = "殺死躲藏在冬日窪地各處的被附身的間諜。", description = "那個夢境好悲傷！看了尖牙與利爪…還有揪心的犧牲…\n\n<月莓有一瞬間哽咽，才慢慢恢復儀態。>\n\n不好意思！當我們還在夢境裡面時，被附身的間諜已經溜進冬日窪地了！\n\n一定要在他們將林地防禦的情報送回去之前，將他們全部除掉。\n\n來，我借你一點我的魔法。找出潛藏在暗影中的目標並消滅他們！", progress = nil, completion = "這些佐司特真大膽，居然敢派間諜來我的林地！真大膽…也真愚蠢。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58717] = {title = "緬想之鈴", objective = "在遺忘墓穴找到知道這個鈴鐺故事的人。", description = "<這個鈴鐺外表傷痕累累。你記得監管者對這件物品非常感興趣。\n\n或許在遺忘墓穴有人知道詳情。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58719] = {title = "樹林長的呼喚", objective = "使用樹林長的號角召喚曠野獵者進入林地。", description = "我們的敵人快速進逼，<name>。我們必須吹響號角，保衛林地！\n\n使用這個號角，召來我們的保衛者。召喚曠野獵者前來殺死攻擊我們的敵人。", progress = nil, completion = "曠野獵者趕來幫忙…唯獨西邊杳無音訊？\n\n狩獵隊長克芮恩帶了人去西邊追蹤危險的敵人，她和她的狩獵隊一定是遇到埋伏了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58720] = {title = "無影無蹤！", objective = "到重生之路找狩獵隊長克芮恩。", description = "曠野獵者響應號召，前來保衛我們…狩獵隊長克芮恩和她的部隊除外。\n\n她帶領狩獵隊伍去了西方，追蹤一個強大的敵人，他們可能遇到麻煩了。\n\n找到她，並且盡可能幫助她。\n\n我們需要她的獵人和領導力，才有可能鞏固我們的防禦。", progress = nil, completion = "這些佐司特本來打算派部隊從背後偷襲我們。\n\n&lt;克芮恩露出得意的笑容。&gt;\n\n你的號召喚來我的獵手夥伴們助我們一臂之力。敵人反而成為被偷襲的一方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58721] = {title = "喚醒夢旅者", objective = "前往醒覺林地。", description = "女王將大部分的注意力都放在醒覺林地。在那裡，靈魂會從野性種子中復甦，返回他們各自的世界。\n\n既然你身上帶著受傷的靈魂，或許那裡正好合適。\n\n<赫恩勛爵研究了一下伊瑟拉的野性種子，然後臉上慢慢露出微笑。>\n\n她全心全意還在戰鬥。即便是現在，她仍想活下去。\n\n來吧，陌生人，我們去看看女王會如何決定她的命運。", progress = nil, completion = "&lt;凜冬女王轉頭凝視著你。&gt;\n\n真稀奇，像你這樣的人居然會出現在我的森林。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58723] = {title = "凜冬之廷", objective = "將統御者的消息告知凜冬女王。", description = "我的屬下通知我，說你送來重要的消息。\n\n你現在可以傳達了。", progress = nil, completion = "監禁者蠢蠢欲動，而亞登曠野的力量卻因靈魄乾旱而衰退。", rewards = "您能選擇下列奬勵中的一個：\n\n暗夜侍臣戒指\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58724] = {title = "女王的要求", objective = "回到奧睿博司去找塔因納拉。", description = "這確實是個惡兆。\n\n我用了僅存的靈魄來拯救我們的林地和保存其中的靈魂。失去的太多了…而森林之心還逐漸衰弱。\n\n需要更多的靈魄才能繼續將監禁者束縛在淵喉裡。遠超亞登曠野所能供應的量。\n\n<女王思索了一下。>\n\n戴納瑟斯王十分擅長抽取靈魄，前去瑞文崔斯並告知他我們的危機。我知道他一定會伸出援手。\n\n你在奧睿博司的盟友能幫你開啟通道。", progress = nil, completion = "亞登曠野發生了什麼事？把一切都告訴我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58725] = {title = "罪孽看守者", objective = "使用緬想之鈴，從遺忘墓穴召來靈魂，然後審視靈魂的命運。", description = "這是緬想之鈴。在發生最近的…「變故」之前，我們用它從遺忘墓穴召出靈魂，審視它們的命運。\n\n如果它們不再像之前那樣傲慢自大，就能進入到下個階段。反之，則必須繼續在墓穴待上更長時間。\n\n我們來用用看，如何？看來已經殘破不堪，希望還能發揮一點功用。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58726] = {title = "厚皮", objective = "從增生的物質上收集40張脈動皮革碎塊。", description = "統御者打造了一把好武器，但以它目前的狀況看來，也派不上用場。\n\n幸運的是，我有足夠本事完成他的作品！\n\n話說回來，我需要材料。其他天選者都忙著戰鬥訓練，就算他們需要更多的武器和護甲，也沒辦法來熔爐協助我。\n\n但這就是你能出力的地方。你想要新武器？那你就要有付出。", progress = "沒有那麼難吧，是吧？", completion = "你動作很快，對吧？我需要更多像你這樣的助手。", rewards = "冷酷處刑者腿甲屍體縫補師護腿血肉建構者護腿欺詐密探馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][58727] = {title = "稱為家的地方", objective = "到屠夫區與拉桑和艾曼妮會面。", description = "你不在我的清單上…所以，看來我們是朋友了…至少目前是。\n\n拉桑把你釋放出來的靈魂帶到統御者之座附近的屠夫區了。\n\n我們過去和他會合，一起規劃下一步。", progress = nil, completion = "這地方實在太適合我們了。我們可以在這裡打造新的傀儡，還能建造一個新家。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58737] = {title = "麥格尼的發現", objective = "瞭解一下麥格尼發現了什麼。", description = "讓熔爐重新運轉是個好消息，但我們似乎又在魔古山寶庫的書庫中，找到徹底解決恩若司的關鍵。這簡直是錦上添花！\n\n你最好坐穩了再繼續聽下去，勇士。", progress = nil, completion = "看來我們有可行的計畫了！\n\n來看看怒西昂對於尋找奈奧羅薩一事有什麼盤算。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58740] = {title = "被馴服的戰蛟", objective = "在恆春谷殺死4隻瑪瑙戰蛟。", description = "參天所到之處，戰蛟必定如影隨形。\n\n這些野獸超級無敵危險。看到它們被魔古馴服，著實令人感到惋惜，但我們不能讓它們為所欲為。\n\n我需要你幫忙，趁它們還沒瓦解我們的防線之前，把它們解決掉。", progress = nil, completion = "看到雲蛟被殺死真是不幸，但是參天的所作所為已經讓它們難以復原了。\n\n別擔心，我們會讓他們付出代價的。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58741] = {title = "切開石頭", objective = "在恆春谷收集10個魔古武器。", description = "跟其他魔古交戰的難題在於，攻擊這些由石頭和金屬所構成的敵人，武器一下子就會鈍掉或是毀損。\n\n身為萊加尼唯一的鐵匠，有的時候要滿足所有戰士的需求還真是不容易。\n\n如果你在與魔古戰鬥的過程中有發現任何武器，我有把握可以讓它們派上用場。", progress = "有什麼發現？", completion = "這些武器的狀態不差。\n\n我們的戰士會好好運用。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
