MultiLanguageQuestData['tw'][58748] = {title = "扮人體雕像好難", objective = "在寵物對戰中擊敗格里席斯‧微爆。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58749] = {title = "維爾席克的飛行", objective = "在寵物對戰中擊敗格里席斯‧微爆。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58750] = {title = "大膽抓牛", objective = "騎乘5頭血膚牛獸回到敦戴身邊。", description = "我在這裡還算是闖出了一點名氣，大家都知道我是那個有牛獸的人，因為每個人都需要牛獸！\n\n你幫我做點事，然後大家也會認識你。\n\n拿著這個骸骨破片，弄些多汁的啃咬者來引誘牛獸，然後把牠騎回我身邊。", progress = nil, completion = "這幾頭是上好的牛獸。感謝你的幫忙，凡人！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58751] = {title = "共臨危難", objective = "到廢棄大牢找到失蹤的女爵。", description = "瑪卓薩斯的每個家族都有兩位爵士。在我的老家族…蛛眼家族殞落之前，我們的藩候派了我手下的女爵去調查祭儀家族有沒有可疑的行為。\n\n從那之後，我再也沒有她的消息。如果不是發現了什麼蹊蹺，就代表她又成為了背叛之下的犧牲品。\n\n她的命令要她前往東邊的凋亡地。如果你找到女爵，把這份傳喚文件交給她。\n\n我和她沒有交情，但她是個強大的戰鬥者，我們需要她的力量。", progress = nil, completion = "你要慶幸在這裡找到的人是我。\n\n瑪卓薩斯的其他人或許尚未察覺你的潛在實力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58754] = {title = "蟲群的勇士", objective = "在恆春谷擊敗3個稀有的螳螂人敵人。", description = "顯然杉札拉在這次的入侵行動中傾巢而出。我們的斥候在戰場上發現了她麾下最強大的勇士的蹤跡。\n\n哪怕只有一隻，金蓮會的弟兄也很難對付這種螳螂人，我們必須親自出馬才行。\n\n你要一起來嗎？", progress = nil, completion = "你的擊殺數真是驚人。只差我一點點。\n\n下次或許有機會超過我。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58755] = {title = "藏匿的補給品", objective = "從恆春谷的琥珀化寶箱中收集3個金蓮會補給品。", description = "侵略我們的螳螂人最近一直把金蓮會的補給品偷走。他們可能是想要活活餓死我們。\n\n如果我們拿不回補給品，還真有可能被他們得逞。\n\n你在對付蟲群的時候，幫忙留意一下四周，說不定我們的補給品就被藏在某處。如果你能拿幾個補給品回來，那可真是幫了金蓮會一個大忙。", progress = "你有找到我們的補給品嗎？", completion = "你找到它們了！也太幸運了吧！\n\n這些補給品可以幫助我們抵擋螳螂人，說不定還能幫助我們驅逐螳螂人呢！\n\n金蓮會欠你一次！", rewards = "您會收到：\n\n艾澤萊晶岩戰爭物資戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58756] = {title = "可怕的治療者", objective = "在恆春谷殺死6個螳螂人琥珀施法者。", description = "琥珀施法者是社會地位最高的螳螂人。他們能夠透過法術任意修補並創造琥珀，讓剛剛歷經戰鬥的螳螂人部隊得以迅速恢復。\n\n他們是具有戰術價值的目標，我們應該把他們揪出來。\n\n要一起來嗎？", progress = nil, completion = "這下蟲群裡面沒有可以替士兵療傷的幫手了，驅逐蟲群只是時間早晚的問題。\n\n你做得很好。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58757] = {title = "考驗新手", objective = "在恆春谷殺死12個維爾席克群生幼螳。", description = "在戰鬥的時候，螳螂人會派出大量幼螳對抗敵人，藉此來測試幼螳的能耐。成功存活下來的幼螳，就可以成為蟲群裡真正的戰士。\n\n我們應該盡全力阻止，讓這些幼螳無法通過考驗。", progress = nil, completion = "居然派出毫無作戰經驗的生物來對抗做好萬全準備的敵人，螳螂人還真是愚蠢。\n\n希望他們永遠也學不到教訓。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58758] = {title = "橫衝直撞的破壞者", objective = "在恆春谷殺死4個崑蟲破壞者。", description = "金蓮會對上一次被螳螂人侵略的事情還記憶猶新。在蟲群發動進攻之前，螳螂人會派出大型崑蟲，藉此弱化敵方的防禦陣線。\n\n看來他們的戰術並沒有改變。\n\n我們必須阻止這些崑蟲，要不然金蓮會將無法抵禦蟲群的入侵。全指望你去把它們擊倒了。", progress = nil, completion = "崑蟲是很危險的野獸。居然能夠打敗他們，你可真是勇敢，&lt;class&gt;。\n\n金蓮會感謝你。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58759] = {title = "女皇的守衛", objective = "在恆春谷殺死8個札拉席克螳螂人。", description = "札拉席克是女皇的精英守衛。他們經過艾澤萊晶岩強化，不徹底征服整個潘達利亞誓不罷休。\n\n如果被他們攻破蟠龍脊，金蓮會絕對打不贏。\n\n在牆那邊擋住他們，<class>。", progress = nil, completion = "你似乎成功擋住他們的攻勢了。這樣應該暫時還撐得住。\n\n如果情況變糟，我會再通知你。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58760] = {title = "琥珀之刃", objective = "從恆春谷的螳螂人身上收集12個琥珀之刃。", description = "螳螂人很脆弱，但是他們所揮舞的琥珀之刃卻威力強大。\n\n只要稍微改造一下，就可以把這種琥珀之刃拿給魔古使用。\n\n把琥珀之刃拿來給我，我會把它們改造成萊加尼的工具。", progress = "你把刀帶來了嗎？", completion = "跟樹木一樣脆弱的生物，居然可以打造出如此鋒利耐用的刀刃，這點著實令我吃驚。\n\n或許就連螳螂人也有值得我們學習的地方。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58761] = {title = "踩在腳下", objective = "在恆春谷壓扁10個維爾席克幼蟲。", description = "以前螳螂人會把幼螳放在孵化室裡面加以保護，等待這些幼蟲準備好加入蟲群接受考驗。\n\n不過這些維爾席克很粗心，會讓自己的幼蟲隨便跑到戶外。\n\n要是有人跑去消滅那些幼蟲，那就不好了，你說是吧？\n\n才怪。", progress = nil, completion = "啊，看著自己腳底下踩著敵人的未來棟樑。\n\n感覺真好，對吧？", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58762] = {title = "被蟲群擄走", objective = "從恆春谷的硬化琥珀囚牢中釋放6位金蓮會的囚犯。", description = "這次的螳族有些不一樣。他們不像平常的螳螂人那樣見人就殺，他們這次會活捉防衛者。\n\n我不想知道他們都是怎麼對待俘虜的。\n\n這樣好了，你去營救俘虜吧，這樣他們就不用受苦了。", progress = nil, completion = "你救出他們了嗎？噢，謝天謝地！\n\n我猜不透螳螂人活捉囚犯是想要幹什麼，但準沒好事！", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58763] = {title = "中斷生產", objective = "到恆春谷摧毀6個琥珀瓶。", description = "螳螂人生活中大大小小的事情幾乎都有用到琥珀，從居住用的建築，到手上的武器無所不包。當然了，我對後者比較感興趣。\n\n如果我們可以奪走螳螂人的材料，就可以奪走他們用來發動戰爭的工具。\n\n找到他們存放琥珀的地點，讓他們再也無法使用琥珀。", progress = nil, completion = "螳螂人痛失寶貴的琥珀，再也無法重新補給了。\n\n做得好，&lt;class&gt;。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58764] = {title = "蟲群的準則", objective = "在恆春谷燒毀6面札拉席克旗幟。", description = "不知好歹的螳螂人自以為贏了。他們到現在還敢在蟠龍脊懸掛旗幟宣示地盤。\n\n一定要讓他們知道，潘達利亞是屬於熊貓人的。\n\n把他們的旗幟給燒了。", progress = nil, completion = "他們的足跡已經從恆春谷這邊被徹底根除。用不了多久，他們的部隊也會全滅。\n\n等到我們終於能把他們給趕出蟠龍脊的那個時候，希望我可以和你並肩作戰。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58765] = {title = "攻城機具破壞者", objective = "在恆春谷破壞3台維爾席克戰車。", description = "金蓮會靠自己的力量就可以對抗螳螂人的戰士了，這點毫無疑問。但是他們的戰車只需要開一砲，我們的鬥士小隊就會被打得落花流水。\n\n如果我們要持續在這場戰鬥裡佔上風，就需要派人滲透敵營，然後破壞掉他們的攻城機具。\n\n希望你可以自告奮勇。", progress = nil, completion = "我們的斥候回報，說是有好幾台螳螂人的戰車遭到摧毀，場面壯觀無比。\n\n我想這件事情應該要感謝你。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58771] = {title = "不含使用說明書", objective = "從追憶中樞的被丟棄的卷軸中找到中樞說明書。", description = "看看這個地方！簡直一團糟。追憶中樞停止運作，被這些「棄誓者」佔領了。\n\n我們需要讓追憶中樞恢復運作，但我不知道該怎麼做。這個地方不是我設計的，而且是很久以前就建造好的。\n\n不過我們運氣很好，在我之前的首席熔爐士是個工作狂，大小事都會記錄下來！如果我們能夠找到她的設計圖，那我一定能想出辦法。就算沒有助憶士幫忙也沒關係。\n\n看看四周，散落著無數卷軸。等你找到我要的卷軸，就到追憶中樞附近找我。", progress = "你找到正確的卷軸了嗎？", completion = "你找到了！還找到了其他許多有趣的典籍。等這裡的事情結束後，一定要好好分門別類。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58773] = {title = "被俘的棘語者", objective = "到亞登曠野的日暮林地解救琦娃。", description = "很高興那頭老熊還沒忘了我。\n\n不幸的是，佐司特也還對我念念不忘。在他們出現以前，我很享受我平靜的來生。\n\n別浪費力氣，試圖用暴力打開這個牢籠。只有使用三把不同的鑰匙，才能打開它，而且每把鑰匙都在不同的佐司特指揮官手中。\n\n他們應該就在這附近，去找他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58775] = {title = "晉見女王", objective = "到亞登曠野的森林之心謁見凜冬女王。", description = "<name>，我們只需要最後一步就能完成晉升紋章了。\n\n幾個紀元以前，我們的紋章原先是在妖精的幫助下打造而成。在亞登曠野深處有道由妖精負責維護的傳送門，它是用來將靈魂渡回他們的世界的。那道傳送門本身就是道強大的力量，而且是重建紋章的最後關鍵。\n\n去亞登曠野尋找凜冬女王，懇求她解決我們的需求。我們已經先派佩拉苟斯擔任我們的使節，前去安排你的會面。", progress = nil, completion = "我們現在有許多工作要處理。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58776] = {title = "孵化問題", objective = "在奧丹姆摧毀6組亞基蟲卵。", description = "亞基數量增加的速度，比我們屠殺它們的速度還要快。如果繼續這樣下去，過不了多久我們就會被蟲海淹沒了。\n\n延緩它們攻勢的唯一方法，就是直接攻擊蟲巢並摧毀蟲卵，但是我們一直沒有成功。\n\n所以我們需要徵召你入伍。\n\n你願意幫忙嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩戰爭物資"}
MultiLanguageQuestData['tw'][58777] = {title = "踩下去", objective = "在奧丹姆輾碎8個亞基幼蟲。", description = "<在你靠近的時候，札菈踩爆了某個像蛞蝓一樣黏呼呼的生物。>\n\n看到了嗎？這種東西看起來好像沒什麼威脅，但是卻能讓那些蟲子成長，我不騙你。\n\n被亞基佔領的地方到處都是這種東西，它們會啃食我們的死者，然後成長為這些怪物。\n\n如果你有看到這種東西，請踩它們一腳，幫世間除害。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戰爭物資戰爭物資聚合幻象艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58778] = {title = "搶得先機", objective = "從奧丹姆的亞基巨怪身上收集1個巨怪戰利品。", description = "營地的士氣最近一直很低靡。沒想到被蟲子咬傷這種事情，居然會影響到大家的心情。\n\n不過我有個點子，可以提振部隊的精神。我們需要戰利品！\n\n去找那種粗壯魁梧的蟲，把它的頭砍下來給我，這樣我們就可以讓那些昆蟲知道，我們不是好惹的！但至少要讓人還認得出來那是頭，好嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58779] = {title = "控制天空", objective = "在奧丹姆殺死15隻會飛的亞基。", description = "我想要派出更多飛行單位，讓他們驅逐亞基，但是空中的蟲子實在太多了，要回到日陽方尖碑那裡幾乎不可能。\n\n我們得先在地面上削減它們的數量，如此才有機會取得制空的優勢。\n\n我可以指望你幫忙嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩戰爭物資戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58780] = {title = "蟲巢先驅", objective = "在奧丹姆殺死5個亞基支配者。", description = "攻擊我們營地的亞基，主要好像是由突擊部隊所組成的。不過，勇敢深入敵軍陣線後方的斥候發現了另一種不同的生物，那種生物又高又瘦，還能駕馭危險的虛無魔法。\n\n我的直覺告訴我，這些生物就是指揮敵人的領袖。它們是需要優先擊殺的目標，路上遇到格殺勿論。\n\n你願意接受這個任務嗎？", progress = nil, completion = "只要砍下來的頭夠多，就連多頭蛇也得死。\n\n在打仗的時候，請記得這件事。", rewards = "您會收到：\n\n艾澤萊晶岩戰爭物資聚合幻象艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58781] = {title = "來自深淵的恐怖", objective = "在奧丹姆擊敗3個稀有的亞基敵人。", description = "亞基每天都威脅著廢土漫遊者的生活，但我聽說還有更可怕的東西跟著它們一起跑了出來。\n\n我們的鬥士很能打，但是如果其中一個古老且可怕的敵人找上我們，後果還是不堪設想。\n\n我知道你曾經打敗過強大的敵人。我想要請你幫忙擊退這樣的敵人。\n\n如果我們遭到沉寂已久的怪物攻擊而損傷慘重，那麼我們將難以保護熔爐的安全。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩戰爭物資戰爭物資"}
MultiLanguageQuestData['tw'][58782] = {title = "來不及帶走的東西", objective = "從奧丹姆的被感染儲藏箱中收集3個廢土漫遊者補給品。", description = "來犯的亞基迫使廢土漫遊者必須逃離我們位於奧丹姆的營地。倉促之間，有很多東西沒能帶走。\n\n我知道你想要主動出擊去對付那些野獸。你去那邊的時候，能不能順道注意看看有沒有我們沒帶走的補給品？\n\n當然了，如果是對你有用的東西，你可以自己留著用。", progress = "有什麼收穫嗎？", completion = "你找到補給品了嗎？謝天謝地！\n\n如果沒有做好準備，會很難熬過沙漠的夜晚。這些東西能夠確保我們得以生存。\n\n廢土漫遊者欠你很大的人情，&lt;class&gt;。", rewards = "您會收到：\n\n艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩艾澤萊晶岩"}
MultiLanguageQuestData['tw'][58785] = {title = "連打帶捕", objective = "捕捉10頭新生的骨牙獸。", description = "骨牙獸是瑪卓薩斯武裝部隊的支柱，每個家族都需要訓練有素的骨牙獸。\n\n我一直都需要新的骨牙獸接受訓練，但它們真的很難找。\n\n幫我送一些年輕的骨牙獸來，我會給你豐厚的獎勵。建議你先弱化它們，再著手捕捉它們。", progress = nil, completion = "我對我們的成果相當滿意！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58787] = {title = "晉升試煉", objective = "到欣悅庭院找克蕾雅。", description = "棄誓者的威脅尚未解除，我們的部隊規模卻逐漸縮小。此時此刻，我們迫切需要補充晉升者。\n\n慷慨的御靈者賜予我們一部分的靈魄貯存，協助優秀的志士晉升並加入我們。\n\n克蕾雅也在晉升之列，因此她必須完成最終試煉。\n\n由於佩拉苟斯還沒做好晉升的準備，因此我請求你幫助克蕾雅通過這次試煉。這是個艱鉅的任務，絕非一人所能完成。\n\n她必須引渡她的第一個靈魂。", progress = nil, completion = "棄誓者佔領了庭院，妨礙我們接受試煉！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58788] = {title = "引導香爐", objective = "從棄誓者部隊身上收集10份引導薰香。", description = "棄誓者無所不用其極地阻止我們晉升。\n\n他們動員大軍，擋在我們面前，剝奪我們參與儀式的機會。\n\n他們還偷走我們開始試煉所需的資源。擊敗他們，取回他們身上的薰香，讓我們得以繼續前進。", progress = "每個香爐都需要相當多薰香，我們必須確保收集到足夠的薰香。", completion = "將我們自己的靈魄注入薰香，我們就能展開各自的旅程。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58789] = {title = "誤人子弟的導師", objective = "殺死戰略家帕拉迪雅和招募官荷路斯。", description = "這些志士…我們曾經一起接受訓練，一起學習。\n\n棄誓者過去引誘他們偏離晉升之路，現在又帶領他們走上絕路。\n\n他們背棄了正道。解決率軍攻擊我們的晉升者。", progress = nil, completion = "志士們居然選擇背棄御靈者意志，我心中的刺痛感永遠不會平復。", rewards = "無私收集者巨披風無私引渡者披風無私看守者披風無私熔爐士的披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][58790] = {title = "穿越帷幕", objective = "協助克蕾雅進行引導儀式。", description = "帕爾莎找到了有儀式說明的卷軸。\n\n我們必須各就各位，吟詠讚美詩，將部分靈魄灌注到一字一句中。\n\n你在這過程中不可或缺，請你在我們冥想時，使用香爐焚燒薰香。剩下的就水到渠成了。", progress = nil, completion = "我知道你是這個世界的生物。能夠得到你的協助，是克蕾雅的榮幸。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58791] = {title = "人生中的一天", objective = "見證班恩‧霍爾的最後一刻。", description = "引渡者的工作在於帶領靈魂穿過帷幕，進入奧睿博司。靈魂在那裡接受審判，然後被分派至暗影之境的其中一個國度。\n\n這個靈魂已經可以啟程了。\n\n在這場試煉中，你將會體驗他死前的最後一刻。\n\n等你準備好了，就會看到這個靈魂的死前景象。", progress = nil, completion = "喔，你在這啊，親愛的。我一直在找你！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58792] = {title = "魂歸何處", objective = "使用幕飛號角前往奧睿博司，然後見證班恩‧霍爾的審判。", description = "這個靈魂不再留戀他的艾澤拉斯世界。\n\n克蕾雅必須盡她的本分，將他引渡到奧睿博司，由審斷者進行審判。\n\n拿著這個禱鐘，等你準備好了，它會召來晉升者，帶著你們穿過帷幕，回到奧睿博司。\n\n莫忘職責。", progress = nil, completion = "我…需要一點時間好好想想。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58793] = {title = "穿越黑暗的信念", objective = "到樂土堡向阿德雷特斯回報。", description = "靈魄乾旱的範圍…已經超乎我的想像。\n\n為什麼沒人告訴我們？\n\n這個消息簡直讓人難以承受…我們引渡靈魂，居然是讓他們承受永恆的折磨？\n\n我們必須回家。", progress = nil, completion = "很高興看到克蕾雅成功回到我們身邊，儘管她心存疑惑，卻還是盡到自己的本分。\n\n希望所有志士都能像她一樣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58794] = {title = "西進行刺", objective = "殺死滿足的鋸齒怪。", description = "我最近陸續發現牛獸的屍體，而且為數不少，我知道罪魁禍首就是凱利希情有獨鐘的骨牙獸！\n\n我發現有一頭生物該對這些屠殺負責，就在此地西邊。去除掉它！\n\n記得不要向凱利希提到這件事！", progress = nil, completion = "你表現得很好，別告訴凱利希就是了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58795] = {title = "晉升者", objective = "協助佩拉苟斯進行晉升儀式。", description = "成功通過試煉後，我們的志士現在準備開啟死後的新篇章。\n\n經過數紀元的訓練和淨化，他們證明了自己，如今獲得晉升的資格。\n\n每叫到一名志士，請你和佩拉苟斯負責引導他們上前。這是我們沿襲了數紀元的傳統，強化我們之間的羈絆。", progress = nil, completion = "有棄誓者？在這種時候？\n\n這是全面進攻！", rewards = "無私收集者腿甲無私引渡者護腿無私看守者腿甲無私熔爐士馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][58796] = {title = "棄誓者的猛襲", objective = "驅逐入侵的棄誓者。", description = "不應對忠誠者的背叛視若無睹。\n\n但在神聖楷模守住城市的時候，就只能靠我們守護樂土堡。\n\n我傷得很重…但我會奮戰到底。我和佩拉苟斯會保護倖存者。你必須幫忙抵禦這波攻勢！", progress = nil, completion = "現在已經化險為夷。\n\n樂土堡或許安全了，不過晉升之巔還需要我們的援助！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58797] = {title = "歷經千錘百煉", objective = "與克蕾雅完成靈魂之絆儀式。", description = "<name>，我的朋友。\n\n一直以來，我都將你視為盟友。當你決定加入昇靈堡陣營時，我興奮不已…我知道你會成為我們的生力軍。\n\n共同經歷的試煉讓我們彼此的羈絆越來越堅固。沒有你，我可能早就像艾奇隆一樣，因為受不了新知帶來的刺激而墮落。\n\n我希望更加鞏固彼此的羈絆，我很榮幸能與你建立靈魂之絆。", progress = nil, completion = "你、我，還有親愛的佩拉苟斯。\n\n我敢說這世上沒有比我們更厲害的團隊。", rewards = "您會學到：\n\n靈魂之絆：克蕾雅\n\n下列法術會施放在您身上：\n\n休息\n\n您還會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58798] = {title = "晉升之巔", objective = "到晉升之巔擊敗『猜疑楷模』德沃絲。", description = "我們的任務尚未完成。\n\n我們或許已經擊退樂土堡這裡的棄誓者，不過這只是為了讓我們分散兵力而進行的佯攻。\n\n御靈者和神聖楷模親自上陣，試圖奪回晉升之巔。\n\n在這種危急時刻，我們必須毫不猶豫援助他們！", progress = nil, completion = "這場攻擊讓我們學到不少教訓，御靈者應該會召集剩下的神聖楷模，一起討論棄誓者的威脅。\n\n需要請你幫忙的時候，我們會再次召你前來。", rewards = "您會收到：\n\n御靈者飛羽名望名望"}
MultiLanguageQuestData['tw'][58799] = {title = "首席的指令", objective = "收集12個百衛機兵核心。", description = "所有百衛機兵生來都是要為琪瑞安效力。\n\n它們現在竟然敢反抗我這個首席熔爐士，這是對昇靈堡的所有百衛機兵的羞辱。看看它們！這些軍教官！巨人！這些…華而不實的東西！\n\n我在此授權給你，明確命令你取出它們的核心。我將會根據它們的行動，將其轉成更適合的用途：回收它們的靈魄，作為中樞的動力。\n\n我還能再造出更多百衛機兵，不必憐憫它們。", progress = "你拿到核心了嗎？", completion = "非常好。它們的靈魄將會用於更好的用途。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58800] = {title = "追憶中樞", objective = "使用靈魄導體讓追憶中樞恢復運作。", description = "<米卡尼寇斯檢驗你幫他取回的卷軸。>\n\n很好，很好。\n\n靈魂之鏡和中樞密不可分。只要我們恢復靈魂之鏡的靈魄供給，它應該就能讓中樞徹底回歸正常。幸好，你送來的這些核心應該夠用。\n\n我現在只需要啟動導體就好，非常簡單！\n\n怎麼了？上啊，你知道該怎麼用，不是嗎？", progress = nil, completion = "靈魄的嗡嗡聲真是悅耳，我已經好久沒聽到這麼響亮的聲音了。", rewards = "您能選擇下列奬勵中的一個：\n\n迴銀指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58802] = {title = "超級厲害的蟲卵", objective = "帶著虛無染化的蟲卵前往蘭姆卡韓找賀帕索‧阿多羅斯。", description = "<亞基蟲族似乎一直在用虛無魔法強化這個蟲卵。\n\n看樣子要孵化還很久，所以可以安全地研究這個蟲卵，看看它們想要拿它來做什麼。\n\n探險者協會應該有人會對這件事感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58803] = {title = "比照辦理", objective = "調查7個奧丹姆裡的虛無染化的蟲卵。", description = "放心吧，孵化出來的東西不會做出什麼壞事的。畢竟亞基又不是「蟲性本惡」，你說是吧？\n\n不過我們還真不知道要怎麼照料這種蟲卵。我需要你去幫忙調查一下。\n\n回去亞基蟲巢那裡，看看還能不能找到其它類似的蟲卵。如果我們能夠觀察它們的行為，就可以把照料蟲卵的方法給學過來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58804] = {title = "虛無孵化", objective = "在遭受恩若司部隊襲擊的地方收集10個晶化虛無。", description = "有一件事情是可以確定的，就是這個蟲卵需要大量的虛無能量才可以成長茁壯。\n\n現在剛好有古神在攻擊艾澤拉斯，真是幸運，你說是吧？\n\n不是嗎？噢…\n\n反正呢，只要是恩若司爪牙出沒的地方，都應該會有豐富的虛無能量。出發去尋找吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58805] = {title = "繼續孵化", objective = "在遭受恩若司部隊襲擊的地方收集10個晶化虛無。", description = "蟲卵的狀況很不錯，但我們還需要更多的虛無水晶，才可以讓它保持健康。\n\n你可以再去幫忙收集一些回來嗎？", progress = "你又帶來更多的虛無水晶了嗎？", completion = "好哩，這些會很管用的。\n\n我會繼續照顧蟲卵，也會讓你知道最新的進展。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58806] = {title = "太陽的溫暖", objective = "在奧丹姆收集阿瑪賽特的太陽能收集器。", description = "奧丹姆沙漠的夜晚冷斃了。我擔心我們寶貴的蟲卵會無法抵抗低溫。\n\n東邊的阿瑪賽特似乎是懂得駕馭太陽能量的專家。如果可以借用他們的技術，我們就可以讓這個蟲卵過得舒舒服服的。\n\n多多留意能派得上用場的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58807] = {title = "包裹起來", objective = "在奧丹姆從亞基施法者身上收集30個亞基絲網。", description = "我發現這個蟲卵有一個很奇怪的現象，那就是它上面沒有亞基蟲巢裡面那種到處都是的保護絲網。\n\n我認為這種絲網具有保護效果，如果能拿一點過來的話，對我們的蟲卵應該會有幫助。\n\n在你出發對付昆蟲的時候，順道看看能不能帶點絲網回來，這樣子我們就能為正在發育的蟲卵做一個繭出來了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58808] = {title = "包在琥珀裡", objective = "在恆春谷標記一個琥珀孵化器，讓賀帕索把它空運走。", description = "你知道誰是照顧蟲卵的專家嗎？螳螂人！\n\n不過，他們整天忙著殺我們，沒空分享撇步，但是應該有另一種方式可以利用他們的知識！\n\n或許，我們可以把他們的其中一個孵化室挪作他用。我相信這樣一定可以加快孵化的過程！\n\n要是你能找到並且標記好的話，我就可以從空中把它運走。", progress = nil, completion = "簡直完美！\n\n這下我們的蟲卵有一個舒適的小窩了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58809] = {title = "驚雷科技", objective = "收集8個來自恆春谷的聚雷針材料。", description = "我聽說魔古會用閃電來加快雲蛟的成長速度。不知道同樣的方法對我們的亞基朋友有沒有效？\n\n只有試過才知道了！前往恆春谷，看看你能不能把材料收集齊全，然後做出屬於我們的聚雷針。\n\n如果跟聚雷針對雲蛟的效果一樣的話，應該可以大幅提升蟲卵孵化的速度。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58810] = {title = "破殼而出", objective = "在蘭姆卡韓看亞基蟲卵孵化。", description = "看來我們的蟲卵已經準備好孵化了！我好興奮啊！\n\n讓我們一起來迎接這位小伙伴的到來。", progress = nil, completion = "你看，他是不是很神奇啊！\n\n距離他變成亞基成蟲還有很長一段路要走，但他目前的狀態就已經夠雄偉了！", rewards = "您會收到：\n\n亞基蟲卵堆"}
MultiLanguageQuestData['tw'][58811] = {title = "均衡飲食", objective = "從奧丹姆和恆春谷的野獸身上收集12個肉塊。", description = "我們的幼蟲已經孵化，接著我們得想方法餵飽他，讓他保持健康。\n\n看樣子亞基蟲是肉食性生物，但是我只看它們吃過…我們這些人。\n\n當然了，我們不能餵這位小伙伴吃人，所以我們得找個替代品。也許可以拿動物的肉來代替？", progress = nil, completion = "看樣子動物的肉不是他最愛吃的。\n\n他暫時是不會餓肚子了，我們之後再嘗試點不一樣的方法。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58812] = {title = "替代肉品", objective = "從奧丹姆或恆春谷的亞基蟲族和螳螂人身上收集12個蟲族的肉。", description = "野生昆蟲把自己族類吃掉是再正常不過的事。不知道這個道理能否套用在亞基身上。\n\n你可以帶點亞基蟲或螳螂人的肉回來嗎？我們的朋友說不定更喜歡那種東西。", progress = nil, completion = "可憐的小東西，昆蟲肉害他肚子痛。\n\n我們只能明天再嘗試點別的了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58813] = {title = "發臭的食物", objective = "前往遭受恩若司爪牙襲擊的區域，從生物身上收集12個腐化血肉。", description = "我突然想到，既然這個生物被注入了虛無能量，或許他會更喜歡…腐化的食物。\n\n我指的當然是恩若司的爪牙了。\n\n機會不大，但值得一試。", progress = nil, completion = "做得好！小傢伙吃得一乾二淨！\n\n而且這也是好事一樁。省得我去找法歐瑞斯討要托維爾人的新鮮屍體。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58816] = {title = "進入後台", objective = "從星湖劇場後台取回一個夜幕花環。", description = "我們下一步要準備的容器，是一組夜幕花。\n\n我們會在儀式中使用這些花朵，但自從乾旱降臨之後，只有在演出時才會用它來突顯扮演的角色。星湖劇場的後台肯定會有。\n\n我敢打賭月莓就在那邊排練下一場劇。另一個好處是，這是我對她進行報復的大好時機。\n\n<柳絮在那一瞬間露出了邪惡的笑容。>", progress = "你找到花了？", completion = "大功告成！這一定很有趣。啊，甜蜜的復仇。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58817] = {title = "玩具公仔", objective = "從奧丹姆的阿瑪賽特身上收集6個阿瑪賽特刻像。", description = "我突然想到，我們的幼蟲目前日子還過得挺枯燥乏味的。我們應該找點東西來給他玩。\n\n畢竟幼蟲要開心才會健康！\n\n阿瑪賽特應該有保留用來膜拜神的雕像。我相信那些東西也可以拿來給我們的小伙伴當玩具。去找幾個回來給他玩吧！", progress = "你有找到合適的玩具嗎？", completion = "你看看，新玩具超讓他開心的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58820] = {title = "血肉工藝束腕", objective = "將血肉工藝束腕放回統御者的雕像上。", description = "這是血肉工藝束腕！它們讓統御者有能力形塑瑪卓薩斯的血肉。\n\n我們必須把它們送回正確的位置，好讓它們的力量激勵我們所有人。", progress = nil, completion = "我感受到力量了。或許護腕會給我們正需要的優勢。", rewards = "刃誓先驅者護臂刃誓之魂臂甲刃誓咒術師裹腕刃誓策略家護腕您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58821] = {title = "光榮追獵", objective = "綁架『忠誠者』梅菲里斯，然後殺死6位病態侍徒來恐嚇他。", description = "或許德拉卡已經忘了她的忠誠，但我會貫徹我的使命。\n\n巫妖摩爾拜坦是我的敵人，他就藏身在祭儀家族領地中。基於某些理由，他的下屬躲在這片沼澤裡。\n\n我們還不清楚他們為什麼會在這裡，但我的虔信者找到了摩爾拜坦的副指揮官，『忠誠者』梅菲里斯。他握有我們想要的答案。\n\n幫我把他帶來。抓到他之後，就殺掉他的同夥，削弱他的意志。\n\n我會讓基地做好審問他的準備。", progress = nil, completion = "對一個名留青史的英雄而言，應該易如反掌。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58825] = {title = "超級蜂王乳", objective = "在恆春谷收集8個濃縮的絕佳蜂王乳。", description = "我金蓮會的朋友告訴了我幾個關於全新螳族的有趣情報。它們顯然已經製作濃縮的絕佳蜂王乳，可以加快新孵化的螳螂人的生長速度。\n\n如果這種蜂王乳對螳螂人有用，按理來說對亞基蟲也會有用！\n\n去尋找這種蜂王乳的樣本，幫助我們的幼蟲生長。", progress = nil, completion = "你看他那狼吞虎嚥的樣子！\n\n希望這東西會有效。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58826] = {title = "血的饗宴", objective = "從恆春谷的多卡尼魔古身上收集8瓶純化的靈魄。", description = "我聽說某個名為多卡尼的魔古氏族精通了駕馭生命之力的本領，並且把生命之力轉換成了一種名為「靈魄」的物質。\n\n如果這種東西真的是濃縮成液體的生命力，那麼把它用在我們的亞基幼蟲身上將會有不得了的效果。\n\n去看看有沒有什麼型態的靈魄是我們能加以利用的吧。說不定小伙伴會喜歡！", progress = "你帶靈魄回來了嗎？", completion = "他很喜歡呢！食物摻有血的味道，這應該有助於他的胃口。\n\n我會持續注意情況，看看靈魄對我們朋友的生長過程會造成什麼樣的影響。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58829] = {title = "一暝大好幾吋", objective = "在蘭姆卡韓幫助亞基幼蟲破繭而出。", description = "你看！我們的幼蟲朋友化成蛹了！\n\n等等…看起來他好像已經準備要破繭而出了。\n\n過去幫他一把吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n影鉤飛蟲寶寶"}
MultiLanguageQuestData['tw'][58830] = {title = "亞基的本能", objective = "使用賀帕索的哨子召喚你的亞基蟲寶寶，在奧丹姆或恆春谷與敵人作戰。與更強悍或稀有的敵人作戰可使你的蟲寶寶成長得更快。", description = "在觀察亞基蟲與廢土漫遊者打仗的過程中，我發現剛一孵化的蟲會馬上加入其它亞基蟲的行列發動攻擊。看來這些生物天生就好戰。\n\n我們應該幫蟲寶寶鍛鍊鍛鍊了。當然，要由你來親自監督。帶他出去外面，讓他見識一下怎麼跟敵人作戰。\n\n他可能沒辦法戰鬥太久，所以你得在準備周全的時候，再叫他出來。\n\n如果運氣好的話，他說不定會把我們視作他的族類。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58831] = {title = "磨練本能", objective = "使用賀帕索的哨子召喚你的亞基蟲寶寶，在奧丹姆或恆春谷與敵人作戰。與更強悍或稀有的敵人作戰可使你的蟲寶寶成長得更快。", description = "我們的小伙伴看起來很煩躁，他已經準備好繼續進行戰鬥練習了。\n\n你願意教導他該怎麼做嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58832] = {title = "琴可琴可小混帳", objective = "殺掉噬絲者琴可。", description = "<潦草的寫著偷取絲行者幼蟲，以及烹煮牠的計畫。\n\n署名的是個叫做琴可的傢伙。>", progress = nil, completion = "該死的木魈！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58833] = {title = "召集所有幫手", objective = "到祭儀家族領地與德拉卡和盟友會面。", description = "$p，時候到了。\n\n我們不能讓科爾蘇加德把祭儀師的巫術當作武器。非消滅他不可。\n\n集結我們的部隊，朝祭儀家族進軍！", progress = nil, completion = "我們有因緣巧合才聚在一起，不過我們現在並肩作戰。\n\n今天的勝利，也是整個瑪卓薩斯的勝利。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58842] = {title = "監管者", objective = "到遺忘墓穴找監管者。", description = "我派監管者重新取回貪婪勳章。\n\n不過，自從她從淵喉回來之後，她的心智變得…有點混沌。溫和一點，好嗎？\n\n我請你協助她進行研究。她在遺忘墓穴。", progress = nil, completion = "我們一定要趕在戴納瑟斯的僕人之前取回這些鏡子裂片。\n\n這是進入地穴的唯一管道，我把我的勳章藏在裡面。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58843] = {title = "御靈者寶庫", objective = "設法進入御靈者寶庫。", description = "我身後便是御靈者寶庫的入口。如你所見，入口有結界保護，防止任何未經許可的人擅闖。\n\n如果要獲得許可，請將你收集的供品放在守護者面前。之後有空的時候，就能來瀏覽寶庫的內容物。\n\n請牢記，棄誓者想盡辦法要進入寶庫，這也是他們在這裡的唯一目標。建議你做好隨時應戰的準備。", progress = nil, completion = "非常高興見到你。這段時間一直沒有訪客造訪寶庫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58844] = {title = "破曉之前", objective = "集結看守者、引渡者、百衛機兵和收集者。", description = "如果要取得勝利，我們需要其他部隊。\n\n集結看守者、引渡者、百衛機兵和收集者。告訴他們，他們的御靈者正在呼喚他們。\n\n神聖楷模會在欣悅庭院清出一塊集結地，為最後的攻擊做準備。", progress = nil, completion = "希望你準備好了，淵喉行者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58846] = {title = "大義", objective = "擊敗萊索妮雅。", description = "棄誓者是曾經與我們並肩作戰的兄弟姊妹…我們昔日的同胞。但我們不能遭到矇蔽。\n\n我們會從四面八方打擊他們。好好表現，但別忘了萊索妮雅才是我們的終極目標。不打倒她的話，她就會在日後徵募更多人完成目標。\n\n循道而行，<name>。", progress = nil, completion = "我們終於等到了這一天，感謝你。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58847] = {title = "基瑞絲緹雅的恩典", objective = "護送烏瑟。", description = "我記得這個特別的靈魂…烏瑟。不久前，德沃絲把他帶到我們面前。她為他辯護，表示他的靈魂與淵喉有所連結。\n\n她隨即把他納入麾下，在他還沒準備好前就讓他晉升。從某種程度來說，他成為她除了萊索妮雅之外的副手。\n\n他還有改變心意的機會，但我們要靜觀其變。好好留意他的狀況。因為御靈者的恩典，他可以留下，但我不會對一個…傷痕累累的人掉以輕心。", progress = nil, completion = "願薩尼歐斯的付出能開花結果。我經歷過這麼多紀元以來，從沒看過如此殘破的靈魂。", rewards = "您能選擇下列奬勵中的一個：\n\n頂點靈魄珠奇蹟靈魄珠蒼穹靈魄球敬意靈魄球神秘靈魄球\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58854] = {title = "召集神聖楷模", objective = "召喚神聖楷模，呼喚他們展開行動。", description = "我們一步步擊敗棄誓者，拯救還沒走遠的人。我們一次次將他們逐出受祝福的御靈者神殿，現在只剩一座。\n\n忠誠神殿。\n\n萊索妮雅因為失敗，變得越來越不顧一切。她放棄了我們堅持守護的一切，全心擁抱淵喉。她在神殿集結了最狂熱的部下，因為她知道我們會去對付她。\n\n我們需要神聖楷模才能解決這一切。召喚他們。", progress = "在對抗萊索妮雅時，如果沒有神聖楷模，我們無法存活。", completion = "現在神聖楷模已經就緒，我們一定要集結其他兵力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58856] = {title = "你想拐誰？", objective = "從鐮棘木魈身上奪取鐮棘魔粉，驅散明顯目標上的幻象來找出阿蠐。", description = "少了一位十分特殊的客人，我們無法舉行儀式。他是一位名叫阿蠐的絲行者幼蟲，而且是我最好的朋友。\n\n不幸的是，可惡的木魈把他抓走了！更糟的是，他們在偷走的東西上面施加幻象，所以沒有人能拿回來！\n\n木魈經常帶著惡作劇粉末。如果你能拿到一些粉末，我可以逆轉他們的幻象，並救出阿蠐。", progress = nil, completion = "我們找到他了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58857] = {title = "種子脫離！", objective = "阻止果姆攻破果姆蟲巢防禦牆，別讓牠們肆虐亞登曠野的其他地方！", description = "我想我們碰到麻煩了。我們從這條樹根摘取種子，結果喚醒了一些鑽地的果姆！這有點棘手。\n\n抓緊我。我會帶你飛離這裡，不過我們必須阻止果姆，否則牠們會攻破當地沃爾凱的防線！", progress = nil, completion = "很好，現在萬事俱備了，&lt;name&gt;。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][58858] = {title = "更多發臭的食物", objective = "前往遭受恩若司爪牙襲擊的區域，從生物身上收集12個腐化血肉。", description = "我們的小傢伙又餓了。\n\n你可以去幫忙找點吃的來餵他嗎？", progress = nil, completion = "太棒了！這樣他一定可以長得又大又壯！\n\n希望到時候他不會把我們給吃掉！", rewards = nil}
MultiLanguageQuestData['tw'][58859] = {title = "旗鼓相當的對手", objective = "讓影鉤飛蟲寶寶加入隊伍，並在寵物對戰中擊敗『追尋者』雷提那斯。", description = "我們的蟲寶寶一路上跟你並肩作戰，肯定鍛練得相當不錯。偶爾讓他單獨跟旗鼓相當的敵人戰鬥，效果會更好。\n\n我知道附近有某個跟他旗鼓相當的對手，就在眾星方尖碑附近的阿瑪賽特。你可以去找找看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58860] = {title = "大壞蟲", objective = "讓影鉤飛蟲寶寶加入隊伍，並在寵物對戰中擊敗亞基沙行者。", description = "跟另一隻亞基交戰會有助於我們的蟲寶寶，讓他了解自己的族類有什麼能耐。\n\n我已經幫他找到對手，可以讓他打一場有挑戰的戰鬥。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58861] = {title = "螳螂人精神", objective = "讓影鉤飛蟲寶寶加入隊伍，並在寵物對戰中擊敗維爾席克幼蟲。", description = "我們可以讓蟲寶寶去觀察螳螂人的戰鬥技法，藉此來訓練他，讓他了解還有什麼其它方法可以使用昆蟲與生俱來的武器。\n\n我已經在恆春谷找到某隻螳螂人，可以拿他來當我們蟲寶寶的對手。帶蟲寶寶去那邊，看看他表現如何。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58862] = {title = "小小防衛者", objective = "讓影鉤飛蟲寶寶加入隊伍，並在寵物對戰中擊敗巴魯克石衛者。", description = "大家都知道巴魯克的魔古會活化遠古雕像，讓它們防衛自己的地盤。它們是很耐打的對手，跟這種防禦堅若磐石的敵人對打，可以累積很多經驗。\n\n我們很幸運，好像有塑石者不小心活化了某個小塑像。活化這個塑像的魔古覺得它沒有用處，就把它丟了，它是我們用來訓練蟲寶寶的大好機會。\n\n在恆春谷找到這個小防衛者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58863] = {title = "訂製物品", objective = "與蘭姆卡韓的鐵匠阿巴西交談。", description = "我想我們的小伙伴已經不再是蟲寶寶，而是亞基成蟲了！已經成長茁壯的他，甚至還可以載著你進入戰場呢。\n\n等等，這個想法超讚！\n\n你可以去跟鐵匠阿巴西談談，看看能不能做個馬鞍出來。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58865] = {title = "來自異世界的裝備", objective = "從奧丹姆與恆春谷的黑暗帝國教徒身上收集12個黑暗帝國武裝。", description = "要幫你的巨蟲打造鞍座，我會需要幾個特殊材料。主要是金屬，比我們目前所擁有的金屬還要輕盈的金屬。\n\n我發現黑暗帝國教徒身上帶的武器是用異世界的材料做成的。那種材料輕得嚇人，卻又堅固無比。\n\n如果你能夠帶幾把他們的武器回來，我說不定可以熔化那些武器的金屬，然後做出可以給亞基蟲使用的鞍具。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58866] = {title = "我自己的飛蟲", objective = "把異界鞍具帶去給蘭姆卡韓的賀帕索‧阿多羅斯。", description = "鞍座完成了。我不喜歡拿那種腐化的金屬來製作東西，但話雖如此我還是不得不說，這是我這輩子所打造過品質最好的鞍具。\n\n我知道它看起來有點…另類。不過我向你保證，你的亞基蟲一定會覺得很舒適。\n\n希望它會對你有幫助。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n影鉤雄蜂"}
MultiLanguageQuestData['tw'][58869] = {title = "為了冬日窪地而戰", objective = "打贏冬日窪地之役。", description = "我們要在這裡挺身奮戰。佐司特和他們的爪牙差點就擊潰我們了。\n\n不過我們不會讓他們摧毀冬日窪地。更不會讓他們奪走我們的靈魄或野性種子。\n\n跟我們一起戰鬥，把他們趕出去。", progress = nil, completion = "我們拿下勝利了。\n\n…但伊瑟拉恐怕難保。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58871] = {title = "天無絕人之鹿", objective = "到森林之心向赫恩勛爵回報。然後與月莓交談。", description = "可達林身上的詛咒非常強大。\n\n但我一定會破解那個詛咒。\n\n<塞爾納斯哼了一聲。>\n\n就連死亡也沒讓我們分離，現在也別想要我離開他。\n\n<塞爾納斯神情嚴肅地仔細觀察你和珊蒂斯。>\n\n幫我救他，我就會幫助你們世界的黑夜戰士。我不能保證救得了她…但我會說出我知道的一切。\n\n回到森林之心，向赫恩勛爵告知整個情況。我們在那裡碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58876] = {title = "失落的飛龍", objective = "將薇希歐娜之子交給心之室的怒西昂。\n\n已提供物品：\n", description = "<在恩若司偌大的軀殼內，有一隻幼龍從其中一個孵化室裡冒出頭來。牠看起來很困惑。\n\n你推測這種孵化室一定是拿來腐化龍類用的，讓毫無防備的牠們直接受到恩若司黑暗低語的影響。跟你之前所遇過的其他暮光龍軍團的成員比起來，年輕的幼龍更容易被逼瘋。\n\n一旦發瘋，就無法恢復正常了。\n\n但也許還來得及拯救這隻幼龍…>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n未腐化的虛無之翼"}
MultiLanguageQuestData['tw'][58877] = {title = "死亡之力的茁壯", objective = "向巫妖王宣誓效忠。", description = "仔細聽好了，<name>。毀滅的時代即將到來，我們將面臨生死存亡的挑戰。現在的情況尤其危急，我們必須挺身保護艾澤拉斯。\n\n因此，我網羅了更多勇士加入我的麾下，包括你的族人。犧牲奉獻會讓你變得與眾不同。昂首挺胸吧。你將成為黯刃騎士團死亡騎士，直到永遠。\n\n向我宣誓忠誠吧。", progress = nil, completion = "我接受你的效忠。別讓我們失望。\n\n為此，我們特地打造出全新的黯刃騎士專屬的武器。\n\n選擇吧，我的勇士。", rewards = "黯刃燃燒巨劍黯刃赤紅巨劍黯刃穢邪巨劍黯刃冰凍巨劍黯刃赤紅軍刀黯刃冰凍軍刀黯刃穢邪軍刀黯刃燃燒軍刀您會收到：\n\n"}
MultiLanguageQuestData['tw'][58879] = {title = "餵飽羊駝", objective = "<對著你背包的所在方向好奇地嗅聞著，並睜大眼睛看著它。>", description = nil, progress = "<對著你背包的所在方向好奇地嗅聞著，並睜大眼睛看著它。>", completion = "&lt;大口咀嚼著吉爾薩草，一邊歡樂地哼唱著。&gt;", rewards = nil}
