MultiLanguageQuestData['tw'][58887] = {title = "羊駝登場", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n躍毛羊駝韁繩"}
MultiLanguageQuestData['tw'][58900] = {title = "穩賺不賠", objective = "到苦痛劇場的入口見安吉歐。", description = "你打響了自己的名號，贏得這裡所有人的尊敬，包括奧納寧在內。\n\n$p，你已經準備好了！\n\n安吉歐正在苦痛劇場的入口等我們，你就要成為冠軍勇士了！", progress = nil, completion = "你為了這一刻走了很長一段路。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58902] = {title = "艾澤拉斯防衛者", objective = "與大領主達瑞安‧莫格萊尼交談。然後，使用大領主的死亡之門前往暴風城。到了那裡之後就去找克羅米。", description = "選得好。\n\n現在正值艱困的時刻。身為少數被選中的人，保護世界之責既是你的負擔，也是你的光榮。這是一份至高無上的榮譽。\n\n但請做好準備，因為你會被無知的人鄙視。凡人往往只看得見我們恐怖的外表，卻看不見我們的內在。不要理會這種蠢蛋，做你該做的事。\n\n去找你的指揮官談話。然後使用他的死亡之門前往生者的領域，並選擇自己的命運。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n死亡之門\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58903] = {title = "艾澤拉斯防衛者", objective = "與大領主達瑞安‧莫格萊尼交談。然後，使用大領主的死亡之門前往奧格瑪。到了那裡之後就去和克羅米交談。", description = "選得好。\n\n現在正值艱困的時刻。身為少數被選中的人，保護世界之責既是你的負擔，也是你的光榮。這是一份至高無上的榮譽。\n\n但請做好準備，因為你會被無知的人鄙視。凡人往往只看得見我們恐怖的外表，卻看不見我們的內在。不要理會這種蠢蛋，做你該做的事。\n\n去找你的指揮官談話。然後使用他的死亡之門前往生者的領域，並選擇自己的命運。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n死亡之門\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58905] = {title = "找回佩拉苟斯", objective = "在利爪之緣和佩拉苟斯、柳絮和阿蠐會面。", description = "現在佩拉苟斯應該拿到種子了！少了種子，就無法展開儀式。他很可能還在利爪之緣。\n\n我們去那裡集合！", progress = nil, completion = "糟了，搞錯種子了。希望我們能找到善用這些種子的地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58908] = {title = "尋找你的道路", objective = "在舊城區的獸欄和阿捲交談。", description = "暴風城有太多地方值得冒險者去探索，但這座城市大得離譜，無法用走的。船長幫你安排了坐騎，可以協助你四處移動。\n\n她說到舊城區的獸欄和阿捲談談…但我不太記得路該怎麼走。\n\n不用擔心，<name>！我們只要向守衛問路就好了。如果你需要找什麼東西，城市的守衛都會跟你報路。\n\n讓我們問問附近的守衛，怎麼去舊城區找獸欄管理員吧！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n黑馬韁繩金色獅鷲獸\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58909] = {title = "騎乘執照", objective = "和達蓮恩‧斯托克斯交談，學習初級騎術。", description = "船長說你會來這裡挑選坐騎，這裡應該沒有太難找吧！\n\n在你出發在夕陽下奔馳之前，你得學會如何…騎牠。幸好我們這裡就有騎術訓練師！\n\n想學習怎麼騎乘的時候，就去跟達蓮恩‧斯托克斯說吧。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n黑馬韁繩未塗色機械陸行鳥\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58910] = {title = "你的專精是？", objective = "和密洛斯‧隼荊交談以了解戰鬥專精。", description = "嘿，<name>！你決定好戰鬥專精了嗎？\n\n即然你是<class>，你已經瞭解冒險者之間的職業差異。但你是否知道，每一個職業還分專精領域？\n\n選擇專精是十分重要的決定。你的專精會決定你在隊伍中的戰鬥角色，還包括武器種類，以及你會使用的技能。\n\n讓我們去和密洛斯‧隼荊交談，進一步了解你的專精！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58911] = {title = "爐石所在為家園", objective = "和梅根‧提爾曼交談，將豬和哨聲旅店設為你的家。", description = "不知道你有沒有同感，但是到處跑來跑去讓我口渴得很！\n\n我們到豬和哨聲旅店休息一下，喝杯冰涼的月莓汁，你覺得如何？\n\n在那邊的時候，可以跟旅店老闆梅根交談，把豬和哨聲旅店設為你的新家。如此一來，如果你發現你被困在某處，附近找不到飛行管理員，你就可以用你的爐石回到旅店。\n\n這不但比騎乘獅鷲獸來得快，而且你還可以省點荷包！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58912] = {title = "緊急會議", objective = "在暴風要塞和蓋瑞克船長交談。", description = "我們在暴風城四處找你，<name>。\n\n船長已經完成向國王匯報了。看來暴風城馬上就需要你出力。\n\n聯盟的所有領袖都集結在暴風要塞開會，烏瑞恩國王親自指名要你出席。我受命前來，以最快速度送達這個消息。\n\n能與你並肩作戰是我的榮幸，<name>。願聖光保佑你旅程平安。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58914] = {title = "戰士末路", objective = "和暗槌大橋的奇怪鬼魂交談。", description = "嘿，<name>！你是個<class>，對吧？或許你能應付這個…不尋常的情勢。\n\n我用林迪的裝置偵察這個地區時，看到一個鬼魂願意為任何「貨真價實」的戰士提供力量。\n\n我知道你還是個新人，但去那邊試試看如何？\n\n我們需要所有力量來對付這些巨魔。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n斬殺\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58915] = {title = "耶爾瑪的最終處決", objective = "殺死『不死』耶爾瑪。你一定要使用斬殺，才能真的殺死他。", description = "你現在獲得我最強大的本領了，年輕的戰士。\n\n用它來了斷我吧！很久以前，我大著膽子違抗巨魔，他們就把我的靈魂困在此地。\n\n只有榮耀之死，才能讓我真心安息。\n\n這是我在來生與兄弟姐妹再度重聚的唯一方式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58916] = {title = "驚恐的準備", objective = "讓馴犬者洛克希做好準備，以便進行恐懼林地的悔罪之狩。", description = "戴納瑟斯王要我幫你為狩獵做好準備。每一位獵人一定到恐懼林地，協助一個靈魂做好準備。\n\n我這邊有一個頑強靈魂，一直都拒絕合作，那就是馴犬者洛克希。該來狩獵他了。\n\n<懼獵者把一套希望破滅者靈魂鎖鍊交到你手中。>\n\n挫挫他的銳氣。我們不能讓他抱著任何希望離開此地。狩獵的用意就是要將對方徹底擊潰，這樣對方在瑞文崔斯的處理過程中…比較不會那麼抗拒。", progress = nil, completion = "這個靈魂快準備好了。\n\n我們有機會完成這次準備工作，並且在過程中解決一個問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58917] = {title = "盜賊末路", objective = "運用潛行靜悄悄移動，並找出第一支遠征隊的盜賊。", description = "失散的遠征隊裡有個叫庫斯頓‧內瑞思的盜賊。他們著陸後，他出發偵察島嶼，確認可能的威脅。\n\n亨利最後看見他的時候，他正前往北方一座洞穴，離此不遠。\n\n你能不能和庫斯頓連繫？他可能有辦法協助我們執行拯救行動。\n\n噢，還有，往北走要小心點。艾拉莉雅發現好幾頭兇惡的熊在那個地區遊盪。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n毒藥\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58918] = {title = "胡威拉斯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58923] = {title = "聖騎士的效忠", objective = "與聖騎士鬼魂交談。", description = "我在使用林迪的斥候機器人時，好像發現了奇怪的東西，你應該去查看一下。\n\n有個聖騎士鬼魂出現在附近的山丘上，她盯著斥候機器人，並示意要你過去。\n\n我不是很了解聖光和聖騎士，但如果我是你，我會去查個明白。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n學習聖盾術\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58931] = {title = "審判官史黛拉的罪孽石", objective = "收集誓復者墓穴鑰匙並開啟墓穴，直到你找到審判官史黛拉的罪孽石。", description = "想要徹底逃離過去是不可能的，淵喉行者。\n\n每一位汎希爾都是以靈魂形態進入瑞文崔斯，身上背負著肉體凡胎的不義之舉。\n\n就像所有靈魂一樣，他們將真名和最羞恥的罪過刻在罪孽石上。\n\n只要使用方式正確，就算是最熟悉的知識也有可能化為潛在的武器。\n\n找到那些協助控罪者的審判官罪孽石，你才有可能殺死他們。從史黛拉著手。\n\n在他們死亡之後，把控罪者的罪孽石帶來給我。我會親自對付她。", progress = "為了自保，審判官將他們的罪孽石藏了起來。", completion = "很好。特梅爾肯定知道如何利用這枚罪孽石。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58932] = {title = "罪孽使者特梅爾", objective = "擊敗墓穴守衛者凱希爾以獲得特梅爾的服從。", description = "<在飛開之前，艾可隆大吼著下達更多命令。>\n\n還要徵用特梅爾。他知道怎麼樣使用這枚罪孽石。", progress = nil, completion = "&lt;艾可薩帶著猜疑的眼神看著特梅爾。&gt;\n\n我從來就沒喜歡過這個小東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58933] = {title = "最致命的毒藥", objective = "殺死『硬漢』嘎葛魯克。", description = "現在該用你取得的毒藥來解決那隻巨魔了。那傢伙的名字叫『硬漢』嘎葛魯克。\n\n他通常在會在他們的城塞附近巡邏。此刻它可能正在尋找你的遠征隊！\n\n將你的刀刃淬毒，然後解決這隻怪物。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58936] = {title = "野獸控制", objective = "在恐懼林地殺死6頭懼蝠。", description = "由於靈魄乾旱導致靈魄嚴重不足，恐懼林地的懼蝠變得很有攻擊性。\n\n現在已經正式要求削減它們的數量。我們必須將我們的造物重新納入掌控。\n\n - 獸群大師塞吉歐", progress = nil, completion = "回復平衡了，請代表我和這個地方的其他守衛者收下這份酬勞。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58937] = {title = "邪惡版的阿蠐", objective = "用佩拉苟斯的烈焰種子燒掉20隻進化蜱蟲。", description = "喔，不！這個地方到處都是蜱蟲！\n\n就算牠們像阿蠐一樣可愛，還是會長成可怕的果姆！如果我們能清掉一些，希瓦爾就不用花那麼多精神對付牠們。\n\n牠們會鑽地逃跑，所以最好用佩拉苟斯的紅色種子燒掉。反正這樣對其他東西也好。", progress = nil, completion = "牠們想卷土重來，恐怕是難上加難了。", rewards = "無私收集者戰靴無私引渡者護靴無私看守者戰靴無私熔爐士長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][58938] = {title = "破壞一切的果姆", objective = "殺死10隻成年果姆。", description = "這些紅色種子一定有什麼用處。它們來自一種十分危險的植物，而且極不穩定。如果我們打算取得真正想要的藍色種子，這些種子或許幫得上忙。\n\n我們來清除一些果姆並搜尋真正的種子吧。", progress = nil, completion = "這些種子不只很有用，它們也很危險！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58939] = {title = "藍色種子", objective = "找到洞穴入口，穿過礙事的刺藤，取得成熟的靈魄種子。", description = "紅色葉片的藍色種子我有印象，但是它藏在一整面刺藤後面的洞穴裡。我那時候沒想到，不過，只要利用紅色種子，我們說不定就能順利進去。\n\n真希望我沒把種子搞錯，否則我們也不會身陷這一團大麻煩。不過，或許一切都會否極泰來。我們走吧！", progress = "這真是場很有趣的冒險，你不覺得嗎？", completion = "種子！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58941] = {title = "蝙蝠群首", objective = "到恐懼林地將馴犬者洛克希鉤在樁柱上。然後，弱化暮懼並捕捉她。", description = "對我們而言，懼蝠相當有用，它們跟石源魔一樣是我們製造出來的，不過少了後者的…智慧。只要一點點指示，它們就會把恐懼植入頑強靈魂的內心。\n\n在靈魄乾旱中，我們對它們的支配能力減弱了。有隻叫暮懼的懼蝠製造出許多麻煩。\n\n這為我們提供了一個大好機會。帶著這個靈魂把她引進來。在她虛弱的時候，我們就可以把她抓起來為己用。", progress = nil, completion = "在抓住暮懼後，我們對這些地區多了一點控制權。", rewards = "懼翼罩氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][58946] = {title = "聖盾術", objective = "使用聖盾術穿過死靈屏障並摧毀死靈祭壇。如果你需要縮短聖盾術的冷卻時間，可以和尤菈交談。", description = "這座島受到死靈魔法的詛咒。聖光勉強才能接觸到這裡。\n\n號召你的聖盾術，就能不受傷地穿過我們面前的屏障，並摧毀這座邪惡的祭壇。\n\n讓這座島上的黑暗勢力知道你受到聖光保護。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58947] = {title = "考驗你的毅力", objective = "評估者馬勒斯和測試者夏哈利。", description = "在苦痛劇場中奮戰獲得名聲，讓許多人成為瑪卓薩斯的偉大傳奇。\n\n如果要跟隨他們的腳步，你必須證明自己有能耐在那裡存活下來。\n\n在戰鬥中擊敗評估者馬勒斯和測試者夏哈利。我們來看看你有多少能耐！", progress = nil, completion = "你證明了你的能耐！我看看能不能馬上派你參加戰鬥！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58948] = {title = "桌上美食", objective = "收集4份兔肉。", description = "今晚我打算做燉肉當晚餐，不過我們似乎沒有兔肉了。\n\n你能再出去一趟，幫我抓幾隻兔子嗎？\n\n喔，記得小心一點，我不久前才聽到狼嚎，狼群通常不會在白天出沒。", progress = "小聲一點，關朵琳。沒事的，我的小寶貝。", completion = "這樣應該夠了。謝謝你，親愛的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58949] = {title = "米莉的花園", objective = "使用你的鏟子開墾3處未開墾的荒土。", description = "愛爾瑪剛剛來過，給了米莉一些鮮花種子，讓她種在外面的花園。\n\n很高興看到我們的女兒對園藝有興趣，不過要是她又讓洋裝沾滿泥巴，我可沒有時間幫她洗！\n\n你可以幫她挖土嗎？別讓她弄到滿身是泥。", progress = nil, completion = "你真是天底下最好的爸爸！\n\n&lt;米莉用力抱住你的腳。&gt;\n\n你看，我幫你做了檸檬水。我只做了一杯的量，別喝太快喔！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58950] = {title = "湖畔鎮的木材", objective = "將一捆木材送到湖畔鎮的城鎮大廳，交給所羅門鎮長。", description = "所羅門鎮長需要一捆升火用的木柴。不過，他太忙了，沒時間過來拿。\n\n你不介意的話，可以幫忙把木柴送到城鎮大廳給他嗎？相信他一定會很感激的。", progress = "大家都有點緊張，班恩。我的工作就是讓他們保持冷靜。", completion = "謝謝你把木材送來。我本來打算自己去拿，不過鎮民一整天都在亂傳假消息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58951] = {title = "湖畔鎮的背水一戰", objective = "對抗入侵的天譴軍團。", description = "要是天譴軍真的來了…根本沒時間撤離！\n\n用木板擋住窗戶！叫大家都躲在家裡！只有躲起來才有一線生機。", progress = nil, completion = "這個可憐的靈魂。\n\n一個正直的人…卻死得這麼慘…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58952] = {title = "淨化烈焰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58953] = {title = "牧師末路", objective = "找到第一支遠征隊的新兵屍體。", description = "你是受過訓練的牧師，對嗎，<name>？有件事可能很適合你。\n\n我們找到了幾具遠征隊其他新兵的屍體。\n\n我猜他們被沖散到島上的各個角落，他們沒能撐過來。\n\n等你有空的時候，可以去為他們祈禱嗎？好讓他們的靈魂得以安息。\n\n我們解決那些巨魔後會好好安葬他們。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n學習復活術\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58960] = {title = "復活新兵", objective = "復活遠征隊新兵。", description = "這些新兵的靈魂不夠強大，無法抵抗這座島上的黑暗法術。\n\n對這些新兵的遺骸使用復活術。趁他們靈魂還沒離去，懇求聖光再給他們一次機會。\n\n我被困在這座島上好幾年了，看這些巨魔隨心所欲、橫行霸道。\n\n該阻止他們了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58961] = {title = "被伏擊的拓荒者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58962] = {title = "術士的交易", objective = "調查第一支遠征隊的術士屍體。", description = "當你在掃盪不死大軍時，我用林迪的裝置偵察了更多區域。\n\n我看到橋附近有個看起來像傳送門的東西，旁邊有個術士的屍體，我們以為他在船難之後就失蹤了。\n\n你能不能去調查那個區域，試著關閉那道傳送門？我們在這座島上遇到的問題已經夠多了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n學會召喚虛無行者\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58974] = {title = "被伏擊的拓荒者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58975] = {title = "清除害蟲", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58976] = {title = "追查記憶", objective = "前往追憶中樞。", description = "攻擊純潔神殿這種事，在昇靈堡簡直聞所未聞。至少，在我所知的範圍內。\n\n我們必須進一步瞭解。神聖楷模獲得的那塊碎片可能有我們想知道的答案。\n\n這附近有個稱為追憶中樞的地方，在那裡，志士和晉升者可以召出他們的記憶，並且儲存起來。如果我們能夠調查這塊碎片的記憶，或許就能進一步瞭解這些所謂的棄誓者，幸運的話，說不定還能揭露他們的計畫。\n\n我會去那裡等你，莫忘職責。再會。", progress = nil, completion = "&lt;米卡尼寇斯暴躁地指了指他背後的棄誓者。&gt;\n\n你是來這裡幫忙解決這個的？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58977] = {title = "記憶裡有什麼？", objective = "從萊索妮雅的碎片收集棄誓者的記憶。", description = "或許可以從這塊碎片抽取記憶，但它們不一定有用。這不完全是琪瑞安的記憶，只有一小塊是而已！真是個奇怪的破碎記憶。它甚至發不出聲！\n\n我們用抽取器看看能發現什麼。抽取器有可能會爆炸，也可能不會。但要為了這個？這種風險完全值得，我認為啦。\n\n不太確定到底會冒出什麼。可能會是回憶。可能什麼都沒有。可能會是想不到的東西，然後想和你打一架！所以，提高警覺好嗎？在所有看起來像那樣的棄誓者身上收集。\n\n準備好就說一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58978] = {title = "萊索妮雅的真相", objective = "站在靈魂之鏡前，見證萊索妮雅過去的記憶。", description = "要不是親眼所見，我不知道自己會不會相信這種事居然會發生。\n\n你現在體內有著萊索妮雅的一部分，前往靈魂之鏡，敞開你的心房。幸運的話，它們會抽取她的精華，展現棄誓者的記憶。\n\n一旦成功，我們或許就能馬上知道他們在計劃些什麼！", progress = nil, completion = "&lt;米卡尼寇斯暗自生氣。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58979] = {title = "我是你的製造者！", objective = "協助米卡尼寇斯重置中樞管理者助憶士。", description = "我徹底受夠了它的無禮態度。\n\n我知道如何重置這個助憶士的人格，不過你必須持續吸引它的注意。\n\n它可能會無所不用其極地攻擊你，建議你試著活下來。克蕾雅的戰力了得，要是撐不住的話，就躲在她身後。\n\n快上啊！", progress = nil, completion = "希望你原諒我的冒犯，我平常不是這樣的。", rewards = "審判志士頭盔純潔志士兜帽謙恭志士頭盔英勇志士頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][58980] = {title = "助憶士，聽候你的差遣", objective = "在回憶步道內找到兩個供品，然後前往御靈者寶庫。", description = "你好，我是中樞管理者助憶士，很高興能幫助你。\n\n我記得你打算存取特定記憶。基於其內容，那段記憶只能在御靈者寶庫檢視。\n\n為了進入寶庫，你必須為看守寶庫的兩名守護者收集供品。我將這些供品藏在棄誓者找不到的地方，因為他們並未獲得授權，不能進入。\n\n首席熔爐士正好是目前唯一能提供授權的人，省了不少麻煩！", progress = "你找到我所說的祭品了嗎？", completion = "你的搜尋成果非常豐碩，很高興看到你安然歸來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58981] = {title = "硬化的蟲巢", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58983] = {title = "決戰艾澤拉斯：戰爭浪潮", objective = "在暴風要塞參加戰事會議。", description = "烏瑞恩國王召集我們舉行一場緊急戰時會議。\n\n我們不在的時候，聯盟和部落之間出了一些問題。你在放逐之境任務中的英勇表現，讓國王印象深刻。\n\n即然你到了，會議就可以馬上開始。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n聯盟兵籍牌部落的戰爭頸鍊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58989] = {title = "符文鑄造的基本知識", objective = "用你的符文鑄造技能來為你的武器刻上符文。\n\n只要有符文熔爐，你可以隨時自由替換刻在武器上的符文。", description = "身為黯刃騎士團的騎士，我們必須隨時準備好面對各種的戰鬥情境。因此，你將會獲得符文鑄造的黑暗力量，把威力強大的符文刻縛到你的武器。\n\n在我們上方的亞榭洛之心有幾座符文熔爐。去嘗試使用你的力量，為武器灌注符文之力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58990] = {title = "巨蟲卵", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58991] = {title = "古怪的腐化", objective = "到心之室尋找關於腐化物品的解答。", description = "<這個物品似乎有著極不尋常的特質。也許心之室裡會有人知道它的來源。>", progress = nil, completion = "泰坦淨化系統，可供使用。", rewards = "您會學到：\n\n泰坦淨化程序\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][58992] = {title = "超級派", objective = "收集4個瑪卓薩斯骨髓。", description = "我想要煮一些溫潤、美味而且黏黏的食物！\n\n沒錯！我想要做一盤美味的骨髓派！完成以後，我保證你一定會把自己撐得像個吸飽血的璧蝨一樣！\n\n但這次不是隨便什麼骨髓都能用。我需要品質最優良且最稀少的骨髓。\n\n而這就是你能幫忙的地方！我需要你幫忙媽媽去挖一些骨髓回來。沒錯…用挖的。\n\n噢，還要做好起衝突的準備。瑪卓薩斯可不喜歡被人隨意翻攪。您會收到：\n\n\n\n任意等級", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n任意等級托馬林的調味水晶優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][58993] = {title = "敵群防禦", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][58995] = {title = "我夢到一場夢", objective = "見證儀式。", description = "這是一場盛會，大家都到這裡了。為了重建晉升紋章，以及昇靈堡的存亡，這場儀式至關重要。\n\n我們欠了凜冬女王和柳絮一大筆恩情。我希望總有一天能夠報答他們。", progress = "你拿到容器了？", completion = "她…她走了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58996] = {title = "艾柏的下落", objective = "調查靈魂看守者艾柏的下落。", description = "淵喉行者，我還有一個任務要給你。\n\n不久前，我派了靈魂看守者艾柏等人去殺死一些煩人的撕骨者。\n\n他們到現在還沒有消息。可以請你去找他們嗎？", progress = "艾柏怎麼了？", completion = "他們被擊敗了？但你卻安然歸來。\n\n真丟臉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][58997] = {title = "苦中帶甜的獎勵", objective = "將亞登曠野容器送到昇靈堡的樂土堡，交給軍政官阿德雷特斯。", description = "我…我不知道該說什麼。\n\n現在只剩下把阿柳…把容器…送回昇靈堡給軍政官阿德雷特斯。這樣的犧牲絕對不能白費。", progress = nil, completion = "你把用來完成晉升紋章的容器帶來了。我知道你們為了它付出很大的代價。\n\n總有一天，我們一定要努力回報亞登曠野的朋友。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59000] = {title = "腐化的面相", objective = "與母親大人交談以了解腐化物品的用途。", description = "腐化有多種不同的神秘特質。它散播的範圍不限艾澤拉斯本身，它還會染指我們最隱密的思緒，有時候就連各種聖物也會遭到腐化，就如你所見的那樣。\n\n雖然我無法直接確認這些效果，但我相信母親大人應該會擁有這些「腐化物品」的相關資訊。", progress = nil, completion = "啟動泰坦淨化系統。", rewards = "您會學到：\n\n泰坦淨化程序\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59002] = {title = "薩滿的職責", objective = "收集4朵灰霧花並在營火上焚燒，才能救出鬼魂之狼的獸群。", description = "你好，年輕人。你的同伴看不到我。只有受過薩滿之道訓練的你，才能見到我。\n\n這座島上的死靈能量困住了我的獸群。我需要你的協助才能讓他們重獲自由。\n\n在這附近的區域收集灰霧花。把它們帶到附近的營火焚燒並深吸一口冒出來的煙。\n\n這樣你就能看見我的獸群，並解開牠們的束縛了。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n鬼魂之狼\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59003] = {title = "可燃燒的繭", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59004] = {title = "潑灑傷害", objective = "從符文淬鍊敵方部隊身上收集50個經過靈魄充能的符文。", description = "閻獄之主的部隊會使用經過靈魄充能的符文強化自身的護甲，只要沒有了那些符文，敵方部隊就會變得不堪一擊！\n\n我研發出特殊的配方，能夠去除衣服上難纏的污漬，但這種配方應該也能夠去除魔法符文！\n\n把我的腐蝕藥水潑灑在符文淬鍊的敵方部隊身上，潑得越多越好！然後再接著收集掉在地上的符文，這樣我就可以萃取出敵人的靈魄。", progress = "你把符文都清理乾淨了嗎？", completion = "淵喉行者，勝利會是屬於我們的！", rewards = "您會收到：\n\n血煉勳章血煉披氅腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼鋼核盔帽血絲手套鋼核束腰血絲之索肉鱗腰帶屍皮腰帶血煉骨鋸\n                            顯示 16 更多                        血煉之弩血煉短劍永恆之霜致命連鎖堅定防衛者煉獄烙印致命合擊多層毛皮花開花落瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐不死軍團"}
MultiLanguageQuestData['tw'][59007] = {title = "靈魂井", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59008] = {title = "木魈的圈套", objective = "釋放西利克並拯救8個俘虜。", description = "幸虧你和可達林剛好經過！這些木魈全瘋了！\n\n救我出去！\n\n他們捉住我的時候，我正在花園採草藥。我敢打賭，他們也一定抓了其他靈魂！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59009] = {title = "她的應屬之地", objective = "帶著符文刃回到統御者之座。", description = "摩爾拜坦走到了盡頭…而且是個痛苦的盡頭。\n\n能成功走到這一步，你的堅定協助功不可沒。我願意效忠於你…不過只是暫時的。\n\n如果你真的想掌控這個國度，還有很多事要做。\n\n我們到統御者之座會合吧。", progress = nil, completion = "能有盟友真好，就算頑固至極也無所謂。", rewards = "冷酷處刑者戰靴屍體縫補師足靴血肉建構者護足欺詐密探長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][59011] = {title = "死後才是真正的考驗", objective = "質問維拉斯，查明藩侯克利瑟斯之死。", description = "把我困在淵喉裡的人就是維拉斯。他很早就開始和祭儀家族，以及傀儡家族聯手。\n\n顯然他也打算把你困在那個可怕的地方。\n\n現在該讓他因為背叛，付出應得的代價了。和我合作，一起對抗他。", progress = nil, completion = "我們的防線岌岌可危。我們必須快點行動。", rewards = "戰爭學者骨鋸再活化處刑者粉碎錘抓握巨杖屈骨者戰刃巨大顎骨弩戰爭學者魔杖再活化處刑者巨劍冷酷處刑者壁壘戰爭學者寶典屈骨者長刀再活化處刑者之劍戰爭學者護杖再活化處刑者小刀戰爭學者短劍您會收到：\n\n"}
MultiLanguageQuestData['tw'][59014] = {title = "山丘之王", objective = "帶馴犬者洛克希到殘墓山丘找懼獵者。", description = "洛克希準備好了，狩獵的時刻終於到了。\n\n帶著他前往殘墓，懼獵者和其他獵人已經在那邊等候了。\n\n動作快，她不喜歡乾等。", progress = "靈魂在哪裡？", completion = "我們可以開始了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59015] = {title = "充滿敵意的回憶", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59016] = {title = "戰鬥的號角：奧丹姆", objective = "殺死奧丹姆的聯盟玩家。", description = "我們在奧丹姆的計畫，受到湧入的聯盟敗類破壞。\n\n盡可能地殺光他們，然後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][59017] = {title = "戰鬥的號角：恆春谷", objective = "殺掉恆春谷的聯盟玩家。", description = "我們在恆春谷的計畫，受到湧入的聯盟敗類破壞。\n\n盡可能地殺光他們，然後向我回報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][59018] = {title = "戰鬥的號角：恆春谷", objective = "殺掉恆春谷的部落。", description = "我們在恆春谷的任務正受到部落入侵的影響。\n\n進入恆春谷，能殺多少就殺多少吧。", progress = nil, completion = "做得好，&lt;class&gt;。", rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][59019] = {title = "戰鬥的號角：奧丹姆", objective = "殺掉奧丹姆的部落。", description = "我們在奧丹姆的任務正受到部落入侵的影響。\n\n進入奧丹姆，能殺多少就殺多少吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n志士的裝備箱戰鬥的號角勛章征服點數"}
MultiLanguageQuestData['tw'][59020] = {title = "科爾蘇加德的第三次覆滅", objective = "替瑪卓薩斯解決科爾蘇加德。", description = "該來消滅瑪卓薩斯的叛徒了。\n\n軍隊已經集合好了，盟友也準備好了，戰爭這部機器開始運轉。\n\n我們千萬不能輸掉這場戰鬥，否則暗影之境就都完了。", progress = nil, completion = "科爾蘇加德逃出了監禁者的掌握，但至少這股邪惡力量已經被逐出了瑪卓薩斯。\n\n做得好，&lt;name&gt;。現在我們可以專心重建軍隊，恢復這裡的秩序了。", rewards = "您會收到：\n\n裝甲戰殖牛獸名望名望"}
MultiLanguageQuestData['tw'][59021] = {title = "他們的死亡信使", objective = "命令特梅爾閱讀審判官史黛拉的罪孽石，然後殺死她。", description = "打從瑞文崔斯的黎明開始，特梅爾就負責對所有人宣達靈魂的罪孽。\n\n在此地的每一個靈魂，包括汎希爾在內，都要被迫在這樣的場合中，忍受一次充滿怒火的聲明。\n\n他一定知道如何運用審判官史黛拉的罪孽石，擊破她的防禦。\n\n只要找到審判官之後對他下達命令，然後消滅她就好。", progress = nil, completion = "在審判官死後，控罪者罪孽石上的結界會變弱。\n\n但我們必須在結界全面崩潰之前殺死兩位審判官，然後我們才能取得控罪者的罪孽石。", rewards = "石鑄腿甲痛苦赦免護腿獵魂者護腿夜幕馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][59023] = {title = "審判官的終結", objective = "命令特梅爾閱讀審判官維爾海姆的罪孽石，然後殺死他。", description = "審判官維爾海姆正沾沾自喜地躲在庭院後方，身邊有好幾頭石獸和忠誠的汎希爾。\n\n我們一定要殺死他才能打破控罪者的罪孽石上的結界，如此一來，宮務大臣才能在他的戰鬥中活用它。\n\n特梅爾會再次協助你貫穿審判官的防禦。不要遲疑。", progress = nil, completion = "宮務大臣確認擊殺成功。我們得動作快點。", rewards = "痛苦赦免裹帶石鑄護臂獵魂者護腕夜幕束腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][59025] = {title = "直搗黃龍", objective = "殺死摩爾拜坦。", description = "摩爾拜坦叛變成功，讓他十分自滿。\n\n讓他享受這樣的感覺，畢竟這一切即將結束。我們會利用這個儀式來引誘他…然後為藩侯復仇。\n\n和我並肩作戰，<name>。我們一起拿這個叛徒殺雞儆猴。", progress = nil, completion = "該死的巫妖…希望他的靈魂永不重生。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59042] = {title = "一顆好心", objective = "將一枚心臟放進艾曼妮的傀儡。", description = "儘管大多數人都不相信，但艾曼妮有一顆和善的心。呃…只要你給她的話，她就能有顆心！\n\n除了你之外，我想不到還有誰更適合給艾曼妮一顆心，淵喉行者。或許這可以溫暖她的血，也溫暖對你的態度。你們有可能成為朋友，甚至是靈魂之絆！\n\n挑選一枚心臟，並把它放在艾曼妮的傀儡中。", progress = "希望你可以精挑細選！", completion = "你辦到了，傀儡完成了。屠殺之女又再次活過來了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59043] = {title = "蛋不嫌多", objective = "前往亞登曠野並收集13個準備孵化的果姆卵。", description = "我在這個帳篷底下做出來的美味佳餚，可是好吃到連半神都流淚。我永遠都需要更多烘焙補給品！\n\n仲介者通常會賣給我世界各地的蛋，但這一次或許你可以幫我一個忙。\n\n你知道果姆嗎？亞登曠野原生的大蟲蟲。嗯，如果你可以去找一些果姆卵給我，那我就烤點好東西當做回禮！\n\n媽媽還會派粉團去幫你忙。您會收到：\n\n\n\n任意等級", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n任意等級托馬林的調味水晶優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][59063] = {title = "詛咒！", objective = "從腐棘木魈身上取得5片碎掉的卷軸，並從大型妖術元素身上取得破爛的捆繩，組合成封住的魂腐卷軸。", description = "喔，天啊，太可怕了！真的很可怕！\n\n我知道正在折磨那個可憐靈魂的可怕詛咒是什麼！不過，那些該死的木魈不停跑來偷我的卷軸，然後不是把卷軸到處亂丟，就是把它們撕爛！\n\n瀑布周圍現在設下了各式各樣的危險魔法！\n\n木魈身上有你需要的卷軸碎片。集齊碎片，加上大型妖術元素身上取得捆繩，就能得到你需要的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59068] = {title = "從來沒有揭曉的秘密", objective = "從看守者鐘花的紀錄中取得從來沒有揭曉的秘密。", description = "卷軸上列的第一個素材是從來沒有揭曉的秘密。\n\n這還蠻簡單的，我認識一個有超多秘密的人。看守者鐘花，是我們這裡的秘探。森林裡有任何壞勾當，都是她第一個通知曠野獵者。\n\n我相信她一定願意說出一個秘密，拯救可達林的靈魂，使他免於在極度痛苦中消散。\n\n我會叫塞爾納斯到她藏秘密的地方等你，讓他不再一直想著發生在他丈夫身上的事。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59069] = {title = "已逝摯愛的遺物", objective = "到暮光高地的朱紅壁壘與雅立史卓莎談話。", description = "我的姐姐，雅立史卓莎，在與死亡之翼的戰爭末期，失去了她的元配，考雷斯塔茲。\n\n在她漫長的生命中，我的姐姐擁有許多配偶，但她最深愛的還是他。我心裡知道，她現在還是愛他。\n\n去朱紅壁壘找雅立史卓莎，跟她要一件象徵過去愛情的信物。那一定能作為反制詛咒的強大素材。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59070] = {title = "獻上靈魄的祭品", objective = "到特那希殺死木魈，收集惡作劇調和的靈魄。", description = "最後，我們的反制法術需要的是同調的靈魄。\n\n我們的靈魄真的所剩無幾。所以這比起平常來說是更大的損失。\n\n想一想阿，這次的狀況是木魈害的，就該讓他們幫忙解決。有些非常可惡的木魈，在特那希為非作歹。他們手上的靈魄應該夠我們用。\n\n塞爾納斯似乎也對於整治那些木魈感到躍躍欲試。我會派他去那裡跟你會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59071] = {title = "治療詛咒", objective = "施展反制詛咒。", description = "我們已經集齊反制詛咒的所有材料\n\n快點施法，不然我們會失去可達林的靈魂，塞爾納斯就會拒絕幫你，然後泰蘭妲就會慘死在淵喉中，然後大家都會非常難過！\n\n不過別太有壓力。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n妖精編織樹枝\n\n您還會收到：\n\n駿馬靈魂名望名望"}
MultiLanguageQuestData['tw'][59087] = {title = "那該死的狐狸！", objective = "尋找並捉住小靈狐雷尼。", description = "你！就是你！\n\n我，克萊利恩‧頌，需要你的協助。好，好，給你一點時間沉湎在我的榮光之中。\n\n<克萊利恩‧頌等了你一陣子。>\n\n好了嗎？很好。我需要你去抓一頭小靈狐。他真的有夠粗野。瘋狂亂跑、到處惹事，毀掉了我那美麗的休息處！他用了某種隱蔽符咒隱去身影，但我知道一定是他！\n\n幫個忙，抓住那小傢伙！", progress = nil, completion = "你，你真的抓到了那頭小雜種？\n\n很好！這真是令人愉悅的驚喜。現在把他交出來。我們要直接去找他的父親。對於備受尊敬的狐王雷納德，我得好好跟他抱怨一下。就算他是宮廷的成員，也不該放任這個骯髒的小傢伙整天來騷擾像我這麼尊貴的人！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59120] = {title = "靈狐雷尼", objective = "<那頭小靈狐開心地跳了過來，帶著頑皮的表情朝你飛奔而來。\n\n看來，你似乎很有趣。有趣到凜冬之廷的狐王雷納德之子，決定好好黏著你。\n\n這怎麼可能是壞事？>您會收到：\n\n", description = "<那頭小靈狐開心地跳了過來，帶著頑皮的表情朝你飛奔而來。\n\n看來，你似乎很有趣。有趣到凜冬之廷的狐王雷納德之子，決定好好黏著你。\n\n這怎麼可能是壞事？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n雷尼"}
MultiLanguageQuestData['tw'][59126] = {title = "供應鏈", objective = "固守這個地區，取回阿提克斯的補給品分類帳和10件鑄骨戰甲。", description = "我的朋友！我現在需要你的專業技術。\n\n我們有一支貨車商隊在附近遭受攻擊！商隊載著很重要的補給品…裡面還有我要用來賣的全新貨物！\n\n這件事很重要…不對…是非常重要，我們必須盡可能拿回那些裝備。\n\n所以，你準備好要出發了嗎？我們盡全力去回收吧！", progress = "你找回那些物品了嗎？", completion = "阿提克斯每週會放一個箱子，把多出來的物品放在裡面，需要就拿去用。", rewards = "您會收到：\n\n優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][59130] = {title = "瘟疫家族", objective = "到瘟疫家族領地附近尋找生還者。", description = "瘟疫家族在這場紛爭中是第一個倒下的。我們曾經以為它的滅亡只是一場意外的結果…如果我們能早點知道真相就好了。\n\n不過，他們的知識或許還沒完全失傳。在你抵達之前，我們的斥候回報說他們的亡城附近有一些動靜。\n\n如果還有任何生還者，我們最好讓他們加入我們的軍隊。不過接近時要小心一點：有毒的落塵說不定已經讓他們陷入瘋狂…甚至可能更糟。", progress = nil, completion = "我的學徒！我一直在到處找你！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59147] = {title = "淨化之手", objective = "殺死敵人，淨化純潔神殿。", description = "尼可隆並不孤單。\n\n<伊芮迪雅眼神冷酷地看向整個神殿。>\n\n長久以來，我為所照顧的志士盡心盡力。長久以來，我在神聖楷模的底下看管這座神殿。現在知道這麼多人都已經孤單地墮落，給了我沉重的打擊。\n\n但是這場…肆無忌憚的毀滅！令人無法容忍。\n\n你必須助我一臂之力，<name>。去吧，結束這一切，一切的一切。\n\n我必須負起責任，照顧那些留下來的人。等到道路打通後，我會到橋邊找你。", progress = nil, completion = "有些汙點必須徹底清除。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59171] = {title = "獵殺他們", objective = "收集3枚靈魄充能瑪卓薩岩。", description = "我的任務沒有靈魄補給的話，沒辦法推進。\n\n但幸好附近的死靈法師相當慷慨，幫我收集了一些靈魄，儲存在瑪卓薩岩水晶裡。\n\n你去幫他們解脫水晶的負擔。他們可能會不太情願離開水晶，但我相信你可以…說服他們。", progress = "別讓我失望。", completion = "很好，這些就行了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59172] = {title = "兵者詭道", objective = "準備審問『忠誠者』梅菲里斯。", description = "你證明了自己是個有用的盟友，<name>。\n\n對我們來說，梅菲里斯無庸置疑握有了豐富的資訊。不過祭儀家族不容許背叛，他不會開口的。\n\n但那也沒關係，蛛眼家族有辦法…不透過言語獲取囚犯的資訊。\n\n把充能水晶放在我身邊。它們會讓審問更順利。", progress = nil, completion = "可能對德拉卡來說，忘掉我們的主人也沒關係，但我在算清舊帳之前絕不停手。", rewards = "您能選擇下列奬勵中的一個：\n\n心靈撕裂指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59173] = {title = "Short-Supply Reward", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
