MultiLanguageQuestData['tw'][59175] = {title = "永恆的復仇", objective = "把摩爾拜坦骨匣帶回去給瓦許女士。", description = "<架子上有著數百個各式各樣的其他骨匣。\n\n許多都標有名字，而在這一個上面特別刻上「摩爾拜坦」這個名字。\n\n瓦許女士一定會對這個骨匣感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59179] = {title = "黑夜戰士的女兒", objective = "到奧睿博司內找珊蒂斯‧羽月。", description = "我在夢境中，看到了很多事情。夜精靈在淵喉受盡折磨。一位夜精靈戰士被復仇所吞噬。\n\n還有…亞登曠野的毀滅。\n\n這些幻象一直在變化…一直很模糊。但我認為泰蘭妲‧語風是拯救夜精靈和亞登曠野的關鍵。\n\n泰蘭妲的養女，珊蒂斯‧羽月，也做了類似的夢。\n\n她現在正前往永恆之城。找到她。只有她才能夠觸碰泰蘭妲的內心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59181] = {title = "深入淵喉", objective = "帶珊蒂斯‧羽月前往淵喉。", description = "自從泰蘭妲出發前往寒冰皇冠，我就沒再見到她…但她仍出現在我的夢中。她在夢魘般的地方遊走，渾身充滿黑夜戰士的力量。\n\n任何凡人都不可能一直背負那種力量。我真不敢想像尊師現在所承受的代價。\n\n弗塔根大領主跟我說了淵喉之事。如果你當真面對過那裡的恐怖，我懇請你也指引我通過。\n\n我們必須找到泰蘭妲、說服她放下黑夜戰士的憤怒。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59183] = {title = "漂蕩的傷痛之影", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59184] = {title = "博傑斯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59185] = {title = "糾纏之網", objective = "收集8罐瑪卓薩岩粉塵。", description = "看來我們找到了一個途徑，可以把摩爾拜坦引到我們手中。不過，如果不能困住獵物，蛛網又有什麼意義？\n\n想讓儀式生效，巫妖需要用到魔法導體。他們以磨成粉狀的瑪卓薩岩繪製符文，引導靈魄。\n\n我很確定，摩爾拜坦的死靈法師就把磨碎的瑪卓薩岩放在那個區域。如果我們收集到夠多的份量，就能繪製用來困住目標的束縛符文。\n\n快去快回，$p。", progress = "我還在等。", completion = "他這次逃不了了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59188] = {title = "吹噓的復仇", objective = "從三位建構者身上收集儀式手稿。", description = "原來你是我女爵的同鄉人？肯定是個很特別的地方，才能養育出這麼強大的人民。\n\n此地的死靈法師已經開始準備摩爾拜坦的儀式，我們應該利用他們的進展。\n\n儀式要由三位死靈法師組成。只要能取得他們的手稿，就能加以修改，達到我們的目的。\n\n收集那些手稿…並請盡情品嚐受害者的痛苦。", progress = "我們對你的成功抱著相當高的期望。", completion = "沒錯…要讓他們知道我們有多痛苦。", rewards = "冷酷處刑者頭盔屍體縫補師兜帽血肉建構者罩盔欺詐密探頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][59189] = {title = "救回泰蘭妲‧語風", objective = "進入托迦司，救回泰蘭妲‧語風。", description = "黑夜戰士的力量正在撕裂泰蘭妲。這樣的怒火…正在吞噬她。\n\n<珊蒂斯沉默了一陣子。>\n\n不過，母親說的也沒錯。我們不能丟下人民的靈魂在此受難。\n\n我們要跟隨泰蘭妲進入托迦司。一定要找出拯救卡多雷靈魂的方法。\n\n在過程中，希望我們也能拯救我的尊師。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59190] = {title = "尋找你的印記", objective = "準備儀式。", description = "我知道德拉卡為什麼會派你代表她前來了…你可以完成她辦不到的事。\n\n需要的東西都到齊了，現在，只差拼湊起來。\n\n儀式的步驟很簡單：在方尖碑四周排列我們手中這些破裂的水晶。\n\n接著是符印，「我們的」符印。在方尖碑的底座使用瑪卓薩岩粉末來畫出束縛符紋。\n\n在你完成好之後，回來找我。", progress = nil, completion = "復仇就快成功了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59196] = {title = "莫忘職責", objective = "到英雄之陵與克蕾雅會面。", description = "我們不能再浪費時間了。必須在下一波攻擊開始之前，謁見御靈者！\n\n我們得想個辦法讓你進入樂土堡…而且要快！\n\n有個叫英雄之陵的地方飄在原野上，是昇靈堡志士休息之處。\n\n我們在那裡會合，我有個計畫。", progress = nil, completion = "軍政官？他可是御靈者的副手！\n\n她真的相信我們，我們還有機會！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59197] = {title = "侍者的工作", objective = "使用「召喚侍者」修復祈願信標，然後使用信標召喚軍政官阿德雷特斯。", description = "侍者在很多地方都能派上用場。\n\n他們維持昇靈堡的整潔，修理壞掉的東西，並且永遠陪在你身邊，為你服務。\n\n你新來的侍者助手應該能夠修復信標，然後你就能將軍政官召喚到英雄之陵。", progress = nil, completion = "卡莉賽恩允許你使用信標，代表她願意為你作保。因此，你得到我的注意。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59198] = {title = "乘翼飛翔", objective = "與阿德雷特斯一起飛往樂土堡。", description = "崇敬的御靈者決定允許你覲見，作為賜予你的恩典。\n\n你有責任將你的發現上呈給她，然後遵循她明智的判斷。\n\n覲見的地點是樂土堡，它是晉升之巔重重樓閣的一部分，無數晉升者生活在其中。\n\n我們會帶你前往，因為只有具備飛行能力，才能抵達那裡。", progress = nil, completion = "御靈者的謁見廳就在上面。在她面前，我強烈建議你要謹言慎行，畢恭畢敬。", rewards = "天織披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][59199] = {title = "『首生者』基瑞絲緹雅", objective = "與阿德雷特斯交談，謁見御靈者。", description = "我會護送你前去謁見御靈者。\n\n我懇求你傳達資訊時，最好簡潔明瞭。\n\n明智的御靈者會聆聽你的訊息，並決定最好的處理方式。", progress = nil, completion = "御靈者賜予你恩典，凡人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59200] = {title = "昇靈堡結界", objective = "到樂土堡調查神殿結界。", description = "昇靈堡的每座神殿都受到樂土堡這裡的結界保護。只要結界還在，敵人就無法發動攻擊。\n\n令人擔憂的是，棄誓者居然能夠進攻純潔神殿…\n\n你的命令是前去檢查結界。只要結界沒損壞，昇靈堡就不會陷落。", progress = nil, completion = "棄誓者似乎就在我們之中，就連晉升之巔也有他們的蹤跡。\n\n我們必須盡快派人援助勇氣神殿。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59202] = {title = "天選者之中", objective = "返回天選者家族。", description = "只剩下一個符文…\n\n我們應該回天選者家族像藩侯克利瑟斯回報。他會想知道進度的。", progress = nil, completion = "我會要我的士兵榮耀克利瑟斯，這是他應得的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59203] = {title = "別惹我", objective = "從競技場觀眾身上收集6個靈魄瓶。", description = "我在這裡管著數不清的事，包賭盤、改善表現的東西…只要顧客願意付帳的，我都幹。\n\n不過，有幾個顧客沒有準時付帳。不付帳的客人，就是沒用的客人。\n\n請好好叫他們把欠的東西交出來。要是他們拒絕的話，你應該很清楚該怎麼做。", progress = "只要是我的任何東西，都別想動歪腦筋。我一定會知道。", completion = "很好，你比我一開始想的來得有用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59206] = {title = "統御者之言", objective = "返回奧睿博司。", description = "就算統御者不在，他的智慧依舊相當正確。放在這裡的這個訊息正等待著有資格的人來聽。\n\n<德拉卡看著你。>\n\n你到瑪卓薩斯來是為了搞清楚昇靈堡為什麼會被入侵。現在你知道我們的陣營裡有叛徒，也知道有高貴的靈魂打算讓狀況回歸正途了。\n\n告訴你在奧睿博司的盟友你看見了什麼。確保永恆者收到統御者的警告。\n\n<name>，能再次和你一起作戰，我感到十分光榮。", progress = nil, completion = "我很高興看到你回來，凡人。\n\n我祈禱你能成功阻止昇靈堡和瑪卓薩斯之間的戰爭。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59207] = {title = "無縛知識", objective = "釋放監管者藍諾、圖書管理員伊拉圖思及歷史學家泰蘭娜。", description = "棄誓者正在掠奪卡莉歐普之眠中的古物。更糟的是，他們還抓了很多聖壇學者。\n\n他們恐怕會審問這些志士，試圖取得有關藏在聖壇內室的古物情報。\n\n大多數的學者都跟我一起逃了出來，但藍諾、伊拉圖思和泰蘭娜卻不見蹤影。", progress = nil, completion = "我們已經治療了你釋放的一些琪瑞安。感謝你的協助，&lt;class&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59209] = {title = "反抗軍增援", objective = "招募守衛隊長波羅莫和謀士莎卡。", description = "<德瑞文將軍四下打量。>\n\n我們需要更多增援部隊。\n\n我知道有此地有兩位對瑞文崔斯真正目的忠誠無比的人士。由於他們的忠誠，懼獵者把他們留在此地，就等靈魄乾旱吞噬他們。\n\n他們兩位都有足夠的能力在任務中協助我們。\n\n帶著這根靈魄樁釘，並灌注他們。帶他們來找我，我會解釋目前的情況。", progress = nil, completion = "我們的人數變多了。我們的生存機率不像過去那麼渺茫了。", rewards = "石鑄頭盔痛苦赦免兜帽獵魂者頭盔夜幕兜帽您會收到：\n\n"}
MultiLanguageQuestData['tw'][59210] = {title = "腐化核心", objective = "弄破三個枯竭的靈魄水晶，然後以死去的病態祭儀師為破裂的靈魄水晶充能。", description = "這個巫妖想透過攻擊蛛眼家族獲得好處，但他渴求的力量會讓他殞落。\n\n我們了解他的秘密儀式，就利用這一點把他引誘出祭儀家族。\n\n帶著這些水晶，<name>，用摩爾拜坦死去手下身上的靈魄來充能。\n\n你得讓這些水晶裂開，這樣水晶才不會在摩爾拜坦開始儀式之前就碎掉，而是在儀式快完成的時候才會破碎。\n\n而那就是我們進攻的時刻。", progress = nil, completion = "做得好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59211] = {title = "被遺忘的村莊", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59223] = {title = "難掩本色", objective = "收集瑪利雷斯的藥水所需的懼影花萃取物。", description = "做得非常好，我的學徒！我們的實驗室重新回到軌道了！\n\n現在，還剩下最後一個材料，就能完成我們為藩侯史特拉達瑪製作的藥水。\n\n你必須跑一趟溫室，我在那裡種了一株懼影花，應該可以採收了。\n\n在你跑腿的這段期間，我會準備其他的基材。路上小心，學徒！", progress = "找到了？", completion = "來吧，我的學徒！我們的努力就要開花結果了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59229] = {title = "巨怪追尋者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59230] = {title = "『靈魂剝除者』達塔諾斯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59231] = {title = "深不可測之力", objective = "到統御者之座與瑪利雷斯會面。", description = "原諒我，學徒…我一度覺得有點頭昏眼花！不過你做到了！你成功製作出藥水了！\n\n我真是替你驕傲。我們藩候對你的作品滿意到不行！\n\n要請你幫忙卻又吝於提供協助的話，還算什麼老師？如果你有什麼非完成不可的研究，我必定傾力相助！\n\n那麼，讓我們冒險前往你的實驗室。我會屏息以待，見證你的成就！", progress = nil, completion = "我知道你找到了某種…新盟友。而且又強化了另一個符文。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59232] = {title = "一堂謙遜的課程", objective = "見證控罪者的審判", description = "感謝你的效力，才能罷免控罪者、讓宮務大臣晉升頂替她原本的位置。\n\n控罪者主動發起叛亂，她不配也不適合為收割者廷衛效力。\n\n現在，請你看清楚瑞文崔斯的叛徒有什麼下場。", progress = nil, completion = "我以仁慈和理解出名。\n\n我會給控罪者足夠的機會悔改錯誤，並從中學習。", rewards = "夜幕肩甲石鑄肩甲痛苦赦免披肩獵魂者護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][59233] = {title = "王子的新皇冠", objective = "將收割者之冠帶給罪殞城的雷納瑟王子。", description = "皇冠已經準備好了。我會把它交付給你，帶去給雷納瑟。\n\n動作快，<name>。如果消息傳出去，這股力量一定會引來不速之客。\n\n你可以使用這面鏡子回去。在你抵達之後，我會派其他人毀掉它。\n\n一路平安，淵喉行者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恐懼哨衛烏黑巨靴破魂者烏黑軟靴懼獵者烏黑脛甲烏黑死亡帷罩長靴名望名望"}
