MultiLanguageQuestData['tw'][59242] = {title = "美麗新家園", objective = "帶著珊蒂斯‧羽月和獲救的夜精靈靈魂到亞登曠野的森林之心，去找伊瑟拉。", description = "將母親留下來令我痛苦不已…但我們得把族人的靈魂帶到安全之處。\n\n我聽到奧睿博司的侍者提過一個叫亞登曠野的地方。一個充滿遠古森林，有著大自然靈魂沉睡的地方。\n\n你很熟悉那個地方，對不對？我想要親眼見證這個奇觀。\n\n也許那裡的靈魂知道如何從黑夜戰士之力拯救我的尊師。您會收到：\n\n", progress = nil, completion = nil, rewards = "妖精編織衣飾妖精編織外套橡心外套橡心法衣女王近衛胸鎧符文看守者鍊衫符文看守者法衣您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59246] = {title = "黑夜戰士的女兒", objective = "到奧睿博司內找珊蒂斯‧羽月。", description = "我在夢境中，看到了很多事情。夜精靈在淵喉受盡折磨。一位夜精靈戰士被復仇所吞噬。\n\n還有…亞登曠野的毀滅。\n\n這些幻象一直在變化…一直很模糊。但我認為泰蘭妲‧語風是拯救夜精靈和亞登曠野的關鍵。\n\n泰蘭妲的養女，珊蒂斯‧羽月，也做了類似的夢。\n\n她現在正前往永恆之城。找到她。只有她才能夠觸碰泰蘭妲的內心。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59254] = {title = "強化戰術", objective = "與蓋瑞克船長比劃。", description = "艾拉莉雅說野豬人抓走了遠征隊剩下的人…包括我兒子在內。\n\n看來我們得主動深入野豬人的巢穴。這不是件容易的事。他們比你之前對付的魚人更具侵略性，而且十分聰明。\n\n我得確定派你出去不會害死你。我們來進行最後一場比劃。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59256] = {title = "懼獵者", objective = "與控罪者交談以觸發陷阱，然後殺死懼獵者並取得恐懼勳章。", description = "陷阱已經安置完畢，而且懼獵者就這樣直接踏進去。\n\n和我預期的一樣，她太傲慢了，因此看不清擺在眼前的明顯事物。準備好我之前交給你的瓶子。在接下來的戰鬥中，可能十分有用。\n\n等你準備好之後，我們就可以觸發陷阱。", progress = "一定要擊敗懼獵者。", completion = "這枚勳章可以為我們效力。但我們少了一位夠資格配戴它的人。\n\n我們得尋求更多盟友。", rewards = "石鑄脛甲痛苦赦免輕鞋獵魂者長靴夜幕輕鞋您會收到：\n\n"}
MultiLanguageQuestData['tw'][59258] = {title = "木靈的故鄉", objective = "一路奮戰，前往特那希，並找到犄角獵人。", description = "犄角獵人已經不在這裡了。但是我知道他去了哪裡。\n\n他跟著他的獵物，往西邊的長者之地去了。這片林地最近變得有些危險，我們持續在對抗入侵的吞噬者。\n\n你前往長者之地的道路上，多半也爬滿了吞噬者。我會一路陪你過橋，確保你能找到犄角獵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59259] = {title = "永恆折磨者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59262] = {title = "折斷的羽翼", objective = "將奧瑞拉的翅膀帶給科瓦斯寇。", description = "你要幫我嗎？真的嗎？哇！\n\n看看我，看起來如何？\n\n我有鳥喙、羽毛、鱗片狀的腳爪。就像鳥一樣，對吧？\n\n不過鳥都有翅膀，我卻只有手臂。為什麼我沒有翅膀呢？\n\n我壞掉了，沒辦法飛。\n\n附近的拉里翁飛起來的樣子好優雅。我必須仔細研究她的翅膀！\n\n你要幫我嗎？", progress = "要是可以研究拉里翁的翅膀，我一定能有所發現！", completion = "完美！我會仔細研究的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59263] = {title = "飛羽", objective = "把100個拉里翁飛羽帶去給科瓦斯寇。", description = "現在，來跟我的手臂比較一下…\n\n看吶！拉里翁翅膀的邊緣有好多長羽毛！\n\n我卻一根都沒有。這就是我飛不起來的原因！\n\n嗯，我需要很多飛羽才能有翅膀。\n\n你願意幫忙嗎？", progress = "羽毛…好多羽毛…", completion = "很好，有足夠的羽毛能把我的手臂變成翅膀了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59265] = {title = "窺探之眼", objective = "從阿卡雷克之痕的傀儡身上收集20顆背叛者之眼。", description = "傀儡家族打算利用我們亡城的廢墟。但我們自己也需要亡城的零件。\n\n我們得好好警告那些拾荒者。\n\n解決在廢墟裡的傀儡家族，從頭顱裡挖出他們的眼睛，那是我們的象徵。\n\n他們會因此知道要再次畏懼黑暗。", progress = "你有禮物嗎？", completion = "我在這些眼珠當中看到了懦弱…你做得很好。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59291] = {title = "征服者的獎勵", objective = nil, description = nil, progress = nil, completion = nil, rewards = "凶霸鬥士鎧甲頭盔凶霸鬥士皮甲頭盔凶霸鬥士鎧甲頭罩凶霸鬥士皮甲兜帽凶霸鬥士鎧甲戰盔凶霸鬥士皮甲軟帽凶霸鬥士鎧甲巨盔凶霸鬥士皮甲顱甲您會收到：\n\n軍需官的獎賞"}
MultiLanguageQuestData['tw'][59292] = {title = "征服者的獎勵", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n軍需官的獎賞"}
MultiLanguageQuestData['tw'][59293] = {title = "特殊配方", objective = "幫助氣囊收集毒瘤核。", description = "你可能會覺得這些氣體是天生的，但實際上得要花很多功夫，才能累積這麼多。而這要靠一層完美包覆的毒瘤核塗層才能達成。\n\n我需要你幫我更新塗層。\n\n你只要帶我走近吸液毒瘤，我就會把黏液核從它表皮拔過來。", progress = "你拿到他要的東西了嗎？", completion = "他又發臭了？雖然我們不太高興，但至少他現在高興了。", rewards = "您會收到：\n\n\n\n任意等級縫補先驅者巨盔縫補咒術師風帽優良肢體回收的補給物資\n\n等級 60–70縫補之魂面具縫補策略家面甲"}
MultiLanguageQuestData['tw'][59311] = {title = "如何捕捉爍亮蝶", objective = "到閃亮之池捕捉5隻飢餓的爍亮蝶，然後向科瓦斯寇回報。", description = "很好！既然收集到適合的工具，該去捉爍亮蝶了！\n\n北方水池的靈魄乾旱情形較為嚴重，很多爍亮蝶都飢餓難耐，一定會馬上飛來吸食靈莉花的花蜜。\n\n放置靈莉花，在爍亮蝶吸食花蜜的時候，用纖絲捕捉！然後回來找我。", progress = nil, completion = "&lt;科瓦斯寇興奮不已&gt;\n\n哇！成功了！希望牠們也能讓我飄浮！", rewards = "您會收到：\n\n樂於助人的爍亮蝶"}
MultiLanguageQuestData['tw'][59314] = {title = "罪殞城", objective = "到罪殞城向雷納瑟王子回報。", description = "我知道你是個可靠的人。瑞文崔斯的復興，仰賴於與其他國度恢復正常交流。\n\n一直以來，王子都深信你會同意成為我們的一員。他預期你會到來，事先召集了收割者廷衛。\n\n雷納瑟正在罪殞城等你，他打算在那裡向眾人介紹你。", progress = nil, completion = "我一直對你深信不疑，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59315] = {title = "收割者廷衛", objective = "站在收割者廷衛前，宣誓效忠。", description = "我們之間這樣的合作關係會是瑞文崔斯復興的關鍵。\n\n作為收割者，我們能夠將我們的力量賜予凡人，不過需要先獲得全體的認同才能這麼做。因此，所有收割者都已經聚在一起，等著你的到來。\n\n我們不該讓他們等太久。", progress = nil, completion = "歡迎加入我們這個小團體，&lt;name&gt;。", rewards = "您會學到：\n\n暗影之門\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59316] = {title = "羈絆之力", objective = "完成靈魂之絆儀式。", description = "與其他人建立靈魂之絆，並非不可逆的過程。然而，建立靈魂之絆也絕非易事。\n\n你們將會體驗彼此的過去，你們的希望、恐懼、夢想，甚至回憶本身…前提是還有任何回憶留存的話。你們將會在真正意義上達到魂靈相連的境界。\n\n完成後，你們之間的羈絆將會超越物理空間，你也會徹底變強。不只是武力方面，連精神上也是。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59317] = {title = "強化羈絆", objective = "強化你與娜迪亞的羈絆。", description = "你也感覺到了，對嗎？我們之間的羈絆比我想像的還要深厚。\n\n我聽說羈絆會隨著時間加深，不過我們可以加快這個過程。\n\n罪殞城需要我們的力量。我們或許最好現在就試著加深羈絆。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59319] = {title = "取得進展", objective = "檢查指揮桌，並展開一場冒險。", description = "汎希爾的本職是洗去靈魂自身的傲慢，不過還是有其他事情需要處理。\n\n我們必須採取行動，跨越瑞文崔斯的邊境，讓暗影之境的靈魂都能各安其命。\n\n請容我為你的同伴示範一下，作為日後諸多攻擊行動的嚆矢。", progress = nil, completion = "無庸置疑，這次任務必定會大大成功。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59321] = {title = "神聖誓盟", objective = "到聖所下層的儀式大廳找雷納瑟王子。", description = "我們的誓盟不是只有契約和承諾，我們還有無與倫比的力量。而我們會在神聖的儀式中，將這股力量賜予你。\n\n儀式完成後，你就能輕而易舉地使用我們的賜禮。", progress = nil, completion = "歡迎，我必須承認，我迫不及待想參與這個重要盛事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59322] = {title = "共享靈魂", objective = "到魂絆熔爐找控罪者。收割者的力量流經你的凡軀。不過，只要與其他人建立靈魂之絆，你就能獲得更強大的力量。\n\n已知這麼做不會有任何壞處，而且雙方都能從中獲益良多。\n\n控罪者負責監督整個過程。等你準備好了，就去魂絆熔爐找她。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "收割者的力量流經你的凡軀。不過，只要與其他人建立靈魂之絆，你就能獲得更強大的力量。\n\n已知這麼做不會有任何壞處，而且雙方都能從中獲益良多。\n\n控罪者負責監督整個過程。等你準備好了，就去魂絆熔爐找她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59323] = {title = "靈魄覺醒", objective = "參與收割者的儀式。", description = "這個儀式將會賜予你我們的賜禮。\n\n我們會激發你靈魂中的靈魄，喚醒只有收割者才知道的力量。 \n\n在此之前，從未對凡人進行過這個儀式，不過我已經確認儀式過程非常安全。", progress = nil, completion = "只要契約未破，力量就會常在。", rewards = "您會學到：\n\n靈霧繚繞\n\n下列法術會施放在您身上：\n\n星術師之怒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59325] = {title = "堅定的盟友", objective = "與德瑞文將軍完成靈魂之絆儀式。", description = "我們天生就適合這種工作，淵喉行者，收割者不可能連打都不打，就輕易放棄他們的力量。\n\n你需要可靠的盟友同行，而且他們必須很清楚暗影之境的打鬥方式。\n\n我來當你的嚮導，我們一起見證瑞文崔斯重拾真正的使命。", progress = nil, completion = "我們合作之下更形強大。", rewards = "您會學到：\n\n靈魂之絆：德瑞文將軍\n\n您還會收到：\n\n名望"}
MultiLanguageQuestData['tw'][59327] = {title = "在叛亂的廢墟中", objective = "搜索罪殞城，尋找雷納瑟王子的線索。", description = "好了，我們到罪殞城了。\n\n我上次看到時，主宰正拖著雷納瑟王子和他最忠誠的追隨者上囚車送來這裡。不過，這裡是個禁地，關於它的謠言和謎團不計其數。我聽說它曾是戴納瑟斯的工坊，他在這裡進行不可告人的實驗。\n\n確實讓人很感興趣，不過我們是來找雷納瑟的。搜索下層，不過記得隨時提高警覺。我會派人傳訊給控罪者，請她帶著盟友過來，人手越多越好。", progress = nil, completion = "不怕我把你的頭扭下來，你就…\n\n等等…\n\n你還活著？這意味著你是…淵喉行者？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59339] = {title = "強化戰術", objective = "與蓋瑞克船長比劃。", description = "艾拉莉雅說野豬人抓走了遠征隊剩下的人…包括我兒子在內。\n\n看來我們得主動深入野豬人的巢穴。這不是件容易的事。他們比你之前對付的魚人更具侵略性，而且十分聰明。\n\n我得確定派你出去不會害死你。我們來進行最後一場比劃。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
