MultiLanguageQuestData['tw'][59342] = {title = "馴服野性", objective = "跟奧斯汀‧哈克斯沃學習馴服野獸，然後對附近的野生動物使用馴服野獸技能。", description = "像你這樣的獵人身邊需要一隻厲害的野獸…否則你是對抗不了這些野豬人的。\n\n準備好後，我會教你如何馴服野獸，然後你就可以去找一隻當你的忠誠夥伴。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59343] = {title = "魂靈相連", objective = "完成靈魂之絆儀式。", description = "我終於體認到，我和你註定要成為最親密無間的兩個靈魂。\n\n你默默忍受的樣子總是讓我著迷，我不禁想像，要是沒有你這個有趣的人在身邊，這無聊的來生會多讓人難以忍受。\n\n讓我們建立靈魂之絆，成為永遠心靈相通的同伴吧。", progress = nil, completion = "得知我們的靈魂永遠密不可分後，讓我不禁滿心歡喜。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59344] = {title = "藍納維斯的勳章", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
