MultiLanguageQuestData['tw'][59347] = {title = "武僧的專注", objective = "跟著基拉並和她一塊冥想。", description = "對抗鷹身人時你打得很好，但我們都要變得更加強大，才能面對接下來的問題。\n\n第一步就是找個好地方開始冥想，集中你的思緒。\n\n只有保持專注武僧才會強大。\n\n來吧，我知道有個地方可以去。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n幽冥掌\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59348] = {title = "更多翅膀！", objective = "收集10朵靈莉花。", description = "想到了！或許是我太重了。大概需要更多翅膀吧！\n\n爍亮蝶擁有漂亮的翅膀。如果找來正確的誘餌和堅固的繩索，或許就能抓到它們。\n\n拜託摘幾朵靈莉花來。它的花蜜是爍亮蝶的美食，而且會讓它們昏昏欲睡！", progress = "靈莉花蜜是爍亮蝶最喜歡的睡前點心！", completion = "好美的花，有股奇特的香味，對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59349] = {title = "最後一次比劃", objective = "與基拉比劃。", description = "在我們回營地之前來場快速比劃吧，<name>。\n\n我想看看這座島嶼讓你成長得如何。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59350] = {title = "德魯伊的形態", objective = "和附近的德魯伊之石溝通。", description = "謝謝你救了我，<name>。讓我協助你鑽研德魯伊之道。\n\n我逃離坑洞的時候，化身為一頭鹿。有個辦法你也能辦到。\n\n跟我來。附近有個古老的德魯伊之石，我們跟利用它與荒野溝通。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n旅行形態\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59351] = {title = "絲絲入扣", objective = "收集10縷翼靈蛇纖絲。", description = "爍亮蝶是靈魄所構成的生物，雖然看起來很纖弱，事實上卻相當強韌！\n\n翼靈蛇尾巴射出的纖絲非常堅韌，應該有助於困住爍亮蝶。\n\n幫我收集一下！", progress = "翼靈蛇纖絲幾乎完全以靈魄構成，不會輕易斷裂！", completion = "&lt;科瓦斯寇使出全力拉扯纖絲&gt;\n\n看到了嗎？超級結實！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59352] = {title = "法師的知識", objective = "在附近湖泊的底部找回美芮迪‧漢茲威爾的書。", description = "對一個新手法師來說，你的施法相當俐落。或許有一天，你會和我一樣厲害！\n\n但你居然不知道變形術！怎麼可以不知道？\n\n變形術是法師的一大重要法術。幫我找回法術書，我就可以教你。\n\n我上次看到巨魔把我的書丟進湖裡！\n\n把我的書找回來，我就教你如何施放變形術。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n變形術\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59354] = {title = "綿羊的最佳用途", objective = "與美芮迪和士兵柯爾交戰來練習變形術。", description = "在我示範如何正確施放這個法術之前，我不會隨便讓你離開。\n\n當你同時被兩個敵人攻擊時，就是施放變形術的時機。\n\n我和柯爾會和你進行一場比試，確保你知道該怎麼做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59355] = {title = "獵人的陷阱", objective = "在這個區域回收零件，來製作冰凍陷阱。", description = "現在，大多數的獵人都已經完成了陷阱方面的訓練。讓我帶你趕一下進度。\n\n首先是冰凍陷阱。你必須從周圍環境找到需要的材料。\n\n美芮迪會提供冰微粒。你可以在這個區域尋找其他東西。\n\n別拖太久了。你需要冰凍陷阱才能對付營地中突然出現的問題。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n冰凍陷阱\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59356] = {title = "追捕潛獵者", objective = "在巨魔廢墟使用你的冰凍陷阱，將潛伏在營地裡的野獸引出來。", description = "現在你拿到陷阱了，我們需要處理更大的問題。\n\n有隻野生動物一直覬覦我們的營地。他已經偷走了一些食物。我們自己的庫存已經夠少了。\n\n我們來合作。設下冰凍陷阱，把那個生物引誘出來。\n\n抓到之後，我再看看是要馴服牠…或是直接把牠消滅。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n召喚寵物2\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59426] = {title = "你的個人助理", objective = "選擇服侍你的侍者，然後向卡莉賽恩回報。", description = "在英雄之陵這裡，我們有個訊號裝置，能以最快速度吸引軍政官的注意。\n\n不過我們很久沒用這個裝置了，恐怕它已經壞掉了。\n\n我允許你停留在昇靈堡的這段期間，能有侍者隨侍在側。\n\n我會召幾個侍者過來，你可以從中挑一個來幫你。", progress = nil, completion = "每當你需要協助的時候，你的侍者能為你提供許多服務。", rewards = "您會學到：\n\n召喚侍者\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59427] = {title = "我們需要更多能量", objective = "到隱蔽避難所周圍收集靈魄。", description = "勞倫特的計畫有點太異想天開了。\n\n進行短距離穿梭時，鏡子是最可靠的管道。但是穿越到聖所需要耗費龐大能量，遠超他或我所能負荷的範圍。\n\n隱蔽者在他們的據點藏了很多靈魄，只要有足夠的靈魄，就能讓鏡子穩固下來，送我們去我們想去的地方。", progress = nil, completion = "很好，這些應該夠。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59430] = {title = "家有瘟疫", objective = "與瘟疫家族的倖存者交談。", description = "雖然實質上瘟疫家族已經不復存在，但他們的知識依舊保留下來。在那邊有些倖存者繼續研究並發明恐怖武器。\n\n用不了多久，我們就會復興家族並帶來更強大的力量，對我們的敵人釋放前所未見的瘟疫和創作！\n\n或許你能幫上忙？和倖存者交談，看誰需要你的協助。", progress = nil, completion = "合力工作可以讓我們雙方都大大受益！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59441] = {title = "靈魂鐵匠尤爾瑪塔", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59520] = {title = "瘟疫之臨：涉入其中", objective = "進入瘟疫之臨並取得12份痘皮樣本，還有藩侯史特拉達瑪的原質。", description = "在瘟疫家族的毀滅中有不少人倖存，但卻還是受到爆炸釋放出來的瘟疫感染。藩侯史特拉達瑪自己也被十二種不同的空氣傳播疾病逼瘋！\n\n這些危機依然存在，並從廢墟向外擴散，每天都有新的受害者受到感染。\n\n我需要你進入廢墟，從受害者身上取回樣本。", progress = "你把痘皮樣本帶來了嗎？", completion = "合力工作可以讓我們雙方都大大受益！", rewards = "欺詐密探肩墊冷酷處刑者肩鎧屍體縫補師襯肩血肉建構者肩冑您會收到：\n\n"}
MultiLanguageQuestData['tw'][59554] = {title = "愉快的旅程", objective = "到阿格西雅安息地與管理者助憶士談話。", description = "各位志士前輩和後輩，注意一下！阿格西雅安息地召集各位。\n\n請進行儀祭之旅，認識過去為拯救這個國度而英勇犧牲的神聖楷模！\n\n乘上坐騎，從英雄之陵往西南方馳騁一小段路，就能抵達阿格西雅安息地。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59555] = {title = "兵臨門下", objective = "騎乘怒翼，消滅敵人的部隊。", description = "剩餘的三個家族正聯手對抗我們。如今他們的聯軍正在攻擊統御者之座，我們的防禦沒辦法永遠撐下去。\n\n我已經派出了後備部隊和他們交戰。而我需要你去突破他們的圍攻。\n\n去找黑彌爾和瑪利雷斯，他們會準備好武器讓你打擊我們的敵人。", progress = nil, completion = "敵人正在舔舐他們的傷口！目前我們的部隊會守住防線，但是該為接下來的突襲做好準備。", rewards = "您會收到：\n\n戰殖牛獸"}
MultiLanguageQuestData['tw'][59556] = {title = "歡迎加入我的家族", objective = "與德拉卡女爵交談，在瑪卓薩斯誓盟大廳正式就任死靈領主。", description = "你和其他誓盟之間的連繫，一度讓我懷疑你到底會不會回來。現在看來我還真蠢。\n\n不管是不是外來者，你勇氣十足，和瑪卓薩斯軍隊並肩作戰。我確信統御者一定很榮幸，能讓你成為我們的一份子！\n\n而總有一天，統御者也會回來，而我們不能只是等待。既然統御者不在，就讓我封你為瑪卓薩斯的死靈領主。", progress = nil, completion = "這是我們必須打贏的戰爭，淵喉行者。現在這使命也是你的了。", rewards = "您會學到：\n\n血肉工藝\n\n您還會收到：\n\n"}
