MultiLanguageQuestData['tw'][59603] = {title = "為暗影之境效力", objective = "使用指揮桌派遣瑪利雷斯展開冒險。", description = "身為瑪卓薩斯的一員，我們的責任就是確保暗影之境的安全。\n\n如果有敵人出現，就由我們去面對！\n\n暗影之境的威脅不是我們任何一人可以處理的。而這就是我能幫忙的地方。\n\n我會成為你的戰場之眼。讓我為瑪利雷斯完成一個簡單的工作，你們兩個都能因此獲益。", progress = nil, completion = "如此一來，就像你親自帶領戰鬥一樣！要我說的話，做得好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59607] = {title = "打倒野獸", objective = "非打爛壞蝙蝠不可！需要彈藥！彈藥在掘息坑！", description = nil, progress = "非打爛壞蝙蝠不可！需要彈藥！彈藥在掘息坑！", completion = "哈哈！射擊時間！", rewards = nil}
MultiLanguageQuestData['tw'][59609] = {title = "死亡也無法止息", objective = "向德拉卡女爵回報。", description = "表現非常出色，我的學徒！你完成了訓練，現在是真正的死靈領主了。\n\n這也表示你的責任越來越大。這就是天才必須背負的重擔！\n\n我相信德拉卡女爵有話要對你說。", progress = nil, completion = "希望你都處理好了，在瑪卓薩斯可沒辦法喊累。", rewards = "您會學到：\n\n世界任務\n\n下列法術會施放在您身上：\n\n風之召喚\n\n您還會收到：\n\n刃誓先驅者護脛刃誓之魂馬褲刃誓咒術師護腿刃誓策略家重腿甲名望名望"}
MultiLanguageQuestData['tw'][59615] = {title = "人人都有出頭天", objective = "取得妮娜的傀儡規格。", description = "淵喉行者，當我聽聞你製造傀儡，並且為仍效忠瑪卓薩斯的靈魂建造家園時，我就開始追尋你的蹤跡！\n\n我很忠心，而且一直想要擁有傀儡的形態，但是藩侯不願意製造符合我天性的傀儡。\n\n我的一生都與詛咒糾纏在一起，它是我所知的一切，也是我仍然想要的一切。\n\n你願意為我製造傀儡嗎？", progress = nil, completion = "我認識這個靈魂，她既強大又忠心。製造這個最不尋常的傀儡後，我們將能得到莫大助力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59616] = {title = "單人軍團", objective = "到傀儡家族領地附近找武鬥士梅維斯。", description = "梅維斯會率軍攻擊，但由你來收尾。沒有增援部隊，沒有騎兵。\n\n只靠你和你的符文刃。\n\n讓我看看你揮舞著什麼樣的力量，外來者。圍攻傀儡家族，讓他們化為荒蕪！", progress = nil, completion = "你的聲音…你不是瑪卓薩斯的人？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59617] = {title = "石惡魔破壞者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59621] = {title = "摧毀幾顆卵", objective = "在生命水岸摧毀10個果姆卵。", description = "就像你看到的，我們有果姆的問題。\n\n我不知道牠們為什麼會變得這麼生氣。它們越變越大，敵意越來越強。一定是靈魄乾旱造成的。如果沒有人阻止的話，牠們會吃光一切！\n\n牠們產卵的速度完全失控了。不能再任由牠們大量繁殖下去了。拜託，進入牠們的巢穴，把你所能找到的卵都摧毀吧。", progress = nil, completion = "這樣應該可以抑制住牠們的數量了。感謝你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59622] = {title = "解決護蛋者", objective = "殺死護蛋者堤歐姆、布魯米和厄瑞斯。", description = "那些卵是個問題，但是照顧它們的果姆也很麻煩。\n\n族母不在的時候，負責孵卵的果姆會成為巢穴的首領。如果放任不管，它們就會產下更多的卵，讓我們的努力白費，等於要從頭來過。更可怕的是，其中一隻甚至有可能會變成蟲后。\n\n它們的數量太多、敵意太強烈，我們無法抑制住它們的數量。除了把它們殺掉之外，看來已經別無他法了。", progress = nil, completion = "牠們之後還會生出更多護蛋者的。但你幫我們爭取到了相當寶貴的時間。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59623] = {title = "煩人大東西", objective = "把布斯奇爾的刺針帶去給果姆工匠卡文納。", description = "你意下如何？想要再狩獵一次嗎？\n\n有隻會飛的小害蟲已經茁壯成了會飛的超級大害蟲。要在果姆身上找到又大又純的身體構造著實不容易，但是身為鐵匠，我就是喜歡有挑戰的事。\n\n<卡文納靠向你，聲音放低。>況且，我也很擔心家人和林地裡其他人的安危。\n\n把那個大傢伙的刺針拿來給我，我好好犒賞你一番。\n\n一言為定？", progress = "不得不說，我真的很期待可以好好研究一下這麼棒的樣本。", completion = "嗯，這就是那隻果姆。我會用它來幫你製作特別的東西。", rewards = "庫雷斯樹長弓庫雷斯樹小刀果姆外殼猛擊錘果姆外殼棍棒果姆釘刺者之矛果姆釘刺者之劍果姆釘刺者戰刃庫雷斯樹法錘庫雷斯樹匕首您會收到：\n\n"}
MultiLanguageQuestData['tw'][59625] = {title = "唯一的解藥", objective = "到昇靈堡見勇氣楷模。", description = "瑪卓薩斯正在重歸正道，重拾暗影之境保衛者的職責。不過進攻昇靈堡的背叛行為仍是我們的一個汙點。\n\n我們以為珈爾瑪的部隊繞路了，不過我們收到勇氣楷模的來信，表示增援部隊已經開始抵達她的神殿。\n\n一定要化解這場威脅。\n\n我已經自願擔任這次行動的先鋒。而你的力量會讓我如虎添翼，$p。", progress = nil, completion = "我們知道你會來。我們靜待結果。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59641] = {title = "庫爾提拉斯王國", objective = "在暴風港與珍娜‧普勞德摩爾女士交談。", description = "庫爾提拉斯擁有全艾澤拉斯最強大的海軍勢力，本來是聯盟的成員國。但在珍娜的父親，海軍總帥戴林‧普勞德摩爾在塞拉摩被殺之後，我們就沒有來往了。\n\n很多人說珍娜當時太相信聯盟和部落一定能和平共處，甚至因此背叛了父親。或許她覺得現在總算是放下過去的時候。\n\n我不想讓珍娜冒這個險…但一定要讓庫爾提拉斯加入聯盟。\n\n願聖光與你同在。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59642] = {title = "焦躁不安", objective = "消滅戰略家歐克、投擲者賈拉斯和軍需官維吉克", description = "那些憎惡體的組織精良，而且擁有充分的補給。我們沒有任何進展。\n\n只要稍微打亂他們的補給和增援，就可以為我們製造優勢。\n\n我需要你設法溜到他們的陣線後方，並消滅三頭控制補給的憎惡體。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59643] = {title = "堡壘競速日！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59644] = {title = "聖光炫目", objective = "使用罪殞城上方的鏡子封印納撒亞城的閘門。", description = "$p，一定要阻止戴納瑟斯王。他從暗影之境竊取靈魄的行為，使得將閻獄之主困在淵喉的封印日漸削弱。絕不能讓閻獄之主逃出淵喉。\n\n沒有時間了，我們得快點行動。我要你立刻前往地表，走進該死的聖光中，盡全力找到越多鏡子越好，將它們對準閘門上方的聚焦鏡。\n\n我們要讓納撒亞城籠罩在一片光明之中，讓汎希爾人沒有勇氣走出堡壘挑戰我們。", progress = nil, completion = "那應該能幫我們爭取一點時間，稍微清空前進的道路。現在快點善用這個機會。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59645] = {title = "死亡降臨", objective = "殺死30支敵人部隊。", description = "傀儡家族不斷入侵，玷汙了瑪卓薩斯原本的榮譽。\n\n除非實現正義，否則無法挽回榮譽。希望我們能徹底地擊敗他們，這樣往後才沒人敢做出這種褻瀆的行為。\n\n和我一起消滅這些叛徒，$p，一個也不留。", progress = "淨化他們。", completion = "目的達到了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59648] = {title = "一步步實現和平", objective = "關閉南方的死靈壁壘。", description = "瑪卓薩斯的怪物再次佔領我的神殿。他們用你們的死靈魔法製造出護盾來固守神殿。\n\n我那些還沒有被你的可惡同類抓住或殺死的侍徒說，他們在南方發現了死靈壁壘的核心。在解決護盾之前，我們無法反擊。\n\n辦好這件事，不然我無法繼續忍受你出現在我面前了。", progress = nil, completion = "我們才剛剛開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59650] = {title = "絕不猶豫、永不屈服", objective = "關閉北方壁壘。", description = "我猜不出傀儡家族是從哪裡找援軍的，不過我們再度寡不敵眾。一想到那些逝去的同胞，我就滿腔怒火。\n\n你必須導正這一切。\n\n那群叛徒在神殿的北方區域建立起了據點。他們用死靈魔法製造了一面護盾，用以防範遠程攻擊。去摧毀它。\n\n清掉眼前的所有阻礙。這就是勇氣神殿的做法。", progress = nil, completion = "在這之後，事情將會變得越來越好。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59653] = {title = "勇氣與無謀的界線", objective = "跟珊卓亞一起穿過突破口。", description = "敵人的據點現在毫無防衛能力。我的侍徒會開始著手準備，好掃除你的族人在我們的家園上所留下的腐化。\n\n不過神殿內部的聖所還殘留著許多腐化。他們的防禦導致我們無法一起飛進去，不過我可以自己攻下一個據點。我們要穿過突破口，然後清光它們。", progress = nil, completion = "我只能帶你到這裡，好好把握。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59656] = {title = "把消息告訴女士", objective = "到爍瀑盆地向懸瀑女士回報。", description = "<索洛迪爾發出長嘆，鬆了一口氣。>\n\n不如今天就先這樣吧。多虧有你，水岸大部分區域都安全了。剩下來的清理工作我們自己來就可以了。\n\n懸瀑女士一定想知道你在這裡的成果。去把這個好消息告訴她吧。", progress = nil, completion = "啊，這樣真是太好了。謝謝你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59658] = {title = "誰才是老大", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59659] = {title = "絕對防空", objective = "殺死三個玷汙者。", description = "憑我們琪瑞安族的能耐，早該開始反擊了，可是這些入侵者實在太卑鄙了。\n\n他們的死靈法師汙染了空氣，害得空氣中瀰漫著汙穢的能量，腐蝕我們的翅膀。\n\n必須先消滅他們，我才有辦法進攻。解決那些可惡的傢伙，我會懲罰剩下的人。", progress = nil, completion = "現在我們準備好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59660] = {title = "新的宴會", objective = "招募舉辦餘燼宴會所需的人員。", description = "我親愛的$p，我聽到一個令人開心的傳言，你好像考慮在罪殞城籌辦新的宴會。\n\n如果這是真的，請務必容我向你推薦工作人員，協助你籌辦最完美的宴會。\n\n<希奧塔從口袋中抽出長長的羊皮紙。>\n\n自從我一踏進罪殞城，我就開始針對宴會的每個工作崗位擬定推薦名單。\n\n我不希望你覺得我自吹自擂，不過舉辦宴會的確是我的專業。", progress = nil, completion = "宴會可不會憑空出現。開始工作吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59661] = {title = "餘燼宴會預演", objective = "協助特梅爾舉辦預演性質的餘燼宴會。", description = "聽著，$p。汎希爾族自從誕生以來，不知道辦過多少場華麗的宴會。\n\n想要舉辦讓他們驚豔的宴會並不簡單。\n\n別擔心，我有個計畫。\n\n我已經安排了一場預演性質的宴會，讓我們能事先掌握一些要領。\n\n出席的只有你、我、雷納瑟，還有誓盟中幾個急於助我們成功的社交名流。\n\n放輕鬆，一定會很有趣的！", progress = nil, completion = "宴會辦得非常好，所有事情都考慮到了。我們真的很懂怎麼籌辦宴會。\n\n我們可以開始籌備第一場正式的餘燼宴會了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59674] = {title = "君子之爭", objective = "到煉火哨站找佩羅迪斯，或到內梅雅的居所找內梅雅。", description = "啊，新鮮的靈魂！你的看法或許對我們有用。\n\n內梅雅和我各自持不同的意見。她對昇靈堡的原生生物「拉里翁」讚不絕口，培育並訓練牠們，當作自己的夥伴。\n\n不過，我認為芬連克斯才是更出色的物種。它們能力出眾，服從性高，而且很容易相處。\n\n拜託，請來考察一下我們的看法。也許你能判斷出誰的意見更加優秀。", progress = nil, completion = "你先來我這邊，讓我覺得很榮幸。請容我帶你看看我的夥伴。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59676] = {title = "慾望收割者", objective = "潛入永恆露臺，將雷納瑟王子的訊息交給女伯爵。", description = "那麼，計畫是這樣的：我們在你身上塗滿泥巴，讓你看起來像是僕人。這東西有防盜設計，所以只要衣服認為它們被偷了，就會把你們所有人傳送到這裡。\n\n你「應該」能夠接近女伯爵，把訊息交給她。記得微笑、點頭、聽令行事，別跟任何人說話，也不要跟有翅膀的東西眼神交會，不然你馬上就會被發現是入侵者。", progress = nil, completion = "啊，女伯爵，這場宴會的女主人。永遠都要假設她身邊有人，而且隨時都可能被她背叛。\n\n嗯…背叛…", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59678] = {title = "徒勞無功", objective = "關閉6個死靈傳送門。", description = "這些叛徒詭計多端。他們在這個地方打開了更多傳送門，讓他們可以輕而易舉地補充人力。\n\n儘管神聖楷模強大無比，仍舊無法殲滅源源不絕的大軍。我們來摧毀這些傳送門。只要沒有援軍，他們勢必就會土崩瓦解。", progress = nil, completion = "他們無法再補充人力了。做得好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59680] = {title = "維希芬妮的惡毒禱鐘", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59698] = {title = "從新開始", objective = "與珊卓亞一起飛行，殺死瑪卓薩斯人。", description = "終於，天空再一次屬於我們了…在這片天空裡，我們正在醞釀復仇的風暴。\n\n來吧，自稱瑪卓薩斯防禦者的人啊，你要彌補那些曾被你視為同胞之人犯下的錯誤嗎？\n\n對他們降下正義制裁！絕不留情！", progress = nil, completion = "為了勇氣！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59700] = {title = "最後的勞力", objective = "殺死安朵蕾女爵。", description = "昇靈堡的危難就潛伏在我們腳下。但是如果我們沒有辦法讓這個殘暴的女爵伏法的話，今天就不算獲勝。\n\n她躲在上方的亡城裡，讓這個一度神聖的殿堂籠罩在暗影之中。\n\n我們要做個了斷、一次解決。傷害會隨著時間復原的。", progress = "這就是剩下的一切。", completion = "但願她的記憶會從這個地方消失。", rewards = "刃誓先驅者粉碎手套刃誓之魂扼殺手套刃誓咒術師手套刃誓策略家護手您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59701] = {title = "共同立場", objective = "將四面雷納瑟王子的旌旗插在暗牆哨塔。", description = "現在我們有了一座可以運作的城塞，我們得展開計畫的下一個階段，才能把瑞文崔斯的控制權從主宰手中搶過來。\n\n我們一定要說服收割者廷衛聚集在一起參加會議。不過，不是在這裡，那跟自殺沒兩樣。\n\n去暗牆哨塔，那是我的舊堡壘，然後把這些旗幟插在塔上四個最偏遠的地方。這樣可以確保收割者的力量與主宰無法干預一場中立會議。", progress = nil, completion = "雖然看起來像普通旗幟，不過只要以正確咒語搭配幾個合適法術，就可以暫時將此地化為一個庇護所。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59703] = {title = "轟炸憎惡體", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59705] = {title = "記得的事", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59706] = {title = "給女伯爵的邀請函", objective = "到通往永恆露臺的誘惑之橋上找棍臉。", description = "女伯爵，慾望收割者。\n\n她的鋒芒比多數寶劍都要銳利。儘管我從沒看過她拿起武器，但你必須知道她絕不會毫無防備。\n\n她的宅邸格局與我的大同小異，就位在納撒亞城的東北側。她的管轄區域是城堡區，專門負責確保貴族照規矩行事。\n\n她一定很樂意知道一些不為人知的消息。我會先派泥掘者過去，準備混進她的宴會。去誘惑之橋上找他。祝你好運。", progress = nil, completion = "幸好我們在他們開始巡邏前就到了。我沒得到許可，不能停在這裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59707] = {title = "給稅務官的邀請函", objective = "到尊殞村與『霧刃』娜迪亞交談。", description = "稅務官就是個愛耍狠的懦夫，就跟他前幾任的嫉妒收割者一模一樣。\n\n但他目前還是個我們難以應付的對手。我已經派了娜迪亞和特梅爾去南邊的尊殞村，確保一切順利，以風險最小的方式接近稅務官。\n\n到那裡跟他們會合，萬事小心。只要稅務官認為這能夠進一步提升他的權力或地位，他絕對殺人不眨眼。", progress = nil, completion = "準備優雅登場了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59708] = {title = "給石鑄宗匠的邀請函", objective = "到威權之門與德瑞文將軍交談。", description = "憤怒勳章目前在石鑄宗匠手中。她很古老、強大，而且負責打造石源魔軍團。\n\n別想和她玩小把戲。有件很危險的事情要先問清楚，你能不能到威權之門與德瑞文將軍見面？\n\n如果我們想看到石鑄宗匠出席，她一定很清楚我們這個要求的嚴重性，這表示你和德瑞文要從正門進去。", progress = nil, completion = "這不會是輕鬆的一天。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59709] = {title = "來世的延續", objective = "和珊卓亞一起飛到勇氣神殿的入口。", description = "昇靈堡出現了新的黎明。我之前還有點疑慮，不過你證明了瑪卓薩斯尚未拋棄他們的榮耀。\n\n再度抓緊我的手。我會帶你回到神廟入口。\n\n讓整個瑪卓薩斯都知道我們的勝利。為了和平，請確保這種事永遠不會再發生。", progress = nil, completion = "期待我們再次會面。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59710] = {title = "奇特的邀約", objective = "與信差亞拉克會面。", description = "喂，那邊那個。沒錯，就是你。\n\n你就是那些尖牙齒一直講個不停的淵喉行者嗎？呃，我以為你會更大隻一點。\n\n算了，監工想要…呃…「向你致意，並邀請你造訪他的礦坑。」這是在形容我和我的同伴挖出來的那堆石頭？辭藻未免太華麗了。\n\n如果你想赴約的話，往下走到進食者的灌木林，見見尖牙齒的信差，亞拉克。他會把詳情告訴你。", progress = nil, completion = "嗯，看來人剛走，真不湊巧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59711] = {title = "嫉妒收割者", objective = "引導特梅爾穿過管理員莊園，並把雷納瑟王子的訊息送給稅務官。", description = "多謝你能在管理員莊園最短安全距離內與我們會面。這邊有許多人，依然認定我那尚未公諸於世的想法值得冒這些風險。\n\n想和稅務官交談，對你或我來說都太過危險。他太過衝動，一心只想討好戴納瑟斯。我建議我們去找特梅爾。\n\n石惡魔是瑞文崔斯的常見信差，而且除了幾個觀察者之外，其他人對它們的到來也都覺得習以為常。在你準備好之後，只要推他一下就好。", progress = nil, completion = "稅務官。我相信他是第二百七十五個，在村莊區裡面作威作福的管理員。\n\n他和之前任何一個嫉妒收割者一樣野心勃勃，只有在他認定目前立場可以獲得更多力量的情況下才會幫忙。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59712] = {title = "當前的形勢", objective = "查看娜迪亞並調查監工馬提亞斯的營地。", description = "嗯，對，不確定他為什麼想見你。我替他辦事很久了，在我看來，他只是想要你替他做些見不得光的事，以達成他的目的。不過，這可能是我先入為主，畢竟我有很多實例可以分享。\n\n我們去看看我的朋友娜迪亞的狀況吧。", progress = "你找到監工馬提亞斯的日誌了嗎？", completion = "非常感激你的幫忙，我的朋友。再這樣下去，我可會欠你不少人情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59713] = {title = "活性材料", objective = "為娜迪亞的調合劑收集材料。", description = "不先從馬提亞斯手中取走我的罪孽石，就很難對付他。我們需要準備某種東西把他敲昏。\n\n凡人，你能幫我拿點材料過來嗎？我有個很高明的計畫。", progress = "你拿到材料了嗎？", completion = "這應該能讓他昏迷好一陣子，以便趁機搶回我的罪孽石。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59714] = {title = "葡萄美酒", objective = "帶一瓶好酒給娜迪亞。", description = "我們需要一點特別的東西，作為調酒的基底。想讓他把調酒喝下去，必須讓他相信你送給他的是一份禮物。\n\n他自認是很專業的品酒大師。未開封的葡萄陳釀對他會是很大的誘惑。\n\n到廢墟附近的古老地窖找找，那裡以前是用來放補給品的。或許地窖的深處還藏著一瓶好酒。亞拉克和我會做好剩下的準備工作。", progress = "你找到合適的酒了嗎？", completion = "啊，太完美了。他一定無法抵抗這個誘惑。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59715] = {title = "給馬提亞斯的訊息", objective = "將監工馬提亞斯召回營地。", description = "很好，萬事俱備！等你準備好了，就讓信差亞拉克請監工馬提亞斯過來，假裝你才剛剛抵達。\n\n我敢肯定，以他最愛的酒作為禮物，一定能引他上鉤。我們在裡面下的毒，劑量足夠讓他癱瘓一段時間，我們可以趁機搶回我的罪孽石。\n\n我們的計畫一定能完美實現！", progress = nil, completion = "啊，淵喉行者！久仰大名。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59716] = {title = "飄飄欲仙", objective = "對馬提亞斯下毒，取得娜迪亞的罪孽石。", description = "一個凡人出現在瑞文崔斯。謠傳你可以自由進出淵喉？太驚人了。我有很多問題想問。\n\n不過，我必須克制自己的好奇心，我有…這麼說吧…有個對你我雙方都好的提議。如果你真的能在暗影之境暢行無阻，那麼，你就能取得一些我拿不到的情報。\n\n你知道你能幫我什麼忙了吧？來吧，我們再進一步詳談。", progress = "我的罪孽石，給我吧。", completion = "喔，做得好！我曾一度擔心你會不會不小心喝下毒藥，幸好你現在還活蹦亂跳的。", rewards = "痛苦赦免法衣石鑄胸鎧獵魂者鍊衫夜幕外衣石鑄護脛痛苦赦免窄褲獵魂者腿甲夜幕束褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][59717] = {title = "記得的事", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59718] = {title = "陽傘危機", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59719] = {title = "廷尉聚集", objective = "見證收割者廷衛的集會。", description = "好吧，我們人數夠了。你已經在這個舞台上為我們盡了一切努力，淵喉行者。\n\n現在輪到我了，得去說服這些古老的蠢蛋忘掉他們現實中最偉大的顧客，轉頭支持我這個帶來「新」計畫的失敗反抗軍。\n\n讓我們看看我還有沒有辦法像以前一樣左右群眾。祝我好運。", progress = nil, completion = "好吧，本來可以更順利的。我不預期他們會馬上改變立場，可是我希望至少有一到兩位願意響應。\n\n現在我們得來硬的了。我們應該在他們派出部隊、重新攻佔這座塔之前離開。", rewards = "您會收到：\n\n破魂者烏黑裹腕恐懼哨衛烏黑護臂懼獵者烏黑護腕烏黑死亡帷罩束腕"}
MultiLanguageQuestData['tw'][59720] = {title = "憤怒收割者", objective = "徒步通過違抗之橋。", description = "我們正走在與我並肩作戰無數次的兄弟姐妹的羽翼陰影下。他們都是剛從石頭雕塑出來之後就由我訓練。\n\n這是個遠古儀式。如果我們步行走過這座橋樑，沿路擊敗任何阻撓我們的敵人，就能夠謁見石源魔之母。不過，不保證我們能平安歸來，所以盡量不要冒犯她。\n\n接下來的戰鬥我並不樂見，但也別無他法。", progress = nil, completion = "我還記得第一個石源魔在石鑄宗匠灌注靈魄之後，隨之活動起來的那一刻。\n\n絕對、千萬不要把她對創造物的同情心，視為一個弱點。她握著憤怒勳章並不是沒理由的。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59721] = {title = "成為獵者", objective = "到長者之地內找胡恩‧高嶺。", description = "<雷頓對你咧嘴一笑。>\n\n他知道你會回來！犄角獵人已經先走一步，去準備狩獵場了。他叫你盡快去找他。\n\n既然你已經拿到做陷阱的材料，你只需要到他身邊就行了…\n\n那裡危機四伏，不過我設計了一種誘惑魔法，應該能幫助你躲過遊蕩野獸的追獵。要是有用的話，你或許可以幫我說點好話…\n\n嗯，總之，我們應該先以獵物為重。祝你狩獵順利，朋友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59722] = {title = "亡城大劫案", objective = "使用傳送門到統御者之座找卡莉克。", description = "亡城安全無虞，不過統御者之座傳送門只能維持一小段時間。\n\n卡莉克會跟著你回來，然後著手建立永久的傳送門。", progress = nil, completion = "我們彷彿永遠不會離去。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59724] = {title = "榮耀戰場", objective = "消滅在萎落廢墟的監工馬提亞斯追隨者。", description = "多虧了你，<name>，我終於掙脫馬提亞斯的魔掌，如此的自由…真是久違了。\n\n現在，讓我們一起進行報復行動吧。\n\n我要給你一個重責大任，就是在這場決鬥中擔任我的助手。我不知道你們那邊的規矩，但我有我的規矩，你的任務就是負責清場。馬提亞斯和他的追隨者在附近的萎落廢墟有個要塞。要是我猜得沒錯，他一定會逃到那裡。\n\n我先做一下戰前準備，等一下就去找你。", progress = nil, completion = "嗯，他真的選了一個風景優美的決鬥場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59725] = {title = "山崖邊的文獻管理員", objective = "到記憶林地與文獻管理員德瑞登交談。", description = "如果不能破除詛咒，可達林就會日漸消逝，直到魂飛魄散！\n\n我們以前常常束縛並封印像這樣的詛咒，不過我們已經很久沒遇過這種事了。\n\n去記憶林地找文獻管理員德瑞登，他能認出這是什麼詛咒，然後把對應的卷軸交給你。\n\n把卷軸帶回來，我們才能弄清楚需要什麼東西，才能反制詛咒。\n\n快點，<name>！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59726] = {title = "小心中計", objective = "接近馬提亞斯，開始決鬥。在馬提亞斯作弊時，協助娜迪亞。", description = "我終於能夠報仇了！\n\n我很肯定，要是馬提亞斯先看到我，他一定會再度逃跑，所以，朋友，你必須代替我跟他對峙。然後，在他分心的時候，我會激怒他。\n\n到時候，為了以防萬一，請你在旁壓陣。你必須確保馬提亞斯不會使出下三濫的手段。如果他真的這麼不要臉，希望你能協助我擊敗他。\n\n他就在那個閘門裡。", progress = nil, completion = "明明只要道歉就沒事了，他卻選擇背信棄義，最終自食惡果。", rewards = "竊罪者的法杖灌木叢橫掃者棘禍卡賓槍棘禍戰刃石崗哨細劍貴族速刃騎兵釘頭錘神聖釘頭錘棘禍長戟您會收到：\n\n"}
MultiLanguageQuestData['tw'][59731] = {title = "意料中的客人", objective = "進入亞登曠野，在森林之心與伯昂撒姆第見面。", description = "在我們等胡恩的消息時，有另外一件重要的事情發生了。\n\n伯昂撒姆第回到亞登曠野了。赫恩勛爵認為他想要晉見凜冬女王。\n\n但我知道死亡羅亞別有意圖。我在夢境中看見了。\n\n去找伯昂撒姆第。去了解命運為你們兩個的安排。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59732] = {title = "對凜冬女王錦上添花的東西", objective = "與伯昂撒姆第一起前往納茲米爾的亡城。", description = "你處理繆薩拉的時候做得不錯。我想要報答你的恩情。我們，畢竟是朋友…對吧？\n\n那個壞羅亞，現在任我宰割了。他一直呢喃著他從凜冬女王手中偷了某個東西。\n\n來我的亡城一趟。這樣你就能親眼看一看老伯昂撒姆第在說什麼。\n\n你會帶著好東西回來給女王陛下…很好很好的東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59739] = {title = "死亡羅亞大麻煩", objective = "殺死『背叛者』贊爾漢並取得他的護甲。", description = "繆薩拉一定還藏著什麼事情。老伯昂撒姆第要全部挖出來。\n\n但這個老羅亞把納茲米爾的不死生物都引來我的家門口！\n\n我需要一點時間才能撬開繆薩拉的嘴。\n\n有個叫贊爾漢的食人妖，負責指揮不死部隊。殺死他，讓繆薩拉看看他殘破的護甲。\n\n這樣應該就能撲滅他想逃走的希望。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59740] = {title = "破鏡重圓", objective = "修復破鏡子並領取獎勵。", description = "你已經成功地調整好很多面鏡子，我認為你可以開始親手修復鏡子了。\n\n只要找到碎片，修復鏡子不是什麼難事，不過有幾件事必須牢記在心。\n\n修復的鏡子十分脆弱，而且不可預測。它們經常用了一次就壞掉，而且無法保證鏡子會把你傳送到安全的地方。\n\n這裡有幾塊碎片，讓你先練習一下。\n\n將鏡子修復到能用的地步，看看它會帶你到哪裡。", progress = "我完全信任你的能力。", completion = "你找到一個恩惠？做得好！誰也無法確知鏡子後面到底埋藏著什麼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59741] = {title = "黑暗羅亞的黑暗魔精", objective = "從進攻亡城的不死生物身上回收100份黑暗魔精。", description = "這亡城到底要被攻打多少次？不能否認，沒人說過信仰伯昂撒姆第很容易…\n\n伯昂撒姆第想逼迫繆薩拉說出自己的秘密。我也得幫忙才行。\n\n亡城外的不死大軍是靠繆薩拉的魔精動起來的。\n\n伯昂撒姆第需要一點那種魔精，才能完成儀式。出去一趟，從遇到的不死生物身上取回魔精。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59742] = {title = "彼界的頑抗", objective = "對6名受傷的伯昂撒姆第信徒使用怪異的粉末。", description = "當不死族大舉進攻亡城的時候，很多伯昂撒姆第信徒都沒能來得及進城。\n\n我們需要多一點信徒幫忙，才能完成伯昂撒姆第的儀式，揭露繆薩拉的計畫。\n\n帶著這種粉末，把它灑在無法進城的信徒身上。這樣能驅散他們身上的黑暗魔法。\n\n至於已經死亡的…他們會在死後世界侍奉伯昂撒姆第。那是我們最後的願望。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59743] = {title = "牆上的蜘蛛", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59747] = {title = "失落的靈魂", objective = "殺死『迷失者』巴利希亞。", description = "珈爾瑪把我們的靈魂囚禁在這裡之後，我們許多人都掙扎著想逃出去，尤其是巴利希亞。\n\n她曾是一名偉大的勇士，但監禁生活讓她陷入瘋狂，黑暗吞噬了她的靈魂。我們在漫長的永世裡試著和她講理，但她顯然已經徹底沉淪。\n\n請結束她悲慘的一生。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59748] = {title = "無法安息", objective = "和亞歷山卓斯到昇靈堡與勇氣楷模交談。", description = "<name>，可以的話，我想請你幫個忙。\n\n這個地方…指引這些人的榮譽感和使命感呼喚著我。\n\n這就是我生前存在的價值。有段時間，瑪卓薩斯也跟我奉行相同的信念…但自我從淵喉歸來，卻發現這裡已經充滿背叛。\n\n我想跟神聖楷模談談昇靈堡。", progress = "有事嗎？", completion = "來吧，有很多東西要讓你看看。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59749] = {title = "輕聲低語", objective = "敲響銅鑼，召喚特別來賓，然後在活化繆薩拉的儀式中使用魔精粉末。", description = "事情是這樣的，<name>。想撬開繆薩拉的嘴，我們必須餵他吃這房間裡所有人的生命精華，一點點就好。\n\n為什麼用那種表情看我？老伯昂撒姆第有讓你失望過嗎？\n\n在他進食的時候，我就會用你拿到的魔精把真相從他嘴裡拖出來。\n\n喔，對了，還有兩件事。首先，我要你幫我邀請一個特別的…朋友。\n\n然後我會給你更多我的魔精粉末，要是在儀式過程中，我的信徒撐不住了，就使用粉末。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "女王近衛披風妖精編織披氅橡心斗篷符文看守者巨披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][59750] = {title = "成功之道", objective = "收集12顆血牙頭顱並帶去給麥索‧穆比。", description = "渴望在競技場上成為勇士的菜鳥？人們會喜歡像你這樣的故事，但第一步是吸引注意力。\n\n計畫如下。麥索‧穆比需要血牙頭顱，但只有真正的戰士才能取得那樣的東西！\n\n你去殺幾頭血牙，用我的小刀把他們的頭帶回來，然後送去給穆比。這應該可以讓你獲得認可。", progress = "你把頭顱送過去了嗎？", completion = "做得好，開始有人認同你了。我聽到人們開始談論這些血牙都是你宰的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59751] = {title = "穿越破碎天空", objective = "在冰封王座完成儀式，打開通往淵喉的裂隙。", description = "當希瓦娜斯扯碎統御之盔時，她碰觸到了頭盔所釋放的力量。\n\n我可以感應到那股力量的餘音，而且我知道她去了什麼地方。\n\n如果你想拯救聯盟和部落的領袖，這頂碎裂的頭盔可以打開一條通道。不過，它無法帶你回來。之後的一切，都只能靠你自己了。\n\n這麼做的風險相當高，<name>，但是我們沒有別的辦法了。所以，我們應該立刻開始進行儀式。", progress = nil, completion = "這不是什麼理想的抵達方式，但至少我們都還活著。\n\n我沒看到泰蘭妲的蹤影。她可能落到其他地方，或是不等我們獨自離開了。我們應該多加留意。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59752] = {title = "斷裂的刀刃", objective = "在惡徒坩堝集結10位黯刃騎士。", description = "這個地方的混沌能量把黯刃騎士打散了。\n\n而且艾澤拉斯的祝福恐怕也無法傳達給你，<class>。要在此地生存就少不了盟友。\n\n我們得在大家被各個擊破之前，趕緊找到他們。", progress = nil, completion = "我們來到此地沒多久，部隊的戰力就快耗光了。只剩下這個方法了。\n\n帶著這個號角。它可以呼喚殘存的黯刃部隊，集結對抗你的敵人。", rewards = "您會學到：\n\n黯刃號角\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59753] = {title = "毀滅者末路", objective = "在惡徒坩堝擊敗毀滅者馬洛斯。", description = "其中一個…較大的惡魔…正在和我們幾位騎士交戰…\n\n快去幫助他們…免得我們損失更多人手。\n\n快…我已經回天乏術了…", progress = "只要你一鬆懈，我們的盟友就會倒下。", completion = "我很不願意丟下我們的騎士，但我們顯然抵擋不住這樣的敵人。\n\n我們一定不能讓他們白白犧牲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59754] = {title = "張開黑化的翅膀", objective = "在卡西斯協助珍娜逃離淵誓追捕者。", description = "能夠再次看到友善的面孔，真讓人放心。但我們沒時間寒暄了。\n\n索爾受傷了，而且我們被這個地方的看守者追捕。我們一定要馬上找個避難處。\n\n走，我想我知道一個地方。", progress = "你在做什麼？沒時間聊天了！", completion = "這些幻象會引開敵人的注意力，但他們不會輕易放棄追捕。\n\n我們必須加快動作！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59755] = {title = "飛離黑暗", objective = "護送眾人從卡西斯前往荒棄休息處。", description = "附近不遠處有個洞穴。只要我們動作快一點，就可以在那邊避難。\n\n要是那些敵人發現我們的話，一定會緊追不放。所以還是要準備隨時迎戰！", progress = nil, completion = "趁現在喘口氣，&lt;name&gt;。\n\n我把我所知的一切告訴你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59756] = {title = "休息片刻", objective = "在荒棄休息處與珍娜交談，得知她對淵喉的理解。", description = "安杜因堅信我們的盟友一定會趕過來救我們。我承認，我已經開始不抱任何希望。\n\n我相信你心中一定有很多疑問，我會盡可能提供答案。但是我免不了擔心，經過了…\n\n已經多久…幾個禮拜？還是更久？在這黑暗的地方，時間彷彿失去意義。\n\n抱歉…我會盡可能把一切都告訴你。", progress = nil, completion = "我需要時間恢復那場戰鬥耗費的體力，索爾也需要好好休息。\n\n在我們休息的時候，或許你和莫格萊尼可以去尋求答案。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59757] = {title = "現場招魂", objective = "在苦難之境用碎裂的統御之盔號令5個惡毒暗影。", description = "如果這些靈魂知道我們所需的情報，我們一定會從他們的口中榨出來。\n\n伯瓦爾給你的頭盔雖然被女妖毀掉了，它的碎片依舊具有強大的統御之力。我們應該可以用它來控制這些靈魂，讓我們有足夠時間查明他們知道些什麼。\n\n但是要制伏這些靈魂，必須先將他們弱化到一定程度。你比較適合這個任務，我對你有信心。", progress = "你想和我談，還是想和死者談？", completion = "沒有用！這些靈魂已經過於殘破，無法提供我們有用的消息。\n\n等等…那是什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59758] = {title = "與死者對話", objective = "在苦難之境用碎裂的統御之盔號令受苦的融合體。", description = "你看那邊！那正是我們要找的目標！\n\n很難說有多少靈魂在那個融合體裡頭痛苦掙扎。如果運氣好的話，其中某個靈魂說不定還保持著理智，能為我們提供答案。", progress = nil, completion = "這麼多的靈魂，其中總會有一個願意開口的。\n\n把這個東西帶回洞穴，查清楚它到底知道些什麼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59759] = {title = "雄獅之籠", objective = "在鍊魂塔找到安杜因‧烏瑞恩國王。", description = "安杜因被關在一個陰影稱之為鍊魂塔的地方。那個地方並不遠，但路上危機重重。\n\n我試了好幾次，想要把他從拘捕者的手中救出來，但負責看守他的部隊太多，我一個人無力應付。\n\n我只能仰賴你的出現來改變局勢。", progress = nil, completion = "我心裡很清楚，聖光不會讓我們失望的。\n\n你在此現身就是明證。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59760] = {title = "加害者的鑰匙", objective = "在鍊魂塔從『加害者』斐爾身上取得加害者的鑰匙，然後解開淵鑄鐐銬。", description = "希瓦娜斯認定我們已經屈服、認定她已經勝券在握。\n\n我們會讓她知道，她錯得多離譜。\n\n首先，我需要你的幫助。困住我的束縛強到難以置信。我們需要鑰匙才能解開我的束縛。\n\n負責…囚禁我的是個名叫『加害者』的怪物。鑰匙很可能就在它身上。", progress = "你找到鑰匙了嗎？", completion = "我幾乎快忘了自由是什麼感覺。\n\n走，讓我們對這些邪魔宣戰吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59761] = {title = "無妄之災", objective = "從鍊魂塔的淵誓部隊身上收集淵誓之鑰，並釋放15位被束縛的靈魂。", description = "在監禁期間，我看到許多靈魂被帶來此處。閻獄之主似乎想要讓他們屈服，扭曲之後為他效命…或是更糟。\n\n沒有靈魂應該承受這種下場，<name>。\n\n此地的淵誓者握有他們鎖鍊的鑰匙。盡你所能的釋放他們，幫助他們從此地脫身。", progress = nil, completion = "我就知道這個工作可以仰賴你。\n\n雖然我們面對難以克服的劣勢，我們還是要努力做正確的事情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59762] = {title = "順流而下", objective = "越過『靈魂之河』果戈亞上方的橋樑。", description = "我們的下一步十分明確，我們必須前往佐瓦爾的大釜。我聽到那些靈魂低聲緊張地提到，那是一個熔爐般的可怕地方，就在靈魂之河的另一邊。\n\n我只去過那邊幾次，但我看到貝恩被那邊的士兵抓住。如果我們的運氣夠好，他應該還在附近。\n\n等他安全之後，我們就可以去找尋魔影提過的甬道石。", progress = nil, completion = "閻獄之主抓到貝恩了！\n\n這比我們原本擔心的還要糟…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59765] = {title = "非實質的傷口", objective = "從迪崔索斯的淵誓撕魂者身上收集一把凋萎刀刃。", description = "雖然貝恩的傷口正在逐漸癒合，但他的靈魂卻步步逼近死亡。我看過這樣的黑暗魔法…在影月氏族的身上。\n\n閻獄之主的僕從一定在貝恩身上施加了類似的詛咒。\n\n影月詛咒的唯一解法，就是找到他們用來毒害靈魂的物品，並將它打碎。\n\n這個地方的巫士都攜帶著裝飾用的匕首，說不定那正是我們要找的東西。\n\n我們一定得找出他們用來詛咒貝恩的那一把，而且動作要快！", progress = "我們只能期望，貝恩身上的詛咒確實是此地的某個巫士所施加的。", completion = "我們的運氣真好，能找到毒害貝恩靈魂的巫士。\n\n不過我需要你的協助，才能打斷它和牛頭人酋長之間的連結。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59766] = {title = "一把好斧頭", objective = "在迪崔索斯的淵誓武裝中找到適合索爾的武器。", description = "我居然把斧頭丟向那個巫婆，真是笨蛋。我們沒有時間分神了。\n\n眼前的戰鬥可不容易。我需要一把武器來協助我們奮戰到甬道石的所在之處。\n\n看來這些士兵握有許多武器。我們一起注意是否還有堪用的武器。", progress = nil, completion = "和霜狼氏族的斧頭比起來，這把的手感和工藝水準都比較差缺，但還算管用。\n\n我們繼續前進吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59767] = {title = "救贖之路", objective = "帶領你的盟友穿過佐瓦爾的大釜。", description = "想要找到甬道石，我們一定要加快動作。那個靈魂提到它俯視著大釜，所以它可能位在另一邊的山脊上。\n\n不幸的是，這個地方到處都是敵方部隊。我們最好避免和他們交戰，才不會招惹閻獄之主的注意。\n\n我可以保護我們不被人發現，但我們得緊緊聚在一起。", progress = nil, completion = "我們成功了！\n\n只要能啟用這個甬道石，我們就有機會逃出這個地方！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59770] = {title = "團結一心", objective = "在科賽路斯啟用侵蝕的甬道石。", description = "<安杜因專心查看方尖碑。>\n\n我從來沒見過這類的符號和標記。我研究過泰坦文物，但看來這似乎是出自其他的來源。\n\n嗯…它對我沒有任何反應。我想珍娜說得沒錯，甬道石是對你的出現產生反應。\n\n或許你能啟動它的機會比我們高。\n\n提高警覺。當它在休眠狀態時，閻獄之主的部隊完全不理會它。但如果情勢有變，很難判斷他們會怎麼做。", progress = nil, completion = "&lt;甬道石似乎正在等待什麼。\n\n你伸手碰觸它的表面…&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59771] = {title = "腐化歷史", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59772] = {title = "研究毀滅", objective = "到奧多薩摧毀5份研究報告。", description = "詛咒神教在奧多薩的城牆內繼續進行手頭的工作。\n\n潛入他們的房間並摧毀他們的研究成果。這樣做可能無法阻止他們，不過可以為我們爭取寶貴的時間。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][59773] = {title = "尋找晉升者", objective = "前往昇靈堡，詢問有關淵喉琪瑞安的事。", description = "當你抵達昇靈堡時，去找一名琪瑞安吧。向這名琪瑞安解釋你必須晉見御靈者。跟審斷者一樣，她也是統治暗影之境的其中一位永恆者。\n\n要是誰能引領你通往真相，那非御靈者莫屬。或許她甚至知道該如何終結這場靈魄乾旱。\n\n當你找到追尋的答案後，歡迎你回來奧睿博司。\n\n凡人，使命指引你的道路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59774] = {title = "迎接永生", objective = "與克蕾雅談話。", description = "請原諒我的失態。你看，連接奧睿博司的道路已經封閉很長一段時間了。我們甚至不知道它會不會再度開啟。\n\n高貴的靈魂，歡迎你來到昇靈堡。你生前的善行讓你得以迎來最光榮的天命！你會成為琪瑞安，帶著翅膀的死者。\n\n我是克蕾雅。很榮幸為你介紹我們美麗的國度。在展開旅程之前，你有很多需要學習的。\n\n打點一下。都準備好了後，我們就開始了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59775] = {title = "協助印迪寇找到潘希亞", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59776] = {title = "來自瘋狂之口", objective = "回到荒棄休息處去找達瑞安‧莫格萊尼領主，看看他知道些什麼。", description = "勇士，我真不知該如何表達我對你的感激。\n\n但是我們不能在此逗留。閻獄之主的部隊很快就會察覺到此處的騷動。\n\n我們立刻離開吧。", progress = nil, completion = "我發覺，其實我不太喜歡使用統御之盔。它蘊含的魔法會讓亡者…十分不安。\n\n我很高興能把它交回你手中。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59777] = {title = "協助卡利克斯找到阿梅希亞", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59778] = {title = "協助索恩找到瓦利克", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59779] = {title = "協助莫瑞亞茲找到巴頓", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59781] = {title = "最後一人", objective = "找到5位新人屍體，並殺死亡眼。", description = "你不是第一個想要成名的新人，像你這樣的人比比皆是！\n\n最近有幾個人想靠著擊殺一頭巨大血牙來證明自己…結果所有人都一去不回。你想得到認可嗎？\n\n那就去找那些失蹤的新人，並親手殺死那隻血牙。", progress = nil, completion = "最後一批的下場真是不幸，但你還健在！", rewards = "新手鬥士徽章您會收到：\n\n"}
MultiLanguageQuestData['tw'][59782] = {title = "亡頌者的虔誠信徒", objective = "到亡頌者之望殺死6個黑暗祭儀師和6個黑暗狂熱者。", description = "雖然亡頌者凱洛斯早就倒下，在附近山上的教徒還在進行他的惡毒計畫。\n\n看來他們受到天譴軍團復甦和天空裂縫的鼓舞，再次動手綁架我們的十字軍，開始進行那些可憎的鍊金實驗。\n\n上前去淨化他們營地中的狂熱者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][59783] = {title = "教徒的俘虜", objective = "從審問者葛雷爾身上取得審問者之鑰。到亡頌者之望解救8個被俘虜的志士。", description = "這些該死的教徒簡直沒完沒了！\n\n在我方毫無警覺之下，他們抓了幾位十字軍拖回營地。\n\n只有聖光知道他們在上面對十字軍做了什麼…\n\n聽說你打遍天下無敵手。我們的人數已經夠少了…如果你能救出這些被俘的人，我們會滿懷感激。\n\n你可以在山上營地找到潛伏的教徒。", progress = "你帶來什麼消息？", completion = "我怎麼一點都不意外？你讓這事看起來易如反掌。", rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][59789] = {title = "萬萬稅", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59800] = {title = "團隊精神", objective = "用團隊精神藥劑澆在15位競技場挑戰者身上。", description = "儘管我們彼此是競爭關係，但我們也都是瑪卓薩斯人。不管他們來自哪個家族，我們都會替他們加油。\n\n進入競技場，並將這個藥劑澆在挑戰者身上。這樣或許能提高他們的存活機率！", progress = nil, completion = "幹得好，你讓那些戰鬥者充滿了鬥志。他們會記住你的協助的…如果他們能活下來的話。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59801] = {title = "拿取力量", objective = "收集8枚靈魄果。", description = "等等！在你進去之前，我想拜託你一件事。\n\n雖然我們好一陣子都沒有野性種子，但我們還是有儲備靈魄。在趕走果姆方面，有靈魄還是很有用。\n\n不論我的村落發生了什麼事，我不想讓這股力量留在他們手中。把靈魄分給其他林地對於整個亞登曠野才更有幫助。\n\n留意村落中的靈魄。我們會把它拿到其他地方好好利用。", progress = "你找到任何靈魄了嗎？", completion = "願它們能在森林中發揮用途。願它們的生命沒有白白浪費。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59802] = {title = "毀滅的村落", objective = "跟隨帕提克。", description = "這本日誌的主人是黎沃爾，我們林地的領袖。上面寫著他找到某種東西可以對抗果姆，但如果它就是引發這一切的源頭呢？\n\n只有一個方法可以確定。跟我一塊前往村落，不管那裡還剩下些什麼。", progress = nil, completion = "不…不…村落。他們都…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59803] = {title = "為了榮耀", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59804] = {title = "恐懼甬道", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59805] = {title = "淵喉之行", objective = "前往淵喉，找到亞登曠野失蹤的荒野神靈。", description = "你也聽到繆薩拉說的…多虧了老伯昂撒姆第。有個古老的靈魂被困在淵喉。我打賭凜冬女王一定會想要回來。\n\n還好你有下去過那裡，對嗎？對你來說應該很簡單。\n\n我會解決這裡剩下的不死生物。等你回來，到亞登曠野來找老伯昂撒姆第。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59808] = {title = "越髒越好", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59809] = {title = "彼界境地", objective = "使用死亡之石前往彼界境地。", description = "你好啊，<name>…我是你的老朋友伯昂撒姆第！\n\n聽說你在替凜冬女王做事。大家對你的風評好像都很不錯！\n\n亞登曠野恐怕正面臨重大危機。但女王…唉，她太驕傲了，根本不屑跟老伯昂撒姆第打交道。\n\n你想要拯救森林嗎，老兄？那就來彼界境地找我。\n\n我會等你來…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59811] = {title = "盤點存貨", objective = "搜尋靜謐水塘，尋找消失的羅亞靈繭。", description = "<class>，黑暗力量正在入侵。\n\n羅亞在艾澤拉斯死亡後，都會來到亞登曠野準備重生。不過，某些在亞登曠野沉睡的羅亞卻消失無蹤！\n\n這一切的幕後黑手一定非常強大，才能在凜冬女王眼皮子底下把他們偷走…\n\n老伯昂撒姆第不容許羅亞從亞登曠野消失。不然遲早有一天會輪到我消失！不，不…我們要阻止這一切！\n\n回到亞登曠野，尋找消失的羅亞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59812] = {title = "隨著蹤跡走", objective = "尋找消失羅亞的線索。", description = "喔，老兄，我有不好的預感！\n\n野性種子不會無緣無故消失…尤其是裡面還寄宿著強大羅亞的種子！就算是哈卡和丹巴拉這樣的壞蛋，也都受到凜冬女王保護。一定是某個人…或某個東西…把他們偷走了！\n\n但是為什麼呢？他們離可以重生還早得很…\n\n四處找找，看看能不能找到一些線索。羅亞搞丟了絕對是壞事情，伯昂撒姆第跟老大的關係已經夠緊張了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59813] = {title = "繆薩拉的爪牙", objective = "擊敗高階祭司拉卡左杜和8個繆薩拉的士兵。", description = "這些人都是繆薩拉的追隨者！我早該猜到他就是這一切的幕後黑手。\n\n很早以前，繆薩拉是死亡羅亞，提拔老伯昂撒姆第的就是他，是他讓我成為羅亞。\n\n那是在他的崇拜者開始背棄他之前的事情了。他一直很貪婪…可是這次…\n\n繆薩拉這次做得太過火了！我們不阻止他的話，他就會奪走亞登曠野的所有羅亞！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59815] = {title = "被偷走的羅亞", objective = "找到『奪魂者』哈卡和丹巴拉。", description = "哈卡和丹巴拉就在這片林地附近…\n\n我們必須快點查清繆薩拉到底想做什麼。他們兩個是艾澤拉斯非常強大的羅亞…強大又邪惡。誰知道繆薩拉打算怎樣利用他們！\n\n搜索靈魂谷地。找到消失的羅亞並查清繆薩拉想要做什麼！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59817] = {title = "凜冬將至", objective = "晉見凜冬女王。", description = "老大打算集結恐怖羅亞，組成一支大軍。哈卡和丹巴拉可能只是開始。為什麼老大變得這麼強？我之前從沒看過他使用這種力量…\n\n凜冬女王對伯昂撒姆第沒什麼好感，不過我們需要她的協助，才能阻止繆薩拉。\n\n你跟女王是不是有點交情啊？如果她願意召集她的部隊，或許就能阻止繆薩拉，挽救一切。\n\n前往森林之心，與女王談談。她是我們剩下的唯一希望。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "妖精編織裹手橡心臂甲女王近衛護手符文看守者手套您會收到：\n\n"}
MultiLanguageQuestData['tw'][59818] = {title = "集結獵者", objective = "將曠野獵者召集到亞登曠野的特那諾。", description = "雖然我完全不想幫助伯昂撒姆第，不過繆薩拉必須接受制裁才行。\n\n我們會根除他的崇拜者，把他們逐出森林，以免他們造成更多傷害。\n\n通報林地，召集曠野獵者，亞登曠野急需保衛者現身。\n\n<獵人/獵人>，儘快動身。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59819] = {title = "掃蕩森林", objective = "在作戰中協助曠野獵者，對抗繆薩拉的部隊。", description = "凜冬女王命令我們把繆薩拉的部隊趕出亞登曠野。\n\n這場戰鬥可不輕鬆。死亡羅亞的勢力十分強大，已經讓我們好幾位獵人身負重傷。\n\n<name>，我們可以靠你扭轉戰局嗎？\n\n協助我們倒下的盟友，並削弱繆薩拉的爪牙！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59821] = {title = "向女王回報", objective = "與凜冬女王交談。", description = "繆薩拉的部隊已經潰不成軍，曠野獵者遲早都會將他們徹底逐出亞登曠野。\n\n但我的直覺告訴我，伯昂撒姆第和繆薩拉之間的衝突還沒結束。那個詭異的小面具陷入沉寂…\n\n你應該快點回到森林之心，向凜冬女王回報。她會指示我們下一步該怎麼走。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59822] = {title = "追蹤荒野神靈", objective = "尋找亞登曠野失蹤靈魂的下落。", description = "這是個黑暗的地方，<name>。我們必須找到被困在這裡的靈魂。\n\n我應該可以找到他的蹤跡…不過我這個老暗影獵手只能做到這樣。\n\n要是我試著跟你一起戰鬥，我跟艾澤拉斯的薄弱連結可能會就此斷裂。這樣一來，我也會被困在這裡。\n\n來吧，我們最好快走。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59824] = {title = "拯救羅亞", objective = "在淵喉中尋找並救出三位受困的羅亞。", description = "雖然我們是來找亞夏曼的，不過我感覺到前面有羅亞正在受到折磨。如果我沒弄錯，應該有三個。\n\n我不知道他們是誰，不過他們不屬於淵喉。\n\n我們必須把他們也帶回亞登曠野！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59825] = {title = "收集種子", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][59826] = {title = "押在自己身上", objective = "當黛瑞斯女士出現在苦痛劇場時擊敗她。", description = "親愛的淵喉行者…我的朋友…你會輸。每個人都很清楚，你根本打不過競技場那些人。\n\n整個挑戰者大道都很清楚，奧睿博司的仲介者很清楚，就連佐姆羅也很清楚。\n\n我帶了一位特別的挑戰者來，剛好可以證明這一點。在苦痛劇場面對黛瑞斯女士，然後證明我們錯了…或是證明我們是對的。\n\n我們會下注，不要讓人失望。", progress = nil, completion = "你的表現讓我大賺了一票…佐姆羅下錯注了。", rewards = "您會收到：\n\n腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐"}
MultiLanguageQuestData['tw'][59827] = {title = "押在自己身上", objective = "當戴弗莫塔出現在苦痛劇場時擊敗他。", description = "親愛的淵喉行者…我的朋友…你會輸。每個人都很清楚，你根本打不過競技場那些人。\n\n整個挑戰者大道都很清楚，奧睿博司的仲介者很清楚，就連佐姆羅也很清楚。\n\n我帶了一位特別的挑戰者來，剛好可以證明這一點。在苦痛劇場面對戴弗莫塔，然後證明我們錯了…或是證明我們是對的。\n\n我們會下注，不要讓人失望。", progress = nil, completion = "你的表現讓我大賺了一票…佐姆羅下錯注了。", rewards = "您會收到：\n\n腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐"}
MultiLanguageQuestData['tw'][59828] = {title = "押在自己身上", objective = "當提奧出現在苦痛劇場時擊敗她。", description = "親愛的淵喉行者…我的朋友…你會輸。每個人都很清楚，你根本打不過競技場那些人。\n\n整個挑戰者大道都很清楚，奧睿博司的仲介者很清楚，就連佐姆羅也很清楚。\n\n我帶了一位特別的挑戰者來，剛好可以證明這一點。在苦痛劇場面對提奧，然後證明我們錯了…或是證明我們是對的。\n\n我們會下注，不要讓人失望。", progress = nil, completion = "你的表現讓我大賺了一票…佐姆羅下錯注了。", rewards = "您會收到：\n\n腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐"}
