MultiLanguageQuestData['tw'][59856] = {title = "瑞贊，帝王羅亞", objective = "接收沃金的一些靈魄以保護自己，然後殺死伊薩比斯，拯救瑞贊。", description = "瑞贊是強大的羅亞，對贊達拉不可或缺。\n\n我們必須救他…不過這個生物身邊有一道死亡屏障，沒人能夠穿越。\n\n除非…我利用自己的靈魄幫你製造反制這個魔法的護盾。\n\n你得速戰速決，殺死那個吸取瑞贊力量的怪物。我的靈魄支撐不了太久。\n\n等你準備好了，就說一聲。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59862] = {title = "失落靈魂的救星", objective = "與看守者一塊走到林地。", description = "森林輕嘆著招呼你，淵喉行者。\n\n你的到來寫在星空中，枝葉都在等待。我們的工作可以開始了。\n\n繼續下去吧。\n\n沿著這條路進入林地。\n\n這些只是我們要一起踏上的旅途的開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59863] = {title = "戰鬥抑制機器人07-X", objective = "為能量抑制模組充能，在辛德拉苟莎之殞以戰鬥抑制機器人07-X轟擊5個敵人。", description = "雖然每個人都忙著用刀劍和魔法抵禦敵人，要不要試點不一樣的。\n\n看吧，我的最新發明：戰鬥抑制機器人07-X！\n\n有了這個裝置，你再也沒有永遠的敵人！\n\n目前我還沒辦法解決能量調節的計算問題，但我確定它能運作了。大部份啦。\n\n現在呢，我們需要從敵人身上「借」點能量才能讓它運作。\n\n上吧。將它充飽能量然後試看看！", progress = nil, completion = "哦哇！真是一場大爆炸，對吧？", rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][59865] = {title = "微光飛行", objective = "觀看科瓦斯寇的試飛。", description = "好好玩喔！\n\n來吧，馬上進行另一個測試，我等不及了！", progress = nil, completion = "成功了！我飛起來了！\n\n我還能再做點調整。這些爍亮蝶是我的謝禮，收下吧。我會收集更多爍亮蝶！", rewards = "您會收到：\n\n纖絲上的爍亮蝶"}
MultiLanguageQuestData['tw'][59866] = {title = "道別時刻", objective = "將迷失的羅亞和沃金帶去見亞登曠野的凜冬女王。", description = "我不知道老沃金會迎來什麼命運…不過到了亞登曠野，一切就會揭曉。\n\n亞夏曼、希爾雷克、沙德拉…他們也屬於那裡。\n\n我們最好快點離開這裡，我已經受夠淵喉了。您會收到：\n\n", progress = nil, completion = nil, rewards = "妖精編織風帽橡心頭冠女王近衛巨盔符文看守者面罩您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59867] = {title = "懸賞：評估者維克斯", objective = "除掉評估者維克斯", description = "苦痛劇場的懸賞目標，罪名是未能清償賭債、竊盜競技場資產，以及殺害合法的討債人員。為了除掉這個維克斯，允許使用任何必要的暴力手段。\n\n特別提醒，請留意為數眾多的同夥，他們對於外來者充滿敵意。\n\n除掉這個重犯為最優先事項。", progress = nil, completion = "做得非常好，淵喉行者。我會派佐姆羅去取回我們失竊的資產。", rewards = "您會收到：\n\n腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐"}
MultiLanguageQuestData['tw'][59868] = {title = "重獲自由的機會", objective = "弱化棘禍家族的汎希爾人，然後讓他們取回自己的罪孽石。", description = "就像我以前一樣，你遇到的一些棘禍家族的汎希爾人一直被迫服從馬提亞斯。他們很可能不想與你為敵，只是別無選擇。等到他們受了傷，他們或許願意停手，看看在你之前取回的罪孽石當中，有沒有他們的罪孽石。\n\n可以的話，就讓他們重獲自由。利用罪孽石來逼迫他人，是件不道德的事。", progress = nil, completion = "你今天交到一些朋友。", rewards = "您能選擇下列奬勵中的一個：\n\n棘禍璽戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59871] = {title = "加以催化", objective = "在催化區使用催化物質。", description = "林地生機盎然，其中庇護的靈魂也生氣勃勃。\n\n你成功獨力滋養靈魂，讓它重生。現在你必須學習如何使用催化物質。\n\n把催化物質種植在野性種子附近後，就能賦予沉睡的靈魂生前前所未見的力量。這股力量會保留到它重生之後。\n\n催化物質相當稀罕，不過我這裡剛好有一種可以讓你使用。其他催化物質則可在暗影之境各地找到。\n\n現在，種植催化物質，見證其中蘊藏的潛能。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59872] = {title = "救神之道", objective = "將靈魂種子放入野性種子中。", description = "確實有許多凡人靈魂在淵喉中受苦。但有許多大自然的神靈也是。\n\n光靠靈魄不可能撫平閻獄之主所造成的傷痛。從他手中奪回的靈體必須重新種植、細心照護。\n\n這些野性種子和其他的不同。這片林地，也跟其他的林地都不同。他們之中沉睡的希望，能讓最殘弱的神靈都有機會重生。\n\n例如這位。把靈體放到野性種子中。讓他開始進行重生。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59873] = {title = "向神致意", objective = "等待這個靈魂孵化完成，接著打開野性種子。", description = "這個靈魂重生之刻就快到了。那是幾乎被淵喉湮滅的命運，卻讓林地和管理者重新點燃。\n\n時間是靈魂的良藥。過了夠久，你就能將雙手放在野性種子上，然後喚醒他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59874] = {title = "淵喉", objective = "到奧睿博司與伯瓦爾交談。", description = "$p，你的到來讓瑪卓薩斯火上加油。要是你有榮譽可言，就照我說的做。\n\n我知道該去哪裡尋找我們要的答案。在德拉卡升女爵之前有位男爵在淵喉失蹤了。聽說你曾去過那個黑暗深淵…然後又回來。\n\n如果他還活著，他或許會知道下一步該怎麼做。\n\n你來自奧睿博司，回去一趟，看看你能不能找到辦法重回淵喉。", progress = nil, completion = "瑪卓薩斯有什麼消息嗎，&lt;name&gt;…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59876] = {title = "戰地報告", objective = "向艾爾文森林、赤脊山和暮色森林的軍官取得報告。", description = "天譴軍團隨時隨地都可能發動攻擊。\n\n為了戒備突襲，銀白十字軍在南邊向東小徑的要地駐紮部隊。但是已經過一段時間了，我還沒收到斥候的任何報告。\n\n天譴軍團的行蹤飄忽不定，我擔心他們已經遇害。\n\n去小徑一趟，檢查一下我們的崗哨。希望你回來的時候，能帶回完整的報告。\n\n<name>，願聖光與你同在。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59877] = {title = "來自寒冰皇冠的消息", objective = "到寒冰皇冠的銀白聯賽場地向審判者瑪瑞爾‧真心報到。", description = "我們在北裂境的部隊也傳來消息。審判者真心需要我們立刻出手相助。\n\n既然你是位身經百戰的<class>，我請求你響應號召。\n\n這次召集的急迫性不容忽視，就算這意味著必須直接面對寒冰皇冠的恐怖之處也不例外。\n\n我知道你擔心此地每個人的安危，我會繼續整合我們在這裡的行動，召集更多援軍。\n\n<name>，願聖光與你同在。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59878] = {title = "太多幼龍", objective = "到辛德拉苟莎之殞殺死4位巨龍復生者和12頭霜育雛龍。", description = "如果冰霜巨龍在我們頭上四處轟炸，想要守住這個地方希望渺茫。\n\n教徒在一直附近讓幼龍起死回生。我們消滅的數量越多，朝我方部隊噴吐致命寒冰的怪物就越少。\n\n結束他們的工作。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][59879] = {title = "檯面下的規則", objective = "與奧納寧會面。", description = "奧納寧是這裡階級最高的仲介者，她負責為我們提供鬥獸場用的異地生物。\n\n她注意到你的努力，想跟你會面！\n\n這很重要，只要能跟仲介者打好關係，就可能受邀參與比賽！", progress = nil, completion = "你是一個大名鼎鼎的外來者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59882] = {title = "穩賺不賠", objective = "與路易森會面你似乎能帶來不少利益。\n\n很多勢力都對你感興趣，認為你在苦痛劇場大有可為，願意在你身上下注。\n\n去吧，路易森會安排你的出場時間。您會收到：\n\n完成任務後，你將獲得：\n\n", description = "你似乎能帶來不少利益。\n\n很多勢力都對你感興趣，認為你在苦痛劇場大有可為，願意在你身上下注。\n\n去吧，路易森會安排你的出場時間。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59894] = {title = "黃金黎明", objective = "傳送至瞰臺，與德拉卡會面。", description = "戰爭的機器發動了，珈爾瑪的惡行現在已經對整個暗影之境造成威脅。\n\n昇靈堡想要復仇，我們也是。只有我們兩股勢力結合，才能一勞永逸傀儡大軍。\n\n到瞰台找德拉卡。你的出席有助於讓協議更加穩固。", progress = nil, completion = "既然已經結盟，那我們現在就開始計劃攻擊。", rewards = "您能選擇下列奬勵中的一個：\n\n刃誓戰旗\n\n您還會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59897] = {title = "尋找男爵", objective = "進入淵喉。", description = "帶著這個護符，四騎士的每個成員都有類似的護符。\n\n護符之中灌注的力量讓它們可以彼此連結。你可以利用這個連結找到達瑞安‧莫格萊尼。\n\n達瑞安在淵喉一定看遍了無數恐怖事物。或許他也看過那個失蹤的男爵。\n\n希望他也能帶領你，找到我們的艾澤拉斯盟友。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
