MultiLanguageQuestData['tw'][59907] = {title = "淵誓威脅", objective = "在惡徒坩堝擊敗8位淵誓敵人。", description = "我們的騎士團十分強大，但四處分散難以打贏這樣的對手。\n\n我們得削弱敵軍的數量。如果黯刃騎士被擊潰，我們就麻煩大了。", progress = nil, completion = "敵人冷酷無情，但我們會繼續擊退他們。\n\n保持警覺，&lt;class&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59910] = {title = "飛行與戰鬥", objective = "與珊卓亞一起飛往傀儡家族領地。", description = "莫格萊尼和艾曼妮負責指揮對西門的攻擊行動。\n\n珊卓亞和你則會從東邊進軍。奪取陣地，殺死所有反抗的人。\n\n等到我們順利包圍他們，就能對珈爾瑪進行最後一擊。", progress = nil, completion = "這個地方已經徹底失序。一定要淨化他們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59914] = {title = "如履薄冰", objective = "偵察卡西斯，尋找任何盟友的跡象。", description = "看來我們暫時逃出了敵人的追捕。我們應該利用這個機會，偵察附近的區域，尋找盟友的蹤跡。\n\n孤身行動比較不會引人注目。黯刃騎士會留在後方，等候我的信號。\n\n走吧，看看這處地獄還有什麼在等著我們。", progress = nil, completion = "讚美聖光！我…我都快要放棄希望了。\n\n&lt;珍娜抬頭看著黯刃騎士。&gt;\n\n這就是…你們殘留的部隊？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59915] = {title = "靈魂在手", objective = "返回荒棄休息處找珍娜‧普勞德摩爾女士。我的直覺果然沒錯。不管是什麼樣的黑暗魔法束縛了這些靈魂，多多少少也保留了他們的理智和記憶。\n\n這得花點時間，但我們會查明這個東西知道些什麼。我的審問過程需要頭盔，但我保證之後一定會交還給你。\n\n讓我們把這個戰利品帶回去給海軍總帥吧。", description = "我的直覺果然沒錯。不管是什麼樣的黑暗魔法束縛了這些靈魂，多多少少也保留了他們的理智和記憶。\n\n這得花點時間，但我們會查明這個東西知道些什麼。我的審問過程需要頭盔，但我保證之後一定會交還給你。\n\n讓我們把這個戰利品帶回去給海軍總帥吧。", progress = nil, completion = "看來你的搜尋大有斬獲。\n\n休息得夠了。還有很多事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59916] = {title = "昇靈堡的屠夫", objective = "在隔離室殺死10位傀儡家族的部隊。", description = "這些惡魔攻擊昇靈堡的時候，有對我的族人仁慈嗎？當他們撕裂我兄弟姐妹的肢體，並用他們來製作更多…這種怪物的時候，還有仁慈嗎？\n\n沒有！在那一天，屠殺昇靈堡的人就已經明確展現了他們的想法！\n\n他們只配面對永恆的黑暗。我要他們親眼見證！", progress = nil, completion = "流這麼多血也無法將他們帶回來…但或許可以讓其他人不再遇到同樣的命運。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59917] = {title = "見到就殺", objective = "殺死8隻狂怒暴食者。", description = "這些無腦的怪物從暗影之境的偏遠之地傾巢而出。靈魄乾旱讓它們餓到發狂，迫使它們尋找新的食物來源。\n\n委婉點說，它們的存在令人感到不便。\n\n它們會大肆破壞土地，拼命尋找靈魄。我們必須削減它們的數量，才能爭取足夠時間，保護墓穴珍藏的知識。\n\n這種事你應該早就駕輕就熟了吧？", progress = nil, completion = "做得好。你幫我們爭取到了寶貴的時間。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59919] = {title = "贏得的羈絆", objective = "與米卡尼寇斯成為靈魂之絆。", description = "你還有一件事情待辦，淵喉行者。\n\n在重建晉升紋章的過程中，你不只贏得了琪瑞安同伴的信賴，還贏得了他們的好感。看來我們的首席熔爐士米卡尼寇斯很享受你們共處的時光，並想和你締結為靈魂之絆。\n\n從他的喜好看來，嗯，對他本人來說，我和你一樣都很訝異。你一定深深打動了他。", progress = nil, completion = "在我渡過的千年光陰中，從來沒想到我會看到有一位侍者和外來者締結靈魂之絆。時代真的在變動，不是嗎？", rewards = "您會學到：\n\n靈魂之絆：米卡尼寇斯\n\n您還會收到：\n\n名望"}
MultiLanguageQuestData['tw'][59920] = {title = "熔爐士，快點燃熔爐", objective = "協助熔爐士索芬妮。", description = "看來，我們終於擁有點燃熔爐所需的材料了。\n\n但恐怕這裡已經年久失修，不管是刻意嘗試不用靈魄工作，還是單純疏失，都別期待熔爐可以正常使用。\n\n在我試圖讓熔爐再次恢復運作時，要是你能幫忙讓這個地方回歸正常，我會感激不盡。", progress = nil, completion = "我很感激你的協助。現在我可以再次練習我的手藝了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59921] = {title = "我的所有可能性", objective = "與亞歷山卓斯‧莫格萊尼一起對著回憶卷軸深思。", description = "這就是前任勇氣楷模打贏上古戰役的地點，她為了暗影之境獻出自己的生命，我只希望自己也能犧牲奉獻。\n\n我的很多侍徒都在這裡對著卷軸沉思。透過卷軸，我們複習勇氣的要義。\n\n陪同亞歷山卓斯在他的聖壇上回想，幫他瞭解自己的勇氣源自何處。\n\n他會知道這個命運非他所屬。", progress = "有什麼消息嗎？", completion = "這場冒險是否讓你有所啟發？", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][59922] = {title = "請別忘記", objective = "回到統御者之座找德拉卡。", description = "一如往常，審斷者的審判絕不可能出錯。\n\n儘管亞歷山卓斯對聖光的虔誠不容否認，不過他真正的力量來源是他對所愛之人的記憶。他是瑪卓薩斯的人，不是昇靈堡的人。\n\n然而，我們收回神殿的目標也不會改變。我的復仇尚未達成，不過，我現在知道瑪卓薩斯還有可以信任的人。\n\n去吧。向你的領導者傳達今天獲勝的消息。\n\n然後，明天我們會將所有敵人一網打盡。", progress = nil, completion = "這麼說，我們證明了我們的榮耀…還得到新的盟友。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59926] = {title = "暖身", objective = "與作戰假人戰鬥來進行暖身。", description = "我們已經接近部落上一支遠征隊失蹤的島嶼了。\n\n你必須做好萬全準備。用這些戰鬥假人暖個身。\n\n我來看看你的能耐！", progress = nil, completion = "看來我們出航之後你有持續訓練，這樣很好。\n\n我必須跟船員討論一下這場風暴。\n\n和索格比劃試試，他會評估你的能力，決定登島之後你該扮演什麼角色。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59927] = {title = "堅守陣地", objective = "與蠻兵索格比劃。", description = "Lok'tar！雨中的戰鬥會然讓人神清氣爽。\n\n我們比劃一下，讓我測試看看你的實力！", progress = nil, completion = "你是個很厲害的&lt;class&gt;。說不定你也能在這座島上找到屬於你的榮耀！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59928] = {title = "準備衝擊", objective = "尋找督軍布瑞卡。你打得很好，<name>。你會成為部落的力量與榮耀！\n\n現在我們…等一等…\n\n那是什麼聲音？", description = "你打得很好，<name>。你會成為部落的力量與榮耀！\n\n現在我們…等一等…\n\n那是什麼聲音？", progress = nil, completion = "這艘船不會完好無缺地抵達那座島。\n\n堅守信念，祈禱元素不會讓我們淒慘地死在海上。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59929] = {title = "瘋狂魚人", objective = "從魚人手中取回6個急救包。", description = "海灘上到處都有船難痕跡。這一定是失蹤的遠征隊出事的島。\n\n我們必須先治療傷兵，才能出發探索。要是棄同伴於不顧，就毫無榮耀可言！\n\n魚人偷了我們的醫療補給品。殺死那些害蟲，取回急救包。", progress = "那幫魚人拿了我們的急救包。殺死他們，把所有急救包帶回來給我。", completion = "做得非常好。我們去協助倖存者恢復過來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59930] = {title = "緊急救助", objective = "對阿波、密斯尊‧追晨者和蘭娜‧喬丹使用急救包。", description = "我們必須先治療傷者，才能開始搜尋我…搜尋失蹤的遠征隊。\n\n拿這個急救包去幫助生還者。部落絕不會棄同伴於不顧！", progress = nil, completion = "既然大家都已經沒有大礙，那就開始行動，另一支遠征隊就在這座島上的某處。", rewards = "您會收到：\n\n空的急救包"}
MultiLanguageQuestData['tw'][59931] = {title = "搜尋失蹤的遠征隊", objective = "搜尋附近的營地，找出遠征隊倖存者。", description = "我看見北方有火光。我們要去調查一下，看看是不是遠征隊的人點的。\n\n你是新兵中的新兵，最好跟我一起行動。\n\n來吧，朝北方前進。", progress = nil, completion = "好…餓…\n\n他們帶走…其他人…我是…最後一個…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59932] = {title = "烤肉", objective = "從廢棄營地附近的野生動物身上取得5塊生肉，然後用營火烹調。", description = "這是翁莎，是跟著遠征隊的薩滿。\n\n她快要餓死了，那不是部落成員該有的死法！\n\n殺死附近的野生動物，用這裡的營火烤熟。\n\n等到翁莎吃飽了，我們再問他失聯的遠征隊發生什麼事。", progress = "拜託…我需要…一些食物…", completion = "&lt;翁莎飛快吞食你煮熟的肉。&gt;\n\n看來我暫時不用去敲伯昂撒姆第的大門了。\n\n你們最好快點，野豬人抓走了秀嘉和遠征隊的其他人！", rewards = "您會收到：\n\n硬肉乾"}
MultiLanguageQuestData['tw'][59933] = {title = "強化戰術", objective = "與督軍嚴斧比劃。", description = "翁莎說野豬人抓走失蹤的遠征隊…包括我女兒在內。\n\n只要你一大意，野豬人就會取你性命。他們比起魚人更加聰明而凶暴。\n\n我不會讓你白白去送死。我們要進行最後一場比劃，確定你的實力。\n\n比劃之後，我們就去找野豬人斬出一條血路！", progress = nil, completion = "你已經準備好大開殺戒了！我們去跟翁莎談談，看看她知道些什麼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59934] = {title = "強化戰術", objective = "與督軍嚴斧比劃。", description = "翁莎說野豬人抓走失蹤的遠征隊…包括我女兒在內。\n\n只要你一大意，野豬人就會取你性命。他們比起魚人更加聰明而凶暴。\n\n我不會讓你白白去送死。我們要進行最後一場比劃，確定你的實力。\n\n比劃之後，我們就去找野豬人斬出一條血路！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59935] = {title = "一路向北", objective = "向北偵察，尋找密斯尊‧追晨者。", description = "野豬人綁走了遠征隊的其他人，帶他們往北方去了。\n\n他們說要把遠征隊的人當成祭品！\n\n你們最好快點往北走，才來得及阻止他們！", progress = nil, completion = "我有好消息…和非常壞的消息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59937] = {title = "馴服野性", objective = "向密斯尊‧追晨者學習馴服野獸，然後對附近的任何野生動物使用。", description = "像你這樣的獵人身邊都需要優秀的寵物。你沒有自己帶上伙伴嗎？\n\n看來我得想辦法彌補的訓練的不足。\n\n仔細聽清楚，希望你機靈一點學習。我會教你怎麼馴服野獸，讓牠成為你的寵物。\n\n如果要跟野豬人戰鬥，一定需要寵物才行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59938] = {title = "擊敗野豬人", objective = "殺死地領主奎克歐格。", description = "我發現，野豬人正在對失蹤的遠征隊其中一個倖存者進行死靈儀式。\n\n負責執行儀式的是這個部族的領導者，地領主奎克歐格。\n\n殺死奎克歐格，拯救倖存者。\n\n讓這隻肥豬看看部落可不是好惹的。", progress = nil, completion = "你真的很有膽量！我很佩服。加入這支遠征隊的時候，我以為只是快速賺點小錢的任務。\n\n結果現在不只有死靈法術，還有瘋狂的巨魔…或許我能趁機賺點大錢！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59939] = {title = "禁忌的野豬人死靈法術", objective = "在野豬人棘地殺死7名野豬人。", description = "野豬人是個野蠻而暴力的種族。我沒想過他們能學會死靈法術。\n\n我們當然不能讓他們繼續進行儀式，更不用說拿部落成員當祭品。\n\n殺死巢穴中的野豬人。讓他們知道自己犯了致命的錯誤。", progress = nil, completion = "做得很好，野豬人似乎開始跟我們保持距離。或許已經得到教訓了。", rewards = "遠征隊鎧甲戰靴遠征隊布甲長靴遠征隊鎖甲脛甲遠征隊皮甲長靴遠征隊鎧甲戰靴遠征隊布甲長靴遠征隊鎖甲脛甲遠征隊皮甲長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][59940] = {title = "摩托推進器Mk5", objective = "用摩托推進器Mk5找出秀嘉‧嚴斧。", description = "你在找秀嘉‧嚴斧，對吧？我得說，她有點激動啊。總是在說要靠一個人的力量自己前進。\n\n不過你運氣很好，因為我是唯一一個可以幫你找到她和遠征隊其他人的哥布林！\n\n看看這個超酷炫的裝置。我從一個地精那裡偷來後，做了一點改造，把它變成自己的東西！\n\n它叫作摩托推進器Mk5。用它來找到秀嘉和其他人吧。", progress = nil, completion = "很好，是時候改變規則，造出巨型野豬了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59941] = {title = "調整大小的解決方案", objective = "對3頭遊蕩的野豬使用尺寸修改器。", description = "我有個好道具叫作尺寸修改器。往剛剛就是用它來放大摩托推進器Mk5。\n\n聽著，我老實跟你說，我只有稍微裡解這東西的運作方式。\n\n所以我會不停按按鈕，看看會發生什麼事。\n\n我敢說，我們早晚能找到將這些野豬巨大化的方法。到時候我們就能用牠解決那些不死族！\n\n你負責拿好尺寸修改器，我來調整看看。然後你就按下按鈕，呃…祈禱會發生好事。", progress = nil, completion = "巨型野豬的計畫沒戲唱，但你們把裝置改造成武器了？\n\n做得好。我們來看看你們會不會成功。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59942] = {title = "死亡修改器", objective = "搭乘摩托推進器Mk5，炸掉不死生物大軍。", description = "我有個完美的計畫。你騎著摩托推進器Mk5進去，轟爛那些行屍走肉！\n\n我決定把尺寸修改器正式改名為「死亡修改器」。讓這些不死族知道死了就該好好躺著！\n\n呃，除了「我們的」不死族以外啦。我們的很棒。\n\n言歸正傳，跳上摩托推進器Mk5，我來駕駛。\n\n等我們救了秀嘉‧嚴斧，我們就轟出一條路去找其他生還者！", progress = nil, completion = "謝謝你，陌生人。我辜負了部落…我不夠強大，無力獨自阻止這個威脅。", rewards = "遠征隊之斧遠征隊長弓遠征隊法杖遠征隊法杖遠征隊巨斧遠征隊巨劍遠征隊法杖遠征隊法杖遠征隊長弓遠征隊短劍遠征隊匕首遠征隊匕首遠征隊鬥棍遠征隊鬥棍您會收到：\n\n"}
MultiLanguageQuestData['tw'][59943] = {title = "鷹身人問題", objective = "到鷹身人棲息地附近與阿波會面。", description = "再次謝謝你救了我，<name>。我保證不會再展露弱點。\n\n那些巨魔計畫要把倖存的遠征隊員當成儀式的祭品，準備復活那條龍。\n\n其中一個倖存者被帶到這裡往北的山丘。阿波先出發去偵察了。\n\n來吧，我們去看阿波有什麼發現。", progress = nil, completion = "我已經找到失蹤的遠征隊隊員…不過我們得先解決很多問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59944] = {title = "拯救赫伯特‧幽爆", objective = "從鷹身人的死靈儀式中救出赫伯特‧幽爆", description = "鷹身人打算把遠征隊的被遺忘者法師，赫伯特‧幽爆當作祭品。\n\n我們的敵人居然想讓不死族當邪惡死靈法術的祭品。\n\n赫伯特自己的道德觀有點…爭議，但他向來很努力幫助部落。我們需要他的魔法幫助我們阻止巨魔。\n\n我們上吧。", progress = nil, completion = "謝謝你救了我！。他們一定是被逼急了要找人犧牲，才會拿已經死的人當祭品。\n\n只有我自己才能汲取我的生命精華進行禁忌儀式！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59945] = {title = "剔除鷹身人", objective = "擊敗10名鷹身人和他們的盟友。", description = "鷹身人似乎與巨魔結盟了，許多鷹身人正在集結，準備攻擊我們的營地。\n\n我們必須削減他們的人數，讓他們無力消滅我們。\n\n也許他們會學到最好別來礙部落的事。", progress = nil, completion = "鷹身人似乎開始撤回棲息地了，這應該能讓我們有足夠時間阻止巨魔。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59946] = {title = "淨化圖騰", objective = "在5根鷹身人圖騰上放火。", description = "鷹身人在這個地區中設下邪惡的圖騰，藉此獲得更多力量。\n\n我們就必須摧毀這些圖騰，削弱對手的戰力。\n\n拿著這支火炬，燒毀你看到的所有圖騰。在戰鬥開始前就先削弱敵人，百利而無害。", progress = nil, completion = "圖騰被毀後，鷹身人流失了不少力量。希望他們經意識到部落可不是好惹的。", rewards = "遠征隊鎧甲束腰遠征隊布索遠征隊鎖甲護腰遠征隊皮甲腰帶遠征隊鎧甲束腰遠征隊鎖甲護腰遠征隊皮甲腰帶遠征隊布索您會收到：\n\n"}
MultiLanguageQuestData['tw'][59947] = {title = "給基地的訊息", objective = "返回部落營地，與督軍嚴斧交談。", description = "也許我母親是對的，我們合力對抗鷹身人，並且大獲全勝！\n\n我們帶赫伯特回到營地吧。\n\n阻撓巨魔、破壞他們復活那條龍的計畫，我們又更近了一步。", progress = nil, completion = "很高興看到你們全都平安歸來。你們親身體現了部落堅強的意志力！\n\n希望這位幽爆魔法的威力真的跟瘋狂的程度成正比。", rewards = "遠征隊鎧甲腿甲遠征隊布甲護腿遠征隊鎖甲護腿遠征隊皮甲腿甲遠征隊鎧甲腿甲遠征隊布甲護腿遠征隊鎖甲護腿遠征隊皮甲腿甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][59948] = {title = "心繫西行", objective = "到部落營地西邊與蘭娜‧喬丹會面。", description = "督軍嚴斧要我們先去西邊偵查，尋找下一個儀式的舉行地點。\n\n我們需要你幫忙，我已經死過一次了。我可不想再經歷第二次。", progress = nil, completion = "充滿死靈能量和蜘蛛的巨大坑洞。\n\n我原本很討厭蜘蛛。但我成為被遺忘者之後，就覺得蜘蛛也還好了。\n\n但不用說他們還是會把你殺死。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59949] = {title = "坑洞潛伏是何人", objective = "救出5名受困的遠征隊成員", description = "這個坑洞裡不斷湧出大量死靈能量。我猜這代表底下正在進行儀式。有儀式的地方就一定有祭品。\n\n你聽到了嗎？自從我縫上新耳朵後，我的聽力就是最棒的。\n\n聽起來像是有更多士兵被困在下面。大概被蛛網團團包住了。\n\n翁莎和我會…留在上面這裡，幫助逃出來的人。\n\n你跳下去，拯救被困在下面的人吧！", progress = nil, completion = "『大地之女』克蘭娜會是我們行動成功與否的關鍵，她與自然的連結能幫助我們瞭解巨魔究竟對這座島做了什麼。\n\n做得好，新兵。", rewards = "遠征隊布甲腕輪遠征隊鎧甲臂甲遠征隊鎖甲臂環遠征隊皮甲護腕遠征隊布甲腕輪遠征隊鎧甲臂甲遠征隊鎖甲臂環遠征隊皮甲護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][59950] = {title = "補給滿載", objective = "從補給官金哈克手中購買任何物品，並把你的東西賣給他。", description = "補給官金哈克成功從船艦殘骸中回收了一些補給品。\n\n在我們前去阻止這些儀式之前，我要你去看看他有沒有任何有用的東西。", progress = nil, completion = "希望你找到了需要的東西。\n\n索格在附近發現這個包包，想說或許能派上用場。", rewards = "您會收到：\n\n標準配發背包"}
MultiLanguageQuestData['tw'][59951] = {title = "德魯伊的形態", objective = "和附近的德魯伊之石溝通。", description = "謝謝你救了我，<name>。讓我協助你鑽研德魯伊之道。\n\n我逃離坑洞的時候，化身為一頭鹿。有個辦法你也能辦到。\n\n跟我來。附近有個古老的德魯伊之石，我們跟利用它與荒野溝通。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n旅行形態\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59952] = {title = "獵人的陷阱", objective = "在這個區域回收零件，來製作冰凍陷阱。", description = "如果你想當個真正的獵人，就必須學會如何設陷阱。\n\n你很幸運，我剛好是這方面的專家。\n\n首先你要用這附近收集的材料，製作合格的冰凍陷阱。\n\n赫伯特應該有寒冰微粒可以給你。其他材料就在附近找找。\n\n你需要使用陷阱，才能處理發生在營地附近的另一個問題。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n冰凍陷阱\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59953] = {title = "追捕潛獵者", objective = "在巨魔廢墟使用你的冰凍陷阱，將潛伏在營地裡的野獸引出來。", description = "既然做好陷阱了，現在我們來處理真正的問題。\n\n有一隻不是在這座島土生土長的奇怪生物一直在騷擾我們的營地。\n\n我認為，我們應該把牠抓起來，看看牠能派上什麼用場。\n\n在這片廢墟中設好冰凍陷阱，引牠出來。我們來看看究竟是什麼樣的動物。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n召喚寵物2\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59954] = {title = "法師的知識", objective = "在附近的湖底找回赫伯特‧幽爆的書。", description = "對於一個新手法師來說，你的技術算是很不錯。不過，還是有一些值得改進的地方。\n\n例如，在我看來，你很顯然對變形術一無所知。\n\n不然，你早就會在那些鷹身人攻擊我們時，對他們使用變形術！\n\n我們來糾正這一點。我的法術書中有變形術的詳細資訊…不過我的拘禁者把它丟進附近的湖中了。\n\n你可以幫我找回來嗎？對了，拿到的時候不要偷看。\n\n打開來看的話幾乎不可能有好下場。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n變形術\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59955] = {title = "綿羊的最佳用途", objective = "對赫伯特和蠻兵索格練習使用變形術。", description = "在還沒確定你可以正確使用變形術之前，我不能就這樣放你走。\n\n原因是，要是你出了差錯，很可能會把人變成完全不同的東西！\n\n要是發生那種事，我必須確定我人在現場記錄一切。\n\n讓我們看看…啊，索格應該可以！我評估實驗對象的功力可是無人能及的。\n\n我們開始吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59956] = {title = "武僧的專注", objective = "跟著阿波並和他一起冥想。", description = "你在與鷹身人的戰鬥中表現得很好。但你還需要更加精進自己才有可能克服接下來的挑戰。\n\n如果想要獲得更多力量，我們必須冥想並專注。\n\n來吧，我知道我們可以去什麼地方。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n幽冥掌\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59957] = {title = "最後一次比劃", objective = "與阿波比劃。", description = "我們在回到營地之前來場快速比劃吧。\n\n我感覺得到你體內散發出新的力量。我想要親身確認一下！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59958] = {title = "聖騎士的效忠", objective = "與聖騎士鬼魂交談。", description = "你在消滅不死族大軍的時候，有一個聖騎士的鬼魂跑過來…指名要找你！\n\n他飄到附近廢墟去了。\n\n你去看看那隻鬼想做什麼吧。我不太了解聖光…但至少我知道不可以忽略鬼魂的要求。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n聖盾術\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59959] = {title = "鑰匙在烙印者手中", objective = "找到鑰匙，釋放達瑞安。", description = "<達瑞安毫無反應。籠子鎖住了，看來也很難直接破壞它。\n\n或許鑰匙，就在他提過的那個「烙印者」手中。>", progress = "你願意聽聽我的提議嗎？", completion = "哎呀哎呀，今天真是處處驚喜！\n\n凡人，我倒是很好奇你為什麼要回來淵喉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59960] = {title = "尋覓蹤跡", objective = "使用騎士護符尋找達瑞安‧莫格萊尼。", description = "<你手中的護符變得滾燙。護符中的魔法隱約地拉動你的手掌。\n\n或許可以用伯瓦爾提過的魔法來找達瑞安‧莫格萊尼了。>", progress = nil, completion = "&lt;達瑞安被關在牢籠裡，看似昏迷不醒。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59961] = {title = "牧師末路", objective = "找到第一支遠征隊的新兵屍體。", description = "<name>，你受過牧師訓練，對吧？我有個不情之請。\n\n我在路上碰到幾個受傷的遠征隊隊員，我試著幫助他們…但他們實在傷得太重。\n\n你可以舉行儀式，讓他們安息嗎？\n\n他們的靈魂應該要能帶著榮耀安息。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n學習復活術\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59962] = {title = "希望永存", objective = "跟隨維娜里。", description = "凡人，所以你是來這裡找人的。嗯，好在我很聰明，我很有可能知道人在哪裡。\n\n讓我和你談筆交易吧。你手上的護符…有股奇妙的力量。\n\n你把護符給我，我就幫你找到這個瑪卓薩斯的男爵。\n\n然後你得離開，我沒有不禮貌的意思，但我真的想要保持低調。\n\n讓我自己來，事情會更順利。", progress = nil, completion = "跟上。我們時間不多。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59965] = {title = "復活新兵", objective = "對3名第一遠征隊新兵施放復活", description = "你必須對這些新兵使用復活，才能救他們。\n\n這個地方的死靈魔法正在拉扯他們的靈魂。\n\n動作快！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59966] = {title = "深入險境", objective = "跟隨維娜里前往墮滅堡。", description = "能和凡人當生意夥伴真讓人興奮！這個護符相當有趣。\n\n怎麼啦？喔對，那個你在找的男爵…\n\n嗯，我正好知道有個瑪卓薩斯督軍被關在墮滅堡的地下。光是聽到這地方的名字，你應該就知道那不是什麼吸引人的地方吧。\n\n我們最好不要引起閻獄之主士兵的注意，還好我有個派得上用場的東西。\n\n給我指示，我就會把我們隱蔽起來，不讓淵誓者發現。", progress = nil, completion = "我的父親…亞歷山卓斯‧莫格萊尼…灰燼使者。\n\n我…從沒想過能夠再見到他。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59967] = {title = "盜賊末路", objective = "運用潛行靜悄悄移動，並找出第一遠征隊的盜賊。", description = "秀嘉提過，遠征隊有個盜賊，名字叫德莉薩‧側襲。\n\n最後一個看到德莉薩的人說她朝西北方去了…那裡有個巨熊的巢穴。\n\n我們都不像你一樣能潛行。你去找找看德莉薩，帶她回來這裡吧。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n毒藥\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59968] = {title = "最致命的毒藥", objective = "殺死『硬漢』嘎葛魯克。", description = "你有毒藥了。現在該來解決巨魔。那蠢蛋的名字叫『硬漢』嘎葛魯克。\n\n他通常會在他們的堡壘中巡邏。我賭他一定是在找你的遠征隊！\n\n把刀刃淬毒，然後解決這頭怪物，讓他知道自己可不是不死之身！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59970] = {title = "術士的交易", objective = "調查第一遠征隊的術士屍體。", description = "偵查周圍區域的時候，我看到山坡上的橋附近有一座開啟的傳送門。這對我們來說肯定不妙。\n\n好像有個術士試著封印傳送門，卻失敗了。\n\n我知道你對這類的…異聞有所涉獵。你能夠運用你的知識，關閉傳送門嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n學會召喚虛無行者\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59971] = {title = "戰士末路", objective = "和暗槌大橋的奇怪鬼魂交談。", description = "你好，<name>！比起我們上次在船上比劃的時候，你又變得更強了。有一天，你或許會成為首屈一指的戰士！\n\n說到這個…\n\n我在北方的橋上遇見一個奇怪的鬼魂，要求跟一個真正的戰士商談。\n\n也許你可以去看看他想做什麼。\n\n他看起來沒有敵意…說不定他會願意幫我們。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n斬殺\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][59972] = {title = "耶爾瑪的最終處決", objective = "殺死『不死』耶爾瑪。你一定要使用斬殺，才能真的殺死他。", description = "你現在獲得我最強大的本領了，年輕的戰士。\n\n用它來了斷我吧！很久以前，我大著膽子違抗巨魔，他們就把我的靈魂困在此地。\n\n只有榮耀之死，才能讓我真心安息。\n\n這是我在來生與兄弟姐妹再度重聚的唯一方式。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59973] = {title = "超越死亡的連繫", objective = "在達瑞安釋放亞歷山卓斯時保護他。", description = "自從穿越到暗影之境以來，我一直專注在任務上，從來沒思考過我家人的靈魂也會在這裡。\n\n不管這個叫做瑪卓薩斯的地方到底是什麼，我希望它值得我父親效力！\n\n我們要救出他，<name>。我有…有很多事要和他說。", progress = nil, completion = "我對你只有無盡的感謝，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59974] = {title = "拯救了一個靈魂", objective = "到瑪卓薩斯的天選者家族找亞歷山卓斯‧莫格萊尼。", description = "維拉斯…這麼久以來…\n\n這可不能容忍，<name>。我們一定要為克利瑟斯復仇，要殺了他！\n\n他把你派去淵喉，一定是認為你回不來了。他低估了你，這是他致命的錯誤。\n\n和莫格萊尼一起去拿下維拉斯的頭。我會警告我們在統御者之座的部隊。", progress = nil, completion = "我不能讓這個傷口繼續潰爛下去，我要馬上灼燒傷口止血！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59975] = {title = "前往暗槌城塞", objective = "到暗槌城塞外與督軍嚴斧會面。", description = "最後的倖存者被關在巨魔北邊的城塞中。\n\n克蘭娜和赫伯特想出了計畫，能讓我們混進去。\n\n我們的一小批人會在北邊會合。你也要跟我們一起來。\n\n如果我們失手，巨魔就會讓那條龍起死回生。我們絕不能讓他們得逞！", progress = nil, completion = "隱約可以看到暗槌城塞就在前方。\n\n赫伯特提出的計畫實在是有點…不尋常。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59978] = {title = "就在他們眼皮下", objective = "讓赫伯特‧幽爆把你變身成一頭巨魔，然後偵察附近的巨魔城塞。", description = "我們需要進入暗槌城塞，救出最後一個生還者，並阻止這一切背後的巨魔死靈法師。\n\n赫伯特和克蘭娜會施放法術，讓你看起來像巨魔…然後你負責押送我們這些「囚犯」進去。\n\n我們勢單力薄，無法正面進攻，只能出奇制勝。\n\n等你準備好了，就跟赫伯特說一聲。", progress = nil, completion = "我們或許還有辦法救督軍雷行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59979] = {title = "正如待宰的巨魔", objective = "在暗槌城塞裡殺死8隻巨魔。", description = "情況比我想的還糟。巨魔料到我們進行救援行動。\n\n看來他們打算一邊攻擊我們的營地，一邊完成儀式。\n\n絕對不能讓他們得逞。擊潰巨魔，讓他們見識部落的力量！", progress = nil, completion = "打擊巨魔的戰力，應該能幫我們爭取到時間阻止他們的陰謀。", rewards = "遠征隊皮甲手套遠征隊鎧甲護手遠征隊布甲手套遠征隊鎖甲護手遠征隊皮甲手套遠征隊鎧甲護手遠征隊布甲手套遠征隊鎖甲護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][59980] = {title = "毀滅投石車", objective = "在暗槌城塞裡炸掉4台投石車。", description = "你有看到在這裡整齊排列的投石車嗎？\n\n看來巨魔正打算朝我們的營地亂扔一些可怕的東西。幸好我有備而來！\n\n寇爾克給了我一些炸藥，以防萬一。\n\n我原本想要留著回到奧格瑪之後，用來炸飛一些壞傢伙…不過好像得讓你現在用掉了。\n\n炸掉投石車，別讓他們有機會攻擊我們的營地！", progress = nil, completion = "做得好！你有沒有厲害到留了一些這要沒用到呢？\n\n…看來是沒有。唉唉，好吧！我還有很多方法能夠炸飛我的敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59981] = {title = "控制他們的石頭", objective = "從賈格納、烏格和古郎克手中取得結界石，然後使用結界石釋放督軍雷行。", description = "督軍雷行撐不了太久。很快，他的生命精華就會全部被吸乾。\n\n戈爾果斯有提到，巨魔用結界石來監禁他。\n\n你得去取得結界石，並且帶回來，用來釋放督軍雷行。", progress = "束縛我的就是那些結界石？或許就連巨魔都聽聞了我力大無窮的傳言！", completion = "謝謝你的馳援，不過就算救了我，也阻止不了巨魔。\n\n他們已經收集了完成儀式所需要的足夠精華！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59984] = {title = "地城：暗槌城塞", objective = "完成地城「暗槌城塞」。", description = "戈爾果斯打算讓一頭威力強大的龍死而復生，那頭龍叫做雷妮爾。\n\n他已經收集到足夠的生命精華，可以嘗試完成復活儀式…復活的雷妮爾，可能不會擁有完整的力量。\n\n除非殺死戈爾果斯，不然他絕對不會罷手！\n\n你必須突襲城塞、殺死戈爾果斯，別讓他完成儀式！\n\n我希望能跟你一起奮勇殺敵，但還無法從黑暗魔法中復原。", progress = nil, completion = "勝利屬於部落！我們是英雄和征服者！可以光榮回去奧格瑪了。", rewards = "遠征隊鎧甲頭盔遠征隊布甲兜帽遠征隊鎖甲頭盔遠征隊皮甲頭盔遠征隊鎧甲頭盔遠征隊布甲兜帽遠征隊鎖甲頭盔遠征隊皮甲頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][59985] = {title = "通往開始的結束", objective = "騎乘部落蠍尾獅返回奧格瑪。", description = "我們在這裡的工作結束了，回奧格瑪吧。\n\n等你準備好了，就跳上一隻蠍尾獅。\n\n我們該回家了。", progress = nil, completion = "能回到奧格瑪真好。\n\n我得馬上去跟大酋長報告，但我知道你這段時間可以做什麼…", rewards = "遠征隊布甲長袍遠征隊鎧甲護軀遠征隊鎖甲護甲遠征隊皮甲外套遠征隊布甲長袍遠征隊鎧甲護軀遠征隊鎖甲護甲遠征隊皮甲外套您會收到：\n\n"}
MultiLanguageQuestData['tw'][59986] = {title = "廣大的催化物質世界", objective = "辨識不同類型的催化物質", description = "催化物質具備各種不同的形態，目前，我先向你介紹其中兩種。\n\n加速催化物質可以加快復原過程，這顯然有助於管理我們能夠復原的靈魂數量。\n\n品質催化物質可以讓靈魂復原之後，提供更高等級的物質賜禮。\n\n等你找到兩種催化物質的樣本後，再回來找我。我已經等不及想知道你小小的眼睛夠不夠銳利，能不能發現它們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][59994] = {title = "信仰之躍", objective = "從塔上跳下來。", description = "我們一起思索文獻管理員遺言的含意：「勝利只屬於那些英勇殞落的人。」\n\n嗯。勝利很可能是指勝利之籍，那是這座塔中最廣為人知的收藏品。\n\n那本書是無價之寶，<name>。真的是價值連城。我們必須盡其所能找到它！\n\n不過，呃…你覺得「英勇殞落的人」指的是什麼？", progress = "你拿到了嗎？", completion = "就是這個…勝利之籍！瑪卓薩斯軍事史上最重要的一本兵書。\n\n它必須屬於我！呃，我們，我是說我們！", rewards = "冷酷處刑者踏靴屍體縫補師軟靴血肉建構者高筒靴欺詐密探足靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][59999] = {title = "林地重生", objective = "將女王的栽培園升級至等級2。", description = "這片園圃的規模已大不如前。雖然沒有全面枯萎，但這場乾旱還是對它造成了重大的影響。\n\n身為看顧它的園丁，我感受到雙重的罪惡感與羞愧。命運帶來如此重大的變故，我根本無能為力。\n\n但是命運也帶來了新生的希望，寄宿在你身上的希望。\n\n凡人，我懇請你到森林之心找出潔哈德，恢復我們失去的東西。\n\n正如受傷的魂靈需要重生，這座園圃也是。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60003] = {title = "英勇之舉", objective = "到訓練場救助6個受傷的驍士。", description = "我們上次面對大批天譴軍團已經不知道是多久前的事了。我們準備不足，難以應對這種規模的攻擊。\n\n雖然我們設法護送許多人抵達安全場所，但還有一些人在這場混沌之中負傷。\n\n搜尋訓練場，在大屠殺之中尋找任何倖存者。\n\n我們需要手頭的每一分助力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][60004] = {title = "英勇之舉", objective = "到訓練場救助6個受傷的驍士。", description = "天譴軍團許久沒有以如此大的陣仗攻打過來。我們的力量不足以抵擋此等規模的突擊。\n\n雖然我們護送許多人前往安全處，還是有人在混亂中受傷了。\n\n搜尋訓練場，找出混戰的倖存者。\n\n我們需要每一分助力。", progress = nil, completion = "我們會好好照顧他們。", rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][60005] = {title = "岌岌可危", objective = "到珊卓亞的守望找到杉尼寇斯。", description = "勇氣神殿絕不能陷落。\n\n所有琪瑞安都在這神聖的殿堂學習戰鬥。不只為了保護昇靈堡，也為了在穿過帷幕引渡靈魂時保護自己。\n\n立刻前往那裡，找到杉尼寇斯，他是勇氣楷模的效忠者。", progress = nil, completion = "儘管不是我希望看到的大批援軍，但我還是歡迎你成為我們的生力軍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60006] = {title = "刻不容緩", objective = "奪回珊卓亞的守望。", description = "在公平對決的條件下，我們的戰士能夠抵擋這源源不絕的瑪卓薩斯軍隊。\n\n但這不是公平對決，外來者。\n\n他們來勢洶洶，卻毫無預警，毫無原由。我們只能倉促應戰。\n\n絕不能允許他們繼續前進一步，一切到此為止。", progress = nil, completion = "我們已經奪下一個戰略要地，不過還有很多事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60007] = {title = "逞凶鬥狠", objective = "取回靈魄匯流裝置、永恆裝甲及御靈共鳴器。", description = "我可以重建這個巨像的核心系統，不過有些地方根本無法修復。幸好，這裡的百衛機兵數量夠多，我相信我們可以變通一下。\n\n該來換上替換零件了！\n\n我需要靈魄匯流裝置為系統充能，還需要一些永恆裝甲保護它的核心，最後需要御靈共鳴器讓它動起來！\n\n剩下的事交給我，快點去找吧！", progress = "你拿到零件了嗎？", completion = "動作真快！非常好，真的非常好！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60008] = {title = "大解八塊", objective = "殺死傀儡家族的部隊。", description = "我們會讓這些瑪卓薩斯叛軍嚐嚐背叛的代價。\n\n北方地帶已經被傀儡家族佔領，瑪卓薩斯最驍勇善戰的戰士都出自這個家族。\n\n他們今天根本毫不留情，那麼我們也不會憐憫他們。我們會並肩作戰，殺進殺出，直到這片神聖土地得到淨化為止。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60009] = {title = "留得青山在", objective = "援救6名琪瑞安俘虜。", description = "我們的一些兄弟還活著！\n\n儘管許多人早已在第一次攻擊中喪命，但他們似乎急著俘虜所有倖存者。我不知道他們有什麼用意，不過他們對屍體很有研究，我們必須做最壞的打算。\n\n有些人已經被帶到上方的亡城，不過有些人還被關在地上的牢籠裡。盡量救出所有人。", progress = nil, completion = "你是真正的盟友，外來者。謝謝你。", rewards = "晉升防衛者紋飾您會收到：\n\n"}
MultiLanguageQuestData['tw'][60013] = {title = "助憶事項", objective = "使用御靈者寶庫的傳送板。", description = "根據你著急的語氣，可以推斷出你希望離開。\n\n我會讓你盡快離開這裡。前廳有個傳送板，我會確保前廳在你離開之後，再次封閉起來。\n\n請跟我來。", progress = nil, completion = "我們必須加快腳步，要讓御靈者知道這裡發生的事。", rewards = "您會收到：\n\n"}
