MultiLanguageQuestData['tw'][60041] = {title = "製造憎惡體", objective = "協助拉桑為寇迪製造新的傀儡軀體。", description = "我們必須動起來，這裡的每個靈魂都需要一具身體。\n\n我們已經備好零件，可以幫寇迪打造身體了。寇迪是很厲害的拾荒者，把他重新打造出來，我們就能輕鬆找到更多傀儡零件。\n\n你願意幫我重新打造他嗎？", progress = nil, completion = "我們成功了，寇迪又重生了！", rewards = "您會收到：\n\n延展血肉"}
MultiLanguageQuestData['tw'][60042] = {title = "你有什麼要求嗎？", objective = "聽取現身的靈魄對傀儡的要求。", description = "寇迪的成功是個好的開始，以後一定有更多成功案例！\n\n解放的靈魂在這裡現身後，與它們交談，聽取它們對新的傀儡軀體的要求。我們很快就需要製作一大堆新傀儡了！", progress = nil, completion = "好多強大的靈魂，我們必須馬上開工。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60043] = {title = "天降正義", objective = "毀掉5枚瑪卓薩岩核心。", description = "只要藩侯的水晶繼續讓天空充滿破壞性的爆破，我們在上面的軍隊就沒辦法完整降落到這個區域。\n\n而就算是現在，藩侯的邪惡屠夫也還持續從昇靈堡劫持而來的琪瑞安身上，抽取殘餘的靈魄。我們得馬上出擊。\n\n我在你身上灌注勇氣之焰，讓你可以標記水晶。標記之後，我就可以在遠方摧毀它們。", progress = nil, completion = "你又為這裡立下一個大功勞。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60044] = {title = "充能刀刃", objective = "在縫合場殺死敵方傀儡，為你的符文刃充能。", description = "有這些重戰士轟炸我們，根本無法前進！我剛剛朝最近的目標發動一波攻擊，但傳統武器對他們的灌魔皮革發揮不了作用。\n\n還好，我有個點子。\n\n你那把符文刃沒辦法直接解決他們，但假如你能淨化珈爾瑪強化的物質，再用符文刃吸收它們的精華的話…", progress = nil, completion = "這或許沒用…但這也可能是我們唯一的獲勝機會。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][60048] = {title = "縫合時間", objective = "將憎惡體工廠升至第1級。", description = "只要有足夠資源，我們就能打造一支傀儡大軍，這將會是暗影之境前所未見的勁旅。\n\n拜訪阿卡迪雅‧莫亞，看看你能不能找到我們需要的資源。", progress = nil, completion = "你已經取得所有我們需要的資源了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60049] = {title = "聽候你的差遣", objective = "回去統御者之座找德拉卡女爵。", description = "我想我應該誇獎你。你的表現真的超乎我的預期。\n\n拉桑或許有點感情用事，但他是對的。這個地方可以作為我們的新家，我們可以在這裡為你解救的靈魂打造新的身體。\n\n告訴德拉卡女爵，艾曼妮公主及屠夫區的傀儡願意向她效忠！只要她需要，我們隨時都能貢獻一己之力。", progress = nil, completion = "做得好。艾曼妮和她的傀儡將會是強大的盟友。\n\n不過，他們需要你的協助，才能徹底發揮潛力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60050] = {title = "西部前線的麻煩", objective = "和琴西亞一塊飛行，到縫合場向亞歷山卓斯報到。", description = "灰燼使者和你的瑪卓薩斯夥伴在西門急需增援。他們快要擋不住了！\n\n珊卓亞和我的族人會從這邊派出增援，並朝著珈爾瑪推進。我們要快點與莫格萊尼會合，只要有一邊的側翼崩潰，我們就不可能獲得勝利。", progress = nil, completion = "我很高興琴西亞能這麼快就找到你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60051] = {title = "技藝精湛的大師", objective = "到餘燼區找勞倫特。", description = "如果希望傳送網路再次正常運作，就必須讓主宰的鏡子製作者為我們服務。\n\n謠傳，有這麼一個商人因罪流放至餘燼區。我相信，應該不需要花太多功夫，就能說服他加入我們陣營。\n\n再次進入餘燼區，找到主宰的鏡子製作者。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60052] = {title = "雙重攻擊", objective = "使用御靈共鳴器炸掉12個祭儀家族士兵的屍體。", description = "祭儀家族佔領了神殿南側。與傀儡家族不同，他們在戰爭中的優勢是源源不絕的復活者大軍。\n\n幸好，我們取回的御靈共鳴器能夠破壞這個優勢。\n\n我們殺進他們部隊的時候，用共鳴器炸掉他們的屍體。能量會使他們魂飛魄散，防止他們又站起來戰鬥。", progress = nil, completion = "共鳴器正在全速運轉，我們的敵人也死傷慘重。太棒了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60053] = {title = "清晰晶亮", objective = "利用死靈抽取器為靈魄匯流裝置充能。", description = "這個靈魄匯流裝置已經耗盡所有靈魄！只是一塊又大又重的金屬！\n\n這當然不是你的錯，完全不是。但我們必須為它充能！\n\n瑪卓薩斯那邊有抽取器，是巨大的綠色水晶，非常顯眼。他們利用水晶從死去的琪瑞安身上抽取靈魄。壞到不行！\n\n我們可以利用它們為裝置充能，然後就能讓這個巨像再次運轉！", progress = nil, completion = "還沒完全充能，不過就快了！可能需要停用幾個安全功能…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60054] = {title = "最終倒數", objective = "阻撓『收割者』亞瑪斯，直到巨像完全充能為止。", description = "如果在巨像完全充能之前，死靈法師的爪牙傾巢而出，我們就會死，毫無疑問。\n\n我們必須吸引他的注意，直到米卡尼寇斯的工作完成為止。\n\n他認為自己勝券在握，我們只是任他宰割的魚肉。我們可以利用他的傲慢，為自己爭取寶貴的時間。\n\n希望一切順利。", progress = nil, completion = "我們現在已經沒有回頭路了，外來者。", rewards = "指引之光肩冑指引之光肩鎧指引之光肩墊指引之光肩衛您會收到：\n\n"}
MultiLanguageQuestData['tw'][60055] = {title = "勇氣之刻", objective = "與杉尼寇斯一起對抗『收割者』亞瑪斯。", description = "我不知道在裂谷的另一側會遇到什麼情況，外來者。御靈者的恩典在上，我希望我的楷模還活著，但我擔心他已遭遇不測。\n\n我們會共同面對這巨大的未知，就像一起讓這個瑪卓薩斯怪物安息一樣。身為琪瑞安，就是要跟隨晉升之路，無論情況有多麼險惡。\n\n不管發生什麼事，你今天已經得到我不朽的敬意。", progress = nil, completion = "杉尼寇斯…走了…對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60056] = {title = "循道而行", objective = "將瑪卓薩斯進攻昇靈堡的事情告知奧睿博司的塔因納拉。", description = "瑪卓薩斯必須為他們對昇靈堡犯下的罪行負責。正義必須得到伸張！\n\n我們必須前往奧睿博司，與「榮耀之聲」塔因納拉交談。將今天發生的事告訴她。告訴她，琪瑞安不會對這場侵略袖手旁觀。\n\n阿特米德會通知御靈者，而我的兄弟姐妹一定會整裝備戰。\n\n絕對不能放他們通過。", progress = nil, completion = "我知道你為何而來。這位琪瑞安已經透露了一切。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60057] = {title = "死靈戰地：神聖楷模的誓約", objective = "到死靈戰地擊敗『收割者』亞瑪斯和『霜縛者』納爾索。", description = "強大的勇氣楷模珊卓亞，她是晉升者中最厲害的戰士。但就算是她，面對瑪卓薩斯最強大的軍隊，也恐無力回天。\n\n現在，你的命運與她交纏在一起。你必須召集你的盟友，勇闖死靈戰地，確保亞瑪斯和納爾索無法安然無恙地返回他們的國度。\n\n願御靈者助你將刀刃插入他們的心臟。", progress = nil, completion = "你在勇氣神殿的事蹟已經傳遍整個昇靈堡，&lt;name&gt;。珊卓亞派人傳信息來，表示你的英勇行為值得賜予豐厚獎勵。", rewards = "輝煌衣飾輝煌背心甲輝煌護胸輝煌外套您會收到：\n\n"}
MultiLanguageQuestData['tw'][60058] = {title = "征服者的獎勵", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60060] = {title = "鏡子同調：尊殞村", objective = "進入位於尊殞村的鏡子。", description = "連接罪殞城與尊殞村的鏡子已經大致完成校準。不過，它尚未進行同調。\n\n同調過程相當簡單，你只需要前往鏡子的所在位置，然後穿過鏡子一次，回到罪殞城，之後，你就能透過兩面鏡子瞬間移動。", progress = nil, completion = "做得好！鏡子同調完畢，你可以隨意使用了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60061] = {title = "強韌如絲", objective = "到輕絲崖殺死攻擊者，解救管理員，並且孵化絲行者幼蟲。", description = "我們是亞登曠野的產絲中心，不過我們現在卻無法產絲！\n\n我們的林地被木魈和這些怪異的…變形生物徹底佔領了。\n\n紡絲的絲行者是非常脆弱的生物，牠們需要和平、安靜的環境，還要一點音樂讓牠們保持愉悅！不過現在這裡到處都是這些怪物，牠們覺得壓力超大。\n\n拜託，你可以進去那裡，消滅那些壞蛋嗎？幫助我們再次生產出絲線。", progress = nil, completion = "謝謝你！我們非常感激你幫忙殺死那些惡棍，拯救我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60062] = {title = "壞掉的豎琴", objective = "尋找破損的豎琴組件。", description = "<壞掉的豎琴掉在地上，而且有些部件不見了。\n\n你或許可以找到更多部件，找人修好它。>", progress = "我失去豎琴了！那些可怕的生物把它搶走，還把它弄壞了。", completion = "你找到我的豎琴了！還找到遺失的部件。只要一下子，我就能修好它。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60063] = {title = "絲行者之歌", objective = "為絲行者彈奏豎琴，收集牠們的絲線。", description = "好了，豎琴修好了。我傷得太重，沒辦法去到絲行者那裡，不過你很強壯，你可以幫助牠們。\n\n我們珍貴的絲行者都在懸崖的另一端。只要看到絲行者，就為牠們彈奏豎琴，牠們就會紡絲給你。不過記得先確定附近沒有會讓牠們感到緊張的東西！\n\n如果你需要迅速移動的手段，可以拿一個旁邊那邊的絲線發射器。對準你要去的目的地，它就會發射絲線，把你拉去那裡！", progress = "你幫助那些可憐的絲行者冷靜下來，並且取得牠們的絲了嗎？", completion = "做得太好了！相信絲行者一定都很喜歡你彈奏的歌曲。你看起來就是一個很有藝術素養的人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60064] = {title = "拯救老格蒂", objective = "殺死千面諾以蘇", description = "我們必須找到老格蒂！她是絲行者的育母，也是我們最可靠的產絲來源，我們不能失去她。\n\n不過我沒辦法去找她，看看她是不是沒事。她通常都會待在懸崖頂端的最高點。你可以上去那裡，確認她的安危嗎？\n\n如果她遭遇不測…就請你迅速確實為她伸張正義。", progress = nil, completion = "&lt;老格蒂死於恐懼，\n\n不過這隻小小的絲行者幼蟲開心地朝你扭動。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60065] = {title = "一絲希望", objective = "將小格蒂帶去給莉莉西索。", description = "<小格蒂一臉希冀地看著你。或許你可以將她送到安全的地方。>", progress = nil, completion = "老格蒂…死了？\n\n但你居然找到她的寶寶！謝謝你，非常謝謝你把她安全地帶離那裡！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60066] = {title = "亞登曠野的絲線", objective = "把小格蒂送到森林之心。", description = "我們或許還是沒辦法穩定為亞登曠野供應絲線。不過還是有些事能做。\n\n請把小格蒂和你從其他絲行者身上收集的絲線送回森林之心。在那裡，小格蒂會很安全，說不定長大之後，還會變成出色又美麗的絲行者，就跟她母親一樣！", progress = nil, completion = "謝謝你送來這批絲線！但是…你似乎還帶了其他東西。\n\n這隻絲行者幼蟲一定會很安全，我保證。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60067] = {title = "正義追擊", objective = "擊敗藩侯珈爾瑪。", description = "德拉卡準備好要對珈爾瑪釋放亡城的力量了。我們只要幫她爭取時間，讓她對準武器！\n\n我們現在做的事情，都是為了大家。昇靈堡和瑪卓薩斯雙方都因為這些怪物，失去了許多東西。\n\n珈爾瑪不是個可以輕鬆打敗的敵人，不過聯合我們所有的部隊，最終就能制裁他們！", progress = nil, completion = "那些死去的人終於可以瞑目了。", rewards = "您會收到：\n\n名望名望"}
