MultiLanguageQuestData['tw'][60230] = {title = "人手越多越好", objective = "聽取現身的靈魂對傀儡的要求。", description = "我們在這裡打造軀體的消息已經傳開了，新的靈魂紛紛前來要求加入我們！\n\n聽取它們對新傀儡軀體的要求。看看我們能不能也幫它們打造新的傀儡！", progress = nil, completion = "好多靈魂，我們有很多工作要做！", rewards = "您會收到：\n\n"}
