MultiLanguageQuestData['tw'][60574] = {title = "搖晃蘑菇", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60575] = {title = "一肚子的妖精", objective = "從吞咬的多頭樹妖內體解救16個野性種子看管者。", description = "在靈魄乾旱期間，當地的植物開始變得狂暴。\n\n看來它們把原本在這裡負責照料野性種子的年幼妖精都吃掉了。\n\n至少現在知道他們究竟跑到哪裡去了。\n\n喔，別擔心。這種事並不是第一次發生，我們能在那些怪物體內存活好一段時間。\n\n帶上我的匕首，用它切開那些大型怪物，解救其他的野性種子照料者。", progress = nil, completion = "幹得好，這應該有助於讓靜謐水塘恢復正常。\n\n我承認，在我找不到看管者的時候，還以為他們都完蛋了。幸好他們只是被當地的植物吃掉了。", rewards = "林地看守者束腰靈魂看管者之索夢棘腰鍊星蔽腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][60577] = {title = "貪食靈魄果", objective = "從吞噬之花身上回收25個靈魄果。", description = "我必須為靜謐水塘的亂象道歉。這裡平常是個相當和平的地方。\n\n野性種子看管者告訴我，你看到的那些植物到處遊蕩，還吃掉了準備用在特那瓦勒的所有靈魄果。\n\n你可以從那些植物體內取得靈魄果嗎？\n\n我們的野性種子急需那些靈魄。", progress = "你找到靈魄果了嗎？雖然有點黏黏的，不過還是能用。\n\n相信我，靈魂不會在意，只要能獲得靈魄就好。", completion = "靈魄果！現在是靈魄乾旱期，每一點靈魄都彌足珍貴，不能浪費。謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60578] = {title = "夢旅者的幻象：背叛", objective = "與夢旅者遭人背叛的幻象搏鬥。\n\n如果離開了幻象，與夢壇盆地的夢旅者的幻象傳送門互動，就能再次進入。", description = "我在靈魂的幻象中感應到，她正在與遭到深深背叛的記憶搏鬥。\n\n她視為兄弟的親近之人，變成她的敵人。\n\n前往盆地的第二座夢壇，協助化解這個夢魘帶來的痛苦。", progress = nil, completion = "老朋友以這麼可怕的方式背叛你，這是多麼令人心痛的事。\n\n但我們已經快要成功了，很快就能安撫野性種子內的靈魂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60585] = {title = "木魈暴動", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60594] = {title = "與眾不同的靈魂", objective = "與織夢者一起去特那瓦勒，將靈魄注入野性種子。", description = "你為特那瓦勒貢獻良多。我必須把這些靈魄帶去給一顆新生的野性種子。\n\n我很希望你跟我一起去。這理所當然，畢竟這些靈魄果是你找回來的。\n\n我都為你感到迫不及待了！我們走吧。", progress = nil, completion = "織夢者的身體散發出星光，既璀璨又祥和。\n\n然後…兩河交會，形成草木茂盛的三角洲。野性種子和凡人，兩者都是初來乍到。靈魂與命運牽起兩者的羈絆。\n\n樹枝已經很久沒有見過這種事了。曠野會持續關注。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60597] = {title = "小果姆飼育區的麻煩", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60600] = {title = "準備迎接凜冬女王", objective = "從月莓女士那裡接受亞登曠野的精華。", description = "特那瓦勒已經準備好迎接凜冬女王的到來！這都要歸功於你。\n\n你已經做得比當初說好的還要多…我卻還沒履行我的承諾。\n\n身為一個飛靈，這是絕不容許的事！要是其他人知道我沒有信守承諾，他們會怎麼看我？\n\n拜託，讓我補償你一下吧。我或許沒辦法把你的訊息傳達給女王，不過我準備了一個特別的驚喜，希望你笑納！", progress = nil, completion = "暗影逐漸籠罩心木林地。無形的事物在黑暗之中蠢蠢欲動。", rewards = "您會學到：\n\n死亡代價\n\n下列法術會施放在您身上：\n\n召喚歹徒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][60601] = {title = "暗翼演練", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n感激禮賜"}
MultiLanguageQuestData['tw'][60602] = {title = "秘密任務", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60605] = {title = "爍鰭鱗片", objective = "在北風凍原讓莫戈莫戈大王看看鱗片。", description = "<魚人跑開時，一片色澤明亮的鱗片掉落在地上。它完全不像你在北裂境看過的任何魚人。\n\n或許莫戈莫戈大王對這個新品種有更多瞭解？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n水下呼吸藥劑"}
MultiLanguageQuestData['tw'][60606] = {title = "歡迎爍鰭", objective = "收集10塊肥美的蟹肉並送給風險海灣的爍腹。", description = "先處理最重要的事情：他們可能餓壞了。和其他地方比較起來，在這塊凍土生活沒那麼愜意，就連最老練的魚人也有可能餓肚子。\n\n我們得餵飽他們，但也要協助他們自行找到食物。\n\n他們已經在注意你了，所以在那個發現魚人的區域附近搜尋食物來源，並教他們如何狩獵。然後把肉帶給他們的領袖…找那個塊頭最大的就對了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60609] = {title = "誰吞噬了吞噬者？", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60614] = {title = "大獵物任務", objective = "收集一塊厚脂肪並帶給風險海灣的爍腹。", description = "<爍腹在沙上畫出圖案。\n\n從魚人畫出的外型看來，應該是頭大海豹。他指著圖案，然後比了比上方，表示這頭生物一定在水面的某處。\n\n然後魚人在沙上挖出一個小小的淺坑，並指了指它幾次。>\n\n姆格！姆格！咕姆。\n\n<他滿腔期待的點了點頭。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60615] = {title = "浪潮的先知", objective = "將鯨脂帶給爍鰭神諭者。", description = "<爍腹指著船的另一邊。他要你把脂肪帶給某人。>\n\n呣格呣格爾。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60616] = {title = "深海珍珠", objective = "收集巨大珍珠並送給爍鰭神諭者。", description = "<神諭者在沙上畫出圓圈，然後指向深處。在她指的地方有個看起來圓滾滾的東西，可能是枚珍珠或是石頭？\n\n神諭者要你在離開之前稍等一下。她的雙手在身邊瘋狂的揮動，然後放在她的嘴巴下方，模仿著一對利牙。\n\n你把這個動作視為警告，或許在冰寒黑暗的水中，有什麼東西正在等著你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60617] = {title = "訓練師的測試", objective = "在寵物對戰中擊敗訓練師葛爾爾林。", description = "<神諭者不再凝視著珍珠，轉過頭來看著你。她似乎陷入沉思，直直的瞪著你，眼睛眨了幾下。\n\n最後，她點了點頭。\n\n神諭者指著你，然後指上方。她將一隻手壓到離地不遠之處，表明某種像寵物大小的東西。\n\n你猜這可能是個考驗你和戰寵關係好壞的測試。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60619] = {title = "把它包起來", objective = "收集一根溫熱的海草莖、一根幼嫩的海草莖和一棵球狀的海草莖，然後交給爍鰭神諭者。", description = "<神諭者看來對新蛋的出現十分興奮。你有一種感覺，這枚蛋對這些魚人十分重要。他們可能沒剩多少蛋了。\n\n神諭者在你面前揮動一小片海草，要你把目光移向一株尚未成熟的植物幼苗。\n\n她用海草把蛋的一小部份包了起來，然後指著你，再指回包裏用的海草。\n\n看來這枚蛋需要用更多未成熟的海草莖包覆。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60620] = {title = "最小的守護者", objective = "殺死偉大的呣阿金再回到爍鰭神諭者身邊。", description = "<神諭者拍拍你的肩，似乎對你目前的一切作為感到很滿意。\n\n她豎起一根手指，然後把雙掌張得大大的，發出一道像…吼聲的魚人吼聲。\n\n她指向外面，然後指著你，接著指向你的武器，正經八百的點了點頭。\n\n一定還有一場試煉在等候你。這看來應該是力量試煉。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n格哩莫有裂縫的蛋"}
MultiLanguageQuestData['tw'][60621] = {title = "大敵當前", objective = "到冬日窪地找到艾利歐德樹林長。", description = "洛克隆在這裡。\n\n我從爍光瀑布一路追著他。然後我看到佐司特打算襲擊部隊的側翼。\n\n我敢說，他們被反咬一口的時候，一定很訝異。\n\n<克芮恩露出凶狠的微笑。她拿起武器，向在場的所有人大聲宣告。>\n\n各位獵人，跟我來！我們奮勇當先，保衛林地！斬草除根，不留活口！", progress = nil, completion = "這場攻擊…他們就好像被什麼力量驅使著！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60622] = {title = "占卜者之眼", objective = "從淵喉的『占卜者』李羅克身上取得占卜者之眼。", description = "要屏蔽淵誓占卜者的監視，需要施展強大的反制魔法。\n\n而主要施法材料是什麼呢？就是發光的眼睛。必須將冥想中的占卜者搖醒，立刻從他們的腦袋上挖下來。\n\n在我們說話的時候，占卜儀式已經開始了。當然，你必須拿回完好無損的眼睛，才能獲得獎勵。\n\n建議你挖眼睛的時候，拿捏一下力道。", progress = "如何？你拿到了嗎？真的完好無損？", completion = "你覺得他有看見這種下場嗎？\n\n我試了一下凡人的幽默。你可以視情況自行笑出來。", rewards = "您會收到：\n\n不羈魂靈強大的不羈魂靈勇武魂靈強大的勇武魂靈強大的盡責魂靈盡責魂靈高傲魂靈強大的高傲魂靈沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][60623] = {title = "啊！真正的怪物！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60624] = {title = "前往心木林地", objective = "騎乘雄鹿前往心木林地。", description = "痛苦與恐懼的風暴驟降於心木林地。希瓦爾拚了命要逃離災難。\n\n騎著雄鹿逆流而上。安撫恐怖的洪水，成為即將淹沒之人的救贖。\n\n快點。時間緊迫。", progress = nil, completion = "我們不能放任心木林地不管。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60628] = {title = "失蹤的獵人", objective = "找到金克拉、瑟林凱、榮達及亞拉隆。", description = "奇怪的生物潛藏在林地外圍，他們既可怕又醜陋。\n\n我不相信他們是亞登曠野的原生物種。\n\n不過，不管他們用什麼方式入侵，一定要將他們全部消滅。\n\n我派了我手下最厲害的獵人去殺他們，但還沒有人回來。去查明他們被什麼事耽擱了。", progress = nil, completion = "只剩下亞拉隆和盧美拉倖存？其他人都倒下了？\n\n&lt;克芮恩憤怒到渾身發抖。&gt;\n\n我會親自帶回他們的遺體。絕不能放過殺害他們的人，一定要為他們報仇！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60629] = {title = "廢物利用", objective = "殺死染疫者，取得他們的武器。", description = "曠野獵者在赫恩勛爵的領導下，為凜冬女王效命。我們是身手矯健的戰士、獵人和追蹤者。\n\n但我們無法在彈盡援絕的情況下戰鬥。這裡的樹林長通知我，他們的運送遇到很大的阻礙。\n\n我等不了了，我們需要裝備，現在就要。\n\n看看你能不能試著回收一些東西。壞掉的武器只要修一修，就能繼續使用。", progress = "你有找到任何有用的東西嗎？", completion = "沒想到你居然能找到這麼多武器。\n\n太奇怪了。我們怎麼會有這麼多武器落入他們手裡？\n\n&lt;克芮恩一臉困惑。&gt;\n\n我發誓，它們會再次用來對付我們的敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60630] = {title = "圖騰滅絕", objective = "破壞邪惡圖騰。", description = "我可以聞到敵人的黑暗魔法正在扭曲空氣、混亂我的心智。他們一定有什麼企圖，才會將邪惡的力量帶進亞登曠野。\n\n如果你看到他們的圖騰，立刻全部破壞掉。\n\n砸爛東西總是能讓我心情好一點。你不覺得嗎？", progress = nil, completion = "事已至此，這不再只是公事，而是我私人的狩獵。\n\n我們要從亞登曠野抹除怪物的存在。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60631] = {title = "大問題，小沃爾凱", objective = "與克芮恩一起殺死染疫者。", description = "亞拉隆的報告跟我看到的情況相符。敵人太多，曠野獵者勢單力薄，無法光靠我們戰勝。\n\n幸好，我強烈希望親自出手解決他們，為我死去的獵人報仇。\n\n走吧，讓那些怪物見識自然的怒火。", progress = nil, completion = "我們殺了很多敵人，但他們卻源源不絕。我們要直搗邪惡的核心，然後把它撕成碎片。\n\n要不然，邪惡可能很快就會擴散到整個亞登曠野。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60632] = {title = "我認得你", objective = "擊敗『獵人』洛克隆。", description = "這個聲音…我以前聽過。不過它現在被恨意扭曲了。\n\n他在追殺我們。\n\n但我可不是獵物。我不會讓他殺死我的朋友還自鳴得意。那不是曠野獵者的處事之道。\n\n雖然他會把我們引誘到對他有利的地方，我們還是要與他一戰。\n\n而且我們會贏。你願意幫我嗎？", progress = nil, completion = "克芮恩要狩獵自己人，內心一定百感交集…但她的判斷是對的。不除掉洛克隆的話，對整個森林都是危害。\n\n真是悲慘的下場…對於被附身者，和必需狩獵他們的人都是。", rewards = "星蔽肩墊林地看守者重肩甲靈魂看管者披肩夢棘肩甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][60637] = {title = "昔日朋友的末路", objective = "到心木林地殺死8個被附身的生物。", description = "心木林地被選上，貢獻出了靈魄，好讓其他林地能夠繼續存在。\n\n但是…突然有很多妖精都戴上了面具。很快就變成大家都戴上了。\n\n我不知道他們都怎麼了，但他們很顯然對我們抱有惡意。求求你…你得…\n\n他們已經不是我曾經熟悉的好友了。", progress = nil, completion = "謝謝你。我很努力試著想要拯救他們…只是一旦戴上面具，一切就無可挽回了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60638] = {title = "回收野性種子", objective = "到心木林地取得6枚乾枯的野性種子。", description = "我在心木林地的其中一個工作是照料野性種子。\n\n有些被選擇帶回特那瓦勒。不過現在蒙面妖精正在吸取它們的靈魄！\n\n我們必須拯救僅剩的種子。求求你，幫忙取回那些還活著的野性種子。\n\n寄身其中的靈魂還有重生的機會，我不會讓他們就此凋零！", progress = "我們要分頭行動，盡可能多拯救一些野性種子。", completion = "你找到更多野性種子了！它們非常虛弱…我不能看著它們這樣受苦。\n\n我們必須結束這一切，盡快帶它們去特那瓦勒。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60639] = {title = "林地之心", objective = "將林地之心送到特那瓦勒。", description = "我們放棄這片林地，任其凋零時，我們原本應該把林地之心帶去特納瓦勒。\n\n但蒙面妖精卻在那之前就展開突擊。他們的目標一定就是林地之心！\n\n林地之心中蘊藏的充沛靈魄，應該要拿去拯救其他林地。那是不能失去的重要資源。\n\n你能取回它嗎？我必須去找我們的其中一個治療者，叫寇任斯。他能幫我們找到可能還活著的人。", progress = nil, completion = "寇任斯…死了？林地之心也被奪走了？\n\n那麼…那麼我們還有很多事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60640] = {title = "林地茁壯", objective = "將女王的栽培園升級至等級3。", description = "林地欣欣向榮，我的凡人朋友，不過其中還有一點成長空間。\n\n有了足夠的靈魄，林地就能同時滋養更多野性種子。每一個都是可能永遠消失的靈魂。\n\n再去找潔哈德談話，繼續進行栽培園的重生。", progress = nil, completion = "你的努力讓林地重獲新生，隨之而來，也有無數靈魂得到幫助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60641] = {title = "林地開花", objective = "將女王的栽培園升級至等級4", description = "栽培園綠意盎然、健康茁壯。現在，必須讓它再次百花盛開。\n\n儘管這需要很多的靈魄，不過每一個靈魂從栽培園重生的靈魂，都會以十倍報答你的恩惠。\n\n跟潔哈德商討，讓栽培園的進一步擴大。", progress = nil, completion = "這片林地對你感激不盡。現在有更多靈魂能重返循環。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60642] = {title = "林地繁茂", objective = "將女王的栽培園升級至等級5", description = "多虧你的努力，栽培園才有機會恢復往日的榮景。\n\n數紀元以前，這片林地是只讓死亡時受到創傷的靈魂休養生息的地方，它們需要細心照料才能重生。\n\n這裡原本不常使用…但現在，卻對循環的延續不可或缺。\n\n告訴潔哈德時機已經到了。為了亞登曠野的未來，女王的栽培園必須繁盛起來。", progress = nil, completion = "這個栽培園，還有其中收留的靈魂，永遠欠你一份情。\n\n謝謝你，淵喉行者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60644] = {title = "引出黑暗", objective = "在迪崔索斯引出凋零的存在並擊敗它。", description = "現在我們有了這把匕首，接下來我們要凝聚所有人的意志力，才能打斷它和牛頭人酋長之間的連結。\n\n珍娜、安杜因和我必須各司其職守住貝恩的靈魂，所以在刀刃破碎之後，只能仰賴你去對付它釋放出來的東西。\n\n你願意接受這個任務嗎？", progress = nil, completion = "多虧你的努力，否則我的身體和靈魂會永遠被困在這個被遺忘的地方。\n\n我欠你一條命，&lt;name&gt;，而且我會奮戰到最後一口氣，來回報這個恩情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60645] = {title = "巨怪追尋者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60646] = {title = "悲慘事業", objective = "拾取10個悲慘精華並摧毀悲慘魂管。", description = "淵誓者在收割流淌在靈魂之河果戈亞中的靈魂所承受的痛苦。\n\n原因是什麼？我還不知道。但我們勢必要阻止他們。\n\n摧毀他們存放痛苦的魂管，幫我取回一些他們加工的樣品。\n\n如果加以研究，或許我能找出他們的目的。", progress = "你終止他們的痛苦了嗎？", completion = "你身負重擔，不過今天，你讓身陷詛咒的靈魂得到救贖。", rewards = "您會收到：\n\n不羈魂靈勇武魂靈盡責魂靈高傲魂靈沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][60647] = {title = "回收靈魄果", objective = "從被附身的人身上回收25個靈魄果。", description = "林地的樹林長也戴上了面具。他恐怕會把林地之心的靈魄吸得一乾二淨！\n\n那些靈魄應該要用在森林的其他林地。如果失去靈魄…心木林地的犧牲就毫無意義了…\n\n我們必須清出通往蒼霧沼澤的通道，快點找到樹林長，不然一切就太遲了。\n\n很多蒙面妖精都偷了心木林地的靈魄果。我們必須沿路回收才行。\n\n現在是靈魄乾旱期，每一點靈魄都珍貴無比。", progress = "我們不能再讓被附身的人從我們身邊奪走任何事物。", completion = "竟然失去了這麼多靈魄果…幸好我們至少回收了一部分。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60648] = {title = "心木林地的倖存者", objective = "從被附身者手中救出卡莎蒂、馬車管理員德芮溫和忒占。", description = "寇任斯…我不敢相信，他居然…\n\n我們必須盡可能拯救其他人。克勒諾樹林長太強了，光靠我們根本沒有勝算。\n\n我看到林地各處還有幾個倖存者，快點，我們要把握黃金救援時間！", progress = nil, completion = "德芮溫…我不想失去她！我們可以用靈魄果救她！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60649] = {title = "芒刺在側", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
