MultiLanguageQuestData['tw'][60660] = {title = "試飛", objective = "觀看科瓦斯寇的試飛。", description = "我把這些裝在我手臂上…然後它們會變成翅膀，對吧？\n\n然後我從懸崖上跳下來，並且飛起來！\n\n你要在旁邊看嗎？", progress = nil, completion = "嗯…失敗了。還缺什麼，還缺什麼…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60661] = {title = "垂死之夢", objective = "將伊瑟拉的野性種子帶到森林之心。", description = "我們失去了不計其數的靈魂了，但這個…她很特別。\n\n<月莓嚴正地看著你。她的語氣異常嚴肅，行動充滿魄力。>\n\n來吧，<name>。我們必須帶著她踏上重生之路，懇請女王救她一命。\n\n快點做好準備，我們時間不多。", progress = nil, completion = "幸會，陌生人。你到來的時間點…相當有趣。\n\n&lt;赫恩笑出聲來。&gt;\n\n而且你的同伴也同樣有趣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60669] = {title = "蠟燭兩頭燒", objective = "到奧格瑪的葛羅瑪許堡上方與洛索瑪‧塞隆交談。", description = "$p，部落受到攻擊了。\n\n不計其數的天譴軍團不死士兵蜂湧而至。規模之大堪比阿薩斯‧米奈希爾還坐鎮寒冰王座之時。\n\n不只是這樣…還有更可怕的事情發生了。\n\n我接下來要告訴你的事情，是最高機密。雖然消息不久就會傳播開來，但我必須先跟你直接商談。\n\n聽我說吧。", progress = nil, completion = "我們當然要搜尋索爾和貝恩，但我們也一定要兼顧保護平民與其他盟友的工作。\n\n因此我找來了有對付天譴軍團經驗的幫手。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60670] = {title = "十字軍的回歸", objective = "到奧格瑪的力量谷與瑟羅格指揮官交談。", description = "我親眼看過天譴軍團的無情進擊。用不了多久他們就會湧進城門。\n\n絕不能讓銀月城的歷史重演。\n\n黯刃騎士團的死亡騎士已經主動出擊，但他們需要援軍。\n\n銀白十字軍再次響應號召。請你協助他們保護我們的人民，<name>。\n\n他們的指揮官正在等你。", progress = nil, completion = "&lt;瑟羅格指揮官咕噥了一聲。&gt;\n\n就是你吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60671] = {title = "我們所做的犧牲", objective = "使用取得的靈魄果拯救馬車管理員德芮溫。", description = "快點！我們可以用我們收集的靈魄果拯救德芮溫。\n\n我知道它們應該用在野性種子上…不過我們不能再讓這些怪物從我們身邊奪走任何人了。", progress = nil, completion = "林地之心…\n\n我們必須把它拿回來…為了那些死去的人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60673] = {title = "叛徒", objective = "殺死罪孽看守者瑪提歐，收集他的鏡子裂片。", description = "好，現在看來我應該讓你進去。\n\n不敢保證瑪提歐會手下留情。我比較喜歡我的前任老闆，但這點別告訴他。\n\n很好奇她出了什麼事。在他們上次對談之後，戴納瑟斯似乎火冒三丈。\n\n就像往常一樣，容我為你開啟那道門。", progress = "你拿到瑪提歐的鏡子裂片了嗎？", completion = "他在工作方面的表現優異。\n\n我猜權力的承諾太過誘人，對他而言難以抗拒，不過現在不是思索這種事的時候。&lt;name&gt;，繼續前進。", rewards = "您會收到：\n\n恐懼哨衛烏黑頭盔破魂者烏黑兜帽懼獵者烏黑頭盔烏黑死亡帷罩兜帽"}
MultiLanguageQuestData['tw'][60709] = {title = "奪回林地之心", objective = "與忒占交談，破除樹林長的屏障，然後迎戰克勒諾樹林長。", description = "黑暗佔據了克勒諾樹林長的心，而他佔據了林地之心。\n\n林地之心流失的靈魄，就像成熟的果實流失甘露。非阻止這一切不可。\n\n邪惡魔法阻擋去路，靈魄岌岌可危，唯有靈魄才是救贖。\n\n懇求忒占，一個古老的靈魂，滿溢的靈魄將是點燃希望的火花。", progress = nil, completion = "我們傷亡慘重。為什麼要做出這種事？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60721] = {title = "靈魄必須流動起來", objective = "使用靈魄傳導器將靈魄引導到瑞文崔斯的某個地點。", description = "你在這裡看到的這部裝置，是用來將靈魄送到急需靈魄的區域，幫助我們的族人。\n\n隨著每個區域的靈魄重新流動，它就會逐漸恢復生氣。你會發現住在那裡的居民能在你的旅程中提供幫助，甚至會發現有全新挑戰等著你去面對。\n\n等你將一些靈魄送來我們的聖所，再使用這部裝置將靈魄導向某個區域，就能親眼見證成果。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60722] = {title = "驅動高塔", objective = "使用靈魄傳導器將靈魄引導到瑪卓薩斯的某個地點。", description = "這部裝置可以用來將靈魄導入我們遍布於瑪卓薩斯的高塔，強化我們駐守在高塔中的部隊。\n\n雖然這可以為我們帶來莫大助益，不過要切記，這些靈魄也可能會引起我們敵人的注意。\n\n使用這部裝置，將我們儲備的靈魄導入其中一座高塔。你很快就能見識到真正的力量所能達到的效果。", progress = nil, completion = "太好了！我感受到靈魄在流動。你可以定期回來操作這部裝置，引導更多靈魄。\n\n只要你收集並且引導更多靈魄到高塔中，高塔與我們聖所的連結就會越來越強。最終就能強化靈魄流，建立永久的連接。\n\n只要有足夠的靈魄流遍整個瑪卓薩斯，我們的軍隊就會所向披靡！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60723] = {title = "乾涸的樹根", objective = "使用靈魄傳導器將靈魄引導到亞登曠野的某個地點。", description = "這部裝置可將大神木的根部浸在靈魄中，讓枝幹獲得急需的靈魄。\n\n等到每個樹幹都充滿靈魄，它就會再一次開花。你會在它的枝幹下發現準備好幫助你的人，或者也能在樹蔭下迎來新的挑戰。\n\n現在，把靈魄帶到聖所，使用這部裝置把靈魄導入曠野。讓花朵再一次綻放吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60724] = {title = "無心", objective = "回到特那瓦勒找塔許莫爾樹林長。", description = "我的許多朋友都回歸循環了…全都是因為那些古怪的面具。\n\n為什麼他們要奪走我的朋友？毀滅我們的林地之心到底有什麼意義？\n\n你必須回到特那瓦勒，把這裡發生的事告訴塔許莫爾樹林長。\n\n我之後也會啟程前往那裡。我只是…需要一點時間道別。", progress = nil, completion = "暗影悄悄籠罩曠野，悲劇使者現身。\n\n命運之河快速流動，流勢無可阻擋。流向何方…卻是不得而知。", rewards = "靈魂看管者長袍林地看守者胸甲夢棘鍊甲星蔽外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][60725] = {title = "戰地報告", objective = "向杜洛塔和貧瘠之地的軍官取得報告。", description = "我們不知道天譴軍團會什麼時候、從哪裡展開攻擊。\n\n為了建立防禦陣線，銀白十字軍在幾個要地建立據點。但我們一直沒有收到通報。\n\n沿著南方的道路找到我派出的戰地軍官。回來的時候要提交完整報告。", progress = "援軍到了嗎！感謝聖光！", completion = "情勢比我們想像的更加嚴峻。\n\n必須趕緊通知瑟羅格指揮官。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60727] = {title = "來自寒冰皇冠的消息", objective = "到寒冰皇冠的銀白聯賽場地向審判者瑪瑞爾‧真心報到。", description = "北裂境的部隊剛剛傳來了令人擔憂的報告。審判者真心需要我們立刻出手相助。\n\n無論寒冰皇冠多麼危險，我們都要立即響應號召。\n\n像你這樣的<class>，對於戰場局勢大有幫助。\n\n我向你保證，你不在的期間我們會守住奧格瑪。\n\n<name>，戰鼓再次響起，相信你已經做好準備。", progress = nil, completion = "你來得正是時候。瑟羅格指揮官對你的評價很高。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60732] = {title = "截斷補給", objective = "干擾淵誓者在佐瓦爾的大釜中的行動。", description = "<你面前的靈魂受到折磨的殘餘燃燒著熔岩烈焰。它在大釜中的作用顯然已經結束了。\n\n靈魂剩下的軀殼毫不受到重視，令人分外不安。如果不阻止，這樣的行為會繼續下去。\n\n給佐瓦爾的大釜中的居民一點警告吧。>", progress = nil, completion = "歡慶你的成就，但也不要忘記任何行動都一定有後果。\n\n他的雙眼看見一切。", rewards = "您會收到：\n\n不羈魂靈強大的不羈魂靈勇武魂靈強大的勇武魂靈強大的盡責魂靈盡責魂靈高傲魂靈強大的高傲魂靈冥魄維娜里"}
MultiLanguageQuestData['tw'][60733] = {title = "關鍵角色", objective = "在統御者之座強化力量符文。", description = "那把劍上的符文…和統御者之座大門上刻的符文一樣。\n\n而且其中一個正在發光…\n\n跟我所想的一樣嗎，$p？你有方法能解開王座的封印？\n\n如果是這樣，或許維拉斯的豪賭並非毫無意義。這可以扭轉整場戰爭的局勢！", progress = nil, completion = "以鮮血與雷霆之名，我們會粉碎敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60735] = {title = "天堂中的麻煩", objective = "回答克蕾雅的問題。", description = "我想了一下你為什麼會出現在這裡，<name>。\n\n我很清楚，你不會無緣無故從奧睿博司來到這裡。我不知道你為什麼來這裡，也不知道你想做什麼。光是這點，就已經史無前例。\n\n你必須瞭解…凡人不會隨隨便便就來到昇靈堡。凡有果，必有因，那些被選召的人，每一個都是獨一無二的存在。\n\n所以…我問你…你到這裡，究竟有何企圖？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60736] = {title = "任務02", objective = "打開通往統御者之座的門。您會收到：\n\n完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60737] = {title = "通往未知的大門", objective = "打開通往統御者之座的門。", description = "你強化最後的符文了？那我們或許可以逆轉戰局了。\n\n開門吧，<name>！我們會盡力拖住敵人！", progress = nil, completion = "&lt;隨著你逐漸靠近古老的石祭壇，符文刃的光芒也越來越亮。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60738] = {title = "前往冬日窪地", objective = "邀請妮亞跟你一起將野性種子送到冬日窪地。", description = "我從沒看過像這樣的野性種子。就算是過去與照料者建立羈絆的種子，也從未出現像這樣的夢魘。\n\n說是這樣說，我們也從未有活著的凡人闖入這裡。\n\n我們必須把這枚野性種子送到冬日窪地，它在那裡才能得到需要的照顧和關注。\n\n我會把它放進靈體育籃，你可以問一下妮亞能不能陪你去嗎？\n\n她的林地消亡後，這個可憐的希瓦爾就一直失魂落魄的。出去走走應該對她有益。", progress = nil, completion = "太不可思議了，居然有野性種子能生成這種夢魘。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60739] = {title = "難搞的觀眾", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60759] = {title = "該死的入侵者", objective = "到十字路口殺死6個教徒和4個嗜血食屍鬼。", description = "一定要將這些報告交給瑟羅格指揮官，但我們防守十字路口的兵力應接不暇。\n\n請你離開前，幫我們盡可能削減天譴軍團的人數。我們或許能藉此喘口氣。", progress = nil, completion = "謝謝你，&lt;class&gt;。我們需要使盡全力才有可能擊退天譴軍團。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60761] = {title = "天譴軍回歸", objective = "到奧格瑪的力量谷將艾爾瑟拉中尉的報告交給瑟羅格指揮官。\n\n已提供物品：\n", description = "把這份報告交給瑟羅格指揮官。一定要讓他知道敵人的完整實力。\n\n如果我們沒辦法守住陣線抵擋天譴軍團…只能祈禱聖光守護我們大家。", progress = nil, completion = "我會把這份報告送到攝政王手中。恐怕這還只是開始。\n\n寒冰皇冠傳來消息，黑暗蠢蠢欲動，需要你出一份力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60762] = {title = "死亡微粒", objective = "在淵喉從廢墟育床收集10個死亡微粒。", description = "我有個任務要交給你，淵喉行者。\n\n適合加入淵誓者的靈魂會被打碎成最原始的精華。由此產生的怪物會形成一個黑色、毫無個人意志的暗影。\n\n這樣的下場十分悲慘。\n\n我想要進一步瞭解這個過程，究竟是什麼促成了靈魂的這種轉變？\n\n在廢墟育床到處都可以找到如雨落下的憔悴的靈魂碎片。帶點碎片給我，我就可以進一步瞭解我們的共同敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n不羈魂靈勇武魂靈強大的盡責魂靈盡責魂靈高傲魂靈強大的高傲魂靈沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][60763] = {title = "「鬚」要你助我一臂之力", objective = "協助月莓和羽光。", description = "你說瑪卓薩斯的統御者給的訊息？我們好久沒有他的消息了，自從…嗯，反正是好長一段時間。\n\n這應該不是惡作劇吧？只是女王可沒時間玩遊戲。不過我倒是有點時間。\n\n<月莓靠近你，輕聲說著。>\n\n說到遊戲，我想我們還少一朵百合。\n\n<月莓對你眨眼暗示。>\n\n我來看一下這個訊息吧。你把最後一朵夜百合交給羽光，我們再來談。", progress = nil, completion = "希望你的到來，對亞登曠野來說，是情況正在逐漸好轉的徵兆。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60764] = {title = "安撫之歌", objective = "與妮亞一起帶著野性種子前往冬日窪地。", description = "我會先飛去冬日窪地，說服艾利歐德樹林長幫助我們。希望等你和妮亞抵達的時候，我已經說服她了。\n\n你似乎能夠有效安撫這枚野性種子，你最好隨時待在它附近。\n\n妮亞也必須對野性種子唱歌，讓它保持平靜…不然可能會再度生成夢魘。\n\n木魈很喜歡打斷我們的歌聲，記得留意他們。\n\n等你準備好出發，就告訴我一聲。", progress = "真不可思議，小小一枚野性種子居然能惹出這麼多麻煩…", completion = "很高興再次見到你。曠野獵者需要你的幫助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60765] = {title = "癒病靈藥", objective = "使用玫沸的癒傷蛻皮來治療15個感染瘟疫的生還者。", description = "很多瘟疫家族的生還者還需要幫助。他們受的苦讓我充滿悲傷。\n\n淵喉行者，我要盡可能幫助他們。就算我們只救得了幾個，也比什麼都不做好。\n\n拜託，幫我治療他們！", progress = nil, completion = "你和玫沸做得很好，幫了瘟疫家族的生還者一個大忙。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者戰爭腰帶縫補之魂腰帶縫補咒術師繫腰縫補策略家束腰\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][60770] = {title = "先壓再燒", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60775] = {title = "惡有惡報", objective = "在淵喉的佐瓦爾的大釜把5個熔魂核心丟進靈魂熔爐。", description = "要在如此悲慘的地方生存下來一直都很困難，但我得承認…用合適的方法為幾個淵誓送終，的確會讓我開心點。\n\n在佐瓦爾的大釜，可以找到閻獄之主僱用的最殘忍爪牙，熔魂師。把他們的核心丟進每個人負責維護的熔爐，應該能讓我感到十分滿意。\n\n如果你還需要更加正當化這個行動，這麼做當然也可以暫時延緩他們的武器生產速度。", progress = nil, completion = "下次記得問我，怎麼做才能讓淵喉污鼠從懸崖邊緣奔竄而下。那真是百看不膩。", rewards = "您會收到：\n\n不羈魂靈強大的不羈魂靈勇武魂靈強大的盡責魂靈盡責魂靈高傲魂靈沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][60778] = {title = "拯救野性種子", objective = "協助寇任斯取回野性種子。", description = "<羽光看了一下筆記。>\n\n我們來看看...這裡有個求助任務，內容是關於陷入危機的野性種子…還有一顆蛋？原本的筆記寫得不是很清楚，不過求助的妖精是…啊！又是寇任斯。\n\n好吧，我們應該很快就會查清楚他到底遇到什麼麻煩！\n\n我先飛去找他，別走錯路。", progress = "你活下來了！", completion = "看著還真有趣！那隻鳥都準備好築巢，養育幼雛了！\n\n喔，我好久沒這樣笑了…", rewards = "您會收到：\n\n"}
