MultiLanguageQuestData['tw'][60843] = {title = "教徒打扮", objective = "從奧多薩的教徒身上拾取密謀者兜帽及密謀者長袍。", description = "雖然我們的斥候成功潛入奧多薩的教徒勢力中，但卻沒辦法進入默德雷薩。\n\n或許現在該探索其他方法了。\n\n從調查附近的邪教儀式秘室著手。你可能會找到某些有用的東西。", progress = "找到什麼了嗎？", completion = "這些應該夠用。", rewards = "您會收到：\n\n銀白十字軍表揚令"}
