MultiLanguageQuestData['tw'][60959] = {title = "燃燒的遠征：在外域展開冒險", objective = "前往殘破不堪的外域。", description = "破碎的外域危機四伏，像你這樣身經百戰的冒險者，也不一定能全身而退。\n\n想辦法回到那裡，繼續你的冒險！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60960] = {title = "丘的魯特琴", objective = "我很緊張，<name>。音樂會讓我的靈魂赤裸裸地暴露在眾人面前。\n\n儘管這顆罪孽石讓我回想起內心的黑暗，我還是希望我的音樂能讓其中的光明熠熠生輝。\n\n大使館中的加瑞登勛爵認同我。他非常善解人意，並且非常享受我第一次來的時候為他表演的曲子。\n\n我一定是把我的魯特琴留在他那裡了。請幫我取回來，我會這裡繼續進行表演前的冥想。", description = nil, progress = "我很緊張，<name>。音樂會讓我的靈魂赤裸裸地暴露在眾人面前。\n\n儘管這顆罪孽石讓我回想起內心的黑暗，我還是希望我的音樂能讓其中的光明熠熠生輝。\n\n大使館中的加瑞登勛爵認同我。他非常善解人意，並且非常享受我第一次來的時候為他表演的曲子。\n\n我一定是把我的魯特琴留在他那裡了。請幫我取回來，我會這裡繼續進行表演前的冥想。", completion = "&lt;丘一邊快速調音，一邊對魯特琴說話。&gt;\n\n老朋友，那些泥掘者對你做了什麼？", rewards = "您會學到：\n\n刺激"}
MultiLanguageQuestData['tw'][60961] = {title = "燃燒的遠征：在外域展開冒險", objective = "前往殘破不堪的外域。", description = "破碎的外域危機四伏，像你這樣身經百戰的冒險者，也不一定能全身而退。\n\n想辦法回到那裡，繼續你的冒險！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60962] = {title = "巫妖王之怒：在北裂境展開冒險", objective = "前往冰天雪地的北裂境。", description = "巫妖王在征服艾澤拉斯上的所有生靈，絕不會善罷甘休。\n\n想辦法回到北裂境，繼續你的冒險！", progress = nil, completion = nil, rewards = nil}
