MultiLanguageQuestData['tw'][60964] = {title = "潘達利亞之謎：在潘達利亞展開冒險", objective = "前往神祕莫測的潘達利亞。", description = "在綠意盎然的潘達利亞，無數謎題和秘密正等著人一探究竟，<name>。\n\n想辦法回到那裡，繼續你的冒險！", progress = nil, completion = nil, rewards = nil}
