MultiLanguageQuestData['tw'][60968] = {title = "德拉諾之霸：在德拉諾展開冒險", objective = "前往德拉諾的獸人家園。", description = "事不宜遲，<name>。德拉諾的人民還需要你的幫助！\n\n想辦法回到那裡，繼續你的冒險！", progress = nil, completion = nil, rewards = nil}
