MultiLanguageQuestData['tw'][60970] = {title = "軍臨天下：在破碎群島展開冒險", objective = "前往破碎群島。", description = "燃燒軍團無窮無盡的大軍入侵我們的世界，準備毀滅艾澤拉斯和上面的所有生靈！\n\n想辦法回到破碎群島，繼續你的冒險！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60971] = {title = "軍臨天下：在破碎群島展開冒險", objective = "前往破碎群島。", description = "燃燒軍團無窮無盡的大軍入侵我們的世界，準備毀滅艾澤拉斯和上面的所有生靈！\n\n想辦法回到破碎群島，繼續你的冒險！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][60972] = {title = "尋覓男爵", objective = "為騎士護符充能。", description = "<伯瓦爾給你的護符發出一道淡淡的紅光，然後黯淡下來。\n\n要用來尋找達瑞安‧莫格萊尼的話，你要先找到方法來恢復它的力量。\n\n你記得有個地方叫做佐瓦爾的大釜，那邊充斥著黑暗魔法。\n\n或許可以在那裡恢復護符的力量。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60973] = {title = "藍圖：寧靜之瓶", objective = "將藍圖：寧靜之瓶帶給達提莉絲。\n\n已提供物品：\n", description = "<你找到了一個小玻璃瓶的計畫書，這能讓你的靈魂之絆在晉升之路中有更大的優勢。\n\n達提莉絲應該可以幫你製作這個東西。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n製作：寧靜之瓶"}
MultiLanguageQuestData['tw'][60974] = {title = "寧靜之瓶", objective = "將寧靜之瓶帶給帕歐隆。", description = "<你的侍者朋友給了你額外的瓶子來裝藥水。\n\n這個應該跟你的藥水一樣，能讓你的靈魂之絆繼續在晉升之路戰鬥。>", progress = nil, completion = "瓶子？非常好！就像朋友一樣！給我保管比較妥當。", rewards = "您會收到：\n\n職責勳章"}
