MultiLanguageQuestData['tw'][60993] = {title = "忠誠要塞", objective = "到忠誠要塞找米卡尼寇斯。", description = "勳章是收割者之冠的魔力之源，如今還是屈服於戴納瑟斯的意志。\n\n重鑄無法解決這個問題，但忠誠要塞卻可以。\n\n那裡最近被棄誓者佔領了。如果我們能把收割者之冠送去要塞，就能徹底根除勳章前主人遺留的影響。", progress = nil, completion = "我們到了。很高興你在這裡也有朋友。\n\n如果我們想順利抵達要塞，很需要朋友相助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60994] = {title = "削弱他們的防禦", objective = "從棄誓者屏障源頭吸取靈魄。", description = "我們可以改造收割者之冠，抹去戴納瑟斯對勳章的腐化。\n\n問題是，棄誓者在要塞周圍設下大範圍的保護屏障。只有進入要塞，才能真正消弭戴納瑟斯遺留的影響。\n\n把屏障動力來源的靈魄吸乾，屏障就會消失。", progress = nil, completion = "做得非常好。\n\n要塞周圍的屏障已經消失了。想要修復收割者之冠，就必須進去才行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60995] = {title = "不忠", objective = "到忠誠要塞殺死15個棄誓者。", description = "這裡有很多與昇靈堡為敵的人。\n\n要是我們削減他們的人數，就能進一步緩和我們與昇靈堡之間的緊張關係。\n\n不要留情。\n\n我會飛到天上協助你們，必要時，我也會提供地面支援。", progress = nil, completion = "擊敗棄誓者了嗎？很好。他們的人數越少，我就越開心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][60996] = {title = "面對你的恐懼", objective = "與德瑞文將軍交談，前往忠誠神殿。然後，協助米卡尼寇斯淨化收割者之冠。", description = "現在可以進入神殿了。我們必須馬上行動，協助米卡尼寇斯消除戴納瑟斯王對收割者之冠的影響。\n\n做好準備，戴納瑟斯的魔法一向破壞力強大。\n\n這絕非易事。", progress = nil, completion = "擊敗戴納瑟斯的迴響後，米卡尼寇斯向我保證收割者之冠已經得到淨化。\n\n這是瑞文崔斯和整個暗影之境的一大勝利。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][61050] = {title = "如何同時佩戴七個勳章", objective = "與德瑞文將軍交談。", description = "一個汎希爾人不可能同時戴上七個勳章，同時還駕馭著它們所賦予的力量，也不可能讓盯著這些徽章的人肅然起敬。\n\n我的想法是製作一個可以限制勳章力量的神器，將那股力量集中在單一佩戴者身上。\n\n不幸的是，瑞文崔斯的工藝技術不足，無法一面引導這股力量，一面避免佩戴者變成戴納瑟斯的傀儡。\n\n所以，我們必須向精通這項技術的國度求助。\n\n德瑞文會告訴你詳情。", progress = nil, completion = "經過一番謀劃後，王子和我制定了一個計畫，需要某個勢力的協助和資源，但不久前我才奉主宰之命與他們發生衝突。\n\n做好眼睛防護，我們必須去昇靈堡一趟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61051] = {title = "心不在焉的工匠", objective = "到秋意高地尋找沙洛大師。", description = "他這個勇無謀、毫無理智、令人抓狂的…\n\n<守護者寇達哼了一聲，跺了一下腳蹄。>\n\n算了，呆站在這裡，對沙洛毫無幫助。我們必須找到他，把他平安帶回來。\n\n來吧，到秋意高地跟我會合。我們可以勘察下面的地穴，看看有沒有他還活著的跡象。", progress = nil, completion = "不！\n\n不知道那個怪物是什麼，但牠抓走了沙洛！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61057] = {title = "千錘百鍊", objective = "跟克芮恩一起完成靈魂之絆儀式。", description = "你自從來到亞登曠野，展現了力量、智謀，與同情心。這些都是強大的獵人必備的特質。\n\n<name>，能夠與你並肩作戰是我的榮幸。我希望能以靈魂之絆的身分繼續與你同行。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n靈魂之絆：狩獵隊長克芮恩\n\n您還會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][61058] = {title = "夢中相絆", objective = "與織夢者完成靈魂之絆儀式。", description = "當伊瑟拉的野性種子對你產生反應時，我就知道你一定很特殊。要是沒有你，她就沒救了！那樣不只是亞登曠野的損失，也是你的世界的悲劇！\n\n自那時起，我看見你繼續幫助了更多需要的人。因為有你的努力，亞登曠野才能恢復元氣。\n\n我很榮幸能繼續支援你在這裡的善行，並成為你的靈魂之絆。", progress = nil, completion = "只要我們同心協力，一定能拯救亞登曠野和所有在這裡沉睡的靈魂。", rewards = "您會學到：\n\n靈魂之絆：織夢者\n\n下列法術會施放在您身上：\n\n燃棘食人妖偽裝\n\n您還會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][61059] = {title = "回函：倫德和棍臉", objective = "「速合」的帽子可以由擁有配方且具備合適交易技能的玩家製作。", description = "我聽說王子想要找倫德和我參加這場宴會。我完全樂意參加，但是倫德說他沒有合適的服裝。\n\n說他需要一頂適合的帽子，展現他豐富的內涵。\n\n他說只有紅頂蠟燭，或是那個妖精狂歡面具才稱得上是好帽子。又或者是粉紅派對帽，或是花俏的公義之冠。", progress = nil, completion = "真是一頂好帽子！倫德一定會成為這場宴會的焦點。", rewards = "您會收到：\n\n回函：倫德和棍臉"}
MultiLanguageQuestData['tw'][61060] = {title = "失孢者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61061] = {title = "烏爾法的指引", objective = "到佐司瓦的烏爾法洞穴與烏爾法交談。", description = "有一個人或許知道如何驅除葛薇亞身上的詛咒。\n\n烏爾法就住在佐司瓦的群山之中，他是非常古老的棘語者，當時他與庫爾提拉斯的人類共同對抗他的佐司特族人。\n\n前往他的住處，尋求他的智慧。他或許有你想知道的答案。\n\n等到亞拉隆把葛薇亞送回來後，赫恩勛爵和我會照顧她。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61062] = {title = "德克利斯副官", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61075] = {title = "一瞬光明", objective = "擊敗4個詛咒之眼。", description = "果戈亞是一條千變萬化的河，接受來自各個世界的靈魂滋養。無數靈魂從這條河的源頭流入河中。那裡稱為惡徒坩堝。\n\n閻獄之主永遠睜開的眼睛巡視著果戈亞河，留意膽敢逃跑的靈魂。\n\n把四下搜尋的眼睛弄瞎。讓它們徹底閉起來。\n\n這給你，用它完成必要的任務。", progress = nil, completion = "做得好，淵喉行者。閻獄之主的目光危險無比。", rewards = "您會收到：\n\n沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][61076] = {title = "烈焰之中", objective = "將勾拉圖爾之力注入佐司特塑像。", description = "我知道你所說的詛咒。那是會控制心靈的黑暗魔法。\n\n很久以前，佐司特受到一名叫做勾拉圖爾的巫法之王所統領。正是他扭曲了我們的儀式，導致我們走向死亡和支配的道路。\n\n我需要取得他一部分的力量，才能破除詛咒。\n\n帶著這個神像前往戈爾伊納，把它放入寂滅之焰重新淬煉。不過要小心…那是個邪惡的地方，無數危險潛伏在陰影之中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][61077] = {title = "面對罪行", objective = "到罪殞城與控罪者交談。", description = "多虧了對納撒亞城發動突擊，我們終於找到機會了。\n\n一個強大的靈魂，經主宰的實驗改造，與惡意結合。\n\n由於這個靈魂來自艾澤拉斯，因此控罪者請你協助清除汙染其罪孽石的腐化。\n\n控罪者正在罪殞城的下層等你。", progress = nil, completion = "我不會假設來自艾澤拉斯的所有凡人彼此都認識。\n\n不過，面對像這樣極具挑戰性的靈魂，就算只是略有耳聞，也能發揮一定作用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61079] = {title = "閻獄之主的好料", objective = "將4個冥魄導引裝置放在淵喉內卡西斯的標示位置上。", description = "淵誓拷問者造成痛苦的才華出眾。\n\n他們造成的痛苦折磨，常常產生多到來不及收集的冥魄。剩下的部分常飄散在空中，任其慢慢消散在黑淵中。\n\n我製作了一個導引裝置，可以收集這些剩餘的冥魄。想要的話，你可以借去用。\n\n卡西斯各個角落有一些適合收集的重要地點。既然你用的是我的導引裝置，等你帶東西回來後我們可以對半分。", progress = nil, completion = "知道閻獄之主的資源掉進我們手中，真讓人心滿意足。做得很好，淵喉行者。", rewards = "您會收到：\n\n不羈魂靈強大的不羈魂靈勇武魂靈強大的勇武魂靈強大的盡責魂靈盡責魂靈高傲魂靈強大的高傲魂靈沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][61087] = {title = "延遲送達：舊城門包裹", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61088] = {title = "土歸土", objective = "在淵喉中的卡西斯救出8個半埋的靈魂。", description = "淵誓者一直在發明新的痛苦折磨。\n\n就連我們腳下的地面是把靈魂輾成碎片後構築出來的。靠著川流不息、行經果戈亞的靈魂，淵誓很熱衷於擴展領域。\n\n目前，淵誓正在掩埋靈魂，用他們的苦難構築新的地形。對其中一些靈魂來說，還不算太遲。\n\n釋放被掩埋的靈魂，阻止他們的痛苦無限擴張。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][61092] = {title = "回函：沃爾大師", objective = "藉由賄賂或是殺掉敵對陣營玩家來說服沃爾大師。", description = "我很忙，所以我會長話短說。\n\n能說服我的唯一方式就是給我足夠的硬幣，讓我覺得值得，不然就是取悅我。\n\n就算餘燼宴會再怎麼讓人樂在其中，每次我只要離開這裡，荷包就會失血。也就是說，我確實很喜歡看一場屠殺秀。\n\n所以呢，付錢或動手殺戮，自己選一個。", progress = nil, completion = "成交，我會出席，那一定會是一段美妙的假期。", rewards = "您會收到：\n\n回函：沃爾大師"}
MultiLanguageQuestData['tw'][61095] = {title = "來自不死軍團的補給品", objective = "在苦痛劇場和納爾空‧塔爾森交談。", description = "你的努力獲得不死軍團的認可。\n\n這些獎勵是你應得的賞賜。希望它們能在接下來的戰鬥中派上用場。", progress = nil, completion = "你對瑪卓薩斯及時伸出援手，不死軍團想要致上最高的謝意。\n\n為了感謝你對我們的使命以及部隊所付出的一切，請接受這份禮物。", rewards = "您會收到：\n\n不死軍團補給品"}
MultiLanguageQuestData['tw'][61096] = {title = "審斷者的意志", objective = "在奧睿博司的樞運之環和卡薛爾會面。", description = "如果昇靈堡和瑪卓薩斯開戰，我們都會蒙受其害。\n\n我們好久沒聽到死靈領主的消息了。你一定要前往他們的國度，查明這次侵略的真相。\n\n雖然我們的靈魄容器存量有限，但還夠為你打開道路。", progress = nil, completion = "這樣應該夠了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61097] = {title = "來自晉升者的補給品", objective = "在昇靈堡和位於英雄之陵的妮可絲副官交談。", description = "晉升者想要為你對昇靈堡伸出援手致上謝意。\n\n為了感謝你對我們的使命以及居民所付出的一切，請接受這份禮物。", progress = nil, completion = "晉升者想要為你對昇靈堡伸出援手致上謝意。\n\n為了感謝你對我們的使命以及居民所付出的一切，請接受這份禮物。", rewards = "您會收到：\n\n晉升者補給品"}
MultiLanguageQuestData['tw'][61098] = {title = "來自曠野獵者的補給品", objective = "到亞登曠野的森林之心與艾瑟琳交談。", description = "曠野獵者感謝你努力援助亞登曠野。\n\n為了表揚你的貢獻，請收下這些禮物。願它們能在接下來的試煉中助你一臂之力。", progress = nil, completion = "曠野獵者感謝你努力援助亞登曠野。\n\n為了表揚你的貢獻，請收下這些禮物。願它們能在接下來的試煉中助你一臂之力。", rewards = "您會收到：\n\n曠野獵者補給品"}
MultiLanguageQuestData['tw'][61099] = {title = "搜尋貝恩", objective = "進入托迦司尋找貝恩。", description = "我自然是不敢親自踏入那座受詛咒的高塔。\n\n雖然我無法準確說出你的同伴在哪裡，但我能給你一份禮物協助你。\n\n在托迦司內使用，應該能帶你到迷失的夥伴附近。我記得他好像叫貝恩‧血蹄，對吧？\n\n它也有可能會害你困在塔內變幻萬千的迴廊中，永遠無法逃脫。\n\n出來混，總得承擔一些風險，我想。祝你好運！", progress = "你找到他了！", completion = "找到貝恩可不是簡單的事，但你勇敢面對高塔的恐怖，功成而返。\n\n做得很好。\n\n但你的工作恐怕才剛開始。", rewards = "您能選擇下列奬勵中的一個：\n\n使命束縛鎖鍊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][61100] = {title = "來自收割者廷衛的補給品", objective = "與彌海菈女士交談，領取你的獎勵。", description = "你為我們做出的貢獻，大家有目共睹。在瑞文崔斯，有越來越多的汎希爾自願加入收割者廷衛，不再效忠主宰。\n\n我們也因而收集到了一些可能對你有用的資源，這些都是從戴納瑟斯王最愚忠的追隨者身上奪來的。我在暗隱村等你過來領取獎勵。", progress = nil, completion = "你為我們做出的貢獻，大家有目共睹。在瑞文崔斯，有越來越多的汎希爾自願加入收割者廷衛，不再效忠主宰。\n\n請收下這些謝禮。", rewards = "您會收到：\n\n收割者廷衛補給品"}
MultiLanguageQuestData['tw'][61102] = {title = "棘語者琦娃", objective = "到亞登曠野的森林之心與赫恩勛爵交談。", description = "我年輕的時候，曾在一位博學又強大的棘語者底下學習，她名叫琦娃。她早在許久以前就已經過世，不過她的靈魂或許仍在暗影之境的某處沉眠。\n\n琦娃深諳遠古而廣博的知識，非我所能及。她或許能為你提供我無能為力的指引。\n\n找到她，把這個神像交給她。她會知道該怎麼做。\n\n願風指引你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61103] = {title = "打破循環", objective = "在淵喉的鍊魂塔擊敗4個淵誓鐐卒和6個亡眼。", description = "在鍊魂塔中的鐐卒是很可怕的東西。\n\n被拷問的靈魂會被逼到心生惡毒之意。然後他們將被分派成守衛，重複無止盡的循環。\n\n如果你想讓閻獄之主增加部隊的速度慢下來，就從源頭著手。\n\n干擾鍊魂塔的循環。", progress = nil, completion = "做得好，淵喉行者。閻獄之主的部隊數量龐大，但並非無窮無盡。", rewards = "您會收到：\n\n沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][61104] = {title = "『抽取者』葛拉瑟勒斯", objective = "在淵喉的鍊魂塔下面擊敗葛拉瑟勒斯。", description = "淵誓者中有許多強大的副官，但其中一位對閻獄之主來說特別重要。\n\n葛拉瑟勒斯是閻獄之主最得力的拷問者，就在鍊魂塔的地下深處。透過區域中的導引裝置，不斷有能量輸送到他身上。\n\n他的工作，就是讓抽取靈魄的過程更有效率。而他的手段相當…不仁慈。\n\n終結他的存在對我們兩個都有利。", progress = nil, completion = "葛拉瑟勒被消滅對於閻獄之主的計畫肯定是重大打擊。做得好。", rewards = "您會收到：\n\n不羈魂靈強大的不羈魂靈勇武魂靈強大的盡責魂靈盡責魂靈高傲魂靈強大的高傲魂靈沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][61105] = {title = "回函：瘟疫設計者瑪利雷斯", objective = "將起泡軟泥趕到凱文身邊，讓瘟疫設計者瑪利雷斯能帶著禮物出席餘燼宴會。", description = "喔！學徒，這聽起來像是到瑞文崔斯進行田野調查的大好機會。\n\n我很期待與新的同事合作。我們必須帶個禮物，謝謝他們的邀請。還有比可愛的軟泥更適合當成禮物的東西嗎？\n\n幫我挑一些品質最好的軟泥，讓我送給主辦人。帶它們去找凱文，讓它們交個朋友、一起出去玩。", progress = nil, completion = "你做得非常好，學徒！", rewards = "您會收到：\n\n回函：瘟疫設計者瑪利雷斯"}
MultiLanguageQuestData['tw'][61107] = {title = "鬥爭之地", objective = "開啟通往瑪卓薩斯的傳送門。", description = "最重要的是，你能不能查明攻擊昇靈堡的起因。\n\n我們需要你的協助才能打開傳送門。只要集中足夠的力量，我們就會召喚通往瑪卓薩斯的傳送門，並引導它就定位。\n\n從這個地方開始，這場戰爭的命運就由你一肩承擔了。", progress = nil, completion = "路已經開啟了。瑪卓薩斯的永恆戰場正等著你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61109] = {title = "回函：狩獵隊長克芮恩", objective = "解除果姆蟲巢造成的威脅，打破那些卵、消滅照顧蛋的東西然後殺光果姆，這樣狩獵隊長克芮恩才能參加餘燼宴會。", description = "我是曠野獵者的隊長，也是神聖林地的防衛者。我應盡的職責是在這裡擊退敵人的部隊，而不是跑到亞登曠野外面冒險。\n\n果姆蟲巢的蟲卵又開始孵化了，我們很快就會被小果姆幼蟲淹沒。在解決這個威脅之前，我都不能擅離崗位。", progress = nil, completion = "做得好。謝謝你的幫忙。", rewards = "您會收到：\n\n回函：狩獵隊長克芮恩"}
MultiLanguageQuestData['tw'][61112] = {title = "嗜肉", objective = "到暴風城的貿易區將部分消化的布料交給格里高指揮官。\n\n已提供物品：\n", description = "<這件沾滿膽汁的布料散發著死亡的惡臭。仔細觀察後，發現它好像有點眼熟。這無疑是銀白十字軍的徽記。\n\n格里高指揮官一定會想要馬上得知這件事的。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61113] = {title = "琦娃的巢穴", objective = "前往位在亞登曠野日暮林地的琦娃的巢穴。", description = "我好久沒聽到琦娃這個名字了。\n\n她以前住在南方的日暮林地附近。亞拉隆對那一帶很熟悉，你可以帶他一起去。\n\n我擔心葛薇亞的狀況對他的心理造成重大負擔。或許跟你一同狩獵也能對他有幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61114] = {title = "嗜肉", objective = "到奧格瑪的力量谷將部分消化的皮料交給瑟羅格指揮官。\n\n已提供物品：\n", description = "<這件沾滿膽汁的皮料散發著死亡的惡臭。仔細觀察後，它好像有點眼熟。這無疑是銀白十字軍的徽記。\n\n瑟羅格指揮官一定會想要馬上得知這件事的。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61123] = {title = "回函：軍政官阿德雷特斯", objective = "尋求謙遜楷模的協助。", description = "我必須婉拒王子的邀請。\n\n這裡還需要我，而且我現在沒有適合參加晚宴的社交服飾。\n\n或許請謙遜楷模代表昇靈堡是更好的選擇。\n\n你應該可以在謙遜神殿找到他，就在此處的東方。\n\n請告訴王子，我不便出席讓我感到深切的遺憾。", progress = "我的答案還是沒變。", completion = "謝謝你提醒我，有時候我的職責需要做些不太愉快的事情。\n\n&lt;軍政官阿德雷特斯向你敬禮。&gt;", rewards = "您會收到：\n\n回函：軍政官阿德雷特斯"}
