MultiLanguageQuestData['tw'][61166] = {title = "廢物回收再利用", objective = "從棄誓者百衛或百衛零件中收集20塊共鳴合金。", description = "百衛需要許多零件。但我們也一樣！\n\n科菲需要金屬。可以從百衛或是地上找到。隨你挑！\n\n不要造成太多傷害，好嗎？那很難清的！", progress = "你拿到金屬了嗎？", completion = "這真是重金屬！就像科菲最愛的音樂一樣！", rewards = "您會收到：\n\n百衛機兵能量核心戰鬥冥想輔助工具送魂使肩墊盾衛胸甲盾衛護脛盾衛重肩甲天鐘項鍊銀符披風鍛造工匠的燃煤以太珍釀純潔省思勇氣思量\n                            顯示 7 更多                        禱鐘擊錘楷模編年史手持靈魂之鏡乾燥恩典花瓣香爐壞掉的百衛控制器神聖使命之琴感激禮賜"}
MultiLanguageQuestData['tw'][61171] = {title = "不滅的羈絆", objective = "將赫恩勛爵的報告送給凜冬女王。", description = "佐司特在我們身上施加如此惡毒的詛咒，一定要付出代價。\n\n我們失去了太多盟友…現在又要放棄太多的朋友。就算我們無法拯救那些被附身的靈魂，至少可以結束他們的苦難。我會下達指示，打倒遇到的每一個被附身的靈魂。\n\n請將這份報告送到凜冬女王手中。一定要馬上讓她瞭解我們得知的消息。\n\n<name>，多謝你的效力，你是個真正的朋友，也是亞登曠野的守護者。您會收到：\n\n", progress = nil, completion = nil, rewards = "妖精編織襯肩橡心披肩女王近衛肩鎧符文看守者肩甲您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][61173] = {title = "回函：米卡尼寇斯", objective = "協助米卡尼寇斯收集可能很完好無缺的零件，讓他可以順利完成工作，出席餘燼宴會。", description = "餘燼宴會聽起來很有趣…不過現在忙死了！棄誓者弄亂了我的補給品。現在一切都亂糟糟的，這種情況沒辦法工作，我的工坊一團混亂！\n\n幫幫我！看看那些零件，大多數都受損了，不過你應該看不出來有沒有瑕疵。幫我收集零件，越多越好，我會從裡面找出完好無缺的零件。", progress = "我的零件呢？", completion = "這一個是最完美的！看到了嗎？剩下的都不能用，你自己留著吧。", rewards = "您會收到：\n\n回函：米卡尼寇斯綜合零件和小東西"}
MultiLanguageQuestData['tw'][61174] = {title = "回函：瓦許女爵", objective = "收集強敵的頭顱，獻給瓦許女爵。", description = "淵喉行者，我和法庭並不陌生。我服侍過艾薩拉女王，後來也在伊利丹大人底下做過事。\n\n但這也不代表我什麼樣的邀請都會接受。\n\n<瓦許女爵露出狡猾的笑容。>\n\n$p，用你的實力贏得我的青睞，那麼我就會相信雷納瑟王子是個值得我付出時間的強者。", progress = "敵人的頭顱在哪裡？", completion = "&lt;瓦許女爵對著你放在她面前的頭贊許地點了點頭。&gt;\n\n既然王子的勢力背後有你的力量在撐腰，那我最好多加注意一點。\n\n好吧。我會去拜訪一下雷納瑟王子，出席他的餘燼宴會。", rewards = "您會收到：\n\n回函：瓦許女爵"}
MultiLanguageQuestData['tw'][61179] = {title = "帶頭熔鑄", objective = "到永恆熔爐與熔爐士瑟琳交談。", description = "永恆熔爐又有靈魄了？\n\n啊！沒錯！真令人開心！\n\n你一定要去。去找熔爐士瑟琳。她會幫忙的！有太多東西要打造！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61180] = {title = "未看先燒", objective = "收集6份縫肉的設計。", description = "你找到的這份卷軸裡，詳細記載了各種方式，可以將倒下的琪瑞安「結合」到珈爾瑪的傀儡中。\n\n這份卷軸還不完整。在縫肉殘存的追隨者手中，一定還有更多卷軸。\n\n在我們抵達的時候，我看到好幾位縫補師和他們的僕人撤退到前面的鎖鍊大廳裡。我想他們一定還有更多這種卷軸。\n\n我們要保證再也沒有人能讀到這些內容。", progress = "一定要毀掉這個邪惡的作品。", completion = "做得好。我會親眼看這些東西化為灰燼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61182] = {title = "和你等重的花粉", objective = "在昇靈堡的平原收集30份旋瓣花花粉。", description = "你知道旋瓣花嗎？！它們會在光線中不斷旋轉！\n\n我們需要花粉。只有盛開的才有花粉！\n\n去找花粉來！在黃金原野中的花。而且它們會轉！轉啊轉個不停！", progress = "花粉十分脆弱。不能持續太久！", completion = "好多！對，對，太好了！非常好！", rewards = "您會收到：\n\n百衛機兵能量核心戰鬥冥想輔助工具盾衛胸甲盾衛戰靴盾衛巨盔天鐘項鍊鍛造工匠的燃煤以太珍釀純潔省思勇氣思量禱鐘擊錘楷模編年史\n                            顯示 5 更多                        手持靈魂之鏡乾燥恩典花瓣香爐神聖使命之琴講師的聖鐘感激禮賜"}
MultiLanguageQuestData['tw'][61189] = {title = "進階膠質研究", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61190] = {title = "灰燼甦醒", objective = "逃離淵喉，到奧睿博司向伯瓦爾回報。", description = "淵喉彷彿有自己的感知…察覺得到我們這些不速之客。\n\n我們必須馬上離開。伯瓦爾一定已經知道這裡發生的事。\n\n我會帶我父親一起走。帶我們離開這裡，<name>，動作快。", progress = nil, completion = "現在該讓你，還有…你的夥伴，離開這裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61193] = {title = "聖光之觸", objective = "在水源收集15朵首生者之光。", description = "需要首生者之光！你知道嗎？\n\n這是御靈者取的名字！經常都在水中生長。科菲的最愛！\n\n在成熟之後閃耀著明亮之光。去岸邊看看！很容易看到！", progress = "只要成熟的花！小花不管用。", completion = "好亮啊！下次科菲要戴個護目鏡再來！", rewards = "您會收到：\n\n百衛機兵能量核心戰鬥冥想輔助工具盾衛束腰鍛造工匠的燃煤以太珍釀純潔省思勇氣思量禱鐘擊錘楷模編年史手持靈魂之鏡乾燥恩典花瓣香爐講師的聖鐘感激禮賜"}
MultiLanguageQuestData['tw'][61196] = {title = "神秘食材", objective = "收集10份疾逝藥膏。", description = "有時候，就算是最老練的琪瑞安，也難以好好冥想。最近，這樣的問題越來越常見。\n\n有一種用最純淨的水精製而成的特殊藥劑，可以用來凝聚心志。我相信它可能有助於改善我們在此地的情況，或許還能當做催化劑來促進其他效果。\n\n你能去拿幾個來嗎？動作快，只要一離開我們的神聖之池，這種液體就會越來越不穩定。", progress = "你有找到那種藥劑嗎？", completion = "我馬上就開始測試這些樣本！十分感謝你。", rewards = "您會收到：\n\n百衛機兵能量核心戰鬥冥想輔助工具送魂使馬褲鍛造助手腿甲盾衛護脛天鐘項鍊鍛造工匠的燃煤以太珍釀純潔省思勇氣思量禱鐘擊錘楷模編年史\n                            顯示 7 更多                        手持靈魂之鏡乾燥恩典花瓣香爐壞掉的百衛控制器循道詩集神聖使命之琴講師的聖鐘感激禮賜"}
MultiLanguageQuestData['tw'][61199] = {title = "武器之日", objective = "從戰場上收集20件庇佑武器。", description = "這邊有好多戰鬥。尤其是最近！\n\n現在到處都是武器。多到不行。我們可以用得上！\n\n去大戰場拿些回來。我們可以用在更好的地方！", progress = "小心別割到了！", completion = "這些太完美了！謝謝你呀！", rewards = "您會收到：\n\n百衛機兵能量核心戰鬥冥想輔助工具鍛造助手頭盔盾衛巨盔盾衛護脛指引之光防衛盾安魂手鐮追悼法刃天鐘項鍊鍛造工匠的燃煤以太珍釀純潔省思\n                            顯示 6 更多                        勇氣思量禱鐘擊錘楷模編年史手持靈魂之鏡乾燥恩典花瓣香爐感激禮賜"}
MultiLanguageQuestData['tw'][61209] = {title = "悲傷旋律", objective = "在昇靈堡的路上，打散15位琪瑞安的記憶。", description = "我們琪瑞安死後應該就在此地的戰場中消亡，但昇靈堡內有許多力量，會喚出先前的兄弟姐妹殘念。\n\n這些記憶正在路上遊蕩。有時候，他們會採取一些行動，製作貨品、守護我們的聖地等等…宛如他們抵達這個永恆之地時賦予的使命。\n\n帶著我的七弦豎琴。它的古老旋律會驅散記憶，記得順便用我們國度的殘餘能量來為它充能。", progress = nil, completion = "七弦豎琴的彈奏聲充滿力量！我們該好好利用。", rewards = "您會收到：\n\n百衛機兵能量核心戰鬥冥想輔助工具靈癒者軟靴送魂使長靴送魂使頭盔送魂使護腕鍛造助手脛甲鍛造助手頭盔盾衛戰靴盾衛巨盔盾衛護臂光榮傷亡裁決錘\n                            顯示 9 更多                        鍛造工匠的燃煤以太珍釀純潔省思勇氣思量禱鐘擊錘楷模編年史手持靈魂之鏡乾燥恩典花瓣香爐感激禮賜"}
MultiLanguageQuestData['tw'][61217] = {title = "勇士：席菈‧飲魂", objective = "我記得很清楚！我不會繼續困在這個地方。\n\n淵喉行者，請容我從旁協助。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：席菈‧飲魂"}
MultiLanguageQuestData['tw'][61218] = {title = "勇士：達格‧墓井", objective = "你幫了我一個大忙，所以我會湧泉以報，協助你擺脫困境。\n\n我和我的鏟子任你驅策。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：達格‧墓井"}
MultiLanguageQuestData['tw'][61219] = {title = "勇士：奈里斯‧暗翼", objective = "完成復仇之後，我彷彿失去目標。\n\n淵喉行者，我想加入你，並把恐懼深植敵人心中。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：奈里斯‧暗翼"}
MultiLanguageQuestData['tw'][61220] = {title = "啊！真的有怪物！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61221] = {title = "勇士：石投", objective = "我的罪孽石最近沒有什麼人在用。\n\n就我的判斷，如果我能跟著你，或許有機會好好使用它。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：石投"}
MultiLanguageQuestData['tw'][61222] = {title = "勇士：治癒者凱勒塔", objective = "淵喉行者，謝謝你解放我。\n\n為了回報你的好心，請容我相助。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：『治癒者』凱勒塔"}
MultiLanguageQuestData['tw'][61223] = {title = "勇士：喪魂者艾樂思", objective = "還不夠！\n\n讓我從你的敵人身上暢飲鮮血！\n\n讓我去對付他們！", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：『喪魂者』艾樂思"}
MultiLanguageQuestData['tw'][61226] = {title = "額外的肢體", objective = "找到領航員山尼爾並協助他。", description = "只靠我們無法執行女爵的計畫。女爵提出的計畫需要一組協調良好的隊伍。\n\n有三人和我一塊操控努拉齊爾。在亡城墜落時，我的兩位靈魂之絆也一同墜落了。\n\n有個和我連結的靈魂還倖存著，那是我的姊妹，山尼爾。他還存活在殘骸裡，只是非常悲傷。\n\n找到山尼爾。帶著她走過創傷，然後在他準備好面對我們的試煉時回來。", progress = nil, completion = "我們經歷了可怕的苦難。我要好好珍惜我還擁有的東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61227] = {title = "另一支腳", objective = "找到技師安西德。", description = "沒有適合的人選能修復亡城、讓亡城飛在空中，想要好好控制亡城簡直是癡人說夢。努拉齊爾的技師都在墜毀時死光了。\n\n但在這個危急時刻，浮現了一個轉機。維恩提到傀儡之間出現了一場…騷動。有個成員反對其他人無窮無盡的搜刮努拉齊爾，而且毫不意外，他因為抗議被關了起來。\n\n找出這個人。我們敵人中的叛徒，就可能是我們的朋友。", progress = nil, completion = "所以你需要一位技師？還真巧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61228] = {title = "達格遺失的鏟子", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61230] = {title = "外來因素", objective = "在蛛眼家族的通訊柱與卡莉克會面。", description = "只有最有效的魔法才能駕馭一座亡城。但是蛛眼家族的舵手和努拉齊爾一起消亡了。\n\n不過，瓦許女爵告訴過我有個方法能找到新舵手。\n\n跟我到家族的通訊信標那邊。我的女爵教過我怎麼做，能幫我們找到需要的人選。\n\n我想她不會甘願在之後為我們效力。但我相信你會鼓勵她服從。", progress = nil, completion = "感謝你準時完成。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61234] = {title = "石投的罪孽石", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61243] = {title = "席菈的回憶石", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61246] = {title = "天選之力", objective = "摧毀膽腫重戰士。", description = "亡城要就位了。現在就是出擊的時刻！\n\n我們要一起把珈爾瑪逼到開闊地帶。坐上我的大鵬，對這些重戰士釋放符文刃的力量。\n\n藩侯沒辦法無視他們的死亡，一旦他離開了那座邪惡的高塔，我們就可以一勞永逸解決他。", progress = nil, completion = "看看這種力量！珈爾瑪已經別無選擇，只能與我們一戰。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61248] = {title = "凱勒塔的自由", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61252] = {title = "召集幫手", objective = "召喚舵手卡利若斯並擊敗他。", description = "我們會遵守女爵的命令。讓我們召喚一位舵手前來…不過這可能會讓她很不高興。\n\n啟用信標，準備面對一場硬仗。巫妖視所有蛛眼家族的人為敵，而且我很確信你在他們家族的名聲也發揮不了什麼用處。", progress = nil, completion = "我的女爵十分信任你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61255] = {title = "回函：亞歷山卓斯‧莫格萊尼", objective = "從鑄骨坊收集9把鑄骨法杖以及3把鑄骨戰斧。", description = "能夠代表瑪卓薩斯出席雷納瑟王子舉辦的餘燼宴會，是我莫大的榮幸。\n\n但在我離開崗位之前，我必須確保我的同袍在我離開時能安全無恙。\n\n一路殺進鑄骨坊並從裡頭取得我們對手的武器。\n\n我會把他們分派到部隊裡，我同時也會做好離開的準備。", progress = "你拿到武器了嗎？", completion = "真是一箭雙雕啊，我們得到許多武器，敵人則是失去許多武器。", rewards = "您會收到：\n\n回函：亞歷山卓斯‧莫格萊尼"}
MultiLanguageQuestData['tw'][61256] = {title = "回函：克蕾雅與佩拉苟斯", objective = "跟克蕾雅與佩拉苟斯一起進入冥想室，面對過去的記憶。", description = "喔，真神奇！謝謝你邀請我們參加餘燼宴會。\n\n我們只是需要透過冥想淨化自己。如果馬上就要離開的話，就更需要冥想了。要一起來嗎？", progress = nil, completion = "我一直認為冥想不只能讓人放鬆，還讓人很有收獲。你不覺得嗎？現在我們最好快點準備啟程了！", rewards = "您會收到：\n\n回函：克蕾雅與佩拉苟斯"}
