MultiLanguageQuestData['tw'][61272] = {title = "藍圖：失諧符咒", objective = "將藍圖：失諧符咒帶給達提莉絲。\n\n已提供物品：\n", description = "<你找到了一個符咒的計畫書，這能使你的靈魂之絆對晉升之路中的敵人造成傷害。\n\n達提莉絲應該可以幫你製作這個東西。>", progress = nil, completion = "我看到你得到了新藍圖。我迫不及待想幫你製作了。", rewards = "您會學到：\n\n製作：失諧符咒"}
