MultiLanguageQuestData['tw'][61396] = {title = "黑暗研究", objective = "將可憎設計帶給阿特米德。\n\n已提供物品：\n", description = "<這份破破爛爛的文件，看起來是縫補師縫肉寫下的。>\n\n…琪瑞安的血肉讓力量、服從和敏捷強化了兩倍！真是太有潛力了！\n\n現在，如果實驗體號碼一三五最後成功移植了翅膀的話…\n\n<文件繼續描述了一長串內容。你應該將它帶給你的琪瑞安盟友。>", progress = nil, completion = "讓我研究一下。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61397] = {title = "伺機攻擊", objective = "與奧斯朋‧布萊克交談。", description = "聖所不能單靠靈魄來運作，需要許多自願的靈魂互相合作，才能解鎖統御者之座的完整潛力。\n\n一直以來，我們的靈魂看守者負責找新的靈魂來聖所。你能自由往來淵喉，正好是個能協助他的獨特機會。\n\n你應該去他那邊，看看你能幫什麼忙。", progress = nil, completion = "靠著你的獨特能力，我們掌握了一個前所未有的良機。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61398] = {title = "餘燼宴會：傳統", objective = "收集50份燭蠟和20片殞命花。殞命花可以透過草藥學技能採收。", description = "能為雷納瑟王子的宴會提供傳統裝飾是暗隱村的榮幸。\n\n汎希爾的裝飾關鍵就是營造特定氣氛。這表示潛伏的石魔，還有大量散發殞命花香味的蠟燭。\n\n<name>，我們的資源捉襟見肘了。要找到石魔並不困難，可是工匠需要蠟才能融化新鮮的殞命花。在村子裡應該還有殘存的蠟燭和滴下來的蠟塊可以用，然後再去採收殞命花。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n契約：傳統主題"}
MultiLanguageQuestData['tw'][61399] = {title = "餘燼宴會：追思凡間", objective = "取回守衛者塔沙郎清單上的物品，為他補充貨源。", description = "只要支付合理的酬勞，那個集團就可以提供你要的裝飾。\n\n做生意最重要的就是重新補給獨一無二、引人注目的物品。既然你可以自由回到你的世界，你可以為我提供一些全新又有趣的產品。\n\n你的世界捕捉到我方顧客的許多想像力。我有一個買家正在尋找一些在艾澤拉斯上的特定原生事物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n契約：追思凡間"}
MultiLanguageQuestData['tw'][61400] = {title = "餘燼宴會：神秘鏡子", objective = "收集12枚裹起來的鏡子碎片、12枚焦黑鏡子碎片及3個燼核。", description = "我支持雷納瑟王子的努力，當然會為餘燼宴會出力！\n\n神秘鏡子十分危險，但可以為派對添增真正的刺激感。我需要許多鏡子碎片，才能及時完成足量的鏡子。\n\n你也必須幫我補充燼核，我才能把玻璃徹底熔化，作為材料。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n契約：神秘鏡子"}
MultiLanguageQuestData['tw'][61401] = {title = "餘燼宴會：汎希爾志願兵", objective = "擺放6張招募海報並測試3名罪殞城新兵。", description = "噢，嗨，又見面了！\n\n你有沒有聽說我被派來指揮餘燼宴會的守衛？如果有新兵在場，那可能會讓人留下更深刻的印象。\n\n我需得把這些招募海報貼起來。如果你能處理這件事，我可以在這裡和有興趣的新兵見面，並在你回來的時候考驗他們的戰鬥技巧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n契約：汎希爾志願兵"}
MultiLanguageQuestData['tw'][61402] = {title = "餘燼宴會：石源魔預備隊", objective = "在威權要塞擊敗敵方的石源人，以填滿靈魄罐。收集12把石源魔長刃。", description = "想要徵召預備隊，為餘燼宴會提供護衛，我們就少不了靈魄。很好，只要能讓他們動起來，忠誠的部隊就能馬上準備完畢。\n\n還得為他們準備武器才行。\n\n解決這些問題後，我就能確保王子與賓客的安全滴水不漏。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n契約：石源魔預備隊"}
MultiLanguageQuestData['tw'][61403] = {title = "餘燼宴會：瑪卓薩斯部隊", objective = "在沃魯敦釋放艾曼妮的投影，並協助她擊敗長年以來的塞斯拉克敵人。", description = "所以你那王子的小派對，招惹到多餘的注目？\n\n<艾曼妮笑了出來。>\n\n我敵人名單長得很，而且有太多人躲藏在生者的世界，想遠離我的視線。懦夫！\n\n但我終於找到一個解決方案。\n\n帶著這枚水晶到我在艾澤拉斯的遺骸上，用它在生者之間暫時投射出我的影像，我才能對我的老同胞報仇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n契約：瑪卓薩斯部隊"}
MultiLanguageQuestData['tw'][61404] = {title = "餘燼宴會：塔賓斯的茶會", objective = "從亞登曠野的遙遠的岩洞，收集純淨的水。", description = "希奧塔的派對想喝茶？塔賓斯泡的茶最棒！\n\n特殊的茶。風味別具一格。只有我泡得出來。配方需要從花園取得好水。在一座漂浮島上有好池子！\n\n你去拿水，塔賓斯來泡茶！", progress = "需要特殊的水才能製作特殊的茶，聽起來很有道理。", completion = "嗯，水喝起來很乾淨…\n\n和我一樣！我是最乾淨的！", rewards = "您會收到：\n\n契約：塔賓斯的茶會"}
MultiLanguageQuestData['tw'][61405] = {title = "餘燼宴會：神聖甜點", objective = "收集1個香蕉牛肉布丁的樣本、30個靈態肉塊及20個幻魄肉排。然後試吃史燉華的創意料理。", description = "配方十分重要。絕對不能搞丟！\n\n我從許多凡人身上認識新的食物，然後加在我的書中。最好的方式就是品嚐一些東西，才能知道什麼才叫好料。你用這個方式教我配方，並且把正確的材料帶過來，我才能一塊烹調。然後嚐嚐你做的，再嚐嚐我做的。幫我學會新食物。\n\n我幫餘燼宴會帶甜點。\n\n很公平，對不對？", progress = "你準備提供材料進行試吃了嗎？", completion = "看似簡單的反而難做。所有材料都務必完美無缺。", rewards = "您會收到：\n\n契約：神聖甜點"}
MultiLanguageQuestData['tw'][61406] = {title = "餘燼宴會：蘑菇驚喜！", objective = "採集18朵羽蓋菇、24朵紋鈴蕈菇以及4朵紫羅蘭褶邊菇。", description = "我還不知道我在蘑菇上的名氣傳得那麼遠。我很樂意為餘燼宴會提供一頓蘑菇盛宴！\n\n嗯…我需要你幫我去收集一些材料，而且我會把我最喜歡的糧秣袋借你。它可以幫你找到最棒的蘑菇。從來沒讓我失望過。\n\n我看看，我需要來自昇靈堡的朵紋鈴蕈菇和那些來自亞登曠野的花俏紫色褶邊菇。在此地最高處生長的蘑菇中，我需要羽蓋菇。你需要用爪鉤才能一路上去。", progress = "你裝滿覓食袋了嗎？", completion = "很好，聞起來很棒，而且都成熟了！你很擅長採蘑菇，&lt;name&gt;。", rewards = "您會收到：\n\n契約：蘑菇驚喜！"}
MultiLanguageQuestData['tw'][61407] = {title = "餘燼宴會：贖罪儀式", objective = "收集125塊罪孽石碎片，並把2位逃跑的靈魂帶給誓奴祭儀師。", description = "如果雷納瑟王子想和來賓分享瑞文崔斯最高天職的相關知識，展示贖罪儀式當然會讓我們覺得與有榮焉。\n\n不過，我必須請你提供協助，以最快的速度準備必要素材。\n\n在這附近捕捉想要從宮務大臣手下的腐化汎希爾逃離的靈魂。把他們帶去給我們的誓復者祭儀師，就在大廳另一頭。他們會準備這些靈魂，供我們使用。\n\n罪孽石碎片也可以協助我們辨識這些失落靈魂的罪孽。", progress = "逃跑的靈魂都躲在贖罪之殿最黑暗的角落。", completion = "多謝你，&lt;name&gt;。控罪者和我會在餘燼宴會中親自引導儀式。\n\n我們會讓每個人想起瑞文崔斯的真正目的。", rewards = "您會收到：\n\n契約：贖罪儀式"}
MultiLanguageQuestData['tw'][61408] = {title = "餘燼宴會：野生奇觀", objective = "將3隻高地符文雄鹿、8條輝芒石斑魚及4隻制伏的衛地涉水者交給妮亞。", description = "如果可以向瑞文崔斯展示亞登曠野的野生動物不是很棒嗎！\n\n你可以在瀑布附近抓到輝芒石斑魚。它們動作很快，所以你必須在它們游到附近飛快地撈起來。\n\n這一張網子可以用來制伏衛地涉水者。被你抓住之後，它們就會跟在你身後。\n\n只要你沒有敵意，高地符文雄鹿就會讓你騎乘。拜託，帶幾隻過來給我。小心那些公牛，它們可不怎麼友善。\n\n我們也會請其他人幫忙。這聽起來很有趣。", progress = nil, completion = "謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n契約：野生奇觀"}
