MultiLanguageQuestData['tw'][61522] = {title = "行屍走肉", objective = "將白骨屍體送回去給屠夫區的拉桑。", description = "這附近還有工作需要做。嗯哼。\n\n我在附近看到有個大屍體。我要去回收它的零件。\n\n你可以一起來，幫我把它拖回去給拉桑，他會喜歡。嗯哼。\n\n你看起來不大，我應該可以背著你一路來回。\n\n你準備好出發了嗎？", progress = nil, completion = "&lt;拉桑焦慮地看了一眼捕蠅怪。&gt;\n\n那…那很好！\n\n感謝你們兩個把資源帶回來！\n\n&lt;拉桑對你露出一抹緊張的微笑。&gt;", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者踏靴縫補之魂長靴縫補咒術師軟靴縫補策略家脛甲\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][61523] = {title = "行屍走肉", objective = "將白骨屍體送回去給屠夫區的拉桑。", description = "這附近還有工作需要做。嗯哼。\n\n我在附近看到有個大屍體。我要去回收它的零件。\n\n你可以一起來，幫我把它拖回去給拉桑，他會喜歡。嗯哼。\n\n你看起來不大，我應該可以背著你一路來回。\n\n你準備好出發了嗎？", progress = nil, completion = "&lt;拉桑焦慮地看了一眼捕蠅怪。&gt;\n\n那…那很好！\n\n感謝你們兩個把資源帶回來！\n\n&lt;拉桑對你露出一抹緊張的微笑。&gt;", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者踏靴縫補之魂長靴縫補咒術師軟靴縫補策略家脛甲\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][61524] = {title = "餘燼宴會", objective = "確認餘燼宴會的賓客名單和設施，然後盡全力取悅賓客。", description = "雷納瑟王子隨時都能主持這週的餘燼宴會，就等你準備好了，淵喉行者。\n\n宴會開始之前，務必跟其他工作人員確認最終賓客名單，以及各種設施是否到位。\n\n記住，我們必須讓賓客感到賓至如歸，並且讓他們相信我們知道自己在做什麼，所以選擇的設施一定要能取悅賓客！\n\n如果有任何關於賓客的問題，就去請教伊琳卡女士。\n\n等到萬事俱備，就跟我說一聲，開始舉行宴會！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61525] = {title = "餘燼宴會", objective = "確認餘燼宴會的賓客名單和設施，然後盡全力取悅賓客。", description = "雷納瑟王子隨時都能主持今天的餘燼宴會，就等你準備好了，淵喉行者。\n\n宴會開始之前，務必跟其他工作人員確認最終賓客名單，以及各種設施是否到位。\n\n記住，我們必須讓賓客感到賓至如歸，並且讓他們相信我們有經過深思熟慮，所以選擇的設施一定要能取悅賓客！\n\n如果有任何關於賓客的問題，就去請教伊琳卡女士。\n\n等到萬事俱備，就跟我說一聲，開始舉行宴會！", progress = nil, completion = "這真是一場值得回憶的宴會！\n\n你下一週要怎麼超越它啊？", rewards = "您會收到：\n\n"}
