MultiLanguageQuestData['tw'][61557] = {title = "黑暗中的回音", objective = "到奧睿博司找伯瓦爾‧弗塔根。", description = "$p，我…我被黑暗幻象所包圍。一股從托迦司內部散發出來的力量。\n\n有種熟悉的感受。一種我闊別已久，自從…\n\n來奧睿博司吧。盡快動身。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61558] = {title = "大領主所見之物", objective = "找出伯瓦爾在托迦司內感應到的事物。", description = "<索爾眉頭深鎖。>\n\n我們正在與大領主交談時，他突然感覺非常痛苦。\n\n他說他可以看到淵喉的閻獄之塔裡面，有某種東西在翻騰，。\n\n這股痛苦似乎越來越猛烈。我們得查明他感受到什麼。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][61559] = {title = "哀傷之刃誕生", objective = "與伯瓦爾和其他人一起討論幻象。", description = "在安杜因的父親失蹤時，我照顧他一如己出。現在看到他變成那個樣子，而且還是拜希瓦娜斯所賜…\n\n<伯瓦爾的雙眼燃起火焰。>\n\n一定要想想辦法。\n\n休息一下。在你準備討論下一步時告訴我一聲。", progress = nil, completion = nil, rewards = nil}
