MultiLanguageQuestData['tw'][61789] = {title = "冒險者：迷失的希比兒", objective = "希奧塔極度推崇迷失的希比兒。\n\n另外，她來訪時在門口丟下了一大袋石源魔軍團的頭和兩大箱的靈魄。所以，看來她早就開始為我們作戰了。\n\n就來看看她和盟友一起行動時的表現如何吧。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：迷失的希比兒"}
MultiLanguageQuestData['tw'][61790] = {title = "冒險者：芙兒卡", objective = "任何能在餘燼區生存得和芙兒卡一樣久的人都頑強得像顆石頭。\n\n她留了幾手能幫助我們打倒敵人。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：芙兒卡"}
