MultiLanguageQuestData['tw'][61839] = {title = "輕咬灌木", objective = "收集歿路沼澤藤根。", description = "<小吞食者飢餓地輕咬你的腳跟，希望得到你的保護。牠是不是會喜歡這裡的哪種植物？>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n爬藤蠕動的零錢包"}
MultiLanguageQuestData['tw'][61840] = {title = "藤根特餐", objective = "收集歿路沼澤藤根。", description = "<小吞食者又出現了，你很明顯看得出來牠想要更多的歿路沼澤藤根。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n覆藤灌能紅寶石"}
