MultiLanguageQuestData['tw'][61869] = {title = "搜索", objective = "檢查工頭的箱子，尋找有價值的東西。", description = "澤瑞奎斯…和裡頭的一切是我們的了。\n\n統御者參與過這座亡者之城的設計。能親眼目睹他親手塑造這座亡城，真是讓人眼睛為之一亮。\n\n最好去搜一下房間。或許裡頭會有他原本用過的工具。", progress = "你有什麼發現？", completion = "這是屬於統御者的！", rewards = "您會收到：\n\n"}
