MultiLanguageQuestData['tw'][61871] = {title = "當前事項", objective = "回到祖達薩的女妖之嚎去找納薩諾斯‧凋零者。", description = "勇士，你做得很好。母親大人和我會想辦法知道下一步該怎麼做。\n\n你最好回去處理你手頭上的事了，然後想盡辦法強化你那條項鍊。\n\n當我和母親大人解決這邊的事情後，我知道該怎麼聯絡你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61872] = {title = "當前事項", objective = "回到波拉勒斯登上風之救贖，去找海弗德‧龍禍。", description = "勇士，你做得很好。母親大人和我會想辦法知道下一步該怎麼做。\n\n你最好回去處理你手頭上的事了，然後想盡辦法強化你那條項鍊。\n\n當我和母親大人解決這邊的事情後，我知道該怎麼聯絡你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61874] = {title = "暗影之境：冰寒的召集", objective = "到奧格瑪的葛羅瑪許堡外面見達瑞安‧莫格萊尼。", description = "<class>，時候到了。\n\n大領主伯瓦爾‧弗塔根要求你前往冰冠城塞頂端。在奧格瑪和我碰面，我會帶你去見他。\n\n我可不打算讓他等太久。", progress = nil, completion = "很好，你來了。\n\n在這種緊急時刻，我們需要像你這樣的英雄。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61875] = {title = "收集露水", objective = "在亞登曠野的森林裡收集30滴薊花露水。", description = "薊花是個很奇特的物種。它的根會深入土裡並汲取深埋許久的水源。透過這些水，它能將這片土地的精華匯聚在露水裡，而我們的工匠會利用這些露水打造強大的武裝。\n\n幫我們收集這些露水，我們會獎勵你的。\n\n快點，它很快就會蒸發！", progress = "露水很快就會蒸發，動作快！", completion = "這些露水絕對能幫工匠們很大的忙！\n\n謝謝你，小傢伙。", rewards = "您會收到：\n\n薊枝戒環靈魂篩選者根鬚谷蔽項鍊暮色守衛鐮刀暮色守衛短弓靈苔法衣液鋼胸甲果姆外殼護胸符文看管者外套符文看管者長手套靈苔手套果姆外殼之襲\n                            顯示 21 更多                        靈苔頭冠果姆外殼兜帽符文看管者護盔符文看管者束褲符文看管者肩衛符文看管者護腕永夜披氅喚醒者蕨葉凋林裂片亞登之露珍珠星光捕捉器星穹橡實妖精曠野琥珀星界軟木發光的銀莓暮落塊莖冬日嫩枝袋中的小果姆失竊魔精圖騰感激禮賜曠野獵者"}
MultiLanguageQuestData['tw'][61876] = {title = "強化之心", objective = "收集血肉塑形者之心。", description = "莫格萊尼來訪昇靈堡時我們談了很久。他提到，如果我們殺得了藩侯，那他的心臟可以用來強化晉升紋章。\n\n這名藩侯擁有改變形態的力量，這是只有少數人才能駕馭的力量。雖然他的下場很悽慘，但如果我們能借助那股力量，那我們的晉升者會獲得前所未見的力量。\n\n這不是我們的作風，但我們的作風一直在改變，我是這麼認為的。或許這是我們走向新道路的第一步。", progress = "必須完成這件事。", completion = "我對自己不需要負責把那東西帶回昇靈堡而感到欣慰。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61877] = {title = "返回樂土堡", objective = "到昇靈堡的樂土堡晉升紋章處見珊卓亞。", description = "我們快點把心臟帶去樂土堡吧。\n\n暗影之境裡有許多不懷好意的東西會為了這股力量攻擊我們。淵喉行者，隨時保持警覺。\n\n我們今天會把勝利帶回去給同袍。", progress = nil, completion = "我很高興再次成為我們的一員。瑪卓薩斯不符合我的風格。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61878] = {title = "偉大的紋章", objective = "把血肉塑形者之心放入晉升紋章。", description = "你準備好之後，只需要把心臟放到晉升紋章這邊的球體裡就好。\n\n米卡尼寇斯的手藝會確保它的能量正確連結，幫助我們進行晉升儀式，而它的力量應該也能保護紋章不受進一步的攻擊。\n\n願傀儡家族再也不會進犯我們的國度。", progress = "<這看起來像是珊卓亞指示你放置心臟的球體。>", completion = "&lt;血肉塑形者之心很輕易就放到發光的球體內了。當它進去之後，你聽到紋章內發出了微弱的喀喀聲，就好像它早就準備好接收這股力量了。\n\n琪瑞安嶄新的世代也就此展開。&gt;", rewards = "您會收到：\n\n名望名望"}
