MultiLanguageQuestData['tw'][61880] = {title = "榮譽出席", objective = "通知特梅爾墓穴守衛者凱希爾將會出席餘燼宴會。", description = "能夠成為餘燼宴會的第一位來賓是我的榮幸。\n\n請告訴雷納瑟王子和你們其他同胞，只要你想打開大門，我肯定願意參加。", progress = nil, completion = "如果凱希爾要來，我們最好確保這會是一場正式的活動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][61882] = {title = "正式娛樂", objective = "通知特梅爾你已為餘燼宴會安排好了娛樂活動。", description = "在第一場餘燼宴會中，你選擇了如此謙遜又正式的娛樂，一定可以讓控罪者開心。\n\n我很期待前往宴會。", progress = nil, completion = "遠古儀式？這才是我心目中的派對！", rewards = "您會收到：\n\n"}
