MultiLanguageQuestData['tw'][61892] = {title = "餘燼宴會大使", objective = "在暗影之境完成世界任務。", description = "想擴大你的影響力很簡單。\n\n找些人。問問他們想要什麼。交給他們。\n\n恭喜。你現在對他們而言有影響力了。\n\n如果我們想要其他界域交流、並拉攏他們，我們一定要用更大的規模來做相同的事。\n\n去其他界域跑跑吧。給他們想要的東西。擴大我們的影響力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n工作人員：大使"}
MultiLanguageQuestData['tw'][61893] = {title = "餘燼宴會大使", objective = "在暗影之境完成世界任務。", description = "想擴大你的影響力很簡單。\n\n找些人。問問他們想要什麼。交給他們。\n\n恭喜。你現在對他們而言有影響力了。\n\n如果我們想要其他界域交流、並拉攏他們，我們一定要用更大的規模來做相同的事。\n\n去其他界域跑跑吧。給他們想要的東西。擴大我們的影響力。", progress = nil, completion = "其他國度的連絡人回報，他們聽到的閒聊都正面肯定你在那邊的行動。\n\n&lt;伊琳卡女士微笑著。&gt;\n\n我們的影響力成長了。", rewards = "您會收到：\n\n工作人員：大使"}
MultiLanguageQuestData['tw'][61894] = {title = "餘燼宴會大使", objective = "在暗影之境完成世界任務。", description = "想擴大你的影響力很簡單。\n\n找些人。問問他們想要什麼。交給他們。\n\n恭喜。你現在對他們而言有影響力了。\n\n如果我們想要其他界域交流、並拉攏他們，我們一定要用更大的規模來做相同的事。\n\n去其他界域跑跑吧。給他們想要的東西。擴大我們的影響力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n工作人員：大使"}
MultiLanguageQuestData['tw'][61895] = {title = "餘燼宴會大使", objective = "在暗影之境完成世界任務。", description = "想擴大你的影響力很簡單。\n\n找些人。問問他們想要什麼。交給他們。\n\n恭喜。你現在對他們而言有影響力了。\n\n如果我們想要其他界域交流、並拉攏他們，我們一定要用更大的規模來做相同的事。\n\n去其他界域跑跑吧。給他們想要的東西。擴大我們的影響力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n工作人員：大使"}
MultiLanguageQuestData['tw'][61896] = {title = "臥底護衛", objective = "從瑪卓薩斯收集刺客日常訓練指南，並從亞登曠野收集20份附魔欺詐者之塵。", description = "你知道為什麼汎希爾要把石源魔雕成不同的外形嗎？\n\n因為外觀的多樣化，就可以帶來戰略的多樣化。我們的不同外形，讓我們具備不同的功用。\n\n我們需要新的外形，才能讓宴會的防禦固若金湯。\n\n靠著正確的訓練與工具，汎希爾守衛可以偽裝成接待員，融入大庭廣眾之間。\n\n在賓客之間遊走而不引人側目，他們就能第一時間處理任何威脅。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設置：歡迎禮品組"}
MultiLanguageQuestData['tw'][61898] = {title = "一口點心", objective = "收集昇靈堡的起司和瑪卓薩斯的酸麵包酵母。", description = "評論來了，$p。我們的菜單過度傾向瑞文崔斯的口味！\n\n每一場最好的宴會都有異國的小盤開胃菜和其他特產，讓賓客每次前來都充滿期望。\n\n像我們這樣的宴會，最自豪的就是經常出現來自其他國度的賓客，我們一定要做得更好！\n\n不用擔心，在孜孜不倦的研究下，我已經草擬了一份十分特殊的材料清單，就等你為我收集。\n\n把東西帶給我，我就會用盤子永生永世為顧客效勞！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設置：開胃菜"}
MultiLanguageQuestData['tw'][61899] = {title = "靈魄品鑑", objective = "從亞登曠野、昇靈堡、瑪卓薩斯和瑞文崔斯收集新鮮的靈魄。", description = "你引發了一種趨勢，$p！\n\n你遊歷在暗影之境不同國度間的奇妙旅程，在瑞文崔斯的精英人士間掀起追求異國情調的新風潮。如果東西來自瑞文崔斯之外，那汎希爾就會想要試試看。\n\n而且我很清楚下一個突破點在哪裡：靈魄品鑑！\n\n想想看：我們從行經的不同國度中，帶回各地的新鮮靈魄，對了，這邊的「我們」其實是指「你」。\n\n那些社交名流只需淺啜一口，就能裝模作樣地對靈魄原產地品頭論足一番。", progress = "你找到了好多靈魄。只不過是喝就有這麼多？", completion = "阿嘻已經向靈魄大師指明他心目中負責帶領大家品嚐靈魄的人選。\n\n我會安排她去辦這件事，並把這個東西交給她。", rewards = "您會收到：\n\n設置：靈魄試吃品"}
MultiLanguageQuestData['tw'][61900] = {title = "舒服的椅子", objective = "從昇靈堡收集30份柔軟靈狐毛皮，並從亞登曠野收集30份馴服之木。", description = "我想讓賓客坐下來。\n\n久站很難受。我很清楚，因為我經常站著。\n\n賓客可以舒舒服服的坐下來。\n\n我為所有賓客製作舒適的椅子。\n\n賓客越開心，就會待得越久！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n設置：舒適椅子"}
