MultiLanguageQuestData['tw'][61968] = {title = "『翼』無反顧", objective = "從亞登蛾身上收集28片無瑕的亞登蛾翅鱗。", description = "孜孜不倦的亞登蛾已經在無數的時光中為曠野獵者提供製造護甲的鱗片。\n\n現在，因為我們的注意力被界域遭遇的威脅以及靈魄乾旱給分散，要找到完美的鱗片是件越來越困難的事了。\n\n只有最高品質的鱗片才符合我們的需求。如果你在旅行的過程中有找到的話，請交給我們。我一定會確保你獲得豐厚的獎賞。", progress = "你拿到鱗片了嗎？", completion = "啊，多麼優良的品質！你做得很好！", rewards = "您會收到：\n\n谷蔽項鍊暮色守衛權杖靈苔法衣液鋼胸甲果姆外殼護胸符文看管者外套液鋼脛甲靈苔輕鞋果姆外殼脛甲符文看管者長靴靈苔頭冠果姆外殼兜帽\n                            顯示 22 更多                        符文看管者護盔靈苔護腿果姆外殼褶裙符文看管者束褲符文看管者繫腰喚醒者蕨葉女王近衛之護凋林裂片亞登之露珍珠星光捕捉器星穹橡實獵豹活力堅定追擊妖精曠野琥珀星界軟木發光的銀莓暮落塊莖冬日嫩枝袋中的小果姆失竊魔精圖騰感激禮賜曠野獵者"}
MultiLanguageQuestData['tw'][61981] = {title = "補充靈魄庫", objective = "收集靈魄來源，然後存入瑞文崔斯罪殞城的靈魄庫中。", description = "好，聽清楚了：我們需要靈魄。\n\n不是一點點，是很多很多。任何值得耗費心力去做的事都需要靈魄才辦得到。這就是暗影之境的運作法則。而且在我們解決戴納瑟斯造成的這團混亂之前都必須如此。\n\n所以呢，我們需要你運用想像力去求來的、借來的、偷來的、拐來的、搶來的、騙來的、佔來的、贏來的、詐來的或任何你可以獲得大量靈魄並拿來捐助的方法。\n\n把靈魄帶來給我，我會好好把它保存起來並讓你能妥善運用。", progress = nil, completion = "這才是所謂的灰色職業道德嘛。你替我們弄來的靈魄馬上就能派上用場。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][61982] = {title = "補充靈魄庫", objective = "收集靈魄來源魄，然後存入昇靈堡樂土堡的靈魄庫中。", description = "你好啊，淵喉行者。\n\n當我們對昇靈堡的影響力日益成長時，我們對我們最寶貴的資源…靈魄…的需求也與日俱增。\n\n我們必須補充靈魄庫存。請到處尋找，盡可能收集靈魄，然後送回這裡。\n\n補充了寶貴的庫存後，我們就能把靈魄引導到最需要的地方。\n\n<class>，莫忘職責。", progress = nil, completion = "淵喉行者，感激不盡，我們絕不會浪費它們的。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][61983] = {title = "補充靈魄庫", objective = "收集靈魄來源，然後存入瑪卓薩斯統御者之座的靈魄庫中。", description = "淵喉行者，我們需要你的力量。\n\n敵對家族的實力每分每秒都在成長。為了跟他們對抗，我們必須找到新的靈魄來源，確保靈魄供應無虞。\n\n請到處搜索，收集這種珍貴資源，然後送回聖所這裡。別讓任何人妨礙你！\n\n有了你的幫忙，敵對家族一定會一個接著一個覆滅，我們終將傲視群雄！", progress = nil, completion = "你的貢獻讓我們在戰場上所向無敵。最終的勝利將屬於我們！", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][61984] = {title = "補充靈魄庫", objective = "收集靈魄來源，然後存入亞登曠野森林之心的靈魄庫中。", description = "你好啊，淵喉行者。\n\n「亞登曠野之心」特那艾奇亞德在我們的照顧之下繁盛卓茂，但我們的聖所仍然需要更多靈魄。\n\n重生的循環以及我們的使命絕對不能中斷。\n\n為了幫助女王陛下，我們必須獲得更多靈魄。你能幫我們補充儲量嗎？", progress = nil, completion = "你提供的靈魄將會滋養我們珍貴的林地。我們感謝你。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][61985] = {title = "喚醒沉睡者", objective = "喚醒8個沉睡的靈魂。", description = "<name>，這片土地會對我說話。亞登曠野是個理解循環的界域，但是從沒面臨過這樣的靈魄乾旱。\n\n如果我們要撐過這場危機的話，那我們需要這裡所有的居民出手相助。\n\n許多靈魂還在森林以及山丘上沉眠。如果他們能提供一些靈魄，那或許我們就能撐久一點。如果你在旅途中碰到了任何靈魂，請喚醒他們，把他們送來我這裡。", progress = nil, completion = "這些露水絕對能幫工匠們很大的忙！\n\n謝謝你，小傢伙。", rewards = "您會收到：\n\n薊枝戒環靈魂篩選者根鬚谷蔽項鍊暮色守衛權杖暮色守衛鐮刀暮色守衛戰棍暮色守衛枝條果姆外殼護胸符文看管者外套符文看管者長手套果姆外殼之襲靈苔頭冠\n                            顯示 20 更多                        果姆外殼兜帽符文看管者護盔液鋼腿鎧靈苔護腿果姆外殼褶裙符文看管者束褲喚醒者蕨葉凋林裂片亞登之露珍珠星光捕捉器星穹橡實妖精曠野琥珀星界軟木發光的銀莓暮落塊莖冬日嫩枝袋中的小果姆失竊魔精圖騰感激禮賜曠野獵者"}
MultiLanguageQuestData['tw'][61996] = {title = "說出魔法咒語", objective = "協助莎賓娜在瑞文崔斯學會12個新法術。", description = "從我第一次施放法術以後，我就無法自拔愛上魔法了。\n\n這才沒有像那些巫妖說的那麼難。你專心在思緒上，把咒語說出來，魔法就發生了！\n\n瑞文崔斯的亞崎汎姆裡有很多紀錄了古老法術的秘典。幫我收集那些秘典，這樣我就能學習新的法術了！您會收到：\n\n\n\n等級 60–70", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者護脛縫補策略家重腿甲\n\n等級 60–60縫補之魂馬褲縫補咒術師護腿\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62000] = {title = "選擇你的使命", objective = "和誓盟交談。決定你的道路如何與使命產生交集。", description = "每個誓盟對暗影之境都很重要。雖然他們之間各自獨立、職責有所歧異，但是需要他們的努力成果，才能完成使命。\n\n所有誓盟都需要成長，才能面對監禁者的威脅。可是你不能分頭效力，只能專注在一條路上。其他凡人有可能採取不同的選擇。\n\n和你這些未來的盟友聊聊，然後在我面前的暗影之境地圖做出你的選擇。", progress = nil, completion = "一切都如預期。永遠信賴審斷者的智慧。", rewards = "您會學到：\n\n敗血症\n\n下列法術會施放在您身上：\n\n羽飾誘餌\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][62041] = {title = "有害之光", objective = "使用玫沸的癒傷蛻皮治療15個光灼流亡者。", description = "我聽說過瑞文崔斯一團混亂的事情。據說流亡者被逼瘋，在乾枯之地被活活燒死。\n\n我腦子裡都是那些受苦的人，讓我覺得非得為他們做點什麼事。\n\n如果你要去那裡，拜託讓我一起去。我只是想盡可能幫助更多人！", progress = nil, completion = "受苦對瑞文崔斯的居民來說司空見慣，但你和玫沸確實幫助了一些人。\n\n做得好。", rewards = "您會收到：\n\n\n\n任意等級縫補先驅者戰爭腰帶優良肢體回收的補給物資\n\n等級 60–70縫補之魂腰帶縫補咒術師繫腰縫補策略家束腰"}
MultiLanguageQuestData['tw'][62043] = {title = "證明你的能耐", objective = "完成琪瑞安的任務。", description = "<name>，你必須再次向我們證明你的價值。\n\n我們還沒有忘了你的背叛。\n\n但你卻說你尋求懺悟之道。這項任務能展現你是否認真想要贏回我們的信任。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62044] = {title = "正面對決", objective = "擊敗噬嚥吞食者", description = "<吞食者顯然變大了，牠用頭示意你看向另外一隻吞食者，彷彿正在催你攻擊牠。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n閃閃發亮的紅寶石項鍊"}
MultiLanguageQuestData['tw'][62045] = {title = "躍躍欲試", objective = "擊敗噬嚥吞食者", description = "<那隻吞食者再次昂首闊步，準備挑起更多爭鬥，用目光威脅最近的吞食者。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n握著鬥棍的汎希爾人手臂"}
MultiLanguageQuestData['tw'][62046] = {title = "新的同伴", objective = "擊敗擅闖的吞界者。", description = "<那隻吞食者已經長成龐然大物，比得上這個地方的其他大多數吞食者。牠顯然想跟在你身邊，不過，牠如果離吞界者太遠，似乎會很不安。或許只要你們一起打倒一隻吞界者，吞界者就不會對吞食者有這麼大的影響力。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n忠誠吞食者"}
