MultiLanguageQuestData['tw'][62213] = {title = "仲介者的交易", objective = "取回仲介者飾物。", description = "嘿，<name>。我有一個能大賺一筆的商業提案，能幫我…我們…很大的忙！聽好了，如果我們能幫奧納寧導正一個事情不如預期的商業貿易，那他就有意願把補給品交給我們。\n\n他似乎有好幾個合夥人出去執行任務之後就一去不回。他需要我們沿著這些合夥人走的路並取回他們沒能交送的物品。很簡單吧？\n\n為了確保我們不會慘遭不測，我自作主張拿了一些或許能幫上我們忙的物品。\n\n所以，你要來嗎？", progress = "你找到那個東西了嗎？", completion = "我就知道淵喉行者辦得到。", rewards = "您會收到：\n\n優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62214] = {title = "墮滅部隊", objective = "在淵喉的墮滅堡殺死淵誓部隊。\n\n建議玩家 [3]", description = "淵喉行者，我們若要繼續生存，就要牽制敵人。\n\n果戈亞的靈魂之流滿盈，淵誓者的軍容更加壯盛。\n\n墮滅堡又有了新募部隊。我們不能讓淵誓者繼續增加兵力。\n\n前往墮滅堡，消滅他們的部隊。事情完成了之後，再回來找我領取獎勵。", progress = nil, completion = "這只是一場小勝利，淵喉行者。還有很多仗要打。", rewards = "您會收到：\n\n不羈魂靈強大的不羈魂靈勇武魂靈強大的勇武魂靈強大的盡責魂靈盡責魂靈高傲魂靈強大的高傲魂靈沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][62216] = {title = "訓練計畫", objective = "殺死德卡迪厄。", description = "克拉錫中士是優秀的訓練官，但這些新兵需要由曾經真正在戰場上拋頭顱灑熱血的戰士給予適當的訓練。像我這樣的戰士！\n\n而且我剛好知道哪裡有能鞭策這些部隊進入狀況的戰鬥。\n\n我們去好好教他們一兩招吧。", progress = nil, completion = "你們兩個是不錯的搭檔。戰鬥中，可靠的夥伴不可或缺。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者護胸縫補之魂上衣縫補咒術師外套縫補策略家鍊衫\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62217] = {title = "實戰訓練", objective = "到昇靈堡的永恆熔爐消滅15個棄誓者士兵。", description = "雖然不是出於我們之手，但瑪卓薩斯確實對昇靈堡的琪瑞安造成了傷害。我們必須盡可能補償。\n\n棄誓者仍持續威脅著他們。這是展現我們的誠意，同時讓新兵累積點作戰經驗的絕佳機會。", progress = nil, completion = "你和馬茲合作無間。每當你需要的時候，他會幫你抵擋攻擊。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者護胸縫補之魂上衣縫補策略家鍊衫\n\n等級 60–60縫補咒術師外套\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62218] = {title = "妖精之泉", objective = "到亞登曠野的爍瀑盆地向努密努魯回報。", description = "努密努魯花了很多時間在保護和照顧整個亞登曠野的許多飛靈。有一些他們照顧的飛靈已經失蹤一陣子了，讓他們很擔心。\n\n去和努密努魯回報，看看你能不能幫他們找回那些四散的樹精。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62219] = {title = "心有旁騖", objective = "找到河花、月風及迅飛，說服他們回去找努密努魯。", description = "我的飛靈朋友總是在追逐無止盡的幻想，所以不是那麼常出現在大家面前。\n\n他們天馬行空的個性常常會讓他們誤入歧途，因此感到分心或沮喪。\n\n去尋找我的朋友，一定要把他們帶回我的根源。那麼，你和他們都會獲得回報的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
