MultiLanguageQuestData['tw'][62250] = {title = "全新冒險等著你", objective = "回到暴風城，展開新的冒險。克羅米的魔法會在你達到70級的時候失效，並將你送回暴風城。", description = "<name>！現在的世界需要你。事情變得…嗯，你最好親自回去看。\n\n我會接手並完成你手頭上的事然後再趕回去。我快要沒辦法讓你繼續待在過去的世界了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62256] = {title = "資產抽取", objective = "前往亞登曠野，找出塔比西亞並取回異界蛋。", description = "嘿，是我的好朋友<name>！聽著，我有點小問題需要幫忙。我一直在想辦法和仲介者歐拉瑞納談筆生意，但他需要有人幫他解決一點事情才肯答應。\n\n事情就是他有個助理帶著一個稀有物品消失了。他要求我…我們…找到並交還他遺失的財產。\n\n那個助理最後的目擊地點是在亞登曠野。我知道，那是個怪地方，對我來說太光明了。但是，我…我們…真的很需要達成這項交易！\n\n所以說，你準備好要出發了嗎？", progress = "我相信你還沒忘記你答應的交易吧？", completion = "唉呀，這還真是精緻啊。你這個重鑄後的夥伴說過你一定能成功，但你做得真是太完美了！\n\n去告訴他，我就把這當成他債務的分期付款款項吧。", rewards = "您會收到：\n\n優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62258] = {title = "翱翔於昇靈堡", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][62259] = {title = "佈滿靈魄的捕夢網", objective = "把附魔的捕夢網送還給夢歌沼地中的晨綻樹林長。\n\n已提供物品：\n", description = "你意外找到了一個附魔的捕夢網，放在很偏僻的地方，所以捕捉到大量靈魄卻還未收割。在夢歌沼地附近的晨綻森樹林長一定會很感謝你能把它平安送回。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62261] = {title = "研磨器", objective = "收集12顆磨刀石以及3個削骨研磨器。", description = "要讓我的手保持鋒利真的是件很困難的事。一直又劈又砍的，它們很快就鈍掉了！我這個小女孩又能怎麼辦？\n\n天選者家族會製作非常高品質的磨刀石。我猜他們也不會就這樣親手奉上，但我的刀刃應該可以說服他們。\n\n不如我們去拜訪一下，看看他們可以那裡有多少備用的石頭？", progress = "你殺光他們了嗎？", completion = "看來「斬首」的「談判」方式成功了。\n\n謝謝你，淵喉行者。這些磨刀石一定能派上用場。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者粉碎手套縫補之魂扼殺手套縫補咒術師手套縫補策略家護手\n\n任意等級優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62262] = {title = "餵養蘑菇", objective = "從天譴岸地的幽影菇上取得20份成熟的孢子樣本。", description = "我正在研究替代性防禦方案，才剛剛找到突破點，就發現孢子樣本用完了！\n\n我用的蘑菇只會生長在東南方，一個令人特別不舒服的地方。想要收集份量合適的樣本，你得 - 我該怎麼說 - 餵飽它們。\n\n不要問我為什麼，但很明顯的一點是，只要用附近的完整、腐化屍體餵養它們，成熟的速度最快。\n\n試著引誘幾個不死怪到我們的蘑菇朋友身邊。那應該可以為它們提供所需的養份，長得頭好壯壯。", progress = "有找到樣本嗎？", completion = "噢，這些真不錯！\n\n我希望沒弄髒你的手。", rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][62263] = {title = "前進未知！", objective = "調查未知的地區。", description = "啊，你來得正是時候。我有一個大發現。\n\n我成功建立一個連結，通往比以往更加遙遠的地方。\n\n你問我是怎麼辦到的？就是努力再努力！不過這道理你早就懂了，你幾乎跟我一樣努力。現在該是你登場的時候了！\n\n想不想來一場更加刺激的冒險？", progress = nil, completion = "有閒暇能靜靜坐下來好好思考一定感覺很棒。\n\n但我自己卻沒有什麼時間，我光是要維持這地方的運作就有做不完的工作了。\n\n但是，你願意幫助老烏龜還真是慷慨啊。", rewards = "您會收到：\n\n谷蔽項鍊暮色守衛鐮刀暮色守衛重槌暮色守衛枝條暮色守衛短弓液鋼戰盔靈苔法衣果姆外殼護胸符文看管者外套符文看管者長靴符文看管者長手套靈苔手套\n                            顯示 14 更多                        果姆外殼之襲果姆外殼褶裙符文看管者肩衛果姆外殼披肩永夜披氅凋林裂片亞登之露珍珠星光捕捉器星穹橡實星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62265] = {title = "全新冒險等著你", objective = "回到奧格瑪，展開新的冒險。克羅米的魔法會在你達到70級的時候失效，並將你送回奧格瑪。", description = "<name>！現在的世界需要你。事情變得…嗯，你最好親自回去看。\n\n我會接手並完成你手頭上的事然後再趕回去。我快要沒辦法讓你繼續待在過去的世界了！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62275] = {title = "昇靈堡", objective = "與塔因納拉交談。", description = "晉升者接連遭受瑪卓薩斯的突襲，以及名為棄誓者的墮落同胞所入侵，如果沒有人伸出援手，他們會漸漸失去對昇靈堡的控制。", progress = nil, completion = "昇靈堡現在處境危急，需要你的幫忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62276] = {title = "死者飲品", objective = "收集24罐純化花蜜以及2個侍者。", description = "棄誓者正在大肆破壞昇靈堡的神殿，而逃竄的志士就這樣把補給留在原地。\n\n那些甜美的飲料就這樣落入棄誓者的手裡了？不可能！\n\n我們沒辦法救出所有的志士，但是我們能夠確保棄誓者無法染指那些補給品。況且，我們需要一些飲料。", progress = "你幫我們找到補給品了嗎？", completion = "呃，我看到你帶了幾個朋友回來？", rewards = "您會收到：\n\n\n\n任意等級死亡天選者的軍旗優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62277] = {title = "亞登曠野", objective = "與塔因納拉交談。", description = "亞登曠野仍然面臨佐司特和其他邪惡勢力的威脅。\n\n凜冬女王需要你幫忙抵禦企圖摧毀亞登曠野的勢力。", progress = nil, completion = "亞登曠野會很感謝你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62278] = {title = "瑪卓薩斯", objective = "與塔因納拉交談。", description = "由於各大家族動盪不定，統御者的忠誠軍隊難以在瑪卓薩斯穩固勢力。\n\n他們需要你的協助來扭轉局勢。", progress = nil, completion = "效忠統御者的軍隊需要你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62279] = {title = "瑞文崔斯", objective = "與塔因納拉交談。", description = "戴納瑟斯王的背叛行為讓混亂在瑞文崔斯蔓延。\n\n他們非常需要你出手幫忙！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
