MultiLanguageQuestData['tw'][62284] = {title = "觀察戰鬥", objective = "在隨機戰場中獲得榮譽值。", description = "你們這些凡人顯然在衝突中越挫越勇。我們集團的成員對此興趣濃厚，想要實際觀察你的戰鬥能力。\n\n你們似乎很喜歡在爭奪中的領土上打來打去。觀察這類地域性行為能讓我獲益良多，而且或許也能為你自己創造機會。\n\n你願意參與嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n多功能靈魄容器榮譽點數征服點數征服點數"}
MultiLanguageQuestData['tw'][62285] = {title = "觀察戰爭", objective = "在史詩戰場中獲得榮譽值。", description = "你對於衝突的熱衷在奧睿博司引起了熱烈的討論，凡人。我們集團的成員對此興趣濃厚，想要實際觀察你的戰鬥能力。\n\n儘管我知道你們的世界最近才打完一場大戰，但我聽說大規模衝突仍在某些地區上演。\n\n你能不能安排一次實戰表演？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n多功能靈魄容器榮譽點數征服點數征服點數"}
MultiLanguageQuestData['tw'][62286] = {title = "觀察練習戰", objective = "在競技場練習戰中獲得榮譽值。", description = "你的族人透過衝突製造的娛樂效果令人陶醉，凡人。我們集團的成員對此興趣濃厚，想要實際觀察你的戰鬥能力。\n\n聽說，透過小規模練習戰，你們最厲害的勇士就能證明自己的實力比對手還要傑出。觀察這類比賽，我的族人無疑能學到不少東西。\n\n能請你示範一下嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n多功能靈魄容器榮譽點數征服點數征服點數"}
MultiLanguageQuestData['tw'][62287] = {title = "觀察競技場", objective = "在競技場中獲得榮譽點數。", description = "你們世界的人似乎在衝突中越挫越勇，凡人。我們集團的成員對此興趣濃厚，想要實際觀察你的戰鬥能力。\n\n在條件受限的情況下進行小規模遭遇戰，應該能讓我得到不少情報，而且你也能趁機賺一筆。\n\n你覺得如何？", progress = nil, completion = "事情順利完成總是讓人神清氣爽！觀察者一定會很高興。", rewards = "您會收到：\n\n多功能靈魄容器榮譽點數征服點數征服點數"}
MultiLanguageQuestData['tw'][62288] = {title = "觀察團隊行動", objective = "在積分戰場中獲得榮譽點數。", description = "你們透過衝突謀求發展的行為真是令人陶醉，凡人。我們集團的成員對此興趣濃厚，想要實際觀察你的戰鬥能力。\n\n聽說，你們最讓人印象深刻的武鬥表演就是兩支預組隊伍同場較勁。我的族人對這類比賽相當陌生。\n\n你願意示範一下嗎？", progress = nil, completion = "這次安排讓我收集到非常實用的資訊。觀察者一定會很高興。", rewards = "您會收到：\n\n多功能靈魄容器榮譽點數征服點數征服點數"}
