MultiLanguageQuestData['tw'][62368] = {title = "重新贏得我們的信任", objective = "完成琪瑞安的任務。", description = "嗯，<name>，看來你對於要重新回到我們的崇高使命是認真的。\n\n看來你對懺悟之道是認真的。這項任務應該能證明你確實有意願重新加入我們的行列。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62371] = {title = "特那希：無聲的警告", objective = "到特那希迷霧擊敗崔朵瓦。", description = "特那希的樂音會隨著林地凋零而一同衰退，然而現在卻是一片寂靜。也已經好一陣子沒有聽見歐法蘭樹林長的聲音了。樹木低語著幽暗的陰影、不和諧的歌曲，以及將死的枯根。一切都很糟。\n\n亞登曠野之友啊，快點前去盤根之家吧。深入迷霧之中。剷除威脅我們的事物。", progress = nil, completion = "你的協助已經在樹根之間傳唱開來了。謝謝你，森林之友。", rewards = "神聖林地脛甲霧紗便鞋林地噬咬者護足橡木集會所長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][62382] = {title = "探索未知", objective = "調查未知的地區。", description = "你來拜訪瑪拉茲莫斯了嗎？我有一個特別的任務要交給你。\n\n我的一個芽苗發現了一個奇怪的地方，那是我從來沒看過的地方。\n\n我不確定那裡有什麼，也不知道安不安全。這時候就是我可靠的蘑菇法師登場的時候了！\n\n<name>，你覺得如何？要不要來場冒險？", progress = nil, completion = "她人看起來很不錯。你說蘑菇王國嗎？嗯…聽都沒聽過。現在的年輕人總是胡搞瞎搞…", rewards = "您會收到：\n\n薊枝戒環谷蔽項鍊暮色守衛小刀暮色守衛重槌暮色守衛枝條暮色守衛短弓暮色守衛盾牌靈苔法衣液鋼胸甲果姆外殼護胸符文看管者外套符文看管者長手套\n                            顯示 30 更多                        液鋼護手靈苔手套果姆外殼之襲液鋼腿鎧靈苔護腿果姆外殼褶裙符文看管者束褲符文看管者肩衛液鋼肩鎧靈苔襯肩果姆外殼披肩液鋼扣環靈苔腰環果姆外殼裹腰符文看管者繫腰永夜披氅女王近衛之護凋林裂片亞登之露珍珠星光捕捉器星穹橡實迴盪呼喚獸群之力元素匯流晦影烈能星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62388] = {title = "祭儀家族", objective = "提高你的名望。", description = "祭儀師是這場戰爭的幕後黑手。每一個背叛行為都是出自於他們的命令。\n\n光憑武力，是無法跟他們的巫術抗衡的。只有查清楚他們在謀劃什麼，才有獲勝的機會。\n\n繼續援助我們的部隊。我會想辦法潛入祭儀家族。", progress = nil, completion = "看來我們或許有辦法深入祭儀家族了。\n\n不要誤以為這個巫妖是盟友。他有他自己的打算。我們只是暫時有共同的目標…我們可以善用這一點。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62389] = {title = "重新贏得我們的信任", objective = "完成汎希爾的任務。", description = "看來你已經邁出贏回我們信任的第一步了。\n\n現在，你必須證明這不會又是我們另一次錯誤的關係了。\n\n這項任務應該能證明你確實有意願重新加入我們的行列。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62390] = {title = "統計身體", objective = "在瑪卓薩斯附近收集30個憎惡體的部位。", description = "我和幾名在傀儡家族外做事的血肉工藝師很熟。如果我們可以替他們找到一些材料，那他們就可以供給我們戰爭用的傀儡。\n\n傀儡家族有很多品質優秀的身體零件。找零件回來給我。", progress = "不管你找到的零件品質如何，我們照單全收。", completion = "我會把這些給血肉工藝師。如果我們的士兵不夠的話，做幾個就好了。", rewards = "您會收到：\n\n腫脹怪異心臟穩定的瘟疫品種通靈塔聚焦水晶保存良好的超凡腦殼魔法防護的論文血絲長袍肉鱗鎖甲護胸屍皮外衣血絲護腿屍皮馬褲肉鱗腰帶鋼核裹腕\n                            顯示 10 更多                        肉鱗裹腕血煉魔典疫蝕穿刺瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐感激禮賜"}
MultiLanguageQuestData['tw'][62391] = {title = "動員瑪卓薩斯", objective = "提高你的名望。", description = "只要科爾蘇加德待在他的亡城，我們很難逮到他。\n\n去吧。我們需要一點時間，才能召集一支軍隊，突破他的防禦。", progress = nil, completion = "我們的部隊準備好了。\n\n讓我們結束這一切。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62392] = {title = "重新贏得我們的信任", objective = "完成暗夜妖精的任務。", description = "你照我們的要求回來了。很厲害嘛，或許你真的改過自新了。\n\n我希望你能再為我們完成一項任務。以證明你真的想要轉換誓盟。\n\n不是我們在懷疑你，但你得瞭解，你過去的行為讓我們有理由去懷疑你的動機是否單純。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62393] = {title = "重新贏得我們的信任", objective = "完成死靈領主的任務。", description = "看來你離開後實力沒有絲毫衰退啊。\n\n問題是…你心中還有任何忠誠可言嗎？\n\n我還有一項能展現你忠誠的任務要給你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62400] = {title = "前進未知！", objective = "調查未知的地區。", description = "啊，你來得正是時候。我有一個大發現。\n\n我成功建立一個連結，通往比以往更加遙遠的地方。\n\n你問我是怎麼辦到的？就是努力再努力！不過這道理你早就懂了，你幾乎跟我一樣努力。現在該是你登場的時候了！\n\n想不想來一場更加刺激的冒險？", progress = nil, completion = "我認得那些傢伙。真是壞消息。\n\n他們應該乖乖待在他們自己存在的界域才對！\n\n謝謝你進行大掃除。", rewards = "您會收到：\n\n暮色守衛權杖暮色守衛鐮刀暮色守衛戰棍暮色守衛枝條暮色守衛短弓暮色守衛盾牌符文看管者外套靈苔輕鞋果姆外殼脛甲符文看管者長靴符文看管者長手套靈苔手套\n                            顯示 19 更多                        果姆外殼之襲靈苔頭冠果姆外殼兜帽符文看管者護盔靈苔護腿果姆外殼褶裙符文看管者束褲符文看管者肩衛靈苔襯肩果姆外殼披肩符文看管者繫腰亞登之露珍珠星光捕捉器星穹橡實星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62401] = {title = "怪異的天譴石", objective = "在寒冰皇冠從不死族部隊身上收集黯沉的天譴石和漆黑的天譴石。", description = "巫妖王的手下原本帶著他們黑暗主人交給他們的天譴石。\n\n在不死族的屍體上，發現了新的石頭。我們不清楚這有什麼用途…但它們散發出更加惡毒的魔力。\n\n在你橫越寒冰皇冠諸殺天譴軍團時，留意這樣的石頭。如果你能帶些回來給我，我就可以把它們轉交給告解者進行研究。", progress = nil, completion = "我馬上將這些東西轉交給告解者。這些天譴石似乎大有文章。\n\n或許可以讓我們進一步瞭解那些來自裂隙、從天空攻擊我們的生物。\n\n如果你在冒險途中找到其他天譴石，請帶回來給我。", rewards = "您會收到：\n\n銀白十字軍表揚令"}
MultiLanguageQuestData['tw'][62402] = {title = "時光漫遊戰役", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][62403] = {title = "野豬殺手來囉", objective = "從瑪卓薩斯的野豬身上收集25根血腥長牙。", description = "瑪卓薩斯裡的野豬有著很奇怪的特質。牠們的獠牙會吸取液體。依據棲息地的不同，這些骨頭裡或許會保存了各種毒，或是其他稀有的鍊金物質。\n\n只有訓練有素的眼光，才能看出那些骨頭裡有什麼，所以帶一大堆回來就對了。之後，我會親自檢查哪些是有用的。", progress = "注意不要讓任何骨頭接觸到你的皮膚太久。那可能會讓你很不舒服。", completion = "這數量還不錯。這堆長牙裡一定會有可以用的。", rewards = "您會收到：\n\n腐蝕液體瓶跳動的憎惡體核心血煉披氅腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼魔法防護的論文肉鱗鎖甲護胸鋼核戰靴血絲足靴肉鱗護足屍皮馬褲\n                            顯示 18 更多                        屍皮肩甲鋼核護肩血絲披肩肉鱗披肩血絲之索肉鱗腰帶屍皮腰帶血煉骨鋸血煉粉碎錘血煉短劍血煉法刃瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐感激禮賜"}
MultiLanguageQuestData['tw'][62406] = {title = "統御者之杖", objective = "把統御者之杖放上統御者雕像。", description = "統御者之杖。代表我們領袖權威的最後一個部位。\n\n回復這座大廳的原貌讓我覺得光榮無比。你應該也能感受到一樣的成就感。\n\n雕像正在等你，<name>。為這個國度帶來榮耀吧。", progress = nil, completion = "我感受到力量。力量與安適。", rewards = "您能選擇下列奬勵中的一個：\n\n頂點靈魄珠奇蹟靈魄珠蒼穹靈魄球敬意靈魄球神秘靈魄球憎恨靈魄球\n\n您還會收到：\n\n名望"}
MultiLanguageQuestData['tw'][62407] = {title = "除草傾向", objective = "幫助氣囊收集腐瓣花瓣。", description = "我的氣味是全瑪卓薩斯最強烈的，但我聽到有人說我的氣味還不是整個暗影之境最強烈的。\n\n他們說亞登曠野有種植物的花會散發比我的氣味更加濃郁的味道。胡說八道！\n\n我們去看看那些植物，如果真的跟傳聞一樣臭，那或許我可以拿來和我的氣味混合一番。", progress = "摘花還有趣嗎？", completion = "為什麼他可以比之前還要臭啊？\n\n噁，至少辦事還算能幹。", rewards = "您會收到：\n\n\n\n等級 60–70縫補先驅者巨盔縫補咒術師風帽縫補策略家面甲\n\n任意等級縫補之魂面具優良肢體回收的補給物資"}
MultiLanguageQuestData['tw'][62414] = {title = "掩埋猜疑", objective = "殺掉10個祭儀家族外圍的妖誓部隊。", description = "如果科爾蘇加德知道奈勒希斯被殺了，那假扮成她就一點意義都沒有。\n\n你必須確保把所有看見你走進洞穴的人全都殺光。", progress = nil, completion = "你沒有留下任何會通風報信的人吧？很好。\n\n我們可以進行下一步的計劃了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62417] = {title = "前進未知！", objective = "調查未知的地區。", description = "啊，你來得正是時候。我有一個大發現。\n\n我成功建立一個連結，通往比以往更加遙遠的地方。\n\n你問我是怎麼辦到的？就是努力再努力！不過這道理你早就懂了，你幾乎跟我一樣努力。現在該是你登場的時候了！\n\n想不想來一場更加刺激的冒險？", progress = "我感覺到另一頭有風，這大概意味著這裡不是地底。", completion = "摘花維生沒什麼錯。這很好，是很正直的工作。\n\n而且能順便修理那些可惡的木魈也很值得。做得好。", rewards = "您會收到：\n\n薊枝戒環谷蔽項鍊靈苔法衣液鋼胸甲符文看管者外套符文看管者長手套液鋼護手靈苔手套果姆外殼之襲靈苔頭冠果姆外殼兜帽符文看管者護盔\n                            顯示 18 更多                        靈苔護腿果姆外殼褶裙符文看管者束褲靈苔腰環果姆外殼裹腰符文看管者繫腰液鋼護臂果姆外殼腕甲符文看管者護腕凋林裂片亞登之露珍珠星光捕捉器星穹橡實星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62420] = {title = "鉗嘴龜靈魂", objective = "將鉗嘴龜靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<鉗嘴龜靈魂意志堅決。你將來能任意化身為龍龜形態。>", progress = nil, completion = "啊。龍龜的精華！真不錯的型態。這現在是你的了，你想要的時候就可以使用它。", rewards = nil}
MultiLanguageQuestData['tw'][62421] = {title = "大嘴蟾靈魂", objective = "將大嘴蟾靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<大嘴蟾靈魂即有耐心又平靜。你將來能任意化身為大嘴蟾之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][62422] = {title = "亞登蛾靈魂", objective = "將亞登蛾靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<亞登蛾靈魂在亞登曠野隨處可見。外表看起來很脆弱，但它們蘊含著隱藏的力量。它們的魔法可以安撫受到最嚴重折磨的靈魂…或是將不小心闖進森林的入侵者陷入永恆的沉眠。你將來能任意化身為蛾之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][62423] = {title = "巨熊靈魂", objective = "將巨熊靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<巨熊靈魂堅強又勇敢。你將來能任意化身為熊之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][62424] = {title = "羽鶴靈魂", objective = "將羽鶴靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<羽鶴靈魂能優雅地漫舞。你將來能任意化身為鶴之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][62425] = {title = "幕翼靈魂", objective = "將幕翼靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<優雅、危險、強大。亞登曠野沒有任何生物比幕翼還要更受人景仰。牠們在保護同族或是領地時特別兇猛。\n\n你擊敗的敵人不只會危害亞登曠野，而是整個暗影之境。亞登曠野的勇士，為此你贏得了特別的殊榮。你能夠呼喚幕翼的本質，並化為牠們的形態。>", progress = nil, completion = nil, rewards = nil}
