MultiLanguageQuestData['tw'][62440] = {title = "蠍尾獅靈魂", objective = "將蠍尾獅靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<蠍尾獅靈魂驕傲又堅定。你將來能任意化身為蠍尾獅之形態。>", progress = nil, completion = "啊，蠍尾獅。你現在可以任意使用這個型態。", rewards = nil}
MultiLanguageQuestData['tw'][62441] = {title = "靈魂的公平交易", objective = "為聖所收集靈魄。", description = "我們在女王的栽培園工作同時，也不能忘記支援誓盟的其他人。\n\n這個地方需要我。你的腿很短，能支援的範圍卻很廣闊。\n\n拜託，去幫我們的誓盟取回我們需要的靈魄。這樣我才能專心準備下一個靈魂，讓你來恢復。", progress = nil, completion = "你一直以來都對栽培園盡心盡力。為此，我十分感謝你。\n\n現在，你可以從這些我親自收集的靈魂之中選擇要恢復哪個。", rewards = "您能選擇下列奬勵中的一個：\n\n強大的盡責魂靈強大的勇武魂靈強大的高傲魂靈強大的不羈魂靈\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][62442] = {title = "協助誓盟", objective = "在亞登曠野完成一項世界任務。", description = "我聽說這個花園外面的界域，有許許多多神奇事蹟。但老實說，我已經老到不想去那些危險的地方了。\n\n你還年輕，而且充滿活力！勇敢踏上未知領域吧，然後帶些英勇的冒險故事回來說給我聽！", progress = nil, completion = "要求你去做這些事對我幫助不小。", rewards = "您會收到：\n\n時光之葉"}
MultiLanguageQuestData['tw'][62443] = {title = "協助誓盟", objective = "在亞登曠野完成一項世界任務。", description = "我聽說這個花園外面的界域，有許許多多神奇事蹟。但老實說，我已經老到不想去那些危險的地方了。\n\n你還年輕，而且充滿活力！勇敢踏上未知領域吧，然後帶些英勇的冒險故事回來說給我聽！", progress = nil, completion = "要求你去做這些事對我幫助不小。", rewards = "您會收到：\n\n野性種子根粒"}
MultiLanguageQuestData['tw'][62444] = {title = "協助誓盟", objective = "在亞登曠野完成一項世界任務。", description = "我聽說這個花園外面的界域，有許許多多神奇事蹟。但老實說，我已經老到不想去那些危險的地方了。\n\n你還年輕，而且充滿活力！勇敢踏上未知領域吧，然後帶些英勇的冒險故事回來說給我聽！", progress = nil, completion = "要求你去做這些事對我幫助不小。", rewards = "您會收到：\n\n野生夜綻花"}
MultiLanguageQuestData['tw'][62445] = {title = "魂靈的驕傲", objective = "在野性種子中放置高傲魂靈。", description = "我想要更加瞭解這個世界裡那些驕傲的生命。\n\n如果你能把一個放到野性種子裡，就像你之前為我做的那樣，那我就能觀察整個恢復過程了。", progress = nil, completion = "這和我的家園完全不一樣，但還是讓我讚嘆不已。", rewards = "您能選擇下列奬勵中的一個：\n\n野生夜綻花時光之葉野性種子根粒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][62447] = {title = "稀有而不尋常的靈魂", objective = "擊敗特那希迷霧的崔朵瓦。", description = "我有件神秘的事要拜託你，<name>！\n\n有誰不喜歡神秘的事呢？\n\n我們發現了一個與眾不同的靈魂，它被放入野性種子後，卻毫無反應。\n\n每一個碰到它的人都做了一個夢，夢到你在跟一隻巨大的怪物纏鬥。只有在你擊敗怪物後，那個靈魂才會踏上重生之路。\n\n我們好像知道那隻怪物的身分。\n\n你願不願意負責調查這些夢境代表什麼？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n變幻的知識神靈"}
MultiLanguageQuestData['tw'][62448] = {title = "守住家族", objective = "提高你的名望。", description = "你在淵喉的經歷讓人印象深刻，但你需要更多驚人的事蹟才能讓瑪卓薩斯人效忠你。\n\n淵喉行者，提高自己在我們部隊裡的知名度吧。瑪卓薩斯人個個都是犧牲奉獻的士兵，但他們可不會隨便跟著某個人參戰。用你的行動證明自己值得效忠。", progress = nil, completion = "你的行為吸引到其他家族…以及質疑他們組織的人的注意力了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62449] = {title = "魂靈的職責", objective = "在野性種子中放置盡責魂靈。", description = "我想要更加瞭解這個世界裡那些盡責的生命。\n\n如果你能把一個放到野性種子裡，就像你之前為我做的那樣，那我就能觀察整個恢復過程了。", progress = nil, completion = "這和我的家園完全不一樣，但還是讓我讚嘆不已。", rewards = "您能選擇下列奬勵中的一個：\n\n野生夜綻花時光之葉野性種子根粒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][62450] = {title = "魂靈的內心", objective = "在野性種子中放置不羈魂靈。", description = "我想要更加瞭解這個世界裡那些不羈的生命。\n\n如果你能把一個放到野性種子裡，就像你之前為我做的那樣，那我就能觀察整個恢復過程了。", progress = nil, completion = "這和我的家園完全不一樣，但還是讓我讚嘆不已。", rewards = "您能選擇下列奬勵中的一個：\n\n野生夜綻花時光之葉野性種子根粒\n\n您還會收到：\n\n"}
