MultiLanguageQuestData['tw'][62559] = {title = "速合的帽子：公義之冠", objective = "我知道我自己的需求！所有人看到我戴著這個公義之冠時，一定全都會鞠躬的。", description = nil, progress = "我知道我自己的需求！所有人看到我戴著這個公義之冠時，一定全都會鞠躬的。", completion = "這很適合，就是它了！", rewards = nil}
MultiLanguageQuestData['tw'][62560] = {title = "力量逐漸增長", objective = "見證凜冬女王強化森林之心。", description = "<name>，真是個好消息！\n\n你已經收集了足夠的靈魄，這樣女王就可以強化森林之心了！", progress = nil, completion = "&lt;name&gt;，這就對了！繼續這樣下去，它很快就會回到先前那完整、光榮且繁若星塵的樣貌了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62561] = {title = "我心滿溢", objective = "見證凜冬女王強化森林之心。", description = "<name>！你相信嗎？我們擁有足夠的靈魄讓凜冬女王完整恢復森林之心了！\n\n你為我們做了好多！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62563] = {title = "又回來了！", objective = "擊敗『破肚者』果岡圖斯", description = "果岡圖斯就是不肯放棄！\n\n我們已經打敗她好幾次了，但拾荒者總是會回收她的身體，修好她然後再把她派回來這裡！\n\n她以為這次能打敗我們…去證明她錯了。", progress = nil, completion = "看起來這件事對你而言很輕鬆。希望她這次能學到教訓了。", rewards = "您會收到：\n\n戰鬥之焰回春藥水腐蝕液體瓶跳動的憎惡體核心血煉勳章血煉披氅腫脹怪異心臟束縛防護骨匣穩定的瘟疫品種通靈塔聚焦水晶保存良好的超凡腦殼鋼核盔帽\n                            顯示 30 更多                        血絲長袍鋼核胸鎧肉鱗鎖甲護胸屍皮外衣屍皮手套鋼核護手血絲手套肉鱗護手血絲兜帽肉鱗罩盔屍皮頭盔鋼核腿甲血絲護腿肉鱗護腿屍皮馬褲鋼核護肩鋼核束腰血絲之索肉鱗腰帶血絲裹腕鋼核裹腕血煉骨鋸血煉短劍瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐感激禮賜"}
MultiLanguageQuestData['tw'][62567] = {title = "徵集冒險者：克羅米的呼喚", objective = "在暴風城和克羅米交談。", description = "克羅米正在尋求經驗老道的冒險者，踏上穿越時間和空間的遠征。\n\n現在出發，就有機會親身參與「過去」的傳奇冒險！\n\n跟駐暴風城大使館附近的克羅米交談詢問更多資訊。", progress = nil, completion = "很高興你來了，&lt;name&gt;！總有種你的未來就在過去等你的感覺！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62568] = {title = "徵集冒險者：克羅米的呼喚", objective = "在奧格瑪和克羅米交談。", description = "克羅米正在尋求經驗老道的冒險者，踏上穿越時間和空間的遠征。\n\n現在出發，就有機會親身參與「過去」的傳奇冒險！\n\n跟駐奧格瑪大使館附近的克羅米交談詢問更多資訊。", progress = nil, completion = "很高興你來了，&lt;name&gt;！總有種你的未來就在過去等你的感覺！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62569] = {title = "閻獄之主的操弄", objective = "幫助珍娜‧普勞德摩爾打破閻獄之主對伯瓦爾的連結。", description = "伯瓦爾只要凝視淵喉，就會引來閻獄之主的注意。\n\n看來他最害怕的事成真了。\n\n<name>，你必須幫助我打破這個連結！頭盔的碎片就是關鍵！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n多功能靈魄容器"}
