MultiLanguageQuestData['tw'][62587] = {title = "尋找內心的平靜", objective = "前往高嶺尋找平靜", description = "我一直都在作夢。\n\n應該說是比較特別的夢。\n\n任何寧靜或平和的地方都可能出現在我的夢中。\n\n就連那些岌岌可危的地方也是一樣，因為只要有方法就能找到平靜。\n\n現在我夢見了你的世界，你的艾澤拉斯。\n\n我無法前往你的界域。幫助我透過你的眼睛和我最近的夢相連結。\n\n我第一個夢是一個很高的地方。非常高的地方。你知道是在哪裡嗎？", progress = nil, completion = "真是個舒適愉悅的夢啊，我很高興你能在現實中也體會到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62588] = {title = "尋找內心的平靜", objective = "前往祖達薩冥想。", description = "你回來了。\n\n這讓我很開心。\n\n更多寧靜之地出現在我的夢裡了。\n\n我看見了沙灘，日落。\n\n我無法前往你的界域。幫助我透過你的眼睛和我最近的夢相連結。", progress = nil, completion = "真是個舒適愉悅的夢啊，我很高興你能在現實中也體會到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62589] = {title = "尋找內心的平靜", objective = "在冬泉谷冥想", description = "我很高興你想要繼續你的冥想。\n\n這能幫助你心緒更加專一。\n\n我又有另一個夢境了。一個寒冷之地的溫暖夢境。\n\n那裡包覆在一片雪白之中。你知道這地方嗎？\n\n前往那裡，並體驗我夢境中看見的奇觀。", progress = nil, completion = "真是個舒適愉悅的夢啊，我很高興你能在現實中也體會到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62590] = {title = "尋找內心的平靜", objective = "在凜風峽灣冥想", description = "謝謝你回來。\n\n我又有另一個夢境了。又一個屬於你的界域的幻象。\n\n在這場夢境中，天空在我頭上漫舞。\n\n在懸崖邊，在北方的大地。\n\n真是壯麗的景色啊。\n\n你一定要親身體驗。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62591] = {title = "尋找內心的平靜", objective = "在藏寶海灣冥想", description = "我們已經一起經歷了很多。\n\n我很感謝在這趟探索之旅上有你相伴。\n\n你親身走在我只能投射感受的地方。\n\n你觸摸了我只能看見的東西。\n\n我又有另一個夢境了。\n\n又一個海岸。一座雕像。\n\n一個小傢伙的大雕像。\n\n去吧，去找出我夢境出現的景色。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62592] = {title = "內心平靜的大師", objective = "在女王的栽培園裡找出新的冥想位置。", description = "你好不容易走到了這一步。\n\n你幾乎準備好能在任何地方任意沉浸在內心的平靜裡了。\n\n只要再經歷最後一次我引領的旅途。\n\n一場很短的旅途。平靜一直都存在於這座花園裡。\n\n再經歷一個平靜之地。\n\n然後，你就能解開你的靈體枷鎖。\n\n我一定會很驕傲。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神奇冥想寶珠"}
MultiLanguageQuestData['tw'][62593] = {title = "狩獵：死亡元素", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n冥魄"}
MultiLanguageQuestData['tw'][62597] = {title = "骸骨工匠黑彌爾", objective = "將亞歷山卓斯‧莫格萊尼的信交給瑪卓薩斯的骸骨工匠黑彌爾。\n\n已提供物品：\n", description = "<亞歷山卓斯‧莫格萊尼留了一張非常直接的介紹信，是關於瑪卓薩斯的骸骨工匠黑彌爾。\n\n她能為餘燼宴會幫上什麼忙呢？>", progress = nil, completion = "淵喉行者，你想做什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62598] = {title = "熔爐士索芬妮", objective = "將軍政官阿德雷特斯的信交給昇靈堡的熔爐士索芬妮。\n\n已提供物品：\n", description = "<軍政官阿德雷特斯留了一封非常正式的介紹信給昇靈堡的熔爐士索芬妮。\n\n她能為餘燼宴會幫上什麼忙呢？>", progress = nil, completion = "淵喉行者，我猜你有求於我。我能幫你什麼忙嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62599] = {title = "果姆工匠卡文納", objective = "將狩獵隊長克芮恩的信交給亞登曠野的果姆工匠卡文納。\n\n已提供物品：\n", description = "<狩獵隊長克芮恩留了封言簡意賅的介紹信給亞登曠野的果姆工匠卡文納。\n\n他能為餘燼宴會幫上什麼忙呢？>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62600] = {title = "找到內心的平靜", objective = "前往亞登曠野，和這片大地的平靜相處。", description = "這個地方是不是挺不錯的？\n\n我知道亞登曠野的神話。\n\n甚至在夢境中驚鴻一瞥過。\n\n但它波濤洶湧的靜默讓人無法想像。\n\n平靜是我類的生存方式。就算在混沌之中。\n\n你也總是能找到平靜。你想看嗎？\n\n我可以感受到附近正在匯聚平靜。這對示範來說再好不過了。", progress = nil, completion = "你明白了嗎？找到平靜，是一種強大的力量。能夠讓人找到自己的中心，就算在最動盪的時刻也能提供慰藉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62601] = {title = "鍛鍛", objective = "把倫德的信送給暗隱村的鍛鍛。\n\n已提供物品：\n", description = "<倫德留了一封皺巴巴的信封，要寄給暗隱村的鍛鍛。信封外面有個很明確的命令告訴鍛鍛是倫德派你來的。\n\n鍛鍛能為餘燼宴會幫上什麼忙呢？>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62603] = {title = "稀有而不尋常的靈魂", objective = "在晉升之巔擊敗德沃絲。", description = "真高興能再見到你，朋友！\n\n我們又發現一個被惡夢纏身的沉睡靈魂。情況很棘手！\n\n在這個夢中，原先忠心耿耿的高貴人物因為自我懷疑而自取滅亡，最終誤入歧途。\n\n如果你成功擊敗這個墮落的楷模，一定能讓這個可憐的靈魂復活。\n\n<name>，你願意再幫我們一次嗎？", progress = nil, completion = "又實現了另一個夢境幻象。真是太厲害了！", rewards = "您會收到：\n\n寧靜的星穹神靈"}
MultiLanguageQuestData['tw'][62605] = {title = "仲介者事宜", objective = "找到遺忘的補給品的所有者。", description = "<有個結滿蛛網的箱子裡頭放著各式各樣的學術補給品，就這樣隨意擺在地上。這看起來是出自於仲介者之手。或許這些東西的所有者就在附近。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62606] = {title = "黑棘混土", objective = "在黑棘林地收集6個黑棘黏土。", description = "啊，這可不是我最想見到的蘑菇法師嗎！介意幫我取得一些黏土嗎？\n\n你知道土壤有分很多種類吧？並非全都是泥土！而黏土呢…黏土是很特別的。你試過在黏土裡頭生長嗎？噢，看來沒有。\n\n要搞定它可不容易，但如果成功了，那味道可是無可比擬！我的根鬚想接受這個挑戰\n\n黑棘林地有一種又苦又複雜的黏土，我非常想要。我很確定如果你好好和他們要一些的話，他們不會介意的。", progress = "如果他們找你麻煩，告訴他們是瑪拉茲莫斯派你來的。我打賭一定有人老到還記得我。", completion = "噢，這真是好東西。它有點苦，沒錯，但底層那複雜且細微的味道真是太棒了。嗯！有機會的話你一定要試試。", rewards = "您會收到：\n\n谷蔽項鍊暮色守衛戰刃暮色守衛彎刀暮色守衛權杖暮色守衛鐮刀暮色守衛重槌暮色守衛戰棍暮色守衛枝條液鋼戰盔靈苔法衣液鋼胸甲果姆外殼護胸\n                            顯示 22 更多                        符文看管者外套靈苔護腿果姆外殼褶裙符文看管者束褲冰寒推進女王近衛之護凋林裂片亞登之露珍珠星光捕捉器星穹橡實死亡之擁狙擊手的焦點刺痛打擊致命合擊堅定追擊肉食本能無限生長星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62607] = {title = "閃閃發光的好東西", objective = "在爍枝收集6個閃爍泥沙。", description = "唉呀，你好啊！今天有空幫我個忙嗎？\n\n你去過爍枝嗎？你知道那裡的名字是怎麼來的嗎？當命名發生時，我親自在現場呢。\n\n很多人覺得是因為樹或者水閃閃發光，他們說得沒錯。但之所以會閃閃發光的秘密其實在淤泥裡。那裡的土壤浸泡在水裡，吸收其中過剩的靈魄，直到最後土地本身就這樣發出光芒了。\n\n我現在真想要來一點閃爍泥沙。你能幫這顆老蘑菇重溫年輕的時光嗎？", progress = "噢，我每次攝取閃爍泥沙時，全身都會陣陣發麻。我的「全身」可是很大啊！", completion = "看看他耀眼的光芒！我光是用看的都覺得渾身期待了。我感覺就好像變年輕了一樣！", rewards = "您會收到：\n\n暮色守衛小刀暮色守衛彎刀暮色守衛權杖暮色守衛鐮刀暮色守衛重槌暮色守衛戰棍暮色守衛枝條暮色守衛短弓暴力催化靈苔法衣果姆外殼護胸符文看管者外套\n                            顯示 30 更多                        符文看管者長靴液鋼腿鎧靈苔護腿果姆外殼褶裙符文看管者束褲符文看管者肩衛靈苔襯肩符文看管者護腕冰寒推進亞登之露珍珠星光捕捉器星穹橡實狂亂釋放蓄積活力獵豹活力強化精準惡魔特種兵刺痛打擊生於荒野逞凶鬥狠野蠻戰鬥者無限生長匿跡遁行三重威脅血脈穿刺星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62608] = {title = "皇家禮遇", objective = "在黑夜花園收集6個皇家泥煤。", description = "真高興能再見到你。我有個特別的請求。\n\n凜冬女王以前常常親自照顧林地。她碰觸的一切都會迸裂出生命和力量。就連她踏過的土地也是如此。\n\n隨著時間過去，女王的花園變成現在的黑夜花園了。因為女王太久沒有親自照顧了。\n\n但那裡的土地仍然藏有她的力量。那是我享用過最美味的泥土。我知道這有點奢侈，但你我都知道這是我應得的！", progress = "有時候就是需要好好犒賞自己一下。", completion = "你也感覺看看這些土壤是多麼豐裕！我要好好品嚐一番。謝謝你。", rewards = "您會收到：\n\n薊枝戒環谷蔽項鍊靈苔法衣液鋼胸甲果姆外殼護胸符文看管者外套液鋼脛甲果姆外殼脛甲符文看管者長靴符文看管者長手套果姆外殼之襲液鋼扣環\n                            顯示 29 更多                        靈苔腰環果姆外殼裹腰符文看管者繫腰果姆外殼腕甲喚醒者蕨葉凋林裂片亞登之露珍珠星光捕捉器大地突波虛空精準星穹橡實醉仙望月步黑暗迷離蓄積活力恐懼之影獵豹活力與獸為伍灰燼殘骸獸群之力重獲新生生於荒野天空之怒傷筋動骨星界軟木發光的銀莓暮落塊莖冬日嫩枝伏擊經驗加成"}
MultiLanguageQuestData['tw'][62609] = {title = "死靈領主武裝", objective = "在瑪卓薩斯完成世界任務。", description = "<骸骨工匠黑彌爾開始讀起了你遞給她的信。>\n\n嗯。莫格萊尼通常對這種事比較在行…\n\n<骸骨工匠黑彌爾讀完信後就用她那骨感的手指把信撕成碎片。>\n\n命令就是命令。我會安排運送一批原始素材並鑄造一些送往你宴會的裝備。\n\n在你等待的同時，莫格萊尼要求你接替我的位置、幫忙清除一些我們的敵人。\n\n信裡面寫的啊，可惜信都被撕碎了，你也沒辦法再看一次了。", progress = nil, completion = "很好。我已經安排好我們需要的一切了。\n\n我會出席。", rewards = "您會收到：\n\n死靈領主武器"}
MultiLanguageQuestData['tw'][62610] = {title = "菌絲巡邏：菇柄之域", objective = "透過妖精之環移動，並且在菇柄之域殺死30個蒙面的入侵者。", description = "<瑪拉茲莫斯嘆了口氣。> \n\n他們又來了，就在菇柄之域那裡。\n\n看來我們上次給他們的教訓還不太夠啊？不如我們聯手給這些小夥子們一些永生難忘的教訓，如何？\n\n你準備好就和我說一聲，然後一起解決他們，就和上次一樣！", progress = nil, completion = "哼，他們罪有應得。他們以為可以這樣隨意踐踏我的林地？只有我才能這樣隨意踐踏！我才能踐踏！", rewards = "您會收到：\n\n谷蔽項鍊暮色守衛枝條液鋼戰盔靈苔法衣液鋼胸甲果姆外殼護胸符文看管者外套符文看管者長手套液鋼護手靈苔手套果姆外殼之襲靈苔頭冠\n                            顯示 29 更多                        果姆外殼兜帽符文看管者護盔靈苔護腿果姆外殼褶裙符文看管者束褲符文看管者肩衛靈苔襯肩果姆外殼披肩符文看管者繫腰冰寒推進亞登之露珍珠星光捕捉器星穹橡實烈焰凝聚神性呼喚殘暴投射致命連鎖燃灼焚焰刺痛打擊百鍊本能多層毛皮無限生長明晰乍現血脈穿刺星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62611] = {title = "菌絲巡邏：心木林地", objective = "透過妖精之環移動，並且在心木林地殺死30個被附身的褻瀆者。", description = "那些戴面具的壞蛋占據了心木林地，我一定要阻止他們的計劃。\n\n心木林地以前真的很美麗。而現在，它卻變得…算了。我們要修正這個狀況，就你和我。現在馬上。\n\n來吧，和我一起戰鬥。我們會給那些怪物迎頭痛擊，讓他們的主子決定要再次褻瀆這片聖地時會三思而後行！", progress = nil, completion = "好了，結束了。他們應該全都被趕回去了，哪怕只是暫時的。我很感謝你的幫助。", rewards = "您會收到：\n\n薊枝戒環谷蔽項鍊暮色守衛小刀暮色守衛戰刃暮色守衛權杖暮色守衛重槌暮色守衛戰棍暮色守衛枝條暮色守衛短弓暮色守衛盾牌符文看管者長手套靈苔手套\n                            顯示 28 更多                        果姆外殼之襲符文看管者肩衛液鋼扣環靈苔腰環果姆外殼裹腰符文看管者繫腰永夜披氅喚醒者蕨葉女王近衛之護凋林裂片亞登之露珍珠星光捕捉器精通烈焰星穹橡實命運逆轉殘暴投射獸群之力重獲新生領先獸群元素匯流百鍊本能明晰乍現星界軟木發光的銀莓暮落塊莖冬日嫩枝伏擊經驗加成"}
MultiLanguageQuestData['tw'][62612] = {title = "汎希爾武裝", objective = "在瑞文崔斯完成世界任務。", description = "<鍛鍛讀了你交給他的信。>\n\n啊，是倫德派你來的啊。早該說的嘛。\n\n沒有問題。我會幫你準備要在那個宴會成為焦點的一切。\n\n但我需要你幫忙說服我的老闆請假的事。\n\n淤泥真的很黏，對吧？\n\n你就幫我處理一下附近的麻煩，然後和大家說是為我做的…這樣應該就行了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n汎希爾武器"}
MultiLanguageQuestData['tw'][62613] = {title = "琪瑞安武裝", objective = "在昇靈堡完成世界任務。", description = "<熔爐士索芬妮讀了你交給她的信。>\n\n我瞭解了。\n\n無論要我去哪裡履行職責，我都願意。\n\n你也有相同感受嗎？當昇靈堡有危難時，你也會履行使命嗎？", progress = nil, completion = "我的錘子是你的了。", rewards = "您會收到：\n\n琪瑞安武器"}
MultiLanguageQuestData['tw'][62614] = {title = "菌絲巡邏：日暮林地", objective = "透過妖精之環移動，並且在日暮林地殺死30個被附身的入侵者。", description = "我希望你準備好大戰一場。\n\n佐司特正在日暮林地壯大他們的勢力。大多數亞登曠野的居民已經不記得他們了，但我還記憶猶新。你必須把他們斬草除根才能永遠趕離此地，否則他們會以更強的態勢捲土重來。\n\n跟我來。我們要把他們殺得一個也不剩。等你準備好就跟我說一聲。", progress = nil, completion = "做得好。他們還是躲在黑暗之境裡，但這是我們現在能達到的最佳結果了。先把他們關住，有一天才能一把火燒了。", rewards = "您會收到：\n\n暮色守衛戰刃暮色守衛彎刀暮色守衛權杖暮色守衛鐮刀暮色守衛戰棍靈苔法衣液鋼胸甲果姆外殼護胸符文看管者外套符文看管者長手套靈苔手套果姆外殼之襲\n                            顯示 26 更多                        符文看管者肩衛液鋼肩鎧靈苔襯肩果姆外殼披肩永夜披氅凋林裂片冬之防護時間異動亞登之露珍珠星光捕捉器星穹橡實堅定屏障托爾托的和諧命運逆轉致命連鎖熊之活力重獲新生領先獸群天空之怒速戰速決星界軟木發光的銀莓暮落塊莖冬日嫩枝伏擊經驗加成"}
MultiLanguageQuestData['tw'][62615] = {title = "菌絲巡邏：輕絲崖", objective = "透過妖精之環移動，並且在輕絲崖殺掉30個黑棘襲擊者。", description = "輕絲崖傳來了壞消息。我們必須幫他們。\n\n威脅可憐絲行者的害蟲最近變得更加殘暴且更具侵略性。絲行者對亞登曠野至關重要。比任何人認為的都還要重要。我們不能再失去這些絲行者了。\n\n等你準備好就和我說一聲，我們一起一勞永逸地把那些討厭鬼嚇跑！", progress = nil, completion = "那些小小女士們現在應該都安全了。他們的使命在亞登曠野很重要，我絕不會再讓任何一個在我眼皮底下死去！", rewards = "您會收到：\n\n薊枝戒環暮色守衛戰刃暮色守衛彎刀暮色守衛權杖暮色守衛鐮刀暮色守衛重槌暮色守衛戰棍暮色守衛枝條暮色守衛短弓寒顫核心液鋼脛甲靈苔輕鞋\n                            顯示 33 更多                        果姆外殼脛甲符文看管者長靴符文看管者束褲符文看管者肩衛靈苔束腕液鋼護臂果姆外殼腕甲符文看管者護腕女王近衛之護凋林裂片亞登之露珍珠星光捕捉器石形本命虛空精準星穹橡實寒冰治療射手優勢恐懼之影腐化睨視兇猛嗜殺與獸為伍獸群之力強韌如樹皮元素匯流晦影烈能花開花落萬全準備靈機之指星界軟木發光的銀莓暮落塊莖冬日嫩枝經驗加成"}
MultiLanguageQuestData['tw'][62616] = {title = "暗夜妖精武裝", objective = "在亞登曠野完成世界任務。", description = "<果姆工匠卡文納讀了你交給他的信。>\n\n狩獵隊長派你過來我一點也不意外。畢竟，我可是全亞登曠野最出色的果姆工匠啊。\n\n她的命令很簡要而且我也很願意幫忙。\n\n我們得多解決一些巡邏隊才能彌補失去的時間和資源。\n\n聽起來還算公平吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗夜妖精武器"}
