MultiLanguageQuestData['tw'][62619] = {title = "曲折離奇的故事", objective = "把曲折離奇的故事帶給記憶林地的文獻管理員德瑞登。\n\n已提供物品：\n", description = "<快速翻閱了一下這本厚重的秘典，裡頭的用字遣詞花俏多變，但劇情不知所云。至少前幾章都是這樣。\n\n封面沾到了一些土，但損傷還不算太嚴重。看來這本書沒有遭逢過什麼大麻煩…就和裡面的劇情一樣。\n\n如果文獻管理員德瑞登能拿回這本書一定會很開心的。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62620] = {title = "峰迴路轉的逸聞", objective = "把峰迴路轉的逸聞帶給記憶林地的文獻管理員德瑞登。\n\n已提供物品：\n", description = "<這本書的內容或許有些道理，但作者卻極盡迂迴地長篇大論，始終找不到重點或結論。或許旅途的過程才是重點，終點並不重要…\n\n無論如何，如果文獻管理員德瑞登能拿回這本書一定會很開心的。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62621] = {title = "逃脫主義小說", objective = "把逃脫主義小說帶給記憶林地的文獻管理員德瑞登。\n\n已提供物品：\n", description = "<動作、冒險、刺激、寒顫…這本書應有盡有！寫下這本書的是人生閱歷豐富的凡人靈魂，令人愛不釋手。\n\n但裡面寫的是真的嗎？真的有人可以在短暫的一生中化解一連串的陰謀詭計、打敗古老邪魔、嚇阻大批軍隊以及殺死惡魔和神靈嗎？\n\n仔細一想，書裡寫的或許是真的。但裡頭提到的「鴨子」到底是什麼東西？那一段看起來像是亂寫的。\n\n反正…這還是一篇好故事。如果文獻管理員德瑞登能拿回這本書一定會很開心的。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62622] = {title = "旅行日誌", objective = "把旅行日誌帶給記憶林地的文獻管理員德瑞登。\n\n已提供物品：\n", description = "<看起來這本書是它自己在亞登曠野四處旅行所紀錄下的遊記！是書本自己寫的，還是自己出版的！\n\n把書本一路翻到最後，你看到你自己登場擔任壞人，以不公不義的方式攻擊這本書並試圖打開它。\n\n你讀到最後一段字寫著「看起來這本書是它自己在亞登曠野四處旅行所紀錄下的遊記！是書本自己寫的，還是…」\n\n你趕緊闔上這本書，同時感覺有點想吐。應該把它還給文獻管理員德瑞登才對。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62623] = {title = "調皮搗蛋的故事", objective = "把調皮搗蛋的故事帶給記憶林地的文獻管理員德瑞登。\n\n已提供物品：\n", description = "<你才把這本書拿在手上不到五分鐘，它就已經從你手上逃走一次、咬了你兩次而且還不知用什麼方法偷了你的金幣。\n\n這跟你想像中的「調皮搗蛋的故事」不太一樣。但想一想，這也不無道理。\n\n你把書本關上並綁得死死的，希望他盡量不要再惡作劇了。該把它還給文獻管理員德瑞登了。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62624] = {title = "女王的栽培園", objective = "與潔哈德交談，解鎖女王的栽培園。", description = "<name>，我聽說你正在幫助我們修復聖所。\n\n有一片非常特別的魔法林地，我們稱之為女王的栽培園。\n\n在這個神奇的栽培園裡，我們會培育古老神靈的靈魂重生。但裡頭的魔法因為靈魄乾旱而逐漸衰弱。\n\n它急切需要你的幫助。\n\n如果你能開始取得我們需要的資源並幫忙恢復作業，那對我們來說是莫大的幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62625] = {title = "稀有而不尋常的靈魂", objective = "到彼界境地擊敗繆薩拉。", description = "<name>，能看到你在恢復栽培園的這件事上大有進展真是太開心了！\n\n不過還有更多工作要做。\n\n我們又找到另一個沉睡的靈魂了。惡夢讓它遲遲無法覺醒。\n\n在夢中，這個靈魂困在兩個古老生物的鬥爭之間。兩個傢伙都有點惹人厭，不過其中一個比另一個糟上許多！\n\n如果你成功擊敗安眠之父，應該就能讓這個靈魂不再沉睡。你願意幫忙嗎？", progress = nil, completion = "又實現了另一個夢境幻象。真是太厲害了！", rewards = "您會收到：\n\n活潑的好奇神靈"}
MultiLanguageQuestData['tw'][62626] = {title = "穆比的神秘印記", objective = "將神秘印記帶回瑪卓薩斯的挑戰者大道。", description = "這個神秘印記看起來對這名穆比老兄很重要。去瑪卓薩斯把這印記還給他，或許你能得到一筆拾獲獎金。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62627] = {title = "一個都不能少", objective = "前往霜火尋找遺骸", description = "這地方還真特殊。\n\n充滿著重生的能量。融合了不同形態的魔法。和我預期的不一樣。\n\n我也允諾過要在我類之中重生。我對這道魔法如此熟悉，卻又如此未曾謀面。但它卻完全維繫了平衡。\n\n能幫助宇宙維持平衡的，不僅僅是那些重大的靈魂而已。\n\n就連最小的生物都充份發揮其作用。\n\n你想看嗎？尋找這種生物的遺骸，我們一起重新喚起它的靈魂。", progress = nil, completion = "你已經找到了嗎？你確實找到了。我看得出來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62628] = {title = "沃爾的憑單", objective = "將憑單帶到瑪卓薩斯的挑戰者大道上。", description = "<憑單上寫得很清楚，如果你把這個憑單拿去給瑪卓薩斯苦痛劇場外面的挑戰者大道上的奧納寧，那他就能從藉由沃爾大師的名義發經費給你。>", progress = "你想和我做交易？", completion = "&lt;奧納寧從你的手上接過憑單，從頭到尾讀了一遍。&gt;\n\n憑單認證完成，授權經費已批准。如果您想再進行另一筆交易，請再和我洽談。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62629] = {title = "一個都不能少", objective = "前往崑萊峰尋找遺骸", description = "該是時候去重新喚起另一頭動物靈魂了。\n\n這一頭在遙遠的地方迷失於烈火和突擊之中。\n\n去吧。去和這頭生物的殘骸溝通吧。釋放牠的靈魂，讓牠回來這裡吧。", progress = nil, completion = "你已經將這個靈魂送還給我們了。牠現在能隨心所欲地在栽培園裡漫遊了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62630] = {title = "一個都不能少", objective = "前往提拉加德海灣尋找遺骸", description = "該是時候去重新喚起另一頭動物靈魂了。\n\n雖然這頭生物對你還有把牠吃了的有翼生物來說非常普通，但牠其實在牠的族類中很特別。\n\n你應該前往牠恐怖的安息之地並和這個靈魂溝通，好讓牠有機會加入我們的栽培園。", progress = nil, completion = "你已經將這個靈魂送還給我們了。牠現在能隨心所欲地在栽培園裡漫遊了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][62631] = {title = "世界任務正等著你", objective = "完成20個暗影之境的世界任務。", description = "當特使之兆在夜空中閃耀時，星辰會強化人們現有的牽絆，並鑄造出新的連繫。雖然友誼無法輕易締結，得仰賴行動來證明彼此的忠誠，但在這些日子裡，這樣的機會多的是。前往這些地方，對需要你幫助的人伸出援手，證明你的價值。", progress = nil, completion = "做得很好，&lt;name&gt;。", rewards = "韌皮長靴韌皮護腕韌皮披風韌皮手套您能選擇下列奬勵中的一個：\n\n商集團交易容器\n\n您還會收到：\n\n多功能靈魄容器"}
MultiLanguageQuestData['tw'][62632] = {title = "穿越時光的燃燒之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "熾炎之星照耀大地，燒灼土壤、烘烤地面。這是一枚無情之星，幾近惡意。在它的影響之下，可能會開啟通往遠方、甚至前往其他時間的新道路。賢者們無法瞭解這個徵兆，但好運往往眷顧英勇之士。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納撒亞寶物箱聖所寶箱聖塚寶藏箱"}
MultiLanguageQuestData['tw'][62633] = {title = "穿越時光的冰封之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "冰凍之星用它寒冷的光芒照耀著這片大地，就連靈魂都要躲入陰影底下。這顆星星和天空中其他星星截然不同，它不停地將暖意和生命吸收殆盡。當它的影響力還在時，新的道路或許會因此而開，那是條通往遠處甚至是彼時的道路。沒有一名賢者真的瞭解這個預兆的本質，但大膽之士才有機會獲得財富。", progress = nil, completion = "啊，&lt;name&gt;，你回來了。你的身上散發著其他世界的氣味。", rewards = "您會收到：\n\n納撒亞寶物箱聖所寶箱聖塚寶藏箱"}
MultiLanguageQuestData['tw'][62634] = {title = "穿越時光的破碎之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "破壞者之星以強光照耀大地，將靈魂逼回暗影之中。它不同於天上的任何星體，即便是最強大的英雄，也能讓他們的弱點暴露無遺。在它的影響之下，可能會開啟通往遠方、甚至前往其他時間的新道路。賢者們無法瞭解這個徵兆，但好運往往眷顧英勇之士。", progress = nil, completion = "啊，&lt;name&gt;，你回來了。你的身上散發著其他世界的氣味。", rewards = "您會收到：\n\n納撒亞寶物箱聖所寶箱聖塚寶藏箱"}
MultiLanguageQuestData['tw'][62635] = {title = "穿越時光的隱蔽之路", objective = "完成5次時光漫遊地城冒險。", description = "隱蔽之星在天際閃耀，星光一明一滅，奇異的迷霧因此籠罩著大地。這星辰和迷霧為大地帶來了深沉的暗影，隱藏著秘密與危險。因其影響，新的道路就此開啟，通往遙遠的地方，甚至久遠的時光。智者也參不透這個信號究竟是何底細，但幸運總是眷顧敢於冒險之人。", progress = nil, completion = "啊，&lt;name&gt;，你回來了。你的身上散發著其他世界的氣味。", rewards = "您會收到：\n\n納撒亞寶物箱聖所寶箱聖塚寶藏箱聖塚寶藏箱"}
MultiLanguageQuestData['tw'][62636] = {title = "穿越時光的破碎之路", objective = "完成5次時光漫遊地城冒險。", description = "兇蠻之星在大地上空閃耀，將對行經之路的一切事物造成莫大威脅。這顆星星象徵著許多事物：獸性、兇殘與尊貴。在它的影響下，有可能開啟全新道路、通往遠方，甚至通往另一個時間。沒有任何智者能夠確實瞭解這個自然跡象，但財富將會眷顧於果敢之人。", progress = nil, completion = "啊，&lt;name&gt;，你回來了。你的身上散發著其他世界的氣味。", rewards = "您會收到：\n\n納撒亞寶物箱聖所寶箱聖塚寶藏箱"}
MultiLanguageQuestData['tw'][62637] = {title = "戰鬥的呼喚", objective = "在戰場贏得4場對戰。", description = "這枚星體在天空閃閃發亮，深受督軍與將領的喜愛，並為各地的謀士帶來好運。有人說，戰鬥之星會強化指揮官的本領，達到近乎傳奇的境界。如果你想考驗自己身處戰場的本事，現在正是好時機。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n榮譽獎章多功能靈魄容器征服點數征服點數"}
MultiLanguageQuestData['tw'][62638] = {title = "征戰使節", objective = "完成4場傳奇難度的地城。", description = "當戰士之兆在夜空中閃耀，表示命運之神會眷顧無懼的勇者。敵人越是強大，獎賞就越豐厚，深入龍潭虎穴，證明你的價值吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n納撒亞寶物箱聖所寶箱聖塚寶藏箱聖塚寶藏箱命定寶箱"}
MultiLanguageQuestData['tw'][62639] = {title = "箇中翹楚", objective = "帶著由25級寵物組成的隊伍，透過尋找對戰功能打倒5位玩家。", description = "這種星象十分怪異，就連最小的生物也因此而顯現出異於平常的習性。沒有一位賢者能夠解釋這種現象，但是聰明的訓練師可以從中獲益良多，尤其是和同伴對戰、考驗技巧。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][62640] = {title = "競技場的呼喚", objective = "贏得10場競技場練習戰。", description = "星辰排列成厄運之兆，鼓動了人們心中的嗜血慾望，呼喚戰士與敵人展開絕命死鬥。競技場大師在這些日子總是可以名利雙收，就連他們也搞不清楚為什麼座位會場場爆滿。在緊張刺激的氣氛之中，豐厚的獎賞等待著那些夠勇敢或是夠魯莽的參賽者踏入競技場…您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n多功能靈魄容器征服點數征服點數榮譽點數"}
