MultiLanguageQuestData['tw'][62995] = {title = "靈鑄禦盾", objective = "將靈鑄禦盾帶給帕歐隆。", description = "<你撿起靈鑄禦盾的時候，雙手好像自己輕輕彈開了。\n\n這個應該能幫助你的靈魂之絆在晉升之路中多挨幾下敵人的攻擊。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n職責勳章"}
MultiLanguageQuestData['tw'][62996] = {title = "妖霜之瓶", objective = "將妖霜之瓶帶給帕歐隆。", description = "<憑子裝滿了冰冷的液體，摸上去冰冰涼涼的。\n\n這應該能干擾你靈魂之絆在晉升之路的對手。>", progress = nil, completion = "好奇怪的液體…哇！好冰！給我保管比較妥當。", rewards = "您會收到：\n\n職責勳章"}
MultiLanguageQuestData['tw'][62997] = {title = "藍圖：妖霜之瓶", objective = "將藍圖：妖霜之瓶帶給達提莉絲。\n\n已提供物品：\n", description = "<你發現了一份計畫書，能夠製作一個凍結晉升之路敵人的混合物。\n\n達提莉絲應該能夠幫你製作這個裝備。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n製作：妖霜之瓶"}
MultiLanguageQuestData['tw'][62998] = {title = "結界之環", objective = "將結界之環帶給帕歐隆。", description = "<你放下結界，被一個防護泡泡給擊退。\n\n這應該能在晉升之路上隔開你靈魂之絆的對手。>", progress = nil, completion = "環？非常非常好！給我保管比較妥當。", rewards = "您會收到：\n\n職責勳章"}
