MultiLanguageQuestData['tw'][63000] = {title = "藍圖：專注符咒", objective = "將藍圖：專注符咒帶給達提莉絲。\n\n已提供物品：\n", description = "<你發現了一份符咒的計畫書，能使你的靈魂之絆在晉升之路上活力充沛。\n\n達提莉絲應該能夠幫你製作這個符咒。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n製作：專注符咒"}
MultiLanguageQuestData['tw'][63002] = {title = "獨行的危險", objective = "在羈絆聖堂與靈魂嚮導戴莉亞談話。", description = "我相信你很清楚樂土堡可以提供的力量，但是光憑這樣還沒辦法打倒戴納瑟斯。\n\n淵喉行者，你必須找個靈魂之絆來協助你。\n\n去下面的房間找靈魂嚮導戴莉亞。她準備好要進行儀式了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63003] = {title = "收集靈魂", objective = "與瘟疫設計者瑪利雷斯談談靈魂之絆的過程。", description = "淵喉行者，你的戰鬥經驗，不輸給瑪卓薩斯的任何士兵。不過我們可不會單打獨鬥。\n\n學習盟友的長處乃一大智慧，這可是瑪卓薩斯的作風。\n\n和瘟疫設計者瑪利雷斯談談，他會教你如何進行靈魂之絆，然後藉此得到最大優勢。", progress = nil, completion = "真高興能再次見到你，我的學徒！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63006] = {title = "為了女王和林地！", objective = "加入暗夜妖精誓盟。", description = "自從你來到我們的界域，已經幫了我們好多好多！我好高興你決定加入我們的誓盟。\n\n之後還會有很多時間回顧。你要先去覲見凜冬女王本人！\n\n別讓她等太久了！", progress = nil, completion = "你在這裡的舉動也會對帷幕外的世界產生影響。幫助森林，或許也能拯救凡間的所有世界。", rewards = "您會學到：\n\n死亡代價\n\n下列法術會施放在您身上：\n\n提高所有抗性 08\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][63008] = {title = "魂絆熔爐", objective = "到魂絆熔爐找芙拉特比。", description = "跟另一名妖精建立羈絆，能進一步為凜冬之廷服務。\n\n這是古老的儀式，會賦予你強大的力量，助你面對往後的許多試煉。\n\n芙拉特比會指示你接下來的事。", progress = nil, completion = "喔，哇賽！我超愛引導靈魂之絆儀式！這是我最喜歡的工作！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63022] = {title = "守則六附加條款：不計代價拯救我", objective = "殺死符文大師瑪夫羅克。", description = "你！就是你！等等！\n\n你就是那個大名鼎鼎的淵喉行者，對嗎？我聽說很多關於你的事蹟。\n\n拜託你，幫幫我！淵誓者正在抽取我夥伴們身上的精華，他們想利用它來製作邪惡的符文。\n\n其中一個淵誓者把我囚禁在這裡，我想下一個就輪到我了。你一定要殺了他，然後放了我！\n\n我會好好補償你的。我在淵喉的這段時間收集了不少的冥魄。我願意全都給你，只要你能救我一命！", progress = nil, completion = "你來得正是時候！那些惡魔正想要殺了我。\n\n按照我們的約定，請收下這些冥魄當作你的報酬。\n\n老實說，我欠你的人情遠遠不止於此。我已經沒有其他東西可以給你了…除了我的智慧跟忠告。", rewards = "您會收到：\n\n冥魄"}
MultiLanguageQuestData['tw'][63029] = {title = "會見大領主", objective = "到奧睿博司向大領主伯瓦爾‧弗塔根回報。", description = "我們收到弗塔根大領主的消息，希望你立即回到奧睿博司。\n\n我只知道這跟淵喉的事情有關。\n\n你最好趕緊去找他。跟那黑暗之地有關的任何事情都必須最優先面對。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63030] = {title = "會見大領主", objective = "到奧睿博司向大領主伯瓦爾‧弗塔根回報。", description = "弗塔根大領主需要你馬上回到奧睿博司。！\n\n細節我不清楚，但傳令者有提到淵喉。\n\n你最好盡快去找他。如果跟淵喉有關，事情一定很嚴重！", progress = nil, completion = "我有可怕的消息，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63031] = {title = "取得資產：結晶化冥魄", objective = "收集10個結晶化冥魄，然後交給淵喉的維娜里。", description = "<這塊水晶裂片看起來是從區域中龐大的水晶造物斷裂下來的。它脈動著未使用的能量。\n\n維娜里應該會對你找到的任何裂片感興趣。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63032] = {title = "會見大領主", objective = "到奧睿博司向大領主伯瓦爾‧弗塔根回報。", description = "大領主伯弗塔根要你前往奧睿博司。\n\n我們只知道這是跟淵喉有關。\n\n去找他，讓他知道瑪卓薩斯無所畏懼。就算面對那個黑暗的地方也一樣。", progress = nil, completion = "我有可怕的消息，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63033] = {title = "會見大領主", objective = "到奧睿博司向大領主伯瓦爾‧弗塔根回報。", description = "奧睿博司信差帶來消息，大領主伯瓦爾‧弗塔根請你前往奧睿博司面會。\n\n看來這件事情跟淵喉…還有主宰的計畫有關。\n\n淵喉行者，我建議你立刻回應他的召喚，我們要把握每個機會。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63034] = {title = "樂土", objective = "到昇靈堡的樂土堡與卡莉賽恩交談。", description = "你必須前往昇靈堡。那裡是飛翼琪瑞安的永恆家園。\n\n別被金色的原野和閃亮的城塔蒙蔽了…琪瑞安也被靈魄乾旱大大削弱了，甚至有一場與墮落同伴的內戰迫在眉睫。\n\n他們正需要你的幫助。去你新的聖所，樂土堡，找一個叫卡莉賽恩的人。她會給你進一步指示。\n\n上方樞運之環的路引師羅阿逢維可以將你送去那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63035] = {title = "初露鋒芒", objective = "到瑪卓薩斯的統御者之座與武鬥士梅維斯交談。", description = "儘管他們曾經團結一致，共同保衛暗影之境，瑪卓薩斯的各大家族已經各自為政，彼此對立。\n\n他們的軍隊在境內相互征伐，甚至還進攻昇靈堡。如今，只剩下死靈領主還願意效忠統御者。\n\n到瑪卓薩斯的統御者之座找武鬥士梅維斯，與他交談。他的戰術技巧，一定能大大協助你。\n\n上方樞運之環的路引師羅阿逢維可以將你送去那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63036] = {title = "恢復平衡", objective = "到亞登曠野的森林之心與月莓女士交談。", description = "對於進入亞登曠野的自然之靈來說，這裡是重生不可或缺的一環。\n\n不幸的是，靈魄乾旱導致整片林地枯萎，使得靈魂永遠無法完成其循環。\n\n如今，敵人打破原有的寧靜，企圖摧毀僅存的森林，對早已疲於奔命的暗夜之廷造成威脅。\n\n暗夜之廷的月莓女士請求救援。上方樞運之環的路引師羅阿逢維可以將你送去那裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63037] = {title = "黑暗渴望", objective = "到瑞文崔斯的罪殞城與雷納瑟王子交談。", description = "邪惡的戴納瑟斯王背叛了我們所有人，將瑞文崔斯貯存的大量靈魄倒入淵喉，雷納瑟王子則決意反叛他的父親。\n\n你必須前往瑞文崔斯，助雷納瑟一臂之力。我們認為他最有希望恢復瑞文崔斯的秩序。\n\n上方樞運之環的路引師羅阿逢維可以將你送去那裡。", progress = nil, completion = "在如此…不湊巧的時候，居然有個凡人來到瑞文崔斯，實在讓我喜出望外。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63038] = {title = "使命必達", objective = "使用封閉寶珠將8個封起來的精華交給維娜里。\n\n建議玩家 [3]", description = "<這名仲介者似乎來自維商集團，他們說不定是維娜里原本的同事。>\n\n檢查了一下，對方手中抓著一張物品清單，還有一顆封閉寶珠。\n\n如果完成這名仲介者的任務、把物品送交維娜里，想必可以獲得一些報酬。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63039] = {title = "復仇紀念碑", objective = "收集8把黯刃符文刃，然後建立一座紀念碑，紀念黯刃騎士團在惡徒坩堝付出的犧牲。", description = "<丟入惡徒坩堝的黯刃騎士團屍骸，代表你初次襲擊這片蠻荒之地導致的後果。\n\n大家會將他們的犧牲牢記在心。>", progress = "<這種危險處境在淵喉隨處可見。\n\n在這裡建立紀念碑一定會引發閻獄之主的怒火。>", completion = "&lt;黯刃騎士團紀念碑下的陣亡騎士符文刃散發出陣陣能量。\n\n雖然跟他們的犧牲相比，這座紀念碑算不上什麼偉大貢獻，但是非做不可。&gt;", rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63040] = {title = "使命必達", objective = "使用封閉寶珠將5個屈從卷軸和3個約束工具交給維娜里。\n\n建議玩家 [3]", description = "<這名仲介者似乎來自維商集團，他們說不定是維娜里原本的同事。>\n\n檢查了一下，對方手中抓著一張物品清單，還有一顆封閉寶珠。\n\n如果完成這名仲介者的任務、把物品送交維娜里，想必可以獲得一些報酬。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63041] = {title = "物資短缺獎勵", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n協力朦朧布包"}
MultiLanguageQuestData['tw'][63043] = {title = "被撕裂的靈魂", objective = "在鍊魂塔破壞10個撕魂者陷阱。", description = "我們之前…不受陷阱影響，有很多很多靈魂…逃跑。\n\n於是他們…做出新陷阱…把逃跑的靈魂…撕成碎片…\n\n…我已經沒救了，破壞陷阱…這樣別人才有機會逃出去！完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][63044] = {title = "鼠湧", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][63045] = {title = "餵飽你的靈魂", objective = "收集靈魄強化復仇的靈魂，並且在他的協助下擊敗審判官莫爾拉克。\n\n建議玩家 [3]", description = "他們…吸取我的靈魄…用在他們的儀式上面…\n\n具有強大力量的靈魂會被帶來這裡…帶到這座祭壇…然後當成祭品，用來召喚難以言喻、服從閻獄之主的恐怖怪物。\n\n我也曾經具有強大的力量…把他們偷走的靈魄重新注入我體內…我就能恢復成那個強大的我。\n\n然後…我們聯手…消滅帶頭做出這些事情的傢伙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63046] = {title = "萬物始末", objective = "從凜冬女王學習野性種子的知識。", description = "我好開心你恢復了我們跟女王的栽培園之間的連結！\n\n有鑑於這項成就，凜冬女王親自請你到醒覺林地與她會面！\n\n你有機會能親眼見證並深入了解亞登曠野的神聖使命。然後你也能為此貢獻。\n\n快點！別讓大家一直乾等！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63047] = {title = "取得資產：符鑄枷鎖", objective = "收集9個符鑄枷鎖，然後交給淵喉的維娜里。", description = "<這些鍊條上面刻著統御符文，上面的魔法力量足以壓制淵誓者最強大囚犯。\n\n不用說也知道，維娜里一定能在一番研究之後找出這些符文的用途。>", progress = "再來做筆交易如何？", completion = "鍊條？這裡到處都是，不怎麼稀奇…等下，上面的符文…\n\n你的眼光果然很敏銳，上面的魔法值得深入研究一番。", rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63050] = {title = "取得：熾燃錠", objective = "收集12塊熾燃錠，然後交給淵喉的維娜里。", description = "<符文鐵匠在這塊金屬錠上灌注了魔力，使其環繞永不熄滅的火焰。\n\n這種金屬很有可能被用來強化佐瓦爾的大釜中的淵誓保衛者。\n\n如果帶一些礦物樣本給維娜里，對她研究閻獄之主的秘密或許有幫助。>", progress = "這是什麼？", completion = "真吸引人，我常常在想，那些大釜的守護者和其他淵誓者到底有何不同。\n\n希望拿到這些鍊條沒讓你花費太大力氣。", rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63051] = {title = "信任問題", objective = "回答維萊恩對淵喉的問題。", description = "喔，淵喉行者！請容我自我介紹。我是維萊恩。我為維商集團處理人員和風險的管控。\n\n我聽說你能夠在奧睿博司和淵喉之間自由進出，而我們集團對淵喉非常感興趣。\n\n你介意我問你幾個問題嗎？\n\n不過當然，你所花的時間跟提供的情報，我都會給予適當的酬勞。畢竟，這些可是最有價值的商品。", progress = nil, completion = "維商集團詢問你有關我的問題？\n\n我真是受寵若驚。你絕對不能跟他們說任何有關我的事。\n\n永遠都不能。\n\n來吧，有工作要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63052] = {title = "信仰之行", objective = "啟動運輸網路。", description = "我們的晉升者能輕易飛越昇靈堡上空，確保整個界域安全、繁榮。\n\n我們許久前建立了靈魄甬道系統，幫助志士、巨人和侍者更快速地在在境內移動。\n\n你去重新啟動系統吧。這樣你也能瞬間前往任何需要你的地方。", progress = nil, completion = "靈魄甬道已經非常久沒有啟動了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63053] = {title = "轉瞬之間", objective = "使用永恆甬道前往昇靈堡，再使用永恆甬道回到樂土堡。", description = "你再也不用騎乘拉里翁橫越昇靈堡了，淵喉行者。\n\n我們的甬道重新啟動了，你可以瞬間移動到任何需要你的地方。\n\n記住你還是要騎乘拉里翁才能回到奧睿博司或是前往其它界域。\n\n親自去試試看吧。", progress = nil, completion = "我們或許還能逐漸開啟更多甬道目的地。海弗斯能告訴你該怎麼做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63054] = {title = "聚鐵成鋼", objective = "啟用指揮桌。", description = "瑪卓薩斯的每個靈魂都有強大的潛力，我們必須盡力召集每一個人才能恢復暗影之境的秩序。\n\n有了這些生力軍的幫助，我們就能動員我們的部隊，讓他們在戰場上證明他們的價值。\n\n去找莫里克‧費德斯嘉。他會負責部署我們的士兵。", progress = nil, completion = "很高興見到你，&lt;name&gt;。只要團結一心，我們的士兵就會征服戰場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63055] = {title = "啟動傳送門", objective = "啟動運輸網路。", description = "統御者曾經在統御者之座和瑪卓薩斯的亡城之間維持傳送門的連結網路。由於缺乏靈魄，加上最近被破壞的許多亡城，讓這些連結失去了效用。\n\n你提供的靈魄讓我們連結上了其中一座傳送門。你可以再次前往我們其中一座最偉大的亡城…只要它還存在的話。", progress = nil, completion = "這些傳送門已經好幾個紀元都沒有啟動了。真令人興奮！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63056] = {title = "聖所升級：鏡子網路", objective = "使用黑暗強化卷軸召喚鏡子網路。", description = "好。我們為你準備了黑暗強化卷軸，可以產生鏡框。這部分都是標準流程。\n\n問題是，那之後你還需要專業的鏡子製作者，才能開始使用。\n\n雷納瑟王子可能認識技術夠好的尖牙齒。你去找他問問吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63057] = {title = "恢復力量", objective = "啟動靈魄傳導器。", description = "靈魄就是力量，<name>！\n\n在靈魄充足的時候，統御者會確保士兵們都能充分獲得他們所需的靈魄。\n\n但是在這場乾旱的影響之下，瑪卓薩斯內部為了爭奪任何能找到的靈魄，而產生嚴重的內鬥。 \n\n如今我們儲備的靈魄增加了，就可以把靈魄分配給整個瑪卓薩斯。在統御者不在的期間，我們死靈領主必須一肩扛起這個重責大任。\n\n去找尤黛爾‧海克斯。她會教你該怎麼做。", progress = nil, completion = "我等了好久，終於能再次發送靈魄給整個瑪卓薩斯了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63058] = {title = "憎惡縫合桌與我", objective = "啟動憎惡體工廠。", description = "傀儡在無數戰爭中，扮演了瑪卓薩斯部隊的骨幹。堅實的身軀能夠把任何靈魂轉換為在前線戰鬥的強大武器。\n\n聖所外面有張老舊的憎惡縫合桌，可以用來打造屬於我們自己的傀儡。有了你為誓盟取得的靈魄，我們應該能把它修好。\n\n等開始工作之後，去找米格西談話。她應該會在屠夫區。", progress = nil, completion = "你修好了縫合桌？太棒了！我們很快就能製造自己的傀儡了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63059] = {title = "極速傳送", objective = "穿過蛛眼家族的傳送門，努拉齊爾，然後使用統御者之座的傳送門回來。", description = "這種距離過去得靠牛獸走很久才到的了，但現在完全不用了！\n\n只要踩進這個傳送門，你一瞬間就能抵達蛛眼家族。 \n\n蛛眼家族的榮光或許不比從前，但在他們曾經強盛的亡城廢墟那裡，仍然能找到珍貴的盟友。\n\n前往那裡，測試一下傳送門的功能。", progress = nil, completion = "只要投入更多的人力，我們就能建立通往暗影之境其他亡城的傳送門。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63060] = {title = "守則六註釋：別忘了隨身物品", objective = "在獸穴尋找仲介者留下的任何東西。", description = "在淵喉中，你找到的任何東西都要帶回來。\n\n在獸穴裡有許多東西爬行。你帶回來的這些符文顯示，被抓去獸穴的仲介者可能在那裡留下了某些有用的東西。\n\n你去找找看。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63062] = {title = "自取折磨", objective = "在迪崔索斯的靈魂裂隙用相位虹吸器吸滿能量，然後交給淵喉的維娜里。", description = "<有個仲介者裝置被丟在這裡。看起來用途是吸取靈魂裂隙的能量。\n\n仲介者想取得這種能量，代表一定有某種用途。你說不定該去完成他們的這項工作。>", progress = nil, completion = "淵喉行者，你找到我的虹吸器，你真的是一天到晚帶給我驚喜。\n\n在淵喉，痛苦與折磨會具現成實體，不過成因不明…你收集到的這個能量可能有助於我們解開謎團。\n\n非常好。", rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63063] = {title = "聖所升級：鏡子網路", objective = "使用黑暗強化卷軸召喚鏡子網路。", description = "我們為你準備了黑暗強化卷軸，可以產生鏡框。這部分都是標準流程。\n\n等你召喚完了，勞倫特就能動手開工了。他善用玻璃的技術十分了得。", progress = nil, completion = "啊！終於湊齊必要工具了，現在能夠來辦正事了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63064] = {title = "聖所升級：指揮桌", objective = "使用黑暗強化卷軸召喚指揮桌。", description = "我們為你準備了黑暗強化卷軸，可以召喚出指揮桌。這可不是隨便什麼指揮桌，而是魔法指揮桌，可以讓你從遠處傳達命令。\n\n謀士莎卡堅持要當你這方面的翅膀。我是不太信任那些什麼翅膀啦，因為他們對我們這些泥掘者不怎麼好。但讓他們指揮戰鬥，連瑪卓薩斯都會怕。", progress = nil, completion = "有很多事情要完成，即使你足智多謀，也不可能同時出現在全境各地。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63065] = {title = "聖所升級：餘燼宴會", objective = "使用黑暗強化卷軸來開始餘燼宴會。", description = "我們幫你準備好黑暗強化卷軸了，這樣你應該有足夠的資源去辦場不得了的宴會討尖牙傢伙歡心。\n\n你應該去找瘋狂公爵聊聊，他被丟進烤箱之前，常常出入各大宴會派對。", progress = nil, completion = "來！我的朋友，快過來！\n\n準備…來場派對吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63066] = {title = "聖所升級：靈魄傳導器", objective = "使用黑暗強化卷軸召喚靈魄傳導器。", description = "好，我們收到你收集來的靈魄了。\n\n事情是這樣的，這些靈魄全都是從其它領域搾取出來的，主宰他胃口太大，把不屬於他的也全部奪走。\n\n所以我們準備了這個低階的黑暗強化卷軸給你，應該能幫你召喚出夠強的東西、讓你透過瑞文崔斯的結界將靈魄導回暗影之境。\n\n在我看來，這樣應該會帶來一些附加的好處。", progress = nil, completion = "該將靈魄導回暗影之境了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63067] = {title = "扎根重生", objective = "啟動靈魄傳導器並找到賽希黎。", description = "靈魄曾經很充足，但如今卻很稀有。你在我們困難之際帶來養分。讓我們成長。\n\n現在我們更能幫助別人，分享我們的豐饒。\n\n看著我們生長，再跟賽希黎說話。他會指引你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63068] = {title = "解決爭議", objective = "到煉火哨站找佩羅迪斯，或到內梅雅的居所找內梅雅。", description = "尋找能達成我們目的的琪瑞安時，我選定了兩個人：佩羅迪斯和內梅雅。\n\n他們兩人的競爭關係非常激烈，鮮少願意把注意力集中在其它事物上。我希望你能幫他們解決爭執，讓他們專注在工作上。\n\n他們大概不願意合作，所以你只能選一個來幫我們。", progress = nil, completion = "啊，你要來幫我解決爭執嗎？我讓你看看我的做事方式吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63069] = {title = "他們手上的資訊", objective = "在飢餓荒野收集18張殘破的日誌書頁，然後帶去淵喉交給維娜里。", description = "<看來這個仲介者遇害前正在收集資訊，維娜里一定會對他手上的資訊十分感興趣。\n\n可惜的是，當地野獸把他的日誌散落在各處。>", progress = "那本書…你手上那本是尋路者的日誌！", completion = "看來維商集團並未放棄追尋淵喉真相。\n\n你做得很好，幫我把尋路者的日誌帶回來，不管這份關於淵喉的資訊內容是多是少，對我們來說都比一具冰冷的屍體來得有用。", rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63072] = {title = "取得資產：冥魄礦", objective = "收集15塊冥魄礦，然後交給淵喉的維娜里。", description = "<這一區的岩石柱上充滿發光的異界金屬礦脈。\n\n淵誓者找了靈魂來此挖掘，但是看來沒持續多久。\n\n只要你能帶些回去，維娜里一定能找出這種礦石的用處。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63073] = {title = "真菌網路", objective = "啟動運輸網路。", description = "靈魄流向最深的根部，滋養蘑菇。我們已經很久沒有用妖精之環橫越亞登曠野了。\n\n讓我們重新連上魔菇網路吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63100] = {title = "悲慘的一群", objective = "在『靈魂之河』果戈亞擊殺10名無助軀殼。", description = "<這個可憐靈魂的軀殼被剝奪殆盡，幾乎什麼也不剩。\n\n不能讓這種悲慘的情況繼續下去，救救剩下可憐的靈魂吧。>完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][63132] = {title = "星宿令狀", objective = "把星宿令狀交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<卷軸上的文字不斷快速變換，看起來藏有許多古老的秘密，維娜里應該會非常感興趣。>", progress = nil, completion = "&lt;維娜里仔細檢視這份令狀。&gt;\n\n用這種方式記錄某人的秘密，十分有趣。想解讀可能得花上不少功夫。\n\n謝謝你帶來給我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63133] = {title = "變幻的密文", objective = "把變幻的密文交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<立方體的各面不斷變換，上頭鑲嵌了你無法解讀的符文。\n\n維娜里應該會感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63134] = {title = "淵誓者巡邏地圖", objective = "把淵誓者巡邏地圖交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<在皮紙上面潦草地勾勒出淵誓者的動向。\n\n維娜里應該會覺得這個資訊很有用。>", progress = nil, completion = "非常寶貴的資訊，真的很寶貴，這樣我必須離開避難所的時候，就能夠避開對方的探查。\n\n淵喉行者，我相信你已經把巡邏路線都記在腦中了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63135] = {title = "寒心部隊飛行路線", objective = "把寒心部隊飛行路線交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<這些圖表詳細說明了淵誓者琪瑞安的巡邏路線。\n\n拿到這份資訊，維娜里一定會非常高興。>", progress = nil, completion = "這樣就能稍稍降低淵誓者的空中優勢。當然這不代表我們就能掉以輕心。\n\n可以的話，不要引起他們的注意，我可不想看到有人跟著你回來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63136] = {title = "混亂符文", objective = "把混亂符文交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<古老的皮紙上頭刻畫著難以理解的線條。\n\n維娜里一定知道這個的價值。>", progress = nil, completion = "啊，沒錯，這很明顯是某人在發瘋的狀態寫下來的。\n\n不過，這不代表說沒有意義，有時候，深陷瘋狂方能看清真相。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63137] = {title = "難解的密文", objective = "把難解的密文交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<立方體各面的記號不斷在變換位置。\n\n維娜里一定很感興趣。>", progress = nil, completion = "&lt;維娜里在評估這份密文的時候，突然笑了起來。\n\n這個…這個是小孩子的玩具。仲介者把這個當成集團加密的教材。\n\n並不是說這個沒有什麼價值，剛好相反，在這種地方，即使是這種小玩意兒，即使僅僅是一閃而過的歡笑，也是難以估算的寶物。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63140] = {title = "陳舊的奧伯隆蝕刻文件", objective = "把陳舊的奧伯隆蝕刻文件交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<這份碎裂的蝕刻文件上面提示了淵喉的起源。\n\n維娜里一定會非常開心。>", progress = nil, completion = "&lt;維娜里快速看了文件一眼。\n\n這是貨真價實的古代文件，可惜保存狀態非常差，上面記錄的秘密一定價值連城。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63142] = {title = "魂鑄藍圖", objective = "把魂鑄藍圖交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<你細看文件內容，突然發現裡面寫的是如何將靈魂鑄成武器的恐怖方法。\n\n維娜里一定會對這個感興趣。>", progress = nil, completion = "在淵喉一定很難取得這些原始材料，閻獄之主手下那些鐵匠…手段想必相當高明，我一點也不訝異。\n\n這些藍圖上面記錄的知識不該現世，就讓祕密繼續是秘密吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63145] = {title = "影縛證詞", objective = "把影縛證詞交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<這些似乎是因為托迦司囚犯受到折磨而痛苦不堪之際說出的雜亂無章話語。\n\n維娜里會找出這其中的價值。>", progress = nil, completion = "淵喉行者，你找到好東西了，這可是來自托迦司內部的第一手資料，相當珍貴。從來沒有人能夠踏進那座塔，然後活著回來親口講述這些事情。\n\n除了我眼前這位以外。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63152] = {title = "汎希爾協定", objective = "把汎希爾協定交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<這個看起來是某種汎希爾人與淵誓者副官之間的密文。\n\n維娜里說不定有辦法解讀。", progress = nil, completion = "&lt;維娜里快速檢閱了一下，以各種方向翻轉這份卷軸。&gt;\n\n已經很長一段時間沒看到這麼複雜的加密方式了，不過如果不弄得這麼誇張就不是汎希爾人了。\n\n不管裡面寫了什麼，對方很明顯不想暴露出來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63153] = {title = "遺棄的折磨手段", objective = "把遺棄的折磨手段交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<這些磨損褪色的書頁上面敘述著某些被認為過度仁慈因而摒棄的懲罰手段。\n\n維娜里可能想看看。>", progress = nil, completion = "啊，可以稍微看出淵喉那群永恆折磨者心中的一絲想法。\n\n非常有趣…而且有點可怕。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63154] = {title = "暗影獵犬護甲板", objective = "把暗影獵犬護甲板交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<符文在這片護甲板表面緩緩變換著、不停在流動。\n\n維娜里應該會對這個感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
