MultiLanguageQuestData['tw'][63158] = {title = "哀號的錢幣", objective = "把哀號的錢幣交給維娜里避難所的維娜里。\n\n已提供物品：\n", description = "<這枚奇怪的硬幣似乎來自某個早已被人遺忘的年代。你握著它的時候，受苦靈魂的哀號立刻充塞腦中。\n\n維娜里可能會知道這枚硬幣的價值。>", progress = nil, completion = "這枚貨幣十分有意思。\n\n我真想知道是如何鑄造出來的…", rewards = "您會收到：\n\n"}
