MultiLanguageQuestData['tw'][63175] = {title = "晉升之路：亞薩諾斯", objective = "與任何靈魂之絆在晉升之路擊敗亞薩諾斯。", description = "你的靈魂之絆需要你在下一場試煉發揮戰術謀略。\n\n他們這週的目標是亞薩諾斯，希望從他的記憶中學習。\n\n等你有空閒，就去找阿特米德回到晉升之路。協助你的靈魂之絆擊敗亞薩諾斯，證明他們的成長。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿波隆的恩賜"}
MultiLanguageQuestData['tw'][63176] = {title = "晉升之路：阿札魯克斯", objective = "與任何靈魂之絆在晉升之路擊敗阿札魯克斯。", description = "你的靈魂之絆需要你在下一場試煉發揮戰術謀略。\n\n他們這週的目標是阿札魯克斯，希望從他的記憶中學習。\n\n等你有空閒，就去找阿特米德回到晉升之路。協助你的靈魂之絆擊敗阿札魯克斯，證明他們的成長。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿波隆的恩賜"}
MultiLanguageQuestData['tw'][63179] = {title = "在水中分隔四處", objective = "在『靈魂之河』果戈亞救出8名淹沒的琪瑞安。", description = "淵喉行者！真高興看到你出現在這裡。\n\n有一小隊邪惡的琪瑞安和淵喉聯手，從昇靈堡各個崗哨擄走我的兄弟姊妹。他們會把我們變成邪惡的海巫，我從沒見過那樣的生物。\n\n黑爾雅…他們應該是這樣叫她的…她一心想分裂我們，好讓我們加入她。\n\n拜託你，可以的話請救救我的同胞。", progress = nil, completion = "淵喉行者，我們欠你一命。\n\n不知道我們是否能夠逃離此處，可是你至少讓我們有機會反擊。", rewards = "您會收到：\n\n冥魄維娜里"}
MultiLanguageQuestData['tw'][63181] = {title = "晉升之路：阿特米德的挑戰", objective = "以佩拉苟斯在晉升之路的忠誠試煉或更高難度擊敗亞薩諾斯。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n佩拉苟斯最近好像在試煉中頻頻受挫。我相信如果由你來指導，在晉升之路進行額外訓練絕對能讓他進步神速！\n\n亞薩諾斯有許多值得學習的地方。有了你的協助，佩拉苟斯就能獲得勝利並帶回值得冥想省思的新體驗。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63182] = {title = "晉升之路：阿特米德的挑戰", objective = "以佩拉苟斯在晉升之路的忠誠試煉或更高難度擊敗努密努魯。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n佩拉苟斯從亞登曠野的經歷中學到許多寶貴的經驗。我想要見識一下他的成長。\n\n對抗努密努魯的試煉正好能提供這樣的機會。有了你的協助，佩拉苟斯就能獲得勝利並帶回值得冥想省思的新體驗。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63184] = {title = "晉升之路：阿特米德的挑戰", objective = "以米卡尼寇斯在晉升之路的忠誠試煉或更高難度擊敗朴片夢魘。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n米卡尼寇斯要求以新的試煉訓練布隆。他手下的軍教官幫忙捕獲了朴片夢魘的記憶，應該也適合做為他的巨人的訓練對象。\n\n有了你的指導，米卡尼寇斯和布隆就能克服新的試煉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63185] = {title = "晉升之路：阿特米德的挑戰", objective = "以克蕾雅在晉升之路的忠誠試煉或更高難度擊敗伊契瑟拉。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n克蕾雅準備好面對新的挑戰了。他迫不急待想回到晉升之路，繼續展現她的新能力。\n\n伊契瑟拉的記憶很適合讓她進行學習。有了你的幫助，克蕾雅就能克服這項挑戰，將經歷納入她的永恆訓練中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63186] = {title = "晉升之路：阿特米德的挑戰", objective = "以克蕾雅在晉升之路的忠誠試煉或更高難度擊敗阿札魯克斯。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n克蕾雅準備好面對新的挑戰了。他迫不急待想回到晉升之路，繼續展現她的新能力。\n\n若要順利護送靈魂穿越帷幕，她必須準備好跟阿札魯克斯這樣的吞噬者對抗。有了你的幫助，克蕾雅就能克服這項挑戰，將經歷納入她的永恆訓練中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63187] = {title = "晉升之路：阿特米德的挑戰", objective = "以米卡尼寇斯在晉升之路的忠誠試煉或更高難度擊敗狂人摩塔莫爾。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n米卡尼寇斯要求以新的試煉訓練布隆。狂人摩塔莫爾的記憶，應該正好適合做為挑戰。他跟米卡尼寇斯都有追求研究成果的熱情心靈。\n\n有了你的指導，米卡尼寇斯和布隆就能克服新的試煉。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63188] = {title = "晉升之路：阿特米德的挑戰", objective = "在晉升之路的智慧試煉中擊敗奧德林與米伊兒。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n薩尼歐斯要求進行智慧試煉，考驗你的計策謀略，以及你的靈魂之絆的能力。\n\n對抗奧德林與米伊兒的試煉正好適合。讓我們看看你跟靈魂之絆的實力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63189] = {title = "晉升之路：阿特米德的挑戰", objective = "在晉升之路的智慧試煉中擊敗突蘭提亞克。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n薩尼歐斯要求進行智慧試煉，考驗你的計策謀略，以及你的靈魂之絆的能力。\n\n對抗突蘭提亞克的試煉正好適合。讓我們看看你跟靈魂之絆的實力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63190] = {title = "晉升之路：阿特米德的挑戰", objective = "使用結界之環在晉升之路的忠誠試煉或更高難度擊敗膽小鬼科林斯。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n大多數的琪瑞安雖然都有偏好的武器，但每一個人都必須學習使用多種的武器與裝備。這樣才既確保心智機靈、也能維持身體與動作敏捷流暢。\n\n我們來看看你的靈魂之絆使用結界之環，能不能對抗膽小鬼科林斯的記憶。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63191] = {title = "晉升之路：阿特米德的挑戰", objective = "使用靈鑄禦盾在晉升之路的忠誠試煉或更高難度擊敗卡莉賽恩。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n大多數的琪瑞安雖然都有偏好的武器，但每一個人都必須學習使用多種的武器與裝備。這樣才既確保心智機靈、也能維持身體與動作敏捷流暢。\n\n我們來看看你的靈魂之絆使用靈鑄禦盾，能不能對抗卡莉賽恩的記憶。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63192] = {title = "晉升之路：謙遜試煉", objective = "在晉升之路中克服謙遜試煉。", description = "<name>，你準備好進行新的挑戰了嗎？\n\n許多琪瑞安在晉升的路上，都會在面對謙遜試煉時遇到挫折。我們必須時時記得無論進步了多少，永遠都有空間可以繼續學習加強。隨著我們持續的訓練，更能克服越來越多的阻礙。\n\n你跟靈魂之絆該回想一下這個教訓了。讓我們見證你們在面對謙遜試煉時獲得勝利吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n阿特米德的恩賜"}
MultiLanguageQuestData['tw'][63206] = {title = "無魂殘軀", objective = "到佐瓦爾的大釜，從冥魄符文鐵匠身上取得冥魄錘，然後摧毀10具裝甲軀殼。", description = "有些淵誓者一開始只是不具生命的鎧甲，出自佐瓦爾的大釜那些冥魄鐵匠之手。打造成型之後會放置等候，直到注入腐朽魔影才算完工。\n\n這是它們最脆弱的時候，你應該把握這個機會發動攻擊。\n\n淵誓符文鐵匠手中的錘子具有破壞的力量，並以此打造鎧甲形體，弄一把來，這樣你就可以在敵人對付我們之前，搶先一步動手把它們敲成飛灰。", progress = "敲碎敵人有沒有讓你覺得心滿意足？", completion = "很滿足，不是嗎？\n\n晉升到閻獄之主軍隊的淵誓者人數越少，我們存活下來的機會就越大。", rewards = "您會收到：\n\n沉睡的靈魂冥魄維娜里"}
MultiLanguageQuestData['tw'][63208] = {title = "下一階段", objective = "選擇前往暗影之境的哪個界域。", description = "你的努力有目共睹，但仍有其它界域需要你的幫助。\n\n想一想旅程的下一步吧，凡人。", progress = nil, completion = "這是睿智的選擇。趕緊去協助他們吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63209] = {title = "推展使命", objective = "選擇前往暗影之境的哪個界域。", description = "仍有其它界域需要你的協助，凡人。\n\n你必須旅行前往其中一個界域，幫助他們克服困境。\n\n你接下來要去哪裡呢？", progress = nil, completion = "願你的努力開花結果。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63210] = {title = "最後階段", objective = "選擇前往暗影之境的哪個界域。", description = "只剩一個界域需要你的協助了，凡人。\n\n準備好就跟我說，我會給你必要的資訊。\n\n這就是使命。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63211] = {title = "向阿德雷特斯回報", objective = "向軍政官阿德雷特斯回報。", description = "你選得很對。\n\n琪瑞安無數時光以來都負責帶領靈魂穿過帷幕進入暗影之境，確保所有界域都有穩定的靈魄供給。\n\n他們的神聖使命不容中斷。去找軍政官阿德雷特斯，以誓盟一員的身分鋪陳你的未來。", progress = nil, completion = "淵喉行者，你好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63212] = {title = "向梅維斯回報", objective = "向武鬥士梅維斯回報。", description = "你選得很對。\n\n死靈領主是暗影之境的永恆守護者。他們必須保持強盛，才能讓暗影之境的其它地放繼續行使使命。\n\n盡你所能幫助他們。去找武鬥士梅維斯，以誓盟一員的身分鋪陳你的未來。", progress = nil, completion = "我就知道你會回來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63214] = {title = "向月莓回報", objective = "向月莓女士回報。", description = "你選得很對。\n\n暗夜妖精在自然靈魂的永恆循環中扮演至關重要的角色。無數世界的平衡都仰賴著他們的付出來維持。\n\n去找月莓女士，以誓盟一員的身分鋪陳你的未來。", progress = nil, completion = "你回來了！我就知道你會選擇我們！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63215] = {title = "向德瑞文將軍回報", objective = "向德瑞文將軍回報。", description = "你選得很對。\n\n汎希爾人必須重拾協助靈魂贖罪的使命，從淵喉的無盡折磨中拯救這些靈魂。\n\n我們必須制止戴納瑟斯的奸計，去找德瑞文將軍，以誓盟一員的身分鋪陳你的未來。", progress = nil, completion = "明智的選擇。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63340] = {title = "罪殞城精兵", objective = "在奧睿博司的政要區與佐索格會面。", description = "<name>，多虧有你，罪殞城的影響力與日俱增！\n\n你的功勞有目共睹，即使遠在瑞文崔斯外的人也略知一二。\n\n奧睿博司的人們在討論你的傳奇故事，衝突大師佐索格請你前往政要區與他會面。\n\n他對戰爭兵法有濃厚興趣，我建議你別讓對方等太久。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63341] = {title = "罪殞城戰術大師", objective = "在奧睿博司的政要區與佐索格會面。", description = "罪殞城的聲望與日俱增，更甚戴納瑟斯一直希望達到的程度！<name>，這全都是你的功勞！\n\n佐索格再次請你前往奧睿博司，立刻動身吧。\n\n我們可不能錯過佐商集團的善意，贏得仲介者集團的信任絕非易事。\n\n他們說不定會為你準備更豐厚的賞賜。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63342] = {title = "死靈領主精兵", objective = "在奧睿博司的政要區與佐索格會面。", description = "<name>，由於你的貢獻，死靈領主的力量日益壯大。\n\n你的功勞有目共睹，即使遠在瑪卓薩斯外的人也略知一二。\n\n奧睿博司的人們在討論你的傳奇故事，衝突大師佐索格請你前往政要區與他會面。\n\n他對戰爭兵法有濃厚興趣，我建議你別讓對方等太久。", progress = nil, completion = "啊，&lt;name&gt;，你在戰場上有多勇猛的故事，我時有所聞。\n\n我想幫你這樣的厲害戰鬥人員準備些精良裝備，我授權佐達許為你進一步升級武器和護具。", rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63343] = {title = "死靈領主戰術大師", objective = "在奧睿博司的政要區與佐索格會面。", description = "你為死靈領主爭取了輝煌的榮耀。這等榮耀再次吸引了其他人的注目。\n\n佐索格再次請你前往奧睿博司，立刻動身吧。\n\n我們可不能錯過佐商集團的善意，贏得仲介者集團的信任絕非易事。\n\n他們說不定會為你準備更豐厚的賞賜。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63344] = {title = "琪瑞安精兵", objective = "在奧睿博司的政要區與佐索格會面。", description = "<name>，多虧你的努力，昇靈堡開始復原了。前方的道路再次變得明朗。\n\n你的功勞有目共睹，即使遠在昇靈堡外的人也略知一二。\n\n奧睿博司的人們在討論你的傳奇故事，衝突大師佐索格請你前往政要區與他會面。\n\n他對戰爭兵法有濃厚興趣，我建議你別讓對方等太久。", progress = nil, completion = "啊，&lt;name&gt;，你在戰場上有多勇猛的故事，我時有所聞。\n\n我想幫你這樣的厲害戰鬥人員準備些精良裝備，我授權佐達許為你進一步升級武器和護具。", rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63345] = {title = "琪瑞安戰術大師", objective = "在奧睿博司的政要區與佐索格會面。", description = "<name>，看看你周圍吧。樂土堡證明了你的貢獻為我們帶來了多少進步。\n\n佐索格再次請你前往奧睿博司，立刻動身吧。\n\n我們可不能錯過佐商集團的善意，贏得仲介者集團的信任絕非易事。\n\n他們說不定會為你準備更豐厚的賞賜。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63346] = {title = "暗夜妖精精兵", objective = "在奧睿博司的政要區與佐索格會面。", description = "多虧有你，現在亞登曠野比過去一段時間要來得安全。\n\n你的功勞有目共睹，即使遠在瑞文崔斯外的人也略知一二。\n\n奧睿博司的人們在討論你的傳奇故事，衝突大師佐索格請你前往政要區與他會面。\n\n他對戰爭兵法有濃厚興趣，我建議你別讓對方等太久。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63347] = {title = "暗夜妖精戰術大師", objective = "在奧睿博司的政要區與佐索格會面。", description = "你的勇氣讓亞登曠野得以重新生長。這也再次引起了仲介者的注意。\n\n佐索格再次請你前往奧睿博司，立刻動身吧。\n\n我們可不能錯過佐商集團的善意，贏得仲介者集團的信任絕非易事。\n\n他們說不定會為你準備更豐厚的賞賜。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n無積分PvP裝備物品等級"}
MultiLanguageQuestData['tw'][63418] = {title = "被利用的探險者", objective = "拯救恰克的朋友", description = "恰克解釋道，叢林裡面發生了奇怪的事情，他的夥伴被野生蘑菇人給抓走了。\n\n他請你拯救他的朋友，並協助釐清叢林裡面發生了什麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63419] = {title = "大量孢子", objective = "收集12個奇怪的孢子", description = "恰克又重複了一次，他說叢林就好像是活了過來一樣，一切都亂了套。\n\n他請你從受到感染的蘑菇人和野獸身上把孢子取回來。\n\n恰克擔心這次的情況不是自然現象。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63435] = {title = "神殿大對決", objective = "在寵物對戰中擊敗安西亞。", description = "我的父母忙著保護神殿…好像是什麼八…椰…神殿？反正我沒在聽。大概是這樣，他們才留我一個人在這裡吧。\n\n他們說我可以跟大白貓一起訓練。我要變成忍者！\n\n<安西亞朝你的方向踢了好幾腳。>\n\n呀！嘿呀！你給我小心一點！\n\n…\n\n我好無聊，你想要來一場寵物對戰嗎？我把我最喜歡的寵物都帶來了。", progress = nil, completion = "好吧，你贏了。這個是我跟其中一個咕嚕摩交換到的東西。你有見過咕嚕摩嗎？他們不喜歡我撓他們的耳根後面，但我還是撓個不停！他們超可愛的啦！", rewards = "您會收到：\n\n咕嚕摩袋子"}
MultiLanguageQuestData['tw'][63447] = {title = "無懼邪惡", objective = "治療4名受傷的暴風城士兵。", description = "你是否擁抱了聖光，<兄弟/姊妹>？是聖光解救我們！是聖光讓我有能力治療這些要求太多的士兵！透過聖光，你才有辦法深入北邊的原野，救援我們倒下的兄弟們姊妹！\n\n帶著這本祈禱書，到原野上對傷者施展聖光的治療之觸。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "北郡修士輕鞋邊境護腕狼獵手之外衣輕量微光護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][63455] = {title = "死者的尊嚴", objective = "使用聚合水晶打造出軀體給10個不屈的靈魂使用。", description = "閻獄之主扭曲這裡的靈魂並迫使其臣服於他的意志，但還是有些靈魂致力挺身反抗。\n\n我要讓你能夠協助他們反抗閻獄之主。透過死靈聚合，我們可以把這個地方的各種符文、護甲和骸骨結合起來，替這些靈魂打造出軀體。有了這些軀體之後，他們就可以為我們而戰、為自己的自由而戰！\n\n把狂熱的靈魂綁縛於軀體上，替我們打造出一支大軍吧！", progress = nil, completion = "做得好，&lt;name&gt;。你的努力使我方部隊變得更加強大！", rewards = "您會收到：\n\n戰鬥之焰回春藥水跳動的憎惡體核心腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼鋼核胸鎧屍皮長靴屍皮手套鋼核護手血絲手套肉鱗護手\n                            顯示 21 更多                        屍皮肩甲鋼核護肩血絲披肩肉鱗披肩鋼核束腰血絲之索肉鱗腰帶屍皮腰帶血絲裹腕鋼核裹腕肉鱗裹腕屍皮裹腕兇猛嗜殺皇家敕令瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐不死軍團"}
MultiLanguageQuestData['tw'][63479] = {title = "團長的召喚", objective = "在銀月城和莉雅德倫女士見面。", description = "你好，<name>。\n\n我們就不拐彎抹角了，銀月城迫切需要你的協助。\n\n奎爾薩拉斯的天譴軍團再度復甦，如果沒有人能抵擋天譴軍團，我們很快就會陷落。我們必須堅守防線！\n\n到血之大廳找我，我們會給你一個完整的簡報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63480] = {title = "簡報", objective = "聆聽簡報內容。", description = "我們時間不多。\n\n天譴軍團攻擊了安寧地，沒人擋得了他們。\n\n必須果斷行動。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63482] = {title = "受死吧，天譴軍團", objective = "殺死安寧地的天譴軍團。", description = "上一次看到這麼多天譴軍團的時候是…\n\n<莉雅德倫搖了搖頭，定下心神。>\n\n無所謂，回想過去的事也沒用。\n\n我們的首要目標是削弱他們的數量，這樣才能找出是什麼東西…或什麼人，導致了這場入侵。\n\n想辦法消滅那些不死生物吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63483] = {title = "法師結界", objective = "協助埃薩和洛摩斯鞏固安寧地的防線。", description = "這不是隨便的進攻…我強烈懷疑背後有強大的生物在操控這些天譴軍團。\n\n統御之盔粉碎後，就有很大的風險，讓有心人士可以暫時控制不死生物。\n\n我跟洛摩斯會幫忙保衛安寧地，但我們得突破他們的陣線。\n\n幫我們掃蕩一個區域，看看是否能引出他們的首領。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63484] = {title = "騎士的武器", objective = "取得安寧地上方的三叉矛。", description = "顯然這個煞婪決定利用天譴軍團的力量來強化自己。我們可以一直擊退他，但他也會一直回來。\n\n我們需要一個能徹底解決他的武器。\n\n我應該有方法。樓上有新鍛造的三叉矛。這武器還沒經過魔法的淬煉，我們得釋放它的所有潛力。這會是我們的聖光武器。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63485] = {title = "誠實之心", objective = "前往昇靈堡的阿格西雅安息地。", description = "如果我們想擊敗沃拉斯，就得增強三叉矛的力量。不過我們不能貪小便宜或強迫別人，這些教訓我現在還記得。\n\n然而，昇靈堡的琪瑞安是引導靈魂到適當歸屬的大師，也許他們願意把一部份力量借給我們。\n\n去昇靈堡，找出方法來強化這把三叉矛吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63486] = {title = "不破意志", objective = "前往瑪卓薩斯的苦痛劇場。", description = "顯然，我們面對的是一個使用可怕魔法讓自己長生不死的人。\n\n我們也知道有另一群人也會使用這種魔法。瑪卓薩斯很熟悉死亡的束縛，也清楚如何顛覆這種束縛。也許某個家族會知道要怎麼幫我們。\n\n去那裡問問要如何打破這種違背自然的循環。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63487] = {title = "返回鬼魂之地", objective = "回安寧地找莉雅德倫女士。", description = "好強的力量！這下就連沃拉斯也絕對擋不住這個武器了。\n\n我們來暗影之境的任務完成了，三叉矛已經成形。\n\n我們回安寧地找莉雅德倫女士吧，希望還來得及扭轉戰局！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63488] = {title = "我是聖光之刃。", objective = "利用強化過的三叉矛殺死死亡之痕的天譴軍團。", description = "是時候把所有力量和訓練運用到戰場上了。\n\n裝上強化的三叉矛，在天譴軍團中殺出一條路吧！\n\n我們在死亡之域門口等你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63489] = {title = "正義到來", objective = "殺死沃拉斯。", description = "你在死亡之痕很快的就解決了天譴軍團，不過我們面前還有更大的目標。現在該來對沃拉斯測試你的武器威力了。\n\n一起解決他吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n帷幕之觸三叉矛"}
MultiLanguageQuestData['tw'][63490] = {title = "血騎士", objective = "在銀月城收下莉雅德倫女士的綬章。", description = "雖然耗盡了三叉矛的力量，但我們勝利了！擊敗沃拉斯後，也許能更容易對付那些天譴軍團了，這都多虧你的協助。\n\n回銀月城找我吧，大家會記得你今天的努力和英勇。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n套裝：血騎士之獻隱匿翡翠陸行鷹"}
MultiLanguageQuestData['tw'][63494] = {title = "鐵砧族長的設計", objective = "找出索爾加登在黑鐵酒吧打賭輸給了誰。", description = "我看到你在看我們的武器。你不知道嗎，這些武器是我親手鍛造的！\n\n目前為止，我設計了一根法杖、一把單手斧和一面盾牌…你喜歡的話，我可以幫你做！\n\n當然，平常的時候我會這樣說。不過我在黑鐵酒吧的打賭中輸了這些設計圖。如果你能拿回我的設計，然後幫我收集材料的話，我很樂意為你鍛造武器！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63501] = {title = "借用一下", objective = "在影爐城附近找到5個暗鑄錠、一個沸騰焰核和燃點雕刻器。", description = "<這些複雜的藍圖詳細寫了索爾加登對武器的設計，但很難閱讀。凌亂的筆跡在空白處寫著註記，列出了索爾加登為自己留下的修改與說明。\n\n你特別注意到了兩條筆記，其中一則是他把雕刻工具借給獵犬訓練師凱曦安格弗，另一則是好奇他們在黑鐵酒吧到底雇了多少元素來幫忙釀酒。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63519] = {title = "不公平的戰鬥", objective = "向戰鬥王杉恩證明你的力量。", description = "懦弱的害蟲，居然欺騙自己、逃過死亡的榮耀？呸！\n\n我有東西可以直接砍倒他，不過這種程度的強化需要夠強的人才能掌握。\n\n讓我見識見識你的膽量和戰鬥技巧吧！如果你能證明自己的實力，我就會幫你強化三叉矛。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63522] = {title = "公平競賽", objective = "和凡德洛來場誠實競賽。", description = "我們琪瑞安很熟悉拒絕穿過帷幕的靈魂，我可以幫你。\n\n但在我授予你的武器力量之前，我得確定你不會濫用這股力量，而且你必須有顆真誠的心靈。\n\n我們來比賽吧。沿著路線，敲響鐘聲。如果你心靈純潔，鐘聲會加快你的速度。你必須敲響五個鐘，才能完成比賽。\n\n不要分心想抄捷徑，也不要想作弊來取得領先，旁門左道是行不通的。\n\n你準備好了嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63543] = {title = "死靈領主進攻戰", objective = "在墮滅堡和寂滅之面完成1個任務。", description = "我們的攻擊行動把閻獄之主的爪牙打了個措手不及。我們要攻破墮滅堡，然後在統御祭壇擊敗他的勇士！\n\n淵喉行者，我們需要你的幫忙。去戰場上支援我們的部隊吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n不死軍團戰爭寶箱"}
MultiLanguageQuestData['tw'][63545] = {title = "擬訂計畫", objective = "將3個百衛零件和15個靈動機螺栓帶去給米卡尼寇斯。", description = "趁著瑪卓薩斯在攻打大門的時候，我們可以利用百衛進攻側門。\n\n許多受到閻獄之主腐化的百衛殘骸四散在這個區域。我們可以利用這些零件打造出新的百衛，協助我們攻打敵人。\n\n請你幫忙收集零件，讓我們能夠打造出新的百衛。", progress = "你找到我所需要的那些零件了嗎？", completion = "這些零件足夠我們打造出新的百衛！", rewards = "您會收到：\n\n粉碎鐵壁戰鬥冥想輔助工具靈癒者兜帽靈癒者護腿送魂使頭盔鍛造助手頭盔盾衛巨盔盾衛護脛天鐘項鍊閃耀光輝凋萎瘟疫地動雷竄\n                            顯示 14 更多                        煉獄蔓延惡魔疾速聖光匯聚迴盪呼喚嗜血體驗猛烈毒藥以太珍釀純潔省思勇氣思量楷模編年史手持靈魂之鏡乾燥恩典花瓣香爐壞掉的百衛控制器晉升者"}
MultiLanguageQuestData['tw'][63576] = {title = "第一步棋", objective = "到奧睿博司與軍政官阿德雷特斯交談。", description = "在誓盟團結起來捍衛暗影之境的同時，閻獄之主在托迦司裡頭也沒有閒著。他似乎正在盤算推動下一階段的計畫。\n\n軍政官阿德雷特斯從樂土堡帶來了令人不安的消息。等你抵達後，他就會告訴你發生了什麼事情。\n\n請不要耽擱，我們可用的時間正在急遽消逝。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63578] = {title = "亞登曠野之戰", objective = "在亞登曠野之戰中保護凜冬女王的符印。", description = "戴納瑟斯王背叛了我們，瑪卓薩斯的統御者也消失無蹤，想必閻獄之主的下一個目標就是凜冬女王。\n\n我們絕不會讓任何人奪走她的符印！\n\n亞登曠野經歷了許多苦難，但那個界域依舊充滿著強大的神祕能量。凡事並非總是如表象那樣簡單。\n\n不論女王面臨到什麼樣的危險，我們都會利用這點來應變。", progress = nil, completion = "我們差點就沒能活下來！我真的是做夢也想不到會發生那種事。\n\n但這一切還沒結束，我們不能鬆懈下來！", rewards = "妖精誓約鉤刺妖精誓約旋刃妖精誓約大刀妖精誓約鐮刀妖精誓約戰槌妖精誓約戰棍妖精誓約引導節根妖精誓約戰弓妖精誓約裁決錘妖精誓約法刃您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][63579] = {title = "聖騎士的靈魂", objective = "從托迦司的放逐者骨窖取回正義殘餘物。", description = "在伯瓦爾‧弗塔根所預見的景象中，托迦司的深處藏有一個房間，閻獄之主會把對他有利用價值的靈魂關在裡面。\n\n烏瑟曾被一把哀傷之刃擊倒。當滿懷憤怒之人揮舞這種武器時，就連靈魂也會四分五裂。\n\n如果閻獄之主手上握有烏瑟的一部份靈魂，那麼除非我們能將失去的部分奪回，否則烏瑟的靈魂永遠也無法癒合。\n\n$p，帶著這個同調裂片前往托迦司。這個裂片應該能夠指引你找到靈魂的所在位置。\n\n找到烏瑟靈魂的失落碎片，他才有可能重歸完整。", progress = "淵喉行者，你好。你來得正是時候。", completion = "我認為這個靈魂碎片會是烏瑟能否痊癒的關鍵。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63580] = {title = "受傷的記憶", objective = "幫助烏瑟建立與正義殘餘物之間的連結。", description = "烏瑟受傷的靈魂到來時，確實促成了許多我們目前陷入的困境。\n\n德沃絲的信念碎裂、她跟黑爾雅之間建立的關係。棄誓者的崛起。\n\n昇靈堡需要改變，但我們卻遲遲找不到方法。\n\n說不定這個靈魂碎片…能夠給我們一些啟發。", progress = nil, completion = "雖然烏瑟的靈魂正在受苦，但我們不能因此絕望。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63581] = {title = "步入光明", objective = "使用靈魂之鏡幫助烏瑟探索自己的過去。", description = "這是我最擔心的情況。\n\n烏瑟靈魂的這一部分遭到殺害他的哀傷之刃腐化。他的記憶破碎而扭曲。\n\n要讓烏瑟放下這段過去的痛苦、讓他的悲慟平息，他必須先重新經歷一遍。\n\n但他不必獨自承受。\n\n使用我的靈魂之鏡，我們就能幫助烏瑟重新面對這些回憶，讓他接受其中蘊含的情感。我們必須幫助他看透其中的扭曲，了解事情的真相。", progress = nil, completion = "他的記憶扭曲變形。\n\n我很抱歉，烏瑟。但我們必須繼續。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63582] = {title = "他是我的學生", objective = "協助烏瑟探索他的第二段記憶。", description = "有關那個阿薩斯王子的回憶對烏瑟造成了很大的創傷。正是因為阿薩斯的關係，烏瑟的靈魂才會支離破碎，德沃絲也才會墮落。\n\n這些記憶所涉及的痛苦劇烈到難以想像。\n\n我們必須繼續深掘。烏瑟必須面對這個黑暗的源頭。\n\n你需要再次進入他的過往，如此才能捍衛他的未來。", progress = nil, completion = "背叛所帶來的傷痛對烏瑟造成了很大的創傷。但是他不會被打敗。\n\n他不能失敗！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63583] = {title = "我打算永生不死", objective = "協助烏瑟探索他的最後一段記憶。", description = "拜託了，<name>。這件事情還沒有結束。\n\n我還必須探索最後一段回憶。必須面對的回憶。\n\n這段回憶…不堪回首。我需要你們大家的幫忙。\n\n我們必須這麼做。", progress = nil, completion = "&lt;阿德雷特斯回過神來，炯炯有神的雙眼充滿決心。&gt;\n\n我認為這次的經驗正是烏瑟需要的契機。也是我尋找的最後一塊拼圖。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63584] = {title = "凱旋而歸", objective = "到樂土堡與卡莉賽恩碰面。\n\n琪瑞安信差可以帶你飛過去。", description = "<name>，這座神殿象徵著昇靈堡嶄新的曙光。\n\n奉獻神殿將成為我們共同努力的基石。我們會跟棄誓者合作，也會不分身分來歷接納所有的志士與琪瑞安，攜手打造出大家都能引以為榮的未來。\n\n我們回去樂土堡吧。我希望你能夠出席這個重要的場合，見證新楷模的晉升、見證新符印的誕生。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63585] = {title = "盲目的忠誠", objective = "到樂土堡與軍政官阿德雷特斯碰面，然後陪伴他晉見御靈者。", description = "現在，我知道琪瑞安未來該何去何從了。\n\n首先，我們要去跟尼可隆談談。我希望你能夠留下來聽聽。\n\n之後我們會回去樂土堡。\n\n我要請求晉見御靈者，而且屆時我需要你們陪伴在我身旁。", progress = nil, completion = "&lt;阿德雷特斯深深一鞠躬。&gt;\n\n這是我的榮幸，但我們才剛剛開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63586] = {title = "奉獻的憐憫之情", objective = "到侍者休憩處與阿德雷特斯碰面。", description = "我們第一件要做的事情，就是重新調整忠誠神殿的用途。\n\n佩拉苟斯自願留在這裡協助準備進行儀式。我希望尼可隆能夠帶領他的夥伴到侍者休憩處找我們，協助我們說服一部分的棄誓者跟隨我們踏上新的道路。\n\n如果你方便的話，就到那邊與我們碰面吧。", progress = nil, completion = "我們開始吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63587] = {title = "可以回收的靈魄", objective = "從棄誓者百衛體內收集5個污化的百衛機兵核心。", description = "<name>，米卡尼寇斯跟我解釋了很多有關棄誓者百衛的事情。\n\n我不敢說我全部都能理解，但看樣子他還沒找到穩定可靠的方法讓那些百衛恢復到正常的運作狀態。\n\n不過，他們體內的靈魄應該還能派上用場！\n\n阿德雷特斯一直專心在思考如何調整神殿的用途，卻忽視了自身的安全。我擔心他的靈魄在過程中會被吸乾。\n\n如果你能夠取出棄誓者百衛體內的核心，阿德雷特斯就會有靈魄貯存可以使用。", progress = "我最近跟米卡尼寇斯合作，研究要如何重新利用棄誓者百衛機兵的靈魄。放心交給我來處理吧！", completion = "謝謝你，&lt;name&gt;。有了這些靈魄，即便阿德雷特斯有個三長兩短，我也能夠把他給救回來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63588] = {title = "重建信念", objective = "說服10個棄誓者重返道途。", description = "<name>啊，棄誓者迷失了自我。\n\n他們就像是鬼魂一樣，遊蕩在忠誠神殿。哪裡也去不了。群龍無首、漫無目的、失去歸宿。\n\n我們必須讓他們看見向前的道路。\n\n我會陪你一起進去神殿。由我來與他們談話，我會喚醒他們的理智。說不定我們還能說服他們，讓他們願意試試看阿德雷特斯的新道路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63589] = {title = "導向正軌", objective = "將靈魄從忠誠要塞引導至神殿。", description = "昇靈堡的五大神殿自古以來就屹立不倒。從來沒有人思考過可以調整其中一座神殿的用途，這麼做肯定需要消耗大量的靈魄。\n\n這座神殿的地底下方貯藏著許多靈魄，是我們在乾旱期間限制使用的重要補給。如今，靈魄再次流淌在我們的界域之中，我們可以改利用這些靈魄貯藏完成現在的目標。\n\n你必須使用地表上的引導器和收集器，引導靈魄流到頂端。如此一來，我應該就能獲得我所需要的能量。", progress = nil, completion = "看到這麼多的靈魄再次流淌在我們的界域之中，讓我內心感到欣慰。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63590] = {title = "禱鐘響起", objective = "在軍政官阿德雷特斯重新調整忠誠神殿的用途時保護他。", description = "我們的正道從現在起不再要求追巡者盲目獻忠誠，而應該激發來自內心的美德。提供一個正確的選擇。\n\n我們必須對遭遇難關的人們展現赤誠的奉獻之心，不論對方是最近剛到來的靈魂，還是需要我們伸出援手的同伴。\n\n我會使用我手邊所有的靈魄來改變這座神殿的意義，替琪瑞安開創嶄新的紀元。\n\n淵誓者恐怕會試著阻擾我們的計畫。<name>，請在儀式進行時保護我。我必須親自完成這件事情。", progress = "<阿德雷特斯正全神貫注在自己的任務上，沒辦法分心。>", completion = "奉獻…源自於憐憫之心。源自於侍奉的精神。\n\n這樣的教條，確實有其價值。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63591] = {title = "盛大的歡迎會", objective = "與卡莉賽恩交談以參加聚會，然後和你的靈魂之絆還有其他琪瑞安互動。", description = "<name>，你在琪瑞安最艱難的時刻向我們伸出援手。你的無私奉獻，幫助我的族人迎來了嶄新的開始。\n\n如果你願意來參加儀式開始前的聚會，我們會感到很榮幸的。我們誓盟的許多成員都對你滿懷感激，並且希望能夠對你有所表示。\n\n今天是個充滿喜悅的一天。真高興你能來現場親眼目睹這一切！", progress = nil, completion = "儀式即將展開。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63592] = {title = "新的道路", objective = "與卡莉賽恩交談，參加在御靈者之座舉辦的儀式。", description = "今天會有新的楷模誕生。自從我們的界域產生以來，首次有神殿被改建，從此將象徵我們對彼此的關懷與奉獻。\n\n新的楷模、新的符印，以及琪瑞安的嶄新道路。\n\n這場儀式意義著實非凡！", progress = nil, completion = "我從沒想過能夠擁有這份榮耀。\n\n前方的路途很漫長，但只要有琪瑞安同胞的支持，奉獻神殿就會帶領我的族人共創未來。\n\n真正的挑戰現在才要開始。", rewards = "您會收到：\n\n御靈者飛羽"}
MultiLanguageQuestData['tw'][63593] = {title = "琪瑞安的新符印", objective = "回去科西亞找統御者。", description = "昇靈堡的未來將由羈絆與奉獻精神構築，新的符印應運而生，象徵著我族前方的道路。\n\n請去跟統御者回報你做的一切。一旦他準備就緒，我們就會把符印送去給他。\n\n希望他能夠使用這個符印來阻止閻獄之主的計畫並拯救暗影之境。", progress = nil, completion = "基瑞絲緹雅是第一位為了職責與侍奉而展翅高飛的人。\n\n凡人，你協助御靈者找到了通往未來的新道路，這樣的成就著實可貴。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][63594] = {title = "淨空城牆", objective = "使用過載勇士消滅墮滅堡城牆邊的6個亡魂尖塔。", description = "<這個卷軸顯示出一系列水晶塔的所在位置，這些水晶塔負責保護墮滅堡不受攻擊。\n\n摧毀這些水晶塔應該能夠幫助我方進攻。>", progress = nil, completion = "敵方的守軍潰敗了！淵喉行者，做得好。", rewards = "您會收到：\n\n四分之一的古代戒指冥魄維娜里"}
MultiLanguageQuestData['tw'][63603] = {title = "犛牛靈魂", objective = "將氂牛靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<氂牛靈魂真摯而堅韌。你將來能任意化身為蠍尾獅之形態。>", progress = nil, completion = "啊，蠍尾獅。你現在可以任意使用這個形態了。", rewards = nil}
MultiLanguageQuestData['tw'][63604] = {title = "鍬牙靈魂", objective = "將鍬牙靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<鍬牙靈魂防衛心強又堅定。你將來能任意化身為鍬牙之形態。>", progress = nil, completion = "啊，鍬牙。你現在可以任意使用這個形態了。", rewards = nil}
MultiLanguageQuestData['tw'][63605] = {title = "尖角蜥靈魂", objective = "將尖角蜥靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<尖角蜥靈魂靈敏又聰明。你將來能任意化身為尖角蜥之形態。>", progress = nil, completion = "啊，是尖角蜥。你現在可以任意使用這個形態了。", rewards = nil}
MultiLanguageQuestData['tw'][63606] = {title = "蜘蛛靈魂", objective = "將蜘蛛靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<蜘蛛靈魂靈巧又狡猾。你將來能任意化身為蜘蛛之形態。>", progress = nil, completion = "啊，蜘蛛。你現在可以任意使用這個型態。", rewards = nil}
MultiLanguageQuestData['tw'][63607] = {title = "恐角龍靈魂", objective = "將恐角龍靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<恐角龍靈魂殘暴而頑強。你將來能任意化身為恐角龍之形態。>", progress = nil, completion = "啊，恐角龍。你現在可以任意使用這個型態。", rewards = nil}
MultiLanguageQuestData['tw'][63608] = {title = "河馬靈魂", objective = "將河馬靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<河馬靈魂相當兇猛。你將來能任意化身為河馬之形態。>", progress = nil, completion = "啊，河馬。你現在可以任意使用這個型態。", rewards = nil}
MultiLanguageQuestData['tw'][63609] = {title = "科多獸靈魂", objective = "將科多獸靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<科多獸靈魂沉靜又忠實。你將來能任意化身為科多獸之形態。>", progress = nil, completion = "啊，科多獸。你現在可以任意使用這個形態了。", rewards = nil}
MultiLanguageQuestData['tw'][63610] = {title = "長毛象靈魂", objective = "將長毛象靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<長毛象靈魂勇敢又防衛心強。你將來能任意化身為長毛象之形態。>", progress = nil, completion = "啊，長毛象。你現在可以任意使用這個型態。", rewards = nil}
MultiLanguageQuestData['tw'][63611] = {title = "Rune Chest Opened", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][63612] = {title = "指揮鏈", objective = "在德司莫泰隆附近與德拉卡碰面。", description = "如果我們要在這麼接近閻獄之主地盤的位置建立據點，那我們就必須做好萬全的打算。\n\n維拉斯和黑爾雅目前撤退到了德司莫泰隆的城牆內側。他們以為自己的處境很安全，因此鬆懈了下來，替我們製造出了大好機會。\n\n我們要趁人不備展開奇襲。以快狠準的攻勢，毫不留情地痛擊對手，這樣子我們說不定能夠直搗黃龍，讓敵人變得群龍無首。", progress = nil, completion = "對方還沒發現我們。但我們的行蹤早晚會暴露。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63613] = {title = "遭譴者之門", objective = "召喚4個死亡之門。", description = "在打信號給澤瑞奎斯之前，我們必須先準備好發動攻擊。在一切準備就緒之後，我們的盟友會開啟死亡之門攻擊目標地區。\n\n我們必須從這裡召喚死亡之門。找出合適的戰略位置吧。", progress = "等我們召喚出全部的死亡之門之後，真正的戰鬥才會開始。", completion = "這樣子應該足以讓我們的大軍通行了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63614] = {title = "手中的武器", objective = "找到索爾的斧頭德葛拉。", description = "請等一下，<name>。\n\n我們第一次在淵喉遇到黑爾雅的時候，我朝對方丟出了我的斧頭「德葛拉」，自從那之後，我就再也沒有見到它了。如果這裡真的是她的地盤，說不定我的斧頭也在這裡。\n\n那是我在納葛蘭親手打造的斧頭，它有著許多我跟家人相處的美好回憶。我希望能夠再次把那個斧頭握在手裡。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63615] = {title = "奪其翅膀", objective = "使用淵誓鎖鍊殺死6個獄誓破魂者。", description = "整個天空都被黑爾雅的琪瑞安手下給遮蔽了。如果不削減對方的數量，澤瑞奎斯和我們的空中盟友就難以推進戰線。\n\n我發現淵誓者習慣使用魔法鎖鏈。我們可以利用對方的裝備來反制敵人，把他們從天空中抓下來。", progress = nil, completion = "我們要讓敵人知道，就算是飛在空中，我們也能對他們出手。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63616] = {title = "開張順利", objective = "打信號給澤瑞奎斯，展開攻勢。", description = "接下來，我們應該能夠展開攻勢了。\n\n打信號給澤瑞奎斯。我們要讓對手見識一下瑪卓薩斯亡城的威力，讓他們知道暗影之境聯軍不是好惹的！", progress = nil, completion = "機會來了，向前推進吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63617] = {title = "強行突破", objective = "殺死鐵衛薩力克斯。", description = "這個地方戰況混亂，上層的大門無人看守。如果我們悄悄溜進去，對方說不定根本就來不及察覺。\n\n只有一位黑爾雅的心腹擋住我們攻進黑爾嘉德要塞的去路。去消滅這個對手！", progress = nil, completion = "接下來，我們要在這邊製造混亂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63618] = {title = "瑪卓薩斯最擅長的事", objective = "在德司莫泰隆上層殺死10個淵誓者。", description = "每多殺死一個敵人，我們的盟友就少一個麻煩。我們要提醒敵人，瑪卓薩斯正是為了戰鬥而存在。讓他們見識一下，膽敢威脅到暗影之境安危的人會有什麼樣悲慘的下場。\n\n殺死你所看到的每一個淵誓者。", progress = nil, completion = "他們居然愚蠢到以為自己的武力有辦法與我們相抗衡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63619] = {title = "被遺棄的棄誓者", objective = "拯救5個棄誓者囚犯。", description = "等等…我認得你！淵喉行者！\n\n我的兄弟姊妹們遭到扭曲…遭到腐化。有些人自甘墮落，接受黑爾雅的力量，也有人努力反抗到底。但最後，我們大家都被迫臣服於她的力量。\n\n我在戰鬥開始的時候順利逃脫，但大多數倖存的棄誓者現在正受到恐怖的儀式折磨。\n\n拜託了，請你一定要解救他們。我們會回去昇靈堡，自願接受御靈者的審判。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63620] = {title = "叛徒的死期", objective = "殺死維拉斯。", description = "維拉斯自從叛變以來，一直都是瑪卓薩斯的眼中釘、肉中刺。身為天選者家族的女爵，我必須負責消滅這個威脅…並且為藩侯克利瑟斯復仇。\n\n誠如統御者所說，擒賊先擒王，我們必須殺掉對方的領袖。\n\n現在就是出手的時機！", progress = nil, completion = "&lt;德拉卡朝著維拉斯的屍體吐口水。&gt;\n\n叛徒死了，瑪卓薩斯將再次團結一心！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63621] = {title = "拉動鎖鏈", objective = "消滅鎖鍊守衛者。", description = "據說這傢伙稱之為鎖鍊守衛者。千萬不可以小看他的力量。他束縛了附近的靈魂，準備要對我們的所在位置發動攻擊。\n\n淵喉行者，我需要你在他攻過來以前，消滅這個威脅。", progress = nil, completion = "&lt;name&gt;，我就知道你靠得住。", rewards = "您會收到：\n\n百衛機兵能量核心靈癒者裹手靈癒者兜帽靈癒者護腿靈癒者腕輪送魂使手套送魂使頭盔送魂使護腕鍛造助手頭盔鍛造助手腿甲鍛造助手腰鍊鍛造助手腕甲\n                            顯示 11 更多                        盾衛巨盔盾衛護脛盾衛護臂銀符披風鍛造工匠的燃煤以太珍釀純潔省思勇氣思量手持靈魂之鏡乾燥恩典花瓣香爐晉升者"}
MultiLanguageQuestData['tw'][63622] = {title = "光榮奪勝", objective = "回去科西亞找統御者。", description = "解決了黑爾雅和維拉斯後，我們今天對抗淵誓者，算是拿下了一場大勝利。這也展示了暗影之境整體團結起來的力量。\n\n我們最好盡快回到科西亞，免得一波未平，一波又起。", progress = nil, completion = "我們顯然必須再次對德司莫泰隆施壓。\n\n只要華爾琪的女巫還有一口氣在，她就絕對不會放過我們。", rewards = "您會收到：\n\n通靈塔聚焦水晶名望"}
MultiLanguageQuestData['tw'][63623] = {title = "王座空缺", objective = "回到統御者之座。", description = "淵喉行者。\n\n我不在的這段時間，你盡心盡力重振這裡的秩序，並讓死靈領主誓盟得以恢復元氣。為了表示感謝，我想要邀請你見證一場典禮。\n\n跟我一起回去我在瑪卓薩斯的權力核心。你對我們如此忠心耿耿，我也是時候予以回報了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63624] = {title = "所經之路", objective = "見證德拉卡的晉升儀式。", description = "瑪卓薩斯的軍隊很強大。即便維拉斯做出大逆不道的事情，大家也依舊能夠振作起來。\n\n我們的當務之急，就是重建一切。淵喉行者，一起來見證瑪卓薩斯的嶄新紀元吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63625] = {title = "拿起斧頭向前衝！", objective = "消滅15個淵誓部隊和指揮官馬拉默特。", description = "我方部隊遭遇到敵人的頑強抵抗！淵喉行者，拿起武器主動出擊、痛宰敵人吧！\n\n消滅防禦大門的淵誓者部隊及其指揮官。", progress = nil, completion = "淵喉行者，勝利會是屬於我們的！", rewards = "您會收到：\n\n戰鬥之焰回春藥水跳動的憎惡體核心血煉勳章血煉戒環腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼血煉護杖血煉骨鋸血煉巨杖血煉之弩\n                            顯示 10 更多                        血煉法刃疫蝕穿刺花開花落疫蝕穿刺瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件儀式實用死靈術手札競技場土壤罐不死軍團"}
MultiLanguageQuestData['tw'][63638] = {title = "不能坐視不管", objective = "確認凜冬女王的安危。", description = "總算是…暫時…處理了希瓦娜斯和淵誓者的威脅。\n\n但是我們得快點確保女王和她的符印的安全。\n\n凜冬女王在森林之心外面，保護野性種子不被淵喉奪走。", progress = nil, completion = "亞登曠野仰賴著生死輪迴的循環。如果沒有了這些魂靈，那還有什麼意義呢？\n\n我不能讓閻獄之主的爪牙摧毀我們努力捍衛的一切。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63639] = {title = "前往奧睿博司回報", objective = "回到奧睿博司去找塔因納拉。", description = "亞登曠野成功抵擋住了攻勢強勁的淵喉爪牙。\n\n但這麼做還是不夠。\n\n回到奧睿博司去找盟友。必須要有人為這次的損失付出代價，我們要採取制裁行動。", progress = nil, completion = "閻獄之主開始對奧睿博司發動攻擊了。\n\n我最大的憂慮如今已經成真。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63644] = {title = "壞消息", objective = "到瑞文崔斯的曙光要塞和雷納瑟王子交談。", description = "不能低估納斯雷茲姆對我們部隊造成的威脅。他們的狡猾跟蛛眼家族最老練的精兵有得比，而我們對他們的計畫卻一無所知。\n\n幾千年前，有個汎希爾人用怒火將納斯雷茲姆逐出暗影之境。\n\n前往罪殞城，找到雷納瑟王子並把這份文件交給他。我會派我的間諜瓦許女爵，到那邊跟你會合。你可以借助她在對抗納斯雷茲姆上的經驗。", progress = "這的確是個壞消息。", completion = "納斯雷茲姆回來了？真不敢相信他們還能這麼大膽。\n\n可惜他們沒有從流放中獲得教訓，反而還以敵人的身分回來了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63645] = {title = "曙光要塞囚犯", objective = "聽雷納瑟王子訴說戴納瑟斯王的遭遇。", description = "噢，你還沒聽說吧。\n\n我們逮到他了。瑞文崔斯的主宰戴納瑟斯王被囚禁在自己的刀刃裡面。\n\n我們在攻打納撒亞城的戰事中，擊敗了那個傢伙。\n\n我們派出了無比英勇的軍隊，使盡一切努力準備。我們用上了所有技術技巧和財富。即便如此，能夠成功還真是一場奇蹟。\n\n也就是這樣，救贖者迎來了救贖。你還想要繼續聽我說嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63646] = {title = "誓盟車隊", objective = "召集特使並前往威權之門。", description = "我們需要全部七個勳章才有辦法鑄造新的汎希爾符印。\n\n統御者是正確的。我們需要的人正是石鑄宗匠。她對無形者的憎惡無窮無盡，而且她手上握有我們需要的最後一個勳章。我認為我們早就該說服她加入我們的陣營了。\n\n我來負責安排相關事宜。這次要先準備好禮物和外交禮儀再前去拜訪。\n\n你最好先讓雪拉知道，讓她能夠安排護送事宜。", progress = "淵喉行者，你帶了什麼給我？聽好了，我對欺瞞絕不容忍，也曾有信使被我抓去餵石獸。", completion = "嗯，統御者的親筆信？我還在想那個老暴君現在怎麼樣了。\n\n&lt;快速檢閱了傳遞過來的信。&gt;\n\n原來如此…。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63647] = {title = "無形訪客", objective = "在石鑄宗匠調查使者的企圖期間，跟她一起行動。", description = "驚懼領主。\n\n是啊。我怎麼沒想到呢？他們此時不回來找我們麻煩更待何時？我懷疑他們早在乾旱期間就已經回來了。\n\n我第一次看到你的時候，還在想你會不會是他們其中一人。自從他們逃離瑞文崔斯，已經過了好久好久的時間，如今的他們更加狡詐。\n\n但他們還不夠聰明…應該吧。\n\n來吧，淵喉行者。跟我來，不要大驚小怪。隨時準備好開戰。你帶來的這位使者可能不像你所想的那樣心懷好意。", progress = nil, completion = "從以前到現在，雪拉其實一直都是納斯雷茲姆嗎？\n\n沒想到即便是在死後世界，我也必須對付納斯雷茲姆的陰險計謀。看來我的戒心在懺悔的過程中變得太過懈怠了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63648] = {title = "納拉加斯", objective = "追殺並擊敗納拉加斯。", description = "我們不能讓納斯雷茲姆繼續持有石鑄宗匠的勳章。\n\n根據控罪者對我們任務的說明，我們必須要取得那個勳章才有辦法打造新的汎希爾符印。我相信這就是納拉加斯和她的爪牙剛才發動伏擊的原因。\n\n勳章的魔法並不隱密。在這個界域中，其效果很容易追蹤。我建議立即展開追獵，在納拉加斯獲得增援前將她消滅。", progress = nil, completion = "我跟石鑄宗匠談過了。我被關在淵喉裡面的時候，雪拉遭到主宰殺害。\n\n過去幾百年以來，她一直都是我的朋友也是我的保護者，我一開始甚至不曉得她已經命喪黃泉、身分還遭到冒用。\n\n戴納瑟斯又多了一項罪行得償還代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63649] = {title = "諜對諜", objective = "追蹤並擊敗5個驚懼領主滲透者。", description = "納斯雷茲姆。驚懼領主。無形訪客。\n\n他們種族有很多名字。他們在很久很久以前被創造出來，為的是成為整個宇宙中最厲害的間諜與滲透者集團。\n\n他們這次的入侵行動低估了三個人。凱爾薩斯‧逐日者、瓦許女爵和<name>！\n\n我帶了一個與凱爾薩斯一同效忠伊利丹時使用過的工具，可以偵測納斯雷茲姆。我才是統領間諜的總管！\n\n我們出發去獵殺間諜吧。", progress = nil, completion = "汎希爾族變得自大狂妄，不願意接受納斯雷茲姆可能已經捲土重來的真相。正是因為這樣的盲目，才會導致他們遭到戴納瑟斯的背叛。\n\n現在他們應該懂得要更警惕了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63650] = {title = "反滲透", objective = "到罪殞城與雷納瑟王子碰面。", description = "瑪爾加尼斯。\n\n我已經許久的時光沒有談論起他的名字了。現在，我們必須獵殺他。\n\n如果他握有憤怒勳章，那麼他將無所遁形。我們可以利用手邊的其他勳章來追查他的行蹤。\n\n到罪殞城來找我，同時帶上你的驚懼領主獵殺小組。我感覺我們會需要更多人手幫忙。", progress = nil, completion = "雖然納斯雷茲姆不是汎希爾，但他們也不是以靈魂打造而成。從許多方面來看，他們比其他的汎希爾同胞都更像是我的手足。\n\n可惜啊，他們誤入歧途。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63651] = {title = "密文", objective = "抄錄10個煉獄火密文。", description = "如果納斯雷茲姆真的已經滲透到罪殞城內部，那麼他們一定會彼此溝通聯繫，而且不可能只透過手勢或言語這麼簡單。他們喜歡使用魔法把訊息寫出來，並利用簡陋的法術加以隱藏，讓一般人無法看見。\n\n我研發出一種魔咒，能夠讓你看見這些訊息。\n\n把這些密文給找出來，並告訴我裡面寫了些什麼。如果內容太艱澀你看不懂的話，我可以幫你翻譯。", progress = nil, completion = "這沒有道理啊。他們的目標看起來太過分散了。我原本還在猜想，他們應該是打算要偷走我的勳章防止我們獲得新的汎希爾符印。但現在看起來，他們的企圖遠遠不只如此。\n\n他們到底想要幹什麼？來，這個翻譯過後的文本給你。", rewards = "您會收到：\n\n翻譯的密文"}
MultiLanguageQuestData['tw'][63652] = {title = "不速之客", objective = "在罪殞城消滅3個納斯雷茲姆。", description = "雪拉…我是說納拉加斯，她應該不是獨自一人行動的。我們必須做最壞的打算，我們的朋友和盟友之中，可能混入了敵人。\n\n收割者廷衛需要一點時間，才有辦法進行偵測儀式。我們在進行儀式的時候，會處於毫無保護的狀態。我需要你使用你當時在罪殞城的威權之門所使用的招數，把潛藏在我們之中的納斯雷茲姆揪出來。\n\n祝你狩獵順利。", progress = nil, completion = "欺敵和壓制暴亂向來不是我的長項。這樣的任務原本會交派給其他更能夠勝任的靈魂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63653] = {title = "王冠權能", objective = "追蹤憤怒勳章。", description = "我們準備好了。\n\n收割者廷衛會使用我們目前手邊所握有的勳章來尋找憤怒勳章。只要對方還沒有把勳章移動到其他界域，我們應該就能夠追查出勳章的下落。\n\n這個儀式並不容易，而且納斯雷茲姆特別擅長避人耳目。當你看到道路出現的時候，千萬不能猶豫，要加快腳步展開行動。\n\n等你找到對方，先等我們抵達再開戰。", progress = nil, completion = "我絕不會輕易把勳章交給這些不速之客。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63654] = {title = "納斯雷茲姆", objective = "從納斯雷茲姆手中搶回憤怒勳章。", description = "憤怒勳章不只是強大的古文物。納斯雷茲姆可能會用來將這整個界域扭曲，以達到他們的邪惡目的。除此之外，只要他們還握有勳章，我們就無法重新打造新的符印。\n\n他們魯莽的詭計已經造成餘燼區幾乎完全毀滅。我不會讓他們濫用我的勳章。\n\n走吧，我們去搶回來。", progress = nil, completion = "情況比我想像的還要糟糕。", rewards = "您會收到：\n\n時朽罪孽石"}
MultiLanguageQuestData['tw'][63655] = {title = "憤怒勳章", objective = "將憤怒勳章帶到罪殞城的平臺。", description = "淵喉行者。我會率領石源魔前往淵喉的深處，摘下每一個納斯雷茲姆的頭。\n\n不過，瑞文崔斯仍然具有重要的戰略價值，不能夠因為一時的自負而掉以輕心。\n\n因此，身為第二任憤怒收割者的我，在此將勳章委託給你，在我指揮戰爭的時候，由你來保管並使用這個勳章。\n\n使用勳章來強化收割者，阻止戴納瑟斯捲土重來，否則他將輕易奪回權位。", progress = "<平台感應到勳章的接近，開始竄出能量。>", completion = "&lt;將勳章放入插槽時，你的靈魂隨著能量連結在一起而感受到強烈的震撼，周遭的一切頓時充滿意志與企圖，你從未感受過這種能量。\n\n攜手同心，收割者在瑞文崔斯的統治地位無可動搖。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63656] = {title = "憤怒的意義", objective = "向統御者回報。", description = "我會召集麾下的部隊，並立刻派遣一部分的兵力前往科西亞。我也會將瓦許女爵和凱爾薩斯召喚的器具分發下去，讓部隊有辦法進一步阻止納斯雷茲姆的入侵。\n\n我必須先處理其他事務，才有辦法親自前去科西亞。我必須保護威權要塞不受到進一步的滲透。\n\n我想統御者應該會想要知道最新的情報。你可以去告訴他，說你成功了。", progress = nil, completion = "你在戰場上的力量向來無人能及。但是今天，你還證明了你的外交實力。\n\n我已經發布命令，部署石鑄宗匠的部隊。你讓她願意出面參戰，做得好。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][63659] = {title = "驚懼領主！", objective = "到科西亞跟統御者交談。", description = "這是我本週發現的第五個滲透進我們部隊的驚懼領主。不多加提防的話，他們會對我們的據點造成極大的傷害。\n\n生前我曾跟一位惡魔獵人學習如何辨識驚懼領主。要找出他們對我來說輕而易舉，但我只有一個人，分身乏術。\n\n我們一定要向統御者回報這些發現。", progress = nil, completion = "又有驚懼領主？我早該料到戴納瑟斯的尖牙部屬會再次入侵。\n\n我不在的時候蛛眼家族雖然遭受挫敗，但我很慶幸他們沒有因此迷失方向。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63660] = {title = "淵喉大開", objective = "允許塔因納拉檢視你的靈魄。", description = "閻獄之主又拿到了另一個符印，而他的軍隊已然主動進攻奧睿博司。\n\n伯瓦爾‧弗塔根和瑪卓薩斯的德拉卡建議主動進攻閻獄之主的大本營。\n\n為此，我們必須找方法讓部隊能夠安全地進出淵喉。\n\n在你出現之前，我們以為這是不可能的，但現在我相信有這樣的可能性存在。\n\n我必須檢視你的靈魄，確認這真的是使命所冀盼的事。", progress = nil, completion = "淵喉行者，若不是非不得已，我不會輕易這麼做。但我們別無選擇。\n\n我們必須開啟通往淵喉的傳送通道。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63661] = {title = "連結至淵喉", objective = "詢問維娜里有關第二個甬道石下落的事情。", description = "述命者很確定有第二個甬道石出現在了淵喉。你必須找到它。\n\n我會在奧睿博司這邊製造出繫錨，並將其連結至你的靈魄。在你與新的甬道石同調後，這個繫錨就會跟甬道石連結起來。\n\n如果你成功的話，誓盟就能夠派遣軍隊安全地往返淵喉了。\n\n利用你在淵喉得到的資源找出這個甬道石吧。\n\n祝你好運，凡人。願使命指引我們大家。", progress = nil, completion = "換作是平常的時候，我會認為你的這種要求令人厭煩又無禮。\n\n但最近發生的事情，讓我相信你的提案或許對我們雙方都會有利。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63662] = {title = "淵喉的秘密", objective = "跟隨維娜里一起前往淵喉裡面的新陸塊。", description = "凡人啊，淵喉正在發生改變。轉機也伴隨而至。\n\n閻獄之主把一座藏在暗影之境深處的界域轉移到了淵喉。我對那個地方有相當程度的興趣，但我不想要隻身前往。\n\n是這樣的，那個地方到處都是淵誓者。他們肯定是在尋找某個很有價值的東西。\n\n我在那片土地附近建立了安全藏匿點。跟我一起前往，我說不定能夠幫你找到你所需要的甬道石。\n\n你說怎麼樣？", progress = nil, completion = "閻獄之主極度渴求這裡的某件事物，但他的寶貴眼睛卻無法看穿這個地方的防禦機制。\n\n算了。我們走吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63663] = {title = "玄秘之城科西亞", objective = "讓維娜里掃描這個區域，然後調查找到的東西。", description = "淵喉行者，我們都很接近各自的目標了。\n\n你志向遠大的甬道石應該不遠。當然，我的需求，則是相對樸實許多。東一點有用的情報，西一個無價的古文物…\n\n我們先調查這個區域，看看附近有沒有什麼實用或危險的東西。然後我們再繼續深入。", progress = nil, completion = "淵喉行者，我必須要更進一步了解你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63664] = {title = "重點整理", objective = "保護墮滅堡內部的前進據點。", description = "我們在通往統御祭壇的橋樑附近的據點遭受敵方猛烈攻擊！我們絕對不能失去搭建在那裡的弩砲。\n\n淵喉行者，我需要你去保護那個地方，直到我方部隊能夠推進為止！", progress = nil, completion = "淵喉行者，勝利會是屬於我們的！", rewards = "您會收到：\n\n安全守護戰鬥之焰回春藥水血煉勳章穩定的瘟疫品種保存良好的超凡腦殼鋼核盔帽血絲長袍肉鱗鎖甲護胸鋼核戰靴屍皮肩甲鋼核護肩\n                            顯示 10 更多                        血絲披肩肉鱗披肩托爾托的和諧瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札不死軍團經驗加成"}
MultiLanguageQuestData['tw'][63665] = {title = "通往奧睿博司", objective = "啟動甬道石，前往奧睿博司。", description = "預言曾紀載，有一天淵喉行者會需要用到這個休止的甬道石。說這會影響暗影之境的命運。\n\n看來那一天已然來到。\n\n喚醒你體內的靈魄，啟動這個甬道石。如此一來，任何與你同心一意的盟友都能使用。\n\n如果塔因納拉確實像你說的一樣，在奧睿博司建立了錨點，那就能引導你回來找我們。\n\n<name>，去吧。告訴你的盟友：淵喉等著他們，而科西亞需要他們的協助。", progress = nil, completion = "做得好，&lt;name&gt;。我很想多了解被拉入淵喉的界域。\n\n我們該主動進攻閻獄之主的部隊了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63669] = {title = "來人啊，餵凱文吃餅", objective = "吞噬8個死去的敵人，讓凱文成長為完全體。", description = "我的軟泥怪家族無時無刻不需要更多靈魄，這個地方的屍體正好可以讓軟泥怪飽餐一頓。\n\n軟泥怪吞噬越多的靈魄，就可以成長得越巨大。亡者的殘餘將成為我們的一部分，造就我們這個美妙又快樂的家族！\n\n帶著凱文去吞噬死去的敵人，直到它吃飽為止。接著，等到它成長為完全體時，我們就可以派它去對付敵人！", progress = nil, completion = "淵喉行者，勝利會是屬於我們的！", rewards = "您會收到：\n\n腐蝕液體瓶腫脹怪異心臟穩定的瘟疫品種保存良好的超凡腦殼鋼核盔帽屍皮手套鋼核護手血絲手套肉鱗護手血絲兜帽肉鱗罩盔屍皮頭盔\n                            顯示 20 更多                        鋼核束腰血絲之索肉鱗腰帶屍皮腰帶血絲裹腕鋼核裹腕肉鱗裹腕血煉魔典血煉骨鋸魔導師烙印疫蝕劈斧惡魔疾速聖光匯聚瑪卓薩斯勇士武裝儀式用瑪卓薩岩結晶戰用護甲組件幼年孢子叢儀式實用死靈術手札競技場土壤罐不死軍團"}
MultiLanguageQuestData['tw'][63672] = {title = "來自森林之心的呼喊", objective = "到森林之心與伊瑟拉碰面。", description = "<在你閱讀文字的同時，伊瑟拉的聲音從卷軸裡傳出。>\n\n<name>，\n\n有一件很重要的事情需要你協助。請盡速前往森林之心與我碰面。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63673] = {title = "家族之中的戰士", objective = "到瑪卓薩斯找胡恩‧高嶺。", description = "<name>，我有好消息要告訴你。在誓盟彼此之間的合作變得更加緊密之後，胡恩的搜尋任務進行得越來越順利了。他掌握了有關兩個黑夜戰士所在位置的可靠情報，對方就在暗影之境這裡。\n\n他請你去瑪卓薩斯找他，他會告訴你第一個黑夜戰士在哪裡。胡恩在知識墓穴等你去找他。\n\n<name>，動作快。伊露恩的力量正在吸取泰蘭妲體內的精華。我不曉得她還能撐多久。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63674] = {title = "徵得同意", objective = "在統御者之座與瓦許女士交談，並請求卡莉克的幫助。", description = "女爵瓦許女士派了一個任務給我。如果有人能夠幫我的話，我很快就能夠報仇雪恨。但我們必須先徵得她的同意，這樣我們才能夠互相幫助。\n\n去統御者之座那裡吧。我們會在那邊找她談談。", progress = nil, completion = "如果有你幫忙的話，我應該很快就能把全部的目標都給解決掉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63675] = {title = "無處可逃", objective = "蒐集線索並殺死澤瑪尼。", description = "澤瑪尼與藩侯的死脫不了關係。\n\n辛丹認為他正在替科爾蘇加德招募忠誠的爪牙，準備進行下一個陰謀詭計。\n\n我們要找出有關他下落的線索，然後宰了他。", progress = "叛徒無處可逃！", completion = "其中一位兇手死了，但我不會就此善罷干休，我要他們通通都付出代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63676] = {title = "無處可藏", objective = "取回科爾蘇加德的信物，並殺掉卓瓦歐拉。", description = "有些科爾蘇加德的同夥，在他大肆展開行動後，仍然繼續隱藏其與科爾蘇加德之間的瓜葛。他們同樣必須為藩侯的死負責。他們同樣得死。\n\n我目前掌握了其中一個人的名字，叫作卓瓦歐拉，但除此之外還有很多其他人。辛丹向我透露，這些叛徒身上都帶有科爾蘇加德的信物。她不曉得叛徒的具體身分，所以我們會直接大開殺戒，直到找出真兇為止。\n\n這同時還能起到殺雞儆猴的效果。", progress = "我一定要讓剩下的餘黨嚇得魂飛魄散，然後乖乖就範。", completion = "叛徒無處可藏！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63677] = {title = "你只有死路一條", objective = "在埃索拉瑪斯殺死法辛吉。", description = "我名單上的最後一個目標，是名為法辛吉的巫妖。\n\n辛丹一直都在密切監視他，想要從中了解科爾蘇加德的下一步計畫是什麼。\n\n她想要用殘忍的方法處決法辛吉。\n\n他在祭儀家族的埃索拉瑪斯。", progress = nil, completion = "瑪卓薩斯的叛徒只會有一種下場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63678] = {title = "替阿卡雷克報仇", objective = "在祭儀家族的埃索拉瑪斯與藩侯辛丹碰面。", description = "害死藩侯阿卡雷克的叛徒全都死光了。\n\n雖然這麼做救不回死去的藩侯，但至少我內心舒坦了一點。\n\n女爵大人希望我們在出發前往亞登曠野之前，能夠先去告訴藩侯辛丹，我們的任務已經完成。", progress = nil, completion = "我們絕不允許叛徒的存在。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63679] = {title = "充滿魔法的神秘之旅！", objective = "到瑞文崔斯找月莓女士。", description = "<月莓女士的聲音從卷軸裡面傳了出來。>\n\n<name>！胡恩好像遇到麻煩了。情況…有點棘手。我們需要你到瑞文崔斯幫忙！請到威權要塞來找我。\n\n待會見！", progress = nil, completion = "真高興你這麼快就趕來！我們遇到了一點點小顛簸。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63680] = {title = "瀕臨邊緣", objective = "追查胡恩‧高嶺的下落。", description = "胡恩好像被石鑄宗匠本人抓去別的地方了！\n\n我們來找找看有沒有什麼線索能夠判斷她的去向。說不定這樣子就能找到胡恩！", progress = nil, completion = "我們找到了胡恩，而且還剛好同時找到儀式需要的幫手！\n\n我最喜歡這種皆大歡喜的結局了！對不對啊？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63681] = {title = "回到森林之心", objective = "回去亞登曠野的森林之心前找伊瑟拉。", description = "我們應該盡快趕回亞登曠野！\n\n你直接去找伊瑟拉。我會護送石鑄宗匠，並確保胡恩能夠平安回來。", progress = nil, completion = "真高興再次見到你。我們可能沒有太多時間。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][63682] = {title = "伊露恩之力", objective = "協助進行儀式。", description = "我們時間有限，已經盡力而為。\n\n現在，我們必須把力量借給塞爾納斯和其他人，然後祈禱泰蘭妲能夠活下來。", progress = nil, completion = "太久太久了…", rewards = "您會收到：\n\n角鷹獸靈魂"}
MultiLanguageQuestData['tw'][63683] = {title = "凜冬符印", objective = "把姊妹之淚帶給在森林之心的伊瑟拉。", description = "我的妹妹啊…原來這麼久了…她沒有放棄我…\n\n<凜冬女王的嘴角揚起一抹淡淡的笑容，但很快就消失無蹤。她把目光轉移到你身上，眼神乘載著萬古的重量。>\n\n<name>，請聽我說。帶著我妹妹的眼淚，前往森林之心。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n星綻花蜜名望"}
MultiLanguageQuestData['tw'][63684] = {title = "兇野暗影獵犬", objective = "召喚你的兇野暗影獵犬並與其建立羈絆。", description = "<符文裝甲軀殼湧動著能量，似乎在掙扎想要脫離控制。\n\n放出你的兇野暗影獵犬，並與其建立羈絆。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n魂縛暗影獵犬"}
