MultiLanguageQuestData['tw'][64194] = {title = "戰爭原型兵器", objective = "在向風之巢使用亞特里奧斯原型擊敗凱拉克西斯。", description = "身為首席熔爐士，我會不辭勞苦地把事情做到盡善盡美！\n\n但是最巨大的百衛因為體型過於龐大，沒辦法帶去科西亞。我能夠解決這個問題。為你介紹亞特里奧斯，這是戰場巨像原型，也是琪瑞安的守禦先鋒！\n\n目前還需要進行測試，需要更多的測試，必須完美到能夠對抗力量強大的敵人。\n\n去吧，帶著亞特里奧斯去打倒厲害的淵喉野獸！按下全部的按鈕！", progress = nil, completion = "哈！這次的勝利簡直完美。亞特里奧斯和你都平安回來了。", rewards = "您會收到：\n\n棄誓志士法衣棄誓志士軟靴棄誓志士裹手棄誓志士兜帽棄誓志士護腿棄誓志士束帶棄誓志士裹帶棄誓志士披氅棄誓志士長袍古代靈魄容器學術侍者手鐲寶庫餘燼石\n                            顯示 6 更多                        明晰禱鐘古神的樣品罐那魯碎片殘破妖精設計圖複雜符文方塊死亡先鋒軍"}
MultiLanguageQuestData['tw'][64196] = {title = "寵物事宜", objective = "沿著艾薩拉之眼的海岸尋找並協助贊提尼和他的寵物。", description = "看來有一群寵物盜獵者在艾薩拉之眼為非作歹。我的供應經理飛行路線有經過那個地方！\n\n贊提尼和他的寵物史特林費洛、史畢迪四號，原本正準備帶一隻稀有的魚人寵物回來，外加幾隻其他的寵物和補給品。\n\n<name>，請找到贊提尼和他的寵物。幫幫他們。然後，我們再試著把那些寵物和補給品奪回來。", progress = nil, completion = "朋友，感謝你的救援。史特林費洛、史畢迪四號和我都感激萬分。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64202] = {title = "交給你", objective = "接受尼爾甘瑪的幫助。", description = "淵喉行者，你的力量…能與我並駕齊驅，與佐瓦爾撕裂我身軀之前的力量匹敵。\n\n這只不過是我的一小部分而已，但這樣就足夠了…\n\n請讓我協助你對抗佐瓦爾吧。如此一來，我就可以完成復仇大業了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n尼爾甘瑪的控制戒指"}
MultiLanguageQuestData['tw'][64203] = {title = "掃蕩海岸", objective = "跟史畢迪四號合作，在艾薩拉之眼的海岸旁收集寵物補給品。", description = "我當時正在運送補給品，身心俱疲，接著便遭受攻擊！對方只搶走寵物，補給品則是散落在這片海灘的各個地方。\n\n我不曉得對方有什麼樣的陰謀，我只知道我們必須搶救這些補給品。你和我很難低調行動…但如果是史畢迪四號的話…如果由他出馬，就不會驚動全部的海盜。他可以幫忙搶救補給品，史特林費洛則負責從空中偵察這片區域的動靜。\n\n史畢迪很喜歡你，跟他聊聊天，然後趁著這些悶燒的補給品還沒燒光之前趕快展開搶救行動。", progress = "我們總是需要更多的補給品。", completion = "我們把寵物補給品奪回來了。接下來要拿回那些寵物。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64210] = {title = "萬應寶盒", objective = "把萬應寶盒帶去給符刻師。", description = "啊，是淵喉行者。我就快撐不下去了，我會永遠化作這地方的一部分，而你卻還能繼續探索，屹立不搖！\n\n我抱著莫大的期望，這個寶盒能克服所有挑戰。可惜啊，我太高估自己的本事了。\n\n但我相信，我沒有高估你的能耐。拿走這個寶盒，證明你有資格擁有它吧。", progress = "啊，你回來了。", completion = "啊…這個裝置真是奇妙。把它安置在這個地方，應該能派上用場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64211] = {title = "黑暗通道", objective = "與珍娜交談，並見證托迦司戰役的結局。", description = "凡人，阻止佐瓦爾的計畫恐怕是遇到了麻煩。\n\n通往禁忌國度的通道被人打開…而且監禁者重新奪回了他很久以前所擁有的力量。\n\n我感應到你的盟友正在從統御聖所返回的路上。我必須要知道究竟發生了什麼事。", progress = nil, completion = "&lt;珍娜看起來很悲傷，但意志堅決。&gt;\n\n我們還有希望。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64212] = {title = "黑暗通道", objective = "與索爾交談，並見證托迦司戰役的結局。", description = "凡人，阻止佐瓦爾的計畫恐怕是遇到了麻煩。\n\n通往禁忌國度的通道被人打開…而且監禁者重新奪回了他很久以前所擁有的力量。\n\n我感應到你的盟友正在從統御聖所返回的路上。我必須要知道究竟發生了什麼事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64213] = {title = "希望的象徵", objective = "協助珍娜檢查安杜因的羅盤。", description = "在安杜因跟著閻獄之主穿過傳送門之前，他丟下了某樣東西。\n\n我並不認為這是閻獄之主有意為之。這肯定說明著，安杜因的靈魂還沒有完全受到操控！\n\n<珍娜打開手掌，裡頭有一個黃金羅盤。>\n\n這個是安杜因相當珍視的貼身之物。我能夠從中感覺到他的氣息。\n\n我們必須釐清他為什麼要把這個東西留給我們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64214] = {title = "希望的象徵", objective = "協助檢查安杜因的羅盤。", description = "在安杜因跟隨閻獄之主穿過傳送門之前，他丟下了某樣東西。\n\n我不確定那是什麼，總之珍娜撿起來了。說不定這是個跡象，代表安杜因還在對抗閻獄之主的力量！\n\n我們必須釐清這個東西是何物，還有年輕的國王為什麼要留下這個東西。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64215] = {title = "寵物巡邏兵", objective = "前往艾薩拉之眼的西岸，從紫帆海盜身上取得鑰匙後，釋放被關起來的寵物。", description = "在史畢迪四號收集補給品時，史特林費洛會負責偵察艾薩拉之眼的其他地方。\n\n沒想到西邊的地方有一大群海盜。被搶走的寵物肯定就在那裡。\n\n過去那邊拯救寵物吧。", progress = nil, completion = "&lt;name&gt;，你把那些寵物救出來了，做得好。\n\n但還是找不到戈嚕。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64216] = {title = "高塔知識", objective = "將萬應寶盒放置在托迦司。", description = "你必須用驕傲和回憶餵養這個盒子，才能解鎖它封存的力量。我曾經在其他界域見過這個盒子所蘊藏的魔咒，它們可以用來吸取或控制靈魂。這個…可憎的東西…把本該是救贖和榮耀的過程轉化為一個鎖。\n\n每當你在挑戰托迦司的樓層時，你的技巧、速度和效率都會轉化成高塔知識，成為這個盒子所吸收的養分。\n\n好好培育它，然後汲取它蘊含的力量。", progress = "<萬應寶盒充滿了能量。>", completion = "&lt;這個盒子飢渴的探尋你在托迦司的所有記憶，試圖汲取過往的功績來餵養自己。&gt;", rewards = "您會學到：\n\n萬應寶盒\n\n您還會收到：\n\n高塔知識"}
MultiLanguageQuestData['tw'][64218] = {title = "遠近都有危險", objective = "調查創始原野。", description = "朋友，有關閻獄之主的事情，我們目前能做的已經都做了。\n\n還有其他事情需要我們去處理。比方說我最近在東邊的區域有看見吞噬者裂隙！\n\n如果不阻止那些怪物，它們就會在這個地方製造混亂。\n\n<name>，你能協助我處理掉它們嗎？", progress = nil, completion = "裡面有人需要我們的幫助！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64219] = {title = "神秘的聲音", objective = "進入始源搖籃。", description = "這裡被破壞得真嚴重。吞噬者是不會善罷甘休的。\n\n希望那個發出聲音的個體沒有受很重的傷。\n\n這扇門沒辦法正常開啟。或許我們可以合力強行闖入！\n\n我不曉得門的後面有什麼，但對方需要我們的幫助。", progress = nil, completion = "我們慢了一步…但我們絕不能放棄希望。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64223] = {title = "事情的核心", objective = "在庇護城與克瑞斯長老交談", description = "她雖然倒下了，但似乎還活著。我們應該能做點什麼來幫助她。\n\n我們去問問看受啟迪者是否知道點什麼。我找個方法把她帶回去庇護城跟你碰面。", progress = nil, completion = "這真是一點幫助都沒有…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64224] = {title = "尋找未知", objective = "在庇護城打聽法琳的消息。", description = "如果長老不願意幫助我們，我們就只能另尋他人的協助。\n\n另一位受啟迪者法琳對於自主機很感興趣。\n\n他說自己跟同胞關係破裂。但庇護城肯定有人知道他的下落。\n\n四處打聽看看有沒有線索能夠引領我們找到法琳。我再去跟長老溝通，看能不能獲得一些情報。", progress = nil, completion = "長老拒絕透露法琳的資訊。\n\n希望你有找到線索。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64225] = {title = "尋找法琳", objective = "找到法琳。", description = "你有發現了嗎？真好運！能夠讓我看看信件的內容嗎？\n\n有個受啟迪者名叫瑟非斯，聽說法琳最後出現的地點位在死後世界熔爐的西側，跑去那邊尋找他了。\n\n我們應該從那邊開始搜索。", progress = nil, completion = "那些刺客的企圖不僅僅只是要取我的性命。他們還想要偷走我的研究成果！我絕不能讓自己的心血落入他們手中。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64226] = {title = "安全措施", objective = "使用感應同步裝置，在流亡者洞穴附近重新啟動10個被觸發的陷阱。", description = "看樣子我在洞窟附近偷偷設置的陷阱並沒有我預期中的那麼有用，畢竟你還是出現在我家中了。\n\n不過，他們還是能夠協助我排除許多不速之客。\n\n因為你把刺客引到這裡來的關係，我沒辦法自己去重新啟動那些陷阱。\n\n這件事情必須要由你來處理，我則負責待在這裡，保護我自己還有我辛苦研究的心血結晶。去使用我放在附近的感應同步裝置，它會告訴你有哪些陷阱需要重新啟動。", progress = nil, completion = "很好。這樣應該能夠暫時保護我們不被發現。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64227] = {title = "看不見的敵人", objective = "殺死流亡者洞穴附近的刺客。", description = "自從你開啟從奧睿博司過來的通道之後，已經有好幾個集團趁機入侵，跑過來想要搶走我的研究成果…並且置我於死地。他們知道我的研究對於整體大局的重要性。\n\n接下來勢必還會有更多的刺客出現，誰叫你要大張旗鼓地跑到我這裡來！\n\n我沒辦法對付那麼多刺客。你必須收拾你闖下的禍，並協助我保護我的研究秘密。\n\n幫我解決那些刺客吧。", progress = nil, completion = "好吧，看起來你還有兩把刷子。謝謝你。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64228] = {title = "輪到你說話了", objective = "跟法琳討論神諭者的事情。", description = "你真的帶了個神諭者過來！而且居然狀態完整！\n\n我從沒聽說過這些神聖的生命體居然會跟自主機以外的人對話。她能夠帶領我們了解澤瑞斯莫提斯的許多事物。\n\n我需要你把你知道的一切都告訴我！", progress = nil, completion = "真是驚人！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64230] = {title = "首創者的暗語", objective = "調查暗語控制臺。", description = "前方的道路尚未明朗，但我們總算是邁出了第一步。\n\n看樣子這個神聖造物比起我更喜歡你。\n\n既然它已經為你展開認知的大門，就繼續看看它還想要向你展示什麼吧。\n\n學習的結果應該能夠啟迪你的心智。", progress = nil, completion = "你感受不到嗎？你獲得的知識正在你的血液中流倘啊！\n\n沒想到居然是你解開了澤瑞斯莫提斯的秘密……\n\n我會仔細觀察你的。", rewards = "同理神諭披肩仲介者神諭披肩時光神諭披肩同理秘語肩墊仲介者秘語肩墊時光秘語肩墊同理神秘風帽仲介者神秘風帽時光神秘風帽同理數符胸甲仲介者數符胸甲時光數符胸甲您會學到：\n\n支援澤瑞斯莫提斯\n\n您還會收到：\n\n首創者的暗語"}
MultiLanguageQuestData['tw'][64237] = {title = "戈嚕與盜匪", objective = "找到寵物盜獵者的首領並展開戰鬥。", description = "除了戈嚕以外的寵物都回來了。<name>，我們必須幫布芮妮找回那隻寵物才行。\n\n史特林費洛找到了一個隱密的地方，寵物盜獵者的首領應該就躲在這裡。\n\n我們去把對方揪出來吧！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n戈嚕"}
MultiLanguageQuestData['tw'][64240] = {title = "琪瑞安的飛行", objective = "從空中協助玄秘寶庫的誓盟部隊。", description = "我們在玄秘寶庫的入口處遭遇到兇猛的敵軍！我方部隊需要增援。\n\n拜託了，率領我的晉升者同胞前去支援戰場上的盟友吧。\n\n地面上的戰鬥人員能夠收拾殘存的敵軍，但是他們需要護盾和治療。\n\n祝你好運！", progress = nil, completion = "我們不用每次都從空中發動攻擊！有的時候，透過治療的手段給予援助才是最佳的策略。\n\n謝謝你，朋友。", rewards = "您會收到：\n\n棄誓志士法衣棄誓志士軟靴棄誓志士裹手棄誓志士兜帽棄誓志士護腿棄誓志士束帶棄誓志士裹帶棄誓志士披氅棄誓志士長袍古代靈魄容器學術侍者手鐲寶庫餘燼石\n                            顯示 6 更多                        明晰禱鐘古神的樣品罐那魯碎片殘破妖精設計圖複雜符文方塊死亡先鋒軍"}
