MultiLanguageQuestData['tw'][64641] = {title = "神秘綠境", objective = "跟光藤一起造訪原翠荒野。", description = "上面那裡不斷散發出一股明亮的力量。我被它深深吸引，就好像飛蛾之於燈火！\n\n雖然我不知道那是什麼，但我很想過去探個究竟。你可以陪我一起去嗎？一定會很好玩的！", progress = nil, completion = "我們是機諾的寇爾群體。\n\n我們是來修復這片土地的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64642] = {title = "掃蕩廢墟", objective = "在原翠荒野殺死15隻生物。", description = "這個地方已經遭到遺棄太久了。植被到處肆意蔓生。\n\n我們必須進入繁盛鑄造場修好它。\n\n在那之前，我們得肅清這個區域。清除隨著時間經過已經逐漸扭曲的異常體。", progress = nil, completion = "這是個好的開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64643] = {title = "尋找解方", objective = "從原翠荒野的廢棄的自主機身上找到8個自主機內部零件。", description = "當初是繁盛鑄造場創造了這個區域。這裡負責維持自主機、生物和植物的存在。\n\n蔓生的植被也是這裡造成的。\n\n我們必須進入鑄造場修復這片土地。這個建築者如果能夠運作的話，應該可以帶領我們突破進去。\n\n這附近的許多自主機早在很久以前就已經失去動力了。使用它們體內還有用的零件吧。", progress = "有你的協助，我們一定能夠重振這個地方的昔日輝煌。", completion = "一定能成功的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64644] = {title = "永恆滋潤", objective = "協助光藤從原翠荒野的池塘中汲水。", description = "我對這個地方和棲息在這裡的生命沒有太多了解，但我對魔法倒是略有研究！我能夠感受到附近的水裡面蘊藏著古老的力量。\n\n說不定這能夠派上用場？\n\n我們去那座池塘看看吧！", progress = "<這個自主機一動不動。>", completion = "&lt;這個生物身上的小缺口看起來剛好適合倒入一些神奇的水。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64645] = {title = "真理之時", objective = "跟著寇爾機諾一起進入原翠荒野。", description = "建築者已經準備就緒。\n\n我們立刻就能動手，開啟繁盛鑄造場，重置這片土地，\n\n讓一切從頭來過。", progress = nil, completion = "我們去鑄造場吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64646] = {title = "飆升", objective = "在繁盛鑄造場啟動4個傳導器。", description = "我們必須要先恢復鑄造場的力量，才有辦法使用它。傳導器會引導能量，讓我們能夠使用。\n\n我們知道該如何使用這些傳導器。幫忙清出一條通路，這樣我們就能從頭開始了。", progress = nil, completion = "這些自主機不應該有這種行為的才對。\n\n它們好漂亮。奇特。新穎。\n\n在進一步採取行動之前，我們必須要深思熟慮。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64647] = {title = "奇怪的零件", objective = "從繁盛鑄造場的自主機身上收集3個蜿蜒種子。", description = "<奇怪的是，自主機體內的種子感覺明顯還是活的。\n\n每個自主機都是這樣嗎？>", progress = "這樣的情況相當反常。", completion = "&lt;寇爾希拉仔細查看自主機的零件，上面纏繞著活生生的藤蔓。&gt;\n\n這不可能。\n\n自主機的體內照理來說是沒有藤蔓的，但這些自主機的體內卻有。\n\n這真是…美麗。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64648] = {title = "自己插的秧", objective = "擊敗充能建築者。", description = "我們告訴建築者，說我們要使用鑄造場重置這片土地。\n\n我們必須阻止它，並保護新的自主機。", progress = nil, completion = "嗯，去認識體內蘊藏生長能量的新生物，這件事聽起來很適合我！\n\n我想先跟他們待在一起，看看我能幫上什麼忙……說不定還能順便學習一下他們的語言。\n\n朋友，謝謝你跟我一起冒險！", rewards = "肅清秘語面具新星秘語面具水晶秘語面具肅清神秘肩冑新星神秘肩冑水晶神秘肩冑肅清數符之冠新星數符之冠水晶數符之冠您會收到：\n\n"}
MultiLanguageQuestData['tw'][64650] = {title = "土狼靈魂", objective = "將土狼靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<土狼靈魂火爆而輕盈。你將來能任意化身為土狼之形態。>", progress = nil, completion = "啊，土狼。你現在可以任意使用這個型態。", rewards = nil}
MultiLanguageQuestData['tw'][64651] = {title = "眼鏡蛇靈魂", objective = "將眼鏡蛇靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<眼鏡蛇靈魂既貪婪又防衛心強。你將來能任意化身為眼鏡蛇之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][64654] = {title = "勇士：班恩‧霍爾", objective = "您會學到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n追隨者：班恩‧霍爾"}
MultiLanguageQuestData['tw'][64706] = {title = "適當激勵", objective = "將6個受激勵的自主機送回去給法琳。", description = "凡人，這片土地上到處都有靜止不動的巨人，但我認為我們應該能夠讓它們甦醒。\n\n這種時候，躲藏在沙漠的小型自主機就可以派上用場。使用我的激勵裝置號召那些自主機過來。如果聚集到足夠的數量，就能利用它們的能量讓這些倒下的巨人重新甦醒，為我軍而戰。\n\n盡可能多帶一點自主機回來，我們就能善加利用！", progress = nil, completion = "做得好，凡人！你的努力付出相信很快就會有成果了。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64709] = {title = "穿越時光的魔化之路", objective = "完成5次時光漫遊地城冒險。", description = "腐化之星照耀大地，燒灼土壤、危害世間。這顆星辰會背叛那些追尋光明之人，其閃耀的紅光不會揭示視界，而是蒙蔽視野。\n\n在它的影響下，新的道路可能通往遠方，甚至通往遙遠的時間。沒有賢者能真正明瞭這個星象，但是好運會眷顧果敢之人。", progress = nil, completion = "啊，&lt;name&gt;，你回來了。你的身上散發著其他世界的氣味。", rewards = "您會收到：\n\n聖所寶箱聖塚寶藏箱"}
MultiLanguageQuestData['tw'][64710] = {title = "低語魔焰水晶", objective = "把低語魔焰水晶帶去給破碎群島上方的達拉然的阿力多米。", description = "水晶閃爍著詭異的魔化綠光。拿在手上時，你聽到惡魔深邃的回音。文字混亂難辨，但是有個字非常清楚，而且不斷重複：達拉然。\n\n或許漂浮在破碎群島上方城市中的某個人，可以告訴你更多這個水晶的事情。", progress = nil, completion = "我會把這東西拉回它該去的地方。&lt;name&gt;，謝謝你帶來給我。", rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][64713] = {title = "收拾碎片", objective = "收集30個球體碎片。", description = "球體能夠協助我們替熔爐打造地景。球體裡面的魔法會引來吞噬者。它們為了得到球體蘊藏的力量，會不惜撕裂金屬外殼。我們必須收集球體的殘骸。\n\n在球體附近尋找碎片。把它們帶來給我們。", progress = "你找到碎片了嗎？我們需要更多碎片。", completion = "這樣足夠我修好一個小型球體了，應該行得通。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64717] = {title = "造物材料", objective = "收集10個幻象碎片和300個小型神秘粒子。", description = "散落在澤瑞斯莫提斯各處的大型金屬球體是已經退役的熔爐，是在造物過程中廢棄的。\n\n位於來世熔爐附近的球體蘊藏著微量的獨特材料，只有那個地方有。\n\n我改造了核心偵測器，讓它能夠採集那些材料。在我指定的熔爐附近使用。最巨大的創先者熔爐有比較高的機會找到稀有的幻象粒子。", progress = "你找到我們所需的東西了嗎？", completion = "我立刻就去進行。這些材料能夠協助瑟祖拉和自主機抵禦統御魔法的影響。", rewards = "您會收到：\n\n靈魄網砂蝕聖物神諭罩衫神諭軟靴神諭長手套神諭窄褲神諭披肩神諭束帶神諭護腕秘語足靴秘語面具秘語長褲\n                            顯示 28 更多                        秘語肩墊秘語繫腰秘語腕環神秘鎖甲護胸神秘護足神秘風帽神秘腿甲神秘肩冑神秘腰鍊神秘束腕數符胸甲數符脛甲數符手甲數符之冠數符護脛數符肩甲數符束腰數符腕輪異常古老的披風暗語蝕刻戒指暗語蝕刻指環暗語蝕刻頸環暗語蝕刻垂飾空無法刃首創者的暗語首創者的暗語首創者的暗語首創者的暗語"}
MultiLanguageQuestData['tw'][64718] = {title = "通往勝利的鑰匙", objective = "從牢裡拯救6個自主機占卜者。", description = "這首歌…尚未完整。需要和諧的旋律。尋找占卜者。令其完成循環的過程。\n\n淵誓者手上持有鑰匙。取回鑰匙，讓占卜者重獲自由。", progress = nil, completion = "和聲開始匯聚，再過不久，我們的聲音就能結合。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64720] = {title = "披荊斬棘", objective = "殺死神諭者佐克斯和神諭者弗拉克希。", description = "淵喉行者！我的斥候回報，淵誓者控制了兩個自主機神諭者協助他們作戰。如果放任不管，這些神諭者就會預測我們的戰術和我們的最終目標。\n\n我們必須趕在這兩個神諭者進入眠地之前將其消滅。沒有那兩個神諭者，淵誓者部隊就無從得知我們在做什麼，直到我們的計畫大功告成。\n\n帶著艾曼妮跟你一起行動吧，她渴望參加戰鬥。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64722] = {title = "敲敲死亡之門", objective = "騎乘卡巴托，前往無盡沙海擊敗淵誓者部隊，並開啟通往永恆者眠地的道路。", description = "凡人，時機已然成熟，你所召集的部隊應該能夠突破淵誓者的陣線並順利抵達眠地。不過，要攻進去還是需要相當程度的努力。淵誓者把入口給擋起來了。\n\n卡巴托會載你進入戰場。消滅淵誓者，並摧毀負責提供屏障能量的裝置。", progress = nil, completion = "首創者在上…我從沒想過自己這輩子能有機會親眼看見這個地方。", rewards = "您會收到：\n\n聖歌裹手斷音之握聖歌護手簧風琴護手"}
MultiLanguageQuestData['tw'][64723] = {title = "恢復計畫", objective = "與瑟祖拉交談。", description = "失去審斷者之後，暗影之境就沒辦法貫徹使命，靈魂也失去方向湧入淵喉。\n\n誠如瑟祖拉所提到的，澤瑞斯莫提斯本應打造新的個體取代審斷者的位置。但恐怕閻獄之主的爪牙對這片土地所帶來的傷害，阻礙了這件事情順利進行。\n\n是時候換我們出動了，我們要讓暗影之境恢復秩序與和諧！去找瑟祖拉交談，看看我們該從哪裡開始著手。", progress = nil, completion = "如果我們提出請求的話，誓盟一定會派出援軍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64725] = {title = "不可饒恕的入侵者", objective = "消滅6個被統御的自主機和3個黑暗先知腐化者。", description = "黑暗在這些廳室中蔓延，不斷散播著失諧。淵誓者從空氣中吸取生命，卻只加諸痛苦於他人之上。不該如此。\n\n如果要恢復歌曲，我們就需要沉靜。我們必須消滅淵誓者。", progress = nil, completion = "沉靜的黃金時刻，是造物能夠開展的空間。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][64726] = {title = "萬物的規律", objective = "使用$13oa個蓄納之球封住破口。", description = "遠古靈魂的精華受到影響而發生轉變，從每個房間中滲透而出。我們必須重振廳室，重新引導靈魂的流向。\n\n球體是關鍵。封住破口，恢復靈魂的流動，這樣才能將靈魂導向容器。", progress = nil, completion = "屏住的呼吸，象徵著期待的情緒。再過不久，靈魂就會融合，造物的歌曲也將開始演奏。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][64727] = {title = "無限之圓", objective = "護送瑟祖拉前往永恆者眠地的中心。", description = "造物在呼喚，你聽見了嗎？但黑暗還是潛伏四周，汙染著遠古的旋律。\n\n我們必須恢復和平，才能開創新世界。行者必須努力守護。\n\n還有很多事要做，帶路吧。", progress = nil, completion = "我們的聲音在揮之不去的黑暗中遭到埋沒。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64728] = {title = "遺忘的故人", objective = "完成儀式。", description = "時候到了，這首歌曲將會造就新的生命。等你準備好之後就來找我。", progress = nil, completion = "失諧久久不能散去。我們需要純淨之音。讓循環的過程重新開始。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][64729] = {title = "數輩子的思考時間", objective = "回到流亡者洞穴。", description = "歌曲已完成，和諧已恢復。但澤瑞斯莫提斯仍迴盪著不和諧之音。\n\n牆外仍有失諧音殘餘。我們必須在被找到前離開這裡。\n\n去找法琳說話…他能開啟通道。", progress = nil, completion = "我簡直不敢相信我們成就的大事…這真的是值得紀念的一天。朋友，沒有你的幫忙我們不可能成功。", rewards = "同理神諭披肩仲介者神諭披肩時光神諭披肩同理秘語肩墊仲介者秘語肩墊時光秘語肩墊同理神秘風帽仲介者神秘風帽時光神秘風帽同理數符胸甲仲介者數符胸甲時光數符胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][64730] = {title = "轉捩點", objective = "檢查容器和自主機占卜者。", description = "停頓，暫停呼吸。旋律餘音繞樑。循環的過程等待著聲音的出現。\n\n<你不確定瑟祖拉的意思，說不定你應該要試著再次舉行儀式，從容器和占卜者開始。>", progress = nil, completion = "我很不想說出口，但是…朋友，我們好像失敗了。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][64731] = {title = "為了眾靈魂", objective = "找個方法創造出新的審斷者。", description = "少了審斷者幫忙阻止靈魂流向淵喉，暗影之境將永遠沒有徹底復原的一天。\n\n結局不能是如此。你一定能夠想出辦法來的，對吧？", progress = nil, completion = "新的聲音加入合唱…循環永續不止。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64733] = {title = "來自遠方的協助", objective = "與受啟迪者、汎希爾、死靈領主和暗夜妖精的代表交談。", description = "我們需要把所有的誓盟集結在一起，要不然絕無可能攻破淵誓者的部隊。\n\n我會去通知琪瑞安，你和佩拉苟斯負責去找其他誓盟。在出發之前，請先去問問法琳，看有沒有機會讓受啟迪者也一起加入戰局。", progress = nil, completion = "有了誓盟部隊的力量加持以及自主機的協助，我們應該能夠順利抵達眠地！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64739] = {title = "佐瓦爾之握", objective = "跟隨『流亡者』哈諾雅，並傾聽對方訴說自己的故事。", description = "我記得這個金屬。我在觸碰到淵喉魔法的時候見過它。就在我被斬成兩半的時候…\n\n我帶你去看看當時的事發地點。跟我來。我來告訴你發生在我身上的故事。", progress = nil, completion = "這比我想像得更糟。糟糕太多了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64741] = {title = "安全檢查", objective = "調查並強化庇護城周圍的護盾導管。", description = "我無法理解，他們可是我的同胞啊！貪婪集團和淵喉的爪牙都已經來到跟前了，他們怎麼還能如此冷漠？\n\n而且他們的防護技術已經過時，沒辦法把危險拒於門外。就算我無法說服他們離開，至少我必須確保他們能安全地繼續待著。\n\n我不想再次失去朋友。\n\n在護盾周圍應該會有四個隱藏的導體。拿上這個工具。這可以協助你檢視並強化那些裝置。", progress = nil, completion = "我就知道。希商集團在偷偷破壞庇護城的防禦機制。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64742] = {title = "犯罪證據", objective = "找到希商集團來過的線索。", description = "看樣子護盾遭到人為破壞。不出所料，殘暴無情的希商集團果然是最先企圖要剝削這片土地的人。\n\n他們的貪婪導致原本就危急的局勢更加惡化。我們必須阻止他們。我們一起四處搜索一下，看能不能找到他們的足跡。", progress = nil, completion = "希商集團就在附近。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64743] = {title = "是希商集團幹的好事嗎？", objective = "收集10張可疑的紙張。", description = "雖然看不見對方，但我很確定這裡就是希商集團建立據點的地方。\n\n希商集團之所以會來到澤瑞斯莫提斯的這個地方，肯定是受到什麼東西所吸引。我們必須釐清其中的原因，才有辦法保護我們的朋友。\n\n他們的隱形科技並沒有辦法妥善隱藏他們的補給品。去看看你能夠透過他們的私人物品發現什麼情報吧。", progress = "我們必須釐清希商集團來這個地方的企圖。", completion = "哦？他們自以為能夠用暗號來掩蓋自己的陰謀嗎？朋友，稍等，這應該一下子就能處理好了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64744] = {title = "揪出隱身的仲介者", objective = "在庇護城外面殺死12個希商集團密探。", description = "你有沒有感覺到這裡的氣氛有異。希商集團雖然躲了起來，但他們就在附近。\n\n幸運的是，我很熟悉他們用來隱身的裝置。來，你拿著這個東西。把它放在地面上，它就能夠幫你找到隱藏在附近的敵人…但只是暫時的。\n\n阻止他們，就算必須得取對方性命也沒關係。", progress = nil, completion = "如果有選擇，我真不想置他們於死地，但我們必須保護庇護城。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64745] = {title = "無私的守護", objective = "在索引編目取回遭竊的文物，並將其歸還至原本的地方。", description = "這裡曾經有很多自主機，它們會唱歌、打造許多東西、貫徹首創者賦予的使命。但是來自淵喉的入侵者把它們全部殺光了。\n\n最後陣亡的自主機原本在附近的建築物保護某個重要的東西。\n\n我親眼目睹其中一個可惡的淵誓者偷走放在門邊的裝置。長老說我們不應該隨意觸碰文物，但如果是為了取回被偷走的文物，應該可以破例吧？", progress = nil, completion = "這個自主機還活著！但是它很虛弱。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64758] = {title = "跟隨領袖", objective = "調查沉眠寶庫。", description = "我們剛剛抵達的時候，封閉了通往沉眠寶庫的大門。那是個聖所、是此地所有珍貴造物的搖籃。我們不應該去干涉沉睡在裡頭的力量。\n\n如果說希商集團的領袖在我們分神欣賞此地之美的時候趁機突破護盾，那麼只怕他們已經造成了不小的損害。\n\n動作快！我們必須前往沉眠寶庫，並確保那個地方的安全。", progress = nil, completion = "不！那個蠢貨對控制臺幹了什麼好事？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64759] = {title = "廢物再利用", objective = "在索引編目附近從6個耗盡的僕從身上獲得雕紋。", description = "這個自主機一直偷偷藏在這裡！恐怕它還是不願意接受我們的協助。\n\n我不確定這樣做是否恰當，但如果能夠讓這個僕從在這座設施協助你，它說不定會聽話一點。\n\n如果你有辦法的話，可以去找外面類似的自主機，並複製它們身上的雕紋。受到淵喉影響的自主機會遭到汙染，但我從高處看下去，沙地那邊有幾個停止動作的自主機，他們身上的雕紋似乎還完好無損。", progress = nil, completion = "希望此舉能夠鼓勵這邊的朋友把我們視作盟友。願首創者原諒我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64760] = {title = "技術障礙", objective = "在沉眠寶庫按下控制臺的按鈕。", description = "這個控制臺故障了！我們必須修好它！\n\n說不定這些按鈕能有什麼功用？", progress = nil, completion = "淵喉行者，謝謝你的協助。\n\n我必須回去奧睿博司。我會告訴亞商集團的人，我們的朋友其實並沒有消失，而是受到了啟迪。", rewards = "原基袋熊符記原狼符記您能選擇下列奬勵中的一個：\n\n原鷹符記\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][64761] = {title = "核心之力", objective = "在索引編目吸取死去野生動物的能量，藉此替耗竭的自主機核心充能。", description = "它好可憐。\n\n神聖的事物本不應該受到打擾，但是…如果我們幫助它存活，長老應該不會怪罪於我們吧？我們這是在保護它，而不是打擾它\n\n…應該吧。\n\n我們可以恢復它的能量。使用這個耗竭的核心作為導體。說不定附近沙地體型較大的靈魄體身上擁有足夠的能量可以為它提供動力。", progress = nil, completion = "這個孤單的自主機將能夠再次振作起來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64762] = {title = "適者復活", objective = "在索引編目復活隱藏的僕從。", description = "核心蘊藏著滿滿的能量！\n\n使用充能的核心重新啟動自主機。希望它不會再把我們視為威脅。\n\n請務必小心。首創者的力量超過我們所能控制的範疇。", progress = nil, completion = "援軍來了。我們可以繼續進行恢復作業了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64763] = {title = "維護模式", objective = "在索引編目調和4個終端機。", description = "設計者傳達了如下指示：\n\n保護自身安全。\n\n在危險消失之後，恢復原靈體存放庫。\n\n凡人對暗語有所了解。凡人會協助我們處理工作。\n\n需要調和能量終端機。每個終端機都需要索引。入侵者竊走了必要的法典。\n\n去吧。", progress = nil, completion = "任務正式展開。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64766] = {title = "申請存取權限", objective = "前往轉化廳找到原型設計者，並取得修復矩陣。", description = "只有設計者擁有能夠完成恢復作業的修復矩陣。設計者會恢復原靈體存放庫。\n\n凡人會進入轉化廳，並把最新進展告知設計者。設計者會恢復存放庫。\n\n我們就快要能夠圓滿達成任務了。", progress = "設計者會協助我們的。", completion = "我們需要修復矩陣。設計者不在這裡。這代表設計者失蹤了。\n\n但即便如此，我們還是必須恢復存放庫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64767] = {title = "最終之曲", objective = "跟著科達並保護原靈體存放庫。", description = "侍從並不具備恢復存放庫所需的力量。但即便如此，這個任務還是必須完成。\n\n凡人必須跟緊一點，這樣才能保護恢復的過程。\n\n來吧。", progress = nil, completion = "我應該要聽長老的話的！這一切都是我的錯！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64768] = {title = "光鍊的文物追尋", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][64771] = {title = "受啟迪者的遠征", objective = "與庇護城各處的受啟迪者交談。", description = "你好，我的朋友！\n\n亞商集團很久以前曾經派出遠征隊前來搜索這個區域，但卻失蹤了。我來到澤瑞斯莫提斯，就是希望能夠拯救走散的集團成員不受淵喉威脅的荼毒。\n\n而我終於找到我的老朋友了！但是，她卻不願意回到安全的地方。\n\n說不定其他人能被說服。你能夠幫我試試看嗎？", progress = nil, completion = "如果說服不了他們，那就只能保護他們了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64772] = {title = "破碎的群體", objective = "找到倖存的機諾，並說服它們到洞穴外面集合。", description = "歐利亞群體的機諾在這裡工作。我們負責打造…\n\n<機諾停頓了片刻。>\n\n它們…負責替熔爐打造新的土地和生物。\n\n雖然遭到吞噬者攻擊，但一部分的機諾還是存活了下來。你必須找到它們。叫它們到北側的洞穴外面集合。我會負責清出一條通路。\n\n不要告訴它們是我派你過去的。它們並不想要見到我。", progress = nil, completion = "謝謝你協助找到倖存者！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64773] = {title = "機諾的不被吃掉指南", objective = "在形態平台削減吞噬者的數量。", description = "吞噬者對我們發動攻擊。它們擊潰了守護者。它們到現在還在尋找食物。\n\n大家都有危險。必須削減吞噬者的數量。\n\n只有這樣才不會被吃掉。", progress = nil, completion = "只要吞噬者的數量變少，我們被吃掉的機率也會降低。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64775] = {title = "不一樣的淵喉生物", objective = "殺死解滅者，並從它身上尋找線索。", description = "洞穴裡面有一隻吞噬者。那個吞噬者能夠生成裂隙。在澤瑞斯莫提斯，這理論上不可能發生才對。\n\n進入洞穴並消滅吞噬者。尋找線索。釐清它是怎麼創造裂隙的。\n\n多加小心。這個吞噬者跟其他的不同。它吸收了首創者的魔法。以前沒發生過。記得提高警覺。\n\n我會留在這裡保護機諾。", progress = "你順利消滅吞噬者了嗎？有沒有找到什麼線索？", completion = "新型的吞噬者。這很棘手。希望它們的數量就只有這些。\n\n至於神祕的金屬…我以前有見過。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64778] = {title = "裂隙偵察", objective = "分析6個扭曲裂隙。", description = "吞噬者是個麻煩。裂隙則是更大的麻煩。\n\n裂隙會跑出更多吞噬者。我們必須關閉裂隙。因此首先需要情報。\n\n拿上漸強裝置。使用它來分析裂隙。把情報帶回來給我們。", progress = nil, completion = "這些情報有用。能告訴我們如何關閉裂隙。裂隙的數量減少，吞噬者的數量也會減少。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64779] = {title = "一斤鮮肉", objective = "從佐瓦爾之握的吞噬者身上收集30個扭曲肉塊。", description = "自主機協助我們排除威脅。但沒有自主機了。我們只能保護自己。我們需要魔法。\n\n吞噬者吃了球體的魔法。現在它們扭曲變形。但也充滿魔法。\n\n把吞噬者的血肉帶回來。我們會從中抽取魔法。這樣才能擊敗吞噬者。", progress = "吞噬者不該吞食這種魔法。", completion = "這是&lt;name&gt;幫忙收集的肉塊嗎？\n\n\n\n也就只能這樣了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64780] = {title = "沒有裂片，就沒有問題", objective = "拿起4個淵鋼裂片，並把裂片丟到懸崖底下。", description = "澤瑞斯莫提斯是神聖的。裂隙不應該出現。是被創造的。\n\n你找到的金屬蘊藏淵喉魔法。吞噬者用來創造裂隙。就是這樣突破我們的防護的。\n\n淵鋼裂片四散在區域四處。拿上裂片。把它們丟到懸崖下。不能讓吞噬者繼續使用來創造裂隙。", progress = nil, completion = "除掉淵鋼可以防止裂隙。作用有限，但幫得上忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64783] = {title = "勁爆暗月熱舞", objective = "參加跳舞競賽以獲得綬章。", description = "西蒙說：「你準備好跳舞了嗎？」<class>，過來展現你的舞步吧。\n\n規則很簡單。你的對手會使出一連串的華麗舞步，而你則必須跟上對方。\n\n收集足夠的綬章，然後回來找西蒙我。對手越強，你能夠獲得的綬章數量就越多。\n\n西蒙說：「你準備好面對挑戰了嗎？」您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n暗月遊戲獎"}
MultiLanguageQuestData['tw'][64784] = {title = "9.0 Rated PvP Incentive - Shadowlands Season 2 Exclusive Mount", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][64785] = {title = "蔓生故事", objective = "檢查大型地質元素和12個地質元素，以獲得研究數據。", description = "自從我們來到這裡之後，原翠荒野一直都還是個未解之謎。這個區域的蓊鬱植被肆意生長蔓延，生物則是像無頭蒼蠅一樣到處亂竄。\n\n我們說不定能夠從這些生物身上取得寶貴的研究數據。\n\n使用拘捕陷阱制伏元素生物。成功制伏之後，在從對方身上採集研究數據。", progress = nil, completion = "這些資訊能夠派上用場，但那些廢墟依舊是個未解之謎！", rewards = "您會收到：\n\n靈魄網砂蝕聖物神諭罩衫神諭兜帽神諭窄褲神諭護腕秘語外衣秘語之握秘語面具秘語繫腰神秘護手神秘風帽\n                            顯示 14 更多                        神秘腰鍊數符手甲數符之冠數符束腰異常古老的披風暗語蝕刻戒指暗語蝕刻指環暗語蝕刻頸環暗語蝕刻垂飾狂想斬斧首創者的暗語首創者的暗語首創者的暗語首創者的暗語"}
MultiLanguageQuestData['tw'][64794] = {title = "知己知彼、百戰不殆", objective = "在地層供應區附近與珊蒂斯碰面。", description = "<name>，你應該跟珊蒂斯一起從東側潛入淵誓者的部隊之中。你們兩個發現的資訊，能夠協助我們規劃下一步的行動。\n\n保重。我們不曉得你們到時候會遇到什麼狀況。", progress = nil, completion = "你來了。\n\n敵人在此處的動靜很詭異。感覺就好像對方真正的大軍其實不在這裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64796] = {title = "掃蕩沙地", objective = "跟著珊蒂斯‧羽月一起偵察地層供應區。", description = "我到目前為止的偵查，幾乎沒有得到關於敵人的有用資訊。我們必須更靠近一點看看。\n\n只要你一聲令下，我就能讓我們兩個隱形。但是請不要靠近驚懼領主，他們的視覺很敏銳，就連隱藏行蹤的獵人也逃不過他們的法眼。", progress = nil, completion = "我們發現對方的下一個目標了。我們應該盡快回到盟友身邊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64797] = {title = "秩序與混亂", objective = "在地土供應區與達瑞安‧莫格萊尼交談。", description = "那些方尖碑一定是佐瓦爾陰謀詭計的關鍵。雖然我們還不完全理解其用途，但我認為阻止淵誓者使用方尖碑對我們一定有好處。\n\n我會把這個訊息傳達給大領主伯瓦爾。你們去跟達瑞安‧莫格萊尼說。他得針對這個消息規劃防禦工事。", progress = nil, completion = "雖然敵人到目前為止還無法突破我們的防禦陣線，但我擔心如果沒有你的協助，我們打不贏這場戰鬥。", rewards = "聖歌護肩簧風琴肩鎧斷音披肩聖歌襯肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][64798] = {title = "我們克服的困難", objective = "擊敗淵縛巨怪，並將能量注入最後一塊裂片裡面。", description = "我現在理解了。接觸過統御之力的所有人，都從中獲得了成長。不論是高貴的情操還是復仇的渴望，都使我們獲得了抵抗的力量。\n\n我經歷過許多波折，但重要的是我必須意識到自己仍然在這裡奮鬥。\n\n如果有人願意跟希瓦娜斯並肩作戰，我相信他們也會願意跟我站在同一陣線。\n\n我準備好再試一次了。這次，我不論遇到什麼樣的困難都會想辦法克服。", progress = nil, completion = "我們從受到統御之力控制的過往經驗中所汲取出來的力量，已經注入到所有的裂片當中。\n\n這樣的過程對我們來說都很艱辛。但是我們攜手同心一起辦到了，我為大家感到驕傲。\n\n至於剩下的部分，我們的未來就全部掌握在統御者手中了。", rewards = "您會收到：\n\n聖歌兜帽斷音頭盔聖歌護脛簧風琴頭盔"}
MultiLanguageQuestData['tw'][64799] = {title = "破碎王冠", objective = "在幾何洞窟與安杜因‧烏瑞恩交談。", description = "我們的朋友已經從首創者聖塚那邊回來，並且帶著一位我們熟識的朋友。\n\n安杜因…他經歷過那麼可怕的事情。\n\n雖然這既艱難又痛苦，但我們還是必須釐清他所知道的情報。閻獄之主阻擋了我們進入聖塚的路，如果盲目追上去可能會淪為統御之力的奴僕。\n\n他是我們最大的希望。", progress = nil, completion = "他經歷過很大的痛苦…\n\n這樣的傷痛很難弭平。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64800] = {title = "走投無路的選擇", objective = "聽取計畫。", description = "佐瓦爾阻止了我們的追擊。如果要擊敗他，我們就得先找方法抵禦統御之力。\n\n而如果要抵禦統御之力，我們就必須先理解它的運作方式。\n\n統御之力源自於瑪卓薩斯的統御者，他應該還能告訴我們更多的情報。\n\n我請泰莉亞帶了一個統御之盔的碎片到澤瑞斯莫提斯。要是我再次戴上這個沉重的負擔，光是想像後果都令我感到害怕…\n\n我們來討論接下來該怎麼辦吧。", progress = nil, completion = "我跟泰莉亞一樣不喜歡這個做法，但我們必須要有辦法安全地運用統御之力，這樣才有辦法駕馭它。\n\n第一步的計畫就是要確認統御之盔還能正常運作、還能對我們起作用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64801] = {title = "厄魯長老", objective = "在詞彙林地外面找到厄魯長老。", description = "自從我們取得受啟迪者的信任以來，我從他們身上了解到許多有關澤瑞斯莫提斯的事情。\n\n他們知道的知識遠比願意分享的多，但他們卻很少實際運用這樣的知識。或許他們只願觀察的事項，我們能加以利用採取行動。\n\n在某個名為詞彙林地的偏僻地帶，有個名叫厄魯的長老。她說不定能夠告訴我們可以如何運用首創者的語言。\n\n去找到她，看看她願不願意協助我們。", progress = nil, completion = "怎麼回事？你想要知道這邊有沒有什麼東西能夠協助你抵抗淵誓者的魔法嗎？\n\n陌生人，你今天很走運。我碰巧知道這個地方就是一座圖書館。而你能夠在圖書館找到你想要的知識。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64802] = {title = "迎向黑暗", objective = "對達瑞安‧莫格萊尼使用破損的統御之盔，測試它的力量", description = "我起初創造統御之力，是為了懲罰佐瓦爾。\n\n是我的憤怒造就了這股力量，如今我們卻要為我當時的傲慢付出代價。就連永恆者偶爾也會犯錯。\n\n但我們還有一絲希望。\n\n拿著破損的統御之盔，對你們自己人使用來測試它的力量。如果破損的統御之盔依舊擁有足夠的力量，就能夠拿到澤瑞斯莫提斯進行進一步測試。", progress = nil, completion = "就連曾經抵禦過統御之力的人，也並非完全免疫。\n\n但是在過往的這份經驗當中，說不定隱含著什麼有用的情報。\n\n我會好好思考一下。\n\n現階段，你就先專心處理澤瑞斯莫提斯的生物吧。去看看要怎麼做，才能強化他們對於統御之力的抵抗能力。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64803] = {title = "牛刀小試", objective = "對澤瑞斯莫提斯的生物使用破損的統御之盔，測試它的力量。", description = "早在我創造統御之力以前，澤瑞斯莫提斯的生物就已經存在。\n\n我們曾經看過佐瓦爾的爪牙對這些生物所帶來的影響，但我想其中還有許多我們尚未了解的地方。\n\n對澤瑞斯莫提斯的生物使用統御之盔的力量，看看能不能從中看出什麼自然抵抗力的端倪。", progress = nil, completion = "你是說比較高階的生物，對於統御之力的抵抗能力也比較強嗎？\n\n那是當然的，這點我應該事先提醒你才對。重點就在於語言啊！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64804] = {title = "神秘條目", objective = "記住詞彙林地裡面的詞語。", description = "這個區域是個蘊藏著無數文字的存放庫。嗯？你說文字的含意是什麼？我毫無頭緒！\n\n我致力於替這些文字編列條目，加以管理。尤其現在還有入侵者在破壞澤瑞斯莫提斯的平衡，這份職責更顯得重要！我們必須努力保存我們找到的知識。\n\n你也能幫得上忙。進入林地，記住裡面的詞語，然後到洞窟那邊跟我回合。裡面的某樣東西說不定能夠協助你進一步測試那頂頭盔的威力。", progress = nil, completion = "這個地方真是不可思議。\n\n我願意花費我所擁有的所有時間待在這裡。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64805] = {title = "不科學的方法", objective = "對啟動的詞彙圖書管理員使用破損的頭盔，並觀察測試結果。", description = "首創者的語言並不像大多數語言那樣是靜態的。這種語言會不斷進化。\n\n比方說哨兵那種生物，就顯然比一般的原雞還要來得高階許多。它們因為擁有較為複雜的思緒，因此天生就比較有辦法抵禦外界的魔法，不被干擾心智。\n\n這可不是我說的就算而已。我們可以實際測試看看！\n\n洞窟裡面有位圖書管理員。把你記下來的詞語帶過去，然後灌注到管理員體內。接著再拿出你的頭盔進行測試。", progress = nil, completion = "你看吧！統御之力要全面凌駕圖書管理員的意志並沒有那麼容易。\n\n雖然說對方最後還是被控制了，但我想這場測試的結果對你很有用。\n\n別擔心，會有另一個自主機取代它的位置。永遠都必須要有一個圖書管理員。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64806] = {title = "記憶所在之處", objective = "在昇靈堡的初省之間與大領主伯瓦爾碰面。", description = "我想我知道昇靈堡那邊的人會要求我們做什麼。這次的行動難度不低。\n\n在破損頭盔的協助下，我們努力想要抵抗統御之力的計畫已經成功邁出第一步。但我們之中也有人曾經因為這頂頭盔而承受苦難，並一度艱難地挺了過來。\n\n就某種角度來說，這頂頭盔跟我們所有人都息息相關。\n\n過往的經驗當中勢必有某些事物，能夠協助我們脫離佐瓦爾的掌控。\n\n我們去昇靈堡的初省之間吧。", progress = nil, completion = "很好，你來了。\n\n我們集結了過去曾經被統御之力控制的人。經歷的時間早晚不一。\n\n大家都挺了過來。雖然有些傷痛難以弭平，但至少我們還在這裡。我們必須秉持著這種信念。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64807] = {title = "我們想要遺忘的傷痛", objective = "協助儀式的進行，並將能量灌注到統御裂片裡面。", description = "創先者的語言能夠派上用場，不過其實還有另一個東西可以協助我們擺脫統御之力的控制。\n\n那就是不屈不撓的意志。\n\n曾經受到統御之力摧殘並一路挺過來的人，已經具備這樣的抵抗能力，我們會將這種抵抗力注入每塊裂片裡面。\n\n統御者親自向我保證過，這麼做行得通。在沒有其他辦法的情況下，我們也只有這麼做。\n\n我相信受這樣的苦會是值得的。", progress = nil, completion = "我覺得…身體變輕了。但我還是忘不了過去所發生的事情，以及等待我去完成的使命。\n\n希望泰莉亞能夠記得她所見過的景象…記得我現在的樣子。希望我在她心目中不是以前那個孤單封閉的人，而是為了造福大家願意挺身而出的英雄。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64808] = {title = "我們之所以強大的原因", objective = "協助儀式的進行，並將能量灌注到統御裂片裡面。", description = "我跟這個地方相見恨晚。在這裡，人們能夠驅散恐怖的黑暗、面對痛苦的回憶並放下…\n\n我願意不惜一切代價幫助大家擊敗佐瓦爾。\n\n我們只能這麼做。", progress = nil, completion = "我想我理解了。\n\n&lt;安杜因振作起來。&gt;\n\n我準備好再試一次了。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64809] = {title = "等式的一半", objective = "前往廢棄瞰臺。", description = "統御者針對首創者語言的理論受到驗證。\n\n不過，這樣還是不夠。\n\n在統御者擬定最終計畫的同時，我們必須深入無盡沙海，尋找這股力量的碎片，並將力量灌注到頭盔裡面。\n\n我、達瑞安和泰莉亞會在那邊跟你會合，協助你對抗淵誓者。", progress = nil, completion = "雖然敵人很強大，但我們擁有武裝和破損頭盔的力量，還是有不少勝算。\n\n我必須承認，我的女兒也在戰場上奮戰，讓我變得額外謹慎小心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64810] = {title = "壓制並摧毀", objective = "在無盡沙海殺死淵誓者。", description = "我們所尋找的東西，就在無盡沙海的寶庫裡面。我們需要力量和夠多的幫手，才有辦法拿到我們要找的東西。\n\n只要攜手同心，我們就能打敗淵誓者。\n\n我很期待主動出擊對付他們。\n\n你要記住，敵人對於統御之盔的破損裂片沒有抵抗能力。", progress = nil, completion = "做得好。\n\n但願這是這頂頭盔最後一次被作為武器使用。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64811] = {title = "強行挖掘", objective = "收集無法理解的詞語。", description = "厄魯長老說我們能夠在這裡找到首創者語言中最複雜的詞彙。\n\n我們必須一路攻到寶庫，然後找到那些詞語，並將其中的力量灌注到頭盔裡面。\n\n順帶一提，我從來沒有想過自己居然會有機會跟父親一起奮戰。雖然戰場是個危險的地方，但我總感覺戰場才是自己的歸宿之地。\n\n準備好就跟我說一聲。", progress = nil, completion = "我們成功了。我們把所能找到最高階的首創者之力灌注到了這頂破損頭盔當中。\n\n我們距離成功只剩下一步之遙。", rewards = "同理神諭披肩仲介者神諭披肩時光神諭披肩同理秘語肩墊仲介者秘語肩墊時光秘語肩墊同理神秘風帽仲介者神秘風帽時光神秘風帽同理數符胸甲仲介者數符胸甲時光數符胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][64812] = {title = "統御熔爐", objective = "前往托迦司的符刻師的秘牢。", description = "現在我們已經萬事俱備。破損的統御之盔經過首創者複雜語言的強化，而且這些裂片裡面也擁有我們記憶的力量。\n\n擁有我們希望抵禦統御之力的意志。\n\n接下來只要等到統御者重鑄頭盔，我們就可以運用其中的力量了。\n\n我知道這麼做很危險，但這是我們的唯一希望。", progress = nil, completion = "真是巧合，我原本被囚禁的那個地方，也正會是我們重獲自由的場所。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64813] = {title = "意志之冠", objective = "重鑄統御之盔。", description = "我起初在創造統御之力時，並沒有預料到這股力量會給各個界域帶來如此龐大的痛苦。不僅僅只是暗影之境，你們的世界也因此遭殃。\n\n是時候把這個象徵著統御魔法的頭盔重新塑造了。但這一次，這頂頭盔將作為另一種用途。\n\n我要把你和你同胞的意志力灌注到這頂頭盔當中，讓它能夠協助我們克服萬難，擊敗佐瓦爾。", progress = nil, completion = "我從來沒有感受過這樣的力量。我們創造了某種嶄新的事物。\n\n這將會是我們擊敗佐瓦爾的關鍵。", rewards = "您會收到：\n\n永恆者秘典"}
MultiLanguageQuestData['tw'][64814] = {title = "熔爐之戰", objective = "殺死8個淵誓者。", description = "我方部隊到目前為止都還撐得住，但我們還不算是真正鞏固這個區域。我們需要你協助削減敵軍的數量。\n\n淵喉行者，這對你來說應該不難吧？", progress = nil, completion = "我們必須保持警戒。絕對不能讓敵人突破我們的防禦。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64815] = {title = "我等共騎", objective = "幫助5個誓盟部隊的士兵。", description = "四大誓盟跟此地的自主機一起合作。\n\n不幸的是，我們其中一部分的士兵走散了，又或者是身負重傷，無法回到這個地方來。\n\n如果你能夠協助他們，將能幫上很大的忙。", progress = nil, completion = "我們在此處承受的損失越少，就越有辦法守住陣線。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64816] = {title = "現實近在眼前", objective = "回去澤瑞斯莫提斯吧。", description = "我們要追擊佐瓦爾，進入暗影之境最核心的地帶。\n\n我們必須回到澤瑞斯莫提斯，了結這一切。", progress = nil, completion = "我們在澤瑞斯莫提斯這裡還有很多任務需要完成，才有辦法抹除佐瓦爾對於暗影之境的影響力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64817] = {title = "大隱隱於市", objective = "保護植物供應區的方尖碑。", description = "那個聲音！是從植物供應區的方尖碑那裡傳過來的！\n\n這不可能，還沒有任何敵人突破防線才對！快點，<name>！跟我來！", progress = nil, completion = "敵人把自己隱藏得很好。這樣下去可不妙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64818] = {title = "可能需要增援部隊", objective = "到庇護城與伯瓦爾‧弗塔根交談。", description = "沒想到驚懼領主已經潛入了我們的陣營。我們必須告訴伯瓦爾發生了什麼事。\n\n我不能離開我在這裡的崗位。快，去把消息告訴他。或許受啟迪者的議會也會知道點什麼。", progress = nil, completion = "我們會派遣援軍過去幫助莫格萊尼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64820] = {title = "自己的錯自己負責善後", objective = "修理5個防禦節點。", description = "動物供應區通常由自動化傀儡負責照顧，但據說它們停止運作了。\n\n根據報告指出，就是因為你隨意干擾這些節點，才導致發生這個問題。也就是說，你要負責把它們修復好。拿著這個調諧器，它應該能夠派上用場。把東西修好之後，就不要再胡亂干擾它們了。", progress = nil, completion = "防禦機制又恢復運作了，希望這樣可以削減淵誓者的數量。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64821] = {title = "萬物皆虛假", objective = "找到並殺死4個驚懼領主破壞者。", description = "這些驚懼領主能夠偽裝成任何事物…就連澤瑞斯莫提斯的居民也不例外，這可不好對付。幸運的是，我們有辦法能夠驅散他們的幻象。\n\n搜索附近的區域，並測試自主機。如果發現驚懼領主的蹤影，就把對方解決掉。", progress = nil, completion = "這樣應該能夠遏止對方的邪惡陰謀。做得好，淵喉行者。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64822] = {title = "溝通中斷", objective = "重新下達命令給三位誓盟指揮官。", description = "莫格萊尼跟我們討救兵的行為很反常。我們原本就有計畫要增派援軍，已經送去三支部隊了。\n\n這樣聽起來，部隊都沒有順利抵達。去看看你能否找到部隊指揮官，務必確保援軍能夠順利抵達莫格萊尼那邊。", progress = nil, completion = "他們說你下達了其他命令？這就怪了。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64823] = {title = "分身決鬥", objective = "在思緒之環找到淵誓者。", description = "這件事情我總感覺不大對勁。根據你回報的狀況看來，似乎是我們內部有人在蓄意搞破壞…或者是又有驚懼領主在作怪。\n\n假如跟驚懼領主有關，那麼方尖碑就有危險！快點過去，要是不趕緊採取行動，可能就會為時已晚！", progress = nil, completion = "瑪爾加尼斯…\n\n我們屈居劣勢。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64824] = {title = "為熔爐而戰", objective = "跟珍娜一起前往來世熔爐。", description = "我們已經盡全速趕來這個地方了。有人看見安杜因出現在這片土地正中央的建物附近，叫做來世熔爐的地方。\n\n想必閻獄之主很快也會過去他的身邊。我們必須立刻啟程離開。", progress = nil, completion = "安杜因…\n\n我們會想辦法救你的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64825] = {title = "尋求庇護", objective = "跟著珍娜和貝恩一起回到庇護城。", description = "我感到迷惘。\n\n我們沒辦法追擊佐瓦爾和安杜因。我會開啟傳送門回到庇護城，到時再討論下一步的計畫。", progress = nil, completion = "我們會探索如何進入聖塚追上他們兩個。不過眼下，你應該要集中注意力處理更迫切的問題。", rewards = "您會收到：\n\n次元神秘護足次元數符手甲次元秘語之握次元神諭護腕"}
MultiLanguageQuestData['tw'][64829] = {title = "找到塔赫利", objective = "在索引編目附近找到塔赫利。", description = "在經歷萬古之久的寧靜之後，淵喉的影響為澤瑞斯莫提斯帶來了傷痛。我們的其中一位侍僧塔赫利特別無法接受最近發生的事情。她離開了這裡一段時間，到現在還沒回來。\n\n你能不能去幫忙關心一下？我們最後一次見到她的時候，她往埋藏在沙地底下的廢墟去了。", progress = nil, completion = "即便是現在，這個地方還是很漂亮。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64830] = {title = "招募受啟迪者", objective = "說服庇護城的長老提供協助。", description = "希瓦娜斯的命運並不是現在的當務之急。\n\n閻獄之主摧毀了和聲隧道，導致我們無法追擊。\n\n或許知識淵博的受啟迪仲介者對這些隧道有所了解，能夠給予我們協助。但是跟仲介者往來通常需要付出一點代價。\n\n不論他們有什麼要求，都盡量配合對方，我們一定要深入了解這些隧道。", progress = nil, completion = "澤瑞斯莫提斯藏有你正在尋找的答案。\n\n不過你得知道要從何處找起。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64831] = {title = "首創者的殘片", objective = "收集3個傳導殘片。", description = "魂靈供應區那邊說不定還殘留著淵誓者在進行破壞的證據。找到證據，從中掌握如何追擊閻獄之主的線索。\n\n我們一起展開狩獵吧。等靠近一點之後，我就能感應到首創者印記的魔法。", progress = "找到所有的殘片了嗎？", completion = "很遺憾，只有找到失去作用的殘片。\n\n但是朋友，不要因為這樣就放棄希望！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64832] = {title = "奪回魂靈供應區", objective = "殺死20個貪食的蜱蟲、5個入侵的吞食者和2個現實突破者。", description = "魂靈供應區到處都是吞噬者，他們就像是飢餓的原蜂一樣到處飛來飛去。\n\n他們正在摧毀附近的自主機，這並不符合首創者的意念，我們必須消滅這些吞噬者。\n\n基於安全著想，同時也為了恢復自然的秩序，請消滅這些威脅。", progress = nil, completion = "日後還會有更多的吞噬者出現，但你目前暫時削減它們的數量了。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64833] = {title = "異中求同", objective = "在魂靈供應區上方與亞拉長老會合。", description = "其他長老對於如何榮耀首創者的造物，有著相當嚴格的詮釋。\n\n但我不像他們那樣不知變通，大家的終極目標都是一樣的。\n\n我們回去你最後看見閻獄之主的地方吧。", progress = nil, completion = "下方的區域到處都是吞噬者，但這對你來說應該沒問題吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64834] = {title = "意外光芒", objective = "釐清傳導殘片之所以會產生反應的原因。", description = "<name>，快看。這些殘片在微微發亮！\n\n它們應該是對朝聖者之澤的某個東西起了反應。\n\n找出引發它們這種反應的原因！", progress = nil, completion = "看樣子這些殘片跟移位裝置有著某種關係，但其中的奧秘是什麼呢？\n\n雖然不曉得它們原本的用途是什麼，總之它們現在失去了能量。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64835] = {title = "藤蔓摘採", objective = "拯救5個失蹤的朝聖者。", description = "我拔腿狂奔，在長滿尖刺的樹叢中連滾帶爬，鞭笞者緊追在後。\n\n其他朝聖者就沒有我那麼走運了。我在逃跑的過程中，聽見其他人痛苦且充滿恐懼的慘叫聲。\n\n你必須找個方法進去。<name>，請務必救救他們！", progress = nil, completion = "真是太感謝你了，你拯救了那些還有希望的朝聖者。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64836] = {title = "將其扼殺於萌芽時期", objective = "殺死培育者。", description = "滋長界地曾經是個平靜的地方。好幾個世紀以來，都不斷有朝聖者來到這片土地瞻仰首創者的奇觀。但如今，這個地方已不再安全。培育者冷酷無情、不講道理，殺害了我的許多弟兄。\n\n你必須消滅它。\n\n其他長老不會同意我的這種做法，但他們錯了。", progress = nil, completion = "殺掉培育者是正確的選擇。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64837] = {title = "朝聖之旅", objective = "在朝聖者之澤與亞拉長老見面。", description = "朝聖者之澤是受啟迪者的聖地。那裡的長老對於首創者的造物有深入的了解。\n\n我們應該能在那裡找到這些奇特殘片的資訊。\n\n到朝聖者之澤跟我會合。離這裡不會很遠。", progress = nil, completion = "歡迎來到朝聖者之澤。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64838] = {title = "有朝聖者的地方，就有道路", objective = "與朝聖者之澤的居民交談。", description = "如果還有辦法修復這些殘片，朝聖者之澤或許有人知道該怎麼做。\n\n先跟尼拉夫長老談談吧。希望他願意提供協助。他今天感覺有些焦慮、分神。\n\n辦好了再到鎮上找我。", progress = nil, completion = "菲洛茲是我們最大的希望？而她卻跟其他朝聖者一起失蹤了？\n\n我們動作最好快點。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64839] = {title = "問題的根源", objective = "收集能量充沛的植物物質。", description = "我想我們應該可以利用這些植物體內的生長能量，並將其用作我們自己的用途，但我需要新鮮的樣本。\n\n你可以從這附近或是滋長界地內任何的鞭笞者身上，或是從被藤蔓纏繞的自主機身上收集到能量充沛的植物物質。", progress = "你找到能量充沛的植物物質了嗎？", completion = "這些樹根蘊藏著相當豐沛的生長能量。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64840] = {title = "失控的增生", objective = "收集12個繁殖精華。", description = "這種生長能量非常不尋常，我想要進一步了解它對於附近自主機的影響力。\n\n從滋長花園死去的自主機身上收集繁殖精華。\n\n把它帶回來讓我研究。", progress = "你拿到繁殖精華了嗎？", completion = "嗯…這種東西會快速繁殖，直到殺死宿主為止。\n\n這比起餽贈，更像是詛咒！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64841] = {title = "控制能量", objective = "釋放造物育籃的過剩能量。", description = "飄浮在我們頭頂上的那個建築就是造物育籃。\n\n我沒辦法靠近它，那座高塔內部充斥著創先者能量，過去那裡形同自殺。\n\n花園那邊有控制臺，能夠用來釋放能量，去使用控制臺吧。", progress = nil, completion = "你做得很好，淵喉行者！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64842] = {title = "花園亂象", objective = "喝下菲洛茲的藥水，並擊敗滋長花園的自主機。", description = "任何嘗試靠近造物育籃的人，都會被那些護衛自主機擊落。\n\n說不定我們能夠以毒攻毒？也就是使用首創者的造物能量來對抗首創者的造物。\n\n我一直沒有時間好好測試看看我的理論，不過這個藥水應該能夠協助你摧毀那些東西…如果你在過程中沒有因為造物能量的影響而死掉的話。", progress = nil, completion = "我覺得使用生長能量來反制對方這件事還挺有詩意的。", rewards = "肅清神諭罩衫新星神諭罩衫水晶神諭罩衫肅清秘語面具新星秘語面具水晶秘語面具肅清神秘肩冑新星神秘肩冑水晶神秘肩冑肅清數符之冠新星數符之冠水晶數符之冠您會收到：\n\n"}
MultiLanguageQuestData['tw'][64843] = {title = "製作鑰匙", objective = "在造物育籃恢復移位裝置鑰匙。", description = "既然已經搞定了那些暴躁的自主機，接下來只剩下最後一件事情要做了。\n\n我們要帶你和你的受啟迪者夥伴上去造物育籃那邊。\n\n剩下的就得靠你自己了。", progress = nil, completion = "我們辦到了！", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64844] = {title = "朝聖之旅結束", objective = "返回朝聖者之澤後面的高臺。", description = "你拯救了許多朝聖者，我也讓你能夠再次進入聖塚。我們的交易圓滿達成，我的朝聖之旅要告一段落了。\n\n但你的旅程還會繼續。\n\n回到朝聖者之澤後方的瞰臺，開啟移位裝置。\n\n<name>，謝謝你。這場冒險……讓我受益良多。", progress = nil, completion = "接下來要做的事情很重要。你準備好了嗎，&lt;name&gt;？", rewards = "聖歌護腿斷音護腿聖歌腿甲簧風琴胸甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][64846] = {title = "托迦司", objective = "與塔因納拉交談。", description = "無數靈魂在托迦司的廳堂中受苦。他們需要你的幫助！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64849] = {title = "譴罪之塔", objective = "跳進樞運之環前往托迦司，在那裡找到需要你幫助的人。", description = "我們對托迦司的了解不多。述命者羅塔爾說那裡有工作需要進行。\n\n他相信有一條路能讓你前往那個地方…而那裡有某個人需要你的協助。\n\n盡你所能抵達托迦司，去看看是誰需要幫助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64850] = {title = "暢遊托迦司", objective = "在托迦司中完成一個區域，協助維尼西的探索行動。使用托迦司內的引路裝置前往不同區域。", description = "淵喉行者，我聽過你的事蹟！你應該也聽過我，我是傳說中的維尼西。\n\n我在這裡透過美妙盒子的幫助，在托迦司中尋找珍貴的寶物。你也覺得這個盒子很棒吧。\n\n或許我們能合作。你先進去托迦司裡頭幫我探勘如何？\n\n如果你在裡頭有所發現，我還會賞你獎勵。", progress = nil, completion = "哎呀，那地方真是充滿各種恐怖的生物…還有強大的力量！\n\n太好了！盒子，聽到了嗎？這裡能找到很多好東西…或許比膽小的維娜里在淵喉找到的還多。\n\n嗯哼，謝謝你，淵喉行者。你漂亮的完成了工作。我之後有更多問題再麻煩你。", rewards = "您會收到：\n\n靈魂灰燼經驗加成"}
MultiLanguageQuestData['tw'][64852] = {title = "永世矩陣", objective = "將物品送去給法琳。\n\n已提供物品：\n", description = "<法琳應該用得上這個。>", progress = nil, completion = "我正好需要這個！然後這是我的一點心意！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64853] = {title = "兩條道路", objective = "前往幾何洞窟向統御者回報。", description = "這有回答到你的問題了嗎？\n\n噢，你是想要找個方法完全抵抗統御魔法嗎？這樣的話，我恐怕不曉得答案。首創者的語言只能拖延時間，沒辦法徹底阻止。\n\n但我能告訴你，如果你想要找到首創者語言中更複雜艱澀的詞語，你可以去無盡沙海那邊的寶庫尋找看看。\n\n我很希望自己也能親自去，但那邊的淵誓者數量太多了。\n\n祝你好運，後續研究順利！", progress = nil, completion = "這位長老已經給了我們有關這個謎題的重要答案。不過，我們接下來還必須採取實際行動。這麼做會有一定難度。\n\n首先，我們要進入無盡沙海，取得首創者語言中難以辨識的詞語，然後把那些詞語的能量注入到頭盔之中。\n\n但光是這麼做還不夠。我們需要更進一步。請容許我做點準備，與此同時，我需要你去幫忙尋找所需的東西。事成之後，我會再傳話給你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64854] = {title = "成功的陷阱", objective = "殺死5個淵誓密視者，並檢查清單上的野生動物。", description = "澤瑞斯莫提斯的野生動物會受到這片大地狂亂創造能量的吸引。野生動物只要找到蘊藏著這種能量的東西…就會把它吃掉！\n\n淵誓密視者注意到了這一點，並且打算找到這些野生動物，並從對方身上取出這股能量。\n\n消滅密視者，並使用拘捕陷阱制伏和檢查這些野生動物，以利於我們的研究。", progress = nil, completion = "這個資訊能夠協助我們進一步揭開澤瑞斯莫提斯的秘密。", rewards = "您會收到：\n\n靈魄網砂蝕聖物神諭罩衫神諭窄褲神諭披肩神諭束帶神諭護腕秘語外衣秘語之握秘語面具秘語長褲秘語肩墊\n                            顯示 28 更多                        秘語繫腰神秘護手神秘風帽神秘腿甲神秘肩冑神秘腰鍊數符之冠數符護脛數符肩甲數符束腰異常古老的披風暗語蝕刻頸環暗語蝕刻垂飾簧風琴提燈頌曲重弩狂想斬斧連奏敲錘民謠之盾輓歌權杖輕緩之劍節奏碎擊錘序曲剃刃聖歌法杖哀歌之刃首創者的暗語首創者的暗語首創者的暗語首創者的暗語"}
MultiLanguageQuestData['tw'][64860] = {title = "乙太晶格", objective = "將物品送去給法琳。\n\n已提供物品：\n", description = "<法琳應該用得上這個。>", progress = nil, completion = "我正好需要這個！然後這是我的一點心意！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64861] = {title = "天命圓盤", objective = "將物品送去給法琳。\n\n已提供物品：\n", description = "<法琳應該用得上這個。>", progress = nil, completion = "我正好需要這個！然後這是我的一點心意！", rewards = "您會收到：\n\n邪惡波克波可首創者的暗語首創者的暗語宇宙靈流"}
MultiLanguageQuestData['tw'][64863] = {title = "秘法守護者", objective = "擊敗4隻守護者或魁儡。", description = "那些在育所巡邏的傀儡並非由大地守護者的魔法活化。\n\n<德維希安瞇起雙眼。>\n\n不能讓敵人潛伏在我們之中。\n\n摧毀他們，清出安全的前進路線。", progress = nil, completion = "那些傀儡是由蒼藍龍魔法活化的。\n\n大地守護者不會允許這種事發生！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64864] = {title = "半龍人，甦醒吧", objective = "喚醒其他半龍人。", description = "<你彷彿從永無止境的睡眠中醒來，所有記憶都只剩下模糊的片段。\n\n你面前的半龍人毫無反應，被不知名的魔法凍結在原地。而你旋即察覺，自己體內擁有解開夥伴束縛的力量。\n\n育所內可能還有其他半龍人處於靜滯狀態。\n\n你必須喚醒他們。>", progress = nil, completion = "&lt;埃祖拉瑟聽取你的報告。&gt;\n\n我的記憶跟你一樣破碎，&lt;name&gt;。但我們絕不能止步不前。\n\n我們必須評估情況，並且建立計畫。", rewards = "您會學到：\n\n崩解\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][64865] = {title = "整裝出發", objective = "取得武器、護甲和補給品。", description = "敵人已經入侵，而我們的部隊卻受困於魔法靜滯，育所面臨崩壞的危險。\n\n<name>，這正是我們艱苦訓練的目的。心有懷疑時，先退回你熟知的領域。\n\n先把最要緊的事情辦好：武器、護甲和補給品。我會去統整部隊，你來收集並裝備所有你能找到的東西。\n\n然後我們去找大地守護者，奈薩里奧一定擁有我們要的答案。", progress = "既然什麼都想不起來，就只能仰賴基本訓練所養成的直覺了。", completion = "這件裝備很古老，食物也滿是灰塵。\n\n真奇怪…這些口糧看起來像放了一輩子。\n\n好吧，我們只能將就點用了。", rewards = "您會收到：\n\n焰影之印晶紅法杖"}
MultiLanguageQuestData['tw'][64866] = {title = "進入大熔爐", objective = "準備好離開育所。", description = "喚能師，我們需要你的技能。\n\n育所正在崩毀，而且我們的補給品不足。我們必須趕緊離開此處，可是我們得先通過這道秘法屏障。\n\n外頭應該還有需要協助的半龍人。照料他們的傷勢，並且消滅任何阻撓你的敵人。\n\n<name>，這可能是我們最後一次並肩走在這裡了。好好加油。", progress = nil, completion = "你治好了我的同胞，做得好。\n\n現在來解決那條龍吧。", rewards = "您會收到：\n\n赤紅半龍人披氅"}
MultiLanguageQuestData['tw'][64867] = {title = "受啟迪者的補給品", objective = "在澤瑞斯莫提斯地庇護城與威洛交談。", description = "啊，有了。我期待這一刻已經有好一段時間了！\n\n來拜訪我吧。我們一起分享這份成就。\n\n我替你精心準備了某樣東西。", progress = nil, completion = "這份獎勵真是沉重。你確定你自己一個人沒問題嗎？", rewards = "您會收到：\n\n受啟迪的仲介者物資"}
MultiLanguageQuestData['tw'][64870] = {title = "受啟迪的仲介者楷模", objective = "在澤瑞斯莫提斯地庇護城與威洛交談。", description = "哎呀呀。你最近看起來很忙呢？", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][64871] = {title = "門口的龍", objective = "擊敗拉比沙苟斯並逃出戰爭育所。", description = "那條藍龍會弄垮育所，把我們困在裡面！\n\n他自稱是瑪里苟斯的手下。那個名字很耳熟，但…巨龍為什麼會想把我們關起來？\n\n聽著，$p。我們所受的訓練是要與巨龍並肩作戰，而不是對抗他們。但是，我們已經別無選擇。\n\n現在我們應該為所當為，喚能師。", progress = nil, completion = "我們會把瓦礫清乾淨，並且確保每個&lt;race&gt;的安危。\n\n不過，我們需要先打下這個區域。", rewards = "您會收到：\n\n晶化青金石"}
MultiLanguageQuestData['tw'][64872] = {title = "體內的烈火", objective = "學習火焰之息並練習強化攻擊。", description = "<name>，你是位喚能師。你是高手中的高手，半龍人軍隊中最爐火純青的優秀士兵。\n\n我很看好你。\n\n儘管你的記憶變得模糊殘破，但你血液中仍流淌著龍族的力量。駕馭它。\n\n你最有力的一項武器，就是你的吐息攻擊。你吸氣的時間越長，你體內的火焰就越強大。\n\n這些爬滿訓練場的蟲群是很好的目標。", progress = nil, completion = "很好。你並沒有忘掉之前的訓練。\n\n低下頭，吸飽氣。", rewards = "您會學到：\n\n火焰之息\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][64873] = {title = "舒展你的翅膀", objective = "練習施放飛騰。", description = "看到那麼多人順利逃離戰爭育所，我覺得很振奮。我自己的龍隊…就沒那麼幸運。\n\n<安珀莎沉默了一陣子。>\n\n禁忌之境還有其他育所，裡面也有陷入危機的半龍人。需要強健的翅膀才能抵達他們所在的地方。\n\n專心一點。別忘記你的訓練，再一次去感受那陣風。你必須找回自己的力量，飛到其他育所。\n\n沒時間休息了。", progress = nil, completion = "你熟悉的速度比過去的我快多了！\n\n現在，你的&lt;class&gt;訓練已經全部完成了。我以前本來是想當個外交官的。", rewards = "您會學到：\n\n飛騰\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][64875] = {title = "奇妙的事物", objective = "前往流亡者洞穴，親自看看瑟祖拉那邊的狀況。", description = "<name>，還好我找到你了！是法琳派我過來找你的。\n\n是有關神諭者的事，它…呃…這有點難形容。總之你應該親自過去看看，動作快！", progress = nil, completion = "我們可能就快要發現奇妙的東西了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64876] = {title = "球體音樂", objective = "檢查圍繞在瑟祖拉身體周圍的碎形。", description = "這是個逐漸而緩慢的過程，神諭者散發出來的能量越來越多，直到你眼前看到的這個宏偉設計成形為止。\n\n不久之後，我們耳邊響起震耳欲聾的嗡嗡聲。\n\n雖然我嘗試過要靠近碎形…但一直無果。不過，這些碎形似乎會跟波克波可產生共鳴。\n\n你跟它之間有著特殊的羈絆，說不定我辦不到的事情，你能夠做到。", progress = nil, completion = "是幻象！神諭者在跟我們溝通！你也看到了吧？真是驚人！這個幻象…讓我的頭好痛。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64878] = {title = "漫長的奇妙旅途", objective = "跟著波克波可一起行動，釐清幻象的內容。", description = "<幻象的聲音透過波克波可傳來，感覺微弱且模糊。>\n\n我是…神諭者瑟祖拉。這個自主機…透過我的聲音在說話，它會暫時聽從我的使喚。\n\n藍圖…遭到扭曲，我們必須加以修復。\n\n深不見底的飢餓席捲這片沙地，絕不能讓它吞噬它正在尋找的東西。\n\n跟我一起來吧，跟著我的聲音前進。", progress = nil, completion = "在沙地上方、在我們上方，容器等待著。", rewards = "肅清神諭罩衫新星神諭罩衫水晶神諭罩衫肅清秘語面具新星秘語面具水晶秘語面具肅清神秘肩冑新星神秘肩冑水晶神秘肩冑肅清數符之冠新星數符之冠水晶數符之冠您會收到：\n\n"}
MultiLanguageQuestData['tw'][64879] = {title = "重要發現", objective = "在流亡者洞穴與法琳會合。", description = "淵喉行者，佩拉苟斯稍早來過一趟，他給了我一份報告，還說神諭者的準備作業已經完成了，需要你盡速趕過去。\n\n如果這件事情能夠協助我們達成任務，那我希望你可以參與。快去流亡者洞穴看看他們需要什麼吧。", progress = nil, completion = "凡人，我有重要消息。瑟祖拉告訴我們準備作業已經完成，是時候創造新的審斷者了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64888] = {title = "借來的力量", objective = "擊敗受到引誘的易變敵人或是汲取池水中的力量，藉此取得與宇宙能量來強化波克波可。", description = "土地供給我們、土地感到飢渴，入侵者吞噬了我們所需之物。\n\n奪回被吞噬之物，吸收殘存的豐饒。\n\n翅膀需要有風才能起飛，我們需要力量才能晉升。", progress = nil, completion = "力量產生脈動，重新點燃希望。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64889] = {title = "澤瑞斯莫提斯的天作之合", objective = "研讀樞位排列，並使用樞位轉移抵達最終樞位。", description = "暗語是關鍵所在。每個暗語，都是向前一步。你必須全部找齊\n\n進去內部密室吧，第一樞位排列在等著我們。\n\n這是邁向晉升、邁向容器的第一步。", progress = nil, completion = "旅途的最後階段開始了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64935] = {title = "介於石與石之間", objective = "砸碎石頭，找到被埋起來的第二樞位排列。", description = "<這個地方到處都散落著岩石。吞噬者所造成的破壞之嚴重，導致你難以找到暗語。\n\n說不定附近的僕從有辦法幫助你清除碎石。>", progress = nil, completion = "情況有所進展。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64936] = {title = "尋尋覓覓", objective = "收集最終樞位的入口詞語，以利取得容器。", description = "大門上有三道鎖，三把鑰匙隱藏在至高點的頂端。\n\n找到詞語、唸出字句、取得容器。", progress = nil, completion = "一場旅程的結束，是另一場旅程的開端。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64937] = {title = "你點亮了我的生命", objective = "操控波克波可保護容器不受吞噬者所傷。", description = "強大的力量會誘發強烈的飢渴，欲望無窮無盡的吞噬者爬到了懸崖上方尋找食物。\n\n再過不久，它們就會席捲高原。它們想要吞噬周遭所有的一切，包括容器、容器的力量還有我們。\n\n我們絕不能讓這種事情發生，操作這個自主機終結那些索求無度的吞噬者吧。", progress = nil, completion = "暫時找到了棲身之所，但還有更重要的任務尚未完成。", rewards = "您會收到：\n\n聖歌軟靴斷音長靴聖歌罩盔簧風琴振音踏靴"}
MultiLanguageQuestData['tw'][64941] = {title = "雞靈魂", objective = "將雞靈魂帶給森林之心的丘發。\n\n已提供物品：\n", description = "<雞靈魂既活潑又貪婪。你將來能任意化身為雞之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][64942] = {title = "統御者的呼喚", objective = "與奧睿博司的塔因納拉交談，前往審斷者殿堂。", description = "雖然我們在統御聖所奮戰，努力想要阻止閻獄之主，但還是失敗了。他把奧睿博司吸入淵喉之中、擊倒了審斷者，並開啟通往澤瑞斯莫提斯的通道。\n\n我們必須追上去。\n\n在審斷者殿堂中，我們將鑄造出屬於自己的道路。\n\n淵喉行者，快。暗影之境以及其他所有世界的命運都危在旦夕。", progress = nil, completion = "我們只差最後一個符印，就可以追擊佐瓦爾了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64944] = {title = "倉促啟程", objective = "騎上靈魄龍鰻，展開前往澤瑞斯莫提斯的旅程。", description = "通往澤瑞斯莫提斯的通道開啟了。\n\n我們必須在這裡分道揚鑣。永恆者禁止回到自己被創造的地方。佐瓦爾違背了創先者最神聖的定律。\n\n你必須獨自一人面對這場旅程。\n\n去吧。在澤瑞斯莫提斯建立據點，這樣我們才能派遣誓盟的部隊過去。\n\n然後，我們會追擊閻獄之主，並終結他的瘋狂。", progress = nil, completion = "看來…我們完全離開奧睿博司了。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64945] = {title = "奇妙土地的陌客", objective = "跟佩拉苟斯一起探索周遭環境。", description = "我們…抵達澤瑞斯莫提斯了嗎？然後，我們是行走在水面上嗎？\n\n這個地方真是太奇妙了！雖然隔著迷霧看得不是很清楚，但還是很奇妙。\n\n我依稀看見遠處有某種建築。說不定在那裡能夠找到答案。", progress = nil, completion = "我絕不會坐視閻獄之主的爪牙汙染這片土地！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64947] = {title = "助我一臂之力", objective = "協助法琳。", description = "如果要把閻獄之主逐出澤瑞斯莫提斯，我們就必須動用所有的資源來對抗敵人。\n\n附近的存放庫那邊有個蘊藏力量的物體，但是存放庫的防禦機制只聽自主機使喚。我不願意傷害自主機，但我有找到一個故障的自主機。\n\n如果你能夠把它的手取下來，我們就可以利用那個沒有作用的肢體來進入存放庫。\n\n把首創者的造物拿來作為這種用途實在不是很妥當，不過我們絕不能坐視淵誓者在這個界域撒野。", progress = nil, completion = "我還真沒預料到會有這種結果。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64949] = {title = "研究用途", objective = "從創始之廳的警戒自主機身上收集12個完好的自主機碎片。", description = "我在澤瑞斯莫提斯的這段時間，很努力地盡量不去打擾到自主機。到目前為止，它們也都幾乎都無視我的存在。\n\n看樣子最近發生的事情改變了這一點。\n\n我想再次強調，我並不想傷害首創者的造物。如果你在執行任務的過程中不得不與自主機交戰，那我們至少得確保自主機不會白白犧牲。\n\n如果我有機會研究死去自主機的碎片，說不定能夠從中找到方法來對抗淵誓者。\n\n請務必小心謹慎。", progress = "你有找到什麼有用的碎片嗎？", completion = "雖然失去了自主機令人惋惜，但這些碎片將有助於我進行研究。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64950] = {title = "雙向交流", objective = "使用自主機的手啟動自主機控制臺，並獲得存放庫的寶藏。", description = "看樣子其它的自主機很不滿我們占用它們同胞的手。它們對我們有了敵意。\n\n真糟糕，不過我們不能因為這樣就停下腳步。\n\n自主機的手應該能夠啟動創始存放庫裡面的控制臺。我認為那個儲物庫裡面藏有威力強大的物品。\n\n拿到東西之後，我會引導你前往另一個地方，這樣你說不定就能聯絡上那些沒有跟你一起過來的盟友了。\n\n就這樣說定囉？", progress = "你有從控制臺那邊拿到東西了嗎？", completion = "&lt;法琳一把從你手中把核心拿過去。&gt;\n\n有趣。我見過很多自主機核心，但這個核心充滿能量、散發出光澤，我從未見過這樣的核心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64951] = {title = "前往庇護城的道路", objective = "跟法琳一起離開創始存放庫。", description = "我原先並沒有料到今天會遇到活生生的凡人和琪瑞安，不過你們所提供的協助對我來說相當重要。\n\n在我開始研究這個自主機核心之前，我會引導你們前往庇護城，也就是我的遠征隊在抵達此處之後所設置的據點。\n\n雖然我因為質疑同胞的「啟迪」教義而遭到流放，但我還是不希望閻獄之主毀了庇護城。\n\n如果你願意幫助他們，他們說不定也會協助你回到盟友身邊。畢竟我們這些仲介者最講究的就是利益交換。", progress = nil, completion = "我只能走到到此為止了。\n\n我和我的同胞…無法認同彼此的哲學思想。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64952] = {title = "摧毀摧毀者", objective = "摧毀4個淵喉摧毀者。", description = "淵誓者擁有可怕的武器，能夠匯聚黑暗魔法攻擊大門。\n\n庇護城周遭的防護屏障就快要撐不住了。我們所建造的一切、所珍視的一切，很快都會化為烏有。\n\n如果你真的那麼厲害，那就證明給我們看吧。摧毀敵人的武裝，協助我們捍衛家園。\n\n願首創者保佑你旗開得勝。", progress = nil, completion = "凡人，你替我們爭取到了時間。願首創者保佑我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64953] = {title = "捍衛庇護城", objective = "在大草原擊敗13個淵誓者。", description = "淵誓者在我們的大門口外面集結成軍。看樣子他們是鐵了心想要佔領我們的家園！\n\n受啟迪者只不過是想要靜靜地讚嘆首創者的奇觀。庇護城防護屏障的用途是保護我們免受小型威脅的侵擾。但我們沒想到閻獄之主會派大軍來攻打我們。\n\n凡人，你說你是我們的盟友對吧？那就協助我們捍衛這片神聖的土地吧。", progress = nil, completion = "你確實有幾把刷子，不過敵人的攻勢卻依舊不斷在增強。", rewards = "您會收到：\n\n名望名望"}
MultiLanguageQuestData['tw'][64957] = {title = "古老的甬道石", objective = "開啟通往奧睿博司的甬道石。", description = "閻獄之主撤回了他的大軍。我應該要鬆一口氣才對，但我擔心他是已經找到了進入聖塚的通道。\n\n<亞拉長老渾身發抖。>\n\n雖然克瑞斯長老對你懷有疑慮，但你證明了自己確實是位盟友。我們需要更多像你這樣的人。\n\n我們這支遠征隊起初來到澤瑞斯莫提斯的時候，發現了一個休眠的甬道石。如果你真的是淵喉行者，那麼根據預言所說，你應該能夠啟動那個甬道石。\n\n如果你的盟友能夠拯救這片神聖的土地，那麼必須為他們打開通到。\n\n來吧。", progress = nil, completion = "淵喉行者！感謝聖光，你和佩拉苟斯都沒事！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64958] = {title = "集結成軍", objective = "在澤瑞斯莫提斯與克瑞斯長老交談", description = "你在前往澤瑞斯莫提斯的旅途中沒有遇到大礙，真是太好了。我聽到佩拉苟斯和克蕾雅的談話內容，看樣子你們這趟旅程很精彩。\n\n這些受啟迪的仲介者說不定能夠成為我們寶貴的盟友。他們對於自主機以及土地的了解，應該都能夠幫助我們對抗閻獄之主。\n\n我們的部隊已經集結完畢，隨時都能跟你一起前往澤瑞斯莫提斯。\n\n$p，最後一場戰鬥即將開打。", progress = nil, completion = "你成功捍衛了庇護城，現在還帶了盟友過來守護這片神聖的土地。\n\n凡人，願首創者保佑你。", rewards = "庇護城衛的盾牌和諧致動器光潔重弩不朽法刃永恆衛士根除者庇護城衛的釘錘庇護城衛的鬥棍真理追尋者的法杖卓越裁決錘奇異之尖門衛戰刃古老保衛者的粉碎之錘您會收到：\n\n靈魄網"}
MultiLanguageQuestData['tw'][64959] = {title = "水獺靈魂", objective = "將水獺靈魂帶給森林之心的丘發。\n\n已提供物品：\n", description = "<水獺靈魂迅捷又自負。你將來能任意化身為水獺之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][64960] = {title = "餵食原基蠕蟲", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][64961] = {title = "貓靈魂", objective = "將貓靈魂帶給森林之心的丘發。\n\n已提供物品：\n", description = "<貓靈魂優雅又充滿好奇心。你將來能任意化身為貓之形態。>", progress = nil, completion = "喔，是貓！你現在也可以飛撲了！", rewards = nil}
MultiLanguageQuestData['tw'][64962] = {title = "誠如預言", objective = "帶法琳和占卜者到中心。", description = "球體就緒。旋律漸漸成形。去吧，去演奏占卜者的和聲，啟動重生的循環。", progress = nil, completion = "造物的窸窣聲、黑暗中的低語。我們可以開始了。", rewards = "您會收到：\n\n名望"}
MultiLanguageQuestData['tw'][64963] = {title = "叛逃者的請求", objective = "前往科西亞的守衛者歇息地，將密文交給公爵夫人敏克絲。\n\n已提供物品：\n", description = "<打開卷軸，你看出這是死亡之盡瑪卓薩斯成員傳給汎希爾盟友的徵調兵器密文…他們都是閻獄之主的僕從。\n\n科西亞的死亡先鋒軍應該有人能幫你解密，如此就能得知對方的計畫。>", progress = nil, completion = "&lt;公爵夫人敏克絲讀著你提供的卷軸，露出一抹微笑。過沒多久，她大笑幾聲。&gt;\n\n閻獄之主部隊的密文還真是落後！這卷軸並沒有說明目標的位置，但看樣子是有一箱武器可供領取。你和你的盟友應該不用費太多心力就能找到這些武器。", rewards = "您會學到：\n\n找到叛徒的寶箱"}
MultiLanguageQuestData['tw'][64964] = {title = "選擇戰鬥員", objective = "選一個自主機傀儡，並使用它來對付淵誓者。", description = "閻獄之主在地層供應區的部隊對於那個地區帶來了嚴重的破壞。如果坐視不管的話，我們將會失去那個區域的所有知識。\n\n我們的其中一位夥伴準備了一些自主機，能夠對抗淵誓者。去跟他們碰面、擊退那些對澤瑞斯莫提斯不敬的敵人。", progress = nil, completion = "做得好。", rewards = "您會收到：\n\n靈魄網砂蝕聖物神諭軟靴神諭長手套神諭兜帽神諭窄褲神諭束帶神諭護腕秘語足靴秘語之握秘語面具秘語長褲\n                            顯示 33 更多                        秘語肩墊秘語繫腰秘語腕環神秘鎖甲護胸神秘護足神秘風帽神秘肩冑神秘腰鍊神秘束腕數符胸甲數符脛甲數符之冠數符肩甲數符束腰數符腕輪異常古老的披風暗語蝕刻戒指暗語蝕刻指環暗語蝕刻頸環暗語蝕刻垂飾簧風琴提燈頌曲重弩狂想斬斧連奏敲錘空無法刃民謠之盾輕緩之劍聖歌法杖哀歌之刃首創者的暗語首創者的暗語首創者的暗語首創者的暗語"}
MultiLanguageQuestData['tw'][64969] = {title = "荒煙漫草", objective = "在滋長界地外面與亞拉長老會合。", description = "我現在明白尼拉夫長老為什麼如此擔憂了。\n\n許多前往滋長界地的朝聖者都沒了消息，其中也包括菲洛茲。他是最有可能握有我們修復殘片所需資訊的人。\n\n做好準備。滋長界地中有許多首創者最新的造物。如果那裡發生了什麼事，或許會造成極其危險的後果。", progress = nil, completion = "菲洛茲解釋了那群失蹤朝聖者的遭遇。\n\n原來他們被困在滋長界地裡面！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][64970] = {title = "時朽鑰石：破碎群島", objective = "完成一個時朽鑰石地城。", description = "我最近獲得了一個特別的鑰石。雖然它看起來很老舊，但它的背後一定有段精彩的故事。\n\n帶著這個鑰石。或許它能讓你想起過去的冒險。當然，希望你能告訴我那些冒險故事。", progress = nil, completion = "朋友，你的冒險真是太精彩了！請收下我的一點心意。", rewards = "您會收到：\n\n多功能靈魄容器"}
