MultiLanguageQuestData['tw'][65060] = {title = "治癒者火山口", objective = "去治癒者火山口與辛德瑞翠絲見面", description = "你從秘法信標看到的畫面顯示，還有半龍人被困在自己的育所裡，我們不能再讓自己的族人出現任何傷亡。\n\n<安珀莎停了一下，眉頭深鎖。>\n\n治療之翼是我們當中最出色的醫療者，他們的育所就位在治癒者火山口，辛德瑞翠絲知道路。\n\n務必把他們都救出來，喚能師。", progress = nil, completion = "看看這些傷患…\n\n裡面有更多的治癒者。我們必須幫助他們！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65063] = {title = "進入巢穴", objective = "跟隨辛德瑞翠絲去尋找維利迪亞。", description = "不管出現在這個育所的劇毒是什麼，這種毒性就連我們最好的治療者都抵擋不了。\n\n這對我們兩人來說都不是什麼好事，<name>。\n\n無所謂。半龍人被困在裡面，所以不管風險有多高，我們都必須進去。\n\n深呼吸，然後跟我一起衝！", progress = nil, completion = "很好。你醒了。\n\n&lt;維利迪亞清了清她的喉嚨。&gt;\n\n我們現在需要&lt;class&gt;的能力。", rewards = "您會收到：\n\n赤紅半龍人戰裝鍊衫"}
MultiLanguageQuestData['tw'][65064] = {title = "看看我找到了誰！", objective = "在次元瀑布附近取得6朵炫彩薔薇。", description = "你看這生物多麼神奇！\n\n希洛說我們已經沒有足夠的資源可以再養一隻「不尋常的寵物」了。\n\n但或許有個方法能夠改造艾爾尼，讓我可以收留它。這裡的生物和周遭環境有一種奇妙的互動方式。我們說不定能夠讓他的體型變小。\n\n我知道有個地方可供我們進行研究。附近有炫彩薔薇，這種植物可能可以觸發我需要的反應，你能夠幫忙收集一點過來嗎？", progress = nil, completion = "或許我們應該先找其他對象來當白老鼠，然後再拿艾爾尼做實驗。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65066] = {title = "植物的香氣", objective = "在次元瀑布附近拿炫彩薔薇做實驗。", description = "或許我們應該先釐清效果，然後再拿艾爾尼做實驗。\n\n其他的薔薇先留著，我們應該多做點測試再說。相較之下，瀑布那邊的生物溫馴許多，更適合進行這類試驗。\n\n我們來看看不同的生物對於薔薇的香氣是否也會有不同的反應。", progress = nil, completion = "這些結果看起來…沒有定論。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65067] = {title = "仲介者燒杯", objective = "從次元瀑布附近的肉食原鹿那裡取回零件燒杯。", description = "在你還沒來這裡之前，我正在進行自己的實驗。\n\n那些實驗…進行得並不順利。沒想到周遭環境中的元素居然能會讓生物變得兇暴，導致最溫馴的生物都變成掠食者。\n\n我當時把裝著零件的容器丟下拔腿狂奔，現在卻記不得當時丟在哪裡了。\n\n燒杯肯定就在那群肉食原鹿所在位置。如果這些花朵無法奏效，我們會需要那個容器才有辦法進行下一個階段的實驗。", progress = "小心，那些肉食原鹿可是會咬人的！", completion = "啊，這個東西鐵定會派上用場的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65068] = {title = "洪流般的影響", objective = "拿次元瀑布的水做實驗。", description = "次元瀑布這邊的許多生物似乎都受到了周遭環境的影響。嗯…我們拿瀑布本身來做實驗吧！\n\n澤瑞斯莫提斯這邊的許多自然組件都具有特殊效果，說不定水也是如此。\n\n取一點水過來，然後把水灑在瀑布那邊的生物身上，看看會發生什麼事！", progress = nil, completion = "真是出人意料。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65069] = {title = "遏止漩渦", objective = "殺死50個艾爾尼複製體。", description = "那些艾爾尼複製體並不怎麼友善。\n\n次元瀑布的某種效果創造出了他們，但他們並不穩定。你有看見他們的去向嗎？\n\n我們必須趕快削減他們的數量，以免他們跑去傷害其他的野生動物。你去負責處理這件事情，我要去瀑布那邊再採集另一個樣本。", progress = nil, completion = "天哪…你怎麼了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65070] = {title = "我能養他嗎？", objective = "對艾爾尼灑水。", description = "喔不，我害這片神聖的土地變得混亂不堪。\n\n你看，艾爾尼跟你建立了羈絆。這令我感到難受，但跟我相比，你應該能夠把他照顧得更好。\n\n等我們解決這件事情之後，我建議你可以領養他。\n\n至少我們現在知道，瀑布擁有能夠改變生物大小的能力。我們再試一次。", progress = nil, completion = "成功了！非常感謝這一路走來你的熱心幫忙，接下來…他就要跟你一起行動了。請好好照顧他。\n\n再見，艾爾尼。", rewards = "您會收到：\n\n艾爾尼"}
MultiLanguageQuestData['tw'][65071] = {title = "救命！", objective = "拯救小柯", description = "我需要幫忙。\n\n我正在四處探索，因為這是我擅長的事，但是我不知道我的妹妹小柯跟著我出來，我需要你幫忙找到她，她有麻煩，請幫忙，幫幫我好嗎？\n\n她進入了洞穴，但她不像我，她不擅長躲藏，我們的父母離這裡太遠，幫不上忙。\n\n你可以幫忙找她嗎？趕在怪物之前先找到她？", progress = nil, completion = "你找到了我妹妹！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65072] = {title = "不安全的工作環境", objective = "協助拉娜搜尋並收集8個創先者文物。", description = "自從拉娜在悠恆裂片那邊發現創先者文物之後，受啟迪者就一直議論紛紛。這些文物比我們原先發現的還要更加古老，透過這些文物，我們說不定能夠更進一步地去瞭解澤瑞斯莫提斯的運作機制。\n\n拉娜正在收集文物，但我擔心她可能會遇到危險。我們在附近有發現希商集團密探的行蹤，對方很有可能是要來竊取文物的。\n\n請前往悠恆裂片，並協助拉娜收集文物。", progress = "你拿到創先者文物了嗎？", completion = "&lt;name&gt;，我很感謝你的幫忙。", rewards = "您會收到：\n\n靈魄網砂蝕聖物神諭長手套神諭窄褲神諭披肩秘語面具秘語長褲神秘護足神秘腿甲數符脛甲數符之冠數符護脛\n                            顯示 18 更多                        數符肩甲異常古老的披風暗語蝕刻戒指暗語蝕刻指環暗語蝕刻頸環暗語蝕刻垂飾頌曲重弩狂想斬斧圓舞戰刃空無法刃節奏碎擊錘序曲剃刃聖歌法杖哀歌之刃首創者的暗語首創者的暗語首創者的暗語首創者的暗語"}
MultiLanguageQuestData['tw'][65073] = {title = "劇毒的問題", objective = "收集6個毒素腺體。", description = "你恢復得很快，<name>。很好。\n\n從我的育所裡逃出來的那些人正在好轉，但其他人還被困在裡面。要是你毫無準備地衝進去救他們，又要連累我去把你拖出來。\n\n有不少甲蟲在火山口周圍築巢，利用牠們的毒素腺體，或許能反制那種劇毒的效果。\n\n我的狀況不適合親自去採集，所以只能靠你了，喚能師。", progress = "時間不多了。", completion = "很好，正是我要的。\n\n我會先製作出能反制那種劇毒的解藥，然後讓你送回育所。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65074] = {title = "簡單的獵物", objective = "殺死 4 個鐮螳螂。", description = "這個育所附近的荒野是鐮螳螂的棲地，牠們是非常貪吃的蟲型生物，有很強的領土意識和攻擊性。\n\n這些受傷的人很容易成為那些生物的獵物。我不希望治癒者在恢復的時候受到攻擊。\n\n在我照料維利迪亞的時候，請去削減牠們的數量。\n\n她…非常勇敢。", progress = nil, completion = "鐮螳螂一向是很難纏的對手，但在我們陷入靜滯的時候，牠們的體型好像變大了，而且更具威脅性。", rewards = "您會收到：\n\n赤紅半龍人戰裝腰帶"}
MultiLanguageQuestData['tw'][65080] = {title = "靈魄轉移", objective = "將靈魄存入緬懷聖庫的原野靈魄分流裝置裡。", description = "現在關鍵時刻到了。\n\n把你身上的靈魄存入我身後的原野靈魄分流裝置。\n\n幸運的話，應該不會有副作用。像是損失靈魄、失去意識，或喪失記憶，那一類的事情。", progress = nil, completion = "太成功了！\n\n相信這個分流裝置，不論是現在或未來都會很有用的。", rewards = nil}
