MultiLanguageQuestData['tw'][65145] = {title = "文物線索", objective = "研究有很好的進展。\n\n初步的研究結果中，我發現了如何找到更多文物的線索，我可以把這些分享給你。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n文物掉落提升"}
MultiLanguageQuestData['tw'][65146] = {title = "文物獵人", objective = "有些文物似乎有痕跡或獨特的識別方式。\n\n這些是詳細的說明。當你找到來源時，這些應該能讓你找到更多文物。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n文物掉落提升"}
