MultiLanguageQuestData['tw'][65335] = {title = "來自奧睿博司的消息", objective = "與『光明使者』烏瑟交談。", description = "我有很重要的消息，能夠從中洞悉閻獄之主的陰謀詭計。\n\n只要胸懷信念並且擁有知識，我們也有機會能夠貫徹真正的正義。\n\n英雄，我們有很多需要討論的事情。", progress = nil, completion = "希瓦娜斯的經歷跟安杜因的命運可能有著密不可分的關係。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65336] = {title = "結構圖重新同化：穩定的地質元素", objective = "把結構圖帶去合適的原靈體熔爐。\n\n已提供物品：\n", description = "<這個結構圖裡面記載著新原靈體造物的建造設計。把結構圖帶去合適的原靈體熔爐，說不定熔爐就能夠為你製作出裡頭記載的生物。>", progress = nil, completion = "&lt;原靈體熔爐在吸入結構圖時發出帶有旋律的音調。&gt;", rewards = "您會學到：\n\n穩定的地質元素"}
MultiLanguageQuestData['tw'][65348] = {title = "結構圖重新同化：全潛能核心", objective = "把結構圖帶去合適的原靈體熔爐。\n\n已提供物品：\n", description = "<這個結構圖裡面記載著新原靈體造物的建造設計。把結構圖帶去合適的原靈體熔爐，說不定熔爐就能夠為你製作出裡頭記載的生物。>", progress = nil, completion = "&lt;原靈體熔爐在吸入結構圖時發出帶有旋律的音調。&gt;", rewards = "您會學到：\n\n全潛能核心"}
MultiLanguageQuestData['tw'][65349] = {title = "失落恩典", objective = "前往魂靈供應區。", description = "湧泉之水乾涸了。\n\n首創者的恩典從來沒有讓我們失望過，有朝聖者開始擔心…首創者是否對我們感到不悅？\n\n但是，我的信念並未動搖。而且正如我所相信，首創者為我們送來了解決的辦法。\n\n是的，就是你。\n\n根據古老的研究文獻，湧泉的源頭來自於魂靈供應區的地底神廟。去吧，我相信你一定能夠恢復泉水。", progress = nil, completion = "&lt;這個自主機遭到吞噬者摧殘殆盡。它的手中緊緊握著某個奇怪的物體。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65350] = {title = "恢復洪流", objective = "找出方法恢復洛克利安魂核。", description = "吞噬者突破了神廟的防禦。這些飢渴的怪物會吞噬它們找到的所有能量，所以它們肯定是被湧泉的能量吸引過來的。\n\n受到了這樣的干擾，難怪水會停掉！\n\n解決的辦法必定就在洛克利安魂核裡面。進去之後，釐清發生了什麼事，看看有沒有辦法修補損害。", progress = "<控制臺散發出強烈的力量。>", completion = "&lt;你的努力有了成果，神廟裡的水開始正常流動，而泉水也應該恢復了。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65351] = {title = "結構圖重新同化：鳴響回音", objective = "把結構圖帶去合適的原靈體熔爐。\n\n已提供物品：\n", description = "<這個結構圖裡面記載著新原靈體造物的建造設計。把結構圖帶去合適的原靈體熔爐，說不定熔爐就能夠為你製作出裡頭記載的生物。>", progress = nil, completion = "&lt;原靈體熔爐在吸入結構圖時發出帶有旋律的音調。&gt;", rewards = "您會學到：\n\n鳴響回音"}
MultiLanguageQuestData['tw'][65353] = {title = "不准吃自主機", objective = "殺死10個入侵的吞食者和現實突破者。", description = "這些吞噬者永無飽足，它們會吞食所有的能量。要是置之不理，肯定會把整個澤瑞斯莫提斯都吞噬殆盡。我們絕對不能讓這些入侵者汙染首創者的造物！\n\n我無力作戰，但是你…也許你正是首創者送來的救星。你願意伸出援手嗎？", progress = nil, completion = "陌生人，我…我得向你致歉。我對你不夠信任，我的信念也因而動搖了。請原諒我，然後收下我的謝意。顯然，首創者在默默引導著你。", rewards = "您會收到：\n\n"}
