MultiLanguageQuestData['tw'][65510] = {title = "雷龍靈魂", objective = "將雷龍靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<雷龍靈魂忠誠而且英勇，你之後能夠隨意呼喚雷龍的化身。>", progress = nil, completion = "啊，是雷龍。你現在可以任意使用這個形態了。", rewards = nil}
MultiLanguageQuestData['tw'][65512] = {title = "異種蠍靈魂", objective = "將異種蠍靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<異種蠍靈魂殘暴而且迅速，你之後能夠隨意呼喚異種蠍的化身。>", progress = nil, completion = "啊，是異種蠍。你現在可以任意使用這個形態了。", rewards = nil}
