MultiLanguageQuestData['tw'][65514] = {title = "犰狳靈魂", objective = "將犰狳靈魂帶給森林之心的丘發。\n\n已提供物品：\n", description = "<犰狳靈魂謹慎而且強韌，你之後能夠隨意呼喚犰狳的化身。>", progress = nil, completion = "喔，是犰狳！這種生物把自己保護得好好的！", rewards = nil}
