MultiLanguageQuestData['tw'][65518] = {title = "蜜蜂靈魂", objective = "將蜜蜂靈魂帶給森林之心的丘發。\n\n已提供物品：\n", description = "<蜜蜂靈魂防禦力強而且速度飛快，你之後能夠隨意呼喚蜜蜂的化身。>", progress = nil, completion = "喔，是蜜蜂！接下來你也能夠像蜜蜂一樣嗡嗡嗡了！", rewards = nil}
