MultiLanguageQuestData['tw'][65563] = {title = "給凱曦的快遞", objective = "把尖刃盔帽送去給凱曦安格弗。", description = "我用了你的材料來製造凱曦拜託我的東西，希望你不會介意。\n\n你願意拿給她嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65594] = {title = "泥水登山", objective = "摧毀3個腐朽圖騰。", description = "愚蠢的腐朽覺得自己是老大，但我才是老大。我們去殺掉它。我把黏液變成朋友了。", progress = nil, completion = "你活了這麼久？好肉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65595] = {title = "一顆爛蘋果", objective = "殺死腐朽根鬚。", description = "腐爛會讓豺狼人挨餓。\n\n腐爛傷害朋友。\n\n我們現在就殺死腐爛。這是大王該做的。", progress = nil, completion = "我會帶領豺狼人更好地打獵。你…還不賴。但豺狼人餓了，你還是肉。\n\n快滾。我不追。", rewards = "您會收到：\n\n滿溢軟泥罐秘法師的黏液條"}
MultiLanguageQuestData['tw'][65606] = {title = "莫魯克名人", objective = "在莫魯凱與亞加莉交談。", description = "你為我們氏族謀取福利的作為，我都看在眼裡。\n\n外來者，回莫魯凱吧。我會備妥一些補給品，協助你進一步與我們合作。", progress = nil, completion = "你的所作所為彰顯了我們的榮耀。我會向長老報告你的事蹟。收下這些補給品，希望對你的狩獵有幫助！", rewards = "您會收到：\n\n裝滿的莫魯克半人馬補給包滿溢莫魯克半人馬補給包"}
MultiLanguageQuestData['tw'][65613] = {title = "經典的龍人造型", objective = "轉化為人形態。", description = "我敢說在你抵達奧格瑪時，你有引起當地居民的注意。一定有些人對你的存在感到比較自在，有些則不然。\n\n在我還是頭年輕的龍時，我選擇了你現在看到的凡人形態。那使我得以成為高嶺的牛頭人的盟友，並生活在他們之間。\n\n雖然你的道路和我的不一樣，然而龍族的本質也在你身上流動，$p。或許那會使你有辦法獲得自己的人形態。\n\n我們一起走吧。", progress = nil, completion = "你確實有個高貴的人形態，&lt;name&gt;。非常顯眼。\n\n我不知道為什麼你的人形態和龍的比起來是如此獨特。或許等我們更了解你的過去時，答案就會自然浮現。\n\n不過在那之前，我們必須為眼前的旅途做準備。", rewards = "您會學到：\n\n人形態\n\n您還會收到：\n\n勇氣半龍人外袍"}
MultiLanguageQuestData['tw'][65615] = {title = "秘法入侵", objective = "調查那個信標。", description = "在我們被囚禁起來的時候，我確定當時還沒有前方那個信標。\n\n法術不是我的專長，可是我認得出那是秘法魔法，就跟育所那頭藍龍使用的魔法一樣。\n\n他說了一個名字…瑪里苟斯。聽起來很熟悉，可是大地守護者教給我們的知識現在都變得好零碎、好遙遠。\n\n假如是這位瑪里苟斯讓我們陷入靜滯，那麼樹立了這個秘法信標的可能也是他。\n\n調查這個區域然後回報。要確定敵方無法使用信標號召增援部隊。", progress = nil, completion = "&lt;埃祖拉瑟專心聽你說著親眼見證的一切。&gt;\n\n所以，另一個育所外面也放著信標。\n\n盟友陷入危機了，我們必須去救他們！", rewards = "您會收到：\n\n赤紅半龍人戰裝頭盔"}
MultiLanguageQuestData['tw'][65625] = {title = "閻獄之主的試煉", objective = "進入托迦司大廳的新傳送門。", description = "淵喉行者！我找了你好久。\n\n據說閻獄之主有新的部隊正在托迦司集結。雖然我不清楚他們要做什麼，但肯定不是好事。\n\n也許你該去終結他們的計畫？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65640] = {title = "原鹿靈魂", objective = "將原鹿靈魂帶給森林之心的莫恩女士。\n\n已提供物品：\n", description = "<原鹿靈魂高貴又睿智。你將來能任意化身為原鹿之形態。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][65649] = {title = "新的交易", objective = "在戰爭模式下，於澤瑞斯莫提斯收集150個原質絲線。", description = "啊，淵喉行者！現在你已經找到了前往澤瑞斯莫提斯的辦法，我們的機會就在眼前。\n\n要不要來談談進一步的商業合作機會？\n\n我們很有興趣觀察這條新的通路所帶來的潛在機會。我相信你能夠取得我們想要的東西。別讓任何人阻擋你的去路。\n\n但如果你不願意，沒關係，要找到別人來解決我們雙方的問題，應該也不會太難。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "破舊的皮束褲宇宙鬥士的縝密決心宇宙鬥士的迴盪決心宇宙鬥士共鳴器宇宙鬥士永恆禦盾您能選擇下列奬勵中的一個：\n\n宇宙鬥士的吞噬詛咒\n\n您還會收到：\n\n榮譽點數"}
MultiLanguageQuestData['tw'][65652] = {title = "團長的召喚", objective = "在銀月城和莉雅德倫女士見面。", description = "你好，<name>。\n\n我們就不拐彎抹角了，銀月城迫切需要你的協助。\n\n奎爾薩拉斯的天譴軍團再度復甦，如果沒有人能抵擋天譴軍團，我們很快就會陷落。我們必須堅守防線！\n\n到血之大廳找我，我們會給你一個完整的簡報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65653] = {title = "辛多雷的勝利", objective = "回銀月城找莉雅德倫女士。", description = "雖然耗盡了三叉矛的力量，但我們勝利了！擊敗沃拉斯後，也許能更容易對付那些天譴軍團了，這都多虧你的協助。\n\n回血之大廳找我吧，銀月城感謝你的英勇付出。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n隱匿翡翠陸行鷹"}
MultiLanguageQuestData['tw'][65655] = {title = "狼之眼", objective = "到提里斯法林地的布瑞爾和卡莉雅‧米奈希爾會面。", description = "感謝我們的間諜，有個驚人的謠言出現了。\n\n被遺忘者正在提里斯法林地集結，不知道他們有什麼目的。值得一提的是，卡莉雅‧米奈希爾也去了那裡。\n\n我們得知道他們打的是什麼算盤，畢竟現在該死的女妖之王已經不是他們的領袖了。\n\n去吧，穿上偽裝滲透他們，看看有什麼發現。所有事都不要錯過，如果有機會獲得他們的信任和獲得更多情報，儘管照他們的要求行動。\n\n請盡快回來報告。", progress = nil, completion = "&lt;卡莉雅仔細看了你一會兒，然後露出微笑。&gt;\n\n你會適應的。不要害怕，我不會把你的事情告訴別人。\n\n但也請你理解，許多被遺忘者曾經是羅德隆的子民，他們想在這裡做特別的事情，我保證，如果你配合並協助他們，這些努力會有所回報的。\n\n艾澤拉斯會變得更好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65656] = {title = "羅德隆的召喚", objective = "到提里斯法林地的布瑞爾和卡莉雅‧米奈希爾會面。", description = "暗影之境逐漸恢復了，現在該來把注意力轉回艾澤拉斯的家園。\n\n被遺忘者在羅德隆王國的廢墟集結。他們想拿回更多提里斯法林地的土地，拋開第四次大戰留下的破壞。\n\n我希望能協助他們。\n\n我也知道對部落而言，我還有很多事情得證明給他們看。來吧，到布瑞爾加入我的行列，我們可以一起幫助被遺忘者。", progress = nil, completion = "我一直很喜歡布瑞爾。\n\n還有很多事得做，但看到這裡的重建工作有所進展，真是令人為之振奮。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65657] = {title = "召集被遺忘者", objective = "召集黑暗遊俠薇蘿娜拉、莉莉安‧佛斯和大藥劑師法拉尼爾。", description = "很開心看到布瑞爾的重建工程已經取得進展，但這只是第一步。首都的廢墟仍然受荒疫影響，至今無法進入。\n\n這就是我希望你們能幫忙的地方。\n\n要恢復這片土地，需要先聚集各式各樣的人，為同樣的目標付出心力。\n\n被遺忘者之中，有幾個影響力大的人物，請幫我召集他們，我們就能當面談談未來該如何前進。", progress = nil, completion = "看來我們已經準備好開始了。\n\n自從…嗯，黑海岸之後，應該沒見過這麼多被遺忘者齊聚一堂了。\n\n但我們現在位於自己的土地，而且也是時候來處理自家的事了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65658] = {title = "捍衛家園", objective = "殺死提里斯法林地的染疫的士兵。", description = "戰爭時擴散的瘟疫已經污染了這片土地、驚擾了死者。也就是說，情勢比以往更加嚴峻。\n\n我們一直在努力重建，但我們的人民身處危險，無法完成工作。\n\n我的首要職責是保護被遺忘者的安全。我會按照卡莉雅的要求和其他人見面，但在這之前，你得先幫我消滅這些染疫者。", progress = nil, completion = "這樣我們的守衛應該就有喘息空間了。這只是比喻啦。\n\n&lt;name&gt;，謝謝你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65659] = {title = "瘟疫集會", objective = "聆聽被遺忘者的話。", description = "我們被遺忘者自從羅德隆毀滅以來，經歷了許多磨難。但我們決心要保護我們的家園。\n\n為什麼我們得放棄自己努力奮鬥的心血呢？\n\n在某方面來說，卡莉雅算是比較新來的，但大家都知道她，畢竟她是阿薩斯的姊姊。\n\n希望我們能向前邁進，而且她能真正協助我們。如果她真的為我們的福祉著想，她能成為強大的力量。", progress = nil, completion = "我以為我的出現可能會引起糾紛，但我很感謝莉莉安的調停，讓我有機會展現我幫助被遺忘者的承諾。\n\n而現在，我必須實踐我的諾言。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65660] = {title = "與信仰同行", objective = "保護護盾內的卡莉雅並收集純粹瘟疫樣本。", description = "我答應過要幫忙，也會信守諾言。我們需要羅德隆瘟疫的純粹樣本，但不能讓任何人處於險境。\n\n跟我一起去吧，我會召喚一道聖光護盾，保護我們深入疫區、順利收集樣本。\n\n我必須全神貫注才能維持這個咒語，相信你能保護我們不受任何外力影響。\n\n你願意一起嗎？", progress = nil, completion = "這種勇氣實屬難得。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65661] = {title = "諮詢盟友", objective = "到瑪卓薩斯和藩侯辛丹談話。", description = "希望卡莉雅對這些瑪卓薩斯領主的想法沒錯，他們知道要怎麼處理這種強大的瘟疫。\n\n我們也只剩下一隻食疫獸了，不過法拉尼爾說他可以複製更多食疫獸，只要牠們的生存力夠強壯的話。\n\n我們去暗影之境吧。", progress = nil, completion = "你帶來了令人不太愉快的例子，展現了瘟疫製造者不受控制和不受拘束的野心。\n\n我相信這個怪物的製造者已經消失了，你想要瑪卓薩斯的家族做什麼事？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65662] = {title = "瘟疫家族", objective = "在瘟疫家族與瘟疫設計者瑪利雷斯見面。", description = "有個瘟疫家族的生還者，擁有你想尋找的知識。你應該已經見過他了。\n\n瘟疫設計者瑪利雷斯的言語或許不太清楚，但是他會知道要怎麼處理你的瘟疫。\n\n去那個殞落家族的廢墟附近找他。記得提高警覺！那裡潛伏了許多生物，可能會在毫無預警的情況下就消滅你。", progress = nil, completion = "哈囉，我親愛的學徒！\n\n你看起來好像有點憔悴，是不是睡眠不足？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65663] = {title = "怪物餵食秀", objective = "殺死瘟疫家族的軟泥和瘟疫屍鵬。", description = "瘟疫家族遭受了磨難，和羅德隆一樣。希望我們在這裡的工作和努力可以修補某些破壞。\n\n但首先，我們必須深入瘟疫家族，才能強化法拉尼爾的食疫獸。\n\n你殺的軟泥或生物都能讓它更堅韌。", progress = nil, completion = "食疫獸看起來變得更強了。大藥劑師法拉尼爾一定會很高興。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65664] = {title = "瘟疫精華", objective = "在瘟疫家族吸收不同混合物。", description = "你的小朋友看起來很餓！別擔心，我知道要怎麼餵飽它。它很快就會長得又大又壯，能吃下所有瘟疫。\n\n附近有各種混合物，能賦予它不同的特性，而且每種顏色都是不同的口味！\n\n我會帶著你給我的瘟疫樣本到瘟疫家族，看看會有什麼發現。到那裡跟我碰面，然後帶你的食疫獸好好飽餐一頓！", progress = nil, completion = "你有看到嗎？你帶來的瘟疫樣本真是太可怕了！\n\n學徒，它打中我的頭，還差點殺死你的朋友。太驚人了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65665] = {title = "具現化", objective = "殺死羅德隆荒疫。", description = "學徒，你帶來的瘟疫真是討厭，做出這東西的一定是個超級虐待狂。\n\n為了研究樣本，我讓它變成實體，結果這個不知好歹的東西卻反過攻擊我，我根本沒惹它！\n\n它在家族裡到處破壞，雖然不樂見如此，但必須快點解決它，否則它會變得越來越強…或越來越大隻。\n\n樂觀一點想的話，如果你的食疫獸能存活下來，它就能順應你那個可怕的瘟疫。", progress = "你解決那個化身了嗎？", completion = "雖然那個樣本給我們造成不少麻煩，但我覺得現在說不定有點希望。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65666] = {title = "返回布瑞爾。", objective = "回羅德隆廢墟外面找大藥劑師法拉尼爾。", description = "我們強化了食疫獸，它現在看起來準備好要飽餐一頓了。\n\n我們回去找法拉尼爾吧。他說他可以複製它的特性，然後把食疫獸分散到整座廢墟裡。\n\n也許，說不定，我們可以再次踏上家園的土地。\n\n來吧，拿著我的爐石回去布瑞爾吧。", progress = nil, completion = "太好了！你不只沒有弄丟我的食疫獸，還把它給帶回來了，而且它長得好強壯！\n\n現在，請見證我這些發明的神奇能力與非凡速度，幽暗城的地表很快就會散佈更多食瘟獸。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65667] = {title = "羅德隆的解藥", objective = "騎上暗影蝙蝠，在羅德隆廢墟部署食疫獸。", description = "時刻已經成熟。以聖光之名，希望我們的計畫能成功。\n\n大藥劑師法拉尼爾的馬車已經複製了很多個食疫獸，蝙蝠也準備好部署它們。\n\n如果你看到有地方災情嚴重，需要我們散播更多治療措施，你可以用信號彈發信號。\n\n到天上去吧，一起結束這場瘟疫。為了羅德隆，也為了被遺忘者。", progress = nil, completion = "我們成功了。我們一起努力清除了地表的致命瘟疫雲。\n\n清理幽暗城的底部區域需要更多時間，但至少有個不錯的開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65668] = {title = "荒寂議會", objective = "見證全新的荒寂議會成立。", description = "結合所有人的知識和專長，被遺忘者恢復了幽暗城的地表區域。\n\n只有拋開彼此的不信任、一同為人民的未來而奮鬥，才能完成這份任務。應該要正式成立議會了。\n\n我們不再是追隨和服從希瓦娜斯‧風行者的不死族。從現在開始，我們是自己的主人，就像當年取回自己的意志一樣，我們也要心懷同樣的獨立意志和驕傲。\n\n我們要迎接嶄新的未來，還有嶄新的領導方式。", progress = "希望和新鮮空氣都回來了。", completion = "真的很榮幸他們能接受我加入被遺忘者的領導議會。\n\n我發誓，我會盡一切努力保護人民，無論他們來自哪裡，或是什麼形式的不死狀態。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65669] = {title = "向葛雷邁恩報告", objective = "將卡莉雅的信送去給奧睿博司的吉恩‧葛雷邁恩。", description = "這歷史性的一刻終於成真，感謝你們的所有協助。\n\n我相信可能有其他人對這裡發生的事有興趣。請你帶這封信和我的祝福回去給他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65674] = {title = "這是什麼？", objective = "把無形體精華帶去流亡者洞穴給法琳。\n\n已提供物品：\n", description = "<你手中的不明精華看起來可以用於許多用途。它簡直散發著無窮可能性。>\n\n<或許法琳能提供更多資訊。>", progress = nil, completion = "凡人啊，這真是有趣的發現。\n\n我在研究過程中有遇過這種素材。理論上，它能改變各種物品的命運…也能說是解放其潛力。很有意思，對吧？\n\n這份精華我要留著，我的研究用得上。作為交換，我能教導你在創造東西時該怎麼利用類似的材料。", rewards = "您會學到：\n\n澤瑞斯莫提斯額外材料\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65680] = {title = "結構圖重新同化：赤心原狼", objective = "把結構圖帶去合適的原靈體熔爐。\n\n已提供物品：\n", description = "<這個結構圖裡面記載著新原靈體造物的建造設計。把結構圖帶去合適的原靈體熔爐，說不定熔爐就能夠為你製作出裡頭記載的生物。>", progress = nil, completion = "非常好。只要有這張結構圖，再加上適當的零件，就有新的曲目可以與你相伴。", rewards = "您會學到：\n\n赤心原狼"}
MultiLanguageQuestData['tw'][65686] = {title = "前往蒼藍高地", objective = "在蒼藍高地與受祝者葛蘭妮亞會面。", description = "你好，<name>！\n\n帕奇娜和我謹代表祈倫托，尋求你們的協助。\n\n祈倫托正努力守護遍布整個蒼藍高地的原始秘法魔法。\n\n藍龍的守護巨龍兼祈倫托領導者，卡雷苟斯，也需要有人幫忙復原那裡的蒼藍誓言石。\n\n如果你願意幫忙，請繼續沿著路前進，就能見到受祝者葛蘭妮亞。\n\n她能告訴你哪裡最需要你的幫忙。", progress = nil, completion = "非常好，有冒險者來了。我可以先和你說明情況，然後我就得去學…釣魚了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65687] = {title = "拳打腳踢", objective = "殺死12個碎界龍人。", description = "其他的追隨者有的…非常惡毒。\n\n<錠塊揉揉他鼻子上的新傷口。>\n\n以前不是這樣的，可是在賽堅諾斯來之後，他說我們應該把力量擺在其他事物之前。現在，大家成天都在打架。\n\n我試過要反擊，可是他們的皮太厚…而我的個子又太小。\n\n但你不一樣！你一定整天在和惡霸打架。或許你可以幫忙？", progress = nil, completion = "那些鱗片沒長齊的笨蛋再也沒辦法傷害任何人了！大地守護者感謝你！\n\n喔。還有我，我也感謝你。", rewards = "您能選擇下列奬勵中的一個：\n\n碎界符咒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65688] = {title = "與卡雷苟斯會面", objective = "取得一袋實用物品，然後去蒼藍文庫的底層見卡雷苟斯。", description = "我們恐怕得分心去處理其他事情，洪荒使者在東邊造成的威脅需要妥善因應。\n\n我請求你代替我去蒼藍文庫一趟，協助卡雷苟斯復原蒼藍誓言石。\n\n你應該帶點補給品，才能因應任何可能的意外。\n\n與我們的傳送門軍需官談談，他應該會有些東西可以派上用場。\n\n祝你好運，<name>。卡雷苟斯一定會很感激你。", progress = "有人來幫忙讓我安心多了。我知道卡德加和其他人一定正忙著應付洪荒使者。", completion = "卡德加很明智，知道需要再次集中心力對付洪荒使者。\n\n好了，我們這裡有很多事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65690] = {title = "教徒的擔憂", objective = "到灼燃棲所找到阿雅桑絲。", description = "昨天有另一個外來者到來。她自稱是紅龍軍團的「特使」，要求覲見我們的首領「奈薩里奧之聲」。\n\n但奈薩里奧之聲突然發狂，他表示，大地守護者正在考驗我們，我們必須處決她！\n\n我知道我們不應該相信外來者，但我們沒必要殺了他們！拜託，幫我救她出來。", progress = nil, completion = "這個小傢伙向你求助？\n\n&lt;阿雅桑絲如釋重負。&gt;\n\n也許我們終究可以拯救碎界使徒。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65691] = {title = "龍翼下的陰影", objective = "迎戰『奈薩里奧之聲』賽堅諾斯。", description = "奈薩里奧之聲就在下方，在他的信徒之間散播謊言。\n\n他看起來是像我一樣的龍裔，可是他的龍語很生疏，一點都不像龍族。\n\n我懷疑他是冒牌的，或許是個幻象。如果我們能制伏他的話，真相肯定會水落石出。", progress = nil, completion = "我們今天撲滅了暮光之錘的最後一塊餘燼。但碎界使徒是另一回事。這些鱗裔會為他們的不幸尋找到新的解釋，建構新的神話，選出新的首領。\n\n我和我的族人會盯著他們。要是又有另一個奈薩里奧之聲崛起，我們就會出手干涉。\n\n你今天做了一件好事。", rewards = "奈薩里奧導魔師節杖黑曜看守者之弩黑曜守護者斬斧黑曜法術裂斧末日預言者巨劍黑爪之爪暗鱗雙刃黑爪之刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][65700] = {title = "核心控制", objective = "調查流亡者洞穴外的奇異生物。", description = "你來的時機正好。\n\n我的陷阱似乎就在剛剛捕捉到很奇異的生物。我不敢單獨調查，但你…你能幫我。\n\n把波克波可帶去。說不定還有我們沒發現的秘密。", progress = nil, completion = "波克波可真的很神奇吧！不知道他究竟有多少能耐。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65702] = {title = "逼瘋", objective = "找回40份不穩定的秘法能量。", description = "蒼藍文庫過去是藍龍聚在一起討論魔法的地方。\n\n現在這裡卻只剩下我一隻藍龍。\n\n這個地方控制著蒼藍高地地底的地脈，只是文庫本身和文庫的僕人都失控了。\n\n我相信，只要讓這個地方恢復正常，我就能順利復原蒼藍誓言石。\n\n傀儡和元素都充滿了不穩定的秘法能量，這些能量都需要重新導向。\n\n摧毀他們，想辦法收集不穩定的秘法能量。", progress = "對大部分的守護者來說，文庫不斷處在一種重新創造的狀態。我們需要修正它的流動。", completion = "做得非常好。光是移除這麼一點不穩定的秘能，這裡的造物已經得到了安撫。", rewards = "您會收到：\n\n烈風迅疾龍：尾巴有鰭強能秘法水晶"}
MultiLanguageQuestData['tw'][65703] = {title = "暗影之境(60)E", objective = "完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][65704] = {title = "暗影之境(60)E", objective = "完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][65705] = {title = "暗影之境(60)E", objective = "完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][65709] = {title = "修整秘法", objective = "從一袋實用物品中找出地脈權杖，然後用它修復2座平台。", description = "我們得先疏理這裡失控的地脈能量，不然無法啟動蒼藍文庫裡的誓言石。\n\n控制誓言石的三枚龍符文當中，有兩個因為不穩定的秘能而發生故障。\n\n很抱歉，由於卡德加分身乏術，再加上這裡沒有其他藍龍，因此只能由你來做。\n\n在你的那袋實用物品中，應該有地脈權杖。\n\n請用權杖修復附近的符文。", progress = "這個地脈權杖應該能讓你好好調整並設定附近的符文。", completion = "做得非常好。看來這些符文能把我們送到文庫的上層了。\n\n我認為，現在僅剩的問題就在那裡…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65711] = {title = "救出莉茲", objective = "在凱汗營地殺死風暴抽取者，並救援雷脊蜥蜴莉茲。", description = "是你！感謝雍亞拉。我剛剛正在裝病，打算騙過下一個闖進來這裡的蠻卒。呃…那些舐蹄者對我施放了某種束縛法術。我自己可以解開。\n\n他們把莉茲抓到洞穴裡面，拜託救救她。我會想辦法自救。\n\n去做你得做的事吧。", progress = nil, completion = "&lt;菈迪亞看著被折磨的野獸，異常地安靜且微微顫抖。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65717] = {title = "重要動機", objective = "把年鑒的回音帶去流亡者洞穴給法琳。\n\n已提供物品：\n", description = "<有個小東西吸引了你的目光。它閃耀著創先者的魔法，雖然古老，但卻異常精緻。>\n\n<這個裝置發出輕柔的震動和音調，不斷重複，簡直就像在…說話一樣？>\n\n<法琳對這東西一定會很有興趣。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n蟹化澤瑞斯戰騎的碎形暗語"}
MultiLanguageQuestData['tw'][65725] = {title = "鑽地原蟾", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
