MultiLanguageQuestData['tw'][65732] = {title = "有耐心的原蟾", objective = nil, description = "看啊，又一個澤瑞斯莫提斯的美麗生物！看牠的眼神這麼靈活，我覺得牠一直都在玩弄我們。\n\n但耐心終究有了成果。布德會很高興。\n\n淵喉行者，做得好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n有耐心的原蟾"}
MultiLanguageQuestData['tw'][65735] = {title = "懸賞：卡司托斯", objective = "消滅卡司托斯。", description = "有個原本穩定的自主機出現了不尋常的故障跡象，開始攻擊朝聖者之澤外面路上的受啟迪者。\n\n對我們的朝聖者而言，維持道路安全相當重要。\n\n拉弗克已經把殲滅此威脅列為最高優先等級。", progress = nil, completion = "我不清楚它為何會有這種行為，但沒了它以後我們一定會比較安全。這個獎勵可以讓你開始取得某些我的優質裝備。", rewards = "您會收到：\n\n靈魄矩陣"}
MultiLanguageQuestData['tw'][65748] = {title = "你做出了貢獻", objective = "從澤瑞斯莫提斯的寶箱、儲藏箱、聖物以及其他容器中找到10個受啟迪的補給品。", description = "我能提供裝備，是因為有首創者的祝福…和許多旅行者努力的成果。\n\n我們每個人都要為了後來的人做出貢獻。\n\n收集你在澤瑞斯莫提斯探索時找到的補給品。把眼睛放銳利一點…它們可能藏在奇怪的地方。把東西帶回來給我，我會把它們轉交給之後的旅行者。", progress = "你有什麼發現了嗎？", completion = "旅行者，你好啊！你找到什麼了？啊，這可以幫助許多其他的旅行者。我要感謝你，他們也會感謝你的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65749] = {title = "裝備的必要性", objective = "收集法琳的研究筆記，把筆記交給拉弗克。", description = "我和我的同事拉弗克分享研究成果有一段時間了。唯有靠我們分享成果，他才能獲得有用的物品。\n\n把我的研究筆記交給拉弗克，看看你能不能讓他對你有好感。一旦時機成熟，他應該可以協助你取得更好的裝備。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n砂蝕聖物"}
MultiLanguageQuestData['tw'][65750] = {title = "八腳怪", objective = "在顫網谷殺死10個顫網伏行蛛或顫網爬行蛛，以及3個洪荒使者馴蛛者。", description = "<class>！\n\n要是你願意的話，我需要你的幫助…\n\n這個聯合遠征隊的目的是研究棲息在這個區域的獨特蛛形生物，不過如你所見，我們的計畫出了差錯。\n\n我們原先以為會是演化適應的現象，實際上卻是洪荒使者對自然秩序的扭曲。\n\n我一向很重視我身為保育學家的職責，不過現在已經不是研究活體的好時機了。我們不能讓被他們扭曲的生物擴散出去，我們事情結束之後再研究牠們的屍體。\n\n你願意幫我們嗎？", progress = nil, completion = "雖然殘忍，卻不得不這麼做，我們不能讓牠們擴散出去。\n\n我想我們已經從牠們身上得到所有必要的情報了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65751] = {title = "平台調整", objective = "在蒼藍文庫頂端驅散3道不穩定的秘法能量。", description = "看來最後的秘法干擾就在上面。\n\n我會繼續調整地脈能量。使用你回收的秘能，解除這裡的干擾。", progress = nil, completion = "做得很好！我可以感受到，這裡底下的地脈開始癒合了。我們快要成功了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65752] = {title = "秘法煩擾", objective = "殺死6隻吸能龍鰻。", description = "大量的法力龍鰻正在吸食源自文庫的原始秘法魔法。\n\n它們吸食的數量太過龐大，導致地脈失去平衡…我們也因此無法復原蒼藍誓言石。\n\n我會使用你收集的不穩定的秘能，凝成類似鉤子的東西。\n\n請用它來殺死龍鰻。我應該能趁牠們吸食量暫時減少的這段時間，在下面調整能量。", progress = nil, completion = "等到這一切結束後，祈倫托一定會妥善保存這些文檔。感謝你的協助。", rewards = "疾風捲兜帽變形皮甲兜帽刺藤鍊甲頭盔霰耀顱甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][65758] = {title = "探險者葛朗吉", objective = "找到葛朗吉‧鐵口。", description = "<name>！跟我合作的探險者協會成員叫葛朗吉‧鐵口，他不在獲救的行列中。他原本已經努力獲得自由，可是在看到逃出來的人很少時，他立刻轉身往回走了！而且是自己一人！\n\n那個呆瓜雖然勇敢但也很衝動，而且不應該遭受到這樣的命運。\n\n拜託你，去找他吧！", progress = nil, completion = "能見到一張擁有正確眼睛數量的臉真開心！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65760] = {title = "前來報到", objective = "跟隨仙卓克絲前往龍心哨站。", description = "我以前只有在書中看過加拉登。\n\n龍族的古老死敵，擅長操控大地和熔岩的強大巨人…一心一意想將龍族殺到滅絕。\n\n<仙卓克絲皺起眉頭，看著遠處的火山。>\n\n我的老師說過，自從龍族離開後，他們就在大地深處沉睡，再也沒人見過他們。\n\n要是他們已經甦醒，群島上的所有幼龍都會有危險！\n\n跟我來，我們去找龍心哨站的指揮官萊薩納克。", progress = nil, completion = "任何援兵我都用得上。\n\n我們必須趕快行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65761] = {title = "比想像中更多冒險", objective = "與戈多洛托合作，找到並拯救菈迪亞。", description = "<戈多洛托的眼神十分銳利，充滿責難。她恫嚇你。>\n\n<也許歐胡納鷹可以幫你找到菈迪亞，並救她出來。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65762] = {title = "首創者聖塚 - 沉重的王冠", objective = "在傳奇難度的首創者聖塚中，從安杜因那裡收集4塊劍刃碎片。", description = "安杜因的劍和閻獄之主有強大的連結。如果我們能拿到這把武器的碎片，我就可以打開通道，直通小國王的所在地。\n\n只要收集到四塊碎片，應該就可以永久破除閻獄之主對安杜因的控制。", progress = "收集四個劍刃碎片，就能讓我們直接前往他那裡。", completion = "這應該能讓我們直接前往安杜因的所在地。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65763] = {title = "首創者聖塚 - 沉重的王冠", objective = "在英雄難度的首創者聖塚中，從安杜因那裡收集4塊劍刃碎片。", description = "安杜因的劍和閻獄之主有強大的連結。如果我們能拿到這把武器的碎片，我就可以打開通道，直通小國王的所在地。\n\n只要收集到四塊碎片，應該就可以永久破除閻獄之主對安杜因的控制。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65764] = {title = "首創者聖塚 - 沉重的王冠", objective = "在普通難度的首創者聖塚中，從安杜因那裡收集4塊劍刃碎片。", description = "安杜因的劍和閻獄之主有強大的連結。如果我們能拿到這把武器的碎片，我就可以打開通道，直通小國王的所在地。\n\n只要收集到四塊碎片，應該就可以永久破除閻獄之主對安杜因的控制。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65768] = {title = "我們的前線斥候", objective = "與澤瑞斯莫提斯的前線斥候交談。", description = "雖然閻獄之主的部隊掌控著澤瑞斯莫提斯絕大多數的地方，但他們並非唯一的威脅。\n\n我派出了斥候到週邊的地區巡邏，調查是否有其他的潛在威脅。\n\n去和每個斥候談談，聽取他們的調查結果。收集這些偵蒐情資，然後回來向我彙報。", progress = "你有什麼發現嗎？", completion = "這些情報有助於規劃下一步的行動。淵喉行者，多謝了。", rewards = "聖歌束帶斷音腰帶聖歌腰鍊簧風琴束腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][65769] = {title = "寒冰絲網", objective = "在顫網谷解救6個繭縛的生存者。", description = "在蜘蛛和牠們的洪荒使者主人攻擊的時候，許多我的朋友和同事都被抓走了。\n\n我看到他們被冰凍的蛛網纏住後拖走了，我都不敢想像他們的下場。\n\n拜託你了，想辦法解救他們吧！", progress = nil, completion = "謝謝你，&lt;name&gt;。我擔心我再也見不到他們任何一人了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65770] = {title = "一諾千金", objective = "向學徒菈迪亞保證會幫她保密。", description = "動物覺得待在你身邊很自在。這代表你是個好人。\n\n老實說…你能不能幫我保密？我想把你介紹給我朋友，其他人都不知道她的存在。\n\n你必須先向我發誓，你會保密這件事。要是我的導師發現的話，她一定會把我逐出平原。", progress = nil, completion = "&lt;托苟曾的歐胡納鷹注視著你。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65771] = {title = "首創者的眷顧", objective = "在大草原四周點燃受啟迪者薰香。", description = "閻獄之主的手下對我們發動了攻擊，這是一個徵兆！過去，我們之中曾有人試圖追尋首創者的禁忌知識，因而招來首創者的憤怒，害我們失去原本擁有的保守。\n\n我們必須為同胞的僭越之舉贖罪。\n\n收下這個薰香。到草原上點燃它，為首創者獻上我們的懺悔，祈禱我等罪人能獲得他們的原諒。", progress = nil, completion = "願首創者接受我們的懺悔，原諒我們的僭越之罪。\n\n淵喉行者，謝謝你。", rewards = "您會收到：\n\n時光神秘護足時光數符手甲重建秘語之握時光神諭護腕受啟迪者"}
MultiLanguageQuestData['tw'][65772] = {title = "必要的物資", objective = "在大草原和周邊的區域，從原鷹、原鹿和原狼身上收集15份蛋白質。", description = "淵誓者的攻擊行動和你們的出現，讓我們的糧食供應出現短缺。我並不樂見如此，但最直接的解決辦法就是從周遭的野生動物徵集我們欠缺的資源。\n\n很遺憾事情變成這樣，但我們還是得這麼做。去獵殺一些野生動物，幫助我們補充糧食。", progress = "你帶回我們需要的補給品了嗎？", completion = "謝謝，我們非常感激你的付出。", rewards = "您會收到：\n\n重建神秘護足重建數符手甲時光秘語之握重建神諭護腕"}
MultiLanguageQuestData['tw'][65773] = {title = "單人任務", objective = "完成5回單人隨機戰鬥。", description = "是時候讓你獨自證明自己的本事了。\n\n有個機會可以延續衝突，但必須由你獨自來完成。有時候你得跟敵人一起戰鬥才能知己知彼。這似乎是個好機會。\n\n祝你好運。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n多功能靈魄容器榮譽點數征服點數"}
MultiLanguageQuestData['tw'][65774] = {title = "育籃覺醒", objective = "前往滋長花園使用造物育籃。", description = "冒險者，你有感覺到嗎？滋長花園上方高處的造物育籃充滿了新的能量。\n\n這股力量能改造世界。你必須立即前去控制。", progress = nil, completion = "你手中現在握有造物的力量。", rewards = "您會收到：\n\n宇宙靈流"}
MultiLanguageQuestData['tw'][65775] = {title = "單人戰略", objective = "完成15回單人隨機戰鬥。", description = "你活過了戰鬥的考驗。\n\n不過，我覺得還是有進步的空間。再去試一次。\n\n結束後再回來找我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n多功能靈魄容器榮譽點數征服點數"}
MultiLanguageQuestData['tw'][65778] = {title = "嘯翔帶餐聚會", objective = "穿上你的偽裝，並對巢母的私人主廚使用原型「蛋」。", description = "<name>，準備好發揮你精湛的演技了嗎？\n\n什麼？你沒有任何演技可言？還好，我用你剛剛收集的所有材料做了這個無懈可擊的嘯翔偽裝給你！\n\n賽佳莉亞跟我還需要一點時間才能完成那顆用來殺死巢母的最後的「蛋」，不過我已經做了一個小型的原型試用版，可以讓你在主廚身上測試。\n\n而且不要擔心！身上有這麼多的羽毛，你的安全性足足提高了12%！", progress = nil, completion = "你做得很好，除此之外，在那件服裝裡也挺好看的！\n\n終於準備好要把這可怕的威脅一網打盡了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65779] = {title = "進入平原", objective = "到雍亞拉平原與席卡斥候會面。", description = "綠龍軍團已經返回他們在附近平原的花園。雅立史卓莎希望你能和『夢境之龍』麥琳瑟拉聯絡。\n\n那些平原上的半人馬是凶猛的獵人。要抵達翡翠花園，你必須先和他們建立外交才行。\n\n記得尊敬他們，但別暴露弱點。", progress = "<托姆爾上下打量你，眼神略帶好奇。>\n\n有事不妨直說。", completion = "那你的身分是龍的使者囉。時代真的變了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65780] = {title = "證明自己", objective = "殺死熾炎元龍。", description = "來自龍族的禮物或許可以讓一些半人馬覺得驚豔，不過席卡氏族還是必須看看你的狩獵能力。\n\n我們的一支狩獵隊伍剛把一頭帶有烈焰之力的元龍打下來。請幫忙殺掉元龍，證明你的能耐。", progress = nil, completion = "我看走眼了。你的確是個強大的戰士。", rewards = "半人馬騎兵軍刀席卡釣魚弓雍伊爾儀式權杖秘法師風刃雍亞拉巨劍鷹擊長矛您會收到：\n\n"}
MultiLanguageQuestData['tw'][65782] = {title = "鎖頭與鑰匙之下", objective = "取得碎界牢籠鑰匙，釋放阿雅桑絲。", description = "當我們聽到死亡之翼教團的謠言時，管理者瑟利思特拉命令我將這些從前的鱗裔帶回去。我們希望那單純是誤解。\n\n顯然，我們錯了。\n\n必須要解決他們的首領。不過我得先離開這個牢籠。找到鑰匙並帶來給我。", progress = nil, completion = "我或許曾蒙受牢獄之災，但碎界使徒沒有徹底跟暮光之錘同流合汙。這就讓我覺得很慶幸了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65783] = {title = "歡迎來到我們的營火", objective = "到木階哨站與斥候托姆爾會面。", description = "你與我們的獵人並肩作戰，獲得坐在營火旁的資格。\n\n我們的可汗正位於我們在沼澤的狩獵據點，為我們即將離開的商隊做準備。我會告訴她你的來意。\n\n你一定找得到路的。", progress = nil, completion = "你們外來者似乎老是喜歡管別人的閒事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65784] = {title = "水獺那邊", objective = "帶3隻巨大的河獺回到艾拉格氏族。", description = "在東北邊的河岸底下，有著錯綜複雜的水獺地道。河流中有豐沛的食物，讓有些水獺的體型變得極為巨大。\n\n出於尊敬，我不會要你獵殺這些美麗的生物。相反地，我希望你把它們活著帶回來，我們會把它們當成聖獸一樣好好照顧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮頭盔巨獺毛皮馬褲巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者纏手雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄護手\n                            顯示 8 更多                        龍鑄束腰龍鑄臂鎧紋刻矛頭平原之息席卡女獵手的箭頭可汗禁衛之血巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][65788] = {title = "與幽魂同行", objective = "在羅德隆的王座廳和卡莉雅談話。", description = "收復這些廢墟，對被遺忘者來說意義重大。尤其是戰爭結束後，我們的人民需要精神支柱，才能繼續前進。\n\n我看到卡莉雅往王座廳的方向過去了。那個地方對她來說有很多回憶，就像鬼魂一樣纏繞不去。\n\n我們應該去看看她。", progress = nil, completion = "謝謝你，&lt;name&gt;。你幫了我們很多忙。\n\n從現在開始，我相信被遺忘者會重建並鞏固自己的身份。我們不只是羅德隆的先人，也是這片土地的子民。我很自豪能與他們同在。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65789] = {title = "河流沉睡之處", objective = "到泥木沼池收集施法材料。", description = "泥木那裡有重要的施法材料，經常用來與先祖溝通。只可惜，淤鰭部族佔據了那個地方，讓我們很難去那裡搜尋材料。\n\n如果你能去沼地裡摘一些花朵，再順便收集淤鰭特有的資源，我會非常感激。", progress = "你全部找到了嗎？", completion = "我十分感謝你。這些將受到妥善運用。", rewards = "您會收到：\n\n鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索巨獺毛皮頭盔巨獺毛皮馬褲巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔\n                            顯示 7 更多                        龍鑄腿甲龍鑄束腰紋刻矛頭平原之息席卡女獵手的箭頭可汗禁衛之血巨龍群島補給品"}
MultiLanguageQuestData['tw'][65791] = {title = "生命守縛者的職責", objective = "在晶紅誓言石旁和雅立史卓莎會面。", description = "生命之池很快就會再次盈滿。\n\n謝謝你的參與，<name>，我心中的感激難以言喻。\n\n去吧，到誓言石那邊找生命守縛者。告訴她，我們準備好迎接龍蛋了。", progress = nil, completion = "所有龍族的未來現在都安全了。", rewards = "您能選擇下列奬勵中的一個：\n\n生命之賜紅寶石\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65792] = {title = "加倍奉還", objective = "與托路金一起殺死10隻岩牙獸。", description = "幾天前，托莉奇宣稱她在沒有任何幫助的情況下，獨力殺了岩牙獸。有鑑於我們的靈魂相互連結，我不想說她是騙子。所以…\n\n我要向她證明，向大家證明，我比她更厲害！最近的岩牙獸位在這裡的東北方，我們在那裡碰面！", progress = nil, completion = "這件事會讓氏族談論好幾個星期！", rewards = "您會收到：\n\n鈷藍看守者法衣鈷藍看守者裹手鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮之握巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者纏手雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄胸甲\n                            顯示 13 更多                        龍鑄護手龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣雍亞拉馴鷹者腰帶紋刻矛頭平原之息席卡女獵手的箭頭可汗禁衛之血巨龍群島補給品巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][65793] = {title = "黑龍貨運", objective = "護送龍蛋前往生命之池。", description = "隨著誓言石再次充滿力量，我們得將黑龍族的未來運送到生命之池，每個巨龍軍團的成員都有這樣的權利，讓這裡的水孕育他們的龍蛋。\n\n很不幸的是，由於我們已經暴露了行蹤，敵人一定會密切監視天空的動靜。為了躲過他們的耳目，我們最後一段旅程最好改以地面徒步的方式完成。\n\n到黑曜壁壘附近和我會面，<class>。生命守縛者的勇士，很高興你能和我們一起同行。", progress = nil, completion = "你的付出令人讚賞，&lt;race&gt;。", rewards = "遠征隊研究員裹帶遠征隊守衛護臂遠征隊傭兵護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][65794] = {title = "守護龍族", objective = "見證黑龍蛋重入生命之池。", description = "感謝你，<class>。同時我也很抱歉，你必須應付那兩位那麼久。\n\n紅龍軍團負責保存和培育所有的真正龍族，即使是偶爾會使我們厭煩的也不例外。\n\n如今黑龍軍團的龍蛋終於也回到這裡，龍族在過去萬年之間從沒未如此團結過。我們的使命總算達成，這應該能夠再次修復晶紅誓言石。\n\n當你準備好將龍蛋送往黑曜生命之池的時候，就來和我說一聲。", progress = nil, completion = "生命之池總算又滿是龍蛋，你的功勞不容忽視。\n\n誓言石也再次閃耀，象徵我們不負職責達成了使命。", rewards = "遠征隊研究員兜帽遠征隊傭兵頭盔田野偵查員盔帽遠征隊守衛頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][65795] = {title = "平原的下一步", objective = "到晶紅鱗哨站與陶拉莎大使會面。", description = "綠龍軍團現在需要你的援助，英雄。我姊妹的女兒和她的夥伴進入了翡翠夢境，嘗試強化他們自己的誓言石。不過，自從他們開始沉睡之後，我們已經一陣子沒有聽到任何新的消息。\n\n去找統治雍亞拉平原的半人馬。想要喚醒綠龍，你可能會需要借助他們的力量以及那塊土地的精魂。\n\n他們既高傲又極度重視捍衛領土，無法容忍任何羞辱。去和我們的大使談話，他會為你做好準備的。", progress = nil, completion = "你和我有許多事情要談。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65796] = {title = "最好的防禦…", objective = "殺死『碎牙者』席雷娜。", description = "我們的下一條路要穿過諾庫德的地盤。在過去，我們與他們的氏族關係不好不壞，不過現在情況改變了。\n\n如果我們不先展開行動，就等於讓敵人來決定我們的生死。我的斥候回報說，發現他們的其中一個將領出現在龍族集合地附近。直接向她主動開戰，別讓她有機會召集部隊、在我們移動時偷襲我們。", progress = nil, completion = "謝謝你，這樣我在我們為這場旅程做準備的時候會安心一點。", rewards = "您會收到：\n\n巨龍群島補給品"}
MultiLanguageQuestData['tw'][65798] = {title = "見機行事", objective = "在諾庫德大道取回武器並殺死諾庫德部隊。", description = "席卡氏族已經在北方形成一道對抗諾庫德族的進攻前線。雖然我不喜歡降格去拾荒，可惜的是，這對我們的補給品來說是必要之惡。勇敢前去戰場並帶回武器，我就會為你的努力提供獎勵。\n\n如果你可以把這樣的努力集中在諾庫德族的攻擊線上，或許祖先審判我時就不會那麼嚴厲。", progress = "武器會是最有用的東西。如果讓你覺得為難，我很抱歉。", completion = "祖先請原諒我。要是我更有能力，我們就不需要降格到用這種有疑慮的方法來取得資源。", rewards = "您會收到：\n\n鈷藍看守者法衣鈷藍看守者之索巨獺毛皮之握巨獺毛皮束帶雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者纏手雍亞拉馴鷹者繫腰龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄束腰巨獺毛皮外衣\n                            顯示 12 更多                        塑鋼師的黑曜錘迅疾龍骨錘靈巧戰戟諾庫德穿刺長戟灼熱蠍尾獅烙鐵莫魯克戰旗掠奪者尖嘯之刃紋刻矛頭平原之息席卡女獵手的箭頭可汗禁衛之血巨龍群島補給品"}
MultiLanguageQuestData['tw'][65801] = {title = "彼此介紹", objective = "向席卡氏族的成員介紹你自己。", description = "<桑索克可汗比著手語，歐奇爾隨即為可汗發聲。>\n\n像你這樣的外來者上次來我們的土地已經是好幾世代前的事了。現在洪荒使者在我們的土地上到處遊走，散播禁忌魔法，我的族人當然非常警戒。\n\n如果你想要和我們同行，就必須讓大家認識你。向我的氏族成員介紹你自己吧。", progress = nil, completion = "其他參加的氏族成員稍早已前往莫魯凱為場地做準備。從這個哨站出發的商隊會是最後一個抵達的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65802] = {title = "旅程補給品", objective = "在木階哨站周圍收集5份營地補給品，在附近的樹林收集4個野花莢。", description = "<桑索克可汗比著手語，歐奇爾隨即為可汗發聲。>\n\n在你和我們同行時，你必須盡一份力。戈洛克最近一直肆無忌憚地掠奪我們的醫療用品，所以我們得補充庫存。到哨站附近去收集橘色花朵，這樣我們才能做更多膏藥。\n\n哨站附近也有補給品，需要有人把它們拿到商隊去。在你到外頭去的時候，我希望你能收集它們。\n\n等到你收集齊了，就交給托姆爾。", progress = "如果沒有拿到商隊的補給品，就別來煩我。", completion = "&lt;斥候托姆爾看向收集的補給品。&gt;\n\n一切似乎都就緒了。", rewards = "諾庫德劫奪者護腰席卡斥候扣環蹄萊看守者腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][65803] = {title = "往城市出發", objective = "與席卡的商隊同行，前往漫遊者草原。", description = "舉行庫拉爾時，不同氏族會一起討論事情，分享故事。雖然平原上散居著很多半人馬氏族，不過我們全都是莫魯克。\n\n車隊隨時都能出發。因為前往莫魯凱的路途有點遙遠，所以途中會休息一下。\n\n等你準備好出發時，就到車隊找我。別讓我們等太久。", progress = nil, completion = "喘口氣吧，兩條腿的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65804] = {title = "為了食物和競爭者", objective = "到漫遊者草原，從野生動物身上收集30份新鮮的獸肉。", description = "莫魯克會從平原各處聚集而來，參加庫拉爾，而這個聚會會持續好幾天的時間。\n\n要餵飽那麼多半人馬可不是容易。席卡氏族的獵人會為所有共享的聚餐提供肉品。在前往莫魯凱的路上進行狩獵是我們的傳統。\n\n這時候你也要出點力。", progress = "年輕的半人馬都很易怒，也很固執。記得別讓他們給你難堪。", completion = "你的狩獵方式和戰鬥方式都很奇特。希望亞魯和蓓莉卡能從你身上學到一、二招。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65805] = {title = "連上雍亞拉", objective = "從河岸收集4份河川蘆葦、8簇鳥禽尾羽和1個薩曼瑟螈心臟。", description = "這裡的風變得更加不安，<name>。雍亞拉正在求救，我必須回應她的呼喚。\n\n我需要一些施法材料才能舉行儀式：生長在河岸的蘆葦、綠頭鴨的尾羽，還有薩曼瑟螈的心臟。去河邊收集這些材料，讓我能夠傾聽她的聲音。", progress = "雍亞拉的聲音似乎轉瞬即逝。我們必須快點行動。", completion = "太好了。我會利用這些東西來解讀她的歌聲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65806] = {title = "莫魯凱", objective = "進入莫魯凱。", description = "<桑索克可汗比著手語，歐奇爾隨即發聲。>\n\n莫魯凱就位在這片林地的後方，依山而建。我們的旅程即將結束。\n\n庫拉爾對莫魯克來說是一個休戰的時期，可是雍‧賽希騰的預言令人擔憂。我們必須保持警覺。", progress = nil, completion = "歡迎來到莫魯凱。", rewards = "您會學到：\n\n莫魯克半人馬名望\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65832] = {title = "矮人防凍劑", objective = "找到6瓶矮人防凍劑。", description = "我遇到了一點小麻煩，$U小夥子:小姑娘;。洪荒使者那群舔冰塊的渾蛋把我困在這塊巨大的冰塊中，我還沒凍成冰塊的唯一原因就是我私藏的好貨。\n\n可惜的是，有個混蛋小偷突襲了我，偷走了我藏得沒那麼好的貨，現在我已經快沒了！\n\n你可不可以幫幫我這矮人，幫我拿幾瓶防凍劑來，不然我的血液就要結冰啦。\n\n噢，還有啊，$U小夥子:小姑娘;，如果你不得不從蜘蛛的重要部位取出來，千萬別告訴我。我寧願被蒙在鼓裡。", progress = "我的小指都要凍僵啦！", completion = "感謝麥格尼！這能保持我的血液不被凍結，直到冰塊融化。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65833] = {title = "洪荒使者破壞行動", objective = "取回三位喚霜者的符石。", description = "洪荒使者不斷地把元素寒冰注入蜘蛛體內，還把牠們當作突擊部隊，想要突破龍族在高地的防線。我們不能讓他們得逞。\n\n那三個看起來冷冰冰的傢伙就是老大。把他們殺了，然後把他們用來集中原始魔法的符石帶來給我，我們就可以試著切斷那股流動的力量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65834] = {title = "殺死女王", objective = "殺死顫網蛛后。", description = "就是這樣！一點正規教育、一點聰明的猜測、然後再把符文重刻一下，我們就做出魔法抽出器啦！還是叫反注器？還是吸取器？\n\n隨便啦！我可以確定的是，我們這樣做一定會讓那個蛛后不開心。如果我們想要阻止這場威脅，就必須除掉她。捏死小隻的只能減緩牠們的擴張，你必須從源頭消滅牠們才行。", progress = nil, completion = "是的，這樣應該會打亂他們的計畫。\n\n現在，只要再…用力…推…", rewards = "您會收到：\n\n顫網蛛卵"}
MultiLanguageQuestData['tw'][65836] = {title = "風暴現身", objective = "到睿冠松林與瓦杜會合。", description = "<瓦杜輕鬆地站了起來，彷彿他的傷已經好了。>\n\n我…我把裂片插進自己身體，然後再也不痛了。我感覺很好，好極了。非常好。\n\n歐雷克還沒回來，一定是出事了。他當初不該拋下我自己去！", progress = nil, completion = "不！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65837] = {title = "松林的麻煩", objective = "在雍亞拉平原的松木崗哨和哨兵歐雷克談話。", description = "席卡高地發生了一場洪荒使者攻擊。\n\n如果你有相關情報，或是覺得自己可以幫上忙，就前往松木崗哨去找歐雷克。告訴他，你是我派去的。<特然輕笑。>我真希望塵蹄還記得我。\n\n記得沿著道路走，$p。在這麼多改變發生後，平原不像以往那麼平靜了。", progress = nil, completion = "特然？他還是像匹野馬一樣跑來跑去，對吧？\n\n感謝你前來。任何幫助我們都來者不拒。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65838] = {title = "突破蕨皮", objective = "調查蕨皮谷外圍。", description = "如果這裡的豺狼人發現了腐朽魔法，就代表地脈和這片土地本身都面臨重大危機。\n\n我的鏡像現在不太穩定，無法承受森林裡面的元素干擾。請進入森林調查腐朽之息的源頭。\n\n我會跟我們的巨牙海民新朋友合作，找到一個可以維持鏡像的地方，與你在更深處會面。\n\n我們必須阻止這一切！", progress = nil, completion = "你最好遮住口鼻，你不會想吸到這種腐朽之息的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65841] = {title = "停止擴散", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65842] = {title = "繳械之舉", objective = "除掉武器大師沃達珂並收集15件碎界武器。", description = "我對那些碎界使徒一點好感都沒有。他們冥頑不靈深信死亡之翼總有一天回歸，而且不願協助我們守護黑曜王座。\n\n武器大師沃達珂曾經發誓效忠黑龍王子，結果卻偷走了很多在黑曜龍堡製作的武器，轉交給碎界使徒。我不能容許這樣的竊賊、不能容許這等背叛。\n\n前往悶燃之巔取回那些武器…必要時亦可動武。", progress = "你拿到武器了嗎？", completion = "做得好。這些武器總算拿回來了。\n\n這肯定不會是我們與碎界使徒之間的最後一次衝突。面對認為死亡之翼會再次回歸的瘋子，絕不能跟他們講道理。", rewards = "您會收到：\n\n耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮馬褲\n                            顯示 47 更多                        巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊擊聲天賜穿刺席卡刺矛精確校準的手持火砲灼熱蠍尾獅烙鐵莫魯克戰旗雍亞拉馴鷹者腰帶戰痕纍纍的鱗片血腥戰騎串刺翻騰的熔岩投擲手鬥棍精緻刮鱗小刀伊斯卡秘法師斬潮錘長者的螢光長棍深海獵人之弩瘤刺弓熔火拳師之拳蒼藍秘法增幅器生命烈焰之瓶夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][65844] = {title = "切除腐化", objective = "殺死5個腐敗樹人和10個蕨皮擲腐者。", description = "這些豺狼人的大腦還有身體一定早就腐朽了！\n\n儘管豺狼人只會到處破壞，但他們跟我們一樣，都是這片土地的原住民。\n\n不過，我們已經看到他們把腐朽散播到大樹部族。照這樣下去，他們會吞噬整個高地，走向自我毀滅。\n\n我們不能讓這種事發生。雖然很殘忍…但他們留不得。", progress = nil, completion = "豺狼人是很有意思的生物！他們並不邪惡，只是有點野蠻。而且非常笨拙。\n\n殺死他們不是什麼光榮的事，不過放任腐朽不管對大家都沒好處，而且不能讓他們傷害我們的家人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65846] = {title = "發臭脈能", objective = "在蕨皮谷外圍收集7顆脈能水晶。", description = "地脈就在這裡，我感覺得到！\n\n不過，我們必須先阻止豺狼人。那棵古樹一定是他們的王牌。\n\n豺狼人已經收集了一些脈能水晶。幸好，他們似乎還不了解水晶蘊藏的力量。\n\n請把水晶帶來給我，越多越好。水晶可以強化我的鏡像，還能讓我從文庫召喚一些有用的東西，用來打倒那個怪物！", progress = "很抱歉，我現在這個形態一點忙都幫不上。我感覺得到，腐朽之息正在逐漸吞噬我的鏡像的力量。\n\n我希望，等到我們抵達地脈洞穴，也就是巨牙海民口中的魔光洞穴，我的本體就能傳送到這裡。", completion = "他們到底做了什麼，用它們來抓背嗎？\n\n&lt;卡雷苟斯捏捏他的鼻梁。&gt;\n\n…我想值得慶幸的是，他們沒發現它們真正的用處。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65848] = {title = "秘典結界束縛", objective = "與卡雷苟斯交談，打開傳送門，接著利用他召喚出的東西，解決蕨皮腐爛者，然後消滅扭曲的古樹。", description = "我們必須阻止那棵樹！有了這些脈能水晶，我總算能幫忙了。\n\n準備好了，就跟我說一聲。我會打開通往蒼藍文庫的傳送門，試著召出一些有用的東西。\n\n後退一點，傳送門可能會有點不穩定。", progress = nil, completion = "你做得很好，英雄，謝謝你。\n\n那棵樹大概不是他們唯一的腐朽中心，但那是對巨牙海民和這條地脈最危險的一個。少了它，這個區域就有可能會恢復。這需要時間，但它會好起來的。\n\n很慶幸我們能給那些巨牙海民的靈魂帶來安息。", rewards = "疾風捲軟靴變形皮甲底鞋刺藤鍊甲脛甲霰耀踏靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][65849] = {title = "前往伊斯凱拉", objective = "在伊斯凱拉與布蕾娜會面。", description = "感謝你的諸多協助，<name>。多虧了你，我的家人安全了。\n\n現在，我們終於能回到伊斯凱拉，見證老波諾里亞回歸大海。他曾經是很棒的酋長，也是我的導師。\n\n拜託，加入我們的行列吧！所有人都能跟我們一起慶祝海洋的循環。", progress = nil, completion = "你的出席讓我很高興。\n\n不過，你得先等一下。儀式還有很多的準備工作要做。", rewards = "您會學到：\n\n伊斯凱拉巨牙海民名望\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65850] = {title = "海洋的循環", objective = "和布蕾娜交談，見證喪禮儀式。", description = "謝謝你，<name>。我已經從新朋友那裡得知我目前需要的資訊。\n\n為他們酋長舉辦的喪禮儀式就快開始了。伊斯凱拉對我們展現友好與熱情，我們也應該在啟程回蒼藍文庫之前參加這場儀式。\n\n和布蕾娜交談，讓她知道我們等他們準備好就過去。", progress = nil, completion = "&lt;卡雷苟斯露出若有所思的神情。&gt;", rewards = "您能選擇下列奬勵中的一個：\n\n莊嚴海貝串飾\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65852] = {title = "登上頂端", objective = "從一袋實用物品裡找出秘法墊腳石，然後用它抵達蒼藍文庫的頂端。", description = "塔頂似乎有東西正在緩慢吞噬秘法能量。\n\n既然你已經讓下面這裡的能量恢復穩定，你應該能夠「駕馭」那裡的秘法魔法。\n\n找找你的背包，裡面應該有稱為「秘法墊腳石」的東西。使用它，然後到上面跟我會合。", progress = "摔下去可是會粉身碎骨的。要多加小心。", completion = "這上面的情況比我預期的還糟！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65855] = {title = "幫助蒼藍高地", objective = "回到安東尼達斯營地找全憶者諾麗可。", description = "我們得先修復蒼藍高地的地脈，不然無法復原誓言石的能量。\n\n有些地脈只有透過卡雷苟斯才能靠近…但是你還是能派得上用場。\n\n去找巨牙海民，他們可能還活著。在巨龍還在的時代，他們就住在這裡，對這片土地有非常深入的了解。\n\n與我們的其中一個秘法助手交談，回到你的盟友身邊。", progress = nil, completion = "巨牙海民？是有一些巨牙海民商人和旅行者會通過這裡。", rewards = "您能選擇下列奬勵中的一個：\n\n水授璽戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65864] = {title = "追上商隊", objective = "在大樹山丘附近追上布蕾娜。", description = "你應該追上布蕾娜，她的商隊才剛通過這裡不到幾個小時。\n\n為了舉行喪禮紀念已故的酋長，他們正在收集他最珍貴的財產。\n\n商隊運載的貨物非常多，她應該不可能走得太遠。", progress = nil, completion = "豺狼人的攻擊殘忍無情。\n\n他們的襲擊兇猛而迅速，所有沒被釘在地上的東西都被拿走了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65867] = {title = "大樹山丘的嚎叫", objective = "殺死杜剛、科沃和巴克拉。", description = "攻擊我們商隊的豺狼人由三名副官所領導。\n\n杜剛的側翼有十幾隻土狼護衛。\n\n科沃設置了許多危險的陷阱。每當我們想去追擊他、結果卻觸發陷阱時，他就會發出瘋子一樣的笑聲。\n\n巴克拉則會無情地嘲弄我們。\n\n為了找回被偷走的東西，必須殺死他們。", progress = nil, completion = "很好，你辦到了我沒能完成的事。\n\n不過我在擔心，還有另一個豺狼人在領導影爪…那傢伙比你遇到的三個都還要嚇人。", rewards = "您會收到：\n\n再生元龍：下顎有鰭迎風護腿變形皮甲馬褲刺藤鍊甲馬褲霰耀腿鎧"}
MultiLanguageQuestData['tw'][65868] = {title = "那些不能嚼", objective = "找回8個葬儀祭品。", description = "我找到一個波諾里亞的葬儀祭品，被這些影爪豺狼人濫用過後丟棄…上面都佈滿了咬痕！\n\n伊斯凱拉酋長最近去世了，他的追悼儀式需要這個東西和其他類似的祭品。\n\n這麼神聖的東西卻被當成了磨牙玩具，實在太侮辱人了。請幫我們留意，找出其他的祭品。", progress = "<哈努往前傾，一臉期待地盯著你的包包。>", completion = "&lt;哈努皺起鼻子。&gt;\n\n呃…沾滿了口水。\n\n酋長的紀念活動還是需要這些東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65869] = {title = "另一次伏擊", objective = "跟阿基恩交談，並檢視4具附近的屍體。", description = "這是個悲劇。而且或許是更多悲劇的開端。\n\n調查阿基恩知道的資訊，然後檢查一下所有在攻擊中死去的人。\n\n我對這裡發生的事情有個預感。我們來看看有沒有線索能支持我的理論吧。\n\n在那同時，我會努力安撫我那嚇到的朋友。", progress = nil, completion = "這真的是場悲劇…但至少我們有線索可以追查。\n\n我們離這場腐敗的源頭越來越近了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65870] = {title = "有補給品！", objective = "取回狩獵用品。", description = "大樹山丘找不到我們被偷的狩獵用品。一定是在那個洞穴裡。\n\n張大眼睛注意有沒有補給品箱子，然後做好應對任何情況的準備。\n\n我不相信豺狼人會讓那些物品沒人看守。", progress = "我可不想讓伊斯凱拉人挨餓…", completion = "&lt;波雅長老讚許地看著你取回的補給品。&gt;\n\n伊斯凱拉巨牙海民又能重拾狩獵了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65871] = {title = "豺口餘生", objective = "救援諾魯克和其他3名被俘虜的巨牙海民。", description = "我已經追蹤到被擄走的巨牙海民，還有我丈夫諾魯克，他們都在這個洞穴裡。\n\n諾魯克時常沒注意到自己的安危，所以這個責任就落到我身上了。但我也不會拉不下臉來求助。\n\n請救救他們！", progress = nil, completion = "&lt;哈努皺起她的臉頰，給諾魯克一個露出長牙的微笑。&gt;\n\n看到諾魯克安然回來，我就放心了。我們一回伊斯凱拉，就會哀悼失去的同胞。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65872] = {title = "有病的豺狼人", objective = "在卡格波的巢穴殺死16隻影爪豺狼人。", description = "我聞到風中有一股奇怪的味道。有些事情不太對勁…\n\n哈努說這個洞穴裡的豺狼人很奇怪…而且生病了。我們應該深入瞭解造成這種情況的原因。\n\n別放鬆你的警戒。儘管他們看起來病得很重，但請記得他們還是跟原來一樣危險狡詐。", progress = nil, completion = "我們從來沒看過這種腐化。\n\n真令人擔憂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65873] = {title = "影爪集團領袖", objective = "殺死卡格波並取回他的圖騰。", description = "在森林的這一邊，卡格波是豺狼人真正的領袖。我們…過去曾經有一些過節。\n\n但這一次不同。他帶著一個奇怪的圖騰，那似乎扭曲了他整個人。\n\n必須要阻止卡格波，然後取回那個圖騰。我擔心豺狼人正在攪和一件比我們所能想像還要黑暗的事情。", progress = "你找回卡格波的圖騰了嗎？", completion = "&lt;布蕾娜收下圖騰時，嫌惡地縮了一下。&gt;\n\n卡格波一直以來都很暴力，但他也是個膽小鬼。在我們人數比較多的時候，他和他的同夥從來沒攻擊過我們。\n\n有些事已經改變了…而這個圖騰就是原因。", rewards = "鋼鐵龍族裁決錘鋒利白銀之劍巨型黃銅砍刀光亮鐵矛戟靈光青銅刀刃弓箭手的裝飾弓您會收到：\n\n"}
MultiLanguageQuestData['tw'][65875] = {title = "龍的休息日", objective = "為瓦札莉亞找到各種飲料。", description = "一輩子在外域…總是不停在戰鬥。根本沒時間放鬆！\n\n有時候，一頭龍需要的只是放一天假到海邊玩，享受一杯超級冰涼的飲料。\n\n嘿，或許你可以幫我放鬆！幫我一個忙，看看你能不能找到這些飲料，為我們的補給品帶來一點新意。", progress = "你把我的飲料拿來了嗎？沒有？真是太糟糕了。", completion = "是啊！該躺下來放鬆了！", rewards = "您會收到：\n\n斯帕拉苟斯"}
MultiLanguageQuestData['tw'][65886] = {title = "前往羅甯之盾", objective = "在高塔瞰台與卓克‧刺軸者會面。", description = "菈薩葛絲和洪荒使者正在向瓦瑟洛斯發動全面攻擊，我們絕不能讓她得逞。\n\n我跟卡德加會從空中支援那裡的戰況。\n\n在這段期間，你去羅甯之盾，這個區域裡面最後的祈倫托營地之一。\n\n你從文庫最上層騎龍應該能更快抵達那裡。\n\n確保那裡的祈倫托成員都沒事，然後再去瓦瑟洛斯。\n\n就靠你從地面支援我們了。", progress = nil, completion = "我剛剛才看到卡雷苟斯和卡德加向山裡走去。我們在這裡對抗洪荒使者，不過我們永遠歡迎更多援手！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65887] = {title = "前往山脈", objective = "在瓦瑟洛斯山脈的底部與卡德加及卡雷苟斯的鏡像會面。", description = "卡德加和卡雷苟斯正在空中對抗洪荒使者，這景象真是壯觀啊！\n\n他們召喚了幾個自己的鏡像，幫助你通過洪荒使者創造出來的巨洞。\n\n有一對現在在山腳下。\n\n如果狀況開始變糟…我們會把消息傳遞出去讓蒼藍高地中的其他夥伴知道。", progress = nil, completion = "這比我預期的還要糟。不能再浪費時間了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65890] = {title = "奈薩贊廢墟", objective = "到奈薩贊廢墟找青空書記艾德奈達。", description = "龍鱗遠征隊需要你出手相助。\n\n我派了青空書記去廢墟蒐集情報。那裡應該毫無人煙，不過我卻在這裡聽見他的慘叫。\n\n他的聲音居然傳了這麼遠，他一定是遇到極大的危險。\n\n這次遠征，不管遇到多麼棘手的情況，我們都要照顧同伴。請找到他，協助他脫離險境。", progress = nil, completion = "我當然是在大叫！那本書聽都不聽，我還能怎麼辦？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65891] = {title = "長篇大論的工具", objective = "對5個礫石堆使用附魔工具。", description = "很好。我正想要找你這樣的冒險者幫忙，既強壯，又結實，還願意幫人處理一些雜事。\n\n簡直就像我用意志力把你召來，我實在太能幹了。這些廢墟似乎引來不少人的注意。我們不能期待他們會小心翼翼地挖掘，他們很可能會汙染樣本！\n\n拿著這個。到廢墟各處，把它部署在值得關注的文物周圍。它有魔法，可以執行所有必要工作。", progress = nil, completion = "我們會及時收集到所有東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65892] = {title = "真正碎裂", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65893] = {title = "文物疑問", objective = "收集60個奈薩贊文物碎片。", description = "碎裂火焰軍跑來這裡了。他們名字裡寫著碎裂！怎麼能信他們經手貴重的文物？\n\n當然不行。儘管如此，我們必須知道他們來這裡的目的，才知道下一步要怎麼走。從他們身上收集任何找得到的東西，然後帶著東西來找我回報。\n\n比起我們在地底找到的東西，這個謎題還有更多拼圖要找。", progress = "這些廢墟已經夠破爛了。", completion = "他們還在找？那你為什麼要帶這個爛東西來給我？\n\n我們必須搶在他們之前找到它！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65895] = {title = "競爭夥伴", objective = "收集有關碎裂火焰軍的情報。", description = "呸！這些工人殺得再多，對我們也沒有什麼幫助。\n\n應該去找他們的工頭，他們之中一定有人知道我們需要的情報。\n\n對了，<name>，這次先聽他們把話說完，再殺了他們。你可能會得到有用的情報。", progress = "有什麼消息嗎？", completion = "過去，我曾經碰到跟這個很像的疾病，我一直希望永遠別再碰到它。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65896] = {title = "修復關係", objective = "協助治療暴風城的居民。", description = "你以為自己能神不知鬼不覺地踏進這座城市嗎？不！\n\n我先前果然沒看錯你們這些傢伙，我絕對不會讓巨龍再次摧毀我的家園。\n\n這裡曾是充滿歡樂與和平的地方。然後你們的先輩「死亡之翼」來了。喔，沒錯，我對他一清二楚。\n\n他造成的破壞還遺留至今，你自己去看看。那些痛苦如今仍在街道上徘徊。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65898] = {title = "元龍問題", objective = "取得龍域並擊敗保護它的元龍。", description = "我對碎裂火焰軍沒什麼好感，但我也無法眼睜睜地看著他們像這樣死於非命。這一切都讓人太熟悉了。\n\n無論這個龍域是什麼，比起被他們得到，還是我們手中比較安全。沿著屍體鋪成的道路走，我想應該就能找到它。\n\n一定要小心，$p。我擔心事情有變，那個巢穴說不定沒有廢棄。", progress = "很高興看到你平安回來。你拿到龍域了嗎？", completion = "謝謝你，&lt;name&gt;。\n\n你幫了很多忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65899] = {title = "找到塞拉莫斯", objective = "搜索附近的洞穴，尋找塞拉莫斯。", description = "<race>！你是來拜訪美麗的紫丁香之地的嗎？它現在這麼狼藉真抱歉。我發誓它平常沒有這麼雜亂！\n\n花園的園丁塞拉莫斯今天應該要跟我們見面來一起處理問題的。維護讓他最近有點忙不過來，所以菲莉娜和我在幫忙他。但我們沒辦法做完全部的事。\n\n你可以幫我們四處找找他嗎？或許他忘記了。", progress = nil, completion = "你找到他了！他今天似乎真的非常沮喪。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65900] = {title = "可疑調味肉排", objective = "收集2份完美鮮嫩的龜肉、6份爬蟲類蛋殼和15朵酸味花。", description = "她的想法很有意思，不過塞拉莫斯需要的是真正能讓他振奮起來的東西。\n\n也就是要特大份量的酸味花。我們能把它弄成糊狀，塗在他最喜歡的龜肉上！\n\n你願意幫我收集食材嗎？", progress = "你知道酸味花為什麼會生長在海岸的樹下嗎？\n\n樹的樹根會留住海浪帶來的豐富營養素，讓酸味花順利成長茁壯。這能讓它們獲得極大的營養價值。", completion = "肉和酸味花的比例剛剛好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65901] = {title = "偷溜", objective = "到雍伊爾溫泉放置風之圖騰，然後通知菈迪亞。", description = "我被永久禁足了！難道我的雍不知道，我明年春天就要滿16歲了嗎？我應該可以想離開就離開才對。\n\n看來你可以幫我的忙。我確實有個逃跑計畫：透過引導這些圖騰，我可以凝聚空氣並製造不小的擾動。不過，我沒辦法把它們放到定位，因為我一直在強風的監視之下。就連托苟都幫不了我。\n\n不過，要是有你幫忙…拜託了！我保證會給你看很酷的東西。", progress = nil, completion = "呼，謝謝你！自由！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65903] = {title = "毛茸茸最讚", objective = "捕捉12隻林地跳兔。", description = "可憐的塞拉莫斯。我有個想法，或許能讓他開心點！\n\n拿著這張網子去捉幾隻土生土長的跳兔，牠們性格溫順，動作卻很快。海岸附近有不少跳兔出沒。\n\n只要把牠們送給塞拉莫斯，那毛茸茸的絕佳觸感，應該能讓他精神一振！", progress = nil, completion = "好！多！跳跳兔！每一隻我都要摸摸！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65905] = {title = "不只是雜草", objective = "清除紫丁香之地的藤蔓和怪物。", description = "也許我們最好給塞拉莫斯一點空間，\n\n但我們也不能無所事事。林地正在快速自我毀滅！請幫幫我們。", progress = nil, completion = "謝謝你，&lt;race&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65906] = {title = "不滿的學徒", objective = "到雍亞拉平原的雍伊爾溫泉，與學徒菈迪亞交談。", description = "我收到一封來自雍伊爾溫泉的有趣的信。\n\n至於信的內容，裡面提到恐怖的監禁生活、控制狂導師，還有極度無聊的一切。它的正式簽名是學徒菈迪亞留下的。這裡還有張插圖，畫著一隻老鷹…把一個名叫梅倫的半人馬踢下懸崖。\n\n這個嘛。我想這應該是求救信，要是你有興趣的話，可以親自去看看。老實說，我想菈迪亞應該沒事。她很常寄這種信給我。", progress = nil, completion = "你是誰？歐德溫派你來的？他真的讀了我的信？\n\n&lt;菈迪亞發出驚訝又開心的哼聲。&gt; 感謝雍亞拉！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65907] = {title = "最愛的水果", objective = "從雍伊爾噴泉收集野生灌木果，並餵給6個懶洋洋的踏泥獸。", description = "秘法師訓練無聊透頂。我有一半的時間都在觀察水的形態。我的兄弟們都已經到野外去狩獵飛龍跟洪荒使者，為這個世界帶來改變。\n\n總之，我保證過會給你看很酷的東西！你知道踏泥獸喜歡灌木果嗎？它就長在附近的噴泉那裡。去摘一些來，我們可以一起餵牠們。", progress = nil, completion = "看來牠們喜歡你！或是牠們喜歡漿果。這樣也不錯。&lt;菈迪亞眨眨眼。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65911] = {title = "蒼藍連線", objective = "返回蒼藍文庫去見卡雷苟斯。", description = "這個群體的情感連結…他們所共享的友誼與家庭。\n\n我…從未有過。藍龍軍團從未有過。或許那是因為我們從未有過這種機會。\n\n現在正是時候。我必須召集我的族人。\n\n到蒼藍文庫和我會合。還有很多事要做。", progress = nil, completion = "我從沒想過能從巨牙海民身上學到那麼多。我想，有空的時候我會去拜訪他們，維繫我們之間的友誼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65913] = {title = "看啊，是看守者？", objective = "前往提爾堡蓄水池，從洪荒使者手中解救看守者瑪拉。", description = "感謝泰坦！<class>，我們需要你的協助！\n\n洪荒使者不久前開始進攻。我和我的姐妹雖然成功守下，但卻傷亡慘重…\n\n但先確保我的看守者安全之後，再來悼念吧！交戰的過程中，有群洪荒使者趁亂逃脫，我發誓，要是他們膽敢傷害我們的看守者…\n\n你必須去幫她，否則就來不及了！", progress = nil, completion = "謝謝你，&lt;race&gt;。要不是有你出手相助，我早就沒命了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65914] = {title = "猛瑪象很重要", objective = "在寇莉格微光水灣附近，從死亡的翁塔克猛瑪象身上收集翁塔克毛皮碎塊及翁塔克獠牙。", description = "我們的部族已經飼養翁塔克猛瑪象群好幾代了。這是我們引以為傲的事蹟，但是現在牠們…卻都死了。\n\n經過這樣的大屠殺，牠們的靈魂因為憤怒而徘徊不去。我們必須妥善運用牠們的屍體，讓牠們的生命得到尊重。\n\n但是數量太龐大，光憑我們根本收集不完。拜託你，從小象和母象身上收集還可以用的材料，然後到寇莉格微光水灣來見我。", progress = "我的孩子們已經挑選了小象，要培養成他們自己的夥伴。我該怎麼跟他們交代呢？", completion = "有了這些遺骸，我想我們可以做出真正特別的東西…讓這些猛瑪象的靈魂得到安息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65916] = {title = "我們不和洪荒使者協商", objective = "到提爾堡蓄水池殺死洪荒使者的首領科裘，並取回遺失的鑰石。", description = "洪荒使者以為他們能夠壓制提爾的力量。他們錯了。\n\n我的瑞夫提手下追查洪荒使者的行蹤，發現他們藏身在離這裡不遠的洞穴裡。如我所料，遺失的鑰石就在他們手中。\n\n勇士，如果我們要修復蓄水池，就必須取回那些鑰石。\n\n此外還必須殺死他們的首領，他們才不會再度發動攻擊。", progress = "等我們取回鑰石以後，祖提奇一定就不會那麼…沮喪了。", completion = "謝謝你，&lt;name&gt;。我們最後的任務就是要恢復結界。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65918] = {title = "預防性維護", objective = "在提爾堡蓄水池殺死8個無縛元素。", description = "洪荒元素正在無止境地增生。原本我和我的姐妹會解決它們，但我們現在無力與它們交戰。有不少士兵陣亡了。\n\n此外，我們這些倖存下來的少數人也都背負著各自的任務。\n\n<祖提奇痛苦地皺了臉一下。>\n\n$p，現在就是你能出手的時候。你能解決那些元素生物嗎？", progress = nil, completion = "謝謝你，&lt;name&gt;。那樣應該可以暫時抑制住它們了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65920] = {title = "為了結界！", objective = "使用遺失的鑰石修復蓄水池的結界，然後啟動控制臺。", description = "我們終於能修復結界了。就算我們遭受到極大的損失，但我們還是必須要完成這個任務。\n\n$p，我們再一次需要你的協助。請將每個鑰石帶到正確的地方，讓結界再次完整。\n\n完成之後就回來，到時候我們就能啟動控制臺，恢復蓄水池的秩序。", progress = nil, completion = "做得非常好，&lt;name&gt;。結界已經恢復了，提爾堡蓄水池又再一次受到保護。謝謝你做的一切，薩爪祖斯欠你一筆很大的人情。", rewards = "姐妹的贈禮姐妹的守衛者您會收到：\n\n"}
MultiLanguageQuestData['tw'][65921] = {title = "瑞夫提懲戒", objective = "到提爾堡蓄水池殺死洪荒使者，並拯救瑞夫提倖存者。", description = "$p，我的腦海都是這個念頭。有那麼多姐妹慘遭殺戮！生命有如草芥一般…絕對要讓殺死他們的傢伙付出代價！\n\n我的士兵一路追蹤洪荒使者，他們說還有一些姐妹活著。\n\n我們必須救出他們，然後讓每個洪荒使者都知道我有多憤怒！", progress = nil, completion = "我會一直為逝去的人悲痛，同時也慶幸我們拯救了不少人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65925] = {title = "排除外患", objective = "在寇莉格微光水灣附近殺死寒冰滑行者和寒冰鑽孔者。", description = "那些巨蟲不屬於這裡。我不知道牠們為什麼會從地下巢穴被吸引到這裡來，可是我們現在沒辦法幫助牠們。\n\n我們不能讓牠們繼續摧毀這裡的自然生態。\n\n殺死巨蟲，<name>。你要的話可以收集牠們身上的資源，完成之後再來微光水灣找我。", progress = nil, completion = "消滅大自然的生命總是令人遺憾…就算是討人厭的生命也一樣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65926] = {title = "應對瀑布", objective = "協助盧里克建造秋步號。", description = "你聽說過微光魚釣者的故事嗎？她建造了一艘無比堅固的船，成功穿過瀑布下方！\n\n那瓦長者最喜歡說這個故事。\n\n我想，如果我們用翁塔克猛瑪象的屍體再次打造這樣的船，它們的尊貴靈魂勢必也會引以為傲。\n\n我的兄弟並不同意，可是，只要我們成功，就能帶魚給我們的姊妹部族了，他們最近都過得不太好。\n\n你已經證明了你的手藝和熱忱！只要我們聯手，一定可以打造出偉大的成品。", progress = nil, completion = "盧里克一直是這麼頑固。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65928] = {title = "任性的風", objective = "在寇莉格微光水灣附近的躁動狂風身上收集10個躁動狂風微粒。", description = "呸！她說要合作？\n\n可是…如果微光魚釣者相信，我們有機會幫上其他氏族的忙…那我們就必須試試看。\n\n為了讓風靈克勞諾特認可我們，我們必須先處理他的元素。在大地開始甦醒時，附近的風元素就已經被侵擾了。\n\n在我檢視你們兩個製作的船的時候，你去和他們戰鬥並卸除他們的武裝，然後把躁動微粒帶來給我。這樣應該可以讓這個區域恢復平靜。", progress = "別擔心，這些風元素生物會在這裡只是因為他們被激怒了。只要摧毀他們，我們就能使這裡的風恢復平靜。", completion = "我會顧好這些微粒，確保它們無害地消散。克勞諾特一定會很高興。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65929] = {title = "破冰", objective = "在寇莉格微光水灣附近從寒冰中打破冰凍之水。", description = "我就知道先祖會同意！\n\n我對神靈知道得不多…考吉才是薩滿。不過我們必須先取悅偉大的風之靈和水之靈，祂們才會為我們現身。\n\n大家都能看到，山上的水元素正在慢慢結凍。這不是自然的結凍現象。最近，寒冷從山上傳下來的現象比以往都嚴重。如果不管的話，我們的整條河都可能結冰。\n\n將他們從冰獄中釋放出來吧！", progress = nil, completion = "非常好。此地的河靈歐圖洛克會很高興知道祂的河會繼續流動，至少暫時如此。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65930] = {title = "與風和水的搏鬥", objective = "在寇莉格微光水灣附近挑戰風之靈克勞諾特。", description = "現在，我們應該就可以和神靈對決了。\n\n盧里克沒有提到嗎？根據我們部族的傳統，我們必須和神靈戰鬥，才可以向祂們祈求恩惠。祂們的祝福的力量取決於你在祂們心中留下的印象。\n\n或許這就是微光魚釣者堅持我們要合作的原因。\n\n如果你挑戰風之靈克勞諾特，盧里克和我就會對付水之靈歐圖洛克。\n\n祂們就住在附近瀑布後的洞穴中。我們在那裡會合吧，冒險者。", progress = nil, completion = "因為考吉的年紀比我大得多，他一直比較像…父親，而不是兄弟。\n\n我原本以為年紀變大，開始擁有自己的家庭以後，會讓我變得不再那麼需要他。\n\n我錯了。甚至在我妻子去世之前，我就知道我錯了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65935] = {title = "趕上克羅米", objective = "到時光合流平台與克羅米會合。", description = "你幫助我們重新掌控了這片沙地，但是我感應到神殿平台上似乎發生了不得了的大事。我們得趕緊起飛，到那邊和克羅諾穆大使會合。\n\n老話一句，時間寶貴。", progress = nil, completion = "時候到了！雖然伊特努斯看起來像是凍結在泡泡裡，但其實她一直在全力掙扎，想要逃出去。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65937] = {title = "疏忽的證據", objective = "找到紫丁香之地出問題的證據，然後拿給塞拉莫斯看。", description = "我們不能放棄。他得知道這裡發生了什麼事！如果他不願離開洞穴，我們就直接展示給他看。\n\n不管什麼證據都可以，反正反常的東西太多了，像是腐化的植物，或是充滿敵意的野生動物！", progress = "看到林地和塞拉莫斯變成這幅模樣，實在讓人害怕。", completion = "你回來了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65938] = {title = "曾經與未來的隊伍", objective = "利用你的時光行者法杖，打破神殿大門的靜滯泡泡。", description = "來吧！我們得把神殿大門周圍的靜滯泡泡打破，救出我們的守望者！你準備好跟時間拔河了嗎？\n\n用力拉扯大門那裡的泡泡，就像之前對水晶做的那樣。小心一點，釋放出來的時間能量一定會全部朝你襲來。我不知道會冒出什麼，但無論如何，至少獲救的守望者一定會站在你這邊。\n\n祝你好運，<name>！", progress = nil, completion = "這是我看過第二大隻的時光元素！我早知道今天應該要帶自拍相機來的。\n\n沒關係！等我下次休假，我再過來這個時間點補拍就好了。", rewards = "時光精神半指手套時光精神手套時光精神護手您會收到：\n\n"}
MultiLanguageQuestData['tw'][65939] = {title = "信念的勇氣", objective = "攻下黑曜龍堡上層。", description = "下一場戰鬥無疑是一場惡戰，不過我們有勇氣、有決心，絕對能以少勝多。\n\n我想有了你出色的戰力，一定能帶領部隊贏得勝利。\n\n等你準備好了，我們就會開始進攻。", progress = nil, completion = "做得非常好，&lt;name&gt;！加拉登的部隊開始潰散了！我們現在已經掌握了堡壘的上層。然而，下層的寶庫需要花更多時間才能佔領。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65940] = {title = "破碎之路", objective = "與席卡的商隊同行，前往河流渡口。", description = "我想你不會介意弄濕你的腳，在接下來的旅程中，我們必須渡過兩條河。\n\n雍‧賽希騰會很樂意跟你分享我們受祝福的看守者「雍亞拉」的故事。你們兩個接下來要好好相處喔。", progress = nil, completion = "我感覺到風裡有什麼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65943] = {title = "洪荒攻擊", objective = "在瓦瑟洛斯擊敗15名洪荒使者。", description = "我跟卡德加正在努力抵擋空中的洪荒使者，但是我們沒辦法往高塔推進。\n\n我們需要你削弱他們的地面部隊，好讓我們靠近菈薩葛絲，在一切太遲之前阻止她。\n\n打倒前方的洪荒使者。如果我能保持專注，會有另一個鏡像在那裡等你。", progress = nil, completion = "做得好，他們的幾支部隊應該從上面被調開了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65944] = {title = "熔岩爆發", objective = "摧毀3顆熔岩球。", description = "洪荒使者撕裂了這座山脈，派出大批部隊湧向瓦瑟洛斯！\n\n我在最初的走廊上發現了一些他們用來散播元素混沌的熔岩球。\n\n摧毀它們，減緩他們的前進速度。我會在上面這裡盡我所能的協助卡雷苟斯。", progress = nil, completion = "這樣應該可以減緩他們的攻勢。和對抗燃燒軍團那時候相比，看來我現在的本領已經生疏了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65947] = {title = "時間暫停的時光行者", objective = "從時間泡泡中解放8個時光行者。", description = "真高興你來了！在但丁和澤拉幫我制住恆龍朋友的同時，我需要你來處理平台上的狀況。\n\n伊特努斯企圖奪取我們誓言石的時候，神殿的防衛機制緊急啟動將她困在靜滯泡泡中。不幸的是，其他的時光行者也遭到波及、被安全措施困住了。\n\n你的時光行者法杖應該可以釋放他們。只是要小心應付跑出來的憤怒小時光元素！", progress = nil, completion = "成功了？我一點也不驚訝…頂多就一點點而已！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65948] = {title = "時間裂隙", objective = "利用東邊和西邊的水晶，進一步強化時光行者法杖。", description = "在神殿封鎖的時候，守望者也和神殿的門一起給封印了。我們需要打破那個靜滯泡泡，把他們救出來！不幸的是，需要能量全滿的時光行者法杖才能這麼做…\n\n我知道了！你可以從平台上的那些水晶汲取力量！那些能量應該夠你的法杖用了。\n\n水晶本身就有靜滯力場，只要將其抽離出來，就能用法杖吸收其中的能量。\n\n如果水晶碎裂也不用太擔心，就算它化成碎片，力量還是在！", progress = nil, completion = "做得非常好！\n\n現在你應該有足夠的時光能量解救守望者了！", rewards = "您會收到：\n\n高地飛龍：尖刺尾巴"}
MultiLanguageQuestData['tw'][65949] = {title = "鞋底治癒者", objective = "將勳章還給蹄鐵匠羅沙。\n\n已提供物品：\n", description = "當我們與雍亞拉一起隨風而逝時，我們會留下這些勳章。\n\n雖然我幫忙製作了這個勳章，但我並不是它真正的主人。\n\n你應該把它交給羅沙，這是她未婚夫的遺物。\n\n把勳章還給她，她或許就能好好哀悼，然後走出來。", progress = nil, completion = "這是…啊，沒錯。那我親愛的已經在天上了，和雍亞拉一起奔馳。等時機到了，我會加入的。\n\n謝謝你，&lt;name&gt;。\n\n你為席卡氏族…還有為我…做的事情，我一定不會忘記。", rewards = "您能選擇下列奬勵中的一個：\n\n羅沙的紀念指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][65950] = {title = "偷竊的戈洛克", objective = "到淤鰭村找回遭竊的補給品。", description = "蹄鐵匠羅沙受邀加入商隊了嗎？沒有！但誰要提供蹄鐵給商隊？蹄鐵匠羅沙。而且淤鰭從誰身上偷東西？還是蹄鐵匠羅沙。哼。\n\n我想叫卡沙爾去，但誰知道他現在跑去哪裡閒晃？\n\n找到我的補給品，給那些該死的小偷一點教訓，讓他們知道別偷到蹄鐵匠羅沙身上。\n\n去吧！", progress = "四周的戈洛克太多了，這裡不夠安全。", completion = "羅沙派你來的？她一定非常生氣。\n\n她已經承受太多壓力了。要是沒把失去的都找回來，我不能回去。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65951] = {title = "唯一供應商", objective = "搜索樹林，尋找卡沙爾。", description = "可憐的羅沙！她任勞任怨地幫商隊做事，結果她的補給品居然被那些卑鄙的戈洛克偷了。\n\n她失去了太多。我正在盡我所能幫助她。\n\n卡沙爾大概自己跑去追回那些補給品，而且沒告訴任何人。他老是這樣。不過這次他一直都沒回來，很多狗也跟著失蹤了。\n\n$p，可以麻煩你去找一下卡沙爾和那些狗嗎？", progress = nil, completion = "謝謝你，&lt;name&gt;。我們開工吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65952] = {title = "傳奇酋長", objective = "殺死鰭爾伽美什酋長。", description = "這個沼地的戈洛克曾經是很單純的生物。或許有點煩人，但永遠不會做出劫掠、偷竊或吃狗肉的事。\n\n都是他們的酋長鰭爾伽美什搞的鬼，害他們越來越偏離單純的本性。\n\n了結他的性命，戈洛克就再也不會對我們構成威脅。", progress = nil, completion = "殺死了戈洛克的酋長，他們就再也不會來打擾我們。\n\n我很驚訝他們在鰭爾伽美什酋長的領導下變得這麼壯大。\n\n我以前從未見過，如此原始的生物起而對抗像我們這樣的強大文明。難道我們的差別真的很大嗎？演化得更進步？好像並沒有…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65953] = {title = "先知先絕", objective = "從戈洛克薩滿身上收集4個圖騰。", description = "這個戈洛克村子的情況未免太瘋狂了，而且最瘋狂的就是那些戈洛克薩滿。\n\n他們邪惡無比，毫無節制地濫用風暴魔法，完全沒在管後果。\n\n我們一定要終結他們的瘋狂行徑。殺死他們，把他們的圖騰帶來給我。我們的秘法師應該會有興趣。", progress = "戈洛克薩滿太過份了。", completion = "&lt;卡沙爾皺眉看著這些圖騰。&gt;\n\n這是風暴魔法圖騰。對於雍亞拉親自賜予的風之賜福來說，風暴魔法就是褻瀆。\n\n我會把這些交給秘術師。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65954] = {title = "關門放狗", objective = "解救席卡巴卡犬。", description = "我聽到熟悉的嚎叫聲和吠叫聲，都是來自從營地失蹤的巴卡犬。\n\n我們親愛的狗狗被關在籠子裡，等著被那些…那些傢伙屠宰。\n\n我們有責任救出我們的夥伴。放出牠們，然後見證席卡巴卡犬真正的實力！", progress = nil, completion = "他們真的很棒，對吧？\n\n每隻巴卡犬在席卡氏族心中都有特別的位置。他們是狩獵的夥伴、是守衛，也是我們最珍愛的朋友。", rewards = "餅乾袋您會收到：\n\n"}
MultiLanguageQuestData['tw'][65955] = {title = "半人馬最好的朋友", objective = "解救卡沙爾，然後到洞穴找他。", description = "$p，一直待在空曠處不安全。\n\n巴巴是我的狩獵夥伴，牠被戈洛克追趕，跑進東邊的洞穴。\n\n救我出來，然後我們一起去救巴巴。清出一條路後，我會在那個洞穴跟你會合。", progress = nil, completion = "&lt;name&gt;，謝謝你。我們在這裡很安全，可以暢所欲言。\n\n我會在巴巴休息的時候保護牠，趕走闖進來的戈洛克。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65956] = {title = "猛爪攻擊", objective = "瓦解加拉登的防禦。", description = "在你的幫助下，我的黑爪刺客會清除防守外圍地帶的加拉登。用小型昏迷炸彈標記目標，他們就會前去支援。\n\n請快點行動，消除可能妨礙我們進攻的所有障礙。", progress = nil, completion = "我們的進攻讓他們節節敗退！現在剩下的就是突破大門了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65957] = {title = "無需英雄", objective = "殺死莫達克‧焰噴、『穿刺者』季格拉和熔火歐菲斯。", description = "從我們觀察到的結果來看，加拉登是個崇尚武力的種族。最強者會身先士卒，激起其他同伴的戰意。\n\n在下方的部隊中，共有三個實力最為強大的加拉登…他們就是你的目標。\n\n<name>，你需要獨自解決他們。這樣應該能對他們的士氣造成沉重打擊。", progress = nil, completion = "你已經證明自己是真正的英雄了，&lt;name&gt;。", rewards = "加拉登殺戮者披氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][65958] = {title = "洪荒力量", objective = "使用元素法器，從殺死的洪荒使者和元素生物身上汲取元素能量。", description = "我恐怕越來越難維持我的鏡像了。洪荒使者正在集中他們所有武力要把我從空中打下來。\n\n別擔心…我有計畫。\n\n我需要你用取得的球體，從殺死的洪荒使者身上收集元素魔法。\n\n我們在前方會需要用提升的元素能量，把他們的部隊從我這裡引開。", progress = nil, completion = "這個寶珠正在散發能量！在接下來的行動中，這一定很有幫助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65962] = {title = "永遠不是最終的倒數", objective = "準備好就與克羅米談話。", description = "真想不到我竟然要解除我們用來保護神殿的安全措施，才有辦法拯救它，但看來非做不可了！\n\n既然我們已經清除了時光元素，也釋放了時光行者，還讓守望者做好了準備，現在終於該解除最後一個靜滯泡泡，處理伊特努斯了。\n\n等你準備好就跟我說一聲。有你陪著我，事情絕對不會出錯的。", progress = nil, completion = "伊特努斯和克羅米在時間與空間當中不斷穿梭。我們要不計代價把他們找回來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65977] = {title = "找回祈倫托法師", objective = "拯救6名瀕死的法師。", description = "洪荒使者攻擊我們遠征隊的時候，我就擔心我們有很多法師已經遭到毒手了。\n\n他們似乎被洪荒使者帶走，在我們說話的同時，他們飽受敵人折磨！\n\n拜託你，你必須救出被留在這裡的法師。他們或許無法成為這場戰鬥的戰力，但是也不能拋下他們！", progress = nil, completion = "我很感謝你。在這場戰鬥中，我們不能拋下任何人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65989] = {title = "加拉登入侵者", objective = "到龍心哨站殺死6個加拉登。", description = "我們或許無力奪回哨站，但我們絕對不能不戰而降。\n\n讓他們知道，我們可不是好惹的。", progress = nil, completion = "好極了。", rewards = "遠征隊研究員法衣遠征隊守衛護胸遠征隊傭兵鍊衫田野偵查員外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][65990] = {title = "讓幼龍逃離魔掌", objective = "從龍心哨站救出4隻哀號的幼龍。", description = "他們突然發動襲擊，我們根本來不及反應。我的守衛盡全力擋住敵人，我們則設法撤離年幼和需要幫助的族人，但恐怕還有更多族人還困在哨站那裡。\n\n請越過那座橋，搜尋倖存者。", progress = nil, completion = "我們還不能休息，不過知道他們得救後，我總算能鬆一口氣了。謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65991] = {title = "清算時間到", objective = "到碎鱗者要塞與怒西昂和管理者瑟利思特拉會合。", description = "見習生仙卓克絲已經把管理者的計畫告訴我了。謝謝生命守縛者願意伸出援手。他們的干涉為我們爭取到寶貴的時間，將傷患送回生命之池接受治療。\n\n我希望我能派人支援瑟利思特拉，但我的守衛必須保護傷患。前往敵人的要塞，跟他們會合。\n\n要是有別的辦法可以對付加拉登，我一定會去做。只可惜一直都沒有…\n\n你必須盡你所能。", progress = nil, completion = "能夠在這麼艱難的時刻，聽到來自龍心哨站的好消息，讓我的心情好了不少。那些難民在生命之池絕對非常安全。\n\n就算是加拉登，也決不敢出兵對上龍后雅立史卓莎。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65992] = {title = "黑爪情報", objective = "與怒西昂派入碎鱗者要塞的間諜交談。", description = "正當我和瑟利思特拉從上方吸引他們的目光時，陰影已經滲透了他們的防禦。\n\n整座要塞都在我的黑爪密探的監控之下，找到他們，告訴他們你是我們這邊的人。他們會給你有關敵人的珍貴情報。", progress = nil, completion = "這令人十分不安。又一個與他們戰鬥的理由。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65993] = {title = "掃興", objective = "到碎鱗者要塞殺死絞肉手索托可。", description = "啊，沒錯。\n\n我來了之後不久，就看到這些巨人的首領剛剛結束戰鬥回來。她正在營地的某處慶祝他們的勝利。\n\n只可惜，他們開心不了多久了，你不覺得嗎？", progress = nil, completion = "加拉登似乎不缺用來阻礙我們的屍體…不過，或許這個打擊會暫時停止他們的行動。你做得很好，朋友。", rewards = "野外探險者護杖探險者協會步槍探險者短劍遠征隊解剖小刀開墾之斧遠征隊防衛者之刃無盡威脅斬斧發現之杖您會收到：\n\n"}
MultiLanguageQuestData['tw'][65994] = {title = "加拉登正義", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65995] = {title = "黑曜龍堡", objective = "將喀拉希計畫書交給怒西昂。\n\n已提供物品：\n", description = "<乍看之下，這似乎是加拉登營地之間的內部通信。\n\n「黑曜龍堡」一詞映入眼簾。\n\n怒西昂也許會對這東西感興趣。>", progress = nil, completion = "我喜歡！我最喜歡窺探敵人的心思了。這樣我才能攻擊地又快又準。\n\n讓我們來看看...\n\n黑曜龍堡？\n\n不。\n\n不！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65996] = {title = "精英援軍", objective = "協助受傷的守衛並找到仙卓克絲。", description = "指揮官萊薩納克一向足智多謀，想要化解他們的威脅，我們需要最老練的守衛相助。召集他們的任務最適合交給像仙卓克絲這樣的年輕見習生，不過她可能需要支援。\n\n仙卓克絲已經前往西邊執行任務，但這個新生的威脅可能已經危及那個地方。他們同樣需要援助。請帶著這個混合物去支援他們。", progress = nil, completion = "仙卓克絲才剛到，就繼續前往下個地點，就像旋風一樣。\n\n我喜歡她。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65997] = {title = "追逐仙卓克絲", objective = "到生命守縛者存護所廢墟尋找仙卓克絲。", description = "見習生仙卓克絲不久前來過這裡。\n\n她轉達了指揮官萊薩納克的命令，要求所有龍獸回到生命之池集合。過了不久，我們整支防守兵團就朝那個方向移動了。\n\n不過我們的斥候當時正在那些古老廢墟中巡邏，所以她就去了那裡，準備召集他們。", progress = nil, completion = "我在文庫裡還沒有讀過洪荒使者竊取龍蛋的相關資訊。\n\n這很糟糕。非常糟糕。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65998] = {title = "龍群的未來", objective = "搶救晶紅龍蛋。", description = "每個龍獸結業的時候，都清楚誓死守護每一顆龍蛋，是我們最崇高的職責。\n\n這是我們訓練的理由，也是我們存在的理由。\n\n我再也不能躲在一旁袖手旁觀，$p。洪荒使者偷了這些龍蛋，將力量注入其中，等同威脅到整個龍群的未來！\n\n雖然敵眾我寡，但你願意跟我並肩作戰嗎？你願意為了拯救龍群而戰嗎？", progress = nil, completion = "&lt;仙卓克絲顯然因為她得做的事激動不已。&gt;\n\n對這些可憐的幼龍來說，死亡是唯一的慈悲…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][65999] = {title = "染紅的齒爪", objective = "殺死15個洪荒使者入侵者。", description = "指揮官萊薩納克警告過我們這些新兵，他已經接到報告說，噬風者菈薩葛絲從囚禁中逃脫了。看來她的僕從在那之後也跟隨著她，對我們珍視的一切造成威脅。\n\n他們動作很快。在上一次的巡邏中，這些廢墟還處於廢棄狀態。\n\n我們必須阻止這裡的洪荒使者。\n\n為了生命守縛者，為了所有龍群！", progress = nil, completion = "&lt;仙卓克絲拍熄護甲上的殘火。&gt;\n\n我們能做的、該做的，我們都做了。", rewards = "您能選擇下列奬勵中的一個：\n\n洪荒使者墜飾\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66000] = {title = "雅立史卓莎的圖書館", objective = "搶救4本重要的文化著作。", description = "<這本書的書頁變得焦黑。\n\n洪荒使者似乎在焚燒在這裡找到的遠古典籍，讓龍群的歷史傳承陷入危險。就像洪荒使者想把龍群從歷史上抹去一般。\n\n請盡可能搶救典籍。>", progress = nil, completion = "我們的歷史會流傳下去。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66001] = {title = "最後的希望", objective = "搶救最後一顆灌能的龍蛋。", description = "一整窩的幼龍，消失了…\n\n<仙卓克絲重新打起精神。>\n\n還有一個地方我們還沒去看。就是那隻元龍放下龍蛋的大型儀式場所。\n\n讓我們一起突破他們堅固的防禦，$p，盡全力搶救龍蛋。", progress = nil, completion = "那是…？", rewards = "遠征隊守衛脛甲遠征隊研究員足靴遠征隊傭兵長靴田野偵查員長靴您會收到：\n\n"}
MultiLanguageQuestData['tw'][66003] = {title = "戒指束縛著它們", objective = "收集12個縛火戒指。", description = "這裡的加拉登族變大膽了，竟然會束縛烈焰元素並讓它們在這地區肆虐。野生動物四處逃竄，元素生物現在離我們營地太近，會造成危險。\n\n幸好，我已經建造了一個小石堡，來阻擋加拉登族釋放的火焰浪潮…我們不會被擊倒的！\n\n請收集束縛這些烈焰元素的魔法戒指。我們要用它們來強化我們的防禦工事，抵禦烈焰元素。", progress = "你收集到所有我需要的戒指了嗎？", completion = "完美！這些戒指殘留的能量可以用來對付它們的創造者，召喚一個由我們控制的傀儡！", rewards = "您能選擇下列奬勵中的一個：\n\n元素束縛戒指\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66004] = {title = "高葛瑞希", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66005] = {title = "過世朋友的勳章", objective = "把過世朋友的勳章帶回去交給卡沙爾。\n\n已提供物品：\n", description = "<這塊嚴重磨損的金屬原先是美麗的裝飾品，對席卡半人馬而言意義重大。\n\n卡沙爾或許知道它的主人是誰。>", progress = nil, completion = "這枚勳章是我一位親密的好友僅有的遺物，她在上一季冒險太深入沼澤了，我還以為再也找不到它了。\n\n這塊皮革是我從她第一場猛瑪象狩獵中剪下來的。我們當時只是孩童。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66006] = {title = "回去找羅沙", objective = "將補給品還給蹄鐵匠羅沙。", description = "巴巴沒事了，羅沙的補給品也拿回來了。我們現在回去，她應該不會再生氣了。\n\n離開的時候，帶一些箱子走。剩下的我會派戰士來搬。", progress = nil, completion = "你拿到補給品了？很好。\n\n放在熔爐旁邊吧。\n\n&lt;羅沙觀望四周然後皺眉。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66007] = {title = "自由的空氣", objective = "摧毀4座熔岩信標。", description = "洪荒使者利用這裡的巨大球體阻擋了卡雷苟斯。\n\n照這樣下去，卡雷苟斯很快就會因傷勢太重而無法繼續飛行。要是他倒下，我就無法抵擋菈薩葛絲了。\n\n利用你手中的強化寶石，應該可以偽裝成元素生物，然後趁機偷溜進去。\n\n然後使用寶石摧毀球體，這樣一來，卡雷苟斯應該就有機會釋放他的力量。\n\n我會持續集中精神，抵擋菈薩葛絲對高塔的攻擊。", progress = nil, completion = "謝謝你，&lt;name&gt;。現在該讓洪荒使者知道蒼藍守護巨龍真正的實力了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66009] = {title = "保衛瓦瑟洛斯", objective = "擊敗『毀滅者』寇索斯", description = "<name>，是時候了。你處理掉地面上的東西以後，空中的洪荒部隊數量也正在減少。\n\n多虧有你，菈薩葛絲正在召喚她其中一名副官來增援他們的部隊。\n\n我需要你去對付這頭怪物，我則向前推進，去和菈薩葛絲戰鬥並協助卡德加。\n\n你戰鬥的時候，我會盡我所能地使用魔法幫你。\n\n該讓菈薩葛絲見識魔法之王的怒火了！", progress = nil, completion = "真高興能見到你，冒險者。時間寶貴！", rewards = "您會收到：\n\n烈風迅疾龍：彎曲犄角疾風捲手套變形皮甲手套刺藤鍊甲之握霰耀粉碎手套"}
MultiLanguageQuestData['tw'][66012] = {title = "封印之門", objective = "前往薩爪祖斯的封印之門，並和娜蕾迪亞談話。", description = "我們的偵查員在巨龍群島上到處搜查有興趣的物品。他們帶回許多筆記，不過有一項發現特別引人注目：一扇門。\n\n那是一座泰坦鍛造的門，而且它被封印起來，不對外開放。還沒有人成功通過那道門，但門裡一定藏著神器。\n\n不過，任何謎題面對聖匣守護者的犀利目光時，都沒辦法持續太久。\n\n而我相信有了探險者協會的幫助，這個挑戰會更加輕鬆。", progress = nil, completion = "對你這麼能幹的人來說，我相信這趟旅程不算什麼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66013] = {title = "調查大門", objective = "在四周尋找線索。", description = "我們到了。如果我們想要穿過這道門，我們必須要知道是誰用什麼方法鎖上它的。\n\n四處看看，或許你能找到我們想要的答案。", progress = nil, completion = "我們還需要更多，才能繼續。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66015] = {title = "藍龍誓約石", objective = "伴隨卡雷苟斯復原蒼藍誓約石", description = "蒼藍高地暫時穩定下來，然後也有更多藍龍趕來了。\n\n該返回蒼藍文庫復原誓言石了。\n\n我想要求你前往那裡，<name>，在這場災難當中，你一直是個帶來好運的存在。", progress = nil, completion = "誓言石再次獲得強化。還有好多事要做啊…不過，蒼藍高地終於又恢復平靜了。", rewards = "疾風捲披肩變形皮甲肩甲刺藤鍊甲肩鎧霰耀肩衛您會收到：\n\n"}
MultiLanguageQuestData['tw'][66016] = {title = "蹄萊氏族", objective = "向卡琳‧多圖回報。", description = "<桑索克可汗比著手語，歐奇爾隨即為可汗發聲。>\n\n蹄萊氏族是大可汗瑪托拉所在的氏族。他們是傳統的守護者、故事的訴說者，也是我們祖先的直系血脈。\n\n想要了解莫魯克半人馬，就必須了解蹄萊氏族。大可汗瑪托拉有個女兒叫卡林‧多圖，她正在準備獻給祖先的供品。請幫她準備，她應該會向你介紹我們一族。", progress = nil, completion = "歡迎你，外來者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66017] = {title = "雍伊爾氏族", objective = "到秘法師水池與雍‧賽希騰會面。", description = "<桑索克可汗比著手語，歐奇爾隨即為可汗發聲。>\n\n在這片土地，像雍‧賽希騰這樣的秘法師都是雍伊爾氏族的一員。維繫這個氏族的並不是家族血脈，其成員都從平原各地精心挑選，天生就能與雍亞拉溝通的半人馬。他們終其一生都在加深與雍亞拉的聯繫，磨練自己的能力。他們最終會被派往各個氏族，為他們提供建議，同時保護我們的土地。\n\n雍‧賽希騰去跟她的可汗談談她看到的預兆。請跟她一起去，了解有關雍伊爾的事。", progress = nil, completion = "能夠回到自己的氏族，感覺真好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66018] = {title = "諾庫德氏族", objective = "陪同托姆爾去找守衛巴依爾。", description = "<桑索克可汗比著手語，歐奇爾隨即為可汗發聲。>\n\n諾庫德氏族是最近才興起的氏族。他們的前任可汗「賈康」建立起一支大軍，重新奪回祖先擁有的地盤。這就是他們一族的做法。\n\n賈康靠自己贏得應有的尊敬，他的兒子卻不是如此。巴拉卡殺死自己的父親，接管了整個氏族。從那之後，他們一族就變得越來越封閉。不過，想要了解莫魯克，就必須了解他們。", progress = nil, completion = "雖然不情願，我還是要在此向你介紹巴依爾，他是巴拉卡可汗手下的一名惡棍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66019] = {title = "榮耀我們的先祖", objective = "協助卡琳‧多圖準備獻給祖先的菜餚。", description = "我們的祖先在雍亞拉之風中與我們並肩而行，指引並保護我們。無論是逝者還是生者，所有的莫魯克人都會為了庫拉爾休戰並齊聚一堂。\n\n這頓飯的香味會將祖先呼喚到我們的火來。在他們抵達時，庫拉爾就開始了。", progress = nil, completion = "先祖為了我們的未來冒了很大的風險。因此需要邀請他們與我們同樂。", rewards = "您會收到：\n\n食譜：三味猛瑪象肉串"}
MultiLanguageQuestData['tw'][66020] = {title = "預兆與薰香", objective = "收集5朵蜜香花，將其磨碎製成蜜香薰香，然後協助雍‧賽希騰舉行儀式。", description = "我和提迦里可汗分享了我們進到莫魯凱以前收到的預兆。她表示擔憂，因為她也覺得風很寒冷。\n\n我們在這裡種植特定的花，磨碎這些花並燃燒就能引發沉思般的效果。我們可以用來加深和預兆的連結。\n\n我希望你去收集一些花來，我們才能做燃燒用的薰香。有了可汗的幫忙，或許我們可以更了解雍亞拉的困境。", progress = "提迦里可汗是最擅長解讀預兆的人。有了她的幫忙，我們可以更了解這個預兆。", completion = "一舉背叛對雍亞拉本身造成了威脅。我們必須勇敢，&lt;name&gt;。該聯合盟友了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66021] = {title = "不歡迎外來者", objective = "擊敗6個諾庫德半人馬。", description = "哈！你看看你。太軟弱了。就像你帶來這裡的那些弱雞獵人一樣。\n\n你想了解諾庫德？我們交流的方式就是戰鬥。\n\n我們的戰鬥儀式叫做「塔巴爾」。我們會訓練，我們會比劃，我們藉此變強。現在，我們的氏族中沒有半個弱者。\n\n談得夠多了。來較量一下吧。", progress = nil, completion = "比起其他任何東西，諾庫德更喜歡用拳頭說話。\n\n在很多事情上，我們的看法並不一致。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66022] = {title = "大可汗瑪托拉", objective = "向可汗禁衛阿卡托回報，參加潔米薩思與大可汗瑪托拉的會面。", description = "我無法在半人馬土地逗留，我必須盡快返回花園。\n\n大可汗瑪托拉已經同意要聽取我們的求援請求。她在莫魯凱中央的建築物可魯塔的頂端等待我的到來。\n\n雖然我必須先親自與她談話，但我也非常歡迎你加入我們。", progress = nil, completion = "愚蠢的叛徒。\n\n&lt;阿卡托朝地上吐口水。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66023] = {title = "打破休戰者", objective = "殺死10個諾庫德部隊的成員。", description = "巴拉卡抹黑了自己的氏族。他對權力的渴望蒙蔽了他的雙眼，讓自己的族人加入風暴的行列。\n\n他們的背叛暴露了自身的脆弱。殺了他們。", progress = nil, completion = "他們選擇的道路如今沾滿鮮血。\n\n斥候托姆爾警告過我們，說這可能會發生。她可能還有進一步的懷疑。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66024] = {title = "蓋住他們的尾巴", objective = "殺死守衛巴依爾。", description = "諾庫德著迷於我們族類在遠古時的戰爭故事。事實上，他們只是弱小又愛玩家家酒的孩子。而隨著一道閃電的打擊，他們切斷了與雍亞拉的連結。\n\n那好！如果他們要走上腐敗之路來尋求戰爭，那我們就讓他們去吧。\n\n當然，巴依爾被留下來指揮，來掩護他逃走。她的血必須染紅泥土。", progress = nil, completion = "巴拉卡一下子就臣服於科蘿洛絲的腐化之力。\n\n風暴已經到來。", rewards = "您會收到：\n\n再生元龍：鬃毛尾巴雍伊爾學徒兜帽席卡斥候頭盔蹄萊看守者兜帽諾庫德劫奪者顱甲"}
MultiLanguageQuestData['tw'][66025] = {title = "諾庫德威脅", objective = "討論後續行動。", description = "諾庫德氏族的軍隊正在佔領莫魯凱。\n\n讓我們在可汗會議廳裡討論接下來的行動吧。我們必須保護莫魯克人的安全。", progress = nil, completion = "莫魯克的生命之血有危險了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66026] = {title = "需要立即的行動", objective = "去蕨皮見布蕾娜。", description = "這些攻擊行動的源頭一定是蕨皮豺狼人。\n\n我們跟蕨皮豺狼人打了好幾代，但在這之前，他們都只是個討厭的存在。\n\n面對這些豺狼人，除了採取緊急行動，我們別無選擇。他們邪惡的腐朽之息會摧毀蒼藍高地，連你在找的東西也不例外。\n\n在蕨皮外圍跟我們碰面。我們需要手頭的每一分助力。", progress = nil, completion = "光是站在這裡，我就能感受到這座森林有多恐怖。這裡相當不對勁。\n\n我已經開始擔心，我不該把我們最厲害的戰鬥者送回伊斯凱拉的。", rewards = "疾風捲裹帶變形皮甲束腕刺藤鍊甲護腕霰耀臂甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][66027] = {title = "召回藍龍", objective = "見證卡雷苟斯召回藍龍軍團。", description = "<name>，我不能再對藍龍軍團重新團結一事恐懼下去了。我們應該要重新團聚為家人…而不是繼續孤守破碎的自我。\n\n就算我無法復原誓言石，我還是能用它的力量對所有藍色巨龍發出訊息。\n\n他們應該收到消息了…收到來自他們守護巨龍的訊息。", progress = nil, completion = "我們必須動身了，&lt;name&gt;。", rewards = "您會學到：\n\n解鎖旋轉急衝\n\n您還會收到：\n\n高地飛龍"}
MultiLanguageQuestData['tw'][66028] = {title = "前往未來！", objective = "前往洪荒使者未來。", description = "我追蹤到克羅諾穆和伊特努斯在一個潛在的未來裡。我不知道你會在那裡找到什麼，我只知道那裡既黑暗又混亂。\n\n索芮朵蜜帶了幾個時光行者去穩定那個未來與這個時空的連結。要讓傳送門維持開啟需要大幅耗用她的力量，所以她得依靠足智多謀的你來助她一臂之力。\n\n見到索芮朵蜜以後，她會給你更多指示。\n\n<name>，快點去找克羅諾穆。", progress = nil, completion = "我們需要找到克羅米和伊特努斯，才能阻止這個時間受到更進一步的傷害。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][66029] = {title = "時間調整", objective = "在洪荒使者未來對克羅米及伊特努斯使用時空水晶，阻止他們繼續在時間當中無限墜落。", description = "克羅諾穆和伊特努斯正在不斷穿梭時空，但我能感知到他們偶爾會停下來。這些短暫的片刻正是唯一能找到他們的機會。\n\n<諾茲多姆召喚出一塊小的時空水晶。>\n\n這個水晶注入了我的力量，它會和我產生時光共鳴。他們到了一個…相當棘手的可能未來。找到他們，然後使用水晶。希望這可以在他們又再次轉移之前，固定住他們的時空座標。", progress = nil, completion = "事情還沒結束，但我現在可以更精準追蹤克羅諾穆了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66030] = {title = "反抗並非無用", objective = "在洪荒使者未來治療反抗軍鬥士。", description = "時光漣漪為這裡的人帶來了麻煩。敵人會出現在之前沒出現的地方，或是比原本還要強大。這些改變雖然微小，但還是可能會造成災難。\n\n我希望你能幫助這裡的反抗軍鬥士。治療他們的傷口，讓他們能夠再次戰鬥。將他們的時間軸重置到正確的軌跡上，就像永遠不曾和我們互動過一樣。這只是小事，但卻是我們可以出力的地方。", progress = nil, completion = "這些勇敢&lt;class&gt;的部隊會再次壯大。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][66031] = {title = "創造時間", objective = "為生存者的營地收集元素精華。", description = "我想我不該對自己在這裡感到太驚訝。\n\n這不是我想要的艾澤拉斯，但這是我僅有的。我們在努力保存剩下的東西，想辦法把世界奪回來，可是你的到來造成了一些問題。\n\n我們會利用外面那些元素的精華，為我們的保護裝置提供能量來確保我們的安全。看到那個護盾了嗎？我們只能依靠它，讓我們不被發現和遭到殲滅，而你把我們的資源用光了。去帶一些精華回來，或許我們就能再撐一天。", progress = "你收集到我們需要的東西了嗎？", completion = "你為我們爭取到一些喘息空間。", rewards = "殲滅守護者披風您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][66032] = {title = "回到現今時間點", objective = "回去找現在的諾茲多姆。", description = "這個時間軸既黑暗又混亂，而且擾動非常嚴重。我想我會在這裡待上一陣子，幫忙撫平可能出現的漣漪。\n\n回去找諾茲多姆。讓他知道我們成功了，即使事情並沒有我們希望的那麼成功。", progress = nil, completion = "你的旅程並沒有達成我們的目標，但依然很成功。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66033] = {title = "前往…過去？", objective = "進入傳送門，去亞茲莫洛斯見安但丁諾穆。", description = "很遺憾我們沒辦法讓克羅諾穆穩定下來，但我們或許還能在另一個地點追上她，讓她停止穿梭時空。\n\n<諾茲多姆皺眉。>\n\n我一生中見識過無數光怪陸離的事，但我瞥見的這條過去時間線…還是十分怪異。\n\n<name>，提高警覺。我不確定你會遇到什麼，但它非常強大，而且…似曾相識。", progress = nil, completion = "不管我以為會是什麼…都和我想像的不一樣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66035] = {title = "魚人微粒", objective = "汲取12個時空微粒。", description = "一個魚人的平行時間軸？！\n\n抱歉我有點自私，不過在你尋找克羅諾穆大使時，可以順便帶一些散落的時光能量微粒嗎？\n\n你只需要走進它們就好，剩下的就交給你的法杖。我等等會再檢驗數據。你知道的，等我們不再忙著穿梭於艾澤拉斯各種現實的時候。", progress = nil, completion = "真是驚人！\n\n說說看，你覺得這個魚人世界裡的魚人會是什麼樣子的？我可不敢想像…", rewards = "您能選擇下列奬勵中的一個：\n\n亞茲莫洛斯之心\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66036] = {title = "呣嚕咕嚕咕嚕！", objective = "姆咯咕嘎咯咕！", description = "姆咕嘎咯咕！咕咕嘎咕嘎！\n\n咕咯嘎咕嘎，咕嘎咕咯，咕嘎，咕咕，咯。姆咕嘎咯咕，咕嘎咕咯，姆咕，嘎咕咯。姆咕咯嘎咕，咕嘎咕咯，咕嘎咕咯，咕嘎咕咯咕，咕嘎咕咯。\n\n姆咯咕咕，嘎，咕咯。\n\n<你不確定對方在說什麼，不過他做出很多戳刺的動作。看來這個魚人希望你能殺死某個東西。>", progress = nil, completion = "喂囉，啦盟！\n\n&lt;魚人似乎感到滿意。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66037] = {title = "返回現實", objective = "回去找現在的諾茲多姆。", description = "我們成功提高克羅諾穆大使和我們時空之間的連結強度了。我敢說等我們再次找到她的時候，就有辦法完成儀式了。\n\n在那之前，讓我們回到現在的時空，那裡的…魚人少多了。", progress = nil, completion = "謝謝你協助維護時間線…它們有時候就是會出問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66038] = {title = "飛速穿越時間！", objective = "飛速穿越時間，追上克羅米和伊特努斯。", description = "<name>，我們必須快速行動才能趕上克羅諾穆大使，而且真的要很快才行！\n\n澤拉跟我會盡可能加速我們的進度，但重要的是必須盡量避免和這個時空有所糾纏，否則會拖慢我們的速度。假如這樣的話，在諾茲多姆的魔法影響克羅諾穆大使之前，我們很有可能追不上她。\n\n我們現在分秒必爭！\n\n", progress = nil, completion = "我的巨龍啊…這裡是黑暗帝國！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66039] = {title = "克羅米時光", objective = "找到克羅米，並完成時光穩定儀式。", description = "這…這裡是黑暗帝國。我們真的穿越到很早以前的過去了。\n\n看那邊！是克羅諾穆大使和伊特努斯！我們得快點行動，趕快完成儀式。\n\n雖然我的好奇心很強，但就連我也不希望看見他們接下來要穿梭到哪個時間去。", progress = nil, completion = "感覺好多了！\n\n喔，不用擔心伊特努斯。我們算是暫時停戰了吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66040] = {title = "回到未來", objective = "保衛你的盟友不受黑暗帝國攻擊，直到時光傳送門被創造出來為止。", description = "我們總算停止無限的時空穿梭了，可是我們在很久遠的過去。非非非常久以前的過去。是「泰坦還沒來到艾澤拉斯」這麼久以前。要回家的話會很…麻煩。\n\n不過我們巨龍辦得到！\n\n但是我們需要你來阻止那些黑暗帝國手下，讓他們不要來攻擊我們。這應該不會花太久時間！\n\n應該吧。\n\n大概吧。\n\n別擔心！你專心阻擋那些詭異的怪物，其他的讓我們來！簡單！", progress = nil, completion = "時間再度穩定下來了。", rewards = "您會收到：\n\n峭壁荒野飛龍奇異的懷錶"}
MultiLanguageQuestData['tw'][66042] = {title = "計畫中的計畫", objective = "在澤瑞斯莫提斯完成世界任務、完成每日任務、搜刮寶藏和殺死稀有生物，以協助盟友。", description = "這裡是暗影之境的起源之地，絕對不能讓這裡也變成暗影之境的末路。\n\n<name>，去找新的盟友合作吧。是否能夠獲得他們的協助將決定我們的成敗，也將決定世間萬物是否會就此灰飛煙滅。", progress = nil, completion = "我們距離目標又更近了一步。繼續前進。", rewards = "您會收到：\n\n受啟迪者長老貢品名望感激禮賜感激禮賜感激禮賜"}
MultiLanguageQuestData['tw'][66044] = {title = "奪下城牆", objective = "解決掉三座攻城強弩和加拉登的勇士丘魯克。", description = "賽柏利安和其他的龍正在阻擋加拉登。我們必須快點奪下防禦塔，確保我們的勝利。\n\n你和我應該清除從上方對我們造成威脅的攻城強弩。\n\n準備好的時候告訴我一聲。", progress = nil, completion = "做得好，&lt;name&gt;。賽柏利安和他的手下會阻擋加拉登，我則要趁機啟動誓言石來恢復力量。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66048] = {title = "最佳計畫與意圖", objective = "與怒西昂部隊的成員一起重新審視計畫。", description = "進攻掌控黑曜龍堡的加拉登絕不是什麼容易的事。就算有怒西昂和他的黑爪部隊，這仍會是一場激戰。怒西昂看起來信心十足，不過…我並沒有那麼樂觀。\n\n也許我們可以跟那些協助制定策略的人談談，看看能不能找到任何改善的空間。", progress = nil, completion = "原來如此。當然，我會謹慎考慮你的評估。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66049] = {title = "黑曜誓言石", objective = "找到黑曜誓言石。", description = "奈薩里奧成為大地守護者時，他曾發誓保護這個世界，<name>。誓言的內容包含守護地底深處，以及與黑龍軍團一起成為艾澤拉斯的防衛者。黑曜誓言石就代表他許下的誓言。\n\n我們必須啟動那顆誓言石，讓整個巨龍群島知道黑龍軍團回來了！\n\n跟我來，<name>。", progress = nil, completion = "這是個阻礙，不過只要有你的幫忙，我們一定可以修復誓言石。跟巴贊圖合作…就能實現目標。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66055] = {title = "破碎的過去", objective = "取回12個誓言石碎片。", description = "誓言石受到損害！有些部分不見了。\n\n盡你所能取回那些碎片吧…或許會有修復誓言石的方法！", progress = "你找到缺失的誓言石碎片了嗎？", completion = "看來碎片都集齊了。我相信我們一定能修好！", rewards = "遠征隊守衛束腰遠征隊研究員束帶遠征隊傭兵腰帶田野偵查員腰帶您會收到：\n\n"}
MultiLanguageQuestData['tw'][66056] = {title = "打造新的未來", objective = "備妥大地守護者的熔爐。", description = "在現存的所有巨龍熔爐中，大地守護者的熔爐是威力最強大的。我們的先人用它打造出強大的武器和護甲，用來保衛艾澤拉斯。\n\n而且它的爐火蘊藏的力量，也是重組誓言石碎片不可或缺的。\n\n走吧，我們得去備妥熔爐，做好準備工作。", progress = "你完成要求的工作了嗎？", completion = "非常好。既然王子已經抵達，我們可以開始了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66057] = {title = "重塑誓言", objective = "復原黑曜誓言石。", description = "四散的碎片已經重組，我們可以開始復原誓言石了。\n\n去吧，協助怒西昂完成修復的工作。", progress = nil, completion = "這會讓事情變得更複雜，不過該屬於我的東西，自然就該是我的！", rewards = "遠征隊研究員窄褲遠征隊守衛護脛遠征隊傭兵腿甲田野偵查員束褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][66070] = {title = "亮刃的骸骨", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66071] = {title = "飛翔大鵬", objective = "援助8隻受傷的藍羽大鵬。", description = "我是哈爾琳‧啾諷教授，聲名遠播的非凡鳥類學家！我來這裡是為了研究巨龍群島神秘的藍羽大鵬，不過我們目前好像有更急切的鳥類問題要處理。\n\n我敢說，這些鷹身人一定是在群島開放的時候，從卡林多飛來的。他們極具侵略性，吃東西的時候簡直就像一群在污水賭場吃到飽的巨魔。\n\n讓我們給這裡的原生種大鵬一個對抗鷹身人的機會吧。帶著這個醫療箱，用它讓受傷的大鵬重新振作起來。", progress = nil, completion = "是羽毛滿滿的任務呢，&lt;name&gt;！\n\n我確實很想幫忙你治療和砍殺，不過我現在比較像是一個「動腦哥布林」。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66074] = {title = "洪荒鐮螳螂女王", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66076] = {title = "遠古角蛙", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66078] = {title = "實力的考驗", objective = "考驗8個黑爪刺客和黑爪復仇者的身手。", description = "我已經精心培植黑爪部隊多年，教導並鼓勵他們向你看齊。\n\n他們或許還不能達到和你一樣的高度，但他們也憑一己之力做出一番成就。我為他們感到自豪。\n\n只要你考校他們一下，就能知道他們的不凡之處。我想你會發現他們身上都有你的影子。", progress = nil, completion = "我相信黑爪部隊已經準備好應付任何狀況了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66079] = {title = "怒西昂等著你", objective = "在黑曜壁壘與怒西昂見面。", description = "這些蛋象徵著龍群的下一代，需要得到妥善的保護和孵育。只是…我的心好痛，而且我很擔心怒西昂。他的固執恐怕會鑄下大錯。\n\n多年來，你一直是值得信任的朋友，<name>。或許你可以代替我，去幫他一把。\n\n到黑曜壁壘去找他。還有拜託，請看好他。他們那一族已經所剩無幾了。", progress = nil, completion = "啊，勇士，你的到來真是太剛好了。既然你來了，我的計畫一定會成功的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66080] = {title = "時光障礙", objective = "在薩爪祖斯的浮動森林找到失蹤的新兵。", description = "你好，<class>。你來得正是時候！\n\n神殿那邊發生了一些意外，讓時間之道變得不穩定，並且擴大到整座山谷。不僅如此，還有一大堆時光行者都失蹤了！\n\n我們已經請求額外的支援，可是有一位新招募者還沒抵達。\n\n你可以去找她嗎？不過要小心，山谷一帶的時間處於相當不穩定的狀態。沒人知道會發生什麼樣的危險！", progress = nil, completion = "我就知道遲早有人會來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66081] = {title = "時間緊迫", objective = "在薩爪祖斯的浮動森林收集8個時光收集石。", description = "青銅神殿遭到攻擊，時間能量已經滲漏到各處。\n\n時光行者在這座森林各個地方放置了收集石，試著收集那些四散的魔法。任何收集到的魔法都可以成為額外的力量！這是件好事，這場危機要把我們的資源都耗盡了。\n\n我應該要負責取回收集石的，但我還需要一點時間喘口氣。\n\n你可以幫我把它們拿來嗎？", progress = "你找到那些收集器了嗎？", completion = "謝謝你，&lt;name&gt;。\n\n現在森林可以慢慢自我修復，時光行者也有額外的能量了。", rewards = "初階時守者護腿初階時守者馬褲初階時守者鱗甲初階時守者護脛您會收到：\n\n"}
MultiLanguageQuestData['tw'][66082] = {title = "瓶中時間", objective = "在薩爪祖斯的浮動森林裡，從殺死的時空充能野生生物身上收集時間能量。", description = "好極了！時光行者法杖毫髮無傷！但它的能量已經耗盡。\n\n我知道了！你可以利用凝聚在野生動物周遭的時間能量來為它重新充能。不幸的是，這代表你必須擊敗森林裡受影響的生物。動盪的能量害牠們變得既危險又不穩定，而且我們必須想辦法削減數量…\n\n有時候，為了更大的利益，你必須做出犧牲。你可以幫忙嗎？我還需要一點時間。", progress = nil, completion = "這根法杖經歷過很多磨難，但它應該可以再次正常運作了。\n\n謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66083] = {title = "彷彿第一次", objective = "與安但丁諾穆交談並參加時光行者訓練。", description = "引導時間之道是個危險的職責。\n\n雖然你不是時光行者，但克羅諾穆大使認為你可以幫上很多忙。不過，為了確保你的安全，我們必須好好訓練你。\n\n很不幸的是，我們全部的指導員依然下落不明。我會盡我所能幫忙，就一起看看我們彼此的表現吧。我知道克羅諾穆大使指望我們兩個來做這件事。", progress = nil, completion = "那還真令人出乎意料！你也看得出來，控制時間魔法會帶來許多危險。\n\n我確實希望能有時間檢視你這個小意外所造成的影響，但我們還有更重要的事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66084] = {title = "這樣的時光", objective = "從時光沙地的時佚敵人身上收集100個時光殘渣。", description = "雖然在訓練中發生了那場小意外，我相信你已經做好足夠準備，可以在這裡援助我們。\n\n山谷裡的扭曲正在使不同的年代和我們的年代交錯。我們不確定這些時間線連接起來的原因，這使人相當警戒。我們需要更多情報。\n\n請你去了解一下那些從不同時間線湧入的生物。它們經過的路徑一定會留下某種殘留的物質。透過研究那樣的物質，我們就有可能找到方法來應對這場危機。", progress = "雖然發生這些事非常不幸，但我很期待能發現新的年表來研究。", completion = "有了這些樣本，就能更理解這些時間線和我們的時間線交錯的方法和理由。\n\n謝謝你的協助。", rewards = "您能選擇下列奬勵中的一個：\n\n因果關係指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66085] = {title = "要是我們能逆轉時光", objective = "在時光沙地和西雅澤拉瑟合力關閉時間裂隙。", description = "盡責的時光行者永遠不會半途而廢。既然我們已經擁有需要的工具，何必繼續乾等和研究呢？\n\n既然你有我本來的法杖，我找到一把備用的來用。它的主人不會想找它的。我的計畫就是，我們合力處理那些裂隙，然後化解今天的危機！事實上，還有其他天的危機。抱歉，時間的事情我還不算完全了解。\n\n你覺得如何？這個任務應該很簡單吧？", progress = nil, completion = "我們成功了！對吧？\n\n好吧，或許有些小波折…但丁不需要知道這些小事。然後還有個出乎意料的訪客…\n\n不過整體來說，我覺得事情挺順利的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66087] = {title = "關閉時間", objective = "在時光沙地協助時光行者，殺死時佚敵人、強化青銅龍盟友、歸還失落的文物，並且關閉時空裂隙。", description = "這些意外將這個時間軸的韌性推到了極限，甚至有可能破裂。要是整個小隊的時光行者都在就好了！\n\n雖然你還是使用法杖的新手，我聽說你依然成功提供我們許多幫助。只要再多加油一下，相信你可以進一步協助我們完成使命。\n\n通常，我會讓你接受完整的訓練，不過現在的時節…非比尋常。把這個進階知識卷軸拿去，然後用它把入侵者趕回去！不過動作要快，這些效果有時限。", progress = nil, completion = "在管理時間的時候，時光行者的法杖是不可或缺的工具。有時候，只需要輕輕戳一下。但有時候，你得採取更有力的作法。這樣應該就可以暫時緩解這個區域的不穩定。\n\n雖然還有更多工作要做，你的夥伴都在神殿急著助你一臂之力。我會確保這邊獲得良好的支援，所以你就放心去吧。\n\n祝你好運。", rewards = "時光行者時光行者時光行者時光行者您會收到：\n\n"}
MultiLanguageQuestData['tw'][66090] = {title = "黑暗遊俠之道", objective = "收下黑暗遊俠戰衣。", description = nil, progress = nil, completion = "&lt;薇蘿娜拉用看穿一切的眼神看著你。&gt;\n\n你的偽裝很不錯，但我一眼就看出這不是你真正的身份。\n\n但無論如何，你冒著生命危險來幫我們，我銘記在心。\n\n希瓦娜斯的華爾琪所復活的卡多雷之中，有些人想回到自己的國家。如果泰蘭妲願意接納他們，他們可以自由離開。也歡迎他們加入黑暗遊俠的行列。\n\n為了表揚你對我們的付出，請收下這份禮物。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66091] = {title = "黑暗遊俠之道", objective = "多年來，我們黑暗遊俠為女妖之王效命，現在，在新的被遺忘者議會領導下，我們為更遠大的目標行動，努力為族人開創美好的未來。\n\n不知道以後會發生什麼事，但我發誓，黑暗遊俠會盡一切力量保衛這個王國。\n\n你的援助，讓我們得以清理羅德隆的廢墟。收下這份心意吧，我們由衷感謝你。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66094] = {title = "薩爾斯克烈思廢墟", objective = "到雍亞拉平原的薩爾斯克烈思附近，與多蒂會合。", description = "從看守者日誌的內容來看，有條河流穿過雍亞拉平原中央，洞察之石就位於河上的龍塔當中。那應該就是薩爾斯克烈思。小心一點。我們可以肯定，碎裂火焰軍絕不會讓我們大搖大擺走進去把它拿走。\n\n你到了那裡，先跟多蒂會合。然後我們再去拿那個石頭。", progress = nil, completion = "你來了。&lt;name&gt;，我有個任務要給你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66100] = {title = "補給重量", objective = "收集6袋道路守衛補給品。", description = "我這次真的搞砸了。我只不過是離開營地一下，但一回來就看到塔拉賽克搶走所有我沒有釘住的東西。\n\n那些補給品很昂貴，而且我也不能再請人送更多過來！我姊姊諾里已經覺得我很無能了。\n\n如果你確定要到山谷去，你可以幫忙注意一下有沒有無主的補給品嗎？", progress = "<艾薇瞥向你的方向，顯然驚慌失措。此時此刻，她的心思似乎不在不見的補給品上。>", completion = "謝謝你，&lt;name&gt;，不過我們現在有更嚴重的事情要擔心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66101] = {title = "登高望遠", objective = "使用勘測員的圓盤，彈跳到空中，偵測附近區域。", description = "多蒂和娜蕾迪亞求立即提交有關周圍地區的勘察報告。\n\n幸好，我拿到一副魔法望遠鏡和勘測員的圓盤，我們可以安全地從天上偵察附近區域。\n\n不幸的是，我有嚴重的懼高症，根本不可能踏上那個裝置。\n\n你沒有懼高症，對吧？", progress = nil, completion = "&lt;阿斯特鬆了一口氣。&gt;\n\n我還以為你一定會從天上掉下來摔死。再次謝謝你替我去冒險。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66103] = {title = "精進實力", objective = "到黑曜壁壘考驗10個黑爪刺客和黑爪復仇者的身手。", description = "我們需要更多部隊協防黑曜龍堡。既然我們已經有了立足之地，接下來就必須確保我們有足夠的新血承擔各種工作。\n\n我們在黑曜壁壘駐紮了其他預備部隊，可以作為我們的生力軍。\n\n他們受過良好訓練，但要是有像你這樣的高手考驗他們的實力，他們一定會獲益良多，我們也能知道他們準備好了。", progress = nil, completion = "謝謝你，&lt;name&gt;。這些部隊現在有了更萬全的準備，這都多虧了你。這個行動需要大量的準備和高超的實力。", rewards = "您會收到：\n\n耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮束帶巨獺毛皮束腕\n                            顯示 28 更多                        雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑戰痕纍纍的鱗片屋克杜魯捕鯨矛蒼藍秘法增幅器生命烈焰之瓶夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][66104] = {title = "法醫生態學", objective = "解剖戈洛克的屍體。", description = "我有點拿不定主意，<name>。薩魯和我已經差不多調查了所有屍體，現在只差臨門一腳，那就是我們無法在方法學上達成共識。要是他能聽我的話就好了！\n\n<生態學家伊斯卡嘆氣。>\n\n現在我們兩個都承受很大的壓力。我甚至還沒提出可信的假說。\n\n你的胃看來挺強壯的。你能不能接手解剖最後兩個戈洛克？我的解剖刀可以借你用。", progress = nil, completion = "傷害濕地的是爭鬥的戈洛克是吧？\n\n&lt;生態學家伊斯卡感到羞愧。&gt;\n\n我現在應該懂了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66105] = {title = "解剖刀解決法", objective = "殺死5個狂暴的水和5個狂暴的風。", description = "我認為我們在這裡能夠安全地收集足夠的數據，可是…\n\n薩魯是位傑出的生態學家，比較希望我們能採取行動。不過，生態系是很脆弱的，一不小心，就可能會傷害到它。然而，我也同樣認為我們時間不多了。\n\n他的做法並非一無可取。應該吧。\n\n消滅一些狂暴元素應該可以幫我們爭取到更多時間，又不會妨礙到我們的研究。記得消滅的元素數量必須相等…我們不希望看到失衡的情況進一步惡化。", progress = nil, completion = "看起來有產生任何影響嗎？沒有嗎？\n\n&lt;生態學家伊斯卡嘆氣。&gt;\n\n好吧，至少我們的研究已經快做完了。", rewards = "遠征隊守衛腿甲遠征隊研究員護腿您會收到：\n\n"}
MultiLanguageQuestData['tw'][66106] = {title = "貝道而馳", objective = "分別從濕喉戈洛克和風鰭戈洛克身上收集15個注水貝殼和15個注風貝殼。", description = "我實在太蠢了，伊斯卡覺得事有蹊蹺的時候，居然還懷疑他。要不是他總是比我多想兩步，他也不可能成為我的研究夥伴。\n\n事到如今，我們還是可以採取行動…為他做出補償。如果元素會暴走都是因為貝殼，那麼你何不潛入它們的營地，從它們黏滑的手上搶走那些貝殼？\n\n帶來成堆的注水貝殼和注風貝殼，讓伊斯卡足以證實他心中的想法。", progress = "那應該夠了。", completion = "伊斯卡和我會把這些帶回生命之池，他們在那裡就不會造成更多麻煩了。\n\n你今天做得很好，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66107] = {title = "救援野生動物", objective = "拯救躁動濕地的野生動物。", description = "就算不是生態學家，也能看出那片濕地出現很大的麻煩。\n\n伊斯卡叫我們在這裡檢驗死去的生物，但我們真正該做的，應該是阻止生物繼續死亡！紅龍軍團的職責是守護生命，不是解剖！\n\n我很尊敬伊斯卡，他本身的才能也很出色，但要是我們等到他做完又臭又長的調查，就來不及拯救濕地了。\n\n我來處理他想太多的問題。你負責進入濕地，一步一腳印地救出一些野生動物。", progress = nil, completion = "好了！濕地復育完成！現在，伊斯卡還在做他的標本…我是說他的研究！\n\n等一下，你說元素一直出現是什麼意思？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66108] = {title = "攻城戰鎚解決法", objective = "殺死『濕喉大王』索咕沫咕和『風鰭大王』烏咕噶咕。", description = "雖然我很高興薩魯終於明白我的觀點，但我也很感激他在我耍龜毛的時候，請你去救那些野生動物。\n\n情況比我們原先預期的還要棘手，幸好他能及時採取行動。根據我們調查的結果，在我們解決戈洛克之前，這場元素暴動恐怕都不會平息。\n\n如果我是薩魯，我覺得最好的辦法應該是直接去找它們的首領。只要沒有帶頭作亂的人，紛爭自然會平息，再也不會威脅到濕地。", progress = nil, completion = "這樣應該就可以讓他們爭奪…至少一段時間了。\n\n感謝你的諸多協助，&lt;name&gt;。", rewards = "遠征隊守衛腕甲您會收到：\n\n"}
MultiLanguageQuestData['tw'][66110] = {title = "給和平一個機會", objective = "向聯盟代表自我介紹。", description = "祝福你與你的同伴，$p。\n\n這場遠征受到了部落與聯盟雙方的保護。我們收到的指示很明確，要協助龍鱗遠征隊的任何成員，不管他們效忠哪一邊。\n\n聯盟代表， 蓋瑞克船長和她的兒子亨利，在營地的另一邊守衛。\n\n我和蓋瑞克船長一起打過天譴軍團。她是可敬的人，對這場遠征會很有助益。\n\n去對她表示你願意協助。讓她知道部落會遵守當初的協議。", progress = nil, completion = "&lt;蓋瑞克船長向你敬禮。&gt;\n\n督軍布瑞卡派你來找我，再一次證實她值得敬佩。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66111] = {title = "入侵的元素", objective = "到翼息大使館殺死15個洪荒元素生物。", description = "龍鱗遠征隊的工匠、技師和探險者根本無力接受戰火的洗禮。\n\n但你和我並非如此，$p。\n\n在巨龍群島上，讓我們利用那股力量，保護那些無法保護自己的人。\n\n清除從北邊入侵的元素生物，讓遠征隊能夠專心追求他們崇高的目標。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66112] = {title = "別忘了製作", objective = "收集洪荒大地核心和洪荒熔火核心。", description = "你以前看過這麼強大的元素生物嗎？\n\n<古朗歡呼。>\n\n我聽守衛抱怨說為什麼要一直跟那些元素戰鬥，但他們沒注意到一點…元素生物越大，就代表製作素材也越大！\n\n不管是為了安全還是其他理由，你到外面去清除元素生物的時候，記得要撿起最大的素材，這樣我就能用那些素材製作一些東西！", progress = "我要先做一個大頭盔才行…不，一支錘子…不，一支大錘子！", completion = "&lt;當你將洪荒核心交給古朗的時候，他瞪大雙眼。&gt;\n\n太開心了！這是我人生中最棒的一天！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66114] = {title = "為了龍后", objective = "與管理者瑟利思特拉一同前往晶紅生命聖殿。", description = "我們保護了珍貴的龍蛋，守護了所有龍群的未來。洪荒使者的所作所為不只帶來種種苦難。\n\n他們還想把我們趕盡殺絕。\n\n我必須馬上告訴龍后。", progress = nil, completion = "情況很危急…但這些年來，我們龍群經歷過許多險境。我們會撐過去的。", rewards = "您會學到：\n\n沃卓肯協調者名望\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66115] = {title = "紅龍的使命", objective = "到晶紅生命聖殿與看管者交談。", description = "我們的使命是關懷及憐憫。我們援助其他軍團不只是為了他們，也是為了整個龍族。\n\n和晶紅生命聖殿這裡的龍裔談話，或許能讓你進一步了解我們。", progress = nil, completion = "希望你已經學會欣賞我們所做的一切。", rewards = "田野偵查員手套遠征隊守衛護手遠征隊研究員手套遠征隊傭兵之握您會收到：\n\n"}
MultiLanguageQuestData['tw'][66116] = {title = "主要威脅", objective = "到閃霜進攻地找指揮官萊薩納克。", description = "有太多脆弱的龍蛋需要保護。如果敵人突破防線，一切就都完了！\n\n我很確定我們的守衛正在戰場上集合，準備把他們趕回去。請去找指揮官萊薩納克，他會讓你的力量發揮最大的效用。", progress = nil, completion = "我會用盡手邊的所有武器來阻止這些敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66117] = {title = "清空戰場", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66118] = {title = "土元素襲擊", objective = "在閃霜進攻地消滅4個暴怒的岩靈。", description = "菈薩葛絲和她的洪荒使者召出巨大的土元素攻擊我們的防禦牆。一定要阻止他們！", progress = nil, completion = "生命聖殿屹立不搖。", rewards = "您能選擇下列奬勵中的一個：\n\n精雕玄武岩戒指\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66119] = {title = "晶紅生命之池：洪荒使者入侵", objective = "進入晶紅生命之池，並阻止洪荒使者攻擊。", description = "洪荒使者一路直搗我們的家園。面對如此猛烈的攻擊，我們猝不及防…讓幾個敵人闖了過去。\n\n其中一個龍獸跟在他們後面追進去，但是一直沒回報他的發現，他可能遭遇不測了。\n\n我會保持警戒，只要我們還沒斷氣，絕不會再放任何敵人過去，不過你必須阻止那些已經闖入的敵人。\n\n去吧！", progress = nil, completion = "這場襲擊對我們家園的傷害會持續多年，可是我們會堅強面對。我們會撐下去…而我們拯救的龍蛋會為我們所有人帶來更光明的未來。\n\n謝謝你。", rewards = "風之翱翔者馬褲咆哮風暴之冠恐懼升騰胸甲晶紅幼龍之殼防火披氅火縛副官頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][66121] = {title = "搶救龍蛋", objective = "從閃霜營地搶救4顆蛋。", description = "洪荒使者偷了我們的龍蛋，用來舉行邪惡的儀式！一定要阻止他們。\n\n幫我們及時取回龍蛋，以免發生憾事。$p，你找到蛋後，就在上面標記。我會確保它們安全送離這個地方。", progress = nil, completion = "只差一點了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66122] = {title = "交戰元龍", objective = "在閃霜營地擊敗3隻元龍。", description = "這些元龍很厭惡我們。他們認為我們是龍族的扭曲版，受到泰坦的操弄和束縛。他們都不懂。\n\n這就是為什麼他們派部隊到我們的城牆下卻不害怕。\n\n他們錯了。\n\n帶著這把長矛，$p。殺死我們的敵人。", progress = nil, completion = "或許他們是我們的血親，我們本來可以視他們為手足…然而，我是不會寬恕他們犯下的殘忍惡行的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66123] = {title = "斬首行動", objective = "在閃霜營地擊敗加茲葛絲。", description = "加茲葛絲是菈薩葛絲底下的邪惡副官之一，正大搖大擺地率領這裡的洪荒使者。\n\n我們來讓他們見識一下，與我們為敵會有什麼下場。", progress = nil, completion = "我們的龍后！", rewards = "田野偵查員肩甲遠征隊守衛肩甲遠征隊研究員披肩遠征隊傭兵護肩您會收到：\n\n"}
MultiLanguageQuestData['tw'][66124] = {title = "勝利退場", objective = "與管理者瑟利思特拉一起逃離閃霜營地。", description = "就我看來，龍后已經撤退到荒野孵化所。那是可以監視當地元龍的哨站…我只希望那裡的防禦足夠堅固。\n\n我們必須立刻前往那裡！", progress = nil, completion = "在龍蛋安全之前，我當時一刻都不得休息…真是鬆了一口氣。。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n再生元龍：微犄角"}
MultiLanguageQuestData['tw'][66126] = {title = "揭開我們的過去", objective = "收集1把組好的鑰匙", description = "將組好的鑰匙交給我", progress = "有了復原的黑曜鑰匙，我們就能為這個熔爐解鎖讓人夢寐以求的功能！", completion = "明智的選擇。所有關於王位的爭吵都無法鞏固我們的防禦工事。我們必須打造武器及裝備來擊退那些加拉登。", rewards = "您會收到：\n\n黑曜貯藏箱"}
MultiLanguageQuestData['tw'][66128] = {title = "接下來的步驟", objective = "到甦醒海岸的龍鱗基地，在探險者的營帳中與多蒂和娜蕾迪亞會合。", description = "就算我們無法明白石頭原本的用途，但發現這些石頭的意義依舊相當重大。\n\n不過在試用石頭之前，我們必須遵守流程。石頭必須先經過檢驗和紀錄，而且相關的報告必須送達聖匣守護者和探險者協會總部。\n\n回基地會合吧，我們可以應付接下來的事情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66129] = {title = "揭開我們的過去", objective = "收集1把組好的鑰匙", description = "將組好的鑰匙交給我", progress = "我們必須拿到遺失的黑曜鑰匙，才能用鑰匙解放的力量，驅逐那些不信者。", completion = "這項貢獻會讓你成為死亡之翼欽選的少數人之一。我們將一同席捲這個世界，宣告暮光之時！", rewards = "您會收到：\n\n黑曜貯藏箱"}
MultiLanguageQuestData['tw'][66130] = {title = "揭開我們的過去", objective = "收集1把組好的鑰匙", description = "將組好的鑰匙交給我", progress = "幫我找到更多復原的黑曜鑰匙，我們就能解鎖黑曜龍堡的所有潛能。", completion = "做得好，勇士。這把鑰匙能讓我們深入了解更多堡壘失落的秘密。", rewards = "您會收到：\n\n黑曜貯藏箱"}
MultiLanguageQuestData['tw'][66131] = {title = "揭開我們的過去", objective = "收集1把組好的鑰匙", description = "將組好的鑰匙交給我", progress = "將更多復原的鑰匙交給我，我們就能進行後續工作。", completion = "謝謝你，&lt;name&gt;。你在此事上的幫助一定能增加我取得王位的機會。", rewards = "您會收到：\n\n黑曜貯藏箱"}
MultiLanguageQuestData['tw'][66133] = {title = "忠誠之鑰", objective = "收集1把大型黑曜鑰匙。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66134] = {title = "艾澤拉斯害蟲控管", objective = "在花園裡殺死8個激動的幼苗。", description = "那邊那位小傢伙！\n\n幫我個忙吧？我的植物要被那些魔花人破壞光了！\n\n各式各樣的元素生物入侵了花園，他們似乎對野生動植物造成了…某種影響。元素能量好像激怒了魔花人，讓他們更瘋狂！\n\n這三個就夠我忙了。拜託你！不然魔花人就要把我的花園搞得一團亂了。", progress = nil, completion = "感謝泰坦，你來了！不然我還真不知道有沒有辦法趕走這些討厭的東西。\n\n那麼，你要不要也幫我這個老龍獸解決花園的其他問題呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66135] = {title = "園丁的學徒", objective = "在花園棚裡清理成堆的垃圾，以找出巴席爾頓領主。", description = "巴席爾頓！巴席爾頓領主，你在哪裡？ \n\n我的行政助理兼學徒，巴席爾頓領主走失了！他很喜歡四處探索，可是他保護自己的能力比我還差。我是個園丁，不是戰士！\n\n可以拜託你去找那個小懶鬼嗎？我需要他在這幫我，我才能夠思考。他通常都在棚子裡翻一堆堆的垃圾。\n\n不過要小心就是了，他一開始可能會有點不友善。", progress = nil, completion = "啊，他在那裡！我可愛的助手。誰是乖小孩啊？好乖的刺小孩？巴席爾頓！誰最刺啊？沒錯！就是你！\n\n咳咳。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66136] = {title = "元素萃取", objective = "在花園裡收集5個含水精華。", description = "一個巨大的火元素幾天前摧毀了一個池塘。我覺得它就是這場騷動的主因，可是它太大了，我們打不過。我們需要想辦法削弱它。\n\n不過，先別說老古爾佩奇派不上用場，我有個計畫！\n\n水元素決定待在藍龍軍團的露臺那裡。只要你能從他們身上收集足夠的精華，或許就能用那些魔法來對付他們。\n\n以火剋火，對吧？嗯，應該是以水剋火。\n\n總之，你趕快開始吧。", progress = "這麼多年來，我從來沒看過這麼多元素生物聚集在同一個地方。為什麼偏偏是我的花園呢？", completion = "太棒了！這正是我們需要的，可以一舉消滅那些火元素。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66137] = {title = "斬草除根", objective = "在花園裡除掉10個入侵的殞命花和鞭笞者嫩草。", description = "我敢說魔花人不是唯一在那邊作亂的野生生物。\n\n雅立史卓莎之樹一直都是我的眼中釘。她的生命魔法會吸引各式各樣的植物和動物，有的好、有的壞。猜猜看，又是誰來處理那些壞生物啊？正是老古爾佩奇我啊！\n\n守護巨龍保佑，我已經老到無法應付這種事了。\n\n管家可沒受過戰鬥訓練，所以，處理生命守縛者的雜草問題就交給你了。", progress = nil, completion = "結果你竟然殺了這麼多，這表示元素生物的問題比我想的還嚴重。至少，雅立史卓莎會感到開心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66138] = {title = "如沙漏裡的流沙", objective = "在花園裡收集8堆風捲時沙。", description = "和花園的其他部分一樣，諾茲多姆的沙漏也受到不平靜的元素生物摧殘。猛烈的風元素生物經過這裡，把裡面的魔法沙撒得到處都是。\n\n沒有這些沙，諾茲多姆在這裡的影響力會被大幅削弱。\n\n身為一個管家學徒，我被交代要無時無刻看守著沙漏。如果你願意代替我收集沙，我會永遠感激你的。", progress = nil, completion = "做得非常好。諾茲多姆昨天告訴我，他希望表達他的感謝之意。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66139] = {title = "終於烈焰", objective = "在花園中使用濃縮水精華來擊敗熾熱煉獄元素。", description = "好吧，小傢伙，我已經幫你把所有的水元素精華放到這個罐子裡了。\n\n只要把罐子朝最大的那個丟過去，應該就行了。畢竟水有什麼時候打不過火呢？這計畫萬無一失。\n\n呃，不過高溫對我的關節不好，所以我會在這裡等著。你一定沒問題的。\n\n祝你好運，小傢伙！", progress = nil, completion = "太棒了！我本來不確定會有效，但能成功真是太好了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66141] = {title = "破碎的傳統，破碎的身體", objective = "在前往鏽松巢穴的路上和加茲與納恩見面。", description = "我親愛的熊怪行為很反常。他們做了…壞事。他們變得更壞了。\n\n熊怪之間以前從來沒打過仗！\n\n我和弟弟成功逃了出來。我來這是為了找人幫忙。他留在我們氏族的巢穴附近。\n\n幫幫我們，不然我們的氏族就要滅亡了！", progress = nil, completion = "我兄弟說的是真的。\n\n比我當初離開的時候還糟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66147] = {title = "水中晶體", objective = "在戈洛克海岸收集4個水晶樣本。", description = "我們現在看起來可能不像，但我們可是專業人士。遠征隊委託我們在這個區域找一批稀有水晶…這可以算是地質勘察。\n\n我還沒有從戈洛克的攻擊中回神。你能好心幫我去找那些水晶嗎？可以的話，請帶回樣本。", progress = "實地工作真累人。", completion = "做得非常好！我會把這個帶去給魯西，看看她的小玩意能拿它來做什麼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66149] = {title = "元素影響", objective = "摧毀3個洪荒使者地縛圖騰，然後更深入鏽松巢穴找納恩。", description = "納恩說不是所有的鏽松氏族都自願跟隨石心與洪荒使者。\n\n有些抵抗者被強制束縛。石塊及泥土從圖騰中流出，困住他們…強迫他們屈服。\n\n將圖騰打碎。讓他們重獲自由！", progress = nil, completion = "我永遠不會原諒洪荒使者讓我們的氏族這麼痛苦。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66150] = {title = "拯救拉札", objective = "拯救拉札‧雷爪。", description = "拉札‧雷爪是我們的靈魂保管人。她保存我們的傳統及歷史。\n\n洪荒使者的信念和我們氏族的完全背道而馳。我就知道她會違抗石心！\n\n石心會不計代價來讓她服從。少了拉札的祝福就稱不上是酋長！\n\n納恩說酋長的守衛卡加爾‧五牙正試著要擊垮她。如果拉札死了，我們的氏族也會一起死去。\n\n去援助她，<name>，而且要有覺悟。他可不會乖乖地讓她走。", progress = nil, completion = "我們的氏族有太多人因為自己的兄弟姊妹作戰而倒下…一切都只為了力量的誘惑。\n\n&lt;拉札發出充滿喉音的低吼，然後漸漸變成一道長長的悲痛低嘆。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66152] = {title = "無處可去", objective = "在荒僻營地和加茲會面。", description = "我們不能待在這裡。\n\n我不知道該怎麼做…接下來要去哪裡…\n\n我們要返回你的荒僻營地。巨牙海民應該會知道鏽松出了什麼事。\n\n如果我們講述並傳承我們的故事，或許這就不會再發生…", progress = nil, completion = "我們的氏族已經支離破碎了。\n\n希望另一個氏族能接納我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66154] = {title = "唾液樣本", objective = "在戈洛克海岸收集12份唾液樣本。", description = "<憔悴的不死族捏了捏鼻梁，然後重重嘆了口氣。>\n\n這會讓我的表現看起來非常糟糕。不知怎麼搞的，我們在一天內就激怒了當地的戈洛克、弄丟了一半的裝備，還少了一個矮人。\n\n根據程序，在這種情況下，我們得發揮出最高效率。去削減那些凸牙敵人的數量，然後把牠們的唾液帶回來給我做進一步的研究。\n\n我只要好東西喔。", progress = "你拿到樣本了嗎？", completion = "嗯，我還真沒想到。這裡竟然真的有人能完成一件事。那句俗諺怎麼說? 兩個給你，一個給我? \n\n&lt;洛威拿起燒杯，喝了一小口。&gt;\n\n啊，就是這個。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66155] = {title = "盧里克的激流泛舟", objective = "搭乘秋步號順流而下。", description = "我沒有想到我兄弟會認同…但我還是很樂見這樣的發展。\n\n時候到了！看看我們的努力有沒有得到回報吧！\n\n和我一起搭上秋步號吧，<name>，讓我們一起順流而下，沿路為伊斯凱拉捕魚！", progress = nil, completion = "呼，真過癮！小船沒有解體真是奇蹟！\n\n非常謝謝你，&lt;name&gt;。讓我們聚在一起，再這樣暢遊一次！", rewards = "您會收到：\n\n烈風迅疾龍：分裂犄角巨牙海民踏泥鞋巨牙海民踢水鞋巨牙海民腳桶巨牙海民涉水靴"}
MultiLanguageQuestData['tw'][66156] = {title = "龍鱗遠征隊名人", objective = "在龍鱗基地與編目員潔可思交談。", description = "你的一舉一動都有人注意，你不斷在證明自己是個知名的探險者！\n\n回去龍鱗基地，我準備了補給品給你，可以幫助你繼續努力工作。", progress = nil, completion = "你的事蹟為所有的探險者帶來了名望。把這些補給品帶走，對你會有幫助！", rewards = "您會收到：\n\n裝滿的龍鱗遠征隊補給背包滿溢巨龍遠征隊補給包"}
MultiLanguageQuestData['tw'][66159] = {title = "最可怕的消息", objective = "在沃卓肯的守護巨龍之座和雅立史卓莎談話。", description = "在你到來之前，卡雷苟斯絕口不提蒼藍高地發生了什麼事。\n\n但不管是什麼事，我都感受到了一股強烈的不祥徵兆，<name>。", progress = nil, completion = "菈薩葛絲！她打算要找出其他同伴…這個消息太讓人不安了。\n\n我們不知道她的洪荒使者會出現在哪裡，一定要保護我們的城市，不受她帶來的混亂影響才行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66163] = {title = "無處可躲", objective = "在沃卓肯殺死6個洪荒使者奸細。", description = "歡迎來到沃卓肯，<race>。\n最近城裡烏雲密布，但我說的可不是天氣。\n\n有洪荒使者在暗中活動，煽動城裡居民的不滿。\n\n我們的敵人十分狡猾，他們偽裝成城裡的普通居民來躲過誓鱗者的追查。他們很擅長躲避衛兵，可是他們應該不會對外來者起疑。\n\n帶著這顆龍瞳石，它可以幫助你看穿他們的偽裝。\n\n去識破那些奸細，殺死他們！", progress = nil, completion = "很好，就把這當作一個警告。讓那些洪荒使者知道，沃卓肯不歡迎他們！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66164] = {title = "盜竊漁人", objective = "在戈洛克海岸取回5個失竊的零件。", description = "既然摩迪根不再舔石頭了，我們現在可以解決問題的癥結了…\n\n那些背信棄義的魚人，他們偷走了我的零件！\n\n我們在這個小不拉幾的村莊才不過一小時，結果！戈洛克就蜂擁過來。洛威在大喊、艾爾娜拉在尖叫，我也在揮著扳手像個瘋地精！\n\n看看你能不能挽回局面，幫我拿回一些零件！", progress = "這狀況差強人意。", completion = "你回來了！我可以開始重新設定地形掃描器 289-07，在情況許可的範圍內讓它運作的。我必須承認，這種海邊的環境稱不上理想。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66166] = {title = "耳目並用", objective = "在沃卓肯找到線索。", description = "洪荒使者一直在對沃卓肯的居民散播他們的惡毒理念。\n\n我們的敵人十分狡猾，在我的誓鱗者面前什麼都不會透露。不過，或許你有辦法靠近去偷聽他們的對話，看看能不能得到什麼寶貴的情報。\n\n我已經在你的地圖上標示了幾個地點供你調查。\n\n還有，把這個魔法石拿去。只要你把它拿在手中，我們就有辦法和彼此溝通。\n\n你準備好了嗎？", progress = nil, completion = "所以，洪荒使者在南方策畫著什麼事情，而鎮南要塞的士兵也一直沒出現…聽起來就很不妙，&lt;name&gt;。非常不妙。", rewards = "竊聽者風帽竊聽者軟帽竊聽者罩盔竊聽者頭盔您會收到：\n\n"}
MultiLanguageQuestData['tw'][66167] = {title = "南方曝光", objective = "前往鎮南要塞大門，試著與要塞衛兵聯絡。", description = "根據你的調查結果，我懷疑洪荒使者正在攻擊伊拉諾格指揮官的鎮南要塞。可是我不能帶我的誓鱗者離開城市，因為那正是洪荒使者樂見的結果。\n\n<name>，我又需要你的協助了。\n\n去鎮南要塞一趟，看看我們面對的是什麼樣的部隊。如果可能的話，試試看聯絡那裡的要塞衛兵。", progress = nil, completion = "陌生人謝謝你，同時也要跟你道歉。在激烈的戰鬥當中很難分出敵我，更何況附近又有這麼多敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66169] = {title = "快意復仇", objective = "在鎮南要塞大門殺死12個熔誓洪荒使者。", description = "洪荒使者出奇不意偷襲了我們。\n\n<維洛米爾厭惡地吐口水。>\n\n我的守衛同伴都被這些怪物無情殺害了。要不是你剛剛及時出現，恐怕我也會和他們一起死去。\n\n我聽見遠處依然有交戰的聲音。說不定還有其他生還者，甚至是伊拉諾格指揮官。\n\n請你幫我分散他們的注意力，這樣我才能偷溜到比較近的地方。\n\n最好的辦法，就是殺掉幾個稱作熔誓者的傢伙。", progress = nil, completion = "做得好，&lt;class&gt;。那些怪物活該被你這樣子教訓！", rewards = "您會收到：\n\n高地飛龍：鎧甲頭部"}
MultiLanguageQuestData['tw'][66170] = {title = "靜默守望", objective = "看見多利蘇爾所見的景象。", description = "<多利蘇爾默默盤旋，用銳利而期待的眼神注視著你。\n\n也許這隻高貴的貓頭鷹有什麼重要的東西想給你過目。>", progress = nil, completion = "&lt;多利蘇爾會意地眨了眨眼。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66173] = {title = "樣本大廳", objective = "探索樣本大廳", description = "你有聽到控制臺說的話嗎？\n\n這裡有個充滿樣本的大廳。裡面有遠古泰坦機械？還是來自其他世界的標本？只有提爾知道裡面會有什麼。\n\n讓我們改變這個狀況吧。", progress = nil, completion = "如果你決定從冒險生涯退休的話，你一定有辦法找到牧龍人的工作。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66174] = {title = "守護巨龍之廳", objective = "探索守護巨龍之廳", description = "守護巨龍之廳嗎？提爾為什麼要把它封印起來？他想要隱藏什麼東西嗎？\n\n這背後可能代表著天大的事情，希望我們能在那裡找到答案。", progress = "我們趁娜蕾迪亞反悔之前快點穿過傳輸器吧？", completion = "我不在意娜蕾迪亞怎麼說，我從一開始就知道你是最好的人選。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66178] = {title = "林地的一天", objective = "到翡翠花園的繁葉棲地與麥琳瑟拉和萊梅克會面。", description = "藍龍軍團派萊梅克來這裡認識並保護我們的花園。\n\n我很高興他們伸出援手。我們的族人數量不多，過去還蒙受極大的損失。藍龍軍團擅長施展強力魔法，我們可以從彼此身上學到很多東西。\n\n來吧。我們來展示一下綠龍軍團在巨龍群島扮演的重要角色吧。", progress = nil, completion = "這裡好平靜。\n\n索姆尼克斯最喜歡來這裡休息，可是…自從他的兒子在半人馬攻擊中喪命後，他一直悶悶不樂。\n\n但我們應該專注於當下。讓我們在這片樹林裡向萊梅克展示我們的使命吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66179] = {title = "未來的種子", objective = "從不同鞭笞者身上收集種子，然後交給花園姊妹。", description = "洪荒使者的攻擊在翡翠花園留下難以磨滅的傷痕。我希望再一次看到它草木茂盛、百花盛開的模樣。\n\n在花園的這片區域中，鞭笞者的數量太多了。花園姊妹可以利用它們的種子培育草木，讓受損的林地恢復舊觀。\n\n消滅鞭笞者並收集它們的種子，然後將種子交給花園姊妹。她們有時候會不忍心傷害其他生物，這對花園整體的發展不利。", progress = nil, completion = "謝謝你。別怕，這些鞭笞者總是會用很快的速度又長回來。它們的數量馬上就會恢復。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66180] = {title = "喚醒古樹", objective = "使用從麥琳瑟拉借來的吐息，喚醒翡翠花園的遠古守護者。", description = "有很多方式可以保障花園的安全，例如請盟友來幫助我們。\n\n有些古樹正在這片林地中沉睡，這些巨大樹人立誓要守護森林及其中的生物。\n\n使用我的龍息碎片喚醒它們。", progress = nil, completion = "其中一個古樹已經死了？是因為冰霜嗎？\n\n這可不是好兆頭。我們需要維持戒備，以防洪荒使者打算再一次襲擊花園。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66181] = {title = "狂亂的防衛者", objective = "殺死狂暴的林爪。", description = "我注意到一件事，這些花園的防禦者各有不同。有巨龍、有龍獸和古樹，甚至還有野生動物。\n\n但是，有個防禦者似乎已經到了走火入魔的地步。在我抵達的時候，牠甚至想要撲擊我！\n\n而既然我們知道這片樹林裡有獵殺的發生，小心謹慎一點也不為過。\n\n遺憾的是，我們必須殺死這頭生物，不然牠就會造成更多傷害。", progress = nil, completion = "花園變得更平靜了，對不對？\n\n你蠻有能力的，&lt;race&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66182] = {title = "蓋瑞瑟斯的研究", objective = "到翡翠花園的深處與蓋瑞瑟斯會面。", description = "除了照料花園外，綠龍軍團還肩負著許多職責。我們也需要守護翡翠夢境，有些綠龍也會專注於其他事情上。\n\n以我的兒子蓋瑞瑟斯為例，他一直對各種魔法很有興趣。\n\n你和萊梅克應該去找他，看看他在做什麼，然後看能不能幫他的忙。", progress = nil, completion = "歡迎！我很感激我的母親對我的研究感到興趣。就算內容有點牽強。\n\n不過我相信萊梅克身為藍龍軍團的特使，對魔法的理解一定比我來得深入，希望我們會有真正的進度。\n\n我們開始吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66183] = {title = "翡翠淚滴", objective = "收集8個翡翠淚滴。", description = "雖然我們是最近才回到翡翠花園，但這裡一直是我們魂牽夢縈的地方。\n\n有很多綠龍還沒從我祖母伊瑟拉的死走出來，我自己也是。我真希望以前能多花點時間陪她，向她學習，聽她說過去經歷的大事件！\n\n在像翡翠花園這樣的地方，當我們流淚時，淚水會變成結晶，其中蘊藏極大的力量。我想到一個辦法，能將這份深切的悲傷化成我們的助力。", progress = nil, completion = "這些樣本真是漂亮，&lt;name&gt;。 現在看看我們能做什麼！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66184] = {title = "生命的繫錨", objective = "將翡翠淚滴的力量注入惰性繫錨。", description = "根據我的研究，我認為有一個方法可以重新建立伊瑟拉和翡翠夢境的連結，並讓她更加靠近艾澤拉斯。\n\n在伊瑟拉死亡時，凜冬女王使用了她的力量，在亞登曠野使她恢復了活力。目前，她和那裡緊緊相連，不過我想，如果我們可以把伊瑟拉帶到翡翠夢境中，我們可以用這些錨來把她留在那裡。\n\n但一切都還只是我的空想。\n\n首先，我們必須把翡翠淚滴的力量注入這些錨內。", progress = nil, completion = "我知道了！我能在這些繫錨中感覺到能量。\n\n當然了，我們只有一個小問題，那就是如何把伊瑟拉從死亡領域帶到生命領域。但是一次先處理一件事。\n\n我會把這些繫錨暫時送去林蔭聖所妥善保管。\n\n我的母親在這裡。她一定有更多想讓你和萊梅克看的東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66185] = {title = "穿越曠野", objective = "到亞登曠野的醒覺林地與索姆尼克斯會面。", description = "老實說，我知道我說過自己沒事，但是，自從蘇列瑟斯去世以來，我一直都過得渾渾噩噩。\n\n一想到我還活著，他卻死了，感覺一切都亂了調。\n\n但我可能還有機會補救這一切。如果我們想要重新掌控遠古枝幹，就只能向伊瑟拉求助，我應該可以幫忙讓她復活。\n\n但是，想要跨越生死已經變得越來越難。我們必須把握時間。\n\n泰蘭妲和瑪法里恩會在那裡跟我們會合。", progress = nil, completion = "你好。索姆尼克斯告訴過我在翡翠花園中的巨大威脅，以及他自己在當中的角色。\n\n但我恐怕這辦法沒有他希望的那麼簡單。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66186] = {title = "代價", objective = "見證決定。", description = "我渴望回到翡翠夢境，保護花園不受洪荒化身和他們追隨者的侵犯。但在我跟凜冬女王之間還有連結時，我就無法離開亞登曠野。\n\n我不敢要求任何人這麼做，除非他們接受隨之而來的後果。就像我當初一樣。\n\n不過，有一個人可以取代我的位子。", progress = nil, completion = "就這麼決定了。我會留在亞登曠野。\n\n我會留下來保護夢境，以及從中而生的所有希望。必須由我來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66187] = {title = "瘋狂摩迪根與水晶國王", objective = "在戈洛克海岸使摩迪根‧鐵顎去水晶化。", description = "外圍我都偵察過了。摩迪根很可能在這座洞穴裡面。\n\n<從洞穴入口傳出沉悶的詛咒和咒罵回音。>\n\n他絕對就在這座洞穴裡。\n\n魯西說這些水晶有著危險的脫水特性。看你能不能把他跟他的…地質發現分開來。盡量別讓他傷得太嚴重。\n\n他在這個領域裡蠻受到敬重的。", progress = nil, completion = "很粗魯的做法，不過我很感激你腦筋動得這麼快，而且…足智多謀。", rewards = "您會收到：\n\n再生元龍：漸層犄角鹽水晶戒指"}
MultiLanguageQuestData['tw'][66188] = {title = "風暴之棲", objective = "到醒覺林地啟動重生之珠。", description = "我們前往醒覺林地吧。只有凜冬女王才能把這個繫絆從伊瑟拉身上轉移給我。我相信她會答應的。她在緊急的時候幫助了伊瑟拉，而現在換伊瑟拉來幫助我們了。\n\n一旦凜冬女王答應請求，將羈絆轉移到我身上，我應該就無法清醒太長的時間。羈絆所帶來的負擔將會沉重難當。\n\n希望我某天能再度醒來，看到這棵新生的樹木完全茁壯成長。", progress = "我很想再一次見到翡翠夢境蜿蜒的大片植被。", completion = "事情辦好了。瑪法里恩會代替我在這裡沉睡。而泰蘭妲則會繼續照顧她的子民，如同她幾千年來所做的那樣。\n\n現在，我們必須做好準備。當我跨進翡翠夢境之後，會有一個短暫的空窗，你可以在那個時候加入我。\n\n你準備好了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66189] = {title = "步入生命", objective = "與伊瑟拉在翡翠夢途殺出一條血路，進入遠古枝幹。", description = "事不宜遲。我能感覺重生的能量在我體內奔湧。我準備好再次跨進翡翠夢境了。\n\n從死亡領域到生的領域。\n\n跟我一起穿過覺醒之門，我們將穿越翡翠夢途抵達遠古枝幹。我預計途中會遇到一些阻礙，所以我們得提高警覺。", progress = nil, completion = "狀況比我想的還糟。我可以破壞包圍林地的冰塊，但我們現在腹背受敵。而且我們必須想辦法解除屏障，讓其他人順利進來。\n\n我們必須迅速行動並殲滅這些敵人，好讓麥琳瑟拉和其他人加入我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66190] = {title = "非常靠近", objective = "與萊梅克一起進入夢境之門林地。", description = "我得好好跟你道謝，<name>，感謝你幫這麼多忙。\n\n說實話，我從未想過能有機會欣賞遠古枝幹中的夢境！畢竟我只是一個卑微的使者！真是榮幸。\n\n索姆尼克斯領主已經慷慨地邀請我進入林地，讓我看看傳送門。如果你願意加入我，那會是我的榮幸。\n\n我這一生都會記得這個時刻的。請和我一起見證吧。", progress = nil, completion = "我…不相信…\n\n這不可能。\n\n我失敗了。我相信萊梅克和他的龍族，而他們背叛了我們大家。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66191] = {title = "卻依然遙遠", objective = "與麥琳瑟拉交談。", description = "在這裡，我不能像以前那樣溜入夢境之中。由於枝幹的防禦啟動了，我們基本上被擋在了外面。\n\n但我擔心這只會讓事情更糟，<name>。\n\n我相信萊梅克不只是騙我們進入夢境，他還在尋找夢境中的某種東西。某件我發誓要保護的珍貴且強大之物。\n\n連蓋瑞瑟斯和索姆尼克斯都不知道它的存在。但現在我別無選擇。你必須知道真相。", progress = nil, completion = "我們的情勢險峻。萊梅克給我們的選擇不多。\n\n他強迫我們做出極大的犧牲。\n\n儘管我們無法從這一側進入林地，但遠在生命的領域之外，仍有辦法進入。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66196] = {title = "求助呱呱", objective = "將被泡泡困住的小鴨子帶回生態學家的營地。", description = "<這隻小鴨子在泡泡裡瘋狂掙扎，發出恐懼的叫聲。>\n\n<也許生態學家會知道如何幫助牠？>", progress = nil, completion = "我們會照料小搖擺。要是你找到其他迷路的小鴨子，記得通知我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66201] = {title = "戰爭之蹄", objective = "將大可汗瑪托拉的訊息傳達給蹄拉凱的可汗禁衛杰柏泰。", description = "巴拉卡會領軍出征。我也會這麼做，但我們寡不敵眾。\n\n巨龍曾向我們求助，我們或許可以借他們的力量來扭轉劣勢。為了向巨龍盟友求援，我必須吹響德魯沙之角，但我需要雍亞拉的祝福。你願意幫我嗎？\n\n去蹄拉凱一趟，將我的宣戰布告交給我的副官杰柏泰。他會派出我的部隊，並且指引你去找侍奉雍亞拉的秘法師。", progress = "外地人，有什麼事嗎？", completion = "&lt;杰柏泰閱讀訊息，神情變得越來越憂慮。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66203] = {title = "沉浸其中", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66210] = {title = "家人團聚", objective = "到伊斯凱拉附近收集4個殯葬祭品，然後將其放入殯葬船。", description = "你的朋友卡雷苟斯想要聊聊地脈的事，不過喪禮的準備工作也不能拋開。\n\n當我跟他會面的時候，你能不能去伊斯凱拉附近收集一些祭品，然後放在親愛的老波諾里亞的殯葬船中？\n\n另外，我也希望你能稍微逛逛這個村莊！我的族人會熱情地歡迎你，更何況你還幫我們對抗蕨皮。", progress = "你有沒有幫自己裝碗湯？", completion = "你的朋友的好奇心真旺盛！他到底什麼時候能休息一下？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66211] = {title = "蕨皮谷：前往源頭", objective = "進入蕨皮谷，面對『腐朽族母』怒眼。", description = "我們非常感謝你幫助擊退蕨皮豺狼人。\n\n但是他們還在繼續聚集，從蕨皮谷深處的某個來源積蓄惡濁的腐朽魔法。更糟的是，我們已經好幾個星期沒有那個區域的巨牙海民的消息了！\n\n我擔心那裡發生了什麼可怕的事。我們必須保護我們的家園。拜託你，集合你的部隊，找到我們的同胞，並試試看阻止到處的腐化！", progress = nil, completion = "伊斯凱拉要是沒你就慘了。", rewards = "不腐翠葉面具腐膿枝根護肩腐朽之母的怒視您能選擇下列奬勵中的一個：\n\n巨牙海民骨製項鍊染血的婚戒\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66212] = {title = "釣魚：副翼海蛾魚", objective = "到巨龍群島各地，從海裡釣起5隻副翼海蛾魚。", description = "這年頭已經沒人知道怎麼好好捕魚了嗎？\n\n<魯克圖盧生氣地抽動鼻子。>\n\n你這個傢伙，去捕些魚來給我。要是好魚。還有，別抓葛藍勾魚！", progress = "嗯，那你捉到了什麼？\n\n最好不要是什麼乾扁的小鯷魚。", completion = "嗯哼。\n\n嗯…哼。\n\n…還算可以。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66213] = {title = "編織故事", objective = "跟波雅長老說個魚的故事。", description = "我親愛的妻子，波雅，她很會說故事。\n\n但是已經三十年了，她不斷地重複講同一個故事！拜託你，<class>，去跟波雅聊聊，讓她有新的故事可以說。\n\n你說什麼？告訴她你的冒險故事嗎？別開玩笑了，我才不想聽這種東西！最棒的故事絕對都跟魚有關。跟她說一個魚的故事，就算要用編的也行！", progress = nil, completion = "謝天謝地，有新的故事。\n\n讓我們聽聽看！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66217] = {title = "尋賞：海岸徘徊者克洛傑", objective = "殺死海岸徘徊者克洛傑。", description = "我們注意這條叫做克洛傑的大鯊魚好多年了，等著獵捕牠的最佳時機。\n\n牠的狩獵範圍漸漸地離海岸越來越近。這代表時機已經到了。集合你的狩獵隊，一定要補到牠！", progress = nil, completion = "這就是海洋的生命循環。有些我們會放生，有些我們會殺死，有些我們會吃掉。一切都保持平衡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66218] = {title = "亂跑的小淘氣", objective = "找到尼洛和納烏。", description = "又見面了。\n\n可以幫我和諾魯克一個忙嗎？我們的孩子，尼洛和納烏，跑去玩了。他們應該知道現在該回來了才對。\n\n可是我走不開，拜託你幫忙去找他們。他們知道怎樣照顧自己，可是我擔心他們遭到了危險。", progress = nil, completion = "大家都說，豺狼人又壞又危險。可是，牠只是個寶寶呀！\n\n媽說我必須照顧納烏，她也是個寶寶。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66221] = {title = "繼續前進", objective = "到沃卓肯的守護巨龍之座與雅立史卓莎交談。", description = "既然青銅誓言石已經恢復，雅立史卓莎可以繼續她的計畫了。\n\n去沃卓肯吧，<name>。她一定想知道你的好消息。", progress = nil, completion = "&lt;name&gt;，你為我們做了這麼多，請接受我們最誠摯的謝意。等時機成熟，我會再通知你陪我進行下一個步驟。", rewards = "您能選擇下列奬勵中的一個：\n\n生命守縛者指環\n\n您還會學到：\n\n冒險模式\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66222] = {title = "風暴前的寧靜", objective = "向蹄拉凱的居民傳達杰柏泰的命令。", description = "諾庫德極為強大，而且盟友眾多。我們需要傾盡全力，才能跟他們一戰。\n\n<name>，你得到大可汗瑪托拉的信賴。她的命令是召集我們的朋友，並讓族人做好準備。\n\n我需要你的協助。去找賀津，叫他動員剩下的可汗禁衛。向遊俠昆亞古示警，說諾庫德可能會入侵。通知艾古拉準備接收傷患，然後告訴堅賽把糧食準備好。\n\n至於秘法師，我記得他們最近剛離開。我會看看是否還有人留在蹄拉凱。", progress = nil, completion = "我不希望造成恐慌，但族人必須做好準備。諾庫德氏族絕不會手下留情。", rewards = "諾庫德劫奪者腿鎧雍伊爾學徒護腿席卡斥候馬褲蹄萊看守者馬褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][66223] = {title = "我們可以養牠嗎？", objective = "把7條凍寒魚帶去給尼洛，可從伊斯凱拉的商人那獲得，或是在巨龍群島的任何海水域捕魚獲得。", description = "他只想要吃掉我們，因為他太餓了！\n\n魚！沒有人能拒絕美味、冰涼的生魚！\n\n凍寒魚是世界上最好吃的。在海洋四處都可以釣到這種魚！就算你一條都釣不到，伊斯凱拉的金酷杜也一定能賣你一些。\n\n多帶點魚來給我，要多到他不再感到飢餓才行！", progress = "好多魚喔！我好想全部吃掉！\n\n…但是不行。這些都是給斯卡普的。這很重要。", completion = "斯卡普一定會很喜歡的，然後我們會變成最好的朋友！", rewards = "尼洛的備用毯子您會收到：\n\n"}
MultiLanguageQuestData['tw'][66224] = {title = "神秘的秘法師", objective = "和波庫會面並前往嶺水靜地。", description = "很抱歉，我對雍亞拉的通靈失敗了。你需要找別人來完成大可汗瑪托拉的要求。\n\n幾天前，我的秘法師同行收到提迦里可汗的緊急召喚，都到嶺水靜地去了。他們應該還在那裡。\n\n到城鎮的外側見我。至少我能為你帶路。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66225] = {title = "搬運圖騰", objective = "在嶺水靜地向諾庫德族取回8個圖騰。", description = "波庫問我為什麼要捎訊息召喚所有的秘法師到嶺水靜地去。\n\n但我沒有送出這樣的訊息。巴拉卡故意把我的秘法師引入陷阱中，要打擊雍伊爾氏族。\n\n不過也可能有其他原因。諾庫德族在收集所有他們能取得的秘法圖騰。這些圖騰受過雍亞拉的祝福。\n\n諾庫德這麼做的動機依然不明，但我們不能讓他們奪走雍亞拉的贈禮。盡你所能奪回越多圖騰越好。", progress = "圖騰裡注有雍亞拉的風之魔法。\n\n然而，諾庫德族背棄了她的教誨。他們打算做什麼？", completion = "這麼多圖騰。這麼多秘法師逝去了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66226] = {title = "情感支持夥伴", objective = "到嶺水靜地，從諾庫德手中救出可憐的生物。", description = "請別傷害我…\n\n什麼？你是來幫忙的？你得救救那些動物！\n\n諾庫德無預警地攻擊了我們。我們全都拚命地逃跑！我跳進湖中，驚險地躲過一劫。\n\n那些動物！牠們被我們留在原地。拜託，我求求你，拯救那些動物。誰知道諾庫德會用什麼樣的殘忍方式對待牠們呢。", progress = "身為學徒，我們透過醫治受傷的生物來練習我們的治療技術。\n\n我們當時照顧的動物有四隻。不管你能救多少，我們都會感到很寬慰的。", completion = "你救了牠們！牠們有點筋疲力盡了，但至少還活著，而且會復原的。\n\n謝謝你，陌生人。請收下這個，這代表我們的無盡感激。", rewards = "您會收到：\n\n感激之岩"}
MultiLanguageQuestData['tw'][66227] = {title = "好好釣魚", objective = "在庫瑞的釣場釣到3尾藍尾小鯉。", description = "又來了一個幫手！我需要幫忙補到足夠的魚好帶回家做飯。\n\n祈倫托的人似乎很擔心那些稱為魔法異象的東西…天曉得那是什麼。\n\n不過只要你努力貢獻自己的力量，這裡永遠歡迎你們。\n\n拿起魚竿開始釣魚。幫手一多事情就簡單了！", progress = "如果你需要一點提示，就告訴我一聲。", completion = "啊，這樣就行了！謝謝你，冒險者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66228] = {title = "安東尼達斯營地", objective = "在安東尼達斯營地與全憶者諾麗可會面。", description = "祈倫托已經在這裡的南邊設立主要營地，叫做安東尼達斯營地。\n\n諾麗可和卡德加目前都在那裡，他們在召募願意協助卡雷苟斯復原蒼藍誓言石的冒險者。\n\n如果你有意助我們一臂之力，請去那裡一趟。", progress = nil, completion = "啊，&lt;name&gt;。很高興見到你…\n\n等等…你感覺到了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66230] = {title = "速寫要求", objective = "取回艾薇的「分類帳」並交還給道路守衛艾薇。", description = "塔拉賽克奪走了他們的利爪能拿到的所有東西，包含我的偵查分類帳。\n\n這些體型過大的蜥蜴會大量囤積飾品和戰利品。我敢說他們把我的分類帳藏到某個地方去了。在你通過關口時，可不可以順便幫我找找? \n\n噢，還有<name>？如果你真的找到了，請不要看裡面。裡面的內容有點…私人。", progress = "你還有找到其他的東西嗎，<name>？", completion = "啊…你真的找到了。\n\n說真的，這比較像是素描本，而不是帳本。從我有記憶以來，我就更喜歡畫畫，而不是偵察…\n\n&lt;艾薇長長的嘆了口氣。&gt;\n\n要是我好好完成我的工作，或許諾里就不會受傷了。\n\n我必須改正這件事…但不知道我能不能獨自辦到。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66232] = {title = "到鹽為止", objective = "在戈洛克海岸收集120塊水晶薄片。", description = "雖然沒人問，但我們不介意在我們的小地方招待你和你的朋友，不過你願不願意當個好鄰居，在你去溫泉的時候幫我帶回一些水晶薄片呢？水晶薄片能讓我們保存各種東西。這是這一帶保存食物的重要方法。\n\n比較大隻的戈洛克身上都蓋滿了這種東西。或許你能從他們身上拿一些回來？", progress = "既然你提了，我其實挺餓的。", completion = "有這些應該就可以用很久了。我們可能會考慮讓你的朋友留下來…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66236] = {title = "捕風", objective = "到風頌高地與波庫會面。", description = "諾庫德族在收集圖騰。洪荒使者在捕捉歐胡納鷹。而雍亞拉也陷入沉默。\n\n無論諾庫德族的計畫是什麼，我們必須阻止他們。你和波庫要到風頌高地去。我們的敵人很有可能已經在那了。\n\n到那裡去尋找雍亞拉。如果她的子民身處險境，她一定會前去找他們，而我們必須幫忙。疾風之母非常強大，但我害怕洪荒使者的能耐。", progress = nil, completion = "巴拉卡和這些洪荒使者踐踏了我們最神聖的信念。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66239] = {title = "散播腐朽", objective = "去貿易哨站見布蕾娜。", description = "<布蕾娜用她厚厚的手不斷翻轉著卡格波的圖騰。>\n\n卡格波只是棋子。他不是這個腐敗的根源。在腐朽之息進一步擴散前，我們必須找到它。\n\n最靠近這裡的巨牙海民是個貿易哨站，過了往伊斯凱拉的那座橋就是了。\n\n我們應該去跟他們確認一下…而且要快。", progress = nil, completion = "就和我擔心的一樣，他們也被攻擊了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66242] = {title = "天氣控制", objective = "殺死8個颶縛精華和6個風暴召喚者學徒。", description = "這個不自然的風暴充滿魔法。這樣看來，諾庫德在學習操控風頌高地的神聖精華來製造風暴元素。有些人的成果斐然，比起其他人…\n\n<波庫指向附近可憐的諾庫德學徒，他因為閃電灼傷依然冒著煙。>\n\n<name>，我們不能讓他們繼續這樣。", progress = nil, completion = "我不想見血，但是我們非得阻止諾庫德族。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66243] = {title = "希望之禮", objective = "到醒覺林地與珊蒂斯‧羽月會合。", description = "你好，淵喉行者。\n\n我帶來了凜冬女王的傳喚。她希望你前來亞登曠野見證由你們世界許多人共同參與的儀式。\n\n珊蒂斯‧羽月也會出席。你可以到醒覺林地找她。", progress = nil, completion = "凜冬女王的禮物…我們居然能親眼見證…\n\n&lt;珊蒂斯的眼中閃爍著希望的淚水。&gt;\n\n我們必須請伊瑟拉幫我們保護這顆珍貴的種子。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66244] = {title = "前往沃卓肯", objective = "前往沃卓肯，並與『生命守縛者』雅立史卓莎會面。", description = "多虧有你，我們才能驚險地避開一場大災難。\n\n不過，我們應該和其他守護巨龍會商、跟大家分享這裡發生的事。\n\n請在沃卓肯內的守護巨龍之座與我會面。菈薩葛絲和她的洪荒使者打算做什麼，我很肯定其他人會有他們的見解。\n\n這裡的北部偏東有個通往薩爪祖斯的岔口。這趟飛行的景色很優美，但別耽擱太久了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66245] = {title = "勿忘亡者", objective = "收集8個鎮南要塞璽戒。", description = "我有好多同袍戰死了。\n\n拜託…幫忙收集可供辨識身分的璽戒，這樣他們的名字才不會被遺忘。", progress = "英雄，事情進行得如何了？你有找到璽戒嗎？", completion = "緬懷他們的英雄事蹟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66246] = {title = "戰爭迷霧", objective = "在鎮南要塞大門尋找守護者維洛米爾的小隊成員。", description = "洪荒使者毫無預警，突然發動攻擊。我的小隊想要聯絡伊拉諾格指揮官，但我們還沒抵達要塞的另一側就被攔截了。\n\n戰鬥相當激烈，我的領隊塔里克士官獨自對付三位洪荒使者，而卡歐拉、米寇爾和我則在他身邊跟別的敵人戰鬥。\n\n在我倒下之前，慘叫是我最後聽到的聲響。\n\n拜託你，<race>。要是你看到我的小隊成員，讓我知道他們出了什麼事。", progress = nil, completion = "我…聽了好難過…但我能理解。謝謝你，&lt;class&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66247] = {title = "稍微使用過的武器", objective = "收集6個熔誓長矛。", description = "這把長矛的前任主人已經不行了，但是長矛本身的狀況倒還不錯。\n\n守護者維洛米爾說，要留意任何有用的資源。或許你可以從熔誓者那裡多取得幾支這樣的長矛。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n熔誓矛頭\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66248] = {title = "綑綁在一起", objective = "收集5個沉重繩索。", description = "這捆沉重的繩索看起來狀況很好。\n\n守護者維洛米爾說過要留意有用的材料。也許你可以再找幾捆過來，他可能會用得上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66249] = {title = "掃蕩天空", objective = "操控攻城蠍弩，擊落空中的熔誓真裔。", description = "你做得很好，收集到這些長矛和繩索。有了它們，就可以確保那些傲慢的洪荒使者不再霸佔天空！\n\n樓梯上方有個平台，上面有好幾台攻城蠍弩。綁上繩索當弓弦、長矛當箭矢，應該就可以把那些熔誓者的龍從空中打下來！\n\n這樣就能清出一條安全通往塔上的路，讓我們繼續搜尋伊拉諾格指揮官的下落。", progress = nil, completion = "做得好，&lt;name&gt;！總算減輕了一點壓力。\n\n但可別就此放下武器，跟他們的戰鬥還沒有結束。", rewards = "您會收到：\n\n高地飛龍：上鉤犄角"}
MultiLanguageQuestData['tw'][66250] = {title = "長官在哪裡？", objective = "在鎮南要塞大門陪伴守護者維洛米爾並檢視暸望塔。", description = "<name>，堡壘只剩這裡我們還沒搜索過。如果伊拉諾格指揮官還活著，肯定就在這邊。\n\n<維洛米爾望向附近的門口。>\n\n我們走吧，去看看到底是什麼狀況。", progress = nil, completion = "該死的東西！指揮官竟然是幕後的黑手？真不敢相信他會這樣背叛我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66251] = {title = "滅火鬥士", objective = "殺死熔岩爪。", description = "伊拉諾格指揮官背叛了我們，任憑這頭野獸為所欲為。\n\n你已經幫了我許多忙，可是以我目前的情況，我實在沒辦法應付那頭怪物。\n\n拜託，再幫我最後一個忙，確保鎮南要塞的大門不會落入洪荒使者的手中。\n\n我們必須殺死他們的領袖！\n\n<name>，請你幫幫我。", progress = nil, completion = "洪荒使者的領袖死了，沃卓肯的增援部隊應該能夠輕鬆解決他們。", rewards = "熔岩爪裹帶熔岩爪腕甲熔岩爪腕鱗熔岩爪護腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][66252] = {title = "報到", objective = "返回沃卓肯並向卓萊恩隊長回報。", description = "洪荒使者的威脅已經得到削弱，<name>。來自沃卓肯的部隊很快就會進去，清除殘留的餘黨。\n\n你應該回到城裡，把剛才發生的事通知卓萊恩隊長。她會有興趣知道這裡和伊拉諾格指揮官的事。\n\n再次感謝你所做的一切，<name>。", progress = nil, completion = "伊拉諾格投靠了洪荒使者？火焰與鱗片啊，這真的太可惡了！\n\n還好，你成功阻止洪荒使者攻下鎮南要塞。\n\n這可是不小的壯舉。感謝你對沃卓肯的貢獻，&lt;name&gt;。我們會銘記在心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66253] = {title = "失竊的貨物", objective = "朝竊賊投擲爆炸派以取回1件貨物。", description = "希莉和贊卡拉的貨物一直進來，我們根本來不及！不過某個工人似乎覺得我不會發現他在偷貨物。\n\n這裡的哥布林在研發一個能教訓這個小偷的裝置：爆炸派。\n\n找到坎亞庫，朝他丟派。他一定是在某個地方作怪。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66254] = {title = "悲觀秘法師", objective = "把強化圖騰放在波庫周圍。", description = "戰爭？巨龍？你需要我連絡雍亞拉？\n\n我做不到！我完全聽不到雍亞拉。我只是名學徒，而雍亞拉似乎把我身上的祝福收回去了。或許是我不夠優秀…\n\n<波庫開始翻找他的包包。>\n\n在我的導師指派我到這個氏族來時，她把這些小圖騰贈與給我。她說如果我有一天懷疑自己，它們就會給我力量。\n\n你願意幫我放置圖騰嗎？我要再呼喚雍亞拉一次。", progress = nil, completion = "還是一無所獲。雍亞拉依舊沒有任何回應。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66256] = {title = "一視同鷹", objective = "在風頌高地釋放6個雍亞拉之子並擊殺6個洪荒使者。", description = "我們已經發現諾庫德族收集秘法圖騰的原因了。他們用圖騰來困住雍亞拉之子。雖然諾庫德族是出力的人，不過洪荒使者才是這個瀆神之舉的指使者。\n\n雍亞拉之子是我們最神聖的歐胡納鷹，是受過疾風之母親自祝福的。<name>，請你釋放所有你找到的歐胡納鷹！然後，如果你遇到任何洪荒使者…\n\n<波庫話沒有說完，但他的表情帶著冷酷的決心。>", progress = nil, completion = "雍亞拉為我們做了這麼多，我們必須盡全力幫助她的孩子。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66257] = {title = "邪惡巫術", objective = "使用波庫的風圖騰來摧毀諾庫德貨車。", description = "據說，雍亞拉將自己的力量注入了我們的祖先莫魯克長矛之中。巴拉卡可汗一定把這個傳說跟洪荒使者說了。\n\n他們從雍亞拉的孩子身上偷走了魔法，用風暴妖術汙染了它，再把它注入弩箭之中。為什麼諾庫德族會需要這樣的武器？\n\n我們不能放任他們去用這武器。他們把這些風暴之箭放到貨車上進行運輸。把我的圖騰拿去，遇到貨車的話就放一個上去。我的風魔法會把它們擊成碎片。", progress = nil, completion = "外頭一定還有更多，但我們已經盡力摧毀一些了。希望這至少能拖延他們的行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66258] = {title = "喔不，雍亞拉！", objective = "在波庫試圖釋放雍亞拉時，擊敗來犯的敵人。", description = "洪荒使者正在束縛雍亞拉，但效果有限。她似乎沒有注意到我們。\n\n提迦里可汗會說：「就連微風都能推倒搖搖欲墜的石頭。」如果我可以稍微干擾她的法術，雍亞拉可能就會有辦法掙脫。\n\n我有個主意，你去讓守衛分心。", progress = nil, completion = "剛剛的翻滾真劇烈。我們能活下來真是走運。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66259] = {title = "壞消息風暴", objective = "去向莫魯凱的大可汗瑪托拉報告。", description = "<name>，我們需要把發生的事都告訴大可汗瑪托拉，包含雍亞拉被捉的事。\n\n你必須盡快趕去莫魯凱。你得自己過去。我在墜落時受了傷，只會拖累你。\n\n不用擔心我。我之後會趕上的。去吧！", progress = nil, completion = "這是很糟糕的消息，&lt;name&gt;，但我們不能喪志。我們受了挫，但還沒有戰敗。", rewards = "您能選擇下列奬勵中的一個：\n\n雍亞拉的雕刻\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66261] = {title = "一個小挫折", objective = "找到戴崔。", description = "啊，冒險者！你正是我希望能遇見的全副武裝的流浪戰士。\n\n我來到這個荒煙漫草的地方是為了處理重要的祈倫托業務。在開始設置營地的時候，我卻被骯髒粗魯的豺狼人追趕了。\n\n事實上，這附近聚集的豺狼人多到堪憂。數量夠多的話，就會威脅到整個高地。\n\n但是不用擔心，因為我有一個計畫！到那邊的湖跟我會合，我會解釋一切給你聽。", progress = nil, completion = "現在，開工吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66262] = {title = "汙水清理", objective = "從湖中清除6個腐物堆。", description = "當務之急，我們需要把我的行動基地奪回來！可是，這裡有這麼多元素生物到處亂竄，讓人連找個立足點都很困難。\n\n當然，這都是那些卑鄙豺狼人的錯。\n\n豺狼人把一大堆垃圾、臟器和雜七雜八的東西丟進湖裡，當地的元素生物因此開始暴走。\n\n發揮一下善心，幫忙清理一些更噁心的髒東西，別讓情況變得無法收拾。還有，更重要的是，別讓我的長袍沾上洗不掉的汙漬！", progress = nil, completion = "我已經嘗得出不同了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66263] = {title = "精準的做法", objective = "殺死剝拳。", description = "豺狼人是很糟糕的生物。很臭。老是一邊抓癢，一邊對著你笑。這裡已經有一大群，而且陸續還有更多。就算說我們，呃我是說你，可以把他們當麥子一樣收割個幾天，可是這麼做毫無用處。他們根本不痛不癢。\n\n打蛇必須打七寸！殺死他們的領袖，他們就會因為無法做決策和絕望而癱瘓了。\n\n你問為什麼要這麼做？不是很明顯嗎？他們可是豺狼人啊！還需要其他理由嗎？", progress = nil, completion = "他們一定很絕望！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66265] = {title = "下一個是誰？", objective = "殺死碎牙。", description = "啊哈！好啊，看來有另一個豺狼人站出來發號施令了。完全如我所料。對。\n\n讓一個能夠信賴的副督軍來確保政權的延續，似乎非常合理，對吧？我們只能再加把勁打擊他們，把他們的官僚體制搞垮，是吧？\n\n什麼？我該用這個機會來反思，我是不是太快就批判這些豺狼人？荒唐！他們可是豺狼人啊！\n\n快點快點！殺死碎牙，打鐵要趁熱，不然他們可能就要舉辦選舉了！", progress = nil, completion = "哈！或許下一次他們要選領導者的時候會好好想一想！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66266] = {title = "骯髒的雜種", objective = "殺死3隻土狼族母和12隻雜種土狼。", description = "那些豺狼人培育的的骯髒雜種土狼必須消失！牠們一點修養也沒有…你不會相信我曾經看過牠們在哪裡排泄…而且儘管我的幻象非常完美，牠們可能還是嗅得出我的位置。\n\n幫這個有修養的世界一個忙，讓牠們從這世界上消失吧。", progress = nil, completion = "裝死裝成真的了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66267] = {title = "M.E.T.A.", objective = "釋放6隻受虐動物。", description = "那些惡魔！劫掠和謀殺是一回事，但是虐待動物？我無法忍受。\n\n豺狼人設置了陷阱，要捕捉動物來餵給他們那些口水直流的土狼。想辦法放走那些毛茸茸的俘虜，讓這些無賴見識一下，法師是怎麼道德對待動物的！\n\n考慮到我最近的行動，這當然還是符合道德規範啦。你到底想要暗示什麼？", progress = nil, completion = "讓那些野蠻傢伙好看了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66268] = {title = "神奇的第三次", objective = "殺死血爪。", description = "什麼？又有一個掌權了？為什麼就這麼厭惡空窗？至少也等一段哀悼的時間以表尊重，表面上做做樣子才對吧？\n\n難道他們沒有禮儀嗎？不懂分寸嗎？不會尊重精心打造的計畫嗎？我還做了圖表耶！\n\n去處理這個叫血爪的傢伙。我需要冷靜一下。\n\n別在一旁冷嘲熱諷，謝謝！", progress = nil, completion = "終於！那一定就是最後一個了。對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66270] = {title = "痛扁豺狼人", objective = "擊敗潛在督軍。", description = "噢，聖光啊…還有更多！怎麼會發生這種事？\n\n我縝密計畫了那麼多！在這座腐臭的湖躲藏了那麼久！安排那麼多暗殺！\n\n這本來應該讓他們陷入混亂、使他們的聚落瓦解的，但我們連拖延時間都稱不上！\n\n或許…或許你說的對，<name>。我一直以來都做錯了…\n\n不！這不可能！反正我們現在來不及回頭了。\n\n去吧…處理這些新冒出來的傢伙。我需要時間整理思緒。", progress = nil, completion = "他們只會繼續戰鬥直到找出新領袖為止？看來情況已經定了。如果我想在這裡建立作戰基地，我們必須殺死他們全部人。\n\n計畫就是，我們…\n\n等等，你要走了？你不想牽扯進來？那我要怎麼辦？我跟豺狼人結怨了，已經沒辦法離開這座湖了！\n\n好吧！你去支持那些滿身跳蚤的無賴吧！\n\n把我答應給你的酬勞拿去，然後就走吧。這片森林裡可不只有你一位勇士！我會找其他人來幫忙！", rewards = "您會收到：\n\n再生元龍：犄角下顎裂脊者之牙原風符咒"}
MultiLanguageQuestData['tw'][66278] = {title = "一個龍獸的廢物", objective = "把懷錶帶去花園交給古爾佩奇。\n\n已提供物品：\n", description = "<許多的垃圾堆中躺著一個閃閃發光的懷表。或許古爾佩奇會知道該怎麼做。>", progress = nil, completion = "這個是在那間小屋裡？這不是我的，但我想我知道是誰的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66279] = {title = "初來乍到", objective = "把懷錶帶去花園交給奧力茲姆。", description = "不過沒錯，這個懷錶屬於其中一個幫我照顧花園的管家。\n\n他是諾茲多姆的同族。好像叫奧力茲姆？這些孩子我老是記不清楚他們的名字。他大部分時間都站在雅立史卓莎的樹旁邊的沙漏那裡。一動也不動，連眼都不眨。\n\n要我說啊，我覺得諾茲多姆他們那族的成員都很奇怪。不過，要是你把這拿去給他的話，他應該會很感激的。", progress = nil, completion = "謝謝你，&lt;name&gt;。看到這個東西找回來了，諾茲多姆會很高興的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66299] = {title = "期待的炸蛋", objective = "殺死嘯翔巢母。", description = "我們的原型成功了！太棒了！\n\n現在該上主菜了。而且這一次，你就是主廚。\n\n只要一些必要的調整，你就可以再次穿上偽裝。然後，你就要把我們的傑作「炸蛋」泡在這個腐臭的燉菜，再到上頭的巢母洞穴，把它裝盤擺放好，然後滑翔下來，引發身後的爆炸！\n\n如果一切都照計畫，她一定會被烤熟的。因為爆炸的緣故。爆炸會把她烤到全熟。", progress = nil, completion = "事情並沒有按照計畫進行，但所有好的哥布林計畫都是這樣的！做得好！\n\n這裡還是會有嘯翔鷹身人，但是少了指揮他們行動的巢母，要削減他們的數量就容易多了。而且，藍羽鵬鳥也真的有機會能夠存活下去。\n\n鷹身人和龍其實沒什麼不同。先不管他們試著大規模消化峭壁上的其他生物，他們還挺像是擁有自己的文明。或許在某個不知名的地方，會有一支愛好和平的鷹身人族群？\n\n喔，還有別卸掉偽裝。其實挺好看的。", rewards = "您會收到：\n\n啾諷教授的無懈可擊鷹身人偽裝高地飛龍：臉頰有脊刺"}
MultiLanguageQuestData['tw'][66308] = {title = "助長火焰", objective = "收集30個灰燼裂片煤炭。", description = "透過大地守護者的熔爐打造的新武器和護甲，將會確保我們在與加拉登的戰爭中，取得最終的勝利。\n\n不過我們必須持續為熔爐的烈焰添加燃料。灰燼裂片煤炭能提供最強的火力，在鑄造武器時不可或缺。\n\n你可以從灰燼裂片地層的礦床和元素生物身上取得灰燼裂片煤炭。", progress = "你收集到新鮮的灰燼裂片煤炭了嗎？", completion = "這種煤炭很合用，&lt;name&gt;。應該能讓熔爐多撐一陣子。", rewards = "您會收到：\n\n巨龍群島補給品"}
MultiLanguageQuestData['tw'][66320] = {title = "時間的流動", objective = "前往時光沙地和克羅米交談。", description = "時間的流動就像河水，有彎彎曲曲的河道與支流，而且有時候它的流向也是可以改變的。但是，任何未解決的異象也都可能害我們的命運走偏、導向錯誤的時間線。\n\n我們正在快速接近一個這樣的異象。我已經派克羅諾穆到時光沙地，調查與糾正可能會干擾真實時間線的問題。\n\n而且我預見，你的協助會極為寶貴。\n\n請出手協助我們，和克羅諾穆會面。", progress = nil, completion = "哈囉！…又見面了？應該吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66321] = {title = "擾亂他們的部隊", objective = "消滅加拉登的部隊。", description = "我打從心裡感覺得到，加拉登部隊正打算對我們發動攻擊。\n\n我們應該先發制人，別讓他們有機會動員起來！\n\n前往熾烈高地，讓那裡的加拉登部隊陷入混亂。", progress = nil, completion = "你帶來的破壞應該能讓他們牢記一陣子。做得好。", rewards = "您會收到：\n\n耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者風帽鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴\n                            顯示 25 更多                        雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮肩冑鈷藍看守者肩墊雍亞拉馴鷹者腰帶戰痕纍纍的鱗片蒼藍秘法增幅器生命烈焰之瓶夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼巨龍群島補給品"}
MultiLanguageQuestData['tw'][66323] = {title = "發呆派", objective = "在奧格瑪叫醒3個工人。", description = "我們已經拿回貨物，就快可以完工了。但所有的工人都在城裡偷懶。\n\n把他們找出來，「鼓勵」他們回來工作。拿吃剩的派丟他們，應該就能叫醒他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66326] = {title = "工欲善其事", objective = "收集1個精準鱗片重錘、1個黑曜丁字砧、5把黑鋼鉗和10個龍爪衝床。", description = "這種火力的熔爐需要能夠承受高度熱能的特殊工具。\n\n但加拉登把這個地方搜刮一空，偷走很多我們工作所需的工具。\n\n可以的話，請從他們身上取回這些工具，好讓我們繼續為盟友打造武裝。", progress = "你找到我們需要的工具了嗎？", completion = "這是個好的開始。你取回的工具能讓我們暫時用一陣子。", rewards = "您會收到：\n\n耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮馬褲\n                            顯示 51 更多                        巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊擊聲天賜穿刺席卡刺矛精確校準的手持火砲儀祭雍伊爾匕首喀拉希塑地手巨錘靈巧戰戟灼熱蠍尾獅烙鐵雍亞拉馴鷹者腰帶戰痕纍纍的鱗片血腥戰騎串刺龍鰻盜獵者燼刃翻騰的熔岩投擲手鬥棍甦醒海岸斬斧碎礁劈斧精緻刮鱗小刀屋克杜魯捕鯨矛深海獵人之弩熔火拳師之拳強化洞察短劍蒼藍秘法增幅器生命烈焰之瓶夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][66327] = {title = "追風", objective = "聽取斥候托姆爾的報告。", description = "我們必須暫停一下，思考我們的戰略。\n\n我們需要雍亞拉的祝福，才能吹響德魯沙之角來召喚綠龍。沒有他們的援助，我們無法打贏這場戰。諾庫德族的數量已經比其他氏族多了，現在他們的勢力又得到洪荒使者的加持。而且現在科蘿洛絲還抓了我們的疾風之母！因此，在諾庫德族發起最後攻擊並包圍莫魯凱前，我們必須找到雍亞拉。\n\n我會立刻派所有的斥候出去。我只希望我們能及時找到她。", progress = nil, completion = "我們太遲了。諾庫德已經大肆攻擊德魯沙之角並屠殺了我的同胞。\n\n我們必須回應這項侵略之舉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66328] = {title = "綠龍有難", objective = "在水池和大可汗瑪托拉會面。", description = "那些龍往下落到平原的西邊去了。我們必須搶在諾庫德族前找到他們。\n\n我們可不希望巴拉卡的行為讓他們覺得所有的莫魯克人都是敵人。", progress = "那些龍可能需要我們的協助，外來者。我們必須快點行動！", completion = "我們的祖先說，綠龍既溫和又有智慧。幸好在聽到我們對此事的說法以前，他們忍住了他們的怒氣。\n\n現在我們知道洪荒使者和諾庫德族是我們的共同敵人，該把他們擊垮了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66329] = {title = "吹響號角", objective = "見證巴拉卡和科蘿洛絲的計畫。", description = "他們為什麼會把雍亞拉帶來這裡？除非…\n\n<name>！我不認為巴拉卡打算摧毀號角。我覺得這是陷阱！我們必須想辦法穿過這陣風，要快點！", progress = "不，巴拉卡！", completion = "在巴拉卡為他今天犯下的罪負起責任之前，我不會停歇的。屠殺我的人民、褻瀆雍亞拉、背叛我們古老的盟友…\n\n復仇得再等一等。還有更急迫的事要處理。我們必須協助綠龍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66331] = {title = "洪荒使者前線", objective = "在風暴裂口和斥候托姆爾、亞莉及蓓莉卡、雍‧賽希騰以及麥琳瑟拉談話。", description = "大可汗瑪托拉捎來消息說，她和她的部隊已經抵達翡翠花園了。他們已經找到科蘿洛絲和她的洪荒使者。看來大量的敵人正在北方的海灘上集結並準備入侵。\n\n明智的她派了許多斥候監視著戰場附近的戰略地點。去收集他們的報告，然後到前線和我與部隊會合。在戰鬥中爭取榮耀，在勝利後報仇雪恨。", progress = nil, completion = "敵人搶先我們一步。不要絕望，我們的決心與我們之間的盟誓一樣堅定。做好準備，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66333] = {title = "為蘇列瑟斯討回公道", objective = "殺死3個諾庫德好戰者並摧毀3個屠龍弩砲。", description = "只要有一隻綠龍還沒斷氣，這些洪荒使者就別想輕鬆染指遠古枝幹。\n\n我們迫不及待想加入這場戰鬥，但是，只要那些屠龍弩砲還在戰場上，我們就無法出擊。現在有諾庫德最強悍的戰士在看守弩砲，所以你也得去打倒那些戰士。\n\n請解決那些弩砲和諾庫德好戰者。消除這個威脅，那麼綠龍就能扭轉頹勢。", progress = nil, completion = "那些糟糕的武器消失得好。願再也沒有其他的龍遭遇蘇列瑟斯的苦難。", rewards = "雍伊爾學徒裹帶諾庫德劫奪者臂甲席卡斥候護腕蹄萊看守者束腕您會收到：\n\n"}
MultiLanguageQuestData['tw'][66335] = {title = "瓦解額外的水晶塔", objective = "使用附魔種子標記洪荒使者水晶塔。", description = "在摧毀那些邪惡武器後，綠龍軍團終於可以正式出擊了。\n\n我們比較熟悉地面上的狀況。我們需要標示目標，好讓麥琳瑟拉和巨龍能從上面攻擊。\n\n麥琳瑟拉給了我這些附魔種子。把它們放在洪荒使者水晶塔附近。我們會用它們的光線來指引飛天巨龍的攻擊。", progress = nil, completion = "真是萬幸，巨龍在這場戰鬥中是站在我們這一邊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66336] = {title = "翡翠之島", objective = "到遠古枝幹與麥琳瑟拉會面。", description = "我沒有忽略你在這其中的貢獻，凡人。我們能夠成功擊敗洪荒使者，你的勇猛占了很大的功勞。\n\n我已經邀請了半人馬到遠古枝幹下加入我。我們歡迎你以及大可汗瑪托拉與她的人民進入我們的家園。\n\n沿著這條路徑，穿越橫跨水面的拱門，進入另一邊的樹林。我會在那邊等你。", progress = nil, completion = "歡迎來到遠古枝幹。在你面前的是綠龍軍團的翡翠誓言石。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66337] = {title = "破颶者", objective = "擊敗科蘿洛絲。", description = "<name>，來我這裡！勝利近在眼前！\n\n洪荒使者已經潰不成軍，看來大勢已去。一切戰果是否會化為泡影，全取決於我們與洪荒使者首領科蘿洛絲之間的最後一戰。\n\n該為一切畫下句點了，我們一起並肩作戰。出擊吧，<兄弟/姐妹>！", progress = nil, completion = "一切…終於結束了。我們的神聖島嶼又再次安全了。謝謝你為我們一族做的一切，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66339] = {title = "諾庫德進攻據點：風屬於天空", objective = "到諾庫德進攻據點擊敗巴拉卡可汗，並救出雍亞拉。", description = "<name>，你要告別了嗎？還是你願意再幫我們一次？\n\n我的斥候回報說，巴拉卡已經撤退到他的城塞，雍亞拉就是被他囚禁在那裡。簡直天理不容！\n\n在此同時，他的諾庫德劫掠者傾巢而出，在平原上到處製造混亂。我們跟劫掠者交戰的時候，你可以趁機潛入諾庫德城塞、救出雍亞拉。你意下如何？", progress = nil, completion = "經此一役，你無疑幫了莫魯克莫大的忙，絕對超乎你的想像。在此向你獻上最深切的感謝，&lt;name&gt;。請帶著雍亞拉的祝福一起離開。", rewards = "憤恨怒羽踏蹄塑像閃電充能行靴諾庫德守舊者肩鎧石根頭飾葛蘭尼斯的堅毅鱗片您能選擇下列奬勵中的一個：\n\n烏克赫遠祖串珠旋風之瓶\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66340] = {title = "進入蒼藍", objective = "在叉河路口與『智者』瑪蘇德會面。", description = "我們已經做了我們該做的。不過我必須留在這裡，觀察誓言石的情況，並領導綠龍軍團，請帶著我們的感恩和信賴踏上旅途。\n\n只要朝南走，就能在蒼藍高地找到藍龍軍團。請協助他們復原他們的誓言石，這樣我們距離治癒艾澤拉斯就又更近一步了。\n\n去找祈倫托的帕奇娜和『智者』瑪蘇德。他們會提供進一步指示。祝你旅途平安，夜夜好夢，<name>。", progress = nil, completion = "你好，冒險者！幸好你有聽到我們求援的呼喚。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66344] = {title = "乘風飛去", objective = "與蓋瑞瑟斯和麥琳瑟拉同行。", description = "所以說，洪荒使者和諾庫德氏族結盟來擴大他們的勢力。\n\n我們在這之前都成功地抵擋了洪荒使者的攻擊，可是諾庫德族帶來了新武器：屠龍弩砲。蘇列瑟斯恐怕不會是最後一頭遭到這武器的邪惡風暴魔法所害的龍。\n\n來吧。我會把你帶到巨龍休息的林蔭聖所去。在大可汗瑪托拉召集她的部隊前，你可以跟我說你對諾庫德族有什麼了解，我們得準備好下一步。", progress = nil, completion = "我們到了，凡人。歡迎來到翡翠花園。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66351] = {title = "山峰上的煙霧", objective = "找到探路者伊普思的飛機。", description = "<探路者傑布看向營地外的山峰，同時嗅了嗅。>\n\n我不喜歡這樣。探路者伊普思幾天前就應該到這裡了。他早就該來協助我，和我一起教導這群新人怎麼安全攀爬石柱的。\n\n現在我又看到遠處有煙。\n\n我一點都不喜歡這樣。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n任務線：攀岩\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66354] = {title = "點燃爐火", objective = "重組受損的誓言石碎片。", description = "熔爐已經就緒。現在只差爐火。\n\n把受損的誓言石碎片放在熔爐上，怒西昂會點燃火花，開始重組過程。", progress = nil, completion = "誓言石受損的部分已經修復完畢！不過這只是個開端，我們還可以完成更多事情。\n\n既然熔爐已經被重新點燃，我可以開始鍛造新的武器及護甲，為我們的行動提供更多助力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66356] = {title = "鐵樹", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66363] = {title = "石化蜥蜴扣環", objective = "從巨龍群島的蜥蜴身上收集20個堅硬蜥蜴皮，交給莫魯克半人馬的杜瑞娥。", description = "相連的鱗片是阻止箭頭的關鍵。我們做的圓盾是整個平原最好的，可是我的蜥蜴皮不夠用了，無法完成下一個訂單。\n\n我看你對我們的手藝很有興趣。在巨龍群島收集蜥蜴的皮，我願意幫你說明我們的工藝訣竅。", progress = "你收集好皮革了嗎？", completion = "這樣材料的品質相當不錯，我很感謝你。\n\n送你一些我們店裡賣的皮革當成謝禮，還有我答應要教你的一些訣竅。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][66364] = {title = "放風箏", objective = "從巨龍群島的各種元龍身上收集10個新鮮的元龍翼，交給伊斯凱拉巨牙海民的天納宇。", description = "讓我跟你說一個機會吧。\n\n元龍的翅膀有驚人的運動範圍，而且牠們的翼骨啊，伸縮範圍非常廣！我們通常會使用繃緊的皮革來做風箏。既然元龍到處造成災情，不知道你可不可以把牠們的翅膀帶來給我？這樣我就可以做出讓全族羨慕的風箏。", progress = "你拿到翅膀了嗎？", completion = "這些東西肯定能派上用場，我很快就會做出一個能飛的風箏。\n\n喔，為了回報你的幫助，讓我給你一些指點，這是我至少該做的。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][66368] = {title = "風暴中的島嶼", objective = "除掉10個熾炎靈體和熔融者伊格涅斯。", description = "休息的時間少之又少，元素生物的威脅卻永不停歇！\n\n真希望能稍微休息一下，讓我能夠製作更多結界，加強我們的防禦。\n\n請盡你所能，減少外圍地區受到的攻擊。", progress = nil, completion = "真是一個求之不得的休息時刻。為了報答，我有個禮物給你。", rewards = "您會收到：\n\n大地符咒"}
MultiLanguageQuestData['tw'][66369] = {title = "大地結界", objective = "啟動大地結界。", description = "我已經使用你收集的戒指強化了一個結界。它收集了附近土地上的石頭，創造出一個活生生的土靈防衛者來保護這個領地。\n\n去測試一下大地結界，確保結界正常運作。", progress = nil, completion = "感謝你的協助，&lt;name&gt;。我會在整個地區設置更多這樣的結界，來對抗加拉登與元素生物。如果你需要幫助，就用這些符咒來啟動它們吧。", rewards = "您會收到：\n\n大地符咒"}
MultiLanguageQuestData['tw'][66383] = {title = "傳說級的協助", objective = "拜訪受啟迪者軍需官威洛，看能獲得什麼協助。", description = "<name>，我們說服了受啟迪的仲介者，他們願意提供額外物資來協助對抗閻獄之主！", progress = nil, completion = "歡迎。請看一下我的商品，其中有能幫你打造傳說級物品的東西！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66390] = {title = "遺失貨物", objective = "前往暴風港，取回竊賊偷走的貨物。", description = "哼，那些滿腦子海水的海鬃又去探險了，我只好留在這裡整理他們的貨物！\n\n唉，不是我要抱怨，但塔文能不能簡單說明。我不需要長篇大論，只要一些指示就好。更慘的是，我的某個工人居然偷走了一些貨物！\n\n你可以幫忙找回貨物嗎？試著跟他用一杯酒交換，不然就拿這個丟他。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66391] = {title = "朝廢墟出發！", objective = "在卡恩薩爾廢墟和瑞南及拉索斯會面。", description = "你有興趣聽我介紹我發明的R.A.D.嗎？沒有？\n\n不管怎樣，我還是要說…因為它發現了一些東西。\n\n今天，它偵測到卡恩薩爾廢墟有秘法能量的巨大脈衝。拉索斯認為這是碎裂火焰軍搞的鬼。這是展示R.A.D.的完美機會！\n\n要一起來嗎？一定會很精彩的。", progress = nil, completion = "你錯過了一場好戲！我們剛才跟碎裂火焰軍的巡邏隊不期而遇。\n\n拉索斯朝他們攻擊，但他們的人數太多了！\n\n所以我就開始到處施放魔爆術…轟隆！磅！\n\n噢，可是呃，對…能量脈衝…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66392] = {title = "召集大自然的盟友", objective = "在林蔭聖所召集德魯伊，並收集賦能錨點。", description = "我們現在還不能絕望。我們必須向前推進，想出其他辦法突破屏障。\n\n首先，我們需要盟友。萊梅克召喚出無數的元素生物，從傳送門傾巢而出。我們需要能像我們一樣在夢境中移動的大軍，或是能輕易帶進夢境的軍隊。\n\n把德魯伊和半人馬召集到林蔭聖所。該是他們履行誓言、守護林地的時候了。", progress = nil, completion = "我要跟你一起進入亞登曠野。我要跟伊瑟拉說我們需要她回來，而且有一個辦法可以做到這點。\n\n做出這個犧牲的應該是我。我已經活得夠久了。我從來都不想活得比我兒子更久。這樣，我就可以為萊梅克的背叛贖罪，同時帶回我們的守護巨龍。\n\n你願意幫我嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66393] = {title = "去找索姆尼克斯", objective = "與萊梅克一起到遠古枝幹的誓言石附近找索姆尼克斯。", description = "自從半人馬殺死了索姆尼克斯的兒子後，他就一直處於憂鬱與失落。\n\n雖然我們都經歷過失去的痛苦，但如果這樣的事發生在蓋瑞瑟斯身上，我無法想像我會有多麼悲痛。\n\n帶萊梅克去找索姆尼克斯，然後看看還能幫上什麼忙。他懷疑洪荒使者正在準備另一次攻擊。我擔心他可能會一時衝動。\n\n別擔心，因為你有幫忙取回翡翠誓言石，你可以跨過屏障。", progress = nil, completion = "歡迎來到遠古枝幹，年輕人。\n\n是麥琳瑟拉派你來看我的嗎？我的年紀已經夠大了，根本不需要她來擔心我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66394] = {title = "削弱帷幕", objective = "到遠古枝幹關閉屏障泊具。", description = "一定有辦法從這片林地內部解除屏障。我感應到周圍有數個強化屏障的節點。\n\n要是你讓夠多的節點失效，應該就能解除屏障，讓其他人順利跟我們會合。", progress = nil, completion = "這應該就行了。屏障就要解除了。\n\n很快地，其他人就可以到翡翠夢境中找我們，我們又可以並肩戰鬥了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66395] = {title = "發出怪聲的岩石", objective = "調查可疑的凍岩，殺死洪荒使者。", description = "麥琳瑟拉不需要擔心我。我沒事。我兒子的死…我沒事。\n\n如果你真的很想讓我寬心，有件事是你可以做的。我懷疑洪荒使者會試著再入侵這片土地。跟上一次不同，我不認為他們會直接攻擊遠古枝幹。他們知道我們會打敗他們。\n\n看到那邊的石頭了嗎？那些顏色怪怪的、有點臭的石頭。我聽到那些石頭底下有東西在動。或許洪荒使者在附近潛伏！你可以去調查嗎？不管你找到什麼，把他們通通打扁。", progress = nil, completion = "我就知道！而且還這麼靠近夢境之門！現在我可以思考…其他事情了。\n\n在你狩獵的時候，我和萊梅克聊得很愉快。他一直很理解，也很有同理心。某種程度上，他讓我想到了蘇列瑟斯…\n\n他問說是否能親眼看看翡翠夢境的傳送門，我覺得沒有什麼不行。尤其是你又清除了門口那些惱人的蜘蛛。他應該會印象深刻。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66396] = {title = "守備的欣賞", objective = "把萊梅克的贈禮給6名守衛。", description = "我知道保衛這樣重要的地方相當累人。而且通常沒人感謝我們龍獸和龍裔的努力。\n\n我希望能為遠古枝幹的守衛獻上一點感激之情。\n\n來，把這些禮物給他們。這是我對他們友好的象徵。希望這發自內心的舉動能好好傳達我的謝意。", progress = nil, completion = "非常好。我希望他們會喜歡那些寶石。那些是我親手做的，就是為了這個特殊場合。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66397] = {title = "全副武力", objective = "釋放翡翠鱗衛及守望者。", description = "我們需要援軍，而且時間緊迫。不過因為屏障的緣故，麥琳瑟拉無法來林地跟我們會合。我們得在夢境中處理兩件事。\n\n殺死這些洪荒使者，從他們身上拿走你需要的東西，以便融化那些冰牢，救出林地守衛。", progress = nil, completion = "謝謝你把我救出來！我真不敢相信伊瑟拉真的在這，她回到翡翠夢境來了！就像我的理論一樣。\n\n我有一萬個問題非常想要問她，但我得專心才行。我們還有萊梅克的問題。\n\n而且，就在他把我凍在冰裡時，我也看到他要去的方向。\n\n他想要夢境裡的某樣東西，某種強大的東西。我不知道是什麼，但在他找到那樣東西之前，我們必須先找到他！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66398] = {title = "翡翠龍軍團", objective = "與蓋瑞瑟斯交談，然後與麥琳瑟拉和伊瑟拉同行，前往盧恩丹。", description = "如果我們要消滅翡翠夢境中的洪荒使者，其中一個必須拿下的地點就是盧恩丹。根據我兒子所說，萊梅克去了那裡。\n\n那是新生之樹的最後一道防線。在那裡，有一件古老的神器保護著大樹不被發現。而且，它的力量強大到可以一次驅逐所有敵人。\n\n我不知道我母親是否還有能力控制並使用它。但是等我們找到萊梅克並阻止他之後，就能解決這件事了。\n\n跟我們一起飛翔吧。", progress = nil, completion = "我們成功了。但是萊梅克已經開始了他的襲擊行動。我們不能讓他突破陣線！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66399] = {title = "我們會越過那座橋", objective = "摧毀冰霜核心以靠近索姆尼克斯。", description = "我們得想辦法應付這場雪！想要提供你適當的支援對抗萊梅克和他的爪牙，我們總不能讓自己的翅膀凍得掉下來。\n\n我感覺到附近有強大的冰霜核心，很可能正在為這場暴風雪提供能量。要是你能摧毀核心，我們就可以迅速消滅萊梅克的爪牙。\n\n而且索姆尼克斯也在那裡。他已經奮不顧身，飛去找萊梅克了。我們得盡快找到他。", progress = nil, completion = "&lt;索姆尼克斯的呼吸痛苦而吃力。他因為冷而顫抖。&gt;\n\n我盡可能…阻止他了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66400] = {title = "冬殞", objective = "擊敗萊梅克。", description = "<索姆尼克斯掙扎著想要呼吸，但漸漸凍結了。>\n\n我成功…阻止他找到樹。但願我做得夠了。\n\n必須快點解決萊梅克。交給你了。\n\n告訴伊瑟拉和麥琳瑟拉我很抱歉…我這老龍太多愁善感了。", progress = nil, completion = "萊梅克輸了，不過還有一大堆元素生物和洪荒使者在夢境中到處亂跑。\n\n我猜想…我們現在知道夢旅者的真實身分了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66401] = {title = "夢旅者", objective = "釋放夢境龍域的力量。", description = "我們為走到這個地步付出了這麼多努力，現在只剩一件事了。盧恩丹的力量只會回應能夠從中控制翡翠夢境的人。\n\n我原本以為只有我母親能夠，但…我看得出來她變了。\n\n我不知道不一樣是不是更好，但它是真的，而我也必須承認這一點。\n\n但來吧，讓我們一同面對吧。", progress = nil, completion = "我就是夢境之龍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66402] = {title = "有其母必有其女", objective = "見證麥琳瑟拉的晉升。", description = "打從再度踏進夢境的那一刻起，我就知道事情不一樣了。但現在我們已經擊敗了萊梅克和洪荒使者，我必須考慮發生的事所有可能的影響。\n\n在我死後，我女兒一直努力維持綠龍軍團的向心力。讓她晉升是最合適的。\n\n麥琳瑟拉必須領導綠龍軍團。", progress = nil, completion = "只要是我母親曾經飛越的地方，我也必須飛越。只要是她的吐息曾經帶來和平與生命的地方，我也必須效法她。\n\n我發誓一定會盡我所能，扮演好綠龍軍團的領袖。我保證一定會盡心盡力，如同伊瑟拉這麼多年來所做的。", rewards = "您會收到：\n\n麥琳瑟拉的祝福"}
MultiLanguageQuestData['tw'][66409] = {title = "當務之急", objective = "在碎鱗者要塞從加拉登身上收集戰利品。", description = "酋長不見任何來客。\n\n不管你是不是伊斯凱拉派來的，我們現在連自己的麻煩都處理不完了，不需要外來者替我們帶來更多麻煩。\n\n要是你有事要談，先當個有用的人，協助我們的守衛。加拉登一直從河的對岸攻擊我們，他們背後的指揮官是塑火者洛拉克。雖然看不太出來，但他的確比其他加拉登多了一點腦子。\n\n解決他，然後把證據帶回來。到時候我們再來談。", progress = "如果那把武器中看不中用，現在就趕快告訴我們，別浪費彼此的時間。", completion = "我必須承認，我沒想到你會活著回來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66410] = {title = "最壞的印象", objective = "與圖塔崁交談。", description = "<哈克塔將你帶回來的戰利品翻了幾次，然後緊緊握在手中。他露出猙獰的表情。>\n\n我們現在淪落到這種地步了。一個外來者一天之內幫我們做的事，比我們自己的酋長好幾週來做的事都還多。\n\n來吧。我會帶你去見他。\n\n或許這樣能挫一挫他的銳氣。", progress = "你想要從我們這裡得到什麼？", completion = "&lt;圖塔崁將戰利品扔到附近的地上，既疲憊又興味索然。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66411] = {title = "騷亂之水", objective = "收集10隻暖水河魚和6份多汁的蟹肉。", description = "看到我們的酋長變成這樣讓我很難過，可是我們的需求不等人。\n\n一直以來，這條河供養了我們世世代代。但隨著加拉登步步進逼，河水也一退再退，裡面的生物被迫相互競爭生存空間和食物。\n\n沒有守衛，我們的釣手就沒辦法跑到太遠的地方釣魚。我們的食物儲備每天都在減少。\n\n你看起來並不需要他人保護。帶著這張漁網，幫忙從河裡捕魚吧。附近螃蟹的肉也多多益善。", progress = "這條河過去十分美麗，而且物產豐饒。期望有朝一日，我們能再次得到它的賜福。", completion = "至少在我們的酋長忽略他的職責時，我們的孩子們不會挨餓。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66412] = {title = "請繼續，巴席爾頓", objective = "在花園裡和巴席爾頓談話。", description = "在你離開之前，我這頭老龍獸還有一件事情想拜託你。\n\n當年巴席爾頓領主和我初次相遇的時候，我們會一起進行各式各樣的冒險。我覺得這就是他走失的原因，因為他想念冒險的感覺。\n\n我現在沒辦法帶他這樣做了。但是你可以！我看得出來，你可以帶他去看我連作夢都沒想過的地方。\n\n不過，我們是應該先問問巴席爾頓的意思。", progress = nil, completion = "老實說，我有點嫉妒他。我也想再變年輕，去探索世界。請你有機會一定得再來拜訪，告訴我他最近又做了什麼。", rewards = "您能選擇下列奬勵中的一個：\n\n巴席爾頓領主\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66413] = {title = "熱浪襲來", objective = "將半熟的魚送去給長者烏努札克。", description = "<這條魚顯然已經死一段時間了。\n\n在進一步檢視時，你注意到它似乎已經被煮熟了。大概是在河裡還活著的時候。\n\n村莊裡的烏努札克或許會對這條魚感興趣。>", progress = nil, completion = "歐巧諾亞保佑我們！這條河受到這樣的侵擾使我痛心。\n\n這一定又是加拉登搞的鬼。他們的熾炎魔法一直在加熱這條河，溫度已經上升到這些可憐的生物都無法承受的地步。\n\n但，我們不能浪費食物，不然會天打雷劈。來吧，把它丟到鍋裡去。我們就用它來煮今天的晚餐。", rewards = "您能選擇下列奬勵中的一個：\n\n食譜：現宰海味食譜：驚奇海蛾魚食譜：鹽烤魚餅食譜：尖牙切片\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66414] = {title = "只缺一個", objective = "找到伊普柯。", description = "我看見了你對村子的貢獻。在情況比較輕鬆的時候，我是可以自己處理的，可是…\n\n<圖塔崁看著河流，然後再次看向你。>\n\n我們的一些巨獺最近不見了。我們認為牠們是不小心游到加拉登的地盤附近。我們找回了好幾隻。沒有一隻是活的。大多數都死無全屍。\n\n我們找不到我的巨獺。她的名字叫做伊普柯，是我多年的狩獵夥伴。如果她…\n\n<他搖了搖頭。>\n\n請你…幫幫我。你能搜索河水中的話，我就專注在岸上。", progress = nil, completion = "都是我的錯。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66415] = {title = "唯有突破重圍", objective = "協助圖塔崁找到新的巨獺夥伴。", description = "是烏努札克叫你來的，對吧？我成為獵人的時候，正是他幫我找到伊普柯，或者說，幫伊普柯找到我。在我們的夥伴關係中，它們才是主導者。\n\n他受傷了。因為我，大家都受傷了。我知道他們需要我的領導，但是沒有她，我就是一個半吊子的領導者。如果我連她都保護不了，我怎麼可能保護得了屋克杜魯的大家？\n\n<他深吸一口氣。>\n\n我無法原諒我自己。但我不能把這份重擔當成藉口，遲遲不踏上應該踏上的道路。", progress = "我知道總有一天會發生這種事，但這並不能減輕絲毫痛苦。", completion = "沒有人能夠取代伊普柯。可是，唯有捧起雙手做好準備，人才能夠承接住水。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66417] = {title = "回收補給品", objective = "收集8個鯨骨碎片和30份浸水的木頭。", description = "呸！我真不敢相信，在我們需要圖塔崁指揮他的守衛和獵人的時候，他還在拖拖拉拉！\n\n我們以前會在碼頭上跟伊斯凱拉貿易，但自從加拉登包圍這裡，嚇跑我們的商人後，生意就做不成了。上個月一半的商品跟我們大部分的船都還在淺淺的河裡，還沒找回來。\n\n守衛和獵人想要幫忙，但他們卻沒有武器。你似乎能夠顧好自己的安危，那就請你跑一趟，收集一些材料，讓我能夠製作長矛！", progress = "等到我們守衛和獵人有了新的武器，我就能建立起一支小隊，收集剩下的殘骸。", completion = "也差不多是時候了！它們有點濕，但我可以用這些做出許多精良的武器。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66418] = {title = "測試巨牙海民軍備", objective = "拿取屋克杜魯骨矛，破壞4個巨牙海民訓練用假人。", description = "第一個武器已經準備好了！將骨頭泡在加拉登的火焰加熱的河裡，讓骨頭的可塑性提高了。我要記住這招！\n\n你一直以來幫了我們不少忙，因此我決定讓你負責測試正統的屋克杜魯武裝。你在巨龍群島的這一側，絕對找不到比這更銳利又堅固的武器。\n\n去我們的訓練場地幫我測試看看。或許能讓酋長回想起真正的戰鬥是什麼樣子！哈！", progress = nil, completion = "哈哈！我從這裡都能聽到那邊騷動的聲音！\n\n如果這還不能讓圖塔崁採取行動，我也沒有別的辦法了。\n\n至少我們的獵人會有足夠的武器來保衛我們的村莊，不管狩獵大師幫不幫忙。謝了，&lt;name&gt;。", rewards = "您會收到：\n\n巨牙海民訓練目標"}
MultiLanguageQuestData['tw'][66419] = {title = "效忠一主", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66420] = {title = "痛快暢飲", objective = "在暴風城朝3個工人投擲鹹海水。", description = "貨物找回來了，該讓其他東西歸位了。\n\n在如此忙碌的時候，我的工人居然還跑去摸魚。看你能不能把他們找回來。\n\n完工之後我們再來好好慶祝。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66421] = {title = "風暴裂口", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66422] = {title = "探險繼續進行！", objective = "在高塔旁與瑞南和拉索斯碰面。", description = "古老的遺跡、動機不明的組織，還有瑞南的R.A.D和它的分析…\n\n這一切都讓我的探險者之魂蠢蠢欲動。\n\n我們必須進一步調查這裡出了什麼事。\n\n南邊有階梯可以通往塔頂，我們應該去一探究竟。", progress = nil, completion = "這些碎裂火焰軍並非死在我手中…或死在瑞南的「獨門絕招」。\n\n我們來的時候，他們已經死了。\n\n瑞南認為他們身上的多個致命傷都是秘法能量造成的。\n\n我認同他的觀察結果。不過還不確定是巨龍控制臺造成的，還是他們自己人誤殺…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66425] = {title = "秘法超載", objective = "協助瑞南驅除秘法氣泡。", description = "好了！完成了！\n\n讓我為你獻上…R.A.D.D.E.R！\n\n登、登、登！\n\n我把它和巨龍控制臺周圍的能量校對到同個頻率，而且刻上了驅散魔法的雕紋。\n\nR.A.D.D.E.R.可以驅散秘法能量並關閉巨龍控制臺，可是雕紋在每次使用後都會減弱。\n\n是不是很方便啊？\n\n在我們附近，我一共偵測到四個控制臺。去把它們關了！", progress = nil, completion = "你成功了，&lt;name&gt;！\n\n嗯，是你和R.A.D.D.E.R.一起…\n\n但隨便啦…現在，幫我把拉索斯帶回荒僻營地。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66426] = {title = "沒時間了", objective = "抵達東塔。", description = "我感覺得到，正當我們說話的時候，秘法波動也在加劇。\n\n我懷疑過不了多久，廢墟就會讓瑞南的J.A.M.看起來像是夜空中遙遠的一顆星。\n\n我們必須去那裡阻止它發生。\n\n$p，請小心一點。\n\n到東塔跟我們會合。我們到那裡再評估現況。", progress = nil, completion = "情況比我們想的還糟。秘法能量幾乎達到最上限。\n\n某種東西正在加快整個過程。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66427] = {title = "迫近的威脅", objective = "殺死莎瓏。", description = "秘法對我造成的傷害無法在戰場上治好。我的傷勢太嚴重，恐怕無法進行戰鬥。\n\n<name>，我需要請你再幫我一個忙。\n\n你必須找到莎瓏，並且阻止她，別讓更多控制臺超載。\n\n這麼做可以為瑞南爭取到一點寶貴時間，讓他校正R.A.D…還是R.A.D.D.E.R…隨便他現在叫什麼。\n\n或許這樣能阻止碎裂火焰軍的計謀。", progress = nil, completion = "這樣就好了。\n\n現在全看瑞南了。我相信他的能力。他讓我們度過許多難關…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66428] = {title = "理所當然的友誼", objective = "使用R.A.D.D.E.R.E.R解除秘法屏障。", description = "好了！R.A.D.D.E.R.E.R已經校正完成，隨時可以使用…由你來用！\n\n為什麼不是我來用呢？非常簡單！\n\n你必須想像跟考慮所有的可能性才行。\n\n我們假設它爆炸好了。如果我受傷、昏迷或死亡，誰會去修好它呢？你能想像嗎？\n\n去吧，解除屏障，我們才能回到營地把拉索斯治好。我負責…遠距離觀測。", progress = "今天的情況難道還會再更壞嗎？", completion = "他就這樣…走了？\n\n他犧牲自己的性命救我們，因為R.A…機器沒發揮作用。\n\n拉索斯那麼相信我…我應該聽勸的…我讓他失望了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66431] = {title = "身處悲痛", objective = "嘗試幫助圖塔崁。", description = "根本不該發生這種事。那些混帳加拉登…屠殺我們的巨獺，把它們的屍體留給他們扭曲的怪物啃食…\n\n圖塔崁的悲痛我感同身受，但要是他一直沉溺在黑暗和悲傷之中，族人的未來恐怕也會一片黑暗。\n\n我們必須展開行動。\n\n他剛才似乎朝著我們上面的瞰臺走去。你今天幫了他很大一個忙。如果是你向他表示善意，他或許願意打開心房。求求你，看看能不能做點什麼。", progress = nil, completion = "&lt;圖塔崁舉起雙手摩挲他的臉，深深嘆了一口氣。他看起來很憔悴。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66435] = {title = "拯救據點", objective = "到生命寶庫遺跡救出5個受困的探險者。", description = "我身為薩滿跟許多元素合作過，但我從未遇過這麼有攻擊性的元素生物！\n\n遠征隊在這裡發現了泰坦遺址，不過有個屏障把內廳封鎖起來。在我們試著要消除屏障時，我想我們觸發了某種保全系統…憤怒的元素生物突然到處都是！\n\n在那些元素生物攻擊時，很多探險者都還在挖掘場工作。許多人都被困住了，但裡面沒有人是戰士。\n\n請你到挖掘場去，協助他們撤退！", progress = nil, completion = "大家都安全地待在我們的新地盤中。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66436] = {title = "出土的麻煩精", objective = "到生命寶庫遺跡殺死12個土元素。", description = "土元素不只想把我們趕走，同時也在摧毀文物和設備！彷彿它們被指示要摧毀跟泰坦相關的一切…\n\n我們暫時抵擋住它們的攻勢了，但只要它們還在，我們的研究就無法進行下去。請你幫我們擊退它們，我們才有探索的空間！", progress = nil, completion = "這樣應該就能鞏固我們在這裡的地位了。做得好，&lt;name&gt;。", rewards = "晶紅守護者束腰生命寶庫之索大地束縛鍊甲晶紅防衛者繫腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][66437] = {title = "關鍵要素", objective = "回到生命寶庫遺跡，將洪荒石之球交給元素師泰暘。\n\n已提供物品：\n", description = "<這個大地之球隨著能量釋放發出嗡鳴聲。>\n\n<元素師泰暘或許知道它的用途。>", progress = nil, completion = "我可以感受到儲存在這個寶珠中的能量。你似乎為我們的麻煩找到了一個解決辦法。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66438] = {title = "崇高的目標", objective = "到角蛙谷找斥候利妥爾。", description = "空氣是非常強大的元素。它會切開岩石，吹動風帆，帶我們前往非去不可的地方。\n\n根據我的假設，想要解除這個屏障，空氣將會是最有效的媒介。做法很簡單，真的。\n\n我的斥候回報說，他們已經找到洪荒強風之球。斥候利妥爾可以帶你過去。他們目前駐紮在角蛙谷附近。快點出發！", progress = "你找到那個斥候了嗎？", completion = "泰夏拉許多任務都不會自己辦，她比較喜歡委託他人。我可以理解她為什麼對洪荒強風之球有興趣。目前，我要自己先留著。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66439] = {title = "急速射擊計畫", objective = "到角蛙谷，從洪荒部隊的成員身上收集洪荒烈焰碎片。", description = "元素之球，是嗎？既然有土元素的，那就一定有火元素的！\n\n角蛙巢穴附近的洪荒使者正在利用熔岩重塑整片土地。如果要說誰會對洪荒烈焰之球感興趣，非他們莫屬！\n\n把它們解決掉，看看能不能找到有用的線索！", progress = "艾卡蒂雅有洪荒烈焰之球的線索。你找到它了嗎？", completion = "啊，是洪荒烈焰之球。它和艾卡蒂雅一樣充滿活力而炙熱。我暫時先留著保管。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66440] = {title = "句點", objective = "與圖塔崁交談。", description = "我不知道該說什麼。我完全不曉得，酋長有這麼深的痛苦。\n\n但是這樣就說得通了。對我們來說，巨獺不只是寵物…尤其對我們酋長這樣的獵人來說，更是如此。巨獺是我們的朋友、夥伴、家人。\n\n伊普柯是圖塔崁第一且唯一的巨獺。對屋克杜魯的獵人來說，這是神聖的羈絆。\n\n我們會好好送她，安詳前往祖先所居之地。", progress = "我已經盡力了。", completion = "&lt;圖塔崁繃緊著下巴，淚水在眼眶打轉。他沒有轉頭看著你。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66441] = {title = "精煉努力", objective = "到生命寶庫遺跡東方的洞穴殺死愛司奎恩。", description = "洪荒石之球是很有利的發現，不過艾卡蒂雅和泰夏拉針對屏障提出的假說相互衝突。\n\n我有我自己的假說。或許有了更多元素球後，真相就會更加清楚。\n\n有一個探險者在附近的洞穴中看到一個超大的水元素。擊敗那個水元素後，或許就能找到其他的元素球。", progress = "元素生物身上有其他的元素球嗎？", completion = "我們必須像水一樣，隨時順應變化。謝謝你把洪荒海浪之球帶來給我。", rewards = "您能選擇下列奬勵中的一個：\n\n聚能元素指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66442] = {title = "理論分析", objective = "協助以元素球對生命寶庫遺跡的泰坦屏障進行測試。", description = "我們現在一共有四種元素球！讓我們來看看到底哪個假說才是對的。", progress = nil, completion = "我原本的假說依然成立。元素聚集在一起的時候更有效果。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66443] = {title = "呼喚狩獵隊", objective = "調查狩獵召集的原因。", description = "<村莊中心傳來低沉的狩獵號角聲，吸引巨牙海民獵人的注意。\n\n你應該去調查一下。>", progress = nil, completion = "要是酋長不處理這件事，我會親自把加拉登族打成肉泥！記住我的話！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66444] = {title = "打鐵趁熱", objective = "殺死『沸河者』祖爾丹。", description = "我跟路上的暸望手談過。他們說這個名叫『沸河者』祖爾丹的加拉登，已經在這個的西南邊展開他邪惡的儀式，地點就在有許多巨獺築巢的瀑布附近。\n\n如果他們正在讓我們上游的河水沸騰，代表他們決定更快對我們動手。我們將會被迫挨餓或撤退。這兩種結果我們都不要。\n\n他們像懦夫一樣，只會來陰的，完全不敢正面對決。那這次就換我們親自去找他們吧？", progress = nil, completion = "沒有你的幫忙，我們的河流、我們的族人統統無法得救。\n\n屋克杜魯氏族欠你很大的人情。", rewards = "您會學到：\n\n馴服巨獺\n\n您還會收到：\n\n圖塔崁的禮讚"}
MultiLanguageQuestData['tw'][66445] = {title = "榮耀逝者", objective = "取回8個陣亡防衛者角環，3個大地守護者的烈焰之刃，和1個思珂希亞號角。", description = "加拉登不屑一顧地褻瀆堡壘或我們族人的屍體！他們折斷死者的骨頭，還拿走他們的私人物品當成紀念品。\n\n這種惡行深深傷了每個驕傲黑龍的心。必須讓死者得到應有的榮耀。\n\n取回加拉登從戰死的屍體上奪走的物品。", progress = "你取回死者的遺物了嗎？", completion = "亡者的回憶將會永遠延續下去。這全都得怪那些該死的加拉登。\n\n這些物品會得到妥善保存，而我們會懷念那些死者。", rewards = "您會收到：\n\n\n\n等級 70–70耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮馬褲\n                            顯示 47 更多                        巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊擊聲天賜穿刺席卡刺矛儀祭雍伊爾匕首掠龍憤怒短劍諾庫德穿刺長戟莫魯克戰旗雍亞拉馴鷹者腰帶戰痕纍纍的鱗片血腥戰騎串刺甦醒海岸斬斧碎礁劈斧精緻刮鱗小刀銳牙魚叉伊斯卡秘法師斬潮錘巨牙海民領航員法杖長者的螢光長棍永恆守衛之劍強化洞察短劍永恆看守者軍刀夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼\n\n等級 69–70生命烈焰之瓶\n\n等級 66–70蒼藍秘法增幅器巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][66447] = {title = "屏障之後", objective = "在生命寶庫遺跡中調查生命寶庫。", description = "既然屏障已經解除，我們就來探索密庫吧！", progress = "泰坦遺址中有很多值得一探究竟的地方，但我們最好從小地方開始比較保險！", completion = "我想我們現在沒事了，&lt;name&gt;。謝謝你。遠征隊該繼續深入挖掘了！\n\n\n\n想說開個薩滿玩笑。太難笑了嗎？", rewards = "遠征隊守衛盾牌寶庫守護者書狀寶庫守護者長柄斧遠征隊守衛鬥棍泰坦電光產生器您會收到：\n\n"}
MultiLanguageQuestData['tw'][66448] = {title = "任性的道路守衛", objective = "找到道路守衛艾薇。", description = "自我有記憶以來，道路守衛就開始為旅行者維護薩爪祖斯的道路安全了。這是一個我的家族世世代代都引以為榮的職責。\n\n哎呀，我的妹妹艾薇最近似乎對這個榮耀不感興趣。她每天早上都應該到這來向我報到的，可是我已經超過一天沒有她的消息了。\n\n如果你在東邊找到一頭做著白日夢的青銅龍獸，我請你引導她來見我。不然，我就得親自去找她了。", progress = nil, completion = "喔，嚇死，是個旅行者。請原諒我，我現在是一團糟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66449] = {title = "拯救幼龍行動", objective = "拯救8隻瀕危幼龍，同時消滅12個灼爪鳳凰和縛灰者托那奇。", description = "喀拉希縛塵者正試著囚禁我們的幼龍。他們的領袖似乎打算利用他們做些邪惡的勾當。我們不能讓這種事發生！\n\n不過加拉登不是這裡唯一的敵人。鳳凰也在追蹤我們的幼龍，帶來了更多危險。\n\n你必須保護幼龍，剷除威脅他們的敵人。歐索莉亞會協助你。", progress = nil, completion = "再小的黑色幼龍都必須好好保護。我們的未來全繫於此。\n\n你今天做了一件很了不起的事情。", rewards = "您會收到：\n\n耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮馬褲\n                            顯示 37 更多                        巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊擊聲天賜莫魯克戰旗雍亞拉馴鷹者腰帶戰痕纍纍的鱗片翻騰的熔岩投擲手鬥棍蒼藍秘法增幅器生命烈焰之瓶夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][66456] = {title = "有毒的調色盤", objective = "收集8個毒化長矛。", description = "我或許不太擅長我的工作，不過，至少在我學習怎麼做事時，我很認真在聽。每個有點本事的守道者都知道怎麼製作合格的解毒劑。我只需要足夠的毒藥來適當混合。\n\n諾里說，攻擊她的塔拉賽克拿著塗有這個的長矛。去找到他們，然後把他們的長矛拿來給我。如果我的直覺沒錯，我應該有辦法用矛尖的殘毒做出解毒劑。\n\n我只希望我們來得及。", progress = "請你動作快，<name>。我目前還能穩定諾里的情況，可是毒藥還是持續在擴散。", completion = "&lt;艾薇拿起你收集的長矛。她小心地用匕首刮過其中一柄的刀片，去掉一層黏稠噁心的樹液。&gt;\n\n我就知道會這樣。謝謝你，&lt;name&gt;。要做解毒劑這樣應該夠了，我甚至認為我知道這毒是從哪裡來的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66457] = {title = "結束藍色時期", objective = "殺死藍鱗。", description = "燼牙全部都追隨一個巨大的蠻卒，我為他取名為藍鱗。他一直都是很兇猛的類型，不過他以前都會讓他的拾荒者手下不要到主要道路來。他們確實有領域性，可是敵意？那是最近才有的。\n\n藍鱗必須對這個突然升溫的情勢負責。找到他，然後把他打倒。", progress = nil, completion = "解決了藍鱗，大概有好一段時間不會再遇到有組織的塔拉賽克進犯。\n\n現在只剩下處理毒藥了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66458] = {title = "提爾的遺產：過往的秘密", objective = "進入荒蕪之地的奧達曼：提爾的遺產，然後取回圓盤。", description = "為了阻止菈薩葛絲釋放其他的洪荒化身，必須讓守護巨龍恢復原有的力量。\n\n問題在於，泰坦們現在分身乏術，而守護者提爾又逝世已久。\n\n雅立史卓莎女王提出一個計畫。荒蕪之地的地底深處有座泰坦設施，名為奧達曼。提爾的盟友似乎在那裡藏了一塊圓盤，裡面儲存著他的記憶。\n\n但據說那個地方已經被穴居怪佔據。請召集你的盟友前往奧達曼，為紅龍女王取回圓盤！", progress = nil, completion = "恆龍？他們一直都有不可告人的企圖。\n\n我會通知紅龍女王，請她想別的辦法恢復守護巨龍的力量。", rewards = "甲蟲火炮斬首者的長柄斧沙丘劈劍寶藏搜索員的拳套知識追尋者的鬥棍劫掠者遺失的尖杖蠍子分割刃盜墓者的匕首您會收到：\n\n"}
MultiLanguageQuestData['tw'][66459] = {title = "殘暴野地：恐怖的沼澤巨獸！", objective = "擊敗馬尼特。", description = "歡迎各位來到殘暴野地！\n\n雖然這個決鬥場是用來舉辦傳統活動，但和藹的半人馬給了我許可，在賽季外可以做我的生意。他們說，這可以測試他們的力量並帶來榮耀。\n\n你想要把冠軍的頭銜帶回家嗎？那麼，你準備好就跟我說吧，你就可以參加入門競賽。", progress = "和葛爾薩克說話來開始回合，然後擊敗殘暴野地的第一個參賽者。", completion = "以第一場天梯賽來說，你做得很好。不過這只是暖身而已。等你準備好時，再去找葛爾薩克說話，就可以進行第二輪比賽。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66460] = {title = "殘暴野地：凋零之王！", objective = "擊敗夜腐。", description = "我想找那些兇狠的豺狼人來參加挑戰。可惜的是，我的同事全都不知道要怎麼跟他們溝通。\n\n不過，我們確實成功抓到了他們創造的怪物，應該會是很不錯的對手！等你想開始第二輪比賽時，就跟我說吧！", progress = nil, completion = "幸好你很快就解決它了。那股臭味都開始飄到頒獎台這來了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66461] = {title = "殘暴野地：來自火山的敵人！", objective = "擊敗和平奪取者席加。", description = "這場競賽的第一個志願者來自甦醒海岸。是一個很大的加拉登族，他沒有他的族人那麼憤怒。\n\n他似乎單純享受戰鬥的過程。嘿，正好是我想看的。", progress = "席加有個知名的開場。你需要和葛爾薩克說話來開始回合，然後擊敗殘暴野地的第三個參賽者。", completion = "真精彩的表演！我從這裡都可以感受到火花飛過來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66462] = {title = "殘暴野地：在夢境中迷失！", objective = "擊敗夏雷斯及塔瑞西。", description = "我跟你說，雖然這裡叫巨龍群島，但我看過的龍其實不多。不過，我們確實有接到兩名龍類的要求，說要一起報名這項競賽。\n\n他們似乎很積極想要證明自己的實力，所以祝你好運！", progress = nil, completion = "…怎麼啦？戰鬥結束了嗎？不知道為什麼，我中途好像睡著了。\n\n既然你站在我面前，我猜你贏了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66463] = {title = "殘暴野地：元素生物復仇回合！", objective = "殺死洪荒使者勇士。", description = "我們臨時要更換出場名單。某個洪荒使者大佬想要加入競賽來挑戰你。而我可不會拒絕一頭憤怒的元素龍。\n\n你一定不會有事的。萬一有事，那…嗯，你簽了免責聲明對吧？", progress = "你需要和葛爾薩克說話來開始回合，然後擊敗殘暴野地的第五個參賽者。", completion = "我之前聽說過你和你團員的謠言，而我現在懂了。你撐得比我想像的久多了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66464] = {title = "殘暴野地：狩獵大師！", objective = "擊敗王牌獵手俄瑪阿。", description = "就是這樣。你和你的夥伴成名了。一場和冠軍本人王牌獵手俄瑪阿的對決。先別急著慶祝。她兇狠無比。我們下輩子見。\n\n在她殺死你之後，你的東西可以給我嗎？", progress = nil, completion = "你是位可敬又可畏的戰鬥者。半人馬非常敬佩你。葛爾薩克很後悔他沒有把農地賭在你身上，而是賭在俄瑪阿。你贏得了大獎。", rewards = "平原巡禮手杖岩牙上鉤拳刃風之賢者法杖席卡獵人之弩諾庫德碎顱者席加的牙籤水背天擇之斧您會收到：\n\n"}
MultiLanguageQuestData['tw'][66465] = {title = "儲存與釋放", objective = "摧毀8根藏起來的毒矛。", description = "就算塔拉賽克的領袖死了，他們也不太可能因為我們禮貌請求，就放棄使用沾有毒藥的長矛。我不能冒險讓他們把這種武器用在毫無戒心的旅行者身上。\n\n我們需要摧毀它們全部。如果你在池邊的貯藏處沒有看到，那燼牙很有可能把他們的長矛存放在靠近源頭的地方。\n\n我不能再讓別人因為我的大意而受傷。進入洞穴，摧毀你能找到的武器庫存。", progress = nil, completion = "不用擔心那些毒矛之後，現在通道安全多了。\n\n你今天的行動保護了很多人的安全，&lt;name&gt;。道路守衛，還有我，都欠了你很多。", rewards = "您會收到：\n\n高地飛龍：重型犄角"}
MultiLanguageQuestData['tw'][66467] = {title = "藝術源於生活", objective = "殺死大型毒芽。", description = "上次我到這個洞穴來時，我描繪了一種巨大的花，那種花上面流出一種噁心的黏稠花液。那是我最好的繪畫作品之一，就算我想忘也忘不了。\n\n花液就是那些塔拉賽克長矛上塗的東西，我很肯定。他們一定已經開始採收它，用來毒化他們的武器。\n\n植物本身很美麗，要殺死它會很可惜。然而，我們不能讓塔拉賽克一直採收它。<name>，請把植物切斷，阻止這場混亂吧。", progress = nil, completion = "謝謝你，&lt;name&gt;。既然燼牙的源頭已經被剝奪了，他們收集毒液的日子也就應該結束了。\n\n我現在明白，我不需要成為道路守衛也能改變世界。我會辭去我的職務，然後專注於我的藝術。希望有一天我能描繪出巨龍群島最美麗的景色，讓全世界都能看到。\n\n我只希望我的姊妹能夠理解。", rewards = "畫家繫腰畫家束帶畫家護腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][66468] = {title = "失而復得", objective = "擊敗佔據蓋利奇爾瞰臺的洪荒使者。", description = "<在你靠近時，薩德蘇斯發出譏笑。>\n\n<class>，你是個有行動力的凡人，還是你要讓路給我們？\n\n在那上面，那些洪荒使者讓我失去不少優秀的士兵。\n\n我們知道他們有什麼打算，但我們必須先剷除敵人，然後拯救那些為我效命的人。", progress = nil, completion = "&lt;莎奈克思瞪著你。&gt;\n\n嗯…看來你這傢伙的能力比指揮官當初所想的還要強。\n\n今天還沒結束，還有很多事要做。", rewards = "您能選擇下列奬勵中的一個：\n\n高地飛龍：背上有脊刺\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66470] = {title = "向前的推力", objective = "取得霧感、土靈及冰鑄傳送門之石，並關閉3座元素傳送門。", description = "<莎奈克思抓抓她的下巴。>\n\n指揮官說得對。洪荒使者正在向元素位面求援。\n\n<莎奈克思得意地笑。>\n\n如果他們的傳送門出了什麼事，一定很可惜，<class>。", progress = "我們得把那些傳送門關閉才行。", completion = "看來你完好無缺地抵達這了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66471] = {title = "首要規劃", objective = "在蓋利奇爾瞰臺的上層露臺，從附近的洪荒使者身上收集7個洪荒使者命令。", description = "指揮官命令我建立前線基地，並且消滅所有反抗者。但是，直到我消滅所有反抗者後，我才意識到一些事。\n\n<莎奈克思發出長長一聲嘆息。>\n\n洪荒使者曾經提到提爾堡。\n\n除非你非常擅長審問，不然我會需要你查清楚他們的計畫。", progress = "你有什麼我們可以拿給指揮官看的東西嗎？", completion = "這正是我們需要的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66472] = {title = "洪荒清單", objective = "把一捆洪荒使者命令交給蓋利奇爾瞰臺橋上的指揮官薩德蘇斯。", description = "關閉傳送門、殺死元素生物，阻止洪荒使者…就算只是暫時的也好。\n\n<莎奈克思笑了笑。>\n\n<class>，還有什麼事我們辦不到嗎？我猜只有時間才能告訴我們了。\n\n把計畫書帶回去給指揮官。我們得到的斬獲，一定能讓他非常高興。", progress = "<薩德蘇斯盯著你。>\n\n你想幹嘛，<class>？", completion = "&lt;薩德蘇斯尷尬地停頓一陣子。&gt;\n\n我和艾利斯還在打賭你會不會成功，&lt;class&gt;。\n\n很高興你成功了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66473] = {title = "大地甦醒", objective = "在蓋利奇爾瞰臺擊敗原初之怒及原初冰雹。", description = "這個洞穴裡面的怪物太多了，我應付不來。\n\n<莎奈克思重重咳了一下。>\n\n我已經見識過你的能耐。\n\n我需要你殺死這些元素生物，別讓它們恢復全部力量。我們不能讓洪荒使者掌控提爾堡！", progress = nil, completion = "謝謝你為我們做的一切，&lt;class&gt;。", rewards = "您會收到：\n\n高地飛龍：下巴有鬃毛"}
MultiLanguageQuestData['tw'][66488] = {title = "懸賞：弗利葛魯斯", objective = "到安東尼達斯營地附近殺死弗利葛魯斯。", description = "<頁面上的文字發出柔和的藍光。>\n\n元素生物弗利葛魯斯以前是瑪里苟斯最喜歡的玩物，但處於無主狀態已經很久了。\n\n這座過去充滿歡笑的據點，現在卻是一片斷垣殘壁。受到肆虐這片土地的邪惡力量影響，這個粗魯、愛搗蛋的生物也變得乖戾且扭曲。\n\n請務必將其消滅，並且注意安全。\n\n成功之後，請告知管理者辛雷苟斯。", progress = nil, completion = "讓我們祈禱不會再有驚喜被困在冰河裡吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66489] = {title = "鞏固防禦", objective = "在安東尼達斯營地中強化蒼藍防衛者。", description = "管理者辛雷苟斯和我剛剛正在討論，洪荒使者的攻擊行動對進攻鈷藍集會的計畫造成什麼影響，對此我有個想法。\n\n<瑟莉絲蒂從長袍的口袋抽出魔杖。>\n\n帶著我的魔杖，強化他們的武器！\n\n只要來點火焰應該就沒問題了…", progress = nil, completion = "做得非常好！\n\n擊退進攻營地的洪荒使者後，我們必須繼續讓他們處於下風。\n\n現在請把魔杖還給我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66493] = {title = "送信！", objective = "在安東尼達斯營地把包裹丟給祈倫托學徒。", description = "<你聽到從傳送門的另一端傳來沉悶的低語。>\n\n喂！對，就是你！\n\n我有些信件要給我們的學徒：家裡寄來的包裹、禮物、還有他們透過魔法信差下訂的東西。\n\n就是些常見的東西。\n\n你可以幫我一個忙，把它們分發出去嗎？", progress = nil, completion = "做得好！別擔心…要是包裹上面沒有「易碎品」的標籤，一定是信差的錯。", rewards = "您會收到：\n\n高地飛龍：頭部有三鰭"}
MultiLanguageQuestData['tw'][66500] = {title = "觀看的方式", objective = "在安東尼達斯營地發掘古老的影像。", description = "我們什麼都沒做！我們什麼都沒做！\n\n等一下…\n\n你好像是個非常重要的<race>…想知道一個秘密嗎？\n\n那就是，廢墟裡面好像有某種魔法。而且我們看得見它！\n\n<斯克朗比驕傲地挺起胸膛。>\n\n我可以教你怎麼樣才看得見！只是…要先對諾麗可保密。", progress = "諾麗可要我們別惹麻煩。老實說，我從來沒聽過這種要求。", completion = "瑪里苟斯和辛德拉苟莎啊？聽都沒聽過。聽起來他們挺相愛的。\n\n不知道是誰把這些放在這的？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66503] = {title = "為了他人的愛", objective = "調查安東尼達斯營地的廢墟高塔頂端。", description = "啊，我看到我的學徒們把你拉進了他們的小遊戲。\n\n<諾麗可輕笑。>\n\n看來他們跟你，在偶然間發現了什麼東西。這些廢墟背後的目的正在慢慢向我們展露出來，不只是現在看到的褪色圖案和歌曲…\n\n這座塔的塔頂上面有什麼在呼喚著。\n\n我在你眼裡看到了好奇的光芒。去吧，我准許你前往。\n\n看看你會發現什麼。", progress = nil, completion = "看著你的世界淪為一片荒蕪，想像一切永遠失傳…\n\n我想都不敢想。\n\n我們一定要記得。", rewards = "您會收到：\n\n迪佛的破布甲愛情手冊"}
MultiLanguageQuestData['tw'][66508] = {title = "輕輕搖晃過的禮物", objective = "這個禮物看起來好像已經被稍微搖晃了幾次。上面的標籤寫著：\n\n給最特別的<race><class>。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n輕輕搖晃過的禮物"}
MultiLanguageQuestData['tw'][66511] = {title = "伊斯凱拉巨牙海民名人", objective = "在伊斯凱拉與慕里克交談。", description = "你持續向我們證明你是我們不可或缺的一份子。\n\n為了向這份羈絆致敬，請到伊斯凱拉找我，我準備了一袋補給品要送你。", progress = nil, completion = "我們要再次對你至上無盡感激。這些小小禮物，不成敬意，但請務必知道，你的協助對我們意義重大！", rewards = "您會收到：\n\n裝滿的伊斯凱拉補給背包滿溢伊斯凱拉補給包"}
MultiLanguageQuestData['tw'][66513] = {title = "展翅高飛", objective = "探索暴風城。", description = "要是這座城市會變成我們的新家，也許應該先稍微了解一下，例如偵察任務什麼的。\n\n去看看這個地方的生活機能。我會跟著怒西昂，盡我的力量幫助他。\n\n非必要的話，就別去招惹當地人。對了，我認為他們應該不常看到有龍出現在他們的街道上。\n\n等到你弄清楚狀況後，再回來找我們。", progress = nil, completion = "聯盟允許我們在暴風城接受庇護。\n\n聽起來是個有趣的地方。", rewards = nil}
MultiLanguageQuestData['tw'][66516] = {title = "普通寶石？我不這麼認為！", objective = "從巨龍群島的加拉登身上收集25個「普通」寶石，交給龍鱗遠征隊的諾克林‧異圈。", description = "真是浪費，這裡的加拉登把強大的寶石當作一般珠寶裝飾品而已！寶石可是有很多用處的，望遠鏡、鏡子、聚焦指示器，更不用說它們具備的無數魔法特性。\n\n我們必須改正這個情形，探險者。拿走那些加拉登的寶石，帶回來給我，我會讓它們發揮更好的作用。不過要小心，加拉登都是勇猛的戰士。", progress = "你成功取得寶石了嗎？", completion = "這些寶石潛力無窮，恐怕就連盧格拉都不知道要怎麼才能全部處理好！\n\n盧格拉是工匠協會的珠寶設計代表。我來分享她之前寄給我的一些筆記，應該對你學習巨龍群島的珠寶設計研究有幫助。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][66517] = {title = "新的武器來源", objective = "從巨龍群島的碎裂火焰軍收集25個完整的半龍人武器，交給莫魯克半人馬的杜瑞娥。", description = "這些碎裂火焰軍對我們的邊界構成了嚴重的威脅，而他們持用的武器尤其讓人擔心。盡你所能收集他們的武器，讓我們可以仔細研究這些武器的弱點，甚至用來加強我們的防禦。\n\n外來者，我對你有信心。只要你好好完成這個任務，我會把我們的鍛造技術傳授給你。", progress = "你找到了什麼？", completion = "外來者，謝謝你。這對我們很有幫助。\n\n然後這是答應的獎勵，我請鐵匠為你準備的卷軸。希望裡面的知識能讓你學得更快更好。", rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][66523] = {title = "照看熔爐", objective = "聚集熔爐所需要的材料：在安東尼達斯營地附近收集角蛙皮、惰性餘燼錐和崩裂核心。", description = "如果你要找某位講師，我只能說…啊，你不是學徒！真抱歉。請讓我自我介紹。\n\n我是管理者維娜苟斯，負責管理這些廢墟。更具體地說，讓這裡恢復過往的榮光，就是疲備不堪的我必須肩負起的任務。\n\n你能夠幫幫我嗎？我需要的施法材料都在這附近：冰元素核心、餘燼錐、角蛙皮…\n\n都是些很常見的東西。", progress = "新鮮空氣和魔法聖物。夫復何求呢？哈！", completion = "謝謝你，&lt;name&gt;。餘燼錐會熊熊燃燒。而元素核心能控制高溫。至於角蛙皮…還是很噁心。不過用它製成的風箱非常好用！\n\n現在，我只需要時間了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66524] = {title = "業餘攝影", objective = "為元龍拍照。", description = "你想成為像我這樣老練的編目員？你來對地方了！\n\n野生保育區到處都是等著被發現和建檔的知識！你問我是怎麼辦到的？當然是利用我的生態記錄器3000型巨龍群島版，這一版還改進了動態捕捉功能！\n\n為了讓你多點經驗，請去拍攝一些照片，包含元龍蛋、學飛的幼龍，還有狩獵中的元龍。然後到這裡西邊的古老元龍骨架旁找我，我會對你的照片給予評價。", progress = nil, completion = "這些實在太棒了！棒到不行！話說，你之前是不是有類似的經驗？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66525] = {title = "競賽攝影", objective = "拍攝灌能元龍蛋和灌能元龍的照片。", description = "既然你已經拍了一些入門級的照片，現在不如稍微提高一下難度吧？\n\n我發現在我們後面的區域，有隻很漂亮的元龍正在飛行。牠有著美麗的角，鱗片還不斷發出電光！這應該是洪荒使者的傑作，不過藝術就是藝術！\n\n看看你能不能拍到那隻元龍和牠的龍蛋的照片。你可能需要爬到高一點的地方，才能拍到好照片！", progress = nil, completion = "喔，看看這個！色彩看起來非常鮮豔。看來你已經是非常出色的編目員了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66526] = {title = "保育工作", objective = "釋放5隻被捕獲的元龍幼龍或被捕獲的元龍。", description = "野生保育區是少數幾個能讓元龍繁衍生息的地方之一。不過，洪荒使者派人去捕捉元龍和牠們的幼龍來進行實驗，把牠們的築巢地搞得雞飛狗跳。\n\n別對他們手下留情。找到那些洪荒使者的盜獵者，除掉他們，並且釋放他們捕獲的獵物。元龍種族的安危全繫於此。", progress = nil, completion = "做得好。洪荒使者仍是個威脅，不過至少這些元龍再次享有自由了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66527] = {title = "專業攝影", objective = "使用垂直增強器，拍攝沉睡元龍的照片。", description = "我從沒訓練過像你這麼優秀的攝影師…而且還活得好好的。這其實是一份危險的工作。\n\n說到危險，我們的最後一個目標是一隻巨大的元龍，我們認為牠很可能成為這個保育區的下一個至尊掠食者。讓我們幫牠拍張個人特寫照吧！", progress = nil, completion = "順便一提，你在上面沒見到另一台相機，對吧？\n\n算了，當我什麼都沒說。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66528] = {title = "無冠之王", objective = "調查元龍骸骨。", description = "這隻古老元龍生前一定是非常霸氣的生物，也許是這個野生保育區有始以來體型最大的生物。\n\n但是，不只如此，要是你更仔細觀察骸骨，我們或許能還原它死前的遭遇。", progress = nil, completion = "看來，牠是跟同樣強大的生物對抗，奮戰至死？牠是不是為了守護保育區，不讓外來者入侵？\n\n謝謝你，&lt;name&gt;。能夠得知那些先行者付出的犧牲，是件好事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66529] = {title = "千言萬語", objective = "拍攝德維希安與元龍骸骨的合照。", description = "了解這裡過去發生的事後，我強烈認為應該留下一點紀念再離開。\n\n你能不能幫我跟這具元龍化石拍張合照？", progress = nil, completion = "希望有朝一日，我能像這隻元龍死前一樣，鼓起勇氣為我的族人而戰。\n\n再次感謝你，&lt;name&gt;！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66546] = {title = "取回圓盤", objective = "取回三個圓盤。", description = "這些圓盤就代表著設施裡的所有知識。我們必須取回它們！\n\n我會操作控制臺解除屏障。取回圓盤的事就交給你了。", progress = "你能想像這些圓盤裡收藏了什麼知識嗎?!", completion = "你果然非常可靠！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66547] = {title = "遲早該放到博物館", objective = "回到龍鱗遠征隊營地和多蒂會面。", description = "一波又一波的泰坦保全裝置、逃脫的元龍、把你變成傀儡的鑰匙…我只是說說啦。\n\n但我這輩子從來沒這麼開心過！\n\n雖然納蕾迪亞大概會說，真正的樂趣現在才要開始。多虧了你的努力，我們現在坐擁一大堆泰坦機密資料！\n\n有空的話，到營地找我們，我們一起比對筆記。", progress = "再次感謝你帶給我一生難忘的體驗。", completion = "我們的線索都斷了，至少現在沒辦法從這些圓盤中解讀出更多資訊。\n\n在那之前，記得多觀察四周和調查線索。你永遠都不知道下一場冒險會在何時出現！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66551] = {title = "三人成虎", objective = "在寵物對戰中擊敗漢妮可", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66553] = {title = "山谷線索", objective = "在冬毛谷找出6個線索。", description = "冬毛族在熊怪中是個特殊案例。\n\n我會把他們歸類為「孤立主義者」。他們是山谷中的鬼魂，他們的毛皮融入在雪景之中。\n\n以前都不太理人，但現在侵略性非常明顯。他們無預警地攻擊了我們的營地！\n\n一定有什麼事不對勁才會驅使他們這樣。我無法問他們發生了什麼事…還不行…可是，或許你可以在他們的村莊裡找到線索？", progress = nil, completion = "喂，你找到了什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66554] = {title = "進攻是最好的防守", objective = "擊敗6個冬毛熊怪。", description = "冬毛族現在都有點神經兮兮，我不覺得他們會喜歡你在那一帶探頭探腦。\n\n如果他們惹事的話，你儘管保護自己。只要讓他們知道你是玩真的，或許就有辦法讓他們講理一點。\n\n不過，盡量別殺人，好嗎？我知道你們這種冒險家有時候會太激動。", progress = nil, completion = "希望你沒讓他們太難受。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66555] = {title = "熊、熊怪、熊怪語", objective = "協助索諾瓦進行翻譯。", description = "是的，聽起來上頭真的是一團亂…一副暴風雨過境，破壞了整個地方那樣。我懂他們為什麼要武裝自己，可是為什麼要攻擊我們呢？\n\n要是我們可以談談，一切就簡單多了，可是冬毛族口風很緊，這點大家都知道，而且他們似乎不會說任何常見的熊怪話。熊怪語？呃，反正你知道我在說什麼。\n\n你去調查的時候，有和誰聊天嗎？", progress = nil, completion = "現在來翻譯這些亂七八糟的…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66556] = {title = "去那冰洞穴", objective = "調查洞穴。", description = "嗯，你的口音很糟糕，一萬年的孤立和語言變化也沒讓事情變比較容易，但我好像大概了解意思了。\n\n基本上他們主要說的內容，是有關於「壞洞穴風」或「邪惡風暴洞穴」之類的。不然就是說他們的髒衣服太星期四了？\n\n這可不像學習地精語那樣，肯定會有些翻錯的地方。不過，洞穴的事情我還蠻確定的，我們從這開始著手吧。", progress = nil, completion = "告訴過你了，至少洞穴的部分我沒弄錯。現在我們可以來試著建立一點外交關係。", rewards = "您會收到：\n\n烈風迅疾龍：脖子有鰭冰凍裂片戒指"}
MultiLanguageQuestData['tw'][66557] = {title = "學術上的熟人", objective = "在荒僻營地找到另一個熊怪語言的專家。", description = "是的，就連我都覺得，熊怪的這個冬毛方言非常難以理解。\n\n我在荒僻營地有一些同事，他們或許能幫上忙。我聽說這個地區還有其他的熊怪部族，比對相關方言的筆記後，或許會有些進展。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66558] = {title = "洛威", objective = "找到洛威。", description = "你是那個和其他人一起從蕨皮回來的人，對嗎？那你大概知道卡加塔發生了什麼事…\n\n自從她沒有跟著布蕾娜和其他人回來，她的兒子洛威就一直很焦慮。我會留在這裡等他回來，但是你能不能去找他？\n\n我猜他跑去東邊那個冰洞穴了。他說了什麼要跟裡頭的雪人戰鬥！", progress = nil, completion = "謝謝你幫我，你是好人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66577] = {title = "守護巨龍的邀約", objective = "與怒西昂交談，了解議會的討論結果。", description = "啊，$p，你來得正好！\n\n我剛剛才跟總指揮官圖拉揚和他的盟友見過面，他們決定接受守護巨龍的邀約，前往巨龍群島。\n\n你當然也會一起去吧？要是沒有你，這趟旅程的樂趣肯定會大打折扣！\n\n然後相信你已經注意到，這裡出現了一些陌生面孔。那些有翼生物叫做半龍人。他們剛認識我不久，但已經被我的魅力所折服。\n\n啊，請恕我無禮，我不該一直自誇。", progress = nil, completion = "我等不及要跟你一起去巨龍群島了，&lt;name&gt;！\n\n對了，你們那位小個頭的盟友還提到了組織一個探險遠征隊的事情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66579] = {title = "療癒之聲", objective = "把共鳴圓盤帶給在信仰之憩的歐利亞瑪努。\n\n已提供物品：\n", description = "<你彷彿可聽見圓盤發出的療癒低鳴。\n\n歐利亞瑪努可能知道更多資訊。>", progress = nil, completion = "閻獄之主已不復存在。你帶來的東西足以證明澤瑞斯莫提斯正在自我療癒！這會進而發展出更多新的工具。能跟暗語產生強烈共鳴的工具。你可以用這些工具來消滅剩餘的淵誓者。", rewards = "您會學到：\n\n共鳴圓盤\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66582] = {title = "取得力量", objective = "到安東尼達斯營地，為躍傳法師德蘭卓拉收集容器中的能量。", description = "在正常情況下，捕捉能量不是什麼問題。不過，我們需要的能量既巨大又不穩定。這個秘能容器就是安全運輸它的方法。\n\n西南方有個地區住著許多充滿能量的生物。這些生物體內的異常能量非常強大，可是很不穩定。\n\n捕捉他們的能量，再回來找我。到時候我們再一起踏上剩下的旅程。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66586] = {title = "提爾的遺產：過往的秘密", objective = "進入荒蕪之地的奧達曼。調查騷動的原因。", description = "為了阻止菈薩葛絲釋放其他的洪荒化身，必須讓守護巨龍恢復原有的力量。\n\n但這不是一件容易的事情。泰坦們毫無回應，而守護者提爾又逝世已久。\n\n雅立史卓莎女王想出了一個計畫。荒蕪之地的地底深處有座泰坦設施，名為奧達曼。她相信提爾的盟友在那裡藏了一塊圓盤，裡面儲存著他的記憶。\n\n召集盟友和你一同前往奧達曼，為紅龍女王取回圓盤。希望提爾留存的知識可以重新恢復守護巨龍的力量。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "甲蟲火炮斬首者的長柄斧沙丘劈劍寶藏搜索員的拳套知識追尋者的鬥棍劫掠者遺失的尖杖蠍子分割刃盜墓者的匕首您會收到：\n\n"}
MultiLanguageQuestData['tw'][66588] = {title = "長者史瓦格蛙", objective = "在寵物對戰中擊敗史瓦格蛙。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66589] = {title = "遠征行動", objective = "為巨龍群島探險隊在暴風城各地招募探險者、工匠和學者。", description = "我叫多蒂，我是龍鱗遠征隊的代表，負責帶領我們這群歡樂的冒險者。詳細的內容稍後再來說明，現在我們得優先召募成員。\n\n每個稱職的探險遠征隊都需要各式各樣的人才，包含學者、工匠，當然還有探險者。\n\n怎麼了？你還站在這裡做什麼？快去召集成員！", progress = nil, completion = "真是神速！\n\n是不是急著要去巨龍群島啊？我也是！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66595] = {title = "休眠的發現", objective = "到甦醒海岸的晶紅鱗哨站，向塞林‧暗砧報到。", description = "<別去想這張奇怪的羊皮紙怎麼跑到你的背包裡的。重要的是訊息的內容。>\n\n致龍鱗遠征隊成員：\n\n現在急需你們出手相助！請立刻前往晶紅鱗哨站報到！\n\n<在看到簽名處之前，羊皮紙上的魔法文字就冒出一陣白煙，分解成藍色的塵埃，只留下空白的紙頁和殘留的甜美花香。>", progress = nil, completion = "訊息？什麼訊息？\n\n你說它神秘消失了是什麼意思？\n\n嗯…沒關係。反正我們有很多事情要談。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66596] = {title = "風中的低語", objective = "在暴風城與大法師卡德加交談。", description = "哈囉，$p。好久不見，我很想多跟你分享一下彼此的近況。\n\n不過，我剛剛跟一位老朋友聊過，我覺得深受啟發…不，應該說警兆已現…沒錯，警兆已現。\n\n畢竟啟示有時候總是好壞摻半。\n\n我真的必須告訴你，我剛才得知的事。", progress = nil, completion = "我能理解你的反應，我敢說我也有同感。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66597] = {title = "這顆老石頭", objective = "檢視蝕刻遠古石碑。", description = "我身後的石頭只是一塊我們在群島上碰巧發現的，怎麼說來著…遠古科技。\n\n但問題是，我們還不能完全確定它們是什麼。挺令人困惑的。\n\n我們已經傳遞消息給一些朋友，問他們能否幫上忙。在這期間，或許你可以搞清楚要怎麼用它？", progress = nil, completion = "什麼符號！？這可不妙…\n\n&lt;塞林搔搔鬍子。&gt;\n\n只有一個方法才能確定。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66598] = {title = "夜裔精靈小知識", objective = "在蒼藍高地的安東尼達斯營地找到躍傳法師德蘭卓拉。", description = "遠古符號不算我的專長。不過…\n\n<塞林翻找他的隨身物，終於拉出一張地圖。羊皮紙頂端寫著安東尼達斯的名字，字體又大又潦草。>\n\n啊哈！在這裡！\n\n要走一段路，但你可以找到幾個古老魔法的使用者…就在這裡。\n\n<指著地圖上的一個點。>\n\n或許他們可以提供些情報。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66612] = {title = "護蟹者的難題", objective = "在崖瀝營地殺死12個戈洛克。", description = "螃蟹有危險了！\n\n這群螃蟹已經經歷了一個難熬的季節。牠們的上一個棲息地被洪荒使者給洗劫了，所以我就把牠們引到這個地區來，結果牠們又被戈洛克入侵！\n\n我以為牠們在這裡很安全，可是戈洛克只會刺激螃蟹逞兇鬥狠，會讓牠們提早滅絕！\n\n拜託，去擊倒那些戈洛克，讓螃蟹可以逃走吧！", progress = nil, completion = "守護巨龍的恩典照耀你，&lt;name&gt;！你拯救了我心愛的螃蟹！我以後會更小心地顧好牠們的。戈洛克別想再干涉我的螃蟹！", rewards = "您會收到：\n\n"}
