MultiLanguageQuestData['tw'][66620] = {title = "翡翠召喚", objective = "在雍亞拉平原的麥琳瑟拉崗哨與麥琳瑟拉交談。", description = "綠龍軍團的麥琳瑟拉請你到翡翠花園去找她。\n\n藍龍軍團的特使已經前來了解花園的情況。儘管我們過去與藍龍有過一些紛爭，所以她認為必須得維持友好、正向的關係。\n\n她在翡翠花園的棲所就在林蔭聖所上面的麥琳瑟拉崗哨。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66622] = {title = "任性的工具", objective = "救援6個任性的工具。", description = "太可怕了！我的…嗝…工具似乎在我不注意的時候跑走了。想到他們…嗝…孤單地在外頭就讓我不忍心，他們一定嚇壞了！\n\n你可以幫我把他們帶回來嗎？記得要有耐心，然後…嗝…盡量安撫他們，我敢說這樣他們就會接近你了！", progress = nil, completion = "謝謝你，&lt;name&gt;！我會*嗝*永遠記得你的英勇行為！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66633] = {title = "做出聲明", objective = "將黑龍旗幟插在12具加拉登的屍體上。", description = "這些加拉登相信黑龍軍團已經玩完了。他們對怒西昂在這裡的威權，既不畏懼也毫無敬意。\n\n我們需要做出聲明，提醒他們黑龍軍團回來了，而且比以往更強大。\n\n殺死加拉登，標記每一具屍體，這樣他們才不會忘記誰才是這裡的老大。", progress = nil, completion = "看來你很熟練，&lt;name&gt;。這會是最強而有力的示威。", rewards = "您會收到：\n\n耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮馬褲\n                            顯示 51 更多                        巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊擊聲天賜穿刺席卡刺矛精確校準的手持火砲儀祭雍伊爾匕首熔岩鍛造斬首者掠龍憤怒短劍世界破擊者之槌諾庫德穿刺長戟莫魯克戰旗雍亞拉馴鷹者腰帶戰痕纍纍的鱗片騎兵衝鋒長槍血腥戰騎串刺龍鰻盜獵者燼刃翻騰的熔岩投擲手鬥棍加拉登恫嚇錘伊斯卡秘法師斬潮錘長者的螢光長棍熔火拳師之拳強化洞察短劍蒼藍秘法增幅器生命烈焰之瓶夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼巨龍群島補給品"}
MultiLanguageQuestData['tw'][66635] = {title = "再次相聚", objective = "與伊瑟拉交談，減弱屏障的威力。", description = "這樣應該夠了。我能感覺到其他人就在林地的外面，準備要進入夢境。\n\n等你準備好的時候跟我說，我會打破冰牆，把屏障降下來。希望我的改變不會讓軍團灰心。\n\n我們還沒有放棄，我們全部都會再度相聚。", progress = nil, completion = "我不敢相信。我所希望的一切…\n\n她在這裡。\n\n但我感覺得出來她變了。我不知道這代表了什麼，而且我擔心我們沒有時間思考這個問題。我們必須去追萊梅克。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66636] = {title = "另外一側", objective = "使用看守者法杖將門打開。", description = "我們總算搞清楚第三顆石頭的放置位置，那重責大任就交給你了！我已經把石頭裝到看守者法杖的殘餘部分上。爬上那裡的鷹架，高舉法杖，表演就準備開始了！", progress = nil, completion = "這裡有好多東西可以探索，我們才剛開始而已！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66646] = {title = "消除因果", objective = "殺死時間元素生物。", description = "恆龍迫使時間能量變得激進。這下糟了。\n\n在協助克羅諾穆大使的時候，請殺死所有遇到的時間元素生物吧。我會留在這裡，協助她壓制伊特努斯。", progress = nil, completion = "做得非常好！我通常反對大開殺戒，不過今天是個例外。", rewards = "時間之道短棒時織之刃急速射擊無情分離歲月如梭青銅之塔克羅米的備用信標時間鋼鐵屏障您會收到：\n\n"}
MultiLanguageQuestData['tw'][66647] = {title = "元素反集中", objective = "取得元素法器。", description = "卡雷苟斯跟我在山脈上方的天空中遭到猛烈的攻擊。洪荒使者殘酷無情，他們的軍隊無窮無盡。\n\n很快地，卡雷苟斯跟我就可能被他們的部隊給擊垮。\n\n不過，我有個計畫。\n\n在山腳下有個叫做魯文‧碎石者的暴躁獸人。祈倫托和她決鬥過好幾次。\n\n她有一個裝置，可以吸收並轉移元素能量。\n\n從她手上拿到裝置，然後再深入一點去和我會合。", progress = "如果你能拿回那個元素法器，應該會派得上用場。", completion = "就是這個！把東西帶在身邊…在接下來的行動中，你會用到的。", rewards = "疾風捲束帶變形皮甲腰帶刺藤鍊甲腰帶霰耀護腰您會收到：\n\n"}
MultiLanguageQuestData['tw'][66648] = {title = "命運交織", objective = "擊敗30個不同的命定團隊副本首領。", description = "<現實圍繞，你對這個地方的記憶，隨著時間的流逝變得模糊、扭曲。某個東西改變了。>\n\n<儘管似曾相識，但你非常確定這不是你所熟悉的那個地方。不完全一樣。>\n\n<然而，前方的道路等著。你不會讓詭計或扭曲的現實耽誤你的宿命。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66649] = {title = "轉動命運", objective = "擊敗15個不同的命定團隊副本首領。", description = "<經過多次試煉，有股力量在你體內滋長。這些不明的異象，如今已不會使你困惑，反而讓你感到自在。>\n\n<再次奔向未知。與黑暗搏鬥，緊握自己的命運。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66650] = {title = "命定終章", objective = "擊敗5個不同的命定團隊副本首領。", description = "<你是冷靜的。這是一種未知的體驗，但對你來說已經不陌生。面對這些難關你已經駕輕就熟，而明朗化是你最終的獎勵。>\n\n<你的思考清晰，最後一次穩健地向前邁進。創造自己的命運，看著它逐漸展開。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66651] = {title = "諾庫無德", objective = "到永恆墓塚找學徒左里克。", description = "諾庫德和烏克赫族已經佔領了永恆墓塚。他們的肯定有什麼邪惡的目的。我們最崇敬的祖先都葬在那裡。\n\n我之前派出學徒左里克前去調查。他到現在還沒回來。\n\n他的能力不差，但缺乏自信。請助他一臂之力，阻止他們的邪惡行動！", progress = nil, completion = "烏克赫氏族用黑暗魔法為自己帶來蒙羞。現在，他們已經和諾庫德盟友一起進入了墓塚。任何氏族都不該來這的！我一直在這裡觀察，他們看不到我，所以很安全。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66652] = {title = "回去找治癒者", objective = "到附近的墳塚調查烏克赫的儀式。", description = "我從這裡看不到他們在做什麼，但我擔心他們在褻瀆墓塚。\n\n請你到最近的墓去，看看你能不能阻止他們在進行的儀式。\n\n如果你發現了能得知他們目標的線索，也請帶回來給我。", progress = "你成功阻止儀式了嗎？有得到他們在做什麼的線索嗎？", completion = "這支長矛…之前是我母親，凱絲安的。她是名偉大的獵人。在她生病時，我…我救不了她。\n\n跟所有偉大的莫魯克半人馬一樣，她和她的武器一起埋葬。可是，這代表烏克赫族在用這些武器喚起並束縛靈魂，讓它們受他們使喚…包含我的母親在內！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66654] = {title = "殲滅褻瀆者", objective = "殺死諾庫德褻瀆者和烏克赫掘墓者，取回他們拿走的先祖武器。", description = "我的母親生前是位英雄。她值得平靜與安息，而不是…被人奴役！我們的英雄都不該被奴役。\n\n他們得付出代價。我們要讓祖先再次帶著武器和榮耀安息。把武器從褻瀆者的手中奪回來！", progress = "你從盜墓者那兒奪回武器了嗎？", completion = "這是個好的開始。我可以用這些武器來解放他們的主人…希望如此。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66655] = {title = "死靈魔法的破除材料", objective = "從復活的夥伴身上收集4個完整頭骨，並收集6份神聖土壤。", description = "就算我們把靈魂從烏克赫的掌握中釋放，我擔心他們會沒辦法找到他們的墓碑。\n\n烏克赫族也在喚起祖先的動物夥伴，這些夥伴在生前都會引導和保護他們。\n\n把那些動物的顱骨還有被這些敵人侵擾的聖土拿來給我。只要把這些材料結合，它們應該可以幫助祖先找到寧靜。", progress = "你拿到施法材料了嗎？在烏克赫氏族把祖先從墓塚帶走前，我們必須解放他們。", completion = "完美！我應該可以用這些把他們從烏克赫族手中釋放。他們就可以再次獲得應有的安息了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66656] = {title = "絕對是永恆沉睡", objective = "擊敗每個知名的半人馬靈魂，然後使用左里克的安息圖騰釋放它們。", description = "祖先們被這個黑暗魔法操控，一看到目標就會攻擊。烏克赫復活了我們最勇猛的戰士和獵人，阻止他們絕非易事。\n\n我會一起去幫忙。該是我母親的長矛重出江湖的時候了。\n\n擊敗他們後，使用我製作的這個圖騰，協助被制伏的靈魂找到返回墓塚的路。", progress = nil, completion = "我的母親再次獲得寧靜，真令我欣慰。謝謝你，&lt;name&gt;！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66658] = {title = "諾庫德進攻據點：誰找到就是誰的", objective = "進入諾庫德進攻據點，擊敗蹄拉和莫魯克，然後將他們的武器放入蹄拉凱墓塚。", description = "在我們阻止喚墓者阿爾班之前，提拉和莫魯克的武器就被拿走了。我們最偉大的祖先有可能再次在這平原上戰鬥…而且是為了諾庫德。\n\n到諾庫德進攻地去。找到莫魯克和蹄拉。在你制伏他們之後，把他們的武器帶回提拉依墓塚。我們會讓他們帶著應有的榮耀再次安息，這次要在我們能更容易守護的地方。", progress = "你能夠擊敗創立我們部族的傳奇英雄的靈魂嗎？", completion = "我從來沒想過外來者會幫忙。我很感謝你。", rewards = "您會收到：\n\n再生元龍：濃密眉噴泉行者面具刺繡寬蹄風帽角質強化罩盔斷矛者十字盔"}
MultiLanguageQuestData['tw'][66660] = {title = "就位…預備…", objective = "回到過去，加入安但丁諾穆及西雅澤拉瑟。", description = "<諾茲多姆眼神空洞。>\n\n他們穿梭掉落得越遠，移動的速度就越快。而且在時光結構上打穿一個個破洞，產生巨大的漣漪。你必須加快動作趕上他們。\n\n<諾茲多姆的視線重新聚焦，轉向看著你。>\n\n我會派出時光行者協助你在時間之道找到方向，加速你的任務進行速度。避免和各個時空的居民交流，而且在你找到克羅諾穆之前，別停下腳步！\n\n快去吧，我們的時間異常寶貴。", progress = nil, completion = "準備好了嗎，&lt;name&gt;？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66661] = {title = "只是個不值錢的硬幣", objective = "到奧睿博司尋找仲介者以獲得更多訊息。", description = "<你對這個奇怪的物品有很多疑惑。你是怎麼取得它的？它有什麼用途？它有危險性嗎？>\n\n<如果永恆之城沒有你要的答案，那麼在那裡行商的仲介者一定能替你解惑。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66671] = {title = "步入荒野", objective = "在蒼藍高地的荒僻營地與麥迪‧散射會面。", description = "你看起來是個有熱情、有能力的冒險者！你想不想協助龍鱗遠征隊啊？\n\n我們在一小塊美妙的荒野中有一座可愛的營地。\n\n如果你想去那裡旅行的話，那裡有很多事可以做。\n\n等你到了那裡之後，找我妹妹麥迪談談。她會讓你好好安頓下來。", progress = nil, completion = "凱迪派你來的？在巨牙海民和熊怪之間的騷動爆發之前，她根本不在這裡！\n\n光是說營地有很多事情要做，根本是低估了情勢。我們要被問題淹沒啦！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66673] = {title = "與寇拉諾斯談話", objective = "到沃卓肯與寇拉諾斯交談。", description = "看守者多年來觀察著諸多事物。許多都迷失在變化莫測的時間當中。不過我們還有寇拉諾斯。", progress = nil, completion = "我們非得和碎裂火焰軍打上一架，才有可能取回這些石頭。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66675] = {title = "守護巨龍之力", objective = "在誓言母石協助雅立史卓莎。", description = "誓言母石是泰坦賜給我們龍族的遠古贈禮。如果我們調查獲得的情報屬實，我或許可以重啟它，藉此恢復我們的守護巨龍之力。\n\n雖然我們無法保證一定可行，但只要這個方法有一絲成功的機會，我就必須嘗試。\n\n<name>，如果你願意與我合作，我會很感激的。", progress = nil, completion = "&lt;name&gt;，發生了什麼事？雅立史卓莎在哪裡？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66676] = {title = "溜回來", objective = "回到雍伊爾溫泉向菈迪亞回報。", description = "這就是莉茲…我的秘密朋友。自從牠被媽媽遺棄後，我就一直在照顧牠。\n\n情況看起來不太妙，我完全不知道他們對牠做了什麼。我必須帶牠回家，雍或許會讓我禁足到世界末日，不過我一定要救莉茲。我非常感激你的幫忙，$p。很抱歉，增加你預期之外的工作。\n\n如果你不介意再冒險一次…願意跟我一起面對雍的怒火嗎？請回去溫泉那裡找我。", progress = nil, completion = "你回來了！聽著…莉茲不會有事的。", rewards = "角質強化靴子斷矛者護足鑲邊寬蹄裹足您會收到：\n\n"}
MultiLanguageQuestData['tw'][66679] = {title = "晶紅生命聖殿迴圈賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66680] = {title = "數羊", objective = "用食物降低小願的戒心，然後用小願的哨子在睿冠松林拯救5隻迷路的阿戈利羊。", description = "真讓人沮喪。當我和我的兄弟歐雷克外出偵察的時候，一隻發瘋的雄鹿攻擊我們。\n\n<瓦杜指著他血淋淋的腳，並皺起眉頭。>\n\n你是來這幫忙的嗎？在遭受洪荒使者的攻擊後，我們飼養的阿戈利羊都散落在松林裡。牠們的羊毛和羊奶對於營地的正常運作不可或缺。\n\n請帶著這個哨子，它能夠指揮小願把阿戈利羊趕回來。如果屠夫桑朵需要額外的鼓勵，她可以吃她最愛的零食。", progress = nil, completion = "我們的阿戈利羊還活著。幫我多拍拍小願，好嗎？我想親自去找牠，但我動不了。&lt;瓦杜嘆了口氣。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66681] = {title = "暴風四起", objective = "到睿冠松林殺死8隻風觸野獸。", description = "要是你到外面的松林去，請殺掉所有被風暴影響的動物。這是個不情之請，但牠們顯然非常痛苦，完全無法得救，只能成為散播狂暴的溫床。\n\n我懷疑這是洪荒使者搞的鬼，源頭一定是他們附近的據點，我曾看到他們在奇怪的祭壇上舉行儀式。\n\n我要再去調查一下。要是你回來的時候，我還沒回來，斥候瓦杜可以向你進行其他任務的簡報。我們現在急需幫手。", progress = nil, completion = "松林現在應該比較安全了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66683] = {title = "最後手段分析", objective = "到松木崗哨詢問有關風觸裂片的事。", description = "<瓦杜閉上眼睛，雙手抱胸，嘴裡唸唸有詞。>\n\n我被鹿刺傷了，真是不意外。現在變成我只是一個需要照顧的人。我弟弟會受到讚揚感謝，家鄉的族人沒人會感到驚訝。\n\n<瓦杜抬頭一看。> 什麼？你拿著的那個是什麼？發光的石頭？我拿一個研究一下，但最好問問其他人。畢竟我是獵人，不是考古學家。<瓦杜哼了一聲，盯著他的腳。> 也許這是叫我轉職的預兆。去吧，你已經證明自己比我還有用。", progress = nil, completion = "&lt;瓦杜震驚地盯著他的腿，上頭插著裂片，傷口處鮮血直流。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66684] = {title = "追逐風暴", objective = "消滅洪荒使者風暴魔法的源頭。", description = "<瓦杜拔出裂片，不斷喘氣。>\n\n我…完全失控了。歐雷克是對的，這個可怕的魔法一定是洪荒使者搞的鬼。拜託你，阻止他們！\n\n我必須把我的兄弟送回營地。", progress = nil, completion = "你回來了！我從這裡就能感受到源頭的毀滅。", rewards = "您會收到：\n\n噴泉行者束腕刺繡寬蹄腕環角質強化腕甲斷矛者護臂"}
MultiLanguageQuestData['tw'][66687] = {title = "頂級掠食者之地", objective = "收集10張暗紡蛛網、2個蠍尾飛狐爪和2個雷脊鱗片。", description = "你應該聽說過『博學者』睿倫，他給了半人馬在殘酷之地生存的工具。他的記憶需要相對的猛獸祭品才能換取。\n\n小心點，旅人。他們已經不像幾紀元以前那麼危險，但他們依然是平原的至尊掠食者。", progress = "你帶祭品回來了嗎？", completion = "你平安回來了。很好。你永遠得對動物的力量保持敬佩。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66688] = {title = "風之痕", objective = "收集風之象徵，並把它們帶到歌唱石附近的祭品容器去。", description = "當世界真正的洪荒生物，也就是元素向半人馬發出挑戰時，希米亞用我們被賜予的禮物迎戰它們。風。\n\n歌唱石在平原上堅毅地豎立著。你在那裡可以獻上風之象徵來喚起她的記憶。這樣的象徵在我們周圍都可以找到…鳥的羽毛、植物孢子、或是河川蘆葦。", progress = nil, completion = "&lt;鐵器裡面有灰燼殘骸，是前人供奉的風之象徵。&gt;\n\n&lt;你把你收集的物品擺上去。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66689] = {title = "不只是石頭", objective = "向瓦杜出示風觸裂片。", description = "<裂片極為光滑，摸起來溫溫的。裂片核心中有閃電火花。>\n\n<或許瓦杜或歐雷克會知道更多內情。>\n\n<想到要將裂片交出時，你突然有股衝動，想將裂片牢牢握在手中，永不分離。>", progress = nil, completion = "&lt;瓦杜沒留意到你來了。他依然坐著，盡量不對受傷的腿施壓，並閉上了眼睛。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66690] = {title = "諾庫德進攻據點：最後的先祖", objective = "在諾庫德進攻據點擊敗巴拉卡可汗，並收集先祖勳章。", description = "你已經證明自己是我們的盟友，對我們的價值觀和生活方式有由衷的興趣。我想要告訴你的還有一個祖先，但這會很危險。\n\n去殺死巴拉卡的族長，叛變的巴拉卡，那個該死的雜種。他一直都會戴著一個珍貴的勳章。把它帶回來給我，我就會永遠欠你這個人情。", progress = "巴拉卡一向墜飾不離身。你得把他殺了。", completion = "…我以為我無法見證這一天的到來。", rewards = "您能選擇下列奬勵中的一個：\n\n先祖勳章\n\n您還會收到：\n\n"}
