MultiLanguageQuestData['tw'][66879] = {title = "角行鳥浩劫", objective = "到滿溢急流與妲薩克蘿思會面。", description = "角行鳥。牠們的鳥嘴可啄斷骨頭，一雙長腳可以讓牠們遠離危險，而且幾乎什麼都吃。\n\n這份工作簡單無比！只有我和我最愛的大鳥一起共度無數時光。要是發生什麼事，我知道如何對付島上的所有小動物。\n\n你願意跟我去一趟北邊的角行鳥高原嗎？我不介意多點人手來幫忙。", progress = nil, completion = "我看了很多關於角行鳥的書，我還曾跟有始以來最大的雷霆蜥蜴寶寶搏鬥過…但我對於水元素根本一無所知！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66880] = {title = "峽谷河川賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66881] = {title = "峽谷河川賽道 - 進階", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66884] = {title = "防火裝備", objective = "從巨龍群島的加拉登身上收集10件防火裝備，交給伊斯凱拉巨牙海民的天納宇。", description = "加拉登的護甲能夠抵抗熊熊烈火，了解這些裝備使用的材質和附魔可以有效幫助我們對抗他們！\n\n想辦法從加拉登身上收集一些樣品回來。讓我們可以好好研究，在自己的裝備上套用同樣的附魔效果。", progress = "你拿到他們的護甲了嗎？", completion = "這些研究樣品十分完美！我們很快就能應用到我們的裝備上。\n\n朋友，非常感謝你。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][66885] = {title = "翡翠花園爬升賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66886] = {title = "翡翠花園爬升賽道 - 進階", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66890] = {title = "遭竊的工具", objective = "為了沃卓肯協調者的多瑟諾斯，從巨龍群島的豺狼人身上收集20個遭竊的工具。", description = "豺狼人老是打劫我們的補給商隊，讓我們飽受困擾。他們似乎特別中意商隊運送的各種工程學用品。要是讓這些凶狠的強盜學會我們的專業技術，會有很大的風險，而且這些小偷也讓我們的生產進度大幅落後。\n\n要是我們可以拿回一些被搶走的工程學零件，應該就能重新趕上進度。", progress = "你取回遭竊的工具了嗎？", completion = "有了這些零件，我們的工程學專案應該回到正軌了。", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][66891] = {title = "爆炸粉塵", objective = "從巨龍群島的鳳凰身上收集20份爆炸粉塵，交給龍鱗遠征隊的諾克林‧異圈。", description = "巨龍群島的熔火鳳凰在死去時，會創造出一種不尋常的灰燼物質。那可以用來改良材料，做出複雜、革命性的機械。不過我大概會用它來做炸藥。", progress = "你收集到足夠的粉塵了嗎？", completion = "這種灰燼是製作許多不同種機器的必要原料，能夠改善艾澤拉斯各地人民的生活。不過我是在瞎扯淡什麼？我們當然是用來做炸藥啦，轟隆！", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][66892] = {title = "洪水困境", objective = "在滿溢急流殺死12個水元素。", description = "元素生物在殺害角行鳥！我練習過如何跟大型動物搏鬥，但我從沒想到需要跟元素生物正面對決！這些傢伙可不是雷霆蜥蜴寶寶…\n\n<妲薩克蘿思傷心地嘆氣。>\n\n請解決一些元素生物。角行鳥比我們想的還要更有靈性。如果牠們有辦法，一定會反擊的！", progress = nil, completion = "我以為我看到事情的全貌。你可以調查一下這些小傢伙怎麼從泉水跑出來的嗎？\n\n事實證明，擔任管理員並不是一件簡單的事。謝謝你的幫忙，&lt;name&gt;。我從你身上學到很多！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66893] = {title = "奪還行動", objective = "在滿溢急流治療8隻受傷的角行鳥。", description = "我或許對水元素一無所知，但我可是非常了解角行鳥！\n\n我調配了一種藥膏，應該可以讓角行鳥保持健康，隨時都能進行戰鬥。我先前從沒機會將藥膏實際用在角行鳥身上，但我已經盡量做了所有研究。\n\n該勇敢面對現實，實際用用看了！", progress = nil, completion = "能看到角行鳥奪回自己的家，實在太令人振奮了。這都是你的功勞，&lt;name&gt;。謝謝你的幫忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66894] = {title = "和老首領一樣", objective = "除掉紅炎艾滋爾。", description = "碎界龍人太容易被蒙騙了。這麼多年來，我們追隨了許多不同的首領，每次都相信他們會帶我們迎來暮光之時，見證死亡之翼的回歸。\n\n不過，死亡之翼從未回歸，連暮光的蹤影也見不著。\n\n該換個新首領了，你或許可以幫忙帶來改變。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n熔火微粒巨龍群島補給品"}
MultiLanguageQuestData['tw'][66896] = {title = "一網打盡", objective = "收集10隻暖水河魚和6份多汁的蟹肉。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66897] = {title = "熔爐燃料", objective = "從巨龍群島的熔岩生物身上收集10個岩漿之核，交給莫魯克半人馬的杜瑞娥。", description = "要做出最好的刀刃，你需要只有岩漿之核才能提供的高溫。我們隨時都會常備幾個來當作熔爐的燃料來源。最近核心的數量有點少，需要補充一下。\n\n巨龍群島的大多數熔岩生物身上都會有岩漿之核。", progress = "你收集到岩漿之核了嗎？", completion = "現在熔爐不怕沒東西燒了，鐵匠一定會很高興。", rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][66899] = {title = "絨毛腳", objective = "從巨龍群島的狼蛛身上收集20個絨毛腳，交給龍鱗遠征隊的諾克林‧異圈。", description = "我們收到一個要求，需要裁縫用的「絨毛腳」…\n\n你盯著我也沒用，提出要求的不是我，我只負責傳達而已。我認為狼蛛的腳可以滿足這個要求。", progress = "你收集到絨毛腳了嗎？", completion = "我無法想像這些東西的用途，我也不是很願意去想像，但還是謝謝你。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][66900] = {title = "魔力聖物", objective = "從巨龍群島的豺狼人身上收集10個魔力聖物，交給伊斯凱拉巨牙海民的天納宇。", description = "啊，你來得正是時候！豺狼人從我們這裡偷走了貴重的寶物，而且不是尋常的物件，它們都是附有魔法的！絕不能讓豺狼人學會我們的魔法！\n\n像你這樣有本事的人應該能一眼認出那些失竊的聖物。你是否願意幫幫我們呢？", progress = "你取回聖物了嗎？", completion = "要是那批聖物一直在豺狼人手中，不知道他們會不會破解聖物的秘密。\n\n謝謝你幫忙取回聖物。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][66901] = {title = "顛覆世界", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66902] = {title = "蜜蜂快滾", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66903] = {title = "淨空密庫", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66921] = {title = "莫魯凱衝刺賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66929] = {title = "一定要收集全部", objective = "取回尤瑪多姆的套卡。", description = "$PC，你介意幫我取回我的卡片嗎？\n\n我跟賽托苟莎說，我需要它們才能向其他學生示範《爐石戰記》的玩法。我想要成立一個社團，可是她不願意把卡牌還我！\n\n她一直不太尊重我，但這次實在太過分了。", progress = "我自己取出了一些卡片，你拿到剩下的卡片了嗎？", completion = "感謝守護巨龍！絕大部分都還完好無缺。\n\n我應該能用青銅魔法倒轉卡片的時間，讓它們回到最佳狀態！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66931] = {title = "是誰帶來的騷動？", objective = "到晶紅生命聖殿查明騷動的原因。", description = "這次震動並不尋常。", progress = nil, completion = "我…\n\n我無比希望能追隨龍后而戰，但我必須證明我能贏得她的信任，守護好生命聖殿。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66933] = {title = "空之鏡衝刺賽道道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66934] = {title = "破壞破龍者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66935] = {title = "水晶毛刺筆", objective = "從巨龍群島的晶脊豪豬身上收集15根水晶毛刺，交給龍鱗遠征隊的諾克林‧異圈。", description = "這些群島棲息著名為晶脊豪豬的獨特生物。牠們是很可愛的生物，不過身上卻有尖銳的水晶毛刺保護。\n\n有個研究員被刺弄傷，我替他治療的時候，發現上面殘留著一股力量，這些刺非常適合用來做成毛刺筆。", progress = "你找到水晶毛刺了嗎？", completion = "這些是魔力共鳴水晶的完美來源。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][66937] = {title = "腐朽情報", objective = "從巨龍群島的腐朽豺狼人身上收集10個腐朽樣本，交給沃卓肯的多瑟諾斯。", description = "豺狼人和他們濫用腐朽魔法的事情越來越讓人擔憂。我們得盡可能研究相關知識，防患於未然。\n\n我們鍊金師都有安全處理這類有害成分的經驗…況且，我們已經習慣這種氣味了。你願意助我們一臂之力嗎？", progress = "你收集到腐朽樣本了嗎？", completion = "我們會研究這些樣本，看看能不能利用鍊金術找出辦法，解決這個不斷惡化的問題。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][66938] = {title = "猛瑪象骨髓", objective = "從巨龍群島的猛瑪象身上收集20份象牙骨髓，交給莫魯克半人馬的杜瑞娥。", description = "我們的專長之一，是釀造前所未有、味道獨特的酒。雖然我們樂於嘗試各種新奇有趣的原料，不過一些常見原料也是不可少的。\n\n其中一種就是猛瑪象長牙中的骨髓。我們的骨髓不太夠了，要是你能幫我們的鍊金師收集一些，我會非常感激。", progress = "你收集到足夠的象牙骨髓了嗎？", completion = "莫魯克氏族的鍊金師一定會很高興。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][66939] = {title = "追捕狩獵大師", objective = "到伊姆布之盾附近獵殺狩獵大師克萊寇。", description = "我從荒僻營地的一個守衛那裡聽說，有個該死的敗類正在殘殺當地的動物。它自稱「狩獵大師」。\n\n狩獵是一回事，但我無法容忍蓄意虐待生物這種事。\n\n再說，我的貨車也需要一個幸運符。\n\n<奈辛瓦里朝一旁吐口水。>\n\n幫我把它的腳爪帶回來。", progress = "狩獵進行得如何？", completion = "啊，看來你成功了。\n\n很好。\n\n希望這附近的小動物更容易睡個好覺。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66940] = {title = "藥劑實驗", objective = "從巨龍群島的戈洛克身上收集15份戈洛克黏液，交給莫魯克半人馬的杜瑞娥。", description = "我們的鍊金師最近打算用各種新原料進行實驗。他們最近愛用的東西…該怎麼說…算是有趣吧。\n\n戈洛克的黏液似乎具備一些成分，可以在特定藥劑中發揮正面效果。", progress = "你收集到戈洛克的黏液了嗎？", completion = "好極了。現在我們可以期待鍊金師能用這東西做出什麼好用的藥劑。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][66941] = {title = "超大型工具", objective = "從巨龍群島的加拉登身上收集10件大型工具，交給莫魯克半人馬的杜瑞娥。", description = "加拉登擁有一些巨大無比的工具和武器。我們可以輕易找到這類工具的用途，就算是把它們熔掉再製造成我們需要的工具也好。\n\n請帶回一些加拉登的工具，供我們研究和使用。", progress = "你找到加拉登，並收集到他們的工具了嗎？", completion = "鐵匠一定會找時間利用它們。謝謝你幫忙收集這些工具。", rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][66942] = {title = "以牙還牙", objective = "從巨龍群島的洪荒使者身上收集10張洪荒儀式圖，交給龍鱗遠征隊的諾克林‧異圈。", description = "這可能會有點爭議，但我相信我們可以研究洪荒使者的儀式，來學習引導元素力量的新方法。一旦我們了解他們的魔法步驟，我有信心我們可以用它來創造各式各樣創新的工程產物。", progress = "你找到洪荒儀式圖了嗎？", completion = "我聽說洪荒使者排斥文明，並想要帶它走向毀滅。哈！他們自己害自己。他們的儀式會啟發各式各樣的新發明，進而帶來下一個科技的黃金年代。", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][66943] = {title = "書寫用紙", objective = "從巨龍群島的腐朽樹人身上收集15張樹皮紙，交給沃卓肯協調者的多瑟諾斯。", description = "我們在巨龍群島進行的研究揭曉了許多意料之外的知識。舉例來說，如果樹人遭到腐朽魔法侵蝕，他們身上的樹皮竟然會變得和羊皮紙相當類似。\n\n而且這種奇特的紙材還可以承受更強大的魔法銘文，十分有用！你可以幫我去多收集一些嗎？", progress = "你取得樹皮了嗎？", completion = "很奇怪的是，樹皮感覺像是精緻的羊皮。不過，拿著未處理的紙會為我的頭腦帶來黑暗的想法。這個量目前就夠了。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][66944] = {title = "孔雀顏料", objective = "從巨龍群島的孔雀身上收集8根孔雀羽毛，交給龍鱗遠征隊的諾克林‧異圈。", description = "巨龍群島上的孔雀擁有一身繽紛的羽毛！我敢說我們一定可以用那些羽毛製作顏料，讓雕銘師調成墨水。", progress = "你收集到孔雀羽毛了嗎？", completion = "顏色好鮮豔！我們會用這些羽毛做出非常棒的顏料。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][66945] = {title = "冰寒墨水", objective = "從巨龍群島的冰蜘蛛和冰熊身上收集20份冰凍排泄物，交給沃卓肯協調者的多瑟諾斯。", description = "寒帶生態圈的生物會排泄極為罕見的神秘液體。那種液體性質獨特，可以製成完美的墨水黏合劑。我是左撇子，所以，光是想到我可以不抹髒我的紙就讓我感到很興奮。", progress = "你收集到冰凍排泄物了嗎？", completion = "辛苦你了。這些材料可以用來製作很好的墨水。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][66946] = {title = "蒼藍高地奔馳賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66948] = {title = "特使抵達", objective = "在翡翠花園了解情況。", description = "我要承認我這輩子沒有離開過翡翠花園，因此從來沒遇過半人馬，更不用說大陸來的凡人了。\n\n不過，我來這裡不只是為了拜訪，而是要請求半人馬的援助，一同守護我們的誓言石並保護我們的信念。\n\n很高興看到你也來這裡幫忙。有許多事情需要討論。", progress = nil, completion = "我們永遠歡迎更多盟友。", rewards = "諾庫德劫奪者胸鎧席卡斥候鍊衫蹄萊看守者外衣您會收到：\n\n"}
MultiLanguageQuestData['tw'][66949] = {title = "飾品強盜", objective = "從巨龍群島的豺狼人身上收集10個失竊的飾品，交給伊斯凱拉巨牙海民的天納宇。", description = "豺狼人有很多不同的飾品。巨牙海民飾品。他們要不是從我們的村莊偷的，就是從和他們對戰時死去的英勇巨牙海民身上偷的，那樣更糟。這些飾品是我們的文物，應該屬於我們。\n\n如果你把它們帶回來給我，我會把製作這些飾品會用到的技術傳授給你。", progress = "你從豺狼人那邊拿回失竊的飾品了嗎？", completion = "我認得這些飾品。我記得它們原本的主人。謝謝你把它們找回來。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][66950] = {title = "巨人之心", objective = "從巨龍群島的山嶺巨人、冰巨人或熔火巨人身上收集5個巨人核心，交給伊斯凱拉巨牙海民的天納宇。", description = "巨龍群島上有許多不同的巨人，據說他們的核心都裝有美麗的寶石。一般來說，我們不會狩獵島上的生物來取得寶藏，可是這些巨人已經造成了不少混亂。\n\n在清除這些搞破壞的巨人時，我們不如就順便收集這些寶石吧。", progress = "你在巨人身體裡有找到任何寶石嗎？", completion = "這些確實是美麗的寶藏。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][66951] = {title = "物種數量控制", objective = "從巨龍群島的岩牙獸及麋牛身上收集25個獸皮，交給伊斯凱拉巨牙海民的天納宇。", description = "最近，巨龍群島有幾個物種有繁殖過剩的問題。具體來說，是岩牙及麋牛。\n\n當然，我們可不想浪費。記得從那些生物身上收集皮革，越多越好。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][66952] = {title = "豺狼人的衣服", objective = "從巨龍群島的豺狼人身上收集20匹豺狼人身上的布料，交給沃卓肯協調者的多瑟諾斯。", description = "豺狼人一直以來都是個威脅，會對遠征隊及巨龍群島的居民發動血腥的劫掠和攻擊。那為什麼他們的衣服那麼乾淨呢？\n\n在你和這些劫掠者作戰後，可以請你收集他們用舊的布料樣本給我分析嗎？", progress = "你帶回豺狼人身上的布料了嗎？", completion = "感謝你的樣本。粗略地看起來，這似乎只是他們從巨牙海民那偷來的荒紋布，不過我會請我們的裁縫仔細檢視縫線來確定。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][66953] = {title = "毛茸之物", objective = "從巨龍群島的阿戈利羊身上收集20個蓬鬆毛皮，交給沃卓肯的多瑟諾斯。", description = "裁縫師永遠都想要取得一些毛茸茸的阿戈利羊毛。這種羊毛特別好用，能讓人應付巨龍群島凍死人的山區氣候。", progress = "你拿到蓬鬆毛皮了嗎？", completion = "真是毛茸茸！很好，這樣就行了。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][66956] = {title = "獵龍者伊格丹", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66957] = {title = "冰中暗影", objective = "調查安東尼達斯營地上方的冰河頂端。", description = "在我穿越安東尼達斯營地的時候，我聽到有人在說悄悄話。他們提到冰原上到處都是動物的屍塊，還有一灘灘的血跡。\n\n不管那是什麼，都讓那些法師害怕，讓當地的動物幾乎死絕。\n\n到冰河頂端調查一下。如果我是愛賭博的矮人，我會猜那一定是某個至尊掠食者的地盤。\n\n幫我帶個一部份回來，這樣才能給祈倫托一個交待。", progress = "小心一點。不管這東西是什麼，它都很強大，而且殘忍無比。", completion = "一個冰巨人？麥格尼的銅鬚啊…你居然人還好好的！真厲害。\n\n我會讓祈倫托看看這個。說不定他們就不會再來煩我！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66958] = {title = "保護與放牧", objective = "到伊斯凱拉東邊獵殺血角。", description = "我前幾天跟伊斯凱拉的一些獵人聊天，聽說他們遇到一件非常可怕的事。\n\n顯然，那裡有一隻叫血角的嗜殺犀牛一直用犀角攻擊體型較小的麋牛。\n\n麋牛在蒼藍高地的競爭已經很激烈了，不需要再有外來的野獸殺死牠們！\n\n帶牠的角來給我。我想讓巨牙海民的朋友有個好印象！", progress = "記住，要小心牠的蹄！犀牛就是用蹄攻擊你的。", completion = "做得非常好，&lt;name&gt;！這對安撫當地的麋牛很有幫助，希望也能讓我們的巨牙海民鄰居知道，我們同樣對大自然充滿敬意！\n\n我們可以藉由血角學到一件事。我們踏上這片美麗的土地，不代表我們有權任意作亂！\n\n在你離開時，世界應該要變得比你到來時更好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66959] = {title = "參觀貿易站", objective = "從收藏箱領取商人的標幣，並參觀貿易站。", description = "<一張傳單被風吹來，飄到你手上。>\n\n來自艾澤拉斯各個角落的罕見古董！滿足不同需求的優質商品！\n\n朋友，你在其他地方絕對看不到這些奇珍異寶。\n\n奧格瑪和多恩諾加都有我們的店面，歡迎你前來大開眼界！\n\n--贊希莉貿易站\n\n<你眯起眼睛閱讀上面的小字。>\n\n記得出示這張傳單，就能額外換取商人的標幣！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n商人的標幣"}
MultiLanguageQuestData['tw'][66960] = {title = "『卓越者』柯羅吉克", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66963] = {title = "未到貨", objective = "到附近的基地告訴編目員沃福德，他的補給品短時間內不會送達。", description = "我曾試著告訴維維西，我能把貨車從泥坑拉出來。\n\n但他不聽，堅持要用魔法解決…結果呢，看看他做的好事。\n\n<搬運工班妮特嘆氣。>\n\n在我試著說服維維西的時候，你能不能跑到山丘上的基地，告訴編目員沃福德，他可能需要再從波拉勒斯送一箱相機備品過來？", progress = nil, completion = "&lt;編目員沃福德笑了笑。&gt;\n\n不是什麼大問題。我在行李裡放了不少備用膠捲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66964] = {title = "落入惡徒之手的神器", objective = "到蒼藍高地的失落廢墟找到雅莉亞‧日翔。", description = "我們在這裡遇到很多…不對，是根本數不清的問題！\n\n天啊，要先從哪件事說起呢？\n\n祈倫托最近發現碎裂火焰軍的秘密計畫。他們正在尋找名為「瓦烏洛斯」的神器。\n\n它具有無窮的力量，甚至擁有…自己的意識！危險程度簡直破表。\n\n有個叫雅莉亞‧日翔的人，帶著兩個巨牙海民去南邊調查碎裂火焰軍。她現在早該回來了才對。\n\n麻煩你去尋找她的下落，並且阻止碎裂火焰軍取得這個神器！", progress = nil, completion = "幸運之神總算眷顧我們了！我們這裡急需幫手。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66968] = {title = "削弱雪人族群", objective = "到羅甯之盾附近殺死葉托。", description = "<奈辛瓦里指向道路的一側。>\n\n看到雪中的那些痕跡了嗎？\n\n雪人的足跡。\n\n一定有什麼東西激怒他們，才會讓他們在這麼靠近大路的地方打獵。看看你能不能殺死他們的首領，我們不希望他們開始伏擊來往的旅人！\n\n如果他性情殘暴，直接把他的頭砍下來。這樣應該能嚇阻其他雪人。", progress = "小心點，朋友。雪人狩獵時，會成群結隊。", completion = "哦哇！說到窮凶惡極…很高興你活著回來了！\n\n雖然不太人道，但是讓雪人遠離道路，對他們最好。\n\n對我們也是。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66969] = {title = "平原氏族", objective = "在莫魯克向桑索克可汗回報。", description = "在你等待特使到來時，桑索克可汗很有興趣知道和氏族的會面進行得如何。她派我來找你，通知你到莫魯凱的中央和她會面並討論。", progress = nil, completion = "&lt;桑索克可汗嘆了口氣，歐奇爾隨即為可汗發聲。&gt;\n\n雖然有大大小小的氏族散居在平原各處，不過其中地位最高分別是席卡、蹄萊、雍伊爾和諾庫德。", rewards = "您能選擇下列奬勵中的一個：\n\n諾庫德頸飾席卡頸鍊蹄萊墜盒雍伊爾墜飾\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][66970] = {title = "『升空者』邰峰", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66971] = {title = "死亡之顏", objective = "到冬毛谷的北邊獵殺霜顎。", description = "告訴我，朋友。你看過死神的真面目嗎？\n\n<奈辛瓦里停了一下，製造戲劇效果。>\n\n我在說什麼鬼話？你一定有這種經歷。\n\n畢竟，死神有很多面目。\n\n我從伊姆布的巨牙海民那裡聽到一個故事，據說死神的其中一個面目就住在這裡的山中。光是提到牠的名字，就會召來冰冷殘酷的死神。\n\n霜顎。\n\n<奈辛瓦里小心翼翼地四處張望。>\n\n好了，現在你必須去狩獵牠了，就算是幫我一個忙！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66972] = {title = "老石牙", objective = "到安東尼達斯營地附近擊殺老石牙。", description = "我有個艱難的任務要交給你，$p。每次殺戮並非都是考驗技術，有些是在考驗良心。\n\n在安東尼達斯營地東邊的森林中，有隻年老的公猛瑪象。我前幾天從遠處觀察牠，不斷聽到牠發出悲傷的鳴叫聲。牠顯然飽受痛苦。\n\n牠開始胡亂破壞下層灌木叢，我擔心牠對其他生物帶來危險。\n\n如果你能讓那個可憐的傢伙安息，也算是好事一樁。幫我把牠的象牙帶回來，我們會給牠應有的哀榮。", progress = "搞定了嗎？", completion = "這不是什麼讓人開心的事。\n\n不過我會把他的牙齒掛在紀念勇士的地方。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66989] = {title = "成果豐碩", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][66997] = {title = "育幼指導", objective = "在晶紅生命之池的花園與威洛斯會面。", description = "看到拉茲塔克接受了幼龍看管者的使命，我覺得相當欣慰！尤其現在有很多小寶貝都開始長牙了。\n\n話說回來，育幼花園的確正在面臨挑戰。不只幼龍覺得壓力很大，看管者更是面臨前所未有的壓力。\n\n求求你，要是你有空的話，請來下面的花園找我。我們需要你的幫忙！", progress = nil, completion = "謝天謝地，你來了！相信你也注意到蜜蜂到處飛來飛去。為此，我們必須做點什麼！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][66998] = {title = "水火不容", objective = "在噴發洞穴殺死熔岩元素。", description = "我看管熔岩元素這麼多年來，從沒看過他們出現這樣的行為！我們幾乎沒辦法把他們困在洞裡。\n\n你現在有空嗎？我們負責守住出口，你負責進去裡面削減他們的數量。\n\n來，帶著這個瓶裝水元素。\n\n我在看管熔岩元素的時候，隨身都會帶著幾個瓶裝水元素。天生的死敵最能吸引他們的注意力！", progress = nil, completion = "謝謝你讓我們能休息片刻。管理員的工作永遠沒有結束的一天。", rewards = "您會收到：\n\n"}
