MultiLanguageQuestData['tw'][70025] = {title = "工匠補給品：龍金鐮刀", objective = "將龍金鐮刀交給晶紅生命聖殿的赫菲思塔。", description = "你看起來遊手好閒，要不要打工啊？\n\n我有工匠聯盟的訂單需要完成，訂單內容是製作龍金鐮刀。雖然我自己動手很快就能完工，但你身為學徒，我想應該給你一點表現的機會。\n\n製作鐮刀，完成後把它送去晶紅生命聖殿，名叫赫菲思塔的德萊尼會付錢給你。", progress = "工匠聯盟今天能幫你什麼忙？", completion = "送貨到府！非常好。很高興與你做生意，&lt;name&gt;。", rewards = "您會收到：\n\n龍金礦石"}
MultiLanguageQuestData['tw'][70026] = {title = "工匠補給品：熔岩甲蟲", objective = "將5隻熔岩甲蟲交給晶紅生命聖殿的赫菲思塔。", description = "草藥師，你在找工作嗎？工匠聯盟請我幫他們的客人收集一些甲蟲。\n\n這片土地非常豐饒，但我不太可能他們一要求，就要幫他們跑腿。\n\n不過，要是你有事出去，說不定可以順路收集一些甲蟲？", progress = "工匠聯盟今天能幫你什麼忙？", completion = "送貨到府！非常好。很高興與你做生意，&lt;name&gt;。", rewards = "您會收到：\n\n荷芡花"}
MultiLanguageQuestData['tw'][70027] = {title = "工匠補給品：勘測員布甲手環", objective = "將勘測員布甲手環交給晶紅生命聖殿的赫菲思塔。", description = "裁縫師，你在找工作嗎？工匠聯盟請我幫他們的客人製作一對腕環。\n\n儘管我很感激這些探險者正試著為紡織事業做出貢獻，但我真的沒時間應付這類要求。\n\n也許你有興趣接手這份工作？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n荒紋布"}
MultiLanguageQuestData['tw'][70028] = {title = "工匠補給品：鹽礦", objective = "將5個鹽礦交給晶紅生命聖殿的赫菲思塔。", description = "礦工，你在找工作嗎？\n\n我跟赫菲思塔聊過，她說工匠聯盟正在幫客人收集鹽。\n\n算了，我自己來，還是不了，我懶得動。\n\n兄弟，你去幫他們採鹽，好嗎？", progress = "工匠聯盟今天能幫你什麼忙？", completion = "送貨到府！非常好。很高興與你做生意，&lt;name&gt;。", rewards = "您會收到：\n\n賽若拜岩礦石"}
MultiLanguageQuestData['tw'][70029] = {title = "工匠補給品：符文賽若拜岩節杖", objective = "將2個符文賽若拜岩節杖交給晶紅生命聖殿的赫菲思塔。", description = "你似乎有魔法天分，附魔師。你可以協助我完成一個訂單嗎？\n\n工匠聯盟為一個客人訂購了幾根用賽若拜岩做的節杖，不過附魔棒不太算是我的專長。\n\n如果你願意的話，晶紅生命聖殿的赫菲思塔會為你的時間和勞力提供報酬的！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n炫彩之塵"}
MultiLanguageQuestData['tw'][70030] = {title = "工匠補給品：品質保證的光學鏡", objective = "將一組品質保證的光學鏡交給晶紅生命聖殿的赫菲思塔", description = "啊，有個工程師！來得正好。\n\n我有些結構圖需要修正，不過有個高個子的女士過來訂了一組光學鏡。\n\n你知道怎麼做光學鏡，對吧？\n\n做好之後，把光學鏡送去晶紅生命聖殿，我記得她說過自己是工匠聯盟的人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍金礦石"}
MultiLanguageQuestData['tw'][70031] = {title = "工匠補給品：廚師的光滑桿麵棍", objective = "將廚師的光滑桿麵棍交給晶紅生命聖殿的赫菲思塔。", description = "雕銘師，你在找工作嗎？\n\n有家叫做工匠聯盟的公司發了訂單給我。\n\n工作內容似乎相當簡單，像你這樣的學徒都能應付。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n攀纏樹皮"}
MultiLanguageQuestData['tw'][70032] = {title = "工匠補給品：珠寶匠眼鏡", objective = "將裂紋黑瑪瑙放大鏡交給晶紅生命聖殿的赫菲思塔。", description = "珠寶設計師，你在找工作嗎？工匠聯盟請我幫他們的客人製作一副眼鏡。\n\n我欸！以為我時間很多嗎！\n\n你會做眼鏡，對吧？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n永恆琥珀鮮豔翡翠"}
MultiLanguageQuestData['tw'][70033] = {title = "工匠補給品：先鋒皮甲長靴", objective = "將先鋒皮甲長靴交給晶紅生命聖殿的赫菲思塔。", description = "製皮師，你在找工作嗎？工匠聯盟請我幫他們的客人製作一些長靴。\n\n很明顯，他們不明白我多受歡迎。你知道今天有多少探險者跑來抱怨他們的鞋子破洞嗎？\n\n拿去，要是你有時間的話，這是量好的尺寸。說不定這個工匠聯盟是你一展長才的舞台。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n閃鱗皮濃密毛皮"}
MultiLanguageQuestData['tw'][70034] = {title = "工匠補給品：薩曼瑟螈鱗片", objective = "將3枚薩曼瑟螈鱗片交給晶紅生命聖殿的赫菲思塔。", description = "剝皮師，你在找工作嗎？工匠聯盟請我幫他們的客人收集薩曼瑟螈的鱗片。\n\n我是個工匠，才不是他們的跑腿仔！\n\n不過…啊，你或許能找到一些鱗片？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n閃鱗皮濃密毛皮"}
