MultiLanguageQuestData['tw'][70154] = {title = "某處的傳送門", objective = "跟隨躍傳法師德蘭卓拉到傳送門的位置。", description = "附魔會保護我們不受裡面不穩定的能量影響。\n\n我會開啟通往最近的石頭的道路。\n\n在你通過之後，要跟緊我。抵達後，啟動裝置時我會需要你的協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70155] = {title = "看、聽和呼吸", objective = "和斯雷施瑞一起釣魚。", description = "你好，<race>。很少人會來打招呼，更不用說待上一會了。大部分人都忙著前往下一個目的地。\n\n你想要跟我一起釣魚嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70156] = {title = "古老的覺醒", objective = "為傳送門提供能量。", description = "傳送門就坐落在我身後。誰都說不準這容器上漸漸削弱的魔法何時會退去，或發生更糟的情況：破裂。\n\n那麼大量的不穩定能量被釋放會是場災難。\n\n我們繼續吧？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n遠古傳送門\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][70157] = {title = "花園遊覽賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70158] = {title = "花園遊覽賽道 - 進階", objective = "滑行通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70159] = {title = "家的滋味", objective = "在龍鱗基地到處問問部落成員，看他們能不能借你所需的原料。", description = "啊，終於！又一個可以出手幫忙的半龍人。\n\n我跟我兄弟想要煮一點糧食吃，可是…\n\n<斯卡勒許比了比周遭。>\n\n這裡的一切都好不一樣。很難找到我們以前煮飯會用的同種材料。\n\n但我們可以隨機應變。去問部落有什麼可以讓我們用來代替蔬菜、蛋白質還有乳化液。這樣我們就可以煮一餐了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70160] = {title = "煉金論文答辯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
