MultiLanguageQuestData['tw'][70164] = {title = "新手運", objective = "在生命寶庫遺跡和時間術師弗希卓及希伯莉‧拍頁說話。", description = "$p，你有空嗎，我快要有突破性進展了！\n\n在育所崩塌之後，我失去的不只是我的戰鬥能力。我也失去了身為半龍人的認同。或許你可以明白。\n\n我喜歡拼湊和拆解東西，所以我加入了遠征隊。可是這個東西讓我遇到麻煩了。\n\n你可以請弗希卓和希伯莉看一下我的筆記嗎？我想要證明我是個有能力的工匠…向他們還有我自己證明。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70166] = {title = "繪畫之樂", objective = "將勞羅斯的自薦畫作交給哈德森。\n\n已提供物品：\n", description = "你喜歡我的收藏嗎？這些都是哈德森的作品，他是史上最出色的畫家。\n\n它們很稀有，而且八成很值錢。他是名隱士，而且好一陣子沒有畫畫了。噢，但我很想認識他…或者是跟他學畫畫！\n\n你…似乎膽子很大。你願意幫我去找他嗎？來！順便帶上我的幾幅作品。或許能讓他眼睛一亮！\n\n或是讓他覺得我很爛…噢天啊。", progress = nil, completion = "這是什麼？一幅畫？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70168] = {title = "悲傷的意外插曲", objective = "從晶紅生命之池、諾庫德進攻據點及蕨皮谷等地城的最後首領身上，取回哈德森遺失的畫作。", description = "你大老遠跑來，我很抱歉…\n\n我親愛的哈德森以前很喜歡畫畫。畫畫曾是他的生命！不知道他遇上了什麼瓶頸。\n\n幾週前，他外出畫畫，在回來的路上，他一怒之下，把所有還沒完成的畫作全丟了。\n\n求求你，旅人，如果你不介意…你能找回那些畫作嗎？它們或許能再次點燃他需要的靈感。\n\n哈德森總是喜歡深入險境，尋找最美的風景。希望你做好萬全準備。", progress = "走開。", completion = "什麼？你做了什麼？！\n\n你為什麼要送垃圾給我？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70169] = {title = "樹也需要朋友", objective = "與勞羅斯交談。", description = "我知道你和蘭恩只是想幫忙。\n\n我不認為這樣會有用，我的靈感…對繪畫的堅定意志…就是消失了。\n\n不過蘭恩是對的，我欠你很大的人情，我會試試看。\n\n帶你的新銳畫家朋友來見我。", progress = nil, completion = "我不敢相信！居然有機會向大師本人學習！\n\n喔，我的天啊，真希望他喜歡我的作品。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70170] = {title = "祛除心中的魔鬼", objective = "從灌注迴廊、阿爾蓋薩學院、蒼藍密庫及奈薩魯斯堡等地城的最後首領身上，取回哈德森遺失的畫作。", description = "可惜他有時候非常頑固。\n\n但我就是無法放著他不管。我們只能再試一次了！\n\n外面還有更多他丟掉的畫作。不過那些畫作都在更加危險的地方，所以我希望你準備好迎接挑戰了！", progress = "接下來該怎麼辦？", completion = "還來？你為什麼非得把這些藝術凶器送到我面前呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70171] = {title = "快樂的意外插曲", objective = "找到哈德森最後的畫作。", description = "<蘭恩皮塔神情失落。>\n\n是因為我嗎？他會沒有靈感，都是因為我嗎？\n\n他說他愛我，但是…你也知道不畫畫對他來說是什麼感覺。\n\n我一直都希望他好。如果這樣他會比較好…那我會離開。\n\n他丟掉的畫作還有最後一幅。在他放棄之前，最後嘗試要畫的東西。\n\n我不能眼睜睜看著它從世上消失。我把它藏在我們家裡。求求你…把那幅畫交給他…就當作是紀念吧。", progress = "真是個奇怪的巨牙海民。怎麼會有人這麼活在自己的世界裡呢？\n\n還是藝術家就是這樣子？我以後也會這樣嗎？噢，天啊。", completion = "對我來說，這一切似乎有點太超過了。我只是想來向大師學習畫畫而已！\n\n不過…這也讓我更深入一點思考藝術對我的意義。\n\n我想…或許我受夠畫畫了。\n\n我要把我的顏料留在這裡…或許做點新的嘗試…", rewards = "您會收到：\n\n畫家的畫架"}
MultiLanguageQuestData['tw'][70172] = {title = "山稜謎團", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70174] = {title = "席卡族", objective = "和桑索克可汗會面。", description = "桑索克可汗是我們氏族最高明的獵人。雖然她聽不到，卻已經一次又一次地證明了自己身為獵人及領袖的能耐。\n\n她是我們所有人的精神導師、受人信任的領袖，也是莫魯克的勇猛保衛者。\n\n能跟她說話是你的光榮。", progress = nil, completion = "&lt;桑索克可汗向你微微點頭。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70175] = {title = "斷掉的飾環", objective = "將東西交給艾蜜莉亞‧貝勒克。\n\n已提供物品：\n", description = "<這可能是艾蜜莉亞‧貝勒克正在找的東西。>", progress = nil, completion = "軟質金屬無法承受元素的力量。\n\n&lt;艾蜜莉亞搖搖頭，同時從你手中拿走指環。&gt;\n\n我會把這枚指環存放在安全的地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70176] = {title = "蛛網受害者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70179] = {title = "一舉兩得", objective = "從當地的土元素身上獲取建築材料。", description = "冒險者，你好！話說，你看起來很有能力，你可以幫我點忙嗎？\n\n阿茲克拉和我負責看守這座塔，我目前稱它處於「翻修前的刺激狀態」。問題是，在我們開始修復時，當地的土元素就攻擊了我們！\n\n於是我想：「哲芙蘭，不如一邊處理土元素一邊收集一些建築材料吧？」這種時候就得靠你了！你可以幫忙嗎？", progress = "說真的，我挺期待可以回到這座高塔工作的，搞不好我會放一面小飾板來紀念你的幫忙！你依然打算幫忙，對吧？", completion = "哎呀，這些比我預期的還要易碎。有人拿這些朝你的頭扔的時候，它們看起來就硬多了！\n\n好吧。不管怎樣，我一定可以把它們用在建築上的，感謝你的幫忙！\n\n或許這附近有一些泥元素可以讓我用來把這黏在一起…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70180] = {title = "迅速啟動？迅速啟動！", objective = "協助葛雷茲為神秘裝置補充能量。", description = "城市裡的一些傢伙主張這個裝置是由傳說中的泰坦看守者提爾創造的。\n\n問題是我們不知道怎麼啟動它！一般的方法我們都試過了：拆解、旋轉還有輕微的電擊。除了觸電沒有任何效果。其實…我想到一個超棒的點子。\n\n看到那裡的旋翼機了嗎？搭上它，我們來看看能不能給這個泰坦東西一點…活力。", progress = nil, completion = "你在尋找什麼力量？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70181] = {title = "提爾的第一個挑戰：技法", objective = "在蒼藍高地完成提爾的第一個挑戰。", description = "<隨著你靠近，雕像上的銘文散發出微弱的光。>\n\n「駕馭守衛者的力量，帶著它的光帶領我們所有人走向更好的未來。」", progress = nil, completion = "令人敬佩的成功。你贏得了你的獎勵。", rewards = "您會收到：\n\n瓶裝精華"}
MultiLanguageQuestData['tw'][70182] = {title = "勝利的甜美滋味", objective = "返回沃卓肯的創新引擎。", description = "小東西裡也有大潛能。瓶裝精華感覺起來輕如鴻毛，但它握有龐大的力量。\n\n把它拿到創新引擎那裡去。", progress = nil, completion = "你可以感受到瓶子散發出來的潛能嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70183] = {title = "專精秘密：煉金術。", objective = "你想尋求什麼樣的智慧？", description = nil, progress = "你想尋求什麼樣的智慧？", completion = "要有耐心，年輕人，還有很多要學的。\n\n但你今天可以慶祝，因為你比以往了解的事物更多了。", rewards = "您會收到：\n\n工匠精神巨龍群島鍊金術知識"}
