MultiLanguageQuestData['tw'][70358] = {title = "巨龍群島鍛造", objective = "你也是來這片群島製造新武器或護甲的嗎？我研究這個新礦石好一陣子了…如果你有興趣的話，我可以教你一些訣竅。", description = nil, progress = nil, completion = nil, rewards = nil}
