MultiLanguageQuestData['tw'][70360] = {title = "巨龍群島附魔", objective = "這些群島充滿了秘法力量！\n\n你看起來像是懂一點附魔的人，想看看令人驚豔的東西嗎？\n\n我可以教你只有巨龍群島才有的新附魔。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70362] = {title = "巨龍群島製皮", objective = "剝取野獸毛皮的方式當然不只一種。\n\n身為製皮師的你一定懂這點。可是，你知道要怎麼使用元龍皮革嗎？\n\n我可以教你新的製皮技術，在巨龍群島會很實用的。", description = nil, progress = nil, completion = nil, rewards = nil}
