MultiLanguageQuestData['tw'][70444] = {title = "殘暴野地", objective = "在殘暴野地與葛爾薩克會面。", description = "給最勇敢的席卡人！\n\n做好萬全準備，然後前往殘暴野地吧。你可以獲得最勇猛之人的頭銜！\n\n證明你的能耐。展現你最強的戰鬥實力！\n\n另有條款及細則。", progress = nil, completion = "嘿，你可不是半人馬。\n\n好，就你吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70446] = {title = "個人歷史", objective = "在黑曜觀測所和安珀莎會面。", description = "分析過文庫中的收藏後，我找到一些線索，指出黑曜觀測所有個對大地守護者非常重要的地方。我只能猜測，裡面可能藏有關於我們軍團歷史的知識。\n\n安珀莎對此很感興趣，我已經把我的發現告訴她。希望我沒做錯。\n\n她已經先進去調查了。拜託，請去盯著她。她是個強悍的士兵，但這個話題實在…不好處理。誰知道到底會找到什麼真相。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70450] = {title = "水獺驚嚇", objective = "嚇走可惡的巨獺\n\n你每天只能額外解鎖一個捕漁網。", description = "嗨，朋友。這些巨獺一直在偷我的漁獲！\n\n要我決定的話，我會把牠們炸飛，可是我們的巨牙海民朋友似乎不太贊同。我做了這個巨獺趨避裝置MK-SH4RK，可是…我不是很擅長游泳。\n\n你看來很擅長，能不能幫所有人一個大忙，啟動這裝置、游啊游到那邊去，把牠們嚇走？", progress = nil, completion = "嘿！做得好，夥伴。現在，讓我們盡情釣魚吧！", rewards = "您會學到：\n\n補充魚\n\n您還會收到：\n\n不祥的海螺"}
MultiLanguageQuestData['tw'][70501] = {title = "狩獵執照", objective = "完成大狩獵訓練任務。", description = "啊，終於準備好要證明你的狩獵能力了？你要記得，這可不是跑來跑去、狩獵任何會動的生物那麼簡單。席卡的狩獵是有目的的。我們狩獵是為了氏族提供食物及衣物、向強大的敵手證明我們的力量以及平衡自然。\n\n我們不會狩獵到土地枯竭，在狩獵過程會撒下種子來成就未來更多的大狩獵。證明你有能力遵守這些規範，我們就會讓你加入。\n\n我不太敢說你那個朋友會成功就是了。", progress = nil, completion = "太棒了！你準備好加入大狩獵了！\n\n請告知這位奈辛瓦里二世說，狩獵不只是盲目殺戮而已，我們不歡迎他加入。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70503] = {title = "提爾的戒備", objective = "找回石頭碎塊。", description = "屍體、破損的裝備、失控的泰坦能量。真是一點都不重視安全…還有程序！看來他們找到了石頭，不穩定的石頭爆裂成了許多碎塊。\n\n幸好，我相當精通於修復魔法裝置。\n\n不過在我重塑石頭之前，我們必須先把每一塊碎塊收集起來。", progress = "我真不敢相信。東西都在這！做得好。", completion = "我會返回營地，讓我的人重新拼湊這塊石頭。別擔心，&lt;name&gt;，文物修復是我們的專長。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70507] = {title = "提爾的見解", objective = "找回提爾的見解。", description = "你在過來的路上有看到薩爾斯克烈思嗎？就是東北方的那座廢棄高塔。\n\n我們在那裡發現了好消息跟壞消息。好消息是石頭找到了，壞消息是被碎裂火焰軍找到的。具體來說，是一個名叫馬柯，而且會使用魔法的半龍人找到的。他用石頭來控制戈洛克族。\n\n我有提到半龍人濫用石頭讓他們發瘋了嗎？\n\n就這樣，祝你好運！", progress = "看來戈洛克不是什麼稱職的保鏢，對吧？要是她還能保持理智的話，不知道會有多危險。", completion = "你拿到了！不用擔心我。我們拿著它應該不會有危險，只要不做瘋狂的事就好，像是心控小魚怪之類的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70509] = {title = "提爾的第三個挑戰：堅毅", objective = "找回遺失的部位並修復破損的雕像。", description = "<看來那些和群島一起重新甦醒的人對守衛者提爾的造物並不友善。或許找到雕像遺失的部位會有幫助。>", progress = "<隨著你靠近，你可以感受到泰坦能量的溫度再次於雕像內四處流動。>", completion = "和之前一樣做得很好。我能感覺到，提爾對未來的信心不是毫無根據。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70510] = {title = "勝利", objective = "返回沃卓肯的創新引擎。", description = "我要再次請你把這個精華拿到創新引擎去。", progress = nil, completion = "你有沒有注意到，每瓶精華在你帶過來時都會變得更亮？這顯現出你注定要走這條路。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70529] = {title = "帶他們回家", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70530] = {title = "測驗週", objective = "在沃卓肯使用取回藥劑配方製造5個龍之鍊金溶液交給康芙拉苟。", description = "阿爾蓋薩學院的學生用光溶液了…又來了。不好意思要這樣問你，但你可不可以收集更多龍之鍊金溶液來，好讓他們繼續他們的課程？", progress = "學生快失去耐心了。", completion = "太好了，我們最後不需要取消測驗了。畢竟沒有溶液就沒辦法測試了！\n\n來，研究這個。就算你是熟練的鍊金師，還是有很多要學的。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][70531] = {title = "法力市集", objective = "在沃卓肯製作10個充氣法力藥水交給康芙拉苟。", description = "這週的法力藥水需求已經大幅上升，$p。我會需要你的協助來完成客戶的訂單。像你這樣熟練的鍊金師一定沒問題的，對吧？", progress = "我們的顧客在等著呢。", completion = "謝謝你，&lt;name&gt;。我的鍊金術非常厲害，但我的客戶服務還有加強的空間。有你在這裡幫我一起完成訂單真好。\n\n來，研究這個。就算你是熟練的鍊金師，還是有很多要學的。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][70532] = {title = "襲擊支援", objective = "在沃卓肯製作10瓶提神治療藥水交給康芙拉苟。", description = "噢，$p，真高興能看到你。好幾名勇士在上一次和洪荒使者作戰時受了傷。我們急需治療藥水。你身為冒險者，自己也會帶著好幾瓶藥水才對，我們則是需要非常多。", progress = "你浪費越多時間，洪荒使者就越強大。", completion = "謝謝你，&lt;name&gt;。這樣我們受傷的勇士就能恢復過來，抵抗作亂的洪荒使者，讓我們多撐一個禮拜。\n\n來，這個給你研究研究。就算你對鍊金術很熟練，依然有很多要學。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][70533] = {title = "藥劑，得加些油", objective = "在沃卓肯製作6個攀纏火油交給康芙拉苟。", description = "你知道攀纏火油是用來為藥劑收尾的絕佳材料嗎？我知道，而且我手上的油用完了。沒有充足的火油庫存，我沒辦法工作。拜託，$p，幫我補充一下實驗室庫存吧。", progress = "沒使用攀纏火油的藥劑就像是沒有鹽的料理一樣。", completion = "太好了，謝謝你。每次記得使用攀纏火油這樣的最後加工材料來收尾，這樣就能做出非常好的藥劑。\n\n來，這個給你研究研究。就算你對鍊金術很熟練，依然有很多要學。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][70539] = {title = "你以為它們沒用", objective = "在沃卓肯製造2個里程碑放大鏡交給叮噹點‧碎爆。", description = "嘿，工程師，你知道大家在巨龍群島飛來飛去時，都會忘記他們需要什麼嗎？護目鏡。\n\n你知道我們今天賣光什麼商品嗎？護目鏡。\n\n你知道我現在需要你給我什麼嗎？你猜對了！", progress = "<叮噹點一邊自言自語一邊找東西。>", completion = "噢，好極了！這些看起來很完美，謝啦！\n\n來，拿好這些結構圖，你一定可以學到什麼新東西。", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][70540] = {title = "工程師最好的好朋友", objective = "幫沃卓肯的叮噹點‧碎爆製作2個龍金包覆的主動式負載平衡器。", description = "嘿，工程師，你有看到我的…\n\n呃…幫我拿…\n\n我決定了！我們應該在店裡擺出更多更多工具，你懂我的意思嗎？", progress = "<叮噹點一邊自言自語一邊找東西。>", completion = "終於！少了這些東西，就像要我把雙手綁在背後製作東西一樣。\n\n來，拿著這些結構圖，你一定可以學到什麼新東西。", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][70541] = {title = "狩獵戰術：夥伴", objective = "選擇在大狩獵中要和巴卡犬還是歐胡納鷹一同戰鬥。", description = "你在莫魯克越來越有名望。你現在或許能跟頑強的巴卡犬或迅捷的歐胡納鷹夥伴一起狩獵。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70545] = {title = "布靈登8000型…？", objective = "在沃卓肯製造10把賽若拜岩螺栓交給叮噹點‧碎爆。", description = "嘿，工程師，我在進行一個秘密計畫。大家一定會為之瘋狂的！可是我還需要更多材料…當個好夥伴，幫我弄些螺栓過來好嗎？", progress = "<叮噹點一邊自言自語一邊找東西。>", completion = "噢噢噢…！&lt;叮噹點開始自顧自地大笑，似乎在想像她會如何使用這些東西。&gt;\n\n來，拿著這些結構圖，你一定可以學到什麼新東西。", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][70549] = {title = "低垂的果實", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70550] = {title = "歡迎來到集會", objective = "在鈷藍集會和薩文交談，了解可在該處使用什麼能力。", description = "我們需要你的幫忙。\n\n碎裂火焰軍已經控制了大部分的鈷藍集會。\n\n請幫我們一起對抗碎裂火焰軍。我們雖然勢單力薄，但還是能提供你一些協助。", progress = nil, completion = "一旦我們控制了鈷藍集會的其他地方，就能為盟友提供更多支援，共同對抗碎裂火焰軍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70557] = {title = "沒有瞄準鏡", objective = "在沃卓肯製造15個青銅龍軍團煙火交給叮噹點‧碎爆。", description = "好零件，工程師，我今天有項大任務要交代你！\n\n顯然，獵人之間流行起了煙火風潮。他們想發射煙火來把鴨子嚇到空中。我猜鴨子應該很聰明，不會吃這套，但我們還是能藉此大撈特撈！你要不要來幫忙完成工作呀？", progress = "<叮噹點一邊自言自語一邊找東西。>", completion = "謝啦，工程師！目前這樣就可以了，直到他們又想出新的千奇百怪理由丟掉還能用的器具為止。\n\n來，拿著這些結構圖，你一定可以學到什麼新東西。", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][70558] = {title = "不只是幻象的幻象", objective = "在沃卓肯製造5個幻象羊皮紙：法術護盾交給塔仁達菈。", description = "我的雕銘學徒啊，你來的時機實在太好了。這裡出了可怕的意外！\n\n出大事了！我訂購的所有幻象羊皮紙都變成真的了！你相信嗎？這是什麼遊戲嗎？有人可能會受傷！\n\n你能不能彌補這個問題、做幾個真正的幻象過來？", progress = "你雕好我需要的東西了嗎？", completion = "我萬分感謝你，我的雕銘學徒。\n\n為了表達感謝，請你接受這些雕紋吧。或許你可以研究它們來精進你的技藝。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][70559] = {title = "幫忙弄點羽毛筆來，好嗎？", objective = "在沃卓肯製造2個雕銘師的牢固羽毛筆交給塔仁達菈。", description = "我的雕銘學徒啊，看到你真好。今天稍早的時候，有幾個新手來試了一下銘文學。他們寫字都太用力，還把羽毛筆尖都弄斷了！我很不想麻煩你，但我可以請你多製作幾支羽毛筆當作我們的庫存嗎？", progress = "你拿到給我學徒用的新羽毛筆了嗎？", completion = "謝謝你，我的雕銘學徒。沒有你我真不知道該怎麼辦。\n\n為了表達感謝，請你接受這些雕紋吧。或許你可以研究它們來精進你的技藝。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][70560] = {title = "最有力的工具：良好記錄", objective = "在沃卓肯製造2個探險手冊綱要交給塔仁達菈。", description = "我的雕銘學徒啊，你今天準備好要寫字了嗎？龍鱗遠征隊帶來了他們在冒險中寫下的大量筆記，並請我們把他們的鬼畫符筆記彙整成合適的綱要，以利隨時在野外檢視。還有啊，我的手今天恰好沒辦法勝任這個任務。我可以再依賴你完成這個工作嗎？", progress = "你把綱要刻好了嗎？", completion = "謝謝你，我的雕銘學徒，謝謝你。\n\n為了表達感謝，請你接受這些雕紋吧。或許你可以研究它們來精進你的技藝。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][70561] = {title = "雕銘師的悲劇", objective = "在沃卓肯製造5個熾炎墨水交給塔仁達菈。", description = "我的雕銘學徒啊！這真是太糟糕、太糟了！\n\n我無法思考我該如何活下去！\n\n<塔仁達菈開始啜泣。>\n\n…我的墨水用光了！你可以再裝一些來嗎？", progress = "你把墨水裝好了嗎？", completion = "謝謝你，我的雕銘學徒。要是有法師願意做出你的分身就好了…\n\n為了表達感謝，請你接受這些雕紋吧。或許你可以研究它們來精進你的技藝。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][70562] = {title = "水管工，石匠", objective = "在沃卓肯製造15個破碎的石頭給圖魯拉多米。", description = "珠寶設計師，你覺得練習勘探技巧的機會聽起來怎麼樣？\n\n龍鱗遠征隊的建築師及水管工委託我們找這些石頭，他們才有辦法建造新的浴池。你應該會覺得，這是個讓你有事做又能練習石工技藝的合適工作。", progress = "石頭好了嗎？", completion = "做得好，&lt;name&gt;。\n\n來，這些是我做的雕刻，你可以研究一下，了解怎樣才能成為像我一樣厲害的珠寶設計師。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][70563] = {title = "展覽", objective = "在沃卓肯製作各種不同的寶石給圖魯拉多米。", description = "噢，珠寶設計師，你覺得練習寶石雕刻的機會聽起來怎麼樣？\n\n我打算要展示不同的切割品，並想到我也可以順便展示你的寶石，前提是你動作要快。為了這次展出，我只收最高品質的成品。", progress = "你的寶石適合拿來展示嗎？", completion = "非常好，這些應該就行了。\n\n來，這些是我做的雕刻，你可以研究一下，了解怎樣才能成為像我一樣厲害的珠寶設計師。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][70564] = {title = "嘆為觀止", objective = "在沃卓肯製造2個裂紋黑瑪瑙放大鏡交給圖魯拉多米。", description = "珠寶設計師，有一個展覽即將到來，而我很擔心少了適當的放大鏡，客戶會沒有辦法看到每個切割點的美。\n\n你不需要拿華麗的成品來，只要做幾副能讓我們的顧客看清楚的放大鏡就好。", progress = "放大鏡做好了嗎？", completion = "感謝你的辛勞…我可以想像有人會這麼說。大概吧。\n\n來，這些是我做的雕刻，你可以研究一下，了解怎樣才能成為像我一樣厲害的珠寶設計師。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][70565] = {title = "飽和襯托", objective = "在沃卓肯製造2個火燒屁股墜飾交給圖魯拉多米。", description = "噢，珠寶設計師，你喜歡我的項鍊嗎？\n\n你當然喜歡啦。可是，除非有東西讓它襯托，不然我無法好好炫耀它。\n\n我知道了，不如你做幾個簡單的墜飾，讓市場飽和吧。等到大家都在戴你設計的作品時，我的項鍊就會是比其他項鍊都耀眼的精品！", progress = "墜飾做好了嗎？", completion = "一切都是為了時尚，&lt;name&gt;。\n\n來，這些是我做的雕刻，你可以研究一下，了解怎樣才能成為像我一樣厲害的珠寶設計師。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][70567] = {title = "給巴卡犬骨頭時", objective = "在沃卓肯製造2個骨鍛之弩給『塑皮者』寇魯茲。", description = "原本我有好幾把做工精美的骨製弓箭，結果根本沒派上用場就被巴卡犬咬壞了。巴卡犬最喜歡啃咬骨頭，不管它們是不是被做成了弓箭…反正現在全都毀了！\n\n你可以幫我製作幾副新的嗎？", progress = nil, completion = "謝謝你，&lt;name&gt;。\n\n這是報酬，收下這些設計圖。你可以研究一下，好好增進你的製皮技術。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][70568] = {title = "鱗片贈品", objective = "在沃卓肯製作2個拓荒者鱗甲護腕給『塑皮者』寇魯茲。", description = "我們的鱗甲護腕品質很好，因此銷路也很棒。但是我已經有點趕不上訂單的需求了！你願意發揮你的專業技術，幫我補充商品的庫存量嗎？", progress = "我們的商品都是最高品質的。我一點也不驚訝它們會賣這麼好。", completion = "做得太好了，&lt;name&gt;。\n\n為了表達謝意，請收下這些設計圖。你可以研究一下，好好增進你的製皮技術。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][70569] = {title = "為崔斯可做工具", objective = "在沃卓肯製造2個草藥師的花籃給『塑皮者』寇魯茲。", description = "我有很多優秀的顧客，崔斯可是其中我最喜歡的。他最近來找我幫忙，因為他弄破了他的草藥師袋子。\n\n我答應會為他做幾個籃子來取代他之前的袋子。\n\n你可以幫我完成這些工作嗎，$p？崔斯可一定會非常感激的。", progress = "這些籃子十分堅固，相信崔斯可一定會很滿意的。", completion = "你幫大忙了，&lt;name&gt;！\n\n這是報酬，收下這些設計圖。你可以研究一下，好好增進你的製皮技術。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][70571] = {title = "來買鼓喲！", objective = "在沃卓肯製造2個兇野皮鼓交給『塑皮者』寇魯茲。", description = "我們的鼓遠近馳名，半人馬的製鼓技藝已經傳承了不知道多少個世紀。不幸的是，這也代表我們的鼓最近有點供不應求。\n\n我看得出來，你的技術也很不錯。說不定你可以幫我們的店家做幾面鼓？", progress = "你的技術相當不錯。這些本領是從哪裡學來的？", completion = "太感謝你了，&lt;name&gt;！\n\n來，收下這些設計圖。你可以研究一下，好好增進你的製皮技術。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][70572] = {title = "其實，他們怕冷", objective = "幫沃卓肯的芙拉馮製作2件勘測員布甲長袍。", description = "$p要說我擔任裁縫師多年來學到了什麼，那就是冒險者永遠低估了寒冷的天氣。\n\n有一些蒼藍高地的探險者在求我賣更暖和的長袍給他們。\n\n你可憐可憐他們，去做幾件來吧？", progress = "長袍做好了嗎？", completion = "謝謝你，&lt;name&gt;。\n\n來，好好研究這些樣品來精進你的裁縫技藝。\n\n別忘了保暖。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][70582] = {title = "獨自織得夠好", objective = "在沃卓肯製造3個荒紋布匹給芙拉馮。", description = "要說我擔任裁縫師多年來學到了什麼，$p，那就是練習的重要性。\n\n永遠別忘了練習你的手藝，就算你以為自己已經精通一切也一樣。我希望你在沒有我監督的情況下也能編織出上好的布。\n\n不然你這禮拜練習一下？在你的能力內做幾條最高品質的荒紋布匹吧。", progress = "布匹準備好了嗎？", completion = "你這些布做得很好，&lt;name&gt;。\n\n來，好好研究這些樣品來精進你的裁縫技藝。\n\n保持機靈。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][70586] = {title = "針多廚師", objective = "在沃卓肯製造2個荒紋布主廚帽給芙拉馮。", description = "要說我擔任裁縫師多年來學到了什麼，$p，那就是太多主廚反倒誤事。\n\n在這裡我是指，我本來想出去喝一杯的，可是臨時來了一個訂單，要買一整櫃的廚師制服。\n\n如果你可以負責縫帽子的話，我能夠自己完成其他東西。", progress = "縫好主廚帽了嗎？", completion = "謝謝你，&lt;name&gt;。你永遠都這麼渴望接受挑戰啊。\n\n來，好好研究這些樣品來精進你的裁縫技藝。\n\n還有要勇於挑戰。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][70587] = {title = "背包問題", objective = "在沃卓肯製造1個簡易縫合材料袋給芙拉馮。", description = "要說我擔任裁縫師多年來學到了什麼，$p，那就是放材料的空間永遠不嫌多。事實上，我們需要幾個額外的袋子來放東西。你不介意再多縫個袋子吧？", progress = "袋子做好了嗎？", completion = "謝謝你，&lt;name&gt;。這些會很合用的。\n\n來，好好研究這些樣品來精進你的裁縫技藝。\n\n還有，遠離那些要賣你無限儲存空間的人。你絕對不想知道這樣會導致什麼後果。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][70589] = {title = "鍛造手藝不可或缺", objective = "為工匠聯盟完成鍛造製作訂單。", description = "嗨嗨嗨，$p！製作訂單一直進來！\n\n要是你在找工作，工匠聯盟有源源不絕的訂單！\n\n你可以看一下我們的公開訂單，或者，如果你有自己的客群，也能接下一些公會訂單或個人訂單！完成越多訂單越好！", progress = nil, completion = "感謝你的幫忙！請繼續製作、製作再製作！", rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][70591] = {title = "工程手藝不可或缺", objective = "為工匠聯盟完成工程學製作訂單。", description = "嗨嗨嗨，$p！製作訂單一直進來！\n\n要是你在找工作，工匠聯盟有源源不絕的訂單！\n\n你可以看一下我們的公開訂單，或者，如果你有自己的客群，也能接下一些公會訂單或個人訂單！完成越多訂單越好！", progress = nil, completion = "感謝你的幫忙！請繼續製作、製作再製作！", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][70592] = {title = "銘文手藝不可或缺", objective = "為工匠聯盟完成銘文學製作訂單。", description = "嗨嗨嗨，$p！製作訂單一直進來！\n\n要是你在找工作，工匠聯盟有源源不絕的訂單！\n\n你可以看一下我們的公開訂單，或者，如果你有自己的客群，也能接下一些公會訂單或個人訂單！完成越多訂單越好！", progress = nil, completion = "感謝你的幫忙！請繼續製作、製作再製作！", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][70593] = {title = "珠寶設計手藝不可或缺", objective = "為工匠聯盟完成珠寶設計製作訂單。", description = "嗨嗨嗨，$p！製作訂單一直進來！\n\n要是你在找工作，工匠聯盟有源源不絕的訂單！\n\n你可以看一下我們的公開訂單，或者，如果你有自己的客群，也能接下一些公會訂單或個人訂單！完成越多訂單越好！", progress = nil, completion = "感謝你的幫忙！請繼續製作、製作再製作！", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][70594] = {title = "製皮手藝不可或缺", objective = "為工匠聯盟完成製皮製作訂單。", description = "嗨嗨嗨，$p！製作訂單一直進來！\n\n要是你在找工作，工匠聯盟有源源不絕的訂單！\n\n你可以看一下我們的公開訂單，或者，如果你有自己的客群，也能接下一些公會訂單或個人訂單！完成越多訂單越好！", progress = nil, completion = "感謝你的幫忙！請繼續製作、製作再製作！", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][70595] = {title = "裁縫手藝不可或缺", objective = "為工匠聯盟完成裁縫製作訂單。", description = "嗨嗨嗨，$p！製作訂單一直進來！\n\n要是你在找工作，工匠聯盟有源源不絕的訂單！\n\n你可以看一下我們的公開訂單，或者，如果你有自己的客群，也能接下一些公會訂單或個人訂單！完成越多訂單越好！", progress = nil, completion = "感謝你的幫忙！請繼續製作、製作再製作！", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][70602] = {title = "歷史課：流沙之戰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70612] = {title = "餵養三瀑布", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70613] = {title = "在他們賴皮前給樹皮", objective = "採集8個攀纏樹皮交給沃卓肯的阿格力克斯。", description = "$p，你是個能幹的草藥師，對吧？附近的鍊金師都在我門前…嗯，我是沒有門啦…找我要更多攀纏樹皮。我們庫存就快賣光啦！\n\n你可以幫我再去多收集一些回來嗎？萬一鍊金師沒辦法做他們需要的藥瓶，我很怕他們會開始亂拿我的東西做實驗。", progress = "你找到足夠的攀纏樹皮了嗎？", completion = "謝謝你，&lt;name&gt;。\n\n請把我的筆記拿去。好好研究來精進你的草藥學知識吧。", rewards = "您會收到：\n\n草藥學田野筆記"}
MultiLanguageQuestData['tw'][70614] = {title = "泡沫熱潮", objective = "採集8個泡沫罌粟交給沃卓肯的阿格力克斯。", description = "<阿格力克斯對你大吼。>我的罌粟茶賣完了！\n\n…噢，你不是要買的客人。讚美泰坦。有人把「泡沫罌粟」變成了本週市面上最潮的飲料，讓我的罌粟全部賣光了。拜託，在那些人成群回來之前，你可以去帶更多罌粟來嗎？", progress = "<阿格力克斯在努力讓自己冷靜。>", completion = "感謝你，&lt;name&gt;，感謝你。\n\n請把我的筆記拿去。好好研究來精進你的草藥學知識吧。\n\n我需要…煮些茶來…", rewards = "您會收到：\n\n草藥學田野筆記"}
MultiLanguageQuestData['tw'][70615] = {title = "草藥失蹤案件", objective = "採集8個虎耳草交給沃卓肯的阿格力克斯。", description = "啊，$p！你在這！\n\n東西被拿走了！有人拿走了我的虎耳草！\n\n我只不過離開兩個小時，但我回來的時候，就發現有人把我的虎耳草拿走了！對方只留下這袋沉甸甸的金幣來炫耀他的罪行。一副草藥有錢就能買的樣子！\n\n…拜託，$p，我需要更多虎耳草，這樣才能彌補那個罪犯從我這裡奪走的東西。", progress = "你找到給我的藥草了嗎？", completion = "謝謝你，&lt;name&gt;。這週真是風波不斷…\n\n請把我的筆記拿去。好好研究來精進你的草藥學知識吧。", rewards = "您會收到：\n\n草藥學田野筆記"}
MultiLanguageQuestData['tw'][70616] = {title = "你說多少個？", objective = "採集20個荷芡花交給沃卓肯的阿格力克斯。", description = "<在你靠近時，阿格力克斯在哭。>\n\n事情發生了…我真不敢相信有人會這樣…\n\n有人到我這裡來，要我賣一千份草藥給他！\n\n簡直令人髮指！真是荒謬至極。荒唐！可笑！！\n\n…請你幫忙。", progress = "五百六十一…五百六十二…\n\n<阿格力克斯再次開始啜泣。>", completion = "喔，很好。這能幫上忙。感謝你的協助。\n\n請把我的筆記拿去。好好研究來精進你的草藥學知識吧。\n\n我還有草藥得數呢。", rewards = "您會收到：\n\n草藥學田野筆記"}
MultiLanguageQuestData['tw'][70617] = {title = "全部都是我的礦", objective = "收集7個龍金礦石交給沃卓肯的『掘地者』瑟奇塔。", description = "龍金礦的用途非常廣泛，可以拿來做很多的東西。它是最完美的礦石，純粹無可挑剔。\n\n帶龍金礦石來給我。我一定要拿到手。你是礦工對吧？那就去採礦！", progress = "嗯？你挖到要給我的礦石了嗎？", completion = "對、對、對！正是我需要的。\n\n離開的時候把我的筆記拿去。我寫了一些在這邊採礦的有用訣竅。", rewards = "您會收到：\n\n採礦田野筆記"}
MultiLanguageQuestData['tw'][70618] = {title = "熔爐的呼喚", objective = "收集16個賽若拜岩礦石交給沃卓肯的『掘地者』瑟奇塔。", description = "熔爐…她在呼喚我。而她要求了賽若拜岩。那邊的人！把賽若拜岩帶來給我！沒錯，一大堆賽若拜岩！<瑟奇塔開始狂熱地大笑。>", progress = "熔爐還要更多、更多、更多！\n\n<瑟奇塔開始狂熱地大笑。>", completion = "很好，很好！\n\n這讓熔爐很滿意。\n\n走的時候把我的筆記拿去吧。筆記裡面一定有你不知道的採礦知識可學。", rewards = "您會收到：\n\n採礦田野筆記"}
MultiLanguageQuestData['tw'][70619] = {title = "皮革研究論", objective = "採集40個強韌皮革交給沃卓肯的『粗曠者』瑞拉索爾。", description = "嘿！你好像可以幫忙我正在進行的皮革研究。這裡有些皮革很軟，但也有些皮革的特性比較堅韌，應該蠻適合做護甲的！\n\n帶一些皮革來給我調查吧，我希望能繼續我的研究。", progress = "你找到可供我研究的皮革了嗎？", completion = "謝謝你，&lt;name&gt;，這應該有助於磨練我的技藝。\n\n來，把我的筆記拿去。應該能幫你更了解這片土地的野獸，還有進階的剝皮手法。", rewards = "您會收到：\n\n剝皮田野筆記"}
MultiLanguageQuestData['tw'][70620] = {title = "鱗片升級", objective = "採集40個不滅龍鱗交給沃卓肯的『粗曠者』瑞拉索爾。", description = "許多人都想知道我怎麼會這麼擅長剝皮，而我都這樣回答：一切取決於鱗片。\n\n你也會好奇、想多學一點嗎？幫我帶一些鱗片來，我就能展示給你看。", progress = "你找到堪用的鱗片了嗎？", completion = "非常完美。做了這麼多練習，你的剝皮技術也進步了吧？一切取決於鱗片！\n\n來，把我的筆記拿去。應該能幫你更了解這片土地的野獸，還有進階的剝皮手法。", rewards = "您會收到：\n\n剝皮田野筆記"}
MultiLanguageQuestData['tw'][70621] = {title = "提爾的第三個挑戰：堅毅已體現", objective = "接受靈感仕女的瓶裝精華。", description = "你的第三項挑戰是為了讓你克服不利的逆境。這是為了讓你展現毅力給我看。\n\n為了讓我指派挑戰給你，你對抗加拉登，並且修復我的雕像。我認為這已經早就滿足你的勝利條件。\n\n<你似乎看到她的唇上掠過了一絲微笑。>", progress = nil, completion = "你的第三項挑戰是為了讓你克服不利的逆境。這是為了讓你展現毅力給我看。\n\n為了讓我指派挑戰給你，你對抗加拉登，並且修復我的雕像。我認為這已經早就滿足你的勝利條件。\n\n&lt;你似乎看到她的唇上掠過了一絲微笑。&gt;", rewards = "您會收到：\n\n瓶裝精華"}
