MultiLanguageQuestData['tw'][70721] = {title = "為愛相「雍」", objective = "協助風之賢者達瓦和獵人納爾曼進行求婚。", description = "空之鏡旁邊有一個小池塘，那是我和納爾曼在我的學徒訓練期間初遇的地方。\n\n學徒會到上面去，進一步靠近雍亞拉才能感受到風。當初，一陣突然的風使我睜開了雙眼，使我透過水中的倒影看見了他。那是整片平原最美的風景。\n\n那會是我們完美的求婚地點。", progress = nil, completion = "謝謝你，&lt;name&gt;。\n\n達瓦和我會永遠記得你為我們做的事。", rewards = "您會收到：\n\n食譜：慶祝蛋糕捧花"}
MultiLanguageQuestData['tw'][70722] = {title = "魯賓斯的需求", objective = "在伊斯凱拉與派楚交談。", description = "我想，我知道我們要做些什麼，<name>。\n\n我們先就此聊一聊吧。\n\n在結束後，我甚至還準備了禮物要送你！很好玩，對不對？", progress = nil, completion = "記得召喚魯賓斯，然後對他使用這顆戰鬥石。它會永久提升他的實力。", rewards = "您會收到：\n\n無瑕龍類生物戰鬥石磨亮的寵物吊飾"}
MultiLanguageQuestData['tw'][70723] = {title = "粉碎地之洪荒使者", objective = "將洪荒核心帶去給瑞斯勒希。\n\n已提供物品：\n", description = "沃卓肯的瑞斯勒希拿到這個一定會很感激的，這對他的洪荒使者研究很有幫助。", progress = nil, completion = "這能讓我們進一步了解洪荒使者。謝謝你。", rewards = "您會收到：\n\n風暴符印"}
MultiLanguageQuestData['tw'][70730] = {title = "席卡贈予者", objective = "協助風之賢者達瓦準備完美的求婚。", description = "噢，$p。\n\n你在太陽下感到舒適嗎？它明亮的撫觸讓你感到安全嗎？每個新的一天是否都象徵著未來的希望，以及活出夢想生活的機會？\n\n那麼，你和我一樣了解愛。\n\n席卡氏族的納爾曼就是我的太陽。他是我的溫暖、是我的光，是我的希望。\n\n像他這麼優秀的男人值得一場配得上他的求婚。\n\n我們必須向雍尋求指引。", progress = "納爾曼是個偉大的人，也該得到相應的示愛。", completion = "阿柏厚的角？這應該可以。\n\n阿柏厚曾經是平原上最健壯的鬃牛。沒有任何禮物比這個更適合最偉大的獵人。我敢說他一定會很喜歡。\n\n也許有一天他會教我狩獵。一個雍伊爾獵人。哈！想像一下。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70732] = {title = "練習賽", objective = "在寵物對戰中擊敗呱許。", description = "好的！既然你已經把那顆石頭用在魯賓斯上，我們來場練習賽，測試他的能耐吧！\n\n在這裡北邊的海岸，有一隻巨大的角蛙，名叫呱許。呱許很喜歡戰鬥！嗯，其實是玩。他也很擅長跟其他寵物相處！\n\n這會是完美的玩樂時間…我是說戰鬥…對魯賓斯來說啦。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][70738] = {title = "瑜珈課", objective = "找到教練及6名瑜珈學生。", description = "本來一切都很好，但現在呢？元素生物正在引發一些，呃…溫和的騷動。\n\n客人正在舒舒服服享受這裡的設施，但是突然間，那些元素就都冒出來了！該死的東西打亂了所有的安排，連新的瑜珈教練都受到波及。\n\n是的，瑜珈是一種新型態的拉筋，同時還可以幫助你冥想。我相信老師跟學生應該都超放鬆的、可能壓根沒注意到元素的出現。\n\n不過，還是保險一點比較好。麻煩你去找一下他們。", progress = nil, completion = "希望這次經歷不會影響他們的評價！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70739] = {title = "血脈、甜品和蹄萊", objective = "協助獵人納爾曼，為他的求婚贏得傳統的祝福。", description = "我曾和可汗並肩狩獵、跑贏我們最快的巴卡犬，甚至徒手和一頭成年的公麋牛搏鬥。以獵人的本領來說，我已經不需要再證明什麼。\n\n然而，以伴侶來說，我還有很多要學的。\n\n雍伊爾氏族的風之賢者達瓦是我的心肝和我的快樂。我希望能證明我配得上他的愛，但我完全不了解這方面的傳統或儀式。我需要向莫魯凱的長者請教他們的智慧之言。", progress = nil, completion = "我寧願要求夜空中的所有星星崇拜我，也不敢主張我完全配得上達瓦的愛。\n\n儘管如此，我還是會鼓起進行下一步的勇氣。在時機成熟時，你願意協助我的盛大求婚嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70740] = {title = "蒸汽清理", objective = "在下層水療中心殺死12個元素生物。", description = "席安似乎覺得元素生物入侵我們美麗的水療中心沒什麼，但我們得立即抑制這些忽然冒出來的烈焰和蒸氣。\n\n我們聘請了一些樂師在下層水療中心表演，但是元素摧毀了他們的裝備。這個地方從來沒有這麼嚴重的元素騷動，我懷疑是洪荒使者搞的鬼。\n\n如果你想要幫忙，就幫忙解決下層水療中心東側的元素。那是第一批活動預定舉辦的地點。", progress = nil, completion = "這是個好的開始，可是數量還有太多，我不喜歡…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70741] = {title = "一些最喜愛的東西", objective = "收集6件丟失的行囊。", description = "<看來瑜珈課被打斷了，學生的個人物品散落四處。>\n\n收集這些東西肯定能幫到安詳夢境水療中心。>", progress = nil, completion = "你真是個好人，願意收集這些物品。我們會立刻把它們還給失主！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70742] = {title = "追本溯源", objective = "搜索黑曜觀測所，尋找關於半龍人過去的線索。", description = "我飛到空中，調查艾錐斯發現的其中一個神器，就在入口的廢墟旁。裡面無疑會有更多。\n\n它們好像被結界保護起來，我需要更靠近一點，才能看得更仔細。這裡的魔法相當古老。\n\n地面看起來什麼都沒有，但等到我們開始調查，這裡一定不會那麼平靜。提高警覺，我們要盡全力調查清楚。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70743] = {title = "珍貴的寶寶", objective = "找到艾札菈的寶寶。", description = "那邊那個，$pr！你還算差強人意吧？\n\n你應該沒有什麼急事吧？\n\n很好！\n\n我珍貴的寶寶不見了。馬上去救她。動作快點，在這麼惡劣的環境中，她根本無法照顧好自己。", progress = nil, completion = "&lt;艾札菈無視你的存在，眼中只有寶寶。&gt;\n\n我的甜心小寶貝，你還好嗎？\n\n洪荒使者的血沾到你了嗎？他們好大的膽子！\n\n&lt;艾札菈終於注意到你。&gt;\n\n我絕對要給這個水療中心一顆星評價。我以為這會是場無血體驗。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70744] = {title = "看看這些骨頭啊！", objective = "清理10個髒汙。", description = "<要是沒有弄到滿地是血，水療中心主管一定會很感激…>", progress = nil, completion = "我不會想知道事發經過的，是吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70745] = {title = "強迫放鬆", objective = "殺死元素召喚者。", description = "我認為你看到的那些洪荒使者並不像領導階層。只是普通走狗，有什麼好怕的？哈哈！\n\n但是他們提起了「瓦德妮」這個名字，這聽起來就像個首領。她肯定就是召來這些元素的罪魁禍首，所以我們得解決掉她這位召喚師。而且能夠引起這樣的騷動，表示他們應該就躲在附近才對。去看看我們正下方的洞穴，我知道有些愛偷懶的員工會窩在那邊偷懶。", progress = nil, completion = "情況終於有起色了，我真開心！我們都值得好好休息一下。\n\n我希望你也在這裡找到喘息空間：這是你應得的，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70746] = {title = "藍色之影", objective = "陪伴安珀莎和泰拉許前往安東尼達斯營地。", description = "那邊的，$p！\n在這一帶看到友善的面孔真好。泰拉許跟我剛剛正在討論關於這區的…新面孔的報告。\n\n<安珀莎壓低她的聲音。>\n\n藍龍。\n\n考慮到我們跟藍龍之間過去的…相處情況，泰拉許跟我認為我們必須親自評估這個情形。\n\n請你加入我們吧。", progress = nil, completion = "還沒看到藍龍的蹤影，不過有很多他們的手下。", rewards = nil}
MultiLanguageQuestData['tw'][70747] = {title = "蒼藍巫師", objective = "在安東尼達斯營地和大法師卡德加談話。", description = "我沒有時間和巫士鬥嘴。\n\n去和這位「大法師」協商吧，$p。好好了解一下，而且還是要保持警覺。他們可能仍是盟友，也可能是敵人…\n\n我們的報告顯示南方有一座大型的文庫建築。\n\n那裡就是我的目的地。", progress = nil, completion = "身為祈倫托的代表，聽到瑪里苟斯對你的同胞做過的事令我相當憂慮。\n\n這需要我們立刻的調查。\n\n…你的夥伴在哪裡？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70748] = {title = "藍眼專屬", objective = "在蒼藍文庫搜尋瑪里苟斯的日誌。", description = "難怪你的夥伴什麼都還沒找到。\n\n這些書只有藍眼睛能看。\n\n然而，我的存在應該可以讓一些相關的秘典透露它們的秘密。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70750] = {title = "支援協調者", objective = "繼續在巨龍群島各地協助沃卓肯協調者和他們的盟友。", description = "就是你！對，我在和你說話。難道這裡還有別人嗎？\n\n<瑟拉澤爾迅速瞥了幾眼路過的人。>\n\n別管他們。他們跟這個請求無關。我只聽說過你，也只想跟你說話！\n\n沃卓肯協調者請我找出已經在巨龍群島打響名號的人，以及想要把我們的盟友和安全確實擺在第一位的人。\n\n去做你最擅長的事，朋友。你會因此獲得豐厚的獎勵。", progress = nil, completion = "朋友，你可真是讓人欽佩啊。身為協調者的代表，我可以向你保證，你的努力我們都看見了！\n\n請接受這份我們的盟友準備的禮物。", rewards = "您會收到：\n\n\n\n等級 60–80沃卓肯寶藏\n\n等級 69–75沃卓肯協調者徽記\n\n等級 68–70伊斯凱拉巨牙海民徽記\n\n等級 63–70龍鱗遠征隊徽記莫魯克半人馬徽記龍鱗遠征隊沃卓肯協調者莫魯克半人馬伊斯凱拉巨牙海民"}
