MultiLanguageQuestData['tw'][70818] = {title = "新龍鱗設備", objective = "一批精心打造的腿甲剛到。如果你看見想要的，就和我說，我們可以交易一下。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70819] = {title = "知名探險者的護甲", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n套裝：知名遠征者皮甲護甲套裝：知名遠征者鎖甲套裝：知名遠征者鎧甲"}
MultiLanguageQuestData['tw'][70820] = {title = "駐紮地「寵物」", objective = "啊！我還以為養了一輩子的獅鷲獸，就能馴服巨龍群島那些狂野的野獸。可是這些絨猴和飛掠蟲快把我逼到極限了！我很樂意讓一隻給你。如果你還想要更多，我可以給你折扣！", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n灰色絨猴黑色飛掠蟲"}
MultiLanguageQuestData['tw'][70821] = {title = "掠蜻蜓騎乘", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n被馴服的掠蜻蜓蒼藍掠蜻蜓"}
MultiLanguageQuestData['tw'][70822] = {title = "失蹤的遠征隊斥候", objective = "我們到達以後派出了許多斥候，但有一定數量的人還沒回來。你在探索的時候可以注意一下那些斥候嗎？他們的特徵就是都帶著公發的遠征隊斥候包。噢，如果你有找到文物的話，就交給編目員潔可思，她會感謝你的。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n遺失的遠征隊斥候包"}
MultiLanguageQuestData['tw'][70828] = {title = "尋路者的羅盤", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n尋路者的羅盤"}
MultiLanguageQuestData['tw'][70831] = {title = "舒服地做研究", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n柔軟的紫色枕頭扁扁的聖匣枕頭小型三角枕頭"}
MultiLanguageQuestData['tw'][70832] = {title = "我們的一份子", objective = "你正是我們遠征隊想要招募的那種冒險者，我們有你加入也很開心！為了表示我們的感激，我想要把我們的外袍送給你。它能讓整個世界看見你的成就！不過，我們也不能忘本，如果你想要聖匣守護者或探險者協會的旌旗，我也能提供。謝謝你所做的一切！", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊外袍"}
MultiLanguageQuestData['tw'][70833] = {title = "寶光幼龍的傳聞", objective = "你聽過巨龍群島古代珠寶設計師的故事嗎？據說透過他的技術，能夠讓他製作的寶石幼龍雕像活過來。我本來以為只是個故事，結果有人在一名遇難斥候的包包裡找到了這張地圖，上面有寶光幼龍的線索。把地圖拿去，看看它是否能帶你發現創造這些傳說活雕像的秘密。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n黑曜寶石簇地圖"}
MultiLanguageQuestData['tw'][70834] = {title = "標題故事", objective = "從我們登陸以來，我紀錄了每位成員的每一項事蹟，和他們對龍鱗遠征隊貢獻的文物。今天，我注意到你的成就有多麼突出。我非常榮幸能賜給你一個威風的頭銜，和這個珍貴的洪荒注能物品，你可以用它來打造強大的物品。過來接受這份獎勵吧，對你英勇的努力成果來說，這是個真正的成就。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n堅勇探險者\n\n您還會收到：\n\n洪荒注能"}
MultiLanguageQuestData['tw'][70835] = {title = "堅固的遠征隊鏟子", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70837] = {title = "跟隨線索", objective = "在迷霧山谷和調查員艾里馬會面。", description = "<調查員艾里馬檢視地圖。>\n\n守護巨龍之座上面畫的叉叉意思應該很明顯。\n\n但是迷霧山谷也被圈起來了。說不定是叛軍的下個目標？或者是他們的基地。\n\n也只能實際去看看了。在那裡和我碰面。", progress = nil, completion = "這裡絕對是行動的基地。\n\n迷霧山谷佈滿了叛軍…還有洪荒使者！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70838] = {title = "有目標的叛亂", objective = "殺死10名叛亂者及洪荒使者。", description = "叛軍的駐紮地點…這就是我們一直在找的地方。算我們走運，他們的破壞者因為大意而把我們引來這邊。\n\n我真不敢相信，我的弟兄會墮落到跟洪荒使者合作。我們可不能姑息這種事。殺死叛亂者和他們的洪荒使者朋友，以免他們造成更多混亂。", progress = nil, completion = "你的本領不錯。\n\n但是那些叛亂者也不是省油的燈。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70839] = {title = "尋找泰坦文物", objective = "我把甦醒之後的時間都花在研究泰坦上。他們的歷史非常耐人尋味。他們究竟握有什麼樣的力量，才能創造出巨龍軍團啊！還有很多關於他們的知識待人發掘！\n\n如果你願意把在巨龍群島各處找到的泰坦文物帶來給我，我會對沃卓肯協調者說你的好話。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n泰坦文物"}
MultiLanguageQuestData['tw'][70840] = {title = "泰坦文物", objective = "你找到泰坦文物了嗎？", description = nil, progress = "你找到泰坦文物了嗎？", completion = "太神奇了！這個文物保存非常良好。我要立刻開始研究它。\n\n十分感謝你的努力！我會記得我的承諾，對沃卓肯協調者稱讚你的。\n\n我剛剛講到哪了？對，這個很適合這裡…", rewards = nil}
MultiLanguageQuestData['tw'][70841] = {title = "更多泰坦文物", objective = "你今天帶了什麼來給我？", description = nil, progress = "你今天帶了什麼來給我？", completion = "你怎麼找到這麼多的？這是不折不扣的文物寶藏堆！你得找個時間跟我分享你的訣竅才行。\n\n你又讓我們對泰坦的理解大幅增加了。沃卓肯協調者對你的評價會很高的！", rewards = nil}
MultiLanguageQuestData['tw'][70842] = {title = "引爆地點", objective = "收集迷霧谷地圖。", description = "叛亂者應該有留下策劃未來攻擊的記錄。趁他們還沒開始下次的行動，我們必須找出他們想做什麼。\n\n在他們的營地搜索有標記的地圖，就像我們在沃卓肯找到的那張一樣。", progress = "你成功取得叛亂者的計畫了嗎？", completion = "我會通知大家，加強這些地點的安全措施。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70843] = {title = "毀掉符文石", objective = "摧毀炙燃符文石。", description = "<這個符文石和叛亂者想放在沃卓肯的那顆十分相似。\n\n雖然它尚未完成附魔，你卻看到遠處還藏有不少已經完成的符文石。\n\n要是你摧毀這些符文石，叛軍就沒辦法拿去別的地方使用。>", progress = nil, completion = "我在這裡都能感受到爆炸的衝擊。\n\n多虧有你的努力，沃卓肯現在變得更安全了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70845] = {title = "追隨提爾的腳步", objective = "在蒼藍高地找到提爾的第一個挑戰。", description = "守衛者提爾早已為所有可能發生的事情做好準備。他察覺未來有一天會需要為世界的工匠帶來助力，因此創造了創新引擎。它擁有創造出特殊物質的能力，使物品發揮出超越凡人能力的效用。\n\n為了確保他的引擎不會遭到濫用，他創造了我來觀察所有想獲得這股力量的人。唯有具備資格的人才有辦法使引擎解放出完整潛能。\n\n你配得上這個挑戰嗎？", progress = nil, completion = "&lt;雕像彷彿對你的存在做出回應一般，整個裝置開始緩緩地活動起來，就像活過來一樣。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70849] = {title = "這需要專家", objective = "前往甦醒海岸的野生保育區與漢妮可談話。", description = "魯賓斯現在好多了，但我認為他還需要一點協助。\n\n一陣子之前，我認識了一個超聰明的龍鱗遠征隊探險者，她叫做漢妮可，而且經常處理元龍的事。她也是名寵物訓練師。我敢說她可以幫魯賓斯更多忙！\n\n我想她當時要去甦醒海岸。我敢說你去那裡就能找到她。\n\n能幫上你的忙讓我很高興！\n\n<她開心地揮手>\n\n再見！祝你好運，魯賓斯。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70850] = {title = "瑪爾德菈遇到危機", objective = "從歐里昂‧暗水手中拯救瑪爾德菈。", description = "做得非常好。在你四處進行破壞的時候，我仔細偵察了這座營地，沒想到卻發現了我的老朋友瑪爾德菈‧焰舌。\n\n我知道她失蹤了，而且謠言說她加入了叛亂者。但是根據我的觀察，她是被俘虜了！\n\n我們不能把她留在這裡。從囚禁她的龍裔手中把她救出來！", progress = nil, completion = "你救了我的朋友，我欠你一個人情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70851] = {title = "生來更野", objective = "向漢妮可請教魯賓斯的需求。", description = "有很多資訊是你要知道的。我們好好談談，再來決定什麼方法對魯賓斯最有利。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n磨亮的寵物吊飾"}
MultiLanguageQuestData['tw'][70853] = {title = "魯賓斯的朋友", objective = "在甦醒海岸的野生保育區捕捉一隻膽小蜻蜓。", description = "就像我們之前講到的，魯賓斯需要兩個東西：搭擋和對戰。\n\n我想我們可以一次解決。\n\n這個地方是膽小蜻蜓的繁殖地。要是你稍微找一下，應該能找到一大堆。\n\n記住，你必須先削弱一番，才能用陷阱捕捉。\n\n捉到一隻後，就回來找我。對戰後，可能會受一點傷，不過我有一些戰鬥訓練石，所以馬上就能治好！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n飛行生物戰鬥訓練石磨亮的寵物吊飾"}
MultiLanguageQuestData['tw'][70854] = {title = "所以情況如何？", objective = "回去沃卓肯的幼鱗托育所找吉哈納。", description = "你做得非常好，<name>。魯賓斯狀況好多了，而且精神很好。\n\n吉哈納一定想知道，快點回去告訴她這個好消息！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n究極戰鬥訓練石嘟嘟先生"}
MultiLanguageQuestData['tw'][70856] = {title = "用火焰殺死它", objective = "用火焰槍火炬摧毀10個感染屍體。", description = "這些邪惡的蜘蛛會在屍體中下蛋。\n\n有時候甚至會找上活人。\n\n我們看過許多碎裂火焰軍的屍體都慘遭它們的毒手。\n\n如果我們想在這活下來並擊敗碎裂火焰軍的話，就不能讓那些蛋孵化。\n\n把這個火炬拿去。火炬裡灌注了空氣及火焰的力量。把它往你想放火的方向指，剩下的交給它就好。\n\n巨牙海民不會輕忽蜘蛛。我準備好才來的。", progress = nil, completion = "做得好。這樣我們就有些喘息空間了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70859] = {title = "守護者掌握之物", objective = "從腐化的守護者埃達維斯身上取回低語裂片。", description = "<class>，我很感謝你的協助。我是第一位發現這個神器瓦烏洛斯和碎裂火焰軍計畫的祈倫托法師。\n\n取回並研究這個似乎有知覺的強大法器是至關重要的事情，而且應該交由我來負責。\n\n碎裂火焰軍無所不用其極地在找它，不過我已經用魔法為我們找到一條路。\n\n這附近有位腐化的守護者，它擁有的魔法裂片和瓦烏洛斯有某種連結。我可以用它來找到神器其餘的部分。", progress = "你找到裂片了嗎？", completion = "把它給我！快點快點！\n\n你也有聽見低語嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70867] = {title = "逆鱗要塞", objective = "完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70871] = {title = "伊斯凱拉漁網", objective = "把材料帶給塔維歐，讓她製作一張伊斯凱拉漁網。", description = "看來你和村民相處得不錯。\n\n\n\n你說，你想要更了解我們的捕魚方法？那麼首先，沒有人會赤手捕魚。我可以幫你製作一張配得上伊斯凱拉族的堅固漁網。", progress = nil, completion = "這是你的伊斯凱拉漁網。好好使用它，除了你自己需要的量之外，不要再從生命循環中取走更多漁獲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70873] = {title = "追逐瀑布", objective = "收取35個落水微粒。", description = "真正的威脅在餘燼石洞中。他們就是在這裡刻蝕符文石，灌注洪荒火焰。\n\n你應該有看到擋住入口的烈焰牆。我無法消除那道牆，但應該還是幫得上忙。我相信只要使用落水微粒，就可以安全通過。\n\n去從附近的元素生物上收取水微粒。", progress = "我們需要那些微粒才能讓你安全進入餘燼石洞。", completion = "&lt;瑪爾德菈檢查了落水微粒。&gt;\n\n很好，這些應該就行了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70874] = {title = "突破火牆", objective = "接受瑪爾德菈的元素祝福。", description = "洞窟內的叛亂者都獲得了一道元素祝福，讓他們能夠安全通過烈焰牆。我也會賦予你相同的加持。\n\n不用擔心。我看過他們施展這個法術很多次，應該可以成功複製出來。", progress = nil, completion = "別擔心，那個濕濕冷冷的感覺只是暫時的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70875] = {title = "惡劣至極", objective = "在餘燼石洞殺死3個叛亂者和4個元素生物。", description = "餘燼石洞的叛亂者對洪荒使者抱有堅定不移的忠誠，因此是對沃卓肯最嚴重的威脅。\n\n消滅他們以及他們釋放的所有元素生物。", progress = nil, completion = "做得很好，&lt;name&gt;。\n\n我們不能讓那些追隨洪荒使者的人散播混亂及毀滅。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70876] = {title = "破壞法器", objective = "在餘燼石洞摧毀4個洪荒法器。", description = "如果瑪爾德菈所言屬實，叛軍正在餘燼石洞製造爆炸符文石。\n\n還有，考慮到這些東西的特性，製造過程中一定有用上洪荒使者的法器。\n\n摧毀那些法器。你看到的時候就會知道。\n\n不能再讓叛軍製造出更多的毀滅性武器。", progress = nil, completion = "少了那些法器，叛亂者就無法把易爆烈焰灌注到他們的符文石裡了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70877] = {title = "及時的呱呱聲", objective = "將被泡泡困住的小鴨子帶回生態學家的營地。", description = "<這隻小鴨子很沮喪，一邊無聲地呱呱叫，一邊害怕地環視四周。>\n\n<也許生態學家會知道如何幫助牠？>", progress = nil, completion = "謝謝你把黛西帶來給我們。目前已經找到兩隻了，一定還有更多，下次出去的時候記得張大眼睛找找。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70878] = {title = "火焰之環", objective = "保護瑪爾德菈‧焰舌，讓她可以封印洪荒使者傳送門。", description = "在餘燼石洞最深處的地方，洪荒使者建立了一個熾炎傳送門，藉此釋放出元素。\n\n我可以封印這個傳送門，但不管另一端是什麼，這一定會引發他們的憤怒，包括那些巨型熔岩。\n\n我會需要你的保護才有辦法阻止他們。", progress = nil, completion = "做得好，&lt;name&gt;！\n\n瑪爾德菈跟我說了你的英勇事蹟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70879] = {title = "回報叛亂者之事", objective = "在守護巨龍之座的頂層和卓萊恩隊長會面。", description = "我對你今天的成果很滿意。<name>，希望你的看法跟我一樣。\n\n我們成功阻止了這些和洪荒使者聯手的叛亂者策畫的邪惡活動。至少目前是如此。從今以後，我們會需要更密切地關注任何的異議。\n\n請盡速回去找卓萊恩隊長。她會想聽我們的完整報告。", progress = nil, completion = "&lt;name&gt;，歡迎回來。\n\n我的手下已經跟我彙報了好消息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][70880] = {title = "用精品烹飪", objective = "哈囉。要不要拿根叉子？還是喝點茶？\n\n看到沃卓肯有這麼多人真好。我相信你一定能好好地幫助我們。如果你需要刀子來搭配叉子，就跟我說吧，我們可以交易！", description = nil, progress = nil, completion = nil, rewards = "巨龍餐叉巨龍餐刀簡單的銀色龍酒杯簡單的金色龍酒杯您能選擇下列奬勵中的一個：\n\n龍獸茶具組"}
MultiLanguageQuestData['tw'][70881] = {title = "提爾的第四個挑戰：精明", objective = "在灌注迴廊從看守者伊力篤斯那取得能量核心，並擊敗洪荒海嘯。", description = "引擎就快要達到效能巔峰了。現在只需要能量核心，就能以更有效率的方式利用加進去的精華。\n\n提爾把這種裝置的知識留給了看守者伊力篤斯。到灌注迴廊去找他，他一定會幫上你的忙。", progress = "你找到看守者伊力篤斯了嗎？", completion = "或許守衛者提爾想要防範的就是這些秩序的敵人。至少失去看守者伊力篤斯對我們來說仍算是勝利。我們可以用他的能量核心來啟動引擎，這樣一部分的他就能以提爾的造物之姿永遠流傳。\n\n&lt;你發誓你看到仕女的臉上閃過一絲悲傷。&gt;", rewards = "您會收到：\n\n瓶裝精華"}
MultiLanguageQuestData['tw'][70882] = {title = "名望物資", objective = "你好，<class>。你已經向沃卓肯協調者證明了你的價值。希望這些物資可以幫到你，繼續實現我們的理念。請別讓我們失望！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n超大型沃卓肯協調者補給包小型沃卓肯協調者補給包"}
MultiLanguageQuestData['tw'][70883] = {title = "栽培之手", objective = "在同心花園尋找古爾佩奇。", description = "你好，凡人。我是替首席園丁古爾佩奇傳話的。他說花園現在一片混亂，但我不太確定那樣算不算不正常。\n\n他和我保證一切都在掌握之中，但其實他是說「都在鏟子掌握之中」。我不確定那是什麼意思，但我相信他一定能找到事情讓你做。請你去找他，他會給你足以應付情況的適當裝備。", progress = nil, completion = "園丁這項工作需要利器。讓我為你提供戰鬥的裝備吧。\n\n如果有需要的話，我還有更多用具可以和你交易，感激你幫忙開闢這片荒野！", rewards = "巨龍草藥園叉子巨龍草藥園鋤頭巨龍草藥園耙子巨龍草藥園手鏟巨龍草藥園鏟子"}
MultiLanguageQuestData['tw'][70884] = {title = "奪回來", objective = "您會學到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n攻打龍禍要塞"}
MultiLanguageQuestData['tw'][70885] = {title = "名望物資", objective = "你好，<class>。你已經向沃卓肯協調者證明了你的價值。希望這些物資可以幫到你，繼續實現我們的理念。請別讓我們失望！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n超大型沃卓肯協調者補給包小型沃卓肯協調者補給包"}
MultiLanguageQuestData['tw'][70887] = {title = "感受自由", objective = "我那些體型小的同胞現在也可以自由地探索巨龍群島。能看到他們繁榮起來並享受著新的體驗，我很開心。\n\n讓我來替你展示他們向你，還有他人表達自己的其他方法吧。", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n峭壁荒野飛龍：鎧甲眉毛峭壁荒野飛龍：分裂頭部犄角峭壁荒野飛龍：臉頰有尖刺峭壁荒野飛龍：深膚色版"}
MultiLanguageQuestData['tw'][70888] = {title = "與最優秀者並肩", objective = "日夜工作來為我們的部隊提供裝備可不是什麼輕鬆的事。這是艱鉅的工作，但我很喜歡。我也聽說你為我們的努力貢獻了一份心力。\n\n為了表達感謝，我希望你能收下一件護甲。就一件。如果你需要別件，你就得拿東西來跟我換了。\n\n請你快點挑。我還有工作要做！", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n黑色龍裔肩墊藍色龍裔肩墊青銅龍裔肩墊綠色龍裔肩墊紅色龍裔肩墊"}
MultiLanguageQuestData['tw'][70889] = {title = "精益求精", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n製作知識的筆記本"}
MultiLanguageQuestData['tw'][70891] = {title = "融入", objective = "如果你想要在這座城裡生活或工作，你就必須融入大家。\n\n我可以讓你訂作最新流行的服飾—甚至還可以選顏色！你覺得哪個軍團的顏色最能凸顯你的雙眼？\n\n如果你挑不出一件想要的，那當然可以討論多挑幾件，不過當然要拿東西來換！", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n套裝：赤紅沃卓肯服飾套裝：黑色沃卓肯服飾套裝：蒼藍沃卓肯服飾套裝：綠色沃卓肯服飾套裝：青銅沃卓肯服飾"}
MultiLanguageQuestData['tw'][70892] = {title = "手藝入門", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n製作知識的筆記本"}
MultiLanguageQuestData['tw'][70893] = {title = "集體盛宴", objective = "在集體盛宴進行5項工作。", description = "我們現在正在舉行集體盛宴！大家都會貢獻材料，並一起煮出最棒的湯。\n\n來加入我們吧！", progress = "你有機會看到盛宴真幸運。我們一天只做六或七次而已！", completion = "只要大家齊心合作，湯就會很好喝！\n\n等湯煮好的時候，你應該試喝看看！", rewards = "您會收到：\n\n充滿補給品的湯鍋"}
MultiLanguageQuestData['tw'][70895] = {title = "時尚地翱翔", objective = "啊，凡人。你的冒險事蹟正在城市裡四處流傳。你和你的飛龍盟友在空中翱翔時，所有的目光都聚焦在你身上！\n\n我們來深入談談龍類豐富多變的外觀吧。", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n峭壁荒野飛龍：四犄角下巴峭壁荒野飛龍：白色毛髮峭壁荒野飛龍：彎鉤犄角峭壁荒野飛龍：腿有尖刺峭壁荒野飛龍：綴鱗斑紋峭壁荒野飛龍：矛形尾巴"}
MultiLanguageQuestData['tw'][70896] = {title = "不浪費就吃穿不缺", objective = "我的主人怒西昂派我到大熔爐這裡。他要我協助你這種冒險者。\n\n我有些優質的腰帶可以和你交易。記得要讓我老闆知道我很認真負責，好嗎？", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][70897] = {title = "成年", objective = "你回來了。工作依然沒有減少。真要說起來，大家比以往更依賴我的技藝。\n\n所以說，你要呆站在那裡一整天，還是要選一個我打造的完美頭盔？對，我知道它們有多棒。\n\n你想要換其他東西嗎？如果你還沒準備好要交易，我就回去工作了。", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n黑曜龍獸頭盔鈷藍龍獸頭盔青銅龍獸頭盔翠綠龍獸頭盔赤紅龍獸頭盔"}
MultiLanguageQuestData['tw'][70899] = {title = "提爾的第五個挑戰：精妙", objective = "使伊力篤斯的能量核心和提爾堡的泰坦能量同調。", description = "正常取得能量核心的方式不是這樣子的，所以需要重新調整一下，才會和引擎的能量同調。提爾堡的居民共鳴頻率應該能讓核心再次發揮完整效能。\n\n雖然我不想再犧牲任何弟兄，我認為這是完成這項挑戰的唯一方法。", progress = nil, completion = "你順利完成了最後一個挑戰。雖然過程中有人犧牲，但我相信這是為了更遠大的利益。守衛者提爾注定要讓你成功。", rewards = "您會收到：\n\n瓶裝精華"}
MultiLanguageQuestData['tw'][70900] = {title = "更新引擎", objective = "將剛調整好的能量核心放進創新引擎內。", description = "提爾認為創新引擎對接下來的戰役來說是必要的。\n\n你已經證明自己具備資格，並克服了所有你面臨的挑戰。引擎現在可以完全發揮能力了。", progress = nil, completion = "&lt;安裝新的核心後，引擎散發出溫暖的能量&gt;", rewards = "您會學到：\n\n精華偵測器\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][70901] = {title = "生物收藏", objective = "你好，凡人。我照料著大地還有以地面為家的生物，甚至包含流浪的元龍幼龍。\n\n不幸的是這裡的元龍幼龍太多了，超出我可以好好照顧的數量。\n\n嗯，你似乎很負責任。你想要照顧元龍幼龍嗎？如果你之後想要找個夥伴…來當好夥伴，那就再來找我吧。", description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n小魔咬赤紅元龍幼龍"}
MultiLanguageQuestData['tw'][70902] = {title = "精益求精", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n製作知識的筆記本"}
MultiLanguageQuestData['tw'][70903] = {title = "掌握泰坦之力", objective = "在我們對抗洪荒使者的過程中，研究提爾堡和巨龍群島的泰坦文物相當關鍵。\n\n他們留下來的武器尤其重要。我最近發現了一大批庫存的武器，我要給你其中一把，來表揚你的努力。\n\n我記錄完發現以後，我很樂意把那些武器用來交易，不過要請你帶材料來給我，協助我的研究。", description = nil, progress = nil, completion = nil, rewards = "泰坦門衛護盾遠古泰坦短槍泰坦守衛者步兵劍泰坦看守者寬劍您能選擇下列奬勵中的一個：\n\n泰坦看守者權杖"}
MultiLanguageQuestData['tw'][70904] = {title = "用多樣性來豐富生活", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n高地飛龍：青銅鱗再生元龍：青銅鱗烈風迅疾龍：青銅鱗盤旋滑龍：青銅鱗"}
