MultiLanguageQuestData['tw'][71209] = {title = "平原的野獸", objective = "收下莉茲的韁繩。", description = "我想莉茲準備好要回去當平原的野獸了。雖然她很親近你和我，但我看得出來她很想回到野外。\n\n總有一天，等我成為風之賢者後，我要探索這片溫泉以外的世界。但是，我得先通過學徒的期中考！時間過得真快啊。\n\n我用你收集的羊毛做了鞍具和韁繩。莉茲會很樂意聽你命令的。\n\n請你帶她踏上各種冒險吧，$p。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n莉茲的韁繩"}
MultiLanguageQuestData['tw'][71210] = {title = "前往龍禍要塞！", objective = "前往甦醒海岸，加入黑曜流亡者的龍禍要塞攻城行動。", description = "<振翅靈獸在你掌心放下一個微微燒焦的紙條。>\n\n<name>，黑曜流亡者已經聽說了你的英勇事蹟。龍禍要塞是我們之前的家園，但那裡已經落入加拉登族的手中。我們不能就這樣屈服。和我們一起奪回我們的領地吧。\n\n- 首領", progress = "我們必須奪下要塞！", completion = "又贏了一場戰鬥，但戰爭還沒結束。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71212] = {title = "攻擊蕨皮", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][71219] = {title = "任性的道路守衛", objective = "找到道路守衛艾薇。", description = "看來，我們比較年輕的幾個道路守衛最近怠慢了他們的職責。\n\n道路守衛諾莉請我去關心她的妹妹艾薇，她就駐守在時光通道的入口處。顯然，她最近的表現稱不上令人滿意。\n\n如果你往東去的時候碰巧遇見了道路守衛艾薇，請向她提醒她的職責有多重要，並讓她知道她姐姐挺擔心她的。", progress = nil, completion = "喔，嚇死，是個旅行者。請原諒我，我現在是一團糟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71225] = {title = "吹過風中：拉扎斯特", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][71227] = {title = "空中挑戰", objective = "和一名青銅時空守衛者說話，來了解空中挑戰。", description = "<振翅靈獸興奮地拍動翅膀，在你的腳邊放下一張字條和一隻燒焦的老鼠。>\n\n乘龍者！你的飛行實力眾所皆知。在巨龍群島各地的空中挑戰中測試你的實力吧。\n\n和任意青銅時空守衛者說話，了解一下狀況吧。", progress = nil, completion = "又有挑戰者了嗎？歡迎你！\n\n空中挑戰是巨龍群島各處的計時賽道競賽。超越賽道時間來贏得排名。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71229] = {title = "平原的呼喚", objective = "在雍亞拉平原與哈達利可汗說話。", description = "<洛奇在你手上放了一個訊息。>\n\n<name>，艾拉格氏族聽聞了你的許多優良事蹟。我們誠摯邀請你認識我們氏族，學習彼此的文化。\n\n哈達利可汗", progress = nil, completion = "我們歡迎你的協助，乘龍者。營地這裡有很多事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71230] = {title = "巨牙海民捕魚裝備", objective = "在蒼藍高地的伊斯凱拉和塔維歐說話。", description = "又見面了，<name>。\n\n<洛威一邊觀望四周、一邊哼著歌。>\n\n喔，對了！塔維歐在幫我做新網子的時候說，她也可以幫你做一張。然後她也可以做其他的捕魚裝備，只要你把需要的材料帶去給她。\n\n你應該去找她談談。", progress = nil, completion = "我的家族是最厲害的漁網編織家和魚叉製作家。如果你把我需要的材料帶來給我，我就可以幫你製作新工具。", rewards = "您會學到：\n\n塔維歐製作捕魚裝備\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][71231] = {title = "獵者的呼喚", objective = "在雍亞拉平原和訓練師弗羅尊說話。", description = "<洛奇在你手上放下通知。>\n\n<name>，席卡氏族邀請你參加大狩獵。在雍亞拉平原和訓練師弗羅尊會面。", progress = nil, completion = "乘龍者！歡迎你在未來的狩獵中協助我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71232] = {title = "巨龍群島的名望", objective = "在沃卓肯與柯札魯交談。", description = "巨龍群島還有許多的事情要忙。\n\n我想請你去找柯札魯談談。他有比較詳細的情報，知道哪邊的人最需要幫助。", progress = nil, completion = "見到你真好，&lt;name&gt;。\n\n巨龍群島有許多獲取力量的來源，你只要知道要去哪找就行了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71233] = {title = "墜落之水", objective = "在蒼藍高地的三瀑布守望和維拉談話。", description = "我愛瀑布。\n\n想知道什麼比一座瀑布更棒嗎？\n\n兩座瀑布。\n\n而唯一一個比那更棒的東西就是…嗯，到西邊去看看三瀑布，你就會懂了！\n\n那裡的旅店老闆挺不錯的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71234] = {title = "望角新聞", objective = "前往蒼藍高地的捕鯨者望角。", description = "那邊的<race>。\n\n你看起來歷練豐富。\n\n我的表親瓦雲從捕鯨者望角帶漁獲來的時候，提到說一名…奇怪的傢伙在那裡紮營。\n\n那個人似乎很守規矩，但可以請你去看看瓦雲好不好嗎？\n\n他比較易怒。", progress = nil, completion = "又來一個人？\n\n太讚了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71235] = {title = "在現場調查的法師", objective = "在蒼藍高地的蠍尾飛狐危崖附近跟祈倫托法師確認狀況。", description = "<race>，Lok'tar。\n\n我們有兩名法師正在附近進行現場調查，如果你有時間的話，他們肯定可以用上你的協助。\n\n就算在最美好的時代，這裡仍是個危險的地方。\n\n更不用說現在連美好都稱不上。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71238] = {title = "晶紅盛宴！", objective = "在晶紅盛宴和主廚盧米雅史卓莎以及莫瑟說話。", description = "所有積極追尋美食的專家注意了！\n\n你是否渴望品嘗這世界最極致的美味？你在尋找機會來一場偉大探索嗎？你願意為完全不認識的人賭上性命和健康嗎？\n\n如果你是這樣的人，就來找絕頂傑出、世界知名的主廚雙人組：盧米雅史卓莎和莫瑟吧！他們目前正在沃卓肯主辦晶紅盛宴！", progress = nil, completion = "你是因為海報來的嗎？它們真的有用嗎？！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71239] = {title = "迷失在空中", objective = "在藍羽崖找到哈爾琳‧啾諷。", description = "我需要人幫忙，而你看起來像會幫忙的人。\n\n我的一個老朋友哈爾琳‧啾諷幾天之前應該在城裡和我碰面的。我們約好要一起在晶紅盛宴大吃特吃、找美容師剪髮，然後參觀他們那邊時髦的拍賣場。\n\n可是她沒出現。她常常工作到忘我，但要是能知道她在哪我會比較安心。\n\n到南邊的山區找找看吧。她有提過，她來這兒的時候會順便到那邊看一下。", progress = nil, completion = "老嘶軸在擔心我，是嗎？等我在這忙完後，我猜我得請她喝酒了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][71241] = {title = "鴨子、鴨子、陷阱", objective = "在原初山谷重置艾拉格氏族的狩獵陷阱。", description = "名叫原初山谷的樹林充滿了先代巨龍的魔法。那裡的一種蠍尾飛狐的皮毛在我的族人之間非常珍貴，但它們擅長躲藏，非常難找。\n\n你可以在那個地區找到一些我們的狩獵陷阱，不用親自去追蹤它們。使用附近水鳥的肉來重新設置它們…我會派我們氏族的人去收取陷阱捕到的獵物。", progress = nil, completion = "謝謝你。希望我們的氏族可以用捕獲的毛皮來貿易。", rewards = "您會收到：\n\n鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮束腕雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者肩衛龍鑄頭盔\n                            顯示 16 更多                        龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄披肩巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊擊聲天賜穿刺席卡刺矛喀拉希塑地手巨錘熔岩鍛造斬首者紋刻矛頭平原之息席卡女獵手的箭頭巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][71242] = {title = "支持風暴研究員", objective = "將元素溢流晶叢帶去給沃卓肯的研究員。\n\n已提供物品：\n", description = "這看起來像來自洪荒風暴的生物的溢流能量晶叢。\n\n在沃卓肯一定有研究員會想要這個的。", progress = nil, completion = "噢，太驚人了！這正是我們要找的東西，謝謝你。", rewards = "您會收到：\n\n元素溢流"}
