MultiLanguageQuestData['tw'][72155] = {title = "推廣附魔", objective = "為沃卓肯的索拉苟莎製作2把符文龍金節杖。", description = "阿爾蓋薩學院下了訂單，購買更多附魔棒。如果要準時交貨，我們需要每個人都努力趕工。你能助我們一臂之力嗎？", progress = "快點，我們沒時間了！", completion = "謝謝你，順利交貨後，學院一定很快就能培養出更多附魔師！\n\n來，研究這個。就算你是熟練的附魔師，還是有很多要學的。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][72156] = {title = "火熱的快遞", objective = "收集15個喚醒之火交給沃卓肯的『掘地者』瑟奇塔。", description = "熔爐正在冷卻！快點，你能幫我嗎？帶一些喚醒之火給我，說不定會有用！", progress = "熔爐的火快熄了，你拿到東西了嗎？", completion = "很好，很好！\n\n一定行得通。\n\n走的時候把我的田野筆記拿去吧。筆記裡面一定有你不知道的採礦知識可學。", rewards = "您會收到：\n\n採礦田野筆記"}
MultiLanguageQuestData['tw'][72157] = {title = "大地之重", objective = "收集15個喚醒之土交給沃卓肯的『掘地者』瑟奇塔。", description = "我手邊有張數百噸洪荒熔鑄合金的訂單，但我的喚醒之土快用完了。我知道這是強人所難，但我可以給你相應的報酬！", progress = "我的顧客快等不及了，你備好東西了嗎？", completion = "好極了，正是我需要的。\n\n請收下我以前的田野筆記。筆記裡面一定有你不知道的採礦知識可學。", rewards = "您會收到：\n\n採礦田野筆記"}
MultiLanguageQuestData['tw'][72158] = {title = "濃密歡樂送", objective = "採集2張濃密毛皮交給沃卓肯的『粗曠者』瑞拉索爾。", description = "我們身上的鱗片是蠻硬的，但是多一層保護並沒有什麼壞處。不過只有最扎實的毛皮可以拿來做我們的護甲，所以要收集起來也頗有挑戰性。你有這個本事嗎？\n\n我見過你的技術。去幫我們的店家收集一些毛皮吧。", progress = "只有最棒的東西我們才會拿來用。", completion = "啊！品質非常好。我沒有看錯人。", rewards = "您會收到：\n\n剝皮田野筆記"}
MultiLanguageQuestData['tw'][72159] = {title = "去鱗", objective = "採集2片閃鱗皮交給沃卓肯的『粗曠者』瑞拉索爾。", description = "鱗片有許多的用途。它們可以提供保護作用，但有時候也可以拿來當作反射的鏡面。事實上，我們許多高級的鏡子就是鱗片打磨的。\n\n而且這種鏡子的需求也很高。去幫我收集一些帶鱗的毛皮，我就跟你分享我工作的訣竅。", progress = "你找到我需要的東西了嗎？", completion = "啊，這些材料真是完美。你的技術讓我刮目相看。\n\n收下這些筆記，就跟我們說好的一樣。你應該可以學到一些新東西。", rewards = "您會收到：\n\n剝皮田野筆記"}
MultiLanguageQuestData['tw'][72166] = {title = "在戰鬥中證明", objective = "在隨機戰場中獲得榮譽值。", description = "你們凡人總是喜歡為了地盤爭個頭破血流，那就這樣吧。\n\n至少場面看起來還算有趣，我也樂在其中。我們來看看你到底如何「證明自己」。您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "霜鬃皮外衣霜鬃鍊甲外衣您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記\n\n您還會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n瑪莉希亞的寶物榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72167] = {title = "在戰爭中證明", objective = "在史詩戰場中獲得榮譽值。", description = "你渴望「真正的挑戰」，對嗎？那就來吧。我知道有些大規模的衝突就連我也無法輕鬆應付。\n\n我很好奇，你這次究竟會敗…還是勝。我們來看看你能不能向我證明你自己。", progress = nil, completion = "那好吧。看來我不得不承認我看錯你了，我有點吃驚，只有一點點。來，這是你應得的。", rewards = "霜鬃皮外衣霜鬃鍊甲外衣您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記\n\n您還會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n瑪莉希亞的寶物榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72168] = {title = "在練習戰中證明", objective = "在競技場練習戰中獲得榮譽值。", description = "你對自己的戰術能力很有自信，對吧？聽說，你們凡人之間會舉行小規模的練習戰。準備出戰，與旗鼓相當的對手一較高下。\n\n讓我們見識一下你的能耐，然後回來找我。", progress = nil, completion = "整個過程似乎相對精采。你可以收下這些。", rewards = "霜鬃皮外衣霜鬃鍊甲外衣您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記\n\n您還會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n瑪莉希亞的寶物榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72169] = {title = "在競技場中證明", objective = "在加入隊伍時，在競技場積分賽中獲得榮譽值。", description = "你真的很喜歡逞凶鬥狠，對嗎？告訴你一個好消息：我也一樣。像你這樣的戰鬥者在預定的場地中彼此一較高下。參賽並獲勝的話，就能贏得獎勵。\n\n讓我們見識一下你的能耐，然後回來找我。", progress = nil, completion = "你達成了為你設立的目標，那麼我也會信守承諾。", rewards = "霜鬃皮外衣霜鬃鍊甲外衣您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記\n\n您還會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n瑪莉希亞的寶物榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72170] = {title = "在團隊中證明", objective = "在積分戰場中獲得榮譽值。", description = "我很好奇，到底有多少凡人像你這樣無比熱愛衝突。聽說，有人會像你這樣加入預組的隊伍，相互抗衡。找幾個志同道合的凡人，一起迎接這次挑戰吧。\n\n讓我們見識一下你的能耐，然後回來找我。", progress = nil, completion = "真讓我驚訝，你居然成功了。我想這些是你應得的。", rewards = "霜鬃鍊甲外衣您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記\n\n您還會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n瑪莉希亞的寶物征服點數榮譽點數"}
MultiLanguageQuestData['tw'][72171] = {title = "在單人隨機中證明", objective = "完成12輪單人隨機玩家對玩家對戰。", description = "你迫不及待地自行追求衝突，這行為取悅了我。要是你對自己的實力這麼有信心，那就讓我親眼見證，順便找點樂子。\n\n我們來見識一下你的能耐，然後回來找我。", progress = nil, completion = "看來你過去的訓練已經開始出現成效。你可以收下這些。", rewards = "霜鬃皮外衣霜鬃鍊甲外衣您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記\n\n您還會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n瑪莉希亞的寶物榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72172] = {title = "精華、裂片和炫彩之塵", objective = "為沃卓肯的索拉苟莎製作10份炫彩之塵。", description = "我們一直很缺基本材料。精華、裂片…而我們的炫彩之塵庫存更是永遠嚴重不足。\n\n如果你不介意幫助我們，也許我們可以增加庫存量，最好能連續一個星期都不用補貨，而不是一天就用完。", progress = "我們當天的炫彩之塵已經用完了！你有弄好的嗎？", completion = "謝謝你，我相信這次能稍微撐久一點了。\n\n來，有空的時候看看這個。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][72173] = {title = "附魔強化", objective = "為沃卓肯的索拉苟莎製作2份汲取之令。", description = "龍鱗遠征隊的裝備需要附魔。\n\n巨龍群島是個變化莫測的地方。所以他們想要升級護腕也是理所當然的。", progress = "龍鱗遠征隊等人幫忙附魔。", completion = "我會馬上把這些送去給龍鱗遠征隊。\n\n順便趁機增進你的附魔知識。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][72175] = {title = "美妙的權杖之爭", objective = "為沃卓肯的索拉苟莎製作3把奇觀權杖：火焰和3把奇觀權杖：空氣。", description = "這週有值得完成的訂單！阿爾蓋薩學院的學生一直在對這些有趣的權杖爭論不休。\n\n你何不贊助幾把權杖呢？", progress = "阿爾蓋薩的學生越來越躁動了。", completion = "太棒了！那些學生一定愛死這些東西了。\n\n順便趁機增進你的附魔知識。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][72189] = {title = "花園多樣性", objective = "與古爾佩奇交談。", description = "你喜歡蝴蝶花園嗎？\n\n你知道，這裡的南方有一個規模更大的花園。負責照料花園的是一個老龍獸，名叫古爾佩奇。\n\n他那裡一直很缺幫手。他有個「助手」，但我從沒真的見過他。我無法想像他能幫上多少忙。\n\n要是你到了那裡，一定要讓他知道是席娜派你去的。", progress = nil, completion = "喔，讚美泰坦，終於有幫手了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72190] = {title = "蓄水池保留區", objective = "找到祖提奇。", description = "<class>！我知道有人急需你的援助。\n\n提爾堡蓄水池剛剛遭受洪荒使者攻擊。我雖然幸運逃生，但其他人恐怕就沒那麼幸運。\n\n蓄水池就在這裡的北方。去找祖提奇，她能告訴你更多詳情。\n\n要是她還活著的話。", progress = nil, completion = "塔利卡成功逃生了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72192] = {title = "灌注迴廊：從無序到有序", objective = "進入灌注迴廊並擊敗洪荒海嘯。", description = "洪荒使者想讓元素混沌重現於世，而且為了達成目的，他們無所不用其極。\n\n我聽到一些令人不安的消息，指出他們已經潛入提爾堡地下深處的灌注迴廊。他們企圖干擾守衛者提爾設下的機制，實現他們的邪惡目的。\n\n求求你，<name>，你必須進入那些神聖的殿堂，終結洪荒使者的威脅。", progress = nil, completion = "&lt;name&gt;，多虧你的努力，灌注迴廊又重獲安全了。", rewards = "遠古角蛙肩甲蛙鳴之冠震地者鋼鐵面甲躍入深淵長袍您能選擇下列奬勵中的一個：\n\n霜升之環伊力篤斯碎片\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72193] = {title = "阿爾蓋薩學院", objective = "參觀阿爾蓋薩學院。", description = "我明白阿爾蓋薩學院打算重新向全世界開放它的大門。\n\n很久以前，這座學術聖地只對龍族開放。但是經過了這麼多年，院長也領悟到讓有志向學的人都有機會來此就讀的益處。而且她還要我多推薦一些有資質的新生來就讀。\n\n你是龍族的重要盟友，如果你願意來就讀將是我們的榮幸。要不要註冊入學就交由你決定，但是我相信朵拉苟莎一定會很樂意親自帶你參觀校園。", progress = nil, completion = "你在學校的第一天竟然就遇到了這麼多事情。還好你已經習慣了應付突發狀況。", rewards = "綴鱗之始肩甲可靠知識胸甲藥水污漬披風青銅挑戰者長袍晶紅角逐者手套您能選擇下列奬勵中的一個：\n\n白金星辰指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72240] = {title = "黑曜衛隊", objective = "把龍隊指揮官的命令傳達給德維希安以及黑曜衛隊。", description = "這位多蒂的熱情真是令人敬佩。希望這不會反過來害她對巨龍群島的危險視而不見。\n\n無論如何，黑曜衛隊會堅守職責，保護遠征隊。\n\n不過，我得先和怒西昂跟總指揮官談談接下來的任務。\n\n我的半龍人同胞正在探索這座城市。去找德維希安，她是我最可靠的副手，通知她我們要在碼頭集合。她會把我的命令轉達給其他的人。", progress = nil, completion = "很高興半龍人會跟我們一起走。\n\n我等不及要騎上野羽，挑戰龍隊指揮官看誰比較厲害。\n\n我的獅鷲獸肯定會飛得比他快！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72241] = {title = "來自過去的教訓", objective = "與龍隊指揮官安珀莎交談。", description = "我是安珀莎，半龍人的龍隊指揮官。在我們從漫長的靜滯中醒來後，怒西昂幫了我們，現在換我幫他了。\n\n你對我的族人和我們的歷史感到疑惑是理所當然的。直到最近，我也有相同的疑惑。\n\n但是『永恆之王』諾茲多姆揭露了半龍人失落的真相。他讓我看見了我們的起源…以及我們為何會被封印。\n\n讓我告訴你我所看見的一切。", progress = nil, completion = "你現在知道真相了。\n\n過去的就讓它過去吧。半龍人現在應該與艾澤拉斯的其他種族一起追尋新的未來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72242] = {title = "巨龍群島工程學", objective = "嗨，那邊的！歡迎來到巨龍群島！嘿，你似乎也同樣是個爆破藝術的愛好者，我給你看一些我在做的裝置如何啊？\n\n我可以把新的工程結構圖傳授給你！", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72243] = {title = "巨龍群島草藥學", objective = "歡迎來到巨龍群島，朋友！\n\n這片蒼翠的土地非常不一樣，而且十分美麗。當然，身為草藥師的你一定懂這點！\n\n你想要的話，我可以教你如何找到巨龍群島獨有的草藥。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72244] = {title = "巨龍群島銘文學", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72245] = {title = "巨龍群島鍊金術", objective = "歡迎來到巨龍群島！你似乎是個厲害的鍊金師，我之前學過龍族鍊金術，需要我教你幾招嗎？\n\n我可以把我知道的所有鍊金術知識教給你。然後你也可以探索群島。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72246] = {title = "安詳夢境", objective = "和水療中心主管交談。", description = "歡迎來到安詳夢境水療中心！\n\n非常抱歉。由於某些情況超出我們的控制，因此我們目前無法接待新顧客。\n\n請容我將你轉介給水療中心主管席安‧棘爪。他會負責解答你的所有疑問。", progress = nil, completion = "歡迎來到安詳夢境水療中心。你在這裡可以參加各種放鬆的活動！\n\n噢！你是來這幫忙的嗎？能得到你的協助是我的榮幸。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72247] = {title = "巨龍群島珠寶設計", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72249] = {title = "巨龍群島裁縫", objective = "<戴恩用批判的眼神打量你的服裝。>\n\n請讓我給你一些裁縫方面的指點。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72250] = {title = "巨龍群島烹飪", objective = "<大廚史塔克做出一連串跟烹飪有關的聲音和手勢。他的攪拌器不斷旋轉！他的爐灶燃起熊熊大火！他將煎鍋重重放下，發出一聲巨響！\n\n眾人對他的喝采響徹整間旅店。\n\n看著如此精采的烹飪秀，你神奇地發現自己的廚藝有所進步。>", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72251] = {title = "巨龍群島烹飪", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72252] = {title = "巨龍群島釣魚", objective = "來參加狩獵嗎？呃，我們要獵的是…魚？所以是獵魚？\n\n<丹妮爾不自然地咳嗽一聲，調整握竿方式。>\n\n對了，你似乎對釣魚有點研究。來吧，讓我教教你如何在這些群島釣魚吧。", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72253] = {title = "巨龍群島釣魚", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72254] = {title = "漁夫丁納克的鬼魂", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72256] = {title = "黑爪兵團", objective = "把龍隊指揮官的命令傳達給寇德西以及黑爪兵團。", description = "娜蕾迪亞非常熱情，但她是歷史學家、不是士兵。她不了解我們在巨龍群島會面臨的危險。\n\n也不是每個人都得擔心這種事情。畢竟，黑爪兵團會負責保護遠征隊。\n\n我要和厄比西昂以及你們的部落領袖討論任務調度的事情。\n\n我的副手寇德西正在和其他半龍人一起探索這座城市。麻煩你去通報他，我們要在飛艇高塔集合。他會把我的命令轉達給其他人。", progress = nil, completion = "很高興半龍人能和我們一起踏上這趟冒險長征。\n\n他們獨特的見解非常寶貴，而且進一步了解自己的歷史也能幫助他們面對自己現在的處境。\n\n就像我之前常說的，歷史會治療所有傷口。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72259] = {title = "牢獄文物", objective = "你找到別的文物了嗎？", description = nil, progress = "你找到別的文物了嗎？", completion = "只要你幫我帶來更多文物，我們就能越來越了解洪荒化身和他們的背景。\n\n我很感謝你。身為龍鱗遠征隊的成員，我希望你知道自己的貢獻有多麼重要。身為研究員，我想讓你知道，你為我帶來的文物讓我得到很多重大發現，實現了我一直以來的夢想。\n\n請你收下這些物資，並且善加利用。", rewards = "您會收到：\n\n巨龍群島補給品"}
MultiLanguageQuestData['tw'][72260] = {title = "牢獄文物", objective = "你找到更多文物了嗎？", description = nil, progress = "你找到更多文物了嗎？", completion = "再次謝謝你為我送來這麼多文物。\n\n我們對洪荒化身的研究之所以能成功，絕大部分都要歸功於你努力找到並捐贈文物。真的很感激你為龍鱗遠征隊所做的貢獻。\n\n請繼續為我們尋來更多文物！", rewards = "您會收到：\n\n巨龍群島補給品"}
MultiLanguageQuestData['tw'][72261] = {title = "不只是監牢？", objective = "將遠古牢獄文物交給莉莉安‧明月。", description = "<這個遠古文物的本質似乎偏向元素。沃卓肯的莉莉安‧明月或許能夠提供更多情報。>", progress = "你帶來可供我研究的東西了嗎？", completion = "洪荒化身被關押在牢獄中，但除此之外，我們對牢獄和其中的囚犯幾乎一無所知。\n\n像這樣的文物可以讓我們一窺他們的文化、歷史…以及實力。透過研究它們，我們可以佔據優勢，擊敗洪荒使者。幫我帶來更多文物，我會提供物資作為獎勵。\n\n對了，我會寫張字條給編目員潔可思，提醒她你幫了龍鱗遠征隊很多忙。", rewards = "您會收到：\n\n巨龍群島補給品"}
MultiLanguageQuestData['tw'][72263] = {title = "騎士精神不死", objective = "學習如何騎乘你的私人沃昆坐騎。", description = "喚能師！這個地方還是有成群的沃昆！\n\n我成功圍捕了幾隻，在你的翅膀累的時候可以當成坐騎。記得要怎麼騎嗎？\n\n這頭是分配給你的，因為龍隊指揮官一直叫你去各個地方。請你好好照顧它。", progress = nil, completion = "&lt;class&gt;！這個地方還是有成群的沃昆！\n\n我成功圍捕了幾隻，在你的翅膀累的時候可以當成坐騎。記得要怎麼騎嗎？\n\n這頭是分配給你的，因為龍隊指揮官一直叫你去各個地方。請你好好照顧它。", rewards = "您能選擇下列奬勵中的一個：\n\n赤紅沃昆碧藍沃昆黑曜沃昆青銅沃昆優秀騎兵的半龍人代幣\n\n您還會學到：\n\n初級騎術\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72266] = {title = "甦醒海岸", objective = "在甦醒海岸與仙卓克絲碰面。", description = "龍獸仙卓克絲在找人幫忙協助甦醒海岸所有的新來者。", progress = nil, completion = "噢，你好！我確實有個好點子，知道你可以做什麼來幫我們的忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72267] = {title = "雍亞拉平原", objective = "到晶紅鱗哨站與陶拉莎大使會面。", description = "綠龍軍團需要冒險者的援助。為了達成目標，你必須和平原的半人馬成為盟友。\n\n陶拉莎大使可以協助你。", progress = nil, completion = "你和我有許多事情要談。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72268] = {title = "蒼藍高地", objective = "在雍亞拉平原上和『智者』瑪蘇德說話。", description = "祈倫托會需要所有人的幫忙，來追蹤藍龍誓約石。\n\n有人看見他們的一些法師在雍亞拉平原尋求幫助。", progress = nil, completion = "啊，又來了一位冒險者！我們需要你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72269] = {title = "薩爪祖斯", objective = "前往沃卓肯，並與『生命守縛者』雅立史卓莎會面。", description = "『生命守縛者』雅立史卓莎安排了一場守護巨龍之座會議，要討論洪荒使者的威脅。\n\n她發出了呼籲，希望有意願的冒險者都去幫忙。", progress = nil, completion = "歡迎來到沃卓肯，&lt;name&gt;。我們開始吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72279] = {title = "巨龍群島補給品", objective = "你好，冒險者。請收下這些物資，在你為我們奔走的時候，提供一點幫助！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n小型伊斯凱拉補給包"}
MultiLanguageQuestData['tw'][72280] = {title = "巨龍群島補給品", objective = "歡迎啊，<race>。謝謝你持續幫助我們的村落和族人，我們又湊了一些物資要給你。祝你腳步穩當，收穫穩定。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大型伊斯凱拉補給包"}
MultiLanguageQuestData['tw'][72281] = {title = "巨龍群島補給品", objective = "<name>，我們又見面了。真高興你能平安回到我們這裡。你為伊斯凱拉提供了莫大的協助，為了表達我們的感激之情，請務必收下這些物資。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n滿溢伊斯凱拉補給包"}
MultiLanguageQuestData['tw'][72282] = {title = "名望物資", objective = "你好，<class>。你已經向沃卓肯協調者證明了你的價值。希望這些物資可以幫到你，繼續實現我們的理念。請別讓我們失望！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n小型沃卓肯協調者補給包"}
MultiLanguageQuestData['tw'][72283] = {title = "名望物資", objective = "沃卓肯協調者注意到了你接連戰勝洪荒使者的事蹟，<class>。他們決定好好報答你，並且希望你能再接再勵、繼續對抗洪荒使者。\n\n請收下這份更為豐厚的補給品時，善用它們來保衛巨龍群島！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大型沃卓肯協調者補給包"}
MultiLanguageQuestData['tw'][72284] = {title = "名望物資", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n滿溢沃卓肯協調者補給包"}
MultiLanguageQuestData['tw'][72291] = {title = "令人難忘的勝利故事", objective = "將你的勝利故事告訴伊斯凱拉的波雅長老。", description = "那是場不錯的戰鬥！\n\n伊斯凱拉的波雅長老會有興趣聽一聽那段勝利的故事。", progress = "最精采的故事可能發生在任何人身上。\n\n我們的所作所為塑造了我們，而我隨時都想多聽聽其他人的豐功偉業，並且讓其他人從中得到啟發。", completion = "什麼？你要說故事給我聽？快點坐下，我洗耳恭聽。\n\n&lt;波雅長老聆聽你戰勝強敵的來龍去脈。&gt;\n\n真讓人熱血沸騰！謝謝你跟我分享這個好故事，年輕人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72292] = {title = "令人嘆為觀止的勝利故事", objective = "將你的勝利故事告訴伊斯凱拉的波雅長老。", description = "那是場磅礡的戰鬥！\n\n伊斯凱拉的波雅長老會有興趣聽一聽那段令人印象深刻的勝利故事。", progress = "最精采的故事可能發生在任何人身上。尤其是那些無畏地深入敵穴的人…\n\n我們的所作所為塑造了我們，而我隨時都想多聽聽其他人的豐功偉業，並且讓其他人從中得到啟發。", completion = "喔，你要說故事給我聽？快點坐下，我洗耳恭聽。\n\n&lt;波雅長老聆聽你戰勝強敵的來龍去脈。&gt;\n\n真讓人熱血沸騰！謝謝你跟我分享這個好故事，年輕人。我會記住這一則故事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72293] = {title = "巨龍群島的冒險", objective = "檢視偵察地圖，選擇巨龍群島的一個地區來提供支援。", description = "噢，我知道你可以做什麼！\n\n龍鱗遠征隊在附近張貼了一張非常精美的巨龍群島地圖。\n\n要我說的話，他們的繪製十分精準和詳盡。抱歉，你來這不是為了聽藝術評論。\n\n你應該去瞧瞧那張地圖，看看巨龍群島的那些地區需要你的幫忙！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
