MultiLanguageQuestData['tw'][72396] = {title = "豐收之角", objective = "從巨龍群島的沃昆身上收集20個彈力號角，交給沃卓肯協調者的多瑟諾斯。", description = "我們的許多發明都仰賴堅固且有韌性的材料。幸好，沃昆角對我們的許多現代發明來說都是完美的製品。\n\n對我們來說更幸運的是，巨龍群島充滿了成群的沃昆。從沃昆身上收集一些彈力號角來給我們，對你來說應該是個簡單的任務。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][72397] = {title = "導覽介紹：龍鱗基地", objective = "在龍鱗基地認識重要的供應商。", description = "歡迎來到駐紮地，$p。\n\n我跟多蒂花了一番功夫才決定出建立營地的完美地點，但我非常滿意我們的選擇。\n\n這裡離遺跡和元龍繁殖地當然還有巨龍軍團都很近。\n\n何不花個幾分鐘探索一下營地，認識一下負責支援遠征隊的供應商呢？", progress = nil, completion = "你見過我爺爺了對吧？\n\n嗯，別全相信他的故事…他很喜歡吹噓家人的事！", rewards = nil}
MultiLanguageQuestData['tw'][72398] = {title = "岩石與石頭", objective = "從巨龍群島的土元素身上收集15份土靈樣本，交給莫魯克半人馬的杜瑞娥。", description = "巨龍群島的土元素是由不同的岩石及礦物組成。我們的鐵匠透過熔煉這樣的材料可以打造出獨特的工具，對此他們感到非常驚豔。其實，他們好像已經熔掉了最後一個樣本。\n\n我很不想破壞他們的樂趣。你介意幫忙補充庫存嗎？", progress = "你從元素生物身上收集到足夠的土靈樣本了嗎？", completion = "啊，鐵匠都會很滿意這些樣本的。", rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][72399] = {title = "隱士的花園", objective = "在暗影斷崖與薩瑞斯說話。", description = "我們的父母總是說，我們不應該到蓋利奇爾上面的花園去。他們認為園丁很兇又很危險。\n\n不過那才不是真的！他是有點難相處，但其實他人很好！\n\n自從洪荒使者出現後，我們就沒再上去過了。現在那裡太危險了。不過，我希望園丁沒事。因為我們現在不能去了，你可以去看看他好不好嗎？", progress = nil, completion = "你穿著那麼笨重的踏靴，最好別踩到我的植物。好了，你來找我有什麼企圖？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72405] = {title = "意外的線人", objective = "前往獅王之傲旅店的地下室跟馬迪亞斯‧肖爾碰面。", description = "<name>，這是個高機密任務。\n\n我們遭人闖入。\n\n要塞有個威力強大的歷史文物被人偷走了…目前情況看來，迪菲亞兄弟會可能是背後主謀。我們抓到其中一個竊賊，但是另外一個人逃走了。\n\n我有種不好的預感，<name>…直覺告訴我，整個事件還有隱情。\n\n我找來了一個…兄弟會事務的專家。到閃金鎮的獅王之傲旅店地下室跟我們碰面吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72406] = {title = "導覽介紹：沃卓肯", objective = "在沃卓肯認識重要的協調者供應商。", description = "歡迎來到沃卓肯，$p。我是烏納托斯，是沃卓肯協調者的名望守衛者。\n\n你對龍族的援助已經獲得認可，城裡各處的供應商已經獲得授權，要為你提供我們最精良的裝備。\n\n何不花點時間，去熟悉一下他們的位置和裝備呢？", progress = nil, completion = "我們代表沃卓肯協調者，而且我們都非常期待和你合作，&lt;name&gt;。", rewards = nil}
MultiLanguageQuestData['tw'][72407] = {title = "浸在成功之中", objective = "從巨龍群島的河獸身上收集18個防水皮革，交給伊斯凱拉巨牙海民的天納宇。", description = "我們部族的漁夫經常穿著浸濕的背包和長靴，十分使人困擾。最近，釣魚點出現了成群的河獸，帶來更大的混亂。\n\n河獸的皮革非常光滑又能防潑水。或許我們可以一次處理兩個問題。如果你可以幫忙處理數量過剩的河獸，把牠們的皮革帶回來，我們的漁夫會很高興的。", progress = "你找到能防水的皮革了嗎？", completion = "我很確信這些皮革會很好用，能保護我們的裝備不再被水弄壞。感謝你的協助。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][72408] = {title = "往事追憶", objective = "在閃金鎮的獅王之傲旅店下方與肖爾說話，了解龍火護符的歷史。", description = "關於這個部份，我相信凡妮莎的說法。我不認為她知道龍火護符是什麼。關於奧妮克希亞的故事，也只公開了一部分，仍有部分維持機密。\n\n說不定就連你也沒聽過。\n\n我會對你倆說明一切。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72409] = {title = "陳舊的記憶", objective = "前往燃燒平原的摩根的崗哨，與狼狽不堪的約翰交談。", description = "不管有什麼狀況，這都不是個好兆頭。要是那個龍女又使用力量腐化所有人，那可就糟了。\n\n不管是誰做的，他一定都對奧妮克希亞很了解。肖爾提過這件事情…雷吉納德‧溫德索爾。他是唯一對普瑞斯托女士起疑的人。嗯，也許他在燃燒平原的朋友會知道更多關於他的訊息。\n\n一定有人在幫她。如果我們能得到情報，揪出跟她密切往來的人，一定大有幫助。\n\n可以幫我去問看看嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72410] = {title = "鐮與尖針", objective = "從巨龍群島的鐮螳螂身上收集10個刺刺螯鉗，交給龍鱗遠征隊的諾克林‧異圈。", description = "我們最近裁縫用的針不太夠了。那些可惡的東西一直斷成兩半！\n\n這個地區的鐮螳螂身上的尖刺部位應該可以當成不錯的替代品。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][72411] = {title = "不須反叛也能達成使命", objective = "聽雅立史卓莎跟瑪爾德菈‧焰舌之間的對話。", description = "很高興再見到你，<name>！儘管你屢獲成功，雅立史卓莎還是不相信我們能透過武力有效阻止叛軍。\n\n為了找尋其他解決方案，雅立史卓莎找來了瑪爾德菈‧焰舌，希望她能跟我們分享關於叛軍的事情，以及她加入叛軍的動機。\n\n也許加入談話並聽聽瑪爾德菈的說法對我們會有幫助。為了避免叛軍眼線走漏消息，他們將在守護巨龍之座第二層，也就是我們下方會面。", progress = nil, completion = "我發現叛軍在沃卓肯的水道裡囤積了大量的炸彈！我們必須阻止他們！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72412] = {title = "爆炸性的中斷", objective = "跟艾里馬在鱗觀洞穴碰面。", description = "我成功潛入一個位在鱗觀洞穴的反抗軍營地。這個營地乍看之下沒什麼特別，但卻有貨車頻繁進出，且上面的貨物都是蓋住的。\n\n最後我終於在不引人注意的情況下，跑到貨車卸貨的地點去。我發現叛軍正在囤積炸彈，而且壞消息還在後頭！\n\n他們把炸彈通通堆在一個柱子旁，那柱子就在提爾堡正下方的水道裡。\n\n跟我在那裡碰面吧，我們必須想出阻止這一切的方法！", progress = nil, completion = "看來我們及時趕到，&lt;name&gt;…我們必須在水道被摧毀前阻止這一切！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72413] = {title = "無法調解的分歧", objective = "殺死煽動者佐拉雷克並取回引爆器。", description = "<name>，我不希望看到龍類同胞之間拔刀相向。我們應該是盟友，而非敵人。不幸的是，他們的領袖，也就是煽動者佐拉雷克，他威脅要摧毀水道，讓我們不得不做出這個決定。\n\n想辦法殺出一條路並抵達洞穴內部，然後在煽動者佐拉雷克引爆炸彈前，不計代價阻止他。接著把引爆器帶回來，確保它安全無虞。拿到引爆器後，誓鱗者就能幫我們安全地移除炸彈了。", progress = "你成功阻止佐拉雷克了嗎？水道安全嗎？", completion = "你阻止了佐拉雷克並取回了他的引爆器，為沃卓肯還有生命之池成功保全了水道。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72414] = {title = "了解囚犯！", objective = "使用瑪爾德菈的禁錮之戒來束縛8名反抗軍。", description = "要是雅立史卓莎真的想知道這場叛亂的起因，我們就需要質問反抗軍。\n\n因此，我們必須安全地抓住想殺死我們的…應該說是抓住想殺死你的反抗軍。這比使用暴力還要困難，而且也更加危險。\n\n不過，在我離開反抗軍時，我有類似的經驗。歐里昂‧暗水施放一種法術把我整個人束縛起來。法術很成功，而我也把它學起來了。\n\n我把那種法術灌注到一個戒指裡了，用它來安全地束縛反抗軍吧。總之，這應該有用啦！", progress = nil, completion = "這種方法比較困難，不過我們活捉的每個反抗軍都代表著一個終結暴力的機會，也是我們多救的一條命。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72415] = {title = "反抗軍激進文宣", objective = "收集5份反抗軍宣傳品。", description = "反抗軍在洞穴各處似乎貼有很多標語和傳單。他們大概是用這種手段來確保大家的目標一致，並也用來激勵大家戰鬥。\n\n少了穩定、連續的思想灌輸，要讓這麼大的群體為共同目標團結不是容易的事，更不用說他們的手段是轟炸市民或摧毀水源之類的惡行了。\n\n我們來大量收集他們的宣傳品吧。這些東西可以讓我們了解他們的想法，也可以知道是誰在灌輸這些想法。", progress = "你拿到他們不錯的手稿樣本了嗎？", completion = "看來這些大部分都是教唆者貝拉芬寫的，我還在反抗軍裡的時候見過她一次。只要我們找到她，或許就能阻止她煽動這樣的仇恨！\n\n我也可以研究這些文宣，看看有沒有從我當反抗軍時一路用到現在的暗號或密語，這樣我們就能了解更多資訊。做得好，&lt;name&gt;！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72416] = {title = "暫時居所", objective = "前往鋼崖壁壘。", description = "我們把反抗軍囚犯都送去鋼崖壁壘。沃卓肯的城市守衛 - 誓鱗 - 的兵營據點就在那裡。\n\n所以那裡有很多守衛，可以阻止他們作亂或逃跑。\n\n到那裡去，看看我們接下來該做什麼，才能徹底終止這場叛亂。", progress = nil, completion = "謝謝你到這裡來，&lt;name&gt;。我來是為了和囚犯討論，了解他們對龍族發起叛亂的原因。請你陪我一起去，聽聽他們會說什麼。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72417] = {title = "固執的歧見者", objective = "詢問5名龍類他們叛亂的原因。", description = "我的目標是用最不暴力的手段來終止這場叛亂。因此，我需要理解叛亂的根本成因。\n\n反抗軍顯然對守護巨龍和飛龍抱有不滿。雖然我們必須用武力來保護沃卓肯，這卻對終結叛亂沒有幫助。\n\n我希望你可以去和囚犯談話，問他們為什麼要叛亂。我會陪你一起去聽他們的答案。", progress = nil, completion = "我不完全認同他們的理由，也絕對不認同他們的暴力手段，不過，對於他們想要改革的原因，我有了新的理解。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72418] = {title = "徵詢意見", objective = "和雅立史卓莎討論反抗軍的怨言。", description = "保守來說，這些談話給我很多啟發。我們問話的反抗軍都有很多話要說，這點是我沒有料到的。\n\n我對這個情況有自己的看法，不過，你對他們的怨言有什麼想法？\n\n你不是巨龍也不是龍類，在這議題上有一定的客觀性。", progress = nil, completion = "我會考慮你的建議。&lt;name&gt;，再次感謝你的協助。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72419] = {title = "掃蕩懸崖叛軍", objective = "在反叛崖和瑪爾德菈與艾里馬會面。", description = "<name>！瑪爾德菈利用她在反抗軍時學會的暗語，仔細檢視了你拿回來的文宣。\n\n她發現了一個加密訊息，讓她找到了另一個營地，貝拉芬就在那裡，對所有願意聽的人煽動叛亂。\n\n瑪爾德菈和巡官艾里馬已經到那去了，去加入他們，或許我們終於會有辦法終止這場叛亂！", progress = nil, completion = "&lt;name&gt;，根據瑪爾德菈找到的暗語，反抗軍正在從鱗觀和其他地點前往這裡。現在反抗軍的數量已經太多，我們需要你的幫忙才能阻止貝拉芬。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72420] = {title = "危險調停", objective = "通知12名龍類雅立史卓莎要實施的改革。", description = "卓萊恩隊長通知我說，雅立史卓莎希望以最和平的方式來處理這件事。我也聽說，雅立史卓莎正在考慮賦予龍類更多權力，甚至是自由。\n\n既然和平就快要來臨，與其和這些反抗軍戰鬥，我們不如把消息散播出去！去跟這裡的龍類說，之後會有改革。或許有些人就會放下武器，選擇離開這地方。\n\n不過，有些人可能會堅持要反抗，你得對此做好戰鬥準備。", progress = nil, completion = "這麼多人選擇停戰真是太好了！真可惜還是有些人不願意，不過，要是你當初跟我說，這個叛軍營地中大部分的人都會放下武器，我當初一定不相信。雅立史卓莎會很高興的，&lt;name&gt;！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72421] = {title = "羽毛筆的力量", objective = "收集6支魔法羽毛筆", description = "<name>，我們必須阻止羽毛筆煽動反抗軍，這樣他們才有時間聽我們說話。\n\n他們的領袖貝拉芬似乎是用那把發光的法杖，讓那些羽毛筆可以自己動起來。盡量把它們都收集起來，讓它們沒辦法複寫她的話語。\n\n等它們停止書寫後，我們就可以直接和她對質 - 但是，我們可不希望那些羽毛筆四散各處，繼續散播這些訊息。", progress = nil, completion = "要是我們沒有把那些羽毛筆收集起來，它們會繼續煽動龍類，我們就會有更多反抗軍要對付。謝謝你阻止它們。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72422] = {title = "阻止謠言", objective = "擊敗教唆者貝拉芬。", description = "我知道了，<name>。貝拉芬就是散播謠言、煽動叛亂的主謀，只要能阻止她，這場叛亂就會結束。\n\n用我的戒指把她束縛住吧，不過你可能需要先削弱她的力量。如果她願意投降，我們會把她帶來見雅立史卓莎。\n\n我想，若她倆見面，群龍之后一定有很多不好聽的話要跟她說。", progress = nil, completion = "謝謝你，&lt;name&gt;。你在平息這次的叛亂中，從一開始就幫了很多忙。現在沃卓肯再次恢復了和平，而更重要的是，我會確保龍類獲得應得的尊敬和對待。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72423] = {title = "度過風暴", objective = "從巨龍群島的諾庫德半人馬身上收集12個暴風武裝，交給伊斯凱拉巨牙海民的天納宇。", description = "啊，你來得正是時候。聽說諾庫德半人馬的武器灌注了風暴附魔，變得十分強大而危險。我們想要拿幾件給我們的附魔師研究看看。\n\n至少，我們把敵人的武器作廢了，拿來做更好的用途。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][72424] = {title = "找個特定的東西", objective = "回到獅王之傲旅店的地下室去找肖爾。\n\n已提供物品：\n", description = "<狼狽不堪的約翰茫然抬頭，對你眨了眨眼。>\n\n是你打倒了那頭老座狼嗎？你大概是溫德索爾以外，我見過最強大的人類了。\n\n<狼狽不堪的約翰嘆了口氣。>\n\n…怎麼樣？還站在這裡幹什麼？快把你找到的東西交給一開始派你來的人吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72426] = {title = "克雷辛頓的新居", objective = "調查位於暮色森林烏鴉嶺的莊園。", description = "太好了，<name>。我們總算有個方向了。\n\n克雷辛頓伯爵是貴族成員，也是個高強的法師。自從安杜因大力打擊暴風城的貪污之後，他便陷入了困境。\n\n如果跟他有關我也不覺得意外。\n\n最近他在暮色森林買下了一座老莊園。我會透過我的人脈打聽一下，看看還能獲得什麼情報。你跟凡妮莎去那座莊園調查一番吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72427] = {title = "活化灌注", objective = "從巨龍群島的鞭笞者身上收集13份尖刺之葉，交給莫魯克半人馬的杜瑞娥。", description = "我今天有個簡單的任務要交給你。\n\n鍊金師現在缺少一種原料，是用來調製一種特別刁鑽的配方的。草藥的取得並不難。你只需要找凶狠的植物來採取樣本就好。你辦得到吧？", progress = "你把草藥取回來了嗎？", completion = "不是所有的狩獵都無比刺激。儘管如此，我們會好好使用你取回的樣本。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][72428] = {title = "角蛙囤積者", objective = "從巨龍群島的角蛙身上收集20個刺眼寶石，交給龍鱗遠征隊的諾克林‧異圈。", description = "這片土地的角蛙對寶石、珠寶和所有閃亮的東西十分癡迷，這不是什麼秘密。噢，我前幾天還在一些角蛙糞便中找到非常稀有的珠寶！\n\n嗯，這項任務可能稱不上吸引人，但角蛙似乎不只有收集貴重物品的習慣，甚至也會把它們吞掉。", progress = "你找到寶石了嗎？", completion = "呃…這些珠寶不太好聞…我們會趕緊清理乾淨。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][72429] = {title = "導覽介紹：莫魯凱", objective = "在莫魯凱與名望守衛者以及名望軍需官會面。", description = "<桑索克可汗比著手語，歐奇爾隨即為可汗發聲。>\n\n莫魯克這個民族並不會堅定地反對外來者，但我們確實需要潛在的盟友先證明他們的能耐。在你認識各氏族並協助我們的冒險之後，支持你的消息就會傳開。\n\n在山丘上的可魯塔較低的樓層中，你會找到大可汗瑪托拉的一位女兒，她可以協助你了解你在我們族人之間的定位。記得去自我介紹一下。", progress = nil, completion = "我很期待看到你會為莫魯克做出什麼貢獻。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72430] = {title = "月溪鎮的惡行", objective = "前往西部荒野的月溪鎮，跟凡妮莎和肖爾碰面。", description = "月溪鎮？克雷辛頓伯爵為什麼會在我的家鄉？\n\n這肯定不是什麼好事。我要通知肖爾。\n\n<凡妮莎朝塞西莉亞‧克雷辛頓瞥了一眼。>\n\n抓她當人質也許不錯。我們把那個有錢的女孩也帶走吧。\n\n在那裡跟我們會合。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72431] = {title = "飢餓的遺產", objective = "跟凡妮莎一起調查月溪鎮的迪菲亞盜賊巢穴。", description = "我已經很久沒回家了。\n\n情況不太對勁。我的同胞應該會在這裡才對。\n\n我要進去了…但我需要支援。\n\n…我不該離家這麼久的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72432] = {title = "這裡只有上等打手", objective = "在月溪鎮的迪菲亞盜賊巢穴殺死16個克雷辛頓侍從。", description = "我們才剛到，我父親的這些「侍從」竟馬上攻擊我們！\n\n這跟我小時候見過的那些友善侍從完全不同。這些傢伙是僱用來的殺手！\n\n如果我父親的計畫跟我猜想的一樣…我們不能讓他得逞。他們會把任何構成阻礙的人通通殺光。\n\n<塞西莉亞痛苦地皺眉。>\n\n不是你死就是我亡…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72434] = {title = "晶紅生命聖殿迴圈賽道", objective = "完成晶紅生命聖殿迴圈賽道。", description = "他們說我還不夠大，有些賽道還不能參加。\n\n但我依然可以看其他人參賽。你應該參賽的！這樣我就可以看你競速飛行。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72435] = {title = "導覽介紹：伊斯凱拉", objective = "去認識一些擁有寶貴裝備的商人。", description = "歡迎來到伊斯凱拉，朋友。\n\n你對抗蕨皮豺狼人的戰功已經在我們的人民之間傳遍了。你已經認識了許多我們的族人，也有更多人想要找機會和你交換知識與裝備。\n\n請你花點時間，把自己介紹給伊斯凱拉各處的友好居民吧。我們是個會互相支持的群體，就像你可以為我們做很多事一樣，相對的，我們的許多族人也可以為你做很多事情。", progress = nil, completion = "我希望你在伊斯凱拉待得愉快。\n\n你現在也知道，我們有很多是優秀的工匠和商人。我鼓勵你繼續到處詢問，了解我的族人們有哪些物品可以提供給你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72438] = {title = "塔拉賽克動機", objective = "從巨龍群島的塔拉賽克身上收集15個龍之卷軸，交給沃卓肯協調者的多瑟諾斯。", description = "在塔拉賽克接受洪荒使者的力量時，他們偷了許多古代卷軸及寶典，打算和他們新發現的魔法結合。我們需要人幫忙把這些卷軸取回來。", progress = "你拿回卷軸了嗎？", completion = "謝謝你幫我們找回這些寶貴的知識。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][72440] = {title = "銀色精神", objective = "在守護巨龍的協助下，前往提爾之墓。", description = "我想，白銀鱗片對我們應該還有點用處。在我觀察的時候，我感覺到裡面有種超越時間的…能量，似乎和提爾同調。它的結構也跟圓盤一樣。\n\n照理來說，我們應該可以用白銀鱗片來收集提爾沒有收進圓盤的記憶。\n\n雖然這聽起來很詭異，不過，到他在提里斯法的陵墓去，我們或許就能還原他的一部分。\n\n雅立史卓莎可以告訴你更多細節，$p。", progress = nil, completion = "這裡是紀念提爾的地方。我們必須懷著謹慎和崇敬的心情。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72442] = {title = "提爾的存在", objective = "保護看守者寇拉諾斯不受陵墓中的傀儡傷害。", description = "就像諾茲多姆可以感知到鱗片殘留的力量一樣，我在這裡可以感知到提爾。那力量就在這地方的一石一礫之中。\n\n我懷疑其他傀儡也可以感知到這股力量。它們一定是在提爾被重塑時來的。我們的方向是正確的。\n\n要是他還以某種形式留在這裡，有控制臺的輔助，鱗片應該會有辦法收集把它收集起來。我們收集提爾最後回憶的這件事，傀儡可能會解讀成我們想摧毀它們。\n\n如果它們醒來，別讓它們靠近。", progress = nil, completion = "這任務超出了老控制臺的負荷，不過我們的堅持得到了回報。\n\n鱗片收到了某種東西，不過我不確定到底是什麼。\n\n我現在只找到了「某種東西」，我…不太想就這樣回去見雅立史卓莎。控制臺失效可能會損壞鱗片裡的內容，又或者這內容也可能是我們需要的東西。\n\n說不定另一個控制臺可以檢驗它的內容？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72443] = {title = "提爾之殞", objective = "使用泰坦控制臺來見證提爾的最後記憶。", description = "我們可以用這個控制臺檢視鱗片的內容，但我不知道我們會看到什麼。\n\n這裡其他的泰坦僕從應該不會來打擾我們。存取它所造成的干擾不會像剛才傳輸我們對提爾的感應那麼大。\n\n不知道是甚麼東西讓崔瓦這麼不安。要提高警覺，$p。\n\n在你準備好要繼續時，將白銀鱗片放在控制臺上。", progress = nil, completion = "即使在他生命最後的時刻，仍展現出如此高貴的精神。扎卡茲利用龍族來嘲諷他…但提爾當時是否已經知道自己將遭到背叛？而現在的雅立史卓莎是否知情？\n\n這對他們會是一個沉重的打擊…\n\n如果我們無法復活提爾，或許這不是他們需要知道的事情。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72444] = {title = "白銀薄片", objective = "逃出陵墓，回去沃卓肯的提爾堡會見守護巨龍。", description = "提爾最後的記憶在我們手中。這是個必須謹慎看待的責任。\n\n我們把白銀鱗片拿去提爾堡給諾茲多姆吧。我們會試著用那裡的控制臺喚醒他。\n\n要是他完全恢復，我們會有很多事情要討論。", progress = nil, completion = "謝謝你，&lt;name&gt;。\n\n我…有點失望，白銀鱗片竟然不是我在找的答案。\n\n我們可能必須面對一個沒有提爾的未來。\n\n我仍對找到圓盤、復活提爾的計畫懷抱希望。我的內心深處相信，我們還是有機會靠自己的力量打敗恆龍和洪荒化身的。\n\n但有某些道路，儘管是黯淡無光的道路，是註定要踏上的。", rewards = "您會收到：\n\n泰坦隔離裝置龍石"}
MultiLanguageQuestData['tw'][72446] = {title = "他們是哪根筋不對？", objective = "守住北郡。", description = "真高興能再見到你，新兵。很遺憾我們是在這種狀況下重逢。\n\n雖然不知道這種「影響力」到底是什麼，但是原本大家只是有些小嫌隙，現在都開始覺得那是值得為此流血的深仇大恨！\n\n更別提那些迪菲亞強盜了！還有那些受雇的暴徒！考慮到現在的狀況，從暴風城派更多士兵來只會讓情況變得更混亂。\n\n據我所知，大部分的人只要挨一頓揍，就會恢復理智了。如果他們在清醒後還繼續與你為敵…那也只能採取必要手段了。這是他們的決定。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72447] = {title = "最大的威脅", objective = "在黑曜龍堡或熔渣泥沼擊殺兩個稀有敵人。", description = "強大的加拉登和其他生物都會威脅到黑曜龍堡和我軍團的安危。\n\n此事無法容忍。\n\n幫忙守住這座區域，找出並消滅兩個我方最強大的敵人。", progress = nil, completion = "做得好。你協助的意願我謹記在心…並十分感激。", rewards = "您會收到：\n\n耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮馬褲\n                            顯示 42 更多                        巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊擊聲天賜儀祭雍伊爾匕首諾庫德穿刺長戟莫魯克戰旗雍亞拉馴鷹者腰帶戰痕纍纍的鱗片血腥戰騎串刺銳牙魚叉長者的螢光長棍強化洞察短劍蒼藍秘法增幅器生命烈焰之瓶夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][72448] = {title = "保全我們的遺產", objective = "在黑曜龍堡或熔渣泥沼擊殺兩個精良敵人。", description = "我付出了這麼多、努力了這麼久可不是為了現在失去堡壘！\n\n很不幸的是，新的威脅出現了。我可以仰賴你的協助，讓你處理敵人嗎？\n\n幫忙守住這座區域，找出並消滅兩個最強大的敵人。", progress = nil, completion = "做得好！我就知道你靠得住，朋友。", rewards = "您會收到：\n\n\n\n等級 70–70耗盡的洪荒混沌鈷藍看守者法衣鈷藍看守者便鞋鈷藍看守者裹手鈷藍看守者風帽鈷藍看守者護腿鈷藍看守者之索鈷藍看守者腕輪巨獺毛皮涉靴巨獺毛皮之握巨獺毛皮頭盔巨獺毛皮馬褲\n                            顯示 51 更多                        巨獺毛皮束帶巨獺毛皮束腕雍亞拉馴鷹者鎖子甲雍亞拉馴鷹者行靴雍亞拉馴鷹者纏手雍亞拉馴鷹者罩盔雍亞拉馴鷹者護脛雍亞拉馴鷹者肩衛雍亞拉馴鷹者繫腰雍亞拉馴鷹者護腕龍鑄頭盔龍鑄胸甲龍鑄脛甲龍鑄護手龍鑄腿甲龍鑄披肩龍鑄束腰龍鑄臂鎧巨獺毛皮外衣巨獺毛皮肩冑鈷藍看守者肩墊龍鱗尖底盾擊聲天賜儀祭雍伊爾匕首喀拉希塑地手巨錘塑鋼師的黑曜錘靈巧戰戟諾庫德穿刺長戟灼熱蠍尾獅烙鐵莫魯克戰旗雍亞拉馴鷹者腰帶戰痕纍纍的鱗片騎兵衝鋒長槍血腥戰騎串刺翻騰的熔岩投擲手鬥棍精緻刮鱗小刀銳牙魚叉沉重的伊斯凱拉之錨巨牙海民領航員法杖長者的螢光長棍瘤刺弓強化洞察短劍永恆看守者軍刀蒼藍秘法增幅器夢幻稜鏡暗焰殘渣袋大型暗焰殘渣袋夢境微弱呢喃夢境明確呢喃覺醒岩石之翼覺醒晶紅之翼\n\n等級 69–70生命烈焰之瓶巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][72449] = {title = "別打了！", objective = "從侍從領袖身上收集4把屏障鑰匙。", description = "我們來得太遲了，<name>。\n\n克雷辛頓躲在修道院裡，他已經把護符的混亂之力擴散到整個北郡了！\n\n我想多數人應該已經失去判斷敵我的能力了。\n\n這個人看起來像是會為自己準備好退路的人。那些探員一定有辦法通過克雷辛頓設下的屏障。殺光他們，拿回任何有用的東西！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72450] = {title = "克雷辛頓的意志", objective = "面對北郡修道院內的克雷辛頓伯爵。", description = "我父親是個高強的法師，雖然我沒他那麼厲害，但還是從他那學來了幾招。\n\n我有看到你從那些執行者身上收集到的印記。我父親的私人房間也是用類似的魔法裝置上鎖，我記得那種裝置可以拆解成幾個較小的部件。\n\n我來把那些印記拼起來，做成一把秘能之鑰吧。這樣我們應該就能通過這屏障了。\n\n然後…我只希望我們能說服他別做傻事。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72451] = {title = "求生意志", objective = "取回龍火護符。", description = "…我想，事件終於落幕了。\n\n我還有很多問題想問他。但是他沒辦法承受那麼強大的力量。\n\n我們絕不能讓護符落入他人之手。<name>，把它拿好。我們會一起確保這東西安全回到暴風城。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72452] = {title = "願榮耀伴你同行，朋友", objective = "跟肖爾在暴風城的英雄谷見面。", description = "雖然一開始沒人料到這次的任務最後會變得如此艱難，不過你的表現非常出色，<name>。如果沒有你的幫忙會有什麼悲慘的後果，我想都不敢想。\n\n一段時間之前，國王要求製作一副護甲。一副只有偉大英雄才有資格穿上的護甲。\n\n你證明了自己值得如此榮耀…雖然你的貢獻遠遠不僅於此。\n\n跟我在英雄谷見面吧，<name>。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n雄獅傳承\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72453] = {title = "兄弟會的背叛", objective = "逃出迪菲亞盜賊巢穴。", description = "我早該猜到的。他們獲得特赦時，我就已經喪失對兄弟會的控制力了。有原則的人很久以前就走光了。\n\n現在，這裡只剩下一幫暴徒。鄧肯‧瑞斯朋一直都是這伙人裡面最兇殘的暴徒。\n\n<name>，我們該走了。如果有蠢蛋膽敢出手阻攔，我們會給他們好好上一課，讓他們知道絕對別跟范克里夫家的人作對。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72454] = {title = "黑曜雛龍", objective = "前往晶紅生命聖殿領取黑龍蛋，然後在黑曜誓言石將其孵化。", description = "有顆黑龍軍團的龍蛋已經可以孵化了。\n\n到晶紅生命聖殿去找育母艾莉昂，向她領取那顆龍蛋。然後，我要你把龍蛋帶到黑曜誓言石，在充滿黑龍軍團之力的地方將它孵化。\n\n成功孵化後，帶著雛龍回到這裡，交給我們進行後續照護。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72455] = {title = "溫暖又舒適", objective = "收集黑曜雛龍巢穴所需的東西。", description = "為了讓黑曜雛龍感到舒適，我們必須幫它打造溫暖的家。\n\n幫它們築巢的時候，需要使用黑曜龍堡的煤塊，確保巢穴溫暖和合宜。其次，文獻管理員艾錐斯可以幫你找到某個東西，讓他們與族人建立羈絆。\n\n我們也需要從扎拉萊克洞窟收集一些東西，畢竟黑龍過去的根據地就在那裡。洛姆一定有人可以幫上忙。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72456] = {title = "信任聖典", objective = "取回黑曜祖譜的書籍，並帶去給怒西昂和賽柏利安的軍需官。", description = "雖然已經守住了黑曜龍堡的上部堡壘，加拉登部隊依然持續在掠奪中庭。那個地區到處都是無價的歷史紀錄！我們必須盡快行動，保全黑龍軍團血脈的東西。\n\n怒西昂跟賽柏利安都想要這個資訊，所以你可以各為他們取得一本寶典，用來討好他們。\n\n前往堡壘的崩塌高塔。你應該會發現值得取回的東西。", progress = "你找到那些秘典了嗎？", completion = "太棒了！怒西昂跟賽柏利安一定會很滿意你這次的努力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72457] = {title = "家常菜", objective = "為黑曜幼龍準備燒烤鴨肉點心。此物品可透過烹飪專業技能製造，或從拍賣場購買。", description = "黑龍雛龍必須好好成長，才能長得既巨大又強壯。這裡的雛龍似乎太瘦小了，所以我認為她需要某個豐盛又營養的東西，協助她持續成長。\n\n烤鴨不只可以補充精力，還有助於大腦發育。我覺得非常適合當做雛龍的食物。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72458] = {title = "抓到了，換你當鬼", objective = "與黑曜雛龍一起玩耍。", description = "每隻幼龍都需要遊戲時間，好好發洩他們旺盛的精力。新生的黑曜雛龍也不例外。\n\n雛龍最喜歡玩鬼抓人。看看她會不會想跟你玩！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72459] = {title = "什麼是鴨鴨？", objective = "到原初山谷，與魯金歐那一起擊殺5隻藍嘴水鴨。", description = "老實跟你說，<name>。\n\n我們已經太久太久沒跟黑龍軍團打交道了，所以關於他們，我能對你說的也不多。我只知道他們是強大的戰士，勇敢地保護所有龍族。\n\n魯金歐那還很幼小，不過，我們也許應該看看她在戰鬥中的表現？帶她去雍亞拉平原，找那裡的鴨子練習一下。我們來看看她的能耐。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72460] = {title = "沉穩的寵物", objective = "為魯金歐那找隻寵物。", description = "我很擔心魯金。她變得超級焦躁，超沒安全感，幾乎任何風吹草動都會讓她嚇一跳！我從沒聽過黑龍居然會如此恐懼這個世界。\n\n我認為，如果要建立她的自信心，最好的做法就是幫她找個伴。這個夥伴必須非常沉穩，動作很慢，不會突然移動。\n\n黑龍軍團的職責是保護大地。也許小小的元素生物會很適合她。\n\n到沃卓肯的寵物店找莉辛卓談談，她應該有合適的寵物。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n伊吉\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72461] = {title = "鴨窺恐懼症", objective = "幫助魯金歐那和伊吉在寵物對戰中擊敗鴨子。", description = "<name>，時機成熟了。魯金歐那的新寵物「伊吉」很順利地幫她建立起自信心，我覺得她現在可以面對她最大的恐懼了。\n\n鴨子。\n\n甦醒海岸有個牛頭人很擅長透過寵物治療內心的創傷。我認為她正是我們需要的人。\n\n拉茲塔克和魯金歐那會在那裡跟你會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n魯金歐那龍石"}
MultiLanguageQuestData['tw'][72462] = {title = "需要治癒的人民", objective = "跟伊崔格一起前往奧特蘭克山谷，找德雷克塔爾討論獸人的未來。", description = "<name>，和平已經持續多年，但奇怪的是，我感覺自己時常躁動不安。雖然有部落跟兒子陪著我，我還是感到寂寞。你也有同感，對吧？我能從你的眼神看出來。許多獸人也有著一樣的眼神。\n\n雖然我們在艾澤拉斯已經落地生根，卻遺忘了獸人最原始的精神。我想或許是這樣吧。\n\n跟我來。我想找個老朋友談談這些煩惱，希望你能與我同行。", progress = nil, completion = "其實這次拜訪德雷克塔爾是用拜訪家人的名義低調進行，可能順便和杜洛卡談談他的未來。\n\n結果，我們討論出的決定卻可能會影響全體&lt;race&gt;的未來！\n\n別誤會，我認為這是當下的最佳做法，只是一切發生得太快，有點讓人不敢相信。我就要成為一名先知了…\n\n還有很多工作要完成，我們最好趕快開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72463] = {title = "戈加爾的仙人掌鮮果飲…", objective = "把一袋仙人掌果交給戈加爾。", description = "<年輕獸人有個遺願，想請人把這些仙人掌果交給戈加爾。\n\n你願意完成她的遺願嗎？>", progress = "噢，你好啊，<name>。你帶了什麼東西呀？", completion = "怎麼會是你把這些東西送來？我原本是要…\n\n噢不。\n\n我沒想到會有人因為這些東西而死！我才剛把這個任務交給所有年輕&lt;race&gt;去做呢！這應該很簡單才對！\n\n嗯…謝謝你為她把東西送來。把這些獎勵拿去吧…", rewards = "您能選擇下列奬勵中的一個：\n\n仙人掌鮮果飲\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72464] = {title = "克許哈格", objective = "前往剃刀嶺的克許哈格並進行榮耀儀式。", description = "克許哈格會在剃刀嶺舉行。在我們談話之際，高爾和伊崔格正在集結氏族。\n\n我們得先跟彼此告別了。你必須盡快為榮耀儀式做好心理準備。我的任務是確保它是值得一搏的挑戰，就連對你也是如此。\n\n我會找來蠍尾獅騎士，把我的家人送到克許哈格那裡去。你可以跟他們同行，或跟我們在那裡碰面。", progress = nil, completion = "你的榮耀儀式已經開始了。願魂靈為你指引勝利的道路。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72465] = {title = "大地祝福", objective = "找到雷霆山之靈並了解獲得大地祝福的方法。", description = "在獲得大地的祝福前，年輕獸人必須先學會尊敬我們四周無所不在的眾靈。如果我們無法跟身邊的元素和生命共存，災禍可能隨時降臨。\n\n我將呼喚眾靈，祂們會指引我們至需要你的協助的地方。是否要完成當前的任務，由你來決定。", progress = nil, completion = "仔細聽我說，年輕人。你的族人稱這裡為「雷霆山」，而我是這裡的守護靈。\n\n下方的峽谷，曾是個生機盎然的地方。如果你付出努力，峽谷也能再次充滿生機。\n\n幫助我吧，這對我的子民和你的族人都有好處。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72466] = {title = "雷霆山之靈", objective = "與雷霆山之靈合作，幫助區域恢復生機。", description = "只有維持微妙的平衡時，生命才能欣欣向榮。你的族人和人類到來時，造成了一連串效應，最後導致這裡成為荒寂之地。\n\n雖然錯不在你，但是你可以貢獻一份心力，幫助此地恢復昔日榮景。\n\n潛入水底，取回埋在淤泥中的種子。我的子民曾與遠古森林和諧共存，種子正是森林所留下的記憶。\n\n小心，這裡的元素有些躁動不安。", progress = "你回來了！你幫助了雷霆山之靈，對不對？", completion = "做得很好，&lt;name&gt;。風中的眾靈正唱著讚美你的頌歌。\n\n總有一天，雷霆山會長成一片新綠洲，造福奧格瑪的族人和雷霆蜥蜴。\n\n你已獲得大地祝福。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72467] = {title = "氏族祝福", objective = "在你的榮耀儀式儀式期間，選擇你要代表的氏族並為他們出戰。", description = "為了獲得氏族的祝福，年輕獸人必須學會氏族成員是其力量之源。對活著的獸人證明你的力量和價值吧。\n\n由於你不是生來就有所屬的氏族，你必須選擇一個想代表的氏族，並取得氏族酋長的認可。\n\n酋長已經齊聚在兵營內。加入一個氏族，並完成他們給予你的任務。", progress = nil, completion = "你已選擇你的道路。準備好繼續了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72474] = {title = "循線緝凶", objective = "從試煉谷居民身上打聽關於「長刀」戈克洛許的情報。", description = "「長刀」戈克洛許讓試煉谷居民人人自危，時間已經持續數週了。有許多獸人失蹤，還有很多年輕的受訓者受了傷。\n\n苦工們賦予這個神秘的兇手「長刀」的稱號，因為我們所能找到的少數幾具屍體有個共通點，就是背上都有極長且駭人的傷口，像是刀傷。他們嚇壞了，全都不願繼續工作！\n\n我們對戈克洛許的身份一無所知，只知道這傢伙非常危險。拜託了，請找出這個怪物，讓這場混亂到此為止吧！", progress = nil, completion = "有什麼發現？\n\n&lt;告訴卡爾圖克關於巨大三趾腳印的事情、卡倫尼夏提到的迅猛龍情報、苦工目擊者的說詞，以及有深層撕裂傷的屍體。&gt;\n\n所以…你是說戈克洛許其實是隻體型龐大的白色迅猛龍嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72475] = {title = "逼退戈克洛許", objective = "狩獵戈克洛許，並帶著殺死獵物的證據回到剃刀嶺。", description = "如果戈克洛許真的是頭迅猛龍，你應該可以像追蹤動物一樣找到牠的下落。\n\n看看你能否找到牠的足跡吧。牠最近都在這一帶活動，這點是肯定的。把牠逼回巢穴，然後跟牠做個了結吧！\n\n殺死牠後，別忘了直接回來剃刀嶺。先知會請你提供殺了牠的證據。\n\n謝謝你，<name>。願魂靈指引你的刀刃。不勝即亡！", progress = "你拿到戰利品了嗎？你有親手殺死敵人，然後把敵人的鮮血塗在臉上嗎？在做到這件事之前，你不會得到你的祝福。", completion = "&lt;阿格拉仔細檢查你臉上的血跡。看完之後，她滿意地點頭。&gt;\n\n殺得乾淨俐落。你守護了年輕族人和弱者，值得感到光榮。眾靈感到欣喜。\n\n你的努力換來了氏族的祝福。\n\n…你可以拿回自己的衣服了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72476] = {title = "先祖祝福", objective = "跟廚師托爾卡談話，了解更多關於製作祭品的事情。", description = "先祖祝福的意義在於教導年輕獸人，若沒有祖先的犧牲，也不會有現在的族人。我們必須使先祖感到光榮、尋求他們智慧的指引，並達成他們的期許。\n\n你的任務是為榮耀的逝者製作祭品，這個祭品不只必須要能配得上他們的地位，還要有資格在艾澤拉斯首場克許哈格儀式的祭品之石前擔當主角！你必須將全副心力投入製作過程，否則成品可能會不符標準。\n\n廚師托爾卡會指導你。先祖會看顧著這一切。", progress = nil, completion = "哇，你這樣的大英雄竟然會來向廚師托爾卡求救？\n\n好吧，但是你必須自己完成大部分的工作才行！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72477] = {title = "獸人雜貨店", objective = "從剃刀嶺的商人那裡獲取烹飪所需的食材。", description = "這裡面有份氏族傳統盛宴的食譜，是在克許哈格的先祖留下的。我們必須替換其中的部份食材，因為…你懂的，有些食材已經找不到了…\n\n但是修改後的食譜一定會更美味！我們會在這道傳統菜餚中加入來自艾澤拉斯的風味！\n\n我可以教你如何製作每道食譜的菜餚，但是你必須自己去收集食材和烹煮。各地的獸人商人都會來到剃刀嶺，所以你應該能在這裡找到所需的材料。", progress = "我們把清單上的東西都找來了嗎？托爾卡說，剃刀嶺應該有所有的材料！", completion = "我們把清單上的所有東西都找齊了！\n\n接下來呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72478] = {title = "榮譽和榮耀", objective = "享受盛宴吧！", description = "你成功完成了榮耀儀式！恭喜你，<name>。\n\n該好好慶祝一番了！我們為在場所有人準備了一場盛大的宴會，以示對你的敬意！\n\n去吧，為你獲得的榮耀狂歡吧。請好好享受。如果有獸人膽敢冒犯你，告訴他，你可是被選中完成新儀式的第一人！", progress = nil, completion = "是的，我認為慶祝該告一段落了。狂歡過頭可就不好了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72479] = {title = "祝福你與你的同伴", objective = "在會場觀禮，直到克許哈格儀式正式結束。", description = "這場克許哈格舉辦得非常成功，這全都是你的功勞，<name>。\n\n現在只等阿格拉完成儀式，然後正式宣告慶典結束了。\n\n我想在我們再次四散各地前，跟大家說幾句話…我很久以前就想跟大家談談這些事情了。", progress = nil, completion = "&lt;name&gt;，我們一族迎來了新時代。\n\n把你找來加入我那老傻瓜的遠征隊時，我從沒想過最後會有這樣讓人驚喜的結局。\n\n我們為你量身打造了這副護甲。這完完全全是你應得的。\n\n向你致敬，&lt;name&gt;，&lt;race&gt;的勇士！", rewards = "您會學到：\n\n德拉諾傳承\n\n您還會收到：\n\n氏族旌旗"}
MultiLanguageQuestData['tw'][72481] = {title = "甦醒海岸巡迴賽", objective = "在甦醒海岸的每個競速賽道飛行。", description = "騎乘飛龍最刺激的活動是什麼？當然是飛龍競速！\n\n我的青銅龍同伴已經在巨龍群島各處規劃了不同的競速賽道。這裡的地形景觀真是多變又豐富，彷彿在求人用最高速度飛越一樣。\n\n如果你碰巧經過我們在甦醒海岸的競速賽道，何不順道試試看呢？", progress = nil, completion = "做得好。和我預期的一樣，你對飛龍競速的掌握進步地很快。\n\n這些都還只是開胃菜而已。接下來是雍亞拉平原！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72482] = {title = "甦醒海岸進階巡迴賽", objective = "在甦醒海岸的每個進階版賽道飛行。", description = "既然你已經飛過巨龍群島各處的基礎賽道並證明你的實力，要不要試試新挑戰啊？\n\n進階版賽道和你飛過的標準賽道很類似，但大部分都有經過調整的飛行路線或額外的障礙物，更能考驗你的飛行技巧。\n\n我們就從甦醒海岸的進階版賽道開始吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72483] = {title = "雍亞拉平原巡迴賽", objective = "在雍亞拉平原的每個競速賽道飛行。", description = "啊，雍亞拉平原。寬闊的開放空間、強勁的風勢、一望無際的美景…以及更多競速賽道！\n\n就和甦醒海岸一樣，如果你找到我的青銅龍同伴，就和他們談談體驗競速賽道的事情吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72484] = {title = "雍亞拉平原進階巡迴賽", objective = "在雍亞拉平原的每個進階版賽道飛行。", description = "進階的賽道會更有挑戰性，但我相信你會有辦法應付的！\n\n我的青銅龍同伴已經在雍亞拉平原安排好進階版賽道，飛行途中會出現障礙物和一些小驚喜。然後你也可以挑戰打破你自己的最佳紀錄！\n\n祝你好運！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72485] = {title = "蒼藍高地巡迴賽", objective = "在蒼藍高地的每個競速賽道飛行。", description = "蒼藍高地的賽道是極為獨特的體驗。有高聳的山峰，連綿的雪地和茂密的森林，形成各式各樣的障礙與挑戰！\n\n當你在蒼藍高地的時候，別忘了去找我的青銅龍同伴，試試他們規劃的賽道！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72486] = {title = "蒼藍高地進階巡迴賽", objective = "在蒼藍高地的每個進階版賽道飛行。", description = "蒼藍高地的進階版賽道旨在把你的飛龍騎術技巧磨練到全新的高度。\n\n只要…小心別從那麼高的地方摔下來！\n\n等你準備好就去找我的青銅龍夥伴，在這些賽道盡興飛翔吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72487] = {title = "薩爪祖斯巡迴賽", objective = "在薩爪祖斯的每個競速賽道飛行。", description = "薩爪祖斯！守護巨龍之座的所在之地，龍族歷史的重要舞台。\n\n同時也有許多高聳的山峰及深險的溝壑給你飛越！\n\n像之前一樣，在你四處探索的時候，我的青銅龍同事已經設置了競速賽道。\n\n何不試試這些賽道，讓你的巡迴賽資歷更加完整呢？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72488] = {title = "薩爪祖斯進階巡迴賽", objective = "在薩爪祖斯的每個進階版賽道飛行。", description = "又輪到薩爪祖斯了！其中的山峰、低谷與賽道都已經準備好，等著你前去競速。\n\n去找我的青銅龍同事，在進階版賽道飛行，完成你巨龍群島巡迴賽的壯舉！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72510] = {title = "禁忌之境 1/1", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72512] = {title = "低語微風", objective = "在雍亞拉棲息地靠近雍亞拉。", description = "<戈多洛托疑惑地歪著頭、朝你點了個頭，然後終於正眼注視著你。但是一會兒之後，她又把目光移向天際…以及莫魯凱旁邊的山峰。你感覺她希望你前往雍亞拉棲息地。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n雍亞拉的神聖之吻"}
MultiLanguageQuestData['tw'][72513] = {title = "我們的命運", objective = "到至高育所與龍隊指揮官安珀莎交談。", description = "喚能師！你最近可能有種異樣的感覺。\n\n我和厄比西昂已經開始開始解除從半龍人身上抽取黑龍軍團精華的遠古虹吸裝置。我在想，或許只有像你這樣訓練有素的喚能師，才能感覺到這個變化。\n\n還有一件事要請你幫忙，來禁忌之境的至高育所找我和厄比西昂。我們需要解救一條龍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72514] = {title = "至高育所", objective = "破壞4個精華收集器。", description = "你感覺到了嗎？\n\n屏障開始漸漸被我們削弱。這座囚禁艾達曼希亞的牢籠中封印著極龐大的力量…\n\n現在我又能使用強化能力了！訓練有素的喚能師不只具備治療和毀滅能力，也能對盟友進行強化。我終於想起來了…除此之外…\n\n我也開始想起這條被囚禁的黑龍是誰…還有她對所有半龍人的意義…\n\n拜託，$p，請幫我移除這些束縛。", progress = nil, completion = "做得好。我們需要厄比西昂來幫忙瓦解這個囚禁魔法的最後一道防線。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72519] = {title = "時間兩調", objective = "在亞茲莫洛斯對克羅米及伊特努斯使用時空水晶，阻止他們繼續墜落穿梭時空。", description = "我知道了…他們墜落時不僅穿越時間，也穿越許多可能性。\n\n快點，我已經定位出時間線中的另一個點，我們有可能趕上他們。那地方…很不尋常，但是，別讓這個世界的古怪現象耽誤了你的行動。克羅諾穆的命運就掌握在你的手中。", progress = nil, completion = "這個過程尚未完成，但我現在可以更精準追蹤克羅諾穆了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72524] = {title = "基礎攀岩裝備", objective = "使用遠征補給工具組來研究攀岩裝備。", description = "<探路者傑布指了指他身旁的補給工具組。>\n\n你會需要補給品才能在外頭生存。\n\n我給你一些攀爬會需要的用具吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72525] = {title = "基礎編目裝備", objective = "使用遠征補給工具組來研究編目裝備。", description = "每個遠征隊記錄員都值得擁有自己的相機！\n\n你不需要幫你的相機取特別的名字，但我非常建議這麼做。這樣更好玩。\n\n總之，探路者傑布應該可以給你所有需要的工具。\n\n我還沒遇過什麼我需要、但他沒帶的東西。他超厲害的！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72526] = {title = "守護者之憩", objective = "逃到黑暗道路去。", description = "我並不樂見其他提爾的造物毀壞。他們費了很大的努力，讓這個陵墓不至於崩塌。可是，在少了提爾剩餘的聖光之後，這地方就會凋零。\n\n<寇拉諾斯指了指白銀鱗片。>\n\n我希望鱗片裡的東西值得用他們的毀滅來換取。我們去找另一個控制臺，看看鱗片裡面有什麼東西。", progress = nil, completion = "我們暫時安全了，但不該久留。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72527] = {title = "沒有什麼「運氣不好」", objective = "去藏寶海灣的「剝你的皮」找布里克雷茲‧古斯提。", description = "聽好，不管你信不信，我來群島只是為了把某些事情做個了結。我最近很不順，還不幸欠了大財主錢。大家都不敢欠他錢太久，如果我還不了錢，他一定會找到我，然後把我的皮給剝了。\n\n我把他的錢投資在魔法水晶上，結果在那天藏寶海灣日報的頭版登出後，魔法水晶的市場價格竟然崩跌了。而且…那批水晶竟然在運送途中搞丟了！\n\n冥冥之中一定有人在搞鬼，想置我於死地。也許古斯提家的人會願意幫我一把。", progress = nil, completion = "…我想，要別人免費幫我，是有點天真了。問布里克雷茲開價多少吧。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72528] = {title = "重生育籃", objective = "在巨龍群島各處從團隊內容收集重生微粒。", description = "重生育籃是個強大的神器，能夠大幅強化你的戰力。\n\n在你和盟友一同奮戰、對抗危害這片土地的重大威脅時，把你發現的重生微粒帶回來。我們需要它才能啟動重生育籃，為你的裝備灌注提爾的智慧與力量。", progress = nil, completion = "啊！這麼多優秀的點子和想法！好多事已經改變了，也有很多事沒變。", rewards = "您會收到：\n\n新生生命之血"}
MultiLanguageQuestData['tw'][72529] = {title = "情報就是王道", objective = "去加尼祿哨站收集3張鱷魚皮，或是給布里克雷茲‧古斯提金幣。", description = "情報可不便宜。這一點澤羅斯自己應該最清楚。\n\n有人在加尼祿哨站附近發現鱷魚，他們認為很危險。你知道我怎麼想嗎？那些都是白花花的錢呀！把那些珍貴的皮革收集來給我，也許我會突然想起澤羅斯那些水晶的重要情報呢。\n\n如果你覺得太危險，我也接受其他支付方式。你知道的，就是最常見的那種方式。\n\n<布里克雷茲雙手抱胸，滿心期待地等著。>", progress = nil, completion = "嗯哼，這樣就行了！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72530] = {title = "不管怎樣，先賄賂再說", objective = "用這些黃金賄賂亞提僱用的保鏢，然後前往蠻荒海岸與勘探者亞提對質。", description = "那狡猾的老騙子！我跟亞提已經白紙黑字簽好合約，要他幫我促銷那些水晶的。一定是有人用更高價的合約挖角他。\n\n亞提每隔一段時間就會去風險投資公司在海岸邊的工作區域視察。他有自己的隨身護衛，但是在藏寶海灣，沒有人是黃金不能買通的。\n\n把我最後剩下的一點黃金拿去吧。到油井那裡去賄賂他的護衛，讓他們睜一隻眼閉一隻眼，這樣你就能跟亞提對質了。", progress = "這些已經是我所有的黃金了。如果你想自己加碼讓對方難以拒絕，請自便。", completion = "你說海盜？！當然，我們知道該去哪裡。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72532] = {title = "錢、錢、錢！", objective = "從南野人海岸的格拉布‧雷德卡及其海盜同夥身上收集1500枚金幣。", description = "格拉布‧雷德卡和他的船員只要有錢，什麼壞事都做得出來，也因此惡名昭彰。\n\n他們的船上一定藏著寶藏。就算船上沒有寶藏，他們的口袋裡也一定藏著黃金。雖然會有點麻煩，但你願意幫我收集那些黃金嗎？\n\n你要怎麼審問他們都可以，我不會過問，但是可別殺了他們！我今天正在努力別開殺戒。", progress = "也該是教訓那些海盜的時候了。讓他們知道這樣隨便威脅人，總有一天會踢到鐵板。", completion = "我的天呀，這真是一大筆錢。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72533] = {title = "水晶大亨", objective = "前往南野人海岸，把格拉布‧雷德卡船上的寶藏拿回來。", description = "格拉布‧雷德卡。<澤羅斯啐了口唾沫。>一個沒風度、輸不起又可悲的傢伙。自以為體型壯碩就很猛。看到我這樣一隻地精賺的錢比他多，他一定恨得牙癢癢。\n\n信不信由你，但我在拍賣場從來都是童叟無欺。跟他相比，我簡直是個聖人。\n\n所以說，格拉布把我的水晶給賣了，對不對？然後買通亞提要他別說出真相，這樣一來就不會有人去找那批水晶了。計畫得真周全呀。\n\n格拉布的船上一定有什麼值錢的東西吧。去把船仔細搜過一遍，把所有值錢的玩意都拿走。", progress = "請快一點…關於我鱗片的事，大財主可不是開玩笑的。你也知道，我是頭龍，而龍鱗確實很值錢。", completion = "你帶了什麼回來？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72534] = {title = "與大財主達成協議", objective = "把寶藏給大財主里維加茲。", description = "哈…！你回來的正是時候。要是晚到一分鐘，你見到的可能就是被剝皮的龍了。\n\n把寶藏給他，快。", progress = nil, completion = "賽諾苟斯！你救了我一命。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72545] = {title = "育所的陣亡將士", objective = "在失落圖書室中，收集泰索司的犄角璽戒、亞洛希的犄角璽戒、艾可拉蒂的犄角璽戒和赫敏的犄角璽戒。", description = "$p，是我的錯。\n\n是我帶這些半龍人到這裡來的。他們知道有死亡風險，但是他們也相信我會支援他們。\n\n我應該在那裡掃蕩廢墟的敵人，不該在這裡翻閱書籍才對。\n\n<安珀莎握緊雙拳。>\n\n我希望你可以幫我拿回他們的犄角璽戒，我們得讓他們走得光榮。", progress = "嗯？抱歉。我剛才…有些心不在焉。", completion = "&lt;安珀莎向你鄭重地點頭致意。&gt;\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][72546] = {title = "學術援助", objective = "跟索諾瓦‧雪山在塞隆崗哨碰面。\n\n已提供物品：\n", description = "<name>！我的冬毛熊怪方言研究獲得重大突破。你幫了我這麼大的忙，我想跟你分享這項成果。\n\n跟我在塞隆崗哨碰面吧，到時我再跟你詳細說明。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72547] = {title = "學術收穫", objective = "從蒼藍高地的洪荒使者身上取回熊怪文物。", description = "我會上去村莊那裡，告訴他們這個壞消息…至少試試看吧。冬毛語真的是個很難學的方言。\n\n我想請你找一些熊怪字跡來給我，這樣我才有希望跟他們順利溝通。\n\n洪荒使者已經消滅高地區域所剩無幾的熊怪，或已經讓他們歸化。去找洪荒使者，不管用什麼手段，把落入他們手中的文物拿回來吧。\n\n我至少需要五個，但文物數量越多越好，我會把我學會的都教給你。", progress = "你有找到要給我的東西嗎？", completion = "這是個很不錯的開始，&lt;name&gt;。\n\n不過要到能對話的程度，我還需要很多個！", rewards = "您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72552] = {title = "一起收集", objective = "為長老馬茲收集8個塊莖。", description = "我是第一次聽到外人說我們的語言。你的腔調有點重…\n\n但是只有部族的朋友才會說我們的語言！\n\n我是長老馬茲。既然已經能安心回家，我們應該盡快啟程。但是我們有許多人心中仍充滿哀傷…也早已飢腸轆轆。我不會要你去收集鮮肉，那太危險了。不過，你可以去收集塊莖來給我們嗎？\n\n我們已經收集了附近的塊莖。我希望這些食物能撫慰心靈、振奮精神，讓我們有力氣回家！", progress = "大樹底下的根糾結纏繞。我們沒有冒險往東走，因為那裡的蟲太多了。也許那裡有更多樹根？", completion = "很高興看到你平安回來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72553] = {title = "多勞多得", objective = "從蟲身上收集12個肉。", description = "我們不傷心。但是我們快餓扁了。這是實話。幾個美味的樹根似乎還不夠。\n\n長老馬茲看不出你有多強大，但是我看得出來。對你來說，幫我們收集鮮肉，應該只是(100)-小菜一碟吧！東邊的蟲應該會是相當好下手的目標。\n\n拜託你了，帶回來的蟲越多越好！", progress = "蟲肉收集起來應該很簡單吧。如果你覺得大隻的有點困難，那就找小隻的吧。", completion = "我就知道我沒看錯人，&lt;class&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72560] = {title = "攀爬", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72584] = {title = "架設你自己的漁網", objective = "在河口釣魚洞架設捕漁網。", description = "想要試用看看你的漁網嗎？前往甦醒海岸南部的河口，並找到魚量豐富的地方。那裡應該會有架設漁網的好地點。", progress = nil, completion = "很好。別忘了幾小時後把你的捕漁網收回來。我們可不想那些魚被浪費掉了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72585] = {title = "開放導覽", objective = "在每個主要陣營據點完成導覽介紹任務：龍鱗基地、莫魯凱、伊斯凱拉及沃卓肯。", description = "英雄，你為巨龍群島做出了許多的貢獻。\n\n大家都很感激你的付出，想要歡迎你進一步融入他們的群體。去找他們談談，了解一下每個群體和他們的特長。\n\n我想你會發現，就像你可以為巨龍群島做很多事一樣，這裡有很多人也想要回報你！", progress = nil, completion = "你去認識大家了嗎？非常好。或許這樣他們就不會一直派特使來了。\n\n我希望你會繼續加強你和這些群體建立的連結。這對你們彼此只有好處。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72586] = {title = "更多的學術收穫", objective = "從蒼藍高地的洪荒使者身上取回熊怪文物。", description = "繼續帶文物來給我吧！\n\n收集越多熊怪字跡來，我就能交叉比對，降低出錯機率。", progress = "別放棄，我們一定要學會這個語言！", completion = "我馬上開始整理這批文物。", rewards = "您會學到：\n\n知識：冬毛\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72587] = {title = "驚人的學術收穫", objective = "從蒼藍高地的洪荒使者身上取回一根完好的雕銘棒。", description = "你是從哪裡找到這個的？真是美極了！\n\n比起保存文明歷史，洪荒使者似乎對破壞更有興趣，這也讓這些發現更加珍貴。\n\n有了這些，我只需要一根好的拓印棒就行了！", progress = "我等不及要開始閱讀了！", completion = "最棒的一天，就要從新發現的文物開始。", rewards = "您會學到：\n\n知識：冬毛\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72588] = {title = "洪荒掠奪者", objective = "從洪荒使者身上找回補給品。", description = "我已經掌握了冬毛族方言的基礎了，但是我可能有個壞消息。\n\n有一群冬毛採獵者似乎遭到附近的洪荒使者襲擊。這裡的冬天就跟丹莫洛那裡一樣嚴峻，而失去補給品對他們而言非常嚴重。\n\n你可以幫忙找回那些補給嗎？如果可以的話，請盡快。", progress = "一整個村莊的人都指望著這些補給品，你可別偷懶啊。", completion = "下次那些手腳不乾淨的洪荒使者肯定不敢再動手了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72589] = {title = "向犧牲致敬", objective = "從死去的冬毛採獵者身上取回他們的個人物品。", description = "雖然我們沒辦法彌補被洪荒使者殺死的採獵者，但是至少可以為他們的家屬提供一些慰藉。\n\n看看你能不能從死者身上找回一些私人物品吧。冬毛熊怪一定會很感謝你的幫助。", progress = "那些洪荒使者殺了多少冬毛熊怪？", completion = "雖然只是小東西，但全都充滿意義。這就是最重要的事情。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72590] = {title = "厄索爾的智慧", objective = "獲得厄索爾的祝福。", description = "我們偏離了睿智的厄索爾之道，執著使我們不再專注、恐懼使我們忘了深思熟慮。\n\n從強大的鏽松熊怪那裡收集松果。這些樹木的根深深紮進土裡，從水中獲得力量，成長迎向強風，而火焰使它成熟。它們正象徵著我們的再一次承諾，遵守真正的平衡之道。\n\n騎上你的飛龍翱翔天際吧，這樣應該就能收集到足夠的數量。樹木上半部是收集這些東西最好的地方。\n\n把東西帶到附近的聖壇，獻給厄索爾。", progress = "我們必須恢復萬物的平衡。", completion = "我們未來的道路一片清晰。感謝你的貢獻。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72591] = {title = "血債血償", objective = "到雍亞拉平原找貝恩。", description = "<name>，我聽說你跟雍亞拉平原的半人馬關係很好。我想請你幫個忙。\n\n幾天前，貝恩前往平原，去尋找一群失蹤的牛頭人。我說要陪他一起去，但他堅持獨自出發。\n\n你也知道，雷霆崖的牛頭人跟卡林多的半人馬有一段血腥的過去。儘管莫魯克半人馬和這段歷史沒有關係，我還是有點擔心。\n\n有你在的話，或許可以緩和緊張局勢。至少我是這麼想的。", progress = nil, completion = "啊，&lt;name&gt;。是梅拉派你來的？\n\n雖然我想自己來，但我承認，你跟半人馬的交情或許可以派上用場。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72592] = {title = "過往的傷疤", objective = "問半人馬莫魯克關於波凡‧風之圖騰失蹤的事情。", description = "是我的好友波凡‧風之圖騰把這個牛頭人部族帶來巨龍群島。自從他們進入這片平原，就從此音訊全無。\n\n要是他們失蹤了，那我就必須找到他們。不幸地是，我低估了這個地方有多遼闊。\n\n既然你跟半人馬有交情，可以幫我問問他們知不知道波凡或他部族的事嗎？\n\n也許他們可以幫我縮小搜索的範圍。", progress = nil, completion = "我是請你去打聽情報，沒有要你邀請半人馬加入我們！你不能叫她回家就好了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72593] = {title = "托姆爾風格的開場", objective = "在水池附近的東部道路跟托姆爾和貝恩碰面。", description = "自從巨龍歸來後，我們發現通過平原地帶的外地人數量大幅增加。我們通常會嚴密看守邊界，但是現在他們的數量實在太多，加上虎視眈眈的諾庫德勢力，實在讓我們難以追蹤他們的動向。\n\n有個斥候回報，有一群符合你描述的外地人正沿著東部道路前進。我們應該從那邊開始搜索。\n\n至於你的朋友，可汗已對我下了命令。不管同伴再怎麼難搞，我也會嚴格執行命令。", progress = nil, completion = "這裡的半人馬跟卡林多的半人馬似乎也沒太多差別。\n\n&lt;貝恩用懷疑的眼神看了托姆爾一眼。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72594] = {title = "告知壞消息", objective = "跟牛頭人對話，並辨認出你找到的物品屬於何人。", description = "我們剛到不久，貝恩就被叫走。波凡仍然下落不明，所以他找一個叫做塔加的人談話。\n\n我就這樣被留在外面吹冷風，真不意外。他們似乎還是不信任我。\n\n無論如何，你一定要進去跟那些牛頭人談談。把之前找到東西拿出來，看看能不能辨認出物品的主人。這樣一來，至少你能讓家屬知道我們目前的搜索進度。\n\n不過切記…對他們好一點，<name>。對他們來說，這可能會是一生之中最糟的一天。", progress = nil, completion = "謝謝你為這些人所做的事。\n\n至於托姆爾，雖然我不想承認，但看起來她證明了自己的價值。\n\n不過她的個性還是很不討喜。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72595] = {title = "尋找波凡‧風之圖騰", objective = "搜索附近區域，尋找失蹤的牛頭人。", description = "根據這名倖存者所說，半人馬發動突襲，讓他們措手不及。波凡率領眾多勇士對抗半人馬，希望能為其他人爭取逃跑的時間。\n\n<name>，波凡最後成功了，但是他和大部分的勇士都沒能回來。我們必須找到他。\n\n我需要你幫忙搜索附近地區。如果找到任何生還者，叫他們來這裡跟我們會合。\n\n如果找到倒下的牛頭人戰士…那就從他們身上取下能辨認身份的物品，帶給他們的家人。", progress = "有什麼發現？", completion = "我跟一些倖存者談過，在戰鬥結束後就沒有人看過波凡了。\n\n那個陣亡的牛頭人身上的頭飾不是他的，所以只有兩種可能…他不是失蹤，就是被捉了。\n\n&lt;貝恩的表情越發凝重。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72597] = {title = "厄索克之力", objective = "獲得厄索克的祝福。", description = "我們已經有很多年沒有為強大的厄索克獻上祭品了，如果我們想為族人恢復平衡，我們就需要他的祝福。\n\n他的聖壇就藏在東部的山區裡，那地方只有少數人會湊巧發現。", progress = nil, completion = "謝謝你，外來者。雖然你帶來讓人憂心的消息，但是我們還是會盡可能紀念厄索克。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72599] = {title = "聯合救援行動", objective = "救出6個風之圖騰俘虜。", description = "托姆爾說，對風之圖騰一族發動攻擊的敵人，是名叫諾庫德的敵對氏族。\n\n沿著這條路走下去，就會抵達他們最近的哨站，被俘的牛頭人很有可能被帶去那裡。\n\n任務很簡單，就是救出俘虜。我們不知道那裡有多少人，或是他們待了多久，所以我們必須快點行動。\n\n根據我的經驗，半人馬通常很快就會解決掉俘虜。", progress = nil, completion = "我們把營地搜了一遍，把能救的人都救出來，但波凡並不在俘虜之中。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72600] = {title = "席卡顯威", objective = "在15名被殺死的諾庫德半人馬或其盟友身上放置席卡旌旗。", description = "雖然我們是來這裡救出被俘虜的牛頭人的，但是我有件私事想請你幫忙。\n\n我們攻擊的地方，曾經是我的家鄉。諾庫德趁著內戰對我們發動突襲，成功佔領了此地。\n\n把那些席卡旌旗拿去。每次你殺死諾庫德半人馬或他們的盟友，就把旌旗插在屍體上。我想藉此警告他們，如果這些傢伙膽敢繼續霸佔我的家園，他們就必須付出生命的代價。", progress = nil, completion = "我看見遍布高地的旌旗了。雖然往事無法改變，但是這讓我能夠微笑以對。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72601] = {title = "波凡的最後希望", objective = "去找雍伊爾溫泉附近的波庫。", description = "如果波凡不在這裡，那諾庫德的人可能把他帶去任何地方。我們或許只剩最後一個找到他的機會，不過這個機會也相當渺茫。\n\n我們還有波凡的項鍊。有個雍伊爾秘法師或許能用項鍊占卜出他的位置。我也只聽說過這個儀式，不知道到底能不能行得通。\n\n去雍伊爾溫泉找波庫吧。他一定會幫我們。\n\n貝恩和我會確保救出來的牛頭人能安全回家。我們會在雍伊爾溫泉跟你會合。", progress = nil, completion = "托姆爾已經把你們的來意告訴我了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72602] = {title = "樂觀的秘法師", objective = "收集一顆強壯的薩曼瑟螈心臟和8朵噴泉花。", description = "我一定可以找到這個叫波凡‧風之圖騰的人，但我需要你們提供幾個東西。\n\n首先，我需要生長在溫泉底部的鮮花。這些花朵具有我們需要的特殊效果。\n\n然後，我需要薩曼瑟螈的心臟。心臟越強壯，成功的機會就越大，所以盡量找一顆最強壯的來吧！\n\n其他的材料我會自己收集。", progress = "你找到想找的東西了嗎？", completion = "太好了，這都能派上用場！你的朋友不願意進入溫泉，那我就在這裡舉行儀式吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72603] = {title = "無價訊息", objective = "把物品放入薰香爐，然後準備體驗幻象吧。", description = "現在只要把這些花朵磨碎，然後…這樣就行了！\n\n把這些物品放入薰香爐中吧。有了這些和波凡的項鍊，我就能懇求雍亞拉幫助我們找到他。\n\n運氣好的話，她會賜予我們幻象。", progress = "但願能夠成功。", completion = "至少我還有個可靠的盟友。&lt;name&gt;，謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72604] = {title = "搏命救援", objective = "跟貝恩‧血蹄在諾庫敦堡外碰面。", description = "我早該知道我們不能信任半人馬。他們也許願意提供我們一點協助，但是在危急時刻卻不願意冒險伸出援手。\n\n先專心處理手上的任務吧。我們不能就這樣放波凡當半人馬的俘虜！我會立刻往諾庫敦堡出發。\n\n盡快到那裡跟我會合吧。", progress = nil, completion = "你來了。很好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72605] = {title = "救出波凡‧風之圖騰", objective = "在諾庫敦堡搜尋波凡‧風之圖騰。", description = "現在分秒必爭，<name>。我們必須盡快找到波凡。\n\n這座堡壘到處都是半人馬。分頭進行的話，搜索的進度會更快，也比較容易避開巡邏的守衛。\n\n拿著一瓶我帶來的藥水。它應該能讓你不被發現，不過要注意諾庫德鬥犬。按照托姆爾的說法，它們聞得到你的氣味。\n\n搜索這一帶，找出波凡。如果你先找到他，那就直接救他出去。別等我。", progress = nil, completion = "我太遲了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72606] = {title = "殺紅眼", objective = "殺死諾庫敦堡內的半人馬。", description = "諾庫德。吉爾吉斯。瑪格拉姆。科卡爾。他們都一樣…\n\n他們危害所在的土地。他們殺戮我的族人。我會阻止他們！\n\n我要終結半人馬的威脅。就在這裡！就是現在！", progress = nil, completion = "&lt;砍殺數十個半人馬後，貝恩顯得很疲勞。他呼吸急促，全身傷痕累累。&gt;\n\n賈默古…要為這一切負責…\n\n我不會…讓他逃掉…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72609] = {title = "塵埃落定", objective = "跟斥候托姆爾和貝恩‧血蹄在托古薩克村碰面。", description = "幸好我們及時趕到。在你跟賈默古對戰的時候，我們攔截了打算從側翼進攻的諾庫德援軍。\n\n在戰鬥中，我們死了兩個同伴。我們已經取回了他們的屍體。最後一個就是波凡。\n\n諾庫德很快就會集結起來追殺我們。我們得馬上離開。\n\n到托古薩克村去吧，牛頭人在那裡紮營。我們在那裡碰面。", progress = nil, completion = "自從我們離開諾庫敦堡，貝恩就沒說過多少話。直到現在，我才發現波凡對他到底有多重要。\n\n至於我，葬禮結束後，我就會返回莫魯凱。即使結果不如我們預期，但我已經履行了可汗的命令。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72632] = {title = "巨龍群島補給品", objective = "朋友，你為我們的村落和族人提供了難能可貴的幫助。我們另外湊了一些物資要給你，希望你能繼續幫助我們！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n大型伊斯凱拉補給包"}
