MultiLanguageQuestData['tw'][72644] = {title = "緊急事務", objective = "前往暴風要塞後的外堡跟馬迪亞斯‧肖爾大師見面。\n\n已提供物品：\n", description = "<一張摺起來的紙條滑入你手中。當你轉頭尋找送紙條給你的人時，卻發現空無一人。>\n\n<name>，現在有個緊急任務，只有像你這樣老練的暴風城英雄才能勝任。\n\n請儘快到暴風要塞後方見我，記得別告訴任何人！\n\n<底部有小小的紋章，代表軍情七處最隱秘的行動。>您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n雄獅精衛套裝\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72646] = {title = "生命火花：甦醒海岸", objective = "在戰爭模式下，於甦醒海岸收集100個生命火花。", description = "你沒有在風中聞到冒險的甜美氣息嗎？\n\n甦醒海岸現在充滿能量與生命，簡直就像快爆發了一樣。到那裡去冒險吧！", progress = "聽說這時候的生命之池非常美麗。", completion = "有找到什麼有用的東西嗎？", rewards = "您會收到：\n\n鬥爭戰利品碎裂的鬥爭戰利品巨龍群島補給品鬥爭戰利品榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72647] = {title = "生命火花：雍亞拉平原", objective = "在戰爭模式下，於雍亞拉平原收集100個生命火花。", description = "<name>，雍亞拉平原洋溢著強大的能量，滋養許多的野生動物。\n\n現在正是加入狩獵的最佳時機，為自己獵取戰利品、爭取榮耀！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鬥爭戰利品碎裂的鬥爭戰利品巨龍群島補給品鬥爭戰利品榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72648] = {title = "生命火花：蒼藍高地", objective = "在戰爭模式下，於蒼藍高地收集100個生命火花。", description = "浪潮襲來，把生命的禮讚帶到蒼藍高地。\n\n這時候就是該陪伴朋友、陪伴家人、享受美食，以及開創新的故事。", progress = "有機會一定要去嚐一下那邊的湯。", completion = "有遇到豺狼人嗎？", rewards = "您會收到：\n\n鬥爭戰利品碎裂的鬥爭戰利品巨龍群島補給品鬥爭戰利品榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72649] = {title = "生命火花：薩爪祖斯", objective = "在戰爭模式下，於薩爪祖斯收集100個生命火花。", description = "薩爪祖斯洋溢著巨龍群島重新甦醒的能量。\n\n好好把握這個機會。", progress = "從那個門出去就是了。絕不會出錯。", completion = "協調者萬分感謝你。", rewards = "您會收到：\n\n鬥爭戰利品碎裂的鬥爭戰利品巨龍群島補給品鬥爭戰利品榮譽點數征服點數"}
MultiLanguageQuestData['tw'][72650] = {title = "春江水暖", objective = "去潘達利亞的翠玉林找琦麗苟莎。", description = "幾年前琦麗苟莎離開荊棘谷時，她有寫信給我。她說那裡雖然風景秀麗、氣候宜居，但是有點太吵了。我以為她已經在潘達利亞找到她要的平靜，也希望事實如此。\n\n說真的，對她沒有回應群島這件事情，我並不意外。儘管如此，我們還是要負責找出她的下落。要我捫心自問的話，我是很希望能再見她一面。\n\n一起去翠玉林一趟避寒一下，別在這裡繼續吹冷風吧。", progress = nil, completion = "…卡雷苟斯？！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72651] = {title = "呵護鯉魚", objective = "在晨綻餵鯉魚並打掃池塘，清理碎石和垃圾。", description = "村裡的鯉魚代表著好運和寧靜，鯉魚的健康狀態也代表著村莊的活力。\n\n鯉魚的飼料是使用昆蟲和蔬菜泥特別製作的。雖然聽起來不怎麼好吃，但在脫水完成、切成整齊的小塊後，其實還不錯。\n\n拿去吧！輕輕把飼料丟在鯉魚附近的水裡就行了。\n\n鯉魚的池塘差不多該打掃了，如果有看到碎石或垃圾，請順手清理一下。", progress = nil, completion = "做完了嗎？謝謝你。鯉魚真是漂亮，對吧？牠們的鱗片閃閃發光，就像龍鱗一樣。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72652] = {title = "珍愛自己", objective = "幫琦麗苟莎整理家裡。", description = "能來到琦麗家，既讓人感到古怪，又讓人覺得愉快。\n\n雖然如此，我不得不說，這裡真是一團亂。她把大部分心力都花在幫助村民身上，我懷疑她完全沒留時間給自己。琦麗的個性就是這樣…<卡雷苟斯嘆了口氣。>\n\n$p，你介意幫忙把這裡稍微整理一下嗎？我想她一定會感激我們的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72653] = {title = "鮮採直送", objective = "把浩瀚蒼穹送到晨綻村民的住處去。", description = "我最近想在這片土地上培育出一種新花朵，這種花的用途很廣泛，村民跟我還在嘗試開發它的各類用途。\n\n我今天剛摘了一批，你可以幫我把花送到目的地嗎？", progress = nil, completion = "太好了！對了，如果你喜歡花朵，我很樂意在下次收成時給你一束。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72655] = {title = "與卡雷苟斯小酌", objective = "跟卡雷苟斯在醉猴樓喝一杯。", description = "<卡雷苟斯沉默了一陣子，臉上露出熱切期盼的表情。>\n\n我原本想叫諾茲多姆來陪我們打發時間，但他應該會跟我說我自己一個人沒問題的。\n\n嗯…醉猴樓，對不對？如果琦麗推薦的話，我們就一起去吧！", progress = "出於同袍情誼，佩吉‧金流推薦了這種超棒的茶…熱麥茶！別客氣，喝點茶吧。", completion = "我很需要休息一下，能來這真是太好了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72656] = {title = "冬泉谷", objective = "跟辛德拉苟莎說話，收集更多情報。", description = "護國者哈爾琳負責管轄冬泉谷一帶。即使在打敗渴求力量的法師昂布蘭希後，她仍繼續在家鄉找尋任何潛在威脅，以絕後患。身為瑪里苟斯唯一一名仍在世的配偶，她繼承了魔法守護者的遺志，時時刻刻以此為己任。\n\n她若能回來加入藍龍軍團，會使我們的勢力更為壯大。", progress = nil, completion = "從我甦醒後，我就一直在觀察哈爾琳。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72657] = {title = "魔法守護者", objective = "去卡林多的冬泉谷找哈爾琳。", description = "我很好奇哈爾琳的事情。她是瑪里苟斯最後一名仍在世的配偶，她在瑪里苟斯急需幫助時及時伸出援手，我對此相當感激。\n\n我承認，我暗中觀察她了一段時間。她具備了藍龍的所有特質：勤學、自豪，使用魔法時也相當謹慎。\n\n若要為了群島的號召去拜訪她，我認為我自己就是最合適的人選。準備好的話，就用我的傳送門吧。我們在那裡碰面。", progress = nil, completion = "入侵者，報上名來！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72658] = {title = "龍石", objective = "透過擊敗獨特的生物、通過地城與團隊副本、完成世界活動或領取寶箱戰利品來取得50個龍石。然後，和庫佐斯談話，使用龍石來升級一件裝備。", description = "在你踏進洛姆的那一刻，我就注意到你了，勇士！看看這些閃亮的裝備啊。而且我感覺得出來，你還想要…更多。\n\n你應該已經在路上看到龍石了。我跟我的朋友庫佐斯知道一種方法，可以控制龍石的力量來升級裝備。\n\n我們已經把這個知識傳授給我們的機械升級專家了。他們每個人都可以跟你說你需要的材料。只要你有足夠的龍石，庫佐斯現在就可以示範給你看。", progress = nil, completion = "你的裝備又更閃亮了一些，勇士！我很樂見我們的群體變得更強大。\n\n請收下這些禮物。", rewards = "您會收到：\n\n黑曜龍石幼龍暗焰紋章碎片"}
MultiLanguageQuestData['tw'][72660] = {title = "天外飛來一梟", objective = "測試並修復梟獸圖騰。", description = "你工作的時候，我檢查了你帶回來的毀損圖騰。關於隱秘小林，有件事我一直覺得很奇怪。那片林地以前有很多無害的白色野兔住在那裡，但現在卻只找得到這些古怪的梟獸圖騰…\n\n我想辦法拼湊了碎片。雖然說不上完美，但希望我們能透過這個稍微了解一下損壞前原有的魔法效果。\n\n說不定它會讓我們長出羽毛和毛皮呢。你可能會以為，我身為藍龍應該很享受這種冷天氣，不，沒這回事。", progress = "我都記不得上次有個像樣的人來幫忙是什麼時候了。謝謝你。", completion = "果然如此，我真是太天真了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72661] = {title = "讓飛龍休息", objective = "跟辛德拉苟莎合作，想辦法讓哈爾琳振作起來。", description = "我的天，我突然有個想法。準備好了，就跟我交談吧。", progress = "我擔心哈爾琳一直沒有好好的休息。", completion = "有時候，我們只是想要再體驗一次簡單的美好。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72662] = {title = "重新補給", objective = "從托古薩克村附近區域收集40個新鮮平原肉類。", description = "諾庫德持續在攻擊穿越平原地帶的外地人。這肯定是出自他們的傑作。\n\n生還者說他們的糧食補給在遭到偷襲後幾乎付之一炬。我們應該想辦法幫幫他們。\n\n到水池附近地區去打獵，送一點肉去給他們吧。那裡應該有不少獵物。這應該能幫他們暫時解決缺食物的問題。", progress = "你收集了多少？", completion = "太好了，這樣應該就夠了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72663] = {title = "松木之徑", objective = "跟托姆爾和貝恩在松木崗哨碰面。", description = "如果波凡沒死，卻不在那裡，那他不是失蹤…就是成了俘虜。從托姆爾的訊息看來，恐怕比較可能是後者。\n\n風之圖騰現在安然無恙，但是因為他們隨時可能遭遇襲擊，所以沒辦法分出人手去找波凡。\n\n看起來我們只能靠自己了。朝松木崗哨出發吧。", progress = nil, completion = "托姆爾想請我在她的營地等你，但是…我婉拒了這個提議。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72664] = {title = "滿出來的蛋", objective = "到甦醒海岸的晶紅生命聖殿與亞美拉會面。", description = "<振翅靈獸轉了個圈，在你手上放了一張被口水浸濕的字條。>\n\n$p，晶紅生命之池被等待孵化的龍蛋塞爆了。我們很樂意歡迎這些寶貝來到艾澤拉斯，但我們的幼龍看管者不夠，無法好好照料它們。\n\n請來生命聖殿找我，一起討論可能的解決辦法。\n\n- 亞美拉您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n解鎖幼鱗托育所\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][72665] = {title = "幼龍看管者的智慧", objective = "在晶紅生命之池的花園與幼龍看管者交談。", description = "我們的護蛋者回報說，有一窩新龍蛋很快就會孵化。一般而言，將有一位幼龍看管者會接收剛孵化的幼龍，讓他跟同軍團的夥伴一起扶養。不過，並非所有龍裔都有成為幼龍看管者的資質，所以我們的人手有點不足。\n\n到生命聖殿下方的花園，尋求各龍軍團幼龍看管者的智慧。艾迦潘索斯是經驗豐富的藍龍幼龍看管者，同時也是幼鱗托育所的所長。不過他需要你的協助。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72666] = {title = "托育所所長艾迦潘索斯", objective = "到沃卓肯的幼鱗托育所找艾迦潘索斯。", description = "亞美拉跟我說了有關幼龍即將孵化的事，並介紹了托育所。你知道艾迦潘索斯是很有名的幼龍看管者嗎？聽說他曾一邊對抗惡魔，一邊照顧幼龍！\n\n如果他真的像大家說得那麼厲害，我一定能從他身上學到很多東西。我才剛剛成為幼龍看管者，但我願意盡我所能幫上忙。\n\n幼鱗托育所就在沃卓肯。我先收拾一下東西，再去那裡找你和艾迦潘索斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72667] = {title = "為點心而跑", objective = "向沃卓肯的商人拿取點心。", description = "到訪托育所的幼龍在停留期間會吃點心，數量龐大的點心。\n\n要是幼龍未來會經常到訪並停留，我們就必須準備更多點心，餵飽他們無底洞般的肚子。\n\n這份清單上列了幼龍最近愛吃的點心。另外我還幫普林利爵士訂了一些東西，記得一起拿回來。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72668] = {title = "培育生命的溫床", objective = "讓幼鱗托育所再次變得井然有序。", description = "幼龍很容易就把環境弄亂。托育所從早到晚都飽受幼龍的肆虐！\n\n請幫忙打掃托育所。新生的幼龍需要一個乾淨的居住環境。\n\n我絕不容許讓他們生活在亂七八糟、雜草叢生的地方！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72669] = {title = "名望物資", objective = "你好，<class>。你已經向沃卓肯協調者證明了你的價值。希望這些物資可以幫到你，繼續實現我們的理念。請別讓我們失望！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n小型沃卓肯協調者補給包"}
MultiLanguageQuestData['tw'][72670] = {title = "被遺棄的一群", objective = "安撫珊達拉的回音，幫助他們獲得平靜。", description = "為了嘗試擋下憤怒的藍龍軍團，珊達拉的法師把他們同胞的靈魂困在了永恆的晶化折磨之中。\n\n現在他們的回音只能四處遊蕩，不斷重新經歷他們的文明所遭遇的厄運，而且這樣的折磨已經超過一萬年了。\n\n我發現有一些遊魂還剩下最後一點的理智，也許有機會說服他們從年代久遠的恐懼泥沼中解脫，讓他們放下過去。", progress = nil, completion = "這種水晶囚牢相當難以逃脫。儘管如此，如果運氣好，我們在此所做的努力可以讓滯留在此的靈魂獲得一絲平靜。", rewards = "您會收到：\n\n龍石"}
