MultiLanguageQuestData['tw'][72677] = {title = "禁忌之境 1/3", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72678] = {title = "禁忌之境 1/4", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72679] = {title = "秘法輓歌", objective = "幫助珊達拉的回音獲得最後的安息。", description = "時候到了，<name>。多虧你的協助，大部分躁動的珊達拉回音都已經獲得平靜。儘管如此，有些回音仍憤懣不平、滿懷悲傷，無法僅憑言語安撫。\n\n我用你找回的碎片成功製作了一個水晶法器的複製品，就跟當年把珊達拉變成廢墟的法器一樣。在這裡使用它，應該能將受困的靈魂引到此處，讓我們有機會幫助他們獲得最後的安息。\n\n提高警覺。我不知道他們累積多年的哀傷會以何種方式顯現。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72681] = {title = "向貿易站報到", objective = "回到貿易站，從收藏箱領取商人的標幣。", description = "<你注意到遠處有個閃亮亮的箱子。你突然想起自己可以領取標幣，然後在T&W貿易站使用。>", progress = nil, completion = "希望你喜歡這個月的最新商品和奇珍異寶，&lt;name&gt;。", rewards = "您會收到：\n\n"}
