MultiLanguageQuestData['tw'][72708] = {title = "巨龍群島補給品", objective = "將巨龍群島補給袋送去給翼息大使館的編目員潔可思。\n\n已提供物品：\n", description = "<那隻元龍一定是從一個倒楣的龍鱗遠征隊成員手上搶走了這袋物資。\n\n翼息大使館的編目員潔可思會知道要怎麼做。>", progress = nil, completion = "我們一直都需要補給品，我知道要怎麼好好運用的。", rewards = "您會收到：\n\n巨龍群島補給品"}
MultiLanguageQuestData['tw'][72709] = {title = "資助尋寶活動", objective = "從編目員潔可思那裡購買考古學家文物筆記。", description = "<編目員潔可思迅速翻開自己的補給袋，拿出一張新繪製的地圖。>\n\n我們的一位考古學家剛剛報告了關於遺失文物的線索，可能就在這個地區。\n\n如果你願意捐贈這些物資來資助考古學家的下一次探險，你就能獲得這張寶藏的線索地圖。", progress = nil, completion = "只要多蒂及娜蕾迪亞確定永久營地的位置，我跟雷亞娜會和他們一起去。\n\n之後再來找我們，看看我們的完整目錄吧。", rewards = nil}
MultiLanguageQuestData['tw'][72712] = {title = "盡己所能", objective = "跟爪兵戴莫斯交談。", description = "很高興你來了，$p。\n\n風暴散去，育所也開啟了。現在正是進攻的良機！我打算率領一隊斥候深入禁忌之境。\n\n等你準備好出發時，告訴爪兵戴莫斯，他是我的副指揮官，他率領的半龍人會在下次偵察行動加入我們。", progress = nil, completion = "你來了。\n\n很好。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][72713] = {title = "遺產", objective = "幫助半龍人斥候佔領失落圖書室。", description = "你來得真早，士兵。\n\n<戴莫斯諷刺地向你敬禮。>\n\n這太不真實了。我們又回到這個很久以前熟悉的地方。但是現在，這裡成了一片廢墟。還充滿了各種沒見過的野生動物。\n\n我想，那句俗話說的沒錯。「人事已非。」\n\n閒聊夠了，該做正事了。安珀莎要我們封鎖這個地方。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][72714] = {title = "妨礙研究行為", objective = "拯救爪兵長駐營的5名害怕的研究員。", description = "龍鱗遠征隊對沙卡瑞斯來說不是什麼威脅。沙卡瑞斯和他的追隨者竟敢明目張膽，在研究期間對他們發動攻擊…\n\n<厄比西昂蹙眉。>\n\n盡可能救下遠征隊的人吧。如果這片廢墟藏有的知識能揭開我們過去的秘密，其價值可說是無與倫比，不過若是跟無辜的性命相比，這些知識一文不值。\n\n等我完事後，我會在上方的遺跡和你碰面。", progress = nil, completion = "做得好，&lt;name&gt;。聽到你救下了這麼多族人…還為我們知識的高塔添磚加瓦，我感到十分欣喜。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][72715] = {title = "火焰止於此處", objective = "在至高育所殺死4個碎裂掠取者、6個碎裂遺跡潛獵者和飛翼長伊亞薩爾。", description = "沙卡瑞斯正在屠殺我們的族人、破壞我們的遺產，將他所到之處的一切燒個一乾二淨。現在，他還企圖掠奪不滅守護者的育所。\n\n<安珀莎憤怒嗥叫。>\n\n厄比西昂和我負責留守，請你擊退碎裂火焰軍的攻勢。等到確定遠征隊安全後，我們會到上頭跟你會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][72717] = {title = "分裂的育所", objective = "協助安珀莎探索龍顱島下方的洞穴。", description = "這裡…我已經有好長一段時間沒回來了。從我擔任龍隊指揮官後就沒回來過了。\n\n這是個悲傷的地方，充滿痛苦…和失敗的記憶。\n\n當時奈薩里奧就是在這裡進行測試，對象是他認為值得花時間的成員。他使用了我們無法理解也無法掌握的力量，把我們當實驗室的白老鼠肆意捉弄。\n\n有許多人…未能達到他的標準。\n\n也許沙卡瑞斯帶我來這裡是為了測試我，就跟我們的父親做過的事情一樣。\n\n你願意跟我同行嗎？", progress = nil, completion = "我們成功包圍他了！\n\n為什麼…他們沒有發動攻擊？他有什麼陰謀？", rewards = "您會收到：\n\n黑暗墮落披風巨龍群島補給品元素溢流"}
MultiLanguageQuestData['tw'][72719] = {title = "穿越時光的魔化之路", objective = "完成5次時光漫遊地城冒險。", description = "覺得你本事很強嗎？我讀過燃燒軍團的事情，他們似乎很厲害。\n\n要不要證明給我看，你比他們還要更厲害？", progress = nil, completion = "哇，看看你！原來你真的挺厲害的。\n\n之後有機會再看看你到底有多厲害。厲害的人就是要能夠一直厲害下去。", rewards = "您會收到：\n\n牢獄寶箱牢獄寶箱亞貝魯斯寶箱亞貝魯斯寶箱埃達希爾寶箱覺醒寶藏貯藏箱"}
MultiLanguageQuestData['tw'][72720] = {title = "競技場的呼喚", objective = "贏得10場競技場練習戰。", description = "你去過競技場嗎？那可真是個厲害的地方！\n\n去競技場贏個幾場戰鬥，讓我見識一下你有多厲害。\n\n我？我經歷的戰鬥可多了。我現在只想做點運動、打破幾個紀錄。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服點數榮譽點數"}
MultiLanguageQuestData['tw'][72721] = {title = "箇中翹楚", objective = "帶著由25級寵物組成的隊伍，透過尋找對戰功能打倒5位玩家。", description = "你有看過那些訓練小生物互相對戰的冒險者嗎？\n\n那可厲害了！你得讓那些小傢伙每天都變得越來越厲害。\n\n去打敗那些冒險者和他們的小寵物，讓我見識一下你有多厲害！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n究極戰鬥訓練石"}
MultiLanguageQuestData['tw'][72722] = {title = "征戰使節", objective = "完成4場傳奇難度的地城。", description = "有所謂的厲害，還有所謂的真的很厲害。\n\n覺得你有本事闖入最危險的地方，然後活下來嗎？", progress = nil, completion = "你看起來比之前更厲害了，很好！\n\n別太滿足啊，厲害的人就是要能夠一直厲害下去。繼續加油！", rewards = "您會收到：\n\n牢獄寶箱亞貝魯斯寶箱埃達希爾寶箱古老銅條"}
MultiLanguageQuestData['tw'][72723] = {title = "戰鬥的呼喚", objective = "在戰場贏得4場對戰。", description = "你曉得什麼叫厲害嗎？我以為我曉得，直到我看了那些超大規模的挑戰活動！\n\n一大群的冒險者互相打了又打、打了又打。\n\n沒有比扭轉劣勢更厲害的了！尤其是還要互相搶旗子！\n\n讓我看看你有多厲害！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n榮譽獎章征服點數"}
MultiLanguageQuestData['tw'][72724] = {title = "穿越時光的破碎之路", objective = "完成5次時光漫遊地城冒險。", description = "你知道什麼最厲害嗎？時光旅行！你知道有什麼比它還厲害嗎？在時光旅行的時候打怪物！\n\n讓我見識一下，這兩件事情你可以做得多厲害。", progress = nil, completion = "你看起來已經很厲害了。別忘了，真正厲害的人就是能夠一直厲害下去。\n\n下次再讓我看看你有什麼本事吧！", rewards = "您會收到：\n\n牢獄寶箱牢獄寶箱亞貝魯斯寶箱埃達希爾寶箱覺醒寶藏貯藏箱"}
MultiLanguageQuestData['tw'][72725] = {title = "穿越時光的隱蔽之路", objective = "完成5次時光漫遊地城冒險。", description = "我聽龍鱗遠征隊的人說過，有個地方叫做潘達利亞。\n\n聽起來就像個很厲害的地方！\n\n覺得你還是比較厲害嗎？那就證明給我看！", progress = nil, completion = "你回來了！覺得自己變厲害了嗎？我們下週就知道了。繼續加油！", rewards = "您會收到：\n\n牢獄寶箱亞貝魯斯寶箱亞貝魯斯寶箱埃達希爾寶箱覺醒寶藏貯藏箱"}
MultiLanguageQuestData['tw'][72726] = {title = "穿越時光的冰封之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "巫妖王！有聽過他嗎？我直到前一陣子才知道。最近我學到好多的新東西。\n\n你知道什麼最厲害？學習新的東西和拓展你的視野。\n\n你知道什麼東西一樣厲害？面對這個巫妖王的威脅！\n\n其實我真的不知道，你要怎樣證明你比這個巫妖王更厲害。但反正，就試試看吧。", progress = nil, completion = "你看起來有點冷酷！感覺比之前更厲害了。", rewards = "您會收到：\n\n牢獄寶箱牢獄寶箱亞貝魯斯寶箱亞貝魯斯寶箱埃達希爾寶箱覺醒寶藏貯藏箱"}
MultiLanguageQuestData['tw'][72727] = {title = "穿越時光的燃燒之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "有個地精學者跟我說了黑暗之門的事情。哇，聽起來真的很厲害！\n\n讓我見識一下，你有沒有比那個黑暗之門的東西還要更厲害！", progress = nil, completion = "你看起來是變厲害了。我想你應該有照我說的話去做。\n\n繼續加油！", rewards = "您會收到：\n\n牢獄寶箱牢獄寶箱亞貝魯斯寶箱亞貝魯斯寶箱埃達希爾寶箱覺醒寶藏貯藏箱"}
MultiLanguageQuestData['tw'][72728] = {title = "世界任務正等著你", objective = "完成10個巨龍群島的世界任務。", description = "你知道怎樣可以證明你有多厲害嗎？幫助巨龍群島的民眾！\n\n這裡有很多的問題要解決。去幫助他們，讓我見識你有多厲害！", progress = nil, completion = "我聽說了你做的所有事情！如果這不叫厲害，我真的不知道什麼才是了！\n\n繼續加油啊！", rewards = "霜鬃皮外衣霜鬃鍊甲外衣加強鍊甲長靴劣質鍊甲披風您能選擇下列奬勵中的一個：\n\n龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記沃卓肯協調者徽記莫魯克半人馬徽記洛姆鼴鼠人徽記夢境守望者徽記"}
MultiLanguageQuestData['tw'][72729] = {title = "大史瓦格蛙", objective = "把生鏽的群島錢幣帶給雍亞拉平原的大史瓦格蛙。", description = "一枚在巨龍群島找到的特殊硬幣。\n\n你聽其他的釣友說過，雍亞拉平原有個生物在收集這種東西。", progress = nil, completion = "&lt;大史瓦格蛙注視著你。&gt;", rewards = "您會收到：\n\n"}
