MultiLanguageQuestData['tw'][72809] = {title = "投入硬幣", objective = "《魔獸兵團》遊戲機出現在你面前。\n\n敢不敢玩一場呀？", description = nil, progress = "《魔獸兵團》遊戲機出現在你面前。\n\n敢不敢玩一場呀？", completion = "你做得很好！", rewards = "您會收到：\n\n兵團抽獎盒"}
MultiLanguageQuestData['tw'][72810] = {title = "穿越時光的破碎之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "最近我讀了一些關於艾澤拉斯那場大災變的書。\n\n你知道什麼叫厲害嗎？看見原本熟悉地方被一頭龍給毀了。\n\n你知道什麼才更厲害嗎？在那些地方戰鬥活下來！", progress = nil, completion = "你好像已經變厲害了！\n\n等我們下次再見面的時候，再看看你有多厲害吧。別忘了，厲害的人就是要能夠一直厲害下去。", rewards = "您會收到：\n\n牢獄寶箱亞貝魯斯寶箱亞貝魯斯寶箱埃達希爾寶箱覺醒寶藏貯藏箱"}
MultiLanguageQuestData['tw'][72831] = {title = "創意解決方案", objective = "讓玷污旌旗的叛亂法師束手就擒。", description = "我一直希望法師能重返塞拉摩的街道，恣意漫步。不過，我從沒想過這個願望會這樣實現。\n\n如果玷污旌旗真的打算再次製作一顆法力炸彈，我絕不能坐視不管。不過，我不會重蹈覆轍，犯下瑪里苟斯過去犯的錯誤。一定有辦法在不動手的情況下，跟這些法師好好講道理的。\n\n我會在你身上附魔，這個魔法能讓你在不殺死這些法師的情況下壓制對方。去吧，別讓他們的邪惡計畫得逞。", progress = nil, completion = "靜滯和安全相關用途一直以來都是秘法魔法的強項。我很高興我們能藉此在這裡達成這樣的成果。\n\n但是，我們心中的疑問仍未得到解答：到底是什麼讓這些法師一開始決定要做出如此魯莽的行為？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72832] = {title = "震盪餘波", objective = "傳送八顆原型法力炸彈。", description = "這群早熟的傢伙似乎想再次製作當年夷平塞拉摩的同一種炸彈。可想而知，他們還未成功。儘管如此，我還是不想冒險。要是他們意外發現更有效的解決方案，那就糟了。\n\n我原本想用法力冰霜冰封整座遺跡，但如果我們親愛的守護巨龍不希望把他們所有人變成法力粉塵，我想我還是先打消這個主意了。不過，還是要有人去阻止他們重現毀滅性武器的無聊舉動才行。\n\n答應我，別把炸彈給引爆了，好嗎？", progress = nil, completion = "嗯…&lt;class&gt;，多數跟我相遇的凡人，下場都不怎麼愉快，而我想你會是個例外。你做事幹練，值得些許表揚。\n\n…但我是不會這樣做的。如果你想要有人摸摸頭說你好棒，去找卡雷苟斯。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72833] = {title = "打破惡性循環", objective = "擄獲杜莉‧爍焰。", description = "現在大部分玷汙旌旗的低階成員都已經被抓住，只剩下組織的領袖要處理了。\n\n我想卡雷苟斯應該會希望留她活口。我沒有這類顧慮，但我也不是隻挑剔的龍。只要能阻止她的計畫，我不太在乎她會有什麼下場。\n\n他的計畫雖然很麻煩，但是目前為止似乎是有用的。因此，我願意再相信他一段時間，相信他自有安排。", progress = nil, completion = "我承認自己沒有料到事情會變成這樣。那隻地精…不。杜莉‧爍焰承受如此的痛苦，我能理解她想獲得強大力量，不讓悲劇在未來重演的心情。\n\n卡雷苟斯說，我們必須成為仲裁者與保衛者，而非只是囤積秘密。我想，我開始理解他為什麼會這樣說了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72854] = {title = "四面楚歌", objective = "前往南牆，跟亡靈哨兵指揮官貝爾蒙特交談。", description = "我們才剛站穩腳跟，又有人打算擊潰我們。\n\n有些人依然認為我們不配待在這裡，而且不惜殺掉我們來達成目的。\n\n有些宿怨太過根深蒂固，難以放下。不知怎麼辦到的，但血色十字軍…雖然已經所剩無幾，但他們仍成功在芬里斯島上建立了初步據點。\n\n前往羅德隆廢墟南牆。亡靈哨兵指揮官貝爾蒙特正在緊密監視他們的動向。", progress = nil, completion = "我沒預料到血色十字軍能集結這麼多士兵發動攻勢。\n\n我很想佩服他們，但我實在太生氣了。幸好，我生氣時就想拿刀到處插人。\n\n總之，情況還是相當糟糕，&lt;name&gt;。這些人不是隨便找來的農民軍。他們一定有個領袖，也受過一定的訓練。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72855] = {title = "前往瑟伯切爾", objective = "前往銀松森林的瑟伯切爾跟黑暗遊俠薇蘿娜拉見面。", description = "法拉尼爾和薇蘿娜拉已經前往瑟伯切爾去執行我們部分的計畫。\n\n我們只有少數亡靈守衛和黑暗遊俠部隊，目前還守得住，但我們需要有人朝血色十字軍的根據地主動出擊。當然，前提是不能再犧牲我們已經不多的部隊。\n\n前往瑟伯切爾跟薇蘿娜拉見面吧。你就是我們毒刃的鋒利尖端。", progress = nil, completion = "你安全抵達了，很好。我和大藥劑師法拉尼爾對消滅血色十字軍已經有了一些想法。\n\n但在這之前，我們必須小心行事。對了，法拉尼爾好像在著手製作某種很有「爆炸性」的東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72856] = {title = "經典不敗", objective = "從附近的野生動物身上收集12個瘟疫肉塊。", description = "皇家藥劑師近幾年來合成過許多精巧的瘟疫，當然，一切都按照與荒寂議會的協議來，沒有…玩過頭。\n\n但要把這些血色襲擊者斬草除根，還是經典的方法最有用。原始的瘟疫幾乎只能在倖存者後代身上的染病組織找到。\n\n去吧，幫我從這裡奇妙的野生動物群體身上中收集一些樣本回來。我會好好利用的。", progress = "真懷念過去那段可以自由實驗、製作藥劑，不受限制、無拘無束的日子…啊，也許以後還有機會。你找來瘟疫樣本了嗎？", completion = "好極了！啊，我還能聞到那原始瘟疫的配方，突然有好多美好回憶湧上心頭。\n\n讓毒素充滿周遭的空氣，看著生物的血肉融化到只剩骨頭，真想念那段時光…呃，我不小心說出來了嗎？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72857] = {title = "轟隆草", objective = "前往銀松森林收集6個轟隆草。", description = "有陰暗草，也有末日草，現在，容我隆重介紹…轟隆草！\n\n你沒聽錯，這也是長在銀松森林當地的品種！搭配煉金配方一起使用的話，這種草可以讓你的成品火力十足。\n\n去幫我收集一些吧。小心別把眉毛燒掉了。不過其實眉毛也沒什麼用，對吧？", progress = "你把我需要的轟隆草都找來了嗎？我等不及要調配了。", completion = "太棒了！而且你的眉毛都還在。應該吧。如果你想要，也可以縫上兩條假眉毛。\n\n現在，一起見證煉金術的奇蹟吧！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72858] = {title = "酸液能贏紙張", objective = "使用酸液步槍摧毀給所有不死生物的公告。", description = "在血色十字軍奪取芬里斯島後，他們嘗試威嚇我們在銀松森林的族人並使他們屈服。\n\n我們不能讓他們用力量或恐懼獲勝。\n\n在為法拉尼爾的藥劑收集材料時，把一切刻意散播的不實言論通通摧毀吧。", progress = nil, completion = "言語是有力量的。只要不許人們說話或發表言論，就能奪走那股力量。\n\n我們的族人在筆墨和刀刃上受的苦已經夠多了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72859] = {title = "上流偽裝", objective = "前往瓦爾甘牧場殺死霍瑟中尉並把他身上的護甲搶來。", description = "我們的計畫是把你送到芬里斯島去，但首先，你得看起來體面一點才行。\n\n斥侯回報，有一大群血色十字軍的士兵正在瓦爾甘牧場訓練，由一名中尉負責監督。有了中尉的護甲，你應該能深入敵陣，不被發現。\n\n不管你用什麼方法，去把護甲從他身上搶來吧。不用告訴我過程。", progress = "你獲得潛入血色十字軍用的偽裝了嗎？", completion = "世界上少了一個愛找被遺忘者麻煩的血色十字軍軍官，而你現在看起來也夠體面了。\n\n接下來，希望我們能順利把你送上島。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72860] = {title = "恐懼是我們的武器", objective = "嚇唬血色新兵並殺死他們。", description = "血色十字軍正在招募新兵。顯然地，當人們想把一切問題都怪在別人身上時，就會一窩蜂地把謊言信以為真。\n\n但他們一定會後悔做這個決定的。我們並不是造成問題的人，是他們攻擊了我們的家園。\n\n帶一個女妖跟你去吧。看到你和女妖，那些新兵一定會被嚇到屁滾尿流。", progress = nil, completion = "在危險擴張前先把根源消滅才是上策。現在芬里斯島孤立無援，也得不到新血助陣。\n\n是時候進入計畫的下一步了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72861] = {title = "血色間諜", objective = "穿上偽裝，前往芬里斯島向軍需官鈕蘭回報。", description = "是時候把你偷渡到芬里斯島上了。我知道你不太想穿著這護甲，但穿著它可以讓你自由穿梭敵陣、不被發現。\n\n走平地登島，別搞什麼花俏的空中行動。\n\n穿上護甲後，想辦法穿過海域到另一邊。到那裡之後，有個軍需官會告訴你下一步該怎麼做。\n\n在那之後，你應該知道該怎麼掀起動亂。", progress = nil, completion = "霍瑟！你的嘴巴附近看起來灰灰的。\n\n那些新兵已經把你操成這樣啦？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72862] = {title = "有內鬼", objective = "在不被發現的情況下，散播瘟疫炸藥並殺死所有血色大法師。", description = "我們很需要那些新兵壯大我們的陣容，但嚇人的不死族一直騷擾我們的補給線！不過，他們很快就要被通通殺光，而且這次爬不起來了。\n\n你可以看一下我們的物資，確保存量夠你的新兵使用嗎？當然，好東西都已經送去芬里斯城堡給指揮官了，但大家還是得吃飯。\n\n嗯，除了少部分人以外。\n\n現在就動身吧，中尉。", progress = nil, completion = "我能聞到瘟疫…還有硝煙的味道。\n\n做得好，你成功突破了他們的防線。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72863] = {title = "女妖的飛行", objective = "跟薇蘿娜拉說話，讓被遺忘者大軍朝這裡進攻。", description = "島上的防禦已被削弱、火砲和法師也不成威脅，現在我們可以準備再次率領部隊安全登島了。\n\n你應該不會以為你得自己一個人跟整支軍隊戰鬥吧？\n\n我知道你有那個本事，但留一些敵人給其他人建功吧。\n\n準備好讓其他人上場時，告訴我一聲就好。", progress = nil, completion = "他們以為我們會躲在城牆後面嗎？\n\n真是幼稚的兒戲。現在，我們會讓他們見識被遺忘者的力量。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72864] = {title = "活人都得死", objective = "殺光所有活著的血色部隊成員。", description = "該讓他們付出代價了。他們會後悔踏上我們的島嶼並妄想入侵我們的家園。\n\n我們會把敵人趕出去、殲滅他們並任由他們的屍首腐爛。", progress = nil, completion = "有時候，只有用對方能理解的語言交流，才能傳達明確的訊息。\n\n血色十字軍唯一理解的語言，就是力量。\n\n但那些人只是跟隨者而已，我們得找到這場入侵背後的主導者，讓他們也收到這個訊息才行。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72865] = {title = "被遺忘者的時刻", objective = "前往芬里斯城堡殺死血色指揮官福賽斯", description = "血色十字軍竟然一次部署這麼多新兵在戰場上，這種事我們從沒見過。\n\n我們很清楚，他們不是自己跑來這裡的，有人在指引他們…某個曾跟被遺忘者在戰場上交手過的人。\n\n我清楚記得這個人。\n\n跟我來，該殺掉指揮官福賽斯以絕後患了。", progress = nil, completion = "結束了。也許有幾個血色十字軍成了漏網之魚，但我們已經把芬里斯島上所有的血色勢力澈底殲滅了。\n\n失去了指揮官後，希望他們短時間內沒辦法再重振旗鼓，而且下次來惹被遺忘者的麻煩前，會好好考慮一番。\n\n我們擁有力量、有共同的使命，還有你。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72866] = {title = "回到羅德隆", objective = "使用傳送門回到羅德隆廢墟。", description = "回到牆內跟其他人見面吧。能跟你再次一起對抗血色部隊，我想貝爾蒙特應該覺得做為不死族，這輩子值得了。\n\n雖然如此，十字軍是不會就此罷休的。他們現在輸了，但以後可能會把這件事當成另一個招募新兵的方法。\n\n如果他們再來惹我們或鄰居，我們會做好準備。\n\n來吧，一起回羅德隆廢墟去。", progress = nil, completion = "歡迎回家。\n\n沒有你，我們是不可能贏得勝利的，我希望你明白這一點。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72867] = {title = "我是被遺忘者", objective = "取得榮譽和被遺忘者的綬章。", description = "我們奮戰奪回了自己的家園，並確保其安全無虞。\n\n你的勇氣和力量激起了被遺忘者的決心。有你在，我們知道有人會為我們而戰。\n\n去吧，他們在等著見你。", progress = nil, completion = "看到了嗎？\n\n只要有我們的骨骸還有力氣，我們就會繼續戰鬥，為我們在艾澤拉斯上的權力和生存空間而戰。\n\n我們是被遺忘者。", rewards = "您會收到：\n\n套裝：被遺忘者勇士套裝龍石"}
MultiLanguageQuestData['tw'][72868] = {title = "更多狩獵戰利品", objective = "外來者，你帶來什麼東西？", description = nil, progress = "外來者，你帶來什麼東西？", completion = "只有最偉大的獵人才有辦法炫耀這麼多偉大的狩獵戰利品。你為我們的狩獵爭光。", rewards = nil}
MultiLanguageQuestData['tw'][72869] = {title = "更多狩獵戰利品", objective = "外來者，你帶來什麼東西？", description = nil, progress = "外來者，你帶來什麼東西？", completion = "只有最偉大的獵人才有辦法炫耀這麼多偉大的狩獵戰利品。你為我們的狩獵爭光。", rewards = nil}
MultiLanguageQuestData['tw'][72872] = {title = "消滅深岩剝石怪", objective = "殺死8隻深岩剝石怪。", description = "你以前看過這種深岩剝石怪嗎？嗯，你當然有啦！你差點就被一頭吃掉了！\n\n牠們有點太靠近我和我的族人的聚落了，需要有人處理一下。洞穴裡、洞穴外，牠們無所不在！這也是我當初到這兒來的原因。\n\n既然我們要一起走一段路，你不如幫我個忙吧？", progress = nil, completion = "你跟那些剝石怪交朋友了嗎？\n\n哈！開玩笑的！我剛在說笑！除非你想成為飛撲剝石怪的美味點心，不然千萬別這麼做！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72873] = {title = "還不夠", objective = "跟著蜜毛長老，找到怒西昂和賽柏利安。", description = "孩子，你全身上下充滿著窮酸味。無法想像你到底是經歷多少磨難，才來到這裡。\n\n不過沒關係！我們鼴鼠人最樂於助人了。尤其是看到有人即將變成深岩剝石怪的點心，更不能棄之於不顧！\n\n我這個靈敏無比的鼻子聞得出來，你不是一個人來到扎拉萊克洞窟。我們把你從這些水晶救出來，一起去找你的朋友吧。", progress = nil, completion = "跟你說，我們找到你的同伴了！雖然他們背上似乎背了一大堆土。這只是一種比喻。\n\n總之呢！我救了你，如果你想報答我，可以幫我幾個忙。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72874] = {title = "父親的秘密", objective = "調查回收的文物。", description = "<name>，仔細看，看到這個埋在深岩剝石怪淤泥裡的奇怪金屬塊了嗎？\n\n自從我們進到這些洞穴裡，我就一直覺得暈頭轉向。我以為是因為怒西昂那個龍崽子一直吵個不停的關係，但這個東西證明我似乎弄錯了。\n\n我會繼續努力解開這個文物的秘密。請到附近的洞穴尋找類似的東西。令人不安的結論逐漸成形，但我們還需要更多資訊，才能下定論。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72875] = {title = "巨龍群島補給品", objective = "你好，冒險者。請收下這些物資，在你為我們奔走的時候，提供一點幫助！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n小型伊斯凱拉補給包"}
MultiLanguageQuestData['tw'][72876] = {title = "多件巨龍群島文物", objective = "你有要貢獻給文庫的東西嗎？", description = nil, progress = "你有要貢獻給文庫的東西嗎？", completion = "看看這些文物啊！這可能要花點時間。\n\n&lt;編目員潔可思匆忙地在她的記錄簿中寫下一些筆記。&gt;\n\n好了！你可以走了！找到更多的話再回來！", rewards = nil}
MultiLanguageQuestData['tw'][72877] = {title = "多件巨龍群島文物", objective = "你有要貢獻給文庫的東西嗎？", description = nil, progress = "你有要貢獻給文庫的東西嗎？", completion = "看看這些文物啊！這可能要花點時間。\n\n&lt;編目員潔可思匆忙地在她的記錄簿中寫下一些筆記。&gt;\n\n好了！你可以走了！找到更多的話再回來！", rewards = nil}
MultiLanguageQuestData['tw'][72878] = {title = "黏液直播現場", objective = "在扎拉萊克洞窟使用套索套捕8隻濕滑芳香螺，收集蝸牛黏液。", description = "親愛的$p，我可以再跟你說件事嗎？\n\n在我回洛姆之後，我注意到我們有些薰香壺不見了。\n\n薰香是我們用來標示貿易路線，還有協助我們找路回洛姆的工具。我們必須盡快補上遺失的薰香，這件事很重要。\n\n順帶一提，我們的薰香是用蝸牛黏液做的，所以你得先抓幾隻蝸牛來！\n\n在你成功之後，剩下的事情西卓斯會幫你。\n\n替我向瑪莉‧雪莉問好吧！", progress = "我們大部分的薰香都是用蝸牛黏液當基底來製成的。", completion = "歐蘭提亞派你來的嗎？這些蝸牛黏液品質很好，可以做成很優質的薰香！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72879] = {title = "彷彿族盟氣息", objective = "和西卓斯一起做鼴鼠人薰香。", description = "嗯，我們這一帶很少有地表人過來。\n\n蜜毛派你來找我一定有很好的理由，她通常不放心讓別人處理她的薰香。\n\n每個族盟的薰香都是他們自己的驕傲。每種薰香味道都不一樣，我們用它們來辨別彼此。\n\n製作薰香是個很精巧的過程。你到那邊的鍋子旁邊，我跟瑪莉‧雪莉可以協助你做些替代用的薰香。", progress = nil, completion = "以新手來說很不錯！你去把這些薰香放到該放的位置吧。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72880] = {title = "滿意薰香", objective = "在扎拉萊克洞窟放置9個遺失的薰香。", description = "你做出的薰香很有用。要做到這麼好，通常需要一點時間！\n\n我自己也忙著釀製東西，所以你得自己到外頭去，把那些薰香放好。\n\n等你完成後，蜜毛一定會想知道事情都辦好了。所以等你放好之後，最好跟她回報一下。", progress = nil, completion = "謝謝你，&lt;name&gt;！西卓斯有幫忙吧？", rewards = "您會收到：\n\n刺鼻的鼴鼠人薰香龍石"}
MultiLanguageQuestData['tw'][72881] = {title = "燕子的故事", objective = "在扎拉萊克洞窟和護燕者內弗羅談話。", description = "地表人！\n\n我是伊芙維絲塔，洛姆鼴鼠人的芳香夫人，也是領袖的女兒。別這麼客氣，你可以叫我伊芙！\n\n就當作我們之間的小秘密，我們送往葛利姆羅格的貨物有點進度上的拖延，而卓格巴對此一定不會開心！你幫了蜜毛長老這麼多…我想你應該也能幫我一把吧？\n\n我們的護燕者內弗羅對這件事應該比較了解。\n\n你能找他談談嗎？拜託你了！", progress = nil, completion = "真的嗎？你要幫忙？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72882] = {title = "飛出欄舍", objective = "在扎拉萊克洞窟找6隻失蹤的燕子。", description = "他們突然不見了！通通…不見了！\n\n所有的燕子，還有內弗羅，全部不見了！\n\n現在你說，伊芙維絲塔告訴你，我們要送去給卓格巴的燕窩耽擱了？\n\n這實在太糟糕了，地表人。\n\n如果你想幫忙的話，那就盡你所能去找燕子吧，帶越多回來越好。\n\n在這同時，我會想辦法看看有沒有可以用的燕窩來給卓格巴。", progress = nil, completion = "噢，幸好你找到了一部分的燕子！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72883] = {title = "難以下燕的真相", objective = "把死掉的燕子拿去給辛楠。", description = "<一隻穴燕的屍體躺在洞穴的地上。你應該跟辛楠說這件事。>", progress = nil, completion = "現在誰在乎一隻死燕子啊，伊芙失蹤了！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72884] = {title = "探尋伊芙維絲塔", objective = "在扎拉萊克洞窟尋找伊芙維絲塔位置的線索。", description = "我女兒失蹤了！我們得去找她！\n\n身為至香者，我可能是下個目標。$p，你願意陪我嗎？\n\n我還可以聞到她的微弱氣味。她一定還在洛姆。\n\n我們動作得快一點！", progress = nil, completion = "看啊，上面有一個洞穴！她一定就在裡面。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72886] = {title = "揪出假冒者", objective = "在扎拉萊克洞窟內擊敗內弗羅並拯救伊芙維絲塔。", description = "我聞到的味道…是內弗羅嗎？！\n\n假如犯人是他，那失蹤的貨物一定也跟他有關！\n\n$p，我要是進去可能會不安全。\n\n請你救出伊芙吧！", progress = nil, completion = "伊芙！幸好她沒事！", rewards = "您會收到：\n\n至香者的禮物龍石"}
MultiLanguageQuestData['tw'][72891] = {title = "禁忌之境 2/6", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72893] = {title = "禁忌之境 2/5", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][72894] = {title = "禁忌之境 2/4", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
