MultiLanguageQuestData['tw'][72900] = {title = "骨窖看守者", objective = "跟賽諾苟斯在隱蔽骨窖見面。", description = "你好啊，<name>。我正忙著找出其他藍龍的下落，不過另外有件事需要你幫忙。\n\n雅立史卓莎和我有個計畫，想好好安置瑪里苟斯和辛德拉苟莎所留下的精華。\n\n雖然距離這兩頭巨龍被殺已經過了一段時間，但是雅立史卓莎依然持有著他們的精華。\n\n賽諾苟斯告訴我，龍類曾經把隱蔽骨窖當成族人的長眠之地。不幸的是，那個地方現在是一片狼藉。\n\n他已經跟斯黛拉苟莎先去那一帶進行整理工作了。你可以去幫他的忙嗎？", progress = nil, completion = "準備好了嗎？", rewards = "您會學到：\n\n蒼藍高地第1章完成\n\n下列法術會施放在您身上：\n\nPlate Fly Off Right\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72908] = {title = "千里眼", objective = "檢查附近的焰視圖騰，找出啟動守衛塔頂層的大型焰視圖騰的方式。", description = "我沒料到加拉登會出現在這裡，但我也不驚訝就是了。根據傳說，他們的長老在大地的深處沉眠。因此有人會潛入地底尋找他們也很合理。\n\n他們的部隊正在嚴密把守這個外圍區域。我認出他們的斥候使用的魔法，那是遠視魔法，力量來源是附近的圖騰。\n\n我在附近的塔頂發現更大的圖騰。如果你能找到啟動它的方式，我們就能用它從遠處搜索火山口。", progress = "這座塔是這個火山口最好的瞭望點。\n\n如果菲拉卡來了，或發生更糟的事，一切動靜都一目了然。", completion = "&lt;厄比西昂瞇起眼睛，陷入沉思。最後他深深嘆了一口氣，並咬緊牙關。&gt;\n\n我們還不能行動。我們需要更多情報，並找到更好的突破口。", rewards = "贈禮披肩繼承肩冑遺贈肩甲授禮肩鎧您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72909] = {title = "薩克利傳說", objective = "檢查遺留在長老聖壇附近的薩克利所有物。", description = "因為我們最近的衝突，我一直在研究加拉登的事情。我們的檔案庫沒什麼他們長老的資訊。\n\n根據傳說，他們以前是偉大的督軍，現在沉睡在地底。加拉登認為長老會甦醒並帶領他們對抗龍族，殘暴地取得勝利。\n\n我們需要了解自己的對手。我們的正下方有個空聖壇，跟那些長老沉眠的地方很像。\n\n我們或許能在那裡找到一些情報。", progress = nil, completion = "根據我們目前收集到的情報，伊瑞迪柯隆似乎已經跟薩克利達成協議，派了洪荒使者去喚醒他們的長老。\n\n是因為他們有共同的敵人嗎？還是伊瑞迪柯隆因此得到某種回報嗎？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72910] = {title = "知己知彼", objective = "從空聖壇附近的薩克利加拉登身上，收集8件薩克利裝備。", description = "那個加拉登人稱她的族人為「薩克利」，不過根據我的部隊回報，並未顯示有第二個加拉登部族在巨龍群島活動。我不喜歡在戰爭裡面對未知狀況。\n\n我們會需要盡量了解他們，而且要快，這樣才能評估他們的優勢和劣勢。根據我的認知，了解一個文化的最好方式就是檢視他們戰鬥的方法。\n\n殺死你在附近發現的所有敵人，收集他們的武裝。我會等你來向我回報。", progress = "有關敵人的任何細節都值得重視。一切都能拿來對付他們。", completion = "看來，這些薩克利的魔法天分比喀拉希好上許多。\n\n真糟糕。\n\n比起陌生的敵人，還是對付老對手比較好，不過我會據此調整我們的策略。", rewards = "龍槌移形石魔杖黑土旋刃未明之天法杖暗釘飛岩槍元龍裂斧綴鱗泰坦之齒接地石法器無比堅硬之牆您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72911] = {title = "擒賊先擒王", objective = "殺死聖壇守衛者奎諾許和裂地者庫希瓦。", description = "在你和厄比西昂不在時，我領悟了一件事情。\n\n那個腐化的火山口就在薩克利長老沉眠的牢獄跟他們軍營的中心。不管裡面有什麼東西，那都是洪荒使者的計畫的關鍵。\n\n而且那裡的守備很鬆散。只有一個洪荒使者和一個薩克利牧師。只要打倒他們，我們應該就可以發掘這一切背後的真相。", progress = nil, completion = "&lt;厄比西昂的目光在賽柏利安和火山口之間來回移動，呼吸變得急促。&gt;\n\n什麼…菲拉卡做了什麼？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72912] = {title = "後果", objective = "檢查賽柏利安的傷勢。", description = "暗焰…\n\n伊瑞迪柯隆早就知道暗焰在這裡嗎？是他腐化了他的兄弟嗎？還是菲拉卡禁不起誘惑？\n\n只有過於無知或傲慢的蠢貨才會去追尋它，自以為能夠掌控連奈薩里奧都掌控不了的黑暗力量。它就像壞疽一樣，一點一滴地侵蝕他，直到他屈服於瘋狂為止。\n\n菲拉卡也會落到相同下場。\n\n我不會讓賽柏利安跟他們一樣。\n\n在我把你們送到安全的地方之前，他已經被燒得體無完膚。我們來評估一下他的傷勢吧。", progress = nil, completion = "如果菲拉卡正在吸收注入火山口的暗焰，我們需要更多幫手，才能阻止他。\n\n不過，我們得先清除賽柏利安傷口的腐化，再來考慮這個。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72913] = {title = "戰場檢傷", objective = "收集5個空的元素核心和1個薩克利烈焰圖騰。", description = "現在的狀況不太樂觀，我們必須臨機應變。我能將火焰引導至土裡來產生岩漿。暗焰也會有類似效果。\n\n洪荒使者在附近召喚土元素。如果我們取出它們的核心，我就能用它們來阻止暗焰繼續侵蝕賽柏利安的傷口。\n\n薩克利的圖騰應該已經與這裡的元素生物同調。它將能大幅提高吸取過程的效率。\n\n賽柏利安必須跟我們一起來。我必須隨時留意他的狀況，這都是為了他好。", progress = "事不宜遲。暗焰會在不知不覺中，迅速侵蝕心靈和肉體。\n\n我會盡一切所能阻止情況惡化。", completion = "我只希望這些東西足以用來舉行淨化儀式。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72914] = {title = "速戰速決", objective = "清除侵蝕賽柏利安傷口的暗焰。", description = "看前面！加拉登已經從火山口的東北側撤離，重兵部署在長老附近。\n\n在熔岩池邊有座祭壇，目前應該是安全的。我們可以把儀式用品設置在那裡。\n\n快點行動，在加拉登回來之前搞定。", progress = "菲拉卡和那些長老可以留待日後。\n\n要是失去賽柏利安，我們就全盤皆輸了。", completion = "賽柏利安的傷還沒好，不過已經清除他身上的暗焰了。\n\n我現在只能做到這樣。我會確保他之後有時間休息。", rewards = "您會收到：\n\n袖珍晦暗元素核心龍石"}
MultiLanguageQuestData['tw'][72915] = {title = "權宜之盟", objective = "殺死4個守衛伊吉拉聖壇的薩克利加拉登。", description = "洪荒使者會在加拉登大軍的保護之下，完成他們的工作。\n\n如果加拉登在對自己有利的條件下作戰，即使數量不多，仍會是難纏的對手。最好的方式是主動突襲，讓他們措手不及。\n\n解決他們。不能讓他們侵佔我們好不容易才開拓出的地盤。", progress = nil, completion = "很好。我們需要讓這個區域暫時保持清空。", rewards = "贈禮裹布贈禮斗篷遺贈披氅繼承披風您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72916] = {title = "搞破壞", objective = "摧毀3個大地汲取導引裝置和4個抽取的元素核心。", description = "洪荒使者正在前面喚醒薩克利的最後一個長老。\n\n我們先前使用遠視圖騰的時候，我觀察到他們從長老身上抽取了某個東西。現在我終於明白，那應該是為了驅散讓長老陷入靜滯的魔法。就跟我們淨化賽柏利安一樣，他們也使用元素核心來抑制魔法。\n\n讓菲拉卡吸收暗焰，絕對是一大災難，不過長老的甦醒卻是更迫切的威脅。我們必須阻止他們。", progress = nil, completion = "希望我們為自己爭取到足夠時間，能夠等到援軍到來。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72917] = {title = "來自地獄中心", objective = "協助賽柏利安殺死菲拉卡。", description = "我們不能再讓菲拉卡安穩地躺在這裡，透過暗焰改造自己，成為與死亡之翼不相上下的威脅。我們必須出擊！這麼做會有危險嗎？會的，但是再不行動只會有災難性的下場。\n\n我曾經僅憑爪子撕裂古羅。那些戰鬥就像在賭博，不過這次不一樣。用屠龍武器殺死元龍，這是再正常不過的事。完全合情合理。不會有任何意外。\n\n既然現在有機會結束這一切，我絕不會猶豫不決。", progress = nil, completion = "我們…失敗了…", rewards = "贈禮長袍繼承衣飾遺贈鎖子甲授禮胸鎧您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72921] = {title = "再次出發", objective = "從賽諾苟斯那獲得特殊視力，然後找回不見的典籍。", description = "啊…你說隱蔽骨窖啊。我曾在那裡擔任類似墓地看守者的角色，不讓野生動物靠近也是我的職責之一。\n\n我在這個地方藏了幾本典籍，並在那些典籍上留下了幾個「有趣」的咒語，讓那些東西不敢靠近這裡。\n\n其他藍龍不太認同我這種…魯莽的做法，所以那時我把典籍刻意藏了起來。\n\n我來幫你施個咒語，這樣你就能看見那些舊典籍並找到它們了。\n\n把典籍全部找來後，我們就可以把入侵這裡的野生動物處理掉了。", progress = "你有找到我的舊典籍嗎？", completion = "他們就在那邊！很高興有生命能在那麼久之後仍然活了下來。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72922] = {title = "褪色的餘燼", objective = "到磺石要塞協助安珀莎阻止沙卡瑞斯。", description = "局面很艱困，我的朋友。創傷和不安全感沒辦法輕易消除。只有時間和合作，才能撫平這種長期抗爭帶來的刺痛。\n\n但是我們還有很緊急的事要處理。如果有一大批龍獸還是堅決效忠奈薩里奧的記憶，這片土地的危險程度將會超乎我們的預期。\n\n安珀莎仍獨自在追捕沙卡瑞斯。必須讓她意識到周遭的威脅。我們必須找到並協助她。", progress = nil, completion = "沙卡瑞斯或許想要躲在亞貝魯斯強大的力量之後，但這幫不了他。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72923] = {title = "與賽柏利安密談", objective = "到加拉登襲擊點與賽柏利安談話。", description = "少了賽柏利安和他堅毅又強大的龍族，我們對磺石要塞的襲擊便無法成功。我們必須說服他，我們的目標是一致的。\n\n要是我們以謀士和將軍的身分來遊說他，他一定會幫我們的…希望如此。\n\n他和他的軍隊就在加拉登襲擊點。", progress = nil, completion = "或許我們可以聯手起來戰鬥。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72924] = {title = "向黑龍王子求助", objective = "到黑曜之眠與怒西昂談話。", description = "少了陰險又善於計策的怒西昂和他的黑爪密探，我們的襲擊不會成功的。我們必須說服他來幫我們。\n\n幸好，我知道他的為人，他不會拒絕任何需要他的人…尤其是奉承他的人。\n\n我們去黑曜之眠找怒西昂，試著說服他吧。", progress = nil, completion = "很高興他願意加入我們。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72925] = {title = "集各方之力", objective = "到磺石要塞與安珀莎談話。", description = "安珀莎正在磺石要塞方等我們。\n\n來吧，<name>。看到我們集結了整個黑龍軍團的勢力來協助她達成目標，她一定會很高興的。", progress = nil, completion = "只要我們團結一心，任何事物都阻止不了黑龍軍團。", rewards = "您會收到：\n\n套裝：黑龍軍團法衣龍石"}
MultiLanguageQuestData['tw'][72926] = {title = "寶劍贈英雄", objective = "從磺石要塞取回黯黑剜割者和長眠之刃。", description = "有幾件具有歷史價值的武器，我相信它們已在時間的洪流中失落了。我願意用我的爪子打賭，它們就在這個要塞中。\n\n龍裔和龍獸忠誠地依附於我死去已久父親的記憶。一群被洗腦的蠢貨。\n\n他們可以接觸到我父親的鍛爐和武器，而且我認為遺失的武器很可能就存放在附近。\n\n如果他們發現自己所擁有的武器，就會用來對付我們，所以不能落在他們的爪裡。", progress = "絕不能讓這些蠢貨掌握這麼強大的武器。", completion = "我們真是合作無間，我的朋友！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72927] = {title = "尋找沙卡瑞斯", objective = "在亞貝魯斯通路中和安珀莎會面。", description = "既然我們在要塞中有了立足點，我們就可以擴大搜索範圍。我們會在這裡抵擋亞貝魯斯的部隊，你去找安珀莎，陪她去見沙卡瑞斯。我們會先守住這裡的陣線，隨後再加入你們。", progress = nil, completion = "他在那裡。\n\n當他操作那部裝置時，亞貝魯斯也在保護他。一定有辦法破開他的防禦！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72928] = {title = "解決他們", objective = "在磺石要塞擊敗效忠奈薩里奧的磺石部隊。", description = "當我看著磺石要塞的時候，你知道我看到什麼嗎？\n\n叛徒。\n\n這些士兵自以為是黑龍軍團的追隨者，卻忽視我們這些真正的奈薩里奧繼承人，屈膝於我們惡毒父親的亡靈。\n\n這讓人不能忍。\n\n讓他們知道自己做錯事了。", progress = nil, completion = "真可惜，這些戰士是為錯誤的理想效忠。他們本來會是很棒的盟友，但他們被自己偏頗的忠誠給害了。", rewards = "您會收到：\n\n幼龍暗焰紋章龍石幼龍夢境紋章"}
MultiLanguageQuestData['tw'][72930] = {title = "阻止沙卡瑞斯", objective = "在亞貝魯斯通路擊敗可怕的防衛者。", description = "這是我們的最後機會，<name>。要是我們讓沙卡瑞斯溜進亞貝魯斯，他可能會獲得超越我們的力量。我們必須現在阻止他！", progress = nil, completion = "他毫不在意效忠他的半龍人。他在乎的只有自己。\n\n&lt;安珀莎振作起來。&gt;\n\n他跟我們已經形同陌路了。", rewards = "您會收到：\n\n尊敬印章飛龍暗焰紋章龍石幼龍夢境紋章"}
MultiLanguageQuestData['tw'][72931] = {title = "前線營地", objective = "到磺石要塞找厄比西昂。", description = "既然沙卡瑞斯已經得到亞貝魯斯防禦的力量，就代表他有一支軍隊保護著他。\n\n我們的下一步是在內部建立一個據點，以便能不受打擾地搜索整個要塞。\n\n我會在那裡等你。", progress = nil, completion = "很好。我們現在可以安全地支援安珀莎的搜索工作了。我知道她一定能成功阻止沙卡瑞斯。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72933] = {title = "一球帶走", objective = "使用賽諾苟斯的秘法球捲起隱蔽骨窖內潛伏的各類生物", description = "我還記得以前我會用咒語把那些生物通通滾成一團，那真是好玩。可惜我老了，現在的身手已經沒有以前一樣快了。\n\n我很樂意讓你試試看，讓我透過你來回味當年的樂趣吧！\n\n滾成一團的各類生物越多，球就會越大；球滾得越大，就能把體型更大的生物捲走。\n\n跟我說話，我就會給你我特製的秘法球，你可以用它來捲起附近的各類生物。", progress = nil, completion = "做得好！啊，我感覺彷彿又年輕了起來。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72934] = {title = "不忘先龍", objective = "翻新逝世藍龍的墓碑", description = "卡雷苟斯和雅立史卓莎很快就會到了。在那之前，我想請你做一件事。\n\n在死前事先立好墓碑，是我們的傳統習俗。這樣你才能知道自己離世後，會在哪裡長眠。\n\n墓地看守者的工作，就是定期翻新墓碑並存入附近殘留的精華。\n\n在我們的客人到訪前，你可以先幫我完成這個工作嗎？\n\n把這份清單拿去，開始處理這些墳墓吧。翻新既有的墳墓，然後把新的也設置好。", progress = nil, completion = "謝謝你，&lt;name&gt;。現在一切準備完成，只等客人到來了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72935] = {title = "重回文庫", objective = "返回蒼藍文庫去見卡雷苟斯。", description = "瑪里苟斯和辛德拉苟莎擁有如此強烈的回憶並非罕見。\n\n據我所知，他們死前經歷過極大的痛苦。他們都是被冒險者殺死的。\n\n想到辛德拉苟莎在被巫妖王復活後必須再次經歷死亡，就讓我難過不已。\n\n我這頭老龍還是別繼續囉唆了。我跟斯黛拉苟莎會在蒼藍文庫跟你碰面。", progress = nil, completion = "謝謝你的協助，&lt;name&gt;。如你所見，有更多藍龍抵達了！\n\n不過…有些還是沒出現。我們可不能忘了他們。\n\n關於瑪里苟斯和辛德拉苟莎的回憶這件事，我會盡力掌握更多相關資訊。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72936] = {title = "艾索雷苟斯的支援", objective = "前往北裂境的奧核之心跟艾索雷苟斯見面。", description = "許多藍龍都回來了，還有很多龍告訴我他們有回來群島的計畫。\n\n儘管如此，仍有幾名巨龍軍團的關鍵成員沒有音訊。\n\n他們之中有幾個可能可以幫上我們的忙。例如駐紮在北裂境奧核之心的艾索雷苟斯。\n\n我用盡一切方式和艾索雷苟斯聯絡，但是到目前為止他都沒有回覆，所以我、你還有辛德拉苟莎將親自去一趟。\n\n多虧誓言石已經重新啟動，辛德拉苟莎現在可以自由在群島地區和我的所在地之間自由往返了。", progress = nil, completion = "也許卡雷苟斯來的時機沒有我想的那麼糟…如果他有把辛德拉苟莎的幻象帶在身上，那情況就會更樂觀。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72937] = {title = "不尋常的干擾", objective = "打倒奧核之心內的古怪秘法攻擊者。", description = "我當然能幫忙找出失聯藍龍的下落。不過，現在我手邊有個麻煩需要我處理。\n\n不久前，奧核之心經歷了數次秘法能量爆發的衝擊，緊接著就遭到某種古怪秘法怪物的襲擊。\n\n如果你能掃蕩這股無主秘能的源頭，我就能幫你創造追蹤藍龍的方法。\n\n這東西給你，小心別摔壞了。把它帶到奧核之心裡的三個地點去，然後使用它。噢，別忘了做好戰鬥準備。", progress = nil, completion = "嗯…情況看起來似乎平靜許多。\n\n不過，我最好去確認一下這些失控回憶到底造成了多大的影響。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72938] = {title = "文庫見聞", objective = "返回蒼藍文庫。", description = "我製作了一個魔法球體，它能幫你找出其他藍龍的約略位置。\n\n現在，請離開吧。除了我手邊的研究工作外，我還得趕快去調查那些攻擊奧核之心的「回憶」。\n\n我一定會徹底研究清楚這件事。", progress = nil, completion = "希望艾索雷苟斯之後會加入我們。\n\n與此同時，我們還有整個艾澤拉斯需要搜。", rewards = "您會收到：\n\n飛龍暗焰紋章碎片龍石飛龍夢境紋章飛龍覺醒紋章"}
MultiLanguageQuestData['tw'][72939] = {title = "塞拉摩", objective = "告訴卡雷苟斯，蘇莉苟莎最後的已知位置。", description = "根據艾索雷苟斯的筆記，藍龍蘇莉苟莎最後一次出現時，她正在調查一個叫做「不潔旌旗」的叛亂法師組織。\n\n蘇莉苟莎的最後一封信，說她打算前往已成廢墟的塞拉摩。也許她在那裡發現了不潔旌旗黨羽的蹤跡。無論如何，如果蘇莉苟莎還活著，塞拉摩應該會是最有可能找到她的地方。", progress = nil, completion = "塞拉摩？那是我最不想回去的地方…但如果蘇莉苟莎在那裡，也許她在那裡有任務要執行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72940] = {title = "失聯的藍龍到底在哪裡？", objective = "選擇一個區域，開始找尋失聯的藍龍。", description = "艾索雷苟斯縮小了失聯藍龍可能所在地的範圍。\n\n我們每個人各負責其中幾個成員吧。相信你能幫我們找到這幾頭龍的。\n\n請選擇你想從哪裡開始。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72942] = {title = "隱蔽的麻煩", objective = "調查隱蔽骨窖內的秘法異象。", description = "我原本希望大家可以找出方法，驅散來自瑪里苟斯和辛德拉苟莎殘留精華的古怪秘法回憶。\n\n我沒預料到這些東西會繼續成長，變得更加失控。\n\n請帶幾頭藍龍到隱蔽骨窖，幫助艾索雷苟斯吧。\n\n辛德拉苟莎和我會在這裡繼續研究，嘗試找出這個狀況的解決方法。", progress = nil, completion = "我想這就是卡雷苟斯說的「團隊合作」吧。\n\n似乎還是能派上用場的樣子。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72944] = {title = "傳訊石：抗議", objective = "找到傳訊石。", description = "<這個傳訊石仍保存著艾達曼希亞以古龍語傳給奈薩里奧的古老訊息。>\n\n<龍隊指揮官一定會對裡面的內容感興趣。>", progress = "有什麼發現？", completion = "嗯…這顆石頭真的出人意料。\n\n看來艾達曼希亞的行為也還算合理。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72946] = {title = "隱蔽骨窖的混沌", objective = "讓秘法入侵者對隱蔽骨窖的控制力下降。", description = "瑪里苟斯和辛德拉苟莎的精華產生了這規模龐大的秘法干擾。\n\n他們的回憶在隱蔽骨窖中四處遊蕩，還試圖從墳墓中汲取秘法能量！\n\n即使我們聯手合作，似乎也只能限制住這些能量。我們必須阻止附近一帶的回憶。\n\n只要這些回憶被驅散，我們就能驅散這個屏障，並處理裡面的精華。", progress = nil, completion = "屏障的力量變弱了！做得好。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72947] = {title = "昔日回憶", objective = "殺死隱蔽骨窖內的三個強大回憶。", description = "隱蔽骨窖內部出現了三個力量非常強大的回憶。\n\n他們的能量很快就會成長到可以自行製造秘法傀儡的地步…到時這個地方會完全被秘法傀儡佔據。\n\n打敗他們，這樣我們才能削弱屏障的力量，並處理瑪里苟斯和辛德拉苟莎的精華！", progress = nil, completion = "這一帶的混沌波動正在逐漸平息。告訴我，你看到什麼回憶？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72948] = {title = "揮之不去", objective = "穿越秘法屏障，取回瑪里苟斯和辛德拉苟莎的精華。", description = "屏障的力量正在減弱，謝謝你的協助。它應該很快就會被打破了。\n\n我們的主要優先任務，就是取回瑪里苟斯和辛德拉苟莎的精華。在讓精華安息的過程中，出了某種嚴重的錯誤。關於回憶目前的狀態，我有幾個可能的理論。我們可以在路上討論。\n\n準備好的時候告訴我一聲。", progress = "看來，藍龍還是無法完全從過去走出來。", completion = "想不到出於慈悲善意的舉動，竟會造成這樣的結果…\n\n我想，所有人都低估了仍埋藏在辛德拉苟莎和瑪里苟斯心中的憤怒。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72949] = {title = "火速回到文庫", objective = "回蒼藍文庫去跟卡雷苟斯見面。", description = "我能從這些精華中聽見憤怒與痛苦的喊叫聲。\n\n我猜這是在嘗試讓他們獲得平靜時觸發的現象。\n\n他們已經休眠許久，但是瑪里苟斯和辛德拉苟莎的怒火在結合之後，產生了這樣的現象。\n\n我們必須趕快前往蒼藍文庫，把這件事情告訴卡雷苟斯和辛德拉苟莎。\n\n若結合眾人之力，也許我們有機會幫助瑪里苟斯和辛德拉苟莎獲得真正的平靜。", progress = nil, completion = "很高興看到你們找回了辛德拉苟莎和瑪里苟斯的精華。\n\n我從沒想過，想要幫助他們的靈魂找到平靜會導致這樣的結果。", rewards = "您會收到：\n\n飛龍暗焰紋章碎片龍石飛龍覺醒紋章"}
MultiLanguageQuestData['tw'][72950] = {title = "最終衝突", objective = "制服蒼藍密庫內瑪里苟斯和辛德拉苟莎騷動的靈魂。", description = "瑪里苟斯和我在死前都經歷了極大的痛苦。我們殘留的精華，都被困在了無盡的迴圈之中。\n\n我們必須重塑精華並打破迴圈，才能讓精華脫困。不過，我們需要非常多的高密度能量才能做到這一點。\n\n我們可能必須動用蒼藍文庫裡所有的秘法能量…再加上所有重聚藍龍的秘法能量。\n\n若想重塑這些靈魂並終結它們受到的折磨，這是我們唯一的機會。", progress = nil, completion = "瑪里苟斯和辛德拉苟莎的靈魂現在終於能安息了。再次謝謝你的幫忙，&lt;name&gt;。\n\n還有最後一件事要做，這事非常重要。", rewards = "您會收到：\n\n高地飛龍：腿有尖刺龍石"}
MultiLanguageQuestData['tw'][72951] = {title = "平靜的告別", objective = "跟賽諾苟斯說最後一次話。", description = "眼見眾藍龍如此團結，而瑪里苟斯和辛德拉苟莎也獲得了平靜，使我心雀躍。\n\n是時候了，我想給大家最後一個禮物。這是藍龍很長一段時間沒見過的東西。\n\n一頭安祥逝世的藍龍。\n\n我的時候到了，<name>。我其實一段時間前就該走了，但是看到藍龍分崩離析的狀況，我不放心就這樣離世。\n\n如果你能到場送我一程，我會感到十分榮幸。", progress = nil, completion = "賽諾苟斯…他給了我們所有人一份珍貴的禮物。\n\n謝謝你，&lt;name&gt;。要是沒有你，我真不知道自己能不能讓藍龍團結起來。為此我將永遠感激你的協助。\n\n是時候帶領大家展望未來了。", rewards = "您會收到：\n\n套裝：蒼藍復原華服蒼藍龍石龍石"}
MultiLanguageQuestData['tw'][72952] = {title = "嚇人的優爾密庫", objective = "進入並探索澤斯克拉密庫：優爾。", description = "塔恰有靈敏的聽覺，他聽見坑道中有聲音。我們朝裡面偷看了一眼。說真的…裡面真的很黑。蠻嚇人的。裡面有各式各樣可怕的生物。我跟塔恰真的不擅長近距離對付那種東西。\n\n你有對付怪物的經驗，對吧？非常好。你先請吧。別擔心。確定裡面安全之後，我們就會進去找你。這是我們的極限了。", progress = nil, completion = "你的表現相當出色。真是太勇敢了。只要找到更多鑰匙，就能繼續探險了。\n\n當然不是所有密庫都像這裡一樣嚇人啦。可能喪命嗎？當然。各種奸詐的設計？這還用說。但是，可能不會這麼嚇人。大概吧。\n\n我們保持聯絡。再過幾天，我們會做好準備，開始探索另一個密庫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72953] = {title = "澤斯克拉密庫：亞茲", objective = "進入並探索澤斯克拉密庫：亞茲", description = "我們在島嶼下面發現了多個密庫。奈薩里奧在裡面藏了許多寶藏、各式各樣的小玩意兒，還有失敗的實驗成果。\n\n我說他有囤積癖，可不是在開玩笑！他的東西填滿了無數房間，這些東西無人聞問了好長一段時間，到現在才重見天日。寶藏就在這些鎖住的門後等著我們！對了，有時候可能會是死亡陷阱。不過，也可能是寶藏喔！現在我們有能打開這些門的鑰匙。", progress = nil, completion = "做得好。只要繼續找來鑰匙，我們就能繼續探險。我相信再過幾天，我們就會開始探索另一個密庫。\n\n這些密庫的名稱，好像是某種編號。亞茲、優爾、伊克斯、基克斯…這些代號一定有某種意義。別誤會，我絕對是全心全意在找寶藏，但是在過程中學點東西也不賴，對吧？說不定喔。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72954] = {title = "澤斯克拉密庫：伊克斯", objective = "進入並探索澤斯克拉密庫：伊克斯", description = "沃福德早上發現有群海盜正在朝密庫前進。我們必須趕快行動，否則密庫可能會被他們搜括一空！\n\n我們立即朝密庫出發吧。不能再浪費時間了。你願意加入我們嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72955] = {title = "澤斯克拉密庫：基克斯", objective = "進入並探索澤斯克拉密庫：基克斯。", description = "我擔心的事成真了。碎裂火焰軍來了，而且他們也發現了密庫。\n\n當然，我們必須阻止他們。他們會把任何有用或是危險的東西直接搶走，交給沙卡瑞斯。\n\n我受夠他給我們帶來的麻煩了。是時候讓他們見識你的能耐了。", progress = nil, completion = "你的表現相當出色。只要找到更多鑰匙，就能繼續探險下去。我們很快就能找到另一個密庫並開始探索了，只是早晚的問題…最多再過幾天吧。\n\n噢，祝你在對付碎裂火焰軍時一切順利。看到半龍人與半龍人自相殘殺，我感到十分遺憾…特別是考慮到現在的狀況而言。我們可以合作發掘過去的秘密，而非掀起內戰。在外面多保重。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72956] = {title = "更多還沒開啟的門", objective = "進入並探索其他澤斯克拉密庫", description = "還有更多密庫，但我們人手不夠，無法全部探索。\n\n這時候就輪到你登場了。你可以去找更多鑰匙嗎？這樣我們就能繼續探索密庫。\n\n我和塔恰會待在這裡，努力記錄我們先前的發現。這是個艱鉅的任務，但總得有一個人去做。好吧，是兩個人。我向你保證，這真的要花不少功夫。", progress = nil, completion = "看看你！又是開門！又是冒險！一點也不悶。\n\n抱歉，有點冷。你的表現相當出色。只要我們有鑰匙，就能繼續探險下去。我非常肯定，再過幾天，我們就能找到另一個密庫。\n\n就你和我！還有塔恰！一起探索未知。好啦，大部分是你，不過我們還是有幫忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72958] = {title = "救地鼠", objective = "找到並拯救圖貝洛斯和他的地表人客戶。", description = "佩里西莫納跟我說了她的生命伴侶圖貝洛斯的事情，也說了跟他的失蹤有關的資訊。\n\n圖貝洛斯當時正帶著一名龍鱗遠征隊的客戶探索這一帶的遺跡。聽起來他們是遇到了碎裂火焰軍。\n\n我不想親自去追蹤碎裂火焰軍。這麼做會讓沙卡瑞斯知道我的存在。\n\n你願意協助我們找尋並救援圖貝洛斯和他的客戶嗎？到時候，他或許就能引導我們到奈薩里奧寶庫去。", progress = nil, completion = "我們該回歸我們來這裡的正題了：尋找沙卡瑞斯。\n\n我會把鼴鼠人和瑞南送回洛姆，那裡比較安全。", rewards = "贈禮束帶繼承環帶遺贈繫腰授禮束腰您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72959] = {title = "這到底是誰的密庫？", objective = "準備好後跟安珀莎談話。", description = "我不知道我們會在密庫裡找到什麼，或是沙卡瑞斯想進去的原因，不過我希望我們可以及時趕到。\n\n在我們繼續前進之前，圖貝洛斯應該帶瑞南和佩里西莫納回洛姆去。\n\n準備好繼續前進時，就來找我吧。", progress = nil, completion = "我還是覺得，我們應該先送他們回洛姆，不過我相信厄比西昂的判斷。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72961] = {title = "充能中", objective = "為瑞南‧寇倫收集6個嗡鳴球體核心。", description = "安珀莎想要昨天就處理掉沙卡瑞斯這個傢伙。我理解！我也討厭乾等。\n\n這扇門難以破解，真令人沮喪…但是！我有一個計畫，因為我總是會有計畫！我的成功秘訣就是領先別人一步，這到目前為止可以說是都很有效！\n\n所以，關於這個計畫…我可能需要你的幫助！", progress = "你幫我拿到一些球體了嗎？", completion = "圖貝洛斯救了我！這些就行了！現在，給我一點時間搞懂能量竄流還有…嗯…對…不，不對，好，或許…", rewards = "您會收到：\n\n嗡鳴球體核心龍石"}
MultiLanguageQuestData['tw'][72962] = {title = "芝麻開門！", objective = "向瑞南詢問他的進展。", description = "很高興我們有進展了，但是…我一直有種預感，裡面似乎有什麼在等著我們。隨著沙卡瑞斯越來越了解奈薩里奧，他的意圖似乎變得越來越黑暗。\n\n我不敢想像他現在會對他的族人說什麼事…關於我和其他半龍人的事。他將永遠分裂我們的族人。\n\n和瑞南談談，看看我們還得等多久。分秒必爭。", progress = nil, completion = "沙卡瑞斯絕不會獨自來到這裡，&lt;name&gt;。建議你跟緊大家，保持警戒。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72965] = {title = "傳承之龍", objective = "到洛姆跟厄比西昂碰面。", description = "我很自豪能看見安珀莎正再次綻放自信的領袖風采。她的人民需要她。\n\n但沙卡瑞斯找到了誓縛者，這令人想起了奈薩里奧傳承的恐怖和追隨他的愚行。\n\n我感覺我們在這些洞穴裡發現的不只會是他的飾品和低語，還有其他更多物品。\n\n來吧。我們有很多事情要討論。我們先回到洛姆，看看我的兄弟們是否找到了制伏菲拉卡的方法。", progress = nil, completion = "我…厄比西昂的譴責讓我很震驚。\n\n任何奈薩里奧藏起來的力量之物，對我們來說都是一種恩賜。\n\n但他說得沒錯…如果我想成為一名守護巨龍，我就必須要向大家展現黑龍軍團真正繼承者擁有的力量。\n\n我會從菲拉卡開始。", rewards = "贈禮馬褲繼承護腿遺贈裙甲授禮護脛您會收到：\n\n閃亮的謝意信物龍石"}
MultiLanguageQuestData['tw'][72966] = {title = "有煙的地方就有火", objective = "到薩克利火山口外跟厄比西昂和賽柏利安碰面。", description = "要是你跟厄比西昂的夥伴聊完天了，我們就來談談更迫切的事。\n\n找到菲拉卡仍是我們的首要任務。我們不能再拖延下去了。\n\n我在扎拉萊克的西側邊緣發現一個巨大無比的火山口。如果菲拉卡還在這裡，可以合理推斷他應該就躲在這片火山地帶。\n\n到那裡跟我們會合，準備展開下一步。", progress = nil, completion = "你順利抵達了。很好。\n\n我們還沒找到菲拉卡，但看到加拉登了。他們的數量好多。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72970] = {title = "鼴鼠人與巨人", objective = "殺死深岩剝石怪育母。", description = "你要知道，我來這裡，不光是幫你們這些無毛的傢伙擦屁股。\n\n深岩剝石怪就跟壓實的泥巴一樣邪惡又難搞。我們試過留下食物之類的方法，看看能不能讓牠們打消攻擊我們城市的念頭，不過牠們全都非常熱衷於襲擊我們的麻雀商隊。\n\n真正麻煩的是率領牠們的大傢伙。想報答我嗎？那就由你、我和這個噴古龍水的傢伙一起來獵殺一隻吧。我已經準備好最完美的誘餌！", progress = nil, completion = "嘖！剛才真是一次苦戰，對吧！", rewards = "贈禮束腕繼承腕環遺贈護腕授禮護臂您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72972] = {title = "甦醒海岸巡迴賽道逆向版", objective = "在甦醒海岸的每個逆向版賽道飛行。", description = "該讓你回去了。當然不是時光倒流，雖然我們的確做得到，而是要你逆向再飛一次賽道。\n\n準備好從不同角度體驗這些賽道。\n\n我們先從「賽羅斯金卡」開始吧！\n\n等等。應該是甦醒海岸！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72973] = {title = "洛姆之味", objective = "到洛姆跟蜜毛長老碰面。", description = "我從一開始就聞得出來，你不是壞人。有點汗味，但不是一個壞傢伙。\n\n你可以把這個視為進入洛姆的私人邀請函，那是鼴鼠人的家園。\n\n我們在入口外面會合吧。這樣一來，我就能用正式的鼴鼠人禮節，歡迎你和你的同伴！", progress = nil, completion = "歡迎來到洛姆，地表人！這是我們的香氣四溢之城！\n\n我叫歐蘭提亞，是這一帶的至香者。這只是比較花俏的說法，就是說我是這裡的領袖。這也代表著我負責保護族人不受上面來的危險和麻煩所害。\n\n不過，我們等下還有時間再詳細說明這些事情。厄比西昂和安珀莎已經告訴我目前的狀況，現在要不要在柔軟的土地上休息一下呢？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72974] = {title = "歡迎來到氣味之城", objective = "交付深岩剝石怪包裹並參觀洛姆。", description = "地表人，很壯觀對不對？\n\n接下來就是苦力活了，我們得把這個深岩剝石怪的肉送去給客戶，另外還得向他們收錢。我是可以自己送，不過，你看我這麼可憐、年老、虛弱又無助，你說是吧？\n\n<蜜毛朝你眨眨眼，動作十分熟練。>\n\n不如你來幫我送貨吧。布萊恩沙斯會負責那些粗重的工作，你就一邊跑腿，一邊參觀這個地方吧。拿出你們最有味道的幹勁。我們都很友善的！", progress = nil, completion = "還不賴啊，孩子。或許怪物獵手名單上還有空位可以寫上你的名字呢！\n\n開玩笑的！又一個笑話！我們沒有名單！只有一群渴望戰鬥的傢伙，跟我一樣非常有膽量。\n\n你總有一天也可以的，繼續努力。", rewards = "吐石者黑土戰刃嚴酷斬斧地縛軍刀衛地長杖黑龍之攫綴鱗泰坦之爪元龍分割刃難以撼動之牆央石法器您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72975] = {title = "下方的陸地", objective = "到沃卓肯的守護巨龍之座跟黑龍軍團碰面。", description = "生命守縛者有關於洪荒化身的消息，要求我們前往守護巨龍之座。\n\n<name>，黑龍軍團會在那邊等你。", progress = nil, completion = "守護巨龍已經都到了。我們不該讓他們久等。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72976] = {title = "世界的裂縫", objective = "與雅立史卓莎談話。", description = "如你所見，怒西昂和賽柏利安也準備一起出席了。如果守護巨龍有洪荒化身最新行動的消息，那就需要黑龍軍團的三大巨頭一起應付。\n\n來吧。他們迫不及待想跟我們談談。", progress = nil, completion = "我盡可能地閱讀過洪荒化身的相關記錄。\n\n菲拉卡就跟伊瑞迪柯隆一樣強大，只是欠缺控制力，無法將力量集中起來，達成特定目標。不管是燒死自己的追隨者，還是燒死我們的人馬，他都樂在其中。\n\n這場戰鬥將會關係到島上所有居民的存亡。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72977] = {title = "烈焰落下之地", objective = "到流瀑峽谷跟賽柏利安和怒西昂碰面。", description = "巨龍軍團向我們求援，而身為群島和龍族的保衛者，我們義不容辭。\n\n我必須找出安珀莎並邀請她加入。相信只要我們承諾在未來對抗碎裂火焰軍時站在她那一邊，現在她就會願意幫助我們。\n\n到洪荒化身造成災難的地點找賽柏利安和怒西昂。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72978] = {title = "大地與火焰之痕", objective = "調查現場。", description = "我們一到這裡，這個半人馬就作勢要攻擊我們。他似乎不想任何人靠近這堆燃燒的灰燼。\n\n我知道你以前跟席卡氏族合作過。可以去跟他談談嗎？我想弄清楚這裡發生了什麼事。\n\n這一切絕不可能是巧合。如果這跟洪荒化身有任何關係，我們就必須徹底查清。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72979] = {title = "大地的退讓", objective = "與怒西昂交談。", description = "你可以留在這裡看文物的後續發展，或之後到洛姆去跟我碰面。那是蜜毛的家，也是你還在洞穴內時，她讓我們休息的地方。\n\n我只希望你可以去找怒西昂，看他過得好不好。我同意，雖然有時他就像隻煩人的害蟲，但…最近發生的事情，讓我不得不承認，其實我也關心他的安危。\n\n留存在世上的黑龍不多了。我們必須照顧彼此才行。", progress = nil, completion = "那個多愁善感的賽柏利安還好嗎？\n\n什麼？光是開口問他的情況就已經夠關心他了！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72980] = {title = "兄弟的守護者", objective = "與賽柏利安交談。", description = "我的鱗片呀，我真的很需要贏一場！那該死的洪荒化身，完全不把我們放在眼裡，打我們跟打蒼蠅一樣。我的自尊受到嚴重打擊，我想賽柏利安大概也有一樣的感受。\n\n雖然他缺乏幽默感、聲音難聽、鞋子還很醜…我還是希望你去看看他過得好不好。無論如何，他都是我的家人，我不希望成為那些深岩剝石怪的晚餐。\n\n等你跟賽柏利安的事情結束後，跟蜜毛和我在這些可怕的巢穴外見面吧。", progress = nil, completion = "來這裡的路上，一路上都能聽到你和怒西昂鬼吼鬼叫。\n\n要是你說夠了，就來看看這個吧，&lt;name&gt;。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72981] = {title = "王子們的耐心", objective = "鑽入地底，摧毀洪荒使者設下的障礙物。", description = "半人馬的回報，自從菲拉卡改變情況後，洪荒部隊正在朝地下推進。怒西昂和我認為不該在此地逗留，等待厄比西昂和他的追隨者到來。這是一個戰術上的失誤。\n\n但我們仍希望你可以加入我們。若你準備好了，我們三個可以一起前進。", progress = nil, completion = "說你渾身散發迷路的「味道」，都還算客氣了！", rewards = "您會收到：\n\n碎石者龍石"}
MultiLanguageQuestData['tw'][72982] = {title = "雍亞拉平原巡迴賽道逆向版", objective = "在雍亞拉平原的每個逆向版賽道飛行。", description = "繼續前進，再逆向飛一次吧。\n\n雍亞拉平原有更多比賽等著你。馬上前往那裡，記得確定自己沒弄錯方向。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72984] = {title = "蒼藍高地巡迴賽道逆向版", objective = "在蒼藍高地的每個逆向版賽道飛行。", description = "下一組逆向賽道會回到蒼藍高地。\n\n要是準備好了，你應該回到那裡，將先前比賽的路徑再重新飛過一遍。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72985] = {title = "薩爪祖斯巡迴賽道逆向版", objective = "在薩爪祖斯的每個逆向版賽道飛行。", description = "你會再一次回到一切的終點。或是一切的起點。我記不清楚了。\n\n去找我的青銅龍同事，在逆向版賽道飛行，完成你的倒飛訓練。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][72987] = {title = "再來一次", objective = "到扎拉萊克洞窟跟厄比西昂碰面。", description = "我了解雅立史卓莎的顧慮。暗焰是一股邪惡的力量，就算是保持一段距離，也會遭受不可名狀的威脅，我們也親眼見證過這點。只可惜，我們沒有袖手旁觀、什麼都不做的餘裕。\n\n比起以往，我們現在更需要新的盟友和救兵。\n\n在我離開扎拉萊克洞窟之前，曾接觸過奈薩里奧派駐在黑曜之眠的士兵。幸運的是，他們仍對黑龍軍團忠心耿耿。\n\n我們在那裡碰面吧。", progress = nil, completion = "很高興你順利趕上了，&lt;name&gt;。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72988] = {title = "藏寶海灣日報", objective = "跟賽諾苟斯說話，讓你在藏寶海灣的聲望暫時變成中立，然後到東部王國的藏寶海灣去找澤羅斯。", description = "我今天在藏寶海灣日報上看到一個你絕對會大吃一驚的人物！幹嘛這樣看我，$p？我有時也喜歡關心一下世界各地的八卦新聞。藏寶海灣是個很有意思的地方。\n\n總之，我讀到了澤羅斯的事情！他曾是某個邪惡法師的俘虜，那個法師痛恨藍龍。在獲救之後，他似乎找到了自己在這世上的生存之道。\n\n年輕人，我給你個建議。千萬別欠債，尤其是在藏寶海灣。如果你的債主是大財主本人，那就真的完蛋了。\n\n在鯊魚把他吃下肚前，我們快去找他吧。", progress = nil, completion = "手拿開，別碰我！噢，等一下…你看起來不是當地人。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72989] = {title = "晶紅雛龍", objective = "前往晶紅生命聖殿領取紅龍蛋，然後在晶紅誓言石將其孵化。", description = "有顆紅龍軍團的龍蛋已經可以孵化了。\n\n到晶紅生命聖殿去找亞美拉，向她領取那顆龍蛋。然後，我要你把龍蛋帶到晶紅誓言石，在充滿紅龍軍團之力的地方將它孵化。\n\n成功孵化後，帶著雛龍回到這裡，交給我們進行後續照護。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72990] = {title = "赤紅舒適度", objective = "收集晶紅雛龍巢穴所需的東西。", description = "我很期待見到我們的晶紅幼龍。畢竟，照顧他們是我的專長！\n\n我已經跟亞美拉談過，打算自己做巢。這些是我需要的材料。收集到後就交給我，我就能做出舒適度前所未見的軟墊！\n\n<拉茲塔克將材料清單交給你。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72991] = {title = "暖心的火龍果派", objective = "在晶紅生命之池附近採集成熟的火龍果，並向沃卓肯的艾如苟莎取得預先做好的派皮，然後全部交給拉茲塔克，以便為晶紅雛龍烤派。", description = "一提到安撫紅龍的零嘴，我馬上就想到以前在晶紅生命之池吃到的派。當我們的鐵匠克雷迪斯在工作空檔烤派時，你立刻就會知道，因為烤火龍果的香氣會傳遍整座山！\n\n我烤的派可能沒有他的那麼美味，不過，我確定晶紅雛龍一定會愛上它。如果你把材料帶來給我，我就會盡全力烤出最棒的派！", progress = "<拉茲塔克拗了拗手指。>\n\n我已經有段時間沒有烤東西了，但我有信心！", completion = "談到照顧紅龍，我一向知道自己在做什麼！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72992] = {title = "不是那樣玩的！", objective = "與晶紅雛龍一起玩耍。", description = "我們的晶紅雛龍似乎不太擅長交朋友。每次她想找同伴玩耍的時候，總是很快就告吹。\n\n她或許有點太熱情，不過幼龍都是這樣子。你何不去教她玩鬼抓人的正確心態是什麼？", progress = nil, completion = "&lt;艾迦潘索斯嘆了口氣。&gt;\n\n我已經可以看出那隻幼龍一定會很不受控。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72993] = {title = "凡事我做主！", objective = "協助貝菈史卓莎。", description = "我從沒見過這麼蠻橫的幼龍！\n\n她居然還有張清單！拜託，把貝菈史卓莎暫時帶離我們身邊。我…需要坐一下。", progress = "<艾迦潘索斯的眼袋變得比平常更明顯。>", completion = "她不只需要培養耐心，她也必須知道世界不是繞著她轉！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72994] = {title = "自傲的寵物", objective = "為貝菈史卓莎取得幼年沃昆戰寵。", description = "我認為，想讓貝菈史卓莎學會別那麼自戀，唯一的方式就是讓她親自了解其他同伴對此的感受。\n\n沃昆是很美麗的生物，不過他們也是極度敏感的夥伴，需要大量的關愛。\n\n沃卓肯的莉辛卓為貝菈準備了一隻幼年沃昆。在與沃昆相處的過程中，或許能讓她反省自己的行為。", progress = nil, completion = "這隻寵物應該能讓貝菈學會別那麼難搞…或是讓可憐的拉茲塔克工作量加倍。反正，他們其中一個一定會有所收獲。", rewards = "您會學到：\n\n沃昆史卓莎公主\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72995] = {title = "耐心點", objective = "協助貝菈史卓莎在寵物對戰中擊敗烏龜。", description = "貝菈史卓莎已經從她的幼年沃昆身上學到很多東西，但我又想到一件她需要學習的事。\n\n她缺乏耐心的現象已經困擾我好一段時間了。最近，我在水邊想這件事，看著烏龜悠悠哉哉地渡日。然後我突然靈光一閃！\n\n伍拉莉是個完美的對手，很適合用來考驗貝菈史卓莎的耐心，不過可憐的沃昆史卓莎公主的耐力不太夠。你可以到甦醒海岸找他們，助他們一臂之力嗎？", progress = nil, completion = "自從來到托育所，她真的成長了許多。雖然她還有很多東西要學，但我真的很以她為傲。\n\n她表達了想跟你一起冒險的意願。希望你不會被她指使得團團轉。", rewards = "您會收到：\n\n貝菈史卓莎龍石"}
MultiLanguageQuestData['tw'][72996] = {title = "青銅雛龍", objective = "前往晶紅生命聖殿領取青銅龍蛋，然後在青銅誓言石將其孵化。", description = "有顆青銅龍軍團的龍蛋已經可以孵化了。\n\n到晶紅生命聖殿去找修司，向他領取那顆龍蛋。然後，我要你把龍蛋帶到青銅誓言石，在充滿青銅龍軍團之力的地方將它孵化。\n\n成功孵化後，帶著雛龍回到這裡，交給我們進行後續照護。", progress = nil, completion = "啊，是隻青銅幼龍。\n\n真希望他一直都是這麼小，對吧？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72997] = {title = "沙中小睡樂無窮", objective = "收集青銅雛龍巢穴所需的東西。", description = "紅龍一向喜歡生活在充滿綠意和生機的環境中，但青銅龍卻偏愛乾燥、多沙的環境。相信你能在薩爪祖斯的時光合流，找到許多適合用來做巢的材料。\n\n我在書上看到，青銅幼龍也很喜歡蜷縮在大小適中的碗盆裡。我在青銅區旅店工作的朋友老是抱怨他們的碗盆太多了…我們可以跟她拿一個來，相信她一定不會介意。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72998] = {title = "專業熟成", objective = "向沃卓肯的戈貢佐姆購買適合青銅雛龍的時光帕馬森乳酪。", description = "自從來到沃卓肯，我就一直在研究青銅龍。雖然他們很認真地履行時間守護者的職責，但閒暇之餘，也開發了許多需要借助魔法的嗜好。\n\n我的朋友戈貢佐姆發誓說，他針對「龍生」每個階段開發了對應的乳酪，並提到他有一種非常適合青銅幼龍的帕馬森乳酪。看來我們雛龍的第一餐已經有著落了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][72999] = {title = "這裡？那裡？無所不在！", objective = "與青銅雛龍一起玩耍。", description = "我們的青銅雛龍一直與其他雛龍保持距離，老是喜歡埋在沙堆裡。有時候，我們會發現他跟其他雛龍一起在沙地，但從沒看過他四處走走！\n\n他需要交些朋友。你何不跟他玩一場鬼抓人呢？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73000] = {title = "穿越時空的噴嚏", objective = "在沃卓肯各地尋找祖薩多姆。", description = "我們常常被祖薩嚇一跳，<name>。\n\n因為他還很小，對時間的控制力還沒完全發展。糟糕的是，他有奇怪的反射反應。每次打噴嚏，他就會消失，然後以任何形態憑空出現在任何地方！追根究柢，他似乎有很多過敏症。\n\n拜託，幫助祖薩多姆找出他到底對什麼東西過敏，別讓他再到處瞬移！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73001] = {title = "有鱗寵物", objective = "為祖薩多姆取得角蛙寶寶戰寵。", description = "我們一直想幫祖薩多姆找到最適合他的寵物。他的過敏症讓我們的選擇變得很有限，不過我已經想到合適的寵物了。\n\n我知道鱗片不會讓祖薩過敏。角蛙寶寶不太會引起過敏，而且莉辛卓一定能幫我們弄來一隻。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n阿努納\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73002] = {title = "短暫免疫", objective = "協助祖薩多姆在寵物對戰中面對過敏症。", description = "祖薩多姆一直很努力控制自己的力量。\n\n雖然我們可能治不好他的過敏症，但他不必每次打噴嚏就穿越時空。\n\n伍拉莉認為她可以測試他的控制力。請去甦醒海岸一趟，協助他們完成這場測試。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n祖薩多姆龍石"}
MultiLanguageQuestData['tw'][73003] = {title = "蒼藍雛龍", objective = "前往晶紅生命聖殿領取藍龍蛋，然後在蒼藍誓言石將其孵化。", description = "有顆藍龍軍團的龍蛋已經可以孵化了。\n\n到晶紅生命聖殿去找艾克佐，向他領取那顆龍蛋。然後，我要你把龍蛋帶到蒼藍誓言石，在充滿藍龍軍團之力的地方將它孵化。\n\n成功孵化後，帶著雛龍回到這裡，交給我們進行後續照護。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73004] = {title = "學者的樂趣", objective = "收集蒼藍雛龍巢穴所需的東西。\n\n覺醒之霜可從巨龍群島各地的許多元素生物身上收集，由10個喚醒之霜組合而成，或從拍賣場購買。", description = "從年幼時期開始，藍龍就是知識的追求者。他們深受書籍和卷軸的吸引，覺得與書為伴是最快活的事。\n\n對於我們的蒼藍雛龍，最棒的巢穴就是被書堆包圍。我想請你為他的巢穴收集這些東西：讓他學習寫字的羽毛筆、可以讓他保持舒適涼爽的東西，以及來自蒼藍高地的床邊故事。聽說很多藍龍的記憶中都有個熟悉的故事。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73005] = {title = "水晶營養學", objective = "為蒼藍雛龍從蕨皮谷收集6個一口大小的脈能水晶。", description = "沒錯，藍龍會吃正常的食物，不過，飲食中最重要的部分是自然中的魔力。無論藍龍身在何處，你總能在附近發現很有營養的脈能水晶礦藏。\n\n當然，在藍龍離開期間，他們的家園已經變成其他生物的家了。蕨皮豺狼人佔據了脈能水晶最多的土地，將它據為己有。你必須進入他們的營地，為我們的幼龍取回水晶。", progress = "從孵化的那一刻起，龍就有無比銳利的牙齒。", completion = "豺狼人不是第一個竊取我們的脈能水晶的傢伙，也不會是最後一個。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73006] = {title = "好吧，其實…", objective = "與蒼藍雛龍一起玩耍。", description = "如我所料，我們親愛的蒼藍雛龍果然是個「小書龍」。艾蘇納也有很多像他這樣的雛龍，不過那裡只收藏了一些卷軸。\n\n儘管沃卓肯這裡的藏書極為豐富，但幼龍還是需要起來動一動！你何不跟它玩場鬼抓人？", progress = nil, completion = "年紀這麼小的幼龍，卻如此博學多聞！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73007] = {title = "新眼鏡", objective = "帶札勒苟斯去沃卓肯的勝利面相，尋找適合的眼鏡。", description = "札勒苟斯是個聰明的孩子，不過，隨著他漸漸長大，我們對他也越來越了解。\n\n他的視力非常差！\n\n他經常提到視線很模糊，無法清楚看到東西的樣子。\n\n沃卓肯大橋的另一側有間沙龍。請陪札勒苟斯去配一副適合的眼鏡，矯正他的視力。", progress = nil, completion = "札勒似乎對他的新眼鏡感到超級滿意！他現在一定在到處炫耀了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73008] = {title = "學者的寵物", objective = "為札勒苟斯取得附魔的書籍寵物。", description = "很久以前，在艾蘇納，蒼翼之憩的蒼藍幼龍經常會與納薩拉斯學院的精靈一起研究魔法。我對那個地方有很多美好的回憶，其中有一個更是令我印象深刻。\n\n那就是附魔的書籍，雖然是很值得研究的對象，但也非常淘氣。聽說莉辛卓有本類似的書籍，我覺得那會是最適合札勒苟斯的寵物！", progress = nil, completion = "希望札勒苟斯會喜歡他的新夥伴。", rewards = "您會學到：\n\n帕利布禮奧思\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73009] = {title = "視覺並非一切", objective = "協助札勒苟斯克服他對視力的不安全感。", description = "自從拿到眼鏡後，札勒苟斯就一直極度仰賴他的視力。當然，這很正常，不過在視覺失效時，他也必須要臨機應變。\n\n我認為該是把燈關掉的時候了。伍拉莉剛好有個超棒的方案。\n\n她認為自己可以教札勒苟斯如何在失去視力時取勝。請去甦醒海岸找他們。", progress = nil, completion = "札勒苟斯對自己的眼鏡很自豪，知道自己就算沒了眼鏡也沒問題後，他變得更有自信了。\n他打算參與你接下來的冒險。", rewards = "您會收到：\n\n札勒苟斯龍石"}
MultiLanguageQuestData['tw'][73010] = {title = "翡翠雛龍", objective = "前往晶紅生命聖殿領取綠龍蛋，然後在翡翠誓言石將其孵化。", description = "有顆綠龍軍團的龍蛋已經可以孵化了。\n\n到晶紅生命聖殿去找札克拉娜，向他領取那顆龍蛋。然後，我要你把龍蛋帶到翡翠誓言石，在充滿綠龍軍團之力的地方將它孵化。\n\n成功孵化後，帶著雛龍回到這裡，交給我們進行後續照護。", progress = nil, completion = "我有時候會帶我照顧的幼龍去見見維爾薩拉的一些翡翠幼龍。\n\n他們通常…沉穩很多…\n\n&lt;艾迦潘索斯遙望遠方。&gt;", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73011] = {title = "家，甜蜜的土堆", objective = "收集翡翠雛龍巢穴所需的東西。", description = "綠龍偏好兼具自然和神秘氣息的家，而且要充滿翡翠夢境之力。\n\n翡翠花園一定會有很多合適的材料，能夠用來打造適合這個小傢伙的巢穴。也許我們應該找綠龍談談，找到能讓他們也感到舒適的東西。", progress = "我們必須為這隻幼獸打造最舒適的環境，讓幼獸好好休息和成長。", completion = "願這隻幼龍能夠順利發芽茁壯。\n\n當然，這只是一種比喻。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73012] = {title = "荷芡花大豐收", objective = "為翡翠雛龍取得荷芡花。\n\n荷芡花可從草本生物身上取得，透過草藥學技能採集，或從拍賣場購買。", description = "所有綠龍都喜歡有葉子又脆脆的點心。生長在翡翠夢境的植物富含各種營養素，能讓綠龍保持健康並感到滿足。\n\n荷芡花是適合年幼綠龍的香甜零嘴，內含成長中的雛龍所需的所有維生素。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73013] = {title = "好…累…", objective = "與翡翠雛龍一起玩耍。", description = "我有點擔心新來的翡翠幼龍。比起大多數的翡翠幼龍，他的睡眠時間沒那麼長。\n\n他似乎有失眠的問題。你何不邀請他一起玩鬼抓人，活動一下身體？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73014] = {title = "失眠的綠龍？", objective = "試著協助波西德里思入睡。", description = "<name>…我們遇到一個問題。\n\n波西德里思有失眠的症狀。\n\n我甚至不知道，居然有綠龍會無法順利入睡！要是他無法進入夢境，又該如何學會怎麼保護夢境？\n\n拜託，盡你所能幫助波西德里思入睡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73015] = {title = "昏昏欲睡的寵物", objective = "為波西德里思取得幼熊寵物。", description = "波西德里思的睡眠問題仍會為他帶來許多麻煩。失眠導致他無法加深自己與夢境的連結。\n\n熊會冬眠，熊會做夢，幼熊軟軟的、暖暖的又毛茸茸的。巨龍群島的某些幼熊甚至會與夢境產生連結。你可以幫波西德里思從莉辛卓那裡帶回一隻幼熊嗎？您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n桑尼斯\n\n您還會收到：\n\n龍石"}
