MultiLanguageQuestData['tw'][73085] = {title = "臨陣退縮", objective = "檢視半龍人犯人的隨身物品，找尋關於碎裂火焰軍的線索。", description = "馬里索斯跟阿米索菈想要假裝自己是冒險家，那也是他們的選擇。我可是有忠誠感的人。\n\n<雖然他的發言大膽，信使看起來卻不太堅定。>\n\n你不知道沙卡瑞斯會做出什麼事，懂嗎？\n\n想翻我的東西然後亂下結論的話，就隨便你吧。但我什麼都不會跟你說的，我沒辦法說。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73086] = {title = "良性競爭", objective = "在比劃中擊敗阿米索拉。", description = "在我的育所夥伴中，有更多人加入安珀莎的勢力了。不過在前碎裂火焰軍跟我們傷害的半龍人之間，氣氛還是挺緊張的。\n\n幸好，我想出了一個很實際的解決辦法，很有半龍人的風格，又可以強化我們身為喚能師的感情：比劃！\n\n來吧，和我比劃！我們給這些粗野的傢伙做個示範吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73089] = {title = "門後的驚喜", objective = "進入密庫，使用澤斯克拉密庫鑰匙再開啟3道大門。", description = "如果要繼續探索這些密庫，就必須開啟更多大門！這也意味著我們需要更多鑰匙。\n\n看看你能不能在禁忌之境找到更多鑰匙。每道門都代表一次機會！", progress = nil, completion = "你的表現相當出色，我的朋友。只要我們有鑰匙，就能繼續進行探險。\n\n我相信再過幾天，我們就能找到另一個可以探索的密庫。我早晚會被自己好奇心殺死！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73090] = {title = "水晶之悔", objective = "前往水晶之歌森林跟菈妮苟莎交談。", description = "我大概知道菈妮苟莎在水晶之歌森林做什麼，但卻想不透為什麼她決定要親自做這件事。\n\n珊達拉遺跡就在這片森林之中，這裡以前是精靈貴族的領地，也是凡人首次與藍龍軍團發生衝突的地方。如果菈妮苟莎真的在水晶之歌森林，那她來此的原因很可能跟珊達拉有關。\n\n去那裡找她吧，<name>，想辦法說服她回來與我們團聚。", progress = nil, completion = "原諒我，&lt;class&gt;。我還以為你是個受盡折磨的秘法亡魂。\n\n…別那樣看我！你應該能理解，在這裡犯下這種錯是情有可原的。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73091] = {title = "水晶之歌森林", objective = "與卡雷苟斯交談。", description = "面對燃燒軍團最近一次掀起的戰火，藍龍菈妮苟莎向凡人伸出了援手。不過，當群島向她求援時，她卻沒有回應。\n\n她出了什麼事嗎？還是她只是不想回來？不管理由是什麼，從艾索雷苟斯的球體看來，我們最後一次看到她是在水晶之歌森林。", progress = nil, completion = "菈妮苟莎一直以來都對我很和善。希望她沒事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73092] = {title = "如家人一般", objective = "在龍隊之眠的派對上，將一盤盤食物拿給半龍人。", description = "吃一點吧！斯卡勒許的特調！如果你是個需要飽餐一頓的半龍人，就來對地方了！\n\n<斯卡勒許壓低聲音對你說話。>\n\n跟你說個祕密吧，<name>？我們的族人最近並不好過。我們需要點什麼來幫助我們放鬆，讓我們記得自己不是孤單一人。我認為家常菜會是好主意。\n\n羅曼跟我會負責烹飪。你可以負責分發食物，把盤子拿給需要熱騰騰食物的半龍人嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73093] = {title = "空位", objective = "找到拉桑聶。", description = "我不想要破壞歡樂的氛圍，可是，有個應該出席的人沒有來。\n\n這是一個讓所有半龍人團聚的日子，不過拉桑聶可能不這麼想。跟我們一樣，他以前是碎裂火焰軍。雖然他在亞貝魯斯的事件後就退出了，我很怕他依然為罪惡感所苦。他似乎很煩惱。\n\n你可以去找他嗎？去確保他心情上還好，而且知道這裡歡迎他？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n復燃之絆紀念物龍石"}
MultiLanguageQuestData['tw'][73094] = {title = "協助遠征隊", objective = "跟龍隊指揮官安珀莎和厄比西昂在禁忌之境的風裂火山口碰面。", description = "沙卡瑞斯會為了他的罪行付出代價。\n\n<安珀莎狠下心。>\n\n我們不能再讓沙卡瑞斯的邪惡野心造成更多半龍人的傷亡了。\n\n如果碎裂火焰軍對龍鱗遠征隊構成威脅，我們就必須馳援盟友。", progress = nil, completion = "太多人為此受苦，太多人因此而死。\n\n這一切該劃下句點了。沙卡瑞斯是罪魁禍首，他必須付出代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73107] = {title = "傳訊石：初步報告", objective = "找到傳訊石。", description = "<這個傳訊石仍保存著艾達曼希亞以古龍語傳給奈薩里奧的古老訊息。>\n\n<龍隊指揮官一定會對裡面的內容感興趣。>", progress = "有什麼發現？", completion = "他們…他們一直都知道。他們一直都知道我們沒有問題，卻把我們困在靜滯狀態。\n\n我會把這段記錄翻譯給所有族人閱讀。願它使我們洞察萬物。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73108] = {title = "傳訊石：囚犯", objective = "找到傳訊石。", description = "<這個傳訊石仍保存著艾達曼希亞以古龍語傳給奈薩里奧的古老訊息。>\n\n<龍隊指揮官一定會對裡面的內容感興趣。>", progress = "有什麼發現？", completion = "嗯，所以說菈薩葛絲有個看守者。還是說，艾達曼希亞就是我們的看守者？\n\n這真讓人困惑。我會把這段記錄翻譯後加入典籍，讓其他族人可以閱讀。十分感激，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73109] = {title = "收訊石：最後警告", objective = "將收訊石交給龍隊指揮官埃祖拉瑟。", description = "<這個收訊石仍保存著奈薩里奧以古龍語發送的古老訊息。>\n\n<半龍人的龍隊指揮官一定會對裡面的內容感興趣。>", progress = "有什麼發現？", completion = "什麼？奈薩里奧到底想阻止艾達曼希亞做什麼？\n\n我會把這段內容翻譯並加入日誌。這些訊息的魔法中都有時間印記，對我來說很方便。\n\n不過當時為何沒在使用後立即銷毀呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73110] = {title = "日誌條目：實驗", objective = "收集日誌條目。", description = "<這個遠古書頁被周圍的魔法束縛住，上面的文字是古龍語。>\n\n<龍隊指揮官一定會對裡面的內容很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73113] = {title = "日誌條目：聖物", objective = "收集日誌條目。", description = "<這個遠古書頁被周圍的魔法束縛住，上面的文字是古龍語。>\n\n<龍隊指揮官一定會對裡面的內容很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73114] = {title = "日誌條目：育所", objective = "收集日誌條目。", description = "<這個遠古書頁被周圍的魔法束縛住，上面的文字是古龍語。>\n\n<龍隊指揮官一定會對裡面的內容很感興趣。>", progress = "<name>，有什麼令人感興趣的消息嗎？", completion = "即使已經知道來龍去脈，這段文字讀起來還是令人相當不安。\n\n我會著手翻譯，讓其他人也能理解。謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73115] = {title = "日誌條目：沉默", objective = "找到日誌條目。", description = "<這個遠古書頁被周圍的魔法束縛住，上面的文字是古龍語。>\n\n<龍隊指揮官一定會對裡面的內容很感興趣。>", progress = "這也許能讓我們有新的看法。", completion = "就因為一條指令，這場沉默持續了數千年之久。\n\n想到我也有可能一直毫不質疑地遵守到我死去的那天，一想到就覺得恐怖。\n\n謝謝你把這段日誌條目帶來給我，&lt;name&gt;，我會納入譯文之中。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73119] = {title = "大量的幼龍點心", objective = "向沃卓肯的商人拿取訂購的點心。", description = "艾迦潘索斯說我們訂得點心可以領取了，但我們現在都有事要忙。\n\n在我們照顧幼龍的時候，你可以跑一趟，幫我們領取點心嗎？", progress = "幸好我們不用自己吃光這些點心。知道幼龍想要什麼，我們就提供什麼。乳酪和餅乾顯然是他們的最愛。", completion = "謝謝你帶來更多點心。這些應該能撐一陣子。", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石\n\n等級 20–80磨亮的寵物吊飾\n\n等級 70–70小動物戰鬥訓練石飛行生物戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73120] = {title = "開胃的餘波", objective = "讓幼鱗托育所再次變得井然有序。", description = "今天的活動被一場即興的食物大戰打斷了。許多不速之客被引來托育所！\n\n請幫忙清理一下。", progress = nil, completion = "我只希望這幅整潔的模樣能多維持個幾分鐘就好！\n\n不管怎樣，謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石\n\n等級 69–80磨亮的寵物吊飾\n\n等級 70–70野獸戰鬥訓練石人形生物戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73124] = {title = "囤積行為", objective = "收集普林利爵士棲所的材料。", description = "幼龍很喜歡跟普林利爵士相處，不過他們到處亂跑，損壞了普林利爵士的棲所。\n\n你能幫牠取得另一叢灌木嗎？在你還沒回來之前，牠可以先用可愛的新玩具撐一下。還有薰香。\n\n當然，我們還是要修復牠的棲所。", progress = "除了要有綠蔭外，普林利爵士只在乎自己的空間是不是有天然材料作為裝飾。", completion = "這個棲所看起來非常棒，&lt;name&gt;。\n\n這應該能讓普林利爵士住一陣子，直到它再次被幼龍蹂躪為止。", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石魔化戰鬥訓練石\n\n等級 20–80磨亮的寵物吊飾\n\n等級 70–70無瑕的戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73126] = {title = "美勞與沐浴", objective = "協助清除幼鱗托育所各處的顏料。", description = "我們今天的美勞活動完全失控了。有隻幼龍對自己的畫筆附魔，然後其他幼龍也跟著做。現在所有東西都被上色了。\n\n在我們清除幼龍身上的顏料時，請把托育所清乾淨。", progress = nil, completion = "你來得正好，&lt;name&gt;。謝謝你。這個工作需要三人合力。\n\n普林利爵士放任幼龍搗亂，該受到譴責…", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石\n\n等級 68–80磨亮的寵物吊飾\n\n等級 70–70龍類戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73128] = {title = "故事時間", objective = "為幼鱗托育所的幼龍打倒各個故事中的壞蛋。", description = "$p，幼龍懇求我們從他們最喜歡的故事集中，選一則唸給他們聽，不過我們已經精疲力盡了。\n\n幼龍深受吸引的那本書被施了魔法，每次唸故事都很累人。\n\n你願意替我們代個班，唸故事給他們聽嗎？", progress = nil, completion = "當幼龍知道我們能用栩栩如生的影像說故事後，他們就要求每個故事都要這樣做。\n\n謝謝你讓我們能稍微休息一下！", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石魔化戰鬥訓練石\n\n等級 20–80磨亮的寵物吊飾\n\n等級 70–70小動物戰鬥訓練石魔法戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73130] = {title = "鳥禽符文塗鴉", objective = "讓幼鱗托育所再次變得井然有序。", description = "昨天魔法符文課的影響顯然延續到了今天。幼龍樂此不疲地在每個可能的地方練習使用符文，完全毫無節制。\n\n幼龍顯然玩得非常開心！拜託，請幫我們將玩具歸回原位，並驅散你碰到的所有符文。", progress = nil, completion = "謝謝你的協助，&lt;name&gt;。那片沙地現在有了自己的意志！\n\n我們會盡我們所能，不讓幼龍再用符文去激怒它。", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石無瑕的戰鬥訓練石磨亮的寵物吊飾\n\n等級 65–80元素生物戰鬥訓練石\n\n等級 70–70水棲生物戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73131] = {title = "有格調的偽裝", objective = "在沃卓肯尋找貝菈史卓莎和她的朋友。", description = "$p！我幫自己和朋友製作了很高明的偽裝，不過只有一個方式能知道偽裝是不是真的完美。\n\n我們來玩捉迷藏吧！在沃卓肯尋找我們，好讓我知道偽裝有沒有用！", progress = nil, completion = "太好玩了！現在我對偽裝有了新的靈感。我要馬上去試驗一下！\n\n你可以走了！", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石\n\n等級 69–80磨亮的寵物吊飾\n\n等級 70–70元素生物戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73132] = {title = "翻箱倒櫃", objective = "在沃卓肯尋找札勒和他的朋友。", description = "嗨，$p！你想玩遊戲嗎？\n\n我一直在研究全艾澤拉斯最好玩的捉迷藏遊戲！\n\n我覺得這本書建議的策略有改進的空間。我們來玩個一局，驗證一下我的假說吧！您會收到：\n\n\n\n等級 70–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石磨亮的寵物吊飾\n\n等級 70–70飛行生物戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73133] = {title = "舒適偽裝", objective = "在沃卓肯尋找波西德里思和他的朋友。", description = "<波西德里思打了個哈欠。>\n\n我就是睡不著。乾脆來玩遊戲吧！\n\n說不定我會在城市裡找到一個很舒服的藏身處。我賭你絕對找不到我！您會收到：\n\n\n\n等級 70–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石磨亮的寵物吊飾\n\n等級 70–70人形生物戰鬥訓練石不死生物戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73134] = {title = "無盡脫逃", objective = "在沃卓肯尋找每個祖薩。", description = "哈…啾！\n\n抱歉。你想玩捉迷藏嗎？我發現新的藏身處，想來試試看！\n\n希望我的過敏不會造成干擾！", progress = nil, completion = "哇，另一個祖薩的藏身處真的很高明！我還有很多要學。\n\n謝謝你陪我一起玩！", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石磨亮的寵物吊飾\n\n等級 70–70魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][73135] = {title = "黑曜之惑", objective = "在沃卓肯尋找魯金和她的朋友。", description = "嗨，$p。\n\n<魯金不安地四處張望。>\n\n你想跟我玩捉迷藏嗎？我覺得這會是非常好的訓練。\n\n我必須隨時注意危險，所以知道哪裡能躲是件好事。你願意幫我練習嗎？", progress = nil, completion = "全被你找到了！我覺得自己更擅長躲藏了。真想馬上再玩一場！\n\n&lt;魯金轉了個圈。&gt;\n\n這真是超級好玩！", rewards = "您會收到：\n\n\n\n等級 70–80野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石魔化戰鬥訓練石\n\n等級 69–80戰寵繃帶\n\n等級 20–80磨亮的寵物吊飾龍石"}
MultiLanguageQuestData['tw'][73137] = {title = "追尋火焰", objective = "在龍顱島跟龍隊指揮官安珀莎碰面。", description = "他說會在黑暗中等著你？\n\n<安珀莎瞇起眼睛。>\n\n我知道沙卡瑞斯在哪裡。\n\n他必須為此負責，而我需要你的協助。想要的話，你可以留在這片廢墟逐一搜索，但是我認為現在我們有更緊迫的任務。如果你願意幫忙幫到底，那就跟我來吧。\n\n我要去龍顱島。", progress = nil, completion = "我就知道你會來。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73139] = {title = "深海補給", objective = "殺死遠鱗納迦，並收集他們的補給品。", description = "我們對來自海洋的威脅相當熟悉。但是有些敵人是決不允許在我們的海岸出沒的。\n\n納迦正在東部地帶朝我們的海灘和洞穴進攻。他們自己帶了補給品。如果我們能降低當地納迦的人口數並扣押他們的補給，就能提高我們的存活機會。\n\n計畫是這樣的：從他們堆放補給的地方或是他們的屍體上把補給搶來，然後殺死他們的領袖。這件事攸關性命。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73140] = {title = "擊碎火山口", objective = "殺死風裂火山口的洪荒使者。", description = "洪荒使者轉移陣地到風裂火山口了。他們在那裡召喚元素生物、濫用大地的恩賜。\n\n我們一定要把他們解決掉，而且下手要快、要果斷。削弱他們的勢力。摧毀他們的圖騰。幫助我們把禁忌之境變成半龍人、巨牙海民和被掠奪的居民可以安身立命的家園吧。", progress = nil, completion = "做得好。你實實在在地破壞了他們打算在禁忌之境進行的陰謀。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73141] = {title = "永燃餘燼", objective = "前往圍城育所，從強大的火之洪荒使者身上收集永燃餘燼。", description = "如何找到熱源、保持溫暖是我們在新家園最常擔心的事情。我們不想把所有帶來的東西都當成燃料燒光，也不想到危機四伏的海岸邊去收集漂流木。那太危險了！\n\n不過洪荒使者帶了他們自己的火焰。\n\n如果你能殺死強大的火之洪荒使者、從他們身上取得永燃餘燼，並把餘燼帶回來，對我們來說會很有幫助的。", progress = "永燃餘燼能讓營地全年保持溫暖。", completion = "這太完美了！再寒冷的夜晚，只要有了它們，我們也能保持溫暖。即使天氣惡劣，它們也能讓烹飪用火持續燃燒、不熄滅。\n\n謝謝你！這裡永遠歡迎你回來。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73142] = {title = "綻放的藍", objective = "從龍隊舊訓練場的藍龍守衛部隊身上收集秘法法器。", description = "瑪里苟斯留下了一部分的部隊，趁我們睡著時監視我們。他已經離開了，但是他的手下仍在這裡，讓大家陷入困境。\n\n斥候發現他們在使用秘法法器。我想，那些法器在我們手上更有用。去收集一些法器吧。他們的守衛可能會試圖抵抗，但是對你來說應該不成問題，對吧？\n\n<辛德瑞翠絲哼了一聲。>\n\n也許他們會識相地離開。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n元素溢流"}
