MultiLanguageQuestData['tw'][73149] = {title = "洪水警報", objective = "在寵物對戰中擊敗奔流。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73155] = {title = "被遺忘的戒指", objective = "將戒指交給莫克特村的研究員伊瑪瑞斯。", description = "<戒指上有個不尋常的印記，莫克特村的某個半龍人或許會感興趣。>", progress = nil, completion = "噢！自從我們甦醒以來，我從未見過像這樣的文物！這是很特別的戒指，顯然是奈薩里奧的鐵匠製作的。\n\n你該留下它。隨身保管。它可能會對你有用。", rewards = "您能選擇下列奬勵中的一個：\n\n瑪瑙環飾\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][73156] = {title = "回去找維利迪亞", objective = "前往禁忌之境的莫克特村跟維利迪亞碰面。", description = "我會把你託付給維利迪亞。她跟治療之翼合作，打算在莫克特村建造一個半龍人、巨牙海民和其他禁忌之境盟友可以安心居住的地方。\n\n我們在這裡有了家園，而我…有些事情我需要思考一下。感謝你陪我一起度過這次考驗。\n\n事情還沒結束。不過至少我知道，下次我們面對沙卡瑞斯的時候，我們有你在。謝謝你。", progress = nil, completion = "歡迎回來，&lt;name&gt;。從你的表情看得出來這一切並不容易。\n\n我不想再面對沙卡瑞斯，但下次我們一定會做足準備。現在我們有更急迫的事要處理。直到禁忌之境成為所有人的安全家園之前，我們不會停歇。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73157] = {title = "慈悲之翼", objective = "前往禁忌之境的三個地點幫助半龍人斥候。", description = "風暴平息後，我們派出數支斥候小隊去探索島嶼。\n\n有幾支隊伍遲遲沒有回來。我們擔心他們可能遭遇到未知的危險。\n\n可以請你在島上尋找他們嗎？找到他們後，使用治癒者的信號，召喚醫療者過來。", progress = nil, completion = "感謝你幫助我們的斥候。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73159] = {title = "探索我們的過去", objective = "跟塔恰和傑布在澤斯克拉密庫的入口碰面。", description = "有了你的幫忙，現在我們能深入了解島嶼了秘密了。\n\n澤斯克拉密庫就在附近。奈薩里奧在這些大型的地下儲存空間中存放了各式各樣的寶藏以及被遺忘的研究。探索這些密庫可能會有很大的收穫。\n\n請跟塔恰和傑布同行，視情況提供他們協助吧。", progress = nil, completion = "這些巨大的門背後有無數房間等著我們去探索。&lt;name&gt;，你準備好了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73160] = {title = "援手和援爪", objective = "在銳鱗海岸幫助傑布、塔恰和沃福德。", description = "龍鱗遠征隊的成員來到這裡幫忙我們探索島上的廢墟。他們的努力也許能幫我們找到更多細節，了解我們的過去。\n\n我的斥候在銳鱗海岸發現三名受困於船難的成員，請幫助他們安全抵達村落。", progress = "前往莫克特村的路上安全嗎？", completion = "幸好有你幫忙，我和傑布都沒事。我們的補給品也安然無恙！\n\n有個巨牙海民漁夫願意載我們一程，送我們到莫克特村。希望我們很快就能在那裡相見。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73169] = {title = "新年慶典", objective = "與暴風城的新年預告者談話。", description = "一年又過去了，<name>！塞納里奧議會邀請艾澤拉斯的所有居民一起來慶祝新年。你可以在月光灑落的祝福法陣處，找到暴風城的新年預告者。她可以告訴你更多有關節日的情報。", progress = nil, completion = "歡迎，&lt;name&gt;。你是來跟我們一起慶祝的嗎？", rewards = nil}
MultiLanguageQuestData['tw'][73170] = {title = "新年慶典", objective = "到奧格瑪的智慧谷，與新年預告者談話。", description = "一年又過去了，<name>！塞納里奧議會邀請艾澤拉斯的所有居民一起來慶祝新年。你可以在月光灑落的祝福法陣處，找到奧格瑪的新年預告者。她可以告訴你更多有關節日的情報。", progress = nil, completion = "歡迎，&lt;name&gt;。你是來參加慶典的嗎？", rewards = nil}
