MultiLanguageQuestData['tw'][73172] = {title = "席卡長者", objective = "你的靈魂之中燃燒著生命之火，年輕的<class>。我接受你的敬意，並以此物作為回禮…", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n先祖硬幣幸運紅包袋"}
