MultiLanguageQuestData['tw'][73178] = {title = "別碰我們的寶藏！", objective = "打敗鐵潮海盜，找回被偷的貨物。", description = "鐵潮海盜常常偷半龍人和巨牙海民的東西。他們什麼都偷，而且什麼都不放過。對他們來說，這些都是寶藏！\n\n請你找回我們被偷的東西。讓他們後悔來到這裡！", progress = "你有好好教訓那些海盜嗎？", completion = "他們應該學到教訓了！", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73179] = {title = "熱湯末日來囉！", objective = "打敗鐵潮海盜並趕跑入侵者。", description = "那些鐵潮海盜竟敢在我們的海域上航行、將島嶼據為己有。他們根本不知道自己惹上了什麼人。我們的莫克特朋友會帶你前往目的地。而我們半龍人…會提供軍火。\n\n<辛德瑞翠絲淺笑。>\n\n福瑟斯里安一直在嘗試用巨牙海民的料理方式做菜，但是結果時好時壞。去跟他要那些危險的試作品，這樣我們就能安全地丟掉那些東西，還可以順便趕走那群海盜！", progress = nil, completion = "哈。我最喜歡早上來碗熱騰騰的軍火湯了。聞起來像…勝利的味道。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73181] = {title = "清償債務", objective = "返回蒼藍文庫。", description = "希望這是我們最後一次見到大財主了。說實在的，我很佩服他在荊棘谷掌握的權力。\n\n我們運氣不錯，找到澤羅斯的時候他還活著。他在出亂子之前跟大財主的關係一定很不錯，不然不可能活命這麼久。\n\n我們回蒼藍文庫去吧。", progress = nil, completion = "這次任務真的讓我累壞了，&lt;name&gt;。我需要休息一下。", rewards = "您會收到：\n\n飛龍暗焰紋章碎片龍石飛龍夢境紋章飛龍覺醒紋章"}
MultiLanguageQuestData['tw'][73183] = {title = "要不要來玩個遊戲？", objective = "去沃卓肯跟蜜仙說話。", description = "<你打開一張字跡潦草的紙條。>\n\n哈囉，好朋友！我叫蜜仙，聽說你很會找東西呢。\n\n是說，我最近在玩一個叫做《魔獸兵團》的新遊戲，但是硬幣剛好不夠了。\n\n要不要出來見面？我可以跟你說要去哪裡找硬幣喔！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73188] = {title = "玷污旌旗", objective = "去塞拉摩找蘇莉苟莎。", description = "只要魔法存在，就會有人利用它做出道德敗壞之舉。\n\n我不確定蘇莉苟莎跟這群叛亂法師有什麼樣的過往，讓她決定展開追捕，但是在這件事情上，我傾向於相信她的判斷。我們去找她吧，<name>。也許我們能解決這個叛亂法師的問題，同時說服蘇莉苟莎回來加入我們。", progress = nil, completion = "你好，凡人。你和你那些跟班來得正是時候，我正要把這群濫用魔法的無賴化成灰燼。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][73189] = {title = "育所補給品", objective = "在支援育所收集6個治癒者補給品。", description = "很高興你來了。支援育所被甲蟲入侵了，我們不得不盡快撤離。也就是說，有很多補給品還在那裡。\n\n現在我們有很多受傷的探險者，所以很需要那些補給品。你能幫我們嗎？\n\n我們需要你盡可能多取回一些補給品。不過小心別中毒了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73190] = {title = "劇毒感染", objective = "殺死治癒者火山口內的甲蟲。", description = "治療之翼需要使用我們的支援育所，但是那裡的劇毒甲蟲災情仍然嚴重。\n\n我想，如果我們幫忙消滅那些害蟲，維利迪亞一定會很感謝的。", progress = nil, completion = "在我們的努力下，蟲害慢慢改善了。有改善就是好事。這些甲蟲總有一天會被通通消滅，我們只須耐心以對！", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73191] = {title = "馴蛇專家", objective = "遷移6隻劇毒水蛇，讓牠們回到治癒者火山口的池子。", description = "肆虐支援育所的劇毒也滲進了這些四處遷徙的水蛇身上。\n\n我們必須幫這些蛇回到牠們原本的池子裡去。否則，這種侵略性極強的物種會對環境造成嚴重破壞。\n\n我可以借你一隻友好的水元素，在轉移蛇到原本棲地的過程助你一臂之力。這不僅是為了我們的安全，也是為了牠們的安全著想。", progress = nil, completion = "這太棒了！在幫助治癒者火山口恢復生機上，我們取得了很多進展。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73192] = {title = "長羽毛的惡魔", objective = "將貴族花園飾品交給閃金鎮的吉倪亞‧布魯克斯。", description = "這個飾品似乎是貴族花園的某種裝飾物。最好把它送回閃金鎮的節慶場地。", progress = nil, completion = "啊，謝謝你把它送回來。我會把被偷的裝飾物放回原位！", rewards = "您會收到：\n\n\n\n等級 20–80塞滿戰利品的籃子\n\n等級 1–60裝滿戰利品的籃子經驗加成"}
MultiLanguageQuestData['tw'][73194] = {title = "近身獵殺", objective = "使用元龍屠殺長矛殺死一頭元龍。", description = "這些駭人的元龍是禁忌之境最兇猛的生物之一。\n\n打敗他們並非易事，幸好我們有很多武器可供使用。\n\n把這柄長矛和魚叉拿去吧。你會用得上它們的。如果被元龍的大嘴一口咬住，你必須用盡全力抵抗才有機會存活。\n\n這不是個容易的任務，但是我有信心你能完成。", progress = nil, completion = "這樣就對啦！被死亡之顎逮個正著的時候，更能體會生命的可貴。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][73196] = {title = "塔瑞克苟莎之眠", objective = "跟卡雷苟斯討論塔瑞克苟莎的事。", description = "<name>，請等一下。\n\n在你離開前…我還有一件事需要你幫忙。我有一個同胞，她值得獲得平靜，請幫幫她吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73197] = {title = "不滅之愛", objective = "從時光合流取回疾逝之沙。", description = "儀式上，除了需要先為塔瑞克苟莎的靈魂準備一個暫時容器外，還需要足夠的魔法精華來磨碎花朵。考慮到你手中的法杖內含青銅龍軍團的魔法，我們還是繼續使用他們的魔法吧。\n\n取一部分的時光合流之沙應該能完美達成這個目的。只要你拿來的沙是魔法強度比較高的那種就可以。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73198] = {title = "勿忘她", objective = "取得一朵法心花，然後把它帶到遠古枝幹去，讓它開花。", description = "由於法杖是由世界樹的枝椏製成的，用來進行靈魂轉移的容器也必須有與其相似的特性。有一種花朵十分頑強，在瓦瑟洛斯這麼惡劣的環境下仍能生長。\n\n但是在某些情況下，這種花卻相當脆弱。請找來這種花，然後把它帶到綠龍軍團的林地去吧。這樣做也許能讓它變得較為強壯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][73221] = {title = "清楚的腦袋", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][73226] = {title = "龍顱淺灘", objective = "收集用來補充釣魚洞的魚，並騎上你的飛龍從上面把魚丟下去。", description = "咬餌的情況應該要更熱烈才對，你不覺得嗎？\n\n我跟你說，這讓我想到一個點子。依據傳說，這些湖泊和河流原本沒有魚，是因為飛過上方的巨龍把魚丟下去，這些水池才有這麼多魚！你能相信嗎？\n\n你和你的飛龍要不要試試看？", progress = nil, completion = "哈！傳說是真的，太驚人了！", rewards = "您會學到：\n\n補充魚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][73227] = {title = "翠玉林", objective = "跟卡雷苟斯說話，收集更多情報。", description = "琦麗苟莎，瑪里苟斯與薩拉苟莎之女，在奧核戰爭中失去了家人，也失去了過往的生活。\n\n在那之後，琦麗苟莎為了找尋永不消逝的夏天，留在了荊棘谷。她雖然找到了冀望的溫暖，但是那裡卻不太寧靜，因此她又搬到了翠玉林裡一座叫做晨綻的小村莊去。\n\n她若回來跟大家團聚，藍龍一定會很歡迎她。", progress = nil, completion = "…琦麗。對，我知道她在哪。", rewards = "您會收到：\n\n"}
