MultiLanguageQuestData['tw'][73386] = {title = "獲得新造型：石蹄牛頭人", objective = "將兵團錫箔包裝套用在《魔獸兵團》迷你棋上，獲得新造型！", description = nil, progress = "將兵團錫箔包裝套用在《魔獸兵團》迷你棋上，獲得新造型！", completion = "恭喜！你的石蹄牛頭人迷你棋多了一個造型！", rewards = nil}
