MultiLanguageQuestData['tw'][74379] = {title = "境內所及", objective = "殺死位於禁忌之境龍隊舊訓練場的誓法者捕翼者。", description = "當半龍人被困在靜滯中的時候，織法者瑪里苟斯的古老僕人 - 誓法者，是我們的看守者。雖然那頭巨龍多年前就已經被殺死，其麾下許多部隊仍對他忠心耿耿，也繼續遵守著他的命令，也就是封鎖這座島嶼。他們對任何失蹤、負傷或是下落不明的半龍人來說都是個威脅。\n\n根據斥候的回報，有個體型壯碩的誓法者蠻卒仍在四處追殺逃脫的半龍人。我們必須解決這個危險的追捕者才行。", progress = nil, completion = "謝謝你，&lt;class&gt;。現在我們可以安心在禁忌之境進行搜救行動了。\n\n雖然有些同胞再也回不了家，但你的舉動已幫助了許多半龍人找到飛回家的路。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][74381] = {title = "神秘遺產", objective = "到守護巨龍之座與治療之翼特使談話，了解禁忌之境的現況。", description = "菈薩葛絲和她的風暴都消散了，但我們的麻煩還沒結束。\n\n通往禁忌之境的道路再次開啟，有些盟友已經回來並建立了營地。但是，沙卡瑞斯和碎裂火焰軍也開始朝那裡邁進。\n\n我們要守住這座島，而且會需要你的協助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74382] = {title = "集體盛宴", objective = "完成任務後，你將獲得：\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74389] = {title = "拍攝火山口", objective = "飛越治癒者火山口，用鏡頭捕捉當地野生動物的蹤跡。", description = "治癒者火山口的節肢動物實在太凶殘了。我們有架旋翼機就是在那裡失蹤的！\n\n我們的遠征隊派了一部偵察機過去，結果一去不回。你可以去搜索那台旋翼機嗎？然後駕駛它來拍攝火山口的野生動物嗎？", progress = nil, completion = "做得好！大量的照片能讓我們的記錄更加完善！", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][74390] = {title = "凶猛獵物", objective = "獵殺禁忌之境各處的精英生物。", description = "對一名獵人高手來說，這個地方到處都是機會。我們要你一起來狩獵。\n\n某些威脅極具凶性。我敢說，某些最大的威脅不只機警，也很狡猾。如果我們分工合作，就能讓禁忌之境成為和從前一樣安全的地方。", progress = nil, completion = "我喜歡你處理問題的方式，他們死有餘辜。", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][74391] = {title = "魚叉手的考驗", objective = "前往龍顱島釣魚洞，從大傢伙身上取得3份大傢伙碎肉。", description = "話說，你注意到這附近是很好的釣場了嗎？龍顱島似乎有一些很不錯的釣魚點。\n\n你何不去釣些魚當晚餐？提醒你一下。我們還需要留一些下來，之後再吃。", progress = "我幾乎可以嚐到那些鮮魚的滋味了！", completion = "我聽說過「精緻餐飲」，我不太知道那是什麼意思，但我知道今晚有頓大餐可吃！", rewards = "您會收到：\n\n元素溢流"}
MultiLanguageQuestData['tw'][74393] = {title = "報告：戰地廢墟", objective = "到戰地廢墟找戰場元帥艾納斯。", description = "我們的處境比我們想得還糟。\n\n加拉登不只掌握了制空權，還打算將他們的長老從亞貝魯斯放出來。萬一讓他們得逞，可能會導致我們永久失去對這個地方的控制權。\n\n去戰地廢墟找戰地指揮官伊格納斯，看看能不能想辦法扭轉劣勢。我們很快就會去跟你會合。", progress = nil, completion = "在外頭看到盟友真好。我們現在正需要盟友。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][74415] = {title = "誠心的祭品", objective = "烹煮獸人料理並在祭品之石處設置先祖盛宴。", description = "現在清單上的所有東西都準備齊全了，只要把它們混合在一起就行了，對吧？這能有多難？\n\n呃…你得自己料理，我不會插手的。我會在旁邊看著。\n\n", progress = "你把任務完成了嗎？", completion = "你做得很好。先祖很少特地穿越到我們的世界、在祭品前顯靈。他們肯定認為你的祭品很有誠意。希望杜洛卡也能珍惜賜予他的那份榮耀。\n\n在榮耀儀式結束後，把你代替其他人獲得的訊息轉達給大家吧。我想他應該會很感謝你。\n\n&lt;她對你快速眨了眨眼。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74436] = {title = "暴風將至", objective = "和洪荒使者未來的索芮朵蜜交談。洪荒使者未來的傳送門就在薩爪祖斯的時光合流。", description = "啊，<class>！我能遇見你真是天時地利人和。\n\n那些元素不只是在目前的時間點威脅巨龍群島，在未來也是一片混亂。前往時光合流，穿越裂隙進入洪荒使者正在肆虐的未來。\n\n到那裡找索芮朵蜜交談，她會告訴你其他細節。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74437] = {title = "對抗風暴", objective = "備妥物資，並且完成洪荒使者未來的「風暴之怒」事件。", description = "儘管我們努力阻止，在這條未來的時間線上，洪荒使者的力量正在逐漸增強。如果他們佔領了這個峽谷，時光合流受到威脅，其他時間之道也會有危險。\n\n時間之道已經承受不了更多威脅了。\n\n<name>，擊退他們。我們必須控制住這個情勢。去找塔諾姆，他會提供你需要的物資。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n可現場部署的熱源"}
