MultiLanguageQuestData['tw'][74441] = {title = "飛鷹大師奈拉克", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74442] = {title = "一隻龍的棄物…", objective = "為沃拉西安尋找一件澤斯克拉密庫內的物品。", description = "你好！我在找我所屬的巨龍軍團過去留下的強大物品。\n\n縱橫歷史，我們一向擁有勇猛的戰士和卓越的戰力，我希望透過找回那些物品來重振往日雄風。\n\n聽說你發現了不少密庫，如果找到了什麼有意思的物品，你可以拿來給我看看嗎？", progress = "你有找到什麼有趣的東西嗎？", completion = "喔，這東西…一定很厲害吧？\n\n雖然看起來不像是武器，但是我認為它值得深入研究。要試試看才知道，對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74443] = {title = "是另一隻龍的珍寶？", objective = "在禁忌之境和沃拉西安交談。", description = "我不得不承認，這東西把我考倒了。\n\n這是件黑龍造物。這可以從握柄上的裝飾判斷出來，但我完全不知道它是什麼東西。這就是我想請教你的部份。\n\n聽說你去過群島各地，你有推薦的詢問對象嗎？", progress = nil, completion = "你覺得這個叫做維利提斯塔茲的人能幫上忙嗎？我願意試一試！\n\n你的建議很棒，&lt;name&gt;。", rewards = "您會收到：\n\n"}
