MultiLanguageQuestData['tw'][74445] = {title = "Forbidden Reach 1/1 C and D", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74447] = {title = "講古時間", objective = "跟維利提斯塔茲談話", description = "所以，你說的這個維利提斯塔茲…我們要去哪找他呢？\n\n晶紅生命聖殿嗎？你真的不是在藉機把我引薦給雅立史卓莎？\n\n不是嗎？那太好了！我會到晶紅生命聖殿去跟你碰面！", progress = "希望會有令人期待的東西！", completion = "嗯，這讓人有點失望。\n\n古老的孵蛋裝置確實算是文化的一部分，不過好像不會特別讓人振奮。\n\n如果你在密庫裡找到其他有趣的東西，我會想看看。", rewards = "您會收到：\n\n"}
