MultiLanguageQuestData['tw'][74489] = {title = "極速祖薩", objective = "協助祖薩多姆滑翔通過檢查環。", description = "青銅幼龍想贏的時候，會變得很魯莽，所以要小心時間之道！\n\n：變身為成年龍並提高速度。\n：恢復1點活力，直到恢復所有活力為止。\n：重置冷卻時間。您會收到：\n\n\n\n等級 70–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶磨亮的寵物吊飾\n\n等級 70–70野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][74491] = {title = "杆位波西德里思", objective = "協助波西德里思滑翔通過檢查環。", description = "翡翠幼龍很常半路睡著，然後突然加速，所以需要盡全力跟上速度。\n\n：往上飛，然後恢復1點活力。\n：使生命之風的持續時間延長5秒。\n：每次恢復活力時，都會向前衝刺。您會收到：\n\n\n\n等級 70–80", progress = nil, completion = nil, rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶龍類戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石磨亮的寵物吊飾\n\n等級 70–70野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石元素生物戰鬥訓練石飛行生物戰鬥訓練石魔法戰鬥訓練石無瑕的戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][74492] = {title = "極速貝菈史卓莎", objective = "協助貝菈史卓莎滑翔通過檢查環。", description = "晶紅幼龍可能會有點失控，所以祝你好運！\n\n：持續消耗所有活力。\n：恢復所有活力，每次都向前加速。\n：消耗赤紅飛行，重置冷卻時間。", progress = nil, completion = "做得好！", rewards = "您會收到：\n\n\n\n等級 70–80戰寵繃帶飛行生物戰鬥訓練石磨亮的寵物吊飾\n\n等級 70–70野獸戰鬥訓練石人形生物戰鬥訓練石機械戰鬥訓練石小動物戰鬥訓練石龍類戰鬥訓練石元素生物戰鬥訓練石魔法戰鬥訓練石不死生物戰鬥訓練石水棲生物戰鬥訓練石無瑕的戰鬥訓練石魔化戰鬥訓練石龍石"}
MultiLanguageQuestData['tw'][74493] = {title = "一次不行，就再試一次", objective = "找出古怪圓形物品的起源。", description = "<沃拉西安把那古怪圓形物品放在手上把玩著。>\n\n嗯，它落在手上的手感很不錯，也許它就是這樣用的。我們去問維利提斯塔茲，看他知不知道這是什麼吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74495] = {title = "哈西安的故事", objective = "聆聽哈西安的故事。", description = "哈囉，<name>，很高興見到你。\n\n你願意跟我們在火邊坐一下嗎？我想是時候來說說一個古老黑龍軍團的好故事了。\n\n我曾經答應你跟沃拉西安，我會跟你們談談你在澤斯克拉密庫找到的瓶子。我想說這個故事的時候到了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n巨龍群島補給品"}
MultiLanguageQuestData['tw'][74501] = {title = "元素灌能營地：燼風", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n莫魯克半人馬徽記"}
