MultiLanguageQuestData['tw'][74503] = {title = "另一份贈禮", objective = "輸出：額外禮物權限需要授權代幣。", description = nil, progress = "輸出：額外禮物權限需要授權代幣。", completion = "輸出：請接受這份禮物。\n\n管理者禮物分配程序。", rewards = "您會收到：\n\n破舊的禮物包"}
