MultiLanguageQuestData['tw'][74847] = {title = "安珀莎在等候", objective = "到莫克特村的峭壁上方與安珀莎會合。", description = "現在絕不能鬆懈。雖然不知道能維持多久，不過營地的狀況還算安穩…我應該能夠從這裡維持整體運作。\n\n安珀莎已經到了，就在你外出的時候。她和她的盟友正從峭壁上方勘察這個地區。我認為最好去跟她見個面。我們不希望她試圖獨自奪下禁忌之境。", progress = nil, completion = "這裡曾是我們的訓練場…我們的許多同伴也在這裡安息。\n\n這裡還有許多秘密。還有許多疑問。幸運的話，我們會找到答案。", rewards = "您會收到：\n\n未利用的禁忌知識"}
MultiLanguageQuestData['tw'][74857] = {title = "老鼠偵探", objective = "尋找失蹤的老鼠。", description = "我通常會把陌生人從我的土地上趕出去，但今天例外。\n\n我的嗅聞鼠不見了。我呼叫珀西的時候她沒出現，這不像她會做的事…\n\n我的嗅覺沒有其他鼴鼠人好，少了她的幫忙，我沒辦法處理收成。\n\n她自己一個人在外面一定很害怕…拜託，你必須把珀西找回來！", progress = nil, completion = "那個鼴鼠人真的很想念他的老鼠耶？嗯…", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][74858] = {title = "農業", objective = "收集6個發光孢子。", description = "那個鼴鼠人說，嗅聞鼠的嗅覺非常靈敏，這種生物能在洞穴中穿梭自如，並找出速度最快的競速蝸牛，甚至能聞出準備好收成的發光孢子。\n\n但是我的嗅覺也挺敏銳的，也許我也能聞出那些發光孢子在哪！\n\n一起幫隱士收成孢子吧。這可以讓他明白，少了他的老鼠朋友也不是那麼糟的事，因為我可以代勞！", progress = "要是有嗅聞鼠，這件事就簡單多了。不過，我也不介意用辛苦的方法做！", completion = "看吧？就跟嗅聞鼠一樣好！\n\n希望隱士也會認同…", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][74859] = {title = "孢子蛾消滅者", objective = "殺死10隻孢子蛾。", description = "看來孢子蛾在毀壞那些收成。\n\n如果牠們繼續這樣把孢子吃掉，隱士就會失去所有收成。\n\n我們必須削減孢子蛾的數量，讓作物健康長大。同時，這也可以讓他知道我懂得怎麼照顧農場。", progress = nil, completion = "這樣應該可以讓孢子好好成長了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][74860] = {title = "友好介紹", objective = "把收成送去給亞倫，並將亞葛盧介紹給他。", description = "是時候把收成送去給隱士了。也許在他看到我們的優良表現後，他會願意雇我當農場幫手！\n\n我，呃…之前有次嘗試跟他說話。我那時想問他需不需要個助手。\n\n他似乎不太喜歡訪客，尤其是卓格巴族。因為這樣，我緊張到還來不及開口就跑走了。\n\n既然你在找他的老鼠，你可以介紹我們認識嗎？", progress = "你必須找到珀西才行，不然大事就不好了！", completion = "那個卓格巴人會跑走，一定是因為他做了虧心事！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][74861] = {title = "不友好對質", objective = "找到亞葛盧。", description = "我認得那個卓格巴人的聲音。\n\n搞不好把珀西抓走的就是他。他一定知道她在哪！\n\n拜託你，$p，請幫我找到那個大個子惡霸。不管用什麼方法，請把珀西帶回來吧！", progress = nil, completion = "我根本不該為馬羅格工作的…", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][74866] = {title = "日誌條目：實驗", objective = "收集日誌條目。", description = "<這個遠古書頁被周圍的魔法束縛住，上面的文字是古龍語。>\n\n<龍隊指揮官一定會對裡面的內容很感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74869] = {title = "解開原初之謎", objective = "從澤斯克拉密庫的元素取得原初地土核心、原初烈焰核心、原初流水核心和原初風暴核心。", description = "真相就在這個密庫之中等著我們。也許我們能找到辦法保護自己，抵制洪荒使者的魔法。躲在這些密庫中的元素生物既古老又狂野，完全不受洪荒使者控制。透過它們，也許可以知道如何幫助地表上的元素生物。\n\n我有個主意。我們需要四個原初核心。然後我們可以打造一個咒符，用來淨化和消除洪荒使者的控制力，解放外面的元素生物。\n\n要是你幫助我們，我願意分享我們在這裡發現的東西。", progress = "你找到核心了嗎？", completion = "這些原初核心正是我需要的。\n\n請讓我和你分享我找到的東西。希望能幫上你的忙。", rewards = "您會收到：\n\n\n\n任意等級澤斯克拉密庫鑰匙奈薩里奧贈禮勳章稜石碎片凝結火焰魔法凝結冰霜魔法凝結大地魔法凝結暗影魔法凝結死靈魔法\n\n等級 70–70凝結自然魔法凝結秘法魔法元素溢流元素溢流元素溢流元素溢流"}
MultiLanguageQuestData['tw'][74871] = {title = "生命火花：禁忌之境", objective = "在戰爭模式下，於禁忌之境收集50個生命火花。", description = "禁忌之境充滿了巨龍群島的活力。\n\n去吧，探索並捕捉火花，不過記得保持警惕，你可能隨時會遇到戰鬥者。", progress = "從那個門出去就是了。絕不會出錯。", completion = "協調者萬分感謝你。", rewards = "您會收到：\n\n鬥爭戰利品碎裂的鬥爭戰利品巨龍群島補給品鬥爭戰利品榮譽點數征服點數"}
MultiLanguageQuestData['tw'][74875] = {title = "春神復甦", objective = "到剃刀嶺、布瑞爾、血蹄村或獵鷹之翼廣場與春日蒐集者談話。", description = "如果你想找點事情做，我聽說有些法師跑到各大主城附近的聚落，像是剃刀嶺、布瑞爾、血蹄村和獵鷹之翼廣場，在那裡招募彩蛋獵人，好像要進行什麼研究。詳情我並不清楚，不過他們一定會告訴你的。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74876] = {title = "互助系統", objective = "和邁里特一起來場挖掘探險。", description = "噢，你好啊。我剛剛又把內心想法說出來了嗎？\n\n我不想用我的問題麻煩別人，可是…\n\n是這樣的，我是個嗅探者。我們會在洞穴各處找尋獨特和令人驚豔的地方！不過我們在洛姆有個重要的規則：我們都會遵守互助系統，不會有人獨自挖地。\n\n我從小到大的夥伴都是同一個，可是她現在太忙了沒辦法挖地。我找到了一股有趣的新氣味，要是以前的話，我有夥伴可以一起去…\n\n讓你來當我的臨時挖地夥伴怎麼樣啊？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74877] = {title = "好朋友", objective = "為邁里特和伊芙維絲塔安排挖地。", description = "說真的，我真的喜歡跟你一起挖地。真的！我不是在抱怨你，可是…我很想我的好朋友。\n\n她很忙，這我不怪她。她之前被綁架，而且又是個公主！我知道她沒什麼空閒時間，我只是希望…\n\n…我不知道耶。\n\n或許我只希望一切能恢復到以前那樣，回到她還想跟我一起挖地的時候。", progress = "是伊芙維絲塔最愛的點心…", completion = "她可能忘了，或是還在忙。", rewards = "您會收到：\n\n"}
