MultiLanguageQuestData['tw'][74908] = {title = "新的冒險", objective = "與編目員達菈交談。", description = "編目員達菈在此調查充滿各種驚奇和神秘的地方。天狐巢穴和治癒者火山口似乎是最有可能的地點。\n\n完成她的任務，就會解鎖她今天的特使任務。你明天可以解鎖其他陣營的特使任務。", progress = nil, completion = "太驚人了！我們必須好好規劃我們的下一步。我會給你詳細的指示。", rewards = "您會學到：\n\n解鎖龍鱗遠征隊的特使任務\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][74909] = {title = "新的漁獲", objective = "與圖里克交談。", description = "圖里克代表伊斯凱拉巨牙海民，在此調查禁忌之境海域的豐饒程度。\n\n完成這個任務，就會解鎖他今天的特使任務。你明天將能解鎖其他陣營的特使任務。", progress = nil, completion = "今天的魚真容易上鉤！", rewards = "您會學到：\n\n解鎖伊斯凱拉巨牙海民的特使任務\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][74910] = {title = "新的敵人", objective = "與說書人艾許克交談。", description = "說書人艾許克在此偵查莫魯克的敵人。\n\n完成這個任務，就會解鎖她今天的特使任務。你明天將能解鎖其他陣營的特使任務。", progress = nil, completion = "讓我衡量一下敵人的實力。還有很多事要做。", rewards = "您會學到：\n\n解鎖莫魯克半人馬的特使任務\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][74911] = {title = "全新視野", objective = "與克拉瑟斯交談。", description = "克拉瑟斯代表沃卓肯協調者在禁忌之境從事各種行動。\n\n完成這個任務，就會解鎖他今天的特使任務。你明天將能解鎖其他陣營的特使任務。", progress = nil, completion = "歡迎來到禁忌之境，朋友！", rewards = "您會學到：\n\n解鎖沃卓肯協調者的特使任務\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][74912] = {title = "奈薩里奧的遺產", objective = "去沃卓肯與諾茲多姆見面。", description = "<在你盯著裂開的泰坦寶石看時，一個聲音突然在你腦海中迴盪。>\n\n<name>！我是諾茲多姆。\n\n你的創造者奈薩里奧過去犯下許多罪行，而現在，贖罪的機會來了。\n\n奈薩里奧曾使用某種神器控制你和其他所有的半龍人，而你手上擁有這個神器的關鍵部分。\n\n到沃卓肯來找我吧。我們有很多事要討論。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74913] = {title = "神器的回憶", objective = "跟諾茲多姆在扎拉萊克洞穴見面。", description = "在我嘗試找出誓縛者時，安珀莎幫過我的忙。誓縛者就是奈薩里奧用來控制你們的神器。\n\n為了找出能反制這個神器的東西，以及如何製作這樣的物品，我找遍了所有的時間線。\n\n你剛發現的這顆寶石就是關鍵，它能讓我的研究有所突破。\n\n我們到扎拉萊克洞穴碰面吧，那裡就是當初你們為了搶奪損壞的誓縛者而開戰的地方。\n\n那地方藏著祕密，而那祕密能幫助我們鍛造能反抗暴政的武器。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74923] = {title = "製作神器需要眾人合作", objective = "使用遠古回憶教導其他人或你自己如何鍛造新神器所需的部件。\n\n你必須透過工作訂單從盟友那裡取得這些部件。", description = "是時候出發了，去找人幫忙你製作鍛造新手套所需的關鍵部件吧。\n\n一般而言，秩序精華不容易找到，不過在你取得這些回憶後，你應該能在多個地點找回精華。\n\n這雙新手套能讓你的盟友和社群獲得強化…也就是說，你必須依靠他人來完成這項任務。\n\n帶上你取回的回憶，用它來教導其他人如何製作各項部件。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74924] = {title = "『無縛傳承』納茲烏洛", objective = "與諾茲多姆交談，並前往大漩渦見證奈薩里奧落敗的時刻。", description = "我的研究顯示，神器的最後這個部件是賦予它反制誓縛者能力的關鍵。\n\n奈薩里奧的精華。\n\n關於這個部分，我能幫上半龍人的忙。一起前往大漩渦，見證他最後的時刻吧。\n\n有了他的精華後，我們的神器『無縛傳承』納茲烏洛就能製作完成了。\n\n準備好了，就跟我交談。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74939] = {title = "磺石混合賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74945] = {title = "鳥糞石策略", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74946] = {title = "避難所", objective = "到托古薩克村找貝恩和托姆爾。", description = "我們接下來的當務之急是追上在波凡停留期間逃跑的其他人。希望波凡和其他勇士已經跟他們再次會合了。\n\n這位托姆爾說，牛頭人最可能的避難地點，應該是東南方的一座廢棄村莊。\n\n雖然她的話聽起來合情合理，但那裡也是設下陷阱的完美地點。\n\n<name>，既然你願意替她背書，我可以信她一次。\n\n希望她不會辜負你的信任。", progress = nil, completion = "好消息是我們找到其他牛頭人了。\n\n壞消息是他想找的波凡不在這裡。\n\n更糟糕的是，每個人都想要我死。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74948] = {title = "蝸牛激勵：紫晶軟殼蝸牛", objective = "召喚一隻滿等的紫晶軟殼蝸牛戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "哇，真美啊。而且牠們是海裡來的？我沒辦法想像我的蝸牛可以承受那麼多鹽分。\n\n滑頭一定感到印象深刻。", rewards = nil}
MultiLanguageQuestData['tw'][74949] = {title = "蝸牛激勵：警戒原型", objective = "召喚一隻滿等的警戒原型戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "那…是我看過最奇異、最華麗的蝸牛。\n\n要是滑頭看到牠不覺得驚豔，我就不知道有什麼蝸牛可以讓他驚豔了。", rewards = nil}
MultiLanguageQuestData['tw'][74950] = {title = "蝸牛激勵：黑谷爬行者", objective = "召喚一隻滿等的黑谷爬行者戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "這就是喜歡洞穴的蝸牛會有的樣子！滑頭一定深有同感。\n\n我自己就深有同感。", rewards = nil}
MultiLanguageQuestData['tw'][74951] = {title = "幻光彎道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74952] = {title = "蝸牛激勵：小原蝸", objective = "召喚一隻滿等的小原蝸戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "我看不出牠名字裡有「小」的原因，但牠確實是隻有殼蝸牛。可是我想，跟滑頭比起來大部分蝸牛都很小！", rewards = nil}
MultiLanguageQuestData['tw'][74953] = {title = "沉重的皇冠", objective = "幫忙創造一段邁里特可以跟伊芙維絲塔說話的時間。", description = "伊芙維絲塔答應要來可是沒來時，我真的很沮喪。\n\n不過我懂她很忙，她之前被綁架，現在還有一堆責任。所以我不怪她。\n\n不過，我很想跟她說，我很珍惜我們小時候共度的時光，還有只要她需要我，我都會在旁邊陪她。這樣，至少她會知道我還在。\n\n你可以幫我吸引她的注意，讓我有時間說我想說的話嗎？", progress = nil, completion = "在她來這裡之後，我反而不知道要說什麼！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][74954] = {title = "幻光進階彎道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][74959] = {title = "蝸牛激勵：泥殼海螺", objective = "召喚一隻滿等的泥殼海螺戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "大部分的人看到泥殼海螺海螺時，都會想問：這有什麼特別的？不過我啊，我欣賞簡單的事物，這其中也有它的美。\n\n滑頭一定也認同！", rewards = nil}
MultiLanguageQuestData['tw'][74960] = {title = "蝸牛激勵：掠食原蝸", objective = "召喚一隻滿等的掠食原蝸戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "掠食是吧？別讓那個小傢伙接近我的水桶就好。我可不希望意外「再次」發生。\n\n&lt;布莉古爾望向遠方，眼神複雜。&gt;\n\n不過，我敢說滑頭感受到那股戰鬥精神了。", rewards = nil}
MultiLanguageQuestData['tw'][74961] = {title = "蝸牛激勵：稜光軟殼蝸牛", objective = "召喚一隻滿等的稜光軟殼蝸牛戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "稜光是吧？那是五彩繽紛的文謅謅說法嗎？嗯，這隻蝸牛確實很符合。希望滑頭不會覺得自己的殼不夠「浮蝸」，哈！\n\n他自己也很漂亮。", rewards = nil}
MultiLanguageQuestData['tw'][74962] = {title = "蝸牛激勵：紅螺", objective = "召喚一隻滿等的紅螺戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "別被牠給騙了，&lt;name&gt;。我感覺得出來，牠很不好惹。希望滑頭受到的是激勵，不是驚嚇！", rewards = nil}
MultiLanguageQuestData['tw'][74963] = {title = "蝸牛激勵：鏽蝕蝸牛", objective = "召喚一隻滿等的鏽蝕蝸牛戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "噢，鏽蝕指的是顏色！我本來有點擔心，你是不是沒有好好照顧這個小寶貝。你害我為滑頭擔心了一下！\n\n呼，真讓人鬆一口氣。", rewards = nil}
MultiLanguageQuestData['tw'][74964] = {title = "蝸牛激勵：小蝸牛史庫特", objective = "召喚一隻滿等的小蝸牛史庫特戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "看看牠的殼啊！你說這是個小孩送你的？\n\n真慶幸是你拿到！小鬼通常對蝸牛…都沒那麼好。", rewards = nil}
MultiLanguageQuestData['tw'][74965] = {title = "蝸牛激勵：殼殼", objective = "召喚一隻滿等的殼殼戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "我真喜歡「殼殼」這名字。或許這個小傢伙是滑頭失散多年的親人！\n\n&lt;布莉古爾又看了一眼遠古蝸牛。&gt;\n\n可能失散了…非常非常久。", rewards = nil}
MultiLanguageQuestData['tw'][74966] = {title = "蝸牛激勵：絲珠蝸牛", objective = "召喚一隻滿等的絲珠蝸牛戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "你看這小傢伙動起來的樣子！這隻絲珠蝸牛的黏液有某種類似絲質的成分。\n\n我不太確定滑頭該怎麼效法牠，不過你倒是可以。", rewards = nil}
MultiLanguageQuestData['tw'][74967] = {title = "蝸牛激勵：螺殼蝸牛", objective = "召喚一隻滿等的螺殼蝸牛戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "我看得出來，滑頭「螺」想跟你這隻蝸牛一樣強壯！哈！\n\n&lt;布莉古爾擦去眼中開心的淚水。&gt;\n\n我下次競速應該這麼說的。我一定要講給其他訓練師聽。", rewards = nil}
MultiLanguageQuestData['tw'][74968] = {title = "蝸牛激勵：極速蝸蝸", objective = "召喚一隻滿等的極速蝸蝸戰寵，並把牠給布莉古爾看。", description = "我在你身上聞到陌生的蝸牛味。你有什麼事瞞著我嗎？\n\n沒什麼人知道這點，不過蝸牛非常容易受同儕壓力影響。展示一下你的超級蝸牛，給滑頭一點激勵吧。", progress = nil, completion = "是…是極速蝸蝸！高嶺的競速蝸牛傳奇！\n\n我的天啊，我一定要跟爆爆表親講這件事。我太榮幸了，滑頭一定也這麼覺得。", rewards = nil}
