MultiLanguageQuestData['tw'][75518] = {title = "岸上的遺體", objective = "與蘿思卡交談並開始仔細挖掘半人馬遺體。", description = "<這名半人馬女性的遺體狀態令人驚訝。\n\n她穿著你沒看過的衣著，她的皮膚上也刺滿了複雜的紋身。\n\n她的遺體仍保持完好，應該身亡沒多久…應該吧？這附近的環境條件可能更利於保存。\n\n蘿思卡絕對會想看一看！>", progress = nil, completion = "你看！我敢打賭這可憐的女孩已經埋在這片淤沙中有好幾百年了，甚至更久。\n\n像這樣的沼地和河床經常會完好保存埋在其中的事物。\n\n既然現在她被挖出來，我們就可以了解她的身分，還有她怎麼會被埋在這裡！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75519] = {title = "漫長的狩獵", objective = "見證那個訊息。", description = "<多利蘇爾沉默，眼神游移著，對你投向渴望和期待的目光。\n\n高貴的貓頭鷹伸出長著利爪的腳，把灌魔水晶交給你。在水晶中，你感覺到了某個訊息。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75538] = {title = "強行要求", objective = "前往暗月馬戲團。", description = "<race>，向你致上最黑暗的問候。咳咳，沒錯！就是最黑暗的問候。\n\n<又高又瘦的男子彷彿突然記得自己在哪裡一般。>\n\n我代表我的客戶，請你前往暗月馬戲團。馬戲團！有誰不愛呢？沒錯、沒錯！\n\n咳咳\n\n她想要見你，沒錯！我們的…夜月女主、黑暗仕女！烏鴉之母…\n\n…暗影女士。", progress = nil, completion = "你比我記憶中…還要嬌小。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75539] = {title = "有邪物過來了", objective = "在暗月馬戲團各處和剛來的術士談話。", description = "$p，你來見我了，菲尼亞斯做得好。有很多工作必須完成。\n\n最好快點開始！\n\n身為黑魔法的大師，我需要你協助我讓這些新人進入狀況。去跟他們談話。他們各個都有不同的背景，而且全都不熟悉黑魔法。\n\n去了解他們的渴求。\n\n他們的願望。\n\n他們的夢想。\n\n我們踏上的道路可以賜予無盡的贈禮和難以想像的力量，人們只需要知道自己真正的渴求是什麼…您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75540] = {title = "神秘的保險", objective = "在暗月馬戲團對自願的學徒使用暗影女士的靈魂石。", description = "啊，最新的一群人已經在我的羽翼下聚集，就像雛鳥跟母鳥一樣。你目前表現得不錯，$p。他們很信任你。\n\n我很信任你。\n\n要帶這些單純的靈魂走上險惡的旅程，下一步就是保護他們不受虛無、毀滅、死亡所害。\n\n把我的靈魂石拿去，用它來為自願者…跟天譴者做好準備。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75541] = {title = "猶豫之人", objective = "在暗月馬戲團與學徒歐曼談話。", description = "嗯。\n\n名單上有一個人現在不在這裡。\n\n是那個德萊尼。\n\n<暗影女士吸一口氣。>\n\n我可以感受到他的聖光。去吧，確保他重新加入我們。\n\n我們還有很多工作要做。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75542] = {title = "詛咒與教徒", objective = "在暗月馬戲團把暗影女士魔典中的詛咒傳授給學徒。", description = "小麥與穀糠分離完畢，現在可以來點好玩的了。\n\n我為我們的學生計畫了一趟刺激的…遠足…不過他們還沒準備好。把我的魔典拿去，讓熊貓人、贊達拉人和牛頭人試試看詛咒。\n\n我在我們的園區周圍發現了一些徘徊的不速之客。就算違反他們的意願，他們依然是很好的實驗品。\n\n我會讓歐曼在遠方召喚這群人，我會再給他指示。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75543] = {title = "意外的最後儀式", objective = "穿過惡魔之門並幫助學徒。", description = "<你可以聽到傳送門的另一端傳來微弱的尖叫聲。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75544] = {title = "復仇綠火", objective = "在詛咒之地和暗影女士對質。", description = "不管暗影女士在玩什麼遊戲，看來我們已經快玩完了。\n\n<歐曼痛苦地呻吟。>\n\n從我們聽到的來看，我們的下個目的地應該是在詛咒之地的某處。我必須休息，可是拜託你，$p…去結束這一切吧。讓暗影女士付出代價，為我們的術士同胞復仇。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n邪惡小鬼\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][75569] = {title = "黑龍鐵匠", objective = "收集8個黑鑄鎧甲。", description = "據說扎拉萊克洞窟北方的黑龍龍類是技術最精良的鐵匠。\n\n他們總喜歡聲稱這是因為他們貴為「大地的支配者」。哼，我倒想看看有哪隻龍可以像鼴鼠人一樣鑽地打洞！\n\n儘管如此，從成品看來，他們的手藝確實高明。帶一些給洛姆的窯燒大師克魯布斯，讓他研究一下他們的技術吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][75573] = {title = "回收宣言", objective = "收集10個灌能宣言。", description = "你知道有誰會喜歡自說自話、喜歡官僚主義，而且會對自己的紀錄附魔嗎？只有龍會！\n\n到洛姆北部的舊黑龍堡壘附近去看一看，一定滿地都是各式各樣經過附魔的敕令、文告，甚至是購物清單！\n\n把你發掘的一切事物帶回給洛姆的『鑿匠』史克里多沙。我很確定她會喜歡解讀這些附魔的新東西！", progress = "他們就是喜歡搞得很複雜，是不是？", completion = "&lt;史克里多沙翻閱著文件。&gt;\n\n「經我之手…」、「大地守護者之意志…」、「聽我號令…」，這聽起來就是龍會說的話！\n\n雖然讀起來可能有點乏味，但這會是份有趣的研究材料。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][75575] = {title = "弩砲殘骸", objective = "收集10個弩砲殘骸。", description = "雖然那些加拉登聞起來像野獸，但是能打造出威力足以屠龍的弩炮，他們工程師兵團的水準絕對是一流的！\n\n他們和一些黑龍在洛姆東北部正激烈戰鬥著，那一帶應該到處都可以找到備用零件。零件可能稍微有使用痕跡，或甚至著火，都可以！\n\n全部都帶回洛姆吧，一點燒焦痕跡不影響我們對它進行鼴鼠人逆向工程法。", progress = "不知道他們用什麼做為扭轉力的來源？", completion = "真有趣。考慮到機械承受的壓力，我還以為不會有這麼多骨架！", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][75598] = {title = "搞定蝸牛", objective = "向滑頭自我介紹。", description = "嗯，你以前騎過蝸牛嗎？\n\n我已經訓練過好幾代競速蝸牛冠軍了，不過我最近遇到了天大的難題。簡單來說，他太大隻了，直接被禁賽。\n\n不過，把這麼優秀的個體關在桶子裡太可惜了。我知道滑頭很有潛力，只要你協助我訓練滑頭，我就把他送給你！", progress = nil, completion = "這是我最驕傲的時刻。你們表現超好。\n\n有實力應付蝸牛競速的快步調的人並不多，可是你呢？你就有這樣的實力。滑頭以後可以和你一起出去冒險了，我知道他一定會喜歡這樣的生活。\n\n&lt;布莉古爾一邊抽搭一邊拍拍滑溜溜的殼。&gt;\n\n踏上滑頭旅程吧，大個子。記得要回來看我們！", rewards = "您會收到：\n\n城中大滑頭"}
MultiLanguageQuestData['tw'][75600] = {title = "又絲又稠", objective = "收集8個鈣絲捆。", description = "雖然你們住在地表的傢伙有很多我們沒有的花俏材料，但是我們也有很多種你們絕對沒有的絲綢！\n\n洛姆附近的蜘蛛做出的絲綢，有我聞過最有意思的氣味！我猜這可能跟牠們的飲食有關。\n\n如果你能收集一些來，洛姆的羅斯瑪就教你怎麼使用它！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][75602] = {title = "來自古老水晶的碎片", objective = "收集10個活化碎片。", description = "我們家附近的水晶生物既神秘又強大。\n\n他們是如何移動的？他們這樣算是活著嗎？他們吃起來是什麼味道？\n\n幫法妮莉帶幾個樣本來好開始研究。別帶太大的來，不然鼴鼠人就要被踩扁了。", progress = "不知道我們能從其中得到什麼收穫呢？", completion = "這太驚人了，&lt;name&gt;。謝謝你為藝術做出貢獻。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][75603] = {title = "善待她的遺體", objective = "向說書人賈盧、蹄鐵匠榮妲兒與提迦里可汗諮詢要怎麼處理這具遠古遺體。", description = "這女孩埋在這裡有很長一段時間了。她的遺體能保持得這麼完好還真是個奇蹟。\n\n從沙石中挖出陶土碎片需要專業技巧，但這會需要比你我還更細心、更專業的技術才能挖掘。莫魯凱離這裡不遠…\n\n我們應該把這件事告訴那群半人馬，讓他們決定怎麼處理，你看怎麼樣？\n\n然後在請教他們的時候，相信他們專業的工匠也可以告訴我們她這身裝備的事。", progress = nil, completion = "&lt;name&gt;，沒有比這更棒的事了。歷史的新篇章逐一揭露，所有人聚集在此見證這項發現…\n\n這絕對會名留青史！\n\n辛苦地在這泥巴中揮灑汗水也都值得了，對不對？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75604] = {title = "古老的文物", objective = "尋找洛姆跟黑龍軍團的專家，來對這個發現進行分析。", description = "嗯，有兩件事可以深究了，是吧？\n\n首要，我們該盡責找出這尊雕像刻的是誰。偷偷跟你說，我比較感興趣的其實是那些把這東西變成藝術品的惡作劇之人。\n\n我確信亞貝魯斯附近有一位黑龍軍團歷史學家。你要不要繼續在洛姆打探，然後看看有沒有跟這種…藝術執照有關的情報。", progress = nil, completion = "我們繼續在高塔附近挖掘吧。\n\n這裡還有很多垃圾堆可以挖。就算我們後來都沒找到這麼特別的東西，我們還是有很多文物可以研究，了解在巨龍再次回到這裡之前，鼴鼠人過著什麼樣的生活。\n\n但我想，我們今天的進度已經夠了！", rewards = "這個任務線能解鎖：\n\n艾澤拉斯文庫：扎拉萊克洞窟，奈薩里奧之視挖掘場\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][75608] = {title = "泰坦垃圾？泰坦珍寶？", objective = "收集10個石工裝備。", description = "看守者入睡後，身邊各式各樣驚人的科技就這樣放著，無人看管。\n\n即使是他們古老的淘汰品，也能讓我們獲益良多。就連他們最不起眼的裝置，對我們來說也是不可思議的奇蹟！\n\n要是有個勇敢、聰明又…恕我冒昧，又如此英俊的人可以去取回一些樣本讓優秀的洛姆鼴鼠人工程師檢視一番，那該有多好…很耳熟嗎？", progress = "不知道我們什麼時候才能真正了解他們的科技。", completion = "你問我石工裝備是什麼？我也不知道，但是我很期待找出答案！", rewards = "您會收到：\n\n工程學資料"}
