MultiLanguageQuestData['tw'][75706] = {title = "跑向終點", objective = "協助狡猾鬼在競速中獲勝。", description = "大家都喜歡精彩的蝸牛競賽！在最刺激的競賽中，每隻蝸牛都有獲勝的機會。\n\n你可以給蝸牛點心來協助牠得勝。看看點心可以讓牠們跑多快！\n\n拿一袋點心，把它們丟在蝸牛的賽道上，看看你能不能讓狡猾鬼獲勝！", progress = nil, completion = "真是場偉大的勝利。狡猾鬼的訓練師應該換你來當！", rewards = "您會收到：\n\n狡猾鬼龍石"}
MultiLanguageQuestData['tw'][75707] = {title = "跑向終點", objective = "協助烤布蕾在競速中獲勝。", description = "大家都喜歡精彩的蝸牛競賽！在最刺激的競賽中，每隻蝸牛都有獲勝的機會。\n\n你可以給蝸牛點心來協助牠得勝。看看點心可以讓牠們跑多快！\n\n拿一袋點心，把它們丟在蝸牛的賽道上，看看你能不能讓烤布蕾獲勝！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n烤布蕾龍石"}
MultiLanguageQuestData['tw'][75709] = {title = "找到兵團硬幣", objective = "在暴風港找出兵團硬幣，然後把它投入《魔獸兵團》遊戲機。", description = "你需要兵團硬幣才能使用這台遊戲機。\n\n巨龍群島各處都可以找到兵團硬幣，我們可以等等再談這個。\n\n我在碼頭這裡藏了一個硬幣，如果你能找到它，那硬幣就是你的了。\n\n把那枚兵團硬幣投入《魔獸兵團》遊戲機，就可以開始玩囉！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n兵團抽獎盒"}
MultiLanguageQuestData['tw'][75711] = {title = "找到兵團硬幣", objective = "在破齒旅店找出兵團硬幣，然後把它投入《魔獸兵團》遊戲機。", description = "你需要兵團硬幣才能使用這台遊戲機。\n\n巨龍群島各處都可以找到兵團硬幣，我們可以等等再談這個部份。\n\n我在旅店藏了一個硬幣，如果你能找到它，那硬幣就是你的了。\n\n把那枚兵團硬幣投入《魔獸兵團》遊戲機，就可以開始玩囉！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n兵團抽獎盒"}
MultiLanguageQuestData['tw'][75713] = {title = "《魔獸兵團》迷你棋：新外觀！", objective = "到奧格瑪力量谷的《魔獸兵團》遊戲機位置。", description = "<你發現錫箔包裝上刻有一個訊息。>\n\n你可以去《魔獸兵團》遊戲機那裡使用兵團錫箔包裝。快去吧，幫你的迷你棋換個造型！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75720] = {title = "想交易嗎？", objective = "在洛姆與龐佐談話。", description = "你好，地表人！\n\n我聽說你喜歡助人。那你來幫忙我吧？\n\n我需要人把幾個包裹送到沃卓肯去，只要你不偷看，我就會給你相應的酬勞。\n\n還有，要是你來洛姆，就順便來找我吧，我們可以做個交易。\n\n你的新朋友，龐佐。", progress = nil, completion = "我聞到你帶著我的信，你來幫忙了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75721] = {title = "交易基礎", objective = "將龐佐的盒子拿去沃卓肯給卡揚。", description = "我來跟你說要做什麼。\n\n我有個朋友名叫卡揚，他到沃卓肯那邊去了。我有東西要送給他，你能幫我交給他嗎？\n\n不許有懷疑。不可以看、不可以聞，也不可以嚐。這只能由卡揚親自打開！\n\n如果你同意的話，我就送你上路吧，當然，我會心懷感激！", progress = nil, completion = "光是聞那股味道，我就知道是龐佐的盒子！\n\n謝謝你把它拿上來，這一趟很遠呢！這個給你，龐佐會很樂意買下的。", rewards = "您會收到：\n\n交易磚塊"}
MultiLanguageQuestData['tw'][75722] = {title = "一袋金子", objective = "在洛姆和米穆普談話。", description = "哈囉，$p！\n\n我聽說你一直以來都在幫助我們！像你這樣的人應該要得到回報…而我也有特別的東西要送你！不如到洛姆來找我吧？\n\n繼續加油吧。\n\n米穆普", progress = nil, completion = "我們永遠感謝你！", rewards = "您會收到：\n\n飛龍暗焰紋章龍石"}
MultiLanguageQuestData['tw'][75723] = {title = "洞穴賞龍", objective = "在洛姆和哈蘿威‧瑪爾談話。", description = "哈囉，地表人！\n\n話說，你幫助了我們許多！我們有個小東西想回報你。到洛姆來找我，我再把東西交給你！\n\n祝你安好，\n哈蘿威‧瑪爾", progress = nil, completion = "能有你在是我們的福氣！", rewards = "您能選擇下列奬勵中的一個：\n\n盤旋滑龍：巨角下巴盤旋滑龍：大鰭狀冠盤旋滑龍：棕褐犄角"}
MultiLanguageQuestData['tw'][75724] = {title = "向鼴鼠人族看齊", objective = "在洛姆和米穆普談話。", description = "你好啊，$p！\n\n我們想感謝你給我們的一切幫助。我們才不會良心不安！\n\n到洛姆跟我見面，我會教你怎麼像鼴鼠人一樣挖地！\n\n誠摯祝福你\n米穆普", progress = nil, completion = "戴上這雙長手套，然後把手插進土裡，接著打開你的鼻子感受一下！\n\n你在扎拉萊克洞窟的每個地方都可以聞到洛姆的味道。\n\n秘訣就是這些爪子！永遠是這些爪子！", rewards = "您會收到：\n\n鼴鼠人挖掘長手套巨龍群島補給品巨龍群島補給品巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][75725] = {title = "踏上賽場", objective = "在葛利姆羅格與布莉古爾談話。", description = "嘿，勇士！\n\n我們這裡有一個全新的大好機會，就是蝸牛競賽，你有沒有聽過？是比賽中最激烈的運動項目！\n\n因為你行動力很高，龐佐說你會有興趣。\n\n到葛利姆羅格的賽場來加入我吧！\n\n到時候見。\n布莉古爾", progress = nil, completion = "你來了！現在我們只需要…訓練我們的蝸牛就好！", rewards = nil}
MultiLanguageQuestData['tw'][75727] = {title = "最臭的外袍", objective = "在洛姆和米穆普談話。", description = "你好，$p！\n\n你一直幫我們忙，真的太厲害了。記得要回洛姆領取特別的獎勵！\n\n誠摯祝福你\n米瑪普", progress = nil, completion = "就是這個，手工打造、手工加味！", rewards = "您會收到：\n\n洛姆鼴鼠人外袍巨龍群島補給品巨龍群島補給品巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][75728] = {title = "交易礫石", objective = "在洛姆與龐佐談話。", description = "嘿，地表人！我需要你再一次的協助。\n\n我喜歡你的打鬥風格。但你有看到這些磚頭嗎？它們超沒用的！你可以把它們打成碎石！\n\n到到洛姆來見我，我再告訴你全部的細節。\n\n龐佐", progress = nil, completion = "希望你平常有在健身。這些東西可不輕！", rewards = "您會收到：\n\n交易礫石巨龍群島補給品巨龍群島補給品巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][75729] = {title = "與觀察者同調", objective = "對三個同調文物進行高科技占測。", description = "你相信這裡以前是一座觀測所嗎？我們的紀錄顯示龍類就是在這裡繪製天體運行圖來預測未來的。\n\n你覺得他們是怎麼辦到的呢？\n\n我發現了跟我們要找的時間區間相符的部分信號。戴上高科技占測鏡找出源頭，這樣我們就可以一探究竟了。", progress = nil, completion = "啊哈！給我你的占測鏡，好讓我校正一下。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75730] = {title = "觀看滑龍", objective = "在洛姆和哈蘿威‧瑪爾談話。", description = "唉呀，你好啊！\n\n聽說你一直都在幫助我們，因此我們有個小小東西想送給你。到洛姆來找我，我再把東西交給你！\n\n祝你安好，\n哈蘿威‧瑪爾", progress = nil, completion = "能有你在是我們的福氣！", rewards = "您能選擇下列奬勵中的一個：\n\n盤旋滑龍：棕色毛髮盤旋滑龍：彎曲犄角盤旋滑龍：長角下顎"}
MultiLanguageQuestData['tw'][75731] = {title = "香味長靴", objective = "在洛姆和哈蘿威‧瑪爾談話。", description = "你好啊！\n\n人們都在討論你一直以來的支持。我們找到了你可能用得上的護甲。到洛姆和我會面，看看它們有沒有用處吧。\n\n祝好，\n哈蘿威‧瑪爾", progress = nil, completion = "能有你在是我們的福氣。", rewards = nil}
MultiLanguageQuestData['tw'][75741] = {title = "一堆礫石", objective = "在洛姆與龐佐談話。", description = "對，就是你！\n\n顯然你跟其他人說，我對你很不好是吧。\n\n我沒有，可是他們叫我對你好一點，因為你為我們做了很多事。\n\n什麼佔便宜？我覺得明明就是正當的工作。\n\n為了讓你和其他人滿意，我就給你一些礫石吧。\n\n到洛姆來見我。\n龐佐", progress = nil, completion = "記得要跟米穆普說，我對你很好，聽到了沒？", rewards = "您會收到：\n\n交易礫石龍石"}
MultiLanguageQuestData['tw'][75742] = {title = "飛龍頭盔", objective = "在洛姆和哈蘿威‧瑪爾談話。", description = "你好啊！\n\n人們都在討論你一直以來的支持。\n\n我們有個小東西要給你。到洛姆跟我會面，我再把東西給你！\n\n祝好，\n哈蘿威‧瑪爾", progress = nil, completion = "能有你在是我們的福氣。", rewards = "您會學到：\n\n飛龍頭盔\n\n您還會收到：\n\n巨龍群島補給品巨龍群島補給品巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][75744] = {title = "表達我們的感謝", objective = "在洛姆和米穆普談話。", description = "你好！\n\n由於你為我們提供了許多協助，我們決定也要提供同等的回報。\n\n到洛姆來見我。我們準備了獎勵，已經等不及要給你了。\n\n誠摯祝福你\n米穆普", progress = nil, completion = "感激不盡，地表人！", rewards = "您會收到：\n\n附魔巨龍暗焰紋章"}
MultiLanguageQuestData['tw'][75750] = {title = "它們是不是很美？", objective = "在寵物對戰中擊敗新村", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75765] = {title = "液體藝術", objective = "將滑溜的陶壺帶回洛姆還給它的主人。", description = "<一個裝滿…泥巴的陶壺？\n\n這似乎是鼴鼠人製成的。或許有個洛姆的居民正在找它！>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75766] = {title = "野外的紅寶石", objective = "將閃爍龍寶石送去洛姆給法妮莉。", description = "<龍族製成的盒子裡是一顆鑲嵌在優質金座上的美麗紅寶石。\n\n洛姆的珠寶設計師會很想看看這個珠寶的。>", progress = "真是閃亮！！", completion = "這真是太美了！這是龍族做的嗎？這東西很紅，還閃閃發光！\n\n謝謝你，&lt;name&gt;！", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75767] = {title = "愛玩的男孩", objective = "在洛姆為濕透的圖騰找個新家。", description = "<洞穴的地上擺著一個非常濕的戈洛克圖騰。這東西怎麼會在這？\n\n鼴鼠人很喜歡這樣的東西，或許洛姆的某個人會從你手中收下它。>", progress = "我一直都需要候補舞者！", completion = "&lt;鼴鼠人用力地嗅聞圖騰。&gt;\n\n他聞起來有魚腥味！好極了！\n\n他在我的表演中會是很好的保鑣。我想要給他的名字是…小哨子！", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75768] = {title = "幸運小鴨", objective = "把羽毛之友給洛姆的辛楠。", description = "<你找到一個小玩具鴨。\n\n它讓你聯想到洛姆的燕子。或許辛楠會喜歡這個玩具？>", progress = "這是給我的嗎？", completion = "哇！謝謝你，&lt;name&gt;。\n\n在我成為新的首席飼燕者後，我一直在找一名助手！", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75769] = {title = "空白繪畫", objective = "把張開的帆布給洛姆的鼴鼠人。", description = "<洞穴的地板上躺著一幅被丟棄的畫作，上面充滿灰塵。\n\n或許洛姆的某個人會用得上這個東西？>", progress = "你怎麼知道我想用鼻子來創作氣味畫作的？", completion = "是全新的畫布！我可以用它來練習我的氣味畫作，真是太完美了。\n\n它現在聞起來完全…空白！謝謝你！", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75770] = {title = "一瓶冒泡藥劑", objective = "將冒泡藥劑拿去洛姆給蜜絲蒂。", description = "<你找到一瓶發光的藍色藥水，它的來源成謎。\n\n或許洛姆鍊金師會想要看看這個？>", progress = "嗯…我需要做些分析！", completion = "這真是有趣。\n\n我得去找全洛姆鼻子最靈敏的傢伙，才有辦法辨識這是什麼東西。\n\n謝謝你，&lt;name&gt;！", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75771] = {title = "薰香再現", objective = "將神秘薰香拿去洛姆給西卓斯。", description = "<你找到一些聞起來很熟悉的薰香，但你講不出確切名字。\n\n西卓斯一定會想聞聞看的。>", progress = "我的天啊！這個薰香的味道真強烈！", completion = "這聞起來不像鼴鼠人薰香！\n\n但這味道並不難聞，反而很香！\n\n你不介意的話，我可以靠近點聞嗎？", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75772] = {title = "酒瓶管理", objective = "找到皮革水壺的主人。", description = "<洞穴的架子上躺著一個小小的皮革水壺。\n\n應該有人想找回它。>", progress = "嗯，這不是我的，不過我願意收下它！", completion = "這個酒瓶的主人不可能是洛姆人。我以前從沒看過這樣的皮革。\n\n你不介意我問的話，我可以靠近點聞嗎？或許我可以加以利用這樣的技術！", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75773] = {title = "空白小書", objective = "將書籍帶回洛姆。", description = "<你找到一本書，裡面寫滿龍之記述，沒什麼別的東西。\n\n也許洛姆有人可以幫你解讀？>", progress = "你說讀什麼？傻瓜，它是空白的！", completion = "這裡面沒有寫字！它聞起來像空白的紙！\n\n要是沒有東西可以聞，我就讀不了它，地面人。\n\n不過算你貼心，帶了空白筆記本來給我。", rewards = "您會收到：\n\n交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75778] = {title = "野生保育區彎道 - 挑戰", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75780] = {title = "餘燼之流飛行賽道 - 挑戰", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75783] = {title = "頂尖之冠河川賽道 - 逆向挑戰版", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75805] = {title = "蒼藍高地奔馳賽道 - 挑戰", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75816] = {title = "文庫境域賽道 - 挑戰", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75833] = {title = "向貿易站報到", objective = "回到貿易站，從收藏箱領取商人的標幣。", description = "<你注意到遠處有個閃亮亮的箱子。你突然想起自己可以領取標幣，然後在T&W貿易站使用。>", progress = nil, completion = "希望你喜歡這個月的最新商品和奇珍異寶，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75834] = {title = "挖掘者馬爾黛", objective = "在寵物對戰中擊敗挖掘者馬爾黛", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75835] = {title = "你根本沒在練吧？", objective = "在寵物對戰中擊敗訓練師奧洛格", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75859] = {title = "支援協調者：嗅探尋寶", objective = "前往扎拉萊克洞窟並陪伴洛姆的邁里特在地下挖掘。繼續在巨龍群島各地協助沃卓肯協調者和他們的朋友吧。", description = "隨著我們在群島各處繼續努力，我們的盟友想再次尋求你的協助。許多沃卓肯的人都感到十分寬慰，因為他們知道你的努力幫我們塑造了更好的未來。\n\n現在，來說正事吧。\n\n我們在的扎拉萊克洞窟的鼴鼠人族盟友總是在尋找新鮮、刺激，或是味道強烈的東西。和他們一起在他們的地盤掘地，探索那些失落和被人遺忘的洞窟吧，看看你會找到什麼。\n\n我們會等你回來，<name>。", progress = nil, completion = "噢，哇，真是動聽的消息！協調者會很欣賞你的努力的。\n\n為了聊表謝意，請收下這份禮物。", rewards = "您會收到：\n\n沃卓肯寶藏龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記龍鱗遠征隊沃卓肯協調者莫魯克半人馬伊斯凱拉巨牙海民"}
MultiLanguageQuestData['tw'][75860] = {title = "支援協調者：遭攻擊的研究員", objective = "前往扎拉萊克洞窟並保護遭攻擊的研究員。繼續在巨龍群島各地協助沃卓肯協調者和他們的朋友吧。", description = "隨著我們在群島各處繼續努力，我們的盟友想再次尋求你的協助。許多沃卓肯的人都感到十分寬慰，因為他們知道你的努力幫我們塑造了更好的未來。\n\n現在，來說正事吧。\n\n龍鱗遠征隊的研究員正在探索扎拉萊克洞窟的深處。他們在徵求勇敢的冒險者，保護他們不受那個地區的諸多危險傷害。\n\n我們會等你回來，<name>。", progress = nil, completion = "噢，哇，真是動聽的消息！協調者會很欣賞你的努力的。\n\n為了聊表謝意，請收下這份禮物。", rewards = "您會收到：\n\n沃卓肯寶藏龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記龍鱗遠征隊沃卓肯協調者莫魯克半人馬伊斯凱拉巨牙海民"}
MultiLanguageQuestData['tw'][75861] = {title = "支援協調者：元素灌能營地", objective = "前往元素灌能營地並搜刮一個封住的貨箱。繼續在巨龍群島各地協助沃卓肯協調者和他們的朋友吧。", description = "南方有動靜傳來。\n\n在薩克利加拉登與菲拉卡之間，<name>，他們完成了一筆邪惡交易。他們的勢力正在打造…某些東西。\n\n我們不知道他們有何目的，但他們會毫不猶豫地將阻撓的勢力剷除殆盡。\n\n拜託了，<name>，我們需要像你這樣的勇士來阻止這些壞人，並奪取他們的資源。\n\n我們會等你回來，<name>。", progress = nil, completion = "我們可以從你這次的行動獲得許多情報。他們在做什麼？嗯，我們可以等等再來揭曉這個謎團。\n\n為了聊表謝意，請收下這份禮物。", rewards = "您會收到：\n\n\n\n等級 70–70龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記\n\n等級 60–70沃卓肯寶藏沃卓肯協調者莫魯克半人馬伊斯凱拉巨牙海民"}
MultiLanguageQuestData['tw'][75865] = {title = "文物竊賊", objective = "收集8片文物裂片。", description = "一群兇惡又長滿鱗片的地表人搬到了洛姆南邊的舊泰坦遺跡附近，開始在那裡大肆破壞。\n\n這樣很沒禮貌，不過他們確實挖出了各式各樣的遠古泰坦垃圾。而那些東西幾乎都有某種魔法。\n\n幫忙拿一些來，看看洛姆的製塵者托布茲能如何運用！", progress = nil, completion = "太棒了，這些聞起來很古老…這種刺鼻感就對了！", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][75867] = {title = "與過往的連結", objective = "觀看過往的事件。", description = "好了，校正完成了！我的也是，這樣我們就會看到一樣的畫面了。\n\n我們去望遠鏡那裡，看看會觀測到什麼吧。", progress = nil, completion = "他們真可惜，不過，這也許是我們的機會。嗯…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75868] = {title = "通往未來的窗口", objective = "搜索灼風鴉的巢穴並找回鏡片。", description = "那些鏡片是集科技與秘法於一體的奇妙物品。相信我們可以學到很多，或許還可以升級我自己的發明。\n\n不過，我們得先把它找出來。你是龍騎士，對吧？你可以飛上去找回鏡片嗎？\n\n鏡片很有可能在其中一個灼風鴉巢穴裡面。", progress = "<name>，你取回鏡片了嗎？", completion = "成功了！\n\n我就知道你是做這件事的最佳人選！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75874] = {title = "飛行時刻", objective = "尋找野獸大師卡拉泰克。", description = "贊達拉棲息著許多翼手龍。牠們可以陪你飛上天空。\n\n到祖達薩的達薩亞洛，拜訪野獸大師卡拉泰克。", progress = nil, completion = "很高興你來。這隻翼手龍很不受控，老是喊著要看看贊達拉以外的世界。我沒辦法訓練這樣的頑劣份子。\n\n你帶走吧。希望能為你的旅程帶來好運。", rewards = "您會收到：\n\n赤紅翼手龍韁繩"}
MultiLanguageQuestData['tw'][75877] = {title = "飛行時刻", objective = "尋找雷拉‧史戴弗。", description = "庫爾提拉斯棲息著許多獅鷲獸。牠們可以陪你飛上天空。\n\n到波拉勒斯的信風市場，拜訪雷拉‧史戴弗。", progress = nil, completion = "很高興你能來。當其他同伴都被送去訓練的時候，這隻小獅鷲獸卻被留了下來。沒想到我真能等到這一天，但牠已經準備好一飛沖天了。\n\n你願意跟牠一起遨遊世界嗎？希望能為你的旅程帶來好運。", rewards = "您會收到：\n\n港灣獅鷲獸"}
MultiLanguageQuestData['tw'][75885] = {title = "快速致富", objective = "讓洛姆的居民下訂一些龐佐的藥膏和葛利姆羅格分時度假券。", description = "地表人，我想問你一個問題。\n\n你想要跟我一樣，戴高貴的帽子嗎？擁有全鎮最棒的蝸牛？享受美好人生？\n\n如果答案是肯定的，那就準備好用龐佐的方法，來賺取你無法想像的豐富財富吧！\n\n我們可以一起發財！我已經發財了，不過你也可以成功！\n\n把我手上這些東西拿去，到鎮上去展示一下。只要你接到訂單，我就會分一定的利潤給你。", progress = nil, completion = "做得好！我還有額外的紅利要給你。\n\n現在你可以向我買更多東西，然後想賣多少就賣多少。只要你賣出東西，我們兩個就會更有錢。", rewards = "您會收到：\n\n交易磚塊龍石"}
MultiLanguageQuestData['tw'][75887] = {title = "菲拉卡的部隊", objective = "前往元素灌能營地。", description = "勇士，菲拉卡和他的洪荒使者盟友和加拉登族立下了一個黑暗的交易。我們聽到消息說，他們的部隊正在攻擊巨龍群島，要尋找資源來完成他們的某種邪惡計畫。\n\n拜託了，勇士，到其中一座元素灌能營地去，你在那裡可以找到我們的盟友，請你去協助他們。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75888] = {title = "元素灌能營地", objective = "搜刮一個元素灌能爐缸和一個元素灌能模具。", description = "菲拉卡跟獵龍者加拉登族做了交易！\n\n在菲拉卡的洪荒使者的庇護下，他們的鐵匠伊吉拉派來了她最能幹的工匠。他們正在收集材料，要打造…某種東西。\n\n想辦法去接觸他們的元素灌能爐缸和模具。你可以把找到的東西留著，不過我們得更了解他們現階段的計畫。部隊似乎需要特殊的結界才能接觸爐缸和模具。你可以從這點開始著手。", progress = nil, completion = "暗焰！他們在把暗焰灌注到每個原料和部件中！\n\n他們要製作什麼？他們絕不只是在為軍隊做裝備那麼簡單，一定是更危險的東西。\n\n很好，英雄。我們相信你不像那些畜生一樣，你一定會妥善利用這些材料的。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75890] = {title = "號角響起", objective = "前往暴風城的駐暴風城大使館附近，跟亞科納琳‧星影交談。\n\n已提供物品：\n", description = "<卷軸上寫滿漂亮的字跡。>\n\n<name>，\n\n你不認識我，但你的事蹟廣為流傳。\n\n以卡多雷族人守護者的身份，請你務必前往暴風城的大使館附近與我會面。泰蘭妲已經要求看守者開始行動，而瑪翼夫‧影歌本人指定要請你協助此事宜。\n\n- 亞科納琳‧星影", progress = nil, completion = "&lt;name&gt;，很榮幸見到你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75891] = {title = "遠古詛咒", objective = "前往費伍德森林跟瑪翼夫‧影歌會面。", description = "謝謝你這麼快就響應我的號召，<name>。\n\n費伍德森林最近又再次出現惡魔腐化的跡象。泰蘭妲派了一隊哨兵和她的一個女祭司去深入調查此事，他們之後卻下落不明。\n\n泰蘭妲於是要求守望者查明真相，而瑪翼夫則私下請求你的協助。\n\n我們必須快點前往費伍德森林，看看瑪翼夫有什麼發現。", progress = "願伊露恩能在這被遺忘的地方引導我們贏得勝利。", completion = "我會跟你說明我們該怎麼做，&lt;name&gt;。\n\n但我必須先讓我的好友安息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][75918] = {title = "火熱季節", objective = "前往位於雍亞拉平原的盧恩丹與珊蒂斯見面。", description = "無庸置疑，你已經看到了菲拉卡持續留下的毀滅慘況。\n\n在其他人與他正面對峙的同時，我跟我的部隊便成了綠龍軍團的耳目。雖然菲拉卡的行動看似雜亂無章，但他的策略仍有跡可循。\n\n我們獲得情報，他準備要在盧恩丹跟維蘭諾斯會面。這跟他近期的舉動相比有些反常，我們也必須找出他這麼做的理由。\n\n考慮到危險的程度，我們需要你的協助。到盧恩丹跟我會合吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75919] = {title = "破壞結界", objective = "摧毀4個結界火焰石。", description = "菲拉卡跟維蘭諾斯已經到了。我看到他們在盧恩丹東北邊陲的懸崖附近。直接在他們附近著陸會暴露我們的行蹤，因此我們不得不在這裡展開任務。\n\n然而，與懸崖連接的橋受到了火焰魔法的保護，我們無法突破屏障。\n\n菲拉卡的洪荒使者似乎在這附近設置了結界石來維持火焰燃燒。\n\n如果我們能摧毀結界石就能撲滅烈火了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75920] = {title = "火眼金睛", objective = "殺死8個燃燒的火語者或熾炎監督者。", description = "這裡的洪荒使者比我預想的還要多很多。菲拉卡平常不會帶人隨行，我懷疑洪荒使者是來保護他的。\n\n他們似乎要駐紮在這裡。但為什麼？\n\n也許洪荒化身對談的內容可以解開這個謎團。\n\n於此同時，我們來斬除守在這裡的洪荒使者吧。我們可不能冒著在過橋的時候還腹背受敵的風險。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75921] = {title = "穿過烈焰", objective = "在過橋接近菲拉卡與維蘭諾斯的同時收集4朵悶燃花朵。", description = "火焰德魯伊…\n\n<珊蒂斯眉頭深鎖。她閉上雙眼，看得出來她在忍住怒氣。>\n\n想到他們還存在，想到我們還有人會加入菲拉卡跟他的…\n\n<她突然打住、深深嘆了一口氣，然後繼續說道。>\n\n我們還有任務要完成。\n\n我們得跨過這座橋來接近洪荒化身，然後偷聽他們的對話。我會隱匿我們的行蹤，這樣就可以躲開元素生物，同時也能持續前進。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75922] = {title = "火辣的消息", objective = "偷聽菲拉卡和維蘭諾斯說了什麼。", description = "<珊蒂斯小聲地跟你說話。>\n\n看到前面了嗎？火焰德魯伊似乎抓到了守衛者…他是自然的保護者，也是我們神聖的象徵。如果他們的力量強大到足以…\n\n<珊蒂斯搖了搖頭，然後示意了附近一片茂盛的樹叢。>\n\n我們一起躲在那裡聽洪荒化身的對談，也許能打聽到德魯伊要對守衛者做些什麼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75923] = {title = "發出警報", objective = "到沃卓肯的守護巨龍之座向卓萊恩隊長回報。", description = "所以火焰德魯伊跟菲拉卡結盟來協助他入侵翡翠夢境。\n\n他們不費吹灰之力就可以把守衛者燃燒殆盡。菲拉卡一定有在暗中強化他們的力量，代價也許就是要協助他進到翡翠夢境中。\n\n我們得馬上派出人手，找出巨龍群島上的所有火焰德魯伊並阻止他們。\n\n快去沃卓肯警告卓萊恩隊長。她會派龍獸出動。\n\n我會去找麥琳瑟拉，然後處理後續事宜。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75932] = {title = "洛姆鼴鼠人", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75935] = {title = "時間指標", objective = "看看節奏願不願意協助沛奇作曲。", description = "喔，很好，一個冒險者。我想，你應該聽說過沛奇吧？那個作曲家？\n\n沒聽過？好吧，別告訴他這件事。\n\n我們原本到處旅行，尋找下一首歌曲的靈感，途中遇見一條名叫節奏的龍。沛奇現在深信他就是我們唯一的救星。\n\n沒錯，因為它的名字。沛奇就是這麼單純。\n\n不過，想當然，節奏太忙了，沒時間幫我們。你可以跟他談談嗎？看看我們能不能幫他分攤一些工作？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75936] = {title = "黏滑又滿足", objective = "將1隻蠕動的蟲子帶去洛姆給瑪莉‧雪莉。", description = "<是隻蟲。你知道誰可能會很喜歡蟲。>", progress = "<黏液從瑪莉‧雪莉身上滴下。>", completion = "&lt;瑪莉‧雪莉甩動她的觸角，同時把黏液滴在你身上。&gt;", rewards = "您會收到：\n\n\n\n任意等級交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][75937] = {title = "擇日不如撞日", objective = "到莫克特村的峭壁上方與安珀莎會合。", description = "安珀莎已經到了，就在你外出的時候。她和她的盟友正從峭壁上方勘察這個地區。\n\n我認為最好去跟她見個面。我們不希望她試圖獨自奪回禁忌之境。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n未利用的禁忌知識"}
MultiLanguageQuestData['tw'][75950] = {title = "正義楷模：哈德溫", objective = "幫助哈德溫打敗腐朽販爛爪。", description = "我們到這裡已經有一段時間了。我利用這段時間觀察了這一帶的豺狼人。\n\n豺狼人通常很惹人厭，但蕨皮谷的腐朽豺狼人…\n\n腐朽不只使他們的身體扭曲，連他們的心智也受到了影響。\n\n腐朽販爛爪是其中最可怕的一個。她在散播腐朽上一視同仁，不管是不聽話的族人、路過的旅人、動物、小孩…\n\n如果這世界還有正義，她早該被殺掉。", progress = nil, completion = "也許我太自不量力了…但有你幫忙，爛爪和她的爪牙為自己的罪行付出了代價。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75951] = {title = "秩序楷模：塔立斯", objective = "帶$o個巨牙海民文物給塔立斯。", description = "我知道崔瓦選這裡做為訓練場地的原因。這裡的腐化…混亂而失序。\n\n這跟提爾和其他泰坦正好相反！\n\n附近的豺狼人甚至對這些腐化雀躍不已。真噁心。\n\n他們搶走了曾經屬於自豪、高貴且重視秩序的巨牙海民的領地。\n\n巨牙海民提出要求，希望把過去他們棄置的文物還給他們。請幫助我打敗豺狼人、取回文物，讓伊斯凱拉的巨牙海民可以延續他們的儀式。", progress = "豺狼人無權擁有那些文物。它們是屬於巨牙海民的。", completion = "我很高興我們幫巨牙海民找回了那些文物。能在這片腐化的混亂中帶來一點秩序，感覺很不錯。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75952] = {title = "犧牲楷模：諾拉金", objective = "幫助諾拉金打敗一隻巨大軟泥怪。", description = "很多人都知道腐化可以透過空氣和地面傳播，但其實也能透過水源傳播。\n\n瘟疫會從住在河流和小溪裡的軟泥怪身上溢出，讓水變得有毒。但如果我們能涉水殺掉一隻大型軟泥怪，水裡的毒素就會慢慢消失。\n\n雖然過程中我也可能會中毒，但就算拼上我這條命，我也非得殺一隻不可。要淨化這地方才行。\n\n<name>，你會幫我嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75953] = {title = "憐憫楷模：薇勒內", objective = "擋下腐朽豺狼人，保護薇勒內。", description = "想到腐化對這裡的野生動植物造成的影響，我就感到十分心痛…\n\n我沒辦法拯救所有住在蕨皮谷周圍的生物，但我至少盡力救了一部分。\n\n西邊有個洞穴，裡面有一個最近剛遭到腐化的熊家族。我相信我可以殺出一條路，到那邊去治療牠們。你願意幫我嗎，<name>？", progress = nil, completion = "提爾對維酷人的憐憫啟發了我。我想他一定也對動物抱持憐憫，你不覺得嗎？他們跟你我一樣，都會受苦和感覺到疼痛…\n\n謝謝你幫我救了那些熊。即使是一點點憐憫，也很有意義。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75958] = {title = "鷹巢裂谷巡航賽道 - 挑戰", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75962] = {title = "火山口雲霄賽道 - 挑戰", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75963] = {title = "火山口雲霄賽道 - 逆向挑戰版", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][75966] = {title = "自行作曲", objective = "提升沛奇的自信。", description = "我保證他不是一直都這樣。但他…經常這樣。\n\n他通常需要幾天的時間，才能重新振作，不過我們現在沒有這種餘裕。他收到的作曲費可不夠花一輩子。\n\n也許你可以幫忙加快這個過程。你可以幫忙提升沛奇的自信嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75970] = {title = "跨越時光的追蹤", objective = "拯救時佚幼熊並送她回到正確的時間線。", description = "有個時光行者發現一隻不慎闖入我們時間線的幼熊。他還來不及抓住幼熊，她就嚇得跑走了！\n\n你可以去找那個可憐的小傢伙嗎？你必須先讓幼熊冷靜下來，她才會跟你走。\n\n帶她回來這裡，我會開啟時光傳送門，送她回家。", progress = nil, completion = "那隻小熊長大以後的樣子讓你很驚訝嗎？藉由這個例子就能知道，就算是小傢伙也可能變成大人物！", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][75971] = {title = "嘎吱作響的時空玩具", objective = "找到時空錯置的玩具，並將其送回正確的時間線。", description = "我們又偵測到時間異常。有我們無法理解其重要性的奇怪東西。\n\n必須把那個東西送回去，以免它對真正的時間線和我們所知的這個世界造成無法彌補的損害。\n\n回收那個東西後，就立刻回來這裡。我會開啟傳送門，讓你把它送回它的時間線。", progress = "我們所有人的命運，全都維繫到要把那個東西送回正確的時間線。", completion = "謝謝你，勇士。你再一次幫忙拯救了艾澤拉斯。一想到沒有你出手相助的後果，我就渾身發抖…", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][75985] = {title = "沉眠吧，戰士", objective = "協助卡沙爾埋葬沙基爾。", description = "沙基爾值得一個體面的告別式。\n\n我想要裝飾他的墳塚並發表一小段演說。我知道你的時間很寶貴，可是，在我舉行儀式的同時，可以請你拿鏟子去把他的骨灰埋起來嗎？", progress = nil, completion = "我很希望能夠付你酬勞，可是我沒有外交獎牌或傳說武器可以送給你，&lt;name&gt;。\n\n請你要知道，少了你…我是不可能自己承受今天這樣的打擊的。因為失去親友而空洞的心需要時間來填補。\n\n祝你平安，謝謝你。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][75987] = {title = "毛卜師", objective = "驅散8隻變形後的生物並沒收珍娜的群體變形魔杖。", description = "珍娜‧普勞德摩爾不知道從哪裡得到一根魔杖。當然，不是我們這條時間線的珍娜，而是她小時候的自己。那時的她年紀還太小，根本不該擁有這樣的力量。\n\n我們需要你去收拾她製造的混亂，並且沒收魔杖。", progress = "珍娜年紀太小，還無法承擔相應責任，不應該讓她接觸魔法。在情況變得更嚴重之前，相信你一定能阻止這一切。", completion = "謝謝你平息這次混亂。一想到她長大之後如果還是這麼…無法無天，就讓我渾身發抖。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][75988] = {title = "幸運爐石戰記卡牌", objective = "殺死魔法卡牌堆並取回安杜因的幸運爐石戰記卡牌。", description = "我原本正在跟我爸爸玩爐石戰記，結果不知為何出現在這裡。然後，有幾隻幼龍帶著我的幸運卡牌飛走，說要把它加進牠們的…卡牌龍捲風？\n\n然後所有的成年龍開始說我必須回家。但是，我還沒拿回幸運卡牌，絕不能離開！\n\n可以請你幫幫我嗎？我保證，只要你幫我拿回卡牌，我就會回家！", progress = "我感覺好多了。鮑伯給了我一點果汁。不過我還是不知道出了什麼事。\n\n這裡是什麼地方？我怎麼來到這裡的？", completion = "你真的拿回我的幸運卡牌了？謝謝、謝謝、謝謝，&lt;name&gt;！\n\n我會永遠記得你的恩情。我現在可以回家了。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][75989] = {title = "黑龍王子之亂", objective = "經由正確的時光傳送門，將每個怒西昂送回對應的時間線。", description = "五道不同的傳送門同一時間在這裡開啟，從每一道門出來的人都是同一個。\n\n現在，我們的旅店擠滿了怒西昂。年齡不同、人生閱歷不同，但都急著指責對方是始作俑者。\n\n快點讓他們回到正確的時間線，以免他們惹出太多麻煩。", progress = nil, completion = "幸好問題都解決了。要是我們的怒西昂也來湊一腳，不知道會如何！我不認為我的旅店應付得了六個怒西昂。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][75990] = {title = "苦情情侶", objective = "在維爾薩拉協助瑪法里恩獲得泰蘭妲的喜愛。", description = "我們發現一個發生在很久很久以前的時間擾動。有人幫助伊利丹迷惑了泰蘭妲，導致我們被燃燒軍團全滅！\n\n瑪法里恩煩惱到睡不著覺，完全不知道如何贏回她的心。\n\n我們必須在時間線毀於一旦之前，助他一臂之力。", progress = "儘管心碎可能會令人相當痛苦，但有時候卻也是成長不可或缺的一環。就算是不怎麼好相處的人…也不例外。", completion = "我們也很想讓伊利丹能與泰蘭妲永遠快樂的在一起，至少能共渡多一點幸福時光。我一直覺得那兩個人一起的時候很可愛！\n\n但我們都有必須扮演的角色，這樣才能確保歷史順利運行！", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][75991] = {title = "可能的過去", objective = "協助另一個你擊敗共同的敵人。", description = "不久前，有個神秘的陌生人經由其中一道時光傳送門出現在這裡。\n\n他說需要你幫忙解決一個即將到來的威脅。有某種隱形裝置，不過一旦停用它之後，你看到的景象可能會讓你非常傻眼。\n\n老實說，你對這個陌生人大概不會有什麼好感。", progress = nil, completion = "喔，很好。你們毫髮無傷地回來了。很高興看到你們能夠暫時忽視彼此間的差異。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
