MultiLanguageQuestData['tw'][75998] = {title = "酥酥脆脆", objective = "將酥脆甲蟲帶到洛姆給梵杜爾。", description = "<你在洛姆的獸欄附近看過這種甲蟲。或許獸欄管理員會有更多牠們的資訊。>", progress = "是櫻桃甲蟲！", completion = "櫻桃甲蟲是蓋瑞最喜歡的點心，很可愛吧？\n\n&lt;蓋瑞搖了搖他的觸角。&gt;\n\n如果你又找到這種蟲的話，記得再帶過來！", rewards = "您會收到：\n\n\n\n任意等級交易磚塊交易礫石"}
MultiLanguageQuestData['tw'][76004] = {title = "深深的傷痕", objective = "將1支深岩剝石怪之爪帶去洛姆給窯燒大師克魯布斯。", description = "<你找到一支棄置的深岩剝石怪爪子。你看過鼴鼠人把這拿來當武器。>", progress = "小心，這些很尖銳。", completion = "這些利爪的尺寸非常適合讓我們當武器用，可惜它們很難找。\n\n如果你又找到更多爪子，歡迎你再拿來給我！", rewards = "您會收到：\n\n\n\n任意等級交易磚塊交易礫石"}
