MultiLanguageQuestData['tw'][76025] = {title = "飛龍暗焰紋章", objective = "在洛姆和米穆普談話。", description = "[Well hello there, $p! \n\nI heard you've been helping us out. How about you meet me in Loamm, so we get you a reward? \n\nKeep up the good work, \n\nMimuup]", progress = nil, completion = "我們不會忘記你為我們做的事！", rewards = "您會收到：\n\n小型洛姆補給包"}
MultiLanguageQuestData['tw'][76026] = {title = "勘查高塔", objective = "與蘿思卡談話來開始挖掘，再從高塔周遭挖出文物。", description = "看看這堆石頭的排列方式！沒有比這更棒的勘查了。\n\n這座高塔在這裡經歷了無數時光，黑龍軍團用它做了一些極為邪惡的事，但那不是我們來此地的原因。巨龍離開後，鼴鼠人盜匪佔據了這片廢墟，拚命把此地洗劫一空。但他們同時也四處留下垃圾。\n\n當我們開始挖掘後，說不定能透過那些垃圾多了解鼴鼠人一點！", progress = nil, completion = "&lt;蘿思卡豪邁地大笑了幾聲。&gt;\n\n噢齁齁，這東西的背後一定有個很瘋狂的故事！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76027] = {title = "振翅與尖嘯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76028] = {title = "巨龍群島補給品", objective = "在洛姆和米穆普談話。", description = "你好啊，$p！\n\n我聽說你一直以來都在幫我們！我們想給你一些獎賞，那麼就到洛姆來找我吧？\n\n繼續加油吧。\n\n米穆普您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n大型洛姆補給包"}
MultiLanguageQuestData['tw'][76029] = {title = "巨龍群島補給品", objective = "在洛姆和米穆普談話。", description = "你好啊，$p！\n\n我聽說你一直以來都在幫我們。我們想給你一些獎賞，那麼就到洛姆來找我吧？\n\n繼續加油吧。\n\n米穆普您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n滿溢洛姆補給包"}
MultiLanguageQuestData['tw'][76030] = {title = "空中盤旋", objective = "和洛姆的哈蘿威‧瑪爾談話。", description = "唉呀，你好啊！\n\n聽說你一直都在幫助我們，因此我們有個小小東西想送給你。到洛姆來找我，我再把東西交給你！\n\n祝你安好，\n哈蘿威‧瑪爾", progress = nil, completion = "能有你在是我們的福氣！", rewards = "您能選擇下列奬勵中的一個：\n\n盤旋滑龍：大尖刺鼻盤旋滑龍：多毛尾巴盤旋滑龍：多毛喉部"}
MultiLanguageQuestData['tw'][76032] = {title = "藏在垃圾堆之中", objective = "小心仔細地挖出汙損的巨龍雕像。", description = "<這尊巨龍雕像跟當地出土的其他雕像十分相似，但卻畫滿了塗鴉。\n\n瞪大的眼睛、波浪線、怪鬍子，還有其他低俗的塗鴉畫滿了這塊原本十分壯觀的石頭。雖然這些塗鴉看起來有些年代、也很斑駁，但年代卻不如這尊雕像久遠。\n\n蘿思卡絕對會想看看！>", progress = nil, completion = "你知道嗎，這些鼴鼠人盜匪蠻有幽默感的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76067] = {title = "簽名、封印、自行遞送", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n紐茲"}
MultiLanguageQuestData['tw'][76072] = {title = "血色之影", objective = "在血色修道院的幽靈當中尋找線索。", description = "<name>，我需要你幫忙。我還以為我成功取得某種表面的平靜，即便我的罪孽尚未獲得寬恕，但是至少可以和心愛家人的靈魂團聚。然而…我妻子的靈魂不見了，像是從未存在過一樣。\n\n在萬鬼節時，在修道院作祟的幽靈都會紛紛從陰影中現身。他們被困在過去，四處遊蕩，一再重現他們的夢魘。\n\n幸運的話，我們或許能從他們當中得到答案，知道她出了什麼事。", progress = nil, completion = "&lt;湯瑪斯爵士陷入沉思，你的到來驚動了他。&gt;\n\n&lt;name&gt;！很抱歉，我突然跑掉，有些回憶…我永遠不想再次想起。\n\n這些殘酷的幽靈似乎很清楚如何在傷口上灑鹽。\n\n來吧，我知道接下來要去哪裡找線索。", rewards = "您會收到：\n\n搗蛋糖果龍石"}
MultiLanguageQuestData['tw'][76073] = {title = "可不是鬧著玩的", objective = "調查修道院的噴泉。", description = "這條小路的盡頭是一座噴泉露臺。在天譴軍團蹂躪羅德隆之前，我會帶蘇珊娜來這裡。我記得當時我對任何事都充滿信心；對自己、對聖光…對她，還有我的孩子。\n\n我在想，我的前途到底是什麼時候開始變得黯淡無光。\n\n如果這裡有幽靈可以幫我們，一定是在噴泉附近。", progress = nil, completion = "&lt;蘇珊娜沉默了一陣子。&gt;\n\n不久前，我的丈夫湯瑪斯求我前往卡林多，躲避天譴軍團。當晚，他並未上床睡覺，而是保持警覺，保護我們。他聲音中的恐懼嚇到我了，他的眼裡充滿絕望…\n\n&lt;蘇珊娜輕輕在她的掌心劃了一條線，然後用力握拳。&gt;\n\n我不會拋棄他。這次不會，永遠不會。", rewards = "您會收到：\n\n搗蛋糖果龍石"}
MultiLanguageQuestData['tw'][76074] = {title = "無頭騎士回來了", objective = "使用隊伍搜尋器進入「無頭騎士」地城，並擊敗無頭騎士。", description = "湯瑪斯撤退到血色修道院了。他跟這個地方有很深的連繫，就算是腐化的他也不例外。\n\n你的名字是<name>，對吧？我的丈夫相信你能幫助他，所以我也深信不疑。我打算追上去，但我一個人救不了他。\n\n你要一起來嗎？", progress = nil, completion = "我再次從瘋狂中獲得救贖。我該如何感謝你才好？", rewards = "您會收到：\n\n搗蛋糖果龍石"}
MultiLanguageQuestData['tw'][76075] = {title = "鬼魅訊息", objective = "到提里斯法林地的血色修道院附近尋找湯瑪斯‧托姆森。\n\n已提供物品：\n", description = "不好意思，是<name>嗎？無論在生者或死者的世界，你最近都很有名。\n\n我有一本名叫「湯瑪斯‧托姆森的聖典」的書。多年來，它一直放在我的書房，提醒我記住那段不該被遺忘的歲月。有一天，它從書架上掉了下來，自行打開！翻開的頁面上有個名字。\n\n那是你的名字，<name>。\n\n如果湯瑪斯的靈魂正在找你，那麼我覺得你應該帶著這本書。說不定他正在血色修道院等著你？", progress = nil, completion = "終於啊，&lt;name&gt;，你找到我了，我就知道你會來。\n\n我又再次需要幫助，像你這麼厲害的冒險者絕對是首選。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76076] = {title = "小東西", objective = "將冰岩放回羅德隆。", description = "幾隻善良的幼龍從歷史中拿了一些小東西。小東西有時候會帶來很大的影響。在幼龍做雙倍家事的同時，我需要有人把這些石頭還回歷史上正確的位置。\n\n很誇張對吧？不過是石頭耶？！一樣得歸位。", progress = nil, completion = "謝謝你幫忙，&lt;name&gt;。維護時間之道的秩序不是一件一直都很有趣或光鮮亮麗的工作，有時候你得做些不想做的事情，不過時間軸還是得繼續前進！", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
