MultiLanguageQuestData['tw'][76122] = {title = "戰鬥本身就是獎勵", objective = "完成5個英雄難度的《巨龍崛起》地城。", description = "啊，<name>。見到你真好。\n\n多虧你的努力，我跟瑟爾倫學到了很多事。但在四周一直都會有東西想打破巨龍群島上的自然法則。\n\n我想請你召集你的夥伴，並持續阻止那些想傷害我們以及群島生活的事物。", progress = nil, completion = "非常感謝你，&lt;name&gt;！\n\n你持續鼓舞了我們所有人。", rewards = "您能選擇下列奬勵中的一個：\n\n英雄難度地城鑽研家的戰利品箱子英雄難度地城鑽研家的戰利品紋章\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][76140] = {title = "恆龍黎明", objective = "到薩爪祖斯的紀元邊境找諾茲多姆。", description = "儘管我的視力有點模糊，但我絕對沒看錯。黑暗勢力聯合起來對抗青銅龍軍團。我不知道自己是否能渡過這次難關…\n\n<name>，請到紀元邊境見我，到時候我們再來仔細談談這次的威脅。若是要找個信任的人協助捍衛我們的未來，那非你莫屬。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76141] = {title = "沙之校正", objective = "在薩爪祖斯的時光沙地各處放置時光沙漏。", description = "時間之道，是嗎？它們出現超級嚴重的錯位現象。我們青銅龍有多討厭這個現象！所以我們必須用這些時光沙漏來校正時間，只要在紀元邊境各處放置沙漏就行了。\n\n你知道我對幫手一向來者不拒！我會在附近放置另一個沙漏。等你全部搞定後，就到那裡找我。", progress = nil, completion = "&lt;克羅米聽你解釋你的行動，不禁睜大雙眼。&gt;\n\n我？來自未來？怎麼會，她是我最信任的三個人之一！\n\n這完全說不通。若要幫助諾茲多姆，她為什麼會要你扭曲時間之道？這似乎只會讓他覺得頭痛。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76142] = {title = "預支時間", objective = "在時光沙地殺死時佚生物，收集生物身上的時佚精華。", description = "我需要你幫我拿些時佚精華來。這附近的生物都充滿了這類物質。\n\n消滅生物之後用這個時光吸取器收集精華。我們會善用精華來進行下一步！\n\n沒錯，這會是一個按部就班的過程。你也知道時間一旦失控，情況就會變得超級瘋狂！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76143] = {title = "克羅…咪？", objective = "將不同時間線的克羅米困在時間靜滯中。", description = "你的「時間校正」行動的結果，似乎就是召喚了…我？好吧，是另一條時間線的我。\n\n我從沒看過這麼多克羅米齊聚一堂！儘管她們外表都很可愛，但是她們正對這裡的時間之道造成浩劫。\n\n我們必須困住她們，同步她們的時間指標。到時候，她們或許就能告訴我們出了什麼事！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76144] = {title = "米羅克搞破壞", objective = "調查假未來的克羅米。", description = "我們必須搞清楚這個「未來的克羅米」到底有什麼企圖。那條龍在哪裡？她必須把事情說個清楚！\n\n我們先去檢查她的其中一個時光沙漏，也許能得到什麼線索。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76145] = {title = "那個克羅米是誰？", objective = "逮捕並審問米羅克。", description = "米羅克不只把自己傳送走，還順便帶走了所有其他的克羅米！這讓我有種不好的預感…\n\n我們必須追上去並逮捕她。然後審問她！我要知道她有什麼企圖。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76146] = {title = "恆龍黎明：時空領主戴歐司", objective = "擊敗時空領主戴歐司。", description = "時空領主戴歐司一定是這一切的幕後黑手。身為恆龍的首領，他一定主導了這次入侵。我敢說米羅克也是在替他做事。\n\n我們去青銅神殿吧！我們必須阻止戴歐司，別讓他毀了真正的時間線。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n靜滯之沙克羅米認證的整齊好時光龍石"}
MultiLanguageQuestData['tw'][76147] = {title = "倒轉與調解", objective = "到薩爪祖斯的時光合流，將時間聖物交給諾茲多姆。", description = "<你感覺到，與時空領主戴歐司的戰鬥結束後取得的聖物散發出強大的時間能量。看起來上面刻著兩個指向左側的箭頭。你應該給諾茲多姆看看。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n巨龍暗焰紋章青銅文庫石龍石幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][76155] = {title = "羊群中的狼", objective = "在暗月島協助歐曼填滿暗影女士的靈魂石。", description = "謝謝你對我這麼好。\n\n但我不想對我們的新…導師表現出不知感恩的樣子。幫我一個忙…找其他的方法來填滿暗影女士的靈魂石。雖然我們不應該測試我們的老師，可是她還沒贏得我的信任。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76158] = {title = "時空絲縷", objective = "在巨龍群島上的團隊遊戲內容當中強化時空絲縷。\n\n時空絲縷只會在團隊中且靠近一名遠古回憶持有者時受到強化。", description = "時空絲縷以細緻的輕柔絲線現形，而且在靠近一名喚能師的遠古回憶時似乎會變得更強韌。\n\n協助喚能師尋找時光殘跡似乎強化了這些絲網，讓它們能與遠古回憶緊密結合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n強化時空絲縷"}
MultiLanguageQuestData['tw'][76159] = {title = "向貿易站報到", objective = "回到貿易站，從收藏箱領取商人的標幣。", description = "<你注意到遠處有個閃亮亮的箱子。你突然想起自己可以領取標幣，然後在T&W貿易站使用。>", progress = nil, completion = "希望你喜歡這個月的最新商品和奇珍異寶，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76162] = {title = "消失的魔精", objective = "找回沃金消失的魔精。", description = "我剛剛在練習魔法，突然就發現自己出現在這。接著我意識到一件事，我的魔精跑掉了！\n\n它不可能跑太遠，你願意去找它嗎？我好像需要喝一杯。", progress = "你找到我的魔精了嗎？", completion = "謝謝你幫忙。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][76163] = {title = "更輕的魔影", objective = "在藏寶海灣和歐曼會面", description = "親愛的，$p：\n\n你好，在我們遇到貝恩霍勒領主後，我花了一點時間整理我的思緒。\n\n我也去找了其他在他的黑暗計畫中倖存的人，並把他們召集到藏寶海灣，我們才能一起決定接下來的計畫。\n\n我們希望你能來這裡和我們會合。\n\n最黑暗的問候，\n\n魔歐曼您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n貝恩霍勒的靈魂石雕紋"}
MultiLanguageQuestData['tw'][76169] = {title = "暗中微光", objective = "找到『壞脾氣』佩頓‧伯恩科，取回8瓶無懼藥水。", description = "天啊！壞脾氣又逃跑了。他被分派到這個崗位，卻從沒來報到過。\n\n我聽見附近的洞穴傳來他的嘶吼聲，他一定打算躲在那裡面。\n\n帶著我的火炬，進入冷影洞穴。沿著壞脾氣偷走的無懼藥水瓶子找到他。他想擅離職守的話請自便，但我不會讓他拿走那些藥水！", progress = "你找到『壞脾氣』佩頓‧伯恩科，還有他帶走的無懼藥水了嗎？", completion = "我不期待壞脾氣能鼓起勇氣回來。不過，你至少有拿回藥水了。\n\n讓我們敬一杯，祝他在那個洞穴裡一切順利。", rewards = "您會收到：\n\n無懼藥水燈火者補給包共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][76171] = {title = "走上提爾之道", objective = "把裝備分給提爾的衛士。", description = "在他們展開最終訓練的試煉之前，依照傳統，新兵必須先領取各自的提爾的衛士裝備。\n\n這通常是由提爾的衛士位階最高的長官來發放，不過…如果能改由你來發放最終試煉的外袍和盾牌給他們，我會倍感榮幸。", progress = nil, completion = "謝謝你，&lt;name&gt;。現在我們的新兵應該準備好接受最終的試煉了。\n\n去找他們吧。要完成任務，他們一定還需要你的指導。", rewards = "您會收到：\n\n提爾的衛士壁壘龍石"}
MultiLanguageQuestData['tw'][76176] = {title = "開始起步", objective = "前往提爾堡跟克羅米和伊特努斯碰面。", description = "現在，我們正式開始追蹤圓盤吧。真不敢相信，經過了數千年，我們現在居然只差一點就能讓提爾復活，而且我還參與其中。\n\n我們應該到裡面去找克羅米和伊特努斯。他們會告訴我們接下來該怎麼做。", progress = nil, completion = "你回來得正是時候，&lt;name&gt;！我們已經決定好提爾的衛士必須把信標放在哪些地方了。去找伊特努斯，等你準備好了，我們就開始。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76194] = {title = "恐怖惡兆", objective = "與亞科納琳‧星影談話，了解關於加德納爾的事情。", description = "泰蘭妲懷疑有人在費伍德森林從事某種邪惡的勾當…真的被她說中了。\n\n為了奪回曾屬於我們的土地，她派了女祭司凱萊莎去那裡的月井，淨化在那裡到處肆虐的惡魔腐化…\n\n現在我們失去了一個姊妹，而月井的腐化依舊。我們不能坐視不管。我們會完成凱萊莎的任務，治癒月井。\n\n亞科納琳跟這個地方有很深的羈絆。我會請她告訴你我們來這裡的原因。", progress = nil, completion = "&lt;name&gt;，該展現實力了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76195] = {title = "反制腐化", objective = "在6具受魔化之觸影響的薩特屍體上使用魔法使秘典。", description = "你願意幫忙，我真的不知道該怎麼感謝你才好，<name>。納琳告訴我這個任務時，我就知道我得來這裡幫她才行。\n\n果然如我所想的，這裡需要我的技術。這裡有邪惡和腐化的魔法，必須要被控制住。\n\n拜託你，拿著這本書，在讓加德納爾附近的所有薩特都安息後，唸出咒語。\n\n不能再讓加德納爾成為一個充滿死亡和腐化的地方。", progress = nil, completion = "這些薩特…是哨兵變成的？我一定會讓做出這種事的傢伙付出代價！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76196] = {title = "慈悲或慘劇", objective = "在費伍德森林殺死佔據加德納爾的邪教徒。", description = "這個地方…過去對我的家人非常重要。因此，我才會同意前來，也是萊杉德想要一起來的原因。\n\n<亞科納琳看了萊杉德一眼，然後再度將目光轉向你。>\n\n即使泰達希爾已經毀滅，我的弟弟仍盡其所能幫助其他人。這點跟你很像，<name>。\n\n來吧。我們必須消除這些渴望力量的蠢貨帶來的威脅。我想你正是最適合這件工作的卡多雷。", progress = nil, completion = "&lt;name&gt;，做得漂亮。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76197] = {title = "一窺恐懼", objective = "擊敗教徒奈瑟思。", description = "我們會聽你的命令一起出擊，<name>。\n\n<瑪翼夫活動一下肩膀。>\n\n這個惡魔生前看到的最後一幕會是我們的刀刃。", progress = nil, completion = "我們的哨兵…被扭曲了！這無法容忍。我們一定要拿下主導這場侵略行動的人，而我會讓他賠上性命！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76203] = {title = "潛入暗影", objective = "跟瑪翼夫‧影歌一起穿越暗影堡，把擋路的敵人都解決掉。", description = "你削弱了他們的力量，並淨化了他們的屍體。你做得很好。\n\n<瑪翼夫轉身朝通往暗影堡的小徑望去。>\n\n來吧，<name>。我們必須找到潛伏在下面的東西，讓一切劃下句點。", progress = nil, completion = "我們不再需要出其不意了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76205] = {title = "恢復平衡", objective = "殺死暗影堡各處的敵人。", description = "低調行事的時機已經過去了。赫爾努拉斯領主已經現身…直到殺掉他之前我絕不罷休。\n\n<瑪翼夫咬緊牙關。>\n\n<name>，做好準備。我們會一起讓這些惡魔見識，他們該懼怕卡多雷的原因。", progress = nil, completion = "我從這裡都能聽見他們的慘叫聲，&lt;name&gt;。做得很好。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76206] = {title = "麻煩源頭", objective = "在暗影堡深處干擾$o個通往扭曲虛空的傳送門。", description = "我真不敢相信納琳到底經歷了多少苦難。我們的歷史和文化被曲解…甚至我的家人…\n\n<萊杉德望向他的姊姊。>\n\n這些惡魔是從某個地方來的。我確定源頭就在我們獸穴的深處。你我聯手可以阻止他們。\n\n<name>，我不會再讓這個地方糾纏她了。", progress = nil, completion = "萊杉德，他…意志堅定，這是無庸置疑的。\n\n也很勇敢。\n\n&lt;name&gt;，謝謝你。現在…該面對這一切的幕後主使者。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76207] = {title = "看守者之怒", objective = "在萊杉德干擾赫爾努拉斯領主的儀式時保護他。", description = "赫爾努拉斯領主的傲慢給了我機會，讓我能仔細研究他的計畫。我似乎找到了一個能趁虛進攻的弱點。\n\n<亞科納琳望向她的弟弟。>\n\n對萊杉德而言，這恐怕難以負荷。但我知道他一定會全力以赴。或許…或許我的觀感是錯的。\n\n是時候讓我的…我們的惡魔安息了。", progress = nil, completion = "&lt;name&gt;，別擔心我了。有我姊姊操心就夠了。\n\n你看那月井，好美啊…", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76212] = {title = "保衛者的印記", objective = "旁觀萊杉德的紋面儀式。", description = "<name>，傳統不該成為我們的絆腳石，而是要讓我們走向未來。\n\n<瑪翼夫望向萊杉德，然後回頭望著你。>\n\n我的觀感也曾使我裹足不前，但是夠了。我厭倦了看到族人之間彼此分裂，而非將精力放在讓彼此、讓世界更美好上。\n\n是時候讓萊杉德擁有他的印記了。卡多雷對改變並不陌生。傳統應該要隨著我們的生活演變，不該成為束縛我們的框架。", progress = nil, completion = "&lt;name&gt;，真不敢相信！真不敢相信！\n\n怎麼會…為什麼…？我永遠不會忘記今天的。謝謝你。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76213] = {title = "女神的榮耀", objective = "向瑪翼夫‧影歌學習「Ama'shan」的意義。", description = "<name>，今天是個值得慶祝的日子，也是一個全新的開始。\n\n亞科納琳和萊杉德提醒了我，卡多雷對改變本就習以為常。我時常忘了自己離開了這麼久，我不在的這段期間同胞們已經有了很大的進展。\n\n<瑪翼夫望向天空。>\n\n在萊杉德慶祝的同時，你的付出也該獲得認同。來吧，<name>。", progress = nil, completion = "Ama'shan &lt;name&gt;，昂首闊步。\n\n願你的英勇之舉繼續啟發卡多雷。", rewards = "您會收到：\n\n守舊者卡多雷刀刃套裝：卡多雷保衛者飾物龍石"}
MultiLanguageQuestData['tw'][76214] = {title = "拍美照", objective = "專心聽從攝影師的指示。", description = "<class>，時尚大考驗讓我們有機會煥然一新。\n\n相機會確保我們看起來顏值爆表。\n\n把注意力放在我和相機上，照我的指示行動，我一定會把你拍得很好看！", progress = "把注意力放在我身上，照我的指示行動。\n\n我一定會把你拍得很上相。", completion = "&lt;name&gt;，相機不會騙人。\n\n你真的是很時尚的&lt;class&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76217] = {title = "活歷史", objective = "啟動尼羅賓的儀器，開始分析奇妙的半龍人酒杯。", description = "我叫尼羅賓。記住這個名字，畢竟我可是秘法手稿學領域的天才！不得不說真是個響亮的頭銜…雖然是我自己封的！\n\n為了更深入研究歷史，我花了數不清的時間結合藍龍跟青銅龍的魔法。今天，你會和我一同見證我的研究成果！\n\n我們就先來用我的儀器分析這個從禁忌之境出土，保存狀況極佳的酒杯吧。", progress = "你可能會嚇一跳。\n\n試著從你的身體深處汲取力量。畢竟這件事只能靠你自己，我也愛莫能助。", completion = "出乎意料…\n\n不過！像我這種生來就是要冒險探索的人，「出乎意料」是常有的事！\n\n前進！為了學術！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76241] = {title = "實驗室松鼠夥伴", objective = "到禁忌之境的失落圖書室與瑞斯會合來繼續你的研究。", description = "我終於讓歷史重現了！我成功了！\n\n現在，我們要好好利用你的特長，我需要你去到外面不會嚇得要死的能力。\n\n把魔法引導到我們的新朋友身上，我會把牠傳送到與文物相連的共振能量最集中的位置。你去那裡跟牠會合，然後等待我進一步的指示。\n\n別怕！我的魔法或許會混淆你的認知，但我的智慧絕對能帶我們通往真相！", progress = nil, completion = "&lt;秘法松鼠的嘴發出了尼羅賓的聒噪聲音。&gt;\n\n&lt;name&gt;嗎？聽得到我說話嗎？是我，尼羅賓啦！那個有極輕微懼曠症的手稿學天才啦！\n\n相信你已經準備好要利用這個小生物來發掘半龍人文明失落已久的祕密了吧！不然你為什麼會和松鼠說話呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76242] = {title = "值得發佈的研究論文", objective = "在失落圖書室與瑞斯一起處理線索。", description = "瑞斯很渴望獲得線索。過去歷史的線索！\n\n更確切地說，我們會利用我的特殊魔法來揭露與分析跟這件文物同調的能量。\n\n你要引導瑞斯前往這些「線索」，而我就會把他當作遠端導體來吸收這些能量。\n\n當這個小生物不能再容納更多能量後，我會把牠傳回這裡，然後把冷冰冰的資料提取出來。\n\n<瑞斯向你眨了眨眼。真怪…>", progress = "你一定會認為，我在禁忌之境待了幾千年，應該很熟悉那時的歷史才對。\n\n但是，沒有唷！因為我大多時間都待在實驗室裡，對外頭的世界沒什麼接觸。", completion = "我十分吃驚但也有點敬佩，因為你在外頭護送這隻藍色半透明飛天松鼠時，看起來一點都不尷尬。很值得誇獎！做得好！\n\n現在收下這個獎勵吧。如果你覺得不夠的話，那請你寫信給學院，幫我抱怨少得可憐的年薪。\n\n至於之後，我隨時都可能請你替我展開一場手稿考察之旅！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76244] = {title = "王子危機", objective = "擊敗時佚豺狼人，並找回失蹤的萊恩‧烏瑞恩。", description = "我剛剛還在和一群膽敢威脅我王子的兇猛豺狼人戰鬥，結果出現一道閃光。一瞬間，我就來到這個奇怪的地方，王子也不見了！一定是那個歹毒的藍皮族母做的好事。\n\n拜託，去找烏瑞恩王子，順便給那些豺狼人好看！", progress = nil, completion = "謝謝你，王子平安回來了。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][76246] = {title = "曼納斯頓的奧秘", objective = "在達拉然找米歐浩斯‧曼納斯頓談話。", description = "曼納斯頓這對夫妻…很特別。\n\n雖然他們的羅曼史有點勁爆，但起初點燃愛火的火花卻非常微小。奇怪的是，米歐浩斯反常地出現了自信危機。\n\n我們需要你為他們搭起鵲橋。願泰坦對我們慈悲…", progress = nil, completion = "你讓事情的發展維持不變，還促成兩個人的戀情。\n\n這樣很好。我們應該專注在正面的事物上。而不是他們未來會造成的災難。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][76247] = {title = "讓家族之火持續燃燒", objective = "收集5個西爾海姆殘渣補給，並用來強化西爾海姆鑰炎。", description = "鑰炎火盆遍布郊外，將黑暗阻擋在外，保障我們族人的安全。隨著燃燒所需的燃料「輻光殘骸」越來越難找到，許多火盆紛紛熄滅。\n\n我們一直努力確保火盆永不熄滅，但有你幫忙會更好。\n\n請從我們的補給品中收集殘骸，使用它們讓我們家族的鑰炎更加旺盛。", progress = "你讓我們的鑰炎更加旺盛了嗎？", completion = "火焰的暖意給了我們奪回這些土地的希望。請帶著一些多出來的殘骸，幫忙點燃附近的其他鑰炎。", rewards = nil}
MultiLanguageQuestData['tw'][76251] = {title = "禽鴨獸", objective = "在蒼藍高地的冬毛谷殺死10隻禽鴨獸。", description = "我認為我的時光轉移是由南方的可怕生物造成。\n\n就算是現在，我還是能聽到那可怕的吵鬧聲。牠們把我從原本的時空拉到這裡，一定只是為了嘲諷我。\n\n殺死牠們，為了我，也為了這個世界上所有好人的安全。", progress = "怎麼？你還在等什麼？想想你能從那些怪物手中拯救多少孩子。\n\n雖然我還沒看到半個，但不怕一萬，只怕萬一。", completion = "你為這個世界帶來了貢獻。\n\n&lt;納薩諾斯打顫。&gt;\n\n不管是誰都不該目睹這樣的生物。我現在還是能聽到那些呱呱聲…", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][76257] = {title = "黑暗院長的天譴石", objective = "找到對黑暗院長的天譴石有興趣的人。", description = "<你手中的天譴石跟這個回憶裡其他的東西一樣真實。它躺在你手中，讓你打從骨子裡感到寒冷。\n\n雖然它是過去的聖物，銀色黎明還是應該知道它的存在。\n\n用伊娃的日誌執行的儀式可能存在你們都沒有料到的嚴重後果。>", progress = nil, completion = "天譴石？我不懂，你怎麼會找到這東西？我們在這裡跟北裂境做了這麼多…\n\n不，不重要，&lt;name&gt;，交給我，我一定會銷毀它。這一定是最後幾顆之一，一定是的。\n\n如果你再找到類似的東西，就帶來給我。為了我們全部人好，我希望這是我們最後一次討論這個東西。", rewards = "您會學到：\n\n天譴石\n\n您還會收到：\n\n銀色黎明勇氣勳章"}
MultiLanguageQuestData['tw'][76258] = {title = "讓時間之火淨化一切！", objective = "取回時光熔爐核心。", description = "那個超大熔渣元素拿走了我熔爐的核心！沒有核心，時光熔爐就只是一個普通的熔爐。對時光鐵匠毫無用處可言！\n\n就算我們有海貝曼恩，我也沒辦法修復它。\n\n這等力量絕不能落入那個…那個熔火怪物手中！\n\n其他元素生物都湧向那些高塔了。我用我一半的鬍子打賭，那個大傢伙一定也在那附近。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n藍藍露龍石"}
MultiLanguageQuestData['tw'][76263] = {title = "驚懼城塞：納克薩瑪斯", objective = "東瘟疫之地的大法師安琪拉‧朵桑托斯想要5個秘法水晶、6個大塊魔光裂片、1個正義寶珠和60枚金幣。你也必須在銀色黎明取得尊敬聲望。", description = "很久以前，納克薩瑪斯的魔法結界阻礙了我們，使我們無法攻擊科爾蘇加德的部隊。雖然我當時成功隱蔽了我們的軍隊，我也學會了驅散結界的方法，以免這個需求再次產生。\n\n我必須對你的故事表達懷疑。不過，要是你決心要進行這個調查，我可以對你的徽記施法，讓你可以親自突破這些屏障。當然，是有代價的。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n強化委任徽章"}
MultiLanguageQuestData['tw'][76264] = {title = "驚懼城塞：納克薩瑪斯", objective = "東瘟疫之地的大法師安琪拉‧朵桑托斯想要2個秘法水晶、3個大塊魔光裂片和30枚金幣。你也必須在銀色黎明取得崇敬聲望。", description = "很久以前，納克薩瑪斯的魔法結界阻礙了我們，使我們無法攻擊科爾蘇加德的部隊。雖然我當時成功隱蔽了我們的軍隊，後來我學會了驅散結界的方法，以免再次發生這種狀況。\n\n我承認我不相信你說的。不過，要是你決心要進行這個調查，我可以對你的徽記施法，讓你可以親自突破這些屏障。只需要付出小小的代價。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n強化委任徽章"}
MultiLanguageQuestData['tw'][76266] = {title = "大量任務", objective = "在紀元邊境的隨地旅店執行一系列的任務。", description = "嗨，<name>！我今天有個超級刺激的任務。我需要你在暴風城各處放置七條麵包，在奧格瑪放五罐牛奶。為了劃下完美的句點，還需要…\n\n<克羅米看了看她手中的筆記。>\n\n在潘達利亞各處撒七百四十二粒米！", progress = nil, completion = "哇，太不可思議了！與潘達利亞的皇帝和他底下的英雄一起渡過的這三天，真的是精采萬分。\n\n&lt;name&gt;，謝謝你讓我有伸展翅膀的機會，接下來就交給我吧。", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][76268] = {title = "墮落者的天譴石", objective = "這裡的天譴石越來越多，<name>，除了你，也有越來越多的冒險者拿過來。\n\n幸好，我們的士兵都沒有神祕地消失，我也沒有聽到更多毛骨悚然的尖叫，至少數量在這個地區算正常。\n\n我還是不要問太多才好，你的獎勵在這裡。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n銀色黎明勇氣勳章"}
MultiLanguageQuestData['tw'][76269] = {title = "放錯地方的蛋", objective = "找到紅龍蛋並將它放在顯眼的地方。", description = "喔，親愛的，這件事有點棘手。我們需要你把蛋放在羅甯一定會注意到的地方。這聽起來或許很奇怪，不過，他必須發現那顆蛋，之後才會展開行動，從舊部落手中救出雅立史卓莎，也順便拯救那顆蛋！\n\n我們要派你去丹奧加茲。那不是這一切應該發生的地方，不過時間現在就像乳酪一樣。好吃卻充滿孔洞。\n\n喔，這裡有一些沙子。它可以讓你行動時更加隱蔽。", progress = "你幫那顆蛋找個好地方了嗎？", completion = "你把它放到正確的位置了嗎？我在說些什麼，你當然成功了，不然我們就不會在這裡！\n\n等到雅立史卓莎獲釋後，格瑞姆巴托之戰就必勝無疑。更重要的是，她和其他守護巨龍會強迫死亡之翼迅速撤兵。如果羅甯沒找到她，誰知道死亡之翼會做出什麼？\n\n&lt;克羅米壓低聲音，看了雅立史卓莎一眼。&gt;\n\n你離開後，她就來了，就像她知道我們在做些什麼一樣！", rewards = "您會收到：\n\n囊封命運索芮朵蜜的認可超因果薄片"}
MultiLanguageQuestData['tw'][76270] = {title = "侵略者的天譴石", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n銀色黎明勇氣勳章"}
MultiLanguageQuestData['tw'][76272] = {title = "拍美照", objective = "專心聽從攝影師的指示。", description = "<class>，時尚大考驗讓我們有機會煥然一新。\n\n相機會確保我們看起來顏值爆表。\n\n把注意力放在我和相機上，照我的指示行動，我一定會把你拍得很好看！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76273] = {title = "拍美照", objective = "專心聽從攝影師的指示。", description = "<class>，時尚大考驗讓我們有機會煥然一新。\n\n相機會確保我們看起來顏值爆表。\n\n把注意力放在我和相機上，照我的指示行動，我一定會把你拍得很好看！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76276] = {title = "改變的大地", objective = "關心鄰近的巨龍群島住民。", description = "埃達希爾的到來為艾澤拉斯帶來了很大的改變。它在這片土地上扎下的根就跟它繁茂的枝葉一般廣闊。\n\n這是個好兆頭，但我們也不能忘記群島上的盟友。拜訪鄰近的住民，確認一下他們是否安好。", progress = "埃達希爾已安穩到來，但我們要確保盟友們也都安然無恙。", completion = "聽到朋友們都沒事讓我十分寬慰。勇士，感謝你去拜訪他們。", rewards = "您能選擇下列奬勵中的一個：\n\n常年球花墜飾日出頭環\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76280] = {title = "新月", objective = "在中央營地與泰蘭妲‧語風交談以開始進行儀式。", description = "有了這些東西與永恆之井的水，我們需要的東西就備齊了。\n\n等你準備好進行儀式，就跟我說吧。", progress = nil, completion = "埃達希爾…終於。感覺就像我一直都沒發現自己憋在心裡，然後突然鬆了一口氣。&lt;name&gt;，你幫了我們這麼多，多少感謝都難以表達我的謝意。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76281] = {title = "值得歡慶的事", objective = "在貝拉梅斯的慶祝活動中提供桌邊服務。", description = "終於呀…來吧，一起歡慶我們所克服的挑戰、慶祝希望又閃耀在聚集於此的卡多雷心中。\n\n來吧，一同參加慶祝吧。", progress = nil, completion = "這樹下充滿了歡樂，生命欣欣向榮。希望能永遠如此。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76282] = {title = "令人不安的感覺", objective = "在貝拉梅斯幫卡德加拿杯飲料。", description = "啊，<name>！我正好在找你。我有點擔心卡德加。這應該不是什麼大事，但他看起來沒有像其他人一樣那麼自在…感覺非常的…心不在焉。\n\n我不太想干涉他的隱私，但你能不能幫我拿飲料給他？或許他會願意跟你談談。", progress = nil, completion = "謝謝你，朋友。我就知道他會願意跟你談。\n\n也許我倆都能稍微放心了。", rewards = "您能選擇下列奬勵中的一個：\n\n賞心悅目的葉片指環夏空璽戒棘刺樹皮指環\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76283] = {title = "Andu-falah-dor", objective = "在貝拉梅斯與麥琳瑟拉交談。", description = "我母親請我們到月井與她會面。\n\n已經一小陣子了，不該再讓她繼續等下去。\n\n我們到那邊再說吧。", progress = nil, completion = "埃達希爾穿越夢境在艾澤拉斯繁茂成長的同時，我的妹妹也成了新的守護巨龍。\n\n&lt;雅立史卓莎朝著原本傳送門的位置看了一眼，微微一笑。&gt;\n\n還有你，&lt;name&gt;，謝謝你讓這一切有個美好的結局。", rewards = "您會收到：\n\n沉重的夢境種子埃達希爾的贈禮龍石"}
MultiLanguageQuestData['tw'][76285] = {title = "拍美照", objective = "專心聽從攝影師的指示。", description = "<class>，時尚大考驗讓我們有機會煥然一新。\n\n相機會確保我們看起來顏值爆表。\n\n把注意力放在我和相機上，照我的指示行動，我一定會把你拍得很好看！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76290] = {title = "歐瑪利安的第二本手冊", objective = "在東瘟疫之地的聖光之願禮拜堂把手冊還給工匠大師歐瑪利安。", description = "維爾海姆：\n\n如果你在讀這封信，代表我派去找你的第一位冒險者已經陣亡了。我也是一樣，最後，我希望你知道，我臨死前想到的是你跟你在專業技能方面有多笨拙。\n\n至於書：這些是我剩下的配方。請跟更有能力的人分享。唉，我敢說你會自己留著，然後為你的服務開出天價，畢竟，你就是個混蛋。\n\n我鄙視你，\n歐瑪利安您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n失傳的知識"}
MultiLanguageQuestData['tw'][76308] = {title = "時尚大考驗", objective = "與塑形師交談，參加並完成時尚大考驗。", description = "好，<class>，那穿搭真的是…很有趣。\n\n我？太挑剔？才沒有。不過，我很好奇其他人的看法。\n\n你應該去那裡跟塑形師談話，參加時尚大考驗。\n\n我們來看看大家對你選擇的穿搭有什麼看法。", progress = nil, completion = "不可思議。你通過時尚大考驗了。\n\n真讓我刮目相看。醜小鴨變天鵝的故事還真是勵志。\n\n你可以走了。你擋住我的鎂光燈了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76309] = {title = "吉爾尼斯險地賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76317] = {title = "夢境的呼喚", objective = "在沃卓肯完成珊蒂斯的「火焰聯軍」故事線，接著再前往雍亞拉平原的遠古枝幹。", description = "這棵大樹在夢境中成長，它很快就會將枝葉伸入艾澤拉斯世界。\n\n但在那之前，我們必須阻止想要傷害它或是將它的力量佔為己有的人。我們必須團結一心，這樣它才能長得更加茂盛。\n\n跟我還有遠古枝幹的所有同伴一同前往翡翠夢境吧。", progress = nil, completion = "不久之前，世界之樹種在了翡翠夢境中，我們在那裡保護它的安危。\n\n現在我們的敵人找到了一條能進入夢境的路。我們必須團結起來保護這棵樹。它能為我們帶來希望…實現更多的可能。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76318] = {title = "歡迎來到夢境", objective = "穿過遠古枝幹的傳送門進入翡翠夢境。", description = "我們得守住所有翡翠夢境的出入口來保護大樹，因為現在菲拉卡找到了盟友為他開啟入口。\n\n我會為你和我們盟友開啟傳送門，綠龍軍團沒辦法孤身奮戰打贏這一仗。\n\n穿過這個傳送門就會進到翡翠夢境。我們必須保護這個界域，以及其中的所有事物。", progress = nil, completion = "菲拉卡的力量威脅了夢境的結構。我們得趕快保護這個國度。這隻飛龍會協助你。", rewards = "您會收到：\n\n繁茂奇行飛龍龍石"}
MultiLanguageQuestData['tw'][76319] = {title = "宴會或是焰火", objective = "使用飛龍騎術或騎乘精靈飛龍撲滅夢境的燃燒區域。", description = "菲拉卡已對夢境的結構造成破壞，我可以感覺到它在燃燒，好像火焰在吞噬我的鱗片一樣。\n\n我也清楚，這樣隱隱作痛的感覺只有菲拉卡折磨我兒子的萬分之一而已。\n\n但我們有個能夠對付烈焰的利器。精靈龍和巨龍有著不同一般的力量。雖然關係維持不易，但他們是極佳的盟友。\n\n現在他們需要我們的幫忙。用上這個，把空中的烈焰全都撲滅吧。", progress = nil, completion = "菲拉卡隨時都可能對大樹發動攻擊。我們需要其他荒野神靈的協助。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76320] = {title = "我們之中的荒野神靈", objective = "在翡翠夢境中尋找荒野神靈與盟友。", description = "翡翠夢境是自然荒野神靈的家。我們會需要他們的力量來抹除菲拉卡對這個界域造成的傷害。\n\n首先要找的是戈德林。這隻遠古神狼對艾澤拉斯和凡人關愛有加，他一定會幫助我們的。\n\n其他的神靈就需要多加說服了。\n\n我會在遐想原野那裡等你，有很多林精和林地守護者都住在那邊。", progress = nil, completion = "我們太遲了。菲拉卡的部隊已經開始攻打夢境！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76321] = {title = "灼熱來襲", objective = "殺死洪荒使者、加拉登與火焰德魯伊。", description = "火焰德魯伊正在為菲拉卡的部隊開啟通往夢境的入口。隨著時間過去，就會有越多入侵者。\n\n我們得在事態變更嚴重之前力挽狂瀾。", progress = nil, completion = "表現不錯，但恐怕現在已經無法完全阻止這些部隊了。他們將對夢境產生不可抹滅的影響。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76322] = {title = "敵人的面貌", objective = "擊敗菲拉卡強大的副官，肅清戰場。", description = "在菲拉卡召喚到翡翠夢境的部隊之中，也有幾個特別強大的敵人。\n\n自卡莎芬從她的巢穴出來以後我就沒看過她了。\n\n把她找出來，然後協助盟友將這些領袖擊敗。", progress = nil, completion = "這比我想得還要嚴重。我們每關閉一個傳送門，火焰德魯伊就會開啟更多。\n\n恐怕還有很多危機正等著入侵。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76323] = {title = "埃達希爾", objective = "在埃達希爾的樹底下與麥琳瑟拉會面。", description = "自這棵樹被種在這裡之後，它便安然在翡翠夢境之中成長茁壯。我們在此關照滋養它有一段時間了。\n\n而現在，正當它要離開這個安穩的搖籃進到艾澤拉斯之時，我們的敵人卻想利用它來完成自己的計畫。\n\n它不僅僅是棵樹而已。\n\n來吧，我們去埃達希爾。", progress = nil, completion = "我們來的正是時候。我們必須在卡莎芬對大樹…或是對我們造成任何傷害之前阻止她。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76324] = {title = "迷失於烈焰", objective = "在埃達希爾的樹底下擊敗卡莎芬長老。", description = "火焰德魯伊造成的威脅比我想像的還要大很多。他們不只讓菲拉卡和他的部隊進到夢境，還想引誘夢境的子民誤入歧途！\n\n我們不能讓這樣的事發生。雖然很難過，但我們務必阻止卡莎芬。\n\n與泰蘭妲一起…擊敗那個林精吧。", progress = nil, completion = "翡翠夢境是個充滿野性、魔法與生命的地方。\n\n看到同胞落入這樣的下場讓我十分難過。希望不會有人再步上她的後塵。\n\n等等…你聽見了嗎？", rewards = "淺翠勇士壁壘盛夏撫慰者器具活潑雄鹿枝條無畏飛靈戰刃淺翠勇士之刃淺翠勇士戰矛盛夏撫慰者柺杖無畏飛靈釘錘活潑雄鹿長弓活潑雄鹿砍斧活潑雄鹿手斧盛夏撫慰者重槌淺翠勇士裁決錘淺翠勇士巨劍盛夏撫慰者魔杖活潑雄鹿幼苗活潑雄鹿曲弓您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76325] = {title = "棘手的菲拉卡", objective = "與麥琳瑟拉交談並準備抵禦菲拉卡的攻擊。", description = "我聽到了振翅的聲響，還聞到了暗焰的氣息。\n\n菲拉卡來了。\n\n<麥琳瑟拉雖然竭力克制，但還是可以感覺得到她的熊熊怒火。>\n\n有人一定會為蓋瑞瑟斯受到的痛苦而付出代價。", progress = nil, completion = "他沒有攻擊世界樹？\n\n他還有其他目標嗎？\n\n而且，為什麼他會聽那個火焰德魯伊的話？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76326] = {title = "夢境之中的家", objective = "在埃達希爾樹下的中央營地與麥琳瑟拉會面。", description = "菲拉卡撤離了埃達希爾，但那反而更加深我的疑慮。他在翡翠夢境中一定還有其他目標。\n\n我們必須在大樹底下跟其他人交換情報。泰蘭妲和卡多雷已經駐紮在那裡了。\n\n我得跟雅立史卓莎談談，來決定下一步該怎麼走。", progress = nil, completion = "既然有了喘息的機會，我們可以開始想想接下來該怎麼做。\n\n而且我知道，有你站在我們這一邊，我們會更強大。", rewards = "您會收到：\n\n夢境守望者"}
MultiLanguageQuestData['tw'][76327] = {title = "伊瑟拉之眼", objective = "使用埃達希爾的傳送門進到伊瑟拉之眼。", description = "蓋紝諾麗的情報還真讓人擔憂。\n\n伊瑟拉之眼的神殿是我在夢境中的力量來源。透過它，我才能獲得伊瑟拉之眼的能量，監測夢境及其中住民的安危。伊瑟拉之眼的力量會在整個夢境之中湧動，還能幫助埃達希爾成長。\n\n若是加拉登成功佔下此處，便能改變這裡的生態，讓大樹停止生長。\n\n我的女兒深知伊瑟拉之眼的重要性，我會跟隨她的。你也應該如此。", progress = nil, completion = "這就是伊吉拉的新手下嗎？不堪一擊。我們會勝過這怪物的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76328] = {title = "新的惡棍", objective = "對5名翡翠護存者使用夢境精華。接著，在伊瑟拉之眼中的神廟與伊瑟拉會面。", description = "加洛克只是菲拉卡的一名嘍囉罷了。我不會被他嚇唬到的。\n\n火焰之球一定是他幹的好事，妄想用他的魔法拿下伊瑟拉之眼。伊瑟拉正在神廟裡頭引導屏障，不過效果似乎不如預期。\n\n現在，我必須去迎戰加洛克。若我們的施法者變弱了，就用我的魔法強化他們吧。防禦陣線不能潰散！", progress = nil, completion = "母親還在掙扎…", rewards = "您能選擇下列奬勵中的一個：\n\n賞心悅目的葉片指環夏空璽戒棘刺樹皮指環\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76329] = {title = "不被覺察地偵查", objective = "在落燼堡監視加拉登領袖。", description = "波德溫回報說加洛克不是伊瑟拉之眼唯一的新敵人。有兩個人正在率領下面的加拉登部隊，分別是戰士和法師。\n\n在他們準備周全的基地直接攻擊他們不太明智，但我很確定他們是加洛克攻擊計畫的一環。\n\n請你幫忙從加拉登首領那裡收集更多情報，我們得找出如何反制他們的進攻。波德溫可以給你潛行偽裝，讓你可以自由出入營地，不會被人看見。", progress = nil, completion = "&lt;麥琳瑟拉十分冷靜。但她的眼神卻顯現了無盡的怒意。&gt;\n\n我們會為同胞復仇的。", rewards = "無畏飛靈罩氅盛夏撫慰者裹布活潑雄鹿斗篷淺翠勇士披風您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76330] = {title = "繳械專家", objective = "殺死6個元素灌能塑造者並摧毀8個元素灌能補給品。", description = "波德溫的偵查小隊帶回了更多關鍵情報。加拉登計畫使用元素灌能武器來扭轉戰局。\n\n我們必須解決他們的工匠和摧毀武器。鎖定這兩者就可以削弱與延緩他們的進攻速度，接下來我們就有更多時間思考下一步的計畫。\n\n你在這次任務中需要深入險境，所以把這個帶上。\n\n把這東西丟向敵人，就可以使他們暫時沉睡。如果你寡不敵眾的話，使用可以幫你脫離戰鬥。\n\n祝你好運，$p。", progress = nil, completion = "這樣就可以大幅削弱他們的戰力了。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76331] = {title = "麥琳瑟拉的賭注", objective = "告訴伊瑟拉消除魔法屏障。", description = "我們已經準備好了。守衛已就緒，陷阱也都設置完畢。\n\n翡翠護存者跟伊瑟拉的魔法會相互連結。只要你一聲令下，他們就會同時消除魔法屏障。這正是加洛克想要的。他的部隊會像飢餓的食腐鳥一樣蜂湧闖入此地。\n\n就等你發號施令了，<name>。", progress = "我們走吧。", completion = "我得相信她…還有我自己。是時候奮勇一搏了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76332] = {title = "穩穩扎根", objective = "在8處耕過的土壤中種下種子，並與基亞‧羽爪談話。接著，再與索姆尼克斯交談。", description = "我們設下了多層陷阱。\n\n在城鎮周圍種下種子，我們的園丁已經準備好泥土。這些種子能有效使敵人中毒。處理的時候要小心一點，有些可能會長得比較快。\n\n還有，我們烏爪獸管理員基亞‧羽爪對於動用強大的猛獸似乎有些點子。去找她談談吧。\n\n最後，與索姆尼克斯會面，要他警告大家戰事將一觸即發。", progress = nil, completion = "現在…我們準備好了。", rewards = "盛夏撫慰者手環淺翠勇士護腕活潑雄鹿腕輪無畏飛靈腕環您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76333] = {title = "三重威脅", objective = "殺死加洛克‧割翼者和他的加拉登副官：鐵砧與熔結者。", description = "加洛克來了。一切都按照計畫。\n\n我們會阻止他和那些手下。", progress = nil, completion = "加洛克就快撐不住了。繼續給他們壓力！", rewards = "盛夏撫慰者兜帽活潑雄鹿頭盔無畏飛靈面罩淺翠勇士戰盔您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76334] = {title = "多多商討", objective = "與綠龍軍團討論麥琳瑟拉的計劃。", description = "加洛克是個懦夫。直到有十分把握之前，他都不敢跟我們直接交戰。\n\n我們沒有資源能夠攻打他的基地。但若是無法與之決戰，也許能把他困在我們的領地之中。\n\n我想我們可以在這裡設下陷阱引誘加洛克和他的部隊。但我的計畫也不是萬無一失，對於戰場的控制將會是至要關鍵。\n\n不過有個問題…我們該怎麼引誘他呢？", progress = "我必須了解各位的想法，尤其是要實施這麼大規模的計劃。", completion = "&lt;麥琳瑟拉靜靜地對我們的盟友點了點頭。&gt;\n\n就這麼定了。大家開始準備吧。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76335] = {title = "森林之力", objective = "在伊瑟拉之眼消滅所有加拉登威脅。啟動陷阱來協助你戰鬥。", description = "利用你稍早設下的陷阱吧，<name>。擊敗所有膽敢威脅我們的怪物！", progress = nil, completion = "戰局扭轉了！繼續推進。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76336] = {title = "飛行與戰鬥", objective = "乘上飛龍騎術坐騎，在伊瑟拉之眼上方殺死25個烈火岩翼蝠。", description = "我們已拿下了腳下這片土地…現在該奪回這片天空了。\n\n縱使加洛克飛離我們，但他的力量衰弱不少。發動攻擊的時候到了。", progress = nil, completion = "總算完成了。", rewards = "無畏飛靈手套淺翠勇士護手盛夏撫慰者長手套活潑雄鹿手甲您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76337] = {title = "餘燼仍在燃燒", objective = "與麥琳瑟拉在埃達希爾重新會合。", description = "我…真不敢相信成功了。對於大家的信任與忠勇我十分感激。若沒有我們盟友與龍族齊心協力，我們不可能打贏這場仗。\n\n但戰事還尚未結束。根據我們獲得的情報，菲拉卡和他的嘍囉正準備發動一場更大的襲擊。他們的基地還十分穩固，而且還離夢境希望，埃達希爾的壁壘十分接近。\n\n攻打伊瑟拉之眼也許只是個幌子。我們會與剩餘的盟友在埃達希爾重新會合。", progress = nil, completion = "感謝你前來，&lt;name&gt;。", rewards = "您會收到：\n\n沉重的夢境種子靈眼的淚水"}
MultiLanguageQuestData['tw'][76338] = {title = "更好的捲心菜破壞者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76339] = {title = "洛克莫丹迴圈賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76342] = {title = "燒死他們！", objective = "在洪荒使者城塞中弱化洪荒使者的根據地。", description = "維蘭諾斯離開之後，菲拉卡便給全部四名維蘭諾斯利爪使不同的任務。\n\n他派我掌管這個營地，還告訴我要不計一切代價保持傳送門開啟。而火焰德魯伊便強化了傳送門，好讓洪荒使者能夠進來。\n\n我們得關閉那些傳送門，削弱他們的勢力。", progress = nil, completion = "破壞他們的勢力應該能暫且保護夢境了。", rewards = "淺翠勇士脛甲無畏飛靈手套淺翠勇士護手盛夏撫慰者長手套活潑雄鹿手甲盛夏撫慰者軟靴活潑雄鹿足靴無畏飛靈長靴您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76343] = {title = "周全的計畫", objective = "在洪荒使者城塞中收集4個線索。", description = "菲拉卡也許很衝動，但他不是蠢蛋。若要拯救夢境，我們得盡快了解他的計畫。\n\n洪荒使者還尚未整頓完畢，滲透他們的營地然後尋找任何線索與情報。\n\n我們獲得的情報越多，我們才可以更快擊敗菲拉卡，一勞永逸。", progress = nil, completion = "雷絲卡留下了這些紙條？", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76344] = {title = "洪荒使者指導原則", objective = "說服5名特羅的洪荒使者與維蘭諾斯站同一陣線。", description = "特羅是維蘭諾斯的一名利爪使。他從來就不想攻打夢境，侍奉他的一些洪荒使者也同樣不願意。看看能不能說服他們加入我們這邊。\n\n我會在你身上標下維蘭諾斯標記，這樣特羅的部隊就不會…這麼快發現你。", progress = nil, completion = "特羅很保護他底下的人。他也會希望我們能盡力拯救所有人。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76345] = {title = "尋找特羅", objective = "在翡翠夢境中發掘更多與菲拉卡計畫有關的情報。", description = "我不知道我舊時的守衛還願意回到我身邊。我很…很高興能見到他們。當我選擇去找雅立史卓莎時，沒有人知道。我就這麼離開了。\n\n但是我得先放下個人的目標，全盤了解菲拉卡的計畫。看看布里還會分享哪些情報吧。", progress = nil, completion = "在為特羅復仇以前，維蘭諾斯是不會停手的。", rewards = "您能選擇下列奬勵中的一個：\n\n常年球花墜飾日出頭環\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76347] = {title = "權力、爆發與謊言", objective = "在燼火峰殺死雷絲卡。", description = "布里告訴我雷絲卡計畫點燃燼火峰，維蘭諾斯就動身追擊她了。\n\n雷絲卡會揭露自己是因為，她知道維蘭諾斯一定會追上來。燼火峰的力量能夠摧毀這道屏障，或是維蘭諾斯。\n\n我們也得跟上去。", progress = nil, completion = "失去這名朋友讓我感到難過，但這是我該做的。", rewards = "盛夏撫慰者禮袍淺翠勇士胸鎧活潑雄鹿護胸無畏飛靈外衣盛夏撫慰者兜帽活潑雄鹿頭盔無畏飛靈面罩淺翠勇士戰盔您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76348] = {title = "又大、又亮、又完美的屏障", objective = "在翡翠夢境中收集6個屏障碎片。", description = "布里？維蘭諾斯？\n\n當她拋下我們，害我們受到菲拉卡的掌控之後，我們不得不追隨他。雖然我不知道他的計畫，但他指派我跟這些洪荒使者摧毀這道屏障。\n\n我們沒有什麼進展，但維蘭諾斯會希望我們拖延他的計畫。\n\n某些屏障的碎片就四散在各處。若你能把它們收集起來，我們可以把它們的能量導回到屏障之中。\n\n可以麻煩你彌補我造成的傷害嗎？", progress = nil, completion = "謝謝你阻止他的破壞。", rewards = "您會收到：\n\n淺翠勇士腿鎧盛夏撫慰者護腿活潑雄鹿腿甲無畏飛靈長褲龍石"}
MultiLanguageQuestData['tw'][76350] = {title = "時光鐵匠", objective = "在紀元邊境的熔爐找鐵諾姆。", description = "你是來幫我們的？如你所見，紀元邊境周圍的時間異常都消失了，但工作永遠做不完。\n\n我們最厲害的時光鐵匠向我們求助，他是名叫鐵諾姆的青銅龍。問題在於，在這一片混亂中，到處都找不到他。他前去設置工坊，現在早該回來了。\n\n<節奏焦躁地嘆了一口氣。>\n\n可以請你去找他嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76351] = {title = "泰坦野獸", objective = "關閉時間裂隙後，回去提爾堡蓄水池找索芮朵蜜。", description = "<你擊敗野獸後，這部小巧的裝置從它的嘴裡滾了出來。\n\n這似乎是泰坦的情報裝置，不過比你在艾澤拉斯看到的裝置還要精巧。\n\n索芮朵蜜一定會想看看這東西。>", progress = nil, completion = "&lt;索芮朵蜜擺弄著這部裝置。&gt;\n\n你說這東西出自一隻大型野獸的嘴巴？\n\n好吧，希望它之前的主人沒受到太多折磨。\n\n我會把它放在我身後的一張桌子上，方便你之後進行賞玩。也許到時候它會比現在還乾淨。", rewards = "您會收到：\n\n超因果薄片索芮朵蜜的認可"}
MultiLanguageQuestData['tw'][76352] = {title = "時光之錘時間！", objective = "在時光通道擊殺時空錯置的生物並摧毀裂隙，來重新同步埃隆努斯的時光之錘。", description = "如果我要在這裡修理年輕鰭杜因的劍，我們就必須破開熔爐上的這個時間鎖。如果錘子可以打壞鎖，那時光之錘一定可以打壞時間鎖。\n\n不幸的是，我的錘子有點失去同步了。不過危機就是轉機。附近的裂隙侵入我們的時間線，地點就在時光合流外面，而且跳脫時間的醜東西大舉入侵。\n\n到紀元邊境外面去，肅清那片區域，同時為我的錘子充能。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76354] = {title = "為了寶藏！", objective = "找到並收集埃隆努斯的文物。", description = "我在時光通道有個倉庫，裡面放滿施了時間魔法的箱子。箱子內裝著來自不同時間線的文物。\n\n不幸的是，我對倉庫設下的防護機制被那些爆炸的時間裂隙弄壞了。我飛過去看了一下，發現那些該死的強奪者把那些箱子丟得到處都是！\n\n既然你要去那裡，順路的話，能不能幫我撿回一些東西。當然，不用全部拿回來！重要的東西拿回來就夠了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76356] = {title = "偷劍焦烙者", objective = "取回鰭杜因‧烏嗄咕喀的劍「海貝曼恩」。", description = "那些從熔爐誕生的髒東西直接撞倒鰭杜因，拿走了海貝曼恩！它們一定是感應到那把劍上殘留的時光能量。\n\n無法想像它們要用它做什麼，不過沒時間靜觀其變了。\n\n沒有鰭杜因的劍，我就無法進行修復，那麼你所做的一切都沒有太大的意義。你可以幫我找回那把劍嗎？畢竟，亞茲莫洛斯的命運全繫於此！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76357] = {title = "灼熱彎道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76361] = {title = "時裝週", objective = "與時尚大考驗特使交談。", description = "啊，時尚大考驗正式開始了，<class>。\n\n參賽者的服裝、創意和氣質都是活動的一大看頭。\n\n跟時尚大考驗特使交談，進一步了解這個活動吧。\n\n先提醒你一下，那些特使…不是些好相處的人。", progress = nil, completion = "你真的覺得自己準備好參加時尚大考驗了嗎？\n\n你就穿這樣？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76362] = {title = "帶角顱骨", objective = "將帶角顱骨交給提爾堡蓄水池的索芮朵蜜。\n\n已提供物品：\n", description = "<儘管處在這種地方，這個顱骨似乎未被魔能腐化。\n\n當你把手伸向它時，你感覺到它散發出一股安心感。\n\n索芮朵蜜一定會想看看這東西。>", progress = nil, completion = "&lt;索芮朵蜜小心翼翼地拿起顱骨，舉到可以平視的高度。&gt;\n\n你說你在被魔能腐化的伊利丹身旁發現這個東西？\n\n我覺得這應該是瑪法里恩。\n\n我們還以為，在我們的時間線，他們的家庭問題已經夠嚴重了。", rewards = "您會收到：\n\n超因果薄片索芮朵蜜的認可"}
MultiLanguageQuestData['tw'][76364] = {title = "暮光恐懼賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
