MultiLanguageQuestData['tw'][76530] = {title = "無生召喚", objective = "前往羅德隆廢墟向莉莉安‧佛斯回報。", description = "<name>，提里斯法需要你幫忙。快過來。\n\n羅德隆廢墟外有個新的危機正在萌芽，情況看起來不樂觀。我會在你抵達時跟你詳細說明。", progress = nil, completion = "謝謝你趕來。我們有個新的麻煩。", rewards = "您會收到：\n\n"}
