MultiLanguageQuestData['tw'][76564] = {title = "巨龍殺手的工具", objective = "找到三個同調文物。", description = "如果你想追一隻巨龍，還有誰比加拉登更厲害的呢？\n\n<name>，看看我們能找到什麼吧。", progress = nil, completion = "啊哈！把護目鏡給我，我會幫你校正的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76566] = {title = "林精花園", objective = "到根縛聖域與伊熙德里斯‧溪衛談話。", description = "$p，有一個我個人非常擔心的問題。\n\n隨著埃達希爾的成長，有個由我的林精族人照料的花園也遭受越來越多的苦難。\n\n有個疲憊不堪的德魯伊正在照料那個花園，不過我懷疑他需要的幫助遠比他提出的還要多。\n\n請代替我去助他一臂之力。", progress = nil, completion = "塞納留斯派你來的？太棒了。我們真的很需要幫忙。\n\n我們必須找到那個林精橡實！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76567] = {title = "躁動的花園", objective = "在根縛聖域耗盡8隻野生動物的力氣。", description = "聖域已經變了一個樣！\n\n世界之樹的樹根沿著這個花園生長，但這個改變似乎讓野生動物變得躁動不安。\n\n拜託幫忙消耗牠們過剩的精力。也許等到牠們累到不行，就會再次安分下來。", progress = nil, completion = "謝謝你，&lt;name&gt;。我看得出你暫時讓牠們冷靜下來了。\n\n這種事已經不是第一次發生，也大概不會是最後一次。這真的只是埃達希爾的樹根造成的嗎？這種行為太古怪了…", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76568] = {title = "松果鼩之亂", objective = "在根縛聖域搖晃20隻松果鼩的種子。", description = "花園陷入一團混亂後，這裡的松果鼩開始囤積種子。重要的種子。我們花一大堆時間照料和培育的種子。\n\n輕輕搖一下就能讓種子掉下來。請快點行動，別讓牠們再帶著更多種子跑掉！", progress = nil, completion = "看來戴歐尼莎決定選你來訓練她。\n\n&lt;伊熙德里斯繃緊了臉。&gt;\n\n太好了。簡直完美。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76569] = {title = "德魯伊守護者會談", objective = "在根縛聖域與伊熙德里斯‧溪衛談談如何扶養林精。", description = "一般而言，被指派到林精聖域的德魯伊都會負責指導新生的林精，直到他們準備好接替自己的職責。\n\n問題在於，很難讓林精離開她產生印痕的對象。\n\n<伊熙德里斯嘆了口氣，揉揉他的眼睛。>\n\n這點她已經表達得很明顯。那好吧，跟我說說你的事吧。說不定你也跟當初的我一樣，可以當個很好的照料者。", progress = nil, completion = "你身經百戰，又擅長解決問題。有時是自己的問題，有時則是別人的問題。\n\n老實說，在我看來，照顧林精也是大同小異。\n\n我覺得戴歐尼莎會沒事的。", rewards = "您會收到：\n\n林精看守者憑證龍石"}
MultiLanguageQuestData['tw'][76570] = {title = "家族事業", objective = "到根縛聖域附近的曲木林，收集6個鞭笞者之心。", description = "我負責向每個新生林精傳授知識。戴歐尼莎已經學到我所有的本事，但她缺乏實務經驗。\n\n既然你完成任務的經驗似乎很豐富，你應該可以教教戴歐尼莎。\n\n在花園外面的曲木林中，有一群鞭笞者最近變得越來越躁動。收集它們的心臟，好讓我們釐清其中的原因。", progress = "德魯伊溪衛告訴我，鞭笞者通常會躺著等待獵物到來。\n\n很高興這些鞭笞者不是這樣，所以戰鬥變得更好玩了！", completion = "這些心臟真難聞！幾乎就跟那些滿嘴利齒的魔花人一樣難聞…", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][76571] = {title = "種植體驗", objective = "讓戴歐尼莎在曲木林種植3株花朵。", description = "戴歐尼莎與塞納留斯的連結讓她能夠種植植物，不過她需要練習的空間。\n\n這裡那些躁動的野生動物會成為你的阻礙。附近的曲木林空間更大，麻煩卻少得多。\n\n<玫莉萊恩微笑，露出不容置疑的堅定眼神。>\n\n如果她中了魔花人的毒，不用擔心，林精對劇毒免疫。但你卻沒有這種特異功能。", progress = nil, completion = "守護者。如果魔花人正在毒害這裡的土地，那就必須鏟除那邊那棵散發劇烈惡臭的巨大植物。", rewards = "您會收到：\n\n幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][76572] = {title = "劇毒催化", objective = "到曲木林擊敗病態增生。", description = "守護者！這些魔花人不只讓鞭笞者中毒了，現在還扭曲了那個魔陀羅！\n\n如果我們不出手阻止，它就會把劇毒散播到花園。花園裡的野生動物會變得如此躁動，也一定是這個原因。它們很快就會入侵這裡！\n\n我們去消滅它吧。你訓練我這麼久，就是為了生死存亡的這一刻！", progress = nil, completion = "嘿！哈！守護者！長矛在手，讓我感受到前所未有的活力！\n\n&lt;戴歐尼莎笑得牙齒都露出來了。&gt;\n\n謝謝你的守護！", rewards = "您會收到：\n\n沉重的夢境種子幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][76576] = {title = "難以置信的提議", objective = "觀看過往的景象。", description = "加拉登領土深處的地底下有巨牙海民神器？\n\n如果不是我們自己找到的話，我還真不敢相信。你覺得他們在這地下做些什麼？\n\n好，看來連結點就在這洞穴裡面。我們進到裡面去吧！", progress = nil, completion = "巨牙海民跟加拉登在進行交易？真想知道那能維持多久。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76577] = {title = "沃卓肯啤酒節", objective = "到巨龍群島上的沃卓肯與布萊杜‧戰酒交談。", description = "我們送了些啤酒節產品到巨龍群島上。我聽說他們開始舉辦自己的慶祝活動了！當然，跟這裡的節慶沒法比，但為了活動去拜訪巨龍一趟也絕對值得！", progress = nil, completion = "你是來喝酒的嗎？哈！我這裡有很多呢。", rewards = nil}
MultiLanguageQuestData['tw'][76579] = {title = "沃卓肯啤酒節", objective = "到巨龍群島上的沃卓肯與布萊杜‧戰酒交談。", description = "看來半龍人今年決定舉辦自己的啤酒節節慶了！當你參與完這裡的慶祝活動後，到巨龍群島上看看他們的節慶吧。", progress = nil, completion = "你是來喝酒的嗎？哈！我這裡有很多呢。", rewards = nil}
MultiLanguageQuestData['tw'][76586] = {title = "散布光芒", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76587] = {title = "研究：雍亞拉平原河川半人馬", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76588] = {title = "烈焰防衛者", objective = "在受鑰炎控制的區域內消滅兩隻稀有生物。", description = "遠征隊面對著棘手的敵人。\n\n如飛蛾撲火般襲向我們鑰炎，企圖撲滅我們的火光，讓我們白費功夫。\n\n有兩個難纏的原生物對我們的鑰炎構成極大威脅，請幫我們擊敗他們。只要同心協力，我們就能驅離這片黑暗。", progress = nil, completion = "做得非常好，這樣就少兩個要對付的威脅了！", rewards = "您會收到：\n\n燈火者補給包"}
MultiLanguageQuestData['tw'][76591] = {title = "冒泡烈酒", objective = "收集沃卓肯裡的烈酒泡泡。", description = "可惡！請半龍人幫我送貨可能是天大的錯誤。他們讓酒桶在城裡到處滾，還把它們摔個粉碎！如果可以的話，我們不該浪費這些美酒！\n\n拿著酒桶然後飛到空中吧！盡可能收集泡泡，不然美酒都被糟蹋了。", progress = nil, completion = "謝謝你的大力幫忙。現在我只需要說服半龍人用飛的載過來就好，不要用滾的…", rewards = "您會收到：\n\n啤酒節獎品章龍石"}
MultiLanguageQuestData['tw'][76592] = {title = "隻翼難行", objective = "在蒼藍高地尋找馬里索斯。", description = "阿米索拉帶回了沉痛的消息。碎裂火焰軍沒有斬除殆盡！\n\n我們已經努力在沃卓肯找出剩下自成一群的半龍人，然後把他們帶回來。我派阿米索拉和馬里索斯跟他們談了，但據阿米索拉回報，他們是碎裂火焰軍的殘餘勢力。\n\n馬里索斯還被抓走了!\n\n馬里索斯原本是他們的一份子，所以他的處境會十分危險。我們必須對此事展開調查，並確保他安全無虞。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][76593] = {title = "本意良善", objective = "在寂寞瀑布尋找能解開馬里索斯鐐銬的鑰匙。", description = "他們不只打傷他…還把他銬了起來！\n\n更可怕的是…我應該也會做相同的事…\n\n馬里索斯身上的鐐銬太重，我們沒辦法帶他離開這裡。鑰匙應該就在營地附近。<name>，去找鑰匙，同時我會在這裡減輕他的痛楚。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76594] = {title = "倒下的半龍人", objective = "在寂寞瀑布尋找翼箔草。", description = "馬里索斯的傷不是治療就能復原的。如果他想飛離這裡，他需要妥善照顧。\n\n幸好，這附近有藥草可以增強治療的效果…應該足以讓他站起來了。\n\n<name>，四處找找、收集翼箔草吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][76595] = {title = "緊急滲透任務", objective = "不讓碎裂火焰軍靠近阿米索拉跟馬里索斯。", description = "軍需官多洛斯的死對碎裂火焰軍來說非同小可…\n\n他們會把我揪出來。馬里索斯跟阿米索拉還很虛弱。不能讓他們找到我們。\n\n鞏固周圍防禦，不要讓碎裂火焰軍靠近阿米索拉跟馬里索斯。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n飛龍暗焰紋章碎片龍石"}
MultiLanguageQuestData['tw'][76598] = {title = "美中不足", objective = "找到雅立史卓莎並確認她的狀況。", description = "很抱歉無法親自與你見面，<name>，不過這似乎是最便捷的方式。\n\n我們與洪荒使者的戰爭令我們的女王一直憂心忡忡，但最近她的心情又變得更加低落。好像有什麼事壓得她喘不過氣。我很清楚內心的負擔可以沉重到何等地步。\n\n不久前，她表示需要找個安靜的地方想事情，隨即離開沃卓肯，不過…我很擔心她。\n\n求求你，請去找她，確定她安然無恙。還有，不必告訴她是我派你去的。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76599] = {title = "精準陀螺光學儀器 - 啟用", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][76600] = {title = "吉光之間", objective = "在奧布雷的幫助下，消滅8個影癲收割者。", description = "我的丈夫「埃茲吉」很喜歡那些收割者，但我不信任它們，現在你也知道原因了！\n\n火光熄滅後，它們都開始試著殺死我們！\n\n你想幫我解決問題嗎？\n\n我是個百發百中的神槍手。你幫我標記目標，我就開始射擊！", progress = nil, completion = "埃茲吉一定會很傷心，但我和你做了必要的事。", rewards = "您會收到：\n\n燈火者補給包共鳴水晶聖落之地阿拉希青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][76733] = {title = "馬鈴薯收集狂", objective = "點燃5根收割火炬，並收集15個火光馬鈴薯。", description = "暴走的收割者毀了我們絕大多數的作物，這個地方的收成工作成了一大挑戰。如果你仔細尋找，一定能找到馬鈴薯。\n\n如果你能點燃收割火炬，或許就能發現藏在黑暗中的馬鈴薯。\n\n利用那些火光，想辦法採集馬鈴薯。在這種艱困的時刻，一點糧食都不能浪費。", progress = "你找到馬鈴薯了嗎？", completion = "太棒了。我們大家都愛炸薯條，我們今晚就炸一些來享用吧！", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希"}
