MultiLanguageQuestData['tw'][77098] = {title = "地面躲藏", objective = "在蒼藍高地帶馬里索斯前往安全地點。", description = "他需要治療，現在就要。\n\n這裡太空曠了。碎裂火焰軍的忠誠分子隨時都能發動突襲。\n\n我們得找掩護，這樣才能照料他的傷勢。\n\n掩護我！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77099] = {title = "酒吧收帳桶", objective = "捐獻給巨龍群島上的各個旅店來結清帳款！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章"}
MultiLanguageQuestData['tw'][77100] = {title = "勘查懸崖邊", objective = "與蘿思卡談話來開始挖掘，再從懸崖邊挖出文物。", description = "沒有比柔和的海風更能激起努力挖掘的心志了！\n\n我們所在的廢墟是遠古龍類的漁村。這些龍類便是當今生活於此的藍色巨龍的祖先。正如你所見，因為地處偏遠，這個地方沒有遭到寶藏獵人破壞。\n\n如果這裡的寶貝沒有被沖到海裡的話，我們一定找得到！", progress = nil, completion = "&lt;蘿思卡讚嘆地吹了口哨。&gt;\n\n遇到這小寶貝還真是幸運，你說是吧？再過一百年，這東西可要成為魚蝦的食物了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77102] = {title = "地獄火疾飛賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77151] = {title = "峭壁的箱子", objective = "與蘿思卡交談並開始仔細挖掘龍類寶箱。", description = "<這個埋在石堆中的桶子被鹽巴給覆蓋，但看起來還十分完整。\n\n這應該是村民用來儲物的普通箱子，但這裡有上千年都無人居住了。裡面還可能會有東西嗎？\n\n蘿思卡一定會想看看！>", progress = nil, completion = "哇，&lt;name&gt;！這個箱子不只完好無缺，裡面裝的東西也不只是海水！\n\n說不定能找到早已失傳數千年的曾曾曾祖母果醬食譜。沒錯，這一定會引起當地人的轟動！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77152] = {title = "酒吧收帳桶", objective = "捐獻給巨龍群島上的各個旅店來結清帳款！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n啤酒節獎品章"}
