MultiLanguageQuestData['tw'][77286] = {title = "水往低處流", objective = "帶著擦拭露出的石板去找沃卓肯的巴比‧卡萊爾。", description = "<拓文是以古代語言寫成。或許巴比‧卡萊爾可以翻譯拓文。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77303] = {title = "搜尋塑像", objective = "卡索斯又送來另一張紙條。\n\n看來有個莫魯克文物有危險了。文物藏在永恆墓塚的其中一個墳墓裡。紙條中提到，有個古老的薰香隱藏了文物，使它不會顯露在外人面前。\n\n剩下的情報都在這張紙條裡。祝你好運，冒險者！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n保護學家的急件二"}
MultiLanguageQuestData['tw'][77304] = {title = "塑像在手", objective = "將雍亞拉塑像還給沃卓肯的保護學家卡索斯。", description = "<塑像模仿雍亞拉的形象，以賽若拜岩雕刻而成，這種礦石經常用於泰坦神殿。\n\n保護學家卡索斯一定會對這東西感興趣。>", progress = "有什麼發現嗎？", completion = "你找到雍亞拉塑像了！我想我不該這麼驚訝。\n\n我們必須把像這樣的文物送回它們原本的地方。但是，就像我的長官說的，我們不能讓它們落入錯誤的人手中。\n\n讓我檢查一下塑像。", rewards = "您會收到：\n\n雍亞拉塑像"}
MultiLanguageQuestData['tw'][77305] = {title = "踏入沙中", objective = "將不完整的石板送回去給保護學家卡索斯。", description = "<時佚碎片已經重組成石板，但上面的許多銘文都已磨損、缺漏。\n\n保護學家卡索斯應該會想看看。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77310] = {title = "夢境之龍的記憶", objective = "在伊瑟拉之眼休息", description = "在夢境中，記憶能以非比尋常的方式延續下去。記憶並非永遠都是線性的，而非你個人擁有的記憶也可以變成你的記憶。\n\n你會被引來這個地方，或許是因為過去的夢境之龍的關係，也或許是因為我偉大的朋友的關係。來吧，想看看嗎？\n\n在這裡休息，全心全意融入夢境的魔法。", progress = nil, completion = "幸好你在這裡，&lt;name&gt;。也許你可以幫我個忙？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77311] = {title = "治療幫手", objective = "使用重生根果協助治療葛瑞克斯。", description = "葛瑞克斯派人請伊瑟拉來見他。我們來到這裡，發現他情況危急。\n\n到目前為止，我們對他的治療毫無功效。不過，既然你來了，你可以幫我們一臂之力。\n\n葛瑞克斯源自夢境。或許將生長在這裡的某個東西注入他的根部，就是讓他恢復的最後關鍵。", progress = "葛瑞克斯的情況相當危急。我們必須盡我們所能幫助他。", completion = "我原本很確定我們幫得上忙。\n\n伊瑟拉似乎感應到這裡有我無法感知的外因。在她歷經磨難後，她的魔法似乎已經有所變化，完全超乎我的認知…", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77312] = {title = "自然延續", objective = "從卑鄙的魔花人身上收集6株萌芽的幼苗。", description = "無可否認，我不知道接下來該怎麼做。\n\n如果他在這裡安息…鮮花會是很好的祭品。\n\n這個地方的魔花人一直藏身在花海中。從它們身上取得種子，勇士，然後我會讓它們開花。\n\n我想葛瑞克斯會喜歡花的。", progress = "一定還有一些事是我們可以…\n\n不。伊瑟拉似乎很肯定。", completion = "發生這種事的時候，好像應該要鼓勵新生。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][77313] = {title = "肅穆的召集", objective = "通知葛瑞克斯的親朋好友。", description = "就跟我害怕的一樣。葛瑞克斯的時間到了。\n\n他的治療不會奏效了。彼世已經在召喚他。\n\n儘管他如此安詳，關心他的人卻仍無比悲傷。我們會一直記得他。\n\n並不是每個人都有道別的機會。\n\n但這次，我們必須確保他們有這個機會。", progress = nil, completion = "這個地方讓人覺得心平氣和。\n\n葛瑞克斯找我來一定有原因。他知道了。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][77314] = {title = "夢中輓歌", objective = "在葛瑞克斯周圍種植6朵花。", description = "一個生命結束，必然有另一個生命誕生。\n\n我們必須讓葛瑞克斯的親朋好友知道這件事，<name>。\n\n把種子種在葛瑞克斯周圍吧，剩下的就交給我姐姐。\n\n這個地方不僅象徵終點，也會象徵新生命的起點。", progress = nil, completion = "那些回憶…讓葛瑞克斯痛苦萬分。我們應該幫助他。", rewards = "您會收到：\n\n重生幼苗幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][77315] = {title = "遠古回憶", objective = "擊殺糾纏折磨。", description = "不能讓那些黑暗的回憶玷汙夢境。\n\n必須消除它們。葛瑞克斯必須克服自己的心魔。如果它們徘徊不去，就可能成為邪物。\n\n擊敗讓他最痛苦的回憶，讓葛瑞克斯得以安息。", progress = "在他的回憶平復之前，葛瑞克斯都無法真正安息。", completion = "謝謝你，&lt;name&gt;。葛瑞克斯終於可以安息了。\n\n那些在乎他的人，似乎也能得到慰藉。人們並非總是能再次得到道別的機會。", rewards = "您會收到：\n\n沉重的夢境種子葛瑞克斯的樹枝翡翠露珠"}
MultiLanguageQuestData['tw'][77316] = {title = "世界樹的麻煩", objective = "從木魈身上取回6個非常重要的樹木物資。", description = "<name>！麥琳瑟拉需要你的協助。\n\n有一些討人厭的搗蛋木魈跟著我們進到了夢境裡，現在它們引起了不小的混亂！\n\n更麻煩的是，它們還偷了我們機密且重要的補給品。\n\n情況危急，得靠你阻止它們，並搶回那些補給品了。", progress = "如果我們不把那些可惡的木魈偷走的物質拿回來，我們的進度就會嚴重落後！", completion = "真是鬆了一口氣！\n\n既然我們已經拿回那些非常重要的物資，我們在這裡的工作也能回到正軌了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77317] = {title = "戴著帽子睡覺", objective = "將6頂蠢帽子戴在夢境德魯伊頭上。", description = "我就告訴你一個秘密，這些木箱呢，其實是假的補給品啦！\n\n這裡的人還真嚴肅呢。還有什麼比一個小小的惡作劇更能打起大家的精神呢？\n\n你可以把這些搞笑的帽子戴到一些睡著的德魯伊頭上，還有什麼能比驚喜小帽更有趣呢？\n\n不過要小心他們與夢境的連結，因為什麼事情都有可能會發生！", progress = nil, completion = "很不錯嘛，我還以為你也被我騙到了！\n\n但看來你比與預期的還要更厲害…\n\n也許是時候來個真正的挑戰了。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][77318] = {title = "麥琳瑟拉說…", objective = "偽裝成麥琳瑟拉，對5個德魯伊下達指令。", description = "有一些德魯伊主動要幫助照顧樹木跟建好營地。\n\n但他們看起來好難過喔！\n\n<月莓女士露出了惡作劇的邪惡微笑。> \n\n我們有千百種理由讓他們樂一樂。你可以給他們下一些指令，提醒他們要好好放鬆一下。\n\n但他們絕對不會聽從你的命令。\n\n所以我幫你準備了這套裝扮。有了這個跟一個小小咒語，他們就不會不服從了！", progress = nil, completion = "你假扮麥琳瑟拉的表現還真是一絕！\n\n&lt;月莓女士爆笑。&gt; \n\n我都快不知道誰才是真的了！", rewards = "您會收到：\n\n沉重的夢境種子月莓女士的惡作劇工具備用的派對帽幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][77322] = {title = "撒塔斯城飄遊賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77325] = {title = "前往文庫！", objective = "到阿爾蓋薩學院與大文物管理員愛德威‧達凜格談話。", description = "你是學者、歷史學家，或是擁有遠大抱負的知識份子嗎？你喜歡不用動腦、只要幹粗活就能賺錢的工作嗎？\n\n掌握自己的未來，加入艾澤拉斯文庫新進人員的行列吧！*\n\n<你瞄到印刷在羊皮紙邊緣的一段小字。>\n\n*臨時辦公室位在北薩爪祖斯的阿爾蓋薩學院。", progress = nil, completion = "終於！他們總算派了個&lt;class&gt;把餐點送來了！\n\n啥…你是來加入文庫的嗎？抱歉抱歉！當然沒問題！\n\n不過如果你看到送東西的人，麻煩跟對方說一下這邊路怎麼走，好嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77327] = {title = "尼羅賓與辦公室", objective = "到尼羅賓在薩爪祖斯的辦公室與他談話。", description = "也許還有很多東西要調查，不過我需要時間先檢查我們的發現。\n\n我們同事尼羅賓，就是那個在總部秘法投影的人，現在應該需要你的幫助了。他在薩爪祖斯的學院有自己的辦公室，他通常都躲在裡面。\n\n我滿肯定他會在那裡的…他幾乎沒有離開過。", progress = nil, completion = "你是新人嗎？\n\n由於你遲到了，我只好假設你被外面的瑣事耽誤了…就像我那些不斷重現的惡夢一樣。\n\n我只能說，很高興見到你本人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77328] = {title = "回去總部！", objective = "到薩爪祖斯的阿爾蓋薩學院與愛德威‧達凜格會面。", description = "愛德威說我們結束之後…呃，我是指實驗之後，想請你回主辦公室一趟。\n\n我相信應該是跟表揚、儀式、獎勵之類的事有關。如果這些東西很吸引你的話，勸你動作要快，不然這些好東西很快就會分給我們找來的其他新人了。", progress = nil, completion = "蘿思卡跟岑娜塔都以為你跟其他人一樣只是想要錢。\n\n但我不這麼覺得！我以為你…呃，好吧。老實說我也以為你只是來賺錢的。\n\n算了，誰在乎啊！你做得很好，你就把這個成果當作成為艾澤拉斯文物管理員的契機吧。\n\n歡迎你加入團隊！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77329] = {title = "一場祥和的集會", objective = "在中央營地與泰蘭妲‧語風交談。", description = "如你所知，埃達希爾可不是一棵普通的樹。泰蘭妲‧語風和剩下的卡多雷已準備了自己的儀式來接納它，並建立新的月井。\n\n泰蘭妲一定希望你出席。\n\n我們在中央營地跟他們會合吧。", progress = nil, completion = "大家一直寄望著埃達希爾，我們好好迎接它的到來吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77331] = {title = "畢業日", objective = "從你的艾澤拉斯文物管理員同事獲得恭喜。", description = "看來你成為了我們高技術邋遢挖掘者團隊的稱職成員了。\n\n不論是你和蘿思卡、岑娜塔和尼羅賓一起破土動工的挖掘場，或是背叛者之眠的大型遺址，從巨龍群島收集到的各式歷史資料從來沒有這麼完善過。\n\n只要你願意，永遠會有工作和夥伴等著你。希望你也願意加入我們在其他大陸的工作。\n\n…我是指，等我們收到足夠贊助以後。", progress = nil, completion = "向你致敬，&lt;name&gt;！\n\n敬你的支持、探索精神以及對歷史的關懷！\n\n願所有渴望學習的人都能找到這樣的歸屬和朋友！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77339] = {title = "恢復資料", objective = "前往提爾的衛士總部，跟崔瓦會面。", description = "在激烈訓練一陣子之後，這一刻總算來了！崔瓦認為提爾的衛士已經準備好要從暗夜堡取回提爾的圓盤了。\n\n來提爾堡南邊的提爾安息地找我們吧，那裡可是提爾的衛士新總部呢。\n\n我們終於能讓提爾復活過來了！", progress = nil, completion = "你在這裡呢，&lt;name&gt;。準備好取回圓盤了嗎？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77340] = {title = "潛入暗夜堡", objective = "到暗夜堡從艾莉珊德手中取回提爾的圓盤。", description = "我們從信標得知，艾莉珊德把圓盤深鎖在星術師高台。\n\n那個是專門用來學習的地方，所以只會有一點點防護措施。我已經把傳送門開在你和提爾的衛士最不會遇到阻力的地方…但你們還是會遇到艾莉珊德還有她的守衛。\n\n你們所有人到那邊之後，就得靠你們自己，所以別把這件事搞砸了。", progress = nil, completion = "我很高興大家辦到了，&lt;name&gt;！我們拿到圓盤跟白銀鱗片，這樣就能重鑄提爾了。太好了，我們來復活提爾吧！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77341] = {title = "意義療法", objective = "在提爾安息地與提爾談話。", description = "親愛的$p，\n\n雖然這麼說強大的提爾好像不太好，但我十分擔心他。在他剛抵達提爾安息地的時候，他花了好幾天的時間與大家交談。我們問了他好多問題，關於泰坦、遠古歷史，還有他對事情的看法。\n\n但最近，提爾的話變少了，回答我們的問題也越來越簡短，甚至帶著不愉快的感覺。\n\n我不知道哪裡出了問題，但似乎不太對勁。你能來與他談談嗎？\n\n為了提爾，\n薇勒內", progress = nil, completion = "&lt;name&gt;，我希望我們可以尋找到我們重鑄的遠大目標。提爾，還有提爾的衛士都是。\n\n也許那個尋找的過程，就是我們人生冒險的下一步。", rewards = "您會收到：\n\n提爾的衛士外袍龍石"}
MultiLanguageQuestData['tw'][77342] = {title = "圓盤快遞", objective = "把提爾圓盤放到泰坦控制臺裡。", description = "你取回了圓盤？\n\n太好了，終於可以喚醒提爾了。\n\n必須把圓盤放到控制臺與白銀鱗片同調，然後再交給提爾。\n\n$p，我認為這份光榮的差事非你莫屬。", progress = nil, completion = "提爾再次與我們同在。真不敢相信，&lt;name&gt;，謝謝你。", rewards = "您會收到：\n\n提爾的衛士的回憶紀錄龍石"}
MultiLanguageQuestData['tw'][77343] = {title = "與提爾的團聚", objective = "聆聽守護巨龍與提爾之間的談話。", description = "能在好幾千年後見到好友回來，實在是太不可思議了。自我們上次的談話之後發生了好多事。\n\n這個世界變了。我們失去提爾可是比大崩裂還要更久遠之前的事呢。不過，之後還有時間可以細談那段往事。現在，只要能跟朋友好好聚一聚就很棒了。$p，你能在我們敘舊的時候陪著我們嗎？", progress = nil, completion = "&lt;name&gt;，我實在不敢相信我們能活到這一刻。過去那麼多年為了提爾的衛士犧牲奉獻、看著他們為守衛提爾墳墓逐漸消亡，而現在，他本人跟衛士再次重現於世了！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77344] = {title = "花點時間好好消化", objective = "在提爾安息地邀請提爾和提爾的衛士一起。", description = "提爾過了幾千年後回來了。要說有幾千我也不清楚。他所知的世界已經變了許多，他也一定有許多問題迫切需要解答。\n\n於此同時，提爾的衛士只想跟提爾說話。提爾安息地似乎是個能給他一點時間、回答問題，還有消化答案的好地方。你可以請他到那邊跟我們會面嗎？", progress = nil, completion = "能直接與提爾對話的感覺實在太好了。我們有許多事想跟他說，同樣，我們也有許多問題等著他回答。\n\n謝謝你的協助，讓這一切得以成真，&lt;name&gt;！", rewards = "您會收到：\n\n巨龍群島飛龍：白鱗龍石"}
MultiLanguageQuestData['tw'][77345] = {title = "快還要更快", objective = "飛行通過檢查環，然後在目標地點降落。", description = "有時候你會旅行到比較遠的地方。\n\n如果你要維持前進速度，又不想向上飛行或是飛越障礙物的話，向前疾衝是最簡單的方式，同時也可以防止自己突然高飛。\n\n再次沿著檢查環抵達目的地，然後跟隨提示使用向前疾衝來維持速度。\n\n如果你卡住的話，可以使用青銅計時器，讓賽洛姆幫你重置。", progress = nil, completion = "做得好。接下來就只需要多加練習了。", rewards = "您會收到：\n\n"}
