MultiLanguageQuestData['tw'][77377] = {title = "前往提爾堡！為了提爾！", objective = "前往提爾堡跟伊特努斯交談", description = "我們復原了傷痛。我們歷經了許多的訓練。而現在終於要面對艾莉珊德了。\n\n跟我們一同到提爾堡吧，諾茲多姆、克羅米和伊特努斯都在那裡等著要把我們送往暗夜堡呢。\n\n我們一定會取回圓盤，而提爾終於能再次回到我們身邊了。", progress = nil, completion = "你確定自己準備好，可以前往暗夜堡了嗎？\n\n你真的明白接下來要面對這位「艾莉珊德」嗎？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77398] = {title = "秘境遊旅賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77399] = {title = "秘境遊旅賽道 - 進階", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
