MultiLanguageQuestData['tw'][77408] = {title = "煩心的預言", objective = "使用傳送水晶登上梵迪卡爾與預言者費倫會面。", description = "預言者費倫已從冥想中甦醒，並請你立即跟他會面。\n\n有件重要的事吸引了他的注意。你的超凡智慧與強大能力絕對能幫他解決問題。\n\n預言者等你登上梵迪卡爾會面。\n\n帶上這顆水晶吧。我們的工藝師已讓它跟船艦上的傳送矩陣同調了。", progress = nil, completion = "&lt;name&gt;，別害怕。這次情況並不嚴重。\n\n其實，我現在還覺得…有一絲希望。但我還是有些擔心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77409] = {title = "不確定性", objective = "到克庫恩與哈圖恩族長交談。", description = "我在冥想時看到了片段的畫面。黃色與紅色、破碎的玻璃、突然的溫暖，我看到了自己的手，但我不敢抓住。我還聞到了魔能…是阿古斯的氣息。\n\n我甦醒之後，有人傳了口信給我。哈圖恩族長想跟我會面。\n\n燃燒軍團失敗以後，我提議讓哈圖恩跟他的人民能重新加入我們。但是，他們選擇繼續待在阿古斯。\n\n從那以後，哈圖恩便很少與我們接觸。也許他回心轉意了。\n\n我之後會去克庫恩。屆時，還請你跟我一同前往。", progress = nil, completion = "我們就看費倫是否兌現了他承諾過的協助吧。\n\n這次沒有什麼事情能夠阻止他了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77410] = {title = "揭開瘡疤", objective = "與阿爾札卡談談，聽聽他有什麼想說。", description = "阿爾札卡是我底下的獵人找到的。他們說他幫助他們抵禦好幾次的燃燒軍團伏擊。\n\n我們長期在阿古斯守夜，從未見過這樣的事。雖然他不像某些惡魔那般強大，但他的意志十分堅定。\n\n他說他想跟費倫談談，也知道我們跟他有聯繫。於是，我便答應他的請求。\n\n如果費倫真是他口中描述的那個樣子，就算對他的族人再怎麼不利，他也不會拒絕的。\n\n我們拭目以待吧。我不抱太大的期望就是了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77411] = {title = "悔悟", objective = "前往那洛亞林地跟阿爾札卡會面，然後殺死代言者納黎登，並取回上古德萊尼水晶。", description = "自燃燒軍團覆滅後，曼那瑞越來越絕望。有些不顧一切爭奪權力。有些決定與世隔絕。也有些組織了教派等待薩格拉斯回歸的那一天。他們深信，他有朝一日會再次領導他們。\n\n納黎登是其中一個教派的領導者。這個教派的活動十分隱密，但據說他手上有基爾加丹守到人生最後一刻的遠古神器。納黎登聲稱可以用這來與薩格拉斯溝通。\n\n我可能知道這件神器。如果沒錯的話，那東西必須還給費倫。", progress = "就算我死在這裡，至少不會是燃燒軍團一時興起的結果。", completion = "完成了。\n\n成功剷除一股邪惡勢力。\n\n這便是我殷切盼望的。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77412] = {title = "證據與承諾", objective = "到克庫恩把光輝之星交給預言者費倫。", description = "增援不太可能，不過弄丟這件文物實在過於冒險。你應該立即帶著它回去找預言者費倫。\n\n前面就有傳送門，我會把它跟我自己的符印同調，好讓你快速通過。\n\n我之後會再跟你會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n飛龍暗焰紋章碎片謙遜之鏡龍石飛龍夢境紋章飛龍覺醒紋章"}
MultiLanguageQuestData['tw'][77414] = {title = "調查夢境湧現", objective = "在夢境湧現中完成活動。", description = "<name>，翡翠夢境的能量流入艾澤拉斯這種事情是前所未見的。如果要對事態發展做好準備，我們就得把這個現象影響的層面研究清楚。\n\n也許我們有機會把它變成我們的優勢呢。\n\n前往受影響的區域，看看你能有什麼收穫。把任何有意思的東西帶回來，我們會看看能怎麼做。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n縛夢護甲箱"}
MultiLanguageQuestData['tw'][77415] = {title = "隱秘之手", objective = "從角蛙的寶藏堆找出奈薩里奧使者的物品。", description = "要在他落單的時候抓嗎？牠們一定就在附近看著，只是我們看不到罷了。你可以過河看一下那個洞穴嗎？\n\n那些角蛙可是出了名的囤積者。如果那些龍獸有拋下了什麼東西。一定就在這裡。", progress = "你有查看那個洞穴嗎？", completion = "你有什麼發現？", rewards = "這個任務線能解鎖：\n\n艾澤拉斯文庫：禁忌之境，龍顱島挖掘場\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][77417] = {title = "造就恆龍的秘密", objective = "看看伊特努斯想揭露什麼事。", description = "顯然伊特努斯有些事想讓我們知道。我不確定這次談話會有什麼結果。\n\n但我相信克羅米。如果她深信可以動搖伊特努斯，那我相信她的評斷。\n\n你準備好之後，我會去聽她想說些什麼。", progress = nil, completion = "所以失去了妹妹莫萊多米是一切的根源…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77423] = {title = "湧動夢境", objective = "與正在調查夢境湧現的德魯伊見面。", description = "<name>，改變即將到來。那些與翡翠夢境有所連結的生物，都已有所察覺。\n\n若要仔細了解這個改變，我們需要你的幫忙。\n\n我們到受影響的地區會合，到時候再擬定計畫。", progress = nil, completion = "這個初生的「夢境湧現」現象，對我們所有人都有影響。還有很多需要調查的地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77424] = {title = "研究：禁忌之境半龍人", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77425] = {title = "刀槍不入的鱗片", objective = "在薩克利軍需官附近搜尋巨牙海民的交易記錄。", description = "加拉登與巨牙海民交易魚叉？就我所知，魚叉是沒辦法刺穿龍麟的。\n\n你覺得這批貨量有多大呢？搜查附近的薩克利軍需官，看看他們有沒有留一些過去的紀錄。", progress = "我知道加拉登平常不太會留紀錄，但這附近一定有什麼線索…", completion = "你回來了！應該有好消息吧？", rewards = "這個任務線能解鎖：\n\n艾澤拉斯文庫：扎拉萊克洞窟，伊吉拉崗哨挖掘場\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][77429] = {title = "熟能生巧：波西德里思", objective = "協助波西德里思滑翔通過檢查環。", description = "想要獲得更好的成績嗎？\n\n：往上飛，然後恢復1點活力。\n：使生命之風的持續時間延長5秒。\n：每次恢復活力時，都會向前衝刺。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77433] = {title = "挖掘：河床", objective = "到雍亞拉平原的河床挖掘場地與蘿思卡‧岩牙會合。", description = "雍亞拉平原莫魯凱附近的河床流傳著關於一支失蹤商隊的傳說！\n\n盡快去那裡找我！記得穿上你最不怕弄髒的舊靴子！", progress = nil, completion = "我們用這個發現震撼半人馬的世界吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77434] = {title = "高科技占測：觀測所", objective = "到甦醒海岸的和睦觀測所與岑娜塔會面。", description = "我的探尋杖一直指向甦醒海岸懸崖上的龍獸遺跡。\n\n不知道我們會找到什麼，但質疑我的發明可不太明智，因為我的發明每次都會有97%的正確機率。\n\n向來如此。", progress = nil, completion = "我們來一窺這些搖動石頭的過去吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77436] = {title = "燃燒獸穴", objective = "在索斯利爾獸穴附近尋找泰蘭妲。", description = "菲拉卡的部隊早已在執行計畫了。他們總是搶先我們一步，如果要好好保護埃達希爾的話，我們的動作就要加快了。\n\n在你前來此地的路上，我們收到情報，有可疑身影進到附近獸穴裡。泰蘭妲已經動身前往調查了。去找她並提供協助吧。", progress = nil, completion = "&lt;class&gt;，你來的正是時候，我正需要幫手。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77437] = {title = "紀元邊境", objective = "到紀元邊境找酒保鮑伯。", description = "時光行者節奏和他的小隊終於解除紀元邊境的封鎖了！\n\n呃…幾乎啦。時光行者已經大致把情況控制住了，不過紀元邊境的居民還面臨一些問題，期待有人出手相助。\n\n告訴鮑伯，是我派你去的！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77483] = {title = "高科技占測：龍顱島", objective = "到禁忌之境的龍顱洞穴與岑娜塔會面。", description = "我調整了我的半龍人文物感應器，它們已經在禁忌之境三角定位出一個新地點，供我們調查。\n\n當地的龍獸說那裡叫做龍顱島。聽起來很不吉利對吧？你應該不太容易被嚇到吧？", progress = nil, completion = "我的初步感應器在靠近洞穴入口的時候就達到峰值了。我們找的東西應該就在裡面。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77484] = {title = "高科技占測：伊吉拉崗哨", objective = "到扎拉萊克洞窟的伊吉拉崗哨與岑娜塔會面。", description = "我的感應器顯示，扎拉萊克洞窟地表下有一個有趣的遺址。\n\n這次探勘最好帶武器，我的初步偵察顯示，可能有大量熔岩跟加拉登。", progress = nil, completion = "他們看起來很願意放過這座洞窟，對吧…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77486] = {title = "挖掘：奈薩里奧之視", objective = "到扎拉萊克洞窟的奈薩里奧之視與蘿思卡‧岩牙會面。", description = "我的一個鼴鼠人同事私底下給了我關於一座地下高塔的情報。這座破舊的高塔恰好位在扎拉萊克的正中央，介於洛姆、加拉登地盤和恐怖的奈薩里奧實驗室的交界地。\n\n帶上你最順手的鏟子，去那裡跟我會合！", progress = nil, completion = "我們來模仿鼴鼠人，嗅出被埋藏的歷史吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77487] = {title = "挖掘：飛翼長駐營", objective = "到禁忌之境的飛翼長駐營與蘿思卡‧岩牙會面。", description = "我們在禁忌之境發現了一座古老的漁村！位置就在西北邊海岸附近一座不起眼的小島，上頭有一座破橋和所有東西！\n\n如果你還有東西想挖，就到那裡找我！", progress = nil, completion = "&lt;name&gt;！你辦到了！\n\n海風真的喚醒你了！", rewards = "您會收到：\n\n"}
