MultiLanguageQuestData['tw'][77697] = {title = "正確的肥料…", objective = "為植物施肥。", description = "<這株植物現在生機勃勃，這都要歸功於你的細心照料。\n\n近距離觀察植物的葉子後，你發現表面上充滿露水。也許正確的肥料可以進一步幫忙這株植物。>", progress = nil, completion = "&lt;幼苗周圍的土壤散發淡淡的光芒。&gt;", rewards = "您會收到：\n\n龍石"}
