MultiLanguageQuestData['tw'][77762] = {title = "微小的希望從不會毫無價值", objective = "與亞許教授談話。", description = "這株植物發育成熟且生機勃勃。現在我們生態系統的這一小角復原了，並且得知你所做的一切之後，我們終於等到了心中期待的景象：夢爪獸帶著牠們的幼獸回來了！\n\n如果你願意接受的話，有隻心懷感激的成年夢爪獸想為你效力。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n沉重的夢境種子赭色夢爪獸韁繩精心培育的花朵幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][77763] = {title = "不尋常的發現：溼透的帳本", objective = "到薩爪祖斯的阿爾蓋薩學院，把溼透的帳本交給愛德威‧達凜格。", description = "<這本皮革封面的帳本已被水浸濕到書頁差點要分家了。\n\n多數文字皆難以辨識，但看得出來是用遠古龍類的方言寫成。似乎是在記錄一筆又一筆的日常物品，後面還記有各自的數量…這會不會是家庭帳簿呢？\n\n愛德威一定知道要如何保存這個發現，並找出原本的主人是誰。>", progress = nil, completion = "啊哈！是個不尋常的發現。我會馬上跟相關人士請教，這樣我們就可以把它歸檔，並盡速送回原處。", rewards = "您會收到：\n\n神秘碎片"}
MultiLanguageQuestData['tw'][77765] = {title = "記錄夢境", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77766] = {title = "不尋常的發現：打孔的巴卡犬牙齒", objective = "到薩爪祖斯的阿爾蓋薩學院，把打孔的巴卡犬牙齒交給愛德威‧達凜格。", description = "<雖然發黃的污漬顯示這東西有千年之久，但這是一顆年幼巴卡犬的乳牙。\n\n有人很仔細地在牙齒的頂部鑿了一個洞把它做成串珠。經過進一步檢視後，仍可以看到穿過那個小洞的破爛毛繩。\n\n愛德威一定知道要怎麼收藏這個發現，並找出原本的主人是誰。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n神秘碎片"}
MultiLanguageQuestData['tw'][77779] = {title = "湯瑪斯爵士的故事", objective = "回去找孤兒監護員。\n\n已提供物品：\n", description = "蘇珊娜…沒想到我還能跟她。現在我們可以回去找孩子，然後好好休息了。<name>，這都得感謝你。\n\n你還留著我的秘典嗎？我的故事就此告一個段落，但我想要親自把它寫下來。\n\n<湯瑪斯的手指撫過空白的書頁，有個神奇的墨水正將他的話語全都記下來。>\n\n請把這個交給孤兒監護員，如果可以的話，也請你代我向她道歉，不好意思嚇到她了。", progress = nil, completion = "就是這樣。無頭騎士再一次被擊敗了，墮落的聖騎士終於重獲自由也得以安息。\n\n聽被遺忘者訴說天譴軍團對羅德隆帶來的浩劫，任何人都可能因此陷入瘋狂。然而，這位聖騎士的力量和對家人的奉獻從未減少，應該值得尊敬。\n\n謝謝你，&lt;name&gt;。你對那個可憐靈魂的憐憫令人敬佩，實在感激不盡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77780] = {title = "見證綻放", objective = "前往雍亞拉平原的遠古枝幹與麥琳瑟拉交談。", description = "埃達希爾已將它的枝葉伸向夢境之外。\n\n就讓我們前往巨龍群島，看看這棵世界之樹在何處扎根吧。", progress = nil, completion = "&lt;麥琳瑟拉的神情為之一亮。&gt;\n\n勇士，我們可是艾澤拉斯頭幾個人在此見證埃達希爾呢。這實在是個特別的一刻。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77781] = {title = "不同的興趣", objective = "在貝拉梅斯使6個木魈搗蛋鬼現形。", description = "我發現慶祝活動引來一些亞登曠野木魈的注意力。他們可是有著不同習性的…奇怪生物。\n\n他們的惡作劇已讓人不堪其擾。請把他們找出來好讓慶祝能夠順利地進行下去吧。", progress = nil, completion = "&lt;name&gt;，謝謝你，我欣賞他們的活力，但今晚他們並沒有列在貴賓名單上。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][77788] = {title = "灰燼水仙研究筆記", objective = "收集燼火花粉的樣本。", description = "<你在殺死的德魯伊身上找到了燒焦的研究報告。\n \n報告上寫的是火焰德魯伊進行的實驗內容。\n\n你發現了他們創造了一種特殊的花粉，還能夠為夢境的植物灌注他們的火焰魔法。他們下一階段則會對當地的野生動物使用相同的花粉。\n \n寇祖一定會想知道花粉樣本和報告的內容。>", progress = "<寇祖居高臨下的看著你，慢慢眨眼。>", completion = "那…實在是太乏味了。煤煙與灰燼，一成不變？\n \n&lt;寇祖晃了晃他巨大的頭顱。&gt;\n \n不，我不喜歡。", rewards = "您會收到：\n\n可怕的研究筆記灰燼水仙研究筆記龍石"}
MultiLanguageQuestData['tw'][77789] = {title = "切斷羈絆", objective = "殺死10名曼那瑞教徒，並使5個薩格萊導體超載。", description = "納黎登召集了一個小小的教徒軍隊。他們深信他能透過古物為薩格拉斯傳話，而且也對他所說的字字句句都深信不疑。就跟薩格拉斯來到阿古斯時，我們緊緊跟隨我們的領袖一樣。那是一種慰藉。一股希望。\n\n但最終，剩下的卻是謊言的空殼。\n\n但他的追隨者並不相信自己受到了欺騙。他們已經在這個區域中建造了自己的導體，試圖操控古物的力量。讓自己也能聽到聲音。\n\n他們會阻止我們。我們必須從中殺出一條血路。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77791] = {title = "處理：共生發光孢子握把", objective = "去雍亞拉平原尋找艾登。", description = "我認識一個可以幫忙冶煉菲拉雷斯的工匠。席卡氏族的艾登擁有相當充裕的資源。他曾對巨龍群島各地的各種材料進行許多實驗。\n\n一把好武器才能成就一名好獵人。艾登之所以有名，就是因為他擅長用奇特的材料製作神兵利器。他對各種動植物的知識也很豐富，絕對能派上用場。", progress = nil, completion = "我知道了。\n\n那把斧頭握起來絕對是一大痛苦。讓我想一下。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77794] = {title = "清晰夢境獎勵", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77795] = {title = "搜刮來的神器", objective = "如果你有補給品的話，我可以跟你用物品交換。雖然老舊，不過是很神聖的東西呢。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n復原埃雷達爾文物\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][77802] = {title = "該怎麼稱呼你？", objective = "到根縛聖域與戴歐尼莎交談，選擇一個稱呼。", description = "守護者！還是該叫…老師！監護人？\n\n我想知道該怎麼稱呼你。由於我自己一個人在花園工作，其他林精都會問我我的德魯伊是誰。\n\n我想告訴她們，我沒有德魯伊。我只有你！\n\n請告訴我你想要我怎麼稱呼你。", progress = nil, completion = "非常棒的稱呼！我找到機會就會用一下。\n\n謝謝你。", rewards = "您會收到：\n\n林精之女頭冠"}
MultiLanguageQuestData['tw'][77813] = {title = "閃電之擊", objective = "到天頂觀測所找安德斯塔茲領主。", description = "<振翅靈獸轉了一圈，並將滿是口水的紙條交到你手中。>\n\n啊，<name>。我聽說你取得了很棒的新坐騎。而且是個能在雷電交加的空中翱翔的獅鷲獸！\n\n我很想看看這奇幻的生物都是怎麼飛翔的。我會在天頂觀測所等你前來。", progress = nil, completion = "嗨，又見面了，&lt;name&gt;。現在，我們來看看這獅鷲獸吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77815] = {title = "風暴競速巡迴賽", objective = "飛過巨龍群島的每場風暴競速比賽。", description = "這風暴獅鷲獸還真是迷人！不管是什麼樣的環境孕育了這樣的生物，都值得進一步探索。\n\n但既然你都來了，我們是該試試牠的能耐，還有你的騎術了。\n\n我的青銅龍夥伴已經搭好了新賽道來測試坐騎的能力。當時空守衛者看到你騎著獅鷲獸時，就會給你機會在這些「風暴競速」中一展身手。\n\n幸運會眷顧那些英勇無畏之人，$p。祝你好運！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n套裝：雷霆風暴飛騎裝束"}
MultiLanguageQuestData['tw'][77818] = {title = "殘暴者", objective = "協助麥琳瑟拉關閉火焰傳送門。", description = "洪荒使者、加拉登和火焰德魯伊在聯手對付我們。\n\n但我可以感覺到還不只這些勢力。有一股強大的力量試著想要穿過這個傳送門。讓我們盡可能地把他們封鎖在外吧。", progress = nil, completion = "很高興你逃出來了。我們不得不在菲拉卡的部隊抵達以前，從大樹那邊撤退。\n\n卡莎芬長老恐怕已經…消逝在這預言之火當中了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77822] = {title = "泰坦模具", objective = "到沃卓肯將泰坦鑰匙模具交給武器鍛造師科雷夫。", description = "<泰坦鑰匙模具就在故事裡面提到的地方。武器鍛造師科雷夫一定很期待看到這個模具！>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77829] = {title = "重鑄傳奇", objective = "在黑曜區中找到武器鍛造師科雷夫。", description = "你來了！武器鍛造師科雷夫在找你。還留了張字條給我，請你到黑曜區找他。\n\n聽起來像是你在幫他打造遠古泰坦鑰匙？記得來跟我分享進度！這真是一大頭條新聞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n泰坦鑰匙材料清單"}
MultiLanguageQuestData['tw'][77831] = {title = "重鑄之鑰", objective = "協助武器鍛造師科雷夫重鑄泰坦鑰匙。", description = "你有最後的材料了吧！太好了！\n\n我已經把熔爐跟模具準備好了。我只需要你等我指示，再加入材料。\n\n對了，別忘了用派瑞斯的火炬，那東西似乎在過程中相當關鍵，我會告訴你使用的時機！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n提爾的泰坦鑰匙"}
MultiLanguageQuestData['tw'][77833] = {title = "處理：濃縮授智皮紙", objective = "去雍亞拉平原尋找夏菈莎‧光暮。", description = "我認識一個可以幫忙冶煉菲拉雷斯的賢者。夏菈莎‧光暮是個很有學問的專家，經常思索控制危險魔法的理論。很少有人像她一樣那麼有智慧。\n\n尋求她的協助來操控暗焰吧。我想她的解決方案或許會需要用到一些炫彩之塵！", progress = nil, completion = "啊，沒錯！謝謝你不遠千里而來。\n\n有人曾告誡我，不要離群索居，不過，我知道隱居在如此蠻荒偏僻的地方，有一天也會有意想不到的好處。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77835] = {title = "處理：影縛符文", objective = "去蒼藍高地尋找莉迪亞菈‧語羽。", description = "莉迪亞菈‧語羽是個理解世界既定規律的學者。但她也很喜歡扭曲這些規則。\n\n能夠協助結合菲拉雷斯的力量的人，非她莫屬。", progress = nil, completion = "你想要束縛暗焰？太危險也大太大膽了吧！我們來試試吧。\n\n我一直在研究翡翠夢境中的植物。研究這個地方奇特、夢幻的植物，真的很容易讓人分心，不過，我見過一種植物，或許能給我們一些解答。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77838] = {title = "破碎的幻夢草", objective = "完成繁盛綻放期間的事件。", description = "你應該還不熟悉幻夢草的性質。\n\n完成繁盛綻放期間的事件就可以獲取關鍵知識，讓你能協助盟友。", progress = nil, completion = "暗影幻夢草依舊令人費解，但希望你的盟友仍用得上這些知識。", rewards = "您會收到：\n\n復原的幻夢草"}
MultiLanguageQuestData['tw'][77839] = {title = "東部王國杯巡迴賽", objective = "完成入門級東部王國杯的賽道。", description = "又要來試試你的能耐了。\n\n我的青銅龍同事已經前往東部王國打造更多全新競速挑戰了。那裡有許多賽道等著你去挑戰。\n\n準備好了嗎？", progress = nil, completion = "不愧是馭天者中的佼佼者！東部王國杯的賽事會持續舉行，去那裡參加其他賽事，證明你確實略勝一籌。", rewards = "您會收到：\n\n艾澤拉斯騎士徽章"}
MultiLanguageQuestData['tw'][77840] = {title = "東部王國杯正式開打", objective = "到沃卓肯拜訪安德斯塔茲領主。", description = "馭天者！你剛好跟安德斯塔茲領主錯過了。他正在招募像你這樣有實力的馭天者，去參加新的賽事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
