MultiLanguageQuestData['tw'][77869] = {title = "回到回音群島", objective = "到回音群島與洛克漢見面。", description = "<name>，回音群島出事了。洛克漢派人來尋求援助。\n\n暗矛部族需要你。", progress = nil, completion = "&lt;name&gt;，真高興你能來。有麻煩了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77871] = {title = "古老羅亞", objective = "聆聽伯昂撒姆第給暗矛食人妖的訊息，並想出解決辦法。", description = "伯昂撒姆第不會無緣無故親自拜訪。先聽他說完。\n\n然後我們思考對策，採取行動。", progress = nil, completion = "暗矛部族向來都會崇拜好幾位羅亞，但繆薩拉？我們有更好的選擇。\n\n我們該做的事很明顯了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77874] = {title = "往昔的羅亞", objective = "製作正確的咒像，尋找能找出其中一名失落羅亞的嚮導，然後跟著嚮導行動。", description = "我們必須找到古老羅亞，把他們召喚回來。一定有辦法可以找到他們去了哪裡。\n\n如果我們能找到古老羅亞，就能舉行羅亞試煉，重新連接他們的力量。\n\n伯昂撒姆第說他們依然在外遊蕩。我覺得這可能是個線索…", progress = nil, completion = "我感覺到有人正盯著我們，在打量我們。這個羅亞很聰明，但我們也不差。\n\n我們繼續吧。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77877] = {title = "與羅亞同行", objective = "與凱弗對話，讓他帶你進入莫什奧格巨魔山。", description = "盧考的碎片分散各地。\n\n但她的心臟在巨魔山的深處。\n\n暗影可以安靜、迅速地指引我們到那裡。等你準備好再跟我說。", progress = nil, completion = "那還真是…不一樣的體驗。我覺得有點反胃！\n\n但我們還有正事要辦。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77878] = {title = "寒冬特使", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77879] = {title = "追蹤潛獵者", objective = "收集6個獻給哈卡的祭品以吸引羅亞。", description = "如果這位羅亞在這裡狩獵，那他可能已經看見我們了。既然我們還不確定，那就分頭行動吧。\n\n我來追獵他，你來吸引他的注意力。迦尼說這位羅亞一直拿走本來要獻給『血之羅亞』哈卡的祭品。\n\n但我們不知道原因。收集一些祭品，看看他會不會想來搶。如果他另有動機…那我們很快就會知道了。", progress = "<凱弗亞西帝正在檢視你的祭品。>", completion = "&lt;凱弗亞西帝一言不發地收下祭品。&gt;\n\n我奪走這些祭品不是為了我自己。拖延哈卡的回歸對大家都好。\n\n光是記住還不夠。你的狩獵現在正要開始。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77880] = {title = "尋找盧考", objective = "詢問有關盧考的情報並跟著線索找到她。", description = "這裡是凱弗亞西帝最後感知到盧考的地方。\n\n我們要在附近收集情報，看看有沒有人知道她去了哪裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77881] = {title = "還有另一位", objective = "前往班姆巴拉尋找盧考。", description = "如果這和繆薩拉有關係的話…那我會幫忙。但要進行足以驅趕繆薩拉的羅亞試煉，我們需要另一名羅亞。\n\n我們的羅亞姐妹也失蹤了。我和她原本是搭檔，但後來我們因理念不合而分開。盧考是重生羅亞。她是最適合與死亡抗衡的羅亞。\n\n我欠她一個道歉。既然你來了，我想現在正是時候。\n\n我最後一次感知到她的存在是在班姆巴拉的小聚落附近。我們在那裡會合吧。", progress = nil, completion = "這個地方跟我記憶中的不一樣。\n\n我沒有感知到我們的姐妹。我必須再更靠近她一點。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77882] = {title = "失竊但不失落", objective = "在莫什奧格巨魔山周圍收集8個祭壇碎片。", description = "這個祭壇缺了很多部分。我們要在盧考回歸之前修好它，否則她會發怒的。我們必須讓盧考看見我們支持她。", progress = "能找到的碎片越多越好。", completion = "都到手了嗎？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77885] = {title = "夢境守望者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77886] = {title = "處理：暗影幻夢草", objective = "完成繁盛綻放的目標，採集暗影幻夢草。", description = "當菲拉雷斯的力量達到極限時，你就會需要一個能讓它冷卻下來的握柄。就像是當一隻野獸衝向你時，你必須站穩自己的腳步：隨著戰鬥逐漸升溫，你必須想辦法保持專注。\n\n產自巨龍群島的各種皮革都有冷卻的作用，不過，我知道有種材料更好。定期暴露在暗焰中的樹葉，將會是整合所有組件的最佳選擇。我們來採集你需要的材料吧。", progress = "你找到我們需要的東西了嗎？", completion = "非常好。\n\n只要狩獵的時間夠久，獵物永遠會手到擒來。很高興我們準確找到你需要的東西。", rewards = "您會收到：\n\n原型幻夢草握把"}
MultiLanguageQuestData['tw'][77889] = {title = "熾熱的提案", objective = "從翡翠夢境的火元素身上收集10個熾炎精華。", description = "啊，你好！\n\n我最近一直在跟幾位雕銘師合作。我們正在開發新型墨水。有點像是火焰墨水，不過更加熾熱！\n\n我們需要火元素身上的熾炎精華，而火元素目前正在攻擊夢境。我想這會是所謂的「雙贏」局面。\n\n請把它們的精華交給我在埃達希爾的助手。", progress = "新知往往來自你最意想不到的地方！", completion = "啊，好極了。我會轉交下去。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][77891] = {title = "修理夢境", objective = "啟動8個研究信標", description = "工程學與科學就像是一體兩面！每當有東西爆炸，那其實都在工程師的計畫之中。\n\n夢境則十分曖昧，尤其是翡翠夢境！總有一天，有人會要工程師把夢境修好，但我們完全不知道該怎麼做。我們需要更多情報，以便了解我們的處理目標！\n\n前往夢境，將研究信標放在我指定的地點。它們會收集必要情報，供日後維修使用。如果你想迅速找到地點，可以使用這個便利的傳送裝置。", progress = nil, completion = "得到好多有關夢境的實用資料，這夠工程師忙上好幾年了。", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][77892] = {title = "極有價值的珍珠", objective = "收集10顆沙耀珍珠", description = "當埃達希爾的樹根延伸到水中時，許多罕見生物紛紛從深海冒出，在夢境各地成長繁衍。\n\n其中一種罕見生物是沙耀蚌殼，能夠孕育魔法珍珠！\n\n看看你能不能找到這些蚌殼，從中獲得珍珠。", progress = "你找到珍珠了嗎？", completion = "太驚人了，&lt;name&gt;，這些珍珠蘊藏極大的力量。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][77894] = {title = "盧考之心", objective = "在祭壇召喚盧考並與其對話。", description = "我本來想找到更多碎片，但有多少算多少，對吧？\n\n呼喚盧考來到這座祭壇。希望她會回應。", progress = nil, completion = "&lt;name&gt;，謝謝你的幫忙。我沒有傷得很重。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77896] = {title = "尋找沉睡的人", objective = "查看沉睡的德魯伊的情況。", description = "在我們對抗菲拉卡部隊的過程中，我的一群德魯伊同伴跑去尋找安靜又安全的睡覺地點。但是，隨著菲拉卡的部隊逐漸逼近他們的位置…\n\n我必須開始規劃另一次攻擊，所以有點分身乏術。\n\n我上次看到他們前往南方，進入海岸旁的洞穴。拜託你，我必須確定他們安全無虞。", progress = nil, completion = "菲拉卡的部隊攻擊我們了嗎？\n\n如你所見，他們根本還沒打到這裡。\n\n不過，我目前的確有更嚴重的問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][77897] = {title = "特別的書", objective = "嗯，這都要感謝我那值得信賴的調查員。\n\n祈倫托有個人還欠我人情。他告訴我卡拉贊有一本書也許能幫助我們解讀你發現的那些石板上的文字。你知道的啊，就是在蒼藍高地和時光沙地找到的那些石板啊？\n\n但我們都深知，只有你才有尋物的高超本領。這是我的線人留下的筆記。你能夠幫我找找那本書嗎？", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n祈倫托聯絡人的便箋"}
MultiLanguageQuestData['tw'][77898] = {title = "致敬與獻祭", objective = "在暗矛要塞搭建羅亞祭壇。", description = "是時候回家了。我們一起歡迎羅亞回歸回音群島吧。他們帶來的正面影響應該很快就可以壓過繆薩拉的力量。\n\n去吧，我會跟上。", progress = nil, completion = "所有祭品都放好了。開始下一步吧。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77899] = {title = "拉許卡", objective = "製作拉許卡。", description = "我們在製造拉許卡時，我們會根據腦中的形象來創造出羅亞的型態。藉由認知羅亞的型態，我們就能更加了解他們的本質。但這些面具畢竟是我們做的，所以當羅亞看到面具的時候，他們就會明白我們對他們的期望。\n\n如果羅亞不願對面具降下祝福，代表他們不會成為我們內心期望的樣子。如果羅亞願意對面具降下祝福，代表他們喜歡我們想像出的型態，並且會與我們達成協議。\n\n我們可以寫下契約，但用言語欺騙比動手簡單多了。", progress = "與羅亞建立羈絆，拉許卡不可或缺。", completion = "&lt;name&gt;，做得好！\n\n我這邊也快完成了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77900] = {title = "羅亞試煉", objective = "在暗矛羅亞的祭壇開始進行試煉。", description = "羅亞對拉許卡降下祝福的同時，試煉就會開始。羅亞會給予我們任務來指導我們。試煉一旦開始，就絕對不會停下來！\n\n我們一起去祭壇吧。巫醫札妲會在儀式中引導我們。她雖然還是加德林大師的學徒，但她的表現已經能獨當一面，可在試煉中提供協助。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77901] = {title = "受訓者再培訓", objective = "在削弱迷失的受訓者之後，從他們身上抽取8道暗影。", description = "你的巫醫正在試圖扭轉試煉來強化繆薩拉。會有許多人向這股力量臣服，但我們始終會與暗矛站在同一陣線。\n\n這跟我原先設想的試煉不太一樣。現在我們只能隨機應變了。中斷他的獻祭魔法，解救你的食人妖同胞。這個符咒能夠幫上忙，但你必須先削弱他們。\n\n盡量別讓他們犧牲。", progress = nil, completion = "這樣就能削弱儀式的力量了。不能再讓更多的暗矛族人被繆薩拉控制！", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77902] = {title = "儀式繼續", objective = "在盧考的幫助下移除3個儀式法陣。", description = "那個巫醫偷走了試煉。她不只嘲諷我們，還打算吞噬生者的生命來釋放繆薩拉。但我們還有辦法影響這場試煉。\n\n只要我們聯手，就能壓制她的邪惡法陣。如果你找到法陣，就呼喚我。讓我們一起擊退死亡。", progress = nil, completion = "若是要與死亡搏鬥，盧考會是很棒的盟友。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77903] = {title = "死亡力量", objective = "殺死繆薩拉的召喚靈體。", description = "儀式一旦開始就無法中斷，但我們不能讓札妲利用我們的族人或羅亞來幫助繆薩拉。\n\n如果我們袖手旁觀，就會有更多的暗矛族人轉而向繆薩拉尋求力量。我會找方法突破札妲的保護能量，你去阻止靈體奪走我們的家園！", progress = nil, completion = "那些爪牙你處理得很好。這樣他們之後就不會搗亂了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77905] = {title = "繆薩拉的化身", objective = "收集迦尼的祝福，接著和盧考一起前往柱子的頂端擊潰札妲的防護圖騰。", description = "時候終於到了，和我們的羅亞一起拯救暗矛族人的靈魂吧。\n\n去看看迦尼有沒有發現什麼。希望他的道具可以讓你接近札妲的咒像，然後摧毀它們。那樣我們就有機會直接攻擊那個巫醫。我會在凱弗亞西帝的幫助下吸引她的注意力，但你要小心她的守護者。他們可不會眼睜睜地看著你破壞她的咒像。", progress = "札妲是暗矛部族的恥辱。", completion = "我們擊敗了札妲，她再也不能幫助繆薩拉逃離他的監牢了。\n\n沒有盧考、凱弗亞西帝，甚至是迦尼這些羅亞的幫助，我們絕對無法贏得勝利。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][77906] = {title = "暗矛羅亞", objective = "摧毀繆薩拉的祭壇，然後換上迦尼的祭壇。", description = "那不是傳統的試煉，但我們只會保留對部族有幫助的傳統。\n\n這就是我們的優勢：能適應迎面而來的考驗。\n\n是時候擺脫過去，來彰顯對我們最重要的事物了。暗矛向來不是最龐大的部族，也不是最強盛的。我們能延續是因為我們選擇了自己的道路和盟友。\n\n你和這些羅亞一同努力和犧牲，不只幫助了伯昂撒姆第，也保護了暗矛族人的靈魂。這就是為什麼我們尊敬我們的羅亞…還有你。", progress = nil, completion = "暗矛部族信奉羅亞並不只是因為力量強大。暗矛部族信奉的是能為部族奉獻的羅亞。\n盧考、凱弗亞西帝和迦尼從前就是這樣。所以我們現在才會崇拜他們。\n\n你製作的面具不只是為了儀式。帶著面具和我們部族的衣飾吧。\n\n穿上它們，展現你對暗矛的認同吧。", rewards = "您會收到：\n\n套裝：暗矛的傳承羅亞的祝福之刃龍石"}
MultiLanguageQuestData['tw'][77908] = {title = "古老秘聞", objective = "將「提爾的傳承」一書交給沃卓肯的巴比‧卡萊爾。", description = "<將書交給沃卓肯的巴比‧卡萊爾，以便解讀石板的內容！>", progress = "我的消息有幫助嗎？你有找到那本書嗎？", completion = "你果然找到了！你知道嗎？你可能會在實地調查員這條路上發光發熱。\n\n提爾的傳承，是吧？真是不可思議。我會跟卡索斯一同合作，看能不能解讀石板上的文字。我確信這本書就是解開謎團的鑰匙。\n\n我們就要有大發現了！我已經等不及看到明天報紙的頭條了。", rewards = nil}
MultiLanguageQuestData['tw'][77910] = {title = "魔法灌木", objective = "對12棵魔法灌木使用澆水壺。", description = "翡翠夢境的某些植物可能含有特定材料，有助於我們在這裡的工作，不過我們需要的量非常大，但我並沒有雇用草藥師去採集材料。\n\n我在一個澆水壺附魔，想解決這個問題。\n請去一趟翡翠夢境，對著我需要的植物使用澆水壺，應該就會自動採集需要的植物。", progress = nil, completion = "做得非常好，這些植物一定能美化這個地方！", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][77911] = {title = "製作毯子", objective = "從鞭笞者身上收集6份絲絨鞭笞者葉。", description = "我無法好好休息！我把所有的精力都消耗在戰鬥中，但這裡實在太吵、地面實在太硬，讓我完全睡不著…\n\n我知道！這樣有點強人所難，但我需要好好休息，才能重回戰場。\n\n我有個一石二鳥的辦法，你能幫我嗎？解決那些暴走的鞭笞者，然後收集它們的葉子，好讓我製成毯子，躺在上面。", progress = "對翡翠夢境而言，這裡真的相當混亂。", completion = "謝謝你的葉子。希望這能讓我順利睡著。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][77912] = {title = "過時珠寶", objective = "收集10個薩克利飾物。", description = "當地的一些珠寶設計師想研究一下薩克利部族飾物的樣本。\n\n既然他們正在攻擊我家，我們或許可以好好把握這個機會。\n\n你應該會以暴制暴，對吧？\n\n等你收集到樣本，就去找亞恭奈克斯。", progress = "新知往往來自你最意想不到的地方。", completion = "我沒想到會這麼快。\n\n你的工作效率真高，&lt;name&gt;。", rewards = "您會收到：\n\n珠寶師設計稿"}
MultiLanguageQuestData['tw'][77914] = {title = "燃燒符文", objective = "從翡翠夢境的火焰德魯伊身上收集10個燃燒符文。", description = "我聽說火焰德魯伊利用一種獨一無二的銘文，讓他們通往夢境的傳送門保持穩定！儘管他們的企圖充滿惡意，我還是不禁對他們的手法感到好奇。\n\n如果我們可以更加了解他們的手法，或許就能為盟友提供更有用的反制措施，讓他們無法來去自如。要是你成功取得任何燃燒符文，能不能交給我同事，讓他進一步研究嗎？", progress = "小心點，朋友。我不認為火焰德魯伊會心甘情願地交出他們的符文。", completion = "非常感謝你。我們會馬上開始破解這些符文。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n雕銘師的雕紋"}
MultiLanguageQuestData['tw'][77922] = {title = "取得蓬鬆填充物", objective = "收集8份絲質鼠尾草。", description = "如果沒有柔軟的東西可以躺，我根本不能好好休息。幸好，夢境中的某些鼠尾草非常蓬鬆，甚至連鵬鳥羽毛都會自慚形穢！它會是最完美的填充物！\n\n你可以幫我收集一些鼠尾草，好讓我能躺在上面嗎？", progress = "這些鼠尾草應該夠柔軟，非常適合弄個舒適的床鋪。謝謝你的協助。", completion = "謝謝你幫我帶回床墊的填充物。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][77928] = {title = "隔牆有耳", objective = "到沃卓肯的美容沙龍附近與方利‧響鳴交談。", description = "還記得我的線人，方利‧響鳴嗎？看來她對奪走文物的幕後黑手又有了不同的推論。\n\n上次的線索毫無進展，讓我有點疲乏。但我們不能拒絕這次的機會。我們至少要聽聽她怎麼說，畢竟這是記者的基本準則。\n\n你在美容沙龍旁便可找到她。", progress = nil, completion = "好，這次我很確定。我追蹤了所有人。沒錯，所有人，包括你在內。\n\n提瑟里斯是這一切背後的主謀。他一直在跟城市裡的可疑人物會面，來確保能獲得物資大幹一票。我猜應該是要進行遠征。\n\n你需要調查他購買的那些箱子。我已經標註了大略位置的座標了。好好利用那思緒軟帽吧！你的塑像也能幫助你縮小範圍來找到確切位置。", rewards = "您會收到：\n\n沃卓肯熱門景點"}
MultiLanguageQuestData['tw'][77932] = {title = "生命的溫暖", objective = "從悶燃樹林的火焰德魯伊身上收集8個變形灰燼樣本。", description = "火焰德魯伊施展狠毒的魔法，所到之處，萬物都會被火焰吞噬。然而，他們使用的鍊金材料確實有獨到之處。\n\n如果你剛好遇到他們的變形灰燼，可以幫我收集嗎？我在夢境的某個聯絡人一直向我索取這東西。", progress = "啊，你來了！你成功拿到那種灰燼了嗎？它的鍊金特性真是不可思議。", completion = "啊，太棒了！有了這個，我就有機會驗證我的猜測了…畢竟，正常人根本不會沒事跑去火源之界！", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][77933] = {title = "發現冒泡水", objective = "從冒泡之泉收集8個樣本。", description = "埃達希爾成長後，也在夢境造就許多地質奇觀。其中包含各式各樣的魔法泉水，從艾澤拉斯深處汩汩湧出。\n\n請去夢境一趟，收集泉水的樣本。", progress = nil, completion = "我完成取樣後，會分享給這裡的其他人。", rewards = "您會收到：\n\n鍊金術筆記"}
MultiLanguageQuestData['tw'][77934] = {title = "完整存貨", objective = "把你的發現帶去給沃卓肯美容沙龍附近的方利‧響鳴。\n\n已提供物品：\n", description = "<在沃卓肯幫方利‧響鳴蒐集箱子上的紙條。>", progress = nil, completion = "嗯，沒發現什麼異常。但是，我深信這是那個龍獸的詭計。為什麼一個普通的旅店老闆要跟這麼多可疑人物會面呢？\n\n我需要重新檢查我的資料，並一一檢視你帶給我的資訊。也許會有什麼線索。\n\n自己小心一點，&lt;name&gt;。我可能有點偏執，但我的眼睛可沒瞎呢。我們時間所剩不多了。", rewards = nil}
MultiLanguageQuestData['tw'][77935] = {title = "供應寶劍", objective = "將3把龍金之劍送交給翡翠夢境的塞蘭妮亞", description = "寶劍！\n\n抱歉，我看到你，而我不想忘記。\n\n沒錯。我們需要寶劍。在夢境中。你可以提供，對吧？\n\n請交給塞蘭妮亞。", progress = "需要幫忙嗎？", completion = "我們會善用這些東西的。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][77936] = {title = "收獲熱能", objective = "到翡翠夢境收集10個永恆火焰精華。", description = "眾所周知，在鍛造過程中，熱能扮演非常關鍵的角色。\n\n我聽說翡翠夢境仍然遭受火焰盟友的猛攻。一定有辦法從那些永恆燃燒的生物身上取得燃料。\n\n如果你順利取得燃料，相信夢境當地的某個鐵匠一定會非常感興趣。", progress = "嗯。怎麼啦？", completion = "你一定打敗了危險的敵人，才拿到這些材料吧。謝謝你。在製作我們的裝置時，這一定能發揮很大的作用。", rewards = "您會收到：\n\n鐵匠的令狀"}
MultiLanguageQuestData['tw'][77937] = {title = "禁忌蜜糖", objective = "從翡翠夢境的暗影光珠收集8份光珠糖。", description = "在這個獨一無二的開花季節中，有人在夢境發現新品種的花。這些奇特的花會產生不可思議的花粉。它的味道非常好聞，就像是新鮮出爐的餅乾。\n\n只可惜它並不能入菜，光是嚐到一點點，都會導致嚴重的急性肝臟中毒。\n\n不過，它卻是超好用的通用附魔添加物。經過初步測試，已經證實它的功效可以達到炫彩之塵的四倍。沃卓肯的商人無不爭相搶購。", progress = "附魔師會很想拿更多來測試。他們一定會謹慎地使用、好好測試。我們希望在開花季節結束後，那些花還會在，不過這點誰都說不準。", completion = "啊，我還以為你帶了剛出爐的餅乾給我！沒想到是更好的東西。", rewards = "您會收到：\n\n附魔師的手稿"}
MultiLanguageQuestData['tw'][77938] = {title = "非主流工程師", objective = "為翡翠夢境的奈菈‧蓬尾收集8朵白果蕈菇。", description = "聽說夢境有個傳奇工程師，能夠製作出最漂亮的捕夢網。\n\n這位工程師名叫奈菈‧蓬尾，最喜歡橡實味蕈菇，全靠它們提高自己的工作效率。橡實味蕈菇…聽起來超怪的，不過的確有所耳聞。\n\n伊瑟拉之眼附近的某個海岸就大量生長著這種蕈菇。千萬要留意那個地方的野生動物。如果這種蕈菇跟我聽說的一樣美味，一定有貪吃的生物在旁看守。", progress = nil, completion = "&lt;奈菈‧蓬尾，一個毛茸茸、眼睛很亮的芙柔亞，伸出小小的手掌收下蕈菇。她如行雲流水般，把蕈菇迅速塞進附近的儲物箱中。\n\n這位一定就是那個喜愛橡實味蕈菇的傳奇工程師。現在一切都說得通了。&gt;", rewards = "您會收到：\n\n工程學資料"}
MultiLanguageQuestData['tw'][77945] = {title = "地上的靴子", objective = "將3雙先鋒皮甲長靴送交給翡翠夢境的塞蘭妮亞。", description = "我正想找你。\n\n我收到一張物資調用單，要我供應來自夢境居民的皮革。當然是鞋子呀。兩足生物總是要穿上它們，才能像鳥一樣在森林穿梭，沒錯吧？\n\n一旦你拿到東西，請交給塞蘭妮亞。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][77946] = {title = "高纖絲線", objective = "從翡翠夢境的附魔灌木取得1份翡翠纖維。", description = "裁縫可以用細線構圖，但在製皮過程中，細線也扮演了非常重要的角色。\n\n夢境的某些硬質植物經過加工後，就能製造出極為強韌的細線，可以用來固定最厚的皮革和鱗片。如果你在旅行過程中，有幸得到任何高密度纖維，只要交給我在夢境的同事，就能得到豐厚的獎勵。", progress = "你不必擔心那些植物。它們幾乎不會受到任何傷害，只要節制地採集，它們會非常樂意與你分享身上的素材。", completion = "啊！這正是我需要的。非常感謝你，&lt;name&gt;。", rewards = "您會收到：\n\n製皮設計"}
MultiLanguageQuestData['tw'][77947] = {title = "洪荒使者時裝", objective = "從翡翠夢境收集10件完好的洪荒使者裝束。", description = "啊，<name>，你來了！\n\n當地的裁縫正在對洪荒使者的長袍進行有趣的研究。如果你可以從攻擊夢境的洪荒使者身上取得長袍，我一定會非常開心…是不是？\n\n記得不要有任何破損。血跡則沒關係，反正可以洗掉。", progress = "需要幫忙嗎？", completion = "木蘭有提到你會送幾件長袍來。\n\n啊，她也說長袍可能需要洗一下。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][77948] = {title = "燃燒殆盡", objective = "到悶燃樹林尋找蘇拉莉思的姐妹。", description = "求求你，我知道這很奇怪，但我們是同一邊的！\n\n我和我姐妹打算一起逃離火焰德魯伊陣營。不過，自從我離開後，她們沒有半個人逃出來，或來跟我會合，現在已經過了好幾天了！我有不好的預感。\n\n要是我心懷不軌，你覺得我還會手無寸鐵、一個人來向你求助嗎？求求你，找到她們。我只有她們了。", progress = nil, completion = "&lt;蘇拉莉思的臉色沉了下來，一臉悲傷地聽著你述說來龍去脈。&gt;\n\n比起永無止境的悔恨，與我家人共渡的有限時光更加難能可貴。生命本身的價值更遠高於此，只可惜一切終不能盡如人意。\n\n謝謝你幫我取回家人僅剩的一點遺物。\n\n愷力奈幫忙拯救的其中一隻小生物似乎很喜歡你。讓牠跟著你吧。這是我們能給這可憐的小傢伙最好的照顧了。", rewards = "您會收到：\n\n沉重的夢境種子卡蘭度幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][77949] = {title = "好看的羽毛", objective = "到翡翠夢境收集10根掉落的大羽毛。", description = "夢境中絕大部分的野生動物都有羽毛或毛皮。牠們落下的絨毛或羽毛據說都極為耐用、柔軟且好看。\n\n巨型眠梟的羽毛更是眾人夢寐以求的逸品。牠們不會經常落羽，而且羽毛很快就會被當地的野生動物拿去築巢。\n\n聽說，最有可能入手羽毛的地方是夢境的蜿蜒根地。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n裁縫樣本"}
MultiLanguageQuestData['tw'][77953] = {title = "岌岌可危的球體", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n保護學家的急件三"}
MultiLanguageQuestData['tw'][77954] = {title = "奇特寶珠", objective = "將拉斯姆斯寶珠交給沃卓肯的提瑟里斯。", description = "<沃卓肯的提瑟里斯要你將寶珠交給他，他會轉交給保護學家卡索斯。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77955] = {title = "爐石大作戰", objective = "從暖石者身上取回加熱的爐石。", description = "等等，我的爐石！沒有爐石，我根本睡不著。\n\n在上一次的戰鬥中，有個加拉登偷走了它。它就像一個小暖爐，我每次都拿著它睡覺。\n\n我討厭欠你更多人情，不過，你可以幫我拿回爐石嗎？\n\n偷走它的加拉登應該在菲拉卡的部隊附近，他們就在這裡的北方。", progress = "我的眼睛快閉上了，但我的身體卻還不想睡…", completion = "吼！我還是睡不著！我很不好意思問你，但也沒什麼選擇了。", rewards = "您會收到：\n\n幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][77957] = {title = "小人當道", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n古代提爾堡神器筆記"}
MultiLanguageQuestData['tw'][77958] = {title = "翡翠夢境的失眠德魯伊", objective = "為失眠的德魯伊唱搖籃曲。", description = "為什麼就算有了暖和的毯子，我還是睡不著呢？\n\n<薩里安大聲咒罵，然後嘆了口氣。>\n\n這是令人害羞的要求，不過，還在泰達希爾的時候，我母親都會在睡前唱搖籃曲給我聽，可以請你為我唱搖籃曲嗎？\n\n任何搖籃曲都可以，我只想好好睡個覺。", progress = nil, completion = "非常感謝你去查看我朋友的情況。\n\n等到他們再次醒來，我們就能再度進攻菲拉卡的部隊。", rewards = "您會收到：\n\n沉重的夢境種子臨時葉片吊床備用的加熱爐石龍石"}
MultiLanguageQuestData['tw'][77976] = {title = "支援協調者：夢境湧現", objective = "去找正在調查夢境湧現的德魯伊，並收集100個夢境湧現精華。繼續在巨龍群島各地協助沃卓肯協調者和他們的盟友。", description = "翡翠夢境突然爆發大量能量，一群來自艾澤拉斯的德魯伊已經展開調查。\n\n這很可能會影響我們所有人，<name>。請協助他們進行調查，了解這個最近出現的現象。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n沃卓肯寶藏龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記龍鱗遠征隊沃卓肯協調者莫魯克半人馬伊斯凱拉巨牙海民"}
MultiLanguageQuestData['tw'][77977] = {title = "不祥文物", objective = "取回拉斯姆斯寶珠以及其藏匿的神器。", description = "<寶珠可以完美嵌在面板上。>", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][77978] = {title = "傳遞火炬", objective = "在悶燃樹林中收集文件並擊殺火焰德魯伊。", description = "<戰略文件散落在黎安翠絲周圍。大部分的文件詳細列出了實驗和未來的進攻地點。>\n\n<要是能找到更多文件，一定能幫上盟友很大的忙。順便削減火焰德魯伊的數量，何樂而不為。>", progress = "有什麼事？", completion = "這都是黎安翠絲收集的？而你…則是幫她收尾。\n\n謝謝你把她的日誌交給我。那些文件你留著吧。你和你盟友能從中獲得極有價值的情報。\n\n它們只會讓我想起痛苦的回憶。", rewards = "您會收到：\n\n墮落反叛者的賞金翡翠露珠"}
