MultiLanguageQuestData['tw'][78040] = {title = "外域杯正式開始", objective = "到沃卓肯拜訪安德斯塔茲領主。", description = "龍騎士！你剛好跟安德斯塔茲領主錯過了。他正在招募像你這樣有實力的龍騎士，去參加新的賽事！", progress = nil, completion = "龍騎士，感謝你來訪！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78041] = {title = "天空之母的憤怒", objective = "尋找艾維娜。", description = "我們接獲報告，指出火焰德魯伊已經在伊瑟拉之眼的南方建立了另一個根據地。\n\n但他們也很倒霉，他們的侵略行動驚擾了當地的野生有翼生物，激怒了飛行之母。\n\n看看艾維娜需不需要任何幫助。未來的戰鬥我們會需要她的雙眼與雙翅。", progress = nil, completion = "我知道塞納留斯一定會派人來支援。\n \n但怎麼會是派這個愚蠢、棲息在地面的羅亞呢？\n\n&lt;艾維娜用失望的眼神看了寇祖一眼，焦慮地敲了敲自己的利爪。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78042] = {title = "艾維娜的估計", objective = "收集20個染血的護甲碎塊。", description = "<艾維娜看著底下的火焰德魯伊，不禁瞇起雙眼。>\n\n寇祖或許會心甘情願地讓這些異端毀滅夢境，但我可不會。\n\n把染血的護甲碎塊帶來給我，證明你殺了他們。\n\n不要手下留情，<name>。這些異端可不是好惹的。", progress = "要是放任他們恣意妄為，夢境遭受毀滅的範圍也會越來越大。", completion = "勇士，起而行果然勝過坐而言呢…\n\n下次如果還有人膽敢入侵你的家園，可別忘了這點。\n\n&lt;艾維娜透出了嚴厲的眼神斜望著寇祖。&gt;", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][78043] = {title = "寇祖的困境", objective = "與火焰偽裝的夢境梟獸交談來蒐集火焰德魯伊的相關情報。", description = "又是你！你一定是來幫忙的，對吧？\n\n絕對是這樣。怎麼可能不是！事情的發展真讓人興奮。這些可悲的德魯伊到底有什麼目的？\n\n幸好，我的一些朋友已經滲透進那些德魯伊，相信他們一定收集到不少情報。\n\n去吧，我充滿好奇心的夥伴，帶回令人振奮的消息吧！", progress = nil, completion = "好吧，這還真有趣，對吧？\n\n&lt;寇祖興奮地迅速拍腳，不禁渾身發抖。&gt;\n\n&lt;name&gt;，你一定也為此著迷，對吧？\n\n喔，我問了一個蠢問題。你當然是這樣！", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][78044] = {title = "駭人的花粉", objective = "揭露並擊殺10個燼火花粉野獸。", description = "這個燼火花粉並沒有激起有趣的改變。它只吞噬了一切，直到萬物化為灰燼為止。這帶來的…是一致…\n\n而我自己認為，這樣的改變平淡到有些可悲。\n\n我贊成改變，不管事物的本質為何。但如果這樣的改變抹殺了未來進一步再改變的可能性，那它就必須遭到阻止。\n  \n如果有生物受到這個花粉的影響，那們它們就必須被消滅。這樣的烈焰可不能讓它繼續延燒下去。", progress = nil, completion = "你能想像這些無聊鬼為了讓我這變幻羅亞來破壞他們改變夢境的陰謀，他們付出了多大的心力嗎\n \n膽子還真大呢！", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][78045] = {title = "斬草除根", objective = "收集8個拔起的灰燼水仙。", description = "<艾維娜盯著寇祖好一段時間，皺著眉頭。>\n \n雖然我無法認同寇祖對變換的癡迷，但他持續的調查卻揭露了一個比一開始更可怕的陰謀。\n\n如果我們不根絕問題的話，擊殺再多野生動物也沒有用。\n \n在下方的森林中找出燃燒的灰燼水仙，把它們拔除乾淨。", progress = "如果放任這些灰燼水仙恣意散播有害的花粉，夢境的其他地方也會變得岌岌可危。\n\n<艾維娜皺起眉頭。>", completion = "做得好，&lt;name&gt;。\n\n相信塞納留斯一定很清楚這些雜草所帶來的危害。你漏掉的殘留花粉或花朵，幾個林精應該就能處理妥當。\n\n\n\n現在只剩下最後一個任務了，勇士。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][78046] = {title = "監督者之監視", objective = "殺死監督者查德瑞恩。", description = "你交給寇祖的那些研究報告中，提到了這些邪惡實驗的幕後黑手。\n\n那個名為「查德瑞恩」的監督者一直都在我們的密切監視之下。\n\n就是他負責監督我們下方的研究站。\n\n如果我們要徹底終結他們的恐怖實驗，破壞他們的進度，就必須解決他。", progress = nil, completion = "所以他們的監督者死了嗎？\n \n&lt;艾維娜向你點了點頭，表示讚賞。&gt;\n \n很好。\n\n現在查德瑞恩不在了，他們的實驗將會被摧毀，他們的研究也繼續不下去了。就希望這一切能終結他們扭曲的計畫。", rewards = "您會收到：\n\n大型夢境種子監督者的焦黑法杖幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][78047] = {title = "外域杯賽事", objective = "完成外域杯的賽道。", description = "又要來試試你的能耐了。\n\n我的青銅龍同事已經前往外域打造更多全新挑戰了。我們想看看有沒有任何大膽的馭天者能完成整個賽事！\n\n準備好接受挑戰了嗎？", progress = nil, completion = "你不愧是龍騎士中的佼佼者！如果你還沒試過的話，歡迎在外域杯挑戰你的最快時間，並取得艾澤拉斯騎士的代表色。", rewards = "您會收到：\n\n艾澤拉斯騎士徽章"}
MultiLanguageQuestData['tw'][78064] = {title = "寇祖的感知", objective = "在寇祖的巢穴尋找並迎戰入侵者。", description = "你有很多問題，而我有很多煩惱。\n\n非常迫切的煩惱。有個入侵者，是一個粗暴結束我的快樂人生的傢伙。我非常煩惱，只希望有人能趕走這個入侵者。\n\n等等，這件事可以交給你啊！這是雙贏的局面，你趕走入侵者，我就回答你的問題。他現在就在北邊的一個洞穴裡。相信你一定能解決他。", progress = nil, completion = "哈！喔，來吧。剛剛真好玩。別那麼生氣。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78065] = {title = "詢問寇祖", objective = "再次接觸寇祖，詢問他的真正想法。", description = "勇士，我知道我們無法讓寇祖成為我們的一份子。然而，我們要盡可能地得到所有幫助。\n\n你必須找到他拒絕幫助我們的原因，說服他踏上正途。我和寇祖的關係並不是很好。如果有你的努力，便可以斬獲更多成果。\n\n聽說寇祖在碎顫林地附近築了一個巢。你願意去跟他談談嗎？", progress = nil, completion = "寇祖說了有人會來。我想你有帶祭品吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78066] = {title = "應得的答案", objective = "得到有關寇祖的解答。", description = "啊，這樣好多了。我終於可以思考了。\n\n再說一次你想要什麼？喔，對！問題。\n\n有問題就問吧。", progress = nil, completion = "&lt;寇祖和他的追隨者離開了。這一定就是他認為你應得的答案。\n\n至少現在是如此。&gt;", rewards = "您會收到：\n\n沉重的夢境種子好友之羽秘密的糾結紗線幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][78068] = {title = "工藝師的請求", objective = "在艾克索達與大工藝師羅穆爾會面。", description = "<有個包裹從艾克索達寄來給你，上面蓋有大工藝師的徽印。\n\n你打開了小盒子，發現一塊手掌大小的光滑六角形水晶。\n\n當你觸碰它時，一則全像訊息在水晶上方的空中顯現。在這則訊息中，大工藝師羅穆爾請你儘早前往艾克索達。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78069] = {title = "傳統重現", objective = "幫助羅穆爾完成全像攝影發射器的修復工作。", description = "先知想要以個人的名義請你幫忙舉辦提夏瑪。但由於他正在其他地方辦事，我想請你先幫我們的忙。\n\n我和我的同事一直在進行一項特別的計畫。既然先知宣布了今天會舉行提夏瑪，那我們就要在慶典上揭曉！\n\n為此，我需要發射器，但它需要檢修。我們的時間只夠做短接啟動。\n\n<name>，去附近的木箱裡拿一些纖絲和焊接工具。也許我可以把它焊接成陣列。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78070] = {title = "期限將至", objective = "到撒塔斯城與阿潭雅談話。", description = "在提夏瑪期間，我和阿潭雅會展示我們計畫的結構圖。\n\n阿潭雅是撒塔斯的高階工藝師。她的父親是赫赫有名的哈塔魯主教，也是我已故的導師。\n\n哈塔魯的成就很難企及，但阿潭雅的才能遠不止於此。\n\n結構圖在阿潭雅手上，她應該要在展出時在場才對。但她沒回覆我的訊息。\n\n阿潭雅不常離開城市，但她為這場提夏瑪破例也不奇怪。或許你可以去開導她。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78071] = {title = "趕工令", objective = "去和貝魯恩聊聊。或許他知道該怎麼說服阿潭雅離開撒塔斯。", description = "我的結構圖標示得清清楚楚，無須解釋。\n\n上面的每個計算都經過驗證，遵守每項建築規範，我甚至還把電網必須遵循的通道佈局也包含在內了。\n\n羅穆爾知道這個計畫。他已經親自確認過所有細節了，他可以自己向大眾解釋。\n\n我沒必要浪費我寶貴的時間去艾克索達參加這個可笑的節慶。\n\n我的學徒會把存有結構圖的資料水晶拿給你。你拿了就快走吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78072] = {title = "舊傷口", objective = "在奧齊頓與靈魂牧師談話。", description = "<貝魯恩對你低語。>\n\n我相信你一定知道，德萊尼有辦法和死者對話。\n\n這和讓所愛之人起死回生不同，但…\n\n在靈魂牧師奪回神殿之後，哈塔魯的骨灰就被帶去了奧齊頓。也許他們有辦法讓阿潭雅走出失去父親的傷痛。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78073] = {title = "揮之不去的傷疤", objective = "幫助瑪拉達爾主教與奧齊頓的靈魂溝通並安撫他們。", description = "我們的確可以幫你。\n\n但或許你可以先幫我一個忙…\n\n當我們得知提夏瑪近在眼前時，我們就急忙為受苦最深的靈魂做好前往艾克索達的準備。慶典的聖禮也許能幫助他們獲得安息。\n\n然而，在請他們離開前，必須先徵得他們的同意。所以我們首先要做的就是和他們溝通，然後安撫他們。\n\n你可以幫忙讓這些靈魂平靜下來嗎？事成之後，我會帶你去哈塔魯的墓地，把你在找的東西給你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78074] = {title = "雙目清晰", objective = "前往哈塔魯主教的墓地，然後回撒塔斯找阿潭雅。", description = "幸運的是，並非所有埋葬在奧齊頓的亡者都像這三個靈魂一樣遭受苦難。有些人坦然地走向死亡，就像雨後的土壤沉澱一樣自然。\n\n哈塔魯主教就是這樣的靈魂之一。感謝聖光讓他能夠安息。\n\n來吧，我帶你去他的墓地。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78075] = {title = "拋下過往", objective = "回到艾克索達找大工藝師羅穆爾。", description = "我的母親在殖民地星球上去世。我和父親相互扶持才走出悲傷，但當他在撒塔斯圍攻中戰死，看著他最偉大成就的城牆化作灰燼…\n\n我意識到我已孑然一身。\n\n於是我埋頭苦學，終於完成屬於我自己的撒塔斯結構圖了。一個更完善的撒塔斯。\n\n<阿潭雅將鏡片握緊在拳頭中，然後無奈地嘆了一口氣。>\n\n我會去艾克索達，但要是羅穆爾敢提一個字，我就把他的焊接工具塞到他嘴裡。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78076] = {title = "緊急出動", objective = "乘坐阿古斯法力魟魚與哈圖恩族長飛往血謎島。", description = "<name>！費倫告訴我你可能會在這裡。他需要你的協助。\n\n佔據附近島嶼的薩特一直在伏擊前去參加提夏瑪的德萊尼。\n\n我和費倫試著想要悄無聲息地解決這個問題。他不想在神聖的節日驚動復仇者和他的族人。\n\n但儘管我們付出不小的努力，攻擊事件依舊頻仍。如果不能讓這些惡魔乖乖就範，整場活動可能就得取消了。\n\n和我一起去處理這場威脅吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78077] = {title = "皮肉之下", objective = "從腐化的野生動物身上收集8個有缺口的骨頭。", description = "我和阿爾札對這件事的看法一致。在用武力擊退這些薩特之前，我們必須先弄清楚他們的底細，否則我們可能會陷入無法取勝的戰鬥。\n\n觀察敵人留下的損害情況，我就可以更了解他們。\n\n這裡的野生動物都被艾克索達的殘餘能量腐化了，不過我懷疑是這些惡魔的存在讓情況惡化。\n\n幫我收集當地野生動物的骨頭。對其進行研究應該能獲得一些線索。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78078] = {title = "評估敵人", objective = "收集6個薩特圖騰。", description = "燃燒軍團或許是單一實體，但規模卻非常龐大。組成軍團的惡魔與他們征服過的無數世界一樣五花八門。\n\n但是我沒有對付薩特的經驗。根據預言者告訴我的情報，他們的生活方式似乎毫無章法。他們是具有智力，但他們的惡意中卻存在野性。\n\n我傾向於認為他們最近的攻擊是隨機事件，但也可能不是。把他們散布在血謎島各處的圖騰帶來給我。如果他們真的另有所圖，那我應該可以弄清楚他們的真正目的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78079] = {title = "切除", objective = "在納茲維恩與費倫和哈圖恩會面，在區域中尋找曼那瑞出現的跡象。", description = "憑良心而論，如果我們在離家園這麼近的地方受到威脅，那我就沒辦法召集德萊尼前來參加提夏瑪。\n\n如果其中一名曼那瑞正在利用薩特策劃這些攻擊，或是要轉移我們的注意力，趁機謀劃更龐大的邪惡陰謀，那麼我們就必須立刻剷除他們。\n\n我們會分頭尋找敵人的蹤跡。阿爾札會搜查北邊的薩特營地。比較近的營地就由你、哈圖恩還有我去調查。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78080] = {title = "追本溯源", objective = "在艾克薩瑞安尋找魔化的源頭並將其摧毀。", description = "你能感受到這份寂靜嗎？\n\n這片區域簡直是空無一物。就連發狂的野生動物都不敢靠近這個營地。\n\n我沒看到任何的直接原因，但這裡的魔化共鳴幾乎快讓人喘不過氣了。我能感覺到它是經由曼那瑞之手編織而成，但我遭到阻止，無法更深入地探索。\n\n他們在隱藏著什麼。\n\n妨礙我的東西一定就是哈圖恩在其他營地發現的隱形魔法。我可以驅散這個魔法，但我不能保證驅散它後我們能發現什麼。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78081] = {title = "痛苦散去", objective = "在艾克索達與預言者費倫會面。", description = "隨著賽羅娜斯再次殞落，血謎島終於可以恢復如初了。毫無疑問，她的影響就是造成這片土地腐化的元凶。\n\n今天又多了一個慶祝的理由了，但這不是我呼喚哈圖恩和阿爾札來艾澤拉斯的真正目的。\n\n我想請他們和我們一起參加提夏瑪。\n\n舉行聖禮的目的是要讓我們反思過去的行為，並致力於創造出更美好的未來。我們的團結合作就是這個概念的體現。\n\n我會帶他們去艾克索達。等你準備好，也請務必加入我們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78082] = {title = "有難同當", objective = "收集10顆回憶石，創造屬於你的回憶石，接著將石頭丟入緩刑烈焰中熔解。", description = "提夏瑪曾經是個孤獨的節日。每一位埃雷達爾都會在石頭上刻上我們所承載的痛苦記憶。我們會反思這段記憶可以教會我們什麼，然後我們會竭盡所能地帶著這些智慧繼續邁進。\n\n最後，我們會把石頭丟進緩刑烈焰中熔解，象徵著消除靈魂的重擔。\n\n到了今天，提夏瑪將不再是一個孤單的紀念日，而是普天同慶的慶典。\n\n收集那些願意相信你的人的石頭，然後將它們丟入烈焰之中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78083] = {title = "攜手並進", objective = "與預言者費倫交談，開始進行儀式。", description = "啊，我想我聽到先知在台前呼喚侍從了。\n\n既然現在大家都齊聚一堂，我很好奇他和羅穆爾打算宣布什麼。\n\n我們快點過去吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n德萊尼全像寶石套裝：德萊尼的傳承龍石"}
MultiLanguageQuestData['tw'][78097] = {title = "生命火花：翡翠夢境", objective = "在戰爭模式下，於翡翠夢境收集100個生命火花。", description = "跟隨精華進入翡翠夢境，尋找可以探索的事物，不過請提防那些擋路的敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n夢境守望者徽記夢境守望者徽記巨龍群島補給品鬥爭戰利品榮譽點數征服點數"}
MultiLanguageQuestData['tw'][78102] = {title = "樹冠遊行賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78113] = {title = "挑戰巡迴賽", objective = "完成巨龍群島每一區的挑戰賽道。", description = "又見面了冒險者！\n\n你喜歡挑戰嗎？希望如此，因為我的青銅同僚為你準備了一組全新的挑戰賽道。\n\n不用懷疑，這些比先前的賽道更加困難。沿路有相同的障礙物，但少了那些恩澤。\n\n準備好迎接挑戰了嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78115] = {title = "翡翠漫步賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78117] = {title = "翡翠漫步賽道 - 逆向版", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78128] = {title = "得快一點", objective = "完成1次戰場閃擊戰。", description = "你想證明自己的能耐，對吧？我剛好有個適合的挑戰，祝你好運！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n榮譽獎章征服點數榮譽點數"}
MultiLanguageQuestData['tw'][78129] = {title = "得更快一點", objective = "完成3次戰場閃擊戰。", description = "你順利通過那個簡單的測試。\n\n但還有更多考驗等著你。再試一次，完成後，就回來找我。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n榮譽點數征服點數"}
MultiLanguageQuestData['tw'][78153] = {title = "處理：原型符文", objective = "製作或獲得莉迪亞菈的束縛符文。", description = "啊，我知道了！我們是在未知的領域，但我有個計畫。\n\n你需要一點宇宙墨水、符刻攀纏樹皮和暗焰精華。\n\n把這個配方分享給交情好的雕銘師，應該能讓他們替你完成製作訂單。讓我更新筆記，加入影縛符文的配方。", progress = "準備好了嗎？要開始了嗎？", completion = "太完美了！當然，我們還沒完工。如果要讓菲拉雷斯接受我們的改造，我們必須強化束縛。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78154] = {title = "展開測試：影縛符文", objective = "在『夢境希望』埃達希爾中擊敗瘤根、『殘暴者』伊吉拉和弗柯羅斯。", description = "我們必須驗收束縛。我們可以與菲拉卡最厲害的副官對戰，測試那些組件，確保它們正確同調。然後，我們可以把調和後的材料與菲拉雷斯綁定。\n\n如果你可以在這個符文束縛他們的時候，擊敗瘤根、『殘暴者』伊吉拉和弗柯羅斯，就代表你已經準備好徹底調和影縛符文。", progress = nil, completion = "太刺激了！與其說像鬥士，我更像工匠，但你的高超武藝令人印象深刻！", rewards = "您會收到：\n\n同調影縛符文"}
MultiLanguageQuestData['tw'][78155] = {title = "處理：灰燼耀光微粒", objective = "在翡翠夢境中從強大的裝備上收集灰燼耀光微粒。", description = "聽說在翡翠夢境中，有著極強暗焰特性的粗糙灰燼很常附著在裝備上。想要取得這種強力的灰燼，唯一的方式就是分解裝備。\n\n來吧，使用這根附魔棒。它應該能讓你汲取所需要的魔塵。", progress = "別放棄！這個過程不只對製作有益，也能修身養性！請牢記這一點！", completion = "希望這根尋物杖有幫上忙！接著來進行下一步…", rewards = "您會收到：\n\n原型秩序皮紙"}
MultiLanguageQuestData['tw'][78156] = {title = "處理：耀光皮紙", objective = "製作或獲得夏菈莎的授智皮紙。", description = "我們可以用秩序魔法嵌入附魔，強化我的作品。\n\n這是我對於濃縮授智皮紙的筆記。把筆記分享給其他交情好的附魔師，應該能讓他們得到足夠的情報，替你完成製作訂單。", progress = "我看過學生因為這種工作而…遭到…分解，但我知道你沒那麼弱。\n\n抱歉。我與世隔絕太久了，我其實不常開這種「玩笑」。", completion = "我們就快成功了。現在，我們只需要想辦法讓水火不容的暗焰和秩序魔法相輔相成。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78159] = {title = "處理：發光孢子握把", objective = "製作或獲得艾登的發光孢子握把。", description = "為了製作能用的東西，我們需要大量的扎拉萊克發光孢子，還有一些皮革。\n\n這是我對於共生發光孢子握把的筆記。把筆記分享給其他交情好的製皮師，應該能讓他們得到足夠的情報，替你完成製作訂單。", progress = "追查下去需要耗費大量心力，不過這個礦場絕對值得。", completion = "該來進行最後一步了。這或許會讓人有點…不舒服。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78160] = {title = "展開測試：共生發光孢子握把", objective = "一邊承受握把與菲拉雷斯的融合過程，一邊強化握把。", description = "你必須相信我。我們需要啟動嵌入握把的材料。\n\n將握把套住菲拉雷斯的斧柄應該就能奏效，但你必須撐過那之後的猛烈衝擊。你會需要邊走邊調整，而且很難一次到位。孢子必須與斧頭進行磨合。", progress = nil, completion = "做得好。這個握把一定能助你一臂之力。", rewards = "您會收到：\n\n同調發光孢子握把"}
MultiLanguageQuestData['tw'][78162] = {title = "寇祖的煩惱", objective = "削弱8個魔花人，然後使用寇祖的飛羽將其變成精靈龍。", description = "你的問題的確對我很重要。可惜，我現在分身乏術。\n\n這些魔花人實在是煩人的小東西。相信你已經看過它們了。它們入侵我的巢穴，讓我不勝其擾。\n\n對我和我的朋友造成困擾？確實如此！這是我的羽毛。你要不要乾脆把這些討厭鬼變成沒那麼煩人的東西？", progress = nil, completion = "又是你？你做了什麼？喔，對。很不錯。", rewards = "您會收到：\n\n翡翠露珠"}
MultiLanguageQuestData['tw'][78163] = {title = "寇祖的考驗", objective = "回答寇祖的100個問題。", description = "你想見寇祖，卻沒有帶祭品？\n\n但變幻羅亞恐怕不是想見就能見到的。你必須先證明自己有資格見他。\n\n羅亞寇祖親自將一百個問題交給了自己的朋友！你必須證明自己智力超群，正確回答每一個問題。\n\n回答完一百個問題後，再回來找我。到時候，你或許就能見到寇祖了。", progress = nil, completion = "你真的打算回答一百個問題？我還以為你會被嚇跑。\n\n下次我會把問題數量增加到一千個。", rewards = "您會收到：\n\n奇幻背包龍石"}
MultiLanguageQuestData['tw'][78170] = {title = "滋養忘年之種", objective = "為我們種下的每個種子澆灌永恆露珠。", description = "這些種子的生長必須極度均衡，而且也需要持續的照護。\n\n我發現，在這地區周圍收集到的永恆露珠，有特殊的能量可以讓些種子發揮沉眠已久的潛能。\n\n若你能夠收集一點露珠並澆在植物上的話，我們就可以解開它們真正的力量了。", progress = "你有為綻放的種子澆灌永恆露珠嗎？", completion = "謝謝你，&lt;name&gt;。你願意協助滋養這些遠古種子的意志讓我覺得很溫暖。", rewards = "您會收到：\n\n盛開野花箱子"}
MultiLanguageQuestData['tw'][78171] = {title = "過往的綻放", objective = "收集3朵夢境種子之花。", description = "感謝你的幫助，這些種子長成了壯觀的植物。但是，最令人興奮的部分才剛要開始。\n\n每一株植物的花朵都是蘊藏著豐富情報的寶藏，可以藉此得知它們的歷史以及讓它們跟世界之樹緊密相連的魔法。研究這些花朵，就能讓我們更清楚掌握每種植物之間的關係。\n\n請你小心採收落下的花朵，帶過來給我。", progress = "你有收集三朵花了嗎？", completion = "你做得很好。這能幫助你用找到的種子恢復其他植物物種。", rewards = "您會收到：\n\n小型夢境種子"}
MultiLanguageQuestData['tw'][78172] = {title = "神秘種子", objective = "到野生花園將種子交給希薇亞‧颯茂。\n\n已提供物品：\n", description = "<希薇亞‧颯茂也許會對這些神秘種子感興趣。>", progress = nil, completion = "這些種子掌握了線索，能解開在泰達希爾大火中消逝的奇怪植物遺產。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78177] = {title = "前往吉爾尼斯", objective = "前往吉爾尼斯廢墟的龍骨港。", description = "收復我的王國的時候到了，勇士。被遺忘者遵守他們的承諾，離開了那裡。\n\n不過，在他們離開後的空窗期，血色十字軍似乎決定趁虛而入，把城市當做他們私有的堡壘。我打算趕走他們。\n\n和我一起奪回吉爾尼斯。", progress = nil, completion = "好吧，看來現在由我主導了。\n\n有點出乎意料，但我欣然接受。\n\n好。我們開始吧。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78178] = {title = "前往吉爾尼斯", objective = "前往東部王國的吉爾尼斯，協助吉爾尼斯人奪回吉爾尼斯城。", description = "<name>，我們收到消息，吉爾尼斯很快就會迎來一場動亂。\n\n我們一直與聯盟合作，想讓吉爾尼斯回到吉爾尼斯人手中。不幸的是，血色十字軍佔據了那座城市。\n\n我們想協助他們消滅血色十字軍，收復那片土地。\n\n我和莉莉安希望你參與這場行動。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78180] = {title = "血色十字軍", objective = "在艾德瑞克之憩擊殺10個血色十字軍成員。", description = "卡莉雅會帶領被遺忘者軍隊攻擊北邊，讓敵人分心。\n\n趁著血色十字軍把注意力放在卡莉雅的部隊上，我希望你、莉莉安跟我在城市裡集合。那裡有個秘密通道能讓我們到南邊去，讓我們為部隊打開城門。\n\n秘密通道入口附近有一群血色十字軍潛伏著。你能去解決他們嗎？", progress = nil, completion = "多虧有你，我們對血色十字軍的第一次進攻打得很順利。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78181] = {title = "艾德瑞克的反擊", objective = "在艾德瑞克之憩殺死奉聖師何娜思。", description = "斥候回報說，艾德瑞克之憩的血色十字軍會去破壞那裡的墓穴，全都是因為一個成員在鼓吹。\n\n為了守護這個地方，有太多吉爾尼斯人獻上了生命。我不會眼睜睜看著任何人…褻瀆他們的墓地！\n\n解決帶頭的人，給他們刻骨銘心的教訓。", progress = nil, completion = "解決了？很好。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78182] = {title = "高度及膝", objective = "穿越艾德瑞克之憩的秘密通道，進入吉爾尼斯城。", description = "泰絲和佛斯在隧道盡頭等你。你到的時候，你們三個要從裡面打開南邊大門，讓我們的軍隊進入城市。\n\n穿過隧道去跟他們會合吧。拿著這根火把，秘道裡到處都是那些害蟲。\n\n我會和軍隊嚴陣以待，準備在大門開啟時長驅直入。", progress = nil, completion = "&lt;name&gt;，來得正好。\n\n準備好進行下一階段的攻擊了嗎？", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78183] = {title = "以血還血", objective = "殺死12個血色十字軍成員。", description = "他們似乎把經驗較豐富的部隊部署在城內。別擔心，我也有很多打敗他們的經驗…我個人。\n\n我們會一個個削減他們的數量。", progress = nil, completion = "根本沒有辦法跟他們講道理。許多生命白白犧牲。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78184] = {title = "火藥與鏡子", objective = "收集8個血色十字軍炸藥。", description = "打開大門非常順利，但我們需要清出一條路讓軍隊前進。根據斥候回報，血色十字軍在那個區域囤積了一些炸藥。\n\n我們借來用用，他們應該不會介意吧？", progress = "嗯？", completion = "這麼好的炸藥不用可惜。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78185] = {title = "戰爭獵犬", objective = "開啟吉爾尼斯城的城門。", description = "我們應該已經享受到不少樂子了，對吧？\n\n駐紮在附近禮拜堂的血色十字軍似乎是他們最精英的部隊。相信我們能在那裡找出誰是他們的指揮官，不過獨自前往只是在找死。\n\n是時候出動吉爾尼斯的精銳部隊，奪回我們的城市了。我的部隊隨時都能出擊！", progress = nil, completion = "現在要來玩真的了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78186] = {title = "擊潰血色十字軍", objective = "在吉爾尼斯城禮拜堂的庭院殺死12個血色十字軍成員。", description = "<name>，血色十字軍最強的軍力都在他們首領的老巢鎮守。我就是從那邊進來的。\n\n要迅速拿下敵人，最好的方式就是先讓他們小小的分心。跟我說要在哪裡和在什麼時候動手就行。", progress = nil, completion = "很好。我的部隊會解決剩下的殘軍。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78187] = {title = "狂炸猛炸", objective = "放置6個炸藥。", description = "看來禮拜堂是他們的基地，而且戒備森嚴，他們在整個庭院設立了很多道防線。如果我們能拆除幾道擋路的防線，部隊圍攻時就會更有效率。\n\n記得那些我們收集的炸藥嗎？現在正是使用的好時機。", progress = nil, completion = "這樣我們的部隊就能輕鬆一點了。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78188] = {title = "公正之火，正義之怒", objective = "殺死血色十字軍的指揮官。", description = "現在我們與城市之間的唯一障礙只剩下一個人。做好準備，這可能會是硬仗。", progress = "她死了嗎？", completion = "我們成功了…重建會需要很多時間，但終於收復吉爾尼斯了！\n\n真是難以置信。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78189] = {title = "嶄新破曉", objective = "聆聽吉恩‧葛雷邁恩與泰絲的對話。", description = "自從我們被迫離開這座城市以來，很多事都變了。變的不只有這片土地，還有我們吉爾尼斯人。\n\n<name>，吉爾尼斯的未來，就由你來見證吧。", progress = nil, completion = "我…我不知道要說什麼。謝謝你，&lt;name&gt;。這一切都要感謝你。", rewards = "您會學到：\n\n套裝：吉爾尼斯貴族套裝\n\n您還會收到：\n\n吉爾尼斯徘徊者韁繩龍石"}
MultiLanguageQuestData['tw'][78190] = {title = "遺留之物", objective = "跟隨葛雷邁恩國王，隨時盯著他。", description = "他居然…把王國交給我。\n\n交給我耶！\n\n我需要一點時間去接受這個現實。不過…聽我說，<name>。我知道我父親是個堅強的人，但他有段時間實在讓自己繃得太緊，我很擔心他會垮掉。我並不打算阻止他，但能不能請你跟在他身邊，確保他沒事呢？請體諒一個女兒的一片孝心。\n\n或者該說是女王的孝心？", progress = nil, completion = "泰絲派你來的，對不對？那個女孩…很聰明，很有毅力，願意盡力守護她所熱愛的一切。那正是她成為出色領袖的原因。\n\n不用擔心我，&lt;name&gt;。我在這世上的職責還未了結。聯盟還需要我的長才，既然吉爾尼斯有了好的領導人，我終於可以全力以赴，迎接那個挑戰了。謝謝你的關心。\n\n也謝謝你這幾年來，為我的王國所做的一切。你展現了我還欠缺的能力，是我最好的表率。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78203] = {title = "繁盛綻放", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78206] = {title = "翡翠恩惠", objective = "參與翡翠狂亂，取得翡翠露珠並貢獻夢境種子以促進新生。", description = "這裡還有許多的物種有待發現和研究。在你探索夢境的同時，你會發現一種叫夢境種子的東西。請你培育它們來繼續我們的研究，然後好好享受它們分享給你的獎賞！\n\n夢境種子到處都有，但大多數都被夢境裡的強大生物給囤積起來了。\n\n另外，你也要注意一種我們稱之為翡翠狂亂的生命能量爆發現象。那是我們獲取大量翡翠露珠的途徑，而露珠則可以為夢境種子提供養分。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n沉重的夢境種子龍石"}
MultiLanguageQuestData['tw'][78215] = {title = "紮根於危險之中", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78226] = {title = "耐人尋味的邀請", objective = "到阿茲-卡罕特蛛絲城的地洞區與「輔臣」會面。", description = "我們收到一封邀請函。正確地說，收件人是你，<name>。\n\n輔臣想和你見上一面。就算是蛛絲城最富有、最有地位的人，聽到這個名字也會緊張不已。\n\n如果能得到這個人的青睞，我們就算面對安蘇芮克的陰謀詭計，也能勝券在握。\n\n你必須去地洞區見他。利用我放在巢穴的費洛蒙散發器偽裝自己，以便安全潛入。", progress = nil, completion = "我有點驚訝，你居然能在卡罕提找到盟友，&lt;name&gt;。\n\n對，沒錯。我還活得好好的。\n\n\n\n不怎麼讓人意外，是吧？", rewards = "這個任務線能解鎖：\n\n多恩諾加傳送門\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78228] = {title = "進入奔蛛城", objective = "將織絲者的計畫告知輔臣，然後施加費洛蒙，以便出入晦影市集。", description = "我送了這些「邀請函」給你和艾蘭里亞兩個人。我用我父親的劍打賭，你一定不會輕易放過這麼好的機會。那也正是你與我們所有人不同的地方。至於艾蘭里亞…\n\n別在意。她很有自信，但也非常謹慎。我的確希望她能多相信自己一點，不過謹慎才能讓她走得長遠。\n\n也許她之後就會來跟我們會合。現在，容我向你介紹我最近認識的朋友。", progress = nil, completion = "很大的排場。下次開會的時候，我應該也來模仿一下。\n\n&lt;尼茲瑞克咳了一聲，但你覺得比較像是竊笑。&gt;\n\n也許我們應該讓他們私下聊聊。在這段時間裡，也許你可以幫我個忙？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78231] = {title = "如同牆上的蜘蛛", objective = "探索晦影市集。", description = "邀請艾蘭里亞是有風險，但是，即使在此時此刻，我覺得那仍然值得一試。我很確定。\n\n我會自己跟她談。在此同時，我想要你前往上方的城市。尼茲瑞克給你的費洛蒙能讓你出入晦影市集。觀察那些商人，聆聽他們的對話，買點東西。\n\n這座城市跟暴風城一樣熱鬧。這裡的居民都應該和我們一樣，不該遭受虐待。你就親自去體驗彼此間的相似之處吧。", progress = nil, completion = "一群熱情的人民，就跟我們過去數十年來一起遇見的那些人一樣。\n\n他們理應和我們一樣，得到夢寐以求的和平和安全感。\n\n讓我們發誓，在被迫戰鬥時，我們對抗的永遠是衝突的源頭，而不是衝突的受害者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78232] = {title = "對洗腦者洗腦", objective = "覆寫3部投影儀。", description = "我們把你叫來這裡，是因為今天是「晉升日」。安蘇芮克女王紆尊降貴地稱這天是為了慶祝我們新發現的進化形態，灌注虛無之後的「晉升」。請留意我隱藏在話語之中的諷刺。\n\n儘管興高采烈的慶祝人潮讓街道充滿活力，遍布在市集的投影儀會四處散布安蘇芮克的惡意宣傳。\n\n帶著我的這個發明。對著那些投影儀使用，覆寫它們，讓它們向大眾散播更加…有啟發的資訊。", progress = nil, completion = "沒錯。輔臣也要我去其他城區做相同的事。\n\n我必須承認，我對安杜因的新盟友的疑慮稍微下降了一點。雖然不到一根小指的高度，但已經比我原先預期的要多了。", rewards = "您會收到：\n\n尼茲瑞克的立體影像操控器"}
MultiLanguageQuestData['tw'][78233] = {title = "織絲者的禮物", objective = "找到織絲者以示好意而透露給你的朋友。", description = "一隻小織蛛告訴我，北邊正在發生一系列有趣的事件。似乎出現極為巧合的一連串失敗，毀了那裡的軍事行動。\n\n我想知道是誰該負起責任。替我去調查一下，看看你古怪的雙眼能不能發掘出潛在的盟友。\n\n你的一些小朋友也在那些激怒某個「哲卡爾」的逃脫者當中。務必去了解一下情況。告訴他們，織絲者向他們…問好。", progress = nil, completion = "我以為我們藏得很隱密。\n\n顯然，沒有我們所想的那麼隱密。不過，我還是很高興看到你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78234] = {title = "強行突破", objective = "在拉克-薩卡茲擊殺8個卡罕提士兵。", description = "就算那個將軍已經走了，但還是很難離開這裡。這個地方被感染了。\n\n我知道自己藏得很好，但我覺得自己並不是處於最佳狀態。在這種情況下，我不確定自己能幫上多少忙。\n\n你必須為我們清出一條路。", progress = nil, completion = "在我自衛時，他們解除了我的武裝。還對我注射毒液。對了，在你看來，這像感染嗎？\n\n算了，就算這樣，我還是會盡可能幫上忙。我向你保證。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78236] = {title = "脫隊的一粒散沙", objective = "在拉克-薩卡茲救援脫隊者。", description = "要是有人脫隊了，我們就必須做點什麼。\n\n我不是在找藉口，但需要有人在這裡保護這些人。我必須留下來。\n\n找到這個脫隊者。找人的時候，順便看一下敵人後方陣地。看看你能不能發現有用的東西。", progress = nil, completion = "一切絕對都在我的掌控之下。\n\n&lt;弗林瑟縮。&gt;\n\n不過…我必須承認，這種毒素讓我原本快如閃電的反應能力變得遲鈍，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78237] = {title = "發射！", objective = "潛入準備運到攻城堡的箱子。", description = "嗯。所以是阿努巴札爾的命令導致囚犯逃跑。這裡的哲卡爾似乎對此非常不滿。\n\n不如這樣吧，你潛入攻城堡，跟阿努巴札爾成為最好的朋友。很簡單吧。\n\n我注意到有很多貨物運來這裡，我們把其中一個箱子的內容物調包，絕對不會有人發現。\n\n在此同時，我會向織絲者分享我們的發現。我很想跟你一起去，但我今天不想再被弗林捅了。", progress = nil, completion = "你還真是個有意思的「貨物」。\n\n你的確能為我所用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78244] = {title = "卡罕提的待客之道", objective = "當你準備好旁聽晉升日演說時，就跟安杜因說一聲，之後低調地離開城市。", description = "安蘇芮克將會在遠處的講臺上，發表她的晉升日演說。\n\n我、艾蘭里亞跟你必須想辦法爬到附近的一座塔上旁聽。如果我們想讓她的臣民反抗她，我們就必須盡可能親身經歷她的洗腦花招。\n\n我已經跟艾蘭里亞說過這件事，但我們不能洩露我們的行蹤。如果真的不幸遇上麻煩，輔臣已經在我們初次見面的地洞區外圍，幫我們安排好一組逃脫飛行者。", progress = nil, completion = "我們成功了。也許不像原本預期的那麼低調，不過至少還活著。", rewards = "您能選擇下列奬勵中的一個：\n\n女王之牙頸飾蟲群大將的護符操絲大師的項圈\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78248] = {title = "我們還擁有的東西", objective = "返回織絲者巢穴。", description = "我來到這座城市，準備…準備終結這場戰爭，就算犧牲性命也在所不惜。\n\n但我還活著。就跟你一樣，跟安杜因一樣。我們有了新的盟友，有了新的方向。在這一刻，我意識到，我的過錯蒙蔽了我的雙眼。\n\n這些話該由安杜因說，而不是我說的。我可能也被他影響了。\n\n我們一起回到你的織絲者巢穴吧。我很想看看你和安杜因如何拯救這些民眾，以及我們的族人。", progress = nil, completion = "我對執行官尼茲瑞克的懷疑不知道被他的真實身分「輔臣」轉移多少次了？也許我對間諜行動的敏感度不如以往了。我可是間諜專家欸！\n\n哈…也許是他本來就比我認為的還要厲害。\n\n知道某人在耍花招方面足以跟自己匹敵，真的讓人坐立難安。我們應該可以合作得相當愉快。", rewards = "這個任務線能解鎖：\n\n多恩諾加傳送門\n\n您還會收到：\n\n輔臣(惡名值)卡吉"}
MultiLanguageQuestData['tw'][78249] = {title = "特定人士", objective = "為阿努巴札爾將軍殺死哲卡爾的手下。", description = "哲卡爾最近把他幾個忠心走狗安插在攻城堡的重要位置。殺了他們就能迫使他調動和重新訓練一批手下，從而製造混亂。\n\n這一切絕對會讓哲卡爾感到為難。解決掉那三個傢伙。", progress = nil, completion = "哲卡爾知道是我搞的鬼。我就是要讓他知道。但他只能吃下這個啞巴虧，因為他無法製造自己的費洛蒙印記。一直以來，都是我代替他施加印記。\n\n要是他承認自己做不到，大家都會質疑他的權威…更不用提他身為奈幽蟲族的面子了。\n\n這會是很大的醜聞。", rewards = "偏愛者斗篷戰術大師披風傳承領主披氅細語者的罩氅您會收到：\n\n"}
MultiLanguageQuestData['tw'][78250] = {title = "將軍授意", objective = "為將軍尋找一些有用的威脅素材。", description = "這還不足以為哲卡爾帶來太多麻煩。應該讓他徹底蒙羞。我已經有了一些情報，但還不太夠。\n\n他把軍事記錄存放在某個小房間，但我體型太大，根本進不去。去看看他到底藏了什麼東西，我想那一定可以用來威脅他！", progress = "應該有我用得到的東西。", completion = "讓我看看！\n\n這…不是威脅素材。這是更糟糕的東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78251] = {title = "達拉然最悲慘的人", objective = "釋放囚犯，以便假裝運送囚犯。", description = "我完全不信任這隻大蟲子。他把我晾在那裡，什麼都不說！\n\n不過，要是他打算讓我們進入攻城堡，倒是可以加以利用。我看到有些人被拖進那個基地的其他地方。我不認為他們打算吃那些人。他們看來是要把那些人運到其他地方。\n\n把他們聚起來，假裝成運送囚犯的車隊，然後若無其事地離開。到外面找我！", progress = nil, completion = "哇…這也太多人了吧。\n\n但他們看起來很失落。幸好，這正是讓我計畫成真的好機會。\n\n這或許可行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78254] = {title = "失竊的影響力", objective = "竊取費洛蒙，準備偷偷運出攻城堡。", description = "哲卡爾保留的這些記錄…他讓為數眾多的奈幽蟲族喪命。把他們用過即丟，跟某些偏激的螳螂人一樣。\n\n我們必須展開行動。就像我說過的，哲卡爾因為晉升過程而再也無法製造他自己的費洛蒙印記。他不得不使用我的印記。他的鍊金師正試著為他製造人工印記…一旦他們成功，我的下場會如何？\n\n把那些假費洛蒙全部拿走，偷偷送出攻城堡。揭穿哲卡爾的陰謀，加以善用…你很有創意，對不對？大鬧一場就對了。", progress = "將軍要你去做什麼事？", completion = "把這些走私出去？嗯。\n\n我敢說我們之後用得到這些東西，不過…需要的話，我們會用它們逃跑。\n\n希望情況不會糟到這種地步。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78255] = {title = "保持自然", objective = "跟守門者攀談，協助車隊離開攻城堡。", description = "該帶著囚犯和那些費洛蒙一起離開這裡了。我找到了一些很有說服力的鐵鏈，畢竟我們的人實在太多了。如果大家都扮演好自己的角色，我覺得成功機率很大。\n\n阿努巴札爾將軍的標記氣味黏液只準備了我和你的份，所以我們扮演獲得准許的雄蟲。應對都交給你，我負責看好推車。希望這樣行得通。\n\n帶我們穿過大門吧，<name>！", progress = nil, completion = "我們短暫休息一下。所有人都在，對吧？", rewards = "您會收到：\n\n走私奈幽長褲走私奈幽腰帶走私奈幽長靴走私奈幽腕輪"}
MultiLanguageQuestData['tw'][78256] = {title = "將軍的共識", objective = "將哲卡爾的費洛蒙交給某個能善用它們的人。", description = "我們這次很走運。阿努巴札爾將軍很喜歡找哲卡爾的麻煩，而「敵人的敵人就是朋友」。\n\n我覺得這會變成一種常態：蜘蛛打算利用我們來搞內鬥。啊，好極了。\n\n我想你一定很想看到那些費洛蒙在某些地方派上用場，對吧？我會負責帶著這些傢伙脫離險境。", progress = "你有東西要給我嗎？", completion = "多麼美的禮物！\n\n阿努巴札爾將軍或許是個出色的盟友。我很滿意你的成果，備用糧。", rewards = "您會收到：\n\n將軍(惡名值)卡吉"}
MultiLanguageQuestData['tw'][78262] = {title = "一切始於龍石", objective = "透過擊敗獨特的生物、通過地城與團隊副本、完成世界活動或領取寶箱戰利品來取得50個龍石。然後，和庫佐斯談話，使用龍石來升級一件第3賽季的裝備。", description = "這片大地有許多秘密，還握有更多力量！\n\n而你…我們都清楚你很享受發掘秘密和收集神奇的裝備。當你準備好解鎖你在這片新大陸找到的裝備中的力量，就來找我跟庫佐斯吧。我們正在進行實驗，等你回來的時候就可以幫你升級裝備。\n\n屆時還請帶一些龍石跟一件新物品，這樣我才能向你展示升級是如何運作的。", progress = nil, completion = "看看那些閃閃發亮的東西！\n\n拜託，請收下這些禮物。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78271] = {title = "夢境紋章", objective = "透過擊敗獨特的生物、通過地城與團隊副本、完成世界活動或領取寶箱戰利品來取得15個幼龍夢境紋章。然後，和維史康談話。", description = "你已經學會基礎，能夠輕鬆升級較低等級的裝備了。\n\n不過，你遲早會找到更好的裝備，然後它們需要多種不同的夢境紋章才能升級。跟龍石差不多，這些紋章都可透過許多不同的活動獲得，彼此間也有所差異…夢境紋章共有四個等級 - 任務越危險，獎勵的紋章等級就越高。\n\n去幫忙完成任務，擊倒強大的敵人，找到寶藏，然後帶一些幼龍夢境紋章來給我！", progress = "我預見了夢境紋章所帶來的驚人成果。", completion = "好極了！這些紋章蘊藏龐大的力量。現在這些力量也將屬於你。", rewards = "您會收到：\n\n翡翠龍石一袋幼龍夢境紋章"}
MultiLanguageQuestData['tw'][78274] = {title = "極度呱噪", objective = "使用叭叭號角嚇跑10隻鴨子。", description = "又來了。你願意再幫忙一次，去嚇跑那群鴨子嗎？我必須留在這裡照顧好我這顆金蛋。", progress = nil, completion = "看他們還敢不敢！", rewards = "您會收到：\n\n明亮的彩蛋龍石"}
MultiLanguageQuestData['tw'][78289] = {title = "前往漫步郡", objective = "在漫步郡與蘆瑟菈會面。", description = "聽說雷首峰山腳下的漫步郡有麻煩了。\n\n我自己是不想住那裡啦，總是又潮濕又一直有雷聲。\n\n不過，禿鼻鴉照護員蘆瑟菈覺得那裡值得一看，因為禿鼻鴉很喜歡那個村落出產的苔蘚。不過她的經驗還很不足，可能需要人幫忙。", progress = nil, completion = "歐特溫派你來的？大概想念我幫忙刷禿鼻鴉的日子了吧。可是漫步郡這裡有點不對勁。\n\n上頭應該要有暴風雨的。從我有記憶以來就一直能從多恩諾加看到它。少了暴風雨，恐怕這地區的苔毛羊作業會有麻煩。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78290] = {title = "昏睡的綿羊", objective = "在漫步郡附近使用充能磁石來喚醒8頭昏睡的苔毛羊。", description = "這些羊群生產的苔蘚是風暴禿鼻鴉最喜歡的點心。可是現在暴風雨沒了，這些羊都昏昏欲睡、脆弱不堪，而且也不再生產苔蘚了。\n\n即使我們無法變出暴風雨，我們還是可以為苔毛羊充個電。你去找找看可以儲存電流的磁石，然後把它帶來這裡給蕭班德雷，讓她來為它充滿能量。", progress = "磁石應該可以儲存足夠的電力，讓苔毛羊有動力可以回到獸欄，又不會傷害到牠們。", completion = "苔毛羊看起來比較有活力了。希望牠們可以快點再次生產苔毛，當然，前提是暴風雨得回來。\n\n牧人史坦斯博認為他知道暴風雨消失的原因。他說有兩頭傳說中的山羊兄弟一年會為暴風雨充能一次，但牠們今年不知道為什麼沒有這麼做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78291] = {title = "強大掠食者", objective = "在漫步郡一帶除掉10隻掠食者。", description = "雷首峰通常有一場永久的暴風雨，當地的苔毛羊會從中汲取能量。少了暴風雨，可憐的寶貝們看起來無精打采，幾乎快要死了。這也讓牠們很容易被掠食者捕捉。\n\n為了讓苔蘚生產重回正軌，我們需要找到暴風雨消失的根本原因。但首先，我們需要擊退掠食者，不然牠們就要把苔毛羊都變成骨頭了。", progress = nil, completion = "這樣應該可以幫牧羊人跟羊群爭取一點時間，好讓我們能調查清楚暴風雨為什麼失蹤。沒有暴風雨代表沒有苔蘚，也就代表風暴禿鼻鴉會脾氣暴躁。\n\n據當地人傳說，暴風雨的產生是因為有兩隻傳奇山羊在雷首峰用頭對撞。他們覺得其中一隻山羊失蹤了，信不信由你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78292] = {title = "消失的風暴領主", objective = "在漫步郡附近找到杜張。", description = "聽好了，陌生人。每年一次，人稱南部風暴領主的偉大山羊杜張會穿越島嶼，在雷首峰上與牠的兄弟貝茲會合。牠們的羊角相互碰撞，喚來了暴風雨並帶來一年的豐收。\n\n可是現在情況不太對勁。杜張沒有來，天空也放晴了。風暴飛騎或許不相信，但我認為你的見識更為廣博。\n\n你還懷疑的話可以四處問問。請你幫我們找到杜張吧。", progress = nil, completion = "你找到牠了！可是為什麼牠還不來山上？還有，為什麼牠看起來這麼悲慘？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78293] = {title = "牠們的苔蘚，我們的收穫", objective = "從漫步郡苔毛羊身上收割苔蘚，並餵給杜張。", description = "你說奈幽蟲族捉了牠？我不知道他們想對老杜張做什麼，可是牠看起來受盡折磨。如果我們想讓牠上山挑戰牠的兄弟貝茲，可不能放牠這樣不管。\n\n從我們的羊群上剃下來的苔蘚通常會讓風暴禿鼻鴉更有精神，所以對杜張搞不好也有效果。去收集一斗的苔蘚然後獻給牠。\n\n如果苔毛羊發脾氣的話，記得要給牠們一點教訓。", progress = nil, completion = "那樣似乎就行了，我認為牠準備好要回去雷首峰找牠兄弟了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78294] = {title = "雷首頭槌", objective = "陪伴杜張到雷首峰上找貝茲。", description = "杜張看起來又再次變得硬朗有活力了。那些苔蘚效果還真強。\n\n我有預感牠準備好要上山了，真希望我們有更充裕的時間。我有好多問題想問。不過在牠到達頂峰時，最大的問題就會得到解答。\n\n我們不應該讓牠自己上去，但我認為牠夠信任你，會讓你帶牠上去。", progress = nil, completion = "傳說是真的。暴風雨、禿鼻鴉、還有這兩隻山羊。一切都息息相關。\n\n我還有好多事要學。不過謝謝你帶領我走上這條道路。", rewards = "您會收到：\n\n共鳴水晶共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][78301] = {title = "無賴角滑移賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78319] = {title = "繁盛綻放", objective = "參與繁盛綻放，並吃下出現的夢果。", description = "埃達希爾正在生長的階段，需要好好照護。親愛的老杉冠正在進行儀式，讓樹周遭的生命能夠成長茁壯，但我們的敵人似乎已經知道這件事了。我們需要各方的幫助。\n\n儀式進行期間，杉冠會汲取夢境的魔法讓夢果生長。吃下這些夢果會賦予你神奇的能力。不過這些強大且美味的果實只會長出一些些而已。到時候可要多加留意！\n\n英雄，懇請你伸出援手吧，你一定會得到夢境的回報。", progress = nil, completion = "啊，空氣中那甜美的花香！\n\n英雄，謝謝你。", rewards = "您會收到：\n\n綻放過剩寶藏箱"}
MultiLanguageQuestData['tw'][78325] = {title = "匕鞘灣突進賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78328] = {title = "到處看看", objective = "到禮品盛會找商人和賓客。", description = "在禮品盛會這裡有很多手藝精湛的工匠，專門為你和你喜歡的人製作禮物。\n\n你應該看看他們賣的東西，還有跟其他參加者聊聊。或許你能找到最適合某個人的禮物！", progress = nil, completion = "那些東西都很棒對吧！我其實有點嫉妒他們的才華…而且也很難忍住不拿起他們做的那些東西！\n\n有看到什麼吸引你的東西嗎？", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78329] = {title = "愛就在身邊", objective = "到暴風城的城門參觀禮品盛會。", description = "聞聞這些玫瑰！我的伴侶在禮品盛會替我拿來的。\n\n想自己去逛逛嗎？地點就在暴風城的城門。那裡擺滿了禮物和食物，尤其是巧克力，簡直讓人愛不釋手！", progress = nil, completion = "朋友，歡迎來到禮品盛會！\n\n你想進一步了解我們的特製巧克力嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78332] = {title = "嗅到問題", objective = "使用O.D.I.E.遙控器在暴風城各地尋找線索。", description = "你也聞到那個怪味道了吧？聞起來就像廢氣、廉價古龍水，還有鍊金術那一類的怪東西。我敢說，王冠化學製藥公司一定有什麼陰謀。想要幫我挖掘它的真相嗎？\n\n來，認識一下我的夥伴。看起來像是一隻土狗，但其實這是簡稱「O.D.I.E.」的嗅覺偵測與檢查引擎！有了這傢伙，我和你就能在一公里外嗅出王冠公司的陰謀！\n\n如何？你要加入嗎？我需要夥伴一起解決這件事。", progress = "O.D.I.E.是能夠嗅出線索，不過還是得你靠你來拼湊出真相。", completion = "有毒的香水？為了自己被踢出城市而復仇？\n\n看來藥劑師胡默爾又在策劃什麼陰謀了。不過竟然是致命劇毒？真是的，情況似乎不怎麼妙。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78334] = {title = "黑河溪流賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78337] = {title = "不請自來的禮物", objective = "在暴風城各處殺死8個王冠化學製藥公司成員。", description = "我嚴重懷疑王冠化學製藥公司的間諜已經混入我們之中。不過，我知道你知道這個O.D.I.E.知道如何鎖定他們的氣味！\n\n不過我們還是不要打擾到那些只是單純來享受過節氣氛的人吧。張大鼻孔聞出化學臭味，確保我們針對的是正確的目標。", progress = nil, completion = "哎呦，&lt;name&gt;，你太臭了！\n\n\n\n更慘的是，我也很臭！\n\n至少，我們讓慶典變得和平一點了。可不能讓王冠公司毀了這場慶典。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78346] = {title = "祖爾德拉克微風賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78348] = {title = "底層朋友", objective = "在氣坑中尋找你們的神秘保護者。", description = "在我們墜毀的時候，我們馬上就被奈幽蟲族團團包圍。要不是有人出手相救，我們幾乎會失去所有我們帶來的人。\n\n我不知道是誰，或是什麼東西為我們挺身而出。但如果我們在這個地方有一絲結交盟友的希望，那麼我們一定要緊緊抓住機會，絕不能鬆手。", progress = nil, completion = "啊！你活下來了。很好。你還有很多事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78350] = {title = "英雄永不消逝", objective = "援助12個受傷的空騎士。", description = "可惡！我們太急了，現在我的手下正為此付出代價。\n\n我們居然會蠢到認為奈幽蟲族不會對奇襲有所準備。阿拉希士兵個個都不是省油的燈，但就算是這樣也很難在飛船墜毀中安然無恙。\n\n我會在這裡保護所有人的安全。拜託，去戰場上盡你所能挽救人命。", progress = nil, completion = "我代替那些被你拯救的人向你道謝，&lt;name&gt;。沒有人應該獨自死在黑暗之中，至少不能是在這種地方。", rewards = "您會收到：\n\n獲救空騎士護臂獲救空騎士手套獲救空騎士盔帽獲救空騎士披肩"}
MultiLanguageQuestData['tw'][78352] = {title = "無用的抽取瓶", objective = "在氣坑各處摧毀8件奈幽蟲族的抽取設備。", description = "說實話，我一點都不在乎奈幽蟲族在謀劃什麼。他們並不是第一群突然冒出來尋求力量的競爭者，也肯定不會是最後一群。問題是他們達成目的的手段。我擔心他們肆意操弄黑血的行為，威脅到的遠不止是卡茲阿爾加那脆弱的生態系統。\n\n我們必須確保他們永遠無法回到這個坑洞。他們的設備還散落在坑洞各處。想辦法把它們破壞殆盡。", progress = nil, completion = "&lt;歐薇娜神色陰沉。&gt;\n\n奈幽蟲族雖然膽大妄為，但即使是對他們來說，這也太過極端了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78353] = {title = "畏懼古神之血", objective = "協助清理氣坑。", description = "這裡不是適合長談的地方，所以我會長話短說。\n\n你看到的這些根屬於某個大得超乎你想像的東西，而我的工作就是保護它們。\n\n對你來說應該顯而易見，這個地方充滿了扭動的黑血。如果我們袖手旁觀的話，這些東西只會散播得更嚴重且深入。\n\n你想要盟友？可以。幫我清理這個地方並保護這些根，那我至少會聽聽你的請求。", progress = nil, completion = "靠著你的汗水和我的法術，我們至少成功把麻煩遏制在這個充滿腐化的洞窟裡了。\n\n話說回來，這還真是場災難。如果一個洞穴的量就有這樣的威力，那麼光是想像奈幽蟲族能用更多的黑血做到什麼，我就不寒而慄。", rewards = "您能選擇下列奬勵中的一個：\n\n嘶鳴黑血戒指腐蝕黑血戒指\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78354] = {title = "引導之絲", objective = "跟隨引導之絲。", description = "<羊皮紙上的字看起來是用燒上去，而不是用寫的。毒素的強烈氣味灼燒著你的鼻子。>\n\n目盲且孤獨，你在黑暗中蹣跚而行。我提供一縷可以緊抓的絲線給你。\n\n如果你想找到你的盟友，那就跟著牠走。", progress = nil, completion = "看來你跟著我的引導之絲來到了終點。\n\n為了我們倆好，我很高興你的熱情勝過了你的生存本能。", rewards = "您會收到：\n\n網織腰帶網織踏靴網織腕甲網織之握"}
MultiLanguageQuestData['tw'][78355] = {title = "破碎夢境的精華", objective = "在『夢境希望』埃達希爾尋找麥琳瑟拉，並向她展示扭曲的夢境精華。", description = "<當你凝視著這奇怪球體的漩渦深處時，你感受到一個充滿哀傷、恐懼和憤怒的遠古回音。也許麥琳瑟拉會更了解這樣的東西？>", progress = nil, completion = "有意思…我在其中感受到瘤根微弱的遠古希望和夢想，卻因為伊吉拉的殘酷行徑變得黑暗且扭曲。感覺就像夢境本身正試著在這個精華之中阻斷她。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78356] = {title = "幼龍紋章", objective = "在使夢境重生的過程中，你功不可沒。作為回報，請收下這個獎勵。謝謝你一直以來的努力，勇士。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n龍石幼龍夢境紋章幼龍覺醒紋章"}
MultiLanguageQuestData['tw'][78358] = {title = "飛龍紋章", objective = "在使夢境重生的過程中，你功不可沒。作為回報，請收下這個獎勵。謝謝你一直以來的努力，勇士。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n龍石飛龍夢境紋章飛龍覺醒紋章"}
MultiLanguageQuestData['tw'][78363] = {title = "夢境外袍", objective = "到中央營地與守衛者安姆林談話。", description = "<梅希斯拉將一張有點潮濕的便箋塞進你手裡。>\n\n<name>，我們對你一直以來的幫助感激不盡。請來中央營地找我，讓我們可以為你的貢獻提供適當的獎勵！\n\n- 安姆林", progress = nil, completion = "你獲取的可不只這個外袍而已。這就是你夢想中的樣子嗎？", rewards = "您會收到：\n\n夢境守望者外袍巨龍群島補給品巨龍群島補給品巨龍群島補給品巨龍群島補給品"}
MultiLanguageQuestData['tw'][78364] = {title = "飛龍紋章", objective = "在使夢境重生的過程中，你功不可沒。作為回報，請收下這個獎勵。謝謝你一直以來的努力，勇士。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n龍石飛龍夢境紋章飛龍覺醒紋章"}
MultiLanguageQuestData['tw'][78369] = {title = "擊潰王冠公司", objective = "使用工匠糖果炸彈摧毀王冠補給品，並擊殺王冠公司成員。", description = "看來胡默爾設置了一些防衛措施。不過別擔心，我也帶了一些特殊的禮物。\n\n<凸栓指了指那個未標記的箱子。>\n\n炸彈。我帶了炸彈。\n\n遊戲時間結束了。拿炸彈丟那些王冠公司的人和他們的補給品。讓他們見識一下高超工藝的威力。等我們破壞了他們的行動，就能著手對付胡默爾了。", progress = nil, completion = "哇，我最喜歡煙火秀了！做得好，&lt;name&gt;。這應該能稍微拖慢他們的腳步。\n\n現在只剩下胡默爾了。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78370] = {title = "憂慮之爪", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78372] = {title = "飛龍紋章", objective = "在使夢境重生的過程中，你功不可沒。作為回報，請收下這個獎勵。謝謝你一直以來的努力，勇士。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n龍石飛龍夢境紋章飛龍覺醒紋章"}
MultiLanguageQuestData['tw'][78373] = {title = "夢境感謝你", objective = "到中央營地與安姆林談話。", description = "<梅希斯拉將一張有點潮濕的便箋塞進你手裡。>\n\n<name>，你對夢境的貢獻無與倫比。請來中央營地找我，我們要給你超棒的獎勵，請拭目以待。\n\n- 安姆林", progress = nil, completion = "謝謝你所做的一切。", rewards = "您會收到：\n\n附魔巨龍夢境紋章"}
MultiLanguageQuestData['tw'][78374] = {title = "龍石", objective = "在使夢境重生的過程中，你功不可沒。作為回報，請收下這個獎勵。謝謝你一直以來的努力，勇士。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78379] = {title = "復仇的惡臭", objective = "與凸栓談話，迎戰王冠化學製藥公司，並擊敗藥劑師胡默爾。", description = "除非解決幕後黑手，否則一切都還沒結束。\n\n我跟你說，藥劑師胡默爾就藏身在影牙城堡，帶著他的親信製作新一批毒香水。要是他的研究成功，暴風城的所有人都會沒命。\n\n你必須全力以赴，夥計。進入城堡、破壞他的陰謀，別讓我們所有人變成散發薰衣草香的屍體。", progress = nil, completion = "聽起來你及時趕到了。幹得好！\n\n要是讓胡默爾成功在慶典下毒，事情肯定會變得一團糟。\n\n就當這是送給他們的一份大禮吧！", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78381] = {title = "夢境合而為一", objective = "找到另一個破裂的夢境火花。", description = "又一個驚人發現，<name>！\n\n如果你可以把這個只有一半的夢境火花與另一半結合，它就能在你的製作過程中派上用場。\n\n去尋找另一個破裂的夢境火花，然後合而為一。", progress = "你找到另一個破裂的夢境火花了嗎？", completion = "真是天大的好消息！只要找到更多，就能繼續結合，讓你的製作裝備受益無窮。", rewards = "您會收到：\n\n破裂的夢境火花"}
MultiLanguageQuestData['tw'][78383] = {title = "戰略優勢", objective = "從拉克-薩卡茲的卡罕提士兵身上尋找弗林的武器和3個奈幽蟲族情報。", description = "雪上加霜的是，他們沒收了我的武器。沒拿回武器前，我不會離開！\n\n在找武器的時候，可以順便尋找證據，了解這裡發生了什麼事。只要是能讓我們在對抗奈幽蟲族時佔上風的東西都可以。\n\n這裡發生的怪事給了我們逃跑的突破口。我的直覺告訴我，那可能是值得利用的機會。", progress = "這附近一定還有對織絲者有用的東西…", completion = "這似乎足以向織絲者換來那個解毒劑了。阿努巴札爾是值得調查的線索。說不定他會像織絲者那樣，願意接受各取所需的交易，我們就能從他那裡得到更有用的東西。\n\n我覺得值得冒一下險。", rewards = "卡罕提徵收鑽孔機卡罕提徵收之鏟卡罕提徵收短匕卡罕提徵收十字弓卡罕提徵收燈籠卡罕提徵收圓盾卡罕提徵收之槌卡罕提徵收短斧卡罕提徵收法杖卡罕提徵收小刀卡罕提徵收之劍卡罕提徵收刀刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][78384] = {title = "追逐聖光", objective = "搜尋安杜因還活著的線索。", description = "安杜因在蟲群的攻擊中倖存。我對此沒有一絲的懷疑。即使如此，這裡到處都是奈幽蟲族，而他僅是孤身一人。\n\n不管他去了哪裡，不管他被帶到哪裡，我都會找到他。幫我找出他還活著的證明，只需要這樣，無論天涯海角，我都會去找他。", progress = "你回來了。\n\n我想你已經有消息了。", completion = "破碎的護手和一些碎布。不過沒看到屍體。這是好事，至少他還活著，而且還反擊敵人。\n\n不過，可用的線索不多。大多數的遊俠顯然會陷入困境。\n\n幸好，我不是普通的遊俠。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78385] = {title = "小型夢境種子", objective = "到[zone]與希薇亞‧颯茂談話。", description = "<Melsysra drops a slightly damp note into your hand.>\n\n<name>, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", progress = nil, completion = "為了感謝你所做的一切，請收下這些夢境種子。", rewards = "您會收到：\n\n小型夢境種子"}
MultiLanguageQuestData['tw'][78386] = {title = "翡翠復甦", objective = "到中央營地與依璃安娜談話。", description = "<梅希斯拉將一張有點潮濕的便箋塞進你手裡。>\n\n<name>，我們找到了把生物帶進夢境的方法。如果想進一步了解，請來找我！\n\n- 依璃安娜", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78387] = {title = "沉重的夢境種子", objective = "Talk to [NPC] in [zone].", description = "<Melsysra drops a slightly damp note into your hand.>\n\n<name>, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", progress = nil, completion = "感謝你所做的一切。請收下這些夢境種子。", rewards = "您會收到：\n\n沉重的夢境種子"}
MultiLanguageQuestData['tw'][78388] = {title = "大型夢境種子", objective = "Talk to [NPC] in [zone].", description = "<Melsysra drops a slightly damp note into your hand.>\n\n<name>, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", progress = nil, completion = "為了感謝你所做的一切，請收下這些夢境種子。", rewards = "您會收到：\n\n大型夢境種子"}
MultiLanguageQuestData['tw'][78389] = {title = "造物者馬拉松賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78392] = {title = "糾纏蛛網", objective = "仔細閱讀織絲者的文檔。", description = "不要誤會了，我沒有打算讓你像隻剛羽化的甲蟲一樣摸黑飛行。要是我的小不點被飢餓的洞穴鑽孔蠕蟲抓走的話，那可就不好了。\n\n你必須自己領悟，親愛的。你的盟友發現自己受困於灼熱的織網之中。你只能和它過去的建造者打好關係，才有希望找回他們。\n\n你很幸運，我會把我的一些個人資源借給你使用。", progress = nil, completion = "現在你已經看出舞台是如何搭建的。恐怕你已經身處演出之中了…但你無須擔心！你還有時間扮演最關鍵的角色。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78393] = {title = "似是而非的歇息", objective = "探索織絲者的巢穴。", description = "自那次不幸的小船之旅後，你已經度過了一個漫長的夜晚，不是嗎？別擔心，小不點。你會發現我這裡的朋友非常親切，即使是對與你有相同偏好的人…儘管他們可能很奇怪。\n\n請花點時間探索一下。我有許多便利的設施可以讓你使用。幸運的話，你也能休息一下，那是你現在最需要的。\n\n…哦，但請注意不要移動得太快。要是有突然的動作，你應該也知道後果。", progress = "沒必要害怕！我幾乎可以肯定我的夥伴不會吃了你。", completion = "如何？你喜歡我的熱情招待嗎？", rewards = "您會收到：\n\n織絲者(惡名值)卡吉"}
MultiLanguageQuestData['tw'][78398] = {title = "一點點礦物質…", objective = "從深淵潛伏魟身上收集魚骨頭。", description = "我認為我們這次有機會成功，<name>。不過，如果我們想看到這株植物順利成長，就必須開始讓土壤再次活化。\n\n請前往伊瑟拉之眼，從水中深處的深淵潛伏魟身上取得魚骨。它們的魚骨富含礦物質，並可輕鬆降解。雖然這樣還沒辦法讓土壤再度肥沃，但這卻是個很好的開始。", progress = "你成功拿到我要的東西了嗎？沒有魚骨，這株植物就無法順利成長。", completion = "這就是我要的。感謝你不辭辛勞去收集。\n\n你知道，這個形態並不適合游泳。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78421] = {title = "夢境之力", objective = "收集埃達希爾入侵者的回音元質和夢想。", description = "看來翡翠夢境本身也在抵禦這些入侵者，並以這些精華的形式留下他們夢想的陰影。離埃達希爾這麼近，就連你的行動也會留下力量的閃逝回音。\n\n也許有足夠時間的話，我們就可以利用這些回音復甦他們的力量，並轉而抵抗菲拉卡。擊敗你找到的入侵者，並在你收集足夠的夢境力量之後再回來找我。", progress = "夢境有好幾層，有些也十分脆弱。我擔心就連防衛者的存在都會改變這片永恆的大地。", completion = "這樣就夠喚醒沉睡在這些熾炎精華當中的力量了。終於，我們能夠利用入侵者的力量對付他們了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78427] = {title = "優質木箱！", objective = "與中央營地的瓦秀妮一起打包1箱貨物。", description = "夢境遭受的攻勢變得越來越猛烈。\n\n我們急需交易商品和補給品，才能守住防線。就算只有一箱物資，也能緩解前線承受的壓力。\n\n瓦秀妮可以協助你打包貨物。然後把貨物帶來給我。\n\n願伊露恩保佑你，夢境防衛者。", progress = "瓦秀妮會協助你準備貨物的。", completion = "你的貢獻令我們感激不盡。", rewards = "您會收到：\n\n沉重的夢境種子神秘種子巨龍群島補給品夢境守望者"}
MultiLanguageQuestData['tw'][78428] = {title = "打包的藝術", objective = "與中央營地的瓦秀妮一起打包5箱貨物。", description = "我們的儲備物資嚴重不足，$p。\n\n我們必須盡快補充我們的備用物資，以免讓敵人佔上風。我們需要的補給品數量遠超當初的預期。\n\n跟之前一樣，瓦秀妮可以協助你打包貨物。湊齊5箱物資後，請回來找我。\n\n願伊露恩保佑你。", progress = "一定要請瓦秀妮協助你準備貨物！", completion = "謝謝你，&lt;name&gt;。我們永遠銘記你的恩情。", rewards = "您會收到：\n\n大型夢境種子巨龍群島補給品夢境守望者"}
MultiLanguageQuestData['tw'][78429] = {title = "覺醒的夢境之力", objective = "喚醒融合精華中的力量。", description = "<name>，你準備好了嗎？我會幫你把他們熾炎夢境的精華融合在一起。你就專注在你收集到的回音元質上，喚醒其中沉睡的力量吧。讓菲拉卡瞧瞧，就連他也該畏懼夢境的力量！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n熾熱精華"}
MultiLanguageQuestData['tw'][78430] = {title = "難駕馭的綠色灌注機械", objective = "在翡翠夢境中擊殺6個魔花人和鞭笞者。", description = "很高興見到你。我叫依璃安娜，我是夢境研究員。\n\n最近我在夢境偵測到一個奇怪的現象。這裡的生物會留下夢境魔法的碎片。\n\n我很好奇，想知道這樣的魔法經過濃縮之後會有什麼樣的效果，但我需要有人幫我萃取出來。\n\n南邊有一些麻煩的鞭笞者和魔花人。\n\n殺幾個應該就夠用在次級的灌注上了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n里希羅"}
MultiLanguageQuestData['tw'][78431] = {title = "翠綠夢幻團隊", objective = "進行次級夢境灌注。", description = "太有趣了！\n\n我竟然能夠濃縮你帶給我的夢境能量。\n\n有了這個，我們就可以灌注了！\n\n開始吧，我會在旁邊看的。", progress = nil, completion = "太驚人了！成功了！", rewards = "您會收到：\n\n"}
