MultiLanguageQuestData['tw'][78441] = {title = "水晶之歌險境賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78444] = {title = "寶貴的盟友：夢境守望者", objective = "在翡翠夢境中協助夢境守望者與他們的盟友。", description = "對應該要維持平穩的大地來說，這改變太大了…\n\n夢境很少有這樣的破壞。這本應該是個和平的地方。也應該是個生命欣欣向榮的搖籃。\n\n勇士，我們會需要一切幫助。我現在命令你去尋求協助，並拓展夢境。\n\n我相信夢境一定會因為你的幫助而給予回報的。", progress = nil, completion = "&lt;守衛者安姆林深吸了口氣。&gt;\n\n空氣已經平靜下來了。雖然速度緩慢，但夢境又再次恢復和平。\n\n所有誓死保衛這裡的人都由衷感謝你，英雄。", rewards = "您會收到：\n\n夢境守望者徽記夢境背袋夢境守望者"}
MultiLanguageQuestData['tw'][78446] = {title = "支援協調者：繁盛綻放", objective = "前往翡翠夢境，協助杉冠實現繁盛綻放。繼續在巨龍群島各地協助沃卓肯協調者和他們的盟友。", description = "隨著翡翠夢境變得一片生機盎然，發育中的世界樹「埃達希爾」也開始蓬勃生長。\n\n古樹杉冠的儀式會強化世界樹周圍的龐大生命能量，促進其成長。協助保護和培育埃達希爾的人手越多，它的成長狀況也會越好！\n\n請助杉冠一臂之力。", progress = nil, completion = "啊，我幾乎能從這裡聞到風中的花香！\n\n請收下這份小小的謝禮，以及我們的感激之情。", rewards = "您會收到：\n\n沃卓肯寶藏龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記沃卓肯協調者伊斯凱拉巨牙海民"}
MultiLanguageQuestData['tw'][78447] = {title = "支援協調者：翡翠恩惠", objective = "前往翡翠夢境，將3顆任何品質的夢境種子種植在翡翠恩惠的土壤中。夢境種子可從夢境的大部分活動中獲得。繼續在巨龍群島各地協助沃卓肯協調者和他們的盟友。", description = "洪荒化身菲拉卡的部隊恣意肆虐翡翠夢境。在這場災難中，有些種子無法順利生根發芽。\n\n在探索夢境的過程中，相信你一定會收集到一些特殊的種子。請把它們種在土裡，細心培育，直到它們開花結果，聽說它們會與你分享豐厚的贈禮。\n\n去吧，幫助翡翠夢境中的生命開花結果！", progress = nil, completion = "夢境就是這麼奇特的地方！\n\n請收下這份小小的謝禮，以及我們的感激之情。", rewards = "您會收到：\n\n沃卓肯寶藏龍鱗遠征隊徽記伊斯凱拉巨牙海民徽記莫魯克半人馬徽記沃卓肯協調者徽記龍鱗遠征隊沃卓肯協調者莫魯克半人馬伊斯凱拉巨牙海民"}
MultiLanguageQuestData['tw'][78452] = {title = "增援 - 啟動", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78454] = {title = "龍骨荒野翔龍賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78457] = {title = "多恩諾加之石", objective = "在多恩諾加與各種土靈居民會面。", description = "我是梅里斯，是多恩諾加的議會守衛。\n\n我很感激你的援助，尤其考慮到你到來時發生的不愉快。請你務必原諒風暴守衛貝格姆。他的責任就是對人抱持懷疑。\n\n我們需要正式地討論我們的處境。如果你跟我們一樣，想要反擊奈幽蟲族，請到根基大廳跟我們會面。我和貝格姆需要審視一直以來的資料。\n\n在這同時，你是我的客人。把我的戒指拿去。有了它，你就可以使用多恩諾加的設施。", progress = nil, completion = "這麼多年來，貝格姆的戒備讓我們得以安全，可是今天，我們需要幫助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78458] = {title = "收割之災 - 啟動器", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78459] = {title = "團結的狀態", objective = "從梅里斯那裡了解關於多恩諾加議會的事情。", description = "我很不想承認，可是我們被奈幽蟲族攻擊得措手不及。\n\n我們的重點現在轉移到守護多恩諾加跟我們日益減少的人口。\n\n由於風暴守衛貝格姆有堅定的驕傲，讓他和風暴飛騎得以驍勇善戰，可是他們已經非常緊繃，而且他們也不懂建設。\n\n地心通途的損壞超越了我們能修復的程度。\n\n可是…情況不是一直如此。如果你想要理解的話，你必須更了解我們才行。", progress = nil, completion = "我們四分五裂。現在，我們的使命正遭受考驗。泰坦，請賜我們力量…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78460] = {title = "震源", objective = "在前往文庫的路上，清理殘骸並拯救土靈。", description = "我辜負了我的人民。地心通途現在無法通行。多恩諾加通往鳴響深淵的命脈已經斷了。\n\n奈幽蟲族會得到報應。這是我的律令，也是我的意志。\n\n我會確認議會守衛是否安好，並把他帶到文庫。代言者布琳瑟應該會在那裡，願泰坦保佑。\n\n可是還有其他誓語平民身陷危險。如果你想要跟我們結盟，請你清理這裡的殘骸，並幫助我們的生還者。\n\n我會到文庫與你會面。", progress = nil, completion = "你來了。\n\n很好。\n\n那是記憶寶石嗎？你不應該打擾我們的亡者。\n\n可是…你把它帶到對的地方來了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78461] = {title = "第四個席次", objective = "在多恩島的芙林村找到阿德貢。", description = "既然我爸跟安杜因現在很虛弱，艾蘭里亞又不見了，現在就要靠我們了，<name>，我們要為索爾跟珍娜的軍隊開路，才有機會反擊奈幽蟲族跟薩拉塔斯。\n\n沒有地心通途，我們就無法找到奈幽蟲族。而少了土靈的幫忙，我們就沒辦法修復地心通途。\n\n如果梅里斯認為這個阿德貢跟她的「無縛者」是唯一可以修復地心通途的土靈，那我們就得找到她。\n\n我該露出專業的微笑，戴上我的外交官帽了。<name>，你願意幫我嗎？", progress = nil, completion = "看來我別無選擇，只能聽你和貝格姆說。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78462] = {title = "憐憫的回音", objective = "在芙林村治療5位土靈居民。", description = "我今天最沒預料到的，就是見到貝格姆，更不用說得到他的幫忙了。但我想，既然地心通途損壞了，他也沒有選擇。我…不知道怎麼思考這件事，接受似乎是唯一合邏輯的做法。\n\n<阿德貢開始用她的石頭雙手碾碎蘑菇人的肉。它以令人不安的速度，很快地變成了糊糊的肉泥。>\n\n來，把這個跟泥土混在一起，為傷者敷藥吧。", progress = "我們以前擊退過動物和元素生物，可是，擊退奈幽蟲族？我的族人是工藝家和礦工，不是戰士。", completion = "&lt;阿德貢檢視茉艾拉、貝格姆，最後看向你。&gt;\n\n我…謝謝你。我已經很久沒有接受外地人…或是誓語者的幫忙了。", rewards = "復原粗陶法杖復原粗陶之斧復原粗陶燈籠復原粗陶懲戒錘復原粗陶盾牌復原粗陶火槍復原粗陶刺刀復原粗陶戰刃您會收到：\n\n"}
MultiLanguageQuestData['tw'][78463] = {title = "基礎材料", objective = "在礦石場收集20個閃亮礦石。", description = "採石場充斥著蘑菇人，所有的採礦坑道都崩塌了，但我們卻沒時間去除掉他們並重建礦坑！\n\n不過，在來這裡的路上，我確實在地上看到很多原礦可以撿。這會是修復地心通途開始，可是…\n\n<貝格姆嘆氣，憂愁地看著受傷的無縛者土靈。>\n\n這裡需要我，阿德貢的人民和我的人民都需要我。你可以代替我收集礦石嗎？", progress = "盡你所能收集吧。地心通途依舊是當務之急，但這些傷患急需幫助。", completion = "雖然不多，但這種礦石可以穩定地心通途。\n\n有阿德貢的協助後，我們就能奪回礦場和礦坑了，同時還能建立一條連接多恩諾加的補給線。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78464] = {title = "探究地底", objective = "在芙林村附近完成地行礦坑探究。", description = "奈幽蟲族的攻擊、你像隕石一樣墜落…\n\n然後現在貝格姆也來了？\n\n貝格姆需要更多人手修復他的地心通途，但是，我確實是有心無力。在這當下，我的人民正面臨死亡。我有一些族人在攻擊中被奈幽蟲族帶走了。\n\n你不是我遇到的第一個外來者。有個小傢伙，好像是叫茉艾拉，比你更早來到這裡，她毫不浪費時間，馬上去追奈幽蟲族，從西邊的小徑前往附近的洞穴。\n\n如果你能找到我的族人，就算是我欠你一份人情。", progress = nil, completion = "感謝你從奈幽蟲族手中救回我的族人。", rewards = "恐蛛探勘者弩恐蛛探勘者戰鬥法杖恐蛛探勘者戰斧恐蛛探勘者軍刀恐蛛探勘者打擊拳套恐蛛探勘者小刀恐蛛探勘者巨釘錘恐蛛探勘者法劍恐蛛探勘者權杖這個任務線能解鎖：\n\n探究夥伴\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78465] = {title = "戈葛林之境", objective = "在多恩島的戈葛林之境和達格蘭碰面。", description = "既然我們已經取得蛋白石，現在可以去戈葛林之境和布琳瑟見面了。\n\n她說她在那裡進行的計畫需要我幫忙。\n\n不知道會是什麼？", progress = nil, completion = "一個考古挖掘場？一座泰坦遺址？\n\n布琳瑟可沒跟我提到這個！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78466] = {title = "味覺之影 - 啟動", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78467] = {title = "為充能而衝", objective = "在戈葛林之境收集3個能量電池。", description = "我很高興達格蘭把你帶來。我有個危險的任務需要幫忙。\n\n我用了達格蘭的蛋白石來維修我們近期在此挖掘場找到的泰坦控制臺。\n\n誓語者一直以來都很想更加了解泰坦，並復原文庫中無法取得的紀錄，甚至是文庫建造之前的紀錄。\n\n如果我們能讓這個控制臺重新運作的話，它或許藏著一些答案。\n\n拿著這個我製作的裝置。既然現在它恢復了，就能帶你找到用來讓裝置恢復供電的泰坦電池。", progress = nil, completion = "&lt;name&gt;，做得很好。\n\n現在我需要達格蘭的幫助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78468] = {title = "文庫", objective = "使用稜彩寶典來查看記憶寶石，然後，把記憶寶石歸還到文庫裡的文庫房。", description = "你找到的記憶寶石功能就跟它的名字一樣。它包含了一位土靈的記憶、指令跟我們律令的寫死編碼。\n\n這座建築叫做文庫，是我們文明的樞紐，在職責輪替結束時，這些記憶會在這裡循環、分門別類後儲存。\n\n有了這個我發明的寶典，我們可以存取記憶寶石的一兩個記憶。把它拿去，讀取一下你找到的記憶寶石。", progress = nil, completion = "歐登會被保存在文庫內讓我感到很欣慰。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78469] = {title = "草原熱", objective = "檢視後將蕾卡的陶罐送去給芙林村的寇敦。", description = "我剛才應該去跟寇敦會面的，可是我跟死石頭一樣動彈不得。那場襲擊讓村莊…陷入癱瘓。\n\n<蕾卡深吸一口氣，然後專心端詳另一個罐子的形狀。>\n\n你可以幫我一個忙，把那些罐子拿去給寇敦嗎？他在村裡的陶器店裡，離這裡不遠。我必須在黏土乾掉之前，把這件作品完成。", progress = nil, completion = "&lt;寇敦小心地將陶器翻過來。&gt;\n\n弧形完美、沒有裂痕、瓶口圓滑…不愧是蕾卡。她是我們鎮上最厲害的工藝師。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78470] = {title = "舞臺", objective = "前往多恩島的舞臺。", description = "奈幽蟲族又在攻擊土靈了。我們必須跟著蟲群！\n\n我們恐怕寡不敵眾，但要是土靈能夠團結，和我們並肩作戰的話…\n\n我們或許有機會贏。", progress = nil, completion = "有人受傷！奈幽蟲族正在對土靈落井下石。\n\n&lt;茉艾拉突然指向戰場的中央。&gt;\n\n那裡！在中間…那是吉里克斯嗎？他又來了？還有…艾蘭里亞？\n\n喔，願山脈之力與我同在…我們必須幫助他們，&lt;name&gt;！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78471] = {title = "匯聚", objective = "返回多恩諾加的根基大廳。", description = "我們知道奈幽蟲族跟薩拉塔斯是盟友。而且我們也大概知道他們攻擊我們還有達拉然的原因。\n\n他們似乎一心想摧毀土靈一族，甚至是對他們落井下石。\n\n可是為什麼呢？是因為地心通途是關鍵，而且光是摧毀它還不夠嗎？或許我們現在在做的事：修復地心通途，正是他們不希望我們做的。\n\n我們應該回去多恩諾加，統合一下情報。", progress = nil, completion = "土靈議會重聚了。希望他們可以放下過去，修復地心通途。\n\n希望他們也會幫助我們對抗奈幽蟲族…以及薩拉塔斯。", rewards = "您會收到：\n\n凝結燼釀手套凝結燼釀肩鎧凝結燼釀戰靴凝結燼釀繫腰共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][78472] = {title = "暗中光源 - 啟用", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78473] = {title = "遺失的夢境之力", objective = "喚醒融合精華中的力量。", description = "你把熾熱精華弄丟了？這麼珍貴的東西竟然還會弄丟…我可以再給你另一個。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n熾熱精華"}
MultiLanguageQuestData['tw'][78499] = {title = "冰冠城塞突圍賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78529] = {title = "暴力衝擊", objective = "爬出礫石堆，並找到你倖存的領袖。", description = "<隨著你慢慢恢復意識，你感覺到視線在晃動。遠方的吼聲與尖叫在你耳鳴的耳中迴盪。\n\n你最後的記憶是達拉然，這偉大的魔法漂浮城市向地面墜落…接著是一片黑暗。\n\n混雜在叫喊與戰鬥的聲音中，你聽見奇怪、昆蟲一般的窸窣聲。\n\n奈幽蟲族在等你。\n\n你必須重新加入戰鬥，可是首先，你必須想辦法從無比沉重的礫石堆中逃生。>", progress = nil, completion = "&lt;name&gt;！你活下來了！\n\n很好。\n\n把武器準備好。戰鬥才正要開始。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78530] = {title = "殺死破壞者", objective = "殺死12個奈幽蟲族。", description = "到處都是奈幽蟲族，<name>。\n\n數量太多了，不可能全部都是空難生還者。我看到其他蟲族從地下鑽出來。\n\n這個女王近衛吉里克斯原本就在這裡等著要壓制我們。\n\n讓他們知道我們可不是待宰的獵物。消滅他們！", progress = nil, completion = "做得好。而且我們也有了進展。或許我們現在可以前進了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78531] = {title = "緊急協尋", objective = "協助7個達拉然空難的生還者。", description = "我們基本上沒受什麼傷。不是每個人都這麼幸運。\n\n在達拉然墜落時，許多在城裡的人都還下落不明。他們會需要我們的幫忙。\n\n去戰場上找生還者，盡你所能去幫他們的忙。\n\n我們需要更多戰力！", progress = nil, completion = "知道很多人都生還真是太好了。\n\n等這場戰鬥結束後，我們再把罹難者的遺體帶回來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78532] = {title = "不穩定的文物", objective = "摧毀5個受損的秘法聖物。", description = "達拉然有許多珍貴又強大的聖物。許多在達拉然墜毀時受到損壞，現在出現了故障。\n\n我們必須摧毀它們！\n\n把這個卷軸拿去，我在裡面注入了粉碎法術。大聲朗讀上面的咒語，就能釋放其中的魔法。\n\n等你完成後，向珍娜報告你的成果，她會懂的。", progress = nil, completion = "進一步破壞達拉然聽起來很不合常理。\n\n可是你跟埃薩做了對的決定。\n\n它們很不穩定，我們不能冒險，讓它們的力量被敵人濫用。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78533] = {title = "守住海灘", objective = "找到麥格尼並擊敗女王近衛吉里克斯。", description = "女王近衛吉里克斯從地底鑽出來，嚇了麥格尼一大跳。\n\n他在殘骸最遠端對抗他的蟲群。\n\n茉艾拉跟我想要幫忙把他們引開，可是我們失敗了。\n\n跟我來，麥格尼需要我們的幫忙！", progress = nil, completion = "外來者，即便你不是入侵者，你也不是我們的盟友。\n\n如果奈幽蟲族是你引過來的，那你也要為多恩諾加遭受的攻擊負起責任才行。", rewards = "這個任務線能解鎖：\n\n天空騎術\n\n您還會收到：\n\n淪陷城市紀念"}
MultiLanguageQuestData['tw'][78534] = {title = "前往多恩諾加", objective = "跟隨風暴飛騎順流，在多恩諾加與貝格姆會面。\n\n多恩諾加裡的多數服務在此任務期間將無法使用。", description = "你們為我們的海岸帶來了死亡與毀滅，我們這裡已經數千年沒有遇上這種災禍了。\n\n可是你手上有奈幽蟲族的血，身邊還有個瑟雷格。這足以讓你暫時贏得我的信任。\n\n我跟我的風暴飛騎必須回到我們的首都多恩諾加，調查很可能即將發生在那裡的攻擊行動。跟我們一起飛行。我們的順流可以讓你輕鬆地在空中翱翔。\n\n等到可以安全降落後，我會派其他風暴飛騎去接你的盟友。", progress = nil, completion = "奈幽蟲族做了什麼？又是為了什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78535] = {title = "他們從地下來", objective = "騎乘風暴禿鼻鴉洛克瑞，並殺死多恩諾加的奈幽蟲族。\n\n多恩諾加裡的多數服務在此任務期間將無法使用。", description = "外來者，我還不知道你來這裡的目的。可是你似乎…很擅長屠殺奈幽蟲族。\n\n就像我們風暴飛騎一樣，我們是這座小島的先鋒。\n\n奈幽蟲族是古老的敵人，如果吉里克斯知道並害怕我這個風暴守衛，我並不會意外。\n\n儘管如此，我們還是需要你的力量，協助我們保護多恩諾加。\n\n我有一頭風暴禿鼻鴉讓你騎。坐上坐騎，幫助我們把城市裡的害蟲除掉吧！", progress = nil, completion = "我不知道奈幽蟲族回來的原因…\n\n或是他們攻擊多恩諾加的原因。\n\n目前，我必須把重點放在評估地心通途的毀損程度。\n\n我們的機語者同胞可能會需要我們的幫助，而泰坦的意志是要讓通往艾澤拉斯中心的路途保持暢通。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78536] = {title = "渺茫機率", objective = "與索爾交談。", description = "泰坦在上…地心通途完全被毀掉了！這要花上數十年甚至數個世紀才能移除這些碎石，並修好奈幽蟲族對內部結構造成的傷害，更不用說是穿梭至星球的核心了。\n\n少了石縛者就要更久…\n\n我需要一點時間決定該怎麼做。\n\n你的朋友們已經安全抵達了。有話去跟他們說，別來煩我。\n\n如果我們需要你，我會讓你知道的。", progress = "必須對議會進行評估。我們會有很多事要做…", completion = "我的指令對你並不適用，外來者。", rewards = "您會收到：\n\n焦黑奈幽長袍焦黑奈幽護腿焦黑奈幽戰鎧焦黑奈幽頭盔共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][78538] = {title = "團體工作", objective = "在地心通途分發梅里斯的命令給10個無縛工人。", description = "無縛者已經帶著所需的設備和資源抵達，可以開始修復地心通途。\n\n對文庫來說，這是一個重要的時刻！我不會對阿德貢這麼說，可是我覺得這一切都是泰坦的安排…\n\n現在，我該執行我的命令了！我制定了一個計畫，可以用最有效率的方式分派我們的工人，我也分配了補給品來歡迎他們。\n\n把這些命令拿去給阿德貢的工人，他們就可以開始認真工作了。我們很快就會去那裡找你。", progress = nil, completion = "就算有這麼多工人，地心通途的修復工程還是會需要時間。\n\n在這同時，我們需要決定該怎麼做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78539] = {title = "永續修補", objective = "與貝格姆討論攻擊奈幽蟲族的計畫。", description = "由於我的風暴飛騎…無法出擊，多恩諾加毫無防備，只有幾個業餘的保安官。如果奈幽蟲族再次攻擊，多恩諾加就會淪陷，我們也會跟著陣亡。\n\n當務之急是把他們趕出城市，並除掉他們的指揮官。\n\n我們可以製作自己的網，用它捉住吉里克斯。\n\n我有個計畫。", progress = nil, completion = "那就決定了。\n\n我們會堅守燼釀酒莊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78540] = {title = "前往酒莊", objective = "在燼釀酒莊與貝格姆會面。", description = "你的弓手朋友是對的。我們必須消滅吉里克斯和他的部隊，才能確保地心通途的安全。\n\n讓我們立刻前往燼釀酒莊吧。", progress = nil, completion = "感謝泰坦！奈幽蟲族還沒有展開掠奪蜜酒的行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78541] = {title = "布置陷阱", objective = "將4條繩索引信連接到滾燙的酒桶上。", description = "有這麼多燼釀酒桶，如果把它們全部點燃，這座酒莊會燒得比熔爐地還熱。\n\n我猜溫布蘭特的酒桶材質都是結實又堅固的鐵木，就是因為這個原因，它們不容易破裂或著火。\n\n幸好，如果我們把每個酒桶都插上引信，就可以從內部引起反應。\n\n工人留下來的繩子可以用來應急。", progress = nil, completion = "吉里克斯會死在我手上。這是我的指令，是我的意志。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78542] = {title = "疏散地區", objective = "疏散8個無縛釀酒工人。", description = "聽著，如果我們別無選擇的話，你可以把我的畢生心血炸掉，可是我絕不會讓我的工人身陷危險。\n\n這都是我們自己選擇的道路，可是我不會讓他們為了一場火或奈幽蟲族犧牲。跟他們說，我叫他們要立刻離開這裡。\n\n如果他們有任何人受到一點擦傷，我就會找議會算帳！", progress = nil, completion = "他們懂得配合乖乖清場讓我真高興。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78543] = {title = "戳刺蜘蛛巢穴", objective = "將一桶燼釀蜜酒桶丟進奈幽蟲族地穴，然後返回蜜酒園。", description = "酒莊已經疏散完畢，炸藥也準備好引爆。現在該把奈幽蟲族引入我們的陷阱中了。\n\n你的同胞就在北邊的奈幽蟲族地穴附近。她跟我說她的指令是看守地穴，確保奈幽蟲族在我們準備好之前不會輕舉妄動。\n\n目前他們沒有動靜，現在可能會需要…哄騙。把一桶燼釀蜜酒拿到地穴去。把它丟進去應該就能驚動他們的「巢穴」。\n\n完成之後就盡快回來蜜酒園跟我們重新會合。", progress = nil, completion = "奈幽蟲群正在往這裡來。\n\n準備好戰鬥吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78544] = {title = "雷霆交加", objective = "在燼釀酒莊抵禦奈幽蟲族，直到女王近衛吉里克斯現身。", description = "奈幽蟲族會憤怒且驕傲地出擊，這正是我們想看到的。\n\n他們很快就會成群衝進酒莊，想要報復我們攻擊他們的地穴。我們會在地上迎戰他們，你負責飛在天上作戰。等吉里克斯出現，要指揮他的軍隊時，我們就把引信點燃。\n\n溫布蘭特收集了一些我們可以用來圍攻奈幽蟲族的物資。趕快把它們設置好，接著我們會讓你騎上風暴禿鼻鴉，去吧！", progress = nil, completion = "吉里克斯死了。我們成功了。任務結束了。貝格姆辦到了。\n\n&lt;她向自己一遍又一遍地重複最後一句話，聲音漸漸變弱，彷彿她無法消化眼前的事件。&gt;", rewards = "您會收到：\n\n蜜斑窄褲蜜斑外衣蜜斑全罩頭盔蜜斑腿甲"}
MultiLanguageQuestData['tw'][78545] = {title = "返回地心通途", objective = "返回多恩諾加找梅里斯。", description = "我們重創了奈幽蟲族的勢力，可是貝格姆…\n\n<阿德貢暫停了一下，讓自己冷靜。>\n\n他非常固執，我們以前爭吵不斷，可是最後…他保衛了我們的族人…所有的人。\n\n貝格姆犧牲了自己，以確保多恩島不受奈幽蟲族的威脅。每個人都必須知道這點…我們也不能再讓奈幽蟲族把我們逼成這樣了。\n\n回去多恩諾加找梅里斯。跟他說我們很快就會回來。我們只是…在這裡還需要一點時間。", progress = nil, completion = "你還活著！可是其他人呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78546] = {title = "回報", objective = "與阿德貢交談，把貝格姆的下場跟梅里斯說。", description = "我們在這裡有聽到爆炸的回音。\n\n我猜你們贏了，可是，看到你單獨前來代表不是一切都那麼順利。\n\n發生什麼事了？", progress = nil, completion = "希望我們都能效法貝格姆的英勇。\n\n他犧牲自己保全了我們的族人…我們的團結。我們不能讓他的犧牲白費。", rewards = "您會收到：\n\n礫石回收軟靴礫石回收之握礫石回收護腕礫石回收肩墊共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][78555] = {title = "身處地底，不知所措", objective = "幫助機語者奪回曳鐵運輸站。", description = "我已經離開太久了。顯然機語者在這裡混得不是很好。至高代言者知道這件事嗎？\n\n奈幽蟲族的破壞和嚴重的疏忽是最糟糕的組合。我們必須盡快讓曳鐵運輸站重新運作。這裡是鳴響深淵和上方城市的重要連結。\n\n$p，請你幫助我們受傷的工人，收集任何可以再利用的貨物，讓曳鐵運輸站再次變得安全。", progress = nil, completion = "謝謝你幫助工人們振作起來。你成功恢復了秩序，或者該說至少能讓我們返回崗位工作的程度。\n\n想讓工頭烏茲傑克斯留下好印象，最好的方式就是把工作做好，而你做到了。\n\n*壓低聲音*…小心一點。他對當權者忠心耿耿，所以我們必須注意我們的言辭。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78557] = {title = "脫離正軌", objective = "在曳鐵運輸站調查脫軌的礦車。", description = "代言者布琳瑟認可了。外來者，有工作要做。\n\n我們的其中一台大型礦車脫軌，把運輸站的主要交會點擋住了。\n\n我的工人士氣低落，因此沒辦法發揮太大的作用。泰坦讓我們在這裡工作，但我的工人卻一點作用都沒有。你可以幫助我們重回正軌嗎？\n\n請務必小心。我可以看出來你是有血有肉的活人，所以我不希望你被壓扁。", progress = nil, completion = "請求回報。你找到什麼了嗎？\n\n你說什麼？一個「斯卡汀」？\n\n這個情報跟我派給你的任務無關。請專心工作。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78558] = {title = "休拉薩嬉戲賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78562] = {title = "散了，壞了", objective = "收集機械工基特林遺失的工具。", description = "喂，就是你！你是來幫忙的，對吧？\n\n機器的嗡嗡聲正在改變，而我…我承認我還沒準備好。這麼多年來，我一直兢兢業業，然後…\n\n總之，重點在於我準備好重回工作崗位了。不過你也看到了，我的工具全都壞了，還散落各處。\n\n如果你可以幫我留意一下，把工具帶回來給我，算我欠你一份人情。", progress = "沒有工具，機械工就毫無用武之地。", completion = "我的量錶！我的卡尺！我的扳手！\n\n再次把它們拿在手裡的感覺真好。不過，我必須承認，我其實沒向你全盤托出。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78563] = {title = "世界之重", objective = "收集機械工基特林的校準砝碼。", description = "我的工具會出現在你找到它們的地方並非偶然。其實它們是被我放在那裡的。\n\n我曾經失意到萬念俱灰的地步。那些機器是我同胞的傑出作品，它們卻再也無法動起來了。那麼我為什麼還要費功夫去修理它們？\n\n但我現在懂了，也理解了！\n\n我需要的最後一件工具，被我丟進水中，還被一隻巨大生物吞了。那傢伙可能需要吃點苦頭，才願意把它還給我。", progress = "一旦拿回所有工具，一切就會再次回到正軌。", completion = "&lt;基特林似乎毫不在意校準砝碼沾滿的腸液。&gt;\n\n你找到它了！現在我來把這東西清理乾淨，再把其他的工具修好。然後，我就能重回工作崗位了。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78564] = {title = "改頭換面", objective = "幫助機械工基特林重鑄並重新運用工具。", description = "萬事俱備了！現在該來履行職責，重鑄這些工具。讓它們和我找回原有的功用。驕傲的鳴響深淵機械工。", progress = nil, completion = "謝謝你一直以來的幫助，真是感激不盡。我曾經失去信念，但是現在，我又尋回了我的信念和工具。\n\n我永遠感激你。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n共鳴水晶共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][78565] = {title = "灰白之丘景點傳送門", objective = "經由景點傳送門前往灰白之丘，為蓋寶摘一束花。", description = "本日主打的是前往北裂境宏偉森林的魔法之旅！\n\n對了，你也是冒險者，對吧？聽著，我想請你幫個忙。\n\n你能幫我到灰白之丘摘些花嗎？我現在分身乏術，但我卻又想送某個人一束花。", progress = "我另一半一定會很喜歡這些花。", completion = "感激不盡，&lt;name&gt;！\n\n希望你喜歡徜徉在那些山丘之間！在那裡，新發現俯拾即是。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78570] = {title = "破損的遺跡", objective = "到多恩島的叢根盆地找伊格莉絲。", description = "保持真誠，<race>t。\n\n我們林野守衛秉持著對芙蕾雅自古以來的承諾，照顧著這片土地。我們的律令歷史比多恩諾加的煽動者接受的律令還要悠久。甚至比多恩諾加本身還古老。\n\n然而，不是每片土地都受到同樣的照護。我們護衛長應該要負責照顧底下的盆地，可是我們很久沒有聽到他的消息了。\n\n我派了一位新手去調查。協助他，我的護衛隊就會欠你一個人情。", progress = nil, completion = "這不是這片盆地該有的樣子。我們有很多工作要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78571] = {title = "菌菇麻煩", objective = "在叢根盆地從蘑菇人身上收集30個叢根孢子。", description = "芙雷德琳是守衛隊的隊長。我被派到這裡來協助她，但我來晚了。\n\n這片山林遭到黑暗的侵擾，<race>s。\n\n這片山林是芙雷德琳的家，由她負責照顧它們，這是由守衛者親自授予的任務。現在她不在了，而她的山林變得一團糟。\n\n把這些壞蛋的孢子帶來給我。或許我們還有辦法淨化這塊土地。", progress = "你都收集到了嗎？", completion = "謝謝你，&lt;name&gt;。我會仔細研究它們。這片山林的蘑菇人造成的威脅比我們原先預期的還要大。\n\n我們必須阻止他們的擴散。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78572] = {title = "山野的記憶", objective = "在叢根盆地搜查芙雷德琳的家，找出對抗蘑菇人的方法。", description = "芙雷德琳之前一定有辦法抵擋蘑菇人。\n\n雖然鄉下依然遵守律令的人已經很少了。但芙雷德琳一直以來都是虔誠的信徒。在她還信奉律令的時候，她絕不會讓這片樹林變成這副德性。\n\n我們應該要去看看她在樹林裡的家，也許裡面有一些東西可以幫上忙。", progress = "翻動林野守衛的物品讓我很不安，有太多不為人知的故事了。", completion = "這根法杖蘊含著熟悉的魔法，是我一直想忘記的。噢，芙雷德琳，這裡發生了什麼事啊？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78573] = {title = "守衛者的援助", objective = "使用芙雷德琳的木杖來淨化叢根盆地。", description = "魔法杖？結界？芙雷德琳，你到底都在幹什麼啊？\n\n<伊格莉絲沉思了一會，她的眉頭緊皺，雙眼炯炯有神。過了一會，她臉上帶著微笑看向你。>\n\n我知道了！\n\n這根法杖裡的生命能量應該可以克服這裡的野生動物身上的真菌腐化。之後再讓牠們回歸到自然的循環中，土地就會慢慢地自我修復了。\n\n如果你看到任何結界，就把它們解除。把她的記憶寶石拿去以防萬一。裡面可能還會有更多情報。", progress = nil, completion = "真是太有意思了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78574] = {title = "林區之首", objective = "在叢根盆地擊敗『不倒者』腐皮。", description = "我還有最後一件事要請你幫忙。\n\n這片山林裡有一頭巨大的怪物在其中遊蕩。你一定也感覺到了。我們必須除掉它。\n\n腐皮是芙雷德琳用來控制這個盆地的最終手段，可是就連它對土靈來說都太超過了。我們的任務不是要控制，而是要照顧它的需求。\n\n再次使用這根法杖，終結腐皮的霸權吧。", progress = nil, completion = "腐皮的死亡代表這座盆地的情況不會再惡化了。\n\n謝謝你，&lt;race&gt;。你的協助是無價的。", rewards = "您會收到：\n\n含孢兜帽含孢風帽含孢護脛含孢鎖子甲共鳴水晶多恩諾加議會"}
