MultiLanguageQuestData['tw'][78589] = {title = "入侵的美食", objective = "將幽影茄子交給真菌農田的迪奈爾大廚。\n\n已提供物品：\n", description = "<這個罕見的植物或許對迪奈爾大廚有用。>", progress = nil, completion = "雖然不是人人都覺得幽影茄子是美味的食物，但只要是我來烹飪，就一定會大受歡迎！", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
