MultiLanguageQuestData['tw'][78591] = {title = "納葛蘭景點傳送門！", objective = "經由景點傳送門前往納葛蘭，為碧翠絲拍攝野生動物的照片。", description = "本日主打的是前往納葛蘭廣闊平原的魔法之旅！\n\n要是你去了那裡，你願意幫我拍一拍動物嗎？喔，別誤會了。來，我的相機借你。\n\n我的朋友碧翠絲最近都在那裡流浪。她一定會喜歡那些相片，不過我得在這裡顧傳送門。", progress = nil, completion = "我知道碧翠絲一定會喜歡你的照片。\n\n謝謝你這麼好心，&lt;name&gt;。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78594] = {title = "菲拉斯景點傳送門！", objective = "經由景點傳送門前往菲拉斯，將丟失的禮物交給正確的失主。", description = "本日主打的是前往菲拉斯陽光沙灘的魔法之旅！蒸汽之池渡假村正在舉辦歡樂慶典，歡迎任何人參加！\n\n不幸的是，先前有些糊塗的人穿過傳送門，卻把自己的禮物留在這裡。\n\n你能幫我把這些禮物還回去嗎？到沙灘找我，我們一起找出禮物的失主吧。", progress = nil, completion = "多謝幫忙，&lt;name&gt;！看到自己的禮物失而復得，大家都很開心。\n\n而且禮物未免太多元了吧！或許大家表達愛意的方式都不一樣。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78595] = {title = "夢境灌注", objective = "到中央營地與依璃安娜談話。", description = "<梅希斯拉將一張有點潮濕的便箋塞進你手裡。>\n\n<name>，你的作為協助取得進行夢境灌注所需的力量。請來中央營地找我，好讓我為你施法。\n\n- 依璃安娜", progress = nil, completion = "開始灌注！", rewards = "您會收到：\n\n夢境灌注"}
MultiLanguageQuestData['tw'][78596] = {title = "葛雷邁恩大人的傳召", objective = "到暴風港與吉恩‧葛雷邁恩碰面。", description = "你好。\n\n葛雷邁恩大人請你到暴風港一趟，幫助他處理有關吉爾尼斯的事。\n\n我要轉達的內容只有這些。\n\n祝你好運，<name>。", progress = nil, completion = "&lt;name&gt;，感謝你來。\n\n讓我向你簡短說明一下這次的任務。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78597] = {title = "秘密行動", objective = "到銀松森林的焚木村與莉莉安和卡莉雅碰面。", description = "<name>，\n\n莉莉安‧佛斯和卡莉雅‧米奈希爾請你加入吉爾尼斯的秘密行動。\n\n等你到了，他們會再跟你說明詳情。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78598] = {title = "夢境灌注", objective = "你的付出讓我們掌握了進行另一次夢境灌注所需的力量！做得好。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n夢境灌注"}
MultiLanguageQuestData['tw'][78600] = {title = "『夢境希望』埃達希爾：灰飛煙滅", objective = "在普通難度的『夢境希望』埃達希爾中，從斯莫德隆身上收集3個餘燼之痕碎片。", description = "斯莫德隆似乎在協助菲拉卡攻打夢境！若你能收集他那把傳奇武器餘燼之痕的碎片，我們就能夠與他的能量同調，然後直接襲擊他的王座了。", progress = "這些碎片中的能量能讓我們快速前往火焰之王的王座。", completion = "這樣應該能讓我們更輕鬆地前往斯莫德隆的王座。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78601] = {title = "『夢境希望』埃達希爾：灰飛煙滅", objective = "在英雄難度的『夢境希望』埃達希爾中，從斯莫德隆身上收集3個餘燼之痕碎片。", description = "斯莫德隆似乎在協助菲拉卡攻打夢境！若你能收集他那把傳奇武器餘燼之痕的碎片，我們就能夠與他的能量同調，然後直接襲擊他的王座了。", progress = "這些碎片中的能量能讓我們快速前往火焰之王的王座。", completion = "這樣應該能讓我們更輕鬆地前往斯莫德隆的王座。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78602] = {title = "『夢境希望』埃達希爾：灰飛煙滅", objective = "在傳奇難度的『夢境希望』埃達希爾中，從斯莫德隆身上收集3個餘燼之痕碎片。", description = "斯莫德隆似乎在協助菲拉卡攻打夢境！若你能收集他那把傳奇武器餘燼之痕的碎片，我們就能夠與他的能量同調，然後直接襲擊他的王座了。", progress = "這些碎片中的能量能讓我們快速前往火焰之王的王座。", completion = "這樣應該能讓我們更輕鬆地前往斯莫德隆的王座。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78607] = {title = "前往米雷達爾", objective = "前往米雷達爾，與鐵擊將軍會面。", description = "我們必須去米雷達爾，向鐵擊將軍報告黑夜教團在這裡的行動。\n\n感謝聖焰，我們阻止了他們，沒讓他們造成更大的傷害。", progress = nil, completion = "總算能休息一下了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78608] = {title = "地熱遊覽賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78613] = {title = "聖落之地的堡壘", objective = "探索米雷達爾。", description = "我必須承認，我從沒想到第一個來到米雷達爾的訪客會是外來者。我以為帝國…算了，沒事。\n\n你幫了我族人很大的忙，這點值得表揚。米雷達爾是阿拉希在聖落之地的堡壘。請好好休息一下。", progress = "這座城市有很多值得一看的地方。", completion = "真好，能坐下來喘口氣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78614] = {title = "米雷達爾之光", objective = "與3個阿拉希孤兒一起玩耍。", description = "多給我一點時間向艾蘭里亞請教有關薩拉塔斯的事。我目前得知的內容讓人非常擔憂。\n\n法林傳話表示她正前往孤兒院，要你去那裡找她。\n\n當她還在米雷達爾的時候，她經常陪那些孩子玩，我很肯定她一定會感激你做跟她一樣的事。", progress = nil, completion = "每次到米雷達爾的時候，我都會來這裡。這些孩子總是能讓我露出微笑，希望他們看到我也一樣。\n\n在經歷了那麼多磨難後，他們值得擁有快樂的童年。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78615] = {title = "鐘聲響起", objective = "前往聖落之地的米雷達爾大門。", description = "那些鐘聲代表米雷達爾正在遭受攻擊！\n\n我們一起前往大門，看看發生什麼事。", progress = nil, completion = "我們會讓他們為此付出代價，&lt;name&gt;。\n\n我們會痛扁他們一頓，讓他們再也不敢回來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78616] = {title = "高科技占測：和睦觀測所之謎", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78618] = {title = "真菌大爆發", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78620] = {title = "暮光叉路", objective = "在聖落之地的崇敬之地擊殺15個寇拜斯攻擊者。", description = "我們必須把崇敬之地從寇拜斯手中搶回來。\n\n把牠們趕回去，用牠們的屍骨鋪出一條血淋淋的路。\n\n不管永恆火焰出了什麼事，我們都必須加以制止。如果牠們像腐化高塔那樣腐化它的話…我都不敢想像會發生什麼事。", progress = nil, completion = "現在，我們只需要解決那個護罩。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78621] = {title = "暗影籠罩", objective = "在聖落之地的崇敬之地殺死寇拜斯深淵語者。", description = "我可以感應到前面有三個虛無信標，全部都在將力量注入巨大的黑暗泉源。\n\n你必須殺了他們，等他們死後，我就可以解除那個護罩。", progress = nil, completion = "非常好。\n\n現在該突破這個護罩了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78624] = {title = "黑暗中的蠟燭", objective = "在聖落之地的崇敬之地殺死艾爾里克‧雷德。", description = "巴雷達爾已轉變為暗影，我們必須撤回米雷達爾！\n\n<瓦麗西亞看向艾爾里克‧雷德。>\n\n我…不。我們必須先殺了艾爾里克。\n\n我們去打倒他，然後就撤退。", progress = nil, completion = "願聖光祝福法林。\n\n我原以為失去了永恆火焰。\n\n我原以為早已失去一切希望，族人只有死路一條。", rewards = "您會收到：\n\n烈焰守衛指環"}
MultiLanguageQuestData['tw'][78626] = {title = "比劃日", objective = "在米雷達爾與8名阿拉希新兵決鬥。", description = "你的戰鬥技巧令人驚豔，<name>。\n\n我們正準備讓下一批後備軍正式開始執勤，但他們的能力卻還有待磨練。\n\n在艾蘭里亞跟我交代有關「薩拉塔斯」的事時，要是你能去協助他們訓練，我會非常感激。", progress = nil, completion = "謝謝你。\n\n他們從你身上學到的東西，之後一定能救他們一命。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78627] = {title = "最終前線", objective = "前往聖落之地的聖光壁壘。", description = "就在寇拜斯攻擊前，我們收到了利維亞的耐心附近出現干擾的消息。現在我們知道起因了。\n\n我們…聖光…我們無法兼顧兩個前線，<name>。我們必須阻止這件事，立刻。", progress = nil, completion = "聖焰啊，他們穿過湖床竄出。\n\n利維亞的耐心已經淪陷了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78628] = {title = "觸發陷阱門", objective = "在聖落之地的利維亞的耐心殺死15個奈幽蟲族。", description = "我們需要時間備妥清算號。帶著你的好友，盡全力阻擋奈幽蟲族。\n\n他們對我們人民做出這種事，唯一的下場就是死。", progress = nil, completion = "做得好，&lt;name&gt;。奈幽蟲族居然還沒逃跑，真讓人意外！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78629] = {title = "為了後備軍奔波", objective = "在聖落之地的利維亞的耐心協助5個阿拉希後備軍。", description = "我們必須試著救援利維亞的耐心的倖存者。\n\n每一個阿拉希人都是或曾是一名軍人。要是你可以幫助他們，相信他們一定能自救。", progress = nil, completion = "謝謝你，&lt;name&gt;。在我、艾蘭里亞、安杜因還有你的努力下，我想我們成功救了不少人。\n\n剩下的很多人都被奈幽蟲族劫持了，我們必須幫他們！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78630] = {title = "清算號的崛起", objective = "登上清算號，殺死150個奈幽蟲族。", description = "清算號已經就緒！\n\n讓這些蜘蛛付出代價吧。血債血償。", progress = nil, completion = "我們實在太蠢了。", rewards = "您會收到：\n\n清算復仇法衣清算復仇馬褲清算復仇罩盔清算復仇胸甲共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][78631] = {title = "與代言者交談", objective = "在前往失去的礦坑的路上安慰剛達加茲的保衛者。", description = "我聽說附近出了問題，而且我知道是哪裡出了問題。\n\n我們曾在剛達加茲東北邊採礦。當我們撤出之後，狗頭人便進駐那裡。\n\n我們有很長一段時間沒聽到那些狗頭人的消息，但聽起來他們現在打算襲擊我們！而至高代言者對此沒有採取任何行動。\n\n必須有人想點辦法。如果我們能擺平這件事，就會有更多機語者會聽我們的話。既然至高代言者毫無作為，那就我們來做。", progress = nil, completion = "能看到有一些狗頭人對這場戰爭不是那麼熱衷的感覺真好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78634] = {title = "一個石頭都不能少", objective = "到失去的礦坑從戰死的土靈身上取回身分牌。", description = "狗頭人占領這個礦坑時，許多土靈戰死了。\n\n更糟的是，那些土靈只能在他們倒下的地方逐漸崩毀。沒有人去把他們帶回來。我們沒辦法讓他們得到安息，或是為他們的記憶獻上敬意。為什麼？我們為什麼會捨棄這些倒下的戰士？\n\n我們不能再辜負他們了，<name>。把我們陣亡同胞的身分牌收集起來，這樣我們才能好好緬懷他們。", progress = "你找到它們了嗎？", completion = "謝謝你，&lt;name&gt;。逝者會永遠活在我們心中。\n\n我們上方的土靈有他們自己的紀念儀式，而機語者會負責準備流程。\n\n小鎮廣場有一座紀念基座，上面有陣亡者的名牌。賈拉克斯會確保我們舉行適當的紀念活動……還有流程檢查，還有重新計算與分配工人。這裡的工作永遠不能停下來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78635] = {title = "死亡與蠟", objective = "從失去的礦坑各處取回爍焰蠟燭。", description = "狗頭人對蠟燭非常執著。蠟對他們來說更是重要。比黃金還要重要。比自由還重要！\n\n我們從蠟燭大王那裡偷來蠟燭。我們讓他看起來很弱小。看起來很弱小的惡霸會失去地位。最後被殺死！\n\n這也代表我們不用在黑暗中等著被吃掉。快去！", progress = "你拿到蠟燭了嗎？", completion = "&lt;看到蠟燭時，史琦德明顯鬆了一口氣。&gt;\n\n啊，真棒。現在把我從這裡救出去！", rewards = "您會收到：\n\n土靈旅行者之索土靈旅行者涉靴土靈旅行者之握土靈旅行者披肩"}
MultiLanguageQuestData['tw'][78636] = {title = "奪回礦坑", objective = "打開通往失去的礦坑的大門。", description = "既然現在我們拿到鑰匙了，是時候和蠟蠋大王開戰了。\n\n把大門打開。等我們進到裡面，就能執行下一個步驟。", progress = nil, completion = "這……情況真不如預期。\n\n我們的狗頭人新朋友可能會有更好的點子。", rewards = "您能選擇下列奬勵中的一個：\n\n野火燈芯復仇火靈\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78637] = {title = "毀壞齒輪咀嚼者", objective = "在失去的礦坑殺死齒輪咀嚼者並取得他的鑰匙。", description = "齒輪咀嚼者是蠟燭大王的打手。大壞蛋！他把土靈設備重組起來投入戰爭，同時也負責礦坑的防衛工作。\n\n需要他的鑰匙才能進入礦坑……然後把我從這東西弄出去！", progress = "你找到鑰匙了嗎？", completion = "&lt;name&gt;，謝謝你。我沒想過自己可以重獲自由。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78638] = {title = "工程毀滅", objective = "在失去的礦坑裡摧毀採礦設備。", description = "有些狗頭人正在改裝礦坑淪陷時來不及帶走的設備。\n\n請在這些設備被用來對付我們之前摧毀它們。我寧願它們變成廢物，也不能讓它們落入敵人手中。\n\n礦坑最底層的西區邊緣有一個儲藏庫。從那裡開始下手吧。", progress = nil, completion = "謝謝你。現在我們的敵人少了一項優勢。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78639] = {title = "狗頭人行動", objective = "在狗頭窟擊敗拘禁者，解救被迫害的狗頭人。", description = "到處都是惡霸！\n\n狗頭窟到處都有無辜的狗頭人受到蠟蠋大王的暴徒壓迫。\n\n讓那些惡霸嚐嚐自己惡行的滋味！\n\n一旦那些惡霸被擊敗，無辜的人就有機會逃跑。重獲自由！", progress = nil, completion = "這是個開始，朋友，是個開始。謝謝你。", rewards = "您會收到：\n\n土靈旅行者束帶土靈旅行者行靴土靈旅行者護手土靈旅行者肩墊"}
MultiLanguageQuestData['tw'][78640] = {title = "宣示命運", objective = "從空中偵察狗頭窟並投放小冊子。", description = "在占領礦坑之前，我的族人住在宏偉的城市裡。岩石頭稱其為狗頭窟。\n\n現在那裡由蠟燭大王的惡霸負責管理。我們必須看看自己在和什麼戰鬥。讓狗頭人知道我們是來幫忙的！而且是比蠟燭大王更好的選擇。\n\n還有什麼方法比小冊子更好？大家都愛小冊子！我們畫得真的很好！\n\n布琳瑟說你有一頭會飛的龍還是鳥之類的？很適合用來偵察！很適合用來發小冊子！\n\n<史琦德滿懷期待地看著你，一邊等待一邊微微搧動雙臂。>", progress = "我從來沒有飛過。好玩嗎？", completion = "看到家園變成這樣真讓人難過。\n\n但我們會修復它！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78641] = {title = "頂撞炬嗥", objective = "在狗頭窟擊敗炬嗥。", description = "炬嗥幫蠟燭大王管理狗頭窟。他就是個大惡霸！很壞、很壞的惡霸。\n\n我們要讓大家知道，我們是可以打贏惡霸的！", progress = nil, completion = "可惜被他逃掉了，但其他人呢？大家都看到他是個懦夫了！這樣正好。\n\n我很高大，所以我很會說話。他更大隻！他應該要更會說話！看來他不是很聰明。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78642] = {title = "新蠟燭，新希望", objective = "從暗焰裂縫取回蠟燭之冠。", description = "我們弱化蠟燭大王的掌控了。但還需要可以凝聚族人的象徵。\n\n大王持有一個古老的聖物，稱為蠟燭之冠，是希望的象徵。這東西是我族的重心。蠟燭大王把它扔掉了！還找到了新的戰利品：暗焰蠟燭。\n\n那個王冠？還在他手裡。蠟燭大王現在應該出來了。看看我們在這裡做了什麼！\n\n趁他不在，我們悄悄溜進去！利用舊坑道！奪回屬於我們的東西！我們真聰明。", progress = nil, completion = "哈！我們成功了！現在大家都知道，蠟燭大王不是唯一的統治者。", rewards = "土靈旅行者軍刀土靈旅行者匕首土靈旅行者法杖土靈旅行者手斧土靈旅行者裁決錘土靈旅行者巨刃劍土靈旅行者標槍土靈旅行者火槍土靈旅行者十字弓土靈旅行者砍斧土靈旅行者之拳您會收到：\n\n"}
MultiLanguageQuestData['tw'][78643] = {title = "晴空萬里，乘風翱翔。", objective = "到沃卓肯的守護巨龍之座與雅立史卓莎交談。", description = "對我們所有人來說，這一直是一條漫漫長路，$p。\n\n但是，在經歷無數苦難與鬥爭後，龍族已經準備好迎接新的時代。\n\n在你踏上下一個冒險之前，我和其他的守護巨龍想感謝你為我們所做的一切。", progress = nil, completion = "願你晴空萬里，乘風翱翔，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78645] = {title = "挖掘：埋藏在河床中", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78646] = {title = "火焰守望", objective = "在俯瞰落燼堡的伊瑟拉之眼懸崖邊與麥琳瑟拉會合。", description = "母親似乎無法跟伊瑟拉之眼完全同步，也許它感知到了她與亞登曠野的連結…\n\n她的屏障只是伊瑟拉之眼一小部分的力量而已。若她能完全同調的話，就能徹底撲滅敵人的火勢。\n\n但我們不能再乾等了，我們仍然需要獲得加洛克與其攻擊計畫的更多情報。波德溫說，伊吉拉的基地中又有一連串新的活動。有了波德溫的協助，我們就可以秘密進行調查。", progress = nil, completion = "這沒那麼簡單…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78649] = {title = "挖掘：河床下的大發現", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78655] = {title = "適應性冷卻藥膏", objective = "把扎拉萊克發光孢子、覺醒之霜和夢境精華交給艾登來製作適應性冷卻藥膏。", description = "如果你需要我的協助的話，我可以製作一個有用的藥膏，幫助你暫時與『夢境裂斧』菲拉雷斯同調。\n\n把我缺少的材料帶來，我就可以完成藥膏了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n適應性冷卻藥膏"}
MultiLanguageQuestData['tw'][78656] = {title = "沖得一乾二淨", objective = "啟動『大水桶』巴尼，利用水管沖掉40堆汙染黏液。", description = "在烈焰復燃後，你可以看到釣魚洞的汙染程度。寇拜斯和青蛙留下了一大堆奇怪的黏液，汙染了水域和海岸線。\n\n我們需要你幫忙淨化這一整片區域，清除這堆有害的黏液！\n\n我特別改造了一台加裝水桶的收割者。利用這部裝置朝一堆堆的黏液灑水，清除汙染我們土地的東西。", progress = nil, completion = "做得好，&lt;name&gt;，現在這裡總算乾淨多了！", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][78657] = {title = "午夜哨衛", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78658] = {title = "神聖之路", objective = "與聖落之地的居民會面。", description = "$p，很高興我們能夠相遇。阿德貢一直跟我說一個名叫聖落之地的洞穴。\n\n她告訴我，那裡的人自稱阿拉希族。我無法想像他們與古代人類王國有關，但這絕不可能是巧合。\n\n一段時間前，阿德貢的人曾跟他們建立良好的關係。無論發生什麼事，我希望修復這段關係，獲得他們的協助。請到聖落之地大門找我。", progress = nil, completion = "在聖落之地，友好的外來者可不常見，只有不斷從暗影湧出的敵人。\n\n儘管你看起來異於常人，但你似乎不害怕光明。要不是我們正身陷危機之中，我會好好歡迎你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78659] = {title = "聖光所及之地", objective = "到神禦之牆附近與法林的盟友會合。", description = "在聖落之地，很多人會稱你為「外來者」。我會稱你為朋友。如果你對戰鬥習以為常，那麼我也想向你求助。正所謂患難見真情。\n\n鐵擊將軍命令軍隊撤退，不再與奈幽蟲族交戰。因為她的離去，讓燈火者和許多部隊困在黑暗之中。我自己一個人或許無法救出他們，但有了你幫忙，我說不定辦得到。\n\n要是你願意的話，可以跟我一起過去，或直接在那裡會合。", progress = nil, completion = "外來者！奈幽蟲族突襲了我們。牆被突破後不久，軍隊就撤退了。我一直拼命擋住他們，不讓他們接近這座塔，但我急需你的幫忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78661] = {title = "挖掘：峭壁中的寶藏", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78662] = {title = "挖掘：遍布峭壁的寶箱", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78663] = {title = "挖掘：散落在高塔", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78664] = {title = "療癒自我的禮物", objective = "與殷談談，發現內心的渴望。", description = "你的眼神看起來像個疲倦的冒險者。\n\n你是為許多人盡心盡力的<class>。你還記得上次對自己好一點是什麼時候嗎？\n\n也許是時候對自己好一點了。面對自己的內心吧。\n\n你自己究竟想要什麼？", progress = nil, completion = "讓我們開始自我療癒吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78665] = {title = "地道問題", objective = "摧毀6個奈幽地洞。", description = "有新盟友在真好。我們並肩作戰，就更有機會守住這座塔。\n\n不過，奈幽蟲族無所不在。如果我們想要趕走他們，就必須摧毀他們用來抵達城牆底下的地洞。\n\n如果你能成功，我們就會盡可能從城牆上提供支援，然後在那裡和你會合。", progress = nil, completion = "非常好，&lt;name&gt;，既然可以不用擔心奈幽蟲族從背後攻擊，我們就能專心對付從下方湧出的敵人了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78666] = {title = "死蜘蛛才是好蜘蛛", objective = "殺死12個奈幽蟲族攻擊者。", description = "$p，如果我們無法阻擋朝我們爬來的奈幽蟲族大軍，那就全盤皆輸了。\n\n他們的數量實在太多了。\n\n我們必須拖慢他們的攻勢，為聖落之地的人爭取更多準備時間。城牆仍是非常有效的防守點。\n\n盡你所能削減他們的數量。", progress = nil, completion = "不錯的開始。下方還會陸續冒出更多奈幽蟲族，但我們必須把注意力轉移到已經進入聖落之地的敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78667] = {title = "記憶復燃", objective = "從陣亡的士兵身上取回6個阿拉希引火盒，並燒掉他們的屍體。", description = "$p，今日有很多好人命喪於此，太多了。\n\n每個阿拉希士兵都帶著一個引火盒。那象徵著他們將自己奉獻給聖焰。很多人會把它當成法器，召出聖焰之火。在巴雷達爾的光芒照耀不到的黑暗之地，聖焰可以帶來希望。\n\n面對奈幽蟲族的進攻，我們無法回收他們的遺體。因此我們必須取回這些象徵物，以便銘記他們的犧牲。然後用這根火炬燒掉他們的遺體。這是我們所能提供的最好的葬禮。", progress = "你取回他們的引火盒了嗎？每一條生命都應該被銘記在聖焰之中。", completion = "謝謝你，&lt;name&gt;，你已經盡力讓他們體面地離去。", rewards = "您會收到：\n\n燈火者裹手燈火者肩冑燈火者繫腰燈火者脛甲"}
MultiLanguageQuestData['tw'][78668] = {title = "在破曉者號上集結", objective = "到忒尼爾飛船港的破曉者號上找法林。", description = "在這麼多奈幽蟲族通過神禦之牆的情況下，最重要的就是要守好我們停在忒尼爾飛船港的飛船。\n\n奈幽蟲族的人數一向能壓制我們，但我們的艦隊使我們可以把防禦者集中在他們攻擊的地方，也讓我們可以在空中安全地轟炸他們。\n\n如果我們失去艦隊，我們的希望就會大幅減弱。有空時就到那裡與我們會面吧。", progress = nil, completion = "很高興有你相助，&lt;name&gt;。\n\n沒有飛船，長久下來我們根本無力對抗奈幽蟲族。\n\n更不用說我們的碼頭工人全都安全躲在甲板底下。\n\n我們來好好防守吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78669] = {title = "蟲眼專屬", objective = "收集3部奈幽蟲族投影儀，了解他們的計畫。", description = "我們從抵達時就在與奈幽蟲族作戰，$p。他們的攻擊很久沒有這麼激烈了。\n\n這些飛船港顯然是個目標，但他們有其他目標嗎？還有更宏觀的目的嗎？\n\n奈幽蟲族帶著投影儀，裡面有來自女王的命令。我們需要盡量了解他們的計畫和意圖，而取回幾台這種投影儀是我們最有效的辦法。", progress = nil, completion = "最後戰役？晉升？我們還沒有釐清太多問題，&lt;name&gt;。但我們至少抓到幾塊拼圖了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78670] = {title = "破壞攻城武器", objective = "在忒尼爾飛船港下方摧毀4座攻城武器。", description = "$p，如果我們想要擊退奈幽蟲族，就必須解決他們的攻城武器。\n\n忒尼爾飛船港附近有好幾桶黑火藥供飛船作戰使用。既然奈幽蟲族讓這些飛船完全無法起飛，不如就把那些火藥用在別的地方。\n\n收集幾桶火藥，放在奈幽蟲族的攻城武器旁。", progress = "<name>，你摧毀他們的攻城武器了嗎？", completion = "摧毀那些攻城武器後，我們的形勢變得比較好了。法林跟著偉大的凱隆一起去點亮黎明塔。她要我們去那裡跟他們會合。", rewards = "您會收到：\n\n阿拉希爆破炸藥"}
MultiLanguageQuestData['tw'][78671] = {title = "黎明塔之光", objective = "協助燈火者點亮黎明塔。", description = "$p，法林去點亮了黎明塔。她說它能讓聖焰的光輝持續照耀聖落之地。凱隆也一同前去了。\n\n很難想像有任何燈塔會比他們的巴雷達爾之星還亮，但我很想看看這個聖光的全新化身。\n\n到黎明塔旁找我，我們可以看看阿拉希的聖焰如何守護這些我失散已久的表親。", progress = nil, completion = "來得正好，&lt;name&gt;。巴雷達爾已經落入黑暗一段時間了。不過現在我們有自己的光芒，讓黑暗不會越雷池一步。", rewards = "您會收到：\n\n守塔者輕鞋守塔者之握守塔者肩衛守塔者護腰共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][78672] = {title = "燈火者的職責", objective = "搭乘燈火者小艇前往羅萊十字路。", description = "黑暗已然敗退。但我們還不能休息。\n\n<法林對你露出疲憊的微笑，不過她的眼睛裡閃爍著光芒。>\n\n黎明塔發出的光芒會將黑暗中最危險的事物阻擋在外。我身為燈火者的職責就是確保所有黎明塔綻放光明。\n\n我接下來要飛去巡邏羅萊十字路。為了我們所有人，我歡迎你和安杜因一同前往。", progress = nil, completion = "寇拜斯把無辜的村民拖到岸邊了！牠們會把受害者溺死，然後吃掉！\n\n我們必須去救他們！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78674] = {title = "疏解壓力的禮物", objective = "在禮品盛會與賽明翁‧葛力斯沃談談，然後到舊城區疏解壓力。", description = "像你這樣的冒險者，內心一定背負著沉重的負擔。何不趁現在好好愛自己呢？\n\n我看到附近有個退伍老兵。他說不定會知道如何與壓力共處。\n\n也許他可以教你，給你一點不同的想法。", progress = nil, completion = "有沒有好一點了？\n\n經歷辛苦的一天後，你得對自己好一點。照顧好自己的身心，才能走得遠。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78679] = {title = "放鬆身心的禮物", objective = "請教博爾多‧露園如何放鬆身心，然後到暴風城奧利維亞的池塘旁放空。", description = "愛自己有很多不同的方式。\n\n有時候，愛自己的最好方式就是放輕鬆。\n\n煙火旁有個夜精靈，他似乎看起來很自在。也許你可以向他請教放鬆身心的方式。", progress = nil, completion = "有沒有覺得煥然一新啊？我個人最喜歡拍拍那些烏龜。\n\n你找到自己最喜歡的放空方式了嗎？", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78685] = {title = "坑道盡頭", objective = "調查有關泰洛科的傳聞。", description = "我們聽到了更多關於泰洛科的傳聞。\n\n那個城鎮和當地的礦坑負責生產礦石。顯然我們已經好幾個禮拜沒有收到貨物了，而且城鎮的工頭也失蹤了。現在至高代言者禁止任何人前往那裡。\n\n這代表我們應該去調查一番。當然，如果有人受傷，我們就應該幫助他們。", progress = nil, completion = "裡面有野獸？\n\n也許泰洛科的居民會需要我們的幫助。\n\n&lt;name&gt;，幫我盯緊達格蘭。他讀過很多驚險刺激的冒險故事，但他從沒有看過現實的殘酷。\n\n而且事情似乎……有點不對勁。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78686] = {title = "光滅", objective = "到瓦爾罕領地附近找塔納和愛米拉。", description = "我的名字是艾格。我負責調派燈火者，評估聖落之地的哪個地方可能需要他們的援助。\n\n幾週前，瓦爾罕領地的黎明塔陷入黑暗。考慮到聖落之地各地發生的事，它很可能是因為寇拜斯大舉入侵。\n\n燈火者塔納和愛米拉正趕去那裡，但再加上這個狀況，已經不是兩個燈火者能處理得來了。你可以去那裡找他們，幫他們恢復瓦爾罕領地的光芒嗎？", progress = nil, completion = "很高興見到你，&lt;name&gt;。我叫塔納，然後這位是愛米拉。\n\n瓦爾罕領地的黎明塔稍早陷入一片黑暗，事件發生之後，我們就趕來幫忙了。\n\n我們做了一些調查，結果顯示，寇拜斯已經奪下了那個地方。我猜瓦爾罕已經躲起來了，而不是把他們擊退。\n\n但好消息是，我們是來幫助他的人民的。如果你能再次協助就更好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78687] = {title = "收集遺物", objective = "從不撓號的亡者身上取回4個找回的引火盒。", description = "不撓號墜毀時，很多東西都出錯了，$p。但最讓人沮喪的是，當我們終於收到命令要返回米雷達爾時，我們無法紀念我們逝去的同胞。\n\n寇拜斯似乎讓我們過世的成員復生了，他們現在以可怕的骷髏型態在不撓號上遊蕩。\n\n拿回他們的引火盒。如果我們可以把引火盒丟進聖焰，他們終於可以在這麼多年之後獲得自由。", progress = "<name>，你找到那些引火盒了嗎？", completion = "烈焰為我們所有人燃燒，&lt;name&gt;。我真希望那晚能救他們一命，但我很高興我們能夠悼念他們。\n\n如果我們不幸陣亡，我們想要的也會是這樣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78688] = {title = "籠子大戰", objective = "用愛米拉的神聖火焰燒毀10個寇拜斯籠子。", description = "在你到來之前，我們偵察了一下，看到瓦爾罕領地周圍放了一大堆籠子。寇拜斯通常會把受害者關在這些籠子裡面，直到需要把他們當作儀式祭品為止。\n\n那些獻祭導致了…更多其他邪惡行徑。其中最令人髮指的就是生吃受害者。\n\n我們必須搶先行動。帶著我的火炬，燒毀那些籠子，我們就不會看到這種事發生在瓦爾罕領地的任何人身上。", progress = nil, completion = "做得好，&lt;name&gt;。沒了那些籠子，寇拜斯就無法關押俘虜。\n\n沒有俘虜，就代表無法舉行邪惡儀式，而防止這一切，也讓我們更有機會拯救瓦爾罕領地的人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78689] = {title = "擒賊先擒王", objective = "擊敗圍攻瓦爾罕領地的寇拜斯首領。", description = "領導是一切興亡的關鍵，$p。遇到好的領導者，團隊就幾乎無所不能。遇到壞的領導者，則紛亂四起、成功遠去。這些我都曾親眼所見。\n\n失去了首領，寇拜斯的圍攻自然不攻而破，我們在這裡的行動也會更加輕鬆。我曾見到三個疑似是首領的寇拜斯，讓我在你的地圖上標註牠們的位置。\n\n解決牠們，有助於我們幫助瓦爾罕領地。", progress = nil, completion = "太棒了。這可以讓我們與寇拜斯更加勢均力敵。至少在領導的部分。\n\n牠們的數量還是比我們多上許多，不過一件一件來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78690] = {title = "狀況警覺", objective = "與瓦爾罕領地的10個居民談話。", description = "不管塔納和瓦爾罕之間發生過什麼事，我們必須照顧瓦爾罕領地的居民。\n\n$p，可以請你去拜訪一下這裡的家族嗎？讓他們知道我們來這裡幫忙了。\n\n看看他們有沒有擔心的事，或是有什麼需要。務必向他們保證，燈火者會趕走寇拜斯。", progress = nil, completion = "我們是來幫忙的。但從過去的經驗中，我知道有時候希望和信心才是最不可或缺的事物。\n\n當你在跟居民談話的時候，我和塔納已經決定好接下來的行動了。\n\n我們必須讓民眾有喘息的空間，但也必須讓他們做好戰鬥的準備。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78691] = {title = "逃脫的傢伙", objective = "到不撓號的殘骸援救麥克斯米連。", description = "$p，我兒子去和寇拜斯戰鬥了。他說服其他小孩跟他一起偷偷外出戰鬥。說他們必須「跟我爸一樣勇敢」。\n\n當他們遇到寇拜斯，其他人都跑回這裡，他卻跑向墜毀的飛船，把牠引開。\n\n我並沒有勇敢面對，$p。不撓號的故事說我是個英雄，但那都是我在報告裡撒的謊。\n\n如果真的要我勇敢一次，那一定是現在。不過，我一個人還是不是寇拜斯的對手。跟我來，$p，幫我援救麥克斯米連。", progress = nil, completion = "我知道這有點陳腔濫調，&lt;name&gt;，但你把麥克斯安全送回家，我真的是感激不盡。\n\n經歷過這一切，你也讓我知道，我必須站出來帶領我的領民。我所見過的情況比死亡還要糟。\n\n我無法抹除我過去犯下的錯，但我可以保證自己不會重蹈覆轍。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78692] = {title = "授人以漁", objective = "將8根長矛分發給瓦爾罕領地的居民。", description = "$p，長久以來瓦爾罕領地的居民一直關在裡面，懼怕黑暗。\n\n儘管外面有很多值得恐懼的事，但這些人既出色又堅毅。他們應該趕走寇拜斯，而不是躲在牆後。\n\n把這些長矛送去給瓦爾罕領地的居民。他們過去只知道對問題視而不見，但我們會給他們重獲新生的手段！", progress = nil, completion = "&lt;name&gt;，既然他們現在已經武裝自己了，我想我們一定能看到他們有所改變。\n\n他們會知道自己可以照顧自己，自己可以解決問題，自己不需要別人來拯救。\n\n當然，我們這些燈火者隨時都會伸出援手，但下次很可能就用不到我們了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78693] = {title = "驅逐恐懼的長矛", objective = "為瓦爾罕領地的居民收集8根寇拜斯長矛。", description = "瓦爾罕和他的追隨者原本想在這裡安居樂業。他們如此肯定，以至於他們完全沒帶任何武器來。\n\n在遭受寇拜斯攻擊的當下，這就成了一大問題，但寇拜斯也確實能幫我們解決這個困境。他們為了圍攻瓦爾罕領地，帶了不少長矛來，刺穿人類的長矛，也能用來刺穿寇拜斯。\n\n去外面替居民收集一些長矛，$p，他們就沒必要那麼害怕。", progress = "寇拜斯給你帶來麻煩了嗎？瓦爾罕領地的居民很快就會變成給寇拜斯帶來麻煩的人了。", completion = "做得好，&lt;name&gt;，這正是我們需要的，不只現在可以用來趕走寇拜斯，之後也能確保瓦爾罕領地的居民未來有能力自衛。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78694] = {title = "奪回瓦爾罕領地", objective = "在瓦爾罕領地各處殺死12個寇拜斯戰士。", description = "$p，我看到的問題，是寇拜斯。他們的數量實在太多了。\n\n我們來到聖落之地的時候，這裡的每個人都曾在帝國軍隊服役。他們現在體能或許有些退化，但他們先前都受過訓練，知道如何作戰。\n\n但是，我們必須消除所有劣勢因素，包括寇拜斯的數量。所以請到外面去，弭平數量上的差距。我和愛米拉會在這裡保障所有人的安全。", progress = nil, completion = "你知道，自從寇拜斯把我的戰友拖入黑夜，當成晚餐，我就一直很厭惡牠們。\n\n希望你所做的努力，能讓這種事不會發生在瓦爾罕領地的居民身上，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78695] = {title = "點燈", objective = "沿著瓦爾罕領地的邊界設置8個火炬，然後見證黎明塔的再次點亮。", description = "寇拜斯一般棲息在深水區，$p。當巴雷達爾光芒最為耀眼的時候，牠們根本不敢靠近我們。其他的明亮光源通常會讓牠們躲得遠遠的，而且會弱化牠們。\n\n身為燈火者，我們不只在暗處保護需要幫助的人，也會提供他們保障自身安全的燈火。請沿著邊界豎立這些火炬，然後在瓦爾罕領地後方的黎明塔跟我們會合。", progress = nil, completion = "你救了我兒子，&lt;name&gt;。你成功挫敗了對我們家園的攻擊行動，給了我們戰鬥所需的武器。\n\n你幫我成為貨真價實的領導者。謝謝你。\n\n瓦爾罕領地將永遠是燈火者的盟友。", rewards = "您會收到：\n\n堅實阿拉希香爐共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][78696] = {title = "我們不去泰洛科", objective = "除掉盤踞在泰洛科入口的野獸。", description = "這位遇險的機語者曾在這裡做某件事。是什麼事呢？看起來有某種東西把他傷得很重。\n\n不能再浪費時間了。\n\n我們必須去泰洛科尋找工頭。你可以把城鎮的入口清理乾淨嗎？有人可能會因此受傷！", progress = nil, completion = "工頭的辦公室沒有什麼線索。如果我們想要答案，就必須搜索這座城鎮。", rewards = "您會收到：\n\n土靈旅行者法衣土靈旅行者馬褲土靈旅行者罩盔土靈旅行者胸甲"}
MultiLanguageQuestData['tw'][78697] = {title = "公司鎮幽靈", objective = "使用調查技能，找出線索，了解泰洛科發生什麼事。", description = "很顯然，工頭不在這裡。但證據指出她最近曾待在這裡。所以她或許還在附近！\n\n我們應該繼續深入城鎮，看看有沒有人知道她可能去了哪裡。\n\n或者也許某人可以直接把我們想要的答案告訴我們。或許我們也能自己找出來！或許這可能是某種攻擊或某種…抱歉。我想得太忘我了。我們去調查一下吧！", progress = nil, completion = "嗯…或許有一個問題的答案揭曉了。但卻衍生出更多的問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78700] = {title = "有限的破壞", objective = "在泰洛科殺死18隻斯卡汀。", description = "我知道我們以前對抗過斯卡汀，勇士，可是這次…這次更糟糕。\n\n我知道斯卡汀之前就在把土靈變成更多斯卡汀，可是我沒想到…那些水晶…那些尖刺…湧動的藍色能量…還有那股氣味！總之，我完全沒預料到這些。\n\n如果我們一定要到外面的話，我在路上一定要順便除掉這些怪物。", progress = nil, completion = "或許我們只是殺了一個群體中的幾位斯卡汀，但我們總得有個開始。", rewards = "土靈旅行者披巾土靈旅行者披風您會收到：\n\n"}
MultiLanguageQuestData['tw'][78701] = {title = "粉筆寫下的真相", objective = "在泰洛科礦坑搜尋訊息。", description = "原來泰洛科的人是用粉筆在石板上來留訊息給彼此。好多線索啊！但這些都是什麼意思呢…\n\n我看出了一些規律，我覺得線索指向礦坑。如果工人還活著，我認為他們會在礦坑裡。\n\n而且我知道工頭是關鍵，她一定是關鍵。", progress = "我們能在這裡找到更多線索。我很確定。", completion = "我想我知道我們接下來該去哪裡了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78703] = {title = "埋藏於石", objective = "調查泰洛科礦坑後方的洞穴。", description = "我們得進去那個洞穴，上一個石板提到它就在附近。雖然沒有署名，但我想那應該是工頭的字跡…而且我們也已經把所有地方都找過了。我們必須去調查一下。", progress = "我們還漏了什麼…那個洞穴裡一定還有什麼東西！", completion = "我就知道！我是對的！這裡面果然有什麼東西。某人想藏在這裡的東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78704] = {title = "找出工頭", objective = "找出工頭。", description = "達格蘭說的沒錯。我想我不應該再對此驚訝了。\n\n所有的線索都顯示洞穴裡有某種東西。也許工頭就躲在這裡。也許她能給我們一些答案。\n\n我們終於走到這一步了。來看看裡面有什麼吧。", progress = nil, completion = "那就是她。工頭。一定是。畢竟……她早就死了。", rewards = "您會收到：\n\n土靈旅行者腕輪土靈旅行者束腕土靈旅行者護腕土靈旅行者臂鎧"}
MultiLanguageQuestData['tw'][78705] = {title = "她所見之物", objective = "調查斯卡汀留下的寶石。", description = "那是什麼？在我們把那個斯卡汀…在牠死前掉出來的東西。\n\n我想我曾經在哪裡看過類似的東西。", progress = "我想我知道那個寶石是什麼…", completion = "喔。這是件大事，對不對？\n\n工頭親眼在甦醒會堂看到這個陰謀。\n\n然後她帶著她的記憶寶石回到泰洛科。\n\n她想要警告其他人，但她已經受到感染…也無法阻止快速的轉化。她把自己關在這個洞穴裡，但還是讓她的腐化散播出去了。\n\n而至高代言者早就知道會發生什麼事。至高代言者就是一切的幕後主使！\n\n我們必須去警告布琳瑟。我們必須去警告世人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78706] = {title = "至高代言者的秘密", objective = "回到剛達加茲找布琳瑟。", description = "我們拿到想要的東西了。我們得回剛達加茲。必須讓布琳瑟知道這裡發生的事情。\n\n我們先走一步了，$p。到剛達加茲和我們會合。", progress = nil, completion = "謝謝你幫忙調查泰洛科的謎團。\n\n知道是什麼情況了嗎？", rewards = "您會收到：\n\n共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][78713] = {title = "地心之戰", objective = "前往希利蘇斯與索爾探討出現在艾澤拉斯各地的幻象。", description = "有個幻象：「璀璨之歌」，正出現在艾澤拉斯各地。我們認為那是一個警訊，但不確定它代表的意義。\n\n到希利蘇斯找我。我們必須向艾澤拉斯的代言者請教這個幻象代表什麼意義。", progress = nil, completion = "人都到了。很好。來查清璀璨之歌到底想告訴我們什麼吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78714] = {title = "糟糕的歡迎典禮", objective = "前往心之室，請麥格尼幫忙解讀璀璨之歌。", description = "有可靠的證據顯示，璀璨之歌是來自艾澤拉斯的警訊。她在向我們求助。\n\n那也是我們來這裡的原因。如果這個幻象真的是艾澤拉斯的警訊，麥格尼會知道她想告訴我們什麼。\n\n他人應該就在心之室。我們走吧。", progress = nil, completion = "我知道你們為什麼來這裡，是為了那些幻象。艾澤拉斯的聲音傳遍世界各地。你們認為我知道她想告訴我們什麼。\n\n可惜，你們猜錯了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78715] = {title = "艾澤拉斯之聲", objective = "協助麥格尼進行儀式。", description = "我已經好幾年沒和艾澤拉斯交流了。一開始，我只是覺得不需要交流。然後，我意識到自己開始埋怨她。居然把我像這樣…丟在這裡。現在，我已經不確定自己能不能辦到。\n\n不過，我知道事態緊急。她的這首璀璨之歌預示情況危急，而我們必須知道出了什麼事。\n\n首先，我們必須備好心之室。你可以啟動附近的控制臺嗎？", progress = nil, completion = "以前從沒發生過這種事。麥格尼是艾澤拉斯的代言者。為什麼與她交流會令他崩潰？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78716] = {title = "慘痛的教訓", objective = "使用達拉然傳送門。", description = "麥格尼的情況暫時穩定下來了，但他還是沒有反應。我們需要快點讓他接受治療。我會開啟一個通往達拉然的傳送門。\n\n等你有空的時候就跟我們走吧。", progress = nil, completion = "想不到艾澤拉斯的代言者嘗試…和艾澤拉斯對話後，居然會變成這個樣子。\n\n我們現在能做的，就是等待麥格尼恢復意識。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78717] = {title = "神秘的警訊", objective = "討論接下來的行動，然後跟上卡德加。", description = "哇，睡得真舒服。我沒想到艾澤拉斯的音量居然這麼…大聲。對於一般人，她會輕聲呼喚。但是，我和她的關係太密切，她聽起來就像在尖叫一樣。聲音還直接傳入我的水晶腦袋。\n\n不過我看到了。卡茲阿爾加，土靈的一座島嶼，被火焰和煙霧籠罩。那正是艾澤拉斯要引導我們去的地方。\n\n正是我們需要保護的對象。", progress = nil, completion = "議會已經做出決定。我們動身前往卡茲阿爾加。\n\n等我們準備好，達拉然會立刻進行傳送。你可以協助我們進行準備嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78718] = {title = "強化結界", objective = "強化達拉然的防禦。", description = "麥格尼看到的景象，預示著卡茲阿爾加或許正陷入…動蕩不安。所以，最好確保達拉然有能力應付最糟的狀況。\n\n來，收下這根魔杖。它已經與達拉然的防禦魔法同調。\n\n在城市的軍事要地附近揮動它，就能強化我們的魔法防禦。", progress = nil, completion = "做得好，勇士。\n\n希望這樣足以應付一切。在這個世界最需要達拉然的時候，我不希望它出了任何意外。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78719] = {title = "達拉然市民", objective = "協助達拉然的市民做好傳送的準備。", description = "我們的市民必須做好跟著達拉然移動的準備。你可以到城裡四處問問，看看有沒有人需要幫助嗎？\n\n我也希望你去找布萊恩和大法師德蘭丹談談。他們希望在我們前往卡茲阿爾加之前能解決一些問題。", progress = nil, completion = "謝謝你的幫忙。讓達拉然市民為接下來可能發生的事做好準備，是很重要的事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78721] = {title = "認識隊員", objective = "找到阿爾加遠征隊。", description = "如果我們打算在卡茲阿爾加探索新的土地，那麼，我們就會需要探險者協會的支援。不過，在這趟冒險中，他們不會獨自上路。協會將再次與聖匣合作，就像在巨龍群島那樣。\n\n這一次，他們自稱阿爾加遠征隊。\n\n我只是有點擔心他們是不是還處得來。在探索的過程中，隊員分分合合是常見的事。你可以去看看情況嗎？", progress = nil, completion = "他們處得很好？那還真教人意外。啊，我沒打算冒犯達格蘭。\n\n很好，那會讓我的工作簡單很多。無論如何，謝謝你去拜訪他們！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78722] = {title = "前往卡茲阿爾加！", objective = "告訴卡德加你準備好出發了。", description = "根據麥格尼所見的景象，卡茲阿爾加或許算不上安全。一旦爆發衝突，我們需要仰賴你伸出援手。\n\n準備好動身時，就告訴我一聲。", progress = nil, completion = "她就是大法師德蘭丹。一直以來，薩拉塔斯都在我面前冷眼旁觀、暗中謀劃，我居然完全沒看出來？\n\n現在，她帶著奈幽蟲族的大軍入侵達拉然。\n\n自始至終，這一切都是薩拉塔斯的計畫。她要我們來卡茲阿爾加。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78724] = {title = "用自己的方式愛自己", objective = "到閃金鎮附近，在決鬥中擊敗邁特利‧葛雷斯頓。", description = "如果你渴望挑戰，我想到一個點子。\n\n我看到一個自負的勇士朝著閃金鎮走了。你可以向他發起對決。\n\n這應該能滿足你的渴望，順便讓他學到寶貴的一課，了解謙遜的重要。", progress = nil, completion = "平常，你總是為別人全力以赴。\n\n今天，你終於為自己全力以赴。沒有比這個更好的禮物了。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78726] = {title = "用自己的方式愛自己", objective = "品嚐禮品盛會商人的美味套餐。", description = "人生一大樂事就是吃飽飽！\n\n盛會上有很多美食和飲料。何不買點東西吃呢？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78727] = {title = "用自己的方式愛自己", objective = "在獅王之傲旅店樓上的客房小睡一下。", description = "參加這場慶典時，我打算在閃金鎮的獅王之傲旅店住一晚。\n\n我聽說他們樓上有空床。你何不看看能不能在那裡小睡片刻？\n\n我覺得自己也要休息一下…就在…這裡…休息…", progress = nil, completion = "…啥？喔！歡迎回來，休息夠了嗎？\n\n平常，你總是為別人全力以赴。\n\n今天，你終於為自己全力以赴。沒有比這個更好的禮物了。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78729] = {title = "惹事生臭", objective = "到銀松森林的影牙城堡入口找巡官凸栓。", description = "那些線索串連成了一個噁心的真相，<name>。\n\n地圖顯示，王冠公司在銀松森林有個重兵把守的行動基地。然後根據那個備忘錄和配方公式，看來他們正在研究某種會令人成癮的毒物。\n\n我認識有個人能給我們一些…巧妙的東西，可用來對付王冠公司。我先去找他，然後再到影牙城堡外面跟你會合。", progress = nil, completion = "你來了。很好，時機正好。\n\n我已經想到一個計畫，可以破壞這場生化陰謀。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78738] = {title = "缺席的代言者", objective = "在土靈工作場與代言者布琳瑟會合。", description = "$p，這是鳴響深淵的至暗時刻。\n\n我總是覺得至高代言者有哪裡不太對勁。這下我們有證據了。\n\n我們必須伸張正義。如果他打算利用甦醒機械，那我們就得阻止他。", progress = nil, completion = "至高代言者和他的追隨者會為他們的罪行付出代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78739] = {title = "挖掘：高塔中的珍寶", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78741] = {title = "共感代言者", objective = "與代言者布琳瑟一起在土靈工作場尋找機語者工頭。", description = "我必須阻止至高代言者製造出更多的斯卡汀。\n\n機語者的協議規定，這個區域的其中一位工頭應該會帶著甦醒會堂的鑰匙。跟我來，我們一起去尋找鑰匙的下落！", progress = nil, completion = "這樣我們就能進入甦醒會堂了……", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78742] = {title = "土靈工作場大戰", objective = "在土靈工作場擊敗敵方機語者和傀儡，救助害怕的工人！", description = "$p！一場戰鬥正在進行！我們需要協助支持我們使命的機語者，並對抗任何捍衛至高代言者的人。\n\n我會留下來和阿德貢一起制定計畫。我需要你率領我們的部隊，我們則會去想辦法控制至高代言者在土靈工作場中做出的壞事。這是我們罷免他的第一步。我們要一勞永逸地阻止他駭人聽聞的罪行。\n\n$p，你怎麼說？想戰鬥嗎？", progress = nil, completion = "你成功地逼退至高代言者的幾位最忠誠的信徒……而你也敲碎了幾顆腦袋。\n\n這是個很好的開始。可是還有好多……太多了……", rewards = "您會收到：\n\n土靈旅行者護腿土靈旅行者護脛土靈旅行者頭盔土靈旅行者外衣"}
MultiLanguageQuestData['tw'][78743] = {title = "我離開之前", objective = "在悼念高地的紀念地與烏塔戈會面。", description = "我能感覺到我的能量快耗盡了。\n\n我很快就無法繼續履行我的職責。這就是我要讓烏塔戈接手的原因。\n\n在我的系統停止之前，我必須除掉悼念高地的狗頭人。他們入侵了我照應的紀念地，掠奪了那裡的無縛者神殿和遺體。\n\n也許你在這裡是件好事。你或許有能力幫助我們。\n\n請幫助烏塔戈剷除狗頭人吧。", progress = nil, completion = "科格蘭還是會稱自己為管理員，但我才是負責管理悼念高地好一段時間的人。\n\n我是不介意，科格蘭人非常好。\n\n可是這裡的情況有點超乎我的掌控了。我們還有一些工作要做。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78744] = {title = "榮耀他們的回憶", objective = "除掉狗頭人的侵害，並將禮物放置在關機的歷屆管理員身旁。", description = "把這些禮物拿去，放在歷屆的管理員身邊。每個禮物都是為了讚揚他們的回憶。\n\n我也希望我們可以做一些簡單的維護，至少照顧一下這個環境。很遺憾的是，狗頭人對這些紀念物所做的破壞，我們要花好幾週才能修好。\n\n請你盡量處理狗頭人吧。如果他們還在這個地區遊蕩，把禮物無人看管地擺著不太明智。", progress = nil, completion = "狗頭人對這個地方造成的破壞還真驚人。好多關機的土靈都遭到褻瀆了！\n\n我知道我還不是主任管理員，可是我要為此負全部的責任。很久以前，在科格蘭開始出現記憶覆寫跟靜滯鎖定的最初跡象時，我就應該要求要繼承管理員的衣缽的。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78745] = {title = "你！不能！拿走！劫掠品！", objective = "從劫掠品堆中找出土靈的物品。", description = "看來狗頭人從這些關機的土靈身上拿走了寶石和其他…身體部位。\n\n真是可惡。\n\n去找出狗頭人藏匿劫掠品的地方，然後把它們帶回來，我之後才能把它們歸位。\n\n他們要為這種破壞行為付出代價！", progress = "你有找到他們的劫掠品嗎？", completion = "謝謝你幫這個忙。\n\n&lt;烏塔戈一邊看著物品，一邊認同地點頭。&gt;\n\n我現在比較放心了，可是還有更多工作要做。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78746] = {title = "一視同仁的法律", objective = "在悼念高地殺死狗頭人入侵者。", description = "在土靈社會中，褻瀆紀念地是最嚴重的禁忌。這個紀念地是一扇通往我們的過往、進入到回憶中的門戶，以及一個自省的地方，我們在這裡可以和已逝之人交流。\n\n不過，還是有很多狗頭人在悼念高地亂竄。狗頭人犯下的罪行，必須受到最嚴厲的懲罰，我們必須進一步削減他們的數量。", progress = nil, completion = "我不是當戰士土靈的料，也不是使用暴力的人。那是風暴飛騎的領域。\n\n這些狗頭人做的事不僅我們無縛者不認同，土靈社會裡的每個人也都不會認同的。我們不得不殺了他們，這點我並不感到自豪，但我們必須不計手段阻止他們。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78747] = {title = "大崩塌", objective = "使用雷管來摧毀狗頭人坑道。", description = "既然我們已經重創他們，我們必須把他們的坑道堵住，確保他們不會跑回來。\n\n記得科格蘭討論過的東西嗎？雷管…那是他的配方。我帶來的量足以撼動一座山！用來對付狗頭人可說是綽綽有餘。\n\n幫我讓狗頭人知道，我們會捍衛我們的領地，這樣他們才不會回來！", progress = nil, completion = "哈哈！我怎麼跟你說的？我連在這裡都能感覺到震動！", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78748] = {title = "修剪燭芯", objective = "找到並殺死狗頭人監工。", description = "據我對狗頭人的了解，他們會有好幾個監工或是領袖，負責主導這場掠奪。\n\n去找到並消滅這些所謂的「監工」。其他人就會群龍無首，忘記他們過來的原因，最好別再來煩我們。", progress = nil, completion = "如果這些狗頭人決定要再次劫掠，消滅行動背後的主謀只能為我們爭取更多時間。\n\n很遺憾的，還有一個狗頭人主腦是我們忽略的，直到現在。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78749] = {title = "這個好地方的負責人是誰？", objective = "殺死神偷波克。", description = "在你處理坑道跟監工時，我看到一個很奇特的狗頭人走進西北方的洞穴。狗頭人似乎特別尊敬他，稱他為神偷波克，也會為他獻上你們稱為「起司」的食物。這使我認為他才是真正的首腦。\n\n如果那個狗頭人才是這場行動真正的策劃者，那我們就該找機會除掉他。\n\n我會到洞穴那裡跟你會面。", progress = nil, completion = "很高興能看到你，&lt;name&gt;。\n\n我可以感受到我的內部零件在攪動，那是焦慮的跡象。科格蘭越來越接近關機了，在那之後，這個地方就會由我來負責。\n\n這是很大的責任，但我認為我已經準備好了。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][78754] = {title = "失落包裹", objective = "將遺棄包裹送去給杜加茲小屋的收割者法妮。", description = "<你在路上找到一個小巧但沉重的皮革包裹，上面有一個標籤。>\n\n剛達加茲包裹快遞\n\n加急\n\n收件者：\n收割者法妮\n杜加茲小屋\n\n小心開啟：內有易燃元素礦物。", progress = nil, completion = "喔，煙燻蜂窩啊…你找到了！我還是無法相信快遞員把我的包裹弄丟了…\n\n我們等著用這個來治療岩蹄的腿已經等很久了。\n\n這東西混合了火焰蜂蜜，應該可以快速幫牠進行簡單的治療！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78755] = {title = "玩泥巴", objective = "收集20把元素充能之沙。", description = "記得我們之前用黏土跟火焰蜂蜜治療岩蹄那次嗎？我們再做一次，但這次要做得更大！\n\n問題是我們沒有黏土了。很幸運的是，最近的地震活動讓一大群元素生物都跑了出來，在東部海灘上作亂！\n\n去幫我把潮濕的元素充能之沙帶來，我們要用它來做藥的基底！", progress = "透過混合活沙跟水，我們就可以創造出元素淤泥，複製底土的治療特性。或至少是類似的東西！\n\n元素混合很有趣吧？", completion = "&lt;name&gt;，你可以感受到淤泥中的能量在你的指間流動嗎？在其中嗡嗡作響的電流？\n\n是不是很令人激動啊？它是不是讓你感覺跟大地和山林合而為一了呢？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78756] = {title = "很多很多火焰蜂蜜", objective = "找到很多火焰蜂蜜。", description = "如果哈莫特想要幫忙治療這個沉睡的大石頭，把他從池子裡弄出來，那我全力支持他。\n\n很可惜的是，我僅剩的火焰蜂蜜都在治療岩蹄傷口時用完了。有這麼多元素生物到處亂竄，我還沒有時間去火渣林採收更多蜂蜜。\n\n去樹林的邊緣，幫我們帶點蜂蜜回來吧。你會需要很多的。", progress = "在我的森林裡要小心。燼蜂很危險，可是我們需要用牠們生產的蜂蜜來製造我們的蜜酒。", completion = "你在什麼上面找到這個？一個活的蜂蜜…\n\n&lt;法妮暫停了一下，然後壓低她的音量。&gt;\n\n我們別把找到活生生火焰蜂蜜的事情跟別人說。要是我們告訴哈莫特這件事，他可能會分心牽掛此事，並因此而涉險…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78757] = {title = "蜂蜜和黏土讓痛痛不見", objective = "協助哈莫特準備岩蹄的藥膏。", description = "是大岩羊！牠們真的很有氣勢，對吧？牠們是島上最棒的元素野獸之一。\n\n壞消息是牠們還是會受傷。可憐的岩蹄被法妮池塘裡的覺醒元素攻擊了。\n\n好消息是我們有照護這個傢伙所需的一切。\n\n我們只需要把你找到的黏土和火焰蜂蜜混合，接著拍在老岩蹄的蹄子上！\n\n準備好了嗎？", progress = nil, completion = "你還真有運用元素的天分。有沒有想過做這行啊？\n\n嘿，既然你不怕弄髒手，你可以幫我們處理法妮的問題嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78758] = {title = "大地裡的脈動", objective = "在水池周圍放置4個震顫石。", description = "在我們去叫醒沉睡的山嶺巨人之前，我們最好評估一下他睡得有多沉。\n\n不過，如果鑽地而出的奈幽蟲族沒有吵醒他，我不確定還有什麼能叫醒他。\n\n把這些大地裂片拿去，放在湖周圍的瀑布跟山丘上。\n\n等我們把它們設置好後，我就可以獲取讀數，了解巨人的健康狀況。", progress = nil, completion = "山嶺巨人的心跳很微弱。\n\n這麼多元素生物從瀑布裡跑出來，驚擾了可憐老兄的沉睡。\n\n幸好，我們兩個是治療元素跟元素相關生物的專家，對吧？\n\n如果藥膏對土靈跟石羊有效，它對山嶺巨人也會有效！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78759] = {title = "喚醒巨人", objective = "幫哈莫特把元素藥膏塗到山嶺巨人身上。", description = "我的地心通途啊，這個東西還真濃烈！\n\n把治療淤泥跟火焰蜂蜜的熔火融合特性混合在一起，我們就能製造出可以叫醒一整座山的藥膏！\n\n這正是你要做的事。把混合藥膏帶去給法妮的池塘裡那位受傷的朋友，然後把藥膏拍到他的皮膚上！\n\n這個量應該可以叫醒他，然後舒緩他的痠痛。\n\n總之，希望有這個效果。", progress = nil, completion = "哇，你看啊！\n\n在瀑布底下沉睡了好幾千年，但他起床的時候連怒吼或跺腳都沒有。\n\n哈！法妮本來還很擔心呢！\n\n你的藥膏做得太好了，&lt;name&gt;。法妮跟我都得好好感謝你。\n\n我們的新朋友看起來也很感激！", rewards = "您會收到：\n\n大地治癒者徽記共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][78760] = {title = "黑鐵降臨", objective = "在土靈工作場擊敗監督者瓦里克和他的勢力。", description = "我們已經盡力在阻止至高代言者的追隨者了。我們妨礙他們摧毀或搶劫可以帶進甦醒會堂裡的東西。\n\n現在，我們只需要在他們協調更團結的反抗之前，把他們部隊的領袖處理掉就好。\n\n你準備好了嗎，<name>？", progress = nil, completion = "鳴響深淵應該暫時安全了。但是至高代言者……\n\n我們必須跟著代言者布琳瑟進入甦醒會堂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78761] = {title = "深入機械", objective = "在甦醒會堂面對至高代言者。", description = "沒時間喘息了！至高代言著正逃向土靈最神聖的機械那裡。我們必須追上他。\n\n記住，我們這麼做是為了土靈！為了正義！為了所有因至高代言者的傲慢而殞落的兄弟姊妹和戰友！", progress = nil, completion = "他不見了？真的不見了？\n\n在我看來，他只不過是放棄了自己的權力。我不知道他逃到哪裡了，我也不在乎。既然甦醒機械又再次運作起來，那我們就可以讓一切重回正軌了。", rewards = "您會收到：\n\n尊崇土靈紋章"}
MultiLanguageQuestData['tw'][78762] = {title = "你的第一個發現", objective = "根據過時的地質學課本練習挖掘。", description = "我們有個新發現！這看起來像是我以前當學生的舊書。哈！\n\n你現在的工作是清除上面的所有泥土，記得要小心一點。我們處理的文物非常脆弱，要是讓文物遭受破壞，還不如乾脆埋在土裡就好。\n\n強化你的元素生物才只是一半的工作。你還需要利用環境，確保一切保持平衡，才能安全地挖掘。", progress = nil, completion = "好了。無論如何…這就是你的第一件文物。\n\n我們在現場發現的東西通常會更加有趣。不過你至少可以留著這個當做紀念！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78820] = {title = "高科技占測：伊吉拉崗哨之謎", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78821] = {title = "綻放的夢境種子", objective = "在翡翠夢境中種下夢境種子。", description = "翡翠夢境的一切全都與和諧和自然的平衡息息相關。為了讓埃達希爾能夠綻放，我們需要在世界之樹旁種下不同的植物。你可以在任一處的肥沃土壤種下種子。", progress = nil, completion = "謝謝你！雖然這些看似小小的舉動，卻能滋養翡翠夢境，還能使埃達希爾長得更加茂盛。", rewards = "您會收到：\n\n種子花收穫的夢境種子貯藏箱"}
MultiLanguageQuestData['tw'][78827] = {title = "去拿走蠟燭！", objective = "為剛達加茲旅店的可疑的排氣口偷取蠟燭。", description = "咳咳！喂，就是你！沒錯，就是你！\n\n<你聽見排氣口後方傳來推擠的聲音，隨後又傳來更加刺耳的陌生聲音。>\n\n我們…呃…我有件事要你做！你看起來很機靈、很敏捷。手腳很快，就像我們…我！像我一樣手腳很快。\n\n幫我們…我，幫我帶蠟燭來！沒錯！\n\n別問問題，去找蠟燭就對了。\n\n我們…呃…我是專家，沒錯。專家不會問問題。\n\n只會想辦法弄到蠟燭。", progress = nil, completion = "&lt;從排氣口傳來熱情的唱歌聲。&gt;\n\n蠟燭！蠟燭！蠟燭！\n\n安靜！噓！別讓那些石頭人聽到…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78837] = {title = "盛大而危急的情況", objective = "在剛達加茲與代言者布琳瑟會面。", description = "我得知了許多有理有據的擔憂。即便至高代言者無所作為…我們也必須針對奈幽蟲族採取一些措施。如果他不做點什麼，那就由我來代勞。\n\n至高代言者把我派遣到地表，原因是我「不講道理」。我們應該有機會去和他…講講道理。我們必須去剛達加茲。", progress = nil, completion = "講道理就到此為止。\n\n鳴響深淵有很多的問題，很顯然至高代言者為此心煩意亂。他聽起來很困擾！\n\n&lt;name&gt;，如果你和你的夥伴可以幫助我們解決這裡的一些難題，也許我可以說服機語者幫你對付奈幽蟲族。那是個困擾我們所有人的問題。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78838] = {title = "機械中的齒輪", objective = "陪布琳瑟與剛達加茲的土靈對話。", description = "剛達加茲是我的家鄉。或者至少該說，在至高代言者認為我很適合被重新發配到地表之前，是我的家鄉。我想念家鄉，但它已經…變了。\n\n隨著機語者的數量減少，我們正在與時間賽跑。\n\n最近，繁重的工作讓我們疲憊不堪，但是，一如往常，我們必須任勞任怨。\n\n讓我帶你到處參觀一下吧。有幾位土靈我想介紹給你認識。", progress = nil, completion = "問題正在增加，而我們的數量正在減少。\n\n至高代言者分心了，狗頭人在攻擊，泰洛科的貨物不見了，而土靈輪班後沒有回來。\n\n要從哪裡開始？看來我們面臨的是很艱難的考驗。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78839] = {title = "狗頭人重擔", objective = "在失去的礦坑殺死入侵的狗頭人。", description = "遏制我們的損失並奪回礦坑的第一步雖然令人不悅，但卻淺顯易懂。沒有了手下，這個蠟燭大王對剛達加茲的威脅就會變小。\n\n<name>，你看看能不能在攻勢越發猛烈之前，削減敵人的數量。", progress = nil, completion = "殘忍的做法，但這是必要的手段。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78860] = {title = "更多蠟燭！", objective = "為剛達加茲旅店的可疑的排氣口偷取更多蠟燭。", description = "我…呃…我們…不對，我！喔，陰影之人，我想跟你談筆新的交易。\n\n更多蠟燭！\n\n作為回報，你會得到…呃…\n\n<一陣閃爍其辭後傳來了新的聲音。>\n\n你弄到更多蠟燭！然後交給我們！交給我！\n\n蠟燭！蠟燭！蠟燭！\n\n<興奮、微弱的唱歌聲持續了一段時間。>", progress = nil, completion = "咳！你辦到了！\n\n更多蠟燭…\n\n…用不完的蠟燭。\n\n&lt;從排氣口傳來敬畏的驚呼聲。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78861] = {title = "支援協調者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78863] = {title = "枝幹之下", objective = "到埃達希爾找泰蘭妲和珊蒂斯。", description = "謝謝你，以及所有守護翡翠夢境的凡人，新的世界之樹如今已扎根在巨龍群島。\n\n埃達希爾的枝幹將會成為充滿和平與安寧的避風港，也是個讓在泰達希爾喪命的卡多雷靈魂安息的地方。\n\n泰蘭妲‧語風和珊蒂斯‧羽月現在就在世界之樹上。他們有話想跟你說。", progress = nil, completion = "歡迎來到貝拉梅斯，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78864] = {title = "回歸", objective = "與珊蒂斯‧羽月交談。", description = "反思與改變的時候到了，$p。為了這個世界，也為了我的族人。\n\n我和母親一直在討論將我們帶來此處的因緣…以及這在之後又會產生什麼樣的結果。\n\n來，我們談談吧。", progress = nil, completion = "我父親終於回到我們身邊了，&lt;name&gt;！", rewards = "您會收到：\n\n紫羅蘭卡多雷睡墊紫羅蘭卡多雷背包"}
MultiLanguageQuestData['tw'][78865] = {title = "手足情盡", objective = "與維蘭諾斯談話。", description = "$p，為了避免你對現況志得意滿，我帶了壞消息來給你。\n\n不久之前，我收到一個意料之外的邀請…來自伊瑞迪柯隆。\n\n雖然我通知了雅立史卓莎，但我從前的兄弟明確表示我必須單獨赴約。而我也這麼做了。\n\n你一定會想聽聽他說了什麼。", progress = nil, completion = "我不清楚伊瑞迪柯隆接下來打算做什麼。但我再也不能稱他為「兄弟」了。", rewards = "您會收到：\n\n"}
