MultiLanguageQuestData['tw'][78874] = {title = "召喚幫忙", objective = "為剛達加茲旅店的旅店老闆布拉克斯製造魔法食物。", description = "如果你想要食物，柔軟可入口的食物，我們恐怕愛莫能助。目前這裡只剩下超棒的岩石和寶石。\n\n其實這已經開始變成麻煩了。\n\n話說…這種情況你完全幫不上忙，對吧？幫我們替那些有血有肉的傢伙弄一點吃的？", progress = nil, completion = "用鐵錘敲我，然後叫我鐵砧吧！好多食物啊！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78875] = {title = "不死之身", objective = "從麥佐斯身上取回祭壇核心部件。", description = "我敢打賭這一切都是麥佐斯那個老巨魔搞的鬼。他早該在很久以前就死去的，但他的魔法依舊十分頑強。\n\n他利用祭壇的核心部件作為媒介，吸收盧考的力量。\n\n將核心部件奪回來，證明失去羅亞力量的他根本就不是什麼不死之身。", progress = "你成功證明麥佐斯並非不死之身了嗎？", completion = "那個核心部件非常重要。它的功能是直接吸取盧考的能量。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][78876] = {title = "發光的紀念物", objective = "在翡翠夢境中前往埃達希爾或中央營地，並將恆光餘燼交給維蘭諾斯。\n\n已提供物品：\n", description = "<一個非比尋常且永不熄滅的餘燼吸引了你的目光。而且它還散發出了純淨且原始的熱氣。>\n\n<維蘭諾斯對這個一定會感興趣的。>", progress = nil, completion = "這是洪荒烈焰的餘燼，而且似乎沒有被那該死洞窟中的暗焰給影響…\n\n謝謝你。這股溫暖讓我不禁想起我那很久很久以前曾有過的兄弟。", rewards = "您會收到：\n\n再生元龍：暗焰的化身"}
MultiLanguageQuestData['tw'][78877] = {title = "祝福這些住家", objective = "祝福剛達加茲各處的薰香。", description = "認知神聖的存在。\n\n自從我有記憶以來，我每天都走同一條路，點燃家園各處的薰香。我的關節因此磨成灰，但這是很重要的工作。\n\n神聖的工作。\n\n在這個黑暗的時期，也許你可以為我們小小的儀式賜予你的祝福？", progress = nil, completion = "我們都是機器中的一個小齒輪。我們轉了又轉，轉了又轉…\n\n這之中蘊藏著一種美。\n\n一種寧靜。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78879] = {title = "喚起熔爐", objective = "想辦法點燃剛達加茲外側的熔爐。", description = "哼！這個炸掉的熔爐已經快不行了。我們想修好它，但是，當地心通途崩塌時，石匠伊薩克正在曳鐵運輸站換班，結果就是…\n\n再也沒人能修好它了。\n\n要是你能想辦法讓它再動起來，剛達加茲會欠你一份恩情！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78880] = {title = "東部王國杯正式開打", objective = "到暴風城拜訪安德斯塔茲領主。", description = "馭天者！安德斯塔茲領主離開巨龍群島前去造訪暴風城了。他正在招募像你這樣有實力的馭天者，去參加新的賽事！", progress = nil, completion = "感謝你的造訪，馭天者！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78881] = {title = "東部王國杯正式開打", objective = "到奧格瑪拜訪安德斯塔茲領主。", description = "馭天者！安德斯塔茲領主離開巨龍群島前去造訪奧格瑪了。他正在招募像你這樣有實力的馭天者，去參加新的賽事！", progress = nil, completion = "感謝你的造訪，馭天者！", rewards = "您會收到：\n\n"}
