MultiLanguageQuestData['tw'][78893] = {title = "青銅碎塊", objective = "使用崩解之沙技能召喚崩解之沙，然後將崩解外套放進崩解之沙，將其拆解成青銅幣。", description = "潘達利亞的商人不會想要收購你在這個時間線裡找到的裝備。\n\n你可以利用恆龍軍團的魔法，將不需要的裝備轉換成青銅幣。\n\n使用崩解之沙技能，拆解崩解外套。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n青銅幣"}
MultiLanguageQuestData['tw'][78894] = {title = "無限成長", objective = "如果交給我足夠的青銅，我就能強化你的裝備。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n青銅幣"}
MultiLanguageQuestData['tw'][78895] = {title = "籠罩剛達加茲的陰影", objective = "追蹤在剛達加茲獵殺土靈的東西。", description = "你看起來很危險。\n\n<托奇朝地上吐口水。>\n\n那很好。我們就需要危險。有東西正在剛達加茲橫行。\n\n這東西很難纏，\n\n而且是最近才出現。\n\n就在地心通途崩塌之前，我開始接獲報告，說工人工作到一半就失去蹤影。我們唯一能夠找到的只有奇怪的石塊。\n\n大多是手指。\n\n要是你能揪出在我的地盤橫行的東西，我會欠你一個人情。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n仇恨刀刃仇恨刀刃"}
MultiLanguageQuestData['tw'][78897] = {title = "是福是禍", objective = "消滅10隻幼蟲場的蟲子。", description = "這個地方被洞穴鑽孔蟲入侵了。牠們對四通八達的根系造成威脅。\n\n沒錯，世界樹是許多生物賴以維生的地方，但這之中並不包括一小群啃食樹葉的害蟲。這是一場蟲害，為了所有人好，必須削減牠們的數量。\n\n但我因為誓言而無法介入此事。但你…並沒有發下這樣的誓言。你願意完成這項重要任務嗎？", progress = nil, completion = "感激不盡，陌生人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78898] = {title = "意圖與直覺", objective = "從召蟲者伊茲提克林身上取得歌唱石。", description = "洞穴鑽孔蟲一般不是群居生物。看到這麼多隻聚集在同一個地方，一定有古怪。\n\n附近一定有奈幽蟲族的召蟲者。\n\n找到他們，取回他們用來把這些蟲子召來這裡的工具。有了它，我們就能及時把蟲子引開。", progress = "我感覺到有更多蟲子正在靠近。就像有東西把牠們引來這個地方一樣。", completion = "真是個奇異的寶石。\n\n一定是其中的歌聲把蟲子引來這個地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78900] = {title = "冷酷的黑色翅膀", objective = "在剛達加茲追蹤鳴響死神。", description = "你是從地心通途下來的，對吧？從最上面？\n\n<托奇輕笑。>\n\n城市中的土靈面臨極大的威脅。在下面這裡，死亡無所不在。\n\n可能會從下方。也可能是從上方。\n\n你過去似乎殺了不少野獸。有沒有意願再多殺幾隻？", progress = nil, completion = "那隻兇惡的蝙蝠其實沒那麼兇惡，對吧？\n\n歡迎來到剛達加茲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78901] = {title = "救...命！", objective = "救援絲凱吉‧燼砰。", description = "喂！\n\n把我弄下去！遠離這些蟲子！拜託！\n\n我會付錢給你！我會欠你人情！我會很樂意出賣任何你想要抹黑的集團成員！\n\n只要把我弄下去就好！\n\n還有，別走太多步。牠們聽得到你的腳步聲。如果你不想被蟲群追著跑，就在岩石上跳躍移動。", progress = nil, completion = "好好好！我沒事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78902] = {title = "委託挖掘", objective = "獲取25塊希維石。", description = "好了，我累不累，我自己知道。所以，我打算雇你擔任我的金幣勇士…又叫金勇。\n\n這全都是我偉大事業的一環。這裡的蟲子很擅長挖出貴重的礦物，就像鼴鼠人擅長嗅出高品質的蘑菇一樣。\n\n我願意賭上我所有的錢…還有你的性命…相信牠們找到了希維石的礦脈。超棒的東西，不過我不認為<class>會知道它有什麼用途。\n\n不如這樣吧，帶一批這種礦物給我，收益就我們兩個人平分！", progress = "東西拿回來了嗎？", completion = "大豐收！這應該能讓我們在姆瑪爾有個好的開始，順便讓那些傻瓜見識我的厲害。\n\n這是你的分成。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78915] = {title = "「瓜」除威脅", objective = "移除8顆影酸臭瓜並殺死10隻影酸蜱蟲。", description = "我需要你的幫助！\n\n巨大的影酸臭瓜開始到處生長。它們既難聞，上面又爬滿了噁心的蜱蟲。\n\n我的父母帶來了幾艘飛船來幫我們把瓜果拔出來，但那些蟲子讓這件事變得很危險。\n\n你能把繩子綁在影酸臭瓜上嗎？這樣一來飛船就可以把它們拖走，也不會搞得一團亂。", progress = nil, completion = "你辦到了！我聽說，有一次臭瓜重到害飛船墜毀！幸好沒發生這種事。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][78918] = {title = "布拉克斯的黃銅指虎", objective = "殺死剛達加茲附近的生物以找到布拉克斯的黃銅指虎。", description = "我有個提案。\n\n我們這裡時不時會出現一些奧客。他們不是壞人，但我們的人工作很認真，有時候情況失控的速度會比鐵錘落下的速度還快。\n\n我通常會用力敲他們的頭頂，讓他們搞清楚狀況，不過我到城鎮外圍幫看守者托奇清除怪物的時候，弄丟了我的指虎。\n\n可以去幫我拿指虎，然後來個幾次愛的敲頭嗎？", progress = "現在，我最後一次用那些指虎打的野獸是什麼呢…", completion = "那就是指虎的功用。它們能讓你的手保持完好！", rewards = "您會收到：\n\n布拉克斯的黃銅指虎"}
MultiLanguageQuestData['tw'][78929] = {title = "來陰的", objective = "救出5個阿拉希俘虜。", description = "寇拜斯潛伏在渾水的淺灘中，以比毒蛇還快的速度，捕捉靠近水邊的獵物！\n\n這還只是牠們獨立狩獵的情況。一旦成群結隊，牠們將會是不容小覷的威脅。自從我們來到這裡，牠們一直是外圍村莊的一大隱患。\n\n一有機會，牠們就會把受害者活活吃掉。我們必須拯救已經被拖到水裡的村民！", progress = nil, completion = "謝謝你，&lt;name&gt;。這些人傷得很重，不過，我想他們會撐過去的。裡面有些人似乎有治療能力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78931] = {title = "高科技占測：龍顱島之謎", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78932] = {title = "難以捉摸的怪物魚", objective = "殺死13個寇拜斯入侵者。", description = "看到你雙眼發光，你該不會想跟法林一起瘋吧？\n\n闖進寇拜斯的水域？在一片黑暗中？\n\n你這個蠢貨是想找死吧。\n\n盡你所能殺掉那些該死的魚，別讓牠們把你拖進水裡當成晚餐。", progress = nil, completion = "敵人是不會休息的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78933] = {title = "甜美日蝕", objective = "收集8顆暗根柿子、30份蛙吻魚子醬和1份以太蜜糖。", description = "我打算製作非比尋常的甜點，就連聖光最虔誠的追隨者都會愛上！\n\n為了讓甜點的味道在光暗之間取得平衡，我需要來自多個黑暗地域的食材。\n\n請幫我收集下列食材：蛙吻魚子醬、暗根柿子和以太蜜糖。", progress = "你找到所有的材料了嗎？", completion = "現在魔法奏效了。請親自品嘗這個作品。", rewards = "您會收到：\n\n甜美日蝕燈火者補給包共鳴水晶聖落之地阿拉希青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][78934] = {title = "阿拉希之劍", objective = "用聖焰點燃火炬，然後在席娜的期盼集結6群阿拉希人。", description = "我相信你的實力。我必須請你前去增援席娜的期盼。我和安杜因會把居民送到羅萊十字路的安全處。\n\n黑暗和寇拜斯接踵而來，席娜的期盼居民的內心將會深陷恐懼。我們不能對他們不管不顧。\n\n用小鎮中央的聖焰點燃火炬，藉此激發居民的勇氣，居民才不會坐以待斃。\n\n我們會追上你。願聖焰指引你的道路，我的朋友。", progress = nil, completion = "阿拉希人堅毅又高傲。寇拜斯或許詭計多端，但牠們今天別想取勝。", rewards = "燈火者的火炬燈火者未點燃的火炬您會收到：\n\n"}
MultiLanguageQuestData['tw'][78936] = {title = "怪魚危機", objective = "在席娜的期盼殺死深淵淤泥、可惡的破浪者和浪潮領主提斯雷奇。", description = "你們這些外來者和法林成功倖存下來，還救了海邊的村民？\n\n<鐵擊鬆了一口氣，快速祝禱一下。> \n\n我們在這裡遇到麻煩了。來襲的寇拜斯派出最強大的部隊到村民的家門口。\n\n我們光是守住戰線，就已經疲於奔命。如果你能解決那些怪物，我們或許就能扭轉局勢。", progress = "當我們第一次遇到寇拜斯時，我們當中的某些人曾試著跟他們和平共處。但很快就發現他們只把我們當成食物。", completion = "每個阿拉希人殺死的寇拜斯已經多到數不清了。而死在寇拜斯手中的阿拉希人，也是多到數不清。\n\n我不清楚他們來自哪個水下洞窟…光是想到，我就全身發抖。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78937] = {title = "暗影交疊", objective = "調查附近的黎明塔。", description = "<法林張大眼睛，驚訝地四處張望。>\n\n剛剛發生什麼事？你看到那個暗影了嗎？而且那個油井…陷入一片漆黑？\n\n我以前從沒見過像這樣的事。\n\n那會是附近的那座黎明塔嗎？我們必須快點！", progress = nil, completion = "這些人的恐懼和恥辱就像煙霧一樣，瀰漫在空中。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78938] = {title = "水領主的勇士", objective = "在璀璨回音事件中，擊敗記憶中的拉格納羅斯。", description = "我必須很遺憾地通知你，在這個凡人國度中，有個可怕的威脅正等著你們。火元素領主拉格納羅斯正在等待時機，準備把艾澤拉斯燒個精光。我們水元素一直與那些次級元素生物交戰不休。請相信我們的示警絕非誇大其辭。\n\n證明你的信念！徹底剷除拉格納羅斯！", progress = nil, completion = "你做到了你們種族大多數人都認為做不到的事。你迎戰拉格納羅斯，並獲得勝利！\n\n以一個如此渺小的生物來說，你足智多謀。\n\n有朝一日，我們或許會發自內心擁戴你的種族和水領主。", rewards = "您會收到：\n\n殘存記憶"}
MultiLanguageQuestData['tw'][78939] = {title = "黯淡的烈焰", objective = "調查失去光明的黎明塔。", description = "這群…自稱黑夜教團的人，他們舉行邪惡的儀式，撲滅黎明塔的烈焰。我不清楚詳情。\n\n我們應該調查一下。", progress = nil, completion = "所以，他們也殺了凱瑟？\n\n&lt;法林緊閉雙眼，一邊禱告，一邊咒罵。&gt;\n\n我們會給他一個體面的葬禮。黑夜教團會為此付出代價。\n\n幾年前，我們封掉了附近的幽岩蔽蔭洞穴。他們一定是想辦法挖了進去，才能鎖定這座黎明塔。\n\n他們到底盤算這個計畫多久了？黑夜教團混入我們之中到底有多久了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78941] = {title = "扭轉局勢", objective = "到聖落之地與鐵擊將軍會面。", description = "薩拉塔斯的軍隊擁有攻擊我們的能力已經一段時間了。所以她選擇這個時機的原因是什麼？\n\n有哪裡不太對勁，她等我們組織軍隊來回應，然後又公開攻擊。我們正被她玩弄於股掌之上。\n\n去向阿拉希將軍報告。我會直接前往戰場。", progress = nil, completion = "很好，你來了。我會長話短說。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78942] = {title = "卡茲阿爾加的力量", objective = "擊退奈幽蟲族。", description = "先驅者以為她能打得我們措手不及，不過，要是她認為自己絕對會贏，那就太天真了。\n\n阿爾加進攻部隊隨時支援你，<name>。別留任何活口。", progress = nil, completion = "部落和聯盟組成了一支強大的軍隊。要是沒有他們，我不認為我們能有多少進展。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][78943] = {title = "鋼鐵與烈焰", objective = "鼓舞20支阿爾加進攻部隊。", description = "我們的部隊或許能夠獨自作戰，不過，看到你出現在戰場上，有助於提振他們的士氣。\n\n帶著這個戰爭號角。吹響號角，讓我們的敵人充滿恐懼。一旦你成功鼓舞我們的部隊，就回去找你的指揮官。", progress = nil, completion = "你來得正是時候。", rewards = "您會收到：\n\n阿爾加看守者法衣阿爾加看守者兜帽阿爾加看守者護脛阿爾加看守者頭盔勇氣石"}
MultiLanguageQuestData['tw'][78948] = {title = "黑暗中的聖光", objective = "與安杜因談話並追擊薩拉塔斯。", description = "情況非常不對勁。隨著戰火持續延燒，雙方都變得越來越激進。\n\n艾蘭里亞似乎知道一些事，戰鬥到一半，她突然跑走了。我們一直在追她，但我不能放任這些士兵死亡。她就在前面，我們可以一起去跟她會合。", progress = nil, completion = "卡德加急需幫助。我們之後會有時間慶祝的。", rewards = "您會收到：\n\n燈火者披氅勇氣石"}
MultiLanguageQuestData['tw'][78950] = {title = "斷足", objective = "殺死奈幽蟲族副官。", description = "雖然我們還沒找到薩拉塔斯，但我們收到報告，表示戰場深處有奈幽蟲族正在發號施令。這個消息不會讓我們得到太多優勢，但每一個行動都至關重要。\n\n解決他們。希望這會給我們多一點喘息空間。\n\n完成後，去找安杜因。他和那個阿拉希小女孩去追艾蘭里亞了。", progress = nil, completion = "噢，很好，你成功了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][78951] = {title = "暗影漸深", objective = "到崖壁信標下方的洞穴殺死10個黑夜教團教徒。", description = "當我抵達聖焰所在的地方時，我感受到注入其中的無窮絕望與無力。\n\n這讓我痛苦不已，但是…單憑我的光芒，並不足以驅散這些暗影。\n\n因此，我們要採取更直接的方式。如果剩下的教徒已經撤退到幽岩蔽蔭，那一定是他們合力讓聖焰持續黯淡。\n\n我們必須阻止他們，不能讓黑暗散播開來。", progress = nil, completion = "&lt;法林咬緊牙關。&gt;\n\n他們已經做出選擇了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78952] = {title = "最後的抵抗", objective = "摧毀暗影裂隙。", description = "<法林用飽含怒氣的氣聲說話。>\n\n做得好。不過，在我們離開之前，還有件事要做。\n\n在這條路上，有幾個強大的牧師。我覺得他們正在召喚某個東西，很大的東西。毫無疑問，這是要從上方襲擊我們，把我們趕出黎明塔。\n\n情況會非常危險，但必須阻止他們。你願意幫我嗎？", progress = nil, completion = "&lt;法林疲憊不堪，眼神渙散。&gt;\n\n就是沒完沒了，是嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78954] = {title = "烈焰復燃", objective = "在崖壁信標協助法林讓神聖火焰復燃。", description = "你感覺到了嗎？希望的回歸？\n\n謝謝你的幫忙，<name>。\n\n黎明塔的烈焰仍然黯淡。不過，我想這次我們能讓它復燃。\n\n我們在黎明塔會合。", progress = nil, completion = "&lt;法林露出疲憊卻溫暖的微笑。&gt;\n\n謝謝你。感謝聖光，你們都願意出手相助。很高興我們能夠互相幫忙。", rewards = "您會收到：\n\n席娜堅兵頭盔席娜堅兵鎖子甲席娜堅兵護脛席娜堅兵風帽共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][78972] = {title = "收割之災", objective = "控制收割機器人雷米，將4個捲心菜和4根胡蘿蔔裝入推車。順便殺死12隻入侵的甲蟲。", description = "我們的父母跑去對抗入侵農場的怪物。當他們不在時，我們想讓農場持續運作。\n\n我們有台收割機器人幫忙處理雜事，但我老是把它開進河裡。要是你可以幫我們駕駛收割機器人，我們就能順利完成工作！", progress = nil, completion = "你很擅長控制雷米。或許你下週也可以回來幫忙！", rewards = "您會收到：\n\n燈火者補給包共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][78974] = {title = "照顧甲蟲", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78978] = {title = "惹事生臭", objective = "到銀松森林的影牙城堡入口找警探凸栓。", description = "那些線索串連成了一個噁心的真相，<name>。\n\n地圖顯示，王冠公司在銀松森林有個重兵把守的行動基地。然後根據那個備忘錄和配方公式，看來他們正在研究某種會令人成癮的毒物。\n\n我認識有個人能給我們一些…巧妙的東西，可用來對付王冠公司。我先去找他，然後再到影牙城堡外面跟你會合。", progress = nil, completion = "你來了。很好，時機正好。\n\n我已經想到一個計畫，可以破壞這場生化陰謀。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78979] = {title = "用自己的方式愛自己", objective = "在剃刀嶺旅店小睡一下。", description = "參加這場慶典時，我打算在剃刀嶺旅店住一晚。雖然外觀看不出來，但住起來其實相當舒適！\n\n你何不看看他們那邊還有沒有空床？\n\n我覺得自己也要休息一下…就在…這裡…休息…", progress = nil, completion = "…啥？喔！歡迎回來，休息夠了嗎？\n\n平常，你總是為別人全力以赴。\n\n今天，你終於為自己全力以赴。沒有比這個更好的禮物了。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78980] = {title = "到處看看", objective = "到禮品盛會找商人和賓客。", description = "在禮品盛會這裡有很多手藝精湛的工匠，專門為你和你珍視的人們製作禮物。但我這句話也不全然正確，也有不少人是專程過來享受這場盛會的！\n\n去吧，跟那些賓客聊聊，同時看看那些工匠賣的東西。你說不定能找到最完美的禮物！", progress = nil, completion = "如你所見，有一大堆的禮物要送！\n\n去幫你在意的人選一個禮物吧！", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78981] = {title = "愛就在身邊", objective = "到杜洛塔的石牙農場附近參加禮品盛會。", description = "聞聞這些玫瑰！我的伴侶在禮品盛會替我拿來的。\n\n想自己去逛逛嗎？地點就在杜洛塔的城門。那裡擺滿了禮物和食物，尤其是巧克力，簡直讓人愛不釋手！", progress = nil, completion = "朋友，歡迎來到禮品盛會！\n\n你想進一步了解我們的特製巧克力嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78982] = {title = "嗅到問題", objective = "使用O.D.I.E.遙控器在奧格瑪各地尋找線索。", description = "你也聞到那個怪味道了吧？聞起來就像廢氣、廉價古龍水，還有鍊金術那一類的怪東西。我敢說，王冠化學製藥公司一定有什麼陰謀。想要幫我挖掘它的真相嗎？\n\n來，認識一下我的夥伴。看起來像是一隻土狗，但其實這是簡稱「O.D.I.E.」的嗅覺偵測與檢查引擎！有了這傢伙，我和你就能在一公里外嗅出王冠公司的陰謀！\n\n如何？你要加入嗎？我需要夥伴一起解決這件事。", progress = "O.D.I.E.是能夠嗅出線索，不過還是得你靠你來拼湊出真相。", completion = "有毒的香水？為了自己被踢出城市而復仇？\n\n看來藥劑師胡默爾正在策劃什麼陰謀。情況似乎不怎麼妙。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78983] = {title = "不請自來的禮物", objective = "在奧格瑪各處殺死8個王冠化學製藥公司成員。", description = "我嚴重懷疑王冠化學製藥公司的間諜已經混入我們之中。不過，我知道你知道這個O.D.I.E.知道如何鎖定他們的氣味！\n\n不過我們還是不要打擾到那些只是單純來享受過節氣氛的人吧。張大鼻孔聞出化學臭味，確保我們針對的是正確的目標。", progress = nil, completion = "哎呦，&lt;name&gt;，你太臭了！\n\n\n\n更慘的是，我也很臭！\n\n至少，我們讓慶典變得和平一點了。可不能讓王冠公司毀了這場慶典。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78984] = {title = "擊潰王冠公司", objective = "使用工匠糖果炸彈摧毀王冠補給品，並擊殺王冠公司成員。", description = "看來胡默爾設置了一些防衛措施。不過別擔心，我也帶了一些特殊的禮物。\n\n<凸栓指了指那個未標記的箱子。>\n\n炸彈。我帶了炸彈。\n\n遊戲時間結束了。拿炸彈丟那些王冠公司的人和他們的補給品。讓他們見識一下高超工藝的威力。等我們破壞了他們的行動，就能著手對付胡默爾了。", progress = nil, completion = "哇，我最喜歡煙火秀了！做得好，&lt;name&gt;。這應該能稍微拖慢他們的腳步。\n\n現在只剩下胡默爾了。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78985] = {title = "復仇的惡臭", objective = "與凸栓談話，迎戰王冠化學製藥公司，並擊敗藥劑師胡默爾。", description = "除非解決幕後黑手，否則一切都還沒結束。\n\n我跟你說，藥劑師胡默爾就藏身在影牙城堡，帶著他的親信製作新一批毒香水。要是他的研究成功，奧格瑪的所有人都會沒命。\n\n你必須全力以赴，夥計。進入城堡、破壞他的陰謀，別讓我們所有人變成散發薰衣草香的屍體。", progress = nil, completion = "聽起來你及時趕到了。幹得好！\n\n要是讓胡默爾成功在慶典下毒，事情肯定會變得一團糟。\n\n就當這是送給他們的一份大禮吧！", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78986] = {title = "灰白之丘景點傳送門", objective = "經由景點傳送門前往灰白之丘，為拉雯摘一束花。", description = "早安！今天的特殊傳送門充滿魔力，會帶你前往北裂境的宏偉森林！\n\n但我有個忙想請你幫一下，因為你看起來很有冒險精神。\n\n請你幫我送一些灰白之丘的花，給一個名叫拉雯的美麗女性。\n\n我很想自己去送…不過你也看到了，她實在美到讓人望之卻步。", progress = "那個製造傳送門的法師？\n\n<拉雯咯咯笑。>\n\n讓我看看。", completion = "逛這個盛會的時候，很容易就會有新發現…\n\n&lt;拉雯一邊無意識地摘著花，一邊朝著奧蘿拉的方向凝視。&gt;", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78987] = {title = "納葛蘭景點傳送門！", objective = "經由景點傳送門前往納葛蘭，為卡恩拍攝野生動物的照片。", description = "早安！今天的特殊傳送門充滿魔力，會帶你前往納葛蘭的廣闊平原！\n\n話說，我有個提議，你想聽聽看嗎？要是你能把拍到的照片送去給我親愛的好朋友卡恩，我就把相機借給你。\n\n他最近一直在納葛蘭流浪，迷失在他自己的思緒當中。像他這麼固執的人，我很確定他會感激有個人能陪他。我很想親自去，但我必須在這裡維持傳送門。", progress = nil, completion = "他要你做什麼？\n\n他知道拉雯…呃啊！我想，我就是老是這樣猶豫不決，才會有這種報應。\n\n沒關係。一切都很好，奧蘿拉，真的很好…\n\n呃，無論如何還是要謝謝你，&lt;name&gt;。問題出在我身上，你不用愧疚。我會想其他辦法吸引拉雯的注意。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78988] = {title = "菲拉斯景點傳送門！", objective = "經由景點傳送門前往菲拉斯，將丟失的禮物交給正確的失主。", description = "早安！今天的特殊傳送門充滿魔力，會帶你前往菲拉斯的陽光沙灘！蒸汽之池渡假村正在舉辦歡樂慶典，歡迎任何人參加！\n\n不幸的是，先前有些糊塗的參加者穿過傳送門，卻把自己的禮物留在這裡。\n\n你能幫我歸還這些禮物嗎？到沙灘找我，我們一起找出禮物的失主吧。", progress = nil, completion = "你真的幫了大忙，&lt;name&gt;。很多找回禮物的失主看起來都歡天喜地。\n\n而且禮物未免太多元了吧！或許大家表達愛意的方式都不一樣。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78989] = {title = "療癒自我的禮物", objective = "與甯談談，發現內心的渴望。", description = "你的眼神看起來像個疲倦的冒險者。\n\n你是為許多人盡心盡力的<class>。你還記得上次對自己好一點是什麼時候嗎？\n\n也許是時候對自己好一點了。面對自己的內心吧。\n\n你自己究竟想要什麼？", progress = nil, completion = "讓我們開始自我療癒吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78990] = {title = "疏解壓力的禮物", objective = "在禮品盛會與托卡‧斷骨者談話，然後到奧格瑪疏解壓力。", description = "大家都知道，像你這樣的冒險者全都背負著沉重的負擔。而現在就是最好的時機，來解決這些問題。\n\n我看到這附近有個老兵。他可能會知道疏解壓力的方式。\n\n或許他會有些想法，能夠指引你。", progress = nil, completion = "感覺有好一點嗎？\n\n累了一整天後，得好好照顧自己的身體。照顧好自己的身心，才能走得遠。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78991] = {title = "放鬆身心的禮物", objective = "請教『重生者』札姿如何放鬆身心，然後到北貧瘠之地的怒水河旁放鬆一下。", description = "沒錯，愛是贈禮。但也可以是你送給自己的禮物。\n\n有時候，愛自己的最好方式就是放輕鬆。\n\n我在怒水河的對岸遇到一個食人妖，她似乎在這方面很有心得。也許你可以向她請教放鬆身心的方式。", progress = "真愛正在讓你放下戒心。只要放輕鬆，你就能明白我的意思。", completion = "你感覺煥然一新了，對嗎？面對生活中的各種問題，我們都需要喘口氣。\n\n放鬆身心幫助我重新發現自我。甚至改變了我整個人生。我原本可是留著長長的獠牙和莫霍克頭耶，噗哈哈哈！我以前真是個蠢男生。\n\n你也多認識自己一點了嗎？", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78993] = {title = "用自己的方式愛自己", objective = "品嚐禮品盛會商人的數袋點心。", description = "人生一大樂事就是吃飽飽！\n\n盛會上有很多美食和飲料。何不買點東西吃呢？", progress = nil, completion = "平常，你總是為別人全力以赴。\n\n今天，你終於為自己全力以赴。沒有比這個更好的禮物了。", rewards = "您會收到：\n\n愛之硬幣"}
MultiLanguageQuestData['tw'][78995] = {title = "蘑菇舞步", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][78996] = {title = "武器和戰士", objective = "在芙林村跟達杜加茲收集3個武器箱，並招募5名戰士。", description = "戈洛克劫掠者最近一直在屠殺這些養殖員並偷取他們的珍珠。他們向我們請求保護，但我們可能心有餘而力不足。\n\n我知道附近有其他人可以幫忙。去找他們，並請求他們的協助。如果他們有所猶豫，就跟他們說報償是珍珠。\n\n我們也會需要給這些養殖員武器，讓他們可以保護自己。去找他們可以用的備用武器跟裝備。\n\n我會去找養殖員，盡我的能力訓練他們。", progress = nil, completion = "做得好，很高興你成功招募了一些戰士。情況比我想的還糟糕，我們的戰力越多越好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78997] = {title = "失竊的珍珠", objective = "在微光水岸從戈洛克身上取回8顆失竊的珍珠。", description = "這些養殖員採收的珍珠是他們唯一的收入來源。一部分的土靈甚至認為珍珠養殖是他們存在的主要原因。\n\n戈洛克一直在趁機竊取珍珠。在你消滅戈洛克的時候，找找他們身上有沒有珍珠。我們要盡量把它們拿回來。", progress = "我們需要把這些珍珠還給養殖員。", completion = "謝謝你，&lt;name&gt;。消滅戈洛克威脅只是我們在這裡的其中一個目標。把生活還給養殖員是另一個目標。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78998] = {title = "前線養殖員", objective = "在微光水岸分發3個武器箱給珍珠養殖員。", description = "大部分的養殖員都已經到戰場上去堅守他們的崗位。在目前的情況下，我已經盡我所能訓練他們了，可是他們拿的依然是農具。\n\n我需要你把收集到的武器分發給前線的人。雖然武器無法大幅增加他們的戰鬥能力，至少可以增加他們的信心，讓他們知道自己不是單打獨鬥。", progress = nil, completion = "太棒了，只要他們團結作戰、互相幫忙，我相信我們會取得勝利的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][78999] = {title = "英雄之心", objective = "擊敗三個戈洛克薩滿領袖。", description = "戈洛克似乎會使用召喚的元素生物來加強他們的部隊。這也是他們可以輕鬆戰勝養殖員的原因。\n\n我們已經用上全部的力量來抵抗戰場上的巨像，我需要你阻止他們創造新的元素生物。\n\n這個大小跟強度的元素生物只有最強的戈洛克薩滿能創造出來。到敵方陣線後頭去找他們，並把他們消滅。\n\n這樣應該就可以一勞永逸，解決掉戈洛克對養殖員造成的威脅了。", progress = nil, completion = "感謝你的援助，陌生人。少了你，這一切都不可能成功。你今天把我們的生計還給了我們，還有我們的希望。\n\n把這個拿去，這是我們的心意。這並不足以表達，但這是我們僅有的東西。希望你知道我們永遠歡迎你。\n\n現在，我們來談談阿嘉莎吧。", rewards = "您能選擇下列奬勵中的一個：\n\n冷光珍珠指環閃亮珍珠戒指\n\n您還會收到：\n\n共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][79009] = {title = "先驅者", objective = "在達拉然的守護者之廳與卡德加和艾蘭里亞會合。", description = "勇士，我們又再次需要你的援助了。有一道神秘的身影在黑暗中蠢蠢欲動。是先驅者…\n\n我們到守護者之廳再說吧。我也請艾蘭里亞去那裡跟我們會合了。", progress = nil, completion = "我們知道伊瑞迪柯隆把黑暗之心交給了先驅者。但黑暗之心是什麼、先驅者又打算利用它做什麼…這些都還是未解之謎。\n\n還有璀璨之歌。它出現的時機絕對不是巧合。\n\n這件事不能再拖延了。所以我希望你和艾蘭里亞可以前去調查。", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79010] = {title = "通往刃多雷的大門", objective = "跟著艾蘭里亞去特洛古斯裂隙。", description = "若這次調查與虛無有關，先問問看虛無精靈較為明智。我們需要前往特洛古斯裂隙，彙報狀況。\n\n我會跟奧姆里克談談。他能幫我們動員裂隙行者。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79011] = {title = "裂隙行者報告", objective = "在特洛古斯裂隙收集裂隙行者的報告。", description = "裂隙行者的任務是調查在艾澤拉斯出現的所有虛無蹤跡。考慮到這股黑暗勢力的危險程度，他們的使命至關重要。這是我的經驗之談。\n\n大多數的裂隙行者都被派去調查一場近期發生的波動了。聽說他們才剛回來，所以我還來不及聽他們的報告。\n\n你可以趁我和艾蘭里亞談話的時候去幫我會會他們嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79012] = {title = "虛無中的裂縫", objective = "在特洛古斯裂隙關閉5個不穩定的虛無裂隙。", description = "特洛古斯裂隙對宇宙轉移極為敏感，導致我們的家園岌岌可危，但虛無精靈…也沒得選。\n\n最近湧進來的虛無能量導致不穩定的裂隙時不時地開啟。另外，現在有許多調查正在艾澤拉斯進行，我已經找不太到裂隙行者來處理這些事情了。\n\n你能關閉沿途發現的不穩定虛無裂隙嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79013] = {title = "葛拉克朗的動亂", objective = "在龍骨荒野的葛拉克朗安息地與艾蘭里亞會面。", description = "葛拉克朗安息地，也是伊瑞迪柯隆最初強化黑暗之心的地方。我們不清楚這件聖物有什麼力量，但我們確信它現在就在先驅者手中。\n\n現在，我們有一個裂隙行者失蹤了，就在這一切開始的地方。\n\n我不認為這是什麼巧合，<name>。我們一起去北裂境調查這個地區吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79014] = {title = "溯影循跡", objective = "在龍骨荒野的葛拉克朗安息地找出虛無領域。", description = "我不常和裂隙行者共事。我習慣獨自一人完成任務。但我不會輕易拋棄他們的任何一員。\n\n我還沒有感知到裂隙行者的存在。現在最好的做法就是重新追蹤她的足跡。\n\n也就是跟隨暗影了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79015] = {title = "黑暗侵襲", objective = "面對失蹤的裂隙行者。", description = "這些虛無生物在這裡做什麼？這是先驅者的所作所為嗎？還是黑暗之心的某種力量？\n\n算了。總之我不會袖手旁觀。\n\n我們必須面對裂隙行者。我不認為現在有辦法和她講道理，但或許她能說出一點情報。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79016] = {title = "殘遺虛無", objective = "前往埃雷達斯的三傑講修院。", description = "別誤會了，<name>。我知道這是陷阱。但如果有任何找到先驅者的機會，我們就必須承擔風險。\n\n隨時做好準備。我們前進吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79017] = {title = "選擇的道路", objective = "在埃雷達斯見證艾蘭里亞的記憶。", description = "在我們眼前的這些幻影。我想它們是…記憶。我的記憶。這是先驅者造成的嗎？還是我自己？\n\n我們得進行調查，找出我們被引來這裡的原因。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79018] = {title = "孤身遊歷，我駐足良久", objective = "在埃雷達斯的三傑講修院調查最後一個記憶。", description = "我感應到前面有另一段記憶。\n\n雖然我並不想參與先驅者的遊戲，但眼下這是唯一的出路。\n\n儘管如此，我們遭遇到的危險記憶可不比那些安全的記憶還少。隨時做好準備。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79019] = {title = "保衛特洛古斯裂隙", objective = "保衛特洛古斯裂隙。", description = "不。刃多雷不會倒下。特洛古斯裂隙也不會淪陷。想都別想。\n\n<艾蘭里亞握緊手中的弓。>\n\n這些以太族爪牙和我們在奧杜亞遇到的是同一種。一定是先驅者在背後操控他們。\n\n我先繼續前進。你負責解決這裡的敵人。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79020] = {title = "空洞與虛無", objective = "在特洛古斯裂隙擊敗圖拉揚的腐化記憶。", description = "我們必須解決掉可憎的圖拉揚幻影。\n\n不能讓那個怪物為非作歹。如果不處理掉它，整個特洛古斯裂隙都會被毀掉。\n\n我會親手送它上路。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n遊俠隊長之弓\n\n您還會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79021] = {title = "璀璨警示", objective = "將暗域行者的警告傳達給達拉然的卡德加。", description = "所以現在她被稱作先驅者是嗎？真適合她。\n\n我已經感覺不到她的存在了，但別搞錯了。薩拉塔斯的邪惡遊戲還沒結束。現在艾蘭里亞只不過是她棋盤上的一枚棋子。\n\n你也一樣，命運的勇士。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n盤旋滑龍：虛無鱗片龍石"}
MultiLanguageQuestData['tw'][79022] = {title = "神秘的訊號", objective = "在鳴響深淵的深爐魔像廠與布琳瑟會合。", description = "<name>，至高代言者布琳瑟送了一封緊急信函給你。\n\n她渴望能為即將到來的戰爭提供幫助，並且正在調查深爐魔像廠中的一個神秘訊號，該處是位於鳴響深淵中的一座廢棄魔像製造工廠。\n\n你可以去那裡找她並提供你的專業知識嗎？", progress = nil, completion = "&lt;name&gt;，謝謝你這麼快就趕來。我又再次需要你的幫助了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79023] = {title = "小朋友，大計畫", objective = "向維護機械自我介紹。", description = "我追蹤一個求救訊號，最後找到了這台小型維護機械。真是耐人尋味的發現，但真正的大獎是東南方的廢棄戰爭魔像設施。\n\n如果我們能夠再次開始生產戰爭魔像，我們就能為戰爭做出貢獻。不幸的是，它已經被一群哥布林拾荒者占領了。而且我們也需要調查和評估該設施是否還能正常運作。\n\n幸運的是，我有一個計畫，與這位小小的朋友有關。你何不自我介紹一下？", progress = nil, completion = "既然介紹已經結束了，那我們就潛入這座設施吧。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79024] = {title = "工廠偵察", objective = "利用ZZ-01-47偵察魔像工廠。", description = "ZZ-01-47應該能在不吸引太多注意的情況下進到裡面。\n\n但要小心！這些哥布林很渴望得到原料，要是他們發現我們的機器人，他們一定不會放過它的。", progress = nil, completion = "所以我們現在的局面是缺能源、缺材料，還要和數量龐大的哥布林為敵。\n\n如果我有外來者的毛孔，它們現在差不多要排出水分了。這是正確的詞彙嗎？我看過你的皮膚排出水過，太了不起了。", rewards = "您會收到：\n\n鳴響深淵聖光之靴鳴響深淵肩冑鳴響深淵之握鳴響深淵脛甲勇氣石"}
MultiLanguageQuestData['tw'][79025] = {title = "計畫成形", objective = "和布琳瑟與達格蘭一起複習計畫。", description = "<name>，這對我們來說是項艱鉅的工作。但我認為，在達格蘭的幫助下，我們可以對此進行分析，並將問題一一解決。\n\n你何不帶我們回顧一下迄今為止得到的情報呢？", progress = "我們可是最聰明的人…好吧，至少在剛達加茲是。我們一定能弄清楚的。", completion = "在我們回去工廠之前，我們需要奪下水力發電壩，並讓影脈抽取站重新運作。\n\n我們開始行動吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79026] = {title = "水力發電壩勞動", objective = "讓水力發電壩重新運作。", description = "熱情過頭的狗頭人、憤怒的元素生物和損壞的發電廠。這個地方真是一團亂！\n\n你看到兩側的那些大輪子了嗎？它們應該要動起來的，但它們沒有。如果我們想讓這個地方重新開始運作，那麼我們就必須讓那些東西動起來。", progress = "我在想，我們能不能用這項技術重建巨石水壩？不覺得大有可為嗎？", completion = "嗚呼！它動起來了！\n\n只需要利用一小部分艾澤拉斯的力量，就能用來保護它。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79027] = {title = "元素恐慌", objective = "擊敗元素生物。", description = "<ZZ-01-47來回抽搐，感應器不停地掃描。他似乎害怕這片區域，如果他真的能感受到恐懼的話。也許除掉一些元素生物能讓他放鬆一點。>", progress = nil, completion = "謝謝。我確定吉吉會很感謝你。等我們完成在這裡的工作，你可以在影脈抽取站找到他們。", rewards = "您會收到：\n\n元素同調墜飾勇氣石"}
MultiLanguageQuestData['tw'][79028] = {title = "我們需要更多礦石", objective = "讓影脈抽取站重新運作。", description = "吉吉已經準備好幫助你讓影脈抽取站重新運作。", progress = nil, completion = "&lt;吉吉吹起了安心的口哨。看來它對這裡低下的維護標準不太滿意。&gt;", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79029] = {title = "大搞破壞", objective = "製造混亂，進入工業區，並重啟設施。", description = "我們回來了，而且準備好了。\n\n你和ZZ-01-47去那裡製造一些混亂。炸點東西讓現場變得一團糟，把他們從工業區吸引出來。我會趁亂潛入其中。有機會的話就來跟我會合，我們應該有機會重新啟動設施並把他們趕走。\n\n我們不需要打敗他們全部。擊敗負責監督這項行動的暗融首領，他們應該就會失去戰意了。\n\n當口袋不再有金幣進帳時，暗融的手下就會撤退了。", progress = nil, completion = "剛剛場面稍微有點危急。但如果有任何人可以在這樣的情況下把握住勝利，我知道那個人一定就是你。\n\n請你回去多恩諾加找大使，把勝利的消息傳達給大家知道。請順帶收下我的謝意，這下機語者又再次欠了你的人情。", rewards = "您會收到：\n\n破壞者肩墊破壞者之握破壞者行靴破壞者束腰共鳴水晶深淵集會勇氣石"}
MultiLanguageQuestData['tw'][79030] = {title = "代言者之聲", objective = "返回多恩諾加找艾蘭里亞。", description = "請向多恩諾加的艾蘭里亞傳達我們的勝利。我相信我們的盟友會對我們能為戰爭提供的幫助而感到高興。", progress = nil, completion = "真是驚人的消息，&lt;name&gt;！\n\n戰爭魔像甦醒，再次向著我們的敵人進軍，就像過去那樣。\n\n你對機語者偉業及所有土靈的貢獻絕對會永久流傳。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79074] = {title = "全員集合！", objective = "前往沃卓肯的鬥士庇護所，把文宣交給考德拉斯。", description = "工匠聯盟和鬥士庇護所的軍需官達成最後一個協議了！\n\n除了他們平常提供的高品質戰鬥裝備之外，符合資格的戰士還能購買代幣，這些代幣可以用來認證供戰場或競技場使用的裝備，不論是製作訂單或他們自己製作的裝備都可使用！\n\n把這個文宣交給考德拉斯即可免費換取兩個征服戰利品！\n\n- 拉布爾", progress = nil, completion = "&lt;考德拉斯先是低聲抱怨幾句，隨即非常流利地說出一大串話。&gt;\n\n拿去吧，這些是我們說好的戰利品。在製作自己的裝備或提交製作訂單使用，你的裝備就能和我所提供的裝備一樣強大。如果你在找某件特定裝備，或想用一些魔法來點綴，這個東西能完美符合你的需求。不過，你得願意多花點心力才行。\n\n有問題嗎？去工匠市場問問吧。", rewards = "您會收到：\n\n龍族征服戰利品大型龍族征服戰利品"}
MultiLanguageQuestData['tw'][79082] = {title = "繁盛綻放", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79089] = {title = "聖化清理", objective = "收復聖落之地的崇敬之地。", description = "我們的崇敬之地遭到褻瀆，如同美玉有瑕。\n\n這可能需要投入更多心力，不過，要是你能順便幫忙清理聖地，我會相當感激。", progress = nil, completion = "謝謝你，&lt;name&gt;。或許看起來不怎麼像，但這裡是我們最重要的聖地之一。\n\n我們在這裡緬懷那些亡者。我們有…很多要緬懷的人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79105] = {title = "缺口", objective = "將市民送到平臺，以保障他們的安全。", description = "儘管我很樂意追擊薩拉塔斯，但我們的當務之急是保護市民。\n\n盡可能救援市民，告訴他們前往附近的平台。我會請法師把每個人都傳送到安全的地方。", progress = nil, completion = "順利撤離第一批人了。但還需要撤離更多人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79106] = {title = "斷絕", objective = "拯救達拉然。", description = "跟我來。我們一起尋找需要救援的人。", progress = "奈幽蟲族見人就綁，把他們困在蛛網裡。務必將你找到的任何人救出來，再繼續前進。", completion = "看來能救的我們都救了。希望其他盜賊也能順利逃脫。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79107] = {title = "風暴過後", objective = "查看風暴飛騎。", description = "圖拉揚跟嘉亞拉已經開始訓練新土靈盟友來當地面部隊了。可是我們需要更多人手。我們需要更多風暴飛騎。\n\n許多人在入侵風暴駐營時丟了性命，又有更多人在奈幽蟲族攻擊中犧牲。他們的領袖，風暴守衛貝格姆也英勇犧牲。\n\n倖存的風暴飛騎在附近的檢傷站接受照護。我們必須盡我們所能讓他們跟他們的禿鼻鴉可以重返天空。在接下來的戰鬥中，他們會是土靈最強力的武器。", progress = nil, completion = "蕭班德雷的事真抱歉，她只是想要保護我。而我為了保護她也說謊了。\n\n不過，你真的不打算把她帶走嗎？你只是想要召喚更多風暴禿鼻鴉？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79108] = {title = "邪惡之種", objective = "收集腐化的影葉種子。", description = "<class>，有些影葉植物比起其他種類更加…糟糕。我不知道該如何說得更明白。\n\n我的蠢弟弟托摩西本該幫我清除這些植物，但我一直沒看到他，也等不了了。\n\n顯然我們不會想看到這些植物大肆繁衍，所以我要你盡可能除掉它們，然後撿走它們的種子。我們會用聖火燒掉種子，確保斬草除根。", progress = "你除掉那些植物了嗎？", completion = "很好，除掉那些植物了。現在，只希望我懶惰的弟弟能夠快點來工作。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79109] = {title = "跟隨咪洛", objective = "發現毛毛手殺人魔咪洛心神不寧的原因。", description = "托摩西的山貓咪洛一直在煩我。我不知道她想幹嘛，但很少看到她跟我弟弟分開行動。她是一隻很優秀的農場貓，但她還是一隻貓，說不定她今天只是覺得托摩西很煩而已？我不知道。也許托摩西陷入什麼麻煩了。\n\n可以請你找出她心神不寧的原因嗎？", progress = "<咪洛一臉期待地看著你。你正被打量中。>", completion = "&lt;咪洛發出開心的叫聲，對你發出呼嚕呼嚕的聲音。&gt;", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79110] = {title = "拯救托摩西", objective = "從貪婪黑暗手中拯救托摩西‧西爾海姆。", description = "<咪洛滿懷期待地看著你，然後看向廢墟，再看向你，接著再看向廢墟。你感覺到她想要你進去裡面。難道這裡是托摩西失蹤的地方？>", progress = nil, completion = "你從黑暗中救了我的蠢弟弟！謝謝你。", rewards = "您會收到：\n\n小香草共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][79114] = {title = "美化行動", objective = "清除鹿殼蟲谷過盛的植物。", description = "這個工作讓你…這類的人來做是再好不過了。\n\n如果你還想活著的話，你最好繼續協助我們。如果你答應的話就能獲得豐厚的報酬。\n\n拉克-亞緒以前的主人把鹿殼蟲野放了，還棄置洞穴於不顧。長時間下來，許多植物入侵了廢棄的鹿殼蟲洞穴。\n\n想辦法把它們清乾淨。什麼方法都行。", progress = nil, completion = "嗯。可以了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79115] = {title = "專業顧問", objective = "與姆瑪爾的領導者交涉，招募養蟲幫手。", description = "光憑你一個人已經不夠了。我們需要更多幫手，爬顎者和小絲蛛也需要有人監督。\n\n鼴鼠人的聚落「姆瑪爾」就在不遠處。但是，過去的強制徵召手段已經失敗了。奈幽蟲族現在被禁止進入聚落。我們需要有人替我們跑一趟。\n\n去跟那些鼠輩交涉。帶幫手回來。", progress = nil, completion = "奈幽蟲族又需要我們幫忙了？這個我倒要來聽聽…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79116] = {title = "蜘蛛光學鏡", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79117] = {title = "年輕氣盛的鼴鼠人", objective = "在姆瑪爾外找到6個鼴鼠人節肢動物專家，邀請他們到拉克-亞緒。", description = "你需要養蟲幫手，對嗎？\n\n上次奈幽蟲族要我們幫忙的時候，他們逼迫我們。他們的協商能力真的很爛！我們要的只是一點點交換條件。\n\n我們有很多個節肢動物專家，但他們大多忙著驅離飛行者。相信他們不會拒絕能夠親自近距離研究甲蟲群的機會！\n\n如果你能減輕他們的工作壓力，他們會許會接受你的提議。", progress = nil, completion = "看到了嗎？我們要的只不過是一點點交換條件。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79118] = {title = "主管換人的拉克-亞緒", objective = "回到拉克-亞緒找菲克薩倫。", description = "很好，你找到養蟲幫手了。\n\n你還在這裡做什麼？快回去啊，你不需要取得我的准許。\n\n確保奈幽蟲族不會虧待他們就好。", progress = nil, completion = "非常好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79119] = {title = "當一隻蟲還真難！", objective = "在拉克-亞緒清理蟲倉。", description = "阿努巴札爾下令了！我們是拉克-亞緒的新主人！但菲克薩倫發了一頓脾氣，還毀了我們的蟲倉。\n\n既然這個蠢貨拒絕聽從命令，說不定你這個異族人會比較聽話。或許到時候我們不會計較你偷聽我們說話，放你一馬。甚至還可能給你一些報酬。\n\n去吧。我們必須復育鹿殼蟲谷，並用甲蟲群填滿它們。", progress = nil, completion = "你證明了自己的用處，真讓我意外。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79120] = {title = "乾草堆中的甲蟲", objective = "捕捉6隻兇野鹿殼蟲，並帶回拉克-亞緒。", description = "拉克-亞緒的外圍地區還有一些兇野鹿殼蟲。\n\n這個氣味手榴彈應該足以擊昏那些蟲子，並向鼴鼠人警示牠們的位置。\n\n一旦牠們陷入昏迷，就會有鼴鼠人把牠們帶回巢穴。\n\n捉住牠們，把牠們帶回來。我們會在這裡等。", progress = nil, completion = "做得非常好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79121] = {title = "蟲蟲考驗", objective = "在拉克-亞緒與亞羅瑪許談話，照顧鹿殼蟲。", description = "喔，抱歉，你以為這是一勞永逸的工作嗎？要是你真的這麼想，在一定程度上，菲克薩倫會很樂意「送你一程」。鹿殼蟲會需要持續的照料。食物、水之類的東西。\n\n就算我再怎麼厭惡鼴鼠人也不得不承認，比起我或菲克薩倫，他們的確更加擅長照顧甲蟲群。\n\n要是這樣解釋還不夠的話，鼴鼠人會告訴你如何完成你的工作。", progress = nil, completion = "工作內容對你來說應該不算太複雜吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79122] = {title = "甲蟲偵察中", objective = "利用拉克-亞緒鹿殼蟲找到5個卡罕提松露。", description = "鹿殼蟲對阿努巴札爾的戰爭行動至關重要。我們的嗅覺也相當敏銳，但只有鹿殼蟲能夠找出珍貴的卡罕提松露。\n\n在一定程度上，卡罕提松露是很多…爆炸藥劑的關鍵材料。如果你想知道細節的話，亞羅瑪許會告訴你更多細節的。", progress = nil, completion = "我要你拿來的就是這個數量。", rewards = "瑣碎差事長手套甲殼裝飾肩衛監督者的特大扣環拉克-亞緒牧人涉靴您會收到：\n\n將軍(惡名值)卡吉"}
MultiLanguageQuestData['tw'][79123] = {title = "終身雇用", objective = "在拉克-亞緒與沙弗林談話。", description = "拉克-亞緒總算開始像個有用的甲蟲園了。\n\n看來我和菲克薩倫比較適合擔任發號施令的角色。你就繼續協助鼴鼠人。作為報酬，你可以保留一部分甲蟲群產出的財富。\n\n對於甲蟲園的開發，沙弗林有更詳盡的計畫。去找他談談。我沒有別的事要跟你說了。", progress = nil, completion = "這些甲殼蟲可不會自己照顧自己！", rewards = "這個任務線能解鎖：\n\n解鎖拉克-亞緒鹿殼蟲世界任務\n\n您還會收到：\n\n拉克-亞緒戰殼蟲"}
MultiLanguageQuestData['tw'][79124] = {title = "南部風暴導體", objective = "找到南部風暴導體。", description = "我就把我上次告訴貝格姆的話說給你聽。與風暴禿鼻鴉建立羈絆是錯的。這些生物就跟土靈一樣聰明，我敢說有些還更勝一籌。\n\n但…蘆瑟菈好像不太一樣。如果她的風暴禿鼻鴉是自願跟隨她的，那麼她召喚的其他禿鼻鴉也可能會做一樣的決定。\n\n若要召喚禿鼻鴉，我們需要貝格姆的導體。它應該就被藏在附近。仔細搜索，也可以問問這些旅人有沒有看到。", progress = "你找到導體了嗎？", completion = "奧巴里格不僅曾經是風暴飛騎，他也以風暴衛兵的身分擔任過貝格姆的左右手很長一段時間。他們似乎因為禿鼻鴉大吵了一架。\n\n可是奧巴里格說那個導體可以當作信標。如果天空之牆的風暴禿鼻鴉願意的話，它會引領牠們穿過風暴。他似乎也認為使用它的人應該是我。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79125] = {title = "卡林多杯正式開始", objective = "到暴風城拜訪安德斯塔茲領主。", description = "馭天者！安德斯塔茲領主離開巨龍群島前去造訪暴風城了。他正在招募像你這樣有實力的馭天者，去參加新的賽事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79126] = {title = "卡林多杯正式開始", objective = "到奧格瑪拜訪安德斯塔茲領主。", description = "馭天者！安德斯塔茲領主離開巨龍群島前去造訪奧格瑪了。他正在招募像你這樣有實力的馭天者，去參加新的賽事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79128] = {title = "外域杯正式開始", objective = "到奧格瑪拜訪安德斯塔茲領主。", description = "龍騎士！安德斯塔茲領主離開巨龍群島前去造訪奧格瑪了。他正在招募像你這樣有實力的龍騎士，去參加新的賽事！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79129] = {title = "禿鼻鴉集結", objective = "守護召喚儀式。", description = "導體已蓄滿能量，我想是時候跟大家一起在山頂會合了\n\n索爾已經將整個過程告訴我，也提醒我召喚風暴禿鼻鴉時，需要相信自己的感覺和直覺。\n\n要土靈相信自己的感覺和直覺，實在…很有挑戰性。\n\n你會幫我的，對不對？我不是戰士，而且上面看起來很危險。\n\n要是我出了什麼事，請保障蕭班德雷的安全。拜託你了。", progress = nil, completion = "做得好。看來天空之牆的禿鼻鴉不僅是回應了召喚。\n\n牠們其實才是主動的一方，也自己選擇了新一代的飛騎。\n\n我很榮幸能在這場儀式中幫上忙。", rewards = "您會收到：\n\n閃電痕風帽閃電痕外衣閃電痕罩盔閃電痕腿甲勇氣石"}
MultiLanguageQuestData['tw'][79130] = {title = "北裂境杯賽事", objective = "完成北裂境杯的賽道。", description = "又要來試試你的能耐了。\n\n我的青銅龍同事已經前往北裂境打造更多全新挑戰了。我們想看看有沒有任何大膽的馭天者能完成整個賽事！\n\n準備好接受挑戰了嗎？", progress = nil, completion = "你不愧是龍騎士中的佼佼者！如果你還沒試過的話，歡迎在北裂境杯挑戰你的最快時間，並取得艾澤拉斯騎士的代表色。", rewards = "您會收到：\n\n艾澤拉斯騎士徽章"}
MultiLanguageQuestData['tw'][79134] = {title = "春神復甦", objective = "在艾爾文森林的閃金鎮與吉倪亞‧布魯克斯交談。", description = "閃金鎮的居民回報，最近他們的慶典經常被迫中斷。好像是因為…憤怒的鴨子在暴走？也許你可以去調查一下這件事。", progress = nil, completion = "好的！沒錯，我剛好有適合你的任務…", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79135] = {title = "極度呱噪", objective = "使用叭叭號角嚇跑10隻鴨子。", description = "那些可惡的鴨子！可以麻煩你再去嚇跑牠們嗎？因為我的金蛋得要顧著才行！", progress = nil, completion = "喔，謝天謝地。那些鴨子快把我逼瘋了！", rewards = "您會收到：\n\n明亮的彩蛋龍石"}
MultiLanguageQuestData['tw'][79136] = {title = "春神復甦", objective = "在剃刀嶺與希娜莉雅‧旅焰交談。", description = "剃刀嶺的居民回報，最近鴨子大舉入侵，導致他們的慶典經常被迫中斷。也許你可以去調查一下這件事。", progress = nil, completion = "好的！沒錯，我剛好有適合你的任務…", rewards = "您會收到：\n\n龍石"}
MultiLanguageQuestData['tw'][79137] = {title = "我們之間的高牆", objective = "到焚木村與莉莉安和卡莉雅談話。", description = "我知道這場戰事跟我們無關，<name>。但我仍謝謝你出手相助。當初是在聯盟的幫助下，羅德隆才順利得到淨化，現在這個人情終於還了。\n\n我不認為可以就此迎來和平。我只是希望，這些努力至少能讓眾人更加了解吉爾尼斯和被遺忘者所處的困境。\n\n我們去焚木村跟莉莉安會合吧。這場慶祝與我們無關。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79139] = {title = "獨處黑暗", objective = "調查安蘇芮克之眼。", description = "我的族人不認為這個黑血會對世界造成威脅。畢竟它長年都保持著休眠的狀態。怎麼可能現在突然改變？\n\n但世界變化的速度遠比我族人想像的還快。奈幽蟲族為了自身目的而決定抽取黑血就是變化的證明。\n\n離這裡不遠的地方有一座奈幽蟲族的瞭望塔。那些從坑洞裡活下來的蟲族不太可能離開太遠。我們應該馬上展開追擊。", progress = nil, completion = "&lt;那個怪異生物的眼睛始終鎖定在你身上，動也不動。牠把某個東西推向你，那是一個有著厚厚的紫色封蠟的卷軸。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79140] = {title = "薪水小偷", objective = "跟不守紀律的土靈受訓者比劃。", description = "這就是我們打敗薩拉塔斯的希望嗎？從無縛者過往背棄的事蹟來看，就知道他們是一群什麼貨色。而誓語者雖然是一群石頭做的傢伙，卻又相當軟弱。城市生活讓他們沒有任何長進。\n\n我們還有很多事要做。\n\n下去讓這些土靈嘗嘗真正威脅的滋味，但是盡量不要讓他們受到致命傷，否則這些倒地的傢伙會向其他人傳達強烈警訊。", progress = nil, completion = "你在下面點燃了火苗，而我們會繼續搧風助燃。\n\n你可以走了，請記得你幫助了這些土靈，讓他們走上榮耀的道路。奈幽蟲族絕對料想不到這個！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79145] = {title = "金屬與石頭", objective = "提供土靈受訓者裝備來應戰。", description = "雖然有些新兵不擅長遵守紀律，但大部分的人工作態度還是很好。他們只需要訓練跟裝備就可以好好發揮了。\n\n土靈武器鍛造師跟護甲商一直在不眠不休地工作，要為這支涉世未深的軍隊提供裝備。不過我們也需要人手幫忙，把這些新武器交到這些受訓者的手上。", progress = nil, completion = "現在他們看起來像真正的軍隊了。我們會繼續他們的訓練，但我相信你有更重要的事情要忙。", rewards = "阿爾加重斧阿爾加之錘阿爾加盾牌阿爾加匕首阿爾加香爐阿爾加戰刃阿爾加短斧您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79146] = {title = "震地者", objective = "與阿德貢、嘉亞拉和圖拉揚會面。", description = "禿鼻鴉與自己選定的飛騎需要花時間培養羈絆。\n\n或許你應該趁這段時間看看其他受訓者的情況。\n\n風暴飛騎是土靈的常備部隊，不過因為我們幫助土靈修復機械，許多無縛者與誓語者都表示願意與我們並肩作戰。\n\n阿德貢、嘉亞拉和圖拉揚正忙著訓練新人。去看看他們是否需要任何協助。", progress = nil, completion = "有誰能把我從這場爭執解救出來？聯盟與部落各執一詞…\n\n幾千年來我都沒有遇過這種事情，就算是在無縛者與誓語者之間也沒有。要是他們把擺架子的一半精力放在訓練上，我們的任務早就完成了。\n\n看看你可以怎麼幫我的人民吧。他們需要紮實的訓練才能應對奈幽蟲族的下一次侵襲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79147] = {title = "飛行訓練初級班", objective = "協助庫德蘭訓練新兵的空中移動。", description = "既然我們所有的新兵都在場，現在是飛常適合升空的時機。你有注意到我的笑話嗎？飛常適合？沒有嗎？\n\n好，我們要讓這些菜鳥慢慢來。先從在空中迅速移動的基礎開始，我們會盡量模擬我們在地底時會需要的精準飛行。\n\n在那之後，我們會提高難度，看看這些禿鼻鴉真正的能耐。我想索爾跟蘆瑟菈應該準備了特殊的訓練。", progress = nil, completion = "這樣就對了！石頭做的菜鳥，在閃電做成的鳥背上翱翔天際。這證明了任何人在老庫德蘭的訓練下都能學飛！\n\n但我們還沒結束呢。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79148] = {title = "尼貝爾加茲精煉廠", objective = "救援6個精煉廠工人並尋找穆德魯特。", description = "快點！元素生物佔據了尼貝爾加茲礦坑，精煉廠員工被它們被困在那裡。\n\n我尤其擔心我的伴侶穆德魯特。最近他的記憶有些混亂。如果你是朋友，就去救他和精煉廠工人。\n\n來，收下這個治療黏土。它只能幫上一點忙，但應該足以讓傷患自己走回來。真希望我們有一顆再生水晶，但那是傳說中的材料。", progress = nil, completion = "工人告訴我，你幫他們逃離了精煉廠。任務完成！\n\n我現在要收回那些黏土了。感謝。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79149] = {title = "精煉廠的騷亂", objective = "殺死10個狂暴元素。", description = "真是一場災難！喔，真糟糕，太糟糕了！那些該死的礦渣元素讓我的精煉廠工人沒辦法工作。\n\n我們身懷職責，必須繼續工作。這些延誤簡直不可容忍。你看起來很有能力。去吧，下去那裡，幫忙消滅元素生物。生產速度絕不能慢下來！", progress = nil, completion = "生產遭遇可怕的延誤。礦工恐怕必須加倍努力，才能彌補損失的時間。\n\n很高興你來到這裡。那些元素生物真是一大威脅，糟糕的威脅！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79150] = {title = "舞臺的戲劇演員", objective = "協助建築師布羅弗清理舞臺。", description = "當我提到要讓無縛者把他們的演出帶到多恩諾加時，我不知道會發生什麼事情。也不知道原來我的「幫助」會妨礙到他們。\n\n我的老朋友布羅弗一直不斷用他的完美主義干擾我們。我們嘗試要搭建背景，但他一直阻止所有人，只為了檢查每一根釘子。我們試圖上色，他一直抱怨顏色不搭…反正你懂的。\n\n我覺得布羅弗需要一個屬於他的任務。也許…像是打掃舞臺？去找他幫忙，讓他一直有事情做。", progress = nil, completion = "太棒了！現在我們可以盡情表演，不用再受制於他的完美主義了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79151] = {title = "孤兒的請求", objective = "在聖落之地從飢餓渦池取回艾莉莎備受寵愛的泰迪熊。", description = "哇，你看起來真強！你能夠幫幫我嗎？\n\n我的父母都被殘忍的寇拜斯殺死了。我來這裡的時候，沒機會把我最喜歡、最寶貝的泰迪熊帶來。\n\n你可以幫我拿來嗎？", progress = "我會讓膽敢侵入這片土地的寇拜斯感到後悔。", completion = "好啦，好啦。我想我也不介意你來幫忙。\n\n你確實看起來又大又壯。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79152] = {title = "大開殺戒", objective = "在聖落之地的飢餓渦池殺死10個寇拜斯。", description = "那個寇拜斯…比我想的還大隻一點，我可能…可能，你懂嗎？對付他們比我原先預期的還要麻煩。\n\n殺光你看到的任何蠢魚臉。", progress = nil, completion = "你殺了不少寇拜斯。\n\n我不介意你再多殺一點，說說而已。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79153] = {title = "勝者為王", objective = "在聖落之地的飢餓渦池殺死『吞噬者』銳鱗並取回牠的頭。", description = "啊，時候到了。\n\n殺死牠們的首領，醃製牠的骨頭，砍下牠的頭，笑著看牠的部族從此破滅！\n\n銳鱗已經死到臨頭了，牠卻還沒意識到這件事。\n\n真是一條蠢魚。", progress = "我在想，他的頭顱是要當成杯子來用呢？還是裝飾在披肩上呢？", completion = "喔，這顆頭比我想的還要髒一點。你可以自己留著。\n\n你比我原先預期的還要能幹很多，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79154] = {title = "最後的道別", objective = "在聖落之地的飢餓渦池協助艾莉莎道別。", description = "嗯，替父母報仇，殺了魚，殺了更多魚，殺了最大的魚。\n\n美好的一天。\n\n我想我應該去燒東西了。", progress = nil, completion = "謝了，&lt;name&gt;。我一定會替你在鐵擊將軍面前說些好話。我跟她很熟。\n\n好啦，其實我只見過她一面。\n\n好啦，其實我只是在街上看過她。\n\n不過我的確很想跟她說話，所以都一樣。", rewards = "您會收到：\n\n成人尺寸的阿拉希肩冑共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][79156] = {title = "律令", objective = "向梅里斯與阿德貢報告。", description = "梅里斯跟阿德貢會想要知道最新情況的。我在前來的路上，聽說他們都要前往舞臺正式參戰。你應該去找他們，跟他們彙報說風暴飛騎準備好了。\n\n我跟札雷因還需要一點時間。不過我們很快就會跟上。貝格姆的精神會與我們同在。", progress = nil, completion = "泰坦啊…他們做了什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79157] = {title = "泰坦故障機制", objective = "擊敗巨型泰坦傀儡。", description = "所以泰坦派了他們的遠古機械來對付他們不聽話的孩子。\n\n我們的創造者會希望我們犧牲一切來保護地心通途嗎？犧牲艾澤拉斯？我們注定踏上無人走過的道路，前往世界的死亡之心嗎？\n\n不，此刻的我們都是無縛者，而我們也會為自己的自由而戰。為了艾澤拉斯！", progress = nil, completion = "這是一場火的考驗，但你證明了多恩島的土靈已經準備好迎接即將到來的戰爭。我們曾經意見不合，但我們現在有一致的目標。不再區分成誓語者或無縛者，而是團結一致。我們也應該像他們一樣，一同對抗黑暗。", rewards = "您會收到：\n\n風暴飛騎腕輪風暴飛騎束腕風暴飛騎護腕風暴飛騎臂鎧共鳴水晶多恩諾加議會勇氣石"}
MultiLanguageQuestData['tw'][79158] = {title = "救贖的種子", objective = "取回豐收之種，並在可播種的土壤播下8顆種子。", description = "這些原本聽話的收割機器人突然失控，在我們的農地上到處搞破壞。\n\n要是不能順利播種，我們就會失敗，但我們絕大多數的種子卻都在那些收割機器人手中！\n\n你能夠到田裡去，消滅那些失控的機器人，收集種子並完成播種嗎？", progress = nil, completion = "你真的幫了個大忙！種下那些種子後，我們就有寶貴的時間能修理收割機器人了。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][79159] = {title = "怠忽職守", objective = "到聖落之地的米雷達爾尋找辛達‧庫里派克。", description = "可以耽誤一下你的時間嗎？\n\n我的其中一個副官辛達‧庫里派克沒到第一個篝火報到。在你看來，這可能不是什麼大問題，但阿拉希人之所以能在聖落之地生存下來，都要歸功於我們的令行禁止和互助合作。\n\n我不是殘酷的人，如果有人在面對惡劣的環境時展現出懦弱，我不會因此懲罰他。可以請你去找他，把他帶回來嗎？\n\n你可以慢慢來。", progress = nil, completion = "你說出我的心聲了，&lt;name&gt;。有計畫，我就能有架構，以及可以實現的目標。\n\n我來想想最好的放鬆方式。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79160] = {title = "釣魚有益身心健康", objective = "在釣魚洞與辛達見面。", description = "小時候，我都會跟著我母親去附近的池塘釣魚。我母親的廚藝糟到人盡皆知的地步，讓我印象最深刻的並不是魚…而是那段寧靜、親暱的時光。\n\n也許我能在這裡找回一小部分的安寧。米雷達爾的南邊有個過去相當熱門的釣點。我會在那裡跟你會合！", progress = nil, completion = "我希望我們能釣魚。但如果今天向我證明了什麼事的話，那就是我重新理解了一個珍貴的道理。\n\n若我現在就棄械放棄，那麼，這些孩子若要生存下去，就不得不拾起武器奮戰。這片土地就是他們僅有的了。\n\n他們會再見到家園的，也必然如此。", rewards = "拋光阿拉希步槍辛達的備用巨斧安德里的缺角靴中刀憂慮船長的鬥棍孩童的舊釣竿阿拉希斥候的步行杖您會收到：\n\n共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][79162] = {title = "燃盡", objective = "回去米雷達爾找安德里‧晨湧。", description = "請回去找指揮官晨湧，代我為缺席一事向他致歉。等我輪班結束後，我會為我自作主張的行為去負荊請罪。", progress = nil, completion = "我不會因為他沒有到場而降罪於他。我很慶幸你能在我無能為力的時候支持他。\n\n我們處在一個動盪不安的時代，&lt;name&gt;。我不願讓任何人經歷這樣的事。在這個時代，我們得想盡辦法存活下去。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79165] = {title = "休息時刻", objective = "在聖光壁壘附近找到法林。", description = "很好，你們兩個都到了。\n\n我想請你們幫個忙。\n\n法林走丟了。我想要你和你這個…不修邊幅的朋友幫忙尋找她的下落。\n\n她人應該在聖光壁壘。", progress = nil, completion = "&lt;安杜因咬住嘴唇，陷入沉思。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79166] = {title = "遺失物", objective = "從顫慄深淵的敵人身上收集8個遺失的個人財產。", description = "過去的某段時間，我會知道該說些什麼來安慰她。\n\n但是如今…就和所有事物一樣，一切都離我遠去了。\n\n<安杜因嘆了口氣。>\n\n一定有我們能做的事。她的老燈火者夥伴，這個安達里…身上應該會有引火盒，對吧？那似乎是對葬禮很重要的東西。\n\n我會陪法林回到米雷達爾，並在那裡跟你會合。如果你認為還有機會找到安達里的遺失物…可以請你試著找找看嗎？", progress = "沒時間哀悼了。眼前還有一場硬仗，現在不是時候。既然你有時間哀悼，就有時間訓練。\n\n確保我們不會輸給任何人。", completion = "你找到他們的東西了？在一片黑暗之中？\n\n謝謝你。\n\n還有，這是…", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79167] = {title = "東借西借", objective = "從米雷達爾的阿拉希人身上收集4個遊戲棋子。", description = "聖光險棋是一種古老又光榮的遊戲。它在阿拉希人之中如此盛行是有原因的！\n\n你可以從中學到很多戰略知識。它還可以教你如何分析你的對手。\n\n<法林突然變得低落。>\n\n不過我們還少了一些必要的棋子，根本沒辦法玩。\n\n有時候，米雷達爾附近的人會借棋子給我們玩遊戲。你可以到處問問嗎？", progress = nil, completion = "我們…好像有點操之過急了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79168] = {title = "聖光險棋", objective = "拿起城堡棋子，與法林和安杜因開始玩一場聖光險棋。", description = "沒關係！我們可以之後再跟你們講解剩下的規則！\n\n不管怎麼說，親自體驗才是最有趣的！\n\n你和安杜因可以一起挑戰我。你們兩個人合作，說不定有贏的機會！\n\n<法林大笑。>", progress = nil, completion = "希望你也覺得這很紓壓，&lt;name&gt;。我完全沒意識到我們有多需要休息一下。", rewards = "您會收到：\n\n聖光險棋冠軍紀念璽戒共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][79173] = {title = "出手相助", objective = "從周圍區域找回各種遭竊的物品，滿足我們的需求。", description = "當暗影籠罩我們的小鎮時，在黑暗的掩護下，各式各樣的珍貴物資紛紛不翼而飛。\n\n隨著光明回歸，終於可以開始重建了，但我們必須先取回失去的東西。\n\n搜索周圍區域，找回可能還派得上用場的物資。", progress = nil, completion = "你找回的物資多到超乎我們原先的預期。我已經分出一些多餘的物資，讓你帶走。", rewards = "您會收到：\n\n燈火者補給包共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][79174] = {title = "受感染的感染源", objective = "到沃許蟲巢殺死12隻被孢子感染的害蟲。", description = "自從法林的先遣營地建立以來，沃許蟲巢那些被孢子感染的害蟲一直是我們的心腹大患。牠們到處散播濃密的孢子雲。我從來沒看過那樣的東西！\n\n牠們已經進攻過一次了，很快就會再次發動攻擊。如果我們要在這裡立足，就必須削減牠們的數量。\n\n去沃許蟲巢，殺掉一些被孢子感染的害蟲！", progress = nil, completion = "受到孢子感染的害蟲越來越少，我們總算有時間思考永久的解決辦法。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79175] = {title = "我覺得我現在是雄蟲", objective = "讓阿努巴札爾用他的費洛蒙標記你。", description = "告訴你，我決定愛屋及烏。你有個小哥布林朋友。我知道你們有多喜歡彼此取暖。\n\n現在你們兩個都會為我做事。首先，我會給你們我的費洛蒙氣味印記。有了它，就代表你們成了我的所有物，我忠心的士兵就不會攻擊你們。", progress = "別浪費我的時間。你們準備好接受我的印記了嗎？跟你的哥布林朋友一起站到費洛蒙的範圍內，沾上它的氣味。", completion = "你的朋友很愛抱怨，不過我的印記會讓你們稍微安全一點，但對哲卡爾的守衛不管用。既然他們跟我敵對了，自然也不會在意什麼氣味印記。\n\n好好善用印記吧，小心安全。", rewards = "您會收到：\n\n將軍的刺鼻裹帶將軍的刺鼻腿甲將軍的刺鼻披肩將軍的刺鼻護甲"}
MultiLanguageQuestData['tw'][79176] = {title = "蛋白石與符文", objective = "用一瓶液態蛋白石跟蓓芙露西交換地下酒吧通行符。", description = "你確實為我災難的一天減輕了不少壓力，<name>。\n\n為此，整個熔爐地跟維持這裡運作的人都會感謝你。\n\n<佛葛蕾向你眨眨眼，露出意有所指的微笑。>\n\n蓓芙露西派你來幫我真是對的選擇。請跟她說不要客氣，我很歡迎更多來自深淵的朋友。\n\n這是她要的液態蛋白石。幫我交給她，順便轉達我對她的讚美。", progress = "城市裡的每一個人都有自己想要的東西，而總是會有一個人有辦法弄到手。", completion = "我派你去找機語者，想辦法把我們弄進地下酒吧，結果你還幫熔爐地的市場總管送貨跟交易？\n\n&lt;梅里斯一邊露出淡淡的笑容，一邊用他沉重的石頭手鼓掌。拍手聲比你想像的還要低沉許多。&gt;\n\n做得好，我足智多謀的外來者。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79178] = {title = "玩《爐石戰記》！", objective = "在爐石戰記對戰桌玩5場爐石戰記卡牌遊戲，或是在對戰桌的附近進行開放卡牌。", description = "來玩爐石戰記吧！\n\n這裡有個新手包，把它打開，將裡面的卡牌加入你的收藏。然後，如果找到有空位的對戰桌，就能坐下來跟其他人玩牌！\n\n假如你找不到空位，那麼你就會需要用到開放卡牌…別跟人家說是我講的，但其實這附近藏了一個可疑的發牌員。", progress = nil, completion = "最近如何啊？來點高級又純粹的娛樂吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79184] = {title = "《爐石戰記》週年慶來了！", objective = "到沃卓肯的守護巨龍之座與主持人法菈拉談話。", description = "「你敢相信嗎？《爐石戰記》已經推出十年了！\n\n我在沃卓肯舉辦了《爐石戰記》比賽，地點就在守護巨龍之座。一起來玩吧！\n\n-主持人法菈拉」", progress = nil, completion = "歡迎來到慶典！趕快出去加入玩樂的行列！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79186] = {title = "《爐石戰記》週年慶來了！", objective = "到暴風城與主持人法菈拉談話。", description = "你敢相信嗎？《爐石戰記》已經推出十年了！\n\n大會主持人法菈拉正在暴風港舉辦《爐石戰記》比賽。一起來慶祝吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79189] = {title = "《爐石戰記》週年慶來了！", objective = "到杜洛塔與主持人法菈拉談話。你敢相信嗎？《爐石戰記》已經推出十年了！\n\n大會主持人法菈拉正在杜洛塔舉辦《爐石戰記》比賽，地點就在奧格瑪和碼頭之間。一起來慶祝吧！您會收到：\n\n完成任務後，你將獲得：\n\n", description = "你敢相信嗎？《爐石戰記》已經推出十年了！\n\n大會主持人法菈拉正在杜洛塔舉辦《爐石戰記》比賽，地點就在奧格瑪和碼頭之間。一起來慶祝吧！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79193] = {title = "旋轉孢子脊刺", objective = "為穆德魯特收集150根孢子脊刺。", description = "歐仙絲派你來的？而且我們應該要是伴侶？為什麼…我戴著勳章。但我沒有任何記憶…好吧，現在不是說這個的時候。\n\n在你來的路上，有沒有看到那些旋轉的孢子？我需要跟它們相連的脊刺…用來…用來做什麼？喔，對了！身為寶石雕刻師，需要在作品上刻出超精細的細節，沒有比那些脊刺更稱手的工具。你能去收集幾根嗎？\n\n我會自己回到精煉廠。我迫不及待想回去，見見這個歐仙絲。", progress = "喂，現在是怎麼回事？你對這些深淵很不熟，不是嗎？你怎麼會出現在這裡？\n\n<你提醒他剛剛說過的話。>\n\n那你還在等什麼？快去幫我收集脊刺！", completion = "你從哪裡來的？你是誰？\n\n我不知道你如何得知我需要這些脊刺，但我很感謝你。身為寶石雕刻師，需要在作品上刻出超精細的細節，沒有比這些脊刺更稱手的工具。你看，我是寶石雕刻師！\n\n你見過我的新朋友歐仙絲了嗎？我…我之前說了什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79194] = {title = "追本溯源", objective = "到東北礦坑外面找克妲茨。", description = "歐仙絲告訴我，你一直很擅長解決礦坑這裡的元素問題。我是克妲茨，民兵的負責人。我們在剛達加茲接獲遭受攻擊的消息，就立刻趕來。你救出的礦工說，元素生物從東北方的礦井傾巢而出。\n\n我會留幾個守衛在這裡，以便提供支援和前去求援。要是你還願意出手相助，就到洞穴外面找我，我們來看看如何阻止那些源源不絕的元素生物。", progress = nil, completion = "啊，&lt;name&gt;，你成功了。我們也是，不過在來的路上時常遭到攻擊。不幸的是，南薩茲身受重傷，需要一點時間才能復原。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79196] = {title = "斷裂絲線名人", objective = "在織絲者巢穴與維娜茲安女士談話。", description = "織絲者一直在注意著你。她認為你要有更多資源可以運用，才會是更好的資產。\n\n前往織絲者巢穴，我有個包裹在等著你。", progress = nil, completion = "為了答謝你已經提供和未來要提供的服務，請接受這項織絲者的贈禮。", rewards = "您會收到：\n\n滿溢斷裂絲線寶藏"}
MultiLanguageQuestData['tw'][79197] = {title = "表面束縛", objective = "在多恩島的多恩諾加與茉艾拉‧索瑞森和你的盟友會合。", description = "<name>，這一刻已然來臨。我們必須盡快趕往多恩諾加，我們的盟友正在那裡等著。\n\n只有齊心協力，我們才有機會對抗先驅者的陰謀詭計。", progress = nil, completion = "看到你們都安全地從旅途中回來讓我真高興。", rewards = "您會學到：\n\n世界任務與冒險模式\n\n您還會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79200] = {title = "我是誰？", objective = "完成甦醒協定的第一階段。", description = "看到你醒來了真好。我知道你一定有很多問題要問，而我們就是來回答那些問題的。我是黎明，這是工頭烏茲傑克斯。\n\n在你上次沉睡後，有很多事情發生改變了，包括我們的甦醒協定。我們都是來指引你的。\n\n就像剛甦醒的其他人一樣，你聽見了一首遙遠而有力的曲子在你心中迴盪。一道改變的輻光正在湧動。\n\n擁抱它。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n艾澤萊晶岩激盪\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79201] = {title = "分析介面", objective = "在分析介面完成分析程序。", description = "這是分析介面。\n\n為了確保我們的主程式完好無缺，這些控制臺設置了一連串的問題，以評估剛覺醒的土靈的記憶矩陣。\n\n雖然黎明鼓勵你依個人的想法回答，但…這麼說吧，我希望你誠實回答。\n\n準備好了就開始吧。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79202] = {title = "以石擊石", objective = "與6個剛甦醒的土靈比劃。", description = "歡迎來到程序論壇。\n\n工頭烏茲傑克斯告訴我，這個房間曾經是我們的職務測試設備。\n\n在他的引導下，我們重新規劃了這個房間的新功能。\n\n土靈的設計本來就不是戰鬥取向，所以這個房間會用來讓剛甦醒的土靈做好準備，迎接眼前這個未知的世界所帶來的挑戰。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79203] = {title = "授權：無效", objective = "擊敗授權壁壘的授權方陣。", description = "授權壁壘！這個房間曾擁有這個名字。\n\n我不眠不休地工作，試圖把這裡重設為原本的樣子，但這該死的大廳突然就開始劇烈搖晃起來。\n\n一具魔像不知道從哪裡冒出來，還開始攻擊我的機械師！我們成功逃走，但魔像把房間封鎖了。\n\n黎明覺得你有辦法對付它。你接受挑戰嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79204] = {title = "做自己", objective = "與黎明談話，完成你的甦醒協定。", description = "經歷像那樣的甦醒協定後，我終於知道為什麼黎明會說你很特別了。\n\n這個世界沒料到會有像你這樣的土靈。\n\n<庫達斯露出凝重的笑容，拍拍你的背。>\n\n黎明和工頭正在覺醒門廊等你。\n\n那麼，去吧！\n\n完成你的甦醒協定，然後離開這裡！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n覺醒外袍"}
MultiLanguageQuestData['tw'][79205] = {title = "勤儉節約", objective = "在狗頭窟各處收集可能有用的廢料。", description = "萬物都有其用途，朋友。甚至是岩石頭覺得毫無價值而扔掉的東西。\n\n狗頭人更清楚這點。\n\n去看看你能找到什麼。需要回收很多的廢料。多到足以讓狗頭人打造出全新的家園！", progress = "你一定會嚇到。狗頭人的工藝很厲害！", completion = "對一個&lt;race&gt;來說還滿不賴的。我們可以善用這些東西。\n\n應該說，大部分東西。有時候，對一個人來說是垃圾的東西，其實真的就只是垃圾。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79206] = {title = "破碎回憶", objective = "將褪色的記憶寶石帶去給布琳瑟。\n\n已提供物品：\n", description = "感覺這一顆寶石似乎很重要。或許值得把它帶去給代言者布琳瑟看看。", progress = nil, completion = "土靈會因為時間不停流逝而失去記憶，而我們會將其記錄在這些寶石中。\n\n當土靈陷入停滯時，我們偶爾可以用記憶寶石來見證他們過的最後一刻。\n\n在我們的生命中，我們會用寶石把珍貴的記憶送到文庫裡，將它們好好地儲放起來。然後我們會在甦醒機械裡面為我們的身體充能並重置我們的心靈。\n\n&lt;name&gt;，謝謝你把這顆寶石帶回來。即使它已經碎裂且褪色，但它還是非常珍貴。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79213] = {title = "時代錯誤", objective = "啟動挖掘出的控制臺，並使用裝置來擊敗戈葛林之境的馬尾藻守護者。", description = "把電池放入控制臺上圓柱形的洞裡。\n\n接著，願泰坦保佑，我們能窺見裡面到底有什麼。", progress = "要取得所需的能量，就得找到適當大小的元素來為神器充能。\n\n如果我想的沒錯，泰坦神器會搞定剩下的一切。", completion = "有意思。它散發出的信號我在哪裡看過。\n\n我好像知道它會帶我們去哪裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79216] = {title = "操縱之網", objective = "探索附近的岩架，排除其中的任何威脅。", description = "這座小鎮一直遭到蜘蛛圍攻肆虐！就算除掉一批，又來一批，簡直沒完沒了。\n\n這背後一定有鬼！\n\n這些蜘蛛都來自光之綻放東北方的小岩架上。到岩架那邊偵察。找到驅使這些蜘蛛攻擊我們的原因，然後除之而後快！", progress = nil, completion = "做得非常好，&lt;name&gt;。現在我們來看看這樣能不能終結八腳怪物的入侵！", rewards = "您會收到：\n\n燈火者補給包共鳴水晶聖落之地阿拉希青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][79217] = {title = "返回基地", objective = "到剛達加茲與布琳瑟會面。", description = "要讓這個工廠重新開始運作是一大挑戰，但我覺得我們一定能想出辦法。我們回去剛達加茲，諮詢一下我們的朋友吧。\n\n他的頭腦一定會成為我們的一大助力。", progress = nil, completion = "你準備好和我們一起集思廣益，想出一個計畫了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79218] = {title = "聖落之地阿拉希名人", objective = "在米雷達爾與奧拉麗亞‧鐵擊交談。", description = "你為我的族人付出的努力並非無人知曉，你也將為此受到獎勵。\n\n到米雷達爾來找我。", progress = nil, completion = "物資稀缺，但這些物資在你手中會讓所有阿爾加人獲利。願聖焰點燃你的道路。", rewards = "您會收到：\n\n滿溢聖落之地寶藏"}
MultiLanguageQuestData['tw'][79219] = {title = "多恩諾加議會名人", objective = "在多恩諾加與審計員巴烏茲交談。", description = "議會欠你一次人情，朋友。\n\n如果你到多恩諾加來拜訪我，我會給你補給品作為答謝的。", progress = nil, completion = "這些獎勵給你。謝謝你，勇士。這些應該足以作為你努力的報酬。", rewards = "您會收到：\n\n滿溢多恩諾加議會寶藏"}
MultiLanguageQuestData['tw'][79220] = {title = "深淵集會名人", objective = "在剛達加茲與蠟販史奇克交談。", description = "好的功勞值得好的獎勵，對吧？\n\n集會非常感激。蠟販史奇克很感激。用許多物資來表現謝意。\n\n到剛達加茲來見蠟販史奇克。", progress = nil, completion = "給你！拿去！", rewards = "您會收到：\n\n滿溢深淵寶藏"}
MultiLanguageQuestData['tw'][79221] = {title = "不尋常的蟲子", objective = "將這隻不尋常的蟲子交給拉克-亞緒的寡婦阿拉克娜依。\n\n已提供物品：\n", description = "拉克-亞緒的奈幽蟲族或許會對這隻奇怪的小蜘蛛感興趣。", progress = nil, completion = "喔，我還在想那些東西去了哪裡呢，謝謝你幫我帶回來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79222] = {title = "暗影硬化主發條", objective = "將這個物品交給剛達加茲的庫達斯。\n\n已提供物品：\n", description = "<也許這是漫長黑暗帶來的影響，或是經過埃茲吉‧鐵輪的擺弄，不過剛達加茲的代言者庫達斯應該會對這個彈簧的力量感興趣。>", progress = nil, completion = "真是驚人的發現，這東西需要仔細檢查一番！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79223] = {title = "終於成為文物管理員了！", objective = "向補給官亞歷絲塔購買文物管理員扣帽。", description = "你現在適應一點了嗎？有沒有體驗到塵土的觸感？有沒有聞到歷史的味道？\n\n為了慶祝這個差強人意的光榮時刻，來一頂…軟帽吧！\n\n你沒聽錯！帶著這個信物去找我們親愛的補給官亞歷絲塔。她會很樂意給你一頂萬能軟帽，象徵你正式從天真的路人晉升為文物管理員。", progress = nil, completion = "撇開對你目前能力的各種評價，至少你現在看起來還算有模有樣！\n\n好了，我同事又需要你發揮才華了。最好別耽誤了！", rewards = "這個任務線能解鎖：\n\n艾澤拉斯文庫：河床、和睦觀測所和失落圖書室挖掘場\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79224] = {title = "收集情報", objective = "在阿茲-卡罕特的織絲者巢穴與寡婦阿拉克娜依談話。", description = "寡婦阿拉克娜依派了她的其中一隻「小織蛛」來傳話。她手中有條線索，或許跟我們的目的有關，還邀請我們去調查一番。如果不夠了解我們的敵人，這世上的所有訓練都會無用武之地。\n\n你應該還記得，我在阿茲-卡罕特的偵察行動的結果…有好有壞。我得承認，短時間內我並不想再下去那裡。幸運的是，這次抵達的援兵中有一位能力出眾的間諜大師。\n\n不幸的是，她有點…嗯，你看了就知道。", progress = nil, completion = "就像我和你那個粗魯的小小間諜大師說的，我相信這會讓雙方都從中受益。\n\n我們都能帶著需要的情報全身而退。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79225] = {title = "遺失之焰", objective = "將遠征隊引火盒交給影叢葡萄園的琪菈‧弗蘭斯壯。\n\n已提供物品：\n", description = "<聖落之地遠征隊成員的引火盒，歸還它們有助於悼念那些英勇犧牲的人。>\n\n遠征隊斥候或許對這個物品略知一二。>", progress = nil, completion = "在暗影日，奧斯丁陷入恐慌，逃離人群。\n\n謠傳，他離開了聖落之地，找到返回地表的方法。我知道他失敗了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79226] = {title = "重大挖掘：背叛者之眠", objective = "到背叛者之眠的重大挖掘場地協助愛德威‧達凜格和艾澤拉斯文物管理員。", description = "戴上你的軟帽、套上牢固的手套，再帶上一點零食，因為背叛者之眠已經準備好迎接來自世界各地、對歷史充滿狂熱的文物管理員了！", progress = "不是每天都能出土遠古巨龍的神秘文物…或甚至是巨龍本身！", completion = "&lt;愛德威掏遍了長袍上的所有口袋。&gt;\n\n拿去，文物管理員&lt;name&gt;！帶著這東西去找補給官亞歷絲塔，領取你的福利。\n\n也許你該換一套新衣服，你現在這套實在…髒到不行。", rewards = "您會收到：\n\n巨龍群島補給品神秘碎片艾澤拉斯文庫"}
MultiLanguageQuestData['tw'][79227] = {title = "蛛眼的觀點", objective = "放置投影儀，來和斥侯在晦影市集、東部闊地和抽搐峽谷與織絲者會面。", description = "我的耳目遍布在這座城市的每一個角落，除了…一個地方。\n\n轉化場是安蘇芮克最早熟手下和最珍貴的寵物的地盤，也是晉升儀式進行的地方。多虧了親愛的伊特希，我最近才有機會染指它，但絕大部分的區域對我來說仍是個謎。\n\n看來只能用更腳踏實地的方式了。放置投影儀來向我的斥候收集情報，然後到那個區域裡某個隱密的角落，跟伊特希和你那個間諜大師佛斯會合。", progress = nil, completion = "那些報告的內容令人不安。看來他們的陰謀詭計已經到了收網階段，就等著我們一腳踏入。\n\n別擔心。要是我們陷入危機，我會讓你知道。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79230] = {title = "明察暗訪", objective = "調查西側儲藏區、中央的倉庫和轉化場的皇家倉庫，並使用憤怒費洛蒙讓守衛分心，避免被發現。", description = "我找出了三個調查點。\n\n建築群東側的倉庫、中央區域的倉庫，還有那座立了皇家蘇芮基旗幟的超大倉庫。我們到那裡碰頭吧。\n\n如果在那裡分頭行動的話，應該不會有什麼大發現。多數奈幽蟲族應該不會發現到你，但晉升者會聞到你的味道。如果遇到狀況的話，就對他們丟這些憤怒費洛蒙吧。這能分散他們的注意力。\n\n保持警覺，低調行事。", progress = nil, completion = "我們來這裡是想弄清楚這些奈幽蟲族的目的。而我不認為我會喜歡查到的結果。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79231] = {title = "再一次返回總部！", objective = "到薩爪祖斯的阿爾蓋薩學院與愛德威‧達凜格會面。", description = "你的表現實在讓人嘆為觀止！無庸置疑，你絕對能成為一位優秀的艾澤拉斯文物管理員。\n\n回到我們在薩爪祖斯的總部跟我們會合。愛德威會把你對團隊的貢獻和功勞全部記錄下來。", progress = nil, completion = "做得好，&lt;name&gt;！做得太好了！\n\n找你加入果然是正確的。你有真正的文物管理員之魂！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79232] = {title = "英勇就義者", objective = "找到奧斯卡爾‧谷鬥、達利安‧鐵鍊和伊多納‧預石的遺體，並取回他們的引火盒。", description = "自從暗影日以來，這裡一直是個危險的地方。\n\n寇拜斯步步進逼，奈幽蟲族到處刺探，純暗影生物也開始化為實體。\n\n我們的日常生活充斥著那些不幸身亡的人的身影。我們必須找到他們的遺體，才能有個了結。\n\n搜尋這些失蹤的遠征隊成員的引火盒，把它們交給我。", progress = "找到引火盒了嗎？", completion = "這些引火盒雖然渺小，卻象徵著我們在暗影日蒙受的巨大損失。我們會修復你找到的那些遺體，重溫所愛之人的回憶。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79233] = {title = "進入實驗室", objective = "從轉化場的忠誠派奈幽蟲族身上收集6份忠誠者分泌物。", description = "雖然我非常推崇暗中行動，但是最有可能得到重大情報的地方必定是無上接合者實驗室。\n\n當然，你需要合適的費洛蒙才能進入那裡，不過我們只要耍點生物上的小花招，就能解決這個問題。\n\n這裡的忠誠派奈幽蟲族一定在邀請名單上，只要六份他們的分泌物，應該就足夠我們三個進行偽裝。", progress = "你看得到我？不，你沒看到。", completion = "好極了！我已經等很久了，終於可以處理真正的陰謀了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79234] = {title = "一小包種子", objective = "將這一小包種子交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<這一小包種子似乎被遺落了，它們或許對阿里雅‧西爾海姆有用>", progress = nil, completion = "哇，謝謝你！", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][79237] = {title = "製造怪物", objective = "從屋頂通道進入無上接合者實驗室，接著再調查第一晉升者目的的相關線索。", description = "我們有了新的目標，那就是查清楚安蘇芮克到底打算用這個…東西做什麼。\n\n我們將會在無上接合者實驗室找到答案。我用我的匕首打賭。\n\n我發現屋頂上有個維修通道，你可以利用這點。伊特希做了某種詭異的混合物，宣稱它可以讓我們自由行動。噁。\n\n我們裡面見。", progress = nil, completion = "這…未免太出乎我的意料之外了。\n\n&lt;莉莉安清清她的喉嚨。&gt;\n\n撇開自家人的內鬥，不管老女王過去是什麼樣子，她無可避免地會現身在戰場上，而且一定會為我們帶來大麻煩。", rewards = "您會收到：\n\n駕崩女王指環勇氣石"}
MultiLanguageQuestData['tw'][79239] = {title = "女王的鎖鍊", objective = "破壞奈菲瑞斯的鐐銬。", description = "安蘇芮克…該死的蟲子，失智又沒膽的小…\n\n<伊特希低聲咒罵，試圖保持鎮定。>\n\n奈菲瑞斯居然變成這副淒慘的模樣，我們一定得放了她。她還是我們的女王。我的仕女知道該怎麼做。\n\n一旦織絲者發現他們所做的一切，就算躲到裂縫深處，也別想逃過她的怒火。", progress = nil, completion = "還記得我說過，要是情況脫離掌控，我會告訴你嗎？現在就是這樣。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79240] = {title = "盜賊特務", objective = "制服伊特希。", description = "我們失去了伊特希。\n\n我們可以之後再來煩惱這件事。現在該擔心的是如何打倒他，不讓情況變得更糟。\n\n<莉莉安哼了一聲。>\n\n我記得我們下來這裡，是為了查清楚薩拉塔斯到底有什麼陰謀。我們最好別節外生枝。", progress = "很難想像情況還能如何變得更糟。", completion = "我們暫時脫離群眾的視線了。\n\n我的首要之務是把伊特希送回織絲者那裡。你去處理那些武器。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79241] = {title = "驚天動地", objective = "在運輸隊的特定位置設置6個搶來的奈幽炸藥，並在遠處引爆它們。", description = "想要低調行動實在太難了。既然我們都暴露了，現在可以大鬧一場了。\n\n我們知道他們從南邊的橋運了很多武器出去。要是我們用那些武器來對付他們，他們就必須想辦法為大軍重新補給。這樣一來，我們至少能爭取到時間。\n\n我在車隊中找到了六個弱點。在那六個點上裝設炸藥，然後找個地方躲好，準備欣賞煙火秀吧。", progress = nil, completion = "不只讓車隊變得一團亂，而且我們還能趁亂溜走。如果要說你的優點的話，就是很擅長製造噪音。\n\n保持低調？我只能說我們盡力而為。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79243] = {title = "製造暴動", objective = "殺死攻城元帥塔克佐和皇家軍需官澤里克。", description = "我們嚴重缺乏火力，根本對付不了準備萬全的他們，不過我們手裡還剩下兩瓶憤怒費洛蒙，我們就讓它們派上用場吧。\n\n有個攻城元帥和軍需官正在監督準備工作，負責發號施令。雖然是後勤人員，不過還是有點份量。這就是費洛蒙可以登場的地方。\n\n各砸他們兩個一瓶，讓他們被自己的手下圍攻。解決這兩個傢伙後，就能看著他們的行動自行崩潰。", progress = nil, completion = "這只能拖延一點時間，並不足以阻止整個行動，但還是很有幫助，能讓上面的人有更多準備時間。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79244] = {title = "來自地底的消息", objective = "通知寡婦阿拉克娜依在轉化場找到了什麼東西，然後返回多恩島的多恩諾加找艾蘭里亞。", description = "我從這裡就能聽到爆炸聲。這能為我們爭取到一點時間。要不是情勢已經糟到不行，我或許還能就此鬆一口氣。\n\n伊特希已經被安全送到後方，不用擔心隔牆有耳。不管薩拉塔斯做了什麼…一定還殘留了蛛絲馬跡。織絲者已經派人進行調查，但前景並不樂觀。\n\n艾蘭里亞想聽聽這次的行動報告。祝你好運。", progress = nil, completion = "到最後，我們至少拖慢了他們的腳步，還拿到一些有價值的好情報，讓上面這裡的大家能夠研究。\n\n這樣值得嗎？那要等時間告訴我們答案了。", rewards = "您會收到：\n\n織絲者裹手織絲者束帶織絲者肩衛織絲者披肩共鳴水晶織絲者(惡名值)勇氣石"}
MultiLanguageQuestData['tw'][79246] = {title = "船長的命令：搜刮錢財", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79249] = {title = "船長的命令：殺無赦", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79256] = {title = "破懼錘的線索", objective = "到穆羅契營地外面找茉艾拉‧索瑞森。", description = "當我父親和達格蘭去南邊處理斯卡汀的時候，他好像感應到他的舊戰錘「破懼錘」。\n\n他說，達拉然墜毀時，他不小心弄丟了破懼錘，他一直很在意這件事。那把戰錘是由銅鬚氏族代代相傳。他最近一直魂不守舍。\n\n我想去看一下，確保他不會一直擔心自己錯過拿回它的機會。到下面的穆羅契營地跟我會合，我們迅速在附近找一下。", progress = nil, completion = "嗯…\n\n我先前沒想到真的會在這裡發現破懼錘。\n\n它真的在這裡，但絕非垂手可得。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79257] = {title = "埋冤岩洞", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79258] = {title = "礦泉水之悲", objective = "從活力石窟的泉水取得溫度恰當的礦泉水。", description = "當那把魔法錘落入深淵時，我就知道它會是對付斯卡汀威脅的強大武器。你的朋友告訴我，它對持有者很「挑剔」。\n\n幸好，我是名英雄！\n\n身為英雄，我知道如何接近它。我們需要混合花粉和水再抹到身上。這樣一來，站在它上面的野獸就會覺得我們和它一樣。\n\n礦泉水的溫度必須剛剛好，才能跟鞭菇粉塵混合並溶在一起。", progress = nil, completion = "過程還真麻煩，但我們總算拿到貝魯德要的水了。\n\n我們該上路了，我不希望我父親的重錘在爛泥中載浮載沉，我完全不能接受這種事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79259] = {title = "完美偽裝", objective = "從活力石窟的鞭菇身上收集鞭菇粉塵。", description = "貝魯德說，站在破懼錘上方的巨大野獸不會隨隨便便讓任何生物近身。\n\n他說，如果我們順利混進去，就能靠得夠近，趁機搶奪戰錘。但是想要混進去，他說我們必須裹在岩洞的粉塵和花粉之中。\n\n那些鞭菇似乎是很好的切入點。\n\n在我看來，這一切都充滿疑點，我們先暫時照他的話做，直到我找回破懼錘，並把它還給我的父親為止。", progress = "你收集到粉塵了嗎？這是靠近重錘的唯一方法，尤其是那頭野獸還在附近晃來晃去。", completion = "&lt;『爍光者』貝魯德身上似乎一粒花粉都沒有。&gt;\n\n你做得很好，把全身都用鞭菇粉塵覆蓋了。\n\n我有點意外你沒有像你朋友一樣癢到狂打噴嚏。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79260] = {title = "地源震", objective = "接近碧綠巨怪。", description = "有一頭野獸擋在我們和魔法錘之間。牠掉進鳴響深淵時衝擊力一定不小，對吧？你看看那個撞擊坑的大小！\n\n既然你身上沾滿花粉跟水，你應該可以靠近那頭野獸，理論上，你是不會受到傷害的。你一定可以完美融入的！\n\n不過，萬一牠真的產生敵意的話，別擔心，我就在你後面。\n\n我們會安全地把重錘拿出來的！", progress = nil, completion = "噢，那個吃琥珀又沒骨氣的可笑土靈！連我見過的穴居怪都比他有誠信！\n\n他把破懼錘拿走了！他把我的家族錘拿走，然後把我們留給這頭野獸等死！\n\n這令人無法接受，我不會讓人這樣虧待你……或我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79261] = {title = "沸騰的瘋狂", objective = "在鳴響深淵追查貝魯德和破懼錘的蹤跡。", description = "那個忘恩負義的岩石頭！他拿走破懼錘，朝北邊跑了！\n\n我想要那把戰錘，不是為了自己，完全不是。但它屬於銅鬚氏族。它的持有者應該懂得尊重其力量！\n\n我們必須追上他，別讓他用那把戰錘傷到自己，或傷到別人！", progress = nil, completion = "這些土靈過得很糟糕。\n\n貝魯德已經一頭熱地衝進去了，可是他要是以為自己可以清理這地方的髒東西，他的石腦袋肯定是想太多了。\n\n&lt;茉艾拉指向附近的石頭挫痕&gt;\n\n你看，他根本控制不了破懼錘！萬一他把它摔到地上，害死自己怎麼辦？我們得找到他才行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79262] = {title = "清理家園", objective = "在轟隆荒地殺死激動的生物。", description = "看來地心通途的崩壞不光是讓幾顆石頭掉下來那麼簡單。它還喚醒了各式各樣的黑暗事物。\n\n過去採礦的榮景，現在已不復存在。\n\n我們必須幫助土靈再次控制這個地方，這也意味著消滅這些野獸。", progress = nil, completion = "這樣好多了。至少現在沒有一大堆生物在這個地方到處亂竄。\n\n不過我們還有其他的問題。\n\n那就是斯卡汀。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79263] = {title = "鴻溝", objective = "在轟隆荒地中尋找『爍光者』貝魯德。", description = "貝魯德把破懼錘佔為己有。我想他以為他可以拯救這些人。當個英雄。\n\n但是，就算有正當理由，也不代表可以肆無忌憚地做壞事。這是我的經驗談。如果一塊石頭一開始就是空心的，不管再怎麼努力嘗試，它永遠不可能再次變成實心。\n\n他現在可能需要拯救自己了。他應該就在這個鬼地方，我們去找他吧。", progress = nil, completion = "&lt;『爍光者』貝魯德的皮膚充滿裂痕與傷口。他的雙眼幾乎無法對焦。他幾乎要沒命了。&gt;\n\n每次……我想用重錘的時候……它都會遠離我。我本來可以救人的。我不能……我不能……", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79264] = {title = "這雙強壯的手", objective = "見證茉艾拉‧索瑞森。", description = "<『爍光者』貝魯德不斷咳出灰塵。>\n\n我知道光憑自己沒辦法對付斯卡汀。我以為要是有了那把魔法錘，我就會所向無敵。你知道的，我必須拿到它，也可能其實我天生就不是這塊料。\n\n但它一直從我的手中滑落。就像是它完全不想跟我扯上關係。它在最糟糕的時間點從我手中掉下去，現在…<貝魯德再次咳嗽。>\n\n它顯然不屬於我。永遠不屬於我。我…很…抱歉。", progress = nil, completion = "我以為這一天永遠不會到來，因為我爸絕對不會把破懼錘給我。他預期的情況大概不是這樣。\n\n但它現在在我手上了，而我一定會把它安全地還給他。\n\n不過在那之前，我們在這裡還有事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79265] = {title = "破懼錘", objective = "與茉艾拉‧索瑞森到轟隆荒地殺死斯卡汀，並拯救土靈。", description = "斯卡汀接手在轟隆荒地這裡的行動。那也是貝魯德認為他需要破懼錘的原因。\n\n在我把戰錘帶回去給麥格尼之前，我們必須把這件事做個了結。\n\n如果我不願意為了造福他人而讓自己涉險，又怎麼當個好女王呢？我們進去裡面，盡可能救人吧。", progress = nil, completion = "我們繞了點路，但我們還是讓這些土靈的人生有所不同了。\n\n希望貝魯德已經學到英雄氣概的真諦。但我猜我們總有一天會知道。\n\n現在，我們來了結這件事吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79266] = {title = "銅鬚傳承", objective = "到剛達加茲找茉艾拉‧索瑞森。", description = "很好，我們這一趟的收獲……比我預期的還多。我們找到了破懼錘，用它做了好事。\n\n現在該把它帶回去給麥格尼了。\n\n希望貝魯德這次已經學到一點教訓，但我猜他很快就會再次惹上麻煩。希望下次他會有正當的理由，也有適合的人支援他。", progress = nil, completion = "真有趣，我可以看得出來為什麼我爸會這麼喜歡這把重錘，還有他讓其他人拿它的時候，代表他有多信任他們。\n\n某種程度上，破懼錘有自己的想法。它有自己的喜好。\n\n我好像可以理解。", rewards = "您會收到：\n\n破懼者的回音共鳴水晶共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][79267] = {title = "蠟到鍋除", objective = "對狗頭窟裡的蠟搞破壞。", description = "如果蠟燭對狗頭人社會這麼重要，那我有個主意，或許可以中斷蠟燭生產…或是至少可以確保有個令人不悅的驚喜在等著我們的敵人。\n\n拿著燼釀蜜酒。倒一些進去狗頭人在那座山頂準備的大蠟桶裡。那是一種強力爆裂物，能劇烈燃燒，所以盡量不要灑出來。\n\n它肯定能讓任何用這種蠟製成的蠟燭在點燃後變得非常容易爆炸。", progress = nil, completion = "希望這樣能挫挫他們的銳氣。\n\n一個首領的權勢總會起起落落。經歷這次打擊後，蠟燭大王正在逐漸失勢。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79268] = {title = "剛德拉克快速賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79272] = {title = "凜懼島攀升賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79282] = {title = "偉大的出道作", objective = "在舞臺完成一個劇團事件。", description = "舞臺看起來太棒了！你準備好要上台了嗎？\n\n幫幫我們，擔任一下工作人員，我們就會給你演出的機會。\n\n你願意接受這個指令嗎？", progress = "我還沒看到你上臺，<name>。你光站在這裡是吸引不了粉絲的！", completion = "真是場精彩的表演！我覺得你在舞臺上的工作讓這裡成為了一個非常棒的表演場地。\n\n有空再回來吧。我們永遠需要更多演員跟工作人員！", rewards = "您會收到：\n\n共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][79295] = {title = "沖掉它們 - 啟動", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79297] = {title = "守夜者", objective = "收集8張黑夜教團宣傳單。", description = "薩拉塔斯在使用黑夜教團來為她效命。\n\n我無意間聽到一些阿拉希人在抱怨米雷達爾四周出現一波新的政治宣傳。盡你所能去調查，然後把情報帶去給鐵擊將軍。我會盡快趕過去。\n\n我們需要說服她這個威脅的嚴重性。", progress = "有我幫得上忙的嗎，<name>？", completion = "&lt;鐵擊將軍閱讀你帶給她的宣傳單。&gt;\n\n我需要進一步了解這個薩拉塔斯。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79300] = {title = "筆記本", objective = "協助蘇菲塔尋找她的筆記本。", description = "$p，我需要你的幫忙。我的未來正處於岌岌可危的境地！我來聖光火花是為了成為飛船船長，我也花了一大堆心力要取得好成績，可是我的筆記本不見了，裡面有我的期末報告！\n\n我是班上第一名，可是要是我不趕快交報告，我就無法成為下一任的飛船船長。請你幫我找到它。\n\n我以為我們去峽谷評鑑彼此的小艇飛行時，我把它留在那裡了，可是我去找的時候沒找到。你可以幫我找找看嗎？", progress = nil, completion = "艾德溫拿走了？當然是他啦。\n\n他非常想要選上船長，可是他知道我的排名比較前面。我沒辦法交報告就是他唯一的機會。我們必須把它拿回來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79301] = {title = "狐群狗黨", objective = "質問艾德溫關於筆記本的事。", description = "我真的受夠艾德溫了。從我們抵達的那一天起，他就一直跟大家說他會被選為船長。\n\n他是個很棒的飛行員，很有天分也懂很多。可是他的自大讓他沒辦法好好對待大家。而且他也知道我的成績跟飛行評鑑分數比他高。\n\n如果我無法交報告，他就會成為下一任船長。從他手中拿回我的報告！", progress = "你拿回來了嗎？我很想看看艾德溫臉上的表情…", completion = "他把筆記本丟進山谷，然後被風吹走了？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79302] = {title = "隨風而逝", objective = "取回10張蘇菲塔的報告書頁。", description = "我真不敢相信艾德溫讓我的報告隨風飄散。\n\n你可以盡量找回你能找到的書頁嗎？我會去學校附近找，你去山谷找。\n\n這份報告已經遲交了…但我對飛船性能有許多很好的見解。等芬奇院長看到它們時，或許他會讓我補交。\n\n去幫我把能找到的頁數找回來吧！", progress = "你找到所有書頁了吧，<name>！", completion = "我真的希望它看起來能更好一點。老實說，就算芬奇院長准我交出報告，我也覺得很丟臉。\n\n但我們還是得試試看…理念才是最重要的，這點永遠不變！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79303] = {title = "有原則的院長", objective = "將蘇菲塔的報告交給芬奇院長。", description = "你能收集到這些真是太好了。我也找到幾張被吹上來的，所以我們應該找到全部了。快拿去給芬奇院長吧！他很可能在教室裡。\n\n我真的很希望他會接受它。他說他不會接受遲交，但這算是情有可原的狀況。如果他不接受的話，我就必須接受艾德溫當船長，聽他的指揮。發生這種事後，我可不確定我辦得到。", progress = nil, completion = "蘇菲塔一直都是非常優秀的學生。老實說，我對這個情況有太多私人情感，無法做出不帶偏見的決定。不過這個情況非常敏感，也不能毫不考慮就拒絕。\n\n身為外來者，我知道你的決定不會偏心，因為你沒有跟這些學生相處好幾個月，所以我可以信任你的判斷。我很感激你幫忙解決這個難題，&lt;name&gt;。", rewards = "您會收到：\n\n飛船船長的披風共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][79304] = {title = "物資禮包", objective = "把愛心包裹交給聖光火花航空學院的蘇菲塔‧林弗雷。", description = "我和同樣身為堅兵的堂妹蘇菲塔一起來到聖落之地。到了這裡之後，我們在頓內爾的恩典工作了好幾年。不過，去年她離開了，為了追尋她想當飛船船長的夢想，她認為至少應該先成為飛船的船員。\n\n她是個堅強的人，不知道她最近過得如何。尤其是，她現在在聖光火花航空學院，吃不到旅店老闆瓦林做的甜捲餅！你可以把這些帶給她嗎？順便看看她是否都好。", progress = "這是什麼？要給我的嗎？", completion = "巴羅實在太好心了，居然送了這些過來。你可以告訴他我一切都好，不過，不知道你能不能先幫我一個忙？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79309] = {title = "狀況回報", objective = "找到失蹤的阿拉希軍團偵察隊。", description = "飛船讓阿拉希軍隊掌控了制空權。但道路是帝國的命脈。為了居民，我的偵察兵努力確保聖落之地道路的安全和照明。\n\n有一支巡邏隊沒有準時回來報告東邊道路的狀況。請循著煙霧或烈焰，尋找失蹤的偵察兵。阿拉希士兵都很清楚絕不能在黑暗中久待。", progress = nil, completion = "&lt;偵察兵維夏姆沒有對上你的視線。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79310] = {title = "尋找失蹤者", objective = "尋找維夏姆的隊員。", description = "守護道路，驅逐黑暗。教化這片扭曲的土地。為了我們帝國的名義。這便是阿拉希軍隊的使命。一個我再也無法承擔的使命。\n\n我好害怕。\n\n我不想回到黑暗中。尤其是在看過那個慘況之後。要是梅法斯特或其他的隊員還活著，他們一定會希望有人給自己一個痛快。而我卻留他們獨自面對恐懼。\n\n告訴真炎隊長她的偵察隊已經死在黑暗中，全軍覆沒。", progress = "<偵察兵維夏姆盯著營火的烈焰。>", completion = "&lt;偵察兵維夏姆緊抓著羅盤，最後抬起頭來看向你。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79311] = {title = "力挽狂瀾", objective = "殺死12個腐腫刺蜂或真菌感染者。", description = "道路應該要有照明。但路上雜草叢生，燈籠變得黯淡。成群結隊，流著口水，散發惡臭。一切都發生得太快。等到我們意識到危險降臨，那些野獸早已步步進逼。當中體型最大的個體龐大無比，暗如黑夜。\n\n我們的職責是殺死怪物，把牠們趕回黑暗。但內心的恐懼使我無法回頭。\n\n我勇氣盡失。但是，外來者，你還能補救這一切。", progress = nil, completion = "讚美聖焰，你還活著。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79312] = {title = "大規模割草", objective = "砍掉8株臭蜜葉。", description = "我和梅法斯特拋下其他人逃命，背後不斷傳來他們的慘叫。骯髒的汙泥弄滅我們的燈籠，在黑暗中，我們跌跌撞撞地涉過水深及膝的水池。我聽見落水聲，好像是她被絆倒了，但我沒有勇氣回頭看。\n\n我事後才發現腳踝上有些小小的咬痕。務必小心，水中好像有什麼東西。\n\n我注意到從池中長出的植物。成群的昆蟲享用著那些植物噁心的花蜜。摧毀那些植物，讓那些怪物挨餓。", progress = nil, completion = "&lt;偵察兵維夏姆向你認可地點點頭，露出沮喪的微笑。&gt;\n\n在黑暗中，就連植物都想置我們於死地。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79313] = {title = "於黑暗中成長", objective = "殺死耕鉤蜂。", description = "我們被告誡永遠不得走進黑暗中。隨時隨地都要帶著燈火。走回頭路的念頭讓我內心充滿畏懼。\n\n但你的勇氣熠熠生輝，<name>。在你身邊，我的道路也變得清晰。\n\n不能再躲躲藏藏了。那隻身披黑色甲殼、殺死我朋友的野獸，今天就得死在那個洞穴裡。我與你同在。", progress = nil, completion = "維夏姆把一切都告訴我了。\n\n我欠了不少人情。無論是對你，或是對那些為帝國犧牲的偵察兵。", rewards = "您會收到：\n\n火焰的追憶共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][79321] = {title = "育籃的贈禮", objective = "在提爾堡與安圖卡談話。", description = "我有急事要告訴你，冒險者。\n\n重生育籃似乎對大地的轟隆聲起了反應 - 甚至也可能是對你做的事有反應！\n\n很神奇的是，它現在願意分享它的力量，不求回報，想要的人只要去找它就行了。\n\n安圖卡對此更為了解。快去吧，$p。這是大好消息。", progress = nil, completion = "育籃每個禮拜都會賦予你足夠的力量來強化一件裝備。\n\n守衛者提爾一定在眷顧我們。不論他身在何方，這絕不是巧合。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79322] = {title = "鴨子怎樣了？", objective = "使用叭叭號角嚇跑10隻鴨子。", description = "唉喲…這群鴨子在這裡幹嘛？八成是什麼東西刺激到牠們了。鴨子差點撞倒我漂亮的祖傳金蛋！\n\n我們得趕走這群鬧事的鴨子，不然活動無法繼續下去。我會擋住牠們，不讓牠們跑進旅店，你幫我處理剩下的鴨子好嗎？", progress = "讓那些鴨子看看誰才是老大！", completion = "那群鴨子弄到一團亂。&lt;name&gt;，謝謝你。", rewards = "您會收到：\n\n明亮的彩蛋龍石"}
MultiLanguageQuestData['tw'][79323] = {title = "禽鳥對策", objective = "在暴風城的巫師聖所與艾莫瑞‧費斯克交談。", description = "我們必須制止這場鴨子入侵鬧劇。\n\n當時我忙著把一些離群的鴨子趕出旅店，結果鴨群跑來偷走一些裝飾和蛋。那堆被偷走的東西裡面有我珍貴的傳家寶！\n\n<name>，拜託你，我沒辦法再忍受這群小偷禽鳥了。我知道在暴風城有一個法師，對方應該知道該怎麼處理這個問題。", progress = nil, completion = "別擔心，他一定會想出辦法來的。等等，那邊好像出現一道傳送門。", rewards = "您會收到：\n\n明亮的彩蛋龍石"}
MultiLanguageQuestData['tw'][79324] = {title = "前往水力發電壩", objective = "在水力發電壩與達格蘭和ZZ-01-47會合。", description = "讓水力發電壩重新開始運作是我們的首要目標。如果我們沒辦法讓設施獲得電力，那我們做的其他事就白費了。\n\n等你到了那邊之後，就去跟達格蘭和ZZ-01-47會合。然後盡量讓他們做點小事就好。我可不想去跟茉艾拉解釋為什麼有我在，她兒子還會受傷，或遇到更糟糕的事。", progress = nil, completion = "這地方真是一團亂！我想我和吉吉應該會留在上面這裡，畢竟這裡沒那麼濕。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79325] = {title = "影脈抽取", objective = "在影脈抽取站與ZZ-01-47會合。", description = "我先派吉吉去影脈抽取站了。\n\n從他們傳回來的資料來看，那片區域充滿了岩石蟲，還覆蓋著這些…排放物。在等你的時候我幫他們做了升級。\n\n我不知道升級能在戰鬥中發揮多大的作用，但對任何試圖威脅他們的人來說，成果可能會很驚人。", progress = nil, completion = "&lt;吉吉發出認同和興奮的嗶嗶聲。看來它已經準備好出發了。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79327] = {title = "微光裂片", objective = "將閃亮的黏土交給尼貝爾加茲礦坑附近的歐仙絲。\n\n已提供物品：\n", description = "<這塊水晶裂片裡面發出微光，摸起來暖暖的。\n\n歐仙絲或許會有興趣檢視這塊礦石。>", progress = nil, completion = "水晶裂片？來自發光的洞穴？為什麼這對我來說如此耳熟？\n\n&lt;她接過水晶仔細檢視。&gt;\n\n這不可能吧！這就是我之前提過的治療水晶！我們以為它已經失傳了。把它拿在手中的感覺真奇妙……\n\n&lt;她深深地嘆一口氣，並看向穆德魯特。&gt;\n\n真希望它也可以療癒我們的心靈，就像它療癒我們的傷口一樣。我們需要讓密庫重新運作才行。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79328] = {title = "大使館與使者", objective = "在多恩諾加建立屬於你陣營的大使館。", description = "我很擔心我們回來之後會發現什麼秘密。雖然我們不得不離開，但看到你跟土靈建立深厚的情誼，並抵禦了奈幽蟲族，我感到很驕傲。\n\n有了你的助力，我們就能贏得勝利。但我們首先得訂下計畫，所以我們得在多恩諾加找個地方討論一下。", progress = nil, completion = "你是說你一直都是個室內設計師，卻把我瞞到現在？\n\n&lt;name&gt;，你很行嘛。\n\n我們回家之後，你一定要幫我重新布置我的房間。", rewards = "阿爾加長矛阿爾加重杖阿爾加步槍阿爾加巨劍阿爾加短斧阿爾加劈咒刃阿爾加權杖阿爾加格鬥刀您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79329] = {title = "發光的收割", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79330] = {title = "鴨子故事", objective = "使用藥水來從5隻鴨子那邊取得資訊。", description = "<name>，拿著這瓶藥水。只要靠它，你應該就能和那群長著羽毛的朋友溝通了。\n\n但如果有任何預期外的副作用，千萬別怪我。", progress = nil, completion = "什麼？有些鴨子是德魯伊？\n\n他們別以為搗亂了還能拍拍屁股走人。", rewards = "您會收到：\n\n明亮的彩蛋龍石"}
MultiLanguageQuestData['tw'][79331] = {title = "搖搖擺擺大步走", objective = "找出鴨子躲藏的地方。", description = "我們必須找出那些鴨子把偷走的東西藏在哪裡！順便查出來那個神秘的戴坦到底是誰。\n\n我說服艾莫瑞多給我一些那種藥水，你就帶在身上，找回我的傳家寶吧！", progress = "鴨子會躲在哪裡呢…", completion = "&lt;吉倪亞仔細地檢查傳家寶&gt;\n\n是不是被鴨子啃過了？我得花點功夫把它重新擦亮！\n\n謝謝你的幫忙，&lt;name&gt;。", rewards = "您能選擇下列奬勵中的一個：\n\n黑色鴨子偽裝棕色鴨子偽裝綠頭鴨偽裝粉紅鴨子偽裝白色鴨子偽裝黃色鴨子偽裝\n\n您還會收到：\n\n明亮的彩蛋鴨子偽裝器龍石"}
MultiLanguageQuestData['tw'][79333] = {title = "艦隊抵達", objective = "偵察港口，尋找來自部落或聯盟船艦的船。", description = "從我們墜毀在這座小島那一刻起，我們就清楚明白，要想對上薩拉塔斯，我們就需要拉攏盟友。\n\n珍娜和索爾去召集援軍了，你和我去看看這裡的土靈能提供哪些幫助。\n\n不得不說，我們自己做得不錯，對吧？\n\n<茉艾拉自豪地對你笑了笑。>\n\n不過，看來我們的援軍終於到了。保安官發現有船艦朝這裡駛來，去看看，確認一下好消息！", progress = nil, completion = "很高興看到你安然無恙，&lt;name&gt;。\n\n這趟旅程比預期的還要長。善變的大海顯然有它自己的打算。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][79335] = {title = "重現傳統", objective = "在崖側哨站附近收集5個礦石和5個充能核心。", description = "在我關機之前，我必須製作一個對我來說意義重大的物品。\n\n身為石縛者，我以前在礦坑裡工作。我有個自己製作的燈籠，我一直用到我在一場崩塌中失去它為止。在那之後不久，我就成為了無縛者。\n\n我希望可以鍛造一個新的燈籠，指引我走完最後的道路。\n\n燈籠的材質是這個地區有少量出產的原礦。我在燈籠裡用的是充能核心。你可以在棲息在這一帶山丘上的風牙狼身上找到它們。\n\n收集材料，我就可以把燈籠做出來。", progress = "你取得我要求的材料了嗎？", completion = "這些非常合適！\n\n現在…希望我還記得要怎麼鍛造燈籠。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79336] = {title = "鍛造記憶", objective = "協助科格蘭鍛造他的燈籠。", description = "在它關機以前，我們土靈會深入下方的甦醒機械，重新開始我們的循環。但現在，就算它仍在運作，我還是覺得我的循環會被打破，只能存在於他人的心中。\n\n<科格蘭長長地嘆了一口氣。>\n\n這雙手看起來很強壯，但隨著時間一分一秒流逝，它們也變得越來越沉重。我的手腕和手肘感到很僵硬，讓我沒辦法把東西帶到熔爐去。\n\n拜託你，請依照我的指示，把正確的材料放到熔爐裡。", progress = nil, completion = "它…嗯，它看起來…我不記得。\n\n可是這個燈籠非常漂亮！", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n結構圖：石縛燈籠"}
MultiLanguageQuestData['tw'][79337] = {title = "最後的旅程", objective = "等待科格蘭，然後在崖側哨站外與烏塔戈會合。", description = "這個燈籠真是完美。\n\n說夠多了，時間已到！我可以感受到我的記憶變得模糊。我們得走了。烏塔戈在等我們。他們會加入我們，和我一起走最後一程前往悼念高地，我們會在那裡舉行一個儀式。\n\n<科格蘭勉強地笑了一下。>\n\n我保證不是什麼華麗的儀式。如我所說，這比較是一種象徵性的過程。\n\n我的頭感覺好重。我剛剛在說什麼？嗯，噢，對！去見烏塔戈！", progress = nil, completion = "&lt;name&gt;，我們必須找到科格蘭！如果他一直勉強自己，他可能會在某個地方關機。\n\n而且他現在的情況不適合單獨行動。他很容易受到風牙狼甚至是狗頭人的攻擊。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79338] = {title = "走失的土靈", objective = "協助烏塔戈找到科格蘭。", description = "真是太糟糕了！我就知道我應該看緊他。\n\n困惑是關機前的最後一個症狀。我們的記憶體有限，會開始覆寫。土靈越是勉強自己，他們的能量就會越快用完，他們就會失去記憶。科格蘭不知道自己在哪裡一定很害怕，他甚至有可能不知道自己是誰。\n\n我真是個石腦袋！\n\n<name>，拜託你，我好像看到他往東走進樹林中。我們在前面的路會合！", progress = "你有找到科格蘭的蹤跡嗎？", completion = "噢，不，科格蘭的情況惡化地很快。\n\n把燈籠給他看是個好主意。\n\n謝謝你引導他回到我身邊。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79339] = {title = "改變傳統", objective = "在海岸邊與烏塔戈跟科格蘭會面。", description = "無縛者土靈無法回到地心通途去，所以我們才有了悼念高地。可是看著科格蘭，回憶起我們最後的對話…\n\n雖然我還不是悼念高地的管理員，可是以科格蘭現在的情況，我必須扛起責任。\n\n身為無縛者，我們創造了我們自己的規則跟傳統。要是他不想站在悼念高地又怎樣？如果管理員科格蘭想要在海邊離開，那我們就照著辦。\n\n<name>，到東南邊的海岸跟我會合。", progress = nil, completion = "能夠散步他很開心，可是這對他造成了很大的負擔。\n\n科格蘭現在幾乎認不得我了。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79340] = {title = "宣示工具", objective = "在不息河口附近收集4個完好的角。", description = "身為無縛者管理員，我們有個傳統，是師父要把衣缽傳承給他們的學徒。\n\n當然，是象徵性的。\n\n要執行傳統，科格蘭會需要一個號角。\n\n他需要面對我、吹響號角，號角的聲音就代表他將悼念高地管理員的衣缽傳承給我。\n\n我看到西邊有岩角犀。如果你可以把牠們的角拿來給我，我會很感激的。我會選擇一個適合的來用。", progress = "記得，犄角的狀態一定要非常良好才行。", completion = "這些真是太美了！\n\n我對岩角犀感到很抱歉，但反正牠們的數量很多。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79341] = {title = "淨化灰燼", objective = "在不息河口附近收集6朵灰坑花朵。", description = "無縛者有一個象徵性的淨化儀式。我們會在關機前舉行。\n\n這是個淨化的象徵性過程。為了儀式，我們需要採集灰坑，這是島上長的一種花。我們會讓燃燒花朵的煙霧穿過我們身上的裂縫，象徵性地移除汙穢。\n\n然後，我們就會準備好迎接最後的時刻。\n\n<烏塔戈一手放在胸前看向科格蘭。她的臉色沉了下來。>", progress = "你找到花了嗎，<name>？", completion = "謝謝你，&lt;name&gt;。我會用它們來準備儀式。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][79342] = {title = "他的離開", objective = "協助烏塔戈與科格蘭舉行儀式。", description = "該舉行儀式了，<name>。\n\n請把裝著灰坑的碗擺在科格蘭旁邊，然後把號角拿給他。\n\n一旦儀式完成，我就會是新的管理員。然後我就得跟我的朋友做最後的道別。\n\n科格蘭會平靜地關機，知道我們一直陪在他的身邊，在這個他最喜歡的地方…等到換我的時候，希望我也是這樣走。\n\n我的核心是泥土，不過能站在他身邊是我莫大的榮幸…站在你身邊也是。", progress = nil, completion = "能夠在這裡，目睹這樣的事件真是我的榮幸。\n\n你也參與了這個過程，我知道在他內心深處，科格蘭的核心的某處，你的回憶會永遠活在其中，&lt;name&gt;。\n\n謝謝你。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n宣示號角"}
MultiLanguageQuestData['tw'][79343] = {title = "我每天都在東聞西聞", objective = "把奇怪的蠟塊交給剛達加茲的諾博斯。", description = "或許剛達加茲的狗頭人會對這奇怪的蠟塊感興趣。", progress = nil, completion = "米多斯總是需要蠟來做東西。\n\n如果有很多的話，就會用更大更閃亮的紅寶石交換。幫忙的話就能換很多酷東西。\n\n繼續嗅聞，繼續交易。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79344] = {title = "都市漫遊", objective = "在多恩諾加四處詢問，尋求在接下來的衝突中表態支持的人。", description = "<name>，你聽到了嗎？\n\n許多城鎮的人們都積極想要支援我們對奈幽蟲族以及薩拉塔斯的攻擊。我覺得這值得我們去接觸他們，看看要怎麼一起合作。\n\n獲得的幫助越多越好。", progress = nil, completion = "謝謝你，&lt;name&gt;。我們找到越多人願意幫忙，就越有機會成功。\n\n不過，要是我們的戰力不夠龐大，就沒辦法成事。\n\n土靈的狀態不好。但我認為這點艾蘭里亞可以幫上忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79346] = {title = "嚼嚼看", objective = "從生長在黑暗中最高大的植物身上收集20份暮莖。", description = "在這裡釣魚不是一件容易的事，尤其是黑暗中的詭異聲響讓你開始疑神疑鬼的時候。\n\n我一向習慣嚼些暮莖，它們來自附近的高大植物，具有甜味和嚼勁，能讓嘴巴忙一點，幫助我度過這段時間！\n\n如果你可以幫個忙，和你的飛行坐騎一起採集一些暮莖，我會非常感激。", progress = "你收集得夠多了嗎?", completion = "你讓這件事看起來很容易。我通常要花一個小時才能爬上其中一株植物。", rewards = "您會收到：\n\n燈火者補給包共鳴水晶聖落之地阿拉希青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][79349] = {title = "企業家有限公司", objective = "到姆瑪爾找瑞普斯努多。", description = "很好，讓我印象深刻。我現在正式任命你為我的金勇！算是領金幣幫我做事的勇士。就像是傭兵，只不過金勇聽起來比較厲害。\n\n你應該見見我的生意夥伴瑞普斯努多。他帶著他的金勇，跟姆瑪爾的鼴鼠人做生意。他或許能給你更多工作，不過我勸你，要是他跟你推銷東西，千萬別買。\n\n姆瑪爾就在這裡的東邊。跟著你的鼻子走就好，你從一英里外就能聞到它的味道。", progress = nil, completion = "絲凱吉真的找到寶了？她的商業嗅覺一向很敏銳。", rewards = "您會收到：\n\n干擾偵測裝置織絲者(惡名值)卡吉"}
MultiLanguageQuestData['tw'][79351] = {title = "等級25", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79352] = {title = "等級24", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][79354] = {title = "機語者", objective = "在剛達加茲旁聽茉艾拉和代言者布琳瑟的對話。", description = "啊，$p！大名鼎鼎的<race>…我們剛剛正談論到你。\n\n<茉艾拉朝代言者布琳瑟點了點頭。>\n\n現在至高代言者的邪惡行徑已經被制止，甦醒機械也再次恢復運作，而我們還有一些未了之事需要處裡。\n\n你介意留下來嗎？", progress = nil, completion = "這是鳴響深淵嶄新的一天。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79355] = {title = "拯救俘虜", objective = "找到4個遠征隊成員。", description = "那些蟲子抓走了我們的人！我們逃到一半，想說休息一下，結果就有人被拖走了！\n\n我們才剛剛逃離奈幽蟲族的魔掌，我們不能再失去更多人了。\n\n去搜索沃許蟲巢。那些蟲子就來自那裡。運氣好的話，我們的人說不定還活著。", progress = nil, completion = "你已經盡力了。我欠你一個人情。我們會處理那個蟲巢，就算是對婕媞的紀念。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79356] = {title = "抗真菌縱火狂", objective = "燒掉8個真菌孢子莢。", description = "我的專業直覺告訴我，那些孢子莢產生的孢子，跟感染那些蟲子的孢子，兩者有一定的關聯。\n\n要是我們毀掉那些真菌孢子莢，應該就能多少降低蘑菇人對那些蟲子的控制程度。\n\n帶著這些抗真菌火焰彈，盡可能點燃真菌孢子莢。", progress = nil, completion = "做得非常好，我的朋友。這樣就能暫時控制住這些蟲子。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79357] = {title = "擒賊先擒王", objective = "擊殺阿加里庫斯‧膿卉。", description = "依瑪拉提到，有個大型蘑菇人正在種植真菌孢子莢，這令人非常擔心。那個洞穴的深處一定有問題。\n\n我們不能乾等著蘑菇人控制一票害蟲來攻擊我們。我們必須在事態惡化前就加以遏止。\n\n前往沃許蟲巢殺掉蘑菇人首領！", progress = nil, completion = "那個蘑菇人領袖的計畫泡湯了，營地又再次恢復安全。謝謝你，朋友。", rewards = "您會收到：\n\n織絲者(惡名值)卡吉卡吉"}
MultiLanguageQuestData['tw'][79367] = {title = "需要幫助的涅博", objective = "收集一捆蠟燭，沿著路障放置蠟燭。", description = "你！你不是蜘蛛。求求你，在蜘蛛又來之前，幫幫忙。\n\n涅博知道蟲鳴穴。以前從沒在這裡看過蜘蛛。蜘蛛來吃幼蟲，吃狗頭人。不過蜘蛛是來自黑暗地方的黑暗生物。討厭亮光。\n\n不能離開哨站。你帶著蠟燭，好不好？點亮路障。趕走蜘蛛。", progress = "驅散黑暗。驅散蜘蛛。", completion = "很好。現在我們安全了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79368] = {title = "蜘蛛剛毛", objective = "收集12份地底爬蛛毒液。", description = "變亮了，很好，不過還有事要做。\n\n蜘蛛來自四面八方。涅博很快，涅博聽見牠們。不過好友史努喬…他被咬了。現在生病了。\n\n涅博有辦法，沒錯，把毒液變成解藥。用蜘蛛咬治療蜘蛛咬。\n\n把毒液帶來。快點！", progress = "你取得毒液了嗎？", completion = "沒錯，噁心的毒液是完美的解藥。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79369] = {title = "保護食物", objective = "收集20顆幼蟲卵。", description = "涅博很年輕，看不到比鼻子還遠的東西。要是失去食物，很多狗頭人都會死。不是只有史努喬。\n\n不能浪費時間。要是蜘蛛吃掉幼蟲和蟲卵，狗頭人就會餓肚子。\n\n救救他們，收集蟲卵。收集越多越好，別讓蜘蛛全部搶走。", progress = "帶來蟲卵，我們就有食物。", completion = "損失不少。有了這些，大概可以撐到下次幼蟲季。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79370] = {title = "解毒膏藥", objective = "對史努喬使用涅博的膏藥。", description = "一點毒液，一點蠟…\n\n<涅博把手伸入袋子裡，掏出一把黏稠、刺鼻的蠟，交給你。>\n\n對對，應該有用。最好的膏藥，家族的秘方。快點，交給史努喬，他會覺得好一點。", progress = nil, completion = "沒用，還變糟了！怎麼會？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][79371] = {title = "女王的解藥", objective = "收集莉斯緹卡女王的毒液，為史努喬製作新的膏藥。", description = "膏藥沒用！蠟是對的，毒液錯了？\n\n沒錯…沒錯！最強的解藥需要最強的毒液。涅博看過爬行蛛。女王是紅黑相間，體型很大很大，狗頭人根本不是對手。女王聞到多汁的幼蟲，就會衝向洞穴。\n\n你必須跟著她。收集女王的毒液。拜託，史努喬的時間不多了。", progress = "女王的毒液一定有用。", completion = "生效了！他不再綠綠的。謝謝你，謝謝你救了我的好友史努喬。", rewards = "您會收到：\n\n共鳴水晶共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][79372] = {title = "希望之卵", objective = "將卵交給涅博。", description = "<蟲后倒臥在地，蜷起身體保護一顆卵。她犧牲了自己，不讓卵遭到蜘蛛的毒手。\n\n你應該將卵交給涅博。他和其他幼蟲照顧員會知道如何處理這顆卵。>", progress = "這是什麼？另一顆卵？", completion = "這不是普通的卵。是蟲后卵。\n\n&lt;涅博從你手中收下卵，一臉崇敬地拿在手裡。&gt;\n\n有了這個，幼蟲不只能活下去，還能繼續壯大。謝謝你。我們會保護它。", rewards = "您會收到：\n\n"}
