MultiLanguageQuestData['tw'][80310] = {title = "落陽要塞", objective = "在落陽要塞與安吉‧秋光交談。", description = "你願意去西邊的落陽要塞找安吉嗎？她被派去訓練新加入的熊貓人，好讓他們能做出貢獻。我想你應該可以露一手給那些新兵瞧瞧。", progress = nil, completion = "我認同你的實力。我們來讓這些受訓者見識一下真正&lt;class&gt;的戰鬥方式。", rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][80311] = {title = "雲蛟衛", objective = "在落英園與安麗長老交談。", description = "騎烏龜的感覺真好！\n\n但騎雲蛟的感覺更是好到不行！\n\n在落英園那裡有人會騎雲蛟，他們可以教你！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱"}
MultiLanguageQuestData['tw'][80312] = {title = "奄奄一息的請求", objective = "將怪魚放到無日海岸寇拜斯營地附近的安全水域中。", description = "<從寇拜斯屍體中取出的魚在你手中虛弱地拍動，看起來奄奄一息，非常可憐。牠的眼珠抽動，而你的腦海深處突然聽見一段急促的聲音。>\n\n水。送我到水裡。遠離這些寇拜斯混帳。遠離天空。", progress = nil, completion = "&lt;那條魚大口吞下海水，恢復正常呼吸，然後轉頭用慧黠的眼睛看著你。&gt;\n\n多虧你，我活下來了。這些岩石的陰影很適合要做的事。\n\n請允許我報答你無私的善舉。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80313] = {title = "潮汐符咒", objective = "到無日海岸從寇拜斯身上收集12枚無日裂片。", description = "<那條魚說話的時候，牠的嘴唇並不會動。你是在腦海裡聽見牠的聲音。>\n\n你也發現了吧，面對寇拜斯的時候，你無法信任自己的感官。很強大的力量，對吧？那就禮尚往來，用他們的力量對付他們，讓他們知道不是只有他們辦得到。\n\n我會教你製作能引誘並消滅他們的工具。你可以從他們身上找到取自深海的裂片。把裂片帶來給我。", progress = "備好材料。這樣我們才能進行下一步。", completion = "閃爍的深淵裂片和一束束珊瑚。以語言的力量束縛，然後戴在脖子上，我會教你如何混淆敵人的感官。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80314] = {title = "來自深海的聲音", objective = "研究三個祭祀場所，深入了解寇拜斯。", description = "欺騙這些寇拜斯的感官是一回事。知道什麼東西能迷住他們又是另一回事。光是想到能吞吃你們這類人，就能讓他們垂涎三尺。不過深海的聲音能鎮住他們，降低他們的防備。那就是你出手的時候。\n\n搜索他們的聖壇，了解這些混帳視為神聖的事物。看看他們如何扭曲表面之下大聲疾呼的真實。", progress = nil, completion = "你現在知道寇拜斯崇拜什麼了。是時候來利用這些黑暗的知識了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80315] = {title = "難以抗拒的誘惑", objective = "在無日海岸外海的小島上，引誘並暗殺刻鰓者和他的寇拜斯潮汐元帥。", description = "完成了。帶著這個潮汐符咒，讓你的身影籠罩在大海的黑暗之中，開始清除寇拜斯。他們最強大的戰士都齊聚在中央的小島，策劃對凡人的陰謀。有了誘餌，他們就看不清你的真正樣貌。利用這個優勢來終結他們。\n\n但你要牢記一點，這股力量是你借來的，它真正的主人是大海。別犯了和寇拜斯一樣的錯。", progress = nil, completion = "這樣一來，他們終於受到教訓了。他們下次把我們這一族當成食物之前，應該會好好考慮一下。\n\n你下手很俐落，陸地人。不過該歸還深海借你的力量了，而我們的緣分也要告一段落了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80316] = {title = "回到大海", objective = "帶怪魚去更深的海裡。", description = "我剛才太過靠近地面的灼熱光芒，身體還很虛弱。請你帶我到更深的水域，遠離這些寇拜斯，讓我能夠回到族人身邊。", progress = nil, completion = "&lt;那條魚發出高歌般的呼喊聲。歌聲朝著海洋的深處傳去。&gt;\n\n我本以為我會因為自己的愚蠢，不光彩地死在寇拜斯手中。但我沒預料到陸地人救了我一命。我會記得你。那麼，我就不再維持這個表象。我的族人等著我回去。\n\n&lt;魚的形體開始變形扭曲。你意識到魚的形象只不過是它的另一個偽裝。&gt;", rewards = "您會收到：\n\n深淵海蛞蝓共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][80320] = {title = "協助卡拉西", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80321] = {title = "出發", objective = "返回地表尋找卡德加。", description = "我們最好在這裡分開。我會引導大家到安全的地方，並四處看看，幫助他們撤離。\n\n在此同時，你應該去找卡德加。相信他現在也需要你的幫助。\n\n再往前走一段就會看到另一個出口，可以帶你回到地表。", progress = nil, completion = "&lt;傳送門閃爍且扭曲，想看到另一邊的情況是不可能的事。&gt;", rewards = "您會收到：\n\n城市守衛頭冠城市守衛面具城市守衛鎖子甲城市守衛護脛"}
MultiLanguageQuestData['tw'][80323] = {title = "不明朗的對峙", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][80334] = {title = "破碎尖塔", objective = "到平靜淺灘找埃薩。", description = "達拉然的尖塔沒有東西來抑制它們的秘法能量，現在正在崩塌。\n\n如果我們讓它們的能量繼續滲出不管，那股力量可能會異變，然後摧毀我們剩下的部隊。\n\n去找埃薩！他會知道該怎麼做的。", progress = nil, completion = "珍娜還活著？\n\n感謝太陽之井！\n\n不過，要是我們不抑制尖塔的能量，我們大家都活不久了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80349] = {title = "回程時刻", objective = "回去找莫菈塔莉。", description = "你最好立刻啟程。傳送門應該能把你送回村莊。", progress = nil, completion = "很好。希望這能加快我們的研究。", rewards = nil}
MultiLanguageQuestData['tw'][80378] = {title = "黑暗之光", objective = "收集凝結黑血，然後交給剛達加茲的狗頭人製燭師「破破」。", description = "當你打量著面前那灘腐臭的汙物時，心中突然浮現一個畫面，一根點燃的紫色蠟燭釋放出無比美妙的力量，緊接著是一段微弱的低語迴盪在你心中：「一根蠟燭統治他們全部，以它的光明束縛他們」。\n\n將足夠的凝結黑血交給剛達加茲的製燭師破破，製造出最不幸的蠟燭。", progress = "<當你靠近時，破破不禁顫抖。>\n\n啊！", completion = "喔…破破通常對新蠟燭來者不拒，但你確定嗎？", rewards = "您會收到：\n\n凝結血棒共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][80380] = {title = "披風與針線", objective = "裝備你的恆龍潛力披風，並從恆龍劫毀者身上收集力量之絲。", description = "一旦你披上披風，就能在任何敵人身上找到絲線。\n\n披風會自動吸收絲線，永久提高你的能力。\n\n試著從附近的恆龍劫毀者身上收集絲線。", progress = nil, completion = "你隨時都能找到類似的絲線，無論是殺死敵人，或是拾取寶藏。", rewards = "您會收到：\n\n青銅幣"}
MultiLanguageQuestData['tw'][80382] = {title = "把雞蛋放到同個籃子裡", objective = "收集10顆西爾海姆蛋，放入這個籃子中。", description = "<這張訂單仍無人接單。如果你協助完成這筆訂單，一定會讓阿里雅‧西爾海姆開心不已。>", progress = "通知阿里雅訂單完成了。", completion = "非常感謝你！在婕塔嬸嬸離開我們之後，我們一直人手不足。任何協助我們都很感激。", rewards = "您會收到：\n\n輻光殘骸共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][80384] = {title = "桶印包裹", objective = "將桶印紙條交給沃卓肯炙烤公羊旅店的達卡許‧嚴帳。", description = "<一個沒什麼特徵的人將一個皺巴巴的小包裹塞進你手中，上面還貼著一張紙條。那個人很快就消失在人群之中。紙條上面的文字歪七扭八，彷彿是用匕首沾著墨水寫成。>\n\n這是你應得的戰利品。\n\n派夥伴去旅店一趟。\n\n<你仔細觀察紙條，看看上面還有沒有其他線索。你發現下方印有一個桶子圖案。\n\n你輕輕搖晃包裹，聽見了響亮的硬幣聲。>", progress = nil, completion = "收到桶腿送來的包裹了，對嗎？\n\n唉，我也真是搞不懂，你怎麼會上了我們這艘賊船，不過船長的決定還輪不到我來質疑。\n\n看一下我擺在這附近的成果，你可以用那些硬幣來跟我換一些好東西。", rewards = "您會收到：\n\n桶印硬幣"}
MultiLanguageQuestData['tw'][80385] = {title = "拚最後一次：巨龍群島", objective = "為巨牙海民的集體盛宴和莫魯克的狩獵提供協助，並幫忙奪回龍禍要塞。", description = "你在我們的盟友間可出了名呢，<name>！\n\n南方的伊斯凱拉巨牙海民需要你為集體盛宴提供協助。\n\n西方的莫魯克需要你為狩獵提供協助。\n\n北方的黑曜流亡者則需要你協助奪回龍禍要塞。\n\n聽起來你有得忙了！祝你好運。", progress = nil, completion = "感謝你的努力，巨龍群島才有這般安逸的生活。\n\n請收下我們的謝禮。", rewards = "您會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n覺醒風暴貯藏箱"}
MultiLanguageQuestData['tw'][80386] = {title = "拚最後一次：扎拉萊克洞窟與時間裂隙", objective = "保護遭攻擊的研究員、在元素灌能營地搜刮封住的貨箱，並協助索芮朵蜜驅散時間裂隙。", description = "我們的盟友再次需要你的協助，<name>。\n\n扎拉萊克洞窟的龍鱗遠征隊需要你保護他們的研究員。\n\n雍亞拉平原與蒼藍高地也遭到薩克利入侵。\n\n同一時間，青銅龍軍團需要你幫助他們解決沃卓肯東邊的時間異象。\n\n動作快點，<name>，時間不多了。", progress = nil, completion = "你幫助過的人都傳來了好消息，&lt;name&gt;。\n\n請收下這個禮物。", rewards = "您會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n覺醒餘燼貯藏箱"}
MultiLanguageQuestData['tw'][80388] = {title = "拚最後一次：翡翠夢境", objective = "在巨龍群島收集一百個夢境湧現精華、協助杉冠進行繁盛綻放，並在翡翠夢境種下3顆任何品質的夢境種子。夢境種子可在翡翠夢境的大多數活動中取得。", description = "德魯伊需要協助！\n\n翡翠夢境的能量正四散到巨龍群島上，還請你幫忙調查。\n\n他們也請你到翡翠夢境協助杉冠進行繁盛綻放。\n\n一些德魯伊也希望你能在翡翠夢境中種下夢境種子。\n\n就請你幫幫他們了，<name>。", progress = nil, completion = "我的老天，你為翡翠夢境所做的一切絕對能幫助艾澤拉斯復原。\n\n為表感謝，請收下這份薄禮。", rewards = "您會學到：\n\n每週覺醒活動\n\n您還會收到：\n\n覺醒夢境貯藏箱"}
MultiLanguageQuestData['tw'][80389] = {title = "拚最後一次", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][80392] = {title = "布讓溫的宮殿的管理員", objective = "向6名靜止的土靈獻上燼釀蜜酒並殺死10隻蜜糖嗅鼴。", description = "你好，外地人。你一定就是我聽說的那位萬事通！我是管理員芭姿瓦菈，我負責照顧陷入靜滯的土靈，就像這位朋友一樣。\n\n我常常會去布讓溫的宮殿走走，用燼釀蜜酒供品來紀念我親愛的土靈同胞。不過最近，我吸引了一群當地鼴鼠的注意。牠們的鼻子很擅長找甜食，更有貪婪的爪子。\n\n你看起來有能力保護自己。你可以陪我去向那些靜滯的人獻上敬意嗎？", progress = nil, completion = "感恩，你果然如傳聞所說，是位堅定的盟友。", rewards = "您會收到：\n\n"}
