MultiLanguageQuestData['tw'][80427] = {title = "協助金蓮會", objective = "你是來幫助我們的嗎？", description = nil, progress = "你是來幫助我們的嗎？", completion = "好極了！繼續訓練，我們隨時候教！", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80429] = {title = "協助聖獸天尊", objective = "煞迫使我們去思考我們要為什麼而戰。為了潘達利亞的未來，你願意付出什麼？", description = nil, progress = "煞迫使我們去思考我們要為什麼而戰。為了潘達利亞的未來，你願意付出什麼？", completion = "你很勇敢，也很可敬。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80430] = {title = "協助聖獸天尊", objective = "你有獻給偉大玄牛的貢品嗎？", description = nil, progress = "你有獻給偉大玄牛的貢品嗎？", completion = "昂首而立，出手俐落。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80431] = {title = "協助聖獸天尊", objective = "你好，挑戰者。我接受你捐贈給寺廟的東西。", description = nil, progress = "你好，挑戰者。我接受你捐贈給寺廟的東西。", completion = "帶著力量與榮耀而戰。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80434] = {title = "進入深處", objective = "在地心通途的底層找到代言者布琳瑟。", description = "那麼就朝地下前進吧。我們最好跟在代言者布琳瑟後面，看看奈幽蟲族讓她的家園變成什麼樣子。\n\n我、麥格尼和達格蘭會在適當的時機下去找你。你介意先去前面探查一下，確保有熱烈的歡迎在等著我們嗎？", progress = nil, completion = "泰坦啊！看來奈幽蟲族對我們的站點動了不少手腳……但我沒有在這裡看到那些蜘蛛怪物。只有掙扎求生的機語者……", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80438] = {title = "協助部落", objective = "Lok-tar，<name>。你帶來什麼幫助？", description = nil, progress = "Lok-tar，<name>。你帶來什麼幫助？", completion = "為了部落！", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80439] = {title = "協助聯盟", objective = "瓦里安國王需要你的幫助，<name>。你有任何物資嗎？", description = nil, progress = "瓦里安國王需要你的幫助，<name>。你有任何物資嗎？", completion = "軍人的責任永遠不會結束。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80441] = {title = "協助雲蛟衛", objective = "雲蛟仰賴順風。你願意捐獻嗎？", description = nil, progress = "雲蛟仰賴順風。你願意捐獻嗎？", completion = "太棒了。祝你一路順風。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80442] = {title = "協助奪日者先鋒軍", objective = "我的斥候回報了敵人有動靜。你有任何能幫助我們部隊的物資嗎？", description = nil, progress = "我的斥候回報了敵人有動靜。你有任何能幫助我們部隊的物資嗎？", completion = "非常好，我們應該能展開反擊了。", rewards = "您會收到：\n\n\n\n等級 70–70非同步稜彩寶石\n\n等級 62–70雷神皇宮鑰匙恆龍寶箱"}
MultiLanguageQuestData['tw'][80443] = {title = "協助祈倫托先遣軍", objective = "不流點血，談何勝利。<class>，你是來幫忙的嗎？", description = nil, progress = "不流點血，談何勝利。<class>，你是來幫忙的嗎？", completion = "我會好好保管的。", rewards = "您會收到：\n\n\n\n等級 70–70非同步稜彩寶石\n\n等級 66–70恆龍寶箱\n\n等級 65–70雷神皇宮鑰匙"}
MultiLanguageQuestData['tw'][80444] = {title = "協助釣手隊", objective = "嘿，夥伴！最近有釣到任何符咒嗎？當地人說它們能帶來好運。", description = nil, progress = "嘿，夥伴！最近有釣到任何符咒嗎？當地人說它們能帶來好運。", completion = "感激不盡！有了這個，我們一定能大豐收！", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][80446] = {title = "搜尋團隊", objective = "擊敗3個地城首領。", description = "我最中意的勇士來了！\n\n如果你需要狩獵的目標，我知道幾個值得一探究竟的地城。", progress = "地城探索還順利嗎？", completion = "我就知道你做得到！", rewards = "您會收到：\n\n\n\n等級 65–70大型青銅寶箱大型永恆絲線捲\n\n等級 10–70恆龍寶箱小型青銅寶箱\n\n等級 50–64青銅寶箱永恆絲線捲\n\n等級 30–49次級青銅寶箱次級永恆絲線捲\n\n等級 10–29小型永恆絲線捲"}
MultiLanguageQuestData['tw'][80447] = {title = "尋找更多", objective = "擊敗2個團隊副本首領。", description = "你覺得自己很強悍嗎？\n\n如果你敢面對真正的挑戰，我就相信你。\n\n擊敗潘達利亞最強大的敵人，讓我們見識一下你到底有多強。", progress = nil, completion = "看來你還挺厲害的！", rewards = "您會收到：\n\n\n\n等級 65–70大型青銅寶箱大型永恆絲線捲\n\n等級 25–70恆龍寶箱小型青銅寶箱\n\n等級 50–64青銅寶箱永恆絲線捲\n\n等級 30–49次級青銅寶箱次級永恆絲線捲\n\n等級 25–29小型永恆絲線捲"}
MultiLanguageQuestData['tw'][80448] = {title = "嶄新的場景", objective = "完成一個事件。", description = "不行，親愛的，我不能放任你整天待在悶熱的地城裡，讓世人無法看見你的裝扮！\n\n穿上你的外出服，我們找個地方放鬆一下！", progress = nil, completion = "喔，親愛的，我看得出來你去了某個好地方。\n\n快點把細節都告訴我！", rewards = "您會收到：\n\n\n\n等級 65–70大型青銅寶箱大型永恆絲線捲\n\n等級 10–70恆龍寶箱小型青銅寶箱\n\n等級 50–64青銅寶箱永恆絲線捲\n\n等級 30–49次級青銅寶箱次級永恆絲線捲\n\n等級 10–29小型永恆絲線捲"}
MultiLanguageQuestData['tw'][80456] = {title = "莽撞的阿拉希人", objective = "在多恩諾加與保安官列夫談話。", description = "我聽說有個阿拉希人在城鎮裡製造麻煩。聽起來他和保安官有些爭執。\n\n你以前跟阿拉希人合作過對不對？或許你會有辦法平息紛爭。", progress = nil, completion = "是的，我能如何幫你？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80457] = {title = "服侍女王", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][80500] = {title = "銅鬚一族", objective = "到達拉然旅客中心找布萊恩和達格蘭，將發生在麥格尼身上的事告訴他們。", description = "<茉艾拉深吸一口氣，試圖冷靜下來。>\n\n我們必須讓布萊恩和我兒子達格蘭知道發生了什麼事。他們正在達拉然的旅客中心。\n\n你可以替我去找他們嗎？父親現在需要他的家人。", progress = nil, completion = "即使是因為情況緊急，但我還是很高興看到所有人齊聚一堂。我父親其實從來沒有…參與達格蘭的人生。但我打算改變這一點，我向你保證。\n\n&lt;name&gt;，謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80502] = {title = "阿茲-卡罕特，別為我哭泣", objective = "為克拉斯金報仇，在晦影市集殺死阿拉希妮。", description = "<你找到一團皺巴巴的筆記，其中還包了一把小鑰匙。>\n\n我一直懷疑阿拉希妮是保守派分子，但我不知道她竟然會做到這等地步。我不知道該何去何從，但我必須離她遠遠的。\n\n不管是誰找到這個，就代表我已經遭遇不測了。這把鑰匙能打開一個存放我財物的箱子。裡面的東西全都歸你了。\n\n請你殺了阿拉希妮，為我報仇。", progress = nil, completion = "這個箱子裡的東西現在歸你了。\n\n- 克拉斯金", rewards = "您會收到：\n\n初擁長靴飢餓新娘腰帶傳統婚禮肩墊愛的最後之握織絲者(惡名值)卡吉"}
MultiLanguageQuestData['tw'][80508] = {title = "洞穴中的恐怖", objective = "在蟲鳴穴跟史奎特在她的營地會面。", description = "你是狗頭人的朋友對吧？需要幫忙。蟲鳴穴有壞事發生。\n\n陰齒幫在紮營。蠟燭大王的親信想要跟土靈開戰。\n\n我無法獨自阻止他們。到營地跟我碰面。", progress = nil, completion = "你來了。很好。很多事要做，很多人要保護。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80509] = {title = "軟泥服裝", objective = "從蠟流和蠟變跳跳兔妖身上收集20份黏黏蠟。", description = "你長這樣，陰齒幫派不會讓你進營地。需要偽裝。讓你看起來像蟲，然後我們直接走進去。\n\n首先，需要蠟。這裡很多。從軟泥怪拿或從跳跳兔妖身上刮。\n\n然後我們把蠟黏在你身上。再把蟲蟲裝扮黏到蠟上。完美偽裝。", progress = "有了對的偽裝，就沒有人會知道你不是蟲。", completion = "都準備好了，你很快就會看起來像蟲了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80510] = {title = "淨化水源", objective = "移除6個蠟碎塊。", description = "陰齒幫真浪費！他們在水裡留好多廢棄物。對水很不好。對廢棄物不好。去把它清理一下。", progress = nil, completion = "好多了。讓廢棄物在水池裡腐壞真說不通。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80511] = {title = "探察營地", objective = "調查陰齒幫營地。", description = "現在我們帶你去營地吧。你會看到鬚鞭頭目在做什麼。我們靠近營地的時候，把蟲蟲偽裝穿上。我來負責談話就好。", progress = nil, completion = "你看到陰齒幫都在幹什麼了嗎？竟然還抓了土靈俘虜！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80512] = {title = "戰勝最強者", objective = "擊敗蟲蟲訓練師。", description = "如果陰齒幫成功的話，以後還會有更多這樣的土靈俘虜。我們需要放了他。\n\n他是獎勵。這裡的每個狗頭人都想跟他戰鬥。一定要證明我們的地位。\n\n你打敗厲害的蟲蟲，他們就會覺得我是厲害的訓練師。然後他們就會讓你到格鬥場上。\n\n祝最厲害的蟲蟲獲勝。", progress = nil, completion = "做得好！你打架起來真的像隻蟲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80513] = {title = "打歪鼻子", objective = "擺放燼閃蠟燭並鬆綁蟲的韁繩。", description = "你需要分散他們的注意力才能把土靈救出來。我需要阻止陰齒幫。我有辦法可以同時完成兩件事。\n\n某個傻瓜在狗頭窟把燼釀蜜酒跟蠟燭的蠟混在一起。蠟燭一開始會正常地燒，然後就會碰！大爆炸！在營地到處放。爆炸是逃脫的好掩護。\n\n你去放的時候，順便鬆開一些蟲的韁繩。讓陰齒幫看看蟲蟲有多可怕。", progress = nil, completion = "非常好，時候到的時候，你會有很好的干擾。等不及了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80514] = {title = "救出貝魯德！", objective = "從營地護送貝魯德。", description = "你做得很好。現在他們會讓你到格鬥場去和土靈「決鬥」。你準備好後就上格鬥場。燼閃蠟燭隨時都可能引爆。\n\n我會回營地去。在那裡等你和土靈。\n\n你是個好人。別被殺死了。", progress = nil, completion = "捕捉？不是，我只是在收集情報。而且我有個壞消息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80515] = {title = "光芒四射", objective = "釋放燭光蟲並收集牠們的發光粉。", description = "很不想承認，可是吵鬧土靈是對的。鬚鞭頭目有最厲害的蟲蟲。可是萬物都有弱點。\n\n蜘蛛怕光，而我們的朋友非常閃亮。如果我們讓他更閃亮，就沒有蜘蛛想跟他打了。\n\n陰齒幫捉了很多燭光蟲。去把牠們放了，然後從牠們身上搓一些發光粉下來。我們讓大土靈大閃亮！", progress = "這最好不要塗在他頭上。", completion = "對，這很完美。有了這個，他就會變很亮！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80516] = {title = "除掉首領", objective = "殺死鬚鞭頭目。", description = "那個狗頭人還懂蠻多的。史奎特說鬚鞭頭目把自己的一群蜘蛛養在附近的洞穴裡。別擔心，我會打頭陣。\n\n來吧，我們要擊敗的可是個頭目。", progress = nil, completion = "你回來了！貝魯德自己回來。史奎特好擔心。\n\n成功了吧？很好。陰齒幫沒有頭目也撐不久了。", rewards = "您會收到：\n\n史奎特的手工輕鞋史奎特的手工手套史奎特的手工護肩史奎特的手工束腰共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][80517] = {title = "追本溯源", objective = "在深爐魔像廠外面與布琳瑟和達格蘭會合。", description = "<吉吉已經準備好要回去深爐魔像廠了。>", progress = nil, completion = "很好，你來了。&lt;name&gt;，希望你準備好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80558] = {title = "不入虎穴", objective = "在姆瑪爾向哥布林打探消息。", description = "這些鼴鼠人待在地下有很長一段時間了…長到讓他們足以建立一座村莊與奈幽蟲族交易。某些鼴鼠人還可以在那座龐大的奈幽城市裡貿易！\n\n那些哥布林？他們是風險投資公司的人。如果阿努巴札爾將軍很常跟他們打交道的話，也難怪他會懷疑我了。\n\n他們到底大老遠跑來這下面做什麼？來打聽是什麼原因讓他們來這裡的吧。", progress = nil, completion = "雖然他們很冒失，但至少還願意跟你談。或許你可以說服他們一起合作對雙方都有好處。\n\n可以做點…交易。他們很欣賞這種做法。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80562] = {title = "綻放的喜悅", objective = "在真菌法師洞窟收集20朵永繁菌。", description = "只有少數的聖光追隨者敢嘗試我打算要做的這道菜。它結合了傳統帝國香料和附近禁止採摘的真菌花。\n\n這道菜會取悅你的味蕾，並讓人回想起聖落之地遠征隊成立時的探險精神。\n\n請前往附近的真菌法師洞窟，採摘我需要的花。", progress = "你找到所有的材料了嗎？", completion = "現在魔法奏效了。請親自試試這個作品。", rewards = "您會收到：\n\n暗莖燉肉燈火者補給包共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][80563] = {title = "同調工具", objective = "找到一個調節水晶。", description = "暴露在黑血之後，奈幽蟲族一定有什麼方法可以淨化自己。如果沒有的話，他們根本沒辦法在採收行動中取得如此巨大的成功。\n\n如果有必要的話，我可以輕鬆地重拾這個現實的和諧來恢復我的心智。但對你和哈南來說，最好還是先知道他們是怎麼做的。\n\n不過，如果你不介意自己的意識永遠被分裂到兩個現實之間的風險…我們可以不用這麼麻煩。", progress = "如此近距離接觸黑血，奈幽蟲族身上一定有東西來淨化他們的心靈。", completion = "調節水晶？真有意思。\n\n不過，我並不覺得這個解決方案有多出色。畢竟這個麻煩是他們自找的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80564] = {title = "野外研究", objective = "調查黑血採收場。", description = "奈幽蟲族正在採收附近的黑血。\n\n如果放任不管，挖掘地脈所造成的腐化就會向外擴散。在腐化吞噬一切之前，都會持續下去。\n\n我並不打算坐視不理，任憑它污染樹根。我正試著學習並理解他們的做法…以便一出手就能直擊要害。\n\n歡迎你加入我的行列。\n\n當然，你應該也不想看到你的世界被滲出的黑血淹沒吧。", progress = nil, completion = "在這一切腐化的中心點，我聽見有個聲音在呼喚我。就像有人在我腦海裡打鼓一樣。\n\n我根本忽視不了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80565] = {title = "迴響反衝", objective = "將哈南從洞穴中的廢棄收割場帶回來。", description = "我原本不打算…\n\n<歐薇娜瞇起雙眼。>\n\n抓住他，<name>。你也曾暴露在黑血中。不過哈南受到的影響更大。\n\n他進入了非表象之境，在黑血的影響下，他的心靈落入那個肉眼無法看到的領域。無論他沉淪到多深的地方，你都必須找到他，把他帶回來。\n\n我會啟動奈幽淨化裝置來接應你們。\n\n千萬別在那個變異狀態下失去自我。", progress = nil, completion = "我的頭…好痛。一切都好模糊，而且…幫幫我，拜託！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80566] = {title = "四面楚歌", objective = "找到蜘蛛並殺了牠們。", description = "<哈南幾乎毫無反應，形體也變得更加虛幻，在非表象之境沉淪得比你還深。>\n\n有些罐子爆開…蜘蛛隨即出現。\n\n殺死…殺死蜘蛛！", progress = nil, completion = "嗯。我發現你似乎很擅長絕處逢生。我會記住你的這個優點。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80567] = {title = "恢復之歌", objective = "使用和諧樂器。", description = "<歐薇娜看到哈南時，鬆了一口氣，但似乎並未停下手邊的工作。>\n\n對於你在那個洞穴中的發現，我其實一點都不意外。奈幽蟲族被困在非表象之境，困在怪物和瘋狂充斥的國度中…\n\n我很想同情他們，但那是他們自找的。\n\n但你必須轉換回來，不能讓黑血對你心靈的影響變得太強大。", progress = nil, completion = "她不可以這樣一直跑掉！我們其他人跟著她來這裡，本來就是不情不願，而且我們從沒同意…\n\n&lt;哈南嘆息。&gt;\n\n不對，我們很清楚跟著她會出什麼事，會有…什麼後果。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80568] = {title = "不留痕跡", objective = "將10個魔法蹤跡收入哈南的鐮刀中。", description = "我必須去確認她平安無事。我在那個洞穴中看到的景象…要是她更敏感一點…\n\n<哈南幾乎要叫出聲來。>\n\n不過，她在外面製造混亂，吸引注意力，留下足跡，讓外來者找到她！找到我們。\n\n我們原本應該保持低調，不被發現。偽裝好自己，盡可能隱藏在我們的其他形態下。\n\n我很不想請你幫這個忙，可是，在我去找她的時候，你可以用我的鐮刀幫忙滅證嗎？", progress = nil, completion = "跟外來者說話是一大禁忌，不過…你幫了我不少忙。\n\n謝謝你幫我分憂解勞。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80569] = {title = "和平手段", objective = "殺死採收看守蜂伊茲提拉。", description = "我知道我無法阻止歐薇娜到下面去，引起別人注意到我們的存在。\n\n可是…也許我們可以阻止我們存在的消息擴散。\n\n找到負責這個採收場的人。然後…採取一切必要行動，確保他們無法散播消息。", progress = nil, completion = "我必須承認，我很高興有你跟我們一起處理這整件事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80570] = {title = "制止洪流", objective = "摧毀8個吸收器。", description = "他們真的理解自己在做什麼嗎？\n\n<歐薇娜齜牙咧嘴，幾乎在低吼。>\n\n盡你所能摧毀越多吸取器越好。打破燈泡、折斷外肢、燒毀殘骸。\n\n我們無法阻止他們全部人，目前還不行。但搞點破壞可以遏制我的怒火。", progress = nil, completion = "他們已經造成了這麼多破壞。曾經住在這裡的生物、曾經欣欣向榮的土地…\n\n要是我們無法阻止他們，我們就必須展開報復，讓他們為造成無法修補的破壞付出代價。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80571] = {title = "解讀雜音", objective = "在非表象之境從不諧敵人身上收集10個不諧精華。", description = "這比我想的還糟。彷彿他們在餵養腐化。鼓勵它。失諧變得越來越大聲…\n\n<歐薇娜似乎有點動搖，但沒有氣餒。>\n\n我幾乎聽不到其他聲音。好像有人在敲我的頭。我…我必須知道這片土地到底淪落到什麼地步。\n\n<name>幫我從非表象之境帶個東西回來。", progress = "奈幽蟲族對這地方做了什麼？", completion = "這不對勁，這全部都不對勁。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80572] = {title = "不諧手段", objective = "需要獲得50層非表象轉移，並從迷失在非表象之境中的精英敵人身上收集3個樣本。\n\n除了摧毀抽取器，站在黑血池中也可以獲得非表象轉移。然而，這樣做的話，層數增加的速度會非常快，要小心。", description = "我再也看不下去了。我必須行動。\n\n<name>，你先前曾從非表象之境活著回來。現在我們必須一起進去那裡。我必須親眼看看，才能說服自己相信這個邪惡的地方真的無藥可救了。\n\n我們會盡可能殺死敵人，尋找我們仍能讓這片土地復原的一絲希望。", progress = "哈南的擔憂並非空穴來風。\n\n但我無法對腐化視而不見，就此袖手旁觀。", completion = "&lt;歐薇娜的聲音因憤怒而變得低沉，但你可以從她的眼神中看見心碎。&gt;\n\n這個地方真的腐化得太嚴重了。對於他們造成的破壞，我們無計可施。", rewards = "您會收到：\n\n織絲者(惡名值)卡吉卡吉"}
MultiLanguageQuestData['tw'][80573] = {title = "隔牆有耳：豐厚的戰利品", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80576] = {title = "失去聽眾", objective = "找出布倫諾克。", description = "真討厭！\n\n布倫諾克跟我正在前往影脈營地的路上，要去舉行一場朗誦儀式。我們遭到了蠍子的攻擊。現在搬運車的齒輪裡卡著一根蠍子的毒刺，然後布倫諾克還跑不見了。\n\n我在修搬運車的時候，他說要去活動一下筋骨，可是他已經離開一陣子了。我需要讓機械再次動起來，你可以幫我找他嗎？", progress = nil, completion = "你不明白，我本來打算離開鳴響深淵的。但在找到我的書之前我可不能走！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80577] = {title = "準備朗誦", objective = "準備朗誦場地。", description = "每年一次，布倫諾克跟我都會踏上穿越鳴響深淵的漫漫長路。\n\n我們會在每個哨站停留，而布倫諾克會跟居民講述一個歷史故事。就算居民忘記，他們也能指望他會幫忙記得。\n\n準備儀式場地是我的責任。你可以跟我一起來嗎？我需要幫忙。", progress = "布倫諾克通常都對朗誦感到很期待。", completion = "謝謝你，時機來臨的時候，希望你可以加入我們的朗誦儀式。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80578] = {title = "平凡的服裝", objective = "找到一套備用的礦工服。", description = "在朗誦後我要開溜。要消失在一群享受燼釀的土靈之中很容易。\n\n但我出城時不能讓人認出來。我不希望有人來阻止我，或是更糟的狀況：覺得我在違背我的誓言。直接消失比較好。\n\n要是你可以幫我找一套備用的礦工服裝的話，我就可以在不引來注意的情況下離開了。", progress = "你找到它們了嗎？", completion = "謝謝你，穿上這些就沒人能認出我了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80592] = {title = "締結合約", objective = "選擇一個斷裂絲線合約。", description = "我們來更新你的合約吧。\n\n記住，你一次只能跟其中一組斷裂絲線建立合約。不過這些合約是暫時的，所以你會有很多機會可以向全部三組的人證明你的實力。", progress = nil, completion = "願你選擇的贊助者為你提供支持，如同你支持他們一樣。", rewards = nil}
MultiLanguageQuestData['tw'][80593] = {title = "嚐一口餘燼", objective = "將酒桶裝滿燼釀蜜酒。", description = "現在我們只剩下最後一樣東西。少了蜜酒的朗誦儀式就不是完整的儀式了。\n\n然而，守爐人哲克跟我說，最近的幾批燼釀蜜酒都還沒有到貨。看來轟隆荒地當地的剝石怪很喜歡喝，把貨物都搶走了。\n\n來，把這個備用酒桶拿去。看看能不能從剝石怪那邊取回一些。", progress = nil, completion = "謝謝你，礦工會很感激的，希望剝石怪沒有那麼難應付。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80670] = {title = "織絲者之眼", objective = "在阿茲-卡罕特繼續協助織絲者。", description = "織絲者的許多眼線潛伏在城市各處，盡可能地在收集關於安蘇芮克的陰謀的情報。\n\n不過，情報並不足以扭轉面對蘇芮基部隊的情勢。織絲者需要願意把手弄髒的人。\n\n我猜你很幸運吧。", progress = nil, completion = "你很有製造麻煩的天分！非常好！\n\n收下這些！", rewards = "您會收到：\n\n\n\n等級 76–80織絲者的賞賜\n\n等級 70–80織絲者的賞賜織絲者(惡名值)卡吉青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][80671] = {title = "將軍之刃", objective = "在阿茲-卡罕特繼續協助將軍。", description = "就連現在，阿努巴札爾將軍的部隊也在不眠不休地工作，以確保阿茲-卡罕特的安全。\n\n安蘇芮克的勢力延伸到她領地的每一個角落。將軍希望能降低她的軍事權威。如果我們消耗她的資源，那或許就能找到襲擊的機會。", progress = nil, completion = "你活著回來了，而阿努巴札爾的敵人卻沒有。\n\n這足以證明你的價值！", rewards = "您會收到：\n\n\n\n等級 73–80將軍的戰爭寶箱\n\n等級 70–80將軍的戰爭寶箱將軍(惡名值)卡吉青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][80672] = {title = "輔臣之手", objective = "在阿茲-卡罕特繼續協助輔臣。", description = "輔臣就連現在都在努力，在阿茲-卡罕特的精英之間散播我們陰謀的影響力。不過，考慮到他的職位，他能提供的直接支援很有限。\n\n這就是你派上用場的地方。你日漸響亮的名聲比你還要遠播，你可以去輔臣到不了的地方。要小心別被吃了，好嗎？", progress = nil, completion = "多虧你的努力，輔臣離與敵人平起平坐的目標又靠近了一步。\n\n為此，感謝是必要的。", rewards = "您會收到：\n\n\n\n等級 74–80輔臣的資金\n\n等級 70–80真菌花誘滴草錐頭草祝綻花阿拉索之矛鉍礦亞基岩鐵爪礦風暴充能皮革幽影甲殼織者布輔臣的資金輔臣(惡名值)卡吉青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][80673] = {title = "跑道驚魂", objective = "飛行撞死或殺死25隻蛾。", description = "你好。\n\n我和麥麥在例行的點燃工作當中，通常會順便清理這一帶的天空。如果我們不消滅這裡的蛾，牠們就會開始入侵空中碼頭，在飛船的機件中產卵。\n\n不湊巧的是，我們現在精神不太好。你可以幫我們一把嗎？牠們相當脆弱，只要高速飛過去，就能讓牠們支離破碎。不然，你也可以用老方法，直接拍死牠們。", progress = nil, completion = "殺了一隻，就又蹦出四隻。不過，還是有幫助。剩下的就交給我們處理。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80676] = {title = "重組記憶", objective = "收集100頁布倫諾克之書的缺失的頁面。", description = "我的誓言是成為一名編撰者。我負責收集並講述我們族人的故事。\n\n<布倫諾克嘆氣。>\n\n要是一個人從沒經歷過故事裡的事，那他講的故事還有寓意嗎？我從來沒有去冒險過。我不想改寫這些前人託付給我的故事。\n\n所以，我開始把它們寫在一本書裡，這本書我就藏在這。每次我們回到影脈營地時，我都會寫下更多故事。\n\n我本來想要離開，把書傳下去的，但蠍子把它搶走了。拜託了，請在牠們拿那些書頁築巢前把它們找回來。", progress = "成千的故事，現在它們大概在某隻野獸的窩裡…", completion = "以泰坦之名啊，感謝你！要是我遺失了這些書頁，我都不知道我該怎麼辦才好。\n\n現在我就可以安心離開，不會背棄我的誓言了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80677] = {title = "灼熱火光", objective = "點燃15顆飛蛾卵。", description = "不管我們拍死多少隻蛾，要是不處理掉牠們的卵，牠們永遠都會成為問題。\n\n帶著這把火器，用它點燃泥潭樹上的卵。", progress = nil, completion = "你以為牠們會得到教訓，離開這裡。但牠們卻一來再來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80678] = {title = "失去的時間", objective = "找到6個遺失的紀念物。", description = "現在工作做完了…有件事我一定會做，那就是在這條路上閒晃，尋找從碼頭掉下來的好東西。當貨物被搬上船的時候，比較小的物品可能會掉下來。有時，人在生氣或是許願的時候也會亂丟東西。\n\n但是有些東西可能具有紀念價值，失去那些東西就等於失去了心中珍貴的回憶。要是你能幫我找找，我會非常感激。", progress = nil, completion = "真是大豐收。帶一些走吧。也許你能找到它們的主人。", rewards = "您會收到：\n\n暗淡羅盤玩偶山貓斷裂的手鐲"}
MultiLanguageQuestData['tw'][80679] = {title = "填充山貓玩具", objective = "你背包裡的東西看起來很眼熟…", description = nil, progress = "你背包裡的東西看起來很眼熟…", completion = "瘦巴巴先生！我以為我再也看不到你了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80680] = {title = "晦暗羅盤", objective = "<汙濁泥沼的羅盤上的名字與公墓墓碑碑文裡的名字相同。>", description = nil, progress = "<汙濁泥沼的羅盤上的名字與公墓墓碑碑文裡的名字相同。>", completion = "&lt;整個世界無比安靜，除了遠方傳來的飛船嗡鳴聲。\n\n儘管經歷長時間的風吹雨打，指針依然指向巴雷達爾。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80681] = {title = "斷裂的手鐲", objective = "你帶了什麼過來？", description = nil, progress = "你帶了什麼過來？", completion = "那是…\n\n&lt;琪菈小心翼翼將手鐲放在手掌上。&gt;\n\n真不敢相信。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80682] = {title = "最後一個故事", objective = "參加朗誦。", description = "好，時候到了。我要在礦坑入口舉辦朗誦儀式。歡迎你來參加，但不要有一定要留下來的壓力。\n\n我會把我的書留下來讓海梅茲找到。她會妥善利用它的。\n\n儀式結束後，我想要好好道別。跟我在城外的橋邊會面吧。我會在朗誦後到那裡去。", progress = nil, completion = "我就知道布倫諾克怪怪的。然後其中一個礦工提到說，你借了一套備用的衣服。這點加上他奇怪的情緒，嗯，並不難猜出他打算離開。\n\n不過我以為他會走這邊。你有看到他嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][80684] = {title = "輕輕搖晃過的禮物", objective = "這個禮物看起來好像已經被稍微搖晃了幾次。上面的標籤寫著：\n\n送給最特別的<race>德魯伊。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n輕輕搖晃過的禮物"}
MultiLanguageQuestData['tw'][80685] = {title = "冬幕節禮物", objective = "禮物上的小標籤寫著：\n\n佳節愉快，<name>！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n冬幕節禮物"}
MultiLanguageQuestData['tw'][80689] = {title = "照顧歐斯加祖", objective = "在爍霧瀑布與芭姿瓦菈會面。", description = "交辦任務完成！我下次例行巡邏的時候會再來看看這些夥伴。\n\n我今天還有一個土靈必須照顧。他……他對我來說非常特別。\n\n你是一個特別體貼的同僚，所以我想要帶你去看他。我們往西邊走一點吧，靠近瀑布那裡。", progress = nil, completion = "你來了！\n\n&lt;她看向她身邊的土靈伸出的手，並嘆一口氣。&gt;\n\n我承認，我在這裡的發現讓我很憂慮。你的到來安慰了我。", rewards = "您會收到：\n\n"}
