MultiLanguageQuestData['tw'][81651] = {title = "探究者的探究指南", objective = "抵達陷坑和真菌法師洞窟。你好！想要在這個區域進行一些探究嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", description = "你好！想要在這個區域進行一些探究嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
