MultiLanguageQuestData['tw'][81748] = {title = "協助奪日者先鋒軍", objective = "我的斥候回報了敵人有動靜。你有任何能幫助我們部隊的物資嗎？", description = nil, progress = "我的斥候回報了敵人有動靜。你有任何能幫助我們部隊的物資嗎？", completion = "非常好，我們應該能展開反擊了。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][81749] = {title = "協助祈倫托先遣軍", objective = "不流點血，談何勝利。<class>，你是來幫忙的嗎？", description = nil, progress = "不流點血，談何勝利。<class>，你是來幫忙的嗎？", completion = "我會好好保管的。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][81750] = {title = "雲霧農場", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][81751] = {title = "火焰與寶石", objective = "從甦醒機械取得覺醒齒輪和鳴響寶石。", description = "這是什麼？引火盒？\n\n我聽說過這些阿拉希裝置，可是這是我第一次把它拿在手上。它比我想像的還小…\n\n你說升級了？哈！這我們也辦得到。下次我們在甦醒機械時，好好留意一下覺醒齒輪和鳴響寶石。", progress = "你幫我找到那些東西了嗎？", completion = "你找到了！讚嘆齒輪，磨亮裝備，看看我們能用你這個神奇的小玩意兒做些什麼吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81767] = {title = "搜刮廢棄物！", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][81793] = {title = "戰爭火花：多恩島", objective = "在戰爭模式下，於多恩島收集100個戰爭火花。", description = "強大的生物在多恩島各地作亂。\n\n過去那邊，清除牠們！", progress = "開始的最佳時機就是現在。", completion = "我們終於可以不受阻礙地繼續站哨了。感激不盡。", rewards = "您會收到：\n\n血腥代幣榮譽點數征服點數共鳴水晶"}
MultiLanguageQuestData['tw'][81794] = {title = "戰爭火花：鳴響深淵", objective = "在戰爭模式下，於鳴響深淵收集100個戰爭火花。", description = "看不見的勢力襲捲了土靈的多個哨站。\n\n找出他們，淨化深淵。", progress = "收復得如何？", completion = "你在深淵中活得很好！", rewards = "您會收到：\n\n血腥代幣榮譽點數征服點數共鳴水晶"}
MultiLanguageQuestData['tw'][81795] = {title = "戰爭火花：聖落之地", objective = "在戰爭模式下，於聖落之地收集100個戰爭火花。", description = "地下的光芒難以捉摸，不過只要你能掌握訣竅，它可以在黑暗中拯救你的性命。\n\n出發吧。前往聖落之地，把你的力量借給阿拉希人。", progress = "小心那片黑暗。", completion = "多虧了你，阿拉希人可以享有片刻的安寧。", rewards = "您會收到：\n\n血腥代幣榮譽點數征服點數共鳴水晶"}
MultiLanguageQuestData['tw'][81796] = {title = "戰爭火花：阿茲-卡罕特", objective = "在戰爭模式下，於阿茲-卡罕特收集100個戰爭火花。", description = "我們接收到阿茲-卡罕特傳來的奇怪數據。去這些地點調查，記得保持警戒。", progress = nil, completion = "你居然活下來了？而且還保有四肢健全。做得好。", rewards = "您會收到：\n\n血腥代幣榮譽點數征服點數織絲者(惡名值)"}
MultiLanguageQuestData['tw'][81797] = {title = "定向偵察", objective = "前往無日海岸，殺死三個寇拜斯塑影者。", description = "如果你在聖落之地待得夠久，相信你一定見識過寇拜斯的邪惡魔法。報告指出，他們持續進化的幻象在阿拉希軍隊內部引發激烈的爭辯。\n\n你的外來觀點正好是我需要的。前往無日海岸，殺死幾隻寇拜斯幻象刺客，然後回報你的發現。他們很常躲在陰影中。", progress = nil, completion = "他們偽裝成阿拉希平民的幻象似乎越來越有說服力了。我很難理解，這種邪惡又笨拙的生物為何能將阿拉希人的一舉一動模仿得唯妙唯肖。\n\n然而，這一切都與我們目前對寇拜斯的了解極為吻合。我們會好好善用你的報告。謝謝你，外來者。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81798] = {title = "回去找茉艾拉", objective = "回去土靈工作場找茉艾拉。", description = "代言者布琳瑟的衝動讓她失去了平常的判斷力。\n\n你最好回去找你的戰友，讓他們知道她的意圖！", progress = nil, completion = "&lt;name&gt;！你回來了。我們一起終結這場鬧劇吧。", rewards = "您會收到：\n\n"}
