MultiLanguageQuestData['tw'][81869] = {title = "用蜜蜂點更多火", objective = "在火渣林從超載的工蟲身上收集10份純淨火焰蜂蜜。", description = "用火焰做東西需要燃燒燃料，以便供應純粹又持久的火力。其中，火渣林蜜蜂製造的蜂蜜特別好用！元素火焰的來源，完全有機，無污染。\n\n我一直都很想取得這種蜂蜜，可是都沒有機會去收集。\n\n把我的採集裝置拿去，收集蜂蜜來完成我們的目標吧。我們會把它注入你的引火盒中。要小心行動，因為有些土靈把這些蜜蜂視為神聖的生物。", progress = "你取得蜂蜜了嗎？", completion = "真是香甜，就連現在都有火焰冒出來。這會是你的引火盒完美的燃料！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81886] = {title = "為了聯盟", objective = "在駐暴風城大使館與穆爾加德大使見面。", description = "這是有史以來第一次，我們能夠親自探索和體驗外面的世界。\n\n一個被稱為聯盟的外島陣營前來幫助我們的親族。堅毅的聯盟展現出崇高的英勇與睿智，並向我們的族人伸出了援手。\n\n你願意成為第一個接納並造訪他們的土地、學習他們的歷史並與他們的人民同行的土靈嗎？\n\n如果那條路在呼喚著你，那麼我希望你會回來分享那些經驗，並向土靈展示世界能為我們帶來什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81887] = {title = "陌生人在陌生地", objective = "在暴風城與克羅米交談。", description = "歡迎來到暴風城，<race>。我邀請你盡情探索我們這座美好的城市。嘿，你看起來很擅長欣賞細膩的石造工藝！在暴風城有很多令人讚嘆的石造建築和城牆。\n\n啊，但你之後再去吧。有頭青銅龍說她想見你。她就在附近的樹下，而且竟然坐在沙漏上！\n\n然後，有名特使正等著歡迎你造訪本市。聽起來你今天會很忙喔！\n\n祝你在這一切順利，<name>！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n套裝：土靈黃銅戰衣\n\n下列法術會施放在您身上：\n\nRe-Animate Visual\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][81888] = {title = "為了部落", objective = "在駐奧格瑪大使館與黑衛大使見面。", description = "這是有史以來第一次，我們能夠親自探索和體驗外面的世界。\n\n一個被稱為部落的外島陣營前來幫助我們的親族。榮耀的部落展現出強韌的精神與力量，並向我們的族人伸出了援手。\n\n你願意成為第一個前往族人未踏之地的土靈嗎？行走於他們的領土之上，聆聽他們的歌謠並向他們的人民學習？\n\n如果那條路在呼喚著你，那麼我希望你會回來分享那些經驗，並向土靈展示世界能為我們帶來什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81889] = {title = "陌生人在陌生地", objective = "與克羅米交談。", description = "嗨。我是黑衛大使。\n\n我很榮幸歡迎你來奧格瑪，<race>。\n\n<黑衛露出了難以讓人放心的笑容。>\n\n你即將踏上一生中最精彩的冒險旅程，我向你保證…呃…\n\n搞什麼啊？我一整天都在用相同的台詞打招呼。我受夠了。\n\n去沙漏頂端那邊找克羅米說話，然後去找你的特使交談。快去吧。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n套裝：土靈黃銅戰衣\n\n下列法術會施放在您身上：\n\nRe-Animate Visual\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][81890] = {title = "未完成的要求", objective = "在絲線區與桑姆拉薩會面。", description = "聽說絲線區的居民遇到了麻煩，好像是跟一群晉升的蒼白鞭絲者有關。\n\n對首都的居民來說，新的居住區應該代表全新的開始，至少女王是這麼說的。實際上，卻是她用來進一步控制那些潛在異議份子的手段。\n\n去見見我的助手桑姆拉薩。我派她先去那裡收集情報。她可以告訴你更多細節。", progress = nil, completion = "你一定是輔臣派來的幫手。歡迎來到絲線區。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81896] = {title = "全新改良", objective = "接受庫達斯的改良版引火盒。", description = "我已經完成改裝了。我必須說，這是我最好的作品之一！\n\n雖然它的設計很不起眼，但在齒輪油跟我的苦心加持下，我已經把它變成了最精明的火焰崇拜者都會很欣賞的裝置。\n\n如果他們想知道我是怎麼辦到的，就讓他們來找我吧。", progress = nil, completion = "這個引火盒的火焰現在會燒得更旺！", rewards = "您會收到：\n\n強化引火盒"}
MultiLanguageQuestData['tw'][81906] = {title = "蛛網的耳語", objective = "在阿茲-卡罕特的地洞區與塔那克會面。", description = "嘿！嘿！\n\n<女孩揮手，吸引你的注意，另一隻手則緊抓著一張紙。>\n\n你絕對不敢相信，但我找到了最可愛、最毛茸茸的小狗！還有一個鈴鐺！就在脖子上！\n\n牠給了我這個，要我交給你。快拿去，我要去抓那隻小狗！\n\n<書信上有著娟秀的字跡，要你去阿茲-卡罕特一趟。>", progress = nil, completion = "看來我的訊息傳到你手上了。你…並不像我想像的那般魁梧，但謠傳你的實力無人能敵。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81908] = {title = "黑暗中的烈焰", objective = "在深淵堡的多個容器中找出8個不明引火盒與艾爾里克的腐化引火盒。", description = "深淵堡中藏著一個引火盒，它曾屬於已故的艾爾里克‧雷德。\n\n這個物品散發出強大的腐化能量。許多奈幽蟲族跟它朝夕相處，深受它的影響。\n\n你的任務是取回那個引火盒，把它交給我。保險起見，把你找到的引火盒都帶回來，我們會全部銷毀，以防萬一。", progress = "你找到引火盒了嗎？", completion = "快點，把它交給我，這東西可不能讓其他人看見！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81909] = {title = "絕對的力量", objective = "與塔那克討論如何銷毀引火盒。", description = "這個物品給我的黑暗誘惑已超越我原本的預期。我可以感覺到有一股力量在我體內流竄。\n\n我們必須發掘出其中的奧秘。\n\n但公開討論這件事可不是明智之舉。跟我到裡面來進一步討論吧。", progress = "你拿著的那個是什麼東西？", completion = "真教人意外。你到底在哪裡找到它的？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81910] = {title = "重大的責任", objective = "收下引火盒。", description = "看到這般腐化的物品還真讓人感到不安。\n\n儘管這個引火盒中充滿了黑暗的力量，但其中仍留有一點聖焰的餘光，試著想掙脫束縛。我不會摧毀那道餘光，勇士。\n\n但我也不敢再留著這個物品了。\n\n也許你純淨的靈魂能夠抵禦其中的黑暗。拜託你，<name>，把它帶走。保護這個純潔的餘光，將束縛它的黑暗魔法淨化掉，幫它重獲自由。", progress = nil, completion = "現在我把看顧與保護這希望餘燼的重責大任交付於你。", rewards = "您會收到：\n\n晦暗引火盒"}
MultiLanguageQuestData['tw'][81912] = {title = "飛行訓練中級班", objective = "協助庫德蘭訓練新兵的空中瞄準。", description = "別以為我沒注意到那些禿鼻鴉會吐閃電。絕對比丟釘錘厲害。不過要是風暴飛騎打不中他們的戰鬥目標，那就沒有意義了。\n\n我們來測試他們的準頭吧。我這邊有一些地精裝置，會發射簡單的練習標靶。帶蕭班德雷到外頭去，讓他們見識一下你的實力！", progress = nil, completion = "這樣才對嘛！打中了不少投射標靶。不過我們真正需要的是一個會動的目標。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][81913] = {title = "飛行訓練高級班", objective = "協助庫德蘭訓練新兵的空中戰鬥。", description = "這些新兵似乎願意接受挑戰。我們幫他們找個更刺激的目標吧。\n\n我在海岸邊看到一個可憐的巨人，有一群飛行惡魔在纏著他。我們去看看這些禿鼻鴉能不能把他們的翅膀射下來，給巨人一個喘息空間吧。\n\n你跟蕭班德雷是其他人的好榜樣。繼續保持！", progress = nil, completion = "訓練很順利對吧？很抱歉我沒能在場，我有一件非做不可的事情。", rewards = "您會收到：\n\n風暴飛騎飛行徽章勇氣石"}
MultiLanguageQuestData['tw'][81914] = {title = "達歐茲坦", objective = "前往達歐茲坦。", description = "我很愛風暴禿鼻鴉。照顧牠們是我的工作，牠們也是我唯一熟悉的事物。儘管如此，有關牠們的一些問題，我到現在都沒有解答。\n\n貝格姆…那個風暴守衛貝格姆…根本就是個專家。只要有機會，我就會問他關於牠們的事。他也會盡全力與我分享他所知道的。\n\n他曾經告訴我在達歐茲坦召喚禿鼻鴉的事。那是一個古老的風暴飛騎哨站，其歷史比風暴駐營還要悠久。如果想更加瞭解風暴禿鼻鴉的話，你可以去那裡看看。", progress = nil, completion = "所以貝格姆離開了。現在其他人也來了。你要召喚更多禿鼻鴉，對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81915] = {title = "棲息之地", objective = "返回達歐茲坦。", description = "<name>，你已經幫了我們很大的忙，我們會以你為榜樣，繼續努力下去。\n\n你應該回達歐茲坦去，關心一下你招募的風暴飛騎新人。你在這裡展現出來的勤奮一定也能讓他們獲益無窮。\n\n而且你也可以擺脫這兩個裝模作樣的傢伙。<name>，我真忌妒你…", progress = nil, completion = "看到你回來真好。地面部隊的事情進行得順利嗎？\n\n我們正準備要開始飛行訓練。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81928] = {title = "人民之聲", objective = "與3名絲線區居民談話。", description = "你可能已經聽說了，對於絲線區的居民來說，事情完全跟他們想的不一樣。蒼白鞭絲者一直在密切監控這裡的居民。\n\n我還來不及收集太多情報，就因為形跡可疑，被一個晉升者趕了出去。你是個新面孔，去絲線區四處走走，跟居民搭話，看看你能不能找到辦法幫助他們。\n\n另外，去找鍊金師塔爾貝克斯吧。我聽說過他的大名。他或許能提供有用的情報。", progress = nil, completion = "啊，你一定聽說我的困擾了，朋友。你應該能幫上忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81929] = {title = "計畫如下", objective = "在法林說明她計畫的同時協助她。", description = "<name>，是時候來對付奈幽蟲族大軍了。哲卡爾將軍在東部集結了龐大勢力。他想突破城牆，入侵聖落之地。時間所剩無幾了。\n\n我們的勢力不足以正面迎擊。為此，織絲者派了加茲魯維來協助我們。為了拯救我的人民，我願意付出一切代價。\n\n如果有機會的話，到那裡之後，我想了結一段私人恩怨。", progress = "就我所知，不是所有奈幽蟲族都是壞人。我只希望我們三人足以應付。", completion = "我想我們三個人就夠了。那就豁出去了吧？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][81930] = {title = "地心之戰", objective = "前往希利蘇斯與珍娜探討出現在艾澤拉斯各地的幻象。", description = "艾澤拉斯各地的人們都看到了「璀璨之歌」幻象。這很可能是某種警訊。\n\n到希利蘇斯找我。說不定艾澤拉斯的代言者可以解讀這個警訊所代表的意義。", progress = nil, completion = "人都到了。很好。來查清璀璨之歌到底想告訴我們什麼吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81945] = {title = "前往阿拉希臨終之地", objective = "在阿拉希臨終之地與法林和加茲魯維會合。", description = "我們在東邊的阿拉希臨終之地外圍重新集結。\n\n他們的部隊就快做好出擊準備，時間不多了，<name>。", progress = nil, completion = "你成功了。現在就來看看我們能不能擊敗這些奈幽蟲族，並拯救聖落之地。\n\n我已經可以想像成功的那一刻了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81950] = {title = "爆爆點心！", objective = "放置蟲子點心，引誘載炸彈的甲蟲摧毀奈幽弩砲。", description = "如果我們要阻止這場入侵，我們就需要解決掉對方的重火力。在這個情況下，重火力指的就是弩砲。\n\n記得我叫你去拿蟲子點心嗎？對，我不是隨便叫你拿的。你聽好，這裡的奈幽蟲族用甲蟲來運送炸彈。這些運輸蟲非常喜歡點心。我是說，誰不喜歡呢？\n\n你只要把點心放在弩砲旁邊，炸彈甲蟲就會走上去，然後爆炸！", progress = "這些弩砲不會自己摧毀自己，你知道吧？", completion = "換我來也不可能做得更好了。嗯，大概。好吧，可能性很大。\n\n反正，我們完成了任務，而且只花了滿滿一袋處理過的不明垃圾，可以說是物超所值了，對吧？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][81959] = {title = "收集藥劑", objective = "到低語崖收集8瓶亮色藥劑。", description = "蒼白鞭絲者的確把我的煉金補給品丟下懸崖去了。藥水會給絲線區的居民需要的力量，幫助他們起義。\n\n我需要有人到低語崖下，幫我收集那些還沒破裂的藥水。我是很想自己去，但寇拜斯卻霸佔了懸崖底下，而我也不太會打架。\n\n這對你來說應該是輕輕鬆鬆，沒錯吧？", progress = "寇拜斯真是煩人的東西。我得把我的亮色藥劑拿回來。", completion = "我希望你有拿回我的亮色藥劑，有嗎？少了它們，我就什麼都沒有了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81962] = {title = "往對的方向推一把", objective = "在絲線區附近擊殺10個蒼白鞭絲者。", description = "太棒了！既然你把亮色藥劑取回來了，我要你去絲線區展示它們的效果！\n\n我確信蒼白鞭絲者會來針對你，但我想讓大眾知道，我們不必看他們的臉色。有了一點動力後，我們就有信心起身反抗了。\n\n沒錯，這一定有用！帶著藥水到標記在地圖上的地方後，殺死蒼白鞭絲者吧。我的藥水有居民們一定會愛上的其他效果。", progress = nil, completion = "藥水的效果還真是奇妙，對不對？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81963] = {title = "勞動的果實", objective = "將3瓶亮色藥劑交給絲線區的居民。", description = "你一定表現了一番，對吧？有很多市民們已經下訂單，也等不及想喝下這些藥水了。\n\n我有最後一項任務想交給你。我想讓你帶上這些最新的訂單，然後去交貨。你會接受，對吧？\n\n市民們都已經熱血沸騰。現在也是時候讓蒼白鞭絲者瞧瞧我們的能耐了。若有人膽敢阻止你，你知道該怎麼做。", progress = nil, completion = "幹得好，朋友。市民們已經得到所有資源來對抗蒼白鞭絲者了。", rewards = "您能選擇下列奬勵中的一個：\n\n解放者的黯淡指環絲線區璽戒\n\n您還會收到：\n\n織絲者(惡名值)卡吉"}
MultiLanguageQuestData['tw'][81964] = {title = "鐵匠的命運", objective = "協助法林‧洛薩查出萊頓‧布萊克霍姆的下落。", description = "趁我們還在這裡，我必須查出我的老朋友萊頓‧布萊克霍姆的下落。他以前是聖落之地最厲害的鐵匠，卻在一場奈幽蟲族突襲中被帶走了。我沒能救下他。\n\n我試著找過他，但除了染血的頭盔之外什麼也沒找到。我已經放棄了希望。可是最近，我聽到一個從神禦之牆上被拉下來的生還者提到一個鐵匠的謠言。\n\n那會是萊頓嗎？<name>，你願意幫我嗎？", progress = "謝謝你幫忙這件事，<name>。", completion = "我真不敢相信萊頓真的死了，但是終於知道我親愛的朋友發生了什麼事，這點對我來說很重要。\n\n我們處理完哲卡爾的怪物之後，就會悼念他。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][81965] = {title = "入侵干擾", objective = "在阿拉希臨終之地干擾奈幽蟲族的入侵行動。", description = "儘管我們無法消滅這裡的奈幽蟲族威脅，但至少可以破壞他們的入侵計畫。\n\n有不少機會可以達成這個目標。我們來看看可以造成什麼樣的破壞。", progress = "我們在這裡斬獲的成果越多，聖落之地就會變得越安全。", completion = "暫時足夠了。我們必須定期回來，削弱他們的部隊，直到找到其他辦法為止。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][81966] = {title = "睡得跟石頭一樣沉", objective = "回到達拉然。", description = "勇士，他醒了。請回到達拉然。", progress = nil, completion = "歡迎回來，勇士。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81969] = {title = "真正的結束", objective = "與法林和加茲魯維合作，擊敗名為『碎裂者』蘇瑞塔克的怪物。", description = "我想要紀念我朋友。但首先，我們必須對這個被聖光遺棄的地方打出致命一擊。\n\n聽說哲卡爾將軍最近在監督一個怪物的誕生…一個虛無腐化的畸形奈幽蟲族。偵察報告鎖定了峽谷上方的一個地點。\n\n我們要去把他恐怖的寵物搶走。這樣應該就可以終結他入侵聖落之地的計畫了。至少拖延一陣子。", progress = nil, completion = "謝謝你，&lt;name&gt;。聖落之地的人欠你一個人情。\n\n如果你願意的話，我想請你做最後一件事。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][81976] = {title = "市集，對不對？", objective = "有青銅幣嗎？來市集花掉它吧！\n\n這能讓你抵達那裡。第一個免費！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n諾斯溫的優惠券"}
MultiLanguageQuestData['tw'][81981] = {title = "什麼軍隊？", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81985] = {title = "世界之魂記憶：闢地者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][81990] = {title = "聖光呼喚", objective = "向琪菈‧弗蘭斯壯報到，繼續為其效力。", description = "注意，聖落之地的居民！\n\n為了奪回被暗影籠罩的外圍地區，現在急需支援。\n\n無數家族農場陷入黑暗之中，需要你們的協助，才能點燃聖焰，讓我們的土地再次變得安全。", progress = nil, completion = "很高興能得到你的援助。你所做的一切都有助於重新點燃這些鑰炎！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][81993] = {title = "風暴飛騎的羈絆", objective = "殺死巨龍群島的強大生物，收集50個風暴之魂。", description = "這隻獅鷲獸可不是普通的獅鷲獸。牠就跟風暴一樣難搞。我花了一整天的時間，試著讓牠冷靜下來。\n\n牠讓我想起蠻錘氏族的古老傳說。我們稱牠們為風暴禿鼻鴉。只有鼎鼎有名的獅鷲騎士才能馴服牠們。\n\n如果你能展現你的風暴之魂，牠或許就願意向你敞開心扉。試著在戰鬥中證明你自己。", progress = "我從沒遇過這麼頑固的獅鷲獸！", completion = "你看！牠好像喜歡你。\n\n來，我在風暴禿鼻鴉的鞍具中找到一些裝備。看來非常適合你！而且像你這樣高貴的獅鷲騎士，絕對需要配得上你的行頭。", rewards = "您會學到：\n\n套裝：深淵風暴飛騎裝束\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][81994] = {title = "神聖的連結", objective = "殺死巨龍群島的強大生物，收集500個風暴之魂。", description = "對，那隻風暴禿鼻鴉已經開始喜歡我們了。不過獅鷲騎士和獅鷲獸必須共同經歷許多考驗，羈絆才會越來越深。\n\n你或許擁有風暴之魂，但我們得看看你對它的掌控能力有多高。是時候在實戰中證明你的實力了。", progress = "我覺得這傢伙漸漸開始信任我了。", completion = "哇，太驚人了！你真的已經學會掌控風暴之魂了。果然是位了不起的優秀獅鷲騎士。\n\n不止如此。我送你的那件護甲現在還蘊藏著風暴之心！真有意思…", rewards = "您會學到：\n\n套裝：狂亂風暴飛騎裝束\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][81999] = {title = "新家，新蠟燭！", objective = "在火渣林與破破會面。", description = "破破聽說地表上有巨大的火焰蜂。\n\n火焰蜂會製造火焰蜜蠟，對吧？能不能用火焰蜂的蜜蠟做蠟燭？做出來是怎樣？\n\n破破一定得知道！", progress = nil, completion = "現在只需要想辦法拿到蠟，但不能死……", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82007] = {title = "尾巴的故事", objective = "找到豆豆、肉肉、雷雷和伊雷娜船長。然後把牠們還給阿提卡‧鬚谷。", description = "新生的山貓又不知道跑到哪去了！\n\n那些調皮的小山貓總是喜歡四處搗蛋，一不留神，就會跑得無影無蹤。在壞脾氣失蹤之後，這裡只剩下我和薇絲帕在做事，你的協助會是我們的及時雨！\n\n我知道那些愛搗蛋的小山貓就在這附近。看看你能不能把牠們帶回來。\n\n我會帶一盞燈去山洞、南邊的蜘蛛地盤和北邊的海岸找找。", progress = nil, completion = "如果這些小山貓會說話，牠們一定會說出相當精采的故事！\n\n裡面有一隻好像特別喜歡你。我想你交到一個新朋友了。", rewards = "您會收到：\n\n雷雷"}
MultiLanguageQuestData['tw'][82041] = {title = "巴雷達爾的祝福", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][82042] = {title = "一顆龍石都不放過", objective = "透過擊敗獨特的生物、通過地城與團隊副本、完成世界活動或領取寶箱戰利品來取得50個龍石。然後，和庫佐斯談話，使用龍石來升級一件第4賽季的裝備。", description = "來到沃卓肯真讓人興奮！我和庫佐斯以前從沒來過這裡。一切就跟我們想像的一樣。有些人甚至會自己跑來搭話。他們真的很感謝我們對龍石和紋章的研究。那是每一位研究者的夢想！\n\n所以我又再次需要你幫忙了。你能不能拿到一些龍石和一件新的冒險裝備？然後回到庫佐斯這邊升級？這樣有助於我們在這裡站穩腳步。", progress = nil, completion = "我的朋友！你真的是我的救星。請收下這些謝禮。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82050] = {title = "覺醒紋章，無限可能", objective = "透過擊敗獨特的生物、通過地城與團隊副本、完成世界活動或領取寶箱戰利品來取得15個幼龍覺醒紋章。然後回到沃卓肯找維史康。", description = "我很感謝你的幫忙，現在你可以在這裡輕鬆升級低階裝備了。\n\n當然，相信你已經知道龍石的作用是有限的。你需要覺醒紋章才能升級強大的冒險裝備。這些紋章的功用和龍石很像，入手的管道也非常多元。覺醒紋章共有四個等級，完成的任務越難，獲得的紋章等級就越高。\n\n將15個幼龍覺醒紋章交給我，我們就能幫你進一步升級一些裝備。", progress = nil, completion = "真是太棒了。看到你實力變強，真讓人興奮！當然，這都是為了推進我的研究。不過，你的實力還是成長了！", rewards = "您會收到：\n\n赤紅勇氣石一袋雕刻先驅者紋章"}
MultiLanguageQuestData['tw'][82059] = {title = "覺醒紋章，無限可能", objective = "透過擊敗獨特的生物、通過地城與團隊副本、完成世界活動或領取寶箱戰利品來取得15個幼龍覺醒紋章。然後回到沃卓肯找維史康。", description = "我很感謝你的幫忙，現在你可以在這裡輕鬆升級低階裝備了。\n\n當然，相信你已經知道龍石的作用是有限的。你需要覺醒紋章才能升級強大的冒險裝備。這些紋章的功用和龍石很像，入手的管道也非常多元。覺醒紋章共有四個等級，完成的任務越難，獲得的紋章等級就越高。\n\n將15個幼龍覺醒紋章交給我，我們就能幫你進一步升級一些裝備。", progress = nil, completion = "看到沒？不覺得很神奇嗎？\n\n等我搞清楚如何把陳舊先驅者紋章變成雕刻先驅者紋章，就會馬上通知你。如果參考處理其他紋章的經驗，會需要更多陳舊先驅者紋章才能有所進展。不過把紋章降階？那超簡單的！", rewards = "您會收到：\n\n赤紅勇氣石一袋雕刻先驅者紋章"}
MultiLanguageQuestData['tw'][82088] = {title = "挫敗寇拜斯", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][82120] = {title = "水池清理", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][82121] = {title = "滿足需求", objective = "在阿茲-卡罕特的攻城堡立下阿努巴札爾的軍旗。", description = "我們已經合作有一段時間了，<name>。我希望你能尊重我對戰爭藝術的看法。一如既往，我們有必須遵守的規定，以及不能跨越的界線。\n\n哲卡爾必須死，而且得由我親自動手。那個晉升者無賴成天踐踏對戰爭的理想，玷汙了我們王國的傳承。\n\n我想請你為我做最後一件事。前往敵方城塞，並把這面旗幟設在台階上。我們必須以正確的方法行事。", progress = nil, completion = "就連哲卡爾都不敢忽略一個正式挑戰。\n\n很好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82122] = {title = "宿命的對決", objective = "防止哲卡爾的手下干擾阿努巴札爾。", description = "我不會逞匹夫之勇，<name>。我一點都不認為哲卡爾會保持著榮譽感來迎接這次挑戰。\n\n我們處在敵人的地盤上，身邊都是他的走狗。干擾是一定會有的。\n\n士兵，我給你兩個任務。首先，你必須擋住那些打算中斷決鬥的搗亂者。再來，更重要的是，你不能用武器或法術攻擊哲卡爾本人。\n\n他只能被我的爪子撕碎。", progress = nil, completion = "總算完成了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82123] = {title = "將軍的信念", objective = "將事情經過告知寡婦阿拉克娜依。", description = "<阿努巴札爾劇烈嘔吐。從他脫臼的大口嘔出膿液。>\n\n我的小隊在斷裂絲線的職責還沒結束。你要確實把這裡發生的事回報給織絲者。儘管她很煩人，但她會知道接下來該怎麼做。", progress = nil, completion = "所以，這就是事情的經過。\n\n該死的蠢貨。他是在想什麼？不過…哲卡爾的死對那些忠誠者會是沉重的打擊。儘管阿努巴札爾的腦子不太好，實力倒是不容質疑。\n\n他的後裔會接手他在斷裂絲線的工作，而大家都會記得他是一位優秀的將軍。", rewards = "您會收到：\n\n將軍的珍寶卡吉"}
MultiLanguageQuestData['tw'][82124] = {title = "滅亡的開端", objective = "在晦影市集製造混亂。", description = "在刺殺行動之後，安蘇芮克女王一直都很忙。她對阿茲-卡罕特的控管越來越嚴格，她忠誠的貴族也會協助她執行她的黑暗陰謀。\n\n在女王的授意下，她的兩位最忠誠的貴族紡紗者塔卡茲和阿努巴拉許封鎖了晦影市集。\n\n塔卡茲令人難以忍受的政治宣傳陰謀和阿努巴拉許日漸壯大的軍事行動都很明顯指向一件事：晉升或死亡。\n\n我需要你去晦影市集干擾他們的控制。", progress = nil, completion = "女王鬆懈了，在她眼裡，紡紗者塔卡茲和阿努巴拉許更值得提防。一網打盡。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82125] = {title = "我等間諜", objective = "到地洞區與古烏蘇會合。", description = "地洞區傳來了令人不安的消息。不祥的計畫正在底下的溝渠展開。絲線區的居民正在以令人擔憂的速度消失。\n\n紡紗者塔卡茲和阿努巴拉許低調的程度跟鐵鎚一樣。我不認為這是他們下的手。這是更低調的人所做的事。\n\n我有個線人在地洞區，他的名字是古烏蘇。到地洞區和他會面，調查下面發生了什麼事。", progress = nil, completion = "來幫忙的人差不多也該出現了。你就是輔臣派來的幫手，對嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82126] = {title = "人民的防禦", objective = "在地洞區拯救5個居民。", description = "輔臣一定跟你說了一些細節。地洞區的居民正在失蹤，這點你是知道的。\n\n不過大家在傳的可不只這樣。我們的居民被帶去轉化場，然後就永遠回不來了！\n\n我們必須不計代價阻止這一切。又有更多人被帶走了，但現在救他們還不遲。他們還在地洞區裡。去找出他們並放他們自由吧。", progress = nil, completion = "地洞區的居民欠你一個人情。做得好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82127] = {title = "讓他們成為獵物", objective = "在地洞區擊殺8個挾持者。", description = "這些綁架者正在抓市民，而且地洞區沒有人能阻止他們。我覺得該有人做些什麼了。\n\n他們潛伏在地洞區，覺得自己沒人能看見，但我看得見他們，我們都能看見他們。只是這裡沒有人能反抗他們。這就是你派上用場的地方。\n\n去獵捕這些綁架者，讓他們知道誰才是真正的獵物。", progress = nil, completion = "希望他們在死前受盡折磨。那些叛徒完全不值得同情。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82130] = {title = "攻擊高層", objective = "擊殺挾持大師。", description = "在你離開的時候，我也沒有閒著。\n\n你在地洞區的功績吸引了一個高層的注意。一個包裹在繃帶中的怪人，帶有絕望的味道。\n\n幸好，這個不尋常的怪物正要一路下到地洞區來，調查為什麼他們的綁架者會失蹤。現在是我們出手破壞整個行動的好機會。", progress = nil, completion = "你的豐功偉業一路流傳到這裡。看來你真的做得很好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82133] = {title = "記錄：田野調查手冊版本", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][82141] = {title = "殺死女王", objective = "擊殺安蘇芮克女王。", description = "我確實有預期到女王會想要收緊她對市民的控制，可是強行讓地洞區的人晉升還是太超過了。\n\n安蘇芮克女王墮落的程度比我想的還嚴重。我無法放任她帶領我們的人民走向滅亡。\n\n時機已經成熟。我們必須殺死安蘇芮克女王，並帶領人民走向更光明的未來。不然，誰知道她還會墮落到什麼程度。", progress = nil, completion = "我並不樂意犯下弒君之罪，但我非做不可。", rewards = "您會收到：\n\n附魔符文先驅者紋章虛無之觸勇氣石虛無之觸勇氣石輔臣(惡名值)勇氣石卡吉"}
MultiLanguageQuestData['tw'][82143] = {title = "失諧之路", objective = "到薩里恩排水溝的洞穴外找歐薇娜和哈南。", description = "哈南唯一說對的地方，是我的存在在這裡…是不被允許的。\n\n但是這些腐化回音不斷在我的腦中迴盪，就像是純淨的世界旋律加入了一段混亂和弦。像是一段呼救。\n\n我必須回應那個呼喚。我必須跟隨這段混亂直到它的源頭，找到它的核心，這樣我才有機會知道要怎麼淨化它。\n\n加入我。", progress = nil, completion = "&lt;歐薇娜擔心地看往洞穴的方向。&gt;\n\n當他同意與我同行時…我應該要看好他的。確保不會有壞事發生。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82144] = {title = "在路上", objective = "找出布倫諾克。", description = "這是通往升降梯唯一的路，他現在早該到這裡來了。\n\n除非…他沒有走這條路！他不會想被人看到的。\n\n他不知道深淵會有多危險。我們必須找到他！", progress = nil, completion = "要是他能早點跟我說就好了…那個石腦袋。不過要是他打算離開，他會需要一個嚮導的。我都不知道他自己一個人要怎麼樣好好找路。\n\n他的編年史已經在前往剛達加茲的車上了。他們會好好保管他的故事。至少到他受夠為止。\n\n我的誓言是照顧他，一直都是。如果我把他留在這裡，我就無法履行我的誓言。\n\n謝謝你幫助他。", rewards = "您會收到：\n\n編撰者裹手編撰者肩衛編撰者鍊甲扣環編撰者護脛共鳴水晶深淵集會"}
