MultiLanguageQuestData['tw'][82213] = {title = "蝙蝠要求", objective = "收集8份銬牙葉鼻蝠肉。", description = "在我們赴約之前，我會精選一些重要的貿易商品，不過，要是有人能幫忙收集一些其他物品，我也樂見其成。\n\n最近，我們一直收集不太到聖落之地最好的蝙蝠肉。你可以先幫忙收集一些肉帶到頓內爾的恩典嗎？", progress = "你拿到肉了嗎？", completion = "太棒了。有那些黃蜂在，我們的人都必須守在城牆上，根本分不出更多人手了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82214] = {title = "有人喜歡黃蜂嗎？", objective = "擊殺10隻銬牙黃蜂。", description = "由於黃蜂的入侵，我們一直沒辦法去收集這個地區的資源。\n\n我們光是防守城牆就分身乏術了，沒有多餘人力去解決牠們。要是你可以代勞的話，我們會非常感激。", progress = nil, completion = "謝了，&lt;name&gt;。\n\n我討厭那些東西。說真的，有誰會覺得跟山貓一樣大的黃蜂是個好東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82215] = {title = "一般纖維", objective = "收集5份強韌常春藤纖維。", description = "蘭桎洞窟和尖牙之地生長著一種植物，它的纖維很適合用來製作繩索。因為那些大黃蜂，我們已經很長一段時間沒去採集了，存貨嚴重短缺。\n\n要是你去了那裡，可以順便採集一些嗎？", progress = "這些纖維就跟魔法一樣。用它們製成的繩索既堅固又有韌性。", completion = "也許你的人會對這些纖維感興趣？\n\n它們能做出有始以來最棒的繩索。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82216] = {title = "經濟要求", objective = "在聖落之地的米雷達爾寫一封推薦信。", description = "聽說你來自地表？你見過土靈了嗎？\n\n我們以前曾跟他們貿易，不過，在黑暗日後，我們陸續派了使者過去。我們派去的人卻一去不回。老實說，我們以為他們已經滅絕了。\n\n我打算再次建立交流。我想請你寫封推薦信，以免我們做了一些冒犯他們的事。", progress = "希望這次能順利。我們真的需要更多資源。", completion = "謝謝你，我會派一個信差帶著這個去找土靈。我希望這人可以平安回來。\n\n還有…謝謝你提供跟你的族人貿易的資訊，我希望他們也會加入。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82217] = {title = "地底經濟學", objective = "在頓內爾的恩典協助阿拉希人進行貿易協商。", description = "在黑暗日之後，我們就沒看過土靈，或聽見他們的消息。我並不清楚原因。\n\n我們以前關係不錯。我甚至還把梅里斯當成朋友，雖然是奇怪的朋友。\n\n我們必須讓這件事順利進行。", progress = "我們必須讓這次的貿易協議通過。", completion = "聖焰保佑。協商過程比我預期得還要順利。\n\n再一次謝謝你。你幫了我們很大的忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82219] = {title = "為生活加料", objective = "在聖落之地採集7株光沐蓮。", description = "聖焰祝福你，<name>。\n\n由於現在鳴響深淵恢復安全，情況也相對平靜，貿易目前進行得很順利。儘管如此，我們的將軍還是無法鬆懈下來。她太緊繃了，這樣不健康。不健康的將軍會讓整個軍隊都不健康。\n\n應該要花一天跟家人相處才對。你可以採集一些做菜要用到的香料嗎？最好採大株的，別管小株的香料。", progress = "被巴雷達爾的光芒照耀過的草藥，味道出奇的好。", completion = "這些非常棒，做得好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82220] = {title = "鷹眼、鷹死", objective = "收集5份老鷹肉片。", description = "棲息在無底深海的老鷹被巴雷達爾的光芒照耀過，因此嚐起來特別美味。\n\n可以收集一些老鷹肉片嗎？帶著這根魚叉，那些老鷹可是很凶猛的。", progress = "自己多小心，那些老鷹很容易傷到你。", completion = "這些看起來很多汁。謝謝你，&lt;name&gt;！\n\n我會確保這些食材變成美味佳餚的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82221] = {title = "盛裝打扮", objective = "幫助鐵擊一家裝飾他們在米雷達爾的家，迎接接下來的宴會。", description = "傳統的阿拉希家族聚餐也會展示不同的獎牌、獎項和家族紀念物。由於我母親的職涯功績不斷，這會花一點時間。\n\n你願意幫忙擺放部分的裝飾嗎？", progress = nil, completion = "謝謝你。這些都是很有歷史的東西。很高興看到它們被展示出來。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82222] = {title = "時尚主廚", objective = "在米雷達爾幫助鐵擊一家烹煮料理。", description = "抱歉，你完全被我女兒拖下水了。你原本一定有更重要的事要做。\n\n她實在太不懂人情世故了。我一定要找她的家長好好談談。\n\n<將軍露出一個短暫且不自然的笑。>\n\n不過，既然你都來了。你要不要跟我們一起做些更有趣的事？我們正準備開始烹飪。", progress = nil, completion = "哈！烈焰啊，我都忘了烹飪是件多麼有趣的事了！\n\n好療癒。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82223] = {title = "私房料理", objective = "在聖落之地米雷達爾的鐵擊宅邸用餐。", description = "私房燉菜，這東西在世界上其他地方可找不到。\n\n我向你保證，雖然這可能沒有帝國邊境旅店煮的燉菜那麼好吃，但這是家人煮的。這就是它最棒的地方。\n\n和我們一起享用。你值得一起品嘗好料。", progress = nil, completion = "啊，我正好需要這個。\n\n歡迎你隨時加入我們，&lt;name&gt;。", rewards = "您會收到：\n\n食譜：巴雷達爾的恩惠共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][82224] = {title = "查看編撰者", objective = "關心布倫諾克。", description = "這樣就都好了。你可以去關心一下布倫諾克嗎？朗誦是件蠻有壓力的事情。有人幫忙的話，他一定會很感激的。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
