MultiLanguageQuestData['tw'][82628] = {title = "布朗派克兄弟檔", objective = "到崇敬之地附近找布朗派克兄弟檔。", description = "布朗派克男爵和他的兄弟一直在崇敬之地附近，努力解決困擾我們已久的那些寇拜斯。\n\n去那裡找他們，看看你能幫上什麼忙。", progress = nil, completion = "希望你是來弄髒自己雙手的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82629] = {title = "奈幽巴宮殿：僅限奈幽蟲族之眼", objective = "在普通難度的奈幽巴宮殿中，收集3枚千疤的璽戒和3枚紡紗者的璽戒。", description = "我們的坑道不是為你們打造的…就算讓你進去，你也會寸步難行。\n\n替我拿絲綢宮廷、聖甲蟲領主阿努巴拉許和紡紗者塔卡茲的璽戒來，我就讓你經由秘密通道前往宮殿。", progress = "想要安全通過就要付出代價。", completion = "不要誤入暗影的領域，&lt;name&gt;，否則我無法保證你的安全。", rewards = "您會收到：\n\n"}
