MultiLanguageQuestData['tw'][82659] = {title = "世界之魂：奈幽巴宮殿", objective = "在普通或更高的難度下通關奈幽巴宮殿。", description = "安蘇芮克女王證明了自己多麼殘酷和狡猾。我們不能讓她的部隊在薩拉塔斯黑血的幫助下，繼續變得更加強大。\n\n終究走到了這一步，這的確是個令人望而生畏的行動。這次我們將精銳盡出，圍攻奈幽巴宮殿！您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][82672] = {title = "另一份邀請", objective = "前往塔納利斯的時光之穴外的慶典。", description = "青銅龍軍團目前在塔納利斯的時光之穴外慶祝！\n\n在那裡有各式各樣的全新活動，以茲紀念這些年來的事蹟、彰顯其榮耀。\n\n前往塔納利斯參加慶典吧。", progress = nil, completion = "歡迎！\n\n這是一年裡的特別時分。青銅龍軍團慶祝這些年來發生的事情。\n\n&lt;name&gt;，你是一位嘉賓！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82676] = {title = "壞掉的假面", objective = "在璀璨回音事件中，擊敗記憶中的奧妮克希亞。", description = "我不記得我是怎麼來到這個沼澤的，但這對我來說非常幸運。在我到處亂走的時候，無意間撞見卡特拉娜‧普瑞斯托女士走進一個入口長著尖牙的奇怪洞穴。真怪，一個貴族女士跑來這種詭異的地方做什麼？\n\n我緊跟著她，結果在巢穴中發現一大窩黑龍蛋。真相大白了。卡特拉娜居然是奧妮克希亞女士！\n\n我求求你，幫助我徹底消滅這隻邪龍。", progress = "要是瓦里安在這裡，他絕對可以殺死她。", completion = "你說真的嗎？她終於安息了？\n\n她是個野心勃勃的傢伙。幸好我們成功阻止了她。要是讓她實現她的陰謀詭計，真不曉得會造成什麼樣的悲劇。", rewards = "您會收到：\n\n殘存記憶"}
MultiLanguageQuestData['tw'][82678] = {title = "文庫：第一張圓盤", objective = "在記憶寶庫與達格蘭會面，並協助他找到泰坦圓盤碎片。\n\n圓盤碎片可從地城、探究以及卡茲阿爾加各處的危險生物和寶藏獲得。", description = "我很高興能向各位報告，資料庫的泰坦記憶寶庫修復工程取得了進展。主機已開啟，正在運轉中，但其內部的部分零件已隨著時間過去而故障。\n\n找回修補零件是件非常困難的事，而這也是我們為何需要你的幫忙。跟我一起前往記憶寶庫，和達格蘭討論我們所需要的東西。", progress = "你有找到什麼嗎？", completion = "這太完美了！這部分的腐蝕程度非常輕微，我們應該有辦法救回存在裡面的資料！\n\n讓我們一起發掘被埋藏的知識吧，&lt;name&gt;！", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱尖端儲物箱青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82679] = {title = "文庫：尋覓歷史", objective = "收集100片泰坦圓盤碎片。\n\n圓盤碎片可從地城、探究以及卡茲阿爾加各處的危險生物和寶藏獲得。", description = "我們還在處理資料庫裡的資料，並盡可能予以修復。但…到目前為止，我們在資料庫修復的圓盤都不能用。\n\n當務之急是找到更多圓盤。我們必須取回我們的記憶。\n\n將你找到的東西交還給達格蘭，他在協助我重建資料庫。", progress = "你找到什麼了嗎？", completion = "謝謝你，&lt;name&gt;。雖然我相信我們已經取回阿札達斯所有的日誌了，但我想繼續修復文庫。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱尖端儲物箱青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82680] = {title = "三盾群島的鳥人", objective = "在三盾群島找到奧巴里格。", description = "你是來看苔毛羊的嗎？不是？\n\n那真是太可惜了。我覺得我們島上的元素生物很迷人。我不是唯一有這種想法的人。\n\n我的一位老朋友奧巴里格住在三盾群島。他在那裡研究野生的雲鴉獸。\n\n說到這裡，我已經有一段時間沒聽到他的消息了。或許有人可以去看看他的情況。嗯，你覺得呢？", progress = nil, completion = "哈莫特叫你來看看我的情況？\n\n哼。原來那坨木炭也會在乎別人。\n\n不過他天生就有感應元素騷動的能力。或許他知道這裡正在醞釀著什麼。\n\n哈莫特的時機抓得不錯，外來者。我們很歡迎你的協助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82681] = {title = "雲鴉獸的降落", objective = "清除三盾群島中央被激怒的元素。", description = "你看到遠方的那群鳥了嗎？那是野生雲鴉獸。\n\n牠們在這些島上平靜生活了很久。但最近的一些事件驚動了地上和海裡的其他元素。其中一隻雲鴉獸受到了攻擊，而牠的遺骸被…肢解了。\n\n鳥群現在不斷地圍著圓圈飛行。當然，牠們很快就會感到疲累。當牠們太累的時候…\n\n如果我們清除了這座島上的敵對元素，牠們可能就會飛回來休息。", progress = nil, completion = "外來者，衷心感謝你的協助。雖然那些雲鴉獸看起來還是不願意回到島上。\n\n如果牠們是在為同伴哀悼，我擔心那些雲鴉獸可能會累死，最後面臨被肢解的命運。\n\n我們必須試試其他方法。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82682] = {title = "元素開胃菜", objective = "收集10條電鰻。", description = "雲鴉獸不可能永遠都繞著圓圈飛，而我也不能接受失去更多雲鴉獸。如果我們拿牠們最愛的食物誘惑牠們，牠們會不會回來休息？\n\n在這些水裡游的鰻魚帶有少量的電流，就像牠們更迅速、更強大的近親風暴禿鼻鴉喜歡苔毛羊一樣。我曾經推測雲鴉獸也因為類似的原因而喜歡這些鰻魚。\n\n其實…從那時候開始，我就一直在餵牠們吃鰻魚。\n\n去收集一些來試試看。", progress = "這些鰻魚可能不像漫步郡的苔毛羊那麼帶勁，但雲鴉獸更喜歡這樣子。", completion = "這些應該夠了。\n\n希望你在收集的時候沒被電得太慘。\n\n我們可以幫雲鴉獸恢復一點能量，讓牠們知道這裡可以安全降落。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82689] = {title = "一片黑暗", objective = "在璀璨回音事件中，擊敗記憶中的巫妖王。", description = "我已經等了這一天很久了，英雄。你和你的盟友們準備要制裁巫妖王了嗎？只要你一聲令下，我們就會衝鋒殺敵！", progress = nil, completion = "好了，總算結束了。\n\n願艾澤拉斯的所有人永遠記得我們在這裡的義舉。願無數人的犧牲永遠在人們的心中燃燒。願他們在面對巨大的邪惡時，永遠不畏懼犧牲生命。", rewards = "您會收到：\n\n殘存記憶"}
MultiLanguageQuestData['tw'][82690] = {title = "不散暗影", objective = "返回艾蘭里亞在聖落之地感應到黑血的地方。", description = "在聖落之地面對薩拉塔斯的時候，我感覺到地下有某種黑暗的東西。那與她無關，卻還是讓我很不安。\n\n我已經學到了獨自面對所有情況不一定是最好的戰術。有時候，領導者也需要在戰場後方觀察局勢。\n\n所以，我決定派你過去。\n\n前往聖落之地，盡你所能查出這股神秘勢力的真相。我可不想再被打個措手不及。", progress = nil, completion = "我沒想到會在這裡見到你。\n\n不過，你總是會在有意思的事發生的地方出現，對吧？\n\n但是沒時間聊天了。我的族人遇上了麻煩。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82691] = {title = "無處喘息", objective = "殺死滲漏生物。", description = "我們所有人跟著歐薇娜來到這些地表的洞穴，因為我們相信我們在做的事。但是…我們沒想到會換來這麼多的傷員，這麼多的艱苦搜尋。\n\n現在，我們只需要一點喘息的空間。殺死在外面傷害我們的生物，這樣我們就有空間可以解決真正的問題。", progress = nil, completion = "這樣應該能給我們一些撤退的空間。\n\n現在我們必須來處理問題的核心了。那就是歐薇娜不惜一切追查這個任務的不懈決心。\n\n我們是時候好好談談了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82692] = {title = "任務的代價", objective = "找到被壓制的哈拉尼爾，並檢視奇怪的花。", description = "我不知道是什麼驅使你來這裡，但我們需要你的幫忙。\n\n我們來調查這片區域的黑血跡象，卻遭到這些生物圍攻。我們有一些人還在戰場上。\n\n你強壯有活力。去找我的族人，幫助他們平安歸來。\n\n然後，如果你有餘力的話，仔細觀察一下從滲入地底的血液中長出來的奇怪花朵。這些花或許有如何對付它的腐化的線索。", progress = nil, completion = "&lt;歐薇娜一言不發地數著哈拉尼爾的數量，好安撫自己。然後她點點頭。&gt;\n\n人都到齊了。非常感謝。\n\n你找到的那些花也很奇怪。它們似乎帶有腐化的特性，並變成了某種新的植物。我必須深入調查此事。\n\n就差一點點了，我們現在不能收手。這可能是我們找出反擊方法的關鍵。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82693] = {title = "攔住去路", objective = "擊敗血殼巨獸。", description = "其中一些生物比其他同類更強。當我們團結一致、驍勇善戰的時候，這些生物不構成威脅。但現在我們戰力衰退、分崩離析，於是便有了弱點。\n\n我的族人很有韌性，但我們也只是凡人。\n\n有一隻野獸的體型比其他野獸還要碩大。這隻野獸讓哈拉尼爾難以回歸和恢復。\n\n殺了它，保障他們的安全。", progress = nil, completion = "&lt;歐薇娜點點頭。&gt;\n\n謝謝你。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82694] = {title = "團結，孤獨", objective = "在聖落之地與哈南會面，聽取計畫。", description = "我沒有瞎。我知道他們疲憊不堪。但我們只差一點就能查出我們能對黑血做什麼。\n\n我們發掘的真相不只對聖落之地很重要，對奈幽王國也是。如果我們要找出一個解決辦法，那我們還有很多工作要做。\n\n現在，我們先撤退並恢復。去一個遠離這些生物的地方。", progress = nil, completion = "納雷洛。凱夏。奈蕾亞。昂錫爾。\n\n哈南。\n\n在這個遠離家鄉的地方，我們就是一個家庭。\n\n我不怪他們想要回去，但要是我在這時候放棄，那我一定會怪我自己。我必須專心面對接下來的事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82695] = {title = "聲音", objective = "在歐薇娜冥想時保護她。", description = "這裡就是我必須專注的地方。我能聽到我的女神的聲音，她一定就在附近。\n\n我會開始冥想，問自己該怎麼做。我該怎麼獨自執行這項任務？沒有其他人的話，我該怎麼繼續下去？\n\n靠近一點，我不知道在我專注的時候，會潛伏著什麼樣的威脅。", progress = nil, completion = "我知道。\n\n我們必須去某個地方，讓我可以聽見東西在石頭底下移動的聲音。我不知道這是什麼意思，我只知道我必須去那裡。\n\n你要跟我一起來嗎？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82696] = {title = "深淵中的鳴響", objective = "在鳴響深淵的穆羅契營地與歐薇娜會合。", description = "我的幻象很清楚。我必須繼續調查下去。\n\n我必須查出阻止黑血擴散的方法，在一切對你我的族人都太遲以前。\n\n到鳴響深淵和我會合。我會變裝一下，方便我避人耳目並偷聽情報。", progress = nil, completion = "現在似乎到處都是哥布林。\n\n別靠得太近看我，否則你會引來注意。我們必須接近哥布林工作的地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82697] = {title = "年度好幫手", objective = "找出哈克索‧鑽塊，從他身上敲詐參與行動的許可。", description = "在這裡看到你真是愉快的驚喜！\n\n在機會營地有大事發生，但不接近在那裡工作的人的話，很難知道是什麼事。\n\n我知道哈克索有參與其中。如果我們想要問東問西，又不引來麻煩，就會需要取得他的證件。\n\n他正在前往機會營地。\n\n去跟蹤他，看看他身上有沒有什麼我們可以利用的東西。別擔心會引起騷亂，我知道你在必要的時候會保持謹慎。\n\n也有可能…不會。", progress = "拿到那份工作指令了嗎？有了它，我們就能進到更多地方。", completion = "完美。現在只要有人問起為什麼我們在這裡，我們就能秀出這個。現在該來點窺探工作了。\n\n…這裡的哥布林比我記得的還要多。肯定有什麼事要發生了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82698] = {title = "故障之敵", objective = "摧毀故障的挖掘機。", description = "我看到附近有很多機械，而且它們似乎都在發出可怕的聲音。不過，我聽不見我在幻象裡聽到的那台機械，至少聽不清楚。\n\n摧毀掉多餘的機械。它們很礙事。\n\n在你消除現場噪音的時候，我會去狩獵和偵察。", progress = nil, completion = "看來你也對工頭辦公室有興趣，是吧？\n\n別胡思亂想，我和你是一國的。我只是沒辦法在不被看到的情況下靠近。\n\n然後，這整場騷亂之中還有一個鏗鏘作響的大麻煩。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82699] = {title = "嘿，發生什麼事了？", objective = "在淵積挖掘場詢問哥布林和發掘證據以尋找線索。", description = "該來打聽一些情報了。\n\n在機會營地外面有一些哥布林，就在淵積挖掘場那裡。我聽到其中一些人在輪到他們上班時發牢騷。\n\n來看看他們能透露出什麼消息。\n\n你在那裡的時候，去調查一下使用過的燃料桶。他們不會讓我看裝滿的燃料桶裡面有什麼，不過卻把用過的燃料桶隨意放置在挖掘場。", progress = nil, completion = "那些哥布林只知道故事的一部分。裡面才是故事的全貌，或者至少是缺失的一塊大拼圖。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82700] = {title = "為爆破而生", objective = "摧毀故障機甲IV號。", description = "我們遇到情報問題了，但我們同時也遇上了機械問題。\n\n如果你看向那裡，可以看到一台暴走的故障大機甲。要是那東西在工作場上大鬧，就不可能有人能找出任何東西。\n\n我們應該做點什麼。", progress = nil, completion = "看來我們全都在尋找情報，但我有一些應該能派上用場的情報。\n\n而且現在要躲已經太遲了，他們看到了我的真實形態。\n\n讓我們看看最後的結果是什麼吧。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][82701] = {title = "蝙蝠對抗世界", objective = "體驗歐薇娜的偵察任務。", description = "我在偵察的時候，我聽到和看到了我無法理解的事物。\n\n或許我可以描述給你和哥布林聽，你們會知道是什麼意思。", progress = nil, completion = "從那個地方逃離之後，我看到你在跟巨型機械戰鬥，而我也必須加入戰局。\n\n看來現在真的無法回頭了。我在這裡孤身一人，只剩你還有這些哥布林。", rewards = "您會收到：\n\n勇氣石雕刻先驅者紋章陳舊幽坑城紋章陳舊以太紋章"}
MultiLanguageQuestData['tw'][82702] = {title = "尋得朋友", objective = "向多恩諾加的艾蘭里亞回報。", description = "所以加里維克斯選擇在這裡露出他的醜陋嘴臉，而且看來他已經把一切都安排好了。\n\n我們應該把這件事報告給艾蘭里亞。看看她要怎麼應付此事。", progress = nil, completion = "你帶給我的遠不只是情報這麼簡單。\n\n雖然我感覺這個…歐薇娜…不會輕易洩漏自己的秘密。但我應該有點耐心。我相信我們最終會找到共通點的。\n\n在此同時，她應該先去和某人聊聊。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82706] = {title = "探究：世界性研究", objective = "在地心之戰中完成3次探究。", description = "最近都很閒，我沒有聽到任何問題。\n\n這似乎是個四處探索的好機會對吧？我聽你差遣！我們可以去任何你想去的地方！", progress = nil, completion = "今天去看了幾個不錯的地方。這是好事。讓我的老心臟蹦蹦跳。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱尖端儲物箱"}
MultiLanguageQuestData['tw'][82708] = {title = "豐碩探究", objective = "從勞迪‧碎石身上取得鑰匙，然後完成一場豐碩探究。", description = "我們一直用「豐碩」來形容某些探究，因為裡面的壞蛋囤積著更多的寶藏。\n\n這些寶藏只能用在卡茲阿爾加各處找到的特殊鑰匙才能解鎖。\n\n我們聽說有一個統治著山脈的石巨人，它的身上似乎卡著一把鑰匙。\n\n把鑰匙搶走，然後前往豐碩探究，看看你能找到什麼！我會在探究裡跟你會合。", progress = nil, completion = "那些奈幽蟲族該學到教訓，別再這麼兇了吧？\n\n你逮住他們，然後我揍他們一頓！或是反過來，我都可以。", rewards = "您會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱"}
MultiLanguageQuestData['tw'][82709] = {title = "豐碩探究", objective = "從勞迪‧碎石身上取得鑰匙，然後完成一場豐碩探究。", description = "我們一直用「豐碩」來形容某些探究，因為裡面的壞蛋囤積著更多的寶藏。\n\n這些寶藏只能用在卡茲阿爾加各處找到的特殊鑰匙才能解鎖。\n\n我們聽說有一個統治著山脈的石巨人，它的身上似乎卡著一把鑰匙。\n\n把鑰匙搶走，然後前往豐碩探究，看看你能找到什麼！我會在探究裡跟你會合。", progress = "我真不敢相信有些人完全不在乎歷史。讓我好難過。", completion = "或許我們拿到的只是碎片，&lt;name&gt;。可是有了碎片，我們就可以重建它。你可以看到它以前的樣子。\n\n碎片比塵土好一點，我想說的就是這個。", rewards = "您會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82710] = {title = "豐碩探究", objective = "從勞迪‧碎石身上取得鑰匙，然後完成一場豐碩探究。", description = "我們一直用「豐碩」來形容某些探究，因為裡面的壞蛋囤積著更多的寶藏。\n\n這些寶藏只能用在卡茲阿爾加各處找到的特殊鑰匙才能解鎖。\n\n我們聽說有一個統治著山脈的石巨人，它的身上似乎卡著一把鑰匙。\n\n把鑰匙搶走，然後前往豐碩探究，看看你能找到什麼！我會在探究裡跟你會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82711] = {title = "豐碩探究", objective = "從勞迪‧碎石身上取得鑰匙，然後完成一場豐碩探究。", description = "我們一直用「豐碩」來形容某些探究，因為裡面的壞蛋囤積著更多的寶藏。\n\n這些寶藏只能用在卡茲阿爾加各處找到的特殊鑰匙才能解鎖。\n\n我們聽說有一個統治著山脈的石巨人，它的身上似乎卡著一把鑰匙。\n\n把鑰匙搶走，然後前往豐碩探究，看看你能找到什麼！我會在探究裡跟你會合。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82712] = {title = "豐碩探究", objective = "從勞迪‧碎石身上取得鑰匙，然後完成一場豐碩探究。", description = "我們一直用「豐碩」來形容某些探究，因為裡面的壞蛋囤積著更多的寶藏。\n\n這些寶藏只能用在卡茲阿爾加各處找到的特殊鑰匙才能解鎖。\n\n我們聽說有一個統治著山脈的石巨人，它的身上似乎卡著一把鑰匙。\n\n把鑰匙搶走，然後前往豐碩探究，看看你能找到什麼！我會在探究裡跟你會合。", progress = nil, completion = "&lt;name&gt;，這還真是…我之前的評論最直接的體現啊。\n\n不過，我們讓他們見識了耍狠的下場…直接對他們以牙還牙！", rewards = "您會收到：\n\n尖端儲物箱阿爾加冒險者的貯藏箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82746] = {title = "豐碩探究", objective = "從勞迪‧碎石身上取得鑰匙，然後完成一場豐碩探究。", description = "我們一直用「豐碩」來形容某些探究，因為裡面的壞蛋囤積著更多的寶藏。\n\n這些寶藏只能用在卡茲阿爾加各處找到的特殊鑰匙才能解鎖。\n\n我們聽說有一個統治著山脈的石巨人，它的身上似乎卡著一把鑰匙。\n\n把鑰匙搶走，然後前往豐碩探究，看看你能找到什麼！我會在探究裡跟你會合。", progress = nil, completion = "嗚呼！我們來了，看到了牠們，然後狠狠地踢了牠們一腳！\n\n現在卡茲阿爾加不用再受邪惡的掠食生物傷害。功德一件對吧？", rewards = "您會收到：\n\n尖端儲物箱"}
MultiLanguageQuestData['tw'][82747] = {title = "十字路口廣場", objective = "到十字路口廣場與邦達茲會面。", description = "你好，外來者。你想知道城市外面的消息嗎？\n\n十字路口是土靈交換情報和商品的重要場所，無論他們遵循的是什麼誓言或律令。\n\n我的朋友邦達茲是那個地方的地下老大。他會很樂意親自接待你。關於你和其他外來者如何來到這座島的各種說法，一定已經傳到他耳裡了。", progress = nil, completion = "…有外來者？活生生的外來者！就像其他人一樣前來拜訪！而且人數眾多！\n\n我真不敢相信我的眼睛。我對島上的一切瞭若指掌，但這完全超乎我的想像。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82748] = {title = "礦運深谷", objective = "完成礦運深谷戰場。", description = "我們接獲報告，指出土靈的深淵出現了麻煩。探索礦運深谷和可用的資源，然後向魯夫厄斯回報。", progress = nil, completion = "你活著從礦坑出來了！太棒了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82762] = {title = "外袍加身", objective = "在勝利面相與凱莎交談。", description = "哇！\n\n這真是件超級美妙的外袍！而且你可以隨心所欲地客製它。\n\n凱莎可以幫你實現你的設計。\n\n去找她然後開始設計吧！", progress = nil, completion = "我很樂意協助你設計你的個人外袍！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82768] = {title = "雲中釣魚", objective = "對狂野的雲鴉獸獻上7條電鰻。", description = "現在我們拿到鰻魚了，可以開始引誘雲鴉獸回到地面上了。\n\n前往鄰近的島嶼。盡你所能靠近牠們然後獻上禮物。\n\n如果夠幸運的話，牠們就會停止轉圈，飛下來享用一頓大餐。", progress = nil, completion = "現在我懂了。這是雲鴉獸穿越元素界域來到這裡的方式。牠們並不是在哀悼，而是在呼喚死去的同胞。\n\n謝謝你的幫助，外來者。你幫助了我更了解這些美麗的生物。", rewards = "您會收到：\n\n奧巴里格的舊裹腕奧巴里格的舊護腕奧巴里格的舊腕輪奧巴里格的舊護臂共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][82771] = {title = "土靈的傳承", objective = "在多恩諾加將經驗上傳至文庫。", description = "回歸文庫的時候到了。\n\n所有土靈漫遊者都受邀前來分享個人經驗，以保存過去的經歷，並為未來鋪路。\n\n艾澤拉斯是個更廣大的世界，相關的知識和經驗，將會是無價之寶，而分享見聞的行為則是土靈傳承的關鍵。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n土靈的傳承"}
MultiLanguageQuestData['tw'][82773] = {title = "實用的人情", objective = "收集6個電流腺體。", description = "我在找我的導師工頭奧巴赫。他…失蹤了。在其他情況下，我會從剛達加茲派出搜救隊，但是時間不夠了。\n\n我懷疑他經過了這裡，但我唯一的線索來自德基茲墨。他希望能清除當地的霧獸。我很不情願。但是如果他見過奧巴赫，我必須知道他知道些什麼。\n\n南邊的潛伏者帶有強大的電流腺體。它們的電力足以驅散最濃的大霧。去收集一些。保證給你報酬。", progress = "越快越好。我必須找到奧巴赫。", completion = "可以了。這些看起來充滿能量，這樣就可以幫你替德基茲墨趕跑霧獸。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82774] = {title = "除霧務盡", objective = "驅散穆羅契營地周圍的迷霧。", description = "機語者不喜歡霧獸。只要有霧的地方，東西就很容易生鏽。不過，我不想傷害牠們。奧巴赫總是說這樣會帶來不幸。\n\n帶著這部裝置。你收集的腺體應該可以提供足夠電力，能夠驅散迷霧，又不會傷害躲在裡面的霧獸。\n\n小心點。霧獸是很膽小，但迷霧中還可能藏著其他生物。", progress = nil, completion = "做得很好。希望德基茲墨的情報值得我們這樣做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82775] = {title = "快速變裝表演者", objective = "在舞臺接受溫蒂琳的指點。", description = "你似乎具備了成為一名偉大演員的資質，$p！\n\n我之所以知道，是因為我自己就是這樣的人，無論其他那些所謂的「演員」說了什麼。\n\n你超快的換裝速度讓我留下深刻的印象。你知道的，我本身就是快速換裝大師。\n\n你就快要達到那個境界了。你只需要像我這樣的專家的一些指點！", progress = nil, completion = "你看，角色的精神不只寄宿在你身上，也寄宿在戲服中。\n\n練習快速變裝就跟練習臺詞一樣重要。\n\n現在你可以快速切換角色，成為千變萬化的藝術大師了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82778] = {title = "聖落之地釣魚大賽", objective = "在大賽突進者增益效果消失前，捕捉這些戰利品魚：啃咬小鯉、阿拉索錘頭魚、女王餌背。", description = "這裡的生活一向很刺激，$p。奈幽蟲族、寇拜斯、飢餓，總是有東西想要你的命。\n\n所以我們需要找時間放鬆一下，挑戰一下努力生存以外的東西。比如說釣魚。\n\n在我童年時期，我爸每個星期六都在釣魚。他會說：「花點時間照顧你自己，不然你就無法照顧別人。」\n\n所以每個週六，我都會邀請人一起挑戰聖落之地釣魚比賽。你有一小時去抓戰利品魚。看看你能帶什麼魚來給我吧！", progress = nil, completion = "真是不錯的收穫，&lt;name&gt;。我等不及看你下週會釣到什麼魚了！", rewards = "您能選擇下列奬勵中的一個：\n\n[Soaked Journal Entry]阿爾加追尋者絲線阿爾加釣手絲線\n\n您還會收到：\n\n米雷達爾大賽獎章"}
MultiLanguageQuestData['tw'][82781] = {title = "引人矚目", objective = "在舞臺接受艾兒瑪的指點。", description = "天啊，$p，你似乎吸引了某位觀眾的關注。\n\n這封粉絲信不小心混入我的粉絲信。我並不意外。分揀我為數眾多的粉絲信一定是件困難的工作…\n\n來，收下它。畢竟，這屬於你。\n\n相信這對你一定是很新奇的體驗。如果你想聽的話，我可以教你如何應付狂熱的粉絲…", progress = nil, completion = "我們必須小心翼翼地面對粉絲。必須顧慮到他們的感受，但也要杜絕不當的行為。\n\n關鍵就在於親切和藹地接受他們的感謝。最好可以回寄簡單的感謝信。如果在這裡看到他們，可以適當地點頭和揮手。讓觀眾覺得開心很重要。\n\n如果他們獻花給你…我會很樂意幫你分擔一點重量。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82782] = {title = "保管服裝", objective = "在舞臺與拉巴安談話。", description = "你作為演員在舞臺上的表現相當出色，$p。\n\n不過身為劇團的一員，我們還有其他規矩需要遵守。其中一條是妥善保管戲服，供日後使用。很多戲服都會不只使用一次。\n\n我認為我們可以相信你會好好使用和保管劇團的戲服，沒錯吧？這代表你可以更常跟我們一起排練…", progress = nil, completion = "太棒了。我非常樂於消弭演員與規矩之間的障礙。\n\n請小心保管戲服。要記得，我們會在之後的演出中用到它們。\n\n祝你好運！別忘了你已經是劇團的一員了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82783] = {title = "克羅米的寶典", objective = "完成克羅米的寶典事件。", description = "哈囉！我非常需要你的援手。\n\n最近的旅程讓我的寶典變得凌亂不堪，我得在一個小時之後展開一趟回到安其拉大門的時間之旅。\n\n我需要你和我一起行動，幫我應付途中的任何…突發狀況。那麼一切應該會很順利，所有來這裡的訪客都會有一個有趣且不太危險的旅程！", progress = nil, completion = "十分感謝你的協助！\n\n第一趟旅程讓我倍感喜悅。多虧有你，不會有人賠上自己的性命或失蹤。不過，之前其實也沒…發生過…", rewards = "您會收到：\n\n\n\n等級 70–80青銅龍慶典藏寶箱\n\n等級 10–69時光好物包時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82784] = {title = "引人入勝的表演", objective = "在舞臺與伯克哈特談話。", description = "$p，我從你的表演中學到不少東西。你很輕鬆就能進入每一個角色。在某齣劇中我看到你從敵人轉換成朋友，從憤怒轉換成哀傷…整個轉變過程自然且流暢。\n\n有你跟我們一起演出，我覺得我們的表演也更加盡善盡美，能帶給觀眾最大的滿足。\n\n如果你有時間的話，我想感謝你的鼎力相助。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82785] = {title = "機械中的鬼魂", objective = "找到工頭奧巴赫。", description = "我們正下方有一座變電站？也許那就是奧巴赫前去躲藏的地方…不論如何，我們必須調查。\n\n如果夠幸運的話，奧巴赫也許還在這裡。入口應該在北邊，靠近爆裂水管留下的水池。請跟我來。他可能需要我們的幫助。\n\n找到他之後我會解釋一切。", progress = nil, completion = "它殺了他，而且我們還放走它。就連他的記憶寶石都不見了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82786] = {title = "保養工作", objective = "沿著激瀑河啟動備份系統。", description = "那個魔像極不穩定。我不認為它能跑太遠。我們會追上它，但心急已經讓我失敗一次了。奧巴赫是真正將一切奉獻給機械的人。我們把他當成榜樣。先把機械修好再說。\n\n機械系統十分精密。我們必須在故障引發連鎖反應之前先啟動備份。順便消滅你看到的所有害蟲。一隻小小的生物就可能毀了精密無比的機械。\n\n我受損了。我會派我的齒輪行者陪你去，作為指令的中繼站。", progress = nil, completion = "備份系統正常運行。現在，我們可以去追那個魔像了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82787] = {title = "特殊任務：巨像復活", objective = "擊殺巨大野獸。", description = "世界任務完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][82792] = {title = "極端情「礦」", objective = "前往蛋白石礦場並尋找雅維嘉。", description = "外來者，我們需要你的幫忙。\n\n這裡的土靈說過你幫得上忙。\n\n我們在蛋白石礦場的土靈同伴還沒回報他們昨天的蛋白石產量。他們一定是遇到了什麼事。\n\n你願意去拜訪一下工頭雅維嘉嗎？", progress = nil, completion = "我正在躲藏…低調一點。\n\n工頭葛米菈派你來的？她一定很擔心我們為什麼還沒送出該有的配額。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82796] = {title = "潛入第三礦坑", objective = "在蛋白石礦場的第三入口與雅維嘉碰面。", description = "我跟其他礦工失去了聯繫。我們沒料到奈幽蟲族會打過來。不過我也無法想像其他人會停止工作。\n\n我們的工作太重要了，不能輕易放棄。\n\n直接衝進礦坑可能會激怒奈幽蟲族，進而讓其他人受害。所以我先前找到了第三條潛入的路徑。不過還是很難不被發現。\n\n跟我來。", progress = nil, completion = "你沒有被發現，很好。是時候給這些奈幽蟲族一個驚喜了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82797] = {title = "抵達岩底", objective = "抵達礦坑底部並找到仙德拉格。", description = "這條路要很久才會到底，不過我確信你一定沒問題的。\n\n要是你還是有所疑慮，我做了一些降落傘，幫助你穩穩落地。\n\n一旦你抵達洞穴底部，就去找仙德拉格。她是資歷最久的工人，最可能知道如何救出所有人。", progress = nil, completion = "你是誰？你為什麼在這裡？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82798] = {title = "你不能拿走我的蛋白石", objective = "幫仙德拉格在蛋白石礦場收集8個蛋白石礦石。", description = "我就直說了。我們在這裡有個目的，最重要的就是那些蛋白石。\n\n在工作沒完成之前，沒有人會離開，蛋白石實在太重要了。如果你能收集到足夠的礦石，我們就能說服他們離開。\n\n不過，要小心一點，那些奈幽蟲族很危險。", progress = "為什麼奈幽蟲族非得要這時候出現？我們就要大功告成了。", completion = "我們收集了不少。但我擔心這樣還不夠多。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82799] = {title = "蛛網布能贏石頭", objective = "在蛋白石礦場救援6名土靈。", description = "工頭雅維嘉派你來的？這就說得通了。\n\n情況不怎麼好。這個地方爬滿了奈幽蟲族，他們心狠手辣，一直強迫我們採礦，拿走我們千辛萬苦開採出來的蛋白石。\n\n要是你不聽話，他們就會用蜘蛛網把你包起來。\n\n當他們攻進來的時候，我在千鈞一髮之際順利逃脫。而其他人…沒錯，這就是你登場的時候了。\n\n有你在此吸引他們的注意力，我就可以去召集被網住的土靈了。", progress = nil, completion = "感謝機械！他們自由了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82800] = {title = "沉積時刻", objective = "協助仙德拉格激勵蛋白石礦場的土靈工人。", description = "有些人已經開始撤離了，不過還有一些冥頑不靈的傢伙不願離開。\n\n你可以去說服他們嗎？\n\n也許外來者的觀點能夠打動他們。", progress = nil, completion = "成功了！謝謝你。\n\n無論我們剩下的時間有多久，每救一個土靈，對我們來說都是件喜事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82801] = {title = "甲蟲珠寶", objective = "在蛋白石礦場外擊敗齊斯阿拉克。", description = "想不讓土靈受害，就必須消滅他們的領導者。\n\n正如俗話說的，沒有工頭，就是一盤散沙。\n\n另外，想抵達安全的地方，我們必須先過他們這一關。", progress = nil, completion = "你回來了，我原本還以為已經沒希望了。\n\n雅維嘉已經把事情經過都告訴我了。很高興我們所有人都平安，還順利拿到蛋白石。\n\n雖然只是個小小的成功，但也是大功一件。", rewards = "您會收到：\n\n齊斯阿拉克之禍護肩齊斯阿拉克之禍腰帶齊斯阿拉克之禍長靴齊斯阿拉克之禍護手共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][82809] = {title = "獅鷲獸同伴", objective = "想辦法讓史颳利開心起來。", description = "<你的史詩風暴禿鼻鴉史颳利靠近你並沮喪地鳴叫。也許有人會知道她為什麼心情低落。>", progress = nil, completion = "&lt;史颳利開心地鳴叫，興奮地跳來跳去。&gt;", rewards = "您會收到：\n\n閃掠強風電電"}
MultiLanguageQuestData['tw'][82810] = {title = "找到時間", objective = "找到6個遺失的紀念物。", description = "你回來了！\n\n如果你想參加的話，淤泥裡還有更多東西等人找回來。這次可能得稍微挖深一點。", progress = nil, completion = "跟之前一樣，我想請你把一部分拿去，看看我們能不能找到它們的主人。", rewards = "您會收到：\n\n象牙引火盒凹陷的矛頭鑲鈿教士"}
MultiLanguageQuestData['tw'][82813] = {title = "借用時間", objective = "找到6個遺失的紀念物。", description = "啊，是我的好朋友來了！我跟麥麥還在這裡找尋回憶。有空幫個忙嗎？", progress = nil, completion = "這些東西一定有故事。看看你能不能也幫它們找到主人吧。\n\n還有，謝謝你。我不確定我們還能找到多少。", rewards = "您會收到：\n\n鈣化的日誌木製刻像堅固的墜盒"}
MultiLanguageQuestData['tw'][82814] = {title = "驅逐黑暗", objective = "摧毀被腐化的魔像，並取回工頭奧巴赫的記憶寶石。", description = "機械很少需要報廢。這種事必須極為謹慎，也會讓人心生不捨。\n\n我們將一大部分的心力投注在工作中。摧毀機械就等同於摧毀自己的一部分。一旦這麼做，就代表我們未能保護好泰坦的傑作。不過，一旦機械暴走傷人，我們也不能坐以待斃。\n\n聽令：摧毀它。取回奧巴赫的記憶寶石。", progress = "我很後悔。這本來應該是我的重擔。", completion = "機械的死亡不是一件值得開心的事，但是我依然很感謝你。相信奧巴赫也是這麼想的。\n\n他做出的決定只有自己可以負責，但沒有人可以質疑他為機械獻出了生命。泰坦會感到驕傲的。", rewards = "您會收到：\n\n共鳴水晶共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][82815] = {title = "堅固的墜盒", objective = "你拿的是什麼東西？", description = nil, progress = "你拿的是什麼東西？", completion = "等等…這個墜盒。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82817] = {title = "發現亂象：黑石深淵", objective = "從黑石深淵的索瑞森大帝那裡取回時空錯置的鐵爐堡藍圖。", description = "時光行者聲稱在黑石深淵偵測到一個時空錯置的物體。\n\n我們或許在那場戰鬥吃了虧，黑鐵氏族十分清楚一旦歷史改寫，會有多麼嚴重的後果。我們目前和矮人的同盟以及同盟帶來的好處將無法維繫。\n\n取回那件物品，守護現有的和平。", progress = "和你戰鬥讓我感覺不到喜悅。我了解青銅龍的立場，以及他們為什麼要做這一切來守護時間線。", completion = "雖然這麼說有些奇怪，我必須感謝你擊敗我的氏族。我們將從漆黑的灰燼中再度崛起。\n\n謝謝你，勇士。", rewards = "您會收到：\n\n\n\n等級 70–80黑鐵矮人寶箱\n\n等級 30–69時光好物包時光扭曲徽章時光扭曲徽章雕刻先驅者紋章勇氣石"}
MultiLanguageQuestData['tw'][82832] = {title = "木製刻像", objective = "有貓患嗎？", description = nil, progress = "有貓患嗎？", completion = "啊，這真可愛。沒辦法告訴你它出自哪裡，看來應該是出自業餘人士之手，而不是專業工匠。不過我還是會把它擺出來展示。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82835] = {title = "鈣化的日誌", objective = "你在找什麼人嗎？", description = nil, progress = "你在找什麼人嗎？", completion = "啊！我有好幾年沒看到這東西了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82836] = {title = "抹除瑟蘿許", objective = "擊敗攻城領主瑟蘿許。", description = "$p，這裡的南邊有個攻城領主，所有的奈幽蟲族似乎都聽她指揮。如果我們能夠擊敗她，或許能扭轉這場戰爭的局勢。\n\n失去了發號施令的指揮官後，阿拉希人也許就可以擊退奈幽蟲族，尤其是當法林可以點亮她口中的黎明塔的時候。\n\n我們拖得越久，阿拉希飛船受到的損害就越嚴重。快去！", progress = nil, completion = "擊敗奈幽蟲族的首領後，我們應該能把防守的工作交給阿拉希人負責了。\n\n你今天拯救了許多性命，&lt;name&gt;。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82843] = {title = "帶土的東西", objective = "為主廚採收附近的芋頭。", description = "啊，又來了一個，是吧？如果你想吃東西，你就得幹活。\n\n可以幫我採摘新鮮的芋頭嗎？", progress = "你把芋頭拿來了嗎？", completion = "喔，好吧…你盡力了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82844] = {title = "完好的東西", objective = "與主廚一起採收6個芋頭。這次要正確採收。", description = "好吧。我跟你去一趟，教你正確的做法。如果我一起上，或許還能儲備足夠的芋頭。看來不能把太精細的工作交給冒險者去做。", progress = "那些就是全部了嗎？", completion = "這次好多了。這些夠用一陣子了。不過，如果你想吃芋頭，我還需要你幫點小忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82845] = {title = "象牙引火盒", objective = "什麼風把你吹來修道院的，外來者？", description = nil, progress = "什麼風把你吹來修道院的，外來者？", completion = "遺失的物品？\n\n這是我的，但我還在猶豫到底算不算遺失物。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82846] = {title = "凹陷的矛頭", objective = "又見面了。我能幫你什麼忙嗎？", description = nil, progress = "又見面了。我能幫你什麼忙嗎？", completion = "啊，我以為只是我自己亂放。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82847] = {title = "足夠的大蒜", objective = "為主廚收集大蒜。", description = "通常這樣就可以了。我沒有那麼挑剔。但你是客人。我們還需要一點大蒜。\n\n我在附近的山丘上發現了一些大蒜。它們不該出現在那裡的。但就是出現了。\n\n只可惜多頭蛇也發現了它們。\n\n你有武器之類的東西，對吧？", progress = "你覺得這樣就夠了？", completion = "啊，這樣就對了。這才叫足夠。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82848] = {title = "幫廚", objective = "協助主廚準備餐點。站在主廚的桌子旁，使用餐點預備技能進行協助。", description = "好了，現在幫我完成這道菜。", progress = "烹飪時間到！", completion = "謝了，陌生人。很高興能有人一起打發時間。祝你一路順風。", rewards = "您會收到：\n\n大蒜結燉肉汙漬斗篷共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][82849] = {title = "鑲鈿教士", objective = "廚房的人有什麼要求嗎？", description = nil, progress = "廚房的人有什麼要求嗎？", completion = "哎呀，你看看。我就在想這個東西放在哪裡。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82852] = {title = "特殊任務：山貓救援", objective = nil, description = "世界任務完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][82894] = {title = "希望的代價", objective = "在米雷達爾醫護站與鐵擊將軍會面。", description = "<name>，很高興見到你。我正準備出發去當地的醫護站。\n\n你願意加入我嗎？", progress = "我們失去了好多人，只要能救回來的就必須盡量救。", completion = "謝謝你，如果你可以改天再回來協助凱勒柏的話，我們會很感激你的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82895] = {title = "責任的重量", objective = "到崖側哨站找烏塔戈，幫助她進入狀況。", description = "我現在是悼念高地的管理員。\n\n我終於感覺到這份新的責任壓在我的肩膀上。這是一項殊榮，但我也必須做好萬全準備。\n\n拜託，幫我完成最後一步，一切就萬事俱備了。\n\n回到崖側哨站找我。", progress = "只差一步，我就能真正成為管理員了。", completion = "在科格蘭臨終之時，你讓他得到安息，現在又幫助我填補他的空缺。\n\n大恩大德，沒齒難忘。", rewards = "這個任務線有助於解鎖：\n\n土靈同盟種族\n\n您還會收到：\n\n共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][82916] = {title = "真菌開花", objective = "為多恩諾加的阿克丹收集20朵真菌花。", description = "你好！\n\n也許你可以幫我處理一些麻煩事？訂單太多了，我不小心算錯了真菌花的數量。老實告訴你，現在還缺非常多。\n\n可以請你發揮善心，幫我補齊不足的部分嗎？", progress = "我不是要催促你，但我真的需要盡快拿到真菌花。拜託了。", completion = "謝謝你，&lt;name&gt;！這些花品質很好。\n\n來，為了感謝你的不辭辛勞，請收下這個。", rewards = "您會收到：\n\n阿爾加草藥師筆記"}
MultiLanguageQuestData['tw'][82946] = {title = "滾入深處", objective = "收集10個奇怪的蠟塊。", description = "給你一個重要任務，行嗎？\n\n去找全都是蠟的東西。快點拿回來，好嗎？有多少，我收多少。\n\n快去到處聞吧，朋友！", progress = "你去聞了嗎？拿到我要的東西了嗎？", completion = "啊，真快回來！讓我看看那些蠟做的寶物。", rewards = "您會收到：\n\n日常儲物箱共鳴水晶深淵集會青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][82952] = {title = "放鬆的機會", objective = "在剛達加茲內部和周圍分發6張傳單給疲憊的工人。", description = "喂喂！沒錯，就是你了。你想要賺點錢嗎？我們正試著提振私人渡假村的生意。也許你聽說過？機會營地水療中心兼渡假村！\n\n老闆派我來剛達加茲分發這疊傳單，不過我的機動車拋錨了，我得留在這裡修好它。不如你替我跑一趟，去那裡發傳單？記得鎖定看起來很疲累的人。", progress = nil, completion = "你回來了！情況如何？我們該開始準備迎接團客了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82953] = {title = "真心邀請", objective = "在蛛絲城中為輔臣傳話。", description = "我現在看得很明白，我這個輔臣已經當不久了。我為阿茲-卡罕特效力的方式必須有所改變。為此，我想請你幫忙最後一件事，<name>。\n\n自從你來了之後，你在蛛絲城做了不少事。現在的你無疑是一個大名人。去找我們在城裡的盟友，請他們到晦影市集聚個會，我有事想傳達給他們所有人。", progress = nil, completion = "你集結了不少人。非常好。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82954] = {title = "暗箭難防", objective = "在蛛絲城中殺死4個蘇芮基刺客。", description = "你一定還記得上次我們在這裡見面時，那個想要殺死我的刺客。要不是你出手相助，我現在就不會站在這裡了。別誤會了，如果我在這一切當中扮演的角色受到威脅，就會面臨沒完沒了的暗殺。\n\n如果我想最後一次做出驚人之舉，我就需要你協助確保我的安全，直到最後一刻。清除潛藏在城市中的那些威脅，盡你所能確保他們不會打斷我的演說。", progress = nil, completion = "在我看來，先發制人是有點無禮。但在如今的情況下，我相信這種做法符合比例原則。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82955] = {title = "輔臣的決心", objective = "在晦影市集見證輔臣的演說。", description = "舞臺已經備妥，演員已經到來。該是我登場的時候了。\n\n謝謝你一直以來的鼎力相助，<name>。無論接下來會發生什麼事，我都很慶幸能與你相遇。", progress = nil, completion = "到此為止了。我人生的其中一章就此落幕。\n\n希望我們的城市能以全新的姿態面對未來。", rewards = "您會收到：\n\n輔臣的珍寶卡吉"}
MultiLanguageQuestData['tw'][82956] = {title = "前往機會營地", objective = "到機會營地喝一杯。\n\n已提供物品：\n", description = "幸好一切平安落幕。現在我的老闆可以不用再追殺我了！\n\n我還得修理一下我的機動車，不過你應該去機會營地看看！我甚至可以給你我們渡假村的免費飲料抵用券。\n\n去找格里茲‧芬格博，他會招待你。", progress = nil, completion = "歡迎來到機會營地！你有飲料抵用券，是嗎？馬上過去！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82957] = {title = "謝謝你的蠟", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][82958] = {title = "小小的祝福", objective = "為多恩諾加的阿克丹收集10朵祝綻花。", description = "喂喂！\n\n我的祝綻花快用完了，我訂的貨卻來不及送達。\n\n可以麻煩你去幫我採一些嗎？", progress = "你拿到我的草藥了嗎？", completion = "啊哈！感謝你的幫忙。真高興知道你是個辦事牢靠的傢伙。\n\n這是我小小的心意。不怎麼多，但希望能幫上你的忙。", rewards = "您會收到：\n\n阿爾加草藥師筆記"}
MultiLanguageQuestData['tw'][82959] = {title = "西爾海姆家族：遺失的日記", objective = "將遺失的日記交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<這本日記似乎屬於阿里雅‧西爾海姆。最好別看內容，直接還給她就好。>", progress = nil, completion = "喔，天啊，我不久前弄丟了那本日記。\n\n我在裡面寫了一些很讓人害羞的東西，老實說，有些故事甚至不是真的！", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82960] = {title = "西爾海姆家族：莉莉的墜盒", objective = "將莉莉的墜盒交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<這個墜盒一定對某個人很重要。也許阿里雅‧西爾海姆有一點頭緒。>", progress = nil, completion = "你找到它了！那是莉莉的墜盒。在婕塔嬸嬸出意外的那陣子，她不小心弄丟它。\n\n我們一直到處找它。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82961] = {title = "西爾海姆家族：雞", objective = "將雞交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<最好將這隻亂跑的雞送回去給西爾海姆農莊的阿里雅‧西爾海姆>", progress = nil, completion = "喔，偉柏，你這隻瘋狂的小雞！你永遠都在我最意想不到的地方出現！\n\n婕塔嬸嬸以前常常會到處追著偉柏跑，想找出牠到底躲去哪裡了。很高興你把牠帶回來了。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82962] = {title = "一把誘滴草", objective = "為多恩諾加的阿克丹收集3朵誘滴草。", description = "喂，沒錯，就是你。\n\n有沒有聽過誘滴草？那是一種很罕見的食蟲植物。雖然我們現在沒有昆蟲，但我希望能拿到一些樣本。要是你發現它們的蹤跡，就告訴我一聲，最好是直接帶來給我。", progress = "記住，它們相當罕見。", completion = "看看這個！這些樣本真棒。\n\n你應該跟我合作。我負責販賣，你負責供貨。", rewards = "您會收到：\n\n阿爾加草藥師筆記"}
MultiLanguageQuestData['tw'][82963] = {title = "西爾海姆家族：小豬豬", objective = "將小豬豬交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<最好將小豬豬送回去給西爾海姆農莊的阿里雅‧西爾海姆>", progress = nil, completion = "這隻小豬已經失蹤好幾天了，我一直祈禱牠能找到回家的路。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82964] = {title = "西爾海姆家族：叔叔的義眼", objective = "將叔叔的義眼交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<一顆玻璃義眼。這是相當珍貴的物品。也許阿里雅‧西爾海姆會知道是誰弄丟的。>", progress = nil, completion = "那是湯瑪斯叔叔的義眼嗎？\n\n每次去田裡散步，他都習慣把它到處亂放。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82965] = {title = "光與影", objective = "為多恩諾加的阿克丹收集5株阿拉索之矛和5株錐頭草。", description = "我現在還缺兩種草藥。\n\n一種是阿拉索之矛，另一種則極為罕見，名叫錐頭草。\n\n我知道你在想什麼，的確，某種程度上來說，這兩種都非常罕見，但我要求的數量不多，而且報酬絕對豐厚。\n\n你覺得呢？弄得到嗎？", progress = "你都弄到了嗎？", completion = "我就知道！\n\n你果然是我認識的草藥供應商裡最棒的。\n\n來，收下這個。該有的禮數不能少。", rewards = "您會收到：\n\n阿爾加草藥師筆記"}
MultiLanguageQuestData['tw'][82966] = {title = "西爾海姆家族：不尋常的馬鈴薯", objective = "將不尋常的馬鈴薯交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<這顆馬鈴薯的形狀相當奇特。幾乎跟某個名人一模一樣。阿里雅‧西爾海姆一定會想看看這個！>", progress = nil, completion = "這顆馬鈴薯太不可思議了。彷彿就像看到鐵擊將軍本人一樣！\n\n我會把它放在家裡展示。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82967] = {title = "西爾海姆家族：耳朵", objective = "將耳朵交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<令人極為不安的發現，你應該拿給西爾海姆農莊的阿里雅‧西爾海姆看。>", progress = nil, completion = "雖然這東西讓人很不安，但我很感激你找到它。在那場意外後，時不時就能在田裡找到婕塔的身體部位。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82968] = {title = "西爾海姆家族：犁頭", objective = "將犁頭交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<狀況極為良好的犁頭。西爾海姆農莊的阿里雅‧西爾海姆應該能好好利用它。>", progress = nil, completion = "衷心感謝你。這東西超級實用。當收割者故障的時候，很多犁頭都損毀了。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希勇氣石"}
MultiLanguageQuestData['tw'][82969] = {title = "追蹤石頭", objective = "掃描魔像留下的殘餘，透過三角測量找出它的位置。", description = "抱歉忍不住偷聽了。不是我在吹牛，但哥布林可是暴走機器人領域的專家。\n\n如果那個魔像和達那格說的一樣不穩定，它就會不斷洩漏各種能量。拿著這個，進行幾次掃描，你就會找到它了。喔，對了，小心一點。打開這個東西的時候，動物們會有一點點小發狂。\n\n服務免費。一個嗜殺的魔像對生意不太好。而且讓你忙來忙去只為了找一個死人讓我有點愧疚。", progress = nil, completion = "有意思。看來它正沿著河流到處閒晃。這不是重點，重點是有它的位置了。我們會找到它，然後報廢它。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82970] = {title = "花開富貴", objective = "為多恩諾加的阿克丹收集10朵真菌花和10朵祝綻花。", description = "嗨，那邊那位！\n\n我有個任務要給你。\n\n我需要一把真菌花，還有一些祝綻花。如果你願意接下這個任務，那些花能換到不錯的報酬。", progress = "報酬我已經準備好了，就等你把草藥帶來。", completion = "群山祝福我！\n\n很高興能跟你做生意。", rewards = "您會收到：\n\n阿爾加草藥師筆記"}
MultiLanguageQuestData['tw'][82990] = {title = "修復損害", objective = "在達那格修復變電站時保護他。", description = "很抱歉。奧巴赫不是來這裡維修的。是他偷走了那個魔像。\n\n奧巴赫和我在深淵裡最黑暗的地方跟它一起共事了許多年。工作讓那個魔像變得殘破不堪。它變得很混亂，甚至變得危險。我們原本打算報廢它，但當那一刻來臨時，奧巴赫無法承受這一切。他對魔像產生了感情。在它被摧毀之前，他搶走了魔像並逃走了。\n\n我們必須找到它，但這個變電站受到的損傷是很嚴重的。在你的幫助之下，我會嘗試修復這裡。", progress = nil, completion = "失去了一名工頭和一座變電站。可惡，我太大意了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][82992] = {title = "風暴充能商品", objective = "收集20張風暴充能皮革，交給多恩諾加的吉娜。", description = "你好，我的朋友！\n\n我正在找願意幫我跑個腿的人。我有些東西快用完了，但我已經有段時間沒有皮革供應商的消息了。如果我沒辦法補充獸皮和皮革，製皮師就無法製作皮甲。\n\n如果你能把大量的風暴充能皮革帶來給我，我會給你報酬。", progress = "有好消息嗎？我還是沒有皮革供應商的消息。", completion = "你拿到皮革了？讚美泰坦！", rewards = "您會收到：\n\n阿爾加剝皮師筆記"}
MultiLanguageQuestData['tw'][82993] = {title = "來自暗影", objective = "收集5個卡罕提蟲群甲殼和5個無日甲殼，然後交給多恩諾加的吉娜。", description = "你好啊！\n\n我聽說把某些…奇特的材料用針線串起，組合在一起，就能製造出相當神奇的材料。\n\n如果你正好喜歡到卡茲阿爾加最後一個有陽光照耀的地方旅行，能不能幫我收集卡罕提蟲群甲殼和無日甲殼？如果你能給我一些樣本，我會給你豐厚的獎勵。", progress = "我已經迫不及待想摸一摸這些材料了。", completion = "真是太奇特了。現在還不確定能用這些材料做出什麼。只能邊做邊看了，願泰坦保佑。", rewards = "您會收到：\n\n阿爾加剝皮師筆記"}
