MultiLanguageQuestData['tw'][83057] = {title = "設下界限", objective = "擊殺折磨維埃佐的奈幽晉升者。", description = "維埃佐經歷過一定程度的虐待，但我卻沒有發現。在他真正安全之前，我們都對於他的恐懼無能為力。\n\n可能的話，我會極力推崇友情、復原及和解。我要求其他人抱持同情心和同理心。每個人都應該要有康復的機會。我為此奉獻我的一生。\n\n但是，在聽到和看到維埃佐的遭遇後…我改變主意了。凡事都要適可而止。我們必須行動。", progress = nil, completion = "這些奈幽晉升者已經變異到不合常理的地步。我雖然痛心，但我必須拯救那些還有救的人，像是維埃佐。", rewards = "您會收到：\n\n將軍(惡名值)卡吉卡吉"}
MultiLanguageQuestData['tw'][83069] = {title = "特殊任務：泰坦復甦", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83070] = {title = "特殊任務：泰坦復甦", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83079] = {title = "礦物沉積", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83080] = {title = "清理泰洛科", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83081] = {title = "礦物不足", objective = "在多恩島的蛋白石礦場收集6個土靈火焰蛋白石。", description = "我沒想過蛋白石礦場會遭受攻擊！我相信布琳瑟也沒想過。\n\n保安官赫卡特不會讓我戰鬥，但也許她會讓你出馬。\n\n我會留在這裡照顧這個土靈。在多恩諾加待過之後，我學會了一兩個小技巧。\n\n喔，不過…布琳瑟真的很需要那些蛋白石…", progress = nil, completion = "火焰蛋白石？你找到了一些嗎？\n\n布琳瑟會很高興的！\n\n這個土靈似乎也比較舒服了。整體來說是個雙贏！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83082] = {title = "歐帕前線", objective = "在多恩島的蛋白石礦場殺死奈幽蟲族部隊。", description = "我是城市守衛，不是士兵！但這些人需要我們的幫助！\n\n奈幽蟲族的數量太多了，根本清理不完。我們只能守住這個隘口，祈望那些礦工能夠順利來到這裡。\n\n那傢伙太嬌小了。不過你看起來是個高手。幫幫我們！", progress = nil, completion = "謝謝你，外地人。你給了他們一個奮戰的機會。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83083] = {title = "遺忘之地", objective = "在多恩島的多恩諾加後面與代言者布琳瑟與達格蘭會面。", description = "多恩諾加後面有個地方…我進不去。\n\n而且我不是唯一一個。有可能是泰坦之力的某種東西阻止了土靈調查城市後方的那一小塊島上區域。\n\n這當然激起了我的好奇心。但千年以來，我都盡忠職守不去靠近那裡，如果這是泰坦所樂見的。\n\n那個站點散發出微弱的信號，就像這個裝置的一樣。也許這就是字面意義上通往該處的「鑰匙」。\n\n來一探究竟吧。", progress = nil, completion = "我無法形容這個地方帶給我的感受。\n\n這裡充滿了…壓迫感。我無法思考。\n\n想要回頭的衝動很…強烈。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83084] = {title = "上古命令", objective = "調查多恩諾加後方的廢棄高塔。", description = "很久之前，曾經有個計畫是要穿越山脈建造一條隧道，通往多恩諾加。\n\n在挖掘開始之前…附近的區域突然就被棄置不動了。\n\n沒有關於發生什麼事的紀錄。只有…一股威懾力，某種力場，讓土靈無法靠近這裡。\n\n我的認知矩陣的每一部分都在迫使我…離開。但我們必須堅持下去。\n\n裝置的信號顯示附近的塔裡有什麼東西。", progress = "我不確定是什麼在殘害著布琳瑟，但很顯然她受到了莫大的痛苦。我提出要護送她回到城市，但是她拒絕了。\n\n我會和她待在一起，確保她不會變得更糟糕，順便再多研究一下這個裝置。", completion = "忘掉你在塔裡發現的東西吧，你看到那個了嗎？！他們看起來像是泰坦看守者！\n\n但是…這一切代表著什麼？他們究竟是誰？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83087] = {title = "上古衛兵", objective = "依循信號，見證第二段記憶。", description = "多尼克…珈蘭…我在舞臺那裡有聽過這些名字！\n\n不過是誰在說話？他們對珈蘭並不滿意。所有這些土靈的身體…\n\n重新定義用途…就像是被改寫那樣嗎？為了守護什麼東西？\n\n我們去追尋另一個信號吧。看來它正通往前方的山丘。\n\n我要待在這裡和布琳瑟一起進一步調查這座塔。裝置讓你帶走。", progress = nil, completion = "你看到了另一個記憶？而且它攻擊了你？\n\n聽起來超讚…我是說，還好你沒事。\n\n你在追蹤訊號的時候，我找到了一些筆記。我把它們整合了一下好方便你閱讀。裡面有更多關於多尼克與珈蘭的內容。\n\n至少我們知道珈蘭他們最後去了哪裡…而不是被掩埋在無數的岩石底下。但是她在守護的東西到底是什麼？\n\n是什麼這麼重要，讓她被改寫程序，只為了守護那個東西上千年？\n\n啊！我們的問題越來越多了。我不喜歡這樣。", rewards = "您會收到：\n\n重組的帳本共鳴水晶共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][83088] = {title = "腐蝕性收集物", objective = "到大桶工廠，從酸性回收物收集6份刺痛殘渣。", description = "伯森科是我的老闆，也是我的老師。過去曾是最棒的潛泥員！但現在…\n\n跟他無關，潛泥已經變得跟以往不同！軟泥怪變得越來越毒。\n\n我認為，狀況已經太糟了，我們都應該配戴護眼裝備，大家都要。但老森科非常墨守成規。需要多一點紅眼案例，才能說服他。\n\n那就是你登場的時候。如果你可以從真的很噁心的軟泥怪身上取得殘渣樣本，我或許就能讓老森科接受現實！", progress = "你從滲液回收物找到足夠的殘渣了嗎？\n\n一定要拿到真的很噁心的東西。你知道的，就是會黏在你身上，還會溶化你的皮膚的東西。", completion = "沒錯！就是這東西！\n\n也許森科這次會聽我的…", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83089] = {title = "發放哥布林護目鏡", objective = "到大桶工廠與5個潛泥員談話。", description = "我的老師森科或許是這裡嗓門最大的人，但需要幫助的人不是只有他。\n\n我們整群人都只聽命於他！這意味著沒人配戴恰當的防護裝備。\n\n帶著這些護目鏡，說服大家在工作時試用一下。要是他們都開始改變想法，或許森科會聽進去。", progress = nil, completion = "&lt;卡贊德菈發出歡呼。&gt;\n\n太好了！大家都在這裡，而且都配戴護目鏡。森科這次最好聽我的！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83091] = {title = "保護眼睛", objective = "在大桶工廠擊敗酸蝕怪。", description = "酸蝕怪？他瘋了？從沒有人能夠解決那隻怪物！\n\n我們必須在森科弄傷自己之前阻止他！\n\n酸蝕怪就潛伏在這條運河中。帶著你的護目鏡，跟我來！", progress = nil, completion = "他沒事！非常感謝你的幫忙，&lt;name&gt;！", rewards = "您會收到：\n\n潛泥員長褲潛泥員束腰潛泥員手套潛泥員外衣共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83092] = {title = "葬送的岩漿", objective = "將聖落之地大門附近的下葬的土靈從石棺中救出來。", description = "當輸送岩漿的管子故障時，我們的工人立刻衝下去修理。\n\n我們被那些元素生物打個措手不及，它們突然現身，用一團團熔岩發動攻擊。\n\n幸好我們土靈都是用堅固的材料製成，一點點岩漿不足以殺死我們。不幸的是，岩漿冷卻後會硬化成岩石棺材，工人們紛紛立在原地，變成石像。\n\n擊碎石棺，救出我的工人！", progress = nil, completion = "謝謝你，地表人。既然工人都回來了，我們就可以繼續工作了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83096] = {title = "歡迎來到幽坑城", objective = "與葛麗菈一同前往內陸飯店，了解幽坑城的更多資訊。", description = "你來啦！我是葛麗菈。歡迎來到幽坑城。如果你想即時掌握目前的狀況，那你找對哥布林了。帕姆西替你做過擔保，這對我來說就很足夠了。\n\n我有一張內陸飯店的優惠券可以給你用。我們就從那裡開始吧。\n\n我們開我的改裝車「葛朗普斯」去吧！等你準備好了就上車。", progress = nil, completion = "所以，那就是內陸飯店。現在事情要開始急轉直下了。", rewards = "您會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83097] = {title = "餘燼與風暴", objective = "收集5個瓶裝風暴與5個燃燒的燼蜂剛毛，並把它們交給多恩諾加的吉娜。", description = "這些野生動物有著驚人的特性。我在想，如果我把這些特點融合在一起，究竟會發生什麼事？\n\n多加留意瓶裝風暴和燃燒的燼蜂剛毛吧。如果你能帶給我一些樣本，我會好好犒賞你的。噢，如果你要親自收集的話，要小心別被燒到或電到，甚至是燒到「和」電到。", progress = "天曉得我們把這些材料混合在一起會有什麼結果！", completion = "太好了！我等不及要開工了。", rewards = "您會收到：\n\n阿爾加剝皮師筆記"}
MultiLanguageQuestData['tw'][83098] = {title = "裂片與轟雷", objective = "收集5個鋒利的骨頭裂片與2個雷霆毛皮，並把它們交給多恩諾加的吉娜。", description = "可以耽誤你一下下嗎？\n\n我在找一些特殊的材料。要有銳利的切面，還有尖銳又滋滋作響的材料。如果你能幫我找一些鋒利的骨頭裂片跟雷霆毛皮，我願意好好犒賞你。", progress = "把這些材料混合在一起後，就可以驗證我的想法了。", completion = "這就是我要的！我等不及要好好利用它們了。", rewards = "您會收到：\n\n阿爾加剝皮師筆記"}
MultiLanguageQuestData['tw'][83099] = {title = "合併與併購", objective = "打敗戈蒂‧貝倫巴特，並協助溫布蘭特奪回燼釀酒莊。", description = "奈幽蟲族攻擊了我的酒莊，讓它只剩下一副燒光的空殼。阿德貢答應要重建酒莊，但我等不及了，就接受風險投資公司的「重建」計畫。\n\n但現在，他們很明顯另有打算。這些討人厭的哥布林已經掌控了這個地方，還拼命壓榨這裡。他們全力提高產能，把燼蜂跟設備都推向極限。\n\n<name>，幫我彌補這個錯誤吧。", progress = "一想到這些哥布林在我的酒莊裡亂搞…噢，我的頭就痛到要裂開。那也讓我想念我的燼釀蜜酒了！", completion = "我非常感謝你為燼釀酒莊所做的事。\n\n把風險投資公司趕走可不是件簡單的事，不過多虧有你，我們才能奪回摯愛的酒莊，才能用正確的方式釀出燼釀蜜酒…那可是傳承了幾百年的古法啊。", rewards = "嚼嚼大廚的毛巾您能選擇下列奬勵中的一個：\n\n繫繩救援酒桶就職85年紀念戒指\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83100] = {title = "擊破外殼", objective = "收集20個幽影甲殼，並把它們交給多恩諾加的吉娜。", description = "歡迎！\n\n你絕對無法相信我們會用上多少東西，這還沒算稀有材料之外的呢！我們需要更多的幽影甲殼。如果你有找到的話就交給我吧。我保證會給你報酬。", progress = "你有找到一些了嗎？", completion = "時機正好，我們剛好快用完了。", rewards = "您會收到：\n\n阿爾加剝皮師筆記"}
MultiLanguageQuestData['tw'][83101] = {title = "取得資源", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83102] = {title = "鉍不可少的生意", objective = "收集20個鉍礦，並交給多恩諾加的塔利。", description = "你知道採礦作業的基礎是什麼嗎？不是挖到那些閃亮亮的稀有礦石，而是挖到好品質的普通鉍礦。\n\n我們從來都不夠用！不論你到哪裡，記得多加留意一下鉍礦。找到多少就都給我吧。\n\n我會給你報酬的。", progress = "這是門鉍不可少的生意，而且生意還在成長！", completion = "你回來啦？感謝。看來你很熟悉礦鎬的使用方式。", rewards = "您會收到：\n\n阿爾加礦工筆記"}
MultiLanguageQuestData['tw'][83103] = {title = "取得亞基岩", objective = "收集10個亞基岩，並交給多恩諾加的塔利。", description = "嘿，就是你！\n\n你有聽過亞基岩嗎？它很有價值、能廣泛運用，但附近也經常有奈幽蟲族。\n\n我需要那種礦石，我也不管你用什麼方法幫我弄到手。如果有奈幽蟲族想阻止你，就幫我大力打他們吧。", progress = "那麼，你拿到了嗎？", completion = "我從來不會拒絕亞基岩。我會把它交給需要的人。", rewards = "您會收到：\n\n阿爾加礦工筆記"}
MultiLanguageQuestData['tw'][83104] = {title = "找出鐵爪礦", objective = "收集10個鐵爪礦，並交給多恩諾加的塔利。", description = "我派了一個小隊去挖鐵爪礦，但他們卻說什麼都沒看到。你相信這種事嗎？那是個冒出地面的大爪子耶！\n\n我不會再派他們去挖了。我相信你看到鐵爪礦的時候一定會認出來的。把礦石交給我，我就會獎勵你。", progress = "相信我，你不會錯過的。", completion = "太感謝你了。我就知道我可以靠你。", rewards = "您會收到：\n\n阿爾加礦工筆記"}
MultiLanguageQuestData['tw'][83105] = {title = "急件要求", objective = "收集5個亞基岩跟5個鐵爪礦，並把它們交給多恩諾加的塔利。", description = "很高興看到你，我有工作要交給你。\n\n有鐵匠在最後一刻送出要求，需要一些稀有礦石。那些臭打鐵的，提早安排有這麼難嗎？嗯，我相信你一定有辦法處理。\n\n看來你得去找一些亞基岩跟鐵爪礦了。", progress = "你拿到手了嗎？那些鐵匠快唸到我耳朵長繭了。", completion = "幹得好。這些礦石會大大派上用場。", rewards = "您會收到：\n\n阿爾加礦工筆記"}
MultiLanguageQuestData['tw'][83106] = {title = "開採空無石", objective = "收集10個鉍礦跟2個空無石，並交給多恩諾加的塔利。", description = "有看過空無石嗎？嗯，你有機會看到的。它們十分稀有，但我們知道要怎麼使用它們。別擔心，我只需要一些而已。\n\n尋找空無石的時候，順便開採一些鉍礦吧。鉍礦永遠不嫌多。", progress = "有找到空無石嗎？", completion = "太棒了！希望你找這些石頭的時候沒有遇到麻煩。", rewards = "您會收到：\n\n阿爾加礦工筆記"}
MultiLanguageQuestData['tw'][83108] = {title = "每日診斷", objective = "收集石庫中4台機械的診斷讀數。", description = "我的責任是每天取得診斷讀數，決定石庫偉大機械的輸出量與運轉效率。這是我的重擔，也是我的榮耀。\n\n說明問題：現在斯卡汀佔據了石庫，我沒辦法接近我的機械！\n\n建議解決方案：我聽說你是個出名的英雄。麻煩你幫我進去收集今天的讀數吧。如果出了什麼差錯，就得盡快處理。等待確認。", progress = nil, completion = "感謝你幫我取得那些讀數。希望分析結果顯示偉大機械的運作一切正常。\n\n在狀況安全到能讓我們返回石庫之前，我就一直困在這裡幫我的裝備散熱。但至少我知道今天的讀數了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83109] = {title = "葛麗菈特快車", objective = "搭乘葛麗菈的改裝車前往尾門公園。", description = "下一站：尾門公園。污水企業聯合曾經掌管那裡，但加里維克斯有其他的計畫。現在暗融表現得好像那個地方和污水企業是屬於他們的…好吧，他們確實盡力了。\n\n假設現在有人在負責經營那裡，我也不確定到底是誰。", progress = nil, completion = "他們很敬重加茲魯維。也許你們去露個臉能給他們一絲希望。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83114] = {title = "繁文縟節", objective = "在猛擊中央站尋找艾蘭里亞。", description = "一開始的麻煩只有黑血，現在還扯到以太族？\n\n我不知道這一切的關連，但如果我們想知道的話，就必須請來幫手。\n\n歐薇娜在不久前去找艾蘭里亞了。我們應該去猛擊中央站，看看他們下來了沒。", progress = nil, completion = "既然艾蘭里亞來了，我們來查出事情的真相吧…就從諾格弗格開始。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83115] = {title = "撲朔迷離", objective = "在大桶工廠與馬林‧諾格弗格交談。", description = "我不認為諾格弗格有介入其中，但要知道這點的唯一辦法，就是和他本人談談。\n\n熱砂企業的總部或許是個開始找他的好地方。\n\n我們會給他一個為自己辯解的機會。如果是個誤會，或者只是他惹上了什麼麻煩，我必須要知道。", progress = "你看到他們這裡有多少暗融的人了嗎？", completion = "&lt;加茲魯維壓低音量。&gt;\n\n這個地方到處都是暗融的人。諾格弗格被嚴密監視了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83116] = {title = "藥水騷亂", objective = "收集一些略顯豪華的諾格弗格藥劑，然後使用它們來引開8名駐紮的實驗室守衛。", description = "能看到你和加茲魯維真的是太好了！我剛剛才在想，我有多想在我生日當天見到你們兩個。\n\n這天是我不會受到任何形式的威脅和壓迫的一天！完、完全沒有。\n\n<他小心翼翼地瞄了一眼暗融守衛，接著對你低語。>\n\n如果我能擺脫他們，我就把我知道的事都告訴你。\n\n<他悄悄地對著他的鍊金工作臺點頭。>", progress = "我會盯著諾格弗格。你去把事辦好。", completion = "風險投資公司和卡迦邁。又多了兩塊拼圖。\n\n希望到了最後它們能拼湊在一起。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83117] = {title = "追隨線索", objective = "在垃圾場外與加茲魯維會合。", description = "風險投資公司其實從來都不是一個優秀的集團。他們的忠誠非常廉價，而且他們對於不擇手段達成目的不會感到內疚。\n\n我們知道他們正在與加里維克斯合作，只是不知道他們到底牽涉得多深。\n\n我們去看看那些卡迦邁補給線吧。沒時間浪費了。", progress = nil, completion = "一大堆暗融，但比在熱砂企業的人數還要少。大概是因為風險投資公司比較聽話。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83118] = {title = "檢查時程表", objective = "收集3張員工時程表。", description = "如果要說一件風險投資公司做得井然有序的事，那就是他們的文件。他們在分配勞動力和讓一切事務如期進行這兩件事上真的是一絲不苟。他們很有效率，這點我不否認。\n\n前面就是他們的其中一座廢料場了。這個地方應該到處都有張貼時程表，讓風險投資公司的員工紀錄他們的工時，並查看他們接下來的工作。\n\n盡量把你找到的時程表帶來。這段期間我們會去看看風險投資公司的總部。", progress = "這個地方應該到處都有張貼時程表。希望這不會像在追野生紅鶴一樣難。", completion = "&lt;加茲魯維快速閱覽時程表，他的神情逐漸變得失望。&gt;\n\n好吧，好消息是諾格弗格沒有說謊。\n\n但壞消息是…這牽涉到很多名字。全部人都被派往了祖達薩的卡迦灣。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83119] = {title = "值得一試", objective = "嘗試說服10名廉價勞工退出風險投資公司。", description = "風險投資公司有非常糟糕的業績記錄，但並非每個為集團工作的人都是壞消息。我們中的一部分人正在努力維持收支平衡。\n\n也許我們可以跟其中一些人講道理。更少風險投資公司員工，就代表更少人幫加里維克斯做他的骯髒勾當。\n\n風險投資公司雇用了很多非哥布林員工，所以只要你穿著制服，就不會有人懷疑你為什麼在場。我有一件備用制服，你大概、可能、或許穿得下。\n\n試試看你能不能勸他們退出。如果他們想跟你打，你就做你該做的事吧。", progress = nil, completion = "這樣就行了。\n\n就算少一個為加里維克斯工作的哥布林，對我來說都算成功。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83120] = {title = "偷取鑰匙卡", objective = "殺死領頭工頭克羅姆。", description = "如果你想進到像卡迦灣這樣的機密工作場，那就得從這裡的克羅姆辦公室弄到一張穿孔卡片。\n\n領頭工頭克羅姆是這裡的老大，負責分配風險投資公司的人力。\n\n要溜進去拿走穿孔卡片對雷吉克來說應該相當簡單，但你必須解決掉克羅姆和他的看門土狼。如果我們想過去卡迦灣，那我們首先不能變成寵物咀嚼玩具，對吧？", progress = "你清出一條路，讓雷吉克能夠去拿穿孔卡片了嗎？", completion = "&lt;加茲魯維一邊檢視著工頭的武器，一邊皺起眉頭。&gt;\n\n這東西的電池是由黑血提供動力的。\n\n我不知道他們是怎麼在不讓它爆炸，或是更糟的情況下辦到這件事的。但現在的情況變得比之前更加危險了。", rewards = "您會收到：\n\n破衛者胸鎧破衛者長靴破衛者裹腕破衛者頭盔勇氣石"}
MultiLanguageQuestData['tw'][83121] = {title = "資產管理", objective = "在幸運一擊礦場殺死6名風險投資公司主管。", description = "你不在的時候，我迅速地查看了一下前方的礦坑。看來他們在讓風險投資公司開採所有的卡迦邁，並把它們運送到海灘那裡。卡迦邁在那裡被打包，但我不知道之後它們會被運往哪裡。\n\n我們必須從源頭將補給切斷。把礦坑裡的主管解決掉，我敢打賭他們的工人在那之後就會有逃跑的念頭了。", progress = nil, completion = "很好。這裡對加里維克斯效忠的風險投資公司員工越少，就對我們越有利。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83122] = {title = "市場崩盤", objective = "在幸運一擊礦場摧毀5個卡迦邁儲備。", description = "當我讓污水企業聯合負責在祖達薩開採卡迦邁時，一切都是既乾淨又安全。至少比現在更乾淨、更安全。我們跟贊達拉人做了一大堆交易才達成這個目標。所以，加里維克斯不只入侵我們的地盤，還讓風險投資公司胡作非為，對我們好不容易才得到的尊重和信賴造成威脅。\n\n炸掉你在礦場中找到的卡迦邁儲備。我不會讓任何不正當的卡迦邁外流，不管買方或賣方是誰。", progress = nil, completion = "等這件事完成之後，污水企業會回來這裡收拾殘局，再用正確的方式接管這裡。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83123] = {title = "礦工危機", objective = "閱讀弄皺的薪資單，然後將其帶回去給加茲魯維。", description = "<在風險投資公司員工的屍體上，你發現了一張被塞進信封裡的皺巴巴紙張。它似乎是來自幽坑城的風險投資公司區域的卡迦邁倉庫薪資單。\n\n在雇主的完整住址下方，有一個用紅色墨水蓋下的標頭。\n\n加里維克斯的秘密卡迦邁倉庫 - 僅限內部使用，請勿實際將其印出\n\n<一張加里維克斯的紙條被用膠帶隨意地貼著薪資單背面。>", progress = nil, completion = "嗯，這樣一來就真相大白了。\n\n付錢給風險投資公司的是加里維克斯在幽坑城的其中一間秘密倉庫。\n\n這就代表他把所有的卡迦邁都存放在那裡。他到底要用這麼多卡迦邁做什麼？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83124] = {title = "B.I.R.D.監視中", objective = "在卡迦灣控制改造的B.I.R.D.來監視暗融的行動。", description = "我拿你收集來的零件，並把部件熱線連接到一些新的機械上，然後把它們塞回機器人裡面。現在可以用這個遙控器控制它了。遙控器還能讓我們看到和聽到機器人的所有見聞。\n\n我不認為靠打打殺殺就能得到我們需要的情報。我們必須用加里維克斯的方式打敗他，監視他的工人。\n\n<name>，你想要幫我們的忙嗎？我會教你怎麼做。", progress = nil, completion = "這最後一個拼圖了。加里維克斯用了黑血和卡迦邁製作那些武器，而他現在要用來修復黑暗之心。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83125] = {title = "價格上漲", objective = "殺死監督者德里茲，然後在幽坑城與加茲魯維會合。", description = "所以諾格弗格沒有說謊。暗融用武力脅迫熱砂企業研究出讓卡迦邁容納黑血的方法。看來這就是他們如何把它裝進武器裡，卻不會引發爆炸…或是更糟糕的情況的辦法。\n\n這些利害關係比我想的還要複雜，而且我有預感這還能牽扯到更深的層面。我必須把諾格弗格帶到安全的地方。你和雷吉克去解決掉監督者，然後回熱砂企業和我們會合。", progress = nil, completion = "可惡…諾格弗格傷得很重。\n\n首先是暗融，現在又有以太族。他們到底想要熱砂企業怎麼樣？", rewards = "您會收到：\n\n渦輪排氣管5000型勇氣石"}
MultiLanguageQuestData['tw'][83126] = {title = "以太入侵", objective = "在大桶工廠殺死12名以太族。", description = "不久之前，這些以太族憑空出現。他們攻擊了諾格弗格，試著把他抓走。我很快就解決第一批攻擊者，但他們源源不絕。\n\n現在他們在徹查每一棟建築，殺死所有攔住他們去路的人。\n\n我不知道他們在找什麼，但我們不能讓他們繼續這場屠殺。\n\n來給他們上一課吧。", progress = nil, completion = "以太族沒有料到會在這裡遇到反抗。他們大錯特錯了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83127] = {title = "分秒必爭", objective = "前往垃圾場，在加里維克斯的秘密倉庫外與加茲魯維會合。", description = "我們之前是時間所剩無幾，但現在我們真的是一點時間都不剩了。\n\n以太族會搶在我們之前到倉庫，但或許我們可以搶在他們之前找到黑暗之心。\n\n快走吧！", progress = nil, completion = "至少以太族把大部分的暗融都解決掉了。這或許…對我們有利。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83128] = {title = "拯救族人", objective = "解救加里維克斯關押在倉庫裡的人質，並殺死10個以太尋心者。", description = "艾蘭里亞去尋找黑暗之心，我們則去找人質。希望他們平安無事。\n\n他們留下了一些伏擊者，不過我們這邊也有軍情七處的高手。要是發現那些伏擊者，就替雷吉克指出來。他會丟出煙霧彈。那會把他們逼出來，並使他們昏迷，我們就能扭轉情勢。", progress = nil, completion = "人質安全了。加里維克斯已經無法再操弄任何一個集團了。\n\n是時候了結一切了。", rewards = "您會收到：\n\n解放者長袍解放者肩衛解放者脛甲解放者繫腰勇氣石"}
MultiLanguageQuestData['tw'][83129] = {title = "無處可藏", objective = "摧毀臨時路障，然後跟隨加茲魯維進入物資庫面對加里維克斯。", description = "這個路障看起來很可疑。荷巴爾特說過加里維克斯去了一個洞穴，要我說的話這看起來就是了。\n\n加里維克斯一定是把黑暗之心藏在裡面。幫我把那個路障炸飛，然後做好戰鬥的準備。", progress = nil, completion = "&lt;加茲魯維重重地吐了口氣，怒視著冒煙的傳送器。&gt;\n\n結束了。我們離開吧。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83130] = {title = "苦澀勝利", objective = "在污水淺灘的廢料工坊與加茲魯維會合。", description = "好了。結束了。我們到此為止。\n\n加里維克斯失敗了，但以太族拿到了黑暗之心。\n\n艾蘭里亞必須去追蹤他們。我們得回去污水淺灘查看每個人的狀況，然後我們就必須離開了。我們在這座城鎮裡已經沒有什麼可以做的了。", progress = nil, completion = "&lt;加茲魯維雙臂交叉，盯著遠處空無一物的位置。&gt;", rewards = "您會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83137] = {title = "當機會爆炸", objective = "調查機會營地被炸開的洞口。", description = "你來啦，<name>！你聽說最新的消息了嗎？在鳴響深淵的機會營地旁的山坡被炸出了一個大洞。\n\n有些投機者已經過去了。我們最好快點趕過去。", progress = nil, completion = "這是…收費站？\n\n你一定是在跟我開玩笑吧。\n\n&lt;蒙特‧加茲魯維翻了翻白眼，發出幾聲輕笑。&gt;\n\n看來沒有什麼東西是不能賺錢的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83138] = {title = "事件落幕", objective = "與雷吉克交談。", description = "斯普琳科和海角沒事。馬林跟荷巴爾特會好起來的。我們未能阻止加里維克斯，但至少黑暗之心…已經不在他手中。\n\n這代表我們可以離開了。我們在這裡已經沒什麼事可以做了。\n\n把你在幽坑城要辦的事做個收尾。我得離開這個該死的地方。", progress = nil, completion = "&lt;加茲魯維從臉頰上擦掉某種灰白的東西，他在低頭凝視它的同時，手也在顫抖著。&gt;", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83139] = {title = "混合訊息", objective = "在收費站支付入場費，然後在北邊的哥布林營地收集情報。", description = "更多工人要前往附近的風險投資公司營地。那裡是非常適合收集情報的第一站。我們付一下入場費吧。目前最好的做法就是乖乖配合。", progress = nil, completion = "也許那個把牆炸掉的幕後黑手也想把我們的注意力吸引到這裡。我們得繼續追查下去。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83140] = {title = "敵對工作環境", objective = "殺死暗融，為加茲魯維和雷吉克吸引注意力。", description = "比機會營地更大更危險？就算你對惡劣的工作環境有很高的容忍度，這些南邊的礦坑聽起來也很糟糕。不過他們在開採什麼？這裡的某種東西非常值錢。我們得查出那是什麼。\n\n我會和雷吉克一起溜過那個大型暗融營地，當然是用潛行模式。盡量幫我們吸引注意力，好嗎？我相信你在這裡可以拖慢生產的速度。", progress = nil, completion = "所有目光都集中在你身上，非常好。而且你還幫我們帶來了這個叫吉多的新資源？想法不錯。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83141] = {title = "礦工調查", objective = "與歐薇娜檢視可疑的罐子和木箱。", description = "他們在從土裡開採什麼「寶物」？\n\n這個深掘行為是否與我的幻象有關？不用說，這些哥布林一定不會覺得黑血有什麼價值。我們必須靠近一點觀察。我們合作的話，就能查出他們這項行動的目的。", progress = nil, completion = "我的幻象顯示南邊還有更多。我們應該快點出發。\n\n你找到的這名哥布林握有更多情報嗎？", rewards = "您會收到：\n\n可疑染污肩衛可疑染污腿甲可疑染污護脛可疑染污裹腕勇氣石"}
MultiLanguageQuestData['tw'][83142] = {title = "重大命令", objective = "將加里維克斯的懸賞單交給加茲魯維。", description = "<這份文件要求任何知道是誰炸開了西邊牆壁的人員，將情報傳達給他們的主管。\n\n上面詳細記載了獎勵：升職到幽坑城內工作。其中也包括了加里維克斯給予恩惠和「讚賞」的承諾。\n\n加茲魯維會想知道這件事的。>", progress = "你有什麼發現？", completion = "加里維克斯正在直接控制暗融，並且想查出是誰在跟他作對。這裡可能有我們的盟友。這是一條重大的線索，&lt;name&gt;。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83143] = {title = "踏實導遊", objective = "跟隨吉多接受他的「導覽」。", description = "你是新來的，對吧？從你問的問題我就能聽出來了。但是別擔心，吉多是你最好的朋友！\n\n我會為你提供個人化的導覽。風險投資公司的城鎮「排水溝營地」就位於這條路的南邊。過程會充滿各種資訊和互動。你絕對沒辦法找到比這更好的體驗了，相信我！", progress = nil, completion = "我無話可說了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83144] = {title = "放血", objective = "殺死黑血生物，並指示歐薇娜攻擊管路的弱點。", description = "腳下的土地在隱隱作痛。這些管路將大量的黑血輸送到北方！\n\n我從沒見過大地以這麼快的速度被感染。淨化腐敗的地方，也許我們還來得及拯救它。\n\n我來處理這些管路結構。當你發現弱點時把它們指出來，我會集中發動攻擊！", progress = "這些哥布林帶來的恐怖對這片土地來說毫無疑問是場疫病。", completion = "我不信任任何該為這條管路負責的哥布林。\n\n小心一點，&lt;name&gt;。", rewards = "您能選擇下列奬勵中的一個：\n\n淨化之環淨化之戒\n\n您還會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83145] = {title = "偏執預防", objective = "調查排水溝營地的間諜問題。", description = "加里維克斯在排水溝營地尋找什麼資訊？來看看這些哥布林能不能給我們一點提示。\n\n就從我們能找到的污水企業哥布林開始問起吧。", progress = nil, completion = "但願雷吉克能在吉多洩密前追上他，但我們不該抱太多希望。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83146] = {title = "帕姆西的寶貴泵浦", objective = "前往泵浦站並與帕姆西會合。", description = "我有一支工程師團隊。全員都有家庭。他們一直遭遇可怕的意外和黑血的感染。我無法再忍受有人死去了。我炸開了牆壁。我祈求這樣能為我們帶來一點希望。\n\n而你帶著阻止黑血的意圖現身了。停止這裡的管路不會有任何成效。我們得去泵浦站。\n\n所以，我的團隊和泵浦？他們都在同一個站點。但我們應該盡快行動。", progress = nil, completion = "真不敢相信。吉多一定是跟監督者哥茲克說了我的事。這個訊息很顯然是在告訴我們停手…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83147] = {title = "血雨腥風", objective = "為歐薇娜殺死血懼。", description = "這裡的黑血之懼不容小覷。它在這個地方的力量導致我的幻象變得遙遠，就像怪異的低語。\n\n在這場腐敗的實體變得更強大之前，將它們殺死。", progress = nil, completion = "要修復這些傷口得付出更多的努力。我們還不能休息。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83148] = {title = "極度冰冷", objective = "殺死凍腸軟泥怪以收集凍爆罐。", description = "我和帕姆西想出了一個點子。既然我們無法取得控制權，沒辦法將它炸毀，那如果我們把泵浦站凍住呢？\n\n跟我來！\n\n帕姆西提到近期在北邊有很多過熱的機械，因為所有的冷卻劑都拿去用在南邊了。也因為血軟泥會把它們吃掉，所以更難取得。假如我們把所有的冷卻劑存貨都找出來，把它們通通倒進去泵浦站會發生什麼事？\n\n我們會讓整場行動徹底凍結，要花上不少時間才能修復！", progress = "拿足以把這個泵浦站凍到硬梆梆的量！", completion = "很好，這麼多一定夠了！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83149] = {title = "報仇雪恨", objective = "殺死殺害帕姆西的工程師的暗融。", description = "我跟著吉多的蹤跡到了南邊，還找到一個名叫哥茲克‧輪鶴的壞傢伙。他四處逼迫工人，還說著什麼「另一場教訓」。吉多一定偷偷向這個哥茲克告密了，但我想要確認一下。我認為這個哥茲克身上一定有證據。\n\n哥茲克原本是可以下令就好的，但看到那台該死的伐木機，還有帕姆西的工人身上的痕跡，我很肯定他一定是親自出手。你也得出手。殺死哥茲克，看看他身上有沒有吉多告密的證據。", progress = "這些工程師不該有這樣的待遇。", completion = "你找到證據了？我就知道。雖然不如抓住吉多本人，但我們最後一定會逮到他的。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83150] = {title = "擴大計畫", objective = "騎乘火箭滑板，使用寒冰射擊管路。", description = "計畫是這樣的。如果我們只凍住表面，它很快就會融化，然後回歸正常。但我們有歐薇娜在。她能鎖定管路的裂痕和洩漏處，這樣一來冷卻劑就能進到內部把一切都搞砸。\n\n既然所有的冷卻罐都是你收集的，我認為把管路凍住的殊榮應該由你來執行。\n\n帕姆西有一個火箭滑板，你可以乘坐它讓冰冷的正義降在泵浦站的重要區域。跟上歐薇娜！", progress = "跳上火箭滑板，開始射擊！", completion = "冰得漂亮！哈！", rewards = "北地長矛北地施術杖北地戰斧北地之刃北地法劍北地猛擊錘北地步槍北地凶器北地戰刃北地巨劍北地斬斧您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83151] = {title = "深入幽坑城", objective = "與加茲魯維談話，然後使用火箭鑽頭前往幽坑城。", description = "我們在這裡能做的事已經完成了。該去看看幽坑城的狀況了。\n\n帕姆西有一個聯絡人，是一個叫葛麗菈的風險投資公司哥布林。等我們到那裡之後，可以先去拜訪她。\n\n我們去找加茲魯維，然後就出發吧。幽坑城可不是那種用小刀就能解決的問題。我們的隊伍裡需要有加茲魯維這樣的人才有希望。你懂的，就是建造者和領導者的類型。", progress = nil, completion = "希望雷吉克和帕姆西知道他們和葛麗菈在這裡做什麼。", rewards = "您會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83152] = {title = "熔岩管理", objective = "在聖落之地大門附近殺死復生熔岩與熔渣泡泡。", description = "管道不通就夠麻煩了，還有一大群岩漿元素在出問題的時候湧出來。\n\n那地方充滿危險，我們可不能冒險派人下去修理，但那些熔岩對深淵的運作十分重要。\n\n如果可以的話，還得請你清理一下，這樣熔岩才能再次流通。", progress = nil, completion = "表現得很好。這樣我們工作時不用再心驚膽跳了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83153] = {title = "氣體採樣", objective = "站在聖落之地大門附近的通氣孔裡，並在噴發時收集樣本。", description = "熔岩累積起來的效果顯而易見，但我們還不了解造成這個現象的原因。\n\n為了找出與杜絕問題，我需要那些從地面冒出的火山氣體樣本。\n\n我要新鮮的樣本。最新鮮的那種。\n\n氣體噴發的時候，你得站在裡面，這樣才能收集到我想要的東西。", progress = nil, completion = "希望這些樣本能讓我們找出問題在哪裡。感謝你的協助。", rewards = "土靈旅行者盾牌土靈旅行者權杖土靈旅行者軍刀土靈旅行者匕首土靈旅行者法杖土靈旅行者手斧土靈旅行者裁決錘土靈旅行者巨刃劍土靈旅行者標槍土靈旅行者火槍土靈旅行者十字弓土靈旅行者砍斧土靈旅行者之拳您會收到：\n\n共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][83154] = {title = "東東的東東", objective = "從暗焰裂縫中取回東東的寶藏。", description = "不公平，不公平！東東一輩子收集了超多亮晶晶的東東。但現在那些燭爪蠢蛋把東東跟家人都趕出來了。那些亮晶晶的東東都還在那邊！\n\n這給你。哥布林朋友幫我列了一張在暗焰裂縫裡的寶藏清單。你去拿回來！", progress = "寶藏很重要。很珍貴。你不可以偷拿！要全部給我！", completion = "你辦到了！辦到了！我的寶藏！看招啦，燭爪蠢貨。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83155] = {title = "絆倒鐵盒", objective = "「移除」15隻硬頭鼴鼠。", description = "有一堆鼴鼠和長腿鹿，把我們擋在前所未見的豐富挖掘場外面。抱歉，我有點太急了。\n\n看到這些伐木機了嗎？這可是業界最棒的獵殺機械。但它們卻一直被這些洞卡住！\n\n聽著，我也是個有生態意識的哥布林，但這些鼴鼠非消失不可。我要你對這些硬頭鼴鼠來硬的。要是你看到我的員工，順便幫他們一把，好嗎？", progress = nil, completion = "你真的讓牠們嚇跑了！現在阻止我們開採那些超讚資源的只剩一樣東西了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83159] = {title = "斬首行動", objective = "殺死阿海納，並收集牠的頭顱。", description = "你之前看過深淵行者嗎？這傢伙看到我們，一定很不高興。隨手就能毀掉伐木機，讓牠的危險性遠超鼴鼠。真慘，那些駕駛一定要加班工作，才能彌補損失。\n\n如果有人去解決牠，然後把某個東西帶回來當證據，今天有人就要大賺一筆了。", progress = "你做了什麼？", completion = "糟糕，真的太糟糕了！你以為把危險的東西殺掉，就不那麼危險了。我們快被踩扁了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83160] = {title = "儲備燼釀", objective = "將儲備燼釀交給聖落之地大門的寇格溫。", description = "交易雖然遭到嚴重控管，但在我有生之年，絕不會讓我的儲備燼釀落入那些混蛋的手裡，或是讓某些元素生物毀掉它。\n\n陌生人，那些觀察者把我盯得死死的。所以我無法親自去取回。但他們絕對不會注意到你。\n\n我把它留在下方舊辦公室的桌子後面。\n\n不要離執法者太近，否則他們會沒收你攜帶的燼釀蜜酒，那我就沒東西可以喝了。", progress = nil, completion = "啊，這就是我在等的東西。&lt;name&gt;，謝謝你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83162] = {title = "放回去，放回去！", objective = "踩踏軟泥怪，並將阿海納的頭顱帶離小鎮。", description = "牠會毀了一切！誰會想去有九公尺高鬼鹿的度假村啊？好了，別慌張。大概是因為你拿走牠的頭，讓牠有點不爽吧。\n\n首先，你得先除掉這些軟泥怪。接著，再把那顆頭帶走。越遠越好。\n\n噢，它們待在溫泉裡可就不妙了！", progress = nil, completion = "呼，真是驚險。這整件事讓我明白美麗的大自然有多重要。\n\n&lt;哥布林大笑了幾聲。&gt;\n\n騙到你了嗎？不過，我想我暫時不會開採淵積挖掘場了。", rewards = "您會收到：\n\n共鳴水晶共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][83163] = {title = "分散風險", objective = "搭乘改裝車前往風險木材廠，並協助友善的風險投資公司哥布林。", description = "我們接下來要前往我的勢力範圍，風險木材廠。就在垃圾場的旁邊。\n\n風險投資公司幾乎已經加入加里維克斯了。這代表有很多高階主管都和他一樣骯髒。小心你的一舉一動。\n\n但這裡還是有一些好人的。像是帕姆西和她的團隊。這個風險投資公司的小員工過得很艱難。大家都認為公司裡的人全是壞蛋，所以沒人想照顧他們。但我總得試試看，對吧？\n\n坐上改裝車吧，我帶你去看看我的話是什麼意思。", progress = nil, completion = "你幫了那些哥布林一個大忙。妮琪帶來了混亂…而且不是以有趣的形式。", rewards = "感激的哥布林盾牌感激的哥布林匕首感激的哥布林之劍感激的哥布林之槌感激的哥布林鬥棍感激的哥布林魔杖感激的哥布林水瓶感激的哥布林刀您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83164] = {title = "蛛絲城：接合者末日", objective = "進入蛛絲城，並擊敗『無上接合者』埃佐。", description = "「晉升」才不是什麼進化。這是種褻瀆，是種惡兆。每日每夜，安蘇芮克讓那惡兆陷得越來越深。\n\n如果我們能摧毀轉化場，就有機會讓阿茲-卡罕特永遠擺脫這些威脅。\n\n『無上接合者』埃佐是安蘇芮克選來監督晉升過程的。把她噁心的頭給砍了，或許就能阻止變異的發生。", progress = nil, completion = "&lt;name&gt;，你給了安蘇芮克一記無法挽救的重擊。\n\n這個給你，保重。", rewards = "您能選擇下列奬勵中的一個：\n\n長老的血淋巴護符實驗體08752號的指環\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83165] = {title = "我行我素的機器人", objective = "在影脈營地與克弗利薩交談。", description = "盡量笑吧。要不是因為我業務繁重，不然我也會這麼做。我的機器人因為踩到石頭絆了一下，就把我甩出去。她自己雖然回正了，但我卻不在駕駛艙裡！\n\n所以現在我就在地面上，而她開心地在那邊飄啊飄。這你敢信？\n\n聽著，如果你有去影脈營地的話，可以幫我跟克弗利薩說我會晚一點上工嗎？我必須等這具廢鐵耗完燃料，降到夠低的高度，我才能安全回到駕駛座上。", progress = nil, completion = "辛魯納又被拋出去了，是嗎？我一直告訴她，她飛太低了。希望這次教訓能點醒她。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83166] = {title = "『回音之城』厄拉卡拉：終結收割", objective = "進入『回音之城』厄拉卡拉，並擊敗『收割者』祈卡托。", description = "你也親眼看到了吧？那就是我們說的「黑血」。\n\n我們不會再袖手旁觀了。我們不會讓安蘇芮克為了上古之神死前的最後聲響，而破壞、開採和壓榨我們的珍貴土地。\n\n去找位在下方的古都，也就是『回音之城』厄拉卡拉。如果你把負責開採的走狗殺了，你就能獲得豐厚的報酬。她的手下都稱她為『收割者』祈卡托。", progress = nil, completion = "祈卡托死了？太好了。\n\n&lt;name&gt;，我們感謝你。不管是實質上，或心理上都是。", rewards = "喚蟲者罩氅您能選擇下列奬勵中的一個：\n\n厄拉卡拉囊雛\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83167] = {title = "空中之眼", objective = "殺死8個間諜機以竊取它們的影像。", description = "剛才和妮琪的交涉很不順利。更糟的是，那些暗融間諜機看到了一切。總覺得我們是不是沒辦法擺脫這些間諜了？\n\n風險投資公司最不需要的就是這些工人在妮琪發脾氣時被拍到，導致加里維克斯認為他們不夠忠誠。\n\n去把間諜機拍到的影像搶回來。它們通常會潛伏在工坊周圍，或是跟著風險投資工人。", progress = "沒什麼比為了做好事而砸毀壞機械更棒的事了。", completion = "加里維克斯握有我們的把柄越少越好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83168] = {title = "黑血跡", objective = "在屋舍嶺調查黑血貨物。", description = "在你熟悉幽坑城的狀況的時候，我一直在追蹤我們的獵物。這裡到處都是黑血，隱藏在吵鬧的干擾之後。\n\n但這座城市騙不了我。我在一個叫屋舍嶺的地方發現了一批黑血貨物，但那裡有機器在把守。我們應該一起過去。", progress = "追蹤貨物應該能讓我們知道是誰在利用黑血。找找附近的標籤和信件！\n\n我想我把所有守衛都擊暈了，他們不會來煩我們了。", completion = "大財主里維加茲正在城市中運輸黑血？而且他對以太族疑神疑鬼？！\n\n我有許多問題，而答案就在他手上。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83169] = {title = "遠離藏寶海灣", objective = "在屋舍嶺找出大財主里維加茲。", description = "不會錯的。這些貨物到處都寫滿了黑水集團…字面意思的那種。黑血被運到這裡，然後黑水集團派信差把它送到城市的某處。\n\n所以，如果我們想查出地點，就得直接去找背後的主使者，大財主里維加茲。葛麗菈提到里維加茲在附近有一個臨時搭建的據點，就在屋舍嶺這裡。我們去拜訪他一下吧。\n\n以太族的事得延後了。", progress = nil, completion = "我確定我們可以理解對方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83170] = {title = "別又來了！", objective = "在屋舍嶺為里維加茲找暗融的麻煩。", description = "暗融正在進駐屋舍嶺，就和他們在黑水港做的事一樣。一旦他們進駐，他們就會開始對當地人使壞。有時他們會直接叫當地人離開。這根本不合理。我想要反抗，但我的行動受到限制了。\n\n如果有個外來者現身開始鬧事，那情況就會有所改變了。", progress = nil, completion = "如果我有更多像你這樣的手下，我就不會失去我的…黑水港。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83171] = {title = "雪上加霜", objective = "燒掉8張里維加茲房子上和周圍的暗融招募海報。", description = "他們稱其為招募海報，但那不是它們存在的唯一目的。它們在那裡是為了提醒眾人這裡由暗融掌管，他們想怎麼做都可以。如果我或當地人去把它們撕下來，我們就會遭到不好的對待。\n\n反正暗融不管怎樣都討厭你。\n\n如果你把所有海報都燒掉，我就欠你一個人情。", progress = nil, completion = "雖然這麼做無法趕走暗融，但沒有那些暗融垃圾貼在牆上，至少屋舍嶺的景色會好一點。\n\n就像我說的，我欠你一個人情。", rewards = "您會收到：\n\n絕望哥布林手套絕望哥布林長靴絕望哥布林肩甲絕望哥布林腰帶勇氣石"}
MultiLanguageQuestData['tw'][83172] = {title = "黑血接力棒", objective = "在垃圾場的下一間黑血倉庫與雷吉克和加茲魯維會合。", description = "黑水集團已經先行一步了，而且他們想讓這個行動繼續下去。里維加茲讓他的手下從站點把它帶走，暫時藏起來，然後把它送到投放點。投放點隨時會變，但目前是在垃圾場的一間倉庫。\n\n我們得去看看，然後查出黑血在那之後會去哪裡。\n\n他說那裡有人把守，所以到邊緣區域找我們。", progress = nil, completion = "那裡有很多守衛。我們肯定沒來錯地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83173] = {title = "清空倉庫", objective = "在垃圾場清除倉庫區域。", description = "垃圾場到處都是守衛。如果我們有機會可以干擾幽坑城的黑血行動，我們就應該好好把握。\n\n我們無法阻止所有黑血被運到城市各處，但我們可以除掉一些守衛並毀掉一些貨物。去製造足以干擾行動的混亂。任何一點都有幫助。", progress = nil, completion = "這樣應該能讓黑血買賣慢下來。希望所有在等貨到的人都會過上不愉快的一天。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83174] = {title = "我們的好朋友", objective = "殺死吉多。", description = "我們的老朋友吉多回來了。看來他被提拔為了垃圾場的監督者，負責追蹤黑血貨物。\n\n我們還沒回報他在排水溝營地出賣我們的這件事。他為了討好加里維克斯，害死了許多善良的哥布林。讓那個小告密者得到應有的下場。", progress = nil, completion = "我不會忘記他在排水溝營地對帕姆西的團隊做的事…這也是在為他們報仇。", rewards = "您會收到：\n\n吉多的骯髒之握吉多的骯髒頭盔吉多的骯髒披肩吉多的骯髒護脛勇氣石"}
MultiLanguageQuestData['tw'][83175] = {title = "另一片拼圖", objective = "在垃圾場與加茲魯維討論吉多的手帳內容。", description = "<手帳上記載著有關吉多的成就的長篇大論，但也包含了幽坑城各地的各種黑血輸送紀錄。手帳中的數個條目顯得特別奇怪：\n\n-用於秘密計畫的一千個單位，送去秘密計畫站點。\n-用於開發中彈藥的二十個單位，透過信差遞送。\n\n轉移工作由熱砂企業的諾格弗格批准。>", progress = "諾格弗格知道最好不要和加里維克斯混在一起。", completion = "這一切都太超過了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83176] = {title = "一種直覺", objective = "向雷吉克詢問加茲魯維，然後到垃圾場外找加茲魯維。", description = "該來想想下一步該做什麼了。這個諾格弗格的事讓加茲魯維很煩躁，我們得盡快去查出到底是怎麼一回事。\n\n有某件事讓我也感到心煩意亂。我們應該快點離開垃圾場。不過先確定加茲魯維會一起走。", progress = nil, completion = "葛麗菈說歐薇娜和艾蘭里亞還沒到。", rewards = "您會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83177] = {title = "社會良藥", objective = "讓受壓迫的住民服用尼茲瑞克的藥水。", description = "我注意到地洞區最受壓迫的住民們似乎正受某種疾病折磨。\n\n帶著這個藥水並讓病患服用。這能夠強化住民的身體，也能阻止疾病進一步擴散。", progress = nil, completion = "我絕不容許他們受苦。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83178] = {title = "規則和結果", objective = "擊敗刺客。", description = "我最近捐了救急物品，這個舉動恐怕有點太莽撞了。似乎引來了一些不懷好意的目光。\n\n提高警覺。潛藏的威脅正在逼近。", progress = nil, completion = "謝謝你的幫助，我或許很有抱負，但我對戰鬥的敏感度奇差無比。\n\n不過，如果安蘇芮克的刺客找到我…\n\n不。我不能停下腳步。我還有很多事還沒做。", rewards = "您會收到：\n\n卡吉卡吉"}
MultiLanguageQuestData['tw'][83181] = {title = "有難同當", objective = "在絲林洞穴殺死船匠伊莎貝拉跟織影者阿扎拉克。", description = "我看到船匠離開洞穴去海灘那邊了。她身邊還有一個看起來很壯碩的奈幽蟲族。\n\n那名船匠就是整個行動背後的主腦。她清楚知道她們的飛船需要哪些木材，以及木材切割的工法。\n\n奈幽蟲族也了解這點，所以派了最強的夥伴來保護她。\n\n如果可以殺掉那名船匠，我們就可以阻止他們精心安排的計畫了。", progress = nil, completion = "奈幽蟲族的領袖死了之後，他們剩餘的勢力就會自亂陣腳。\n\n失去了船匠的知識和領導，他們的整個行動將會陷入困境。\n\n希望這樣也能讓他們盟友關係出現裂痕。", rewards = "您會收到：\n\n阿爾加編織之索阿爾加斥候長靴阿爾加繫腰阿爾加重型護手共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][83182] = {title = "血淋淋的遺產", objective = "在聖落之地的飢餓渦池中取回艾莉莎雙親的物品。", description = "寇拜斯殺死我的雙親時，還偷走了他們最珍惜的東西。\n\n當然不是我。是某個東西。\n\n我們殺死寇拜斯的時候，順便把東西找出來吧。", progress = "愚蠢的寇拜斯。我討厭他們。", completion = "幹得好。你比那些告訴我不要這麼做的大人要有用多了。\n\n「可是艾莉莎，寇拜斯很危險。你可能會死掉。」愚蠢的大人，都以為自己很懂。\n\n你準備好要殺掉大隻的了嗎？我準備好了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83194] = {title = "承受砲火", objective = "陪伴在蒙特‧加茲魯維身邊。", description = "我能站在這裡是為了雷吉克。他甚至沒有多想…他只是…", progress = "我們在這裡還有事沒完成。", completion = "&lt;加茲魯維露出了你從沒見過的神情。他看起來怒氣衝衝，但他依舊用無比冷靜的語氣說話。&gt;\n\n已經無法否認了…不是加里維克斯死，就是我們亡。我們不能再忍受他了，多一天都不行。他必須被阻止。不能再妥協，無須再忍耐。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83195] = {title = "號召人民", objective = "與德克‧賣油者一起挑選標題，然後在尾門公園散播革命的宣傳。", description = "沒有人比污水企業聯合被加里維克斯整得更慘。很多人早就想要起義了，但這還不夠。我們必須讓他們知道加里維克斯都做了些什麼，並說服他們現在就是絕佳的時機。\n\n我們先從標題開始吧。來吧，說說你的想法。像你這樣的大人物比任何人都適合傳遞訊息。", progress = nil, completion = "空氣中瀰漫著變革的氣味。我能感覺到。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83196] = {title = "散播吧！", objective = "在尾門公園殺死20個暗融。", description = "加里維克斯無法掩蓋真相，但他可以痛扁我們，直到大家只能選擇接受。我們不會再讓這種事發生了。\n\n如果你看到有人在傷害污水企業的哥布林，你就去還以顏色吧。", progress = nil, completion = "靠談話來解決這件事的時機早已過去。如果他們要站在加里維克斯那邊，那是他們自找的。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83197] = {title = "街頭歸誰管？", objective = "面對殺害雷吉克的『喬事人』妮琪。", description = "是她！『喬事人』妮琪，風險投資公司的高階執法者。她的手上沾滿了雷吉克的鮮血。\n\n我不禁擔心她是否還有另一顆子彈。我們得快點追上她。<name>，你要跟我一起去嗎？", progress = nil, completion = "你正好趕上加入登船小隊的時機。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83198] = {title = "後院海軍", objective = "在黑水港摧毀暗融兜風者。", description = "加里維克斯和他的團隊已經干涉我們的事業太久了。看看他們對我的港口幹了什麼好事！他們對自己的財產放心到會騎著水上摩托轉圈圈！\n\n是時候讓他們見識一下大海的火力了。\n\n控制這門火炮，把那些掠過我們水域的暗融船隻炸上天。在那之後，幫我一個忙，去看看大傢伙的情況，行嗎？", progress = nil, completion = "嗯。砲火的轟鳴和黑火藥的味道。你會是個優秀的火炮手。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83199] = {title = "壓箱秘方", objective = "在黑水港從渡假村工作人員身上收集萊姆。", description = "聽好了，<name>，斯普琳科長久以來一直在研發某種配方，而我終於準備好從中獲利了。那就是一點煉金師的秘密原料。柑橘！能以一半的速度帶來諾格弗格的恢復藥劑兩倍的效果。它能強化你的骨頭，促進肌肉生長，還能幫你報稅。堪稱無所不能！\n\n問題是，我手頭上目前沒有這種東西。這些渡假村之類的可能有你需要的東西。我們一直保存著這份配方，等著把它交給某個大人物。在你把它製作出來之前，先去確認海角有沒有事，可以嗎？", progress = "呃。他們用黑血打敗我了嗎？", completion = "萊姆？這些又是什麼？我們在對抗的東西比壞血病還要糟糕！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83200] = {title = "站住，你這無賴", objective = "釀造諾格弗格豪華藥劑加萊姆，將其餵給艦隊指揮官海角。", description = "呃。我已經被關押了很久。我一怒之下就魯莽行事。\n\n不管諾格弗格給了你什麼，我保證我絕對不會浪費。幫助我重回戰場，我們會將黑水集團的全力傾瀉在這些入侵者身上。", progress = nil, completion = "我感覺煥然一新，謝謝你。\n\n他們表面上把我們的港口轉型為價格高昂的渡假村，背地裡卻幹著黑血的走私買賣。\n\n我們去報仇吧。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83201] = {title = "加急快遞", objective = "掛上故障的搬箱機器以搭便車。", description = "接下來就由黑水公司接管港口吧。但只要黑血還在外流通，人民就無法安居樂業。\n\n那些飛行運輸器一定是要把黑血帶去某個風險投資公司掌控的地方。只要能徵用一架，你或許就能找到葛麗菈。我們分頭行動的時候，她朝那個方向去了，還一邊喊著她的一個朋友在路上了。", progress = nil, completion = "正好是我想見到的兩個人。這裡的黑血讓我們忙得不可開交。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83202] = {title = "拳打腳踢", objective = "擊敗三名風險投資公司忠誠副官。", description = "靠對話來解決歧見的時間已經結束。我已經不想再靠猜測來判斷誰還在和加里維克斯勾結了。\n\n妮琪的部分手下仍然在維持這些新武器的生產。所以，我們必須除掉他們。等一切都結束之後，這也能讓風險投資公司的清理作業變得更簡單。\n\n千萬要小心。妮琪不會為她的副官們豁出性命，但她會趁機策劃一場專門對付你的戰鬥。", progress = nil, completion = "總得有人來做這件事。我們的工作還沒完成。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83203] = {title = "武器正熱", objective = "在垃圾場摧毀黑血木箱和武器。", description = "那些為自己的利益而榨取艾澤拉斯的人，他們的毀滅慾望總會讓我感到恐懼。但這些武器和過去出現的完全不同。\n\n所有黑血容器都必須被推翻和摧毀。由黑血驅動的武器也必須被銷毀和拆解。使用這些武器對付他人者，殺無赦。這座城市，乃至整個世界的人民，在我們完成這些事以前都無法脫離危險。", progress = nil, completion = "你做得很好。但現在，我們必須向組裝這些武器的核心地帶發起進攻。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83204] = {title = "某個東東", objective = "在垃圾場為帕姆西收集零件。", description = "妮琪的科技以黑血為動力。我會知道這點，是因為我參與了一半的開發。這也代表我知道我們該怎麼把她從天上擊落，好讓我們可以打敗她。\n\n沒時間進行前製了。我們得直接製造。\n\n還記得我們的小小浮板冒險嗎？冰很好玩對吧？我想我們可以用同樣的方式…垃圾場一定會有我們需要的所有回收物，用來製造這個假設性的什麼東東。", progress = "你有說廢話的時間，還不如趕快去砸廢料！", completion = "在我認識的工程師裡面，只有一位的聰明才智能及時幫我們打造出打倒妮琪的道具…", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83205] = {title = "生產停擺", objective = "在垃圾場破壞黑血儲備。", description = "<歐薇娜用泥土摩擦手掌，然後把她的關節折得咯咯響。>\n\n現在該讓那些玩弄黑血的人見識一下自然的怒火了。我等不及想召喚在艾澤拉斯盤根錯節的樹根。\n\n加入我吧。和我們先前做的一樣，釋放自然的怒火。讓我們將他們珍貴的黑血儲備破壞殆盡。", progress = nil, completion = "灑出來的黑血當然會變成巨型怪物了。好吧，至少你把它解決掉了。他們能用來為武器提供動力的黑血越少越好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83206] = {title = "街頭歸我們管", objective = "號召幽坑城的人民對抗加里維克斯。", description = "其實貿易親王對這裡的哥布林一點都不公平，所以這不能僅僅只是又一場集團鬥爭。群眾必須知道，他們並不是在為污水企業或熱砂企業而戰。\n\n他們是在為幽坑城而戰。\n\n我們必須讓一個不是集團高層的人負責激發他們的怒火，並保護他們的安全。盡你所能護送他們到加樂宮，然後告訴這些哥布林，這裡是他們的城市。", progress = nil, completion = "這些街道不屬於加里維克斯，而是屬於我們。在這之後，他永遠不會忘記這點。", rewards = "您會收到：\n\n幽坑城革命軍鎖子甲幽坑城革命軍頭盔幽坑城革命軍長靴幽坑城革命軍腿甲勇氣石"}
MultiLanguageQuestData['tw'][83207] = {title = "我最棒的女孩", objective = "擊敗『喬事人』妮琪。", description = "我們把加里維克斯逼到死路了。看看幽坑城和受他掌控的居民終於起身反抗。\n\n他以為他的這個「喬事人」能保護他的安全。我們去讓加里維克斯、妮琪還有所有人瞧瞧，這次的情況截然不同了。\n\n<加茲魯維看著他剛剛就地取材做出來的某個東東。>\n\n看好了。", progress = nil, completion = "感受一下吧。我們贏了。加里維克斯可以暫時苟延殘喘，但我們把城市從他的手裡搶回來了。\n\n在今天，幽坑城屬於我們。", rewards = "您會收到：\n\n遣散費勇氣石"}
MultiLanguageQuestData['tw'][83229] = {title = "特殊任務：擾動的深淵", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83240] = {title = "劇團", objective = "參加劇團活動。", description = "<name>，既然你是我們劇團的榮譽成員，何不一同參與演出呢？\n\n不是什麼要角啦…我也不想讓其他團員在舞台上光彩盡失。你也知道他們的性子。\n\n那你願意嗎？例如，一個禮拜演一次如何？", progress = "演出必須繼續！繼續再繼續。我們續約變成常駐演出了。對土靈來說，這代表著…嗯，這代表我們會有很長一段時間有工作了。", completion = "太棒了！我們劇團正需要你這樣的人加入，&lt;name&gt;。\n\n在我們下次演出時，請你再來協助我們吧！", rewards = "您會收到：\n\n劇團寶箱劇團寶箱共鳴水晶多恩諾加議會青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83247] = {title = "懷疑之心", objective = "在蘭桎洞窟找出9個薩曼瑟螈心臟。", description = "長年以來，當我們在聖落之地看到阿拉希人以外的生物，全都想把我們給殺了。像是奈幽蟲族、暗影生物、野獸之類的。所以請原諒我因為你突然出現而起了疑心。\n\n但是我的另一半要我表現得更加好客…而為了她，我也想試著成為更好的人。\n\n蘭桎洞窟的有些薩曼瑟螈一直在騷擾我們。把牠們殺了，然後帶回證據給我。", progress = nil, completion = "你幫了大忙。\n\n也許她是對的，也許我應該把頓內爾當成榜樣。\n\n謝謝你。", rewards = "您會收到：\n\n酒染護腿團結阿拉希上衣薩曼瑟螈鱗護脛德瑞沒戴過的面甲共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][83271] = {title = "總是有另一個秘密", objective = "在多恩諾加的文庫裡見達格蘭‧索瑞森二世與布琳瑟。", description = "自從我爸做了某件事後，不管是什麼，泰坦機械又能再次運作…就連多恩諾加這裡的也可以了。\n\n達格蘭光是一直問布琳瑟問題就很開心了，不過他現在正在幫她整理文庫。\n\n現在他需要你的幫助。他興奮到說不出原因，不過他想跟你在文庫裡見上一面。", progress = nil, completion = "太有趣了。這很明顯是個守衛者的房間。但是做什麼用的？\n\n我們必須進一步調查。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83274] = {title = "穿越時光的初始之路", objective = "完成5次時光漫遊地城冒險。", description = "老戰士一直在提當年勇，說在他們那個時候，艾澤拉斯有多麼危機四伏。\n\n我賭他們會說，在他們那個時代，你這個弱雞絕對撐不了10分鐘。\n\n覺得自己沒那麼弱嗎？那就證明給我看。", progress = nil, completion = "你辦到了，&lt;name&gt;！讓那些老戰士看看，艾澤拉斯後繼有人了！", rewards = "您會收到：\n\n青銅龍慶典藏寶箱時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83275] = {title = "裝備附魔", objective = "為任一枚戒指附魔愛樂丁給予的附魔戒指 - 微光加速，以完成物品附魔教學。", description = "你好，外來者！\n\n自從你在我們的海岸華麗登場後，我一直聽到你的豐功偉業。我們土靈歡迎你出手相助。\n\n我可以教你如何用這片土地上的資源為你的裝備附魔。為了擊敗我們的敵人，能增強實力的做法都值得一試。", progress = nil, completion = "願你像大地一樣不屈不撓。快出發吧，外來者！", rewards = "您能選擇下列奬勵中的一個：\n\n附魔戒指 - 微光致命一擊附魔戒指 - 微光加速附魔戒指 - 微光精通附魔戒指 - 微光臨機應變\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83276] = {title = "搶救阿軸大兵", objective = "到貴族谷找阿軸。", description = "我的其中一隻小織蛛有很久沒向我報告了。我派了阿軸去取回能對付安蘇芮克得力愛將的有用情報，但也沒有下文。\n\n『猛毒之舌』密斯克是個卑鄙的奸佞小人，而且也很危險。雖然我相信我可愛的阿軸有能力完成任務，但像密斯克這樣的狂妄暴徒，不知會對我的小傢伙做出何等恐怖的事。\n\n找出阿軸。保障她的安全。", progress = nil, completion = "&lt;小蜘蛛以懇求的眼神看著你。你也看出來她希望你不要把這件事告訴任何人。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83277] = {title = "個人偷竊", objective = "在密斯克的居所中找到3個定罪證據。", description = "<小蜘蛛環顧房間四周，眼睛逐漸瞇了起來。\n\n你想到織絲者要你取回證據來恐嚇密斯克。\n\n但現在看來，阿軸在密斯克的儲藏室裡翻箱倒櫃這下是因為私人恩怨了。>", progress = "我的小不點，你找到什麼了嗎？", completion = "看來你把我的阿軸帶回我身邊了。除此之外，還有一些相當有意思的證據。\n\n看來，『猛毒之舌』密斯克為了獲得安蘇芮克和她同夥的青睞，不惜誹謗他的主人。他踐踏著奈菲瑞斯女王的遺澤，逐漸擴張自己的勢力。\n\n這根本不合理。快點回來見我，我的小不點。我需要一些時間來規劃我們接下來的行動。", rewards = "您會收到：\n\n卡吉卡吉"}
MultiLanguageQuestData['tw'][83278] = {title = "西爾海姆家族：遺失的鞋子", objective = "將遺失的鞋子交給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<這隻鞋子是西爾海姆家族的人會穿的風格。或許阿里雅‧西爾海姆可以提供一些線索。>", progress = nil, completion = "阿迪森跟我以前都會脫下鞋躡手躡腳穿越這些洞穴。腳步輕的話，沉睡的蘑菇就不會醒來。這不是萬無一失的計畫，我們在逃離生氣的鞭菇時，確實弄丟很多鞋子。\n\n不過，這隻鞋子似乎是婕塔的？", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][83279] = {title = "證明自己的氣概", objective = "在蘭桎洞窟裡擊敗聚合罪孽。", description = "沒錯，你的確幫我們處理了這些害蟲，但遠遠不夠。我要的更多。\n\n我們城鎮附近有個區域聚滿了暗影。如果你真的沒有受到…過去的奇怪背景給控制，你應該可以毫不費力地除掉這個威脅，對吧？", progress = nil, completion = "打從我一出生，就一直是聖焰教堂的信徒。教義是我難以割捨的一部分。\n\n但我現在知道你是來幫忙的。只要你願意為我們效力，不管你的力量來自何方，我都會伸出友誼的援手。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83282] = {title = "西爾海姆家族：一窩蛋", objective = "將一窩蛋拿去給西爾海姆農莊的阿里雅‧西爾海姆。\n\n已提供物品：\n", description = "<這一窩雞蛋一定屬於附近的農場。或許阿里雅‧西爾海姆可以提供一些線索。>", progress = nil, completion = "你在附近的洞穴裡發現了這個？我們有幾隻雞很愛冒險，可能不小心跑進去了。\n\n要找回所有的流浪雞基本上是個全職工作。", rewards = "您會收到：\n\n共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][83283] = {title = "為了士氣", objective = "在蘭桎洞窟取回6桶帝國香檳。", description = "請原諒我丈夫的魯莽態度。當我們加入這次遠征時，預計最糟糕的情況就是離開家人幾年而已。但我們卻定居於此，對抗…對抗終極勢力、對抗雷尼拉什。又有誰知道我們的使命何時才能結束？\n\n我囤放了大量教堂葡萄園出產的酒，好在對的時間讓大家喝個痛快。我藏酒的蘭桎洞窟被其他生物佔據了。你可以替我去取酒嗎？", progress = "想像有二十個阿拉希人為了一盞燈火而擠在一起十年。想像一下，他們終於能喘口氣，好好與同胞喝上一杯。\n\n現在想像一下，他們聽到酒全沒了之後的感受。\n\n…請你快去快回。", completion = "噢，感謝烈焰。\n\n你成功阻止了一場可能會發生的小暴動。祝福你，感恩你！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83285] = {title = "古老卷軸", objective = "卷軸真的很讓人著迷。可以旅行到千里之外、橫越整片大地。不過這個卷軸似乎還能穿梭在不同年代間。\n\n你能找到這個卷軸，是個徵兆，也是一種祝福。", description = "一開始，薄霧似乎讓卷軸的細節變得模糊。當你專心辨讀卷軸的特徵時，薄霧短暫消散，顯露出以最好的羊皮紙製成的全新卷軸，上面有個看似剛剛蓋下的封蠟，蠟似乎都還沒凝固。轉瞬間，卷軸感覺變得脆弱無比，封蠟也似乎隨時都會碎裂。隨著薄霧開始再次凝聚，你看見卷軸不斷閃爍，在新舊的兩個極端之間變換。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][83286] = {title = "埋藏於多恩諾加之下的事物", objective = "在多恩諾加的記憶寶庫裡重新啟動中央主機。", description = "太奇怪了。這裡的機械與控制臺都有收到能源，但我無法重新啟動。\n\n達格蘭的調查可能要再等等了。\n\n我已經知道這個設施的名稱了，就是「記憶寶庫」。這讓我深信，我一開始的理論是對的。它與多恩諾加的文庫有相通。\n\n因為你們兩人對這類型的泰坦設施都很熟悉，你們應該也比較有機會讓它重新啟動。", progress = nil, completion = "現在我可以在記憶寶庫裡存取主機了。\n\n這裡有很多東西…但都不甚完整。要重新開始可能會花上一點時間。\n\n恐怕有些資料已經損毀，需要修復。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83306] = {title = "野生物扎根之地", objective = "在烏爾阿野營地與歐薇娜碰面。", description = "我的一些人發現一些哈拉尼爾正在西南邊建立他們的其中一個營地。他們缺少一些重要的補給品，於是我的人主動伸出援手。不過，我不知道他們在那邊相處得怎麼樣。\n\n你可以去看看情況嗎？確保我們有好好招待哈拉尼爾…並確保沒有人無意間冒犯到任何人。拜託你了。", progress = nil, completion = "又是你啊。有意思。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83315] = {title = "為未知做好打算", objective = "回去多恩諾加找茉艾拉‧索瑞森。", description = "這個過程可能會很久。恐怕達格蘭在島上要比預計待上更長一段時間。\n\n或許…\n\n這裡有許多泰坦文物可以用來當作「鑰匙」，解鎖主機情報或修復主機。這樣就可以加快整個過程。\n\n但也只有時間能夠證明了。\n\n你已經幫了我們夠多了，<name>。回去告訴茉艾拉我們所發現的事物吧。", progress = nil, completion = "我知道我想念達格蘭的時候該去哪裡找他。\n\n能看到他這麼開心做自己實在是太好了。我為他感到驕傲。\n\n謝謝你這段時間一直幫助他。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83321] = {title = "怪異蝙蝠", objective = "調查可疑的德魯伊。", description = "嗨。女士大人近期發現幼蟲場有奇怪的蝙蝠飛來飛去的。\n\n但間諜回報，說牠的舉動卻更像人類。我們認為牠是個德魯伊，卻不知為何沒有向奈幽蟲族顯出真實樣貌。\n\n你的臉看起來就不像是會被他當場揍一頓的人，去外頭探查一番吧。", progress = nil, completion = "你！你正是我要找的人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83322] = {title = "破曉者號：洗禮儀式", objective = "協助完美進行破曉者號的洗禮儀式。", description = "阿拉希艦隊的旗艦當屬破曉者號了。她是阿拉希工程的偉大奇觀，也表達了我們對聖焰的信仰。只要有她在聖落之地的上空，我們就有力量能夠擊退任何膽敢再來襲擊我們土地的奈幽蟲族。\n\n因為你過去幫了我們這麼多，我們誠摯邀請你來參加破曉者號的洗禮儀式。如果你能確保儀式安穩進行，我會好好感謝你的。", progress = nil, completion = "很好。\n\n這比任何聖落之地的其他儀式進行得要好太多了。\n\n感謝你的參與。", rewards = "您會收到：\n\n飛船船長遺失的墜飾共鳴水晶聖落之地阿拉希"}
MultiLanguageQuestData['tw'][83324] = {title = "絲線", objective = "在絲線區與桑姆拉薩會面。", description = "你在找什麼嗎？<琳妮瞇起眼睛盯著你。>如果你是來打聽的話，我是有聽說主城的一些傳聞。織絲者的同伴正在調查絲線區的某些事。\n\n這個新的區域應該要為主城的居民帶來個美好的新開始，但女王的蒼白鞭絲者卻把那裡搞得像軍營一樣。這對那裡的人來說不是什麼好事。\n\n到區域外與一個叫桑姆拉薩的奈幽蟲族會面。她會把所有細節都告訴你。", progress = nil, completion = "你一定是「共同朋友」派來的幫手。歡迎來到絲線區。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83325] = {title = "豐碩甲蟲", objective = "在拉克-亞緒與基什奈爾交談。", description = "阿努巴札爾將軍對拉克-亞緒的甲蟲園有著遠大的計畫。他試圖讓它恢復正常，來作為他戰局的助力。\n\n但是…我對他留下來監督的兩人持保留態度。\n\n基什奈爾或許知道他在做什麼，但菲克薩倫？殘暴，更不堪重任。或許需要有人…點醒一下他們。\n\n到拉克-亞緒找基什奈爾，並跟他說說阿努巴札爾的命令。", progress = nil, completion = "啊，所以將軍派了一位觀察者來嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83326] = {title = "最後一根蠟燭", objective = "為剛達加茲旅店的可疑的排氣口偷取最後一根蠟燭。", description = "你還真是個蠟燭神偷。\n\n我們有最後一項任務想交給你，蠟老大！最後一次了！之後就是輕鬆的事了。\n\n地下室有根大蠟蠋。那些石頭人會用來防老鼠來偷走他們的蜜水。我們不是老鼠！我們可是狗頭人！\n\n<一陣尷尬的停頓。>\n\n嗯，好像也沒什麼字跟狗頭人押韻。\n\n幫我們搶大蠟蠋就對了！", progress = nil, completion = "嗚呼！蠟燭欸！是大蠟燭！\n\n…你有聞到煙味嗎？", rewards = "您會學到：\n\n偷竊：冒泡蠟\n\n您還會收到：\n\n冒泡蠟"}
MultiLanguageQuestData['tw'][83328] = {title = "分析介面", objective = "在分析介面完成分析程序。", description = "這是分析介面。\n\n為了確保我們的主程式完好無缺，這些控制臺設置了一連串的問題，以評估剛覺醒的土靈的記憶矩陣。\n\n雖然黎明鼓勵你依個人的想法回答，但…這麼說吧，我希望你誠實回答。\n\n準備好了就開始吧。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n領養石心大岩羊\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83329] = {title = "等級50", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83330] = {title = "等級60", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83331] = {title = "保存與假裝", objective = "使用哥布林「歷史探測器」來找到可以挖掘「歷史物品」的地方。", description = "小蔥在挖掘歷史。你要幫忙找嗎？\n\n哥布林給了我歷史探測器。說它可以找到地下的歷史！你用、小蔥挖。", progress = nil, completion = "非常感謝，挖掘發現者。\n\n我知道這些東西大部分沒有真正重要的歷史…但總有一天會有的。\n\n小蔥會好好保存他們，直到狗頭人創造新的歷史。\n\n然後保存並保護，直到永遠。", rewards = "您會收到：\n\n共鳴水晶共鳴水晶深淵集會"}
MultiLanguageQuestData['tw'][83333] = {title = "應付麻煩", objective = "完成20波甦醒機械事件。", description = "你好，朋友。\n\n機械再次進入失修狀態，需要有人執行修復工作。\n我需要你的專長，才能成功進行維護。\n\n表現出色的協助將會有所回報。", progress = nil, completion = "機械又開始繼續運作了。\n\n再次感謝你的協助。", rewards = "您會收到：\n\n\n\n等級 72–80覺醒機械寶箱\n\n任意等級覺醒機械寶箱青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83334] = {title = "帝國的財富", objective = "阿拉希人真的很感激你在這個險地伸出援手。我們的感激之情難以言喻，請收下這個。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n共鳴水晶"}
MultiLanguageQuestData['tw'][83335] = {title = "懸賞：城鎮破壞者", objective = "殺掉多恩島上的城鎮破壞者史提卡。", description = "<這個紙條是用小片的甲殼釘在柱子上的。>\n\n針對阻礙多恩諾加律令的犯罪，議會將會頒發獎勵給殺死甲殼野獸史提卡的人。\n\n在此附上史提卡的護甲樣本。如果你無法對它造成破壞，你最好嚴守你原本的職責，將這項任務留給他人。", progress = nil, completion = "議會愛怎麼吵都隨便他們。真正的英雄是挺身而出，讓世界更安全的人。謝謝你，英雄。", rewards = "您會收到：\n\n甲殼裹腕城鎮破壞者的腕輪懸賞奈幽蟲族的手環地穴領主護腕共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][83336] = {title = "大地之傷", objective = "在多恩島從『大地之傷』羅斯身上取得破損的石心。", description = "<在你靠近時，愛提卡正在抱怨。>\n\n地面在晃動。這樣可不妙。\n\n麻煩又開始喚醒元素了。攪動它們其中的腐敗。對我們所有人都是危險。讓它們屈服，把它的心臟帶來。\n\n這樣土地才有辦法恢復。這樣愛提卡才能盡到她的職責。", progress = "<愛提卡一邊抱怨一邊無神地盯著你。>", completion = "哼，破碎的心要花很久的時間來修補。\n\n愛提卡聽見你了，羅斯。大地會復原的。", rewards = "您會收到：\n\n共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][83337] = {title = "雷之傷疤", objective = "在多恩島的漫步郡附近的牧場殺死雷疤。", description = "看看這個美麗的城鎮。你看到什麼？牧人和他們的苔毛羊。可是這個牧人的羊群在哪裡？牠們在一頭野獸的肚子裡。他們叫他雷疤。\n\n雷疤的嚎叫聲如雷、撕咬如閃電、肚子裡裝滿我畢生的心血。\n\n我來這裡想買武器，但我們只有牧羊工具。你看起來很強壯。你可以終結雷疤在我們牧場上的霸權嗎？", progress = nil, completion = "謝謝你，冒險者。我在這個世界上的角色是牧羊人，你則是屠狼者。我們都有自己的本分。", rewards = "您會收到：\n\n共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][83338] = {title = "法師殺戮者", objective = "在多恩島的漫步郡附近殺死法師殺戮者腓特希。", description = "我承認我來這裡是有理由的。有一個還在逍遙法外的傢伙配不上他擁有的自由。\n\n他是一個來自紫羅蘭堡的犯人，我們姑且稱他為法師殺戮者。我來這裡是想請求這些人幫忙，可是他們都是農夫跟牧人。我希望你更能勝任這項挑戰。\n\n去找出那個邪惡的傢伙，結束他的生命。", progress = nil, completion = "達拉然或許已經毀壞，但祈倫托並沒有允許釋放法師殺戮者！\n\n謝謝你的協助，&lt;name&gt;。\n\n你確定你把他徹底殺死了嗎？", rewards = "您會收到：\n\n共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][83339] = {title = "破尖者", objective = "在多恩島的漫步郡附近殺死阿努貝絲卡。", description = "我們對奈幽蟲族攻擊並不陌生。祈倫托的準備齊全，可以處理這樣的威脅。但達拉然…\n\n也曾有所準備。我無法擊退這座城鎮所有的敵手，但你或許有辦法。我過來的時候，看到路邊有一些埋伏。熟悉的敵人，熟悉的戰術。去觸發那個陷阱，殺死潛伏在下的怪物吧。", progress = nil, completion = "謝天謝地。有了你的協助，或許我們這次…有辦法做出改變。\n\n這些人值得過上安全的生活。", rewards = "您會收到：\n\n共鳴水晶多恩諾加議會"}
MultiLanguageQuestData['tw'][83345] = {title = "戰鬥的呼喚", objective = "在戰場贏得4場對戰。", description = "我聽說你的人民在廣闊的原野和殘破的廢墟中互相打了許多大戰。\n\n在還有正事要辦時為了旗幟互相爭鬥，感覺有點浪費時間。不過，戰場是戰士氣概的試煉場。若是如此，那這一切還是有價值的。\n\n帶給我勝利的好消息！期待你們能讓我刮目相看。", progress = nil, completion = "你帶著勝利的好消息回來了？或許還有幾場敗仗？\n\n每場敗仗都是推動你進步的寶貴教訓。別忘了也要慶祝你的勝利。", rewards = "您會收到：\n\n榮譽獎章征服點數青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83347] = {title = "征戰使節", objective = "完成4場傳奇難度的地城。", description = "你敢接受真正的挑戰嗎？在這場挑戰中深入最黑暗的地方，接著飛升到最高的天空。\n\n把自我逼到極限才能真正測試我們的技術。", progress = nil, completion = "你完成了一項不簡單的任務。我感到有點佩服了。", rewards = "您會收到：\n\n奈幽寶藏箱幽坑城寶箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83357] = {title = "箇中翹楚", objective = "帶著由25級寵物組成的隊伍，透過尋找對戰功能打倒5位玩家。", description = "我們和機械之間的連結就像是其他人和寵物的連結一樣。你必須和你的夥伴和諧相處，才能完成偉大的壯舉！\n\n向我展現你能和你的寵物一起完成團隊合作。在它們的幫助下擊敗你的敵人！您能選擇下列奬勵中的一個：\n\n", progress = nil, completion = nil, rewards = "您能選擇下列奬勵中的一個：\n\n究極戰鬥訓練石\n\n您還會收到：\n\n青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83358] = {title = "競技場的呼喚", objective = "贏得10場競技場練習戰。", description = "你在競技場證明你的氣概了嗎？贏得足夠多的戰鬥，也許有一天你的英勇事蹟也值得收錄在文庫之中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n征服點數榮譽點數青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83359] = {title = "穿越時光的破碎之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "你們之中的某個人帶來了一個奇怪的故事，關於大災變是如何讓艾澤拉斯瀕臨崩毀的。在你們的土地上，因為邪惡生物死亡之翼的陰謀，這些感受尤為深刻。\n\n穿越時空迎戰他與其他威脅。", progress = nil, completion = "大災變的回音在整個艾澤拉斯迴盪。那確實是一段艱難的時光。", rewards = "您會收到：\n\n奈幽寶藏箱奈幽寶藏箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83360] = {title = "穿越時光的魔化之路", objective = "完成5次時光漫遊地城冒險。", description = "我聽說過關於整個燃燒軍團的威脅潛伏於時空路徑上的故事。\n\n擊敗他們，帶回消滅他們的消息。", progress = nil, completion = "你已經收拾掉燃燒軍團了嗎？這是他們應得的下場，至少我聽起來是這樣。", rewards = "您會收到：\n\n奈幽寶藏箱"}
MultiLanguageQuestData['tw'][83362] = {title = "穿越時光的隱蔽之路", objective = "完成5次時光漫遊地城冒險。", description = "你們之中的某個人帶來了潘達利亞的故事！我非常樂意有一天能在那片天空中翱翔。\n\n穿越迷霧與時空，帶回你流傳的事蹟吧。", progress = nil, completion = "哇，迷霧的水氣讓你全身溼透了。聽說你帶回了在潘達利亞勝利的消息。", rewards = "您會收到：\n\n奈幽寶藏箱幽坑城寶箱"}
MultiLanguageQuestData['tw'][83363] = {title = "穿越時光的燃燒之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "你的人民帶來了黑暗之門的故事，其中包含了許多敵人與挑戰。我還想聽到更多與此相關的故事。\n\n穿越時空到這個境外之地、擊敗敵人，然後帶回消滅他們的消息。", progress = nil, completion = "你光榮地回歸，並帶回踩熄燃燒軍團之火的故事了嗎？", rewards = "您會收到：\n\n奈幽寶藏箱奈幽寶藏箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83364] = {title = "穿越時光的破碎之路", objective = "完成5次時光漫遊地城冒險。", description = "自從你的城市從天上掉下來之後，我學到了更多關於這個世界的歷史，以及像你一樣的英雄面臨過的挑戰。\n\n從歷史中學習是我們保障未來的方式。穿越時間到一個充滿地獄火的過去，再次擊倒那些威脅並將這些經歷帶回現實中。", progress = nil, completion = "你回來了，而我們的現實沒有崩壞。我就當作這是成功了。", rewards = "您會收到：\n\n奈幽寶藏箱幽坑城寶箱"}
MultiLanguageQuestData['tw'][83365] = {title = "穿越時光的冰封之路", objective = "擊敗5個時光漫遊團隊首領或地城。", description = "自從你的城市從天上掉下來之後，我學到了更多關於這個世界的歷史，以及像你一樣的英雄面臨過的挑戰。\n\n從歷史中學習是我們保障未來的方式。穿越時間到一個冰封的過去，再次擊倒那些威脅並將這些經歷帶回現實中。", progress = nil, completion = "你從時光穿越的旅途中帶回了什麼經歷？", rewards = "您會收到：\n\n奈幽寶藏箱奈幽寶藏箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83366] = {title = "世界任務正等著你", objective = "在卡茲阿爾加完成10個世界任務。", description = "也許我們可以把你的悲劇轉變成對我們雙贏的經歷。你有很多方式可以幫助土靈。\n\n盡你所能協助他們。", progress = nil, completion = "你的事蹟傳遍了我的族人。土靈傳頌著你的名字，直至聲名遠播。", rewards = "曲刃撕裂者森林皮束褲您會收到：\n\n青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83417] = {title = "不法之徒", objective = "與瑞澤克談話，確定他有合約報酬。", description = "我們是個傳統哥布林家族，而我甜心的婚約對象也來自這樣的家族。小倆口訂下合約，在結婚後彼此買斷，讓他們在結婚後可以享受一下兩人時光。\n\n我拿到錢，打算幫我甜心買斷她婚約對象的合約，不過，你知道嗎？要是她的婚約對象身上沒錢，沒辦法買斷我的小甜心的合約，事情就尷尬了。\n\n去找那個孩子談談，確定他為那個大日子做好準備。如果他還沒？那就幫忙搞定一切。", progress = nil, completion = "我就知道會發生那樣的事。做得好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83418] = {title = "完美外套", objective = "獲取華美羽毛外套材料。", description = "我的小公主值得擁有整個艾澤拉斯上最美好的東西，而她的衣服則要再乘以兩倍。不然其他人要怎麼知道我心目中的她有多麼完美？\n\n有個傢伙說他那裡有一匹珍稀毛皮，能用來幫我的女兒製作出最華美的外套。去見那個傢伙，把東西帶回來。最好別把它弄髒了。", progress = "滴答！", completion = "嘿，那看起來很時髦！那些羽毛一定能讓我的寶貝看起來超美！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83419] = {title = "完美的賓客名單", objective = "從剩下的賓客那裡取得出席的回函。", description = "完美的婚禮必須有完美的賓客名單！\n\n但我還在等一些人的回函。爸爸說他會確保他們出席，那意味著你得提醒他們，我的婚禮他們非到不可。那將會是這個小鎮前所未見的最大盛事！他們怎麼會不想來？我們可是一家人欸！算是啦。\n\n反正，讓這個名單上的所有人都同意出席我的婚禮。記得提醒他們，爸爸說過「不然就試試看」。", progress = nil, completion = "很好！座位的安排總算可以確定下來了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83420] = {title = "完美的宴席", objective = "與硬片大廚交談，並取得欠缺的食材。", description = "我完美的日子需要完美的食物！我一直在哥布林IG上找資訊，硬片大廚是我婚禮主廚的唯一人選。爸爸向我承諾會給我最好的，而他總是信守承諾！\n\n我需要你確定每一道菜在上桌時都很適合拍照打卡。每個人都必須知道我的婚禮有多麼美好。\n\n啊！我等不及想看到硬片大廚在我婚禮時端上的佳肴了！", progress = "硬片大廚是不是很天才？", completion = "我的婚宴菜一定會讓大家都很羨慕！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83421] = {title = "完美婚禮", objective = "阻止婚禮殺手，別讓他們對場地造成太多破壞。", description = "我雇了一些暴徒去毀掉婚禮。只有最棒的婚禮才會遭到破壞，對吧？\n\n但我又不想因此失去場地的定金。所以我需要你阻止那些暴徒，別讓他們太超過，懂嗎？", progress = nil, completion = "嘿！我拿回定金了。做得好。", rewards = "您能選擇下列奬勵中的一個：\n\n恆久承諾墜飾永恆之愛項鍊\n\n您還會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83432] = {title = "培育所", objective = "畢爾果絲希望你進入培育所，並終結斯卡汀威脅。", description = "我在多恩諾加四周的線人叫我要保密，但我信任你，主要是因為我需要有人去做這件事。\n\n我們在培育所中有個麻煩：斯卡汀肆虐。\n\n我需要有人把培育所裡的斯卡汀都清掉，找出麻煩的源頭，並放一顆巨石把它堵起來。\n\n在你完成這個任務後，回來找我領取獎勵吧。\n\n還有記得…別告訴任何人。", progress = "這麼快就回來了？我希望是好消息？", completion = "做得好，你現在是我最愛的英雄了。\n\n至少到明天之前是如此。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您能選擇下列奬勵中的一個：\n\n斷裂絲線表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83436] = {title = "燼釀酒莊", objective = "畢爾果絲希望你把風險投資公司趕出燼釀酒莊。", description = "我的一名叫溫布蘭特的線人捎來了消息。你或許有聽說過他。他負責燼釀酒莊的營運。\n\n他表示，一群跟自稱為風險投資公司有牽扯的哥布林正想要把酒莊奪走。我們不能讓他們得逞。我需要你到酒莊去排除威脅。\n\n燼釀蜜酒是土靈的東西，應該受到土靈的掌握。溫布蘭特會讓他們清楚意識到這件事，但在那之前，我得靠你來收尾。", progress = nil, completion = "溫布蘭特給我捎來了消息。做得好。\n\n收下你的獎勵吧。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您能選擇下列奬勵中的一個：\n\n斷裂絲線表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83442] = {title = "輾轉反側", objective = "在幽坑城搜索斯納普‧皮油的公寓，尋找結構圖。", description = "我的所有筆記。我的計畫！\n\n<斯納普憤怒地顫抖。>\n\n我只知道亂翻我公寓的人是邁特‧星火齒輪。他是我工作上的對手，很可能打算把我的最新發明嗅聞強化機5000型佔為己有！\n\n那是我們設計的格柵上的配件。在我外出覓食時，我剛剛為我們的老闆完成結構圖。等到我回來的時候…\n\n也許他沒找到它。先幫我找，之後再來解決邁特。", progress = "那張結構圖是將消音器樣式的零件裝在格柵上。它非常特別，你絕不可能錯過它！", completion = "&lt;斯納普將嘲諷的紙條揉成一團。&gt;\n\n喔，這次他別想搶走我的升遷機會！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83443] = {title = "暗焰裂縫", objective = "畢爾果絲希望你前往暗焰裂縫並面對無邊黑暗。", description = "我們有一位新盟友是個來自鳴響深淵的狗頭人，名叫史琦德，他聯絡了我。\n\n我需要你去暗焰裂縫除掉某個威脅，史琦德稱之為無邊黑暗。\n\n狗頭人大部分時間都在地底活動，怎麼會怕黑呢？這對我來說完全沒道理。不過狗頭人就是狗頭人，我不想浪費時間去理解他們。", progress = "如果你搞清楚這個無邊黑暗是怎麼回事，再跟我說吧。", completion = "所以無邊黑暗是個狗頭人？我還以為史琦德太誇大了呢。\n\n這是你的獎勵。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您能選擇下列奬勵中的一個：\n\n斷裂絲線表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83445] = {title = "臭臭的", objective = "到屋舍嶺的便宜牙飾與斯納普‧皮油交談。", description = "喔！那個邁特太讓人生氣了！他甚至還冒領功勞。我是對的。他打算向我們的老闆展示嗅聞強化機！\n\n事實上，他現在很可能正在這麼做。\n\n不過那給了我一個點子。我們或許沒有結構圖，但邁特不知道如何操作它。如果我們可以向老闆證實那不是邁特的設計，功勞說不定還是歸我！\n\n你有多擅長按按鈕？你願意幫我展示原型機嗎？", progress = "我們得快一點！邁特最多有一小時準備。\n\n一切都在我去休息的時候，那個王八蛋！", completion = "那個可惡、無腦、該死的工程師！\n\n他會為此付出代價！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83446] = {title = "停工", objective = "到屋舍嶺的便宜牙飾阻止嗅聞強化機5000型的生產。", description = "我們的簡報顯示我們才是真正能操作裝置的人！如果薩米不是那麼專注於邁特手中的文件…就算我們沒有結構圖，任何人都能清楚知道我們才是那東西的製作者！\n\n不過一切都還沒結束。你看到邁特如何超載嗅聞強化機了嗎？我們也能那麼做！一次按下一大堆按鈕，就能奪走他竊佔的所有不成熟想法！\n\n我們進去裡面，對原型機搞破壞，拖慢生產進度！", progress = nil, completion = "喔，呃，嗨，&lt;name&gt;。謝謝你幫我們撕裂那些壞掉的原型機。這是你的分成。\n\n結果，這一切都是誤會。他以為我偷了他的點子，才闖入我家。\n\n對於嗅聞強化機…氣味模擬器…隨便啦，他的確有不錯的想法。", rewards = "您會收到：\n\n失落靈感束帶失落靈感肩甲失落靈感鎖子甲　失落靈感護手共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83457] = {title = "石庫", objective = "畢爾果絲希望你終結石庫的斯卡汀腐化。", description = "我有份工作要交給你，是至高代言者布琳瑟親自指派的。\n\n斯卡汀的腐化快要遍布石庫了。為了阻止恐慌，至高代言者布琳瑟請求我們的幫忙。我跟她說她可以相信我們，就跟我們相信腳下的岩床一樣。\n\n到石庫去，根除斯卡汀的腐化吧。完成了再跟我說一聲。", progress = nil, completion = "你確實就像岩床，堅定又可靠。\n\n我會向至高代言者布琳瑟傳達你成功的消息。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您能選擇下列奬勵中的一個：\n\n斷裂絲線表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83458] = {title = "聖焰隱修院", objective = "畢爾果絲希望你前往聖焰隱修院並幫助伊特娜‧布雷茲修女。", description = "很高興見到你，<name>。我有個只有你能做的工作。\n\n阿拉希的伊特娜‧布雷茲修女認為聖焰隱修院裡有些不對勁。她沒有對目前的情況多做解釋。\n\n請去聖焰隱修院找修女。胃裡的小石頭告訴我說，她或許是對的，而且會需要你的幫忙。", progress = nil, completion = "有時候，你需要做的就是聽從你胃裡的小石頭。\n\n來，這是為了獎勵你付出的時間與努力。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您能選擇下列奬勵中的一個：\n\n斷裂絲線表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83459] = {title = "破曉者號", objective = "畢爾果絲希望你前往破曉者號，協助鐵擊將軍維持儀式的安全。", description = "我收到了來自阿拉希鐵擊將軍的消息。她請你參加一場破曉者號上面的儀式。\n\n她說的參加是指她需要額外的一雙眼睛，或是兩雙或五雙。你有在儀式當維安人員的經驗嗎？感覺就像是熔爐地的一灘黏稠泥巴。\n\n我很抱歉，不過鐵擊將軍已經提出了要求，我也只能簡單回答「好」。就跟俗話說的一樣，不是每座山爬起來都那麼刺激。", progress = nil, completion = "我收到消息說，儀式更像泥石流，而不是黏黏的泥巴池。\n\n幸好你當時在場。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您會收到：\n\n"}
MultiLanguageQuestData['tw'][83465] = {title = "『回音之城』厄拉卡拉", objective = "畢爾果絲希望你去阻止厄拉卡拉在進行的行動。", description = "我有個新線人叫輔臣，他的密探圖魯蒙來找過我們。\n\n我從沒想過會有奈幽蟲族來找我們幫忙，不過他們口中的危機似乎會威脅到我們所有人。\n\n我需要你下去阿茲-卡罕特並潛入『回音之城』厄拉卡拉。如果圖魯蒙所言不虛，我們就不能讓他們在下面策劃的陰謀成真。\n\n終結他們的行動。帶回你找到的證據。", progress = nil, completion = "黑血？我不確定那是什麼，不過如果奈幽蟲族覺得它很邪惡，那我就相信他們。\n\n來，請收下這個做為獎勵。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您能選擇下列奬勵中的一個：\n\n斷裂絲線表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83469] = {title = "蛛絲城", objective = "畢爾果絲希望你去消滅蛛絲城中所有的威脅。", description = "我們的奈幽蟲族盟友圖魯蒙又聯絡我們了。他提到一個叫做轉化場的地方，那裡正在進行恐怖的實驗。\n\n我需要你潛入城市，與輔臣會合來執行剩下的任務。\n\n消滅輔臣的敵人，終結這場威脅，然後回來找我領取報酬。", progress = nil, completion = "我不知道我信不信任這些奈幽蟲族，現在還不確定。\n\n他們策劃邪惡陰謀的能力，還有這些輔助黑暗計畫的設施…讓我打從心底不舒服。", rewards = "曲刃撕裂者雪怪項圈信念披風森林皮束褲您能選擇下列奬勵中的一個：\n\n斷裂絲線表揚\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83484] = {title = "喔，老鼠！", objective = "找到愛麗絲‧烤火。", description = "好了，我發誓，這不是笑話。我需要幫忙，因為…\n\n我把我最好的朋友變成老鼠了。\n\n我的朋友阿麗是這裡的廚師。她非常努力，卻…沒什麼用。她的嗅覺很遲鈍。於是我幫她買了一瓶藥水，可以讓她更有味道！\n\n…我是說，改善她的嗅覺。但它卻把她變成老鼠！然後她就跑掉了！\n\n你得幫我找到她。商人有另一瓶藥水，可以讓人聽懂老鼠的話。不過我不敢喝。\n\n你可以使用它，然後去找她嗎？", progress = nil, completion = "我不能永遠當隻老鼠。我需要你的幫忙！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83485] = {title = "強力飲料", objective = "幫助愛麗絲‧烤火。", description = "<嗅><嗅>\n\n這種藥水有大桶工廠的味道。北邊的外圍有一個商人，專門販賣藥水。一定是從他那裡來的。如果你能找到他，說不定能叫他交出解藥。\n\n拜託幫幫我。你是唯一一個能聽懂我的話的人！", progress = nil, completion = "如果你在讀這段文字，我去卡迦灣沿岸搜刮材料了。\n\n如果你是來收取欠款的話，你已經侵入私人土地，也不用管這張字條了。\n\n-蓋特利", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83486] = {title = "遠端工作", objective = "到贊達拉的卡迦灣找到蓋特利‧賽斯威。", description = "如果你在讀這段文字，我去卡迦灣沿岸搜刮材料了。\n\n如果你是來收取欠款的話，你已經侵入私人土地，也不用管這張字條了。\n\n-蓋特利", progress = nil, completion = "&lt;這裡的某處一定生長著紅莓。&gt;", rewards = "您會收到：\n\n下水道漫遊者肩墊下水道漫遊者手套下水道漫遊者護腕下水道漫遊者腰帶勇氣石"}
MultiLanguageQuestData['tw'][83487] = {title = "職業風險", objective = "採集紅莓材料，然後交還給韓福瑞。", description = "<你推測，採集足夠的紅莓，再交還給韓福瑞，應該就能讓愛麗絲變回普通的哥布林。>", progress = "<name>，解藥方面有什麼進展嗎？", completion = "再次感謝你的解藥。我們會保留它，以備不時之需。\n\n結果愛麗絲的廚師功力突飛猛進，並且打算繼續精益求精！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83489] = {title = "召集所有鬥士！", objective = "將廣告拿去給多恩諾加的爭奪者大門的霍桑。", description = "大家都來吧，前往多恩諾加！\n\n除了爭奪者大門提供的強大裝備之外，新來的戰鬥者和資深鬥士也可以購買徽章代幣，用來製造可以在競技場與戰場中使用的認證裝備！\n\n把這張傳單拿給霍桑來領取免費代幣！\n\n- 艾莎", progress = nil, completion = "啊，我正在想說，積極的鬥士什麼時候會出現呢。\n\n按照約定，拿去吧。提交製作訂單或製作你自己的裝備時可以用這些。成品就會跟拉蘭迪在那邊賣的裝備一樣強大，不過當你在找符合喜好的客製化裝備時，這些就很好用。如果你還需要更多，你知道該去哪裡找我。\n\n有問題嗎？把它們帶到熔爐地吧。", rewards = "您會收到：\n\n百鍊鬥士徽章"}
MultiLanguageQuestData['tw'][83492] = {title = "戰隊：一同奮戰", objective = "在加基森和小藍與她的戰隊碰面。", description = "嘿，<name>，我跟幾個朋友組成了戰隊，正在研究一個東西，讓我們在分散各處時也可以輕鬆合作！\n\n我們只剩下最後的步驟需要一點幫忙。\n\n等你有空的時候，到加基森來找我們吧！", progress = nil, completion = "&lt;name&gt;，感謝你過來！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83493] = {title = "戰隊：裂隙讀取器", objective = "掃描加基森附近的易位異常體。", description = "我敢說你很好奇我們在研究什麼，對吧？我們在做一個我們可以從任何地方存取的戰隊銀行！\n\n在我想到更有趣的名字以前，鉚釘會暫時叫它戰隊銀行遠距抑制器，不過我們需要人幫忙讓它完工。\n\n如果我們想確保我們可以在多個地點存取我們共同的資產，我們會需要傳送門！我們在外頭找到了一些好東西。\n\n如果你可以幫我們掃描一下當地異常現象的話，那就幫上大忙了！", progress = nil, completion = "這才叫閃閃發光的資料！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83494] = {title = "戰隊：岸邊的空間鬼魂", objective = "在加基森附近從部分傳送的生物身上收集空間殘渣。", description = "離這裡不遠的沙漠裡有一大堆傳送到一半的東西在四處遊蕩。老實說，就算只有一隻也是個令人驚訝的數量，不過不知道為什麼有一大堆！\n\n牠們稱不上友善，但我敢說我們可以從牠們的困境中學到一些知識，確保戰隊銀行遠距抑制器不會把我們珍貴的戰利品傳送到樹裡面！\n\n去看看你能不能找到一些資訊，讓我們了解哪裡出了差錯。畢竟人們不會隨便傳送來傳送去，對吧？", progress = "有什麼線索嗎？", completion = "&lt;name&gt;，做得好！我不太確定這是什麼，但我覺得這一定幫得上忙！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83495] = {title = "戰隊：雙生易位", objective = "啟動加基森外面的易位警示重組轉化原並面對後續發生的事情。", description = "我們勢如破竹！你不在的時候，我們接收到一個更異常的異常現象，追蹤的結果顯示地點在城鎮西邊。\n\n我們已經在那裡架設了一個全新的易位警示重組轉化原，但我想要等你回來再開始。畢竟你一路上幫了很多忙。\n\n你需要做的就是進行輸入，然後打開開關！簡單到不行，這是我聽說的啦。\n\n鉚釘說災難發生的機率挺樂觀的，所以我知道不會有壞事發生！", progress = nil, completion = "做得好！\n\n和我想像的不太一樣，但我得說邪惡版的我臉上的鬍子真帥！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83496] = {title = "戰隊：時空就是金錢", objective = "在加基森銀行放置重組轉化原反向工程矩陣。", description = "既然我們已經取得所有的易位數據，我們需要做的就只剩下在適合的銀行設下蟲洞，這樣我們很快就可以在野外把裝備丟進彼此的口袋之中了！\n\n而且加基森這裡正好有個銀行！\n\n你甚至可以同時幫你自己的傳送門調頻，好隨時在任何地方存取你自己的戰隊銀行。這樣一定超方便的！", progress = "你找到銀行了嗎？", completion = "出現了一些小問題，但沒有什麼是好用的老方法：團隊合作無法解決的！上吧！", rewards = "您會學到：\n\n戰隊銀行遠距抑制器\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][83497] = {title = "擔憂的朋友", objective = "在米雷達爾與偉大的凱隆會面。", description = "啊，<name>，你來了！偉大的凱隆正在關心你和你的朋友安杜因。\n\n我認為他們想跟你討論法林的事。不是什麼緊急的事，她大概只是需要人陪。不過我們都有點擔心她。\n\n等你有空的時候，去找凱隆聊聊吧？", progress = nil, completion = "我希望路程不算太遙遠。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83499] = {title = "秘法荒地", objective = "在平靜淺灘協助埃薩‧奪日者收集必要材料，以便施放防護法術。", description = "祈倫托的倖存者很猶豫要不要回來這個地區。在達拉然墜落的前後，大量的能量遭到驅散。一股看不見卻實際存在的瘴氣滯留在這個地區，影響著對其敏感的人。\n\n我們還不確定這個地方會不會造成危害，或是有其他更具體的危險潛伏在此。\n\n我可以保護我們，但我把所有的施法材料都花在舞臺那裡了。你可以協助我取得更多嗎？", progress = "過去這幾天…很不好過。", completion = "很好，這樣就夠了。謝謝你，&lt;name&gt;。\n\n儘管那裡遍布著碎片和元素生物，但那些廢墟似乎沒有立即的危險。不過，如果我們要在這裡待上一段時間，最好還是建立一道秘法屏障。\n\n畢竟我們不清楚長期暴露在這種環境中會有什麼影響。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83500] = {title = "先驅之手澤克維爾", objective = "在先驅者之手澤克維爾的探究中擊敗他。", description = "我們在這些探究中探索時，必須小心澤克維爾。我想我們現在還不夠強，沒辦法擊敗他，但之後一定可以的！\n\n讓我們繼續探索並收集寶藏，等到累積足夠的實力，再去追查他的巢穴並擊敗他。", progress = nil, completion = "我們成功了！我們替所有冒險者把這地方變安全了。\n\n現在薩拉塔斯失去了她最強大的一名附庸，這應該會讓她陷入困境。", rewards = "您會收到：\n\n劇毒勝利"}
MultiLanguageQuestData['tw'][83502] = {title = "防護魔法課程", objective = "在平靜淺灘協助埃薩‧奪日者施放法術來創造秘法護罩。", description = "屏障的法術準備好了，但我必須引導它並設定它的參數。\n\n在我引導法術的時候，把這些結界拿去，把它們放在屏障預定的邊界。\n\n等你弄好之後，我們就會為法術提供能量。", progress = nil, completion = "&lt;埃薩深吸一口氣。&gt;\n\n好，先這樣就行了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83503] = {title = "返回多恩諾加", objective = "返回多恩島的多恩諾加，回報來龍去脈。", description = "戰鬥終於結束了，我想該是療傷的時候了。\n\n回到多恩諾加，勇士。\n\n等到卡德加的身體恢復到能夠行動的程度，我就會馬上回去那裡。", progress = nil, completion = "每一場仗我們都打得很辛苦。而且總是一波未平，一波又起。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83519] = {title = "那賭場怎麼辦？", objective = "在加樂宮開幕派對詢問羅斯巴‧加里維克斯的事。", description = "時代在變。現在老加斯特已經下台，而各個集團的頭頭都想奪得幽坑城的至寶：加樂宮。\n\n明天將會舉行會議來決定這件事，但幸好，這件事完全掌握在我能信任的人手中。\n\n他名叫羅斯巴‧加里維克斯。\n\n我知道，我知道。但羅斯是個好人。我之後會再介紹給你認識。\n\n首先，先幫我一件事。去問問派對裡的貴賓對新主人的看法吧。", progress = "別被加里維克斯的名字給嚇到了。他們家族龐大，也不是每個人都是壞胚子。", completion = "這…很糟。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83522] = {title = "債臺高築", objective = "與凱傑和神奇的戴維談談簽加樂宮權證的事。", description = "清單上第一個羅斯巴的首席就是遊戲界的天才雙人組：凱傑和神奇的戴維。\n\n我從我妻子的兄弟那裡聽說，風險投資公司買下了他們兩人的債務，還很剛好是羅斯巴‧加里維克斯出事的當下。\n\n他們把他殺了嗎？如果他們債務很多的話，這可不是個好動機。但也不會有人知道是誰在掌控那個哥布林。\n\n最好的辦法就是把他們帶來風險木材廠的舊掩埋場。如果他們不想簽新權證，我們就知道罪魁禍首是誰了！", progress = nil, completion = "你看吧？他們跟贊達拉甲殼蟹一樣逍遙自在。\n\n但如果你真的想要他們的服務，我們或許可以談談…", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83524] = {title = "垃圾裡有黃金", objective = "在垃圾場完成角子機採礦。", description = "凱傑和戴維確實是設計遊戲的好手。他們還為我設計過一個超高人氣的遊戲。\n\n如果你願意承擔風險的話，我就給你個機會從我手中贏得雇用他們的權力，以及他們的債務。\n\n去拿一把十字鎬，然後進到掩埋場吧。當哨音響起後，你將會與我其他的「員工」來一場競賽。\n\n在最後一聲鐘響前取勝，我就會放那兩個人走。輸了，你就是我的了。\n\n這就是角子機採礦。你那條小命很快就會是我的了。", progress = nil, completion = "你沒有贏。還真教人感到意外。\n\n歡迎加入塔波納拉的欠債團。好戲還在後頭呢…", rewards = "您能選擇下列奬勵中的一個：\n\n最後希望指環最後險招之戒\n\n您還會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83527] = {title = "反正本來就有風險", objective = "收集債務印記，並釋放欠債者。", description = "這是我有史以來做過最爛的工作。我之前還在暗月馬戲團顧烏龜丟圈圈呢。\n\n雖然我們沒被鍊子綁著，但塔波納拉握有我們的債務。他把資訊都記在債務印記上，而他的手下也都有這些紀錄，還藉此欺壓我們。\n\n如果你拿到那些印記的話，我們就能重獲自由了。但要拿到的話得先好好教訓他們，所以你每教訓一個手下，我就給你一分。\n\n你最喜歡累積分數了，對吧？", progress = nil, completion = "大家準備好了嗎？很好！這絕對不會再讓我們被攔下來了。\n\n實在是太感謝你了，&lt;name&gt;。真的。加樂宮準備要迎來許多的遊戲愛好者了！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83528] = {title = "全都是一場遊戲", objective = "從克德‧乳牙專員手上取得凱傑和神奇的戴維的債務。", description = "聽著。我知道我們有欠債，但羅斯巴相信我們！有了他，我們才在賭場的另一端有了希望之光。\n\n現在他不在了…我們就只是兩個空有腦袋的遊戲天才，為了工作而工作。\n\n但速車告訴我們，我們還有機會可以在加樂宮工作。這是真的嗎？如果是真的，戴維和我就加入。\n\n問題是，戴維和我的債務全都在遊戲專員：克德‧乳牙的手上。而他還有小塔波在背後撐腰。", progress = nil, completion = "你花了多少錢才取回他們的債務印記？\n\n噢…那我應該是不用幫你填報銷表單了！", rewards = "您會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83529] = {title = "聖落之地釣魚大賽", objective = "在大賽突進者增益效果消失前，捕捉這些戰利品魚：苦鉍魚、低語凝星魚、莊嚴點背魚。", description = "這裡的生活一向很刺激，$p。奈幽蟲族、寇拜斯、飢餓，總是有東西想要你的命。\n\n所以我們需要找時間放鬆一下，挑戰一下努力生存以外的東西。比如說釣魚。\n\n在我童年時期，我爸每個星期六都在釣魚。他會說：「花點時間照顧你自己，不然你就無法照顧別人。」\n\n所以每個週六，我都會邀請人一起挑戰聖落之地釣魚比賽。你有一小時去抓戰利品魚。看看你能帶什麼魚來給我吧！", progress = nil, completion = "真是不錯的收穫，&lt;name&gt;！我等不及看你下週會抓到什麼魚了！", rewards = "您能選擇下列奬勵中的一個：\n\n[Soaked Journal Entry]阿爾加追尋者絲線阿爾加釣手絲線\n\n您還會收到：\n\n米雷達爾大賽獎章"}
MultiLanguageQuestData['tw'][83530] = {title = "聖落之地釣魚大賽", objective = "在大賽突進者增益效果消失前，捕捉這些戰利品魚：血紅鱸魚、咆哮釣手尋覓魚、尖刺鮟鱇魚。", description = "這裡的生活一向很刺激，$p。奈幽蟲族、寇拜斯、飢餓，總是有東西想要你的命。\n\n所以我們需要找時間放鬆一下，挑戰一下努力生存以外的東西。比如說釣魚。\n\n在我童年時期，我爸每個星期六都在釣魚。他會說：「花點時間照顧你自己，不然你就無法照顧別人。」\n\n所以每個週六，我都會邀請人一起挑戰聖落之地釣魚比賽。你有一小時去抓戰利品魚。看看你能帶什麼魚來給我吧！", progress = nil, completion = "真是不錯的收穫，&lt;name&gt;！我等不及看你下週會抓到什麼魚了！", rewards = "您能選擇下列奬勵中的一個：\n\n[Soaked Journal Entry]阿爾加追尋者絲線阿爾加釣手絲線\n\n您還會收到：\n\n米雷達爾大賽獎章"}
MultiLanguageQuestData['tw'][83531] = {title = "聖落之地釣魚大賽", objective = "在大賽突進者增益效果消失前，捕捉這些戰利品魚：躊躇雅羅魚、多恩狗魚、阿茲-卡罕特髒鯊。", description = "這裡的生活一向很刺激，$p。奈幽蟲族、寇拜斯、飢餓，總是有東西想要你的命。\n\n所以我們需要找時間放鬆一下，挑戰一下努力生存以外的東西。比如說釣魚。\n\n在我童年時期，我爸每個星期六都在釣魚。他會說：「花點時間照顧你自己，不然你就無法照顧別人。」\n\n所以每個週六，我都會邀請人一起挑戰聖落之地釣魚比賽。你有一小時去抓戰利品魚。看看你能帶什麼魚來給我吧！", progress = nil, completion = "真是不錯的收穫，&lt;name&gt;！我等不及看你下週會抓到什麼魚了！", rewards = "您能選擇下列奬勵中的一個：\n\n[Soaked Journal Entry]阿爾加追尋者絲線阿爾加釣手絲線\n\n您還會收到：\n\n米雷達爾大賽獎章"}
MultiLanguageQuestData['tw'][83532] = {title = "聖落之地釣魚大賽", objective = "在大賽突進者增益效果消失前，捕捉這些戰利品魚：晶化鱘、鏡面彩虹魚、血紅狗鯊。", description = "這裡的生活一向很刺激，$p。奈幽蟲族、寇拜斯、飢餓，總是有東西想要你的命。\n\n所以我們需要找時間放鬆一下，挑戰一下努力生存以外的東西。比如說釣魚。\n\n在我童年時期，我爸每個星期六都在釣魚。他會說：「花點時間照顧你自己，不然你就無法照顧別人。」\n\n所以每個週六，我都會邀請人一起挑戰聖落之地釣魚比賽。你有一小時去抓戰利品魚。看看你能帶什麼魚來給我吧！", progress = nil, completion = "真是不錯的收穫，&lt;name&gt;！我等不及看你下週會抓到什麼魚了！", rewards = "您能選擇下列奬勵中的一個：\n\n[Soaked Journal Entry]阿爾加追尋者絲線阿爾加釣手絲線\n\n您還會收到：\n\n米雷達爾大賽獎章"}
MultiLanguageQuestData['tw'][83534] = {title = "連暖身都不算", objective = "為地窖地精宣傳，並召集觀眾。", description = "真不敢相信里維加茲把我們排在第一個！沒有人會來聽第一組樂團啦！\n\n隨便啦。你是老馬蒂提過的那個人嗎？他早就告訴我你不讓加樂宮被拍賣掉的大致計畫了。聽起來有點荒唐，但這個計畫很適合我們。\n\n我們來談個交易吧。我們的經紀人在賭場的交易告吹時把我們丟包了，所以你要來填補她的空缺。不用擔心，不會比你做過的其他工作還糟。\n\n現在第一件要做的，就是幫我們召集觀眾。", progress = nil, completion = "幹得好，老大。你找來了觀眾，而且人數蠻多的。\n\n再來第二件事…你應該知道要怎麼彈奏樂器吧？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83535] = {title = "劫掠派對之亂", objective = "在表演期間用機甲三邊鐘來保護地窖地精。", description = "來！這個機甲三角鐘給你！\n\n你會不會彈奏樂器已經不重要了，因為你現在要用這個。\n\n當我們在熱血表演的時候，其他樂團的成員會衝上台來阻止我們。\n\n三角鐘不只能完美搭配音樂，還會把樂團以外的其他人都噴到場地最邊邊。", progress = nil, completion = "這是我們有史以來演奏過的最大一場！簡直是個戰區，對吧？\n\n你幹得很好。去拿老傢伙的新契約吧，我們會簽名的。", rewards = "您會收到：\n\n舞台破壞者手套舞台破壞者腕環舞台破壞者肩衛舞台破壞者腿甲共鳴水晶勇氣石幽坑城集團"}
