MultiLanguageQuestData['tw'][83539] = {title = "心情憂鬱", objective = "在平靜淺灘建立祈倫托前哨站。", description = "這裡…恐怕只剩下我一個人了，<name>。也許其他人只是距離太遠，收不到我的信件。\n\n我們可能得在這裡建立一個哨站，並清理墜毀地點。\n\n就這樣吧…", progress = nil, completion = "做得好。那個袋子很好用，對吧？很慶幸我當初把它帶在身邊。\n\n現在，繼續處理手邊的任務…", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83540] = {title = "穿越排隊潮", objective = "讓馬林‧諾格弗格說出喬喬‧哥布瑞的去向。", description = "不知道你的鼻子是不是和我的一樣，在開車過來的路上就嗅到了，但下方的街道有股令人愉悅的味道。\n\n問題是，人群太多，害我找不到哥布瑞。\n\n這就要麻煩諾格了。他近期是個大人物，我想他會幫我們的忙。\n\n他看起來就像個什麼話都不會說的冷酷科學家，但他的自尊就跟我妻子的兵團模型一樣，一碰就碎。\n\n去激他一下，他應該會透漏消息。", progress = nil, completion = "諾格弗格還給你了私人推薦信？\n\n如果他覺得我會讓人插隊的話，那他比我想像中的還要笨。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83541] = {title = "評論轟炸", objective = "取回100張食客評論卡。", description = "讓我看看你不是只會講大話的人。\n\n我會讓每個客人填食客卡。他們本該在上頭寫下他們對菜單的感想，並交回來。但我一張都沒看到。\n\n很詭異吧？沒錯。這個情況還真不妙。\n\n去吧。去幫我拿回評論。沒有它們，我對加樂宮的看法就不會改變。", progress = "他們覺得密林水果紅酒漬風暴魟魚怎麼樣？\n\n我敢打賭他們會覺得很苦。我知道那一批的味道是苦的。我在煮的時候，鹽巴剛好用完了。", completion = "食客們會懶可以理解。\n\n但連我的對手也在收評論卡，就因為塔波納拉告訴他們這樣就可以攆我走？真的假的？他們就不能…煮更好吃的東西出來嗎？\n\n不重要了。雖然你不是廚師，但我想你完成任務了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83542] = {title = "以魚換金", objective = "用金魚交換哥布瑞的寶貴平底鍋。", description = "嘖…我就知道會發生這種事。\n\n食客們特別喜歡一道菜：鍋煎深行者大腿肉佐油封血味阿爾加錐頭草。\n\n菜名很長，對吧？我原本以為客人會因為菜名太長而不寫在評論卡上。\n\n問題是，要是沒了平底鍋，我又該怎麼鍋煎呢？而且我在加樂宮出事後，就把我最寶貴的平底鍋賣掉了。\n\n要我重操舊業？那就去找回我的平底鍋。那些深行者的大腿肉是不會自己煎熟的。", progress = "布萊兒和查布‧貝斯。兩個騙子夫妻檔。\n\n但他們的確會幫我找來最好的魚。", completion = "你雖然不是當廚師的料，但你的確很會幫忙找東西。", rewards = "您會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83543] = {title = "卡茲阿爾加的冒險", objective = "檢視偵察地圖，選擇卡茲阿爾加的一個地區來提供支援。", description = "卡茲阿爾加的各個角落都有我們的斥候，他們回報的都是同一件事：麻煩。\n\n看來我們來的時機剛剛好，對吧？\n\n瞧瞧你後方桌上的偵察地圖，看你有沒有可以幫上忙的地方。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83546] = {title = "責任", objective = "收東西並開車前往法院。", description = "今天該好好打扮了，<name>！\n\n我們拿到契約簽名了。我們有各個集團的支持。我們還有…我的孩子。\n\n我的妻子今天原本要一起來的，但她在洗澡時不小心跌倒了！你敢相信嗎？她一整個早上都得去找治療師了。我為她感到難過。真的很難過。\n\n反正！這是她的損失！我們把需要的東西都收一收，我載大家到法院去！", progress = nil, completion = "哇！人真多，對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83548] = {title = "多恩島", objective = "在多恩島上和珍娜‧普勞德摩爾女士交談。", description = "達拉然被攻擊後的倖存者正被女王近衛吉里克斯率領的奈幽蟲族包圍。\n\n伸出你的援手保護剩餘的人。", progress = nil, completion = "我們不會讓奈幽蟲族再奪走我們任何一個人民。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83550] = {title = "鳴響深淵", objective = "在鳴響深淵與代言者布琳瑟會合。", description = "代言者布琳瑟前往了鳴響深淵，看看在她不在的這段期間機語者過得怎麼樣。\n\n她請冒險者在地心通途的底部一起加入她。", progress = nil, completion = "感謝你前來。情況比我想像的還糟糕。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83551] = {title = "聖落之地", objective = "和聖落之地的法林‧洛薩對話。", description = "安杜因‧烏瑞恩希望能獲得信任並幫助聖落之地的阿拉希人。\n\n他需要協助才能說服這些潛在的盟友。", progress = nil, completion = "如果你是來尋求幫助的，恐怕我們正處於自己的危機當中。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83552] = {title = "阿茲-卡罕特", objective = "在阿茲-卡罕特的清算號上和法林‧洛薩交談。", description = "一艘阿拉希飛船在阿茲-卡罕特遭受兇惡的奈幽蟲族伏擊。\n\n幫助倖存者抵禦奈幽蟲族的襲擊。", progress = nil, completion = "&lt;name&gt;，來得正好。我們被偷襲了。讓我們一起擊退敵人。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83553] = {title = "竊法狗頭人", objective = "在多恩島的悼念高地與卡雷苟斯碰面。", description = "我們的達拉然「清理行動」範圍恐怕遠超多恩島的海岸。\n\n在我嘗試找到你的過程中，我在島上繞了許多圈。在我飛行途中，我感應到了許多熟悉之物的魔力，那些是以前保存在達拉然的物品。\n\n危險的物品。\n\n某個人或某個東西把它們帶到了沒人知道的地方。我們必須在無辜的路人受傷之前找到這些物品。\n\n跟我來。", progress = nil, completion = "我們從這裡開始搜尋。\n\n我能感覺到這棟建築的周圍和下方散發出微弱的秘法光環。\n\n它們一定是被狗頭人帶來這個地方。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83554] = {title = "飾品、古董和其他強力物品", objective = "從悼念高地的狗頭人手中拿回失竊的祈倫托神器。", description = "這裡的狗頭人竊取的物品可能會為他們帶來無數的麻煩。\n\n盡可能拿回他們竊取的物品…可以不擇手段。\n\n當你在解決悼念高地墓地附近的狗頭人時，我會前往地底，搜索克里格瓦之眠，並採取相同行動。\n\n等你拿回狗頭人偷走的祈倫托神器後，就到克里格瓦之眠附近找我。", progress = "我們必須搜尋並搶回我們找到的東西。就算是最微小的骨董，也可能對某個人意義重大…或是極度危險。", completion = "看見他們在如此短的時間內有辦法搜刮這麼多東西著實讓我感到震驚。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83555] = {title = "神秘項鍊", objective = "在多恩島的悼念高地把項鍊還給卡雷苟斯。", description = "<寶石脈動著的秘法能量，暗示著織入其核心的遠古魔法。>", progress = nil, completion = "你是說，拿走這東西的狗頭人死了？\n\n那…好像不太妙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83556] = {title = "也許你不該碰那個", objective = "在悼念高地調查翡翠項鍊。", description = "這條項鍊…\n\n它顯然富含強大的魔力，不過…它很隱密，就像是在對我隱藏它的來源一樣。\n\n你再仔細看看。或許有什麼很明顯的線索是我沒注意到的。", progress = nil, completion = "我放鬆警惕的行為真是愚蠢。\n\n不要緊張，&lt;name&gt;，不過這東西好像是個…類似次元袋的東西。\n\n從這裡那些遭遇不幸的狗頭人看來，要回到多恩島可能會很困難。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83558] = {title = "法院如賭場", objective = "使用X-Plo-Dar 64k來找出是誰握有炸彈開關。", description = "我已經準備好要解決這個案子了。但有一件小小的事情要讓你知道…\n\n我這張桌子底下有炸彈。\n\n別緊張！這不是第一次了。但這裡有很多人，我也不想因為有小小的炸彈而中斷這件事。\n\n拿著這個X-Plo-Dar 64k。透過它用炸彈的信號來追蹤握有開關的哥布林。\n\n根據我的律師直覺，設下這個炸彈的人也是羅斯巴的殺手。我有預感。", progress = nil, completion = "塔波納拉？他是炸彈客？…真的假的？\n\n我感到驚訝是因為這太明顯了！", rewards = "您會收到：\n\n機關嗅探者兜帽機關嗅探者肩甲機關嗅探者護脛機關嗅探者裹手勇氣石"}
MultiLanguageQuestData['tw'][83563] = {title = "吃閉門羹", objective = "擊敗塔波納拉‧嘶軸，並確保法官藍德羅為新的加樂宮權證進行公證。", description = "你找到我們所需的關鍵證據了。現在要做的就是向法官揭露羅斯巴的殺手了。\n\n我可以猜到塔波納拉不會輕易認罪，所以他一定會準備好各種各樣的哥布林式藉口。\n\n你懂我的意思。炸彈、大砲、哭戲、賭場搶案之類的。但我不擔心，你很可靠。", progress = nil, completion = "還記得我說的嗎？我說他一定會找藉口。還真的，正如我們所料。\n\n如你所見，大家都跟著加茲魯維和塔波納拉的手下打起來了。我們幹得不錯，對吧？\n\n我嗎？我要去加樂宮大門。新的契約人要跟我在那邊會面，我想在我們兩人從律師變成顧客之前，先祝他們開業大吉。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83566] = {title = "噢，那間賭場！", objective = "把加樂宮交出來。", description = "你確實是個好律師，你知道吧？\n\n哈！開玩笑的！這個產業的機密就是，才沒有什麼好律師！\n\n不如你跟我去加樂宮大門吧。對現在要經營這個地方的孩子們來說，這會是個不錯的送別回憶吧。\n\n更不用提我們要把公證的權證交給他們了！", progress = "因為冒險結束，所以你才淚眼汪汪嗎？\n\n還是你暗地希望這個地方會被拍賣掉，而你有機會買下來嗎？\n\n我敢打賭是後者！哈！", completion = "這個下水道日常就是隨時都有麻煩事。對吧，&lt;name&gt;？\n\n但這個…姑且說，這對幽坑城的所有人來說是個福音。\n\n這雖然不是市鑰，但馬蒂想把他最好的律師衣裝留給你。心懷驕傲地穿上它吧，孩子。", rewards = "您會收到：\n\n公眾防衛者外套共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][83569] = {title = "死亡與稅賦", objective = "和幽坑城政府指派的公設辯護律師會面。", description = "他就這樣…爆炸了…\n\n如果要哥布林死，就只能這樣了。這就是我對可憐羅斯的感受了。我會想念他的。我們也要查出是誰幹的！\n\n但有個更緊迫的問題：現在加樂宮是歸誰的？\n\n是時候來找法律專業人士了。幽坑城政府派了一個名叫速車的公設辯護律師，他明天會帶我們去法院處理案子。這案子全靠他了。\n\n去屋舍嶺把剩下的權證交給他，然後解決這件事。", progress = nil, completion = "我可以向你保證，我通常都會淹沒在我的文書工作中，遠比剛才誇張得多。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83587] = {title = "我們出擊的機會", objective = "到皇家藥劑室與輔臣碰面。", description = "<看起來很幼小的蜘蛛拿給你一個密封的卷軸。密封的信上有著輔臣的印記。>\n\n阿茲-卡罕特的力量平衡正在變換。女王每天都變得更不穩定，我們恐怕必須在機會消失之前阻止她從我們手中溜走。\n\n收到信後來皇家藥劑室見我。", progress = nil, completion = "我也想派我的私人侍從過去接你，但現在的情況需要保密行動。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83616] = {title = "固若金湯", objective = "為大紡織者安托芮克絲效力，對抗雷恩卡特。", description = "現在該來處理這場政變的另一塊拼圖了。\n\n我在大紡織者安托芮克絲的大顎之下工作一段時間了。她固守在拉克-阿哈特內，覺得沒有任何人能威脅到身處頂端的她。她已經拒絕臣服於雷恩卡特。\n\n就算她清楚知道，雷恩卡特若得到王權的支持，那一切也只是時間問題。讓我們來促進她對這個狂妄份子的驅逐行動。\n\n看看他們反目成仇的速度有多快。", progress = nil, completion = "呃。我沒時間做這種事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83627] = {title = "美好的開始", objective = "把裝有天銳者血液的瓶子交給沙爾巴。", description = "<奈幽鍊金師似乎會對這個感興趣。\n\n晉升是他們最拿手的領域，這或許是進一步了解這個過程的關鍵。>", progress = nil, completion = "嗯？什麼？這還真是驚人…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83628] = {title = "放鬆緊繃", objective = "和陌生人交談來改善與阿拉希人的關係。", description = "和這些陌生人的關係很…緊張。能夠以他們的營地作為掩護讓我們很感激。但看起來他們只是在忍受我們的到來。我們提出分享我們的補給，但這似乎冒犯到了他們。\n\n我的姊妹身受重傷。我在那邊的帳篷看到了可以救助她的草藥，但那隻巨大的蝸牛擋住了入口。我過不去。\n\n我向山丘上的守衛請求協助，但他只是瞪著我。我不知道該怎麼辦！也許他會聽你的？", progress = nil, completion = "我並非不歡迎你，陌生人。我是最後的古樹。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83629] = {title = "古樹的歇息", objective = "為戈亥擊殺15個暴食的蜱蟲。", description = "這曾經是一座大湖。隨著時間過去，根鬚破壞了地面，並把水全部都吸走了。我這一生都生活於此，見證了一切。但是現在，我們迎來了更黑暗的變化。\n\n有時候變化會帶來死亡。衰敗即是自然。\n\n但那些以我的人民為食的蜱蟲並不是這樣。它們散播一種奇怪的感染，讓我的樹皮感覺像從身體裡蔓生出來。\n\n摧毀這些蜱蟲，讓我安息，不必在睡眠形態時懼怕它們啃食我。", progress = nil, completion = "一切都安靜下來了。也許現在我可以和我的族人一起休息了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83632] = {title = "記憶之環", objective = "將戈亥的樹根帶到歐爾雷野營地。", description = "我很感激你做的一切。不用擔心，我還沒說完。\n\n如果你願意，請拿著這塊樹根回到派你過來的人那裡。他們可以透過年輪來看到我一生的歷史。我的生命只是織錦中的眾多絲線之一，但我們所有人都交織在一起。\n\n你遇到的這些陌生人可能在隱居，甚至有點神秘，但是他們理解這種織錦的能力無人能及，而他們會用生命來守護它。", progress = "你找到古樹了嗎？", completion = "戈亥給了我這塊樹根，他還活著…\n\n我明白了。他的故事在我們這裡會很安全。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83639] = {title = "開放溝通", objective = "與伊莎蓓爾交談並解除誤會。", description = "你知道其他人過著和你截然不同的生活。我們的方式限制了我們。我們的傳統不適合說給陌生人聽。我會告訴你只是因為歐薇娜的一番話。但我從這裡就能感覺到昂錫爾的不滿。\n\n有時候謎團會讓人感到不舒服。就像是許多人害怕黑暗的道理一樣。因為那是未知的。\n\n我知道我看起來神神秘秘的。但我們的方式並不代表阿拉希人冒犯了我們。他們在製造根本不存在的緊張局勢。", progress = nil, completion = "不敢相信這只是一個簡單的誤會。我不該隨便下定論的。\n\n謝謝你讓我變得輕鬆多了，也謝謝你幫助我的姐妹。", rewards = "您會收到：\n\n織絲者(惡名值)卡吉卡吉"}
MultiLanguageQuestData['tw'][83641] = {title = "困於生死之間", objective = "找到離開微型異次元的方法。", description = "微型異次元。這是古老的魔法。\n\n當瑪里苟斯不想被打擾的時候，他偶爾會使用微型異次元。\n\n法師主要將其作為研究空間，或用來測試危險的法術。或者，那個法師正在做些不想被人發現的事…\n\n不知道這個是誰創造的？不過那不重要，反正我們都得想辦法出去。\n\n幸好，每個微型異次元都有出口。不過，它通常藏得很隱密。\n\n我們去找出來吧。", progress = nil, completion = "快看！殘留在那條項鍊中的魔法已經消失了。而且，科爾蘇加德的鏡像也跟著不見了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83643] = {title = "意外存活", objective = "在平靜淺灘與卡雷苟斯重新碰面。", description = "我們在科爾蘇加德的微型異次元裡經歷的事情恰好提醒了我們，不顧道德或規定胡亂使用魔法會有什麼後果。\n\n對我來說，這強調了祈倫托的存在有多重要。\n\n不過真要說的話，科爾蘇加德也曾是一名祈倫托。這也提醒了我們權力如何使人腐敗。\n\n現在我們已經確保這些神器不會讓別人踏上意外的旅程了…我們回去埃薩那裡吧。\n\n也許現在有更多人對他的信做出回覆了。", progress = nil, completion = "看來有更多法師前來了！\n\n這給了我希望。\n\n相信埃薩一定鬆了口氣。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83711] = {title = "征服的武器", objective = "在積分競技場和戰場上取得征服點數。", description = "英雄，你卓越的表現甚至傳到了我耳裡。如果你能像他們口中的那樣戰鬥，也許你會比我的其中一個造物還要更強大。在歷史寫下你的名字。當你證明自己擁有精湛技巧與榮譽心時，回來這裡找我。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83715] = {title = "取回回收物", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83716] = {title = "樹根之下", objective = "在西阿茲-卡罕特找到避難的營地。", description = "<name>，很高興看到你過得很好。我最近收到關於一些空騎士在飛船失事地點附近的營地避難的消息。\n\n你可以幫我去看看他們的狀況嗎？", progress = nil, completion = "我們已經盡力利用手邊有的資源了。這座營地的主人允許我們在這裡尋求庇護，但這裡並不怎麼友善。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83718] = {title = "護卵大作戰", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83719] = {title = "甲殼之語", objective = "為沙爾巴的實驗收集足量奈幽蟲族甲殼。", description = "嗯，這還真是個有趣的樣本。這隻生物的造物主似乎在基因平衡上犯下了極大的錯誤。也難怪你會覺得遇上怪物了。這手法還真是拙劣！\n\n但只要有適合的材料，我就可以讓牠變得更加完美。希思芭將會是我們的試驗體。他的晉升或許能吸引那些管理升遷的人的注意！", progress = "甲殼樣本能協助強化希思芭新形態下的力量。", completion = "我會好好使用這些甲殼的！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83720] = {title = "毒液？多多益善", objective = "為沙爾巴的實驗收集足量奈幽毒液。", description = "既然現在已經取得足量用來製作完美護甲的甲殼樣本了，我們還需要完美的毒液。別那樣看著我。我們的形體必須時時維持強大力量，還要有能力可以保護自己！\n\n我會開始製作希思芭晉升的全新甲殼，與此同時，我需要的東西就交給你去採集了。但要注意，一定得是奈幽蟲族毒液。一定要。恐怕甲蟲或蜘蛛這次都沒用了。\n\n至於要去哪裡找毒液，你可以自己決定。", progress = "太好了！這正是我要找的東西。", completion = "這樣應該行得通。該進行實驗的最後階段了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83721] = {title = "血流成海", objective = "為沙爾巴的實驗收集足量奈幽鮮血。", description = "太棒了！就快看到終點了！雖然我們即將大功告成，不過要是缺了這個基因方程式最重要的部分：血液，就還是無以為繼。我們需要不少奈幽蟲族的血。\n\n不過，為了確保這次的新型態萬無一失，一定要用奈幽蟲族最強者的血，天銳者或晉升者的都可以。這能保證我們拿到的基因素材是最好的。\n\n這種素材才配得上希思芭！", progress = "我們的實驗就要開花結果了，異族人。", completion = "做好準備，你即將見證完美！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83722] = {title = "令人欣慰的飛行", objective = "從沙爾巴手中收下希思芭。", description = "唉…太倒霉了。\n\n我的實驗好像失敗了，而希思芭付出了代價。不過，我非常看好這項實驗未來的發展。我遲早會讓整個流程達到最完美。到了那個時候，我或許就能策劃自己的晉升！\n\n儘管希思芭的實體跟我的預期差距很大，但他的心靈似乎還算完好。相信他一定能派上用場。帶他走吧。比起放在我這間小店，戰場才是最適合他這個新形態的地方。", progress = nil, completion = "&lt;大肆嘲笑沙爾巴一番後，希思芭興奮地站到你身旁。&gt;", rewards = "您會收到：\n\n希思芭"}
MultiLanguageQuestData['tw'][83723] = {title = "伸出援手", objective = "幫助法師脫離他們在多恩島的傳送門。", description = "卡雷苟斯的假設是正確的，達拉然的瓦礫干擾了長途傳送。\n\n法師的傳送門沿著海岸顯現，但沒有人從裡面走出來。那些法師很可能被困在傳送門中。\n\n或者，達拉然釋放的力量可能引來了一些渴求法力的生物，像是惡魔獵犬。\n\n我們必須展開調查。祈倫托的法師也許身陷險境。惡魔獵犬是可接受的風險。\n\n我們別再浪費時間了。", progress = nil, completion = "很高興看到散落各地的祈倫托法師響應埃薩的號召。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83738] = {title = "織絲者惡名", objective = "在織絲者巢穴與波賓談話。", description = "織絲之母向你表達莫大的感謝。\n\n回到巢穴來。我有很棒的東西要給你。\n\n我已經用蛛網把它們保護起來了，所以不用擔心！", progress = nil, completion = "繼續做好事！\n\n織絲者還請我們把她的「讚美」給你，但我在這裡沒有找到「讚美」。\n\n也許我把它們吃掉了？抱歉啦！", rewards = "您會收到：\n\n織絲者的珍寶斷裂絲線"}
MultiLanguageQuestData['tw'][83739] = {title = "將軍惡名", objective = "在織絲者巢穴與志士基普卡談話。", description = "你的事蹟已經傳到將軍的許多侍僧那裡了！\n\n來織絲者巢穴找我。我們幫你準備了一份禮物！", progress = nil, completion = "來！收下這些禮物，作為對你實力的敬意！\n\n將生命獻給死亡！", rewards = "您會收到：\n\n將軍的珍寶斷裂絲線"}
MultiLanguageQuestData['tw'][83740] = {title = "輔臣惡名", objective = "在織絲者巢穴與圖魯蒙談話。", description = "輔臣請我為你的努力提供額外的資源。\n\n來織絲者巢穴。我會帶著一個包裹在那裡等你。", progress = nil, completion = "輔臣的讚賞對你來說應該就是非常足夠的禮物了…\n\n要不是因為他為人慷慨，這些東西可能就會浪費掉了。帶著感激之心收下它們吧。\n\n還有，盡量試著活下去，異族人。", rewards = "您會收到：\n\n輔臣的珍寶斷裂絲線"}
MultiLanguageQuestData['tw'][83743] = {title = "秘法冷戰", objective = "前往阿茲-卡罕特與珍娜‧普勞德摩爾女士碰面。", description = "有些法師來了，但…我以為會有更多人響應埃薩的號召。\n\n不過也許那只是我的一廂情願。\n\n即使有你和卡雷苟斯在悼念高地的行動，但我們還需要更多幫助。除了科爾蘇加德的墜飾外，狗頭人的劫掠物中也有不少力量中等的神器。\n\n在此同時，也有報告指出，強大的魔法物品流落到阿茲-卡罕特，意味著奈幽蟲族一定早就搜刮過達拉然的廢墟！\n\n我們必須找回這些神器，不能讓它們被用來對付我們。", progress = nil, completion = "我們可能來得太遲了，&lt;name&gt;。對我們所有人都是。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83749] = {title = "探究：水力發電壩", objective = "在任一難度下完成水力發電壩探究。", description = "還真是趟驚險的旅程！你敢相信這邊深淵的深處有多少東西嗎？\n\n這些機語者告訴我，他們在這個叫水力發電壩的地方遇上麻煩。聽起來狗頭人又在亂搞了。他們還在那個地方的深處貯藏了一些寶藏。\n\n怎麼樣？我們一起去冒險，順便幫這些人一個忙吧！", progress = nil, completion = "速戰速決。根本輕輕鬆鬆！\n\n但我們面前這個陷阱寶箱可就不好說了。", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83752] = {title = "澤克維爾的威脅", objective = "與布萊恩‧銅鬚交談來調查奇怪的箱子。", description = "有人在監視著我們，<name>。他們把這個箱子放在這裡讓我們找到。\n\n準備好了就告訴我。我會觸發這邊的陷阱，來看看究竟是怎麼回事。", progress = nil, completion = "我可不是那種遇到一點點威脅就會退縮的人。看來我還有更多東西可以調查。\n\n相信我很快就能再次見到你！", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83753] = {title = "火砲反擊", objective = "中斷污鼠會的攻擊，並消滅火炮大師金裘。", description = "情況變得不妙了，<name>！那些海盜暴徒有一門大砲，而且正威脅著要把我們轟上天！\n\n但這也可能是一個機會。\n\n如果你解決掉那些發射大砲的猴子，我們應該能自己控制那門大砲來還以顏色！", progress = "你最好告訴我，那些海盜都死光了！", completion = "讓我來都沒辦法做得更好了。你應該來一罐卡迦可樂慶祝一下。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][83755] = {title = "探究：夜暮聖所", objective = "在夜暮聖所尋找澤克維爾的蹤跡，並完成任一難度的探究。", description = "能再見到你真是太好了！自我們上次相聚之後，我遇到了一些麻煩。\n\n有個名叫「澤克維爾」的奈幽蟲族要遠征隊停止探索這片土地。你知道這意味著什麼。我們要探索更多！\n\n這些黑夜教團的教徒或許有澤克維爾的情報。我們去夜暮聖所一趟，看看能找到什麼吧。", progress = nil, completion = "嗯…所以澤克維爾這傢伙在我們探索時潛伏在黑暗的角落。他搞不好還有能力能強化其他傢伙！\n\n我們得更加深入，查出真相。跑腿的工作就交給我吧！", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83758] = {title = "探究者之喚：菌菇愚行", objective = "在任一難度下完成菌菇愚行探究。", description = "情報顯示，蘑菇人又回到我們之前稱為「菌菇愚行」的地方了。\n\n在洞穴中探索，並掃蕩一切威脅。", progress = nil, completion = "謝謝你解決了蘑菇人。或許有一天，他們不再會是我們系統中的故障因子。", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83759] = {title = "探究者之喚：克里格瓦之眠", objective = "在任一難度下完成克里格瓦之眠探究。", description = "急需協助\n\n克里格瓦之眠已經被狗頭人奪下了！這個神聖的土靈永眠之地必須恢復平靜才行。", progress = nil, completion = "克里格瓦之眠對我們的人民來說是個神聖之地。謝謝你幫我們讓那個地方恢復平靜。", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83761] = {title = "探究：深淵堡", objective = "在深淵堡找出澤克維爾的情報，並完成任一難度的探究。", description = "有誰能想到我會能舒舒服服地待在奈幽蟲族的巢穴呢？\n\n曾經有個名叫澤克維爾的討厭鬼威脅了想探索這座島嶼的人們。我已經向織絲者詢問情報。\n\n聽說，這個名叫深淵堡的地方或許有他的相關紀錄。我們來去看看能找到什麼吧！", progress = nil, completion = "澤克維爾是薩拉塔斯的打手！而且他還試著摧毀找到的任何艾澤拉斯記憶！\n\n這讓我們的探索工作更加重要了，&lt;name&gt;。我們不會放棄，就算有薩拉塔斯的走狗緊逼在後也不放棄！", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83762] = {title = "臨界質量", objective = "在氣坑協助珍娜‧普勞德摩爾女士解除法力炸彈。", description = "跟我害怕的一模一樣。\n\n塔倫‧織歌者用來毀滅塞拉摩的法力炸彈，跟它有關的筆記就放在達拉然中進行看管。知道這件事的人少之又少。\n\n我曾強烈要求銷毀筆記。但其他人持不同看法，認為要是這種炸彈再次被製造出來，我們需要筆記才能解除炸彈。\n\n現在，那些筆記既是問題所在，也是解決方案。\n\n幸好，我曾看過那些筆記，<name>。我會帶你逐步解除法力炸彈。", progress = nil, completion = "你總是不會辜負我的信任。做得好。", rewards = "您會收到：\n\n勇氣石雕刻先驅者紋章陳舊幽坑城紋章陳舊以太紋章"}
MultiLanguageQuestData['tw'][83763] = {title = "保護傳承", objective = "從氣坑收集貴重物品。", description = "較大的威脅已經受到控制，<name>，但我認為在阿茲-卡罕特這裡，還有其他對我們的傳承十分重要的神器，無論是好是壞。\n\n儘管它們還是很危險，但它們的知識終將讓我們受益無窮。而我們絕不能讓奈幽蟲族從他們和薩拉塔斯毀滅達拉然的行動中獲益。\n\n務必徹底探索氣坑，任何角落都別放過，<name>。", progress = "我們必須盡我們所能奪回祈倫托的傳承。", completion = "你找到了什麼？\n\n塔倫‧織歌者的筆記。\n\n其他物品都會得到妥善保管，但這些筆記…\n\n我會親自銷毀它們。\n\n謝謝你，&lt;name&gt;。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83764] = {title = "太過強大，太過危險", objective = "尋找散落在氣坑的危險神器，並摧毀它們。", description = "現在奈幽蟲族持有的一些文物，先前都是保管在達拉然精心設計的庫房中。由此可知它們的危險和強大程度。\n\n如今那些庫房已經都不在了，我們僅剩的選擇就是摧毀它們。\n\n現在想來，將這麼多強大的神器集中存放在一個地方，似乎是致命的錯誤，即使那個地方是達拉然也不例外。\n\n我只放心將這個任務交給你，<name>。找到並摧毀那些神器。", progress = nil, completion = "謝謝你，&lt;name&gt;。\n\n未來，祈倫托必須找到更好的方法來研究和保管魔法神器。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][83766] = {title = "探究者之喚：恐怖地穴", objective = "在任一難度下完成恐怖地穴探究。", description = "有兩樣東西會毀了這個行業。激烈競爭，還有恐怖地穴的洞窟。我們需要有人解決後者！\n\n這裡發生了可怕的事。有許多工人在洞窟裡失蹤了。\n\n我們需要你剷除威脅，這樣才能讓事業更加蓬勃！", progress = nil, completion = "你解決恐怖地穴裡的蜘蛛了嗎？太好了！\n\n我會為那個地方想個更好的名字。「恐怖地穴」好像不太響亮。", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83767] = {title = "探究者之喚：陷坑", objective = "在任一難度下完成陷坑探究。", description = "我們接獲報告，表示有大量的寇拜斯聚集在一個名叫陷坑的地方。有人怕他們一有機會，就會攻打岸邊的小型村落。\n\n如果有誰能進到陷坑並阻止他們的計畫，就能獲得豐厚的報酬！", progress = nil, completion = "感謝你的協助。當前的情況，要幫助聖落之地的所有人還真的有些困難。\n\n希望寇拜斯在發動攻擊前能三思而後行了。", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83768] = {title = "探究者之喚：奔蛛裂層", objective = "在任一難度下完成奔蛛裂層探究。", description = "召集能使劍或施法的勇者！\n\n奈幽蟲族在美麗的神禦之牆陰影下進行一個邪惡的儀式。據傳，有一座供奉他們邪神的神廟就在地底之下。\n\n必須有人去調查那個邪惡的地方，並終止他們的陰謀。", progress = nil, completion = "你活著從奔蛛裂層回來了？就我所知，許多燈火者不得不從那可怕的地方撤退。\n\n你讓這片大地更加安全了。謝謝你。", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83769] = {title = "探究者之喚：真菌法師洞窟", objective = "在任一難度下完成真菌法師洞窟探究。", description = "香料大危機！\n\n真菌法師洞窟的蘑菇人一直在搶奪要送往羅萊十字路的香料箱。必須要有人深入洞窟，並剷除蘑菇人的威脅！\n\n你將獲得豐厚的報酬。", progress = nil, completion = "我聽說有人讓蘑菇人的數量大幅減少了。謝謝你！", rewards = "您會收到：\n\n夥伴經驗值夥伴經驗值夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][83770] = {title = "探究者之喚：迴繞地道", objective = "在任一難度下完成迴繞地道探究。", description = "我們許多生還者都聽過迴繞地道的傳說。那個地方似乎是奈幽蟲族的軍事重地。\n\n如果攻擊那裡，或許就能破壞奈幽蟲族的戰爭計畫。", progress = nil, completion = "你辦到了！這應該能讓地表上的部隊鬆一口氣。", rewards = "您會收到：\n\n卡吉"}
MultiLanguageQuestData['tw'][83771] = {title = "探究者之喚：塔克-瑞桑深淵", objective = "在任一難度下完成塔克-瑞桑深淵探究。", description = "織絲者的指示\n\n塔克-瑞桑深淵仍舊是個充滿紛擾的麻煩之地。\n\n必須有人剷除威脅，這樣我們的計畫才能順利進行。", progress = nil, completion = "做得好。如果還需要消滅更多寇拜斯的話，我一定會跟你說的。", rewards = "您會收到：\n\n卡吉"}
MultiLanguageQuestData['tw'][83773] = {title = "再見了，魔法城", objective = "在平靜淺灘將達拉然倖存者帶來的紀念物放在船上。", description = "祈倫托的問題很多，有些並非一天就能解決。\n\n但我們能做的一件事就是致敬那些死去的人。在跟這裡的每個人談過後，我們東拼西湊出一個儀式，準備送走失去的人…還有達拉然。\n\n如果你能加入我們，一起緬懷去世的那些祈倫托成員，我們將會倍感榮幸。", progress = nil, completion = "我會待在這裡，與你們所有人同在，盡我所能提供幫助。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83775] = {title = "無限成長II", objective = "你的成長令人嘆為觀止，但你可能還是需要我的服務。伊特努斯已經批准預算，將撥出一筆青銅幣來贈予經驗老道的時光奔走者。如果你需要的話，我能幫你強化裝備。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n青銅幣"}
MultiLanguageQuestData['tw'][83776] = {title = "無限成長III", objective = "上次和你交談感覺像是不久前的事。我還有青銅幣要給你，你想用來做什麼都可以。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n青銅幣"}
MultiLanguageQuestData['tw'][83777] = {title = "無限成長IV", objective = "時光奔走者！你的成就令人驚豔。你在這條時間線的旅程將會就此結束，或者這只是另一個開始呢？無論如何，我能進一步強化你的裝備，或者你也能用你的青銅幣和其他恆龍弟兄進行交易。決定權在你。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n青銅幣"}
MultiLanguageQuestData['tw'][83793] = {title = "協助錦魚人", objective = "我的人民隨波逐流，坐立難安。請援助我們的村落，讓我們能順流而下，應天而行。", description = nil, progress = "我的人民隨波逐流，坐立難安。請援助我們的村落，讓我們能順流而下，應天而行。", completion = "我們對你的協助十分感激。", rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][83794] = {title = "濕透的節慶木箱", objective = "將濕透的節慶木箱還給阿利克斯。", description = "<箱子濕透了，還散發一股魚腥味，但包裝還是相當嚴密。歸還這個補給品一定能讓阿利克斯相當感激。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83795] = {title = "協助猴人", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n恆龍寶箱非同步稜彩寶石"}
MultiLanguageQuestData['tw'][83825] = {title = "修補偉大的故事", objective = "將荊棘谷的青山還給時光之穴外的蕾妮‧嘶沼。", description = "太可怕了！我的書被撕碎了，書頁飛得到處都是！\n\n我看到沙魔抓了其中幾頁，走進那個通道，還有幾頁被冒險者拿走，他們正準備迎戰塔納利斯的大怪物，剩下的則散落在這附近。也許你那個鳥塑像可以找回書頁？\n\n拜託幫我回收那些書頁，讓我把書恢復原狀！\n\n喔，記得小心那個陰險的克拉維茲‧羅倫特。他在時尚狂亂的舞臺下面賣新書，一本一百金。簡直是在搶劫！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83827] = {title = "停止歌聲", objective = "解救7個被魅惑的士兵，並殺死『海洋女妖』瑪卡貝。", description = "那些海妖…他們在那裡！我在想…庫爾提拉斯人為這座小島命名的靈感是來自水晶，或是這些生物？\n\n不管是哪個，這些海妖的歌聲引誘了很多士兵踏上死路。\n\n我們的哥布林盟友準備了一部裝置，能夠消除他們對我們部隊的心控。\n\n消滅這些「海妖」，驅散俘虜我們部隊的魅惑效果。", progress = nil, completion = "做得很好，&lt;name&gt;。不該有任何靈魂再次臣服於如此可怕的生物。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][83832] = {title = "撕裂的夢想", objective = "到時光之穴外找蕾妮‧嘶沼。", description = "你好，冒險者！我這次又需要你幫忙了。\n\n有個名叫蕾妮‧嘶沼的訪客，昨晚肆虐這裡的沙魔毀了她的一本書。我還在處理那些沙魔造成的其他問題，只能拜託你去幫幫蕾妮。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][83930] = {title = "驅蟲方案", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][83931] = {title = "破損的慶典木箱", objective = "將破損的節慶木箱還給阿利克斯。", description = "<這個木箱嚴重破損。角落似乎至少被一隻狼啃過。歸還這個補給品一定能讓阿利克斯相當感激。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][83932] = {title = "歷史文件", objective = "將在島上發現的12份筆記和文件加入研究日誌。", description = "想像一下，居然有機會陪著領空隊長伊雷娜‧蘭斯卡特展開這麼偉大的冒險。這可是千載難逢的好機會！\n\n不過，如果我想為這趟旅程寫一本書，就需要收集一些有關這座島的史料。\n\n也許你能把你找到的筆記或文件收集起來？任何東西可能都有助於我們了解這個地方的歷史！", progress = nil, completion = "你收集了很多珍貴的史料。這裡有好多秘密等著我們發掘！\n\n我已經等不及想動筆了。\n\n但我需要先想出完美的書名。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][83933] = {title = "卡迦灣", objective = "在猛擊中央站與加茲魯維和雷吉克會合，然後使用岸邊鑽鑿前往卡迦灣。", description = "好了，我們拿到卡迦灣的穿孔卡片了，而且還有充足的理由相信風險投資公司跟加里維克斯的關係比我們想的還要密切。\n\n諾格弗格說我們能在那些礦場找到答案，那也代表必須去卡迦灣調查一下。\n\n走吧。我們會在猛擊中央站和你會合。", progress = nil, completion = "暗融正在監視這個地方。\n\n他們在這裡隱藏著什麼。某種龐大的東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84001] = {title = "全權委託", objective = "修復2段礦坑軌道，清理5台翻覆的礦車，並收集12份礦石樣本。", description = "我們的採礦團隊取得了很大的進展。所有的礦車都已經裝滿了礦石樣本，並送回了營地。\n\n不過現在有個問題…\n\n因為軌道出了狀況，沒有半台礦車成功抵達營地！\n\n請你去修理軌道，並盡可能收集任何遺失的礦石，好讓我們把那些樣本送回營地。", progress = "礦車現在順利運行了嗎？", completion = "幹得漂亮，&lt;name&gt;。我就知道你一定能想到辦法解決這個問題。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][84020] = {title = "需要修復的機甲", objective = "將故障的機甲帶去給剛達加茲的代言者朱拉克斯。", description = "這套機甲也曾風光一時。或許技術高超的機語者能幫你的忙。\n\n我知道代言者朱拉克斯最近派了機械工來維護機甲。他或許能給你一些建議。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][84021] = {title = "沒有輪齒的機器", objective = "將超頻齒輪環發射器交給代言者朱拉克斯，換取零件。", description = "診斷：機器的移動機能已損壞。\n\n我們必須盡快讓它動起來。我需要一些替換零件。齒輪必須保持轉動。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][84022] = {title = "聯合斷裂絲線", objective = "加入織絲者、將軍與輔臣的行列，建立斷裂絲線。", description = "你做得很好，現在阿努巴札爾和尼茲瑞克都是我們的盟友了。\n\n是時候進一步鞏固我們這三方之間的關係了。我們會利用投影儀展開三方會談。準備好開始的時候，就啟動投影儀。", progress = nil, completion = "我以為會經歷很長的口水戰，結果大家的合作意願都很高，這也意味著大家的處境都不怎麼好。\n\n我們眼前還有很長的路要走。坦白說，你的協助無可取代。這或許最終將會成為我人民的救命繩。\n\n謝謝你。", rewards = "您會收到：\n\n織絲者(惡名值)將軍(惡名值)輔臣(惡名值)卡吉"}
MultiLanguageQuestData['tw'][84023] = {title = "自訂方向", objective = "將合成造酒器交給代言者朱拉克斯，換取零件。", description = "這台機器漫無目的地移動。\n\n我們來引導它走向正途吧。\n\n將指令傳達給這個裝置。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][84024] = {title = "抓取控制", objective = "將蠟燭大王的雕刻刀交給代言者朱拉克斯，換取零件。", description = "這台機器雖然在呼吸，卻毫無生命。\n\n我們必須給它生命。\n\n尋找能賦予靈性的導體。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][84025] = {title = "煥然一新", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n石庫機甲"}
MultiLanguageQuestData['tw'][84084] = {title = "只要一小撮", objective = "收集20份風暴之塵，然後交給多恩諾加的納加德。", description = "魔塵是附魔技藝的基礎。那些新手附魔師對這種平凡的材料嗤之以鼻，但大師卻很清楚它的千變萬化。\n\n將風暴之塵帶來給我。不管我們有多麼專業，我們都必須回歸基本功。", progress = "你收集到風暴之塵了嗎？", completion = "令人欣慰。很高興看到重視基本功的附魔師同行。", rewards = "您會收到：\n\n阿爾加附魔師對開本"}
MultiLanguageQuestData['tw'][84085] = {title = "潛在的力量", objective = "收集10塊閃爍裂片，然後交給多恩諾加的納加德。", description = "身為附魔師，我們不能只會販賣符文或魔杖。潛能才是我們真正該賣的東西。我們掌握著有潛力的力量，將其注入有形之物中。\n\n為此，閃爍裂片不可或缺。我需要很多個，才能繼續進行作業。", progress = "魔塵提供多樣性，裂片則賦予可能性。", completion = "值得喝采。這些能用來實現很多有用的附魔。", rewards = "您會收到：\n\n阿爾加附魔師對開本"}
MultiLanguageQuestData['tw'][84086] = {title = "稀有的必需品", objective = "收集1個輝煌水晶，然後交給多恩諾加的納加德。", description = "有時候，我們會需要提供最出色、最強大的增益效果。在這種時候，就需要使用輝煌水晶。\n\n的確，這種水晶相當稀有，但是，想要抵達技藝的巔峰，它必不可少。別擔心，它絕不會被白白浪費。", progress = "只要到手，我一定會善加利用。", completion = "真美，對吧？相信你能夠感應到它所能釋放的潛能。", rewards = "您會收到：\n\n阿爾加附魔師對開本"}
