MultiLanguageQuestData['tw'][84334] = {title = "警告偵探", objective = "警告偵探瓊斯有關變形者的事。", description = "歡迎回來，<name>。\n\n我看到那個偵探朝西邊去了。快去警告他，別讓那個變形者逮到他！", progress = nil, completion = "變形者？哈！胡扯！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84336] = {title = "找出差異", objective = "解決變身惡魔的案件。", description = "聽好了，我是真正的偵探。你相信我，對吧？\n\n我知道…問我任何事。這裡的好人能夠證實我的說法，我們就能證明我沒被調包。", progress = nil, completion = "非常感謝你解決這個案件，&lt;name&gt;！\n\n希望這個活動接下來能平安落幕。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84352] = {title = "不用再走路了", objective = "到凱蒂小屋的三樓找塔魯菈奶奶。", description = "我們得做些什麼，提高你的移動效率。幸好，我有適合的人選。去凱蒂小屋見塔魯菈奶奶，看看她能不能借你車子。", progress = nil, completion = "你需要一輛車？我們當然可以幫你弄一輛車來！我們有好多車！來，我這裡甚至就有一些備用鑰匙！", rewards = "這個任務線能解鎖：\n\n斷頸者G-99\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][84363] = {title = "尋包行動", objective = "使用派瑞斯火炬在塔納利斯的廢墟尋找寶藏。", description = "我知道了！我們可以用那根棒子去找寶藏！\n\n你和安佐去調查其他廢墟。找到超級酷的東西！\n\n我會在派對跟你們會合。", progress = nil, completion = "哇，這才是真正的寶藏！", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84365] = {title = "逐步逼近", objective = "在多恩諾加與布萊恩‧銅鬚交談。", description = "布萊恩的斥候回報，他們發現有援軍正向卡茲阿爾加的海岸逼近。\n\n他正在多恩諾加號召冒險者加入他的行列。", progress = nil, completion = "我聽說有援軍正往群島趕來。你對卡茲阿爾加很熟…他們需要你的獨到見解。", rewards = "這個任務線能解鎖：\n\n升級戰役略過\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][84367] = {title = "集結時刻", objective = "回去多恩諾加找茉艾拉‧索瑞森。", description = "我們很快就會有更多援軍了。就在此時，我聽說艾蘭里亞跟安杜因回到多恩諾加了。\n\n如果我對茉艾拉的認識沒錯的話，她早就在跟他們規劃下一步行動了。就跟獅鷲獸能輕鬆在天空翱翔一樣，領導對她來說也是再熟悉不過了。最好在她找你以前，先去跟她碰頭吧。", progress = nil, completion = "還真是剛好。自我們在這裡墜毀以來，這是第一次得到好消息。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84370] = {title = "成功關鍵", objective = "把蜘蛛密碼鑰匙交給多恩諾加的伊莉絲‧尋星者。", description = "<密碼鑰匙？伊莉絲‧尋星者或許知道這個東西的來歷。>", progress = "這張地圖根本就是錯的…勇士！我想你有好消息吧？", completion = "太奇妙了！這就是我百思不得其解的地方。\n\n芬利找到的地圖是個密碼。但這個鑰匙並不完整…如果你在外頭找到更多的話，請把它們帶來給我。我會解開這張地圖的，不然我就不配稱為伊莉絲‧尋星者了。", rewards = "您會收到：\n\n地底幣地底幣共鳴水晶共鳴水晶"}
MultiLanguageQuestData['tw'][84371] = {title = "故事漫遊：匕首與大祭司", objective = "跟隨阿洲的引導，瞭解薩拉塔斯過往的故事。", description = "『虛無先驅者』薩拉塔斯是個狡詐又危險的對手。她的存在只有極少數人才知曉。\n\n我們第一次聽到她時是在燃燒軍團第三次入侵艾澤拉斯的期間，但謠傳稱她早在這次事件之前就已經存在了。\n\n這是一個關於力量、黑暗與欺騙的故事。跟著我，我會告訴你薩拉塔斯神秘過往的故事。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石陳舊幽坑城紋章陳舊以太紋章"}
MultiLanguageQuestData['tw'][84376] = {title = "財產貶值", objective = "造訪桶底公寓並詢問租房事宜。", description = "<你偶然發現了一張被釘在租用告示牌上的徵人海報。>\n\n徵人啟示：徵求身體健全的冒險者，擔任當地公寓大樓的保全。\n\n必須具備不會輕易死亡的能力。\n\n獎勵：提供免費食宿以換取服務。\n\n有意者請前往附近的桶底公寓樓上，以深入了解詳情。", progress = "那個莫茲快把我逼瘋了！也許你能幫我勸勸他。", completion = "我沒想到真的有人會出現。你是來問免費住房的事嗎？\n\n你沒對桶底透露任何事，對吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84378] = {title = "租客保險", objective = "殺死12名幽坑騎士摩托幫成員。", description = "那個吝嗇的老房東讓這個地方慢慢地分崩離析已經夠糟了，但現在我們又有了更大的麻煩。\n\n最近，那些在街上橫行霸道的潛在幫派分子，幽坑騎士，從輕微盜竊和噪音投訴變成了全副武裝的威脅。他們開始破壞這個地方，甚至直接攻擊我們！\n\n最糟糕的是，沒有錢能搬出去的人卻要為那些混混造成的傷害而被趕出去。\n\n你保護我們的安全，你就可以免費住在這裡。", progress = nil, completion = "你回來了。\n\n&lt;姬雅拉因為傷口而露出猙獰的表情。&gt;\n\n你的時機可以再更好一點。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84379] = {title = "租客問題", objective = "拯救8名被捕的租客。", description = "<嘉比急切地向你揮手。\n\n這個小哥布林緊張地將雙手擰在一起，試著找出能解釋她的擔憂的詞語。>\n\n有些哥布林不是搬出去的…他們是被綁架的。我知道。\n\n我的朋友不會搬走。絕對不會。\n\n<嘉比淚眼矇矓的雙眼祈求地朝上看著你。>\n\n拜託幫幫忙，<class>。拜託嘛？", progress = nil, completion = "所有人都獲救，就只為了再被攻擊一次。\n\n我們不能讓這種事繼續下去了，&lt;name&gt;。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84380] = {title = "武器現金", objective = "摧毀整個建築群中的幽坑騎士裝備。", description = "<在武器箱裡，你找到了一張寫給幽坑騎士的弄皺紙條。>\n\n我很高興看到你們能善用你們的新玩具。多虧你們，這些小小的侵占者才會成群離開！\n\n繼續保持下去，我還能提供更多這種武器。但盡量不要把整棟樓燒毀。一塊空地可租不出去，哈哈！\n\n署名，\nM.B.B.", progress = "找到什麼了嗎？", completion = "給幽坑騎士的信？我想我知道這個簽名…\n\n是那個懦弱的房東，莫茲‧桶底！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84381] = {title = "重新協商", objective = "擊敗賈維斯‧斷骨者，並在街道對面三樓的辦公室從莫茲‧桶底身上拿走桶底房契。", description = "就這麼定了！我想我們都知道這場混亂是誰造成的。就是那個混帳的房東，莫茲‧桶底！\n\n幽坑騎士被解決掉之後，他馬上就派了他的暴徒賈維斯來大肆破壞。看來如果他沒辦法把我們嚇跑，他就會強迫我們離開。\n\n<姬雅拉厭惡地朝地上吐了一口口水。>\n\n他想嚇倒我們可沒這麼容易。\n\n你很能打，<name>。莫茲的辦公室就在街道對面。去告訴他，他惹錯哥布林了！", progress = "我們在這裡會沒事的。你快去對付莫茲！", completion = "哈！這樣就能讓那個老吝嗇鬼知道誰才是老大了。而且有了這份房契，他就沒辦法威脅我們了！\n\n你做得很好。我想你得到那間免費房間當之無愧。", rewards = "您會收到：\n\n瘋狂車手腕甲瘋狂車手肩衛瘋狂車手腿甲瘋狂車手長靴勇氣石"}
MultiLanguageQuestData['tw'][84392] = {title = "谷地之饑", objective = "到低吼窪地找多蕾娜。", description = "嘿。想吃頓大餐嗎？\n\n就算是跋山涉水才能享用美食也願意嗎？\n\n那就去找多蕾娜吧，她會幫你的。別試著說服她離開那座谷地。相信我…我們都試過了。究竟是誰會遠離光明的庇佑而住在那種地方…\n\n但她也過得很好就是了。", progress = nil, completion = "啊，又來一個了。你有什麼事嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84393] = {title = "現形棒", objective = "跟隨瑪魯，然後對奧丹姆廢墟外的火盆使用派瑞斯火炬。", description = "很好，該來試試那根現形棒了！\n\n跟我來。", progress = "所有工具都會用才是好偵探。", completion = "太酷了！", rewards = "您會收到：\n\n派瑞斯火炬"}
