MultiLanguageQuestData['tw'][84409] = {title = "為了英勇而戰", objective = "阿拉希人真的很感激你在這個險地伸出援手。我們的感激之情難以言喻，請收下這個。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84419] = {title = "朝廢墟出發！", objective = "到奧丹姆廢墟外與瑪魯和安佐會合。", description = "你找到我弟弟的偵探工具了！\n\n<瑪魯尊敬地舉起它。>\n\n現形棒！這個東西能夠點燈，熔化東西，還可以解鎖古代寶藏。你要做的事情就是把它舉起來！\n\n我們打算在奧丹姆廢墟外面試用它。要一起來嗎？", progress = nil, completion = "準備好冒險了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84423] = {title = "抖落灰塵", objective = "在聖落之地從飢餓渦池取回艾莉莎備受寵愛的泰迪熊。", description = "哇，你看起來真強！你能夠幫幫我嗎？\n\n我的父母都被殘忍的寇拜斯殺死了。我來這裡的時候，沒機會把我最喜歡、最寶貝的泰迪熊帶來。\n\n你可以幫我拿來嗎？", progress = nil, completion = "歡迎回來活人的世界，&lt;class&gt;。\n\n你有很多情報需要複習。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84424] = {title = "上吧，去冒險！", objective = "使用戰爭育所的傳送門前往克羅米的所在位置。", description = "我們很有空，<class>。有空到想做什麼就做什麼。\n\n經由下方的傳送門，就能通往你的餘生。\n\n青銅龍軍團的一個成員會幫助你踏上旅程。", progress = nil, completion = "該來幫你複習一下了，&lt;name&gt;！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84426] = {title = "浸水的節慶木箱", objective = "將浸水的節慶木箱還給阿利克斯。", description = "<這個木箱被浸濕了，但裡面的東西還能回收。歸還這個補給品一定能讓阿利克斯相當感激。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84429] = {title = "傀儡隔離", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][84430] = {title = "水晶聖戰", objective = "從納迦部隊手中取回10枚水晶碎片和30個水晶碎塊。", description = "我曾誓死保護巴雷達爾…現在新的星辰從大海向我們歌唱。\n\n我不知道這對阿拉希有什麼意義，我只知道，一旦讓這些邪惡的深海生物得逞，很可能會招來禍事。\n\n毫不留情地殺死他們，取回他們手中的所有水晶碎片。", progress = "你拿回水晶碎片了嗎？", completion = "願巴雷達爾的子民永遠昌盛。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][84432] = {title = "長艇靠岸", objective = "消滅15個血喚維酷人。", description = "這些血喚維酷人根本不尊重我們或我們的研究。就算我們試著和他們分享我們的發現，我們還是被攻擊了！\n\n他們根本不在乎我們無意傷害這座島…他們只想我們離開。\n\n但現在我們還不能走。還有好多事物等著我們探索！必須有人去告訴他們，我們還沒打算離開，他們最好不要來打擾我們。\n\n我們必須讓他們知道，我們也是會反擊的。", progress = nil, completion = "我並非喜歡用暴力解決問題的人，不過武力有時候是唯一的選項。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][84435] = {title = "諾菈最後的心願", objective = "解開拉斯克之謎。", description = "你好，<name>！你能去看看拉斯克的狀況嗎？\n\n他好像有什麼心事。", progress = "諾菈能夠訴說的故事…", completion = "聽到她終於能夠安息了，真讓人欣慰。\n\n我會一直訴說這個故事好幾年，&lt;name&gt;。謝謝你。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84438] = {title = "簡單獲勝", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n秘典：變苔毛羊術"}
MultiLanguageQuestData['tw'][84439] = {title = "卡迦結論", objective = "將爵士的報告送去給內陸飯店的寇瑞‧霍克斯。", description = "你在這裡真的幫了我很多，<name>，但我還需要你再幫我一個小小的忙。\n\n<爵士遞給你一個塞滿了結構圖和書面報告的信封。>\n\n你可以把這個拿去給我的合約代理人寇瑞‧霍克斯嗎？他會把信封送回總部。你大概能在內陸飯店看到他正在張貼更多零工表單。", progress = "你看不出來我有點忙嗎？招募可是一份很辛苦的工作！", completion = "喔，爵士有新報告了？你怎麼不早說呢？\n\n&lt;寇瑞搶走信封，將其撕開並查看報告。&gt;\n\n他需要多少人手？！", rewards = "您會收到：\n\n共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][84446] = {title = "卡茲阿爾加的名望", objective = "在多恩諾加與法林‧洛薩談話。", description = "為了幫助卡茲阿爾加，我們還有很多事要做。\n\n但我對這片土地了解不多，只知道這裡是土靈的國度。\n\n我得將你們引介給法林‧洛薩，看看聖落之地需要什麼幫助。\n\n跟她交談，看看她是否需要幫助。你們已經認識彼此了，對吧？", progress = nil, completion = "&lt;name&gt;，很高興再次見到你。\n\n我們有一大堆事要做。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84469] = {title = "戰寵賓果", objective = "根據謎題找到戰寵。", description = "嗨嗨！來自潘達利亞的大師級馴獸師提出了一個挑戰，要求找到這張酷炫的賓果卡片上的戰寵。\n\n我們要做的就是解開謎題，找到正確的戰寵，然後記錄在我們的賓果卡片上，但我怎麼樣都找不到最後兩隻。普通的戰寵很容易就能找到，但這些賓果卡片要求我們找到特殊版的生物。\n\n嗯…他們的規則中沒有說不能找外援。你願意幫朋友這個忙嗎？", progress = nil, completion = "嘿，多謝了，朋友！\n\n賓果！", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84470] = {title = "沾滿泥土的節慶木箱", objective = "將沾滿泥土的節慶木箱還給阿利克斯。", description = "<儘管已經挖了出來並清除塵土，這個木箱卻還是有股死亡的氣味。不過，歸還這個補給品應該能讓阿利克斯相當感激。>", progress = "嗯？", completion = "喔，你找到遺失的木箱了！太好了！\n\n真的很感謝你。如果你找到其他木箱，請送回來給我。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84489] = {title = "快樂購物！", objective = "與店員談話。", description = "在了解主要景點之後，來談談購物吧。\n\n你可以在主要展館發現一些很棒的全新商品。繞一繞、看一看之後，再和店員談談，了解他們有哪些好東西。\n\n逛完了就回來找我，讓我知道你對哪些東西有興趣吧。\n\n等會見囉！", progress = nil, completion = "希望你看到了自己心儀的東西，或是享受逛街的樂趣。\n\n既然你對這裡並不陌生，我就讓你好好享受慶典吧，畢竟這次的週年慶典也是為你舉辦的。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84490] = {title = "寶庫", objective = "從寶庫取得一件戰利品。", description = "多恩諾加的許多系統已沉睡多年，如今又再次開始運轉了。<race>，其中一個可能派得上用場，那就是寶庫。\n\n過去，這些塵封的盔甲與武器曾是土靈履行誓語者的職責，保衛多恩諾加時不可或缺的裝備。現在，我們將向你開放寶庫，希望你能善用其中找到的東西，幫助他人，完成自己的任務。\n\n寶庫位於多恩諾加議會的寶庫內。議會守衛已給予你自由取用其中物品的權限。", progress = "<name>，寶庫任你自由使用。", completion = "看來已經在寶庫裡找到好用的裝備了，對吧？\n\n很好。裡面還存放著很多物品。定期來查看吧。你永遠料不到自己還會發現什麼好東西。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84506] = {title = "追尋戰寵", objective = "到戰寵遊樂場附近找杰佩托‧樂吱。", description = "你好，冒險者！\n\n我發現一群戰寵馴獸師正在舉辦賓果遊戲。杰佩托‧樂吱是他們其中的一員，但他的進展緩慢，似乎讓他有點沮喪。\n\n不如你去看看能幫上什麼忙吧？", progress = nil, completion = "喔，你願意幫我追蹤一些稀有的小動物？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84519] = {title = "遠古奇趣：戰鬥", objective = "為布萊恩‧銅鬚使用並裝備不滅的鋼鐵塑像。", description = "<你拿著聖物，發現它正散發著微弱的光芒。這看起來很重要。探險者協會應該會感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84520] = {title = "遠古奇趣：通用", objective = "使用並為布萊恩‧銅鬚裝備流線降阻聖物。", description = "<你拿著聖物，發現它正散發著微弱的光芒。這看起來很重要。探險者協會應該會感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84521] = {title = "燒腦之旅", objective = "護送瑪魯解開貝勒陶的謎題。", description = "瑪魯一直是很出色的小偵探，是時候給她一頂思緒軟帽，當做她的獎勵了！\n\n不過，我不能直接拿給她，所以我把零件埋了起來，她得自己組裝出來。我把每個零件的座標藏在謎題中。解開謎題，找到埋藏的地點！\n\n可以拜託你護送她，確保她不會遇到麻煩嗎？你可以用我的思緒軟帽幫忙。還有，我會給你特殊的線索書，謎題會隨著你的進度顯現在上面。", progress = nil, completion = "你成功了！看看瑪魯臉上露出虎牙的笑容。非常感謝你的幫忙。", rewards = "您會收到：\n\n精心裝飾的思緒軟帽時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84542] = {title = "璀璨回音", objective = "將璀璨回音帶去世界之魂記憶，接著釋放它。", description = "<你的手中拿著一個小型的艾澤萊晶岩球體。其光芒穩定且明亮，但它發出的聲音悲戚而渴望。它輕輕地觸動了你。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84547] = {title = "必定買回", objective = "將空的卡迦可樂交給漂流物淺灘的布林基‧油脂指。\n\n已提供物品：\n", description = "<就算是一個卡迦可樂空罐，它還是有點價值。也許布林基‧油脂指可能會收下它。>", progress = nil, completion = "我不收這些回收物。我只會在裡面裝滿雜牌可樂。\n\n絕對沒有人能喝出區別，我保證！", rewards = "您會收到：\n\n祝焰鐵"}
