MultiLanguageQuestData['tw'][84583] = {title = "背上的猴人", objective = "面對喧鬧的猴人。", description = "你好，<name>。你應該不介意再幫我一個忙吧？有兩個奇怪的傢伙在可愛動物區的外圍製造麻煩。\n\n也許你可以說服猴人別再朝我們的客人吼叫。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84588] = {title = "玩具救援行動", objective = "尋找被偷的玩具。", description = "不！有個鬼鬼祟祟的小偷偷走了我朋友的玩具！\n\n你現在是個優秀的偵探了，對吧？你可以幫我的朋友葉努找回失竊的玩具嗎？你可以在巨龍群島找到他。", progress = nil, completion = "哇，你是玩具救援專家！你覺得是誰偷了玩具？\n\n我們應該分析你找到的線索，看看能不能鎖定兇手！明天再回來，我們可以看看證據。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84595] = {title = "長毛怪怪人的案件", objective = "為瑞可和卡玲找到夥伴寵物。", description = "瑞可已經受夠這些該死的混球了！卡玲想要的就只是一個毛茸茸的小傢伙，但這些猴人完全不同意！\n\n卡玲說瑞可必須停止碎碎念。說拿走他們的毛孩就是「偷」。\n\n你是個幫得上忙的怪怪人嗎？幫卡玲找到毛茸茸的朋友！最好做筆記，怪怪人才不會卡住。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84616] = {title = "慶祝美好時光！", objective = "參加慶典周邊活動，完成造訪時獲得的任務。", description = "歡迎來到青銅龍慶典！\n\n我代表軍團邀請你前來享受各項活動。你可以選擇反映寵物的鏡像，在我們的遊樂場上奔跑。\n\n你可以參與諸如時尚狂亂或坐騎狂熱之類的大型活動。每隔15分鐘就會替換為一個新的活動。\n\n你也可以給自己一個挑戰：找茉艾拉再次造訪黑石深淵，或是與克羅米清理寶典、為旅程做準備。\n\n無論是什麼活動，最重要的是你樂在其中！", progress = nil, completion = "看到這麼多來自艾澤拉斯和其他地方的訪客前來這次的慶典，真是讓人倍感驕傲。這個慶典的目的是為了紀念過去的事蹟，這些事蹟讓我們現在得以一同在慶典中慶祝。\n\n我們衷心希望你享受這次的活動。收下這份青銅龍軍團的禮品，希望它能讓你往後的冒險更加順利！", rewards = "您會學到：\n\n青銅龍軍團的祝福\n\n您還會收到：\n\n青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84619] = {title = "古籍研究社", objective = "從污鼠會的船隻和停泊區獲取各種文書資料。", description = "污鼠會的猴人是大師級的拾荒者。多年來，他們屢次拜訪這座島，奪取任何可能有價值的東西。\n\n他們的戰利品中包含許多研究資料，或許有助於揭開這個地方的歷史。\n\n潛入他們的營地，登上他們的船隻，然後取回你找到的所有書籍、卷軸和文件。", progress = "你找到值得一讀的東西了嗎？", completion = "好多驚人的手稿！我敢說我會整晚熬夜把這些看完。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][84621] = {title = "侍從的馬刺", objective = "幫助坎帕拉特。", description = "你前來向坎帕拉特宣誓效忠嗎？想成為棕桌騎士嗎？\n\n看起來不像是新手，不過，就算是最勇猛的騎士也要先從侍從開始做起。獲得馬刺，學習謙遜。\n\n證明你用相同方式學到這些。看看能做些什麼來幫助城堡。\n\n或許也能成為其他侍從的榜樣。", progress = nil, completion = "做得好，侍從&lt;name&gt;。記得保持謙遜。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84624] = {title = "沾滿沙塵的慶典箱", objective = "將沾滿沙塵的慶典箱還給阿利克斯。", description = "<這個箱子必定經歷過很多事情！歸還這個補給品一定能讓阿利克斯相當感激。>", progress = "嗯？", completion = "喔，你找到遺失的箱子！太好了！\n\n我真的很感謝你把它們送回來。如果你找到更多箱子，請交給我。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84625] = {title = "完好如初的慶典箱", objective = "將完好如初的慶典箱還給阿利克斯。", description = "<你在安葬這堆骸骨的無名墓地找到這箱慶典補給品。把補給品歸還給阿利克斯，他一定會相當感激。>", progress = "嗯？", completion = "喔，你找到遺失的箱子！太好了！\n\n我真的很感謝你把它們送回來。如果你找到更多箱子，請交給我。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84627] = {title = "深海三巨頭", objective = "消滅督軍瑟雷西、開採者西利賽和『寂靜浪潮』納魯。", description = "這些生物真是神出鬼沒，令人害怕！\n\n我已經在帝國水域遇見他們無數次。我很清楚他們的策略，也做出解決他們的計畫。\n\n我的斥候已經鎖定了他們的三個首領的位置。消滅他們，我們就能佔上風。", progress = nil, completion = "幹得漂亮，&lt;name&gt;。我的船上很需要像你這麼有才幹的人…歡迎跳槽。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][84638] = {title = "高地的麻煩", objective = "透過多恩諾加的傳送門前往阿拉希高地。", description = "嘉亞拉和達納斯都收到阿拉希高地動亂的消息。激流堡裡發生內亂，瑪格哈和激流堡哨站則受到突襲。\n\n達納斯和嘉亞拉要回到激流堡和落錘鎮的家園，來緩解局勢。\n\n我想跟他們一起去。我一直想讓自己和我的族人與阿拉希重新建立連結。我也想進一步了解部落。\n\n嘉亞拉十分願意，但…達納斯經過說服後才同意。\n\n不過，我稍微暗示了你也會一起去…", progress = nil, completion = "我有聽說強盜在高地打劫的消息，但…我不知道情況是如此嚴重。\n\n幸好我們恰巧碰上這次襲擊。\n\n如果要徹底調查，我們最好從這裡開始。\n\n不過…我由衷希望法林沒看到這一幕。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84639] = {title = "火炬與焦油", objective = "從迪菲亞強盜身上取回10個被偷的火炬，並在紐沃農莊裡取回10桶焦油桶。", description = "我們曾被襲擊過。但這次…\n\n<沃克打了哆嗦。>\n\n這次不太一樣。\n\n他們不要牲畜、穀物或錢財。他們拿走了火炬和拿來修屋頂的焦油桶。\n\n我不知道他們要那些東西做什麼，但…我也猜得出來。他們想燒了某樣東西。\n\n你得在他們襲擊另一座農莊前搶先阻止！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84640] = {title = "麻煩將至", objective = "把不熟悉的紋章交給紐沃農莊農場的達納斯‧托爾貝恩。\n\n已提供物品：\n", description = "<這個迪菲亞強盜戴著一個上頭有陌生紋章的徽章。\n\n這個紋章看起來像是正在升起的太陽，並散發出長長的光束。太陽和光束都是紅色的。\n\n或許達納斯認得出來。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84643] = {title = "宵禁騷亂", objective = "在激流堡解決掉15個瑪蘭支持者。", description = "很高興有你的幫忙。從部署到卡茲阿爾加、面對高地的威脅，到處理逃兵，我們根本就沒有足夠士兵可以維持秩序。\n\n瑪蘭的支持者在整座城市內引起了不少的麻煩。他們會偷走補給品、擾民…你能想到的他們都做得出來。我們已經實施宵禁了，但瑪蘭的支持者卻公然抗命。\n\n身為我的代理人，我想請你叫那些麻煩製造者都給我回家。如果他們找你麻煩，我允許你給他們一點教訓。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84645] = {title = "代理人快遞", objective = "把布魯斯頓的請求令狀交給激流堡的人民。", description = "激流堡的貿易市場已然瓦解。因為這些襲擊，我們的貨物與人手都十分短缺。\n\n尼艾絲太忙了，所以我就接下了撰寫官方協助請求的任務。\n\n大多都很簡單也很直接，都是為了激流堡部隊的補給品和其他東西的令狀。\n\n但喬瑟夫的警告令狀就不一樣了。他公開指責那些非人類種族，把我們困境的起因都推給他們。在他引發暴動之前，必須有人嚴正警告他把嘴閉上。\n\n身為我的代理人，你願意幫我請求協助嗎？您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84649] = {title = "瑪蘭‧托爾貝恩", objective = "在激流堡的兵營裡旁觀法林‧洛薩和瑪蘭‧托爾貝恩的會面。", description = "我是薇若妮卡‧尼艾絲上校，托爾貝恩大人不在時，便由我代為管理激流堡。\n\n我相信你在激流堡協助我們的人民時，很常聽到「瑪蘭」這個名字。她是瑪蘭‧托爾貝恩女士，達納斯的外甥女。達納斯‧托爾貝恩大人在為卡茲阿爾加徵招部隊的時候也暫時由她治理。\n\n大人不在的這段期間，她的行動致使她鋃鐺入獄。\n\n話雖如此，托爾貝恩大人覺得法林該找她談談。或許是想了解…她的想法吧。如果有需要的話，我可以帶你去找她。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84650] = {title = "在避難谷地避難", objective = "在阿拉希高地的避難谷地尋找達納斯。", description = "如果你想找托爾貝恩大人，並把你對瑪蘭女士的懷疑告訴他的話，他被一封信函文件請去遙遠東邊的落錘鎮了。\n\n他在路途中可能會在避難谷地停留，那是往獸人城鎮半路上的激流堡營地。因為強盜很常襲擊那個區域，我想他會在那裡停留，並關心人民的狀況。\n\n或許你可以在那裡追上他。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84651] = {title = "熟悉的面孔", objective = "擊敗對避難谷地發起襲擊的首領。", description = "早期的時候，這些針對我們聚落襲擊的強盜似乎只是為了爭奪資源。\n\n現在他們像是聯手起來，一切行動都是談好似的。\n\n對大家來說，這可不是什麼好消息。\n\n但沒有能幹的首領，這些暴徒是不會團結起來的。沒了這些首領，這些強盜自然就樹倒猢猻散了。\n\n如果你願意的話，把襲擊避難谷地的首領找出來，並殲滅他們。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84652] = {title = "補足補給品", objective = "在避難谷地收集4個補給木箱。", description = "激流堡的部隊駐紮在卡茲阿爾加，因此沒辦法顧及他處的聚落。\n\n落錘鎮盡可能地協助，但我們的人也在卡茲阿爾加奮戰。\n\n我們在落錘鎮收容了許多受傷的激流堡難民，但為了照顧他們，我們的資源也近乎消耗殆盡。\n\n不過或許有方法可以幫助更多人。\n\n維琪告訴我，避難營地是附近聚落的補給站。如果可以拿到更多補給品，我們就能在落錘鎮照顧更多難民了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84658] = {title = "尋找家人", objective = "在紐沃農莊農場查出馬肖‧枯野、雪倫‧枯野和艾莉的下落。", description = "媽媽在哪？爸爸呢？\n\n艾莉呢？\n\n<瑪姬眼眶泛淚地環顧四周。>\n\n我們看到強盜的時候，我還跟在格雷夏姆先生和克拉貝爾的身邊。他把我抱起來後，我們就跑到這裡來了。\n\n我不知道媽媽、爸爸和艾莉在哪裡。\n\n你可以幫我找他們嗎？克拉貝爾也開始擔心了…\n\n<瑪姬抽泣著。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84659] = {title = "尋找法林", objective = "在激流堡的建築物中尋找法林和紅色黎明的情報。", description = "我看到法林被人帶走，但沒辦法在不被他們發現的情況下跟蹤他們。她應該被囚禁在另一棟建築物裡。\n\n去把她找出來。希望她還活著…\n\n然後看看你能不能找到更多關於紅色黎明的情報。我們不該這麼快就被擊垮。尼艾絲上校和托爾貝恩女士肯定在各處都安插了他們的手下。\n\n我們握有越多情報，反擊時就能有越多勝算。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84664] = {title = "促進地底世界經濟", objective = "在織絲者巢穴的其中一個商人那裡花費卡吉。", description = "你好啊，「異族人」。你看起來和這裡非常地格格不入。你是被飛船還是什麼東西輾過嗎？\n\n隨便啦，那不是重點。根據其他外來者的經驗，如果你想在這底下生存，那你就必須了解道上的規矩。黃金在你的世界或許是硬通貨，但在這裡你得用到卡吉，而且是一大堆。\n\n來，拿去。把這當作是上面的觸肢女士向你釋出的善意。去幫你自己買點好東西吧。", progress = nil, completion = "你仔細看過四周了嗎？這個地方真的很詭異，即使是對我這樣的機靈女孩來說也一樣。但只要收集足夠的卡吉，你就可以買到各種東西，不論是在這裡，還是在蛛絲城。\n\n&lt;琳妮上下打量你一番。&gt;\n\n不過，你大概還是會被吃掉，所以或許你該去找找精美的奈幽墓碑。", rewards = nil}
MultiLanguageQuestData['tw'][84667] = {title = "進步的G.O.L.E.M.", objective = "與G.O.L.E.M.一起參觀大桶工廠，並幫加特‧波克茲、『暴躁』南和幽坑城的孩童解決問題。", description = "幽坑城的居民正在高聲呼救！他們需要保護！他們需要喜悅！他們需要過活！\n\n身為發明家，我窮盡一生打造某個能為人民分憂解勞的裝置，而它已經準備好進行測試了。我把它稱為我的哥布林絕佳宜居性改善機器，或簡稱為G.O.L.E.M！\n\n去找出一些問題，然後帶著它出去轉轉…順便也把我兒子一起帶去！比茲的體內還沒有發明家的骨氣，但他肯定能和鄰居侃侃而談。", progress = nil, completion = "好吧，它運作的時候確實很棒！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84672] = {title = "收垃圾日", objective = "收集12份垃圾，並使用G.O.L.E.M.的焚化爐功能將其處理掉。", description = "我的老爸總是在思考這些拯救世界的瘋狂點子…我不懂。這有點超出我的理解範圍，但我猜這就是為什麼我從來都不是他希望我成為的發明家。\n\n不過，我還是對如何解決這裡的問題有一些想法。像是那些把垃圾弄得滿街都是的可惡嚙齒動物！\n\n雖然這可能無法讓社區恢復生機，但我打賭如果我們把街道清理乾淨，大家也會過得快樂一點。", progress = nil, completion = "這個地方已經看起來乾淨多了！也許這個G.O.L.E.M.真的有點能耐。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84673] = {title = "世界最棒的發明家", objective = "協助比茲修復G.O.L.E.M.。", description = "我…不是像我老爸那樣的發明家。說真的，我甚至完全不是當科學家的料。我的大師發明就掛在那邊的牆上，但老實說，它還需要經過很多道工程才能實際辦到…任何事。\n\n但這個！這可能是我向老爸證明我能讓他驕傲的大好機會！\n\n我們要做的事只有，呃，找出修好這東西的辦法。這有什麼難的呢？", progress = nil, completion = "情況不秒。這完全沒有用。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84674] = {title = "G.O.L.E.M.大暴走！", objective = "平息G.O.L.E.M.製造的混亂。", description = "G.O.L.E.M.開始暴走了！失控！癲狂！\n\n我得追上去，誰知道這麼強大的發明會造成什麼後果！再加上，想像一下如果我們把它弄丟，我的老爸會有多生氣！\n\n我很不想請你幫我收拾爛攤子，但總得有人留在後方讓一切恢復秩序。你能幫我嗎？", progress = nil, completion = "亂成一團…G.O.L.E.M.到底做了什麼！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84675] = {title = "閣樓中的對決", objective = "拯救比茲並摧毀G.O.L.E.M。", description = "是我太過盲目！導致一切都分崩離析了！\n\n鄰里的狀況變得比之前更糟糕，而這都要怪G.O.L.E.M！還有我的兒子，我親愛的比茲…\n\n他跑進這棟建築，試圖想讓裝置停下來。我對他太嚴苛了，現在我可能再也見不到他了…\n\n你一定要找到他，然後徹底讓那東西停下來。", progress = nil, completion = "你知道嗎…他可能稱不上是個發明家，但我以那孩子為榮。", rewards = "您會收到：\n\nG.O.L.E.M.二世共鳴水晶共鳴水晶共鳴水晶勇氣石"}
MultiLanguageQuestData['tw'][84680] = {title = "滾石復活", objective = "活化8個躁動的小石岩或躁動的岩石，擊敗8個血鹽恐懼和血鹽巨怪。", description = "進攻的維酷人利用鹽巴和鹹水元素，控制它們去對付自己的敵人。\n\n為了反制他們的攻擊，我們也可以控制這些元素。\n\n利用這個岩石復活裝置釋放寄宿在附近岩石中的元素，把它們變成強大的盟友。有了它們的幫忙，我們就能擊敗這些進攻的維酷人。", progress = nil, completion = "你在壓制那些元素生物上表現出色，&lt;name&gt;。我很想看到你繼續大顯神威。", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][84682] = {title = "為了合約與贊助者", objective = "與斷裂絲線的代表交談，接著締結你的第一個合約。", description = "斷裂絲線準備好要迎接你和你的盟友了。你將會成為點燃安蘇芮克蛛網的火炬。\n\n將軍、輔臣，以及我本人，織絲者，每個人都有不同的手段來對付敵人…還有能幫助我們的共犯的不同增益。你可能會傾向於優先選擇其中一項，或是嘗試同時涉獵全部三項。\n\n去和我們的代表會面，了解我們的各種不同做法。然後你就能締結你的第一個合約。\n\n別擔心，小不點，沒有任何選擇會永久有效。", progress = nil, completion = "願你選擇的贊助者為你提供支持，如同你支持他們一樣。", rewards = "這個任務線能解鎖：\n\n締結合約\n\n下列法術會施放在您身上：\n\n星界雲蛟"}
MultiLanguageQuestData['tw'][84683] = {title = "深入排水溝", objective = "在排水溝營地與帕姆西會合。", description = "你在這裡幹嘛？搞破壞嗎？\n\n我能理解。情況已經脫離掌控了。但如果我們把這裡的管路炸掉，情況就會變得更糟。黑血會流得到處都是。也許我們可以一起想出點正經的事來做。\n\n來排水溝營地找我。我們到時候再聊，先遠離這堆討厭的軟泥再說！", progress = nil, completion = "小聲一點！我從沒在排水溝營地見過這麼多間諜…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84684] = {title = "雷斯的狂奔", objective = "追蹤雷斯。", description = "我看到一個形跡可疑的狐狸人。她看起來很…不安。我好像看到她身邊有一把刀子，而且她的眼睛裡閃爍著黑魔法。\n\n她一發現我在看她，就馬上逃跑了。她是通緝犯嗎？\n\n她…掉了這個。給你。", progress = "<雷斯似乎在匆忙之中弄掉了這顆寶石。>", completion = "&lt;雷斯落下的這顆寶石究竟有什麼用途？&gt;", rewards = "您會收到：\n\n奇特寶石"}
MultiLanguageQuestData['tw'][84693] = {title = "織絲者巢穴專業技能工作臺", objective = "在織絲者巢穴與阿奇塔茲談話。\n\n已提供物品：\n", description = "將這件物品獻給織絲者巢穴的阿奇塔茲，建造你自己的專業技能工作臺。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84700] = {title = "地下合約", objective = "前往織絲者巢穴找寡婦阿拉克娜依。", description = "這隻小織蛛的身上背著一張紙條。這是寡婦阿拉克娜依寫給你的。\n\n「親愛的小不點：\n\n我本人和我們斷裂絲線三巨頭的其他成員要求你出席。阿茲-卡罕特本身正處於進化的邊緣，不過我們需要你的…獨特手段，才能確保這點能實現。\n\n此外，如同往常一樣，贈予你和你的事業的獎勵將會相當可觀。」", progress = nil, completion = "感謝你不辭辛勞回到我簡陋的巢穴。\n\n&lt;寡婦阿拉克娜依發出低沉的笑聲。&gt;\n\n我們為你準備了一些偉大的計畫。這是理所當然的。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84701] = {title = "代言者", objective = "在多恩諾加與麥格尼談話。", description = "所以有另一個跟我有過類似體驗，但情況不一樣的人。\n\n我必須和他談談。", progress = nil, completion = "你是來道別的嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84704] = {title = "不同的觀點", objective = "將4個補給木箱放在來落錘鎮避難的阿拉希難民身邊。", description = "達納斯不在這裡。\n\n法林說因為我們的邀請，所以他已經動身前往落錘鎮了。我可沒向他或任何人發出這樣的消息。\n\n我會立即派先遣騎去找他。\n\n在我們等待他們回來的同時，你和卡爾加的機智或許拯救了我們的人類難民。我們的食物補給剛好用完，沒辦法再供給他們了。\n\n直接把木箱交給他們吧。我想他們一定會對裡面的食物心懷感激的。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84711] = {title = "失蹤的達納斯", objective = "在阿拉希高地的十字路口與嘉亞拉霸主會合。", description = "我的先遣騎在路上發現一個被摧毀的車隊。\n\n四周都是激流堡士兵的屍體。\n\n那可能是達納斯的護衛隊，又或是一群倒楣鬼。\n\n無論如何，我們必須展開調查。希望達納斯還活著。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84714] = {title = "來自鐵爐堡的愛", objective = "在亞格洛克從紅色黎明士兵身上收集20個遭竊的鐵爐堡補給品。", description = "這個「紅色黎明」佔據了亞格洛克的堡壘。各式各樣的強盜團體都已經被他們納入麾下了。\n\n我很確信他們把偷來的戰利品都帶來這裡。\n\n如果我們取回他們偷走的東西，並把它們交還給阿拉希高地的人們，或許能緩解緊張的局勢。\n\n看看他們身上有沒有什麼東西吧。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84715] = {title = "達納斯的下落", objective = "在亞格洛克的建築物中尋找達納斯和紅色黎明的情報。", description = "以亞格洛克為基地十分聰明。太聰明了。\n\n看起來他們的大部分勢力都在這裡。如果達納斯還活著，他們肯定把他囚禁在這裡。\n\n在建築物中尋找他的行蹤。然後盡可能查出紅色黎明的情報。任何能讓他們垮台的情報都可以。\n\n希望達納斯還活著。如果他遭遇不幸，我們就有一場漫長又血腥的仗要打了。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84719] = {title = "正在等候的探險", objective = "到多恩諾加的東門與史卡吉特會面。", description = "你好，<name>！你是為了響應海妖島的冒險號召而來的嗎？\n\n最近，有支哥布林回收團隊在某座小島的中心發現奇特的「歌唱水晶」。\n\n跟哥布林一樣，聖落之地的阿拉希人也對這種水晶很感興趣，而我們也是。我們正準備派一支遠征隊到那座小島！\n\n遠征隊的大多數成員都已經出發了，而哥布林的最後一艘船也隨時會啟航。\n\n如果你快一點，你應該可以在啟航之前趕到，跟我們一起去！", progress = nil, completion = "啊，你就是被黎明說服而加入我們的人，對嗎？\n\n那好，動作快！他們非常固執，堅持要派一個體面的風暴飛騎護送我們出城，但那太花時間了！\n\n阿拉希人和其他土靈已經在小島上了，瑞基特很可能正在想我們到底死到哪裡去了！\n\n來吧！我會在路上告訴你一些細節！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84720] = {title = "前往海妖島！", objective = "與史卡吉特談話，前往海妖島。", description = "海妖島充滿謎團，但在這之中卻有利可圖。\n\n當我的船員發現這個荒島上有一些奇特的歌唱水晶時，還以為自己中大獎了…\n\n結果，多恩諾加的所有人都對這些無主的「奇特歌唱水晶」感興趣。阿拉希人和土靈馬上整裝出發，我們卻連一艘飛艇都還來不及包下！\n\n幸好我們運氣還不錯，瑞基特的團隊已經先去了那裡。\n\n我們是最後一批出發的，我已經等不及想動身了。我們到底還在等什麼？", progress = nil, completion = "我們成功了！毫髮無傷地抵達！\n\n瑞基特告訴我，整個營地都還在熱烈討論水晶的事。\n\n每個人對於如何找出水晶的用途似乎都有不同的看法。\n\n他們不喜歡瑞基特和我的做法，但你或許更擅長溝通。\n\n你想參與其中嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84721] = {title = "掃描水晶", objective = "收集土靈原型機、阿拉希法器和哥布林能量源的資料，協助巴古斯。", description = "為了瞭解關於這顆位在島嶼中心的「歌唱水晶」，我們會用到一些特殊的機器。\n\n我們打造出一個裝置，能夠掃描露出的刻面，但水晶的能量太過複雜，無法讀取。能量訊號高度異常。\n\n哥布林和阿拉希人似乎很想做出貢獻，就讓我們在他們的幫助下進行吧。\n\n帶著我的工具箱，取回原型機，以及阿拉希人和哥布林準備的零件。", progress = "一般來說，我們的技術很擅長分析水晶，以及蘊藏在其中的能量。\n\n不過，在這裡發現的能量充滿異常，不會與我們的技術同步…", completion = "懷疑…解開了。\n\n聖落之地的輻光殘骸似乎與這裡發現的能量完美同調，給了我們能夠捕捉的正確訊號。\n\n哥布林的電池…遠超出我們的需求，但它們的工作效率極高。\n\n我們幾乎可以進行實地測試了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84722] = {title = "閃亮亮的訊號", objective = "到水晶旁與巴古斯會合，協助他設置水晶塔。", description = "真有意思！\n\n阿拉希人的這些輻光殘骸似乎讓我們的裝置有了需要的焦距。剩下的工作就是讓它正確地與它的尺寸同調。\n\n為了與訊號同調，我們必須在那個地點周圍設置一些水晶塔。\n\n需要開始進行測試，<name>。要是願意幫我的話，就跟我來。", progress = nil, completion = "太驚人了！\n\n水晶塔的同調結果指出這顆水晶遠比這個刻面顯示的大上許多。\n\n根據訊號的複雜度，它似乎在我們腳下綿延了好幾英里，而且…等等，這是什麼？\n\n那座山丘上似乎又傳來第二個訊號？真的很奇怪…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84723] = {title = "埋藏的祕密", objective = "調查廢墟，找到訊號來源。", description = "以大多數外來者的標準來看，這些廢墟…相當古老。\n\n問題來了：那些不友善的外來者接到的命令是找到這個房間，還是找到這塊石板？\n\n線索之一是，我的讀數顯示能量正流經作為導體的這塊石板，而不是源自石板。\n\n該進一步調查一下嗎？\n\n也許調查能得到一些答案，並找到能量讀數的源頭。", progress = nil, completion = "我的熔爐啊…這是…\n\n&lt;巴古斯瞠目結舌，一臉驚奇地盯著發光的水晶。不久後，他點點頭。&gt;\n\n這應該就是第二個訊號的源頭，不過這裡的能量似乎與原版的融合在一起。\n\n就好像是它想要我們找到這個地方…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84724] = {title = "璀璨寶庫", objective = "調查水晶聖壇。", description = "這個寶庫…這顆水晶…\n\n誰建了這個地方？誰住在這裡？石板上一再提到的這個「賽斯」是誰？\n\n當我們開始追查水晶的來歷時，我沒料想到會在地底的深處發現古代文明的遺跡。\n\n<巴古斯摸摸他金屬絲般的鬍子，然後看了你一眼。>\n\n這值得靠近一點檢查，你不認為嗎？", progress = "我們似乎有很驚人的發現…", completion = "問題越來越多，得到的解答卻少之又少。\n\n幸好，這個裝置能夠從能量讀數收集一些資料。\n\n它需要一些時間處理資料，不過我們很快就能更加了解這顆「海妖水晶」。\n\n在此同時，我們來仔細研究一下你找到的那枚戒指和黃水晶裂片。這裡的安格菈應該能幫上忙。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84725] = {title = "飾環之喚", objective = "裝備賽斯的飾環，並將風詠者的符文黃水晶鑲嵌至歌唱之風插槽中。\n\n接下來，將風詠者的符文黃水晶從插槽中取出。", description = "<安格菈戴著眼鏡，一臉興奮地看著你。>\n\n<name>，你聽到了嗎？\n\n這個小小的黃水晶正在呼喚飾環…就像海妖水晶呼喚著你和我們所有人一樣。\n\n我不確定它們結合之後會發生什麼事…只有一個方法能找出解答。\n\n將飾環戴在你的手指上，然後把黃水晶嵌入底座。", progress = nil, completion = "從這裡就能感覺到…輻射。其中充滿了沉睡已久的力量。\n\n是誰雕刻出這些小小的黃水晶？它們為什麼與飾環完美契合，卻又…分別在不同地方找到？\n\n喔，我真希望能親眼看到你和巴古斯在這個寶庫中發現的東西…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84726] = {title = "發掘秘密", objective = "發掘海妖島埋藏的秘密。", description = "<安格菈握住你的手，仔細檢查這個嵌入水晶的飾環。>\n\n<name>，你感覺得到與戒指產生共鳴的能量嗎？這個飾環似乎…醒來了。\n\n也許這座小島上埋藏著更多秘密，等著你去一探究竟。\n\n黎明鼓勵我們去探索和了解這座小島，但我在這裡有必須處理的工作。\n\n你何不去看看還能發現什麼秘密？", progress = "你有什麼發現？是另一個寶藏嗎？", completion = "真奇怪。就算是碎片，也會與能量產生共鳴。我在想是不是…\n\n&lt;安格菈將碎片像拼圖一樣拼在一起，然後用手緊握。不久後，她張開手，掌心躺著一枚完美融合的裂片。&gt;\n\n雕刻精度和華麗度可能比不上你在寶庫中找到的黃水晶，不過，就算是這樣的小石頭，裡面也蘊藏著力量。", rewards = "您會學到：\n\n符文使之眼\n\n您還會收到：\n\n原始歌唱黃水晶祝焰鐵"}
MultiLanguageQuestData['tw'][84727] = {title = "第二個訊號", objective = "跟隨巴古斯前往北方。", description = "出乎意料的發展。\n\n能量訊號似乎有第二個來源，就在這裡的北邊。\n\n真讓人好奇。\n\n從水晶預估的大小來看，我認為它或許是第二個暴露的刻面。\n\n需要去調查一番。跟我來。", progress = nil, completion = "看來這座島上不是只有我們這批人，&lt;name&gt;。\n\n\n\n在談判之前就先行使暴力…不合邏輯的舉動招致了不幸的後果。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84728] = {title = "重塑刻面", objective = "協助安格菈修復黃水晶。", description = "你發現的破裂黃水晶似乎完美契合那枚戒指的其中一個插槽，不過…\n\n<安格菈將裂片嵌入戒指，黃水晶卻逐漸脫離，掉了出來。>\n\n戒指似乎拒絕接受這枚裂片。如果我們可以修復黃水晶，使裂片中的能量恢復穩定，說不定戒指就會接受它？\n\n既然你已經幫了巴古斯不少忙，何不再次伸出援手？", progress = nil, completion = "&lt;安格菈將發光的黃水晶拿在手中，隨即將它遞給你。&gt;\n\n似乎可以了…這麼小的水晶居然散發出這麼強的能量，簡直前所未見。\n\n刻在上面的符文極為古老，而且非常強大。", rewards = "您會收到：\n\n風詠者的符文黃水晶"}
MultiLanguageQuestData['tw'][84730] = {title = "武裝職責", objective = "收集50個風暴侵蝕碎片。\n\n碎片可以從海妖島各處的生物身上搜刮到。", description = "這座島上的無機質非常地奇特。鹽水和長年風暴侵蝕的效果讓這個地方的礦物質含量變得非常豐富。\n\n而豐富的礦物質正是受命者想要注入全新武裝裡的材料。\n\n幫我從島上的各種生物那裡拿來大量的風暴侵蝕碎片。我想試試看它們是否配得上我的工藝。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n套裝：石縛土靈戰衣"}
MultiLanguageQuestData['tw'][84735] = {title = "黑鐵矮人的真相", objective = "在再訪黑石深淵團隊副本中擊敗達格蘭‧索瑞森大帝。", description = "鮮少人知曉黑鐵氏族真實的一面，親眼見證的人就更少了。\n\n時光行者答應送我們回到過去、黑鐵氏族大帝崩殂的時間點。希望這能讓我向你展示那次戰敗後發生的一切，無論是好的，還是壞的…\n\n你要自己親眼見證真相嗎？", progress = nil, completion = "黑鐵矮人當時受到拉格納羅斯宰制，我想讓他們擺脫這樣的桎梏。要是我當初能辦到，搶在丈夫還沒…\n\n來，收下這些主持人的代幣吧。感謝你親眼見證當時的真相。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84740] = {title = "踏入荒蕪", objective = "使用回音勘測裝置幫助奧姆菲納尋路。", description = "你是要去沙丘嗎？我在找我的妹妹沙哈塔。我不確定她是不是還活著，但我一定要找到她。\n\n至於該從哪裡找起，我唯一能想到的只有我們的村莊。凱瑞西已經和我記憶中的樣子完全不一樣了。我需要地標，任何能讓我辨認和導航的東西都行。\n\n這個回音勘測裝置給你。它能顯現過去的蹤跡…但願這足以為我們指明方向。", progress = nil, completion = "&lt;name&gt;，謝謝你。我想我已經知道方向了。你有看到這裡曾經孕育了多少生命嗎？實在很難想像沙哈塔有辦法在這裡生存這麼久…不。我們會找到她的。一定會。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84741] = {title = "沙中之兆", objective = "跟隨奧姆菲納前往他的村莊。", description = "我開始有種熟悉的感覺了。我想我認得回去村莊的路了。\n\n我先跟你說一聲…我不只是在找我的妹妹。我們的母親是在我到城市裡念書的時候過世的。沙哈塔把她埋在她最喜歡的樹下，但我當時沒到場。我發誓我本來要回家舉辦喪禮的，但我沒能趕上。\n\n我已經讓我的誓言擱置太久了。至少現在我該努力嘗試，這是我欠母親的。走吧，我們去找村莊。", progress = nil, completion = "我不知道我在期待什麼。她說得對。我確實違背了誓言，現在我的村莊也不在了…不過，她還在這裡。\n\n如果她手上有母親的任何私人物品，那就還有機會用勘測裝置找出墓地的位置。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84755] = {title = "最後的玩具", objective = "與瑪魯交談。", description = "瑪魯發現她的其中一個玩具不見了！\n\n這會跟你之前幫她朋友找玩具的事有關嗎？", progress = nil, completion = "不！我的玩具不見了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84756] = {title = "玩具小偷", objective = "發現玩具小偷。", description = "我的玩具！被偷走了！\n\n我們必須揪出兇手，不能讓他們偷走更多玩具！", progress = nil, completion = "耶！你找到所有玩具了！那條大狗狗是怎麼收集到這麼多玩具的？\n\n我得去看看那一堆裡還有沒有我的玩具…\n\n謝謝你的幫忙。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84759] = {title = "星光下的不幸相遇", objective = "在沙哈塔的營地和她會面。", description = "我以前會練習再次看到我哥時要說的話。但後來我覺得沒什麼好說的了…\n\n他離開了這麼多年，現在卻想回來拿傳家寶？我在我們母親的墓旁種了她最愛的樹。只有我一人。他那時早該回來了，我現在沒空照顧他的情緒。\n\n要是你們兩個真的這麼想聊，至少也該有點常識，別在荒郊野外聊。來我的營地，我們到那裡再談。", progress = nil, completion = "我從沒想過會再次見到菲納。他要來幫忙辦母親的喪禮已經有點太遲了。那棵樹已經和墓地一起消失了，現在他竟然想來找我幫忙？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84760] = {title = "友善的警告", objective = "殺死縛魂者薩比爾和決鬥者卡辛。", description = "在吞盡發生之前，蘇法迪原本是一群牧師。他們遵循著謙恭和慈善的傳統，不過那也和凱瑞西的其餘部分一同被抹除了。如果荒地居民認為我不會報復，那他們就永遠不會放過我。\n\n我想你應該知道展現力量有何價值。殺死他們的領袖，當作對其他人的警告。", progress = nil, completion = "希望這樣足以讓他們卻步…至少能維持一段時間也好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84761] = {title = "勞動與入侵", objective = "取回沙哈塔的遭竊的補給品。", description = "菲納選了個糟糕的時機來向我求助。等我從蘇法迪那裡拿回我的補給品之後，我馬上就會離開了。\n\n他們襲擊的時候我正好經過，要是魯雅沒有把我扛走的話，他們一定會把我殺死。我跟蹤他們回到蘇法德，但那裡的人數不是我能應付的。\n\n如果你幫我取回我的補給品，我就試試看能不能幫到菲納。", progress = "希望他們還沒把我的東西用光光。", completion = "你只找到這些？他們還真是迫不及待想把我的補給品用完。不過，有總比沒有好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84762] = {title = "言出必行", objective = "幫助沙哈塔取回她母親的項鍊。", description = "我有一條我們的母親製作的項鍊。蘇法迪打劫我的時候把它拿走了。古老的凱瑞西物品很稀有。如果蘇法迪還沒把它拿去交易，那它會和他們的其他貴重物品放在一起。\n\n我原本打算把它放棄。感傷並不值得冒生命危險，但你遵守了承諾…光是這點就比我哥好很多了。幫我把項鍊拿回來，它就歸你了。", progress = "發生了什麼事？菲納在哪裡？", completion = "全沒了。好幾個月的補給品付之一炬。如果菲納還沒死，那他很快就會了。蘇法迪不會善罷甘休的，尤其是在我們做了那些事之後。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84765] = {title = "羈絆如枝", objective = "幫助奧姆菲納和沙哈塔悼念他們的母親。", description = "在塔札維許待了這麼久，我每天心心念念的就是回到家鄉。現在卻只有帶來更多的悲傷。就算勘測裝置沒受損，我還是沒有能用來尋找母親墓地的東西。\n\n<奧姆菲納四處張望著洞穴。>\n\n看到這些印記了嗎？這裡曾是交換的神殿。我想這也是個適合道別的地方。你願意再幫我最後一次嗎？一點都不危險，只是點個香而已。", progress = nil, completion = "過了這麼久，我以為當我們兌現誓言的時候會有不同的感覺。\n\n也許現在是時候停止對過去念念不忘了。謝謝你。", rewards = "您會收到：\n\n共鳴水晶勇氣石凱瑞西信託同盟"}
MultiLanguageQuestData['tw'][84767] = {title = "燒焦的節慶木箱", objective = "將燒焦的節慶木箱還給阿利克斯。", description = "<這個木箱被火燒焦，但裡面的東西還能回收。歸還這個補給品一定能讓阿利克斯相當感激。>", progress = "嗯？", completion = "喔，你找到遺失的木箱了！太好了！\n\n真的很感謝你。如果你找到其他木箱，請送回來給我。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84773] = {title = "晶化的節慶木箱", objective = "將晶化的節慶木箱還給阿利克斯。", description = "<這個木箱佈滿結晶，沒辦法輕鬆撬開。歸還這個補給品一定能讓阿利克斯相當感激。>", progress = "嗯？", completion = "喔，你找到遺失的木箱了！太好了！\n\n真的很感謝你。如果你找到其他木箱，請送回來給我。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84776] = {title = "來探究吧", objective = "在卡茲阿爾加完成5次探究。", description = "到處進行探究，就有機會找到許多寶藏。\n\n其中的一些寶藏也許對你有用。", progress = nil, completion = "你活著回來了！做得很好。", rewards = "您會收到：\n\n探究者戰利品寶箱青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][84781] = {title = "秘密大師", objective = "看來你也是個尋秘獵人！有人叫我給你這個。祝你好運！", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n黃金莫芬鬆餅"}
MultiLanguageQuestData['tw'][84784] = {title = "故事漫遊：匕首的死敵", objective = "啟動3個祭儀方尖碑來召喚尤格薩倫、克蘇恩和亞煞拉懼。", description = "恩若司大人現在召集了他的盟友來協助處理薩拉塔斯的潰敗。你已被選中來迎接他們。\n\n你知道該做什麼。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
