MultiLanguageQuestData['tw'][84820] = {title = "誓言與血脈", objective = "拯救奧姆菲納。", description = "在吞盡發生之後，我沒想過我會再次見到菲納。一開始，比起難過，對他的離開感到生氣反而更容易。後來我變得容易放下，只為了專注在生存上。再次看到他之後，那些情感又統統回來了。\n\n破誓者…他違背了歸鄉的誓言，但家人才是我們自誕生以來的第一個誓言。要是我現在拋棄他，那我又算什麼？\n\n他是我的哥哥…這是誓言，也是血脈。我不會讓蘇法迪傷害他。", progress = nil, completion = "我幾乎沒料到她會來救我，就算會也不會是那個樣子。儘管如此，勘測裝置受損，沙哈塔的補給品也被燒了。也許我就不該回家的。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84821] = {title = "活動槍靶", objective = "在鼴鼠背上用長槍刺中攜帶假人的軟泥怪。", description = "既然獲得馬刺，就來使用一下！\n\n軟泥怪帶著槍術假人逃跑了，不過那也讓它們變成活靶子。更好的練習目標！\n\n到門旁騎上高貴的鼴鼠戰騎，拿好長槍，追上軟泥怪。\n\n任何騎士都要會的重要能力。", progress = nil, completion = "哈！長槍就像滾水，從這裡就能聽見嗶剝聲。\n\n你已經是優秀的騎士。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84822] = {title = "前往伊斯凱拉", objective = "在伊斯凱拉與赫米特‧奈辛瓦里會面。", description = "讓這些孩子回到伊斯凱拉，好嗎？\n\n我們到那邊會合。", progress = nil, completion = "啊，這樣好多了。全都帶回家安置好了。十分感激！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84826] = {title = "洛凡秘境", objective = "在洛凡秘境與暗域行者會面。", description = "我不會為我們做的事找藉口。只要我還健在，我就會一直背負這個責任。艾蘭里亞會理解為什麼這是必要的。當她看到『吞盡者』的力量時，她就會懂了。\n\n我們至少還需要兩個瑞西緞帶，才能帶著足夠的力量對抗迪曼修斯。我的朋友奧姆貝拉是緞帶持有者。她在下一座島上的洛凡秘境工作。我們去請她加入我們吧。", progress = nil, completion = "秘境破損，奧姆貝拉可能有危險了！我能看到凱瑞西廢土的拾荒者已經進到裡面了。\n\n奧姆貝拉或許還活著。我們必須找到她，還有她的瑞西緞帶。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84827] = {title = "破碎秘境", objective = "在洛凡秘境尋找奧姆貝拉。", description = "洛凡秘境被一大塊墜落的虛無之鏡砸碎，導致其結構被毀，管理員也四散各地。之後他們回來尋找任何可回收的裝備和動植物，避免它們淪為荒地的一部分。\n\n在廢墟裡尋找任何線索，幫助我們知曉監督者奧姆貝拉的命運。我們必須得到她的瑞西緞帶！我和奧姆雷什會去撞擊坑那裡找。", progress = "有沒有可能奧姆貝拉還在殘骸裡的某處？", completion = "荒地居民殺死了奧姆貝拉，奪走了她的瑞西緞帶。自吞盡之戰以來，這些墮落的神諭者就不斷地襲擊纏結者的所有成員。這真是令人沮喪的一天。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][84831] = {title = "洛凡侵染", objective = "在洛凡秘境殺死10隻入侵的生物。", description = "隕石擊中時，我和奧姆貝拉試著盡可能搶救。少了秘境的防護罩，我們很快就受到星外暗界的拾荒者圍攻。後來我們在逃跑的途中走散了。\n\n這樣的生物根本不屬於凱瑞西，而且牠們對我們試圖打造的穩定生態系懷抱敵意。我們必須除掉這些入侵的生物，才能找到我們的裝備和奧姆貝拉。", progress = nil, completion = "謝謝你。要是沒人處理那些生物，我們很快就會徹底淪陷。\n\n驚人的是，這些生物就算沒有秘境的防護屏障也能生存，也不會像凱瑞西人一樣變成能量。不知道能不能將這種強大的適應能力轉移到秘境中的幾種原生物種上？", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][84834] = {title = "暴風裂縫", objective = "帶6個虛無裂縫精華給暴風原野的薩拉塔斯。", description = "荒地居民曾經是凱瑞西世界之魂的神諭者。他們對自己的誓言既自豪又強硬。如今他們卻像動物一樣在廢墟中拾荒。就算是老鼠都有其作用。\n\n替我收集虛無裂縫精華。我有個點子，或許能說服墮落的神諭者加入我們。", progress = "許多虛無的住民都是飢餓的能量吞食者。它們會貪婪地湧向能量的匯聚點，就像飛蛾撲火一樣。", completion = "做得好，我的勇士。我們會利用這個來引出我們的獵物。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84835] = {title = "沉溺巢穴", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84836] = {title = "震顫窪地", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][84838] = {title = "敵人的敵人", objective = "將聚合虛無能量放置在卡斯提迦。", description = "荒地居民在古老凱瑞西的廢墟中紮營。那是一個能躲避在凱瑞西荒地中橫行的貪婪虛無野獸的庇護所，也是抵禦外來者的壁壘。\n\n要是有帶著敵意的實體進入他們的營地，你可以將之擊敗，這麼一來就能贏得他們的敬重。把你收集到的虛無能量帶去此地北方的廢棄塔樓。做好準備！", progress = nil, completion = "迪曼修斯摧毀了凱瑞西。在殘酷的凱瑞西荒地中，我們會懲罰所有辜負他的人。你說你的誓言與我們一致？那就來聊聊吧。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][84848] = {title = "虛無之前", objective = "說服撰魂師加入。", description = "我的勇士，你成功用你的暴力讓這些荒地居民刮目相看了。做得好。現在該輪到我出馬了。\n\n我知道這些曾經的神諭者想要什麼。他們夢想能再次聽見凱瑞西之歌。我必須讓他們相信這是有可能的，然後牽動那條渴望的絲線。很快我們就會得到一支大軍，還有另一條瑞西緞帶。\n\n首先，我們先把塔比卡儀式匕首還給他們。", progress = nil, completion = "我們很樂意和影衛開戰。但我不能把這條瑞西緞帶交給我不信任的人。\n\n復仇的承諾何其容易，但荒地居民的信任得來不易。", rewards = "您會收到：\n\n勇氣石"}
