MultiLanguageQuestData['tw'][85109] = {title = "凱瑞西信託同盟名人", objective = "到塔札維許與奧姆席立克交談。", description = "旅行者，你對凱瑞西的援助會被永遠銘記。在此獻上我們最深的謝意。\n\n為了表示感謝之情，我們為你準備了一份禮物。去塔札維許找奧姆席立克。他會把禮物親手交到你手中。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n滿溢凱瑞西聯合會寶藏"}
MultiLanguageQuestData['tw'][85113] = {title = "特殊任務：風暴正在醞釀", objective = nil, description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n土靈旱鴨子儲物箱"}
MultiLanguageQuestData['tw'][85174] = {title = "出門辦事", objective = "在尾門公園與德克‧賣油者交談。", description = "你們都見識過加里維克斯的能耐了。這些武器，這個黑血…我們必須從源頭切斷他的供應。里維加茲，你得把從你的總部運出來的貨物毀掉。然後葛麗菈，風險投資公司一定是跟『喬事人』妮琪搭上線才能有如此精良的武裝。我們分頭行動。\n\n<name>，我想要你跟我來。我在尾門公園有個叫德克的新聞記者，你會想和他談談的。我們需要決心跟智慧才能奪回這座城市。我很快就會過去。", progress = nil, completion = "這裡真是一團亂！但如果加茲魯維有個計畫，我絕對支持他！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85189] = {title = "法院的一天", objective = "在屋舍嶺到馬蒂‧速車的辦公室和他會面。", description = "又完成一堆瑣碎的法律工作了，<name>！你該考慮一下加入這個行業…這個行業也不知道在做什麼就是了。\n\n我會去拿地精的簽名，我們到時候在我的辦公室會合。\n\n一般來說，我很願意載你回去，但我有事情要先忙。等等見。", progress = nil, completion = "我們來到緊要關頭了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85190] = {title = "塵歸塵", objective = "與加茲魯維交談，將雷吉克的骨灰送還給馬迪亞斯‧肖爾。", description = "我很意外肖爾會親自現身。我原本以為他會派個探員之類的過來，不過…也許我該開始相信人性本善。\n\n我確保雷吉克得到安息。得到他應有的尊敬。製作這個箱子花了我很多時間。有一大堆小東西。我並不擅長這麼精細的作業，不過我做出了相當不錯的成品。\n\n相信他還是可以輕輕鬆鬆把鎖撬開，不過…\n\n<加茲魯維露出悲傷的微笑。>\n\n我們來把他送回暴風城的老家吧，好嗎？", progress = nil, completion = "我很抱歉突然換地方，不過你必須親眼看看這個，而不是光聽我說。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85191] = {title = "一幕又一幕", objective = "在西部荒野燈塔收集雷吉克的遺物。", description = "雷吉克是我底下最出色的探員，除此之外，他也是我的朋友。\n\n他不是不甘不願地到幽坑城出任務的暴風城探員。他為暴風城做事，但他愛的是幽坑城。\n\n他的族人才是他的家鄉。不是我們。\n\n幫我收集雷吉克留在這裡的一些東西。它們應該跟著他，一起回到幽坑城。", progress = "雷吉克不是一個很外向的人，不過藉由一些小地方，就足以讓我了解他。", completion = "雷吉克認同暴風城和我們的理念，但他最愛的永遠是幽坑城。\n\n我必須讓你們兩個知道這點。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85192] = {title = "回家", objective = "到幽坑城廢料工坊的樓上與加茲魯維和馬迪亞斯‧肖爾會合。", description = "雷吉克會希望他的骨灰回到幽坑城。這點我很肯定，而我願意幫我的朋友最後這個忙，完成這件事。\n\n他一定不希望自己被塞在暴風城墓園的大理石板下，遠離他的族人。\n\n我們走吧，<name>。", progress = "知道他一直把幽坑城視為自己的家鄉…\n\n太讓人難受了。我本來可以更加了解他這個人。", completion = "雷吉克終於到家了。\n\n我們會確保他再也不會被迫離鄉背井。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85195] = {title = "海盜烹飪法", objective = "利用羅莎的歡樂盛宴解譯筆記，尋找正確食材。", description = "這是破譯後的庫克托羅姆筆記。雖然看起來還是怪怪的，但我確定破譯的內容是正確的。\n\n我順利得出每個必要食材的數量，但他似乎用自己的方式為每種食材命名，所以…祝你好運！", progress = "你別擔心。我們很有耐心，真的。", completion = "我們真是太走運了，你成功了！現在我們可以準備盛宴，然後啟航回家了。\n\n謝謝你，朋友！", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][85208] = {title = "海盜信件", objective = "從藏寶海灣的憤怒羅莎那裡拿回筆記。", description = "你來了，<name>。在藏寶海灣有個叫憤怒羅莎的人想見你。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85229] = {title = "惡人齊聚一堂！", objective = "將廣告拿去給多恩諾加的爭奪者大門的霍桑。", description = "大家都來吧，前往多恩諾加！\n\n除了爭奪者大門提供的強大裝備之外，新來的戰鬥者和資深鬥士也可以購買徽章代幣，用來製造可以在競技場與戰場中使用的認證裝備！\n\n把這張傳單拿給霍桑來領取免費代幣！\n\n- 艾莎", progress = nil, completion = "啊，我正在想說，積極的鬥士什麼時候會出現呢。\n\n按照約定，拿去吧。提交製作訂單或製作你自己的裝備時可以用這些。成品就會跟拉蘭迪在那邊賣的裝備一樣強大，不過當你在找符合喜好的客製化裝備時，這些就很好用。如果你還需要更多，你知道該去哪裡找我。\n\n有問題嗎？把它們帶到熔爐地吧。", rewards = "您會收到：\n\n星界鬥士徽章"}
MultiLanguageQuestData['tw'][85238] = {title = "階梯上的陌生人", objective = "找到奧姆巴拉德。", description = "拜託！我們一定要阻止那克羅亞。奧商集團派我們三個人來這裡安裝研究機器，這都是為了幫助研究滅絕的植物。剛開始荒地居民們還算客氣，甚至有些好奇…直到我們準備離開。\n\n他們強迫我們改造機器。奧姆姆薩拒絕了，他們就殺了他。奧姆巴拉德和我選擇屈服。我們也應該拒絕才對。\n\n完成改造後，荒地居民們放鬆了警戒。奧姆巴拉德叫我快跑，我就照做了。他當時就在我身後。拜託了，幫我找到他。", progress = nil, completion = "我聽到他倒下了。我應該為他停下的，但我卻選擇繼續逃跑。\n\n我們得彌補這一切。我們幫荒地居民把那台機器改造成武器。它不會幫助這片土地重生，只會殺光所有生物。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][85239] = {title = "新一輪吞盡", objective = "打斷那克羅亞的儀式。", description = "這裡早已不是什麼神殿，這是屠宰場。他們把俘虜的靈魂硬生生撕出來，用來驅動他們的儀式。現在，他們正將竊取來的能量灌進我們的機器。我想我知道他們的目的了。\n\n經過我們改造後，用秘法能量讓裝置超載，就能製造龐大的能量循環。這會瓦解整個凱瑞西的魔科技。秘境會全面失效，塔札維許也將毫無防備。我們會成為那克羅亞的下一道大餐。如果你能打斷他們的儀式，就能幫我們爭取時間。", progress = nil, completion = "那會拖慢他們的腳步，但恐怕還不夠。我們必須結束這一切，不能讓他們毀了我們的所有努力。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][85240] = {title = "唯餘飢渴", objective = "擊殺那克羅亞荒地居民。", description = "他們以為薩拉塔斯回來是為了他們，他們相信自己的崇拜終將得到回報。為了證明對她的忠誠，他們會吞噬一切。\n\n我們來這裡是為了和平，為了重建那破碎的家園。$p，我們得守住未來。那是我們僅存的一切。這些荒地居民正集結人手準備攻擊秘境。如果讓他們破壞防護罩，整個秘境會被洗劫一空。絕不能讓他們得逞。", progress = nil, completion = "即使我們在這裡失敗了，這也許還能替我們的防衛者爭取一線生機。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][85241] = {title = "昔日驕傲的牧師", objective = "擊殺『揭滅者』伊薩姆。", description = "他們的首領正在主持最後一處儀式現場。『揭滅者』伊薩姆…我親眼見識過他如何名副其實。如果他用我們的回音機器反過來對付我們，他和他的信徒會摧毀一切。我們全都會成為他們缺席的「神」的祭品。\n\n殺了他，終止那場儀式。我們絕不能再讓第二次吞盡發生。", progress = nil, completion = "不，他死了。但為什麼儀式還沒停下？它反而變得更強了。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][85242] = {title = "賽季複習課程", objective = "在探究者的文件中了解探究第2賽季的資訊，接著再向里諾‧傑克森和芬利‧莫戈頓爵士購買補給品。", description = "我們又要回去探究，來發掘更多秘密了！\n\n首先，先來看看我們找到的新東西。\n\n接下來，我們再來談談令人擔憂的事。", progress = nil, completion = "都準備好了嗎？很好。\n\n我有個故事想告訴你。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85243] = {title = "我要拿回我的帽子", objective = "聽布萊恩說他弄丟寶藏和帽子的故事。", description = "你可能發現我好像不太一樣。\n\n有些哥布林把我的帽子搶走了！我們收集的所有寶藏也都不見了！\n\n事發經過是這樣的。", progress = nil, completion = "現在你知道來龍去脈了。\n\n但至少我有還手，給他們一點顏色瞧瞧。\n\n交給你了！我還有其他要事要處理。", rewards = "您會收到：\n\n探究者的哥布林奔走者"}
MultiLanguageQuestData['tw'][85244] = {title = "擊敗幽坑霸主", objective = "提升你的物品等級，並在幽坑城的級別8探究中挑戰幽坑霸主。", description = "那個該死的「幽坑霸主」把我的帽子搶走了！還有我們收集的古董也是。\n\n是時候來報仇了。如果想把他撂倒的話，我們得變得更強。\n\n當你準備好之後，他就在幽坑城裡。\n\n我也會跟你去的！", progress = nil, completion = "我們辦到了！哈！\n\n這樣所有人都知道，我們可不好惹！\n\n其他人也休想再偷我的帽子！\n\n啊…有你回到身邊實在是太好了。\n\n來。收下我的備用帽子。另一頂不見的情況下，戴著它總覺得怪怪的。", rewards = "您會收到：\n\n布萊恩的備用帽子爆炸性勝利"}
MultiLanguageQuestData['tw'][85249] = {title = "蜜蜂的考驗", objective = "在中庭與植物學家愛蓮拉會面。", description = "我會請你的…貴賓…前往中庭照料蜜蜂。\n\n你該去看看她。她應該會需要幫助。", progress = nil, completion = "&lt;name&gt;，又見面了！你是來幫忙的嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85255] = {title = "寧靜之蜂", objective = "在凱瑞西的普萊姆斯秘境中鎮靜並標記10隻蜜蜂。", description = "我想我們可以開始準備讓蜜蜂移到綠洲裡了。我想標記牠們來監測蜂巢。\n\n蜜蜂不會靜止不動太久。我們需要先讓牠們鎮靜下來再標記牠們。我已經標記女王蜂了。你可以標記其他蜜蜂嗎？", progress = nil, completion = "啊，謝謝你！希望你沒有被叮到！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85256] = {title = "終於有植物學相關的東西了", objective = "收集10個凱瑞西花卉植株。", description = "蜜蜂生活得還不錯，對當地的植物也沒有什麼負面影響。那花卉呢？\n\n我從綠洲的植物上取得了一些植株樣本。你可以從這個秘境裡採集一些樣本，好讓我進行比較嗎？", progress = "能再次開始研究植物讓我欣喜若狂。最近都在「蜂」狂研究蜜蜂。有聽懂吧？「蜂」狂？", completion = "太好了！蜜蜂和植物相處融洽。這代表牠們準備好進駐綠洲了！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85257] = {title = "在普萊姆斯秘境勤做工", objective = "在普萊姆斯秘境與植物學家愛蓮拉會面。", description = "好了。讓這些蜜蜂進到普萊姆斯秘境裡，進行下一輪實驗吧！", progress = nil, completion = "如果我是蜜蜂，我會是女王蜂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85258] = {title = "喔，蜂蜜啊蜂蜜", objective = "在綠洲收集8個蜂巢，並照顧女王蜂。", description = "蜂巢的狀況蠻穩定的。但我想快速檢查一下蜂蜜的存量。這些植物的花粉不太一樣，所以蜂蜜的品質應該也有所改變。我們得確保能讓蜂巢正常運作。\n\n根據過去秘境的實驗，應該沒什麼問題。但還是得檢查一下，沒錯吧？", progress = "你收集到蜂巢了嗎？", completion = "我會對這個資料進行分析，來確保沒有任何問題。謝謝你。\n\n如果你還有空的話，愛蓮拉說有其他任務需要幫忙。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85259] = {title = "搖擺舞", objective = "在綠洲為蜜蜂跳舞。", description = "愛蓮拉要我幫我轉達這條訊息。\n\n「嘿，奧姆塔拉。我要跳舞給蜜蜂看，好讓牠們知道新的花卉在哪裡。你可以叫<name>做一樣的事嗎？」\n\n真奇怪，不過還是請你盡力…跳支舞。", progress = nil, completion = "你有迎「蜂」起舞嗎？你做得不錯，&lt;name&gt;。這能幫助蜜蜂和讓綠洲蓬勃發展。讓更多蜜蜂知道植物在哪裡絕對不是壞事。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85260] = {title = "今天太「蜂」了", objective = "拾起10隻過勞的蜜蜂，然後送牠們回蜂巢。", description = "我剛剛發現有幾隻蜜蜂躺在地上。我想牠們找到新植物前讓自己太勞累了。\n\n牠們會沒事的。牠們只是累壞了。你可以幫我把牠們撿起來，然後送回蜂巢嗎？", progress = nil, completion = "所有蜜蜂都到齊了。謝了，&lt;name&gt;。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85261] = {title = "蜜蜂美照", objective = "為女王蜂和10隻蜜蜂做紀錄。", description = "啊，你來了。是時候開始記錄了！\n\n我們必須追蹤蜜蜂在綠洲的生活狀況。我已經把文件都弄好了。或許你可以去現場幫我拍那些蜜蜂？", progress = "你有拍到不錯的照片嗎？", completion = "你真的很會拍照欸。看看這張照片的構圖！\n\n我們不需要編目員沃福德等級的照片…但有你幫忙真好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85262] = {title = "王家行進", objective = "幫女王蜂找到蜂巢的新位置。", description = "嗯，你的照片讓我覺得，蜂巢準備好分巢了！\n\n這是所有蜂巢的最終目標，誕生新的女王蜂，然後建立新的蜂巢。也代表女王蜂得搬到新位置，不過這附近有很多秘境，你說對吧？\n\n你可以幫她找個新位置嗎？", progress = "你把老女王安置好了嗎？", completion = "很好，我們的女王已經長大了！", rewards = "您會收到：\n\n勇氣石"}
