MultiLanguageQuestData['tw'][85461] = {title = "食品零工", objective = "在塔札維許從以太族手中取回15箱遭竊的食物。", description = "我們給動物的最新一批食物在塔札維許被以太族搶走了。\n\n我想請你以牙還牙。", progress = "你取得食物了嗎？", completion = "你對暴力的詮釋總是讓我感到開心，&lt;name&gt;。\n\n我敢打包票，以太族一定不這麼認為。", rewards = "您會收到：\n\n共鳴水晶勇氣石凱瑞西信託同盟雕刻以太紋章"}
MultiLanguageQuestData['tw'][85462] = {title = "統御挑戰", objective = "挑戰石背首領。", description = "我們的石背首領最近有點…躁動。他應該是想找個人挑戰。\n\n你是我們當中最能幹的。去挑戰他一下。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85465] = {title = "玩球", objective = "跟小刺尾玩的同時，接球10次。", description = "這隻小刺尾一整個早上都想要我關注牠。牠是很迷人沒錯，但我還有工作要做！\n\n我想牠需要放電一下。帶著這顆球去跟牠玩。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
