MultiLanguageQuestData['tw'][85546] = {title = "共鳴水晶", objective = "<name>，你對議會而言是個寶貴的資產。我們請你接受這枚獎章作為感謝，從今以後，你就是一名榮譽議員了。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n共鳴水晶"}
MultiLanguageQuestData['tw'][85553] = {title = "零工：螃蟹到處跑", objective = "在卡迦灣從彈殼蟹身上收集15份火藥蟹肉。", description = "對任何在海上冒險的船員來說，食物是非常重要的資源。火藥也一樣。\n\n我們去卡迦灣殺死一些螃蟹並收集彈殼吧，這可謂是一石二蟹。\n\n不過要小心別在過程中被炸飛了，行嗎？", progress = "我們需要時間才能將火藥從蟹肉分離，所以快去解決牠們！", completion = "你看看！這些肉夠餵飽整個團隊和其他人了。\n\n我們只需要非常謹慎地把火藥去除掉就行了。可不希望有人在烹飪的時候被炸斷手。", rewards = "您會收到：\n\n戰爭火花共鳴水晶共鳴水晶共鳴水晶共鳴水晶"}
MultiLanguageQuestData['tw'][85554] = {title = "零工：蛋黃面永遠朝上", objective = "在卡迦灣收集8顆翼手龍蛋。", description = "最近幽坑城裡非常流行吃翼手龍的蛋。如果黑水集團沒辦法進口高需求的奢華商品，那不就有損我們的名號了嗎？\n\n如果你想賺點錢，就去卡迦灣幫我們收集一些吧。\n\n喔，記得別拿太多。最近的顧客很喜歡我們把商品打上「符合道德」的標籤。", progress = nil, completion = "記住我的話，這些一定會在早午餐店大賣。", rewards = "您會收到：\n\n渦輪排氣管5000型可能隱形斗篷共鳴水晶共鳴水晶共鳴水晶共鳴水晶"}
MultiLanguageQuestData['tw'][85562] = {title = "意外艱難", objective = "從暗融勢力手中奪回港務局。", description = "哈！我從來沒有這麼爽過！現在，我們奪回了原本就屬於黑水集團的東西，<name>。\n\n他們把我們珍貴的總部變成了那種骯髒汙泥的走私者港灣。現在有太多箱黑血要處理，但只要沒有鮮活的人力，他們就無法移動貨物。我們把他們砍了吧。", progress = nil, completion = "在這之後，加里維克斯應該就知道不要輕易與黑水公司為敵。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][85570] = {title = "殘破的日記", objective = "將日記交給海妖島營地的絲特琳‧維拉薩。\n\n已提供物品：\n", description = "<當你匆匆翻閱日記時，它幾乎在你手中解體。\n\n殘留的幾頁上寫滿了鬼畫符。\n\n或許營地的絲特琳‧維拉薩會對這本日記感興趣。>", progress = nil, completion = "喔，哈囉，&lt;name&gt;！你手上拿著什麼?", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85571] = {title = "四散在風中", objective = "在小島上收集5張日記書頁。", description = "我的天啊！這本日記缺了好多頁！\n\n<絲特琳小心翼翼地翻閱日記，以免弄掉更多鬆脫的書頁。>\n\n這本日記好像不是很古老…而且似乎出自人類之手？這會是了解來到這裡的人類出了什麼事的關鍵嗎？一切都是個謎！\n\n如果能夠找到缺失的部分，應該能知道了…你在外探索的時候，能不能順便尋找一下？", progress = "你找到更多日記書頁了嗎？", completion = "哇，看看這些書頁！\n\n做得非常好，&lt;name&gt;！現在，最困難的部分來了…", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85572] = {title = "團體工作", objective = "詢問艾爾塔、史琦德和瑞基特能不能看懂那本日誌。", description = "這個…呃…你真是給了我一個大難題。這一些書頁…它們的順序到底是什麼？\n\n啊哈！\n\n這本日記似乎屬於來到這裡的某個庫爾提拉斯人…\n\n<絲特琳抬起頭，興奮地眼睛發光。>\n\n…透過裡面的內容，或許能知道他們在這座小島上的遭遇。\n\n不過上面的字很難看懂…也許我們應該到處問問，看看有沒有人看得懂？\n\n來，帶幾頁走。在你去營地問人的時候，我會試著繼續解讀日記的內容。", progress = nil, completion = "喔！&lt;name&gt;，還好有你在。我對日記的研究有了重大突破，但我想先知道你找到什麼東西。\n\n你找到什麼有趣的東西了嗎？有人能解讀那份手稿嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85573] = {title = "終於得以安息", objective = "將破損的庫爾提拉斯人日記帶到廢棄礦坑的庫爾提拉斯基地後方的墓地。", description = "<絲特琳一邊聽你說明你得到的情報，一邊重重地點頭。>\n\n這個可憐的傢伙曾是搭乘名為少女之喃號的船來到這裡的船員之一。他們幾乎在一場風暴全滅，後來甚至連倖存者都消失了！\n\n他是最後一人，但…最後也沒能活下來。也許我們可以讓他的回憶獲得安息？\n\n我發現庫爾提拉斯的基地後方有一片墓地…也許把日記放在他的同伴的墓旁，能讓他的回憶得到一些安寧。", progress = nil, completion = "很好。真高興一切都結束了…希望他現在能跟著他的朋友和同伴，一起好好安息。\n\n如果你感興趣的話，我抄錄了日記的內容，你可以拿去看。它或許有一些用處。\n\n&lt;絲特琳停頓了一下，陷入沉思。&gt;\n\n不知道…那些船員出了什麼事？為什麼最後只剩下寫日記的人？\n\n看來這座島上還有很多費解的謎團。", rewards = "您會收到：\n\n抄錄的庫爾提拉斯人日記"}
MultiLanguageQuestData['tw'][85574] = {title = "模糊不清的慶典箱", objective = "將模糊不清的慶典箱還給阿利克斯。", description = "<這個帶著黑暗死靈能量的木箱在現實中忽隱忽現。無論如何，阿利克斯都會很感激你讓這個補給品物歸原主。>", progress = "嗯？", completion = "喔，你找到遺失的木箱！太好了！\n\n真的很感謝你。如果你找到其他木箱，請送回來給我。", rewards = "您會收到：\n\n時光扭曲徽章青銅龍慶典代幣青銅龍慶典代幣"}
MultiLanguageQuestData['tw'][85589] = {title = "弄皺的書頁", objective = "從島上的蠍尾獅巢穴收集15份築巢紙張。", description = "這座島上大部分的蠍尾獅都是用牠們從島嶼的遺跡裡找到的對開本、卷軸和文件來築巢。\n\n因為這個緣故，牠們的巢中或許藏有能幫助我們了解這個地方的歷史全貌的線索。\n\n我們的斥候已經設置好了爪鉤固定點讓你爬到牠們的巢裡，但你也可以用你喜歡的方式來取回蠍尾獅當作築巢材料的紙張。我們對這座島的歷史知識就全靠那些紙了！", progress = "我真的很想看看蠍尾獅拿走的那些紙上記載了什麼！", completion = "有一點點咬過的痕跡，但我還是可以看清楚上面的文字。做得很好，&lt;name&gt;！", rewards = "您會收到：\n\n雕刻先驅者紋章勇氣石祝焰鐵祝焰鐵"}
MultiLanguageQuestData['tw'][85648] = {title = "探究者之喚：地行礦坑", objective = "在任一難度下完成地行礦坑探究。", description = "需要幫手\n\n地行礦坑內依舊麻煩不斷，搞定麻煩者將獲豐厚獎賞。", progress = nil, completion = "總算少了一件事要煩心了。", rewards = "您會收到：\n\n夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][85649] = {title = "探究者之喚：水力發電壩", objective = "在任一難度下完成水力發電壩探究。", description = "注意\n\n水力發電壩的運作急轉直下，需要有志之士前去處理。", progress = nil, completion = "你在水力發電壩的行為值得嘉獎。", rewards = "您會收到：\n\n夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][85653] = {title = "小心摸索", objective = "在海妖島周邊的海域中尋找更多黃水晶。", description = "你的那枚戒指引發了不小的騷動，不是嗎？它背後的歷史…維酷人？某個名叫賽斯的人？\n\n我知道你和巴古斯透過偵察小島，釋放了戒指的更多潛能，不過…你也許該把注意力轉向大海？\n\n帶著你的戒指到海裡，看看會發生什麼事。帶著你的所有發現回來找我。我或許是個新手，但我能夠把你帶回來的東西拼湊在一起。", progress = "寇拜斯會讓任何人罹患深海恐懼症。你很勇敢，居然還能在海裡尋找寶石。", completion = "&lt;學徒坦莫拿走三個歌唱碎片，懷疑地看著它們。&gt;\n\n你看得出這裡面蘊藏著力量。我…希望可以安全地融合它們。可能什麼事都不會發生。也可能發生任何事。\n\n&lt;學徒坦莫拿出一瓶黏稠的金色液體，開始將它們拼在一起。液體發出光芒，黃水晶再次融為一體。他將修復的黃水晶交給你。&gt;\n\n很驚奇嗎？別這樣。老實說，這是很貴的膠水。希望這枚戒指能讓我們進一步了解這座小島！", rewards = "您會學到：\n\n海居者的祝福\n\n下列法術會施放在您身上：\n\n開火!\n\n您還會收到：\n\n原始歌唱黃水晶祝焰鐵"}
MultiLanguageQuestData['tw'][85654] = {title = "風馳電掣", objective = "取得足夠的祝焰鐵，以便測試N.U.K.U.L.A.R目標標定器和TR-06打擊者。", description = "哇，<name>。這不就是營地的大家都在講的東西。\n\n<狄迪抓住你的手，仔細觀察你的戒指。>\n\n你手指上的那枚戒指真的很特別，你真的不想換一個？\n\n<狄迪抬頭對你眨眨眼。>我只是在開玩笑，我們來看看能用它做什麼吧！\n\n找到我們一直在找的那種魔法金屬，帶給我足夠的量，我會試著讓你穿上那裡的打擊者。\n\n你的戒指應該能提供需要的動力給它，然後引起一些騷亂！", progress = "你順利找到那種鐵礦，並且製造出一些騷亂了嗎？", completion = "真高興看到還有其他人跟我一樣唯恐天下不亂。&lt;狄迪擦去眼角的一小滴淚。&gt;", rewards = "您會學到：\n\n超級充能\n\n下列法術會施放在您身上：\n\nAnti-Gravity Well\n\n您還會收到：\n\n原始歌唱黃水晶祝焰鐵"}
MultiLanguageQuestData['tw'][85655] = {title = "釋放她的力量", objective = "裝備賽斯的飾環，與海妖島上的生物搏鬥，在戰鬥中激發它的隱藏能力。", description = "你和巴古斯找到的這枚戒指帶你們跑遍整座小島，了解它的歷史，並找到它的寶藏。\n\n這枚戒指幫助你進行探索，以及戰鬥。不過，我們從未將戒指的力量真正發揮到極限。\n\n也許該來進行一些正式的測試。如果我們冒一點險，說不定可以發掘出它的更多潛能。\n\n去尋找實力高強的對手，對戒指進行測試。帶著你的觀察結果回來找我。", progress = nil, completion = "真是驚人的發現。不過，我覺得還有更多有待發掘的地方。", rewards = "您會學到：\n\n賽斯的微風\n\n您還會收到：\n\n原始歌唱黃水晶祝焰鐵"}
MultiLanguageQuestData['tw'][85656] = {title = "歌唱強盜捕捉者", objective = "抓到三個竊賊。", description = "你似乎抓到用那枚戒指的訣竅了，對嗎？也許你可以用它幫上我的忙。\n\n我們這裡的補給品，尤其是黃金和祝焰鐵，一直在消失！\n\n<坦莫貼著你低聲說話。>\n\n我通常不會做出這種假設，阿拉希人是值得信任的傢伙，不過數量一直在增加，我在想，我們當中是不是出了內賊。\n\n看看你能不能揪出他們。他們實在太明目張膽了。相信你一定能抓到現行犯！", progress = "記得錢不露白。竊賊似乎無所不在。", completion = "那真是一個荒唐至極的故事。不過，有鑑於發生在這座小島上的種種怪事，我只能說我一點都不意外。", rewards = "您會學到：\n\n海妖竊賊\n\n您還會收到：\n\n原始歌唱黃水晶祝焰鐵"}
MultiLanguageQuestData['tw'][85657] = {title = "賽斯會很驕傲", objective = "乘坐穿天者飛行，看看賽斯的飾環能不能為你抵擋強風。", description = "這裡的風暴很恐怖不是什麼秘密。\n\n但是！我不認為我們給了那裡的那枚戒指與風暴公平對決的機會。我是說，那東西可以讓你游得跟魚一樣快，憑空製造出龍捲風，甚至揪出垂涎魔法寶箱的隱形人！那它一定有辦法對付有點惡劣的天氣，對吧？\n\n乘著我的氣球上去，看看你能不能利用你的那枚戒指，讓氣球保持穩定。說不定我們能找到待在空中的秘訣！", progress = nil, completion = "看來那枚戒指的確能對付強風和風暴！\n\n你應該不會想把戒指借給某個女孩，對吧？有了那枚戒指，我就能贏下一些比賽…我們可以成為合作夥伴！得到的獎金我們三七分成。不然四六分成？噢，那就五五分成，不能再多了。\n\n還是不要？好吧，那就算了。至少我做了一場美夢。", rewards = "您會學到：\n\n海妖之翼\n\n您還會收到：\n\n原始歌唱黃水晶賽斯的飾環祝焰鐵"}
MultiLanguageQuestData['tw'][85664] = {title = "探究者之喚：夜暮聖所", objective = "在任一難度下完成夜暮聖所探究。", description = "呼叫支援！\n\n黑夜教團似乎在名為夜暮聖所的地方設立了基地。\n\n阻止他們的行動乃是當務之急。", progress = nil, completion = "我聽說某人終結了黑夜教團的詭計，幹得好。", rewards = "您會收到：\n\n夥伴經驗值共鳴水晶"}
MultiLanguageQuestData['tw'][85666] = {title = "探究者之喚：迴繞地道", objective = "在任一難度下完成迴繞地道探究。", description = "需要幫手\n\n據說奈幽蟲族在迴繞地道內展開了大規模軍事行動。\n\n阻止他們的行動並協助達拉然墜毀的生還者！", progress = nil, completion = "你辦到了！這應該能讓地表上的部隊鬆一口氣。", rewards = "您會收到：\n\n卡吉"}
MultiLanguageQuestData['tw'][85667] = {title = "探究者之喚：深淵堡", objective = "在任一難度下完成深淵堡探究。", description = "織絲者的指示\n\n有人在名為深淵堡的地方進行黑暗的行動。\n\n我希望這些行動遭到制止。", progress = nil, completion = "即使是你這類生物，本次表現依舊令人激賞。", rewards = "您會收到：\n\n卡吉"}
MultiLanguageQuestData['tw'][85678] = {title = "修理自己的裝備", objective = "與軍需官里赫特交談，然後選擇「修理所有物品」來修復你受損的裝備。", description = "你的裝備看起來不像你上次出行時那麼好。\n\n與軍需官里赫特交談來進行修理。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][85710] = {title = "縮小時間到", objective = "縮小並收集10個石背漫遊者。", description = "我們試著為這些石背進行醫療檢查，但牠們似乎因為…不想這麼做而變得十分暴躁。\n\n維娜里提供了這個縮小裝置來協助我們。去幫我收集一些吧。", progress = nil, completion = "啊！這樣的大小就好處理多了。不知道為什麼，牠們看起來怪可愛的。\n\n謝謝你。我會進行檢查，之後就會把牠們放回去。", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][85711] = {title = "自發性的回饋", objective = "送食物給飢餓的顧客。", description = "愛麗絲回來了，比起變成<小聲說>老鼠之前，她現在的廚師功力突飛猛進。\n\n不過，我說了不算。來，分發一些食物，從顧客那裡得到最直接的評價吧！", progress = nil, completion = "真神奇，不是嗎？\n\n我不認為她想這麼快就變回來，至少在她進一步提升個人能力之前。不過我們已經有紅莓解藥，隨時都能把她變回來。再次謝謝你。", rewards = "您會收到：\n\n點點共鳴水晶勇氣石幽坑城集團"}
MultiLanguageQuestData['tw'][85715] = {title = "需要深思", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][85716] = {title = "布滿符文的長矛", objective = "將布滿符文的長矛交給漂流物淺灘的安格菈。\n\n已提供物品：\n", description = "<一根布滿複雜符文的長矛。安格菈或許會對這件武器感興趣。>", progress = nil, completion = "這實在太驚人了！只要仔細研究上面的符文，一定能學到很多東西。", rewards = "您會收到：\n\n祝焰鐵"}
