MultiLanguageQuestData['tw'][85960] = {title = "零工：迷失在非表象中", objective = "在苦痛田野從非表象之境救出8名迷失的哥布林。", description = "有些被暗融強迫去採血場工作的員工一直沒有回家。\n\n我們收到的報告指出，他們可能是在某種「非表象之境」中迷失了。顯然這和那灘巨大的血池有關。\n\n聽起來這份工作適合比我更無關緊要…我是指經驗豐富的人士。", progress = nil, completion = "不錯嘛，不過他們似乎有些不太對勁，如果你懂我的意思。\n\n為此我要扣你一點薪資。畢竟商品受損了。", rewards = "您會收到：\n\n戰爭火花機械鑄造護手廢料線圈之握叛亂尖刺之握閃線裹手寶庫鑰匙裂片共鳴水晶共鳴水晶共鳴水晶共鳴水晶"}
MultiLanguageQuestData['tw'][85961] = {title = "布局棋子", objective = "到佐戌瞰臺找暗域行者。", description = "在這裡的西北方有個小島，名為佐戌瞰臺。我的斥候們一直在找進入法力熔爐歐美加的方法，那裡是我們阻止『吞盡者』歸來的關鍵。\n\n幸運的話，他們應該已經找到一條安全的通道了。", progress = nil, completion = "我希望我的斥候已經找到安全進入法力熔爐的途徑。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][85962] = {title = "零工：非表象材料", objective = "在苦痛田野收集10份非表象生長物。", description = "拜那些還留在原地的黑血所賜，鳴響深淵正在發生各種古怪的事件。\n\n而有瘋狂和變異在的地方，就會有機會！\n\n過去那裡，看看你能不能找到一些可怕但或許有利可圖的材料。", progress = "試著別在把東西送回來之前發瘋，好嗎？", completion = "我確定研發部的弟兄們一定能用這些…奇怪的東西做出點什麼。\n\n…你有聽到低語聲嗎？", rewards = "您會收到：\n\n共鳴水晶共鳴水晶共鳴水晶共鳴水晶"}
MultiLanguageQuestData['tw'][86151] = {title = "自斷後路無面者面具", objective = "把自斷後路無面者面具放回恐怖幻象裡的祭壇。", description = "背井離鄉的戰士總是步步為營，尤其是當她遠離自己原本的世界的時候。虛無讓這份無常化成現實，稍有差錯，就可能讓人墜入深淵或萬念俱灰。", progress = "把自斷後路無面者面具放上祭壇。", completion = "如果你願意踏足，自斷後路的危險道路將向你開放。", rewards = nil}
MultiLanguageQuestData['tw'][86152] = {title = "蠻勇無面者面具", objective = "把蠻勇無面者面具放回恐怖幻象裡的祭壇。", description = "這位獵人無意領導眾人，而是希望隨時都有挑戰。他以敏捷手勢指揮盟友，而且從不逃避與敵人近身交鋒。他所展現的力量不亞於我的其他僕從，甚至更加致命。將這個面具送回蠻勇祭壇，在對手的攻勢越來越猛烈的時候，驗證你的決心。", progress = "把蠻勇無面者面具放上祭壇。", completion = "只要你夠有勇氣，蠻勇的道路就會對你敞開。", rewards = nil}
MultiLanguageQuestData['tw'][86153] = {title = "黑暗幻覺無面者面具", objective = "把黑暗幻覺無面者面具放回恐怖幻象裡的祭壇。", description = "這些魔導師扭曲其魔法以操縱和征服世界。為了追求更大的力量，他們不斷深入虛無的領域。在追尋的過程中，這名魔導師意識到，想像世界的深處埋藏著真正黑暗且恐怖的事物。", progress = "把黑暗幻覺無面者面具放上祭壇。", completion = "如果你選擇投身其中，處於理智邊緣的風險將會顯露。", rewards = nil}
MultiLanguageQuestData['tw'][86154] = {title = "痛苦無面者面具", objective = "把痛苦無面者面具放回恐怖幻象裡的祭壇。", description = "交換秘密，交換謊言，暗中行事，這是所有間諜大師的拿手好戲。他失去的熱情和感情都已不復存在，在他自身的職責和對上位者的忠誠下消失殆盡。除了痛苦，什麼也不剩。痛苦是最恰當的導師和工具，也是虛無最熟知的事物。如果你有勇氣感受千變萬化的痛苦，就送回我的面具。", progress = "把痛苦無面者面具放上祭壇。", completion = "我承受的瘋狂與折磨還不夠，歡迎日後召來更多痛苦。", rewards = nil}
MultiLanguageQuestData['tw'][86155] = {title = "長夜無面者面具", objective = "把長夜無面者面具放回恐怖幻象裡的祭壇。", description = "想要來到這裡，需要的是無與倫比的耐性，以及老練冒險者的武力。然而，長夜將至，隨之而來的，還有我們最終的征途。那些對抗永恆暮光的人終將徒勞無功，因為在最漫長的夜裡，他們將永遠在理智邊緣掙扎。", progress = "把長夜無面者面具放上祭壇。", completion = "朝最漫長的夜邁出一步已經讓你喪失一部分理智。你願意賭上你剩下的理智，進行徒勞無功的努力嗎？", rewards = nil}
MultiLanguageQuestData['tw'][86156] = {title = "出手相助", objective = "資助海妖島指揮圖上的事件10次，並殺死目標來完成一個事件。", description = "你。再來一次。可能會有我們還沒看到的好東西。\n\n設法進入那些洞穴，看看裡面有什麼！", progress = "你調查過那個洞穴了嗎？還沒？那還不快去！", completion = "那未免太簡單了。我們應該多來幾次！", rewards = "您會收到：\n\n祝焰鐵"}
MultiLanguageQuestData['tw'][86174] = {title = "特殊任務：風暴正在醞釀", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86177] = {title = "零工：由浪潮供應", objective = "沿著卡迦灣收集5個閃亮的財寶。", description = "你看起來是不介意把手弄髒的類型。有興趣來場小小的尋寶嗎？\n\n據說有一艘船在離卡迦灣不遠處爆炸。去到海岸，看看海潮帶來了什麼。\n\n畢竟，「誰找到就歸誰」是哥布林社會的基本原則之一。", progress = "記得帶你自己的鏟子。我從不提供任何補給，這是我永遠不會履行的責任。", completion = "大豐收啊！\n\n別擔心，我會把戰利品分給你一份的。", rewards = "您會收到：\n\n戰爭火花機械鑄造護手廢料線圈之握叛亂尖刺之握閃線裹手鍍金戰刃鍍金之劍共鳴水晶共鳴水晶共鳴水晶共鳴水晶"}
MultiLanguageQuestData['tw'][86178] = {title = "零工：淨灘", objective = "在卡迦灣擊殺10個激動的卡迦元素生物。", description = "風險投資公司是時候來賺取一點好名聲了。\n\n我們打算雇用像你這麼有效率的工人，去清理卡迦灣。\n\n你可以去那裡幫我們除掉一些…呃…失心瘋的卡迦元素生物嗎？我們會給你一些很實惠的補助。", progress = nil, completion = "多謝幫忙，夥計。\n\n錢多事少是最好的。", rewards = "您會收到：\n\n機械核心增幅器鍍金長矛鍍金寬劍鍍金步槍鍍金之刃鍍金之錘鍍金鬥棍鍍金小刀鍍金凶器怪怪屋鏡片共鳴水晶共鳴水晶共鳴水晶共鳴水晶"}
MultiLanguageQuestData['tw'][86179] = {title = "零工：意外之喜千載難逢", objective = "在卡迦灣的幸運一擊礦場放置6根支撐樑。", description = "你知道卡迦灣那裡有個幸運一擊礦場吧？當初那裡是倉促開發的。暗融並沒有給風險投資公司足夠的時間加固那個地方。\n\n簡而言之，如果不做補強，礦場有很高的機率崩塌。那對任何人都不是好消息，尤其是對於我的錢包。\n\n你可以去那裡一趟，補強礦場的一些支撐樑嗎？這樣應該能暫時撐一下。", progress = nil, completion = "那樣應該能為我們爭取一些時間。\n\n做得好，朋友。", rewards = "您會收到：\n\n戰爭火花可能隱形披風可能隱形披巾寶庫鑰匙裂片共鳴水晶共鳴水晶共鳴水晶勇氣石"}
MultiLanguageQuestData['tw'][86180] = {title = "零工：感染之水", objective = "在卡迦灣從卡迦刺喉鯊魚那裡取回被吞掉的卡迦邁。", description = "我的工人本來應該從祖達薩送來一些卡迦邁，不過運輸工作顯然出了差錯，有隻鯊魚吞掉整個箱子。\n\n我試著向保險公司索賠，但他們拒賠。所以我們別無選擇，只能自己找回那批卡迦邁。\n\n有興趣獵鯊魚嗎？", progress = "你覺得那些鯊魚最後可能會開口說話嗎？我有點想看會說話的鯊魚。", completion = "做得漂亮，&lt;name&gt;。現在我可以不用寫那麼多報告了。\n\n…在你把那隻鯊魚開腸破肚後，你洗過那些卡迦邁，對吧？", rewards = "您會收到：\n\n戰爭火花機械鑄造披肩機械鑄造頭盔機械鑄造護手廢料線圈肩衛廢料線圈之握叛亂尖刺肩冑叛亂尖刺頭盔叛亂尖刺之握閃線肩墊閃線裹手寶庫鑰匙裂片\n                            顯示 4 更多                        共鳴水晶共鳴水晶共鳴水晶勇氣石"}
MultiLanguageQuestData['tw'][86182] = {title = "鬼魂剋星", objective = "在凱瑞西的離繫空間中收集10個石背精華。", description = "我一直在研究綠洲控制臺，我相信我也準備好下一步了。因為這涉及到毀滅，讓我直覺就想到你。\n\n我想請你用相位導體來進入凱瑞西的離繫空間，並取回幽靈石背的精華。你回來之後我再跟你說明內情。", progress = "如何？你成功了嗎？", completion = "太好了。\n\n現在就復活死者吧。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86183] = {title = "眾神之力", objective = "協助維娜里用她的機器在綠洲製造生命。", description = "今天，我們要創造生命。\n\n假設我的計算是對的…當然是了，那我們就能利用你收集到的精華，搭配我們蒐集的資料，創造出新的石背。", progress = nil, completion = "&lt;name&gt;，做得好。這絕對是有史以來第一次。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86184] = {title = "縮小行動回歸", objective = "縮小並收集10個石背漫遊者。", description = "機器有其作用，但石背必須開始繁殖，牠們才能存續下去。到目前為止，牠們還沒展現出打算這麼做的傾向。\n\n帶著這個裝置，用它來收集石背做測試。奧姆塔拉會負責評估資料。", progress = "你按照要求把石背帶來了嗎？", completion = "謝謝你。我們從中收集來的資料可說是極為珍貴。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86185] = {title = "自由競速", objective = "與石背首領競速。", description = "為了幫助石背交配，我跟維娜里和奧姆塔拉談過了。\n\n石背顯然會進行比賽來展現雄性氣概。\n\n跟石背首領來一場比賽吧，最糟的情況就是你們都有運動到。最好的結局就是他能成功找到配偶。", progress = "競速的結果如何？", completion = "啊！真是一場刺激的比賽，&lt;name&gt;！\n\n你有偷偷許願嗎？或許這樣就能贏了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86186] = {title = "超級嗅聞者", objective = "前往卡茲阿爾加，到阿茲-卡罕特的姆瑪爾尋找一隻願意為綠洲提供協助的鼴鼠人。", description = "石背似乎沒有分泌正確的賀爾蒙，才導致牠們無法繁殖。\n\n我們認為這是靜滯後的副作用。這個科技從未在這麼長時間過後進行測試。直到現在。\n\n赫米特告訴我，艾澤拉斯有稱為「鼴鼠人」的生物，他們在這方面很有研究。從阿茲-卡罕特帶一個來給我吧。你可以用我的傳送門快速抵達那裡。", progress = nil, completion = "真會講價！那就來進行交易吧！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86187] = {title = "盡最大努力收集小東西", objective = "在拉克-亞緒和鄰近區域收集50個蟲塊。", description = "<name>，你是位精明的協商者。真是太有趣了！我會開始打包。你去幫我收集一些蟲塊，好嗎？", progress = "進展如何？", completion = "這就對了！這正是我在找的東西。希望你沒有碰上太多麻煩！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86188] = {title = "更多蘑菇", objective = "在拉克-亞緒和鄰近區域收集8個拉克-亞緒蘑菇。", description = "可憐的加爾里需要能在我離開的時候獨當一面。你找到的蘑菇可以幫到他。\n\n暫時先準備八個吧。最後一個我們之後再來想要怎麼辦！", progress = "拿到蘑菇了嗎？", completion = "很好。非常好！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86189] = {title = "真菌入侵", objective = "在沃許蟲巢殺死10隻怪物。", description = "我要派你去一個有點可怕的地方，但我很確定你能搞定阻攔你的一切事物！\n\n你可以去清掉一些生物，讓加爾里以後收集原料的時候輕鬆一點嗎？", progress = nil, completion = "奈幽蟲族我還可以接受，但那些東西…\n\n那些東西真的嚇死我了。幸好牠們死光了。呼！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86190] = {title = "一個搞定一切的蘑菇", objective = "在沃許蟲巢中收集一個沃許蘑菇。", description = "我們一直在調製一種新的氣味來滿足在地人的品味，但我們一直缺最後一種材料。\n\n那是一種來自沃許蟲巢的稀有蘑菇。把它拿到手，加爾里就可以在我不在的時候調好香氛了！", progress = "你拿到那種蘑菇了嗎？", completion = "喔喔，沒錯。就是這個。這就是會徹底帶來變革的氣味！做得好，&lt;name&gt;！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86191] = {title = "後聞有期", objective = "在凱瑞西的綠洲與魯巴恩和維娜里會面。", description = "嗯。我想這就是全部了。我準備好去冒險了！", progress = nil, completion = "&lt;name&gt;，你帶來了一位…很不尋常的朋友。雖奇怪，但很有魅力。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86192] = {title = "給牠們躺的骨頭床", objective = "從凱瑞西附近收集8個生物骨頭，並在綠洲把它們堆成一堆。", description = "我剛才在那裡和奧姆塔拉討論。很顯然，石背會為生產用的巢穴收集骨頭，說來好笑，畢竟牠們是草食性生物！\n\n牠們通常會從死去的動物身上收集骨頭，但我們的秘境裡沒有屍體供牠們收集。可以幫我從綠洲外的生物身上收集骨頭嗎？牠們會很感激你的，我也是！", progress = "你按照要求搭建好巢穴了嗎？", completion = "謝謝你，&lt;name&gt;。雖然我完全想不透這怎麼可能會舒服，但畢竟我不是石背，這是理所當然的。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86193] = {title = "一命換一命", objective = "關閉機器。", description = "我們來遲了！這個儀式能自行維持，會不斷吸收能量直到機器超載。如果失效連鎖反應開始，塔札維許、秘境…所有地方都將陷入危險。\n\n如果我們能移除灌注器，那股能量應該會在造成災難前自行消散。但它的力量太強了，你一接近就會被撕裂，我自己也沒有足夠力量完成這件事…\n\n解開我的束縛。我會用我的能量保護你，應該足以讓你靠近那台機器。", progress = nil, completion = "你還好嗎？我試著幫你擋下爆炸衝擊。\n\n&lt;奧姆塔哈的身影時隱時現。&gt;\n\n對不起，我耗費太多能量了…我只需要休息一下。", rewards = "您會收到：\n\n共鳴水晶勇氣石凱瑞西信託同盟"}
MultiLanguageQuestData['tw'][86194] = {title = "愛的香氣", objective = "讓12隻石背漫遊者染上費洛蒙。", description = "我去幫你檢查了一下石背，你的仲介者朋友是錯的！\n\n石背散發的是愛的氣味，只是還沒有強烈到可以蓋過凱瑞西的乾燥空氣。一點都不行！我調製了一些費洛蒙，應該能幫牠們解決問題！\n\n拿著噴霧對石背噴一下吧。這樣就能讓牠們開始「辦事」了！", progress = nil, completion = "給它一點時間發酵，&lt;name&gt;。愛情可不是兩三下就能催生出來的！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86195] = {title = "石背足球", objective = "跟石背幼獸玩的同時，接球10次。", description = "我…我的老天。我從沒想過會有這一天。新的石背誕生了！\n\n我一直都在做非入侵性的標準醫療檢測。不過，我還需要測試一下牠的協調性。我觀察到牠一直追著這顆球跑。不然就請你丟一下，觀察結果如何吧？", progress = "小石背有對球做出反應嗎？", completion = "生命徵象良好，協調性也比我預期的好上許多。謝謝你陪小石背玩…呃，我是說測試牠的協調性。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86196] = {title = "給我燃料", objective = "為奧姆維克收集焰花花粉。", description = "<name>，謝謝你趕來。\n\n在試圖改造凱瑞西的地貌時，我們面臨了很多危險，其中包含將秘境視為便利的能量來源而聚集過來的生物。\n\n斯賓荷斯秘境就深受其害。我已經有解決辦法，不過，需要你幫忙進行準備。", progress = "你幫我收集到足夠的花粉了嗎？", completion = "太完美了，&lt;class&gt;。透過我們的設備，就能讓這種不起眼的植物解放潛在力量。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][86200] = {title = "給我火焰", objective = "將焰花花粉加工成燃料。", description = "現在，我們必須把這種焰花花粉加工成燃料。有了這種燃料，這些害蟲的死期就到了。", progress = nil, completion = "太棒了。希望你已經準備好讓這些惱人的生物嘗嘗仲介者的怒火。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][86201] = {title = "看看我的除蟲大法", objective = "使用火焰噴射器，強迫吸飽飽的潛伏者離開秘境，然後消滅牠們。", description = "既然這些焰花花粉已經加工完成，我們可以放火燒死斯賓荷斯秘境的害蟲了。", progress = nil, completion = "秘境防護罩的完整度逐漸回到正常值。我就知道你們這個種族對火焰情有獨鍾，&lt;race&gt;。", rewards = "您會收到：\n\n共鳴水晶勇氣石凱瑞西信託同盟"}
MultiLanguageQuestData['tw'][86203] = {title = "水閘行動", objective = "畢爾果絲要你在水閘行動中與基澤‧巨電對峙。", description = "我透過情報得知，暗融勢力入侵了鳴響深淵的水力發電壩。他們掌控了發電機，並把電力改送到其他地方去了。\n\n我們不知道他們的目的為何，但我不是很想知道。\n\n終止他們的行動，我會給你你應得的獎賞。", progress = nil, completion = "議會守衛聽到水力發電壩回到土靈的掌握之中一定會很高興。\n\n幹得好，外來者。", rewards = "您會收到：\n\n斷裂絲線表揚共鳴水晶多恩諾加議會聖落之地阿拉希深淵集會"}
MultiLanguageQuestData['tw'][86204] = {title = "解放幽坑城：敗者一家", objective = "於解放幽坑城中擊敗閃亮亮大王加里維克斯。", description = "自從加里維克斯忘掉自己的出身之後，他就成為了幽坑城的汙點。\n\n加里維克斯一直在壓榨弱小，他的貪婪和總是在尋找「下一個絕佳生意」的行為只會讓他的壓榨更嚴重。為了自己追尋權力？沒有這種事！真正的權力掌握在人民手中。\n\n我們去讓加里維克斯嘗嘗正義的滋味吧，<name>。", progress = nil, completion = "我不敢相信…", rewards = "您會收到：\n\n附魔符文幽坑城紋章虛無之觸勇氣石共鳴水晶幽坑城集團"}
MultiLanguageQuestData['tw'][86261] = {title = "心繫更安全的海岸", objective = "輕撫最忠實的朋友。", description = "<一看到你走進營地，這隻髒兮兮的狗突然變得很活潑。看到幫他找到心愛玩具的人那張熟悉的面孔後，他不斷搖著尾巴。\n\n頸上的褪色狗牌上寫著：「公爵」。\n\n自從庫爾提拉斯人失蹤後，他似乎就一直在這裡，順利在這座多災多難的島上存活下來。\n\n「公爵」熱切地盯著你，用鼻子碰碰你的手，希望你摸摸他。>", progress = nil, completion = "&lt;馬馬杜似乎想跟你離開這座島，展開新的冒險。\n\n他嘴裡咬著他心愛的玩具，開心地搖著尾巴。\n\n希望這是一段美好友誼的起點。&gt;", rewards = "您會收到：\n\n馬馬杜"}
MultiLanguageQuestData['tw'][86271] = {title = "理智之眠", objective = "在鳴響深淵的洞穴裡搬運癱瘓的工人。", description = "看來又有人出事了，是嗎？\n\n我告訴你，這些黑血挖掘場吞噬工人的速度比我雇用的速度還要快！每過一天，我的一個員工就會嚇得瑟瑟發抖，口中充滿在土裡看到觸手的胡言亂語…\n\n帶他去見我的人史提區夫，就在那裡的洞裡。他正在製作某種「解藥」。\n\n看看他能不能幫上這個可憐蟲的忙。", progress = nil, completion = "這是今天的第三個。\n\n情況越來越糟了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86272] = {title = "對抗黑血", objective = "在鳴響深淵幫助史提區夫減輕哥布林的症狀。", description = "黑血？噁心的東西。幸好我戴了口罩。沒有人應該在那種糟糕的環境中工作。\n\n它會滲入你體內，讓你頭腦不清。有些人會頭暈目眩，看到幻覺。有些人甚至會長出奇怪的鱗片。一想到就讓我渾身發癢。\n\n而且完全沒有解藥。我們能做的，就是緩解痛苦，稍微減輕一下症狀。\n\n我正在製作「解藥」。它其實只是普通的湯，但他們不知道。\n\n就快「完成」了，不過還差了一些味道。", progress = nil, completion = "雞湯在很多地方都能派上用場。不知道漱口是不是有同樣的功效。\n\n至少雞湯聞起來很香。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86273] = {title = "造訪工坊", objective = "到鳴響深淵，在理智之眠的深處，尋找翠希‧雷轉的工坊。", description = "現在我們只能做這麼多了。\n\n但如果你真的想幫我們徹底解決問題，你得去找當地的工程師談談…呃，翠絲克…還是叫提席。\n\n她把工坊設立在洞穴的深處，貝尼要她不分晝夜地研究某種…「永久的治療方法」。\n\n她是個怪人，但就和刀刃一樣銳利。如果要說誰有機會治好下面的這些人，那肯定是她。", progress = nil, completion = "欸！你看不出來我很忙嗎？\n\n你要幹嘛？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86274] = {title = "自動化解決方案", objective = "在鳴響深淵收集掉在洞穴各處的金屬碎塊。", description = "你大概已經知道了，暴露在黑血中對你的健康有害。那對我們的行動極為不利。\n我們不能一直換工人。不僅成本太高，也不道德。\n\n所以！解決方案是什麼？那就是用我的全自動機器人取代我們的工人。\n\n這些美麗的東西不會受到黑血影響。它們只會一直挖，一直搬，高精度且高效率，而且再也不會有工人生病！\n\n我只是需要更多廢料來把它們拼湊起來。要加入嗎？", progress = "時間很寶…你知道我的意思。", completion = "好極了！這能組好它們，開始正式運作！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86275] = {title = "徵求除蟲專家", objective = "在鳴響深淵的洞穴裡殺死血饗蟲。", description = "好吧，如果你真想幫忙…\n\n在這個洞穴裡，我們很安全，不用擔心黑血，前提是這裡沒有爬滿噁心的血饗蟲。\n\n這種醜陋的小東西一直很喜歡吸血，但牠們現在吸的是黑血！我的直覺告訴我，牠們咬到我們，就會順便散播黑血的毒素。\n\n我無法像這樣工作。每次我在廢料堆看到血饗蟲，都會尖叫。牠們太噁了，我一點都不想被咬，然後開始出現幻覺。\n\n把牠們踩扁，讓我們能安全地繼續工作！", progress = nil, completion = "噁。很噁心，但很有效。我現在可以回去工作了！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86276] = {title = "親臨現場", objective = "到鳴響深淵的苦痛田野部署哥布林機器人。", description = "如果翠希已經有那些機器人，那麼我們就只需要把它們的工作區域標示出來。\n\n到外面去，發射照明彈，然後部署那些錫罐，看看它們是不是真的會工作。\n\n小心常出問題的伺服馬達、冒煙的散熱口…你懂我的意思。\n\n如果它們正常運作？那很好。\n\n如果沒有，嗯…我會把一些工人叫回來，收拾殘局。", progress = nil, completion = "它們有用？我是說，它們當然有用！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86277] = {title = "不再成為「蟲」飼料", objective = "到鳴響深淵的苦痛田野擊殺狂暴眼柄。", description = "我們已經讓機器人開始在田野工作，不過外面還是有不少有血有肉的工人。\n\n必須讓他們能夠安全地回到這裡，但他們卻做不到，一隻流著口水的「巨蟲」纏著他們，因為牠愛吃哥布林的肉。\n\n以下是工作內容：我不想要那東西只是被嚇跑，我要牠消失。到那裡去，追殺那隻成長過頭的「蚯蚓」，確保牠死透了。\n\n別留手，我要看到血流成河。以慰那些被當成午餐的哥布林在天之靈。", progress = nil, completion = "哇，看來你把我的話記在心裡！\n\n事情結束後，記得去洗個澡，好嗎？", rewards = "您會收到：\n\n除蟲專家手套除蟲專家束褲除蟲專家腰帶除蟲專家肩衛勇氣石"}
MultiLanguageQuestData['tw'][86297] = {title = "士氣反映領導能力", objective = "在幽坑城找出負責管理污水企業聯合的哥布林。", description = "幽坑城會吞噬所有美好的人事物。現在拉斯洛遭殃了。我們必須找出現在是誰在負責管理，並想出保護他們安全的辦法。我想我知道該從哪裡問起。", progress = nil, completion = "至少沒有任何哥布林是加里維克斯的下一個目標，但這是暫時的。這會給我們處理黑血的時間。然後我們就能想辦法讓我的族人脫離加里維克斯的魔掌。", rewards = "您會收到：\n\n勇氣石"}
