MultiLanguageQuestData['tw'][86327] = {title = "暴風原野", objective = "在暴風原野與薩拉塔斯會面。", description = "那些荒地居民拿走了那條仲介者的緞帶。我們必須把它奪回來，否則你永遠無法接近迪曼修斯。\n\n他們的嗜血本性真是令人著迷。我覺得我們該設法把他們拉攏過來。我們需要軍隊來應對即將到來的戰鬥，而他們的人數正好夠用。\n\n我們與他們的營地之間有虛無之鏡。那也許能成為操弄的手段，去和那些荒地居民談談。", progress = nil, completion = "迪曼修斯的光環正在撕裂凱瑞西僅存的殘骸。很快，他就會吞噬這個世界最後的一切。\n\n我們阻止他的時間正一分一秒地流逝。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86332] = {title = "能量分配", objective = "在荒地居民營地內外收集並分配收集的能量。", description = "我的族人必須依靠能量存活。我們可以從外設的水晶塔中提取，或是獵殺那些偷取我們資源的能量拾荒者。\n\n我們先收集今天那可憐的一點能量，再分送給我的族人。如果我們真的要並肩作戰，了解彼此的盟友是有幫助的。", progress = "在殘酷的凱瑞西荒地中，唯有生存才是王道。我們必須奪取所需的一切，才能保住未來。", completion = "你的幫助我們銘記在心。靠著那些木箱中的能量，我的族人至少又能再活一天，甚至活得更久。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86339] = {title = "綠洲超載賽道", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86340] = {title = "綠洲超載賽道 - 進階版", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86341] = {title = "綠洲超載賽道 - 逆向版", objective = "滑翔通過檢查環。", description = "飛行穿過標記賽道路線的檢查環。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86342] = {title = "飛騰於凱瑞西之上", objective = "完成「綠洲超載運轉」競賽。", description = "我們曾試著讓卡洛克在綠洲外飛行。或許你對騎乘牠們有興趣？", progress = nil, completion = "太好了。看著卡洛克和你在空中翱翔，實在是太過癮了。\n\n你還真是個騎術精湛的騎士，&lt;name&gt;。", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][86348] = {title = "狐狸災禍", objective = "在凱瑞西的離繫空間中進行相位深潛時，收集10個刺尾精華。", description = "你對石背的問題處理得不錯。那麼刺尾呢？\n\n如果要提高牠們的族群數量，我們就會需要牠們的星界精華來製造新生命。幫我收集一下。", progress = "你拿到精華了嗎？", completion = "你一如既往地一樣可靠。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86349] = {title = "看門蟲精華獵人", objective = "在凱瑞西的離繫空間收集10個看門蟲精華。", description = "刺尾最會狩獵小型生物了。如果要提高牠們的族群數量，我們就要相應地提高看門蟲的數量。\n\n去收集牠們的星界精華吧。你可以使用相位導體來進入離繫空間。", progress = "情況怎麼樣？", completion = "很好。接下來讓我接手。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86350] = {title = "狐狸之香", objective = "讓8隻皇家刺尾染上費洛蒙。", description = "是我最愛的<race>！\n\n我一直在綠洲附近嗅聞東西，也給那些刺尾調製了一些費洛蒙。你可以幫我給牠們來一劑嗎？\n\n等你完成之後就跟奧姆塔拉說一聲，他好像也想做一些測試！", progress = "你把費洛蒙塗到牠們身上了嗎？", completion = "啊，感謝你一直以來的協助。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86351] = {title = "擺好姿勢", objective = "為10隻皇家刺尾做紀錄。", description = "我們給刺尾的食物越來越少了。這很奇怪。牠們應該透過狩獵獲取大部分的食物。\n\n你可以幫牠們拍一些用作紀錄的照片嗎？或許這樣就能看出問題的端倪了。", progress = nil, completion = "牠們完全沒有在狩獵？這太離譜了。我們必須盡快找出解決辦法。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86352] = {title = "尋找一名好作者", objective = "在巨龍群島的蒼藍高地上找赫米特‧奈辛瓦里。", description = "我越來越擔心，我們讓整個生態系統過於平衡了。我們需要找人諮詢。\n\n你讀過一本名叫《荊棘谷的青山》的書嗎？我很喜歡這本書。作者似乎從獵人轉職成保育人士了。別問我為什麼會知道這件事。\n\n不過，這正是我需要請教的兩門學問。去找他吧。我記得他就在巨龍群島的蒼藍高地。用傳送門傳到那裡吧。", progress = nil, completion = "如果你想要我幫你，那你得先幫我。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86353] = {title = "保護年輕一代", objective = "在蕨皮刺藤拯救6個巨牙海民孩童。", description = "這些豺狼人從伊斯凱拉綁架了一些幼童。我正要潛進去救他們出來，但我需要有人協助。\n\n我們分頭行動。兩人總比一人好。如果你看到小孩子，告訴他們在這裡集合。告訴他們是赫米特派你來的。他們認識我。", progress = nil, completion = "幹得好，&lt;name&gt;。\n\n老實說，看到你的時候我倍感欣慰。真不知道我一個人能不能辦到。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86354] = {title = "下猛藥", objective = "殺死棘皮谷和附近地區的豺狼人和其爪牙。", description = "這些豺狼人一直在荼毒這片大地。他們數量過多，讓整個生態系統失去平衡。\n\n我們必須阻止他們，讓這片腐朽的大地復原。", progress = nil, completion = "我們剷除這裡的腐化了。假以時日，大地就會恢復生機。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86355] = {title = "物盡其用", objective = "在蒼藍高地附近收集20份麋牛肉。", description = "凱瑞西是吧？聽起來有點像虛空風暴。\n\n我和巨牙海民相處了好一段時間，盡可能向他們學習。我本該去收集晚餐要用到的肉。如果你幫我辦這件事，我就可以開始打包了。", progress = "一定要切取整隻動物的肉。這樣會比較快。", completion = "這應該能餵飽整座村莊的巨牙海民！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86356] = {title = "永續採收", objective = "在蒼藍高地附近收集12個切碎的木頭。", description = "我想要報答巨牙海民對我的熱情招待。他們有一些需要修理的東西。\n\n你可以幫他們收集一些木材嗎？他們可以自己搞定修理工作，只不過需要有人幫他們收集材料。", progress = "你拿到木材了嗎？", completion = "這對他們的所有修理工程來說應該綽綽有餘了！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86357] = {title = "餵食時間", objective = "在伊斯凱拉外放置一堆肉給當地的巨獺。", description = "當地的巨獺和巨牙海民有著強烈的共生關係，餵食的時間也剛好到了。\n\n你可以餵牠們一些之前採收的肉嗎？", progress = nil, completion = "很好！肚子飽飽，牠們才會快快樂樂。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86358] = {title = "什麼藉口都好", objective = "在伊斯凱拉外撫摸5隻巨獺幼獸。", description = "這會是最艱難的任務。\n\n幼獺需要適應陌生人的觸摸。我…我想請你去摸摸牠們。\n\n雖然很難，但這是必要的。", progress = nil, completion = "&lt;name&gt;，感謝你做出這麼大的犧牲。你在這裡的事蹟絕對不會被遺忘。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86359] = {title = "回到凱瑞西", objective = "回到凱瑞西的綠洲。", description = "好，我準備好出發了。我們要怎麼過去？", progress = nil, completion = "我一直在為這一刻做準備，但我還是發現我有點…緊張。&lt;name&gt;，你可以先離開了。我和作者有很多事想聊一下。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86360] = {title = "驚奇狐狸小姐", objective = "教導刺尾族母狩獵看門蟲掠行者10次。", description = "刺尾沒有在遵照牠們的本能狩獵？\n\n維娜里說過，牠們通常不會把看門蟲視為獵物。我們得教教族母如何狩獵看門蟲！", progress = nil, completion = "如果你跟年輕時的我說，我以後的工作是教動物如何狩獵，我一定會嗤之以鼻。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86361] = {title = "你在跟刺尾玩嗎？", objective = "跟小刺尾玩的同時，接球10次。", description = "我們得確保小刺尾的反應能力呈現最佳狀態，這樣牠們長大之後才能好好狩獵\n\n請帶著這顆球，讓小刺尾追著它跑吧。當然了，這都是出於科學目的。", progress = nil, completion = "非常好，有的時候，玩耍也能發揮和訓練同樣的效果。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86362] = {title = "狐狸都會夢到什麼？", objective = "收集5個血液樣本。", description = "我想收集一些刺尾身體狀況的醫學資料。請幫我收集一些血液樣本。\n\n用這些讓牠們陷入沉睡。當你回收這些飛鏢時，上頭沾有的血液應該就足夠用來取樣了。", progress = nil, completion = "太好了！這正是我需要的。或許你會想在這裡當全職員工？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86363] = {title = "勇氣石的用處", objective = "在卡茲阿爾加、幽坑城和凱瑞西冒險時收集50顆勇氣石，接著回去找庫佐斯並升級一件第3賽季裝備。", description = "我們來到多恩諾加已經好幾個月了，不過關於勇氣石還有很多事有待鑽研。我們發現，在艾澤拉斯以外的地方也能找到它們！這項發現開啟了一個截然不同的研究方向。\n\n有新的研究，就代表我們需要新的供給。幫我拿來一些，我們就能幫你把裝備升級到嶄新的高度。", progress = nil, completion = "我的朋友！我就知道你靠得住。請收下這些東西作為報酬。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86364] = {title = "來自以太的紋章", objective = "透過擊敗獨特的生物、通過團隊副本、完成世界活動或領取寶箱戰利品來取得15個陳舊以太紋章。然後回到多恩諾加找維史康。", description = "太驚人了。單靠勇氣石就可以升級低等級的裝備。\n\n雖說如此，勇氣石也只能做到這麼多了。更強大的裝備會需要用到以太紋章來激發其完整的潛力。這些紋章可以透過多種不同活動取得。以太紋章有四種階級，任務越是危險，獎勵給你的紋章階級就越高。\n\n帶十五個陳舊以太紋章給我，我們就能幫你把一些裝備做進一步的升級。", progress = nil, completion = "真是太棒了。看到你實力變強，真讓人興奮！當然，這都是為了推進我的研究。不過，你的實力還是成長了！", rewards = "您會收到：\n\n赤紅勇氣石"}
MultiLanguageQuestData['tw'][86365] = {title = "紋章轉化", objective = "將15個雕刻以太紋章交給多恩諾加的維史康，然後用它們兌換一袋陳舊以太紋章。", description = "我的朋友，這些紋章真是太神奇了。看來它們可以轉化成不同的階級！\n\n如果你發現自己已經不需要低階的紋章，那麼我可以把它們轉化成更強大的紋章。我也可以把紋章轉化成較低的階級。\n\n我們來練習一下轉化流程吧。這裡有一些雕刻以太紋章。跟我說一聲，我就幫你把它們轉化成陳舊以太紋章。", progress = "如果你弄丟那些雕刻以太紋章，可以從凱瑞西各地的強大生物身上找到更多。我聽說牠們的種類非常多！", completion = "好極了！\n\n請記得，只有在你的能力成長到超出紋章的效用時，我才能把它們轉化成更高的階級，而且這套流程要價不斐。感謝你的協助！", rewards = "您會收到：\n\n赤紅勇氣石"}
MultiLanguageQuestData['tw'][86367] = {title = "幼蟲踐踏", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86369] = {title = "閃亮的財富", objective = "找到另一個碎裂的財富火花。", description = "你來得正是時候，<class>。\n\n<管理者庫勃拿出一塊碎裂水晶。>\n\n這是碎裂的財富火花。在你的裝備上使用像這樣的材料，就能把不錯的裝備變成頂級裝備。\n\n但是，它現在還派不上用場，因為它只不過是一個碎片。如果在冒險過程中，你有幸拿到另一個碎片，把它帶來給我。只要再帶來一個碎片，我就會把這個給你，讓你把兩個碎片結合成一個財富火花。", progress = "你順利找到碎裂的財富火花了嗎？有嗎？還是沒有？", completion = "太棒了！結合這兩個碎裂的財富火花，製造出強大的財富火花。你可以利用自己的製作技能，結合出更多火花。", rewards = "您會收到：\n\n碎裂的財富火花"}
