MultiLanguageQuestData['tw'][86482] = {title = "生命線", objective = "與傑哲爾‧彈指談話。", description = "<當你靠近時，嚙龍幾乎動也不動。牠顯然很虛弱，而且似乎過於瘦小。\n\n也許傑哲爾‧彈指賣的東西能幫助牠恢復健康？>", progress = "<那隻小嚙龍用呆滯的眼睛疲憊地看著你。>", completion = "&lt;那隻小嚙龍狼吞虎嚥地吃下美食。燉肉和用來醃肉的含咖啡因的卡迦可樂似乎讓牠有了活力。\n\n牠目露感激地看著你。\n\n牠會記得你。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86483] = {title = "一口咬下", objective = "從入侵部隊：海盜、納迦或維酷人身上，找到5個肉類口糧。", description = "<當你靠近時，嚙龍似乎認出你，牠的耳鰭晃動，一副很期待的樣子。\n\n牠不只一夜之間長大了，鰭片的顏色也變成海藻綠，近似於你餵牠吃的卡迦可樂燉肉。\n\n牠的爪子下方壓著幾個牠從附近的入侵部隊偷來的肉類口糧。嚙龍一臉期待地看著你。\n\n也許你可以殺死入侵小島的部隊，為牠帶來更多的肉類口糧。", progress = "<嚙龍抓刨地面，然後一臉期待地看著你。牠的眼睛散發出智慧的光芒。>", completion = "&lt;當你靠近時，嚙龍突然變得很活潑，不斷嗅著空氣，想知道你有沒有帶食物來。\n\n一看到你手中的口糧時，牠的嘴巴開始一張一合，期待享用美味的大餐。\n\n飽餐一頓後，小嚙龍躺下來休息，卻向上看著你，彷彿希望你明天再來。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86484] = {title = "暴風壞牌氣", objective = "和蘇琪‧拴鉗交談以進入海怒暴風，並殺死生物，取得風觸神秘的肉。", description = "<當你靠近時，嚙龍似乎認出你，牠的耳鰭晃動，一副很期待的樣子。\n\n牠不只一夜之間長大了，鰭片也變成你昨天餵牠吃的肉的顏色。\n\n牠的爪子下方壓著上次的海怒暴風帶來的海中生物的殘骸。嚙龍一臉期待地看著你。\n\n也許勇闖海怒暴風，殺死那裡的生物，你就能為牠帶來更多肉。>", progress = "<嚙龍抓刨地面，然後一臉期待地看著你。牠的眼睛散發出智慧和飢餓的光芒。>", completion = "&lt;一看到你帶來的肉，飢餓的嚙龍不禁垂涎三尺。你一放下肉，牠就開始狼吞虎嚥，一下子吃得一乾二淨。\n\n牠抬頭看著你，第一次露出尊敬的神情。畢竟，你殺了強大的生物，替牠帶來這頓大餐。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86485] = {title = "忠誠的朋友", objective = "與嚙龍談話。", description = "<當你靠近時，嚙龍似乎認出你，牠的耳鰭晃動，一副很期待的樣子。\n\n牠站在你面前，展示龐大、柔軟的身軀，看似已經長大成龍。牠低頭看著你，巨大的嘴巴輕輕動了動，彷彿做出了某個決定。\n\n牠似乎在等你跨出第一步。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n稜彩嚙龍青綠色嚙龍點心"}
MultiLanguageQuestData['tw'][86486] = {title = "飢腸轆轆的嚙龍", objective = "在海妖島上擊殺生物，找到8個神秘的肉點心。", description = "<當你靠近時，嚙龍似乎認出你。牠的耳鰭晃動，一副很期待的樣子。\n\n牠又餓了，並且嚙龍一臉期待地看著你。牠似乎想吃肉，而且似乎完全不在意肉的來源。>", progress = "<當你靠近時，嚙龍出現騷動，牠充滿智慧的雙眼審視著你。\n\n顯然牠希望你為牠帶來大餐。>", completion = "&lt;你一放下口糧，嚙龍就馬上開始狼吞虎嚥。牠顯然非常餓。\n\n飽餐一頓後，牠顯得心滿意足，並開始昏昏欲睡。你發現牠不會一直這個樣子。也許你明天應該試著再來餵牠。&gt;", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86491] = {title = "殘虐雙煞！正式登場！", objective = "到多恩諾加的爭奪者大門附近與威尼‧斯威茲交談。", description = "注意了，各位格鬥粉絲！世上最凶狠的壞蛋們成群結隊，回來報仇了！這次他們將以「殘虐雙煞」的形式再次回歸！\n\n到多恩諾加的爭奪者大門底下找我，報名參加殘虐雙煞。再一次打倒這些首領。重溫舊夢！\n\n-威尼‧斯威茲您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86495] = {title = "瑞西緞帶", objective = "說服艾蘭里亞，讓薩拉塔斯對你施行變形儀式。", description = "在吞盡之戰期間，我親眼目睹了『吞盡者』降臨後的恐怖景象。凡人無法靠近他在法力熔爐的本體。他就是終焉的熵，而你，只是一具血肉之軀。\n\n薩拉塔斯熟知整個星外暗界的儀式。憑藉瑞西緞帶的力量，她能夠改造凱瑞西人，讓他們得以承受迪曼修斯的力量。\n\n艾蘭里亞不會喜歡這個計畫。你必須說服她！", progress = nil, completion = "她答應了？\n\n艾蘭里亞願意聽你說話，勇士。你確實是我們的救星。", rewards = "您會收到：\n\n勇氣石勇氣石"}
MultiLanguageQuestData['tw'][86496] = {title = "井然有序的設計", objective = "收集50個水晶破裂碎塊。\n\n水晶破裂碎塊只能在海怒暴風期間從海妖島各處的生物身上搜刮到。", description = "<巴古斯拿著一小塊金色水晶的破片。>\n\n就和阿拉希人在聖落之地找到的輻光殘骸一樣，海妖水晶似乎正影響著島嶼周圍的地質基質。\n\n與我們的哥布林同胞不同，我不建議收集我們在島上看到的大型裂片，免得驚動了我們腳下的脆弱洞穴，或是冒犯到阿拉希人。\n\n但這些小型破片有調查的價值。\n\n幫我拿一塊大的回來。是為了…研究用途。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n套裝：覺醒土靈戰衣"}
MultiLanguageQuestData['tw'][86503] = {title = "什麼是殘虐雙煞？", objective = "一邊完成威尼的「殘虐」任務，一邊在殘虐雙煞中獲勝，然後與威尼‧斯威茲交談。", description = "問得好！想知道就照做：去找希姬‧瑪芙交談，報名參加殘虐雙煞對戰。\n\n念在你是新手，讓我給你一份到了那邊可以做的「殘虐」任務清單！\n\n祝你好運！也許我們會在那邊見面。", progress = nil, completion = "我看到你的表現了，相當精采。這是你的獎金。合作愉快。\n\n你隨時都能再次報名。下次我會記得賭你贏。", rewards = "您會收到：\n\n殘虐獎金"}
MultiLanguageQuestData['tw'][86535] = {title = "試運行", objective = "使用傳送器從幽坑城前往多恩諾加。", description = "嘿，你想賺點小錢嗎？\n\n我們跟土靈談成一筆交易，打算在多恩諾加建造一個傳送器。我們可以靠觀光人潮發大財，他們則拿到幽坑城珠寶商提供的破裂、碎裂或賣不出去的高品質寶石。\n\n我剛剛讓這一端的機器開始運作，不過還來不及進行測試。你想試試看嗎？如果你順利從另一端出去，我的同事肯琪會給你報酬。\n\n我們一致同意這會構成口頭免責聲明，好嗎？", progress = nil, completion = "哇喔！我以為羅斯托打算用沙鼠或桃子罐頭之類的東西測試新的傳送器，而不是真正的人。\n\n不過你只有一點點滋滋作響！太好了。\n\n告訴你一個好消息。既然幫了我們這個忙，再順便為你的個人安全危害展現一點誠意，只要需要的話，我們願意讓你免費使用傳送器。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86555] = {title = "幽坑城大恩人", objective = "謝謝你協助幽坑城回到正軌。這是用來答謝你的禮物。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n幽坑城執法者襯墊"}
MultiLanguageQuestData['tw'][86556] = {title = "穿越時光的破碎旅程", objective = "完成5次時光漫遊地城冒險。", description = "破壞者之星以強光照耀大地，將靈魂逼回暗影之中。它不同於天上的任何星體，即便是最強大的英雄，也能讓他們的弱點暴露無遺。在它的影響之下，可能會開啟通往遠方、甚至前往其他時間的新道路。賢者們無法瞭解這個徵兆，但好運往往眷顧英勇之士。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光好物包"}
MultiLanguageQuestData['tw'][86560] = {title = "穿越時光的隱蔽旅程", objective = "完成5次時光漫遊地城冒險。", description = "隱蔽之星在天上閃爍，用它一閃一閃的光芒召來詭異的迷霧覆蓋大地。這顆星辰和迷霧使深沉的暗影降臨大地，隱藏其中的秘密和危險。在它的影響之下，可能會開啟通往遠方、甚至前往其他時間的新道路。賢者們無法瞭解這個徵兆，但好運往往眷顧英勇之士。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光好物包"}
MultiLanguageQuestData['tw'][86563] = {title = "穿越時光的蠻野旅程", objective = "完成5次時光漫遊地城冒險。", description = "殘暴之星照耀大地，威脅著將所有擋路的人踩在腳下。這顆星辰象徵著很多事：原始、熾烈和高貴。在它的影響之下，可能會開啟通往遠方、甚至前往其他時間的新道路。賢者們無法瞭解這個徵兆，但好運往往眷顧英勇之士。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光好物包"}
MultiLanguageQuestData['tw'][86564] = {title = "穿越時光的魔化旅程", objective = "完成5次時光漫遊地城冒險。", description = "腐化之星照耀大地，以燒光一切威脅著所有人。這顆星辰背叛那些追求光明之人，它的紅光帶來晦暗，而非顯露。\n\n在它的影響之下，可能會開啟通往遠方、甚至前往其他時間的新道路。賢者們無法瞭解這個徵兆，但好運往往眷顧英勇之士。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光好物包"}
MultiLanguageQuestData['tw'][86575] = {title = "火箭啟動", objective = "回鳴響深淵的洞穴外找貝尼‧鵝炮。", description = "那個廢料正好是我需要的東西。既然沒了那血饗蟲，我不用再心驚膽顫，就能讓這些機器人正式上線。\n\n在我收尾的時候，你何不去告訴貝尼這個好消息？\n\n他一定想馬上部署它們！", progress = nil, completion = "你幫助提希讓那些機器人正式上線？\n\n太棒了，&lt;name&gt;！\n\n我再也不用煩惱人力調派的事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86584] = {title = "用強制休假震驚他們", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86587] = {title = "前往瑪卓薩斯", objective = "前往暗影之境的瑪卓薩斯，幫維娜里捕捉一些魟魚。", description = "魟魚曾翱翔於凱瑞西的天空。如今牠們那受到虛無之觸的後代遍布綠洲之外的天空，我們手邊已經沒有未受到虛無之觸的活體樣本了。\n\n不過，我知道有一個地方可以讓我們抓到棲息於生態系相同位階的相似生物，那裡就是暗影之境的瑪卓薩斯。使用我的傳送門，幫我找到那種生物。", progress = nil, completion = "是維娜里派你來的？真是太巧了！我正好在找助手。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86588] = {title = "祭儀屠殺", objective = "殺死13個病態祭儀師。", description = "當地的祭儀師對死靈魟魚造成了不少問題。具體來說，是瘟疫問題。\n\n如果你把他們殺掉的話，或許能解決死靈魟魚的問題。", progress = nil, completion = "你還真是個好學徒。\n\n什麼都照著指示做！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86589] = {title = "每天一瘟疫，醫生遠離我", objective = "從死掉的染疫死靈魟魚身上收集6個瘟疫樣本。", description = "祭儀師一直在可憐的死靈魟魚身上測試一種新的疫病。這真是太可惡了…那可是我的工作！\n\n幫我拿來一些死去魟魚的樣本，這樣我應該就能幫還沒死去的魟魚調配解藥。", progress = "你幫我拿到那些樣本了嗎？", completion = "呸！這根本一點都不專業。我看過其他瘟疫造成的膿比這個還噁心！當然，那些瘟疫是我造成的。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86590] = {title = "我根本就不在這裡工作", objective = "收集15個怨恨精華。", description = "有你在這裡太好了，學徒！我來收集當地的怨恨精華。只要一點點就能讓瘟疫變得很有意思。\n\n既然你都來了，那就換你來收集吧！這可是絕佳的學習機會！", progress = "如何？你收集到精華了嗎？", completion = "你真的是個很棒的學徒！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86591] = {title = "拙劣的模仿", objective = "殺死大祭儀師沃拉克斯。", description = "這都是沃拉克斯幹得好事。他跟你一樣，曾是我的學徒！\n\n他正在嘗試複製我的傑作？這算是一種讚美，但手法也太拙劣了。學徒，我會幫你製作解藥，同時，解決他的方法就交給你想了。", progress = nil, completion = "噢，算了。我應該請你帶回他的遺體的。我可以好好利用。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86592] = {title = "針打好打滿", objective = "為5隻鎮靜的死靈魟魚注射。", description = "如果這些魟魚要進行移動，我們應該先幫牠們接種疫苗。\n\n這真是個學習抑制瘟疫的絕佳機會啊，學徒！這種好事可不是每天都有的。", progress = nil, completion = "真高興有你在，學徒。我覺得清除生物裡的瘟疫不太好。這樣感覺不太健康。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86593] = {title = "前往綠洲", objective = "前往凱瑞西的綠洲。", description = "我猜你現在要回去了吧？\n\n能跟你共事真的很快樂，學徒。希望我們很快就能再見。屆時，我一定會準備好一些新實驗給你做。拜託一定要好好照顧這些死靈魟魚！希望牠們能在新家過得開心。", progress = nil, completion = "幹得好。我已經根據隔離程序，把死靈魟魚轉移到中庭了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86594] = {title = "口味獨特", objective = "放置3個食物。", description = "我們正試著找出這些魟魚都吃些什麼。\n\n我手上有一些食物。你可以放牠們出來嗎？我會觀察牠們的反應。", progress = "餵食時間到。快去吧！", completion = "看來牠們幾乎什麼都吃。雜食動物應該很好養。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86595] = {title = "管理責任", objective = "在中庭清理18個凝結團塊。", description = "這些魟魚移動的時候似乎會有些黏液掉落。黏液會凝結，弄得髒兮兮的！\n\n維娜里給了這台真空裝置來協助處理。你可以在外頭的時候順便吸乾淨嗎？", progress = nil, completion = "那些黏液真是頑強。謝謝你幫我除掉！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86601] = {title = "飛鏢射手", objective = "標記5隻好奇的死靈魟魚。", description = "用這些飛鏢標記那些死靈魟魚。我會監測牠們的位置和健康狀態。這些飛鏢也會注入一種死靈魟魚根本不會注意到的止痛劑。\n\n這些仲介者的發明還真厲害！", progress = nil, completion = "標記死靈魟魚的工作辦得不錯。這樣一來我們就能更方便地監測牠們了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86602] = {title = "醫療檢查", objective = "在普萊姆斯秘境中從動物身上收集樣本。", description = "你說你的朋友幫死靈魟魚治好疫病了，但我們需要看一下其他動物有沒有從牠們那裡染上任何疫病。\n\n你可以去採集一些樣本，好讓我們仔細檢查嗎？", progress = nil, completion = "嗯，牠們都看起來很健康。\n\n這有點出乎意料，但是好事！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86603] = {title = "魟魚接球", objective = "跟死靈幼魟玩的同時，接球10次。", description = "你帶回來的其中一隻死靈魟魚似乎懷孕了，而我一整天都在照料她的新生兒。多謝你囉。\n\n也許你不介意幫我測試一下牠的反射能力？", progress = nil, completion = "這份資料能發揮很大的作用，謝謝你。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86604] = {title = "可疑意圖", objective = "收集7份死靈魟魚黏液。", description = "之前赫米特叫你收集的黏液可能對我們有用處。\n\n直接從死靈魟魚的身上收集黏液。你可以用這個鎮定飛鏢讓牠們落入你能收集到的範圍內。", progress = "你收集到黏液了嗎？", completion = "這應該能在綠洲各處的多項計畫中發揮良好的作用。我們感謝你。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86605] = {title = "強化針劑", objective = "套住6隻寧靜的死靈魟魚，並交給馬栓旁的奧姆塔拉。", description = "分析你帶回來的樣本之後，我發現這些死靈魟魚很缺維他命。\n\n維娜里已經洽詢瑪利雷斯，請他準備一些東西了…維娜里在請他清除瘟疫後，又重新準備好了維他命。\n\n請把死靈魟魚聚集起來，好讓我們做第一批測試。", progress = nil, completion = "做得好！我們會監控藥劑，如果有問題我們都會知道。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86606] = {title = "黃金黏液", objective = "在綠洲清理25個凝結團塊。", description = "我們的管理員還沒為死靈魟魚的遺留物做每日清潔。我在塔札維許有許多買家排隊等著買這種材料。他們很急著要，所以收集的工作就交給你了。\n\n帶著這個真空裝置。我會好好報答你的。", progress = nil, completion = "你的努力能讓綠洲獲益良多。謝謝。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86607] = {title = "自由的魟魚競速", objective = "與暴衝的死靈魟魚比賽，並抵達終點線。", description = "那些死靈魟魚對你給牠們的治療反應良好！好到有一隻需要好好放電一下。\n\n你可以幫牠消耗一下體力嗎？", progress = nil, completion = "&lt;name&gt;，你動作真快！比我現在快多了。以後跟速度有關的事就交給你了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86610] = {title = "在虛無的夜晚中", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86618] = {title = "無照駕駛", objective = "學習如何駕駛斷頸者G-99。", description = "好了。在你正式上路、碾過某人之前，我們先來確認你知道如何正確操作。\n\n我們會向你介紹車輛、我們提供的D.R.I.V.E.服務，以及如何有型地開車。", progress = nil, completion = "做得很棒！先說一下，這些車本身沒有保險，如果你惹上任何麻煩，都得自行解決。", rewards = "這個任務線能解鎖：\n\n斷頸者G-99\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][86619] = {title = "劇團", objective = "您會收到：\n\n", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n傑出演員箱子"}
