MultiLanguageQuestData['tw'][86728] = {title = "水閘行動：垃圾處理", objective = "在水閘行動中擊敗基澤‧巨電。", description = "嘿，夥計。我聽說有東西想在鳴響深淵吸取水力發電壩的能量。\n\n從我們的石頭朋友那裡偷東西可不是什麼好事，如果就這樣放手不管，我們可能也會受到波及。\n\n我聽說你對處理垃圾很有一套，而想搞事的那些人對我們來說也是垃圾一個。\n\n幫我個忙，好嗎？不一定要動粗啦，但態度還是要有…相信你懂我在說什麼。", progress = nil, completion = "謝了，夥計。那些企業應該學到一點教訓了。", rewards = "您會收到：\n\n勇氣石共鳴水晶幽坑城集團"}
MultiLanguageQuestData['tw'][86731] = {title = "穿越時光的初始之路", objective = "完成5次時光漫遊地城冒險。", description = "自從你的城市從天上掉下來之後，我學到了更多關於這個世界的歷史，以及像你一樣的英雄面臨過的挑戰。\n\n從歷史中學習是我們保障未來的方式。穿越時間到一切的開端，再次擊倒那些威脅並將這些經歷帶回現實中。", progress = nil, completion = "你從時光穿越的旅途中帶回了什麼經歷？", rewards = "您會收到：\n\n奈幽巴皇家紋章歐維納斯的水銀蛋奈幽寶藏箱"}
MultiLanguageQuestData['tw'][86775] = {title = "拼命賺錢", objective = "完成價格飆升事件至少一次。", description = "偶爾，我們的工作會超過我們的負荷量。你知道那意味著什麼，一大筆錢。在價格飆升的時候來幫個忙，我們一定會好好感謝你的幫忙。", progress = nil, completion = "哇。我們忙得不可開交。多謝幫忙！", rewards = "您會收到：\n\n奶奶的超極紅利共鳴水晶雕刻幽坑城紋章幽坑城集團污水企業聯合"}
MultiLanguageQuestData['tw'][86782] = {title = "中庭醫院", objective = "在中庭與赫米特‧奈辛瓦里會面。", description = "死靈魟魚現在都在中庭，赫米特也去查看牠們了。\n\n他想請你也去一趟。", progress = nil, completion = "很高興你來了。\n\n那我們開始吧？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86783] = {title = "日光下的魟魚", objective = "在普萊姆斯秘境與赫米特‧奈辛瓦里會面。", description = "好。來把這些魟魚送去北邊的普萊姆斯秘境吧！", progress = nil, completion = "準備好來第二輪了嗎？", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][86786] = {title = "虛無獵人", objective = "協助雷歐娜擊敗強大的宇宙蠕蟲，奪取牠的力量。", description = "<name>，虛無擁護所有真相。而最大的真相是，沒有一點幫助，我無法擊敗拉蒙塔。\n\n然後你來了。\n\n我的獵物是名為『貪食者』拉蒙塔的宇宙蠕蟲。牠一開始很小隻，但隨著牠吞噬的虛無實體越來越多，體型和力量也越來越大。\n\n如果能夠擊敗牠，我就能奪取牠的力量。你願意幫我嗎？", progress = nil, completion = "你一直以來幫了我不少忙。作為回報，我允許你一起在這個荒廢、破碎的星球殘骸上創造歷史。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][86800] = {title = "橫掃千軍", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][86801] = {title = "眾人無面者面具", objective = "把眾人無面者面具放回恐怖幻象裡的祭壇。", description = "藉由我們眾人的意志，這個世界沉淪，成為滿足我們神明胃口的大餐。只有沐浴在敵人的鮮血中，才能獲得我們主人的青睞，釋放他們永無止盡的眾生面相。", progress = "把眾人無面者面具放上祭壇。", completion = "永遠飽飲眾人的鮮血。因為我們將會永無止盡，吞噬這個世界。", rewards = nil}
MultiLanguageQuestData['tw'][86820] = {title = "法力熔爐歐美加：迪曼修斯步步逼近", objective = "在法力熔爐歐美加團隊副本中擊敗迪曼修斯。", description = "就是現在，$p。我們必須擊敗這位虛無領主…不惜一切代價。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n附魔符文以太紋章虛無之觸勇氣石"}
