MultiLanguageQuestData['tw'][86961] = {title = "分散風險投資", objective = "找到你潛在的「商業合作夥伴」，然後與他交談。", description = "<這封信的收件人是「打倒加里維克斯的<class>」。你費了一番功夫才撕開封口層層疊疊的強力膠帶。>\n\n嘿，夥計，\n\n你的名聲一直以來都很不錯。不怕捲起袖子，認真做事。有些人真的很看重這一點。\n\n來說正事吧。到我的倉庫找我，也許我們能成為商業上的合作夥伴。", progress = nil, completion = "期待能和你做生意。", rewards = nil}
