MultiLanguageQuestData['tw'][87001] = {title = "懸賞：碎脈", objective = "收集一個運算容器、一個標記矩陣，還有一些虛無融合樹脂，來製作鑰匙。", description = "那個被稱為碎脈的恐怖怪物，藏匿於暗影點的靜止牢籠之中。牠不是被囚禁，而是被當作武器，在我們毫無防備時釋放出來。\n\n製造一把鑰匙，打開碎脈的靜止牢籠，讓所有人都能看見這項威脅。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n碎脈牢籠鑰匙"}
MultiLanguageQuestData['tw'][87008] = {title = "臨時婚禮顧問", objective = "與涅涅和瑞澤克交談。", description = "喂，終於變成一場值得誇讚的婚禮了！\n\n你做得不錯。一切都到定位，就等著我女兒的婚禮正式開始。可喜可賀。\n\n我知道新娘和新郎都想向你道謝，去找他們聊聊吧。", progress = nil, completion = "我的小公主說你做得很好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87010] = {title = "運算容器", objective = "將5根沉重的變數節杖交給工程師奧姆魯夫", description = "要打造一個運算容器可不是件容易的事。\n\n我最近沒做過這種東西，因為我需要用來完成工作的資料節杖被小偷偷走了。你若能把那些節杖找回來，我就能造出來。\n\n提醒你一下！\n\n那些節杖很重，搬運起來得費點力。我可是出了名的常常手滑弄掉它們。", progress = nil, completion = "搬那些沉重的節杖實在很折磨人。還好這種苦差事不是我在做。\n\n不過這一切都是值得的！我已經完成了你想要的物品。", rewards = "您會收到：\n\n運算容器"}
MultiLanguageQuestData['tw'][87284] = {title = "璀璨回音", objective = "將璀璨回音帶去世界之魂記憶，接著釋放它。", description = "<你的手中拿著一個小型的艾澤萊晶岩球體。其光芒穩定且明亮，但它發出的聲音悲戚而渴望。它輕輕地觸動了你。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87285] = {title = "標記矩陣", objective = "從影衛敵人身上抽取8個虛無標記。", description = "標記矩陣必須與影衛所操縱的虛無能量頻率對齊。你必須取得這些能量的樣本。\n\n我設計的拘捕陷阱可以用來捕捉影衛，讓你抽取與他們的腐化能量綁定的虛無標記。\n\n只要有那些標記，我就能製作出標記矩陣，調整你的裝置使其能對虛無驅動的構造物運作。", progress = nil, completion = "別告訴我這個矩陣最後會用來造什麼，我只希望那東西夠驚人！", rewards = "您會收到：\n\n標記矩陣"}
MultiLanguageQuestData['tw'][87290] = {title = "綠洲", objective = "前往凱瑞西的綠洲。", description = "又見面了，<name>。\n\n維娜里請我找你。她要你去綠洲找她。\n\n我之後會跟你會合。我要在這裡處理一些事。", progress = nil, completion = "維娜里沒跟我說她雇用了外界者。好幫手還真難找。我想你應該能派上用場吧。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87291] = {title = "沙拉吧", objective = "收集7份切碎的綠洲植物植株，接著放置3個植物拼盤。", description = "赫米特、奧姆塔拉和我一直在想辦法幫助看門蟲。凱瑞西崩壞的時候，牠們最初的食物似乎都消失了！\n\n你可以去採集一些花花草草，然後幫牠們做成一個小拼盤嗎？", progress = "你餵飽看門蟲了嗎？", completion = "成效真不錯！你對於擺出誘人肉料理有獨到的眼光。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87292] = {title = "盤根麻煩", objective = "解救10隻卡住的看門蟲。", description = "我們的蜜蜂在栽培當地植物這方面有很優異的表現。一些植物幾乎是呈現了爆發性的增長。\n\n不過，有一些看門蟲被這些植物的根纏住了。我一整個早上都在幫牠們解開。你可以幫個忙嗎？", progress = nil, completion = "終於啊！希望小看門蟲不會再惹上什麼麻煩了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87293] = {title = "無恥行銷", objective = "在塔札維許為綠洲尋求贊助。", description = "看門蟲曾是凱瑞西很流行的寵物。\n\n我推測我們可以利用這點吸引塔札維許的人，好為綠洲提供支援和捐款。\n\n我想請你測試一下這個理論。", progress = nil, completion = "看來看門蟲如今的流行程度完全不減當年。太好了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87294] = {title = "世界終於認知的真相", objective = "用自拍相機和多個戴著帽子的看門蟲拍照。", description = "<name>，我有個點子。大家似乎都很喜歡看門蟲，於是我把牠們放大、幫牠們戴帽子，然後將牠們放在風景優美的景點。帶著這台相機，拍一些看門蟲的照片。\n\n如果我想得沒錯，這對幫我們的事業拉贊助有很大的幫助。", progress = "你拍到照片了嗎？別忘了讓你迷人的臉龐也出現在其中。", completion = "這些照片真是太棒了。你的拍照技巧真是了得。我特別喜歡和可愛爵士的這一張。\n\n謝謝你。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87297] = {title = "兌現支票", objective = "在內陸飯店與葛麗菈‧嘶軸交談。", description = "我們還有一件正事要做。\n\n來吧。葛麗菈正在飯店大廳等我們。", progress = nil, completion = "我們已經讓大家都見識到，幽坑城不會臣服於任何人腳下。如果他們打算逼迫我們，就最好做好浴血奮戰的準備。\n\n未來絕不會幸福美滿，但只要是我們自己選擇的，那樣就夠了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87298] = {title = "虛無融合樹脂", objective = "已收集35個虛無顆粒。", description = "虛無融合樹脂不是我平常的專業，但我知道有辦法能幫你做出來。\n\n虛無能量持續滲透我們防護罩的裂縫，污染秘境裡的植物。如果我們剷除那些受污染的植物，或許能取得製作樹脂的原料。\n\n摧毀虛無污化植物，把你找到的虛無顆粒帶來給我。", progress = "快點，你得完成這項任務！", completion = "我擔心污染很快就會再度出現，但這次的處理至少能延緩它幾天的進程！\n\n喔，你看看我憑藉你的努力做出了什麼！", rewards = "您會收到：\n\n虛無融合樹脂"}
MultiLanguageQuestData['tw'][87299] = {title = "這些東西有多古老？", objective = "在激流堡內從紅色黎明士兵身上收集20個證物。", description = "瑪蘭試圖宣布自己是激流堡的新任統治者。雖然軍隊中有些人參與了這次政變，但還是有很多人忠心於達納斯‧托爾貝恩大人的。\n\n但當我們的軍隊出現分裂時，瑪蘭早就準備好對付我們了。她身邊有一群我從未看過的士兵組成的大軍。他們自稱是紅色黎明，但我想他們只是一群透過偷竊補給品來換上我們制服的強盜罷了！\n\n幫助我們擊敗她的手下，然後收集能揭開他們真面目的證據！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87301] = {title = "離繫電池", objective = "與瑪義‧庫會面，進入離繫空間並收集10個離繫能量樣本。", description = "離繫電池難以製造，因為它需要那些從虛空倉庫滲漏至離繫空間的飄渺能量。\n\n不過，我知道有個人能夠採集這種能量。如果他能順利抽取並儲存，再交回給我，我們就有足夠材料來製作電池了。\n\n去找瑪義‧庫，收集這些能量，我們就可以製作電池。", progress = nil, completion = "瑪義‧庫已經充滿了離繫能量。建造一顆電池綽綽有餘。", rewards = "您會收到：\n\n無縛電池"}
