MultiLanguageQuestData['tw'][87321] = {title = "未完之事", objective = "到幽坑城的內陸飯店和蒙特‧加茲魯維會面。", description = "嘿，朋友，你為我…還有為幽坑城所做的一切，真的讓我感激不盡。\n\n<馬林看了斯普琳科一眼，然後再看向你。>\n\n我知道，自從雷吉克和加茲魯維把你帶來這裡，你就一直很忙，聽從我們要求到處跑。不過還有最後的一件事要做。\n\n到飯店和加茲魯維會面。相信他很感激你出手相助。", progress = nil, completion = "謝謝你過來，勇士。\n\n我們還需要再做一件事，才能讓幽坑城回到正軌。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87324] = {title = "一堆虛無之禍寶石", objective = "已收集20顆虛無之禍寶石。", description = "虛無之禍寶石可不是好惹的東西！\n\n影衛把那些寶石藏在離繫空間裡。你得進去找出來。但要小心，可能也有人在盯著這些寶石！\n\n我已經標記了藏寶點的位置，不過附近還可能散落著其他寶石。你能拿多少是抓多少，等你結束時就會有一堆寶石等著你。", progress = "快，趁別人還沒動手前先搶到那些寶石。", completion = "我就知道你做得到。扣掉我的尋寶費後，你還是能留下一堆寶石。", rewards = "您會收到：\n\n一堆虛無之禍寶石"}
MultiLanguageQuestData['tw'][87327] = {title = "挑戰者之韌", objective = "與林多米會面，了解關於強韌鑰石的事。", description = "哇，<name>，你成功通關了一些超級可怕的地城，還活著回來告訴我你的經歷！\n\n來找我，我來看看能不能讓你最具挑戰的鑰石更為強韌。", progress = nil, completion = "既然薩拉塔斯突然卻不可避免的背叛對你而言不成問題，從現在開始，我一定只會給你真的很強韌的鑰石。\n\n不過，你還是可以索取簡單一點的鑰石。畢竟每個人有時候都需要休息一下。", rewards = "這個任務線能解鎖：\n\n強韌鑰石\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][87328] = {title = "真正的恐怖", objective = "與索芮朵蜜交談，協助建立傳送門。", description = "<name>，我們有許多事情要談。虛無的最新威脅讓我們所有人岌岌可危。但我們不是第一次遇到這種情況。過去的遭遇可以給我們線索。\n\n黑血也是同樣的情況。恩若司過去曾用它來誘發幻象。\n\n或許我們可以回到那些時間點，找出反制它的方法。\n\n來吧，協助我建立傳送門。", progress = nil, completion = "非常好！沒時間可以浪費了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87329] = {title = "進入最黑暗的回憶", objective = "與恐怖幻象傳送門互動，重新探索黑血的恐怖。", description = "準備好了嗎？\n\n穿梭時間之道的道路已經開啟，通往我們上次進入幻象的地點。\n\n你的理智將會遭到考驗。第一次嘗試時，你很可能撐不了多久。\n\n傳送門已經準備好了，<name>。進去吧。", progress = "我們必須以過去的知識為基礎。你有什麼新發現嗎？", completion = "沒關係，&lt;name&gt;。你回來了。你做得很好。記住，這只不過是幻象的回憶。\n\n回到過去時，雖然我們會保障你的安全，但當前虛無對我們所有人造成的危害仍然非常真實。", rewards = "您會收到：\n\n錯置的腐化紀念物"}
MultiLanguageQuestData['tw'][87335] = {title = "回音教學", objective = "與阿格穆合作，共同製造恩若司的回音，然後將其插入恐怖幻象沙漏。", description = "我們可以利用錯置的腐化紀念物製造恩若司的回音。\n\n除非你想聽，否則我不想拿那些細節煩你。\n\n不想？喔，好吧。\n\n<阿格穆好像有點失望。>\n\n你擁有的回音越多，我們就能讓你做好更萬全的準備，應付那些幻象。\n\n那我們開始吧。", progress = nil, completion = "你製造的回音越多，所需的紀念物就越多。\n\n如果你想知道製造下一個需要多少紀念物，就跟我說一聲，我會幫你算。\n\n那些幻象極為詭異，不過我知道我們一定會成功，&lt;class&gt;。虛無別想勝過我們。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87337] = {title = "管理責任", objective = "把凱瑞西的綠洲清乾淨。", description = "維娜里很忙碌。當她和奧姆塔拉不在的時候，會由我來指派任務。\n\n綠洲這裡有許多生物。牠們把環境搞得很亂。去好好清乾淨吧。", progress = nil, completion = "很抱歉管理員居然給你這樣的任務。好幫手實在很難找。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87338] = {title = "第一天自我介紹", objective = "讓綠洲的動物好好認識你，並透過綠洲的控制臺查看牠們的狀態。", description = "我們帶來了一些從靜滯中救出的原生物種。我們必須重建牠們的棲息地。\n\n這裡主要有兩個物種，這個控制臺則能監控綠洲裡的物種。我建議在動手之前，先好好認識這些生物。", progress = nil, completion = "你毫髮無傷。非常好。這代表我們可以快點繼續了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87339] = {title = "持續活動", objective = "在凱瑞西的綠洲中進行多項活動。", description = "雖然你會進行一些與你專長相符的任務，綠洲當中還是有一些額外的日常工作需要完成。\n\n這些工作一般會由管理員來做，如果你剛好遇到，我是不會拒絕他人伸出援手的。現在跟未來都一樣。", progress = "你有在認真工作嗎？", completion = "如果想幫管理員的話，四處都可以收集資料、為植物澆水，或是填平土壤。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87340] = {title = "垃圾郵件", objective = "飛越塔札維許上空的檢查環，來分發傳單。", description = "在開始之前還有最後一件事。一件需要你的個人能力才能完成的特殊任務。\n\n不是，跟殺戮無關。是飛行。綠洲需要捐款，而捐款都離不開廣告。\n\n帶著這幾疊傳單，在塔札維許到處分發吧。", progress = nil, completion = "我已經收到好幾筆捐款申請了。做得好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87343] = {title = "懸賞：幻空之毒", objective = "結合晦影表象、能量封裝與一袋帷幕裂片，以製作傳送門鑰匙。", description = "暗影點內的影衛軍隊已經集結在一位神秘勇士「幻空之毒」的麾下。\n\n雖然幻空之毒的存在尚未被證實，但我們已經找到一個據說是他用過的傳送門。\n\n啟動傳送門，揭露幻空之毒的真面目，這樣我們才能與其對峙並將之消滅。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n幻空之毒傳送門鑰匙"}
MultiLanguageQuestData['tw'][87344] = {title = "重大威脅", objective = "完成懸賞，化解城市遭遇的威脅。", description = "塔札維許是座充滿混亂的城市，到處都危機四伏。我們永遠都需要你幫忙。\n\n查看我們的懸賞告示，看看你有沒有能力解決我們最棘手的威脅。", progress = nil, completion = "做得不錯，記得隨時查看懸賞告示，了解最新出現的威脅。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87345] = {title = "懸賞：『扭曲者』希沃斯", objective = "收集塔札維許表象、以太徽印和一顆佐姬塔果。", description = "『扭曲者』希沃斯，塔札維許前任執法官，出身於一個強大的仲介商會家族。\n\n鮮為人知的是，這個家族的權勢來自於非法犯罪活動，而希沃斯則對此選擇視而不見。\n\n當真相曝光後，希沃斯選擇潛逃。但我認為他根本沒有離開城市，而是大隱隱於市，繼續進行非法活動。\n\n製作一個避難所中和器，讓整個塔札維許的人都能看到希沃斯的真面目。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n希沃斯避難所中和器"}
MultiLanguageQuestData['tw'][87354] = {title = "『離繫者』雷薩諾爾", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][87358] = {title = "晦影表象", objective = "已掃描18個影衛精華。", description = "要打造出完美的表象，關鍵在於用我提供的巧妙裝置掃描活體的影衛。這裝置能讓你複製他們存在核心的獨特精華，並將其儲存以供我們使用。\n\n你可以在正常空間與離繫空間中找到影衛。不管在哪，他們對陌生人可不友善，當然也不會樂意被掃描。", progress = nil, completion = "幹得漂亮！很少有人能帶著滿滿的掃描資料回來。", rewards = "您會收到：\n\n晦影表象"}
MultiLanguageQuestData['tw'][87363] = {title = "塔札維許表象", objective = "已掃描15個影衛精華。", description = "要製作出完美的塔札維許表象，你得使用我提供的裝置，掃描塔札維許周遭的活體影衛。\n\n這個裝置會標記目標，讓你得以複製他們存在核心的獨特精華，並儲存下來供我們使用。\n\n這可不是什麼輕鬆差事，你得親自接近他們，看他們是否願意被掃描！", progress = nil, completion = "塔札維許的犯罪份子可不喜歡被掃描。很少有人能帶著滿滿的掃描資料回來。", rewards = "您會收到：\n\n塔札維許表象"}
MultiLanguageQuestData['tw'][87374] = {title = "C.H.E.T.T.啟動", objective = "在內陸飯店二樓與C.H.E.T.T.交談，了解C.H.E.T.T.清單。", description = "<你瞥到一個黑影離你而去，而且發現你的背包稍微變重了。\n\n快速翻找一下，找到一張你不認得的卡片。\n\n其中一面只寫著「C.H.E.T.T.！」。另一面則是幽坑城的簡圖，附上前往內陸飯店二樓的指示。>", progress = nil, completion = "&lt;不確定你現在到底對這台神秘機器知道多少，你帶著嶄新的機會，繼續你的冒險旅程。&gt;", rewards = nil}
MultiLanguageQuestData['tw'][87376] = {title = "以太徽印", objective = "收集12份棄置的暗影令狀。", description = "以太徽印可讓你在不引起懷疑的情況下，自由存取並操控以太族資產。\n\n要取得真正的徽印非常困難。但我們可以用棄置的密文來偽造，這樣會簡單許多。\n\n如果你不介意弄髒手的話，去城外的垃圾堆翻找棄置的令狀。拿給我，我就能幫你製作徽印。", progress = "你找到那些暗影令狀了嗎？", completion = "喔，這些不錯。要做一枚徽印簡直易如反掌。", rewards = "您會收到：\n\n以太徽印"}
MultiLanguageQuestData['tw'][87380] = {title = "佐姬塔果", objective = "已收集8張離繫之皮", description = "這顆果子可以給你，但你得先幫我辦件事。\n\n有東西在暗中監視我們。你看不到，但這果子的氣味吸引了牠們。那是潛伏在我們視線之外的隱匿怪物。\n\n進入離繫空間，獵殺這些生物，把牠們的皮帶來給我。我需要證明牠們真的存在！", progress = "你看到牠們了嗎？你把牠們剁成碎片了嗎？", completion = "我就知道牠們真的存在，看看這些出色的獸皮！拿去吧，就如我承諾的，這顆果子歸你了。", rewards = "您會收到：\n\n佐姬塔果"}
MultiLanguageQuestData['tw'][87404] = {title = "能量封裝", objective = "已從力量收割者與轟雷無翼龍處收集10份能量。", description = "你需要能量封裝？那你肯定是打算用它啟動某個傳送門或傳送裝置！\n\n我可以輕鬆幫你製作，只要你提供足夠的能量。\n\n去附近的收割者那裡。他們會讓我們收集所需的能量，只要我們幫忙驅趕那些無翼龍。", progress = "你準備好所需的能量了嗎？", completion = "這是個簡單的任務，但我覺得非常值得。畢竟，能量是我們這裡所有作業的核心驅動力。", rewards = "您會收到：\n\n能量封裝"}
MultiLanguageQuestData['tw'][87405] = {title = "懸賞：格拉伯", objective = "收集一籃佐姬塔果、一打帷幕裂片，還有一些風味十足的廢料。", description = "城鎮東邊的物移沙地裡出現了一條巨大沙蟲。當地人給牠取了個名字叫「格拉伯」。\n\n可惜的是，佐威副官在前往調查時被這隻怪物拖進了沙裡，至今生死未卜。\n\n想個辦法把這條沙蟲引出來，這樣才能一舉殲滅牠。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n格拉伯誘餌"}
MultiLanguageQuestData['tw'][87406] = {title = "故障的巨大機械猩猩", objective = "帶著故障的巨大機械猩猩去找帝提‧引信小子進行修理。\n\n已提供物品：\n", description = "<雖然你盡了最大的努力，機械依舊紋絲不動。\n\n也許一名當地的專家能讓它恢復運作。>", progress = nil, completion = "是超強猩猩！你在哪裡找到這個的？\n\n故障？大概只是一些線路鬆動了。\n\n稍微給它搖一下…打開這個開關…現在它跟新的一樣了！", rewards = "您會收到：\n\n巨大機械猩猩"}
MultiLanguageQuestData['tw'][87408] = {title = "靈魂生物", objective = "在凱瑞西的離繫空間收集15個飛行者精華。", description = "我們在創造現有生物這方面已經達到完美，但我想再更進一步。我想利用沒能撐過吞盡之戰的生物來測試這套流程。\n\n這個世界曾有一種名為卡洛克的生物。找出牠的精華，幫我把它收集起來。", progress = "你收集到我需要的精華了嗎？", completion = "如果這能成功，那這將會是我這輩子的最高成就：讓滅絕物種重新現世。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87409] = {title = "死亡會帶來新生", objective = "協助維娜里用她的機器在綠洲製造生命。", description = "現在，我們要做的就是讓機器發揮作用了。\n\n這項殊榮就交給你了。要是失敗，我就怪到你頭上…\n\n…開玩笑的，朋友。大部分啦。", progress = nil, completion = "大成功…&lt;name&gt;，你知道這代表著什麼嗎？我們不再侷限於我們帶來的生物。只要我們可以找到離繫樣本，我們就可以重新製造凱瑞西的任何生物。牠們又可以重現於世了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87410] = {title = "打擊協商", objective = "在晦影城塞裡收集12個虛無防護零件。", description = "卡洛克體型龐大，牠們早晚都要展翅高飛。不如我們盡早計劃吧？\n\n影衛擁有各式各樣的虛無防護機制，我想你可以用平常的協商方法，從敵人那裡取得一些零件。完成之後，請把零件交給維娜里。", progress = "你拿到零件了嗎？", completion = "赫米特還真聰明。可以讓動物攜帶的虛無之盾是個很不錯的主意。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87411] = {title = "讓東西看起來硬梆梆", objective = "在綠洲外協助維娜里打造虛無之盾。", description = "我想我們可以打造出赫米特設想出的虛無之盾，但這些零件不太理想。到東邊的綠洲外和我會合，到時候我們再看看能不能製作出可行的方案。", progress = "來吧。我們開始建造吧。", completion = "儘管我仍然存疑，但看來我們有一面可以運作的攜帶式虛無之盾了。做得好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87413] = {title = "鳥浴", objective = "清理7隻囂張的卡洛克。", description = "<name>，你來得正好！卡洛克變得太髒，導致牠們的原生氣味被蓋掉了。這裡沒有足夠的水幫牠們洗澡！\n\n帶著這個靈魄真空。它可以直接把髒污吸下來，但你只需要清理地面上的卡洛克就好。試試看去北邊的岩石上找找！", progress = nil, completion = "啊，我已經能聞出風中的氣味改變了。非常感謝！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87414] = {title = "醫療手段", objective = "縮小並收集8個囂張的卡洛克。", description = "如果能好好幫卡洛克進行醫療檢查那就好了。\n\n你可以把牠們縮小，然後帶來給我嗎？", progress = nil, completion = "啊，這些就行了。十分感激。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87415] = {title = "凱瑞西的天空", objective = "帶著卡洛克在綠洲外飛行來測試護盾裝置。", description = "你協助製作的防護裝置經過測試了。抱歉我的措辭可能不夠精準，但它準備好展開首航了。\n\n和奧姆塔拉談談吧。他已經幫你選好一條可以讓卡洛克跟著飛行的路線了。", progress = nil, completion = "過了千年之後，成為第一個騎乘卡洛克的人的感覺怎麼樣？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][87417] = {title = "世界之魂：地城", objective = "在普通或更高難度下，通關任何賽季地城。", description = "卡茲阿爾加的敵人紛紛崛起，他們一同向那些不相信他們理念的人帶去痛苦。\n\n<法林停頓，然後快速瞄了一眼她面前的桌子，接著再將目光轉移回你身上。>\n\n讓這些人見識聖光吧，<name>。如果他們無法看清自己的錯誤，請讓他們的信仰有個慈悲的結束。", progress = nil, completion = "謝謝你讓卡茲阿爾加全體人民看到了希望的曙光。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n尖端儲物箱"}
MultiLanguageQuestData['tw'][87419] = {title = "世界之魂：探究", objective = "完成一次任意難度的地心之戰探究。", description = "這片土地上有許多深坑，讓我們的敵人以為躲在裡面就很安全。探索這些隱匿的區域，讓那些敵人永無寧日。", progress = nil, completion = "多虧有你的努力，這個世界的暗影又少了一些。", rewards = "您會收到：\n\n阿爾加冒險者的貯藏箱尖端儲物箱"}
MultiLanguageQuestData['tw'][87420] = {title = "一籃佐姬塔果", objective = "收集8顆剛摘下的佐姬塔果。", description = "你需要的佐姬塔果比我平常敢存放在這裡的量還要更多！\n\n一顆佐姬塔果就能讓我兄弟不敢靠近市集，你竟然想要一整籃？\n\n朋友啊，你可真大膽！\n\n去普萊姆斯秘境吧，我偷偷在那邊種了幾棵，藏得很好。拿著我的採收裝備，找到果子後想摘多少就摘多少。", progress = "你摘夠了嗎？", completion = "這麼多佐姬塔果！快點，把它們裝籃子帶走，免得那股味道把我們的客人都嚇跑！", rewards = "您會收到：\n\n一籃佐姬塔果"}
MultiLanguageQuestData['tw'][87422] = {title = "世界之魂：幽坑城世界任務", objective = "在幽坑城完成世界任務。", description = "或許我還不了解幽坑城，但他們的確需要幫助。我們的紛爭才讓他們有今日的處境，如果能讓他們邁出下一步也是件好事。\n\n去那裡幫幫他們。看看能不能讓這些…集團團結起來，和我們結盟。", progress = nil, completion = "你成功達成了一些…特殊的請求。大家不會忘記你對幽坑城的貢獻的。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n尖端儲物箱尖端儲物箱"}
MultiLanguageQuestData['tw'][87423] = {title = "世界之魂：幽坑城探險者", objective = "在幽坑城完成各種活動。", description = "幽坑城是由許多創新設計、努力、忠誠，和哥布林的堅強意志所構築而成。這些哥布林不躲在不見天日的洞穴裡，反而打造了一個活生生的城市。\n\n我們有好幾年沒有看到生面孔了，而他們也為我們的土地帶來了新生機。無論他們需要什麼，去幫助他們吧。", progress = nil, completion = "當巴雷達爾黯淡無光時，如果他們陷入我們的處境，他們又會打造出些什麼？\n\n你的努力真的很有幫助。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n尖端儲物箱"}
MultiLanguageQuestData['tw'][87424] = {title = "世界之魂：世界首領", objective = "擊敗地心之戰中開放的所有世界首領。", description = "被敵人侵擾的地方不只有聖落之地。\n\n難纏的怪物也威脅著我們的盟友。不論戰爭的陰影籠罩在哪裡，凶猛的野獸和狡猾的惡徒也會紛紛崛起。不管是阿拉希人、土靈或與我們並肩奮鬥的人，他們都殺。從無辜的農夫到優秀的戰士，無一倖免。\n\n聖焰在你心中燃燒。你是我們最大的希望，請去獵殺這些棘手的邪惡生物吧。", progress = nil, completion = "你的情況怎麼樣？有新受的傷，還是有新故事可以分享呢？", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n尖端儲物箱"}
MultiLanguageQuestData['tw'][87425] = {title = "大型黏滑虛無物質", objective = "收集5份腐化的樹液。", description = "啊，我知道你在說什麼了！\n\n那些腐化植物分泌的樹液含有虛無能量。你盡可能多收集些樹液，我會把它們混合成大型黏滑物質。", progress = "你找到樹液了嗎？", completion = "任何能剷除腐化植物的手段，對我們這裡的作業都有莫大幫助。", rewards = "您會收到：\n\n大型黏滑虛無苔蘚"}
MultiLanguageQuestData['tw'][87426] = {title = "風味十足的廢料", objective = "收集24份棄置廢料", description = "在這片沙地裡撿破爛可是能大賺一筆的，不過要當心那隻怪物。\n\n牠餓得發狂，我親眼看過牠把拾荒者拖進沙裡！\n\n你可以用食物誘牠現身，我有次丟些廢料就餵到牠了。\n\n你得收集最香的垃圾才能把牠騙出來。你先去收集，我幫你挑出風味最佳的廢料。", progress = "你有找到什麼美味的東西嗎？", completion = "我已經挑出最香的那幾塊，保證能引起那怪物的注意！", rewards = "您會收到：\n\n風味十足的廢料"}
MultiLanguageQuestData['tw'][87475] = {title = "蘇芮基入侵：防守城牆", objective = "協助聖焰輝光擊退米雷達爾外的蘇芮基。", description = "聖焰在上！那些可惡的甲殼害蟲非常冷血！\n\n我們收到奧拉麗亞‧鐵擊的報告，有一小群奈幽蟲族正在騷擾城市的外圍區域。\n\n前往米雷達爾的外圍，與我們的盟友會合並一同戰鬥。", progress = nil, completion = "辛苦了，&lt;name&gt;。剩下的就交給我們的援軍來處理。\n\n麥爾頓的報告指出，崇敬之地西邊有更龐大的勢力，所以我們必須保持警惕，守住城牆。\n\n願聖焰能引導你的利劍。", rewards = "您會收到：\n\n共鳴水晶陳舊幽坑城紋章聖焰輝光聖焰輝光"}
MultiLanguageQuestData['tw'][87477] = {title = "蘇芮基入侵：南方蟲群", objective = "協助聖焰輝光擊退聖落之地南部的蘇芮基蟲群。", description = "這些蘇芮基不會輕易放棄進攻。\n\n南部陣地送來報告，提醒我們留意沿著山脈進行騷擾的一小批蟲群。\n\n我不清楚他們是打算攻擊忒尼爾飛船港或巴雷達爾的恩惠，但我們不能任憑他們先出招。\n\n與我們的盟友一起攔截那群奈幽蟲族！", progress = nil, completion = "&lt;name&gt;，法林小姐對你的看法是對的。我們欠你一個人情。\n\n你為忒尼爾飛船港和巴雷達爾的恩惠爭取到了寶貴的時間。\n\n剩下的就交給我們處理。", rewards = "您會收到：\n\n共鳴水晶陳舊幽坑城紋章聖焰輝光聖焰輝光"}
MultiLanguageQuestData['tw'][87480] = {title = "蘇芮基入侵：東部攻勢", objective = "協助聖焰輝光，阻止蘇芮基在東部的攻擊行動。", description = "<name>，沒有時間休息了！\n\n我們位在聖落之地東部的土靈盟友發現了一個準備要攻打頓內爾的恩典的蘇芮基軍團。他們一定是鎖定了黎明塔！\n\n在我們說話的同時，聖焰輝光的援軍正在鞏固城鎮和洛薩臺地的防禦。\n\n前往東方提供一切協助吧！", progress = nil, completion = "&lt;name&gt;，頓內爾的恩典的人民十分感謝你。\n\n我們會持續與土靈盟友守住洛薩臺地，並強化下方城鎮的防禦。\n\n願聖焰的光芒與你同在，朋友。", rewards = "您會收到：\n\n共鳴水晶陳舊幽坑城紋章聖焰輝光聖焰輝光"}
MultiLanguageQuestData['tw'][87496] = {title = "有利的包裹", objective = "在幽坑城拜訪每個集團的軍需官。", description = "這段日子很難過，所以各個集團都在施行「保留僱員」的新商業策略。我以前是沒聽過，但聽起來很酷。\n\n總之，我很確定那個意思是，只要工作夠久，員工就可以在公司商店買東西。\n\n去看看那些集團都賣些什麼吧。在你開始上工之前，先看看有沒有什麼是你喜歡的。", progress = nil, completion = "他們的東西都很不錯，對吧？\n\n如果你需要幫忙找到他們，就跟我說一聲。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][87546] = {title = "懸賞：紫色泥媒", objective = "結合大型黏滑虛無物質、能量封裝和離繫電池，打造一把解鎖靜滯球體的鑰匙。", description = "在修復秘境時，我們移除了大量受污染的植物，讓土地得以逐漸恢復。\n\n但有一個腐化的鞭笞者趁我們不注意時逃掉了。秘境技師給牠取了個名字叫「紫色泥媒」，牠的根系與種子正在普萊姆斯秘境裡不斷擴張。\n\n那株植物躲藏在秘境外的一個老舊靜止牢籠裡。你需要製造一個裝置來解除保護，才能讓牠現身並將其根除。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n紫色泥媒牢籠鑰匙"}
MultiLanguageQuestData['tw'][87548] = {title = "一打帷幕裂片", objective = "收集12顆遭竊的帷幕裂片", description = "我當然知道帷幕裂片，那是極受重視的寶物，經常成為小偷的目標！但放心，像本人奧姆斯托這樣的正直市民，絕不會參與這種罪行。\n\n你想找到帷幕裂片，只需要追蹤這城市裡的老鼠，那些傢伙是最狡猾的小偷！\n\n跟隨一隻行竊的奔走者回到牠的巢穴，你一定會在牠的寶藏中發現幾顆帷幕裂片。帶回來後，我會幫你湊成一打包起來。", progress = "你有跟上那些老鼠嗎？", completion = "看來這些城市老鼠對你不構成威脅。這一打的裂片剛好可以組成一個漂亮的形狀，我幫你打包好！", rewards = "您會收到：\n\n一打帷幕裂片"}
MultiLanguageQuestData['tw'][87550] = {title = "第2週：我們真的紅了", objective = "贏得一場殘虐雙煞對戰，然後與威尼‧斯威茲交談。", description = "這是殘虐雙煞的第二週！殘暴加倍，樂趣也加倍！本週獲勝之後還能獲得更多獎勵！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n殘虐獎金"}
MultiLanguageQuestData['tw'][87551] = {title = "第3週：幫忙宣傳", objective = "在對戰期間放置你的殘虐旌旗，然後贏得對戰。", description = "嘿，你想幫上組織的忙嗎？你知道的，幫忙宣傳？下次進行對戰時，把你的殘虐旌旗丟入場中。表示支持！\n\n但是要小心一點，你的對手可能會被激怒，跟你不死不休…您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n勝者的領獎台，高分\n\n您還會收到：\n\n殘虐獎金"}
MultiLanguageQuestData['tw'][87552] = {title = "第4週：聲名鵲起", objective = "贏得一場殘虐雙煞對戰，然後與威尼‧斯威茲交談。", description = "你越來越有名了，<race>。繼續連勝下去，我一定能賣票賣到手軟。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n獲得測量值：平均物品等級\n\n您還會收到：\n\n殘虐獎金"}
MultiLanguageQuestData['tw'][87553] = {title = "第5週：又是精采的一週！", objective = "贏得一場殘虐雙煞對戰，然後與威尼‧斯威茲交談。", description = "<威尼正忙著數錢>\n\n什麼？喔，嘿，<name>。你是來幫忙吸引客人…我是說…來參加對戰嗎？好極了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n殘虐獎金"}
MultiLanguageQuestData['tw'][87554] = {title = "第6週：最後一戰！", objective = "贏得一場殘虐雙煞對戰，然後與威尼‧斯威茲交談。", description = "到此為止，活動即將結束。我們在眾人的歡呼中登場吧！\n\n做個完美的結束，我們就能一起數錢了！您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n殘虐獎金"}
MultiLanguageQuestData['tw'][87569] = {title = "法定的休息時間", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][87581] = {title = "不用再走路了", objective = "到「運送和搬運」的三樓找塔魯菈奶奶。", description = "我們得做些什麼，提高你的移動效率。幸好，我有適合的人選。去「運送和搬運」見塔魯菈奶奶，看看她能不能借你車子。", progress = nil, completion = "你需要一輛車？我們當然可以幫你弄一輛車來！我們有好多車！來，我這裡甚至就有一些備用鑰匙！", rewards = "這個任務線能解鎖：\n\n斷頸者G-99\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][87582] = {title = "探究：瘋狂挖掘場", objective = "在任一難度下完成9號挖掘場探究。", description = "嘿，夥伴。排水溝營地南方發生了怪事。\n\n我有些朋友失蹤了，而他們的家人都很擔心。你可以幫個忙到下面，看看發生什麼事了嗎？\n\n<帕克斯抓了抓下巴後看著你。>\n\n我也會好好補償你的。我跟你保證。", progress = nil, completion = "嘿，我很感激你到下面把問題解決了。\n\n雖然朋友這件事是騙你的，但你也有拿到報酬，不是嗎？", rewards = "您會收到：\n\n勇氣石共鳴水晶幽坑城集團"}
MultiLanguageQuestData['tw'][87583] = {title = "探究：水閘裡才有好料", objective = "在任一難度下完成後街水閘探究。", description = "我的好夥伴<class>，暗融霸佔了幽坑城的下水道。他們為了錢財壓榨努力工作的哥布林，偷他們的午餐，有時候還會摧毀他們的紅鶴草坪裝飾！\n\n我告訴你，那些暗融真的很不守規矩。\n\n我相信你一定會做對的事，然後幫助我們，特別是在聽了這個如此催淚的故事後。", progress = nil, completion = "嘿，老兄。感謝你讓幽坑城的所有紅鶴都能好好過日子了。\n\n你是真英雄。", rewards = "您會收到：\n\n勇氣石共鳴水晶幽坑城集團"}
MultiLanguageQuestData['tw'][87588] = {title = "壓爆垃圾", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][87597] = {title = "一袋帷幕裂片", objective = "收集18顆奧姆斯托的帷幕裂片", description = "我原本也能賣你帷幕裂片，但我自己的存貨也被偷走了。這城市的老鼠根本毫不猶豫，只要我一轉身就動手。\n\n只要你跟著任何一隻行竊的奔走者回巢穴，一定能找到一些被偷走的裂片。\n\n我會提供你一個裝置，用來追蹤那些偷竊的害獸。請找回足夠的帷幕裂片，滿足你我的需求。", progress = "你找到那些帷幕裂片了嗎？", completion = "啊，我就知道你能辦到！正直市民奧姆斯托開始覺得你可能會對我的生意非常有幫助了。", rewards = "您會收到：\n\n一袋帷幕裂片"}
MultiLanguageQuestData['tw'][88652] = {title = "死敵無面者面具", objective = "把死敵無面者面具放回恐怖幻象裡的祭壇。", description = "總是會有一些敵人，你會一再與他們開戰或發生衝突。即使擊敗他們，他們也會一再捲土重來，不斷攻擊你。這就是真正的死敵。而且不管你做什麼，這種敵人會永遠糾纏著你。", progress = "把死敵無面者面具放上祭壇。", completion = "認清你的死敵是徹底擊敗他們的第一步。然而，如果他們找不到捲土重來的辦法，無法一再挑戰你，那就稱不上死敵。", rewards = nil}
MultiLanguageQuestData['tw'][88656] = {title = "舒適的石頭", objective = "從扭曲的大地之靈、暴怒的粉碎者或破碎的奔行者身上收集20個光滑的石頭。", description = "那就開始吧。我們需要收集讓蛇能在凱瑞西舒適地生活的材料。我們來為牠們鋪個休憩點吧。\n\n其中一個很重要的東西就是石頭！蛇可以在上頭曬太陽，或是躲在下面。\n\n附近的土元素給我們帶來不少麻煩。看看你能不能從它們身上取得一些石塊。", progress = "能幫這些小動物，而不是殘害牠們，實在是太好了。\n\n生氣的元素生物不算啦！", completion = "這些就夠用了。幹得好。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88657] = {title = "贊格苔蘚", objective = "在贊格沼澤收集15份沼澤苔蘚。", description = "接下來，我們需要苔蘚。接下來要說的你可能不喜歡，但我們得進到黏糊糊的沼澤找。\n\n納迦控制了那個地方。苔蘚就長在蘑菇樹上。他們也很喜歡啃那些苔蘚或是有怪味道的東西。\n\n前往贊格沼澤最快的方法就是穿過北方的隘口。如果是我的話，我會在暗羽陸地那邊尋找。", progress = "你找到多少了？在我們回到凱瑞西之前，這是最後一項任務了。", completion = "很高興你這麼快就回來，而且還毫髮無傷。我和老費茲差點就快擋不住這些發狂的塔巴克了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88658] = {title = "「嘶嘶」入扣", objective = "收集10隻納葛蘭毒蛇和20株芳香的譽夢草。", description = "當然了，我們還需要蛇。這也是我們來這裡最主要的原因。\n\n你可以在南邊的泰拉蕊盆地找到一些比較小隻的。在牠們的巢穴附近製造一點騷動，牠們就會自己跑出來了。牠們喜歡的植物都長在那邊。\n\n說到植物，別忘了摘一些附近的香草植物。以防你不知道，蛇的嗅覺其實很敏銳。", progress = "你找到多少了？我也看不出來。你的袋子每次都是滿的。", completion = "當我們把蛇帶到凱瑞西時，得確保牠們能獲得最舒適的環境。\n\n哎呀。那些植物的香味。真的很香！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88660] = {title = "飛機上有蛇", objective = "在奈辛瓦里狩旅團的墜機殘骸中找出兩條蛇。", description = "最後一個，也是最重要的事，我們得把我飛機上的兩條蛇抓出來！\n\n我不知道蛇一般都活多久，但那兩條蛇好像不會死一樣。而且每次我靠近，牠們都會用嘲笑的眼神看我。\n\n你可以幫我把牠們找出來嗎？", progress = nil, completion = "太好了！我會通知維娜里，這樣我們就可以用她天殺的傳送門離開了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88661] = {title = "前往中庭", objective = "到凱瑞西的中庭和赫米特‧奈辛瓦里會合。", description = "我們需要的都找到了。該回去了。\n\n在把蛇帶到綠洲的生態系之前，我們得先進行測試。凱瑞西有幾個名叫秘境的地方。\n\n維娜里的傳送門會送我們到中庭那邊。但我還是比較想要搭我的飛機去。", progress = nil, completion = "現在真正的麻煩事才剛要開始。\n\n如果蛇無法適應凱瑞西，我們得確保牠們能安全回到納葛蘭。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88662] = {title = "名字有什麼意思嗎？", objective = "為母蛇和公蛇命名。", description = "雖然墜機殘骸中的兩條蛇不喜歡我，但牠們好像跟你很合得來。\n\n你想幫牠們取名嗎？", progress = "你決定好了嗎？", completion = "兩條蛇的名字都取得很好！麵麵女士和抱抱先生，我很喜歡！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88663] = {title = "爬蟲測量", objective = "與資料收集無人機對話，完成兩條蛇的資料分析。", description = "現在要來測一下生命徵象了。維娜里和她的手下為了辦事，什麼工具都有。\n\n這個小機器人就是用來測量蛇的。你準備好之後就跟它說吧。\n\n你去做別的事情的時候，我可以收集剩下的蛇的資料。", progress = nil, completion = "等等…帶卵？麵麵女士懷孕了？\n\n我們要有蛇寶寶了！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88664] = {title = "納葛蘭育植", objective = "種植6株芬芳的譽夢草。", description = "還記得你在納葛蘭收集的臭臭植物嗎？你可以重新種植嗎？\n\n不用現在就種。只要量夠來測試，讓它們適應凱瑞西的土壤就好。\n\n我們最後所需的植物一定會比這些還多。", progress = nil, completion = "欸，我在這裡還是聞得到。天啊！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88665] = {title = "跟隨氣味", objective = "把納葛蘭毒蛇引到普萊姆斯秘境裡。", description = "現在得往北進到普萊姆斯秘境裡了。還真繞口。\n\n拿著剩下的其中一朵臭花，把蛇都引到那邊去吧。", progress = nil, completion = "現在要進行下一輪測試了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88666] = {title = "苔蘚棲所", objective = "測試8個長滿苔蘚的毒蛇棲所。", description = "我已經把你在納葛蘭收集的石頭和苔蘚都放在一起了。現在就要來看蛇喜不喜歡了。\n\n我已經把棲所分散在秘境各處，這樣你就可以找出不一樣的地方了。\n\n你在測試的同時，我會做好準備，把牠們都送到綠洲。", progress = nil, completion = "好。我們會把牠們喜歡的棲所留下來，剩下的就來調整一下。\n\n做得好，&lt;name&gt;！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88667] = {title = "讓蛇喝水", objective = "用赫米特的澆水罐讓10隻乾巴巴的蛇喝水。", description = "噢，不！有些蛇出現適應不良的狀況了。牠們沒有喝足量的水，已經呈現缺水狀態了。\n\n快，<name>。拿著這個澆水罐，讓它們好好喝水。", progress = nil, completion = "謝謝你，&lt;name&gt;！我想我們該去洗個澡。你覺得這些秘境裡會下雨嗎？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88668] = {title = "爬蟲類移動計畫", objective = "對兩條命名的蛇使用維娜里的移動標記，並把牠們送往綠洲。", description = "我們的測試成功了！該移到綠洲了。\n\n維娜里給了我這些「移動」裝置，讓蛇可以快速到那邊去。\n\n你去送餘燼和靛青，剩下的不如交給我吧？自從我把牠們移到這裡之後，牠們就沒給我好臉色看過。", progress = nil, completion = "現在得讓蛇好好適應生態系。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88669] = {title = "築巢時間", objective = "為兩條命名的蛇搭好家。", description = "我們得為這兩條蛇好好打造一個家，而且餘燼也要產卵了。\n\n我已經先四處看過了，也發現這附近有一片樹蔭。\n\n如果要讓那個地方變得舒適安全，還有很多工作要做。再用一次維娜里的移動標記，來召喚你所需的一切材料吧。", progress = nil, completion = "牠們很喜歡嗎？那真是好消息！", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88670] = {title = "安撫毒蛇", objective = "用赫米特的的安撫之笛安撫15隻激動的毒蛇。", description = "多數的蛇不喜歡維娜里的傳送門。其他由奧姆塔拉複製出來的蛇也不喜歡。牠們都受到刺激，我也怕牠們把自己弄傷了。\n\n我這邊有支笛子。別說了。這該死的東西我根本就不會吹。\n\n你可以拿著笛子，吹一些靜心的音樂，讓蛇平靜下來嗎？", progress = nil, completion = "我們從這裡就聽得到你的音樂。你究竟還會多少東西？", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88671] = {title = "額外的蛋", objective = "收集6顆卡洛克蛋。", description = "我一直在跟其他人談論蛇的食物來源，我們也想出一個辦法了。\n\n卡洛克在綠洲的生態系裡似乎有點繁殖過剩了。如果你去拿一些牠們的蛋，應該就足以把蛇餵飽了。", progress = "偷蛋行動進行得怎麼樣了？", completion = "你怎麼搬得動全部的蛋啊？早知道我就給你更多的移動標記了。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][88672] = {title = "小蛇！", objective = "協助小蛇誕生。", description = "說到蛋，我發現餘燼已經把卵產下來了。我們很快就要有蛇寶寶了！\n\n到巢穴那邊等我，我們就可以一起迎接凱瑞西的第一波新生蛇了。", progress = nil, completion = "所有的蛇的適應狀況比我們預期的要好很多。這讓我對凱瑞西抱有更多希望了。\n\n你幹的可是件大事，&lt;name&gt;！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88711] = {title = "聖輝入侵：毒液與費洛蒙", objective = "協助聖焰輝光擾亂在狂野山谷的蘇芮基部隊。", description = "我們在阿茲-卡罕特的盟友幫忙找出一個攻擊蘇芮基的戰略位置。\n\n報告指出，我們的敵人正在收集毒液，以便用於他們的戰爭機器。\n\n讓我們善用這次機會，切斷他們的補給，說不定還能更加了解他們的鍊金術。", progress = nil, completion = "無論蘇芮基在收集著什麼，我們都要做好最壞的打算。\n\n或許我們的聖焰師能透過你找到的樣本，來製作一些解毒劑。\n\n我們會永遠感謝你的協助，朋友。聖焰輝光因為有你而燃燒得更明亮。", rewards = "您會收到：\n\n共鳴水晶陳舊幽坑城紋章聖焰輝光聖焰輝光"}
MultiLanguageQuestData['tw'][88774] = {title = "能量耗盡", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][88803] = {title = "及時協助", objective = "與沙漏互動，取得索芮朵蜜的協助。", description = "你好，勇士。\n\n我找到在幻象中進一步協助你的辦法了。你需要的話，可以利用這個沙漏請求我的協助。\n\n我會生成一具傀儡，在幻象中幫助你。", progress = nil, completion = "在任何幻象中都能請求支援。", rewards = nil}
MultiLanguageQuestData['tw'][88805] = {title = "穿越時光的創傷之路", objective = "完成5次時光漫遊地城冒險。", description = "過去的敵人回來了，以往的戰傷又再次被揭開了。\n\n擊敗那些敵人，再光榮地回來吧。", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][88808] = {title = "穿越時光的創傷旅程", objective = "完成5次時光漫遊地城冒險。", description = "艾澤拉斯需要幫助，勇士。在戰爭的摧殘下，她的傷口仍未復原。前往贊達拉和庫爾提拉斯，找出那些想讓她受傷的人吧。\n\n以她之名，擊敗敵人和保衛艾澤拉斯。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][88818] = {title = "虛無掃蕩者", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][88870] = {title = "污水企業聯合尊敬", objective = "到廢料工坊與羅可‧拉茲砰交談。", description = "到目前為止，你在污水企業幹得不錯。繼續好好表現吧。\n\n去找羅可‧拉茲砰談話，他會答謝你。", progress = nil, completion = "嘿，這是要給你的。", rewards = "您會收到：\n\n污水寶箱"}
MultiLanguageQuestData['tw'][88871] = {title = "污水企業聯合崇敬", objective = "到廢料工坊與羅可‧拉茲砰交談。", description = "到目前為止，你在污水企業幹得不錯。繼續好好表現吧。\n\n去找羅可‧拉茲砰談話，他會答謝你。", progress = nil, completion = "嘿，這是要給你的。", rewards = "您會收到：\n\n污水寶箱"}
MultiLanguageQuestData['tw'][88872] = {title = "污水企業聯合崇拜", objective = "到廢料工坊與羅可‧拉茲砰交談。", description = "你在污水企業幹得不錯。我們十分感謝。\n\n去找羅可‧拉茲砰談話，他會答謝你。", progress = nil, completion = "嘿，這是要給你的。", rewards = "您會收到：\n\n污水寶箱"}
MultiLanguageQuestData['tw'][88873] = {title = "熱砂企業尊敬", objective = "到熱砂實驗室與實驗室助理萊茲莉交談。", description = "熱砂企業想要感謝你的協助。\n\n請遵守所有安全程序，然後向實驗室助理萊茲莉領取獎勵。", progress = nil, completion = "我們有東西要給你。", rewards = "您會收到：\n\n熱砂寶箱"}
