MultiLanguageQuestData['tw'][88876] = {title = "黑水集團尊敬", objective = "到港務局與船務長哈蒂交談。", description = "有了你的協助，黑水集團現在一帆風順。\n\n船務長哈蒂已經備好你的劫掠分紅…也就是，感激你的貢獻的獎勵。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n黑水寶箱"}
MultiLanguageQuestData['tw'][88877] = {title = "黑水集團崇敬", objective = "到港務局與船務長哈蒂交談。", description = "有了你的協助，黑水集團現在一帆風順。\n\n船務長哈蒂已經備好你的劫掠分紅…也就是，感激你的貢獻的獎勵。", progress = nil, completion = "這是你的分紅，完全合法。", rewards = "您會收到：\n\n黑水寶箱"}
