MultiLanguageQuestData['tw'][89192] = {title = "努力工作", objective = "在綠洲外協助維娜里打造虛無之盾。", description = "我們的虛無之盾快用完了。還得麻煩你製作新的。\n\n到東邊的秘境外跟我會合。我們一起做。", progress = "來吧。我們開始吧。", completion = "你把正確的東西給我的能力還真是有幫助。你絕對不敢相信欠缺這項能力的人有多少。", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89194] = {title = "隨「蜂」搖擺", objective = "在綠洲為蜜蜂跳舞。", description = "<name>，正是我要找的<race>！我想請你給寶…我是說蜜蜂跳支舞。\n\n這件事就交給你了。", progress = nil, completion = "蜜蜂已經都知道植物的位置了，但多提醒一下也不是壞事。\n\n題外話，我很喜歡看你跳舞。", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89197] = {title = "魟魚牧場", objective = "套住6隻寧靜的死靈魟魚，並交給馬栓旁的奧姆塔拉。", description = "啊，你來了。我想幫死靈魟魚進行醫療檢查，我需要有人來幫忙抓牠們。也許你可以幫個忙？", progress = nil, completion = "謝謝你。對一個肢體較少的人來說，你的協調性確實比較好。", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89198] = {title = "乾洗服務", objective = "清理10隻囂張的卡洛克。", description = "真糟糕！卡洛克又暴躁起來了。\n\n可以幫牠們清乾淨，好讓牠們散發最自然的味道嗎？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][89209] = {title = "嗡嗡嗡", objective = "拾起10隻過勞的蜜蜂，並帶牠們回蜂巢。", description = "這些蜜蜂真是刻苦耐勞的工作能手…應該說工作蜂？我想這就是牠們叫工蜂的原因吧…啊，抱歉我分心了。\n\n有一些蜜蜂在外工作到累癱了。你可以把牠們送回蜂巢嗎？", progress = nil, completion = "你搞定了？那就別在這「嗡嗡」不休，快離開！\n\n這是諧音梗！很勉強的諧音梗！", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89210] = {title = "為照相而「蜂」狂", objective = "為女王蜂和15隻蜜蜂做紀錄。", description = "好了，<name>。帶著這台相機和這卷底片。就跟之前做的一樣。是時候進行記錄了！\n\n我知道你想好好放「蜂」，但這次得好好專心了。", progress = nil, completion = "真是美得令我甘拜下「蜂」。這張照片一定要保存起來！", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89212] = {title = "皇家攝影師", objective = "為10隻皇家刺尾做紀錄。", description = "<奧姆塔拉正專心地拍著幾張自己的照片。>\n\n啊！<name>！我們需要更新刺尾的紀錄。\n\n這台相機…我剛才只是在測試它的功能正不正常而已。請你去更新一下資料吧。", progress = nil, completion = "謝謝你幫忙更新。也許在給維娜里的報告中，我們可以省略之前發生的事？", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89213] = {title = "颯爽飛行", objective = "為7隻囂張的卡洛克做紀錄。", description = "我們需要用來記錄卡洛克的新照片。你在秘境裡的時候，請幫我們拍個幾張。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][89221] = {title = "在地美食", objective = "收集7份切碎的綠洲植物植株，接著放置3個植物拼盤。", description = "今天早上起床的時候，我想到：「<name>為看門蟲放的那盤拼盤看起來真是棒極了。如果<name>再去放一盤的話，我猜牠們一定很喜歡。」\n\n你何不讓這件事成真呢，嗯？", progress = "你餵飽看門蟲了嗎？", completion = "謝了，&lt;name&gt;。你真是個救「食」主。", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89222] = {title = "艾澤拉斯殘骸", objective = "把艾澤拉斯殘骸交給波拉勒斯的楚布羅。", description = "稍微看過一眼，這似乎是艾澤拉斯生命之血的結晶碎片。凝視碎片能看到熟悉的戰爭前線，還有困在戰鬥中的無數生命。你差點就被震耳欲聾的風暴和洶湧波濤的聲響給吞噬，但隨之又嘎然而止。\n\n庫爾提拉斯正呼喚著你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][89223] = {title = "艾澤拉斯殘骸", objective = "把艾澤拉斯殘骸交給達薩亞洛的楚布羅。", description = "稍微看過一眼，這似乎是艾澤拉斯生命之血的結晶碎片。凝視碎片能看到熟悉的戰爭前線，還有困在戰鬥中的無數生命。你差點就被震耳欲聾的風暴和洶湧波濤的聲響給吞噬，但隨之又戛然而止。\n\n贊達拉正呼喚著你。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n時光扭曲徽章時光扭曲徽章"}
MultiLanguageQuestData['tw'][89238] = {title = "持續觀察", objective = "縮小並收集8個囂張的卡洛克。", description = "如果想評估卡洛克的狀況，我們有許多醫學資料要分析。\n\n請拿著電容器圓盤來把牠們縮小，然後把牠們撿起來運送。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][89240] = {title = "夢裡叮個鈴個叮！", objective = "從皇家刺尾身上收集5個血液樣本。", description = "我們必須看看刺尾的情況如何。你可以幫我收集血液樣本嗎？\n\n跟之前一樣，用飛鏢麻醉牠們，再把帶有血液的飛鏢帶回來給我。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
