MultiLanguageQuestData['tw'][89242] = {title = "我要黃金黏液！", objective = "在綠洲清理25個凝結團塊。", description = "看來我們的管理員又在忙裡偷閒了。\n\n帶著真空裝置，把團塊都清乾淨。我會給你一部分的收入。", progress = nil, completion = "&lt;name&gt;，你從不讓人失望。大部分時候啦。按照約定，這是你的分成。", rewards = "您會收到：\n\n勇氣石陳舊以太紋章"}
MultiLanguageQuestData['tw'][89250] = {title = "燒胎", objective = "與墨伯交談來調整你的斷頸者G-99。", description = "沒有什麼比無拘無束地飆速更令人興奮的了，也沒有什麼比塔魯菈奶奶車庫裡的斷頸者G-99更能引人注目了。\n\n墨伯一定知道該如何以新部件來調整你的載具。>", progress = nil, completion = "準備好調整你的載具了嗎？", rewards = "您會收到：\n\n"}
