MultiLanguageQuestData['tw'][89490] = {title = "懸賞：秘法商人索澤爾", objective = "將一枚秘法符文符印與充能水晶和走私者的印記結合，打造出秘法誘餌，引出索澤爾。", description = "秘法商人索澤爾是塔札維許近期一連串竊案的幕後主使，造成大量魔法聖物、法杖，甚至數箱劇毒佐姬塔果失竊。\n\n線人指出，只要展示一件珍稀的秘法聖物，索澤爾可能就會現身。\n\n製作一件足以誘惑這名罪犯現身的物品。您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n秘法誘餌"}
MultiLanguageQuestData['tw'][89492] = {title = "世界之魂：鬥場中的殘虐雙煞！", objective = "在殘虐雙煞中獲勝，然後與威尼‧斯威茲交談。", description = "沒錯，殘虐雙煞要開始了！\n\n表達你的支持！與多恩諾加的希姬‧瑪芙對話，報名加入殘虐雙煞對戰。\n\n到那裡之後，等叫到你的時候就可以上場了！讓他們見識你的能耐吧，英雄！您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][89493] = {title = "歡迎來到戰場", objective = "歡迎你，學員！很高興看到你在這裡。\n\n現在正是上戰場的好時機。盡全力對抗蘇芮基。我們看好你。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n聖焰結界\n\n下列法術會施放在您身上：\n\n殘暴錘擊"}
MultiLanguageQuestData['tw'][89494] = {title = "授階典禮", objective = "<name>！很高興看到你升官。我想要正式恭喜你順利提升你的軍階。\n\n這次升官你當之無愧，在你持續為聖焰輝光效力的過程中，你展現出勇氣和極具潛力的特長。\n\n說到這個，請收下這件外袍，披上它繼續奮戰。期待能在戰場上看到你。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n神聖充能"}
MultiLanguageQuestData['tw'][89496] = {title = "聖焰防衛者", objective = "在我們與蘇芮基交戰的過程中，你成功證明了自己，<name>。\n\n你守護聖焰的勇氣和意願真令人欽佩，而你憑藉高超實力扭轉局勢的次數已經多到數不清。\n\n因此，我授予你這件外袍。請收下它，作為你不屈不撓的象徵和認可。", description = nil, progress = nil, completion = nil, rewards = "您會學到：\n\n神聖充能\n\n下列法術會施放在您身上：\n\n星光狀態"}
MultiLanguageQuestData['tw'][89501] = {title = "充能水晶", objective = "與瑪義‧庫會合，進入文庫襲擊探究，收集6份秘法能量樣本與一顆尚未充能的水晶。", description = "秘法充能水晶並非凱瑞西的原產物，但我們有方法可以自己製作！\n\n我認識一個小幫手，他能協助你收集並儲存秘法能量。將這股能量與一顆尚未充能的水晶帶回來，我們就能將它製作出充能水晶。\n\n請求瑪義‧庫的協助，經由以太傳送門前往蒼藍密庫，收集秘法能量與水晶。", progress = "你找到水晶與所需的能量了嗎？", completion = "瑪義‧庫已充滿秘法能量，足夠為水晶充能。", rewards = "您會收到：\n\n充能水晶"}
MultiLanguageQuestData['tw'][89502] = {title = "世界之魂：夜暮激戰", objective = "完成夜暮激戰事件。", description = "剩餘的蘇芮基部隊在聖落之地和阿茲-卡罕特到處肆虐，但我們認為他們正在崇敬之地西側集結兵力，以便直接進攻米雷達爾！\n\n請與聖焰輝光一起防守，消除蘇芮基帶來的威脅！", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][89505] = {title = "走私者的印記", objective = "在北蘇法德收集足夠的失物，裝滿奧姆斯托的背包。", description = "像本人奧姆斯托這樣正直的市民，怎麼可能擁有像走私者的印記這種違法物品呢？\n\n如果我真的剛好有…那我也只會給我欠過人情的人。\n\n如果你幫我個忙，那我就欠你一次了。\n\n前往北蘇法德，把我遺失在那裡的物品收集起來放進我的背包。完成後，我或許能提供你所需的東西。", progress = nil, completion = "如我承諾的，我會用這枚你需要的印記來還你這份人情。將它放在物品上，就等於向其他人表明該交易已獲得集團官員的批准。", rewards = "您會收到：\n\n走私者的印記"}
MultiLanguageQuestData['tw'][89514] = {title = "世界之魂：重返恐怖幻象", objective = "在重返恐怖幻象中擊敗5個首領。", description = "這種腐化奈幽蟲族的黑血非常棘手。\n\n我聽說這並不是上古之神第一次使用這東西。\n\n有個新訪客來到多恩諾加，是青銅龍索芮朵蜜，她找到辦法讓你重返過去的事件。\n\n快去找她，重溫這些恐怖幻象，盡可能收集情報。\n\n張大你的眼睛，<name>。你收集到的任何情報都一定能成為我們現在的助力。您會學到：\n\n", progress = nil, completion = nil, rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][89515] = {title = "聖焰輝光名人", objective = "到莫蓋恩之淚與拉思‧布朗梅特交談。", description = "你持續在戰場上激勵著我們，<name>。在這艱難的時刻，你的英雄之舉保衛了我們的人民，對此我們由衷感激。", progress = nil, completion = "希望你能一直為自己的貢獻感到驕傲，另外這是表示謝意的一點小禮物。", rewards = "您會收到：\n\n聖輝軍官儲藏箱"}
MultiLanguageQuestData['tw'][89561] = {title = "包起來", objective = "與哈辛姆談談你的瑞西纏帶。", description = "莎達尼絲跟我提過你的事，有能力前往離繫空間的凡人。你是怎麼辦到的？等等，讓我推測一下。\n\n一定是因為你當成披風戴在身上的那些纏帶。它們被瑞西緞帶改造過。自從吞盡之戰以來，我再也沒看過這種東西。非常好。很經典。\n\n你追求經典嗎？還是追求力量？我可以用現代的魔科技強化你的瑞西纏帶，方便你應付離繫空間的危險。", progress = nil, completion = "謝謝你，&lt;name&gt;。你在離繫空間的冒險能為我們的相位深潛者清出道路，回收一直流落到虛無的能量。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90081] = {title = "秘法符文符印", objective = "進入文庫襲擊探究並收集0枚蝕刻碎片。", description = "秘法符文符印是證明某件物品為蒼藍工匠真跡的重要標誌。當然，它也可以黏在任何東西上，讓一件跳蚤市場的小玩意搖身變成看似無價的藝術品。\n\n我可以幫你打造一枚這樣的符印，說不定還能賣個好價錢。你只要去蒼藍密庫替我收集需要的材料，我們就能製作這枚符印。\n\n幫我帶兩份材料來，我會留一份當作報酬，另一份就交給你。", progress = "你收集到那些材料了嗎？", completion = "太好了，這些材料已經足夠製作你需要的東西。", rewards = "您會收到：\n\n秘法符文符印"}
MultiLanguageQuestData['tw'][90122] = {title = "擊殺『扭曲者』希沃斯", objective = "擊殺『扭曲者』希沃斯。", description = "<使用希沃斯避難所中和器來揭露並擊殺『扭曲者』希沃斯。>", progress = "擊殺『扭曲者』希沃斯。", completion = "幹得好，我會為你擊殺這個懸賞目標發放報酬。", rewards = "您會收到：\n\n凱瑞西信託同盟凱瑞西信託同盟凱瑞西信託同盟以太之絲"}
MultiLanguageQuestData['tw'][90123] = {title = "擊殺幻空之毒", objective = "擊殺幻空之毒。", description = "<使用幻空之毒傳送門鑰匙來揭露並擊殺幻空之毒。>", progress = "擊殺幻空之毒。", completion = "幹得好，我會為你擊殺這個懸賞目標發放報酬。", rewards = "您會收到：\n\n凱瑞西信託同盟凱瑞西信託同盟凱瑞西信託同盟以太之絲"}
