MultiLanguageQuestData['tw'][90663] = {title = "偷回我們的東西", objective = "與希達斯交談，取回消失的進口商品。", description = "維娜里拉了許多贊助，好讓綠洲的復原工作能夠順利起步。塔札維許有不少商人慷慨解囊，不過有些人卻只想偷雞摸狗。\n\n不可信賴的進口商從碼頭偷走一大批靜滯封印的商品。我需要像你這樣有本事的人去找回貨物。", progress = "你取回我消失的商品了嗎？", completion = "我沒想到會這麼多！這裡面不全是我的進口商品吧？\n\n算了，還是很高興看到這些商品。這是我的一點小心意。", rewards = "您會收到：\n\n"}
