MultiLanguageQuestData['tw'][90701] = {title = "膽小的歡呼炸彈", objective = "找到一顆隱藏在殘虐道具裡的歡呼炸彈。在它爆炸之前敲打它。", description = "哥布林熱愛炸彈，這點我懂。但一定什麼東西都非得爆炸嗎？\n\n幫我個忙：當你進入下一場殘虐雙煞對戰時，在其中一棵木樹和盆栽道具裡找到歡呼炸彈。\n\n你找到炸彈後，搶在它「爆炸」之前…幫我敲它一下。別擔心，它們很膽小。", progress = nil, completion = "幹得好，&lt;name&gt;。你得讓那些炸彈知道誰才是老大，懂了嗎？", rewards = "您會收到：\n\n呼喚牛角萬用鑰匙"}
MultiLanguageQuestData['tw'][90705] = {title = "故事漫遊", objective = "在多恩諾加、暴風城或奧格瑪找到博學行者阿洲。", description = "你對你的世界的歷史感到好奇嗎？你想要了解更多嗎？\n\n博學行者阿洲正在到處旅行，收集艾澤拉斯與各個地方的重要事件和人物的故事。只要前往你的陣營主城和他碰面，他會很樂意和你分享一個過往的故事！\n\n也許不只一個故事。他很樂意和人交談！\n\n告訴他是助理賴利要你來的。", progress = nil, completion = "喔？賴利竟然開始送訪客到我這裡了？\n\n&lt;博學行者阿洲發出深沉又爽朗的笑聲。&gt;\n\n她當然會這麼做了！\n\n啊，不過她說得對。如果有什麼比收集故事還令我熱愛的，那一定就是說故事了！坐下來，讓我和你分享一個故事。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90719] = {title = "借用腐化", objective = "前往恐怖幻象的腐化和失落區域，在首領身上尋找黑血殘留物和錯置的腐化紀念物。", description = "冒險者，我有了驚人的發現。\n\n分析當時的記憶之後，我發現我應該可以重現出在過去被使用的腐化效果。不過是以更容易控制的方式。\n\n我需要你擊敗地圖上腐化或失落區域中的首領，收集黑血殘留物以及一些錯置的腐化紀念物。", progress = "你成功了嗎？", completion = "很好，只要把這個殘留物和錯置的腐化紀念物結合在一起，我就可以…沒錯，就像這樣…然後再加入一點我的青銅龍魔法…好了。完成了。\n\n現在我已經掌握了實際經驗，只要你帶來更多錯置的腐化紀念物，我就可以製作出更多。我會試試能不能進一步改善這個過程。請之後再來找我。", rewards = "您能選擇下列奬勵中的一個：\n\n次級暮光破滅符文次級虛無反響符文次級無垠諸星符文次級濺血重創符文次級扭曲肢體符文次級虛無儀式符文\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][90729] = {title = "雙贏", objective = "販售6件暗影貿易囤貨。", description = "你昨天取回的東西並非全部都是我的，不過老實說，我們打算全都留下來！\n\n希達茲已經剝削人們好幾年了。該換到他承擔損失了。\n\n現在，我有一個雙贏的提案。你幫我賣掉一半的剩餘商品，剩下的就歸你所有！", progress = nil, completion = "你做得非常好！我應該更常雇用你！", rewards = "您會收到：\n\n暗影貿易進口"}
MultiLanguageQuestData['tw'][90731] = {title = "強化腐化", objective = "前往恐怖幻象的失落區域，在首領身上尋找黑血凝結物和錯置的腐化紀念物。", description = "冒險者，歡迎回來。我有了新的發現，但需要進行測試。\n\n我相信，隱藏在恐怖幻象失落區域中的，是一個稀有的黑血凝結物。這可能是強化腐化效果的關鍵…當然是以安全的方式。\n\n如果你可以進到這些區域並找到這個物品，然後帶回來更多錯置的腐化紀念物，我應該可以提高腐化效果的效力。", progress = "你成功了嗎？", completion = "好，看起來很有希望…凝結物的催化速度較慢，所以增加的腐化會更容易控制…很好，這樣就可以在沒有任何副作用的情況下，提高腐化物質的產量。\n\n可惜，我沒辦法讓它維持穩定太久。這些效果無法持續生效。我很抱歉，冒險者，不過我們應該把握時間好好利用這些效果。\n\n跟之前一樣，如果你帶給我更多錯置的腐化紀念物，我就能幫你製作更多這種強效的腐化。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90747] = {title = "錯誤的寶藍石背", objective = "與巴艾斯和其他人交談。", description = "我們可能出師不利，但有件事應該讓你知道。\n\n記得你用來搬運所有進口商品的那隻老石背嗎？我原本以為牠只是沒用的老傢伙，結果牠居然才是真正的寶貝。\n\n稀有的寶藍石背，價值連城！\n\n你可能會想知道牠去了哪裡，以及巴艾斯為什麼不急著分享利潤！", progress = nil, completion = "很好。這會是有利可圖的機會…對我而言。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90769] = {title = "屬於你的藍", objective = "收下你的獎勵。", description = "你為什麼想要這麼奇怪的野獸？\n\n我幫你留了很多更好的東西。要不要來些肥皂？\n\n不過，我會達成$p的心願。", progress = nil, completion = "願靈魂保護你，夥計，還有你的藍色新朋友！", rewards = "您會收到：\n\n藍色貝瑞"}
MultiLanguageQuestData['tw'][90770] = {title = "詐騙", objective = "進入離繫空間，取回格利夫塔要求的物品。", description = "有人說你想要那隻藍色的野獸。這真是一個非常划算的交易。這個市集果然到處都是機會。\n\n在寶藏源源不絕的地方還能找到更多交易。\n\n你知道在哪裡嗎？\n\n去這個特別的地方尋寶，我會把藍色的野獸給你。", progress = "你找到寶藏了嗎？", completion = "做得好，夥計。格利夫塔今天很開心。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90773] = {title = "肉品事業", objective = "收集12份暮背腰肉、5條沙翼魟尾和5顆俯擊者蛋。", description = "既然我幫了你，相信你一定不介意報答我。\n\n我對於新鮮、無污染的肉類一直有穩定的需求，卻不太容易弄到。綠洲是禁區，但是不是有野生動物漫遊在沙地中？\n\n這裡列出了我需要的東西。把那些東西帶給我，我就把你需要知道的事告訴你。", progress = "你收集到所有的肉了嗎？", completion = "就像我承諾過的。\n\n我把那隻藍色石背賣給像你一樣的外來者。不是什麼大英雄，更像是某個小角色。\n\n明天再來。他通常會來這裡用餐。而且他不光是聞味道，他還會吃！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90776] = {title = "遠古奇趣：戰鬥", objective = "使用並為布萊恩‧銅鬚裝備一件戰鬥古董。", description = "<你拿著古董，發現它正散發著微弱的光芒。這看起來很重要。探險者協會應該會感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90778] = {title = "遠古奇趣：通用", objective = "使用並為布萊恩‧銅鬚裝備一件通用古董。", description = "<你拿著古董，發現它正散發著微弱的光芒。這看起來很重要。探險者協會應該會感興趣。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90779] = {title = "破裂的鑰石", objective = "通關任何傳奇2以上難度的地城。", description = "當你觸摸石頭時，英勇事蹟的零碎畫面在你腦中一閃而過，但它們隨即便消失了。\n\n或許完成一個足夠令人敬佩的任務，可以讓石頭的魔法再次穩定下來？您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90781] = {title = "戰爭火花：凱瑞西", objective = "在戰爭模式下，於凱瑞西收集100個戰爭火花。", description = "謠傳凱瑞西的衝突正在升溫，去那裡詳細瞭解情況！", progress = "去把事情做個了結。", completion = "你這麼快就回來，讓我很驚訝，做得好。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n血腥代幣榮譽點數征服點數共鳴水晶"}
MultiLanguageQuestData['tw'][90938] = {title = "勇闖虛無", objective = "到佐戌瞰臺找哈辛姆。", description = "凡人，你知道離繫空間嗎？相信你認識遭遇過離繫空間的人。\n\n我們先前認為，只有能量生物，像是凱瑞西的那些人，才能進行相位深潛。自從先驅者回歸後，她利用瑞西纏帶，創造出讓實體生物變成能量的手段。\n\n我叫做哈辛姆，也正好擁有一些瑞西纏帶。我們現在急需足夠強大的冒險者，勇闖離繫空間深處淘金。", progress = nil, completion = "我可以提供你探索離繫空間所需的一切。", rewards = "您能選擇下列奬勵中的一個：\n\n賦能纖維時光纖維精準纖維靈巧纖維\n\n您還會收到：\n\n瑞西纏帶"}
MultiLanguageQuestData['tw'][90969] = {title = "泰坦控制臺", objective = "在超載探究中找到一個達格蘭的泰坦控制臺。", description = "冒險者，這些謠傳是真的。我親眼見過泰坦的手下，而它們都不是好惹的。我們必須找出它們現在出現的原因，並阻止它們造成更多危害。\n\n面對並阻止這些變節的泰坦傀儡。為了協助你，我找到了一些泰坦控制臺。我早已在受影響的區域裡面完成設置。我可以用它們和你溝通。我在想，我們也可以利用它們來擊退那些泰坦勢力。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90970] = {title = "細數泰坦圓盤碎片", objective = "在探究中取得泰坦圓盤裂片並擊敗泰坦傀儡。", description = "我們得取得更多泰坦圓盤。深入探索這個區域，找到泰坦傀儡，並擊敗它們。你應該能找到一些圓盤裂片。這個控制臺可以進行復原來取得其中的資料。\n\n也別忘了找出藏寶庫。這些傀儡似乎在協助當地居民。部分的當地居民可能已經透過其他寶藏找到了額外的泰坦圓盤了。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][90972] = {title = "共同目標", objective = "與阿達魯斯交談。", description = "<name>！我聽說你來到凱瑞西了。很好。我需要幫忙。\n\n我的學徒雷歐娜一直在研究駕馭虛無之力的新方法。她找上了一位名叫阿達魯斯的惡魔獵人，想看看伊利達瑞的作法能否提供任何幫助。\n\n老實說，我不確定我能不能信任阿達魯斯。他不像…勤奮好學的那類人。和雷歐娜不一樣。\n\n雷歐娜只是打算在他掌控虛無的過程中從旁觀察，但她卻消失了。請把她找出來。去和阿達魯斯談談，他應該知道點什麼。", progress = nil, completion = "阿達魯斯派你來的？\n\n他真的對我的能力缺乏信心，居然還派人來監工。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91009] = {title = "耐用的情報儲存容器", objective = "完成一次探究，為裝置充能。", description = "冒險者，聽得見嗎？我發現了一個較小的泰坦裝置，名叫耐用的情報儲存容器，它剛好能裝在你的腰帶上。我推測這能使用較小的泰坦圓盤，讓你無論在何處都能獲得增益效果。\n\n但每一個裝置都得接電發動。如果你在探究期間製造夠多的麻煩，應該就會生成裝置能偵測到並收集的火花，並產生你一生都用不完的能量。", progress = nil, completion = "裝上裝置。沒錯！裝置已經啟動了。\n\n好…如果我啟動啟用程序的話…已經完成了。裡面已經有兩個圓盤了。選單中也會顯示帶有小型泰坦圓盤的區域。我想我可以改良裝置，但我需要時間。之後再來找我吧。", rewards = "您會收到：\n\n耐用的情報收集容器耐用的情報收集容器耐用的情報收集容器耐用的情報收集容器"}
MultiLanguageQuestData['tw'][91026] = {title = "為升級而收集", objective = "完成任何探究。", description = "哈囉？哈囉？你回來了！太好了！\n\n我正在研究泰坦控制臺，也從超載區域中收集了許多新的情報，包括發現的故障指令。這或許是它們意外表現的關鍵原因，但我需要花點時間來確定。\n\n返回探究，以便檢查故障指令的結果，我可以利用這項資訊升級你的腰帶！", progress = nil, completion = "來，沒錯…有了這項資訊，我就可以做一些最後的調整了。然後加上這個指令…\n\n啊！這樣應該就可以了。如果你把這個插入你耐用的情報儲存容器裡，就能更新裝置效果的…呃，強度了。", rewards = "您會收到：\n\n泰坦記憶卡"}
MultiLanguageQuestData['tw'][91030] = {title = "全新泰坦指令", objective = "完成任何探究。", description = "我的計算需要更多的資料。我這裡有另一張升級卡快要完成了，但我不確定它能不能順利整合。\n\n但如果你回到探究區域擊敗更多的敵人，我就能觀察它們的反應。根據它們的反應，我就能幫你的腰帶進行最後的升級。", progress = nil, completion = "嗯，跟我猜的一樣。沒錯…我只要對這個調整一下…完成了。\n\n好消息是，這個升級不會讓你的腰帶爆炸！我知道原本有很小的機率，但再也不會了。你的資料證明，我原本設定的能量有點太高了。所以…還好我有請你額外確認一下，對吧？", rewards = "您會收到：\n\n泰坦記憶卡"}
MultiLanguageQuestData['tw'][91031] = {title = "推展極限", objective = "通關任何探究。", description = "你上次離開後，應該很擔心腰帶升級真的會爆炸吧？我很抱歉。我有的時候就是會興奮過頭。\n\n我想我能讓你的腰帶釋放更多力量，至少多一些。而且也很安全啦！你的資料顯示，你進入了許多探究，也遇到了許多敵人。那就是關鍵，再一次回去，準備最後一次升級你的腰帶。", progress = nil, completion = "最後一次行動的資料為我提供了進行另一個升級所需的素材。但這是我們能幫腰帶進行的最後一個升級，再繼續下去就會發生嚴重的熔毀了。當然了，熔毀能讓我們了解到其設計的更多細節…\n\n老媽常說：「達格蘭！如果你要毀掉獨一無二的古老神器，那就毀掉你自己的。」所以這是最後一次升級了。\n\n這是最後一張升級卡。謝謝你的幫忙。希望我們未來有機會一起進行更多實驗！", rewards = "您會收到：\n\n泰坦記憶卡"}
MultiLanguageQuestData['tw'][91033] = {title = "監測傀儡", objective = "通關一個超載探究。", description = "歡迎回來，冒險者。我有個小小的請求。我需要你繼續監測這些泰坦傀儡。\n\n我們發現它們在艾澤拉斯各處移動，但我還不知道它們的最終目的或指示是什麼。或許你可以去收集一點情報，這樣我們就可以知道真相了。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][91035] = {title = "造物削弱", objective = "擊敗5個傀儡並通關一個超載探究。", description = "先前的結果顯示，傀儡的超載狀況有所削弱了。我們必須看看這是一次性的結果，還是削弱會持續下去…\n\n回到這些超載的區域裡，測試這些傀儡身上的能量，然後進行回報。完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][91039] = {title = "法林的要求", objective = "在多恩諾加與法林‧洛薩交談。", description = "<name>，\n\n嘉亞拉和達納斯已經到多恩諾加了。他們似乎對阿拉希高地的緊張情勢感到擔憂。聽起來蠻嚴重的。\n\n你可以來多恩諾加一趟嗎？我相信你可以解決這件事。\n\n法林您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91044] = {title = "虛無之飢", objective = "回到桑朵拉與博學者奧姆里克和雷歐娜會合。", description = "我已經盡我所能避免這個結果。如果你沒把他推進傳送門，失控的虛無能量早就把我們周圍的洞穴弄塌了。\n\n他很強大。某方面來說，我覺得那其實對他不利。\n\n回到桑朵拉找我。我必須向奧姆里克回報，讓他知道這裡發生的事。", progress = "我在這裡都能感覺到虛無能量的翻騰，<class>。出了什麼事？", completion = "我由衷希望阿達魯斯沒事，也希望他不要怪罪我們。刃多雷的敵人已經夠多了。\n\n我很高興雷歐娜能有所突破。不過沒有你的幫忙，她永遠無法成功。", rewards = "您會收到：\n\n共鳴水晶勇氣石凱瑞西信託同盟"}
MultiLanguageQuestData['tw'][91052] = {title = "世界之魂：超載探究", objective = "完成一次任意難度的地心之戰超載探究。", description = "有東西讓敵對泰坦傀儡啟動，並進到卡茲阿爾加各處的多個洞穴之中了。探索和調查這些區域，並掃除任何威脅。", progress = nil, completion = "還不清楚是什麼東西迫使這些敵對泰坦傀儡來到地表上，實在令人不安。幸好有你的努力，這個威脅才總算解除了。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][91089] = {title = "擊敗奇維扎", objective = "提高你的物品等級，在凱瑞西的級別8探究中挑戰奇維扎。", description = "所以她是來領賞金的嗎？\n\n沒有人告訴她試圖殺掉艾澤拉斯的勇士很不禮貌嗎？更別說是銅鬚家的成員？", progress = nil, completion = "呼！太驚險了。\n\n我真的無法忍受在那裡四處潛行和傳送。\n\n看來在這次血脈賁張的體驗之後，我該好好休息一下了。", rewards = "您會收到：\n\n以太勝利"}
MultiLanguageQuestData['tw'][91093] = {title = "不只是相位", objective = "在凱瑞西的離繫空間中進行相位深潛時完成活動。", description = "離繫空間對凱瑞西上的人們是個持續存在的危險。其中充滿了被放逐的靈魂、損壞的科技，還有各式各樣的怪物。\n\n幫助凱瑞西信託同盟，在離繫空間中擊敗我們的敵人。進入相位深潛時，你可以使用相位導體在凱瑞西的殘骸之間移動。", progress = nil, completion = "&lt;race&gt;，十分感謝你的協助。信託同盟委派你來幫助我們真是明智之舉。", rewards = "您會收到：\n\n共鳴水晶凱瑞西信託同盟離繫硬幣"}
MultiLanguageQuestData['tw'][91138] = {title = "我是創造者，亦是毀滅者", objective = "展現你對生與死的精通。", description = "如此渺小的東西。而且杜爾原先蘊藏的力量也一滴不剩。不過依然是價值無可估量的聖物。\n\n<class>，你知道嗎？對杜爾而言，光與暗都是更加宏大的真實不可分割的一部分。\n\n凡是擁有創造的力量，亦擁有毀滅的力量。奉行這項真理，你就能重新認識自己，重新認識犧牲自己讓整個星球不至於毀滅的偉大那魯。", progress = nil, completion = "啊，沒錯。我感覺到你內在的變化。成長一方面來自於給予死亡，另一方面來自於培育生命。\n\n也許這個小東西可以當作紀念，讓人回想起杜爾，以及他在迪曼修斯最終命運中扮演的角色。", rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][91140] = {title = "過去的碎片", objective = "向塔札維許的奧姆恩出示碎片。", description = "<這枚結晶碎片已經失去了它原有的光輝。如今終於擺脫迪曼修斯恐怖的軀體，來到虔誠者的手中，在其深處，微光一閃而逝。\n\n也許塔札維許有人會知道更多。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
MultiLanguageQuestData['tw'][91142] = {title = "信託同盟外袍", objective = "又完成了一個任務。信託同盟感謝你的貢獻。創辦者成立了一個基金，專門鼓勵這類行為。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n聯合會外袍"}
MultiLanguageQuestData['tw'][91143] = {title = "雕刻紋章", objective = "又完成了一個任務。信託同盟感謝你的貢獻。創辦者成立了一個基金，專門鼓勵這類行為。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n雕刻以太紋章"}
MultiLanguageQuestData['tw'][91173] = {title = "聖焰不滅", objective = "完成夜暮激戰事件。", description = "這些蘇芮基真的是死纏爛打！我們只能用刀劍還以顏色。\n\n在接下來的戰鬥中，你還會繼續支援我們嗎？", progress = nil, completion = "你為我們爭取到片刻安寧。\n\n好好休息，但記得讓你的武器保持鋒利。", rewards = "您會收到：\n\n聖輝貢獻背袋勇氣石雕刻幽坑城紋章聖焰輝光聖焰輝光"}
MultiLanguageQuestData['tw'][91193] = {title = "特殊任務：頂點天賦1 - 解鎖", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][91203] = {title = "特殊任務：頂點天賦2 - 解鎖", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['tw'][91205] = {title = "究極至尊豪華渦輪加速：強力挑戰", objective = "在尋求團隊或更高難度的解放幽坑城團隊副本中擊敗任意四名首領，或是通關任意四個傳奇地城。", description = "<幽坑城有麻煩了。我們需要一個穩定的團隊，或是一些夠強的人也可以，為我們在幽坑城的朋友提供幫助。只要幫忙剷除一些難纏的競爭對手，我們保證不會讓你們白忙一場。\n\n完成任務，並從多恩諾加寶庫外的顧問瑞斯雷處取得特殊獎勵。此為期間限定提案。適用部分限制條件。>", progress = nil, completion = "謝了，朋友。幽坑城現在是一團亂。我們需要任何能取得的幫助。\n\n嘿，約定就是約定。這是我們欠你的。\n\n我們把這稱為初次幫忙的頭獎獎勵。別忘了回來完成更多工作！", rewards = "您會收到：\n\n謎樣集團代幣"}
MultiLanguageQuestData['tw'][91314] = {title = "離繫潛能", objective = "在離繫空間收集5份相位變異精華。", description = "<class>，聽說你探索過離繫空間？那裡充滿了純淨的虛無能量。我很想親自研究，但上次進去的人已被虛無吞噬。\n\n我需要你的幫忙來進行研究。虛無之痕山洞裡有些相位迷失的生物，我想分析它們的精華。如果你能幫我收集，我會非常感激。\n\n小心行事。", progress = "你成功取得那些相位變異精華了嗎？", completion = "這些資料對我研究離繫空間的進展幫助極大。謝謝你。\n\n我無法想像，我們能揭開多少關於凱瑞西的驚人發現。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91413] = {title = "暮光誓言之末", objective = "將暮光誓言印記帶去凱瑞西的綠洲給維娜里。\n\n已提供物品：\n", description = "<書頁上的古老符文在你的凝視下扭曲，其力量似乎正在快速消散。>\n\n<維娜里會對這個感興趣。>您會收到：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n皇家虛無之翼韁繩"}
MultiLanguageQuestData['tw'][91420] = {title = "以物易物", objective = "將你的發現交給塔札維許的奧姆米烏茲。\n\n已提供物品：\n", description = "<神秘的礦物在你手中發出低鳴。塔札維許應該有人知道它有什麼用。在帷幕市集到處尋找感興趣的人。>", progress = nil, completion = "&lt;奧姆米烏茲仔細查看礦石。&gt;\n\n你找到的這個石頭相當有意思。我想進一步檢查它，以及你發現的其他石頭。你願意交換嗎？\n\n如果你在帷幕市集遇到奧商集團的其他成員，他們或許也願意交換商品。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91451] = {title = "草莖市場", objective = "將你的發現交給塔札維許的奧姆米特。\n\n已提供物品：\n", description = "<神秘的植物在你手中發出低鳴。塔札維許應該有人知道如何處理它。在帷幕市集到處尋找感興趣的人。>", progress = nil, completion = "&lt;奧姆米特將植物拿在手中賞玩。&gt;\n\n來自死寂的荒地、被虛無灌注的草莖？這對你根本毫無用處。事實上，就用它來跟我交換其他植物吧，它們會具備更…讓人熟悉的屬性。\n\n如果你在帷幕市集遇到奧商集團的其他成員，他們或許也願意交換商品。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91454] = {title = "相位迷失冒險者", objective = "將日記交給桑朵拉的研究員艾莎芮。", description = "這本日記沾滿黏液和唾液，裡面有先前的相位深潛者留下的部分內容。\n\n<第27天\n\n離繫空間比我預期的還要廣闊許多，這裡的怪物也比我在凱瑞西看到的強上許多。\n\n附近有一個我明天要探索的洞穴。裡面充滿相位變異精華。這可能有助於進一步了解這裡的生態。>\n\n研究員艾莎芮應該會對這個很感興趣。", progress = nil, completion = "&lt;艾莎芮隨機翻到日記的某一頁。&gt;\n\n這裡面記載很多有關離繫空間的事。我想要仔細閱讀一下。\n\n謝謝你幫助我進行研究。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91459] = {title = "法力熔爐歐美加：行走之影", objective = "在普通或更高難度的法力熔爐歐美加，擊敗奈薩斯王薩哈達爾。", description = "英雄，聽得見嗎？影衛有個移位裝置，用來把貨物送到他們的倉庫，也可以把你直接送到他們在法力熔爐下方的哨站。他們絕對不會料到有這樣的伏擊！\n\n當然了，這是有訣竅的。我們沒有憑證，無法使用他們的補給線…所以我們需要你幫忙解決這個難題。擊敗你能找到的最高階影衛成員，帶著身分證明回來，我們就能幫你打造一張進入前線的單程票。", progress = nil, completion = "&lt;name&gt;，這絕對符合高階的要件！在我施加魔法之後，移位裝置就能為我們所用。下一站，敵人的地盤！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91460] = {title = "法力熔爐歐美加：行走之影", objective = "在英雄或更高難度的法力熔爐歐美加，擊敗奈薩斯王薩哈達爾。", description = "英雄，聽得見嗎？影衛有個移位裝置，用來把貨物送到他們的倉庫，也可以把你直接送到他們在法力熔爐下方的哨站。他們絕對不會料到有這樣的伏擊！\n\n當然了，這是有訣竅的。我們沒有憑證，無法使用他們的補給線…所以我們需要你幫忙解決這個難題。擊敗你能找到的最高階影衛成員，帶著身分證明回來，我們就能幫你打造一張進入前線的單程票。", progress = nil, completion = "&lt;name&gt;，這絕對符合高階的要件！在我施加魔法之後，移位裝置就能為我們所用。下一站，敵人的地盤！", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91461] = {title = "法力熔爐歐美加：行走之影", objective = "在傳奇難度的法力熔爐歐美加，擊敗奈薩斯王薩哈達爾。", description = "英雄，聽得見嗎？影衛有個移位裝置，用來把貨物送到他們的倉庫，也可以把你直接送到他們在法力熔爐下方的哨站。他們絕對不會料到有這樣的伏擊！\n\n當然了，這是有訣竅的。我們沒有憑證，無法使用他們的補給線…所以我們需要你幫忙解決這個難題。擊敗你能找到的最高階影衛成員，帶著身分證明回來，我們就能幫你打造一張進入前線的單程票。您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91481] = {title = "快速虹吸器", objective = "到暗影點向佐洛波回報。", description = "目前為止都很順利！我們開發了一些科技，應該能在你進攻法力熔爐時派上用場。", progress = nil, completion = "佐洛波帶了一把新武器給你。用這個吸收法力熔爐的秘法輻射，利用他們的能量對付他們。", rewards = "您會學到：\n\n快速虹吸器"}
MultiLanguageQuestData['tw'][91483] = {title = "駭入大型主機", objective = "到暗影點向佐洛波回報。", description = "我們破壞者在駭入歐美加的安全系統方面取得極大進展。過來一趟，讓我跟你分享我們的發現。", progress = nil, completion = "法力熔爐裡有一些控制臺，用來維持設施內的能量流動順暢。我們破解了第一組控制臺的安全系統，讓你在對付盧米薩和縛魂者娜辛德里附近的敵人時能夠扭轉乾坤。你只能使用一台，但破壞它們應該能讓你在戰鬥中獲得優勢。祝你好運。", rewards = "您會學到：\n\n垃圾駭入I"}
MultiLanguageQuestData['tw'][91525] = {title = "獵殺首惡：盧米薩", objective = "在任何難度下，在法力熔爐歐美加擊敗盧米薩。", description = "我們的情報指出，法力熔爐中有一隻巨獸，專門生產賦予影衛形體的絲線。打倒牠，我們就能妨礙他們製造援軍。喔，巴丘索要你順便帶一些絲線回來，他或許能用它製作一些有用的東西。", progress = nil, completion = "它的品質簡單前所未見！我得馬上動工。現在，來談談你的報酬吧。", rewards = "您會學到：\n\n獵殺首惡：盧米薩\n\n您還會收到：\n\n織獸絲線"}
MultiLanguageQuestData['tw'][91539] = {title = "璀璨回音", objective = "將璀璨回音帶去世界之魂記憶，接著釋放它。", description = "<你的手中拿著一個小型的艾澤萊晶岩球體。其光芒穩定且明亮，但它發出的聲音悲戚而渴望。它輕輕地觸動了你。>您會收到：\n\n完成任務後，你將獲得：\n\n", progress = nil, completion = nil, rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91624] = {title = "星光火花", objective = "到多恩諾加與管理者庫勃交談。", description = "一道星光的幻象滲入你的腦海之中。\n\n管理者庫勃應該有更多關於星光碎片的資訊。", progress = nil, completion = "這是碎裂的星光火花。\n\n每一週，這些碎片會在你冒險的途中出現。它目前的狀態沒什麼用處，但只要把它和另一個碎片結合，就能賦予其力量。這類材料具有可塑性、耐用性，也是許多工匠眼中的珍品。\n\n結合兩個碎片就能製造出一種獨特的製作材料，能讓物品達到超越凡人可及的技術。。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91780] = {title = "以太探究", objective = "到多恩諾加找布萊恩‧銅鬚。", description = "<name>，在探究這方面還有很多事能做！\n\n到多恩諾加找我。有很多事要討論！", progress = nil, completion = "真高興見到你！我們有一大堆事要討論。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91781] = {title = "賽季提醒", objective = "在探究者的文件中了解探究第3賽季的資訊，接著再向里諾‧傑克森和芬利‧莫戈頓爵士購買補給品。", description = "我們又可以在探究中發掘更多東西了！\n\n讓我先幫你了解一下最新情況。\n\n在那之後，我需要你幫我解決一點小麻煩…", progress = nil, completion = "好了，該來處理我剛才提到的麻煩了。", rewards = "您會收到：\n\n"}
MultiLanguageQuestData['tw'][91782] = {title = "強制收回！", objective = "取回布萊恩丟失的裝備。", description = "<name>，我想你已經猜到我的麻煩是什麼了。\n\n我的衣服、工具，還有我的古董！所有東西，除了我的靴子和帽子，我可不會再讓這些離開我。\n\n全都被一些聲稱我的虛空倉庫拖欠款項的集團暴徒強制收回了。\n\n你願不願意幫老布萊恩擺脫這個困境？我確定你只要跟他們解釋一下這只是誤會，他們就會把我辛辛苦苦得來的裝備還回來了。\n\n至少把我的馬褲還來。", progress = "多恩諾加一直以來都是這樣微風陣陣的嗎？", completion = "我真不敢相信這全都是騙局。\n\n古董的事還真可惜，但至少你把我的馬褲找回來了！", rewards = "您會收到：\n\n探究者法力浮艇"}
MultiLanguageQuestData['tw'][91855] = {title = "世界之魂：凱瑞西世界任務", objective = "在凱瑞西完成世界任務。", description = "我現在知道，有人需要幫忙的地方，艾澤拉斯的英雄就會出現。凱瑞西是個奇怪又遙遠的地方，但那裡的盟友需要我們。\n\n去那裡助他們一臂之力。看看你能做些什麼，為以太族和仲介者尋得一線生機。", progress = nil, completion = "你是所有英雄的典範。謝謝你。", rewards = "您會學到：\n\n每週活動\n\n您還會收到：\n\n"}
MultiLanguageQuestData['tw'][92031] = {title = "認識破壞者", objective = "到暗影點向佐圖魯回報。", description = "<暗影點的法力熔爐破壞者迫不及待想看到影衛和他們的盟友被逐出法力熔爐歐美加。這可能是拜訪他們的好時機。>", progress = nil, completion = "英雄！你暴君剋星的名聲早已傳遍這裡。看看能不能在那份名單上多加一個名字。", rewards = nil}
MultiLanguageQuestData['tw'][92330] = {title = "勇氣石", objective = "又完成了一個任務。信託同盟感謝你的貢獻。創辦者成立了一個基金，專門鼓勵這類行為。", description = nil, progress = nil, completion = nil, rewards = "您會收到：\n\n勇氣石"}
